INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-vuong-quyen-phan-8', 'Trò Chơi Vương Quyền (Phần 8)', 'Game Of Thrones (Season 8)', 'https://phimimg.com/upload/vod/20240730-1/a758db8f7dd8192353b767a57c9e1920.jpg', 'https://phimimg.com/upload/vod/20240730-1/49f2dafb4fca2fa2755fc568fbd4757e.jpg', '<p>Game of Thrones - Trò Chơi Vương Quyền mùa thứ 8 là mùa cuối cùng của bộ phim truyền hình đình đám này. Những tưởng mùa phim này thì phe con người, hay ít ra là phương Bắc, sẽ đoàn kết chống lại Night King (Dạ Đế) nhưng Mẹ Rồng (Emilia Clarke) và Sansa Stark (Sophie Turner) lại lườm liếc nhau đến đau cả mắt.Nguyên nhân của hành động này đến từ việc người nhà Stark từng có thâm thù với Targaryen trong cuộc chiến tranh giành vương vị nhiều năm trước. Dân phương Bắc vốn đã ít tin người, huống gì là một nữ hoàng của kẻ địch năm xưa. Chưa kể, Jon Snow (Kit Harington) đã từ bỏ ngôi vị Vua phương Bắc (King of the North) chỉ để nhờ tới sự giúp đỡ.Game of Thrones phần cuối này không chỉ là cái kết cho toàn loạt phim mà còn quyết định xem ai sẽ là chủ nhân cuối cùng của Iron Throne (Ngôi Báu Sắt) hay liệu con người, với những mưu mô toan tính, có đáng sống trước sức mạnh của Bóng Trắng?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 25, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Peter Dinklage","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Emilia Clarke","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Sophie Turner","avatar":""},{"name":"Maisie Williams","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Alfie Allen","avatar":""},{"name":"John Bradley","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Isaac Hempstead Wright","avatar":""},{"name":"Gwendoline Christie","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Jerome Flynn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324374);
