INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-gia-cua-chua-ban-tay-diet-quy', 'Sứ Giả Của Chúa (Bàn Tay Diệt Quỷ)', 'The Divine Fury', 'https://phimimg.com/upload/vod/20260210-1/af9d542b0ba9f058d1b1164e78ee2f90.jpg', 'https://phimimg.com/upload/vod/20260210-1/ba30eb47bbf10fac751531c13f2bdd50.jpg', '<p>The Divine Fury kể về một nhà vô địch võ thuật tên Yong Hoo, anh phát hiện ra sức mạnh trừ tà ma ẩn giấu trong mình. Còn rất trẻ, Yong Hoo đã quay lưng lại với Chúa khi lời cầu nguyện tuyệt vọng của anh cho sự sống còn của cha anh không được đáp lại. Rồi một ngày nọ, chàng trai có một vết thương bí ẩn trên lòng bàn tay. Vết thương ấy mở dẫn đến cuộc gặp với một linh mục cấp cao để chống lại các thế lực xấu xa.…</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Park Seo-jun","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Woo Do-hwan","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Jung Ji-hoon","avatar":""},{"name":"Lee Seung-hee","avatar":""},{"name":"Sim Hee-seop","avatar":""},{"name":"Kim See-eun","avatar":""},{"name":"Kim Seon-min","avatar":""},{"name":"Jeong Eui-soon","avatar":""},{"name":"Kim Beom-soo","avatar":""},{"name":"Park Jae-hong","avatar":""},{"name":"Cha Si-won","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Seo Jeong-yeon","avatar":""},{"name":"Jo Eun-hyung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Divine Fury (2019)","Божий жнець","Božská zuřivost","驱魔使者","Божественный гнев",