INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-nhan-dac-cong', 'Tố Nhân Đặc Công', 'The Rookies', 'https://phimimg.com/upload/vod/20260212-1/d7cdeba696cae9d85cfefaed65f1a5b2.jpg', 'https://phimimg.com/upload/vod/20260212-1/41857cb62ee365b939d00abfa72b7aac.jpg', '<p>Triệu Phong, bậc thầy thể thao mạo hiểm (Vương Đại Lục đóng) tình cờ gia nhập vào một cuộc giao dịch phạm pháp quốc tế, vì vậy cần phải đi theo đặc công quốc tế (Comilla · Kiều Ốc Duy Cơ đóng) cùng nhau đến Budapest. Tại đây anh ta cùng hình cảnh &quot;vô dụng&quot; Miểu Miểu (Trương Dung Dung đóng), nhà khoa học &quot;nghiệp dư&quot; Đinh Sơn (Hứa Ngụy Châu đóng) và bác sĩ thất nghiệp LV (Lưu Mỹ Đồng đóng) hợp thành một tố nhân đặc công - đặc vụ nghiệp dư. Bốn đặc vụ &quot;Tiểu Bạch&quot; hợp tác với đặc công quốc tế cấp cao Comilla và những kẻ khủng bố đã mở ra một cuộc chiến đấu ly kì vui nhộn.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Darren Wang","avatar":""},{"name":"Sandrine Pinna","avatar":""},{"name":"Timmy Xu","avatar":""},{"name":"Liu Meitong","avatar":""},{"name":"Xiao Zhan","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"Bernadett Ostorházi","avatar":""},{"name":"David Rayden","avatar":""},{"name":"Björn Freiberg","avatar":""},{"name":"Temur Mamisashvili","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Lenox Lu","avatar":""},{"name":"Danny Chan Kwok-Kwan","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Pei Kuishan","avatar":""},{"name":"Qi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"nam