INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-da-mau', 'Cảnh Sát Da Màu', 'Black And Blue', 'https://phimimg.com/upload/vod/20260210-1/09e22efc430bb5c04618e0a1254055d0.jpg', 'https://phimimg.com/upload/vod/20260210-1/d86cef22e254369f452b08fbe7605420.jpg', '<p>Bộ phim xoay quanh một nữ cảnh sát (do Harris đóng) làm việc tại New Orleans chứng kiến nhóm cảnh sát thoái hóa giết chết một kẻ buôn lậu ma túy được máy ghi hình gắn trên mũ của cô ghi lại. Khi không thể giết cô để xóa dấu vết, bọn thoái hóa vu cho cô tội giết người và tìm mọi cách giết cô để phi tang chứng cứ trong khi bọn buôn lậu ma túy cũng săn đuổi cô để trả thù cho đồng bọn. Tyrese Gibson đóng vai một họa sĩ triển vọng giúp nhân vật của Harris ngăn chặn tội ác và phô bày sự thật.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Naomie Harris","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Nafessa Williams","avatar":""},{"name":"James Moses Black","avatar":""},{"name":"Carsyn Taylor","avatar":""},{"name":"Lucky Johnson","avatar":""},{"name":"Deneen Tyler","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Nelson Bonilla","avatar":""},{"name":"Frankie Smith","avatar":""},{"name":"John Charles II","avatar":""},{"name":"Oscar Gale","avatar":""},{"name":"Rhonda Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20