INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-dau-bep-cung-dinh', 'Tiểu Đầu Bếp Cung Đình', 'True Cooking Master Boy', 'https://phimimg.com/upload/vod/20260206-1/c3bba935878c2295050b92481546ebc5.jpg', 'https://phimimg.com/upload/vod/20260206-1/14bab6a43c5e6d678186d907ae80ca36.jpg', '<p>Vào thế kỷ 19 ở Trung Quốc, Lưu Mão Tinh, là người trẻ nhất trong lịch sử giành được danh hiệu Siêu đầu bếp. Sư phụ của cậu, Châu Du, khuyên cậu nên mở mang kiến thức, vì vậy cậu bắt đầu cuộc hành trình vòng quanh Trung Quốc cùng với hai người bạn, Tứ Lang và Mỹ Lệ. Trong quá khứ, mẹ của Mão, vì muốn mang hạnh phúc đến cho mọi người nên đã chiến đấu chống lại Hội Ẩm thực Ngầm. Sau khi trở về, cậu cũng hợp tác với Giải Lỗ và Lôi Ân để chiến đấu chống lại Hội Ẩm thực Ngầm, bảo vệ các Dụng cụ Nấu ăn Huyền thoại...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Yukiyo Fujii","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["厨神小当家","中华小当家","真 中华一番","Shin Chuuka Ichiban!","Shin Chūka Ichiban!","진 중화일미!","요리왕 비룡 더 마스터!","진・중화일번!","진 중화일번!","廚神小當家","True Cooking Master Boy","真・中華一番!"]', 1784690324374);
