INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-khong-trong-luc', 'Người không trọng lực', 'The Man Without Gravity', 'người không trọng lực the man without gravity elio germano michela cescon silvia d''amico elena cotta vincent scarito pietro pescara jennifer brokshi andrea pennacchi cristina donadio dieter-michael grohmann dominique lombardo francesco procopio salvio simeoli agnieszka jania balkis l''invraisemblable légèreté d''oscar der mann ohne gravitation ο άνθρωπος χωρίς βαρύτητα oscar, a gravitáció nélküli ember mannen uten tyngdekraft człowiek wolny od grawitacji omul fără gravitație человек без гравитации el hombre sin gravedad mannen som trotsade tyngdlagen yer cekimsiz adam người không trọng lực o homem sem gravidade l''uomo senza gravità', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oi-me-cua-con', 'Ôi Mẹ Của Con!', '¡Ay, mi madre!', 'https://phimimg.com/upload/vod/20260129-1/19d1621f83d5015e485e51f3f41d78be.jpg', 'https://phimimg.com/upload/vod/20260129-1/5babb883ab8b108fd87411033c8fe7ff.jpg', '<p>Khi người mẹ xa cách đã lâu của cô đột ngột qua đời, một phụ nữ phải tuân theo những hướng dẫn kỳ quặc được đưa ra trong di chúc để nhận một tài sản thừa kế quan trọng.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Secun de la Rosa","avatar":""},{"name":"Estefanía de los Santos","avatar":""},{"name":"Mariola Fuentes","avatar":""},{"name":"Marta Torné","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Terele Pávez","avatar":""},{"name":"María Alfonsa Rosso","avatar":""},{"name":"Concha Galán","avatar":""},{"name":"Alfonso Sánchez","avatar":""},{"name":"Fernando Huesca","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["¡Ay, mi madre!"]', 1784690324374);
