INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('21-cay-cau', '21 Cây Cầu', '21 Bridges', 'https://phimimg.com/upload/vod/20260126-1/de2e69ef88dd5cc428969ac5e01da7c5.jpg', 'https://phimimg.com/upload/vod/20260126-1/cf520f7dc417987c6b1f2c7bf3b72c38.jpg', '<p>Một loạt cảnh sát tại New York bị giết chết bí ẩn. Thanh tra Andre Davis xông pha vào cuộc và phát hiện ra những âm mưu khủng khiếp của một băng đảng khát máu. Để triệt hạ chúng, Andre Davis đã khẩn cầu chính quyền đóng cửa toàn bộ 21 cây cầu, khiến cả hòn đảo Manhattan - trái tim của New York trở thành tử địa, nội bất xuất ngoại bất nhập.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chadwick Boseman","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Stephan James","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Keith David","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Victoria Cartagena","avatar":""},{"name":"Gary Carr","avatar":""},{"name":"Morocco Omari","avatar":""},{"name":"Chris Ghaffari","avatar":""},{"name":"Dale Pavinski","avatar":""},{"name":"Christian Isaiah","avatar":""},{"name":"Sarah Ellen Stephens","avatar":""},{"name":"Jamie Neumann","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["17 Bridges","21 브릿지-테러 셧다운","Nueva York sin salida","MANHATTAN LOCKDOWN","Manhattan sin salida","21 Bridges (2019)","21 Bridges - Jagd durch Manhattan","21 Köprü","21 Bridges"]', 1784690324374);
