INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-godzilla-de-vuong-bat-tu', 'Chúa Tể Godzilla: Đế Vương Bất Tử', 'Godzilla: King of the Monsters', 'https://phimimg.com/upload/vod/20260123-1/9432196d1b83d912a85592fe1f46d662.jpg', 'https://phimimg.com/upload/vod/20260123-1/ad462632fc712ebe980dedb5c63a9a5e.jpg', '<p>Sự xuất hiện của Godzilla trong quá khứ khiến con người phát hiện ra những sinh vật cổ đại Titan khổng lồ vẫn còn tồn tại trên Trái Đất. Sau trận chiến đánh bại kẻ thù, Godzilla mất tích vào lòng biển. Một ngày kia, Rồng ba đầu Ghidorah trỗi dậy kéo theo sự thức tỉnh của hàng trăm quái vật khổng lồ. Tất cả những gì chúng muốn là tranh giành quyền lực tối cao, thống lĩnh thế giới. Trong trận đại chiến hủy diệt chưa từng có trong lịch sử này, liệu &quot;Chúa tể của muôn loài&quot; Godzilla sẽ trở lại và là “đấng cứu thế” của nhân loại trước hiểm họa diệt vong ?</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kyle Chandler","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Millie Bobby Brown","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Thomas Middleditch","avatar":""},{"name":"Aisha Hinds","avatar":""},{"name":"O''Shea Jackson Jr.","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Elizabeth Faith Ludlow","avatar":""},{"name":"Jonathan Howard","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":