INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chua-te-godzilla-de-vuong-bat-tu', 'Chúa Tể Godzilla: Đế Vương Bất Tử', 'Godzilla: King of the Monsters', 'chúa tể godzilla: đế vương bất tử godzilla: king of the monsters kyle chandler vera farmiga millie bobby brown ken watanabe zhang ziyi bradley whitford sally hawkins charles dance thomas middleditch aisha hinds o''shea jackson jr. david strathairn anthony ramos elizabeth faith ludlow jonathan howard godzilla ii: king of the monsters fathom godzilla 2 godzila: monstrų karalius gojira kingu obu monsutāzu 고질라: 킹 오브 몬스터 godzilla 2 - rei dos monstros godzilla：king of the monsters godzilla: rey de los monstruos 2019 哥斯拉2：怪兽之王 哥吉拉ii：怪獸之王 哥斯拉2: 王者巨獸 ゴジラ　キング・オブ・モンスターズ godzilla ii: el rey de los monstruos گودزیلا: سلطان هیولاها godzilla 2 re dei mostri chúa tể godzilla 2: đế vương bất tử godzilla 2: king of the monsters 哥斯拉ii：王者巨獸 godzilla: raja segala raksasa godzilla king of the monsters kotm godzilla: king of the monsters', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-buom-buom', 'Ngôi Nhà Bươm Bướm', 'Butterfly House', 'https://phimimg.com/upload/vod/20260123-1/cc327cd05f3103774e34870a61b7714e.jpg', 'https://phimimg.com/upload/vod/20260123-1/ea656687938967a0f0bdc295616efe7f.jpg', '<p>Ngôi nhà bươm bướm xoay quanh câu chuyện tình của Hoàng (Liên Bỉnh Phát) và Mai (Hoàng Yến Chibi). &nbsp;Yêu nhau trong lúc cùng du học ở Mỹ, cả hai quyết định tiến đến hôn nhân. Rắc rối nằm ở chỗ ba mẹ của Hoàng - ông Cường (Quang Minh) và dì Hân (NSƯT Thành Lộc) - là một đôi đồng tính. &nbsp;Trong khi đó, phía sui gia là ông Thịnh (Xuân Trường) chuẩn bị lên chức hiệu trưởng một ngôi trường cấp III có tiếng ở Hà Nội, và mang quan niệm sống truyền thống, khắt khe. Sau vài lần thuyết phục, Mai mới có thể đưa cha và mẹ (Hồng Đào) vào Sài Gòn để gặp gỡ gia đình Hoàng. &nbsp;Từ đây, hàng loạt sự kiện dở khóc dở cười xảy ra khiến cuộc hôn nhân của đôi trẻ đứng trước nguy cơ tan vỡ.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Võ Quang Minh","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Xuan Truong","avatar":""},{"name":"Liên Bỉnh Phát","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Hồng Đào","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Butterfly House","Ngôi Nhà Bươm Bướm"]', 1784690324374);
