INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma', 'Má', 'Ma', 'https://phimimg.com/upload/vod/20260116-1/e6eb71f5848dfb82fb484c56d8e31f6f.jpg', 'https://phimimg.com/upload/vod/20260116-1/384c99fa1c295dc034b7f0b37d84d4c3.jpg', '<p>Bộ phim MA xoay quanh nữ sát nhân biến thái do Octavia Spencer thủ vai. Cô là một người phụ nữ cô độc, luôn giữ mình trong thị trấn yên tĩnh ở Ohio. Khi được một nhóm bạn trẻ hỏi mua rượu, cô ta đã gợi ý cho họ xuống hầm căn nhà cũ của mình để tổ chức tiệc tùng nhằm tránh việc say rượu khi lái xe. Tuy nhiên, khi đám bạn trẻ nhận ra sự kỳ lạ của người phụ nữ này thì cũng là lúc mọi điều đáng sự, ám ảnh xảy đến với chính họ.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Octavia Spencer","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Diana Silvers","avatar":""},{"name":"McKaley Miller","avatar":""},{"name":"Corey Fogelmanis","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Gianni Paolo","avatar":""},{"name":"Dante Brown","avatar":""},{"name":"Tate Taylor","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Dominic Burgess","avatar":""},{"name":"Tanyell Waivers","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Heather Marie Pate","avatar":""},{"name":"Victor Turpin","avatar":""},{"name":"Kyanna Simone Simpson","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Messiba Sof","マー -サイコパスの狂気の地下室-","Keva","แม่_ร้าย","马大姐","マー ―サイコパスの狂気の地下室―","Restez sains et saufs, Ma","MA","Ma"]', 1784690324374);
