INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-de-dai-une-fille-facile', 'Cô Nàng Dễ Dãi (Une fille facile)', 'An Easy Girl', 'https://phimimg.com/upload/vod/20260116-1/cc15fbc56d153409509fc96ca447f173.jpg', 'https://phimimg.com/upload/vod/20260116-1/939b03a580df6a506a0c8c97694dd621.jpg', '<p>Sau khi năm học kết thúc, người em họ 22 tuổi của cô là Sofia đến Paris để cùng cô trải qua kỳ nghỉ. Là một phụ nữ trẻ có tâm hồn phóng khoáng và ngoại hình quyến rũ, Sofia sẵn sàng tham gia vào những cuộc chơi tới bến. Đến bãi biển đầy bọt và hộp đêm, hai chị em tình cờ gặp Andres và Philippe. Hai người đàn ông giàu có mời họ lên du thuyền, Sofia hướng dẫn Naïm làm quen với thế giới của sự sang trọng, lộng lẫy. Liệu mọi chuyện rồi sẽ ra sao, Naïma học được gì từ cô em họ của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Mina Farid","avatar":""},{"name":"Zahia Dehar","avatar":""},{"name":"Benoît Magimel","avatar":""},{"name":"Nuno Lopes","avatar":""},{"name":"Clotilde Courau","avatar":""},{"name":"Lakdhar Dridi","avatar":""},{"name":"Loubna Abidar","avatar":""},{"name":"Henri-Noël Tabary","avatar":""},{"name":"Cédric Appietto","avatar":""},{"name":"Mickaël Migliorini","avatar":""},{"name":"Mathias Ben Hamou","avatar":""},{"name":"Colette Rossi","avatar":""},{"name":"Lise Lomi","avatar":""},{"name":"Martine Guzman","avatar":""},{"name":"Julie Allione","avatar":""},{"name":"Lolita Chammah","avatar":""},{"name":"Andy Gi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Easy Girl","Моє спекотне літо з Соф