INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-giet-nguoi-bi-an', 'Vụ Giết Người Bí Ẩn', 'Murder Mystery', 'https://phimimg.com/upload/vod/20260112-1/b65d1e46ae6bb2ae302bd84f5da6f664.jpg', 'https://phimimg.com/upload/vod/20260112-1/c419514bbf95c06086eb8a956c2803da.jpg', '<p>Đánh dấu sự trở lại của 2 diễn viên hài Adam Sandler và Jennifer Anniston. Murder Mystery kể về tuần trăng mật đầy kì thú của đôi vợ chồng trẻ Nick Spitz và Audrey Spitz, vô tình trong chuyến đi châu Âu họ vướng vào một âm mưu giết người nguy hiểm và bất kì ai trên chuyến tàu đó đều có dấu hiệu khả nghi. Đứng giữa việc bị nghi ngờ và bị theo dõi, 2 vợ chồng quyết định tự mình truy tìm sự thật về kẻ giết người, đồng thời họ khám phá ra một âm mưu lớn đằng sau đó.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"David Walliams","avatar":""},{"name":"Dany Boon","avatar":""},{"name":"John Kani","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Luis Gerardo Méndez","avatar":""},{"name":"Shioli Kutsuna","avatar":""},{"name":"Erik Griffin","avatar":""},{"name":"Sufe Bradshaw","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Leigh Kil","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Criminales en el mar","Misterio a Bordo","Gyagyás gyilkosság","Таємниче вбивство","За