INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-an-co-mat-2019', 'Long Ẩn Cơ Mật', 'Iron Mask', 'https://phimimg.com/upload/vod/20260108-1/027226ddc79f20b43876dcf30e9efbd8.jpg', 'https://phimimg.com/upload/vod/20260108-1/1d8c7e51e2727dd7c614c2daf9c60d86.jpg', '<p>Long Ấn Cơ Mật, Jouey to China: The Iron Mask Mystery (2019) Nhà du hành người Anh Jonathan Green nhận được từ Peter Đại đế một đơn đặt hàng để lập bản đồ Viễn Đông Nga. Một lần nữa, anh bắt đầu một cuộc hành trình dài đầy những cuộc phiêu lưu kỳ thú cuối cùng sẽ đưa anh đến Trung Quốc. Người vẽ bản đồ sẽ bất ngờ đối mặt với rất nhiều khám phá ngoạn mục, gặp gỡ những sinh vật kỳ quái, gặp gỡ các Công chúa Trung Quốc và đối đầu với các võ sư chết chóc và thậm chí là vua của tất cả các con rồng, Vua rồng. Điều gì có thể nguy hiểm hơn là gặp gỡ trực tiếp với Viy, ngoại trừ làm lại? Điều gì sẽ mạnh mẽ hơn lần này, một sự hoài nghi trung thành của nhà khoa học hoặc ma thuật đen cũ đã chiếm lấy quyền lực của các vùng đất phương Đông ?</p>', 'Full', 1, 'single', 'completed', 30, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jason Flemyng","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Yao Xingtong","avatar":""},{"name":"Anna Churina","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Pavel Volya","avatar":""},{"name":"Vilen Babichev","avatar":""},{"name":"Mikhail Mukhin","avatar":""},{"name":"Aleksandr Tsyoma","avatar":""},{"name":"Aleksey Ogurtsov","avatar":""},{"name":"Igor Jijik","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Viy 2. Tayna Pechati drakona","Тайна Железной маски: путешествие в Китай","The Mystery of the Dragon Seal: Journey to China","Вий 2. Тайна Печати дракона","Tayna pechati drakona","The Iron Mask","The Iron Mask : La légende du dragon","비이 2","Viy 2","The Dragon Seal","Long pai zhi mi","Le mystère du sceau du dragon","Viy 2 - El Misterio Del Dragon","Fürst der Dämonen 2","Fürst der Dämonen 2 - Iron Mask","La Légende du dragon","The Journey to China: The Mystery of Iron Mask","中国游记","نقاب آهنین","وی ۲: سفر به چین","Journey to China; The Mystery of Iron Mask","中国游记：龙牌之谜","Тайна печати Дракона"]', 1784690324374);
