INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-song-phan-10', 'Xác Sống (Phần 10)', 'The Walking Dead (Season 10)', 'https://phimimg.com/upload/vod/20250917-1/3d4f5f6cd3648ce22a1bc6e974993092.jpg', 'https://phimimg.com/upload/vod/20250917-1/c56c983c56225ee625e062f15e52dd09.jpg', '<p>Loạt phim xoay quanh nhân vật do nam diễn viên Andrew Lincoln thủ vai chính là phó cảnh sát trưởng Rick Grimes, người đã tỉnh dậy sau một khoảng thời gian hôn mê và nhận ra rằng thế giới đã bước vào thời kỳ hậu tận thế với sự xuất hiện tràn lan của thây ma ăn thịt. Anh lên đường tìm kiếm gia đình mình và gặp được nhiều người vẫn còn sống sót trên đường đi.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Cohan","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Melissa McBride","avatar":""},{"name":"Christian Serratos","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Ross Marquand","avatar":""},{"name":"Josh McDermitt","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Cooper Andrews","avatar":""},{"name":"Callan McAuliffe","avatar":""},{"name":"Cailey Fleming","avatar":""},{"name":"Lauren Ridloff","avatar":""},{"name":"Eleanor Matsuura","avatar":""},{"name":"Nadia Hilker","avatar":""},{"name":"Cassady McC","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Të vdekurit e gjallë","Живите мъртви","Les morcheurs","行尸走肉","Živí mrtví","Elavad surnud","Οι Ζωντανοί Νεκροί","行屍","Živi mrtvaci","מתים מהלכים","Mordeye moteharrek","ウォーキング・デッド","워킹 데드","워킹데드","Gyvieji numirėliai","Gyvi numirėliai","Staigājušie Miroņi","Живи Мртовци","Żywe trupy","The Walking Dead","The Walking Dead: Invazia zombi","Okružen mrtvima","Zivi mrtveci","Živí mŕtvi","ล่าสยอง...กองทัพผีดิบ","ฝ่าวงล้อม ซอมบี้ล้างโลก","Yürüyen Ölüler","Ходячі мерці","І мертві підуть","TWD","Yuradigan murdalar","Xac Song"]', 1784690324374);
