INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aochan-khong-the-hoc', 'Ao-chan Không Thể Học!', 'Ao-chan Can''t Study!', 'https://phimimg.com/upload/vod/20251223-1/4ee83db56889d46e54ad1bc40dcdde24.jpg', 'https://phimimg.com/upload/vod/20251223-1/fd63ebd3f8586af664ac8ea8f601cdc2.jpg', '<p>Cha của ao horie, một tác giả tiểu thuyết khiêu dâm nổi tiếng, đã chọn tên ao vì a là viết tắt của &quot;apple&quot; và o là viết tắt của &quot;orgy&quot;! Tuyệt vọng muốn thoát khỏi di sản của cha mình và vào một trường đại học danh tiếng, ao dành hết tâm trí vào việc học thay vì theo đuổi tình yêu. cô không có thời gian cho con trai, nhưng chỉ có một vấn đề: Kijima, bạn cùng lớp đẹp trai và nổi tiếng của cô, vừa thú nhận tình yêu của mình với cô! Và tệ hơn nữa, cô không thể ngừng nghĩ những suy nghĩ bẩn thỉu về anh ta! Có vẻ như việc thoát khỏi ảnh hưởng của cha cô sẽ khó khăn hơn cô nghĩ…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Juri Kimura","avatar":""},{"name":"Toshinari Fukamachi","avatar":""},{"name":"Yusuke Shirai","avatar":""},{"name":"Takashi Kondo","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Junta Terashima","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["满脑都是OO的我没办法谈恋爱","Ao-chan, ça n''étudie pas !","Ao-chan can''t study !","Midara na Ao-chan wa Benkyou ga Dekinai","Midara na Ao-chan wa Benkyō ga Dekinai","淫らな青ちゃんは勉強ができない","Ao-chan Can''t Study!","滿腦都是○○的我沒辦法談戀愛