INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('archer-phan-10', 'Archer (Phần 10)', 'Archer (Season 10)', 'https://phimimg.com/upload/vod/20251220-1/585537d1f857a8a39fae31ce71d45654.jpg', 'https://phimimg.com/upload/vod/20251220-1/1c7fef443b51101ac7e5ee352b5e903a.jpg', '<p>Sterling Archer là điệp viên đáng gờm nhất thế giới. Anh làm việc cho ISIS, một cơ quan tình báo do chính mẹ mình điều hành. Giữa những lần đối phó với sếp và các đồng nghiệp — một trong số đó là bạn gái cũ của anh — Archer luôn tìm cách quấy rối hoặc quyến rũ bất kỳ ai lướt qua đời mình. Những trò hề của anh chỉ có thể được tha thứ vì sau cùng, bằng một cách nào đó, anh vẫn luôn ngăn chặn thành công mọi cuộc khủng hoảng đe dọa đến nhân loại.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"H. Jon Benjamin","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Amber Nash","avatar":""},{"name":"Chris Parnell","avatar":""},{"name":"Aisha Tyler","avatar":""},{"name":"Lucky Yates","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["间谍亚契","Archer: Vice","Archer: Dreamland","Archer: Danger Island","Archer: 1999","Archer: Into the Cold","Archer"]', 1784690324374);
