INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-fuller-phan-5', 'Gia Đình Fuller (Phần 5)', 'Fuller House (Season 5)', 'https://phimimg.com/upload/vod/20251220-1/7ecaf38a1347a15d65074f7a628c8fef.jpg', 'https://phimimg.com/upload/vod/20251220-1/38f41c84962c260d90f045fd5b5d654d.jpg', '<p>D.J. Tanner-Fuller là một góa phụ đang phải một mình nuôi dạy ba đứa con trai. Khi cuộc sống trở nên quá tải và khó lòng xoay sở, cô đã nhờ đến sự giúp đỡ của em gái Stephanie và người bạn thân nhất Kimmy. Cả ba người phụ nữ cùng chung sống dưới một mái nhà, tạo nên những tình huống gia đình vừa hài hước vừa ấm áp.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 12, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jodie Sweetin","avatar":""},{"name":"Candace Cameron Bure","avatar":""},{"name":"Andrea Barber","avatar":""},{"name":"Elias Harger","avatar":""},{"name":"Soni Bringas","avatar":""},{"name":"Michael Campion","avatar":""},{"name":"Juan Pablo Di Pace","avatar":""},{"name":"Fox Messitt","avatar":""},{"name":"Dashiell Messitt","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Jobban bír-lak","Fuller House"]', 1784690324374);
