INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dororo-di-tim-48-phan-co-the', 'Dororo (Đi Tìm 48 Phần Cơ Thể)', 'Dororo', 'https://phimimg.com/upload/vod/20251221-1/2f8a47c504c557b45baa8c1344ee109b.jpg', 'https://phimimg.com/upload/vod/20251221-1/7afb59bd358d9322305de001ba090964.jpg', '<p>Phim kể về Dororo, một tiểu tặc tinh ranh, trong một lần nọ đã gặp được Hyakkimaru, một lãng nhân chuyên đi săn quỷ. Trước khi Hyakkimaru chào đời, cha của cậu, lãnh chúa Kagemitsu Daigo, đã lập khế ước trao 12 phần trên cơ thể con mình cho quỷ, đổi lại, ông sẽ có được giang sơn. Và thế là, Hyakkimaru ra đời với một cơ thể dị dạng, người chẳng ra người, quỷ chẳng ra quỷ, chính vì thế, Daigo đã sai người thả cậu trôi sông, mặc cho số phận con trai mình. Nhưng may thay, Hyakkimaru vô tình được một đại phu nọ cứu, ấy cũng là người nuôi lớn, làm cho cậu những bộ phận giả thay thế những phần bị lấy mất. Qua bao năm tháng, giờ Hyakkimaru đã trưởng thành, đồng nghĩa với việc, hành trình tìm diệt 12 con quỷ nhằm đoạt lại những phần cơ thể bị lấy mất của cậu bắt đầu</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 12, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rio Suzuki","avatar":""},{"name":"Hiroki Suzuki","avatar":""},{"name":"Naoya Uchida","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Mutsumi Sasaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dororo to Hyakkimaru","Dororo (2019)","どろろ(2019)","도로로","دورورو","Dororo","どろろ"]', 1784690324374);
