INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('younger-phan-6', 'Younger (Phần 6)', 'Younger (Season 6)', 'https://phimimg.com/upload/vod/20251217-1/4266a6931a73c7d1620b998e4d860e68.jpg', 'https://phimimg.com/upload/vod/20251217-1/b13862be07a72b668b4fe146a9deb19d.jpg', '<p>Ở tuổi 40, bà mẹ đơn thân Liza gặp khó khăn khi tìm việc nên đã quyết định giả làm gái trẻ 26 tuổi. Cô thành công trở thành trợ lý tại một nhà xuất bản và phải nỗ lực che giấu thân phận thật sự của mình với tất cả mọi người, ngoại trừ cô bạn thân.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sutton Foster","avatar":""},{"name":"Hilary Duff","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Nico Tortorella","avatar":""},{"name":"Molly Bernard","avatar":""},{"name":"Peter Hermann","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["第二春","サバヨミ大作戦！","ライザのサバヨミ大作戦","Younger"]', 1784690324374);
