INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dam-len', 'Kẻ đâm lén', 'Knives Out', 'https://phimimg.com/upload/vod/20251216-1/e88dc1e333d05d5c7a77338edb06bbf7.jpg', 'https://phimimg.com/upload/vod/20251216-1/10aaf42c52cfebb378d285cee41d17d1.jpg', '<p>Nhân dịp sinh nhật lần thứ 85 của mình, tiểu thuyết gia trinh thám nổi tiếng Harlan Thombrey đã tổ chức một buổi tiệc với đông đủ các thành viên trong gia đình. Tuy nhiên, ông Harlan bất ngờ qua đời ngay trong ngày hôm đấy. Thám tử Benoit Blanc được cử đến để điều tra vụ án và tất cả mọi người trong gia đình đều trở thành nghi phạm. Vậy trong ngôi nhà nhiều thế hệ này, ai mới chính là ‘Kẻ Đâm Lén’?</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Daniel Craig","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Katherine Langford","avatar":""},{"name":"Jaeden Martell","avatar":""},{"name":"Riki Lindhome","avatar":""},{"name":"Edi Patterson","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"K Callan","avatar":""},{"name":"Noah Segan","avatar":""},{"name":"M. Emmet Wals","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Morning Bell","Knives Out - Ein Mord zum Dessert","Knives Out 1","ナイブズ・アウト／名探偵と刃の館の秘密","Knives Out"]', 1784690324374);
