INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-quan-sieu-thu', 'Liên Quân Siêu Thú', 'StarDog and TurboCat', 'https://phimimg.com/upload/vod/20251215-1/55d01994537b33c7cd7aa978e6068094.jpg', 'https://phimimg.com/upload/vod/20251215-1/4256d630dedddec6080377ee1468b2fc.jpg', '<p>Năm 1969, có 1 chú chó được đưa vào không gian, nhưng một sự cố xảy ra và biến chú thành Siêu Cún. Lạc lối ở tương lai nơi tất cả mọi người đều căm ghét động vật, Siêu Cún cần tìm cho mình những trợ thủ đắc lực để giúp cậu gặp lại chủ nhân của mình. Sau cuộc gặp gỡ tình cờ với Mèo Tia Chớp, Thỏ Thông Thái và tổ chức Vệ Thú – nơi bảo vệ các loài động vật ở Glenfield, Siêu Cún và bộ sậu mới của cậu bất đắc dĩ phải đối đầu với chính quyền thị trấn và trở thành những anh hùng quả cảm.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Luke Evans","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Ben Bailey Smith","avatar":""},{"name":"Rachael Louise Miller","avatar":""},{"name":"Cory English","avatar":""},{"name":"Morgan Cambs","avatar":""},{"name":"Ben Smith","avatar":""},{"name":"Dan Russell","avatar":""},{"name":"Robert G. Slade","avatar":""},{"name":"Charli D''Amelio","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["SpaceDog and TurboCat","明星狗与涡轮猫","Супер Пёс и Турбо Кот","スタードッグ＆ターボキャット","SuperHond & TurboKat","Tähekoer ja Turbokass","StarDog and TurboCat"]', 1784690324374);
