INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nhan-cua-dac-vu', 'Tình Nhân Của Đặc Vụ', 'Above Suspicion', 'https://phimimg.com/upload/vod/20251206-1/6c47077ca1ff0f6d5580a58508a80ce5.jpg', 'https://phimimg.com/upload/vod/20251206-1/d6edde70df8df569258d952be8b01818.jpg', '<p>Câu chuyện có thật rợn người về một chàng trai gương mẫu của FBI, vừa kết hôn, được điều động đến một thị trấn vùng núi Appalachian ở Kentucky. Tại đây, anh bị cuốn vào một mối tình vụng trộm với một người phụ nữ địa phương nghèo khó, người sau đó trở thành người cung cấp tin mật chủ chốt của anh. Cô nhìn thấy ở anh phương tiện để thoát thân; nhưng thay vào đó, mối quan hệ này lại trở thành một thảm họa cho cả hai người.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emilia Clarke","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Johnny Knoxville","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Sophie Lowe","avatar":""},{"name":"Austin Hébert","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Chris Mulkey","avatar":""},{"name":"Omar Benson Miller","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Brian Lee Franklin","avatar":""},{"name":"Brittany O''Grady","avatar":""},{"name":"Luke Spencer Roberts","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Robert C. T","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["危險線人","エージェント・スミス：2019","Suspicions","Above Suspicion"]', 17846903243