INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-co-lan-hai', 'Không Có Lần Hai', 'Never Twice', 'https://phimimg.com/upload/vod/20251203-1/2ef86569c840b2beefa7e2e875f57ba0.jpg', 'https://phimimg.com/upload/vod/20251203-1/4584a091a74d4fc5f92d2f7170598c96.jpg', '<p>Nằm giữa Seoul hoa lệ, có một quán trọ từng là nơi ẩn mình của các văn nghệ sĩ nổi tiếng. Nhiều năm qua đi, nơi này giờ đã xuống cấp và trở thành chốn dừng chân của những người không còn nơi nào để đi, những người có cuộc sống phức tạp hoặc đang mang trong mình những vết thương tinh thần chưa lành hẳn. Và cũng ở chính nơi đây, những vị khách trọ tìm thấy sự kết nối kỳ diệu giữa người với người và từ đó dần tìm lại được phương hướng cho cuộc đời lạc lối của mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2019, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Se-wan","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Youn Yuh-jung","avatar":""},{"name":"Oh Ji-ho","avatar":""},{"name":"Ye Ji-won","avatar":""},{"name":"Park Ah-in","avatar":""},{"name":"Park Joon-geum","avatar":""},{"name":"Hwang Young-hee","avatar":""},{"name":"Ji Hye-in","avatar":""},{"name":"Kwon Eun-bin","avatar":""},{"name":"Jeon Soo-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Doobuneun Eobda","두번은 없다","No Second Chances","No Second Chance","두 번은 없다"]', 1784690324374);
