INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-sat-nhan-mercedes-phan-3', 'Tên Sát Nhân Mercedes (Phần 3)', 'Mr. Mercedes (Season 3)', 'https://phimimg.com/upload/vod/20251124-1/d161163ccab4e877689438aa06507287.jpg', 'https://phimimg.com/upload/vod/20251124-1/bd01b752b6e9360b4a55e8d1da91c65a.jpg', '<p>Một kẻ giết người hàng loạt điên loạn liên tục trêu chọc một thám tử cảnh sát đã về hưu bằng một loạt thư và email rùng rợn. Điều này buộc cựu cảnh sát phải thực hiện một chiến dịch tư nhân, có nguy cơ phạm pháp, nhằm đưa kẻ sát nhân ra công lý trước khi hắn ra tay một lần nữa.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brendan Gleeson","avatar":""},{"name":"Jharrel Jerome","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Breeda Wool","avatar":""},{"name":"Justine Lupe","avatar":""},{"name":"Maximiliano Hernández","avatar":""},{"name":"Gabriel Ebert","avatar":""},{"name":"Rarmian Newton","avatar":""},{"name":"Claire Bronson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Г-н Мерседес","มิสเตอร์เมอร์เซเดส","Mr. Mercedes"]', 1784690324374);
