INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-su-tu-2019', 'Vua Sư Tử', 'The Lion King', 'https://phimimg.com/upload/vod/20251120-1/92102b867102c99ae65634e09707aca2.jpg', 'https://phimimg.com/upload/vod/20251120-1/6a343a21e2381d8f507b0ee25069816e.jpg', '<p>Bộ phim Vua Sư Tử được đạo diễn bởi Jon Favreau sẽ đưa khán giả đến với xavan Châu Phi rộng lớn nơi vị vua tương lai Simba được sinh ra. Tuy là người kế vị ngai vàng chính thức nhưng Simba phải đương đầu với những âm mưu của Scar, người chú ruột luôn toan tính chiếm lấy ngôi báu. &nbsp;Cuộc chiến ở Pride Rock trở nên khốc liệt hơn bao giờ hết và đỉnh điểm là việc chú sư tử Simba bị lưu đày khỏi quê hương. Với sự giúp đỡ của 2 người bạn mới Timon và Pumbaa, Simba dần học cách trưởng thành và quay trở về để giành lại những gì vốn dĩ thuộc về cậu. Bằng kĩ xảo đồ họa ấn tượng và âm nhạc sống động, Vua Sư Tử sẽ tái hiện lại những nhân vật mà khán giả yêu mến theo một cách hoàn toàn mới.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chiwetel Ejiofor","avatar":""},{"name":"John Oliver","avatar":""},{"name":"Donald Glover","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"John Kani","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Beyoncé","avatar":""},{"name":"JD McCrary","avatar":""},{"name":"Shahadi Wright Joseph","avatar":""},{"name":"Penny Johnson Jerald","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Eric André","avatar":""},{"name":"Florence Kasumba","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Billy Eichner","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Chance th","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Vasiliás Ton Liontarión","Król Lew","Levji kralj","獅子王","The Realistic Lion King","狮子王3D重拍版","The Lion King"]', 1784690324374);
