INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pen15-phan-1', 'PEN15 (Phần 1)', 'PEN15 (Season 1)', 'https://phimimg.com/upload/vod/20251115-1/d30f8b0e86ba0d8e2ee51b7a426cf9c1.jpg', 'https://phimimg.com/upload/vod/20251115-1/aeb00b4ba3a0ed5ce16b2cf112d4d1d4.jpg', '<p>Maya Erskine và Anna Konkle vào vai chính… là chính họ phiên bản 13 tuổi vào năm 2000, trong khi toàn bộ bạn diễn còn lại đều là học sinh 13 tuổi thật. Bộ phim tái hiện đời sống trung học cơ sở một cách chân thật, hài hước và đầy ngượng ngùng — nơi chỉ một nét bút gel cũng có thể biến “ngày tuyệt nhất” thành “ngày tệ nhất”.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maya Erskine","avatar":""},{"name":"Anna Konkle","avatar":""},{"name":"Mutsuko Erskine","avatar":""},{"name":"Taylor Nichols","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Taj Cross","avatar":""},{"name":"Dallas Liu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["PEN15"]', 1784690324374);
