INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-thu-tuong-lai-phan-2', 'Cao Thủ Tương Lai (Phần 2)', 'Future Man (Season 2)', 'https://phimimg.com/upload/vod/20251115-1/bd447df4595822dc7fc29d28a23812b6.jpg', 'https://phimimg.com/upload/vod/20251115-1/e3c6518768af93d508b7762c86c0b8c3.jpg', '<p>Josh Futturman, một người gác cổng ban ngày nhưng là một game thủ đẳng cấp thế giới ban đêm, được giao nhiệm vụ ngăn chặn sự tuyệt chủng của nhân loại sau khi những vị khách bí ẩn từ tương lai tuyên bố anh là chìa khóa để đánh bại cuộc xâm lăng sắp xảy ra của một siêu chủng tộc.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 12, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Hutcherson","avatar":""},{"name":"Eliza Coupe","avatar":""},{"name":"Derek Wilson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Future Man - O Viajante Do Tempo","Futureman","Future Man"]', 1784690324374);
