INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-ton-trong-thinh-lang', 'Sinh Tồn Trong Thinh Lặng', 'The Silence', 'https://phimimg.com/upload/vod/20251028-1/08339f60fa151ff5c3a868fd261e3692.jpg', 'https://phimimg.com/upload/vod/20251028-1/40f654ecaa859ea4f495ca6a9e71d566.jpg', '<p>Khi thế giới bị tấn công bởi những sinh vật nguy hiểm chết người săn mồi bằng âm thanh, cô gái tuổi teen cùng gia đình lánh nạn ở ngoại ô và gặp phải một hội thánh bí ẩn.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stanley Tucci","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Kate Trotter","avatar":""},{"name":"John Corbett","avatar":""},{"name":"Kyle Breitkopf","avatar":""},{"name":"Dempsey Bryk","avatar":""},{"name":"Billy MacLellan","avatar":""},{"name":"Chris Whitby","avatar":""},{"name":"Barbara Gordon","avatar":""},{"name":"Zoe Doyle","avatar":""},{"name":"Cory O''Brien","avatar":""},{"name":"Alex Hatz","avatar":""},{"name":"Gregory Waters","avatar":""},{"name":"Sarah Abbott","avatar":""},{"name":"Kate Corbett","avatar":""},{"name":"John Fray","avatar":""},{"name":"Konima Pa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["El silencio","Ни звука","Un silence de mort","เงียบให้รอด","收聲剎","死寂逃亡","الصمت","Səssizlik","The Silence"]', 1784690324374);
