INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chien-1917', 'Thế Chiến 1917', '1917', 'https://phimimg.com/upload/vod/20251024-1/6cd279f40a9c7f76875fc333cb39fc64.jpg', 'https://phimimg.com/upload/vod/20251024-1/2ca80374fd7f4d471e125f7eea221cb7.jpg', '<p>1917 là một bộ phim chiến tranh sử thi của đạo diễn Sam Mendes và đồng biên kịch bởi Mendes và Krysty Wilson-Cairns. Bộ phim được dựa trên một câu chuyện do ông nội Alfred Mendes kể cho cháu Sam Mendes, và kể lại câu chuyện về hai người lính trẻ Anh ở đỉnh điểm của Thế chiến 1 trong Mùa xuân năm 1917, được giao nhiệm vụ đưa ra một thông điệp cảnh báo về một cuộc phục kích trong một trong những cuộc giao tranh ngay sau khi quân Đức rút về Phòng tuyến Hindenburg trong Chiến dịch Alberich - Thời gian chính là kẻ thù.</p>', 'Full', 1, 'single', 'completed', 22, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"George MacKay","avatar":""},{"name":"Dean-Charles Chapman","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Andrew Scott","avatar":""},{"name":"Richard Madden","avatar":""},{"name":"Claire Duburcq","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Daniel Mays","avatar":""},{"name":"Adrian Scarborough","avatar":""},{"name":"Chris Walley","avatar":""},{"name":"Nabhaan Rizwan","avatar":""},{"name":"Jamie Parker","avatar":""},{"name":"Tommy French","avatar":""},{"name":"Paul Tinto","avatar":""},{"name":"Billy Postlethwaite","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2