INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-quy-nhi-ma-thu-ba-takagi-phan-2', 'Nhất Quỷ Nhì Ma Thứ Ba Takagi (Phần 2)', 'Teasing Master Takagi-san (Season 2)', 'nhất quỷ nhì ma thứ ba takagi (phần 2) teasing master takagi-san (season 2) yuki kaji rie takahashi takagi: a mestra das pegadinhas 擅长捉弄人的高木同学 擅长捉弄的高木同学 karakai jouzu no takagi-san quand takagi me taquine karakai jōzu no takagi-san からかい上手の高木さん３ karakai jouzu no takagi-san 3 karakai jouzu no takagi-san 2 озорная такаги мастер дразнилок такаги поддразнивание такаги แกล้งนัก รักนะรู้ยัง? teasing master takagi-san からかい上手の高木さん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-13', 'Upin & Ipin (Phần 13)', 'Upin & Ipin (Season 13)', 'https://phimimg.com/upload/vod/20251022-1/fe5cf188c4b9e1e70936dd5c5a75b61e.jpg', 'https://phimimg.com/upload/vod/20251022-1/c6f1b1195566573c35f77b44753866bf.jpg', '<p>“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p>Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p><br/></p><p><br/></p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 17, 2019, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324374);
