INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('upin-ipin-phan-13', 'Upin & Ipin (Phần 13)', 'Upin & Ipin (Season 13)', 'upin & ipin (phần 13) upin & ipin (season 13) asyiela putri siti khairunnisa hajah ainon ariff calvin tony lokeemin tang ying sowk muhammad hafiz hassan muhammad fareez daniel rufaidah mohamed fadzil usayd uqashah kamsani siti nor adwin safie irfan fahim maheswary mohan suleiman bakti azl upin & ipin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-truyen-thuyet-than-dao', 'Upin & Ipin: Truyền Thuyết Thần Đao', 'Upin & Ipin: The Lone Gibbon Kris', 'https://phimimg.com/upload/vod/20251018-1/b8c3398dbd68870498b88be50080b753.jpg', 'https://phimimg.com/upload/vod/20251018-1/f077e7992a7dcc0e818aa79a781ef670.jpg', '<p>Bộ phim phiêu lưu mới này kể về hai anh em song sinh đáng yêu Upin và Ipin cùng nhóm bạn Ehsan, Fizi, Mail, Jarjit, Mei Mei và Susanti trong hành trình giải cứu vương quốc huyền ảo Inderaloka khỏi tay ác vương Raja Bersiong. Câu chuyện bắt đầu khi Upin, Ipin và các bạn tình cờ phát hiện một thanh kiếm thần bí (kris) dẫn họ bước vào thế giới kỳ diệu này. Trong lúc tìm cách trở về nhà, họ bất ngờ được giao trọng trách khôi phục vương quốc về thời huy hoàng xưa. Với sự giúp đỡ của Mat Jenin và Belalang, nhóm bạn phải vượt qua hàng loạt thử thách cam go trong một hành trình đầy hành động, phép thuật và tiếng cười.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2019, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Mohd Amir Asyraf Mohd Noor Rashid","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Ahmad Mawardi Abdul Rahman","avatar":""},{"name":"Fakhrul Razi","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Muhammad Musyrif Azzat","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Andhika Astari","avatar":""},{"name":"Ahmad Razuri Roseli","avatar":""},{"name":"Siti Hasmah Taiban","avatar":""},{"name":"Muha","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"