INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dam-phat-chet-luon-phan-2', 'Đấm Phát Chết Luôn (Phần 2)', 'One Punch Man (Season 2)', 'đấm phát chết luôn (phần 2) one punch man (season 2) makoto furukawa kaito ishikawa hiroki yasumoto kazuhiro yamaji yuichi nakamura kenjiro tsuda aoi yuki saori hayami hikaru midorikawa ואן-פאנץ'' מאן וואן פאנץ'' מן वन पंच मैन مرد یک مشتی wanpanman one punch man one punch man ワンパンマン opm человек одного удара ون بنش مان anh hùng onepunch nhất quyền nhân ワンパンマン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-o-noi-tan-cung-anh-sao', 'Anh Ở Nơi Tận Cùng Ánh Sao', 'Stars Fall', 'https://phimimg.com/upload/vod/20251012-1/6df52bd311d19eba0ed553b9a379ab0a.jpg', 'https://phimimg.com/upload/vod/20251012-1/5376a7f4bb6d5d613e33bb69f624b4c8.jpg', '<p>Ánh sao lấp lánh giữa những ngón tay — là vết thương, hay là sự che chở ấm áp? Cậu ấm Bạch Hi và người bạn thân Lưu Xuân Xuân gặp phải một vụ tai nạn xe bí ẩn. Sau đó, trợ lý Hàn Trác xuất hiện — thực ra anh ta là vệ sĩ ngầm mang năng lực đặc biệt. Một phòng trưng bày danh tiếng bất ngờ mời Lưu Xuân Xuân tổ chức triển lãm tranh với điều kiện vô cùng hậu hĩnh. Ngay sau đó, một vệ sĩ khác tên Vương Viễn Thần cũng xuất hiện, nhưng thân thế anh ta lại mờ ám khó lường. Bốn người họ dần bị cuốn vào vòng xoáy hiểm nguy, và khi triển lãm tranh đến gần, sự thật ẩn giấu phía sau mọi chuyện bắt đầu dần hé lộ…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Su Shangqing","avatar":""},{"name":"Qi Mingzhe","avatar":""},{"name":"Chen Siyu","avatar":""},{"name":"Li Lanling","avatar":""},{"name":"Zhang Enze","avatar":""},{"name":"Xiao Liansha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Zai Xing Guang Shen Chu","你在星光深处"]', 1784690324374);
