INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-tinh-qua-mang', 'Thư Tình Qua Mạng', 'The Space Between the Lines', 'https://phimimg.com/upload/vod/20251009-1/a1951711b8928749fed9e0de8e0397c2.jpg', 'https://phimimg.com/upload/vod/20251009-1/ab99aa119ea3994bd6c4c67dc7686450.jpg', '<p>Một email gửi nhầm đã mở đầu cho mối liên hệ kỳ lạ giữa Emma, một người phụ nữ đang trong mối quan hệ bế tắc, và Leo, một nhà ngôn ngữ học đang cố vượt qua nỗi cô đơn. Hai người bắt đầu trò chuyện qua email, chia sẻ cảm xúc, bí mật và dần nảy sinh tình cảm, dù chưa từng gặp mặt.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Nora Tschirner","avatar":""},{"name":"Alexander Fehling","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"Ella Rumpf","avatar":""},{"name":"Claudia Eisinger","avatar":""},{"name":"Katharina Gieron","avatar":""},{"name":"Eleonore Weisgerber","avatar":""},{"name":"Yoran Leicher","avatar":""},{"name":"Moritz Führmann","avatar":""},{"name":"Gina Henkel","avatar":""},{"name":"Piet Fuchs","avatar":""},{"name":"Martin Horn","avatar":""},{"name":"Dominik Maringer","avatar":""},{"name":"Joan Pascu","avatar":""},{"name":"Doris Plenert","avatar":""},{"name":"Karolina Horster","avatar":""},{"name":"Ul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["失眠的北风吹来爱情","Gut gegen Nordwind"]', 1784690324375);
