INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-nguoi-ban-phan-bien', 'Xin Chào Người Bạn Phản Biện', 'Hello Debate Opponent', 'https://phimimg.com/upload/vod/20251008-1/0dfeddac44cdf43535774cfccdbdb94f.jpg', 'https://phimimg.com/upload/vod/20251008-1/394887854d3b4ee258d6d68b0ef6481c.jpg', '<p>Phim xoay quanh cuộc sống và việc học tập của một nhóm sinh viên tại một ngôi trường đại học danh tiếng. Đều trẻ và tràn đầy sức sống, nhóm phản biện được thành lập và cùng nhau xây dựng, hoàn thiện các kỹ năng cho bản thân. Không có nhiều điều kiện nhưng bằng sự nhiệt huyết của tuổi trẻ, cả nhóm dần khẳng định được bản thân, dần tích lũy kinh nghiệm cho con đường còn rất dài phía trước.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Jiayi","avatar":""},{"name":"Zhai Zilu","avatar":""},{"name":"Lu Zhaohua","avatar":""},{"name":"Mi Mi","avatar":""},{"name":"Wang Zexuan","avatar":""},{"name":"Lin Lu","avatar":""},{"name":"Yu Xuanchen","avatar":""},{"name":"Wang Luqing","avatar":""},{"name":"Ke Ying","avatar":""},{"name":"Ren Luomin","avatar":""},{"name":"Yan Jingyao","avatar":""},{"name":"Zhang Naitian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["你好对方辩友","Hello Debate Opponent","Ni Hao Dui Fang Bian You","你好，对方辩友 2","니호, 대방변우2 : 우리들의 토론 이야기","니호, 대방변우 시즌 2","你好，对方辩友"]', 1784690324375);
