INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-thanh-trung', 'Thời Khắc Thanh Trừng', 'The Cleansing Hour', 'https://phimimg.com/upload/vod/20251008-1/bed2869a4c05f0e1caa0b8464c070473.jpg', 'https://phimimg.com/upload/vod/20251008-1/773e18b0f211d2d77a372c893c77c9b7.jpg', '<p>Một buổi trừ tà công chiếu trước hàng chục vạn con người đang xem, Những bí ẩn xung quanh các tập tục kỳ lạ trong video trực tiếp ấy,... Nhưng tất cả chỉ là trò dàn dựng câu view của Max và Drew, hai con người được cho là doanh nhân thành đạt. Mọi rắc rối bắt đầu nảy sinh khi một trong những diễn viên trong đoàn thực sự bị ma nhập, trở thành con tin của quỷ dữ. Trước đám đông đang say sưa chìm đắm vào thứ giả tạo mà ekip dàn dựng, tình huống này khiến những người trong cuộc rơi vào thế khó: nhục nhã hay là chết?</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kyle Gallner","avatar":""},{"name":"Ryan Guzman","avatar":""},{"name":"Alix Angelis","avatar":""},{"name":"Chris Lew Kum Hoi","avatar":""},{"name":"Emma Holzer","avatar":""},{"name":"Daniel Hoffmann-Gill","avatar":""},{"name":"Joanna David","avatar":""},{"name":"Tara Karsian","avatar":""},{"name":"Giulia Nahmany","avatar":""},{"name":"Amrou Al-Kadhi","avatar":""},{"name":"Matt Raimo","avatar":""},{"name":"Shvan Aladdin","avatar":""},{"name":"Lucas Bond","avatar":""},{"name":"Tiberiu Harsan","avatar":""},{"name":"Sam Hale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Година очищення","Exorzismus 2.0","Hodina očištění","A Hora do Exorcismo","Час дьявола [The Cleansing Hour (2019)]","The Cleansing Hour"]', 1784690324375);
