INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-linh-phi-phan-1', 'Thông Linh Phi (Phần 1)', 'Psychic Princess (Season 1)', 'https://phimimg.com/upload/vod/20251001-1/302df8d42ab6a770a6ab64ed4a4366be.jpg', 'https://phimimg.com/upload/vod/20251001-1/dae4f5754da95c4ece45e720cbcc71db.jpg', '<p>Đại tiểu thư phủ Thừa tướng Thiên Vân Hề từ nhỏ đã có năng lực dị thường, coi là điều không lành nên được nuôi trên núi Linh Vân. 16 tuổi thay em gái Thiên Vân Thường gả vào phủ Dạ vương. Nghe đồn Dạ U Minh tính cách lập dị, tàn nhẫn lạnh lùng. Điều gì sẽ chờ đợi Thiên Vân Hề phía trước?</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Nhật Oánh","avatar":""},{"name":"Yến Tử Đông","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["通灵妃"]', 1784690324375);
