INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-nam-3-thang-30-ngay-thap-nien-tam-nguyet-tam-thap-nhat', '10 Năm 3 Tháng 30 Ngày (Thập Niên Tam Nguyệt Tam Thập Nhật)', 'Ten Years Late', 'https://phimimg.com/upload/vod/20251001-1/5792453a6feade8885d418ab98b8d28b.jpg', 'https://phimimg.com/upload/vod/20251001-1/f7f65b6c55f26938f78914504aa4f58f.jpg', '<p>Trong &quot;10 năm 3 tháng 30 ngày&quot; Đậu Kiêu vào vai Cận Nhiên - tay săn công ty lừng lẫy trên thương trường. Nhưng vì tình yêu và ước mơ, từ bỏ mức lương ngất ngưởng, trở về nước đảm nhận Giám đốc điều hành của công ty Phi Đồ, gặp lại tình đầu. Sự nghiệp và tình yêu còn nhiều khó khăn, cậu ấy sẽ vượt qua thế nào? Na Trát vào vai Viên Lai - Trưởng phòng phát triển của Phi Đồ, cô gái ngay thẳng, ẩn nhẫn. Mối tình từ đại học đến công ty sẽ như thế nào ? 10 năm đã qua liệu sẽ viết lên cái kết rung động lòng người?</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Đậu Kiêu","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Song Dandan","avatar":""},{"name":"Kim Trạch","avatar":""},{"name":"Lưu Lộ","avatar":""},{"name":"Kanazawa","avatar":""},{"name":"Vương Quân","avatar":""},{"name":"Vương Quân Hạo","avatar":""},{"name":"Cảnh Lợi","avatar":""},{"name":"Trương Tân Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["十年三月三十日"]', 1784690324375);
