INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-nam-vung-2019', 'Kẻ Nằm Vùng', 'Undercover Punch And Gun', 'https://phimimg.com/upload/vod/20250626-1/9320e210f0e441976baa8fb7a971ec41.jpg', 'https://phimimg.com/upload/vod/20250626-1/8ef553cfb0bdfef5fea144f61f72a3fb.jpg', '<p>Tiểu Ngũ, từ là một cảnh sát ngầm lại tình cờ ngồi lên vị trí &quot;lão đại&quot;. Nào ngờ đó chính là cái bẫy để kéo anh xuống vũng lầy. Cùng lúc đó, một thế lực thần bí cũng gia nhập cuộc chơi bóng tối.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"An Chí Kiệt","avatar":""},{"name":"Ngũ Doãn Long","avatar":""},{"name":"Ngô Kiến Hào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Undercover vs. Undercover","Wo hu qian long","Undercover Punch & Gun","Под прикрытием: Удар и пистолет","潛行者","潛龍狙擊"]', 1784690324375);
