INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-uy-marvel', 'Đại Úy Marvel', 'Captain Marvel', 'https://phimimg.com/upload/vod/20250921-1/68ec76eabfab720f03ac7c6e59c81c56.jpg', 'https://phimimg.com/upload/vod/20250921-1/fade94fa0cacab50a76740e1dbf1c18f.jpg', '<p>Từ xa xưa, hai tộc Kree và Skrulls đã xảy ra cuộc chiến tranh kéo dài rất lâu, gọi là Chiến tranh Kree–Skrull. Với trình độ kĩ thuật phát triển, người Kree dần áp đảo trong cuộc chiến và khiến cho số lượng người Skrulls bị giảm đi đáng kể. &nbsp;Năm 1995, Vers thức giấc tại Hala, quê hương của Đế chế Kree. Cô luôn bị ác mộng về một vụ rơi máy bay, và về một người phụ nữ bị sát hại trước mặt mình. Trí nhớ của cô dừng lại tại thời điểm cô đạt được sức mạnh của mình. Cô được Yon-Rogg, thủ lĩnh của Starforce huấn luyện để trở thành thành viên của đội. Mặc dù Yon-Rogg tin rằng cô đã sẵn sàng nhưng Supreme Intelligence, một trí tuệ nhân tạo có vai trò điều hành Đế chế Kree lại không cho cô gia nhập đội, nơi mà có Minn-Erva - một xạ thủ bắn tỉa và các cộng sự Korath, Bron-Char và Att-Lass.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brie Larson","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Lashana Lynch","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Rune Temte","avatar":""},{"name":"Algenis Perez Soto","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Akira Akbar","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"Colin Ford","avatar":""},{"name":"Kenne","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kapitani Marveli","Kapetan Marvel","Captain Marvel 3D","Kapten Marvel","Kaptain Marvel","마블 캡틴 마블","Kapitenia Marvëll","Капитан Марвeл","Marvel Studios'' Captain Marvel","惊奇队长","Đại Uý Marvel","Kaptan Marvel","קאפטן מארוול 1","Kapitan Marvel","Capitana Marvel","كابتن مارفل","Captain Marvel"]', 1784690324375);
