INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-bong-toi', 'Đứa Con Của Bóng Tối', 'Brightburn', 'https://phimimg.com/upload/vod/20250920-1/6b60e144b7028ae16be1225a467059d6.jpg', 'https://phimimg.com/upload/vod/20250920-1/f1cac99a0164f1d077825d7094585a3f.jpg', '<p>Nhiều năm trước, cặp vợ chồng hiếm muộn Kyle và Tori khao khát và cầu nguyện có một đứa con sau những nỗ lực đầy tuyệt vọng. Cuối cùng, trong một đêm xuất hiện các hiện tượng đặc biệt, lời thỉnh cầu của họ đã được đáp lại. Kyle và Tori tìm thấy một đứa trẻ sơ sinh trong rừng. Họ vui mừng mang nó về nuôi và đặt tên là Brandon – một cậu bé kỳ dị.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jackson A. Dunn","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"David Denman","avatar":""},{"name":"Matt Jones","avatar":""},{"name":"Meredith Hagner","avatar":""},{"name":"Becky Wahlstrom","avatar":""},{"name":"Emmie Hunter","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"Annie Humphrey","avatar":""},{"name":"Abraham Clinkscales","avatar":""},{"name":"Christian Finlayson","avatar":""},{"name":"Jennifer Holland","avatar":""},{"name":"Terence Rosemore","avatar":""},{"name":"Elizabeth Becka","avatar":""},{"name":"Steve Agee","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Brandenburg","Brightburn","El hijo de la ocuridad"]', 1784690324375);
