INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bi-an', 'Cuộc Chiến Bí Ẩn', 'The Blackout', 'https://phimimg.com/upload/vod/20250918-1/a76ea66bdcfad458bb741044c1e88005.jpg', 'https://phimimg.com/upload/vod/20250918-1/52f81221ad48f221059e9b17c1ebe273.jpg', '<p>Không có thiên thạch rơi xuống Trái đất, không có kẻ khủng bố nào khiến thế giới gặp nguy hiểm, không có chiến tranh nguyên tử nào được bắt đầu, nhưng đã xảy ra sự cố. Liên lạc giữa hầu hết các thị trấn trên Trái đất đã bị cắt đứt. Một khu vực nhỏ như vòng ở Đông Âu vẫn có điện và thậm chí có thể có sự sống được báo cáo từ Không gian. Những gì lực lượng quân sự tìm thấy bên ngoài Ring là gây sốc. Có xác chết ở khắp mọi nơi: trong các cửa hàng, trong xe hơi, trên đường, trong bệnh viện và nhà ga. Ai hoặc cái gì đang phá hủy tất cả sự sống trên Trái đất? Tiền đồn cuối cùng của nhân loại sẽ tồn tại bao lâu?</p>', 'Full', 1, 'single', 'completed', 27, 2019, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Lukerya Ilyashenko","avatar":""},{"name":"Pyotr Fyodorov","avatar":""},{"name":"Svetlana Ivanova","avatar":""},{"name":"Aleksey Chadov","avatar":""},{"name":"Kseniya Kutepova","avatar":""},{"name":"Konstantin Lavronenko","avatar":""},{"name":"Philipp Avdeev","avatar":""},{"name":"Artyom Markaryan","avatar":""},{"name":"Sergey Godin","avatar":""},{"name":"Artyom Tkachenko","avatar":""},{"name":"Angelina Strechina","avatar":""},{"name":"Alexandr Nedorezov","avatar":""},{"name":"Stasya Tolstaya","avatar":""},{"name":"Mikhail Grubov","avatar":""},{"name":"Artyo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Blackout: Invasion Earth","Blackout: A Batalha Final","The Blackout: La Invasión","The Blackout","Blackout","前哨基地","Аванпост"]', 1784690324375);
