INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-cua-toi-khong-ngu-duoc', 'Hàng Xóm Của Tôi Không Ngủ Được', 'My Neighbour Can''t Sleep', 'https://phimimg.com/upload/vod/20250917-1/523d73158be6e5de6a2a21c5b5674f7c.jpg', 'https://phimimg.com/upload/vod/20250917-1/445c0e1d789a1387e5983e20e835bf76.jpg', '<p>Bộ phim kể về cô nàng Tống Mễ Đa – một “diễn viên chính kịch” với ước mơ trở thành nhà văn tiểu thuyết ngôn tình, và Tịch Tụng – một nghệ sĩ piano đang khổ sở vì căn bệnh mất ngủ. Giữa họ dần nảy sinh một chuyện tình ngọt ngào, nơi cả hai cùng nhau trưởng thành và hoàn thiện ước mơ của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Di Hân","avatar":""},{"name":"Vương Tử Tân","avatar":""},{"name":"Mã Tuyết Dương","avatar":""},{"name":"Dương Khả","avatar":""},{"name":"Tuyết Thành","avatar":""},{"name":"Quách Hức Văn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Neighbour Can''t Sleep","我的鄰居睡不著","我的邻居睡不着"]', 1784690324375);
