INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jumanji-tro-choi-ky-ao-thang-cap', 'Jumanji - Trò Chơi Kỳ Ảo: Thăng Cấp', 'Jumanji: The Next Level', 'https://phimimg.com/upload/vod/20250915-1/6bb50206f676e7e4ab4b76c4121b06b2.jpg', 'https://phimimg.com/upload/vod/20250915-1/ef204a33c091b37cf932193e67ab3d86.jpg', '<p>Nhiệm vụ lần này của các nhân vật khi quay trở lại Jumanji là để giải cứu một người bạn trong nhóm. Tuy nhiên những thử thách trước mắt không hề dễ dàng như họ nghĩ, phải đối mặt với vùng đất khô cằn và những ngọn núi tuyết cùng hàng loạt nguy hiểm chết người. Liệu chuyến hành trình có kết thúc tốt đẹp hay không?</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Nick Jonas","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Morgan Turner","avatar":""},{"name":"Madison Iseman","avatar":""},{"name":"Ser''Darius Blain","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Colin Hanks","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Marin Hinkle","avatar":""},{"name":"Vince Pisani","avatar":""},{"name":"Dorothy Steel","avatar":""},{"name":"Jen","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}