INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-sieu-anh-hung-4-hoi-ket', 'Biệt Đội Siêu Anh Hùng 4: Hồi Kết', 'Avengers: Endgame', 'biệt đội siêu anh hùng 4: hồi kết avengers: endgame robert downey jr. chris evans mark ruffalo chris hemsworth scarlett johansson jeremy renner josh brolin don cheadle paul rudd benedict cumberbatch chadwick boseman brie larson tom holland karen gillan zoe saldaña evangeline lilly tessa tho avengers: endgame 3d marvel studios'' avengers: endgame vengadores 4: endgame 复仇者联盟4：终局之战 vingadores ultimato vingadores: ultimato avengers 4: hồi kết 어벤져스 4 hakmarrësit: loja e fundit ha''nokmim: sof ha''mis''hak アベンジャーズ　エンドゲーム keršytojai: pabaiga اوینجرز : اینڈگیم мсціўцы: фінал одмаздници: крај на игрите qisasçılar: final վրիժառուները: վերջնախաղ المنتقمون: نهاية اللعبة انتقام‌جویان: پایان بازی кек алушылар: финал ar alýanlar: soňy oýun एभेन्जर्स: इन्डगेम অ্যাভেঞ্জার্স: এন্ডগেম அவெஞ்சர்ஸ்: எண்ட்கேம் అవెంజర్స్: ఎండ్ గేమ్ შურისმაძიებლები:  ენდშპილი avengers 4 avengers: infinity war part ii אנדגיים المنتقمون نهاية اللعبة avengers: endgame encore avengers: endgame', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-y-tam-linh', 'Pháp Y Tâm Linh', 'The Listener', 'https://phimimg.com/upload/vod/20250913-1/64a91a53bf0d53d60b910d13ce02aea1.jpg', 'https://phimimg.com/upload/vod/20250913-1/cc9d70d258ad783b9f85495eb2b87009.jpg', '<p>Pháp y Minh Xuyên, tay nghề cao siêu, đã phá giải vô số vụ án. Thế nhưng, vì tính cách cô độc và khép kín, mọi người đều biết rất ít về anh. Đúng lúc đó, một vụ án giết người hàng loạt nhiều năm chưa có lời giải bất ngờ có tiến展 mới. Phương thức gây án vô cùng đặc biệt khiến cảnh sát nhận định hung thủ phải tinh thông y học, nên gọi hắn là “bác sĩ giết người”. Nữ đội trưởng cảnh sát hình sự mới nhậm chức La Bút Tâm lập tức hướng sự nghi ngờ về phía Minh Xuyên, và bắt đầu theo dõi nhất cử nhất động của anh…</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Niệt Viễn","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Lư Phương Sinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Forensic Mind","The Listener","心灵法医"]', 1784690324375);
