INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tim-sat-da-hua-jai-sila', 'Con Tim Sắt Đá (Hua Jai Sila)', 'Con Tim Sắt Đá', 'https://phimimg.com/upload/vod/20250913-1/eeabf9c2d52dc9386edfe58622e72d15.jpg', 'https://phimimg.com/upload/vod/20250913-1/b446f6c111c668b00978138e6c641d12.jpg', '<p>Tor là một đứa con yêu quý của một người phụ nữ vốn là một tình nhân của một người đàn ông giàu có. Sau khi mẹ mình bị bỏ mặc đến chết, Tor bị buộc phải sống với gia đình của bố và chịu sự ngược đãi của mẹ kế. Tor tìm được sự an ủi và đồng cảm từ Mingta, cô gái nhà bên. Vào một đêm, trong lúc bị truy đuổi bởi người mẹ kế, Tor đã nhảy xuống sông khiến cho nhiều người cho rằng Tor đã chết. Tuy nhiên, Tor may mắn sống sót và sống dưới một cái tên mới là Sila. Nhiều năm sau, Tor trở thành một người giàu có và khét tiếng. Mang trong mình sự hận thù, Tor quay lại để trả thù cho những người đã làm tổn thương mẹ mình và bản thân. Mục đích chính của Sila chính là để trả thù những kẻ làm tổn thương anh lúc nhỏ, nhưng anh không ngờ được sẽ gặp lại người bạn duy nhất thời thơ ấu, Mingta. Tuy Mingta nhanh chóng nhận ra Sila chính là người bạn thân Tor đã khuất, nhưng anh luôn phủ nhận để có thể thực hiện được kế hoạch trả thù của mình.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thanapob Leeratanakajorn","avatar":""},{"name":"Nopjira Lerkkajornnamkul","avatar":""},{"name":"Siraphun Wattanajinda","avatar":""},{"name":"Ann Siriam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Man of Vengeance","Con Tim Sắt Đá"]', 1784690324375);
