INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-chi-mang', 'Đòn Chí Mạng', 'Deadly Sniper', 'https://phimimg.com/upload/vod/20250303-1/01599c5f3623e126723085db1fe1ffcc.jpg', 'https://phimimg.com/upload/vod/20250303-1/62869ab117c16bf487de5462c62dd42d.jpg', '<p>Tay bắn tỉa huyền thoại Tả Anh Kiệt, nhờ một trận chiến thành danh nhưng bị người khác vu oan mà phải vào tù. Trong lúc bị bắt giam anh ta dược Thẩm Tuyết-một nữ đặc công xinh đẹp giao cho một nhiệm vụ- ám sát chuyên gia về vi khuẩn Kitano Kiyoshi. Tả Anh Kiệt bị phản bội, bị truy đuổi bởi quân Nhật, trong tình thế nguy hiểm đó mọi âm mưu dần được hé lộ. Hận nước thù nhà, oan gia ngõ hẹp, một trận chiến chuẩn bị nổ ra</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"La Lập Quần","avatar":""},{"name":"Vương Thư Duẫn","avatar":""},{"name":"Yên Việt","avatar":""},{"name":"Thái Điền Trực Hành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狙杀","Deadly Sniper","致命狙杀"]', 1784690324375);
