INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('annabelle-ac-quy-tro-ve', 'Annabelle: Ác Quỷ Trở Về', 'Annabelle Comes Home', 'https://phimimg.com/upload/vod/20250907-1/23e7dad6492b95a956c5bdb37e61cf02.jpg', 'https://phimimg.com/upload/vod/20250907-1/b2e1abf8a0fc0b45b960714a3a50b37c.jpg', '<p>Sau những sự kiện xưa, vợ chồng pháp sư trừ tà Warren đưa Annabelle về nhà và niêm phong nó trong một căn phòng đặc biệt. Một ngày nọ trong lúc vợ chồng Warren rời khỏi nhà để thực hiện một nhiệm vụ bí ẩn, cơn ác mộng thực sự bắt đầu khi người bạn Daniela của Mary Ellen - bảo mẫu nhà Warren tò mò khám phá căn phòng đầy những món đồ quỷ ám và vô tình giải thoát cho Annabelle. Từ đó, Annabelle dẫn dắt các linh hồn khác có trong căn phòng cùng trỗi dậy, với mục tiêu mới nhằm vào chính Judy – cô con gái nhà Warren và bạn bè của cô bé</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mckenna Grace","avatar":""},{"name":"Madison Iseman","avatar":""},{"name":"Katie Sarife","avatar":""},{"name":"Michael Cimino","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Samara Lee","avatar":""},{"name":"Paul Dean","avatar":""},{"name":"Luca Luhan","avatar":""},{"name":"Alison White","avatar":""},{"name":"Stephen Blackehart","avatar":""},{"name":"Sade Katarina","avatar":""},{"name":"Kenzie Caplan","avatar":""},{"name":"Gary-7","avatar":""},{"name":"Natalia Safran","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Alexander Ward","avatar":""},{"name":"Steve Coult","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Annabelle 3 - La maison du Mal","Аннабель 3","Анабель приходить додому","애나벨 3","Проклятие Аннабель: Возвращение домой","安娜贝尔3:回家","Annabelle 3 : La maison du mal","Annabelle 3 - De Volta Para Casa","Annabelle 3 : Retour à la maison","Annabelle III: Comes Home (2019)","אנבל 3: חוזרת הביתה","Annabelle 3: Ác Quỷ Trở Về","Annabelle: 3 - Vuelve a Casa","ანაბელის წყევლა 3","Annabelle Comes Home"]', 1784690324375);
