INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('annabelle-ac-quy-tro-ve', 'Annabelle: Ác Quỷ Trở Về', 'Annabelle Comes Home', 'annabelle: ác quỷ trở về annabelle comes home mckenna grace madison iseman katie sarife michael cimino vera farmiga patrick wilson samara lee paul dean luca luhan alison white stephen blackehart sade katarina kenzie caplan gary-7 natalia safran douglas tait alexander ward steve coult annabelle 3 - la maison du mal аннабель 3 анабель приходить додому 애나벨 3 проклятие аннабель: возвращение домой 安娜贝尔3:回家 annabelle 3 : la maison du mal annabelle 3 - de volta para casa annabelle 3 : retour à la maison annabelle iii: comes home (2019) אנבל 3: חוזרת הביתה annabelle 3: ác quỷ trở về annabelle: 3 - vuelve a casa ანაბელის წყევლა 3 annabelle comes home', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-vang-hoang-kim-dong', 'Đôi Mắt Vàng (Hoàng Kim Đồng)', 'The Golden Eyes', 'https://phimimg.com/upload/vod/20250905-1/10035a53b6cab06a66e8fe957a73bb72.jpg', 'https://phimimg.com/upload/vod/20250905-1/8c09ea0769d373183d4ae0349cb992db.jpg', '<p>Trang Duệ, một nhân viên bình thường của một cửa hiệu cầm đồ, bị cướp giữa đêm khuya; trong quá trình đánh nhau với tên cướp thì bị một mảnh ngọc vỡ đánh bị thương, sau khi vết thương đã lành thì phát hiện ra mình đang đứng giữa ngã rẽ cuộc đời. Sau đó, Trang Duệ quyết định bước lên chuyến hành trình mạo hiểm của bản thân. Trong chuyến hành trình tìm ra sự thực của số mạng, Trang Duệ không ngừng phấn đấu, gần như đã bước lên đỉnh cao của cuộc đời. Sau khi trải qua đồ thạch, những chuyến phiêu lưu trong rừng, trận chiến sinh tử với Bành Phi và trải nghiệm tình cảm như có như không giữa nữ cảnh sát Miêu Phi Phi và nhà thiết kế trang sức đến từ Hong Kong Tần Huyên Băng. Bí mật về chuyến khảo cổ của 40 năm trước dần được hé lộ...</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nghệ Hưng","avatar":""},{"name":"Vương Tử Văn","avatar":""},{"name":"Vương Tường Quân","avatar":""},{"name":"Lý Lương Vỹ","avatar":""},{"name":"Trương Vệ Kiện","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黄金瞳","The Golden Eyes"]', 1784690324375);
