INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-than-cua-charlie-2019', 'Những Thiên Thần Của Charlie', 'Charlie''s Angels', 'https://phimimg.com/upload/vod/20250905-1/3e0b44b4d6076e906e04ce61eab144b6.jpg', 'https://phimimg.com/upload/vod/20250905-1/a05356e164e012dc66549cd01da83fb5.jpg', '<p>Những thiên thần của Charlie luôn sở hữu các kỹ năng điều tra và giữ bảo mật cho những khách hàng tư nhân; và Townsend đã mở rộng chi nhánh ra quốc tế với đội ngũ “nữ chiến binh” thông minh, gan dạ, được đào tạo bài bản bởi nhiều huấn luyện viên chuyên nghiệp trên toàn cầu. Khi được cảnh báo về một công nghệ có nguy cơ đe doạ đến toàn nhân loại, những thiên thần được triệu tập hành động, đánh cược mạng sống của để bảo vệ tất cả chúng ta...</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Naomi Scott","avatar":""},{"name":"Ella Balinska","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Jonathan Tucker","avatar":""},{"name":"Nat Faxon","avatar":""},{"name":"Chris Pang","avatar":""},{"name":"Luis Gerardo Méndez","avatar":""},{"name":"Noah Centineo","avatar":""},{"name":"David Schütter","avatar":""},{"name":"Hannah Hoekstra","avatar":""},{"name":"Jane Chirwa","avatar":""},{"name":"Emre Kentmenoğlu","avatar":""},{"name":"Murali","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Янголи Чарлі","3 Engel für Charlie - Eine neue Welt braucht neue Engel","Ангелы Чарли","Charlie''nin Melekleri","Những Thiên Thần Của Charlie","チャーリーズ・エンジェル","霹雳娇娃","新霹雳娇娃","Charlie''s Angels"]', 1784690324375);
