INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chu-chim-gian-du-2', 'Những Chú Chim Giận Dữ 2', 'The Angry Birds Movie 2', 'https://phimimg.com/upload/vod/20250905-1/f3332a965753e9826acaf4e2f0db58f4.jpg', 'https://phimimg.com/upload/vod/20250905-1/6ee057a25ed5064ee8eb6ec7044f1f32.jpg', '<p>Từ nhỏ đến lớn, Red luôn bị xem là kẻ lạc loài do bộ lông mày “độc và lạ”. Trong thế giới loài chim, chú quả xứng danh là “thánh nhọ”: đi học thì bị bạn bè cười nhạo, ra đường cũng bị trêu chọc, đến lúc ve vãn các cô nàng cũng chẳng xong. Chỉ đến khi đàn lợn xanh xuất hiện và âm mưu cướp sạch trứng chim, Red cùng đồng bọn mới có cơ hội trở thành “anh hùng”.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Phần Lan', 0, '[{"name":"Jason Sudeikis","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Leslie Jones","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Rachel Bloom","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Sterling K. Brown","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Dove Cameron","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"JoJo Siwa","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Ni","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Angry Birds 2 - Der Film","앵그리버