INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robert-the-bruce', 'Robert The Bruce', 'Robert The Bruce', 'https://phimimg.com/upload/vod/20250901-1/fc6a1e0775702efa4d1380df6e616c6b.jpg', 'https://phimimg.com/upload/vod/20250901-1/0894d97732164adc650324a33c5b1640.jpg', '<p>Năm 1306, vua Scotland Robert the Bruce trở thành một kẻ ngoài vòng pháp luật sau khi đất nước bị xâm lược. Nhưng trước khi có thể giải phóng mảnh đất thiêng liêng của mình, ông phải tìm lại ý chí chiến đấu và sống sót trước sự truy sát của những kẻ muốn lấy mạng ông để đổi lấy vàng của người Anh.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Angus Macfadyen","avatar":""},{"name":"Anna Hutchison","avatar":""},{"name":"Zach McGowan","avatar":""},{"name":"Gabriel Bateman","avatar":""},{"name":"Talitha Eliana Bateman","avatar":""},{"name":"Brandon Lessard","avatar":""},{"name":"Diarmaid Murtagh","avatar":""},{"name":"Emma Kenney","avatar":""},{"name":"Patrick Fugit","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Shane Coffey","avatar":""},{"name":"Daniel Portman","avatar":""},{"name":"Seoras Wallace","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Nick Farnell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Rei da Escócia","Robert the Bruce - König von Schottland","キングス・オブ・ブレイブ","Robert the Bruce"]', 1784690324375);
