INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-may-anh-chet-choc-may-anh-cua-quy-du', 'Chiếc Máy Ảnh Chết Chóc (Máy Ảnh Của Quỷ Dữ)', 'Polaroid', 'https://phimimg.com/upload/vod/20250901-1/4d4ce4dae2dfcec2786f34a23c665581.jpg', 'https://phimimg.com/upload/vod/20250901-1/5e1aba8e7138f8e7758cb2f8620ed363.jpg', '<p>Câu chuyện bắt đầu khi Brad - cô nữ sinh trung học đơn độc tìm được một chiếc máy ảnh Polaroid ở tiệm đồ cũ. Từ khi cô dùng đến nó, những điều quái dị bắt đầu lần lượt xảy ra. Quá khứ đen tối của chiếc máy ảnh dần được hé lộ và kinh hoàng hơn, những ai được chụp ảnh đều phải trải qua cái chết đau đớn.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kathryn Prescott","avatar":""},{"name":"Tyler Young","avatar":""},{"name":"Samantha Logan","avatar":""},{"name":"Keenan Tracey","avatar":""},{"name":"Priscilla Quintana","avatar":""},{"name":"Javier Botet","avatar":""},{"name":"Mitch Pileggi","avatar":""},{"name":"Davi Santos","avatar":""},{"name":"Katie Stevens","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Madelaine Petsch","avatar":""},{"name":"Erika Prevost","avatar":""},{"name":"Shauna MacDonald","avatar":""},{"name":"Rhys Bevan-John","avatar":""},{"name":"Emily Power","avatar":""},{"name":"Matthew Lumley","avatar":""},{"name":"Ri","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Пункт назначения. Смайл","Morte Instantânea","Polaroid"]', 1784690324375);
