INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-lung-phan-1', 'Linh Lung (Phần 1)', 'Ling Cage (Season 1)', 'https://phimimg.com/upload/vod/20250614-1/45008565aa28b148b273dfc35a07238c.jpg', 'https://phimimg.com/upload/vod/20250614-1/9bf6ac69f516acdc744b291be67a3c29.jpg', '<p>Trong tương lai, trái đất sẽ trải qua một thảm hoạ kinh hoàng. Những con người còn sống buộc phải nương náu trên ngọn hải đăng lơ lửng trên không, rồi phải đối mặt với những sinh vật tà ác trên mặt đất, cũng như những câu chuyện thiện ác trái ngược nhau, khó có thể phân biệt giữa đúng và sai.</p>', 'Hoàn Tất (16/16)', 15, 'hoathinh', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Sheng Feng","avatar":""},{"name":"Xin Teng","avatar":""},{"name":"Gu Jiangshan","avatar":""},{"name":"Ji Guanlin","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Xu Jiaqi","avatar":""},{"name":"Dafang Gong","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Duan Yixuan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["灵笼","Incarnation","Ling Long","Ling Long: Incarnation","[灵笼 第二季].Ling.Cage.2025","靈籠：INCARNATION","Spirit Cage: Incarnation","Ling Cage","Ling Cage: Incarnation","Spirit Cage","Linh Lung"]', 1784690324375);
