INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-10-phuong-hoang-bong-toi', 'X-Men 10: Phượng Hoàng Bóng Tối', 'Dark Phoenix', 'https://phimimg.com/upload/vod/20250817-1/908c9261f51f9c8d83b0cf9f134cb44f.jpg', 'https://phimimg.com/upload/vod/20250817-1/d040c88d778ec6b68963fa6d8dbb8a70.jpg', '<p>Một thập kỷ sau sự kiện trong phim X-Men: Cuộc chiến chống Apocalypse, nhóm X-Men đang theo đuổi những nhiệm vụ khó khăn hơn. Vào năm 1992, X-Men phản ứng với tín hiệu đau khổ từ tàu con thoi Endeavour, bị phá hủy nghiêm trọng bởi một năng lượng giống như ngọn lửa Mặt trời. Trong một lần trên vũ trụ, một cơn bão Mặt Trời đe dọa tính mạng của cả nhóm, khiến Jean Grey phải sử dụng sức mạnh để cứu mọi người. Nhưng, đồng thời, nó cũng làm cho Jean giải phóng một sức mạnh đáng gờm, Phượng hoàng Bóng tối.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sophie Turner","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Scott Shepherd","avatar":""},{"name":"Ato Essandoh","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Halston Sage","avatar":""},{"name":"Lamar Johnson","avatar":""},{"name":"Summer","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu