INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xmen-10-phuong-hoang-bong-toi', 'X-Men 10: Phượng Hoàng Bóng Tối', 'Dark Phoenix', 'x-men 10: phượng hoàng bóng tối dark phoenix sophie turner james mcavoy nicholas hoult tye sheridan michael fassbender alexandra shipp evan peters jessica chastain kodi smit-mcphee jennifer lawrence scott shepherd ato essandoh brian d''arcy james halston sage lamar johnson summer x战警7：黑凤凰 x-מן: הפניקס האפלה x-men: dark phoenix x-men: černý fénix x-men: čierny fénix gʻaroyib odamlar: qora feniks x-men - dark phoenix 엑스맨: 다크 피닉스 x-men fênix negra x-men 10: fénix oscura dị nhân 7: phượng hoàng bóng tối x-men 7 - dark phoenix dark phoenix', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('family-guy-phan-18', 'Family Guy (Phần 18)', 'Family Guy (Season 18)', 'https://phimimg.com/upload/vod/20250817-1/bb412924aed9fe49cc00d65f05e787b1.jpg', 'https://phimimg.com/upload/vod/20250817-1/3ebc55d5564ed644e6308f43f51e0458.jpg', '<p><span style="text-wrap-mode: wrap;">Bộ phim xoay quanh những cuộc phiêu lưu và hoạt động thường nhật của gia đình Griffin, bao gồm trụ cột gia đình Peter Griffin, một người đàn ông béo phì trung niên ngốc nghếch và vụng về làm việc trong nhà máy bia, Lois, nội trợ kiêm giáo viên dạy piano, vốn xuất thân từ gia đình tài phiệt Pewterschmidt, Meg, một cô bé 18 tuổi thường xuyên bị bắt nạt, Chris, cậu bé 15 tuổi thừa cân và cư xử ngốc nghếch giống Peter và Stewie, một bé trai 1 tuổi thông minh nhưng tinh ranh và đôi khi nham hiểm, cư xử theo cách của một người trưởng thành. Sống cùng gia đình là Brian, chú chó được nhân cách hóa, với nhiều thói quen của con người như hút thuốc, uống rượu martini, mặc dù về nhiều mặt vẫn được coi là thú cưng.</span></p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth MacFarlane","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Arif Zahir","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["გრიფინები","Keluarga Pria","مرد خانه","خانواده‌ دوست","쇼킹 패밀리","쇼킹패밀리","परिवारको केटा","Сім’янин","Ґріффіни","Family Guy"]', 1784690324375);
