INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('family-guy-phan-18', 'Family Guy (Phần 18)', 'Family Guy (Season 18)', 'family guy (phần 18) family guy (season 18) seth macfarlane alex borstein mila kunis seth green patrick warburton arif zahir გრიფინები keluarga pria مرد خانه خانواده‌ دوست 쇼킹 패밀리 쇼킹패밀리 परिवारको केटा сім’янин ґріффіни family guy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-phuong-hoang-phuong-dich', 'Truyền Thuyết Phượng Hoàng (Phượng Dịch)', 'Legend Of The Phoenix', 'https://phimimg.com/upload/vod/20250817-1/97324ae502143cc80c5e19e52b20b281.jpg', 'https://phimimg.com/upload/vod/20250817-1/b885f658ef861d6724d5bed0ab0f8192.jpg', '<p>Vào thời Đông Lương, có nàng Ngưng Chi xinh đẹp lương thiện. Một lần nàng theo đoàn kịch nhập cung biểu diễn chúc mừng Thọ Yến của Hoàng Thái Hậu, không ngờ rằng lại bị trưởng công chúa hãm hại, may mắn thay được đệ nhất mưu sĩ Ngụy Quảng kịp thời ra tay giúp đỡ, Ngưng Chi từ đây đối với chàng tương tư mãi không quên. Hai năm sau, Ngưng Chi ngoài ý muốn tiến cung làm cung nữ hầu cận của Hoàng Hậu. Với sự thông minh, lòng nhân hậu và sự dũng cảm Diệp Ngưng Chi đã chiến đấu vì tầng lớp nghèo khổ, chống lại cường quyền và trở thành giai thoại trong Hoàng Cung, khiến chính hoàng hậu cũng phải cảm động với tấm chân tình của nàng, đồng thời cũng hấp dẫn sự chú ý của vị Hoàng Đế cao cao tại thượng, nàng từ đó lâm vào tình thế nguy nan, nhất cử nhất động trong hậu cung đều trở nên vô cùng khó khăn. Cùng lúc ấy, Trưởng công chúa bắt đầu củng cố quyền lực, Diệp Ngưng Chi vô tình bị cuốn vào vòng xoay tranh quyền đoạt thế. May mắn thay Ngụy Quảng vẫn luôn kề bên nàng, cùng nàng vượt qua trùng trùng điệp điệp khó khăn, đẩy lùi Quốc nạn. Từ một cung nữ thân phận thấp hèn, Diệp Ngưng Chi đã trở thành Hiền Phi trí tuệ nhân hậu, danh tiếng lưu truyền đến ngàn đời sau. Cuối cùng nàng trở lại cuộc sống thường dân sống một cuộc đời viên mãn với tình yêu chân thành.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 6, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Hoằng San","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Tào Hi Văn","avatar":""},{"name":"Lê Diệu Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Legend of the Phoenix","凤弈"]', 1784690324375);
