INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-diet-6-van-menh-den-toi', 'Kẻ Hủy Diệt 6: Vận Mệnh Đen Tối', 'Terminator: Dark Fate', 'https://phimimg.com/upload/vod/20250806-1/960228c09bf9da70cc7c82ef4684f947.jpg', 'https://phimimg.com/upload/vod/20250806-1/7dbfd8c7e1b7473108ef77e9f43a1166.jpg', '<p>Phim là phần thứ sáu của thương hiệu phim Kẻ Hủy Diệt được phát hành. Không giống như các phần trước, bộ phim lần này được hậu thuẫn sản xuất bởi chính James Cameron sau khi đã giành lại được quyền chủ thương hiệu Terminator đã bán trước đó. Lần này bộ phim sẽ được chính ông viết kịch bản cùng với Charles Eglee, Josh Friedman, Goyer và Rhodes. Và trên hết phim sẽ được đạo diễn bởi Tim Miller.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Linda Hamilton","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Natalia Reyes","avatar":""},{"name":"Gabriel Luna","avatar":""},{"name":"Diego Boneta","avatar":""},{"name":"Ferran Fernández","avatar":""},{"name":"Tristán Ulloa","avatar":""},{"name":"Stephanie Gil","avatar":""},{"name":"Tomás Álvarez","avatar":""},{"name":"Tom Hopper","avatar":""},{"name":"Alicia Borrachero","avatar":""},{"name":"Enrique Arce","avatar":""},{"name":"Manuel Pacific","avatar":""},{"name":"Fraser James","avatar":""},{"name":"Pedro Rudolphi","avatar":""},{"name":"Di","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-