INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-vu-nu-quyen', 'Phi Vụ Nữ Quyền', 'Miss & Mrs. Cops', 'phi vụ nữ quyền miss & mrs. cops ra mi-ran lee sung-kyoung yoon sang-hyun sooyoung choi yeom hye-ran wi ha-jun joo woo-jae kang hong-suk kim do-wan jun suk-ho cho byeong-kyu lee jung-min ha jung-woo sung dong-il lee re ahn seong-bong baek seung-hwan so hee-jung kim min- 陀枪师奶x新扎师姐 霹雳娇锋 ガール・コップス：2019 陀槍師奶x新紮師姐 女警 걸캅스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tia-chop-phan-6', 'Người Hùng Tia Chớp (Phần 6)', 'The Flash (Season 6)', 'https://phimimg.com/upload/vod/20250729-1/e5f4b99b5d8a5e8825deb889e946cd77.jpg', 'https://phimimg.com/upload/vod/20250729-1/36b6c2be06baddd75e890504311cefff.jpg', '<p>Phim dựa theo một nhân vật của DC Comics, trong 1 thí nghiệm tại Starling City, anh chàng Barry đã vô tình bị ảnh hưởng bởi vụ nổ trong thí nghiệm khiến anh hôm mê bất tỉnh nhiều ngày trong bệnh viện. Khi tỉnh dậy, anh ta đã phát hiện ra rằng mình có khả năng đặc biệt đó là tăng tốc độ cơ thể và di chuyển siêu nhanh. Kể từ đây, huyền thoại về người anh hùng Flash bắt đầu.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Grant Gustin","avatar":""},{"name":"Candice Patton","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Danielle Nicolet","avatar":""},{"name":"Kayla Compton","avatar":""},{"name":"Brandon McKnight","avatar":""},{"name":"Jon Cor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["闪电侠 (格兰特·古斯汀)","The Flash (2014)","The Flash 2014","פלאש","플래시","The Flash"]', 1784690324375);
