INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-phong-doat-than-luc', 'Trảm Phong Đoạt Thần Lục', 'The Record of the Decapitation of the Gods', 'https://phimimg.com/upload/vod/20250725-1/b9dcc46cf2d566c2a06ef3359f038862.jpg', 'https://phimimg.com/upload/vod/20250725-1/9afb3e4ae5f4654a2c9be41c57e78a86.jpg', '<p>Giáo chủ Minh Thiên không hài lòng với kế hoạch sắp đặt của Thiên Giới, lén lút phái Vân Tiêu tiên tử vào trong Thiên Cung đánh cắp Thần Phổ, không ngờ Vân Tiêu lại bị Thiên Cung bắt giữ giam vào trong Mặc Đồn Sơn, giáo chủ lại hạ lệnh cho đệ tử Kim Linh đến núi Côn Lôn để hạ độc. Để cứu Vân Tiêu tiên tử, Thân Công Báo lợi dụng Độn Phong Bào để lọt vào trong Mặc Đồn Sơn, biết Vân Tiêu tiên tử có ý định hủy trời diệt đất, để ngăn chặn, Giang Tử Nha lọt vào trong Mặc Đồn Sơn để ngăn thảm họa xảy ra dưới nhân gian.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lữ Hi","avatar":""},{"name":"Tôn Tử Quân","avatar":""},{"name":"Hứa Huệ Cường","avatar":""},{"name":"Đỗ Dục Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["참장탈신록","斩将夺神录"]', 1784690324375);
