INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-phong-than-khuong-tu-nha-2019', 'Tân Phong Thần Khương Tử Nha', 'Legend Of Jiang Ziya', 'https://phimimg.com/upload/vod/20250725-1/f6cff97011923a38d3ea35e9a9ded5f8.jpg', 'https://phimimg.com/upload/vod/20250725-1/aa769a33ecebdab8a6b6732dc26d5093.jpg', '<p>Khương Tử Nha vì vi phạm tiên quy mà bị đày xuống hạ giới. Trong thân phận người phàm, Khương Tử Nha đã giúp đỡ thiếu nữ Thanh Loan đi tìm roi thần ở núi Phong Thần. Trong hành trình cứu lấy thôn Như Ý, Khương Tử Nha đã lĩnh ngộ được ý nghĩa của sự bác ái chốn nhân gian, chuộc tội thành công, lấy lại pháp lực đánh bại thần sông!</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Níu Tể Mộng","avatar":""},{"name":"Trần Hạo Dân","avatar":""},{"name":"Đỗ Dục Phong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Legend Of Jiang Ziya","Jiang Ziya","Novo Deus Jiang Zi Ya","Xin feng shen jiang zi ya","The Legend of Jiang Ziya","新封神姜子牙"]', 1784690324375);
