INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-hitrun-biet-doi-toc-do', 'Biệt Đội HIT&RUN (Biệt Đội Tốc Độ)', 'Hit And Run Squad', 'https://phimimg.com/upload/vod/20250715-1/fdab9ddfc1b31fb45fa9fafac39f88e6.jpg', 'https://phimimg.com/upload/vod/20250715-1/e8647e4872c5b4ec24ff1d1f2ff1cfdc.jpg', '<p>Bộ phim xoay quanh biệt đội chuyên cảnh sát chuyên điều tra những vụ án &quot;gây tai nạn rồi bỏ chạy&quot;. Trong Hit and Run Squad, Gong Hye Jin sẽ hoá thân thành hình tượng cô cảnh sát nghiêm túc Eun Si Yeon, bên cạnh đó cũng không thể thiếu một anh chàng &quot;át chủ bài&quot; Seo Min Jae do Ryu Jun Yeol thủ vai. Cả hai đã cùng nhau vây bắt gã doanh nhân Jung Jae Chul (Jo Jung Suk), ngoài sở thích kiếm tiền còn đam mê &quot;đánh võng lạng lách lên lề&quot; và chạy xe với vận tốc &quot;bàn thờ&quot;.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Gong Hyo-jin","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Cho Jung-seok","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Key","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Lee Sung-wook","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Park Ye-yeong","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Kim Go-eun","avatar":""},{"name":"Lim Sun-woo","avatar":""},{"name":"Yoo Yeon-soo","avatar":""},{"name":"Park Hyoung-soo","avatar":""},{"name":"Bae Yu-ram","avatar":""},{"name":"Lee Myeong-ja","avatar":""},{"name":"Na Chul","avatar":""},{"name":"Ahn S","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hit-and-Run Squad","뺑반","Опергруппа Авария","Esquadrão Justiceiro"]', 1784690324375);
