INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-trang-2-trum-a-phien', 'Bão Trắng 2: Trùm Á Phiện', 'The White Storm 2: Drug Lords', 'https://phimimg.com/upload/vod/20250725-1/d6b84ddc53b67e17a4d3f600589a932a.jpg', 'https://phimimg.com/upload/vod/20250725-1/a673b41a73da5b80011a288f8c104497.jpg', '<p>Trùm ma túy Địa Tàng đang dần bành trướng thế lực của mình ra quốc tế và khiến cho cả thế giới ngầm điêu đứng. Mặt khác, Dư Thuận Thiên, từ một đứa trẻ mang trong mình nỗi ám ảnh về người cha nghiện ma túy đã trở thành một kẻ đi săn trùm á phiện. Thuận Thiên mạnh tay chi trả một số tiền lớn cho kẻ lấy được mạng tên trùm ở Hồng Kông. Cuộc đi săn thanh tẩy thế giới ngầm liệu có thật sự thành công?</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Lâm Gia Hân","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Lâm Gia Đống","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["La tempesta bianca 2: i signori della droga","화이트스톰2 : 마약전쟁","The White Storm 2 – Drug Lords","La tormenta blanca: Los capos de la droga 2","ホワイト・ストーム：2019","扫毒2：天地对决","扫毒2:天地对决","掃毒2：天地對決","So duk 2: Tin dei duei kuet","화이트 스톰 2: 마약전쟁","화이트스톰 2: 마약전쟁","화이트스톰 2 : 마약전쟁","掃毒2 天地對決"]', 1784690324375);
