INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dora-va-thanh-pho-vang-mat-tich', 'Dora và Thành Phố Vàng Mất Tích', 'Dora and the Lost City of Gold', 'https://phimimg.com/upload/vod/20250724-1/38c7c4f7f744a45033015efb0ef66889.jpg', 'https://phimimg.com/upload/vod/20250724-1/67de94c9596dfc0763d98d4057720947.jpg', '<p>Biết bao năm tháng cùng bố mẹ khám phá rừng già chẳng ích gì cho Dora (Isabela Moner) khi đối diện với cuộc khám phá nguy hiểm nhất đời mình – trường Trung học. Luôn mang tâm thức nhà thám hiểm, không lâu sau, Dora dẫn dắt Boots (một con khỉ, bạn thân của cô), Diego (Jeffrey Wahlberg), một cư dân rừng già bí ẩn (Eugenio Derbez), và một nhóm thiếu niên ô hợp dấn thân vào cuộc thám hiểm như phim hành động để cứu bố mẹ cô (Eva Longoria, Michael Peña) và giải bí ẩn bất khả giải ẩn sau thành phố vàng bị lãng quên.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Úc', 0, '[{"name":"Isabela Merced","avatar":""},{"name":"Jeffrey Wahlberg","avatar":""},{"name":"Madeleine Madden","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Madelyn Miranda","avatar":""},{"name":"Malachi Barton","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Sasha Toro","avatar":""},{"name":"Marc Weiner","avatar":""},{"name":"Joey Vieira","avatar":""},{"name":"Pia Miller","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"Damien Garvey","avatar":""},{"name":"Anikka","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b239