INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hoa-cua-ac-ma', 'Bông Hoa của Ác Ma', 'The Flowers of Evil', 'https://phimimg.com/upload/vod/20250710-1/0a999a46d231551322d5d0720f418457.jpg', 'https://phimimg.com/upload/vod/20250710-1/0876e055356fa2c9fe08665d9fa28fce.jpg', '<p>Kasuga Takao, một thiếu niên yêu văn học, thích đọc sách. Saeki Nanako, là nàng thơ mà Kasuga thầm thích. Một ngày nọ, cậu quên cuốn sách yêu thích của mình ở lớp và quay lại để lấy nó. Trong lớp học, cậu vô tình thấy bộ đồng phục thể dục của Saeki để quên. Trên một xung động điên cuồng, cậu đánh cắp nó. Bây giờ mọi người đều biết “kẻ biến thái nào đó” đã lấy trộm đồng phục của Saeki, khiến Kasuga đang chết chìm trong tội lỗi và nhục nhã. Nhưng rồi cô gái kỳ dị, học sinh cá biệt của lớp, Nakamura, đã vô tình nhìn thấy cậu lấy đồng phục đó. Thay vì tố cáo, cô ấy lại muốn lập 1 giao kèo với Kagusa. Nakamura định làm gì với Kagusa? Liệu giao kèo đó là gì đây?</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kentaro Ito","avatar":""},{"name":"Tina Tamashiro","avatar":""},{"name":"Shiori Akita","avatar":""},{"name":"Marie Iitoyo","avatar":""},{"name":"Miho Kitagawa","avatar":""},{"name":"Takara Sakumoto","avatar":""},{"name":"Taketo Tanaka","avatar":""},{"name":"Wakana Matsumoto","avatar":""},{"name":"Asuka Kurosawa","avatar":""},{"name":"Kazuya Takahashi","avatar":""},{"name":"Sumie Sasaki","avatar":""},{"name":"Maki Sakai","avatar":""},{"name":"Shingo Tsurumi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aku no Hana","The Flowers of Evil","รักโรคจิต","Şeytanın Gülləri","惡の華"]', 1784690324375);
