INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-phieu-mieu-luc', 'Cửu Châu Phiêu Miểu Lục', 'Novoland: Eagle Flag', 'https://phimimg.com/upload/vod/20250711-1/086ea126d056e6db2224a66fb541f4da.jpg', 'https://phimimg.com/upload/vod/20250711-1/97bbf7d55a978b84b049278550cd3f8a.jpg', '<p>Thế tử bộ Bắc Lục Thanh Dương Lã Quy Trần đến Đông lục với thân phận chất tử có duyên hội ngộ với Đông lục thứ tử Cơ Dã kẻ luôn không nhận được sự yêu quý của gia tộc và công chúa Vũ nhiên người đang trên đường tị nạn cùng với ông nội mà kết thân bằng hữu. Họ cùng đồng hành tại học viện thái tử nhưng vì lý do thân phận mà trở thành đối tượng bị thách thức và khiêu chiến. Trong quá trình giúp đỡ và tương trợ lẫn nhau giữa họ tạo nên một tình bạn sâu sắc hơn bao giờ hết. Và công chúa Vũ Nhiên với sự hoạt bát của mình cũng dần khiến cho hai chàng thiếu niên thầm ngưỡng mộ, tình yêu từ đây cũng bắt đầu nảy mầm… Bá chủ Ly Quốc, Doanh Vô Ế lấy danh ngĩa phù Thiên Tử để mệnh lệnh chư hầu, Lã Quy Trần, Cơ Dã, Vũ Nhiên theo đại danh tướng Tức Diễn vì chính nghĩa mà quyết chiến ải Thương Dương, không ngờ rằng đằng sau cuộc chiến này còn ẩn dấu âm mưu to lớn. Trong nguy nan, những thiếu niên ấy không ngừng trưởng thành, họ kề sát bên nhau cùng chiến đấu lập nên kì tích để danh ngàn đời!</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 8, 2019, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Tống Tổ Nhi","avatar":""},{"name":"Trần Nhược Huyên","avatar":""},{"name":"Trương Gia Trạch","avatar":""},{"name":"Trương Phong Nghị","avatar":""},{"name":"Trương Chí Kiên","avatar":""},{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Lí Quang Khiết","avatar":""},{"name":"Vương Âu","avatar":""},{"name":"Trần Hầu Vũ","avatar":""},{"name":"Trương Trí Nghiêu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jiu Zhou Piao Miao Lu","九州縹緲録 宿命を継ぐ者","九州縹緲録（ひょうびょうろく）～宿命を継ぐ者～","九州缥缈录"]', 1784690324375);
