INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuu-chau-phieu-mieu-luc', 'Cửu Châu Phiêu Miểu Lục', 'Novoland: Eagle Flag', 'cửu châu phiêu miểu lục novoland: eagle flag lưu hạo nhiên tống tổ nhi trần nhược huyên trương gia trạch trương phong nghị trương chí kiên giang sơ ảnh lí quang khiết vương âu trần hầu vũ trương trí nghiêu jiu zhou piao miao lu 九州縹緲録 宿命を継ぐ者 九州縹緲録（ひょうびょうろく）～宿命を継ぐ者～ 九州缥缈录', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-va-dan-ngong', 'Cậu Bé Và Đàn Ngỗng', 'Spread Your Wings', 'https://phimimg.com/upload/vod/20250708-1/b7822f4ae9c36b6fcaf1defe53172231.jpg', 'https://phimimg.com/upload/vod/20250708-1/90bdbefd61d8db2af4e96a0f739f0039.jpg', '<p>Christian, một nhà khoa học đầy tầm nhìn, chuyên nghiên cứu về loài ngỗng hoang dã. Đối với cậu con trai tuổi teen mê trò chơi điện tử, việc phải trải qua kỳ nghỉ cùng cha mình giữa vùng hoang dã thực sự là một cơn ác mộng. Thế nhưng, hai cha con lại gắn bó với nhau qua một dự án điên rồ: cứu lấy một loài ngỗng đang có nguy cơ tuyệt chủng nhờ vào chiếc máy bay siêu nhẹ của Christian! Và rồi, một hành trình phi thường và đầy hiểm nguy bắt đầu...</p>', 'Full', 1, 'single', 'completed', 25, 2019, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Jean-Paul Rouve","avatar":""},{"name":"Louis Vazquez","avatar":""},{"name":"Mélanie Doutey","avatar":""},{"name":"Frédéric Saurel","avatar":""},{"name":"Lilou Fogli","avatar":""},{"name":"Grégori Baquet","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Philippe Magnan","avatar":""},{"name":"Ariane Pirié","avatar":""},{"name":"Christine Braconnier","avatar":""},{"name":"Cyril Necker","avatar":""},{"name":"Cédric Meusburger","avatar":""},{"name":"Murielle Huet des Aunay","avatar":""},{"name":"Jacques Germain","avatar":""},{"name":"Matthieu Warter","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015