INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-trang-that-thu-ke-phan-boi', 'Nhà Trắng Thất Thủ: Kẻ Phản Bội', 'Angel Has Fallen', 'https://phimimg.com/upload/vod/20250701-1/1ef5025a91c3e357065847b09ed0d6bd.jpg', 'https://phimimg.com/upload/vod/20250701-1/a19f0b0e8431c01315967c2a2928871a.jpg', '<p>Mike nhậm chức không lâu thì phái đoàn Mỹ bị tấn công và anh bị gán cho tội danh mưu sát Tổng thống. Từ đây, anh phải bắt đầu hành trình vạch trần thân phận kẻ phản bội Nhà trắng thật sự.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Frederick Schmidt","avatar":""},{"name":"Michael Landes","avatar":""},{"name":"Ori Pfeffer","avatar":""},{"name":"Rocci Williams","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Harry Ditson","avatar":""},{"name":"Linda John-Pierre","avatar":""},{"name":"Jasmine Hyde","avatar":""},{"name":"Ian Porter","avatar":""},{"name":"Laurel L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Presidente bajo fuego","Has Fallen 3","天使陷落","エンド・オブ・ステイツ","エンド・オブ・ステイツ：2019","Nhà Trắng Thất Thủ 3: Kẻ Phản Bội","白宮淪陷3：天使淪陷","ผ่ายุทธการ ดับแผนอหังการ์","Angel Has Fallen"]', 1784690324375);
