INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-sinh-tu', 'Chuyến Bay Sinh Tử', 'The Captain', 'https://phimimg.com/upload/vod/20250701-1/9298512a78aabc9ec8c7b6a187988741.jpg', 'https://phimimg.com/upload/vod/20250701-1/b8be071796495605502c3434c5040b5e.jpg', '<p>Dựa trên sự kiện có thật diễn ra vào năm 2018, phim kể về một chiếc máy bay bị vỡ kính buồng lái trong lúc ngày càng lên cao. Các phi công làm cách nào để đảm bảo mạng sống cho tất cả mọi người trên máy bay và hạ cánh an toàn trong lúc thời tiết cực kỳ xấu?</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hàm Dư","avatar":""},{"name":"Lý Hiện","avatar":""},{"name":"Lý Thấm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Captain","中國機長","Il Capitano","Terror En El Aire","China''s Captain","中国机长"]', 1784690324375);
