INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-uoc-nho-nhoi', 'Điều Ước Nhỏ Nhoi', 'The Last Wish', 'https://phimimg.com/upload/vod/20250628-1/4c4970626d18b9cc199e5e3e7a82f50d.jpg', 'https://phimimg.com/upload/vod/20250628-1/104db8ec6d4d9b51a64b20e68c3f1108.jpg', '<p>Bộ phim kể về Cao Viễn (do Bành Dục Sướng thủ vai), một học sinh trung học bất ngờ mắc bệnh teo cơ và được bác sĩ thông báo không còn sống được bao lâu. Trước khi chết, cậu quyết tâm hoàn thành một nguyện vọng cuối cùng – trở thành một người đàn ông đích thực! Hai người bạn thân bên cạnh là Từ Hạo (do Vương Đại Lục thủ vai) và Trương Chính Dương (do Ngụy Đại Huân thủ vai), sau khi biết chuyện, đã không tiếc bất cứ điều gì để giúp Cao Viễn thực hiện ước mơ cuối cùng. Họ cùng nhau trải qua một hành trình dở khóc dở cười, cảm động và tràn đầy tình huynh đệ.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Dục Sướng","avatar":""},{"name":"Vương Đại Lục","avatar":""},{"name":"Ngụy Đại Huân","avatar":""},{"name":"Phan Tử Phi","avatar":""},{"name":"Kha Thục Dĩnh","avatar":""},{"name":"Tằng Lê","avatar":""},{"name":"Lưu Tư Dao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wei Da De Yuan Wang","Petit souhait","伟大的愿望","The Last Wish","小小的愿望"]', 1784690324375);
