INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dieu-uoc-nho-nhoi', 'Điều Ước Nhỏ Nhoi', 'The Last Wish', 'điều ước nhỏ nhoi the last wish bành dục sướng vương đại lục ngụy đại huân phan tử phi kha thục dĩnh tằng lê lưu tư dao wei da de yuan wang petit souhait 伟大的愿望 the last wish 小小的愿望', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-thien-than-thu', 'Ngự Thiên Thần Thú', 'The Holy Beasts', 'https://phimimg.com/upload/vod/20250624-1/a946bd6d649485d91ff1b9adb5d11911.jpg', 'https://phimimg.com/upload/vod/20250624-1/6d8323d4e8d70d5965ac9a4b13d024b2.jpg', '<p>Thiên Sư Các từng gần như bị tiêu diệt toàn bộ trong một cuộc vây bắt hung thú thượng cổ Cùng Kỳ, chỉ còn truyền nhân Thiên Phóng (do Trương Tử Văn thủ vai) và Nhược Linh (do Vân Ca thủ vai), người mất trí nhớ, lưu lạc nhân gian mở tiệm Ngự Yêu Phường để sinh sống. Do trong thành liên tiếp xảy ra các vụ yêu quái làm hại người, Thiên Phóng phát hiện trên người Thái tử Hoài Xung (do Diệp Tiểu Khai thủ vai) có manh mối liên quan đến sự mất tích của sư phụ mình. Cả hai vì thế gia nhập đội bắt yêu, từng bước vạch trần sự thật ẩn giấu sau hàng loạt sự kiện kỳ lạ. Cốt truyện kết hợp giữa truyền thuyết dân gian và đấu tranh chốn cung đình, cuối cùng hướng đến mối nguy cơ cốt lõi: Cùng Kỳ một lần nữa giáng thế, đe dọa toàn cõi thiên hạ.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Băng Khiết","avatar":""},{"name":"Trương Tử Văn","avatar":""},{"name":"Lý Tử Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Imperial Beast","Imperial God Emperor","御天神兽"]', 1784690324375);
