INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-an-lich-su-bang-dang-kelly', 'Dấu Ấn Lịch Sử Băng Đảng Kelly', 'True History Of The Kelly Gang', 'https://phimimg.com/upload/vod/20250624-1/0d92b5688bca0f4a6bff745cf8046dda.jpg', 'https://phimimg.com/upload/vod/20250624-1/b5105cdfcb53c464dfbc66192ffa40a7.jpg', '<p>Dựa trên tiểu thuyết cùng tên nổi tiếng về tên cướp Ned Kelly vào những năm 1870. Với những ký ức ám ảnh mãi đeo đuổi hắn, Ned dần tiến vào con đường cướp bóc đầy điên cuồng và chẳng thể quay đầu.</p>', 'Full', 1, 'single', 'completed', 21, 2019, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"George MacKay","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Charlie Hunnam","avatar":""},{"name":"Orlando Schwerdt","avatar":""},{"name":"Earl Cave","avatar":""},{"name":"Sean Keenan","avatar":""},{"name":"Thomasin McKenzie","avatar":""},{"name":"Rory Collins","avatar":""},{"name":"Jacob Collins-Levy","avatar":""},{"name":"Marlon Williams","avatar":""},{"name":"Gentle Ben Corbett","avatar":""},{"name":"Claudia Karvan","avatar":""},{"name":"Harry Greenwood","avatar":""},{"name":"Josephine Blazi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The true History of the Kelly Gang","켈리 갱의 진실","Outlaws - Die wahre Geschichte der Kelly Gang","穿著裙子的凱利黑幫","Le Gang Kelly","Outlaws","La verdadera historia de la Banda de Kelly","True History of the Kelly Gang"]', 1784690324375);
