INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-an-lich-su-bang-dang-kelly', 'Dấu Ấn Lịch Sử Băng Đảng Kelly', 'True History Of The Kelly Gang', 'dấu ấn lịch sử băng đảng kelly true history of the kelly gang george mackay nicholas hoult essie davis russell crowe charlie hunnam orlando schwerdt earl cave sean keenan thomasin mckenzie rory collins jacob collins-levy marlon williams gentle ben corbett claudia karvan harry greenwood josephine blazi the true history of the kelly gang 켈리 갱의 진실 outlaws - die wahre geschichte der kelly gang 穿著裙子的凱利黑幫 le gang kelly outlaws la verdadera historia de la banda de kelly true history of the kelly gang', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-em-lau-that-lau', 'Bên Em Lâu Thật Lâu', 'Stand By Me', 'https://phimimg.com/upload/vod/20250624-1/2635d370fb87617b9c569a8defad321f.jpg', 'https://phimimg.com/upload/vod/20250624-1/947ee323d0402a8adc80923e519333d7.jpg', '<p>Tính cách khờ khạo và thật thà, cả tuổi thanh xuân của Triệu Cửu Bính đều gắn liền với Lương Bạc Hà. Hai người bạn thanh mai trúc mã cùng nhau lớn lên, mọi niềm vui và nỗi buồn đều có liên quan đến đối phương. Khi cả hai vào cùng một trường đại học, hàng loạt sự việc bất ngờ xảy ra khiến mối tình đầu của Bạc Hà bị một đàn anh điển trai cướp mất. Không thể nắm lấy, cũng chẳng đành lòng buông tay, Cửu Bính quyết định không im lặng nữa, mà phải dũng cảm giành lấy nữ thần trong lòng mình. Thế nhưng, trong mắt Bạc Hà, cậu vẫn chỉ là một chàng trai trẻ con, mãi không chịu lớn. Từ mối quan hệ lưng chừng giữa tình bạn và tình yêu, họ dần trở lại là bạn bè bình thường, từ thân thiết không rời trở nên xa cách. Không cam lòng, Cửu Bính vẫn kiên trì viết nên bản tình ca theo đuổi không có hồi kết, chỉ có sự đồng hành âm thầm kéo dài mãi mãi.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Ngạn Tuấn","avatar":""},{"name":"Phó Tinh","avatar":""},{"name":"Thạch Triệu Khánh","avatar":""},{"name":"Vương Yến Dư","avatar":""},{"name":"Lý Trác Nam","avatar":""},{"name":"Hồng Gia Lạc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["九餅、薄荷與夏天","Stand by Me","陪你很久很久"]', 178469