INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-voi-lua-phim-bo-2019', 'Đùa Với Lửa', 'Playing With Fire', 'https://phimimg.com/upload/vod/20250620-1/38c8c76b0df37b86d9fd83c30976180c.jpg', 'https://phimimg.com/upload/vod/20250620-1/ccdfe54b92ba5c447a73500ee0dcb08c.jpg', '<p>Ba người phụ nữ thành đạt — bao gồm một người mẹ và con gái của bà — cùng phải lòng một người đàn ông quyến rũ tại vùng Tam giác Cà phê của Colombia.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Yuri Vargas","avatar":""},{"name":"Jason Day","avatar":""},{"name":"Margarita Rosa de Francisco","avatar":""},{"name":"Carlos Ponce","avatar":""},{"name":"Laura Perico","avatar":""},{"name":"Alejandro Aguilar","avatar":""},{"name":"Tony Plana","avatar":""},{"name":"Marcelo Serrado","avatar":""},{"name":"Leticia Huijara","avatar":""},{"name":"Germán Quintero","avatar":""},{"name":"Luis Alberti","avatar":""},{"name":"Ricardo Vesga","avatar":""},{"name":"Álvaro Rodríguez","avatar":""},{"name":"Gaby Espino","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Playing with Fire","Jugar con fuego"]', 1784690324375);
