INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-huong-cang-2-truy-long', 'Trùm Hương Cảng 2: Truy Long', 'Chasing the Dragon II: Wild Wild Bunch', 'https://phimimg.com/upload/vod/20250619-1/3325cdf87666b4b4c36fb92899cbe217.jpg', 'https://phimimg.com/upload/vod/20250619-1/6ff8f2b12d57078330730ef605b16b2b.jpg', '<p>Bộ phim Trùm Hương Cảng 2: Truy Long lấy bối cảnh trước khi Hong Kong được trao trả cho Trung Quốc, tên tội phạm hung hãn gian xảo Long Chí Cường (Lương Gia Huy đóng) gây ra nhiều vụ án lớn, cảnh sát Hong Kong và Trung Quốc rất quan tâm đến tên tội phạm này, phái cảnh sát chìm Hong Kong Hà Thiên (Cổ Thiên Lạc đóng) trà trộn vào tập đoàn phạm tội của Long Chí Cường, chờ đợi thời cơ bắt giữ hắn. Trải qua nhiều lần thăm dò, cuối cùng Hà Thiên biết được mục tiêu bắt cóc tống tiền tiếp theo của Long Chí Cường là ai? Khi Hà Thiên tưởng rằng mình đã giành được sự tin tưởng của Long Chí Cường, âm thầm phối hợp với cảnh sát giăng thiên la địa võng thì hóa ra đây là cái bẫy.</p>', 'Full', 1, 'single', 'completed', 39, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lâm Gia Đống","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Khương Hạo Văn","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Lưu Hạo Long","avatar":""},{"name":"Huỳnh Nhật Hoa","avatar":""},{"name":"Viên Khiết Doanh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["追龙2","Chasing The Dragon II: Wild Wild Bunch","CHASING THE DRAGON 2: WILD WILD BUNCH","Chui lung II","Chasing the Dragon 2 : Master of Ransom","The Drug King","Chasing the dragon II","Chasing the dragon II : wild wild bunch","추룡 2: 적왕","追龍II：賊王"]', 1784690324375);
