INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chu-cho-hoang-gia', 'Những Chú Chó Hoàng Gia', 'The Queen''s Corgi', 'https://phimimg.com/upload/vod/20250610-1/d08c416f0e1efc83efb69629e49a1a15.jpg', 'https://phimimg.com/upload/vod/20250610-1/c4fe23552c0f690ae4c9ad0a89228a66.jpg', '<p>Cuộc phiêu lưu của Rex, chú chó corgi đáng yêu nhất nước Anh. Trong một lần vô tình, Rex bị lưu lạc ra thế giới bên ngoài nơi mà có rất nhiều thử thách cũng như các nguy hiểm rình rập. Để trở về bên cạnh Nữ Hoàng, Rex đã phải trải qua những thử thách và ở đó Rex đã tìm ra được tình yêu cũng như tìm được chính bản thân mình.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2019, 'Lồng Tiếng', 'FHD', 'Bỉ', 0, '[{"name":"Rusty Shackleford","avatar":""},{"name":"Jo Wyatt","avatar":""},{"name":"Mari Devon","avatar":""},{"name":"Dino Andrade","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Leo Barakat","avatar":""},{"name":"Nicole Moorea Sherman","avatar":""},{"name":"Kirk Thornton","avatar":""},{"name":"Madison Brown","avatar":""},{"name":"Camila Rhodes","avatar":""},{"name":"Rick Zieff","avatar":""},{"name":"Dave B. Mitchell","avatar":""},{"name":"Elizabeth Dean","avatar":""},{"name":"Jamal Fahim","avatar":""},{"name":"David A. Alano","avatar":""},{"name":"Daniel Wolfe","avatar":""},{"name":"Lani Minella","avatar":""},{"name":"Lin","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Corgi","퀸즈 코기","Kuninganna Corgi","ロイヤルコーギー　レッ