INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-abigail', 'Cuộc Phiêu Lưu Của Abigail', 'Abigail', 'https://phimimg.com/upload/vod/20250610-1/45d5c2c8ef13e209661fea6493118f3a.jpg', 'https://phimimg.com/upload/vod/20250610-1/d30612adb8de1dba2689a8306e40b543.jpg', '<p>Cô gái trẻ Abigail sống ở môt thành phố có biên giới bị đóng cửa rất nhiều năm vì một căn bệnh bí ẩn. Cha của cô là những người nhiễm bệnh đầu tiên và đã bị bắt đi khi cô mới sáu tuổi. Trưởng thành, cô quyết định tìm kiếm tung tích của cha và phát hiện ra thành phố này không đơn giản như cô nghĩ.</p>', 'Full', 1, 'single', 'completed', 29, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Nga', 0, '[{"name":"Tinatin Dalakishvili","avatar":""},{"name":"Rinal Mukhametov","avatar":""},{"name":"Artyom Tkachenko","avatar":""},{"name":"Ravshana Kurkova","avatar":""},{"name":"Kseniya Kutepova","avatar":""},{"name":"Gleb Bochkov","avatar":""},{"name":"Olivier Siou","avatar":""},{"name":"Sesil Plezhe","avatar":""},{"name":"Nikita Dyuvbanov","avatar":""},{"name":"Nikita Tarasov","avatar":""},{"name":"Petar Zekavica","avatar":""},{"name":"Aleksandra Serebryakova","avatar":""},{"name":"Marta Timofeeva","avatar":""},{"name":"Sergey Goroshko","avatar":""},{"name":"Dmitry Lug","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Эбигейл","Ебігейл","Abigail and the Forbidden City","Magical Adventures in the Forbidden City","魔域戰記","Abigail"]', 1784