INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-thien-nga-vuong-quoc-am-nhac', 'Công Chúa Thiên Nga: Vương Quốc Âm Nhạc', 'The Swan Princess: Kingdom of Music', 'https://phimimg.com/upload/vod/20250610-1/3da5f22319aba10e7671c103a5d2ebee.jpg', 'https://phimimg.com/upload/vod/20250610-1/ceba6554759e90cce0a653d39edc1fe2.jpg', '<p>Công chúa Odette tổ chức một cuộc thi âm nhạc để chúc mừng sinh nhật Công chúa Alise. Sự xuất hiện của hoàng tử Li xứ Cathay làm Alise xao xuyến; cùng lúc đó Mei Li, em gái Li lại muốn Odette giúp sức cứu Chen, một người bị nguyền rủa phải sống dưới lốt rồng. Câu chuyện tình yêu và âm nhạc sẽ kết thúc như thế nào?</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nina Herzog","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Alexandre Chen","avatar":""},{"name":"Joseph Medrano","avatar":""},{"name":"Clayton James","avatar":""},{"name":"Jennifer Miller","avatar":""},{"name":"Doug Stone","avatar":""},{"name":"Gardner Jaas","avatar":""},{"name":"Christine Lakin","avatar":""},{"name":"Bleau Essen","avatar":""},{"name":"Grant Durazzo","avatar":""},{"name":"Stephanie Sheh","avatar":""},{"name":"Brian Nissen","avatar":""},{"name":"Dick Stanners","avatar":""},{"name":"George Ju","avatar":""},{"name":"Ben King","avatar":""},{"name":"Lynna Yee","avatar":""},{"name":"Francis Huang","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{