INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-hoa-thu-nguyet', 'Xuân Hoa Thu Nguyệt', 'Love Better Than Immortality', 'https://phimimg.com/upload/vod/20250608-1/3ed575c506fa029ad234a5e53abd50da.jpg', 'https://phimimg.com/upload/vod/20250608-1/b318dc0a4802284e0c453e10e89ca8b0.jpg', '<p>Bộ phim xoay quanh cô gái hiện đại cổ linh, tinh quái Lôi Lôi (Triệu Lộ Tư). Lôi Lôi mê xuyên không nên đã tiêu tốn số tiền không nhỏ để về thời cổ đại, nơi có các đại hiệp, thiếu hiệp; các tiểu thư yêu kiều. Cô bị mắc vào một đoạn tình cảm rối ren trong thời cuộc phân tranh giữa hai phe chính - tà. Câu chuyện tình yêu lãng mạn nhưng không kém phần phức tạp, dở khóc dở cười cũng từ đó bắt đầu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2019, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hồng Dương","avatar":""},{"name":"Triệu Lộ Tư","avatar":""},{"name":"Ngô Tuấn Huy","avatar":""},{"name":"Tạ Bân Bân","avatar":""},{"name":"Trình Mỹ Dung","avatar":""},{"name":"Tưởng Hân","avatar":""},{"name":"Trương Kỳ","avatar":""},{"name":"Lưu Nãi Di","avatar":""},{"name":"Trương Dật Kiện","avatar":""},{"name":"Vương Nhất Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Love Better Than Immortality","天雷一部之春花秋月"]', 1784690324375);
