INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-he-ma-quai-2', 'Gã Hề Ma Quái 2', 'It Chapter Two', 'https://phimimg.com/upload/vod/20250605-1/9ea45824e526ed40682d52b6296ee1ed.jpg', 'https://phimimg.com/upload/vod/20250605-1/58ba19da7b01894d68337d7ad1d2f28a.jpg', '<p>It Chapter Two (Gã Hề Ma Quái 2) vẫn là câu chuyện về những cô cậu bé của nhóm The Losers Club, lúc này đã trưởng thành và đối mặt với vô số vấn đề trong cuộc sống. Chưa dừng lại ở đó, ám ảnh ma hề Pennywise cứ 27 năm lại xuất hiện một lần tại thị trấn Derry buộc 7 cô cậu bé ngày nào phải tiếp tục cuốn vào cuộc chạm trán tiếp theo giữa hai bên thiện và ác. &nbsp;Mặc dù có thể cả nhóm đã trưởng thành và khôn ngoan hơn, cuộc chiến của họ với Pennywise vẫn còn đó những hậu quả bất ngờ, thậm chí khiến một số thành viên phải trải qua đau đớn đến tột cùng.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Bill Skarsgård","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Isaiah Mustafa","avatar":""},{"name":"Jay Ryan","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Andy Bean","avatar":""},{"name":"Teach Grant","avatar":""},{"name":"Jaeden Martell","avatar":""},{"name":"Sophia Lillis","avatar":""},{"name":"Finn Wolfhard","avatar":""},{"name":"Chosen Jacobs","avatar":""},{"name":"Wyatt Oleff","avatar":""},{"name":"Jeremy Ray Taylor","avatar":""},{"name":"Jack Dylan Grazer","avatar":""},{"name":"Nicholas Hamilton","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["It - A Coisa: Capítulo 2","ES - Kapitel Zwei","Det: Kapitel 2","Ça : Chapitre 2","ÇA : Chapitre Deux","זה: פרק 2","آن: بخش ۲","IT イット THE END \"それ\"が見えたら、終わり。","小丑回魂2","It: Capítulo 2","IT Capítulo 2","อิท","It: Chapter Two","It Chapter Two"]', 1784690324375);
