INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-cuu-hoa-chicago-2019', 'Đội Cứu Hoả Chicago (Phần 8)', 'Chicago Fire (Season 8)', 'đội cứu hoả chicago (phần 8) chicago fire (season 8) taylor kinney david eigenberg joe miñoso christian stolte miranda rae mayo daniel kyri hanako greensmith jocelyn hudon jake lockett dermot mulroney chicago fire : caserne 51 风城烈火 芝加哥烈火群英 chicago fire שיקגו fire שיקגו פייר آتش‌نشانی شیکاگو чикаго в огне one chicago chicago fire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-12-canh-gio', 'Trường An 12 Canh Giờ', 'The Longest Day in Chang''an', 'https://phimimg.com/upload/vod/20250602-1/bcd2da1fcdd68781710c99736dc3ab60.jpg', 'https://phimimg.com/upload/vod/20250602-1/47368ed4eff0e9e5ef9de2941f76f97a.jpg', '<p>Lấy bối cảnh vào thời Thịnh Đường, vào đêm trước lễ Thượng Nguyên (tức Tết Nguyên Tiêu), Trường An – kinh đô phồn hoa – rơi vào tình trạng nguy hiểm khi một nhóm sát thủ từ phương Bắc âm mưu gây ra cuộc tấn công khủng bố quy mô lớn. Để ngăn chặn thảm họa, Trương Tiểu Kính - một tử tù từng là quan chức an ninh, được phóng thích để thực hiện nhiệm vụ đặc biệt. Anh hợp tác cùng Lý Tất , một quan chức trẻ tuổi của Tĩnh An Tư, nhằm truy tìm và ngăn chặn âm mưu trong vòng 12 canh giờ (tương đương 24 giờ). Trong quá trình điều tra, họ phát hiện ra không chỉ có mối đe dọa từ bên ngoài, mà còn có những kẻ phản bội ngay trong nội bộ. Cuộc chạy đua với thời gian bắt đầu, với mục tiêu bảo vệ sự an toàn của hàng triệu dân chúng trong thành Trường An.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lôi Giai Âm","avatar":""},{"name":"Dịch Dương Thiên Tỉ","avatar":""},{"name":"Châu Nhất Vi","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Hàn Đồng Quân","avatar":""},{"name":"Lý Ngạn Tuấn","avatar":""},{"name":"Nguyên Bảo","avatar":""},{"name":"Vương Hựu Quân","avatar":""},{"name":"Từ Dương","avatar":""},{"name":"Triệu Sở Hàn","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["长安十二时辰","장안12시진","長安十二時辰","The Longest Day In Chang''an","The Longest Day in Chang an"]', 1784690324375);
