INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-an-12-canh-gio', 'Trường An 12 Canh Giờ', 'The Longest Day in Chang''an', 'trường an 12 canh giờ the longest day in chang''an lôi giai âm dịch dương thiên tỉ châu nhất vi nhiếp viễn hàn đồng quân lý ngạn tuấn nguyên bảo vương hựu quân từ dương triệu sở hàn 长安十二时辰 장안12시진 長安十二時辰 the longest day in chang''an the longest day in chang an', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-choi-the-nao-hangout-with-yoo', 'Bạn Chơi Thế Nào? (Hangout With Yoo)', 'How Do You Play?', 'https://phimimg.com/upload/vod/20250601-1/a0ec6ee5fa19b3429600a1b2df149c77.jpg', 'https://phimimg.com/upload/vod/20250601-1/92489d78abb39f089c34646515a4e137.jpg', '<p>Sau thành công của tập phát sóng thử nghiệm, Giám đốc sản xuất Kim Tae Ho và Yoo Jae-suk tiếp tục sử dụng hình thức relay (tiếp nối) ở nhiều lĩnh vực khác nhau như sáng tác âm nhạc. Chương trình sau đó được mở rộng với việc Kim Tae Ho hướng dẫn Yoo Jae-suk học các kỹ năng mới, chẳng hạn như chơi trống, hát nhạc trot, cùng với sự giúp đỡ của các chuyên gia. Đồng thời, Yoo Jae-suk còn được khám phá những lĩnh vực hoàn toàn mới mà anh chưa từng thử sức trước đó.</p>', 'Tập 215', 999, 'tvshows', 'ongoing', 8, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae-suk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["How Do You Play?","How Do You Play","閑著幹嘛呢","闲着干嘛呢","玩甚麼好呢","Nolmyeon Mwohani","Зависни с Ю","Hangout with Yoo","놀면 뭐하니?"]', 1784690324375);
