INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-hoa-anh-hung', 'Liệt Hoả Anh Hùng', 'The Bravest', 'https://phimimg.com/upload/vod/20250527-1/0ce671d8a42a2fd5f85c62725a051bf2.jpg', 'https://phimimg.com/upload/vod/20250527-1/32cd72d5453d1c91fa6a6e5356f972cf.jpg', '<p>Chuyển thể từ báo cáo văn học, thuộc dự án vinh danh những &quot;anh hùng lửa&quot; của đất nước tỉ dân. Với dàn diễn viên nổi tiếng, phim nhanh chóng chiếm lĩnh phòng vé ngay từ ngày đầu công chiếu.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Đỗ Giang","avatar":""},{"name":"Dương Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lie huo ying xiong","A Redenção","The Bravest","The Bravest - Kampf den Flammen","Odważna decyzja","A legbátrabb","烈火英雄"]', 1784690324375);
