INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-ban-than-2019', 'Yêu Nhầm Bạn Thân', 'Friend Zone', 'https://phimimg.com/upload/vod/20250526-1/0232a07c71ec868ed3623c3ab9952b16.jpg', 'https://phimimg.com/upload/vod/20250526-1/26d84363a8c7eaa5779527cfca96d833.jpg', '<p>Yêu Nhầm Bạn Thân xoay quanh mối tình đơn phương của Palm – một tiếp viên hàng không. Ngay từ lúc còn ngồi trên ghế nhà trường, anh đã thầm yêu Gink, nhưng sau đó, quyết định giữ tình bạn thân thiết. 10 năm trôi qua, cả hai trưởng thành và vẫn giữ mối quan hệ bạn thân khác giới, những khi bên nào có trục trặc với người yêu, thì đều có bên kia xuất hiện làm “phao cứu sinh”.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Naphat Siangsomboon","avatar":""},{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"Jason Young","avatar":""},{"name":"Benjamin Joseph Varney","avatar":""},{"name":"Nathasit Kotimanuswanich","avatar":""},{"name":"Sukhapat Lohwacharin","avatar":""},{"name":"Chertsak Pratumsrisakhon","avatar":""},{"name":"Panasya Sawettaporn","avatar":""},{"name":"Panissara Arayaskul","avatar":""},{"name":"Joseph Ronald Zamudio","avatar":""},{"name":"Paweesuda Chanket","avatar":""},{"name":"Thanaporn Wag","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["友情以上","Friend Zone ระวัง..สิ้นสุดทางเพื่อน"]', 1784690324375);
