INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-thoi-tiet', 'Đứa Con Của Thời Tiết', 'Weathering with You', 'https://phimimg.com/upload/vod/20250526-1/6340a02d0d46cde962184319cd56723b.jpg', 'https://phimimg.com/upload/vod/20250526-1/00b744219355b28bd08540de7433e696.jpg', '<p>Xoay quanh cuộc sống của cậu thiếu niên Morishima Hodaka, ở độ tuổi “trẻ trâu” 16 mùa bánh trưng, sau khi đã quá chán cuộc sống tại vùng đảo xa nên cậu có ý định lên thành phố Tokyo để tìm kiếm thử thách của riêng mình. Thế nhưng, mọi việc dần trở nên không giống như cậu mong tưởng, cuộc sống trở nên túng thiếu giữa thành thị đắt đỏ để rồi cậu co mình lại cùn nỗi cô đơn nhớ nhà. Để có tiền trang trải, Hodaka viết bài cho một tờ tạp chí chuyên tin tức về những hiện tượng lạ thường. &nbsp;Nhưng đúng lúc mới đi làm thì trời cứ mưa mãi khiến cuộc sống xung quanh trở nên ảm đạm và càng não nề. Và rồi như một định mệnh ông trời sắp đặt, trong một con hẻm của thành phố đông đúc và bận rộn, Hodaka gặp một cô gái trẻ tên Hina Amano, một cô gái có khả năng kỳ lạ có thể làm ánh sáng trên bầu trời bừng sáng thông qua những lời nguyện cầu đặc biệt.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Kotaro Daigo","avatar":""},{"name":"Nana Mori","avatar":""},{"name":"Tsubasa Honda","avatar":""},{"name":"Sakura Kiryu","avatar":""},{"name":"Sei Hiraizumi","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Chieko Baisho","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Sumi Shimamoto","avatar":""},{"name":"香月萌衣","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Mone Kamishirai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Tenki no ko","Weather Child","Child of Weather","आपके साथ अपक्षय","天気の子","Дитя погоды","El tiempo contigo","Weathering with You - Das Mädchen, das die Sonne berührte","天气之子","O Tempo com Você","Tenki no Ko","Les Enfants du Temps","Tenki No Ko","Weathering With You","天氣之子","Weathering with You - Das Mädchen das die Sonne berührte","天気の子：2019","Weathering with You - La ragazza del tempo","Ilmojen lapset","Weathering with You","Hava Durumu Çocuğu","Gökyüzü Çocuğu"]', 1784690324376);
