INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-con-cua-thoi-tiet', 'Đứa Con Của Thời Tiết', 'Weathering with You', 'đứa con của thời tiết weathering with you kotaro daigo nana mori tsubasa honda sakura kiryu sei hiraizumi yuki kaji chieko baisho shun oguri sumi shimamoto 香月萌衣 ryohei kimura kana hanazawa ayane sakura kana ichinose masako nozawa hidekatsu shibata ryunosuke kamiki mone kamishirai tenki no ko weather child child of weather आपके साथ अपक्षय 天気の子 дитя погоды el tiempo contigo weathering with you - das mädchen, das die sonne berührte 天气之子 o tempo com você tenki no ko les enfants du temps tenki no ko weathering with you 天氣之子 weathering with you - das mädchen das die sonne berührte 天気の子：2019 weathering with you - la ragazza del tempo ilmojen lapset weathering with you hava durumu çocuğu gökyüzü çocuğu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-anh-trang', 'Định Mệnh Ánh Trăng', 'Destined to the Moon', 'https://phimimg.com/upload/vod/20250525-1/7db115483888463f9402fd7aa27fe78b.jpg', 'https://phimimg.com/upload/vod/20250525-1/e7caad163654a3b587d7527606dcf62f.jpg', '<p>Phim là câu chuyện hài hước về hành trình xuyên không của hai cô gái có tính cách trái ngược nhau hoàn toàn là Duang Kaew, cô Công chúa sống trong cung điện thời Ayutthaya và nữ trung tá của cục phòng chống tội phạm Opal. Vào một đêm định mệnh lúc trăng tròn, trong lúc sử dụng chiếc vòng cổ xưa năm nghìn năm để chữa bệnh cho mẹ, không ngờ Duang Kaew lại bị xuyên không đến thời điểm hiện tại. Linh hồn của Kaew nhập vào thân xác của Opal còn linh hồn của nữ cảnh sát bị hoán đổi với Kaew, trở về quá khứ. Sau đó, Kaew gặp được anh chàng đồng nghiệp Pipop của Opal và đem lòng yêu mến sự mạnh mẽ và điển trai của chàng, còn Opal đụng độ với thái y hiền lành, tốt bụng Luang Osotwonwet. Câu chuyện rồi sẽ đi về đâu, liệu hai người có thể trở về như bình thường hay cứ mãi sống với cuộc đời mới?</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pichukkana Wongsarattanasin","avatar":""},{"name":"Puen Khanin Chobpradit","avatar":""},{"name":"Thakrit Tawanpong","avatar":""},{"name":"Khunnarong Pratesrat","avatar":""},{"name":"Kiatkamol Lata","avatar":""},{"name":"Nutwara Vongvasana","avatar":""},{"name":"Jack Chakapan Chan-O","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Likhit Haeng Jan","Moon''s Destiny","ลิขิตแห่งจันทร์"]', 1784690324376);
