INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thanh-dia-nguc', 'Âm Thanh Địa Ngục', 'Maturot Lohgan', 'https://phimimg.com/upload/vod/20250525-1/f9fde30239bb9841c35ab881ed6ca437.jpg', 'https://phimimg.com/upload/vod/20250525-1/811873d1a00797bbf8c13f3b7121c802.jpg', '<p>Một tên cướp, một đóa hoa thiên đường, một tình yêu chỉ đến một lần trong đời. Khoảnh khắc ngọt ngào nhất trong cuộc đời hắn chính là: cô ấy. Giá như hắn không phải là Suer Pa, tên cướp bị truy nã vùng Praiwaree… Và cô không phải là M.L. Petch Nampeung, tiểu thư quý tộc – vị hôn thê của kẻ thù không đội trời chung với hắn – viên cảnh sát trưởng. Thì có lẽ hắn đã không bắt cóc cô, giam giữ cô trong trại của bọn cướp. Giá như số phận nhân từ hơn, để họ gặp nhau muộn hơn một chút… Khi ấy, hắn có thể ngẩng cao đầu mà nói rằng Petch Nampeung là người phụ nữ của hắn. Hắn có thể yêu thương và chăm sóc cô, thay vì buộc cô phải sống một cuộc đời đầy tủi nhục. Cô chỉ mới 17 tuổi và không muốn trở thành vợ của bất kỳ ai. Cô từng thề rằng nếu hắn ép buộc cô, cô sẽ hận hắn suốt đời. Thế nhưng, khi thời khắc chia ly đến, cô không thể kìm nén những giọt nước mắt. Phải chăng chuyện tình giữa tên cướp vùng Praiwaree và đóa hoa thiên đường sẽ thật sự kết thúc như vậy sao?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pattaradet Sa-nguankwamdee","avatar":""},{"name":"Mookda Narinrak","avatar":""},{"name":"Yotsawat Tawapee","avatar":""},{"name":"Weerachai Hattakovit","avatar":""},{"name":"Annie Sararat Sajew","avatar":""},{"name":"Phantira Pipityakorn","avatar":""},{"name":"Trin Settachoke","avatar":""},{"name":"Cherlisa Seriwibunkit","avatar":""},{"name":"Pympan Chalayanacupt","avatar":""},{"name":"Thanayong Wongtrakul","avatar":""},{"name":"Phutharit Prombandal","avatar":""},{"name":"Sa Anisa Nugraha","avatar":""},{"name":"Par","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suparburoot Jorm Jon 2: Maturot Lohgan","Gentleman Thief Series 2","สุภาพบุรุษจอมโจร - มธุรสโลกันตร์"]', 1784690324376);
