INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-thanh-dia-nguc', 'Âm Thanh Địa Ngục', 'Maturot Lohgan', 'âm thanh địa ngục maturot lohgan pattaradet sa-nguankwamdee mookda narinrak yotsawat tawapee weerachai hattakovit annie sararat sajew phantira pipityakorn trin settachoke cherlisa seriwibunkit pympan chalayanacupt thanayong wongtrakul phutharit prombandal sa anisa nugraha par suparburoot jorm jon 2: maturot lohgan gentleman thief series 2 สุภาพบุรุษจอมโจร - มธุรสโลกันตร์', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-du-nien-phan-1', 'Khánh Dư Niên (Phần 1)', 'Joy Of Life (Season 1)', 'https://phimimg.com/upload/vod/20240515-1/993a36c0f70be4c22606b7c579781e6f.jpg', 'https://phimimg.com/upload/vod/20240515-1/3e20c1557d928528553e7823d45c3ee1.jpg', '<p>Khánh Dư Niên được chuyển thể từ tiểu thuyết cùng tên của tác giả Miêu Nị. Lấy bối cảnh những năm cuối nhà Đông Tấn, tướng quốc công Lưu Dụ soán vị Thành Vũ Đế. Giữa trận huyết chiến, chỉ có đứa bé do hoàng phi Diệp Khinh Minh sinh ra may mắn thoát nạn. Thượng thư Phạm Kiến đem đứa nhỏ về nuôi dưỡng, đặt tên là Phạm Nhàn. Phạm Nhàn năm 18 tuổi, bắt đầu bị cuốn vào cuộc tranh giành mưu quyền trong cung. Đồng thời cũng trở thành vị quan tài ba giải quyết nhiều vụ án nan giải. Phạm Nhàn một lòng trung thành với Vũ Đế, sau lại biết y chính là kẻ hại chết cha mẹ mình. Chân tướng sáng tỏ, Phạm Nhàn vì cha mẹ quyết tâm báo thù, cũng vì thương xót sinh linh trăm họ, chống lại chính sách tàn bạo của Vũ Đế. Cuối cùng thành công khiến Vũ Đế thoái vị, ngôi vị truyền cho Tam hoàng tử. Triều đình trong ngoài khôi phục, dân an thái bình, Phạm Nhàn đem theo người thương yêu ẩn cư bên bờ biển.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 9, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhược Quân","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Trần Đạo Minh","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Vu Vinh Quang","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Lý Thần","avatar":""},{"name":"Tiêu Chiến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324376);
