INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lam-xung-2-da-tru-lam', 'Anh Hùng Lâm Xung 2 : Dã Trư Lâm', 'The Panther Head Hero 2 : Wild Boar Forest', 'https://phimimg.com/upload/vod/20250522-1/6304d370259e5683e26ec6e30a64dbe9.jpg', 'https://phimimg.com/upload/vod/20250522-1/6390bb671d9dcdd6c3a8e44b5c3e4b02.jpg', '<p>Lâm Xung chịu hàm oan bị áp giải đến Thương Châu. Lúc rời đi, ông vẫn đau đáu về gia đình của mình. Trong giây phút đưa tiễn người huynh đệ chí cốt, Lỗ Trí Thâm hứa sẽ bảo vệ gia đình Lâm Xung. Hai người mang trong mình câu chuyện riêng, bắt đầu hành trình thử thách nơi thế gian loạn lạc.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Văn Đông Tuấn","avatar":""},{"name":"Tôn Hoàng Thần","avatar":""},{"name":"Tất Kiền","avatar":""},{"name":"Tống Khải","avatar":""},{"name":"Lưu Kim","avatar":""},{"name":"Lý Tinh Hải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Leopard Head Forest Flushed Wild Boar Forest","Water Margin Heroes: Panther Head Lin Chong - Wild Boar Forest","豹子头林冲之野猪林"]', 1784690324376);
