INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lam-xung-1-vu-an-bach-ho-duong', 'Anh Hùng Lâm Xung 1 : Vụ Án Bạch Hổ Đường', 'The Panther Head Hero 1 : The White Tiger Hall', 'https://phimimg.com/upload/vod/20250522-1/70655014eb7eab6d8fc1361b58e02e61.jpg', 'https://phimimg.com/upload/vod/20250522-1/121a37ec0e20e9ff7ebb9b31afda47ae.jpg', '<p>Bộ phim&nbsp;xoay quanh Lâm Xung - một anh hùng sử thi hư cấu trong tiểu thuyết Thủy Hử, luôn kiên định với niềm tin của riêng mình rằng không bao giờ được lạm dụng bạo lực cho dù thế nào đi nữa. Nhưng một ngày, Lâm Xung bị kẻ thù lừa và anh ta cần chiến đấu lại bản thân để mang lại công lý và sự trong sạch.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Văn Đông Tuấn","avatar":""},{"name":"Bào Đan","avatar":""},{"name":"Tôn Hoàng Thần","avatar":""},{"name":"Tất Kiền","avatar":""},{"name":"Tống Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Water Margin: Leopard Head Lin Chong","Leopard Head Lin Chongzhi Baihutang","수호전 백호당 임충","豹子头林冲之白虎堂"]', 1784690324376);
