INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-mat-trang-phieu-luu-ky', 'Doraemon: Nobita và Mặt Trăng Phiêu Lưu Ký', 'Doraemon: Nobita''s Chronicle of the Moon Exploration', 'doraemon: nobita và mặt trăng phiêu lưu ký doraemon: nobita''s chronicle of the moon exploration wasabi mizuta megumi oohara yumi kakazu tomokazu seki subaru kimura junko minagawa alice hirose sōichi nakaoka shigeo takahashi yuya yagira kotaro yoshida kotono mitsuishi yasunori matsumoto shihoko hagino wataru takagi ikue otani yukiji doraemon movie 39: nobita no getsumen tansaki doraemon movie 39 eiga doraemon: nobita no getsumen tansaki 도라에몽: 노비타의 월면탐사기 電影哆啦a夢：大雄的月球探測記 doraemon - il film: nobita e le cronache dell''esplorazione della luna doraemon: nobita và mặt trăng phiêu lưu ký doraemon - penjelajahan nobita di bulan โดราเอมอน ตอน โนบิตะสำรวจดินแดนจันทรา 哆啦a梦：大雄的月球探险记 ドラえもん のび太の月面探査記 多啦a夢 - 大雄的月球探測記 doraemon: nobita''s chronicle of the moon exploration 映画ドラえもん のび太の月面探査記 哆啦a梦：大雄的月球探测记 哆啦a梦 大雄的月球探险记', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-am-duong', 'Đại Chiến Âm Dương', 'The Knight Of Shadows: Between Yin And Yang', 'https://phimimg.com/upload/vod/20231101-1/49256b3d00a325c6f3e461de7cf1cdf1.jpg', 'https://phimimg.com/upload/vod/20231101-1/650add06be54d08853b963c43bd3eff9.jpg', '<p>Bồ Tùng Linh (Thành Long) trong Đại chiến âm dương được xem như một bậc thánh nhân với cây bút thần kỳ. Ông đã thu phục rất nhiều yêu quái nguy hiểm, rồi nhốt chúng vào cuốn sách của cõi Âm. Khi bước sang tuổi trung niên, Bồ Tùng Linh quyết định ẩn mình, rồi viết thành sách những câu chuyện quá khứ của bản thân và mang chúng đi bán cho người đời. Tuy nhiên, khi mọi chuyện tưởng như đang yên bình, ngôi làng nơi họ Bồ đang sinh sống bỗng nhiên xuất hiện hai con yêu ma hùng mạnh. Mọi chuyện càng trở nên rắc rối khi một trong hai ác quỷ - Nhiếp Tiểu Tình (Chung Sở Hy) - lại có mối liên hệ đặc biệt với hiệp khách trừ quỷ Ninh Thái Thần (Nguyễn Kinh Thiên).</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Long","avatar":""},{"name":"Chung Sở Hy","avatar":""},{"name":"Nguyễn Kinh Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324376);
