INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-am-duong', 'Đại Chiến Âm Dương', 'The Knight Of Shadows: Between Yin And Yang', 'đại chiến âm dương the knight of shadows: between yin and yang thành long chung sở hy nguyễn kinh thiên jackie chan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-lai-vo-bau', 'Cua Lại Vợ Bầu', 'Win My Baby Back', 'https://phimimg.com/upload/vod/20250520-1/eb5d90244ac35946afb00a1b40c6cc3a.jpg', 'https://phimimg.com/upload/vod/20250520-1/4d97490e2f1fe6650cbb0e4a82267d82.jpg', '<p>Trọng Thoại và Nhã Linh yêu nhau đã được bảy năm. Những lỗi lầm nho nhỏ bắt đầu tích tụ thành mâu thuẫn cực lớn đẩy cả hai xa nhau. Lại thêm sự xuất hiện của người cũ Quý Khánh càng khiến Nhã Linh xao lòng. Và rồi, cô có thai. Rốt cuộc đứa bé là của ai và Nhã Linh sẽ chọn người đàn ông nào đi tiếp cùng mình? &nbsp;Sở hữu dàn diễn viên được đông đảo công chúng biết đến- kết hợp thế hệ diễn viên trẻ và các bậc lão làng kỳ cựu, cộng thêm kịch bản vui tươi nhưng chẳng kém phần cảm động, Cua Lại Vợ Bầu là điển hình cho công thức thành công gần như 100% của phim Việt mùa Tết.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trấn Thành","avatar":""},{"name":"Ninh Dương Lan Ngọc","avatar":""},{"name":"Anh Tú","avatar":""},{"name":"Mạc Văn Khoa","avatar":""},{"name":"Khả Như","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["把我宝贝赢回来","Cua Lại Vợ Bầu"]', 1784690324376);
