INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-sinh-tu-va-nguoi-may-phan-1', 'Yêu, Sinh Tử Và Người Máy (Phần 1)', 'Love, Death & Robots (Season 1)', 'https://phimimg.com/upload/vod/20241005-1/5c210afcce1c1b928d22ef77f24b788b.jpg', 'https://phimimg.com/upload/vod/20241005-1/f1aece74a59cf248f8ba8676ec4bae77.jpg', '<p>Các sinh vật đáng sợ, những bất ngờ kinh hoàng và hài kịch đen hội tụ trong tuyển tập hoạt hình do Tim Miller và David Fincher sáng tạo này. Chứa nội dung nhạy cảm.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 10, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael B. Jordan","avatar":""},{"name":"Elodie Yung","avatar":""},{"name":"Joe Dempsie","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Samira Wiley","avatar":""},{"name":"Tsuji Daisuke","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Rebecca Riedy","avatar":""},{"name":"Helen Sadler","avatar":""},{"name":"Hayley McLaughlin","avatar":""},{"name":"Time Winters","avatar":""},{"name":"Elly Condron","avatar":""},{"name":"Stefan Kapicic","avatar":""},{"name":"Bruce Thomas","avatar":""},{"name":"Jeff Be","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Amor, Morte & Robôs","爱，死亡和机器人","爱死亡与机器人","爱、死亡 & 机器人","愛死亡與機器人","Szerelem, halál és robotok","אהבה מוות & רובוטים","ラブ、デス&ロボット","Meilė, mirtis ir robotai","Любовь, смерть и роботы","Láska, Smrť & Roboti","Любов, смерть та роботи","Любов, смерть + роботи","Love, Death + Robots","Love Death + Robots","Love, Death and Robots","Love Death Robots","Sevgi, o''lim va robotlar","Love, Death & Robots"]', 1784690324376);
