INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-sinh-tu-va-nguoi-may-phan-1', 'Yêu, Sinh Tử Và Người Máy (Phần 1)', 'Love, Death & Robots (Season 1)', 'yêu, sinh tử và người máy (phần 1) love, death & robots (season 1) michael b. jordan elodie yung joe dempsie topher grace mary elizabeth winstead gary cole samira wiley tsuji daisuke maurice lamarche rebecca riedy helen sadler hayley mclaughlin time winters elly condron stefan kapicic bruce thomas jeff be amor, morte & robôs 爱，死亡和机器人 爱死亡与机器人 爱、死亡 & 机器人 愛死亡與機器人 szerelem, halál és robotok אהבה מוות & רובוטים ラブ、デス&ロボット meilė, mirtis ir robotai любовь, смерть и роботы láska, smrť & roboti любов, смерть та роботи любов, смерть + роботи love, death + robots love death + robots love, death and robots love death robots sevgi, o''lim va robotlar love, death & robots', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-set-trong-mua', 'Tiếng Sét Trong Mưa', 'Thunder In The Rain', 'https://phimimg.com/upload/vod/20250519-1/17fbecf7e01d9135328e074bea36f0e2.jpg', 'https://phimimg.com/upload/vod/20250519-1/efb352ba6b865ba1440c3f306dc62e23.jpg', '<p>Tiếng sét trong mưa xoay quanh hai nhân vật chính là Khải Duy (Cao Minh Đạt) và Thị Bình (Nhật Kim Anh). Trở về quê sau nhiều năm du học xứ trời Tây, cậu Ba Khải Duy đã đem lòng yêu một cô hầu tên Thị Bình, người mang trên mình nét hồn nhiên và sự hiền lành, ngây thơ trong sáng. Hai con người đã dành trọn trái tim cho đối phương và cuối cùng Thị Bình mang thai. Giông bão cũng từ đấy kéo đến, trút xuống cuộc đời cô khi đã để bà Hội (Diệu Đức) – mẹ của Khải Duy phát hiện, hành hạ và buộc cô phải gieo mình xuống sông tự vẫn nhưng không thành, từ đó bỏ xứ ra đi. Thời gian dần trôi, Khải Duy trở thành ông chủ đồn điền cao su giàu có đầy uy lực. Đứa con của anh và Thị Bình ngày nào cũng đã trưởng thành và được Khải Duy đổi tên thành Thanh Bình (Quốc Huy), như một cách để tưởng nhớ người phụ nữ mà cả đời Khải Duy yêu thương. Trong một lần, Thanh Bình đã cứu được Phượng (Oanh Kiều) – một cô gái suýt bị hãm hiếp trong rừng cao su và sau đó đem lòng yêu cô. Phượng được nhận vào phụ việc trong gia đình Khải Duy. Tình cảm giữa cô và Bình ngày càng sâu đậm cho đến một ngày, những uẩn khúc hai mươi mấy năm về trước được phơi bày khi mẹ của Phượng lên thăm con gái. Cuộc tình đang nồng thắm của Bình và Phượng bỗng chốc trở thành nỗi đau chới với bên bờ loạn luân...</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhật Kim Anh","avatar":""},{"name":"Cao Minh Đạt","avatar":""},{"name":"Khương Thịnh","avatar":""},{"name":"Oanh Kiều","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324376);
