INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-doi-ky-si-long-ryusoulger', 'Chiến Đội Kỵ Sĩ Long Ryusoulger', 'Kishiryu Sentai Ryusoulger', 'https://phimimg.com/upload/vod/20250515-1/a551e04af91bf366b6eae374fcbac6a1.jpg', 'https://phimimg.com/upload/vod/20250515-1/f94626a9caad469b1386ce77415cbe9b.jpg', '<p>65 triệu năm trước, các hiệp sĩ của tộc Ryusoul đã được chọn để tham gia vào một chiến dịch chiến tranh chống lại tộc Druidon độc tài, những kẻ muốn thống trị Trái Đất. Tuy nhiên, chiến dịch của tộc Druidon đã bị gián đoạn bởi thiên thạch đã kết thúc kỷ nguyên của loài khủng long, buộc chúng phải bỏ trốn vào không gian. Trong khi đó, các Kishiryu được đưa vào giấc ngủ sâu như một biện pháp dự phòng phòng khi tộc Druidon quay trở lại. Những hiệp sĩ được chọn quyết định sống trong hòa bình và truyền lại sứ mệnh của mình qua nhiều thế hệ. Ở thời hiện đại, tộc Druidon quay trở lại để giành lại Trái Đất, và thế hệ hiệp sĩ hiện tại – các Ryusoulger – đứng lên chiến đấu chống lại chúng với sự hỗ trợ của Ui Tatsui và cha cô, Naohisa Tatsui.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 13, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hayate Ichinose","avatar":""},{"name":"Keito Tsuna","avatar":""},{"name":"Ichika Osaki","avatar":""},{"name":"Yuito Obara","avatar":""},{"name":"Tatsuya Kishida","avatar":""},{"name":"Katsumi Hyodo","avatar":""},{"name":"Mana Kinjou","avatar":""},{"name":"Sora Tamaki","avatar":""},{"name":"Mitsuru Fukikoshi","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Ryota Takeuchi","avatar":""},{"name":"Jouji Nakata","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Tomokazu Seki","avatar":""}]', '[{"name":"Hành Động","slug":