INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-kho-khan-phan-5', 'Nhiệm Vụ Khó Khăn (Phần 5)', 'Line of Duty (Season 5)', 'https://phimimg.com/upload/vod/20250515-1/eb19cc8e9385e4c089e80ceb0128ad93.jpg', 'https://phimimg.com/upload/vod/20250515-1/38af2a32c7a12365cf79791e33083790.jpg', '<p>Trung sĩ – Thám tử Steve Arnott bị điều chuyển tới bộ phận chống tham nhũng sau khi từ chối che đậy một vụ nổ súng nhầm lẫn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Martin Compston","avatar":""},{"name":"Vicky McClure","avatar":""},{"name":"Adrian Dunbar","avatar":""},{"name":"Gregory Piper","avatar":""},{"name":"Nigel Boyle","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Owen Teale","avatar":""},{"name":"Anneika Rose","avatar":""},{"name":"Matthew Forsythe","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["בשירות החוק","ライン・オブ・デューティ 汚職特捜班","Line of Duty"]', 1784690324376);
