INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-nha-di-con', 'Về Nhà Đi Con', 'Come Home My Dear', 'https://phimimg.com/upload/vod/20250513-1/12d9b590628a39a911cff88ec9a3a4fa.jpg', 'https://phimimg.com/upload/vod/20250513-1/8a15f2b74a70c386236224e02b821375.jpg', '<p>Câu chuyện phim Về nhà đi con xoay quanh 3 chị em gái Thu Huệ, Anh Thư, Ánh Dương mồ côi mẹ từ thuở nhỏ, mỗi người một tính cách, một lối sống. Chị cả Thu Huệ dịu dàng, điềm đạm; cô hai Anh Thư xinh đẹp, sắc sảo, thực dụng; cô út Ánh Dương bộc trực, hoang dã, sống như một cậu con trai. Cả 3 chị em đều gặp phải những biến cố của riêng mình nhưng họ may mắn khi có chung một điểm tựa là ông Sơn - một người bố tận tuỵ, hết mực yêu thương các con. Sau nhiều biến cố, cuối cùng, 3 cô con gái đều nhận ra hạnh phúc lớn nhất mà họ có được chính là một người bố luôn sẵn sàng bao bọc và nói &quot;Về nhà đi con&quot; bất cứ khi nào họ cần một mái ấm...</p>', 'Hoàn Tất (85/85)', 85, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trung Anh","avatar":""},{"name":"Thu Quỳnh","avatar":""},{"name":"Bảo Thanh","avatar":""},{"name":"Bảo Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Về Nhà Đi Con"]', 1784690324376);
