INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-bo-tuc-dai-ngan-ha', 'Lớp Bổ Túc Dải Ngân Hà', 'Looking Up', 'https://phimimg.com/upload/vod/20250507-1/afe88e0eb719361bae4efb774230a885.jpg', 'https://phimimg.com/upload/vod/20250507-1/e1b88a06e07c8810739f96384707f66c.jpg', '<p>Trong vũ trụ bao la, các phi hành gia vô tình mất liên lạc với trái đất, khoảnh khắc tuyệt vọng nhất trong đời, anh nhớ lại người cha vĩ đại nhất của mình. Hai cha con cùng vượt qua quãng thời gian dài, để bảo vệ tình yêu và tình thân, câu chuyện đầy ắp niềm vui, sự ấm áp, nước mắt và cả những điều kỳ diệu.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Ren Suxi","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Wang Xi","avatar":""},{"name":"Li Jianyi","avatar":""},{"name":"Sun Xilun","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Wang Ge","avatar":""},{"name":"Wei Zun","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yin He Bu Xi Ban","银河补习班"]', 1784690324376);
