INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-2019', 'Truy Sát', 'Kill It', 'https://phimimg.com/upload/vod/20231219-1/261635aab43c896d73b36d1535588e53.jpg', 'https://phimimg.com/upload/vod/20231219-1/d6e75134ed44e7eeb8fca177fa4ee2e7.jpg', '<p>Bộ phim kể về câu chuyện người đàn ông bị ác quỷ bỏ rơi và người phụ nữ được ác quỷ đem về nuôi dưỡng và người ủy thác vì muốn trả thù mà truy đuổi hai người. Người đàn ông bị ác quỷ vứt bỏ trở thành sát thủ để tìm lại người thân của mình, còn người phụ nữ được ác quỷ nuôi nấng lại là một cảnh sát hình sự. Để trả thù cho người yêu đã chết, cô đã dấn thân vào con đường truy tìm tên sát thủ Kim Soo Hyun.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Ki Yong","avatar":""},{"name":"NANA","avatar":""},{"name":"Jeong-eui Roh","avatar":""},{"name":"Li Zai Yuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324376);
