INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-chuc-cao-thu-dinh-cao-vinh-dieu', 'Toàn Chức Cao Thủ: Đỉnh Cao Vinh Diệu', 'The King''s Avatar: For The Glory', 'https://phimimg.com/upload/vod/20250506-1/0f0d7eb0082b7b5f70aa4ca390dc0763.jpg', 'https://phimimg.com/upload/vod/20250506-1/ca7f500bd5ab064f5720bc396330d354.jpg', '<p>Toàn Chức Cao Thủ – Đỉnh Cao Vinh Diệu kể về thế giới thể thao điện tử đã chính thức trở thành sự kiện thể thao thứ 78 tại quốc gia này và “Vinh quang” sẽ tổ chức giải đấu chuyên nghiệp lần đầu tiên. Diệp Tu, 18 tuổi và bạn của anh- Tô Mộc Thu bắt đầu thành lập đội thể thao điện tử “Gia Thế”.Bên cạnh đó, giải đấu lần này còn quy tụ các cao thủ nổi tiếng trên cả nước lại với nhau để giành được vị trí vinh quang cao nhất của giải đấu eSports. Ngay khi “Gia Thế” bước vào vòng chung kết, đội đã gặp khủng hoảng và sẽ phải đối mặt với đội Royal Winds. Làm thế nào Diệp Thu, với tư cách là đội trưởng, giải quyết vấn đề nan giải? Một nhóm thanh thiếu niên với ước mơ như vậy có thể leo lên đỉnh vinh quang?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Kiệt","avatar":""},{"name":"Tây Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Quánzhí gāoshǒu: FOR THE GLORY","Quánzhí gāoshǒu zhī Diānfēng róngyào","全职高手 FOR THE GLORY","全职高手：巅峰荣耀","全职高手动画大电影","The King''s Avatar: For the Glory","Quanzhi Gaoshou: Dianfeng Rongyao","全职高手之巅峰荣耀"]', 1784690324376);
