INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-den-ky-quai', 'Ngôi Đền Kỳ Quái', 'Pee Nak', 'https://phimimg.com/upload/vod/20250506-1/f05978a2cdf8fe242a60d107638614ac.jpg', 'https://phimimg.com/upload/vod/20240121-1/4b40f51efa469324c5f6dfabc2bc0d5a.jpg', '<p>Ngôi Đền Kỳ Quái nói về bộ ba hoàn cảnh vì lời thề ngớ ngẩn sẽ cạo đầu đi tu nếu trúng số và may mắn trúng ngay giải chót. Và “may mắn” lại nhân đôi khi hội bạn thân lại chọn trúng ngay ngôi đền bị ám bởi hàng loạt hiện tượng siêu nhiên. Từ một lời thề quái gở, hội bạn “thân ai nấy lo” này sẽ phải đối mặt với hàng loạt rắc rối đang đón chờ phía trước ra sao?</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Vachiravit Paisarnkulwong","avatar":""},{"name":"Chinawut Indracusin","avatar":""},{"name":"Witthawat Rattanaboonbaramee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324376);
