INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-chang-cap-cuu', 'Yêu Chàng Cấp Cứu', 'My Ambulance', 'https://phimimg.com/upload/vod/20250429-1/07151c111717c772b03af3d04951e47a.jpg', 'https://phimimg.com/upload/vod/20250429-1/f1a20055723b4012f1c04018eb15ba8c.jpg', '<p>Peng, một bác sĩ nội trú tại khoa cấp cứu, và Tantawan đã yêu nhau suốt 15 năm. Tantawan – người sở hữu năng lực kỳ diệu – bắt đầu nghi ngờ tình cảm của Peng dành cho mình liệu còn vẹn nguyên. Một ngày nọ, cả hai gặp tai nạn giao thông nghiêm trọng, khiến Tantawan bị thương nặng. Khi tỉnh lại, cô hoàn toàn mất trí nhớ – và không hề hay biết rằng sự thật đằng sau vụ tai nạn đã bị che giấu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Davika Hoorne","avatar":""},{"name":"Sunny Suwanmethanon","avatar":""},{"name":"Wongravee Nateetorn","avatar":""},{"name":"Kanyawee Songmuang","avatar":""},{"name":"Thiti Mahayotaruk","avatar":""},{"name":"Putthipong Assaratanakul","avatar":""},{"name":"Krit Amnuaydechkorn","avatar":""},{"name":"Napat Chokejindachai","avatar":""},{"name":"Paweenut Pangnakorn","avatar":""},{"name":"Ponlawit Ketprapakorn","avatar":""},{"name":"Machida Sutthikulphanich","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["神的答案","我的救护车","爱的救护","Ruk Chut Jai Nai Chukchern","My Ambulance","รักฉุดใจนายฉุกเฉิน"]', 1784690324376);
