INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-nguyen-sinh', 'Quái Vật Nguyên Sinh', 'Primal', 'https://phimimg.com/upload/vod/20231026-1/b2d89dc13479a68df93511016b146b1d.jpg', 'https://phimimg.com/upload/vod/20231026-1/a81d0779f1d51139eca74041698feaa5.jpg', '<p>Bộ phim xoay quanh Frank Walsh, một thợ săn đang thực hiện nhiệm vụ đưa một con báo trắng cùng nhiều loài động vật hoang dã từ Brazil về một sở thú ở Mỹ bằng tàu biển. Đi cùng với Frank trên chuyến tàu định mệnh đó là một tên tội phạm giết người, được chính phủ nhờ dẫn độ về Mỹ. Tàu khởi hành không bao lâu thì tên tội phạm thoát khỏi nơi giam giữ, giết hại những người lính canh gác, bí mật thả những con thú ra và lẩn trốn trên tàu. Frank buộc phải sử dụng kỹ năng chiến đấu và săn thú của mình để vừa tìm ra tên tội phạm, vừa tránh khỏi nanh vuốt của những con vật nguy hiểm chết người.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Jeremy Jay Nazario","avatar":""},{"name":"LaMonica Garrett","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Isaac Santiago","avatar":""},{"name":"Braulio Castillo Jr.","avatar":""},{"name":"Tommy Walker","avatar":""},{"name":"Sewell Whitney","avatar":""},{"name":"Leon Andrew Joseph","avatar":""},{"name":"Sebastian Vazquez","avatar":""},{"name":"John Lewis","avatar":""},{"name":"Rey Hernandez","avatar":""},{"name":"Drake Shannon","avatar":""},{"name":"Jaime","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324376);
