INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-than-dai-duong-tham-sat', 'Hung Thần Đại Dương: Thảm Sát', '47 Meters Down: Uncaged', 'https://phimimg.com/upload/vod/20240123-1/f48624963158b7bbe91611d268bcd9e7.jpg', 'https://phimimg.com/upload/vod/20240123-1/97ad6028adafe0f0771fe87b3298c0dc.jpg', '<p>Trong chuyến phiêu lưu đến một vùng đảo ít người biết đến, 4 cô gái Mia, Sasha, Nicole và Alexa quyết định lặn xuống biển để khám phá một thành cổ của người Maya dưới đáy đại dương. Khi vào đến bên trong, cổng thành bỗng sụp đổ khiến họ phải nhanh chóng tìm cách thoát thân trong những đường hầm mê cung và các hang động kỳ quái trước khi cạn sạch dưỡng khí.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Sophie Nélisse","avatar":""},{"name":"Corinne Foxx","avatar":""},{"name":"Nia Long","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324376);
