INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-hoa-lac-loi', 'Vinh Hoa Lạc Lối', 'Ji Dang', 'https://phimimg.com/upload/vod/20250418-1/a95d33aa8ccf71d8c1a6caf1d1b1473a.jpg', 'https://phimimg.com/upload/vod/20250418-1/8725f46b9d8fe81d8b826b8885efbf71.jpg', '<p>Câu chuyện về 3 anh em họ Lu cùng lớn lên tại Thượng Hải những năm 1990, chứng kiến nền kinh tế hỗn loạn nơi đây dần thay đổi trở thành trung tâm tài chính thương mại lớn của Trung Quốc. Lu JiangTao từ tay trắng trở lên giàu có, nhưng anh dần thay đổi và đánh mất bản thân, trở lên thực dụng và thờ ơ với gia đình. Anh coi người thân và gia đình như những công cụ cho mục đích làm giàu. Người anh cả Lu Hai Bo luôn coi trọng gia đình, tình cảm. Anh có thể thất bại và từ bỏ nhiều thứ, nhưng điều đó lại giúp anh thành công về sau. Cùng với gia đình, Hai Bo giúp đỡ JiangTao nhận thức được sai lầm và tìm lại hạnh phúc.Trong thế giới kinh doanh khốc liệt, gia đình họ Lu một lần nữa cùng nhau vượt qua khó khăn, vươn đến thành công.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 7, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Trọng","avatar":""},{"name":"Quách Hiểu Đông","avatar":""},{"name":"Lý Niệm","avatar":""},{"name":"Xa Hiểu","avatar":""},{"name":"Hầu Dũng","avatar":""},{"name":"Đào Trạch Như","avatar":""},{"name":"Trương Đấu Đấu","avatar":""},{"name":"Lý Đình Triết","avatar":""},{"name":"Lý Thành Như","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ji Dang","激荡"]', 1784690324376);
