INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-moi-phan-2', 'Lính Mới (Phần 2)', 'The Rookie (Season 2)', 'lính mới (phần 2) the rookie (season 2) nathan fillion melissa o''neil alyssa diaz eric winter mekia cox richard t. jones shawn ashmore jenna dewan lisseth chavez الروكي 菜鸟警察 the rookie : le flic de los angeles ο νεοσύλλεκτος عنوان فارسی : تازه‌کار ザ・ルーキ 더 루키 руки новачок the rookie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-tham-lang', 'Nhân Chứng Thầm Lặng', 'Bodies At Rest', 'https://phimimg.com/upload/vod/20231109-1/5e6456f6b9630b3457386a2edb29e472.jpg', 'https://phimimg.com/upload/vod/20231109-1/0e5e14f5fbf22a72aefb7e49c46bbe90.jpg', '<p>Một đêm bình thường tại nhà xác thành phố bỗng hóa thành địa ngục khi một nhóm tội phạm bịt mặt xông vào nhằm đánh cắp một thi thể chứa bằng chứng quan trọng. Đối đầu với chúng là bác sĩ pháp y Chung Đại Dũng và trợ lý của anh – những người không hề được huấn luyện nhưng buộc phải chiến đấu để sống sót. Trong vòng vài giờ ngắn ngủi, một trò chơi trí tuệ, tâm lý và hành động nghẹt thở diễn ra – nơi từng cánh cửa, từng hành lang, từng xác chết... đều có thể là chìa khóa thoát khỏi nơi hiểm nguy hoặc chính là cái bẫy chết người.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Dương Tử","avatar":""},{"name":"Trần Gia Lạc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324376);
