INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-dao', 'Chiêu Dao', 'The Legends', 'https://phimimg.com/upload/vod/20250416-1/6159a4781d542267edac5e07db225d1a.jpg', 'https://phimimg.com/upload/vod/20250416-1/f07d4c897ecaf8333622466f3831c41c.jpg', '<p>Chiêu Dao xoay quanh Nữ ma đầu Lộ Chiêu Dao (Bạch Lộc) là môn chủ của Vạn Lục Môn. Lúc sống nàng ta hoành hành ngang ngược khiến hai giới tiên ma vừa nghe tên đã khiếp sợ. Trong một lần xuống núi Chiêu Dao cứu được tiểu tử Mặc Thanh (Hứa Khải). Trong lúc nàng sắp lấy được ma khí thượng cổ Kiếm Vạn Quân thì bị Mặc Thanh vô tình sát hại. Bản thân Chiêu Dao lúc sống thì tự cao tự đại vang danh giang hồ, đến khi chết lại chết trong tay kẻ mình đã cứu trở thành một hồn ma nghèo kiết xác không ai ngó ngàng. Những năm đó cũng chỉ có mình Mặc Thanh đến thăm mộ nàng, còn mang cho nàng không ít hoa quả tươi. Nhưng trong lòng Chiêu Dao vẫn mang mối hận sát thân do Mặc Thanh gây ra.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 7, 2019, 'Vietsub + Thuyết Minh + Lồng Tiiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Hứa Khải","avatar":""},{"name":"Lý Tử Phong","avatar":""},{"name":"Đại Húc","avatar":""},{"name":"Tiêu Yến","avatar":""},{"name":"Mễ Lộ","avatar":""},{"name":"Diệp Ân Vỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhaoyao","Zhao Yao","เจาเหยา จอมมารโลต้องจำ","The Legends","Chiêu Diêu","Chiêu Dao","招摇"]', 1784690324376);
