INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-thu-cung', 'Liên Minh Thú Cưng', 'Pets United', 'https://phimimg.com/upload/vod/20250416-1/e56810f6bd9dea9841bab7930042dbaf.jpg', 'https://phimimg.com/upload/vod/20250416-1/5722557b1d4884603ddd41c48ffa0bd7.jpg', '<p>Phim kể về hành trình chiến đấu chống lại thị trưởng Frank Stone của chú chó Roger (Robin Hood của thành phố Robo) và những người bạn. Khi Stone âm mưu trục xuất tất cả các sinh vật sống khỏi thành phố Robo để biến nó thành một nơi chỉ có Robot. Mặc cho phải đương đầu với robot thông minh, thiết bị tối tân nhưng với khát khao được sống sót, tồn tại, Roger và những thú cưng khác vẫn quyết tâm đấu tranh để giành lại thành phố của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Đức', 0, '[{"name":"Natalie Dormer","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Jeff Burrell","avatar":""},{"name":"Harvey Friedman","avatar":""},{"name":"Jan Odle","avatar":""},{"name":"Bryan Larkin","avatar":""},{"name":"Naomi McDonald","avatar":""},{"name":"Tom Haywood","avatar":""},{"name":"Andres Williams","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["寵物聯盟","Kæledyrsligaen","Pets United"]', 1784690324376);
