INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-que-huong', 'Tìm Lại Quê Hương', 'Everybody Say Kungdari', 'https://phimimg.com/upload/vod/20250412-1/4c08f416eec98a528fc96f2d91288746.jpg', 'https://phimimg.com/upload/vod/20250412-1/c1fd5fb9fe1cbaaee48770d4406f8559.jpg', '<p>Bo Mi được nhận làm con nuôi tại Mỹ. Cô sống ở New York, tận hưởng cuộc sống của mình ở đó, nhưng cô lại dính vào một tình huống không ngờ. Bo Mi không có quốc tịch Hoa Kỳ và cô bị trục xuất khỏi đất nước của họ. Cô trở về ngôi làng quê hương Kungdari, Hàn Quốc. Ở đó, Bo Mi gặp Soo Ho. Soo Ho từng làm việc trong lĩnh vực tài chính tại Mỹ. Anh ấy đã thành công ở đó, nhưng để tập trung phát triển một phương pháp chữa trị tự nhiên cho đứa con gái bị bệnh của mình, anh đã quyết định ở lại Kungdari.</p>', 'Hoàn Tất (99/99)', 99, 'series', 'completed', 7, 2019, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Seok-jung","avatar":""},{"name":"Choi Ji Won","avatar":""},{"name":"Kim Tae-yul","avatar":""},{"name":"Seo Sung Gwang","avatar":""},{"name":"Myeong Ji-yeon","avatar":""},{"name":"Seo Hye-jin","avatar":""},{"name":"Kim Ho-jin","avatar":""},{"name":"Lee Bo-hee","avatar":""},{"name":"Park Si-eun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["모두 다 쿵따리"]', 1784690324376);
