INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-mong-manh', 'Hạnh Phúc Mong Manh', 'Bad Love', 'https://phimimg.com/upload/vod/20250412-1/0b5fbccb8c007155819a07bb20b8bfc7.jpg', 'https://phimimg.com/upload/vod/20250412-1/cd434e52c0aee99d398787c61d1cc3b6.jpg', '<p>Một tai nạn đã thay đổi số phận của 5 người đàn ông và phụ nữ. Không giống như những câu chuyện tình yêu thông thường với những kỷ niệm và giai đoạn đáng yêu, tình yêu của họ bị phán xét và soi mói. Bất chấp những lời chỉ trích về họ, họ không thể ngăn mình yêu nhau một cách tuyệt vọng. Hạnh phúc mong manh là một bộ phim tình cảm buồn khắc họa tình yêu chân thật đến đau lòng. Nữ chính trong phim là So Won, một cố gái mạnh mẽ và tự lập, nỗ lực bước vào tập đoàn thời trang hàng đầu.</p>', 'Hoàn Tất (129/129)', 129, 'series', 'completed', 8, 2019, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Go-eun","avatar":""},{"name":"Lee Seon-ho","avatar":""},{"name":"Oh Seung-ah","avatar":""},{"name":"Yoon Jong-hwa","avatar":""},{"name":"Jeon Seung-bin","avatar":""},{"name":"Cha Min-jee","avatar":""},{"name":"Shim Eun-jin","avatar":""},{"name":"Nam Kyung-eup","avatar":""},{"name":"Jung Ae-ri","avatar":""},{"name":"Jeon Jin-gi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["나쁜사랑","나쁜 사랑"]', 1784690324376);
