INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-den-phan-5', 'Gương Đen (Phần 5)', 'Black Mirror (Season 5)', 'https://phimimg.com/upload/vod/20231002-1/02d000e11129794032cdfebb3e9650cb.jpg', 'https://phimimg.com/upload/vod/20231002-1/0608d3603ea3e05588fb0fcb9adea3ab.jpg', '<p>Black Mirror là tấm gương phản chiếu mặt đen tối nhất của nhân loại, xoáy vào những vấn đề của con người trong thời kì công nghệ đang phát triển nhanh đến đáng sợ. Với mỗi tập là một cốt truyện riêng biệt, bộ phim khiến người xem không thể rời mắt bằng hàng loạt nút thắt bất ngờ được gỡ một cách khéo léo và những kết thúc nặng nề, ám ảnh và không tài nào đoán trước được.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dawson","avatar":""},{"name":"Selma Telse","avatar":""},{"name":"Airport Stewardess","avatar":""},{"name":"Todd","avatar":""},{"name":"Older May Double","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324376);
