INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-chet-khong-chet', 'Kẻ Chết Không Chết', 'The Dead Don''t Die', 'https://phimimg.com/upload/vod/20250409-1/df16fc7b53e0e6cf36189e8153e964e5.jpg', 'https://phimimg.com/upload/vod/20250409-1/4d7930f897c5c862ab0a8f6f35556f2b.jpg', '<p>Lấy bối cảnh thị trấn nhỏ yên bình bị khuấy động bởi đám xác sống. Nhưng điều ghê rợn không kém là các cư dân cũng thấy việc này rất bình thường và đối mặt với bọn thây ma một cách rất ung dung và điềm tĩnh. Nhân vật trung tâm của phim là hai viên cảnh sát do Bill Murray và Adam River thủ vai, trông họ là hai người tỉnh táo nhất khi cùng nhau lập kế hoạch và đi vòng vòng để giúp người chứ không trốn chui trốn lủi...</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Tom Waits","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Eszter Balint","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Maya Delmont","avatar":""},{"name":"Taliyah Whitaker","avatar":""},{"name":"Jahi Di''Allo Winston","avatar":""},{"name":"Kevin McCormick","avatar":""},{"name":"Sid O''Connell","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"RZA","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Jodie Ma","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Мъртвите не умират","Les morts ne meurent pas","死無可死","Ha''Mettim Ei''nam Mettim","Мертві не помирають","The Dead Don''t Die"]', 1784690324376);
