INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-gemstone-chinh-truc-phan-1', 'Nhà Gemstone Chính Trực (Phần 1)', 'The Righteous Gemstones (Season 1)', 'https://phimimg.com/upload/vod/20250404-1/6cec0f73a101803ea8cb4fa90f13ae5c.jpg', 'https://phimimg.com/upload/vod/20250404-1/b7eb5156712359e4d328ef7411f95904.jpg', '<p>Gia đình truyền giáo Gemstone gây dựng hình tượng vô cùng chính trực và thanh cao, nhưng ẩn bên trong là những thói hư tật xấu đang ngày một mất kiểm soát. Đế chế phúc lành của nhà Gemstone bị những kẻ bên ngoài đe dọa, cả ở ở quá khứ và hiện tại.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny McBride","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Edi Patterson","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Tim Baltz","avatar":""},{"name":"Tony Cavalero","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"John Goodman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["神佑家族","布道家族","布道家庭","正义的宝石","The Righteous Gemstones"]', 1784690324376);
