INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-con-tim-phan-2', 'Tín Hiệu Con Tim (Phần 2)', 'Heart Signal (Season 2)', 'https://phimimg.com/upload/vod/20250327-1/b6cf6cda743ae011041456be0d0539b7.jpg', 'https://phimimg.com/upload/vod/20250327-1/1d9c64da4cecf08d03673c5a8d3c44bf.jpg', '<p>Tín Hiệu Con Tim là chương trình thực tế giao lưu suy luận về tình cảm nam nữ. Các cặp đôi nam nữ độc thân bước vào &quot;Ngôi nhà nhỏ tín hiệu&quot; sống chung và phát triển tình cảm với nhau.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Haitao","avatar":""},{"name":"Jerry Yan","avatar":""},{"name":"Chunye Zhang","avatar":""},{"name":"Ariel Lin","avatar":""},{"name":"Rao Xueman","avatar":""},{"name":"The8","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Heart Signal","心动的信号"]', 1784690324376);
