INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-xac-song-phan-1', 'Vương Triều Xác Sống (Phần 1)', 'Kingdom (Season 1)', 'https://phimimg.com/upload/vod/20250326-1/f167b6b2508b442433f2dfc4bbf14885.jpg', 'https://phimimg.com/upload/vod/20250326-1/924b993d910ac21c663eabd30ac16339.jpg', '<p>Vương Triều Xác Sống (Kingdom) 2019 là phim hàn quốc lấy bối cảnh thời Joseon, Thái tử Lee Chang (Joo Ji Hoon) có nhiệm vụ điều tra một dịch bệnh bí ẩn đang hoành hành trên khắp đất nước. Mọi chuyện bắt đầu lệch khỏi quỹ đạo khi Lee Chang phát hiện loại bệnh này liên quan đến xác sống. Chưa kể, các thế lực trong triều đình đối với thứ &quot;dịch bệnh&quot; này có nhiều phương thức xử lý khác nhau với mục tiêu lớn nhất là bảo vệ quyền lợi cá nhân, gây nên cục diện rối loạn thảm khốc.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Ryu Seung-ryong","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Huh Joon-ho","avatar":""},{"name":"Ahn Eun-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["尸战朝鲜","李屍朝鮮","Koningrijk","Kingdom","킹덤"]', 1784690324376);
