INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-nam-nang-dau-phan-1', 'Nhà Có Năm Nàng Dâu (Phần 1)', 'The Quintessential Quintuplets (Season 1)', 'https://phimimg.com/upload/vod/20250316-1/d86649a127e6fb25b6639805d64f4771.jpg', 'https://phimimg.com/upload/vod/20250316-1/9a433748e0398ed07b8902e77cb73dcc.jpg', '<p>Trong một lần nọ, anh chàng Futaro Uesugi được thuê về làm gia sư cho 5 cô con gái của một ông chú giàu nứt vách, và dĩ nhiên, tiền thuê cậu khá là cao. Thế là những câu chuyện dở khóc dở cười xoay quanh anh gia sư Uesugi và 5 cô nàng xinh đẹp nhưng hay gây rắc rối cho cậu bắt đầu…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Inori Minase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["As Quíntuplas","五等分的花嫁","The Quintessential Quintuplets","Go-Toubun no Hanayome","Gotoubun no Hanayome","5-toubun no Hanayome","Go-Tōbun no Hanayome","5Hanayome SP","5등분의 신부","Sposób na pięcioraczki","Go Toubun no Hanayome","The Quintessential Quintuplets∬.","五等分の花嫁"]', 1784690324376);
