INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-co-nam-nang-dau-phan-1', 'Nhà Có Năm Nàng Dâu (Phần 1)', 'The Quintessential Quintuplets (Season 1)', 'nhà có năm nàng dâu (phần 1) the quintessential quintuplets (season 1) yoshitsugu matsuoka kana hanazawa ayana taketatsu miku ito ayane sakura inori minase as quíntuplas 五等分的花嫁 the quintessential quintuplets go-toubun no hanayome gotoubun no hanayome 5-toubun no hanayome go-tōbun no hanayome 5hanayome sp 5등분의 신부 sposób na pięcioraczki go toubun no hanayome the quintessential quintuplets∬. 五等分の花嫁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quai', 'Thủy Quái', 'Water Monster', 'https://phimimg.com/upload/vod/20231117-1/48d34dcfefbc5bee6e4b2df925e5d51d.jpg', 'https://phimimg.com/upload/vod/20231117-1/9b1354c9c2f0d7457cb148d12889fb8c.jpg', '<p>Thủy Quái kể về một người con trai yếu đuối và nhút nhát. Anh sinh ra trong một gia đình đánh cá và đã nhìn thấy cha mình bị quái vật &quot; khỉ nước &quot; giết chết khi anh đi câu cá với cha lúc còn nhỏ, nó đã để lại một nỗi ám ảnh trong tim anh. Mười năm sau, quái vật &quot;Khỉ nước&quot; xuất hiện trở lại, giết chết em trai và cha của nữ chính. Để cứu người phụ nữ, nam chính không để những người phụ nữ bị giết làm &quot;vật hiến tế&quot;. Anh bắt đầu học các kỹ năng câu cá và nước mà cha anh đã dạy cho anh. Anh cũng mời anh em họ của mình để tập luyện và tham gia chiến đấu cùng nhau. Dân làng cũng nhận ra rằng những sai lầm của họ và đã gia nhập đội quái vật dưới nước. Cuối cùng tất cả mọi người đã diệt trừ được những con khỉ nước, dân làng trở lại một cuộc sống bình thường.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Lincheng","avatar":""},{"name":"Zhu Lilan","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Wang Jianguo","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Li Gaoji","avatar":""},{"name":"Le Sihong","avatar":""},{"name":"Wu Chengzhi","avatar":""},{"name":"Yi Xie","avatar":""},{"name":"Daimo Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324376);
