INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-voi', 'Nữ Hoàng Voi', 'The Elephant Queen', 'https://phimimg.com/upload/vod/20250324-1/ac309f4c36168bcaa6ac60fd56cce505.jpg', 'https://phimimg.com/upload/vod/20250324-1/fa61ee3d67cfb98690bd994ca8e12736.jpg', '<p>Hành trình đầy tình yêu gia đình và lòng dũng cảm của voi cái đầu đàn Athena, khi dẫn dắt đàn voi vượt qua địa hình hiểm nguy của Châu Phi để trở về với quê nhà.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Chiwetel Ejiofor","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["The Elephant Mother","Царица Слоница - Слоницата Майка","מלכת הפילים","The Elephant Queen"]', 1784690324376);
