INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-thien-vo-thuong-truyen', 'Ngự Thiên Vô Thường Truyện', 'The Devil Of Village', 'https://phimimg.com/upload/vod/20250324-1/6da63b78c93bfd198196823cecd7e14d.jpg', 'https://phimimg.com/upload/vod/20250324-1/e484381168ea80d5ab29e2d4a18d9c10.jpg', '<p>Trong thành Lan Lăng liên tục xảy ra các án “quỷ ăn thịt người”, lời đồn dậy lên bốn phía khiến lòng dân lo lắng. Ngự Thiên Giám phái nhóm Vô Thường gồm Hắc Phong và Bạch Vũ đi điều tra. Chân tướng từng chút từng chút một bị bại lộ, những bí mật xấu xa, đen tối của Ngự Thiên Giám cũng dần dần được phơi bày…</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Kiệt","avatar":""},{"name":"Tôn Vũ Hàn","avatar":""},{"name":"La Đại Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["御天无常传"]', 1784690324376);
