INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-long-to-su', 'Giáng Long Tổ Sư', 'Master Dragon', 'https://phimimg.com/upload/vod/20250324-1/e9926f0a5147c8e82faf9329bf45135e.jpg', 'https://phimimg.com/upload/vod/20250324-1/13a6dc1cdc6ba73e8a3f4cbb6cc32bd7.jpg', '<p>Hàng yêu đại sư Tống Định Bá được cửa hàng gạo mời đến để thu phục và thuần hóa yêu lừa Mã Lư, tiếng tăm lẫy lừng. Nhưng không may, sau đó Mã Lư chạy trốn, Tống Định Bá bám theo phát hiện thôn dân đang trói Tiêu Tiêu để cúng cho thần linh thạch tượng, nhân lúc âm dương hỗn loạn đã cứu Tiêu Tiêu, và đánh bại được yêu xà giả làm thần linh. Tiêu Tiêu vô cùng cảm kích Tống Định Bá, sau khi biết được danh tiếng của Tống Định Bá liền mời vào Kinh bắt yêu. Từ đây ba người cùng đi lên Kinh, trên đường tiêu diệt sạch toàn bộ yêu quái mà quốc sư phái đến. Thân phận của Tiêu Tiêu cũng dần bị bại lộ, Tiêu Tiêu chính là tam công chúa, luôn nghi ngờ tên quốc sư trong triều là yêu quái, dùng tà đạo để mê hoặc quần chúng, mong muốn Tống Định Bá có thể giúp diệt trừ yêu ma.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Benny Chan Ho-Man","avatar":""},{"name":"Qin Hanlei","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"Fan Shixuan","avatar":""},{"name":"Xie Yihong","avatar":""},{"name":"Dian Wen","avatar":""},{"name":"Ning Xiaohua","avatar":""},{"name":"Fu Xiaohu","avatar":""},{"name":"Guo Ziheng","avatar":""},{"name":"Chen Yue","avatar":""},{"name":"Li Shiyan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Master Dragon","降龙祖师"]', 1784690324376);
