INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-ma-quai', 'Khách Sạn Ma Quái', 'Hotel Del Luna', 'https://phimimg.com/upload/vod/20241019-1/d8ea7dbc495688ea43446b4713a54b51.jpg', 'https://phimimg.com/upload/vod/20241019-1/599868f0e8b262d901f2c39ece474fd8.jpg', '<p>Jang Man-Wol (IU) là giám đốc của khách sạn Del Luna. Khách sạn nằm ở khu sầm uất của Seoul và có bề ngoài cổ kính. Nhiều năm trước, cô mắc phải một lỗi lớn nên bị kẹt lại ở khách sạn Del Luna. Cô xinh đẹp, nhưng không kiên định, luôn nghi ngờ và tham lam.

Koo Chan-Sung (Yeo Jin-Goo) từng là trợ lý trẻ tuổi nhất ở một tập đoàn khách sạn đa quốc gia. Anh là người cầu toàn và chân thật. Tuy bề ngoài trông điềm đạm nhưng thực chất anh lại rất dễ mềm lòng. Vì một sự việc bất ngờ mà anh bắt đầu làm quản lý ở khách sạn Del Luna.

Khách ở khách sạn này toàn bộ đều là ma.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"IU","avatar":""},{"name":"Yeo Jin Goo","avatar":""},{"name":"Bae Hae Sun","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Хотел \"Дел Луна\"","德鲁纳酒店","Hotel Deluna","هتل دل لونا","ホテルデルーナ～月明かりの恋人","Hotel Del Luna","Отель «Дель Луна»","รอรักโรงแรมพันปี","德魯納酒店","호텔 델루나"]', 1784690324376);
