INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khach-san-ma-quai', 'Khách Sạn Ma Quái', 'Hotel Del Luna', 'khách sạn ma quái hotel del luna iu yeo jin goo bae hae sun хотел "дел луна" 德鲁纳酒店 hotel deluna هتل دل لونا ホテルデルーナ～月明かりの恋人 hotel del luna отель «дель луна» รอรักโรงแรมพันปี 德魯納酒店 호텔 델루나', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-cung', 'Đông Cung', 'Good Bye My Princess', 'https://phimimg.com/upload/vod/20250323-1/9f0cf988bf4298cd4d3a2e6447cfc70f.jpg', 'https://phimimg.com/upload/vod/20250323-1/5c0a89a98d4f0f48235d97f6a08019b0.jpg', '<p>Đông Cung (Good Bye My Princess): Tác phẩm phim truyền hình với tên gọi Đông Cung được chuyển thể từ cuốn tiểu thuyết cùng tên nổi tiếng của tác giả Phỉ Ngã Tư Tồn. Phim sẽ được công chiếu ra mắt khán giả vào năm 2019. Nội dung của Đông Cung xoay quanh câu chuyện tình yêu đầy bi ai xuất phát từ cuộc hôn nhân chính trị giữa nàng công chúa Tây Lương Tiểu Phong (do Bành Tiểu Nhiễm thủ vai) xinh đẹp và đương kim thái tử Lý Thừa Ngân (do Trần Tinh Húc thủ vai). Cùng với những đau khổ giằng xé nội tâm giữa những con người đó là những mâu thuẫn được đẩy lên cao trào xảy ra trong Đông cung, cùng với những âm mưu đen tối chôn cung đình. Nhưng rồi cuối cùng thì những vòng xoay ấy lại khiến cho con người phải thay đổi và nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Bành Tiểu Nhiễm","avatar":""},{"name":"Ngụy Thiên Tường","avatar":""},{"name":"La Gia Lương","avatar":""},{"name":"Dương Cung Như","avatar":""},{"name":"Thiệu Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Goodbye My Princess","东宫"]', 1784690324376);
