INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('power-rangers-beast-morphers', 'Power Rangers Beast Morphers', 'Power Rangers Beast Morphers', 'https://phimimg.com/upload/vod/20250320-1/bbe524d46e7818a3e2dddd0cd8c6883c.jpg', 'https://phimimg.com/upload/vod/20250320-1/b2cf6045ceb9048872d3616ff2dd419b.jpg', '<p>Lấy bối cảnh trong tương lai, một cơ quan bí mật ở thành phố Coral Harbor có tên là Grid Battleforce kết hợp một chất mới được phát hiện có tên là &quot;Morph-X&quot; với DNA động vật để tạo ra một nhóm Power Rangers mới được gọi là Beast Morphers. Beast Morpher Rangers phải bảo vệ Morphin Grid khỏi Evox, một loại virus máy tính độc ác tạo ra bản sao avatar ác của các ứng cử viên Beast Morphers ban đầu Blaze và Roxy, người đã bị hôn mê. Khi ba người trong số họ được chuyển đến Cyber Dimension, Evox, Cybervillain Blaze và Cybervillain Roxy có được người cai trị thực tế của nó Scro Muff như một đồng minh khi anh ta giúp họ trong kế hoạch đưa Evox về Trái đất</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Olivier Savoie-Mainguy","avatar":""},{"name":"Jean-Guy Bouchard","avatar":""},{"name":"Christiane Labelle","avatar":""},{"name":"Monique Lacasse","avatar":""},{"name":"Pierre G. Lacasse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Anniversary"]', 1784690324376);
