INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-lili', 'Tom Và Lili', 'Tom And Lili', 'https://phimimg.com/upload/vod/20250318-1/5755d5dabda314bdb11a1dac2340d972.jpg', 'https://phimimg.com/upload/vod/20250318-1/fd5f0fbb14295784d7e690e1dfac98da.jpg', '<p>Chuyện kể về hai anh em Tom và Lili sống trong một quán ăn gia đình sôi động. Hai anh em luôn bày ra những trò đùa tinh quái, mang đến bầu không khí náo nhiệt cho quán ăn, nhưng đồng thời cũng đem lại không ít tai vạ!</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 7, 2019, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Tom-Tom et Nana"]', 1784690324376);
