INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tom-va-lili', 'Tom Và Lili', 'Tom And Lili', 'tom và lili tom and lili  tom-tom et nana', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-truyen-thuyet', 'Mười Hai Truyền Thuyết', 'Our Unwinding Ethos', 'https://phimimg.com/upload/vod/20250317-1/0b638be0bf2f3b84a42220ef451d80b8.jpg', 'https://phimimg.com/upload/vod/20250317-1/b39b6e7e81f98d081a7a63989f897686.jpg', '<p>Mười Hai Truyền Thuyết xoay quanh chuyện anh chàng phóng viên Phó Tử Bác (Tiêu Chính Nam) hay lang thang khắp nơi, thu thập bằng chứng để làm sáng tỏ các vụ án huyền bí trong lòng thành phố. Ngoài nhân vật cảnh sát do Trương Dĩnh Khang thủ vai, Phó Tử Bác còn gặp gỡ nhà dân tộc học Phan Đóa Lạp (Lâm Hạ Vy). Trong mỗi vụ án, Đóa Lạp luôn cho rằng hung thủ đã dựng lên truyền thuyết tà ma để che đậy tội ác. Thực sự điều gì đang núp bóng sau mỗi án mạng? Là những tính toán tinh vi của kẻ thủ ác hay những cấm kị ma quỷ từ thế giới bên kia.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2019, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tiêu Chính Nam","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""},{"name":"Trương Dĩnh Khang","avatar":""},{"name":"Lâm Hạ Vy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Mười Hai Truyền Thuyết","十二傳說"]', 1784690324376);
