INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-tinh-yeu', 'Phép Màu Tình Yêu', 'Yehh Jadu Hai Jinn Ka!', 'https://phimimg.com/upload/vod/20250310-1/b089960e75d3c8773abfc08caece31d9.jpg', 'https://phimimg.com/upload/vod/20250310-1/a3494e14bd0bdeffef39ff259dd71277.jpg', '<p>&#39;Phép màu tình yêu&#39; – một xuất phẩm có nội dung hư cấu được lấy cảm hứng từ những câu chuyện thần thoại dân gian, nội dung xoay quanh chuyện tình lãng mạn giữa chàng trai bị phép thuật của yêu ma khống chế – Aman và cô gái nghèo tốt bụng mang trái tim thiên thần – Roshni... Một bộ phim giả tưởng hiện đại, với những nhân vật hư cấu nhưng đã tạo nên câu chuyện đầy kịch tính, hứa hẹn sẽ cuốn hút người xem theo từng tập phim.</p>', 'Hoàn Tất (164/164)', 164, 'series', 'completed', 7, 2019, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Aditi Sharma","avatar":""},{"name":"vaibhavi kapoor","avatar":""},{"name":"Shehzada Dhami","avatar":""},{"name":"Vikram Singh Chauhan","avatar":""},{"name":"Jaswinder Gardner","avatar":""},{"name":"Shruti Sharma","avatar":""},{"name":"Gouri Agarwal","avatar":""},{"name":"Garima Vikrant Singh","avatar":""},{"name":"Richa Bhattacharya","avatar":""},{"name":"Seema Azmi","avatar":""},{"name":"Himani Sahani","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yehh Jadu Hai Jinn Ka!"]', 1784690324376);
