INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhom-bat-ma', 'Nhóm bắt ma', 'Typewriter', 'https://phimimg.com/upload/vod/20250308-1/a56adaba7e331524ac198ce7791078d1.jpg', 'https://phimimg.com/upload/vod/20250308-1/46b56b57e7596de71b70d03469a59077.jpg', '<p>Ba người bạn trẻ ở Goa lên kế hoạch săn ma tại căn biệt thự cũ, nhưng khi một gia đình mới chuyển đến, quá khứ bị chôn vùi của căn nhà dần được hé mở một cách đáng sợ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Mikhail Gandhi","avatar":""},{"name":"Sara Gesawat","avatar":""},{"name":"Palomi Ghosh","avatar":""},{"name":"Sameer Kochhar","avatar":""},{"name":"Palash Kamble","avatar":""},{"name":"Meenacshi Martins","avatar":""},{"name":"K.C. Shankar","avatar":""},{"name":"Aaryansh Malviya","avatar":""},{"name":"Aarnaa Sharma","avatar":""},{"name":"Jisshu Sengupta","avatar":""},{"name":"Harish Khanna","avatar":""},{"name":"Purab Kohli","avatar":""},{"name":"Kanwaljit Singh","avatar":""},{"name":"Masood Akhtar","avatar":""},{"name":"Ramakant Dayma","avatar":""},{"name":"Bijou Thaangjam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Typewriter"]', 1784690324376);
