INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-han-hoa-phan-1', 'Nhật Ký Hán Hoá (Phần 1)', 'God Troubles Me (Season 1)', 'https://phimimg.com/upload/vod/20250308-1/6e52f1891ea75465c8eeedd7ab5032db.jpg', 'https://phimimg.com/upload/vod/20250308-1/2287bde4f34d812c70bbcda8c8080a9e.jpg', '<p>Trong thế kỷ 21, ba cõi người, thần và yêu mất thăng bằng do sự phát triển nhanh chóng của xã hội loài người. Nhóm các thần và yêu đến thế giới loài người để tìm kế hoạch cứu rỗi. Tô Mạc Đình là một cô gái trẻ hoạt động xã hội với thân phận là Con của Thần và Quỷ. Sau khi bị bố mẹ mời ra khỏi nhà với lý do tự lập và hoàn thiện bản thân, cô đã đụng độ hai vị thần đẹp trai, dễ thương: Thiên Cơ Tinh - người cũng sống trong thế giới và Địa Khôi - con quỷ mèo bí ẩn, điềm tĩnh và lạnh lùng. Dưới sự dẫn dắt của Thổ Địa, cả ba thành lập một nhóm cứu rỗi và bắt đầu những công việc hàng ngày hài hước và thót tim.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Feifei Qiao","avatar":""},{"name":"Zhen Wang","avatar":""},{"name":"Xin Teng","avatar":""},{"name":"Chen Siyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Han Hua Ri Ji","Hanhua Riji","한화일기","Божества беспокоят меня","Дневник культурной адаптации","God Troubles Me","汉化日记"]', 1784690324376);
