INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-ruong-phan-2', 'Mục Ruỗng (Phần 2)', 'Rotten (Season 2)', 'https://phimimg.com/upload/vod/20250308-1/7bf22335e7382119ef1fd01daf200d46.jpg', 'https://phimimg.com/upload/vod/20250308-1/bab3303526705f1fc3439a1570daa662.jpg', '<p>Khám phá những bí mật đằng sau đường và sô-cô-la, giá trị thực sự của bơ và nước đóng chai, và thế giới hay thay đổi của thực liệu rượu và cần sa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Latif Nasser","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["腐烂","부패의 맛","Rotten"]', 1784690324376);
