INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-gio-thoi', 'Khi gió thổi', 'The Wind Blows', 'https://phimimg.com/upload/vod/20250308-1/29a40bab7fd2925c41fa8dba417b716a.jpg', 'https://phimimg.com/upload/vod/20250308-1/98dd02757f5eae34b0266862588716ef.jpg', '<p>Gió Không Ngừng Thổi kể về Do Hoon và So Jin là một cặp vợ chồng đã kết hôn. Một ngày, Do Hoon phát hiện ra mình mắc phải căn bệnh Alzheimer, vì vậy anh quyết định ly hôn với Soo Jin vì lo lắng cho tương lai của cô. Và rồi cặp đôi chia tay. Sáu năm sau, định mệnh khiến họ gặp lại nhau một lần nữa.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kam Woo-sung","avatar":""},{"name":"Kim Ha-neul","avatar":""},{"name":"Kim Sung-cheol","avatar":""},{"name":"Kim Ga-eun","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Yoon Ji-hye","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name":"Jeon Guk-hyang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["风在吹","바람이분다","The Wind Blows","바람이 분다"]', 1784690324376);
