INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-vung-harlem-phan-1', 'Bố Già Vùng Harlem (Phần 1)', 'Godfather Of Harlem (Season 1)', 'https://phimimg.com/upload/vod/20250308-1/10fd97dfa2fcf0367b8e6719428ed44d.jpg', 'https://phimimg.com/upload/vod/20250308-1/889a1f5ff47531da2bca20c1a2fdfb42.jpg', '<p>Lấy cảm hứng từ trùm tội phạm khét tiếng Bumpy Johnson, người sau mười năm trong tù trở về vào đầu thập niên 1960 và chứng kiến khu phố từng dưới quyền kiểm soát của mình rơi vào hỗn loạn. Với những con phố nay nằm trong tay mafia Ý, Bumpy quyết tâm giành lại vị thế của mình ở Harlem.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Forest Whitaker","avatar":""},{"name":"Ilfenesh Hadera","avatar":""},{"name":"Antoinette Crowe-Legacy","avatar":""},{"name":"Lucy Fry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Крестный отец Гарлема","Godfather of Harlem"]', 1784690324376);
