INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('na-tra-ma-dong-giang-the', 'Na Tra: Ma Đồng Giáng Thế', 'Ne Zha', 'https://phimimg.com/upload/vod/20250223-1/905d107f2e45c42e465b8fe54a7ba28f.jpg', 'https://phimimg.com/upload/vod/20250223-1/e10b13bc61ffa46300f7821e682b0c4f.jpg', '<p>Từ thuở xa xưa, tinh hoa đất trời hội tụ thành một viên ngọc chứa đựng năng lượng khổng lồ. Nguyên Thủy Thiên Tôn đã phân tách viên ngọc này thành 1 viên Linh Châu và 1 viên Ma Hoàn. Viên Linh Châu sẽ đầu thai thành một anh hùng cứu thế, phò trợ nhà Chu. Trong khi đó, Ma Hoàn sẽ tạo ra một Ma Vương tàn sát thiên hạ. Để ngăn chặn thảm họa, Nguyên Thủy Thiên Tôn đã hạ chú để sau 3 năm Ma Vương sẽ bị Thiên kiếp tiêu diệt. Liệu Na Tra có đủ sức để thay đổi Thiên mệnh?</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Lü Yanting","avatar":""},{"name":"Joseph","avatar":""},{"name":"Han Mo","avatar":""},{"name":"Chen Hao","avatar":""},{"name":"Lü Qi","avatar":""},{"name":"Yang Wei","avatar":""},{"name":"Zhang Jiaming","avatar":""},{"name":"He Yuxiang","avatar":""},{"name":"Ren Junpeng","avatar":""},{"name":"Da Hai","avatar":""},{"name":"Xingliner","avatar":""},{"name":"Tao Yuan","avatar":""},{"name":"Li Nan","avatar":""},{"name":"Liu Linzhu","avatar":""},{"name":"Yu Chen","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ne Zha","哪吒","Nezha","Ne Zha: Birth of the Demon Child","ناچا : ميلاد الطفل الشيطان","Nezha: Zrození dětského démona","Ne zha zhi mo tong jiang shi","Nezha - El renacer de un dios","哪吒之魔童降世","너자","나타지마동강세"]', 1784690