INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-gian', 'Nội Gián', 'Spy Tracker', 'https://phimimg.com/upload/vod/20250218-1/727ab4d2b4415418bc5cc37b0a31ec0e.jpg', 'https://phimimg.com/upload/vod/20250218-1/caa14e0ec51878af84c92c11c1118b4e.jpg', '<p>Là dự án có tầm quan trọng lớn lao, công trình nghiên cứu vật liệu chế tạo tàu sân bay trở thành mục tiêu của các tổ chức gián điệp quốc tế. Để bảo vệ công trình, một đội đặc nhiệm bao gồm các nhân tố tinh anh trong lực lượng an ninh được thành lập. Không chỉ mang đề tài gián điệp, phim còn khắc họa sinh động một cuộc chiến công nghệ giữa các phe thù địch với những bậc thầy máy tính và các vũ khí tối tân.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Trác Văn","avatar":""},{"name":"Lý Lâm","avatar":""},{"name":"Trương Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Spy Tracking","Die Hai Zhui Zong","谍海追踪"]', 1784690324376);
