INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hong-sat-thu', 'Bóng Hồng Sát Thủ', 'Maria', 'https://phimimg.com/upload/vod/20250211-1/1390b7e043f63440bb71890460ea3ce2.jpg', 'https://phimimg.com/upload/vod/20250211-1/b338af1b6ccfb7113ff26f1d56560e30.jpg', '<p>Lily là nữ sát thủ của tổ chức &quot;Bông Hồng Đen&quot;, cô phản bội lại tổ chức để chọn cuộc sống bình thường như bao người. 7 năm sau khi biết cô còn sống tổ chức sát thủ đã cho thành viên của mình xử lý cô và cả gia đình. Jill chứng kiến cái chết của chồng con tại nhà mình, cô đã lên kế hoạch tàn sát lại tổ chức giết người này.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Cristine Reyes","avatar":""},{"name":"Ivan Padilla","avatar":""},{"name":"KC Montero","avatar":""},{"name":"Ronnie Lazaro","avatar":""},{"name":"Freddie Webb","avatar":""},{"name":"Guji Lorenzana","avatar":""},{"name":"Johanna Rish Tongcua","avatar":""},{"name":"Jennifer Lee","avatar":""},{"name":"Cindy Miranda","avatar":""},{"name":"Andrea Del Rosario","avatar":""},{"name":"Miel Manalang","avatar":""},{"name":"Johnny Revilla","avatar":""},{"name":"Ronnie Liang","avatar":""},{"name":"L.A. Santos","avatar":""},{"name":"Enzo De Guia","avatar":""},{"name":"Malay Rodriguez","avatar":""},{"name":"Ronald M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Maria - Tagalog","มาเรีย ผู้หญิงทวงแค้น","Maria"]', 1784690324376);
