INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-chat-cua-su-lang-man', 'Bản chất của sự lãng mạn', 'Be Melodramatic', 'https://phimimg.com/upload/vod/20250116-1/bdbeee79a22f74715589e68954ae24f7.jpg', 'https://phimimg.com/upload/vod/20250116-1/3a57fde29388ce91c911115ccbd5e015.jpg', '<p>Bản Chất Của Lãng Mạn (Be Melodramatic): Im Jin Joo, Lee Eun Jung và Hwang Han Joo là những người bạn thân đã bước vào ngưỡng tuổi 30.

Hwang Han Joo là trưởng nhóm tiếp thị cho một công ty sản xuất phim truyền hình. Cô là bà mẹ đơn thân đấu tranh để cân bằng giữa công việc và cuộc sống cá nhân khi nuôi dạy một đứa trẻ.

Im Jin Jin là một biên kịch với nhiều thăng trầm cảm xúc và một cá tính độc đáo. Mặc dù cô ấy là một biên kịch nhưng cô lại cố gắng viết kịch bản của mình theo phong cách văn học.

Lee Eun Jung là đạo diễn phim tài liệu. Cô điều hành một công ty sản xuất riêng, mặc dù cô chính là nhân viên duy nhất. Bỗng một trong số những bộ phim của cô trở nên nổi tiếng chỉ sau một đêm</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Chun Woo-hee","avatar":""},{"name":"Jeon Yeo-been","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Ahn Jae-hong","avatar":""},{"name":"Gong Myeong","avatar":""},{"name":"Yun Ji-on","avatar":""},{"name":"Lee You-jin","avatar":""},{"name":"Lee Ju-bin","avatar":""},{"name":"Baek Ji-won","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Han Jun-woo","avatar":""},{"name":"Kim Young-ah","avatar":""},{"name":"Kim Myeong-jun","avatar":""},{"name":"Ryu Abel","avatar":""},{"name":"Seo Sang-won","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Baek Soo-hee","avatar":""},{"name":"Jung Seung-kil","avatar":""},{"name":"Park Hyeong-su","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["浪漫的体质","Melo ist meine Natur","Melo体质","恋愛体質 30歳になれば大丈夫","Melo Suits Me","Особенности мелодрамы","30 แล้วไง หัวใจยังไหว","Melo is My Nature","Be.Melodramatic","멜로가 체질"]', 1784690324376);
