INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-bi-mat-cua-nang-thu-ky', 'Cuộc đời bí mật của nàng thư ký', 'The Secret Life of My Secretary', 'https://phimimg.com/upload/vod/20250116-1/5eb2b929d37e6dc62c265a052f967ad1.jpg', 'https://phimimg.com/upload/vod/20250116-1/aa5e953e8439b3bb6343d23e67f6f4c6.jpg', '<p>Yêu Từ Cái Nhìn Đầu Tiên xoay quanh câu chuyện tình yêu giữa chàng giám đốc &quot;mặt lạnh&quot; Do Min Ik (Kim Young Kwang) và cô nàng thư kí &quot;bất cần&quot; Jung Gal Hee (Jin Ki Joo). Với vẻ ngoài điển trai nhưng sở hữu tính khí thất thường, hình tượng của Do Min Ik sẽ khiến khán giả liên tưởng tới chủ tịch Lee Young Joon của What’s Wrong With Secretary Kim (tựa Việt: Thư Kí Kim Sao Thế?). Bên cạnh đó, nàng thư ký Jung Gal Hee luôn hết lòng làm theo những chỉ thị &quot;kì dị&quot; của chàng cấp trên khó ở, khiến khán giả nhớ ngay tới Kim Mi So, người duy nhất có thể &quot;trị&quot; được sếp của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Young-kwang","avatar":""},{"name":"Jin Ki-joo","avatar":""},{"name":"Kim Jae-kyung","avatar":""},{"name":"Koo Ja-sung","avatar":""},{"name":"Jung Ae-ri","avatar":""},{"name":"Kim Min-sang","avatar":""},{"name":"Kim Byung-choon","avatar":""},{"name":"Baek Hyun-joo","avatar":""},{"name":"Seo Dong-won","avatar":""},{"name":"Kim Ji-min","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Choi Tae-hwan","avatar":""},{"name":"Han Ji-Sun","avatar":""},{"name":"Son San","avatar":""},{"name":"Choi Yun-la","avatar":""},{"name":"Kwon So-hyun","avatar":""},{"name":"Lee Seung-Hyung","avatar":""},{"name":"Kim Hee-jung","avatar":""},{"name":"Song J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182d