INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-waikiki-2', 'Nhà Trọ Waikiki 2', 'Eulachacha Waikiki 2', 'https://phimimg.com/upload/vod/20250116-1/84c8b19d2d3f363ef897f860711359ba.jpg', 'https://phimimg.com/upload/vod/20250116-1/a0ec6a317069226643d5ca11aa0fb811.jpg', '<p>Nhà Trọ Waikiki 2 kể về Lee Joon-Ki (Lee Yi-Kyung) là một diễn viên kém nổi tiếng. Anh điều hành nhà trọ Waikiki nhưng nơi này đang đối mặt với phá sản. Để vực lại nhà nghỉ, Lee Joon-Ki lôi kéo bạn trung học của mình là Cha Woo-Sik (Kim Sun-Ho) và Kook Ki-Bong (Shin Hyun-Soo) đầu tư vào nơi này. Cha Woo-Sik là một người khó tính và muốn trở thành ca sĩ. Vì Lee Joon-Ki, anh dồn hết tiền của vào Waikiki. Kook Ki-Bong từng là tuyển thủ bóng chày đầy hứa hẹn nhưng giờ chỉ chơi ở những giải đấu nhỏ. Vì Lee Joon-Ki, anh cũng dồn hết tiền của vào Waikiki. Cùng với 3 người đàn ông này, Han Soo-Yeon (Mun Ka-Young), Kim Jung-Eun (Ahn So-Hee) và Cha Yoo-Ri (Kim Ye-Won) cũng bắt đầu sống tại Waikiki.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Sun Ho","avatar":""},{"name":"Lee Yi Kyung","avatar":""},{"name":"Shin Hyun Soo","avatar":""},{"name":"Mun Ka Young","avatar":""},{"name":"Ahn So Hee","avatar":""},{"name":"Kim Ye Won","avatar":""},{"name":"Jeon Su Kyeong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["加油吧威基基","مرحبا بكم في وايكيكي","ไวกีกิ เกสต์เฮาส์อลเวง","Сміх у Вайкікі","Ласкаво просимо до Вайкікі","Eulachacha Waikiki","Welcome to Waikiki 2","으라차차 와이키키"]', 1784690324377);
