INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-va-lua-doi', 'Âm mưu và lừa dối', 'The Lies Within', 'https://phimimg.com/upload/vod/20250116-1/dfc1d8bbf0e412905c09a8dd6fcceb0c.jpg', 'https://phimimg.com/upload/vod/20250116-1/dca0faa5197248b5c6390486a490c0f3.jpg', '<p>Ai Cũng Dối Lừa kể về Jo Tae Sik ( Lee Min Ki ) từng là một thám tử tài ba, nhưng giờ anh lại mong mỏi một cuộc sống bình thường. Vì điều này, Jo Tae Sik đã xin chuyển đến một trạm cảnh sát ở một ngôi làng nhỏ không có nhiều cư dân. Tuy nhiên trong lúc đó Jo Tae Sik lại nhận được một vụ án liên quan đến cái chết của Nhà lập pháp Kim Seung Chul. Ông ta chết trong một tai nạn xe hơi, nhưng Jo Tae Sik cảm thấy rằng vụ tai nạn xe hơi không quá rõ ràng và sau đó con rể của nhà lập pháp cũng đã mất tích.

Trong khi đó, Kim Seo Hee (Lee Yoo Young) là con gái út của nhà lập pháp quá cố và chồng cô hiện đang mất tích. Cô kết hôn với chồng để mang lại lợi ích cho cả hai gia đình, nhưng mối quan hệ của họ không được tốt đẹp cho lắm. Kim Seo Hee trở thành một nhà lập pháp để tìm ra sự thật đằng sau cái chết của cha cô và cứu người chồng mất tích của cô. Jo Tae Sik và Kim Seo Hee sớm phát hiện ra một âm mưu và cố gắng tiết lộ sự thật</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee You-young","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"On Ju-wan","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Kim Si-eun","avatar":""},{"name":"Yun Jong-seok","avatar":""},{"name":"Kim Jong-soo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Lies Within","所有人的謊言","大家的謊言","Everyone''s Lie","모두의 거짓말"]', 1784690324377);
