INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rang-buoc-phan-1', 'Ràng Buộc (Phần 1)', 'BONDING (Season 1)', 'https://phimimg.com/upload/vod/20250115-1/53f30b5c26f48c8a77964ec31b9a2cd9.jpg', 'https://phimimg.com/upload/vod/20250115-1/976318eeb8b0006a8c87371ecd39771c.jpg', '<p>Nữ nghiên cứu sinh tại Thành phố New York với nghề tay trái là nữ bạo dâm tuyển cậu bạn thân đồng tính hồi trung học làm trợ lý.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zoe Levin","avatar":""},{"name":"Brendan Scannell","avatar":""},{"name":"Micah Stock","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["绑定","BONDiNG","Связь","Bonding"]', 1784690324377);
