INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-1', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 1)', 'Dr. STONE (Season 1)', 'https://phimimg.com/upload/vod/20241009-1/23104870287ee2f4de302580ddff2d2a.jpg', 'https://phimimg.com/upload/vod/20241009-1/2132b555c4c90b750782bfe453edfac2.jpg', '<p>Trong nháy mắt, toàn bộ nhân loại đã bị hoá đá bởi 1 hiện tượng kì bí. Phải đến vài nghìn năm sau, Senku – cậu thiếu niên có khả năng nghiên cứu khoa học trời sinh mới được thức tỉnh. Đối mặt với sự diệt vong của cả một nền văn minh do thế giới đá (Stone world) tạo ra, Senku đã quyết định dùng sức mạnh khoa học mà mình có để hồi sinh lại toàn bộ thế giới. Từ đó, những cuộc phiêu lưu mạo hiểm chưa từng có để tạo ra một thế giới mới đã được bắt đầu!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小林裕介","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Доктор Стоун","石纪元","新石纪","石纪元 科学与未来 第2部分","Dr.STONE","डॉ. स्टोन","ドクターストーン","Dr.STONE STONE WARS","Dr.STONE (ドクターストーン)","Dr.STONE NEW WORLD","Dr.STONE SCIENCE FUTURE","닥터스톤","닥터스톤 4기","Доктор Стоун: Каменные войны","دكتور ستون","طبيب الحجر","Dr. STONE 新石紀","Dr. STONE WARS 新石紀 戰爭","Dr. STONE NEW WORLD 新石紀-新世界","Dr. STONE 龍水","石紀元","Dr. STONE: Stone Wars","Dr. STONE: New World","Dr. STONE: Science Future","Doctor Stone","Tiến Sĩ Đá","Tiến Sĩ Đá: Vương Quốc Khoa Học","Tiến S