INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-huyen-bi-phan-1', 'Hội Huyền Bí (Phần 1)', 'Los Espookys (Season 1)', 'https://phimimg.com/upload/vod/20250111-1/b0300bd34f046ac4848fe8519acb00c4.jpg', 'https://phimimg.com/upload/vod/20250111-1/f4d33baf0d7c151bbc6ba95f3cc400c8.jpg', '<p>Một nhóm bạn đam mê những thứ rùng rợn và biến sở thích thành việc làm ăn, đem đến nỗi kinh hãi cho những ai muốn thử cảm giác mạnh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 11, 2019, 'Vietsub', 'FHD', 'Chile', 0, '[{"name":"Bernardo Velasco","avatar":""},{"name":"Julio Torres","avatar":""},{"name":"Ana Fabrega","avatar":""},{"name":"Cassandra Ciangherotti","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["埃斯普基斯","墨西哥异想城","לוס אספוקיס","לוס אספוקיז","Mexico City: Only Good Things Happen","Los Espookys"]', 1784690324377);
