INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nu-hoa-bat-khi', 'Tiểu Nữ Hoa Bất Khí', 'I Will Never Let You Go', 'https://phimimg.com/upload/vod/20250111-1/40af788888df72dbcca1bde7aa500e69.jpg', 'https://phimimg.com/upload/vod/20250111-1/2b0eac6a6f08de81ee7c8929b117af33.jpg', '<p>Bộ phim Tiểu Nữ Hoa Bất Khí được chuyển thể từ tiểu thuyết cùng tên của tác giả Trang Trang. Theo nguyên tác, nữ chính Hoa Bất Khí (Lâm Y Thần) được chàng trai tên Mạc Nhược Phỉ nhận nuôi từ nhỏ, hắn dạy cô ăn xin, trộm cắp, lừa đảo... để sinh tồn. Trong một lần kết hôn giả để lừa tiền, Hoa Bất Khí và Mạc Nhược Phỉ cùng trốn chạy và rơi xuống vực. May mắn là cả hai đều thoát chết và xuyên không về thời cổ đại. Trong khi Nhược Phỉ tốt số hơn được sống trong nhung lụa giàu sang thì Bất Khí lại phải tiếp tục số kiếp ăn xin nghèo khổ. Chưa hết, sau khi người ăn mày nhận nuôi cô qua đời, Bất Khí một thân một mình chui vào ổ chó, uống sữa chó để sống sót qua mùa đông lạnh giá...</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ariel Lin","avatar":""},{"name":"Vin Zhang","avatar":""},{"name":"Austin Lin","avatar":""},{"name":"Zhang Xinyu","avatar":""},{"name":"Tiara Huang","avatar":""},{"name":"Sun Zujun","avatar":""},{"name":"Hu Caihong","avatar":""},{"name":"Gao Kaiyuan","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"Xing En","avatar":""},{"name":"Wang Ruolin","avatar":""},{"name":"Song Wenzuo","avatar":""},{"name":"Bao Yanxi","avatar":""},{"name":"Chu Han","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["I Will Never Let You Go","Nunca Te Dejaré Ir","Легенда о Хуа Буци","小女花不弃"]', 1784690324377);
