INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-truong-cung-shin', 'Đến Trường Cùng Shin', 'Shinchan School Time', 'https://phimimg.com/upload/vod/20250109-1/ae758c3a1286d880ccd4a907c49e5ac3.jpg', 'https://phimimg.com/upload/vod/20250109-1/9812f17b832385d71a659c0c3150e06f.jpg', '<p>Shin bắt đầu ngày mới bằng việc thường xuyên trễ chuyến xe buýt đến trường mẫu giáo. Tuy vậy, ở lớp Shin và các bạn luôn tìm được vô vàn niềm vui cũng như trải qua nhiều tình huống đáng nhớ cùng cô Ageo và thầy hiệu trưởng đáng mến.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 12, 2019, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Крайон Шин-чан","蜡笔小新","Crayon Shin-Chan","Shin Chan","Shin Chan (1992)","Shin-chan","Shin-Chan","Kureyon Shin Chan","짱구는 못말려","เครยอนชินจัง","ชินจัง","蠟筆小新","クレヨンしんちゃん"]', 1784690324377);
