INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin', 'Shin', 'Cậu Bé Bút Chì', 'https://phimimg.com/upload/vod/20250109-1/0d5ed7b632f6dc92b4761c7ceb570249.jpg', 'https://phimimg.com/upload/vod/20250109-1/d1a22724b4e156eaa9e701bc9b632585.jpg', '<p>Shin - Cậu bé bút chì chuyển thể từ bộ truyện tranh ăn khách của Nhật Bản do họa sĩ Usui Yoshito sáng tác và minh họa. Nhân vật chính của bộ phim là Shin (tên viết tắt của Shinnosuke) - một cậu bé 5 tuổi sống trong một gia đình Nhật Bản bình thường, có bố là trưởng nhóm công ty Futaba, mẹ là Misae - một bà nội trợ. Chú bé Shin và gia đình có thể coi là một gia đình biểu tượng cho tầng lớp trung lưu ở Nhật Bản, một gia đình được lấy hình mẫu từ bất kỳ gia đình nào trong xã hội Nhật Bản thời nay.&nbsp;</p>', 'Hoàn Tất (300/300)', 300, 'hoathinh', 'completed', 11, 2019, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Akiko Yajima","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Mari Mashiba","avatar":""},{"name":"Chie Sato","avatar":""},{"name":"Rokuro Naya","avatar":""},{"name":"Michie Tomizawa","avatar":""},{"name":"Teiyu Ichiryusai","avatar":""},{"name":"Yumi Takada","avatar":""},{"name":"Tamao Hayashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Крайон Шин-чан","蜡笔小新","Crayon Shin-Chan","Shin Chan","Shin Chan (1992)","Shin-chan","Shin-Chan","Kureyon Shin Chan","짱구는 못말려","เครยอนชินจัง","ชินจัง","蠟筆小新","クレヨンしんちゃん"]', 1784690324377);
