INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-dong-dau-doi', 'Rung Động Đầu Đời', 'My First First Love', 'https://phimimg.com/upload/vod/20250103-1/ab7712d2b5d0b427849b45635814c043.jpg', 'https://phimimg.com/upload/vod/20250103-1/0a4725f77c1a0140d10aa3cb0f69ab39.jpg', '<p>Rung Động Đầu Đời là một bộ phim tình cảm lãng mạn về tình yêu, tình bạn và cả những mơ mộng của tuổi trẻ.Yoon Tae Oh và Han Song Yi là một đôi bạn thân 20 năm và không có sự tồn tại của bất cứ tình cảm nào khác. Seo Do Hyun là bạn trai của Han Song Yi và cũng là bạn thân của Yoon Tae Oh. Liệu có tồn tại tình bạn đúng nghĩa giữa 2 người khác giới? Mối quan hệ của bạn thân của người yêu sẽ đi đến đâu?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Soo","avatar":""},{"name":"Jung Chae Yeon","avatar":""},{"name":"Jung Jin Young","avatar":""},{"name":"Choi Ri","avatar":""},{"name":"Kang Tae Oh","avatar":""},{"name":"Hong Ji Yoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My First First Love","Потому что это моя первая любовь","첫사랑은 처음이라서"]', 1784690324377);
