INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-tuoi-18', 'Khoảnh Khắc Tuổi 18', 'At Eighteen', 'https://phimimg.com/upload/vod/20250103-1/07747ebd732536cf97c52305584c4a52.jpg', 'https://phimimg.com/upload/vod/20250103-1/8d5c29bdb99355fd580d64c8b96feb68.jpg', '<p>Khoảnh Khắc Tuổi 18 (Moment at Eighteen) kể về cuộc sống và ước của những cô cậu học sinh đang ở độ tuổi 18. Họ sẽ nhìn nhận thực tế vào những khoảnh khắc của cuộc đời, những khoảnh khắc mà tất cả chúng ta có thể đã trải qua lúc này hay lúc khác. Ong Seong Woo sẽ hóa thân vào Choi Jun Woo, cậu sống trong sự cô đơn và nó đã trở thành thói quen. Mặc dù Choi Jun Woo sẽ khiến người đối diện thiếu thiện cảm ngay từ cái nhìn đầu tiên, nhưng đấy chỉ đơn giản là anh ấy luôn cô đơn và không biết thể hiện cảm xúc của mình. Dưới bỏ bộc thu mình, Jun Woo vẫn là một chàng trai trẻ ngốc nghếch và dễ thương.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ong Seong-wu","avatar":""},{"name":"Kim Hyang-gi","avatar":""},{"name":"Shin Seung-ho","avatar":""},{"name":"Kang Ki-young","avatar":""},{"name":"Sim Yi-young","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Choi Jae-woong","avatar":""},{"name":"Moon Bin","avatar":""},{"name":"Jung Young-ju","avatar":""},{"name":"Jung Hyeon-jun","avatar":""},{"name":"Yoo In-soo","avatar":""},{"name":"Han Sung-min","avatar":""},{"name":"Kim Bo-yoon","avatar":""},{"name":"Moon Joo-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Moment of Eighteen","Memorias adolescentes","لحظة في الثامنة عشرة","เพราะเธอคือรักแรก","Moment at Eighteen","18 Moments","열여덟의 순간"]', 