INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marvels-jessica-jones-phan-3', 'Marvel''s Jessica Jones (Phần 3)', 'Marvel''s Jessica Jones (Season 3)', 'https://phimimg.com/upload/vod/20241231-1/d65c81a109b5cd40a8021484237a6ecf.jpg', 'https://phimimg.com/upload/vod/20241231-1/d3d1e8f19288ff880c30bf6789163d88.jpg', '<p>Bị ám ảnh bởi quá khứ đau thương, Jessica Jones dùng năng lực làm thám tử tư nhằm tìm kẻ gây đau khổ cho mình trước khi hắn có thể hại ai khác ở Hell&quot;s Kitchen.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Krysten Ritter","avatar":""},{"name":"Rachael Taylor","avatar":""},{"name":"Eka Darville","avatar":""},{"name":"Benjamin Walker","avatar":""},{"name":"Carrie-Anne Moss","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Marvel - Jessica Jones","Jessica Jones","Marvel''s A.K.A. Jessica Jones","Marvel''s Jessica Jones"]', 1784690324377);
