INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-do-den-phan-2', 'Học Viện Đỏ Đen (Phần 2)', 'Kakegurui (Season 2)', 'https://phimimg.com/upload/vod/20241229-1/10582cdead13a3d9f2b8d8d1cb3beb8a.jpg', 'https://phimimg.com/upload/vod/20241229-1/e8842bda60a03f3f70338b1980408dd5.jpg', '<p>Học Viện tư thục Hyakkaou là nơi dành cho học sinh thuộc tầng lớp danh giá với một sơ yêu lý lịch cực khủng. Bạn hiểu không? Khi bạn là cậu ấm cô chiêu của một gia đình thuộc lớp quý tộc, mấy thứ như học lực tốt hay chơi thể thao giỏi là hoàn toàn không cần thiết. Vốn là kẻ sinh ra để nắm quyền lực, tất cả những gì bạn cần là một cái đầu chứa đầy mưu kế và nắm bắt được suy nghĩ người khác. Và không có cách nào luyện tập kĩ năng này tốt hơn... cờ bạc! Đúng vậy, cờ bạc gần như là &quot;môn học&quot; chính tại học viện này, không chỉ để luyện tập cái đầu, mà còn quyết định cả giai cấp trong trường. Tại học viện Hyakkaou, kẻ thắng làm vua, kẻ thua làm thú. Nhưng cho đến khi Yumeko Jabami xuất hiện, cô đã dạy cho tụi học sinh này biết thế nào là &quot;canh bạc sinh tử&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Tokutake","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Ayaka Fukuhara","avatar":""},{"name":"Karin Nanami","avatar":""},{"name":"Yuuki Wakai","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Mayu Udono","avatar":""},{"name":"Mariya Ise","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Kakegurui","狂赌之渊××","狂赌之渊XX","Kakegurui - Compulsive Gambler","賭ケグルイ(アニメ)","賭ケグルイ××","Kakegurui: Compulsive Gambler","賭ケグルイ"]', 1784690324377);
