INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-be-sieu-nang-luc-phan-2', 'Cậu Bé Siêu Năng Lực (Phần 2)', 'Mob Psycho 100 (Season 2)', 'cậu bé siêu năng lực (phần 2) mob psycho 100 (season 2) ito setsuo sakurai takahiro otsuka akio irino miyu matsuoka yoshitsugu hosoya yoshimasa fujimura ayumi tanezaki atsumi satake uki kokuryu sachi ishida akira ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ro-danh-cho-moi-nguoi', 'Bóng Rổ Dành Cho Mọi Người', 'Ahiru No Sora', 'https://phimimg.com/upload/vod/20241228-1/daa32e3603ed430f5c4cfd0dd9f55116.jpg', 'https://phimimg.com/upload/vod/20241228-1/31c729bfdfc87fb0943da1abb466116d.jpg', '<p>Kurumatani Sora là một chàng trai nhỏ bé, yếu đuối nhưng lại có niềm đam mê vô tận với bóng rổ. Cậu đã chuyển tới trường cao trung Kuzuryuu để thực hiện lời hứa với mẹ của mình rằng sẽ giành vô địch giải thi đấu đầu tiên trong cuộc đời cao trung của cậu. Vì chiều cao, dáng người nhỏ bé, nên cậu là tâm điểm của mọi sự ngược đãi, kể cả từ các thành viên trong câu lạc bộ bóng rổ. Nhưng một khi mang đôi giày của mẹ mình, cậu như thể có được một đôi cánh để bay cao, bay xa trên sân bóng. Tuy nhiên, câu lạc bộ bóng rổ nơi này lại được điều hành bởi Momoharu, một đội trưởng không hề quan tâm gì tới bóng rổ. Sora đã thách đấu người đội trưởng đó để có thể gia nhập vào câu lạc bộ. Mặc cho thành viên trong đội của Momoharu chơi bẩn trong trận thách đấu đó, Sora đã giành chiến thắng và khiến cho Momoharu, người anh trai song sinh của Momoharu là Chiaki và thành viên của đội bóng rổ nữ sinh Madoka rung động. Từ đây, với đôi cánh của một chàng vịt lùn, câu lạc bộ bóng rổ nam sinh sẽ lại gắn kết...</p>', 'Hoàn Tất (50/50)', 50, 'hoathinh', 'completed', 18, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kisho Taniyama","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Yuki Kaji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Ahiru''s Sky","篮球少年王","Ahiru no Sora","اهيرو نو سورا","أهيرو نو سورا","Команда мрії","Ахіру но Сора","あひるの空"]', 1784690324377);
