INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-loi-chuc-ngu-ngon', 'Ngàn Lời Chúc Ngủ Ngon', 'A Thousand Goodnights', 'https://phimimg.com/upload/vod/20241222-1/22e6a7d47167bfe24847c40aaa0b6496.jpg', 'https://phimimg.com/upload/vod/20241222-1/6c4639c62e84258f30e79a34e0cd69cd.jpg', '<p>Để thực hiện mong ước của cha mình và khám phá nguồn gốc của mình, Dai Tian-qing bắt đầu cuộc hành trình vòng quanh Đài Loan và tìm thấy tình yêu và sự cứu chuộc trên đường đi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2019, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Nicholas Teo","avatar":""},{"name":"Yu Han Lien","avatar":""},{"name":"Chen Bo-zheng","avatar":""},{"name":"Li Chung Lin","avatar":""},{"name":"Aining Yao","avatar":""},{"name":"Ke-Li Miao","avatar":""},{"name":"Cherry Hsieh","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["一千个晚安","일천개만안 : 천 번의 굿나잇","천 번의 굿나잇","천번의 굿나잇","Ngàn Lời Chúc Ngủ Ngon","一千個晚安"]', 1784690324377);
