INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngan-loi-chuc-ngu-ngon', 'Ngàn Lời Chúc Ngủ Ngon', 'A Thousand Goodnights', 'ngàn lời chúc ngủ ngon a thousand goodnights nicholas teo yu han lien chen bo-zheng li chung lin aining yao ke-li miao cherry hsieh 一千个晚安 일천개만안 : 천 번의 굿나잇 천 번의 굿나잇 천번의 굿나잇 ngàn lời chúc ngủ ngon 一千個晚安', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-da-bi-an', 'Viên Đá Bí Ẩn', 'Abyss', 'https://phimimg.com/upload/vod/20241222-1/10cb34acd770bc4ff32013958ea8a03b.jpg', 'https://phimimg.com/upload/vod/20241222-1/25429d3a11a3ea54b6ed2d1e1a39b492.jpg', '<p>Ko Se-Yeon (Kim Sa-Rang) là một công tố viên xinh đẹp và giỏi việc, nhưng lại bị tai nạn giao thông chết. Nhờ viên đá Abyss bí ẩn, Ko Se Yeon đã sống lại nhưng với một ngoại hình khác. Ko Se-Yeon hiện giờ (Park Bo-Young) có ngoại hình bình thường.

Viên đá Abyss bí ẩn có thể giúp người chết sống lại nhưng với ngoại hình khác. Ngoại hình mới của họ phụ thuộc vào mức độ tốt đẹp của linh hồn họ.

Cha Min (An Se-Ha) là người thừa kế một công ty mỹ phẩm. Anh thông minh, khiêm tốn, có trái tim nhân hậu nhưng lại không ưa nhìn. Cha Min bị tai nạn giao thông qua đời. Nhờ viên đá Abyss bí ẩn, anh sống lại với một ngoại hình khác. Cha Min hiện giờ (Ahn Hyo-Seop) sở hữu ngoại hình bảnh trai.

Ko Se Yeon bắt đầu làm luật sư ở một công ty luật. Còn Cha Min bắt đầu làm việc cho Ko Se Yeon ở công ty luật đó.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Bo-young","avatar":""},{"name":"Ahn Hyo-seop","avatar":""},{"name":"Lee Sung-jae","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Song Sang-eun","avatar":""},{"name":"Han So-hee","avatar":""},{"name":"Kwon Soo-hyun","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Lee Cheol-min","avatar":""},{"name":"Kim Sa-rang","avatar":""},{"name":"Ahn Se-ha","avatar":""},{"name":"Yeseo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Μαγική Άβυσσος","תהום","Eobiseu","لقاء بعد الموت","ลูกแก้วคืนวิญญาณ","Abyss","Viên Đá Bí Ẩn","어비스"]', 1784690324377);
