INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cong-to-vien', 'Nhật Ký Công Tố Viên', 'Diary of a Prosecutor', 'https://phimimg.com/upload/vod/20241220-1/dcedb443470e982c3a96313bf1142ee0.jpg', 'https://phimimg.com/upload/vod/20241220-1/b67bba1916eb0d3cc4d8157645f71c40.jpg', '<p>Một công tố viên sáng giá đe dọa làm đảo lộn thói quen buồn tẻ của những đồng nghiệp mới đang kiệt sức vì công việc khi cô được thuyên chuyển đến một thành phố tỉnh lẻ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-kyun","avatar":""},{"name":"Jung Ryeo-won","avatar":""},{"name":"Lee Sung-jae","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Jeon Seong-woo","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Baek Hyun-joo","avatar":""},{"name":"Yeseo","avatar":""},{"name":"Ahn Eun-jin","avatar":""},{"name":"Ahn Chang-hwan","avatar":""},{"name":"Jeong Jae-seong","avatar":""},{"name":"Kim Yong-hee","avatar":""},{"name":"Cha Soon-bae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Diary of a Prosecutor","Geomsanaejeon","Inside Stories of Prosecutors","Prosecutor Civil War","War of Prosecutors","검사내전"]', 1784690324377);
