INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-giap-chi-thanh-hai-mon-quyet-chien', 'Thiết Giáp Chi Thành: Hải Môn Quyết chiến', 'Kabaneri of the Iron Fortress: The Battle of Unato', 'https://phimimg.com/upload/vod/20241220-1/4e78f8463a9ca9ef7d57fde8a51c1af5.jpg', 'https://phimimg.com/upload/vod/20241220-1/a0e8a5ba7799e41fd6bf5deefe816398.jpg', '<p>Thiết Giáp Chi Thành: Hải Môn Quyết Chiến là thế giới chịu ảnh hưởng của cuộc cách mạng công nghệ, một quái vật nguy hiểm đã xuất hiện đe dọa hàng loạt tính mạng của nhân loại. Chúng có vẻ ngoài giống thây ma và gần như bất tử, muốn giết được chúng, con người phải đâm xuyên thủng quả tim được bao bọc bởi vỏ sắt thép bên ngoài. Hằng ngày, họ phải sống trong nỗi sợ hãi khi sinh vật thây ma gọi là Kanabe kia luôn sẵn sàng lây nhiễm bệnh độc cho họ. Tại quốc đảo Hinomoto, con người đã xây dựng các trạm tàu để cùng nhau sống sót và tránh khỏi lũ quái vật. Họ lui tới các trạm để sinh hoạt và kiếm sống, cũng như dựa vào sự giúp đỡ của đội quân đầu não trú nơi đầu tàu là Hayajiro. Tại đó, Ikoma, chàng kỹ sư trẻ sống tại trạm Aragane đã giúp sức xây dựng Hayajiro. Cậu đã chế tạo vũ khí bí mật có tên là Tsuranukit Zutsu dùng để chống lại sự giết chóc hung bạo của bọn quái vật.</p>', 'Hoàn Tất (3/3)', 3, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tasuku Hatanaka","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Kanae Oki","avatar":""},{"name":"Kensuke Sato","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Eiji Hanawa","avatar":""},{"name":"Rikako Aida","avatar":""},{"name":"Hideaki Tezuka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Koutetsujou no Kabaneri Movie 3: Unato Kessen","甲铁城的卡巴内利～海门决战～","Kabaneri of the Iron Fortress: The Battle of Unato","Кабанери Железной Крепости: Битва за Унато","Koutetsujou no Kabaneri: Unato Kessen","甲鉄城のカバネリ 海門決戦"]', 1784690324377);
