INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thiet-giap-chi-thanh-hai-mon-quyet-chien', 'Thiết Giáp Chi Thành: Hải Môn Quyết chiến', 'Kabaneri of the Iron Fortress: The Battle of Unato', 'thiết giáp chi thành: hải môn quyết chiến kabaneri of the iron fortress: the battle of unato tasuku hatanaka sayaka senbongi maaya uchida toshiki masuda kanae oki kensuke sato ryota osaka mariya ise shin-ichiro miki eiji hanawa rikako aida hideaki tezuka koutetsujou no kabaneri movie 3: unato kessen 甲铁城的卡巴内利～海门决战～ kabaneri of the iron fortress: the battle of unato кабанери железной крепости: битва за унато koutetsujou no kabaneri: unato kessen 甲鉄城のカバネリ 海門決戦', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-chang-nok-du', 'Chuyện Chàng Nok Du', 'The Tale of Nokdu', 'https://phimimg.com/upload/vod/20241218-1/502b7744ebcb907d293bcc435a90450c.jpg', 'https://phimimg.com/upload/vod/20241218-1/5f5d287c80e3647965e5572c6c173471.jpg', '<p>Jeon Nokdu (Jang Dong Yoon) là công tử một gia đình quý tộc. Hôn sự với vị hôn thê nhỏ tuổi do gia đình sắp xếp khiến chàng vô cùng phiền não. Để trốn tránh hôn sự sắp đặt này, Jeon Nokdu quyết định bỏ nhà ra đi bằng cách cải trang thành nữ nhân và trốn tới một ngôi làng goá phụ. Tại đây, chàng gặp được Dong Dong Joo (Kim So Hyun), một cô gái đang được đào tạo để trở thành kỹ nữ. Dù không muốn, Dong Dong Joo cũng không có lựa chọn nào khác.

Dong Dong Joo tình cờ biết được bí mật của Jeon Nokdu cũng như lý do chàng phải ẩn mình ở ngôi làng goá phụ này. Sau khi được Jeon Nokdu cứu thoát khỏi một tình thế cực kỳ hiểm nguy, Dong Dong Joo đã trở thành con gái nuôi của &quot;mẹ Nokdu&quot;. Về phía Jeon Nokdu, chàng quyết định sẽ sống ở ngôi làng goá phụ này trong vòng một năm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-yoon","avatar":""},{"name":"Kim So-hyun","avatar":""},{"name":"Kang Tae-oh","avatar":""},{"name":"Jeong Jun-ho","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Lee Moon-sik","avatar":""},{"name":"Song Geon-hee","avatar":""},{"name":"Park Da-yeon","avatar":""},{"name":"Hwang Mi-young","avatar":""},{"name":"Yoon Geumseon-ah","avatar":""},{"name":"Cho Soo-hyang","avatar":""},{"name":"Yang So-min","avatar":""},{"name":"An So-jin","avatar":""},{"name":"Song Chae-yoon","avatar":""},{"name":"Ko Gun-han","avatar":""},{"name":"Hwang In-yeop","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["조선로코 - 녹두전"]', 1784690324377);
