INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-tam-mai-moi-joseon', 'Trung Tâm Mai Mối Joseon', 'Flower Crew: Joseon Marriage Agency', 'https://phimimg.com/upload/vod/20241222-1/3b25df951bc056ddec330bb9a1d55f1e.jpg', 'https://phimimg.com/upload/vod/20241222-1/57be4ed6761f7097e6aa87d8d3a11ea2.jpg', '<p>Hoàng đế Lee Soo muốn kết hôn với Gae Ddong, nhưng vì gia thế thấp kém của cô, điều đó gần như là không thể. Để kết hôn với Gae Ddong, Lee Soo đã thuê Trung tâm mai mối mỹ nam. Trung tâm này bao gồm 3 người đàn ông đẹp trai: Ma Hoon, Do Joon và Ko Young Soo. Họ là trung tâm mai mối bậc nhất ở Joseon. Hoàng đế Lee Soo yêu cầu Trung tâm mỹ nam phải biến Gae Ddong thành một người phụ nữ quý phái.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Min-jae","avatar":""},{"name":"Gong Seung-yeon","avatar":""},{"name":"Seo Ji-hoon","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Byeon Woo-seok","avatar":""},{"name":"Go Won-hee","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Jeong Jae-seong","avatar":""},{"name":"Jung Ji-yoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Os Casamenteiros de Joseon","Flower Crew Dating Agency","花黨：朝鮮婚姻介紹所","Flower Crew: Joseon Matchmaking Maneuver Agency","Flower Crew: Joseon Marriage Agency","조선혼담공작소 꽃파당"]', 1784690324377);
