INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cuong-si', 'Tình Cuồng Si', 'Club Friday Season 11: Love Without Formula', 'https://phimimg.com/upload/vod/20241221-1/f8a1a7e44649eadbba0bd9babee6e449.jpg', 'https://phimimg.com/upload/vod/20241221-1/bf2cc5218ad9c8d85d511eaae6c0ea33.jpg', '<p>Anh chàng trăng hoa Ed quyết định hỏi cưới người bạn gái lâu năm mà không biết cô vừa phát hiện ra hành vi lăng nhăng của anh. Mãi đến khi bị bạn gái công khai khước từ lời cầu hôn trước mặt biết bao người, Ed mới bắt đầu thấy hối hận. Hành trình chuộc lỗi đầy gian nan bắt đầu từ đó. Liệu Ed có thể tìm lại tình yêu đã mất hay không?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Oat Pramote Pathan","avatar":""},{"name":"Belle Kemisara Paladesh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱的掌门人"]', 1784690324377);
