INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-2019', 'Tái Sinh', 'Sang Nang Prai', 'https://phimimg.com/upload/vod/20241221-1/c44d2272bfdcdd0c64f8a7f5e4214f84.jpg', 'https://phimimg.com/upload/vod/20241221-1/a20e644ff25b53c5d23ca4d7925a45b0.jpg', '<p>Hai chị em Thawadee và Thawalai tài sắc vẹn toàn cùng phải lòng vị đại tướng quân Phakinai. Trớ trêu thay, trái tim chàng chỉ có bóng hình của nàng Thawalai. Vì thế, người chị đã lên kế hoạch ép em gái cưới thái tử của vùng đất bên cạnh. Tuy nhiên, ngày đưa dâu, con thuyền chở Thawalai gặp bão và bị nhấn chìm. Phakinai đã cố gắng cứu được Thawalai, nhưng Thawadee thì bỏ mạng dưới đáy biển sâu. Linh hồn oán hận của Thawadee ám vào chiếc thuyền cổ và giết chết tất cả những kẻ muốn trộm kho báu ở đây. Trong khi đó, Thawalai và Phakinai được tái sinh với thân phận khác. Một lần nữa, định mệnh lại đưa ba người lại gần nhau với một bi kịch mới...</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 10, 2019, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Golf Anuwat Choocherdratana","avatar":""},{"name":"JakJaan Akhamsiri Suwanasuk","avatar":""},{"name":"Kannaporn Puangtong","avatar":""},{"name":"Aun Witaya Wasukraipaisarn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324377);
