INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-chay-dreams', 'Đội Bóng Chày Dreams', 'Hot Stove League', 'https://phimimg.com/upload/vod/20241221-1/bf95be530d660970b79da8fdf35c5005.jpg', 'https://phimimg.com/upload/vod/20241221-1/48bef5c47ca294c38495d287b21d2e36.jpg', '<p>Câu chuyện về hai nhà quản lý có mục tiêu là chuyển đội bóng chày của họ từ cuối giải đấu lên hàng đầu. Baek Seung Soo ( Nam Goong Min ) là tổng giám đốc mới được tuyển dụng của một đội bóng chày giải đấu nhỏ đang gặp khó khăn được gọi là Dreams, đứng cuối bảng xếp hạng. Trong khi đó, Lee Se Young ( Park Eun Bin ) là người quản lý hoạt động trung thành và tận tụy của đội. Cùng nhau, họ phải tìm cách xoay chuyển vận may của đội.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Namkoong Min","avatar":""},{"name":"Park Eun-bin","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Cho Byeong-kyu","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Kim Do-hyun","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Kim Ki-moo","avatar":""},{"name":"Chae Jong-hyeop","avatar":""},{"name":"Bae Min-jun","avatar":""},{"name":"Kim Jung-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["J2 Stove League","棒球大联盟","金牌救援","Seutobeurigeu","Hot Stove League","Stove League","스토브리그"]', 1784690324377);
