INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-tien', 'Tru Tiên', 'Jade Dynasty', 'https://phimimg.com/upload/vod/20241221-1/5ff49251a44e984c6267c9b3dc1709ac.jpg', 'https://phimimg.com/upload/vod/20241221-1/0a01b19966265cd133eb334066e14d8d.jpg', '<p>Bộ phim mới nhất của Tiêu Chiến, diễn viên chính trong “Trần Tình Lệnh”! Trong một đêm, cả thôn bị giết, chàng gia nhập Thanh Vân Môn trên Đại Trúc Phong, tình cờ lấy được báu vật Thiêu Hỏa Côn, từ đó rơi vào cuộc chiến giữa hai phe tà và ác! Truyền kỳ tiên hiệp phương Đông hấp dẫn đang chờ bạn~</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Meng Mei Qi","avatar":""},{"name":"Tina Tang","avatar":""},{"name":"Xinzhi Qiu","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"David Chiang","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Bryan Leung","avatar":""},{"name":"ANTHONY BAO","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324377);
