INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bangkok-ngay-den-toi', 'Bangkok Ngày Đen Tối', 'Bangkok Dark Tales', 'https://phimimg.com/upload/vod/20241221-1/1201d2afe856841cc3144cf002016b77.jpg', 'https://phimimg.com/upload/vod/20241221-1/0acb99265e9bffc80db11bfcbfbde0e7.jpg', '<p>Bangkok Ngày Đen Tối (Bangkok Dark Tales) là ba câu chuyện kinh dị hấp dẫn, xảy ra tại ba địa điểm rùng rợn khác nhau ở Bangkok. Câu chuyện đầu tiên kể về Gam - nữ doanh nhân phải làm việc đến tận đêm giao thừa. Tại công ty, cô ngồi cạnh bàn của người đồng nghiệp đã chết cách đây vài tuần. Trải nghiệm mà Gam phải đối mặt vào đêm đó đã thay đổi cuộc đời cô mãi mãi. Câu chuyện thứ hai theo chân Bee và Ann - người không bao giờ tin vào ma quỷ. Cả hai đến Bangkok lần đầu tiên. Họ thuê ngôi nhà rùng rợn từng là nơi ở của một gia đình sát nhân tàn bạo. Và câu chuyện cuối cùng xảy ra tại rạp chiếu phim chỉ cho phép hồn ma đến xem phim, nhưng có một đôi trẻ vô tình ghé thăm. Liệu cả hai có cơ hội thoát khỏi rạp phòng chiếu đó không?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tonawanik Adisorn","avatar":""},{"name":"Bankie Nuttachai Jiraanont","avatar":""},{"name":"Cherreen Nachjaree Horvejkul","avatar":""},{"name":"Yeepun Napat Banchongchitpaisal","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["บางกอก…สยอง"]', 1784690324377);
