INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-hiem-hoa-ai', 'Hiệp sĩ mặt nạ: Hiểm họa A.I.', 'Kamen Rider ZERO-ONE', 'https://phimimg.com/upload/vod/20241219-1/ec0f324b3510342b931fe66949b07105.jpg', 'https://phimimg.com/upload/vod/20241219-1/beb1d3a687da61a7340194ba0777751b.jpg', '<p>Hiệp Sĩ Mặt Nạ: Hiểm Họa A.I - Kamen Rider Zero-One, Trong tương lai khi người máy AI có mặt khắp nơi, một chàng nghệ sĩ hài bất ngờ trở thành tân chủ tịch của một tập đoàn công nghệ khổng lồ sau khi ông nội cậu qua đời. Để đối mặt với âm mưu xấu xa của tổ chức khủng bố và tập đoàn đối thủ, cậu buộc phải gánh trách nhiệm trở thành Kamen Rider để bảo vệ hòa bình cho nhân loại và người máy.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fumiya Takahashi","avatar":""},{"name":"Noa Tsurushima","avatar":""},{"name":"Ryutaro Okada","avatar":""},{"name":"Hiroe Igeta","avatar":""},{"name":"Daisuke Nakagawa","avatar":""},{"name":"Shuya Sunagawa","avatar":""},{"name":"Maynard Plant","avatar":""},{"name":"Blaise Plant","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["假面骑士Zero-One","假面骑士01","Kamen Rider 01","Kamen Rider Zero-One","Reiwa Rider 1","仮面ライダーゼロワン"]', 1784690324377);
