INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-3a-tu-gio-cac-em-la-con-tin-cua-toi', 'Lớp 3A, Từ Giờ Các Em Là Con Tin Của Tôi', 'Mr. Hiiragi''s Homeroom', 'https://phimimg.com/upload/vod/20241211-1/a4114d30bdece0d417e0b947ae532a6d.jpg', 'https://phimimg.com/upload/vod/20241211-1/ccb98d0903700812ff1fd899f8c65bcf.jpg', '<p>Vài ngày trước khi tốt nghiệp, một giáo viên khiêm tốn bắt cả lớp mình chủ nhiệm làm con tin: anh quyết tìm ra sự thật về người bạn học đã chết vì tự tử của chúng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaki Suda","avatar":""},{"name":"Mei Nagano","avatar":""},{"name":"Mio Imada","avatar":""},{"name":"Ryota Katayose","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Nana Mori","avatar":""},{"name":"Seiichi Tanabe","avatar":""},{"name":"Rina Kawaei","avatar":""},{"name":"Aki Moriyama","avatar":""},{"name":"Mayuu Yokota","avatar":""},{"name":"Riku Hagiwara","avatar":""},{"name":"Hikari Tobita","avatar":""},{"name":"Kaoru Wakabayashi","avatar":""},{"name":"Yuki Imai","avatar":""},{"name":"Yumena Yanai","avatar":""},{"name":"Mayu Hotta","avatar":""},{"name":"Fuju Kamio","avatar":""},{"name":"Shiori Akita","avatar":""},{"name":"Yun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["3 Nen A Kumi: Ima kara Mina-san wa, Hitojichi Desu","3年A組 －今から皆さんは、人質です－","3年A組 今から皆さんは、人質です","3학년 A반 -지금부터 여러분은 인질입니다-","3학년 A반: 지금부터 여러분은 인질입니다","Mr Hiiragis Homeroom","Mr.Hiiragis.Homeroom","Lớp 3A, Từ Giờ Các Em Sẽ Là Con Tin","3年A組 ―今から皆さんは、人質です―"]', 1784690324377);
