INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-trom-cap-ban-hoat-hinh-phan-1', 'Bộ ba trộm cắp: Bản hoạt hình (Phần 1)', 'Trailer Park Boys: The Animated Series (Season 1)', 'https://phimimg.com/upload/vod/20241203-1/527c8b3b4eab564024f678830efca2e6.jpg', 'https://phimimg.com/upload/vod/20241203-1/06216f9b16cac22402bbea309e33a734.jpg', '<p>Những gã trai hư hỏng nhưng được ưa thích ở Nova Scotia vẫn luôn quá lố. Giờ đây, từ sau tập cuối của mùa 12, họ đã chính thức trở thành những nhân vật hoạt hình.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mike Smith","avatar":""},{"name":"John Paul Tremblay","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"John Dunsworth","avatar":""},{"name":"Pat Roach","avatar":""},{"name":"Cory Bowles","avatar":""},{"name":"Jacob Rolfe","avatar":""},{"name":"Tyrone Parsons","avatar":""},{"name":"Sarah Dunsworth","avatar":""},{"name":"Jeanna Harrison","avatar":""},{"name":"Marguerite McNeil","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["公园男孩：动画版","公园男孩：魔菇历险记","Trailer Park Boys: The Animated Series"]', 1784690324378);
