INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-deu-biet', 'Thời Gian Đều Biết', 'See You Again', 'https://phimimg.com/upload/vod/20241203-1/5d82be83e424a71be4f3b544f2dec718.jpg', 'https://phimimg.com/upload/vod/20241203-1/8984685de9044747be2721243db0a81e.jpg', '<p>Bộ phim xoay quanh câu chuyện tình cảm của cô gái Thời Giản (Đường Yên) cùng với hai người đàn ông: Diệp Gia Thành (Đậu Kiêu) và Dịch Bái (Dương Thước). Thời Giản, 31 tuổi, trong một chuyến bay đi thăm chồng thì vô tình gặp ông chủ của tập đoàn lớn Dịch Bá. Nhưng bất ngờ máy bay gặp sự cố, Thời Giản bị va đập và bất tỉnh. Cô mơ thấy mình trở về 10 năm trước, khi vẫn còn là sinh viên đại học. Sau khi thích ứng với sự thật là mình trở về quá khứ, Thời Giản bắt đầu tìm cách trị bệnh cho mẹ và làm quen với người chồng tương lai Diệp Gia Thành. Trớ trêu thay, Dịch Bái trong thời điểm này cũng yêu cô...</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 18, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Yên","avatar":""},{"name":"Đậu Kiêu","avatar":""},{"name":"Dương Thước","avatar":""},{"name":"Lữ Nhất","avatar":""},{"name":"Lam Danh Oánh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tempo Sabe Tudo","See You Again","时间都知道"]', 1784690324378);
