INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-em-di-den-dinh-vinh-quang', 'Cùng Em Đi Đến Đỉnh Vinh Quang', 'Gank Your Heart', 'https://phimimg.com/upload/vod/20241203-1/4e932ef632b677231689fe543576339e.jpg', 'https://phimimg.com/upload/vod/20241203-1/7a70d37e4ca81f8cee641453d13d8077.jpg', '<p>&quot;Cùng Em Đi Đến Đỉnh Vinh Quang&quot; được chuyển thể từ tác phẩm &quot;Điện Cạnh Luyến Nhân&quot; của Nam Dã Lâm Nhi, kể về chàng trai Quý Hướng Không - một game thủ tài năng và luôn cố gắng không ngừng để trở thành người giỏi nhất. Tuy là một cao thủ chiến thuật và chưa bao giờ chịu thất bại nhưng Hướng Không luôn bị gắn mác gà mờ. Tình cờ, anh quen biết với Khâu Anh - một cô gái xinh đẹp, nhiệt huyết trong công việc nhưng cũng chưa bao giờ được đánh giá cao. Hai con người, một hoàn cảnh, họ khích lệ cùng nhau cố gắng và dần đạt được ước mơ.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 9, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Yibo","avatar":""},{"name":"Wang ZixuVương Tử Tuyền","avatar":""},{"name":"Nghiêm Vũ Hào","avatar":""},{"name":"Yên Hủ Gia","avatar":""},{"name":"Vương Nhất Bác","avatar":""},{"name":"Đinh Quán Sâman","avatar":""},{"name":"Yan Yuhao","avatar":""},{"name":"Ding Guan Sen","avatar":""},{"name":"Lu Xiaoyu","avatar":""},{"name":"Chai Hao Wei","avatar":""},{"name":"Gao Taiyu","avatar":""},{"name":"Hu Yun Hao","avatar":""},{"name":"Huang Xin Yao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["电竞恋人","Accompany You to the Top of the World","สู่ฝันเส้นขอบฟ้า","陪你到世界之巅"]', 1784690324378);
