INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-y-chi-ha', 'Cẩm Y Chi Hạ', 'Under The Power', 'https://phimimg.com/upload/vod/20241125-1/21c71af28571a0e2429413eb53934729.jpg', 'https://phimimg.com/upload/vod/20241125-1/ca5019360581bfecee06b1074de16c08.jpg', '<p>Triều đình xảy ra vụ án mất cắp ngân lượng, mười vạn lượng bạc được dùng để tu sửa cầu đường đã không cánh mà bay, nữ bổ khoái Viên Kim Hạ phụng mệnh hỗ trợ Cẩm y vệ Lục Dịch cùng đến Dương Châu điều tra, truy tìm số ngân lượng bị mất cắp.

Viên Kim Hạ và Lục Diệp vốn không cùng chí hướng nhưng do việc điều tra vụ án nên phải liên thủ với nhau. Hai người từ chỗ như nước với lửa đã dần có cái nhìn khác về đối phương và sau đó nảy sinh tình cảm, vòng quay số phận từ đó bắt đầu xoay quanh nhau....</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 7, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Diệp Thanh","avatar":""},{"name":"Đàm Tùng Vận","avatar":""},{"name":"Hàn Đống","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Что скрывают маски","錦衣之下","锦衣之下"]', 1784690324380);
