INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-phu-nu-be-nho-2019', 'Những Người Phụ Nữ Bé Nhỏ', 'Little Women', 'https://phimimg.com/upload/vod/20241114-1/e1009abdfd02b04dd82f727c92d4f831.jpg', 'https://phimimg.com/upload/vod/20241114-1/597653bf57e1a1ec31464f9f4e1cab6a.jpg', '<p>Bộ phim kể về câu chuyện gia đình March ở Concord, bang Massachussette, trong cuộc nội chiến. Người cha ra ngoài mặt trận, ở nhà chỉ còn Marmee cùng bốn cô con gái: Meg- cô chị cả rất &quot;người lớn&quot;, Jo - cô em thứ hai nghịch ngợm như con trai và mơ ước trở thành một nhà văn trong tương lai, Beth- cô em thứ ba yếu đuối và dịu dàng và Amy- cô em út điệu đàng và rất có tài hoạ sĩ. Họ kết bạn với cậu con trai Laurie nhà bên và đã cùng nhau có những tháng ngày vất vả nhưng thật hạnh phúc. Rồi nhiều đổi thay đã diễn ra trong gia đình March, mỗi người đi một phương, nhưng cuối cùng họ đều nhận ra rằng: gia đình là nơi bình yên và đẹp đẽ nhất trong tâm hồn họ.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Florence Pugh","avatar":""},{"name":"Eliza Scanlen","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Timothée Chalamet","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"James Norton","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"Jayne Houdyshell","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Rafael Silva","avatar":""},{"name":"Mason Alban","avatar":""},{"name":"Emily Edström","avatar":""},{"name":"Maryann Plunkett","avatar":""},{"name":"Hadle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Unge Kvinner","Mujercitas","작은 아씨들","Adoráveis Mulheres","Малки жени","小妇人","小婦人","她們","Küçük Kadınlar","Những người phụ nữ nhỏ bé","Čas deklištva","Fiicele doctorului March","Mažosios moterys","Piccole donne","Μικρές κυρίες","Kisasszonyok","Pikku naisia","نساء صغيرات","Փոքրիկ Կանայք","Little Women"]', 1784690324380);
