INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kipo-va-ky-nguyen-ky-thu-phan-1', 'Kipo Và Kỷ Nguyên Kỳ Thú (Phần 1)', 'Kipo And The Age Of Wonderbeasts (Season 1)', 'kipo và kỷ nguyên kỳ thú (phần 1) kipo and the age of wonderbeasts (season 1) karen fukuhara sydney mikayla deon cole coy stewart dee bradley baker amy landecker dan stevens sterling k. brown jee young han anna vocino jake green jeff bennett steve blum carlos alazraqui michael-leon wooley kipo e os animonstros 奇波和神奇动物的时代 kipo und die welt der wundermonster kipo y la era de los magnimales kipo et l''âge des animonstres h κίπο και η εποχή των τρανοθηρίων kipo e l''era delle creature straordinarie キポとワンダービーストの冒険 kipo and the age of wonderbeasts', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-phat-vuong-phi', 'Bạch Phát Vương Phi', 'Princess Silver', 'https://phimimg.com/upload/vod/20241108-1/d2b8de8fbfc7d9d8073b0d7597e802e6.jpg', 'https://phimimg.com/upload/vod/20241108-1/2606d6ca07a9be8a4a7116b2ee23e15e.jpg', '<p>Bạch Phát Vương Phi là câu chuyện kể về cuộc đời Mạn Yêu - Dung Nhạc trưởng công chúa của Khải Vân quốc. Vì mối bang giao giữa hai nước mà nàng được đem gả cho thất hoàng tử Lâm Thiên quốc - Ly Vương điện hạ. &nbsp;Ly Vương - Tông Chính Vô Ưu vốn là người con trai được hoàng đế yêu thích nhất, nhưng vì chứng kiến mẫu phi chết dưới tay cha ruột mà luôn căm hận ông và hoàng thất. Phó Trù từ một tướng sĩ vô danh trở thành đại tướng quân danh trấn thiên hạ lại luôn mang trong mình mối thù sâu nặng với cả hoàng tộc, đặc biệt là Ly Vương. Giữa sóng gió tranh đấu của nam nhân, người duy nhất họ làm tổn thương lại là người con gái họ yêu thương nhất. Anh em tương tàn, thiên hạ phân cách, kết cục nào cho Mạn Yêu, Tông Chính Vô Ưu và Phó Trù giữa thời loạn thế?</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 8, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Trị Đình","avatar":""},{"name":"La Vân Hi","avatar":""},{"name":"Trương Tuyết Nghênh","avatar":""},{"name":"Kinh Siêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["白发王妃","白发"]', 1784690324380);
