INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-linh-cai-chuyen-chua-ke-2019', 'Thiên Linh Cái: Chuyện Chưa Kể', 'Kumanthong The Untold Story', 'https://phimimg.com/upload/vod/20241104-1/e83548a14780771ac1bb4d86790b3df1.jpg', 'https://phimimg.com/upload/vod/20241104-1/41bcc2149b920cb26d8da62fded644c8.jpg', '<p>Dựa trên vụ án có thật, gây rúng động xã hội những năm 90 về kẻ giết người hàng loạt đầu tiên tại Việt Nam. Phim kể về Sỏi là một cô gái câm điếc, cuộc sống cô thay đổi khi cô kết hôn với Huỳnh, một thầy lang được nhiều người tin tưởng. Tuy nhiên, Sỏi dần dần nhận ra những dấu hiệu kỳ lạ của chồng mình.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Quang Tuấn","avatar":""},{"name":"Đinh Y Nhung","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Memorist","메모리스트"]', 1784690324380);
