INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-nha-kim-tieu', 'Tòa Nhà Kim Tiêu', 'Barrack O Karma', 'https://phimimg.com/upload/vod/20241101-1/cf1e9b733a334071f099ebd8b0e7b47a.jpg', 'https://phimimg.com/upload/vod/20241101-1/edfcc05736f94bd7b1bca32e8804ead6.jpg', '<p>Lưu Húc Hy (Trần Sơn Thông đóng chính) gặp phải một hiện tượng kì lạ, mỗi khi anh ta đi ngủ sẽ mơ phải những giấc mộng là những câu chuyện bí ẩn xảy ra cách thực tại đến 6 thập kỷ. Trong giấc mơ đó của Húc Hy, anh đã gặp một cô nàng kĩ nghệ làm trong ca lầu có vẻ ngoài giống với cô nàng tiếp viên hàng không sống chung toà nhà với anh có tên Dương Mẫn. Để phá giải được bí ẩn này Húc Hy phải tiếp tục đi vào trong những giấc mơ để tìm ra lời giải cho những bí ẩn chưa có câu trả lời...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2019, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joel Chan","avatar":""},{"name":"李施嬅","avatar":""},{"name":"劉江","avatar":""},{"name":"Bob Cheung Yin-Pok","avatar":""},{"name":"林子善","avatar":""},{"name":"康華","avatar":""},{"name":"Gloria Tang","avatar":""},{"name":"Geoffrey Wong Chi-Hung","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["今宵大厦","Golden Building","Gam siu daaih hah","Barrack O''Karma","Barrack OKarma","金宵大廈"]', 1784690324380);
