INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-ky-phuong', 'Thiếu Gia Kỹ Phường', 'Homme Fatale', 'https://phimimg.com/upload/vod/20241031-1/6b4b64dd5ea62da90de666a6a4d0c6fe.jpg', 'https://phimimg.com/upload/vod/20241031-1/a9f2882d02f760d73b74d54729cc3602.jpg', '<p>Một chàng trai sinh ra và lớn lên ở kỹ viện, số phận đã mặc định cho chàng bị thiên hạ khinh miệt về thân phận và địa vị thấp kém đó. Nhưng chàng đã kiên cường đứng lên để phá vỡ định kiến và thay đổi vận mệnh của chính mình.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이준호","avatar":""},{"name":"정소민","avatar":""},{"name":"최귀화","avatar":""},{"name":"예지원","avatar":""},{"name":"공명","avatar":""},{"name":"이일화","avatar":""},{"name":"Ha Jae-sook","avatar":""},{"name":"전노민","avatar":""},{"name":"강승현","avatar":""},{"name":"신은수","avatar":""},{"name":"Park Jung-won","avatar":""},{"name":"김동영","avatar":""},{"name":"조이현","avatar":""},{"name":"Kim Woo-hyuk","avatar":""},{"name":"Lee Noah","avatar":""},{"name":"Yoo Jong-yeon","avatar":""},{"name":"An Seong-won","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["妓房少爷","青楼少爷","HOMME FATALE","Homme Fatale","기방도령"]', 1784690324380);
