INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thieu-gia-ky-phuong', 'Thiếu Gia Kỹ Phường', 'Homme Fatale', 'thiếu gia kỹ phường homme fatale 이준호 정소민 최귀화 예지원 공명 이일화 ha jae-sook 전노민 강승현 신은수 park jung-won 김동영 조이현 kim woo-hyuk lee noah yoo jong-yeon an seong-won 妓房少爷 青楼少爷 homme fatale homme fatale 기방도령', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-le-hoa-dinh', 'Hạc Lệ Hoa Đình', 'Royal Nirvana', 'https://phimimg.com/upload/vod/20241029-1/8da71476c46d160a086244373e183c5e.jpg', 'https://phimimg.com/upload/vod/20241029-1/65e5f42e95c4cf6033e4028f3d57917c.jpg', '<p>Hạc Lệ Hoa Đình được cải biên dựa trên tiểu thuyết cùng tên của Tuyết Mãn Lương Viên. Nam nhân vật chính là thái tử Tiêu Định Quyền có tính cách mâu thuẫn, số phận bi kịch. Chàng là thái tử nhưng bị vua cha nghi kị. Chàng mất em gái, mất mẹ từ nhỏ, mất vợ mất con chưa ra đời, ân sư tự tử, lẻ loi hiu quạnh, phụ hoàng lạnh nhạt, gian nan qua ngày, anh em tranh đấu gay gắt, âm mưu dồn dập, sau cùng mất cả người cậu thân thiết. Tiêu Đinh Tuyền kịch liệt phản đối một cuộc nổi loạn được lên kế hoạch bởi thuộc hạ của chú mình, mặc dù mọi chuyện có thể đã quá muộn. Nữ chính A Bảo (Lý Nhất Đồng) tài hoa hơn người, thông minh trác tuyệt, là gián điệp vua cha cài vào chỗ nam chính. Nhưng theo thời gian, nàng phát hiện ra thái tử Tiêu Định Quyền khác xa với tưởng tượng về một người đàn ông đầy tham vọng mà nàng nghĩ. Cuối cùng, A Bảo đã yêu Tiêu Đinh Tuyền.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 7, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"羅晉","avatar":""},{"name":"李一桐","avatar":""},{"name":"黃志忠","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Miao Pu","avatar":""},{"name":"Jin Han","avatar":""},{"name":"鄭業成","avatar":""},{"name":"Wang Yuanke","avatar":""},{"name":"陸妍淇","avatar":""},{"name":"Liu Yitong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ROYAL NIRVANA","He Li Hua Ting","တော်ဝင်နန်း၏ ပရိယာယ်","鹤唳华亭"]', 1784690324380);
