INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-thuong-dong-day', 'Yêu Thương Đong Đầy', 'All I Want For Love Is You', 'https://phimimg.com/upload/vod/20241026-1/939a1ec03c5cf102d1b96da84c8a251e.jpg', 'https://phimimg.com/upload/vod/20241026-1/6bcd30f1c549a1d5aafcb840715ebced.jpg', '<p>Yêu Thương Đong Đầy kể về khoảng thời gian sắp đến kì thi đại học, Cố Tiểu Mãn vì muốn tiếp tục làm bạn học với nam thần Tả Ngạn của mình, liều mạng mà học tập. Nhờ vào sự cố gắng vất vả cùng với sự chỉ dạy của nam thần học bá Tả Ngạn, Cố Tiểu Mãn đạt được thành công, cùng vào một trường đại học với nam thần. Nếu như nói cuộc sống cấp 3 của hai người chỉ là có chút ngây ngô, khiến trái tim thiếu nữ của khán giả trỗi dậy. Thì ở đại học, cũng là như cũ, nhưng hai người dần dần trở nên ngọt ngào với nhau hơn.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鲁照华","avatar":""},{"name":"Liu Yuhan","avatar":""},{"name":"Xie Zhixun","avatar":""},{"name":"Han Xinyu","avatar":""},{"name":"劉胤君","avatar":""},{"name":"Yanqing Sun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["All I Want for Love is You","满满喜欢你"]', 1784690324380);
