INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-yeu-trong-mua', 'Lời Yêu Trong Mưa', 'Voice In The Rain', 'https://phimimg.com/upload/vod/20241024-1/e1875a8881216109c9581c440a9e7f21.jpg', 'https://phimimg.com/upload/vod/20241024-1/fe0596786cb425582301d0b437e5799d.jpg', '<p>Rin là một cô nàng trẻ trung, năng động làm nghề thiết kế thời trang. Cô được truyền cảm hứng từ giọng nói của một người đàn ông. Hóa ra giọng nói đó là của Tanthai, người mà cô sắp hợp tác. Anh là một người mẫu, diễn viên có ngoại hình bắt mắt nhưng không được công chúng công nhận về tài năng. Hai con người luôn cảm thấy cô đơn, trống trải trong cuộc sống bỗng chốc tìm thấy sự đồng điệu ở trái tim và khám phá ra rằng không có gì to lớn hơn âm thanh của tình yêu họ dành cho nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', '', 0, '[{"name":"Linn Mashannoad Suvanamas","avatar":""},{"name":"Na Naphat Vikairungroj","avatar":""},{"name":"Fluke Kan Kantathavorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["La voz en la lluvia","Siang Ruk Nai Sai Fon","เสียงรักในสายฝน"]', 1784690324380);
