INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-doi-co-vu', 'Sát Thủ Đội Cổ Vũ', 'The Cheerleader Escort', 'https://phimimg.com/upload/vod/20241020-1/37aa6733968604bbbb2c20192d76d562.jpg', 'https://phimimg.com/upload/vod/20241020-1/f3aff71335d46a0bc44cd6526e7094c6.jpg', '<p>Một sinh viên mới vào đội cổ vũ đã phải lòng nhà hảo tâm giúp đỡ mình. Nhưng tất cả sụp đổ khi cô biết đội của mình đều &quot;hộ tống&quot; các cựu sinh viên giàu có, người cô tương tư cũng là một trong số họ.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Alexandra Beaton","avatar":""},{"name":"Cynthia Preston","avatar":""},{"name":"Damon Runyan","avatar":""},{"name":"Carolyne Maraghi","avatar":""},{"name":"Joelle Farrow","avatar":""},{"name":"Victor Cornfoot","avatar":""},{"name":"Mikaël Conde","avatar":""},{"name":"Bukola Walfall","avatar":""},{"name":"Brittany Clough","avatar":""},{"name":"Emily Clarke","avatar":""},{"name":"Keara Graves","avatar":""},{"name":"Julia Knope","avatar":""},{"name":"Al Connors","avatar":""},{"name":"Isabella Gow","avatar":""},{"name":"Peter Michael Dillon","avatar":""},{"name":"Puja Uppal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Perfect Cheerleader","La porrista perfecta","The Cheerleader Escort"]', 1784690324380);
