INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-y-than-tham', 'Cẩm Y Thần Thám', 'Detective Of Ming Dynasty', 'https://phimimg.com/upload/vod/20241016-1/a517b7a42d29bc674b970a80cc46ca20.jpg', 'https://phimimg.com/upload/vod/20241016-1/be9c4fa372c2c432303e6b22b47232b1.jpg', '<p>Tổng binh Sơn Tây - Khuất Vĩ bị ám toán trong lúc làm nhiệm vụ, mà thanh bảo đao của ông lại rơi vào tay của giang hồ đại đạo Lục Khôn. Nữ bổ đầu Lục Phiến Môn - Thạch Y Y và Cẩm Y Vệ Lục Tân tiến hành điều tra và bắt giữ Lục Khôn. Nhưng sự thật nào đơn giản như thế. Bức màn bí mật dần được vén lên, ai mới là hung thủ thật sự?</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Văn Đông Tuấn","avatar":""},{"name":"Tưởng Dục Vĩ","avatar":""},{"name":"Vương Á Nam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["锦衣神探"]', 1784690324380);
