INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-y-than-tham', 'Cẩm Y Thần Thám', 'Detective Of Ming Dynasty', 'cẩm y thần thám detective of ming dynasty văn đông tuấn tưởng dục vĩ vương á nam 锦衣神探', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-la-cuon-bay', 'Chiếc Lá Cuốn Bay', 'The Fallen Leaf', 'https://phimimg.com/upload/vod/20240920-1/02355bdd32ac3190badabc9c6859bfe6.jpg', 'https://phimimg.com/upload/vod/20240920-1/0abec82872b51cd3d68da0fba597c01a.jpg', '<p>Phim xoay quanh cuộc đời bi kịch của cô nàng chuyển giới Nira (Baifern). Chananthawat từ nhỏ đã nhận thức được giới tính thật của bản thân, vì lẽ đó cậu và mẹ của mình luôn bị ông bố lăng nhăng đối xử tệ bạc và thường xuyên đánh đập. Sâu thẳm trong lòng Chananthawat luôn khao khát được sống với giới tính thật của mình và chỉ có mẹ cậu luôn yêu thương, chấp nhận cậu. Chananthawat muốn bố mình giống như người chú Chatchavee (Push), người đàn ông ấm áp luôn đứng về phía mẹ mình, chăm sóc và hiểu cho mình. Chananthawat cùng với sự ủng hộ của mẹ, đã quyết định làm một việc thay đổi cuộc đời của mình. Hai mẹ con quyết định rời khỏi nhà, bay sang Anh để Chananthawat thực hiện phẫu thuật chuyển giới, và trở thành một người phụ nữ xinh đẹp và quyến rũ tên Nira.Tuy nhiên, mẹ cô đã qua đời trong lúc cô thực hiện phẫu thuật ở nước ngoài và từ đó, cô về nước và sống với sự giúp đỡ của bác sĩ Benjang (Aun) với tư cách là em vợ của anh ta. Trớ trêu thay, không chỉ người chú Chatchavee mà ngay cả người bố của Nira cũng say mê nhan sắc xinh đẹp của cô, mà không biết đó chính là người thân, là đứa con mà mình ruồng bỏ năm nào. Mối tình oan nghiệt này cũng trở nên càng phức tạp hơn khi Nira cũng phải lòng người chú Chatchavee. Biết được điều đó, Rungrong (Tangmo) - vợ của Chatchavee và cũng là cô của Nira luôn coi thường tình yêu của Nira và ghen tị với cô, không ngừng tìm cách hãm hại Nira.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 8, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"Apasiri Nitibhon","avatar":""},{"name":"Rusameekae Fagerlund","avatar":""},{"name":"Witaya Wasukraipaisarn","avatar":""},{"name":"Angpao Thankorn Kanlayawuttipong","avatar":""},{"name":"Puttichai Kasetsin","avatar":""},{"name":"Chutima Naina","avatar":""},{"name":"Natha Lloyd","avatar":""},{"name":"Suppapong Udomkaewkanjana","avatar":""},{"name":"Jakkrit Amarat","avatar":""},{"name":"Yuranunt Pamornmontri","avatar":""},{"name":"Keerati Mahapreuk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bai Mai Tee Plid Plew","The Leaves","ใบไม้ที่ปลิดปลิว"]', 1784690324380);
