INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-riverdale-phan-4', 'Thị Trấn Riverdale (Phần 4)', 'Riverdale (Season 4)', 'https://phimimg.com/upload/vod/20241015-1/0b1ace971148c173c84d07a6e5e6d538.jpg', 'https://phimimg.com/upload/vod/20241015-1/a72df39ae9dc61fb4ab813b0739e8c28.jpg', '<p>Thị trấn Riverdale (Phần 4) vẫn là câu chuyện nhìn từ xa, Riverdale cũng giống như rất nhiều thị trấn nhỏ khác trên khắp thế giới. An toàn, bình yên, trong sạch. Nhưng khi đến gần hơn, những bóng tối lẩn khuất ngay bên dưới bắt đầu lộ diện. Phim mở đầu bằng cái chết của Jason Blossom đã gây ra sự xáo trộn cho cả thị trấn, những bí mật bắt đầu được hé lộ. Ở Riverdale, không có ai là người vô tội...</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"KJ Apa","avatar":""},{"name":"Lili Reinhart","avatar":""},{"name":"Camila Mendes","avatar":""},{"name":"Cole Sprouse","avatar":""},{"name":"Marisol Nichols","avatar":""},{"name":"Madelaine Petsch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Riverdale"]', 1784690324380);
