INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguon-goc-cua-huong-vi-phan-1-am-thuc-trieu-san', 'Nguồn Gốc Của Hương Vị (Phần 1) - Ẩm Thực Triều Sán', 'Flavorful Origins (Season 1)', 'https://phimimg.com/upload/vod/20240205-1/8c17788c82d755211adc9689f36a5faf.jpg', 'https://phimimg.com/upload/vod/20240205-1/e4d3d31ad008ccea6bfc8b1e4aeac291.jpg', '<p>Thâm nhập vào thế giới ẩm thực hấp dẫn của Triều Sán, khám phá những nguyên liệu độc đáo và tìm hiểu câu chuyện của những người góp phần kiến tạo nên nền ẩm thực này.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Thần","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324380);
