INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luke-nguyen-tren-chuyen-tau-bac-nam', 'Luke Nguyễn Trên Chuyến Tàu Bắc Nam', 'Luke Nguyen''s Railway Vietnam', 'https://phimimg.com/upload/vod/20241007-1/e2c058ce2e25d8dd496fd2da43ac8b68.jpg', 'https://phimimg.com/upload/vod/20241007-1/d259577584dc499c4e83dd616142ae66.jpg', '<p>Luke Nguyen&#39;s Railway Vietnam (Luke Nguyễn trên chuyến tàu Bắc Nam) do Đài SBS của Úc sản xuất vào năm 2019 và từng thắng giải thưởng danh giá Best Lifestyle Program tại Giải thưởng Truyền hình châu Á lần thứ 25 (2020). Phim được chiếu ở 150 quốc gia trên thế giới, trong đó có Việt Nam (Netflix vừa mua bản quyền phát hành tháng 6-2023). Đây có lẽ là loạt phim tài liệu có ý tưởng thú vị và độc đáo nhất để tôn vinh ẩm thực và du lịch Việt Nam của Luke Nguyen - chủ của tám nhà hàng thành công ở Úc và Việt Nam, tác giả của tám cuốn sách về ẩm thực bán chạy và là người dẫn chương trình (host) kiêm sản xuất của nhiều chương trình truyền hình về ẩm thực khắp thế giới.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 16, 2019, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Luke Nguyen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Luke Nguyen''s Railway Vietnam"]', 1784690324380);
