INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-no-toi-mot-moi-tinh-dau', 'Thế Giới Nợ Tôi Một Mối Tình Đầu', 'Lucky''s First Love', 'https://phimimg.com/upload/vod/20240930-1/200c998fd203f7f5aca645ff20d757b8.jpg', 'https://phimimg.com/upload/vod/20240930-1/4333a5f3f5ef09afbd0fc472c6495e31.jpg', '<p>Một cô gái đáng yêu, trạch nữ chính hiệu, Hình Vận, 24 tuổi làm việc tại công ty game mobile TIG, luôn ước mơ trở thành một nhà thiết kế game. Vừa hay công ty đang thực hiện tuyển chọn phương án sản phẩm liên quan đến dự án về tình yêu trong toàn công ty, để thực hiện ước mơ của mình, cô nàng với kinh nghiệm tình trường bằng không đã gia nhập vào đội quân đi xem mắt. Đâu ai ngờ, hành động này của cô đã khiến chủ tịch Hạ Kha dần dần nhận ra tấm chân tình của mình đối với Hình Vận.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xing Zhaolin","avatar":""},{"name":"白鹿","avatar":""},{"name":"翟子路","avatar":""},{"name":"Chen Haolan","avatar":""},{"name":"Liu Ruoyan","avatar":""},{"name":"Huang Jidong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lucky''s First Love","The World Owes Me A First Love","世界欠我一个初恋"]', 1784690324381);
