INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-dia-nguc-phan-4', 'Chúa Tể Địa Ngục (Phần 4)', 'Lucifer (Season 4)', 'https://phimimg.com/upload/vod/20240928-1/7787908d7d4909a3e20695bd08334824.jpg', 'https://phimimg.com/upload/vod/20240928-1/33bcf6483236dc2f9f589c49a82c15e8.jpg', '<p>Suýt bị cancel bởi Fox, nhưng thật may mắn làm sao, Netflix đã đưa Lucifer về với vòng tay ấm áp của mình và hồi sinh loạt phim này. Mùa 4 của Lucifer sẽ được sản xuất bởi Netflix, hứa hẹn những điều tươi mới và đầy bất ngờ. Phim xoay quanh chuyến du hí xuống trần gian của Lucifer khi đã quá chán cuộc sống ở Địa ngục. Hắn chọn Los Angeles làm địa điểm để vui chơi và tìm hiểu thêm về người phàm. Tại đây, Lucifer bị thu hút bởi nữ thám tử thuộc Sở Cảnh sát Los Angeles Chloe - người miễn nhiễm với sức mạnh và sự quyến rũ của hắn. Sau khi giúp cô giải quyết một vụ án, con ác quỷ được mời giúp đỡ trong các trường hợp tiếp theo với tư cách là cố vấn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Ellis","avatar":""},{"name":"Lauren German","avatar":""},{"name":"Kevin Alejandro","avatar":""},{"name":"D.b. Woodside","avatar":""},{"name":"Lesley-Ann Brandt","avatar":""},{"name":"Scarlett Estevez","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Aimee Garcia","avatar":""},{"name":"Tricia Helfer","avatar":""},{"name":"Tom Welling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["路西法","ლუციფერი","Λούσιφερ","Lucifer az Újvilágban","لوسيفر","루시퍼","Луцифер","魔鬼神探","Lucifer"]', 1784690324381);
