INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-da-tan-nuong', 'Nhất Dạ Tân Nương', 'The Romance Of Hua Rong', 'https://phimimg.com/upload/vod/20240929-1/50e3938cd19693ed4985d808971799c3.jpg', 'https://phimimg.com/upload/vod/20240929-1/176edb68c24ec3df9a0c3e681cbb8daf.jpg', '<p>Kể về con gái của đại tướng quân - Hoa Dung vô tình trở thành đảo chủ phu nhân của vua hải tặc Tần Thượng Thành. Cô không chịu thỏa hiệp, gây chuyện rồi bỏ chạy trong ngày đại hôn. Tần Thượng Thành đã nhận định cô là ái thê nên ra sức đánh bại tình địch, theo đuổi nương tử khắp thiên hạ. Hai người từ cặp đôi oan gia không ai chịu thua ai đến nắm tay nhau vượt qua bao nguy hiểm trùng trùng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2019, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Hao","avatar":""},{"name":"Zhao Zhao Yi","avatar":""},{"name":"王澤軒","avatar":""},{"name":"Guan Xin","avatar":""},{"name":"Na Mao","avatar":""},{"name":"Yu Kaining","avatar":""},{"name":"黃千碩","avatar":""},{"name":"Dai Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["일야신낭","เจ้าสาวโจรสลัด","一夜新娘"]', 1784690324381);
