INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-yo-han', 'Bác Sĩ Yo Han', 'Doctor John', 'bác sĩ yo han doctor john 지성 이세영 이규형 김혜은 신동미 전노민 엄효섭 오승현 정인기 황희 jung min-ah chun young-min 권화운 son san 이유미 kim yeong-hoon 정재성 oh hyun-joong 윤주상 정경순 park jin-young kim mi-hye noreen joyce guerra moon hak-jin jang hee-soo 윤찬영 oh yoo-na 윤주상 lim dong-jin 고 доктор джон 痛症医师车耀汉 医師 ヨハン 의사 요한 doctor room doctor john หมอหัตถ์เทวดา 天才醫生車耀漢 醫生耀漢 天才醫師耀漢 約翰醫生 의사요한', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lala-school-hoc-vien-am-nhac', 'LaLa School: Học Viện Âm Nhạc', 'LaLa School: Music Academy', 'https://phimimg.com/upload/vod/20240925-1/57ec5829a8968aa6fa9eee8a9aa2089c.jpg', 'https://phimimg.com/upload/vod/20240925-1/5c10dff895bdeea9a0dd5760401fda48.jpg', '<p>LaLa School: Học Viện Âm Nhạc kể về việc nữ sinh Tuệ Nghi nhận được học bổng tại khoa Ca sĩ của trường LaLa. Tài năng của Tuệ Nghi đã gây nhiều sự chú ý đối với các học viên khác và đồng thời đem lại cho cô nàng không ít rắc rối. Bộ phim là những tình huống hài hước xảy ra tại Học viện siêu sao LaLa School xen kẽ chuyện tình lãng mạn của các nhân vật trong phim. Tình tiết phim được đẩy lên cao trào khi cuộc thi La La Idol bắt đầu. Từ đây, những âm mưu thầm kín nhằm mục đích trở thành người chiến thắng diễn ra phá tan bầu không khí vui tươi, hồn nhiên vốn có thường ngày.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhi Katy","avatar":""},{"name":"Khánh Vũ","avatar":""},{"name":"Lê Chi","avatar":""},{"name":"Lykio","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我太爱哥哥了怎么办","少爷与我的罗曼史"]', 1784690324381);
