INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lala-school-tuoi-tre-tai-cao', 'LaLa School: Tuổi Trẻ Tài Cao', 'LaLa School: Talented Youth', 'https://phimimg.com/upload/vod/20240925-1/02e351c0379f5192963612cdea2e91ed.jpg', 'https://phimimg.com/upload/vod/20240925-1/bcb40e26a5f2a1993571426642e69718.jpg', '<p>LaLa School: Tuổi Trẻ Tài Cao kể về nhóm P336 tại trường LaLa School: Việt Thi - cô nữ sinh tuy gia cảnh khó khăn nhưng luôn lạc quan, mỉm cười. Mon tưởng như vô lo vô nghĩ với cuộc sống khá đơn giản, đủ đầy nhưng rất biết quan tâm đến bạn bè. Hailey tốt bụng, đầy đam mê với ca hát nhưng lại bị gia đình ngăn cấm và phản đối. Kenji, cậu bé nhỏ nhất nhóm có kiểu giao tiếp tưng tửng (giống như chính Kenji ở ngoài đời) khiến cho các thành viên khác nhiều phen phát bực. Winner xuất thân từ nhóm Underground bỗng có mối duyên kỳ lạ với P336 và chính thức gia nhập nhóm, cùng nhau đánh bại “thế lực thù địch”.&nbsp; Xen lẫn các mâu thuẫn giữa các thành viên là những chuyện tình lãng mạn của tuổi mới lớn. Những rung động đầu đời, những tình cảm chớm nở từ sự quan tâm giúp đỡ, tương trợ nhau.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhi Katy","avatar":""},{"name":"Khánh Vũ","avatar":""},{"name":"Lê Chi","avatar":""},{"name":"Lykio","avatar":""},{"name":"Ngô Trọng Huỳnh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
