INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-den-phan-1', 'Mùa Hè Đen (Phần 1)', 'Black Summer (Season 1)', 'https://phimimg.com/upload/vod/20240924-1/6a1f2103ef1c130b1be524a30070a3d8.jpg', 'https://phimimg.com/upload/vod/20240924-1/9f0b58edc03d78ea60d44d47cbc20e06.jpg', '<p>Trong lúc xã hội đang vô cùng hỗn loạn với đại dịch zombie đang lan truyền với tốc độ chóng mặt, Rose một bà mẹ trẻ tìm kiếm đứa con gái thất lạc của mình. Trong suốt hành trình tìm con, Rose liên minh với những người tị nạn, cùng nhau vượt qua sự tấn công của hàng ngàn xác sống, chấp nhận kiến thiết thế giới hỗn độn này bằng cách lập ra luật mới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jaime King","avatar":""},{"name":"Christine Lee","avatar":""},{"name":"Zoe Marlett","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["黑夏","Черное лето","Black Summer"]', 1784690324381);
