INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-nguoi-chua-lanh-vet-thuong-cho-anh', 'Yêu Em Người Chữa Lành Vết Thương Cho Anh', 'From Survivor To The Healer', 'https://phimimg.com/upload/vod/20240923-1/5012f4750c62f6cd7e4f5c0e21752d41.jpg', 'https://phimimg.com/upload/vod/20240923-1/2de4b0f4c4d726607157daff0d4abc66.jpg', '<p>Yêu Em Người Chữa Lành Vết Thương Cho Anh - From Survivor To The Healer kể về chuyện tình của Nhan Thư Nhân (Đậu Kiêu) và Tôn Thụ. Thư Nhân đang học thạc sĩ thì tình cờ gặp gỡ và yêu đương với đàn em Tôn Thụ (Miêu Miêu). Vì biến cố của gia đình, Thư Nhân đòi chia tay không lý do với Tôn Thụ. Thất tình và cũng thất vọng vì nghĩ là bố chết là do mẹ, Tôn Thụ quyết định lựa chọn đi du học Nhật Bản. 5 năm sau, Thư Nhân trở thành bác sĩ khoa tâm thần ở bệnh viện Tư Khang, chuyên chữa trị cho những người bị mắc bệnh trầm cảm nhưng bản thân anh cũng mắc chứng bệnh mất ngủ, lo âu và phiền muôn… Thầy giáo của Thư Nhân và Tôn Thụ là Trần Nguyên Canh (Kim Sĩ Kiệt) lại mời cả Tôn Thụ vào làm bác sĩ tâm lý, cùng khoa với Thư Nhân. Sau khi gặp lại, Thư Nhân lại muốn hàn gắn lại mối quan hệ của hai người nhưng lúc đầu Tôn Thụ khá lạnh nhạt vì vẫn còn hận Thư Nhân. Mãi đến khi mẹ cô phải nằm viện chữa bệnh thì cô mới cảm nhận được Thư nhân vẫn còn yêu mình. Dần dần, trong quá trình làm việc, hai người đã trở lại với nhau. Sau này, khi Thư Nhân vô tình biết rõ hơn về biến cô gia đình của anh mấy năm trước, anh tự trách mình và nghi ngờ luôn chính tay nghề và thành tựu nghề nghiệp của mình. Liệu bác sĩ tâm lý Tôn Thụ có chữa lành được vết thương lòng cho Thư Nhân để cả hai có thể hạnh phúc bên nhau.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đậu Kiêu","avatar":""},{"name":"Miêu Miêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["From Survivor To Healer","爱上你治愈我"]', 1784690324381);
