INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-chet-gio-tay-phap-su-mu', 'Ai chết giơ tay: Pháp Sư Mù', 'Land of Spirits: The Blind Shaman', 'https://phimimg.com/upload/vod/20240922-1/285132bf8ce4bc0b33b7e3175a25ac75.jpg', 'https://phimimg.com/upload/vod/20240922-1/ef096bb2496094f8d18a0a21b336e017.jpg', '<p>Bộ phim điện ảnh Pháp Sư Mù: Ai Chết Giơ tay sẽ tái hiện hành trình đi tìm lại ánh sáng cho đôi mắt của Tinh Lâm (Huỳnh Lập) và những câu chuyện nhân quả đan xen mà Tinh Lâm phải trải qua để thấu hiểu rõ hơn về cuộc đời. Cùng với Thụy Du (Quang Trung) - chàng trai có khả năng cho các linh hồn người chết nhập vào, và Liên Thanh (Hạnh Thảo) - cô gái có khả năng nhìn thấy linh hồn, họ trở thành bộ ba ăn ý. Cả nhóm cùng giải cứu những linh hồn chưa siêu thoát cũng như chữa trị cho đôi mắt của Tinh Lâm.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Quang Trung","avatar":""},{"name":"Hạnh Thảo","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Huỳnh Lập","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Blind Shaman","Pháp Sư Mù","Ai Chết Giơ Tay: Pháp Sư Mù"]', 1784690324381);
