INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-the-ky-moi-cua-anh-hung', 'Học Viện Anh Hùng: Thế Kỷ Mới Của Anh Hùng', 'My Hero Academia: Heroes Rising', 'https://phimimg.com/upload/vod/20240922-1/50b67a97f57b1dc23dd819deaaa9121e.jpg', 'https://phimimg.com/upload/vod/20240922-1/2abe784d881962b70dccff8795e15ebb.jpg', '<p>Bộ phim điện ảnh mới của “Học Viện Anh Hùng Của Tôi” được đặt tên “Học Viện Anh Hùng Của Tôi: Thế Kỷ Mới Của Anh Hùng” và đưa ra áp phích, được quyết định trình chiếu vào ngày 20/12/2019 tại Nhật Bản. Bộ phim này được tác giả truyện tranh Horikoshi Kohei đạo diễn và thiết kế nhân vật, sẽ phát triển một câu chuyện mới. Horikoshi Kohei cho biết bộ phim này là chương cuối với nguyên tác bởi ông ấy đã dùng neta vốn muốn dùng trong chương cuối truyện tranh vào bộ phim này.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"山下大輝","avatar":""},{"name":"岡本信彦","avatar":""},{"name":"井上芳雄","avatar":""},{"name":"今田美桜","avatar":""},{"name":"寺崎裕香","avatar":""},{"name":"黒沢ともよ","avatar":""},{"name":"梶裕貴","avatar":""},{"name":"石川界人","avatar":""},{"name":"佐倉綾音","avatar":""},{"name":"増田俊樹","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"広橋涼","avatar":""},{"name":"井上麻里奈","avatar":""},{"name":"畠中祐","avatar":""},{"name":"真堂圭","avatar":""},{"name":"古島清孝","avatar":""},{"name":"西田雅一","avatar":""},{"name":"喜多村英梨","avatar":""},{"name":"奈良徹","avatar":""},{"name":"悠木碧","avatar":""},{"name":"名塚佳織","avatar":""},{"name":"桑野晃輔","avatar":""},{"name":"Kosuke Miyoshi","avatar":""},{"name":"永塚拓馬","avatar":""},{"name":"中村悠一","avatar":""},{"name":"鳥海浩輔","avatar":""},{"name":"武内駿輔","avatar":""},{"name":"三宅健太","avatar":""},{"name":"諏訪部順一","avatar":""},{"name":"高戸靖広","avatar":""},{"name":"小桜エツコ","avatar":""},{"name":