INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ba-me-sieu-nhan-phan-3', 'Những bà mẹ siêu nhân (Phần 3)', 'Workin'' Moms (Season 3)', 'https://phimimg.com/upload/vod/20240920-1/1765d0a12bfac482f0b90846561633ce.jpg', 'https://phimimg.com/upload/vod/20240920-1/8d76a7667e6e5ddc25f80becbae1cab1.jpg', '<p>Khi Kate điều chỉnh cho quen tình trạng bình thường mới, Anne chuyển hướng cơn giận, Frankie đạt bước tiến mới trong nghề còn Jenny nỗ lực trở thành người mẹ tốt hơn.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Catherine Reitman","avatar":""},{"name":"Dani Kind","avatar":""},{"name":"Juno Rinaldi","avatar":""},{"name":"Katherine Barrell","avatar":""},{"name":"Jessalyn Wanlim","avatar":""},{"name":"Novie Edwards","avatar":""},{"name":"Dennis Andres","avatar":""},{"name":"Raymond Ablack","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Workin Moms","上班族妈妈","职场老妈","Workin''moms","Workin'' Moms"]', 1784690324381);
