INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-sau-va-di-chung-2', 'Biển Sâu Và Dị Chủng 2', 'The Mutant Python 2', 'https://phimimg.com/upload/vod/20240918-1/2e69fb72a9b81c80a6c4e8f0002c44bf.jpg', 'https://phimimg.com/upload/vod/20240918-1/966b8bbf0fccbf0f4c50869eda421331.jpg', '<p>Ở Đông Nam Á, với phong cảnh tuyệt đẹp, một chiếc tàu tuần dương chở nhiều khách du lịch đi vào vùng biển huyền bí, nơi có một dị nhân khổng lồ. Mọi người lần lượt chết một cách bí ẩn. “Kẻ giết người” trong bóng tối và kẻ bí ẩn trong số khách du lịch khiến chiếc tàu tuần dương trở thành “cỗ máy hành quyết”. Những người sống sót chạy trốn đến một hòn đảo hoang kỳ lạ gặp một dị nhân hung dữ hơn và bắt đầu hành trình sinh tồn.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Chiu","avatar":""},{"name":"Zhang Ze","avatar":""},{"name":"Zhao Sifan","avatar":""},{"name":"Wu Juncheng","avatar":""},{"name":"Pei Chenwei","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["深海X异种2","The Mutant Python II"]', 1784690324381);
