INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-thich-khach-o-long-cung-nha-giam-nu-dai-minh', 'Nữ Thích Khách Ở Long Cung: Nhà Giam Nữ Đại Minh', 'Longgong Female Assassin', 'null', 'https://phimimg.com/upload/vod/20231109-1/5bbacb84ee67e4db1faf724440a6d791.jpg', '<p>Một câu chuyện trong đó triều đình sẽ cạnh tranh với nhau xung quanh quyền lực đế quốc. Hoàng đế cử tướng Che phụ trách căn cứ bí mật nổi tiếng dưới nước. Grandpa Soft đã cử một kẻ giết người để thực hiện tội ác và thâm nhập vào căn cứ, trong khi General Che cố gắng tìm ra kẻ ám sát và hóa giải âm mưu của Grandpa Soft. Hai lực lượng đã tung ra một trò chơi tuyệt vời xung quanh căn cứ bí mật dưới nước. Là hai quân cờ, Shiqi và Tangfang vừa là kẻ thù vừa là chị em, những ân oán sau lưng họ được hé lộ.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324381);
