INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-truong-pha-le-den-ky-nguyen-khang-chien', 'Hậu trường - Pha lê đen: Kỷ nguyên kháng chiến', 'The Crystal Calls Making the Dark Crystal: Age of Resistance', 'https://phimimg.com/upload/vod/20231108-1/fd4a316c82ddb6c5012425035645538b.jpg', 'https://phimimg.com/upload/vod/20231108-1/38e8ccd4d9a9041dfeb937f1eb081f3a.jpg', '<p>Khám phá hậu trường cùng các ngôi sao, nghệ sĩ múa rối và tác giả khi họ đưa thế giới phép thuật Thra của Jim Henson bước vào đời thực trong loạt phim kỳ ảo hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Natalie Dormer","avatar":""},{"name":"Hannah John-Kamen","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Caitríona Balfe","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Jeffrey Addiss","avatar":""},{"name":"Cindy Holland","avatar":""},{"name":"Cameron Richardson","avatar":""},{"name":"Lisa Henson","avatar":""},{"name":"Brian Froud","avatar":""},{"name":"Michael Kilgarriff","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324381);
