INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hau-truong-pha-le-den-ky-nguyen-khang-chien', 'Hậu trường - Pha lê đen: Kỷ nguyên kháng chiến', 'The Crystal Calls Making the Dark Crystal: Age of Resistance', 'hậu trường - pha lê đen: kỷ nguyên kháng chiến the crystal calls making the dark crystal: age of resistance taron egerton natalie dormer hannah john-kamen nathalie emmanuel gugu mbatha-raw caitríona balfe simon pegg jeffrey addiss cindy holland cameron richardson lisa henson brian froud michael kilgarriff ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tre-trau-khoi-nghiep', 'Trẻ Trâu Khởi Nghiệp', 'Start-Up', 'https://phimimg.com/upload/vod/20231103-1/0940fb1905fd0f06514c1fa7f035a69f.jpg', 'https://phimimg.com/upload/vod/20231103-1/04c1cdf1e1887a4a6d67b9a99e2bba89.jpg', '<p>2 chàng học sinh cấp 3 Taek-Il và Sang-Pil với vô số rắc rối mà họ gặp phải khi vào đời. Tưởng đâu dễ ăn lắm nên “đôi bạn cùng tiến” này quyết định không học đại học để đi tìm con đường riêng cho bản thân. Trong khi Taek-Il theo đầu bếp “áo hồng” Geo-Seok để làm nhân viên giao đồ ăn thì đứa bạn còn lại là Sang-Pil lại vào làm cho một “công ty tài chính”. Nào ngờ dòng đời đâu có êm ả đâu, 2 đứa “trẻ trâu” bị nghiệp quật túi bụi, vừa ngẩng đầu lên đã bị đạp xuống một cách không thương tiếc.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Jung Hae-in","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Choi Sung-eun","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Kim Kyung-duk","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Goh Doo-shim","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Lee Hae-woon","avatar":""},{"name":"Sung Hyuk","avatar":""},{"name":"Seung Eui-yeol","avatar":""},{"name":"Bang Eun-jeong","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Kwon Hyeok-beom","avatar":""},{"name":"Back Joo-h","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324381);
