INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-yeu-quat-sinh-hoai-nam-2019', 'Thầm Yêu Quất Sinh Hoài Nam', 'Unrequited Love', 'https://phimimg.com/upload/vod/20240909-1/79c3a971cc315b08aca64c65b739388c.jpg', 'https://phimimg.com/upload/vod/20240909-1/dd99323a04fcb1ae3bc83716a6a3c00b.jpg', '<p>Lạc Chỉ, một cô gái bình thường thầm mến một chàng trai ấm áp như ánh mặt trời, Thịnh Hoài Nam. Tình cảm cô dành cho anh rất phức tạp, một mặt cô bị thu hút bởi sự xuất sắc của anh, mặt khác cô lại cố ép mình tránh xa anh bởi những vướng mắc giữa hai gia đình. Lạc Chỉ vẫn luôn cố gắng đuổi theo bước chân Thịnh Hoài Nam, thi đỗ vào trường đại học tốt nhất. Sau đó trải qua nhiều cơ duyên, cuối cùng quan hệ giữa hai người cũng trở nên thân thiết hơn. Nhưng quá trình trưởng thành và áp lực cuộc sống đã khiến hai người trải qua không ít thử thách. Liệu rằng khi đối mặt với khó khăn, Lạc Chỉ có thể tiếp tục giữ vững tình cảm với Thịnh Hoài Nam? Giữa gia đình và tình yêu, cô sẽ đưa ra lựa chọn như thế nào?</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Hồ Băng","avatar":""},{"name":"Trương Dật Kiệt","avatar":""},{"name":"Lưu Mỹ Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
