INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-le-anh-khong-the-yeu-em-2019', 'Có Lẽ Anh Không Thể Yêu Em', 'I Don''t Love You Yet', 'https://phimimg.com/upload/vod/20240908-1/7418ff6ae1acc8c4e15b712affa56b85.jpg', 'https://phimimg.com/upload/vod/20240908-1/53e187a9294da245c96253f34993ed9a.jpg', '<p>Mitarai Yo là một phụ nữ làm việc cho một thợ đóng giày. Cô ấy thấy công việc của mình rất bổ ích và đã thăng tiến thành công trong sự nghiệp. Nhưng cô ấy vẫn tiếp tục bị tan vỡ trái tim và cuộc sống lãng mạn của cô ấy cũng không suôn sẻ sau này. Ishida Ren làm việc cho một nhà phát triển và là bạn thân nhất của Yo. Là bạn học cũ ở trường trung học và đại học, Ren là người duy nhất mà cô dành trọn trái tim mình, và anh hiểu cô nhất. Vào sinh nhật lần thứ 29 của Yo, những người bạn đặt cược với nhau xem ai trong số họ có thể kết hôn trong năm sau. Nếu một trong hai người không tổ chức đám cưới trước sinh nhật lần thứ 30 của cô ấy, người thua cuộc phải trả cho người chiến thắng một khoản tiền mừng 300.000 yên.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"足立梨花","avatar":""},{"name":"白洲迅","avatar":""},{"name":"Kodai Asaka","avatar":""},{"name":"Matsumoto Kiyo","avatar":""},{"name":"Yu Sakuma","avatar":""},{"name":"永野宗典","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
