INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tich-duyen', 'Thần Tịch Duyên', 'Love And Destiny', 'https://phimimg.com/upload/vod/20240909-1/1426d4386ad6cd291948e1e83290c542.jpg', 'https://phimimg.com/upload/vod/20240909-1/ae208bfb6700db261b870917ea2936bd.jpg', '<p>Thần Tịch Duyên là câu chuyện kể về vạn năm trước, Cửu Thần vì phong ấn Ma Thần mà rơi vào trạng thái ngủ say, đột nhiên vì thiếu nữ Linh Tịch đi lạc mà thức tỉnh. Trong quá trình chung sống, hai người dần nảy sinh tình cảm. Linh Tịch được phát hiện trời sinh có ma khí, mà ma khí này lại chính là linh dược của Ma tộc, giúp mở phong ấn giải thoát Ma Thần gây họa cho chúng sinh. Đây là điều tối kị, vận mệnh hai người từ đây gặp nhiều trắc trở. Cửu Thần không muốn lạm sát vô tội, chống chọi với áp lực, giúp đỡ Linh Tịch giải trừ ma khí. Dưới sự giúp đỡ của Cửu Thần, Linh Tịch từ một thiếu nữ ngây thơ trở thành người dẫn dắt người trong tộc chống lại Ma Thần. Hai người trải qua gian khổ thu hoạch được tình yêu.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 10, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"張震","avatar":""},{"name":"倪妮","avatar":""},{"name":"李東學","avatar":""},{"name":"Zhang Zhixi","avatar":""},{"name":"Li Jiaming","avatar":""},{"name":"Hai Ling","avatar":""},{"name":"Liu Qianhan","avatar":""},{"name":"Zhang Haiyu","avatar":""},{"name":"Na Guangzi","avatar":""},{"name":"Yuan Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324381);
