INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-tich-duyen', 'Thần Tịch Duyên', 'Love And Destiny', 'thần tịch duyên love and destiny 張震 倪妮 李東學 zhang zhixi li jiaming hai ling liu qianhan zhang haiyu na guangzi yuan hao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huynh-de-tuong-tan', 'Huynh Đệ Tương Tàn', 'Blood Brothers', 'https://phimimg.com/upload/vod/20240908-1/6641e36d7f61f906c8d7a0db57984a11.jpg', 'https://phimimg.com/upload/vod/20240908-1/97fdb890db7739c6ad5b16212273f0a3.jpg', '<p>Huynh Đệ Tương Tàn - Blood Brothers lấy bối cảnh chiến tranh thế giới thứ 2, lúc ấy, Napa - một phu nhân tướng quân - chẳng may bị sảy thai khi chồng đang ở nước ngoài. Vào thời điểm đó, Lampao, một trong những người hầu của phu nhân Napa phát hiện bản thân đang mang song thai. Vì vậy, Napa đã hỏi xin một trong hai đứa trẻ và Lampao đã đồng ý vì từng nghe lời thầy bói phán rằng: hai đứa trẻ này sẽ giết nhau nếu ở cùng nhau. Sau đó, Sasin, anh lớn đã được đưa cho Napa nuôi dưỡng, còn Lampao đã rời khỏi căn nhà và chuyển đến sống ở vùng nông thôn cùng với đứa bé còn lại là Ravit. 22 năm sau, định mệnh đã đưa họ gặp lại nhau cùng với những điều bất ngờ. Mỗi người phải tự đưa ra những lựa chọn vì bản thân, vì tình yêu và cả tình huynh đệ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Neng Sarun Naraprasertkul","avatar":""},{"name":"Plengkwan Nattaya Thongsaen","avatar":""},{"name":"Tre Porapat Srikajorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
