INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-da-nhan-cach', 'Nhật Ký Đa Nhân Cách', 'Psychopath Diary', 'https://phimimg.com/upload/vod/20240904-1/aafe19cfc9efd25ae85aca11953e4f9d.jpg', 'https://phimimg.com/upload/vod/20240904-1/5cb2aa2728e3979a9e3a0b56602f2dea.jpg', '<p>Yook Dong-Sik (Yoon Si-Yoon) làm việc tại một công ty môi giới. Anh ta có một tính cách rụt rè và anh ta thậm chí không thể tức giận với những người coi thường anh ta. Một ngày nọ, anh chứng kiến một vụ giết người. Anh ta vô tình nhặt được một cuốn nhật ký thuộc về kẻ giết người, một kẻ giết người hàng loạt. Cuốn nhật ký ghi lại tất cả các vụ án giết người mà tên đó thực hiện. Yook Dong-Sik chạy trốn cùng với cuốn nhật ký, nhưng anh vô tình bị cảnh sát Sim Bo-Kyung (Jung In-Sun) đâm phải. Yook Dong-Sik bị mất trí nhớ vì tai nạn. Do cầm cuốn nhật ký, Yook Dong-Sik đã lầm tưởng rằng anh ta là một kẻ giết người hàng loạt. Kể từ giây phút đó, anh bắt đầu thay đổi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"윤시윤","avatar":""},{"name":"정인선","avatar":""},{"name":"박성훈","avatar":""},{"name":"이한위","avatar":""},{"name":"Hwang Hyo-eun","avatar":""},{"name":"이민지","avatar":""},{"name":"Choi Tae-hwan","avatar":""},{"name":"Han Soo-hyun","avatar":""},{"name":"Oh Chae-eun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
