INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-y-thien-do-long-ky', 'Tân Ỷ Thiên Đồ Long Ký', 'The Heaven Sword And Dragon Saber', 'https://phimimg.com/upload/vod/20240904-1/d626a1057268ff09154b31e44be76b3e.jpg', 'https://phimimg.com/upload/vod/20240904-1/0487844ee5878d43db78693df1b5d55d.jpg', '<p>Phiên bản chuyển thể lần thứ 8 của tác phẩm đã để lại nhiều đánh giá khác nhau. Các diễn viên của phiên bản như Tăng Thuấn Hy (Trương Vô Kỵ), Trần Ngọc Kỳ (Triệu Mẫn), Lâm Vũ Thân (Dương Tiêu) ban đầu bị đánh giá là không hợp vai lại để lại nhiều ấn tượng. Tăng Thuấn Hy đã đem đến một Trương Vô Kỵ trẻ trung, đúng tuổi của nguyên tác. Trần Ngọc Kỳ thu hút nhờ vào diễn xuất tự nhiên, lanh lợi, giàu tình cảm. Cô đã mang lại một Triệu Mẫn thông minh, dám nói dám làm, trọng nghĩa khí, dám hi sinh vì tình yêu. Chúc Tự Đan thể hiện khá tốt một Chu Chỉ Nhược vừa nhu mì vừa hắc hóa mạnh mẽ. Tuy còn nhiều ý kiến trái chiều nhưng bộ phim đã khá thành công trong việc khắc họa cuộc đời thiếu niên Trương Vô Kỵ cùng chuyện tình cảm của chàng với 4 cô gái xinh đẹp Chu Chỉ Nhược, Ân Ly, Tiểu Chiêu và Triệu Mẫn giữa những ân oán giang hồ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"曾舜晞","avatar":""},{"name":"Yukee Chen","avatar":""},{"name":"祝緒丹","avatar":""},{"name":"Kabby Hui","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"Lin Shen","avatar":""},{"name":"黑子","avatar":""},{"name":"周海媚","avatar":""},{"name":"Xiao Rongsheng","avatar":""},{"name":"Chen Chuang","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"王德順","avatar":""},{"name":"Chaoren Zhang","avatar":""},{"name":"Maggie Chen","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"宁文彤","avatar":""},{"name":"Xie Yuchen","avatar":""},{"name":"Emile Amro","avatar":""},{"name":"Li Jie","avatar":""},{"name":"刘竞","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324381);
