INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-chet-biet-yeu', 'Thần Chết Biết Yêu', 'The Death''s Holiday', 'https://phimimg.com/upload/vod/20240904-1/583eb7c05a979d7c93f871d01401b671.jpg', 'https://phimimg.com/upload/vod/20240904-1/1030b503a9b59f9a6574b4cf267190e4.jpg', '<p>Thần Chết Biết Yêu - The Death&#39;s Holiday kể về một thần chết tốt bụng quyết định đến nhân gian để chứng minh tình yêu lớn lao như thế nào, nhưng anh ta phải gặp trở ngại vì thần chết quỷ quyệt muốn đưa người phụ nữ anh ta yêu trở lại địa ngục. Sau những thử thách, trắc trở họ đã chứng minh cho tình yêu mãnh liệt của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2019, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Nut Devatastin","avatar":""},{"name":"Rattapoom Tokongsup","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
