INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-cai-nao-trai', 'Tôi Và Cái Não Trái', 'Me & My Left Brain', 'https://phimimg.com/upload/vod/20240903-1/14fcabfcabc10767496d8d7326a6dbac.jpg', 'https://phimimg.com/upload/vod/20231103-1/b9c38b8f3411cb88198a8d8da5b0f0ca.jpg', '<p>Arthur và Helen đã quen nhau được vài tháng nhưng anh không biết mối quan hệ của họ là bạn hay hơn bạn bè. Và thế là Arthur đã thức trắng đêm mổ xẻ từng khoảnh khắc thời gian anh dành cho Helen.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Chantelle Barry","avatar":""},{"name":"Rachael Beck","avatar":""},{"name":"Malcolm Kennard","avatar":""},{"name":"Natalia Ladyko","avatar":""},{"name":"Alex Lykos","avatar":""},{"name":"Laura Dundovic","avatar":""},{"name":"Simon McLachlan","avatar":""},{"name":"Janette Lakiss","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324381);
