INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-doc-quyen-dung-cam-yeu', 'Ký Ức Độc Quyền: Dũng Cảm Yêu', 'Unique Memory: Love As You Like', 'https://phimimg.com/upload/vod/20231102-1/ddfe44e42b33dd46a13e985247ab5f9d.jpg', 'https://phimimg.com/upload/vod/20231102-1/6e9b66aedc18cca0724422eeed81cbbd.jpg', '<p>Mộ Thừa Hoà và Tiết Đồng cuối cùng cũng kết hôn! Sự nghiệp của Mộ Thừa Hoà đi vào bước vào bế tắc, những lo lắng và cố chấp đưa anh và Tiết Đồng dần dần xa cách. Cùng lúc đó một Lưu Khải tràn đầy năng lượng tiếp cận Tiết Đồng. Mộ Thừa Hoà sẽ làm thế nào để níu giữ trái tim của Tiết Đồng? Hai người rốt cục vì sao lại quay lại với nhau và xác định tình cảm ở nước Nga.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Chao","avatar":""},{"name":"TingtingLi","avatar":""},{"name":"Chen Bohao","avatar":""},{"name":"Sun Jialing","avatar":""},{"name":"Li Jiuxiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324381);
