INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-thoi-den-vu-hiep-quan-son', 'Quỷ Thổi Đèn: Vu Hiệp Quan Sơn', 'Mojin', 'https://phimimg.com/upload/vod/20231102-1/f2d2464216250a3dc9cd6757cd40cfb2.jpg', 'https://phimimg.com/upload/vod/20231102-1/3498828a860aea3386a8b11843139e9a.jpg', '<p>Sự mang thai ngoài ý muốn của Shirley Yang, mang đến nhiều áp lực đối với Hu Bayi, người bị mắc kẹt trong một lời nguyền đẫm máu. Theo lời mời khảo cổ của Giáo sư Sun, ông biết rằng trong khu di tích lịch sử Feng, mở 12 năm một lần ở làng Dixian, có thể có những xác chết có thể loại bỏ lời nguyền. Với sự giúp đỡ của Yaomei, bộ ba kẻ cướp mộ huyền thoại đã vào núi một lần nữa để chiến đấu sinh tồn.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Zuo","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"Mi Te","avatar":""},{"name":"Wang Xinru","avatar":""},{"name":"Liang Guorong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
