INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-su-thanh-nong', 'Đại Sư Thanh Nông', 'Cyan Wizard', 'https://phimimg.com/upload/vod/20231102-1/0fb5670a39375862e60d42bc5dfee754.jpg', 'https://phimimg.com/upload/vod/20231102-1/c1fcc9d2d383cc3e0b7db9b198f81a30.jpg', '<p>Phim xoay quanh nhân vật Li Daoshi, một pháp sư trừ tà được sư phụ cử xuống núi để hoàn thành nhiệm vụ đã được giao phó. Khi đi ngang qua ngôi làng chài, anh tình cờ gặp người đàn ông giả điên giả khùng và phát hiện ra bí mật của ngôi làng lâu nay. Hiện tại, có một con quái vật biển hung ác, đã giết chết bất cứ ai đi qua con sông để đánh bắt cá. Sau trận chiến đầu tiên với quái vật, Li Daoshi biết được thân thế thật của con thủy quái và tìm cách hóa giải thù hận và minh oan cho nó. Bằng trái tim nhân hậu và lòng trắc ẩn, anh cố thuyết phục mọi người nhưng không ai chấp nhận, liệu Li Daoshi có thể giúp thủy quái trở về cuộc sống bình thường.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xinze Li","avatar":""},{"name":"Lin Fengye","avatar":""},{"name":"付赫安琪","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Song Jiaxin","avatar":""},{"name":"Xu Caixiang","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324381);
