INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-pham-an', 'Vũ Trụ Phàm Ăn', 'Foodiverse', 'https://phimimg.com/upload/vod/20231101-1/f6c0562bf1653863ef1fe99a4b56318d.jpg', 'https://phimimg.com/upload/vod/20231101-1/1ec8bc3d0b8d779bb7b3d7d3c3233924.jpg', '<p>Hành tinh Bột, nơi sinh sống của nhiều loại đồ ăn đang yên đang lành bỗng bị lão quý ông Háu Ăn đến từ hành tinh Hoàn Hảo dụ dỗ và biến họ trở thành những món đồ ăn hoàn hảo. Với sứ mệnh đặc biệt của mình, liệu cô bé Bánh Chẻo và cậu bạn thân Bánh Bao có giúp mọi người thoát khỏi âm mưu xấu xa của quý ông Háu Ăn?</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Sitong","avatar":""},{"name":"Bo Sun","avatar":""},{"name":"Xu Wu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324381);
