INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tu-dau-lam-xung', 'Báo Tử Đầu Lâm Xung', 'The Man Named Leopard', 'https://phimimg.com/upload/vod/20240901-1/17743f09ee118e2f500f822f0f6e2446.jpg', 'https://phimimg.com/upload/vod/20231101-1/f14731a2a0754a8ad315a7c64f2472a3.jpg', '<p>Trong triều đại của Hoàng đế Huizong của Song, Lin Chong là một sĩ quan trong Quân đội Hoàng gia gồm 800.000 binh sĩ. Vợ anh tình cờ gặp Gao Yanei, con trai nuôi của một vị quan chức độc đoán, Gao Qiu. Gao Yanei bị thu hút bởi vẻ đẹp của cô ấy và muốn biến cô ấy thành người phụ nữ của mình. Lu Qian, người bạn Lin Chong, phản bội Lin Chong và giúp Gao Yanei. Lin Chong đang thiết lập và mang vũ khí vào Hội trường Bạch Hổ. Sau đó, ông bị trục xuất đến Cang Châu để gia nhập quân đội. Trên đường đi, anh ta bị ám sát nhưng vẫn sống sót với sự giúp đỡ của Lu Zhishen.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Zhen","avatar":""},{"name":"Jin Song","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Zhang Lei","avatar":""},{"name":"Yang Qifang","avatar":""},{"name":"Yu Huitao","avatar":""},{"name":"Xu Shao-Hang","avatar":""},{"name":"Chen Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324381);
