INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-kich-vi-dai', 'Vở Kịch Vĩ Đại', 'The Great Show', 'https://phimimg.com/upload/vod/20240628-1/ab3d1bbbc5909101b6c97e5186299d6c.jpg', 'https://phimimg.com/upload/vod/20240628-1/758d287c50de0fe7de32d8f94bb84207.jpg', '<p>Wi Dae Han là một nhà cựu lập pháp và nhà chính trị gia vật chất. Anh muốn được đắc cử trở thành nhà lập pháp một lần nữa. Một ngày nọ, cô gái 18 tuổi Da Jung tìm đến anh. Cô bé nói anh là cha ruột của cô. Mẹ cô bé một mình nuôi bốn đứa con, bao gồm cả Da Jung nhưng cô đã chết trong một vụ tai nạn. Hiện giờ Da Jung phải chăm sóc ba người em. Wi Dae Han chấp nhận Da Jung và 3 người em của cô bé. Anh tiến hành một &quot;vở kịch vĩ đại&quot; để trở thành nhà lập pháp lần nữa.</p>', 'Hoàn Tất (16/16)', 16, 'tvshows', 'completed', 13, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"송승헌","avatar":""},{"name":"이선빈","avatar":""},{"name":"임주환","avatar":""},{"name":"노정의","avatar":""},{"name":"박하나","avatar":""},{"name":"손병호","avatar":""},{"name":"김동영","avatar":""},{"name":"정준원","avatar":""},{"name":"유성주","avatar":""},{"name":"이원종","avatar":""},{"name":"Yoo Jang-young","avatar":""},{"name":"Han Sang-hyuk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324381);
