INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-tham-vong', 'Nhà Văn Tham Vọng', 'Dickinson', 'https://phimimg.com/upload/vod/20240628-1/a7bf7a8ee2d1ad024e15b333226e3d03.jpg', 'https://phimimg.com/upload/vod/20240628-1/84d9519741f514544af1e7cb2d7e9efc.jpg', '<p>Câu chuyện có thật hấp dẫn của nhà văn đầy tham vọng Emily Dickinson được đưa vào cuộc sống với cảm giác và sự nhạy cảm hiện đại. Xấu hổ bởi chính cha mẹ của mình và xa lánh xã hội, Dickinson sẽ không dừng lại để chống lại nền tảng nghiêm ngặt của mình và khiến giọng nói của cô được nghe qua phép thuật của thơ ca.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Adrian Enscoe","avatar":""},{"name":"Anna Baryshnikov","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324381);
