INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-toi-la-nguoi-hung', 'Bố Tôi Là Người Hùng', 'My Hero My Daddy', 'https://phimimg.com/upload/vod/20240828-1/0b0f7a7d45ab0403d46d218cd9c9b6f9.jpg', 'https://phimimg.com/upload/vod/20240828-1/8a4e3c5caccaa33ecab3924adae80d3e.jpg', '<p>Bố Tôi Là Người Hùng - My Hero,My Daddy là bộ phim ngôn tình hay nhất, xoay quanh câu chuyện về gia đình Sư Phụ Hoàng – một nhà thiết kế vest lâu đời cho một thương hiệu thời trang nam nổi tiếng ở Đại Lục. Ông có 3 cô con gái với ba tính cách vô cùng khác nhau. Tình yêu quá lớn của người cha dành cho các cô con gái đã đẩy ông vào cuộc chiến với các chàng rể trong chính gia đình mình. Ba cô con gái của ông với 3 tính cách khác nhau nhưng tựu chung lại đều rất mạnh mẽ, sống tình cảm và có chính kiến, chính vì vậy chuyện tình cảm của mỗi người con gái luôn khiến ông lo lắng không yên.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 11, 2019, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"蔡振南","avatar":""},{"name":"周孝安","avatar":""},{"name":"Linda Lin","avatar":""},{"name":"David Chiu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
