INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-kham-biet-lap', 'Phòng Khám Biệt Lập', 'Eli', 'https://phimimg.com/upload/vod/20240827-1/c8e5b67757fd88bdcd22d4b0aa1c0065.jpg', 'https://phimimg.com/upload/vod/20240827-1/8f88fe870727c966aecda1083f9c7489.jpg', '<p>Được bố mẹ tháp tùng trong tuyệt vọng, cậu bé 11 tuổi mắc bệnh suy nhược vào một phòng khám biệt lập để trải qua liệu trình chữa trị thử nghiệm.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charlie Shotwell","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Sadie Sink","avatar":""},{"name":"Deneen Tyler","avatar":""},{"name":"Katia Gomez","avatar":""},{"name":"Austin Foxx","avatar":""},{"name":"Parker Lovein","avatar":""},{"name":"Lou Beatty Jr.","avatar":""},{"name":"Jared Bankens","avatar":""},{"name":"Nathaniel Woolsey","avatar":""},{"name":"Kailia Posey","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324381);
