INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-sieu-kho', 'Nghề Siêu Khó', 'Extreme Job', 'https://phimimg.com/upload/vod/20240827-1/7ac310d283e0a85a88e72664634ef8f8.jpg', 'https://phimimg.com/upload/vod/20240827-1/e6c45927ae175e2d0af5c918880656e7.jpg', '<p>Nhóm điều tra do đội trưởng Ko (Ryu Seung-yong) lãnh đạo đứng trước nguy cơ giải tán nhờ chuỗi “thành tích” thất bại đáng nể. Cơ hội cuối cùng để cứu vớt sự nghiệp của họ chính là phải triệt phá một băng đảng buôn bán ma tuý tầm cỡ quốc tế. Để làm được điều đó, đội trưởng Ko và các thành viên trong nhóm đã cải trang thành những nhân viên bán gà tại một quán ăn ngay đối diện hang ổ của kẻ địch. Trớ trêu thay, món gà rán của họ quá ngon và nhà hàng bỗng chốc nổi như cồn, căn cứ địa có nguy cơ bại lộ khiến 5 cảnh sát chìm rơi vào những nguy hiểm khó lường.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"류승룡","avatar":""},{"name":"이하늬","avatar":""},{"name":"진선규","avatar":""},{"name":"이동휘","avatar":""},{"name":"공명","avatar":""},{"name":"신하균","avatar":""},{"name":"오정세","avatar":""},{"name":"김의성","avatar":""},{"name":"송영규","avatar":""},{"name":"허준석","avatar":""},{"name":"김지영","avatar":""},{"name":"김종수","avatar":""},{"name":"양현민","avatar":""},{"name":"이중옥","avatar":""},{"name":"김강현","avatar":""},{"name":"태원석","avatar":""},{"name":"Jang Ji-woong","avatar":""},{"name":"Jang Jin-hee","avatar":""},{"name":"신신애","avatar":""},{"name":"Na Chul","avatar":""},{"name":"Ji Chan","avatar":""},{"name":"Jung Won-chang","avatar":""},{"name":"Yoo Je-yoon","avatar":""},{"name":"한준우","avatar":""},{"name":"정재광","avatar":""},{"name":"Kim Nam-woo","avatar":""},{"name":"Jeongeun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"nam