INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-cuong-trong-da', 'Kim Cương Trong Đá', 'Uncut Gems', 'https://phimimg.com/upload/vod/20231030-1/78c3456c9a6d05d6802ea1282385356f.jpg', 'https://phimimg.com/upload/vod/20231030-1/90758b3496cf646610d8abf9f6094637.jpg', '<p>Howard Ratner, một thợ kim hoàn ở thành phố New York lôi cuốn luôn tìm kiếm điểm số lớn tiếp theo, thực hiện một loạt các vụ cá cược cao có thể dẫn đến cơn gió của cả cuộc đời.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Julia Fox","avatar":""},{"name":"Kevin Garnett","avatar":""},{"name":"Idina Menzel","avatar":""},{"name":"Eric Bogosian","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Keith William Richards","avatar":""},{"name":"Mike Francesa","avatar":""},{"name":"Jonathan Aranbayev","avatar":""},{"name":"Noa Fisher","avatar":""},{"name":"The Weeknd","avatar":""},{"name":"Mesfin Lamengo","avatar":""},{"name":"Sun Zhi Hua-Hilton","avatar":""},{"name":"Liang Wei-Hui-Duncan","avatar":""},{"name":"Deneke Muhuge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324381);
