INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-sau-doi-khat', 'Hố sâu đói khát', 'The Platform', 'https://phimimg.com/upload/vod/20231026-1/cee6bad0a7fb7c8a866edfaae05979f4.jpg', 'https://phimimg.com/upload/vod/20231026-1/b59b7db6542ca3c92f460799e72f83fc.jpg', '<p>Bối cảnh phim là tại một “nhà tù” thẳng đứng sâu hun hút được chia thành nhiều tầng. Mỗi ngày, một bàn đồ ăn sẽ lần lượt được chuyển xuống qua các tầng để nuôi sống các “tù nhân”. Cứ như vậy, đồ ăn thừa của tầng trên sẽ trở thành thức ăn và những người sống ở đó buộc phải làm mọi cách để sinh tồn. &nbsp;Phủ bóng lên bộ phim không chi có sự tối tăm của chốn ngục tù mà còn là nỗi sợ hãi, sự giễu cợt dành cho bản tính ích kỷ của con người.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Iván Massagué","avatar":""},{"name":"Antonia San Juan","avatar":""},{"name":"Zorion Eguileor","avatar":""},{"name":"Emilio Buale","avatar":""},{"name":"Alexandra Masangkay","avatar":""},{"name":"Zihara Llana","avatar":""},{"name":"Mario Pardo","avatar":""},{"name":"Algis Arlauskas","avatar":""},{"name":"Txubio Fernández de Jáuregui","avatar":""},{"name":"Eric Goode","avatar":""},{"name":"Óscar Oliver","avatar":""},{"name":"Chema Trujillo","avatar":""},{"name":"Miriam Martín","avatar":""},{"name":"Gorka Zufiaurre","avatar":""},{"name":"Miriam K. Martxante","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
