INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thung-lung-silicon-phan-6', 'Thung Lũng Silicon (Phần 6)', 'Silicon Valley (Season 6)', 'https://phimimg.com/upload/vod/20240809-1/92c688564ccb751412ac369883232ecb.jpg', 'https://phimimg.com/upload/vod/20240809-1/497a4831ef9824759b19cf2c7c11baeb.jpg', '<p>Trong mùa cuối của Thung lũng Silicon, Richard và hội bạn đối mặt với những thách thức lớn để bảo toàn lời hứa không lợi dụng dữ liệu người dùng cho các mục đích vụ lợi.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Thomas Middleditch","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Martin Starr","avatar":""},{"name":"Amanda Crew","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Suzanne Cryer","avatar":""},{"name":"Jimmy O. Yang","avatar":""},{"name":"Chris Diamantopoulos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324381);
