INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-cua-chung-ta-phan-1', 'Hành Tinh Của Chúng Ta (Phần 1)', 'Our Planet (Season 1)', 'https://phimimg.com/upload/vod/20240820-1/008eb479587304eb4fd85da839f47896.jpg', 'https://phimimg.com/upload/vod/20240820-1/49dade15f537e4a66dc67d74fccefc5d.jpg', '<p>Loạt phim tài liệu đầy tham vọng với phạm vi ấn tượng đưa ta trải nghiệm vẻ đẹp tự nhiên của Trái đất và nghiên cứu cách khí hậu thay đổi tác động lên mọi sinh vật sống.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2019, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324381);
