INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-the-gioi-mot-hanh-tinh', 'Bảy Thế Giới, Một Hành Tinh', 'Seven Worlds, One Planet', 'https://phimimg.com/upload/vod/20240820-1/a33f8502802759e11faed1a434038037.jpg', 'https://phimimg.com/upload/vod/20240820-1/c8c9c7b11b22d1951679d3a35390d9a4.jpg', '<p>Seven Worlds, One Planet (Bảy Thế Giới, Một Hành Tinh) là series phim tài liệu của BBC gồm 7 tập kể về cuộc sống tự nhiên trên 7 châu lục của Trái Đất: Châu Á, Châu Âu, Châu Phi, Châu Úc, Châu Mỹ (Bắc Mỹ và Nam Mỹ) và Châu Nam Cực. Phim được ra mắt hồi tháng 10 năm 2019, phần lời dẫn được đảm nhận bởi nhà tự nhiên học David Attenborough. Với những người hâm mộ các chương trình về lịch sử tự nhiên, thế giới động vật của BBC có sự góp giọng của David Attenborough như The Blue Planet (2001), Planet Earth (2006),… thì Seven Worlds, One Planet (2019) là một series phim khó có thể bỏ qua.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324381);
