INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-23-cu-dam-sapphire-xanh', 'Thám Tử Lừng Danh Conan 23: Cú Đấm Sapphire Xanh', 'Case Closed: The Fist of Blue Sapphire', 'https://phimimg.com/upload/vod/20231019-1/c8c7ddb80b838219a656bcaa239f079c.jpg', 'https://phimimg.com/upload/vod/20231019-1/23107d8381df2f9b69fdac426f2504ee.jpg', '<p>Tập phim lần thứ 23 sẽ lần đầu tiên đưa chân khán giả xuất ngoại trong lịch sử phim trinh thám Conan để đến với Đảo Quốc Sư Tử Singapore. Tại đây, một vụ án mạng đã xảy ra và hiện trường để lại là một tấm thẻ rướm máu có thông báo của Siêu Đạo Chích Kid. Mục tiêu lần này của Kid chính là báu vật trong truyền thuyết – viên đá Sapphire xanh ẩn dưới đáy đại dương. Tuy nhiên, cao thủ Karate mạnh nhất thế giới với liên tiếp 400 trận bất bại Kyogoku Makoto đã xuất hiện để ngăn chặn Kid. Vậy lý do Kid cũng đưa Conan đến Singapore là để làm gì? Cú đấm giết người bí ẩn đó là như thế nào? Âm mưu đen tối nào sẽ dần lộ diện?... Câu trả lời sẽ được bộ ba tam giác siêu ngầu Siêu Đạo Chích – Cao Thủ Karate – Thám Tử Lừng Danh giải đáp trong Thám Tử Lừng Danh Conan: Cú Đấm Sapphire Xanh</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Nobuyuki Hiyama","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Ikusaburo Yamazaki","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Dominic Allen","avatar":""},{"name":"Ryan Drees","avatar":""},{"name":"Mayuko Kawakita","avatar":""},{"name":"Jeff Manning","avatar":""},{"name":"Yuu Asakawa","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Wataru Tak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
