INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-chuc-cao-thu', 'Toàn Chức Cao Thủ', 'The King''s Avatar', 'https://phimimg.com/upload/vod/20240814-1/d345519fb03d59add407b6370db33f0f.jpg', 'https://phimimg.com/upload/vod/20240814-1/331ea84da96e962475f047d4dbecbeec.jpg', '<p>Trong game online Glory, Diệp Tu nổi tiếng là game thủ top 1. Anh đã bị trục xuất khỏi đội ngũ chuyên nghiệp của mình. Sau khi rời khỏi team chơi game chuyên nghiệp, anh ta sống tại một quán cà phê Internet được thuê làm người quản lý. Khi Glory ra mắt máy chủ thứ mười, anh ta tham gia vào trò chơi một lần nữa, được trang bị mười năm kinh nghiệm chơi game, ký ức về quá khứ và một vũ khí tự chế tạo của anh ta.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"杨洋","avatar":""},{"name":"麥小琪","avatar":""},{"name":"李沐宸","avatar":""},{"name":"Lai Yu Meng","avatar":""},{"name":"Lai Yi","avatar":""},{"name":"範津瑋","avatar":""},{"name":"Sun Ning","avatar":""},{"name":"Yang Tingdong","avatar":""},{"name":"Liang Sen","avatar":""},{"name":"Li Junchen","avatar":""},{"name":"Yin Yi","avatar":""},{"name":"Sun Ya Long","avatar":""},{"name":"安钦夫","avatar":""},{"name":"Li Jun Hao","avatar":""},{"name":"Cheng Jian","avatar":""},{"name":"Bai Xiang","avatar":""},{"name":"Han Mi","avatar":""},{"name":"Song Hanyu","avatar":""},{"name":"Zhao Chulun","avatar":""},{"name":"Suen Han-Wen","avatar":""},{"name":"Leng Jiyuan","avatar":""},{"name":"翟子路","avatar":""},{"name":"Hao Shuai","avatar":""},{"name":"Chen Shuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324381);
