INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-bach-nuong-tu-truyen-ky', 'Tân Bạch Nương Tử Truyền Kỳ', 'The Legend Of White Snake', 'https://phimimg.com/upload/vod/20240812-1/3c915d79631ec73de599fa26d3f04822.jpg', 'https://phimimg.com/upload/vod/20240812-1/18f7ee018b0e5e06521deb5fe2b66196.jpg', '<p>Tân Bạch nương tử truyền kỳ có nội dung chính kể về một con Bạch Xà nuốt được linh đan của hồ ly mà gia tăng tu vi tu thành người rồi trở thành Bạch Tố Trinh dưới núi Nga My. Nhưng nàng lại vô tình đánh thức nguyên thần của Cửu Lạt Ma, khiến nguyên thần của hắn trùng sinh vào xác con trai đích tôn Hứa Gia ở Thành Lâm An, Hứa Tiên lớn lên như bao đứa trẻ bình thường khác lại trở thành một thư sinh nho nhã. Bạch Tố Trinh tuy là xà yêu nhưng bản tính dịu dàng lại lương thiện, vì muốn mở rộng nhãn giới nên đến thành Lâm An du ngoạn. Tại đây, cô gặp gỡ Thanh xà với tên hiệu là Tiểu Thanh, cả 2 kết làm tỉ muội. Trong một lần tình cờ, Bạch Tố Trinh và Tiểu Thanh gặp chàng thư sinh với dung mạo khuynh thành Hứa Tiên. Và từ đây, giữa Bạch Tố Trinh và Hứa Tiên bắt đầu một mối nhân duyên rung động lòng người và trời đất.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 27, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bùi Tử Thiêm","avatar":""},{"name":"Chu Long Nghiễm","avatar":""},{"name":"Cúc Tịnh Y","avatar":""},{"name":"Lý Lâm","avatar":""},{"name":"Nhiếp Tử","avatar":""},{"name":"Phùng Kiến Vũ","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Vu Mông Lung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324381);
