INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-co-tro', 'Mối Tình Cô Trò', 'Wet Season', 'https://phimimg.com/upload/vod/20240812-1/4f2cbcf3384759a0d42b2a5fb9c4ebc5.jpg', 'https://phimimg.com/upload/vod/20240812-1/40a0394c6ff579e99e40cfd5f2b10372.jpg', '<p>Bộ phim xoay quanh cuộc sống của Ling, một giáo viên trường học phải đối mặt với tình trạng vô sinh trong khi phải chăm sóc người cha chồng ốm yếu của mình ở nhà. Một trong những học sinh của Ling, Kok Wei Lun, đã phải lòng cô trong các lớp học tiếng Trung bổ sung. Hai người trở nên thân thiết hơn khi Wei Lun chấp nhận sự kèm cặp thêm của Ling.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"楊雁雁","avatar":""},{"name":"Koh Jia Ler","avatar":""},{"name":"李銘順","avatar":""},{"name":"Yang Shi Bin","avatar":""},{"name":"Brayden Koh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324381);
