INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-ket', 'Mắc Kẹt', 'The Stranded', 'https://phimimg.com/upload/vod/20240811-1/ba44c95791a15e4eae31e3164a153885.jpg', 'https://phimimg.com/upload/vod/20240811-1/a716843be996a1bc02e40f7890a29593.jpg', '<p>The Stranded (Mắc Kẹt) là tác phẩm gốc đầu tiên của Thái Lan nói riêng và Đông Nam Á nói chung được phát sóng trên Netflix. Với sự kết hợp giữa đạo diễn Sophon &quot;Jim&quot; Sakdaphisit của Shutter (Hồn Ma Báo Oán), The Promise (Giao Ước Chết) và ê-kíp chuyên nghiệp từ Hollywood, The Stranded là một phim cực kì đáng xem.

The Stranded kể về một nhóm học sinh trung học bị mắc kẹt trên đảo hoang Pintu sau trận sóng thần. Không thể trông chờ vào đội cứu hộ, những cô cậu tuổi teen phải tự kết thân, đoàn kết lại để tự cứu lấy chính mình. Tuy nhiên, giữa họ có quá nhiều xung đột và bí mật. Chưa kể, hòn đảo không một bóng người như địa ngục kéo họ vào những sự kiện ghê rợn.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Papangkorn Lerkchaleampote","avatar":""},{"name":"Chutavuth Pattarakampol","avatar":""},{"name":"Oabnithi Wiwattanawarang","avatar":""},{"name":"Chayanit Chansangavej","avatar":""},{"name":"กิตติศักดิ์ ปฐมบูรณา","avatar":""},{"name":"Ticha Wongtipkanon","avatar":""},{"name":"Chaleeda Gilbert","avatar":""},{"name":"Chanya McClory","avatar":""},{"name":"สินจัย เปล่งพานิช","avatar":""},{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"Pamiga Sooksawee","avatar":""},{"name":"Siwat Jumlongku","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
