INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-dau-bep', 'Cô Nàng Đầu Bếp', 'Miss Culinary', 'https://phimimg.com/upload/vod/20240811-1/f0305d47d2fc084b83b15177ee72c4a1.jpg', 'https://phimimg.com/upload/vod/20240811-1/ef8f47398a2c3fe80e78376c28807e20.jpg', '<p>&quot;Miss Culinary&quot; hé lộ tài năng của một chàng trai trẻ cố gắng giữ bạn gái bằng cách kể những câu chuyện ngon lành về công thức nấu ăn của mẹ mình để giành lại trái tim bạn gái. Với câu chuyện về cuộc đời của mẹ mình chua, ngọt, mặn, cay, phim kể về một cô gái bỏ trốn khỏi quê hương ở tỉnh Uthai Thani để đối mặt với cuộc sống ở Bangkok vào những năm 70 để thực hiện ước mơ trở thành đầu bếp tại một khách sạn 5 sao, cùng với tình yêu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jason Young","avatar":""},{"name":"Thanawin Teeraphosukarn","avatar":""},{"name":"Wanida Termthanaporn","avatar":""},{"name":"Thanabordee Jaiyen","avatar":""},{"name":"ชนนิกานต์ เนตรจุ้ย","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324381);
