INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-chien-binh-dang-yeu', 'Chàng Chiến Binh Đáng Yêu', 'My Dear Warrior', 'https://phimimg.com/upload/vod/20240810-1/ad38b37fac352496bf2c66f6906dc54c.jpg', 'https://phimimg.com/upload/vod/20240810-1/cfaff91d5dac99e3f7d3a95c1e39baac.jpg', '<p>Chàng Chiến Binh Đáng Yêu Sky là một nữ thiên văn học độc thân xinh đẹp tại một cung thiên văn và đã nhận được một món quà: một cuốn sách bìa gỗ dày và cây bút thần từ Vanda, người cô đã chăm sóc Sky từ nhỏ và là một nhà văn điên loạn bị mất trí nhớ. Vanda là tác giả của một câu chuyện hoạt hình về một chiến binh và Sky cuối cùng phải lòng nhân vật hoạt hình tên là Hoshi – một chiến binh anh hùng đẹp trai, thông minh và tốt bụng. Vào đêm sinh nhật của Sky, cô ấy mong muốn có được tình yêu từ một người đàn ông như Hoshi, đã hoàn thành trong một lời cầu nguyện. Hoshi và công chúa xinh đẹp Luna – bạn gái của Hoshi – cùng với tình địch Cairo bất ngờ bỏ truyện tranh. Câu chuyện loạn lạc và tình yêu lãng mạn bắt đầu. Liệu tình yêu có thể tồn tại giữa con người và phim hoạt hình?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2019, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pimchanok Luevisadpaibul","avatar":""},{"name":"Oabnithi Wiwattanawarang","avatar":""},{"name":"Claudia Chakrabandhu Na Ayudya","avatar":""},{"name":"Suthada Jongjaiphar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
