INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-balkan', 'Chiến Dịch Balkan', 'Balkan Line', 'https://phimimg.com/upload/vod/20231019-1/a6b885aa1dd6f83196265f29ad3fa822.jpg', 'https://phimimg.com/upload/vod/20231019-1/59d04ccfb566c82886a79765a26740e1.jpg', '<p>The Balkan Line (Chiến Dịch Balkan): Năm 1999, Serbia bị ném bom và khu vực Kosovo bị cướp bóc bởi những tên khủng bố dưới sự chỉ huy của lãnh chúa Albania là Smuk. Bọn cướp đã thực hiện,các vụ cướp, ám sát hàng loạt và diệt chủng để lấy các bộ phận cơ thể người để buôn bán nội tạng. Sĩ quan tình báo Nga Bek Ethoev và cựu lính nhảy dù là Andrey Shirthov, đã trở thành lính đánh thuê cùng với một biệt đội đặc nhiệm nhỏ được giao nhiệm vụ nguy hiểm trong chiến dịch Balkan là: ngăn chặn và tiêu diệt bọn khủng bố, chiếm lại sân bay được bọn cướp sử dụng và giải cứu các tù nhân Serbia cùng cô người yêu Yasna đang bị bắt để chuẩn bị cho cuộc giao dịch nội tạng…</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Anton Pampushnyy","avatar":""},{"name":"Gosha Kutsenko","avatar":""},{"name":"Miloš Biković","avatar":""},{"name":"Milena Radulović","avatar":""},{"name":"Gojko Mitić","avatar":""},{"name":"Ravshana Kurkova","avatar":""},{"name":"Dmitry Frid","avatar":""},{"name":"Aleksandar Srećković ''Kubura''","avatar":""},{"name":"Svetlana Chuikina","avatar":""},{"name":"Miodrag Radonjić","avatar":""},{"name":"Nikola Randelovich","avatar":""},{"name":"Emir Kusturica","avatar":""},{"name":"Kirill Poluhin","avatar":""},{"name":"Nodari Dzhanel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324381);
