INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-hi-cong-luoc-la-ngoc-canh-vang', 'Diên Hi Công Lược: Lá ngọc cành vàng', 'Yanxi Palace: Princess Adventures', 'https://phimimg.com/upload/vod/20240804-1/a26fa97667ff6de420c75105268461aa.jpg', 'https://phimimg.com/upload/vod/20240804-1/ac8825309a362f8dcc7301438b75f01f.jpg', '<p>Công chúa Chiêu Hoa con gái của Ngụy Anh Lạcvà vua Càn Long. Chiêu Hoa nảy sinh tình cảm với Phúc Khang An, con trai của Nhĩ Tình và Phó Hằng &nbsp;trên danh nghĩa, tuy nhiên thực chất đây là con của Phó Khiêm – em trai Phó Hằng. Chiêu Hoa không những có mối tình đầy bi kịch, day dứt với Phúc An Khang mà câu chuyện còn thêm phần kịch tính khi có sự xuất hiện của con gái Hoằng Trú.

Chiêu Hoa cũng sẽ được &quot;di truyền&quot; tính đa mưu túc trí của người mẹ quyền lực Ngụy Anh Lạc.Phúc Khang An vốn coi Ngụy Anh Lạc là kẻ thù giết mẹ nên đã tiếp cận Chiêu Hoa để lợi dụng trả thù. Tuy nhiên chính anh lại nảy sinh tình cảm với con gái kẻ thù, vì si tình mà không nỡ xuống tay với cô. Sau khi biết được sự thật này, Chiêu Hoa đã dứt khoát quay lưng với Phúc An Khang và nhận lời cầu hôn của người khác khiến Phúc An Khang phải ôm hận, day dứt cả đời.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"王鶴潤","avatar":""},{"name":"Xu Xiaonuo","avatar":""},{"name":"Wang Yizhe","avatar":""},{"name":"Wang Yuwei","avatar":""},{"name":"吴谨言","avatar":""},{"name":"聶遠","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
