INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-cau', 'Truy Cầu', 'Chasing Love', 'https://phimimg.com/upload/vod/20240802-1/4b546a50fb9625bb9653b128ba75db4f.jpg', 'https://phimimg.com/upload/vod/20240802-1/c98e169ea4105b7536ce973c46f6ae8f.jpg', '<p>Nhân vật lẫy lừng của Học viện Đằng Viễn – Tề Cảnh Hạo phát hiện bí mật: nữ sinh Nhan Hiểu Hi vừa chuyển đến không phải tiểu thư nhà giàu. Cậu chẳng thèm để tâm người sống ham hư vinh như vậy nhưng lại phát hiện cô có tuyệt kỹ chơi bóng mà mình tìm kiếm đã lâu. Cậu lấy bí mật của cô ra đe doạ cô phải dạy mình tuyệt kỹ cho mình. Vốn nghĩ đây là một vụ mua bán có lời nhưng không ngờ người cầm đằng chuôi là Cảnh Hạo bị Hiểu Hi xoay mòng mòng. Xem ra trước khi giành được quán quân thì cần phải xử lý tiểu ác ma này trước đã…</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"黃聖池","avatar":""},{"name":"Zhu Yuanbing","avatar":""},{"name":"Bu Guanjin","avatar":""},{"name":"Shiqi Fan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
