INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-tham-nhung-4', 'Đội Chống Tham Nhũng 4', 'P Storm', 'https://phimimg.com/upload/vod/20240802-1/6a68103d899451d77c9f97d0cb748497.jpg', 'https://phimimg.com/upload/vod/20240802-1/122a64e538a0425ab3f6ab9b01bc0eb0.jpg', '<p>Sau thành công của bộ ba &quot;Z Storm&quot;, &quot;S Storm&quot; và &quot;L Storm&quot;, phần tiếp theo &quot;P Storm&quot; kể về một gã cảnh sát đã nhận hối lộ 30 triệu đô la Hong Kong để giúp một kẻ giết người trong nhà tù sớm được trả tự do. Một cuộc điều tra đã được bắt đầu để tìm ra danh tính gã cảnh sát. Lục Chí Liêm (Cổ Thiên Lạc) vào tù giả làm phạm nhân để tiếp cận và tìm chứng cứ từ Tào Nguyên Nguyên (Lâm Phong) – thiếu gia ăn chơi khét tiếng đang bị giam giữ, còn đồng nghiệp Trình Đức Minh (Trịnh Gia Dĩnh) thì ở bên ngoài để tìm kiếm bằng chứng. Trong khoảng thời gian này, Lục Chí Liêm còn phải đối mặt với những kẻ từng bị anh vạch tội bỏ tù trước đây.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"古天樂","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"Raymond Lam","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"張智霖","avatar":""},{"name":"譚耀文","avatar":""},{"name":"Dada Chan","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"廖啟智","avatar":""},{"name":"艾威","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Janelle Sing","avatar":""},{"name":"Stefan Wong","avatar":""},{"name":"張松枝","avatar":""},{"name":"Justin Cheung","avatar":""},{"name":"Adam Pak Tin-Nam","avatar":""},{"name":"Ding Haifeng","avatar":""},{"name":"Monna Liu","avatar":""},{"name":"Kevin Chu","avatar":""},{"name":"Kumer So","avatar":""},{"name":"石修","avatar":""},{"name":"陳曼娜","avatar":""},{"name":"Eddi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324381);
