INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-loi-phan-5', 'Thành Phố Tội Lỗi (Phần 5)', 'Gotham (Season 5)', 'https://phimimg.com/upload/vod/20240729-1/0c9906a910950b5dd333f644eb097f90.jpg', 'https://phimimg.com/upload/vod/20240729-1/64fca540c91d9017f97ae2c48e8cf6d7.jpg', '<p>Trước khi làm cảnh sát trưởng, tân cảnh sát James Gordon đã đấu tranh chống tội phạm và nạn tham nhũng ở Thành phố Gotham để trả thù vụ sát hại bố mẹ của Bruce Wayne.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben McKenzie","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"David Mazouz","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Robin Lord Taylor","avatar":""},{"name":"Erin Richards","avatar":""},{"name":"Camren Bicondova","avatar":""},{"name":"Cory Michael Smith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324381);
