INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-von-chuot-phan-2', 'Mèo Vờn Chuột (Phần 2)', 'Killing Eve (Season 2)', 'https://phimimg.com/upload/vod/20240729-1/da3d1c3146dd2a5f276337bd40f22a38.jpg', 'https://phimimg.com/upload/vod/20240729-1/dc26be6ae42b2bd81846e9c92190b81d.jpg', '<p>Tưởng rằng Villanelle đã bị trừ khử, Hội Thập Nhị cử sát thủ khác đi hoàn thành nhiệm vụ dang dở của cô. Eve được gọi về London để điều tra vụ án mạng do sát thủ bí ẩn mới này gây ra và đồng thời, cô vẫn tiếp tục tìm kiếm tung tích của Villanelle. Trong lúc đó, Villanelle phải chật vật tìm cách trở về London sau khi bị đưa vào một bệnh viện ở Paris.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Oh","avatar":""},{"name":"Jodie Comer","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Camille Cottin","avatar":""},{"name":"Robert Gilbert","avatar":""},{"name":"Anjana Vasan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
