INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-nhin-thay-mui-huong', 'Cô Gái Nhìn Thấy Mùi Hương', 'Flavour It''s Yours', 'https://phimimg.com/upload/vod/20240727-1/521f40520a8cfa9a240f7d81d0d62332.jpg', 'https://phimimg.com/upload/vod/20240727-1/aa7fa10132555e712272f6ebac9cf92b.jpg', '<p>Bộ phim“Nhìn Thấy Mùi Hương” kể về câu chuyện của thiên tài trong giới thẩm định rượu Lục Vi Tầm (Cung Tuấn vào vai) có vị giác tuyệt đẳng và cô gái Hà Bất Tuý (Tống Y vào vai) từ nhỏ mất đi vị giác. Bởi vì một nụ hôn bất ngờ mà đã tráo đổi vị giác cho nhau, đồng thời nên duyên cho hai người. Liệu một người lạnh lùng, nghiêm khắc có tiếng là bạo quân trong giới thẩm định rượu và một người hoạt bát, ngây thơ gặp nhau sẽ tạo nên câu chuyện gì đây?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"宋伊人","avatar":""},{"name":"Gong Jun","avatar":""},{"name":"Dai Chao","avatar":""},{"name":"Zhang Wanqing","avatar":""},{"name":"楊澤","avatar":""},{"name":"Serina Huang","avatar":""},{"name":"Jin Yubo","avatar":""},{"name":"Zhao Tianyu","avatar":""},{"name":"Yue Yueli","avatar":""},{"name":"Bai Fan","avatar":""},{"name":"Fu Jia","avatar":""},{"name":"Cai Xiangyu","avatar":""},{"name":"Wang Cheng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
