INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uu-tu-phan-2', 'Ưu Tú (Phần 2)', 'Elite (Season 2)', 'https://phimimg.com/upload/vod/20240727-1/352e982ff62f71c7d4be2566c3dc7caa.jpg', 'https://phimimg.com/upload/vod/20240727-1/fc50cabc19491183f7757b48dae3be8b.jpg', '<p>Sau cái chết của một người bạn cùng lớp, một nam sinh biến mất, lòng trung thành thay đổi, nhóm bạn mới làm tình hình thêm phức tạp và rất khó để che đậy bí mật đen tối.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Itzan Escamilla","avatar":""},{"name":"Miguel Bernardeau","avatar":""},{"name":"Danna Paola","avatar":""},{"name":"Arón Piper","avatar":""},{"name":"Omar Ayuso","avatar":""},{"name":"Álvaro Rico","avatar":""},{"name":"Mina El Hammani","avatar":""},{"name":"Ester Expósito","avatar":""},{"name":"Jorge López","avatar":""},{"name":"Claudia Salas","avatar":""},{"name":"María Pedraza","avatar":""},{"name":"Georgina Amorós","avatar":""},{"name":"Miguel Herrán","avatar":""},{"name":"Jaime Lorente","avatar":""},{"name":"Leïti Sène","avatar":""},{"name":"Sergio Momo","avatar":""},{"name":"Carla Díaz","avatar":""},{"name":"Martina C","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
