INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-bat-phan-1', 'Nắm Bắt Phần 1', 'The Capture Season 1', 'https://phimimg.com/upload/vod/20240719-1/2bfe5665ea4bdc04bea115a6051d282e.jpg', 'https://phimimg.com/upload/vod/20240719-1/670fbde3cef07c4919bf3d4e8fb12469.jpg', '<p>Khi bản án của người lính Shaun Emery về tội giết người ở Afghanistan bị lật tẩy do bằng chứng video thiếu sót, anh trở lại cuộc sống như một người tự do cùng với cô con gái nhỏ của mình. Nhưng khi đoạn phim CCTV đáng nguyền rủa về một đêm đi chơi ở London được đưa ra ánh sáng, cuộc đời của Shaun có một bước ngoặt đáng kinh ngạc và anh phải sớm đấu tranh cho tự do của mình một lần nữa.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2019, 'Thuyết Minh', 'FullHD', 'Anh', 0, '[{"name":"Holliday Grainger","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Paapa Essiedu","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Tessa Wong","avatar":""},{"name":"Andy Nyman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
