INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vip', 'VIP', 'VIP', 'https://phimimg.com/upload/vod/20240116-1/2b815a2bbd9947fc448b542d9a65da20.jpg', 'https://phimimg.com/upload/vod/20240116-1/e48238b45add75bdd12f4e6034bf3d99.jpg', '<p>Những nhân viên này phục vụ yêu cầu của nhóm khách hàng sang chảnh nhất tại cửa hàng, đồng thời cố gắng xoay xở với cuộc sống riêng không mấy xa xỉ của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Na Ra","avatar":""},{"name":"Lee Sang Yun","avatar":""},{"name":"Lee Chung Ah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
