INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-6', '100 Người Thử Nghiệm (Phần 6)', 'The 100 (Season 6)', 'https://phimimg.com/upload/vod/20240616-1/550b33d3e556713b7476dd794e2df406.jpg', 'https://phimimg.com/upload/vod/20240616-1/f9e264443e12a1eda5d861e70e04e1c5.jpg', '<p>Sau 125 năm ngủ đông, du hành xuyên qua các vì sao, các anh hùng của chúng ta thức dậy trên ngôi nhà mới, món quà cuối cùng từ những người bạn thân yêu đã khuất. Một nơi mà họ có thể thử lại. Họ được giao một nhiệm vụ đơn giản: làm tốt hơn. Hãy là những người tốt. Với tôn chỉ này, Clarke và Bellamy dẫn đầu một nhóm đến thế giới bí ẩn này, hy vọng bắt đầu lại và cuối cùng tìm thấy hòa bình. Nhưng những thói quen cũ khó phai mờ và khi họ tình cờ gặp một xã hội bình dị, họ nhanh chóng nhận ra rằng không phải mọi thứ trên Sanctum đều hoàn hảo như vẻ ngoài của nó. Bất chấp quyết tâm làm tốt hơn, những mối đe dọa cả hữu hình và vô hình sẽ một lần nữa buộc các anh hùng của chúng ta phải chiến đấu vì mạng sống của họ và tương lai của nhân loại.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2019, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Eliza Taylor","avatar":""},{"name":"Bob Morley","avatar":""},{"name":"Lindsey Morgan","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Tasya Teles","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"Shelby Flannery","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"k