INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ngam', 'Đặc Vụ Ngầm', 'Treadstone', 'https://phimimg.com/upload/vod/20240612-1/449f76ad8d0fdf6c7643201d3a4f612e.jpg', 'https://phimimg.com/upload/vod/20240612-1/6c6a75bf7bf2a219e5d5ec06989fcce5.jpg', '<p>Chương trình bí mật của CIA đào tạo ra những chiến binh tối thượng để tiêu diệt những kẻ thù của nước Mỹ. Họ là những đặc vụ ngầm ẩn dưới vỏ bọc người dân bình thường và bị xóa sạch ký ức về đợt huấn luyện. Mọi chuyện vượt ngoài tầm kiểm soát khi những cỗ máy giết người này bị đánh thức ngoài ý muốn. Cán cân quyền lực có nguy cơ bị đảo lộn…</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeremy Irvine","avatar":""},{"name":"Brian J. Smith","avatar":""},{"name":"Omar Metwally","avatar":""},{"name":"한효주","avatar":""},{"name":"Tracy Ifeachor","avatar":""},{"name":"Gabrielle Scharnitzky","avatar":""},{"name":"Emilia Schüle","avatar":""},{"name":"Michelle Forbes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324381);
