INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-nu-vien-ngoc-than', 'Vệ Nữ Viên Ngọc Thần', 'Divya Drishti', 'https://phimimg.com/upload/vod/20240609-1/0b815fdc953691c5649266d6019255dd.jpg', 'https://phimimg.com/upload/vod/20240609-1/d1fbeb57c171f41a67fd5035cfd8dab5.jpg', '<p>Một cốt truyện hoàn toàn mới để các mọt phim siêu nhiên Ấn Độ đổi gió màn ảnh, Vệ Nữ Viên Ngọc Thần lần đầu lên sóng TodayTV kể câu chuyện về cặp song sinh được Đấng Shiva lựa chọn trao cho sứ mệnh bảo vệ quyền năng tối thượng trong tương lai.</p>', 'Hoàn Tất (113/113)', 113, 'series', 'completed', 12, 2019, 'Lồng Tiếng', 'HD', 'Ấn Độ', 0, '[{"name":"Nyra Banerjee","avatar":""},{"name":"Sana Sayyad","avatar":""},{"name":"Sangita Ghosh","avatar":""},{"name":"Adhvik Mahajan","avatar":""},{"name":"Mansi Srivastava","avatar":""},{"name":"Rati Pandey","avatar":""},{"name":"Ridheema Tiwari","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324381);
