INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-an-co-mat', 'Long Ẩn Cơ Mật', 'Iron Mask', 'https://phimimg.com/upload/vod/20231029-1/8a449e6dafcc8d77a3365e31a2f3f2b1.jpg', 'https://phimimg.com/upload/vod/20231029-1/9e52e66020af4400c0119c92de286fce.jpg', '<p>Long Ấn Cơ Mật, Jouey to China: The Iron Mask Mystery (2019) Nhà du hành người Anh Jonathan Green nhận được từ Peter Đại đế một đơn đặt hàng để lập bản đồ Viễn Đông Nga. Một lần nữa, anh bắt đầu một cuộc hành trình dài đầy những cuộc phiêu lưu kỳ thú cuối cùng sẽ đưa anh đến Trung Quốc. Người vẽ bản đồ sẽ bất ngờ đối mặt với rất nhiều khám phá ngoạn mục, gặp gỡ những sinh vật kỳ quái, gặp gỡ các Công chúa Trung Quốc và đối đầu với các võ sư chết chóc và thậm chí là vua của tất cả các con rồng, Vua rồng. Điều gì có thể nguy hiểm hơn là gặp gỡ trực tiếp với Viy, ngoại trừ làm lại? Điều gì sẽ mạnh mẽ hơn lần này, một sự hoài nghi trung thành của nhà khoa học hoặc ma thuật đen cũ đã chiếm lấy quyền lực của các vùng đất phương Đông ?</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jason Flemyng","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Anna Yao","avatar":""},{"name":"Anna Churina","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Pavel Volya","avatar":""},{"name":"Vilen Babichev","avatar":""},{"name":"Mikhail Mukhin","avatar":""},{"name":"Alexandr Tsema","avatar":""},{"name":"Aleksey Ogurtsov","avatar":""},{"name":"Igor Jijikine","avatar":""},{"name":"V","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324381);
