INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-bac-thay-vo-thuat', 'Diệp Vấn: Bậc Thầy Võ Thuật', 'Ip Man: Kung Fu Master', 'https://phimimg.com/upload/vod/20231026-1/46602b81f4281f04eba43bb8016cdc24.jpg', 'https://phimimg.com/upload/vod/20231026-1/1d03184831acb87e60adde82d136a54d.jpg', '<p>Quay trở lại những ngày đầu của Ip trước Cách mạng Cộng sản năm 1949. Ip, do Dennis To thể hiện lần thứ ba với vai võ sĩ nổi tiếng kèm cặp Lý Tiểu Long, lúc đó là đội trưởng cảnh sát bị buộc tội giết người của một tên cướp tàn nhẫn nhưng danh dự, và được nhắm mục tiêu báo thù bởi đứa con gái nguy hiểm của mình. Bị buộc phải từ bỏ lực lượng, Ip cũng sớm phải đối mặt với sự xuất hiện của quân đội Nhật Bản tại Quảng Châu.
 Trong thời gian làm đội trưởng cảnh sát ở Phật Sơn, Ip Man là mục tiêu của một băng đảng xã hội đen báo thù ngay khi quân đội Nhật Bản xâm lược khu vực.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu-Hang To","avatar":""},{"name":"Yuanli Ruoxin","avatar":""},{"name":"Tong Xiaohu","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Ren Yu","avatar":""},{"name":"Chang Qinyuan","avatar":""},{"name":"Zhao Xiaoguang","avatar":""},{"name":"Li Rizhu","avatar":""},{"name":"Guo Jiayi","avatar":""},{"name":"Michael Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
