INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ly-het-y', 'Trợ Lý Hết Ý', 'The Upside', 'https://phimimg.com/upload/vod/20231023-1/3d9e2ab6ce4203ece444f1853bc1b9c1.jpg', 'https://phimimg.com/upload/vod/20231023-1/bc71ce44e6ff8adb9e2572eb715cfc8e.jpg', '<p>Phim kể về mối quan hệ có nhiều tình huống dở khóc dở cười giữa hai nhân vật: Một người đàn ông giàu có nhưng bị liệt tứ chi và một thanh niên thất nghiệp đang cố gắng sống tích cực, tốt đẹp hơn.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"Aja Naomi King","avatar":""},{"name":"Tate Donovan","avatar":""},{"name":"Jahi Di''Allo Winston","avatar":""},{"name":"Genevieve Angelson","avatar":""},{"name":"Suzanne Savoy","avatar":""},{"name":"Julianna Margulies","avatar":""},{"name":"Rachel Alana Handler","avatar":""},{"name":"Junnie Lopez","avatar":""},{"name":"Pia Mechler","avatar":""},{"name":"Amara Karan","avatar":""},{"name":"Ursula Triplett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324381);
