INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-mo-but-ky-2-no-hai-tiem-sa', 'Đạo Mộ Bút Ký 2: Nộ Hải Tiềm Sa', 'The Lost Tomb 2: The Wrath Of The Sea', 'https://phimimg.com/upload/vod/20231219-1/c8ea38efd32194a945fd1da60653ec68.jpg', 'https://phimimg.com/upload/vod/20231219-1/223efa3f04f1dc68a0d79f9e42477fc4.jpg', '<p>Phim Đạo Mộ Bút Ký 2: Nộ Hải Tiềm Sa - The Lost Tomb 2: The Wrath Of The Sea 2019: Câu chuyện bắt đầu từ một nhóm thợ khoét đất (dân trộm mộ) đã tìm được quyển sách lụa, trên đó ghi lại vị trí của một cổ mộ kỳ bí từ thời Chiến Quốc. Có điều đám thợ gặp chuyện vô cùng hung hiểm dưới mặt đất.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Diêu Dịch Thần","avatar":""},{"name":"Diêu Lỗ","avatar":""},{"name":"Hầu Minh Hạo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324381);
