INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-ong-song-tu', 'Đàn Ông Song Tử', 'Gemini Man', 'https://phimimg.com/upload/vod/20231020-1/466828b0753f30777597d23590d5fc04.jpg', 'https://phimimg.com/upload/vod/20231020-1/1e3bd3b4c8762dcf0afbd1860ede593f.jpg', '<p>Will Smith thủ vai trong bộ phim hành động giật gân bất tận của đạo diễn đoạt giải Oscar, Ang Lee. Sát thủ về hưu Henry Brogan (Smith) buộc phải chạy trốn và bị săn đuổi bởi địch thủ tối hậu – một bản sao vô tính trẻ hơn của chính mình. Đầy những cảnh giao thủ hoành tráng và hiệu ứng hình ảnh đột phá, Đàn Ông Song Tử chính là tương lai của phim hành động.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Will Smith","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"Linda Emond","avatar":""},{"name":"Ilia Volok","avatar":""},{"name":"E.J. Bonilla","avatar":""},{"name":"Victor Hugo","avatar":""},{"name":"David Shae","avatar":""},{"name":"Theodora Miranne","avatar":""},{"name":"Diego Adonye","avatar":""},{"name":"Lilla Banak","avatar":""},{"name":"Igor Szász","avatar":""},{"name":"Alexa GyÖrgy","avatar":""},{"name":"Fernanda Dorogi","avatar":""},{"name":"Alexandra S","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324381);
