INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-co', 'Thủy Cơ', 'Thủy Cơ', 'https://phimimg.com/upload/vod/20240603-1/f408c7c9dc382832727eada29592d5e0.jpg', 'https://phimimg.com/upload/vod/20240603-1/41fec4e3dabc0b2af150d32657921535.jpg', '<p>Thủy Cơ đành chấp nhận dừng chân nơi quê nhà bằng một công việc tự do, ổn định. Cô muốn tạo nên chỗ đứng cho chính người thân của mình. Liệu Thủy Cơ có thể thoát khỏi được những món nợ đời khi mà chính cuộc sống đã buộc cô phải gieo quá nhiều oan trái?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 15, 2019, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Diệu Hiền","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Cao Minh Đạt","avatar":""},{"name":"Chi Bảo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324382);
