INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-lau-trung-hoa', 'Ẩm Thực Lẩu Trung Hoa', 'The Hot Life', 'https://phimimg.com/upload/vod/20240530-1/f8ad4b25187b0af072f833c394780065.jpg', 'https://phimimg.com/upload/vod/20240530-1/41263f963f1f70d98766a688ab383c13.jpg', '<p>Bắt đầu cuộc hành trình xuyên Trung Quốc để khám phá món lẩu đặc sản vùng miền của đất nước và cách món ăn ấm áp này gắn kết mọi người lại với nhau</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324382);
