INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-thuc-lau-trung-hoa', 'Ẩm Thực Lẩu Trung Hoa', 'The Hot Life', 'ẩm thực lẩu trung hoa the hot life  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-tuoi-moi-lon', 'Hội Chứng Tuổi Mới Lớn', 'Rascal Does Not Dream of a Dreaming Girl', 'https://phimimg.com/upload/vod/20240522-1/a57fc5b093c522eab19d2ef8f8a1953d.jpg', 'https://phimimg.com/upload/vod/20240522-1/444ca7fe962f109f6caff73cb2c86d71.jpg', '<p>Có một tin đồn trong thế giới học đường, ấy là về một hiện tượng kì bí gọi là &quot;hội chứng tuổi mới lớn&quot;. Một ngày nọ, cậu học sinh cao trung Sakuta Azusagawa đột nhiên thấy một cô gái tai thỏ xinh đẹp xuất hiện trước mặt mình. Cô gái ấy chính là Mai Sakurajima - đàn chị lớp trên của Sakuta và là một nữ diễn viên nổi tiếng hiện đang tạm nghỉ. Không hiểu vì lý do gì mà chỉ có mình Sakuta thấy cái tai thỏ của Mai mà thôi, không ai ngoài cậu có thể thấy được cả. Thế là Sakuta quyết định tìm cách giải mã bí ẩn này. Cậu tiếp cận và dành nhiều thời gian với Mai hơn, và từ đó, cậu dần hiểu ra những cảm xúc bí mật được giấu kín trong Mai. Nào ngờ đâu, những cô gái khác với &quot;hội chứng tuổi mới lớn&quot; cũng bắt đầu xuất hiện trước mặt Sakuta.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"石川界人","avatar":""},{"name":"瀬戸麻沙美","avatar":""},{"name":"久保ユリカ","avatar":""},{"name":"東山奈央","avatar":""},{"name":"種﨑敦美","avatar":""},{"name":"内田真礼","avatar":""},{"name":"水瀬いのり","avatar":""},{"name":"Himika Akaneya","avatar":""},{"name":"内田雄馬","avatar":""},{"name":"佐藤聡美","avatar":""},{"name":"志村知幸","avatar":""},{"name":"相川奈都姫","avatar":""},{"name":"大津愛理","avatar":""},{"name":"福西勝也","avatar":""},{"name":"Karin Nanami","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324382);
