INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-jack-mot-mat', 'Thần Bài : Jack Một Mắt', 'Tazza : One Eyed Jack', 'https://phimimg.com/upload/vod/20230930-1/bc13d19e99501fc2690fa7e005aae4b9.jpg', 'https://phimimg.com/upload/vod/20230930-1/8e6aa1f025bf83e8760dceaa052cc03f.jpg', '<p>Do Il-chul (Park Jung-min đóng), con trai của thần bài lão luyện đã gặp một thần bài một mắt bí ẩn (Ryoo Seung-bum đóng), từ đó bước vào thế giới của những cao thủ thực sự. Nhiều con bạc điêu luyện do kẻ một mắt dẫn dắt đã nhận được thiệp mời “Jack một mắt” có thể thay đổi vận mệnh, và từ đây một canh bạc sinh tử bắt đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Jeong-min","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Choi Yu-hwa","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Lim Ji-yeon","avatar":""},{"name":"Lee Hong-nae","avatar":""},{"name":"Ju Jin-mo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324382);
