INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-whitehall-du-lich-cung-cha-toi-phan-3', 'Jack Whitehall: Du Lịch Cùng Cha Tôi (Phần 3)', 'Jack Whitehall: Travels With My Father (Season 3)', 'https://phimimg.com/upload/vod/20240302-1/d5a023726f01c56aa65a3cc3ef5b7fd8.jpg', 'https://phimimg.com/upload/vod/20240302-1/a1567217099f9cf913a1f1cdaa885769.jpg', '<p>Khi sinh sống và làm việc tại Los Angeles, Jack chứng minh cho ông bố Michael bảo thủ thấy miền Tây nước Mỹ hấp dẫn nhường nào, nhằm thuyết phục ông chuyển đến Mỹ.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jack Whitehall","avatar":""},{"name":"Michael Whitehall","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324382);
