INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('jack-whitehall-du-lich-cung-cha-toi-phan-3', 'Jack Whitehall: Du Lịch Cùng Cha Tôi (Phần 3)', 'Jack Whitehall: Travels With My Father (Season 3)', 'jack whitehall: du lịch cùng cha tôi (phần 3) jack whitehall: travels with my father (season 3) jack whitehall michael whitehall ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-gia-hang-xom', 'Đại Gia Hàng Xóm', 'My Life As Loan Shark', 'https://phimimg.com/upload/vod/20240302-1/13b9cf5de158f6eb59238c6bda0b40ae.jpg', 'https://phimimg.com/upload/vod/20240302-1/0b66f1d004cbd0773731ea8749124190.jpg', '<p>Vay nặng lãi là phương thức phổ biến để giải quyết nhanh chóng nhu cầu tài chính, một ông trùm với hệ thống cho vay nặng lãi sử dụng các quy tắc giang hồ để quản lý, thu hồi nợ bằng các biện pháp bạo lực. Ông trùm bị điều tra, lời khuyên từ người vợ rửa tay gác kiếm. Rồi biến cố xảy ra, ông trùm bị sét đánh, trở thành một người tốt bất ngờ. Bộ phim là câu chuyện về các băng đảng xã hội đen, mối quan hệ của các nhân vật sừng sỏ, tài chính đen và giang hồ, cuộc chiến chống tội phạm của cảnh sát, những câu chuyện cảm động….Xã hội chứa đầy những bất công và sự bất bình đẳng giữa người giàu và người nghèo. Những công dân nhỏ bé trong những góc tối đang rất cần được giải cứu. Mọi người thực sự cần một người đàn ông giàu có được cứu trợ.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 13, 2019, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
