INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-beo-dang-yeu', 'Công Chúa Béo Đáng Yêu', 'Love The Way You Are', 'https://phimimg.com/upload/vod/20240302-1/a3b794d165dc4e84a621e035aa76afee.jpg', 'https://phimimg.com/upload/vod/20240302-1/e9f8d844b4a0439e3d0e40de9cb6fdf3.jpg', '<p>Là Một Cô Mập nói về cô nàng béo Chân Viên Viên, sau khi giảm béo thành công đã lắc mình biến hóa trở thành ngôi sao Eva mới của làng siêu mẫu. Gặp lại nam thần Nguyễn Đông Thăng, hai người diễn ra một câu chuyện tình yêu lãng mạn, dở khóc dở cười, tương ái tương sát.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Khưu Bách Hạo","avatar":""},{"name":"Mã Mộng Duy","avatar":""},{"name":"Thích Nghiên Địch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
