INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-dong-phan-2', 'Biển Động (Phần 2)', 'High Seas (Season 2)', 'https://phimimg.com/upload/vod/20240302-1/99f572c66bd1ffe8c4bf9456effe9575.jpg', 'https://phimimg.com/upload/vod/20240302-1/c33a8d23c3f35be101142b70b5ba22fe.jpg', '<p>Hai chị em khám phá ra những bí mật gia đình đáng sợ sau khi một loạt cái chết bí ẩn xảy ra trên một con tàu sang trọng đi từ Tây Ban Nha đến Brazil vào những năm 1940.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ivana Baquero","avatar":""},{"name":"Jon Kortajarena","avatar":""},{"name":"Alejandra Onieva","avatar":""},{"name":"Eloy Azorín","avatar":""},{"name":"Marco Pigossi","avatar":""},{"name":"Daniel Lundh","avatar":""},{"name":"Natalia Rodríguez","avatar":""},{"name":"Ignacio Montes","avatar":""},{"name":"Begoña Vargas","avatar":""},{"name":"Cristina Plazas","avatar":""},{"name":"Pep Antón Muñoz","avatar":""},{"name":"Itsaso Arana","avatar":""},{"name":"Nicolás Francella","avatar":""},{"name":"Claudia Galán","avatar":""},{"name":"Antonio Durán ''Morris&#039","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
