INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giong-noi-1', 'Giọng Nói 1', 'Voice 1', 'https://phimimg.com/upload/vod/20240302-1/ab2833e8437d09865807a4b16a49962d.jpg', 'https://phimimg.com/upload/vod/20240302-1/52ade7a1458cef777b003829d8a1994e.jpg', '<p>Phim kể về trung tâm 112, nơi giải quyết các vấn đề khẩn cấp của người dân trong thời gian ngắn nhất, với người đứng đầu là Kang Kwon Joo, một chuyên gia phân tích giọng nói tại Mỹ và có thính giác vô cùng nhạy bén. Bên cạnh đó, cô và các đồng đội cũng phải đối mặt với những tên sát nhân vô cùng nguy hiểm và thông minh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2019, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Lee Ha Na","avatar":""},{"name":"Lee Jin-Wook","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324382);
