INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-trang-diem-phan-2', 'Phù Thủy Trang Điểm (Phần 2)', 'Glow Up (Season 2)', 'https://phimimg.com/upload/vod/20240302-1/0aba832fb95f212c363c5d3c454255ab.jpg', 'https://phimimg.com/upload/vod/20240302-1/721e0656cc7169ad2883d71492144d02.jpg', '<p>Trong cuộc thi này, các nghệ sĩ trang điểm khao khát thành công dấn thân vào những thử thách nhiều sắc màu để giành cơ hội làm nên sự nghiệp trong ngành làm đẹp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Val Garland","avatar":""},{"name":"Dominic Skinner","avatar":""},{"name":"Maya Jama","avatar":""},{"name":"Stacey Dooley","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
