INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rat-vui-duoc-gap-em-ufo', 'Rất Vui Được Gặp Em UFO', 'Nice To Meet UFO', 'https://phimimg.com/upload/vod/20240302-1/4c375d865fec3220d38cba8b71b39b53.jpg', 'https://phimimg.com/upload/vod/20240302-1/8f07d532b5bf96834a519ec69360679f.jpg', '<p>Một tác phẩm do Văn học iQiyi, Điện ảnh truyền hình JIAYUSKY Bắc Kinh, Điện ảnh truyền hình Century Boying, Truyền thông Thai Phoenix và Thư viện YIYUN kết hợp sản xuất, bộ phim hài khoa học viễn tưởng tình cảm gồm hai phần do “Kế hoạch YUNTENG” của iQiyi cải biên sản xuất kể về người ngoài hành tinh do Niếp Niếp thủ vai phải bước vào giới giải trí của Trái Đất để tìm kiếm thái tử ngoài hành tinh. Xông vào và thay đổi số phận của người quản lý hàng đầu Cố Lưu Niên cùng với diễn viên nổi tiếng Tạ Thần Khê...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Even","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324382);
