INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-trong-dau-thuong', 'Yêu Trong Đau Thương', 'Love In Sadness', 'https://phimimg.com/upload/vod/20240302-1/dc08289561e3503c09f881c71ea2887b.jpg', 'https://phimimg.com/upload/vod/20240302-1/a1f30df898f56f8b046941af1e18bbe0.jpg', '<p>Jung Won (Ji Hyun Woo) yêu sâu đậm với Ha Gyung (Park Han Byul), tuy nhiên, Ha Gyung lại không như vậy, cô ngoại tình và muốn chia tay với Jung Won. Khi Jung Won phát hiện ra cũng là lúc Ha Gyung bị tai nạn, hôn mê sâu suốt 5 năm. Vì quá yêu, Jung Won chấp nhận tha thứ, ngày đêm cầu nguyện nhưng Ha Gyung lại ra đi mãi mãi. Một ngày, Jung Won vô tình gặp Ma-ri, người phụ nữ có khuôn mặt giống hệt Ha Gyung. Ma-ri đang sống hạnh phúc cùng chồng là In Wook (Ryu Soo Young) - chủ tịch một tập đoàn lớn, nơi Jung Won đang làm việc. Liệu Jung Won có nhận ra được hiện thực Ma-ri không phải là Ha Hyung không hay anh cứ mãi đắm chìm trong tình yêu của mình, đuổi theo Ma-ri, phá vỡ hạnh phúc gia đình cô?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Han-byul","avatar":""},{"name":"Ji Hyun Woo","avatar":""},{"name":"Ryu Soo Young","avatar":""},{"name":"Wang Bit Na","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324382);
