INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-cham-vao-noi-mem-yeu-day-long-em', 'Đừng Chạm Vào Nơi Mềm Yếu Đáy Lòng Em', 'Soft Memory', 'https://phimimg.com/upload/vod/20240302-1/dce1a1da1acb6481140f17d025ce39e9.jpg', 'https://phimimg.com/upload/vod/20240302-1/f827eec3930413b0d6efe268c585654f.jpg', '<p>Với gam màu ấm áp về chủ đề thanh xuân, kể nên câu chuyện về bốn thanh thiếu niên, nữ sinh trung học Tôn Tiểu Nhu, học bá với ngoại hình vô cùng đáng yêu Âu Dương Vũ Sinh, Ga lăng mang trong mình giọng hát tuyệt vời Sở Lộ, và Cao Nguyên với tình yêu âm nhạc sâu sắc.Họ cùng tạo nên một bức tranh tươi mới nhiệt huyết về thanh xuân, mang đến một giai điệu tươi trẻ và cái nhìn sâu sắc về sự trưởng thành!</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dịch Hằng","avatar":""},{"name":"Tân Thụy Kỳ","avatar":""},{"name":"Nghê Ngôn","avatar":""},{"name":"Thái Nghi Đạt","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324382);
