INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-thoi-thanh-xuan-am-ap-cua-chung-ta', 'Gửi Thời Thanh Xuân Ấm Áp Của Chúng Ta', 'Put Your Head On My Shoulder', 'https://phimimg.com/upload/vod/20240302-1/44a9b2c67480786828e936056bdd3fc5.jpg', 'https://phimimg.com/upload/vod/20240302-1/05dbd827dca2178cd1bdc886049924b2.jpg', '<p>Cô nữ sinh Tư Đồ Mạt thiếu dũng khí, thiếu quyết đoán từ nhỏ đến lớn đã quen với việc làm theo sự sắp xếp của gia đình. Nhưng từ khi ngoài ý muốn quen biết chàng thiên tài vật lý Cố Vị Dịch, từ đây cuộc sống bình lặng của cô trở nên đặc sắc. Nhiều lần đôi oan gia này có giao chiến, có liên minh, cũng vì vậy mà cả hai dần cởi bỏ những định kiến và dần yêu thích đối phương. Hai người cùng nhau trải qua những cột mốc quan trọng như tốt nghiệp, kiếm việc, đi làm, và nhận ra rằng thời khắc thanh xuân ấm áp nhất chính là cùng đúng đối tượng lựa chọn đúng phương hướng và nắm tay nhau cùng trải qua năm tháng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xing Fei","avatar":""},{"name":"Lin Yi","avatar":""},{"name":"Daddi Tang","avatar":""},{"name":"Zheng Yingchen","avatar":""},{"name":"Zhou Junwei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324382);
