INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-7', 'Trại Giam Kiểu Mỹ (Phần 7)', 'Orange Is The New Black (Season 7)', 'https://phimimg.com/upload/vod/20240302-1/a6a6fe85194022de538733760bce65cc.jpg', 'https://phimimg.com/upload/vod/20240302-1/dd8ae4e1b09f7ac9562ae763d521bc4e.jpg', '<p>Bị kết án một thập kỷ tội phạm vận chuyển tiền ma túy cho bạn gái cũ, Piper Chapman thường tuân thủ luật pháp bị kết án một năm rưỡi sau song sắt để đối mặt với thực tế về việc nhà tù thay đổi cuộc sống thực sự như thế nào.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2019, 'Vietsub', 'HD 720p', 'Âu Mỹ', 0, '[{"name":"Danielle Brooks","avatar":""},{"name":"Taylor Schilling","avatar":""},{"name":"Taryn Manning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324382);
