INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sinh-tren-hoang-dao', 'Nữ Sinh Trên Hoang Đảo', 'Sounan Desu Ka', 'https://phimimg.com/upload/vod/20240229-1/a3e45214c58084194e7dfca5c3537030.jpg', 'https://phimimg.com/upload/vod/20240229-1/8b3e690cef58e9640c67d1e784800154.jpg', '<p>Vì một vụ tai nạn máy bay ... bắt đầu từ hôm nay, chúng tôi dành cả mùa xuân của cuộc đời mình trên một hòn đảo sa mạc !! Không có gì ở đây, vì vậy chúng tôi phải làm mọi thứ !! Và ăn tất cả mọi thứ !! (Ugh!) Hãy xem câu chuyện sinh tồn của nữ sinh trung học của chúng ta về lòng can đảm và kiến thức. Chúng tôi thực sự đang làm khá tốt! Chúng tôi học cách ăn ve sầu, cách chế tạo bẫy, thử nghiệm dị ứng đơn giản, cách ăn cua ẩn sĩ, v.v.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
