INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-greenhouse-phan-3', 'Học Viện Greenhouse (Phần 3)', 'Greenhouse Academy (Season 3)', 'https://phimimg.com/upload/vod/20240229-1/39028c952400b8e51b885e3ffa5c050a.jpg', 'https://phimimg.com/upload/vod/20240229-1/e36909cc1760e1c5ded5aa157a566454.jpg', '<p>Học Viện Greenhouse được chuyển thể từ hiện tượng teen quốc dân (Ha-Hamama) của Israel, bộ phim xoay quanh chị em nhà Woods, 8 tháng sau khi mẹ mất trong một vụ nổ tàu vũ trụ, họ ghi danh vào Học viện Greenhouse - một trường nội trú tư nhân cho các nhà lãnh đạo tương lai có năng khiếu. Thật không may, hai chị em lại phải gia nhập hai nhóm đối thủ truyền kiếp nhưng lại phải chung tay vào cuộc điều tra bí mật giữa hai nhóm để rồi phát hiện ra bí ẩn chết người buộc thành viên hai nhóm xóa bỏ hiềm khích, tạm gác các mối quan hệ cá nhân và hợp tác bảo vệ thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ariel Mortman","avatar":""},{"name":"Finn Roberts","avatar":""},{"name":"Chris O''Neal","avatar":""},{"name":"Dallas Hart","avatar":""},{"name":"Cinthya Carmona","avatar":""},{"name":"Benjamin Papac","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
