INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('once-upon-a-time-in-hollywood', 'Once Upon A Time… In Hollywood', 'Once Upon A Time… In Hollywood', 'https://phimimg.com/upload/vod/20240228-1/f75fee7bb2ac5cafbfb41019c5a63468.jpg', 'https://phimimg.com/upload/vod/20240228-1/75a671b8da709f9c96c17e8694d3957e.jpg', '<p>Los Angeles, năm 1969, cựu ngôi sao Rick Dalton và người đóng thế lâu năm cho anh là Cliff Booth nay đã thành những kẻ hết thời. Cả hai buộc phải đấu tranh để tồn tại giữa Hollywood khắc nghiệt. Cuối cùng, họ phải nhờ đến sự giúp đỡ của cô hàng xóm- nữ minh tinh xinh đẹp Sharon Tate. Do Quentin Tarantino làm đạo diễn, Leonardo DiCaprio cùng Brad Pitt thủ vai chính, không có gì ngạc nhiên khi Once Upon A Time được nhiều người xem là bộ phim đáng mong đợi nhất 2019.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Margaret Qualley","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Julia Butters","avatar":""},{"name":"Austin Butler","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Bruce Dern","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
