INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-sau-ven-toan', 'Trước Sau Vẹn Toàn', 'Never Say Never', 'https://phimimg.com/upload/vod/20240228-1/36ba9a815c9c1bb86360747900fefb3f.jpg', 'https://phimimg.com/upload/vod/20240228-1/cdce0945e765b3c7cdbf7f07a4bd1e5b.jpg', '<p>Tại căn cứ huấn luyện đặc nhiệm TX, khi Phương Hàn biết được tin người yêu là La Phi đã hy sinh trong lúc làm nhiệm vụ nằm vùng thì vô cùng đau buồn. Cũng đúng lúc này, trong cuộc đấu tranh tiêu diệt sào huyệt bọn buôn bán vũ khí và ma túy Long Lũy, không biết vì nguyên nhân gì mà thất bại thảm hại, số người thương vong rất lớn, thủ phạm chính là Long Lũy đã chạy trốn. Với sự khuyên nhủ đầy lý lẽ của trưởng phòng cơ quan phòng chống ma túy Hàn Sở Đông, Phương Hàn đã quyết định tiếp tục làm nhiệm vụ còn dang dở của La Phi, Phương Hàn đã đi đến thành phố Thương Lan phía nam đất nước, để tìm hung thủ đã giết La Phi và tóm gọn tổ chức buôn bán ma túy.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qin Jun Jie","avatar":""},{"name":"Sun Yi","avatar":""},{"name":"Wang Yong Quan","avatar":""},{"name":"Kent tong","avatar":""},{"name":"Haowen Xue","avatar":""},{"name":"Li Kun Lin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
