INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-raven', 'Black Raven', 'Black Raven', 'https://phimimg.com/upload/vod/20240228-1/0759ddf704b6ee082282a066645371c5.jpg', 'https://phimimg.com/upload/vod/20240228-1/f8effb7a6a5e669d2c16a90cacaa15b7.jpg', '<p>Ukraine 1922. Đế quốc Nga đã tan rã, nhưng một nhà nước mới vẫn chưa được thành lập. Nhiều người đã cố gắng tạo dựng và củng cố nền độc lập của mình trong thời kỳ này, và đây là câu chuyện về một trong những người như vậy. Đây là câu chuyện về cuộc đời và tình yêu của một người - Ivan, biệt danh Raven ...</p>', 'Full', 1, 'single', 'completed', 26, 2019, 'Vietsub', 'HD', 'Ukraina', 0, '[{"name":"Taras Tsymbaliuk","avatar":""},{"name":"Pavlo Moskal","avatar":""},{"name":"Danylo Mireshkin","avatar":""},{"name":"Ksenia Danilova","avatar":""},{"name":"Zoryana Marchenko","avatar":""},{"name":"Andrii Mostrenko","avatar":""},{"name":"Oleksii Trytenko","avatar":""},{"name":"Alina Kovalenko","avatar":""},{"name":"Nataliia Sumska","avatar":""},{"name":"Oleh Mosiichuk","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
