INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('evelyn', 'Evelyn', 'Evelyn', 'https://phimimg.com/upload/vod/20240228-1/31847f4c4c16d9fbb8a438a9fd9f2b26.jpg', 'https://phimimg.com/upload/vod/20240228-1/bdc4f544968794cc93457c0175346720.jpg', '<p>Bị ám ảnh bởi vụ tự sát của em trai, một đạo diễn cùng gia đình đi bộ xuyên nước Anh trong hành trình thử thách giàu cảm xúc mà đẹp mê hồn để chữa lành nỗi đau.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324382);
