INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-du-ky', 'Tiên Du Ký', 'Xian You Ji', 'https://phimimg.com/upload/vod/20240228-1/be1915c4d7562d6a5ad57a64d8eea18f.jpg', 'https://phimimg.com/upload/vod/20240228-1/4938fcd4ea107d264759b8931105d5c8.jpg', '<p>Tiên Du ký - Xianyouji 2019: Hoàng đế bị cao nhân pháp thuật Vệ Ngạn khống chế vì vậy quyền lực của Hoàng đế chỉ còn tồn tại trên danh nghĩa. Bên cạnh Hoàng đế có một người thân cận tên là Tiên Thỏ, cô là người mà năm đó Tiên Nhân dùng pháp thuật chế tạo ra, đời đời kiếp kiếp làm hộ vệ thân cận bên cạnh Hoàng đế. Ngoài ra, Tiên Thỏ cũng là người duy nhất biết được trên thế gian này chỉ có 4 người có thể chế ngự Vệ Ngạn, đồng thời 4 người này phải hợp sức lại với nhau mới có thể đánh bại Vệ Ngạn. Hoàng đế vì muốn diệt trừ Vệ Ngạn nên đã ra lệnh cho Tiên Thỏ đi tìm 4 người này. Chỉ cần tìm được họ thì mới có hy vọng ổn định giang sơn, bảo vệ dân chúng thiên hạ</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ô Giai Di","avatar":""},{"name":"Phí Tẩm Nguyên","avatar":""},{"name":"Tiêm Thụy Thanh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324382);
