INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-vo-chu', 'Trận Chiến Vô Chủ', 'Under Cover', 'https://phimimg.com/upload/vod/20240315-1/7545d5d47215b5837c0d6043724688fd.jpg', 'https://phimimg.com/upload/vod/20240315-1/151e096f33be8f5ce54813f687311872.jpg', '<p>Vào cuối triều đại nhà Thanh, phiến quân nổi dậy và thực hiện nhiều tội ác, liên tiếp lẻn vào cung điện và thực hiện các vụ ám sát. Nhưng tất cả đều thất bại. Vì lý do này, Dong Ha Xuyên sẵn sàng vào cung điện và độc lập ám sát Xianfeng. Nhưng khi thành công đã đến, cuộc xung đột dân sự của phiến quân đã sụp đổ. Trận chiến Dong Ha Xuyên và những người khác đã không thành công.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mai Dian Bang","avatar":""},{"name":"Bai Jian En","avatar":""},{"name":"Yang Hao Yuan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324382);
