INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-my-nam', 'Học Viện Mỹ Nam', 'Great Men Academy', 'https://phimimg.com/upload/vod/20240220-1/aaa6a8a649e4adb10f4533e090243289.jpg', 'https://phimimg.com/upload/vod/20240220-1/c472d2b49f792a0e5ecd4614ed061675.jpg', '<p>Học Viện Mỹ Nam (Great Men Academy) vietsub xoay quanh Học viện Great Men, ngôi trường dành cho các quý ông, nơi bắt đầu câu chuyện tình yêu của Love (New Chanyapuk Numprasop), một cô gái luôn mơ mộng về tình yêu với Vier (Ice Paris Intarakomalyasut), chàng trai nổi tiếng trong trường.&nbsp;Một ngày nọ, điều kỳ diệu xảy ra khi Love có thể biến thành một chàng trai (James Teeradon Supapunpinyo).&nbsp;Nên cô quyết định tận dụng điều này để đăng ký vào Học viện Great Men với hy vọng có thể đến gần Veir và giành được trái tim của anh. Nhưng có vẻ như mọi thứ không dễ dàng như cô mong đợi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"New Chanyapuk Numprasop","avatar":""},{"name":"James Teeradon Supapunpinyo","avatar":""},{"name":"Ice Paris Intarakomalyasut","avatar":""},{"name":"JJ Krissanapoom Pibulsonggram","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324382);
