INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mickey-manh-me', 'Mickey Mạnh Mẽ', 'Mickey And The Bea', 'https://phimimg.com/upload/vod/20240227-1/9818d705ecb4f0a8988349cc86cb0e34.jpg', 'https://phimimg.com/upload/vod/20240227-1/4e1ae5a3ae6b3398af25574d7e2f93b0.jpg', '<p>Mickey Mạnh Mẽ - Mickey and The Bear là câu chuyện kể về một thiếu nữ trẻ tuổi Michaela “Mickey” Peck sống cùng với bố Hank - cựu chiến binh. Mỗi ngày, Hank đều đắm chìm trong men rượu, hầu như chẳng khi nào tỉnh táo. Mọi chuyện tốt dần hơn với Mickey và bác sĩ tâm lý của cô là Leslee cũng đóng vai trò chủ động hơn trong việc chăm sóc Hank. Cha dần hồi phục, Mickey mắc kẹt giữa tình yêu, sự nghiệp và trách nhiệm đối với người cha của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Calvin Demba","avatar":""},{"name":"Camila Morrone","avatar":""},{"name":"James Badge Dale","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
