INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-tomiris', 'Huyền Thoại Tomiris', 'The Legend Of Tomiris', 'https://phimimg.com/upload/vod/20240227-1/4691974f10cb24339f4b5a144f1726a9.jpg', 'https://phimimg.com/upload/vod/20240227-1/68b54a0fbb1c0cbe5188657ee1708c35.jpg', '<p>Đây là câu chuyện về cuộc đời của nữ hoàng thảo nguyên vĩ đại - Tomiris huyền thoại. Cô được định sẵn để trở thành một chiến binh khéo léo, sống sót sau sự mất mát của những người thân thiết và đoàn kết các bộ tộc Scythia / Saka dưới quyền của cô.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Almira Tursyn","avatar":""},{"name":"Erkebulan Dairov","avatar":""},{"name":"Adil Akhmetov","avatar":""},{"name":"Aizhan Lighg","avatar":""},{"name":"Azamat Satybaldy","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
