INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-thep-2-khung-long-troi-day', 'Bầu Trời Thép 2: Khủng Long Trỗi Dậy', 'Iron Sky: The Coming Race', 'https://phimimg.com/upload/vod/20240227-1/c29114358f1c7a7494c6c29337bf42c7.jpg', 'https://phimimg.com/upload/vod/20240227-1/e9a3d6610a30c1f584d9f1c8ab0cae5a.jpg', '<p>Bầu Trời Thép 2: Khủng Long Trỗi Dậy - Iron Sky 2: The Coming Race (2019):Iron Sky: The Coming Race với ý tưởng khá là thú vị. Lấy bối cảnh 20 năm, sau cuộc xâm lăng của phát xít Đức từ mặt trăng, Trái Đất bị hủy hoại bởi chiến tranh hạt nhân. Nhưng con người vẫn còn hi vọng cuối cùng để sống còn đó là tiến vào trung tâm Trái Đất, một nơi hiện là sở hữu của giống bò sát có khả năng thay hình đổi dạng cùng đội quân khủng long hùng mạnh</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Lara Rossi","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Julia Dietze","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
