INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-nhat-chet-choc-2', 'Sinh Nhật Chết Chóc 2', 'Happy Death Day 2U', 'https://phimimg.com/upload/vod/20240227-1/203499710e661bd449522004558b361b.jpg', 'https://phimimg.com/upload/vod/20240227-1/bafe34d4737efff464f5ee640cf2d38f.jpg', '<p>Đã sống sót sau các sự kiện Farcical nhưng hoàn toàn đe dọa tính mạng trong Happy Death Day (2017), em gái Sorority phong kiến, cây Gelbman, tìm thấy bản thân trong cùng một ký túc xá đại học, biết ơn khi còn sống. Tuy nhiên, lần này là bạn cùng phòng của Carter, Ryan, người tuyên bố rằng anh ta đang sống lại một ngày nghịch lý cùng một lần nữa, với tư cách là một kẻ giết người hoang tưởng bí ẩn trong một mặt nạ trẻ con có răng có một con dao bếp lớn đã có thói quen giết anh ta. Trong những trường hợp đó, một dũng cảm nhưng vô ích cố gắng đối mặt với thử thách, một lần nữa, sẽ gửi cây trở lại quảng trường một, bị mắc kẹt trong một vòng lặp thời gian quá quen và máu quá quen thuộc. Có bao nhiêu cái chết tách cây khỏi một sinh nhật thực sự hạnh phúc?</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324382);
