INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-noi-doi-hoan-hao', 'Lời Nói Dối Hoàn Hảo', 'The Good Liar', 'https://phimimg.com/upload/vod/20240220-1/61c0933582d73945ec4a17a335401c06.jpg', 'https://phimimg.com/upload/vod/20240220-1/28b9f78e8e66a2738d6809b883f4ca6c.jpg', '<p>Hoàn thiện Con Man Roy Courtnay đã thiết lập các điểm tham quan của mình trên dấu ấn mới nhất của mình: Betty McLeish gần đây, trị giá hàng triệu người. Nhưng lần này, những gì đáng lẽ phải là một kẻ lừa đảo đơn giản leo thang thành một trò chơi mèo và chuột với các cổ phần cuối cùng.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
