INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-canh-noi-anh', 'Hạ Cánh Nơi Anh', 'Crash Landing on You', 'https://phimimg.com/upload/vod/20240312-1/730bba171e170e0b0d20e70ce51d45c4.jpg', 'https://phimimg.com/upload/vod/20240312-1/05197bbc8d624a3e0ae6c9fcdb7c6ee8.jpg', '<p>Báo Động Khẩn, Tình Yêu Hạ Cánh sẽ xoay quanh tình yêu của một nữ thừa kế người Nam Hàn tên Yoon Se Ri (Son Ye Jin) và một sĩ quan Bắc Hàn tên Ri Jung Hyuk (Hyun Bin). Trong một lần nhảy dù, nàng đã trót phải đáp xuống trên lãnh thổ Bắc Hàn vì điều kiện thời tiết và tình cờ &quot;rơi vào tay&quot; một chàng sĩ quan. Trong quá trình Jung Hyuk giúp Se Ri che giấu thân phận và bảo vệ cô, hai người đã dần nảy sinh tình cảm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 28, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Son Ye-jin","avatar":""},{"name":"Seo Ji-hye","avatar":""},{"name":"Kim Jung-hyun","avatar":""},{"name":"Yang Kyung-won","avatar":""},{"name":"Lee Sin-young","avatar":""},{"name":"Yoo Su-bin","avatar":""},{"name":"Tang Joon-sang","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Kim Young-min","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Jung Ae-ri","avatar":""},{"name":"Nam Kyung-eup","avatar":""},{"name":"Pang Eun-jin","avatar":""},{"name":"Choi Dae-hoon","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Park Hyeong-su","avatar":""},{"name":"Yoon Ji-min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324382);
