INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-tuyet-voi', 'Thế Giới Tuyệt Vời', 'Beautiful World', 'https://phimimg.com/upload/vod/20240220-1/cc151ddab61bb20cc8645ce458f15a18.jpg', 'https://phimimg.com/upload/vod/20240220-1/822c1ca78337a34f1eaa7ef18a5b3228.jpg', '<p>Thế Giới Tuyệt Vời kể về cặp vợ chồng Park Moo Jin (Park Hee Soon) và King In Ha (Choo Ja Hyun) có một cuộc sống tưởng như yên bình cho đến khi họ phát hiện con trai mình Sun Ho (Nam Da Reum) bị thương nghiêm trọng do bạo lực học đường. Đau đớn và căm phẫn, hai người quyết tìm ra sự thật. Ở bên kia chiến tuyến là Oh Jin Pyo (Oh Man Seok) và Seo Eun Joo (Cho Yeo Jeong), một cặp vợ chồng giàu có và địa vị xã hội cao chuyên dùng tiền và quyền để che đậy những lỗi lầm của đứa con trai ngỗ ngược.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hee Soon","avatar":""},{"name":"Choo Ja Hyun","avatar":""},{"name":"Oh Man Suk Jo Yeo Jung","avatar":""},{"name":"Nam Da Reum","avatar":""},{"name":"Kim Hwan Hee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324382);
