INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-lon-thoi-qua', 'Gió Lớn Thổi Qua', 'Blowing In The Wind', 'https://phimimg.com/upload/vod/20240220-1/818883ec9307e1be154c0f635e9ea726.jpg', 'https://phimimg.com/upload/vod/20240220-1/ea74e87d721351be98a7af7fb6d9ff07.jpg', '<p>Bộ phim kể về câu chuyện tình đan xen những bước trưởng thành trong cuộc sống của các cô cậu sinh viên. Vì muốn vực dậy hội leo núi của trường mà nữ sinh đại học Lâm Phong (Lý Khải Hinh đóng) đã làm quen với Hạ Địch (Hình Chiêu Lâm đóng) - một cựu thành viên của hội nhưng lại mắc chứng sợ độ cao. Trải qua một số hiểu lầm, nhờ có chung đam mê và mơ ước mà cả 2 ngày càng thân thiết. Lâm Phong đã giúp cho Hạ Địch vượt qua chứng bệnh của bản thân và vực dậy được câu lạc bộ leo núi.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hình Chiêu Lâm","avatar":""},{"name":"Lý Khải Hinh","avatar":""},{"name":"Chanon Santinatornkul","avatar":""},{"name":"Quách Vỹ Khiết","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324382);
