INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-mot-noi-chi-chung-ta-biet', 'Có Một Nơi Chỉ Chúng Ta Biết', 'Somewhere Only We Know', 'có một nơi chỉ chúng ta biết somewhere only we know trương siêu lý đình đình trần bác hào tôn gia linh trương chương lý cửu tiêu đặng úc lập lý hoan phương văn cường cung nhuệ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-gap-anh-2019', 'Muốn Gặp Anh', 'Someday Or One Day', 'https://phimimg.com/upload/vod/20240310-1/ddeef2543e7e1d01319b4fbb9801fb16.jpg', 'https://phimimg.com/upload/vod/20240310-1/6f67766a6d3daf06be51ea8f265f0723.jpg', '<p>Vũ Huyên mãi chìm đắm trong nỗi nhớ khôn nguôi khi người bạn trai Thuyên Thanh mất tích vì tai nạn máy bay. Bỗng một ngày, cô xuyên không trở về quá khứ năm 1998 trong cơ thể Trần Vận Như. Kỳ lạ là hai người trông giống hệt nhau, và Tử Duy - bạn của Vận Như lại giống hệt Thuyên Thanh. Điều đáng nói là trong hiện tại của Huyên, Vận Như bị giết vào đêm giao thừa năm 1999. Vì sao Huyên lại xuyên không về thời điểm của Trần Vận Như trong quá khứ? Nếu cô ngăn được việc Trần Vận Như bị giết, liệu tương lai có thay đổi không?</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 13, 2019, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Hứa Quang Hán","avatar":""},{"name":"Kha Giai Yến","avatar":""},{"name":"Nhan Lục Nhân","avatar":""},{"name":"Thi Bách Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
