INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-chuyen-toi-chuyen-sinh-thanh-slime-oad', 'Về Chuyện Tôi Chuyển Sinh Thành Slime OAD', 'Tensei Shitara Slime Datta Ken OVA, That Time I Got Reincarnated As A Slime OAD', 'https://phimimg.com/upload/vod/20240215-1/81eae02a5d11a8c0e2cd5fde0ac3d94e.jpg', 'https://phimimg.com/upload/vod/20240215-1/fc81d5cc30c44c9309f264b6d0eea009.jpg', '<p>Như thường lệ, Rimuru bị tranh giành cơ thể slime của mình bởi Shuna và Zion. Chương ngoại truyện vui nhộn về việc Rimuru và những thành viên all-star khác trong liên bang Jura Tempest tận hưởng sự nghỉ ngơi, thư giãn, thong thả thoáng chốc bên bờ hồ.</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
