INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-ngua-spirit-tu-do-rong-ruoi-cau-chuyen-ve-chu-ngua-spirit-phan-2', 'Chú Ngựa Spirit Tự Do Rong Ruổi Câu Chuyện Về Chú Ngựa Spirit (Phần 2)', 'Spirit Riding Free: Pony Tales (Season 2)', 'https://phimimg.com/upload/vod/20240215-1/e5c81949d29c0ac42e6b4d38292cf06b.jpg', 'https://phimimg.com/upload/vod/20240215-1/c8fa4a8a2a1bd7cd2963ad0d322136b2.jpg', '<p>Niềm vui lại tiếp diễn với Lucky và những người bạn cùng nhiều chuyến phiêu lưu nữa. Họ đi tới đâu, là vui tới đó... và bạn phải tham gia cùng!</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amber Frank","avatar":""},{"name":"Bailey Gambertoglio","avatar":""},{"name":"Sydney Park","avatar":""},{"name":"Darcy Rose Byrnes","avatar":""},{"name":"Gabriella Graves","avatar":""},{"name":"Duncan Joiner","avatar":""},{"name":"Nolan North","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
