INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-khoa-kin', 'Căn Phòng Khóa Kín', 'The Locked Room', 'https://phimimg.com/upload/vod/20240215-1/a5ed40292ac01c03a21cfe7bdb972dd7.jpg', 'https://phimimg.com/upload/vod/20240215-1/f72912a2e8e0ba253baa22d0e0496b9e.jpg', '<p>Căn Phòng Khóa Kín - The Looked Room kể về một lần tình cờ ở trên máy bay, người đàn ông lạnh lùng có tài mở khóa kỳ lạ đã thu hút sự chú ý của nữ cảnh sát Tần Tả Mạn. Trong một vụ án giết người kỳ lạ trong căn phòng bí mật, Tần Tả Mạn đã phát hiện người đàn ông đó hóa ra là chuyên gia an ninh trường đại học công an mời về- Mộc Hạ. Từ đó hàng loạt vụ án kỳ lạ về căn phòng bí mật kỳ quái không ngừng xuất hiện.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Viên Viện","avatar":""},{"name":"Kim Thế Giai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
