INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-trinh-tham', 'Bác Sĩ Trinh Thám', 'Doctor Detective', 'https://phimimg.com/upload/vod/20240209-1/a467233605c9368dd7f7dc8cec6052ea.jpg', 'https://phimimg.com/upload/vod/20240209-1/3775cec9a8225f75217174271e1a3c36.jpg', '<p>Doh Joong Eun từng rất nổi tiếng với danh hiệu “chuyên gia giải quyết những vụ án tai nạn lao động”. Tuy nhiên, sau khi kết hôn, cô chỉ muốn dồn toàn tâm, toàn sức chăm lo cho gia đình nhỏ. Khi phát hiện chồng ngoại tình, Joong Eun quyết định ly hôn và trở về làm “nữ hoàng phá án”. Cùng với chàng bác sĩ đồng nghiệp Huh Min Ki, họ đã tìm ra sự thật liên quan đến tai nạn công nghiệp và các sự cố khác tại các khu công nghiệp mà Tập đoàn TL muốn che đậy.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Bong Tae Gyu","avatar":""},{"name":"Lee Ki Woo","avatar":""},{"name":"Park Jin Hee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
