INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-mandalorian-phan-1', 'The Mandalorian (Phần 1)', 'The Mandalorian (Season 1)', 'https://phimimg.com/upload/vod/20240307-1/3fa2745135211bf716d669d661a1df66.jpg', 'https://phimimg.com/upload/vod/20240307-1/de76265bef846a46ef02735fff8cbab2.jpg', '<p>Sau sự thất bại của Đế chế dưới tay lực lượng nổi dậy, một thợ săn tiền thưởng đơn độc hoạt động trong Outer Rim, tránh xa sự thống trị của Tân Cộng hòa, đã trải qua nhiều cuộc phiêu lưu đầy bất ngờ và mạo hiểm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pedro Pascal","avatar":""},{"name":"Katee Sackhoff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
