INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-nang-truyen', 'Thanh Nang Truyện', 'Prodigy Healer', 'https://phimimg.com/upload/vod/20240205-1/a6d3949341679efa35aa9974ed0da70c.jpg', 'https://phimimg.com/upload/vod/20240205-1/dd7028a2fe812d2b774c1f042849e61e.jpg', '<p>Thanh Nang Truyện kể về Diệp Vân Thường (Triệu Lộ Tư), một cô nàng xinh đẹp và hiền lành. Trong một giấc mơ kỳ lạ, cô bị một con chim lớn mang đến một vùng đất kỳ diệu, mà nơi đó có Mộc Tinh Trần, chàng trai đặc biệt. Ở một thế giới khác, Vân Thường được trải nghiệm và chiêm ngưỡng nhiều điều mới lạ, và rồi đem lòng yêu mến Tinh Trần. Sau đó, hai người trở về đúng thời điểm hiện tại, lúc Nhật Bản đang gây áp lực lên trung hoa dân quốc. Cơ duyên giúp Tinh Trần trở thành một chiến sĩ, chiến đấu bảo vệ tổ quốc.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2019, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Lý Hoành Nghị","avatar":""},{"name":"Triệu Tư Lộ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324382);
