INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-ngoai-hanh-tinh-sai-tieu-that', 'Cô Gái Ngoài Hành Tinh Sài Tiểu Thất', 'My Girlfriend Is An Alien', 'https://phimimg.com/upload/vod/20240205-1/c4a8cd0b263cbcef9ebcdf7cce113298.jpg', 'https://phimimg.com/upload/vod/20240205-1/4badab686ecb1cf87d3fe0d99f7cc191.jpg', '<p>Cô Gái Ngoài Hành Tinh Sài Tiểu Thất kể về cô nàng Sài Tiểu Thất tới từ hành tinh Cape Town xuyên không đến trái đất và vô tình gặp Phương Lãnh - là một tổng tài cao lãnh, tài giỏi. Tuy nhiên Phương Lãnh lại có một căn bênh kì lạ là cứ mỗi khi trời mưa quên đi những người khác giới đã từng xuất hiên trong cuộc đời mình. Ở trái đất Tiểu Thất đã vô tình để mất dữ liệu và bị giữ lại. Để sống sót ở trái đất Tiểu Thất đã phải sử dụng rất nhiều siêu năng lực của mình, hết lần này đến lần khác tự mình giải quyết mọi khó khăn rắc rối. Từ đó mở ra câu chuyện tình vô cùng hài hước mà không kém phần lãng mạn.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vạn Bằng","avatar":""},{"name":"Từ Chí Hiền","avatar":""},{"name":"Dương Nguyệt","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
