INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tinh-lenh', 'Trần Tình Lệnh', 'The Untamed', 'https://phimimg.com/upload/vod/20240205-1/260088089e39734ae3998bd1eb36900d.jpg', 'https://phimimg.com/upload/vod/20240205-1/72541f9ed5e0eb6e68cd681379706c91.jpg', '<p>Giữa sự kình địch trong tộc của giới thần tiên, hai tri kỉ đối mặt với những âm mưu hiểm độc và vén màn bí mật đen tối liên quan đến sự kiện thảm khốc trong quá khứ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiếu","avatar":""},{"name":"Vương Nhất Bác","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Vu Bân","avatar":""},{"name":"Uông Trác Thành","avatar":""},{"name":"Lưu Hải Khoan","avatar":""},{"name":"Chu Tán Cẩm","avatar":""},{"name":"Vương Hạo Hiên","avatar":""},{"name":"Kỷ Lý","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
