INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-tinh-lenh', 'Trần Tình Lệnh', 'The Untamed', 'trần tình lệnh the untamed tiêu chiếu vương nhất bác mạnh tử nghĩa tuyên lộ vu bân uông trác thành lưu hải khoan chu tán cẩm vương hạo hiên kỷ lý ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-luc-tinh-yeu', 'Phụ Lục Tình Yêu', 'Romance Is A Bonus Book', 'https://phimimg.com/upload/vod/20240205-1/6c809ac2e2735da923dfc2dee41d4223.jpg', 'https://phimimg.com/upload/vod/20240205-1/f9d48d36c39885901bc927de7c355dbf.jpg', '<p>Cha Eun Ho là một nhà văn thiên tài và là trưởng ban biên tập trẻ nhất trong công ti của anh. Anh thông minh và đẹp trai. Tuy nóng tính trong công việc nhưng anh lại có một trái tim ấm áp và hiểu lý lẽ. Kang Dan Yi từng là nhà viết quảng cáo nổi tiếng, nhưng giờ thì cô đã hết thời. Hiện tại cô nghèo đói và thất nghiệp. Mặc dù cố gắng tìm công việc mới nhưng cô vẫn thất bại với sự nghiệp ấn tượng và bảng thành tích xuất sắc của mình. Cuối cùng cô được nhận một công việc ở công ti xuất bản bằng cách nói dối về lí lịch của mình. Cha Eun Ho là trưởng ban biên tập ở công ti đó và họ từ từ có tình cảm với nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jong-Suk","avatar":""},{"name":"Lee Na-Young","avatar":""},{"name":"Jung Eugene","avatar":""},{"name":"Wi Ha-Joon","avatar":""},{"name":"Kim Tae-Woo","avatar":""},{"name":"Kim Yu-Mi","avatar":""},{"name":"Kim Sun-Young","avatar":""},{"name":"Jo Han-Chul","avatar":""},{"name":"Kang Ki-Doong","avatar":""},{"name":"Park Gyu-Young","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
