INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-thanh-hung-nang-nua-thanh-mua', 'Nửa Thành Hửng Nắng Nửa Thành Mưa', 'Half Bright And Half Rain', 'https://phimimg.com/upload/vod/20240205-1/0114c87ba4a1c3ad33d957e390b813bc.jpg', 'https://phimimg.com/upload/vod/20240205-1/e6827706650c29525dcc8e081a0daa81.jpg', '<p>Kể về mối tình vượt không gian và thời gian giữa Thiên Tầm, một thực tập sinh của tòa soạn báo và Tô Minh Mâu, chàng trai dịu dàng ấm áp chuyên săn bắt yêu linh. 1000 năm trước, cả hai đã từng là một đôi tình nhân, nhưng do số phận nghiệt ngã đã phải lìa xa nhau. Thiên hồi luân chuyển, liệu tình yêu của cả hai có lại đơm hoa kết trái?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Fu Yu","avatar":""},{"name":"Lin Shijie","avatar":""},{"name":"Zhao Yu Cheng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
