INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('turu-ga-tay-me-quay', 'Turu: Gà Tây Mê Quẩy', 'Turu, The Wacky Hen', 'https://phimimg.com/upload/vod/20240219-1/7ec5ea3606011dbacb0f8a181ac256c9.jpg', 'https://phimimg.com/upload/vod/20240219-1/45d40a17c003cc43d4496fc9049fbf47.jpg', '<p>Sinh ra với sự khác biệt, cô gà mái Turu không thể đẻ trứng như các bạn gà mái khác và luôn mang trong lòng sự tự ti về bản thân. Cuộc đời của Turu bước sang một trang mới khi cô gà bé nhỏ được nhận nuôi bởi Isabel, một giáo viên âm nhạc đã nghỉ hưu. Quyết định chơi các bài hát với hy vọng rằng âm nhạc sẽ giúp Turu đẻ trứng, Isabel khám phá ra rằng cô gà của mình có thể hiểu được tiếng người và còn có một giọng hát vô cùng truyền cảm. Tai nạn không may khiến Isablel phải rời xa nông trang. Để gặp lại được Isabel, Turu sẽ trải qua một hành trình đặc biệt mà cô không hề ngờ tới.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Lồng Tiếng', 'HD', 'Tây Ban Nha', 0, '[{"name":"Eva Hache","avatar":""},{"name":"José Mota","avatar":""},{"name":"Ana Ángeles García","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324382);
