INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-dang-thuong', 'Cậu Bé Đáng Thương', 'Honey Boy', 'https://phimimg.com/upload/vod/20240219-1/08c4253be528406229ebc48108409063.jpg', 'https://phimimg.com/upload/vod/20240219-1/7131922bf12075166d3f7605be5942af.jpg', '<p>“Cậu Bé Ngọt Ngào (Honey Boy) là bộ phim được nam diễn viên Shia LaBeouf chắp bút viết kịch bản từ chính trải nghiệm của bản thân mình. Nhà làm phim tài năng thắng nhiều giải thưởng Alma Har’el đã mang lên màn ảnh rộng cuộc đời đầy sóng gió của một cậu bé mà sau này khi trưởng thành, cậu phải đấu tranh với chính người cha của mình giữa việc theo đuổi phim ảnh, niềm đam mê của mình, hay theo đuổi những ước mơ của cha. Kịch bản đã tiểu thuyết hóa tuổi thơ của một cậu bé khi tiến đến cương vị của một ngôi sao điện ảnh, và đau đớn chịu đựng cú tai nạn nghề nghiệp. Har’el chọn hai diễn viên Noah Jupe và Lucas Hedges vào vai Ortis Lort để khắc họa nhiều cảnh khác nhau trong sự nghiệp đầy thăng trầm của nhân vật. Diễn ...</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Lucas Hedges","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Byron Bowers","avatar":""},{"name":"Laura San Giacomo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
