INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dao-tau-giac-mo', 'Kẻ Đào Tẩu Giấc Mơ', 'Coma', 'https://phimimg.com/upload/vod/20240219-1/5af72b538360d679e20faceef293ab0c.jpg', 'https://phimimg.com/upload/vod/20240219-1/bd6bfa1d87f62f6e1ceadb910370b572.jpg', '<p>Một kiến trúc sư trẻ tài năng tỉnh dậy sau một tai nạn kinh hoàng và phát hiện rằng anh ta đang lạc trong một thế giới khác kỳ lạ và hỗn loạn. Thế giới đó được gọi là COMA và ở đó những toà nhà, những dòng sông và thành phố đều có thể tồn tại trong cùng một không gian của một căn phòng. Những định luật vật lý anh được học không còn đúng ở thế giới này và bên cạnh việc thích nghi, anh ta còn phải chiến đấu để bảo vệ mạng sống của mình cũng như tìm cách để thoát ra, trở về với thế giới thực.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Rinal Mukhametov","avatar":""},{"name":"Anton Pampushnyy","avatar":""},{"name":"Lyubov Aksyonova","avatar":""},{"name":"Milos Bikovic","avatar":""},{"name":"Konstantin Lavronenko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
