INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-hang-ma-truyen', 'Thục Sơn Hàng Ma Truyện', 'Shushan Subdues Evil', 'https://phimimg.com/upload/vod/20240219-1/4065b3103ff26a9b70e2645b6adf6eb5.jpg', 'https://phimimg.com/upload/vod/20240219-1/8ebf753c9a92c37bd1493fa60b253c09.jpg', '<p>Anh em Bai Ze và Lingfeng đã lớn lên ở Côn Lôn từ nhỏ. Bởi vì họ đi lạc vào cõi bí mật, mỗi người họ đều có một kho báu, Haotian Mirror và Peerless Magic. Sau khi được tiết lộ rằng Ling Feng đã thực hiện phép thuật, hai người đã bị Kunlun trục xuất khỏi giáo phái và đến thị trấn Baima trong thế giới phàm tục. Bai Ze và Ling Feng đã gặp những người yêu dấu của họ, Youyou và Yunmeng, và muốn dành phần còn lại của cuộc đời họ. Thật bất ngờ, Kunlun bị truy đuổi và giết chết, Yunmeng yêu dấu của Ling Feng đã chết một cách bi thảm, và Ling Feng rơi vào con đường của quỷ. Để trả thù Kunlun, Ling Feng đã giết hại chủ nhân của mình. Bai Ze không thể chịu đựng nổi và anh tuyệt vọng rồi dẫn đến trầm cảm,với sự giúp đỡ của Youyou, cuối cùng anh ta đã có một bản hùng ca.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Chen","avatar":""},{"name":"Mingze Wang","avatar":""},{"name":"Zixuan Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
