INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-kinh-thanh-bi-mat', 'Quyển Kinh Thánh Bí Mật', 'The Secret Scripture', 'https://phimimg.com/upload/vod/20240219-1/e4aa16571dc948f63238b320ba203ac3.jpg', 'https://phimimg.com/upload/vod/20240219-1/ee0ab742dd454f14c60c45d7d96522e1.jpg', '<p>Roseanne McNulty sẽ sớm được rời khỏi viện tâm thần Roscommon đã mục nát cũ kĩ ở Ireland mà bà gọi là nhà trong hơn 40 năm qua. Bác sĩ tâm thần của bệnh viện, tiến sĩ Stephen Grene, được gọi vào để đánh giá tình trạng của bà. Anh bị mê hoặc bởi những nghi lễ và những câu chuyện khó hiểu của Roseanne và sự gắn bó dữ dội của bà đối với cuốn Kinh thánh trong nhiều thập kỷ.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
