INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-luc-cau-vong', 'Trọng Lực Cầu Vồng', 'The Gravity Of The Rainbow', 'https://phimimg.com/upload/vod/20240126-1/4538491831940bee5842772fd6a827e7.jpg', 'https://phimimg.com/upload/vod/20240126-1/9c640fb4faa6e0cbbf4feccb317941d1.jpg', '<p>Hà Thái Hồng yêu đời nhiệt huyết phải lòng chàng giáo sư nghèo Lý Hoàng ham mê con chữ. Nhưng mẹ cô kiên quyết phản đối mối tình này vì sớm đã coi thiếu gia giàu có Tô Đông Lâm là con rể. Chuyện tình cảm chưa giải quyết xong thì hai cô bạn thân của Thái Hồng lại trở mặt thành thù. Hết bất ngờ này đến bất ngờ khác ập đến, Thái Hồng sẽ phải đưa ra lựa chọn thế nào cho bản thân?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Lượng","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Cao Dĩ Tường","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
