INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bup-be-ky-uc-violet-evergarden', 'Búp Bê Ký Ức: Violet Evergarden', 'Violet Evergarden: Eternity And The Auto Memories Doll', 'https://phimimg.com/upload/vod/20240207-1/c2073c9b7355f78d248bb5e0bbb16588.jpg', 'https://phimimg.com/upload/vod/20240207-1/e702526f6eee12411dab07541ae33440.jpg', '<p>Búp Bê Ký Ức: Violet Evergarden là một ngoại truyện của series anime đình đám Violet Evergarden, bộ phim xoay quanh Violet Evergarden - một nữ chiến binh người máy đã giải ngũ và bắt đầu công việc viết thuê tại bưu cục. Violet tình cờ gặp gỡ Isabella York - một cô bé bị bắt nhập học tại học viện dành riêng cho con gái của các gia đình danh giá. Từ đấy, Violet và Isabella chia sẻ với nhau nhiều điều về cuộc sống... Bộ phim được sản xuất bởi Kyoto Animation - một trong những xưởng sản xuất phim hoạt hình anime nổi tiếng nhất Nhật Bản, bộ phim đánh dấu sự trở lại của hãng phim sau sự cố hỏa hoạn đau thương.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yui Ishikawa","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Koki Uchiyama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
