INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-anh-hung-shazam', 'Siêu Anh Hùng Shazam', 'Shazam!', 'https://phimimg.com/upload/vod/20240207-1/053c4b2f083023becfbddc4222b5877d.jpg', 'https://phimimg.com/upload/vod/20240207-1/c18500bc4642751b8c2263bcaa1bd7b4.jpg', '<p>Tất cả chúng ta đều là người hùng, vấn đề ở chỗ chúng ta phải biết cách phát huy năng lực của mình. Trong trường hợp của Bill Batson (Angel), với sự giúp đỡ của một phù thủy cổ xưa, chỉ cần nói lớn từ “Shazam” là đứa trẻ 14 tuổi này có thể biến thành siêu anh hùng Shazam trưởng thành (Levi). Nhưng bên trong thân hình như một vị thần đó vẫn là trái tim của một đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Zachary Levi","avatar":""},{"name":"Asher Angel","avatar":""},{"name":"Jack Dylan Grazer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324382);
