INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('isnt-it-romantic', 'Isn''t It Romantic', 'Isn''t It Romantic', 'https://phimimg.com/upload/vod/20240205-1/1f774117fdc921eaefd85a44f29c17c0.jpg', 'https://phimimg.com/upload/vod/20240205-1/c934be3ff9e8bcb8a6aaba0e05764817.jpg', '<p>Một kiến trúc sư nữ độc thân béo có vấn đề tìm một người đàn ông. Cô ghét romcoms với kết thúc hạnh phúc không thực tế. Tại văn phòng NYC của cô, cô được đối xử thiếu tôn trọng bởi tất cả trừ hai người bạn của cô. Cô ngay lập tức rơi vào khách hàng mới đẹp trai. Cô đánh vào đầu mình trong một cơn lốc và thức dậy với tư cách là nhân vật chính trong một chiếc romcom nơi đàn ông thấy cô dễ thương. Khách hàng đẹp trai rơi vào cô.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324382);
