INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-hung-thu-phan-2', 'Truy Tìm Hung Thủ (Phần 2)', 'Mortel (Season 2)', 'https://phimimg.com/upload/vod/20240118-1/2b823b90ec3c6e53012a49998ff7f821.jpg', 'https://phimimg.com/upload/vod/20240118-1/dbaf9c19265368c02e7bd1bd8c71aab0.jpg', '<p>Sau khi giao ước với một nhân vật siêu nhiên, hai học sinh trung học nhận được sức mạnh phi thường và cùng hợp lực để giải quyết một vụ giết người.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Carl Malapa","avatar":""},{"name":"Némo Schiffman","avatar":""},{"name":"Manon Bresch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324382);
