INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-an', 'Lãnh Án', 'Cold Case', 'https://phimimg.com/upload/vod/20240118-1/97099a2f8ed93dce5c7ae0af02696432.jpg', 'https://phimimg.com/upload/vod/20240118-1/e5d03bd7dd2fa4155ae58e253cf841f4.jpg', '<p>Bộ phim là câu chuyện kể về nữ cảnh sát phòng chống ma túy La Anh Vĩ, vì chứng kiến bạn trai cũng là đồng nghiệp hi sinh trong khi thi hành nhiệm vụ, cô quyết tâm theo đuổi vạch trần âm mưu của tập đoàn ma túy Quỷ Xanh. Đồng hành cùng cô là ba nữ cảnh sát Thái Văn Tâm, Hạ Lạc Dương, và Phùng Nhất Tâm, thành lập nên Tiểu Đội Lãnh Án tiếp tục bước trên hành trình tìm kiếm chân tướng sự thật.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"LiYuan","avatar":""},{"name":"ShiShi","avatar":""},{"name":"WangYu","avatar":""},{"name":"ChenMuyang","avatar":""},{"name":"Pu Tao","avatar":""},{"name":"XuYuan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324382);
