INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nhan-legion-phan-3', 'Dị Nhân Legion (Phần 3)', 'Legion (Season 3)', 'https://phimimg.com/upload/vod/20240118-1/f07067219800daf5be4e1f767dbac13f.jpg', 'https://phimimg.com/upload/vod/20240118-1/86e4ebe9fa50b247007fdee432b529a2.jpg', '<p>Phim Dị Nhân Legion (Phần 3) - Legion (Season 3) 2019: xoay quanh David Haller - người được chẩn đoán bị tâm thần phân liệt lúc còn thiếu niên, David phải ở lại bệnh viện nhận sự điều trị từ các bác sĩ trong nhiều năm trời. Sau khi gặp gỡ với một bệnh nhân cùng viện, anh phát hiện ra sức mạnh phi thường của mình. David Haller cũng chính con trai của giáo sư X - Charles Xavier. David bị đa nhân cách nặng và cứ mỗi nhân cách lại có một sức mạnh khác nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Stevens","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"Mackenzie Gray","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324382);
