INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-thu-phong-than', 'Xuân Thu Phong Thần', 'Chun Qiu Fengshen', 'https://phimimg.com/upload/vod/20240207-1/9e49165b7c63e508924487640bc76ecc.jpg', 'https://phimimg.com/upload/vod/20240207-1/64a4e6fc0f6742c3f3568753e999a1b0.jpg', '<p>Vào cuối triều đại nhà Chu, vua Chu hành động một cách tùy tiện và cạn kiệt mọi nguồn lực để xây dựng sức mạnh quân sự của mình, khiến người dân phải sống một cuộc sống khốn khổ và đất nước đang trên bờ vực sụp đổ. Lợi dụng sự hỗn loạn, ma quỷ đến để gây xáo trộn trong thế giới loài người. Khi cơ thể của anh ta bị quỷ cáo chiếm giữ, Vua Chu ra lệnh bắt và giết tất cả thợ săn trên toàn quốc. Trong đó, có cha mẹ của Han Qi bị giết chết tàn nhẫn. May mắn thay, Han Qi được chúa tể của Thung lũng Linjing cứu. Han Qi trở thành bảo vệ Zishang trong thành phố Feng. Sau khi vượt qua các chướng ngại vật, họ loại bỏ những con quỷ trong thành phố Feng.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Rouxuan Fu","avatar":""},{"name":"Yijie Gong","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324382);
