INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tro-ly', 'Người Trợ Lý', 'The Assistan', 'https://phimimg.com/upload/vod/20240207-1/7c2c35f708704aaf556276a4b1f1463a.jpg', 'https://phimimg.com/upload/vod/20240207-1/c775c2b02eaf3e5c6e0baf025d53c7d6.jpg', '<p>Người Trợ Lý - The Assistant là cái nhìn cụ thể hơn về một trong cuộc đời của một vị trợ lý cho một người vô cùng quyền lực. Càng ngày Jane càng nhận ra trong công việc thường ngày của mình có những điều khuất tất đe doạ tới mọi khía cạnh trong công việc của cô.</p>', 'Full', 1, 'single', 'completed', 5, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jon Orsini","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"Owen Holland","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
