INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-muc-tieu', 'Khóa Mục Tiêu', 'Locked In', 'https://phimimg.com/upload/vod/20240207-1/018a1fda357a5a4fe8c1a59bae4caa02.jpg', 'https://phimimg.com/upload/vod/20240207-1/defb21b43941dfcb2af0e95267279bc5.jpg', '<p>Cơn bão ập đến, người lạ gõ cửa xin một nơi trú chân vì xe anh ta đã hết xăng. Bất đắc dĩ tin tưởng người lạ, Taylor không thể không tin rằng anh ta có liên quan đến cái chết của cha mình, vừa bị sát hại cách đây ít lâu. Bây giờ cô ấy phải dũng cảm bảo vệ người mẹ và giành sự sống với người đàn ông bí ẩn có động cơ độc ác này.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josie Davis","avatar":""},{"name":"Ryan Paevey","avatar":""},{"name":"Kaleigh Rivera","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324382);
