INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-thuy-danh-bo-luat-loi-nhuan', 'Lính Thủy Đánh Bộ: Luật Lợi Nhuận', 'Jarhead: Law Of Return', 'https://phimimg.com/upload/vod/20240128-1/4aa9d3a840994788d0e0067aa5eea3c1.jpg', 'https://phimimg.com/upload/vod/20240128-1/e433d7e9d92393dd1cf09e6e9270e62f.jpg', '<p>Thiếu tá Ronan Jackson (Devon Sawa), một phi công chiến đấu tài ba cho Lực lượng Quốc phòng Israel và con trai của Thượng nghị sĩ Hoa Kỳ (Robert Patrick), bị bắn hạ khi đang bay qua không phận Syria. Sau khi sống sót một cách kỳ diệu, Jackson bị một nhóm dân quân Hezbollah bắt giữ. Câu chuyện hấp dẫn và đầy sức mạnh với hành động khó nhằn, Jarhead: Law of Return theo chân một đội quân tinh nhuệ, do Trung sĩ xạ thủ Dave Torres (Amaury Nolasco) lãnh đạo, vì họ liều mạng với hy vọng cứu được đồng minh. đã không bao giờ gặp nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amaury Nolasco","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Jeff Pierre","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
