INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-bao-cao-mat', 'Bản Báo Cáo Mật', 'The Report', 'https://phimimg.com/upload/vod/20240128-1/9d6d8f3dbf34aa9dbd975536fa3dc086.jpg', 'https://phimimg.com/upload/vod/20240128-1/6bdec765ee34da41e39d11954327183a.jpg', '<p>The Report kể về nhân viên của Thượng viện lý tưởng Daniel J. Jones, được ông chủ của mình giao nhiệm vụ chỉ đạo một cuộc điều tra về Chương trình giam giữ và thẩm vấn sau ngày 9/11 của CIA, khám phá những bí mật gây sốc.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Driver","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Jon Hamm","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324382);
