INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-hang-ma-truyen-2', 'Thục Sơn Hàng Ma Truyện 2', 'The Legend Of Zu 2', 'https://phimimg.com/upload/vod/20240128-1/e06b88b1ff4768069a91de41e082e691.jpg', 'https://phimimg.com/upload/vod/20240128-1/6db0c25f0ee6936b206859ea414e9542.jpg', '<p>Vân Cư Nhạn phản đồ Nga Mi thu thập năm viên đá thần do thú dữ thượng cổ huyền bí để thống nhất tam giới, hồi sinh lại Nga Mi, Côn Luôn hai vị sư tổ phá hủy Nga Mi. Ba giới vừa mới từ trong tiên ma đại trận yên bình lại một lần nữa rơi vào mối nguy. Tiêu Hà vì mau chóng tập hợp các viên đá thần trước Vân Cử Nhạn nhằm phá hoại âm mưu của cô ta, và Nguyên Ấu Thanh cùng nhau dẫ đầu các đệ tử, đi lên con đường để tìm những viên đá. Dưới sự giúp đỡ của Côn Luân sư thúc, Tiêu Dao Từ- những người đã rút lui khỏi giang hồ ,Tiêu Hà và Nguyên Ấu Thanh một nhóm đông rơi xuống nơi yêu quái chiến đấu với rồng quỷ. Thậm chí không tiếc hi sinh sinh mạng.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bành Ngưu Khư","avatar":""},{"name":"Từ Thiếu Cường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324382);
