INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-gio-song-sinh', 'Sóng Gió Song Sinh', 'Song Naree', 'https://phimimg.com/upload/vod/20240215-1/36d66b27327f0e71931bcf7a27e1dd0d.jpg', 'https://phimimg.com/upload/vod/20240215-1/9c667c684c0dff1c5c313c99ca75047f.jpg', '<p>Sóng Gió Song Sinh là bộ phim tâm lý, tình cảm Thái Lan xoay quanh hai chị em song sinh có khuôn mặt giống hệt nhau nhưng tính cách hoàn toàn khác nhau. Cha mẹ của cặp sinh đôi Neung và Song ly dị khi cả hai còn bé. Neung là chị lớn được mẹ nuôi dưỡng, còn em gái Song được cha chăm sóc. Cả hai lớn lên với môi trường và hoàn cảnh sống khác nhau khiến cho tính cách cũng trở nên hoàn toàn trái ngược. Với Neung, cô lớn lên trong nghèo khó với mẹ và cha dượng. Neung tự tin vào bản thân, chiều chuộng và thích vui chơi, đặc biệt là với đàn ông. Còn về Song, sau khi cha qua đời, cô nhận được sự giáo dục tốt và mái ấm từ người dì và chú nên trở thành một cô gái dịu dàng, trong sáng và hồn nhiên. Khi Neung gây chuyện và gặp rắc rối với Ard, là một cảnh sát, anh bắt đầu nghi ngờ nhiều điều về cô. Đặc biệt là khi anh gặp Song, vị hôn thê của em trai khiến cho anh nhầm tưởng rằng Song chính là Neung. Càng ngày Neung càng gây ra nhiều vấn đề rắc rối, nhưng Ard lại luôn khăng khăng nghi ngờ và đổ lỗi lên Song.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Min Peechaya Wattanamontree","avatar":""},{"name":"Thunwa Suriyajak","avatar":""},{"name":"Great Sapol Assawamunkong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"