INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-than-bi-cua-muc-da-than-tien-nhan', 'Chuyện Thần Bí Của Mục Dã: Thần Tiên Nhãn', 'Mystery Of Muye: God Eyes', 'https://phimimg.com/upload/vod/20240126-1/98acc47105138b76d55838729b78ff2f.jpg', 'https://phimimg.com/upload/vod/20240126-1/bf6298d1dc9df13a476ccd7dd60eea10.jpg', '<p>Một kẻ trọm mộ kiêu ngạo và tham lam phát hiện ra một người phụ nữ có làn da trắng như tuyết trong ngôi mộ cổ khi anh ta đang tìm kiếm một kho báo cổ xưa. Người phụ nữ này thực chất là một công chúa và có đối mắt có thể nhìn xuyên thấu mọi việc từ thời cổ đại đến nay. Sự xuất hiện của công chúa đã phá vỡ hòa bình của thế giới và cuộc phiêu lưu của họ đã khiến cả hai phải lòng nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Khưu Bá Hạo","avatar":""},{"name":"Lỹ Vũ Dương","avatar":""},{"name":"Thang Mẫn","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324383);
