INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-2019', 'Hàng Xóm', 'My Lovely/Handsome Neighbor', 'https://phimimg.com/upload/vod/20240124-1/3697bb1f9af1b5f78ed1e04fc3f5eb36.jpg', 'https://phimimg.com/upload/vod/20240124-1/d7d2e30d56b3ccbfd06c3dc606c64e25.jpg', '<p>Một đội nghe trộm do Yoo Dae Kwon (Jung Woo) đứng đầu nhận chỉ thị của chính phủ theo dõi ứng cử viên tổng thống Lee Ui Sik (Oh Dal Soo) và các thành viên gia đình của ông đang bị quản thúc sau khi hồi hương từ nước ngoài. Các thành viên của đội nghe trộm cải trang thành một gia đình, chuyển đến nhà bên cạnh Lee Ui Sik, giả làm hàng xóm và bắt đầu hoạt động giám sát. Sau đó, trong vô số nội dung nghe lén có vẻ bình thường, bí mật từ từ lộ ra. Yoo Dae Kwon dần bị tính cách của Lee Ui Sik chinh phục và quay sang ủng hộ ông, giúp Lee Ui Sik lật ngược tình thế bất lợi trong cuộc tổng tuyển cử.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Bàng Ngỗ Mỗ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324383);
