INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-an-danh', 'Điệp Viên Ẩn Danh', 'Spies In Disguise', 'https://phimimg.com/upload/vod/20240123-1/8bb56e8fbfd7814174f776ced5322842.jpg', 'https://phimimg.com/upload/vod/20240123-1/a8c68fe2f3f1c7a19229e897c5f3c003.jpg', '<p>Super Spy Lance Sterling và Nhà khoa học Walter Beckett là hầu hết các mặt đối lập. Lance mượt mà, Suave và Debonair. Walter thì không. Nhưng những gì Walter thiếu các kỹ năng xã hội, ông bù đắp trong Smarts và phát minh, tạo ra các tiện ích tuyệt vời của Lance sử dụng trên các nhiệm vụ hoành tráng của mình. Nhưng khi các sự kiện thực hiện một bước ngoặt bất ngờ, Walter và Lance đột nhiên phải dựa vào nhau một cách hoàn toàn mới. Và nếu cặp vợ chồng kỳ lạ này không thể học cách làm việc như một đội, cả thế giới đang ở trong tình trạng nguy hiểm.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324383);
