INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('habibie-ainun-3', 'Habibie & Ainun 3', 'Habibie & Ainun 3', 'null', 'https://phimimg.com/upload/vod/20240123-1/89b2fb019e54c0bd19d24a0c08a58027.jpg', '<p>Trong phim tiểu sử này, một sinh viên y khoa thách thức các chuẩn mực xã hội để trở thành một bác sĩ – rồi cuối cùng trở thành đệ nhất phu nhân Indonesia.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Reza Rahadian","avatar":""},{"name":"Maudy Ayunda","avatar":""},{"name":"Jefri Nichol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
