INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doa-hong-cua-toi', 'Đóa Hồng Của Tôi', 'Rosebud', 'https://phimimg.com/upload/vod/20240123-1/af600c54ad20635eb90a943c6c8f6058.jpg', 'https://phimimg.com/upload/vod/20240123-1/7f2e28c477d831562889cf08cb1ad15c.jpg', '<p>Đóa Hồng Của Tôi - Rosebud (2019):Đóa Hồng Của Tôi kể về Jang-mi – một bà mẹ đơn thân luôn cố gắng hi sinh bản thân để chăm sóc cho đứa con gái của mình. Hồi còn con gái, bà ấy rất mê ca hát và cũng được trời phú cho giọng ca làm say đắm biết bao con tim, một hãng thu âm nổi tiếng lúc bấy giờ đã mời Jang-mi đến cộng tác. Tuy nhiên mọi sự chưa đâu đến đâu thì cô gái trẻ lúc đó đã phải từ bỏ con đường ca hát chỉ vì đi chơi vào một đêm mưa. Mãi đến sau này, khi tình cờ gặp lại bạn trai cũ thì từng góc khuất trong cuộc đời bà mới được hé lộ, cũng từ đó cuộc sống không còn êm đềm nữa mà trở nên phức tạp hơn rất nhiều.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Ho-Jung","avatar":""},{"name":"Park Sung-Woong","avatar":""},{"name":"Oh Jungse","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
