INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-quai-vat', 'Phỏng Vấn Quái Vật', 'Interviewing Monsters', 'https://phimimg.com/upload/vod/20240123-1/a99d0e5c52465f549cbceeb66214c583.jpg', 'https://phimimg.com/upload/vod/20240123-1/179916e2205cd35c455e90a4849eb391.jpg', '<p>Một giáo sư đại học đáng kính, Cory Mathis (Les Stroud) cho rằng vợ mình đã bị một quái vật trong rừng giết chết, và ông dần bị ám ảnh bởi nỗi ám ảnh và sự trả thù. Ông hợp tác với thợ săn Big Foot huyền thoại Fran Andersen (Stacy Brown Jr.), người đã đặt mục tiêu sẽ giành tiền thưởng Nat Geo 10 triệu đô la để bắt con quái vật. Thật không may, nhân viên kiểm lâm của cuốn sách, Billy Teal (Tom Green), một điệp viên chính phủ bí mật và cũng là một tên lừa đảo chuyên nghiệp (Rick Dyer) có kế hoạch khác. Bộ phim là một vở hài kịch đen tối và dí dỏm với một nhân vật chính dị thường, một câu chuyện xoắn não, và một loạt các sự kiện đã tạo nên về một kết thúc đầy bất ngờ.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Les Stroud","avatar":""},{"name":"Stacy Brown Jr.","avatar":""},{"name":"Tom Green","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324383);
