INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-phong-than-na-tra-nao-hai', 'Tân Phong Thần: Na Tra Náo Hải', 'Nezha Conquers The Dragon King', 'https://phimimg.com/upload/vod/20240123-1/75059280c974b22544d63b1e71272088.jpg', 'https://phimimg.com/upload/vod/20240123-1/2641b1655740cd25fa2d8da52594814a.jpg', '<p>Thời nhà Thương thảo, Thần vị Thiên giới thiếu trống, Nhân gian ma quỷ lộng hành, Lê dân chịu vàn khổ cực. Trong đêm Trần Đường quan, Xà tinh Thạc Tị vào một hộ dân, đại khai sát giới,trong lúc cướp đi con nhỏ của nhà này, thì Lí Tịnh nghe tin xông tới, Kéo cung càn khôn bắn ba múi tên, mũi thứ ba bắn lật xà tinh, Xà tinh trọng thương độn thổ đi mất. Lí Tịnh không bắt đước xà tinh, nản lòng. Xà tinh trốn ở một chỗ trị thương ,trong lòng thù hận vô cùng , tìn thời cơ báo thù.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Miu Tse","avatar":""},{"name":"Miu Tse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324383);
