INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dau-ban-be', 'Giải Đấu Bạn Bè', 'Buddy Games', 'https://phimimg.com/upload/vod/20240121-1/7b37615a2f9853da9e10fb34cd20e58c.jpg', 'https://phimimg.com/upload/vod/20240121-1/3d2d2d44991d3d9316839ecbf5bf0e60.jpg', '<p>Josh Duhamel (Transformers) Sao trong bộ phim hài hoang dã và vui nhộn này, không bị cấm. Sau sáu người bạn suốt đời đã rơi vào năm năm, Bob (Duhamel), còn gọi là Bobfather, đoàn tụ những người bạn của anh ta cho những trò chơi Buddy, một cuộc thi điên rồ của những thách thức về thể chất và tinh thần vô lý với cơ hội giành được 150.000 đô la. Bây giờ tất cả các cược đã tắt, như những người quyết định chiến đấu, móng vuốt, và tiệc tùng cho những chiếc Big Bucks trong Funded Bro-Fest này có Dax Shepard (Chips), Olivia Munn (Bữa tiệc Giáng sinh văn phòng) và Kevin Dillon (Entourage) .</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Bakkedahl","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"James Roday","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Nick Swardson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324383);
