INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-sau-cuong-bao', 'Cá Sấu Cuồng Bạo', 'The Blood Alligator', 'https://phimimg.com/upload/vod/20240121-1/fd2493bb84b878e52875d53292011051.jpg', 'https://phimimg.com/upload/vod/20240121-1/ece9993a7d7fb6870a509eb307f3faee.jpg', '<p>Phim Cá Sấu Cuồng Bạo kể về nhà khoa học Trần Tịnh, cô biết được chuyện chồng sắp cưới của mình bị cá sấu tấn công, đã ngay lập tức kiên quyết gia nhập vào đội thám hiểm. Nhưng người Khởi sướng tất cả những việc này là ông chủ của người chồng sắp cưới. Trên lập trường của lý luận và bảo vệ môi trường, Trần Tịnh đã chiến đấu với thế lực tà ác, và cuối cùng đã giành được thắng lợi. Bộ phim này chủ yếu cho thấy sự lựa chọn của các nhà khoa học khi đối mặt gữa 2 vấn đề nghiên cứu khoa học bất hợp pháp và đạo đức cá nhân. Nhân vật chính Trần Tịnh luôn giữ vững lập trường. Kiên quyết không bước vào ranh giới của các hành vi bất hợp pháp. Vì bảo vệ môi trường chiến đấu với thế lực đen tối. Cuối cùng đã đánh bại phe phản diện và bảo vệ.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bảo La Khải","avatar":""},{"name":"Khổng Hân Bác","avatar":""},{"name":"Trương Húc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
