INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ngoai-hanh-tinh-dien-cuong', 'Người Ngoài Hành Tinh Điên Cuồng', 'Crazy Alien', 'https://phimimg.com/upload/vod/20240104-1/55180968deae5a44017aba465d1b2b52.jpg', 'https://phimimg.com/upload/vod/20240104-1/00f9f48a698b449b1be7f10778bc09a1.jpg', '<p>Cảnh Hạo (Hoàng Bột) cùng với người anh em tốt của mình là Đại Phi (Thẩm Đằng) một lòng muốn phát tài nhưng sự nghiệp của mỗi người đều vô cùng ảm đạm. Một hôm, sự xuất hiện ngoài ý muốn của “vị khách đến từ hành tinh khác” đã phá vỡ đi cuộc sống bình yên của cả hai. Lực lượng bí mật phương Tây cũng đã phái biệt đội điều tra tung tích toàn cầu của người ngoài hành tinh này và mở ra nhiều câu chuyện dở khóc dở cười khác nhau...</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bo Huang","avatar":""},{"name":"Shen Teng","avatar":""},{"name":"Matthew Morrison","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324383);
