INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-thuc-dua-em-den', 'Mỹ Thực Đưa Em Đến', 'Meet In Gourmet Food', 'https://phimimg.com/upload/vod/20240116-1/ac82adcef67c97aa8d6c1e4bf50b8c27.jpg', 'https://phimimg.com/upload/vod/20240116-1/85a1fe04c16dfa12d4aa68c85125bd63.jpg', '<p>Mỹ Thực Đưa Em Đến, Meet in Gourmet Food 2019 Mỹ Thực Đưa Em Đến (Vô Cùng Thích Em) xoay quanh nữ sinh Tô Tiểu Hề - một cô gái có vị giác vô cùng nhạy bén. Cô luôn âm thầm theo đuổi ước mơ khám phá những ẩm thực đặc sắc. Cô vô tình gặp gỡ Lý Thời, một đầu bếp thiên tài cao lãnh đang bắt đầu khởi nghiệp với quán ăn của mình. Dù tính tình trái ngược, nhưng ẩm thực đã khiến họ xích lại gần nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Bác Hào","avatar":""},{"name":"Chư Chỉ Oánh","avatar":""},{"name":"Yến Tử Đông","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
