INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-den', 'Tiền Đen', 'Money', 'https://phimimg.com/upload/vod/20240104-1/01fdba523b89b5038f1367fc9be644e9.jpg', 'https://phimimg.com/upload/vod/20240104-1/3c9187161a2a1275eb7f8843f7e401b3.jpg', '<p>Tiền Đen - Money (2019): Cho Il-hyun (Ryu Jun-yeol) – một nhân viên môi giới chứng khoán mới vào nghề đang khao khát làm giàu. Không có “ô dù” hay quan hệ trong ngành, Il-hyun đứng trước nguy cơ bị sa thải với “thành tích” 0 Won lợi nhuận. Trong cơn bĩ cực, cậu được giới thiệu với một nhân vật bí ẩn đầy quyền lực có bí danh là Lệnh Bài (Yoo Ji-tae). Việc nhận lời tham gia vào những giao dịch đen của Lệnh Bài giúp cho Il-hyun phất lên nhanh chóng. Chính sự giàu lên “bất thường” này của Il-hyun khiến cậu lọt vào tầm ngắm của Han Ji-cheol (Jo Woo-jin) thuộc Sở Thanh tra Tài chính, người truy lùng Lệnh Bài hòng lật tẩy bộ mặt thật của hắn...</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryu Jun-yeol","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Jo Woo-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324383);
