INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-toi-thuong', 'Sức Mạnh Tối Thượng', 'God Of War II', 'null', 'https://phimimg.com/upload/vod/20240104-1/e8a80e165126c60c0d8b07d6c2b462e6.jpg', '<p>Sức Mạnh Tối Thượng - God of War II là một phiên bản khác xa với cốt truyện quen thuộc trước đây về bộ 3 Đổng Trác, Điêu Thuyền và Lữ Bố. Lữ Bố vốn là một ác quỷ vô danh mang số hiệu 19 được triều đình thử nghiệm để trở thành cỗ máy sát thủ phục vụ cho chiến tranh. Vô tình được Điêu Thuyền cứu sống sau một lần nổi cơn nộ sát, bị trọng thương. Cả hai đem lòng yêu nhau nhưng Lữ Bố vốn là món tài sản đắt giá, bị truy lùng gắt gao. Bình yên bên người đẹp chưa bao lâu thì sóng gió ập tới, cả làng Điêu Thuyền bị tàn sát, Lữ Bố bị bắt đi và mất luôn trí nhớ. Để nhiều năm sau gặp lại, chàng là một võ tướng bách chiến bách thắng, còn nàng là vật phẩm dâng hiến cho Đổng Trác, lúc này là cha nuôi của Lữ Bố, chuyện tình tay 3 phức tạp bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Bách Khiếu","avatar":""},{"name":"Lĩnh Diễn Chính","avatar":""},{"name":"Lưu Dữ Hy","avatar":""},{"name":"Mạnh Anh Hào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
