INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-vinh-cuu', 'Tình Yêu Vĩnh Cửu', 'Sunrise In Heaven', 'https://phimimg.com/upload/vod/20240104-1/3d3ec2d3eb9269f5e6ccc0e61dc100e4.jpg', 'https://phimimg.com/upload/vod/20240104-1/32c8efbda1af7ad6fdf726c52e71c3b6.jpg', '<p>Một câu chuyện tình yêu đích thực kéo dài suốt đời nhưng cuối cùng dẫn đến một sự mất mát của tình yêu đau đớn. Jan là con gái của một người cha chiến binh quá bảo vệ, nhưng điều đó không ngăn cô ấy yêu Steve, một GI giới trẻ trong không quân.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
