INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-4-hoi-cuoi', 'Diệp Vấn 4: Hồi Cuối', 'Ip Man 4: The Finale', 'https://phimimg.com/upload/vod/20231231-1/0dc7261d91342b41217b09693af1bed4.jpg', 'https://phimimg.com/upload/vod/20231231-1/55018f0671c5eabe0497eac975e3e9a3.jpg', '<p>Diệp Vấn 4 là câu chuyện tiếp theo khi kết thúc phần 3, Diệp Vấn trở thành gà trống nuôi con khi vợ mất vì bệnh ung thư. Phần 4 tiếp tục mạch truyện trước nhưng mốc thời gian là vào năm 1964, lúc này Diệp Vấn đã hơn 70 tuổi. Phát hiện mình bị ung thư thanh quản do nhiều năm hút thuốc, chưởng môn họ Diệp sau đó đã quyết định sang San Francisco (Mỹ) để kiếm trường cho con và dạy võ. Thế nhưng người Mỹ lại không hiểu được võ thuật Trung Hoa. Đồng thời chính Diệp Vấn lại bị thử thách nhiều lần ngay trên đất Mỹ, nơi cộng đồng Hoa kiều bị dân Mỹ nhìn với ánh mắt phân biệt.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Hồng Kông', 1, '[{"name":"Scott Adkins","avatar":""},{"name":"Chung Tử Đơn","avatar":""},{"name":"Trần Quốc Khôn","avatar":""},{"name":"Ngô Kiến Hào","avatar":""},{"name":"Ngô Thiên Ngữ","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324383);
