INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-ke-dem-giang-sinh', 'Truyện Kể Đêm Giáng Sinh', 'A Storybook Christmas', 'https://phimimg.com/upload/vod/20231231-1/ab49d655153727327c9fdc50f3848fef.jpg', 'https://phimimg.com/upload/vod/20231231-1/048687a125e624752e196f263151836a.jpg', '<p>Đó là mùa Giáng sinh bận rộn hơn bình thường đối với Celeste Everette. Ngoài việc ở công ty giờ đây cô cũng là người bảo vệ cho cháu gái của mình. Đây sẽ là Giáng sinh thứ hai họ trải qua cùng nhau như một gia đình. Celeste đã hoãn đám cưới của mình với luật sư Brandon vào phút cuối để cháu gái mình có 1 Giáng sinh hoàn hảo.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ali Liebert","avatar":""},{"name":"Jake Epstein","avatar":""},{"name":"Habree Larratt","avatar":""},{"name":"Victoria Maria","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
