INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-doc-quyen-gap-lai-tinh-yeu', 'Ký Ức Độc Quyền: Gặp Lại Tình Yêu', 'Unique Memory: Farewell To Love', 'https://phimimg.com/upload/vod/20240102-1/e1f098fda439f24a31935c7d29232519.jpg', 'https://phimimg.com/upload/vod/20240102-1/3d565f4dcc57bf43e9cb5e044425032a.jpg', '<p>Khi Bai Lin và Song Qiqi đến thời điểm họ phải quyết định tình yêu của mình. Khi bước vào năm thứ tư Bai Lin bắt đầu thực tập. Nhưng vì thiếu tự tin Cô không dám đối mặt với tình cảm của Lý Gia Hàng dành cho mình. Về phần Song Qiqi, người đã làm việc chăm chỉ và tiết kiệm tiền để học tập, Phải làm việc cùng với người tôi từng thích như Xiao Zheng. Và cùng lúc đó, có một người cũng yêu cô như Diệp Phi, cách đó không xa. Họ sẽ chọn con đường tình yêu cuối cùng này như thế nào?</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Zhang","avatar":""},{"name":"Deng Yu Li","avatar":""},{"name":"Li Huan","avatar":""},{"name":"Fang Wen Qiang","avatar":""},{"name":"Ye Zi Cheng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324383);
