INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-truong-toi-pham', 'Hiện Trường Tội Phạm', 'A Witness Out Of The Blue', 'https://phimimg.com/upload/vod/20240102-1/e46515b88c34a39a20a7db3c15d1eb65.jpg', 'https://phimimg.com/upload/vod/20240102-1/d6a7d19d88edc4e29ace002db1f9244d.jpg', '<p>Hiện Trường Phạm Tội kể về câu chuyện của Uông Tân Nguyên (Cổ Thiên Lạc thủ vai) là tên cầm đầu của một băng nhóm tội phạm nguy hiểm, băng nhóm này đã thực hiện nhiều vụ cướp có giá trị lớn. Trong một vụ cướp cửa hàng đá quý, bọn chúng đã gây ra và để lại thương vong lớn cho nhiều người. Hai tháng sau, đồng bọn của Uông Tân Nguyên bị một người đàn ông cắt cổ, giết chết thảm hại ở trong phòng. Có thể vì phân chia không đồng đều giữa các thành viên nên trong nhóm nên đã xảy ra nội chiến, đấu đá tranh giành lẫn nhau, cảnh sát đã liệt Uông Tân Nguyên vào danh sách là nghi phạm số một của vụ án. Đi sâu vào điều tra, viên cảnh sát Lâm Pháp Nhiễm (Trương Kế Thông thủ vai) liệu có tìm ra chân tướng của vụ án và bắt tên hung thủ phải đền tội.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Jessica Hester Hsuan","avatar":""},{"name":"Kai-Chung Cheung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
