INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('al-acecho', 'Al Acecho', 'Al Acecho', 'https://phimimg.com/upload/vod/20240128-1/1dec9d04370f09d1e22f187ec9787811.jpg', 'https://phimimg.com/upload/vod/20240128-1/827f96e350451b9e6aa028114811dbc4.jpg', '<p>Park Ranger Pablo Silva (Rodrigo de La Serna) Xây dựng lại cuộc sống của mình ở điểm đến mới của mình, một nơi bị lãng quên và gặp khó khăn mà ít người muốn đi, Công viên Pereyra Ireola. Ngay sau đó, dưới sự yên tĩnh rõ ràng, ông phát hiện ra một mạng lưới những kẻ săn trộm. Bản năng thợ săn cũ của anh ta sẽ có anh ta trên Prowl. Anh ta sẽ có thể trốn tránh mọi người ngoại trừ chính mình.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324383);
