INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-mat-doi-em', 'Bóng Mát Đời Em', 'The Parentage', 'https://phimimg.com/upload/vod/20240112-1/80a38fc01041970dbb2acf351d1a1c95.jpg', 'https://phimimg.com/upload/vod/20240112-1/695915757a6a0b95590f6ed7c14905ea.jpg', '<p>Bóng Mát Đời Em - The Parentage - Câu chuyện Khẽ là một cô gái vô cùng xinh đẹp, con gái của một vị luật sư tài ba và có một giọng hát rất hay. Cô được hai người bạn thân đeo đuổi, Pit chân chành còn Rangsan lại là một người đào hoa. Số phận của khẽ trở nên đau khổ khi cô không chọn Pit mà lại yêu Rangsan. Yêu phải một người đào hoa được các cô gái săn đón, cô đã bị hãm hại mà cô phải mất con và trở nên tật nguyền lưu lạc khắp nơi... ngày gặp lại Pit cũng là ngày cô lìa đời với căn bệnh tim quái ác, để lại con gái với lời trối kỳ lạ.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 12, 2019, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Krissada Pornweroj","avatar":""},{"name":"Nutcha Jeka","avatar":""},{"name":"Ruangsak Loychusak","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324383);
