INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bacurau', 'Bacurau', 'Bacurau', 'https://phimimg.com/upload/vod/20240102-1/bdce100728d0b8da4cc68196ee33cd2e.jpg', 'https://phimimg.com/upload/vod/20240102-1/50ce743f6b303a6f30721cba1d07cdc0.jpg', '<p>Bacurau, một khu định cư nhỏ ở backcountry từ xa của Brazil, bị lung lay bởi cái chết của một người đàn ông lớn tuổi của nó. Nhưng một cái gì đó kỳ lạ đang xảy ra trong làng, và có rất ít thời gian để tang tóc. Nguồn cung cấp nước đã bị cắt đứt, động vật đang đóng dấu trên đường phố, và những quan tài trống rỗng đang bước lên bên lề đường. Một buổi sáng, dân làng thức dậy để tìm ngôi nhà của họ đã biến mất khỏi bản đồ vệ tinh hoàn toàn. Dưới mối đe dọa từ một kẻ thù vô danh, Bacurau niềng răng cho một cuộc chiến tàn bạo, đẫm máu để sinh tồn.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324383);
