INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nhan-cua-toi-la-quyen-su', 'Nữ Nhân Của Tôi Là Quyền Sư', 'Pushing Hand', 'https://phimimg.com/upload/vod/20240110-1/46b11f172a777fbf8892bc6832da3a0c.jpg', 'https://phimimg.com/upload/vod/20240110-1/fe899a0cbd1a40eea18c23c4f7ef36be.jpg', '<p>Liễu Thanh Dương là một người yêu xe mô tô, anh đã cứu Trần Nhất Phàm trong một cuộc đua xe. Cùng lúc đó, ba của Thanh Dương qua đời, để lại một món nợ, anh và mẹ phải đến công trường xây dựng để sinh sống. Trần Nhất Phàm đã cứu anh và tuyển anh vào làm việc tại tập đoàn bất động sản Minh Đức. Được thúc đẩy bởi ý thức trách nhiệm phải chăm sóc mẹ và trả hết nợ, Thanh Dương cố gắng chăm chỉ làm việc và dần trưởng thành. Tập đoàn Minh Đức có nguy cơ bị nuốt chửng bởi bốn đối thủ cạnh tranh lớn, Liễu Thanh Dương đã nhờ Mai Đạo viễn tái xuất để cứu lấy tập đoàn Minh Đức. Mai Đạo Viễn chọn Thanh Dương làm người đại diện của mình. Mai Đạo Viễn dạy Liễu Thanh Dương môn võ Thái Cực - Thôi Thủ - để anh có thể hiểu được đạo lý làm người và chân lý trong kinh doanh.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 11, 2019, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Giả Nãi Lượng","avatar":""},{"name":"Vương Âu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324383);
