INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-sieu-quay', 'Bộ Đôi Siêu Quậy', 'Adventure Boyz', 'https://phimimg.com/upload/vod/20231231-1/21d09a4b26199f4cd5323a7542c87f32.jpg', 'https://phimimg.com/upload/vod/20231231-1/9fa2028bdf76419645f401d4db5bd96e.jpg', '<p>Bộ phim Bộ Đôi Siêu Quậy - Adventure Boyz xoay quanh cuộc phiêu lưu kịch tính của 2 cậu bé cùng gia đình nhỏ của mình trong cuộc đụng độ không mong muốn. Trong lâu đài lớn nhất nước Anh, một tên trùm tội phạm khét tiếng đã đánh cướp và chọn làm căn cứ địa của mình nhưng điều bất ngờ xảy đến trong cuộc gặp gỡ giữa tay đua kiệt xuất và 2 cậu con trai trên chiếc BMW siêu ngầu. Liệu ông trùm có thể loại bỏ được những mối nguy hại này không?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Angela Dixon","avatar":""},{"name":"Howard J. Ford","avatar":""},{"name":"Jon Campling","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
