INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-quai-tren-song', 'Yêu Quái Trên Sông', 'The River Monster', 'https://phimimg.com/upload/vod/20231231-1/1a8d2230f022369035ffff694d133a81.jpg', 'https://phimimg.com/upload/vod/20231231-1/af28b27b6f6a138d070f9c5d33c5f356.jpg', '<p>Yêu Quái Trên Sông kể về Liễu Nhất Đao, biệt hiệu giang hồ là “Quỷ Đao”, vì để chữa trị bệnh tình cho muội muội là Tiểu Phiêu, không ngại quy ẩn giang hồ, đi khắp nơi để tìm danh y. Tiểu Loan, là cá chép Cẩm Lý, không may đến với nhân gian và bị người tại Nhân Yêu Các bắt đi. Liễu Nhất Đao vì muốn kiếm tiền nên đã giải cứu Tiểu Loan, và sau đó đã biết được thân phận thật của Tiểu Loan chính là Hắc Long chuyển thế. Lúc này, yêu tộc cũng đã thăm dò được tin tức của Tiểu Loan, muốn chiếm đoạt cô để kêu gọi Hắc Long phục sinh. Liễu Nhất Đao trong quá trình bảo vệ Tiểu Loan, hai người đã nảy sinh tình cảm với nhau. Về phía Tiểu Phiêu, vốn dĩ không chấp nhận sự có mặt của Tiểu Loan, nhưng dần dần hai người cũng đã trở thành bạn tốt.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324383);
