INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-long-nghia-hiep', 'Tấm Lòng Nghĩa Hiệp', 'The Imperial Guards Bloody For Blood', 'null', 'https://phimimg.com/upload/vod/20231231-1/a7d82292ee9012466e5e0927252ff83c.jpg', '<p>Tấm Lòng Nghĩa Hiệp - The Imperial Guards Bloody For Blood nội dung kể về Bạch Thống lĩnh Bạch Phi Hoàng cấu kết với Ninh Dương âm mưu hành thích hoàng thượng nhằm chiếm đoạt ngai vàng. Thẩm đại nhân giao số 27 và số 28 đón chuyến xe cá muối từ Ninh Dương Phủ lấy về hộp gấm quý. Trong chuyến đi này, 2 người đã phát hiện ra âm mưu của Bạch Phi Hoàng. Số 28 đã gặp A Nhược cô nương, người được Bạch Phi Hoàng cưu mang, khi cô biết Bạch Phi Hoàng lợi dụng cô dâng cho hoàng thượng tìm thời cơ hạ thủ hoàng thượng, cô đã nói cho số 28 kế hoạch của đó của hắn. Mọi chuyện sẽ phát triển như thế nào? Liệu Bạch Phi Hoàng có ám sát được hoàng thượng và chiếm được ngai vàng hay không?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yan","avatar":""},{"name":"Li Guangbin","avatar":""},{"name":"NIE Wen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
