INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cong-chua', 'Bí Mật Công Chúa', 'The Secret Of Princess', 'https://phimimg.com/upload/vod/20240123-1/8a7f7857e59611030eb9cf8beba676b3.jpg', 'https://phimimg.com/upload/vod/20240123-1/5aead73a04dfce8b8221cf4db6a523e8.jpg', '<p>Bộ phim Bí Mật Công Chúa - The Secret Of Princess kể về câu chuyện một đám cháy đã xảy ra tại kỹ viện Túy Nguyệt Phường ở Trường An, và một kỹ nữ tên là Kính Nguyệt bị thiêu chết, còn a hoàn Tiểu Hồng lại bị mất tích trong đám cháy. Tưởng chứng như chỉ là một vụ án bình thường, nhưng nó đã khiến Đại Lý Tự và Đại thái giám của Hoàng cung phải trực tiếp ra tay. Người đứng đầu Đại Lý Tự là Bùi Thiếu Khanh đã nhờ Tô Yến Nam, một người bạn của mình, giúp điều tra vụ án. Tô Yến Nam phát hiện ra rằng người chết trong đám cháy là a hoàn Tiểu Hồng, còn cô nương Kính Nguyệt đang mất tích và bị các thế lực truy sát. Kính Nguyệt cô nương có thân phận như thế nào, và đằng sau vụ cháy nay có âm mưu gì mà các thế lực lớn lại phải che giấu kỹ càng như vậy?</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lu Guandong","avatar":""},{"name":"Xu Shuying","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
