INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-uong-va-ket-hon', 'Ăn Uống Và Kết Hôn', 'Eat, Drink And Be Married', 'https://phimimg.com/upload/vod/20240123-1/03f6425ca81014f2561a6afc5546d43f.jpg', 'https://phimimg.com/upload/vod/20240123-1/afacaa6e4ca4cbba61d86ee5c122ff6f.jpg', '<p>Chỉ ba ngày sau ngày cưới của Jess và Max, họ đã sẵn sàng hủy bỏ đám cưới của mình do căng thẳng quá mức đối với việc vượt quá tầm kiểm soát của kế hoạch . Cuối cùng, họ đến gặp Billie, nhờ trợ giúp của Billie bằng cách lôi kéo cô ấy thêm trợ giúp cho công việc kinh doanh của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jocelyn Hudon","avatar":""},{"name":"Jake Foy","avatar":""},{"name":"Sam Robert Muik","avatar":""},{"name":"Sydney Scotia","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
