INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-leningrad', 'Giải Cứu Leningrad', 'Saving Leningrad', 'https://phimimg.com/upload/vod/20240123-1/f9014961eb5050804b030275390c7e36.jpg', 'https://phimimg.com/upload/vod/20240123-1/02382cb1952e6dbae7d4a91ee941b221.jpg', '<p>Lấy bối cảnh tại mặt trận phía Đông, phim xoay quanh hành trình chống chọi quyết liệt của những con người anh dũng trên chiếc sà lan 752, diễn ra vào đêm 16 đến 17 tháng 9 năm 1941 tại hồ Ladoga. Kostya cùng mọi người trên sà lan bị bao vây, họ tìm cách sơ tán người dân từ Leningrad nhưng không ngờ bị máy bay chiến đấu của quân đội Đức ném bom, khiến sà lan bị chìm.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Mariya Melnikova","avatar":""},{"name":"Gela Meskhi","avatar":""},{"name":"Anastasiya Melnikova","avatar":""},{"name":"Andrei Udalov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324383);
