INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giai-cuu-leningrad', 'Giải Cứu Leningrad', 'Saving Leningrad', 'giải cứu leningrad saving leningrad mariya melnikova gela meskhi anastasiya melnikova andrei udalov ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-thu-dam-mau', 'Tình Thù Đẫm Máu', 'A History Of Jealousy', 'https://phimimg.com/upload/vod/20240123-1/4c46ae0c32024c53ec2ee48ea8b3ba65.jpg', 'https://phimimg.com/upload/vod/20240123-1/bcfd7726c525123cb74edfb2491dc948.jpg', '<p>Một ngày trước ngày diễn ra buổi hòa nhạc lớn của Soo-min, những người bạn đại học của cô ấy là Won-ho, Sun-ki, Hong và Jin-sook đã tụ tập để ăn mừng Soo-min. Nói về những kỷ niệm cũ của họ và vui vẻ dường như là một khoảnh khắc vui vẻ của những người bạn cũ. Nhưng ngay sau khi Soo-min đi vào phòng tắm, Jin-sook bắt đầu một câu chuyện đáng lo ngại về Soo-min rằng cô đã bị lạm dụng tình dục bởi cha và anh trai của mình sau cái chết của mẹ cô. Khi tất cả bạn bè đều bị sốc, từng người một bắt đầu kể về toàn bộ bí mật của Soo-min như thể họ biết mọi thứ về cô ấy mà không biết Soo-min đang nghe lén cuộc trò chuyện của họ. Nó đẩy Soo-min đến sự trả thù không thể thay đổi với những bí mật đằng sau.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Nam Gyu-ri","avatar":""},{"name":"Oh Ji-ho","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Kim Seung-hyun","avatar":""},{"name":"Jo Han-sun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
