INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-hitandrun', 'Biệt Đội Hit-And-Run', 'Hit-and-Run Squad', 'https://phimimg.com/upload/vod/20231230-1/952a993fb6f5b9c537a041760cfbb78c.jpg', 'https://phimimg.com/upload/vod/20231230-1/258debd78bbde83e33604091ff3f5fab.jpg', '<p>Bộ phim xoay quanh biệt đội chuyên cảnh sát chuyên điều tra những vụ án gây tai nạn rồi bỏ chạy. Trong Hit and Run Squad, Gong Hye Jin sẽ hoá thân thành hình tượng cô cảnh sát nghiêm túc Eun Si Yeon, bên cạnh đó cũng không thể thiếu một anh chàng át chủ bài Seo Min Jae do Ryu Jun Yeol thủ vai. Cả hai đã cùng nhau vây bắt gã doanh nhân Jung Jae Chul (Jo Jung Suk), ngoài sở thích kiếm tiền còn đam mê đánh võng lạng lách lên lề và chạy xe với vận tốc bàn thờ.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gong Hyo-jin","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Cho Jung-seok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
