INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-the-gioi-ngam', 'Quý Ông Thế Giới Ngầm', 'The Gentlemen', 'https://phimimg.com/upload/vod/20231227-1/54494f4ef2bcff199b2d98ec8bb60ee0.jpg', 'https://phimimg.com/upload/vod/20231227-1/abf6062cd4305e15ca60d6501109a3f3.jpg', '<p>Một người tốt nghiệp Mỹ tài năng của Oxford, sử dụng các kỹ năng độc đáo của mình và Audacity, tạo ra một đế chế cần sa sử dụng bất động sản của các quý tộc Anh nghèo khó. Tuy nhiên, khi anh ta cố gắng bán đế chế của mình cho một tỷ phú đồng nghiệp của Mỹ, một chuỗi các sự kiện diễn ra, liên quan đến tống tiền, lừa dối, Mayhem và giết người giữa những tên côn đồ đường phố, càn tinh Nga, bọn xã hội đen và nhà báo máng xối.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324383);
