INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi-toi-ac', 'Bóng Tối Tội Ác', 'Dark Is The Night', 'https://phimimg.com/upload/vod/20231219-1/075f38c3caeec6cc441a7b640cc6d313.jpg', 'https://phimimg.com/upload/vod/20231219-1/2f8389702f012df83040609009a92347.jpg', '<p>Bộ phim Bóng Tối Tội Ác - Dark Is The Night là bộ phim kể xoay quanh cuộc Nguyên Phương - con gái của chủ một doanh nghiệp nổi tiếng. Mọi chuyện bắt đầu khi cô đột nhiên nhờ A Dương và Kevin giúp cô ấy tìm người chị dâu mất tích là Hiểu Hàm. Họ nhanh chóng biết rằng Hiểu Hàm có thể đã bị người anh trai bị bệnh tâm thần của Nguyên Phương là Nguyên Tuấn giết chết, và tung tích của Hiểu Hàm hiện không rõ. Sau bao chuyện xảy ra, họ phát hiện mọi chuyện không hề đơn gian và A Dương đã quyết tâm sẽ bảo vê Nguyên Phương bằng mọi cách. Liệu kẻ sát nhân thực sự là ai? Và ai đã đợi trong bóng tối để có cơ hội trả thù?</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Lý Chí Chính","avatar":""},{"name":"Trần Đình Ni","avatar":""},{"name":"Triệu Tuấn Á","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324383);
