INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-ngoan-muc', 'Cuộc Giải Cứu Ngoạn Mục', 'Abducted', 'null', 'https://phimimg.com/upload/vod/20231219-1/5c366cf5af30a2dc184401989f357e48.jpg', '<p>Bộ phim Cuộc Giải Cứu Định Mệnh – Abducted kể về câu chuyện của chàng trai Dane – một cựu chiến binh Mỹ đã về hưu và đang làm tài xế xe tải để kiếm tiền nuôi con gái. Anh vẫn chưa vượt qua được cái chết của vợ mình. Một ngày nọ, con gái của anh bị bắt cóc, còn cảnh sát vẫn chưa điều tra được gì nên anh quyết định tự mình giải quyết. Từ đó dẫn đến một cuộc chạy đua thót tim với thời gian để cứu thoát cô gái và trừng phạt bọn bắt cóc.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scout Taylor-Compton","avatar":""},{"name":"Daniel Joseph","avatar":""},{"name":"Michael Urie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
