INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-tuyet-voi-nhat-cua-chung-ta-ban-dien-anh', 'Điều Tuyệt Vời Nhất Của Chúng Ta (Bản Điện Ảnh)', 'My Best Summer', 'https://phimimg.com/upload/vod/20231219-1/b4f8331eea81dbd32ef04912b59612cc.jpg', 'https://phimimg.com/upload/vod/20231219-1/6151cfaa13356e3f2ee0bded2c957511.jpg', '<p>Geng Geng tình cờ là một cô gái bình thường trước khi cô vào trường trung học tốt nhất tỉnh. Cô ấy không thích cuộc sống của mình ở đó cho đến khi cô ấy gặp Yu Huai, bạn cùng lớp của cô ấy - tên của họ tạo thành từ Geng geng yu huai, có nghĩa là Những kỷ niệm khó quên. Họ không thích nhau ngay từ đầu, nhưng sau đó họ bắt đầu hiểu nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Arthur Chen","avatar":""},{"name":"He Landou","avatar":""},{"name":"Kara Hui","avatar":""},{"name":"Zhou Chu-chu","avatar":""},{"name":"Wang Lingyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324383);
