INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-3-tu-dia-nguc', 'Bộ 3 Từ Địa Ngục', '3 From Hell', 'https://phimimg.com/upload/vod/20231219-1/50ccb38a7e59090da77782ba7aed340e.jpg', 'https://phimimg.com/upload/vod/20231219-1/2ac15ee86184d9f4f89ef8fcd77e03cf.jpg', '<p>Otis tẩu thoát khỏi nhà tù, gặp lại Winslow và cả hai cùng nhau nghĩ ra kế hoạch đưa em gái Baby của anh ta ra ngoài. Ngay ở thời điểm đầu, The Rejects đã giết chết vô số người vô tội trên đường Mexico. Sau khi trú ngụ tại một địa điểm kín đáo được không lâu, họ bị một nhóm kẻ giết người truy sát, khởi nguồn cho cuộc chiến một mất một còn. Với đẳng cấp và kinh nghiệm của mình, liệu bộ ba có thể hạ được những tay sát thủ chuyên nghiệp kia.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sheri Moon Zombie","avatar":""},{"name":"Bill Moseley","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Jeff Daniel Phillips","avatar":""},{"name":"Dee Wallace","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
