INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-tham-truyen-2', 'Trí Thâm Truyện 2', 'Zhi Shen 2', 'https://phimimg.com/upload/vod/20231219-1/1f37d739ad7e5c6c139de29c7dfa7c08.jpg', 'https://phimimg.com/upload/vod/20231219-1/6951385a126fd0d7263d04e5b8e01edd.jpg', '<p>Để có được Lin Chong, Gao Yanei đã thiết lập một loạt kế hoạch và âm mưu. Một mặt, Wild Boar Lin muốn giết Lin Chong, và mặt khác, anh ta cố tình để Lin Niangzi tìm hiểu tin tức để khiêu khích Lu Zhishen. Lu Zhishen được Lin Chong giao phó để bảo vệ phu nhân Lin. Ví Lin Chong đang lâm vào tình trạng khó khăn nên anh Lu Zhishen phải cứu Lin Chong trước, sau đó quay lại bảo vệ Lin phu nhân. Trong quá trình hộ tống Lin Chong đến Cangzhou, Zhishen đã phải đối mặt với rất nhiều khó khăn do Gao Yanei bày ra từ trước. Tuy nhiên, đáng tiếc rằng, Zhishen đã không kịp quay lại đề cứu Lin phu nhân vì bà đã treo cổ tự tử để bảo vệ trinh tiết của mình do sự hãm hại của Gao Yanie.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Song","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324383);
