INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-tolkien', 'Nhà Văn Tolkien', 'Tolkien', 'https://phimimg.com/upload/vod/20231219-1/5a27188adb0b1bd3014f247dc0a1ad5c.jpg', 'https://phimimg.com/upload/vod/20231219-1/daa46a043e18925b509112f67ecb96ea.jpg', '<p>Anh, đầu thế kỷ 20. Nhà văn và nhà ngữ văn tương lai John Ronald Reuel Tolkien (1892-1973) và ba người bạn cùng trường của ông đã tạo ra một mối quan hệ bền chặt giữa họ khi họ có chung niềm đam mê văn học và nghệ thuật, một tình bạn thực sự sẽ bền chặt hơn khi họ lớn lên, nhưng sự bùng nổ của Chiến tranh thế giới thứ nhất đe dọa phá vỡ nó.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicholas Hoult","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Harry Gilby","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
