INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('von-lieng-con-nguoi', 'Vốn Liếng Con Người', 'Human Capital', 'https://phimimg.com/upload/vod/20231215-1/a805560f5098c2af2b001cead8339678.jpg', 'https://phimimg.com/upload/vod/20231215-1/5be2626f9fa97af4677373fd4dc87fec.jpg', '<p>Mối tình của hai cô cậu tuổi teen, một giàu và một trung lưu, dẫn đến bi kịch khi một khoản đầu tư tài chính đầy rủi ro và vụ tông xe rồi bỏ chạy hủy hoại gia đình họ.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liev Schreiber","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Maya Hawke","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Betty Gabriel","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Paul Sparks","avatar":""},{"name":"Fred Hechinger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324383);
