INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alita-thien-than-chien-binh', 'Alita: Thiên Thần Chiến Binh', 'Alita: Battle Angel', 'https://phimimg.com/upload/vod/20231215-1/1e22c6be18b0738f2bf5f629f2ab38ba.jpg', 'https://phimimg.com/upload/vod/20231215-1/da0469a562c795550ba7a233eb1dc4c9.jpg', '<p>Alita là một sáng tạo từ một thời đại tuyệt vọng. Được tìm thấy bởi Tiến sĩ Ido bí ẩn trong khi trolling cho các bộ phận Cyborg, Alita trở thành một kẻ gây chết người, nguy hiểm. Cô ấy không thể nhớ cô ấy là ai, hoặc cô ấy đến từ đâu. Nhưng với Tiến sĩ Ido, sự thật là quá rõ ràng. Cô ấy là người có thể phá vỡ chu kỳ tử vong và phá hủy khỏi tiphares. Nhưng để hoàn thành mục đích thực sự của mình, cô ấy phải chiến đấu và giết chết. Và đó là nơi có ý nghĩa thực sự của Alita đến chịu. Cô ấy là một thiên thần từ thiên đường. Cô ấy là một thiên thần của cái chết.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324383);
