INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-bao-thanh-thien-huyet-thu-co', 'Tân Bao Thanh Thiên: Huyết Thù Cổ', 'Justice Bao', 'https://phimimg.com/upload/vod/20231211-1/4e93f9cac6ec5a3aee0957dda90b3f62.jpg', 'https://phimimg.com/upload/vod/20231211-1/633059da8bb33b219c9887301f948dac.jpg', '<p>Bắc Tống và nhà Liêu xảy ra chiến tranh, trấn Bạch Vân bị quân Liêu bao vây trong ba tháng. Không có thực phẩm, người dân khó sống qua ngày. Có tin đồn rằng người dân trong thành đã bị sát hại và những cái chết kỳ lạ đã xảy ra trong doanh trại quân Liêu ở ngoài thành. Lúc này, Bao Chửng nhận lệnh đến điều tra vụ án sau khi bị giáng chức. Các bí mật dần dần được hé lộ, nhưng sự thật đằng sau đó còn kinh hoàng hơn những gì mà ông tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huỳnh Duy Đức","avatar":""},{"name":"Trần Tín Triết","avatar":""},{"name":"Trương Thiên Kỳ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324384);
