INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-cua-em-to-am-cua-anh', 'Nhà Của Em, Tổ Ấm Của Anh', 'One Year', 'https://phimimg.com/upload/vod/20231219-1/9c64834c9fcf3f58abeb640971df30c5.jpg', 'https://phimimg.com/upload/vod/20231219-1/e650bef9f3b85c9ed3354e7ca8529c9b.jpg', '<p>có nội dung xoay quanh Mook - một bà mẹ đơn thân với năm cô con gái - và Tum - một ông bố goá vợ đang sống cùng hai con. Cả hai có tình cảm với nhau và quyết định kết hôn. Tuy nhiên tình yêu của họ vấp phải trở ngại khi các con của Mook không đồng ý cuộc hôn nhân này. Vì vậy, cả hai đã thống nhất sẽ sống thử với nhau một năm. Nếu bất kỳ thành viên nào trong gia đình không hài lòng việc sống chung, thì họ sẽ phải đồng ý chia tay.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mam Kathaleeya McIntosh","avatar":""},{"name":"Duu Sanya Kunakorn","avatar":""},{"name":"Cherprang Areekul","avatar":""},{"name":"Kao Jirayu La-ongmanee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
