INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-che-giau', 'Bí Mật Che Giấu', 'Official Secrets', 'https://phimimg.com/upload/vod/20231212-1/6636e76b6ba2000dbace345e3d8d0f91.jpg', 'https://phimimg.com/upload/vod/20231212-1/63131fb07ce53361bb4a3119f777ce51.jpg', '<p>Câu chuyện có thật về người tố giác tình báo Anh Katharine Gun, người - trước cuộc xâm lược Iraq năm 2003 - đã làm rò rỉ một bản ghi nhớ tuyệt mật của NSA tiết lộ một hoạt động gián điệp bất hợp pháp chung giữa Hoa Kỳ và Vương quốc Anh chống lại các thành viên của Hội đồng Bảo an Liên Hợp Quốc. Bản ghi nhớ đề xuất tống tiền các quốc gia thành viên tham gia bỏ phiếu cho chiến tranh.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Matt Smith","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Adam Bakri","avatar":""},{"name":"Matthew Goode","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
