INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-dong-pha-bang', 'Hành Động Phá Băng', 'The Thunder', 'https://phimimg.com/upload/vod/20231219-1/fec8e6a29d3aed059e35fc1d15a502f6.jpg', 'https://phimimg.com/upload/vod/20231219-1/fd239d94ab97709ec41f1a9a41257a88.jpg', '<p>Một nhóm buôn lậu ma túy xuyên quốc gia ngoài biên giới đang thông đồng với các thành phần bất hợp pháp ở địa phương Đông Sơn để thực hiện mưu đồ sản xuất Ma túy đá dưới ngầm với quy mô lớn nhằm đạt được mục đích cung cấp số lượng lớn cho những tỉnh của đại lục Trung Quốc và hải ngoại để thu về lợi nhuận cao. Trong hoàn cảnh nguy hiểm và phức tạp này thì các cảnh sát đội phòng chống ma túy do Lý Phi làm đại diện đã không ngần ngại hy sinh tính mạng để phá tan mạng lưới buôn bán Ma túy ngầm cực lớn được bảo hộ bởi những kẻ có ô dù lớn, và từng bước phá giải thế cục, để quyết sạch trướng ngại cho sự triển khai thuận lợi của “Hành động Chuyên án ma túy Lôi Đình”.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 10, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Wang Jin Song","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Lý Mặc Chi","avatar":""},{"name":"Zhang Xi Lin","avatar":""},{"name":"Gong Lei","avatar":""},{"name":"Yang Zi Hua","avatar":""},{"name":"Tang Xu","avatar":""},{"name":"Ma Yu Jie","avatar":""},{"name":"Qian Bo","avatar":""},{"name":"Zhao Xuan","avatar":""},{"name":"Dong AI","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
