INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vitalina-varela', 'Vitalina Varela', 'Vitalina Varela', 'https://phimimg.com/upload/vod/20231211-1/455dd801cd58369076c10629e11242f7.jpg', 'https://phimimg.com/upload/vod/20231211-1/9e7803917f34e025770b02a89f7666ad.jpg', '<p>Vitalina Varela lấy danh hiệu từ tên của nữ diễn viên chính của mình, một người phụ nữ Cape Verdean, như thường lệ với các diễn viên không chuyên nghiệp của Costa, chơi một phiên bản hư cấu của chính mình. Vitalina lần đầu tiên xuất hiện trong một tập phim trong bộ phim trước đây của đạo diễn, tiền ngựa (bước sóng 2015), trong đó cô kể lại cách chồng cô đã rời khỏi quê hương gần 25 năm trước để làm việc ở Lisbon - một sự tách biệt đã trở thành vĩnh viễn khi cuối cùng cô đến lục địa , ba ngày sau đám tang của mình. Ở Vitalina Varela, Costa khúc xạ và mở rộng tập phim mà tập luyện chắc chắn trong quan điểm khắc kỷ của nữ anh hùng của mình, chiếm được sức mạnh và khả năng phục hồi phi thường của cô ấy khi cô ấy điều hướng những dấu vết vật lý ỏi của cô ấy bị bỏ lại, phát hiện ra bí mật, cuộc sống bất hợp pháp, và gặp phải Những cuộc sống khác làm tối những cái bóng của các fontainhas mà một lần là.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
