INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-ve-nha', 'Đưa Con Về Nhà', 'Bring Me Home', 'https://phimimg.com/upload/vod/20231211-1/d8c8546789f5478bad4a300b6052b4b5.jpg', 'https://phimimg.com/upload/vod/20231211-1/f638d0c7f048cce4449a4934fc294380.jpg', '<p>Đưa Con Về Nhà - Bring Me Home là tác phẩm điện ảnh ly kỳ, xoay quanh câu chuyện một bà mẹ quyết tâm tìm lại đứa con trai bị thất lạc 6 năm trước bằng mọi giá. Bộ phim dẫn dắt người xem đi từ bất ngờ này đến bất ngờ khác, người phụ nữ mất con đã được dẫn dắt đến một làng chài nơi các sĩ quan cảnh sát của Đại Hàn Dân Quốc tham gia những vụ tham nhũng có tính chất nguy hại quốc gia và chính trị tại đây. Cuộc hành trình tìm kiếm không thể nào dễ dàng, liệu một người mẹ sẽ phải hi sinh những điều lớn lao tới dường nào để mang được người con trai của cô về ? Liệu bản thân cô có được an toàn sau tất cả mọi việc?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hae Joon","avatar":""},{"name":"Lee Won Geun","avatar":""},{"name":"Yeong-ae Lee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
