INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('klaus-cau-chuyen-giang-sinh', 'Klaus - Câu Chuyện Giáng Sinh', 'Klaus', 'https://phimimg.com/upload/vod/20231211-1/0c851d7740cdce1940c0e6128673801b.jpg', 'https://phimimg.com/upload/vod/20231211-1/143e845110ef9011d0f91b376a19dba7.jpg', '<p>Viên bưu tá ích kỉ và người thợ làm đồ chơi ẩn dật bắt tay trở thành đôi bạn lạ kì, mang tới cho một thị trấn lạnh lẽo và u ám niềm vui mà nơi đó cần đến vô ngần.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Schwartzman","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Rashida Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
