INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tinh-lenh-chi-sinh-hon', 'Trần Tình Lệnh Chi Sinh Hồn', 'The Untamed: Living Dead', 'https://phimimg.com/upload/vod/20231211-1/70a0322d877d68d7292783935e8925cc.jpg', 'https://phimimg.com/upload/vod/20231211-1/8f29f88c88625fa486c85860ba3cd1c3.jpg', '<p>Là phim điện ảnh, ngoại truyện của Trần Tình Lệnh. Câu chuyện xảy ra ở Bồ Phong Thành, gần Kỳ Sơn, từng được gọi là “toà thành không bóng đêm”. Thủa xa xưa, nơi này từng là chốn phồn hoa đèn hoa rực rỡ, đêm cũng như ngày. Nhưng giờ lại bị bao trùm bởi một màu đen tối cùng truyền thuyết về việc “cứ thắp đèn là có người chết”. Ôn Ninh và Lam Tư Truy sẽ phải đối mặt với những cuộc gặp gỡ kì lạ nào đây?</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bin","avatar":""},{"name":"Paul Yu Pin","avatar":""},{"name":"Zheng Fan Xing","avatar":""},{"name":"Vương Nhất Phi","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"He Longlong","avatar":""},{"name":"Li Xiang Yang","avatar":""},{"name":"Guo Jianwei","avatar":""},{"name":"Luo Ning","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324384);
