INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-viec-deu-on', 'Mọi Việc Đều Ổn', 'All Is Well', 'https://phimimg.com/upload/vod/20231211-1/a2f9d734b4d9ad4be09af6213ec4080a.jpg', 'https://phimimg.com/upload/vod/20231211-1/0f1880d14c25f48375e2cdec9594ce6a.jpg', '<p>Một người phụ nữ bị người em vợ của ông chủ mới tấn công tình dục gắng gượng tiếp tục như chưa hề có gì xảy ra, nhưng đêm đó vẫn đè nặng lên tâm trí và cơ thể cô.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Aenne Schwarz","avatar":""},{"name":"Andreas Döhler","avatar":""},{"name":"Hans Löw","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324384);
