INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-nhi', 'Đội Điều Tra Nhí', 'TKKG', 'https://phimimg.com/upload/vod/20240103-1/1b5050bc731b9081adee439efe7c1097.jpg', 'https://phimimg.com/upload/vod/20240103-1/b6621325e36f475230018b8a4b3373df.jpg', '<p>Khi cha của Willi bị bắt cóc và chỉ được trả tự do cho một bức tượng có giá trị trong bộ sưu tập nghệ thuật của ông, Tim là người duy nhất tin tưởng rằng cảnh sát đã đi sai đường. Cùng với con gái của cảnh sát thông minh Gaby và người ngoài cuộc vô cùng thông minh Karl, họ bắt đầu tự mình điều tra. Chống lại tất cả các tỷ lệ cược cả bốn phát hiện ra một âm mưu. Trong chuyến phiêu lưu thám tử lớn đầu tiên, họ cùng nhau phát triển thành một cộng đồng gắn bó, và vì vậy Tim, Klöschen, Karl và Gaby trở thành ban nhạc TKKG.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma-Louise Schimpf","avatar":""},{"name":"Ilyes Moutaoukkil","avatar":""},{"name":"Lorenzo Germeno","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
