INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-va-dau', 'Máu Và Dầu', 'Blood And Oil', 'null', 'https://phimimg.com/upload/vod/20240103-1/9713e40bc579a4f8e617e910dfcfa5bf.jpg', '<p>Bộ phim Máu Và Dầu - Blood And Oil kể về câu chuyện khi dầu thương mại được phát hiện ở ngôi làng nhỏ Oloibiri, Nigeria, ngôi làng đã trở nên thịnh vượng cũng như có nhiều việc làm hơn. Hai thập kỷ sau khi những giọt dầu cuối cùng được khai thác và các công ty dầu mỏ của Mỹ bỏ rơi họ, tất cả những gì còn lại của ngôi làng chỉ là nguồn nước ô nhiễm, những đứa trẻ ốm yếu và nền kinh tế rơi vào khủng hoảng. Khi một tập đoàn đa quốc gia mới một lần nữa muốn đầu tư vào việc khai thác dầu mỏ, cơn thịnh nộ của dân làng gia tăng và các chiến binh Nigeria, dẫn đầu là Gunpowder, đã tìm cách trả thù những người nước ngoài tham lam bằng cách bắt cóc Powell, Giám đốc điều hành của công ty. Những gia đình trong làng trở nên chia rẽ khi già làng Timpriye phải đấu tranh để cứu lấy cuộc sống của người đàn ông đại diện cho tất cả những tệ nạn mà dầu mỏ đã mang đến cho ngôi làng của ông nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Mofe-Damijo","avatar":""},{"name":"William R. Moses","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
