INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuan-thien-phu-ky-an-vu-an-quoc-tu-giam', 'Thuận Thiên Phủ Kỳ Án - Vụ Án Quốc Tử Giám', 'The Imperial College Mystery Case Of Shuntian', 'null', 'https://phimimg.com/upload/vod/20231211-1/c58e422288f3a6b40ffbb0185353ed7a.jpg', '<p>Thuận Thiên Phủ Kỳ Án Vụ Án Quốc Tử Giám - The Imperial College Mystery Case Of Shuntian xoay quanh triều đại Càn Long của nhà Thanh, đã xảy ra một vụ án mất tích của Giám thị Học viện Hoàng đế, thần đồng 14 tuổi Mã Tuấn mất tích một cách bí ẩn trong quá trình khám nghiệm ngôi nhà. Dinh thự Shuntian Yin Wang Chenglin phải chịu trách nhiệm Để điều tra tung tích của Mã Tuấn Trong quá trình điều tra Vương Chính Lâm, giám thị coi thi cùng với Mã Tuấn Nhưng việc vô tình giết người khiến vụ án càng thêm rối rắm.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Gexiao Xi","avatar":""},{"name":"Jiachen","avatar":""},{"name":"Meng Zhichao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
