INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-foster-dang-sau-nhung-ban-hit', 'David Foster: Đằng Sau Những Bản Hit', 'David Foster: Off The Record', 'https://phimimg.com/upload/vod/20231211-1/9cf5f5d23ca895a21e744fd8efcfa738.jpg', 'https://phimimg.com/upload/vod/20231211-1/2f6b20caea0e357ec46c9394970763fd.jpg', '<p>Từ thần đồng nhí thành nhà sản xuất âm nhạc lừng danh, David Foster chia sẻ câu chuyện thành công qua các thước phim hiếm có và cuộc phỏng vấn với các cộng sự của ông.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"David Foster","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324384);
