INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mayday-life', 'Mayday Life', 'Mayday Life', 'https://phimimg.com/upload/vod/20231210-1/1350b1cc0245a42dbaa9358896d1f2f4.jpg', 'https://phimimg.com/upload/vod/20231210-1/4e692906d43760c9457434659e90992b.jpg', '<p>Chuyến lưu diễn Life của Ngũ Nguyệt Thiên mở ra khi năm siêu anh hùng lỗi thời được triệu tập để cứu thế giới khỏi một kẻ thù ngoài hành tinh căm ghét âm thanh.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mayday","avatar":""},{"name":"Hoàng Bột","avatar":""},{"name":"Lương Gia Huy","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324384);
