INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mayday-life', 'Mayday Life', 'Mayday Life', 'mayday life mayday life mayday hoàng bột lương gia huy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-tuong-mac-ta', 'Can Tương Mạc Tà', 'Spirit Of Two Swords', 'https://phimimg.com/upload/vod/20231210-1/bf32cfdec0c5cddbae7ccd25ad8cb6b3.jpg', 'https://phimimg.com/upload/vod/20231210-1/b431354c4015bd86007a3fb39656bcab.jpg', '<p>Cuối thời Xuân Thu, năm sứ quân tranh giành quyền bá chủ, nhân dân lâm vào cảnh khốn cùng. Vua nước Ngô tàn ác đến mức không chần chừ một giây để giết người để sở hữu kiếm thần. Sư phụ Ou Yezi từ chối giúp đỡ vị vua độc ác và buộc lòng cải trang thành người nhà luyện võ thông thường. Các đệ tử của ông là Qingyun, Ganjiang và Moye, là những người có trái tim mềm mại và nhân hậu. Thật không may, đệ tử Ganjiang đã thất bại trong việc ám sát nhà vua và Qingyun đã dùng máu của mình để đúc kiếm. Để cứu người dân, Ganjiang và Moye đã lấy lại sức mạnh và chung tay diệt trừ cái ác, bảo vệ thế giới bằng cách hy sinh bản thân.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiro Wang","avatar":""},{"name":"Lia Qi Zhi","avatar":""},{"name":"Mi Lu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
