INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hoan-tai-paradise', 'Hỏa Hoạn Tại Paradise', 'Fire In Paradise', 'https://phimimg.com/upload/vod/20231210-1/861b294aa49bab02e0eba6913274b0af.jpg', 'https://phimimg.com/upload/vod/20231210-1/71b56c5a8337f847d3cc30ecdc242fed.jpg', '<p>Trong phim tài liệu này, những người sống sót kể lại trận Camp Fire 2018 đã tàn phá thị trấn Paradise, trở thành trận cháy rừng kinh hoàng nhất trong lịch sử California.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324384);
