INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-tien-ao', 'Cuộc Chiến Tiền Ảo', 'Crypto', 'https://phimimg.com/upload/vod/20231211-1/4d6c011035223e5319f770e1b53e80ff.jpg', 'https://phimimg.com/upload/vod/20231211-1/b2a48bdba8ed0539ec611ff67084cfac.jpg', '<p>Phim có tựa đề việt là Cuộc Chiến Tiền Ảo, thuộc thể loại tội phạm hình sự, được khởi động từ lúc đồng tiền bitcoin đang còn rất hot và tăng giá chóng mặt, đây có lẽ chính là nguồn cảm hứng cho John. Ngoài ra, phim còn có sự tham gia của dàn diễn viên tương đối chất lượng với một số gương mặt đáng chú ý như: Beau Knapp, Alexis Bledel, Luke Hemsworth, Kurt Russell, Jeremie Harris, Jill Hennessy, Vincent Kartheiser,… Nội dung phim xoay quanh nhân vật Caleb, một nhân viên ngân hàng trẻ đang làm việc tại Phố Wall. Sau khi bị giáng chức trở về quê nhà, anh bắt đầu tìm hiểu nhiều hơn về đồng tiền ảo và vô tình bị lôi kéo vào điều tra một mạng lưới rối rắm về tham nhũng và lừa đảo ở Upstate New York. Từ đây, cuộc sống của anh thay đổi chóng mặt, nó vừa có ảnh hưởng tích cực nhưng khiến anh rơi vào sự rối loạn cả về tâm lý lẫn công việc.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Beau Knapp","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Luke Hemsworth","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324384);
