INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-chuyen-2-linh-vuc-song-song', 'Đường Chuyên 2: Linh Vực Song Song', 'Tang Zhuan Xia Zhi Ling Yu Shuang Sheng', 'https://phimimg.com/upload/vod/20231211-1/41db828dfe042ace396906bc63fe7579.jpg', 'https://phimimg.com/upload/vod/20231211-1/8006639d7e64771a18ed9b0e21efc5f6.jpg', '<p>Đường Chuyên 2: Linh Vực Song Song - Tang Zhuan Xia Zhi Ling Yu Shuang Sheng (2019) :những năm Trinh Quán nhà Đường, Hoàng đế Tô Đặc đến Đại Đường tìm cao nhân Vân Diệp. Vì cục diện trong nước hỗn loạn, Mạc Lâm phát sát thủ và Thiên Ma Cơ đến thích sát. Sau khi biết thân phận của hoàng đế, Vân Diệp và Địch Nhân Kiệt, Tiểu Võ tìm cao nhân Khổng Tước Cốc cầu giúp. Thiên Ma Cơ và Hắc Xỉ Thường lần nữa đến phá hoại, trận ác chiến kinh thiên động địa nổ ra.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cường Vũ","avatar":""},{"name":"Dương Tử Thanh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324384);
