INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-nam-ngoai', 'Mùa Hè Năm Ngoái', 'The Last Summer', 'https://phimimg.com/upload/vod/20231211-1/91ab06b002ef85645c9aec503b3b980d.jpg', 'https://phimimg.com/upload/vod/20231211-1/87184f191f3baeda4d79fb68f5cafe6f.jpg', '<p>Với một số câu chuyện giao nhau, mùa hè cuối cùng sau một nhóm sinh viên tốt nghiệp trung học gần đây khi họ điều hướng theo cách của họ thông qua mùa hè cuối cùng của họ trước khi cất cánh học đại học. Khi thanh niên vật lộn với tình yêu bị mất và tìm thấy, hình thành tình bạn trong những trường hợp bất ngờ, và kiểm soát nhiều hơn trong các mối quan hệ của họ với cha mẹ, cuối cùng họ quyết định họ sẽ là ai và họ sẽ làm gì khi họ đứng trên ranh giới của tuổi trưởng thành.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324384);
