INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-macaron', 'Thiếu Nữ Macaron', 'Cheat My Boss', 'https://phimimg.com/upload/vod/20231208-1/50f969134d087791bce94817aa642580.jpg', 'https://phimimg.com/upload/vod/20231208-1/90f0e7f2757458ef35f0d1d5f3d768ab.jpg', '<p>Kể về thiếu nữ Giang Sở Sở vừa tốt nghiệp đại học, lưu lại thành phố với mục tiêu trở thành hot girl. Lúc sự nghiệp gặp khó khăn thì ngẫu nhiên gặp được tổng giám đốc xí nghiệp truyền thông là Lạc Thiên Nhất. Lại bởi vì thân phận là hot girl, hai người triển khai một câu chuyện “phim giả tình thật” ngọt ngào.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Dụ Mễ","avatar":""},{"name":"Lữ Dũng Trác","avatar":""},{"name":"Bồ Đào","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
