INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-khi-em-den', 'Từ Khi Em Đến', 'Then Came You', 'https://phimimg.com/upload/vod/20231211-1/d851e6e59cdf61490f1bcfbc4d7d4d8c.jpg', 'https://phimimg.com/upload/vod/20231211-1/5fdfa38536aa7c3d1afd9373b7b87238.jpg', '<p>Một kẻ đạo đức giả làm công việc xử lý hành lý ở sân bay buộc phải đối mặt với nỗi sợ hãi khi một thiếu niên người Anh mắc bệnh nan y nhờ anh giúp cô thực hiện danh sách việc cần làm lập dị của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Asa Butterfield","avatar":""},{"name":"Maisie Williams","avatar":""},{"name":"Nina Dobrev","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
