INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-que-ra-pho-nguoi-ban-ngoai-hanh-tinh', 'Cừu Quê Ra Phố: Người Bạn Ngoài Hành Tinh', 'A Shaun The Sheep Movie: Farmageddon', 'https://phimimg.com/upload/vod/20231211-1/df3e4b1fd72dacb849f222b87bd654f3.jpg', 'https://phimimg.com/upload/vod/20231211-1/18b41b1da6a8a83598c32b02f4927eb5.jpg', '<p>Có một cái gì đó kỳ lạ đang diễn ra trong thị trấn Mossingham yên bình, ngay sau nhiệm vụ giải cứu tuyệt vời ở Shaun the Sheep Movie (2015). Là những đơn đặt hàng Shaun tinh nghịch trong pizza cho đàn chiên dưới mũi của nông dân và Bitzer, con chó chăn cừu mãi mãi, một UFO bí ẩn, di chuyển nhanh chóng bước vào bầu không khí của Trái đất và những vùng đất sụp đổ gần trang trại dưới cùng Verdant Rausy. Bây giờ, Lu-La, sinh vật thân thiện phi thường từ sâu thẳm thiên hà, đang gặp nguy hiểm nghiêm trọng, xa nhà. Shaun có thể, và phần còn lại của những con cừu, cho mượn một bàn tay giúp đỡ và bảo vệ người bạn đồng hành ngoài trái đất mới của họ khỏi sự phát hiện của Bộ hành tinh, và nhà lãnh đạo không thể ngăn cản, đại lý đỏ?</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324384);
