INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-doc-quyen', 'Ký Ức Độc Quyền', 'Somewhere Only We Know', 'https://phimimg.com/upload/vod/20231208-1/064eb9a09885bef8ba6c0b5c05dc32df.jpg', 'https://phimimg.com/upload/vod/20231208-1/4d0994f7a97f59452a7a69aa04dc25b7.jpg', '<p>Nghiên cứu sinh tiến sĩ khoa Vật Lý đại học Đông Hồ Mộ Thừa Hoà trong một lần làm giám khảo đột xuất coi thi cuối kỳ, anh đã hiểu nhầm sinh viên năm ba khoa tiếng Anh Tiết Đồng gian lận trong thi cử. Từ đó hai người kết nên “mối duyên không thể giải”. Trong quá trình qua lại, Mộ Thừa Hoà và Tiết Đồng dần dần có tình cảm và trở thành một câu chuyện hai bên yêu thầm lãng mạn. Và trong những năm tháng đại học, Tiết Đồng gặp được ba người bạn cùng phòng: Triệu Hiểu Đường xinh đẹp lạnh lùng, Bạch Lâm hoạt bát nhiệt tình, Tống Kỳ Kỳ hiền lành ngoan ngoãn. Bốn cô gái với tính cách khác nhau trong quá trình làm bạn cũng đã được trải nghiệm những mối tình khác nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Juck Zhang","avatar":""},{"name":"Li Ting Ting","avatar":""},{"name":"Chen Bo Hao","avatar":""},{"name":"Sun Jia Ling","avatar":""},{"name":"Li Jiu Xiao","avatar":""},{"name":"Zhang Zhang","avatar":""},{"name":"Deng Yu Li","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Fang Wen Qiang","avatar":""},{"name":"Nate","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324384);
