INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ve-nha-cua-cun-con', 'Đường Về Nhà Của Cún Con', 'A Dog''s Way Home', 'https://phimimg.com/upload/vod/20231209-1/8cc80f8cfecb37e4fb19bbfd3b6dd963.jpg', 'https://phimimg.com/upload/vod/20231209-1/dd099c6ad0ba39aaf6ca2894e323c4f2.jpg', '<p>Cô cún Bella thực hiện cuộc phiêu lưu tìm về ngôi nhà thân quen, nơi cô lớn lên cùng cậu chủ đẹp trai của mình tại một nơi cách đó tận 600 ki-lô-mét. Trên cuộc hành trình của mình, Bella gặp rất nhiều người bạn mới và trải qua nhiều thử thách thú vị. Phim chuyển thể từ tiểu thuyết cùng tên nằm trong bộ ba loạt tiểu thuyết nổi tiếng lấy chủ đề về các chú chó.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Judd","avatar":""},{"name":"Jonah Hauer‑King","avatar":""},{"name":"Bryce Dallas Howard","avatar":""},{"name":"Alexandra Shipp","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
