INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-sang-mua-dong', 'Trăng Sáng Mùa Đông', 'Moonlit Winter', 'https://phimimg.com/upload/vod/20231209-1/a15439cc0c1d7d3cea2dcdcb51a348a0.jpg', 'https://phimimg.com/upload/vod/20231209-1/14d5db69546a3da14bcbc4895f7ac608.jpg', '<p>Yoon-hee sống với cô con gái tuổi teen SAE-BOM. Vào một ngày mùa đông, Yoon-hee nhận được một lá thư từ Otaru, Nhật Bản. Sae-Bom vô tình đọc bức thư và học hỏi về tình yêu đầu tiên của mẹ cô, mà cô không bao giờ nói về trước đây.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
