INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-so-phan', 'Hoán Đổi Số Phận', 'Left-Handed Wife', 'https://phimimg.com/upload/vod/20231207-1/127b7863387bea732125afe209062c88.jpg', 'https://phimimg.com/upload/vod/20231207-1/307452e438fa539b358b8b4404a306cf.jpg', '<p>Hoán Đổi Số Phận (Left-Handed Wife) kể về Lee Soo Ho (Kim Jin Woo) và Oh San Ha (Lee Soo Kyung) là một cặp đôi ngọt ngào và yêu nhau sâu đậm. Sau khi tổ chức đám cưới, cả hai cùng đi hưởng tuần trăng mật. Không may trong chuyến đi này Lee Soo Ho đã gặp tai nạn, mất tích và lâm vào tình trạng mất trí nhớ. Oh San Ha sau khi biết chuyện đã tìm mọi cách để tìm kiếm chồng mình mà không ngờ bản thân đang dần chạm đến những bí mật đen tối không tưởng.</p>', 'Hoàn Tất (103/103)', 103, 'series', 'completed', 19, 2019, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Yeon-Joo","avatar":""},{"name":"Jin Tae Hyun","avatar":""},{"name":"Kim Jin Woo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
