INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-nguoi-da-thu', 'Mặt Người Dạ Thú', 'Instinct', 'https://phimimg.com/upload/vod/20231207-1/9a730bd2255b83edc22a269666ee985f.jpg', 'https://phimimg.com/upload/vod/20231207-1/535b8de60de7e325fc2cc359cff3e2bf.jpg', '<p>kể về câu chuyện đen tối của Prao - một nữ sinh trung học - là thành viên băng nhóm đeo mặt nạ động vật chuyên săn lùng tội phạm. Một ngày nọ, cô trở thành nạn nhân của một cuộc thử nghiệm tàn độc và từ từ biến mình thành một con vật. Cô quyết định sử dụng khả năng của mình để điều tra chân tướng vụ việc và chữa lành cho bản thân trước khi biến hình thành một con vật thực sự.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pat Chayanit Chansangavej","avatar":""},{"name":"Ben Benjamin Varney","avatar":""},{"name":"Jack Kittisak Patomburana","avatar":""},{"name":"Tia Tavee","avatar":""},{"name":"Pae Daweerit Chullasapya","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
