INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-gioi-xanh', 'Biên Giới Xanh', 'Green Frontier', 'https://phimimg.com/upload/vod/20231207-1/84131107ecb3f80ebc407fec091a71af.jpg', 'https://phimimg.com/upload/vod/20231207-1/f5c98c3fa8f7c69db1bb627b39d65615.jpg', '<p>Khi một nữ thám tử trẻ tuổi ở Bogotá bị lôi kéo vào rừng để điều tra bốn vụ sát hại phụ nữ, cô phát hiện ra ma thuật, âm mưu độc ác và nguồn gốc thực sự của chính mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Juana del Río","avatar":""},{"name":"Ángela Cano","avatar":""},{"name":"Miguel Dionisio Ramos","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
