INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-minh-phong-hoa', 'Đại Minh Phong Hoa', 'Empress Of The Ming Legend Of Sun Ruowei', 'https://phimimg.com/upload/vod/20231207-1/4f3f4a34fa8b2fa0250e54563fd03377.jpg', 'https://phimimg.com/upload/vod/20231207-1/056e29be9f781bcb496e4b7cf29660e0.jpg', '<p>Năm đầu triều Minh Vĩnh Lạc, phu phụ Ngự Sử Đại Phu Cảnh Thanh bị Thành Tổ Chu Đệ tàn sát cả tộc. Trưởng nữ Man Thù được Tôn Trung cứu đi, được nuôi nấng dưới cái tên Tôn Nhược Vi. Nhiều năm sau, thế lực ngầm “Thanh Chính giáo” chi phối Tôn Nhược Vi, âm mưu gả cho Hán vương dã tâm bừng bừng. Thế nhưng, vì cơ duyên mà cô lại bị gả vào Đông cung, trở thành phi tần của hoàng thái tôn Chu Chiêm Cơ từng ngẫu nhiên quen biết. Sau khi vào cung, Tôn Nhược Vi ôm mối thù giết cha, mối hận tàn sát cả tộc lại hiểu được nỗi thống khổ của bách tính trong thiên hạ. Nàng nhìn thấy những tranh đấu âm hiểm chốn cung đình, dần dần trở nên trưởng thành hơn cũng bắt đầu động lòng với Chu Chiêm Cơ tâm địa thiện lương. Cuối cùng, Tôn Nhược Vi từ bỏ lòng thù hận, phò tá Chu Chiêm Cơ bước lên ngôi vị hoàng đế, vì hạnh phúc và an bình của người trong thiên hạ. Sau khi Chu Chiêm Cơ đột ngột qua đời, Tôn Nhược Vi lại lần lượt trải qua hai đời hoàng đế là Chu Kỳ Trấn và Chu Kỳ Ngọc. Nàng dùng chính sự thông tuệ và khí phách của mình giải cứu vương triều Đại Minh vượt qua vô số sóng gió nguy nan dùng nhân đức thu phục thiên hạ</p>', 'Hoàn Tất (62/62)', 62, 'series', 'completed', 16, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Á Văn","avatar":""},{"name":"Đặng Gia Giai","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
