INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-phong-giang-ma-ky', 'Khai Phong Giáng Ma Ký', 'Exorcist Judge Bao', 'https://phimimg.com/upload/vod/20231209-1/ae00044bd49cbc851eedc5673c3354b0.jpg', 'https://phimimg.com/upload/vod/20231209-1/b3233125febc2ec132ac95a32599426c.jpg', '<p>Thái tử nửa đêm bị hạ, nghi là do Miêu Yêu tác quái, tin đồn lan ra, lòng người bàng hoàng. Bao đại nhân được lệnh cùng với phục yêu sư Khôi Phủ Quân và cấm quân Kiều Cơ, phá tan vụ án Yêu Miêu, và giải nghi án sáu năm trước “li miêu hoán thái tử”.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Benny Chan","avatar":""},{"name":"He Qi Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
