INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hensuki-ban-co-san-sang-yeu-mot-ke-bien-thai-mien-co-ay-la-mot-nguoi-de-thuong', 'Hensuki: Bạn Có Sẵn Sàng Yêu Một Kẻ Biến Thái, Miễn Cô Ấy Là Một Người Dễ Thương?', 'Hensuki: Are you willing to fall in love with a pervert, as long as she''s a cutie?', 'https://phimimg.com/upload/vod/20231207-1/f8405309db00543ef782f3c4618bb996.jpg', 'https://phimimg.com/upload/vod/20231207-1/b526877172221fb954c9dd0a6cea798e.jpg', '<p>Bộ phim hài lãng mạn bắt đầu khi một bức thư tình được gửi đến cho Keiki Kiryuu, một học sinh trung học bình thường chưa từng có bạn gái bao lâu còn sống. Bức thư không bao gồm tên người gửi - nhưng bức thư có cả quần lót màu trắng. Trong quá trình điều tra xem ai có thể là Cô bé Lọ Lem đã bỏ lại quần lót của mình, Keiki phát hiện ra mọi ứng viên đều biến thái và cực kỳ muốn anh ta tham gia vào trò đồi bại của họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324384);
