INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-toi', 'Thú Tội', 'Confession', 'https://phimimg.com/upload/vod/20231207-1/3093c3230a8e24c4d86929a21b750521.jpg', 'https://phimimg.com/upload/vod/20231207-1/cd7d4084c06fdb09c571f0c68c936a1b.jpg', '<p>Thú Tội - Confession là phim Hàn Quốc xoay quanh câu chuyện về Choi Do-Hyun một chàng trai mắc bệnh tim, đã dành phần lớn thời thơ ấu của mình ở trong bệnh viện. Anh ấy đã có một cơ hội để ghép tim. Ngay sau ca phẫu thuật ghép tim thành công, cha anh bị buộc tội giết người và phải nhận án tử hình. Choi Do-Hyun đã trở luật sư, để điều tra lại vụ án của cha mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 22, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Kwang- il","avatar":""},{"name":"Lee Jun-ho","avatar":""},{"name":"Nam Gi-ae","avatar":""},{"name":"Shin Hyun-bin","avatar":""},{"name":"Yoo Jae- myung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
