INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-ha-nam-ay-co-gio-thoi-qua', 'Mùa Hạ Năm Ấy Có Gió Thổi Qua', 'Wind Blew That Summer', 'https://phimimg.com/upload/vod/20231207-1/c2a81a09201afb1957b3188ebdd19880.jpg', 'https://phimimg.com/upload/vod/20231207-1/2a4920a4a9f1da0db3e5ca7b43de8104.jpg', '<p>Bộ phim xoay quanh cô bạn Bạch Nhất Hàm trong sáng, ngốc ngếch. Tuổi thanh xuân học trò của cô vốn bình lặng trôi qua nhưng lại thay đổi hoàn toàn vì sự xuất hiện của cậu bạn Lâm Tinh Cách.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Ngọc","avatar":""},{"name":"Thái Nghiêu","avatar":""},{"name":"Lãnh Tâm Thanh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
