INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-2019', 'Câu Chuyện Tình Yêu', 'The Love Story in Banana Orchard', 'https://phimimg.com/upload/vod/20231207-1/5f1131c70ec48bb8aea8f1274ab8017a.jpg', 'https://phimimg.com/upload/vod/20231207-1/5bc3440a36bc5a54d01a0ef957009551.jpg', '<p>Câu Chuyện Tình Yêu - The Love Story in Banana Orchard kể về Cao Chí Hồng - con trưởng của trang trại chuối, anh yêu đại tiểu thư con nhà giàu sau một sự hiểu lầm. Tuy nhiên, sau một tai nạn, nhị tiểu thư bí mật nảy sinh tình cảm với Cao Chính Hồng. Đồng thời, chính Cao Hồng cũng có tình cảm với đại tiểu thư. Khi tình cảm bị xáo trộn và sự thay đổi tàn nhẫn của số phận ập đến, mỗi người sẽ chọn cho mình con đường hạnh phúc nào đây?</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 19, 2019, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Tử Nghi","avatar":""},{"name":"Trần Khiêm Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324384);
