INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-o-thi-tran-hung-nhan', 'Yêu Ở Thị Trấn Hùng Nhân', 'Welcome To The Beartown', 'https://phimimg.com/upload/vod/20231208-1/c30806985b2d9be7fe6a3f95916cf4db.jpg', 'https://phimimg.com/upload/vod/20231208-1/5ed8d14d73dd4f8d0916e653fcd77676.jpg', '<p>Giới thiệu vắn tắt: Hà Tất và Mông Tiểu Tiên cùng làm tại bộ phận ATM của 1 ngân hàng, do công ty cấm yêu đương công sở, nên phải yêu ngấm ngầm. Trong lúc đó, tại thị trấn Hùng Nhân cách đó 300km, 1 cây ATM rút tiền xuất hiện sự cố, rút 1 ATM trả gấp đôi. Mông Tiểu Tiên và Hà Tất đánh cược, ai tìm được người rút tiền nhận tiền trả nhầm trước sẽ được ở lại làm việc tại ngân hàng. Thế là 1 cuộc chiến giữa kiếm tiền và tình yêu đã diễn ra tại thị trấn nhỏ này</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Á Văn","avatar":""},{"name":"Trương Dung Dung","avatar":""},{"name":"Wang Liang","avatar":""},{"name":"Xiao Fan","avatar":""},{"name":"Lu Ye","avatar":""},{"name":"Han Yan Bo","avatar":""},{"name":"Wang Xu Feng","avatar":""},{"name":"Dobrgyal","avatar":""},{"name":"Liu Shi Liu","avatar":""},{"name":"Qie Lu Tong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324384);
