INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-quy-dai-nao', 'Vu Quy Đại Náo', 'Singles Make Couples', 'https://phimimg.com/upload/vod/20231207-1/4f341dec445ad0a1600e6bb012619ec6.jpg', 'https://phimimg.com/upload/vod/20231220-1/d7b2ca0fc4e3adc63f2b59c001dab62a.jpg', '<p>Gây ấn tượng với mô tả văn hóa cưới xin ở các tỉnh miền Tây, Vu Quy Đại Náo kể về ba người bạn thân chạy trốn áp lực hôn nhân từ người nhà. Họ quyết định tự kiếm tiền bằng cách tổ chức tiệc cưới thuê.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Ngọc Trinh","avatar":""},{"name":"Diệu Nhi","avatar":""},{"name":"Việt Hương","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324384);
