INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-hen-mua-thu', 'Ước Hẹn Mùa Thu', 'Autumn Promise', 'https://phimimg.com/upload/vod/20231210-1/4e936f706c99ce6083c715ff9ca05abf.jpg', 'https://phimimg.com/upload/vod/20231210-1/3469a9cd6312aadc0e5d6489f16dd7e8.jpg', '<p>Thanh xuân thời niên thiếu của bạn là gì? Có phải là một ai đó để nhớ, để tiếc nuối mỗi khi nghĩ về? Pha Lê (Hoàng Oanh) và Duy (Trần Quốc Anh) của “Ước Hẹn Mùa Thu” cũng từng có một thanh xuân như thế…
 Ước Hẹn Mùa Thu là hành trình đi tìm lại mối tình đầu sau 15 năm hôn mê của chàng trai tên Duy mà trong đó 3 yếu tố: tình yêu, tình bạn &amp; tình địch đan xen lẫn nhau tạo nên những màu sắc rất đặc biệt. Và đó cũng chính là lời ước hẹn của tuổi trẻ mà họ - những chàng trai, cô gái đã kịp tìm lại được trước khi để những lo toan bộn bề của cuộc sống cuốn trôi đi...</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Yoon Trần","avatar":""},{"name":"Hoàng Oanh","avatar":""},{"name":"Nhan Phúc Vinh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324384);
