INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-kim-thang', 'Bắc Kim Thang', 'Home Sweet Home', 'https://phimimg.com/upload/vod/20231210-1/ed8c8a54a2f1bb194ff66f88aa58425a.jpg', 'https://phimimg.com/upload/vod/20231210-1/b23149c89a59a604476b0293f79ed5d8.jpg', '<p>Lấy bối cảnh miền Tây những năm 1990, chuyện phim Bắc Kim Thang bắt đầu khi Thiện Tâm (Trịnh Tài) – cậu con trai trưởng của một gia đình giàu có – trở về nhà sau 6 tháng hôn mê vì tai nạn trên Sài Gòn. Anh bắt đầu nhận ra sự khác lạ trong nhà khi ông nội lâm bệnh nặng, còn cô em họ Hai Lầm (Minh Hy) thì bị đuổi đi vì chửa hoang.Trong khi đó, cha (Duy Phương) và mẹ (Bích Hằng), cũng như chú Út (Hữu Tiến), lại không hề quan tâm đến tung tích Hai Lầm. Họ chỉ nhất mực lo hối thúc con trai lấy giấy tờ nhà đất của ông nội. Không những thế, Thiện Tâm liên tục nhìn thấy nhiều hình ảnh kinh dị về cô em gái. &nbsp;Anh quyết điều tra về tung tích của Hai Lầm, và những bí mật đen tối về nơi được gọi là tổ ấm bắt đầu dần hé lộ.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Trịnh Tài","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Duy Phương","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324384);
