INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-son-tam-linh', 'Thất Sơn Tâm Linh', 'Kumanthong', 'https://phimimg.com/upload/vod/20231210-1/6aac7bb1c8bcf1fc37a112fcae3b4fbe.jpg', 'https://phimimg.com/upload/vod/20231210-1/b23f39307be4d74380bd2090dbe8ae3d.jpg', '<p>Thất Sơn Tâm Linh là câu chuyện kể về gã thầy thuốc sát nhân tên Huỳnh. Với tướng mạo hiền từ, cách nói chuyện nhẹ nhàng, từ tốn, thường xuyên chữa bệnh mà không lấy tiền, hắn tạo được lòng tin của rất nhiều người dân ở nơi hắn đến. Hắn ta luôn gieo rắc vào đầu người khác về những bài thuốc bí truyền, những cách chữa bệnh kỳ lạ mang đậm màu sắc kì dị…Nhưng đằng sau đó là một âm mưu khủng khiếp!</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Quang Tuấn","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Đinh Y Nhung","avatar":""},{"name":"Thanh Tú","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"La Thành","avatar":""},{"name":"Lê Thiện","avatar":""},{"name":"Phan Tấn Thi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
