INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-cu-bien-mat', 'Chứng Cứ Biến Mất', 'The Void Evidence', 'null', 'https://phimimg.com/upload/vod/20231208-1/96eb136ac0f69ffca7ff16a291d77cf4.jpg', '<p>Ở thành phố miền núi, diễn ra một vụ giết người hàng loạt làm cả thành phố hoảng loạn.Nhóm điều tra nhận được một e-mail nặc danh với video trực tiếp về một vụ giết người. Zhao Meng, Ye Qianying và những người khác ngay lập tức mở một cuộc điều tra. Dưới sự giúp đỡ của Ye Qianying, Wang Zhengyi, một sĩ quan huyền thoại của Đội điều tra, bí mật giải quyết vụ án. Tên tội phạm để lại manh mối khác nhau trong mỗi vụ giết người, khiến cuộc điều tra trở nên phức tạp hơn. Khi Đội điều tra tiếp tục điều tra về vụ án, họ phải đối mặt với nhiều áp lực và chịu tổn thất lớn. Dưới nỗ lực tuyệt vời, Nhóm điều tra cuối cùng cũng tìm ra manh mối và tiết lộ một thảm đã diễn ra trong suốt thời gian qua.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Junpeng","avatar":""},{"name":"Xu Zhinuo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
