INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ca-mot-chuyen-di', 'Hơn Cả Một Chuyến Đi', 'Come As You Are', 'https://phimimg.com/upload/vod/20231219-1/f2c5243d0647ffb2a9b2f9f717d65b4c.jpg', 'https://phimimg.com/upload/vod/20231219-1/3014f77aa1b77201f053a54cf862c439.jpg', '<p>Hơn Cả Một Chuyến Đi - Come As You Are lấy cảm hứng từ một câu chuyện có thật - kể về ba thanh niên khuyết tật chạy trốn thực tại để tới một nhà thổ chuyên cung cấp dịch vụ đặc biệt ở Montreal với một tài xế xe cấp cứu hết đam mê. Họ tìm kiếm trải nghiệm tình dục mà trước đây chưa từng được trải qua khi ngồi trên xe lăn và suy giảm thị lực.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Grant Rosenmeyer","avatar":""},{"name":"Hayden Szeto","avatar":""},{"name":"Ravi Patel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
