INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-lam-vay-cuoi', 'Cô Nàng Làm Váy Cưới', 'Made For You With Love', 'https://phimimg.com/upload/vod/20231219-1/c7300b54c384504fb207a347bacd58c0.jpg', 'https://phimimg.com/upload/vod/20231219-1/298eb74fdcf0efc18775834a663c5249.jpg', '<p>Cô nàng chuyên làm chiếc váy cưới cho các cô dâu đã thổi sức sống mới vào những chiếc váy đã qua sử dụng, biến giấc mơ thành hiện thực cho những cô dâu không đủ khả năng mua những chiếc váy đắt tiền. Nhưng khi gặp được chàng trai hoàn hảo, cô ấy sợ không cho trái tim mình cơ hội thứ hai trong tình yêu.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Edy Ganem","avatar":""},{"name":"Brendon Zub","avatar":""},{"name":"Matreya Scarrwener","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
