INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-cua-em', 'Thiên Sứ Của Em', 'Club Friday The Series 11: Kon Mai Kuan Ruk', 'https://phimimg.com/upload/vod/20231207-1/d07ed326b9cd50e42af93c5f987580de.jpg', 'https://phimimg.com/upload/vod/20231207-1/f106adbdcc0d0ffe68f6a0e724ac9c36.jpg', '<p>Thiên Sứ Của Em (Club Friday The Series 11: Kon Mai Kuan Ruk) vietsub xoay quanh Oem, một phóng viên xinh đẹp, tài giỏi với một tương lai rộng mở và sáng lạng. Cũng vì sự tài giỏi này mà các đồng nghiệp đã vô cùng ganh ghét và đố kị với cô. Rồi một ngày, bi kịch xảy ra với Oem khi cô rơi vào tầm ngắm của tên quản lý trăng hoa, bị hắn cưỡng hiếp và sau đó cô bị nhiễm HIV. Chính lúc này người bạn thân luôn bên cạnh cô bấy lâu nay đã ngỏ lời yêu cô, xoa dịu nỗi đau và muốn trở thành dỗ dựa tinh thần cho cô, bất chấp sự phản đối của người thân và gia đình.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 18, 2019, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Bo Vanda Sahawong","avatar":""},{"name":"Ohm Atshar Nampan","avatar":""},{"name":"James Ruangsak Loychusak","avatar":""},{"name":"Nan Chalita Fuangaromya","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
