INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-60-ngay', 'Tổng Thống 60 Ngày', 'Designated Survivor: 60 Days', 'https://phimimg.com/upload/vod/20231207-1/cdd04ae514d25adbf407195faa418266.jpg', 'https://phimimg.com/upload/vod/20231207-1/fa18141fbf9502c68b3e8efb06e9100e.jpg', '<p>Tổng Thống 60 Ngày kể về Park Moo-Jin (Ji Jin-Hee) là cựu giáo sư môn hóa học và hiện đang giữ chức vụ Bộ trưởng Bộ Môi Trường. Anh không hề có tham vọng, niềm tin cá nhân hay khiếu chính trị của một chính trị gia. Một ngày nọ, các viên chức chính phủ cấp cao tụ họp tại buổi diễn thuyết về tình hình đất nước của Tổng thống. Sau đó một vụ nổ xảy ra, giết chết nhiều quan chức chính phủ, trong đó có cả Tổng thống. Park Moo Jin là quan chức chính phủ cấp cao nhất còn sống. Tuy không muốn nhưng anh vẫn phải ngồi vào vị trí Tổng thống tạm quyền trong 60 ngày. Park Moo Jin truy lùng tổ chức đã gây ra vụ nổ, và thành một nhà lãnh đạo quốc gia.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Jin Hee","avatar":""},{"name":"Heo Jun Ho","avatar":""},{"name":"Kang Han Na","avatar":""},{"name":"Lee Joon Hyuk","avatar":""},{"name":"Bae Jong Ok","avatar":""},{"name":"Kim Gyu Ri","avatar":""},{"name":"Nam Woo Hyun","avatar":""},{"name":"Ok Ye Rin","avatar":""},{"name":"Son Seok Koo","avatar":""},{"name":"Choi Yoon Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', 