INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-tu-biet', 'Lời Từ Biệt', 'The Farewell', 'https://phimimg.com/upload/vod/20231208-1/b9b7e63e869a09fd3f806a917ffee6d7.jpg', 'https://phimimg.com/upload/vod/20231208-1/3057f5787c5b4fe28c7587b770b9dead.jpg', '<p>Bộ phim kể về một gia đình Trung Quốc, khi gia đình phát hiện ra người bà mà họ yêu quý sắp qua đời. Họ quyết định giấu kín bí mật với bà và lên lịch một đám cưới để tụ họp trước khi bà ấy mất. Billi cảm thấy không thoải mái với quyết định của gia đình, và không thể giữ bí mật với bà của cô.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Awkwafina","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Diana Lin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
