INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-ly-dien-ha-yeu-roi', 'Hồ Ly Điện Hạ Yêu Rồi', 'His Highness Fox Lord Falls In Love', 'https://phimimg.com/upload/vod/20231208-1/d58a4ac910545bb384853cc039e5ec7a.jpg', 'https://phimimg.com/upload/vod/20231208-1/08bec119064a9cb4efc251965e47865e.jpg', '<p>Cô gái xui xẻo trong lúc đang khó khăn nhất lại vô tình gặp được bá đạo tổng tài Nhan Vũ, mà anh ta lại còn muốn cô phải sống chung với anh ta! Điều bất ngờ nhất là anh ta còn là ông anh họ mình đang muốn nhờ vả! Nhưng hình như anh họ đang che giấu bí mật gì đó...</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pan Zi Jian","avatar":""},{"name":"Zhizhou He","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324384);
