INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hoa-tien', 'Người Hỏa Tiễn', 'Rocketman', 'https://phimimg.com/upload/vod/20231208-1/ad0da8fd6722d7c76f5b9674fa17199d.jpg', 'https://phimimg.com/upload/vod/20231208-1/5e301fb5d831cbdde750af6516db419c.jpg', '<p>Trong năm 2019 có khá nhiều thước phim âm nhạc được sản xuất, đây là dòng phim tương đối khó làm và không phải là thể loại được ưa chuộng. Tuy có kinh phí không cao nhưng cần chỉnh chu trong từng cảnh quay, đặc biệt là khâu âm thanh. Sắp tới, dự án được đánh giá cực cao Rocketman sẽ ra mắt khán giả, hứa hẹn sẽ là món ăn tinh thần không thể bỏ qua của các fan yêu thích dòng phim này. Phim dự kiến công chiếu tại thị trường Việt Nam từ ngày 14 tháng 6 năm 2019. Người Hỏa Tiễn được Dexter Fletcher đảm nhận vai trò chỉ đạo sản xuất, đạo diễn nổi tiếng 53 tuổi người Anh từng đứng sau rất nhiều dự án đình đám và ông cũng chính là cái tên quan trọng đóng góp vào sự thành công của thước phim này. Ngoài ra, phim còn có sự tham gia của dàn diễn viên chất lượng như: Taron Egerton, Jamie Bell, Richard Madden, Bryce Dallas Howard, Gemma Jones, Steven Mackintosh. Trong đó, nam tài tử Taron sẽ thủ vai chính. Nội dung phim kể về kể về con đường trở thành một huyền thoại âm nhạc của Elton John. Từ nhỏ, cậu đã đam mê với âm nhạc và học rất nhanh, đặc biệt là chiếc đàn piano. Tuy có người mẹ khá lạnh lùng nhưng Elton lại được bà yêu thương, đùm bọc cho đến khi trưởng thành. Mặc dù rất tài năng nhưng Elton lại không được bất cứ ai trong gia đình công nhận về tài năng, và phải một mình bước lên và khẳng định bản thân. Với lỗ lực không biết mệt mỏi, Elton cuối cùng cũng bước tới đỉnh cao danh vọng.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Richard Madden","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324384);
