INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-kinh-di-luc-nua-dem', 'Chuyện Kinh Dị Lúc Nửa Đêm', 'Scary Stories To Tell In The Dark', 'https://phimimg.com/upload/vod/20231208-1/23ef10dd252682f1988a2d6ab2ac02ef.jpg', 'https://phimimg.com/upload/vod/20231208-1/74a655b9a0f76762cb52550ab53253d1.jpg', '<p>Đó là năm 1968 ở Mỹ. Thay đổi đang thổi trong gió ... nhưng dường như xa khỏi sự bất ổn ở các thành phố là thị trấn nhỏ của Thung lũng Mill nơi dành cho nhiều thế hệ, bóng của gia đình Bellows đã lờ mờ lớn. Đó là trong biệt thự của họ ở rìa thị trấn mà Sarah, một cô gái trẻ với những bí mật khủng khiếp, biến cuộc sống bị tra tấn của mình thành một loạt những câu chuyện đáng sợ, được viết trong một cuốn sách đã vượt qua những câu chuyện về thời gian có cách trở thành một cách quá thực tế Đối với một nhóm thanh thiếu niên khám phá ngôi mộ đáng sợ của Sarah.</p>', 'Full', 1, 'single', 'completed', 39, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '[]', 1784690324384);
