INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-hoc-duong', 'Phi Vụ Học đường', 'Dead Kids', 'https://phimimg.com/upload/vod/20231208-1/25db22367a131c437773d015b9ac57ad.jpg', 'https://phimimg.com/upload/vod/20231208-1/7b5294ca6712beebdfb0ce7b616758eb.jpg', '<p>Nam sinh ngại giao tiếp kết giao với nhóm bạn lập dị đang âm mưu bắt cóc cậu bạn học giàu có, kiêu ngạo. Nhưng thật không may, âm mưu này lại trở nên nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Khalil Ramos","avatar":""},{"name":"Vance Larena","avatar":""},{"name":"Kelvin Miranda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324384);
