INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-thien-dai-thanh-hoa-diem-son', 'Tề Thiên Đại Thánh Hoả Diệm Sơn', 'Monkey King: The Volcano', 'https://phimimg.com/upload/vod/20231207-1/195bb9a671cb28a7d556105dfc408aff.jpg', 'https://phimimg.com/upload/vod/20231207-1/2b5ed9c0c7f638d3ab05ffc797e43945.jpg', '<p>Phim được lấy bối cảnh chính tại Hỏa Diệm Sơn được dàn dựng ở Nội Mông, xoay quanh hành trình vượt qua ải vô cùng khó khăn tại hỏa diệm sơn của tề thiên đại thánh. Viêm Linh Nhi (La Mễ đóng) vốn là hỏa linh trong lò luyện đơn của thái thượng lão quân, trong lần ngộ không đại láo thiên cung đã vô cùng rơi xuống hỏa diệm sơn. Giống như mối tình truyền kiếp, cô chờ đợi ngộ không tại đây đã rất nhiều năm nay, nhưng liệu hai người có thể hạnh phúc trọn vẹn.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324384);
