INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-nguoi-o-vung-ngoai-o', 'Kẻ Giết Người Ở Vùng Ngoại Ô', 'Killer in Suburbia', 'https://phimimg.com/upload/vod/20231206-1/eb4ca823dc7d2e454fbd3690264dcd65.jpg', 'https://phimimg.com/upload/vod/20231206-1/c63ca923527ca7138267f91334fa1110.jpg', '<p>Gina và cô con gái nhỏ Kelsey chuyển đến một thị trấn mới để Kelsey có thể theo học một trường trung học tốt hơn. Nhưng khi Kelsey bị bắt cóc khi đang hẹn hò, mọi cơn ác mộng của Gina đều trở thành sự thật.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Boti Bliss","avatar":""},{"name":"Morgan Obenreder","avatar":""},{"name":"Rebecca Marshall","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324384);
