INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('14-ngay-12-dem', '14 Ngày 12 Đêm', '14 Days, 12 Nights', 'https://phimimg.com/upload/vod/20231206-1/90285e9781b3db02d301d7206b318fb1.jpg', 'https://phimimg.com/upload/vod/20231206-1/1281a8cb70971f1153e4c93d2b88004e.jpg', '<p>Isabelle Brodeur bắt tay vào hành trình đến Việt Nam, nơi sinh của con gái nuôi. Con đường của cô dẫn cô đến với người phụ nữ từng là bảo mẫu của con gái cô. Làm như vậy, Isabelle biết được sự tồn tại và nơi ở của mẹ ruột của con gái mình. Trong suốt cuộc hành trình tuyệt đẹp tuyệt vời này, Isabelle khám phá ra đất nước của con gái mình qua con mắt của người phụ nữ đã đưa cô vào thế giới này. Cuộc hành hương này khiến hai người phụ nữ tiết lộ những bí mật sâu kín nhất của họ</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Anne Dorval","avatar":""},{"name":"Leanna Chea","avatar":""},{"name":"François Papineau","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
