INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta', 'Chúng Ta', 'Us', 'https://phimimg.com/upload/vod/20231206-1/d2305a8e0f5d46f33e93019d2e5c0f3f.jpg', 'https://phimimg.com/upload/vod/20231206-1/eaa57161b769a8abb3d36337a5e1976e.jpg', '<p>Chúng Ta - Us (2019):Us, một tác phẩm đến từ hãng phim Monkeypaw, lấy bối cảnh tại một bờ biển mang tính biểu tượng phía Bắc California trong thời điểm hiện tại, với sự tham gia của các diễn viên như nữ diễn viên đạt giải Oscar Lupita Nyong’o với vai Adelaide Wilson, người đã trở lại căn nhà bên bờ biển mà cô sống thời ấu thơ cùng người chồng Gabe (ngôi sao Winston Duke của Black Panther) và hai người con (Shahadi Wright Joseph, Evan Alex) trong kì nghỉ hè. Bị ám ảnh bởi một chấn thương không thể giải thích trong quá khứ, kết hợp với một chuỗi các sự việc trùng hợp kỳ lạ, Adelaide cảm thấy sự hoang tưởng của bản thân đang tăng ở mức cảnh giác cao độ khi cô ngày càng chắc chắn rằng một điều gì đó tồi tệ sẽ xảy đến với gia đình mình...</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lupita Nyong''o","avatar":""},{"name":"Winston Duke","avatar":""},{"name":"Evan Alex","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324384);
