INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-vieng-tham-tu-than', 'Chuyến Viếng Thăm Tử Thần', 'Guests', 'https://phimimg.com/upload/vod/20231205-1/416e81866f83ef83b4bc48041b318f7f.jpg', 'https://phimimg.com/upload/vod/20231205-1/a9c925814ed45ad424f2edfeaba3bc77.jpg', '<p>Katya và nhóm bạn chợt nảy ra một trò chơi đáng sợ - tổ chức tiệc tùng trong một ngôi nhà trống. Ngay cả khi màn đêm buông xuống, họ vẫn không thấy sợ hãi. Không ngờ rằng, ngôi nhà đã bị một linh hồn cổ xưa từ năm 1900 chiếm giữ. Khi buổi tiệc đang diễn ra, Katya dần phát hiện ra nhiều điều bí ẩn, đặc biệt là với chủ nhân căn nhà ... cũng là người con trai cô phải lòng.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Yuriy Chursin","avatar":""},{"name":"Angelina Strechina","avatar":""},{"name":"Mikhail Meshcheryakov","avatar":""},{"name":"Anastasiya Ukolova","avatar":""},{"name":"Anar Khalilov","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
