INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-dai-cua-sieu-nhan', 'Triều Đại Của Siêu Nhân', 'Reign of the Supermen', 'https://phimimg.com/upload/vod/20231204-1/72830a66b88e02c38f30d258b0261710.jpg', 'https://phimimg.com/upload/vod/20231204-1/3a62da0267a3a9d0246da341518eb00c.jpg', '<p>Chuyện xảy ra , sáu tháng sau sự hy sinh của Superman để đánh bại Doomsday , thì đột nhiên xuất hiện thêm bốn phiên bản mới, khác nhau của Superman : Superboy , Steel , Cyborg Superman và Eradicator . Mỗi người trong số họ đều khác nhau về tính cách và phong cách chống tội phạm so với Người Đàn Ông Thép, khiến cả thế giới đặt câu hỏi, họ là ai ? Tại sao họ lại đến đây ? Mục đích của họ là gì? Liệu Supermen thực sự đã chết hay chưa . Về phần Lois Lane cô vẫn đang đau buồn với cái chết của Clark, nên cô quyết định lao vào điều tra về những Supermen mới này.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jerry O''Connell","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"Rainn Wilson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
