INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-len-ban-la-gioi-nhat', 'Cố Lên! Bạn Là Giỏi Nhất', 'Mr. Fighting', 'https://phimimg.com/upload/vod/20231204-1/d05cb56feb71575414d3eefb210c3273.jpg', 'https://phimimg.com/upload/vod/20231204-1/9a16fda282de5ca9fe741932bf2ffd69.jpg', '<p>Ngôi sao hết thời Hách Trạch Vũ (Đặng Luân đóng) sau 10 năm bị người quản lý Đằng Đan (Ô Quân Mai đóng) không từ mà biệt ném cho một người quản lý không chút kinh nghiệm Ngưu Mỹ Lệ (Nghê Hồng Khiết đóng) khiến anh vừa mơ hồ vừa tức giận. Vì tìm Đằng Đan, Hách Trạch Vũ đành tạm thời chấp nhận sự sắp đặt này, nhưng đoàn đội mới lại khiến anh thật không dám tin, từ trợ lý là nhân viên Marketing siêu thị Phúc Tử (Mã Tư Thuần), cho tới tài xế là bố Phúc Tử (Hàn Đồng Sinh), toàn bộ... đều là người ngoài ngành. Tuy rằng tình trạng của Ekip Thảo Đài khó khăn chồng chất, nhưng nhiều lần cùng nhau trải qua những khảo nghiệm của hiện thực cuộc sống và cùng nhau cố gắng vượt qua những thử thách. Tình yêu khiến cho mọi người trở nên thân thiết với nhau như người thân.Sau những lần vấp ngã, Hách Trạch Vũ đã có được tình thân, tình bạn, tình yêu. Cuối cùng cũng nhận ra một điều, Một bản thân càng tốt hơn không phải là thành công và vinh quang, mà là tôn nghiêm, trách nhiệm và dũng khí của bản thân....</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đặng Luân","avatar":""},{"name":"Mã Tư Thuần","avatar":""},{"name":"Hàn Đồng Sinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324384);
