INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vao-dong-tro-tan', 'Vào Đống Tro Tàn', 'Into The Ashes', 'https://phimimg.com/upload/vod/20231203-1/39f6de7ba01e77d609d234cd8503d15a.jpg', 'https://phimimg.com/upload/vod/20231203-1/df3fa95271b6de858f412fbb17b7d434.jpg', '<p>Có một công việc lương thiện và một người vợ hết mực yêu thương, Nick Brenner tưởng rằng đã thoát khỏi quá khứ tội phạm của mình một cách an toàn. Nhưng đồng bọn cũ đã không quên anh và số tiền anh đã đánh cắp, và khi chúng lấy thứ mà Nick coi trọng nhất bây giờ - người vợ - anh ta không còn gì để mất. Đối mặt với cảnh sát trưởng thị trấn, cũng là cha vợ của mình, Nick phải quyết định xem anh ta sẽ làm lại cuộc đời mới của mình hay đắm chìm trong cuộc trả thù và buộc kẻ thù phải trả giá cho những gì chúng đã làm.</p>', 'Full', 1, 'single', 'completed', 6, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Grimes","avatar":""},{"name":"Robert Taylor","avatar":""},{"name":"James Badge Dale","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
