INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-pha', 'Phong Vân Phá', 'Two Knight Riders', 'https://phimimg.com/upload/vod/20231215-1/a8bcc20c60758c53f5bf90d7aaeb54bf.jpg', 'https://phimimg.com/upload/vod/20231215-1/1e3594f91bbee3ee01b6c6ed73d706a4.jpg', '<p>Bộ phim Phong Vân Phá - Two Knight Riders là câu chuyện về bộ đôi Phong Vân Song Kỵ - Mã Địch Lô và Cung Huyền Kinh. Họ ăn cắp tiền của người giàu, giúp đỡ người nghèo và chống lại quân đội của chính phủ lâm thời - Mã Gia Quân. Những người trong Mã Gia Quân đã chia rẽ Phong Vân Song Kỵ, khiến Cung Huyền Kinh phản bội Mã Địch Lô. Liệu rằng, họ có thể quay trở lại như trước đây, kết hợp với nhau để chống lại những âm mưu đen tối phía sau Mã Gia Quân?</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Zhuoting","avatar":""},{"name":"Yang Junyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324384);
