INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-truc-tong-dai-phan-4', 'Những Cô Gái Trực Tổng Đài (Phần 4)', 'Cable Girls (Season 4)', 'https://phimimg.com/upload/vod/20231204-1/cf6c2cf6da7d11e041cd57d04848b0c4.jpg', 'https://phimimg.com/upload/vod/20231204-1/45e758702624a38d59e290ab03b8a3b2.jpg', '<p>Giữa những thay đổi xã hội vào năm 1931, hội bạn bị vướng vào một vụ giết người bí ẩn và phải cùng hợp tác để phá án trước khi một trong số họ bị kết án tử hình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2019, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Blanca Suárez","avatar":""},{"name":"Yon González","avatar":""},{"name":"Ana Fernández","avatar":""},{"name":"Nadia de Santiago","avatar":""},{"name":"Ana Polvorosa","avatar":""},{"name":"Nico Romero","avatar":""},{"name":"Denisse Peña","avatar":""},{"name":"Raúl Mérida","avatar":""},{"name":"Miguel Diosdado","avatar":""},{"name":"Ángela Cremonte","avatar":""},{"name":"Valentina Zenere","avatar":""},{"name":"Concha Velasco","avatar":""},{"name":"Ana Risueño","avatar":""},{"name":"Martiño Rivas","avatar":""},{"name":"Antonio Valero","avatar":""},{"name":"Gary Pique","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324384);
