INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-chi-em-em', 'Chị Chị Em Em', 'Sister Sister', 'https://phimimg.com/upload/vod/20231204-1/f0d1bba7ed331bb0ca257d007e11474c.jpg', 'https://phimimg.com/upload/vod/20231204-1/10a9837ba2e5e464aac8c0c293d81997.jpg', '<p>Đây là bộ phim tâm lý, khám phá câu chuyện tình yêu xoay quanh hai người phụ nữ xinh đẹp - Thiên Kim và Bảo Nhi. Đối mặt trong một cuộc chơi mà chỉ có một người chiến thắng, khi hạnh phúc của tổ ấm nhỏ sắp bị bão cuốn đi, ai sẽ quyết liệt đấu tranh cho những gì mình muốn và ai sẽ cam chịu để giữ bình yên?</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Thanh Hằng","avatar":""},{"name":"Chi Pu","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Kathy Uyen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324384);
