INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('re-bat-dau-lai-o-mot-the-gioi-khac-la-giao-keo-dong-bang', 'Re: Bắt đầu lại ở một thế giới khác lạ: Giao kèo đóng băng', 'Re: Zero Hyouketsu no Kizuna Bond of Ice', 'https://phimimg.com/upload/vod/20231204-1/dac5738090d456ab48394219a3b09d35.jpg', 'https://phimimg.com/upload/vod/20231204-1/3e86f82792684d0569aac3336b1bd0f7.jpg', '<p>Phù thủy Satella bị mọi người ghét bỏ. Cô có đôi mắt xanh tím và mái tóc bạch kim. Emilia, sống một mình trong một khu rừng rộng lớn, bị hiểu lầm vì cô ấy giống một phù thủy Satella. Lúc đó, một tinh linh dưới hình dạng một con mèo con xuất hiện trước mặt cô ...</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324385);
