INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-kim-cuong-xanh', 'Cuộc Chiến Kim Cương Xanh', 'Siberia', 'https://phimimg.com/upload/vod/20231204-1/453f34caa2234ca8599fc101f926af82.jpg', 'https://phimimg.com/upload/vod/20231204-1/9ee13354a077b6018ca7e96723946f09.jpg', '<p>Keanu Reeves vào vai Lucas Hill một thương gia đến Nga để bán những viên kim cương quý hiếm. Tuy nhiên cuộc giao dịch không thành công và anh trở thành đối tượng bị săn đuổi của những băng nhóm tội phạm và nhiều&nbsp;lực lượng chức năng khác. Với kỹ&nbsp;năng chiến đấu của mình, anh thoát chết và tìm đường rời khỏi nước Nga. Trên đường trốn chạy Lucas gặp gỡ và đắm chìm trong tình yêu với một cô chủ quán cà phê xinh đẹp ở một thị trấn nhỏ thuộc&nbsp;Siberia. Liệu đây là sự tình cờ hay một cái bẫy khác dành cho anh?</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324385);
