INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-kinh-di-trong-nha-xac', 'Chuyện Kinh Dị Trong Nhà Xác', 'The Mortuary Collection', 'https://phimimg.com/upload/vod/20231202-1/b1c0310a7aea2cd48f3958c83627b8f9.jpg', 'https://phimimg.com/upload/vod/20231202-1/4b7a937a9a472e107ab730ad1a323c2f.jpg', '<p>Vì quá chán nản với công việc hiện tại, cô gái trẻ Sam, sau khi tham dự đám tang của một cậu bé tại một nhà xác ma mị, đã tiếp cận người quản lý nhà xác Montgomery Dark để tìm việc làm. Cô gái trẻ đã thách Montgomery Dark kể cho cô nghe những câu chuyện đáng sợ nhất về cái chết mà ông từng biết từ khi điều hành nhà xác này. Bốn câu chuyện ngắn về cái chết được ông hé lộ: về một bà nội trợ, một nam sinh đại học, một người chồng có vẻ yêu vợ và một cô giữ trẻ.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clancy Brown","avatar":""},{"name":"Caitlin Custer","avatar":""},{"name":"Sarah Hay","avatar":""},{"name":"Mike C. Nelson","avatar":""},{"name":"Jacob Elordi","avatar":""},{"name":"Barak Hardley","avatar":""},{"name":"Christine Kilmer","avatar":""},{"name":"Ben Hethcoat","avatar":""},{"name":"Jennifer Irwin","avatar":""},{"name":"James Bachman","avatar":""},{"name":"Alison Gallaher","avatar":""},{"name":"Phyllis Applegate","avatar":""},{"name":"Brennan Murray","avatar":""},{"name":"Ema Horvath","avatar":""},{"name":"Michael Bow","avatar":""},{"name":"Tom Woodruff Jr.","avatar":""},{"name":"Tristan By","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324385);
