INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-yeu-quai', 'Anh Trai Yêu Quái', 'Dear Devil Brother', 'https://phimimg.com/upload/vod/20231210-1/49881484eacd6f40928c2455d95cf030.jpg', 'https://phimimg.com/upload/vod/20231210-1/4e670a098300f9bd1dd379db62c3f84f.jpg', '<p>Cuộc đoàn tụ bất đắc dĩ giữa người anh Kiều Minh Tuấn và người em Issac, vận động viên Judo bị chấn thương nên phải từ bỏ sự nghiệp, bắt đầu cho những tình huống giành gia tài khó đỡ.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Isaac","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Diệu Nhi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324385);
