INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-kha-than', 'Thần Thám Kha Thần', 'Detective KeChen', 'https://phimimg.com/upload/vod/20231203-1/19c494c01c98e324e7b7f7773c9aaefd.jpg', 'https://phimimg.com/upload/vod/20231203-1/99b9619c81d4d50ab895199301ff63db.jpg', '<p>Đầu những năm 20 của thế kỷ trước, quân phiệt hỗn chiến, dân chúng điêu linh; Kha Tần - cao thủ thẩm vấn của sở cảnh sát Thiên Tân, với tinh thần tôn trọng chính nghĩa, kinh nghiệm phong phú và kỹ năng phi thường, trong quá trình làm việc và cuộc sống, đã giúp dân chúng tra rõ rất nhiều chân tướng, giơ cao lá cờ chính nghĩa, làm cho thời kỳ chiến loạn của họ có được một không gian trong sạch, đảm bảo sự an toàn cho tầng lớp nhân dân dưới đáy xã hội. Trong quá trình điều tra phá những vụ án khác nhau, Kha Tần đã tìm ra những nhân chứng quan trọng và bí mật của một vụ nổ năm đó, vụ án cũ này liên quan đến cái chết bất ngờ của cha mẹ anh, tất cả các đầu mối đều chỉ vào thượng cấp tuyệt vời mà anh ấy vô cùng ngưỡng mộ.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Zhi Zhong","avatar":""},{"name":"Li Qian","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324385);
