INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-hon-ngot-ngao', 'Môi Hôn Ngọt Ngào', 'Tell It to the Bees', 'https://phimimg.com/upload/vod/20231201-1/aafedc7f50c9b514f6fb22ebe59569f9.jpg', 'https://phimimg.com/upload/vod/20231201-1/6cf6f8a00be7d26d8f5f95d069d8b3bf.jpg', '<p>Một bà mẹ Lydia độc thân (Holliday Grainger) bị chồng bỏ rơi, gặp bác sĩ nhỏ của làng Jean Markham (Anna Paquin) gần đây đã trở về quê nhà khi con trai của Lydia Charlie được đưa đến bác sĩ sau khi bị bắt nạt ở trường. Khi Lydia và Charlie bị đuổi vì thu nhập của Lydia từ công việc của cô không đầy đủ để trả tiền thuê nhà, Jean mời họ ở lại nhà và cô và Lydia sớm phát triển một tình bạn và một cái gì đó nhiều hơn.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Anna Paquin","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Emun Elliott","avatar":""},{"name":"Steven Robertson","avatar":""},{"name":"Lauren Lyle","avatar":""},{"name":"Gregor Selkirk","avatar":""},{"name":"Kate Dickie","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Euan Mason","avatar":""},{"name":"Zara Howell","avatar":""},{"name":"Violet Fluendy","avatar":""},{"name":"Kaidon McGrath","avatar":""},{"name":"Liam Meghan","avatar":""},{"name":"Joanne Gallagher","avatar":""},{"name":"Joni Samson","avatar":""},{"name":"Isaac Jenkins","avatar":""},{"name":"Farah Samson","avatar":""},{"name":"Leo Hoy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
