INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-kindness-of-strangers', 'The Kindness of Strangers', 'The Kindness of Strangers', 'https://phimimg.com/upload/vod/20231201-1/1bc17ffd0f6d26d744f59b36c1637c0b.jpg', 'https://phimimg.com/upload/vod/20231201-1/673e73173d63f19ccb0c79bb83b90378.jpg', '<p>Clara và hai con trai của cô trốn thoát khỏi người chồng lạm dụng của mình với ít hơn một chút so với chiếc xe của họ và có kế hoạch bắt đầu lại ở New York. Sau khi xe kéo đi, gia đình gặp Alice, người đưa họ vào một nơi trú ẩn khẩn cấp. Trong khi ăn cắp thức ăn tại một nhà hàng Nga có tên &#39;Winter Palace, Clara gặp Marc, người đã có cơ hội giúp đỡ những bữa ăn cũ lấy lại vinh quang trước đây. &quot;Cung điện mùa đông&quot;, sớm trở thành một nơi gặp những cuộc gặp gỡ bất ngờ giữa những người đang trải qua một số cuộc khủng hoảng và số phận mà giờ đã mang lại với nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Zoe Kazan","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Tahar Rahim","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Jack Fulton","avatar":""},{"name":"Will Bowes","avatar":""},{"name":"Patricia McKenzie","avatar":""},{"name":"Masa Lizdek","avatar":""},{"name":"Gugun Deep Singh","avatar":""},{"name":"Esben Smed","avatar":""},{"name":"JoAnn Nordstrom","avatar":""},{"name":"Daniel Kash","avatar":""},{"name":"Lisa Codrington","avatar":""},{"name":"Kim Roberts","avatar":""},{"name":"Rodr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
