INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-kindness-of-strangers', 'The Kindness of Strangers', 'The Kindness of Strangers', 'the kindness of strangers the kindness of strangers zoe kazan andrea riseborough tahar rahim caleb landry jones jay baruchel bill nighy david dencik jack fulton will bowes patricia mckenzie masa lizdek gugun deep singh esben smed joann nordstrom daniel kash lisa codrington kim roberts rodr ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-bi-an-2019', 'Hành Trình Bí Ẩn', 'Missing Link', 'https://phimimg.com/upload/vod/20231201-1/2dff765a9aee36ef24bde3ca95ea6547.jpg', 'https://phimimg.com/upload/vod/20231201-1/f7d14bfb64ca0e8518d4ffed510c9c69.jpg', '<p>Lionel Frost tự coi mình là nhà điều tra hàng đầu thế giới về thần thoại và quái vật. Vấn đề là không ai trong số những đồng nghiệp của anh chấp nhận điều đó. Cuối cùng, cơ hội cho Lionel đã tới trong chuyến thám hiểm vùng Tây Bắc Thái Bình Dương để chứng minh sự tồn tại của một sinh vật huyền thoại - một tàn dư của tổ tiên loài người nguyên thủy. &nbsp;Hành Trình Bí Ẩn là hành trình con người học cách chấp nhận bản thân, tin tưởng và hướng về phía trước. Tác phẩm vừa được xướng tên ở hạng mục Phim hoạt hình xuất sắc Quả cầu vàng 2020.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Amrita Acharia","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Ching Valdes-Aran","avatar":""},{"name":"David Walliams","avatar":""},{"name":"Humphrey Ker","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Neil Dickson","avatar":""},{"name":"Ian Ruskin","avatar":""},{"name":"Matthew Wolf","avatar":""},{"name":"Darren Richardson","avatar":""},{"name":"Alan Shearman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324385);
