INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chong-gia-mao', 'Người Chồng Giả Mạo', 'The Wrong Husband', 'https://phimimg.com/upload/vod/20231201-1/200471e77f2508a5e42d4670aa210302.jpg', 'https://phimimg.com/upload/vod/20231201-1/aa7d61343aa6bf491f22b025477b94d2.jpg', '<p>Sau khi Derrick đi công tác về, Melanie nhận thấy chồng mình cư xử rất khác lạ. Linh cảm của cô đã mách bảo đúng. Kẻ đó không phải Derrick, mà là Alex, em sinh đôi của chồng cô. Alex có ý đồ gì khi đóng giả anh trai mình và Derrick thật sự hiện đang ở đâu?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlotte Graham","avatar":""},{"name":"Rick Cosnett","avatar":""},{"name":"Sofia Mattsson","avatar":""},{"name":"Randy Crowder","avatar":""},{"name":"Forrest Hoffman","avatar":""},{"name":"M.J. Karmi","avatar":""},{"name":"Keida Dervishi","avatar":""},{"name":"John Lacy","avatar":""},{"name":"Cayleb Long","avatar":""},{"name":"Harry Moses","avatar":""},{"name":"Jeff Rolle Jr.","avatar":""},{"name":"Brytni Sarpy","avatar":""},{"name":"Judy Geeson","avatar":""},{"name":"John Combs","avatar":""},{"name":"David Lago","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
