INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-khoi-nghiep', 'Giấc Mơ Khởi Nghiệp', 'Upstarts', 'https://phimimg.com/upload/vod/20231201-1/91f3325354b0b4f2bba8220f2714cc45.jpg', 'https://phimimg.com/upload/vod/20231201-1/370d2b39780255eb4f27f8f7fdb2d583.jpg', '<p>Hi vọng có thể làm việc tốt trong lúc kiếm hàng triệu đô, ba chàng cử nhân bắt tay khởi nghiệp. Nhưng việc kinh doanh khởi sắc thì tình bạn của họ lại bắt đầu rạn vỡ.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Priyanshu Painyuli","avatar":""},{"name":"Shadab Kamal","avatar":""},{"name":"Chandrachoor Rai","avatar":""},{"name":"Rajeev Siddhartha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
