INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-sinh-tu-2-phan-no', 'Ván Cờ Sinh Tử 2: Phẫn Nộ', 'The Divine Move', 'https://phimimg.com/upload/vod/20231201-1/51d94178de86e7de7e2298d41fe2671b.jpg', 'https://phimimg.com/upload/vod/20231201-1/d1e0aa7eb808ea92550e9db354ebe175.jpg', '<p>Quỷ Thủ là người mất hết tất cả chỉ vì một ván cờ vây. Khi sư phụ Hur Il-do, người thầy mà anh tin tưởng nhất qua đời, anh quyết tâm vạch ra một kế hoạch trả thù những kẻ từng hãm hại mình. Bất chấp mọi hiểm nguy, Quỷ Thủ chu du khắp nơi, thách đấu những kỳ thủ cờ vây “máu mặt” và tạo nên những ván cờ đầy kịch tính và đẫm máu.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Woo Do-hwan","avatar":""},{"name":"Jung In-gyeom","avatar":""},{"name":"Won Hyun-jun","avatar":""},{"name":"Shin Soo-yeon","avatar":""},{"name":"Yu Seon","avatar":""},{"name":"Hong Gi-jun","avatar":""},{"name":"Stephanie Lee","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Park Sang-hoon","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Kim San","avatar":""},{"name":"Cha Sung-je","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324385);
