INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('brittany-thi-chay-marathon', 'Brittany Thi Chạy Marathon', 'Brittany Runs a Marathon', 'https://phimimg.com/upload/vod/20231130-1/5a354e2f732d24a3b9eae55b0cd3630e.jpg', 'https://phimimg.com/upload/vod/20231130-1/fa37d1adbe40a73f02af5f599c0e7742.jpg', '<p>Phim dựa trên câu chuyện có thật về Brittany O’Neill. Người xem sẽ được giới thiệu về sự khủng hoảng ở tuổi 28 của cô, công việc thì không như ý muốn, bạn bè chỉ toàn xem thường cô, cũng chẳng có mối quan hệ tình cảm nào, ngày qua ngày chỉ tự giấu sự xấu hổ của mình sau lớp vỏ bọc bên ngoài. Vậy làm thế nào để Brittany có thể thay đổi cuộc đời mình theo một hướng tích cực hơn?</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jillian Bell","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Micah Stock","avatar":""},{"name":"Alice Lee","avatar":""},{"name":"Patch Darragh","avatar":""},{"name":"Peter Vack","avatar":""},{"name":"Kate Arrington","avatar":""},{"name":"Juri Henley-Cohn","avatar":""},{"name":"Adam Sietz","avatar":""},{"name":"Mikey Day","avatar":""},{"name":"Max Pava","avatar":""},{"name":"Jennifer Dundas","avatar":""},{"name":"Erica Hernandez","avatar":""},{"name":"Dan Bittner","avatar":""},{"name":"Beth Malone","avatar":""},{"name":"Nadia Quinn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
