INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-su-that-ket-thuc', 'Đi Tìm Sự Thật: Kết Thúc', 'Chronicle Mysteries: The Deep End', 'https://phimimg.com/upload/vod/20231130-1/12790f079b1f1d0bc894f4f039e24a98.jpg', 'https://phimimg.com/upload/vod/20231130-1/672f8539f3da6075224dd465735baa96.jpg', '<p>Khi Spencer Burke được tìm thấy đã chết trong hồ bơi của anh ta, vợ anh ta bị đưa ra xét xử, nhưng Alex McPherson tin rằng cô vô tội. Một bất ngờ vào phút cuối tại phiên tòa khiến Alex và các nhân viên của tờ báo Chronicle có 1 tuần để điều tra lại và minh oan cho người vợ - một dấu vết đã dẫn Alex và Drew tìm hiểu cuộc đời bí mật của Burke, dẫn đến một kết luận gây sốc.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Alison Sweeney","avatar":""},{"name":"Benjamin Ayres","avatar":""},{"name":"Olivia Steele-Falconer","avatar":""},{"name":"Rebecca Staab","avatar":""},{"name":"Tegan Moss","avatar":""},{"name":"Chenier Hundal","avatar":""},{"name":"Robyn Bradley","avatar":""},{"name":"Edward Ruttle","avatar":""},{"name":"Karen Holness","avatar":""},{"name":"Jessica Heafey","avatar":""},{"name":"Fraser Corbett","avatar":""},{"name":"Anita Brown","avatar":""},{"name":"Sean Campbell","avatar":""},{"name":"Megan Leitch","avatar":""},{"name":"Tosca Baggoo","avatar":""},{"name":"Chad Riley","avatar":""},{"name":"Sean Millin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324385);
