INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-last-tree', 'The Last Tree', 'The Last Tree', 'https://phimimg.com/upload/vod/20231210-1/ee6d471f7e2fd3f638e693b024024d86.jpg', 'https://phimimg.com/upload/vod/20231210-1/a4a178329e517f9e9d0d43017cc1b7ab.jpg', '<p>Femi là một cậu bé người Anh thuộc Di sản Nigeria, sau một tuổi thơ hạnh phúc ở vùng nông thôn Lincolnshire, di chuyển đến bên trong London để sống với mẹ của mình. Đấu tranh với văn hóa và giá trị xa lạ về môi trường mới của mình, Femi tuổi teen phải tìm ra con đường nào đến tuổi trưởng thành mà anh ta muốn thực hiện.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
