INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tinh-tim-thay-haru', 'Vô Tình Tìm Thấy Haru', 'Extraordinary Haru', 'https://phimimg.com/upload/vod/20231203-1/878c74d32a9dc5cf987659c2c7e66ecb.jpg', 'https://phimimg.com/upload/vod/20231203-1/99cd3b775abf90287c8da9b0cfb800e3.jpg', '<p>Vô Tình Tìm Thấy Haru - Extraordinary You xoay quanh cô nàng Eun Dan O, được sinh ra trong gia đình giàu có, học tại ngôi trường danh giá nhưng cô lại bị bệnh tim. Cô còn có vị hôn phu là Baek Kyung, nhưng anh ta luôn ghét cô. Cô thỉnh thoảng lại bị mất trí nhớ và phát hiện mình đang sống trong truyện tranh nhưng cô lại là nhân vật phụ, và không còn nhiều thời gian nữa là cô sẽ tan biến. Vì thế cô đã tìm kiếm một người có thể giúp được mình trong thế giới này là anh chàng cùng lớp điển trai, và Dan O đã đặt tên anh là Haru. Từ đây cả hai đã cùng nhau thay đổi câu chuyện và nhanh chóng kết thúc nó, không những vậy còn tạo nên câu chuyện tình yêu của riêng mình.</p>', 'Hoàn tất (16/16)', 16, 'series', 'completed', 13, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-yoon","avatar":""},{"name":"Kim Ro-woon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324385);
