INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blow-the-man-down', 'Blow the Man Down', 'Blow the Man Down', 'https://phimimg.com/upload/vod/20231130-1/0afa01453421f3923c8ed659e285debd.jpg', 'https://phimimg.com/upload/vod/20231130-1/b17bb2768b52f66e64b1e92fa1f3bbf6.jpg', '<p>Mary Beth và Priscilla Connolly cố gắng che đậy một cuộc chạy mau khủng khiếp với một người đàn ông nguy hiểm. Để che giấu tội ác của họ, các chị em phải đi sâu vào bức tượng tội phạm quê hương của họ, khám phá những bí mật đen tối nhất của thị trấn.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Saylor","avatar":""},{"name":"Sophie Lowe","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Annette O''Toole","avatar":""},{"name":"Marceline Hugot","avatar":""},{"name":"Gayle Rankin","avatar":""},{"name":"Will Brittain","avatar":""},{"name":"Skipp Sudduth","avatar":""},{"name":"Ebon Moss-Bachrach","avatar":""},{"name":"David Coffin","avatar":""},{"name":"David Pridemore","avatar":""},{"name":"Adam Wolf Mayerson","avatar":""},{"name":"Mark S. Cartier","avatar":""},{"name":"Meredith Holzman","avatar":""},{"name":"Linda S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
