INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-quyet-thoi-mien', 'Phán Quyết Thôi Miên', 'Guilt by Design', 'https://phimimg.com/upload/vod/20231130-1/59e85140f7271272baf768ae0d406435.jpg', 'https://phimimg.com/upload/vod/20231130-1/44b9e3b6def35b7fa55d102ed94df4d0.jpg', '<p>Trương Gia Huy là nam diễn viên có tầm ảnh hưởng lớn bậc nhất làng điện ảnh Hong Kong trong những năm gần đây, sự nghiệp của anh đã trải qua đủ thăng trầm khác nhau, và vươn lên một cách từ từ, vững chắc. Đến nay, khi mà các ngôi sao kỳ cựu lần lượt giải nghệ thì tài tử họ Trương là người không thể thiếu để lĩnh sướng con đường điện ảnh xứ cảng thơm. Năm 2019, anh tham gia vào khá nhiều dự án đình đám, và Guilt by Design là một ví dụ điển hình rất đáng được nhắc đến.</p>', 'Full', 1, 'single', 'completed', 7, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Zhang Han","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Cecilia So","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Vincent Wong","avatar":""},{"name":"Deon Cheung","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Lee Sheung-Ching","avatar":""},{"name":"Renci Yeung","avatar":""},{"name":"Ai  Mee","avatar":""},{"name":"Derek Kwok","avatar":""},{"name":"Cheung Ka-Ming","avatar":""},{"name":"Wiyona Yeung","avatar":""},{"name":"Ts","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324385);
