INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hoi-thu-hai-doi-thu', 'Cơ Hội Thứ Hai: Đối Thủ', 'A Second Chance: Rivals!', 'https://phimimg.com/upload/vod/20231129-1/4db5198d8ca8f52a756c43b9ad3bc601.jpg', 'https://phimimg.com/upload/vod/20231129-1/57f45676130d9b7fd1a9d3ec13d6941e.jpg', '<p>Khi Maddy đảm nhận việc huấn luyện một đội gồm các vận động viên thể dục dụng cụ trẻ mười hai tuổi, cô ấy phải đối mặt với sự cạnh tranh gay gắt giữa thành phố và quốc gia, nạn phân biệt chủng tộc, bắt nạt trên mạng và sự thiếu tự tin của chính mình nhưng cuối cùng vẫn chấp nhận thử thách.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Emily Morris","avatar":""},{"name":"Stella Shute","avatar":""},{"name":"Eva Grados","avatar":""},{"name":"India Colombi","avatar":""},{"name":"Elysia Markou","avatar":""},{"name":"Alexander Lloyd","avatar":""},{"name":"Adam Tuominen","avatar":""},{"name":"Sally Pearson","avatar":""},{"name":"Natasha Wanganeen","avatar":""},{"name":"Nina Pearce","avatar":""},{"name":"Carmel Johnson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324385);
