INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-judy', 'Luật Sư Judy', 'Saint Judy', 'https://phimimg.com/upload/vod/20231129-1/af1ba2d78c85cd2870f50aca0a777a8d.jpg', 'https://phimimg.com/upload/vod/20231129-1/0b544c8c1bf998d227c377f25c8bfaee.jpg', '<p>Saint Judy&#39; là câu chuyện có thật đầy cảm hứng về luật sư di trú Judy Wood và cuộc chiến của cô đã thay đổi luật tị nạn của Mỹ mãi mãi. Trong vụ án đầu tiên của mình, Judy đại diện cho một người phụ nữ bị buộc phải trốn khỏi quê nhà sau khi bị Taliban bức hại vì mở trường học cho con gái. Trong khi tung hứng với cuộc sống làm mẹ đơn thân, Judy chiến đấu với những trận chiến ngoan cường trong và ngoài tòa án, không chỉ cứu mạng khách hàng của cô, mà còn thay đổi Luật tị nạn ở Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Monaghan","avatar":""},{"name":"Leem Lubany","avatar":""},{"name":"Common","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Ben Schnetzer","avatar":""},{"name":"Gabriel Bateman","avatar":""},{"name":"Peter Krause","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
