INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-song-con-2019', 'Cuộc Chiến Sống Còn', 'Solum', 'https://phimimg.com/upload/vod/20231129-1/a22b8d54f4fcb3f3f6402760686d262d.jpg', 'https://phimimg.com/upload/vod/20231129-1/85887a0c79cd3a31a3b22340f4b7dfbe.jpg', '<p>Bộ phim Cuộc Chiến Sống Còn - Solum kể về một cuộc phiêu lưu kỳ thú của cặp đôi trẻ. Trong một chương trình thực tế được tổ chức trên một hòn đảo không có người ở, nơi tám thí sinh phải chiến đấu vì sự sống còn của họ. Solum không chỉ là một trò chơi - đó là một bài kiểm tra, một quá trình lựa chọn và một tấm gương đối diện với bản chất của Tự nhiên, với sự giả dối của Loài người.</p>', 'Full', 1, 'single', 'completed', 39, 2019, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Diogo Morgado","avatar":""},{"name":"Darwin Shaw","avatar":""},{"name":"Catarina Mira","avatar":""},{"name":"Gonzalo Ramos","avatar":""},{"name":"Francisco Froes","avatar":""},{"name":"Carlos Carvalho","avatar":""},{"name":"Maria Botelho Moniz","avatar":""},{"name":"Luís Lourenço","avatar":""},{"name":"Anna Ludmilla","avatar":""},{"name":"Cláudia Semedo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324385);
