INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-tren-dao', 'Ám Sát Trên Đảo', 'Killer On The Island', 'null', 'https://phimimg.com/upload/vod/20231209-1/2c63927e5bb6a49028970ca51bc20520.jpg', '<p>Ám Sát Trên Đảo - Killer On The Island là bộ phim kể về kỳ nghỉ trong mơ với chồng của một người phụ nữ bỗng trở thành mục tiêu bị săn đuổi, sau khi cô bắt đầu nghi ngờ một trong những người dân đảo đảo có thể đã thực hiện nhiều vụ giết người, và hắn sẵn sàng tấn công lại!</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jordi Vilasuso","avatar":""},{"name":"Barbie Castro","avatar":""},{"name":"Brian Patrick Clarke","avatar":""},{"name":"Jackie Moore","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324385);
