INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-2019', 'Người Vận Chuyển', 'The Courier', 'https://phimimg.com/upload/vod/20231026-1/df6abe5a403a8817eb93fe110e6fa4a3.jpg', 'https://phimimg.com/upload/vod/20231026-1/74b69c0bad11021c5c347b34d91b18bc.jpg', '<p>Bộ phim Người Chuyển Vận Chuyển hành động dữ dội này mở ra trong thời gian thực khi hai linh hồn bị lôi kéo chiến đấu cho cuộc sống của họ. Người chiến thắng giải thưởng Viện hàn lâm (R) Gary Oldman (nhượng quyền của Hiệp sĩ bóng đêm) đóng vai một tên trùm tội phạm độc ác ra tay để giết Nick, nhân chứng đơn độc được thiết lập để làm chứng chống lại anh ta. Anh ta thuê một nữ chuyển phát nhanh xe máy bí ẩn (Olga Kurylenko, Quantum of Solace) để vô tình đưa ra một quả bom khí độc để giết Nick, nhưng sau khi cô cứu Nick khỏi cái chết nhất định, bộ đôi phải đối đầu với một đội quân giết người tàn nhẫn để sống sót. ...</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Alicia Agneson","avatar":""},{"name":"Amit Shah","avatar":""},{"name":"Craig Conway","avatar":""},{"name":"Lee Charles","avatar":""},{"name":"Joel Michaely","avatar":""},{"name":"Greg Orvis","avatar":""},{"name":"Calli Taylor","avatar":""},{"name":"Gordon Alexander","avatar":""},{"name":"Ty Hurley","avatar":""},{"name":"Jamie Satterthwaite","avatar":""},{"name":"Renars Latkovskis","avatar":""},{"name":"Neil Chapelhow","avatar":""},{"name":"Michael Fato","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
