INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-lien-lac', 'Mất Liên Lạc', 'Lost Transmissions', 'https://phimimg.com/upload/vod/20231209-1/0f59b10e98468e1da078b136f4c9fd77.jpg', 'https://phimimg.com/upload/vod/20231209-1/a0de388ce3963ae6111b5b529a6b8667.jpg', '<p>Nhạc sĩ Hannah phát hiện ra bạn của cô, nhà sản xuất thu nhạc Theo Ross, đang dùng thuốc điều trị bệnh tâm thần phân liệt. Cô tìm cách đưa Theo vào một cơ sở tâm thần, giúp anh vượt qua những ảo tưởng hào nhoáng và nghiệt ngã của giới giải trí. Phim mang đến cái nhìn rõ nét về những góc khuất phía sau sự ra đời của một bản hit.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Tao Okamoto","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
