INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-cong-ly-2019', 'Đi Tìm Công Lý', 'The Culprit', 'https://phimimg.com/upload/vod/20231115-1/ec480459b3c77d2779650e5466a2cd4e.jpg', 'https://phimimg.com/upload/vod/20231115-1/47a63e32f14becba59a97ffdbbbe396a.jpg', '<p>Vợ của Young Hoon, (Song Sae Byeok) bị sát hại tàn nhẫn. Một mẫu tóc được tìm thấy tại hiện trường vụ án khớp với tóc của bạn thân anh ta, Joon Sung (Oh Min Suk) và Joon Sung sớm bị bắt vì tội giết người. Trong khi đó, vợ của Joon Sung, Da Yeon (Yoo Sun) khăng khăng rằng chồng mình vô tội. Young Hoon cũng muốn biết sự thật đằng sau cái chết của vợ mình. Để cứu chồng khỏi cảnh tù tội, Da Yeon cần Young Hoon làm nhân chứng. Young Hoon đề nghị Da Yeon hợp tác để khám phá sự thật và đổi lại anh sẽ làm nhân chứng cho chồng cô.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Sae-byuk","avatar":""},{"name":"Yu Seon","avatar":""},{"name":"Jang Hyuk-jin","avatar":""},{"name":"Oh Min-seok","avatar":""},{"name":"Han Soo-yeon","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Lee Soi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324385);
