INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-phuong', 'Hai Phượng', 'Hai Phượng', 'https://phimimg.com/upload/vod/20230917-1/510f39527bcc07538cc1a163128c40a5.jpg', 'https://phimimg.com/upload/vod/20230917-1/7e4c2ad600ac6d37b8397c39744003f1.jpg', '<p><span style="font-family: ">Hai Phượng kể về cuộc hành trình đầy gay cấn và gian của khi người mẹ vùng quê tìm cách cứu con mình thoát khỏi đường dây bắt cóc khổng lồ. Không tấc sắc trong tay, người phụ nữ thân cô thế cô làm sao chống lại bọn xã hội đen tàn ác để giành lại nguồn sống của đời mình?</span><br/></p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Veronica Ngo","avatar":""},{"name":"Phan Thanh Nhien","avatar":""},{"name":"Phạm Anh Khoa","avatar":""},{"name":"Thanh Hoa","avatar":""},{"name":"Mai Cat Vi","avatar":""},{"name":"Le Trang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
