INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-dam-gian-du', 'Nắm Đấm Giận Dữ', 'Fury First', 'null', 'https://phimimg.com/upload/vod/20231208-1/e4cd355f0e5cb34b1dee9fd60f779d2b.jpg', '<p>Nắm Đấm Giận Dữ - Fury Fist kể về Xiao Ma, con trai sau của nhà vô địch quyền anh, bị đánh bại trong cuộc bầu chọn của Thập hổ Quảng Đông, và được mẹ của anh ta sắp xếp vào Tây Môn Hội. Xiao Ma phát hiện ra rằng Lord Doro đã cấu kết với người nước ngoài để tuồn khói và đốt khói. Lord Doro lao vào giết gia đình ngựa, và cuối cùng thức tỉnh lương tâm để bảo vệ gia đình và đất nước, và bắt đầu một cuộc chiến tuyệt vọng với Lord Doro.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Jian","avatar":""},{"name":"Chen Jiajia","avatar":""},{"name":"Zhai Lin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324385);
