INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nguoc-thoi-gian-de-tim-em', 'Đi Ngược Thời Gian Để Tìm Em', 'HELLO WORLD', 'https://phimimg.com/upload/vod/20231130-1/4938a5f73f35e5bfba940b7d9e907148.jpg', 'https://phimimg.com/upload/vod/20231130-1/945ad05b9ac00913213dceffaa16e73c.jpg', '<p>Bộ phim lãng mạn giả tưởng này lấy bối cảnh tại Kyoto vào năm 2027 và sẽ sử dụng nhiều địa danh nổi tiếng như Fushimi Inari Taisha và đền Kamo. Movie xoay quanh cậu bé học sinh cao trung Naomi Katagaki. Một ngày nọ, một người lạ đột ngột xuất hiện trước mặt cậu và tự xưng mình là Naomi đến từ tương lai 10 năm sau. Cùng với nhau, họ phải thay đổi tương lai và cứu lấy cô bạn Ruri, người mà 3 tháng sau sẽ hẹn hò với Naomi hiện tại.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takumi Kitamura","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Minami Hamabe","avatar":""},{"name":"Haruka Fukuhara","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Moka Hiraguri","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324385);
