INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-do-hao-nhoang', 'Ấn Độ Hào Nhoáng', 'The Bling Lagosians', 'https://phimimg.com/upload/vod/20231129-1/2ece123d0c783b9553ac8b6631acd607.jpg', 'https://phimimg.com/upload/vod/20231129-1/c132aab3d882b4cb2de094e0486a063b.jpg', '<p>Khi nữ gia chủ nhất quyết đòi tổ chức bữa tiệc xa hoa mừng sinh nhật 51 tuổi, món nợ gia đình nằm trên bờ vực bị bơi bày, đe dọa việc kinh doanh – và cả di sản của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Nigeria', 0, '[{"name":"Bunmi Aboderin","avatar":""},{"name":"Toyin Abraham","avatar":""},{"name":"Tana Egbo-Adelana","avatar":""},{"name":"Osas Ighodaro","avatar":""},{"name":"Joyce Akabogu","avatar":""},{"name":"Samuel Animashaun","avatar":""},{"name":"ayolola ayoola","avatar":""},{"name":"Aiyeola Bisola","avatar":""},{"name":"Monalisa Chinda","avatar":""},{"name":"Chris Okagbue","avatar":""},{"name":"Alexx Ekubo","avatar":""},{"name":"Inna Erinze","avatar":""},{"name":"Justin Ezirim","avatar":""},{"name":"Dele Gabriel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
