INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-am-dia-nguc', 'Tổ Ấm Địa Ngục', 'Hellcome Home', 'https://phimimg.com/upload/vod/20231129-1/910837f12f2df850020ef6ebe3ef66e2.jpg', 'https://phimimg.com/upload/vod/20231129-1/d689ba579faf57b18ad642704b87e03b.jpg', '<p>Phim là hai câu chuyện riêng biệt từ các khoảng thời gian khác nhau: gia đình Villareal ở thời điểm hiện tại và nhà Domingo sống cùng một ngôi nhà vào những năm 90. Những tưởng sẽ được sống bình yên thoát khỏi thành phố ồn ào, họ không ngờ rằng mình sẽ gặp phải những sinh vật siêu nhiên và linh hồn ma quỷ làm ảnh hưởng đến cuộc sống và tinh thần của các thành viên.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Dennis Trillo","avatar":""},{"name":"Beauty Gonzalez","avatar":""},{"name":"Raymond Bagatsing","avatar":""},{"name":"Lui Manansala","avatar":""},{"name":"Alyssa Muhlach","avatar":""},{"name":"Nhikzy Calma","avatar":""},{"name":"Elle Ramirez","avatar":""},{"name":"Teroy Guzman","avatar":""},{"name":"Teejay Marquez","avatar":""},{"name":"Gillian Vicencio","avatar":""},{"name":"Miel Espinoza","avatar":""},{"name":"Kokoy de Santos","avatar":""},{"name":"Francis Magundayao","avatar":""},{"name":"Iana Bernardez","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324385);
