INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-che-ngu-gio', 'Cậu Bé Chế Ngự Gió', 'The Boy Who Harnessed the Wind', 'https://phimimg.com/upload/vod/20231125-1/f3256f9c8503b1a805fd0fe78096f6b4.jpg', 'https://phimimg.com/upload/vod/20231125-1/0911d096358f0df3978dfcee63f6557f.jpg', '<p>Bắt nguồn từ một cuốn sách khoa học, cậu bé 13 tuổi William Kamkwamba đã dựng lên một tuabin gió để cứu ngôi làng ở Malawia khỏi nạn đói. Dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maxwell Simba","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Aïssa Maïga","avatar":""},{"name":"Lily Banda","avatar":""},{"name":"Joseph Marcell","avatar":""},{"name":"Lemogang Tsipa","avatar":""},{"name":"Philbert Falakeza","avatar":""},{"name":"Noma Dumezweni","avatar":""},{"name":"Khalani Makunje","avatar":""},{"name":"Robert Agengo","avatar":""},{"name":"Felix Lemburgo","avatar":""},{"name":"Raymond Ofula","avatar":""},{"name":"Rophium Banda","avatar":""},{"name":"Kelvin Maxwell Ngoma","avatar":""},{"name":"Edwin Chonde","avatar":""},{"name":"Fiskan Makawa","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324385);
