INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-su-va-ke-dien', 'Giáo Sư Và Kẻ Điên', 'The Professor and the Madman', 'https://phimimg.com/upload/vod/20231125-1/f1f9af8a58213682fe7c49beb4dd60b2.jpg', 'https://phimimg.com/upload/vod/20231125-1/9cc69ae2b6ceea4359b73c2e4dd7506d.jpg', '<p>Giáo Sư Và Kẻ Điên - The Professor And The Madman kể về vị giáo sư nổi tiếng, Sir James Murray cùng cuộc đời thăng trầm của ông. Vào năm 1857, ông bắt đầu biên soạn cuốn từ điển tiếng Anh Oxford và nhận được hơn 10000 mục từ một bệnh nhân đang được điều trị tại bệnh viện Broadmoor Criminal Lunatic Asylum. Sau đó, ông làm lãnh đạo ủy ban giám sát và Tiểu thương WC, trở thành một tên tuổi được nhiều người nhắc đến.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Natalie Dormer","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Jeremy Irvine","avatar":""},{"name":"Brendan Patricks","avatar":""},{"name":"Adam Fergus","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Brian Fortune","avatar":""},{"name":"Aidan McArdle","avatar":""},{"name":"David Crowley","avatar":""},{"name":"Kieran O''Reilly","avatar":""},{"name":"Bryan Murray","avatar":""},{"name":"Oengus MacNamara","avatar":""},{"name":"Christopher M","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
