INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-khoang-nhuong', 'Không Khoang Nhượng', 'Trust No 1', 'https://phimimg.com/upload/vod/20231125-1/71913af91ef587eac0904c01a6f87c6c.jpg', 'https://phimimg.com/upload/vod/20231125-1/8ad9879705ff9d0ef77593ac7a66910d.jpg', '<p>Sĩ quan Bradley điều tra các vụ giết người được cho là một phần của vụ giết người hàng loạt và nhanh chóng biết được vụ án còn lớn hơn nhiều. Với số lượng nạn nhân đang tăng lên, và không có manh mối gì thêm, anh ta quay sang phương án cuối cùng để được giúp đỡ, anh trai của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Douglas Rouillard","avatar":""},{"name":"Britton Purvis","avatar":""},{"name":"Charles Justo","avatar":""},{"name":"Ryan Rouillard","avatar":""},{"name":"Michele Gomez","avatar":""},{"name":"Michael Zammito","avatar":""},{"name":"Scott D. Gold","avatar":""},{"name":"Bradford Eckhart","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324385);
