INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-den-vien-nien-ngu-thu', 'Đợi đến Viên Niên Ngữ Thu', 'Buried City to Shut All Lights', 'null', 'https://phimimg.com/upload/vod/20231125-1/1ae3f5b5bbb5e1b91a89917ebdb9bb2e.jpg', '<p>Một câu chuyện tình buồn và đau khổ giữa một giáo viên và một học sinh kể về nữ chính và âm mưu trả thù của cô. Quan Ji gửi con gái Qiyue đi học nghệ thuật dưới sự hướng dẫn của con trai thứ hai của gia tộc Chu. Qiyue đổi tên thành Yiluo (Helan Dou). Con trai thứ hai Chu Che (Feng Lijun) là một thiếu niên xinh đẹp với phong thái kiêu ngạo. Vì một căn bệnh bí ẩn, anh sống ẩn dật không muốn gặp du khách. ** Phần tiếp theo của chương trình truyền hình</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Landou","avatar":""},{"name":"Feng Lijun","avatar":""},{"name":"Chake Lau","avatar":""},{"name":"Zhang Yuqi","avatar":""},{"name":"Sang Na","avatar":""},{"name":"Yu Zi Xuan","avatar":""},{"name":"Yao Shuhao","avatar":""},{"name":"Wu Heng","avatar":""},{"name":"Wei Yankan","avatar":""},{"name":"Zheng Tuojiang","avatar":""},{"name":"Diana Dai","avatar":""},{"name":"Liu Di","avatar":""},{"name":"Ivan Xu","avatar":""},{"name":"Zhang Xingyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324385);
