INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-san-moi', 'Đảo Săn Mồi', 'Prey', 'https://phimimg.com/upload/vod/20231125-1/78f6b50ec6e47e2dc962e3de5d009c15.jpg', 'https://phimimg.com/upload/vod/20231125-1/f10acc26eaab15d243d6e8337d6f5ca6.jpg', '<p>Để vượt qua sang chấn tâm lý, Toby đã đăng ký một khóa học sinh tồn. Chương trình yêu cầu cậu phải tập cắm trại một mình nơi đảo hoang trong 3 ngày. Xui xẻo thay, hòn đảo mà cậu chọn lại bị ám bởi một thế lực chết chóc kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Miller","avatar":""},{"name":"Kristine Froseth","avatar":""},{"name":"Jolene Anderson","avatar":""},{"name":"Phodiso Dintwe","avatar":""},{"name":"Jerrica Lai","avatar":""},{"name":"Anthony Jensen","avatar":""},{"name":"Jody Mortara","avatar":""},{"name":"Vela Cluff","avatar":""},{"name":"Joey Adanalian","avatar":""},{"name":"Travis Cluff","avatar":""},{"name":"Mariya Kraineva","avatar":""},{"name":"Loganathan Kanabathy","avatar":""},{"name":"Nathan Healy","avatar":""},{"name":"Jennifer Riordan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324385);
