INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-tri-nhan-sinh', 'Phi Trì Nhân Sinh', 'Pegasus', 'https://phimimg.com/upload/vod/20231125-1/29635b88026ef40a9b411fea80dd55a3.jpg', 'https://phimimg.com/upload/vod/20231125-1/68adfc3602a317edcf6202c3309fcab7.jpg', '<p>Phi Trì Nhân Sinh xoay quanh tay đua hết thời Trương Trì, anh là tay đua từng hô mưa gọi gió trong giới đua xe, nay chỉ có thể bán cơm chiên ở vỉa hè, Trương Trì quyết chí quay lại đường đua, khiêu chiến với tài năng thế hệ mới khi sự nghiệp của anh đã ở giai đoạn hoàng hôn. &nbsp;Trương Trì muốn tập hợp dàn cộng sự năm xưa, kêu gọi thần long, tái hiện ngày tháng huy hoàng trước đây, không ngờ hiện thực tàn khốc, gặp đủ trắc trở. Trên con đường quay lại đường đua, Trương Trì phải bắt đầu từ việc thi lấy bằng lái, rốt cuộc sẽ có bao nhiêu khó khăn chờ đợi tay đua hết thời này?</p>', 'Full', 1, 'single', 'completed', 8, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shen Teng","avatar":""},{"name":"Johnny Huang","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Yin Fang","avatar":""},{"name":"Zhang Benyu","avatar":""},{"name":"Wei Xiang","avatar":""},{"name":"Li Chun''ai","avatar":""},{"name":"William Feng","avatar":""},{"name":"Sui He","avatar":""},{"name":"Pan Xiaoting","avatar":""},{"name":"Tian Yuan","avatar":""},{"name":"Xu Jiawei","avatar":""},{"name":"Bing Li","avatar":""},{"name":"Zack Gao","avatar":""},{"name":"Gao Hailong","avatar":""},{"name":"Liu Dinghan","avatar":""},{"name":"Zhang Dabao","avatar":""},{"name":"Teng Ge''Er","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Ph