INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-coc-ngay-den-toi', 'Băng Cốc Ngày Đen Tối', 'Bangkok Dark Tales', 'https://phimimg.com/upload/vod/20231206-1/ceb77f092af0dec320a1cf0bcecd06d4.jpg', 'https://phimimg.com/upload/vod/20231206-1/4a70bcc7e20a126c0063c992dba72c9b.jpg', '<p>Nếu bạn nghĩ &quot;Bangkok&quot; là một thành phố tuyệt vời thì tôi xin bạn hãy suy nghĩ kỹ - Hãy chuẩn bị tinh thần xem &quot;Bangkok Dark Tales&quot; bộ phim được tạo nên từ 3 tình huống 3 câu chuyện kinh dị và 3 địa điểm rùng rợn ở Bangkok mà bạn sẽ không bao giờ quên.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324385);
