INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-dau-2019', 'Nụ Hôn Đầu', 'Fall in Love at First Kiss', 'https://phimimg.com/upload/vod/20231125-1/317fcbd3bd4e8b5b13bf9a691e66c9d0.jpg', 'https://phimimg.com/upload/vod/20231125-1/4996b624d6331202b7f9af9d86b1e69d.jpg', '<p>Nụ Hôn Đầu xoay quanh hai nhân vật chính là Giang Trực Thụ và Viên Tương Cầm. Trong khi Giang Trực Thụ là một chàng trai thư sinh toàn năng lạnh lùng hàng ngàn học sinh mến mộ thì Tương Cầm lại là một cô nàng hậu đậu, ngây thơ và đem lòng mơ mộng về người mà cô quyết định sẽ ảnh hưởng đến mình suốt cuộc đời. Từ lần đầu tiên gặp mặt, đến những cảm xúc lẫn lộn không thể diễn tả thành lời và cuối cùng là can đảm nói ra hết tình cảm của bản thân, hành trình tìm kiếm tình yêu đích thực của cả hai tràn ngập trong những giai thoại ngọt ngào và lãng mạn.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Darren Wang","avatar":""},{"name":"Lin Yun","avatar":""},{"name":"Kenji Chen","avatar":""},{"name":"Cecilia Choi","avatar":""},{"name":"Christopher Lee Ming-Shun","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Yi-Chen Tsai","avatar":""},{"name":"Alina Cheng","avatar":""},{"name":"Keelong Hsu","avatar":""},{"name":"Shu-yao Kuo","avatar":""},{"name":"Li-Tung Chang","avatar":""},{"name":"Rays Hsu","avatar":""},{"name":"Dino Lee","avatar":""},{"name":"Yankee Yang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
