INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-hon-dau-2019', 'Nụ Hôn Đầu', 'Fall in Love at First Kiss', 'nụ hôn đầu fall in love at first kiss darren wang lin yun kenji chen cecilia choi christopher lee ming-shun christy chung lai-tai yi-chen tsai alina cheng keelong hsu shu-yao kuo li-tung chang rays hsu dino lee yankee yang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-ao-tuong', 'Vùng Đất Ảo Tưởng', 'A Land Imagined', 'https://phimimg.com/upload/vod/20231125-1/cf4997ea61d6d1d8ccb55f88d6f5f1b8.jpg', 'https://phimimg.com/upload/vod/20231125-1/fa7350e3d72a0081f436328d643ef9c4.jpg', '<p>Chuyện phim bắt đầu bằng việc một người công nhân xây dựng người Trung Quốc tên là Wang Bi Cheng đến Singapore làm việc. Không may Wang bị thương ở tay trong quá trình làm việc nên chuyển sang làm lái xe. Nhưng bỗng một hôm Wang mất tích một cách bí ẩn, không một lời nhắn để lại, không chút manh mối.Sau khi nhận được tin báo án, Lok anh chàng sĩ quan cảnh sát nhanh chóng nhận vụ án này và điều tra, bởi vì Lok cũng đang điều tra một vụ tương tự, một công nhân người Bengal khác cũng đã mất tích giống như cái cách Wang mất tích.Nhưng càng điều tra, Lok càng phát hiện ra những người chủ của những công nhân này đều là những kẻ vô đạo đức. Dường như chủ của họ đều liên quan đến nhau hoặc cùng là một người, nhưng đều là kẻ xấu. Vậy rốt cuộc thì điều gì đã xảy ra với Wang và người công nhân Bengal kia? Liệu Lok có tìm ra được những người này và cứu họ hay họ đã bị hại ở một nơi nào đó?</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Peter Yu","avatar":""},{"name":"Liu Xiaoyi","avatar":""},{"name":"Guo Yue","avatar":""},{"name":"Jack Tan","avatar":""},{"name":"Ishtiaque Zico","avatar":""},{"name":"Kelvin Ho","avatar":""},{"name":"George Low","avatar":""},{"name":"Debabrota Basu","avatar":""},{"name":"Andie Chen","avatar":""},{"name":"Khalishan Liang","avatar":""},{"name":"Qin Tianshu","avatar":""},{"name":"Ottylia Liu","avatar":""},{"name":"Xiao Jing","avatar":""},{"name":"Andy Nyo","avatar":""},{"name":"Joey Heng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
