INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuong-sat-bien-thai', 'Kẻ Cuồng Sát Biến Thái', 'Extremely Wicked, Shockingly Evil and Vile', 'https://phimimg.com/upload/vod/20231124-1/d4bf4a45d081574e9daccd4327c0d81e.jpg', 'https://phimimg.com/upload/vod/20231124-1/b277bc570c79a4d8f54df1c466bcddfe.jpg', '<p>Kẻ Cuồng Sát Biến Thái - Extremely Wicked, Shockingly Evil, and Vile là là bộ phim dựa trên nhân vật có thật Ted Bundy - tên sát nhân hàng loạt khét tiếng hàng đầu trong lịch sử nước Mỹ. Bundy bị buộc tội giết người dã man khi hành hung hơn 30 phụ nữ và quan hệ với xác của họ sau đó. Bộ phim sẽ tái hiện lại những tội ác mà Ted Bundy gây ra từ khi bắt đầu cho đến lúc bị tử hình, cùng với đó là đào sâu mối quan hệ giữa Ted và người bạn gái lâu năm Elizabeth.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Angela Sarafyan","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Grace Victoria Cox","avatar":""},{"name":"Forba Shepherd","avatar":""},{"name":"Grace Balbo","avatar":""},{"name":"Morgan Pyle","avatar":""},{"name":"Ava Inman","avatar":""},{"name":"Macie Carmosino","avatar":""},{"name":"Sydney Vollmer","avatar":""},{"name":"Ken Strunk","avatar":""},{"name":"Joe Berlinger","avatar":""},{"name":"Brandon Trost","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324385);
