INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-noi-day-cua-lanh-chua-narasimha-reddy', 'Cuộc Nổi Dậy Của Lãnh Chúa Narasimha Reddy', 'Sye Raa Narasimha Reddy', 'https://phimimg.com/upload/vod/20231124-1/7de84ebe5d7450b2cd0dffb832706b20.jpg', 'https://phimimg.com/upload/vod/20231124-1/874061d0955d83dc1d7cabf20f8bbbe5.jpg', '<p>10 năm trước cuộc nổi loạn của phe phái, Syeraa Uyyalawada Narasimha Reddy, anh hùng vô danh của Kurnool, Rayalaseema là chiến binh tự do đầu tiên của Ấn Độ bắt đầu một cuộc nổi loạn chống lại thuộc địa Đông Ấn Anh vào năm 1846.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Chiranjeevi","avatar":""},{"name":"Sudeep","avatar":""},{"name":"Vijay Sethupathi","avatar":""},{"name":"Ravi Kishan","avatar":""},{"name":"Jagapati Babu","avatar":""},{"name":"Nayanthara","avatar":""},{"name":"Tamannaah Bhatia","avatar":""},{"name":"Henry Maynard","avatar":""},{"name":"Oscar Skagerberg","avatar":""},{"name":"Mark Kitto","avatar":""},{"name":"Brahmaji","avatar":""},{"name":"Ranadheer Beesu","avatar":""},{"name":"Nassar","avatar":""},{"name":"Tanikella Bharani","avatar":""},{"name":"Mukesh Rishi","avatar":""},{"name":"Raghu Babu","avatar":""},{"name":"Prudhviraj","avatar":""},{"name":"Anand","avatar":""},{"name":"Ajay Rathnam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324385);
