INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-noi-day-cua-lanh-chua-narasimha-reddy', 'Cuộc Nổi Dậy Của Lãnh Chúa Narasimha Reddy', 'Sye Raa Narasimha Reddy', 'cuộc nổi dậy của lãnh chúa narasimha reddy sye raa narasimha reddy chiranjeevi sudeep vijay sethupathi ravi kishan jagapati babu nayanthara tamannaah bhatia henry maynard oscar skagerberg mark kitto brahmaji ranadheer beesu nassar tanikella bharani mukesh rishi raghu babu prudhviraj anand ajay rathnam ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-5-de-danh', 'Tháng 5 Để Dành', 'Sunset Promise', 'https://phimimg.com/upload/vod/20231124-1/f765a904e02ef7e55caa9098ab0c1187.jpg', 'https://phimimg.com/upload/vod/20231124-1/65014e2a285db612a5125c2539ec6d30.jpg', '<p>Được chuyển thể từ tiểu thuyết mạng Ranh giới, Tháng 5 để dành xoay quanh mối tình tuổi học trò giữa Hiếu (Xuân Hùng) và Mai Ngọc (Minh Trang) vào những năm đầu thế kỷ XXI. &nbsp;Hiếu vốn là cậu học sinh lớp 11 yêu thích văn thơ, với những rung động và tò mò thuở đầu đời về tình yêu và giới tính. &nbsp;Giống như bao bạn học khác, cậu phải lòng cô lớp phó học tập xinh xắn và tài năng Mai Ngọc. &nbsp;Trong một lần làm chung báo tường, cô gái cũng bắt đầu “cảm nắng” cậu bạn cùng lớp ngây ngô. Song, mối tình tưởng chừng hồn nhiên của họ sớm gặp phải vô vàn sóng gió.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Xuân Hùng","avatar":""},{"name":"Minh Trang","avatar":""},{"name":"Đức Ngụy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324385);
