INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-danh-lua', 'Nghệ Thuật Đánh Lừa', 'Art of Deception', 'https://phimimg.com/upload/vod/20231121-1/c09ab9f3320d1f06af5bd65f0ae1dab6.jpg', 'https://phimimg.com/upload/vod/20231121-1/6e0aafddd1f5ffcb44030f282fec7d73.jpg', '<p>CIA lên kế hoạch để có được sự kiểm soát tâm trí hoàn toàn đối với toàn bộ con người bị nhiễm virus thông qua chip nano. Khi chip máy tính bị gián đoạn do sự cố, Joseph Markham đã tìm ra sự thật, và cuộc chiến giành sự sống, tình yêu và sự thống trị thế giới bắt đầu.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Ryan","avatar":""},{"name":"Jackie Nova","avatar":""},{"name":"Leon van Waas","avatar":""},{"name":"Zac Titus","avatar":""},{"name":"Craig Bruenell","avatar":""},{"name":"Jerry Hansen","avatar":""},{"name":"Christopher Erickson","avatar":""},{"name":"Nicholas Talone","avatar":""},{"name":"Landall Goolsby","avatar":""},{"name":"Tannis Hanson","avatar":""},{"name":"Rich Paul","avatar":""},{"name":"Kelvin Nova","avatar":""},{"name":"Daniel Pierce IV","avatar":""},{"name":"Andrew Miller","avatar":""},{"name":"Daniel Joo","avatar":""},{"name":"Mark Sivertsen","avatar":""},{"name":"Keenan Johnston","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
