INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('archimedes-no-taisen', 'Archimedes no Taisen', 'The Great War of Archimedes', 'https://phimimg.com/upload/vod/20231120-1/e456d945145c2b6d39cf8464e7633620.jpg', 'https://phimimg.com/upload/vod/20231120-1/cf51ee52f61172124f3c20bf38fe0825.jpg', '<p>Đó là vào đầu những năm 1930 và Bộ tư lệnh Hải quân Đế quốc Nhật Bản quyết định chế tạo thiết giáp hạm lớn nhất và đáng gờm nhất thế giới, Yamato. Một trong những đô đốc, Yamamoto Isoroku, không đồng ý. Anh ấy tuyển dụng chuyên gia toán học và mới nổi Tadashi Kai, người phát hiện ra có sự khác biệt giữa ước tính chi phí chính thức và số liệu thực tế. Họ sớm phát hiện ra rằng họ đã vấp phải một âm mưu.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masaki Suda","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Minami Hamabe","avatar":""},{"name":"Tsurube Shofukutei","avatar":""},{"name":"Katsuya Kobayashi","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Isao Hashizume","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Hiroshi Tachi","avatar":""},{"name":"Hoshi Ishida","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
