INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cau-trai-ngoan', 'Những Cậu Trai "Ngoan"', 'Good Boys', 'https://phimimg.com/upload/vod/20231123-1/28fca587f6755c06c6b214d0ad105511.jpg', 'https://phimimg.com/upload/vod/20231123-1/eee471626c829b478a7edaadcd56b314.jpg', '<p>Ba cậu nhóc 12 tuổi, cùng hành trình trốn học để tới San Fernando sửa món đồ chơi đã hỏng trước khi cha mẹ của chúng trở về nhà. Sau khi được một người bạn mời tham gia vào bữa biệc “hôn”, Max đã rất háo hức và rủ thêm 2 người bạn là Lucas và Thor tham gia. Tuy nhiên, cậu không biết hôn và quyết định tìm hiểu về vấn đề này, và chiếc flycam của bố Max được dùng để làm công cụ tìm hiểu. Chưa thể quay lén được gì thì chiếc máy bay đã bị đốn hạ và hư hỏng nặng, 3 cậu nhóc phải sửa được nhanh nhất có thể trước khi bị ba mẹ phát hiện.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jacob Tremblay","avatar":""},{"name":"Brady Noon","avatar":""},{"name":"Keith L. Williams","avatar":""},{"name":"Molly Gordon","avatar":""},{"name":"Midori Francis","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Josh Caras","avatar":""},{"name":"Retta","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Millie Davis","avatar":""},{"name":"Enid-Raye Adams","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Chance Hurstfield","avatar":""},{"name":"Vanessa Przada","avatar":""},{"name":"Lina Renna","avatar":""},{"name":"Benita Ha","avatar":""},{"name":"Maja Aro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
