INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-don-va-vinh-quang', 'Đau Đớn Và Vinh Quang', 'Pain and Glory', 'https://phimimg.com/upload/vod/20231123-1/92717178c87a154dd8d9b2c78c2a3a65.jpg', 'https://phimimg.com/upload/vod/20231123-1/74b74d30319262e9236d42206fabffba.jpg', '<p>Bộ phim được phát hành tại Tây Ban Nha vào ngày 22 tháng 3 năm 2019 để đánh giá tích cực.Phim đã ra mắt quốc tế tại Liên hoan phim Cannes 2019, nơi bộ phim được chọn để tranh giải Cành cọ vàng. Tại Liên hoan phim Cannes, Banderas đã giành giải thưởng Nam diễn viên xuất sắc nhất và Alberto Iglesias đã giành giải thưởng cho Nhạc phim hay nhất. Pain and Glory hiện đang được phát hành trên toàn thế giới. Tính đến tháng 8 năm 2019, nó đã thu về tổng cộng 26,6 triệu đô la trên toàn thế giới. Nó được chọn là tác phẩm Tây Ban Nha cho Phim truyện quốc tế hay nhất tại Giải thưởng Hàn lâm lần thứ 92. Nó được chọn bởi tạp chí Time là bộ phim hay nhất của năm. Bộ phim kể về một loạt các cuộc tái ngộ của Salvador Mallo (Antonio Banderas), một đạo diễn phim bị từ chối. Một số trong những cuộc tái ngộ này diễn ra trong thời gian thực, một số khác được nhớ lại qua hồi tưởng: thời thơ ấu của anh vào những năm 1960, khi anh cùng gia đình đến làng Paterna nguyên thủy, đi học, tình yêu trưởng thành đầu tiên của anh ở Madrid vào những năm 1980, nỗi đau của sự tan vỡ của mối quan hệ này, viết như một liệu pháp để quên, khám phá điện ảnh, đối mặt với việc không thể tiếp tục quay phim…</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Asier Etxeandia","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Nora Navas","avatar":""},{"name":"Julieta Serrano","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"César Vicente","avatar":""},{"name":"Asier Flores","avatar":""},{"name":"Cecilia Roth","avatar":""},{"name":"Susi Sánchez","avatar":""},{"name":"Raúl Arévalo","avatar":""},{"name":"Pedro Casablanc","avatar":""},{"name":"Julián López","avatar":""},{"name":"Eva Martín","avatar":""},{"name":"Sara Sierra","avatar":""},{"name":"Constancia Céspedes","avatar":""},{"name":"Rosalía","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
