INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-thu-bat-dac-di', 'Cầu thủ bất đắc dĩ', 'Back of the Net', 'https://phimimg.com/upload/vod/20231123-1/9476b2a47d89cb8a003e44ffa8bc4e54.jpg', 'https://phimimg.com/upload/vod/20231123-1/51f33a6e52ea4cb23ee2162133d5f1b2.jpg', '<p>Cô nàng người Mỹ đam mê khoa học chuẩn bị trải qua một mùa hè ở bãi biển đã vô tình bị đưa đến học viện bóng đá Úc và phải giao du với những người nơi đây.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Sofia Wylie","avatar":""},{"name":"Kate Box","avatar":""},{"name":"Christopher Kirby","avatar":""},{"name":"Tiarnie Coupland","avatar":""},{"name":"Ashleigh Ross","avatar":""},{"name":"Yasmin Honeychurch","avatar":""},{"name":"Melissa Bonne","avatar":""},{"name":"Gemma Chua-Tran","avatar":""},{"name":"Trae Robin","avatar":""},{"name":"Raj Labade","avatar":""},{"name":"Nick Bolton","avatar":""},{"name":"Caitlin Foord","avatar":""},{"name":"Keith Stribling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324385);
