INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-hoan-hao', 'Cuộc Hẹn Hoàn Hảo', 'The Perfect Date', 'https://phimimg.com/upload/vod/20231123-1/4cb69bdfb02d26fe7ab2939a50a0a2c0.jpg', 'https://phimimg.com/upload/vod/20231123-1/b47d472f8921a3a1867e86926164678b.jpg', '<p>Để kiếm tiền học đại học, một học sinh trung học tạo ra ứng dụng hẹn hò cho phép cậu sắm vai bạn trai. Nhưng khi cảm xúc thật nhen nhóm, mọi thứ trở nên phức tạp.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Centineo","avatar":""},{"name":"Laura Marano","avatar":""},{"name":"Odiseas Georgiadis","avatar":""},{"name":"Camila Mendes","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Carrie Lazar","avatar":""},{"name":"Alexander Biglane","avatar":""},{"name":"Blaine Kern III","avatar":""},{"name":"Zak Steiner","avatar":""},{"name":"Ty Parker","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"Rhonda Johnson Dents","avatar":""},{"name":"Maureen Brennan","avatar":""},{"name":"Autumn Walker","avatar":""},{"name":"Ivan Hoey Jr.","avatar":""},{"name":"Emily Chatel","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
