INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-quy-nho', 'Những Con Quỷ Nhỏ', 'Little Monsters', 'https://phimimg.com/upload/vod/20231120-1/a31794989da672f5fc3c0f0e24f19bf3.jpg', 'https://phimimg.com/upload/vod/20231120-1/2fdb8d7b213836071e5825025deb9131.jpg', '<p>Một nhạc sĩ đã hết thời hợp sức với một giáo viên và một đứa trẻ thể hiện cá tính để bảo vệ trẻ nhỏ khỏi sự bùng phát bất ngờ của thây ma.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Lupita Nyong''o","avatar":""},{"name":"Alexander England","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Diesel La Torraca","avatar":""},{"name":"Kat Stewart","avatar":""},{"name":"Nadia Townsend","avatar":""},{"name":"Charlie Whitley","avatar":""},{"name":"Chris Bunton","avatar":""},{"name":"Ava Caryofyllis","avatar":""},{"name":"Shia Hamby","avatar":""},{"name":"Kim Thien Doan","avatar":""},{"name":"Caliah Pinones","avatar":""},{"name":"Vivienne Albany","avatar":""},{"name":"Marshall Napier","avatar":""},{"name":"Alan Dukes","avatar":""},{"name":"Felix Williamson","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
