INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-ben-ho', 'Bí Mật Bên Hồ', 'Secrets at the Lake', 'https://phimimg.com/upload/vod/20231120-1/f79302c80bd52323e537fd592c97b55a.jpg', 'https://phimimg.com/upload/vod/20231120-1/aa2c6b8a7f03ecc85e6222eede23df59.jpg', '<p>Trong một lần tiệc tùng quá đà, Katie và hai người bạn không may gây ra tai nạn và bỏ chạy, khiến chồng lẫn hai con nhỏ của Megan Myers mất mạng. Trớ trêu thay, đúng một năm sau đó, gia đình Katie đã vô tình chọn thuê chính căn nhà của Megan làm nơi nghỉ mát. Từ đây, bí mật động trời lâu nay dày vò những người trong cuộc dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicky Whelan","avatar":""},{"name":"Anna Hutchison","avatar":""},{"name":"Alexandria DeBerry","avatar":""},{"name":"Trevor Stines","avatar":""},{"name":"Ricky Garcia","avatar":""},{"name":"Kara Royster","avatar":""},{"name":"Kim DeJesus","avatar":""},{"name":"Giullian Yao Gioiello","avatar":""},{"name":"Jou Jou Papailler","avatar":""},{"name":"Stacie Conard","avatar":""},{"name":"Claudia Coffee","avatar":""},{"name":"Sarah Cleveland","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
