INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-mo-bi-cam-doan', 'Ước Mơ Bị Cấm Đoán', 'Forbidden Dream', 'https://phimimg.com/upload/vod/20231120-1/219e38e3f61ee8450e8a0e2f047419ac.jpg', 'https://phimimg.com/upload/vod/20231120-1/6754be90acf94efc5becf5e564438ed2.jpg', '<p>Một trong những nhân vật quan trọng nhất của lịch sử hoàng gia Hàn Quốc, vua Sejong đã phát triển mối quan hệ 20 năm với kỹ sư kiêm nhà phát minh Jang Yeong-sil, một nhà khoa học thực sự đáng chú ý dựa trên mối quan tâm chung của họ đối với thiên văn học.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Min-sik","avatar":""},{"name":"Han Suk-kyu","avatar":""},{"name":"Shin Goo","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Im Won-hee","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Jeon Yeo-been","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Min Kyung-jin","avatar":""},{"name":"Lee Dong-yong","avatar":""},{"name":"Kim Seung-hoon","avatar":""},{"name":"Kim Seung-tae","avatar":""},{"name":"Choi Jae-sup","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Ryu Ji-hoon","avatar":""},{"name":"Bae Je-gi","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
