INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-bep', 'Nhà Bếp', 'The Kitchen', 'https://phimimg.com/upload/vod/20231120-1/144b85356180a777f7b37aec5ebb2b29.jpg', 'https://phimimg.com/upload/vod/20231120-1/ccc7fd1220688d7e52b2ef09f456613b.jpg', '<p>Năm 1978, ba người vợ của xã hội đen bắt đầu điều hành Hell’s Kitchen. Nhưng các thế lực dữ dằn cả trong và ngoài mafia Ireland đe dọa tước quyền kiểm soát của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melissa McCarthy","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Common","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Jeremy Bobb","avatar":""},{"name":"E.J. Bonilla","avatar":""},{"name":"Wayne Duvall","avatar":""},{"name":"Annabella Sciorra","avatar":""},{"name":"Myk Watford","avatar":""},{"name":"Pamela Dunlap","avatar":""},{"name":"John Sharian","avatar":""},{"name":"Bria","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
