INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-bep', 'Nhà Bếp', 'The Kitchen', 'nhà bếp the kitchen melissa mccarthy tiffany haddish elisabeth moss domhnall gleeson bill camp margo martindale common james badge dale brian d''arcy james jeremy bobb e.j. bonilla wayne duvall annabella sciorra myk watford pamela dunlap john sharian bria ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-rocca', 'Cô Bé Rocca', 'Rocca Changes The World', 'https://phimimg.com/upload/vod/20231120-1/3bb6df1569d163a9220990a84a43d0fc.jpg', 'https://phimimg.com/upload/vod/20231120-1/52962e4688a924fd63a3eed8e2e05c2a.jpg', '<p>Rocca là một cô bé 11 tuổi có mẹ qua đời khi sinh con. Cô đã sống với cha mình, một phi hành gia trên ISS, tại Baikonur Cosmodrome, nơi thay vì đi học bình thường, cô đã trải qua phần lớn chương trình đào tạo phi hành gia, giúp cô trưởng thành và tự tin hơn. Cô được gửi đến Hamburg để sống với bà ngoại. Khi cả phi công và hầu hết hành khách trên chuyến bay của cô đến Hamburg đều bị ngộ độc thực phẩm, cô có thể hạ cánh máy bay, nhưng rời đi trước khi danh tính của cô được biết. Rocca kết bạn với một số người vô gia cư ở địa phương và trở nên lo lắng về cách đối xử của họ với xã hội; cô ấy cũng kết bạn với những người bị ruồng bỏ trong lớp và trở nên lo lắng về việc họ bị bắt nạt như thế nào. \r\n</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Luna Marie Maxeiner","avatar":""},{"name":"Barbara Sukowa","avatar":""},{"name":"Ivan Doan","avatar":""},{"name":"Mina Tander","avatar":""},{"name":"Fahri Yardım","avatar":""},{"name":"Volker Bruch","avatar":""},{"name":"Detlev Buck","avatar":""},{"name":"Cordula Stratmann","avatar":""},{"name":"Natalya Bogdanis","avatar":""},{"name":"Robin Bongarts","avatar":""},{"name":"Bo Hansen","avatar":""},{"name":"Karin Heine","avatar":""},{"name":"Markus Knüfken","avatar":""},{"name":"Marta Laubinger","avatar":""},{"name":"Kailas Mahadevan","avatar":""},{"name":"Lars Nagel","avatar":""},{"name":"Nela Schmitz","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hướ