INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-diet-quy-chuyen-di-cua-anh-em', 'Thanh Gươm Diệt Quỷ: Chuyến đi của anh em', 'Demon Slayer: Brother and Sister Bond', 'https://phimimg.com/upload/vod/20231201-1/7ae23dbe1546e34c5853bfb34d7d09d5.jpg', 'https://phimimg.com/upload/vod/20231201-1/3f545bb593ad60fa3c59bf97f7f8643a.jpg', '<p>Tanjiro thấy gia đình mình bị tàn sát và người sống sót duy nhất, em gái Nezuko Kamado, bị biến thành Ác ma. Tuy nhiên, trước sự ngạc nhiên của anh, Nezuko vẫn bộc lộ những dấu hiệu cảm xúc và suy nghĩ của con người. Từ đó bắt đầu cuộc hành trình tìm kiếm Ác ma đã giết gia đình họ và biến em gái anh trở lại làm người. Một đoạn phim tóm tắt của Kimetsu no Yaiba, bao gồm các tập 1-5 với các cảnh quay bổ sung.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324385);
