INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tinh-ai', 'Trò Chơi Tình Ái', 'Serenity', 'https://phimimg.com/upload/vod/20231120-1/330934472909abd73e8d3144f3a9a5c4.jpg', 'https://phimimg.com/upload/vod/20231120-1/753962f16025da73304daecf5eb3209f.jpg', '<p>Baker Dill (Matthew McConaughey) là một thuyền trưởng thuyền đánh cá đứng đầu một chuyến tham quan yên tĩnh, vùng nhiệt đới có tên là Đảo Plymouth. Tuy nhiên, cuộc sống lặng lẽ của anh ta tan vỡ, tuy nhiên, khi người vợ cũ Karen (Anne Hathaway) theo dõi anh ta với một lời cầu xin tuyệt vọng để được giúp đỡ. Cô cầu xin Dill cứu cô - và con trai nhỏ của họ - từ người chồng mới, bạo lực của cô (Jason Clarke) bằng cách đưa anh ra biển trên một chuyến du ngoạn câu cá, chỉ để ném anh vào những con cá mập và để anh chết. Sự xuất hiện của Karen nhét vào một cuộc sống mà anh ta đã cố gắng quên đi, và khi anh ta vật lộn giữa quyền và sai, thế giới của anh ta đã lao vào một thực tế mới có vẻ như vậy.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Jeremy Strong","avatar":""},{"name":"Charlotte Butler","avatar":""},{"name":"David Butler","avatar":""},{"name":"Rafael Sayegh","avatar":""},{"name":"Michael Richard","avatar":""},{"name":"Robert Hobbs","avatar":""},{"name":"Kenneth Fok","avatar":""},{"name":"Garion Dowds","avatar":""},{"name":"John Whiteley","avatar":""},{"name":"Edeen Bhugeloo","avatar":""},{"name":"Redd Pepper","avatar":""},{"name":"Gunnar Sizemo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
