INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-gap-go-o-ben-xe-phia-nam', 'Cuộc Gặp Gỡ Ở Bến Xe Phía Nam', 'The Wild Goose Lake', 'https://phimimg.com/upload/vod/20231120-1/b9a1e1f89ed577408f80dec00ceb9a2b.jpg', 'https://phimimg.com/upload/vod/20231120-1/e6300bb0f2ce0eaf5cf95910cb2831f1.jpg', '<p>Thủ lĩnh nhóm trộm xe Chu Trạch Nông phải chạy trốn sự truy lùng được treo thưởng một món tiền lớn, khó khăn cứu lấy mình! Mạo hiểm và tình yêu, nhân tính và cứu rỗi, màn \&quot;gặp gỡ\&quot; đặc biệt này sẽ có kết cục thế nào đây?</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hu Ge","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Liao Fan","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Qi Dao","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Zeng Meihuizi","avatar":""},{"name":"Zhang Yicong","avatar":""},{"name":"Chen Yongzhong","avatar":""},{"name":"Li Zhipeng","avatar":""},{"name":"Fu Xiaoxian","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324385);
