INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-o-jangsari', 'Trận Chiến ở Jangsari', 'The Battle of Jangsari', 'https://phimimg.com/upload/vod/20231119-1/6ff1255a5c2e390340c51592ac8f33a8.jpg', 'https://phimimg.com/upload/vod/20231119-1/e6f4e787c52c72d1234ca73d5005c07e.jpg', '<p>Bộ phim đưa chúng ta lên tàu Munsan vào ngày 15 tháng 9 năm 1950, ở đỉnh cao của Chiến tranh Triều Tiên. Đại úy Lee Myeong-jun và đội quân gồm 772 binh sĩ sinh viên của anh ta đang chuẩn bị xâm chiếm bờ biển của Jangsa-ri, bị quân đội Bắc Triều Tiên chiếm đóng, cung cấp một cuộc chia rẽ rất cần thiết cho lực lượng Liên Hợp Quốc trước Trận chiến Incheon. Viết nhanh và bắt buộc – từ chỉ dẫn trong vài ngày đến hai tuần – học sinh trung học cơ sở và trung học phổ thông. bao gồm Choi Sung-Pil và Gi Ha-ryun đã dũng cảm chiến đấu chống lại Triều Tiên để ra bãi biển và thực hiện nhiệm vụ. Nhưng con tàu của họ mắc cạn trong cuộc đổ bộ có nghĩa là họ phải kìm hãm một làn sóng trả đũa khổng lồ ...</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Myung-min","avatar":""},{"name":"Minho","avatar":""},{"name":"Kim Sung-cheol","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Kwak Si-yang","avatar":""},{"name":"Lee Jae-wook","avatar":""},{"name":"Jang Ji-gun","avatar":""},{"name":"Lee Ho-jung","avatar":""},{"name":"Dong Bang-woo","avatar":""},{"name":"George Eads","avatar":""},{"name":"Megan Fox","avatar":""},{"name":"Jung Jong-joon","avatar":""},{"name":"Han Chul-woo","avatar":""},{"name":"Hwang Jae-yeol","avatar":""},{"name":"Kim Jin-wook","avatar":""},{"name":"Kim Min-kyu","avatar":""},{"name":"Lee Cheol-min","avatar":""},{"name":"Yang Jung-gyeong","avatar":""},{"name":"Jang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324385);
