INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-qua-bi-an', 'Món quà bí ẩn', 'Good Sam', 'https://phimimg.com/upload/vod/20231118-1/9a6ddb72493db5690502e3a7b5aa39e2.jpg', 'https://phimimg.com/upload/vod/20231118-1/b81d334d4e5817afa115f98eb2c7e69a.jpg', '<p>Khi theo đuổi câu chuyện về nhân vật bí ẩn tặng cả túi tiền cho những người lạ khắp thành phố New York, cô phóng viên tò mò đã tìm được tình yêu của đời mình.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiya Sircar","avatar":""},{"name":"Chad Connell","avatar":""},{"name":"Marco Grazzini","avatar":""},{"name":"Jesse Camacho","avatar":""},{"name":"Mark Camacho","avatar":""},{"name":"Elana Dunkelman","avatar":""},{"name":"Kelly Hope Taylor","avatar":""},{"name":"Kenny Wong","avatar":""},{"name":"Daniela Sandiford","avatar":""},{"name":"Christina Tannous","avatar":""},{"name":"Ivan Smith","avatar":""},{"name":"Stefanie Nakamura","avatar":""},{"name":"Scott Humphrey","avatar":""},{"name":"Jodie Resther","avatar":""},{"name":"Vince Benvenuto","avatar":""},{"name":"Mylène Dinh-Robic","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324385);
