INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mon-qua-bi-an', 'Món quà bí ẩn', 'Good Sam', 'món quà bí ẩn good sam tiya sircar chad connell marco grazzini jesse camacho mark camacho elana dunkelman kelly hope taylor kenny wong daniela sandiford christina tannous ivan smith stefanie nakamura scott humphrey jodie resther vince benvenuto mylène dinh-robic ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-sat', 'Ngộ Sát', 'Sheep Without a Shepherd', 'https://phimimg.com/upload/vod/20231118-1/87a12068d7f89c0b0565f1572a79e8bd.jpg', 'https://phimimg.com/upload/vod/20231118-1/d306d0639517043567386da0f200decb.jpg', '<p>Nội dung phim xoay quanh cuộc sống của người đàn ông trung niên Lý Duy Kiệt và hành trình che giấu tội giết người của mình để bảo vệ con gái.Chọn một thị trấn bình yên, lấy cô gái xinh đẹp A Ngọc làm vợ, Duy Kiệt có 17 năm sinh sống và làm ăn tại miền bắc Thái Lan. Sau khi mọi thứ ổn định, anh quyết định mở một quán net và giành nhiều thời gian để chăm sóc vợ và con gái. Trong thời gian gần đây, thị trấn xảy ra nhiều biến động, tội phạm ngày càng nhiều và luật pháp luôn dung túng cho tội ác. Một ngày nọ, con gái Duy Kiệt bị con trai tổng thanh tra cưỡng bức, vì bảo vệ con mà anh vô tình đánh chết hắn. Biết rằng pháp luật sẽ không đứng về phía mình nên anh cố gắng che giấu tất cả.</p>', 'Full', 1, 'single', 'completed', 9, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiao Yang","avatar":""},{"name":"Tan Zhuo","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Bian Tianyang","avatar":""},{"name":"Audrey Hui","avatar":""},{"name":"Ye Liu","avatar":""},{"name":"Ming-Shuai Shih","avatar":""},{"name":"Zhang Xiran","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324385);
