INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bikram-tu-bac-thay-yoga-den-toi-pham-tinh-duc', 'Bikram: Từ bậc thầy Yoga đến tội phạm tình dục', 'Bikram: Yogi, Guru, Predator', 'https://phimimg.com/upload/vod/20231118-1/82d51621c71b0ea9229a89781c0ac6d6.jpg', 'https://phimimg.com/upload/vod/20231118-1/da8914f57a1dec39a6d7e5af2fec95d8.jpg', '<p>Phim tài liệu mô tả các thăng trầm của Bikram Choudhury – nhà sáng lập môn yoga nóng – khi đế chế toàn cầu của ông ra đời và các bí mật đen tối bị đưa ra ánh sáng.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Larissa Anderson","avatar":""},{"name":"Francesca Asumah","avatar":""},{"name":"Sarah Baughn","avatar":""},{"name":"Bikram Choudhury","avatar":""},{"name":"John Dowd","avatar":""},{"name":"Mukul Dutta","avatar":""},{"name":"Jafa-Bodden Micki","avatar":""},{"name":"Carla Minnard","avatar":""},{"name":"Richard Nixon","avatar":""},{"name":"Mark Quigley","avatar":""},{"name":"Val Sklar Robinson","avatar":""},{"name":"Mandeep Kaur Sandhu","avatar":""},{"name":"Jakob Schanzer","avatar":""},{"name":"Patrice Simon","avatar":""},{"name":"Liz Winfield","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324385);
