INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bikram-tu-bac-thay-yoga-den-toi-pham-tinh-duc', 'Bikram: Từ bậc thầy Yoga đến tội phạm tình dục', 'Bikram: Yogi, Guru, Predator', 'bikram: từ bậc thầy yoga đến tội phạm tình dục bikram: yogi, guru, predator larissa anderson francesca asumah sarah baughn bikram choudhury john dowd mukul dutta jafa-bodden micki carla minnard richard nixon mark quigley val sklar robinson mandeep kaur sandhu jakob schanzer patrice simon liz winfield ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('code-geass-su-phuc-sinh-cua-lelouch', 'Code Geass : Sự phục sinh của Lelouch', 'Code Geass: Lelouch of the Re;Surrection', 'https://phimimg.com/upload/vod/20231117-1/8b9689dc3945e47568d5dba523a6947a.jpg', 'https://phimimg.com/upload/vod/20231117-1/8f9d9d18779ee10c29d69263dbcd9d08.jpg', '<p>Fukkatsu no Lelouch là câu chuyện nói về sự kiện hai năm sau Zero Requiem, thế giới hòa bình sau sự hy sinh của Lelouch. Nhưng, khi đóng vai trò là thành viên danh dự của Liên đoàn các quốc gia, Nunnally vi Britannia và Zero họ đã bị bắt làm con tin bởi Shalio, lãnh đạo quân sự của Vương quốc Zilkhistan, do chị gái của ông là lãnh đạo tôn giáo của Zilkhistan, Shamna. Vào thời điểm đó CC và Lelouch vi Britannia thì lại đang lang thang khắp nơi, để cùng nhau tìm kiếm một cánh cổng đến Thế giới C để đối mặt với sự bất tỉnh tập thể và Lelouch hoàn toàn, nhưng chỉ là vỏ bọc của chính mình trước đây mà họ không hề hay biết. Sau khi mọi thứ ổn định, Nunnally cầu xin Lelouch ở lại với cô và sống hết mình bên cạnh cô. Lelouch từ chối yêu cầu của cô, tuy nhiên, quyết định thay vì sống cuộc sống bên cạnh CC, khám phá thế giới dưới bút danh mà anh tạo ra, LL. Suzaku tiếp tục với vai trò Zero, và Kallen gia nhập Hiệp sĩ Đen. Câu chuyện sẽ diễn ra như thế nào?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Yukana","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Keiko Toda","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Tetsu Siratori","avatar":""},{"name":"Satomi Arai","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324386);
