INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-cua-chung-ta-hau-truong', 'Hành tinh của chúng ta - Hậu trường', 'Our Planet: Behind The Scenes', 'https://phimimg.com/upload/vod/20231116-1/c422a865293c502c432b4351d6cfdea0.jpg', 'https://phimimg.com/upload/vod/20231116-1/afa33f8d52bdea3e676b2c7b0e7ff959.jpg', '<p>Những năm tháng dành cho việc ghi lại hình ảnh các loài sinh vật trên toàn cầu chắc hẳn sẽ mang đến nhiều cảm xúc. Sau đây là những góc nhìn từ phía hậu trường.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324386);
