INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-hoa-soai-ca', 'Đại Ca Hóa Soái Ca', 'The Dude in Me', 'https://phimimg.com/upload/vod/20231116-1/05133631bc8090687f74bad994c86908.jpg', 'https://phimimg.com/upload/vod/20231116-1/4abbc26ddd153b0f760234775bb00d89.jpg', '<p>Đại Ca Hóa Soái Ca là câu chuyện hoán đổi linh hồn giữa cậu học sinh trung học Dong-hyun và tay xã hội đen máu mặt Pan-soo. Sau một tai nạn bất ngờ, linh hồn của ông chú trung niên Pan-soo tỉnh lại trong thân hình của Dong-hyun. Với thân phận mới, Pan-soo đã quyết định tìm hiểu nguyên nhân của vụ tráo đổi kỳ lạ này, bắt đầu từ vụ tai nạn khiến Dong-hyun rơi từ trên tầng cao xuống.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Jin-young","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Lee Soo-min","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Yoon Song-ah","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Jeong Yun-ha","avatar":""},{"name":"Kim Hyun-mok","avatar":""},{"name":"Jang Jin-hee","avatar":""},{"name":"Oh Yun-su","avatar":""},{"name":"Ji Chan","avatar":""},{"name":"Kwon Hyeok-beom","avatar":""},{"name":"Nam Jin-bok","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Mi So Yun","avatar":""},{"name":"Jung Hyun Cheol","avatar":""},{"name":"Lee P","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
