INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-boi-nam-boi-den-tan-cung-the-gioi-giac-mo', 'Câu lạc bộ bơi nam - Bơi đến tận cùng thế giới - Giấc mơ', 'Road to the World', 'https://phimimg.com/upload/vod/20231129-1/074c113b9c8fea367d320e5bfd4e56a3.jpg', 'https://phimimg.com/upload/vod/20231129-1/d6a111591e474c5f081331f088d41423.jpg', '<p>Haruka, Makoto, Nagisa và Rin tạo thành một liên kết trẻ với tư cách là đội đầu tiên. Mục tiêu là tiến tới cuộc thi cấp quốc gia với nội dung chạy tiếp sức. Họ có một sợi dây ràng buộc là ước mơ. Từ giờ họ hướng đến mục tiêu, biến giấc mơ thành hiện thực. Và câu chuyện của những người trẻ không ngừng &quot;bơi lội&quot; sẽ chuyển sang giai đoạn tiếp theo.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Tatsuhisa Suzuki","avatar":""},{"name":"Tsubasa Yonaga","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Kouki Miyata","avatar":""},{"name":"Jeff Manning","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Ryohei Kimura","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
