INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tuyet', 'Quái Vật Tuyết', 'Snow Monster', 'null', 'https://phimimg.com/upload/vod/20231115-1/08a848cb8185c864093cb9d28b98ae9b.jpg', '<p>Chưa bao giờ điện ảnh Trung Quốc được đánh giá cao trong dòng phim khoa học viễn tưởng, không chỉ vì kịch bản chưa đủ tầm mà kỹ sảo của điện ảnh hoa ngữ cũng chưa đủ xuất sắc để tạo ra một tác phẩm bom tấn. Còn với dòng phim chiếu mạng thì điều đó còn khó hơn rất nhiều, không có kinh phí lớn thì khó có thể làm được các cảnh quay chất lượng. Snow Monster là minh chứng cho điều đó, mặc dù poster của phim được thiết kế rất bắt mắt và chuẩn mực nhưng khi theo dõi thì lại thấy một tác phẩm quá kém chất lượng. Phim hầu hết chỉ nhận đánh giá tiêu cực và rõ ràng không phải tác phẩm đáng để theo dõi.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Juncheng","avatar":""},{"name":"Zhang Yongxian","avatar":""},{"name":"Tang Xin","avatar":""},{"name":"Jiang Yongbo","avatar":""},{"name":"Shaoqiang Xu","avatar":""},{"name":"Jiang Guojun","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Zhang Jingtong","avatar":""},{"name":"Jin Wang","avatar":""},{"name":"Zhao Wenlong","avatar":""},{"name":"Xu Wei","avatar":""},{"name":"Chao Cao","avatar":""},{"name":"Cong Qing","avatar":""},{"name":"Shu Yi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
