INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cuu-shaun-nguoi-ban-ngoai-hanh-tinh', 'Chú Cừu Shaun: Người Bạn Ngoài Hành Tinh', 'A Shaun the Sheep Movie: Farmageddon', 'https://phimimg.com/upload/vod/20231115-1/66cc1b9b67fbccdd095ddb57e53265ef.jpg', 'https://phimimg.com/upload/vod/20231115-1/47f642bd07a6720df23e736cbf4d9ac1.jpg', '<p>Lu-la, một cô bé ngoài hành tinh hết sức đáng yêu rơi từ chiếc phi thuyền không gian xuống trang trại Mossy Bottom. Thế là chú cừu thông minh Shaun cùng những người bạn bắt tay vào công cuộc giúp đỡ để đưa Lu-la về với quê hương mình.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Justin Fletcher","avatar":""},{"name":"John Sparkes","avatar":""},{"name":"Amalia Vitale","avatar":""},{"name":"Kate Harbour","avatar":""},{"name":"David Holt","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Richard Webber","avatar":""},{"name":"Emma Tate","avatar":""},{"name":"Simon Greenall","avatar":""},{"name":"Chris Morrell","avatar":""},{"name":"Joe Sugg","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Tim Hands","avatar":""},{"name":"Joseph Balderrama","avatar":""},{"name":"Ron Halpern","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324386);
