INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-long-bat-bai', 'Cửu Long Bất Bại', 'Invincible Dragon', 'https://phimimg.com/upload/vod/20231115-1/bdf575f1b45bb31b1d5a45eb51a3d4f7.jpg', 'https://phimimg.com/upload/vod/20231115-1/3d9ddd32ddb3e35f0bab5a4b43835c71.jpg', '<p>Một cao nhân với hình xăm rồng liên tục giúp sức cho cảnh sát phá vỡ những vụ án lắt léo. Anh dần trở thành một người được xã hội săn đón và ngưỡng mộ. Chính sự đón nhận đó đã vô tình lôi anh vào một vụ án nghiêm trọng hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Zhang Jin","avatar":""},{"name":"Anderson Silva","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"Annie Liu","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"JuJu Chan","avatar":""},{"name":"Endy Chow","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Tsun-Hung Liu","avatar":""},{"name":"Vernon Fong","avatar":""},{"name":"Loletta Lee","avatar":""},{"name":"Steve Wong Ka-Keung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
