INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuu-long-bat-bai', 'Cửu Long Bất Bại', 'Invincible Dragon', 'cửu long bất bại invincible dragon zhang jin anderson silva kevin cheng annie liu stephy tang juju chan endy chow hugo ng lam suet richard ng carl ng tsun-hung liu vernon fong loletta lee steve wong ka-keung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-an-dat', 'Cuộc Đời Ẩn Dật', 'A Hidden Life', 'https://phimimg.com/upload/vod/20231114-1/91690145a285248e43910d9d62cc1d1b.jpg', 'https://phimimg.com/upload/vod/20231114-1/64c42fd4914e8ed0c60cc99254330b35.jpg', '<p>Bộ phim mô tả cuộc đời của Franz Jägerstätter, một thanh niên người Áo và người Công giáo sùng đạo , anh đang có một cuộc sống êm ả và hạnh phúc bên cạnh người vợ xinh đẹp và câu con trai bé nhỏ . Khi chiến tranh bùng nổ , anh đã kiên quyết từ chối chiến đấu cho Đức quốc xã trong Thế chiến II để có thể ở bên gia đình bé nhỏ của mình . Thế nhưng quân đội Đức Quốc Xã không dễ dàng buông tha cho anh như vây , họ dùng mọi cách để ép anh tòng quân , thậm chí dùng đến những nhũ hình răn đe mạnh mẽ nhất . Franz Jägerstätter phải cố gắng mọi cách để thoái khỏi vòng vây của Đức Quốc Xã và quay trở về với mái ấm nhỏ bé có người vợ và cậu bé kháu khỉnh đang đợi anh.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"August Diehl","avatar":""},{"name":"Valerie Pachner","avatar":""},{"name":"Maria Simon","avatar":""},{"name":"Karin Neuhäuser","avatar":""},{"name":"Tobias Moretti","avatar":""},{"name":"Ulrich Matthes","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"Michael Nyqvist","avatar":""},{"name":"Franz Rogowski","avatar":""},{"name":"Karl Markovics","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Wolfgang Michael","avatar":""},{"name":"Johannes Krisch","avatar":""},{"name":"Martin Wuttke","avatar":""},{"name":"Johan Leysen","avatar":""},{"name":"Waldemar Kobus","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324386);
