INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-tham-doan', 'Bồi thẩm đoàn', 'Juror 8', 'https://phimimg.com/upload/vod/20231113-1/78a68bde96d84a8a26cb8f2c565e919c.jpg', 'https://phimimg.com/upload/vod/20231113-1/0cbe7b0faa9775124eed8bb559dd1947.jpg', '<p>Tại phiên tòa đầu tiên có bồi thẩm đoàn trong lịch sử Hàn Quốc, vụ xét xử tội giết mẹ tưởng chừng đơn giản bỗng trở nên phức tạp hơn khi một bồi thẩm viên nảy sinh nghi ngờ.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon So-ri","avatar":""},{"name":"Park Hyung-sik","avatar":""},{"name":"Baek Soo-jang","avatar":""},{"name":"Cha Mi-kyeong","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Seo Jeong-yeon","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Cho Soo-hyang","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Seo Jin-won","avatar":""},{"name":"Lee Yeong-jin","avatar":""},{"name":"Shim Dal-gi","avatar":""},{"name":"Lee Yong-i","avatar":""},{"name":"Kim Hak-sun","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Yoo Soon-woong","avatar":""},{"name":"Yeom Hye-ran","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324386);
