INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-hinh-nom-hoa-bi-ngan', 'Truyền Thuyết Hình Nộm: Hoa Bỉ Ngạn', 'Puppet Prince', 'https://phimimg.com/upload/vod/20231113-1/f42fefdd875ec8a1ea744efbdb0f04d2.jpg', 'https://phimimg.com/upload/vod/20231113-1/fdbc967ebc082df766803289798fc10b.jpg', '<p><strong>Truyền Thuyết Hình Nộm: Hoa Bỉ Ngạn</strong> Puppet Prince 2021 Full HD Vietsub Thuyết Minh Shishi vốn ngưỡng mộ anh trai Feihe, và Feihe sau đó đã biến mất khi cả hai phát triển Con rối hoàn hảo, và con rối cũng biến mất. Cô giáo gặp một người đàn ông tại dinh thự của lãnh chúa với thiết kế độc quyền của Feihe ở trên vai, nhưng tiếc là không thấy anh ta đâu.<br/>Mang theo mô hình là một con rối hoàn hảo do Feihe làm, sau đó nó được sử dụng bởi quan chức quyền lực Jiang Xiangbang để thay thế lãnh chúa thành phố thực sự Ji Yechen để cai trị thành phố hoàng gia. Hắn bẩm sinh không thấy màu sắc, chỉ nhìn sư phụ là có màu sắc, thật kỳ lạ.<br/>Để tìm ra manh mối của Feihe, Shishiye chạy tới dinh thự của lãnh chúa thành phố, nhầm lẫn Ji Yechen là cận vệ riêng của lãnh chúa, và bắt buộc phải cúi đầu để lấy thông tin từ lãnh chúa. Hai người họ đã gặp một số sự cố kỳ lạ, và với sự giúp đỡ, họ đã có ấn tượng tốt về nhau.<br/>Cô nghĩ rằng lãnh chúa đã giết chết đàn anh của mình nên đã đi ám sát, nhưng lại phát hiện ra lãnh chúa chính là cận vệ vĩ đại. Khi Xiangbang đến để truy sát họ, cả hai đã vô tình rơi vào cung điện dưới lòng đất, nhưng họ bị sốc khi thấy Feihe và lãnh chúa Zhencheng đang bị giam giữ. Tình cảm và vận mệnh của họ đang bị thử thách với nhiều bất ngờ.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ji Chen","avatar":""},{"name":"He Nan","avatar":""},{"name":"Wang Luojia","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Liu Yonggang","avatar":""},{"name":"Naomen Eerdeni","avatar":""},{"name":"Han Mengwu","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324386);
