INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dam', 'Ma Đầm', 'In Fabric', 'https://phimimg.com/upload/vod/20231113-1/8988b2fb96bf54b6732a689bd53d2fe4.jpg', 'https://phimimg.com/upload/vod/20231113-1/7baabd0123ff8cb004296f60df78c7cf.jpg', '<p>Váy Đỏ Sát Nhân lấy bối cảnh vào thời điểm cuối năm các cửa hàng thời trang ở Anh Quốc mở ra các chương trình đại hạ giá. Nhưng riêng ở cửa tiệm “Dentley and Soper”, có một sự thật đằng sau việc đại hạ giá này. Nó nằm ở chính chiếc đầm màu đỏ nổi bật đang được bày bán, chờ đợi nạn nhân tiếp theo của mình, vì khác với những chiếc đầm thông thường, một khi bạn đã mặc vào thì chắc chắn bạn sẽ không bao giờ có thể thoát khỏi nó.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Sidse Babett Knudsen","avatar":""},{"name":"Julian Barratt","avatar":""},{"name":"Richard Bremmer","avatar":""},{"name":"Fatma Mohamed","avatar":""},{"name":"Gwendoline Christie","avatar":""},{"name":"Hayley Squires","avatar":""},{"name":"Caroline Catz","avatar":""},{"name":"Jaygann Ayeh","avatar":""},{"name":"Steve Oram","avatar":""},{"name":"Leo Bill","avatar":""},{"name":"Barry Adamson","avatar":""},{"name":"Susanna Cappellaro","avatar":""},{"name":"Anthony Adjekum","avatar":""},{"name":"Terry Bird","avatar":""},{"name":"Sara Dee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324386);
