INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-cuu-long-thanh-trai', 'Diệp Vấn: Cửu Long Thành Trại', 'Ip Man and Four Kings', 'https://phimimg.com/upload/vod/20231113-1/2fe3a12ac8f2e818d1bd348117d6e0e3.jpg', 'https://phimimg.com/upload/vod/20231113-1/51e5337feea4014b0179d53e797e7e9c.jpg', '<p>Bộ phim Diệp Vấn: Cửu Long Thành Trại – IP Man And Four Kings là bộ phim điện ảnh được chỉ đạo sản xuất bởi đạo diễn Phó Lợi Vĩ với các diễn viên chính như Đường Văn Long, Lâu Nam Quang, Lâm Phong Diệp, Triệu Lâm, Trần Ngọc Dũng,.. Diệp Vấn: Thành Cửu Long lấy bối cảnh vào những năm 1950, có một lượng lớn các võ sĩ đã đến HongKong để mở phòng tập đấm bốc. Trong đó Diệp Vấn (Đường Văn Long) là một võ sĩ vô danh không có tiếng tăm gì nổi bật đã làm cho Trịnh Đức Long (Lâm Phong Diệp đóng) chú ý. Trịnh Đức Long sợ rằng Diệp Vấn sẽ là mối đe dọa của chính bản thân mình nên đã gán cho Diệp Vấn tội diệt môn và hơn thế nữa hắn còn muốn mượn tay cảnh sát để tiêu diệt Diệp Vấn. Liệu rằng âm mưu độc ác của Trịnh Đức Long có thực hiện được và đến cuối cùng tội ác của hắn có được đưa ra ánh sáng?</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Michael Tong","avatar":""},{"name":"Lin Fengye","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Zhao Lin","avatar":""},{"name":"Chen Yuyong","avatar":""},{"name":"Li Huo-Huo","avatar":""},{"name":"Zheng Liuzhi","avatar":""},{"name":"Li Peize","avatar":""},{"name":"Shi Chenwei","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
