INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rambo-hoi-ket-dam-mau', 'Rambo: Hồi Kết Đẫm Máu', 'Rambo: Last Blood', 'https://phimimg.com/upload/vod/20231113-1/ad76015903ea836ff179c08bcf9a7aec.jpg', 'https://phimimg.com/upload/vod/20231113-1/e8095643fda2e780d18028244ea4dbc1.jpg', '<p>“Hồi kết đẫm máu” sẽ tiếp nối hành trình sử thi của Rambo khi ông đã dần ổn định, tận hưởng cuộc sống bình lặng bên gia đình tại một trang trại ở Arizona. Mọi chuyện đều đang diễn ra tốt đẹp cho đến khi Gabriela hay tin về cha ruột của mình và cô quyết định đi tìm người cha tệ bạc ấy để hỏi rõ lý do vì sao năm xưa ông đã bỏ rơi cô. Mặc cho Maria và Rambo ngăn cản quyết liệt, cô gái trẻ vẫn bất chấp sang Mexico.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Sergio Peris-Mencheta","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"Yvette Monreal","avatar":""},{"name":"Joaquín Cosío","avatar":""},{"name":"Pascacio López","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"Nicholas Wittman","avatar":""},{"name":"Jessica Madsen","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Fenessa Pineda","avatar":""},{"name":"Marco de la O","avatar":""},{"name":"Álvaro Flores","avatar":""},{"name":"Úrsula Murayama","avatar":""},{"name":"Atanas Sre","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
