INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-dep-troi-trong-khu-pho', 'Một Ngày Đẹp Trời Trong Khu Phố', 'A Beautiful Day in the Neighborhood', 'https://phimimg.com/upload/vod/20231114-1/65b7ed2034956b95e4e32452da40501b.jpg', 'https://phimimg.com/upload/vod/20231114-1/6ed32a8feebc0d221a6931f396cac599.jpg', '<p>Tom Junod, một nhà báo đoạt nhiều giải thưởng nhưng có tính hay hoài nghi đã chấp nhận trong niềm ghen tỵ khi nhận lời viết một bài về tiểu sử về Fred Rogers – một biểu tượng truyền hình nước Mỹ được nhiều người yêu mến. Nhờ đó anh ta đã vượt qua sự hoài nghi, học cách biết cảm thông và cả sự khuôn phép, lễ nghi, tính lịch sự từ “người hàng xóm” đáng mến nhất nước Mỹ này.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Matthew Rhys","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Susan Kelechi Watson","avatar":""},{"name":"Maryann Plunkett","avatar":""},{"name":"Enrico Colantoni","avatar":""},{"name":"Wendy Makkena","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Noah Harpster","avatar":""},{"name":"Carmen Cusack","avatar":""},{"name":"Kelley Davis","avatar":""},{"name":"Christine Lahti","avatar":""},{"name":"Maddie Corman","avatar":""},{"name":"Daniel Krell","avatar":""},{"name":"Jon L Peacock","avatar":""},{"name":"Gretchen Koerner","avatar":""},{"name":"Gav","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324386);
