INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-my-va-can-sa', 'Nước Mỹ và cần sa', 'Grass Is Greener', 'https://phimimg.com/upload/vod/20231114-1/69dbc12d8b71f3cc1d9f671c34bf1dee.jpg', 'https://phimimg.com/upload/vod/20231114-1/f4c06286cdf08f0ffab7bb094f1caf59.jpg', '<p>Cần sa khiến jazz và hip-hop thăng hoa, rồi châm ngòi cuộc chiến ma túy đẫm mùi bất công chủng tộc. Các chuyên gia khám phá mối liên hệ phức tạp giữa nước Mỹ và cần sa.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Snoop Dogg","avatar":""},{"name":"B-Real","avatar":""},{"name":"Damian Marley","avatar":""},{"name":"Killer Mike","avatar":""},{"name":"Chuck D","avatar":""},{"name":"Darryl McDaniels","avatar":""},{"name":"Doug E. Fresh","avatar":""},{"name":"Sen Dog","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324386);
