INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-chi-diem', 'Kẻ Chỉ Điểm', 'The Informer', 'https://phimimg.com/upload/vod/20231114-1/053fe17a670598de22798f63c483c922.jpg', 'https://phimimg.com/upload/vod/20231114-1/839dd45bbc424915f609509bdb97e6c0.jpg', '<p>Pete Koslow, cuộc sống đáng mơ ước của anh bỗng nhiên bị đảo lộn khi anh ta bị tống giam sau một cuộc chiến để bảo vệ vợ mình. Koslow đã được trao cơ hội để được trả tự do sớm hơn bằng cách trở thành đặc vụ hoạt động bí mật cung cấp thông tin cho FBI. Và ngoài ra nhiệm vụ của anh còn là sử dụng tất cả khả năng, cũng như kỹ năng bí mật của mình để hạ gục trùm tội phạm buôn bán ma túy đá mạnh nhất của Ba Lan ở New York. Trong bước cuối để chạm đến tự do, Koslow phải trở lại nhà tù Bale Hill, nơi mà anh cố gắng để rời khỏi cũng là nơi mà nhiệm vụ của anh đi vào gấp rút khi một thỏa thuận buôn bán ma túy gặp trục trặc và anh bị nghi ngờ. Tuy nhiên, trên con đường tìm kiếm tự do., không may một cảnh sát NYPD bí mật đã bị thiệt mạng, Koslow thấy mình gần như bị cuốn vào cuộc chiến của FBI và băng đảng tội phạm.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Common","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Ruth Bradley","avatar":""},{"name":"Eugene Lipinski","avatar":""},{"name":"Martin McCann","avatar":""},{"name":"Mateusz Kościukiewicz","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Matthew Marsh","avatar":""},{"name":"Karma Meyer","avatar":""},{"name":"Janusz Sheagall","avatar":""},{"name":"Srbo Markovic","avatar":""},{"name":"Ignacy Rybarczyk","avatar":""},{"name":"Alma Di Stefano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
