INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-doi-mat-cha-toi-cau-chuyen-ve-ronda-rousey', 'Qua đôi mắt cha tôi: Câu chuyện về Ronda Rousey', 'The Ronda Rousey Story: Through My Father''s Eyes', 'https://phimimg.com/upload/vod/20231115-1/3ca3d1ab9b020251a119acfdef277ad5.jpg', 'https://phimimg.com/upload/vod/20231115-1/4f49cbebd889e390eaaffa3e9db2a58e.jpg', '<p>Bộ phim tài liệu xoay quanh Ronda Rousey – cựu quán quân Olympic và UFC – trên con đường đến đỉnh vinh quang trong giới võ thuật tổng hợp.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ronda Rousey","avatar":""},{"name":"Pete Antico","avatar":""},{"name":"Gary Stretch","avatar":""},{"name":"Gene LeBell","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324386);
