INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ba-ho-diem-thu-huong', 'Đường Bá Hổ, Điểm Thu Hương', 'Flirting Scholar From The Future', 'https://phimimg.com/upload/vod/20231115-1/0f1f36b00cedeeb3de501a874b1d686d.jpg', 'https://phimimg.com/upload/vod/20231115-1/650f0cf7bb4d78ed27461b490d47da2c.jpg', '<p>Bá Hổ, Hạo Nam và Bài Cốt là bạn thân từ nhỏ, cả ba đều là fan của bộ phim “Đường Bá Hổ điểm Thu Hương”, xem từ nhỏ đến lớn. Sau khi trưởng thành, Bá Hổ làm thám tử, Hạo Nam làm nhân viên phục vụ ở bãi đỗ xe, còn Bài Cốt lại trở thành một nhà phát minh không có tên tuổi. Trùng hợp, cỗ máy thời gian mà Bài Cốt chế tạo đã hút ba người vào trong bộ phim “Đường Bá Hổ điểm Thu Hương”</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chan Ho-Man","avatar":""},{"name":"Natalis Chan","avatar":""},{"name":"Fiona Zhen","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Cheng Pei-pei","avatar":""},{"name":"Wang Chunyuan","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Sabrina Qiu","avatar":""},{"name":"Yun QianQian","avatar":""},{"name":"Ye Xiangming","avatar":""},{"name":"Gui Jingjing","avatar":""},{"name":"Wang Xinyao","avatar":""},{"name":"Rainky Wai","avatar":""},{"name":"Alex Lam Chi-Sin","avatar":""},{"name":"Jason Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
