INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nancy-drew-va-cau-thang-bi-mat', 'Nancy Drew và Cầu Thang Bí Mật', 'Nancy Drew and the Hidden Staircase', 'https://phimimg.com/upload/vod/20231115-1/94f528b462be2f8a1ec860abce447da4.jpg', 'https://phimimg.com/upload/vod/20231115-1/528cbbcf7c1d96b7a22cf09e63a41ae1.jpg', '<p>Nancy Drew, một học sinh trung học thông minh có thiên hướng quan sát và suy luận nhạy bén, tình cờ gặp phải sự ám ảnh của một ngôi nhà địa phương. Là một người ngoài cuộc đang vật lộn để hòa nhập với môi trường xung quanh mới, Nancy và những người bạn của cô bắt đầu giải quyết bí ẩn, kết bạn mới và thiết lập vị trí của họ trong cộng đồng.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophia Lillis","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Linda Lavin","avatar":""},{"name":"Zoë Renee","avatar":""},{"name":"Mackenzie Graham","avatar":""},{"name":"Laura Slade Wiggins","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Jesse C. Boyd","avatar":""},{"name":"Jay DeVon Johnson","avatar":""},{"name":"Andrew Matthew Welch","avatar":""},{"name":"Jon Briddell","avatar":""},{"name":"Josh Daugherty","avatar":""},{"name":"Evan Castelloe","avatar":""},{"name":"Jennifer Riker","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324386);
