INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bao-chuyen-te-nhi', 'Cảnh Báo Chuyện Tế Nhị', 'Park Na-rae: Glamour Warning', 'https://phimimg.com/upload/vod/20231113-1/1bf1a364e76391a1b5b9ef801b327a39.jpg', 'https://phimimg.com/upload/vod/20231113-1/d44907198218de1a34c17295a8437d4a.jpg', '<p>Diễn viên hài được yêu thích của Hàn Quốc và nhân vật chị đại được yêu thích nói về tình dục, các mối quan hệ và cuộc sống của người nổi tiếng. Và cô ấy hỗn xược và bẩn thỉu hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Na-rae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
