INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-dc-nguoi-doi-va-van-de-dai-gia-dinh', 'LEGO DC:  Người Dơi Và Vấn Đề Đại Gia Đình', 'Lego DC Batman: Family Matters', 'https://phimimg.com/upload/vod/20231113-1/654947e41640150e936b766bda5c47fe.jpg', 'https://phimimg.com/upload/vod/20231113-1/11181949396be177b6a8300248900ba3.jpg', '<p>Sự nghi ngờ tăng cao sau khi Batman, Batgirl, Robin và các siêu anh hùng khác của DC nhận được những lời mời bí ẩn. Tuy nhiên, các giá trị gia đình vẫn phải bền chặt khi Batman và nhóm của anh chạm trán với Red Hood phản diện, kẻ bị ám ảnh bởi việc tiêu diệt Bat-gia đình và toàn bộ Thành phố Gotham.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2019, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Troy Baker","avatar":""},{"name":"Jason Spisak","avatar":""},{"name":"Will Friedle","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Scott Menville","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Christian Lanz","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Cam Clarke","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"André Sogliuzzo","avatar":""},{"name":"Jake Green","avatar":""},{"name":"Josh Keaton","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"Fred Tatasciore","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
