INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhom-nhac-parchis-phim-tai-lieu', 'Nhóm nhạc Parchís: Phim tài liệu', 'Parchís: the Documentary', 'https://phimimg.com/upload/vod/20231113-1/780dc50933fdfa40a6f93cdb40e5bce8.jpg', 'https://phimimg.com/upload/vod/20231113-1/6b001b9eeda923a43ca0beac8566fcfe.jpg', '<p>Bộ phim nói về Parchís, nhóm nhạc thiếu nhi ở Tây Ban Nha. Họ gặt hái thành công chưa từng có với nhiều bài hát lọt Top 10 và một vài bộ phim đình đám vào thập niên 80.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Constantino ''Tino'' Fernández Fernández","avatar":""},{"name":"Yolanda Ventura","avatar":""},{"name":"Gemma Termes Prat","avatar":""},{"name":"Francisco ''Frank'' Díaz","avatar":""},{"name":"David Muñoz Forcadas","avatar":""},{"name":"Ángel Arroyo","avatar":""},{"name":"Antoni Planas","avatar":""},{"name":"Eva Mariol","avatar":""},{"name":"Imma Cabecerans","avatar":""},{"name":"Joaquín Oristrell","avatar":""},{"name":"Jorge Lérida","avatar":""},{"name":"José Viruete","avatar":""},{"name":"Marta Mi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324386);
