INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-the-thanh-xa', 'Song Thế Thanh Xà', 'Green Snake', 'https://phimimg.com/upload/vod/20231112-1/c318a3b06b369ceb8a42be69ab10fcd1.jpg', 'https://phimimg.com/upload/vod/20231112-1/31351feb9e77994f2c0ede4d637796af.jpg', '<p>Bộ phim xoay quanh nhân vật Thanh Xà là một con rắn hóa thành người, bộ phim nói về việc Thành Xà đã bị người vu oan giật chồng, và đã bị đánh trọng thương sau đó bị bắt đi, nhưng sự thật dần được vén màn và mọi người lên kế hoạch giải cứu cô ấy. Liệu bộ phim sẽ đến đâu ? Hãy cùng xem Phim nhé</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Jiaming","avatar":""},{"name":"Sheng Nan","avatar":""},{"name":"Dong Liwuyou","avatar":""},{"name":"Yuan Yuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324386);
