INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-co-nhu-la-mo', 'Đời Có Như Là Mơ', 'Isn''t It Romantic', 'https://phimimg.com/upload/vod/20231112-1/fa932e51c6ea33d42602cd4f264eaf27.jpg', 'https://phimimg.com/upload/vod/20231112-1/114d0558fca084a15ebf1c3a2a9b878b.jpg', '<p>Tỉnh dậy sau chấn thương đầu, nữ kiến trúc sư căm ghét phim hài lãng mạn bỗng thấy cuộc sống tẻ nhạt của mình trở thành bản tình ca hài hước, khuôn sáo và đầy màu sắc.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rebel Wilson","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Priyanka Chopra Jonas","avatar":""},{"name":"Betty Gilpin","avatar":""},{"name":"Brandon Scott Jones","avatar":""},{"name":"Tom Ellis","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Jay Oakerson","avatar":""},{"name":"Michelle Buteau","avatar":""},{"name":"Alex Kis","avatar":""},{"name":"Rao Rampilla","avatar":""},{"name":"Marcus Choi","avatar":""},{"name":"Hugh Sheridan","avatar":""},{"name":"Luciano Acuna Jr.","avatar":""},{"name":"Raymond Anthony Thomas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
