INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-xa-duyen-khoi', 'Bạch Xà: Duyên Khởi', 'White Snake', 'https://phimimg.com/upload/vod/20231112-1/f5a0c3b7070377cb3623b3ff08049085.jpg', 'https://phimimg.com/upload/vod/20231112-1/16d785fdee34b5b2daa17500002ca3cd.jpg', '<p>Phim lấy bối cảnh những năm cuối thời Đường, quốc sư vì mối hận với xà tộc nên đã phát động dân chúng bắt rắn. Bạch Xà - Tiểu Bạch trên đường ám sát quốc sư không may mất trí nhớ, được người bắt rắn A Tuyên cứu giúp, A Tuyên chính là tiền kiếp của Hứa Tiên. &nbsp;Dưới sự giúp đỡ của A Tuyên, Tiểu Bạch bắt đầu dấn thân vào con đường mạo hiểm tìm lại kí ức. Hai người dần dần nảy sinh tình cảm với nhau, thế nhưng lúc này thân phận xà yêu của nàng cũng được hé lộ. Người và yêu vốn khác biệt, liệu họ có vượt qua được thử thách này?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Zhe","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Xiaoxi Tang","avatar":""},{"name":"Liu Ziling","avatar":""},{"name":"Zhang Yaohan","avatar":""},{"name":"Zheng Xiaopu","avatar":""},{"name":"Boheng Zhang","avatar":""},{"name":"He Zhang","avatar":""},{"name":"Cheng Ma","avatar":""},{"name":"Cheng Yin","avatar":""},{"name":"Chen Linsheng","avatar":""},{"name":"Hui Long","avatar":""},{"name":"Lin Qiang","avatar":""},{"name":"Zhang Bin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324386);
