INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thay-doi-cuoc-choi', 'Người thay đổi cuộc chơi', 'The Game Changers', 'https://phimimg.com/upload/vod/20231111-1/e047a01a62c0ea51a5c9e543640569d0.jpg', 'https://phimimg.com/upload/vod/20231111-1/398aecd33c6f4153ae75c7b98d20e899.jpg', '<p>Gặp gỡ các nhà khoa học có tầm nhìn và vận động viên hàng đầu, võ sĩ UFC thực thi nhiệm vụ tìm kiếm chế độ ăn tối ưu giúp con người đạt được hiệu suất lẫn sức khỏe tốt.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Wilks","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Patrik Baboumian","avatar":""},{"name":"Scott Jurek","avatar":""},{"name":"Dotsie Bausch","avatar":""},{"name":"Tia Blanco","avatar":""},{"name":"Nimai Delgado","avatar":""},{"name":"Rip Esselstyn","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324386);
