INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot', 'Đốt', 'Burn', 'https://phimimg.com/upload/vod/20231111-1/61789ef889457b85101ba46e34b7cd4a.jpg', 'https://phimimg.com/upload/vod/20231111-1/e5a966cd0d85bdd220401e77ced3b36b.jpg', '<p>Cô nhân viên trạm xăng cô đơn, bấp bênh Melinda cảm thấy mệt mỏi vì bị lu mờ bởi Sheila, người đồng nghiệp hướng ngoại, tự tin hơn của cô. Khi trạm xăng bị Billy, một người đàn ông tuyệt vọng đang cần tiền gấp, chĩa súng vào trạm xăng, Melinda tìm cơ hội để kết nối với tên cướp, bất kể ai bị thương.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tilda Cobham-Hervey","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Shiloh Fernandez","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"James Devoti","avatar":""},{"name":"Robert Figueroa","avatar":""},{"name":"John D. Hickman","avatar":""},{"name":"Wayne Pyle","avatar":""},{"name":"Winter-Lee Holland","avatar":""},{"name":"Steve Garfanti","avatar":""},{"name":"Malina Moye","avatar":""},{"name":"Angel Valle Jr.","avatar":""},{"name":"Rob Figueroa","avatar":""},{"name":"Doug Motel","avatar":""},{"name":"Keith Leonard","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324386);
