INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-14-le-hoi-hai-tac', 'Đảo Hải Tặc 14: Lễ Hội Hải Tặc', 'One Piece: Stampede', 'https://phimimg.com/upload/vod/20231111-1/868387abd36f75a62c4288f55ef3d3ec.jpg', 'https://phimimg.com/upload/vod/20231111-1/e1f9cc3bf7362db210bd184ecd0f4ac0.jpg', '<p>Băng Mũ Rơm cùng Luffy và vô số hải tặc trên thế giới nhận lời mời đến lễ hội Hải Tặc để Tranh đoạt chìa khóa dẫn đến kho báu Vua Hải tặc do Buena Festa tổ chức. Ngay cả tên quái vật Douglas Bullet biệt danh &quot;Hậu duệ của quỷ cũng tham chiến. Hơn thế nữa, với mong muốn tóm gọn Hải tặc, đội ngũ Hải Quân cũng bí mật tham gia. Những thế lực mạnh nhất đều góp mặt trong đại chiến. Cái kết nào sẽ xảy đến và liệu còn nhân vật bất ngờ nào xuất hiện không?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuki Yao","avatar":""},{"name":"Cho","avatar":""},{"name":"Tsutomu Isobe","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Mahito Ohba","avatar":""},{"name":"Rino Sashihara","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Yusuke Sa","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id