INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('adam-devine-khoanh-khac-tuyet-voi-nhat', 'Adam Devine: Khoảnh Khắc Tuyệt Vời Nhất', 'Adam Devine: Best Time of Our Lives', 'https://phimimg.com/upload/vod/20231111-1/45275773270ad7ce1906918759833a4f.jpg', 'https://phimimg.com/upload/vod/20231111-1/847994d805f88afec7dc5da2bcf59f8c.jpg', '<p>Diễn viên hài được giới phê bình đánh giá cao, Adam Devine, biết rằng lớn lên thật tệ hại và ở đây để cho bạn biết lý do tại sao. Được quay trước một ngôi nhà chật kín người tại Nhà hát Orpheum ở quê hương Omaha, Nebraska, bộ phim hài đặc biệt mới trên Netflix của Devine sẽ mang đến một câu chuyện hài hước về những phần tồi tệ nhất của quá trình trưởng thành bao gồm tuổi dậy thì, sự phán xét của cha mẹ và suýt chết vào ngày sinh nhật thứ 21 của bạn.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Devine","avatar":""},{"name":"Andrew Santino","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
