INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoi-chet-choc', 'Chuỗi Chết Chóc', 'Kill Chain', 'https://phimimg.com/upload/vod/20231113-1/307e05530e21341c2a1f6fe95fd94835.jpg', 'https://phimimg.com/upload/vod/20231113-1/bb948b4dc8491fe40b7db3b0f816058e.jpg', '<p>Một vụ nổ súng trong phòng khách sạn giữa hai sát thủ khởi động một đêm dài, nơi các thi thể rơi xuống như quân domino, khi chúng tôi theo một chuỗi cảnh sát quanh co, bọn côn đồ, kẻ tấn công, một nữ Fatale và một cựu lính đánh thuê thông qua một vụ giết người, phản bội, trả thù và cứu chuộc</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Anabelle Acosta","avatar":""},{"name":"Enrico Colantoni","avatar":""},{"name":"Ryan Kwanten","avatar":""},{"name":"Angie Cepeda","avatar":""},{"name":"Eddie Martinez","avatar":""},{"name":"Alimi Ballard","avatar":""},{"name":"Jon Mack","avatar":""},{"name":"Luna Baxter","avatar":""},{"name":"Pedro Calvo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
