INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-hoang-hon-dao', 'Võ Lâm: Hoảng Hồn Đao', 'Soul Knife', 'https://phimimg.com/upload/vod/20231113-1/9e24acb4634221784f300096ae65cc69.jpg', 'https://phimimg.com/upload/vod/20231113-1/005de6ba02567ab624c01c8170c3ef51.jpg', '<p>Tianyinmen là một trường phái võ thuật kiểu phương Tây. Đó là một môn võ thuật. Nó có giá trị hơn cho các giao dịch tiền. Hàng năm ca sĩ cửa sẽ thu thập bảo bối đẳng cấp thế giới để tổ chức &quot;tiệc hội pháo hoa&quot;. Triển lãm pháo hoa đã tổ chức một cuộc đấu giá kéo dài ba ngày. Có hàng ngàn viên ngọc Quan Âm và những thứ tưởng tượng khác nên hàng năm có rất nhiều sông hồ và các doanh nhân giàu có đến đấu giá. Tuy nhiên, màn trình diễn pháo hoa năm nay đặc biệt gây chú ý bởi nữ thần võ thuật “linh dao”; vốn im lặng hàng trăm năm nay đã xuất hiện trong “Lễ hội pháo hoa”.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zea Min","avatar":""},{"name":"Deric Wan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
