INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien', 'Bao Thanh Thiên', 'Justice Bao', 'null', 'https://phimimg.com/upload/vod/20231113-1/f76656201b9bf55ff2e7ee9aa1d57cc7.jpg', '<p>Bộ phim nói về nhân vật Bao Thanh Thiên trong cuốn tiểu thuyết nổi tiếng của lịch sử Trung Quốc cổ đại. Bên cạnh việc giữ nguyên cốt truyện, bộ phim có thêm những chi tiết ma thuật, kỳ bí. Bộ phim tập trung vào quá trình vào xử án của Bao thanh thiên cùng với những tình tiết ly kỳ</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Weide Huang","avatar":""},{"name":"Tan Xin Zer","avatar":""},{"name":"Zhang Tianqi","avatar":""},{"name":"Sun Jia Lu","avatar":""},{"name":"Wang Jiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
