INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-thanh-thien', 'Bao Thanh Thiên', 'Justice Bao', 'bao thanh thiên justice bao weide huang tan xin zer zhang tianqi sun jia lu wang jiao ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-de-tao-nen-co-ban-gai-nhat-nheo', 'Cách để tạo nên cô bạn gái nhạt nhẽo', 'Saenai Heroine no Sodatekata Fine The Movie Saenai Heroine no Sodatekata Fine', 'https://phimimg.com/upload/vod/20231113-1/f772896b79b0195bb231acd2758ff323.jpg', 'https://phimimg.com/upload/vod/20231113-1/316c379649b66e1235baa9a1ab58a9f8.jpg', '<p>Sau khi Eriri và Utaha quyết định theo Kosaka Akane, một nhà sáng tạo thiên tài để thực hiện siêu phẩm Chronicle, Tomoya cũng quyết định sẽ làm một doujin game tuyệt đỉnh xoay quanh nữ chính Megumi. Không may Kosaka đổ bệnh, Tomoya liền bỏ nhóm của mình để quay sang giúp đỡ Eriri và Utaha-senpai hoàn thành siêu phẩm game của họ. Điều đó làm Megumi cực kì thất vọng, vì chàng trai cô yêu luôn ưu tiên cho các cô gái khác, trong khi cô mới là người gần kề bên cậu nhất. Liệu siêu phẩm của bộ đôi tác giả Eriri và Utaha có gây được tiếng vang? Còn Doujin game của nhóm Tomoya có hoàn tất đúng hạn? Mối quan hệ giữa Tomoya và Megumi sẽ tiến triển thế nào?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Kiyono Yasuno","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Sayuri Yahagi","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Tetsuya Kakihara","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
