INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-anh-hung-indo', 'Siêu Anh Hùng Indo', 'Gundala', 'https://phimimg.com/upload/vod/20231113-1/1c08b6689090926de3a9db2750f3747c.jpg', 'https://phimimg.com/upload/vod/20231113-1/2a96096082c729c3840688010635db2f.jpg', '<p>Nội dung phim xoay quanh cuộc đời của Sancaka và hành trình trở thành anh hùng của những con người bị áp bức bóc lột. Ngay từ khi còn nhỏ, Sancaka đã phải sống trên đường phố vì bố mẹ rời bỏ anh. Trong môi trường khó khăn và đầy nguy hiểm, anh luôn tìm hướng đi an toàn nhất cho bản thân. Tuy nhiên, khi bạo loạn ngày càng nhiều, cuộc sống tệ dần đi, Sancaka phải quyết định giữa việc tiếp tục sống cho bản thân hoặc thay đổi để trở thành anh hùng với những người bị áp bức.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Abimana Aryasatya","avatar":""},{"name":"Tara Basro","avatar":""},{"name":"Bront Palarae","avatar":""},{"name":"Ario Bayu","avatar":""},{"name":"Muzakki Ramdhan","avatar":""},{"name":"Faris Fadjar Munggaran","avatar":""},{"name":"Rio Dewanto","avatar":""},{"name":"Marissa Anita","avatar":""},{"name":"Lukman Sardi","avatar":""},{"name":"Cecep Arif Rahman","avatar":""},{"name":"Ari Tulang","avatar":""},{"name":"Aming Sugandhi","avatar":""},{"name":"Kelly Tandiono","avatar":""},{"name":"Andrew Suleiman","avatar":""},{"name":"Asmara Abigail","avatar":""},{"name":"Rendra Bagus Pamung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324386);
