INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-vien-ky-dieu', 'Công Viên Kỳ Diệu', 'Wonder Park', 'https://phimimg.com/upload/vod/20231113-1/69aa00f188e73b15a5cedb35c384a317.jpg', 'https://phimimg.com/upload/vod/20231113-1/e10ed7781ff01bed2f4914b6922eac86.jpg', '<p>Đắm chìm trong một chuyến phiêu lưu anh hùng ca nơi mọi thứ đều có thể xảy ra! Cô gái trẻ có tên June, người luôn mang trong mình những ý tưởng sáng tạo ngây ngô đã khám phá ra một công viên giải trí trong những giấc mơ của mình lại hoàn toàn có thật. Vô vàn những chuyến phiêu lưu khắp thế giới của những con vật đáng yêu khiến sự thú vị không bao giờ kết thúc. Với những pha hành động gay cấn và tràn ngập tiếng cười, Công viên kì diệu là một một chuyến đi mà cả gia đình sẽ đều rất thích thú.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2019, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Jennifer Garner","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"John Oliver","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Brianna Denski","avatar":""},{"name":"Ken Hudson Campbell","avatar":""},{"name":"Sofia Mali","avatar":""},{"name":"Oev Michael Urbas","avatar":""},{"name":"Kevin Chamberlin","avatar":""},{"name":"Kate McGregor-Stewart","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Lisa Foiles","avatar":""},{"name":"Tom Baker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"n