INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-may-hoc-viec', 'Thợ máy học việc', 'Mokalik (Mechanic)', 'https://phimimg.com/upload/vod/20231123-1/40ef7e65dc8f0521547a1fe87274099f.jpg', 'https://phimimg.com/upload/vod/20231123-1/1c1f4542a4a6c514d7cafba520f335ae.jpg', '<p>Cuộc đời của chàng trai trẻ thay đổi khi cậu được tới học việc tại tiệm thợ máy cách xa ngôi nhà ngoại ô, cho đến khi một cơ hội buộc cậu phải đưa ra quyết định khó khăn.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Nigeria', 0, '[{"name":"Femi Adebayo","avatar":""},{"name":"Halimat Adegbola","avatar":""},{"name":"Ayo Adesanya","avatar":""},{"name":"Faith Afolabi","avatar":""},{"name":"Darimisire Afolayan","avatar":""},{"name":"Tooni Afolayan","avatar":""},{"name":"Banke Akinterinwa","avatar":""},{"name":"Dayo Akinpelu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
