INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-chet-choc', 'Tình yêu chết chóc', 'The Deathly Love', 'https://phimimg.com/upload/vod/20231120-1/ccdba80eed3bb4eccdfd787054ce0833.jpg', 'https://phimimg.com/upload/vod/20231120-1/1d9cf58706d00e0a381002e3509010b5.jpg', '<p>Mo Xiaoyan được chẩn đoán mắc một căn bệnh hiếm gặp trong quá trình kiểm tra y tế và qua điều tra biết được rằng Lin Feng phù hợp với cô. Liệu Lin Feng có thể đồng ý với yêu cầu tưởng chừng như vô nghĩa này với sự liên lạc thường xuyên của Mo Xiaoyan? Mặt khác, bạn nam của Mo Xiaoyan đã phải lòng em gái của Lin Feng, nhưng chưa bao giờ có ấn tượng với cô ấy, liệu cuối cùng hai con uyên ương có thể đến được với nhau?</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Yonggan","avatar":""},{"name":"Qian Siyi","avatar":""},{"name":"Cai Suyang","avatar":""},{"name":"Ke Yijun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
