INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-noi-doi-nho-nhat', 'Lời Nói Dối Nhỏ Nhặt', 'White Lie', 'https://phimimg.com/upload/vod/20231111-1/45304c44f8a582f3404c4bf19b484ed2.jpg', 'https://phimimg.com/upload/vod/20231111-1/1e907e4433e2e6e03133fe28fd91b0ac.jpg', '<p><strong>Lời Nói Dối Nhỏ Nhặt</strong> kể về sinh viên đại học Katie Arneson đã giả mạo chẩn đoán ung thư trong suốt 10 tháng. Cô ấy dùng giả dược, cạo đầu và nhịn đói để trông ốm yếu hơn trước mặt mọi người. Là người nổi tiếng trong trường, Katie đã dùng việc lừa bệnh ung thư để đạt được mục đích về tình cảm lẫn tài chính, gây quỹ thông qua các chiến dịch huy động vốn cộng đồng, đồng thời thu hút bạn bè, những người ủng hộ cùng người bạn gái Jennifer Ellis.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kacey Rohl","avatar":""},{"name":"Amber Anderson","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Connor Jessup","avatar":""},{"name":"Thomas Olajide","avatar":""},{"name":"Christine Horne","avatar":""},{"name":"Sharon Lewis","avatar":""},{"name":"Darrin Baker","avatar":""},{"name":"Vanessa Matsui","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Carolina Bartczak","avatar":""},{"name":"Dan Beirne","avatar":""},{"name":"Shanice Banton","avatar":""},{"name":"Murray Furrow","avatar":""},{"name":"Jennifer Vallance","avatar":""},{"name":"Julia Knope","avatar":""},{"name":"James Madge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
