INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-dieu-ky-2019', 'Giáng Sinh Diệu Kỳ', 'Twinkle All The Way', 'https://phimimg.com/upload/vod/20231111-1/cfe09c7e67abb47f780e829a6b460d5b.jpg', 'https://phimimg.com/upload/vod/20231111-1/aa258dc5a3f7ecabeea3e293b04c64e6.jpg', '<p>Cadence Clark hiện đã ly hôn, đang sống cùng con gái Mary bảy tuổi. Còn Henry Harrison góa vợ, một mình nuôi cô con gái sáu tuổi Ruthie. Thật tình cờ, cả hai phải cùng nhau ghép đôi trong một chương trình ở trường cho các con vào dịp Giáng Sinh. Hai con người với hai tính cách khác biệt, liệu họ có trở thành một đội hợp ý?</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Drew","avatar":""},{"name":"Ryan McPartlin","avatar":""},{"name":"Lesley Ann Warren","avatar":""},{"name":"Mark Ghanimé","avatar":""},{"name":"Rachael Crawford","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Randy Thomas","avatar":""},{"name":"Nicki Whitely","avatar":""},{"name":"Andrew Bushell","avatar":""},{"name":"Mark Irvingsen","avatar":""},{"name":"Jerald Bezener","avatar":""},{"name":"Lisa Michelle Cornelius","avatar":""},{"name":"Brian Sills","avatar":""},{"name":"Paul Dick","avatar":""},{"name":"Cleary Herzlinger","avatar":""},{"name":"Isla Elizabeth Gr","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324386);
