INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giang-sinh-dieu-ky-2019', 'Giáng Sinh Diệu Kỳ', 'Twinkle All The Way', 'giáng sinh diệu kỳ twinkle all the way sarah drew ryan mcpartlin lesley ann warren mark ghanimé rachael crawford lanette ware randy thomas nicki whitely andrew bushell mark irvingsen jerald bezener lisa michelle cornelius brian sills paul dick cleary herzlinger isla elizabeth gr ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-at-second-sight', 'Love at Second Sight', 'Love at Second Sight', 'https://phimimg.com/upload/vod/20231111-1/033d13ceccb0dcf19e6979b88dbb0813.jpg', 'https://phimimg.com/upload/vod/20231111-1/23e5d5123e20eb8aae66e2b882e06de8.jpg', '<p>Paris, 2009. Raphaël là một học sinh trung học vượt qua những ngày với người bạn thân nhất Felix cùng lúc mà anh ta cố gắng kết thúc cuốn tiểu thuyết khoa học viễn tưởng đầu tiên của mình khi có cơ hội anh ta gặp Olivia, một người hâm mộ sinh viên khác để chơi piano. Sau một cuộc gặp gỡ huyền diệu đầu tiên giữa họ, Raphaël tìm thấy trong cảm hứng của cô để kết thúc cuốn tiểu thuyết. Mười năm sau, 2019, cuốn tiểu thuyết đã được quay trong một saga khoa học viễn tưởng nổi tiếng và Raphaël trong một nhà văn bán chạy nhất với sự nghiệp thành công bao gồm cả sự xuất hiện trong truyền hình và internet. Do đó, anh ta quay vào một người đàn ông tràn đầy mình mà không có không gian cho bất kỳ ai khác, và cuộc hôn nhân với Olivia là mỗi lần lạnh và xa hơn. Sau khi kết thúc cuốn sách cuối cùng và nói chuyện với Olivia sắp kết thúc mối quan hệ, cả hai đi ngủ. Sáng hôm sau, Raphaël thức dậy để tìm thấy chính mình trong một thực tế thay thế: anh ta làm giáo viên trong một trường trung học công lập với Felix của giáo viên, có liên quan đến Mélanie (một giáo viên khác của trường của anh ta), sự nghiệp của ông là nhà văn không tồn tại và Olivia là một nghệ sĩ piano nổi tiếng không nhận ra anh ta. Không thể chấp nhận thế giới mới này là thực tế và không cần phải nhớ về những năm mười năm này, Raphaël nói với Felix, sự thật yêu cầu anh ta giúp đỡ để biết cuộc sống của anh ta trong thế giới thay thế này như thế nào. Muốn quay lại và phục hồi cuộc sống trước đây của mình, Raphaël tìm thấy một giải pháp khả thi: Khôi phục Olivia khiến cô ấy yêu anh lần nữa. Giả vờ là một nhà văn ma của những người nổi tiếng &#39;tiểu sử&#39; quan tâm đến cô ấy, Raphaël gặp Olivia để biết lịch sử của cô ấy, nhưng sau đó anh ấy phát hiện ra một rắc rối bất ngờ: Olivia đã đính hôn với đại lý của mình, Marc. Nếu Raphaël không vội vàng, có thể anh ta không bao giờ có thể phục hồi cuộc sống mà anh ta có.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"François Civil","avatar":""},{"name":"Joséphine Japy","avatar":""},{"name":"Benjamin Lavernhe","avatar":""},{"name":"Camille Lellouche","avatar":""},{"name":"Amaury de Crayencour","avatar":""},{"name":"Edith Scob","avatar":""},{"name":"Juliette Dol","avatar":""},{"name":"Samir Boitard","avatar":""},{"name":"Christian Benedetti","avatar":""},{"name":"Guillaume Bouchède","avatar":""},{"name":"Anne-Valérie Payet","avatar":""},{"name":"Raphael von Blumenthal","avatar":""},{"name":"Bertrand Combe","avatar":""},{"name":"Guillaume Mélanie","avatar":""},{"name":"So","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324386);
