INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sturgill-simpson-gioi-thieu-sound-fury', 'Sturgill Simpson giới thiệu Sound & Fury', 'Sturgill Simpson Presents Sound & Fury', 'https://phimimg.com/upload/vod/20231111-1/2a84e53c9fc1087290208c8b4f3659e6.jpg', 'https://phimimg.com/upload/vod/20231111-1/5d0a56e28d47c236d14fad451eceb617.jpg', '<p>Trong album hình ảnh anime này, một người lái xe bí ẩn tiến sâu vào địa ngục sau tận thế, hướng tới một cuộc đấu dữ dội với hai đối thủ quỷ dị.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sturgill Simpson","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324386);
