INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kip-luyen-rong-vung-dat-bi-an', 'Bí Kíp Luyện Rồng: Vùng Đất Bí Ẩn', 'How to Train Your Dragon: The Hidden World', 'https://phimimg.com/upload/vod/20231111-1/a7d405784bf8745c0223d7047cbe8a9f.jpg', 'https://phimimg.com/upload/vod/20231111-1/02923098eeec71ed7bf921ca961d9ecd.jpg', '<p>Bí kíp luyện rồng: Vùng đất bí ẩn là một bộ phim hoạt hình máy tính 3D hành động giả tưởng Mĩ năm 2019, được sản xuất bởi DreamWorks Animation và phát hành bởi Universal Pictures dựa trên cuốn sách cùng tên. Đây là phần tiếp theo của Bí kíp luyện rồng 2 và là phần cuối cùng trong loạt phim Bí kíp luyện rồng. &nbsp;Một năm sau khi bảo vệ Berk khỏi Drago, Răng Sún và Nấc Cụt cùng với những bạn của họ, tiếp tục giải cứu các con rồng bị bắt để đưa chúng trở lại Berk và tạo cho các loài rồng một môi trường nhộn nhịp. Nhưng nỗ lực giải cứu những con rồng đã khiến hòn đảo trở nên quá đông với một lượng lớn số rồng. Để xử lí tình trạng quá tải này, Nấc Cụt quyết định tìm một &quot;vùng đất bí ẩn&quot;, nơi trú ngụ mà cậu thấy là an toàn nhất cho các con rồng mà người cha quá cố, Stoick đã nói với cậu. Trong khi đó, một con Fury trắng bị giam cầm bởi các lãnh chúa, sau nó được trao lại cho thợ săn rồng khét tiếng Grimmel làm mồi nhử.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jay Baruchel","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Justin Rupple","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Kieron Elliott","avatar":""},{"name":"Julia Emelin","avatar":""},{"name":"Gideon Emery","avatar":""},{"name":"Ashley Jense","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
