INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-clinton', 'Con Đường Clinton', 'Clinton Road', 'https://phimimg.com/upload/vod/20231111-1/565a15a0016ef9429ff6fcf5ca88ba75.jpg', 'https://phimimg.com/upload/vod/20231111-1/c5149fae4aadef4a20a7962c1b9e1796.jpg', '<p>Câu chuyện kể xảy ra ở vùng nông thôn New Jersey. Một lính cứu hỏa góa vợ tìm lại tung tích vợ mình sau khi cô ta ta mất tích trên con đường bị ma ám. Lần theo những manh mối thực, anh ta phải chiến đấu với những thế lực siêu nhiên để sống sót tìm cho mình câu trả lời về sự mất tích.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"Ice-T","avatar":""},{"name":"Erin O''Brien","avatar":""},{"name":"James DeBello","avatar":""},{"name":"Katelyn Pearce","avatar":""},{"name":"Vincent Pastore","avatar":""},{"name":"Ace Young","avatar":""},{"name":"Cody Calafiore","avatar":""},{"name":"Katie Morrison","avatar":""},{"name":"Lauren LaVera","avatar":""},{"name":"Sarah Pribis","avatar":""},{"name":"Bo Dietl","avatar":""},{"name":"Richard Grieco","avatar":""},{"name":"Milan-Devi LaBrey","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324386);
