INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-cuoc-doi', 'Chuyến Bay Cuộc Đời', 'Astronaut', 'https://phimimg.com/upload/vod/20231111-1/d464ad24e68f0383599bdedcc35a862b.jpg', 'https://phimimg.com/upload/vod/20231111-1/1542dde50bf0cf322657420f60169a16.jpg', '<p>Phi Hành Gia kể về một người đàn ông góa vợ đã nói dối về tuổi của mình và tham gia chương trình bốc thăm để có cơ hội một lần trong đời được đi trên chuyến bay thương mại đầu tiên ra ngoài vũ trụ. Khi nghe thấy tên của anh được rút ra, anh sớm thấy mình chuẩn bị cho cuộc phiêu lưu cuối cùng trong giấc mơ của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Richard Dreyfuss","avatar":""},{"name":"Lyriq Bent","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Krista Bridges","avatar":""},{"name":"Art Hindle","avatar":""},{"name":"Richie Lawrence","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Joan Gregson","avatar":""},{"name":"Colin Mochrie","avatar":""},{"name":"Jennifer Phipps","avatar":""},{"name":"Brendan Flynn","avatar":""},{"name":"Judy Marshak","avatar":""},{"name":"Karen LeBlanc","avatar":""},{"name":"Mimi Kuzyk","avatar":""},{"name":"Lori Hallier","avatar":""},{"name":"Maria Ricossa","avatar":""},{"name":"Rhona Shekter","avatar":""},{"name":"Sandra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
