INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-phai-lam', 'Điều Phải Làm', 'A Score to Settle', 'https://phimimg.com/upload/vod/20231120-1/19c5db1d061c0696bf0c88cf18edbe89.jpg', 'https://phimimg.com/upload/vod/20231120-1/3af1b207fb2af2823b03ff32e1fc003c.jpg', '<p>Sau khi phục vụ 19 năm tù vì tội ác không cam kết, Frank được phát hành. Anh ta sẽ phải đưa ra lựa chọn - để bù đắp cho những năm đã mất đi với con trai mình hoặc trả thù những người mà ông coi bạn bè. Frank sẽ có thể bắt đầu cuộc sống một lần nữa chứ?</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Noah Le Gros","avatar":""},{"name":"Karolina Wydra","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Mohamed Karim","avatar":""},{"name":"Dave Kenneth MacKinnon","avatar":""},{"name":"Ian Tracey","avatar":""},{"name":"Bailey Coppola","avatar":""},{"name":"Zyan Panagopoulos","avatar":""},{"name":"Alex Alegria","avatar":""},{"name":"Linda Ko","avatar":""},{"name":"Carmel Amit","avatar":""},{"name":"Anthony Timpano","avatar":""},{"name":"Nicole G. Leier","avatar":""},{"name":"Sean Owen Roberts","avatar":""},{"name":"Leanne Khol Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
