INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('terra-willy-cuoc-phieu-luu-toi-hanh-tinh-la', 'Terra Willy: Cuộc Phiêu Lưu Tới Hành Tinh Lạ', 'Astro Kid', 'https://phimimg.com/upload/vod/20231110-1/60133b11c99abd5caebf87fbe49c779f.jpg', 'https://phimimg.com/upload/vod/20231110-1/bec97d8c4c1a95db690fac8f9006791f.jpg', '<p>Bộ phim lấy bối cảnh tương lai, theo sau hành trình sinh tồn của cậu bé 10 tuổi tên Willy, bị lạc mất gia đình trong một tai nạn trên tàu vũ trụ. Tàu cứu hộ của Willy hạ cánh xuống một hành tinh kì lạ, chưa được khai phá. Với sự giúp đỡ của Buck – một robot tự vận hành và Flash – một sinh vật bản địa dễ thương, Willy phải vượt qua những khó khăn, nguy hiểm cũng như khám phá hệ thống động – thực vật trên hành tinh này trước khi nhóm giải cứu cậu được gửi tới.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Timothé Vom Dorp","avatar":""},{"name":"Édouard Baer","avatar":""},{"name":"Marie-Eugénie Maréchal","avatar":""},{"name":"Guillaume Lebon","avatar":""},{"name":"Barbara Tissier","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324386);
