INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sao-bong-ro', 'Siêu sao bóng rổ', 'High Flying Bird', 'https://phimimg.com/upload/vod/20231110-1/29bc8b21da3aa95f3c6abe0a42d9915b.jpg', 'https://phimimg.com/upload/vod/20231110-1/f32cb703584ff73ecead052a34298403.jpg', '<p>Khi một lính mới kiêm khách hàng mà anh đại diện bị NBA đóng băng, người đại diện này lên kế hoạch táo bạo để cứu sự nghiệp cả hai và phá cấu trúc quyền lực của giải.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"André Holland","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Melvin Gregg","avatar":""},{"name":"Sonja Sohn","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Glenn Fleshler","avatar":""},{"name":"Jeryl Prescott","avatar":""},{"name":"Justin Hurtt-Dunkley","avatar":""},{"name":"Caleb McLaughlin","avatar":""},{"name":"Bobbi Bordley","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Bill Duke","avatar":""},{"name":"Eddie Tavares","avatar":""},{"name":"Farah Bala","avatar":""},{"name":"Skip Bayless","avatar":""},{"name":"Shannon Sharpe","avatar":""},{"name":"Joy Taylor","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
