INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-chua-tung', 'Chúng Ta Chưa Từng', 'The Way We Weren''t', 'https://phimimg.com/upload/vod/20231110-1/daaa16453e1f640b2977b12b8763f18a.jpg', 'https://phimimg.com/upload/vod/20231110-1/65e356ce9451a08d9741c7b2f328009f.jpg', '<p>Bộ phim Chúng Ta Chưa Từng - The Way We Weren&#39;t kể về câu chuyện dở khóc dở cười của cặp đôi Charlotte và Brandon. Hai người gặp nhau ngay sau khi mối quan hệ trước đó của họ tan vỡ, vì vậy, trong nỗ lực để khiến bản thân trở nên hấp dẫn hơn, họ phóng đại và nói dối về bản thân mình. Nhưng sau khi họ chuyển đến cùng nhau, tất cả sự lừa dối được làm sáng tỏ, tạo ra những tình huống vừa trớ trêu vừa hài hước.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Fiona Gubelmann","avatar":""},{"name":"Ben Lawson","avatar":""},{"name":"Amber Stevens West","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Alyssa Diaz","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"Alexandra Davies","avatar":""},{"name":"Alan Simpson","avatar":""},{"name":"Kristi Clainos","avatar":""},{"name":"John Cirigliano","avatar":""},{"name":"Ronnie Gene Blevins","avatar":""},{"name":"Cloe Tichelli","avatar":""},{"name":"Rick Hays","avatar":""},{"name":"Patricia Belcher","avatar":""},{"name":"Alex Weed","avatar":""},{"name":"Rita Rani Ahuja","avatar":""},{"name":"Jolene Ki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
