INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-con-mai', 'Trái Tim Còn Mãi', 'Here Awhile', 'https://phimimg.com/upload/vod/20231109-1/65106fb14f5b9c0a068212d6aaf4a3fc.jpg', 'https://phimimg.com/upload/vod/20231109-1/21e1731ee461dc1a1d0f6ab1cf9da5df.jpg', '<p>Bộ phim Trái Tim Còn Mãi Sau - Here Awhile kể về cuộc đời của Anna sau khi phát hiện mình bị mắc bệnh nan y; Cô đã quyết định quay về quê nhà Portland Oregon sau 15 năm để gặp lại người em trai xa cách đã lâu là Michael. Tại nơi này cô mong muốn được có cơ hội dành những ngày cuối đời để bên người thân và kết thúc cuộc đời bằng cách sử dụng Đạo luật được chết nhân đạo ở Oregon. Tuy đây là quyết định rất khó khăn và đau đớn nhưng những người thân bên cạnh cô đã quyết định ủng hộ và cùng cô có những tháng ngày cuối cùng thật tươi đẹp và hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Camp","avatar":""},{"name":"Steven Strait","avatar":""},{"name":"Joe Lo Truglio","avatar":""},{"name":"Chloe Mason","avatar":""},{"name":"Kristin Taylor","avatar":""},{"name":"Reza Leal-Smartt","avatar":""},{"name":"Grant Hall","avatar":""},{"name":"Sydney Lovering","avatar":""},{"name":"Parker Hall","avatar":""},{"name":"Dana Millican","avatar":""},{"name":"Deborah Lee Smith","avatar":""},{"name":"Griffin Gadre","avatar":""},{"name":"Kieran Gadre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
