INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tieu-chi-vi', 'Hoa Tiêu Chi Vị', 'Fagara', 'https://phimimg.com/upload/vod/20231109-1/844af41cd5d461c2cdd7c48ef02390b9.jpg', 'https://phimimg.com/upload/vod/20231109-1/5694255632690cd0a37fa4961e514d22.jpg', '<p>Hoa Tiêu Chi Vị - Fagara là câu chuyện kể về Như Thụ - một cô gái đang cùng bố sống những chuỗi ngày bình yên với công việc yêu thích là lên kế hoạch cho một công ty du lịch. Những biến cố bất ngờ liên tiếp ập đến khi bố cô qua đời. Điều cô càng không thể ngờ là mình có tới 2 cô em gái cùng cha khác mẹ ở Đài Bắc và Trùng Khánh là Như Chi và Như Quả. Mặc dù 2 bố con sống cùng nhau bấy lâu nay nhưng đến bây giờ cô mới phát hiện ra bố mình đã từng có cuộc sống khác. Lần đầu tiên 3 chị em cô gặp nhau là trong đám tang của bố, trong mối quan hệ không thể giải thích. Tình cha con là cốt lõi của câu chuyện, còn số phận cuộc đời của mỗi cô con gái chính là hương vị đặc trưng của phim. Liệu họ có thể chấp nhận nhau? Liệu tình cảm ruột thịt máu mủ có được đong đầy?</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sammi Cheng","avatar":""},{"name":"Megan Lai","avatar":""},{"name":"Li Xiaofeng","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Linda Liu","avatar":""},{"name":"Wu Yanshu","avatar":""},{"name":"Lo Chun Yip","avatar":""},{"name":"Bryant Mak","avatar":""},{"name":"Kaki Sham","avatar":""},{"name":"Ben Yuen Foo-Wa","avatar":""},{"name":"Tam Tin-Bo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
