INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-sat', 'Giám Sát', 'Watching', 'https://phimimg.com/upload/vod/20231109-1/ddc609e6765cafb174bec43dd6a43f34.jpg', 'https://phimimg.com/upload/vod/20231109-1/8ed3a00730ac16bd3ffd3528b458be94.jpg', '<p>Young-Woo (Gang Ye-Won) là một phụ nữ luôn hi sinh cho sự nghiệp và tham công tiếc việc. Một đêm nọ, cô bị Joon-Ho (Lee Hak-Joo) bắt cóc trong nhà để xe của công ty. Joon-Ho làm bảo vệ của tòa nhà. Young-Woo đấu tranh để trốn thoát khỏi Joon-Ho.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ye-won Kang","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Im Ji-Hyun","avatar":""},{"name":"Min Kyung-jin","avatar":""},{"name":"Lee Eun-hee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
