INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-mang', 'Đoản Mạng', 'We Die Young', 'https://phimimg.com/upload/vod/20231109-1/0bd88c44540a3b225ba41b183b3cbc85.jpg', 'https://phimimg.com/upload/vod/20231109-1/fecc0947c0ec0d2abf66a746747fb481.jpg', '<p>Lucas, một cậu bé 14 tuổi được gia nhập vào cuộc sống băng đảng ở Washington, D.C., xác định rõ ràng rằng sẽ không để đứa em trai 10 tuổi của mình đi theo con đường tương tự. Khi một cựu chiến binh Afghanistan đi vào khu phố, một cơ hội sẽ xuất hiện.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"David Castañeda","avatar":""},{"name":"Joana Metrass","avatar":""},{"name":"Elijah Rodriguez","avatar":""},{"name":"Nicholas Sean Johnny","avatar":""},{"name":"Charlie MacGechan","avatar":""},{"name":"Dean John-Wilson","avatar":""},{"name":"Jim Caesar","avatar":""},{"name":"Kerry Bennett","avatar":""},{"name":"Uriel Emil Pollack","avatar":""},{"name":"Pablo Scola","avatar":""},{"name":"Robyn Cara","avatar":""},{"name":"Jacob Scipio","avatar":""},{"name":"Joseph Long","avatar":""},{"name":"Tony Wreden","avatar":""},{"name":"Karlos Klau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
