INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-gia-quyen-tinh-vo-anh-hung', 'Hoắc Gia Quyền: Tinh Võ Anh Hùng', 'Fist of Legend', 'https://phimimg.com/upload/vod/20231110-1/e8196df81a879c5db449a9bf6a208908.jpg', 'https://phimimg.com/upload/vod/20231110-1/05c1beaa4b0fc4e17cad84b480f6825b.jpg', '<p>Trần Chân sang Nhật Bản học tập kỹ thuật tiên tiến theo lời dặn của sư phụ, nhưng lại phát hiện thấy có nhiều học sinh người Hoa bị mất tích. Trong lúc đang được sự giúp đỡ của người bạn tốt là Lương Thiệu Văn để tìm ra hung thủ thật sự, Trần Chân đã phải đấu trí đấu dũng với Ito Shinji của hội Hắc Long và hội trưởng Yamada Kazumin. Cuối cùng cậu đã phá được âm mưu của hội Hắc Long, hủy hoại phòng thí nghiệm bí mật của người Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Wenjie","avatar":""},{"name":"Gu Lei","avatar":""},{"name":"Wu Heng","avatar":""},{"name":"Li Qianfeng","avatar":""},{"name":"Jin Jiahui","avatar":""},{"name":"Zhao Chenyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
