INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tien-bat-yeu-2', 'Đại Tiên Bắt Yêu 2', 'The Love of Immortal', 'https://phimimg.com/upload/vod/20231110-1/9349189155e988a73f40338336e4d327.jpg', 'https://phimimg.com/upload/vod/20231110-1/3ed8a3c87b76867c6002e90e4838947a.jpg', '<p>Thiên Ý là học sinh lưu ban nổi tiếng trên Thiên giới, do nghiệt duyên tiền kiếp chưa dứt nên không thể thành tiên, chỉ có thể làm một tiểu tiên đồng ở Tiên Thư Các, một lần vô tình thả Tuyết yêu bị giam, Thiên Ý hạ phàm bắt yêu bị mất đi pháp lực, dựa vào thân phận người phàm để đọ sức với Tuyết yêu, vô tình nảy sinh tình cảm. Thiên Ý được biết tiền kiếp của mình phạm lỗi dẫn đến Tuyết nữ thành yêu, tự nguyện vật vờ nghìn năm trên đường Hoàng tuyền, cuối cùng Tuyết yêu vì cứu Thiên Ý hi sinh bản thân mình.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eric Suen","avatar":""},{"name":"Lorene Ren","avatar":""},{"name":"Lee Lichun","avatar":""},{"name":"Hao Xuankai","avatar":""},{"name":"Xin Pan","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"He Cao","avatar":""},{"name":"Gao Weiman","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
