INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-chien-tranh-lanh', 'Ván cờ chiến tranh lạnh', 'The Coldest Game', 'https://phimimg.com/upload/vod/20231110-1/d8d116053eb1fbde0e25da37850978e5.jpg', 'https://phimimg.com/upload/vod/20231110-1/43240ab2e1d99d602ee86106ec7b44fe.jpg', '<p>Warsaw, Ba Lan, trong Cuộc khủng hoảng tên lửa Cuba, năm 1962. Josh Mansky, một thiên tài toán học rắc rối và là cựu vô địch cờ vua Hoa Kỳ, được tuyển dụng để tổ chức một trận đấu công khai nguy hiểm với nhà vô địch Liên Xô, trong khi chơi trò chơi gián điệp chết chóc ẩn giấu trong bóng tối đen tối nhất của một lãnh thổ thù địch.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Bill Pullman","avatar":""},{"name":"Lotte Verbeek","avatar":""},{"name":"Nicholas Farrell","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Robert Więckiewicz","avatar":""},{"name":"James Bloor","avatar":""},{"name":"Aleksey Serebryakov","avatar":""},{"name":"Evgeniy Sidikhin","avatar":""},{"name":"Cezary Kosiński","avatar":""},{"name":"Aleksandr Lobanov","avatar":""},{"name":"Wojciech Mecwaldowski","avatar":""},{"name":"Magdalena Boczarska","avatar":""},{"name":"Andy Beckwith","avatar":""},{"name":"John Benfield","avatar":""},{"name":"Ludwiki Bor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
