INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ngay-mua-o-new-york', 'Chuyện Ngày Mưa Ở New York', 'A Rainy Day in New York', 'https://phimimg.com/upload/vod/20231110-1/96986fcfc2f59df67ca720814daee679.jpg', 'https://phimimg.com/upload/vod/20231110-1/dc1f996eb0777a79c77117950ed2e5bc.jpg', '<p>Chàng sinh viên Gatsby Welles theo chân bạn gái Ashleigh Enright tới Manhattan, New York vào dịp cuối tuần vì Ashleigh giành được cơ hội phỏng vấn đạo diễn Roland Pollard. Thay vì một chuyến đi đặc biệt và lãng mạn như kỳ vọng, Gatsby liên tục bị bạn gái bỏ rơi. Ashleigh thơ ngây đeo đuổi cuộc phiêu lưu chớp nhoáng bên 3 người đàn ông “sừng sỏ” của Hollywood. Gatsby lang thang trên đường phố New York, tình cờ gặp gỡ nữ diễn viên Shannon và đóng chung với nàng một cảnh hôn đầy lãng mạn và khám phá ra nhiều điểm chung giữa hai người.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothée Chalamet","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Griffin Newman","avatar":""},{"name":"Kelly Rohrbach","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Annaleigh Ashford","avatar":""},{"name":"Cherry Jones","avatar":""},{"name":"Jonathan Hogan","avatar":""},{"name":"Taylor Black","avatar":""},{"name":"Kathryn Leigh Scott","avatar":""},{"name":"Ben Warheit","avatar":""},{"name":"Will Roger","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd07