INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ung-dung-tu-than', 'Ứng Dụng Tử Thần', 'Countdown', 'https://phimimg.com/upload/vod/20231109-1/933122ffc0972db091752b6da2431617.jpg', 'https://phimimg.com/upload/vod/20231109-1/0ea9462b532e6d2f7ec421e37f8a3a2b.jpg', '<p>Ứng Dụng Tử Thần: Quinn – một cô y tá vô tình cài đặt một ứng dụng lạ mà nó khả năng đoán được thời điểm cái chết xảy ra. Cô rùng mình khi Countdown (tên ứng dụng) thông báo rằng cô chỉ còn 3 ngày để sống. Kể từ đó hàng loạt các thực thể kinh dị ám ảnh cô. Countdown đã điểm những giây cuối cùng, Quinn phải tìm mọi cách để chống lại định mệnh mà chiếc ứng dụng này gán cho mình.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Lail","avatar":""},{"name":"Jordan Calloway","avatar":""},{"name":"Talitha Bateman","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Dillon Lane","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Tom Segura","avatar":""},{"name":"Lana McKissack","avatar":""},{"name":"Anne Winters","avatar":""},{"name":"Tichina Arnold","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Valente Rodriguez","avatar":""},{"name":"Louisa Abernathy","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Jonny Berryman","avatar":""},{"name":"Cornell Adams","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
