INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-bi-mat', 'Vũ Khí Bí Mật', 'Secret Weapon', 'https://phimimg.com/upload/vod/20231108-1/1bc6e88a73c6fc2d6e31bee137c0813d.jpg', 'https://phimimg.com/upload/vod/20231108-1/94930c38b713c60f63d9d7520f53775c.jpg', '<p>Bộ phim kể về bệ phóng tên lửa nổi tiếng của Liên Xô có biệt danh &quot;Katyusha&quot;, được giữ bí mật trong Thế chiến 2. Một trong những cỗ máy giết người độc đáo này đã bị chết đuối trong cuộc rút lui bất ngờ của quân đội Nga. Một đơn vị đặc biệt được hình thành từ các cựu vận động viên được gửi đến để giải cứu vũ khí bí mật mà người Đức không bao giờ có thể tìm thấy - bất kể nó cần gì.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Aleksandr Efremov","avatar":""},{"name":"Sergey Efremov","avatar":""},{"name":"Evgeny Antropov","avatar":""},{"name":"Timofey Tribuntsev","avatar":""},{"name":"Anatoliy Gushchin","avatar":""},{"name":"Polya Polyakova","avatar":""},{"name":"Azamat Nigmanov","avatar":""},{"name":"Nadezhda Antzipovich","avatar":""},{"name":"Alexander Efremov","avatar":""},{"name":"Aleksandr Ustyugov","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324386);
