INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-gian-doi', 'Cuộc Tình Gian Dối', 'Deception of the Novelist', 'https://phimimg.com/upload/vod/20231108-1/a3e59535a0772b9ff3e010e08347fb59.jpg', 'https://phimimg.com/upload/vod/20231108-1/3ceec450d1ba38c566ac9dedf894ccb8.jpg', '<p>Cuộc Tình Gian Dối xoay quanh nhân vật của Trương Kiến Thanh là một tiểu thuyết gia nổi tiếng nhận được khoản thừa kế ‘khủng’ sau khi cha anh qua đời. Anh cho một người phụ nữ hai dòng máu Nhật-Trung tên Elaine (Linah Matsuoka) thuê một bất động sản mà anh được thừa kế và họ rơi vào lưới tình, gây rạn nứt giữa anh và vợ (Hà Bội Du). Một đêm, đột nhiên phát hiện xác Elaine ở ban-công của ngôi nhà. Khi cảnh sát bắt đầu điều tra, họ nhận ra có rất nhiều tình tiết đáng ngờ trong vụ án dẫn đến nghi vấn đây không phải là một vụ báo thù người chồng phản bội thông thường…</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Justin Cheung","avatar":""},{"name":"Jeana Ho Pui-Yu","avatar":""},{"name":"Linah Matsuoka","avatar":""},{"name":"Billy Luk","avatar":""},{"name":"Chan Ho-Man","avatar":""},{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"C Kwan","avatar":""},{"name":"Gregory Wong","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"Raymond Chiu","avatar":""},{"name":"Terry Zou","avatar":""},{"name":"Kelly Chen Jia-li","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 17846903