INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ly-va-nhan-tu', 'Công Lý và Nhân Từ', 'Just Mercy', 'https://phimimg.com/upload/vod/20231108-1/8683f8cccc0b3cb7039e4f22fff1756a.jpg', 'https://phimimg.com/upload/vod/20231108-1/c392b8d3cae479b91822452cec44a2ff.jpg', '<p>Sau khi tốt nghiệp Harvard, Bryan đến Alabama để bảo vệ quyền lợi của những người bị kết án sai cùng sự hỗ trợ của luật sư địa phương Eva Ansley. Một trong những vụ án đầu tiên và gây tranh cãi nhất của ông là vụ án của Walter McMillian vào năm 1987, bị tuyên án tử hình vì can tội sát hại một thiếu nữ 18 tuổi, mặc dù có nhiều bằng chứng chứng minh sự vô tội của bị cáo và sự thật là lời khai duy nhất chống lại anh ta đến từ một tên tội phạm với động cơ nói dối. Trong những năm tiếp theo, Bryan bị kéo vào một mê cung của những thao túng chính trị và pháp lí cùng với sự phân biệt chủng tộc công khai trong suốt quá trình đấu tranh cho Walter và những người khác, chống lại cả một hệ thống pháp luật và phe lợi thế.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael B. Jordan","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"O''Shea Jackson Jr.","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Rob Morgan","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"J. Alphonse Nicholson","avatar":""},{"name":"Karan Kendrick","avatar":""},{"name":"Hayes Mercure","avatar":""},{"name":"Lindsay Ayliffe","avatar":""},{"name":"Dominic Bogart","avatar":""},{"name":"Tim Hooper","avatar":""},{"name":"Andrene Ward-Hammond","avatar":""},{"name":"John Lac","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324386);
