INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-yeu-truyen-1-nhiep-tieu-thien', 'Hồ Yêu Truyện 1: Nhiếp Tiểu Thiến', 'Fox Demon', 'null', 'https://phimimg.com/upload/vod/20231113-1/56fab00f3a20a9f2d4e680c6754bc03f.jpg', '<p>Nie Xiao Qian, một cô gái cô đơn bị quái vật điều khiển, vô tình gặp được Ning Cai Chen, một học giả đến Bắc Kinh để tham dự kỳ thi hoàng gia. Xiao Qian đang chuẩn bị cúng tế cho bà ngoại cây quỷ Lao Lao. Sau khi có bản chất tốt bụng, Xiao Qian liên tục tiếp cận Ning Cai Chen và cảm động trước sự ngây thơ của anh. Sau khi biết được hoàn cảnh của Xiao Qian, Ning Cai Chen đã nhờ Yan Chi Xia lấy lại linh hồn của Xiao Qian, nhưng bị con quỷ núi Đen già chặn lại và trải qua một giai đoạn trải nghiệm quanh co và khó khăn từ yêu đến người.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Zhuan Kai","avatar":""},{"name":"Gao Fan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324386);
