INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-bo-dan-chu', 'Bên bờ dân chủ', 'The Edge of Democracy', 'https://phimimg.com/upload/vod/20231103-1/bbb735925218f4c527c8a255b5789394.jpg', 'https://phimimg.com/upload/vod/20231103-1/b669605864d47518c84170849c7d158e.jpg', '<p>Phim tài liệu chính trị và hồi ký cá nhân đan xen trong hành trình nhằm đi sâu tìm hiểu sự thật phức tạp phía sau sự sụp đổ của hai nhiệm kỳ tổng thống Brazil.</p>', 'Full', 1, 'single', 'completed', 21, 2019, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Dilma Rousseff","avatar":""},{"name":"Luiz Inácio Lula da Silva","avatar":""},{"name":"Michel Temer","avatar":""},{"name":"Eduardo Cunha","avatar":""},{"name":"Jair Bolsonaro","avatar":""},{"name":"Sérgio Moro","avatar":""},{"name":"Paulo Maluf","avatar":""},{"name":"Jean Wyllys","avatar":""},{"name":"Aécio Neves","avatar":""},{"name":"Gilberto Carvalho","avatar":""},{"name":"Petra Costa","avatar":""},{"name":"Barack Obama","avatar":""},{"name":"Queen Elizabeth II of the United Kingdom","avatar":""},{"name":"Nelson Mandela","avatar":""},{"name":"Li An","avatar":""},{"name":"Elen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324386);
