INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-hoang-dao', 'Đêm Hoàng Đạo', 'Abduction', 'https://phimimg.com/upload/vod/20231103-1/7177f69544c501faf167149f35f23e4d.jpg', 'https://phimimg.com/upload/vod/20231103-1/d65cfa0f32c234e325a90fa2cfc69c23.jpg', '<p>Đêm Hoàng Đạo (Abduction) một căn phòng đầy rẫy những xác chết kì dị, Quinn (Scott Adkins) nhận ra mình và con gái đang bị người ngoài hành tinh bắt cóc, một thế lực siêu nhiên do ba bóng người mặc áo trùm đầu màu đen điều khiển. Trong lúc cố gắng chống trả để cứu cô con gái bé bỏng của mình, Quinn bị rơi vào không gian vô định và đi thẳng đến tương lai của 30 năm sau tại một quốc gia xa lạ trong tình trạng mất hết kí ức. Cùng lúc đó, Connor, một tay lính đánh thuê cũng phát hiện người vợ trẻ của mình cũng bị mất tích một cách bí ẩn. Với sự giúp đỡ của nữ bác sĩ tâm lý xinh đẹp Anna (Trương Ngọc Ánh) và tiến sĩ Gong, một nhà khoa học lập dị nhưng biết tường tận về sự hiện diện của người ngoài hành tinh trên trái đất. Họ đã lần theo dấu vết của thế lực siêu nhiên là những người trùm mũ đen kỳ lạ. Một bộ phim hành động hay do trung quốc sản xuất, mời các bạn cùng theo dõi...</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Andy On","avatar":""},{"name":"Lily Ji","avatar":""},{"name":"Aki Aleong","avatar":""},{"name":"Trương Ngọc Ánh","avatar":""},{"name":"Daniel Whyte","avatar":""},{"name":"Mike Leeder","avatar":""},{"name":"Paul W. He","avatar":""},{"name":"Philippe Joly","avatar":""},{"name":"Andrew Ng","avatar":""},{"name":"Temur Mamisashvili","avatar":""},{"name":"Brahim Achabbakhe","avatar":""},{"name":"Jai Day","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Kevin Lee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324386);
