INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khun-phaen-huyen-thoai-bat-dau', 'Khun Phaen: Huyền Thoại Bắt Đầu', 'Khun Phean Begins', 'https://phimimg.com/upload/vod/20231103-1/05a7f6ef413389d234848183d66175a4.jpg', 'https://phimimg.com/upload/vod/20231103-1/b62f38ab756ae672ce65b4394f67b702.jpg', '<p>Khun Phaen Begins được thực hiện dựa trên tác phẩm văn học dân gian lớn nhất Thái Lan là Khun Chang Khun Phaen. Câu chuyện xoay quanh nhân vật chính tên Kaew (Mario Maurer), không nơi nương tựa lẫn kí ức, anh trở thành một trên trộm vặt lang thang khắp nơi, và rồi nhiều biến cố xảy ra khiến anh dần tìm lại ký ức. Khun Phaen: Huyền Thoại Bắt Đầu hứa hẹn sẽ là một là bộ phim đầy kịch tính về những ngày trước khi trở thành “siêu anh hùng” huyền thoại Khun Phaen của Kaew</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mario Maurer","avatar":""},{"name":"Philip Thinroj","avatar":""},{"name":"Yongwaree Ngamkasem","avatar":""},{"name":"Supakorn Kitsuwon","avatar":""},{"name":"Jade-Angelica Fromento","avatar":""},{"name":"Ruangrit Siripanich","avatar":""},{"name":"Nopachai Jayanama","avatar":""},{"name":"Pramote Seangsorn","avatar":""},{"name":"Sirinut Apijundej","avatar":""},{"name":"Apiwich Reardon","avatar":""},{"name":"Moniejaya Tanaryan","avatar":""},{"name":"Pakapon Tanphanich","avatar":""},{"name":"Nong Piyachot","avatar":""},{"name":"Jumpol Thon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
