INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khun-phaen-huyen-thoai-bat-dau', 'Khun Phaen: Huyền Thoại Bắt Đầu', 'Khun Phean Begins', 'khun phaen: huyền thoại bắt đầu khun phean begins mario maurer philip thinroj yongwaree ngamkasem supakorn kitsuwon jade-angelica fromento ruangrit siripanich nopachai jayanama pramote seangsorn sirinut apijundej apiwich reardon moniejaya tanaryan pakapon tanphanich nong piyachot jumpol thon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-nha-o-chuot', 'Siêu Nhân Nhà Ổ Chuột', 'The Ghetto Superman', 'null', 'https://phimimg.com/upload/vod/20231103-1/0dfb1bf55e03e36cc165066af55cc9fc.jpg', '<p>Hai mươi năm trước, một cặp cha con người ngoài hành tinh theo một thiên thạch rơi xuống trái đất... Trong một lần sự cố, Hoàng Tử Thần lòng ôm bất mãn với ngời ngoài hành tinh Lý Mặc Sâm, chờ dịp báo thù đều là không bệnh mà chết, thế là tiến áp dụng mê hoặc bằng sắc đẹp xong liền từ bỏ kế hoạch vạch trần ý đồ. Cùng lúc đó, Trần Thảo Mai, do nhặt được khoáng thạch ngoài hành tinh nên biến thành chuyên gia năng lượng cá sấu, vẫn luôn tìm kiếm cặp cha con này. Đồng thời, hắn cũng ngấp nghé kỹ thuật phân ly lượng tử của bố Hoàng Tử Thần. Kẻ thù chung của hai gia đình khiến vận mệnh của Lý Mặc Sâm và Hoàng Tử Thần trói buộc lại với nhau.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324386);
