INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-chien-binh', 'Sáu Chiến Binh', 'Foxtrot Six', 'https://phimimg.com/upload/vod/20231103-1/98329e4d6af433776f0b06f5e3665d5b.jpg', 'https://phimimg.com/upload/vod/20231103-1/0c0d857ae8c0cd92898072a36d126fe5.jpg', '<p>Một cựu lính thủy và những người bạn của anh ta đấu tranh để cứu Indonesia khỏi một nhà lãnh đạo đảng tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Oka Antara","avatar":""},{"name":"Rio Dewanto","avatar":""},{"name":"Verdi Solaiman","avatar":""},{"name":"Mike Lewis","avatar":""},{"name":"Arifin Putra","avatar":""},{"name":"Chicco Jerikho","avatar":""},{"name":"Julie Estelle","avatar":""},{"name":"Gisellma Firmansyah","avatar":""},{"name":"Miller Khan","avatar":""},{"name":"Edward Akbar","avatar":""},{"name":"Aurélie Moeremans","avatar":""},{"name":"Godfred Orindeod","avatar":""},{"name":"Norman R. Akyuwen","avatar":""},{"name":"Cok Simbara","avatar":""},{"name":"Willem Bevers","avatar":""},{"name":"Joshua Pandelaki","avatar":""},{"name":"Ario Pr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324386);
