INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-phi-thuong-cua-chu-cho-enzo', 'Cuộc Đời Phi Thường Của Chú Chó Enzo', 'The Art of Racing in the Rain', 'null', 'https://phimimg.com/upload/vod/20231103-1/c1a75687058b53980957189acc1780c0.jpg', '<p>Dựa trên tiểu thuyết ăn khách của Garth Stein, bộ phim đặt chúng ta vào góc nhìn và lời kể của chú chó Golden Retriever tên Enzo khi sống cùng gia đình của Denny Swift với người vợ xinh đẹp Eve và con gái Zoe. Sống cùng một tay đua thể thức một dày dạn kinh nghiệm như Denny khiến Enzo cũng yêu thích môn thể thao tốc độ này và chiếc tay lái của chiếc xe đua thể thực một cũng bẻ hướng cuộc đời của Enzo theo một cách phi thường nhất - Khám phá cuộc sống muôn màu của &quot;Sen&quot; qua cái nhìn của &quot;Boss&quot;.</p>', 'Full', 1, 'single', 'completed', 10, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Milo Ventimiglia","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Ian Lake","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"McKinley Belcher III","avatar":""},{"name":"Ryan Kiera Armstrong","avatar":""},{"name":"Lily Dodsworth-Evans","avatar":""},{"name":"Al Sapienza","avatar":""},{"name":"Andres Joseph","avatar":""},{"name":"Karen Holness","avatar":""},{"name":"Aliza Vellani","avatar":""},{"name":"Elizabeth Bowen","avatar":""},{"name":"Aias Dalman","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324386);
