INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-trong-tim', 'Lửa trong tim', 'Firebrand', 'https://phimimg.com/upload/vod/20231103-1/0f906cfb211c4aa36a4b7c472632634e.jpg', 'https://phimimg.com/upload/vod/20231103-1/d56ca3a9539a3f6dd1c239ce05a746b7.jpg', '<p>Mặc dù có thể giúp các khách hàng nữ giải quyết những vụ ly hôn khó khăn, ám ảnh về vụ tấn công tình dục lại ảnh hưởng đến chính cuộc hôn nhân của nàng luật sư.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Usha Jadhav","avatar":""},{"name":"Sachin Khedekar","avatar":""},{"name":"Girish Kulkarni","avatar":""},{"name":"Rajeshwari Sachdev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
