INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lua-trong-tim', 'Lửa trong tim', 'Firebrand', 'lửa trong tim firebrand usha jadhav sachin khedekar girish kulkarni rajeshwari sachdev ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-truoc-le-tot-nghiep', 'Đêm Trước Lễ Tốt Nghiệp', 'Booksmart', 'https://phimimg.com/upload/vod/20231103-1/875ef926f7468bf7f87418fa27289af7.jpg', 'https://phimimg.com/upload/vod/20231103-1/953177ff0a2ac62940fa6f857229c3da.jpg', '<p>Phim giới thiệu người xem về đôi bạn thân Molly và Amy. Họ đã dành trọn những năm tháng cấp 3 để học hành thật giỏi, vì mục tiêu lọt vào được những trường đại học danh giá nhất nước Mỹ. Vào ngày cuối cùng của năm học, Molly chợt phát hiện ra các bạn học cùng lớp mình cũng đã được vào các trường đại học danh giá kia, cho dù họ đã dành phần lớn thời gian để ăn chơi và tiệc tùng. Quá tức giận vì đã bỏ lỡ những buổi tiệc vui vẻ đó, Molly đã thuyết phục Amy cùng nhau dành trọn đêm còn lại trước ngày lễ tốt nghiệp, chỉ để tiệc tùng một lần cho biết. Liệu cả hai “mọt sách” này sẽ có thể tiệc tùng một cách trọn vẹn và an toàn nhất?</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Beanie Feldstein","avatar":""},{"name":"Kaitlyn Dever","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Victoria Ruesga","avatar":""},{"name":"Mason Gooding","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Diana Silvers","avatar":""},{"name":"Molly Gordon","avatar":""},{"name":"Billie Lourd","avatar":""},{"name":"Eduardo Franco","avatar":""},{"name":"Nico Hiraga","avatar":""},{"name":"Austin Crute","avatar":""},{"name":"Noah Galvin","avatar":""},{"name":"Michael Patrick","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324386);
