INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-truoc-le-tot-nghiep', 'Đêm Trước Lễ Tốt Nghiệp', 'Booksmart', 'đêm trước lễ tốt nghiệp booksmart beanie feldstein kaitlyn dever jessica williams jason sudeikis lisa kudrow will forte victoria ruesga mason gooding skyler gisondo diana silvers molly gordon billie lourd eduardo franco nico hiraga austin crute noah galvin michael patrick ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-gau-bac-cuc-truy-tim-co-vat', 'Đầu Gấu Bắc Cực: Truy Tìm Cổ Vật', 'Norm of the North: King Sized Adventure', 'https://phimimg.com/upload/vod/20231103-1/ac8ba6b6e46635c0577d5fb92033cb8f.jpg', 'https://phimimg.com/upload/vod/20231103-1/47c848112b67a82af053ed42c8957945.jpg', '<p>Trong lần trở lại này Norm sẽ giúp người dân Trung Hoa tìm lại một cổ vật thời cổ đại đã bị đánh cắp bởi Dexter - một nhà khảo cổ học có âm mưu xấu xa. Những tình huống khó khăn nhưng cũng không kém phần hài hước sẽ mang đến cho các khán giả những tràng cười ngất ngây.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andrew Toth","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Michael Dobson","avatar":""},{"name":"Simon Hayama","avatar":""},{"name":"Cole Howard","avatar":""},{"name":"Maya Feltheimer","avatar":""},{"name":"Jennifer Cameron","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Lisa Durupt","avatar":""},{"name":"Brian Dobson","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"Alan Marriott","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324386);
