INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('merry-va-bright', 'Merry và Bright', 'Merry and Bright', 'https://phimimg.com/upload/vod/20231111-1/fb5759f52dcbc8a19e27c289225b3c8a.jpg', 'https://phimimg.com/upload/vod/20231111-1/46c0736a90d6fe6009e5a252b2c28abc.jpg', '<p>Mẹ của Cate đang sắp xếp ngày xem mắt cho cô con gái CEO của mình. Một tuần trước Giáng sinh, Cate gặp Gabe và tưởng rằng anh là người mình hẹn hò, nhưng hoá ra anh ta là một tư vấn viên cho công ty kẹo của cô. Anh ấy cũng độc thân.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodie Sweetin","avatar":""},{"name":"Andrew W. Walker","avatar":""},{"name":"Nancy Sorel","avatar":""},{"name":"Paul Essiembre","avatar":""},{"name":"Stephanie Moroz","avatar":""},{"name":"Jason Wishnowski","avatar":""},{"name":"Pilar Floyd","avatar":""},{"name":"Sharon Lawrence","avatar":""},{"name":"Darren Martens","avatar":""},{"name":"Ryder Morcilla","avatar":""},{"name":"Candace Smith","avatar":""},{"name":"Derek James Trapp","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
