INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-the-la-anh-ay', 'Có Thể Là Anh Ấy', 'It Could Be Him', 'https://phimimg.com/upload/vod/20231111-1/56b4096806b10945586403100b6c199a.jpg', 'https://phimimg.com/upload/vod/20231111-1/5a6951e7d95611bcb79c1316a28adf94.jpg', '<p>Một nữ y tá vừa chia tay bạn trai hiện đang độc thân và sẵn sàng hòa nhập. Cô ấy đang được tiếp cận bởi hai chàng trai là bạn thân. Tình hình trở nên phức tạp hơn khi chỉ có một anh hùng trong mỗi bộ phim lãng mạn nên cả hai phải chiến đấu để giành được trái tim của mình. Họ càng đến gần cô ấy, cô ấy càng hiểu rõ hơn về trái tim của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sattaphong Phiangphor","avatar":""},{"name":"Ruangrit Siripanich","avatar":""},{"name":"Chonnipha Wisetsood","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324386);
