INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-hac-am-2', 'Tiên Hắc Ám 2', 'Maleficent: Mistress of Evil', 'https://phimimg.com/upload/vod/20231103-1/28af4f6d608f3382070cc31b3511e31b.jpg', 'https://phimimg.com/upload/vod/20231103-1/54ad03f946ea2c47b4b02852b822cbeb.jpg', '<p>Thời gian trôi qua thật bình yên với Maleficent và Aurora. Mặc dù mối quan hệ của cả hai được tạo dựng từ những tổn thương, thù hận rồi sau đó mới đến tình yêu thương nhưng cuối cùng thì nó cũng đã đơm hoa kết trái. Tuy vậy, xung đột giữa hai giới: loài người và tiên tộc vẫn vẫn luôn hiện hữu. Cuộc hôn nhân vốn bị trì hoãn giữa Aurora và Hoàng tử Phillips chính là cầu nối gắn kết Vương quốc Ulstead và nước láng giềng Moors lại với nhau. &nbsp;Bất ngờ thay, sự xuất hiện của một phe đồng minh hoàn toàn mới sẽ khiến Maleficent và Aurora bị chia cắt về hai chiến tuyến trong trận Đại Chiến. Trận chiến này sẽ thử thách lòng tin lẫn tình cảm của cả hai. Liệu rằng họ có thật sự trở thành một gia đình hay không? Tất cả sẽ được giải đáp trong Maleficent: Mistress of Evil/ Tiên Hắc Ám 2.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"Robert Lindsay","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Jenn Murray","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Judi Shekoni","avatar":""},{"name":"MIYAVI","avatar":""},{"name":"Kae Alexander","avatar":""},{"name":"Warwick Davis","avatar":""},{"name":"Emma Ma","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324386);
