INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-gai-toi', 'EM GÁI TÔI', 'My Little Sister', 'https://phimimg.com/upload/vod/20231103-1/130d0f5598de5d7f1a20d4eda477f9e4.jpg', 'https://phimimg.com/upload/vod/20231103-1/25ecd81b7444c2125367ce53829c9a8a.jpg', '<p><strong>Em Gái Tôi</strong> lấy bối cảnh trong cuộc Chiến tranh Vệ quốc vĩ đại của nhân dân Liên Xô chống phát xít Đức trong thế chiến thứ 2. Cô bé Ukraina Oksana, mất cha mẹ, tìm thấy mình ở một ngôi làng nhỏ heo hút trên miền núi cao tuyết trắng thuộc nước Cộng hòa Bashkortostan nhỏ nhắn thuộc Liên bang Nga, nơi cô được sống trong một gia đình mới.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Arslan Krymchurin","avatar":""},{"name":"Marta Timofeeva","avatar":""},{"name":"Yusuf Rakhmetov","avatar":""},{"name":"Ilgiza Gilmanova","avatar":""},{"name":"Sulpan Abdrahimova","avatar":""},{"name":"Rauis Zagitov","avatar":""},{"name":"Vitalii Salii","avatar":""},{"name":"Nazhiba Iskandarova","avatar":""},{"name":"Ruslan Khaysarov","avatar":""},{"name":"Gulnaz Khaysarova","avatar":""},{"name":"Sagidulla Baizigitov","avatar":""},{"name":"Irada Kadyrova","avatar":""},{"name":"Vladimir Kuzin","avatar":""},{"name":"Fanis Rakhmetov","avatar":""},{"name":"Timur","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
