INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-vu-hiep-quan-son', 'Ma Thổi Đèn: Vu Hiệp Quan Sơn', 'Raiders of the Wu Gorge', 'https://phimimg.com/upload/vod/20231102-1/6c75f426d10160df36b6c164005974a8.jpg', 'https://phimimg.com/upload/vod/20231102-1/343b15ad7cb4cf650e38bd23c0377553.jpg', '<p>Sự mang thai ngoài ý muốn của Shirley Yang, mang đến nhiều áp lực đối với Hu Bayi, người bị mắc kẹt trong một lời nguyền đẫm máu. Theo lời mời khảo cổ của Giáo sư Sun, ông biết rằng trong khu di tích lịch sử Feng, mở 12 năm một lần ở làng Dixian, có thể có những xác chết có thể loại bỏ lời nguyền. Với sự giúp đỡ của Yaomei, bộ ba kẻ cướp mộ huyền thoại đã vào núi một lần nữa để chiến đấu sinh tồn.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Zuo","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"Mi Te","avatar":""},{"name":"Wang Xinru","avatar":""},{"name":"Liang Guorong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324386);
