INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-quai-sieu-cap-tri-ky-quai-vat', 'Hội quái siêu cấp: Tri kỷ Quái vật', 'Super Monsters Furever Friends', 'https://phimimg.com/upload/vod/20231102-1/602b9df498d645c27fe86c8f69d4f07b.jpg', 'https://phimimg.com/upload/vod/20231102-1/91da3155f98210e47c4818b9a872bbc4.jpg', '<p>Vào đêm đầu tiên của mùa xuân, các Siêu quái vật tụ họp để ăn uống và vui chơi trong công viên – cũng như để gặp mặt các thú cưng dễ thương mới!</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Elyse Maloway","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Erin Mathews","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Alessandro Juliani","avatar":""},{"name":"Nicole Anthony","avatar":""},{"name":"Diana Kaarina","avatar":""},{"name":"Ian James Corlett","avatar":""},{"name":"Britt McKillip","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Elishia Perosa","avatar":""},{"name":"Nathan Witte","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Edward Foy","avatar":""},{"name":"Maria J. Cruz","avatar":""},{"name":"Ingrid N","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324386);
