INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-nuoc-toi', 'Dòng Nước Tối', 'Dark Waters', 'https://phimimg.com/upload/vod/20231102-1/b88d7eeee241b75106b49f5ac41f5205.jpg', 'https://phimimg.com/upload/vod/20231102-1/62bd993d7a5e47b62be6352a70161132.jpg', '<p>Dòng Nước Tối là bộ phim dựa trên một sự kiện có thật, kể về một luật sư sẵn sàng đánh đổi tất cả, từ gia đình đến sự nghiệp, để đánh tranh chống lại một tập đoàn công nghiệp hàng đầu. Robert Bilott (Mark Ruffalo) là một luật sư mẫn cán. Anh được người dân địa phương thuê để tìm sự liên kết giữa các hiện tượng động vật chết và sức khỏe cộng đồng bị sụt giảm. Qua điều tra, Bilott phát hiện tập đoàn DuPont đang bí mật thải các chất độc hại ra môi trường suốt 4 năm qua. Các vụ kiện tụng diễn ra và không thiếu những lời đe dọa nhằm vào Bilott, liệu anh có thể đứng vững trước một trong những thế lực công nghiệp lớn nhất tại Mỹ?</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Ruffalo","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Mare Winningham","avatar":""},{"name":"William Jackson Harper","avatar":""},{"name":"Louisa Krause","avatar":""},{"name":"Kevin Crowley","avatar":""},{"name":"Bruce Cromer","avatar":""},{"name":"Denise Dal Vera","avatar":""},{"name":"Richard Hagerman","avatar":""},{"name":"Abi Van Andel","avatar":""},{"name":"John Newberg","avatar":""},{"name":"Barry Mulholland","avatar":""},{"name":"Jeffre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324386);
