INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-da-den-cuoi-cung-o-san-francisco', 'Người da đen cuối cùng ở San Francisco', 'The Last Black Man in San Francisco', 'https://phimimg.com/upload/vod/20231102-1/29aefb8566bbbef0db066452305facd4.jpg', 'https://phimimg.com/upload/vod/20231102-1/6fe8c5e0e144a66a2a0e7c7f51debf1d.jpg', '<p>Chán nản khi thấy thành phố lột xác và thay đổi quá nhanh, Jimmie quyết định thực hiện ước mơ và cùng một người bạn chuyển về sống trong ngôi nhà rộng lớn của ông mình.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jimmie Fails","avatar":""},{"name":"Jonathan Majors","avatar":""},{"name":"Tichina Arnold","avatar":""},{"name":"Rob Morgan","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Finn Wittrock","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Isiain Lalime","avatar":""},{"name":"Jamal Trulove","avatar":""},{"name":"Jordan Gomes","avatar":""},{"name":"Maximilienne Ewalt","avatar":""},{"name":"Jello Biafra","avatar":""},{"name":"San Quinn","avatar":""},{"name":"Daewon Song","avatar":""},{"name":"Willie Hen","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Tonya Glanz","avatar":""},{"name":"Sergio Gonzalez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324386);
