INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('37-giay', '37 Giây', '37 Seconds', 'https://phimimg.com/upload/vod/20231101-1/80be01919c469bdda5560b5dabae3c70.jpg', 'https://phimimg.com/upload/vod/20231101-1/3b2270c844d3e4d5f0b184ead7c03ca2.jpg', '<p>Mắc kẹt giữa tiêu chuẩn xã hội và bổn phận làm con, một họa sĩ manga trẻ tuổi bước vào hành trình khác thường để khám phá tự do tình dục và giải phóng bản thân.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mei Kayama","avatar":""},{"name":"Misuzu Kanno","avatar":""},{"name":"Shunsuke Daitoh","avatar":""},{"name":"Makiko Watanabe","avatar":""},{"name":"Yoshihiko Kumashino","avatar":""},{"name":"Minori Hagiwara","avatar":""},{"name":"Haruka Imou","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Shohei Uno","avatar":""},{"name":"Eita Okuno","avatar":""},{"name":"Shizuka Ishibashi","avatar":""},{"name":"Toshinori Omi","avatar":""},{"name":"Yuka Itaya","avatar":""},{"name":"Nanami Kawakami","avatar":""},{"name":"Nobu Morimoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
