INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-cua-rush', 'Giáng Sinh của Rush', 'Holiday Rush', 'https://phimimg.com/upload/vod/20231101-1/0b7b515808c9faa1fc2c747be2cfa8f0.jpg', 'https://phimimg.com/upload/vod/20231101-1/e1ba062065dc76cf62b8ff78fed63c72.jpg', '<p>Một DJ radio góa vợ và bốn đứa con bị chiều hư phải thắt lưng buộc bụng và nương tựa lẫn nhau khi cuộc sống xa hoa tan biến ngay trước Giáng Sinh.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sonequa Martin-Green","avatar":""},{"name":"La La Anthony","avatar":""},{"name":"Deon Cole","avatar":""},{"name":"Stormi Maya","avatar":""},{"name":"Tamala Jones","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Roscoe Orman","avatar":""},{"name":"Darlene Love","avatar":""},{"name":"Amarr M. Wooten","avatar":""},{"name":"Jimmy Palumbo","avatar":""},{"name":"Deysha Nelson","avatar":""},{"name":"Andrea-Marie Alphonse","avatar":""},{"name":"Selena-Marie Alphonse","avatar":""},{"name":"Alysia Livingston","avatar":""},{"name":"Malika Samuel","avatar":""},{"name":"Rocco Paren","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324387);
