INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-soi-hanh-dong', 'Bầy Sói Hành Động', 'Operation Wolves', 'https://phimimg.com/upload/vod/20231101-1/b0c8f33383b78951abc6e93dd59d3218.jpg', 'https://phimimg.com/upload/vod/20231101-1/dc010e3ca2cda4fa9b24b1a1bc1162d4.jpg', '<p>Li Yao là một tình nguyện viên y tế tại làng Aid, anh bất ngờ bị bọn cướp tấn công và bắt giữ. Cha của Li Yao đã liên lạc với đội cảnh sát Zhang Zhen và Wu You để cứu anh. Đội an ninh cứu Li Yao, nhưng một số người còn lại vẫn bị bọn cướp bắt giữ. Các thành viên đội cảnh sát đã có một cuộc chiến khốc liệt với bọn cướp để giải thoát cho những người đã bị bắt.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kaiyu Xie","avatar":""},{"name":"Li Junyao","avatar":""},{"name":"Joel Adrian","avatar":""},{"name":"Chen Xingyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
