INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-hoang-tan', 'Đêm Hoang Tàn', 'Hard Night Falling', 'https://phimimg.com/upload/vod/20231101-1/813e2ce242864155017c2855e7c86347.jpg', 'https://phimimg.com/upload/vod/20231101-1/3105acedbad81358d0243d440efef1ea.jpg', '<p>Sau một hoạt động của Interpol ở Ý, Michael tham dự một bữa tiệc tối của công ty thì bất ngờ, 50 khách bị bắt làm con tin bởi 15-20 người có vũ trang với giá 150.000.000 đô la tại đây.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Hal Yamanouchi","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Mario Opinato","avatar":""},{"name":"Brice Martinet","avatar":""},{"name":"Andrea Scarduzio","avatar":""},{"name":"Sinne Mutsaers","avatar":""},{"name":"Ralph Palka","avatar":""},{"name":"Ruben Rigillo","avatar":""},{"name":"Gioia Vicari","avatar":""},{"name":"Yoon C. Joyce","avatar":""},{"name":"Chiara Arrigoni","avatar":""},{"name":"Marianella Bargilli","avatar":""},{"name":"Giampiero Mancini","avatar":""},{"name":"Giulio Greco","avatar":""},{"name":"Fabrizio Jovine","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324387);
