INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-kiem-ha-thien-son-tu-la-nhan', 'Thất Kiếm Hạ Thiên Sơn: Tu La Nhãn', 'The Seven Swords', 'https://phimimg.com/upload/vod/20231101-1/6f2cda27f274764a6c02b413e78167f5.jpg', 'https://phimimg.com/upload/vod/20231101-1/bb338b4fe3ca0d963c21f61580c48b5c.jpg', '<p>Nội dung phim xoay quanh cuộc chiến tranh giành Ta Lu Nhãn giữa các thế lực trong giang hồ và triều đình, cùng những ân oán không hồi kết. Câu chuyện bắt đầu từ việc xuất hiện một bảo vật có sức mạnh kinh khủng, Dương Vân Thông, Thần Điệu Môn &nbsp;và triều đình truy tìm. Tuy nhiên, Vân Thông bị đánh trọng thương, được thiếu niên Mục Lang giúp đỡ, nhưng cuối cùng không ai biết Ma Nhãn ở đâu. 16 năm sau, Tu La Vương tái xuất và tàn sát giang hồ, Mục Lang một lần nữa phải giải mật hàm để cứu mọi người.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Zhuowen","avatar":""},{"name":"Chen Jie","avatar":""},{"name":"An Ziyi","avatar":""},{"name":"Yu Sichu","avatar":""},{"name":"Fei Long","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324387);
