INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-lua-dao', 'Quý Cô Lừa Đảo', 'The Hustle', 'https://phimimg.com/upload/vod/20231029-1/1c311d13388202318e24a5cac12de3ab.jpg', 'https://phimimg.com/upload/vod/20231029-1/402365a8eb66effa4e6001685958b6a1.jpg', '<p>Bộ phim tình cảm hài hước xoay quanh câu chuyện của 2 cô nàng lừa đảo chuyên nghiệp. Trong khi Rebel Wilson vào vai nàng nghệ sĩ lừa đảo “hạng xoàng” thì Anne Hathaway lại đáo để với những phi vụ và con mồi đắt giá hơn. Cả hai cùng hợp tác để khiến những gã đàn ông tồi tệ “chạy biến” khỏi số tiền của chính họ.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Alex Sharp","avatar":""},{"name":"Ingrid Oliver","avatar":""},{"name":"Hannah Waddingham","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Douggie McMeekin","avatar":""},{"name":"Ashley McGuire","avatar":""},{"name":"Casper Christensen","avatar":""},{"name":"Eloise Lovell Anderson","avatar":""},{"name":"Philip Desmeules","avatar":""},{"name":"Jarreau Antoine","avatar":""},{"name":"Celine Abrahams","avatar":""},{"name":"Raffaello Degru","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324387);
