INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-va-ga-lang-thang-2019', 'Tiểu Thư và Gã Lang Thang', 'Lady and the Tramp', 'https://phimimg.com/upload/vod/20231030-1/9c7b18f935ebeee4ed3261da9d95a9da.jpg', 'https://phimimg.com/upload/vod/20231030-1/1e6e255452b3d920899c2a92c02cfea6.jpg', '<p>Câu chuyện tình yêu giữa chú gà trống được nuông chiều tên Lady và chú chó lai lang thang tên Tramp. Lady thấy mình trên đường sau khi chủ nhân của cô có con và được Tramp cứu khỏi một bầy đàn, người cố gắng dạy cô sống cuộc sống không mặc quần áo và không đeo cổ.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tessa Thompson","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Ashley Jensen","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Janelle Monáe","avatar":""},{"name":"Yvette Nicole Brown","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Nate \"Rocket\" Wonder","avatar":""},{"name":"Parvesh Cheena","avatar":""},{"name":"F. Murray","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
