INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-thuy-danh-bo-luat-hoi-huong', 'Lính Thủy Đánh Bộ: Luật Hồi Hương', 'Jarhead: Law of Return', 'https://phimimg.com/upload/vod/20231030-1/9af6b04c8166732fef32dfd2a4159631.jpg', 'https://phimimg.com/upload/vod/20231030-1/a5e96655e14a75278b93b0d8625ff727.jpg', '<p>Thiếu tá Ronan Jackson (Devon Sawa), một phi công chiến đấu tài ba cho Lực lượng Quốc phòng Israel và con trai của Thượng nghị sĩ Hoa Kỳ (Robert Patrick), bị bắn hạ khi đang bay qua không phận Syria. Sau khi sống sót một cách kỳ diệu, Jackson bị một nhóm dân quân Hezbollah bắt giữ. Câu chuyện hấp dẫn và đầy sức mạnh với hành động khó nhằn, Jarhead: Law of Return theo chân một đội quân tinh nhuệ, do Trung sĩ xạ thủ Dave Torres (Amaury Nolasco) lãnh đạo, vì họ liều mạng với hy vọng cứu được đồng minh. đã không bao giờ gặp nhau.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'HD', 'Israel', 0, '[{"name":"Yael Eitan","avatar":""},{"name":"Nicholas Aaron","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Tsahi Halevi","avatar":""},{"name":"Shanti Ashanti","avatar":""},{"name":"Jeff Pierre","avatar":""},{"name":"Udi Razzin","avatar":""},{"name":"Amos Tamam","avatar":""},{"name":"George Zlatarev","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324387);
