INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-bong-toi-cua-mat-trang', 'Trong Bóng Tối Của Mặt Trăng', 'In the Shadow of the Moon', 'https://phimimg.com/upload/vod/20231026-1/c352c7b49c345824a469f7a83f636beb.jpg', 'https://phimimg.com/upload/vod/20231026-1/cdc8887d693d7785df9fb0f319ae2b3c.jpg', '<p>Năm 1988, sĩ quan cảnh sát Philadelphia Thomas &quot;Locke&quot; Lockhart, khao khát trở thành thám tử, bắt đầu truy tìm một kẻ giết người hàng loạt có tội ác bất chấp lời giải thích khoa học. Khi kẻ giết người tái xuất hiện một cách bí ẩn 9 năm sau, nỗi ám ảnh về việc tìm ra sự thật của Locke có nguy cơ hủy hoại sự nghiệp, gia đình và có thể cả sự tỉnh táo của anh.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Boyd Holbrook","avatar":""},{"name":"Cleopatra Coleman","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Sarah Dugdale","avatar":""},{"name":"Rudi Dharmalingam","avatar":""},{"name":"Rachel Keller","avatar":""},{"name":"Quincy Kirkwood","avatar":""},{"name":"Philippa Domville","avatar":""},{"name":"Tony Nappo","avatar":""},{"name":"Al Maini","avatar":""},{"name":"Ryan Allen","avatar":""},{"name":"Tony Craig","avatar":""},{"name":"Gabrielle Graham","avatar":""},{"name":"Julia Knope","avatar":""},{"name":"Nicolas Van Burek","avatar":""},{"name":"Murray","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
