INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ao-den-su-menh-toan-cau', 'Đặc Vụ Áo Đen: Sứ Mệnh Toàn Cầu', 'Men in Black: International', 'https://phimimg.com/upload/vod/20231026-1/b9ce89abb4cfcb29b95795ed7aed6708.jpg', 'https://phimimg.com/upload/vod/20231026-1/776cef2985baa4419aea03ac9bdd9205.jpg', '<p>Những đặc vụ áo đen là người bảo vệ trái đất khỏi mối đe dọa từ các sinh vật ngoài hành tinh. Trong cuộc phiêu lưu mới này, nhiệm vụ của họ ngày càng trở nên nguy hiểm hơn khi phải đối đầu với một nội gián trong chính tổ chức của mình. Men In Black International là spin-off của siêu phẩm Men In Black nổi tiếng, do Chris Hemsworth, Tessa Thompson và Lian Neeson thủ vai chính.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Laurent Bourgeois","avatar":""},{"name":"Larry Bourgeois","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Mandeiya Flory","avatar":""},{"name":"Kayvan Novak","avatar":""},{"name":"Annie Burkin","avatar":""},{"name":"Tim Blaney","avatar":""},{"name":"Spencer Wilding","avatar":""},{"name":"Marcy Harriell","avatar":""},{"name":"Inny Clemons","avatar":""},{"name":"Thom Fou","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324387);
