INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-nhan-ban', 'Sinh Vật Nhân Bản', 'Assimilate', 'https://phimimg.com/upload/vod/20231026-1/1bc82d1b524a185ab137ccaefe1a06e0.jpg', 'https://phimimg.com/upload/vod/20231026-1/43fddd91ae8bdd024337fbff308d5655.jpg', '<p>Assimilate là bộ phim kinh dị mới kể về 3 bạn trẻ khám phá những điều đang xảy ra kỳ lạ của người dân trong thị trấn. Điển hình như Kayla phát hiện ra cha của mình có biểu hiện bất bình thường, ông ít nói, mặt không cảm xúc, và rồi Kayla cùng Randy và Zach tìm hiểu nguyên nhân khi cả thị trấn đều có chung một biểu hiện bất thường. Về sau họ thấy một loài sinh vật ghê rợn cố gắng tìm cách ăn thịt khi thấy con người, sau đó nó sẽ biến hoá thành một bản sao của chính nạn nhân nó giết. Hoá ra cả thị trấn đều bị giết hại bởi loài sinh vật này và chúng nhân bản với tốc độ chóng mặt</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andi Matichak","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Calum Worthy","avatar":""},{"name":"Jessica Medina","avatar":""},{"name":"Joel Courtney","avatar":""},{"name":"Katherine McNamara","avatar":""},{"name":"Mason McNulty","avatar":""},{"name":"John Murlowski","avatar":""},{"name":"Terry Dale Parks","avatar":""},{"name":"Vito Viscuso","avatar":""},{"name":"Kyler Porche","avatar":""},{"name":"Cotton Yancey","avatar":""},{"name":"Ryan Wiltshire","avatar":""},{"name":"Christina Michelle Williams","avatar":""},{"name":"Calvin Williams","avatar":""},{"name":"Martin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"