INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doom-diet-vong', 'Doom: Diệt Vong', 'Doom: Annihilation', 'https://phimimg.com/upload/vod/20231026-1/351e36947dc30f32296ad9eadea71ec8.jpg', 'https://phimimg.com/upload/vod/20231026-1/49007ba7ca0cf4def91d0d6a45e53f39.jpg', '<p>Annihilation sẽ theo chân một nhóm chiến sĩ quân đội chuyên thực hiện các nhiệm vụ ngoài không gian. Họ bỗng nhận được một cuộc gọi cầu cứu đến từ căn cứ trên sao Hỏa. Khi cả nhóm đặt chân tới, nơi này đã bị vây chiếm bởi những ác quỷ đến từ cổng địa ngục và có khả năng sẽ lan rộng đến cả Trái Đất.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Manson","avatar":""},{"name":"Luke Allen-Gale","avatar":""},{"name":"Nina Bergman","avatar":""},{"name":"Dominic Mafham","avatar":""},{"name":"James Weber Brown","avatar":""},{"name":"Lorina Kamburova","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Jemma Moore","avatar":""},{"name":"Katrina Nare","avatar":""},{"name":"Chidi Ajufo","avatar":""},{"name":"Gavin Brocker","avatar":""},{"name":"Cassidy Little","avatar":""},{"name":"Arkie Reece","avatar":""},{"name":"Nathan Cooper","avatar":""},{"name":"Clayton Adams","avatar":""},{"name":"Amar Chadha-Patel","avatar":""},{"name":"Hari Dhill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324387);
