INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-dung-co-gai-tren-ngon-lua', 'Chân Dung Cô Gái Trên Ngọn Lửa', 'Portrait of a Lady on Fire', 'https://phimimg.com/upload/vod/20231026-1/3a62586033606b0f0dbb972a3188e281.jpg', 'https://phimimg.com/upload/vod/20231026-1/77879f280acba691d8fe530c65d78848.jpg', '<p>Trên một hòn đảo biệt lập ở Brittany vào cuối thế kỷ XVIII, một nữ họa sĩ có nghĩa vụ vẽ một bức chân dung đám cưới của một phụ nữ trẻ.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Noémie Merlant","avatar":""},{"name":"Adèle Haenel","avatar":""},{"name":"Luàna Bajrami","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Christel Baras","avatar":""},{"name":"Armande Boulanger","avatar":""},{"name":"Guy Delamarche","avatar":""},{"name":"Clément Bouyssou","avatar":""},{"name":"Michèle Clément","avatar":""},{"name":"Cécile Morel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324387);
