INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kip-luyen-rong-tro-ve-nha', 'Bí Kíp Luyện Rồng: Trở Về Nhà', 'How to Train Your Dragon: Homecoming', 'https://phimimg.com/upload/vod/20231026-1/b1355a8a9abf942d99da32f640f529ca.jpg', 'https://phimimg.com/upload/vod/20231026-1/73d6db35a95524438bb32d20a46cd05c.jpg', '<p>Đã mười năm kể từ khi những con rồng chuyển đến Thế giới ẩn, và mặc dù Toothless không sống ở New Berk nữa, Hiccup vẫn tiếp tục truyền thống kỳ nghỉ mà anh từng chia sẻ với người bạn thân nhất của mình. Nhưng những người Viking ở New Berk đã bắt đầu quên đi tình bạn của họ với rồng. Hiccup, Astrid và Gobber không biết phải làm gì để giữ những con rồng trong lòng dân làng. Và trên biển, những con rồng có một kế hoạch của riêng mình ...</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jay Baruchel","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
