INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-dao-ca-sau-tu-than', 'Địa Đạo Cá Sấu Tử Thần', 'Crawl', 'https://phimimg.com/upload/vod/20231025-1/e87b14765a5c2edd9e1bd50f2a709606.jpg', 'https://phimimg.com/upload/vod/20231025-1/fb61b44d3fe778a677a49a121e1a9b0a.jpg', '<p>Khi một cơn bão cấp 5 quét qua Florida, Haley vội vã đi tìm cha cô đang bị thương và mắc kẹt dưới gầm nhà của họ. Khi cơn bão mạnh lên và mực nước dâng cao, hai người phải đối mặt với một mối đe dọa thậm chí còn đáng sợ hơn nữa đang ẩn nấp dưới mặt nước. Từ nhà sản xuất Sam Raimi (Evil Dead) và đạo diễn Alexandre Aja (The Hills Have Eyes), Địa Đạo Cá Sấu Tử Thần là một phim kinh dị gây run sợ từ đầu đến cuối.</p>', 'Full', 1, 'single', 'completed', 21, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kaya Scodelario","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Morfydd Clark","avatar":""},{"name":"Ross Anderson","avatar":""},{"name":"Jose Palma","avatar":""},{"name":"George Somner","avatar":""},{"name":"Anson Boon","avatar":""},{"name":"Ami Metcalf","avatar":""},{"name":"Tina Pribićević","avatar":""},{"name":"Srna Vasiljević","avatar":""},{"name":"Colin McFarlane","avatar":""},{"name":"Annamaria Serda","avatar":""},{"name":"Savannah Steyn","avatar":""},{"name":"Cso-Cso","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324387);
