INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-khach-khieu-tinh', 'Vị Khách Khiêu Tình', 'Curiosa', 'https://phimimg.com/upload/vod/20231025-1/09dbf56519fd674a4fdcfa2d37e0ead9.jpg', 'https://phimimg.com/upload/vod/20231025-1/0a3d6d9360420b416caf7c4391516315.jpg', '<p>Để trả hết nợ cho cha, Marie de Heredia kết hôn với nhà thơ Henri de Regnier, nhưng đó là Pierre Louÿs, người mà cô yêu, một nhà thơ cũng là một người khiêu dâm và là một du khách tuyệt vời. Đó là với anh ta rằng cô sẽ sống một khởi đầu cho tình yêu và khiêu dâm thông qua liên kết nhiếp ảnh và văn học mà họ phát minh ra cùng nhau. Một câu chuyện tình yêu say đắm tự do tình dục, dựa trên mối quan hệ giữa tác giả Pierre Loüys và Marie de Régnier ở thế kỷ 19.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Noémie Merlant","avatar":""},{"name":"Niels Schneider","avatar":""},{"name":"Benjamin Lavernhe","avatar":""},{"name":"Camélia Jordana","avatar":""},{"name":"Amira Casar","avatar":""},{"name":"Scali Delpeyrat","avatar":""},{"name":"Mathilde Warnier","avatar":""},{"name":"Mélodie Richard","avatar":""},{"name":"Emilien Diard-Detoeuf","avatar":""},{"name":"Damien Bonnard","avatar":""},{"name":"Guilhem Fabre","avatar":""},{"name":"Alexia Giordano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324387);
