INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-do-bay-chu-lun', 'Hài Đỏ & Bảy Chú Lùn', 'Red Shoes and the Seven Dwarfs', 'https://phimimg.com/upload/vod/20231025-1/13207147cf10cea294ab1a1207dc1cd1.jpg', 'https://phimimg.com/upload/vod/20231025-1/8de2236bc008ee99ba7b530722066b6b.jpg', '<p>7 chàng hoàng tử vì bị phù phép mà biến thành 7 chú lùn da xanh. Muốn hóa giải lời nguyền ác độc này, họ phải có được tình yêu chân thành từ cô gái mang đôi hài đỏ xinh đẹp nhất trần đời. Đến một ngày, nàng Hài Đỏ đã tìm đến ngôi nhà của 7 chú lùn, nhưng việc hóa giải lời nguyền lại không đơn giản đến thế…</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Simon Kassianides","avatar":""},{"name":"Frederik Hamel","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Frank Todaro","avatar":""},{"name":"Ava Kolker","avatar":""},{"name":"Asher Blinkoff","avatar":""},{"name":"Juju Journey Brener","avatar":""},{"name":"Brian T. Delaney","avatar":""},{"name":"Piotr Michael","avatar":""},{"name":"Ben Diskin","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Terri Do","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
