INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-do-bay-chu-lun', 'Hài Đỏ & Bảy Chú Lùn', 'Red Shoes and the Seven Dwarfs', 'hài đỏ & bảy chú lùn red shoes and the seven dwarfs chloë grace moretz sam claflin gina gershon patrick warburton jim rash simon kassianides frederik hamel nolan north frank todaro ava kolker asher blinkoff juju journey brener brian t. delaney piotr michael ben diskin kari wahlgren terri do ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('salma-va-dieu-uoc-nhiem-mau', 'Salma và Điều Ước Nhiệm Màu', 'Salma''s Big Wish', 'https://phimimg.com/upload/vod/20231024-1/a85d033a21a3f50bc490d8c17fd50811.jpg', 'https://phimimg.com/upload/vod/20231024-1/e1873faf8f43d2e000a2de2ee11c480a.jpg', '<p>Tại thị trấn Santa Clara của Mexico, Salma là một đứa trẻ mồ côi 16 tuổi chưa bao giờ được gặp cha mẹ ruột. Câu chuyện duy nhất cô bé được nghe kể là họ đã bỏ rơi cô. Salma dành phần lớn cuộc đời của mình để tìm kiếm manh mối về danh tính của cha mẹ và nơi ở của họ. Cho đến một ngày, cô phát hiện ra một cuốn sách đặc biệt chứa đựng những câu chuyện về Santa Clara và lịch sử dân tộc. Lấy cảm hứng từ cuốn sách đặc biệt này, Salma bắt đầu cuộc phiêu lưu với hai anh em nuôi dũng cảm và tốt bụng của mình, Jorge và Pedro, để tìm ra mối liên hệ với di sản của gia đình với hy vọng cuối cùng là gặp cha mẹ.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2019, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Fernanda Castillo","avatar":""},{"name":"Alan Estrada","avatar":""},{"name":"Memo Aponte","avatar":""},{"name":"Carlo Rota","avatar":""},{"name":"Susana Ballesteros","avatar":""},{"name":"Dani Artaud","avatar":""},{"name":"Jewels Jaselle","avatar":""},{"name":"Emma Prat","avatar":""},{"name":"Cristina Milizia","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
