INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pokemon-tham-tu-pikachu', 'Pokémon: Thám Tử Pikachu', 'Pokémon Detective Pikachu', 'https://phimimg.com/upload/vod/20231024-1/785af0f217d3eaffbc4db288f9ac3def.jpg', 'https://phimimg.com/upload/vod/20231024-1/fc1805754365e37f7e2cf673cd3a1b13.jpg', '<p>Tim Goodman có ước mơ làm huấn luyện viên Pokémon nhưng đã từ bỏ kể từ khi cha anh mất tích trong một vụ tai nạn. Một hôm anh phát hiện ra một chú Pikachu đi lạc vào nhà mình và đáng ngạc nhiên là anh hiểu được nó nói gì và cả 2 nhanh chóng trở thành bạn.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Justice Smith","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Omar Chaparro","avatar":""},{"name":"Chris Geere","avatar":""},{"name":"Rita Ora","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Josette Simon","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Alejandro De Mesa","avatar":""},{"name":"Max Fincham","avatar":""},{"name":"Simone Ashley","avatar":""},{"name":"Edward Davis","avatar":""},{"name":"Diplo","avatar":""},{"name":"Ben Fox","avatar":""},{"name":"Kadiff Kirwan","avatar":""},{"name":"Ryoma Tak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
