INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-dao-tau-giai-cuu', 'Kế Hoạch Đào Tẩu: Giải Cứu', 'Escape Plan: The Extractors', 'https://phimimg.com/upload/vod/20231024-1/8bb2bc3d91050154247a477ebb19030f.jpg', 'https://phimimg.com/upload/vod/20231024-1/e7918e8a44bcf9a8f0493dbc7ef0ff9f.jpg', '<p>Phần 3 của Kế Hoạch Đào Tẩu là một câu chuyện hoàn toàn mới. Lần này, chuyên gia an ninh Ray Breslin (Stallone) được thuê để giải cứu con gái của một nhà tài phiệt bị bắt cóc tại nhà tù bí ẩn mang tên Trạm Quỷ. Cộng sự của ông gồm có tay cung cấp vũ khí Trent (Dave Bautista) và hacker Hush (50 Cent). Sen Lo (Trương Tấn) – bạn trai của con tin cũng bất ngờ xuất hiện và đồng hành cùng nhóm trong cuộc giải cứu. Tuy nhiên, khi họ bước vào Trạm Quỷ cũng là lúc họ rơi vào chiếc bẫy chết người. Không những phải đối đầu với kẻ thù tàn bạo, nhóm còn phải chạy đua với thời gian để giải thoát các con tin khỏi tay tử thần.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Zhang Jin","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Melise","avatar":""},{"name":"Russell Wong","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Rob de Groot","avatar":""},{"name":"Holland Herzfeld","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Tony DeMil","avatar":""},{"name":"Shea Buckner","avatar":""},{"name":"Justin Yu","avatar":""},{"name":"Heidi Lewa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
