INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('everest-nguoi-tuyet-be-nho', 'Everest: Người Tuyết Bé Nhỏ', 'Abominable', 'https://phimimg.com/upload/vod/20231024-1/f8ecc6cb19ea10c801ceeb6b76ddf1b0.jpg', 'https://phimimg.com/upload/vod/20231024-1/575fca16531b4d8f3b5ff2a7eeb569c8.jpg', '<p>Khi cô gái tuổi teen Yi chạm trán với một Người Tuyết trên mái nhà của căn hộ cô sống tại Thượng Hải, cô và hội bạn tinh nghịch gồm Jin và Peng đã đặt cho nó cái tên “Everest”. Và cả hội đã cùng lên đường trên một hành trình vĩ đại, giúp sinh vật kỳ diệu đó trở về bên gia đình trên nóc nhà Trái Đất. Nhưng việc hội 3 người bạn cần phải làm là phải hành động trước một bước để tránh khỏi Burnish – một người đàn ông giàu có đang nung nấu ý đồ bắt cóc Người Tuyết, và nhà động vật học - giáo sư Zara để giúp Everest trở về nhà.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chloe Bennet","avatar":""},{"name":"Albert Tsai","avatar":""},{"name":"Tenzing Norgay Trainor","avatar":""},{"name":"Joseph Izzo","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Tsai Chin","avatar":""},{"name":"Michelle Wong","avatar":""},{"name":"Rich Dietl","avatar":""},{"name":"James Hong","avatar":""},{"name":"Christine Lin","avatar":""},{"name":"Kym Miller","avatar":""},{"name":"Jason Ko","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Karen Huie","avatar":""},{"name":"Vic Chao","avatar":""},{"name":"Fernando Chien","avatar":""},{"name":"Reuben Uy","avatar":""},{"name":"David P. Sm","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id