INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-tich-thanh-the', 'Bí Tích Thánh Thể', 'Corpus Christi', 'https://phimimg.com/upload/vod/20231024-1/cb527e8f5617651190bb824662318ed2.jpg', 'https://phimimg.com/upload/vod/20231024-1/86f20967a12303583145c9308f63db02.jpg', '<p>Corpus Christi - Boze Cialo (Bí Tích Thánh Thể) là tác phẩm điện ảnh đến từ Ba Lan của đạo diễn Jan Komasa lấy cảm hứng từ các sự kiện có thật được Mateusz Pacewicz viết kịch bản. Câu chuyện kể về chàng thanh niên 20 tuổi Daniel (Bartosz Bielenia) đang thụ án trong một trại giam thanh thiếu niên vì tội giết người cấp độ hai. Được giác ngộ bởi linh mục nhà tù, Cha Tomasz (Lukasz Simlat) và nguyện hiến dâng đời cho Thiên chúa, nhưng bởi quá khứ tội phạm đã không cho phép anh nộp đơn vào chủng viện. Dù vậy Daniel vẫn không từ bỏ giấc mơ của mình.</p>', 'Full', 1, 'single', 'completed', 24, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Bartosz Bielenia","avatar":""},{"name":"Aleksandra Konieczna","avatar":""},{"name":"Eliza Rycembel","avatar":""},{"name":"Tomasz Zietek","avatar":""},{"name":"Barbara Jonak","avatar":""},{"name":"Leszek Lichota","avatar":""},{"name":"Łukasz Simlat","avatar":""},{"name":"Zdzisław Wardejn","avatar":""},{"name":"Anna Biernacik","avatar":""},{"name":"Lidia Bogacz","avatar":""},{"name":"Bogdan Brzyski","avatar":""},{"name":"Malwina Brych","avatar":""},{"name":"Juliusz Chrząstowski","avatar":""},{"name":"Radoslaw Ciucias","avatar":""},{"name":"Mateusz Czwartosz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
