INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-chu-cho-bailey', 'Hành Trình Của Chú Chó Bailey', 'A Dog''s Journey', 'https://phimimg.com/upload/vod/20231022-1/85291377184dc3919413b15a9aecf587.jpg', 'https://phimimg.com/upload/vod/20231022-1/c57e03fb387fb810421420ea32e52734.jpg', '<p>Một chú chó tìm thấy ý nghĩa cho sự tồn tại của chính mình thông qua cuộc sống của những con người mà nó gặp.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Marg Helgenberger","avatar":""},{"name":"Betty Gilpin","avatar":""},{"name":"Henry Lau","avatar":""},{"name":"Kathryn Prescott","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Abby Ryder Fortson","avatar":""},{"name":"Emma Volk","avatar":""},{"name":"Ian Chen","avatar":""},{"name":"Jake Manley","avatar":""},{"name":"Johnny Galecki","avatar":""},{"name":"Tyler Asher Xin-Qin","avatar":""},{"name":"Beckett Richard Pin","avatar":""},{"name":"Daniela Barbosa","avatar":""},{"name":"Kevin Claydon","avatar":""},{"name":"Arlene Duncan","avatar":""},{"name":"Cherissa R","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
