INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-trinh-cua-chu-cho-bailey', 'Hành Trình Của Chú Chó Bailey', 'A Dog''s Journey', 'hành trình của chú chó bailey a dog''s journey marg helgenberger betty gilpin henry lau kathryn prescott dennis quaid josh gad abby ryder fortson emma volk ian chen jake manley johnny galecki tyler asher xin-qin beckett richard pin daniela barbosa kevin claydon arlene duncan cherissa r ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-buon', 'Câu Chuyện Buồn', 'Blue Story', 'https://phimimg.com/upload/vod/20231023-1/274fdc567ef1867fd168338b3bad1330.jpg', 'https://phimimg.com/upload/vod/20231023-1/8520a265913f1d6235915b5502ac6158.jpg', '<p>Câu chuyện là một câu chuyện bi thảm về tình bạn giữa Timmy và Marco, hai chàng trai trẻ từ những đoạn mã đối nghịch. Timmy, một cậu bé nhút nhát, thông minh, ngây thơ và nhút nhát từ Deptford, đến trường ở Peckham, nơi cậu kết bạn với Marco, một đứa trẻ thích đi dạo, lôi cuốn từ khu vực địa phương. Mặc dù từ các mã bưu điện chiến tranh, cả hai nhanh chóng hình thành một tình bạn bền chặt cho đến khi nó được thử nghiệm và họ kết thúc ở phía đối thủ của một cuộc chiến đường phố. Câu chuyện mô tả các yếu tố về trải nghiệm cá nhân của chính Rapman và các khía cạnh thời thơ ấu của anh.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Stephen Odubola","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Khali Best","avatar":""},{"name":"Karla-Simone Spence","avatar":""},{"name":"Eric Kofi Abrefa","avatar":""},{"name":"Max Fincham","avatar":""},{"name":"Kadeem Ramsay","avatar":""},{"name":"Rohan Nedd","avatar":""},{"name":"Tuwaine Barrett","avatar":""},{"name":"Sean Sagar","avatar":""},{"name":"Andre Dwayne","avatar":""},{"name":"Rapman","avatar":""},{"name":"Remi-Lawal Abiola","avatar":""},{"name":"Junior Afolabi Salokun","avatar":""},{"name":"Kemi Lofinmakin","avatar":""},{"name":"Duayne Boachie","avatar":""},{"name":"Jo Mar","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324387);
