INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-va-ninja-rua', 'Người Dơi và Ninja Rùa', 'Batman vs Teenage Mutant Ninja Turtles', 'https://phimimg.com/upload/vod/20231023-1/c3a136e0f7ea402540912284f33afc2c.jpg', 'https://phimimg.com/upload/vod/20231023-1/4907ae69acee89a0f3242a8a0d0972e6.jpg', '<p>Batman, Batgirl và Robin đã liên minh với Rùa Ninja Mutant Teenage để chiến đấu chống lại kẻ thù đã tuyên thệ của Rùa, The Shredder, người đã hợp tác với Ra’s Al Ghul và The League Of Assassins Khi bọn tội phạm Gotham bị tấn công bởi những con rùa có kích thước bí ẩn, Người Dơi và đồng minh của mình, Batgirl và Robin, cố gắng tìm kiếm các sinh vật và ngăn chặn chúng. Họ sớm biết rằng Gotham có một số khách truy cập mới Trong khi đó, Shredder, Ra’s Al Ghul và Liên minh sát thủ đã giải thoát những tên tội phạm nguy hiểm nhất của Gotham khỏi các tế bào của chúng, bao gồm ông Freeze, Bane, Scarecrow, Two-Face, Poison Ivy và Joker. Batman và The Teenage Mutant Ninja Turtles có thể giải quyết sự khác biệt của họ trước khi quá muộn không? Một trong những điều ...</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Troy Baker","avatar":""},{"name":"Eric Bauza","avatar":""},{"name":"Darren Criss","avatar":""},{"name":"Kyle Mooney","avatar":""},{"name":"Baron Vaughn","avatar":""},{"name":"Rachel Bloom","avatar":""},{"name":"Ben Giroux","avatar":""},{"name":"Brian George","avatar":""},{"name":"Jim Meskimen","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Cas Anvar","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Andrew Kishino","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
