INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-do-3', 'Quỷ Đỏ 3', 'Hellboy 3', 'https://phimimg.com/upload/vod/20231023-1/fce84bef3731be0c0a82bb76939ae518.jpg', 'https://phimimg.com/upload/vod/20231023-1/243f7f28a9d6374e0c3c83310b2988ce.jpg', '<p>Được chuyển thể dựa trên bộ truyện tranh cùng tên nổi tiếng của tác giả Mike Mignola, phần “reboot” Hellboy là cuộc chiến giữa “Quỷ đỏ” (David Harbour - Stranger Things) và một ác nữ cổ xưa (Milla Jovovich - Resident Evil) đang lên kế hoạch tiêu diệt loài người.</p>', 'Full', 1, 'single', 'completed', 27, 2019, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"David Harbour","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Sasha Lane","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Brian Gleeson","avatar":""},{"name":"Penelope Mitchell","avatar":""},{"name":"Mark Stanley","avatar":""},{"name":"Emma Tate","avatar":""},{"name":"Troy James","avatar":""},{"name":"Mario de la Rosa","avatar":""},{"name":"Ava Brenna","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324387);
