INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-va-su-menh-thien-tu', 'Cậu Bé Và Sứ Mệnh Thiên Tử', 'The Kid Who Would Be King', 'https://phimimg.com/upload/vod/20231023-1/6d72718a31168f466f0e6cd05b4ce990.jpg', 'https://phimimg.com/upload/vod/20231023-1/7be6229a1fe3e6126cc691e629bb27c8.jpg', '<p>Cậu nam sinh người Anh Alexander Elliot, người đã rút thanh kiếm Excalibur của vua Arthur khỏi lòng đất, khiến cõi trần gian gặp lâm nguy. Cậu bé đã tập hợp những những người bạn thân nhất của mình, để cùng nhau chống lại kẻ phản diện từ thời Trung Cổ Morgana. Ả ta đang triệu hồi đội quân quái vật cổ xưa nhằm âm mưu thống trị thế giới.</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Louis Ashbourne Serkis","avatar":""},{"name":"Dean Chaumoo","avatar":""},{"name":"Tom Taylor","avatar":""},{"name":"Rhianna Dorris","avatar":""},{"name":"Denise Gough","avatar":""},{"name":"Angus Imrie","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Noma Dumezweni","avatar":""},{"name":"Nathan Stewart-Jarrett","avatar":""},{"name":"Mark Bonnar","avatar":""},{"name":"Alexandra Roach","avatar":""},{"name":"Nick Mohammed","avatar":""},{"name":"Adam Buxton","avatar":""},{"name":"Clau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
