INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dumbo-chu-voi-biet-bay', 'Dumbo: Chú Voi Biết Bay', 'Dumbo', 'https://phimimg.com/upload/vod/20231022-1/79edea4ef2477c410da71ba09a4d9890.jpg', 'https://phimimg.com/upload/vod/20231022-1/7831c1538a86f5e1f42ca7067f68485d.jpg', '<p>Dumbo: Chú voi con có đôi tai ngoại cỡ và biến nó thành cây hài cho đoàn xiếc. Tuy nhiên khi họ phát hiện ra chú voi Dumbo có thể bay, cả đoàn xiếc đã gây dựng lại danh tiếng và thu hút sự chú ý của V.A. Vandevere – một doanh nhân thành đạt có sở thích sưu tầm động vật lạ cho công viên giải trí Dreamland của hắn. Dumbo vút bay đến một tầm cao mới cùng với nghệ sĩ xiếc Colette Marchant cho đến khi Holt phát hiện ra những bí ẩn đen tối đằng sau vẻ ngoài hào nhoáng của Dreamland.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Nico Parker","avatar":""},{"name":"Finley Hobbins","avatar":""},{"name":"Roshan Seth","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Joseph Gatt","avatar":""},{"name":"Miguel Muñoz Segura","avatar":""},{"name":"Sharon Rooney","avatar":""},{"name":"Zenaida Alcalde","avatar":""},{"name":"Michael Buffer","avatar":""},{"name":"Phil Zimmerman","avatar":""},{"name":"Ragevan Vasan","avatar":""},{"name":"Frank Bourke","avatar":""},{"name":"Zel","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324387);
