INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-kinh-hoang', 'Ký Ức Kinh Hoàng', 'Doctor Sleep', 'https://phimimg.com/upload/vod/20231023-1/83e6e1e0dabb4989e5448e78538addc8.jpg', 'https://phimimg.com/upload/vod/20231023-1/3c597b924470592305abda88501bf3a6.jpg', '<p>Doctor Sleep lấy bối cảnh nhiều năm sau The Shining (1980), khi cậu bé Danny năm nào giờ đây đã trưởng thành nhưng liên tục chìm trong rượu, những cơn thịnh nộ vô chừng và phải đối diện với những hồn ma trong quá khứ. Quyết định làm lại cuộc đời, Danny đã dọn đến sống tại New Hampshire. Trong lúc đó, Danny dần phát hiện ra mình có một năng lực siêu nhiên mạnh mẽ và có thể kết nối với cô bé 12 tuổi tên Abra Stone. Từ đấy, Danny và Abra đoàn kết cùng nhau để chống lại Rose the Hat và những kẻ tay sai - The True Knot - những kẻ chuyên truy sát những người có năng lực đặc biệt như Danny và Abra để có cuộc sống bất tử</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Kyliegh Curran","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Zahn McClarnon","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"Selena Anduze","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Carel Struycken","avatar":""},{"name":"Katie Parker","avatar":""},{"name":"Jamie Flanagan","avatar":""},{"name":"Met Clark","avatar":""},{"name":"Zackary Momoh","avatar":""},{"name":"Jocelin Donahue","avatar":""},{"name":"Dakota Hickman","avatar":""},{"name":"Carl Lumbly","avatar":""},{"name":"Henry","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug"