INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-buoc-de-yeu', 'Năm Bước Để Yêu', 'Five Feet Apart', 'https://phimimg.com/upload/vod/20231022-1/d39424f1a088490b9bd58d8335066886.jpg', 'https://phimimg.com/upload/vod/20231022-1/1bead17dc43aa6ecbecf7febf115edd0.jpg', '<p>Năm Bước Để Yêu là câu chuyện tình nơi bệnh viên của Stella và Will. Cả hai mang chứng bệnh u xơ nang và hoại tử phổi. Họ không thể đến gần nhau hơn 6 bước chân (1,8 mét). Tuy thế, với những gì mà căn bệnh quái ác đã cướp đi của họ, cả hai không ngại việc trộm lại một bước chân để được gần nhau hơn.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Haley Lu Richardson","avatar":""},{"name":"Cole Sprouse","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Kimberly Hebert Gregory","avatar":""},{"name":"Parminder Nagra","avatar":""},{"name":"Claire Forlani","avatar":""},{"name":"Emily Baldoni","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Rebecca Chulew","avatar":""},{"name":"Sue-Lynn Ansari","avatar":""},{"name":"Ariana Guerra","avatar":""},{"name":"Cecilia Leal","avatar":""},{"name":"Cynthia Evans","avatar":""},{"name":"Trina LaFargue","avatar":""},{"name":"Sophia Bernard","avatar":""},{"name":"Brett Austin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
