INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghia-dia-ma-quai', 'Nghĩa Địa Ma Quái', 'Pet Sematary', 'https://phimimg.com/upload/vod/20231022-1/9f9c0e218e2be9b4da72260dc8bbcfcb.jpg', 'https://phimimg.com/upload/vod/20231022-1/91034cb94002c9806c395ce7c836bf6c.jpg', '<p>Đây là tác phẩm được dựa trên quyển sách cùng tên của Stephen King được viết vào năm 1983 và được xem là một trong những câu chuyện đen tối nhất của ông.&nbsp; Pet Sematary kể về Giáo sư Louis Creed (Jason Clarke) cùng vợ Rachel (Amy Seimetz) và hai đứa con nhỏ sau khi chuyển từ Boston tới vùng nông thôn Maine, đã khám phá ra một vùng nghĩa địa bí ẩn nằm sâu trong rừng nằm gần ngôi nhà của họ. Khi bi kịch xảy đến, Louis tìm đến người hàng xóm kì lạ, Jud Crandall (John Lithgow), bắt đầu cho một chuỗi những sự kiện đầy kinh hoàng, giải phóng những thực thể tà ác bí ẩn kéo theo những hậu quả khủng khiếp</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Clarke","avatar":""},{"name":"Amy Seimetz","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Jeté Laurence","avatar":""},{"name":"Hugo Lavoie","avatar":""},{"name":"Lucas Lavoie","avatar":""},{"name":"Obssa Ahmed","avatar":""},{"name":"Sonia Maria Chirila","avatar":""},{"name":"Alyssa Brooke Levine","avatar":""},{"name":"Maria Herrera","avatar":""},{"name":"Jacob Lemieux","avatar":""},{"name":"Maverick Fortin","avatar":""},{"name":"Lou Ferrando","avatar":""},{"name":"Najya Muipatayi","avatar":""},{"name":"Emma Hill","avatar":""},{"name":"Frank Schorpion","avatar":""},{"name":"Linda E. S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
