INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-togo', 'Chú Chó Togo', 'Togo', 'https://phimimg.com/upload/vod/20231020-1/703cf95cc8e9ab4f5736fd63884e85c2.jpg', 'https://phimimg.com/upload/vod/20231020-1/16a28ffe154405b34b56b94bcb3d6aa9.jpg', '<p>Câu chuyện kể về chú chó kéo xe tuyết Togo, chú chó dẩn đường trong cuộc vận chuyển huyết thanh tại Alaska năm 1925 và đã thành công mang huyết thanh về thị trấn Nenana, bất chấp bị xem là giống loài thấp bé và yếu kém. Một bộ phim cực kì cảm động, giàu tính nhân văn và suy nghẫm</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Willem Dafoe","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Christopher Heyerdahl","avatar":""},{"name":"Richard Dormer","avatar":""},{"name":"Adrien Dorval","avatar":""},{"name":"Madeline Wickins","avatar":""},{"name":"Michael Greyeyes","avatar":""},{"name":"Nive Nielsen","avatar":""},{"name":"Nikolai Nikolaeff","avatar":""},{"name":"Thorbjørn Harr","avatar":""},{"name":"Catherine McGregor","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Michael Gaston","avatar":""},{"name":"Zahn McClarnon","avatar":""},{"name":"Brandon Oa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
