INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-lich-su', 'Cuộc Đua Lịch Sử', 'Ford v Ferrari', 'https://phimimg.com/upload/vod/20231019-1/785c2c81701b80aae215edd3199d4611.jpg', 'https://phimimg.com/upload/vod/20231019-1/b90eac7d97a158f823498336429893b5.jpg', '<p>Khán giả sẽ có dịp tái ngộ hai tài tử Christian Bale và Matt Damon trong dự án mới nhất của đạo diễn James Mangold. Phim lấy bối cảnh đường đua Le Mans 1966 xoay quanh cuộc cạnh tranh gắt gao giữa hai hãng xe hàng đầu thế giới là Ford và Ferrari. Trước sự thống trị của Ferrari, hãng Ford quyết định chiêu mộ nhóm kỹ sư do huyền thoại Carroll Shelby đứng đầu, cùng tay đua kiệt xuất Ken Miles để chế tạo ra một mẫu xe đua mang tính cách mạng nhằm đánh bại đối thủ Ferrari.</p>', 'Full', 1, 'single', 'completed', 22, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Caitríona Balfe","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Remo Girone","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"JJ Feild","avatar":""},{"name":"Jack McMullen","avatar":""},{"name":"Corrado Invernizzi","avatar":""},{"name":"Joe Williamson","avatar":""},{"name":"Ian Harding","avatar":""},{"name":"Christopher Darga","avatar":""},{"name":"Shawn Law","avatar":""},{"name":"Emil Beheshti","avatar":""},{"name":"Darrin Prescot","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324387);
