INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('midsommar-le-hoi-ha-chi', 'Midsommar: Lễ Hội Hạ Chí', 'Midsommar', 'https://phimimg.com/upload/vod/20231021-1/cd3bcf1888fd8b62a644822714aae108.jpg', 'https://phimimg.com/upload/vod/20231021-1/da627ab794167f43135b1364965c3a0e.jpg', '<p>Lễ Hội Đẫm Máu lấy câu chuyện xoay quanh cô gái Dani cùng bạn trai và 3 người bạn khác đi du lịch tới ngôi làng Hårga tại Thụy Điển. Chuyến đi của họ trùng vào dịp làng Hårga tổ chức lễ hội mừng ngày hạ chí. Tưởng rằng tất cả sẽ có một quãng thời gian vui vẻ bên nhau nhưng rồi mọi thứ bắt đầu trở nên không như ý muốn của mình và thậm chí còn đáng sợ gấp nhiều lần.</p>', 'Full', 1, 'single', 'completed', 24, 2019, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Florence Pugh","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"William Jackson Harper","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Vilhelm Blomgren","avatar":""},{"name":"Isabelle Grill","avatar":""},{"name":"Gunnel Fred","avatar":""},{"name":"Ellora Torchia","avatar":""},{"name":"Archie Madekwe","avatar":""},{"name":"Henrik Norlén","avatar":""},{"name":"Agnes Westerlund Rase","avatar":""},{"name":"Julia Ragnarsson","avatar":""},{"name":"Mats Blomgren","avatar":""},{"name":"Lars Väringer","avatar":""},{"name":"Anna Åström","avatar":""},{"name":"Hampus Hall","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324387);
