INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-com-va-ac-quy', 'Trùm, Cớm và Ác Quỷ', 'The Gangster, the Cop, the Devil', 'https://phimimg.com/upload/vod/20231018-1/4f1515673860ddc076120b27a9819868.jpg', 'https://phimimg.com/upload/vod/20231018-1/1e8c44c18917ee7d6400ba5c13ac04cb.jpg', '<p>Có ai ngờ được rằng Jang Dong Su - một tay trùm khét tiếng cũng có lúc trở thành nạn nhân của một kẻ giết người máu lạnh?! Chính sự kiện này đã mở ra một cuộc hợp tác bất đắc dĩ giữa ông trùm và gã cớm để truy bắt hung thủ. Tất nhiên, mặc dù phối hợp với nhau nhưng hai bên vẫn ngấm ngầm sử dụng những luật lệ và giữa cho mình những bí mật riêng. Liệu cuộc vây bắt này sẽ diễn ra như thế nào? Ai sẽ người dành được chiến thắng cuối cùng?</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Choi Chul-min","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Oh Hee-joon","avatar":""},{"name":"Kim Gyu-ri","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Ryu Tae-ho","avatar":""},{"name":"Cha Soon-bae","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Lee Eun-saem","avatar":""},{"name":"Yoon Yeong-gyun","avatar":""},{"name":"Bae Min-jun","avatar":""},{"name":"Moon Soon-ju","avatar":""},{"name":"Lee So-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
