INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-hobbs-shaw', 'Quá Nhanh Quá Nguy Hiểm: Hobbs & Shaw', 'Fast & Furious Presents: Hobbs & Shaw', 'https://phimimg.com/upload/vod/20231018-1/9ede7ea6afffd4d2e25098364d6db3a0.jpg', 'https://phimimg.com/upload/vod/20231018-1/06b2c1c521b9899e5cbd487ca9c3b461.jpg', '<p>Kể từ khi luật sư Hobbs (Johnson), một nhân viên trung thành của Sở An Ninh Ngoại Giao Hoa Kỳ, và Shaw (Statham), một cựu quan chức ưu tú của quân đội Anh, lần đầu tiên mặt đối mặt trong Furious 7, họ đã cạch mặt nhau. Nhưng từ khi một kẻ theo chủ nghĩa vô thần được cải tiến gen Brixton (Idris Elba) giành quyền kiểm soát một mối đe dọa sinh học quỷ quyệt có thể thay đổi nhân loại mãi mãi - và truy lùng một đặc vụ MI6 lừa đảo, thông minh và đáng sợ (Vanessa Kirby), mà tình cờ là em gái của Shaw, hai kẻ thù không đội trời chung phải hợp tác để đánh bại kẻ duy nhất xấu xa hơn mình.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Eliana Su''a","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Lori Pelenise Tuisano","avatar":""},{"name":"John Tui","avatar":""},{"name":"Joshua Mauga","avatar":""},{"name":"Joe Anoa''i","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Alex King","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"John Macdonald","avatar":""},{"name":"Georgia Me","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23