INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-skywalker-troi-day', 'Star Wars: Skywalker Trỗi Dậy', 'Star Wars: The Rise of Skywalker', 'https://phimimg.com/upload/vod/20231018-1/779f3b098ced2d05b48f4fc3c4293937.jpg', 'https://phimimg.com/upload/vod/20231018-1/d962be812b5cf55e3466bcdbbaa70c81.jpg', '<p>Nội dung phim được xem như phần kết của đế chế Skywalker. Đây sẽ nơi diễn ra các cuộc chiến giành tự do và xác định những huyền thoại mới.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carrie Fisher","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Daisy Ridley","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"John Boyega","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"Naomi Ackie","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Lupita Nyong''o","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Joonas Suotamo","avatar":""},{"name":"Kelly Marie Tran","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Greg","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324387);
