INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('joker-ga-he', 'Joker: Gã Hề', 'Joker', 'https://phimimg.com/upload/vod/20231018-1/77ddf9d17ed4388b5b6ba438ee072ea3.jpg', 'https://phimimg.com/upload/vod/20231018-1/8caf81b5a7c17308ace50c3b1e486988.jpg', '<p>Joker từ lâu đã là siêu ác nhân huyền thoại của điện ảnh thế giới. Nhưng có bao giờ bạn tự hỏi, Joker đến từ đâu và điều gì đã biến Joker trở thành biểu tượng tội lỗi của thành phố Gotham? JOKER sẽ là cái nhìn độc đáo về tên ác nhân khét tiếng của Vũ trụ DC – một câu chuyện gốc thấm nhuần, nhưng tách biệt rõ ràng với những truyền thuyết quen thuộc xoay quanh nhân vật mang đầy tính biểu tượng này. Bộ phim đã xuất sắc giành giải thưởng Sư Tử Vàng- Phim Hay Nhất tại LHP Venice lần thứ 76, cùng tràng pháo tay dài 8 phút, và lời khen ngợi dành cho diễn xuất của tài tử Joaquin Phoenix. Một bộ phim không thể bỏ lỡ của tháng 10 năm nay.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Glenn Fleshler","avatar":""},{"name":"Leigh Gill","avatar":""},{"name":"Josh Pais","avatar":""},{"name":"Rocco Luna","avatar":""},{"name":"Marc Maron","avatar":""},{"name":"Sondra James","avatar":""},{"name":"Murphy Guyer","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Dante Pereira-Olson","avatar":""},{"name":"Carrie Louise Putrello","avatar":""},{"name":"Sha","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
