INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-john-wick-phan-3-chuan-bi-chien-tranh', 'Sát Thủ John Wick: Phần 3 - Chuẩn Bị Chiến Tranh', 'John Wick: Chapter 3 - Parabellum', 'https://phimimg.com/upload/vod/20231018-1/72e545b71bf7cd4f09ffcd7b28de1852.jpg', 'https://phimimg.com/upload/vod/20231018-1/d4878333467d621e5f2373f294a711c2.jpg', '<p>Sau khi trở thành &quot;giải thưởng lớn&quot; của giới sát thủ toàn cầu, siêu sát thủ John Wick phải cùng chú chó cưng lên đường chạy trốn. Với giá 14 triệu $, John Wick trở thành mục tiêu béo bở của bất cứ kẻ săn đầu người nào.</p>', 'Full', 1, 'single', 'completed', 11, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Mark Dacascos","avatar":""},{"name":"Asia Kate Dillon","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Jerome Flynn","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Margaret Daly","avatar":""},{"name":"Robin Lord Taylor","avatar":""},{"name":"Susan Blommaert","avatar":""},{"name":"Unity Phelan","avatar":""},{"name":"Jason Mantzoukas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324387);
