INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-chong-khung-bo', 'Biệt Đội Chống Khủng Bố', 'Uri: The Surgical Strike', 'https://phimimg.com/upload/vod/20231016-1/0b93f8597890bd05698029eb67fea378.jpg', 'https://phimimg.com/upload/vod/20231016-1/86be9115dbf18628edd610d2f2d7be2c.jpg', '<p>Thiếu tá Vihaan Singh Shergill của Quân đội Ấn Độ chỉ huy một chiến dịch bí mật chống lại một nhóm chiến binh đã tấn công một căn cứ ở Uri, Kashmir, vào năm 2016 và giết chết nhiều binh sĩ.</p>', 'Full', 1, 'single', 'completed', 24, 2019, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Vicky Kaushal","avatar":""},{"name":"Paresh Rawal","avatar":""},{"name":"Yami Gautam","avatar":""},{"name":"Kirti Kulhari","avatar":""},{"name":"Mohit Raina","avatar":""},{"name":"Dhairya Karwa","avatar":""},{"name":"Rajit Kapoor","avatar":""},{"name":"Ivan Rodrigues","avatar":""},{"name":"Manasi Parekh","avatar":""},{"name":"Swaroop Sampat","avatar":""},{"name":"Shishir Sharma","avatar":""},{"name":"Satyajit Sharma","avatar":""},{"name":"Raj Babbar","avatar":""},{"name":"Manish Chaudhary","avatar":""},{"name":"Abrar Zahoor","avatar":""},{"name":"Rakesh Bedi","avatar":""},{"name":"Ujjwal Chopra","avatar":""},{"name":"Riva","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324387);
