INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-doi-chong-khung-bo', 'Biệt Đội Chống Khủng Bố', 'Uri: The Surgical Strike', 'biệt đội chống khủng bố uri: the surgical strike vicky kaushal paresh rawal yami gautam kirti kulhari mohit raina dhairya karwa rajit kapoor ivan rodrigues manasi parekh swaroop sampat shishir sharma satyajit sharma raj babbar manish chaudhary abrar zahoor rakesh bedi ujjwal chopra riva ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-doc', 'Bí Mật Độc', 'Secret Poison', 'null', 'https://phimimg.com/upload/vod/20231014-1/dc9cecfdfb36d0565a2f6d1a08620148.jpg', '<p>Trên thế giới có một loại độc đáng sợ nhất, tên là Vô Nhất Độc, không chỉ có thiết kế phức tạp, còn có thể tùy ý khống chế người khác sinh tử, đây là một loại độc dược đã thất lạc vào Đường Môn, nhưng nó lại có một loại độc dược đáng sợ nhất trên thế giới. thực ra đã xuất hiện ở thành phố Hongri trong sa mạc, Đường Môn phái con trai thứ hai là Đường Trung Sinh đến điều tra. Anh hùng huyền thoại Bai Yihou đã lâu không xuất hiện trên thế giới cũng có liên quan đến vụ việc này. Kể từ khi mọi người đến thành phố Hongri, mọi người đã chết một cách bí ẩn trong thành phố. Các lính canh trong thành phố đang truy lùng nghi phạm Tang Zhongsheng. Bai Yihou và trùm xã hội đen Liu Chan&#39;er có liên quan đến vụ việc và không thể thoát khỏi sự nghi ngờ. May mắn thay, Yun Ling, người phụ trách bộ phận giám sát thành phố, tin tưởng họ và giúp họ thoát khỏi sự truy bắt. Nhóm Baiyihou bắt đầu điều tra sự thật, quá khứ tội lỗi dần lộ diện, hóa ra Yun City Lord và những người khác chính là ba con ma của Tang Sect đã trốn thoát khỏi Tang Sect hai mươi năm trước, họ chạy trốn đến thành phố Hongri và sử dụng một nhóm trẻ em làm đối tượng thí nghiệm. Anh ta đã tạo ra Chất độc không mặc quần áo đáng sợ, thứ kiểm soát cuộc sống của toàn thành phố. Vì nuôi Cổ Vương, Vân quân dương mệnh đã bị giảm đi một nửa, hiện tại vì kéo dài mạng sống, hắn đang chuẩn bị hình thành ngũ âm trận pháp, tế cả thành để thu hồi trăm cổ. đang bị đe dọa. Bai Yihou ra tay đột phá đội hình của Yun City Lord, nhưng sau đó anh ta mới nhận ra rằng Yun City Lord chỉ là một quân cờ, kẻ chủ mưu thực sự đằng sau hậu trường là đại yêu Suzaku, người có tranh chấp lịch sử với Bai Yihou. ..</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deric Wan","avatar":""},{"name":"Yu Qingbin","avatar":""},{"name":"卓霖","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324387);
