INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bich-huyet-dan-sa', 'Bích Huyết Đan Sa', 'A Brave Heart', 'https://phimimg.com/upload/vod/20231014-1/875bcc1532d7c133acd72a91544ad6fe.jpg', 'https://phimimg.com/upload/vod/20231014-1/0ac2de3ef4865e7387ddb9a401f48cb8.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Những người đam mê nhiếp ảnh yêu văn hóa Gelao - Gia Định đã đến huyện Ô Xuyên, cội nguồn của Gelao, để du lịch, trong quá trình chụp ảnh và sáng tạo tại quê hương Gelao, gặp được hướng dẫn viên du lịch xinh đẹp xinh đẹp của bộ tộc Gelao - Mengqin, tình yêu chung của văn hóa Gelao đã khiến hai bạn trẻ nhìn thấy nhau từ cái nhìn đầu tiên, dưới Đá Mẹ Cửu Thiên, cô gái Gelao kể truyền thuyết cổ xưa về Danxin...</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Theo truyền thuyết, người Phổ là những người đầu tiên trên thế giới làm chủ công nghệ tinh luyện dansand, và sau khi Tần Thủy Hoàng thống nhất sáu nước, để tìm kiếm sự bất tử, ông đã cử tướng Lang Zhongling Qin Tian đến bộ lạc Pu ở biên giới phía tây nam để khám phá trái tim Dan bí ẩn. Để đạt được mục đích ủng hộ Hồ Hải lên ngôi, kẻ phản bội Triệu Cao đã thiết lập một kế hoạch độc hại và ra lệnh cho hậu duệ của Lục quốc cướp Đan Sa, trong một nỗ lực vô ích để tiêu diệt Tần Thiên và Dan Xin cùng nhau bằng một hòn đá, và Tần Thiên lạnh lùng và khắc nghiệt đã trở thành bạn thân với chàng trai anh hùng và võ thuật Bai Yan của bộ lạc Mayang và cô gái xinh đẹp sôi nổi và hào phóng Hongsha trong quá trình chiếm lại dansha, và thậm chí còn bị lây nhiễm nhiều hơn bởi bầu không khí ấm áp của bộ lạc Mayang, và trở thành một thành viên của bộ lạc từ tận đáy lòng. Cuối cùng, để tránh sự hủy diệt của bộ lạc. Bai Yan, với tư cách là huyết thống của Shoudan, đã hy sinh mạng sống của mình vào giây phút cuối cùng để bảo vệ các gia tộc. Tần Thiên cũng hy sinh mạng sống quý giá của mình vì nó. Cát Đỏ mang theo xương thịt của Bạch Yến, truyền huyết thống của người Thọ Đản từ thế hệ này sang thế hệ khác...</span></p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Jiading","avatar":""},{"name":"Liu Changde","avatar":""},{"name":"Mengqin","avatar":""},{"name":"Liu Zi","avatar":""},{"name":"Cheng Qian","avatar":""},{"name":"Chu Tiểu Ưng","avatar":""},{"name":"Triệu Ran","avatar":""},{"name":"Yu Yanqin","avatar":""},{"name":"Hầu Đồng Giang","avatar":""},{"name":"Vương Quan Trần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
