INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bich-huyet-dan-sa', 'Bích Huyết Đan Sa', 'A Brave Heart', 'bích huyết đan sa a brave heart zhang jiading liu changde mengqin liu zi cheng qian chu tiểu ưng triệu ran yu yanqin hầu đồng giang vương quan trần ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-hoa', 'Cứu Hỏa', 'Blast', 'https://phimimg.com/upload/vod/20231014-1/4316fdf2b061d5ff8cb749ba384d303f.jpg', 'https://phimimg.com/upload/vod/20231014-1/99c1a8d90d514133cd142f03dd12dafa.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về câu chuyện của Xie Xiaoxing, người chịu ảnh hưởng của cha mình từ nhỏ và khao khát trở thành lính cứu hỏa, và được chuyển bởi phi đội dịch vụ đặc biệt cứu hỏa &quot;Đội Haijiao&quot; khi ông sắp nghỉ hưu, trở thành một anh hùng lửa thực sự. Trong đội Hải Kiều, anh gặp đồng đội sinh tử và huấn luyện viên ác quỷ Vương Hạo Trạch, và vô tình phát hiện ra quá khứ giữa Vương Hạo Trạch và cha mình. Cùng lúc đó, nhà máy luyện cốc của mẹ Xie Xiaoxing bất ngờ gặp nguy hiểm do những nguy hiểm tiềm ẩn không rõ ràng, Xiaoxing cùng đồng đội vội vã tiến hành giải cứu công nhân bị mắc kẹt trong xưởng gas. Những người bị mắc kẹt lần lượt được giải cứu, nhưng nguy hiểm vẫn tiếp tục leo thang, và &quot;Đội Haijiao&quot; rơi vào tình trạng tuyệt vọng của sự sống và cái chết. Xie Xiaoxing đã chủ động yêu cầu một nhiệm vụ giải cứu cực kỳ nguy hiểm, và cuối cùng đã tổ chức một cuộc giải cứu hỏa ly kỳ.</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Zheng","avatar":""},{"name":"Yuan Bu","avatar":""},{"name":"Liang Tingwei","avatar":""},{"name":"Mu Yancheng","avatar":""},{"name":"Huang Yunan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
