INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-tho-cam-mau-xanh', 'Bảo Vệ Thổ Cẩm Máu Xanh', 'Blood Guard', 'https://phimimg.com/upload/vod/20231014-1/2a5c34bafd634ecc56fd21f6e76f0590.jpg', 'https://phimimg.com/upload/vod/20231014-1/003b1e9ce75dc16af5de568a32a9b4a2.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ye Wuji là một tay xã hội đen ở giữa triều đại nhà Minh, người đã vô tình tham gia vào một cuộc đấu tranh để ám sát hoàng đế, và khi anh ta tìm ra những gì đã xảy ra, anh ta quyết định bảo vệ hoàng đế và loại bỏ các quan chức tham nhũng bằng cách hy sinh bản thân để cứu người.</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leng Haiming","avatar":""},{"name":"Zhang Xinyuan","avatar":""},{"name":"Wang Weiguo","avatar":""},{"name":"Guo Changhui","avatar":""},{"name":"Su Youchen","avatar":""},{"name":"Song Chunlei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324387);
