INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-lap-di', 'Bộ Đôi Lập Dị', 'The Eccentric Duo', 'https://phimimg.com/upload/vod/20231014-1/38a5849aa7097b54db334e298cf4a9bc.jpg', 'https://phimimg.com/upload/vod/20231014-1/f8ceb94c9c35b3aef0ba0a425cc77eff.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Được đạo diễn bởi Guo Yizan, đạo diễn cấp cao Cao Guiqian đã vội vã đến địa điểm quay phim để động viên và quan tâm đến những người trẻ tuổi này, Yingda đích thân hướng dẫn hiện trường trong quá trình quay phim, vở kịch được tải lại bởi một thế hệ diễn viên quyền lực mới trong nước Min Jian, Yu Lei, Gao Ziyuan và các ngôi sao mới khác, Giải thưởng Chuông vàng Đài Loan Nam diễn viên chính xuất sắc nhất Wang Genghao say mê biểu diễn</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Scott Wang","avatar":""},{"name":"Jian Min","avatar":""},{"name":"Lei Yu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324387);
