INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bom-mat-ong', 'Bom Mật Ong', 'Honey Bomb', 'null', 'https://phimimg.com/upload/vod/20231014-1/ac9f7463b8794390ae92a8f41403696b.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể một câu chuyện tuổi trẻ vui tươi và hơi &quot;lạc lõng&quot;, với nhiều yếu tố giao thoa và thời trang. Thế hệ thứ hai của những người giàu có ngu ngốc, những người lao động cổ cồn trắng chị em hoàng gia, những người đàn ông nữ bạo lực, những người đàn ông siêu xấu tính và những người trẻ tuổi giả vờ là B xuất hiện từng người một, và dàn dựng một bộ phim hài điên rồ về &quot;thời gian và không gian chồng chéo&quot; và &quot;cứu vãn những trận chiến tình yêu&quot; trong Max Villa. Năm người trẻ tuổi vốn dĩ không liên quan đã giở trò trinh sát và phản phát hiện dưới sự thao túng của các thế lực bí ẩn, còn ẩn nấp và nghe lén thì chưa kể, ba người phụ nữ và hai người đàn ông thân mật, khiến tim người ta đập nhanh hơn, để xem cờ nào cao hơn.</span></p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Pi","avatar":""},{"name":"Zhang Xiaojue","avatar":""},{"name":"Wang Ge","avatar":""},{"name":"Feng Kai","avatar":""},{"name":"Pan Yingan","avatar":""},{"name":"Trương Á Phi","avatar":""},{"name":"Ngô Lôi","avatar":""},{"name":"Quan Triết","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
