INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-chia-se', 'Bố Chia Sẻ', 'Shared Dad', 'https://phimimg.com/upload/vod/20231014-1/0a3828515b7bcbba961d5b53da433655.jpg', 'https://phimimg.com/upload/vod/20231014-1/05c512f66befdf774527b98f2a9fab0a.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Câu chuyện kể về câu chuyện của một người cha không đủ tiêu chuẩn, người tìm thấy trách nhiệm của mình đối với gia đình từ sự nghịch ngợm của con gái mình. Mặc dù Lin Hang là một sinh viên có thành tích cao, tốt nghiệp một trường đại học danh tiếng, nhưng anh ta gần như trung niên và không đạt được gì, và đã kết hôn với vợ Zhang Jia trong nhiều năm, và hai người có một cô con gái lập dị Lin Duoduo. Lin Hằng lười biếng đã dành 10 năm nhàn rỗi, nhưng may mắn thay, vợ anh là Trương Gia đã mở một cửa hàng làm tóc và làm việc chăm chỉ để duy trì cuộc sống của mình. Lindodo tinh nghịch thấy rằng cha mình không có gì để làm mỗi ngày và quyết định tìm cho anh ta một &quot;công việc&quot;: chia sẻ cha mình và chia sẻ nó với những người cần nó. Lâm Hằng, người đã phản đối vấn đề này một thời gian, cuối cùng miễn cưỡng đồng ý làm cha của người khác một lần, nhưng anh ta đã vượt khỏi tầm kiểm soát, che giấu vợ mình là Trương Gia để bí mật làm công việc &quot;chia sẻ cha&quot;, và vì lý do này, có một số hiểu lầm, gần như phá vỡ gia đình. Khi làm cha của người khác, Lin Hằng cũng nhận thấy &quot;vật liệu&quot; cần thiết để trở thành một người cha thực sự.</span></p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Yumeng","avatar":""},{"name":"Song Bo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
