INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-sieu-nhan-cua-toi', 'Bố Siêu Nhân Của Tôi', 'My Super Dad', 'https://phimimg.com/upload/vod/20231014-1/c57080eec0852f98cd0feaa12541db08.jpg', 'https://phimimg.com/upload/vod/20231014-1/c51f2d565440009f28cf65e27c19e92c.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ma Zhitu đã ngồi tù 17 năm, được thả sau khi thụ án, và gần như lớn hơn một chút, vội vã trở về quê nhà Handong để tham dự đám cưới của con gái và chứng kiến khoảnh khắc hạnh phúc của cô. Liu Ziqiu, một cô gái &lt;&gt; tuổi trong thời kỳ nổi loạn, mất mẹ từ nhỏ, và cha cô là Liu Feng, chủ sở hữu của một công ty niêm yết, thường bận rộn với công việc và kết hôn với mẹ kế trẻ Zhou Yulu, điều này khiến Liu Ziqiu bất mãn và cản trở về mọi mặt. Sau một cuộc tranh cãi với cha mình, Liu Ziqiu đã bỏ nhà đi và đến Hán Đông để tỏ lòng tôn kính với người mẹ quá cố của mình.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tại cửa hàng tiện lợi của nhà ga, Mã Chí Vũ và Lưu Tử Khâu gặp nhau lần đầu tiên, sau khi trải qua một loạt tai nạn trớ trêu, hai người đã chuyển từ nhìn nhau không thuận lợi sang ảnh hưởng đến nhau.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Cuối cùng, Lưu Tử Khâu không còn thất thường nữa và buông bỏ những nghi ngờ trước đây với cha mình, và Mã Chí Trúc cũng nhận ra con gái mình với sự giúp đỡ của Lưu Tử Khâu</span></p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shi Qiang","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
