INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-co-gai-tuyet-voi', 'Bốn Cô Gái Tuyệt Vời', 'Four Great Catches of Girls', 'https://phimimg.com/upload/vod/20231014-1/ebcd80c484d1ea9d15baa029ebd30cd7.jpg', 'https://phimimg.com/upload/vod/20231014-1/9efba9b5291531ee2c319a5554cdfc8f.jpg', '<p>Nhà tù Jinling bị một kẻ giết người bí ẩn đột nhập, và người chết thực ra là một thợ mỏ trong một mỏ bạc, Liumen được tòa án ra lệnh nhanh chóng đến nhà tù Jinling để điều tra vụ án. Họ cho rằng Liumen, một nhóm chuyên gia, sẽ phái một kẻ bắt giữ hạng nhất. Tôi nhanh chóng đi điều tra, nhưng điều tôi không ngờ lại là bốn nữ thám tử xinh đẹp mới vào nghề, mặc dù bốn người còn trẻ và là phụ nữ nhưng họ đều có kỹ năng và lòng dũng cảm độc đáo. Bốn người họ phát hiện ra vụ án giết người có liên quan đến mỏ bạc Jinling, họ sợ rằng ai đó đã làm giàu cho mình trước khi bị phát hiện và giết chết. Khi phát hiện ra băng đảng lớn nhất Jiulong cũng có liên quan đến vụ án. Vấn đề, họ đã tìm thấy người giám sát mỏ Chen Zengzhi, nhưng không ngờ họ lại gặp được quan huyện. Giống như Zuo Hengzhi, anh ta bị ám sát bởi một bàn tay độc ác. Anh trai Mu Changfeng dẫn đầu bốn người quyết định quay trở lại Bắc Kinh để báo cáo, nhưng Trên đường đi bị tấn công trọng thương rồi bất tỉnh, lúc này bốn người phát hiện con trai của quan huyện lệnh Tả Kinh, chủ nhân Tiêu Thiên Nam của họ có thể đã lợi dụng mối quan hệ của mình cấu kết với Trần Tăng Chi để biển thủ mỏ bạc giết người. Được sự bảo vệ của sư huynh, bốn cô gái đã sử dụng kỹ năng độc đáo của mình để bóc kén, cuối cùng thoát khỏi nguy hiểm, bắt được Xiao Tiannan và giúp triều đình thu hồi mỏ bạc bị mất tích.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yingying Ma","avatar":""},{"name":"Hong Shan Shan","avatar":""},{"name":"Zhu Xinyuan","avatar":""},{"name":"Fangyuan Mao","avatar":""},{"name":"Ying Kwan Lok","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324387);
