INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('budda-tuc-gian', 'Budda Tức Giận', 'The Angry Budda', 'https://phimimg.com/upload/vod/20231014-1/4c13556f5e085f3e3bac82fc8217876c.jpg', 'https://phimimg.com/upload/vod/20231014-1/8979a4f57aaa6bc9a03a5fccfec7c84f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ở thành phố nhỏ phía tây bắc thành phố Rùa, Dagui và Yiping là những người bạn tốt lớn lên cùng nhau, và họ đã từng theo đuổi Chunlan, một người yêu thời thơ ấu, cùng nhau. Sau đó, Dagui kiếm bộn tiền bằng cách đào và bán các di tích văn hóa và trở thành một bạo chúa trong làng. Chunlan kết hôn với Dagui do áp lực gia đình. Tuy nhiên, Yiping không thể quên Chunlan và quyết định làm ầm ĩ về đám cưới của Dagui và Chunlan. Do nhầm lẫn, do tình cờ, Kazuhira đã lấy được bức tượng Phật bằng vàng nguyên chất mà Dagui đã bán trước đó. Doanh nhân Đài Loan Boss Lu, luật sư Jack và cái miệng nhỏ nhắn của Dagui thay phiên nhau tranh giành tượng Phật vàng, và với cái chết bí ẩn của Dagui, những hiểu lầm và tranh chấp tiếp tục leo thang. Ai là kẻ giết người, một loạt những câu chuyện kỳ lạ đã xảy ra xung quanh cái chết của Dagui, và một trò hề phơi bày sự xấu xí của bản chất con người bắt đầu, và khi bí ẩn được nâng lên từng lớp, cuối cùng người ta phát hiện ra rằng một số nhóm nhân mã đã bị số phận &quot;hài hước đen&quot;.</span></p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tian Chuan","avatar":""},{"name":"Zhang Luyao","avatar":""},{"name":"Dai Zhuoning","avatar":""},{"name":"Gao Shuang","avatar":""},{"name":"Yang Yong","avatar":""},{"name":"Gao Lei","avatar":""},{"name":"Yang Youan","avatar":""},{"name":"Wang Jiaqiang","avatar":""},{"name":"Wang Xiaolong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
