INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-cua-qianmen-1', 'Bẫy của Qianmen 1', 'Trap of Qianmen 1', 'null', 'https://phimimg.com/upload/vod/20231014-1/76ffc186c261b03093a7d837502d3f91.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Qianmen, xuất thân từ Xia Yu, có đệ tử vượt trội về trí tuệ và giỏi chiến lược. Vào thời cổ đại, hầu hết trong số họ là cố vấn hoặc bậc thầy quân sự, và Zhang Liang, Su Qin, v.v. đều đến từ Qianmen. Sufeng khôn ngoan và sức mạnh của người đàn ông ngàn mặt, kẻ giả mạo Xiaoying và siêu hacker Fat Dragon là những kẻ thiết lập bước đi trên bờ vực bóng tối, và họ vạch trần sự lừa dối và trừng phạt cái ác và lòng tham của thế giới thông qua thiết kế khéo léo. Vài người đi trên bờ vực của bóng tối, tìm kiếm ánh sáng của bình minh.</span></p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Tianwen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
