INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-lai-cua-ban', 'Tương Lai Của Bạn', 'Feeling You', 'https://phimimg.com/upload/vod/20231014-1/a1e72dd66357ddc7c18b4ab855191cd1.jpg', 'https://phimimg.com/upload/vod/20231014-1/6b20ea78b4f5b0313ff55f7cc47cc4ca.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về một câu chuyện tình yêu giả tưởng kéo dài thời gian và không gian, và tài năng âm nhạc Su Zhe (do Xu Zhinuo thủ vai) và nữ nhiếp ảnh gia thị trấn nhỏ Xiaomi (do Zhou Sizhu thủ vai) chia sẻ thính giác và xúc giác thông qua thần giao cách cảm bí ẩn, và những câu chuyện tình yêu xuyên thời gian và không gian. Hai người bị thương rúc vào nhau, sưởi ấm cho nhau và từ từ yêu nhau, nhưng sau khi quyết định gặp nhau, họ phát hiện ra rằng hai người không ở cùng một thời gian và không gian, làm thế nào cô ấy trong quá khứ và anh ấy trong tương lai nên tiếp tục yêu nhau qua thời gian và không gian?</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhinuo Xu","avatar":""},{"name":"Sizhu Zhou","avatar":""},{"name":"Wang Wei","avatar":""},{"name":"Jin Yongsan","avatar":""},{"name":"Guiqiang Zhang","avatar":""},{"name":"Linyi Gan","avatar":""},{"name":"Wandong Guo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
