INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-thien-tai', 'Cậu Bé Thiên Tài', 'Genius Boy', 'https://phimimg.com/upload/vod/20231013-1/eddb9f23f1503ad72baa3b1e147e2420.jpg', 'https://phimimg.com/upload/vod/20231013-1/1ecaf0d02f0785182eba7092282ca458.jpg', '<p>Cả thiên tài và em gái đều thích đọc sách về không gian và họ cũng thích nghe những câu chuyện của người khác về người ngoài hành tinh. Một ngày nọ, sau giờ học, anh gặp một đứa trẻ bị thương trên đường và đưa cậu về nhà, sau khi hồi phục, cậu được biết tên cậu là Luce và cậu là một chiến binh nhí đến từ hành tinh YS. Nhiệm vụ này là đến Trái đất để quan sát hệ sinh thái và chúng tôi có hai người bạn đồng hành. Chỉ vì bầu không khí bị ô nhiễm và hư hỏng nên đĩa bay cũng bị ma sát dữ dội, chúng rơi xuống và tách ra. Bằng cách này, thiên tài và những người bạn của mình bắt đầu tìm kiếm những người bạn đồng hành ngoài hành tinh. Trong giai đoạn này, các em gặp phải những khó khăn, trở ngại không thể tưởng tượng được nhưng các em không hề lùi bước mà đối mặt với mọi việc một cách dũng cảm và tháo vát. Sự việc này khiến các em nhận thức được sự nguy hiểm của ô nhiễm không khí và các em đã gia nhập hàng ngũ bảo vệ môi trường. Sau khi được giải cứu, ba người ngoài hành tinh đã trở lại hành tinh thành công, còn thiên tài và những người bạn đồng hành của anh đã trở lại cuộc sống bình thường. Mọi chuyện cứ như một giấc mơ, các em kể câu chuyện cho các bạn cùng lớp nghe, mọi người trong lớp đều nâng cao ý thức bảo vệ môi trường.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
