INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tran-dot-bien-2', 'Con Trăn Đột Biến 2', 'The Mutant Python 2', 'https://phimimg.com/upload/vod/20231013-1/ace5cf5864ba52fc68574144d9a8a9da.jpg', 'https://phimimg.com/upload/vod/20231013-1/e36d335aee49169d07e68a503314a8bb.jpg', '<p>Ở Đông Nam Á, với phong cảnh tuyệt đẹp, một chiếc tàu tuần dương chở nhiều khách du lịch đi vào vùng biển huyền bí, nơi có một dị nhân khổng lồ. Mọi người lần lượt chết một cách bí ẩn. “Kẻ giết người” trong bóng tối và kẻ bí ẩn trong số khách du lịch khiến chiếc tàu tuần dương trở thành “cỗ máy hành quyết”. Những người sống sót chạy trốn đến một hòn đảo hoang kỳ lạ gặp một dị nhân hung dữ hơn và bắt đầu hành trình sinh tồn.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leo Chiu","avatar":""},{"name":"Zhang Ze","avatar":""},{"name":"Zhao Sifan","avatar":""},{"name":"Wu Juncheng","avatar":""},{"name":"Pei Chenwei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
