INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tuoc-xu-hoang-gia', 'Công Tước Xứ Hoàng Gia', 'The Duke of Royal Tramp', 'https://phimimg.com/upload/vod/20231013-1/797df20a7e5946c34a60504d1a23fdbd.jpg', 'https://phimimg.com/upload/vod/20231013-1/25596c2db811372fb93fa3ff05b09ace.jpg', '<p>Nó kể về câu chuyện của Lãnh chúa hạng nhất Chen Shengwu và Hoàng đế Shunzhi rơi vào bẫy của Mulima và sống giữa những người dân, họ tình cờ đến lãnh thổ của Vua Nam Vân Nam và gặp vị hôn thê Nightingale của Vua Nam Vân Nam. Để cứu Nightingale và Hoàng đế Shunzhi, Chen Shengwu và Nam vương Vân Nam Câu chuyện về mối quan hệ giữa Wu Dashuai và con trai Wu Shaobao với nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ning Wang","avatar":""},{"name":"Deric Wan","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Rain Lau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
