INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-tuoc-xu-hoang-gia', 'Công Tước Xứ Hoàng Gia', 'The Duke of Royal Tramp', 'công tước xứ hoàng gia the duke of royal tramp ning wang deric wan ng man-tat law kar-ying rain lau ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-su-hoan-hao', 'Cộng Sự Hoàn Hảo', 'Perfect Partner', 'https://phimimg.com/upload/vod/20231013-1/63c2601275668fdbfd709dbeeec6ea52.jpg', 'https://phimimg.com/upload/vod/20231013-1/43a211baf29d9cd505bb777895b5a429.jpg', '<p>Yin Shengnan thích đọc tiểu thuyết hồi hộp và bí ẩn từ khi còn nhỏ, anh luôn muốn trở thành cảnh sát và trở thành một thám tử bậc thầy. Khi vô tình biết được chai rượu cổ đã bị đánh cắp trong nhà dì Yan, cô rất tò mò và muốn tìm hiểu. Cô tìm ra tên trộm thông qua máy ghi âm lái xe của người bạn cùng lớp cấp hai Zhao Chongming. Sau nhiều khó khăn, cuối cùng cô cũng bắt được nghi phạm Holly, người đã giao cho tên trộm trộm chai rượu, đồng thời thu hồi thành công chai rượu cổ và trả lại cho dì Yan. Nhưng có điều gì đó bất thường, không ngờ chai rượu được tìm thấy lại là hàng giả. Sau một hồi điều tra, Yin Shengnan và Zhao Chongming nghi ngờ Qian Xinmin, giám đốc nhà đấu giá, phải chịu trách nhiệm vì dì Yan đã từng mang một chai rượu đến nhà đấu giá để thẩm định. Gần đây, Tiền Tâm Dân đột nhiên từ chức, hành vi đáng ngờ, còn bị một số thành phần vô lương tâm truy đuổi. Để giải đáp bí ẩn và lấy lại bình rượu, cả hai không chỉ lần lượt trải qua những nguy hiểm mà còn sáng tác nên một mảnh tình.</p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lam Song","avatar":""},{"name":"Zheng Qi","avatar":""},{"name":"Yu Huo","avatar":""},{"name":"Ye Chen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
