INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-su-hoan-hao', 'Cộng Sự Hoàn Hảo', 'Perfect Partner', 'cộng sự hoàn hảo perfect partner lam song zheng qi yu huo ye chen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-kite-confused-whereabouts', 'A Kite Confused Whereabouts', 'A Kite Confused Whereabouts', 'https://phimimg.com/upload/vod/20231013-1/78aa2f5d08f824c0cfef38a868fc1f15.jpg', 'https://phimimg.com/upload/vod/20231013-1/dbb0f276a1592a0278ac75351223d695.jpg', '<p>Nửa đêm, đội trưởng cục hình sự đang canh đêm gần dinh thự Xinwang bắt giữ Bai Moyu, đột nhiên nhìn thấy một tên trộm mang theo một chiếc hộp và trốn thoát khỏi Wang Mansion. Bai Moyu đã chiến đấu với tên trộm. Trong quá trình đó, Bai Moyu đã cắt đứt một nắm tóc của tên trộm, tên trộm vội vàng bỏ chạy và đánh mất một lọ bảo vật. Bai Mozhen mở bức thư đến cổng cung điện Wangfu để tìm hiểu sự việc nhưng lại gặp phải sự mỉa mai của Huangfu, tổng giám đốc cung điện. Ngày hôm sau, hoàng đế đột nhiên tuyên bố sẽ cho Vương Tín đại nhân mang diều gỗ đến gặp ngài ba ngày sau. Vua Xin đi vào kho thì phát hiện chiếc diều gỗ đã bị thất lạc. Anh ta khẩn trương mời Bai Moyu và Yang Yuanzhun đến điều tra. Nếu họ không tìm được nó, tai họa sẽ ập đến.</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eric Suen","avatar":""},{"name":"Zhou Ruijun","avatar":""},{"name":"Sunny Chan","avatar":""},{"name":"Tan Tianming","avatar":""},{"name":"Zhang Guoqing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
