INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-ulanfu', 'Câu chuyện về Ulanfu', 'A Story Of Ulanfu', 'null', 'https://phimimg.com/upload/vod/20231013-1/39ce4e5f131a61b8e34f0f430df1c767.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim chọn những sự kiện lịch sử có thật vào tháng 1945 năm 10 khi Ulanfu &quot;một mình đi họp&quot; để giải tán chính quyền bù nhìn Nội Mông để bảo vệ sự thống nhất của quê hương, kể câu chuyện về thế hệ cách mạng vô sản cũ, đồng chí Ulanfu, người được lệnh sử dụng trí tuệ để giải quyết cái gọi là chính phủ lâm thời của &quot;Cộng hòa Nhân dân Nội Mông&quot;, và cuối cùng đã lãnh đạo Nội Mông trên con đường tự trị dân tộc khu vực.</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Xiaoning","avatar":""},{"name":"Bản đồ ngày Qi Na","avatar":""},{"name":"Li Chunming","avatar":""},{"name":"Ngày hoa Tana","avatar":""},{"name":"Gangzhao Riga","avatar":""},{"name":"Narisu trắng","avatar":""},{"name":"Agu","avatar":""},{"name":"Lưu Bành Vân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324387);
