INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-ve-ulanfu', 'Câu chuyện về Ulanfu', 'A Story Of Ulanfu', 'câu chuyện về ulanfu a story of ulanfu li xiaoning bản đồ ngày qi na li chunming ngày hoa tana gangzhao riga narisu trắng agu lưu bành vân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alter-ego', 'Alter Ego', 'Alter Ego', 'null', 'https://phimimg.com/upload/vod/20231013-1/bf1d09668235872dd4e54674ffa0af45.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Wang Rui, một sinh viên của nhóm nghiên cứu, đã du hành đến năm 2050 trong một thí nghiệm để nhìn thấy bản thân tương lai của mình, và thế giới tương lai đang phải đối mặt với một cuộc khủng hoảng lớn do sự đột biến của robot sinh học, để giải quyết vấn đề này, Wang Rui đã trở lại năm 2015 để tập trung vào nghiên cứu, nhưng kết quả nghiên cứu đã bị các đồng nghiệp của anh đánh cắp. Để giải quyết nút thắt giữa những người bạn đồng hành và bản thân, Wang Rui đã quay trở lại năm 2005 một lần nữa, muốn cứu mọi thứ khỏi nguồn. Khi tất cả các quỹ đạo được viết lại, cuộc khủng hoảng biorobot vẫn chưa được giải quyết. Lúc này, Vương Thụy phát hiện ra từ manh mối liệu bản thân tương lai của mình có phải là con người thật của mình hay không. Người yêu chỉ là một con marionette, và tương lai tươi sáng là vô ích, Wang Rui nên cứu mạng mình như thế nào? Và làm thế nào để giải quyết cuộc khủng hoảng của con người?</span></p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Shanshan","avatar":""},{"name":"Zhou Ziqi","avatar":""},{"name":"Li Shuo","avatar":""},{"name":"Wang Yang","avatar":""},{"name":"Liu Yuxuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
