INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat', 'Ám Sát', 'Assasination', 'null', 'https://phimimg.com/upload/vod/20231013-1/cfbefd7d086e6caf561ec4ca2fdf1f26.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tại Thượng Hải trong thời kỳ đảo bị cô lập, Chu Kỳ Phương, chủ tịch Phòng Thương mại Sea Wind, người không đồng ý phục vụ quân đội Nhật Bản, và người bảo trợ Lu Nansheng và các lang băm và hồ khác đã chống cự tuyệt vọng và bắt đầu một trận chiến sinh tử với thiếu tướng Nhật Bản Saito.</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lv Liangwei","avatar":""},{"name":"Yang Mingyi","avatar":""},{"name":"Zhou Zhuo","avatar":""},{"name":"Yuan Qianshan","avatar":""},{"name":"Zhang Qi","avatar":""},{"name":"Vương Diêu","avatar":""},{"name":"Trương Hồng Vĩ","avatar":""},{"name":"Hàn Long Xuyên","avatar":""},{"name":"Từ Mục","avatar":""},{"name":"Lý Đông Hải","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324387);
