INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-sat', 'Ám Sát', 'Assasination', 'ám sát assasination lv liangwei yang mingyi zhou zhuo yuan qianshan zhang qi vương diêu trương hồng vĩ hàn long xuyên từ mục lý đông hải ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-nu-hoang', 'Ám Sát Nữ Hoàng', 'Assassinate The Queen', 'null', 'https://phimimg.com/upload/vod/20231013-1/d01a3f4e3c0ba3498fb260fd24a832d3.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong những năm cuối cùng của triều đại Yin Shang, Su Daji đã ra lệnh tiêu diệt gia đình của tướng Situ Halberd, người đã đe dọa ông. Để bảo vệ dòng máu duy nhất của gia tộc Situ, những người trung thành như Bigan, Jiang Ziya, Huang Feihu và Bo Yikao đã giấu hai mẹ con trốn thoát trong dân chúng, và đặt tên cho đứa trẻ là Yu Chen. Trong mười năm qua, những người trung thành và chính trực đã bất chấp sự sống và cái chết, và liên tiếp thực hiện các vụ ám sát Tô Đại Tế, nhưng họ thường xuyên thất bại. Su Daji phát hiện ra rằng chính Bi Gan và những người khác là chủ mưu. Giam cầm Giang Tử Nhã và bức hại Bigan, trước khi chết, Bi Gan đã tìm thấy Yu Chen, hy vọng rằng anh ta có thể tiêu diệt quỷ thiếp và hoàn thành nhiệm vụ của Kuang là hỗ trợ nhà Thương Giang Sơn Sheji. Tuy nhiên, vào thời điểm này, Yu Chen đã là một cậu bé thành phố hoài nghi và yêu tiền, liệu anh ta có thể đảm nhận nhiệm vụ lớn này không? Trong một loạt các hoạt động giải cứu sau đó, Yu Tan dần dần bị xúc động bởi tinh thần không sợ hãi của Bo Yi Kao và những người khác, và niềm tin vào việc trở thành một anh hùng và cứu người dân trong tình trạng khó khăn đã ra đời, truyền cảm hứng cho lòng trung thành trong máu của Yu Chen, và Yu Tan, người có thể chạy trốn đã tiếp quản sứ mệnh lịch sử.</span></p>', 'Full', 1, 'single', 'completed', 14, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yingtong","avatar":""},{"name":"Han Jinming","avatar":""},{"name":"Xu Yingzhi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324387);
