INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-rong', 'Anh Em Rồng', 'Dragon Brothers', 'null', 'https://phimimg.com/upload/vod/20231013-1/4b146aea1a4debf87a5f4a68ac3aba01.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Từ nhỏ, Lý Hỏa đã thích xem phim Hong Kong. Một ngày nọ, khi còn nhỏ, anh vô tình nhìn thấy Lý Tiên Ngưu rời khỏi nhà với một nhóm người một cách uy nghiêm, và bức ảnh ngay lập tức trùng khớp với bộ phim, và Li Mars đoán rằng cha anh là một ông chủ địa phương, mặc dù cha anh chỉ định giết lợn.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Cho nên Lý Hỏa vốn dĩ không nghe lời, từ đó đến nay đã ngưỡng mộ Lý Thiên Ngưu. Còn Lý Tiên Ngưu thấy con trai mất mẹ từ nhỏ cũng rất ngoan ngoãn nên không chọc vào lời nói dối này. Đồng thời, nó cũng giáo dục anh, học tập chăm chỉ và giúp kiếm được nhiều tiền hơn trong tương lai.</span></p>', 'Full', 1, 'single', 'completed', 13, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Bolun","avatar":""},{"name":"Liu Xiang","avatar":""},{"name":"Shao Zichen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
