INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-vo-duong-gia-tuong', 'Ảnh Võ Dương Gia Tướng', 'Shadow Warrior', 'null', 'https://phimimg.com/upload/vod/20231013-1/0206c5d719568dad633599065bdb0ecc.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim này kể về câu chuyện của You Kong và Luo Jing, hai người yêu nhau sống ở thế kỷ 21, đến nhà Tống do nhầm lẫn, do sự xuất hiện của hai người, lịch sử đi chệch khỏi quỹ đạo ban đầu, và chỉ bằng cách tìm thấy năm viên đá quý, thời gian và không gian mới có thể trở lại bình thường. Trong trận chiến đèo Diêm Môn, Dương Lưu Lang bị thương, ngoại hình bị phá hủy. Sau khi được U Giác giải cứu, Dương Lưu Lang phát hiện người này trông khá giống mình. Để chiến đấu với Pan Renmei, Yang Rokuro cầu xin You Kong giả vờ là chính mình. Bạn và Luo hòa hợp với Yang Rokuro và Chai Meirong, và họ có một mối quan hệ và quyết tâm giúp đỡ Rokuro. Thiết kế của You Kong đã dẫn Pan Renmei vào trò chơi, nhưng thật bất ngờ, kế hoạch này đã được Pan Renmei nhận ra và đi vào bộ đầy đủ của Pan Renmei. Trong quá trình tránh né những kẻ truy đuổi, Dương Lưu Lang đã hy sinh bản thân để bảo vệ mọi người. You Kong, người thoát khỏi sự truy đuổi, được truyền cảm hứng từ tình cảm của gia đình và đất nước Liulang, dẫn tất cả binh lính chính nghĩa tấn công Bianliang, và với sức mạnh của tướng quân vĩ đại Huyan Pixian, đã đánh bại Pan Renmei và tìm thấy năm viên ngọc. Lịch sử vẫn là lịch sử ban đầu!</span></p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhu Xiaopeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
