INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-tich-thoi-dai-cua-chung-toi', 'Ấn Tích Thời Đại Của Chúng Tôi', 'Our Beautiful Memory', 'null', 'https://phimimg.com/upload/vod/20231013-1/54ca9ffb9b6de233da4fadaa222cd8f7.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim này chủ yếu kể về trải nghiệm xúc động khó quên của anh hùng và nữ chính, người yêu thời thơ ấu Giang Lai và vẫn chơi với nhau từ nhỏ, và ngay khi hai người sắp đạt được kết quả tích cực, Cảnh Kinh muốn cướp lấy tình yêu, Giang Lai không cúi đầu trước thế lực, nhưng anh không thể đối mặt với sự thật rằng mẹ anh đã chết và bỏ nhà đi. Cuối cùng, anh không thể từ bỏ tình yêu của mình dành cho người tĩnh lặng bất kể điều gì, và trở lại và vẫn nhận ra nhau vào ngày thứ 701 rời đi, và cuối cùng đã kết thúc hoàn hảo.</span></p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Song Yan","avatar":""},{"name":"Xia Wenxi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324387);
