INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-giao-huong-dong-que-8x', 'Bản Giao Hưởng Đồng Quê 8x', '80s Country Symphony', 'null', 'https://phimimg.com/upload/vod/20231013-1/aaeae430be9c97803c19f885aaf3302d.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Hai anh em Wei Erdonkey và Wu Deshun sinh ra ở nông thôn vào những năm 80, và bắt kịp với sự nuôi dưỡng của văn hóa nước ngoài trên truyền hình và đài phát thanh, đặc biệt là tác động của văn hóa Hồng Kông và Đài Loan, khiến hai anh em chôn vùi tham vọng lớn trong lòng khi còn trẻ. Họ đã trải qua cuộc sống trong khuôn viên trường của thế hệ sau những năm 80 cùng tuổi, tình yêu ngu dốt, kẻ bắt nạt nhỏ của thị trường, đầu sóng và quần ống loe, tất cả đều được phô trương trên họ. Trước khi tốt nghiệp trung học cơ sở, Wei Erdonkey đã đến Bắc Kinh với khao khát, để lại anh trai Wu Deshun ở lại làng, sau khi Wei Erdonkey rời đi, Wu Deshun cũng không có ý định đi học, bỏ học và đến lớp thổi hoa để học thổi, lớp thổi hoa đã trải qua thời hoàng kim vào những năm 70, văn hóa mới chảy vào làng, văn hóa phương Tây có tác động lớn đến lớp thổi hoa, cạnh tranh khốc liệt, tiêu biểu nhất là ban nhạc kèn vàng do Jingba thành lập là đối lập nhất, văn hóa Trung Quốc và phương Tây chính thức mở ra một cuộc chiến cưa lớn không khói súng...</span></p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wei Jin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324387);
