INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-ma-va-hoang-tu', 'Bạch Mã Và Hoàng Tử', 'White Horse And Prince', 'null', 'https://phimimg.com/upload/vod/20231013-1/3d4077b98be2b35b09b96422643c8cf9.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Lin Fan, người bán xe cũ, đã đến đoàn làm phim Bạch Mã để giao xe đạo cụ, và gặp nam diễn viên nhóm Mina, người tận tâm và nghiêm túc, và giành được sự ưu ái của Lin Fan và quản lý cảnh Bai Yichen. Mina được nhà quảng cáo rất sặc sỡ mời đến KTV Mr. Chen, may mắn là Lin Fan đã đến kịp thời để ngăn chặn những lời tục tĩu Mr. Chen, Lin Fan nhầm tưởng Mina là một ngôi sao, nói dối rằng anh ta là CEO của tập đoàn Lin Group, và sử dụng chiếc xe sang trọng của đại lý xe hơi để đón Mina, Mina cũng rất đau khổ, muốn làm rõ danh tính của mình, nhưng sợ mất Lin Fan. Bai Yichen thế hệ thứ hai giàu có thực sự có ý định biến Mina trở thành một nữ số một bom tấn thực sự, và Huang Dao cực kỳ ích kỷ cản trở mọi cách. Lin Fan đã nhiều lần muốn thú nhận thân phận của mình, nhưng luôn bỏ lỡ, Mina rất bình tĩnh nói với Lin Fan rằng anh chỉ là một diễn viên nhỏ, nhưng Bai Yichen đã dùng kế hoạch tiết lộ danh tính của Lin Fan là bán xe cũ, khiến Mina tức giận rời đi. Giám đốc Huang muốn giết Mina, và Lin Fan xuất hiện một lần nữa để bảo vệ Mina, nhưng anh ta bị thương nặng.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Đi lòng vòng, một số người yêu cuối cùng trở thành người phụ thuộc vì &quot;tình yêu&quot;.</span></p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Xiao","avatar":""},{"name":"Li Yuanzhen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
