INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-trong-rong', 'Bằng Chứng Trống Rỗng', 'The Void Evidence', 'null', 'https://phimimg.com/upload/vod/20231012-1/5bc0dae384dce8819598a30ec4b81329.jpg', '<p>&quot;Giết người ngược&quot; bắt đầu bằng việc đội cảnh sát hình sự nhận được một email truyền hình trực tiếp về vụ giết người ẩn danh. Từ góc nhìn thám tử của các nhân vật khác nhau trong đội cảnh sát hình sự, phim dần dần tiến tới giải quyết bí ẩn, cho phép tái hiện một vụ giết người nhiều năm trước trước mặt mọi người dưới hình thức trả thù. Ngoài cốt truyện bí ẩn, cô đọng, sự xích mích, vướng mắc giữa tội phạm và cảnh sát cũng như sự thật khó hiểu, bộ phim còn hé lộ những mối liên hệ tài tình giữa các nhân vật khác nhau trong xã hội và nhiều điều khác nhau trong từng chi tiết nhỏ, trong đó có tình cảm gia đình, nỗi khao khát. vì tình anh em, tình anh em nồng nàn và cách thể hiện chân thực hình ảnh công an nhân dân trong thời đại mới vừa nhức não, vừa kích thích tư duy.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xue Fei","avatar":""},{"name":"Huang Junpe","avatar":""},{"name":"Yan Fengbin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324387);
