INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-oi', 'Người Lạ Ơi', 'My Beloved Stranger', 'https://phimimg.com/upload/vod/20231012-1/05d98efde3e357c3dadc959e22609885.jpg', 'https://phimimg.com/upload/vod/20231012-1/5f0bd4a3efb22df1f76899ea3775448c.jpg', '<p>Đăng DJ - chàng &quot;bad boy&quot; không thích gắn bó lâu dài với bất cứ cô nàng nào. Một ngày nọ, xuất hiện cô gái xinh đẹp muốn tiếp cận anh để thực hiện nhiệm vụ giải cứu hành tinh của mình. Giữa hai người lại có mối liên hệ tình cảm kéo dài hàng ngàn năm, liệu sự thật là như thế nào?</p>', 'Full', 1, 'single', 'completed', 12, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Karik","avatar":""},{"name":"Thùy Anh","avatar":""},{"name":"Trịnh Thảo","avatar":""},{"name":"Trương Thế Vinh","avatar":""},{"name":"Huy Khánh","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324387);
