INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau-tho-ngay', 'Tình Đầu Thơ Ngây', 'First Love', 'https://phimimg.com/upload/vod/20231012-1/b49d2eea045266d86cf577e0e51d0518.jpg', 'https://phimimg.com/upload/vod/20231012-1/6bc994e20ab8d7b00cf37eb48b8f428e.jpg', '<p>Mỹ An luôn thầm thương trộm nhớ Thiên, nam sinh toàn diện khóa trên. Tuy được các cô gái trong trường ngưỡng mộ nhưng Thiên tính tình lập dị, lạnh lùng. Một ngày, bố An đi công tác xa nên đành gửi con gái ở nhờ nhà người bạn thân nhất, Thiên bỗng có thêm cô bạn cùng nhà bất đắc dĩ.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Nguyễn Thái Sơn","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Lan Phương","avatar":""},{"name":"Mai Kỳ Hân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324387);
