INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-tuyet-voi-khi-o-ben-em', 'Thật Tuyệt Vời Khi Ở Bên Em', 'Heavenly Being with You', 'https://phimimg.com/upload/vod/20231012-1/e7b1735fbee1cde36502ee9a0e83deb9.jpg', 'https://phimimg.com/upload/vod/20231012-1/132783dd05db8377f455bb0df0ec6405.jpg', '<p>Chuyện phim Thật tuyệt vời khi ở bên em bắt đầu khi ngôi sao điện ảnh Đình Bảo (Harry Lu) và vợ là Mi Minh (Oanh Kiều) bất ngờ gặp tai nạn giao thông.&nbsp; Tuy bị mất trí nhớ, Bảo vẫn sớm phải trở lại showbiz bởi hàng chục hợp đồng đã ký kết từ trước lúc bi kịch xảy ra.&nbsp; Từ đây, anh dần phát hiện ra bản thân từng sử dụng rất nhiều chiêu trò tình ái hòng trở nên nổi tiếng dưới sự giúp sức của ông bầu Ân (Tiến Luật). Cuộc hôn nhân của nam diễn viên thực tế không hề được công bố, và Mi Minh luôn phải chịu tiếng là mẹ đơn thân.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Harry Lu","avatar":""},{"name":"Tiến Luật","avatar":""},{"name":"B Trần","avatar":""},{"name":"Oanh Kiều","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324388);
