INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chu-ma-ca-rong', 'Cậu Chủ Ma Cà Rồng', 'The Vampire', 'null', 'https://phimimg.com/upload/vod/20231011-1/10f2ffe48b688d7bf17842f19cabd5ed.jpg', '<p>Phim ma cà rồng đầu tiên của Việt Nam Trong một thế giới giả tưởng hiện đại, năm cô gái trẻ tụ tập để tranh giành cơ hội thay đổi cuộc đời mà không hề hay biết về một kế hoạch khát máu đang chờ đợi họ.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trương Minh Thảo","avatar":""},{"name":"Vo Dang Duy Luan","avatar":""},{"name":"Yeye Nhat Ha","avatar":""},{"name":"Truc May","avatar":""},{"name":"Lam Huong Giang","avatar":""},{"name":"Huyen Thoai","avatar":""},{"name":"Mai Kỳ Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324388);
