INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-thay-ngoi-sao', 'Anh Thầy Ngôi Sao', 'Anh Thầy Ngôi Sao', 'https://phimimg.com/upload/vod/20231011-1/ee98b6f2bfdd2f4cd4b0cbd3c0175d3d.jpg', 'https://phimimg.com/upload/vod/20231011-1/c003d679666c51f998cd6cb9ef736099.jpg', '<p>Chuyện phim Anh thầy ngôi sao theo chân Hoàng (Huyme) - chàng giáo viên thanh nhạc trẻ tuổi luôn nuôi mộng một ngày trở thành ca sĩ nổi tiếng. Nóng lòng muốn được đứng hát trên sân khấu, anh sập bẫy kẻ gian và mắc nợ một số tiền lớn.&nbsp; Quá đau buồn, Hoàng chấp nhận đến Xóm Quí - một làng chài ngoài đảo xa - để giảng dạy. Đời không như mơ, Hoàng buộc phải làm quen với lớp học nghèo nàn chỉ có 5 em học sinh, cùng cuộc sống lam lũ của người dân nơi đây.&nbsp; Với sự giúp đỡ của trưởng xóm Bừng (Đức Thịnh) và cô “thợ đụng” Sâm (Miu Lê), anh vẫn theo đuổi ước mơ khi gửi các ca khúc do mình tự sáng tác cho một cuộc thi âm nhạc.&nbsp; Tuy nhiên, mọi chuyện diễn ra không hề đơn giản như những gì chàng giáo viên trẻ tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Huyme","avatar":""},{"name":"NSƯT Đức Thịnh","avatar":""},{"name":"Miu Lê","avatar":""},{"name":"Xuân Nghị","avatar":""},{"name":"Gil Le","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324388);
