INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-4-nha-co-khach', 'Lật Mặt 4: Nhà Có Khách', 'Face Off 4: The Walking Guests', 'https://phimimg.com/upload/vod/20231011-1/b467de00af63280d3f008b4219d90bfa.jpg', 'https://phimimg.com/upload/vod/20231011-1/7ebadff5708adc5a0a7c3aaf8348469b.jpg', '<p>Lật Mặt: Nhà Có Khách xoay quanh chuyến trở về nhà ngỡ tưởng rất vui vẻ đầm ấm của Vy cùng bạn bè. Thế nhưng, một chuỗi những tai nạn và sự việc bất thường diễn ra đã đẩy tình thế của tất cả mọi người, đặc biệt là Vy vào tình thế nguy hiểm. Làm sao để có thể cứu Vy và ngăn những mối nguy hiểm tiếp theo xảy ra? Tai nạn đã xảy đến với mẹ của Vy và cậu em trai có liên quan gì đến những thế lực hiểm ác đang đeo bám tất cả mọi người?</p>', 'Full', 1, 'single', 'completed', 15, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lý Hải","avatar":""},{"name":"và một số diễn viên khác","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324388);
