INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('savage', 'Savage', 'Savage', 'https://phimimg.com/upload/vod/20231009-1/2d31d05b6058874910105c789d53bbe9.jpg', 'https://phimimg.com/upload/vod/20231009-1/03d8764d6debf5f76363d407e3839ba4.jpg', '<p>Lấy cảm hứng từ những câu chuyện có thật về các băng đảng đường phố ở New Zealand trong suốt 30 năm, chúng ta theo dõi Danny tại ba thời điểm quan trọng trong cuộc đời anh khi anh lớn lên từ một cậu bé trở thành kẻ thực thi bạo lực của một băng đảng.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"John Tui","avatar":""},{"name":"Jake Ryan","avatar":""},{"name":"Olly Presling","avatar":""},{"name":"Seth Flynn","avatar":""},{"name":"Chelsie Preston Crayford","avatar":""},{"name":"Erroll Shand","avatar":""},{"name":"Dominic Ona-Ariki","avatar":""},{"name":"Cameron Brown","avatar":""},{"name":"Jack Parker","avatar":""},{"name":"Creedence Phillips","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324388);
