INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-acemaster', 'Hoa Acemaster', 'Top Female Force', 'null', 'https://phimimg.com/upload/vod/20231008-1/b2a74fd92d865907b787e4c1a7342b89.jpg', '<p>Dưới sự lãnh đạo của tổng tư lệnh Li Wei, thế hệ mới của Bawanghua Xiao Qiao, Ah, Hao Ge và Yan Pig đã phá thành công nhiều vụ án quy mô lớn và trở nên nổi tiếng, và ánh đèn sân khấu làm lu mờ Phi Hổ dưới sự chỉ huy của Huang SIR . A Li, KING, Shantou và Black. Hai đội bắt đầu nhìn nhau và bí mật thi đấu.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Siqi","avatar":""},{"name":"Mai Changqing","avatar":""},{"name":"Shi Xiu","avatar":""},{"name":"Kabby Hui","avatar":""},{"name":"Daniel Chan Yee-Heng","avatar":""},{"name":"Alycia Chan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324388);
