INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-sang-roi-ta-ngu-di-thoi', 'Trời Sáng Rồi Ta Ngủ Đi Thôi', 'Good Morning and Good Night', 'https://phimimg.com/upload/vod/20231007-1/cb66663f8cc0041a60ef672fcc723b19.jpg', 'https://phimimg.com/upload/vod/20231007-1/430feb92c2b3115c34caf2d178b688d5.jpg', '<p>Chuyện phim Trời sáng rồi, ta ngủ đi thôi theo chân chàng nhạc sĩ trẻ Vĩnh Tâm (Hà Quốc Hoàng) và nữ tài xế Giang Thanh (Trần Lê Thúy Vy). Tình cờ gặp nhau qua một cuốc xe ôm công nghệ, cả hai quyết định dành một ngày để cùng vi vu khắp Sài Gòn.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hà Quốc Hoàng","avatar":""},{"name":"Trần Lê Thúy Vy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324388);
