INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-quynh', 'Trạng Quỳnh', 'Trạng Quỳnh', 'https://phimimg.com/upload/vod/20231007-1/326ad17cf25b900f80f555a384e577f9.jpg', 'https://phimimg.com/upload/vod/20231007-1/173c79cacf719bb01af2e94c54f440f0.jpg', '<p>Nội dung bộ phim Trạng Quỳnh được phóng tác từ những giai thoại về nhân vật cùng tên trong dân gian Việt Nam. Chuyện phim xoay quanh Quỳnh (Quốc Anh) - một anh chàng thông minh, ma mãnh, rất thích bày trò trêu chọc người dân trong làng.&nbsp; Quỳnh thầm thương trộm nhớ nàng Điềm (Nhã Phương) - con gái của thầy Đoàn (Tùng Tuki). Anh cứ thế ra sức tán tỉnh người trong mộng mà chưa thành. Song, cô gái tài sắc vẹn toàn còn sớm lọt vào mắt xanh của Trịnh Bá (Công Dương) - cháu của chúa Trịnh.&nbsp; Gã dùng âm mưu hãm hại thầy Đoàn để ép Điềm phải làm đám cưới. Không chịu khuất phục, cô cùng Quỳnh và người bạn thân Xẩm (Trấn Thành) khăn gói lên kinh để báo quan.</p>', 'Full', 1, 'single', 'completed', 16, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Quốc Anh","avatar":""},{"name":"Nhã Phương","avatar":""},{"name":"Trấn Thành","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Công Dương","avatar":""},{"name":"NSƯT Đức Thịnh","avatar":""},{"name":"Văn Tùng","avatar":""},{"name":"Bạch Long","avatar":""},{"name":"Linh Trung","avatar":""},{"name":"Tuấn Voi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324388);
