INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yolo-ban-chi-song-mot-lan', 'YOLO : Bạn Chỉ Sống Một Lần', 'YOLO : Bạn Chỉ Sống Một Lần', 'https://phimimg.com/upload/vod/20231007-1/bbb0ed8663548f6c53798876f873e2e3.jpg', 'https://phimimg.com/upload/vod/20231007-1/f79087dd3729ebccbb366b98adbbe8d8.jpg', '<p>Những người trẻ dấn thân theo đuổi đam mê âm nhạc, đặc biệt là “thế giới ngầm” - underground. Để thỏa mãn đam mê ca hát với cá tính âm nhạc của riêng mình, họ phải trải qua nhiều sóng gió và nỗ lực không ngừng để khẳng định bản thân. Những cám dỗ, mảnh tối của giới giải trí cũng là những thách thức để người bạn trẻ này đối mặt và không vấp ngã.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Soobin Hoàng Sơn","avatar":""},{"name":"Cường Seven","avatar":""},{"name":"Nguyễn Minh Trang","avatar":""},{"name":"Băng Di","avatar":""},{"name":"Khánh Huyền","avatar":""},{"name":"Tuấn Trần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324388);
