INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-phan-1', 'Thấy (Phần 1)', 'See (Season 1)', 'https://phimimg.com/upload/vod/20231006-1/4b2bb349a9c953faeee16ce5d9e720c3.jpg', 'https://phimimg.com/upload/vod/20231006-1/679a427b47f8648e30307430072031f6.jpg', '<p>Xa trong một tương lai lạc hậu, loài người đã mất đi khả năng nhìn, và xã hội phải tìm ra những cách mới để tương tác, xây dựng, săn bắn và để tồn tại. Tất cả những điều đó được thử thách khi một cặp song sinh được sinh ra với thị giác.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 21, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Momoa","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Yadira Guevara-Prip","avatar":""},{"name":"Nesta Cooper","avatar":""},{"name":"Sylvia Hoeks","avatar":""},{"name":"Archie Madekwe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324388);
