INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-thu-cua-con-dau-quy', 'Lá thư của con dấu quỷ', 'Legend of the Demon Seal', 'https://phimimg.com/upload/vod/20231006-1/fd7eaeb67648044985674ac5012bcf1b.jpg', 'https://phimimg.com/upload/vod/20231006-1/bff215380a84297e93881589a0684053.jpg', '<p>Làm việc như một họa sĩ bình thường trong dự án truyện tranh The Legend of Demon Sea của Bai Ze, họa sĩ đầy tham vọng Feng Xue cảm thấy mình như bị lãng phí tài năng. Để trút bỏ sự thất vọng của mình, anh ấy bắt đầu một phiên bản khác của dự án, lấp đầy những cuộc phiêu lưu minh họa của một bậc thầy giả kim bằng những câu chuyện thần thoại tương đồng với công việc hàng ngày của anh ấy. Với truyện tranh của mình, Feng sẽ trả thù bất cứ khi nào anh bị coi thường hoặc bị bỏ qua trong xưởng vẽ, lôi kéo đồng nghiệp và sếp của mình vào những cảnh không mấy hay ho. Nhưng khi Bai Ze phát hiện ra một phiên bản minh họa về chính mình đang đau khổ dưới bàn chải của Feng, anh ấy không hề tức giận. Anh khen ngợi sự độc đáo của Feng Xue và đưa bản thảo mới cho sếp của mình. Đây là lúc Bai Ze cũng học được ý nghĩa của việc chán nản trong công việc, thách thức anh lựa chọn giữa những gì anh tin tưởng và những gì công việc yêu cầu.</p>', 'Full', 1, 'single', 'completed', 18, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sammul Chan Kin-Fung","avatar":""},{"name":"Yu Hanbing","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Jin Song","avatar":""},{"name":"Nina Wu","avatar":""},{"name":"Zhu Jiaqi","avatar":""},{"name":"Li Tianye","avatar":""},{"name":"Zhang Xinna","avatar":""},{"name":"Zhou Haodong","avatar":""},{"name":"Lilyice Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324388);
