INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thung-lung-khoa-rong', 'Thung Lũng Khóa Rồng', 'Locked Dragon Valley', 'https://phimimg.com/upload/vod/20231006-1/7fa5ece4cc1aeeb3421a1c2a346f2a9d.jpg', 'https://phimimg.com/upload/vod/20231006-1/2edcdc6c9dc84f4c6741bb1bfb57fd72.jpg', '<p>Cách đây rất lâu, bọn cướp đã cướp một số lượng lớn kho báu vàng bạc khi đi qua Thung lũng Suolong và bị bộ tộc Mang chặn lại. Cả hai bên và ngựa đều bị giết ở Thung lũng Suolong, nhưng cuối cùng, không bên nào ra khỏi Thung lũng Suolong và biến mất một cách kỳ lạ. Tất cả bảo bối đều không rõ, có người nói đều bị phá hủy, có người bị thú rừng nguyên thủy ăn thịt, có người bị mụ phù thủy gài bẫy. Để tìm được kho báu, Ngộ Không một mình đến chùa Suolong để lấy bản đồ kho báu và phòng kho báu mở kho báu, sau đó đi đến Thung lũng Suolong.</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wen Dongjun","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Li Sha","avatar":""},{"name":"Li Muyao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324388);
