INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-chuyen-nghe', 'Băng Đảng Chuyển Nghề', 'Change of Gangster', 'https://phimimg.com/upload/vod/20231006-1/72702bd2765efe5b0f4f78b0ac890ae9.jpg', 'https://phimimg.com/upload/vod/20231006-1/32d86bb107be376977fa2e5fcbbeff3a.jpg', '<p>Nội dung phim kể về diễn viên điện ảnh anh Vũ và sao nhí Feyrman 
không ưa nhau trong đoàn làm phim. Anh Vũ bị thương mất trí, sau khi 
tỉnh lại cứ tưởng mình là đại ca, và tưởng Feyrman là con trai mình. Để 
hoàn thành bộ phim Đạo diễn đã để anh Vũ lẫn lộn giữa thật và giả, không
 ngờ lại bị cuốn vào một vụ án cướp của thật sự. Anh Vũ và Feyrman trong
 bối cảnh thực thực hư hư tình cảm ngày càng thân thiết, cuối cùng cùng 
nhau hóa giải mọi nguy nan.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Francis Ng","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Qiao Shan","avatar":""},{"name":"Wen Song","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Philippe Joly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324388);
