INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phat-nhanh-bff', 'Chuyển Phát Nhanh BFF', 'BFF Courier', 'https://phimimg.com/upload/vod/20231006-1/a2cb3b356131010aa17cfa2993c72e70.jpg', 'https://phimimg.com/upload/vod/20231006-1/f5f5e475c3fabada55c3e5171fe31c39.jpg', '<p>Truyện kể về bốn người phụ nữ độc thân quen nhau từ nhỏ và có mối quan hệ rất thân thiện, mỗi người đều có những tính cách, giá trị hoàn toàn khác nhau và không có điểm chung nên thường tạo ra những trò đùa nhỏ trong cuộc sống hàng ngày. Câu chuyện của bốn người phụ nữ này giúp khán giả hiểu sâu hơn về những khuôn mẫu suy nghĩ, quan điểm về tình yêu, quan điểm về gia đình, bạn bè… của nhiều người phụ nữ trong xã hội, giống như một bộ từ điển dành cho phụ nữ. Mỗi người đều có tính cách và cách làm việc khác nhau, theo năm tháng sẽ không thể tránh khỏi những bất đồng, tuy nhiên bốn người họ luôn xử lý rất tốt và hòa hợp với nhau. Tuy nhiên, khi mọi chuyện đụng chạm đến chuyện riêng tư của mỗi người, và thậm chí phản bội hoặc che giấu họ, Có chỗ nào cho sự chung sống hòa bình không?</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Monie Tung Man-Lee","avatar":""},{"name":"Regen Cheung","avatar":""},{"name":"Yee-Man Lee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324388);
