INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-duc-gioi-tinh-phan-1', 'Giáo Dục Giới Tính (Phần 1)', 'Sex Education (Season 1)', 'https://phimimg.com/upload/vod/20231001-1/b105adc166464822c3a8c9b036da5f4e.jpg', 'https://phimimg.com/upload/vod/20231001-1/832903c98dbd5c3534dd0ae08abe2f8c.jpg', '<p>Sex Education theo chân cậu nam sinh “còn trinh trắng” Otis (Asa Butterfield) tổ chức một buổi trị liệu tình dục trong trường học của mình, lấy cảm hứng từ chính công việc của mẹ. Otis luôn cảm thấy không hứng thú với những vấn đề về tình dục và điều đó khiến mẹ lẫn bạn bè cậu khá quan ngại. Mọi chuyện bắt đầu dở khóc dở cười hơn khi cô bạn nổi loạn đề xuất về phòng tư vấn tâm sinh lý tuổi mới lớn.Không chỉ muốn giúp cải thiện đời sống chăn gối cho các bạn mình, mục đích của ý tưởng táo bạo này của cậu bé còn là để cưa đổ cô gái trong mơ Maeve (Emma Mackey) - một nữ sinh thông minh và cá tính, và cũng là “đối tác” của Otis trong buổi trị liệu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 22, 2019, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gillian Anderson","avatar":""},{"name":"Asa Butterfield","avatar":""},{"name":"Emma Mackey","avatar":""},{"name":"Kedar Williams-Stirling","avatar":""},{"name":"Alistair Petrie","avatar":""},{"name":"Mikael Persbrandt","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Ncuti Gatwa","avatar":""},{"name":"Connor Swindells","avatar":""},{"name":"Aimee Lou Wood","avatar":""},{"name":"Mimi Keene","avatar":""},{"name":"Chaneil Kular","avatar":""},{"name":"Alexander Westwood","avatar":""},{"name":"Tanya Reynolds","avatar":""},{"name":"Cerys Watkins","avatar":""},{"name":"Patric","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6f