INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lich-su-cua-hien-tai', 'Lịch Sử Của Hiện Tại', 'Shining Modern History', 'https://phimimg.com/upload/vod/20230930-1/3588629241d840abb7b34b794a46bdf8.jpg', 'https://phimimg.com/upload/vod/20230930-1/fe364033d0dbae94ec8df60ede3f0713.jpg', '<p>Huyn Dae và Min Ju là bạn tình của nhau, vốn dĩ hai người đã quyết
 định khi một trong hai người kết hôn thì sẽ kết thúc mối quan hệ này. 
Thế nhưng dục vọng không đáy của Huyn Dae đã đẩy hai người xuống vực 
thẳm. Min Ju cũng không cách nào buông bỏ mối tình mà mình không thể có 
được. Mối quan hệ của hai người dần trở nên phức tạp, khát khao tình dục
 ngày càng khó điều khiển. Khi dục vọng và nhân tính được thể hiện một 
cách trần trụi nhất.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sang-won","avatar":""},{"name":"Jung Da-won","avatar":""},{"name":"Lee Won-jong","avatar":""},{"name":"Ha Joo-hee","avatar":""},{"name":"Lee Yu-mi","avatar":""},{"name":"Ha Soo-min","avatar":""},{"name":"Geum Chae-an","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324388);
