INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tham-hoa-nui-baekdu', 'Đại Thảm Hoạ Núi Baekdu', 'Ashfall', 'https://phimimg.com/upload/vod/20230930-1/97c860d5bb192074879025db455b91e5.jpg', 'https://phimimg.com/upload/vod/20230930-1/a139ed77bb056b6524451fec95292a3a.jpg', '<p>Núi Baekdu – ngọn núi lửa cao nhất bán đảo Triều Tiên nằm ở biên giới giữa Triều Tiên và Trung Quốc bất ngờ phun trào, khiến toàn bộ người dân trên bán đảo kinh hoàng. Thảm họa chưa dừng lại ở đó, tiếp theo sau sẽ là những lần phun trào được dự báo là dữ dội hơn nữa, đe dọa sẽ nhấn chìm toàn bộ bán đảo Triều Tiên trong tro tàn tận thế. Một kế hoạch hợp tác giữa Hàn Quốc và Triều Tiên được đề ra để ngăn cản núi lửa Baekdu phun trào, liệu nhiệm vụ dường như bất khả thi này có thể thành công?</p>', 'Full', 1, 'single', 'completed', 21, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Ha Jung-woo","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Bae Suzy","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kim Si-a","avatar":""},{"name":"Lee Sang-won","avatar":""},{"name":"Ok Ja-yeon","avatar":""},{"name":"Choi Gwang-il","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324388);
