INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom', 'Hàng Xóm', 'Handsome Neighbor', 'https://phimimg.com/upload/vod/20230929-1/e9e3383fb1f2b0c7a058995fada528d9.jpg', 'https://phimimg.com/upload/vod/20230929-1/431ae17963f77cfcd9f3dddf703ae884.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;">Một tay đầu cơ không nổi tiếng có năm em trai, để kiếm thêm tiền cho các em chăm chỉ học tập, ngày nào anh ta cũng về sớm và về muộn để xếp hàng mua vé. Anh ta sống trong một tầng bán hầm. Cô gái có ước mơ âm nhạc, do mẹ không hiểu nên tôi đã lên thành phố để ủng hộ ước mơ của mình thông qua phát sóng trực tiếp. Những người đầu cơ thì đi ngủ sớm và dậy sớm, còn những người dẫn chương trình thì đi ngủ muộn và dậy muộn. Do Hai người chênh lệch múi giờ, họ thực hiện hàng loạt câu chuyện cười ngớ ngẩn nhưng ấm áp, tuy hài hước nhưng hơi cảm động, trong cuộc sống thực tế và suy nghĩ vô hạn, hãy cố gắng tìm sự cân bằng, chất lượng và thú vị, kể về cuộc đời bất lực của những con người nhỏ bé trong thành phố lớn và cuộc sống tuyệt vời của họ.</span></p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peng Yu Si","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324388);
