INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-hau-vuong-that-gia-ton-ngo-khong', 'Mỹ Hầu Vương ：Thật Giả Tôn Ngộ Không', 'The True and False Monkey King', 'https://phimimg.com/upload/vod/20230929-1/50125188bf391e8e0addd3f58fe4227b.jpg', 'https://phimimg.com/upload/vod/20230929-1/86e010a784f783dcf0f5ee046f225875.jpg', '<p>Hai con linh hầu ở Hoa Quả Sơn vốn là huynh đệ thân thiết. Lục Nhĩ vô tình gặp được Long Như Ý và có được chuỗi tràng hạt. Vì tìm phép thuật bảo vệ Hoa Quả Sơn, chúng không quản đường sá xa xôi đến Thiên Trụ, gặp lại Long Như Ý. Lục Nhĩ bị xà yêu dẫn dụ, giết chết Lão Hầu khiến huynh đệ trở mặt. Tiểu Long Nữ không tuân theo thiên quy bị thiên đình trừng phạt hoá thành Định Hải Thần Châm. Hầu Cát được Bồ Tát cảm hoá, bảo vệ Đường Tăng đi Tây Thiên thỉnh kinh.</p>', 'Full', 1, 'single', 'completed', 21, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Au-Yeung","avatar":""},{"name":"Jin Yongsan","avatar":""},{"name":"Kang Yihan","avatar":""},{"name":"Han Yi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324388);
