INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-phuc-ma', 'Thục Sơn Phục Ma', 'The Legend of Zu', 'https://phimimg.com/upload/vod/20230929-1/36ea8dfafa7d9575a1b75b73c2209253.jpg', 'https://phimimg.com/upload/vod/20230929-1/5744ab42f385dbfe562131742797b741.jpg', '<p><span style="">Bai Ze Lingfeng Hai anh em này lớn lên ở giáo phái Kunlun từ nhỏ.&nbsp;</span><span style="">Sau đó, hai người tiến vào khu vực bí mật và phát hiện ra hai món đồ có giá trị.&nbsp;</span><span style="">Đó là Gương Thiên Hào và công nghệ cao cấp nhất.&nbsp;</span><span style="">Nhưng chẳng bao lâu sau, chuyện luyện võ của Lăng Phong bị bại lộ.&nbsp;</span><span style="">Do đó, hai anh em đã bị trục xuất khỏi giáo phái Kunlun.&nbsp;</span><span style="">Mà hai người này đến thế tục huyện Bạch Mã, ở thế tục, hai người này gặp được một cô gái trẻ mà họ yêu thương.&nbsp;</span><span style="">Tên của họ là Yu Yua và Yun Meng.&nbsp;</span><span style="">Nhưng sau đó, Yun Meng đã bị Kun Lun Sect giết chết.&nbsp;</span><span style="">Lưu Phong sau đó đã trở thành một con quỷ.&nbsp;</span><span style="">Để trả thù Kunlun, Lingfeng đã bị giết không thương tiếc và đoạn tuyệt với Bai Ze.&nbsp;</span><span style="">Với sự giúp đỡ của Yu Yua&nbsp;</span><span style="">Bai Ze tỉnh táo lại, cuối cùng, trên đỉnh Kunlun, Bai Ze đã đánh bại Ling Feng bằng Hao Tian và thành lập giáo phái Chu Shan.</span></p>', 'Full', 1, 'single', 'ongoing', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Chen","avatar":""},{"name":"Wang Mingduo","avatar":""},{"name":"Zhao Yilin","avatar":""},{"name":"Zhang Zixuan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324388);
