INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-du', 'Đông Du', 'Journey To The East', 'https://phimimg.com/upload/vod/20230928-1/e02eee5c77a853695f2152d191c70ba6.jpg', 'https://phimimg.com/upload/vod/20230928-1/9d16e586d04b0377b1dfe58d07420841.jpg', '<p>Bộ phim kể về câu chuyện “Hàn Diểu”, kiếp sau của Hàn Tương Tử, 
một trong Bát Tiên, đông du rèn luyện trong một thế giới không có nước, 
đã giúp Đông Hải Long Nữ “cá vượt Long môn”. Mượn câu chuyện tình yêu 
giữa Hàn Tương Tử và Long Nữ trong thần thoại Bát Tiên truyền thống, mở 
ra một thế giới Bát Tiên hoàn toàn mới.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yuan","avatar":""},{"name":"Li Qinyao","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Chen Bing Qiang","avatar":""},{"name":"Wang Zhipeng","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324388);
