INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-bat-hao', 'Biệt Đội Bất Hảo', 'The Bad Guys: Reign of Chaos', 'https://phimimg.com/upload/vod/20230926-1/1a9213e9a2a3c84258e4ecb1451cf9cc.jpg', 'https://phimimg.com/upload/vod/20230926-1/6b99735dfb0fd996bb81c55b872e2a01.jpg', '<p>Đội Điều Tra Đặc Biệt do đội trưởng Oh Gu-tak thành lập, với tiêu chí không cần quan tâm phương pháp tốt xấu, chỉ cần “bắt sống bọn tội phạm”. Thành viên gạo cội nhất của đội là tay đấm Park Woong-chul, người đã vào tù cũng là đại ca được tôn kính. Hai thành viên mới được chiêu mộ thêm là mỹ nữ chân dài bốc lửa - thiên tài lừa đảo Kwak No-soon và tay cảnh sát lì lợm đang lĩnh án Ko Yoo-sung.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Kim Sang-joong","avatar":""},{"name":"Kim A-joong","avatar":""},{"name":"Jang Ki-yong","avatar":""},{"name":"Park Hyo-joon","avatar":""},{"name":"Kim In-woo","avatar":""},{"name":"Lee Jae-yoon","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Park Hyoung-soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324388);
