INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-cua-me', 'Hạnh Phúc Của Mẹ', 'The Happiness of a Mother', 'https://phimimg.com/upload/vod/20230919-1/5257bc3ec52209d19e0736affa220e44.jpg', 'https://phimimg.com/upload/vod/20230919-1/9349e6157fede471d660a5260710a363.jpg', '<p><span style="font-family: ">Hạnh Phúc Của Mẹ kể về “cuộc chiến” giúp con trở thành một đứa trẻ bình thường của mẹ Tuệ - một người mẹ đơn thân và chân quê với cậu con trai mắc bệnh tự kỷ bẩm sinh. Như rất nhiều người mẹ ít kiến thức nhưng giàu tình yêu thương ở những vùng đất nghèo khó, mẹ Tuệ hoàn toàn không có những kỹ năng sư phạm để dạy một đứa trẻ tự kỷ. Nhưng với bản năng của người mẹ dành cho đứa con mình dứt ruột sinh ra, mẹ Tuệ chỉ có một phương pháp duy nhất là dạy con bằng cách bảo bọc mọi thứ, kể cả việc từ chối lời cầu hôn của một người đàn ông rất chân thành.</span></p>', 'Full', 1, 'single', 'completed', 25, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Huy Khang","avatar":""},{"name":"Cát Phượng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324388);
