INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-song-2019', 'Chỗ Sống (2019)', 'Vivarium (2019)', 'https://phimimg.com/upload/vod/20230917-1/d2f4a0fc02502a4300060d90e5f21945.jpg', 'https://phimimg.com/upload/vod/20230917-1/c6a79a9f39790de44b59b4d18a280597.jpg', '<p><span style="font-family: ">Đôi tình nhân trẻ đang muốn tìm kiếm một ngôi nhà mới, họ tìm đến một cty bất động sản và gặp một nhân viên có dáng vẻ cùng cư xử khá kỳ quặc. Anh ta dẫn hai người đến thăm quan căn nhà rồi sau đó đột nhiên biến mất. Hai người nhận thấy nhiều sự kỳ lạ ở đây và quyết định ra về, nhưng đi mãi họ cũng vẫn quay lại trước cửa căn nhà số 9 mà họ vừa thăm quan.</span></p>', 'Full', 1, 'single', 'completed', 28, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Imogen Poots","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Jonathan Aris","avatar":""},{"name":"Senan Jennings","avatar":""},{"name":"Éanna Hardwicke","avatar":""},{"name":"Molly McCann","avatar":""},{"name":"Danielle Ryan","avatar":""},{"name":"Olga Wehrly","avatar":""},{"name":"Jack Hudson","avatar":""},{"name":"Mark Quigley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324388);
