INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-ba-2019', 'Vợ Ba (2019)', 'Vợ Ba (2019)', 'https://phimimg.com/upload/vod/20230917-1/f1f7163725d52db8dd5d85db206a66b6.jpg', 'https://phimimg.com/upload/vod/20230917-1/be5ca3654d0a3a3e5e1a498d4236e22e.jpg', '<p><span style="font-family: ">Người vợ ba lấy bối cảnh vùng thôn quê Việt Nam cuối thế kỷ 19. Nội dung phim xoay quanh câu chuyện về cô gái tên Mây (Nguyễn Phương Trà My thủ vai) được gả làm vợ ba cho một gia đình giàu có. Tưởng như bắt đầu một cuộc sống sung túc, đầy đủ, cô gái trẻ không ngờ mình bị lôi vào một cuộc tranh đấu ngầm trong gia đình mới với vợ cả và vợ hai để có được vị trí quan trọng ở nhà chồng. Dựa trên những câu chuyện có thật về thân phận người phụ nữ Việt Nam trong xã hội xưa, phim cũng đề cập đến các vấn đề của xã hội lúc đó như hôn nhân sắp đặt, tục đa thê, trọng nam khinh nữ.</span></p>', 'Full', 1, 'single', 'completed', 25, 2019, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Nguyen Phuong Tra My","avatar":""},{"name":"Tran Nu Yen Khe","avatar":""},{"name":"Le Vu Long","avatar":""},{"name":"Nhu Quynh","avatar":""},{"name":"Maya","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Mai Cat Vi","avatar":""},{"name":"Nguyen Thanh Tam","avatar":""},{"name":"Trung Anh","avatar":""},{"name":"Khanh An Tang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324388);
