INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thua-me-con-di', 'Thưa Mẹ Con Đi', 'Goodbye Mother', 'https://phimimg.com/upload/vod/20230917-1/7e0fad4ecf4e00f2ac81ce6369ce1a40.jpg', 'https://phimimg.com/upload/vod/20230917-1/3e1d40fa4da4cfbcce12cac8d3dfd098.jpg', '<p><span style="font-family: ">Cậu con trai sống ở nước ngoài quay về nhà cùng người bạn đồng giới để thú nhận về mối quan hệ của họ. Thế nhưng anh lại bị choáng ngợp bởi bổn phận làm con.</span></p>', 'Full', 1, 'single', 'completed', 29, 2019, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Lãnh Thanh","avatar":""},{"name":"Võ Điền Gia Huy","avatar":""},{"name":"Hồng Đào","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Lê Thiện","avatar":""},{"name":"Thanh Tú","avatar":""},{"name":"Hữu Nghĩa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324388);
