INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau-2-2018', 'Thám Tử Phố Tàu 2', 'Detective Chinatown 2', 'https://phimimg.com/upload/vod/20260628-1/2534345a1e60ee63d3c7ad2b8724d2bf.jpg', 'https://phimimg.com/upload/vod/20260628-1/8685d369bfe51480c39565bb6185194d.jpg', '<p>Với Detective Chinatown II (Thám Tử Phố Tàu 2), Tần Phong lên đường sang Mỹ để tham dự đám cưới của ông cậu Đường Nhân. Thế nhưng sau đó, cậu mới phát hiện ra rằng, đây chỉ là chiêu thức lừa đảo của Đường Nhân để dụ mình qua tham dự một cuộc thi thám tử vì khoản tiền thưởng kếch xù. Nội dung mà cuộc thi đưa ra, đó là các ứng viên phải tìm kiếm bằng được cháu trai của ông trùm phố Tàu (Chinatown). Từ đây, nhiều vụ án liên tiếp xảy ra, khiến Tần Phong không khỏi nghi ngờ. Cậu cùng ông chú Đường Nhân dần khám phá ra được những bí mật kinh thiên động địa.</p>', 'Full', 1, 'single', 'completed', 46, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Bảo Cường","avatar":""},{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Tiêu Ương","avatar":""},{"name":"Lưu Thừa Vũ","avatar":""},{"name":"Thượng Ngữ Hiền","avatar":""},{"name":"Vương Tấn","avatar":""},{"name":"Thê Phu Mộc Thông","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Tăng Giang","avatar":""},{"name":"Bạch Linh","avatar":""},{"name":"Vương Tấn","avatar":""},{"name":"Michael Pitt","avatar":""},{"name":"Natasha Liu Bordizzo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tang ren jie tang an 2","Detective Chinatown 2","Detective Chinatown Vol 2","唐人街探案2"]', 1784690324388);
