INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-biet-giam-xac-song', 'Khu Biệt Giam Xác Sống', 'Zombiepura', 'https://phimimg.com/upload/vod/20260622-1/e136f67c77bc3729cfc83e992e6c8f8b.jpg', 'https://phimimg.com/upload/vod/20260622-1/57b1ed2da8e68d2e15cc25d959acb589.jpg', '<p>Khi một loại virus bí ẩn bất ngờ bùng phát tại một trại lính biệt lập, một anh lính dự bị lười biếng và viên chỉ huy nghiêm khắc, cứng rắn của mình buộc phải gạt bỏ mọi hiềm khích để hợp tác sinh tồn, đồng thời học lại bài học về ý nghĩa thực sự của một người lính chân chính.</p>', 'Full', 1, 'single', 'completed', 49, 2018, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Benjamin Heng","avatar":""},{"name":"Alaric Tay","avatar":""},{"name":"Richard Low","avatar":""},{"name":"Joey Pink Lai","avatar":""},{"name":"Rayve Tay","avatar":""},{"name":"Haresh Tilani","avatar":""},{"name":"Crispian Chan","avatar":""},{"name":"Chen Xiuhuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["좀비 워","尸杀军营","ゾンビプーラ","丧尸战士","Zombiepura"]', 1784690324388);
