INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lee-chong-wei-su-troi-day-cua-huyen-thoai', 'Lee Chong Wei: Sự Trỗi Dậy Của Huyền Thoại', 'Lee Chong Wei: Rise Of The Legend', 'https://phimimg.com/upload/vod/20260621-1/08b431c5ad890add84cadad11f4a87e2.jpg', 'https://phimimg.com/upload/vod/20260621-1/6f4eece888afd8939f943ce5104663f1.jpg', '<p><em>Lee Chong Wei</em> là một bộ phim điện ảnh tiểu sử của Malaysia ra mắt năm 2018 do Teng Bee đạo diễn. Bộ phim kể về câu chuyện truyền cảm hứng mạnh mẽ của biểu tượng thể thao quốc gia Lee Chong Wei, người đã vươn lên từ cảnh nghèo khó tột cùng để trở thành tay vợt cầu lông số một thế giới. Tác phẩm được xây dựng dựa trên cuốn tự truyện ra mắt năm 2012 của chính anh mang tên <em>Dare to Be a Champion</em> (Dám Trở Thành Nhà Vô Địch).</p>', 'Full', 1, 'single', 'completed', 55, 2018, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Jake Eng","avatar":""},{"name":"Tosh Chan","avatar":""},{"name":"Mark Lee","avatar":""},{"name":"Yeo Yann Yann","avatar":""},{"name":"Ashley Hua","avatar":""},{"name":"Rosyam Nor","avatar":""},{"name":"Uriah See","avatar":""},{"name":"Sherie Merlis","avatar":""},{"name":"Bernard Hiew","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["李宗伟：败者为王","Lee Chong Wei Rise of The Legend (2018)","李宗偉：敗者為王","Lee Chong Wei: Rise of the Legend"]', 1784690324388);
