INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ghep', 'Mảnh Ghép', 'Mosaic', 'https://phimimg.com/upload/vod/20260620-1/010286d45b329dd0bf5e1ed5d54ebe8f.jpg', 'https://phimimg.com/upload/vod/20260620-1/2c6663f4b6f178c9989440ec79c77157.jpg', '<p>Bộ phim đi sâu khám phá những góc khuất tâm lý ẩn sau tình yêu và tội ác giết người tại một thị trấn nghỉ dưỡng nhỏ vùng núi mờ sương. Câu chuyện theo chân Olivia Lake, một tác giả kiêm họa sĩ minh họa sách thiếu nhi vô cùng nổi tiếng, người mà sự nghiệp văn chương lẫy lừng đã biến cô thành một biểu tượng, một ngôi sao địa phương được săn đón trong cộng đồng dân cư khăng khít nơi đây.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 30, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Ferrin","avatar":""},{"name":"Frederick Weller","avatar":""},{"name":"Paul Reubens","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Jeremy Bobb","avatar":""},{"name":"Maya Kazan","avatar":""},{"name":"Beau Bridges","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Michael Cerveris","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Zandy Hartig","avatar":""},{"name":"Jacob Vargas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["马赛克","מוזאיק","Mosaic"]', 1784690324388);
