INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-anh-hung', 'Chú Chó Anh Hùng', 'Sgt. Stubby: An American Hero', 'https://phimimg.com/upload/vod/20260620-1/4e95ec94de00a1e3b2405df5bef56928.jpg', 'https://phimimg.com/upload/vod/20260620-1/ab9583aaefd36e872e2af6f8f0b3a159.jpg', '<p>Câu chuyện có thật về chú chó được trao tặng nhiều huân chương nhất trong lịch sử quân đội Mỹ — Trung sĩ Stubby — và mối gắn kết bền chặt, kiên cường mà chú đã xây dựng cùng những người đồng đội của mình nơi chiến hào khốc liệt của Thế chiến thứ nhất.</p>', 'Full', 1, 'hoathinh', 'completed', 52, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jim Pharr","avatar":""},{"name":"Jordan Beck","avatar":""},{"name":"Jason Ezzell","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sgt. Stubby: An Unlikely Hero","Sergent Stubby: En usandsynlig helt","Sgt. Stubby: An American Hero"]', 1784690324388);
