INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phieu-luu-cua-jim-cuc-quan-lukas-va-dau-may-hoi-nuoc', 'Chuyến Phiêu Lưu Của Jim Cúc Quần Lukas Và Đầu Máy Hơi Nước', 'Jim Button and Luke the Engine Driver', 'https://phimimg.com/upload/vod/20260617-1/b906d3fda53baa3bbcd0e8127141a1e7.jpg', 'https://phimimg.com/upload/vod/20260617-1/c9409617b22753aa6bfaa6dce62b643f.jpg', '<p>Bộ phim Jim Button and Luke the Engine Driver kể về hành trình khám phá thế giới của cậu bé Jim và người bạn tốt nhất của cậu - người lái đầu máy xe lửa Luke sau khi rời khỏi hòn đảo Lummerland. Cuộc phiêu lưu này đưa hai người đến với biển cả, sa mạc, Mandala, thành phố rồng Frau Mahlzahn giải cứu công chúa và tìm về cội nguồn của Jim.</p>', 'Full', 1, 'single', 'completed', 40, 2018, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Henning Baum","avatar":""},{"name":"Solomon Gordon","avatar":""},{"name":"Annette Frier","avatar":""},{"name":"Uwe Ochsenknecht","avatar":""},{"name":"Christoph Maria Herbst","avatar":""},{"name":"Milan Peschel","avatar":""},{"name":"Rick Kavanian","avatar":""},{"name":"Eden Gough","avatar":""},{"name":"Leighanne Esperanzate","avatar":""},{"name":"Kao Chenmin","avatar":""},{"name":"Ozzie Yue","avatar":""},{"name":"Volker Michalowski","avatar":""},{"name":"Alex Liang","avatar":""},{"name":"Hon Ping Tang","avatar":""},{"name":"Fang Yu","avatar":""},{"name":"Darryl Quon","avatar":""},{"name":"Tadashi En","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["ג''ים בוטן ונהג הקטר","Jim Knopf","Jim Botão e Lucas, o Maquinista","Jim Knopf & Lukas der Lokomotivführer","Jim Bouton et la cité des dragons","Kuba Guzik na tajemniczym lądzie","Jim Knopf & Lukas, der Lokomotivführer","Jim Knopf und Lukas der Lokomotivführer"]', 1784690324388);
