INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chu-cua-toi', 'Ông Chú Của Tôi', 'My Mister', 'https://phimimg.com/upload/vod/20260614-1/df2e1a38af52e90fa5a34cc5436af03f.jpg', 'https://phimimg.com/upload/vod/20260614-1/2706e0a2c7f79a14e7e4e28fae3eeb36.jpg', '<p>Dong Hoon, 1 kiến trúc sư tài năng, nhiệt huyết đang gặp phải những vấn đề trong công việc và cuộc sống. Ji Ah, 1 cô gái tuổi đôi mươi, nhưng điều người ta thấy ở cô không phải à sức sống mà là sự chịu đựng và nhẫn nhịn. Chính sự bất hạnh và kém máy mắn cũng như đồng cảm đã đưa Dong Hoon và Ji Ah đến gần với nhau</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 26, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-kyun","avatar":""},{"name":"IU","avatar":""},{"name":"Goh Doo-shim","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Song Sae-byuk","avatar":""},{"name":"Lee Ji-ah","avatar":""},{"name":"Jeong Young-ju","avatar":""},{"name":"Son Sook","avatar":""},{"name":"Jang Ki-yong","avatar":""},{"name":"Ahn Seung-gyun","avatar":""},{"name":"Kim Young-min","avatar":""},{"name":"Shin Gu","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Ryu Abel","avatar":""},{"name":"Kwon Na-ra","avatar":""},{"name":"Park Hae-joon","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Seo Sang-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的大叔","My Mister [My Ahjussi]","My Ahjussi","マイ・ディア・ミスター〜私のおじさん〜","マイ・ディア・ミスター 私のおじさん","Мой мистер","My Ajusshi","My Mister","나의 아저씨"]', 1784690324388);
