INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-chu-cua-toi', 'Ông Chú Của Tôi', 'My Mister', 'ông chú của tôi my mister lee sun-kyun iu goh doo-shim park ho-san song sae-byuk lee ji-ah jeong young-ju son sook jang ki-yong ahn seung-gyun kim young-min shin gu jeon kuk-hwan jung hae-kyun seo hyun-woo ryu abel kwon na-ra park hae-joon oh na-ra seo sang-won 我的大叔 my mister [my ahjussi] my ahjussi マイ・ディア・ミスター〜私のおじさん〜 マイ・ディア・ミスター 私のおじさん мой мистер my ajusshi my mister 나의 아저씨', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-duong-huyet-kiem', 'Thái Dương Huyết Kiếm', 'Return Of The Guard', 'https://phimimg.com/upload/vod/20260611-1/77e477ac7dbbb2d35f2dc2fab6dae765.jpg', 'https://phimimg.com/upload/vod/20260611-1/10c4bc5bdb8baa817fe0cb1562d45e00.jpg', '<p>Sau khi Tân hoàng đế họ Chu lên ngôi, cả gia tộc họ Tiền bất ngờ bị thảm sát diệt môn. Ban đầu, mọi bằng chứng điều tra đều chĩa mũi dùi vào Hán Vương – kẻ vốn đang nung nấu dã tâm mưu phản đoạt vị. Tuy nhiên, bước ngoặt của vụ án xảy ra khi người huynh đệ của Cẩm Y Vệ Tần Phong bàng hoàng phát hiện ra một bí mật kinh thiên động địa: kẻ thủ ác thực sự đứng sau giật dây toàn bộ bi kịch này không ai khác, mà lại chính là vị Tân vương mà họ đang phục mệnh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 23, 2018, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Thanh Bân","avatar":""},{"name":"Vương Tử Phi","avatar":""},{"name":"Địch Uy","avatar":""},{"name":"Thái Lạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324388);
