INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-day-co-nang', 'Ở Đây Có Nắng', 'Ở Đây Có Nắng', 'https://phimimg.com/upload/vod/20260605-1/6189ae40a1c93d8e08bdd6ef633a5a58.jpg', 'https://phimimg.com/upload/vod/20260605-1/ef681897e5927f43c62e0b947c83740a.jpg', '<p>Ở Đây Có Nắng xoay quanh nhân vật Tùng Nhân – một MC, đạo diễn chương trình truyền hình nổi tiếng đang sống yên vui với người yêu. Bỗng một ngày Tùng Nhân bàng hoàng phát hiện mình có đứa con trai “trên trời rơi xuống” - kết quả mối tình nhiều năm trước với người yêu cũ. Thừa nhận đứa trẻ đồng nghĩa với việc sẽ vướng vào tai tiếng, sự nghiệp có thể tiêu tan, nhưng nhìn thấy con sống bơ vơ, nhớ lại thân cảnh mồ côi của chính mình, Tùng Nhân quyết định nuôi con. Tình phụ tử vừa ấm áp thì éo le bất ngờ xảy đến.</p>', 'Full', 1, 'single', 'completed', 35, 2018, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Quý Bình","avatar":""},{"name":"Gia Bảo","avatar":""},{"name":"Quỳnh Chi","avatar":""},{"name":"Trương Thanh Long","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Here Comes The Sun","Ở Đây Có Nắng"]', 1784690324388);
