INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-gio-het-e', 'Bao Giờ Hết Ế', 'Bao Giờ Hết Ế', 'https://phimimg.com/upload/vod/20260604-1/781c0eab30c7c214a85762e632fd58f6.jpg', 'https://phimimg.com/upload/vod/20260604-1/9f0d3f26961fb7c82211c22c007cd326.jpg', '<p>Phim xoay quanh nữ doanh nhân thành đạt Thiên Kim. Ở tuổi 30, cô chẳng thể tìm nổi một tấm chồng bởi lời nguyền “sát phu” của gia tộc. Không những thế, cô còn bị tay người yêu Johnny lừa dối và trộm hết sạch tài sản sau một đêm mặn nồng.</p>', 'Full', 1, 'single', 'completed', 44, 2018, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Anh Tú","avatar":""},{"name":"Thúy Vân","avatar":""},{"name":"Đàm Phương Linh","avatar":""},{"name":"Đình Quân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Bao Giờ Hết Ế"]', 1784690324388);
