INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chai-va-anh-mieu', 'Anh Chai Và Anh Miêu', 'Shiba San And Meow Chan', 'https://phimimg.com/upload/vod/20260518-1/9895e55f53892e7dba7c2a7c6fd6d80b.jpg', 'https://phimimg.com/upload/vod/20260518-1/42d89a425662d096eabe7e4d8ca989f9.jpg', '<p>Shiba San và Meow Chan, một chương trình thiếu nhi ăn khách, trong đó hai anh em lần lượt vào vai chó và mèo, đã gây sốt trong giới trẻ và mang lại danh tiếng cho cả hai. Tuy rạng rỡ trên sân khấu, nhưng cả hai đều mang trong mình những tâm sự riêng. Shiba San thầm yêu một người đàn ông đã có vợ, còn Meow Chan thì nhớ mẹ tái giá và hoang mang khi bà bỏ rơi mình. Một hành trình sau đó sẽ dẫn dắt hai chú mèo hoang đối mặt với sự trống rỗng bên trong.</p>', 'Full', 1, 'single', 'completed', 22, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉冠廷","avatar":""},{"name":"Chih-Hsuan Wu","avatar":""},{"name":"Wei-Yi Lin","avatar":""},{"name":"邱宜禾","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chai Ge Yu Miao Di","柴哥與喵弟"]', 1784690324388);
