INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-mo-rong-phan-3', 'Cuộc Mở Rộng (Phần 3)', 'The Expanse (Season 3)', 'cuộc mở rộng (phần 3) the expanse (season 3) steven strait dominique tipper wes chatham shohreh aghdashloo frankie adams cara gee nadine nicole keon alexander jasai chase-owens експанзията 浩瀚天穹 太空无垠 无垠的太空 苍穹浩瀚 expanze διαστημική συνωμοσία הרקיע پهنه экспансия пространство простір експансія the expanse', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-cuoi-cung', 'Trận Chiến Cuối Cùng', 'The Last Warrior / The Scythian', 'https://phimimg.com/upload/vod/20260511-1/102057d4cbcd1e934b81f0efd70d2755.jpg', 'https://phimimg.com/upload/vod/20260511-1/c280c8952092760b732e196927e8111b.jpg', '<p>Người Scythia, từng là những chiến binh kiêu hãnh, đã biến mất. Một số ít hậu duệ của họ đã trở thành những sát thủ đánh thuê tàn nhẫn, “Những con sói của Ares.” Lutobor, là một người lính với một nhiệm vụ khó khăn trong tầm tay. Anh ta tham gia vào các cuộc xung đột giữa các giai thoại và bắt đầu một cuộc hành trình nguy hiểm để cứu gia đình của mình. Người dẫn đường cho anh ta là một người Scythia bị giam giữ tên là Marten. Lutobor và Marten là kẻ thù của nhau. Họ cầu nguyện với các vị thần khác nhau nhưng phải cùng nhau bắt đầu cuộc hành trình này. Họ can đảm trên thảo nguyên hoang dã, tiến về nơi trú ẩn cuối cùng của người Scythia, đến nơi dường như là cái chết không thể tránh khỏi của họ.</p>', 'Full', 1, 'single', 'completed', 26, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Nga', 0, '[{"name":"Алексей Фаддеев","avatar":""},{"name":"Виталий Кравченко","avatar":""},{"name":"Александр Кузнецов","avatar":""},{"name":"Василиса Измайлова","avatar":""},{"name":"Александр Пацевич","avatar":""},{"name":"Юрий Цурило","avatar":""},{"name":"Andrey Permyakov","avatar":""},{"name":"Виктор Соловьёв","avatar":""},{"name":"Анатолий Лакуцин","avatar":""},{"name":"Вячеслав Юровских","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Scythian","더 시티언","El último guerrero","Скиф"]', 1784690324388);
