INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-thanh-pho-vang', 'Truyền Thuyết Thành Phố Vàng', 'K.G.F: Chapter 1', 'https://phimimg.com/upload/vod/20260508-1/8b9d057670925256e1ef53aef9d49ed9.jpg', 'https://phimimg.com/upload/vod/20260508-1/b957644f2bba87120d315977de82eab1.jpg', '<p>Phim lấy bối cảnh vào những năm 1960, nội dung phim xoay quanh cuộc đời người đàn ông Rocky. Sinh ra trong nghèo khó và hiểu hết sự đau khổ, thiếu thốn của người nghèo, Rocky quyết định đến Bombay để tìm kiếm quyền lực và tiền bạc. Sau khi đầu quân cho một băng đảng mafia, anh được cử đi giết Garuda. Cuối cùng, Rocky quyết định quay trở về ngôi làng của mình, cùng người dân nơi đây thoát khỏi cảnh nô lệ, nghèo đói.</p>', 'Full', 1, 'single', 'completed', 22, 2018, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Yash","avatar":""},{"name":"Srinidhi Shetty","avatar":""},{"name":"Ramachandra Raju","avatar":""},{"name":"Archana Jois","avatar":""},{"name":"Anant Nag","avatar":""},{"name":"Vasishta N. Simha","avatar":""},{"name":"Achyuth Kumar","avatar":""},{"name":"Ayyappa P. Sharma","avatar":""},{"name":"Malavika Avinash","avatar":""},{"name":"B. S. Avinash","avatar":""},{"name":"Vinay Bidappa","avatar":""},{"name":"Ramesh Indira","avatar":""},{"name":"Lakki Lakshman","avatar":""},{"name":"Tarak Ponnappa","avatar":""},{"name":"Dinesh Mangaluru","avatar":""},{"name":"Harish Rai","avatar":""},{"name":"Govinde Gow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["K.G.F","Kolar Gold Fields","KGF-1","เคจีเอฟ วีรบุรุษเหมืองทองโกลาร์","科拉爾金礦","ಕೆಜಿಎಫ್ ಅಧ್ಯಾಯ ೧"]', 1784690324388);
