INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-cao-ve-sarah-va-saleem', 'Báo Cáo Về Sarah Và Saleem', 'The Reports On Sarah And Saleem', 'https://phimimg.com/upload/vod/20260509-1/fe650c7293d8238e3324672f3be78dd3.jpg', 'https://phimimg.com/upload/vod/20260509-1/ecbcb0c21ff2f2b2eba7c0775837644d.jpg', '<p>Mối quan hệ vụng trộm giữa một người đàn ông Palestine đã kết hôn và một người phụ nữ Israel đã kết hôn ở Jerusalem trở nên nguy hiểm về mặt chính trị khi họ bị bắt gặp ở sai địa điểm vào sai thời điểm, khiến họ phải đối mặt với nhiều hơn cả việc hôn nhân tan vỡ.</p>', 'Full', 1, 'single', 'completed', 31, 2018, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Adeeb Safadi","avatar":""},{"name":"Sivane Kretchner","avatar":""},{"name":"Ishai Golan","avatar":""},{"name":"Hanan Hillo","avatar":""},{"name":"ميساء عبد الهادي","avatar":""},{"name":"Kamel El Basha","avatar":""},{"name":"Jan Kühne","avatar":""},{"name":"Rebecca Esmeralda Telhami","avatar":""},{"name":"Raya Zoabi","avatar":""},{"name":"Mohammad Eid","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["사라와 살림에 관한 보고서","Der Fall Sarah & Saleem","Sarah & Saleem","التقارير حول سارة وسليم"]', 1784690324388);
