INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-gio-20-moi-tuan-mot-lan', '7 Giờ 20 Mỗi Tuần Một Lần', '7:20 Once A Week / En tu piel', 'https://phimimg.com/upload/vod/20260508-1/3965d6f5bcfbcce8eaabcfc28120cebb.jpg', 'https://phimimg.com/upload/vod/20260508-1/50887643030da807c5a74085fef5443e.jpg', '<p>Phim xoay quanh Julia và Diego, hai người xa lạ gặp nhau tình cờ trên cùng chuyến xe buýt lúc 7:20 mỗi sáng, một lần mỗi tuần. Từ những cuộc trò chuyện ngắn ngủi, họ dần nảy sinh tình cảm, nhưng mối quan hệ mong manh ấy bị thử thách bởi cuộc sống riêng, khoảng cách và những lựa chọn cá nhân, đặt ra câu hỏi liệu tình yêu có thể tồn tại khi chỉ gặp …</p>', 'Full', 1, 'single', 'completed', 25, 2018, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Eva Arias","avatar":""},{"name":"Josue Guerrero","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["7.20 Once a Week","En tu piel"]', 1784690324388);
