INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-vuong-gia-tro-ve', 'Hoàng Phi Hồng: Vương Giả Trở Về', 'Wong Fei-Hung: Return Of The King', 'https://phimimg.com/upload/vod/20260509-1/0890ee87d5a05357b613915b74252b4a.jpg', 'https://phimimg.com/upload/vod/20260509-1/cfe43cb4060c0cdc933b47c4aa3be4e1.jpg', '<p>Quỷ Cước Thất trên võ đài tựa như mãnh thú, nhất định muốn dồn Lương Khoan vào chỗ chết. Hoàng Phi Hồng xuất hiện kịp lúc cứu Lương Khoan, chân tướng từng bước bị vạch trần, mục đích của Brown rõ ràng là chế tạo &quot;cỗ máy chiến tranh&quot;. Cũng chính lúc này Hoàng Phi Hồng dần dần nhận ra, chủ mưu đứng sau bức màn lại là một người khác.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Thần","avatar":""},{"name":"Lương Tuấn Nhất","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["황비홍 - 왕의 귀환","Wong Fei-Hung : Return of The King","Wang Zhe Gui Lai Huang Fei Hong","Return of the King Huang Feihong","王者归来黄飞鸿"]', 1784690324388);
