INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-yeu-tinh-truyen-thuyet-arcadia-phan-3', 'Thợ Săn Yêu Tinh: Truyền Thuyết Arcadia (Phần 3)', 'Trollhunters: Tales Of Arcadia (Season 3)', 'https://phimimg.com/upload/vod/20260429-1/252ef7dbff76095307bcd3d776559290.jpg', 'https://phimimg.com/upload/vod/20260429-1/d34bade6c0b1f1b9d30eb2903adef6f4.jpg', '<p>Khi tìm thấy viên ngọc hộ mệnh bí ẩn, một cậu học sinh bình thường tiếp nhận sứ mệnh đặc biệt và lên đường bảo vệ hai thế giới. Bộ phim của đạo diễn Guillermo del Toro.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 23, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lexi Medrano","avatar":""},{"name":"Charlie Saxton","avatar":""},{"name":"Amy Landecker","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Yara Shahidi","avatar":""},{"name":"Jonathan Hyde","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Cole Sand","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Emile Hirsch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lovci trolů: Příběhy z Arkádie","Chasseurs de Trolls","Κυνηγοί Tρολ: Το