INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-thuc-giac', 'Quỷ Dữ Thức Giấc', 'Devilman Crybaby', 'https://phimimg.com/upload/vod/20260426-1/69f01d4cb2b602baba2f5fe3e676322d.jpg', 'https://phimimg.com/upload/vod/20260426-1/2ee826139fd4527129caefdb27d700ac.jpg', '<p>Akira Fudo biết được một tin động trời từ người bạn thân nhất của mình, Ryo Asuka, rằng loài quỷ dữ đang trỗi dậy để chiếm lại thế giới từ tay loài người. Nhận thấy nhân loại hoàn toàn vô vọng trước mối đe dọa này, Ryo đã đề nghị Akira hợp nhất với một con quỷ. Sau quá trình đó, Akira trở thành Devilman — một sinh vật mang sức mạnh khủng khiếp của ác quỷ nhưng vẫn giữ được trái tim nhân hậu của con người.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 15, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koki Uchiyama","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"KEN THE 390","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Masato Obara","avatar":""},{"name":"Sayaka Kobayashi","avatar":""},{"name":"Eri Inagawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["哭泣之子(恶魔人)","デビルマン","デビルマン・クライベイビー","DEVILMAN crybaby"]', 1784690324388);
