INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-noi-tru-phan-2', 'Bác Sĩ Nội Trú (Phần 2)', 'The Resident (Season 2)', 'https://phimimg.com/upload/vod/20260414-1/64f7b26a39b880e87ba6c0f7062b16bb.jpg', 'https://phimimg.com/upload/vod/20260414-1/df05303ee06bdb6eeb5ec03833a83532.jpg', '<p>Một bác sĩ nội trú năm cuối tài giỏi nhưng cứng rắn dẫn dắt một bác sĩ trẻ đầy lý tưởng trong ngày làm việc đầu tiên của anh ta. Qua đó, bộ phim vén bức màn bí mật về những gì thực sự xảy ra trong nền y học hiện đại, từ những khoảnh khắc cứu người cao cả cho đến cả những góc khuất đầy khắc nghiệt.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Czuchry","avatar":""},{"name":"Manish Dayal","avatar":""},{"name":"Malcolm-Jamal Warner","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Anuja Joshi","avatar":""},{"name":"Jane Leeves","avatar":""},{"name":"Andrew McCarthy","avatar":""},{"name":"Kaley Ronayne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Residente","驻院医生","傲骨仁医","რეზიდენტი","Резидент","The Resident"]', 1784690324388);
