INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-dieu-cam-ky', 'Phạm Điều Cấm Kỵ', 'Disobedience', 'https://phimimg.com/upload/vod/20260409-1/fe011e016e2b239f70f986c26a611dea.jpg', 'https://phimimg.com/upload/vod/20260409-1/43fc1026b81a1f43962d73c26570e046.jpg', '<p>Thông qua câu chuyện tình yêu bị kìm nén giữa hai người phụ nữ, đạo diễn đã lột tả một xã hội cổ hủ, ngập tràn định kiến, nơi tự do bị bóp nghẹt bởi chính những người hàng ngày rao giảng về tự do.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Rachel Weisz","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Anton Lesser","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"David Fleeshman","avatar":""},{"name":"Steve Furst","avatar":""},{"name":"Trevor Allan Davies","avatar":""},{"name":"Sophia Brown","avatar":""},{"name":"Anthony Dowding","avatar":""},{"name":"Bernice Stegers","avatar":""},{"name":"Clara Francis","avatar":""},{"name":"Lia Cohen","avatar":""},{"name":"Cara Horgan","avatar":""},{"name":"Orlando Brooke","avatar":""},{"name":"Dom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nepovinoveniye","디서비디언스","Desobedencia","ロニートとエスティ かのじょたちのせんたく","Disobedience"]', 1784690324388);
