INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-phan-1', 'Lúc Đó Tôi Đã Chuyển Sinh Thành Slime (Phần 1)', 'That Time I Got Reincarnated As A Slime (Season 1)', 'lúc đó tôi đã chuyển sinh thành slime (phần 1) that time i got reincarnated as a slime (season 1) miho okasaki tomoaki maeno takuya eguchi hochu otsuka asuna tomari chikahiro kobayashi jun fukushima rie tanaka rina hidaka anzu haruno aquella vez que reencarne como un slime 關於我轉生變成史萊姆這檔事 tensei shitara slime datta ken 关于我转生变成史莱姆这档事 that time i got reincarnated as a slime tensura regarding reincarnated to slime aquella vez que me convertí en slime moi, quand je me réincarne en slime تولد دوباره به‌عنوان یک اسلایم وقتی به‌عنوان یک اسلایم تناسخ پیدا کردم آن زمان که به‌عنوان یک اسلایم زندگی دوباره یافتم tensei shitara slime datta ken tensei slime tensura 2 tensei shitara slime datta ken 2 転生したらスライムだった件 転スラ tensei shitara slime datta ken 3rd season tensei shitara slime datta ken: coleus no yume tensei shitara slime datta ken s4 tensei shitara slime datta ken 4th season 전생했더니 슬라임이었던 건에 대하여 전생했더니 슬라임이었던 건에 대하여 3기 關於我轉生變成史萊姆這檔事 柯里烏斯之夢 моє переродження в слиз that time i got reincarnated as a slime 2 that time i got reincarnated as a slime: visions of coleus chuyển sinh thành slime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-du-hanh-phan-3', 'Kẻ Du Hành (Phần 3)', 'Travelers (Season 3)', 'https://phimimg.com/upload/vod/20260404-1/d1b3f4726bc136c5e7223e09beddd1c8.jpg', 'https://phimimg.com/upload/vod/20260404-1/9e7299e5f1c148f2aa1566f80f34a49f.jpg', '<p>Một đặc vụ liên bang dõi theo bốn người bỗng nhiên mang những tính cách hoàn toàn mới, đưa đến một phát hiện đầy sửng sốt về tương lai của nhân loại.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 20, 2018, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Eric McCormack","avatar":""},{"name":"MacKenzie Porter","avatar":""},{"name":"Nesta Cooper","avatar":""},{"name":"Jared Abrahamson","avatar":""},{"name":"Reilly Dolman","avatar":""},{"name":"Patrick Gilmore","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Viajantes no Tempo","时间旅行者","Cestovatelé časem","Ταξιδιώτες στο Χρόνο","Idővonal","시간 여행자","時空旅行者","Travelers"]', 1784690324388);
