INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-dot', 'Thiêu Đốt', 'Burning', 'https://phimimg.com/upload/vod/20260402-1/12bc3cb9beed7e642597c1270d74949f.jpg', 'https://phimimg.com/upload/vod/20260402-1/35e0ad8e33fc83a5aba96a8ba883d568.jpg', '<p>Burning được xây dựng dựa trên truyện ngắn của nhà văn Nhật Bản Haruki Murakami &quot;Barn Burning&quot; và được thay đổi bối cảnh từ Nhật Bản thành Hàn Quốc. Jong Soo (Yoo Ah In) là một người giao thức ăn nhanh. Một ngày nọ, anh tình cờ va phải Haemi (Jeon Jong Seo), một cô gái anh quen hồi nhỏ, và nhanh chóng bị cái tính thất thường nhưng bí ẩn của cô gái ấy mê hoặc.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Ah-in","avatar":""},{"name":"Steven Yeun","avatar":""},{"name":"Jeon Jong-seo","avatar":""},{"name":"Kim Soo-kyung","avatar":""},{"name":"Choe Seung-ho","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Min Bok-gi","avatar":""},{"name":"Ban Hye-ra","avatar":""},{"name":"Cha Mi-kyung","avatar":""},{"name":"Lee Bong-ryeon","avatar":""},{"name":"Jang Won-hyung","avatar":""},{"name":"Jeon Seok-chan","avatar":""},{"name":"Lee Jung-ok","avatar":""},{"name":"Ok Ja-yeon","avatar":""},{"name":"Kim Shin-rock","avatar":""},{"name":"Song Duk-ho","avatar":""},{"name":"Jeong Da-yi","avatar":""},{"name":"Park Seoung-tae","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ardiente","Em Chamas","燃烧烈爱","มือเพลิง","Beoning","버닝"]', 1784690324388);
