INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-chet-choc-phan-1', 'Cơn Mưa Chết Chóc (Phần 1)', 'The Rain (Season 1)', 'https://phimimg.com/upload/vod/20260330-1/c0210925544c51203da0dc8dd951ced9.jpg', 'https://phimimg.com/upload/vod/20260330-1/ce1e5460b82e14429e294b712dc45f24.jpg', '<p>Sáu năm sau khi con virus trong nước mưa xóa sổ gần như toàn bộ dân số Scandinavia, hai chị em đã gia nhập nhóm người còn sống sót để tìm kiếm sự an toàn và cả sự thật.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 32, 2018, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Alba August","avatar":""},{"name":"Lucas Lynggaard Tønnesen","avatar":""},{"name":"Mikkel Boe Følsgaard","avatar":""},{"name":"Lukas Løkken","avatar":""},{"name":"Sonny Lindberg","avatar":""},{"name":"Johannes Bah Kuhnke","avatar":""},{"name":"Natalie Madueño","avatar":""},{"name":"Clara Rosager","avatar":""},{"name":"Evin Ahmad","avatar":""},{"name":"Rex Leonard","avatar":""},{"name":"Sandra Guldberg Kampp","avatar":""},{"name":"Cecilia Loffredo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["毒雨","雨","The Rain","La lluvia","Η Βροχή","Kiša","레인"]', 1784690324388);
