INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-lung-quai-thu', 'Săn Lùng Quái Thú', 'Monstrum', 'https://phimimg.com/upload/vod/20260323-1/b0c812f5aedc77812d4b59e9c0a8c11a.jpg', 'https://phimimg.com/upload/vod/20260323-1/ed4a8c640322182270e208f0c2873d8d.jpg', '<p>Bộ phim lấy bối cảnh vào đời vua thứ 22 của Joseon. Lúc bấy giờ, bệnh dịch hạch đang lan tràn khắp quốc gia này. Không những vậy, lời đồn về sự xuất hiện của một con quái vật gọi là “Monstrum” chuyên săn lùng những người vô tội khiến dân chúng càng thêm sợ hãi. Trước tình cảnh này, hoàng đế đã triệu kiến tướng quân Yun-gyeom để điều tra sự thật. Liệu Monstrum có thực sự tồn tại? Hành trình giải mã những bí ẩn của Yun-gyeom cùng con gái Myung-i, cận vệ Seong-han và phán quan Heo sẽ gặp phải những khó khăn gì? Cùng theo dõi Monstrum để tìm được câu trả lời.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Myung-min","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Lee Hye-ri","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Lee Do-gyeong","avatar":""},{"name":"Lee Kyu-bok","avatar":""},{"name":"Kim Joong-hee","avatar":""},{"name":"Kim Kang-il","avatar":""},{"name":"Cho Won-hee","avatar":""},{"name":"Jang Yong-bok","avatar":""},{"name":"Yun Hui-su","avatar":""},{"name":"Han So-yeong","avatar":""},{"name":"Joo Ye-rim","avatar":""},{"name":"Kang Tae-young","avatar":""},{"name":"Hong Ji-yoon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","