INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-phat-xit-phan-3', 'Thế Giới Của Phát Xít (Phần 3)', 'The Man in the High Castle (Season 3)', 'https://phimimg.com/upload/vod/20260312-1/931499ed37dedaa58b4bbab0cd063ecf.jpg', 'https://phimimg.com/upload/vod/20260312-1/6a9d489f729e7bc81358947bbc09576a.jpg', '<p>Khám phá điều gì sẽ xảy ra nếu phe Đồng Minh thua Thế chiến II, và Nhật Bản cùng Đức Quốc xã cai trị Hoa Kỳ. Dựa trên tiểu thuyết đoạt giải thưởng của Philip K. Dick.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexa Davalos","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Joel de la Fuente","avatar":""},{"name":"Jason O''Mara","avatar":""},{"name":"Brennan Brown","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Frances Turner","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Oraakkelin kirja","Le Maitre du Haut Chateau","L''uomo nell''alto castello","높은 성의 사나이","Žmogus pilyje","El Hombre Del Castillo","Mannen i høyborgen","Człowiek z Wysokiego Zamku","The Man in the High Castle"]', 1784690324388);
