INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tac-pham-thu-hai', 'Tác Phẩm Thứ Hai', 'The Second', 'https://phimimg.com/upload/vod/20260311-1/edb7f79a4e2f2f9ac2a063e63e832f22.jpg', 'https://phimimg.com/upload/vod/20260311-1/4e2ff670a5ac0d4dbfba19e9498c8b78.jpg', '<p>Sau thành công vang dội của cuốn hồi ký, một nữ nhà văn tưởng như đã chạm đến đỉnh cao danh vọng. Thế nhưng, mọi thứ đảo lộn khi người bạn thân bất ngờ tiết lộ sự thật đằng sau những trang sách. Những bí mật bị phơi bày kéo theo chuỗi hệ lụy về dối trá và phản bội, đẩy cô vào vòng xoáy khủng hoảng. Khi ranh giới giữa sự thật và hư cấu sụp đổ, danh tiếng, tình bạn và cả quá khứ của cô đều bị đặt lên bàn cân.</p>', 'Full', 1, 'single', 'completed', 22, 2018, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Rachael Blake","avatar":""},{"name":"Susie Porter","avatar":""},{"name":"Vince Colosimo","avatar":""},{"name":"Martin Sacks","avatar":""},{"name":"Susan Prior","avatar":""},{"name":"Megan Dale","avatar":""},{"name":"Bridget Webb","avatar":""},{"name":"Will Beasley","avatar":""},{"name":"Lisa Kay","avatar":""},{"name":"Paula Nazarski","avatar":""},{"name":"Cate Feldmann","avatar":""},{"name":"Nancy Evans","avatar":""},{"name":"Mirene Igwabi","avatar":""},{"name":"Bruce Cameron","avatar":""},{"name":"Greta Carew-Johns","avatar":""},{"name":"Jason Virgil","avatar":""},{"name":"Amy Emanuele","avatar":""},{"name":"Susan Bush","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Second"]', 1784690324388);
