INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gianh-lai-cong-ly', 'Giành Lại Công Lý', 'Doppelganger', 'https://phimimg.com/upload/vod/20260221-1/d13bb8b7f99b4ca327450e54e99182d7.jpg', 'https://phimimg.com/upload/vod/20260221-1/034fcf49f5ac3da1c7e7e10f60d6ab57.jpg', '<p>Bộ phim là một câu chuyện đầy kịch tính với những bí mật và tình tiết gây cấn. Lập Uy đã phải đối diện với những khó khăn sau khi thay đổi danh tính, nhưng may mắn anh có được sự giúp đỡ từ Nhuệ Kiệt và có cơ hội thay thế Lý Nhuệ Minh. Cuộc sống mới của Lập Uy trở nên giàu sang và hào phóng, nhưng rồi sự thật về danh tính của anh dần được hé lộ. Gia đình Nhuệ Minh gặp biến cố khi mất tài sản, liệu họ có thể vượt qua khó khăn này không?</p><span style="color: rgb(160, 160, 160); font-family: __Inter_0fc6d3, __Inter_Fallback_0fc6d3, system-ui, arial; font-size: 11.9656px; text-align: justify; text-wrap-mode: wrap; background-color: rgb(37, 37, 37);"></span>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 20, 2018, 'Lồng Tiếng', 'FHD', 'Singapore', 0, '[{"name":"Jasmine Sim","avatar":""},{"name":"Lý Minh Thuận","avatar":""},{"name":"Phạm Văn Phương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["入侵者"]', 1784690324388);
