INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-entebbe', 'Chiến dịch Entebbe (7 Ngày Ở Entebbe)', '7 Days in Entebbe', 'https://phimimg.com/upload/vod/20260126-1/381522b60aaa34652b49d285f362a887.jpg', 'https://phimimg.com/upload/vod/20260126-1/29c706ee365f28491bc26476147d1168.jpg', '<p>Vào tháng 7 năm 1976, chuyến bay Air France từ Tel-Aviv, Israel tới Paris qua Athens bị bắt cóc bởi 4 tên khủng bố và bắt buộc phải hạ cánh ở Entebbe, Uganda. Hành khách là người Do Thái bị tách ra và bắt làm con tin nhằm mục đích buộc Israel giải phóng các thành phần khủng bố của PFLP-EO đang bị giam giữ bởi Mossad. Sau nhiều cuộc tranh luận, chính phủ Israel đã đưa ra quyết định cử một đơn vị đặc nhiệm ưu tú đột kích vào sân bay và giải cứu các con tin.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Rosamund Pike","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Lior Ashkenazi","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Ben Schnetzer","avatar":""},{"name":"Andrea Deck","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Angel Bonanni","avatar":""},{"name":"Juan Pablo Raba","avatar":""},{"name":"Peter Sullivan","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Laurence Bouvard","avatar":""},{"name":"Brontis Jodorowsky","avatar":""},{"name":"Natalie Stone","avatar":""},{"name":"Flynn Allen","avatar":""},{"name":"Zina Zinche","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Entebbe","7 días en Entebbe","Rescate en Entebbe","7 Tage in Entebbe","Otages à Entebbe","Operação Entebbe","航劫168小时","恩德培行动","恩德培七日","エンテベ空港の7日間：2018","航劫168小時","7 Days in Entebbe"]', 1784690324388);
