INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-ky-binh-qua-cam', '12 Kỵ Binh Quả Cảm', '12 Strong', 'https://phimimg.com/upload/vod/20251102-1/fd7a6148a91981c00ee3abf64a2f2388.jpg', 'https://phimimg.com/upload/vod/20251102-1/0fdc5ac81410c177cabde9b20b7bfe7f.jpg', '<p>Vài tuần sau vụ khủng bố kinh hoàng 11/9 tại Mỹ, một nhóm binh lính 12 người thuộc lực lượng đặc biệt đã được cử đến Afghanistan để tham gia vào một cuộc chiến nhằm tiêu diệt Taliban và các đồng minh AlQueda. Bộ phim là câu chuyện về cách mà 12 người lính này đã cùng với một nhóm nhỏ kỵ binh người Afghanistan thay đổi toàn bộ cuộc chiến trước khi người Mỹ kịp nhận ra là nó đã bắt đầu.</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Trevante Rhodes","avatar":""},{"name":"Geoff Stults","avatar":""},{"name":"Thad Luckinbill","avatar":""},{"name":"Austin Stowell","avatar":""},{"name":"Ben O''Toole","avatar":""},{"name":"Jack Kesy","avatar":""},{"name":"Fahim Fazli","avatar":""},{"name":"Austin Hébert","avatar":""},{"name":"Kenny Sheard","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Yousuf Azami","avatar":""},{"name":"Taylor Sheridan","avatar":""},{"name":"William Fich","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["骑兵团","Twelve Strong","Horse Soldiers","Operation - 12 Strong","12 Strong - Die wahre Geschichte der US-Horse Soldiers","Кавалерія","12猛漢","12 Valientes","12 壯士","12 Strong: The Declassified True Story of the Horse Soldiers","12 Strong - Die wahre Geschichte der US-Horse-Soldiers","12 Strong"]', 1784690324388);
