INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mowgli-cau-be-rung-xanh-huyen-thoai-rung-xanh', 'Mowgli: Cậu Bé Rừng Xanh (Huyền Thoại Rừng Xanh)', 'Mowgli: Legend of the Jungle', 'https://phimimg.com/upload/vod/20260112-1/c92e03fa7e1ae9f0b3cc8470c30d07ca.jpg', 'https://phimimg.com/upload/vod/20260112-1/08e5f2e33ab360a249ef08a973c1cc95.jpg', '<p>Mowgli: Legend of the Jungle được xây dựng dựa trên tác phẩm văn học kinh điển của tác giả Rudyard Kipling, &quot;The Jungle Book&quot; kể lại cuộc phiêu lưu của Mowgli - cậu bé mồ côi được đàn sói nuôi dưỡng trong một khu rừng già Ấn Độ. Nội dung của câu chuyện đã mang lại cho khán giả nhiều cảm xúc về cuộc đời của một cậu bé đáng thương phải đứng giữa cuộc chiến của hai thế giới muôn thú và loài người ...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Anh', 0, '[{"name":"Rohan Chand","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Matthew Rhys","avatar":""},{"name":"Freida Pinto","avatar":""},{"name":"Keveshan Pillay","avatar":""},{"name":"Louis Ashbourne Serkis","avatar":""},{"name":"Moonsamy Narasigadu","avatar":""},{"name":"Soobrie Govend","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Книга джунглей: Начало","Jungle Book: Origins","Mogli: O Livro da Selva","Mowgli","Jungle Book","Маугли: Легенда джунглей","Mogli - Entre Dois Mundos","Mowgli : la légende de la jungle","Mauglí - příběh džungle","Mauqli: Cəngəlliyin Əfsanəsi","Mowgli: Legend of the Jungle"]', 1784690324389);
