INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mowgli-cau-be-rung-xanh-huyen-thoai-rung-xanh', 'Mowgli: Cậu Bé Rừng Xanh (Huyền Thoại Rừng Xanh)', 'Mowgli: Legend of the Jungle', 'mowgli: cậu bé rừng xanh (huyền thoại rừng xanh) mowgli: legend of the jungle rohan chand christian bale cate blanchett benedict cumberbatch naomie harris andy serkis peter mullan jack reynor eddie marsan tom hollander matthew rhys freida pinto keveshan pillay louis ashbourne serkis moonsamy narasigadu soobrie govend книга джунглей: начало jungle book: origins mogli: o livro da selva mowgli jungle book маугли: легенда джунглей mogli - entre dois mundos mowgli : la légende de la jungle mauglí - příběh džungle mauqli: cəngəlliyin əfsanəsi mowgli: legend of the jungle', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-cuoi-cung-phan-3', 'Vương Triều Cuối Cùng (Phần 3)', 'The Last Kingdom (Season 3)', 'https://phimimg.com/upload/vod/20260112-1/d8e0ab697a947f09706d10c4cfd6a2f9.jpg', 'https://phimimg.com/upload/vod/20260112-1/b3c21ad29043098ded850bd13fdfb60c.jpg', '<p>Một bộ phim về những chiến công anh hùng và những trận chiến hoành tráng với chiều sâu chủ đề bao gồm chính trị, tôn giáo, chiến tranh, lòng dũng cảm, tình yêu, lòng trung thành và hành trình tìm kiếm bản sắc chung của chúng ta. &nbsp;Kết hợp các nhân vật và sự kiện lịch sử có thật với các nhân vật hư cấu, đó là câu chuyện về cách một dân tộc kết hợp sức mạnh của họ dưới một trong những vị vua nổi tiếng nhất lịch sử để khai hoang đất đai cho chính họ và xây dựng một nơi mà họ gọi là quê hương.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexander Dreymon","avatar":""},{"name":"Emily Cox","avatar":""},{"name":"Eliza Butterworth","avatar":""},{"name":"Mark Rowley","avatar":""},{"name":"Ruby Hartley","avatar":""},{"name":"Cavan Clerkin","avatar":""},{"name":"Arnas Fedaravičius","avatar":""},{"name":"Harry Gilby","avatar":""},{"name":"Timothy Innes","avatar":""},{"name":"Stefanie Martini","avatar":""},{"name":"Phia Saban","avatar":""},{"name":"Adrian Schiller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sonuncu Krallıq","Последното кралство","O Último Reino","孤国春秋","最后的王国","Το Τελευταίο Βασίλειο","最後的王國","Posljednje kraljevstvo","Az utolsó királyság","آخرین پادشاهی","ラスト・キングダム","라스트 킹덤","Paskutinioji karalystė","Det siste kongeriket","Upadek królestwa","Poslednje kraljevstvo","Последнее королевство","المملكة الأخيرة","Posledné kráľovstvo","Son Krallık","Останнє Королівство","Vương Triều Cuối Cùng","The Last Kingdom"]', 1784690324389);
