INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-tien-gia', 'Phi Vụ Tiền Giả', 'Project Gutenberg', 'https://phimimg.com/upload/vod/20260109-1/8a234b8c2ca687b110e2e3297851d299.jpg', 'https://phimimg.com/upload/vod/20260109-1/9f4a2b24a104380988cd87bbd5ed92de.jpg', '<p>Cảnh sát Hồng Kông đã phá vỡ một phi vụ tiền giả động trời và bắt được Lee Man, một thành viên chủ chốt của đường dây tiền giả khi hắn đang chạy trốn sang Thái Lan. Các thanh tra cảnh sát đang nỗ lực tìm ra chân tưóng của Painter, kẻ chủ mưu đứng đầu băng đảng làm tiền giả từ lời khai của Lee Man. Bất chấp sự truy đuổi mạnh mẽ của cảnh sát, băng đảng của Painter lừa mua được giấy in tiền và cướp được một xe tải chở mực bảo mật để sản xuất hàng loạt các tờ tiền đô giả có thể qua mặt được cả những chuyên gia tiền tệ. Sở cảnh sát nhận ra họ phải đối mặt với một kẻ thù mạnh hơn họ tưởng ...</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chow Yun-Fat","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Joyce Feng","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"David Wang","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Deon Cheung Chung-Chi","avatar":""},{"name":"Justin Cheung Kin-Sing","avatar":""},{"name":"Carl Ng Ka-Lung","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Xing Jiadong","avatar":""},{"name":"Sam Leung Kin-Ping","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3