INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-cua-long-tham', 'Cái Giá Của Lòng Tham', 'Tumbbad', 'https://phimimg.com/upload/vod/20260105-1/0aad358e6db5812e8d547dd6c2a45203.jpg', 'https://phimimg.com/upload/vod/20260105-1/c79bac8e43601178ff13236d8df1cc1f.jpg', '<p>Ấn Độ, năm 1918. Ở ngoại ô Tumbbad, một ngôi làng bị nguyền rủa nơi trời luôn mưa, Vinayak cùng với mẹ và anh trai chăm sóc một bà già bí ẩn, người giữ bí mật về kho báu của tổ tiên mà Vinayak bị ám ảnh.</p>', 'Full', 1, 'single', 'completed', 31, 2018, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sohum Shah","avatar":""},{"name":"Mohammad Samad","avatar":""},{"name":"Harsh K.","avatar":""},{"name":"Jyoti Malshe","avatar":""},{"name":"Dhundiraj Prabhakar Jogalekar","avatar":""},{"name":"Rudra Soni","avatar":""},{"name":"Madhav Hari Joshi","avatar":""},{"name":"Piyush Kaushik","avatar":""},{"name":"Anita Date-Kelkar","avatar":""},{"name":"Deepak Damle","avatar":""},{"name":"Cameron Anderson","avatar":""},{"name":"Ronjini Chakraborty","avatar":""},{"name":"Harish Khanna","avatar":""},{"name":"Ratnabali Chatterjee","avatar":""},{"name":"Raghubir Yadav","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Tumbbad 2018","คำสาปแห่งทุมบ์บาด","塔巴德","तुम्बाड"]', 1784690324389);
