INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('om-em-that-chat-2018', 'Ôm Em Thật Chặt', 'Hold Me Tight', 'https://phimimg.com/upload/vod/20260104-1/0fdd41177497a748c2c1d5d1494879dd.jpg', 'https://phimimg.com/upload/vod/20260104-1/c225a0843b17b1628888f4f2ab15c1b3.jpg', '<p>Cuộc sống hạnh phúc bên chồng con của Nam Hyun Joo bỗng đảo lộn khi cô nhận được tin mình mắc bệnh hiểm nghèo và chỉ còn sống được sáu tháng. Đối mặt với cái chết cận kề, thay vì sống trọn vẹn những ngày cuối cùng bên người thân, cô lại che giấu bệnh tình và thậm chí còn quyết định ly hôn với chồng. Với Hyun Joo, sáu tháng còn lại không phải là kết thúc, mà là cơ hội để cô làm lại cuộc đời, thực hiện nốt những tâm nguyện còn dang dở và sống vì bản thân sau nhiều năm hy sinh cho gia đình.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 10, 2018, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Hye-jin","avatar":""},{"name":"Yoon Sang-hyun","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Lee Na-Yoon","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Kim Ye-joon","avatar":""},{"name":"Kim Soo-kyung","avatar":""},{"name":"Han Kyu-won","avatar":""},{"name":"Bret Allan Lindquist","avatar":""},{"name":"Sung Ryung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["紧紧相拥","Let''s Hold Hands Tightly and Watch The Sunset","Let''s Watch the Sunset","Let''s Look at the Sunset Holding Hands","손 꼭 잡고, 지는 석양을 바라보자"]', 1784690324389);
