INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-geed-ket-noi-uoc-nguyen', 'Ultraman Geed: Kết Nối Ước Nguyện', 'Ultraman Geed The Movie: Connect The Wishes', 'https://phimimg.com/upload/vod/20251227-1/0f4f653fc61d61d040518638ed3a569d.jpg', 'https://phimimg.com/upload/vod/20251227-1/816af5ba91370f627052d8c745c1b5a1.jpg', '<p>Bộ não nhân tạo khổng lồ Gilbaris đang âm mưu tiêu diệt mọi sự sống có trí tuệ trên khắp vũ trụ. Ultraman Geed phải đối mặt với định mệnh nghiệt ngã khi chạm trán một kẻ thù hùng mạnh, kẻ có khả năng chống lại cả sức mạnh ánh sáng của các Chiến binh Ultra. Trong cơn nguy biến, Ultraman Orb, Jugglus Juggler và Ultraman Zero đã kịp thời xuất hiện để ứng cứu! Chính những cảm xúc mãnh liệt trào dâng bên trong Riku đã đánh thức hình thái tối thượng của Geed — Ultimate Final!</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuomi Hamada","avatar":""},{"name":"Chihiro Yamamoto","avatar":""},{"name":"Shintaro Asanuma","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Mayu Hasegawa","avatar":""},{"name":"Hideyoshi Iwata","avatar":""},{"name":"Yuta Ozawa","avatar":""},{"name":"Yuika Motokariya","avatar":""},{"name":"Satoshi Eishima","avatar":""},{"name":"Kai Shishido","avatar":""},{"name":"Nobuyuki Kase","avatar":""},{"name":"Chisato Kawai","avatar":""},{"name":"Ken Okada","avatar":""},{"name":"Katsue Yokoyama","avatar":""},{"name":"Hiromi Mi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính