INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kimmy-bat-bai-phan-4', 'Kimmy Bất Bại (Phần 4)', 'Unbreakable Kimmy Schmidt (Season 4)', 'https://phimimg.com/upload/vod/20251220-1/ebaf4abf8b574d55319f2396b29e88bf.jpg', 'https://phimimg.com/upload/vod/20251220-1/9da188515fc2ee5392c93b352a2823fe.jpg', '<p>Khi một người phụ nữ được giải cứu khỏi một giáo phái ngày tận thế và đặt chân đến thành phố New York, cô phải học cách thích nghi với một thế giới mà cô từng nghĩ rằng không còn tồn tại nữa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ellie Kemper","avatar":""},{"name":"Tituss Burgess","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Carol Kane","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["打不倒的金咪","언브레이커블 키미 슈미트","언브레이커블 키미슈미트","Unbreakable Kimmy Schmidt"]', 1784690324389);
