INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-fuller-phan-4', 'Gia Đình Fuller (Phần 4)', 'Fuller House (Season 4)', 'https://phimimg.com/upload/vod/20251220-1/e83e0155d44037348a79ebfb98aa3f5c.jpg', 'https://phimimg.com/upload/vod/20251220-1/a4349aeb9167968ed5b3178a7310f87e.jpg', '<p>D.J. Tanner-Fuller là một góa phụ đang phải một mình nuôi dạy ba đứa con trai. Khi cuộc sống trở nên quá tải và khó lòng xoay sở, cô đã nhờ đến sự giúp đỡ của em gái Stephanie và người bạn thân nhất Kimmy. Cả ba người phụ nữ cùng chung sống dưới một mái nhà, tạo nên những tình huống gia đình vừa hài hước vừa ấm áp.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jodie Sweetin","avatar":""},{"name":"Candace Cameron Bure","avatar":""},{"name":"Andrea Barber","avatar":""},{"name":"Elias Harger","avatar":""},{"name":"Soni Bringas","avatar":""},{"name":"Michael Campion","avatar":""},{"name":"Juan Pablo Di Pace","avatar":""},{"name":"Fox Messitt","avatar":""},{"name":"Dashiell Messitt","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Jobban bír-lak","Fuller House"]', 1784690324389);
