INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-panther-chien-binh-bao-den', 'Black Panther: Chiến Binh Báo Đen', 'Black Panther', 'https://phimimg.com/upload/vod/20251211-1/b4977eac62969f488dcb292b9ba54098.jpg', 'https://phimimg.com/upload/vod/20251211-1/5704d0324651b14e2f8c39a66d6072b0.jpg', '<p>Vương quốc Wakanda, quê hương của Black Panther/ T&quot;Challa hiện ra qua lời kể của một nhân chứng sống sót trở về. Đây là quốc gia khá khép kín và sở hữu lượng Vibranium lớn nhất trên thế giới. Black Panther - người cầm quyền của Wakanda sở hữu bộ áo giáp chống đạn và móng vuốt sắc nhọn, anh được miêu tả là “người tốt với trái tim nhân hậu”. &nbsp;Nhưng cũng chính vì những đức tính tốt này mà Black Panther gặp khó khăn khi kế thừa ngai vàng sau khi vua cha băng hà. Đối mặt với sự phản bội và hiểm nguy, vị vua trẻ phải tập hợp các đồng minh và phát huy toàn bộ sức mạnh của Black Panther để đánh bại kẻ thù, đem lại an bình cho nhân dân của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Chadwick Boseman","avatar":""},{"name":"Michael B. Jordan","avatar":""},{"name":"Lupita Nyong''o","avatar":""},{"name":"Danai Gurira","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Letitia Wright","avatar":""},{"name":"Winston Duke","avatar":""},{"name":"Sterling K. Brown","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Florence Kasumba","avatar":""},{"name":"John Kani","avatar":""},{"name":"David S. Lee","avatar":""},{"name":"Nabiyah Be","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Marvel''s Black Panther","마블 블랙 팬서","Marvel Studios'' Black Panther","黑豹","Chiến Binh Báo Đen","Czarna Pantera","ブラックパンサー：2018","Black Panther","Pantera Negra: 1","Սև Պանտերա","Черная пантера","بلاك بانثر"]', 1784690324389);
