INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-thoi-gian', 'Kẻ Trộm Thời Gian', 'Stealing Seconds', 'https://phimimg.com/upload/vod/20251208-1/d8c94a6975c1b69a6b26995c2d1a1637.jpg', 'https://phimimg.com/upload/vod/20251208-1/e1d18786f6f51c00ece2e58363c209f4.jpg', '<p>Chuyện phim kể về chàng trai tên Tăng Đống Nhân ( Viên Vỹ Hào). Lúc anh được sinh ra sức khỏe rất yếu, gần như mất đi, nhưng may mắn thay, thời khắc anh sinh ra đúng lúc lại vừa bước qua năm mới có giây nhuận, tức là mỗi người trên thế giới đều có thêm một giây. Anh nhờ lời cầu nguyện và nụ hôn chan chứa yêu thương của người mẹ mà sống dậy như một phép màu. Cuộc sống của Đống Nhân bình thường như bao người khác, anh làm việc ở một công ty tổ chức sự kiện nhưng vì tính tình không ganh đua, cố gắng nên thường hay bị giao những công việc vặt. Trong một lần vô tình bị đột tử giữa đường và được nhân viên cứu hộ Trình Mẫn Kỳ ( Đường Thi Vịnh) hô hấp nhân tạo, anh mới sống sót qua được cơn nguy kịch. Kỳ lạ thay, sau khi cứu Đống Nhân thì Mẫn Kỳ bị bất tỉnh hai ngày, bỏ lỡ đám cưới của cô và Châu Đức Sâm ( Dương Triều Khải). Kết quả hôn lễ bị hủy và chồng chưa cưới của cô thì mất tích một cách khó hiểu. Cuộc đời của Mẫn Kỳ sau khi cứu Đống Nhân thay đổi hoàn toàn, khiến cô hoang mang vô cùng. Sau này, khi Đống Nhân phát hiện ra mình đã hại Mẫn Kỳ không thể kết hôn cùng với bạn thân của anh, anh cảm thấy có lỗi nên thường ở bên cạnh giúp đỡ cô. Từ đây hai người dần có tình cảm với nhau, đồng thời anh cũng phát hiện ra khả năng kỳ lạ của bản thân mình. Nhớ lại lời mẹ dặn mình phải biết quý trọng thời gian, qua đó anh mới biết nếu như anh muốn tiếp tục sống anh phải đánh cắp thời gian của người khác bằng một nụ hôn.?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 16, 2018, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đường Thi Vịnh","avatar":""},{"name":"Viên Vỹ Hào","avatar":""},{"name":"Chu Thần Lệ","avatar":""},{"name":"Lại Úy Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["棟仁的時光","Stealing Seconds"]', 1784690324389);
