INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-gio-nghet-tho', 'Một Giờ Nghẹt Thở', 'Beast Of Burden', 'https://phimimg.com/upload/vod/20251206-1/a50a766a7223a8b3c1b794ae7563f702.jpg', 'https://phimimg.com/upload/vod/20251206-1/54d192f9126b5e77143055cb54a51165.jpg', '<p>Sean Haggerty chỉ có một giờ để giao món hàng lậu của mình.&nbsp; Một giờ để trấn an một băng đảng ma túy, một sát thủ, và DEA (Cục Quản lý Thực thi Ma túy) rằng mọi thứ vẫn ổn.&nbsp; Một giờ để đảm bảo vợ anh sống sót.&nbsp; Và anh phải thực hiện tất cả những điều đó từ trong buồng lái chiếc máy bay Cessna của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"Grace Gummer","avatar":""},{"name":"Robert Wisdom","avatar":""},{"name":"David Joseph Martinez","avatar":""},{"name":"Cesar Perez","avatar":""},{"name":"Mark Rhino Smith","avatar":""},{"name":"Renée Willett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El Traficante","El traficante","Der Kurier - In den Fängen des Kartells","Beast of Burden"]', 1784690324389);
