INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-bach-hop-yagate-kimi-ni-naru', 'Mối Tình Bách Hợp (Yagate Kimi ni Naru)', 'Bloom Into You', 'https://phimimg.com/upload/vod/20251204-1/ecfac860dc1beab2694f88c19a70d668.jpg', 'https://phimimg.com/upload/vod/20251204-1/45712a1eec864c07f05e5ff48ee24e79.jpg', '<p>Có Yuri nhé :v Yuu rất thích những câu truyện tình lãng mạn, cô luôn mong rằng một ngày nào đó, mình sẽ được tỏ tình giống như những trang tình yêu kia. Ngày tốt nghiệp, chàng trai mà Yuu thích đã tỏ tình với cô, nhưng cô không cảm nhận được những thứ cảm xúc giống trong những tác phẩm đầy lãng mạn mà cô thường đọc. Cô hẹn cậu bạn đó một tháng để mình có thể suy nghĩ, bước vào trường mới, Yuu đã gặp Nanami – một thành viên của hội học sinh và cũng là đàn chị của cô. Sau khi biết Nanami đã từ chối không biết bao nhiêu lời tỏ tình và tuyên bố rằng “chị không muốn yêu ai hết”, Yuu đã lấy hết can đảm kể lại mọi việc với Nanami. Mọi việc tưởng chừng đã kết thúc, nào ngờ Nanami ngay lập tức tỏ tình với Yuu…</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuuki Takada","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Taichi Ichikawa","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Yuka Terasaki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["最终我成为了你","Yagate Kimi ni Naru","Yagate Kimi ni Naru - Bloom into You","이윽고 네가 된다","Когда-нибудь я стану тобой","В итоге я стану твоей","สุดท้ายก็คือเธอ","やがて君になる"]', 1784690324389);
