INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bojack-horseman-phan-5', 'BoJack Horseman (Phần 5)', 'BoJack Horseman (Season 5)', 'https://phimimg.com/upload/vod/20251202-1/eae83a39ce50b7ac19acc91bcba02599.jpg', 'https://phimimg.com/upload/vod/20251202-1/a40ddb19c250defbd6f5d24b8c7dc7d6.jpg', '<p>Hãy gặp chú ngựa đóng sitcom được yêu thích nhất của những năm 1990, ở 20 năm sau. Anh là kẻ thô lỗ có trái tim, không hẳn là vàng, nhưng là gì đó giống vàng. Đồng chăng?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Arnett","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Paul F. Tompkins","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["بوجاك هورسمان","ცხენი ბოჯეკი","Μπότζακ Χόρσμαν","בוג''אק הורסמן","Конь БоДжек","Кiнь БоДжек","BoJack Horseman"]', 1784690324389);
