INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-ky-la-tiec-quai-vat-vui-nhon', 'Những Người Bạn Kỳ Lạ: Tiệc Quái Vật Vui Nhộn', 'Oddbods: Party Monsters', 'https://phimimg.com/upload/vod/20251120-1/c5f963d222d7386a339b7b345899565b.jpg', 'https://phimimg.com/upload/vod/20251120-1/9f75593ee90e55770a40cd387a367c68.jpg', '<p>Tổ chức bữa tiệc hóa trang quái vật, Jeff mời một pháp sư đến biểu diễn phép thuật để bữa tiệc thêm phần thú vị. Tuy nhiên, nhóm bạn nghịch ngợm lại khiến ông ta tức giận biến họ thành chính nhân vật mà họ đã hóa trang. Lúc này, Slick trong thân phận Sherlock Holmes phải sử dụng tất cả các kỹ năng thám tử để cứu các bạn của mình.</p>', 'Full', 1, 'single', 'completed', 27, 2018, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Nadia Ramlee","avatar":""},{"name":"Chio Su-Ping","avatar":""},{"name":"Jeremy Linn","avatar":""},{"name":"Marlon Dance-Hooi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Oddbods: Party Monsters"]', 1784690324389);
