INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-thu-vo-hinh-4', 'Quái Thú Vô Hình 4', 'The Predator', 'quái thú vô hình 4 the predator boyd holbrook trevante rhodes sterling k. brown jacob tremblay keegan-michael key olivia munn thomas jane alfie allen augusto aguilera jake busey yvonne strahovski brian a. prince mike dopud niall matter javier lacroix gabriel labelle niko o predador pred4tor 铁血战士：掠夺者 the predator le prédateur 더 프레데터 הטורף 4 av 4 鐵血戰士：血獸進化 铁血战士4 predator 4: the predator predator: a ragadozó predator: új ragadozó predator iv المفترس 4', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-cuoc-doi-mot-trai-tim-bac-si-tim', 'Hai Cuộc Đời Một Trái Tim (Bác Sĩ Tim)', 'Two Lives One Heart (Heart Surgeons)', 'https://phimimg.com/upload/vod/20250916-1/7a6e428e33e359ed53abcad724d4ef7a.jpg', 'https://phimimg.com/upload/vod/20250916-1/0207ea115f4bfe35d90af8f8807d4cbe.jpg', '<p>Bộ phim xoay quanh cuộc sống hỗn loạn của Park Tae Soo (Go Soo), một bác sĩ phẫu thuật tim tận tâm, chăm chỉ nhưng lại luôn bị coi thường chỉ vì tốt nghiệp một trường đại học không mấy danh tiếng. Trong một tình huống đầy cấp bách, Park Tae Soo đã gặp Choi Seok Han (Uhm Ki Joon), một giáo sư phẫu thuật giỏi tay nghề nhưng cũng có một cuộc đời đầy bất hạnh. Cuộc gặp gỡ định mệnh này đã giúp Park Tae Soo có được cơ hội làm việc tại một bệnh viện lớn ngay giữa thủ đô Seoul tráng lệ. Tưởng rằng cuộc đời đã bước sang một trang mới tươi sáng hơn nhưng rốt cuộc, Park Tae Soo liên tục phải đối mặt với vô vàn rắc rối khi anh dần phát hiện ra những góc tối trong công việc lương y mà mình đang theo đuổi.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Go Soo","avatar":""},{"name":"Uhm Ki-joon","avatar":""},{"name":"Seo Ji-hye","avatar":""},{"name":"Jung Bo-seog","avatar":""},{"name":"Nam Kyung-eup","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Oh Dong-min","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Lee Jae-won","avatar":""},{"name":"Cha Soon-bae","avatar":""},{"name":"Son Kwang-Eop","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Hong Lu-hyeon","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Kang Seo-ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '["胸腔外科-盜取心臟的醫生們","Two Lives One Heart","Cardiothoracic Surgery","Thoracic Surgery","흉부외과:심장을 훔친 의사들"]', 1784690324389);
