INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-cuoc-doi-mot-trai-tim-bac-si-tim', 'Hai Cuộc Đời Một Trái Tim (Bác Sĩ Tim)', 'Two Lives One Heart (Heart Surgeons)', 'hai cuộc đời một trái tim (bác sĩ tim) two lives one heart (heart surgeons) go soo uhm ki-joon seo ji-hye jung bo-seog nam kyung-eup kim ye-won jang so-yeon oh dong-min ahn nae-sang lee jae-won cha soon-bae son kwang-eop jo jae-yun hong lu-hyeon park kyung-hye kang seo-ha 胸腔外科-盜取心臟的醫生們 two lives one heart cardiothoracic surgery thoracic surgery 흉부외과:심장을 훔친 의사들', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-ky-dam-2', 'Cổ Kiếm Kỳ Đàm 2', 'Swords Of Legends 2', 'https://phimimg.com/upload/vod/20250622-1/3aaeea71d6640354b5a044fc79b13dba.jpg', 'https://phimimg.com/upload/vod/20250622-1/2731f100f8513e414a7ce1d2df69dfad.jpg', '<p>Nhạc Vô Dị, chàng trai hiệp nghĩa lên đường đi tìm tòi học tập yển thuật . Trên đường cậu gặp được nàng Văn Nhân Vũ – một cô gái trung can nghĩa đảm của Bách Thảo Cốc, cùng với Hạ Di Tắc – đệ tử Thái Hoa quan và cũng là nửa người nửa yêu. Họ lên đường đi tìm yển sư Tạ Y, đồng thời gặp được linh nữ A Nguyễn. Họ cùng nhau chiến đấu chống lại đám người của Lưu Nguyệt Thành. Lưu Nguyệt Thành điều kiện sống không tốt nên Đại Tế Tư Thẩm Dạ quyết định hợp tác với Tâm Ma làm hại chúng sinh, đổi lại đưa tộc Liệt Sơn xuống hạ giới.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 14, 2018, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Phó Tinh","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Trương Dân Kiệt","avatar":""},{"name":"Vương Vũ Tuyền","avatar":""},{"name":"Lý Tranh Nghiệp","avatar":""},{"name":"Từ Hải Kiều","avatar":""},{"name":"Trịnh Hiểu Đông","avatar":""},{"name":"Cung Bội Bật","avatar":""},{"name":"Dĩnh Nhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Gu Jian Qi Tan","고검기-담","Legend of the Ancient Sword","Ancient Sword Fantasy","Swords of Legends","古剑奇谭"]', 1784690324389);
