INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-phau-thuat-cua-grey-phan-15', 'Ca Phẫu Thuật Của Grey (Phần 15)', 'Grey''s Anatomy (Season 15)', 'ca phẫu thuật của grey (phần 15) grey''s anatomy (season 15) ellen pompeo chandra wilson james pickens jr. kevin mckidd caterina scorsone camilla luddington kim raver jason george chris carmack anthony hill adelaide kane alexis floyd niko terho harry shum jr. trevor jackson anatomia e greit a anatomia de grey l''anatomie de grey 实习医生 grey''s anatomy die jungen ärzte grey''s anatomy die jungen aerzte grey''s anatomy - die jungen ärzte a coeur ouvert 그레이 아나토미 анатомія пристрасті greys anatomy grey''s anatomy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-nguyen-thuy-phan-5', 'Ma Cà Rồng Nguyên Thủy (Phần 5)', 'The Originals (Season 5)', 'https://phimimg.com/upload/vod/20251102-1/0ded990c80c31b01e3ea1b2a4dc6f7bc.jpg', 'https://phimimg.com/upload/vod/20251102-1/4466f4213389c3c57449fe24a96f57e8.jpg', '<p>Klaus Mikaelson nhận được tin có thế lực siêu nhiên đang vùng dậy chống lại hắn ở New Orleans. Những nghi vấn của Klaus đưa hắn về gặp lại tên đệ tử xảo quyệt của hắn, Marcel, một trùm ma cà rồng điều khiển tất cả ma cà rồng lẫn người dân nơi đây. Vì muốn giúp em trai mình hối cải, Elijah theo Klaus quay về New Orleans và nhanh chóng phát hiện ra cô người sói Hayley cũng đến đây để tìm manh mối về dòng tộc mình, và bị rơi vào tay của một phù thủy quyền năng tên Sophie. Căng thẳng xảy ra trên thị trấn này khi những luật lệ mà Marcel đưa ra buộc dân chúng phải tuân theo đang có nguy cơ bị phá vỡ. Vì Klaus, tìm cho ra câu trả lời vì sao đệ tử hắn lại có được mọi thứ đáng lý ra phải là của hắn. Trong khi chờ đợi liệu em gái họ, Rebekah, có rời Mystic Falls để gặp lại gia đình không, Klaus và Elijah ép buộc phù thủy nơi đây lập liên minh để đảm bảo New Orleans một lần nữa sẽ dưới quyền cai trị của Những Ma Cà Rồng Nguyên Thủy.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joseph Morgan","avatar":""},{"name":"Daniel Gillies","avatar":""},{"name":"Charles Michael Davis","avatar":""},{"name":"Riley Voelkel","avatar":""},{"name":"Yusuf Gatewood","avatar":""},{"name":"Danielle Rose Russell","avatar":""},{"name":"Steven Krueger","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},