INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-cam-lang', 'Vùng Đất Câm Lặng', 'A Quiet Place', 'https://phimimg.com/upload/vod/20251028-1/7e86044ed4ee4a9b2ebbb486c8f0c788.jpg', 'https://phimimg.com/upload/vod/20251028-1/374193b8d814ff1aeafe4776625ed2a4.jpg', '<p>Tách biệt khỏi phần còn lại của thế giới, một gia đình khăng khít nơm nớp lo sợ mình sẽ phát ra tiếng động thu hút những sinh vật ngoài hành tinh đáng sợ.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Emily Blunt","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Millicent Simmonds","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Cade Woodward","avatar":""},{"name":"Leon Russom","avatar":""},{"name":"Rhoda Pell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Un posto tranquillo","Kena vaikne kohake","Sans un bruit","Un coin tranquille","A Quiet Place Part 1","Vùng Đất Câm Lặng","無聲絕境","Un lugar tranquilo","Səssiz Bir Yer","A Quiet Place 1","A Quiet Place"]', 1784690324389);
