INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-cam-lang', 'Vùng Đất Câm Lặng', 'A Quiet Place', 'vùng đất câm lặng a quiet place emily blunt john krasinski millicent simmonds noah jupe cade woodward leon russom rhoda pell un posto tranquillo kena vaikne kohake sans un bruit un coin tranquille a quiet place part 1 vùng đất câm lặng 無聲絕境 un lugar tranquilo səssiz bir yer a quiet place 1 a quiet place', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-nu-quyen', 'Cuộc Chiến Nữ Quyền', 'The Forgotten Valley', 'https://phimimg.com/upload/vod/20251023-1/a4f61284dc47f24dbef62374183c40e2.jpg', 'https://phimimg.com/upload/vod/20251023-1/6f5d9fde560a5bc2df6823ef8999eb42.jpg', '<p>Lục Thủy Phong (do Vương Hạo Nhiên đóng) và La Quế Tư (do Trần Khải Lâm giữ vai) là đôi vợ chồng muốn thay đổi và xây dựng quê hương phong kiến và lạc hậu của mình, nhưng họ bị cản trở bởi sự cai trị của Lục Kim Cốc (do Lưu Giang thủ vai), người cha cũng là trưởng thôn, và bị cuốn vào chuyện hồn ma tân nương giết người, bắt cóc. Một nhóm phụ nữ bị áp bức, bao gồm ba cô vợ lẻ của Kim Cốc và nhiều chị em khác, không cam tâm tiếp tục bị đối đãi bất công từ cánh đàn ông, lén lút tổ chức một liên minh nhằm bảo vệ các chị em trong làng bị bức hại. Cuộc chiến của phái yếu chống lại phái mạnh đã diễn ra ngày càng khốc liệt, và tình cảm giữa hai vợ chồng Phong và Tư cũng gặp nhiều thử thách. Trong phim còn có sự tham gia của các diễn viên như Tô Ngọc Hoa, Chu Lệ Thần, Cung Gia Hân, Nguyễn Triệu Tường.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2018, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Ho-Yin Wong","avatar":""},{"name":"Grace Chan","avatar":""},{"name":"Louisa So Yuk-Wah","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Rosanne Lui Shan","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"Katy Kung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["平安谷之诡谷传说","平安谷之詭谷傳說"]', 1784690324389);
