INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-nu-quyen', 'Cuộc Chiến Nữ Quyền', 'The Forgotten Valley', 'cuộc chiến nữ quyền the forgotten valley raymond ho-yin wong grace chan louisa so yuk-wah lau kong rosanne lui shan rebecca zhu katy kung 平安谷之诡谷传说 平安谷之詭谷傳說', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tro-bach-quy-kakuriyo-no-yadomeshi-phan-1', 'Quán Trọ Bách Quỷ (Kakuriyo no Yadomeshi) (Phần 1)', 'Kakuriyo: Bed & Breakfast For Spirits (Season 1)', 'https://phimimg.com/upload/vod/20251002-1/fc775a660d97b533da04f3552baa372b.jpg', 'https://phimimg.com/upload/vod/20251002-1/cb4bca0933d375e1a4bc0bec520f0f09.jpg', '<p>Series xoay quanh một cô sinh viên tên là Aoi. Cô đã được thừa hưởng từ người ông quá cố của mình năng lực thấy được linh hồn. Không những thế, cô còn là một nữ công gia chánh chính hiệu với tài nghệ nấu bếp siêu hạng. Một ngày nọ, Aoi bị một vị thần và cũng là chủ của nhà trọ Tenshinya bắt cóc. Hắn ta nói rằng vì món nợ của ông cô, cô phải trở thành vợ của hắn. Đương nhiên Aoi không hề chấp nhận điều này, và cô quyết định sẽ trả món nợ thay ông mình bằng cách làm việc tại Tenshiya.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kakuriyo no Yadomeshi","かくりよの宿飯 弐","Kakuriyo no Yadomeshi Ni","かくりよの宿飯第２期","Чем кормят в ином мире","妖怪旅館營業中 貳","Kakuriyo -Bed & Breakfast for Spirits- 2","かくりよの宿飯"]', 1784690324389);
