INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-quy-nhi-ma-thu-ba-takagi-phan-1', 'Nhất Quỷ Nhì Ma Thứ Ba Takagi (Phần 1)', 'Teasing Master Takagi-san (Season 1)', 'https://phimimg.com/upload/vod/20241121-1/c8c080586daa64982867951933583f04.jpg', 'https://phimimg.com/upload/vod/20241121-1/46143e0d10df676559ab5f052eedf601.jpg', '<p>&quot;Nếu cậu đỏ mặt, cậu sẽ thua.&quot; Sống theo chân lý này, cậu học sinh cấp 2 Nishikata thường xuyên bị Takagi-san cô hàng xóm của mình chọc ghẹo. Với niềm tự hào dũng mãnh của đàn ông Nishikata quyết định trả thù cô bạn ở trên lớp. Và như vậy, cậu ta luôn luôn cố gắng trêu lại Takagi-san mỗi ngày, nhưng thay vào đó lại bị chọc ngược lại. Và Takagi-san đã bị đỏ mặt vì thua.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 20, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Rie Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Takagi: A Mestra das Pegadinhas","擅长捉弄人的高木同学","擅长捉弄的高木同学","Karakai Jouzu no Takagi-san","Quand Takagi me taquine","Karakai Jōzu no Takagi-san","からかい上手の高木さん３","Karakai Jouzu no Takagi-san 3","Karakai Jouzu no Takagi-san 2","Озорная Такаги","Мастер дразнилок Такаги","Поддразнивание Такаги","แกล้งนัก รักนะรู้ยัง?","Teasing Master Takagi-san","からかい上手の高木さん"]', 1784690324389);
