INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-long-tu-tien-truyen', 'Ngự Long Tu Tiên Truyện', 'Dragon Sword (To Be Immortal)', 'https://phimimg.com/upload/vod/20251020-1/a55c98d6868a6bef65b7ec679c9bd946.jpg', 'https://phimimg.com/upload/vod/20251020-1/b4790be342a1498dd91fb0ad4522e812.jpg', '<p>Phim kể về Phó Viêm (do Bành Vũ Tư thủ vai) — một nhân viên văn phòng bình thường làm việc từ sáng đến tối, bất ngờ qua đời trong một vụ tai nạn giao thông trên đường đi làm. Đúng lúc đó, một người dẫn đường thần bí xuất hiện, nói với anh rằng cái chết không phải là kết thúc mà là khởi đầu của một hành trình mới. Người này giúp Phó Viêm tái tạo thân thể, mở ra con đường tu tiên huyền ảo đầy thử thách và cơ duyên…</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Vũ Tư","avatar":""},{"name":"Trương Hâm Nguyên","avatar":""},{"name":"Tần Ngôn Vĩ","avatar":""},{"name":"Tào Kỳ","avatar":""},{"name":"Trần Thần","avatar":""},{"name":"Ngụy Tử Cường","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Legend of Dragon Cultivator","Dragon Sword","To be Immortal","To Be Immortal (2018)","御龙修仙传"]', 1784690324389);
