INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngu-long-tu-tien-truyen', 'Ngự Long Tu Tiên Truyện', 'Dragon Sword (To Be Immortal)', 'ngự long tu tiên truyện dragon sword (to be immortal) bành vũ tư trương hâm nguyên tần ngôn vĩ tào kỳ trần thần ngụy tử cường legend of dragon cultivator dragon sword to be immortal to be immortal (2018) 御龙修仙传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-danh-thue-2', 'Lính Đánh Thuê 2', 'Mercenary War 2', 'https://phimimg.com/upload/vod/20251020-1/cb6ae4c0f7e78a6021e25188acb03b9e.jpg', 'https://phimimg.com/upload/vod/20251020-1/c6a32157a1ae12f32e1fc80b2f8ef412.jpg', '<p>Nội chiến tại quốc gia M mất kiểm soát, phe nổi dậy gây ra cuộc thảm sát sắc tộc, khiến cộng đồng quốc tế đặc biệt quan tâm, nhưng Hội đồng Bảo an Liên Hợp Quốc lại không phê chuẩn hành động can thiệp quân sự. Tử An nhận một nhiệm vụ nguy hiểm: dẫn đội lính đánh thuê thâm nhập sâu vào vùng chiếm đóng của quân phản loạn, tìm kiếm bác sĩ Linh Nguyệt thuộc nhóm y tế Hội Chữ Thập Đỏ và đưa cô đến nơi an toàn. Trên đường đi, Tử An cùng đồng đội vượt qua vô số trận chiến đẫm máu trong rừng rậm, cuối cùng tìm được Linh Nguyệt. Tuy nhiên, cô kiên quyết không rời đi nếu không mang theo 70 người tị nạn mà cô đang chăm sóc. Tử An — người từng được huấn luyện rằng nhiệm vụ luôn quan trọng hơn tất cả — nay phải đối mặt với lựa chọn sinh tử: tuân lệnh để sống sót hay làm điều đúng đắn để cứu người. Khi anh còn chưa kịp đưa ra quyết định, một cuộc khủng hoảng mới lại ập đến, đẩy những người lính đánh thuê vào trận chiến cuối cùng giữa nghĩa vụ và lương tri.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Miêu Duẫn Đồng","avatar":""},{"name":"Thạch Vũ Thanh","avatar":""},{"name":"Bassem Khayati","avatar":""},{"name":"Trương Từ","avatar":""},{"name":"Lý Kiều Đan","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["佣兵战争2"]', 1784690324389);
