INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-cac-goa-phu-hanh-dong', 'Khi Các Góa Phụ Hành Động', 'Widows', 'https://phimimg.com/upload/vod/20251020-1/0847ebb84d38ad914a3ce468ee295878.jpg', 'https://phimimg.com/upload/vod/20251020-1/36624baa4405d48f5674932cdf864c76.jpg', '<p>Bộ phim xoay quanh câu chuyện nhóm cướp do Rawlins dẫn đầu bị cảnh sát giết chết sau một phi vụ thất bại. Song, họ cũng đã kịp giấu một số tiền lớn trước đó. Không chỉ đối mặt với nỗi đau mất chồng, bốn góa phụ gồm Veronia, Linda, Alice và Belle còn bị các điều tra viên bủa vây tứ phía. Đây là lúc họ bắt đầu phát hiện ra những âm mưu ngầm to lớn liên quan đến cái chết của chồng mình. Họ cũng chính thức bước vào cuộc đấu trí căng thẳng với những tay chính trị gia quan liêu như Jack và Tom Mulligan hay nhóm cảnh sát tham nhũng… Không còn sự lựa chọn, bốn người phụ nữ đã quyết định hợp lực để tiếp tục băng cướp, hoàn thành phi vụ trước đó của chồng, đồng thời bảo vệ gia đình mình trước những hiểm nguy.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Viola Davis","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Carrie Coon","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Molly Kunz","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Matt W","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Viudas","寡妇劫案","寡妇特工","寡婦","以寡敌众","As Viúvas","Widows"]', 1784690324389);
