INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giac', 'Ảo Giác', 'Unsane', 'https://phimimg.com/upload/vod/20251020-1/870106720355fbe77a342c1c0d12dd38.jpg', 'https://phimimg.com/upload/vod/20251020-1/fe7da957cd182c1ddf76f48185ccd6d7.jpg', '<p>Dõi theo câu chuyện của cô gái Sawyer Valentini (do Claire Foy thủ vai) khi cô bị ép vào một viện tâm thần trái với ý muốn của mình. Tại đây cô bắt gặp kẻ bám đuôi đã lén theo mình hết nơi này đến nơi khác, và phát hiện ra hắn là một nhân viên làm việc tại bệnh viện. Nhiều tình huống xảy ra sau đó khiến cô bối rối và hóa rồ, không rõ đâu là thực đâu là giả tưởng.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Claire Foy","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Jay Pharoah","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Aimee Mullins","avatar":""},{"name":"Amy Irving","avatar":""},{"name":"Sarah Stiles","avatar":""},{"name":"Marc Kudisch","avatar":""},{"name":"Colin Woodell","avatar":""},{"name":"Myra Lucretia Taylor","avatar":""},{"name":"Lynda Mauze","avatar":""},{"name":"Zach Cherry","avatar":""},{"name":"Polly McKie","avatar":""},{"name":"Raúl Castillo","avatar":""},{"name":"Michael Mihm","avatar":""},{"name":"Robert Kelly","avatar":""},{"name":"Natalie Gold","avatar":""},{"name":"Sol Marina Cr","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Unsane - Ausgeliefert","Distúrbio","Perturbada","언세인","Не в собі","Unsane"]', 1784690324389);
