INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cong-to-vien-phan-1', 'Nữ Công Tố Viên (Phần 1)', 'Partners For Justice (Season 1)', 'https://phimimg.com/upload/vod/20250418-1/87715d5e9897cbc198f32f647246bdc3.jpg', 'https://phimimg.com/upload/vod/20250418-1/c09062d795d2e02b705953c6838bfe94.jpg', '<p>Xác chết không bao giờ nói dối. Tuy nhiên, những người sống vì công lý không từ bỏ qua sự thật một cách dễ dàng. Baek Beom, một bác sĩ pháp y bị ám ảnh bởi sự thật ẩn giấu, là một thiên tài hiểu biết về pháp y. Anh không quan tâm đến cuộc sống và chỉ quan tâm đến người chết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 13, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Jae-young","avatar":""},{"name":"Jeong Yu-mi","avatar":""},{"name":"No Min-woo","avatar":""},{"name":"Kang Seung-hyun","avatar":""},{"name":"Ahn Suk-hwan","avatar":""},{"name":"Park Jun-gyu","avatar":""},{"name":"Park Hee-jin","avatar":""},{"name":"Ko Kyu-phil","avatar":""},{"name":"Kim Young-woong","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Song Young-gyu","avatar":""},{"name":"Noh Susanna","avatar":""},{"name":"Oh Man-seok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["검법남녀","검법남녀 2","Напарники","Investigation Partners","Investigation Couple","Investigation Couple 2","Investigation Partners 2"]', 1784690324389);
