INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thanh-toi-pham-giong-noi-phan-2', 'Âm thanh tội phạm (Giọng nói) (Phần 2)', 'Voice (Season 2)', 'https://phimimg.com/upload/vod/20251009-1/5fc6725bb52c6aa31175864dbe229d6c.jpg', 'https://phimimg.com/upload/vod/20251009-1/af1dc78a882967c00fa8ab295a763bdc.jpg', '<p>Cuộc sống của cảnh sát Moo Jin Hyuk bị mất kiểm soát sau cái chết thương tâm của vợ. Anh bắt đầu truy tìm hung thủ sau khi gặp Kang Kwon Joo, một cảnh sát có khả năng phân tích giọng nói và vô tình bố cô cũng từng bị sát hại bởi tên sát nhân đó. Hai con người, một mục tiêu, họ sẽ sát cánh cùng nhau để truy tìm kẻ thủ ác.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2018, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ha-na","avatar":""},{"name":"Song Seung-heon","avatar":""},{"name":"Son Eun-seo","avatar":""},{"name":"Kim Joong-ki","avatar":""},{"name":"Baek Sung-hyun","avatar":""},{"name":"Song Boo-gun","avatar":""},{"name":"Kang Seung-yoon","avatar":""},{"name":"Maurice Turner Jr.","avatar":""},{"name":"Kim Kyu-na","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["夺命杀声","声命线","Voice - Jede Stimme ist einzigartig","Voice – Jede Stimme ist einzigartig","Voice: Voz","Voz (Boiseu)","Voice 聲命缐 4","Boiseu","보이스","聲命線","Voice","Giọng nói"]', 1784690324389);
