INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-than-2018', 'Loạn Thần', 'Delirium', 'https://phimimg.com/upload/vod/20251004-1/189b13b9cd51984ea73b3ddb26e07e1b.jpg', 'https://phimimg.com/upload/vod/20251004-1/e19b75604e78ad910d7d81054845b086.jpg', '<p>Sau khi chuyển đến dinh thự của cha mẹ quá cố, một người đàn ông có tiền sử mắc bệnh tâm thần bắt đầu nghi ngờ rằng ngôi nhà mới của mình bị ma ám.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Topher Grace","avatar":""},{"name":"Kelli Barksdale","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Marty Eli Schwartz","avatar":""},{"name":"Cody Sullivan","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Robin Thomas","avatar":""},{"name":"Braden Fitzgerald","avatar":""},{"name":"Daisy McCrackin","avatar":""},{"name":"Genesis Rodriguez","avatar":""},{"name":"Harry Groener","avatar":""},{"name":"Jorge-Luis Pallo","avatar":""},{"name":"Josh Harp","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Home","Elmezavar","Delirium"]', 1784690324389);
