INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tomb-raider-huyen-thoai-bat-dau', 'Tomb Raider: Huyền Thoại Bắt Đầu', 'Tomb Raider', 'https://phimimg.com/upload/vod/20251002-1/ca0166b6277df0b90d90fb515d4f44a8.jpg', 'https://phimimg.com/upload/vod/20251002-1/4a17777db8336a77babdbe6a63558ae4.jpg', '<p>Tomb Raider kể về chuyến hành trình đầy hiểm nguy của cô gái trẻ Lara Croft nhằm tìm ra lời giải cho cái chết bí ẩn của cha mình. Trước khi qua đời, ông đã để lại lời nhắn cho cô về một tổ chức tên Trinity đang cố khởi động kế hoạch diệt chủng toàn thế giới. Lara Croft lên đường đến Biển Quỷ để thực hiện di chúc của cha. Đây là một địa danh có thật và được biết tới với tên gọi là Tam Giác Rồng, nằm trong vùng biển Nhật Bản và nổi tiếng bởi những vụ mất tích tàu thuyền bí ẩn.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Alicia Vikander","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Alexandre Willaume","avatar":""},{"name":"Tamer Burjaq","avatar":""},{"name":"Adrian Collins","avatar":""},{"name":"Keenan Arrison","avatar":""},{"name":"Andrian Mazive","avatar":""},{"name":"Milton Schorr","avatar":""},{"name":"Hannah John-Kamen","avatar":""},{"name":"Peter Waison","avatar":""},{"name":"Samuel Mak","avatar":""},{"name":"Sky Yang","avatar":""},{"name":"Civic Chu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Tomb Raider: A Origem"