INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-tuoi-20', 'Trở Lại Tuổi 20', 'Twenties Once Again', 'https://phimimg.com/upload/vod/20251001-1/5b378ecc6464e33788f71794c9db4d45.jpg', 'https://phimimg.com/upload/vod/20251001-1/abce9e2a509fa6cf2dec1fc399015a5d.jpg', '<p>Sau một trận cãi vã ỏm tỏi với ông chồng già Hạng Đại Hải , Thẩm Mộng Quân quyết định uống thuốc ngủ tự vẫn. Có ai ngờ thứ thuốc “thánh” ấy đã tình cờ biến bà thành một cô thiếu nữ trẻ trung tuổi đôi mươi. Bà lấy tên là Mạnh Lệ Quân (Hồ Băng Khanh), sống một cuộc đời mới và theo đuổi giấc mơ ca hát bấy lâu nay chôn kín.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 13, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Băng Khanh","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Đinh Quân","avatar":""},{"name":"Lâm Tử Lặc","avatar":""},{"name":"Tạ Lâm","avatar":""},{"name":"Vương Quân Hạ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["20.Once.Again","Old Grandma Teen Heart","Twenties Once Again","重返20岁"]', 1784690324389);
