INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ke-vi', 'Người Kế Vị', 'Basilisk The Ouka Ninja Scrolls', 'https://phimimg.com/upload/vod/20250923-1/f01d250ef4b2cfd339fd48c4f47b7e9b.jpg', 'https://phimimg.com/upload/vod/20250923-1/cf62b0e4d4fb00aedd23cf62cf3fa5f8.jpg', '<p>Câu chuyện diễn ra vào năm 1614. Hai gia tộc nhẫn giả, Tsubagakure của Iga và Manjidani của Kouga, chiến đấu với nhau để xác định cháu trai của Tokugawa Ieyasu liệu sẽ trở thành tướng quân tiếp theo. Cuộc cạnh tranh chết người giữa 10 ninja ưu tú từ mỗi gia tộc giải phóng mối hận thù hàng thế kỷ có nguy cơ phá hủy mọi hy vọng về hòa bình giữa họ.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Inori Minase","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Takuya Kirimoto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Basilisk: O Pergaminho Secreto dos Kouga","甲賀忍法帖","Basilisk: Los pergaminos ninja de Koga","Basilisk","Basilisk: Kouga Ninpouchou","Basilisk: Ouka Ninpouchou","バジリスク ～桜花忍法帖～","バジリスク 甲賀忍法帖","Basilisk: Kouga Ninpou Chou","Basilisk: The Ouka Ninja Scrolls","Basilisk: The Kouga Ninja Scrolls","バジリスク甲賀忍法帖"]', 1784690324389);
