INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-kien-va-chien-binh-ong', 'Người Kiến Và Chiến Binh Ong', 'Ant-Man And The Wasp', 'https://phimimg.com/upload/vod/20250919-1/f9a00d5d43980ebd93d5085c34c621ae.jpg', 'https://phimimg.com/upload/vod/20250919-1/14305fb6ae345d13a64413096d3fcd64.jpg', '<p>Sau trận nội chiến khốc liệt, Scott Lang – anh hùng Người Kiến với khả năng phóng to, thu nhỏ lại phải đối mặt với sự lựa chọn khó khăn trong cuộc sống đời thường: làm siêu anh hùng gánh vác những trách nhiệm nặng nề của thế giới hay làm một người cha có trách nhiệm. Trong lúc ấy, Scott được tiến sĩ Hank Pym và Hope Van Dyne – Chiến Binh Ong triệu tập để thực hiện một nhiệm vụ cấp bách mới. Scott sẽ phải mặc vào bộ áo Người Kiến một lần nữa và chiến đấu bên cạnh chiến binh ong để lật mở những bí ẩn trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Hannah John-Kamen","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"T.I.","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Abby Ryder Fortson","avatar":""},{"name":"Divian Ladwa","avatar":""},{"name":"Goran Kostić","avatar":""},{"name":"Rob","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8