INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thu-toi-tu-tu', 'Lời Thú Tội Tử Tù', 'The Forgiven', 'https://phimimg.com/upload/vod/20250919-1/b2c9ee087a02a5c6f4f56d957132daec.jpg', 'https://phimimg.com/upload/vod/20250919-1/37935bfab0e3e1538e10306493629528.jpg', '<p>Chế độ Apartheid chấm dứt, Tổng Giám mục Desmond Tutu được mời xem xét khoan hồng cho tên tội phạm khét tiếng Piet Blomfeld. Nhưng cuộc trò chuyện giữa họ lại dần trở thành sự thú tội và thứ tha.</p>', 'Full', 1, 'single', 'completed', 36, 2018, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Forest Whitaker","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Jeff Gum","avatar":""},{"name":"Debbie Sherman","avatar":""},{"name":"Terry Norton","avatar":""},{"name":"Dominika Jablonska","avatar":""},{"name":"Rob Gough","avatar":""},{"name":"Morné Visser","avatar":""},{"name":"Thandi Makhubele","avatar":""},{"name":"Osbert Solomons","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Robert Hobbs","avatar":""},{"name":"Nandiphile Mbeshu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Forgiven - Ohne Vergebung gibt es keine Zukunft","The Forgiven"]', 1784690324389);
