INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-he-dien-loan', 'Gã Hề Điên Loạn', 'Terrifier', 'https://phimimg.com/upload/vod/20250918-1/985fee0290194c0a410b679d3e3b4c97.jpg', 'https://phimimg.com/upload/vod/20250918-1/a1b01f358d7e51772f2dd863aa13be83.jpg', '<p>Một tên hề với biệt danh là Art đã lên kế hoạch biến ba người phụ nữ trẻ thành con mồi của mình trong đêm Halloween. Và tất cả những ai cản đường đều trở thành nạn nhân của hắn...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Howard Thornton","avatar":""},{"name":"Jenna Kanell","avatar":""},{"name":"Samantha Scaffidi","avatar":""},{"name":"Catherine Corcoran","avatar":""},{"name":"Pooya Mohseni","avatar":""},{"name":"Matt McAllister","avatar":""},{"name":"Katie Maguire","avatar":""},{"name":"Gino Cafarelli","avatar":""},{"name":"Cory DuVal","avatar":""},{"name":"Michael Leavy","avatar":""},{"name":"Xiomi","avatar":""},{"name":"Erick Zamora","avatar":""},{"name":"Clifton Dunn","avatar":""},{"name":"Julie Asriyan","avatar":""},{"name":"Margaret Reed","avatar":""},{"name":"Alan Hasnas","avatar":""},{"name":"Jason Leavy","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Terrifier - Ein wirklich böser Clown","رعب انگیز","مرعب","מפחיד 1","テリファー","テリファー：2016","Жахаючий","Той, що жахає","Ужасяващ","อีหนูกูจะฆ่ามึง","Terrifier 1","Terrifier","Terrifer"]', 1784690324389);
