INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-peter', 'Thỏ Peter', 'Peter Rabbit', 'https://phimimg.com/upload/vod/20250526-1/caf55c872aed4648c6251a3354f8a583.jpg', 'https://phimimg.com/upload/vod/20250526-1/70bff1d5efd725ae19fa8420ba0e0d21.jpg', '<p>Khi khu đất mà chú thỏ Peter nghĩ là thuộc về mình bị tay chủ vườn Mc Gregor chiếm đoạt, chú và đồng bọn đã phát động cuộc chiến vừa khốc liệt vừa hài hước chống lại gã nhân loại khó tính. Không còn gói gọn ở vùng quê, chiến tranh thậm chí lan tới London phồn hoa đô hội. Thỏ Peter láu lỉnh và Mc Gregor thông minh, ai sẽ giành phần thắng cuối cùng đây? Peter Rabbit được chuyển thể từ bộ truyện thiếu nhi kinh điển “The tale of Peter Rabbit” của nhà văn Beatrix Potter, kể về một chú thỏ cứng đầu cố gắng lẻn vào vườn rau của bác nông dân. Giờ đây, câu chuyện cổ sẽ được thổi bùng hơi thở hiện đại và đem đến cho người xem những trải nghiệm hoàn toàn mới.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2018, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"James Corden","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Daisy Ridley","avatar":""},{"name":"Colin Moody","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Felix Williamson","avatar":""},{"name":"Sia","avatar":""},{"name":"Fayssal Bazzi","avatar":""},{"name":"Ewen Leslie","avatar":""},{"name":"Christian Gazal","avatar":""},{"name":"Rachel Ward","avatar":""},{"name":"Bryan Brown","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Will Re","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cb