INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ac-doi-dau-2', 'Thiện Ác Đối Đầu 2', 'The Equalizer 2', 'https://phimimg.com/upload/vod/20250915-1/c224dfca4edd538a19d0c32a2e618564.jpg', 'https://phimimg.com/upload/vod/20250915-1/2923e1f663aa81cc2c69f983b57df7ca.jpg', '<p>Thiện Ác Đối Đầu 2 là một bộ phim hành động cực kỳ gây cấn và kịch tính với sự tham gia diễn xuất trở lại của diễn viên gạo cội Denzel Washington. Trong phim, cựu đặc vụ CIA tiếp tục trở thành “người hùng thầm lặng” truy tìm công lý đặc biệt càng quyết liệt hơn sau cái chết của người bạn thân Susan.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Ashton Sanders","avatar":""},{"name":"Orson Bean","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Jonathan Scarfe","avatar":""},{"name":"Sakina Jaffrey","avatar":""},{"name":"Kazy Tauginas","avatar":""},{"name":"Garrett Golden","avatar":""},{"name":"Adam Karst","avatar":""},{"name":"Alican Barlas","avatar":""},{"name":"Rhys Olivia Cote","avatar":""},{"name":"Tamara Hickey","avatar":""},{"name":"Ken Baltin","avatar":""},{"name":"Colin Allen","avatar":""},{"name":"Antoine de Lartigu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Equalizer 2: senza perdono","The Equalizer 2: A Vingança","The Equalizer II","El Justiciero 2","The Equalizer 2 (El protector 2)","イコライザー2：2018","มัจจุราชไร้เงา 2","م