INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-sieu-anh-hung-3-cuoc-chien-vo-cuc', 'Biệt Đội Siêu Anh Hùng 3: Cuộc Chiến Vô Cực', 'Avengers: Infinity War', 'https://phimimg.com/upload/vod/20250517-1/ce91513c3f6e12457edea803bdd583d3.jpg', 'https://phimimg.com/upload/vod/20250517-1/ea70303d55b86c6badee2a80b839a739.jpg', '<p>Sau chuyến hành trình độc nhất vô nhị không ngừng mở rộng và phát triển vụ trũ điện ảnh Marvel, bộ phim Avengers: Cuộc Chiến Vô Cực sẽ mang đến màn ảnh trận chiến cuối cùng khốc liệt nhất mọi thời đại. Biệt đội Avengers và các đồng minh siêu anh hùng của họ phải chấp nhận hy sinh tất cả để có thể chống lại kẻ thù hùng mạnh Thanos trước tham vọng hủy diệt toàn bộ vũ trụ của hắn.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Chadwick Boseman","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Seb","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Avengers: In