INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-tuoi-thanh-xuan-phan-1', 'Hội Chứng Tuổi Thanh Xuân (Phần 1)', 'Rascal Does Not Dream Of Bunny Girl Senpai', 'https://phimimg.com/upload/vod/20250909-1/a259569899cd43a2be24109783988b3e.jpg', 'https://phimimg.com/upload/vod/20250909-1/3951696db0e23024a231d4c6ff0bffc5.jpg', '<p>Hội chứng tuổi thanh xuân — một hội chứng được đồn đại, bí ẩn ảnh hưởng đến những người trong giai đoạn tuổi dậy thì. Điển hình, một cô gái trong hình dạng con thỏ xuất hiện trước mặt Sakuta Azusagawa. Danh tính thực sự của cô gái đó chính là Mai Sakurajima, một học sinh nổi tiếng. đàn chị trong trường Cao Trung. Trong quá trình tìm hiểu bí ẩn đằng sau hội chứng này, Sakuta đã bắt đầu nhận ra cảm xúc của mình đối với Mai và câu chuyện bắt đầu từ đó...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Aya Yamane","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Reina Ueda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青春期笨蛋不做兔女郎学姐的梦","青春猪头少年不会梦到兔女郎学姐","青春期笨蛋不会梦到兔女郎学姐","青春豬頭少年不會夢到兔女郎學姊","