INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-ma-so', 'Ác Quỷ Ma Sơ', 'The Nun', 'https://phimimg.com/upload/vod/20250907-1/5c9fc3a58d750ad69cee44b6b5c4db52.jpg', 'https://phimimg.com/upload/vod/20250907-1/f952ae8c631b98e6ca67b7146d020823.jpg', '<p>Bộ phim lấy bối cảnh vào năm 1952 tại Romania, hai nữ tu Công giáo La Mã sống tại Tu viện Carța đi vào một đường hầm tăm tối, họ cầm theo một chiếc chìa khóa với mục đích lấy lại một di tích Thiên Chúa giáo cổ đại, họ đã bị tấn công bởi một thế lực vô hình. Nữ tu Victoria may mắn sống sót đã cầm theo chiếc chìa khóa và chạy trốn khỏi kẻ tấn công, đó là một con ác quỷ xuất hiện với hình dạng một nữ tu, sau đó sơ Victoria đã tự treo cổ mình khi trong tay vẫn còn cầm chặt chiếc chìa khóa. Thi thể của cô được phát hiện bởi Frenchie, một người Pháp gốc Canada sinh sống tại Romania, anh là một dân làng chở vật tư cho các nữ tu tại tu viện Carta...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taissa Farmiga","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Bonnie Aarons","avatar":""},{"name":"Jonas Bloquet","avatar":""},{"name":"Ingrid Bisu","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Charlotte Hope","avatar":""},{"name":"Sandra Teles","avatar":""},{"name":"Maria Obretin","avatar":""},{"name":"August Maturo","avatar":""},{"name":"Jack Falk","avatar":""},{"name":"Lynnette Gaza","avatar":""},{"name":"Ani Sava","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Gabrielle Downey","avatar":""},{"name":"David Ho","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"3