INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dao-to-su', 'Ma Đạo Tổ Sư', 'The Founder of Diabolism', 'https://phimimg.com/upload/vod/20250903-1/bc057d44e9fdedb430c1eadc0e3c30a8.jpg', 'https://phimimg.com/upload/vod/20250903-1/9493b2d6c132b1b5d810aded2fecd4ad.jpg', '<p>Đời trước, thanh danh của Ngụy Vô Tiện vô cùng thối nát, bị người đời phỉ báng.

Ôn thị ngang ngược, tội ác tảy trời khiến sinh linh đồ thán. Thế gia nghĩa sĩ trên giang hồ phát động “ Xạ Nhật Chi Chinh ”, vì trượng nghĩa mà hợp lực thảo phạt Ôn gia. “Di Lăng Lão Tổ” Nguy Vô Tiện mặc dù lập được công lớn, nhưng lại bị kẻ gian ghen ghét hãm hại, khiến hẳn bị vạn người thóa mạ. Sau 30 năm, Nguy Vô Tiện lần nữa xuất hiện, cùng Cô Tô Lam Thị Lam Vong Cơ, Vân Mộng Giang Thị Giang Trừng tương ngộ. Từ đây bí ẩn trong Giang hồ cũng dần được hé lộ.</p>', 'Hoàn Tất (35/35)', 35, 'hoathinh', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Jiang Bian","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Titus Jin","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"Shao Tong","avatar":""},{"name":"Chen Zhangtaikang","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Liu Sanmu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Mo Dao Zu Shi","魔道祖师 前尘篇","魔道祖师 羡云篇","The Founder of Diabolism","魔道祖师 完结篇","MDZS","Gran maestro del cultivo demoníaco","Madou soshi","魔道祖師 完結編","魔道祖師","魔道祖師 前塵編","魔道祖師 羨雲編","마도조사","Магистр дьявольского культа","Великий майстер з культивування демонів","Засновник діаболізму","Grandmaster of Demonic Cultivation","The Master of Diabolism","Ma Đạo Tổ Sư","魔道祖师"]', 1784690324389);
