INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-nhen-vu-tru-moi', 'Người Nhện: Vũ Trụ Mới', 'Spider-Man: Into The Spider-Verse', 'người nhện: vũ trụ mới spider-man: into the spider-verse shameik moore jake johnson hailee steinfeld mahershala ali brian tyree henry lily tomlin luna lauren velez zoë kravitz john mulaney kimiko glenn nicolas cage kathryn hahn liev schreiber chris pine natalie morales edwin h. bravo oscar isaac animated spider-man ספיידרמן: מימד העכביש spider man : nouvelle génération سبايدر مان: في عالم العنكبوت een nieuw universum 뉴스파 pókember: irány a pókverzum! ობობა-კაცი: ობობის სამყაროში სპაიდერმენი: ობობის სამყაროში homem aranha no aranhaverso spider-man uniwersum spider-man: new universe người nhện: vũ trụ mới スパイダーマン：スパイダーバース：2018 homem-aranha no aranhaverso spider-man: novi svet 蜘蛛侠1：平行宇宙 (迈尔斯·莫拉斯) اؤرومجک آدام: هؤرومچک عالمینده 스파이더맨: 인투 더 스파이더버스 žmogus voras: į naują visatą homem-aranha: no aranhaverso aranhaverso spider-man: een nieuw universum فیلمێکی ساڵی ٢٠١٨یە spider-man: into the spider-verse', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-am-sat', 'Kẻ Ám Sát', 'Accident Man', 'https://phimimg.com/upload/vod/20250823-1/443ce63113281bd43892a44a879c76a3.jpg', 'https://phimimg.com/upload/vod/20250823-1/a3bed84710a73abc6b16d0752ed5eab0.jpg', '<p>Mike Fallon là một sát thủ chuyên nghiệp máu lạnh. Hắn luôn làm khách hàng của mình hài lòng và rất giỏi đánh lạc hướng điều tra của cảnh sát. Hắn là tay sát thủ số một trong số những kẻ chuyên ám sát thuê. Tuy nhiên khi người thân của hắn bị lôi vào cuộc thì mọi chuyện đã đi theo một hướng khác…</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"Ray Park","avatar":""},{"name":"Amy Johnston","avatar":""},{"name":"David Paymer","avatar":""},{"name":"Perry Benson","avatar":""},{"name":"Nick Moran","avatar":""},{"name":"Ross O''Hennessy","avatar":""},{"name":"Tim Man","avatar":""},{"name":"Leon Finnan","avatar":""},{"name":"Brooke Johnston","avatar":""},{"name":"Stephen Donald","avatar":""},{"name":"Ravi Aujla","avatar":""},{"name":"Stu Small","avatar":""},{"name":"Aaron Thomas Ward","avatar":""},{"name":"Brittany","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Нещастният случай","Asesinatos accidentales","意外殺手","Нещасний випадок","Accident Man"]', 1784690324389);
