INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deadpool-2', 'Deadpool 2', 'Deadpool 2', 'https://phimimg.com/upload/vod/20250821-1/a851456512f6c0df30a79e35ae0b756b.jpg', 'https://phimimg.com/upload/vod/20250821-1/dffaea6f42fda54f0cd5f74c548c90ae.jpg', '<p>Trong phần 2 Deadpool sẽ đối đầu với sát nhân Cable, một kẻ đến từ tương lai với âm mưu giết hại một đứa bé – Người mà theo hắn sau này sẽ trở thành một dị nhân đầy quyền năng. Với nỗ lực đảm bảo sự an toàn cho đứa bé, Deadpool sẽ nhận được sự giúp đỡ từ cả những người bạn mới và cũ, và đặc biệt là các thành viên từ một đội quân mới thành lập có tên X-Force</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Julian Dennison","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Leslie Uggams","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Brianna Hildebrand","avatar":""},{"name":"Jack Kesy","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Shioli Kutsuna","avatar":""},{"name":"Stefan Kapičić","avatar":""},{"name":"Randal Reeder","avatar":""},{"name":"Nikolai Witschl","avatar":""},{"name":"Thayr Harris","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Lewi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Deadpool: Number Two","เดดพูล 2","Deadpool 2: Super Duper Cut","死侍2","Quái Nhân Deadpool 2","死侍2