INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-baki-phan-1', 'Võ Sĩ Baki (Phần 1)', 'BAKI (Season 1)', 'https://phimimg.com/upload/vod/20250819-1/550bb61ea7e79c2a1705c29b0d248aa5.jpg', 'https://phimimg.com/upload/vod/20250819-1/cea5a1b7db3dfa820d07664e74fcbdba.jpg', '<p>5 tử tù khét tiếng vượt ngục, kéo đến Nhật để tìm thất bại thực sự. Họ lần lượt đối đầu với Baki và các cao thủ như Doppo, Retsu, Hanayama... Sau chuỗi trận chiến đẫm máu, từng kẻ bị đánh bại. Baki mạnh mẽ hơn cả về võ thuật lẫn tinh thần, chuẩn bị cho thử thách lớn hơn.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 12, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Issei Futamata","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Yoshihisa Kawahara","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Mugihito","avatar":""},{"name":"Takayuki Sugo","avatar":""},{"name":"Bin Shimada","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Toru Furuya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["刃牙 大擂台赛的传说","刃牙 死囚篇","Baki (2018)","Μπάκι","באקי המתאבק החדש","BAKI","Baki: Dai Raitaisai-hen","باكي المحارب","Baki: The Great Raitai Tournament Saga","バキ"]', 17846903243