INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-si-baki-phan-1', 'Võ Sĩ Baki (Phần 1)', 'BAKI (Season 1)', 'võ sĩ baki (phần 1) baki (season 1) nobunaga shimazaki kenjiro tsuda takehito koyasu issei futamata banjo ginga chafurin akio otsuka yoshihisa kawahara sora amamiya mugihito takayuki sugo bin shimada rikiya koyama takuya eguchi toru furuya 刃牙 大擂台赛的传说 刃牙 死囚篇 baki (2018) μπάκι באקי המתאבק החדש baki baki: dai raitaisai-hen باكي المحارب baki: the great raitai tournament saga バキ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('family-guy-phan-17', 'Family Guy (Phần 17)', 'Family Guy (Season 17)', 'https://phimimg.com/upload/vod/20250817-1/6ba88c5ba77d71c1f5efb94b164c86ee.jpg', 'https://phimimg.com/upload/vod/20250817-1/d0d4932839c43485d4ac5b70e513eec7.jpg', '<p><span style="text-wrap-mode: wrap;">Bộ phim xoay quanh những cuộc phiêu lưu và hoạt động thường nhật của gia đình Griffin, bao gồm trụ cột gia đình Peter Griffin, một người đàn ông béo phì trung niên ngốc nghếch và vụng về làm việc trong nhà máy bia, Lois, nội trợ kiêm giáo viên dạy piano, vốn xuất thân từ gia đình tài phiệt Pewterschmidt, Meg, một cô bé 18 tuổi thường xuyên bị bắt nạt, Chris, cậu bé 15 tuổi thừa cân và cư xử ngốc nghếch giống Peter và Stewie, một bé trai 1 tuổi thông minh nhưng tinh ranh và đôi khi nham hiểm, cư xử theo cách của một người trưởng thành. Sống cùng gia đình là Brian, chú chó được nhân cách hóa, với nhiều thói quen của con người như hút thuốc, uống rượu martini, mặc dù về nhiều mặt vẫn được coi là thú cưng.</span></p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth MacFarlane","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Mila Kunis","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Arif Zahir","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["გრიფინები","Keluarga Pria","مرد خانه","خانواده‌ دوست","쇼킹 패밀리","쇼킹패밀리","परिवारको केटा","Сім’янин","Ґріффіни","Family Guy"]', 1784690324389);
