INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-dao-hoang-hau', 'Phù Dao Hoàng Hậu', 'Legend Of Fuyao', 'https://phimimg.com/upload/vod/20250808-1/f623d416e48cb4568afd02ec39983dda.jpg', 'https://phimimg.com/upload/vod/20250808-1/7798358f07f69194f0b93c007090e8a7.jpg', '<p>Bộ phim&nbsp;được chuyển thể từ tác phẩm kinh điển cùng tên, nội dung xoay quanh Mạnh Phù Dao (Dương Mịch) - một cô gái kiên cường, túc trí đa mưu vì muốn thu thập “mật lệnh” của Ngũ Châu mà phải trải qua muôn vàn hiểm nguy. Trên đường lang bạt, nàng gặp gỡ Trưởng Tôn Vô Cực (Nguyễn Kinh Thiên) và được chàng hết lòng giúp đỡ. Trải qua nhiều thử thách, hai người mới nhận ra tấm chân tình của đối phương, rồi cùng nắm tay dẹp loạn giặc phương Nam xâm lược, đoạt lại vương quyền.</p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 10, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Nguyễn Kinh Thiên","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Cao Vỹ Quang","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Legend of Fu Yao","扶摇"]', 1784690324389);
