INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-bon-chan', 'Ngôi Sao Bốn Chân', 'A Dog And Pony Show', 'https://phimimg.com/upload/vod/20250808-1/f473f3113c4cddbdf8e9ea43fde9c3a3.jpg', 'https://phimimg.com/upload/vod/20250808-1/1d8efa430911ddb18229988e7b42b9c8.jpg', '<p>Bị gánh xiếc bỏ rơi, chú chó biểu diễn được một cậu bé nhận nuôi. Chưa ở bên bạn mới bao lâu, chú đã rơi vào tầm ngắm của gánh xiếc khác. Từ đó mở ra hành trình gay cấn, hài hước và đầy cảm xúc.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mira Sorvino","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Ralph Macchio","avatar":""},{"name":"James Russo","avatar":""},{"name":"Patrick Muldoon","avatar":""},{"name":"Christopher Backus","avatar":""},{"name":"Valente Rodriguez","avatar":""},{"name":"Malcolm Danare","avatar":""},{"name":"Jacob Young","avatar":""},{"name":"Aris Alvarado","avatar":""},{"name":"Daniel Luján","avatar":""},{"name":"Demetrius Navarro","avatar":""},{"name":"Madeleine Falk","avatar":""},{"name":"Trish Cook","avatar":""},{"name":"Kimberly Woods","avatar":""},{"name":"Fernando Carrillo","avatar":""},{"name":"Laur","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Dog & Pony Show","A Dog and Pony Show"]', 1784690324389);
