INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gang-to-tai-xuat', 'Găng Tơ Tái Xuất', 'Unstoppable', 'https://phimimg.com/upload/vod/20250804-1/0c13127e680aa4e53652e51347ea54a0.jpg', 'https://phimimg.com/upload/vod/20250804-1/6917ce92e3edd9efdc48593470fb60f9.jpg', '<p>Găng Tơ Tái Xuất câu chuyện bắt đầu từ Dong-Chul và Ji-Soo là một cặp vợ chồng hạnh phúc. Dong-Chul đã từng là một tay xã hội đen khét tiếng, nhưng anh ta đã thay đổi cách thức của mình. Một ngày nọ, Dong-Chul đến nhà để tìm nhà của anh ấy trong tình trạng hỗn loạn và vợ anh ấy mất tích. Dong-Chul sau đó nhận được một cuộc điện thoại từ một người đề nghị trả tiền cho anh ta để từ bỏ vợ. Dong-Chul thề sẽ cứu vợ.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Don Lee","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Kim Seung-o","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Lee Seong-woo","avatar":""},{"name":"Bae Noo-ri","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Cho Han-na","avatar":""},{"name":"Yoo Ah-jin","avatar":""},{"name":"Lee Dong-jin","avatar":""},{"name":"Park Kwang-jae","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Bae Jin-ah","avatar":""},{"name":"Lim Il-gyu","avatar":""},{"name":"Jeon Ik-ryoung","avatar":""},{"name":"Hong Yi-joo","avatar":""},{"name":"Kim","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["