INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-quyet-chia-khoa-quy-du', 'Quỷ Quyệt: Chìa Khóa Quỷ Dữ', 'Insidious: The Last Key', 'https://phimimg.com/upload/vod/20250731-1/9444d387b5159016ff5f62829c60a524.jpg', 'https://phimimg.com/upload/vod/20250731-1/5653d1f4748a2f462b8c830d3686a88b.jpg', '<p>Jason Blum, Oren Peli và James Wan đóng vai trò là các nhà sản xuất của phim. Đây là phần phim thứ tư của loạt phim Quỷ quyệt, lấy bối cảnh sau kết thúc của Quỷ quyệt 3 và trước hai phần phim đầu tiên. Với sự tham gia diễn xuất của Lin Shaye, Angus Sampson, Leigh Whannell, Spencer Locke, Caitlin Gerard và Bruce Davison, nội dung phim xoay quanh câu chuyện về nhà tâm linh Elise Rainier khi bà quay trở lại ngôi nhà cũ của mình hồi nhỏ để tìm lại con quỷ đã ám ảnh tuổi thơ của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Lin Shaye","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Kirk Acevedo","avatar":""},{"name":"Caitlin Gerard","avatar":""},{"name":"Spencer Locke","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Tessa Ferrer","avatar":""},{"name":"Aleque Reid","avatar":""},{"name":"Ava Kolker","avatar":""},{"name":"Pierce Pope","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Javier Botet","avatar":""},{"name":"Marcus Henderson","avatar":""},{"name":"Amanda Jaros","avatar":""},{"name":"Judith Drake","avatar":""},{"name":"Hana Hayes","avatar":""},{"name":"Thomas Robie","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Insidiou