INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quy-quyet-chia-khoa-quy-du', 'Quỷ Quyệt: Chìa Khóa Quỷ Dữ', 'Insidious: The Last Key', 'quỷ quyệt: chìa khóa quỷ dữ insidious: the last key lin shaye leigh whannell angus sampson kirk acevedo caitlin gerard spencer locke josh stewart tessa ferrer aleque reid ava kolker pierce pope bruce davison javier botet marcus henderson amanda jaros judith drake hana hayes thomas robie j insidious: chapter 4 潜伏：最后的钥匙 la noche del demonio: la última llave insidious 4: the last key insidious la última llave insidious : la dernière clé הרוע שבפנים 4: המפתח האחרון วิญญาณตามติด: กุญแจผีบอก วิญญาณตามติด 4 อินซิเดียส 4 quỷ quyệt 4: chìa khóa quỷ dữ insidious la dernière clé insidious 4 इंसिडियस चैप्टर ४: अंतिम कड़ी insidious: the last key', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tia-chop-phan-5', 'Người Hùng Tia Chớp (Phần 5)', 'The Flash (Season 5)', 'https://phimimg.com/upload/vod/20250729-1/ce26f13b92c6397f3f42e940d33515b2.jpg', 'https://phimimg.com/upload/vod/20250729-1/e1d218103ac53d3e12c9753c0ab74ad4.jpg', '<p>Phim dựa theo một nhân vật của DC Comics, trong 1 thí nghiệm tại Starling City, anh chàng Barry đã vô tình bị ảnh hưởng bởi vụ nổ trong thí nghiệm khiến anh hôm mê bất tỉnh nhiều ngày trong bệnh viện. Khi tỉnh dậy, anh ta đã phát hiện ra rằng mình có khả năng đặc biệt đó là tăng tốc độ cơ thể và di chuyển siêu nhanh. Kể từ đây, huyền thoại về người anh hùng Flash bắt đầu.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Grant Gustin","avatar":""},{"name":"Candice Patton","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Danielle Nicolet","avatar":""},{"name":"Kayla Compton","avatar":""},{"name":"Brandon McKnight","avatar":""},{"name":"Jon Cor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["闪电侠 (格兰特·古斯汀)","The Flash (2014)","The Flash 2014","פלאש","플래시","The Flash"]', 1784690324389);
