INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-trong-tam-bao', 'Vụ Cướp Trong Tâm Bão', 'The Hurricane Heist', 'https://phimimg.com/upload/vod/20250725-1/69f2738df0573b22cb2e9d8880684c06.jpg', 'https://phimimg.com/upload/vod/20250725-1/dbba543ebc1b47d55e0205f3e3e269af.jpg', '<p>Một nhóm người đã lên kế hoạch cướp 600 triệu USD từ một cơ sở đúc tiền ở vùng duyên hải Mỹ trong thời gian cơn bão cấp 5 đổ bộ. Khi vụ việc xảy ra, cả thị trấn biển chỉ còn một nhà khí tượng học, cô gái Marine và một đại diện của kho bạc ở lại. Họ không chỉ phải cùng nhau chống chọi với cơn bão mà còn phải đối mặt với vụ trộm thế kỷ của những tin tặc vô cùng khôn ngoan.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Toby Kebbell","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Ryan Kwanten","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Melissa Bolona","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Christian Contreras","avatar":""},{"name":"Jimmy Walker","avatar":""},{"name":"Mark Basnight","avatar":""},{"name":"Erik Rondell","avatar":""},{"name":"Mark Rhino Smith","avatar":""},{"name":"Jamie Andrew Cutler","avatar":""},{"name":"Ed Birch","avatar":""},{"name":"Moyo Akandé","avatar":""},{"name":"James Barriscale","avatar":""},{"name":"Keith D. Evans","avatar":""},{"name":"Natacha Kara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Category 5","ปล้นเร็วฝ่าโคตรพายุ","Categoria 5","El gran huracán categoría 5"