INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-quen-xa-la', 'Người Quen Xa Lạ', 'Intimate Strangers', 'https://phimimg.com/upload/vod/20250725-1/a0bcf76b9cf3a43d98a4ddb4005aadc0.jpg', 'https://phimimg.com/upload/vod/20250725-1/14bd93d329fc15511cbe77077f7be47c.jpg', '<p>Một nhóm bạn thân thiết với nhau đã 30 năm. Một đêm nọ, họ tụ họp tại một buổi tiệc tân gia ấm cúng và cùng tán gẫu. Những câu chuyện phiếm, những kỉ niệm năm xưa ùa về khiến họ vô cùng vui vẻ. Trong không khí phấn khích đó, một người trong nhóm đã đề nghị các “tri kỉ” hãy đặt điện thoại lên bàn để bất kì cuộc điện thoại, tin nhắn nào đổ chuông tới cũng phải chia sẻ cùng nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Hai-jin","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Lee Seo-jin","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Kim Ji-soo","avatar":""},{"name":"Song Ha-yoon","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Ji Woo","avatar":""},{"name":"Choi Yu-hwa","avatar":""},{"name":"Lee Soon-jae","avatar":""},{"name":"Lee Do-gyeong","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Cho Jung-seok","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Kim Min-kyo","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Choi Sun-ja","avatar":""},{"name":"Jeong Min-gyu","avatar":""},{"name":"Jung Ji-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["完美的他人","完璧な他人","Intimate Strangers","完璧な他人：2018