INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trum-ma-tuy-mexico-phan-1', 'Trùm Ma Túy: Mexico (Phần 1)', 'Narcos: Mexico (Season 1)', 'trùm ma túy: mexico (phần 1) narcos: mexico (season 1) scoot mcnairy josé maría yázpik alejandro edda luis gerardo méndez matt letscher gorka lasaosa alfonso dosal mayra hermosillo luisa rubino manuel masalva kristen lee gutoskie bobby soto lorenzo ferro josé zúñiga alejandro furth alberto guer narcos: μεξικό 나르코스 멕시코 барыги: мексика narcos: meksika narcos: mexico', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-tan-ky-tan-co-may-thoi-gian', 'Tầm Tần Ký (Tân Cỗ Máy Thời Gian)', 'A Step Into The Past', 'https://phimimg.com/upload/vod/20250721-1/6651d946c96bfe041524f0b516b32bca.jpg', 'https://phimimg.com/upload/vod/20250721-1/3954ce35225c9d3017aeffd5b800d4e4.jpg', '<p>So với nguyên tác Tầm Tần ký và bộ phim kinh điển Cỗ máy thời gian của TVB thì tình tiết của phiên bản này có sự thay đổi đáng kể. Trong phim, Hạng Thiếu Long (Trần Tường) vì cứu Triển Phong (Ngô Kỳ Long) đã một mình lái phi thuyền vũ trụ đi chấp hành nhiệm vụ, không ngờ gặp phải cơn bão tinh thạch nên rơi xuống địa cầu lạc vào thời đại nhà Tần. Hạng Thiếu Long được xem là “Tân Thánh Nhân”, gây được sự chú ý với người cổ đại, nhưng cũng phải đối mặt với những cạm bẫy hiểm nguy đến từ thế lực đen tối. Không chỉ bị cuốn vào các sự kiện lớn trong lịch sử như cuộc phân tranh thời chiến quốc, thống nhất lục quốc, cùng Doanh Chính (Châu Văn Đạo) trải qua những cuộc thử thách sinh tử và những ân oán tình thù. Ngoài ra anh chàng còn có mối tình say đắm với Tinh Vân (Quách Hiểu Đình) cùng mối quan hệ phức tạp với Triệu Bàng và Liên Tấn...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2018, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Vũ","avatar":""},{"name":"Hạ Nam","avatar":""},{"name":"Triệu Đỉnh Chấn","avatar":""},{"name":"Ngưu Tử Phan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["심진기 2018","A Step Into The Past","寻秦记"]', 1784690324389);
