INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khung-long-vuong-quoc-sup-do', 'Thế Giới Khủng Long: Vương Quốc Sụp Đổ', 'Jurassic World: Fallen Kingdom', 'thế giới khủng long: vương quốc sụp đổ jurassic world: fallen kingdom chris pratt bryce dallas howard rafe spall justice smith daniella pineda james cromwell toby jones ted levine jeff goldblum bd wong geraldine chaplin isabella sermon robert emms peter jason kevin layne john schwab sam redford charlie rawe jurassic world 2 jurassic world ii - il regno distrutto 侏羅紀世界2：迷失國度 jurassic park v: jurassic world - fallen kingdom 侏罗纪世界2 侏罗纪世界2：迷失国度 侏罗纪世界：迷失国度 侏羅紀世界：迷失國度 侏罗纪世界2：失落王国 jurassic world: fallen kingdom', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-xanh', 'Miền Xanh', 'Green Land', 'https://phimimg.com/upload/vod/20250715-1/0facf3ae526ef389e4d2fa61f6456ca8.jpg', 'https://phimimg.com/upload/vod/20250715-1/9062378d3fbcc9a065f28998fdcea36f.jpg', '<p>Bộ phim “Miền Xanh” kể về Hoàng Vy - một nữ sinh xinh đẹp từ Sài Gòn chuyển về một ngôi trường vùng quê học tập. Sự xuất hiện của Hoàng Vy làm xáo động cuộc sống vốn bình lặng của tập thể học sinh lớp 12A1. Về quê, ban đầu Vy sống khép kín. Ngoài chuyện đi học, cô thường đến Long Sơn, một ngôi chùa lớn nổi tiếng cổ kính trong làng. Vy có mối quan tâm đặc biệt với sư Huệ Đức - trụ trì của chùa Long Sơn - người được người dân trong vùng hết mực kính trọng và biết ơn. Những ngày học sau đó, Vy tiếp xúc với Trung và nhóm bạn trong tập thể lớp 12A1 trong một môi trường chân chất, hoang sơ, khác lạ hoàn toàn với nơi cô từng sống. Sự hồn nhiên, chân chất từ Trung và đám bạn quê, không khí yên bình thanh thản vùng nông thôn; sự ấm áp, thanh tịnh của sư Huệ Đức… tất cả những điều đó đã khiến cho cuộc sống khép kín của cô dần được thay thế và nhanh chóng tìm lại sự cân bằng, xoa dịu nỗi đau trong tâm hồn mà Hoàng Vy tưởng chừng không bao giờ vượt qua được.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quang Thái","avatar":""},{"name":"Yến Chi","avatar":""},{"name":"Thanh Nha","avatar":""},{"name":"Nhật Trường","avatar":""},{"name":"Thanh Tân","avatar":""},{"name":"Lâm Thắng","avatar":""},{"name":"Xuân Hiệp","avatar":""},{"name":"Kim Tính","avatar":""},{"name":"Nguyễn Sơn","avatar":""},{"name":"Trần Thuận","avatar":""},{"name":"Kiều Khanh","avatar":""},{"name":"Đinh Hữu Tài","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324389);
