INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mien-xanh', 'Miền Xanh', 'Green Land', 'miền xanh green land quang thái yến chi thanh nha nhật trường thanh tân lâm thắng xuân hiệp kim tính nguyễn sơn trần thuận kiều khanh đinh hữu tài ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-sieu-bao-chua', 'Cá Mập Siêu Bạo Chúa', 'The Meg', 'https://phimimg.com/upload/vod/20250628-1/bd4e7445a1f5c2e243ae4ea7b37265bd.jpg', 'https://phimimg.com/upload/vod/20250628-1/8cb36af401b2de4683fb20fb6cdbec94.jpg', '<p>Một chiếc tàu ngầm dưới lòng biển sâu bị tấn công bởi một sinh vật khổng lồ và đầy nguy hiểm được cho là đã tuyệt chủng từ lâu. Hậu quả là khiến cả đoàn người bị mắc kẹt dưới đáy Thái Bình Dương và bị đe dọa tính mạng. Thời gian trôi qua, một đội chuyên gia thợ lặn mà đứng đầu là Jonas Taylor, nhà đại dương học người Trung Quốc, cháu gái ông là Suyin đã đến để giải cứu đoàn tàu. Nhưng không ai ngờ rằng, kẻ thù của họ lại chính là kẻ săn mồi to lớn và vĩ đại nhất lịch sử – một con cá mập thời tiền sử dài 75 foot thường được biết đến với cái tên Megalodon.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jason Statham","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Jessica McNamee","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Shuya Sophia Cai","avatar":""},{"name":"Page Kennedy","avatar":""},{"name":"Robert Taylor","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Mai Hongmei","avatar":""},{"name":"Wei Yi","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Rob Kipa-Williams","avatar":""},{"name":"Tawanda Manyimo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c14