INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-map-sieu-bao-chua', 'Cá Mập Siêu Bạo Chúa', 'The Meg', 'cá mập siêu bạo chúa the meg jason statham li bingbing rainn wilson cliff curtis ruby rose jessica mcnamee masi oka winston chao shuya sophia cai page kennedy robert taylor ólafur darri ólafsson mai hongmei wei yi vithaya pansringarm rob kipa-williams tawanda manyimo meg: tubarão gigante mégalodon megatubarão [the meg] (2018) megatubarão - the meg (2018) megalodón เม็ก โคตรหลามพันล้านปี meg 1 megalodon cá mập siêu bạo chúa the meg', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-lan-truyen', 'Minh Lan Truyện', 'The Story Of Ming Lan', 'https://phimimg.com/upload/vod/20250625-1/79bc37374da22baa4ebb6310ee1f49be.jpg', 'https://phimimg.com/upload/vod/20250625-1/2b5fb44c09e631bc2320300e2daa152e.jpg', '<p>Minh Lan Truyện xoay quanh chuyện tình cảm của Thịnh Minh Lan (Triệu Lệ Dĩnh), thiếu nữ con nhà quan thời Bắc Tống cùng với hai chàng trai Cố Đình Diệp (Phùng Thiệu Phong) và Tề Hành (Chu Nhất Long). Là con thứ sáu trong phủ họ Thịnh, Minh Lan xinh đẹp và thông tuệ hơn người nhưng sớm mồ côi mẹ. Cô luôn sống trong cảnh mẹ cả không thương, tỷ muội ganh đua. Cô phải nhẫn nhục trưởng thành trong nghịch cảnh để báo thù cho mẹ ruột. Ngoài ra, phim Minh Lan Truyện cũng cho thấy mối quan hệ vợ chồng từ oan gia đối đầu, thử thách đến chân thành sống chết có nhau của Minh Lan và chàng công tử Cố Đình Diệp.</p>', 'Hoàn Tất (73/73)', 73, 'series', 'completed', 20, 2018, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Chu Nhất Long","avatar":""},{"name":"Thi Thi","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Vương Nhân Quân","avatar":""},{"name":"Tào Thúy Phân","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Cao Lộ","avatar":""},{"name":"Vương Nhất Nam","avatar":""},{"name":"Lý Y Hiểu","avatar":""},{"name":"Vương Hạc Nhuận","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee6