INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('minh-lan-truyen', 'Minh Lan Truyện', 'The Story Of Ming Lan', 'minh lan truyện the story of ming lan triệu lệ dĩnh phùng thiệu phong chu nhất long thi thi trương giai ninh vương nhân quân tào thúy phân lưu quân lưu lâm cao lộ vương nhất nam lý y hiểu vương hạc nhuận 知否 知否知否 明兰传 知否知否应是绿肥红瘦 지부지부응시녹비홍수 the story of minglan do you know? it ought to be a wilting flower amongst the lush leaves', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-thinh-truong-ca', 'Thiên Thịnh Trường Ca', 'The Rise Of Phoenixes', 'https://phimimg.com/upload/vod/20250625-1/e3d864a070ebfd903c9490f665ac1428.jpg', 'https://phimimg.com/upload/vod/20250625-1/409c81e15782cc476bf64daef23e4a1e.jpg', '<p>Là bộ phim truyền hình cổ trang Trung Quốc, dựa trên tiểu thuyết Hoàng Quyền của tác giả Thiên Hạ Quy Nguyên, với sự tham gia của hai diễn viên chính Trần Khôn và Nghê Ni. Bộ phim xoay quanh chuyện yêu hận tình thù giữa Hoàng tử đương triều Ninh Dịch và Công chúa tiền triều Phượng Tri Vi giữa lúc quyền mưu đấu đá, &quot;Cờ một ván quyền mưu thiên hạ, bạc một canh yêu hận thăng trầm&quot;.</p>', 'Hoàn Tất (70/70)', 70, 'series', 'completed', 13, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Khôn","avatar":""},{"name":"Nghê Ni","avatar":""},{"name":"Triệu Lập Tân","avatar":""},{"name":"Nghê Đại Hồng","avatar":""},{"name":"Viên Hoằng","avatar":""},{"name":"Vương Âu","avatar":""},{"name":"Bạch Kính Đình","avatar":""},{"name":"Trương Hiểu Thần","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""},{"name":"Vu Minh Gia","avatar":""},{"name":"Hầu Nham Tùng","avatar":""},{"name":"Hải Nhất Thiên","avatar":""},{"name":"Thị An","avatar":""},{"name":"Thiệu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["凰权·弈天下","天盛長歌","天盛长歌"]', 1784690324389);
