INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-thinh-truong-ca', 'Thiên Thịnh Trường Ca', 'The Rise Of Phoenixes', 'thiên thịnh trường ca the rise of phoenixes trần khôn nghê ni triệu lập tân nghê đại hồng viên hoằng vương âu bạch kính đình trương hiểu thần mai đình lưu mẫn đào vu minh gia hầu nham tùng hải nhất thiên thị an thiệu đồng 凰权·弈天下 天盛長歌 天盛长歌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nien-dai-cam-hong', 'Niên Đại Cam Hồng', 'Age Of Legends', 'https://phimimg.com/upload/vod/20250622-1/d77da4e88bebe1896376ad9f4db34de9.jpg', 'https://phimimg.com/upload/vod/20250622-1/e64a22f6375c110a4a183daaa6ca2b69.jpg', '<p>Lưu Tử Quang xuất thân bình dân nhưng tài giỏi, quang minh lỗi lạc, là hình ảnh tiêu biểu cho thanh niên Trung Quốc đương đại và nữ chính Hồ Dung – bông hoa của đội hình cảnh, xinh đẹp hiên ngang nhưng cũng vô cùng nóng nảy. Mặc dù cô nàng đối với Lưu Tử Quang yêu hận đan xen nhưng cả hai người họ cùng chung tín ngưỡng, tâm linh tương thông nên đến sau cùng vẫn bên nhau.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 9, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Vỹ Đình","avatar":""},{"name":"Mã Tư Thuần","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Trương Dịch","avatar":""},{"name":"Trương Dung Dung","avatar":""},{"name":"Nhiêu Tuấn","avatar":""},{"name":"Trương Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Огненные годы","橙红年代"]', 1784690324389);
