INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nien-dai-cam-hong', 'Niên Đại Cam Hồng', 'Age Of Legends', 'niên đại cam hồng age of legends trần vỹ đình mã tư thuần lưu dịch quân trương dịch trương dung dung nhiêu tuấn trương nghệ огненные годы 橙红年代', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-tham-vong', 'Lâu Đài Tham Vọng', 'SKY Castle', 'https://phimimg.com/upload/vod/20250621-1/1c294a512349338bfe8ffda934b85b8c.jpg', 'https://phimimg.com/upload/vod/20250621-1/f5e483a9c39f8b06712841afffeb3c15.jpg', '<p>Lâu Đài Tham Vọng lấy chủ đề về gia đình nhưng nó lại được khai thác ở một khía cạnh mới – đó chính là những mâu thuẫn trong cách nuôi dạy con cái với cuộc chiến vào được các trường đại học hàng đầu Hàn Quốc. Bốn người phụ nữ trong Lâu Đài Tham Vọng chính là 4 gương mặt tiêu biểu cho những người mẹ, người vợ trong xã hội. Han Seo Jin và Lee Soo Im cùng đại diện cho những người phụ nữ mạnh mẽ, vượt khó nhưng con đường mà họ hướng đến lại khác nhau. Trong khi Seo Jin cố gắng thúc ép con cái của mình học những điều bản thân cô định hướng, thuê gia sư kèm cặp thì Soo Im lại rất tôn trọng ý kiến, sở thích của con cái. Còn No Seung Hye và Jin Jin Hee có xuất thân từ gia đình giàu có nên họ cũng không quá áp đặt vào việc học hành của con trẻ, nhưng bản thân chồng của họ lại đối lập hoàn toàn, từ đó tạo nên những mâu thuẫn không thể dung hòa.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yum Jung-ah","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Lee Tae-ran","avatar":""},{"name":"Kim Seo-hyung","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Jung Jun-ho","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Kim Byung-chul","avatar":""},{"name":"Kim Bo-ra","avatar":""},{"name":"Kim Hye-yoon","avatar":""},{"name":"Lee Ji-won","avatar":""},{"name":"Kang Chan-hee","avatar":""},{"name":"Kim Dong-hee","avatar":""},{"name":"Cho Byeong-kyu","avatar":""},{"name":"Lee Hyun-jin","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Park You-na","avatar":""},{"name":"Lee Eugene","avatar":""},{"name":"Kwon Hwa-woon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["SKY Kaeseul","프린세스 메이커","스카이 캐슬","스카이캐슬","天空城堡","Princess Maker","Sky Castle","SKY 캐슬"]', 1784690324389);
