INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lau-dai-tham-vong', 'Lâu Đài Tham Vọng', 'SKY Castle', 'lâu đài tham vọng sky castle yum jung-ah yoon se-a lee tae-ran kim seo-hyung oh na-ra jung jun-ho choi won-young kim byung-chul kim bo-ra kim hye-yoon lee ji-won kang chan-hee kim dong-hee cho byeong-kyu lee hyun-jin jo jae-yun park you-na lee eugene kwon hwa-woon sky kaeseul 프린세스 메이커 스카이 캐슬 스카이캐슬 天空城堡 princess maker sky castle sky 캐슬', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khan-cap-thoat-e', 'Khẩn Cấp Thoát Ế', 'Dude''s Manual', 'https://phimimg.com/upload/vod/20250620-1/2a56d7ff85211c98899ab1bd7093e0a6.jpg', 'https://phimimg.com/upload/vod/20250620-1/800019b6183e06e901df2dc75d3c3206.jpg', '<p>Lê Đồng (do Đổng Tử Kiện thủ vai) là một chàng trai đại học điển hình: hơi ngốc nghếch, rụt rè và đặc biệt… chưa từng có bạn gái. Khi một người bạn nhờ cậu giúp đỡ để theo đuổi Cảnh Điềm (Chung Sở Hy), một cô nàng xinh đẹp nổi tiếng trong trường, Lê Đồng không ngờ rằng chính mình lại bị cuốn vào mối tình tay ba dở khóc dở cười. Trong hành trình &quot;cố vấn tình yêu&quot; này, Lê Đồng dần nhận ra tình cảm thật của mình và cũng bắt đầu thay đổi bản thân, trở nên tự tin và dám đối diện với con tim. Phim mang đến thông điệp dễ thương về tuổi trẻ, tình bạn và sự trưởng thành trong tình yêu.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Tử Kiện","avatar":""},{"name":"Chung Sở Hy","avatar":""},{"name":"Xuân Hạ","avatar":""},{"name":"Viên Phúc Phúc","avatar":""},{"name":"Cẩm Cẩm","avatar":""},{"name":"Du Khôn Nhiên","avatar":""},{"name":"Ngô Dực Dao","avatar":""},{"name":"Lưu Mộng Mộng","avatar":""},{"name":"Sỉ Cảnh Diên","avatar":""},{"name":"Ngân Tuyết","avatar":""},{"name":"Đỗ Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["脫單告急","完全男生手册","Hey Boys","脱单告急"]', 1784690324389);
