INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-hay-chet', 'Chơi Hay Chết?', 'Truth or Dare', 'https://phimimg.com/upload/vod/20250608-1/7108263f9bf882c352ca410399fc9adc.jpg', 'https://phimimg.com/upload/vod/20250608-1/9ee7b191d54b54ff185fcba14477ee7d.jpg', '<p>CHƠI HAY CHẾT kể về trò Truth or Dare quen thuộc, được một nhóm các sinh viên trẻ cùng nhau chơi trong chuyến dã ngoại Mexico. Từ một trò chơi vô hại, Truth or Dare trở nên đáng sợ khi hơn khi lần lượt từng người trong nhóm bạn bị giết hại bởi một thế lực siêu nhiên đáng sợ. Những người đã tham gia bắt buộc phải tuân thủ nghiêm ngặt quy tắc của trò chơi: Hoặc là nói thật, hoặc sẽ bị trừng phạt.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Lucy Hale","avatar":""},{"name":"Violett Beane","avatar":""},{"name":"Tyler Posey","avatar":""},{"name":"Hayden Szeto","avatar":""},{"name":"Aurora Perrineau","avatar":""},{"name":"Sophia Ali","avatar":""},{"name":"Landon Liboiron","avatar":""},{"name":"Morgan Lindholm","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Ezmie Garcia","avatar":""},{"name":"Nolan Gerard Funk","avatar":""},{"name":"Sam Lerner","avatar":""},{"name":"Brady Smith","avatar":""},{"name":"Tom Choi","avatar":""},{"name":"Vera Taylor","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Omar Leyva","avatar":""},{"name":"Leslie","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Blumhouse''s Truth or Dare","Wahrheit oder Pflicht","Verdad o reto","트루스 오어 데어","Pravda alebo odvaha","Action ou vérité","Vérité ou conséquence","אמת או חובה","O Jogo do Desafio: Versão Estendida do Diretor","Truth or Dare"]', 1784690324390);
