INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('choi-hay-chet', 'Chơi Hay Chết?', 'Truth or Dare', 'chơi hay chết? truth or dare lucy hale violett beane tyler posey hayden szeto aurora perrineau sophia ali landon liboiron morgan lindholm gary anthony williams ezmie garcia nolan gerard funk sam lerner brady smith tom choi vera taylor andrew howard omar leyva leslie blumhouse''s truth or dare wahrheit oder pflicht verdad o reto 트루스 오어 데어 pravda alebo odvaha action ou vérité vérité ou conséquence אמת או חובה o jogo do desafio: versão estendida do diretor truth or dare', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-ac-ma-dung-hon-toi-phan-3', 'Thiếu Gia Ác Ma Đừng Hôn Tôi (Phần 3)', 'Master Devil Don''t Kiss Me (Season 3)', 'https://phimimg.com/upload/vod/20250606-1/8e27235d6f053c38a20064acad3e2b88.jpg', 'https://phimimg.com/upload/vod/20250606-1/1c64889fd35c98d59811b56bf70e019b.jpg', '<p>Thiếu gia ác ma Hàn Thất Lục khi đang cầu hôn vị hôn thê An Sơ Hạ lại vì sự hiểu lầm do Lí Thâm Đông của &quot;Quái Đức Tứ Thiếu&quot; gây ra dẫn đễn nguy cơ chia tay. Lí Thâm Đông thích An Sơ Hạ từ cái nhìn đầu tiên, nhất quyết theo đuổi cô. Còn Hàn Thất Lục từ khi cô nàng Bạch Thu Tử yêu thích mình mà mối quan hệ với Sơ Hạ càng gặp nhiều trắc trở. #Sau những nỗ lực không ngừng nghỉ, Hàn Thất Lục và An Sơ Hạ cuối cùng đã tìm lại sự ngọt ngào chớp nhoáng của tình yêu, đồng thời trải qua những thay đổi lớn hơn. Liệu hai người họ có nên duyên? Có thể chịu đựng thử thách cuộc sống và bảo vệ tình yêu của chính mình ...</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phí Chính Vũ","avatar":""},{"name":"Dư Tâm Điềm","avatar":""},{"name":"Văn Sinh","avatar":""},{"name":"Lý Sầm Dịch","avatar":""},{"name":"Thạch Tân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恶魔少爷别吻我","Èmó Shàoyé Bié Wěn Wǒ","E Mo Shao Ye Bie Wen Wo","Emo Shaoye Bie Wen Wo","Ngok3 Mo1 Siu2 Je4 Bit6 Man5 Ngo5","Wu Mo Siu Ye Bit Man Ngo","Master Devil Do Not Kiss Me 2"]', 1784690324390);
