INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-ac-ma-dung-hon-toi-phan-1', 'Thiếu Gia Ác Ma Đừng Hôn Tôi (Phần 1)', 'Master Devil Don''t Kiss Me (Season 1)', 'https://phimimg.com/upload/vod/20250606-1/485c4610ad6d9202ecd6355f698437ee.jpg', 'https://phimimg.com/upload/vod/20250606-1/236d9908689bdc2b4ac191709f886a9e.jpg', '<p>An Sơ Hạ và mẹ cô sống cuộc sống nương tựa lẫn nhau. Sau khi mẹ cô qua đời, trong lúc khó khăn tuyệt vọng nhất, quý bà Viên Viên vì giao ước trước đây với mẹ cô đã đưa An Sơ Hạ về nhà nuôi dạy. Với thân phận vợ chưa cưới của Hàn gia Hàn Thất Lục, An Sơ Hạ được bước vào ngôi trường quý tộc danh giá học tập, nhưng trên thực tế An Sơ Hạ và Hàn Thất Lục nhìn không hợp mắt nhau, lại còn oan gia ngõ hẹp. Câu chuyện sẽ diễn ra như thế nào, các bạn hãy cùng tìm hiểu nhé !</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hoành Nghị","avatar":""},{"name":"Hình Phi","avatar":""},{"name":"Trương Quýnh Mẫn","avatar":""},{"name":"Phù Long Phi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恶魔少爷别吻我","Èmó Shàoyé Bié Wěn Wǒ","E Mo Shao Ye Bie Wen Wo","Emo Shaoye Bie Wen Wo","Ngok3 Mo1 Siu2 Je4 Bit6 Man5 Ngo5","Wu Mo Siu Ye Bit Man Ngo","Master Devil Do Not Kiss Me 2"]', 1784690324390);
