INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-ly-hon-the-ky', 'Vụ Ly Hôn Thế Kỷ', 'Matrimonial Chaos', 'https://phimimg.com/upload/vod/20250530-1/ebf57c8f7459f71b7b7159f664269158.jpg', 'https://phimimg.com/upload/vod/20250530-1/7ea86a3093a0366b02099f4fcbef3403.jpg', '<p>Jo Seok Moo tốt nghiệp một trường đại học danh tiếng, nhưng thay vì tìm một công việc truyền thống, anh lại theo đuổi ước mơ trở thành nhạc sĩ. Tuy nhiên, Jo Seok Moo không thể trở thành nhạc sĩ như mong muốn và vì tuổi đã cao, anh cũng không thể tìm được một công việc ổn định. Sau đó, anh bắt đầu làm việc tại một công ty dịch vụ an ninh, nơi anh gặp Kang Hwi Ru lần đầu tiên – khi cô là khách hàng của anh. Hai người kết hôn và đã sống chung được 3 năm, nhưng Jo Seok Moo bất ngờ đệ đơn ly hôn. Họ có rất ít điểm chung: Jo Seok Moo là người cứng đầu, thích ở một mình, còn Kang Hwi Ru lại có tính cách dễ chịu và lạc quan. Một cặp đôi khác cũng xuất hiện trong câu chuyện là Jin Yoo Young và Lee Jang Hyun. Điều đặc biệt là Jin Yoo Young chính là mối tình đầu của Jo Seok Moo.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cha Tae-hyun","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Lee El","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Moon Sook","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Yoon Hye Kyung","avatar":""},{"name":"Hwang Jeong-min","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Ha Yoon-kyung","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Kim Chae-eun","avatar":""},{"name":"Choi Woo-ri","avatar":""},{"name":"Lee Jong-hyuk","avatar":""},{"name":"Lee Yeong-jin","avatar":""},{"name":"Yoon Geumseon-ah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Matrimonial Chaos","The Best Divorce","The Greatest Divorce","최고의 이혼"]', 1784690324390);
