INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-nhan', 'Thương Nhân', 'The Trader (Sovdagari)', 'https://phimimg.com/upload/vod/20250530-1/5f20b74ee4a412f115e22a4323ce431e.jpg', 'https://phimimg.com/upload/vod/20250530-1/b55361a7ec8fb19aeb9c4a6d50cc6ed5.jpg', '<p>Một thương nhân hay du ngoạn hé lộ góc nhìn về cuộc sống thôn dã tại Cộng hòa Georgia, nơi khoai tây chính là tiền tệ và sự đói nghèo vắt kiệt mọi tham vọng.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'FHD', 'Georgia', 0, '[{"name":"Gela","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["조지아의 상인","The Trader","Sovdagari","Sovdagari - Der Händler","Sovdagari: el comerciante","Handlarz","Sovdagari: O Mercador","O Mercador","Торговец","Sovdagari - Le Marchand","სოვდაგარი"]', 1784690324390);
