INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-kinh-sat-nhan', 'Ống Kính Sát Nhân', 'Murder In The Lens', 'https://phimimg.com/upload/vod/20241102-1/773020ef5a074b43d0a3fb5dad020612.jpg', 'https://phimimg.com/upload/vod/20241102-1/703f23315bbc7258bf2ff219652ac56f.jpg', '<p>Chuyện phim xoay quanh K - thanh tra sáng giá nhất ở đồn cảnh sát. Là con người say mê công việc, nên đời tư của anh không có gì nổi trội ngoài các vụ trọng án. Trong một sự cố hi hữu, K gián tiếp gây ra cái chết cho một nữ đồng nghiệp và bị cái chết này ám ảnh. Vì lẽ đó anh vuột mất cơ hội thụ lý vụ án vợ chồng nghệ sĩ Liên Hoa bị mưu sát vào tay thanh tra Dương. Chỉ vài ngày sau khi án mạng xảy ra, nghi phạm đã bị thanh tra Dương bắt, nhưng những bí mật vẫn lờ mờ như màn sương bao phủ khắp thị trấn nhỏ bé.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Diễm My 9x","avatar":""},{"name":"Khương Ngọc","avatar":""},{"name":"Kinh Quốc","avatar":""},{"name":"Nguyễn Chánh Tín","avatar":""},{"name":"Thương Tín","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Quang Sự","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ống Kính Sát Nhân","Murder in the Lens"]', 1784690324390);
