INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bat-dac-di', 'Cô Dâu Bất Đắc Dĩ', 'When I Marry A Stranger', 'https://phimimg.com/upload/vod/20250525-1/01984341565ade1dbb2bd9f658de9c77.jpg', 'https://phimimg.com/upload/vod/20250525-1/702b0d88bbdc6027becdfd359b1860c6.jpg', '<p>Maysarin là một tiểu thư nổi tiếng trong giới thượng lưu, đã đính hôn với Sarut, nhưng anh ta lại bỏ rơi cô ngay trong ngày cưới. Kadethaen là một doanh nhân bất động sản 30 tuổi, đang chờ đợi cô dâu Pinmanee tại sảnh tiệc của một khách sạn sang trọng — thì anh phát hiện ra cô đã bỏ trốn cùng một người đàn ông khác. Kade rời buổi tiệc, đi ra bãi biển nơi đang diễn ra một buổi party, và ở đó anh gặp May — vẫn trong chiếc váy cưới, đang ngồi uống rượu một mình. Họ bắt đầu uống cùng nhau, và những người xung quanh tưởng họ là một cặp đôi nên cả hai đã giả vờ yêu nhau. Kade thậm chí còn cầu hôn cô một cách đùa cợt. Sau đó, họ trở về khách sạn và qua đêm cùng nhau. Sáng hôm sau, May hối hận về những gì đã xảy ra và chỉ muốn quên Kade đi. Nhưng Kade thì không muốn buông tay…</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mik Thongraya","avatar":""},{"name":"Pooklook Fonthip Watcharatrakul","avatar":""},{"name":"Phongsakon Tosuwan","avatar":""},{"name":"KiewKoi Kwankawin Thamrongratthased","avatar":""},{"name":"Sompob Benjathikul","avatar":""},{"name":"Bee Wanvipa Yokakul","avatar":""},{"name":"Nuttanan Khunwat","avatar":""},{"name":"Fernne Natchayakarn Pagwhan","avatar":""},{"name":"Thira Chutikul","avatar":""},{"name":"Don Khomsan Arunrueangsawat","avatar":""},{"name":"Rachawat Klipnger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["เจ้าสาวจำยอม"]', 1784690324390);
