INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-dau-bat-dac-di', 'Cô Dâu Bất Đắc Dĩ', 'When I Marry A Stranger', 'cô dâu bất đắc dĩ when i marry a stranger mik thongraya pooklook fonthip watcharatrakul phongsakon tosuwan kiewkoi kwankawin thamrongratthased sompob benjathikul bee wanvipa yokakul nuttanan khunwat fernne natchayakarn pagwhan thira chutikul don khomsan arunrueangsawat rachawat klipnger เจ้าสาวจำยอม', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-thoi-gian-de-yeu-anh-2018', 'Ngược Dòng Thời Gian Để Yêu Anh', 'Love Destiny', 'https://phimimg.com/upload/vod/20240927-1/795141b3cbcecc48d4827281019e5dc7.jpg', 'https://phimimg.com/upload/vod/20240927-1/b3ad4656a3efecf7da4b5339672fc7a2.jpg', '<p>Karakate, quý nữ thời Ayudhaya sống ở thế kỉ XVII, tính tình đanh đá cay nghiệt, ganh ghét đố kị khiến bản thân mang tiếng xấu gần xa. Cuối cùng vì bị ác tâm che mờ mà muốn giết người để rồi nghiệp báo đến đòi mạng.

Vì một lời hứa, Kesurang sống lại trong thân xác quý nữ Karakate, người bây giờ mang danh điên khùng do Kesurang hết lần này đến lần khác hành xử kì lạ. Tại đây cô gặp phải một vị hôn phu Ok-muen Sunthorndeva miệng lưỡi sắt đá lúc nào cũng như muốn đòi mạng, một Ok-muen Reungratchapakdee lịch thiệp, một Mae Malee dịu dàng đằm thắm, một Ok-luang Surasongkram tham mưu quyền quý, một quý nữ Janwad (người mà Karakate âm mưu giết nhưng bất thành) đỏng đảnh cao quý… Lời hứa của Kesurang cùng trái tim người con gái ấy sẽ đi về đâu? Liệu rằng Kesurang có thể xóa đi thanh danh ác nữ mà Karakate đã để lại hay không?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 16, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Thanawat Wattanaputi","avatar":""},{"name":"Ranee Campen","avatar":""},{"name":"ปรมะ อิ่มอโนทัย","avatar":""},{"name":"Kannarun Wongkajonklai","avatar":""},{"name":"Louis Scott","avatar":""},{"name":"Susira Angelina Naenna","avatar":""},{"name":"Jirayu Thantrakul","avatar":""},{"name":"Janya Thanasawaangkoun","avatar":""},{"name":"Peter Tuinstra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["回到过去爱他","宿缘","爱的宿命","天生一对","พรหมลิขิต","Love Destiny","บุพเพสันนิวาส"]', 1784690324390);
