INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-dao-giau-vang', 'Doraemon: Nobita và Đảo Giấu Vàng', 'Doraemon: Nobita''s Treasure Island', 'doraemon: nobita và đảo giấu vàng doraemon: nobita''s treasure island wasabi mizuta megumi oohara yumi kakazu subaru kimura tomokazu seki yo oizumi kotono mitsuishi yasunori matsumoto shihoko hagino hisako kanemoto daiki yamashita fumiko orikasa aoi yuki saori hayami ryuuzaburou ootomo yoshiko kamei kazuya i doraemon movie 38: nobita no takarajima eiga doraemon: nobita no takarajima 映画 ドラえもん のび太の宝島 電影哆啦a夢：大雄的金銀島 哆啦a梦：大雄的金银岛 도라에몽: 노비타의 보물섬 doraemon - il film: nobita e l''isola del tesoro โดราเอมอน ตอน เกาะมหาสมบัติของโนบิตะ doraemon: nobita và đảo giấu vàng 多啦a夢 - 大雄之金銀島 เกาะมหาสมบัติของโนบิตะ โดราเอมอน เกาะมหาสมบัติของโนบิตะ doraemon the movie: nobita''s treasure island 哆啦a梦 大雄的金银岛 映画ドラえもん のび太の宝島', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-may-man', 'Người đàn ông may mắn', 'A Fortunate Man', 'https://phimimg.com/upload/vod/20250520-1/c135c0d11deee12e8c7e10d4dd4245c4.jpg', 'https://phimimg.com/upload/vod/20250520-1/034547d1618b5dc3ab717a1d6755f333.jpg', '<p>Một kỹ sư tài năng trốn chạy khỏi gia đình hà khắc để theo đuổi công danh giữa tầng lớp ưu tú Copenhagen, nhưng niềm kiêu hãnh thúc đẩy anh có thể hủy hoại anh.</p>', 'Full', 1, 'single', 'completed', 28, 2018, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Esben Smed","avatar":""},{"name":"Katrine Greis-Rosenthal","avatar":""},{"name":"Benjamin Kitter","avatar":""},{"name":"Julie Christiansen","avatar":""},{"name":"Rasmus Bjerg","avatar":""},{"name":"Ole Lemmeke","avatar":""},{"name":"Sara Viktoria","avatar":""},{"name":"Sophie Marie Jeppesen","avatar":""},{"name":"Tommy Kenter","avatar":""},{"name":"Tammi Øst","avatar":""},{"name":"Jens Albinus","avatar":""},{"name":"Paul Hüttel","avatar":""},{"name":"Anders Hove","avatar":""},{"name":"Elsebeth Steentoft","avatar":""},{"name":"Mei Oulund","avatar":""},{"name":"Karl Fischer","avatar":""},{"name":"Claus","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Un hombre afortunado","Lykke-Per"]', 1784690324390);
