INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-dan-ong-may-man', 'Người đàn ông may mắn', 'A Fortunate Man', 'người đàn ông may mắn a fortunate man esben smed katrine greis-rosenthal benjamin kitter julie christiansen rasmus bjerg ole lemmeke sara viktoria sophie marie jeppesen tommy kenter tammi øst jens albinus paul hüttel anders hove elsebeth steentoft mei oulund karl fischer claus un hombre afortunado lykke-per', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-chien', 'Độc chiến', 'Believer', 'https://phimimg.com/upload/vod/20250518-1/6a8a5e217585e7786701c2348c450dff.jpg', 'https://phimimg.com/upload/vod/20250518-1/3ffcefd9e83299e7dd82e8bbfd625339.jpg', '<p>Believer là bộ phim được làm lại từ tác phẩm hợp tác giữa Trung Quốc - Hồng Kông năm 2013 Drug War. Bộ phim của đạo diễn Lee Hae Young quy tụ dàn sao hoành tráng như Cha Seung Won, Ryu Jun Yeol, Kim Joo Hyuk, Kim Sung Ryung, Jo Jin Woong và Park Hae Joon. Xoay quanh câu chuyện về Won Ho (Jo Jin Woong), một cảnh sát thuộc đội chống tội phạm ma túy bất ngờ hợp tác với Rak (Ryu Jun Yeol), một tên buôn lậu ma túy cấp thấp, để cùng triệt phá đường dây buôn lậu ma túy quốc tế đặt tại Seoul mà Rak từng là một thành viên. &nbsp;Không chỉ là 1 trong 10 phim có kinh phí khủng nhất Hàn Quốc năm 2018, &quot;Believer&quot; còn là tác phẩm cuối cùng của diễn viên Kim Joo Hyuk trước khi qua đời vào tháng 10 năm ngoái.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Jin-woong","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Kim Joo-hyuk","avatar":""},{"name":"Cha Seung-won","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Kang Seung-hyun","avatar":""},{"name":"Jung Jun-won","avatar":""},{"name":"Jung Ga-ram","avatar":""},{"name":"Jin Seo-yeon","avatar":""},{"name":"Kim Dong-young","avatar":""},{"name":"Lee Zoo-young","avatar":""},{"name":"Geum Sae-rok","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Lee Ye-eun","avatar":""},{"name":"Lee Ji","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["독전","Dok-jeon","信徒","毒战寒流","독전: 익스텐디드 컷","毒戦 BELIEVER","毒戦 BELIEVER：2018","Believer (2018)","Creyente","毒战","Drug  War Believer","毒戰","毒戰(2018)"]', 1784690324390);
