INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-cau', 'Móc Câu', 'Greta', 'https://phimimg.com/upload/vod/20231130-1/727309f731d4918005e1d67468756039.jpg', 'https://phimimg.com/upload/vod/20231130-1/d4b11b33f8d3cd3ff4018aec88c937e9.jpg', '<p>Móc Câu - Greta (2019):Greta là câu chuyện về một cô gái trẻ ngây thơ mang tên Frances (Moretz) sinh sống tại thành phố xô bồ New York của Mỹ. Cô vô tình tìm được một chiếc ví bị lạc trên tàu điện và trả về chủ của nó. Người chủ chiếc ví là một quá phụ mang tên Greta (Huppert), một người dạy đàn piano với tính yêu nhạc cổ điển và sống cô đơn tại một căn hộ. Frances cảm thấy tình mẫu tử từ Greta vì cô vừa mất mẹ nên đã giao tiếp và quen với Greta. Nhưng Frances dần khám phá ra những bí mật đáng sợ đằng sau cuộc sống của Greta và cô trở thành con mồi của Greta !</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Isabelle Huppert","avatar":""},{"name":"Maika Monroe","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Zawe Ashton","avatar":""},{"name":"Jeff Hiller","avatar":""},{"name":"Thaddeus Daniels","avatar":""},{"name":"Raven Dauda","avatar":""},{"name":"Parker Sawyers","avatar":""},{"name":"Jessica Claire Preddy","avatar":""},{"name":"Jane Perry","avatar":""},{"name":"Angela Thompson Georgas","avatar":""},{"name":"Rosa Escoda","avatar":""},{"name":"Graeme Thomas King","avatar":""},{"name":"Hershel Blat","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich",