INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-nam-ruc-ro', 'Tháng Năm Rực Rỡ', 'Go-Go Sisters', 'https://phimimg.com/upload/vod/20250516-1/2b202b2b336a27b62b02bf9437a786b5.jpg', 'https://phimimg.com/upload/vod/20250516-1/0ccf6567e479c5082874572e7b739b23.jpg', '<p>Tháng Năm Rực Rỡ là câu chuyện về tình bạn, về tuổi trẻ cuồng nhiệt của một nhóm bạn gái thời trung học. Bộ phim là hành trình đi tìm lại những ký ức thanh xuân của Hiểu Phương và nhóm nữ quái Ngựa Hoang. Tình cờ gặp lại người bạn cũ Mỹ Dung và cũng là trưởng nhóm Ngựa Hoang, Hiểu Phương đau xót khi biết bạn đang mắc bệnh hiểm nghèo. Để thực hiện tâm nguyện của bạn thân, Hiểu Phương quyết tâm tìm lại các thành viên của nhóm Ngựa Hoang. Hành trình đi tìm những người bạn cũ cũng chính là hành trình để Hiểu Phương trở về với những tháng năm rực rỡ của cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hồng Ánh","avatar":""},{"name":"Thanh Hằng","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Hoàng Oanh","avatar":""},{"name":"Jun Vũ","avatar":""},{"name":"Khổng Tú Quỳnh","avatar":""},{"name":"Mỹ Uyên","avatar":""},{"name":"Trịnh Thảo","avatar":""},{"name":"Mỹ Duyên","avatar":""},{"name":"Minh Thảo","avatar":""},{"name":"Tuyền Mập","avatar":""},{"name":"Thanh Tú","avatar":""},{"name":"Anh Thư","avatar":""},{"name":"Lan Phương","avatar":""},{"name":"Song Ngu","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Tiến Vũ","avatar":""},{"name":"Văn Tùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Tháng năm rực rỡ"]', 1784690324390);
