INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-manh-cua-loi-cau-nguyen-duay-rang-atitharn', 'Sức Mạnh Của Lời Cầu Nguyện (Duay Rang Atitharn)', 'The Prayer', 'https://phimimg.com/upload/vod/20250425-1/2b39de470b9f23302059c0e55b1ccfa2.jpg', 'https://phimimg.com/upload/vod/20250425-1/518945387ae20889bb6205bda3e5bc95.jpg', '<p>Trong kiếp trước, Warada (Mew Nittha) là con gái đầu lòng của trung tướng Praphot và một người giúp việc. Dù mang dòng máu quý tộc, cô lại bị gia đình hắt hủi và sống như một người ở nhờ. Warada bị hãm hại và qua đời trong uất ức. Trước khi chết, cô nguyện cầu rằng nếu có kiếp sau, sẽ trả thù những kẻ đã gây ra đau khổ cho mình. Hai mươi năm sau, Warada được đầu thai thành Natthamon, một cô gái trẻ xinh đẹp với những năng lực đặc biệt. Từ nhỏ, Natthamon thường xuyên gặp ác mộng về cái chết của Warada và thấy hình ảnh của một người đàn ông lạ mặt. Khi trưởng thành, cô gặp Krit (Tik Jesdaporn), người đàn ông xuất hiện trong giấc mơ của mình và cũng là cậu ruột của bạn thân cô. Krit từng yêu Warada trong quá khứ và không thể quên cô sau cái chết của nàng. Natthamon bắt đầu làm thư ký cho Krit, và từ đây, những bí mật trong quá khứ dần được hé lộ. Cô phải đối mặt với những ký ức tiền kiếp và quyết định liệu có nên tiếp tục con đường báo thù hay buông bỏ để tìm kiếm sự bình yên.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2018, 'Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Jesdaporn Pholdee","avatar":""},{"name":"Nittha Jirayungyurn","avatar":""},{"name":"Kummun Klomkaew","avatar":""},{"name":"Namfon Patcharin Srivasupirom","avatar":""},{"name":"Pattrakorn Tungsupakul","avatar":""},{"name":"Supoj Janjareonborn","avatar":""},{"name":"Pisanu Chutanimsakul","avatar":""},{"name":"Sarocha Watittapan","avatar":""},{"name":"Songsit Rungnopakunsi","avatar":""},{"name":"Asanai Tientong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Duay Rang Attiharn (2018)"]', 1784690324390);
