INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-deo-bam-phan-5', 'Kẻ Đeo Bám (Phần 5)', 'You (Season 5)', 'https://phimimg.com/upload/vod/20250425-1/df872ec72b8bb3ac4e17bce429867eb2.jpg', 'https://phimimg.com/upload/vod/20250425-1/a44e57141de8a5584acad1cc00041a24.jpg', '<p>Tựa như liều thuốc độc khó cưỡng, lại ôm mối cuồng si mãnh liệt, anh dùng đến cả những biện pháp cực đoan để len lỏi vào cuộc sống của những cô gái mình mê đắm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Penn Badgley","avatar":""},{"name":"Charlotte Ritchie","avatar":""},{"name":"Madeline Brewer","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Griffin Matthews","avatar":""},{"name":"Natasha Behnam","avatar":""},{"name":"Pete Ploszek","avatar":""},{"name":"Tom Francis","avatar":""},{"name":"Nava Mau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ti","Ти","Você","Ты","安眠书店","TY","You: Du wirst mich lieben","You","ΕΣΥ","安眠書店","Te","את","شما","Tu","YOU ー君がすべてー","君は","너의 모든 것","Ty","Sen","Kẻ Đeo Bám"]', 1784690324390);
