INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngong-vit-phieu-luu-ky', 'Ngỗng Vịt Phiêu Lưu Ký', 'Duck Duck Goose', 'https://phimimg.com/upload/vod/20250424-1/45ccd6f918fbba38b011075252ad592b.jpg', 'https://phimimg.com/upload/vod/20250424-1/51a51fc4ff7e7097dbcfc2e9b019edb5.jpg', '<p>Duck Duck Goose xoay quanh cuộc hành trình của chú ngỗng tên Peng. Cậu ta luôn nghĩ rằng mình giỏi hơn những chú ngỗng khác. Peng rất hay tự mình thực hiện những pha nhào lộn với tốc độ bay rất nhanh. Chính vì thế mà một lần nọ, khi đang mải mê với những cú nhào lộn ấy, Peng không may đâm phải một đàn vịt và chia rẽ 2 chú vịt trong đàn là Chao và Chi. Từ đó, cuộc phiêu lưu đầy ắp những tiếng cười của họ bắt đầu.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Jim Gaffigan","avatar":""},{"name":"Zendaya","avatar":""},{"name":"Lance Lim","avatar":""},{"name":"Greg Proops","avatar":""},{"name":"Natasha Leggero","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"Carl Reiner","avatar":""},{"name":"Jennifer Grey","avatar":""},{"name":"Reggie Watts","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Tong Zirong","avatar":""},{"name":"Meilee Condron","avatar":""},{"name":"William M. Steinberg","avatar":""},{"name":"Cathy Cavadini","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Al aire patos","Asas Pelos Ares","Peng e i due anatroccoli","Ben met de Eendjes op Reis","Папа-мама гусь [Duck Duck Goose (2017)]","Ördek Goose","Duck Duck Goose"]', 1784690324390);
