INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-thay-bau-troi-tua-nhu-ngay-ay-phan-1', 'Muốn Thấy Bầu Trời Tựa Như Ngày Ấy (Phần 1)', 'Our Skyy (Season 1)', 'https://phimimg.com/upload/vod/20250420-1/da19f09089bb7c6177eec4178c0e91c2.jpg', 'https://phimimg.com/upload/vod/20250420-1/bb406cbb05e199b6d6728f65af10108f.jpg', '<p>&quot;Our Skyy&quot; là một phim tuyển tập gồm 5 tập, mỗi tập là phần tiếp nối câu chuyện tình yêu của những cặp đôi nổi tiếng từng xuất hiện trong các bộ phim boylove Thái Lan trước đó. Các cặp đôi gồm: Pick và Rome (từ Secret Love: Puppy Honey) In và Sun (từ My Dear Loser) Tee và Mork (từ ’Cause You&#39;re My Boy) Kao và Pete (từ Kiss Me Again) Arthit và Kongpob (từ SOTUS) Mỗi tập phim là một lát cắt về cuộc sống, tình cảm và những thử thách mới mà các cặp đôi phải đối mặt sau khi câu chuyện gốc khép lại. Bộ phim giống như một món quà nhỏ dành cho khán giả yêu mến các cặp đôi này — cho chúng ta thấy &quot;sau cái kết, họ ra sao?&quot;.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 5, 2018, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jumpol Adulkittiporn","avatar":""},{"name":"Atthaphan Phunsawat","avatar":""},{"name":"Tawan Vihokratana","avatar":""},{"name":"Thitipoom Techaapaikhun","avatar":""},{"name":"Nawat Phumphotingam","avatar":""},{"name":"Pawat Chittsawangdee","avatar":""},{"name":"Prachaya Ruangroj","avatar":""},{"name":"Perawat Sangpotirat","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Wachirawit Ruangwiwat","avatar":""},{"name":"Krit Amnuaydechkorn","avatar":""},{"name":"Pattranite Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["อยากเห็นท้องฟ้าเป็นอย่างวันนั้น"]', 1784690324390);
