INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muon-thay-bau-troi-tua-nhu-ngay-ay-phan-1', 'Muốn Thấy Bầu Trời Tựa Như Ngày Ấy (Phần 1)', 'Our Skyy (Season 1)', 'muốn thấy bầu trời tựa như ngày ấy (phần 1) our skyy (season 1) jumpol adulkittiporn atthaphan phunsawat tawan vihokratana thitipoom techaapaikhun nawat phumphotingam pawat chittsawangdee prachaya ruangroj perawat sangpotirat phiravich attachitsataporn wachirawit ruangwiwat krit amnuaydechkorn pattranite li อยากเห็นท้องฟ้าเป็นอย่างวันนั้น', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-quai-thu', 'Võ Lâm Quái Thú', 'Kung Fu Monster', 'https://phimimg.com/upload/vod/20231113-1/8f23a2a0ceef6654a1f00d5475e5cb86.jpg', 'https://phimimg.com/upload/vod/20231113-1/88ce665bd1a1668ceb1cb7060820c4c8.jpg', '<p>Vào thời triều đại vua Minh Thần Tông thời nhà Minh, một tiểu quái thú trốn thoát khỏi cung điện hoàng gia, buộc đốc chủ Tây xưởng tàn ác vào thời điểm đó là Tôn Ngọc Hạc phải truy tìm. Cùng lúc đó, nghĩa quân thiếu hiệp Chân Kiếm và sư muội Hùng Kiều Kiều đã cùng với nữ hiệp Lãnh Băng Băng lập nên một nhóm lục lâm hảo hán để cướp kho bạc triều đình chia cho người nghèo. Tuy nhiên, nhóm lục lâm chưa kịp ra tay thì tiền trong kho bạc đã &quot;không cánh mà bay&quot;. Mọi nghi vấn dồn vào Phong Tứ Hải – một cao thủ trong giang hồ và từng là người của triều đình, nhưng anh lại là người cứu thoát cho tiểu quái thú ấy, điều này đã buộc anh phải chạy trốn trước sự truy lùng gắt gao của quân lính. Bất ngờ thay, Phong Tứ Hải lại đụng độ với nhóm hiệp khách giang hồ, và sự xuất hiện không ai ngờ tới của con quái thú từng trốn thoát càng khiến mọi việc trở nên rối ren hơn.</p>', 'Full', 1, 'single', 'completed', 36, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Trần Học Đông","avatar":""},{"name":"Quách Bích Đình","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Châu Đông Vũ","avatar":""},{"name":"Phương Trung Tín","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8