INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-moi-phan-1', 'Lính Mới (Phần 1)', 'The Rookie (Season 1)', 'https://phimimg.com/upload/vod/20250417-1/9624b37616c057ff8e43a2bbd0862b24.jpg', 'https://phimimg.com/upload/vod/20250417-1/3232bb6fecb1329142f798ee9df1f6cc.jpg', '<p>Sau một tai nạn, John Nolan 40 tuổi theo đuổi ước mơ gia nhập Sở Cảnh sát Los Angeles. Là lính mới già nhất, anh phải vượt qua những hiểm nguy trong công việc và sự hoài nghi từ những người coi đây chỉ là cuộc khủng hoảng tuổi trung niên.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Nathan Fillion","avatar":""},{"name":"Melissa O''Neil","avatar":""},{"name":"Alyssa Diaz","avatar":""},{"name":"Eric Winter","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Jenna Dewan","avatar":""},{"name":"Lisseth Chavez","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["الروكي","菜鸟警察","The Rookie : Le Flic de Los Angeles","Ο Νεοσύλλεκτος","عنوان فارسی : تازه‌کار","ザ・ルーキ","더 루키","Руки","Новачок","The Rookie"]', 1784690324390);
