INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-huyen-bi-3-ky-nghi-ma-ca-rong', 'Khách Sạn Huyền Bí 3: Kỳ Nghỉ Ma Cà Rồng', 'Hotel Transylvania 3: Summer Vacation', 'https://phimimg.com/upload/vod/20250412-1/7aee404121d5449e33cf58f591bd99c0.jpg', 'https://phimimg.com/upload/vod/20250412-1/690ecc704b53bf836ac62a2d432373b7.jpg', '<p>Khách Sạn Huyền Bí 3 lần này sẽ là “cuộc chơi lớn” với một phen tiệc tùng sang chảnh hết mức của gia đình Dracula. Đã quá ngán với cường độ làm việc chăm chỉ 365 ngày không nghỉ, bá tước Dracula quyết định “đình công”. Để khai sáng cho người cha trăm tuổi chưa bao giờ bước ra khỏi “lũy tre làng”, vợ chồng nhà Jonathan – Mavis lập ra kế hoạch xả hơi táo bạo: Thuê đứt một du thuyền du lịch hạng sang để đưa tất thảy bộ xậu quái vật già trẻ lớn bé làm một chuyến ra khơi nhớ đời.</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Adam Sandler","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Fran Drescher","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"David Spade","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Asher Blinkoff","avatar":""},{"name":"Chris Parnell","avatar":""},{"name":"Joe Jonas","avatar":""},{"name":"Chrissy Teigen","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Aaron LaPlante","avatar":""},{"name":"Michelle","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564