INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khach-san-huyen-bi-3-ky-nghi-ma-ca-rong', 'Khách Sạn Huyền Bí 3: Kỳ Nghỉ Ma Cà Rồng', 'Hotel Transylvania 3: Summer Vacation', 'khách sạn huyền bí 3: kỳ nghỉ ma cà rồng hotel transylvania 3: summer vacation adam sandler andy samberg selena gomez kathryn hahn jim gaffigan kevin james fran drescher steve buscemi molly shannon david spade keegan-michael key asher blinkoff chris parnell joe jonas chrissy teigen mel brooks aaron laplante michelle hotel transilvania 3: monstrii in vacanta hotel transylvania 3 monster vacation hotel transylvania 3: a monster vacation hotell transylvania 3: monsterferie hôtel transylvanie 3 : des vacances monstrueuses 몬스터호텔 3 hotel transilvania 3 unas vacaciones monstruosas モンスター・ホテル　クルーズ船の恋は危険がいっぱい？！ სასტუმრო ტრანსილვანია 3: საზაფხულო არდადეგები სასტუმრო ტრანსილვანია 3: საზაფხულო დასვენება hotel transylvania 3 โรงแรมผีหนี ไปพักร้อน 3: ซัมเมอร์หฤหรรษ์ hotel transylvania3 hotel transylvania 3: summer vacation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-3', 'Họa giang hồ chi bất lương nhân (Phần 3)', 'A Portrait of Jianghu: Bad Guys (Season 3) / Hua Jiang Hu Zhi Bu Liang Ren 3', 'https://phimimg.com/upload/vod/20250412-1/5bba3ca5b11732b4dbf3ec15a4140e66.jpg', 'https://phimimg.com/upload/vod/20250412-1/153e844ec0bf6b55e6e9749662d4ce02.jpg', '<p>Họa Giang Hồ Chi Bất Lương Nhân Phần 3: Phim võ hiệp trở lại, tái hiện phong vân loạn thế cuối thời nhà Đường! Càn Lăng bị phá hủy, kho báu Long Tuyền thất lạc, hoàng tử tiền triều Lý Tinh Vân muốn ẩn dật nơi núi rừng, nhưng Bất Lương Soái quyết tâm bắt Thiên Tử để uy hiếp chư hầu, triệu tập các thế lực giang hồ phục hồi Đại Đường. Vương đạo và bá đạo sẽ có một cuộc đối đầu quyết định trong vòng xoáy quyền lực! Mộ Quý Phi, thành Trường An kể lại giang sơn vẻ vang của Đại Đường năm xưa; Vu cổ Miêu Cương, Tương Tây Cản Thi sẽ hé lộ những cuộc tranh đấu ngầm trong giang hồ. Họa Giang Hồ Chi Bất Lương Nhân Phần 3 sẽ tiếp tục kể lại câu chuyện võ hiệp đầy tình yêu, thù hận và những mưu mô thâm hiểm trong thế giới giang hồ.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0084