INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-3', 'Họa giang hồ chi bất lương nhân (Phần 3)', 'A Portrait of Jianghu: Bad Guys (Season 3) / Hua Jiang Hu Zhi Bu Liang Ren 3', 'họa giang hồ chi bất lương nhân (phần 3) a portrait of jianghu: bad guys (season 3) / hua jiang hu zhi bu liang ren 3 jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kham-pha-2018', 'Khám Phá', 'We', 'https://phimimg.com/upload/vod/20250411-1/3af36785b7a618b99aaa22d2c33c2e39.jpg', 'https://phimimg.com/upload/vod/20250411-1/4acdbcf61c6cb95bd0485787d042e29f.jpg', '<p>Trong một mùa hè thiêu đốt ở một ngôi làng biên giới Bỉ – Hà Lan, tám thiếu niên chơi các trò chơi khám phá để phá vỡ sự đơn điệu bơ phờ. Họ thách thức lẫn nhau và bản thân họ và khá sớm, sự tò mò về tình dục của họ bắt đầu làm mờ đi ranh giới giữa đúng và sai. Khi sự ngây thơ bị nghiền nát trong các trò chơi đồi trụy và bóc lột tình dục, thanh thiếu niên sớm biến thành kẻ săn mồi tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Pauline Casteleyn","avatar":""},{"name":"Aimé Claeys","avatar":""},{"name":"Gaia Sofia Cozijn","avatar":""},{"name":"Axel Daeseleire","avatar":""},{"name":"Salomé van Grunsven","avatar":""},{"name":"Laura Drosopoulos","avatar":""},{"name":"Friso van der Werf","avatar":""},{"name":"Lieselot Siddiki","avatar":""},{"name":"Maxime Jacobs","avatar":""},{"name":"Tom De Vreese","avatar":""},{"name":"Joke Devynck","avatar":""},{"name":"Tijmen Govaerts","avatar":""},{"name":"Pieter Embrechts","avatar":""},{"name":"Gonny Gaakeer","avatar":""},{"name":"Michaël Pas","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["We","위!","去他x的放蕩青春","Wir","Εμείς","Mi","インモラル・ゲーム　淫らな遊戯","Wĳ: A Summer Odyssey in Four Parts","WIR - der Sommer, als wir unsere Röcke hoben und die Welt gegen die Wand fuhr","My!","Мы","Chúng Ta","Wij"]', 1784690324390);
