INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('young-ju', 'Young Ju', 'Youngju', 'https://phimimg.com/upload/vod/20250411-1/edb296e414a14c8c1ab05d89aef3b017.jpg', 'https://phimimg.com/upload/vod/20250411-1/1e3f1375a261c63149b81eec863afa6c.jpg', '<p>Cha mẹ của Youngju qua đời sau một vụ tai nạn, để lại cô bé một mình chăm sóc cho cậu em trai ngang bướng. Mong muốn được trả thù, cô bé âm thầm tìm đến tiệm bán đậu hũ của người đã gây nên tai nạn, và được cặp vợ chồng đó nhận vào làm. Dù rất căm giận, nhưng sự nồng ấm, chân thành của cặp vợ chồng già đã dần xóa đi ác cảm và giúp cô thấu hiểu về hoàn cảnh của họ.</p>', 'Full', 1, 'single', 'completed', 5, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyang-gi","avatar":""},{"name":"Kim Ho-jung","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Tang Joon-sang","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Kim So-suk","avatar":""},{"name":"Kim Min-yeop","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["영주"]', 1784690324390);
