INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-chuyen-chua-ke', 'Lọ Lem: Chuyện Chưa Kể', 'Cinderella and the Secret Prince', 'https://phimimg.com/upload/vod/20250407-1/21a4e463b40bf45ed209e6cb98c9b6bf.jpg', 'https://phimimg.com/upload/vod/20250407-1/5bccfb7fbc574804d8294f0c2b00d23d.jpg', '<p><span style="text-wrap-mode: wrap;">Với sự giúp đỡ của tiên đỡ đầu Crystal, cô bé Lọ Lem và những người bạn là ba chú chuột đã trốn thoát khỏi căn gác xép để tham dự Vũ hội hoàng gia tại cung điện. Nhưng rồi họ phát hiện ra một bí mật khủng khiếp: Hoàng tử thật sự đã bị mụ phù thủy độc ác biến thành chuột, còn Hoàng tử đang đứng trước mặt mọi người trong Vũ hội chỉ là kẻ giả mạo! Lọ Lem và những người bạn thân thiết của cô quyết định dấn thân vào cuộc phiêu lưu đầy khó khăn và nguy hiểm để giúp Hoàng tử trở lại làm người và đánh bại mụ phù thủy độc ác.</span></p>', 'Full', 1, 'hoathinh', 'completed', 6, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 1, '[{"name":"Cassandra Lee Morris","avatar":""},{"name":"Stephen Mendel","avatar":""},{"name":"R. Martin Klein","avatar":""},{"name":"Stephanie Sanditz","avatar":""},{"name":"Terrence Stone","avatar":""},{"name":"Wendee Lee","avatar":""},{"name":"Kirsten Day","avatar":""},{"name":"Chris Niosi","avatar":""},{"name":"Tony Azzolino","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Cinderella 3D","New Cinderella","신데렐라:마법 반지의 비밀","신데렐라-마법 반지의 비밀","Cinderella","Cinderella and Secret Prince","Tuhkatriinu Ja Nõiutud Prints","Cindere