INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('power-rangers-sieu-ninja-thep', 'Power Rangers: Siêu Ninja Thép', 'Power Rangers Super Ninja Steel', 'https://phimimg.com/upload/vod/20250320-1/8c4ebad1087c34fccb0589956e5faff3.jpg', 'https://phimimg.com/upload/vod/20250320-1/c6a6442a73b171388229df3171227ea4.jpg', '<p>Trong Power Rangers Super Ninja Steel , những thiếu niên anh hùng thấy mình phải đối mặt với một kẻ thù cũ khi họ phát hiện ra Madame Odius đã sống sót và quyết tâm hơn bao giờ hết để đánh cắp Ninja Nexus Prism và hồi sinh sức mạnh của nó cho mục đích đen tối của mình. Bây giờ, các Rangers và một số sự giúp đỡ bất ngờ từ những người bạn mới phải sử dụng sức mạnh của tinh thần đồng đội để bảo vệ Prism, đánh bại Odius và cứu thế giới!</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Power Rangers Super Megaforce Finale: Legendary Battle","Power Rangers Super Megaforce: The Legendary Battle"]', 1784690324390);
