INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-mat-tua-khoi-suong', 'Hương Mật Tựa Khói Sương', 'Ashes of Love', 'https://phimimg.com/upload/vod/20250326-1/8ec857981271fb0d0f31ba4ee82e068f.jpg', 'https://phimimg.com/upload/vod/20250326-1/0ee9a9c1963b1e0531e545abc9793926.jpg', '<p>Phim Hương Mật Tựa Khói Sương lấy bối cảnh của một thế giới thần tiên, trong thế giới đó Dương Tử hóa thân thành một quả tinh tên Cẩm Mịch tu luyện suốt hơn 4000 năm. Vốn là con gái của Hoa Thần nhưng chịu phải kiếp nạn từ nhỏ, Cẩm Mịch bị Hoa Thần dùng thuốc tuyệt tình khiến cô trải qua quãng thời gian 4000 năm trong sự cô đơn và ngưỡng tưởng không bao giờ có thể gặp được một thiên duyên tiền định của mình. Sau khi tu luyện trở thành tiên nữ, Cẩm Mịch vẫn là một tiên tử trong sáng, thiên chân với vẻ ngoài có mê lực thần kỳ khiến cả Dạ Thần Nhuận Ngọc và Hỏa Thần Húc Phượng. Tuy nhiên người đưa Cẩm Mịch đi từ vị ngọt đến vị đắng của tình yêu lại là Hỏa Thần Húc Phượng. Câu chuyện tình của hai người trải qua những khó khăn, trầm loạn của Hoa giới nhưng cho đến khi mọi thứ đã muộn thì Cẩm Mịch mới phát hiện ra tình cảm của mình.</p>', 'Hoàn Tất (63/63)', 63, 'series', 'completed', 9, 2018, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Zi","avatar":""},{"name":"Deng Lun","avatar":""},{"name":"Luo Yunxi","avatar":""},{"name":"Wang Yifei","avatar":""},{"name":"Yukee Chen","avatar":""},{"name":"Zhou Tingwei","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"Du Yuchen","avatar":""},{"name":"Xia Zhiyuan","avatar":""},{"name":"Wang Yuanke","avatar":""},{"name":"Wang Renjun","avatar":""},{"name":"Peng Yang","avatar":""},{"name":"Zhang Junran","avatar":""},{"name":"Zhang Yanyan","avatar":""},{"name":"Li Yixuan","avatar":""},{"name":"Sa Dingding","avatar":""},{"name":"Ning Wentong","avatar":""},{"name":"Liao Jinfeng","avatar":""},{"name":"Shang Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Cinzas do Amor","The honey sank like frost","Cendres d''amour","אפר האהבה","霜花の姫 香蜜が咲かせし愛","そうかのひめ こうみつがさかせしあい","향밀침침신여상","Пепел любви","มธุรสหวานล้ำ สลายเป็นเถ้าราวเกล็ดน้ำค้าง","香蜜沉沉燼如霜","Ashes of Love","Hương Mật Tựa Khói Sương","香蜜沉沉烬如霜"]', 1784690324390);
