INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-mat-tua-khoi-suong', 'Hương Mật Tựa Khói Sương', 'Ashes of Love', 'hương mật tựa khói sương ashes of love yang zi deng lun luo yunxi wang yifei yukee chen zhou tingwei kathy chow hoi-mei he zhonghua du yuchen xia zhiyuan wang yuanke wang renjun peng yang zhang junran zhang yanyan li yixuan sa dingding ning wentong liao jinfeng shang na cinzas do amor the honey sank like frost cendres d''amour אפר האהבה 霜花の姫 香蜜が咲かせし愛 そうかのひめ こうみつがさかせしあい 향밀침침신여상 пепел любви มธุรสหวานล้ำ สลายเป็นเถ้าราวเกล็ดน้ำค้าง 香蜜沉沉燼如霜 ashes of love hương mật tựa khói sương 香蜜沉沉烬如霜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-con-tim-phan-1', 'Tín Hiệu Con Tim (Phần 1)', 'Heart Signal (Season 1)', 'https://phimimg.com/upload/vod/20250327-1/9a18788d37c44dd09194d3d02a3aecf1.jpg', 'https://phimimg.com/upload/vod/20250327-1/7b7d60f1382a6f6d5929a39339afbc77.jpg', '<p>Tín Hiệu Con Tim là chương trình thực tế giao lưu suy luận về tình cảm nam nữ. Các cặp đôi nam nữ độc thân bước vào &quot;Ngôi nhà nhỏ tín hiệu&quot; sống chung và phát triển tình cảm với nhau.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Haitao","avatar":""},{"name":"Jerry Yan","avatar":""},{"name":"Chunye Zhang","avatar":""},{"name":"Ariel Lin","avatar":""},{"name":"Rao Xueman","avatar":""},{"name":"The8","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Heart Signal","心动的信号"]', 1784690324390);
