INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-deo-bam-phan-1', 'Kẻ Đeo Bám (Phần 1)', 'You (Season 1)', 'https://phimimg.com/upload/vod/20250308-1/83d45d8a484fc5c3838f2cbea1deb979.jpg', 'https://phimimg.com/upload/vod/20250308-1/3f7fed69856d6f5e7a907048f8db045d.jpg', '<p>Tựa như liều thuốc độc khó cưỡng, lại ôm mối cuồng si mãnh liệt, anh dùng đến cả những biện pháp cực đoan để len lỏi vào cuộc sống của những cô gái mình mê đắm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Penn Badgley","avatar":""},{"name":"Victoria Pedretti","avatar":""},{"name":"Elizabeth Lail","avatar":""},{"name":"Shay Mitchell","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"James Scully","avatar":""},{"name":"Ambyr Childers","avatar":""},{"name":"Carmela Zumbado","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Tati Gabrielle","avatar":""},{"name":"Dylan Arnold","avatar":""},{"name":"Shalita Grant","avatar":""},{"name":"Travis Van Winkle","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"John Stamos","avatar":""},{"name":"Luca Padovan","avatar":""},{"name":"Zach C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ti","Ти","Você","Ты","安眠书店","TY","You: Du wirst mich lieben","You","ΕΣΥ","安眠書店","Te","את","شما","Tu","YOU ー君がすべてー","君は","너의 모든 것","Ty","Sen","Kẻ Đeo Bám"]', 1784690324390);
