INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-bien-phan-1', 'Tinh Thần Biến (Phần 1)', 'Stellar Transformation (Season 1)', 'https://phimimg.com/upload/vod/20250224-1/42ea47470ecdd4aa3687186b374b402e.jpg', 'https://phimimg.com/upload/vod/20250225-1/c73675234e070dceaf194560819106d3.jpg', '<p>Phim Tinh Thần Biến là một tiểu thuyết võ hiệp có nội dung về một câu Truyện Tiên Hiệp hoành tráng kể về người thanh niên Tần Vũ gian khổ tu luyện, vượt hết khó khăn này đến nguy hiểm khác để lên Thần Giới tìm người yêu. Tần Vũ đã gặp duyên kỳ ngộ học được Tinh Thần Biến công pháp của Lôi Vệ, gian khổ tu luyện để làm cho người thân mình an toàn, nhờ sự giúp sức của Lan thúc(chú của người yêu) và Nghịch Ương tiên đế để phi thăng lên tiên giới và thần giới, nhưng rồi tại thần giới tranh đấu với cả nhà thần vương của Lôi Phạt thành và Lôi Phạt thiên tôn, cuối cùng nhờ sự giúp sức của Lôi Mông (sau này là nhị sư huynh của Tần Vũ và cũng là Lâm Lôi trong truyện Bàn Long cùng tác giả) phát triển lên sau này đã sáng tạo ra Tần Mông vũ trụ của riêng mình. Tinh Thần Biến mang đậm sắc thái tiên, thần, lấy tinh thần dũng cảm vượt khó khăn, cố gắng đến cực hạn của bản thân nhân vật chính để đi tìm được tình yêu của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Weng","avatar":""},{"name":"Shen Dawei","avatar":""},{"name":"Jingxia Liu","avatar":""},{"name":"Liu Yuxuan","avatar":""},{"name":"Muqing Ke","avatar":""},{"name":"Ming Zhao","avatar":""},{"name":"Xia Lei","avatar":""},{"name":"Hongbo Guo","avatar":""},{"name":"Qingqing Du","avatar":""},{"name":"Jackwin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Stellar Transformations","Legend of Immortals","Xingchen Bian","Xing Chen Bian","Stellar Transformation","星辰變","星辰变"]', 1784690324390);
