INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-than-bien-phan-1', 'Tinh Thần Biến (Phần 1)', 'Stellar Transformation (Season 1)', 'tinh thần biến (phần 1) stellar transformation (season 1) yuan weng shen dawei jingxia liu liu yuxuan muqing ke ming zhao xia lei hongbo guo qingqing du jackwin stellar transformations legend of immortals xingchen bian xing chen bian stellar transformation 星辰變 星辰变', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ly-cap-trung-tonegawa', 'Quản Lý Cấp Trung Tonegawa', 'Mr. Tonegawa Middle Management Blues', 'https://phimimg.com/upload/vod/20250221-1/89293e97fd9ecc0670bdec14c816509f.jpg', 'https://phimimg.com/upload/vod/20250221-1/05bab169b9531ba6a906fce41cbc12da.jpg', '<p>Không ai biết cảm giác trở thành kẻ ác là thế nào... trừ cánh tay phải của kẻ ác, người phải biến những ý tưởng điên rồ của ông chủ thành các kế hoạch thực tế. Khi chủ tịch tàn ác của Tập đoàn Teiai cảm thấy chán với các việc như gãy chân và đuổi góa phụ/trẻ mồ côi, ông ta giao nhiệm vụ nghĩ ra điều gì đó &#39;đặc biệt&#39; cho Yukio Tonegawa, người đứng thứ hai tàn nhẫn của mình. Nhưng làm sao để khiến một người có thể phá hủy hàng chục cuộc đời trước bữa sáng cảm thấy vui vẻ? Có một lượng lớn nạn nhân tiềm năng dưới hình thức những người vay nợ quá hạn của TFO, nhưng nếu Tonegawa và đội ngũ của anh ta, những người gần như giống nhau với trang phục đen, không thể tạo ra một &#39;trò chơi tử thần&#39; làm ông chủ vui thích, thì chính họ có thể sẽ phải tham gia trò chơi đó!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Masane Tsukayama","avatar":""},{"name":"Chiharu Sawashiro","avatar":""},{"name":"Takaya Aoyagi","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Koutaro Nishiyama","avatar":""},{"name":"Daiki Hamano","avatar":""},{"name":"Rikiya Koyama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chuukan Kanriroku Tonegawa","Chūkan Kanriroku Tonegawa","The Chronicles of Middle Manager Tonegawa","中間管理録トネガワ"]', 1784690324390);
