INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tat-phan-no', 'Bồ Tát Phẫn Nộ', 'Bodhisattva In Storm', 'https://phimimg.com/upload/vod/20250220-1/8a42f0242c1b2054e34a036ce1b8e810.jpg', 'https://phimimg.com/upload/vod/20250220-1/cb9d7acd24608fb1c8c14af08fce6e6b.jpg', '<p>Năm 1946, chiếc tàu chở hàng &#39;Triều Phong Maru&#39; đầy ắp những người Đài Loan từ Nhật Bản về lại cảng Cơ Long. Sinh viên Trung Quốc Đào Triển Văn, nổi danh vì phá được vụ án giết người, cùng với người bạn Dương Huy Minh đến trang trại Bồ Tát để cầu hôn, nhưng lại gặp phải một vụ án mạng bí ẩn...</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 16, 2018, 'Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Wu Kang-ren","avatar":""},{"name":"Wu Chien-Ho","avatar":""},{"name":"Esther Liu","avatar":""},{"name":"Lin Si Yu","avatar":""},{"name":"Lawrence Ko Yu-Luen","avatar":""},{"name":"Liu Kuan-ting","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["憤怒的菩薩"]', 1784690324390);
