INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pacific-rim-troi-day', 'Pacific Rim: Trỗi Dậy', 'Pacific Rim: Uprising', 'https://phimimg.com/upload/vod/20250219-1/c2cdcf6472a6470a2760b4a54906deff.jpg', 'https://phimimg.com/upload/vod/20250219-1/ba83a96d13d5849955d421d49c242edc.jpg', '<p>Lấy bối cảnh 10 năm sau những sự kiện đã diễn ra ở phần 1, Jake Pentecost – truyền nhân duy nhất của huyền thoại Stacker Pentecost đã thực hiện lời hứa với cha mình, gia nhập nhóm người điều khiển Jaeger gồm có Lambert (Scott Eastwood) và Amara chỉ mới 15 tuổi (Cailee Spaeny), cùng nhau xây dựng nên một chiến tuyến chống lại Kaiju. Cuộc xung đột toàn cầu kéo dài giữa những quái vật âm mưu phá hủy thế giới và những robot khổng lồ do con người chế tạo ra nhằm đánh bại lũ quái vật hứa hẹn sẽ là một cuộc chiến cam go và kịch tính khi lũ quái vật giờ đây đã tiến hóa vượt bậc cả về thể lực và trí lực.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"John Boyega","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Cailee Spaeny","avatar":""},{"name":"Jing Tian","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"Max Zhang Jin","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Madeleine McGraw","avatar":""},{"name":"Karan Brar","avatar":""},{"name":"Ivanna Sakhno","avatar":""},{"name":"Mackenyu","avatar":""},{"name":"Wesley Wong","avatar":""},{"name":"Levi Meaden","avatar":""},{"name":"Rahart Adams","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Nick E. Tarabay","avatar":""},{"name":"Dustin Cl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"6856