INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('snowfall-phan-2', 'Snowfall (Phần 2)', 'Snowfall (Season 2)', 'https://phimimg.com/upload/vod/20250218-1/9450105aa5c56215cc258216dbf851b9.jpg', 'https://phimimg.com/upload/vod/20250218-1/bb4d0e4b0fd3725b7861b1eaa9ff2f34.jpg', '<p>Los Angeles. Năm 1983. Một cơn bão đang đến và tên của nó là crack. Câu chuyện diễn ra trong bối cảnh những ngày đầu của dịch crack cocaine và tác động cực kỳ lớn của nó lên văn hóa mà chúng ta biết, theo chân nhiều nhân vật trên một hành trình đầy bạo lực.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Damson Idris","avatar":""},{"name":"Carter Hudson","avatar":""},{"name":"Sergio Peris-Mencheta","avatar":""},{"name":"Michael Hyatt","avatar":""},{"name":"Amin Joseph","avatar":""},{"name":"Angela Lewis","avatar":""},{"name":"Isaiah John","avatar":""},{"name":"Devyn A. Tyler","avatar":""},{"name":"Alejandro Edda","avatar":""},{"name":"Gail Bean","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["白粉飞","毒雪纷飞","Snowfall"]', 1784690324390);
