INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('snowfall-phan-2', 'Snowfall (Phần 2)', 'Snowfall (Season 2)', 'snowfall (phần 2) snowfall (season 2) damson idris carter hudson sergio peris-mencheta michael hyatt amin joseph angela lewis isaiah john devyn a. tyler alejandro edda gail bean 白粉飞 毒雪纷飞 snowfall', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-co-thien-ha', 'Độc Cô Thiên Hạ', 'The Legend Of Dugu', 'https://phimimg.com/upload/vod/20240820-1/50d8ca1d9434627176194bef1c94fa23.jpg', 'https://phimimg.com/upload/vod/20240820-1/994b2456d2612df2663a6e34d878857a.jpg', '<p>Độc Cô Thiên Hạ là bộ phim lấy bối cảnh ở những năm cuối triều đình Bắc Chu đầy rối ren, loạn lạc. Vì một lời tiên đoán &quot;Độc Cô thiên hạ&quot; mà ba người con gái của trọng thần Độc Cô Tín là Bàn Nhược, Mạn Đà, Già La từng bước từ danh môn khuê tú lột xác thành những nữ nhân hoàng tộc. Trong đó, trưởng nữ Độc Cô Bàn Nhược (An Dĩ Hiên) một lòng muốn trở thành hoàng hậu, thực hiện tiên đoán Độc Cô thiên hạ, vì thế không tiếc từ bỏ tình yêu của mình là đại tư mã Vũ Văn Hộ (Từ Chính Hy), chấp nhận thành thân cùng Vũ Văn Dục (Trâu Đình Uy), gia nhập hoàng thất Bắc Chu và trở thành Minh Kính hoàng hậu. Tuy nhiên, Bàn Nhược vì yêu quyền lực mà vẫn dan díu với Vũ Văn Hộ, quyền thần thực sự nắm quyền lực của nhà Bắc Chu.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 9, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Băng Khanh","avatar":""},{"name":"Lý Y Hiểu","avatar":""},{"name":"An Dĩ Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324390);
