INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-gia-lam-chieu-2', 'Gái Già Lắm Chiêu 2', 'The Cougar Queen', 'https://phimimg.com/upload/vod/20250216-1/4a06e04a3f1805dd67c90cf826fee09f.jpg', 'https://phimimg.com/upload/vod/20250216-1/8aa5a27029a7cc82ef01ca04ababd015.jpg', '<p>Chuyện phim xoay quanh Ms. Q (Ninh Dương Lan Ngọc) - một MC của chương trình truyền hình chuyên khai thác đời tư ngôi sao làng giải trí Việt. &nbsp;Xinh đẹp, bản lĩnh và đang ở đỉnh cao sự nghiệp, cô không hề nghĩ đến chuyện kết hôn dù đã bước sang tuổi băm. Một ngày nọ, Ms. Q bất ngờ bị bạn trai, và cũng là nhà đầu tư chương trình, phản bội. &nbsp;Cả tình yêu lẫn sự nghiệp của cô nàng bỗng chốc sụp đổ. Nhóm bạn thân gồm Kiki Ngô (Thùy Anh), Đài Trang (Phương Lan) và Maria Cao (Thoại Tiên) quyết định thuê chàng trai bao tên Jack (Lê Xuân Tiền) về để Ms. Q “giải sầu”. &nbsp;Ngay sáng hôm sau, cô bàng hoàng phát hiện ra rằng anh chàng “tình một đêm” kia chính là nhân viên thực tập mới của công ty. Từ đây, hàng loạt sự kiện dở khóc dở cười xảy đến khiến cuộc sống của cả Ms. Q lẫn Jack hoàn toàn thay đổi.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Ninh Dương Lan Ngọc","avatar":""},{"name":"Phương Lan","avatar":""},{"name":"Thoại Tiên","avatar":""},{"name":"Lê Xuân Tiền","avatar":""},{"name":"Thùy Anh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gái Già Lắm Chiêu 2"]', 1784690324390);
