INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-duong-cobra-kai-phan-1', 'Võ Đường Cobra Kai (Phần 1)', 'Cobra Kai (Season 1)', 'https://phimimg.com/upload/vod/20240922-1/c77315cb9ea6be6e4fc654c5dc47b99f.jpg', 'https://phimimg.com/upload/vod/20240922-1/f88c6ee745935ad69ac09f4a8816642a.jpg', '<p>Võ Đường Cobra Kai kể về mấy chục năm sau giải đấu thay đổi cuộc đời, cuộc cạnh tranh giữa Johnny và Daniel một lần nữa lại bùng lên. Phim là phần sau của Cậu bé Karate.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ralph Macchio","avatar":""},{"name":"William Zabka","avatar":""},{"name":"Xolo Maridueña","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324390);
