INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-ngu-hoang-kim', 'Giấc Ngủ Hoàng Kim', 'Golden Slumber', 'https://phimimg.com/upload/vod/20231203-1/540ee8e79abe44d66f72b7a48eea52cb.jpg', 'https://phimimg.com/upload/vod/20231203-1/54fa5c76eacea064db7a09a613dd2116.jpg', '<p>Gun-Woo (Gang Dong-won) là một chuyển phát nhanh trung thực và chăm chỉ, thậm chí đã giành được một giải thưởng công dân mô hình để cứu một ca sĩ khỏi một vụ cướp. Ra khỏi màu xanh, người bạn cũ Moo-Yeol của anh đến thăm anh tại nơi làm việc. Chỉ với một khoảnh khắc ngắn để tận hưởng sự bất ngờ thú vị, Gun-Woo chứng kiến một sự cố bom giết chết một ứng cử viên tổng thống ngay trước mắt anh ta. Moo-Yeol nói với Gun-Woo rằng anh ta chịu trách nhiệm về vụ đánh bom và rằng mọi người sẽ đến sau anh ta vì đó là kế hoạch của cơ quan để biến anh ta thành nghi phạm. Gun-Woo quản lý để chạy trốn khỏi hiện trường nhưng tất cả các bằng chứng, bao gồm các cảnh quay camera an ninh, chứng minh chứng kiến và dấu vân tay hướng về phía anh ta như nghi phạm. Anh ta gặp cựu đặc vụ bí mật Ông Min (Kim Eui-sung), một người bạn cũ của Moo-Yeol và anh ta giúp xóa tên anh ta. Gun-Woo phải chiến đấu với tất cả sức mạnh của mình để sống sót. Tuy nhiên, khi anh ta cố gắng chạy trốn, mọi người xung quanh anh ta được đưa vào những tình huống nguy hiểm, bao gồm cả những người bạn cũ Dong-Kyu (Kim Dae-myeung), Geum-Chul (Kim Sung-Kyun) và Sun-Young (Han Hyo-joo) .</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324390);
