INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-nguoi-khong-lo-phan-3', 'Đại Chiến Người Khổng Lồ (Phần 3)', 'Attack On Titan (Season 3)', 'https://phimimg.com/upload/vod/20240507-1/3adce4aa7cd0cdc9538ea3793208edd5.jpg', 'https://phimimg.com/upload/vod/20240507-1/027a7afc129a0e43c8a5dec77d806e0e.jpg', '<p>Chứng kiến quê hương bị tàn phá, chàng thanh niên Eren Yeager quyết tâm chiến đấu với bọn Titan khổng lồ đang đe dọa hủy diệt loài người.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Kisho Taniyama","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Natsuki Hanae","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324390);
