INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-ca-hanh-phan-1', 'Thiếu Niên Ca Hành (Phần 1)', 'Great Journey Of Teenagers (Season 1)', 'https://phimimg.com/upload/vod/20250119-1/bd0afca5d5fe69cc3454ab688d4ae2c2.jpg', 'https://phimimg.com/upload/vod/20250119-1/b10ed55b3d1b19dff9d42c2962691ad3.jpg', '<p>Phim Thiếu Niên Ca Hành Sau khi Vong Ưu đại sư của Hàn Thủy Tự tọa hóa, một cỗ quan tài vàng thần bí nhập thế, vén lên phân tranh trong giang hồ. Thế lực các nơi đối chọi gay gắt, Lôi Vô Kiệt, Tiêu Sắt, Đường Liên, Tư Không Thiên Lạc, Thiên Nữ Nhụy lần lượt rơi vào phân tranh. Sách mã giang hồ mộng, ỷ kiếm đạp ca hành. Câu chuyện về bí mật của quan tài vàng dần dần được hé mở…</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 10, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yi","avatar":""},{"name":"Zhang Boheng","avatar":""},{"name":"Lei Yao","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Wei Chao","avatar":""},{"name":"Yu Su","avatar":""},{"name":"Ajie","avatar":""},{"name":"Jing Yang","avatar":""},{"name":"Li Lu","avatar":""},{"name":"Qiuxiang Shen","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Shaonian Ge Xing","Youths and Golden Coffin","Shao Nian Ge Xing Feng Hua Xue Yue","Shao Nian Ge Xing","Shaonian Gexing","少年歌行动漫","少年歌行 黄金棺材篇","少年歌行 风花雪月篇","少年歌行 海外仙山篇","少年歌行 血染天启篇","少年歌行之風花雪月篇","少年歌行之黃金棺材篇","少年歌行","少年歌行之風花雪月特別篇","少年歌行之海外仙山篇","少年歌行之血染天啟篇","Great Journey of Teenagers"]', 1784690324390);
