INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-waikiki', 'Nhà Trọ Waikiki', 'Welcome to Waikiki', 'https://phimimg.com/upload/vod/20250116-1/9554a4009e48897518965672ad56ea97.jpg', 'https://phimimg.com/upload/vod/20250116-1/3f24a722ca1743f14205a0fffcb3d4a7.jpg', '<p>Dong Goo, Joon Ki và Doo Sik, ba anh chàng cùng sống và quản lý một nhà nghỉ tên Waikiki. Chuyện không hay xảy đến khi nhà nghỉ có nguy cơ bị đóng cửa khiến cả ba phải lao đao tìm đủ mọi kế kiếm tiền. Chưa hết, sự bí ẩn của một bé gái cùng người mẹ đơn thân cũng làm đảo lộn cuộc sống của ba người.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Yi-kyung","avatar":""},{"name":"Kim Seon-ho","avatar":""},{"name":"Shin Hyun-soo","avatar":""},{"name":"Mun Ka-young","avatar":""},{"name":"An So-hee","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Bret Allan Lindquist","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["加油吧威基基","مرحبا بكم في وايكيكي","ไวกีกิ เกสต์เฮาส์อลเวง","Сміх у Вайкікі","Ласкаво просимо до Вайкікі","Eulachacha Waikiki","Welcome to Waikiki 2","으라차차 와이키키"]', 1784690324390);
