INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tro-waikiki', 'Nhà Trọ Waikiki', 'Welcome to Waikiki', 'nhà trọ waikiki welcome to waikiki lee yi-kyung kim seon-ho shin hyun-soo mun ka-young an so-hee kim ye-won bret allan lindquist 加油吧威基基 مرحبا بكم في وايكيكي ไวกีกิ เกสต์เฮาส์อลเวง сміх у вайкікі ласкаво просимо до вайкікі eulachacha waikiki welcome to waikiki 2 으라차차 와이키키', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-anh-troi-danh', 'Ông Anh Trời Đánh', 'Brother Of The Year', 'https://phimimg.com/upload/vod/20240205-1/f3ba8490c29789a9ddd1939c5d9b3168.jpg', 'https://phimimg.com/upload/vod/20240205-1/1e5da35498df66f275e862784f833aa7.jpg', '<p>Ông Anh Trời Đánh là bộ phim tình cảm hài kể về cặp anh em trái dấu Chut (Sunny) và Jane (Yaya). Nhưng đừng nhìn bề ngoài Chut như thế mà lầm về “bản lĩnh làm anh” nhé, hễ có cậu trai nào thử đến tán em gái mà xem, kiểu gì cũng bị ông anh này đuổi đi bằng hết (thực ra mục đích chính là trả thù ý mà!). Đó là lý do Jane giấu biệt mối quan hệ giữa mình với Moji (Nichkhun) – anh chàng điển trai lai Nhật, vì Jane ko muốn mọi sự “xôi hỏng bỏng không” như những lần trước. Nhưng đã là tình yêu thì làm sao mà giữ bí mật cho được? Khi Chut biết Jane và Moji lén quen nhau thì cả hai đã hẹn ước nghiêm túc và tính chuyện kết hôn luôn rồi. Vậy Chut có chịu để yên không? Chà chà, đã bảo rồi mà, cái gì làm cho em gái hạnh phúc thì ông anh trai “trời đánh” này sẽ không để nó xảy ra đâu!</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub + Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Sunny Suwanmethanont","avatar":""},{"name":"Yaya – Urassaya Sperbund","avatar":""},{"name":"Nichkhun Horvejkul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324390);
