INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-ngay-ben-em', '100 Ngày Bên Em', '100 Days Of Sunshine', 'https://phimimg.com/upload/vod/20250116-1/c6ff43ca3485d06469dac81207c97708.jpg', 'https://phimimg.com/upload/vod/20250116-1/440bfc766d279b163cc293b2b0f8a5dd.jpg', '<p>Chuyện phim 100 ngày bên em xoay quanh Ánh Dương (Khả Ngân) - một vlogger nổi tiếng, trẻ trung, và xinh đẹp trên trên mạng xã hội với cuộc sống khiến bao người phải ghen tỵ. &nbsp;Cô gái chuẩn bị tổ chức đám cưới trong mơ với chàng bạn trai đại gia Lê Huy (Bê Trần). Nhưng khi đang đắm chìm giữa niềm hạnh phúc, Ánh Dương bỗng suy sụp khi phát hiện ra khối u não, rồi bị người yêu ruồng bỏ. &nbsp;Để lấp vào vị trí chú rể còn trống trong đám cưới sắp sửa diễn ra, nữ vlogger đành tìm đến người bạn cũ Nhật Minh (Jun Phạm). Vốn là một game thủ danh tiếng, anh nay chỉ là kẻ vô công rỗi nghề, ăn bám vợ chồng cậu em trai Minh Sơn - Thu Nga (Gin Tuấn Kiệt - Tam Triều Dâng).</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Khả Ngân","avatar":""},{"name":"B Trần","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Gin Tuấn Kiệt","avatar":""},{"name":"Tam Triều Dâng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["100 Days of Sunshine","100 ngày bên em"]', 1784690324390);
