INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-mai-tuoi-17', 'Vẫn Mãi Tuổi 17', 'Still 17', 'https://phimimg.com/upload/vod/20250116-1/c90f8be9ad9b2fda212458dddd19f96f.jpg', 'https://phimimg.com/upload/vod/20250116-1/34f044158a41ecfbac4ec611afe499e4.jpg', '<p>Phim nói về Gong Woo Jin (Yang Se Jong) là một người đàn ông 30 tuổi độc thân và làm nghề thiết kế phim trường. Vì một chấn thương tâm lý từ 13 năm trước, anh không muốn có mối quan hệ nào với người khác. Khi Woo Seo Ri (Shin Hye Sun) 17 tuổi, cô rơi vào cơn hôn mê. 13 năm sau, cô tỉnh dậy. Độ tuổi tinh thần của cô vẫn là của cô bé 17 tuổi, nhưng giờ cô đã 30 tuổi rồi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yang Se-jong","avatar":""},{"name":"Shin Hye-sun","avatar":""},{"name":"Ahn Hyo-seop","avatar":""},{"name":"Ye Ji-won","avatar":""},{"name":"Wang Ji-won","avatar":""},{"name":"Jung Yoo-jin","avatar":""},{"name":"Yoon Sun-woo","avatar":""},{"name":"Park Si-eun","avatar":""},{"name":"Yoon Chan-young","avatar":""},{"name":"Ahn Seung-gyun","avatar":""},{"name":"Jo Hyun-sik","avatar":""},{"name":"Lee Do-hyun","avatar":""},{"name":"Kim Min-Seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Из 17 в 30","Тридцать, но семнадцать","雖已30但仍17","Мені 30, але ще 17","Мені 30, але досі 17","Мені 30, але 17","30, але 17","30 But 17","Thirty But Seventeen","서른이지만 열일곱입니다"]', 1784690324390);
