INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-len-dinh-kien', 'Vượt Lên Định Kiến', 'A Different View', 'https://phimimg.com/upload/vod/20250111-1/e1cd3a58facaa4ca1cc8d850ba7433fb.jpg', 'https://phimimg.com/upload/vod/20250111-1/71dd8c3a821f4ed59fd0cb1cbf815177.jpg', '<p>Phim lấy bối cảnh những năm 1920 ở Tây Ban Nha, tại một trường nữ sinh. Để tìm kiếm manh mối về một sự cố đã xảy ra với mình trong quá khứ, Teresa đến đây làm giáo viên. Đối mặt với phong cách dạy học truyền thống cùng đường lối cứng nhắc ở nơi đây, cô đã nỗ lực hết mình để giúp các cô gái trẻ tìm thấy tiếng nói và giành lấy sự tự chủ cho cuộc đời mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2018, 'Thuyết Minh', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Patricia López Arnaiz","avatar":""},{"name":"Macarena García","avatar":""},{"name":"Carla Campra","avatar":""},{"name":"Gloria Muñoz","avatar":""},{"name":"Ana Wagener","avatar":""},{"name":"Álvaro Mel","avatar":""},{"name":"Carlos Olalla","avatar":""},{"name":"Begoña Vargas","avatar":""},{"name":"Abril Montilla","avatar":""},{"name":"Lucía Díez","avatar":""},{"name":"Elena Gallardo","avatar":""},{"name":"Juanlu González","avatar":""},{"name":"Jordi Coll","avatar":""},{"name":"Melina Matthews","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La otra mirada"]', 1784690324390);
