INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tu-ho-lee', 'Quý Tử Họ Lee', 'The Rich Son', 'https://phimimg.com/upload/vod/20250111-1/d4f712b7b7f6bbc2f7887a3e5dc5b795.jpg', 'https://phimimg.com/upload/vod/20250111-1/d55438de57dc1fa9eb930e58768bea81.jpg', '<p>Chỉ sau một đêm, Lee Gwang Jae - quý tử giàu sang của một chuỗi nhà hàng nổi tiếng - bỗng trở thành kẻ không xu dính túi khi bố mắc nợ lớn, còn con riêng của mẹ kế lại lên tiếp quản công ty gia đình. Từ một cậu ấm chỉ biết ăn chơi, giờ đây Gwang Jae buộc phải nỗ lực hết mình để phát triển công thức nấu ăn mà bố anh đã dày công nghiên cứu và xây dựng lại mọi thứ từ hai bàn tay trắng.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2018, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Ji-hun","avatar":""},{"name":"Kim Joo-hyun","avatar":""},{"name":"Lee Kyu-han","avatar":""},{"name":"Hong Soo-hyun","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Lee Seung-yun","avatar":""},{"name":"Kim Min-gue","avatar":""},{"name":"Jeon Su-kyung","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Jung Bo-seog","avatar":""},{"name":"Kang Nam-gil","avatar":""},{"name":"Kim Yeong-ok","avatar":""},{"name":"Cha Seo-won","avatar":""},{"name":"Mi Ram","avatar":""},{"name":"Yoon Cheol-hyeong","avatar":""},{"name":"Elkie Chong","avatar":""},{"name":"Park Soon-cheon","avatar":""},{"name":"Park Jae-jung","avatar":""},{"name":"Shim Eu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["富家公子","Сын богатых родителей","С