INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-the-ma-vuong-phan-1', 'Dị Thế Ma Vương (Phần 1)', 'How Not To Summon A Demon Lord (Season 1)', 'https://phimimg.com/upload/vod/20250102-1/0d056cb07ff415e3d4e8cb7bc9b8d2ad.jpg', 'https://phimimg.com/upload/vod/20250102-1/f680591c6203bfa3ad29eb4f697bd740.jpg', '<p>Trong MMORPG Cross Reverie, Sakamoto Takuma tự hào về sức mạnh áp đảo của mình và được những player khác gọi là 『Ma Vương』. Một ngày kia, cậu được triệu hồi đến thế với khác với hình dáng trong game. Ở đó có hai người con gái cứ khăng khăng rằng mình là chủ triệu hồi. Takuma đã bị các cô gái áp dụng ma thuật nô lệ hóa dùng cho thú triệu hồi — Tuy nhiên, năng lực vốn có của cậu, 《Phản Hồi Ma Thuật》, đã kích hoạt! Chính các cô gái mới là người trở thành nô lệ! Takuma cảm thấy bối rối. Cậu tuy là ma thuật sư mạnh nhất, nhưng lại không có năng lực giao tiếp. Cậu chỉ có thể nói thành lời khi đóng vai Ma Vương như từng làm ở trong game!? Cuộc phiêu lưu ở thế giới khác của Ma Vương (đóng kịch) có sức mạnh tuyệt đối làm rung chuyển thế giới, bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaaki Mizunaka","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Yumi Hara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["异界少女召唤术","异界少女召唤术Ω","Isekai M