INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ki-dieu-o-motown-phan-1', 'Điều kì diệu ở Motown (Phần 1)', 'Motown Magic (Season 1)', 'https://phimimg.com/upload/vod/20241222-1/ab0beed1460820927eb041458dafaa9a.jpg', 'https://phimimg.com/upload/vod/20241222-1/0a3115f078b7a94f39152b99784d18d7.jpg', '<p>Có cọ vẽ thần kì trong tay, theo những giai điệu rộn rã của Motown, cậu bé Ben giàu trí tưởng tượng đã hô biến nghệ thuật đường phố để khắp chốn đều muôn phần rực rỡ.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Avia Fields","avatar":""},{"name":"Marissa Margaux","avatar":""},{"name":"Monie Mon","avatar":""},{"name":"Betsy Kenney","avatar":""},{"name":"Alex Thomas","avatar":""},{"name":"Heaven Beatbox","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Motown Magic"]', 1784690324391);
