INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-than-thanh-phan-1', 'Trò Chơi Thần Thánh (Phần 1)', 'Sacred Games (Season 1)', 'https://phimimg.com/upload/vod/20241222-1/3298edee4d26a60eb3b26eca58850773.jpg', 'https://phimimg.com/upload/vod/20241222-1/98fd6b8064f7c57975e9dcb7cc9b9a6c.jpg', '<p>Lấy bối cảnh ở Mumbai, Sacred Games đào sâu vào mạng lưới tổ chức tội phạm phức tạp, sự đồi bại, chính trị và gián điệp dưới sự khôi phục kinh tế của Ấn Độ. Đây là một kiệt tác của sự giàu sang xuất chúng và sức mạnh mà đan xen vào cuộc sống của những người đặc quyền, những người nổi tiếng, những người nghèo khổ và những kẻ khát máu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Nawazuddin Siddiqui","avatar":""},{"name":"Radhika Apte","avatar":""},{"name":"Neeraj Kabi","avatar":""},{"name":"Jitendra Joshi","avatar":""},{"name":"Rajshri Deshpande","avatar":""},{"name":"Saurabh Sachdeva","avatar":""},{"name":"Kubra Sait","avatar":""},{"name":"Anil Charanjeett","avatar":""},{"name":"Surveen Chawla","avatar":""},{"name":"Jatin Sarna","avatar":""},{"name":"Shalini Vatsa","avatar":""},{"name":"Sukhmani Sadana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Sacred Games"]', 1784690324391);
