INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-phan-2', 'Đế Chế (Phần 2)', 'Dynasty (Season 2)', 'https://phimimg.com/upload/vod/20241218-1/e1dc4e4d5d41accba04e4ec085f5a78e.jpg', 'https://phimimg.com/upload/vod/20241218-1/b2679a98ec6dda2c9592bc4cabdeafc8.jpg', '<p>Sau trận hỏa hoạn thảm khốc thiêu cháy dinh cơ của gia đình, nhà Carrington vươn lên từ đống đổ nát để tái dựng xây đế chế của mình -- và trở lại thời huy hoàng.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Gillies","avatar":""},{"name":"Grant Show","avatar":""},{"name":"Rafael De La Fuente","avatar":""},{"name":"Robert Christopher Riley","avatar":""},{"name":"Sam Adegoke","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"Maddison Brown","avatar":""},{"name":"Adam Huber","avatar":""},{"name":"Daniella Alonso","avatar":""},{"name":"Elaine Hendrix","avatar":""},{"name":"Sam Underwood","avatar":""},{"name":"Michael Michele","avatar":""},{"name":"Wakeema Hollis","avatar":""},{"name":"James Mackay","avatar":""},{"name":"Nathalie Kelley","avatar":""},{"name":"Nicollette Sh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Dinastia","Dynasty (Dinastia)","新豪门恩怨","豪门是非多","卡灵顿家族","王朝","Dynastie (2017)","Δυναστεία","다이너스티: 1%의 1%","Dynasty"]', 1784690324391);
