INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-bay-mat-tich-phan-1', 'Máy Bay Mất Tích (Phần 1)', 'Manifest (Season 1)', 'https://phimimg.com/upload/vod/20241217-1/480dd553be0c247a389e0b4ad8d70eb1.jpg', 'https://phimimg.com/upload/vod/20241217-1/32927aaa3fa29c68f74a0ac27423b364.jpg', '<p>Chuyến bay số hiệu 828 đã hạ cánh an toàn sau một chặng bay không mấy êm ả, phi hành đoàn và tất cả hành khách đều thở phào nhẹ nhõm. Tuy nhiên, họ được cho biết rằng thế giới đã trải qua 5 năm rưỡi kể từ lúc họ bước lên chuyến bay đó. Gia đình, bạn bè và đồng nghiệp của họ đã từ bỏ mọi nỗ lực tìm kiếm sau ngần ấy năm, và chấp nhận sự thật họ đã chết thì đột nhiên họ lại trở về. Đối mặt với điều tưởng chừng như không thể này, tất cả đều không thể giải thích được, chuyện gì đã xảy ra với họ?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Melissa Roxburgh","avatar":""},{"name":"Josh Dallas","avatar":""},{"name":"Athena Karkanis","avatar":""},{"name":"J.r. Ramirez","avatar":""},{"name":"Luna Blaise","avatar":""},{"name":"Jack Messina","avatar":""},{"name":"Parveen Kaur","avatar":""},{"name":"Tim Moriarty","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Manifeste","命运航班","Manifiesto","Manifest"]', 1784690324391);
