INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-than-phan-2', 'Hộ Thần (Phần 2)', 'The Protector (Season 2)', 'https://phimimg.com/upload/vod/20241203-1/da2999f9bfded359d16898786ebba75c.jpg', 'https://phimimg.com/upload/vod/20241203-1/f86ff35d732472a89d8909021f441546.jpg', '<p>Một thanh niên phát hiện ra rằng anh ta có sức mạnh đặc biệt. Nhưng anh cần phải học cách sử dụng các năng lực này để bảo vệ thành phố và toàn nhân loại chống lại các thế lực đen tối muốn tiêu diệt Istanbul. Trong hành trình này, không có lựa chọn nào khác ngoài hành động với bạn bè, những người sẽ giúp anh ta.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2018, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Mehmet Kurtulus","avatar":""},{"name":"Çagatay Ulusoy","avatar":""},{"name":"Hazar Ergüçlü","avatar":""},{"name":"Okan Yalabik","avatar":""},{"name":"Ayça Aysin Turan","avatar":""},{"name":"Yurdaer Okur","avatar":""},{"name":"Burçin Terzioglu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '["The Protector","Le Protecteur","Χακάν: Ο Προστάτης","Защитник","الحارس","Hakan: Muhafız"]', 1784690324391);
