INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-cung-ke', 'Thâm Cung Kế', 'Deep In The Realm Of Conscience', 'https://phimimg.com/upload/vod/20241203-1/793f2ff2aaa0b04729ac7962b70ac1ac.jpg', 'https://phimimg.com/upload/vod/20241203-1/d64c2ae69c71ec283cd349fff36b92f1.jpg', '<p>Vào những năm Đường Long, Lý Long Cơ (do Mã Tuấn Vỹ đóng) bắt tay với Thái Bình Công chúa (do Trần Vỹ đóng), phát động chính biến. Họ lập mưu tiêu diệt gia tộc của Vi hậu (do Mễ Tuyết đóng) – kẻ đang thao túng triều đình, làm xói mòn hệ thống pháp luật Nhà Đường.

Lý Long Cơ và Thái Bình Công chúa ủng hộ Lý Đán (do Lý Long Cơ đóng) nắm giữ triều cương. Tưởng rằng lần đảo chính này đã đem lại sự bình yên cho chốn cung cấm. Nào ngờ, những cơn sóng ngầm của các thế lực tranh quyền đoạt vị vẫn cuồn cuộn dâng trào.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 17, 2018, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tiêu Chính Nam","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Mễ Tuyết","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Mã Tuấn Vỹ","avatar":""},{"name":"Lưu Tâm Du","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["宫心计2·深宫计","宫心计2","深宮計2","宮心計2：深宮計","궁심계2심궁계","궁심계","궁심계2: 심궁계","Deep In The Realm Of Conscience","宮心計2深宮計"]', 1784690324391);
