INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-cung-phan-1', 'Con Cưng (Phần 1)', 'Baby (Season 1)', 'https://phimimg.com/upload/vod/20241128-1/dca9ee99a5c4c3ac4cec4b2f1f93121b.jpg', 'https://phimimg.com/upload/vod/20241128-1/c0ac6051e8869f87654e79e7ff339e16.jpg', '<p>Con Cưng (Phần 1) dựa trên câu chuyện có thật xoay quanh cuộc sống của hai nữ sinh rich kids Chiara (Benedetta Porcaroli) và Ludovica (Alice Pagani) đến từ giới thượng lưu của Rome, Ý. Chán nản với cuộc sống áp lực, giả tạo bị chi phối bởi đồng tiền, hai cô nàng tuổi teen rủ nhau làm gái mại dâm ban đêm. Chiara và Ludovica đã tìm thấy tự do tình dục và độc lập về tài chính trong việc làm gái ngành. Dù dựa trên câu chuyện có thật, thế nhưng Baby vẫn bị Trung tâm quốc gia phòng chống lạm dụng Mỹ lên án vì cổ súy nạn buôn bán tình dục.. Người mẹ của một trong hai nữ sinh ngoài đời đã bị bắt và phạt tù 6 năm vì cố tình tham gia vào đường dây mại dâm này để kiếm tiền.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mehdi Nebbou","avatar":""},{"name":"Galatea Ranzi","avatar":""},{"name":"Benedetta Porcaroli","avatar":""},{"name":"Alice Pagani","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Baby/ベイビー","Детка","Малышка","Baby"]', 1784690324391);
