INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-xui-xeo-phan-2', 'Phù thủy xui xẻo (Phần 2)', 'The Worst Witch (Season 2)', 'https://phimimg.com/upload/vod/20241118-1/4361fa7b7852625e2ef1a41e47728661.jpg', 'https://phimimg.com/upload/vod/20241118-1/fbc23b97a9d510da63d4321e51c28fe4.jpg', '<p>Năm thứ hai tại Học viện Cackle đồng nghĩa với gấp đôi ma thuật, cùng cả những trò tinh nghịch dành cho cô học viên phù thủy Mildred Hubble hậu đậu và bạn bè.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 5, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Bella Ramsey","avatar":""},{"name":"Lydia Page","avatar":""},{"name":"Clare Higgins","avatar":""},{"name":"Raquel Cassidy","avatar":""},{"name":"Meibh Campbell","avatar":""},{"name":"Jenny Richardson","avatar":""},{"name":"Miriam Petche","avatar":""},{"name":"Tallulah Milligan","avatar":""},{"name":"Wendy Craig","avatar":""},{"name":"Shauna Shim","avatar":""},{"name":"Megan Hughes","avatar":""},{"name":"Tamara Smart","avatar":""},{"name":"Trixie Hyde","avatar":""},{"name":"Kitty Slack","avatar":""},{"name":"Ynez Williams","avatar":""},{"name":"Mina Anwar","avatar":""},{"name":"Dagny Rollins","avatar":""},{"name":"Kelsey C","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["A Pior das Bruxas","魔法学校","Σκανδαλιάρα Μάγισσα","Una Strega Imbranata","꼴찌 마녀 밀드레드","The Worst Witch"]', 1784690324391);
