INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-the-gioi-game-phan-3', 'Lạc Vào Thế Giới Game (Phần 3)', 'Overlord (Season 3)', 'https://phimimg.com/upload/vod/20241116-1/ac8b67a4a24871fecffca4cc8fcbb7e9.jpg', 'https://phimimg.com/upload/vod/20241116-1/84629fcd16b9033d2025056f1e2d33ef.jpg', '<p>Bộ phim lấy bối cảnh năm 2138 khi con người không còn phân biệt được đâu là thực đâu là ảo được nữa. Yggdrasil, một trò chơi trực tuyến nổi tiếng đã âm thầm bị đóng cửa trong quá khứ. Tuy nhiên một top-player tên Momonga đã quyết định sống chết cùng với trò chơi này và sau đó hắn đã trở thành một tên Cốt Bạch Hắc Ma có sức mạnh lớn nhất trong trò chơi này. Thế giới dần đổi thay, cho đến khi các NPC dần dần có cảm xúc của một con người. Không gia đình, không bạn bè, không việc làm hay chỗ đứng trong xã hội, hắn quyết định chiếm lấy thế giới này cho riêng mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Hino","avatar":""},{"name":"Yumi Hara","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Akeno Watanabe","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Masayuki Katou","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Hiromi Igarashi","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kei Shindo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["不死者之王","OVERLORD","Ōbārōdo","オーバーロードⅢ","オーバーロードⅡ","オーバーロード2","オーバーロード3","Overlord Ple Ple Pleiades","Soushuuhen Overlord","オーバーロードⅣ","Overlord","ПОВЕЛИТЕЛЬ","Властелин","Владыка","Повелитель 1","Повелитель 4","Повелитель 3","Повелитель 2","โอเวอร์ลอร์ด","Оверлорд 3","Оверлорд Ⅲ","Оверлорд 2","Оверлорд Ⅱ","Оверлорд II","Оверлорд III","Оверлорд","Overlord 3","Overlord Ⅱ","Overlord II","Overlord III","Overlord Ⅲ","Overlord 2","Overlord IV","Lạc Vào Thế Giới Game","オーバーロード"]', 1784690324391);
