INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-voi-vo', 'Ngoại Tình Với Vợ', 'Adultery With Wife', 'https://phimimg.com/upload/vod/20241114-1/58c317db3dcc65a46ad163c690233c6c.jpg', 'https://phimimg.com/upload/vod/20241114-1/2cf50bba8286c8fdbb71854211e3222c.jpg', '<p>Thủy Tiên - người vợ chung thủy, một lòng một dạ vì chồng vì gia đình chồng. Cô sống vì gia đình chồng trong suốt cuộc hôn nhân, chịu đựng sự hà khắc và cay nghiệt của mẹ chồng … Sau khi cô phát hiện ra bản thân mình bị chồng lừa dối. Từ cô gái hiền lành, khả ái, Cô bỗng trở nên mạnh mẽ, cá tính và mang mối hận trả thù.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phan Thị Mơ","avatar":""},{"name":"Nhan Phúc Vinh","avatar":""},{"name":"Trương Nam Thành","avatar":""},{"name":"Bích Huyền","avatar":""},{"name":"Hà Trí Quang","avatar":""},{"name":"Hoàng Trinh","avatar":""},{"name":"Phương Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The New Adventures of the Black Stallion","The Adventures of the Black Stallion"]', 1784690324391);
