INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-tich-tren-nui-phan-1', 'Vết Tích Trên Núi (Phần 1)', 'Signs (Season 1)', 'https://phimimg.com/upload/vod/20241113-1/599691b9825ef86c14bdd1ec094cc7a2.jpg', 'https://phimimg.com/upload/vod/20241113-1/fcba978502fec31e2ec3c621ff3a6669.jpg', '<p>Vết Tích Trên Núi kể về khi vụ giết một phụ nữ trẻ có điểm tương đồng với vụ án chưa có lời giải từ thập kỷ trước, một chỉ huy cảnh sát mới phải phá vỡ sự im lặng bao trùm thị trấn Núi Owl.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andrzej Konopka","avatar":""},{"name":"Helena Sujecka","avatar":""},{"name":"Piotr Trojan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Signs","Znaki"]', 1784690324391);
