INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gao-nep-gao-te-phan-1', 'Gạo Nếp Gạo Tẻ (Phần 1)', 'Sticky Rice And Plain Rice (Season 1)', 'https://phimimg.com/upload/vod/20241113-1/fadfc5cce22417cb5c362d7ae2f0200f.jpg', 'https://phimimg.com/upload/vod/20241113-1/4e44578827b8d77fb64837b5acf1b37a.jpg', '<p>Chuyện xoay quanh gia đình bà Mai ông Vương làm nghề giáo, ông bà luôn mong ước con cái thành đạt có địa vị xã hội. Hương - cô con gái đầu học vấn thấp, lấy chồng nghèo, có con trước làm bà xấu hổ. Ngược lại, bà rất cưng chiều cô con gái thứ hai tên Hân, vì cô lọt vào top 10 Hoa hậu Việt Nam và có chồng doanh nhân giàu có. Cô thứ ba tên Minh cũng khiến bà nhức đầu khi tự ý bỏ nghề y để chuyển sang biên kịch. Sự thiên vị tình cảm của bà Mai tưởng chừng bị vùi lấp cho đến khi gia đình Hân phá sản. Hàng loạt biến cố, những câu chuyện cười ra nước mắt trong quan hệ gia đình nổ ra ác liệt.</p>', 'Hoàn Tất (109/109)', 109, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSND Hồng Vân","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Lê Phương","avatar":""},{"name":"Thúy Ngân","avatar":""},{"name":"Hoàng Anh","avatar":""},{"name":"Băng Di","avatar":""},{"name":"Phương Hằng","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"NSƯT Minh Đức","avatar":""},{"name":"Mai Huỳnh","avatar":""},{"name":"Puka","avatar":""},{"name":"Ngọc Thuận","avatar":""},{"name":"Thùy Trang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Gạo Nếp Gạo Tẻ"]', 1784690324391);
