INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khep-lai-qua-khu', 'Khép Lại Quá Khứ', 'Closing The Past', 'https://phimimg.com/upload/vod/20241104-1/a52efd5105f7741603bd6246f5ae5894.jpg', 'https://phimimg.com/upload/vod/20241104-1/c7e47078a02056b4c51b9944ecec6356.jpg', '<p>“Cây độc không trái, gái độc không con” chính là nỗi đau tột cùng của mỗi nàng dâu. Thủy đã gánh chịu sự chế giễu này suốt 7 năm kết hôn với Việt. Vì thế, cả hai vợ chồng quyết định nhờ người đẻ thuê để mưu cầu cuộc sống trọn vẹn. Nhưng chính lúc này đây, sóng gió mới thực sự ập đến.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trung Dũng","avatar":""},{"name":"Ngọc Lan","avatar":""},{"name":"Thanh Bình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["السابق: حارس الكنز","Stealer-七个朝鲜通报","Karma: Seven Joseon Notices","Stealer: Seven Joseon Coins","تاوان: هفت هشدار چوسان","نتیجه عمل: هفت هشدار چوسان","카르마: 일곱 개의 조선통보","حاميها حراميها","스틸러: 일곱 개의 조선통보"]', 1784690324391);
