INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-hi-cong-luoc', 'Diên Hi Công Lược', 'Story of Yanxi Palace', 'https://phimimg.com/upload/vod/20240802-1/6398b13377cec33648c4b9e596782642.jpg', 'https://phimimg.com/upload/vod/20240802-1/2b9eb922cbcee996aa5ff17077bc27ff.jpg', '<p>Bộ phim Diên Hi Công Lược lấy bối cảnh những năm đầu thời đại Càn Long, thiếu nữ Ngụy Anh Lạc (Ngô Cẩn Ngôn) vào cung làm cung nữ để điều tra chân tướng về cái chết của người chị gái và thề giành lại công lý cho chị mình. Phú Sát hoàng hậu (Tần Lam) là người hiền đức, tuân theo lễ pháp, lo lắng Anh Lạc lầm đường lạc lối, vì vậy luôn tận lực trợ giúp và quan tâm cô. Dưới sự dạy bảo của hoàng hậu, Ngụy Anh Lạc từng bước trưởng thành và trở thành một nữ quan chính trực, kiên cường, bỏ lại lòng oán hận để sống một cuộc sống đúng đắn. Sau đó hoàng hậu bất hạnh qua đời, khiến Ngụy Anh Lạc đối với Càn Long (Nhiếp Viễn) hiểu lầm chồng chất, hai người từ căm ghét lẫn nhau cuối cùng dần thấu hiểu và giúp đỡ đối phương. Anh Lạc bằng sự dũng cảm, trí thông minh linh hoạt, ý chí rộng lớn đã hóa giải những khó khăn trùng điệp chốn cung đình, cuối cùng trở thành Hoàng Quý phi giúp đỡ hoàng đế Càn Long xây dựng thời thái bình thịnh thế.</p>', 'Hoàn Tất (70/70)', 70, 'series', 'completed', 13, 2018, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"吴谨言","avatar":""},{"name":"聶遠","avatar":""},{"name":"Charmaine Sheh","avatar":""},{"name":"秦嵐","avatar":""},{"name":"許凱","avatar":""},{"name":"Wang Yuanke","avatar":""},{"name":"Tan Zhuo","avatar":""},{"name":"Zhang Jiani","avatar":""},{"name":"Jiang Zixin","avatar":""},{"name":"Su Qing","avatar":""},{"name":"王冠逸","avatar":""},{"name":"Shumei Lian","avatar":""},{"name":"Li Chun''ai","avatar":""},{"name":"宋春麗","avatar":""},{"name":"Xu Baihui","avatar":""},{"name":"Sookie Pan","avatar":""},{"name":"Lin Chenhan","avatar":""},{"name":"Gao Yang","avatar":""},{"name":"Huang Shiliang","avatar":""},{"name":"Tang Yang Yang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324391);
