INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-nhap', 'Xé Nháp', 'A Rough Draft', 'https://phimimg.com/upload/vod/20241031-1/185c23acd5ab63b034eec0ae0bb0c10a.jpg', 'https://phimimg.com/upload/vod/20241031-1/c4fb2ae06a246746a14ca62439d62338.jpg', '<p>Vốn chỉ là một lập trình viên đang lên kế hoạch cầu hôn bạn gái, bỗng một ngày, Kirill bị lãng quên ngay trong thế giới của mình. Và đó chỉ là mở đầu cho những sự thật kinh hoàng phía sau.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Nikita Volkov","avatar":""},{"name":"Severija Janusauskaite","avatar":""},{"name":"Vilen Babichev","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Draft","Chernovik","A Rough Draft","Világok őre","Nanečisto","I guardiani dei mondi","O Guardiao dos Mundos","Le Gardien des mondes","Черновик"]', 1784690324391);
