INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-muon-thoi-gian-ngung-lai', 'Khoảnh Khắc Muốn Thời Gian Ngừng Lại', 'About Time', 'https://phimimg.com/upload/vod/20241026-1/ffdcb560e36adcb416274aa64f1ca010.jpg', 'https://phimimg.com/upload/vod/20241026-1/383101667910dc796087e4d69506ac1a.jpg', '<p>Tình cảm nảy sinh giữa một nữ diễn viên nhạc kịch sắp lìa đời và một người đàn ông với khả năng ngăn chiếc đồng hồ sinh mệnh của cô đếm ngược.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이상윤","avatar":""},{"name":"이성경","avatar":""},{"name":"임세미","avatar":""},{"name":"김동준","avatar":""},{"name":"한승연","avatar":""},{"name":"로운","avatar":""},{"name":"정동환","avatar":""},{"name":"김해숙","avatar":""},{"name":"나영희","avatar":""},{"name":"장광","avatar":""},{"name":"강기둥","avatar":""},{"name":"김규리","avatar":""},{"name":"민성욱","avatar":""},{"name":"Kim Sa-hee","avatar":""},{"name":"Oh Ah-Rin","avatar":""},{"name":"태인호","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Meomchoogo Sipeun Soongan: Eobawoottaim","Meomchugo Sip-eun Sun-gan: Eobaut-taim","Вовремя","О времени","หยุดเวลาหารัก","想暫停的瞬間：About Time","想停止的瞬間：About Time","A Moment I Want to Stop: About Time","About Time","멈추고 싶은 순간: 어바웃타임"]', 1784690324391);
