INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoanh-khac-muon-thoi-gian-ngung-lai', 'Khoảnh Khắc Muốn Thời Gian Ngừng Lại', 'About Time', 'khoảnh khắc muốn thời gian ngừng lại about time 이상윤 이성경 임세미 김동준 한승연 로운 정동환 김해숙 나영희 장광 강기둥 김규리 민성욱 kim sa-hee oh ah-rin 태인호 meomchoogo sipeun soongan: eobawoottaim meomchugo sip-eun sun-gan: eobaut-taim вовремя о времени หยุดเวลาหารัก 想暫停的瞬間：about time 想停止的瞬間：about time a moment i want to stop: about time about time 멈추고 싶은 순간: 어바웃타임', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-le-la-yeu', 'Có Lẽ Là Yêu', 'About Is Love', 'https://phimimg.com/upload/vod/20241026-1/1d87ea0c5fcd4e77ae9612e4bf7e1509.jpg', 'https://phimimg.com/upload/vod/20241026-1/af505e555451207b58272532bdc99aaf.jpg', '<p>Biến cố của gia đình lúc mười tám tuổi đã khiến Vệ Khanh mắc bệnh sạch sẽ nghiêm trọng, không thể tiếp xúc với người khác, nhưng là tổng tài của Vân Mã, Vệ Khanh đã gặp phải rất nhiều rắc rối vì nó. Cực khổ tìm người có duyên suốt mười năm mà không có kết quả, thế rồi vào năm hai mươi tám tuổi, vì say rượu ngoài ý muốn mà Vệ Khanh đã gặp gỡ sinh viên mỹ thuật Chu Thị mười tám tuổi, qua nhiều lần tiếp xúc, thế mà lại không hề khó chịu. Thế nên, một &quot;hợp đồng yêu đương&quot; với mục đích chữa bệnh được mở ra từ đây, chọc ghẹo, đấu khẩu, giúp đỡ lẫn nhau, Vệ Khanh dần dần nảy sinh tình cảm với Chu Thị, đồng thời, trong lúc loại bỏ tâm bệnh cho Vệ Khanh, Chu Thị cũng nhờ Vệ Khanh cổ vũ mà buông bỏ mối tình đơn phương vô vọng, một lần nữa tìm lại mục đích mới của cuộc đời. Mà hai chị em bên cạnh Chu Thị, cũng đã diễn giải quy luật tình yêu IQ cao của học bá và học thần, đôi hoan hỉ oan gia là nữ thần hoạt bát và thiên tài nghệ thuật sống chung với nhau, đều đạt được tình yêu của riêng mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngạn Hi","avatar":""},{"name":"Hứa Hiểu Nặc","avatar":""},{"name":"Thái Ất Gia","avatar":""},{"name":"Dương Hân Dĩnh","avatar":""},{"name":"Hồ Văn Triết","avatar":""},{"name":"Lý Tâm Bác","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["大约是爱2","Maybe It''s Love","大约是爱"]', 1784690324391);
