INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-le-la-yeu', 'Có Lẽ Là Yêu', 'About Is Love', 'có lẽ là yêu about is love ngạn hi hứa hiểu nặc thái ất gia dương hân dĩnh hồ văn triết lý tâm bác 大约是爱2 maybe it''s love 大约是爱', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-quan-100-ngay', 'Lang Quân 100 Ngày', '100 Days My Prince', 'https://phimimg.com/upload/vod/20241026-1/9734318d4e63666b185a785bf08b1ea7.jpg', 'https://phimimg.com/upload/vod/20241026-1/9f5d6c7d935284009990311ff7744423.jpg', '<p>Lee Yool là thế tử, nhưng chàng đột ngột biến mất. Chàng quay lại cung điện sau 100 ngày. Chuyện gì đã xảy ra với thế tử trong 100 ngày qua? Trong khi đó, Hong Sim thông minh và điều hành cơ quan điều tra tư đầu tiên ở Joseon. Lee Yool ngã xuống vách núi và suýt chết vì một vụ cố ý ám sát. Chàng mất trí nhớ và đi loanh quanh trong 100 ngày với một cái tên và danh phận mới. Trong thời gian này, chàng gặp Hong Sim.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"도경수","avatar":""},{"name":"남지현","avatar":""},{"name":"조성하","avatar":""},{"name":"조한철","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"Ji Min-hyuk","avatar":""},{"name":"김선호","avatar":""},{"name":"정해균","avatar":""},{"name":"한소희","avatar":""},{"name":"허정민","avatar":""},{"name":"김재영","avatar":""},{"name":"조현식","avatar":""},{"name":"안석환","avatar":""},{"name":"김기두","avatar":""},{"name":"이민지","avatar":""},{"name":"이준혁","avatar":""},{"name":"Jung Ji-hoon","avatar":""},{"name":"Heo Jung-eun","avatar":""},{"name":"Jeong Joon-won","avatar":""},{"name":"도지한","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Mi Príncipe en Cien Días [100 Days My Prince]","백일의 낭군님","รัก 100 วันของฉันและองค์ชาย","100 Days My Prince","Lang Quân 100 Ngày"]', 1784690324391);
