INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tien-don-dep', 'Cô Tiên Dọn Dẹp', 'Clean with Passion for Now', 'https://phimimg.com/upload/vod/20241017-1/f2fe76c97869a47039cf6be49f0b3bba.jpg', 'https://phimimg.com/upload/vod/20241017-1/a3a03abd029073f5e86764db9b0bf4a2.jpg', '<p>Phim kể về Jang Sun Gyul sở hữu một công ty làm sạch. Anh ghét vi trùng và có một nỗi ám ảnh với việc giữ mọi thứ lấp lánh sạch sẽ. Anh gặp Gil Oh Sol, một người phụ nữ với cá tính tươi sáng, hoàn toàn trái ngược với Sun Gyul. Cô gặp anh ta và bắt đầu giúp anh ta đối mặt với chứng sợ vi trùng của mình. Trong quá trình nhận được sự giúp đỡ của cô, anh đã yêu Gil Oh Sol.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김유정","avatar":""},{"name":"윤균상","avatar":""},{"name":"송재림","avatar":""},{"name":"유선","avatar":""},{"name":"안석환","avatar":""},{"name":"김원해","avatar":""},{"name":"민도희","avatar":""},{"name":"고건한","avatar":""},{"name":"이도현","avatar":""},{"name":"Cha In-Ha","avatar":""},{"name":"배윤경","avatar":""},{"name":"Choi Yoo-song","avatar":""},{"name":"Lee Kyu-sub","avatar":""},{"name":"Yang Hak-jin","avatar":""},{"name":"최유리","avatar":""},{"name":"손병호","avatar":""},{"name":"Jung Ji-hoon","avatar":""},{"name":"김혜은","avatar":""},{"name":"Kim Ki-nam","avatar":""},{"name":"김정영","avatar":""},{"name":"Koo Ja-geon","avatar":""},{"name":"손상연","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ildan Tteugeopge Cheongsohara","일단 뜨겁게 청소하라!!","В страстных объятиях уборки","Приберись получше","Уборка со страстью","รักนี้ สะอาดเนี้ยบ","First, Clean Passionately","Clean with Passion for Now!!","Clean Up Like