INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-tien-don-dep', 'Cô Tiên Dọn Dẹp', 'Clean with Passion for Now', 'cô tiên dọn dẹp clean with passion for now 김유정 윤균상 송재림 유선 안석환 김원해 민도희 고건한 이도현 cha in-ha 배윤경 choi yoo-song lee kyu-sub yang hak-jin 최유리 손병호 jung ji-hoon 김혜은 kim ki-nam 김정영 koo ja-geon 손상연 ildan tteugeopge cheongsohara 일단 뜨겁게 청소하라!! в страстных объятиях уборки приберись получше уборка со страстью รักนี้ สะอาดเนี้ยบ first, clean passionately clean with passion for now!! clean up like it''s hot 일단 뜨겁게 청소하라', '');
