INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('b-su-khoi-dau-phan-1', 'B: Sự Khởi Đầu (Phần 1)', 'B: The Beginning (Season 1)', 'b: sự khởi đầu (phần 1) b: the beginning (season 1) hirata hiroaki kaji yuki seto asami touchi hiroki inaba minoru koshimizu ami toyonaga toshiyuki tanaka shintaro goto atsushi morikawa toshiyuki ishikawa kaito sato satomi kitada yu saiga mitsuki nakai kazuya kameda nozomi awane makoto ter 彼之初 b the beginning b le commencement パーフェクト・ボーンズ b：the beginning ビーザビギニング идеальные кости би: начало бі: початок b: початок — спадщина бі: початок. спадщина бі: початок — спадщина b: початок. спадщина b: the beginning succession b the beginning b: the beginning', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-thanh-xuan-cua-chung-ta', 'Thời Thanh Xuân Của Chúng Ta', 'Our Youth', 'https://phimimg.com/upload/vod/20241007-1/dce4c7772ab8331163f4590bc863d528.jpg', 'https://phimimg.com/upload/vod/20241007-1/f856a211336eddeeca934474771b1738.jpg', '<p>Thời Thanh Xuân Của Chúng Ta - Our Youth - là bộ phim kể về một thành phố nhỏ ở miền nam vào những năm cuối thập niên 80 của thế kỷ XX, nơi đây có cô gái Cao Tiểu Mẫn cùng với 3 người chị em của mình, 4 cô gái với 4 tính cách khác nhau, còn có những bậc phụ huynh muộn phiền vì những chuyện thường ngày và vui vẻ vì những điều rất đỗi bình thường. Một bên là giấc mơ đỗ đại học và những giận hờn của tình bạn, một bên là tình yêu ngây ngô mới chớm nở, có cãi cọ cũng có nổi loạn và cả hiểu chuyện, trải qua năm tháng thanh xuân những thứ được và mất, từ những vất vả không dễ cảm nhận được của cha mẹ, các con dần dần khôn lớn. Năm gia đình ở Cao Đài Môn, mỗi nhà mỗi cảnh, cũng không ngừng phải đối diện với biết bao biến cố. Nhà Cao Tiểu Mẫn vì sửa nhà mà vay nợ còn bố thì thất nghiệp, bố Báo Tử xuống biển khởi nghiệp làm ăn phát đạt, bệnh nghề nghiệp gây khó khăn. Trong cuộc sống hàng xóm láng giềng với nhau không tránh khỏi va chạm, nhưng họ vẫn quan tâm chăm sóc lẫn nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Kỳ","avatar":""},{"name":"Quách Gia Hạo","avatar":""},{"name":"Khang Ninh","avatar":""},{"name":"Tiền Đông Ni","avatar":""},{"name":"Trương Bắc Bắc","avatar":""},{"name":"Trường Long","avatar":""},{"name":"Thạch Tử Thần","avatar":""},{"name":"Khấu Chân Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们的青春期"]', 1784690324391);
