INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-khung-long-phieu-luu-den-vung-nui-lua', 'Vua Khủng Long: Phiêu Lưu Đến Vùng Núi Lửa', 'Dino King: Journey To Fire Mountain', 'https://phimimg.com/upload/vod/20241004-1/7f086ff906ed9c024015a19ff3245f55.jpg', 'https://phimimg.com/upload/vod/20241004-1/c6851ac5aefc6cc96c851bc9a9529b3a.jpg', '<p>Speckles, một con khủng long tarbosaurus hung dữ và đứa con trai nhỏ của hắn, đang thương tiếc sự mất mát của gia đình trong một trận chiến hoành tráng, đi lang thang khắp các vùng đất để tìm kiếm thức ăn, phiêu lưu và hòa bình. Dưới sự giám sát của bố, Junior lớn lên khỏe mạnh nhưng lại có tính cách quá tự tin do tuổi còn nhỏ. Sau một lần chạm trán khiến Junior bị bắt cóc, Speckles dấn thân vào cuộc phiêu lưu đến tận cùng trái đất để tìm con trai mình. Gặp phải bạn bè và kẻ thù, đồng minh và kẻ thù, Speckles sẽ không dừng lại và sẽ lao vào mọi ngóc ngách để cứu con cháu của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박희순","avatar":""},{"name":"라미란","avatar":""},{"name":"김성균","avatar":""},{"name":"김응수","avatar":""},{"name":"Park Jung-geum","avatar":""},{"name":"Yeon Ji-won","avatar":""},{"name":"김흥래","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["The Dino King 2","Speckles: The Tarbosaurus 2","점박이 한반도 공룡 2-새로운 낙원","Dino King 2","Le dernier des dinosaures","점박이 한반도의 공룡 2: 새로운 낙원"]', 1784690324391);
