INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-vong-phap-luat', 'Ngoài Vòng Pháp Luật', 'Outlawed', 'https://phimimg.com/upload/vod/20241004-1/571a530d7d0d4ecbc8a5581e09d3d7de.jpg', 'https://phimimg.com/upload/vod/20241004-1/8cdbf69908ed295a0f8cc7112d2ba4fe.jpg', '<p>Một cựu Biệt kích Thủy quân lục chiến Hoàng gia phát hiện ra bằng chứng có thể hạ bệ một quan chức tham nhũng và khiến anh ta phải ngồi tù suốt đời. Khi người yêu thời thơ ấu của anh bị bắt cóc, nhiệm vụ của anh là giải cứu cô ấy và không để bất cứ điều gì cản đường anh.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Adam Collins","avatar":""},{"name":"Emmeline Hartley","avatar":""},{"name":"Andy Calderwood","avatar":""},{"name":"Andre Squire","avatar":""},{"name":"Tina Harris","avatar":""},{"name":"Tobias Fries","avatar":""},{"name":"Tonia Misuzu Dorrington","avatar":""},{"name":"Jessica Norris","avatar":""},{"name":"Rose Barker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Heart of Chaos","Outlawed"]', 1784690324391);
