INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-10', 'Gia Đình Hiện Đại (Phần 10)', 'Modern Family (Season 10)', 'https://phimimg.com/upload/vod/20241001-1/28082450c064a23d7945505e3b4b1737.jpg', 'https://phimimg.com/upload/vod/20241001-1/ba7435ef4f1cfbf2e6e4a12cdcf4ec10.jpg', '<p>Khi mùa thứ mười bắt đầu, Jay được dự đoán sẽ trở thành đại nguyên soái trong cuộc diễu hành ngày 4 tháng 7, khiến Pritchett-Dunphy-Tuckers đốt quá nhiều pháo hoa. Phil tình cờ có cơ hội nghề nghiệp mới, trong khi Claire vật lộn với vai trò có khả năng thay đổi của mình trong gia đình. Trong khi đó, Gloria bị ám ảnh bởi mối quan hệ của Manny và các hoạt động ngoại khóa của Joe. Đại gia đình đối phó với cái chết, nhưng họ cũng tiến hóa, với nhiều tiếng cười hơn bao giờ hết.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324391);
