INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-ma-phien-toai', 'Bạn Ma Phiền Toái', 'The Soul-Mate', 'https://phimimg.com/upload/vod/20240922-1/907503dc5a79e44c57416d35112e66c1.jpg', 'https://phimimg.com/upload/vod/20240922-1/0213be0ae0d7f1fa4c8a1fbe461ed42a.jpg', '<p>Jang-su (Ma Dong-seok) và Tae-jin (Kim Young-kwang) sở hữu cá tính hoàn toàn đối lập. Là một võ sư nổi tiếng, nhưng Jang-soo lại tỏ ra ích kỷ và chẳng bao giờ chịu giúp đỡ người hoạn nạn. Tất cả những gì anh quan tâm chỉ là lo lắng chữa trị căn bệnh tim bẩm sinh cho cô con gái nhỏ Do-kyung (Choi Yoo-ri). Trong khi đó, Tae-jin lại là một viên cảnh sát đầy nhiệt huyết, luôn đấu tranh cho chính nghĩa. Vì theo dõi một đường dây buôn bán phụ nữ trái phép, anh bị nhóm xã hội đen hãm hại.
 Là người duy nhất nhìn thấy linh hồn của Tae-jin, Jang-su đành bất đắc dĩ giúp đỡ viên cảnh sát đòi lại công bằng.</p>', 'Full', 1, 'single', 'completed', 5, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"마동석","avatar":""},{"name":"김영광","avatar":""},{"name":"이유영","avatar":""},{"name":"최귀화","avatar":""},{"name":"주진모","avatar":""},{"name":"최유리","avatar":""},{"name":"Heo Jae-ho","avatar":""},{"name":"고규필","avatar":""},{"name":"Bae Jung-hwa","avatar":""},{"name":"Kang Seung-wan","avatar":""},{"name":"Yoon Hee-won","avatar":""},{"name":"Han Soo-hyun","avatar":""},{"name":"이영석","avatar":""},{"name":"Ye Jung-hwa","avatar":""},{"name":"Cha Soon-hyeong","avatar":""},{"name":"김선문","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Wonderful Ghost","Wondeopool Goseuteu","鬼神拍档","与鬼同行：大叔追凶","The Soul-Mate","نیمه گمشده","روح شگفت‌انگیز","원더풀 고스트"]', 1784690324391);
