INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('retsuko-hung-hang-phan-1', 'Retsuko hung hăng (Phần 1)', 'Aggretsuko (Season 1)', 'https://phimimg.com/upload/vod/20240920-1/3655a29f4506c9e2988317e9d545300a.jpg', 'https://phimimg.com/upload/vod/20240920-1/87c262c8a713d6ce472150f0e8522123.jpg', '<p>Thất vọng với công việc văn phòng bạc bẽo, cô Gấu trúc đỏ Retsuko xốc lại tinh thần sau những vật lộn hàng ngày bằng việc hát karaoke loại nhạc death metal khi tan làm.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaolip","avatar":""},{"name":"Rareko","avatar":""},{"name":"Shingo Katou","avatar":""},{"name":"Rina Inoue","avatar":""},{"name":"荒井聡太","avatar":""},{"name":"鶴田真希","avatar":""},{"name":"Yuki Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["冲吧烈子","Η Ρέτσουκο Έξω Φρενών","Aggressive Retsuko","Retsuko Hung Hăng","アグレッシブ烈子"]', 1784690324391);
