INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-cu-tinh-moi', 'Chồng Cũ, Tình Mới', 'Love, Again', 'https://phimimg.com/upload/vod/20240919-1/5ce3bac052115ad3a4858af5712c73ab.jpg', 'https://phimimg.com/upload/vod/20240919-1/deb1d607ec7e2443cf84098943d45563.jpg', '<p>Những tưởng sau buổi lễ ly hôn chính thức với sự góp mặt của toàn thể người quen và bạn bè, Hyun-woo (Kwon Sang-woo) và Sun-young (Lee Jung-hyun) sẽ chính thức đường ai nấy đi với cuộc sống riêng của mỗi người. Ấy vậy mà chưa kịp tận hưởng đời độc thân được bao lâu, cuộc sống của Hyun-woo một lần nữa bị đảo lộn khi vợ cũ bất ngờ xuất hiện trở lại cùng người đàn ông đang theo đuổi cô Sang-cheol (Lee Jong-hyuk). Oái oăm thay, Sang-cheol là bạn từ thời trung học của Hyun-woo, và anh cũng không hề biết gì về mối quan hệ nhiều duyên nợ giữa Hyun-woo và Sun-young. Câu chuyện dở khóc dở cười giữa ba người rốt cuộc sẽ kết thúc trong tình yêu hay thù hận?</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"권상우","avatar":""},{"name":"이정현","avatar":""},{"name":"이종혁","avatar":""},{"name":"성동일","avatar":""},{"name":"정상훈","avatar":""},{"name":"김현숙","avatar":""},{"name":"박경혜","avatar":""},{"name":"구성환","avatar":""},{"name":"전소민","avatar":""},{"name":"Shin Soo-ji","avatar":""},{"name":"이화시","avatar":""},{"name":"이상준","avatar":""},{"name":"Hong Eun-ji","avatar":""},{"name":"정다은","avatar":""},{"name":"Jong Ho","avatar":""},{"name":"Yoon Jae-in","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Guy Guy Girl","놈놈년","Shall We Do It Again","두번할까요"]', 1784690324391);
