INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-cuoi-cung', 'Hoàng Hậu Cuối Cùng', 'The Last Empress', 'https://phimimg.com/upload/vod/20240916-1/9bffdc79dd228dea187ece089320fcca.jpg', 'https://phimimg.com/upload/vod/20240916-1/12a82b0e4eefbf6f3be76b148e511882.jpg', '<p>Phim Hoàng Hậu Cuối Cùng Lấy bối cảnh Hàn Quốc hiện đại dưới chế độ quân chủ lập hiến, The Last Empress kể câu chuyện về Oh Sunny (Jang Na Ra), một nữ diễn viên nhạc kịch sau một đêm bất ngờ trở thành hoàng hậu. Biết mình chỉ là quân cờ trong cuộc chiến tranh giành quyền lực, Oh Sunny quyết tâm khám phá đến cùng vụ ám sát bí ẩn, đồng thời chiến đấu để bảo vệ những người cô yêu thương và giành lấy hạnh phúc.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장나라","avatar":""},{"name":"최진혁","avatar":""},{"name":"신성록","avatar":""},{"name":"이엘리야","avatar":""},{"name":"신은경","avatar":""},{"name":"오승윤","avatar":""},{"name":"Oh Ah-Rin","avatar":""},{"name":"박원숙","avatar":""},{"name":"이희진","avatar":""},{"name":"Shin Go-eun","avatar":""},{"name":"윤다훈","avatar":""},{"name":"스테파니 리","avatar":""},{"name":"황영희","avatar":""},{"name":"고세원","avatar":""},{"name":"태항호","avatar":""},{"name":"Kim Dong-Kyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324391);
