INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('illang-lu-doan-soi', 'Illang: Lữ Đoàn Sói', 'Illang: The Wolf Brigade', 'https://phimimg.com/upload/vod/20240913-1/8efc2c395b69aa3c21d4d16102f57ff9.jpg', 'https://phimimg.com/upload/vod/20231208-1/2e50ed21a8a324fc61ab2713fb08d7d5.jpg', '<p>Năm 2029, đội cảnh sát ưu tú Illang chiến đấu với một nhóm khủng bố phản đối sự thống nhất của hai miền Triều Tiên. Nhưng một kẻ thù khác có thể đang rình rập gần đó.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gang Dong Won","avatar":""},{"name":"Han Hyo Joo","avatar":""},{"name":"Jung Woo Sung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324391);
