INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-kha-thi-sup-do', 'Nhiệm Vụ: Bất Khả Thi - Sụp Đổ', 'Mission: Impossible - Fallout', 'https://phimimg.com/upload/vod/20231018-1/9f26cc2f4dd5a7e0b162c88ae76be238.jpg', 'https://phimimg.com/upload/vod/20231018-1/1c0aa4faaa20179df8ea981afb7be708.jpg', '<p>Trong một nhiệm vụ nguy hiểm để thu hồi số plutonium bị đánh cắp, Ethan Hunt (Tom Cruise) đã chọn cứu đồng đội thay vì hoàn thành nhiệm vụ, khiến vũ khí hạt nhân rơi vào tay một mạng lưới tội phạm chết người đang có ý định hủy diệt nền văn minh. Giờ đây, khi thế giới đang lâm nguy, Ethan và đội IMF (Simon Pegg, Ving Rhames, Rebecca Ferguson) buộc phải hợp tác với một đặc vụ CIA cứng rắn (Henry Cavill) khi họ chạy đua với thời gian để chặn một thảm họa hạt nhân. Một mối de dọa khủng khiếp nhất, những pha hành động ấn tượng nhất và nhiệm vụ bất khả thi nhất từ trước tới nay!</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Sean Harris","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Frederick Schmidt","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Yang Liang","avatar":""},{"name":"Kristoffer Joner","avatar":""},{"name":"Wolf Blitzer","avatar":""},{"name":"Dean Ashton","avatar":""},{"name":"Alix Bénézech","avatar":""},{"name":"Joey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a24