INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-rong-trong-ba-coi', 'Tìm kiếm rồng trong ba cõi', 'Search for Dragons in Three Realms', 'null', 'https://phimimg.com/upload/vod/20231108-1/f2a165294dfe319a2b2cb7cba33dc72d.jpg', '<p>Cậu học sinh Cui Lin, chủ tịch câu lạc bộ giọng nói của trường đại học, bị Cơ sở Cải huấn Vũ trụ bắt vì quá tự ái, kiêu ngạo và độc hại, gây ra nhiều năng lượng tiêu cực cho những người xung quanh. Anh bị kết án phải biến thành chiếc ô suốt đời để phục vụ nhân loại. Để thoát khỏi số phận bi thảm bị biến thành chiếc ô, Trey Rin lên đường đến một vùng đất khác trên hành tinh khác và lên đường tìm kiếm linh hồn của con rồng bị bỏ lại ở đó. Anh gặp võ sĩ mạnh mẽ Jin Haitang, người có thể sạc lại pin và thái tử, người bị buộc phải gặp rắc rối trong cung điện. Để phá vỡ âm mưu của chủ nhân, họ đã giăng bẫy để dụ anh ta vào bẫy nhưng không ngờ chủ nhân lại phóng ra năng lượng tiêu cực đủ mạnh để hủy diệt hành tinh này.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gu Renqi","avatar":""},{"name":"Yan Yuxin","avatar":""},{"name":"Ren Xiaoyao","avatar":""},{"name":"Xue Baohe","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Yue Su","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324391);
