INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('man-dem-keo-den', 'Màn Đêm Kéo Đến', 'The Night Comes for Us', 'màn đêm kéo đến the night comes for us joe taslim iko uwais julie estelle sunny pang asha kenyeri bermudez abimana aryasatya zack lee revaldo dimas anggara salvita decorte dian sastrowardoyo hannah al rashid shareefa daanish ronny p. tjandra morgan oey epy kusnandar asta nurcah ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-khong-dung-cam-uong-phi-thanh-xuan', 'Sống Không Dũng Cảm Uổng Phí Thanh Xuân', 'When We Were Young', 'https://phimimg.com/upload/vod/20240909-1/ab4924aa307a612b0434227ccd5247b1.jpg', 'https://phimimg.com/upload/vod/20240909-1/09d97e52dabdd59012e867829b3cbab5.jpg', '<p>Mùa hạ năm 1996, Dương Tịch vốn nổi tiếng trong lớp với đôi chân chạy như bay được cha mẹ tặng cho chiếc xe đạp sau khi cô giành giải nhất cuộc thi chạy toàn trường. Trên đường về nhà, chiếc xe đạp bị cướp mất, trong lúc đuổi theo tên cướp xe, vô tình bị sức ép của vụ nổ phòng thí nghiệm làm cho bị thương, không cách nào tham gia vào cuộc thi điền kinh lấy điểm cộng vào đại học. #Sau khi đi học lại, Dương Tịch phát hiện tên thủ phạm gây ra vụ nổ lúc đó, không những đã chuyển đến lớp cô, mà còn giành lấy vị trí lớp trưởng mà cô hằng khao khát. Người mới đến tên là Hoa Bưu - một thiên tài khoa học nhiệt huyết, trượng nghĩa, và có chút bốc đồng. #Hoa Bưu vô tình bị xem là kẻ thù của cả lớp. Anh ta đã sử dụng bộ não thiên tài của mình để cứu vãn tiệc Trung thu, dùng trí nhớ kỷ lục khéo léo giành thắng lợi trò chơi, và bỏ mặc sự an nguy của mình để bị đâm thay anh em. Từ những hành động này, cả lớp cuối cùng đều gạt bỏ định kiến và sự thù hằn với Hoa Bưu, và anh cũng trở thành thành viên của nhóm &quot;Tiểu đội xe bay năm người&quot;. Dương Tịch cũng dần nhận thấy không chỉ có nhiệt huyết và sự mạnh mẽ, Hoa Bưu còn rất hiếu thảo với người bà, vậy nên cô cũng buông bỏ định kiến và kết bạn với anh ta. Nhóm năm người họ cùng nhau trải qua những ngày cuối cấp 3 vui vẻ, cũng nếm trải những cay đắng của quá trình trưởng thành, và cùng viết nên một câu chuyện thanh xuân khó phai mờ này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hầu Minh Hạo","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Trương Diệu","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Lý Minh Đức","avatar":""},{"name":"Phan Mỹ Hoa","avatar":""},{"name":"Vương Sâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324391);
