INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuan-dam-cuoi', 'Tuần Đám Cưới', 'The Week Of', 'https://phimimg.com/upload/vod/20240909-1/d36e7bec5f5338098ea3f6f669488ab7.jpg', 'https://phimimg.com/upload/vod/20240909-1/a643f6f9f8cf009e6eeba89f511bf6eb.jpg', '<p>Cha mẹ của cặp đôi sắp cưới đang chuẩn bị những bước cuối cùng cho lễ cưới.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Rachel Dratch","avatar":""},{"name":"Allison Strong","avatar":""},{"name":"Roland Buck III","avatar":""},{"name":"Katie Hartman","avatar":""},{"name":"Chloe Himmelman","avatar":""},{"name":"Jake Lippmann","avatar":""},{"name":"Jim Barone","avatar":""},{"name":"June Gable","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"Christian Capozzoli","avatar":""},{"name":"Nasser Faris","avatar":""},{"name":"Jared Sandler","avatar":""},{"name":"Andrew Polk","avatar":""},{"name":"Liz Larsen","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324391);
