INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuan-dam-cuoi', 'Tuần Đám Cưới', 'The Week Of', 'tuần đám cưới the week of adam sandler chris rock steve buscemi rachel dratch allison strong roland buck iii katie hartman chloe himmelman jake lippmann jim barone june gable suzanne shepherd christian capozzoli nasser faris jared sandler andrew polk liz larsen ja ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-vung-tro-ve', 'Nằm Vùng Trở Về', 'Undercover Return', 'https://phimimg.com/upload/vod/20240908-1/0c6c74cc1520ba3a83702f5e9276f814.jpg', 'https://phimimg.com/upload/vod/20240908-1/7e2c0d2f1b5bb3a3fdd1004af390139d.jpg', '<p>Cuộc chiến chống ma túy bùng nổ, Bảo Ngọc đóng giả làm trinh sát viên hoàn thành nhiệm vụ, hy vọng được quay về đội. Nhưng, lại có một nhiệm vụ khó khăn, nguy hiểm hơn gấp bộ phần chờ anh hoàn thành, Bảo Ngọc lợi dụng trùm ma túy Kim Phi bị mất trí nhớ trong bệnh viện, bắt đầu sự nghiệp nằm vùng lần nữa, dưới tình huống không có nhân viên đặc cần, thâm nhập vào công ty Phi Thành, giành được sự tín nhiệm của người vợ trẻ của chủ tịch Điền Kính, tổng giám đốc Lâm Oanh.

Do thân phận của Bảo Ngọc quá mức nhạy cảm, càng bởi vì Điền Kính thành lập địa vị trọng yếu ở Hồng Xuyên kinh tế, không thể khiến cho ông ta nghi ngờ, ảnh hưởng đến phát triển kinh tế ở Hồng Xuyên. Mà Điền Kính lại tuyệt đối không cho phép vợ mình là Lâm Oanh có bất cứ dính dáng gì với thành viên tập đoàn buôn bán thuốc phiện. Vì điều này, nhiệm vụ của Bảo Ngọc, dường như không thể hoàn thành. Chính dưới tình hình không thể này, trước Bảo Ngọc, Liên Trung và Tần Việt, đã giả thành nhân viên trinh thám...</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 7, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Shen","avatar":""},{"name":"Zhang Jiayi","avatar":""},{"name":"劉奕君","avatar":""},{"name":"翟天臨","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"李沁","avatar":""},{"name":"Fu Jing","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Yang Yuting","avatar":""},{"name":"Wang Ban","avatar":""},{"name":"XiaoYun Qian","avatar":""},{"name":"Li Yanming","avatar":""},{"name":"张晶伟","avatar":""},{"name":"Yan Jie","avatar":""},{"name":"Zhu Yun''er","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324391);
