INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-gioi-han-2018', 'Vượt Qua Giới Hạn', 'Payakka', 'https://phimimg.com/upload/vod/20240904-1/d0826149d3ee1b2f187c0d77a075b24c.jpg', 'https://phimimg.com/upload/vod/20240904-1/7d6f240e98e91455f5ad1cf0707c733d.jpg', '<p>Vượt Qua Giới Hạn - Phayakkha kể về Ployrampa, một phụ nữ quý tộc đem lòng yêu Pakin, một chàng trai trẻ được định sẵn là có một linh hồn tiềm ẩn trong cơ thể anh ta. Khi anh ấy 25 tuổi, anh ấy sẽ là nửa người nửa hổ. Là một con quái vật chết chóc, anh ta bị săn đuổi bởi những thợ săn, đặc biệt là người đứng đầu làng phản diện Kongdate, người muốn có phép thuật trong cơ thể anh ta. Ployrampa và Pakin yêu nhau mà không sợ hãi, nhưng cách duy nhất để họ thực sự ở bên nhau là nếu anh ấy hoàn toàn là con người trở lại. Liệu Pakin có sống sót sau tất cả những kẻ săn độc ác đang đuổi theo anh ta? Sự thật về sự ra đời của anh ta và thần hổ là gì?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2018, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324391);
