INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuot-qua-gioi-han-2018', 'Vượt Qua Giới Hạn', 'Payakka', 'vượt qua giới hạn payakka  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-bach-xa', 'Truyền Thuyết Bạch Xà', 'The Destiny Of White Snake', 'https://phimimg.com/upload/vod/20240904-1/d0a77aece686d1d5a0870a5ee0a9e4a3.jpg', 'https://phimimg.com/upload/vod/20240904-1/d21720209de703f3e84131479aaa8069.jpg', '<p>Bộ phim kể về cuộc đời và mối tình của tiểu xà tinh tên Bạch Yêu Yêu (Dương Tử đóng). Bạch Yêu Yêu du ngoạn vô tình gặp Hứa Tuyên (Nhậm Gia Luân đóng) và sư muội Lãnh Ngưng (Hà Đỗ Quyên đóng) hành y cứu người trong buổi lễ hoa đào và đem lòng yêu mến anh. Tuy nhiên, trải qua thời gian tươi đẹp ngắn ngủi, Hứa Tuyên bị bệnh nặng khiến Bạch Yêu Yêu phải trộm tiên thảo và vi phạm thiên quy không được phép gặp lại Hứa Tuyên.

Sau khi khỏi bệnh, Hứa Tuyên nhớ lại chuyện cũ, liền một thân một mình đi tìm Bạch Yêu Yêu. Hứa Tuyên không biết rằng sư muội của mình đã trót thương mình từ lâu, để mặc cho Lãnh Ngưng làm loạn, thả giao long với mục đích phá hoại mối tình của Yêu Yêu và Hứa Tuyên nhưng không thành thậm chí còn gây họa cho nhân gian. Vì lẽ đó, Tiểu Bạch Xà mới phải hy sinh thân mình cùng Tề Tiêu (Mao Tử Tuấn đóng) trấn giữ tháp Lôi Phong và vĩnh viễn không gặp lại Hứa Tuyên nữa.</p>', 'Hoàn Tất (61/61)', 61, 'series', 'completed', 11, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Cư Văn Phái","avatar":""},{"name":"Trương Húc","avatar":""},{"name":"Tu Khánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324391);
