INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-bach-xa', 'Truyền Thuyết Bạch Xà', 'The Destiny Of White Snake', 'truyền thuyết bạch xà the destiny of white snake cư văn phái trương húc tu khánh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-chien-ky-dap-hoa-hanh-ca', 'Thục Sơn Chiến Kỷ Đạp Hỏa Hành Ca', 'The Legend Of Zu 2', 'https://phimimg.com/upload/vod/20240904-1/901edc61ca9306a64ec9f84c2abc42f4.jpg', 'https://phimimg.com/upload/vod/20240904-1/801cf7353aa5417ba48b36af8a51238a.jpg', '<p>Thục Sơn Chiến Kỷ: Đạp Hỏa Hành Ca - The Legend of Zu 2, Ở thị trấn Thục Sơn, do Xích Hồn Thạch đột nhiên có sự thay đổi khác biệt, hơn nữa sức phá hủy trong nó khiến cho cả Hỏa lê tộc và cả thế giới võ lâm phải đối diện với một tai nạn khủng khiếp chưa từng có. Dư Anh Nam – được số mệnh lựa chọn là người bảo hộ cho Hỏa Lê tộc và em gái Dư Anh Kỳ đều mang bí mật của riêng mình ẩn cư tại một thôn nhỏ. Anh Nam cũng không biết nàng chính là được ca ca Anh Kỳ nhặt về nuôi, bởi vì nàng bị mất ký ức khi nhỏ. Hai anh em cùng nhau đến Thục Sơn học võ, nhằm tìm lại sức mạnh của người giám hộ. Kể từ đó, từ Thục Sơn đến Toàn Cơ Môn, Lạc Tiên cung, cuộc chiến giữa yêu- hận, chính- tà bắt đầu xảy ra…</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 8, 2018, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Nghiêu","avatar":""},{"name":"Hà Giai Dĩnh","avatar":""},{"name":"Hồ Hạo Phàm","avatar":""},{"name":"Lạc Ứng Quân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324391);
