INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-cong-chua', 'Tháp Công Chúa', 'Single Ladies Senior', 'https://phimimg.com/upload/vod/20240904-1/de96664807d12ee08a39f8d5046f89b9.jpg', 'https://phimimg.com/upload/vod/20240904-1/ccc9b31302ae509753feea92c18e2835.jpg', '<p>Nội dung phim xoay quanh 4 cô gái từ khi học đại học đến 10 năm sau. Dương Mi Na trong quá khứ bị bạn trai và cô bạn thân Trác Lệ cắm sừng . Mười năm sau, cô vô tình gặp lại Trác Lệ và bạn trai phản bội. Nhưng những gì diễn ra trong quá khứ lại không giống những gì cô tưởng tượng. Bạn trai sau 10 năm đã trở thành doanh nhân thành đạt nhưng vẫn không thể quên được cô. Số phận đẩy họ gặp lại một lần nữa và mâu thuẫn, hiểu nhầm trong quá khứ dần được hé lộ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2018, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Châu Quần Đạt","avatar":""},{"name":"Christina Mok","avatar":""},{"name":"Lý Chính Thiên","avatar":""},{"name":"Summer Meng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324391);
