INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-ran-2', 'Nữ Thần Rắn 2', 'Nakee 2', 'https://phimimg.com/upload/vod/20231102-1/b502c451b95755eece17aaf26e734628.jpg', 'https://phimimg.com/upload/vod/20231102-1/83d2b1560293e784d268aa8454784f84.jpg', '<p>Soi, cô gái trẻ sinh ra và lớn lên ở một ngôi làng phía Bắc của Thái Lan. Cô dành cả thanh xuân để coi sóc đền thờ nữ thần Nakee nhằm tỏ lòng tôn kính. Nhưng những vụ án chết người kì lạ liên tiếp xảy ra khiến dân làng cho rằng đấy là điềm báo sự trở lại của Nữ Thần Rắn. Đồng thời coi Soi chính là hiện thân của Nữ thần rắn đang quay về báo thù. Soi sẽ phải làm cách nào với những điềm báo này.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Urassaya Sperbund","avatar":""},{"name":"Natapohn Tameeruks","avatar":""},{"name":"Phupoom Phongpanu","avatar":""},{"name":"Lakana Wattanawongsiri","avatar":""},{"name":"Somphong Kunapratom","avatar":""},{"name":"Poyfai Malaiporn","avatar":""},{"name":"Piya Trakulrat","avatar":""},{"name":"Saichia Wongwirot","avatar":""},{"name":"Watcharapong Pattama","avatar":""},{"name":"Jonathan Samson","avatar":""},{"name":"Suchat Phutchanthuek","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324391);
