INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-phu-nhan-thi-truong', 'Bí Mật Phu Nhân Thị Trưởng', 'Let''s Cheat Together', 'https://phimimg.com/upload/vod/20231101-1/395527f436f81caa878bce293cf18f4d.jpg', 'https://phimimg.com/upload/vod/20231101-1/ae9ad6207757ee8cadef111d1c2573be.jpg', '<p>Một đoạn clip quay trộm cảnh Trình Kiến và vợ của thị trưởng hôn nhau say đắm đang được phát tán trên mạng khiến anh lâm vào cảnh “sống không bằng chết”. Sắp phải thân bại danh liệt, Trình Kiến phải làm gì để người bạn gái đanh đá Miu Miu tin vào sự trong sạch của mình? Và vì cớ làm sao mà anhh lại rơi vào cảnh trớ trêu này?</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Shao-Huai Chang","avatar":""},{"name":"Ko Chia-yen","avatar":""},{"name":"Joe Chen","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Umin Boya","avatar":""},{"name":"Aviis Zhong","avatar":""},{"name":"Ken Lin","avatar":""},{"name":"Oscar Chiu","avatar":""},{"name":"Hui-Chen Ma","avatar":""},{"name":"Retina","avatar":""},{"name":"Chin-Lan Chang","avatar":""},{"name":"Leo Wang","avatar":""},{"name":"Chang-Hao Liu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
