INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-trang', 'Khoảng Trắng', 'White Space', 'https://phimimg.com/upload/vod/20231101-1/3f2f27568c5921546de96ac1ea9b60e6.jpg', 'https://phimimg.com/upload/vod/20231101-1/97617f7ca683d07087d4917f59e96b6a.jpg', '<p>Khi một tàu đánh cá không gian sâu bị cướp bởi một nhóm cướp biển, Thuyền trưởng đã đưa ra một quyết định táo bạo để theo đuổi một loài quý hiếm và gần như tuyệt chủng. Nỗi ám ảnh của anh đẩy họ tiến xa hơn vào không gian khi phi hành đoàn xoay quanh cuộc nổi loạn và sự phản bội.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Holt McCallany","avatar":""},{"name":"Zulay Henao","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"James Devoti","avatar":""},{"name":"Kodi Kitchen","avatar":""},{"name":"Spencer Hill","avatar":""},{"name":"Tiffany Brouwer","avatar":""},{"name":"Ron Yuan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
