INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-o-long-vien-tieu-ngao-giang-ho', 'Tân Ô Long Viện: Tiếu Ngạo Giang Hồ', 'Oolong Courtyard: Kung Fu School', 'https://phimimg.com/upload/vod/20231101-1/ed4b46c07e38a1a5c9f7784fa8b43997.jpg', 'https://phimimg.com/upload/vod/20231101-1/c5f5ee6ee41ba3d28505345b2e01eb1d.jpg', '<p>Bộ phim sẽ đưa khán giả quay lại với kí ức về một Ô Long Viện với những trò nghịch ngợm quỷ quái của các chú tiểu. Đến với &quot;Tân Ô Long Viện: Tiếu Ngạo Giang Hồ&quot;, 2 trong số 3 nhân vật chính của loạt phim trước sẽ quay trở lại trong phần này, đó là “sư huynh” Ngô Mạnh Đạt – “cặp bài trùng” một thời của Châu Tinh Trì và “sư đệ” mập mạp đáng yêu – Hác Thiệu Văn. &nbsp;Trong phần này, Ô Long Viện mở một đợt nhập môn, nhưng một số đối tượng xấu lợi dụng cơ hội này để tìm cách đột nhập và gây một số bất lợi cho Ô Long Viện. Thế nhưng, chúng lại không biết mình sẽ chạm trán với các môn đệ “siêu nhây” của Ô Long Viện ở những tình huống trớ trêu nhưng không kém phần hài hước.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ng Man-tat","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Hao Shaowen","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Wang Zhi","avatar":""},{"name":"Song Xiaobao","avatar":""},{"name":"Ning Wang","avatar":""},{"name":"Kong Lian-Shun","avatar":""},{"name":"Zhang Zidong","avatar":""},{"name":"Xinrui Li","avatar":""},{"name":"Elsie Yeh","avatar":""},{"name":"Laiyun Song","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324392);
