INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-thuy', 'Phong Thủy', 'Fengshui', 'https://phimimg.com/upload/vod/20231101-1/fb92d7bd468c63b5823ec6d4cd835e2e.jpg', 'https://phimimg.com/upload/vod/20231101-1/3e4fe3d7f13558eede32cbd36ce924c0.jpg', '<p>Bộ phim Phong Thủy - Fengshui xoay quanh cuộc chiến tranh quyền đoạt vị trong triều đình và những âm mưu đáng sợ của những thế lực đang muốn lật đổ ngôi vương. Trong đó, gia tộc họ Kim có thế lực rất mạnh và có cơ hội lớn nhất lên làm vua nhưng lại bị ảnh hưởng bởi một khu mộ bí mật. Jae-sang là một bậc thầy phong thuỷ, ông đã biết trước những âm mưu toan tính của dòng tộc này nên đã tìm mọi cách để cản trở và phá hoại kế hoạch.</p>', 'Full', 1, 'single', 'completed', 5, 2018, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Cho Seung-woo","avatar":""},{"name":"Ji Sung","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Moon Chae-won","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Park Choong-seon","avatar":""},{"name":"Lee Won-keun","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Kang Tae-oh","avatar":""},{"name":"Yoon Ga-hyun","avatar":""},{"name":"Yun Yeong-keol","avatar":""},{"name":"Ahn Seong-bong","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Jeon Shin Hwan","avatar":""},{"name":"Jo Hyun-sik","avatar":""},{"name":"Jung Jae Hun","avatar":""},{"name":"Kim Yeong-jo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
