INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-thuc', 'Nhận Thức', 'Perception', 'https://phimimg.com/upload/vod/20231101-1/c574d4639b42d7939a8481cf0abf841e.jpg', 'https://phimimg.com/upload/vod/20231101-1/8b94b472cacaf533e6b6328796a02cee.jpg', '<p>Là một chuyên gia bất động sản thành công khi theo đuổi Nina, một nhà ngoại cảm nhỏ bé bí ẩn phải chật vật hàng ngày để nuôi dưỡng đứa con trai nhỏ của mình, điều cuối cùng Daniel mong đợi nhận được là việc được đọc vận mệnh. Nhưng khi Nina cảm nhận được linh hồn của người vợ đã chết của Daniel, một nghệ sĩ trẻ đầy tiềm năng, thì mong muốn kết nối với người vợ quá cố của mình nhanh chóng trở thành nỗi ám ảnh của Daniel. Bị ám ảnh bởi những ký ức, Daniel quyết tâm đoàn tụ với người vợ cũ của mình. Do đó, Daniel và Nina phải quyết định họ sẵn sàng làm những gì để có được thứ họ muốn trong thế giới kinh dị tâm lý siêu nhiên này.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wes Ramsey","avatar":""},{"name":"Max Jenkins","avatar":""},{"name":"Caitlin Mehner","avatar":""},{"name":"Valerie Jane Parker","avatar":""},{"name":"Meera Rohit Kumbhani","avatar":""},{"name":"John French","avatar":""},{"name":"Sarah East","avatar":""},{"name":"Davis Aguila","avatar":""},{"name":"Apollo Bacala","avatar":""},{"name":"Vee Kumari","avatar":""},{"name":"Shaleen Cholera","avatar":""},{"name":"Matthew Davis","avatar":""},{"name":"Daniel H. Shoemaker","avatar":""},{"name":"Tshombi Basemore","avatar":""},{"name":"J. Barrett Cooper","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
