INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-cau', 'Lời Nguyện Cầu', 'The Prayer', 'https://phimimg.com/upload/vod/20231101-1/4326b534ab1388640d73176f0da23bf7.jpg', 'https://phimimg.com/upload/vod/20231101-1/97e4c7c11274d46328bdbb2d257b00ec.jpg', '<p>Thomas là một người nghiện ma túy. Trong nỗ lực chấm dứt thói quen của mình, anh ấy tham gia một cộng đồng gồm những người từng nghiện sống biệt lập trên núi và sử dụng lời cầu nguyện như một cách để chữa bệnh cho bản thân.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Anthony Bajon","avatar":""},{"name":"Damien Chapelle","avatar":""},{"name":"Àlex Brendemühl","avatar":""},{"name":"Louise Grinberg","avatar":""},{"name":"Hanna Schygulla","avatar":""},{"name":"Magne-Håvard Brekke","avatar":""},{"name":"Davide Campagna","avatar":""},{"name":"Maïté Maillé","avatar":""},{"name":"Antoine Amblard","avatar":""},{"name":"Colin Bates","avatar":""},{"name":"Iñaki Aguirre","avatar":""},{"name":"Stefan Crepon","avatar":""},{"name":"Anto Mela","avatar":""},{"name":"Massimo Riggi","avatar":""},{"name":"Raphaël Liot","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
