INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-nguyen-cau', 'Lời Nguyện Cầu', 'The Prayer', 'lời nguyện cầu the prayer anthony bajon damien chapelle àlex brendemühl louise grinberg hanna schygulla magne-håvard brekke davide campagna maïté maillé antoine amblard colin bates iñaki aguirre stefan crepon anto mela massimo riggi raphaël liot ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-ngay-4-thang-9', 'Lời Nguyền Ngày 4 Tháng 9', 'Fourth Of September', 'https://phimimg.com/upload/vod/20240901-1/7db5a3c19dad47337c9d03b6688e8223.jpg', 'https://phimimg.com/upload/vod/20231101-1/d1b2f7de8e7d86f66450bea09d6de3a6.jpg', '<p>Lời Nguyền Ngày 4 Tháng 9 - Fourth Of September xoay quanh câu chuyện của người bố nhà họ Trương bị một người bạn gài bẫy trong một vụ lừa đảo cờ bạc và mắc một khoản nợ lớn. Ông ta buộc phải đưa gia đình bốn người của mình đến Hoa Liên và chuyển đến một ngôi nhà cho thuê bị ma ám. Viên cảnh sát Hồ Lão không ngừng lẩm bẩm về lời nguyền ngày 4 tháng 9 và vụ án mạng kinh hoàng của cả gia đình sắp xảy ra vào ngày hôm đó. Người mẹ của nhà họ Trương tin vào lời nguyền và quyết định rời khỏi nhà. Tuy nhiên, người bố không đồng ý với kế hoạch của bà. Ông ta đánh gục người mẹ, đứa con gái và con trai khi họ đang ngủ và trói họ trong phòng tắm, liệu lời nguyền có là sự thật và chuyện gì sẽ xảy đến với gia đình họ?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Xing Li","avatar":""},{"name":"Tsung-Hua Tou","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
