INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghin-le-mot-dem', 'Nghìn Lẻ Một Đêm', 'Sweet Dreams', 'https://phimimg.com/upload/vod/20240630-1/3a65aee5a76f6c6fa51a69d8977d5d48.jpg', 'https://phimimg.com/upload/vod/20240630-1/18e5bc404a2349cf474cd3a73b7ccf6f.jpg', '<p>Địch Lệ Nhiệt Ba đảm nhận vai Lăng Lăng Thất - nhân viên của khách sạn Bối Mã. Lăng Lăng Thất có tính tình lương thiện, thật thà, là một cô gái rất thích giúp đỡ mọi người; nhưng cô lại rất tự ti và yếu đuối. khuyết điểm này đã ảnh hưởng nghiêm trọng đến cuộc sống của cô, khiến cô khó phát triển sự nghiệp, khó lòng thăng tiến, cũng như không thuận lợi thực hiện được lý tưởng sống của mình. Bên cạnh đó nhân vật Lăng Lăng Thất rất thích anh chàng đồng nghiệp Bách Hải (Đặng Luân) nhưng lại không dám bày tỏ tình cảm.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Đặng Luân","avatar":""},{"name":"Vương Thụy Tử","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
