INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-3-ba-chang-khuyet', 'Lật Mặt 3: Ba Chàng Khuyết', 'Face Off 3: Imperfect Trio', 'https://phimimg.com/upload/vod/20240827-1/755f113d948984643ccd7df2c03f4f13.jpg', 'https://phimimg.com/upload/vod/20240827-1/1224c7ba187951af2415d433da3b4689.jpg', '<p>Lật Mặt 3: Ba Chàng Khuyết là hành trình tìm lại người thân của ba người bạn Tâm - Đức - Lộc tuy kém may mắn phải chịu khuyết tật trên cơ thể và bị cha mẹ bỏ rơi từ nhỏ nhưng luôn lạc quan với cuộc đời. Phim là phần tiếp theo của Series hành động hài - hành động Lật Mặt, do Kiều Minh Tuấn, Huy Khánh, Song Luân và hot girl Thái Lan Nene đóng chính.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Song Luân","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Phương Bình","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324392);
