INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-sieu-cap-huyen-thoai-broly', 'Bảy Viên Ngọc Rồng Siêu Cấp: Huyền Thoại Broly', 'Dragon Ball Super: Broly', 'https://phimimg.com/upload/vod/20240827-1/bb3064e92aa97d20827be521bc6da879.jpg', 'https://phimimg.com/upload/vod/20240827-1/f3c5b869a3fb9334ebf92f4e2a1c1540.jpg', '<p>Bảy Viên Ngọc Rồng Siêu Cấp: Broly lấy bối cảnh khi đế chế Frieza đàn áp, đặt ách thống trị, bắt người Saiyan phải phải phục vụ làm việc dưới quyền của chúng. Khi đó 3 đứa trẻ Saiyan đã được sinh ra cùng một lúc, nhưng số phận của chúng lại hoàn toàn khác nhau: Vegeta là hoàng tử của tộc người Saiyan, Kakalot (Goku) là con trai của tướng quân Bardock, và Broly là con của Paragus.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"野沢雅子","avatar":""},{"name":"久川綾","avatar":""},{"name":"堀川りょう","avatar":""},{"name":"古川登志夫","avatar":""},{"name":"草尾毅","avatar":""},{"name":"中尾隆聖","avatar":""},{"name":"山寺宏一","avatar":""},{"name":"森田成一","avatar":""},{"name":"大友龍三郎","avatar":""},{"name":"宝亀克寿","avatar":""},{"name":"渡辺菜生子","avatar":""},{"name":"銀河万丈","avatar":""},{"name":"千葉繁","avatar":""},{"name":"稲田徹","avatar":""},{"name":"水樹奈々","avatar":""},{"name":"杉田智和","avatar":""},{"name":"菊池正美","avatar":""},{"name":"斉藤貴美子","avatar":""},{"name":"Yukiko Morishita","avatar":""},{"name":"桐本拓哉","avatar":""},{"name":"江川央生","avatar":""},{"name":"谷昌樹","avatar":""},{"name":"阿座上洋平","avatar":""},{"name":"松山鷹志","avatar":""},{"name":"島田敏","avatar":""},{"name":"青森伸","avatar":""},{"name":"高塚正也","avatar":""},{"name":"沼田祐介","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 178