INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-vien-ngoc-rong-sieu-cap-huyen-thoai-broly', 'Bảy Viên Ngọc Rồng Siêu Cấp: Huyền Thoại Broly', 'Dragon Ball Super: Broly', 'bảy viên ngọc rồng siêu cấp: huyền thoại broly dragon ball super: broly 野沢雅子 久川綾 堀川りょう 古川登志夫 草尾毅 中尾隆聖 山寺宏一 森田成一 大友龍三郎 宝亀克寿 渡辺菜生子 銀河万丈 千葉繁 稲田徹 水樹奈々 杉田智和 菊池正美 斉藤貴美子 yukiko morishita 桐本拓哉 江川央生 谷昌樹 阿座上洋平 松山鷹志 島田敏 青森伸 高塚正也 沼田祐介 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-dua-anh-toi-di-gium-cai', 'Mau Đưa Anh Tôi Đi Giùm Cái', 'Take My Brother Away', 'https://phimimg.com/upload/vod/20240825-1/4b1f8110e377c8f9e8428e816c555e6f.jpg', 'https://phimimg.com/upload/vod/20240825-1/bc3404ed99a3328f0679e3c78b0d41fd.jpg', '<p>Phim xoay quanh một cặp anh trai em gái hay chảnh chọe với nhau với những phân cảnh khó đỡ, cười ra nước mắt.</p>', 'Tập 48', 72, 'hoathinh', 'ongoing', 6, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"中村悠一","avatar":""},{"name":"雨宮天","avatar":""},{"name":"小野賢章","avatar":""},{"name":"花江夏樹","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
