INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-dua-anh-toi-di-gium-cai', 'Mau Đưa Anh Tôi Đi Giùm Cái', 'Take My Brother Away', 'mau đưa anh tôi đi giùm cái take my brother away 中村悠一 雨宮天 小野賢章 花江夏樹 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-la-dai-luc', 'Đấu La Đại Lục', 'Soul Land', 'https://phimimg.com/upload/vod/20240822-1/b33f409a503b9d7af4967e3e91d0c2a8.jpg', 'https://phimimg.com/upload/vod/20240822-1/4cabd6c124cb29f10105e3b4c42bbefc.jpg', '<p>Câu chuyện với nhân vật chính, con một thợ rèn, một thợ rèn trở thành tửu quỷ, vì thê tử đã mất, sẵn sàng lôi cuốn người đọc ngay từ những chương đầu tiên. Đấu La Thế Giới, một đại lục rộng lớn, cư dân đông đúc. Chức nghiệp cao quý nhất tại đây được gọi là Hồn Sư. Mỗi người sinh ra, đều có một vũ hồn bẩm sinh. Vũ hồn có thể là cái cày, cái cuốc, liêm đao... thuộc khối công cụ; một đóa hoa cúc, một cành mai... thuộc thực vật hệ; đến các vũ hồn cường đại như Tuyết Ảnh Ma Hùng, Tật Phong Ma Lang.... Để có thể trở thành hồn sư, ngoài vũ hồn cường đại, còn cần đến hồn lực để sử dụng vũ hồn đó, vũ hồn càng lớn, hồn lực càng cao, đại biểu cho thực lực mạnh mẽ tại Đấu la đại lục. Cứ 10 cấp hồn lực, vũ hồn có thể phụ gia thêm một cái hồn hoàn, có được từ việc liệp sát hồn thú, những quái thú mạnh mẽ, có tu vị hằng nghìn năm. Hành trình tu luyện, tìm hiểu bí ẩn cái chết của mẫu thân, bí mật tông sư của phụ thân, câu chuyện sẽ cho người đọc những trải nghiệm thú vị.</p>', 'Hoàn Tất (265/265)', 265, 'hoathinh', 'completed', 13, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"沈磊","avatar":""},{"name":"张琦","avatar":""},{"name":"Wei Zhai","avatar":""},{"name":"Dian Tao","avatar":""},{"name":"Lu Zhao","avatar":""},{"name":"赵乾景","avatar":""},{"name":"Zhihao Su","avatar":""},{"name":"Chanfei Li","avatar":""},{"name":"Ying Huang","avatar":""},{"name":"Xiang Xu","avatar":""},{"name":"Ruan Congqing","avatar":""},{"name":"許棕哲","avatar":""},{"name":"Shuang Liang","avatar":""},{"name":"秦紫翼","avatar":""},{"name":"赵乾景","avatar":""},{"name":"倪康","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324392);
