INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-dai', 'Triều Đại', 'Dynasties', 'https://phimimg.com/upload/vod/20240820-1/62d4d2c2758e760ef804c8dbdfc37d1e.jpg', 'https://phimimg.com/upload/vod/20240820-1/296e8b02df85bc70aeb4f2b5635375b0.jpg', '<p>Ngài David Attenborough mang đến cho bạn loạt phim về thế giới tự nhiên với tên gọi Các Triều Đại, một loạt phim cho ra mắt tháng 11 năm 2018 từ BBC Earth.

Chúng ta sẽ cùng được theo dõi những câu chuyện có thật về năm loài động vật nổi tiếng nhất, nhưng cũng đang có nguy cơ tuyệt chủng cao nhất trên thế giới. Đó là: Chim cánh cụt, tinh tinh, sư tử, chó hoang Châu Phi và hổ. Mỗi loài đều đang trong một cuộc đấu tranh khốc liệt chống lại các đối thủ và chống lại các thế lực tự nhiên, các gia đình này chiến đấu cho sự sống còn của chính chúng và cho tương lai của các triều đại của chúng</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324392);
