INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-22-ke-hanh-phap-zero', 'Thám Tử Lừng Danh Conan 22: Kẻ Hành Pháp Zero', 'Case Closed: Zero the Enforcer', 'https://phimimg.com/upload/vod/20231019-1/e9a6f4a08ac2af720937f8507ff64418.jpg', 'https://phimimg.com/upload/vod/20231019-1/2406bb467e6435cda705392936e73729.jpg', '<p>Conan Movie 22 xoay quanh nhân vật Tooru &quot;Zero&quot; Amuro và nghi vấn cảnh sát trưởng Kuroda là một trong những thành phần của tổ chức áo đen.&nbsp; &quot;Edge of Ocean&quot;, một cơ sở mới của Vịnh Tokyo sẽ là nơi tổ chức Hội nghị Thượng đỉnh Tokyo. Hội nghị sẽ được tổ chức vào ngày 1/5 và có tới 22.000 cảnh sát được huy động, nhưng một vụ nổ bom cực lớn đột ngột xảy ra tại cơ sở siêu hoành tráng này! Tại nơi đó, vào lúc xảy ra vụ việc, lại nhìn thấy bóng dáng của Amuro Tooru thuộc tổ chức bí mật của Cảnh sát Quốc gia với bí danh là &quot;Zero&quot; đang điều khiển các cảnh sát an ninh trên toàn quốc. Tại hiện trường, cảnh sát đã phát hiện dấu vân tay của Mori Kogoro và ông bị bắt. Để chứng minh ông Mori vô tội, Conan đã bắt tay vào điều tra nhưng liên tục bị &quot;kẻ 3 mặt&quot; Amuro cản đường.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2018, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Aya Ueto","avatar":""},{"name":"Daikichi Hakata","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Mikiko Enomoto","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Asako Dodo","avatar":""},{"name":"Yukimasa Kishin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
