INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-22-ke-hanh-phap-zero', 'Thám Tử Lừng Danh Conan 22: Kẻ Hành Pháp Zero', 'Case Closed: Zero the Enforcer', 'thám tử lừng danh conan 22: kẻ hành pháp zero case closed: zero the enforcer minami takayama kappei yamaguchi wakana yamazaki rikiya koyama toru furuya aya ueto daikichi hakata yukiko iwai wataru takagi ikue otani kenichi ogata megumi hayashibara naoko matsui mikiko enomoto gara takashima asako dodo yukimasa kishin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-tich-truyen', 'Vân Tịch Truyện', 'Legend Of Yun Xi', 'https://phimimg.com/upload/vod/20240815-1/1a5d72535ec4b7039d8a52d8b3da191b.jpg', 'https://phimimg.com/upload/vod/20240815-1/94be73ecd984ae289a1166ab90a1c509.jpg', '<p>Bộ phim Vân Tịch Truyện là câu chuyện kể về cuộc đời Hàn Vân Tịch, một cô gái tinh thông độc thuật. Do có sẹo độc trên mặt nên Hàn Vân Tịch luôn bị mọi người xa lánh, chê bai. Trong một cơ duyên, vì muốn tìm lại mẹ của mình, Vân Tịch nghe lệnh Thái hậu và Thiên Huy đế gả vào phủ Tần Vương, làm Tần Vương phi để thám thính tình hình của Tần Vương - Long Phi Dạ. Hàn Vân Tịch cũng khiến Cố Thất Thiếu động lòng với cô, luôn ra tay giúp đỡ, bảo vệ mỗi khi Vân Tịch gặp nguy hiểm. Trải qua nhiều biến cố, Hàn Vân Tịch động chân tình với Tần Vương, trợ giúp Long Phi Dạ phá giải các âm mưu của Hoàng thất Thiên Ninh quốc, Bắc Lệ và Tây Khâu. Sau này Hàn Vân Tịch vì muốn giải Độc cổ cho Long Phi Dạ đã hi sinh bản thân mình. Nhờ vào năng lực thần kì của chiếc vòng tay, Hàn Vân Tịch đã sống lại và cùng Long Phi Dạ quy ẩn núi rừng, sống một cuộc đời an ổn, bạc đầu giai lão, không chia không lìa.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 9, 2018, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鞠婧禕","avatar":""},{"name":"Zhang Zhehan","avatar":""},{"name":"米熱","avatar":""},{"name":"Hu Bing","avatar":""},{"name":"Lin Siyi","avatar":""},{"name":"Xu Jia Qi","avatar":""},{"name":"Wang Youshuo","avatar":""},{"name":"Chen Jiayi","avatar":""},{"name":"秦晓轩","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b4