INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-den-tu-hu-vo-phan-1', 'Cô Gái Đến Từ Hư Vô (Phần 1)', 'Girl From Nowhere (Season 1)', 'https://phimimg.com/upload/vod/20240811-1/cdc626981ce1724850ab7a3f410ee904.jpg', 'https://phimimg.com/upload/vod/20240811-1/cedbd563fbc9ee87826dc5bf9d2dddc4.jpg', '<p>“Người ta vẫn hay nói rằng những tháng năm học trò là khoảng thời gian đẹp đẽ nhất của cuộc đời người. Nhưng thật ra…”, đây chính là lời mở đầu gây tò mò của phim Girl From Nowhere (Dek Mai). Bộ phim lấy cảm hứng từ câu chuyện có thật, khai thác tệ nạn trong môi trường học đường, xoáy sâu vào những bí mật mà không ai dám vạch trần ra ánh sáng.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 13, 2018, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chicha Amatayakul","avatar":""},{"name":"Chanya McClory","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324392);
