INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vi-khach-kho-chieu-phan-2', 'Những Vị Khách Khó Chiều (Phần 2)', 'High Maintenance (Season 2)', 'https://phimimg.com/upload/vod/20240808-1/639850788e22dcca07d170ac733f5eef.jpg', 'https://phimimg.com/upload/vod/20240808-1/d0f9753ec52e0e294df7dbc531ee3ecf.jpg', '<p>Hãy cùng khám phá thói quen hàng ngày của một nhóm người New York đa dạng và cách họ thắp sáng mọi thứ. &quot;The Guy&quot; là một người giao cần sa vô danh có nhóm khách hàng bao gồm một nhóm nhân vật lập dị với chứng loạn thần kinh đa dạng như thành phố này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Sinclair","avatar":""},{"name":"Katja Blichfeld","avatar":""},{"name":"Katja Blichfeld","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
