INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-huy-diet', 'Vùng Hủy Diệt', 'Annihilation', 'https://phimimg.com/upload/vod/20231023-1/778051d1759c422011093c59c1dba204.jpg', 'https://phimimg.com/upload/vod/20231023-1/b8dead4ae930564d81087b0f5358f81a.jpg', '<p>Phim xoay quanh hành trình của nhà sinh học do người đẹp Natalie Portman thủ vai. Thành viên trong đoàn thám hiểm 5 nhà khoa học có nhiệm vụ thăm dò một khu vực bí ẩn nhằm tìm ra lời giải đáp cho căn bệnh kỳ quái mà chồng cô mắc phải sau khi trở về từ nơi đây. Sau khi chồng cô thám hiểm khu rừng này thì hiện tượng kỳ lạ bắt đầu xuất hiện. một căn bệnh không có lời giải, khiến cho anh trở thành một cái xác không hồn. Để tìm hiều căn bệnh cũng là con đường duy nhất để cứu chồng mình, cô cùng 4 cộng sự cùng nhau xâm nhập vào vùng đất kỳ ảo này. Một vùng đất bên trên phủ kín mây mù và khi bước qua bức tường plasma, họ sẽ tới một thế giới mới hoàn toàn lạ lẫm, những hiện tượng kỳ bí và những sinh vật, cây cối khác biệt hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Natalie Portman","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Tuva Novotny","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"John Schwab","avatar":""},{"name":"Sammy Hayman","avatar":""},{"name":"Josh Danford","avatar":""},{"name":"Kristen McGarrity","avatar":""},{"name":"Kumud Pant","avatar":""},{"name":"Honey Holmes","avatar":""},{"name":"Hiten Patel","avatar":""},{"name":"Kola Bokinni","avatar":""},{"name":"O","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324392);
