INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-anh-quoc-phan-5', 'Bóng Ma Anh Quốc (Phần 5)', 'Peaky Blinders (Season 5)', 'https://phimimg.com/upload/vod/20240730-1/bd859e4c5e599e1be2291802dc47e790.jpg', 'https://phimimg.com/upload/vod/20240730-1/15d006c2ceffbd28ba8b6edee9c3f89a.jpg', '<p>Khi gia đình Shelby vật lộn với vụ sụp đổ chứng khoán năm 1929, quyền lực của Tommy bị đe dọa bởi các thành viên nhỏ hơn trong gia đình và những đối thủ phát xít.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Jeffrey Postlethwaite","avatar":""},{"name":"Matthew Postlethwaite","avatar":""},{"name":"Ian Pe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
