INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-ky-kim-sao-the', 'Thư Ký Kim Sao Thế?', 'What''s Wrong with Secretary Kim', 'https://phimimg.com/upload/vod/20240729-1/3076a178e12a412decd75b3afa18bc04.jpg', 'https://phimimg.com/upload/vod/20240729-1/1ae80cef1d1876d74e994cb53b16d5bd.jpg', '<p>Phim Sao Thế Thư Ký Kim ? - Thư Ký Kim Sao Thế? xoay quanh câu chuyện tình lãng mạn của Lee Young Joon, một tài phiệt đời hai hoàn hảo nhưng quá yêu bản thân, và người trợ lí của anh ta, Kim Mi So, người được gọi là &quot;huyền thoại của giới thư ký&quot;. Trong phim, Park Min Young thủ vai Kim Mi So trong khi Park Seo Joon lần nữa hóa thân thành chàng trai giàu có giống như thời She Was Pretty. Kim Mi So là một nữ thư kí đã làm việc cho Lee Young Joon được 9 năm. Cô không những tài năng mà còn xinh đẹp, sở hữu nụ cười tỏa sáng, nhưng lại chưa từng yêu ai bao giờ. Việc Kim Min So nộp đơn thôi việc cho Lee Young Joon cùng nụ cười trên môi khiến anh trở nên đau đầu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박서준","avatar":""},{"name":"박민영","avatar":""},{"name":"이태환","avatar":""},{"name":"표예진","avatar":""},{"name":"김혜옥","avatar":""},{"name":"김병옥","avatar":""},{"name":"강기영","avatar":""},{"name":"Kang Hong-suk","avatar":""},{"name":"황찬성","avatar":""},{"name":"김예원","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"황보라","avatar":""},{"name":"Baek Eun-hae","avatar":""},{"name":"Heo Soon-Mi","avatar":""},{"name":"Kim Jung-woon","avatar":""},{"name":"Lee Jung-min","avatar":""},{"name":"서효림","avatar":""},{"name":"Moon Woo-jin","avatar":""},{"name":"Kim Ji-Yu","avatar":""},{"name":"Bae Gang-Yoo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
