INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-da-cho-ta-gap-nhau', 'Phép màu đã cho ta gặp nhau', 'The Miracle We Met', 'https://phimimg.com/upload/vod/20240718-1/f0d6094ae782809d5b06e69d5a93851a.jpg', 'https://phimimg.com/upload/vod/20240718-1/f9a2d96e6e84a23dc9f15ad116105863.jpg', '<p>Một người đàn ông chết trong một vụ tai nạn ô tô nhưng tỉnh dậy với linh hồn của một người khác. Anh trở thành người chủ của hai gia đình và đau khổ vì hai người vợ khác nhau của mình.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2018, 'Vietsub', 'FullHD', 'Hàn Quốc', 0, '[{"name":"김명민","avatar":""},{"name":"김현주","avatar":""},{"name":"라미란","avatar":""},{"name":"고창석","avatar":""},{"name":"Joseph Lee","avatar":""},{"name":"황보라","avatar":""},{"name":"최병모","avatar":""},{"name":"황석정","avatar":""},{"name":"김환희","avatar":""},{"name":"전석호","avatar":""},{"name":"윤지혜","avatar":""},{"name":"정석용","avatar":""},{"name":"카이","avatar":""},{"name":"배윤경","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
