INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-5', '100 Người Thử Nghiệm (Phần 5)', 'The 100 (Season 5)', 'https://phimimg.com/upload/vod/20240616-1/191ef0fe7bc4ede55c178c2af088781b.jpg', 'https://phimimg.com/upload/vod/20240616-1/ecd63b51ffdd44077c7e079f7410f414.jpg', '<p>Các lò hạt nhân còn sót lại bắt đầu rò rỉ và đang đốt cháy bầu khí quyển. Các anh hùng của chúng ta sẽ phải có trách nhiệm với nơi được gọi là Nhà, nơi mà các thế hệ tương lai sẽ sinh sôi nảy nở. Liệu họ có thể bắt đầu lại bằng cách ăn mừng hay bản chất ác độc sẽ khiến họ mất đi cơ hội ngoi lên từ đống tro tàn?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Eliza Taylor","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Bob Morley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324392);
