INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-canh-sat-chicago-phan-6', 'Sở Cảnh Sát Chicago (Phần 6)', 'Chicago P.D. (Season 6)', 'https://phimimg.com/upload/vod/20240608-1/7ed2346215b963ad73e89931cd3b91a2.jpg', 'https://phimimg.com/upload/vod/20240608-1/0bf5d718cb17f9d609ef64d04e54a79a.jpg', '<p>Một bộ phim cảnh sát hấp dẫn kể về những người đàn ông và phụ nữ thuộc Quận 21 của Sở Cảnh sát Chicago, những người đã sẵn sàng cống hiến hết mình để phục vụ và bảo vệ cộng đồng của mình. Quận 21 được tạo thành từ hai nhóm khác nhau rõ rệt: cảnh sát mặc đồng phục tuần tra và đối đầu với tội phạm đường phố của thành phố và Đơn vị Tình báo chống lại các tội phạm lớn của thành phố - tội phạm có tổ chức, buôn bán ma túy, giết người nổi tiếng và hơn thế nữa.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Beghe","avatar":""},{"name":"Tracy Spiridakos","avatar":""},{"name":"Marina Squerciati","avatar":""},{"name":"Patrick John Flueger","avatar":""},{"name":"LaRoyce Hawkins","avatar":""},{"name":"Benjamin Levy Aguilar","avatar":""},{"name":"Amy Morton","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
