INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('so-canh-sat-chicago-phan-6', 'Sở Cảnh Sát Chicago (Phần 6)', 'Chicago P.D. (Season 6)', 'sở cảnh sát chicago (phần 6) chicago p.d. (season 6) jason beghe tracy spiridakos marina squerciati patrick john flueger laroyce hawkins benjamin levy aguilar amy morton ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-alhambra', 'Ký ức Alhambra', 'Memories of the Alhambra', 'https://phimimg.com/upload/vod/20240702-1/d683da19d21c27290fe56bc27aafbea3.jpg', 'https://phimimg.com/upload/vod/20240702-1/3485288f4f004b629001116466e81191.jpg', '<p>Bộ phim Memories of the Alhambra (Hồi Ức Alhambra) xoay quanh mối tình vừa bí ẩn vừa lãng mạn giữa Jung Hee Joo (Park Shin Hye), một &quot;bà chủ&quot; nhà nghỉ và Yoo Jin Woo (Hyun Bin) - một CEO thiên tài đến Tây Ban Nha trong một chuyến công tác.

Jung Sae Joo (Chanyeol), em trai của Hee Joo đồng thời là một lập trình viên tài giỏi chỉ thích sống trong thế giới của riêng mình. Họ sẽ bị cuốn vào hàng loạt bí ẩn tại Granada, thành phố của ma thuật, và từ đó hình thành những mối liên kết đặc biệt với nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"현빈","avatar":""},{"name":"박신혜","avatar":""},{"name":"찬열","avatar":""},{"name":"한보름","avatar":""},{"name":"박훈","avatar":""},{"name":"이학주","avatar":""},{"name":"조현철","avatar":""},{"name":"민진웅","avatar":""},{"name":"김의성","avatar":""},{"name":"이레","avatar":""},{"name":"이승준","avatar":""},{"name":"이시원","avatar":""},{"name":"이재욱","avatar":""},{"name":"Bret Allan Lindquist","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324392);
