INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-uc-alhambra', 'Ký ức Alhambra', 'Memories of the Alhambra', 'ký ức alhambra memories of the alhambra 현빈 박신혜 찬열 한보름 박훈 이학주 조현철 민진웅 김의성 이레 이승준 이시원 이재욱 bret allan lindquist ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-gau-bac-cuc-chia-khoa-than-ky', 'Đầu Gấu Bắc Cực: Chìa Khóa Thần Kỳ', 'Norm of the North: Keys to the Kingdom', 'https://phimimg.com/upload/vod/20231026-1/f01d0b3be04f1c815e294c6f903daa79.jpg', 'https://phimimg.com/upload/vod/20231026-1/cdff93dbc3c27448a5fa2413928e1b7d.jpg', '<p>Hành trình phiêu lưu của chú gấu Norm cùng 3 người bạn của mình ở New York sau khi quê hương Bắc Cực của chú có dấu hiệu bị tan chảy. Để tồn tại ở New York, Norm chấp nhận làm &quot;một con thú mua vui&quot; để kiếm tiền cho 1 tập đoàn lớn và đây cũng là cách để Norm có thể tiếp cận được tập đoàn này vì có nhiều thông tin cho thấy tập đoàn này chính là thủ phạm khiến cho ngôi nhà Bắc Cực bị tan chảy.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Andrew Toth","avatar":""},{"name":"Maya Feltheimer","avatar":""},{"name":"Jennifer Cameron","avatar":""},{"name":"Cole Howard","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Alan Marriott","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Lisa Durupt","avatar":""},{"name":"Brian Dobson","avatar":""},{"name":"Marco Soriano","avatar":""},{"name":"Maureen Jones","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324392);
