INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-ngu-ho-tu-than', 'Mỹ Nhân Ngư: Hồ Tử Thần', 'The Mermaid: Lake of the Dead', 'https://phimimg.com/upload/vod/20231026-1/0aa68bf71bf316771aba1c176d4a4a58.jpg', 'https://phimimg.com/upload/vod/20231026-1/8fe51818ac24ced185baf0a4d25558cf.jpg', '<p>Truyền thuyết kể rằng, nếu bạn bơi tại hồ tử thần vào ban đêm, Mỹ nhân ngư sẽ xuất hiện… Từ nhiều năm trước, một cô gái trẻ không may bị chết đuối và trở thành Tiên cá hắc ám dưới Hồ Tử Thần. Ả ta sa vào lưới tình với Roman và muốn giữ chàng cho riêng mình mãi mãi. Để vĩnh viễn chiếm đoạt Roman, ả âm mưu dìm hôn thê Marina của chàng xuống đáy hồ. Điều gì sẽ xảy ra? Liệu Marina có cứu được chính mình cùng với Roman?”</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Victoria Agalakova","avatar":""},{"name":"Efim Petrunin","avatar":""},{"name":"Nikita Elenev","avatar":""},{"name":"Sesil Plezhe","avatar":""},{"name":"Sofya Shidlovskaya","avatar":""},{"name":"Igor Khripunov","avatar":""},{"name":"Dariya Yartseva","avatar":""},{"name":"Dmitry Yartsev","avatar":""},{"name":"Alla Artamonova","avatar":""},{"name":"Emil Sales","avatar":""},{"name":"Nadezhda Igoshina","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324392);
