INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-lopez', 'Siêu nhân López', 'Superlopez', 'https://phimimg.com/upload/vod/20230922-1/e64dd0fd44dfb115af99171767e25d0e.jpg', 'https://phimimg.com/upload/vod/20230922-1/3626a558a2dd178ae9efa79b40a0fb02.jpg', '<p>Juan López phải cân bằng công việc văn phòng với những chiến công anh hùng để cứu lấy tình yêu của đời mình và hành tinh quê hương Chitón.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Dani Rovira","avatar":""},{"name":"Alexandra Jiménez","avatar":""},{"name":"Julián López","avatar":""},{"name":"Maribel Verdú","avatar":""},{"name":"Pedro Casablanc","avatar":""},{"name":"Carlos Zabala","avatar":""},{"name":"Gracia Olayo","avatar":""},{"name":"Nao Albet","avatar":""},{"name":"Gonzalo de Castro","avatar":""},{"name":"Marc Rodríguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324392);
