INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-chet', 'Thần Chết', 'Death Wish', 'https://phimimg.com/upload/vod/20231021-1/1e9427a6cefb1ceaf9edfb95f6a9d530.jpg', 'https://phimimg.com/upload/vod/20231021-1/9592becd4922eb636daadea9802525b3.jpg', '<p>Được MGM làm lại dựa trên bộ phim gốc cùng tên năm 1974, nội dung phim tập trung vào Paul Kersey, một bác sĩ phẫu thuật sống tại Chicago, người đã nhận thấy thành phố nơi ông đang sinh sống luôn bị bao trùm bởi những hành động bạo lực và phi nhân tính mà trong đó vợ và cô con gái của Paul cũng là nạn nhân. Lực lượng cảnh sát không thể khống chế được hết những tên tội phạm trong thành phố, vậy nên đây chính là lúc Paul trả thù và làm người hùng.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Camila Morrone","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"Len Cariou","avatar":""},{"name":"Jack Kesy","avatar":""},{"name":"Ronnie Gene Blevins","avatar":""},{"name":"Kirby Bliss Blanton","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Ian Matthews","avatar":""},{"name":"Nathaly Thibault","avatar":""},{"name":"Christopher Tyson","avatar":""},{"name":"Melantha Blacktho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
