INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ma-jack-xay', 'Ngôi Nhà Mà Jack Xây', 'The House That Jack Built', 'https://phimimg.com/upload/vod/20240607-1/99def376cc31cd4d90ac151b8a81e9ab.jpg', 'https://phimimg.com/upload/vod/20240607-1/03e36039b83ff42a9a23d452138c81d9.jpg', '<p>The House that Jack Built là bộ phim kể về tên giết người hàng loạt Jack do nam diễn viên Matt Dillon đóng vai chính. Đây là bộ phim được lấy cảm hứng từ chính tên sát nhân có thật trong lịch sử những vụ án giết người hàng loạt tại Mỹ. Trong phim, Jack là một kiến trúc sư thất nghiệp sống trong cô đơn. Anh ta tìm thấy niềm vui trong những “bữa tiệc” giết người man rợ và xem đó là nghệ thuật...</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Matt Dillon","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Sofie Gråbøl","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Jack McKenzie","avatar":""},{"name":"Mathias Hjelm","avatar":""},{"name":"Ed Speleers","avatar":""},{"name":"Emil Tholstrup","avatar":""},{"name":"Marijana Janković","avatar":""},{"name":"Carina Skenhede","avatar":""},{"name":"Rocco Day","avatar":""},{"name":"Cohen Day","avatar":""},{"name":"Robert Jezek","avatar":""},{"name":"Osy Ikhile","avatar":""},{"name":"Christian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
