INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-choi-sieu-dang', 'Những Tay Chơi Siêu Đẳng', 'The Player', 'https://phimimg.com/upload/vod/20240530-1/aa1ccccd24a19b30f117ba2a6dd81343.jpg', 'https://phimimg.com/upload/vod/20240530-1/2ad712c2548a57fe445532ad6c8bb1ba.jpg', '<p>Xoay quanh một nhóm chuyên giải quyết những vụ án hình sự bao gồm những tay kì cựu như một kẻ lừa đảo thiên tài, một tay đấm giỏi võ, một tin tặc thông minh và một tay lái chuyên nghiệp có khả năng đánh lái cừ khôi. Nhiệm vụ của họ là truy tìm những tài sản mà bọn tội phạm đã đánh ...</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2018, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"송승헌","avatar":""},{"name":"오연서","avatar":""},{"name":"태원석","avatar":""},{"name":"이시언","avatar":""},{"name":"장규리","avatar":""},{"name":"하도권","avatar":""},{"name":"허성태","avatar":""},{"name":"이준혁","avatar":""},{"name":"조성하","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324392);
