INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asako-i-ii', 'Asako I & II', 'Asako I & II', 'https://phimimg.com/upload/vod/20240503-1/7e7ee2db9711f81c86447fa7e5e7d1a9.jpg', 'https://phimimg.com/upload/vod/20240503-1/dc79e9284046a346897ce800ffab9ce8.jpg', '<p>Asako và Baku chia sẻ một mối tình lãng mạn mãnh liệt và trọn vẹn—nhưng một ngày nọ, Baku đầy tâm trạng nổi lên và biến mất. Hai năm sau, khi chuyển từ Osaka đến Tokyo, Asako gặp được người giống hệt Baku.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Erika Karata","avatar":""},{"name":"Masahiro Higashide","avatar":""},{"name":"Rio Yamashita","avatar":""},{"name":"Sairi Ito","avatar":""},{"name":"Koji Seto","avatar":""},{"name":"Daichi Watanabe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324392);
