INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-vo-cua-em', 'Chàng Vợ Của Em', 'My Mr. Wife', 'https://phimimg.com/upload/vod/20231011-1/101b5a94b116f99022439484f8f60986.jpg', 'https://phimimg.com/upload/vod/20231011-1/792324a2f1cd6cd5b246e0db7cbb9add.jpg', '<p>Từ trước tới nay, người Việt vốn quen với hình ảnh người phụ nữ lúi húi trong bếp, phục vụ cơm nước cho chồng con, còn người đàn ông thì ra ngoài xã hội làm việc, kiếm tiền.&nbsp; Song, mọi chuyện hoàn toàn khác đối với Mai (Phương Anh Đào). Xinh đẹp, mạnh mẽ, giàu có, nhưng đổi lại, cô gái luôn bận rộn trăm công nghìn việc tại công ty, hàng ngày phải đối đầu với “đám đàn ông ở công ty”.&nbsp; Mai bận đến nỗi không có thời gian chăm sóc chó cưng, nhà cửa thì bừa bộn, và bản thân không còn khái niệm “bữa cơm gia đình”. Người phụ nữ hiện đại, sành điệu ấy chẳng cần bất cứ đấng mày râu nào chu cấp kinh tế, nhưng lại khao khát một “chàng vợ” có thể thay mình tề gia nội trợ, làm hậu phương vững chắc cho cô thỏa chí tung hoành.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Phương Anh Đào","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Thanh Trúc","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Vân Trang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324392);
