INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-6', 'Trại Giam Kiểu Mỹ (Phần 6)', 'Orange Is The New Black (Season 6)', 'https://phimimg.com/upload/vod/20240302-1/288ceac7669626f83980e37eff4ef4a0.jpg', 'https://phimimg.com/upload/vod/20240302-1/cc2639b9e66ed3e15af96987141d208a.jpg', '<p>Được chuyển thể từ cuốn hồi ký Orange Is the New Black Season 6 của Piper Kerman, kể về Piper Chapman, một phụ nữ đang có đầy đủ mọi thứ: nhà cửa, công việc và một người chồng sắp cưới. Bỗng một hôm, cô phải vào tù vì dính líu tới vụ buôn ma túy từ 10 năm trước, cùng người tình đồng tính trước đây. Piper sẽ phải làm sao để sống sót trong tù, cũng như giữ được tình yêu của mình?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2018, 'Vietsub', 'HD 720p', 'Âu Mỹ', 0, '[{"name":"Taylor Schilling","avatar":""},{"name":"Danielle Brooks","avatar":""},{"name":"Taryn Manning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324392);
