INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-nhan-tinh', 'Những Cô Nhân Tình', 'Mistress', 'https://phimimg.com/upload/vod/20240302-1/cbdac9f22e2a72822aedbfaa83ab9a31.jpg', 'https://phimimg.com/upload/vod/20240302-1/e258d6928442e8b6358cf2a8fe7e97f0.jpg', '<p>Phim Những Cô Nhân Tình là phim xoay quanh tình bạn, tình yêu và những mối quan hệ phúc tạp giữa bốn người phụ nữ thân thiết, Bộ phim cũng đã từng được remake tại Mĩ. Trong bản phim hàn remake, Han ha In vào vai Se Yeon, một góa phụ sống với con gái mình sau khi chống chết trong một vụ tai nạn ...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2018, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ga In","avatar":""},{"name":"Shin Hyun Bin","avatar":""},{"name":"Choi Hee Seo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
