INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-du-lich-lang-man-cua-nguoi-vo', 'Chuyến Du Lịch Lãng Mạn Của Người Vợ', 'Viva La Romance', 'https://phimimg.com/upload/vod/20240302-1/c471c7f1bfb48c4992b545d9d32f0a5f.jpg', 'https://phimimg.com/upload/vod/20240302-1/b3dedc53ee8001fa4c81e19d24dcd34d.jpg', '<p>Đây là một chương trình quan sát và chữa bệnh cho các cặp đôi hoàn toàn mới. Nhóm vợ gồm bốn nữ diễn viên Xie Na, Ying Caier, Ying Er và Cheng Lisha bắt đầu một hành trình lãng mạn, trong khi nhóm chồng ở lại nhà kho để quan sát từ xa những người vợ trong cuộc hành trình và tìm hiểu về họ, một khía cạnh khác của cuộc sống. Trong cuộc đối thoại xuyên thời gian và không gian này, các cặp vợ chồng xem xét lại mối quan hệ của họ và hàn gắn cuộc hôn nhân của họ. Bằng cách thể hiện những mối quan hệ vợ chồng khác nhau, hãy cùng khán giả khám phá mật mã của một cuộc hôn nhân hạnh phúc.</p>', 'Hoàn Tất (7/7)', 7, 'tvshows', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324392);
