INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-tu-hoang', 'Phượng Tù Hoàng', 'Untouchable Lovers', 'https://phimimg.com/upload/vod/20240229-1/9b80ac47a5f860f7ef90f2b6aafb1817.jpg', 'https://phimimg.com/upload/vod/20240229-1/bd41e8cd877bbdfcaff281151ffcaf2f.jpg', '<p>Thiên Cơ Các - một tổ chức hàng đầu muốn lật đổ vị vua đang cai trị thời nhà Lưu Tống là Lưu Tử Nghiệp. Để thực hiện âm mưu, Thiên Cơ Các đã âm thầm thay thế chị gái của Lưu Tử Nghiệp là Sơn Âm công chúa Lưu Sở Ngọc bằng một người giống hệt. Dưới thân phận của Sở Ngọc, cô đã gặp gián điệp của Bắc Ngụy là Dung Chỉ. Trải qua nhiều khó khăn và hiểu lầm, cuối cùng Sở Ngọc và Dung Chỉ cũng nhận ra được tình cảm thật sự. Sau bao trắc trở, mối nhân duyên chưa dứt vẫn đưa họ đến với nhau.</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Trương Hinh Dư","avatar":""},{"name":"Trương Dật Kiệt","avatar":""},{"name":"Bạch Lộc","avatar":""},{"name":"Hứa Khải","avatar":""},{"name":"Ngô Cẩn Ngôn","avatar":""},{"name":"Triệu Lộ Tư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324392);
