INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mary-poppins-tro-lai', 'Mary Poppins Trở Lại', 'Mary Poppins Returns', 'https://phimimg.com/upload/vod/20240228-1/766d9b959d96847a79af777d60843788.jpg', 'https://phimimg.com/upload/vod/20240228-1/8e6611bea55471b70d495bc1683fb6f0.jpg', '<p>Trong bộ phim sắp ra mắt của hãng phim Disney, Mary Poppins Returns, một phần phim hoàn toàn mới kế thừa đúng tinh thần của tác phẩm gốc, Marry Popins quay trở về để giúp đỡ thế hệ sau của gia đình Banks tìm thấy niềm vui và điều kì diệu trong cuộc sống mà họ đang dần đánh mất. Emily Blunt hóa thân thành cô bảo mẫu gần như hoàn hảo với khả năng phép thuật đặc biệt. Cô có thể biến bất cứ công việc nào thành một chuyến phiêu lưu tuyệt vời khó quên. Bộ phim còn có sự góp mặt của Lin-Manuel Miranda thủ vai người bạn thân thiết của cô, Jack - một anh chàng làm nghề thắp đèn với lối sống tích cực, luôn luôn muốn đem ánh sáng đến khắp con phố ở London. bằng một cách thần kì nào đó đã quay trở lại cuộc sống của gia đình họ và cùng với sự giúp đỡ của Jack, cô đã mang niềm vui trở lại căn nhà của gia đình nhà Banks.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Pixie Davies","avatar":""},{"name":"Nathanael Saleh","avatar":""},{"name":"Lin-Manuel Miranda","avatar":""},{"name":"Joel Dawson","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Colin Firth","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324392);
