INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-vi-tinh-yeu-rat-phuc-tap', 'Bởi Vì Tình Yêu Rất Phức Tạp', 'It''s Complicated', 'https://phimimg.com/upload/vod/20240229-1/9abe28202ea07fbeded1cb84074f17e3.jpg', 'https://phimimg.com/upload/vod/20240229-1/0d948498b23d7c542477953c24ca053c.jpg', '<p>Nói về thực tại các mối quan hệ đang tồn tại trong xã hội hiện đại, khiến chúng ta phải đặt câu hỏi về niềm tin của chính mình trong các mối quan hệ này. Liệu hôn nhân có phải là chương cuối cùng của tình yêu không? Tình dục có thực sự là một phần thiết yếu trong một mối quan hệ? Có phải tình yêu chỉ dành riêng cho hai người?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mardthong Sarawut","avatar":""},{"name":"Tangmo Nida Patcharaveerapong","avatar":""},{"name":"Nong Thana Chatborirak","avatar":""},{"name":"Baitoei Zuvapit Traipornworakit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324392);
