INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-canh-sat', 'Đời Cảnh Sát', 'Live', 'https://phimimg.com/upload/vod/20240229-1/914e42d2dd56275fea776b15cde6fb0d.jpg', 'https://phimimg.com/upload/vod/20240229-1/d949f6a972fb8d66297606e3754277e6.jpg', '<p>Các cảnh sát thuộc đội tuần tra bận rộn nhất Hàn Quốc luôn nỗ lực ngày đêm để bảo vệ luật pháp và sự yên bình – nhưng trong thực tế, trật tự lại là điều rất xa vời.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Yu Mi","avatar":""},{"name":"Lee Kwang Soo","avatar":""},{"name":"Bae Seong Woo","avatar":""},{"name":"Bae Jong Ok","avatar":""},{"name":"Lee Soon Jae","avatar":""},{"name":"Sung Dong Il","avatar":""},{"name":"Jang Hyun Sung","avatar":""},{"name":"Lee Si Eon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
