INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-mat-bao-kich', 'Điềm Mật Bạo Kích', 'Sweet Combat', 'https://phimimg.com/upload/vod/20240229-1/816c439ce18d9a0c5dcf6f909f255134.jpg', 'https://phimimg.com/upload/vod/20240229-1/97f6f7cd027a8f772ee4473bd6eca308.jpg', '<p>Chàng trai trẻ Mai Minh Thiên (Lộc Hàm) xuất thân trong một gia đình nghèo khó, phải bỏ học đi làm thêm kiếm tiền, là người dày dặn kinh nghiệm xã hội. Anh nuôi hoài bão trở thành vận động viên boxing chuyên nghiệp. Để đạt được ước mơ, Minh Thiên đã phải cố gắng hơn bạn bè đồng trang lứa rất nhiều. Là một thanh niên có chí tiến thủ, ngoan cường, có thể âm thầm chịu đựng mọi gian khổ, thách thức. Quan Hiểu Đồng vai Phượng Vũ, người được mệnh danh là “nữ vương boxing”, bề ngoài có vẻ lạnh lùng thờ ơ nhưng nội tâm cũng yếu đuối, nhạy cảm như bao cô gái khác. Phượng Vũ và Minh Thiên sẽ cùng nhau viết lên câu chuyện tình đẹp như mơ. Liệu điều gì sẽ xảy ra với một cô gái “bách chiến bách thắng” và chàng trai không xuất sắc trong đấm bốc ?</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lộc Hàm","avatar":""},{"name":"Triệu Việt","avatar":""},{"name":"Quan Hiểu Đông","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324392);
