INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-than-xe-om', 'Nam Thần Xe Ôm', 'Bikeman', 'https://phimimg.com/upload/vod/20240228-1/091a3f6fd1676b2a0b09f8f6b3462adc.jpg', 'https://phimimg.com/upload/vod/20240228-1/76b4c4681a55fb2dcbf29064fb02ca33.jpg', '<p>Giả làm nhân viên ngân hàng với gia đình, một tài xế xe ôm nhanh nhẹn phải vật lộn để duy trì màn kịch đó khi tình cờ gặp lại người anh thầm thích hồi nhỏ.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pachara Chirathivat","avatar":""},{"name":"Jennifer Kim","avatar":""},{"name":"Sananthachat Thanapatpisal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324392);
