INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-rung-sau', 'Quái Thú Rừng Sâu', 'Wildling', 'https://phimimg.com/upload/vod/20240228-1/f2d8426a0b8e27b2ebf87b69d7db43c5.jpg', 'https://phimimg.com/upload/vod/20240228-1/43f91d539c75635c5d6f3b47983fce89.jpg', '<p>Không giống với những đứa trẻ khác, Anna lớn lên tại một căn gác được trông giữ chặt chẽ bởi một người đàn ông bí ẩn và luôn bị ám ảnh về tên quái vật ăn thịt trẻ con có tên là Wildling. Vào năm 16 tuổi, cô được giải thoát và bắt đầu một cuộc sống bình thường. Thế nhưng khi Anna bước vào tuổi dậy thì cũng là lúc những cơn ác mộng ập tới. Chúng dẫn cô đến với một bí mật đáng sợ đã bị che giấu bấy lâu nay…</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324392);
