INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhi-lang-than-chi-tam-muc', 'Nhị Lang Thần Chi Tam Mục', 'Eriro God', 'https://phimimg.com/upload/vod/20240228-1/4370ee0c667e7d774ae96c684e5c6682.jpg', 'https://phimimg.com/upload/vod/20240228-1/bba34120abd82934ddb54c5c194b9e8d.jpg', '<p>Nhị Lang Thần Chi Tam Mục - Eriro God:Trước kiếp số, yêu giới gây loạn nhân gian, thiên thần hạ giới hàng yêu, tam giới hỗn chiến, sinh linh đồ thán. Cuối cùng Nguyên Thủy Thiên Tôn chấm dứt trận chiến, luyện hóa vong linh tam giới thành một viên Thông Minh Linh Châu, giao cho đệ tử dưới tòa Ngọc Đỉnh Chân Nhân canh giữ. Vì thân thế phi phàm, Dương Tiễn bị Tam Giới Linh Châu pháp lực vô biên nhập vào, trong lúc bị tiên pháp linh châu dày vò, cũng trở thành “bảo vật” bị người khác tranh đoạt. Trải bao kiếp nạn, vì bảo vệ người nhà và người yêu, Dương Tiễn cuối cùng hóa Thông Minh Linh Châu thành thiên nhãn, thiên đình phong làm “Tam Mục Thần Quân”</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lữ Dịch San","avatar":""},{"name":"Phạm Kim Hiên","avatar":""},{"name":"Tương Hoài","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324392);
