INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-quy', 'Chúa Quỷ', 'The Golem', 'https://phimimg.com/upload/vod/20240228-1/b48ea1be8f70bac45300940f2a5dafc6.jpg', 'https://phimimg.com/upload/vod/20240228-1/732c1f0391d846c45d0f7c6d5d5af677.jpg', '<p>Nội dung phim kể về một ngôi làng của người Do Thái, nơi đây vốn rất hạnh phúc và bình yên với cuộc sống đơn giản. Tuy nhiên, một dịch bệnh kỳ lạ bùng phát đã lấy đi sinh mạng của rất nhiều người dân quanh đây khiến tất cả hoang mang và sợ hãi. Hanna, người phụ nữ mạnh mẽ của gia tộc, cô quyết tâm tìm cách cứu dỗi sự sống cho nơi này. Và bí mật tạo ra một Golem có sức mạnh phi thường dựa trên cuốn sách thần bí của đáng sáo tạo được Hanna áp dụng. Tuy đã được báo được sự nguy hiểm đến từ hành động này nhưng Hanna vẫn quyết định tạo ra Golem, liệu cô sẽ phải đối mặt với những gì.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hani Furstenberg","avatar":""},{"name":"Ishai Golan","avatar":""},{"name":"Alex Tritenko","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324392);
