INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-ngam', 'Mật Vụ Ngầm', 'Black Water', 'null', 'https://phimimg.com/upload/vod/20240220-1/8a3eb9f4b28002fd7eb7ea696f544e2c.jpg', '<p>Mật Vụ Ngầm - Black Water xoay quanh cuộc trốn chạy của anh chàng Wheeler khỏi chiếc tàu ngầm bí ẩn mà mình đang bị giam giữ. Sau khi tỉnh dậy vào một ngày, anh chàng này đã nhận ra mình đang bị bắt cóc bởi những tên CIA (Cơ quan tình báo trung ương Mỹ) biến chất. Từ đó, anh đang phải tìm mọi cách, tận dụng hết khả năng để thoát khỏi nơi đó.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Kilpatrick","avatar":""},{"name":" Jean-Claude Van Damme","avatar":""},{"name":"Dolph Lundgren","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324392);
