INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-hom-nay-den-luot-toi', 'Từ Hôm Nay, Đến Lượt Tôi!', 'From Today, It''s My Turn!!', 'https://phimimg.com/upload/vod/20240215-1/6ef5b1d497b58755594f9bed345212a6.jpg', 'https://phimimg.com/upload/vod/20240215-1/b1b435be2684fdf9170b29e4e623e155.jpg', '<p>Để thay đổi, Mitsuhashi và Ito vào vai những trai hư không biết sợ để làm mới bản thân ở trường cấp ba mới, khiến dân anh chị trong trường nổi điên.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kaku Kento","avatar":""},{"name":"Ito Kentaro","avatar":""},{"name":"Nana Seino","avatar":""},{"name":"Hashimoto Kanna","avatar":""},{"name":"Nakano Taiga","avatar":""},{"name":"Yamoto Yuma","avatar":""},{"name":"Wakatsuki Yumi","avatar":""},{"name":"Masaki Reiya","avatar":""},{"name":"Jiro","avatar":""},{"name":"Hasegawa Shinobu","avatar":""},{"name":"Izuka Kenta","avatar":""},{"name":"Aihara Mika","avatar":""},{"name":"Suzuki Nobuyuki","avatar":""},{"name":"Isomura Hayato","avatar":""},{"name":"Muro Tsuyoshi","avatar":""},{"name":"Jun Sena","avatar":""},{"name":"Sato Jiro","avatar":""},{"name":"Yoshida","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324392);
