INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-hom-nay-den-luot-toi', 'Từ Hôm Nay, Đến Lượt Tôi!', 'From Today, It''s My Turn!!', 'từ hôm nay, đến lượt tôi! from today, it''s my turn!! kaku kento ito kentaro nana seino hashimoto kanna nakano taiga yamoto yuma wakatsuki yumi masaki reiya jiro hasegawa shinobu izuka kenta aihara mika suzuki nobuyuki isomura hayato muro tsuyoshi jun sena sato jiro yoshida ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-sao-bang-ngoai-truyen', 'Vườn Sao Băng Ngoại Truyện', 'Hana Nochi Hare: HanaDan Next Season', 'https://phimimg.com/upload/vod/20240215-1/637a85ebed53c10040625faba6e36cc2.jpg', 'https://phimimg.com/upload/vod/20240215-1/3898965bce12f1ed6bf3eb20dc9071b8.jpg', '<p>Con Nhà Giàu phiên bản mới sẽ chuyển thể phần hậu truyện của bộ manga chính chủ với tên gọi Hana Nochi Hare / Hana Dan Next Season (Con Nhà Giàu 2). Bối cảnh của phim diễn ra ở Học viện Eitoku 10 năm sau khi nhóm F4 tốt nghiệp. Tình hình ở Eitoku hiện tại vô cùng bi đát. Số học sinh giảm đi rõ rệt vì khủng hoảng kinh tế, trong khi số lượng trường đối thủ ngày càng tăng. Thống trị Eitoku hiện tại là nhóm C5 (Correct 5) gồm 5 học sinh tiêu biểu, dẫn đầu là Kakuragi. Oto là con gái của một cựu CEO đã từng có cuộc sống thượng lưu, cho đến khi bố cô ấy phá sản. Cô ấy cũng có một vị hôn phu, Tenma, hội trưởng hội học sinh ở ngôi trường đối thủ của Học viên Eitoku. Vườn Sao Băng Ngoại Truyện bắt đầu khi nhóm C5 tiến hành lùng sục và loại trừ các học viên có gia cảnh bần hàn đang ẩn nấp trong trường. Khi Haruto và Oto đụng độ, họ vô tình biết được bí mật riêng tư của nhau. Một nàng công chúa hết thời gặp gỡ một hoàng tử lập dị, cả hai đi đến quyết định</p>', 'Full', 11, 'series', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nakagawa Taishi","avatar":""},{"name":"Hirano Sho","avatar":""},{"name":"Iitoyo Marie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324392);
