INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-sieu-nhan', 'Hành Tinh Siêu Nhân', 'Krypton', 'https://phimimg.com/upload/vod/20240215-1/b7703e48f6a0c10c76c031097d90f89b.jpg', 'https://phimimg.com/upload/vod/20240215-1/77f7d06390863c280d605389e727a5eb.jpg', '<p>Phim Hành Tinh Siêu Nhân - Krypton 2018: lấy bối cảnh quê hương của Superman - hành tinh Krypton trước khi bị phá hủy. Nhân vật chính của phim là ông nội của Superman - Seg-El, người đàn ông đã phải chiến đấu để chuộc lại danh dự của gia đình và cứu vớt thế giới khỏi sự hỗn loạn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cameron Cuffe","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Elliot Cowan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324392);
