INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-go-2018', 'Gặp Gỡ', 'Encounter', 'https://phimimg.com/upload/vod/20240209-1/b05f218a65e98328c70bd7c1b623a535.jpg', 'https://phimimg.com/upload/vod/20240209-1/39b37af927b6e97d2461f41cb34fbc46.jpg', '<p>Cha Soo Hyun (Song Hye Kyo thủ vai) là đại diện khách sạn, chưa bao giờ được sống theo ý muốn của mình mình. Kim Jin Hyuk (Park Bo Gum thủ vai), một người có một tâm hồn trong sáng, sống một cách hạnh phúc và trân trọng cuộc đời. Sau một lần tình cờ gặp gỡ, câu chuyện tình yêu lãng mạn đầy cảm động của hai người bắt đầu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Hye-Kyo","avatar":""},{"name":"Park Bo Gum","avatar":""},{"name":"Jang Seungjo","avatar":""},{"name":"차화연","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324392);
