INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-dung-tren-cau-ngam-phong-canh', 'Em Đứng Trên Cầu Ngắm Phong Cảnh', 'To Love, To Heal', 'https://phimimg.com/upload/vod/20240205-1/046cbb70b9d68bb36b5be0a4020f0c21.jpg', 'https://phimimg.com/upload/vod/20240205-1/f4fda165044da7e240b1e4680d7365fe.jpg', '<p>Phim Em Đứng Trên Cầu Ngắm Phong Cảnh chuyển thể từ tiểu thuyết cùng tên của tác giả Cố Tây Tước kể về câu chuyện tình của Tiêu Thủy Quang (Lý Khê Nhuế) và Chương Tranh Lam (Khương Triều). Phim là hành trình vượt qua nỗi đau và tìm kiếm hạnh phúc mới của một cô gái đã không may mất đi mối tình đầu của mình bởi một tai nạn ngoài ý muốn...Tổng giám đốc công ty game Chương Tranh Lam vô tình quen biết và yêu giáo sư kiếm đạo Tiêu Thủy Quang, bèn dùng nhiều cách thức để bắt lấy cơ hội tiếp cận nữ thần, đồng thời luôn âm thầm bên cạnh giúp đỡ Tiêu Thủy Quang vượt qua vết thương tình cảm, giúp cô đón nhận tình yêu mới...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Khương Triều","avatar":""},{"name":"Lý Khê Nhuế","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
