INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-huong-cua-mot-nguoi-phu-nu', 'Mùi Hương Của Một Người Phụ Nữ', 'Scent Of A Woman', 'https://phimimg.com/upload/vod/20240220-1/6493bb959cc71afb40111c69d6a2057a.jpg', 'https://phimimg.com/upload/vod/20240220-1/2c96824e55f626fdc8184b6da075670e.jpg', '<p>Lấy bối cảnh hiện đại đan xen quá khứ, Plerngfah và Tuanai sống ở thời hiện đại nhưng họ luôn nhớ về bản thân 1500 năm trước. Plerngfah - chàng phóng viên và Tuanai - cô giáo xinh đẹp và hai người yêu nhau từ kiếp trước. Mọi chuyện bắt đầu từ cái chết của Khun Utaiyothin - một người lính bị cô gái yêu đơn phương vì hiểu lầm nên hận. Khi Khun chết thì vợ anh – Duangkae - đang mang thai. Với lời ước hẹn của hai vợ chồng rằng Tình yêu là sự gắn kết sẽ đưa linh hồn hai ta gặp lại nhau đã dẫn lối để họ tìm được nhau ở thời hiện đại.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"James Jirayu Tangsrisuk","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324392);
