INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-song-dap-gio', 'Cưỡi Sóng Đạp Gió', 'Duckweed', 'https://phimimg.com/upload/vod/20240219-1/cea944cc5af8db581446cf5455dedd96.jpg', 'https://phimimg.com/upload/vod/20240219-1/bda3a27e349a424996349f24f72e38d0.jpg', '<p>Năm 2020, A Lãng là một chàng trai trẻ đam mê tốc độ và kiên quyết trở thành tay đua cự phách. Tuy nhiên, cha anh là A Chính lại luôn phản đối ước mơ của con trai. A Lãng đã nỗ lực giành giải vô địch để chứng minh cho cha anh thấy khả năng của mình. Và anh đã thành công. Sau khi bước lên bục vinh quang, hai cha con A Lãng đã gặp tai nạn xe hơi thảm khốc. Khi tỉnh lại A lãng bất ngờ phát hiện mình đã xuyên không về Thượng Hải năm 1998, tại đây anh gặp lại chính cha mình thời trai trẻ…. Cũng từ đó anh bắt đầu cuộc phiêu lưu kề vai sát cánh cùng cha mình, đồng thời cũng biết được người mẹ mà anh chưa từng được gặp mặt.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Bành Vu Yến","avatar":""},{"name":"Đặng Siêu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324392);
