INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-diet-quy', 'Kẻ Diệt Quỷ', 'Corbin Nash', 'https://phimimg.com/upload/vod/20240219-1/bda4792b70991b5d96137ed1c8adf148.jpg', 'https://phimimg.com/upload/vod/20240219-1/6511fe9a3083b74ce03c4ac325531326.jpg', '<p>Phim Kẻ Diệt Quỷ: Trong khi điều tra sự thật đằng sau cái chết của cha mẹ mình, Corbin (Dean S. Jagger) phát hiện ra anh là hậu duệ cuối cùng còn sống thuộc gia tộc Nash, một dòng tộc chuyên săn quỷ. Sự thật được phát hiện cũng là lúc anh bị giết để trừ khử. Corbin được hồi sinh bởi Macy (Fernanda Romero), một linh hồn thuần khiết và một nhà tiên tri mù bí ẩn (Malcolm McDowell). Sự thèm khát trả thù và cơn giận dữ đã biến anh thành một thợ săn quỷ thực thụ...</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Corey Feldman","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Rutger Hauer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324392);
