INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-yeu-quy', 'Con Trai Yêu Quý', 'Beautiful Boy', 'https://phimimg.com/upload/vod/20240219-1/b688ff1ba75eec1979fce53a6a3aa09d.jpg', 'https://phimimg.com/upload/vod/20240219-1/f32f4b0884c62eed2accccbc19042bd9.jpg', '<p>Con Trai Yêu Quý - Beautiful Boy dựa trên cuốn hồi ký Beautiful Boy: A Fathers Journey Through His Sons Addiction (Con Trai Yêu Quý: Hành Trình Của Một Người Cha Đưa Con Khỏi Cơn Nghiện) kể về Nic Sheff (Timothée Chalamet), cậu thanh niên trẻ lỡ sa chân vào con đường nghiện ngập. Sự mặc cảm, tự ti ngày một đẩy cậu đi xa khỏi tình yêu thương từ người cha tội nghiệp David (Steve Carell). Dù cho Nic có chối bỏ cha thế nào, David vẫn kiên nhẫn ở bên và yêu con trai mình với tất cả tình thương ông có. Một bên là người con lảng tránh thực tại, bị dằn vặt bởi ma túy và tội lỗi đối với cha mẹ. Một bên là người cha yêu thương con vô điều kiện, dù ông không hiểu hết được con trai mình.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Timothee Chalamet","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
