INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-rac-roi', 'Bộ Đôi Rắc Rối', 'Double Trouble', 'https://phimimg.com/upload/vod/20240126-1/d2eb4fe60ae06f88ab6a14f7c59cd25c.jpg', 'https://phimimg.com/upload/vod/20240126-1/468ce6634971a7e3a55a2a25943c72f8.jpg', '<p>Bộ Đôi Rắc Rối - Double Trouble: Bộ phim theo chân hai cảnh sát Mert Barca (Barca) và Mustafa Kerim Can (MKC) để giải quyết những vụ án hóc búa mang tầm cỡ quốc gia và quốc tê. Barca - anh trung úy liều lĩnh, bất chấp nguy hiểm, trái lệnh cấp trên để thực hiện vụ án mà anh cho rằng kẻ đứng sau đã gây ra cái chết của vợ mình. Còn MKC - anh trung úy ưa thích vẻ bề ngoài, làm việc rất nguyên tắc và lý trí, luôn là nỗi khiếp sợ của bọn tội phạm nhưng anh lại có 1 gia đình không trọn vẹn. Điều gì sẽ làm cho hai con người trái ngược nhau về tính cách, hoàn cảnh hợp tác thành công được.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 19, 2018, 'Lồng Tiếng', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Engin Şenkan","avatar":""},{"name":"Eren Hacısalihoğlu","avatar":""},{"name":"İbrahim Çelikkol","avatar":""},{"name":"Kerem Bursin","avatar":""},{"name":"Öykü Karayel","avatar":""},{"name":"Özge Gürel","avatar":""},{"name":"Zafer Algöz","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
