INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('selfie-voi-than-chet', 'Selfie Với Thần Chết', 'Selfie From Hell', 'https://phimimg.com/upload/vod/20240205-1/7235d72c528c131ca106597cec360084.jpg', 'https://phimimg.com/upload/vod/20240205-1/228d47af718fd397980a6562e806b803.jpg', '<p>Nội dung phim SELFIE VỚI THẦN CHẾT kể về Julia – một vlogger nổi tiếng, cô thường xuyên selfie tự sướng và đăng tải các bức ảnh qua mạng xã hội để nhận được nhiều sự quan tâm.Thế nhưng trong một lần selfie, Julia đã mắc phải một sai lầm nghiêm trọng và tính mạng cô bị đe dọa bởi thế lực đen tối. Đứng trước sự việc đó, Hana – chị gái của Julia phải tìm cách xâm nhập vào thế giới bí ẩn này để giải cứu cho em mình.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Alyson Walker","avatar":""},{"name":"Tony Giroux","avatar":""},{"name":"Meelah Adams","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324392);
