INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-hoc-va-cam-tinh', 'Khoa Học Và Cảm Tính', 'Nuts - Science And Sensibility', 'https://phimimg.com/upload/vod/20240207-1/42d7e6953a39ca0461612a9f8986f3a7.jpg', 'https://phimimg.com/upload/vod/20240207-1/116a3c0a8c0b453c11f6f715bd1af6f5.jpg', '<p>Nam sinh thiên tài vật lý Hoàng Kiếm (Trương Nhược Quân) và phú nhị đại học lực phẩm chất toàn vẹn Hứa Tử Thông (Lý Hiện) vì cùng tranh nhau một xuất học dưới sự hướng dẫn của giáo sư vật lý nổi tiếng ở Viện công nghệ Massachusetts (MIT), Mỹ mà đấu đá trên nhiều phương diện. Hoàng Kiếm vì thiếu kinh nghiệm trong các hoạt động đoàn thể theo như yêu cầu của MIT nên phải tham gia Hội Thục Viên (toàn các nữ sinh); ở đây anh gặp phải Chu Châu ( Mã Tư Thuần) một phóng viên muốn moi móc các chuyện bí mật ở trường học nên đã trà trộn vào trường.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"Mã Tư Thuần","avatar":""},{"name":"Trương Nhược Quân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324392);
