INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-duong-hiep-khuc', 'Càn Dương Hiệp Khúc', 'An Amorous Swordsman', 'null', 'https://phimimg.com/upload/vod/20240205-1/0d3d9812cfd6e9e52e3fca7e11f9a2ca.jpg', '<p>Càn Dương Hiệp Khúc - An Amorous Swordsman kể về thời đại võ lâm hưng thịnh, Kiều Tấn Phong là đồ đệ của trang chủ đời thứ năm của Càn Dương sơn trang, vì trang chủ không truyền dạy võ học Ẩn Kiếm Thức cho Kiều Tấn Phong nên hắn bày kế hại sư đệ Thẩm Vũ Sơn. Tô Năng vì trả thù cho sư phụ mà lên kế hoạch để trở thành thân cận của Kiều Tấn Phong, anh đã dẫn Kiều Tấn Phong gặp Thẩm Thu Bạch để lấy lòng tin của hắn. Bản gốc đao pháp đã được tiêu hủy vì tránh rơi vào tay kẻ xấu, Thẩm Vũ Sơn chuyển đao pháp thành cẩm phổ. Dần dần chiếm được lòng tin của Kiều Tấn Phong , Tô Năng sắp xếp sư đệ ở ngoài âm thầm luyện đao pháp chờ ngày đánh bại Lão tặc này.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yan","avatar":""},{"name":"Cui Youbin","avatar":""},{"name":"Lu Xiaoran","avatar":""},{"name":"Yang Xiaobo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
