INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('springsteen-tren-san-khau', 'Springsteen Trên Sân Khấu', 'Springsteen On Broadway', 'https://phimimg.com/upload/vod/20240128-1/ad5c38771363d360598cf63205ceb665.jpg', 'https://phimimg.com/upload/vod/20240128-1/91e5ef48b294637bda3f06a29528341f.jpg', '<p>Springsteen trên sân khấu Broadway là một buổi biểu diễn acoustic độc tấu được viết và biểu diễn bởi Giải Tony, Giải Oscar và người 20 lần đoạt giải Grammy Bruce Springsteen. Dựa trên cuốn tự truyện bán chạy nhất toàn cầu Sinh ra để chạy, Springsteen trên sân khấu Broadway là một buổi tối độc đáo với Bruce, cây đàn guitar, cây đàn piano và những câu chuyện rất riêng tư của anh ấy. Ngoài ra, nó còn có sự xuất hiện đặc biệt của Patti Scialfa. Netflix sẽ cho phép khán giả toàn cầu xem các bộ phim mà các nhà phê bình đang phát cuồng từ bất cứ đâu.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Springsteen","avatar":""},{"name":"Patti Scialfa","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324393);
