INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-than-ky', 'Chiến Thần Ký', 'Genghis Khan', 'https://phimimg.com/upload/vod/20240128-1/7bd954fd41ad70396d17b72e3f1a9f42.jpg', 'https://phimimg.com/upload/vod/20240128-1/8a2aa319357d12259dd9b9192cba2d66.jpg', '<p>Là con trai của thủ lĩnh bộ tộc, Thiết Mộc Chân có hôn ước và tình yêu với Bội Nhĩ Thiếp, nhưng cha chàng chết trận, bộ tộc loạn lạc, đôi trẻ phải chia xa. Khi Thiết Mộc Chân tìm đến hỏi cưới Bội Nhĩ Thiếp cũng là lúc âm mưu bá chiếm tam giới của Ma Vương rục rịch trỗi dậy, buộc chàng phải đối đầu với thế lực tàn ác khổng lồ.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Quân","avatar":""},{"name":"Lâm Duẫn","avatar":""},{"name":"Trần Vỹ Đình","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
