INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-nang-xanh', 'Cẩm Nang Xanh', 'Green Book', 'https://phimimg.com/upload/vod/20240128-1/e2bad756fb907eb22d1014c52de2fc72.jpg', 'https://phimimg.com/upload/vod/20240128-1/bd3f14a1b8d1554076fe150e7dc53194.jpg', '<p>Green Book lấy bối cảnh tại vùng Thâm Nam Hoa Kỳ vào thập niên 1960, cốt truyện phim xoay quanh một nghệ sĩ piano nhạc jazz và nhạc cổ điển người Mỹ gốc Phi Don Shirley (Mahershala Ali) và Tony Vallelonga (Viggo Mortensen), một vệ sĩ gác cửa giữ vai trò vệ sĩ và tài xế của Shirley.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Viggo Mortensen","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Dimiter D. Marinov","avatar":""},{"name":"Mike Hatton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
