INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-vong-tuoi-tre-2018', 'Khát Vọng Tuổi Trẻ', 'Teen Spirit', 'https://phimimg.com/upload/vod/20240128-1/923a7dfb4e0875b8c286ecd46dd0a957.jpg', 'https://phimimg.com/upload/vod/20240128-1/585d487fde459377491e3fafe75f1f89.jpg', '<p>Violet là một thiếu nữ nhút nhát, mơ ước thoát khỏi thị trấn nhỏ của mình và theo đuổi đam mê ca hát. Với sự giúp đỡ của một người cố vấn không ngờ, cô tham gia một cuộc thi hát địa phương. Nó sẽ kiểm tra sự chính trực, tài năng và tham vọng của cô. Mang âm hưởng âm nhạc pop, Teen Spirit là bộ phim đầy nội tâm và lịch lãm về câu chuyện Cô bé Lọ Lem.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elle Fanning","avatar":""},{"name":"Millie Brady","avatar":""},{"name":"Rebecca Hall","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
