INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-va-chang-mai', 'Công Chúa Và Chàng Mai', 'The Princess And The Matchmaker', 'https://phimimg.com/upload/vod/20240127-1/eeab6cf689456d4b5b61db46504c0bd0.jpg', 'https://phimimg.com/upload/vod/20240127-1/b668583d787f528a30a7c69808040f10.jpg', '<p>The princess and the matchmaker xoay quanh chuyện tuyển phò mã cho một cô công chúa bướng bỉnh Songhwa (Shim Eun Kyung) thời Joseon. Nàng Ông chúa Songhwa (Shim Eun-kyung) không chấp nhận số phận của mình phải kết hôn với người được định đoạt sẵn. Có bốn nam nhân được cho là nhân tuyển phù hợp với địa vị của cô. Từ chối việc số phận bị sắp đặt, cô trốn khỏi cung điện để tìm kiếm người đàn ông mà mình thực sự yêu. 3 chàng trai tài trí nhất Joseon (Kang Min Hyuk, Yeon Woo Jin, Choi Woo Shik) là ứng cử viên làm chồng công chúa. Không chấp nhận sự sắp đặt của số mệnh, cô công chúa lẻn ra khỏi cung để tự chọn phò mã tương lai của mình. Trong phim Lee Seung Gi vào vai Seo Do Yoon, một thầy tướng số chuyên bói quẻ tình duyên nổi tiếng nhất thời Joseon.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shim Eun-kyung","avatar":""},{"name":"Lee Seung-gi","avatar":""},{"name":"Kim Sang-kyung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324393);
