INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-than-2018', 'Ẩn Thân', 'Leave No Trace', 'https://phimimg.com/upload/vod/20240127-1/3909eed11220c548d84ddfb5683c723a.jpg', 'https://phimimg.com/upload/vod/20240127-1/b86dac5babb62b4df03a4a33a5e4c38b.jpg', '<p>Một người cha và cô con gái mười ba tuổi đang sống một sự tồn tại lý tưởng trong một công viên đô thị rộng lớn ở Portland, Oregon khi một sai lầm nhỏ đã làm hỏng cuộc sống của họ mãi mãi.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
