INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-lach-giang-sinh', 'Trở Lại Lạch Giáng Sinh', 'Return To Christmas Creek', 'https://phimimg.com/upload/vod/20240126-1/35f23335f3eb9ddc2155074fa3796794.jpg', 'https://phimimg.com/upload/vod/20240126-1/04f20f82933341ef848609ef84c1ae6a.jpg', '<p>Khi một nhà phát triển ứng dụng ở Chicago trở về quê nhà để tìm cảm hứng cũng như kết nối lại với gia đình, cô tìm thấy tình yêu ở nơi không ngờ tới nhất.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tori Anderson","avatar":""},{"name":"Stephen Huszar","avatar":""},{"name":"Steven Weber","avatar":""},{"name":"Kari Matchett","avatar":""},{"name":"Janet Porter","avatar":""},{"name":"Lyla Elliott","avatar":""},{"name":"Byron Abalos","avatar":""},{"name":"Stuart Hughes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324393);
