INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-7-nam', 'Đêm 7 Năm', 'Seven Years Of Night', 'https://phimimg.com/upload/vod/20240126-1/4ac408f0be549c0bc237eff6c9c7fdb5.jpg', 'https://phimimg.com/upload/vod/20240126-1/a8dbbfbec55e2c26ebc403201aed9089.jpg', '<p>Seven Years of Night dựa trên cuốn tiểu thuyết bán chạy nhất của tác giả Jung Yoo Jung. Câu chuyện xoay quanh một người cha có kế hoạch trả thù kẻ vô tình giết chết đứa con gái mà ông hết mực thương yêu. Bảy năm sau sự việc mất con đau lòng, người cha mù quáng quyết định ra tay đòi lại công đạo, nhưng không phải với kẻ thủ ác, mà là một người khác. Trong khi đó, con trai của kẻ sát nhân cũng bàng hoàng phát hiện ra sự thật đau lòng rằng cha mình từng phạm tội nghiêm trọng và phải chịu án hành quyết. Dù sự thật đã được phơi bày song tính mạng của cậu lúc này lại không được đảm bảo nữa. Có phải cậu sẽ là người thay cha trả cho hết món nợ máu bảy năm về trước?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Jang Dong-gun","avatar":""},{"name":"Song Sae-byuk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
