INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alpha-nguoi-thu-linh', 'Alpha: Người Thủ Lĩnh', 'Alpha', 'https://phimimg.com/upload/vod/20240126-1/cbdd41bab1172f0ce6a6763dfb80a709.jpg', 'https://phimimg.com/upload/vod/20240126-1/fa4dd40e054fecba3008683ab009b78d.jpg', '<p>Một cuộc phiêu lưu sử thi được thiết lập trong kỷ băng hà cuối cùng, Alpha là một câu chuyện hấp dẫn, trực quan tỏa sáng một ánh sáng trên nguồn gốc của người bạn thân nhất của con người. Khi đang săn lùng đầu tiên với nhóm ưu tú nhất của bộ lạc, một chàng trai trẻ bị thương và phải học cách sống sót một mình trong vùng hoang dã. Sau khi chàng trai trẻ dồn dập một con sói đơn độc bị bỏ rơi bởi gói của nó, cặp đôi này học cách dựa vào nhau và trở thành những đồng minh không có khả năng, chịu đựng vô số nguy hiểm và tỷ lệ cược áp đảo để tìm đường về nhà trước khi mùa đông đến.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
