INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nguoi-deu-biet', 'Mọi Người Đều Biết', 'Everybody Knows', 'https://phimimg.com/upload/vod/20240123-1/d918ec827b84e122da55824db5cd8e38.jpg', 'https://phimimg.com/upload/vod/20240123-1/496597260118f7509adc844b119d7a30.jpg', '<p>Mọi Người Đều Biết - Everybody Knows (2018):Laura (Penélope Cruz) sống cùng chồng là Alejandro (Ricardo Darín) ở Argentina. Nhân dịp đám cưới em gái, cô đưa hai con về ngôi làng quê hương ở Tây Ban Nha. Laura gặp lại người tình cũ là Paco (Javier Bardem) – hiện là chủ một vườn nho. Trong đám cưới, Laura phát hiện ra cô con gái 16 tuổi của mình đã mất tích. Một tin nhắn gửi đến thông báo cô bé bị bắt cóc và đòi gia đình trả tiền chuộc. Chồng của Laura từ Nam Mỹ bay sang để giải quyết tình hình.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Penélope Cruz","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Ricardo Darín","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
