INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-chan-dau-tien', 'Bước Chân Đầu Tiên', 'First Man', 'https://phimimg.com/upload/vod/20240123-1/1c9d420bc02cf1986e4ae42bd782c873.jpg', 'https://phimimg.com/upload/vod/20240123-1/1219c4bfbb9cf8d8c5ccaebfd32e64cd.jpg', '<p>Bước Chân Đầu Tiên tái hiện lại hành trình lịch sử đưa con người tiếp cận mặt trăng của NASA, xoay quanh cuộc đời của phi hành gia huyền thoại Neil Amstrong trong giai đoạn 1961-1969 cũng như những hy sinh và mất mát – đối với riêng bản thân ông và cả nước Mỹ nói chung – trong quá trình thực hiện một trong những nhiệm vụ nguy hiểm nhất trong lịch sử nhân loại.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Claire Foy","avatar":""},{"name":"Jason Clarke","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324393);
