INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-nay-muon-gap-em', 'Khoảnh Khắc Này, Muốn Gặp Em', 'In My Heart', 'https://phimimg.com/upload/vod/20240123-1/41509e5037af145828d4dad88f2dbf92.jpg', 'https://phimimg.com/upload/vod/20240123-1/13101a413e89586223cbfba5ebb7d038.jpg', '<p>Hai anh em A Lạc (Đồ Thiệu Tồn thủ vai) và A Nguyên (Nguyên Đằng thủ vai) là những con người rất yêu âm nhạc. Một đêm nọ, vì để có thể chơi thử một cây đàn piano đắt tiền hai anh em đã mạo hiểm đột nhập vào giảng đường của trường học. Nhưng không ngờ trong lúc tránh bảo vệ tuần tra, hai anh em đã gặp phải một đám lưu manh. Sau khi xảy ra xô xát, A Nguyên đã lâm vào hôn mê. A Lạc trở nên suy sụp và tự trách bản thân, nhưng vì giấc mơ âm nhạc của hai anh em mà A Lạc vẫn cố gắng thực hiện nó. Nhưng cuộc đời của A Lạc đã bước sang trang mới khi gặp được Monster (Tuấn Thiến thủ vai). Câu chuyện của họ sẽ đi về đâu</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Thuyết Minh', 'HD', 'Malaysia', 0, '[{"name":"Charles Tu","avatar":""},{"name":"Zen","avatar":""},{"name":"Teng Yuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
