INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-vo-danh', 'Đứa Trẻ Vô Danh', 'Children Of Nobody', 'https://phimimg.com/upload/vod/20240118-1/4dee441fe043e48cb1e81cb548b3b5ae.jpg', 'https://phimimg.com/upload/vod/20240118-1/f3b02bda4dd8513eb96b597ddcab475a.jpg', '<p>Phim Đứa Trẻ Vô Danh - Children Of Nobody 2018: Cha Woo Kyung là một chuyên gia tâm lý tại một trung tâm giành cho trẻ em. Cô ấy có một cuộc sống hoàn hảo với một công việc yêu thích, một người chồng giỏi giang, dịu dàng và cô ấy đang mang thai đứa con thứ hai. Một tai nạn đã làm thay đổi cuộc sống của Cha Woo Kyung. Cô ấy phải đối mặt với rất nhiều sự việc kì lạ và phải tìm ra sự thật. Trong khi đó, Kang Ji Hun là một điều tra viên. Anh ấy có niềm tin vững chắc rằng tội phạm phởi được trừng trị thích đáng trong khi bản thân đang phải chôn vùi nỗi đau trong quá khứ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sun Ah","avatar":""},{"name":"Lee Yi Kyung","avatar":""},{"name":"Nam Gyu Ri","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
