INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-ma-quai-2018', 'Vùng Đất Ma Quái', 'Ghostland', 'https://phimimg.com/upload/vod/20240124-1/977ad6bf3d5f0be0b6a4c115a55c0dea.jpg', 'https://phimimg.com/upload/vod/20240124-1/b35cf75f1485240a77dab0270ded729e.jpg', '<p>Pauline cùng hai cô con gái Beth và Vera được thừa kế ngôi nhà cũ của người dì xấu số. Nhưng trong đêm đầu tiên dọn đến ở, một kẻ giết người lạ mặt xông vào nhà và Pauline đã phải chiến đấu để cứu con mình. Thời gian trôi đi, trong khi Beth lập gia đình và trở thành một tác giả văn học nổi tiếng chuyên thể loại kinh dị thì Vera lại bị sa lầy trong sự hoang tưởng phá hoại trong chính ngôi nhà cũ. Mười sáu năm sau, Vera đã phải cầu cứu Beth tuy nhiên khi Beth trở lại ngôi nhà cũ cũng là lúc những sự kiện ma quái lại bắt đầu xảy ra ...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Crystal Reed","avatar":""},{"name":"Mylène Farmer","avatar":""},{"name":"Anastasia Phillips","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
