INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-sinh-boi-loi', 'Tiên Sinh Bơi Lội', 'Mr Swimmer', 'https://phimimg.com/upload/vod/20240116-1/3cccde6f691991870c090ba93935be02.jpg', 'https://phimimg.com/upload/vod/20240116-1/9d7c7cb07b682de94d55d7ea7bab91cc.jpg', '<p>Thiên tài bơi lội Bạch Vịnh Trạch lớn lên trong một gia đình bình thường, cùng với Tống Trà Trà là tiểu thư có gia cảnh sa sút trở thành 1 đôi oan gia. Lam Thiên là bạn thân của Bạch Vịnh Trạch bởi vì một bí mật mà phải chia tay vị hôn thê của mình là Tống Trà Trà. Chính vì thế, trong sự nghiệp, tình yêu, đối mặt với tình cảm, Bạch Vịnh Trạch và Lam Thiên từ bạn bè thân thiết trở thành đối thủ cạnh tranh</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 13, 2018, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Cúc Tịnh Y","avatar":""},{"name":"Hoàng Hinh Dao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
