INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-luc-sieu-pham', 'Trí Lực Siêu Phàm', 'The Darkest Minds', 'https://phimimg.com/upload/vod/20240121-1/53ab5f1666e9df8e44205b64dab77fd1.jpg', 'https://phimimg.com/upload/vod/20240121-1/7b2725a9b54a5df072ef1a4d3330328b.jpg', '<p>Bộ phim sẽ theo chân cô bé Ruby 16 tuổi, người sở hữu siêu năng lực mạnh nhất giữa những người bạn có khả năng “bất thường” như mình, gồm Liam, Chubs, và Suzume. Thế giới của Ruby đầy khắc nghiệt khi 98% trẻ em tử vong vì bệnh lạ. 2% còn lại sở hữu siêu năng lực mà ngay chính họ cũng không thể kiểm soát. Các cô cậu bé phát hiện một số điều bí ẩn, và khi Ruby cùng bạn bè nhận ra rằng, chạy trốn không phải là cách giải quyết vấn đề, họ cùng nhau đối mặt và chống lại những người lớn đã phản bội mình.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amandla Stenberg","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Patrick Gibson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
