INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-ma-troi-day', 'Thây Ma Trỗi Dậy', 'Attack Of The Southern Fried Zombies', 'null', 'https://phimimg.com/upload/vod/20240207-1/0852f5ec57fb61571c8bc3b64f1aac5a.jpg', '<p>Một loại thuốc được thử nghiệm nhằm kiểm soát dịch bệnh đã trở thành thảm họa giết chết nhiều người và khiến họ trở thành xác sống. Anh phi công trẻ gặp nạn, bất đắc dĩ trở thành thủ lĩnh dẫn dắt nhóm người hiếm hoi còn sống sót trong thị trấn đang bị thây ma chiếm đóng, lao vào chiến đấu trước khi bọn chúng bá chủ thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothy Haug","avatar":""},{"name":"Wyntergrace Williams","avatar":""},{"name":"Escalante Lundy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
