INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-tho-cua-tinh-dau', 'Tập Thơ Của Tình Đầu', 'Anthology', 'https://phimimg.com/upload/vod/20240207-1/38d8f41e4bcff597cb7b88d9471c5425.jpg', 'https://phimimg.com/upload/vod/20240207-1/c1fbd76583a499c9c4b8e83965266dea.jpg', '<p>Một bệnh dịch lạ bùng phát và chỉ duy nhất thuốc đặc trị của công ty AMANAH là có thể chữa khỏi. Mọi nghi vấn quanh loại thần dược này bắt đầu được dấy lên khi hàng loạt sự việc kỳ lạ bị phanh phui. Nhầm làm sáng tỏ mọi chuyện, một nhóm những con người gan dạ đã dán thân vào cuộc chiến chóng lại những kẻ đứng sau vụ này.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"One","avatar":""},{"name":"Shin Eun Soo","avatar":""},{"name":"Noh Susanna","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
