INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-trong-bay', 'Bẫy Trong Bẫy', 'Mystery Of Antiques', 'https://phimimg.com/upload/vod/20240116-1/b14b62ff09b8544732e8191420e35ceb.jpg', 'https://phimimg.com/upload/vod/20240116-1/fb99fb960a2dc00e353b555b547c7793.jpg', '<p>Phim Bẫy Trong Bẫy - Mystery of Antiques 2018: Một vị khách ghé vào tiệm đồ cổ của Hứa Nguyện, lôi cô vào trong một âm mưu nằm mơ cũng không ngờ tới, một món bảo vật hiếm có trong tiệm bỗng dưng có hàng vạn liên hệ với mình, một thế cục mấy chục năm trước lại ứng vào số mệnh của mình. Hứa Nguyện đặt mình vào sinh tử, đấu trí đấu dũng với các phe thần thánh mấy chục năm trước.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hạ Vũ","avatar":""},{"name":"Thái Văn Tịnh","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
