INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-quy-troc-yeu-ky', 'Chung Quỳ Tróc Yêu Ký', 'Demon Catcher Zhong Kui', 'https://phimimg.com/upload/vod/20240116-1/050d319226828bff21bee00ede987ed4.jpg', 'https://phimimg.com/upload/vod/20240116-1/ca5e8a7c0d6912cc2fc39791db952de5.jpg', '<p>Phim Chung Quỳ Tróc Yêu Ký - Demon Catcher Zhong Kui 2018: Trên trời Thần Chung Quỳ là một vị thần cai quản việc phục ma, áp chế yêu quái tác quái trên nhân gian. Trong một lần nóng giận Thần Chung Quỳ đã mạo phạm thiên đình nên đã bị giáng làm dân thường và mất đi toàn bộ ký ức. Và hiện tại anh tên là Mục Thiên Nhiên, với mong muốn tìm là thân thế thật sự của mình anh đã gặp gỡ và kết giao với Lăng Hề (Dương Dung) cùng Dương Nhân Chấp (Lý Tử Phong). Họ nhận diệt yêu trừ ma giúp đỡ người khác, bắt đầu một cuộc hành trình đầy thử thách.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 18, 2018, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Dung","avatar":""},{"name":"Dương Húc Văn","avatar":""},{"name":"Lý Tử Phong","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324393);
