INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-loi', 'Tội Lỗi', 'The Guilty', 'https://phimimg.com/upload/vod/20240118-1/3b3d4165af7f777453f9a04b0bc4d8b8.jpg', 'https://phimimg.com/upload/vod/20240118-1/60c6aba864478f58ecb3190a9e52d4be.jpg', '<p>Asger Holm là viên cảnh sát trực điện thoại. Hôm ấy anh nhận cuộc gọi khẩn cấp về một người phụ nữ bị bắt có. Khi cuộc gọi đột ngột ngắt kết nối, cuộc tìm kiếm người phụ nữ và kẻ bắt cóc cô bắt đầu. Chỉ duy nhất chiếc điện thoại là công cụ điều tra của mình, Asger Holm bước vào cuộc đua với thời gian để giải cứu người phụ nữ bí ẩn đó. Nhưng có một tội ác lớn hơn rất nhiều so với những gì anh ta nghĩ ban đầu.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Thuyết Minh', 'HD', 'Đan Mạch', 0, '[{"name":"Jakob Cedergren","avatar":""},{"name":"Jessica Dinnage","avatar":""},{"name":"Omar Shargawi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
