INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giac-thuc-tai', 'Ảo Giác Thực Tại', 'Deja Vu', 'https://phimimg.com/upload/vod/20240111-1/a86576ab2b62b019d84b7e743e1c3666.jpg', 'https://phimimg.com/upload/vod/20240111-1/d2e7eab3612ab7a9205f0ce0c81ce566.jpg', '<p>Khi Ji-Min (Nam Gyu-Ri) đang ở trong xe với vị hôn phu Woo-Jin (Lee Gyu-Han) lái xe, Woo-Jin tông phải một người phụ nữ. Người phụ nữ chết vì tai nạn và họ rời khỏi hiện trường vụ tai nạn. Kể từ đó, Ji-Min bị ám ảnh bởi những linh kiến của người phụ nữ đã chết xuất hiện trước mặt cô. Ji-Min đến đồn cảnh sát để báo cáo tai nạn xe hơi và nói chuyện với thám tử In-Tae (Lee Chun-Hee) về tai nạn xe hơi. Anh ta thông báo với cô ấy rằng không có bất kỳ tai nạn chết người nào được báo cáo. Với những câu hỏi chưa được trả lời, Ji-Min càng thêm kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Nam Gyu-ri","avatar":""},{"name":"Lee Chun-hee","avatar":""},{"name":"Lee Kyu-han","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
