INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('charming-hoang-tu-hao-hoa', 'Charming: Hoàng Tử Hào Hoa', 'Charming', 'https://phimimg.com/upload/vod/20240111-1/ce330234612bc21ec89d412c87b6dc6e.jpg', 'https://phimimg.com/upload/vod/20240111-1/46d8ecac60493f96735e6b0ff35938fd.jpg', '<p>Hoàng Tử Hào Hoa là bộ phim hoạt hình ngoại truyện hài hước lấy cảm hứng từ những câu chuyện cổ tích quen thuộc. Hàng loạt tình huống “dở khóc dở cười” xảy đến khi hoàng tử Charming trở thành “nam thần” của tất cả các cô gái trong vương quốc bao gồm cả Bạch Tuyết, Lọ Lem và Công Chúa Ngủ Trong Rừng. Chàng sẽ làm đốn tim tất cả các cô gái chỉ bằng một một nụ cười “chết người” khiến mọi trái tim đều gục ngã, Ít ai biết được đó là lời nguyền từ mụ phù thủy dành cho chàng từ bé. Trước khi sinh nhật lần thứ 21, chàng phải thực hiện sứ mệnh đi tìm sự hóa giải cho lời nguyền khắc nghiệt kia được kết thúc hoặc sẽ không bao giờ có được tình yêu đích thực của riêng mình và sống cô đơn đến suốt cuộc đời còn lại.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Tisdale","avatar":""},{"name":"Demi Lovato","avatar":""},{"name":"Avril Lavigne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324393);
