INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-xinh-dep', 'Ma Cà Rồng Xinh Đẹp', 'Beautiful Vampire', 'https://phimimg.com/upload/vod/20240109-1/5f89f36180560f8f6646d183449439a1.jpg', 'https://phimimg.com/upload/vod/20240109-1/86e418656cdd9fc73faa6f734d6346f9.jpg', '<p>Ma cà rồng 500 tuổi xinh đẹp sống một cuộc đời lặng lẽ điều hành một phòng thay đồ trong một con hẻm hẻo lánh. Đã có một cuộc khủng hoảng gây tử vong cho cô ấy. Mùi của chàng trai thích cô liên tục kích thích bản năng ma cà rồng của cô đã bị kìm nén trong một thời gian.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD 720p', 'Hàn Quốc', 0, '[{"name":"Jung Yeon-Joo","avatar":""},{"name":"Song Kang","avatar":""},{"name":"Park Jun-Myun","avatar":""},{"name":"Lee Yong-Nyeo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
