INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-pha-chau-au', 'Công Phá Châu Âu', 'Europe Raiders', 'https://phimimg.com/upload/vod/20240104-1/0c207ca68dd80d6a5f33c40f70c34fdf.jpg', 'https://phimimg.com/upload/vod/20240104-1/212c74359082d42e0286526431a02617.jpg', '<p>Công Phá Âu Châu là một câu chuyện về Lâm Tại Phong (Lương Triều Vỹ) - một trong những điệp viên hàng đầu thế giới. Anh cùng các trợ thủ như Vương Đình Anh (Đường Yên), hacker Lạc Kỳ (Ngô Diệc Phàm) truy tìm công nghệ “bàn tay của Chúa” bị đánh cắp tại Châu Âu. Trong quá trình săn tìm, họ đã nhận phải sự truy lùng của các băng đản Châu Âu, CIA Mỹ và Liên minh chống tội phạm Châu Âu. Hành trình của nhóm vì thế mà trở nên gian nan, đầy khắc nghiệt hơn rất nhiều.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lương Triều Vỹ","avatar":""},{"name":"Ngô Diệc Phàm","avatar":""},{"name":"Đường Yên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
