INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-padmaavat', 'Hoàng Hậu Padmaavat', 'Padmaavat', 'https://phimimg.com/upload/vod/20240104-1/1963c98b6e0ffdfd57abcc186a95890d.jpg', 'https://phimimg.com/upload/vod/20240104-1/ee48c8382f8f9942461dcbff7324b20f.jpg', '<p>Padmavati là bộ phim sử thi kể về Padmavati, vị Hoàng hậu huyền thoại của nhà nước Hindu Rajput với lòng dũng cảm và trí thông minh tuyệt đỉnh của người... Lấy bối cảnh thời trung cổ Rajasthan, công chúa Padmavati (Deepika Pakudone xinh đẹp thủ vai) kết hôn với Ratan Singh (Shahid Kapoor thủ vai), vị vua dũng cảm của xứ Mewar. Cuộc sống của họ diễn ra hạnh phúc dưới thành Chittor. Cho đến ngày, vẻ đẹp thần thánh và sự thông minh hiếm có của Hoàng hậu Padmavati được truyền đến tai Alauddin (Ranveer Singh thủ vai) - một Sultan (danh hiệu để chỉ Vua của các nước Hồi giáo) đầy tham vọng. Được mách rằng chiếm được Hoàng hậu Padmavati sẽ giúp hắn chinh phục cả thế giới nên Alauddind đã không ngần ngại dấy binh tấn công Mewar... Phim được chọn để chiếu tại Liên hoan phim Quốc tế Thượng Hải lần thứ 21 diễn ra vào ngày 25/06/2018 tới đây.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Deepika Padukone","avatar":""},{"name":"Ranveer Singh","avatar":""},{"name":"Shahid Kapoor","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324393);
