INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-nguoi-scythian', 'Sự Trỗi Dậy Của Người Scythian', 'The Scythian', 'https://phimimg.com/upload/vod/20240104-1/7b1c3e7f0545ab1036fcdf212a4f998e.jpg', 'https://phimimg.com/upload/vod/20240104-1/ed725358dd1ee1d5742650562ee39c41.jpg', '<p>Người Scythia, từng là những chiến binh kiêu hãnh, đã biến mất. Một số ít hậu duệ của họ đã trở thành những sát thủ đánh thuê tàn nhẫn, “Những con sói của Ares.” Lutobor, là một người lính với một nhiệm vụ khó khăn trong tầm tay. Anh ta tham gia vào các cuộc xung đột giữa các giai thoại và bắt đầu một cuộc hành trình nguy hiểm để cứu gia đình của mình. Người dẫn đường cho anh ta là một người Scythia bị giam giữ tên là Marten. Lutobor và Marten là kẻ thù của nhau. Họ cầu nguyện với các vị thần khác nhau nhưng phải cùng nhau bắt đầu cuộc hành trình này. Họ can đảm trên thảo nguyên hoang dã, tiến về nơi trú ẩn cuối cùng của người Scythia, đến nơi dường như là cái chết không thể tránh khỏi của họ.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Aleksey Faddeev","avatar":""},{"name":"Vitaly Kravchenko","avatar":""},{"name":"Aleksandr Kuznetsov","avatar":""},{"name":"Vasilisa Izmaylova","avatar":""},{"name":"Alexander Patsevich","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
