INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-dong-dat', 'Thảm Họa Động Đất', 'The Quake', 'https://phimimg.com/upload/vod/20240104-1/40446c4d56a1d7b119a7d990b9e0815b.jpg', 'https://phimimg.com/upload/vod/20240104-1/91a9cb861ee64f710773caa543bc4c0d.jpg', '<p>Ba năm sau khi cứu sống thị trấn của mình trong cơn sóng thần kinh hoàng, Kristian Eikjord được tôn vinh là anh hùng nhưng lại ly hôn và giờ đang sống một mình. Và rồi mọi thứ bỗng thay đổi khi anh phát hiện một thảm họa mới sắp diễn ra ở thủ đô Oslo, nơi vợ và các con anh sinh sống.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Kristoffer Joner","avatar":""},{"name":"Ane Dahl Torp","avatar":""},{"name":"Edith Haagenrud-Sande","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324393);
