INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-chung-toi', 'Chuyện Tình Chúng Tôi', 'The Hows Of Us', 'https://phimimg.com/upload/vod/20240104-1/81bf5282032a0b2b4306544fd34e5411.jpg', 'https://phimimg.com/upload/vod/20240104-1/aa8fb8897b5269b0017e4bd0000483ef.jpg', '<p>Câu chuyện về cặp đôi Primo và George, họ đã có mối quan hệ lâu dài và đang trong quá trình xây dựng tương lai cùng với nhau. Nhưng tình yêu của họ bị thử thách khi phải đối mặt với những trở ngại - từ sự hiểu lầm đến những con đường sự nghiệp khác nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD 720p', 'Âu Mỹ', 0, '[{"name":"Joross Gamboa","avatar":""},{"name":"Kathryn Bernardo","avatar":""},{"name":"Daniel Padilla","avatar":""},{"name":"Darren Espanto","avatar":""},{"name":"Jean Garcia","avatar":""},{"name":"Susan Africa","avatar":""},{"name":"Ria Atayde","avatar":""},{"name":"Kit Thompson","avatar":""},{"name":"Alwyn Uytingco","avatar":""},{"name":"Juan Miguel Severo","avatar":""},{"name":"Ketchup Eusebio","avatar":""},{"name":"Zoren Legaspi","avatar":""},{"name":"Julie Anne San Jose","avatar":""},{"name":"John Arcilla","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324393);
