INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tin-2018', 'Con Tin', 'Bel Canto', 'https://phimimg.com/upload/vod/20240111-1/74e0b4213022951adfe670741f14ac95.jpg', 'https://phimimg.com/upload/vod/20240111-1/6b5c7d56ebaeb273f2e3642396a4e234.jpg', '<p>Chuyển thể từ cuốn truyện nổi tiếng cùng tên của nhà văn Ann Patchett, Bel Canto nói về một ca sĩ soprano (Julianne Moore) đi đến một đất nước độc tài ở Nam Mỹ để hát cho một kỹ nghệ gia Nhật Bản (Ken Watanabe). Tuy nhiên, giữa buổi hòa nhạc, Roxane và những người có mặt tại party bị một nhóm phiến quân mang vũ khí bắt làm con tin để trao đổi với các tù chính trị. Điều bất ngờ là cả những kẻ bắt cóc và con tin đã xây dựng được mối quan hệ hiểu biết nhau bất chấp thực tế.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Sebastian Koch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
