INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suc-anh-huong', 'Sức Ảnh Hưởng', 'Influence', 'https://phimimg.com/upload/vod/20240104-1/b3cd329e491007fc8fee033ff9e466d9.jpg', 'https://phimimg.com/upload/vod/20240104-1/a1d601aa0161ecfb2636a94a65145cc8.jpg', '<p>Influence là câu chuyện về buổi hẹn hò đầu tiên của hai thanh thiếu niên mắc chứng tự kỷ giao tiếp chủ yếu bằng cách đánh vần trên bảng chữ cái (một hình thức hỗ trợ giao tiếp thông qua sự giúp đỡ của cha mẹ họ). Bộ phim khám phá tình yêu tuổi trẻ khi hai người trẻ đầy quyết tâm, thử thách sâu sắc đấu tranh để tìm đường đến với nhau. Bộ phim được lấy cảm hứng từ nhà văn</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kim Cristo","avatar":""},{"name":"James Kacey","avatar":""},{"name":"Rachel Zeiger-Haag","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
