INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-miseducation-of-cameron-post', 'The Miseducation Of Cameron Post', 'The Miseducation Of Cameron Post', 'https://phimimg.com/upload/vod/20240104-1/b9648237febbcec8e08a19e4c85ad2da.jpg', 'https://phimimg.com/upload/vod/20240104-1/5784b85b2fa3b5ee57343377a0a6adf5.jpg', '<p>Pennsylvania, 1993. Sau khi bị bắt với một cô gái khác, Teen Cameron Post được gửi đến một trung tâm trị liệu chuyển đổi được điều hành bởi Tiến sĩ Lydia Marsh chặt chẽ và anh trai của cô, Reverend Rick, người được điều trị bao gồm việc ăn năn vì cảm giác hấp dẫn cùng giới. &nbsp;Cameron kết bạn với những người tội nhân Jane và Adam, do đó tạo ra một gia đình mới để đối phó với sự không khoan dung xung quanh.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
