INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-va-su-nghiep-phan-1', 'Hôn Nhân Và Sự Nghiệp (Phần 1)', 'Castle And Castle (Season 1)', 'https://phimimg.com/upload/vod/20240116-1/3d133d7f5c23b13b9025a4ee823c38cd.jpg', 'https://phimimg.com/upload/vod/20240116-1/c45459ac9287008d37a0af0dec1f608d.jpg', '<p>Một cặp đôi luật sư tài giỏi và thành công bảo vệ các quyền lợi đối nghịch trong hệ thống tư pháp, gây nên căng thẳng cho cuộc hôn nhân hạnh phúc của họ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 15, 2018, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Richard Mofe-Damijo","avatar":""},{"name":"Dakore Egbuson-Akande","avatar":""},{"name":"Blossom Chukwujekwu","avatar":""},{"name":"Bimbo Manuel","avatar":""},{"name":"Jude Chukwuka","avatar":""},{"name":"Daniel Etim Effiong","avatar":""},{"name":"Anee Icha","avatar":""},{"name":"Deyemi Okanlawon","avatar":""},{"name":"Eku Edewor","avatar":""},{"name":"Dorcas Shola Fapson","avatar":""},{"name":"Ade Laoye","avatar":""},{"name":"Denola Grey","avatar":""},{"name":"Kevin Ushi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
