INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-mo-huyen-bi', 'Lăng Mộ Huyền Bí', 'The Mystery Mausoleum', 'null', 'https://phimimg.com/upload/vod/20240104-1/9fb5bec214efd64abc584ad7bb729c61.jpg', '<p>Một đoàn thám hiểu săn tìm kho báu trong hang rồng Thiên Sơn đã phát hiện một ngôi mộ cổ quái có lịch sử đến nghìn năm. Đoàn thám hiểm liên tục gặp phải những chuyện kỳ lạ. Thời khắc nhà thám hiểm trẻ mở chiếc quan tài đá cũng chính là lúc làm thức tỉnh thi thể một cô gái. Anh ta không hề biết rằng cô gái đó đã đợi anh ta hàng nghìn năm. Câu chuyện về tình yêu luân hồi nghìn năm chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Ke","avatar":""},{"name":"Trương Lam Nghệ","avatar":""},{"name":"Trương Lam Nghệ","avatar":""},{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Ren Qing An","avatar":""},{"name":"Ray","avatar":""},{"name":"Wang Lei","avatar":""},{"name":"Zhang Jing Da","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
