INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-diep-vien', 'Nữ Điệp Viên', 'Raazi', 'https://phimimg.com/upload/vod/20240103-1/bc45c06b910f6442347fdaaad8aa2fd6.jpg', 'https://phimimg.com/upload/vod/20240103-1/d6d32f5f100ab998a5dce00349e0a663.jpg', '<p>Năm 1971, căng thẳng gia tăng giữa Ấn Độ và Pakistan đang dâng lên cao trong cuộc chiến giải phóng Đông Pakistan để thành lập nên nhà nước Bangladesh độc lâp. Cục Tình báo trung ương Ấn Độ đã có một quyết định mạo hiểm khi cử một nữ tình báo viên 20 tuổi không có kinh nghiệm trong chuyên môn đến nơi nguy hiểm, nơi mà tập trung nhiều lài liệu tác chiến của Pakistan. Dưới danh nghĩa kết hôn để chiếm được tình cảm với gia đình của phía kẻ thù, Sehmat đã làm nên những điều phi thường mà không ai nghĩ một cô gái có thể làm được. Nhưng trong quá trình thực thi nhiệm vụ, cô bắt đầu nảy sinh tình cảm thật với gia đình nhà chồng, cũng như mặc cảm tội lỗi đã khiến cô gái trẻ phải day dứt...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Alia Bhatt","avatar":""},{"name":"Jaideep Ahlawat","avatar":""},{"name":"Vicky Kaushal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
