INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aquaman-de-vuong-atlantis', 'Aquaman: Đế Vương Atlantis', 'Aquaman', 'https://phimimg.com/upload/vod/20231231-1/e0ac7e0d1fbf27b94a4292d6563c2ad5.jpg', 'https://phimimg.com/upload/vod/20231231-1/ddad618023d47450a28bdc2ee2e75f2b.jpg', '<p>Sau những sự kiện trong Justice League, Arthur Curry / Aquaman trở về biển cả và bắt đầu đảm nhận quyền thừa kế vương quốc Atlantis dưới sự cố vấn của công chúa Mera. Thế nhưng, đế chế huyền thoại bao năm ẩn mình dưới lòng biển sâu Atlantics sắp phải dậy sóng khi Orm quyết tâm thu phục 7 chủng tộc nơi đáy đại dương để tiêu diệt toàn bộ sự sống trên mặt đất.Giữa lúc biển xanh cuộn trào những đợt sóng dữ dội nhất Aquaman sẽ đương đầu với mọi việc như thế nào để bảo vệ quê hương và thế giới?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Momoa","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Yahya Abdul-Mateen Ii","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Ludi Lin","avatar":""},{"name":"Michael Beach","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Graham Mctavish","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Sophia Forrest","avatar":""},{"name":"Tainui Kirkwood","avatar":""},{"name":"Tamor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
