INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-bac-phong-van', 'Tây Bắc Phong Vân', 'Justice In Northwest', 'https://phimimg.com/upload/vod/20231231-1/43a6bb030d4796c1995620a283989d01.jpg', 'https://phimimg.com/upload/vod/20231231-1/e12d7a763945451807ff9098b6a3e032.jpg', '<p>Cao Kiều – đội trưởng đội cảnh sát chống tội phạm ma tuý- bị thương dẫn tới mất vị giác sau lần vây bắt tội phạm. Cô tình cờ quen với ông chủ tiệm cháo và trở thành khách quen của quán. Nhưng không ngờ ông ta là người chế ma tuý cho đường dây tội phạm lớn. Liệu rằng mối quan hệ của cả hai sẽ như thế nào.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Bành Kính Từ","avatar":""},{"name":"Từ Nam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
