INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-nhan-so-ket-duyen-voi-utsusemi', 'Hữu Nhân Sổ: Kết Duyên Với Utsusemi', 'Natsume Yujin-cho The Movie: Ephemeral Bond', 'null', 'https://phimimg.com/upload/vod/20240102-1/43bb23bcf8c17ba7b00fc2cfa9b680b6.jpg', '<p>Ngày ngày trải qua cuộc sống bận rộn cùng với các yêu quái, Takashi tình cờ gặp lại bạn học cũ Yuki, Vào lúc này, Takashi quen với Tsumura Yorie từng xuất hiện trong ký ức của yêu quái đã được trả lại tên. Bà có quen biết với Reiko, hiện đang sống một cuộc sống bình yên bên đứa con duy nhất là Tsumura Mukuo. Nhưng thị trấn nơi hai mẹ con bà sống dường như có yêu quái bí ẩn tiềm tàng. Trên đường điều tra chuyện này trở về, hạt giống yêu ký sinh trên người Nyanko-sensei đã lớn thành cây và kết quả trong sân nhà Fujiwara. Không ngờ Nyanko-sensei ăn trái cây có hình dáng tương tự với mình xong lại phân chia thành ba cá thể.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kamiya Hiroshi","avatar":""},{"name":"Inoue Kazuhiko","avatar":""},{"name":"Gao Liang Jian Wu","avatar":""},{"name":"Kobayashi Sanae","avatar":""},{"name":"Fujimura Ayumi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324393);
