INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-bien-do', 'Điệp Vụ Biển Đỏ', 'Operation Red Sea', 'https://phimimg.com/upload/vod/20240102-1/622a17de8c9d5996133aa3859d0b338c.jpg', 'https://phimimg.com/upload/vod/20240102-1/06a62ec1f106f8767fe45c21ad105ec4.jpg', '<p>Câu chuyện của phim Điệp Vụ Biển Đỏ lấy bối cảnh từ hành động sơ tán Hoa kiều để bảo vệ lợi ích của những kiều dân Trung Quốc, lúc này một hạm đội Hải quân được lệnh đến Italia để chấp hành nhiệm vụ sơ tán cho kiều dân. Tuy nhiên, trong cuộc sơ tán đó, hai mẹ con người Trung Quốc đã bị một tổ chức khủng bố quốc tế bắt cóc, vì thế mà Hải quân đã phái Đại đội đặc chủng Giao Long gồm 5 người đến giải thoát con tin, địa điểm mà họ phải tiến vào để tiếp cận con tim chính là một khu rừng núi hoàn toàn xa lạ với rất nhiều những hiểm nguy đang chờ đợi…</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"Johnny Huang","avatar":""},{"name":"Hai Qing","avatar":""},{"name":"Du Jiang","avatar":""},{"name":"Jiang Luxia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
