INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cua-sara', 'Nhật Ký Của Sara', 'Sara''s Notebook', 'https://phimimg.com/upload/vod/20240102-1/c6bd99c12c797d004464a01b2659fbc6.jpg', 'https://phimimg.com/upload/vod/20240102-1/21d7f9db80d3f1e0222ea23efb28510d.jpg', '<p>Laura Alonso là một luật sư người Tây Ban Nha từ Madrid đến Cộng hòa Congo, để tìm kiếm Sara, em gái của cô, sống sau hai năm tại đây, nhưng giờ không còn manh mối về cô em. Tìm kiếm địa chỉ liên lạc, Laura nhận ra rằng Sara đang ở khu vực Goma, một trong những khu vực khó khăn nhất của đất nước do các lãnh chúa bộ tộc cai quản và chiến tranh triền miên vì tranh giành xuất khẩu khoáng sản. Quyết tâm đi đến cuối cùng mặc dù không biết quốc gia cũng như ngôn ngữ, Laura liên lạc với Sergio Rojas, một doanh nhân người Latinh, để tìm cách đến Goma. Laura đã nhờ Sven, người yêu cũ của Sara, để cùng đến Goma. Cả hai cùng nhau bắt đầu một cuộc hành trình từ Kinsasa (thủ đô Congo) đến Goma. Cuộc hành trình của họ là nỗi sợ hãi, súng đạn, máu và sự man rợ...</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Belén Rueda","avatar":""},{"name":"Marian Álvarez","avatar":""},{"name":"Manolo Cardona","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
