INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-song-sot', 'Những Người Sống Sót', 'I Think We''re Alone Now', 'https://phimimg.com/upload/vod/20240102-1/e1b60804d31701e4665fd5982c42b606.jpg', 'https://phimimg.com/upload/vod/20240102-1/2317800adc625a0514db251e476c254c.jpg', '<p>Những Người Sống Sót - I Think Were Alone Now (2018):Del là người sống sót sau cơn đại dịch quét sạch loài người trên thế giới, anh ta sống hoàn toàn đơn độc ở một thị trấn nhỏ. Cho đến một ngày Del phát hiện ra Grace, một cô gái đang bị mắc kẹt trên một chiếc xe...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peter Dinklage","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Paul Giamatti","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324393);
