INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-thien-tai', 'Nhà Văn Thiên Tài', 'Heung-Boo: The Revolutionist', 'https://phimimg.com/upload/vod/20240102-1/6c40c93f09a7e9e2f78c4b371043b684.jpg', 'https://phimimg.com/upload/vod/20240102-1/f225242fde6b0c6bd9081540d7e1296f.jpg', '<p>Bộ phim lấy bối cảnh thời kỳ Joseon khi những kẻ quý tộc đấu đá tranh giành quyền lực và cuộc sống của dân thường càng ngày càng khó khăn. Trong phim, Jung Woo vào vai nhà văn tài ba nhất Joseon - Heung Boo, người viết văn để tìm anh trai thất lạc của mình. Kim Joo Hyuk vào vai Jo Hyuk, người giúp Heung Boo nhận ra lí tưởng thay đổi thế giới của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
