INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('incoming', 'Incoming', 'Incoming', 'https://phimimg.com/upload/vod/20240102-1/7c8f48090619951a888ede71911fcfb5.jpg', 'https://phimimg.com/upload/vod/20240102-1/69e0b7f40d9803f3242ad29abe21f196.jpg', '<p>Trạm vũ trụ quốc tế hiện là một nhà tù - địa điểm đen cuối cùng. Không ai ra ngoài. Và không ai biết nó ở đó. Nhưng khi những kẻ khủng bố bị cầm tù chiếm lấy Nhà ga và biến nó thành một tên lửa nhằm vào Moscow, chỉ có một phi công đưa đón và một bác sĩ tân binh mới có thể ngăn chặn chúng. Nhiệm vụ của họ rất phức tạp bởi một điệp viên CIA lừa đảo (Scott Adkins), người có kế hoạch riêng cho nhà ga và những kẻ khủng bố bên trong.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Aaron McCusker","avatar":""},{"name":"Michelle Lehane","avatar":""},{"name":"Vahidin Prelić","avatar":""},{"name":"Lukas Loughran","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
