INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-thoi-gian-de-yeu-em', 'Ngược Dòng Thời Gian Để Yêu Em', 'Another Time', 'https://phimimg.com/upload/vod/20231231-1/946c5a7ebaf081cc4caadac43eb64807.jpg', 'https://phimimg.com/upload/vod/20231231-1/91ed99b5cb453cd3aec20070427736ae.jpg', '<p>Ngược Dòng Thời Gian Để Yêu Em - Another Time là bộ phim lãng mạn ly kỳ về người đàn ông tên Eric. Anh đã du hành ngược thời gian để có cơ hội được yêu lại lần nữa. Ở khoảng thời gian trôi ngược này, anh ấy gặp Ally, là người yêu lý tưởng mà anh đang tìm kiếm. Eric sẽ phải làm gì khi thời gian trở về hiện tại đang đến gần, đi hay ở với tình yêu vừa tìm thấy của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arielle Kebbel","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
