INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bang-2', 'Người Băng 2', 'Iceman 2: The Time Traveler', 'https://phimimg.com/upload/vod/20231231-1/fb082716afa2142500d81785f6ee9c3d.jpg', 'https://phimimg.com/upload/vod/20231231-1/3e446767427fefc010013f06bbcd3894.jpg', '<p>Người Băng 2 tiếp nối chuyến phiêu lưu của một Cẩm y vệ đời nhà Minh – Hạ Anh (Chân Tử Đan đóng), sau khi được giải thoát khỏi lớp băng từ một trận đánh gần 4 thế kỷ trước. Tại Hồng Kông, Người Băng được tái sinh, gặp gỡ và thân thiết với Tiểu Mỹ. Nhưng do là người duy nhất nắm giữ bí mật du hành thời gian, anh bị truy lùng bởi cảnh sát và truyền thông. Anh phải đến Bắc Kinh quay ngược dòng thời gian về lại Minh triều, bằng cách sử dụng khả năng điều khiển Kim Cầu, tìm cách thay đổi lịch sử để bảo vệ những người thân yêu. Tuy nhiên, một cái bẫy đang chờ sẵn khi anh quay về quá khứ. Điều gì sẽ xảy ra khi anh thay đổi lịch sử?</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Baoqiang Wang","avatar":""},{"name":"Huang Sheng-Yi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324393);
