INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-rising', 'A.I. Rising', 'A.I. Rising', 'https://phimimg.com/upload/vod/20240123-1/f7286fc1d7a0f2002b8a1bef7f04b3a2.jpg', 'https://phimimg.com/upload/vod/20240123-1/34fe850befc31f51571b63abdb0bd059.jpg', '<p>Ederlezi Rising là một huyền thoại viễn tưởng khoa học thú vị được thiết lập trong tương lai gần về nhiệm vụ không gian tiên phong đến Alpha Centauri được thực hiện bởi Tập đoàn đa quốc gia Ederlezi. Ederlezi tuyển mộ Milutin Một Cosmonaut Slav được đào tạo trong Liên Xô tương lai mới được cải cách và đồng hành cùng anh ta với Nimani, một nữ Android được lập trình để thực hiện bất cứ điều gì anh ta mong muốn.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324393);
