INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-luc-sieu-pham', 'Năng Lực Siêu Phàm', 'Psychokinesis', 'https://phimimg.com/upload/vod/20240123-1/01a6dce71c857675cae794fff84a2972.jpg', 'https://phimimg.com/upload/vod/20240123-1/02d0491ad3323282df145179d639340b.jpg', '<p>Năng Lực Siêu Phàm (Psychokinesis ) kể về Shin Seok-heon (Ryu Seung-ryong) - nhân viên bảo vệ của một trung tâm chăm sóc sức khỏe. Một lần tình cờ, ông uống phải thứ hợp chất lạ tiết ra từ mảng thiên thạch bí ẩn rơi xuống gần nơi mình sinh sống. Sau đó, Seok-heon cảm thấy cơ thể mình bắt đầu có nhiều biểu hiện khác lạ, và khám phá ra bản thân nay sở hữu siêu năng lực giúp di chuyển vật thể từ xa. Ông quyết tâm dùng khả năng trời cho để giúp đỡ Roo-mi (Shim Eun-kyung) - cô con gái mà Seok-heon từng bỏ rơi từ nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Shim Eun-kyung","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Jung Yu-mi","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Kim Young-sun","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Tae Hang-ho","avatar":""},{"name":"Jung Young-ki","avatar":""},{"name":"Lee Je-yeon","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Go Na-Hee","avatar":""},{"name":"Lee Jeong-eun","avatar":""},{"name":"Woo Jung-kook","avatar":""},{"name":"Han Sung-soo","avatar":""},{"name":"Hwang Yeon-hui","avatar":""},{"name":"Yoon Don-sun","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324393);
