INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-anh-do-vat', 'Chuyện Tình Anh Đô Vật', 'Love+Sling', 'https://phimimg.com/upload/vod/20231230-1/c2e62eed85c76dfb6e588cb84447a619.jpg', 'https://phimimg.com/upload/vod/20231230-1/8a7c66bfc07d8471cfd10669759fda02.jpg', '<p>Bộ phim hài tình cảm này xoay quanh cuộc sống của một người đàn ông từng là vận động viên đấu vật, đang sống trong cảnh gà trống nuôi con và chàng trai hiếu thảo luôn cố gắng hết sức để nối nghiệp đấu vật của bố. Quan hệ cha con của họ bỗng một ngày trở nên rối rắm trước sự xuất hiện của Lee Sung Kyung, một cô bạn mà người con trai rất thích, nhưng cô nàng lại đem lòng thích người bố.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324393);
