INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-suong-chet', 'Màn Sương Chết', 'Just A Breath Away', 'https://phimimg.com/upload/vod/20231230-1/1d9e6cbcb1ea7b66b4b245a012e36fbe.jpg', 'https://phimimg.com/upload/vod/20231230-1/ad6a60fc7724df822ea244456d187ae4.jpg', '<p>Không được báo trước, một trận động đất vô cùng lớn tấn công Paris, cả thành phố sau đó bị bao phủ bởi một lớp sương mù dày đặc. Màn sương chết ấy đang lần lượt cướp đi tính mạng của rất nhiều những người dân nơi đây. Gia đình cô bé 11 tuổi Sarah - người được nuôi dưỡng trong lồng kính y tế đặc biệt từ khi vừa chào đời, may mắn là một trong số ít những người còn sống sót, nhưng họ cũng chỉ cách cái kết tàn nhẫn kia một làn hơi thở vô cùng mong manh. Liệu phép màu nào đó sẽ xảy ra? Và sự sống có thể tiếp diễn với cô bé và gia đình trong khi tất cả điều kiện sống không đứng về phía họ?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Romain Duris","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Fantine Harduin","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324393);
