INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-doc-tren-con-song', 'Đơn Độc Trên Con Sóng', 'Solo', 'https://phimimg.com/upload/vod/20231230-1/0094b9bbdd166601fa019e4fc161deaf.jpg', 'https://phimimg.com/upload/vod/20231230-1/fdcbf48ab77bfc59da6feb836005f133.jpg', '<p>Ở Quần đảo Canary hẻo lánh, một tay lướt sóng rơi khỏi vách đá. Chiến đấu để sinh tồn, anh suy ngẫm về cuộc sống và quá khứ tình cảm. Dựa trên các sự kiện có thật.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Alain Hernández","avatar":""},{"name":"Aura Garrido","avatar":""},{"name":"Ben Temple","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
