INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-muon-an-tuy-cua-cau-2018', 'Tớ Muốn Ăn Tụy Của Cậu', 'I Want To Eat Your Pancreas', 'https://phimimg.com/upload/vod/20231227-1/baa3d1f929496cbcf739b764c0e70710.jpg', 'https://phimimg.com/upload/vod/20231227-1/e014187941b5f78cc9471ff3bd772fd6.jpg', '<p>Ngày nọ, nhân vật chính tìm được một cuốn nhật ký, của cô bạn cùng lớp Sakura Yamauchi, trong bệnh viện. Qua đó, cậu biết được rằng cô bạn của mình đang trải qua căn bệnh tuyến tụy giai đoạn cuối và chỉ còn sống được vài tháng mà thôi. Sakura đã nói rằng cậu là người duy nhất ngoài gia đình cô biết về sự thật này. Cậu đã hứa giữ bí mật cho Sakura. Dù tính cách của họ hoàn toàn trái ngược nhau, nhân vật chính quyết định sẽ ở bên cạnh Sakura trong những ngày tháng cuối đời của cô.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mahiro Takasugi","avatar":""},{"name":"Lynn","avatar":""},{"name":"Jun Fukushima","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Atsuko Tanaka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324393);
