INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-ai', 'Sủng Ái', 'The Favourite', 'https://phimimg.com/upload/vod/20231219-1/636fc78f3a2c0a162377bada71a7e220.jpg', 'https://phimimg.com/upload/vod/20231219-1/0324b46ec6fc6004ab5f9fc456110c7c.jpg', '<p>Đầu thế kỷ 18. Anh đang chiến tranh với người Pháp. Tuy nhiên, đua vịt và ăn dứa đang phát triển mạnh. Một nữ hoàng yếu đuối Anne (Olivia Colman) chiếm ngôi mộ và người bạn thân của cô Lady Sarah (Rachel Weisz) cai quản đất nước thay cho cô ấy trong khi chăm sóc sức khỏe và tính khí trung bình của Anne. Khi một người hầu mới Abigail (Emma Stone) đến, sự quyến rũ của cô yêu cô đến Sarah. Sarah mất abigail dưới cánh của cô và Abigail nhìn thấy một cơ hội để trở về với rễ quý tộc của cô. Khi chính trị chiến tranh trở nên khá tốn thời gian cho Sarah, Abigail bước vào vi phạm để lấp đầy với tư cách là người bạn đồng hành của Nữ hoàng. Tình bạn đang phát triển của họ mang đến cho cô một cơ hội để thực hiện tham vọng của mình và cô sẽ không để người phụ nữ, người đàn ông, chính trị hoặc thỏ đứng theo cách của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324393);
