INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('real-girl', 'Real Girl', 'Real Girl', 'https://phimimg.com/upload/vod/20231230-1/28a5a047253bca69ee7e9ca7f03e9e25.jpg', 'https://phimimg.com/upload/vod/20231230-1/ba87c44f875760eec937d48099ec8a51.jpg', '<p>Hikaru Tsutsui là một học sinh trung học. Anh ấy thích các trò chơi hoạt hình và video trong thế giới ảo, nhưng anh ấy không tận hưởng cuộc sống thực của anh ấy. Những người ở trường của mình thậm chí không biết anh ta tồn tại. Một ngày nọ, anh dọn dẹp hồ bơi ở trường của mình với Iroha Ikarashi xinh đẹp. Iroha tiếp cận Hikaru và thú nhận rằng cô ấy thích anh ta.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324393);
