INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-neo-cua-parker', 'Mỏ Neo Của Parker', 'Parker''s Anchor', 'https://phimimg.com/upload/vod/20240121-1/44353dd5abb14f33acb6617890c96201.jpg', 'https://phimimg.com/upload/vod/20240121-1/9de4973abac636299e24b84dba46af3d.jpg', '<p>Khi Krystal Parker phát hiện ra cuộc sống của mình không theo kế hoạch của cô, cô học cách buông tay và bắt đầu lại. Sau khi chồng bỏ cô vì cô không thể có con, Krystal Parker tìm thấy sự bình yên khi gặp gỡ với người bạn thân thời thơ ấu. Cô trở nên mạnh mẽ hơn để bước ra thế giới và với sự hỗ trợ của mọi người trong thị trấn, cô đã mở lòng với những cơ hội mới và tìm được tình yêu đích thực của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Marquette","avatar":""},{"name":"Michael Beach","avatar":""},{"name":"Penny Johnson Jerald","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
