INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-thien-dai-thanh-tran-yeu-quai', 'Tề Thiên Đại Thánh: Trấn Yêu Quái', 'Qi Tian Da Sheng', 'https://phimimg.com/upload/vod/20240121-1/75180045462feaccf9e1dd1aff977011.jpg', 'https://phimimg.com/upload/vod/20240121-1/517d598d7f061596fd6a7e297f0f6f11.jpg', '<p>Trên đường giải cứu sư phụ, Ngộ Không và Bát Giới lưu lạc đến một trấn nhỏ chỉ toàn những tiểu yêu quái đáng mến. Nhờ vậy, họ dần tìm được manh mối vế con yêu quái đang bắt giữ sư phụ Đường Tăng. Mặt khác, cả hai không hề biết rằng trong những yêu quái nơi đây có kẻ âm mưu muốn chiếm lấy trái tim của Ngộ Không</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Tử Thông","avatar":""},{"name":"Phạm Mộng","avatar":""},{"name":"Trần Hạo Dân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324393);
