INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-chap-hiem-nguy', 'Bất Chấp Hiểm Nguy', 'Point Defiance', 'https://phimimg.com/upload/vod/20240121-1/fa48c35b84355b68f4da8d7fdedd55cb.jpg', 'https://phimimg.com/upload/vod/20240121-1/4f2ae14b05155262dabf5a5f0868cdb4.jpg', '<p>Bất Chấp Hiểm Nguy - Point Defiance xoay quanh một ngôi nhà biệt lập tại vùng quê của hai anh em. Nơi đây bỗng trở nên bí ẩn sau khi người anh trai trở về từ nghĩa vụ quân sự ở Afghanistan. Một cô gái xinh đẹp đến thăm người anh, nhưng sau hôm đó, tin cô ta mất tích lan rộng trên các bản tin. Sự trùng hợp và chiếc áo dính máu được người em tìm thấy khiến cho anh ta càng chắc chắn thủ phạm là anh trai mình. Anh ta sẽ làm gì? Tố cáo hay che đậy sự thật? Những bí mật kinh hoàng gì bị chôn vùi tại đây?</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
