INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giu-ngon-hai-dang', 'Người Giữ Ngọn Hải Đăng', 'The Vanishing', 'https://phimimg.com/upload/vod/20231230-1/f0079fd7fe4e229c8998a79728ee2c6b.jpg', 'https://phimimg.com/upload/vod/20231230-1/0528476f521052806755119327690baa.jpg', '<p>Phim được lấy cảm hứng từ bí ẩn Flannan Isle. Một chiếc thuyền cứu trợ nhỏ tiếp cận Isle, một hòn đảo nhỏ bị cô lập, 20 dặm ngoài khơi bờ biển gồ ghề. Mục đích của nó là thay thế ba người giữ ngọn hải đăng, sau 6 tuần một mình làm việc. Nó gần bến tàu và không ai trong số họ chào đón. Tời bị hỏng. Một cuộc gọi. Không có gì. Những người gác có kinh nghiệm là Thomas, James và Donald đã biến mất. Các đèn được làm sạch và nạp lại; Bàn được đặt cho bữa tối. Có một chiếc ghế lộn ngược. Hai bộ thùng dầu màu vàng bị thiếu ... Những người đàn ông không bao giờ được tìm thấy.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Connor Swindells","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
