INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-gioi', 'Địa Giới', 'Terminal', 'https://phimimg.com/upload/vod/20231219-1/5222cf3cc84cc258771ab6e8cffa06ef.jpg', 'https://phimimg.com/upload/vod/20231219-1/22308548deae95bf4b48eb4697b1c100.jpg', '<p>Địa Giới - Terminal lấy bối cảnh một thành phố ngổn ngang vì các phe phái thanh toán lẫn nhau, xoay quanh vụ trả thù ngọt ngào của Annie (Margot Robbie) - một sát thủ hàng loạt khêu gợi và nguy hiểm với khả năng cải trang, lừa lọc và thả thính siêu cấp. Các nhân vật khác gồm cặp sát thủ đang làm nhiệm vụ, một giáo viên hấp hối và người chăm sóc bí ẩn, tất cả đều là những đầu mối dẫn tới vụ trả thù trung tâm của phim.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Robbie","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Dexter Fletcher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324393);
