INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-the-ngoc', 'Phương Thế Ngọc', 'Fong Sai Yuk', 'https://phimimg.com/upload/vod/20231219-1/eb333d6e3220e6f7fde7e48dfbf7fe4b.jpg', 'https://phimimg.com/upload/vod/20231219-1/c3e61e27e796e049db0f7e340fafb4a2.jpg', '<p>Thiếu niên Phương Thế Ngọc thông minh xuất chúng, yêu thích võ thuật nhưng bị cha ép theo con đường đèn sách. Để không bị áp bức bởi những thế lực đen tối, Phương Thế Ngọc đã cùng Hồng Hi Quan và Hồ Huệ Càn kết nghĩa huynh đệ, hành hiệp trượng nghĩa, cứu giúp bá tánh. Thế nhưng, con đường họ chọn không hề dễ dàng.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Tiễn Sắc Lệ","avatar":""},{"name":"Từ Tử Lực","avatar":""},{"name":"Tống Lôi Đào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324393);
