INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-sinh-ton', 'Ngày Sinh Tồn', 'Hostile', 'https://phimimg.com/upload/vod/20231219-1/f89e9118a5215b59963d8f69494ec515.jpg', 'https://phimimg.com/upload/vod/20231219-1/e4ba7a66c500cddde7d841d9a7be36fc.jpg', '<p>Nếu bạn trở thành số ít loài người còn sống sót khi dịch bệnh bùng nổ, liệu bạn sẽ là người may mắn, hay là kẻ phải mang nỗi bất hạnh? Sau khi người thương biến mất, Juliette từ một cô nàng ngỗ ngược, cô trở thành một chiến binh chiến đấu với những sinh vật đáng sợ bởi căn bệnh quái ác khiến cho nhân loại đang đứng trước bờ vực của sự diệt vong. Trải qua rất nhiều khó khăn, thử thách, liệu hạnh phúc có mỉm cười với Juliette, và Trái đất có được giải cứu khỏi đám quái vật mang trong mình mầm bệnh nguy hiểm đó?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Javier Botet","avatar":""},{"name":"Brittany Ashworth","avatar":""},{"name":"Grégory Fitoussi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
