INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuong-ghen', 'Kẻ Cuồng Ghen', 'A Friend''s Obsession', 'https://phimimg.com/upload/vod/20231219-1/1a3f9658d1e367308a5a89ecbfa114fb.jpg', 'https://phimimg.com/upload/vod/20231219-1/042bd44d86635493b970c32adc92d9d4.jpg', '<p>Kẻ Cuồng Ghen - A Friends Obsession là bộ phim lấy cảm hứng từ những sự kiện có thực. Khi vị hôn phu Megan bị giết chết dã man, cô bắt đầu hành trình xuyên quốc gia để xây dựng lại cuộc sống. Cô tình cờ gặp lại Lloyd, người đồng nghiệp cũ, anh ấy vẫn muốn vượt qua ranh giới bạn bè và có mối quan hệ yêu đương với cô. Khi biết Megan có bạn trai mới, Lloyd liền lên kế hoạch để sẽ đối phó, giống như cách Lloyd đối xử với chồng sắp cưới của Megan một năm trước...</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324393);
