INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bim-sua', 'Cuộc Chiến Bỉm Sữa', 'Tully', 'https://phimimg.com/upload/vod/20231219-1/e1b331569fc7301090b8f6f72a4230c1.jpg', 'https://phimimg.com/upload/vod/20231219-1/04ac6f0418aae50ca5830ad716e52e8f.jpg', '<p>Khủng hoảng ập đến với Marlo khi đứa con thứ ba của cô chào đời. Hai đứa lớn trong đó có cậu con trai, Jonah gặp khó khăn trong việc hoà nhập cùng các bạn và cần nhiều sự chăm sóc từ mẹ. Chồng cô, một tuýp người đàn ông có gia đình kiểu mẫu, tỏ ra yêu thương vợ, con hết mực nhưng thật sự vô tâm. Dù không thích nhận sự giúp đỡ nhưng Marlo không thể một mình cáng đáng mọi thứ.</p>', 'Full', 1, 'single', 'completed', 6, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlize Theron","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Mark Duplass","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324393);
