INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-cua-laplace', 'Phù Thủy Của Laplace', 'Laplace''s Witch', 'https://phimimg.com/upload/vod/20231215-1/3f3465a1b20dbdb69050d9aa4aef1590.jpg', 'https://phimimg.com/upload/vod/20231215-1/b2ed81023f49ddf463e928e0c9923112.jpg', '<p>2 người bị đầu độc bằng Hydro sulfua (H2S) tại 1 suối nước nóng. Cảnh sát yêu cầu chuyên gia, nhà địa lý học, Shusuke Aoe xác nhận xem nguyên nhân cái chết là do tai nạn hay do bị sát hại. Trong quá trình điều tra, Shusuke Aoe gặp Madoka Uhara, người dự đoán chính xác rằng sẽ có hiện tượng tự nhiên xảy ra. Cảnh sát bắt đầu nghi ngờ Madoka có liên quan tới cái chết, và vụ án thứ 3 xảy ra.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sho Sakurai","avatar":""},{"name":"Suzu Hirose","avatar":""},{"name":"Sota Fukushi","avatar":""},{"name":"Tao Okamoto","avatar":""},{"name":"Lily Franky","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324393);
