INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oi-troi-thai-tu-dien-ha-cua-toi', 'Ôi Trời Thái Tử Điện Hạ Của Tôi', 'Oh My Prince', 'https://phimimg.com/upload/vod/20231215-1/9b5b2281571d84755b4ccfeb29cf1074.jpg', 'https://phimimg.com/upload/vod/20231215-1/9a6cb171c16cf5d2e4e4633279a1ac08.jpg', '<p>Phượng Hoàng xinh đẹp rơi xuống trần gian, được phong làm Trục Nguyệt công chúa. Khi Dực quốc và Nam Du quốc giao tranh, để hoà hoãn cuộc chiến, Trục Nguyệt công chúa vô tình gả vào thâm cung, bị quấn vào một loạt cuộc đấu tranh cung đình. Cùng xem thử Tiểu Phượng Hoàng làm thế nào để biến nguy thành an, giành được trái tim của Thái tử.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phùng Chỉ Mặc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324393);
