INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tich-hien-dai-phan-1', 'Cổ Tích Hiện Đại (Phần 1)', 'Tell Me A Story (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/36ad3642f7670c03f0ea93ebac3d77be.jpg', 'https://phimimg.com/upload/vod/20231219-1/0cbe3a216aaa263664474617eb0e5aa5.jpg', '<p>Đây là nội dung catch-up kênh BlueAnt Entertainment, sẽ hết hạn sau 7 ngày, quý khách cần active gói VIP để xem.Ra mắt vào ngày lễ Halloween, series gốc của đài CBS Tell Me A Story sẽ đưa người xem đến với góc nhìn khác của những câu chuyện cổ tích được yêu thích nhất, biến chúng trở thành những câu chuyện kinh dị ghê rợn.Lấy bối cảnh thành phố New York hiện đại, mùa đầu tiên của series này sẽ chọn kể lại The Three Little Pigs, Little Red Riding Hood và Hansel and Gretel, mang đến những tập phim về tình yêu, mất mát, sự tham lam, trả thù và những kẻ giết người.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Wesley","avatar":""},{"name":"Danielle Campbell","avatar":""},{"name":"James Wolk","avatar":""},{"name":"Natalie Alyn Lind","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324393);
