INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-luc-trong-bong-toi', 'Quyền Lực Trong Bóng Tối', 'Vice', 'https://phimimg.com/upload/vod/20231213-1/2ca474f56cb6bc40a4d61977c4b87af3.jpg', 'https://phimimg.com/upload/vod/20231213-1/58c26f78b03e5b16f6aa218f5d5a3fe9.jpg', '<p>Quyền Lực Trong Bóng Tối - Vice (2018): Vice là vai diễn mới nhất của nam diễn viên Christian Bale, tái hiện lại cuộc đời chính trị của phó tổng thống quyền lực nhất trong lịch sử nước Mỹ. Bộ phim nói về Dick Cheney, phó tổng thống đời thứ 46 của nước Mỹ, ông phục vụ dưới thời George W. Bush, được đánh giá là phó tổng thống có thực quyền cao nhất lúc bấy giờ. Dick Cheney sinh năm 1941, từng làm chức Bộ trưởng bộ Quốc phòng Mỹ, sau đó được bổ nhiệm làm phó Tổng thống dưới quyền Tổng thống George W. Bush cả 2 nhiệm kỳ, từ 2001 tới 2009. Ông Cheney là người có vai trò trong nhiều chính sách quan trọng của TT Bush, mở rộng quyền hành pháp ở Mỹ, ông cũng được cho là “kiến trúc sư” của cuộc chiến tranh Iraq.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Steve Carell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
