INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-bat-ap-chinh', 'Tà Bất Áp Chính', 'Hidden Man', 'https://phimimg.com/upload/vod/20231211-1/7fee347100c367e4380c06391b13a257.jpg', 'https://phimimg.com/upload/vod/20231211-1/e63ec5b401a47450d8ccd55545a6c436.jpg', '<p>Bộ phim lấy bối cảnh những năm 30 thời kỳ quân phiệt hỗn chiến ở Trung Quốc. Chứng kiến sư huynh Tiềm Long (Liêu Phàm) cấu kết với Nhật Bản giết hại cả nhà sư phụ, Lý Thiên Nhiên (Bành Vu Yến) may mắn thoát thân và được một vị bác sĩ người Mỹ cứu giúp. Sang Mỹ, Thiên Nhiên vốn có thiên phú về võ thuật, anh chàng được tham gia huấn luyện đặc công và sau đó anh trở về Trung Quốc để báo thù.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Wen","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Liao Fan","avatar":""},{"name":"Zhou Yun","avatar":""},{"name":"Xu Qing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
