INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kien-cuong', 'Kiên Cường', 'Tankers', 'https://phimimg.com/upload/vod/20231212-1/df57f797166060987fbeb4b79e23c231.jpg', 'https://phimimg.com/upload/vod/20231212-1/1b890736f16d2f481380fe7dbe5838bd.jpg', '<p>Kiên Cường - Tankers (2018):Phim kể về một nhân vật có thật, đại úy Sêmiôn Kônôvalốp. Kíp xe của đại úy Kônôvalốp đã diệt 16 xe tăng, 2 xe bọc thép và 8 xe ô tô của Đức. Chiến đấu cùng đơn vị ở chiến trường Nhiznhemichiatkin, Huyện Taraxốpxki, Tỉnh Rôxtốp. Sau đó 3 người còn sống của kíp chiến đấu. Bắt được một chiếc xe tăng Đức, quay về với Hồng quân. Vì hành động anh hùng, Xêmiôn Kônôvalốp (1920 - 1989) đã được phong danh hiệu Anh hùng Liên bang Xô-viết.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Andrey Chernyshov","avatar":""},{"name":"Vladimir Yepifantsev","avatar":""},{"name":"Olga Pogodina","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324394);
