INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ky-dieu-o-kasama', 'Điều Kỳ Diệu Ở Kasama', 'Miracle In Kasama', 'https://phimimg.com/upload/vod/20231212-1/055ce0ae1f4c80809b410988b8c08064.jpg', 'https://phimimg.com/upload/vod/20231212-1/15397b229f1e345e9f86ab9695eb5433.jpg', '<p>Bạn thấy đấy, hạt dẻ được bọc trong một cái vỏ cứng và đầy gai. Chúng ta cũng vậy. Điều kỳ diệu ở Kasama, xoay quanh Yuka Shibuya, một nữ diễn viên đang gặp khó khăn ở Tokyo. Mùa thu hàng năm Yuka đều đến thị trấn nông thôn Kasama để giúp gia đình Kinoshita thu hoạch hạt dẻ. Nhưng năm nay thì khác. Ông ngoại Kinoshita đã qua đời vào mùa xuân và Hatsue hiện đang sống một mình. Daiki Mishima, một thanh niên bí ẩn toàn thân bị đánh bầm dập, đột nhiên xuất hiện trong cánh đồng hạt dẻ. Bất chấp sự phản đối của Yuka, Hatsue đưa anh vào nhà cô để giúp đỡ. Khi vụ thu hoạch hạt dẻ bắt đầu, cả ba bắt đầu hình thành một mối quan hệ đặt biệt.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Akiko Kurano","avatar":""},{"name":"Mau Nishio","avatar":""},{"name":"Yûhi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
