INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-doc-ac', 'Kế Hoạch Độc Ác', 'Lizzie', 'https://phimimg.com/upload/vod/20231211-1/ea0535f8d26a11b21b5a711018414e73.jpg', 'https://phimimg.com/upload/vod/20231211-1/39cd0e2c4a36586cafd5a40c42d31716.jpg', '<p>Lizzie là một phụ nữ chưa lập gia đình ở tuổi 32. Cô là người bị ruồng bỏ trong gia đình khi người cha là một quý tộc lấy thêm vợ lẽ. Cuộc đời của Lizzie đã trở nên tươi mới đầy sức sống khi Bridget Sullivan - một cô hầu gái trẻ nghèo khó đến sống với gia đình. Lizzie tìm thấy sự đồng cảm của cô hầu gái hiền lành, xinh đẹp. Và mối tình đồng giới của hai cô gái đã nảy nở nhưng đồng thời đi kèm với một kế hoạch độc ác được gây dựng.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Sevigny","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Jamey Sheridan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
