INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quyet-chien-thien-vuong', 'Quyết Chiến Thiên Vương', 'The Epic Battle', 'quyết chiến thiên vương the epic battle wang yi lin felix lok hugo ng doi-yung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-bong-tinh-yeu', 'Đuổi Bóng Tình Yêu', 'Sai Rak Sai Sawat', 'https://phimimg.com/upload/vod/20231219-1/e36d76424bd8fb0e35cd87e6b76aff06.jpg', 'https://phimimg.com/upload/vod/20231219-1/2107751a50d5c4f62974bf6e7baeddc6.jpg', '<p>Câu chuyện bắt đầu vào năm 1921. Jao Karmfah là một nhà quý tộc đến từ Chiang Mai. Như một sự sắp đặt của các thành viên trong gia đình, anh đã đính hôn với Yaowalak. Sau khi trở lại Chiang Mai để kinh doanh, anh đã yêu Fongkae ngay từ cái nhìn đầu tiên. Karmfah quyết định cắt đứt giao ước với Yaowalak để theo đuổi Fongkae. Tuy nhiên, Fongkae đã có một người đàn ông cô ấy yêu, Khun Chai Yingsak Warangkorn. Cha mẹ của Fongkae thích Karmfah làm con rể của họ và nhốt Fongkae đi, trong khi chờ đợi lễ cưới của cô cho Karmfah. Yingsak lẻn vào nhà Fongkae và đưa cô ấy đi. Khi nghe thấy điều này, Karmfah nhanh chóng đuổi theo họ. Khi anh tìm thấy họ, anh nhận ra rằng anh không thể ép buộc bất cứ ai yêu anh. Cũng như Yaowalak không thể ép anh yêu cô. Anh cho phép họ ở bên nhau, và đưa cho Fongkae một chiếc trâm cài tóc mà anh đã đặc biệt chế tạo cho cô. Fongkae và Yingsak tiếp tục có hai con, Mom Luang Sakchai và Mom Luang Sommapa.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 14, 2018, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Camilla Kittivat Kirn","avatar":""},{"name":"Fluke Krirkphol Masayavanich","avatar":""},{"name":"Tre Porapat Srikajorn","avatar":""},{"name":"Tongtong Kitsakorn Kanoktorn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324394);
