INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-tieu-nhan-chung', 'Thủ Tiêu Nhân Chứng', 'Solver', 'https://phimimg.com/upload/vod/20231211-1/ee1ad9364deb1e601928255cede4df51.jpg', 'https://phimimg.com/upload/vod/20231211-1/24549c79675757897544d9d002b44e10.jpg', '<p>Khi Luke Williams đến thăm ngôi nhà của người ông quá cố, anh phát hiện ra câu đố chứa mật mã bí ẩn dẫn đến một sự thật nguy hiểm không thể lường trước.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Ruby","avatar":""},{"name":"Kerry Knuppe","avatar":""},{"name":"Antonio Jaramillo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
