INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-nam-lung-danh-va-thung-lung-khung-long', 'Bộ Năm Lừng Danh Và Thung Lũng Khủng Long', 'The Famous Five And The Valley Of Dinosaurs', 'https://phimimg.com/upload/vod/20231211-1/d31ccc2f910c4b0c1d0d121767c26c87.jpg', 'https://phimimg.com/upload/vod/20231211-1/619f4224930454643f14bbdf8b57f7ac.jpg', '<p>Trên đường đến một bữa tiệc mà họ không muốn tham dự, Bộ Năm Lừng Danh gần như cảm thấy nhẹ nhõm khi xe của dì Fanny bị hỏng, khiến họ mắc kẹt trong một thị trấn nhỏ. Để vượt qua thời gian, họ đến thăm bảo tàng lịch sử tự nhiên địa phương, nơi một số bộ xương khủng long mới được phát hiện đang được công bố. Tại đây họ gặp Marty, người nói với họ rằng cha anh, đã chết từ lâu, được cho là đã tìm thấy một bộ xương khủng long hoàn chỉnh và lập bản đồ về nơi ở của nó. Thật không may, bản đồ đã bị đánh cắp. George, Julian, Dick, Anne và Timmy, tham gia một chuyến đi bộ có hướng dẫn qua Thung lũng Khủng long.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amelie Lammers","avatar":""},{"name":"Marinus Hohmann","avatar":""},{"name":"Ron Antony Renzenbrink","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
