INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-dao-tren-troi-2018', 'Đảo Hải Tặc: Đảo Trên Trời (2018)', 'ONE PIECE Episode Of Skypiea  2018', 'https://phimimg.com/upload/vod/20231211-1/32841f520ee4493e28eb315e30e26f4b.jpg', 'https://phimimg.com/upload/vod/20231211-1/1172faf8822cda089a34eb755d262760.jpg', '<p>Cricket là hậu duệ của một nhà thám hiểm đáng xấu hổ được gọi là Noland Nói Dối, người đã được tưởng nhớ trong một câu chuyện cổ tích 400 năm trước. Tuy nhiên, Noland không nói dối và thực sự đã đến Đảo Trời. Luffy và những người khác vô tình có được bản đồ đến Đảo Trời, và biết được rằng họ phải bị nuốt chửng bởi dòng nước biển để đến đó. Sau khi vượt qua dòng hải lưu, họ đến Skypiea, vùng đất của các vị thần, một nơi được cai trị bởi Chúa Trời Enel.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"TanakaMayumi","avatar":""},{"name":"OkamuraAkemi","avatar":""},{"name":"NakaiKazuya","avatar":""},{"name":"YamaguchiKappei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
