INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-anh-toi-di-gium-cai', 'Đưa Anh Tôi Đi Giùm Cái!', 'Go Brother!', 'https://phimimg.com/upload/vod/20240104-1/320b4108449d5cee93e0ddb236655c7f.jpg', 'https://phimimg.com/upload/vod/20240104-1/11e4429707c236b49d529f12c32488f5.jpg', '<p>Phim quanh một cặp anh trai em hay xung đột với nhau, một thằng anh trai không quan tâm đến gia đình, suốt ngày chọc phá em gái sẽ có cảm giác như thế nào??? Nên chiên hắn lên hay cho vào nồi hấp đây? Thời Miểu chỉ mong anh trai mình lập tức biến mất khỏi thế gian này, đến điều ước trong ngày sinh nhật đáng quý của mình cũng là ”Mau Đưa Anh Tôi Đi Giùm Cái”. Không ngờ điều ước ấy lại thành hiện thực. Anh trai mình trở thành anh trai của bạn thân cô Diệu Diệu, Thời Miểu hiểu được cảm giác của Diệu Diệu đồng thời trong lòng cũng thầm gào thét ”Đồ độc ác”! Thời Miểu trở thành đứa con duy nhất trong gia đình, cô cảm thấy cuộc sống vô cùng vô cùng tốt, nhưng lại phát hiện ra tuy ngoài mặt Thời Phân luôn vui vẻ với mọi người, trêu chọc em gái nhưng ẩn giấu bên trong lại có những bí mật không ai ngờ...</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bạch Dục Sướng","avatar":""},{"name":"Triệu Kim Mạch","avatar":""},{"name":"Trương Tử Phong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
