INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-duc-va-do-thi', 'Tình Dục Và Đô Thị', 'Sex And The Metropolis', 'https://phimimg.com/upload/vod/20231211-1/a7510104d6f74e691261ef8ad99734fd.jpg', 'https://phimimg.com/upload/vod/20231211-1/57877bde97f2d97c9602ca41ad835ecf.jpg', '<p>Bộ phim kể về ba câu chuyện, tình yêu và thù hận của ba kiếp người. Lăn bụi đỏ, Sex and the City, ngày nào dàn dựng tình yêu nam nữ, vui buồn. Lập trình viên Xie Lang được yêu thích và ga lăng, và lọt vào tầm ngắm của trùm thế giới ngầm Macau, Huo Anna; Anna xinh đẹp, giản dị và kiêu ngạo, nhưng cô ấy bị rung động bởi sự thật nửa vời của Xie Lang, vì vậy việc nhặt một cô gái trở thành bong bóng, và cả hai thề rằng họ sẽ mãi mãi bên nhau. Tuy nhiên, sau một đêm hoan lạc, ông chủ đã cướp đi người con gái yêu của mình, để lại Tạ Lãng chỉ với nỗi sầu muộn vô tận.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tian Chuan","avatar":""},{"name":"Ge Yi","avatar":""},{"name":"Liu En Shang","avatar":""},{"name":"Bardie Bao","avatar":""},{"name":"Liu Chang","avatar":""},{"name":"Yang Xin","avatar":""},{"name":"Hua Liu","avatar":""},{"name":"Eliza","avatar":""},{"name":"Potting","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324394);
