INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-khong-thanh', 'Kế Hoạch Không Thành', 'Dead Heading', 'https://phimimg.com/upload/vod/20240102-1/c6d6393da1465a45f23d621b938471c2.jpg', 'https://phimimg.com/upload/vod/20240102-1/149270c54694f0918c59dc858dc448b5.jpg', '<p>Khi tiếp viên hàng không, Anna, đến London Heathrow sau chuyến bay đường dài từ New York, cô đã kiệt sức và cáu kỉnh khủng khiếp. Một phòng khách sạn nhạt nhẽo khác chỉ làm tăng thêm trạng thái cảm xúc ủ rũ của cô. Một cuộc gặp gỡ tình cờ với một người đàn ông đẹp trai trong quán bar làm vui vẻ buổi tối của cô và hai người nhanh chóng kết nối với nhau trong đêm. Khi Anna thức dậy vào sáng hôm sau, cô thấy mình đầy máu và người đàn ông bị sát hại dã man trên giường. Ai đã làm điều đó? Hoàn cảnh khiến cô rơi vào tình huống khó khăn để gọi cảnh sát, nhưng giờ cô sẽ làm gì? Làm thế nào để bạn thoát khỏi một cơ thể bị mắc kẹt trong phòng khách sạn? Anna sẽ chạy đua với thời gian để ghép các mảnh lại với nhau để khám phá ra một sự thật khủng khiếp. Cô ấy có thể không cô đơn!</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Annie Bootiman","avatar":""},{"name":"Emma Conway","avatar":""},{"name":"Jen Cunningham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
