INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thoat-hau-tan-the', 'Lối Thoát Hậu Tận Thế', 'Cargo', 'null', 'https://phimimg.com/upload/vod/20231211-1/68c8d1b5c70d89bd5a344452876ebce1.jpg', '<p>Giữa tình trạng bệnh dịch khủng khiếp, một người cha kiếm tìm khắp chốn hoang vu ở Úc với hy vọng có ai đó sẵn lòng bảo vệ và chăm sóc cô con gái nhỏ bé của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Martin Freeman","avatar":""},{"name":"Anthony Hayes","avatar":""},{"name":"Susie Porter","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
