INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-thoat-hau-tan-the', 'Lối Thoát Hậu Tận Thế', 'Cargo', 'lối thoát hậu tận thế cargo martin freeman anthony hayes susie porter ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kin', 'Kin', 'Kin', 'https://phimimg.com/upload/vod/20231211-1/9fdca89f5ecd8f7f4eec10fed5ea1366.jpg', 'https://phimimg.com/upload/vod/20231211-1/df89a418a094e282b30389b600353562.jpg', '<p>Kin là một bộ phim nói về sự phức tạp của cuộc sống, tình yêu và các mối quan hệ gia đình. Nhiều năm đã trôi qua kể từ khi cuộc sống của Yoke và Ella bị đảo lộn khi họ trở về với gia đình hợp pháp của mình sau khi bị tráo đổi khi mới sinh. Nhiều năm sau, Yoke dường như đã chấp nhận vai trò của mình là một Shelley có địa vị cao, có ý thức về địa vị, đảm nhận vai trò lãnh đạo trong công việc kinh doanh của gia đình. Ella đã chấp nhận số phận của mình với tư cách là một thành viên của gia đình Loh thuộc tầng lớp lao động, nhưng phải đấu tranh để tạo nên điều gì đó cho cuộc đời mình. Cuộc chiến tự nhiên và nuôi dưỡng đã diễn ra đúng hướng hay mối quan hệ giữa các gia đình vẫn căng thẳng và phức tạp hơn bao giờ hết? Lohs, Shelleys, Hassans và Balas đã vượt qua những mất mát cá nhân, sự giam giữ cũng như sự ghẻ lạnh của những người thân yêu của họ; nhưng căng thẳng kéo dài vẫn còn. Những bí ẩn tiếp tục mở ra khi các nhân vật theo đuổi các chương trình nghị sự cá nhân của họ, trong khi bộ phim tình cảm đầy dẫy khi những khúc quanh đáng ngạc nhiên được tiết lộ đe dọa sự ổn định mà họ…</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Rachel Wan","avatar":""},{"name":"Aaron Khaled","avatar":""},{"name":"Carla Dunareanu","avatar":""},{"name":"Jasmine Sim","avatar":""},{"name":"Jason Godfrey","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
