INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-thang-ay-toi-tung-theo-duoi-em', 'Năm Tháng Ấy Tôi Từng Theo Đuổi Em', 'You Are The Apple Of My Eye', 'https://phimimg.com/upload/vod/20231210-1/eb0a8340dea95be1bbc448f120e51b16.jpg', 'https://phimimg.com/upload/vod/20231210-1/adc1ca873f2bfa9efa512df6fcbd7a08.jpg', '<p>Sau 7 năm, những khán giả yêu thích bộ phim Cô Gái Năm Ấy Chúng Ta Cùng Theo Đuổi một lần nữa được thưởng thức lại câu chuyện này qua phiên bản mới - trong trẻo, lãng mạn không kém - dưới góc máy của những nhà làm phim Nhật Bản. Nội dung phim xoay quanh chuyện tình tuổi học trò của cặp đôi Kosuke Mizushima và Mana Hayase. Mặc dù mối quan hệ giữa hai người bắt đầu không phải quá tốt đẹp nhưng tuổi học trò của họ sẽ trở nên nhạt nhòa nếu như thiếu mất nhau. Để rồi khi thời gian trôi qua cùng với một số biến cố, liệu Mana Hayase và Kosuke Mizushima có thể cùng sánh vai đến cuối con đường?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuki Yamada","avatar":""},{"name":"Saito Asuka","avatar":""},{"name":"Honoka Matsumoto","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
