INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-hanh-tinh-xanh-cua-chung-ta', 'Đại Dương: Hành Tinh Xanh Của Chúng Ta', 'Oceans: Our Blue Planet', 'https://phimimg.com/upload/vod/20231210-1/09e5ad9b6458aa33a40ff3ee38ca3f61.jpg', 'https://phimimg.com/upload/vod/20231210-1/4663e5b025f83b0b1f714dfe83c7c121.jpg', '<p>Oceans: Our Blue Planet là một cuộc hành trình khám phá đầy huyền diệu, đưa khán giả đến những thế giới sâu thẳm, bí ẩn của các đại dương trên Trái Đất. Phim được dàn dựng với những cảnh tượng đầy kịch tính và kinh ngạc, bộ phim tiết lộ những câu chuyện chưa kể về những sinh vật đáng kinh ngạc nhất của đại dương.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kate Winslet","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324394);
