INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-duong-hanh-tinh-xanh-cua-chung-ta', 'Đại Dương: Hành Tinh Xanh Của Chúng Ta', 'Oceans: Our Blue Planet', 'đại dương: hành tinh xanh của chúng ta oceans: our blue planet kate winslet ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-dau-bi-nguyen-rua', 'Nàng Dâu Bị Nguyền Rủa', 'The Wrath', 'https://phimimg.com/upload/vod/20231211-1/4871fb746b41b442bd10afc57f384c59.jpg', 'https://phimimg.com/upload/vod/20231211-1/b7ab090adad306d8d683ab5a2ab156ba.jpg', '<p>Dựa trên truyền thuyết nổi tiếng từ thời xa xưa, The Wrath kể về bi kịch của gia tộc họ Lee - nhà có ba cậu con trai nhưng đều chết một cách bí ẩn vào đúng đêm tân hôn.Ok Bun (Son Na Eun thủ vai) bị bán đi làm hầu gái nhưng nhờ có vẻ ngoài xinh đẹp, cô lọt vào mắt xanh của cậu út nhà họ Lee. Đúng như lời nguyền, vào ngày cưới của cả hai thì tân lang qua đời, còn cô sống như góa phụ từ ấy.Ok Bun luôn phải chịu sự ghét bỏ của Shin (Seo Young Hee) - người đàn bà cai quản gia tộc này. Nhìn bề ngoài thì Shin có vẻ là người bình thường, tuy nhiên không ai biết bà ta đang giấu một bộ xương khô trong tủ quần áo.Kinh hoàng hơn, thể xác của Shin từ lâu đã bị một hồn ma chiếm giữ. Phải chăng nhân vật này chính là nguyên nhân của mọi đau thương đang diễn ra trong gia đình họ Lee?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Na-eun","avatar":""},{"name":"Seo Young Hee","avatar":""},{"name":"Lee Tae‑ri","avatar":""},{"name":"Son Sung Yoon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
