INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-bi-an', 'Vũ Khí Bí Ẩn', 'Kin', 'https://phimimg.com/upload/vod/20231211-1/0d1af91570c76f9046533e83bff59d97.jpg', 'https://phimimg.com/upload/vod/20231211-1/4ea4fea470f905f88062726874f8de9d.jpg', '<p>Vũ khí bí ẩn (tên gốc: Kin) là một bộ phim khoa học viễn tưởng (Sci-fi) kể về hành trình chạy trốn của một cậu bé da màu (14 tuổi) và người anh trai nuôi khỏi sự truy sát của một tên tội phạm khát máu và hai kẻ “giấu mặt”. Liệu họ có trốn thoát thành công khi tất cả hai anh em có chỉ là một vũ khí không rõ nguồn gốc? Và tình anh em sẽ trở thành gánh nặng hay giúp họ chiến thắng được kẻ thù?</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Myles Truitt","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Jack Reynor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324394);
