INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thay-ma-2018', 'Vùng Đất Thây Ma', 'ZOMBIE LAND SAGA', 'https://phimimg.com/upload/vod/20231219-1/763ce2079e875905fe2d5b7c3d009300.jpg', 'https://phimimg.com/upload/vod/20231219-1/30bf784e47eebfd4d472e9ffeb034bf4.jpg', '<p>Một buổi sáng vẫn như mọi khi. Một bản nhạc mọi khi vẫn nghe. Cũng vẫn là mình của mọi khi. Sự yên bình của bảy cô gái bỗng chốc sụp đổ. Một thế giới thây ma chết chóc và lươn lẹo, ... Một thế giới bước vào mà không được kháng cự, điều ước duy nhất của những cô gái đó ở thế giới thây ma giữa điều tốt nhất và tồi tệ nhất, đó là: Chúng tôi muốn được sống. Đây là một câu chuyện thần kỳ do các cô gái tạo nên..</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Abigail Breslin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324394);
