INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-voi-ngoi-im-tren-dat', 'Chú Voi Ngồi Im Trên Đất', 'An Elephant Sitting Still', 'https://phimimg.com/upload/vod/20231231-1/e87280d3ac4b211efd6bd27bc89e80fe.jpg', 'https://phimimg.com/upload/vod/20231231-1/e206bde67f801a3734676fa5713c9b69.jpg', '<p>Ở thành phố Manzhouli, miền bắc Trung Quốc, họ nói rằng có một con voi chỉ đơn giản là ngồi và phớt lờ thế giới. Manzhouli trở thành nỗi ám ảnh đối với các nhân vật chính của bộ phim này, một người khao khát thoát khỏi vòng xoáy đi xuống mà họ tìm thấy chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Peng Yuchang","avatar":""},{"name":"Wang Yuwen","avatar":""},{"name":"Zhang Yu","avatar":""},{"name":"Congxi Li","avatar":""},{"name":"Zhenghui Ling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
