INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-hoa-nhu-ca', 'Liệt Hỏa Như Ca', 'Liehuo Ruge', 'https://phimimg.com/upload/vod/20231219-1/9f7af7a291316b5235c607d53d27ab8c.jpg', 'https://phimimg.com/upload/vod/20231219-1/964c22b71f5aa4148a93e06a95d512d2.jpg', '<p>Liệt hỏa như ca 2017 được chuyển thể từ cuốn tiểu thuyết cùng tên của tác giả Minh Hiểu Khê. Phim có nội dung kể về một vị tiểu thư Liệt Như Ca (Địch Lê Nhiệt Ba) - người thừa kế sơn trang mang tên Liệt Hỏa. Liệt Như Ca có mối quan hệ tình cảm với cả 3 người đàn ông là Ngân Tuyết - Chiến Phong (Trương Bân Bân) - Ngọc Tự Hàn (Lưu Nhuế Lân). Họ cùng trải qua hoạn nạn, nếm trải những dư vị cảm xúc yêu ghét giận hờn đan xen oán thù gia tộc.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 17, 2018, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Du Dân","avatar":""},{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Trương Bân Bân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324394);
