INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-chien-luoc-tuong-lai-yg', 'Phòng Chiến Lược Tương Lai YG', 'YG Future Strategy Office', 'https://phimimg.com/upload/vod/20231219-1/af44e5e5e9ec9a5ad976ad51afee2ae6.jpg', 'https://phimimg.com/upload/vod/20231219-1/5ce19c431ddd6f1826c995f57d857896.jpg', '<p>Ngôi sao K-pop Seungri, thành viên trẻ nhất của BIGBANG, tìm cách dẫn dắt đội ngũ nhân viên vụng về tại Phòng Chiến lược Tương lai YG trong loạt phim hài dí dỏm này.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seungri","avatar":""},{"name":"Yoo Byung Jae","avatar":""},{"name":"Lee Jai Jin","avatar":""},{"name":"Jinu","avatar":""},{"name":"Son Se Bin","avatar":""},{"name":"Kim Ga Eun","avatar":""},{"name":"Park Chung Hwan","avatar":""},{"name":"Baek Yeong Gwang","avatar":""},{"name":"Choi Sin Deuk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
