INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-duoi-bau-troi-u-am', 'Cười Dưới Bầu Trời U Ám', 'Laughing Under The Clouds', 'https://phimimg.com/upload/vod/20231231-1/46070bebb4abbe684ce931f9223038d2.jpg', 'https://phimimg.com/upload/vod/20231231-1/da108fa445378bcfc9dfd08e6a8a128d.jpg', '<p>Vào buổi bình minh của thời kỳ Minh Trị, Gokumonjou, một nhà tù không thể trốn thoát, đã được thành lập giữa một hồ nước khổng lồ để chống lại tỷ lệ tội phạm tăng vọt mà kỷ nguyên mới mang lại. Phục vụ như những người lái đò là anh em nhà Kumou nổi tiếng: người đứng đầu gia đình lập dị, Tenka; con trai thứ hai liều lĩnh nhưng cao quý, Soramaru; và đứa trẻ ngây thơ nhất, Chuutarou. Bất chấp công việc nghiệt ngã của họ, cả ba có cuộc sống tương đối yên bình ở thị trấn Oumi nhiều mây, cùng với quản gia của họ, Shirasu Kinjou. Nhưng bị chôn vùi trong lịch sử lâu đời của Oumi là truyền thuyết về Orochi đáng sợ, một con thú ngoằn ngoèo thức dậy ba trăm năm một lần trong một vật chứa của con người. Soramaru và Chuutarou không hề hay biết, công việc thực sự của gia tộc Kumou là phong ấn Orochi trước khi nó hồi sinh hoàn toàn—nếu không thế giới sẽ bị hủy diệt. Giữa lần hồi sinh tiếp theo của con quái vật, gia đình Kumou phải tìm ra giải pháp để tiếp tục cười dưới mây.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sota Fukushi","avatar":""},{"name":"Shunsuke Daitoh","avatar":""},{"name":"Renn Kiriyama","avatar":""},{"name":"Yuma Nakayama","avatar":""},{"name":"Kirato Wakayama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
