INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xau-nu-chung-vo-diem', 'Xấu Nữ Chung Vô Diệm', 'The Ugly Queen', 'https://phimimg.com/upload/vod/20231219-1/156f72f45ae1ad3f7274ccc56f7dc963.jpg', 'https://phimimg.com/upload/vod/20231219-1/3cb916cfec6f2a3f127b65fc7da2584b.jpg', '<p>Phim Xấu Nữ Chung Vô Diệm - The Ugly Queen 2018: Lấy bối cảnh thời Xuân Thu Chiến Quốc, các nước chư hầu phân tranh. Trong số bảy nước mạnh, Tề quốc được coi như là quốc gia mạnh nhất. Tề Uy Vương băng hà, truyền lại ngôi cho Tề Tuyên Vương. Tề Tuyên Vương trầm mê tửu sắc, không quan tâm đến chính sự quốc gia. Ngọc Hoàng Đại Đế có bảy người con gái, trong đó Lục công chúa xinh đẹp lương thiện, thương xót lê dân bách tính, quyết tâm hạ phàm để cứu vớt bách tích khỏi khổ nạn lầm than. Nhưng nàng không thể hạ phàm với thân phận tiên nữ, đành phải đội lên mình vỏ bọc ngoại hình của Dạ Xoa mới có thể hạ phàm giúp đỡ dân chúng. Nàng đầu thai ở Chung Li thôn – một vùng rừng núi rộng lớn, nên lấy tên là Chung Li Vô Diệm. Vì ngoại hình xấu xí, da xanh ngắt, tóc xấu, từ nhỏ ít có người lại gần nàng. Nàng lại yêu thích học săn bắt tập võ, học chữ. Nàng trở thành một người tài giỏi, trên thông thiên văn dưới tường địa lý. Sau này, nàng trở thành hoàng hậu của Tề Tuyên Vương, giúp vua Tề chú tâm hơn đến việc trị quốc. Thời Tề Tuyên Vương tại vị, không có nước nào đến xâm lăng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Hải Thành","avatar":""},{"name":"Diêm Lập Phi","avatar":""},{"name":"Hách Văn Đình","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
