INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-sau-phong-kin', 'Tội Ác Sau Phòng Kín', '10x10', 'https://phimimg.com/upload/vod/20231211-1/d9f96850a7a22360998ad9d3f3e9f469.jpg', 'https://phimimg.com/upload/vod/20231211-1/3a3d4e6506cfb9664d7e326196d6fbfa.jpg', '<p>Lewis trông có vẻ như là một anh chàng bình thường trong mắt mọi người nhưng thực chất anh đang che dấu kế hoạch bắt cóc của mình, đối tượng là một người phụ nữ tên Cathy. Sau khi lên kế hoạch tỉ mỉ, Lewis đã bắt được Cathy và giam cô ấy trong căn phòng bí mật trong nhà anh. Căn phòng này được cách âm đến 10 feet, cũng từ đây những bí mật từ quá khứ của Cathy được hé lộ. Tuy nhiên, mọi chuyện không chỉ dừng lại ở đó, Cathy không hề đơn giản như cách mà mọi người biết về cô.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Luke Evans","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"Noel Clarke","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
