INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('unfriended-dark-web', 'Unfriended: Dark Web', 'Unfriended: Dark Web', 'https://phimimg.com/upload/vod/20231211-1/9e10695b2e3ed72067137aeb3262a664.jpg', 'https://phimimg.com/upload/vod/20231211-1/33459c1dcc3d97230b989bf9cb76cec8.jpg', '<p>Kể câu chuyện về một thiếu niên thuộc sở hữu của một máy tính xách tay mới và thấy rằng nó có thể đã bị đánh cắp. Ông phát hiện ra chủ sở hữu trước đó có thể đang theo dõi mọi động thái mà anh ta thực hiện và sẽ làm bất cứ điều gì để lấy lại.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
