INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-trong-can-nha', 'Tội Ác Trong Căn Nhà', 'Bad Samaritan', 'https://phimimg.com/upload/vod/20231211-1/976f9b5b3cce3da1da9ca80e2e7ffd49.jpg', 'https://phimimg.com/upload/vod/20231211-1/f5d7db514b80dc2278249ae8687b9cab.jpg', '<p>Sean và Derek, hai nhân viên đỗ xe tại một nhà hàng đã bày ra một chiêu lừa đảo tinh quái nhằm mục đích trộm tài sản của các khách hàng giàu có. Mọi việc diễn ra suôn sẻ cho đến khi đối tượng tiếp theo lọt vào tầm ngắm của họ là một tên giết người hàng loạt.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Tennant","avatar":""},{"name":"Robert Sheehan","avatar":""},{"name":"Kerry Condon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
