INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-phi-gia-dao', 'Manh Phi Giá Đáo', 'Mengfei Comes Across', 'https://phimimg.com/upload/vod/20231203-1/dbeaff9a74f5be2158c9471cf1b0a820.jpg', 'https://phimimg.com/upload/vod/20231203-1/c6911ef83ebc3dbab1e409dcbdccdf45.jpg', '<p>Bộ Manh (Kim Thần đóng) bước vào chốn thâm cung vào thời kỳ Tùy Đường. Không muốn sống cuộc đời giam lỏng, số phận bị định đoạt, Bộ Manh giả vờ bị bệnh để tránh chuyện chính trị và làm bạn tốt với các phu nhân quan lại trong cung điện. Nhưng rồi một ngày, hoàng đế (Uông Đông Thành đóng) có xung đột với cha của Bộ Manh, chàng tìm đến nàng để trút giận. Tuy nhiên, chàng thấy mình ngày càng bị thu hút bởi Bộ Manh. Với cá tính không chịu khuất phục của nàng, vị hoàng đế không những giận thêm mà còn thương nhớ, chàng thường tạo cớ để 2 người có cơ hội bên nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 18, 2018, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Kim Thần","avatar":""},{"name":"Uông Đông Thành","avatar":""},{"name":"Hàn Cửu Nặc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
