INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-dong-vat-phan-3', 'Vương Quốc Động Vật (Phần 3)', 'Animal Kingdom (Season 3)', 'https://phimimg.com/upload/vod/20231203-1/8adea37fc2f3d1316976b8d49ae9fbf4.jpg', 'https://phimimg.com/upload/vod/20231203-1/26bb97c74614a70d7ad51dfdd9ac71fc.jpg', '<p>Gia đình Cody gần như suy sụp khi J nắm quyền sau mất mát lớn, bà Smurf bị tống giam và sự tái xuất hiện của một thành viên gia đình đã xa cách từ lâu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ellen Barkin","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Shawn Hatosy","avatar":""},{"name":"Ben Robson","avatar":""},{"name":"Jake Weary","avatar":""},{"name":"Finn Cole","avatar":""},{"name":"Daniella Alonso","avatar":""},{"name":"Molly Gordon","avatar":""},{"name":"Carolina Guerra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
