INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nang-nguoi-me', 'Bản Năng Người Mẹ', 'Breaking In', 'https://phimimg.com/upload/vod/20231210-1/6ecfa3029626c49bb09cfa588d3ab082.jpg', 'https://phimimg.com/upload/vod/20231210-1/bad8ec7dd51a4dc3275bba3229134c3d.jpg', '<p>Sau vụ giết người của cha mình, Shaun Russell đi đến nhà, cô lớn lên cùng với hai đứa con, con gái Jasmine và Son Glover. Shaun dự định giải quyết bất động sản của cha mình và bán nhà ở vị trí từ xa, có nhiều tính năng bảo mật, bao gồm cả một màn hình từ xa cầm tay. Hệ thống an ninh là không trực tuyến khi đến nơi, nhưng đã sớm được kích hoạt lại bởi hoa nhài. Không biết đến gia đình, bốn tội phạm - Peter, Sam, Duncan và nhà lãnh đạo của họ Eddie - đã ở trong nhà. Jasmine và Glover được lấy con tin trong khi Shaun ở bên ngoài. Peter đuổi theo Shaun vào rừng, nơi cô ấy quản lý để bất tỉnh. Cô để anh ta bị ràng buộc và bịt miệng, và sử dụng liên lạc để gọi ngôi nhà. Eddie nói với cô ấy rằng họ chỉ đến nơi an toàn và 4 triệu đô la họ tin là bên trong; Isaac đang được điều tra và Sam đã học được rằng ông thanh lý tài sản của mình. Phi hành đoàn chỉ có 90 phút kể từ khi họ cắt đường dây điện thoại trước khi công ty bảo mật sẽ liên hệ với cảnh sát, vì vậy họ muốn tìm nó và rời đi nhanh chóng. Che giấu trong những tán cây, Shaun nhìn thấy Maggie, người môi giới, đến với giấy tờ để bán nhà. Eddie chào đón cô ở cửa, giải thích về Shaun đã đi vào thị trấn một cách nhanh chóng, và mời cô vào. Maggie thông báo ví của Shaun trên bàn đằng sau Eddie và từ chối. Khi Maggie đang rời đi, Duncan tấn công và khuất cổ họng, làm đảo lộn Eddie, vì nó có nghĩa là Shaun sẽ không thể kiểm soát được ..</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
