INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-hai-nguoi-hung', 'Học Viện Anh Hùng: Hai Người Hùng', 'My Hero Academia: Two Heroes', 'https://phimimg.com/upload/vod/20231210-1/91f097f385f6fc90a59071376f827dc6.jpg', 'https://phimimg.com/upload/vod/20231210-1/155bb89fe47e0d59fa7227c0aef2cde6.jpg', '<p>Sau ba tác phẩm nổi tiếng “One Piece”, “Naruto” và “Bleach”, “Học Viện Anh Hùng Của Tôi” trở thành truyện tranh trụ cột với “Tuần san Shonen Jump” trong 10 năm gần đây, đã tạo nhiều thành tích tuyệt vời tại nhiều nơi như Nhật Bản, Mỹ, Trung Quốc, v.v... và được nhiều người chú ý. “Học Viện Anh Hùng Của Tôi” kể về cuộc hành trình một người thiếu niên không có siêu năng trưởng thành anh hùng trong thế giới tương lai nhiều người có siêu năng. Là bộ phim điện ảnh đầu tiên của tác phẩm này, bộ phim này đã giành thành tích xuất sắc tại nước ngoài. Còn bộ phim này kể về câu chuyện thanh xuân chiến đấu vừa giản đơn vừa mãnh liệt: nhân vật chính Midoriya Izuku và thầy giáo All Might cùng nhau chiến đấu với kẻ địch. Bộ phim này không những thừa kế đặc trưng của truyện tranh thiếu niên nhiệt huyết truyền thống, mà còn mạnh dạn sáng tạo.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Daiki Yamashita","avatar":""},{"name":"San Zhai Jian Tai","avatar":""},{"name":"Mirai Shida","avatar":""},{"name":"Namase Katsuhisa","avatar":""},{"name":"Okamoto Nobuhiko","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Yûki Kaji","avatar":""},{"name":"Masuda Toshiki","avatar":""},{"name":"Hirohashi Ryou","avatar":""},{"name":"Ryoh Hirohashi","avatar":""},{"name":"Ryo Hirohashi","avatar":""},{"name":"Zai Zhong You","avatar":""},{"name":"Inoue Marina","avatar":""},{"name":"Kei Shindou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324394);
