INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-cun-cung', 'Biệt Đội Cún Cưng', 'Show Dogs', 'https://phimimg.com/upload/vod/20231210-1/5a9f80cdb870a6f9c71cecf34905fd97.jpg', 'https://phimimg.com/upload/vod/20231210-1/b3bfcfe70962b52c09fe8d2d2f1b03a2.jpg', '<p>Biệt Đội Cún Cưng là câu chuyện xoay quanh hành trình phá án của Max và người bạn đặc biệt – một chú chó có khả năng suy luận vô cùng tài tình. Theo đó, Max đang điều tra về một vụ bắt cóc gấu trúc. Để hoàn thành nhiệm vụ, anh và chú chó phải thâm nhập vào lễ hội cún cưng Canini. Tại đây, cả đội trải qua nhiều thử thách oái ăm, dở khóc dở cười để bắt được kẻ chuyên buôn bán động vật bất hợp pháp thực sự. Một chú chó cảnh sát và cộng sự là con người đang điều tra về một nhóm tội phạm. Chúng lợi dụng 1 chương trình về chó để thực hiện phi vụ phi pháp của minh. Liệu Max và các cộng sự có phá được vụ án khó nhằn này? Liệu chuyện gì sẽ xảy ra?</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Arnett","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Natasha Lyonne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324394);
