INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-nho-doi', 'Chuyến Đi Nhớ Đời', 'Staycation', 'https://phimimg.com/upload/vod/20231227-1/d04672f2d2b21e1b1a7f561e6a7a2352.jpg', 'https://phimimg.com/upload/vod/20231227-1/d09227773958ab3fbe3b7b4c703690b2.jpg', '<p>Chuyến Đi Nhớ Đời - Staycation là bộ phim hài hước kể về chuyến đi nhớ đời của gia đình A Cường. Cả gia đình may mắn trúng một chuyến du lịch, nhưng đời không như là mơ. Trong chuyến đi ấy, có biết bao câu chuyện xảy đến với từng thành viên trong gia đình của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":" Chin Siu Ho","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Andrew Lam","avatar":""},{"name":"Johnson Lee","avatar":""},{"name":"Louisa So","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
