INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chet-de-hoi-sinh', 'Chết Để Hồi Sinh', 'Dying To Survive', 'https://phimimg.com/upload/vod/20231209-1/0f8596425aa27691f9d52b0b603015b3.jpg', 'https://phimimg.com/upload/vod/20231209-1/7c43efb551b60b3c56fe5b2b3a2ef68c.jpg', '<p>Dying to Survive quy tụ dàn diễn viên Từ Tranh, Chu Nhất Vi, Vương Truyền Quân, Đàm Trác, kể chuyện một chủ cửa hàng mắc nợ lớn, liều lĩnh tổ chức đường dây nhập thuốc Ấn Độ giá rẻ vào Trung Quốc. Anh đổi đời, được các bệnh nhân tôn sùng như thần thánh nhưng gặp rắc rối với luật pháp. Kịch bản dựa trên câu chuyện có thật về một thương gia mắc bệnh ung thư được xem như người hùng khi đưa thuốc từ Ấn Độ về Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zheng Xu","avatar":""},{"name":"Wang Chuanjun","avatar":""},{"name":"Yu Zhang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
