INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-hang-khang-chien', 'Ngân Hàng Kháng Chiến', 'The Resistance Banker', 'https://phimimg.com/upload/vod/20231210-1/a85d8632fbe04402ecc29ecf42a0d67b.jpg', 'https://phimimg.com/upload/vod/20231210-1/7c9726e5f5a759ed18effae6a6c2d262.jpg', '<p>Một nhân viên ngân hàng ở Amsterdam đã mạo hiểm cả gia đình và tương lai để thành lập một ngân hàng bí mật nhằm tiếp viện cho kháng chiến và cản bước quân Quốc xã.</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Barry Atsma","avatar":""},{"name":"Jacob Derwig","avatar":""},{"name":"Pierre Bokma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
