INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-nhung-dai-duong', 'Giữa Những Đại Dương', 'Submergence', 'https://phimimg.com/upload/vod/20231210-1/212e80babbd06194c2df64cbfc444402.jpg', 'https://phimimg.com/upload/vod/20231210-1/c6c16614dd47341533742b17471bf541.jpg', '<p>Được chuyển thể từ cuốn tiểu thuyết lãng mạn nhưng không kém phần hiện thực, tàn khốc, “Giữa Những Đại Dương” được kể thông qua hồi ức của James, chàng điệp viên người Anh đang bị bọn khủng bố giam giữ, tra tấn; và Danielle, nữ khoa học gia đang lặn hàng nghìn mét dưới đáy biển cho công việc nghiên cứu của mình. Giữa muôn vàn hiểm nguy và cách trở, những kỉ niệm tươi đẹp bỗng trở thành điểm tựa, niềm hi vọng le lói giúp họ tồn tại. Họ nhớ về lần đầu gặp gỡ, trên một bờ biển thơ mộng ở miền Tây nước Pháp…</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Alexander Siddig","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324394);
