INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-san-nguoi', 'Quỷ Săn Người', 'It Comes', 'https://phimimg.com/upload/vod/20231208-1/3efd36e6d0952f3fb2c4526f31c79449.jpg', 'https://phimimg.com/upload/vod/20231208-1/bcafa25891cc45fc4b5b4c458cbf7905.jpg', '<p>Cuộc sống có vẻ hoàn hảo cho Hideki sống với người vợ xinh đẹp của mình trong căn hộ ngoại ô mới của mình. Một ngày nọ, anh được một đồng nghiệp gọi rằng một du khách đến gặp anh tại văn phòng của mình. Khi anh ta đến quầy lễ tân, Hideki đang bối rối khi biết rằng khách truy cập đã rời đi một bản ghi nhớ về tên của con gái chưa sinh của mình là Chisa. Hai năm sau, đồng nghiệp đã chết một cách bí ẩn và nhà của Hideki bị tấn công bởi một sự hiện diện độc ác. Để bảo vệ gia đình, Hideki yêu cầu sự giúp đỡ từ một nhà báo Nozaki và một nhà xuất bản uy tín, người thực hiện một nghi thức để phá vỡ một câu thần chú không xác định. Nhưng họ đến để tìm hiểu những gì họ đang đối phó là vượt quá trí tưởng tượng của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
