INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yuuna-o-nha-tro-yuragi', 'Yuuna Ở Nhà Trọ Yuragi', 'Yuuna of Yuragi Manor', 'https://phimimg.com/upload/vod/20231207-1/1e9b543d41c63fc734faa0bf0dbfc76d.jpg', 'https://phimimg.com/upload/vod/20231207-1/15258160b4bab7ced786d08fc33b1cb7.jpg', '<p>Từng là một nhà nghỉ suối nước nóng nhưng nay đã trở thành nhà trọ với giá thuê cực kì rẻ, Nhà Trọ Yuragi hầu như bị bỏ hoang và chỉ có vài khách trọ đặc biệt. Nơi đó được đồn đại là bị ma ám nên hầu như chẳng ai dám đến thuê trọ. Nhưng vì thế nên nơi đó lại là lựa chọn hoàn hảo cho Fuyuzora Kogarashi, một nhà ngoại cảm nghèo mạt cần một mái nhà để che thân và những con ma để trục xuất. Kogarashi đã sẵn sàng để đối mặt với con ma được đồn đại nhưng hóa ra con ma đó không hề tà ác như lời đồn mà là Yuuna, một hồn ma thiếu nữ xinh đẹp với mái tóc bạc đã quên hết mọi chuyện trước khi cô chết. Bất ngờ với Kogarashi hơn nữa là những khách trọ khác của Nhà Trọ Yuragi không chỉ cũng nhìn thấy được Yuuna như cậu mà họ đều có những khả năng siêu nhiên của riêng mình. Dù phải đối mặt với nhiều rắc rối vì những bạn trọ đặc biệt của mình, Kogarashi vẫn quyết tâm tìm ra điều nuối tiếc của Yuuna khiến cô chưa thể siêu thoát nhằm giúp cô không trở thành ác ma và bị đày xuống Địa Ngục.</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
