INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-nha-ma', 'Bí Mật Nhà Ma', 'Buyer Beware', 'https://phimimg.com/upload/vod/20231208-1/71b129e985805e7f358d10a61a7e971e.jpg', 'https://phimimg.com/upload/vod/20231208-1/ac9e07553ea2300c0819f02ca1a51af8.jpg', '<p>Phim Bí Mật Nhà Ma - Buyer Beware 2018 : Chuyện phim xoay quanh một công ty chuyên thu mua đồ vật của những người chết bất đắc kỳ tử để đem bán lại với mức giá cao ngất. Các linh hồn oan khuất cũng vì thế phẫn nộ mà trở về đeo bám những con người bất tuân</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Carlos Chan","avatar":""},{"name":"Carmen Tong","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
