INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bok-soo-tro-ve', 'Bok Soo Trở Về', 'My Strange Hero', 'https://phimimg.com/upload/vod/20231207-1/dcca89ceb930d565a6e6f7e3aabd1733.jpg', 'https://phimimg.com/upload/vod/20231207-1/fff904ca94e0a6faa475f385f4883e6b.jpg', '<p>Phim kể về anh chàng Kang Bok Soo, người có quá khứ từng bị đuổi học vì vướng tội danh bạo lực học đường. Về sau, anh trở lại với tư cách giáo viên, quyết tâm trả thù những kẻ năm xưa đã vu oan hãm hại mình, nhưng rồi sau đó vô tình bị cuốn vào những sự kiện bất ngờ. Nữ chính Jo Bo Ah sẽ vào vai Son Soo Jung, mối tình đầu khó quên của Kang Bok Soo. Jo Bo Ah / Kim Dong-Young / Kwak Dong Yeon / Park Ah-In / Yoo Seung Ho /</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jo Bo Ah","avatar":""},{"name":"Kim Dong-Young","avatar":""},{"name":"Kwak Dong Yeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
