INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ca-cuoc', 'Học Viện Cá Cược', 'Kakegurui Live-Action', 'https://phimimg.com/upload/vod/20231207-1/562ffb4c0254eedc570dc662cdffd4f4.jpg', 'https://phimimg.com/upload/vod/20231207-1/504187ce4ad9d30b538ebdf031b125f7.jpg', '<p>Phim Học Viện Cá Cược - Kakegurui Live-Action 2018: Hyakkaou Academy, một học viện danh giá. Ở trong học viện này, học sinh được chia thành các tầng lớp xã hội khác nhau. Nhưng đứng trên tất cả những người khác đó là Hội học sinh - Những người cai trị trên các học sinh, sinh viên bằng những Trò Chơi Cờ Bạc của họ. Đó sẽ là thiên đường nếu bạn giành chiến thắng, còn nếu bạn bị mất tất cả: Địa Ngục. Sử dụng thành thạo các mưu kế khi chơi đó là niềm ao ước của các học sinh, tuy vậy những kẻ đứng hàng thấp nhất, hay còn gọi là PET, sẽ phải chịu đựng những sự điên rồ mà lũ học sinh quái thai này mang lại. Nhưng có một cô gái mới chuyển tới học viện này, tên cô ấy là Jyabami Yumeko!</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Natsumi Okamoto","avatar":""},{"name":"Yurika Nakamura","avatar":""},{"name":"Mahiro Takasugi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
