INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-manh-ba', 'Truyền Thuyết Mạnh Bà', 'The Ferry Man Manjusaka', 'https://phimimg.com/upload/vod/20231208-1/d668b1b582f6b03741a376453573356b.jpg', 'https://phimimg.com/upload/vod/20231208-1/2fd722424202792756e59bcdaa2632bb.jpg', '<p>Tương truyền để được đầu thai các hồn ma phải đến Mạnh Bà Trang và uống canh Mạnh Bà. Tam Thất thân là người cai quản nơi đây, thế nhưng từ bé lại xấu xí, đần dộn đã thế còn nấu canh cực kỳ khó nuốt. Vì vây, đã 600 tuổi nhưng Tam Thất vẫn chưa có ý trung nhân, cho đến khi gặp được Trường Sinh đến từ nhân gian</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Hoa","avatar":""},{"name":"Vu Nghị","avatar":""},{"name":"Vương Thụy Xương","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324394);
