INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-biet-stella', 'Từ Biệt Stella', 'Stella''s Last Weekend', 'https://phimimg.com/upload/vod/20231208-1/727342c624073af1f35651860f645b08.jpg', 'https://phimimg.com/upload/vod/20231208-1/950032aac07c355ef4a7a2d037d4deae.jpg', '<p>Jack trở về nhà để cùng mẹ và cậu em trai Oliver tiễn đưa con chó già Stella yêu quý của họ. Trong khi người mẹ lên kế hoạch cho một bữa tiệc cảm động để kỷ niệm cuộc đời của Stella, Jack và Oliver phát hiện ra cả hai đều yêu cùng một cô gái. Vào một cuối tuần đặc biệt, tình anh em của họ sẽ được thử thách bằng cả tình yêu và sự mất mát.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Wolff","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Polly Draper","avatar":""},{"name":"Paulina Singer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
