INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-thanh-ansi', 'Đại Chiến Thành Ansi', 'The Great Battle', 'https://phimimg.com/upload/vod/20231208-1/e6ac3ba09388d0961654ad4b9678ce12.jpg', 'https://phimimg.com/upload/vod/20231208-1/8fc6d772247d4350a346a0b72b21bdfa.jpg', '<p>Cuộc chiến kéo dài 88 ngày đêm giữa quân đội Goguryeo và quân xâm lược nhà Đường để bảo vệ thành chiến Ansi. Một cuộc chiến không cân sức tưởng chừng như đã có kết quả an bài, nhưng kết cục lại không ai ngờ tới và được ghi danh vào sử sách như một trận đánh tiêu biểu cho tinh thần chiến đấu mãnh liệt.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jo In-sung","avatar":""},{"name":"Nam Joo-hyuk","avatar":""},{"name":"Park Sung-woong","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324394);
