INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-aotu-phan-2', 'Thế Giới Aotu (Phần 2)', 'Aotu World (Season 2)', 'https://phimimg.com/upload/vod/20231207-1/d1cafd342d0a6dc0ee831e107a052381.jpg', 'https://phimimg.com/upload/vod/20231207-1/b52e8f4fd447cf6da9f1b75c1953ba46.jpg', '<p>Người tạo ra thế giới Aotu là một vị thần tự do và giản dị, người đã tạo ra các hành tinh và sau đó cai trị con người trong Thế giới tự động. Thần cho một số hành tinh trở nên giàu có và lộng lẫy, một số hành tinh lại nghèo và hoang vắng, một số người thích tự do và hạnh phúc trong khi những người khác chịu cảnh nô lệ thuế nặng. Thần đặt Bảy Linh vật để thực hiện mệnh lệnh của mình cho thần. Tuy nhiên, thần cũng cho người dân của mình cơ hội - nếu bất cứ ai muốn thay đổi vận mệnh và thực hiện ước mơ của mình, họ có thể tham gia Trò chơi Aotu! Người tham gia sẽ nhận được các khả năng đặc biệt của người dùng khác từ hệ thống trò chơi và rèn luyện khả năng liên tục thách thức các trạm kiểm soát. Miễn là bạn có được chiến thắng cuối cùng trong cuộc thi của Aotu, bạn sẽ có được mọi thứ, cũng như quyền hạn như Bảy Linh vật. Tuy nhiên, tất cả những điều này không đơn giản như vậy.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 15, 2018, 'Thuyết Minh', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
