INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-papa-da-con-gai', 'Hồn Papa Da Con Gái', 'Daddy Issues', 'https://phimimg.com/upload/vod/20231210-1/6b805c658d912ca14ad8f3396ea766e4.jpg', 'https://phimimg.com/upload/vod/20231210-1/a233147863b61a36ae5c7c04c014bc86.jpg', '<p>Với mong muốn hai cha con có thể thân thiết và hiểu nhau hơn, linh hồn của người mẹ đã thực hiện một lời nguyền khiến họ bị tráo đổi. Họ sẽ phải đối mặt với những tình huống oái ăm, trớ trêu như thế nào trong thời gian 7 ngày? &nbsp;Hồn Papa, Da Con Gái kể về câu chuyện của hai cha con Hải (Thái Hòa) và Châu (Kaity Nguyễn). Mặc dù là người một nhà nhưng mối quan hệ của họ ngày càng trở nên xa cách vì nếu như Châu là nữ sinh học giỏi nổi tiếng nhất trường, thì Hải lại là người cha ham chơi chỉ biết dựa dẫm vào con gái. &nbsp;Để có thể khắc phục tình trạng này, linh hồn người mẹ đã thực hiện một lời nguyền, khiến hai cha con bị hoán đổi với nhau trong vòng 7 ngày.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Thái Hòa","avatar":""},{"name":"Kaity Nguyễn","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Kathy Uyen","avatar":""},{"name":"Trang Hý","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324394);
