INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-xuc-cam', 'Tìm Lại Xúc Cảm', 'Dry Martina', 'https://phimimg.com/upload/vod/20231208-1/a9915f4be6f239f18c6d1fe682c528db.jpg', 'https://phimimg.com/upload/vod/20231208-1/4c5963a75c309f16abce260006b486c7.jpg', '<p>Cuộc gặp gỡ lạ lùng với người hâm mộ và cuộc hẹn hò với bạn trai cũ của người đó đã đưa đẩy một ca sĩ đến với cuộc phiêu lưu ái tình trong câu chuyện về dục vọng ở Chile.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Antonella Costa","avatar":""},{"name":"Patricio Contreras","avatar":""},{"name":"Geraldine Neary","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
