INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-phan-nghiet-nga', 'Số Phận Nghiệt Ngã', 'Pimp', 'https://phimimg.com/upload/vod/20231208-1/9eb2ee36d79cbc5548c7dfdf0d8887c9.jpg', 'https://phimimg.com/upload/vod/20231208-1/ef98895bfb21a1f11746f891980d3663.jpg', '<p>Sinh ra trong tầng lớp thế giới ngầm, để tồn tại cuộc sống của Thứ Tư (Keke Palmer) như một trò chơi mạo hiểm, tiền và súng đạn. Đối thủ xuất hiện, buộc cô phải bước vào một trận chiến đường phố dữ dội để giành quyền lực bảo vệ người mẹ làm gái điếm và người yêu.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
