INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-giet-duong', 'Kế Hoạch Giết Dượng', 'Thoroughbreds', 'https://phimimg.com/upload/vod/20231208-1/30517346d3476f77abf5b415643a4e3b.jpg', 'https://phimimg.com/upload/vod/20231208-1/09d087923ae7fe3b72d9ddc010386e9e.jpg', '<p>Thoroughbreds là bộ phim giật gân-chính kịch kể về hai cô gái tên Lily và Amanda con nhà gia đình khá giả ở Connecticut (thủ vai bởi Olivia Cooke và Anya Taylor-Joy). Hai nàng đã nhen nhóm lại ngọn lửa tình bạn của nhau và quyết định hợp tác lập ra một kế hoạch hiểm ác để… giết bố dượng của mình. Cùng với sự giúp đỡ của gã buôn ma túy địa phương là Tim (thủ vai bởi Anton Yelchin), Thoroughbreds dõi theo câu chuyện kì lạ, tăm tối nhưng cũng rất thú vị đặt bối cảnh vùng ngoại ô nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olivia Cooke","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Anton Yelchin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324394);
