INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-xe-dai-chien', 'Siêu Xe Đại Chiến', 'Wheely', 'https://phimimg.com/upload/vod/20231208-1/d730ff21fd761e393e474392c4be7f49.jpg', 'https://phimimg.com/upload/vod/20231208-1/b2f86355904854f23836b57e4bd1ae22.jpg', '<p>Sau bi kịch sự nghiệp, Wheely giã từ đường đua và trở thành tài xế lái taxi để kiếm sống qua ngày. Wheely còn hứa với mẹ không bao giờ đua xe nữa. Thế nhưng mọi chuyện đã đổ sông đổ bể khi Wheely gặp Bella - cô siêu mẫu của giới siêu xe. Với trái tim đã thuộc về nàng, Wheely bắt đầu tính kế quay lại đội đua.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Barbara Goodson","avatar":""},{"name":"Chris Jai Alex","avatar":""},{"name":"Ogie Banks","avatar":""},{"name":"Brock Powell","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324394);
