INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-tac', 'Hà Tặc', 'The River Pirates', 'https://phimimg.com/upload/vod/20231219-1/6c006e86745502ca58579807907f1a69.jpg', 'https://phimimg.com/upload/vod/20231219-1/9613b2063d46dd721d4b174a096aa8c6.jpg', '<p>Triều đình rối ren, kẻ thù tìm cách đánh cắp khuôn đúc tiền để làm loạn. Thừa cơ khôn đúc được hộ tống tới kinh thành, bọ hà tặc sông Hán Thủy đã cướp nó đi. Trong lúc vui mừng quá khích, chúng lại bị một kỹ nữ đánh cắp và giấu khuôn đúc vào nhà một thợ đúc bạc. Nhằm lấy lại khuôn đúc, bọn hà tặc buộc phải lên một kế hoạch vô cùng tỉ mỉ.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lô Hâm","avatar":""},{"name":"Lưu Sở Minh","avatar":""},{"name":"Mã Thiên Nhất","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
