INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-canh-su', 'Thanh Xuân Cảnh Sự', 'Caught In The Heartbeat', 'https://phimimg.com/upload/vod/20231207-1/8347d4609c6240b06642331184443d79.jpg', 'https://phimimg.com/upload/vod/20231207-1/7522f0fd14a961b9d467b8ebc45892bb.jpg', '<p>Nói về Thanh niên Đường Nhất Tu lập chí quyết tâm trở thành một cảnh sát chính nghĩa. Trong quá trình chấp hành nhiệm vụ tại bệnh viện, anh vô tình gặp gỡ Cổ Tĩnh. Cổ Tĩnh vốn là con nhà cảnh sát, nhưng đang bị hôn mê nhưng vô tình Nhất Tu đã khiến cho Cổ Tĩnh được tỉnh dậy, hoạt động được bình thường nhưng kí ức lại bị mất đi. Cổ Tĩnh với trí nhớ và năng lực phân tích hơn người, thông qua nhiều khảo thí và huấn luyện cũng trở thành cảnh sát. Đường Nhất Tu và Cổ Tĩnh trở thành một đôi phá án cực ăn ý. Trải qua nhiều quá trình, Đường Nhất Tu cũng giúp đỡ Cổ Tĩnh tìm kiếm lại kí ức đã bị mất.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngụy Đại Huân","avatar":""},{"name":"Tiêu Tuấn Diễm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
