INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-xam', 'Đôi Mắt Xám', 'Grey Eyes', 'null', 'https://phimimg.com/upload/vod/20231206-1/0c13e48554315eca98eb24dfb5df5fa6.jpg', '<p>Đôi Mắt Xám - Grey Eyes kể về câu chuyện trong một tương lai hậu tận thế, loài người bị mù màu. Một nhà khoa học lỗi lạc đột ngột qua đời, để lại chiếc cặp quý giá chứa đầy ma túy tổng hợp có khả năng gây nghiện cao cho phép mọi người nhìn lại màu sắc thông qua Ana, một cô bé chỉ 12 tuổi. Việc sở hữu chiếc cặp khiến cô trở thành mục tiêu của một bác sĩ với những kế hoạch độc ác về ma túy, và hy vọng duy nhất của cô để thoát khỏi sự truy đuổi của anh ta là dựa vào sự trợ giúp của hai vệ sĩ tận tụy của nhà khoa học đã chết. Nhưng họ không thể ngờ được rằng cuộc hành trình nguy hiểm của họ xoay quanh một bí mật to lớn: chính Ana có thể là chìa khóa để cứu vãn một thế giới trong đống đổ nát.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Cecilia Milano","avatar":""},{"name":"Fernando Amaral","avatar":""},{"name":"William Prociuk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
