INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-hon-trong-mua', 'Oan Hồn Trong Mưa', 'Love Rain', 'https://phimimg.com/upload/vod/20231206-1/d2d2c10f2c9a3d274d3ff0b006171419.jpg', 'https://phimimg.com/upload/vod/20231206-1/33dc3c5cde904929bdd23a50648e8f47.jpg', '<p>Phim xoay quanh câu chuyện về cái chết bí ẩn và đầy oan khuất của cô gái tên Som. Bước ra từ cửa hàng tiện lợi vào lúc 1 giờ sáng, Som phát hiện rằng mình đã chết không lý do. Gab - cậu thiếu gia nhà giàu bỏ nhà ra đi và đang làm việc tại cửa hàng tiện lợi vô tình trở thành người duy nhất nhìn thấy Som. Liệu có uẩn khúc gì với cái chết của Som? Tại sao định mệnh lại sắp đặt Gab là người duy nhất biết Som tồn tại và những màn trả thù chết chóc trong phim sẽ thế nào?…</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Boom Kitkong","avatar":""},{"name":"Sammy Cowell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
