INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-khun-pan-2', 'Người Hùng Khun Pan 2', 'Khun Pan 2', 'null', 'https://phimimg.com/upload/vod/20231203-1/c4da3b5132cf96464c7658f3ca60a229.jpg', '<p>Bộ phim Người Hùng Khun Pan 2 - Khun Pan 2 kể về câu chuyện của đất nước Thái lan sau khi kết thúc Thế chiến 2. Những tên cướp nắm quyền lực phù thủy đã xây dựng vương quốc của riêng chúng. Họ lang thang, cướp bóc và giết bất cứ ai cản đường họ. Khun Phan được kêu gọi phục vụ để thâm nhập vào các băng đảng cướp bằng bí danh là Sua Butr.Anh rơi vào nguy hiểm khi cả cảnh sát và kẻ cướp bắt đầu nghi ngờ lòng trung thành của anh ta. Anh phải đối đầu với những người có trí thông minh, phép thuật và võ thuật bình đẳng, những người tìm cách giết anh ta. Khun Pan sẽ phải sử dụng tất cả các kỹ năng của mình cả về thể chất và tinh thần để cố gắng sống sót trước sự tấn công của cả pháp luật và ngoài vòng pháp luật. Ai sẽ là người cuối cùng đứng trong trò chơi về thể lực và sự tinh ranh.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Ananda Everingham","avatar":""},{"name":"Arak Amornsupasiri","avatar":""},{"name":"Ratchawin Wongwiriya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
