INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-nghiem', 'Kẻ Thử Nghiệm', 'The Titan', 'https://phimimg.com/upload/vod/20231203-1/bdf883f24cb9c6eca6b0c0a9b0a09871.jpg', 'https://phimimg.com/upload/vod/20231203-1/57d69b8e705565abcd67609868cb5692.jpg', '<p>Phi công không lực Hotshot, Rick Janssen (Sam Worthington), được lựa chọn cho một cuộc thử nghiệm quân sự nhằm tạo ra một con người có khả năng tồn tại trong môi trường khắc nghiệt trên mặt trăng của sao Thổ, TITAN. Cuộc thử nghiệm thành công, biến Rick thành siêu nhân, nhưng nó cũng gây ra những phản ứng phụ chết người đe dọa cuộc sống của Rick, vợ và gia đình, và có thể là cả nhân loại.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Taylor Schilling","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Agyness Deyn","avatar":""},{"name":"Nathalie Emmanuel","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
