INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sieu-quay', 'Thám Tử Siêu Quậy', 'Sherlock Gnomes', 'https://phimimg.com/upload/vod/20231203-1/c4d31dd8d40c482b8f9d280d0e19671b.jpg', 'https://phimimg.com/upload/vod/20231203-1/beed6847dbfb90d305c6b83f2b38350c.jpg', '<p>Trở lại từ khu vườn nơi mà Gnomeo và Juliet sinh sống, những chú lùn lần này sẽ có cuộc hành trình mới đầy hứa hẹn tại thành phố London. Khi Gnomeo và Juliet lần đầu đặt chân đến thành phố này cùng bạn bè và gia đình, họ đã nhận ra rằng khu vườn mới của họ đang bước sang mùa xuân. Tuy nhiên, họ nhanh chóng phát hiện ra đã có một kẻ bắt cóc tất cả những thần lùn giữ cửa ở London. Khi đó Gnomeo và Juliet quay trở về nhà để tìm đến sự giúp đỡ của một người duy nhất có khả năng lần ra manh mối và thủ phạm cho vụ án này đó chính là... SHERLOCK GNOMES.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"James McAvoy","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324394);
