INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-cua-quy', 'Hoa Của Quỷ', 'Gogol. Viy', 'https://phimimg.com/upload/vod/20231203-1/2ee74421fd739823d755a2187d9fe4a4.jpg', 'https://phimimg.com/upload/vod/20231203-1/602b9ef3816bf9a132ffc8b389a22ead.jpg', '<p>Nằm trong series phim Gogol đình đám và đầy tham vọng của điện ảnh Nga, HOA CỦA QUỶ (tựa gốc: GOGOL: VIY) lấy bối cảnh tại một ngôi làng bí ẩn Dikanka trong quá khứ xa xôi, nơi mà một thế lực đen tối đã bắt và giết chết các cô gái trẻ. Nikolai Gogol (Alexander Petrov thủ vai) – một pháp sư từ St Petersburg đã nhập cuộc điều tra. Anh dần phát hiện ra hung thủ đứng sau tất cả là Kỵ Sỹ Hắc Ám. Nhưng cuộc chiến chống lại thế lực đen tối không hề suôn sẻ, lúc này vị pháp sư trẻ tuổi cần đến sự giúp đỡ của người bạn đồng hành tuyệt vời là là Thợ Săn Phù Thủy kiêm Nhà Thần Học Khoma Brutu...</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Thuyết Minh', 'HD', 'Nga', 0, '[{"name":"Alexander Petrov","avatar":""},{"name":"Aleksey Vertkov","avatar":""},{"name":"Evgeniy Stychkin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
