INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-thanh-maria-madalena', 'Bà Thánh Maria Mađalêna', 'Mary Magdalene', 'https://phimimg.com/upload/vod/20231203-1/d5d5f5df34627d4fdfa734ac1be41b62.jpg', 'https://phimimg.com/upload/vod/20231203-1/027b04af7d75a0ad698a4009f2fa0455.jpg', '<p>MARY MAGDALENE khắc họa bức chân dung có thực và nhân văn của một trong những nhân vật bí ẩn và bị hiểu nhầm nhất trong lịch sử. Tác phẩm có thật từ trong Kinh thánh kể về câu chuyện của Mary (Rooney Mara), một người phụ nữ trẻ đi tìm một lẽ sống mới. Bị áp bức bởi những giai cấp trong xã hội thời bấy giờ, Mary đã chống đối lại cả gia đình truyền thống của cô để tham gia một phong trào xã hội mới do Chúa Giêsu Nazareth tài giỏi (Joaquin Phoenix) dẫn đầu. Từ đó, cô sớm có chỗ đứng trong phong trào và là người chủ chốt trong chuyến đi tới Jerusalem. Chấp bút bởi Helen Edmundson và Philippa Goslett, MARY MAGDALENE có sự tham gia của hai ngôi sao lớn: Chiwetel Ejiofor và Tahar Rahim.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rooney Mara","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
