INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-cam-tu-alpha', 'Biệt Đội Cảm Tử Alpha', 'Project E.1337: ALPHA', 'https://phimimg.com/upload/vod/20231203-1/b9d6f5845630db0136dcace4c7123ce2.jpg', 'https://phimimg.com/upload/vod/20231203-1/cd737ba12ae26a1c2a1f609ea26d8a3e.jpg', '<p>Khi thế giới rơi vào hỗn loạn vì một loại vi khuẩn không xác định, một số vùng an toàn bắt đầu lợi dụng những người kém may mắn hơn để thu lợi riêng. Với nguồn tài nguyên ngày càng cạn kiệt và những kẻ nổi dậy ...</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carmen Gangale","avatar":""},{"name":"Taylor Nelms","avatar":""},{"name":"Shelby Brunn","avatar":""},{"name":"Michael Vitovich","avatar":""},{"name":"Stefanie Barber","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324394);
