INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chinh-phuc-vach-nui-el-captain', 'Chinh Phục Vách Núi El Captain', 'Free Solo', 'https://phimimg.com/upload/vod/20231203-1/69d7f73ecbe8873954b384ae8d5e5e9c.jpg', 'https://phimimg.com/upload/vod/20231203-1/996f5bc46c0ba77fe5cb56e4c742ec26.jpg', '<p>Free Solo khiến khán giả hồi hộp khi thưởng thức vì phải chờ xem điều gì sẽ xảy đến tiếp theo trong câu chuyện nghẹt thở về vận động viên leo núi chuyên nghiệp Alex Honnold khi anh tay không chinh phục El Capitan - một vách núi đá granite cao 914.4m tại công viên quốc gia Yosemite. Leo lên vách đá dựng nổi tiếng nhất thế giới không dùng dây và thiết bị an toàn là một kỳ tích chưa từng có. Honnold sẽ thách thức giới hạn chịu đựng của con người cả về mặt thể chất và tinh thần. Giành giải #Oscar cho Phim tài liệu xuất sắc nhất và nhận được cơn mưa lời khen, được đánh giá là một trong những bộ phim tài liệu thành công nhất mọi thời đại.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Honnold","avatar":""},{"name":"Tommy Caldwell","avatar":""},{"name":"Jimmy Chin","avatar":""},{"name":"Sanni McCandless","avatar":""},{"name":"Mikey Schaefer","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324394);
