INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-bi-an', 'Sát Thủ Bí Ẩn', 'Collateral', 'https://phimimg.com/upload/vod/20231204-1/2f576d357203ce9d36b9c25896968bea.jpg', 'https://phimimg.com/upload/vod/20231204-1/32db1637fa3f845d7c35b34df555032c.jpg', '<p>Sát Thủ Bí Ẩn Tài sản thế chấp 2018 Phim Sát Thủ Bí Ẩn: Các thanh tra ở London đang điều tra một vụ giết người từ một người đàn ông giao bánh pizza, trong đó có nữ Thanh tra Kip Glaspie, cô nghi ngờ rằng không phải vậy. Đó chỉ đơn giản là một vụ giết người thông thường nên cô quyết định tìm ra sự thật bí ẩn sâu bên trong.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 12, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"John Simm","avatar":""},{"name":"Nicola Walker","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324394);
