INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-bi-mat-tich', 'Đứa Con Bị Mất Tích', 'Her Son''s Secret', 'https://phimimg.com/upload/vod/20231215-1/067be717dc105a5e6b0618460ae1e2e6.jpg', 'https://phimimg.com/upload/vod/20231215-1/b976167dcb1b4b924ee7f0bd49fa4adb.jpg', '<p>Đứa Con Bị Mất Tích - Her Sons Secret là bộ phim được truyền cảm hứng bởi sự kiện có thực. Sarah chưa bao giờ bỏ cuộc khi mất đứa con trai Matt 13 năm trước - được cho là bị chết đuối - cô vẫn nuôi hy vọng. Một ngày nọ, người tự xưng là Matt xuất hiện ở cửa nhà Sarah. Nhưng sự xuất hiện của Matt cũng kéo theo hàng loạt những tai họa đến với gia đình. Matt có phải là kẻ mạo danh? Và nếu là thật thì anh ấy muốn có một ngôi nhà yêu thương hay trả thù?</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"David Garelik","avatar":""},{"name":"Olivia d’Abo","avatar":""},{"name":"Tammy Blanchard","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
