INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-huyen-bi-toi-ac-cua-grindelwald', 'Sinh Vật Huyền Bí: Tội Ác Của Grindelwald', 'Fantastic Beasts: The Crimes of Grindelwald', 'https://phimimg.com/upload/vod/20231205-1/2c14df06bbde5862d78d3d79a3fbefa9.jpg', 'https://phimimg.com/upload/vod/20231205-1/9d2603657ed1c2f924388a2fa056fa6a.jpg', '<p>Trong một nỗ lực để ngăn chặn các kế hoạch nâng cao những phù thủy máu tinh khiết của Grindelwald để cai trị tất cả những sinh vật không ma thuật, Albus Dumbledore đã tranh thủ Scamander Newt của mình, người đồng ý giúp đỡ, mặc dù anh ta không biết về những nguy hiểm nằm ở phía trước. Các dòng được vẽ như tình yêu và lòng trung thành được thử nghiệm, ngay cả trong số những người bạn và gia đình thật nhất, trong một thế giới phù thủy ngày càng chia rẽ.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324394);
