INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-ma-ky', 'Phong Ma Kỷ', 'The Legend Of Earth Traveler Sun', 'https://phimimg.com/upload/vod/20231205-1/2fdd8c60f318a5b2710082aee1407e63.jpg', 'https://phimimg.com/upload/vod/20231205-1/919f2a1d92bde5c307724b5124d8f016.jpg', '<p>Kể về cuộc hành trình đầy bí ẩn của A Tôn – chàng trai sở hữu dị năng, mang trong mình thân phận đặc biệt – cùng những người bạn khi đến vùng đất cổ, nơi phong ấn máu của Xi Vưu. Đối đầu với tộc người kỳ lạ, tìm kiếm tung tích về cha, vạch trần thân phận phương sĩ bí ẩn và bảo vệ phong ấn. Liệu A Ton có vượt qua những thử thách này?</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Vân Tường","avatar":""},{"name":"Phùng Húc Đông","avatar":""},{"name":"Trinh Kim Minh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324394);
