INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('teen-titans-go-to-the-movies', 'Teen Titans Go! To the Movies', 'Teen Titans Go! To the Movies', 'https://phimimg.com/upload/vod/20231204-1/ea7eb613e55675411038edbf2a511064.jpg', 'https://phimimg.com/upload/vod/20231204-1/7a47142ce1c2fc80c8ada197337a97e6.jpg', '<p>Dường như với thanh thiếu niên rằng tất cả các siêu anh hùng lớn ngoài kia đang đóng vai chính trong những bộ phim của chính họ, tất cả mọi người, nhưng đó là Teen Titans, đó là. Nhưng thủ lĩnh thực tế, Robin quyết tâm khắc phục tình hình, và được coi là một ngôi sao thay vì một Sidekick. Giá như họ có thể có được đạo diễn phim Hollywood nóng nhất để chú ý họ. Với một vài ý tưởng Madcap và một bài hát trong lòng, Teen Titans đến Town Town, chắc chắn sẽ rút ra giấc mơ của họ. Nhưng khi nhóm được đánh giá cao bởi một nhân vật phản diện nghiêm trọng và kế hoạch điên rồ của mình để chiếm lấy trái đất, mọi thứ thực sự trở nên tồi tệ. Nhóm nghiên cứu tìm thấy tình bạn của họ và tinh thần chiến đấu của họ thất bại, đưa số phận của chính Teen Titans vào dòng.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324394);
