INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-y', 'Thiên Ý', 'Hero''s Dream', 'https://phimimg.com/upload/vod/20231204-1/120db10b43a22568fb3dccbd5f528f22.jpg', 'https://phimimg.com/upload/vod/20231204-1/da11650140d253ef66e86c61ff817388.jpg', '<p>Bộ phim lấy bối cảnh cuối đời nhà Tần đầu nhà Hán, các nhân vật danh chấn một thời là Tần Thủy Hoàng (Kiều Chấn Vũ), Hàn Tín (Âu Hào), Lưu Bang, Hạng Vũ cùng bị cuốn vào những sự việc thần bí dưới bàn tay của Nữ Hi (Đường Yên) – người sáng tạo nên nền văn minh nhân loại, vị “Thần” với pháp thuật cao siêu, nắm giữ thiên ý của loài người. Tần Thủy Hoàng vì muốn trường sinh bất lão mà bắt tay với sứ giả của Thần, gây nên nhiều thảm cảnh cho nhân gian. Hàn Tín mất đi người yêu Quý Khương bởi sự tàn bạo của Tần Thủy Hoàng nên đem lòng báo thù, chiến loạn nổ ra. Quý Khương được sứ giả tái sinh nhưng lại mất đi ký ức, tự xưng là Tiền Tiểu Phương (Hải Linh). Vị Thần luôn tự xưng ấy có thực sự là thần thánh hay chỉ là một người từ tương lai xuyên không đến? Thiên hạ chúng sinh dưới bàn tay thôi thúc của quyền năng tối thượng và lòng tham của con người sẽ đi về đâu? Tần mạt Hán sơ, quần hùng tranh bá. Hoài Âm thiếu niên Hàn Tín có duyên gặp được một người áo đen thần bí, xưng có thể mượn trợ thần lực giúp Hàn Tín quật khởi, điều kiện là chỉ cần Hàn Tín đáp ứng cùng hắn làm một trận giao dịch. Bánh xe lịch sử không ngừng chuyển động, Tần Thủy Hoàng, Lưu Bang, Hạng Vũ, Trương Lương phân tranh quyền lực, thân ở trong loạn thế, Hàn Tín phát hiện chuyện thay đổi vương triều cùng quyền lợi phía sau có một lực lượng thần bí thao túng…</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 18, 2018, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Âu Hào","avatar":""},{"name":"Đường Yên","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324394);
