INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-me-ke', 'Âm Mưu Mẹ Kế', 'Killer In Law', 'https://phimimg.com/upload/vod/20231203-1/151d1168634288182ed2832c605107c8.jpg', 'https://phimimg.com/upload/vod/20231203-1/45314829f4daa46071f1d8c31b88fed7.jpg', '<p>Âm Mưu Mẹ Kế - Killer In Law là bộ phim được truyền cảm hứng từ một câu chuyện có thật. Melissa đang sống hạnh phúc cùng chồng và cô con gái 8 tuổi. Tuy nhiên, mẹ chồng đột nhiên xuất hiện muốn chuyển đến sống cùng, Melissa nhận ra rằng bà đang có một âm mưu, muốn chiếm hữu cô con gái của họ để thay thế đứa con đã chết của mình, tính mạng của cô cũng đang là mục tiêu bị nhắm đến.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kelly Sullivan","avatar":""},{"name":"Brett Zimmerman","avatar":""},{"name":"Nana Visitor","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324394);
