INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-dem-an-ai', '30 Đêm Ân Ái', '30 Nights Of Sex', 'https://phimimg.com/upload/vod/20231202-1/1ad664b1f48c15338fb44be8ca804562.jpg', 'https://phimimg.com/upload/vod/20231202-1/c8b9a955ebf0b59706e53fff060c673b.jpg', '<p>30 Đêm Ân Ái - 30 Nights Of Sex: Trong nỗ lực cuối cùng để cứu vãn cuộc hôn nhân, Nick và Willa đã tìm đến một nhà tư vấn lập dị nhưng khá nổi tiếng khi hàn gắn thành công cho các cặp vợ chồng trong giai đoạn có thể tan vỡ. Và bắt đầu một cuộc hành trình kéo dài một tháng với những cuộc hẹn hò, những trò chơi khiêu khích gợi tình, vui nhộn với cặp đôi Nick và Willa. Họ có hàn gắn được không hay chỉ nhìn thấy những thói xấu của người còn lại, bộ phim này sẽ là một lời giải đáp.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Fogler","avatar":""},{"name":"Mandy Kaplan","avatar":""},{"name":"Johnny Giacalone","avatar":""},{"name":"Alyssa Brayboy","avatar":""},{"name":"Nick Bush","avatar":""},{"name":"Chris Butler","avatar":""},{"name":"Ted Cannon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324394);
