INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-vo-danh', 'Thế Giới Vô Danh', 'Anon', 'https://phimimg.com/upload/vod/20231212-1/dc6fe620e4cbcfedfbfc08e2ee58e20d.jpg', 'https://phimimg.com/upload/vod/20231212-1/bbdd14cd8c33e231e8ea2e3347927694.jpg', '<p>Sal Frieland (Owen) là một thám tử trong một thế giới không có sự riêng tư, dốt nát, hoặc giấu tên; nơi cuộc sống của mọi người trong suốt, có thể theo dõi và được ghi lại bởi chính quyền; nơi tội phạm gần như chấm dứt tồn tại. Nhưng trong cố gắng giải quyết một loạt các vụ giết người chưa được giải quyết, Frieland tình cờ gặp một phụ nữ trẻ được biết đến chỉ là Cô gái (Seyfried). Cô không có danh tính, không có lịch sử và không thể nhìn thấy cảnh sát. Sal nhận ra điều này có thể không phải là kết thúc của tội phạm, mà là sự khởi đầu.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Colm Feore","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324395);
