INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-tham-lang', 'Mật Danh Thầm Lặng', 'Dark Iris', 'https://phimimg.com/upload/vod/20231212-1/5d11a28c7c248fc56618d0ec3f9fa161.jpg', 'https://phimimg.com/upload/vod/20231212-1/a10bbcd12273d02cbc87fb6ae576873d.jpg', '<p>Iris bị ám ảnh bởi một kẻ theo dõi bí ẩn và những giấc mơ của chính cô. Các nhân viên FBI vây quanh Iris trong khi các thi thể xếp chồng lên nhau xung quanh cô. Ở thời hiện đại, Tiến sĩ Jekyll và Cô Hyde, Iris cố gắng sống sót khi cô bị săn đuổi bởi chính cơ quan đã tạo ra cô.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"KateLynn E. Newberry","avatar":""},{"name":"Marylee Osborne","avatar":""},{"name":"Rebekah Hart Franklin","avatar":""},{"name":"Kyle Hotz","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324395);
