INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-den-thung-lung-cam', 'Hành Trình Đến Thung Lũng Cấm', 'Journey to the Forbidden Valley', 'https://phimimg.com/upload/vod/20231201-1/a58503cce380a8b715576c5d4519b6ff.jpg', 'https://phimimg.com/upload/vod/20231201-1/334d3382aebedf4d70d91b0035637d3e.jpg', '<p>Sau vụ tai nạn máy bay xảy ra ở một vùng hẻo lánh miền Trung Trung Quốc, trong số những hành khách sống sót có một cậu bé Trung Quốc và người giám hộ của cậu. Trong khi chờ đợi để được giải cứu, họ chạm trán với Yeren - một sinh vật người vượn được đồn đại là đã sinh sống ở vùng núi Thần Nông Giá trong nhiều thế kỷ. Liệu Yeren sẽ là bạn hay thù?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sasha Jackson","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Erroll Shand","avatar":""},{"name":"Jiahang Su","avatar":""},{"name":"Alexi Xiaowu Woo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324395);
