INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-de-ngo', 'Ngôi Nhà Để Ngỏ', 'The Open House', 'https://phimimg.com/upload/vod/20231130-1/4d184751e57fdf643719fdb29b749492.jpg', 'https://phimimg.com/upload/vod/20231130-1/3c7e6ace4f4c3d73ad901b7601a7806c.jpg', '<p>Sau một thảm kịch, một người mẹ và cậu con trai chuyển đến một căn nhà trống của một người họ hàng mà không biết rằng có một kẻ xấu đang chờ họ.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan Minnette","avatar":""},{"name":"Piercey Dalton","avatar":""},{"name":"Sharif Atkins","avatar":""},{"name":"Patricia Bethune","avatar":""},{"name":"Matt Angel","avatar":""},{"name":"Suzanne Coote","avatar":""},{"name":"Aaron Abrams","avatar":""},{"name":"Kathryn Beckwith","avatar":""},{"name":"Ethan Cushing","avatar":""},{"name":"Edward Olson","avatar":""},{"name":"Leigh Parker","avatar":""},{"name":"Paul Rae","avatar":""},{"name":"Jessica Robertson","avatar":""},{"name":"Katie Walder","avatar":""},{"name":"Robert Everett Williams Jr.","avatar":""},{"name":"Ryan Robertson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
