INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nhan-cua-sat-thu', 'Lời Nhắn Của Sát Thủ', 'Message Man', 'https://phimimg.com/upload/vod/20231130-1/af54178a060557e9d791dc41409a026a.jpg', 'https://phimimg.com/upload/vod/20231130-1/803b24b1bf9e2918eff39839fa0047ff.jpg', '<p>Message Man lấy bối cảnh vẻ đẹp của quần đảo Indonesia. Câu chuyện kể về một cựu sát thủ ẩn dật, Ryan Teller (Paul O&#39;Brien). Chọn sống một cuộc sống du mục trên thuyền của mình, Ryan hình thành một tình bạn bất đắc dĩ với một cậu bé địa phương Doni (Aji Santosa) và gia đình. Khi cậu bé gần như bị giết, bắt đầu một trả thù dữ dội buộc Ryan phải thiết lập lại các mối quan hệ và cũng đối mặt với quá khứ đen tối của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Paul O''Brien","avatar":""},{"name":"Alfridus Godfred","avatar":""},{"name":"Verdi Solaiman","avatar":""},{"name":"Valentine Payen","avatar":""},{"name":"Aji Santosa","avatar":""},{"name":"Mario Irwinsyah","avatar":""},{"name":"Agni Pratistha","avatar":""},{"name":"Mike Lewis","avatar":""},{"name":"Ronny P. Tjandra","avatar":""},{"name":"Gary Plant","avatar":""},{"name":"Bran Vargas","avatar":""},{"name":"Denny Baskar","avatar":""},{"name":"Epy Kusnandar","avatar":""},{"name":"Patria Sandya Mustika","avatar":""},{"name":"Trisa Triandesa","avatar":""},{"name":"Monica Sayangba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
