INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('movie-hau-can-ma-ca-rong-alice-in-the-garden', 'Movie Hầu Cận Ma Cà Rồng: Alice In The Garden', 'Gekijouban Servamp: Alice In The Garden', 'https://phimimg.com/upload/vod/20231211-1/6cce59e3f7dbf96a4b104dba1a245ad9.jpg', 'https://phimimg.com/upload/vod/20231211-1/7fe66387c700c714af97b28f0a64d532.jpg', '<p>SerVamp là một từ kết hợp giữa 2 từ SERVANT - người hầu và VAMPIRE - ma cà rồng, theo đó, SerVamp là việc ma cà rồng sẽ phải làm theo mệnh lệnh của người mà đã thỏa thuận cho nó lấy máu. Shirota Mahiru, người đã ký hợp đồng với Kuro đã bị mắc vào trận chiến giữa các ma cà rồng. Khi Servamp Tsubaki biến mất, Mahiru đã nghĩ rằng có lẽ mình đã được trở lại được cuộc sống bình yên thường ngày, thì khi anh gọi Arisuin Misono, bí mật chôn giấu của gia đình Arisuin dần được hé lộ.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
