INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tung-hoanh-giang-ho', 'Tung Hoành Giang Hồ', 'Swimming Dragon Sword', 'null', 'https://phimimg.com/upload/vod/20231211-1/b1636535ec66e2b896f7224a39ec9d13.jpg', '<p>Tung Hoành Giang Hồ - Swimming Dragon Sword xoay quanh thanh Long kiếm mệnh danh đệ nhất thần binh lợi khí trong giang hồ, có sức mạnh đến nỗi đã bị chôn vùi bởi những con người đánh nhau đến đẫm máu cả trăm năm trước và trong thanh kiếm còn giấu một bộ võ công bí tịch gọi là Long du cửu thức. Có một vị trưởng môn của thất danh môn chính phái đã hợp lại đem kẻ gian ác này tiêu diệt và để thanh kiếm này không gây họa bọn họ bàn bạc giấu thanh kiếm này. Rốt cuộc thanh kiếm này đang ở trong tay ai ?</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lining He","avatar":""},{"name":"Yuan Zhongfang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324395);
