INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tinh-sa', 'Thiên Tịnh Sa', 'Drinking Wind Inn', 'null', 'https://phimimg.com/upload/vod/20231210-1/5737ac3ef566df86c7b0cfdcdbf74ec6.jpg', '<p>Thiên Tịnh Sa - Drinking Wind Inn - The Last Man Stand kể về thời Trung Hoa Dân Quốc, Ngô Phong một tội phạm chính của vụ cướp tiền lương của Tân quân, đã trốn thoát khỏi nhà tù. Chỉ huy quân đội mới muốn bắt hắn để trả thù cho người anh em đã chết của mình, Tổ hợp sát thủ nhận được chỉ thị, sau khi hoàn thành nhiệm vụ trên sa mạc, ba người và ngựa bất ngờ gặp nhau tại Quán trọ Âm phong, và thủ lĩnh băng đảng cát Sa bang hội. A Thủy một nữ bang chủ cũng nhận được nhiệm vụ đến Đại Mạc giết người và tìm đồ. Hang Chi Đạo cũng đến Đại Mạc. Tất cả đều tụ họp tại quán trọ, vì bà chủ quán trọ là đồng bọn của Ngô Phong năm đó. Ai cũng muốn bắt được Ngô Phong và bắt hắn nói ra nơi cất giấu quân lương.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Zhuoting","avatar":""},{"name":"Yang Junyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324395);
