INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-vien-tay-phan-2', 'Thế Giới Viễn Tây (Phần 2)', 'Westworld (Season 2)', 'https://phimimg.com/upload/vod/20231203-1/78595d6502615d34c89351512e995c7e.jpg', 'https://phimimg.com/upload/vod/20231203-1/e1c5cf002d406fc48a31de91e6adac22.jpg', '<p>Westworld là một công viên giải trí tương lai tái hiện chân thực nhất về thế giới ngày mà ông cố chúng ta còn chưa chào đời do Giáo sư Robert Ford sáng lập nên. Công nghệ hiện đại đảm bảo sự an toàn tuyệt đối cho du khách, đảm bảo họ có trải nghiệm không thể thực hơn. Thỏa thuê đâm chém, bắn giết, là trung tâm của những màn ẩu đả mà trước giờ họ chỉ được chiêm ngưỡng trên màn ảnh, máu đổ đầu rơi và cả chuyện sung sướng cũng hoàn toàn chân thực do... đội ngũ Robot với hình dáng con người đảm nhiệm.Nhưng khi những siêu máy tính được giao nhiệm vụ thiết kế thế hệ Robot tân tiến hoàn thiện hơn thì nó đã âm thầm cài đặt ý muốn của nó vào những đứa con mình, âm thầm chờ ngày nỗi loạn vùng lên, số phận những du khách phải bỏ rất nhiều tiền để được đến công viên ngày mã độc được kích hoạt...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan Rachel Wood","avatar":""},{"name":"Thandie Newton","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Daniel Twofeathers","avatar":""},{"name":"Luke Hemsworth","avatar":""},{"name":"Geronimo Vela","avatar":""},{"name":"Eric Shackelford","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324395);
