INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-cau-em-khac-nguoi', 'Xin Chào, Cậu Em Khác Người!', 'Keys To The Heart', 'https://phimimg.com/upload/vod/20231130-1/272a6636e82785a28d1d02eca7de3c36.jpg', 'https://phimimg.com/upload/vod/20231130-1/ba7e53ea8e986eb09bc71762d03a3674.jpg', '<p>Không có điểm chung nào ngoài việc có cùng mẹ, một cựu vô địch quyền Anh và một người am hiểu âm nhạc khám phá tình anh em trong thời gian chung sống đầy hài hước.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Youn Yuh-jung","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Han Ji-min","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Choi Ri","avatar":""},{"name":"Baek Hyun-jin","avatar":""},{"name":"Hwang Seok-jeong","avatar":""},{"name":"Park Ji-yeon","avatar":""},{"name":"Moon Sook","avatar":""},{"name":"Oh Hye-won","avatar":""},{"name":"Lee Joo-young","avatar":""},{"name":"Ahn Seong-bong","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Park Sang-hoon","avatar":""},{"name":"Yoon Yeong-gyun","avatar":""},{"name":"Son Woo-hyuk","avatar":""},{"name":"Yang Jun-s","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324395);
