INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bob-lazar-khu-vuc-51-dia-bay', 'Bob Lazar: Khu Vực 51 & Đĩa Bay', 'Bob Lazar: Area 51 and Flying Saucers', 'https://phimimg.com/upload/vod/20231130-1/b4cac283bfe05af351a6f75f4379a1cd.jpg', 'https://phimimg.com/upload/vod/20231130-1/c9f03b5df40a01e62a38627f6ed19c90.jpg', '<p>Khu vực 51, đĩa bay đến từ thế giới khác - và chương trình tạo ra một công nghệ khốc liệt. Bob Lazar vẫn là cái tên nổi tiếng và gây tranh cãi nhất trong thế giới UFO. Lý do bạn biết về Khu vực 51 là vì Lazar đã đến và nói với bạn về nó. Những tiết lộ của anh ấy đã khiến cuộc sống của anh ấy bị đảo lộn và anh ấy đã cố gắng tránh xa ánh đèn sân khấu. Vì lý do này, anh ấy chưa bao giờ để bất kỳ nhà làm phim nào bước vào thế giới riêng tư của cuộc sống hàng ngày của mình - đó là - cho đến bây giờ. Bộ phim của Corbell khám phá những tuyên bố của Lazar qua lăng kính của ba mươi năm - cung cấp những thước phim hiếm và chưa từng được tiết lộ trước đây - đảm bảo sẽ thay đổi cục diện của cuộc tranh luận.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Lazar","avatar":""},{"name":"George Knapp","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Jeremy Kenyon Lockyer Corbell","avatar":""},{"name":"Joy White","avatar":""},{"name":"Phyllis Tucker","avatar":""},{"name":"Layne Keck","avatar":""},{"name":"Mario Santa Cruz","avatar":""},{"name":"Zack Slizewski","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324395);
