INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-sac-anh-hung-4', 'Bản Sắc Anh Hùng 4', 'A Better Tomorrow', 'https://phimimg.com/upload/vod/20231130-1/3b11a22aee384982edc8550c6e725ae4.jpg', 'https://phimimg.com/upload/vod/20231130-1/2c45e2a9722e5457c75e38c32368efdf.jpg', '<p>Bộ phim là câu chuyện về 3 con người, 3 tính cách khác nhau: Châu Khải, 30 tuổi, thành viên quan trọng của đường dây buôn lậu, tính tình khảng khái, có phần cố chấp, yêu ghét phân minh; Châu Siêu - 23 tuổi, cảnh sát, em trai ruột của Châu Khải, tính tình cởi mở, lạc quan, hăng hái làm việc, lòng đầy chính nghĩa, hiện là ngôi sao đang lên của Phòng Phòng chống Ma túy; Mã Kha, 28 tuổi, thành viên băng nhóm buôn lậu, cánh tay phải của Châu Khải, suy nghĩ đơn giản, trọng nghĩa khí, nhiệt tình thẳng thắn.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nick Wang","avatar":""},{"name":"Ma Tianyu","avatar":""},{"name":"Darren Wang","avatar":""},{"name":"Yu Ailei","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Li Meng","avatar":""},{"name":"Zhang Yishang","avatar":""},{"name":"Jiang Peiyao","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Yûta Nakano","avatar":""},{"name":"Sang Ping","avatar":""},{"name":"Zha Ka","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Ding Sheng","avatar":""},{"name":"Ning Hao","avatar":""},{"name":"Li Mincheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324395);
