INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oblivion-verses', 'Oblivion Verses', 'Oblivion Verses', 'https://phimimg.com/upload/vod/20231130-1/fddb8140698db2867dbbc6bf125d42cd.jpg', 'https://phimimg.com/upload/vod/20231130-1/e379d5dfd15de8834a505a167c947daa.jpg', '<p>Khi người chăm sóc người già của một nhà thờ xa xôi phát hiện ra cơ thể của một phụ nữ trẻ bị giết trong một cuộc biểu tình, anh ta bắt đầu một cuộc phiêu lưu kỳ diệu để cho cô một sự chôn cất thích hợp trước khi dân quân trở về.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Juan Margallo","avatar":""},{"name":"Tomás del Estal","avatar":""},{"name":"Manuel Morón","avatar":""},{"name":"Itziar Aizpuru","avatar":""},{"name":"Gonzalo Robles","avatar":""},{"name":"Amparo Noguera","avatar":""},{"name":"Julio Jung","avatar":""},{"name":"Lucas Bolvarán","avatar":""},{"name":"Willy Semler","avatar":""},{"name":"Luis Dubó","avatar":""},{"name":"Mario Soto","avatar":""},{"name":"Elisa Sepulveda Ruddoff","avatar":""},{"name":"Víctor Hugo Ogaz","avatar":""},{"name":"Alex Rivera","avatar":""},{"name":"Nicolás de Terán","avatar":""},{"name":"Jessica Vera","avatar":""},{"name":"Francisc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
