INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huynh-de-hoang-kim', 'Huynh Đệ Hoàng Kim', 'Golden Job', 'https://phimimg.com/upload/vod/20231129-1/493ff6bf0365e2c4cdb2e97cb009f2d1.jpg', 'https://phimimg.com/upload/vod/20231129-1/9f110285918c5c1a19f50d1bc139f25d.jpg', '<p>Năm anh em Sư Vương (Trịnh Y Kiện), Hỏa Sơn (Trần Tiểu Xuân), Bill (Tạ Thiên Hoa), Đàm Định (Tiền Gia Lạc), Lão Thử (Lâm Hiểu Phong), dưới sự chỉ đạo của ân sư Tào Sir (Tăng Chí Vĩ) cùng nhau vào sinh ra tử. Vì muốn cứu sống những đứa trẻ với số phận đáng thương nên năm anh em đã quyết định ăn trộm một loại thuốc đặc hiệu, không may mắc bẫy của kẻ địch, rơi vào một màn mưa bom bão đạn. Cả năm người đều biết không thể quay đầu lại được nữa, nhưng họ vẫn quyết chí hoàn thành.</p>', 'Full', 1, 'single', 'completed', 7, 2018, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Charmaine Sheh","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Sergej Onopko","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Temur Mamisashvili","avatar":""},{"name":"Phillip Jang Il-Do","avatar":""},{"name":"Zhang Yamei","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Paul Philip Clark","avatar":""},{"name":"Björn Freiberg","avatar":""},{"name":"Semiquav","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324395);
