INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('va-em-se-den', 'Và Em Sẽ Đến', 'Be with You', 'https://phimimg.com/upload/vod/20231129-1/4d4cef942606cff5ef1c822aa7097935.jpg', 'https://phimimg.com/upload/vod/20231129-1/9dbee81f0b8ce772613d6dfa1bf1a0ec.jpg', '<p>Và Em Sẽ Đến bắt đầu với một lời hứa từ Soo A (Son Ye Jin) vào cơn mưa đầu mùa cô ấy sẽ quay về với với chồng mình Woo Jin (So Ji Sub) và con trai Ji Ho (Kim Ji Hwan). Nhưng khi trở lại, Soo A hoàn toàn không còn ký ức về thực tại các mối quan hệ mà cô từng có trước đây. Woo Jin đã từng bước để giúp Soo A khơi dậy từng ký ức mà cô đã lãng quên. Bằng những mảnh ghép từ tình yêu đơn phương anh dành cho cô, ngày hẹn hò đầu tiên từ thời phổ thông, và nụ hôn đầu tiên… Một lần nữa, Woo Jin và Soo A lại yêu nhau.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"So Ji-sub","avatar":""},{"name":"Son Ye-jin","avatar":""},{"name":"Kim Ji-hwan","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Son Yeo-eun","avatar":""},{"name":"Lee You-jin","avatar":""},{"name":"Kim Hyun-soo","avatar":""},{"name":"Bae Yoo-ram","avatar":""},{"name":"Seo Jeong-yeon","avatar":""},{"name":"Park Seo-jun","avatar":""},{"name":"Gong Hyo-jin","avatar":""},{"name":"Lee Min-sung","avatar":""},{"name":"Lee Seung-joon-III","avatar":""},{"name":"Shin Woo-hee","avatar":""},{"name":"Jo Ha-seok","avatar":""},{"name":"Seo Young-sam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324395);
