INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-tham-nhung-3-san-bao', 'Đội Chống Tham Nhũng 3: Săn Bão', 'L Storm', 'https://phimimg.com/upload/vod/20231129-1/a31f1f91fab998ce9b34394dbb77ac9b.jpg', 'https://phimimg.com/upload/vod/20231129-1/d5889db7fbd0c02cdf782f5bb23204df.jpg', '<p>Trong một vụ án tưởng chừng như đi vào bế tắc của điều tra viên Lục Chí Liêm (Cổ Thiên Lạc) cùng đồng nghiệp, thì anh ta bị cáo buộc dính đến vụ việc quan liêu nhũng nhiễu ngay trong chính vụ án của mình. Để minh oan cho bản thân, Lục Chí Liêm đã dấn thân điều tra và phát hiện hàng loạt những đường dây bất hợp pháp. Từ đó, anh bắt đầu bước vào nhiều phen hiểm nguy cũng như những màn đấu trí đến nghẹt thở.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Julian Cheung","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Adam Pak Tin-Nam","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Janelle Sing","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Ding Haifeng","avatar":""},{"name":"Toby Chan","avatar":""},{"name":"Deon Cheung","avatar":""},{"name":"Alan Luk","avatar":""},{"name":"Ng Siu-H","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
