INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-luc-sieu-pham-2018', 'Trí Lực Siêu Phàm', 'The Darkest Minds', 'https://phimimg.com/upload/vod/20231017-1/8b5e2141f0776ec444b88e361b5c76cf.jpg', 'https://phimimg.com/upload/vod/20231017-1/e5f90ca7367588cb54de271f1dad12b2.jpg', '<p>Trong thế giới điêu tàn của The Darkest Minds (Trí Lực Siêu Phàm), siêu năng lực của bọn trẻ được phân loại dựa trên màu sắc: Blue dùng để chỉ những khả năng liên quan đến di không vật (telekinesis), Yellow là những quyền năng thao túng dòng điện, Orange là những cá nhân có thể đi vào tâm trí người khác, còn phân loại Red là khả năng điều khiển lửa. Và nhân vật chính của bộ phim - Ruby thuộc phân loại Orange, được đánh giá là một trong những dị nhân nguy hiểm nhất. Cùng với nhiều người bạn đồng trang lứa khác gồm Liam (Harris Dickinson), Chubs (Skylan Brooks) và Zu (Miya Cech), cô đã trốn chạy khỏi trại tập trung, đi tìm một mái nhà mới giữa một xã hội đầy thù địch …</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amandla Stenberg","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Patrick Gibson","avatar":""},{"name":"Skylan Brooks","avatar":""},{"name":"Mandy Moore","avatar":""},{"name":"Miya Cech","avatar":""},{"name":"Gwendoline Christie","avatar":""},{"name":"Grace DeAmicis","avatar":""},{"name":"Faye Foley","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Wallace Langham","avatar":""},{"name":"Golden Brooks","avatar":""},{"name":"Sammi Rotibi","avatar":""},{"name":"McCarrie McCausland","avatar":""},{"name":"Logan Siu","avatar":""},{"name":"Ethan Alexander Mc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908