INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-thua-ke', 'Quý Cô Thừa Kế', 'The Heiress', 'https://phimimg.com/upload/vod/20230919-1/6cafda90699739e08a9740e5ea222f04.jpg', 'https://phimimg.com/upload/vod/20230919-1/12673d30c8de8537408882e985ca26a6.jpg', '<p><span style="font-family: ">Bà ngoại đột ngột qua đời, cô tiểu thư chỉ biết ăn chơi rơi vào khóa học bất đắc dĩ để kế thừa số tài sản khổng lồ theo di chúc của người bà quá cố. Từ đây, hàng loạt sự kiện dở khóc dở cười xảy ra bởi sự hậu đậu của nàng tiểu thư kiêu kỳ. Sự trở lại của Ngân Khánh cùng dàn diễn viên triển vọng: Song Luân, Liên Bỉnh Phát, Sĩ Thanh… khiến Quý Cô Thừa Kế trở thành tác phẩm thu hút nhất mùa phim cuối năm 2018.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ngân Khánh","avatar":""},{"name":"Sĩ Thanh","avatar":""},{"name":"Hồng Đào","avatar":""},{"name":"Võ Quang Minh","avatar":""},{"name":"Song Luan","avatar":""},{"name":"Lien Binh Phat","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324395);
