INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-tinh-yeu-2018', 'Thử Thách Tình Yêu', 'Kasal', 'https://phimimg.com/upload/vod/20231101-1/a4b185d11cf8509d403906c4c7087788.jpg', 'https://phimimg.com/upload/vod/20231101-1/bb4e7c9367bfa1f91c9d52da79d8acee.jpg', '<p>Lia Marquez chuẩn bị kết hôn cùng Philip Cordero, một người đàn ông hoàn mỹ sắp tranh cử chức thị trưởng sau khi cha anh hết nhiệm kỳ. Tuy nhiên, mọi thứ trở nên phức tạp khi Wado dela Costa, bạn trai cũ của Lia, lại trở thành thành viên ban tranh cử của Philip. Thường xuyên chạm mặt nhau khiến những cảm xúc xưa ùa về và đặt Lia vào tình huống hết sức khó xử.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Bea Alonzo","avatar":""},{"name":"Paulo Avelino","avatar":""},{"name":"Derek Ramsay","avatar":""},{"name":"Christopher de Leon","avatar":""},{"name":"Cherie Gil","avatar":""},{"name":"Ricky Davao","avatar":""},{"name":"Celeste Legaspi","avatar":""},{"name":"Ces Quesada","avatar":""},{"name":"Vin Abrenica","avatar":""},{"name":"Kylie Verzosa","avatar":""},{"name":"Cris Villonco","avatar":""},{"name":"Cai Cortez","avatar":""},{"name":"JC Alcantara","avatar":""},{"name":"Divine Aucina","avatar":""},{"name":"John Lapus","avatar":""},{"name":"Bobby Andrews","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
