INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cai-the-2018', 'Anh Hùng Cái Thế', 'Monkey King Reincarnation', 'null', 'https://phimimg.com/upload/vod/20231013-1/dfb5f001aa813d3c88d31faa8b0307cc.jpg', '<p>Những ngày gần đây, các trưởng lão của một số môn phái ở sông hồ đã bị giết không thể giải thích được, và người dân ở sông hồ đều hoảng sợ. Công Tôn Tấn lần lượt nhận được lời thách thức từ các bậc thầy, một lần gặp Yue&#39;er trông giống như chủ nhân Hồng đã chết, mặc dù Hong là sư phụ của Công Tôn Tấn và người yêu của anh ta, nhưng Xun không dám kết hôn với chủ nhân vì quan niệm trần tục, Hồng đã tự tử trong nước mắt để khiến Xun hối hận suốt đời, và khi số phận cho Xun một cơ hội khác, mâu thuẫn nội tâm của Tấn rất phức tạp. Lần theo âm mưu chấn động trái đất ẩn sau lưng Yue&#39;er trong giải pháp...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Lantuo","avatar":""},{"name":"Mori Jun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324395);
