INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha-bao-thu', 'Người Cha Báo Thù', 'Your Son', 'https://phimimg.com/upload/vod/20231129-1/91859d02ca7ed5fe9f6956625b6a3173.jpg', 'https://phimimg.com/upload/vod/20231129-1/55cb594a902c098af0b7140613a985d8.jpg', '<p>Jaime, một bác sĩ sống ở Seville, thấy cuộc sống của mình thay đổi hoàn toàn khi con trai ông phải chiến đấu để giành lấy mạng sống của mình sau khi bị đánh đập trong một vụ cướp. Cảm giác đau đớn và bất lực sớm chuyển thành cảm giác căm ghét và tức giận, biến một người cha tốt thành một người đàn ông mất nhân tính.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Jose Coronado","avatar":""},{"name":"Pol Monen","avatar":""},{"name":"Ana Wagener","avatar":""},{"name":"Ester Expósito","avatar":""},{"name":"Asia Ortega","avatar":""},{"name":"Sauce Ena","avatar":""},{"name":"Marco H. Medina","avatar":""},{"name":"Gonzalo Hermoso","avatar":""},{"name":"Sergio Castellanos","avatar":""},{"name":"Luis Bermejo","avatar":""},{"name":"Ramiro Alonso","avatar":""},{"name":"Paqui Montoya","avatar":""},{"name":"Vicente Romero Sánchez","avatar":""},{"name":"José Blanco","avatar":""},{"name":"Marta Romero","avatar":""},{"name":"Cris Nollet","avatar":""},{"name":"David Moreno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
