INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('azali-dinh-menh', 'Azali: Định Mệnh', 'Azali', 'https://phimimg.com/upload/vod/20231129-1/322588f623666d737acd29a28362b0c6.jpg', 'https://phimimg.com/upload/vod/20231129-1/30efacdc3e106d180a1c892974f8f796.jpg', '<p>Bị đưa đến nơi xa lạ nhằm thoát khỏi cuộc hôn nhân sắp đặt, đứa trẻ 14 tuổi bước vào hành trình đau khổ của nghề mại dâm và sự nghèo đói tại khu ổ chuột thuộc Accra.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Ghana', 0, '[{"name":"Asana Alhassan","avatar":""},{"name":"Akofa Edjeani Asiedu","avatar":""},{"name":"Peter Ritchie","avatar":""},{"name":"Adjetey Anang","avatar":""},{"name":"Ama K. Abebrese","avatar":""},{"name":"Emmanuel Nii Adom Quaye","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
