INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-quai-tho-san-quy-du', 'Ma Quái: Thợ Săn Quỷ Dữ', 'Nekrotronic', 'https://phimimg.com/upload/vod/20231129-1/f6b1ecd3449f8506ca635811a56235af.jpg', 'https://phimimg.com/upload/vod/20231129-1/d58a37aef381d33f16b8f6d727a07b84.jpg', '<p>Ma Quái (Nekrotronic) là một bộ phim mới chiếu rạp của Australia, thể loại kinh dị, khoa học viễn tưởng,… và được đạo diễn bởi Kiah Roache-Turner. Nội dung phim kể về một người đàn ông phát hiện ra rằng anh ta là một phần của một giáo phái bí mật của những sinh vật ma thuật chuyên săn lùng và tiêu diệt quỷ trên internet.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Ben O''Toole","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Tess Haubrich","avatar":""},{"name":"Caroline Ford","avatar":""},{"name":"Bob Savea","avatar":""},{"name":"Goran D. Kleut","avatar":""},{"name":"David Beamish","avatar":""},{"name":"Charmaine Bingwa","avatar":""},{"name":"Benedict Hardie","avatar":""},{"name":"Philip Partridge","avatar":""},{"name":"Jessica Racz","avatar":""},{"name":"Mike Duncan","avatar":""},{"name":"Connor Van Vuuren","avatar":""},{"name":"Jeffrey Mercado-Libunao","avatar":""},{"name":"Jesse Rowl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
