INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lang', 'Người Làng', 'Ordinary People - The Villagers', 'https://phimimg.com/upload/vod/20231129-1/cced734c2b54fb2c32e183bc76e59175.jpg', 'https://phimimg.com/upload/vod/20231129-1/a806d6d748e64dd9be60a61d00b3de91.jpg', '<p>Ki Cheol (Ma Dong Seok) là một thầy giáo dạy môn thể dục. Vì một sự cố ngoài ý muốn, anh bị điều về công tác ở một ngôi trường nhỏ vùng nông thôn. Tại đây, một nữ sinh tên Kang Yoo Jin (Kim Sae Ron) khăng khăng với anh rằng bạn nữ của mình đã bị bắt cóc và cô là người duy nhất biết điều đó. Ki Cheol cảm thấy có gì đó không ổn, nhưng dường như không ai trong làng quan tâm. Yoo Jin và Ki Cheol phối hợp cùng nhau để tìm cô nữ sinh này nhưng Ki Cheol phát hiện ra những dấu vết về cô ấy cũng đang dần biến mất.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ma Dong-seok","avatar":""},{"name":"Kim Sae-ron","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Lee Sang-yeob","avatar":""},{"name":"Shin Se-hwi","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Oh Hee-jun","avatar":""},{"name":"Bae Jin-ah","avatar":""},{"name":"Moo-yeong Yeo","avatar":""},{"name":"Yoo Young-bin","avatar":""},{"name":"Lee Sang-hun","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Kang Jeong-won","avatar":""},{"name":"Kang Min-joon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324395);
