INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-nguoi-dep-2', 'Giải Cứu Người Đẹp 2', 'Baaghi 2', 'https://phimimg.com/upload/vod/20231129-1/e850451b928d5a12251ab0c06d9954ca.jpg', 'https://phimimg.com/upload/vod/20231129-1/1fa056c05ae7489418eaadf737f875d5.jpg', '<p>Nội dung của phim Giải Cứu Người Đẹp 2 tiếp tục xoay quanh anh chàng Ronnie (Tiger Shroff), hiện đang phục vụ trong quân đội Ấn Độ. Một ngày nọ, anh nhận được một cú điện thoại từ người yêu cũ của anh – Neha (Disha Patani), khi cô đang rất lo lắng cho cô con gái đang bị mất tích của cô. Sau khi tới gặp Neha, Ronnie thấy rằng Neha rất bối rối bởi sự kiện này, trong khi cảnh sát thì có vẻ thờ ơ, họ không xử lý trường hợp mất tích này một cách nghiêm túc có thể bởi có một thế lực khủng khiếp nào đó đang đứng ở phía sau.Sau đó Ronnie bắt đầu cuộc điều tra của chính mình và thấy rằng không có sự thật trong câu chuyện của Neha vì điều đó chưa bao giờ xảy ra. Nhưng Neha thì luôn kiên quyết rằng con gái của cô đã bị bắt cóc. Từ đó anh bắt đầu cuộc hành trình đi tìm đứa bé từ những manh mối nhỏ, một mình anh phải đấu trọi lại với rất nhiều những thế lực đen tối, từ những trận đánh đấm cho tới những cuộc đấu súng đầy khốc liệt theo đúng nghĩa của một “Rambo”...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Tiger Shroff","avatar":""},{"name":"Disha Patani","avatar":""},{"name":"Manoj Bajpayee","avatar":""},{"name":"Randeep Hooda","avatar":""},{"name":"Darshan Kumaar","avatar":""},{"name":"Prateik Babbar","avatar":""},{"name":"Deepak Dobriyal","avatar":""},{"name":"Aryan Prajapati","avatar":""},{"name":"Jacqueline Fernandez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
