INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-san-lung-san-vat', 'Cuộc Săn Lùng Sản Vật', 'Prospect', 'https://phimimg.com/upload/vod/20231128-1/55e7ea79b19edc3c2f08fe3318e9ceef.jpg', 'https://phimimg.com/upload/vod/20231128-1/bf74372ff77a9a4a4f2300a63214bd61.jpg', '<p>Bộ phim kể về tương lai trên một hành tinh xa lạ bị nhiễm độc. Xoay quanh câu chuyện về hai cha con đi săn lùng khoáng sản quý trên hành tinh này và đem về trái đất. Tuy nhiên, không chỉ có họ là người đi tìm các kim loại này, bọn cướp đang truy lùng để chiếm đoạt các khoáng sản họ đã khai thác được...</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Thatcher","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Jay Duplass","avatar":""},{"name":"Andre Royo","avatar":""},{"name":"Sheila Vand","avatar":""},{"name":"Anwan Glover","avatar":""},{"name":"Luke Pitzrick","avatar":""},{"name":"Arthur Deranleau","avatar":""},{"name":"Alex McCauley","avatar":""},{"name":"Doug Dawson","avatar":""},{"name":"Krista Johnson","avatar":""},{"name":"Brian Gunter","avatar":""},{"name":"Trick Danneker","avatar":""},{"name":"Christopher Morson","avatar":""},{"name":"Shepheard Earl","avatar":""},{"name":"Ben Little","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
