INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mary-kieu-hanh', 'Mary Kiêu Hãnh', 'Proud Mary', 'https://phimimg.com/upload/vod/20231128-1/dc772074506eedcf8c2c9150f8cc930a.jpg', 'https://phimimg.com/upload/vod/20231128-1/7477d2b803b65f4e41bb459400e601f5.jpg', '<p>Trong khi cố gắng bảo vệ một cậu bé mồ côi, nữ sát thủ đầy mặc cảm tội lỗi đã châm ngòi một cuộc chiến băng đảng và sớm phải đối mặt với những mối đe dọa lớn từ mọi phía.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taraji P. Henson","avatar":""},{"name":"Jahi Di''Allo Winston","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Billy Brown","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Margaret Avery","avatar":""},{"name":"Erik LaRay Harvey","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Owen Burke","avatar":""},{"name":"Alex Ziwak","avatar":""},{"name":"Jose Guns Alves","avatar":""},{"name":"Leah Procito","avatar":""},{"name":"David Chen","avatar":""},{"name":"Jim Ford","avatar":""},{"name":"Therese Plaehn","avatar":""},{"name":"Josep","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324395);
