INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-tuong-lai', 'Thế Giới Tương Lai', 'Future World', 'https://phimimg.com/upload/vod/20231127-1/f4ba53883fb2b8699a266927b35b79dd.jpg', 'https://phimimg.com/upload/vod/20231127-1/6ab1cf75a4f4ca062f2863c4b584d9d2.jpg', '<p>Trong phim, Franco đóng vai lãnh chúa (Warlord) một kẻ vô lại tâm thần dùng người đàn bà đẹp robot Ash (Suki Waterhouse) do mình tạo nên làm nô lê tình dục và làm sát thủ cho mình. Nhân vật chính trong phim là Hoàng tử Prince (Jeffrey Wahlberg, cháu của diễn viên Mark Wahlberg, đóng). Ash bất ngờ phản chủ, tham gia với Prince trong cuộc hành trình qua sa mạc với hy vọng tìm được một loại thuốc phép lạ có thể cứu được Nữ hoàng (Lucy Liu đóng), đang chờ chết. Loại thuốc này cất giữ tại một nơi gọi là Paradise Beach do bà trùm ma túy Drug Lord (Milla Jovovich) trấn giữ. Họ bị Warlord cử tay đồ tể Tattooed Face (Cliff &quot;Method Man&quot; Smith) và băng xe máy truy đuổi.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Jeffrey Wahlberg","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Snoop Dogg","avatar":""},{"name":"Rumer Willis","avatar":""},{"name":"Method Man","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Ben Youcef","avatar":""},{"name":"Wilmer Calderon","avatar":""},{"name":"Tamzin Brown","avatar":""},{"name":"Carmen Argenziano","avatar":""},{"name":"Elisha Henig","avatar":""},{"name":"Lee Coc","avatar":""},{"name":"Erika L. Elkhalide","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
