INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-anh', 'Vô Ảnh', 'Shadow', 'https://phimimg.com/upload/vod/20231129-1/4c4f8fc8f64a92145e42728f9fbca7f8.jpg', 'https://phimimg.com/upload/vod/20231129-1/c9a06e03dd2e09d0b881d40957475386.jpg', '<p>Shadow (Vô Ảnh) lấy bối cảnh dưới thời kỳ Tam Quốc. Đại Đô Đốc Phái quốc Tử Ngu (Đặng Siêu) trong một lần chiến đấu đã bị thương nặng và phải ẩn thân trong bóng tối. Để tiếp tục nhiệm vụ của mình, hắn ta giao phó cho sát thủ có tên Cảnh Châu, biệt hiệu “Ảnh tử” – cũng chính là cái bóng của mình. Cuộc chiến trong Vô Ảnh càng trở nên nguy hiểm và rắc rối khi Phái quốc bị sự đe dọa của các thế lực ngoại bang.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Sun Li","avatar":""},{"name":"Ryan Zheng Kai","avatar":""},{"name":"Wang Qian-Yuan","avatar":""},{"name":"Wang Jingchun","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Guan Xiaotong","avatar":""},{"name":"Leo Wu","avatar":""},{"name":"Feng Bai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
