INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo', 'Người Vợ', 'The Wife', 'https://phimimg.com/upload/vod/20231129-1/38589a72410607b4b44d73bd925c66ff.jpg', 'https://phimimg.com/upload/vod/20231129-1/28908b0f89a92946db9cec5613b3c43a.jpg', '<p>Một người phụ nữ bỗng dưng đặt dấu hỏi lại về sự lựa chọn của cuộc đời mình khi bà cùng chồng đến Stockholm để ông nhận đề cử giải Nobel Văn Học</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Glenn Close","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Max Irons","avatar":""},{"name":"Harry Lloyd","avatar":""},{"name":"Annie Starke","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Johan Widerberg","avatar":""},{"name":"Karin Franz Körlof","avatar":""},{"name":"Richard Cordery","avatar":""},{"name":"Jan Mybrand","avatar":""},{"name":"Anna Azcárate","avatar":""},{"name":"Peter Forbes","avatar":""},{"name":"Fredric Gildea","avatar":""},{"name":"Jane Garioni","avatar":""},{"name":"Alix Wilton Regan","avatar":""},{"name":"Nick","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
