INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-2-than-long-tai-xuat', 'Tế Công 2: Thần Long Tái Xuất', 'The Incredible Monk 2: Dragon Return', 'https://phimimg.com/upload/vod/20231129-1/ae81008b35236aff6db47d952070133b.jpg', 'https://phimimg.com/upload/vod/20231129-1/4d2bda930b28c4ebc3b447c94228f85a.jpg', '<p>Tướng quân Cao Nhân Kiệt chính là danh tiếng triều đình, đã tham gia nhiều trận lớn nhỏ và giành nhiều chiến thắng, lập được không ít công lao hiển hách, trở thành người anh hùng dân tộc. Cao Bân và Tự Thiếu phải lòng thanh mai trúc mã Phượng Nghi, nhưng ý trời lại lệnh Phượng Nghi bị ép phải xuống biển làm kỹ nữ. Cao Nhân Kiệt yêu Phượng Nghi, lại bị mọi người chỉ trích lại không dám cưới Phượng Nghi làm thê tử. Cao Nhân Kiệt cầu Tế Công giúp, Tế Công trải qua bao nhiêu khó khăn, thề phải làm mối cho hai người mệnh khổ này! Khi tất cả đã thành công, thuộc hạ của Cao lại hạ độc thủ, giết chết Phượng Nghi, muốn Cao Nhân Kiệt quên đi tình cảm trai gái, dốc lòng vì nước vì dân. Tế Công phẫn nộ, oán hận ông trời vì sao lại chia cách uyên ương? Lẽ trời ở đâu? Giận dữ biến thành rồng thần, thề phải thay đổi vận mệnh, đi ngượi thiên ý, trực tiếp đi xuống địa phủ, chiến đầu chống lại các linh hồn tà ác, cướp lại nguyên thần của Phượng Nghi</p>', 'Full', 1, 'single', 'completed', 23, 2018, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chan Ho-Man","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Sun Mingming","avatar":""},{"name":"Joe Hsieh","avatar":""},{"name":"Jin Gang","avatar":""},{"name":"Zhang Yiqian","avatar":""},{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Yang Neng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324395);
