INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-cua-bella', 'Câu Chuyện Của Bella', 'Bella''s Story', 'null', 'https://phimimg.com/upload/vod/20231129-1/c7d7b753d2a6514083924108009ac486.jpg', '<p>Bella 17 tuổi luôn mong muốn có cuộc sống tốt hơn. Cô sống với người chú nghiện cờ bạc, và cô luôn được nói rằng bố mẹ cô đã chết. Cô khao khát được thực hiện ước mơ trở thành một nhà báo, nhưng vấn đề cờ bạc của chú mình khiến cô không thể đi học đại học. Khi cô nhìn thấy người bạn thân nhất của mình đi học, Bella thấy bất mãn và mong muốn làm điều gì đó. Thông qua một người bạn của chú, cô được giới thiệu với một cố vấn tại trường đại học địa phương, người trở thành cố vấn của cô. Cuối cùng, cô biết được sự thật về cha mẹ mình và vượt qua những bất hòa bằng cách biến hiện thực của mình thành một câu chuyện cổ tích ngoài đời thực.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bella Rose","avatar":""},{"name":"Jason Gedrick","avatar":""},{"name":"Sharon Leal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
