INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-xe-taxi-5', 'Quái Xế Taxi 5', 'Taxi 5', 'https://phimimg.com/upload/vod/20231125-1/b78728e9e5e02d61c2929a489dd298e5.jpg', 'https://phimimg.com/upload/vod/20231125-1/7ed0a32afcf06596a18991cdfaa69f95.jpg', '<p>Bộ phim hài Quái Xế Taxi 5 là phần thứ năm của loạt Quái Xế Taxi đình đám của Pháp. Trong phần này, một sĩ quan cảnh sát được lệnh phải hạ gục một băng cướp sỡ hữu những chiếc Ferrari mạnh mẽ trong khi anh phải điều khiển một chiếc xe taxi dòng Peugeot 407.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Franck Gastambide","avatar":""},{"name":"Malik Bentalha","avatar":""},{"name":"Bernard Farcy","avatar":""},{"name":"Salvatore Esposito","avatar":""},{"name":"Édouard Montoute","avatar":""},{"name":"Sabrina Ouazani","avatar":""},{"name":"Sand Van Roy","avatar":""},{"name":"Anouar Toubali","avatar":""},{"name":"Monsieur Poulpe","avatar":""},{"name":"Sissi Duparc","avatar":""},{"name":"Ramzy Bedia","avatar":""},{"name":"Moussa Maaskri","avatar":""},{"name":"Éric Fraticelli","avatar":""},{"name":"Saïd M''Roumbaba","avatar":""},{"name":"David Salles","avatar":""},{"name":"Elise L","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324395);
