INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-can-em-hanh-phuc', 'Chỉ Cần Em Hạnh Phúc', 'More Than Blue', 'https://phimimg.com/upload/vod/20231125-1/2258ad5ad152c8c47a30002da493d6df.jpg', 'https://phimimg.com/upload/vod/20231125-1/84a4eed552ddd735ba0cd2d493058c96.jpg', '<p>K và Cream gặp nhau năm 16 tuổi tại trường trung học và dần thân thiết như người trong gia đình. Năm tháng thôi qua, K đi làm cho một hãng thu âm và Cream trở thành nhạc sĩ, họ vẫn sống với nhau dù không phải là một đôi. Một ngày kia, K bị chẩn đoán mắc bệnh bạch cầu, K do dự không tiết lộ bệnh tình của mình cũng như thổ lộ tình yêu với Cream vì sợ cô tổn thương. Trước khi không còn thời gian, K phải làm mọi thứ để Cream có thể ổn định và hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Jasper Liu","avatar":""},{"name":"Ivy Chen","avatar":""},{"name":"Bryan Shu-Hao Chang","avatar":""},{"name":"Annie Chen","avatar":""},{"name":"Emma Wu","avatar":""},{"name":"Bruce Ho","avatar":""},{"name":"Heaven Hai","avatar":""},{"name":"Phoebe Lin","avatar":""},{"name":"Shih Chih Tian","avatar":""},{"name":"Aining Yao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324395);
