INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-phi-thuong-cua-fakir', 'Hành Trình Phi Thường Của Fakir', 'The Extraordinary Journey of the Fakir', 'https://phimimg.com/upload/vod/20231125-1/ba4058d0633a22de457c2bef1d694fe6.jpg', 'https://phimimg.com/upload/vod/20231125-1/38ac5ff2de80ccbcd2ba2705928d5505.jpg', '<p>Hành Trình Phi Thường Của Fakir - The Extraordinary Journey of the Fakir (2018):Ajatashatru Lavash Patel đã sống cả đời trong một khu phố nhỏ ở Mumbai lừa mọi người bằng ảo thuật đường phố và biểu diễn như một ‘fakir’, người có thể làm nên những điều kỳ diệu không thể. Sau cái chết của mẹ mình, anh bắt đầu cuộc hành trình tìm cha và vươn lên từ nghèo khó.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dhanush","avatar":""},{"name":"Bérénice Bejo","avatar":""},{"name":"Erin Moriarty","avatar":""},{"name":"Barkhad Abdi","avatar":""},{"name":"Gérard Jugnot","avatar":""},{"name":"Ben Miller","avatar":""},{"name":"Abel Jafri","avatar":""},{"name":"Sarah-Jeanne Labrosse","avatar":""},{"name":"Kay Greidanus","avatar":""},{"name":"Amruta Sant","avatar":""},{"name":"Vinod Jaywant","avatar":""},{"name":"Naman Jain","avatar":""},{"name":"Svar Kamble","avatar":""},{"name":"Hearty Singh","avatar":""},{"name":"Gandharv Dewan","avatar":""},{"name":"Omkar Ketkar","avatar":""},{"name":"Preet Bhanushali","avatar":""},{"name":"Burjor Das","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
