INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hop-nhac-ma-quai', 'Hộp Nhạc Ma Quái', 'The Music Box', 'https://phimimg.com/upload/vod/20231125-1/4b0c9eb656dc981eaddd6de579b08f13.jpg', 'https://phimimg.com/upload/vod/20231125-1/4a3cc561e794939bd71fab0a17a48623.jpg', '<p>Hộp Nhạc Ma Quái - The Music Box (2018):Khi hộp nhạc không phải là một thứ đồ chơi…Đó là nơi trú ẩn của một oan hồn khao khát được chiếm hữu tình yêu thương…Làm cách nào để cô bé Sophie 6 tuổi chịu rời bỏ HỘP NHẠC MA QUÁI?</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Rachel Daigh","avatar":""},{"name":"Antonio Lujak","avatar":""},{"name":"Antonella Salvucci","avatar":""},{"name":"Cearl Pepper","avatar":""},{"name":"Fiona Whitelaw","avatar":""},{"name":"Melissa Leone","avatar":""},{"name":"Anita Tenerelli","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
