INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-xam-noi-doi-mat', 'Màu Xám Nơi Đôi Mắt', 'Grey Eyes', 'https://phimimg.com/upload/vod/20231125-1/22e1610eb0a955ace36412bf6d3982a2.jpg', 'https://phimimg.com/upload/vod/20231125-1/c93c0996facd3d036e6446c7a757fedf.jpg', '<p>Bối cảnh tương lai hậu tận thế, loài người bị mù màu. Một nhà khoa học lỗi lạc đột ngột qua đời, để lại chiếc cặp quý giá chứa đầy ma túy tổng hợp có khả năng gây nghiện, giúp mọi người nhìn lại được màu sắc. Việc sở hữu chiếc cặp khiến cô bé Ana 12 tuổi trở thành mục tiêu truy sát của một tên bác sĩ xấu xa. Hành trình chạy trốn của cô bé mở ra một bí mật: chính Ana có thể là chìa khóa để cứu vãn một thế giới đang trong đống đổ nát.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Uruguay', 0, '[{"name":"William Prociuk","avatar":""},{"name":"Fernando Amaral","avatar":""},{"name":"Cecilia Milano","avatar":""},{"name":"Christian Zagia","avatar":""},{"name":"Rafael Soliwoda","avatar":""},{"name":"Fiorella Bottaioli","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
