INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-lop-18', 'Tạm Biệt Lớp 18', 'To Us, From Us', 'https://phimimg.com/upload/vod/20231125-1/52a0b7aa25dda0dbc7f4e117f0751861.jpg', 'https://phimimg.com/upload/vod/20231125-1/2c88b625fb3fd10d6bc3f67ba9a4887c.jpg', '<p>Một ngày nọ, lớp 18, lớp yakuza khét tiếng ở trường trung học Wutong nhận được một lá thư từ chính họ trong tương lai. Bức thư đã dự đoán chính xác điều gì sẽ xảy ra với lớp 18 trong những năm trung học của họ, đồng thời yêu cầu các học sinh hoàn thành ba nhiệm vụ bất khả thi để cứu giáo viên dạy toán đang bị bệnh. Để tránh những điều không may được ghi trong thư, những đứa trẻ hư đã kêu gọi đình chiến và dần dần nảy sinh mối quan hệ ấm áp với giáo viên Toán trên hành trình thay đổi lịch sử.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qin Hai","avatar":""},{"name":"Yanxi Ke","avatar":""},{"name":"Yanxi Ke","avatar":""},{"name":"Jingwen Xiong","avatar":""},{"name":"Jingwen Xiong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
