INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-co-the-hinh-dung', 'Chỉ Có Thể Hình Dung', 'I Can Only Imagine', 'https://phimimg.com/upload/vod/20231125-1/c0366cc85da994840e062c235a2298c0.jpg', 'https://phimimg.com/upload/vod/20231125-1/654218e78097dbd7cb5818b1518a8320.jpg', '<p>Cậu bé 10 tuổi Bart Millard sống với mẹ và người cha bạo hành Arthur ở Texas. Một ngày nọ, mẹ anh đưa anh đến một trại Cơ đốc giáo, nơi anh gặp Shannon. Khi trở về từ trại, Bart thấy mẹ mình đã rời đi và những người chuyển đồ đang dọn đồ đạc của bà. Anh tức giận đối mặt với cha mình, người phủ nhận rằng sự ngược đãi của ông là lý do khiến cô bỏ đi. Nhiều năm sau, ở trường trung học, Bart và Shannon hẹn hò. Bart chơi bóng để làm hài lòng cha mình nhưng bị chấn thương, gãy cả hai mắt cá chân và kết thúc sự nghiệp. Môn tự chọn duy nhất còn chỗ trống là lớp âm nhạc, vì vậy anh ấy miễn cưỡng đăng ký.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"J. Michael Finley","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Brody Rose","avatar":""},{"name":"Madeline Carroll","avatar":""},{"name":"Gianna Simone","avatar":""},{"name":"Kevin Downes","avatar":""},{"name":"Jason Burkey","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"Tanya Clarke","avatar":""},{"name":"Nicole DuPort","avatar":""},{"name":"Priscilla C. Shirer","avatar":""},{"name":"Taegen Burns","avatar":""},{"name":"Trace Adkins","avatar":""},{"name":"Mark Furze","avatar":""},{"name":"Randy McDowell","avatar":""},{"name":"Cole Marcus","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
