INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-song-con-2018', 'Cuộc Chiến Sống Còn', 'Traffik', 'https://phimimg.com/upload/vod/20231124-1/8b0bfbe034cd93dd0425f4a02e3960ba.jpg', 'https://phimimg.com/upload/vod/20231124-1/4b9b0f7ba445e9272078eea707bd6403.jpg', '<p>Một cặp đôi đi nghỉ cuối tuần lãng mạn trên núi bị một nhóm biker tiếp cận. Đơn độc trên núi, Brea và John phải tự bảo vệ mình chống lại băng đảng này, những kẻ sẽ không từ thủ đoạn nào để bảo vệ bí mật của chúng.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paula Patton","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Luke Goss","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Dawn Olivieri","avatar":""},{"name":"Priscilla Quintana","avatar":""},{"name":"Lorin McCraley","avatar":""},{"name":"Roselyn Sánchez","avatar":""},{"name":"Lisa Hitchcock Kallstrom","avatar":""},{"name":"Stacey Arwen Raab","avatar":""},{"name":"Scott Anthony Leet","avatar":""},{"name":"William W. Barbour","avatar":""},{"name":"Claude Duhamel","avatar":""},{"name":"Adrian B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
