INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-ai', 'Bạn Gái AI', 'AI Girlfriend', 'null', 'https://phimimg.com/upload/vod/20231013-1/9c345210b83cd46708306658ddf9f4df.jpg', '<p>Chu Đào từ nhỏ mắc bệnh tim bẩm sinh, đối với tương lai có thái độ tiêu cực, hắn luôn nghi ngờ trên đời này thật sự có người nào quan trọng hơn mạng sống của mình hay không. Nếu có... vậy thì ... cô ấy có ở bên cạnh tôi không? ? Chu Tao còn trẻ, suốt ngày lang thang trong cửa hàng quần áo của anh họ Chu Văn, cho đến một ngày, Chu Đào vô tình kích hoạt robot số D đến từ tương lai, Chu Tao đã thử mọi cách nhưng không thể thoát khỏi điều này &quot;sản phẩm cao cấp&quot;, Chu Tao Tao bất lực dẫn dắt Số D bắt đầu hòa nhập với thế giới. Dần dần, Chu Tao thay đổi thái độ tiêu cực muốn &quot;hủy diệt thế giới&quot;, và những người xung quanh đều có những tác động khác nhau do đến sự tồn tại của số D.</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Qing","avatar":""},{"name":"Liu Wei","avatar":""},{"name":"Mao Na","avatar":""},{"name":"Wei Yankan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324395);
