INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-tung-tich-ao', 'Truy Tìm Tung Tích Ảo', 'Searching', 'https://phimimg.com/upload/vod/20231125-1/d36ab89c303e22719933f6597396814d.jpg', 'https://phimimg.com/upload/vod/20231125-1/3db6fba364002012a580135aa7b4d341.jpg', '<p>Thuộc thể loại tâm lý hình sự, Searching được dự đoán sẽ là &quot;món ăn tinh thần&quot; đầy kịch tính dành cho các fan điện ảnh trong thời điểm phim kinh dị đang bão hòa như hiện nay. 37 tiếng sau khi con gái mất tích, ông bố David Kim quyết định tự mình điều tra sự thật. Đến lúc này, ông bàng hoàng nhận ra một điều rằng: Hóa ra từ trước đến nay ông không hề hiểu gì về cuộc sống của cô con gái 16 tuổi cả. Bộ phim như một câu hỏi lớn đặt ra đối với tất cả các bậc phụ huynh: Liệu trong thời buổi công nghệ hiện nay, họ hiểu con cái của mình được bao nhiêu?</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cho","avatar":""},{"name":"Michelle La","avatar":""},{"name":"Debra Messing","avatar":""},{"name":"Joseph Lee","avatar":""},{"name":"Sara Sohn","avatar":""},{"name":"Briana McLean","avatar":""},{"name":"Erica Jenkins","avatar":""},{"name":"Connor McRaith","avatar":""},{"name":"Dominic Hoffman","avatar":""},{"name":"Ric Sarabia","avatar":""},{"name":"Steven Michael Eich","avatar":""},{"name":"Melissa Disney","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Ben Cain","avatar":""},{"name":"Alex Jayne Go","avatar":""},{"name":"Megan Liu","avatar":""},{"name":"Kya Dawn Lau","avatar":""},{"name":"Colin Woodel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c