INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-dong-vat', 'Thế Giới Động Vật', 'Animal World', 'https://phimimg.com/upload/vod/20231124-1/efcd7fc51553aa3575f8576c8e5a4dd5.jpg', 'https://phimimg.com/upload/vod/20231124-1/d24437b7bba31aa8d1ecec68f29770ad.jpg', '<p>Thế Giới Động Vật được cải biên từ tác phẩm truyện tranh Ultimate Survivor Kaiji của tác giả Nobuyuki Fukumoto. Chàng trai chẳng làm được chuyện gì nên hồn - Trịnh Khai Tư &nbsp;- tham gia vào một trò chơi sinh tử đầy bí ẩn trên con tàu hạng sang nhằm trả nợ. Cách tính điểm của cuộc đấu này được dựa trên phương thức &quot;oẳn tù tì&quot;. Vì người mẹ đang hôn mê và cô bạn thanh mai trúc mã Lưu Thanh, Trịnh Khai Tư buộc phải sống sót trở về.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yifeng","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Cao Bingkun","avatar":""},{"name":"Wang Ge","avatar":""},{"name":"Su Ke","avatar":""},{"name":"Wu Yanshu","avatar":""},{"name":"Yao Anlian","avatar":""},{"name":"Lei Han","avatar":""},{"name":"Li Yijuan","avatar":""},{"name":"Yi Yunhe","avatar":""},{"name":"Keith Shillitoe","avatar":""},{"name":"Alberto Lancellotti","avatar":""},{"name":"Chi Jia","avatar":""},{"name":"Zhang Junyi","avatar":""},{"name":"Wang Fang","avatar":""},{"name":"Chen Zhixi","avatar":""},{"name":"Jia Qingru","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
