INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-bong-kinh-hoang', 'Trận Bóng Kinh Hoàng', 'Final Score', 'https://phimimg.com/upload/vod/20231124-1/fc317f31b89017ffd3179f764635f865.jpg', 'https://phimimg.com/upload/vod/20231124-1/ec76816543214a0d1553374ddfcea363.jpg', '<p>Tin rằng gã anh trai phản bội Dimitri ( Pierce Brosnan) đang lẩn trốn đâu đó tại sân vận động Boleyn Ground nơi diễn ra trận bán kết tranh cúp Châu Âu giữa hai đội tuyển West Ham United và Dynamo FCC, Arkady ( Ray Stevenson), tên cầm đầu cuộc cách mạng tại bang Sukovia ở nước Nga đã phong tỏa toàn bộ sân vận động khiến nội bất xuất, ngoại bất nhập để truy tìm kẻ thù. Trong đám đông có mặt tại đó, Mike Knox ( Dave Bautista) và đứa cháu của mình Danni ( Lara Peake) đã vô tình có mặt tại trận cầu sống còn và phải đối mặt với băng nhóm nguy hiểm của tên Arkady. Liệu Mike có kịp thời ngăn chăn Arkady trước khi hắn tìm thấy Dimitri? Sự sống của 35,000 người có mặt tại sân vận động và người dân nước Nga phụ thuộc cả vào anh…</p>', 'Full', 1, 'single', 'completed', 8, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Amit Shah","avatar":""},{"name":"Lara Peake","avatar":""},{"name":"Alexandra Dinu","avatar":""},{"name":"Lucy Gaskell","avatar":""},{"name":"Martyn Ford","avatar":""},{"name":"Gordon Alexander","avatar":""},{"name":"Peter Pedrero","avatar":""},{"name":"Nick Rowntree","avatar":""},{"name":"Lee Rogers","avatar":""},{"name":"Craig Conway","avatar":""},{"name":"Rian Gordon","avatar":""},{"name":"Bill Fellows","avatar":""},{"name":"Matthew Lorenzo","avatar":""},{"name":"Tony Cottee","avatar":""},{"name":"Rufus Brevet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id"