INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-vien-kinh-hoang', 'Tu Viện Kinh Hoàng', 'St. Agatha', 'https://phimimg.com/upload/vod/20231124-1/238916158b48ef6839d8420f04628177.jpg', 'https://phimimg.com/upload/vod/20231124-1/6927a114dfb4d17f152f7e7717cee721.jpg', '<p>Phim Tu Viện Kinh Hoàng - St. Agatha (2019) :Ác quỷ ma sơ không cần phải là Valak. Bộ phim này sẽ chứng minh điều đó. Khi Mary mang trong bụng đứa con của mình, cũng là lúc cô tuyệt vọng nhất: phải bỏ lại người bạn trai không đủ khả năng để lập gia đình, bị xã hội khinh miệt và cô không có gì ngoài nghề lừa đảo. Mary tìm đến một tu viện bí ẩn, nơi có những ma sơ dang rộng vòng tay chào đón cô với câu nói: “chúng tôi chăm sóc những phụ nữ như cô”. Mary không hề ngờ rằng, ẩn sau những nụ cười thánh thiện đó là những bí mật kinh hoàng của những người phụ nữ mượn danh tôn giáo để thực hiện điều sai trái. Cùng với các thai phụ khác trong tu viện, Mary phải làm mọi cách để thoát ra để bảo vệ đứa con sắp chào đời của mình. Liệu Mary có thành công?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sabrina Kern","avatar":""},{"name":"Carolyn Hennesy","avatar":""},{"name":"Courtney Halverson","avatar":""},{"name":"Seth Michaels","avatar":""},{"name":"Trin Miller","avatar":""},{"name":"Lindsay Seim","avatar":""},{"name":"Jayson Warner Smith","avatar":""},{"name":"Hannah Fierman","avatar":""},{"name":"Shaun Fletcher","avatar":""},{"name":"Maximus Murrah","avatar":""},{"name":"Marsha Fee Berger","avatar":""},{"name":"Rachael Gavrielli","avatar":""},{"name":"Myles Cranford","avatar":""},{"name":"Geoffrey Gould","avatar":""},{"name":"Marion Guyot","avatar":""},{"name":"Bobby C.","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
