INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-pham-an-danh', 'Thủ Phạm Ẩn Danh', 'Eve of Abduction', 'https://phimimg.com/upload/vod/20231123-1/ebaf41e8cb86c2b3cfb93f2779188e9f.jpg', 'https://phimimg.com/upload/vod/20231123-1/b15eb4f3821ce60482d143d80863a6da.jpg', '<p>Thủ Phạm Ẩn Danh - Eve of Abduction là bộ phim kể về câu chuyện sau khi một người mẹ nhận lời cầu hôn của người tình mới. Cô bắt đầu nhận được tin nhắn từ một kẻ theo dõi ẩn danh, đe dọa sẽ bắt cóc con gái mình nếu cô không phá vỡ hôn ước. Các mối nguy hiểm luôn rình rập con gái của cô. Và mối đe dọa thực sự là ai?</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Lind","avatar":""},{"name":"Chrishell Stause","avatar":""},{"name":"Robb Derringer","avatar":""},{"name":"Betsy Randle","avatar":""},{"name":"Wolfgang Bodison","avatar":""},{"name":"Philip Boyd","avatar":""},{"name":"Braeden Carl","avatar":""},{"name":"C.J. Valleroy","avatar":""},{"name":"Dylan Raine Woods","avatar":""},{"name":"Jean St. James","avatar":""},{"name":"Julia Farino","avatar":""},{"name":"Lindsay Hanzl","avatar":""},{"name":"Marcy Goldman","avatar":""},{"name":"David Bickford","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
