INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tuan-de-chet', 'Một Tuần Để Chết', 'Dead in a Week (Or Your Money Back)', 'https://phimimg.com/upload/vod/20231123-1/8ca11d223b3aacd7ea579dd71ef9f6b2.jpg', 'https://phimimg.com/upload/vod/20231123-1/e808788d60149d2985110610ca31137a.jpg', '<p>phim theo chân Leslie ( Tom Wilkinson ), một tay sát thủ già cỗi đang chuẩn bị về hưu, rửa tay gác kiếm nhưng lại chưa đáp ứng đủ chỉ tiêu hàng năm của mình với Hiệp hội sát thủ Anh. Ông chủ không chính thức của ông là Harvey ( Christopher Eccleston ) đã đặt cho ông một thời hạn. Thời hạn đó buộc Leslie phải dùng đến biện pháp cuối cùng, là cắm trại ở các địa điểm tự sát và lựa chọn một số đối tượng. Về phía Chelsea Bridge, anh ta phải vật lộn với nhà văn William ( Aneurin Barnard) và Leslie đã đưa ra một thỏa thuận, rằng trả tiền hoặc chết trong vòng một tuần. Nhưng với thỏa thuận đã ký, William cuối cùng lại tìm được cảm giác an toàn, khiến anh ta tự hỏi rằng liệu thoả thuận đó có phải là điều mà anh ta thực sự muốn hay không.&nbsp;</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Aneurin Barnard","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Freya Mavor","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Marion Bailey","avatar":""},{"name":"Velibor Topic","avatar":""},{"name":"Nigel Lindsay","avatar":""},{"name":"Gethin Anthony","avatar":""},{"name":"Marcia Warren","avatar":""},{"name":"Emma Campbell-Jones","avatar":""},{"name":"Nathalie Buscombe","avatar":""},{"name":"Carol MacReady","avatar":""},{"name":"Harry Collett","avatar":""},{"name":"Orion Lee","avatar":""},{"name":"Eileen Nicholas","avatar":""},{"name":"James Kermac","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3