INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-cuong-nhiet', 'Thanh Xuân Cuồng Nhiệt', 'Colossal Youth', 'https://phimimg.com/upload/vod/20231123-1/79c7bfd0a63f7c2dbc3ced035f130c53.jpg', 'https://phimimg.com/upload/vod/20231123-1/6a2163f49fd02cb6ad57ce8e646b19b8.jpg', '<p>Thanh Xuân Cuồng Nhiệt - Colossal Youth kể về MColossal Youth theo chân bốn người bạn Ryder (Troy Osterberg), Greg (Riker Lynch), Erica (Kimmy Caruso) và Jordan (Reese Everett Ryan) khi họ điều hướng cuộc sống, tình yêu và khoảng thời gian hoang dã và điên rồ của trường trung học. Ryder là một người lãng mạn vô vọng và khi nỗi ám ảnh về cô gái trong mộng của anh ta là Siobhan (Alexa Dowd) trở lại trường học, anh ta đã thất bại khi cố gắng giành lấy trái tim của cô ấy.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Troy Osterberg","avatar":""},{"name":"Kimmy Caruso","avatar":""},{"name":"Riker Lynch","avatar":""},{"name":"Jesse Borrego","avatar":""},{"name":"Reece Everett Ryan","avatar":""},{"name":"Alexa Dowd","avatar":""},{"name":"P.G. Marlar","avatar":""},{"name":"Lori Crow","avatar":""},{"name":"Paul Matthew Lopez","avatar":""},{"name":"James E. Morris III","avatar":""},{"name":"Peggy Schott","avatar":""},{"name":"Valeria Jauregui","avatar":""},{"name":"William Austin Barker","avatar":""},{"name":"Anastasia Antonia","avatar":""},{"name":"Destiny Baldwin","avatar":""},{"name":"Rydel Lyn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324395);
