INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-tai-cung-dien', 'Giáng sinh tại cung điện', 'Christmas at the Palace', 'https://phimimg.com/upload/vod/20231121-1/b277433652f9e668474485a97e977848.jpg', 'https://phimimg.com/upload/vod/20231121-1/024cd239346ec432b5b05ee35d8dc899.jpg', '<p>Một chuyện tình hoàng gia có thể là món quà của biên đạo trượt băng Katie vào Giáng sinh này, nhưng làm sao cô có thể chọn giữa tình yêu và sự nghiệp mơ ước ở quê nhà?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Merritt Patterson","avatar":""},{"name":"Andrew Cooper","avatar":""},{"name":"Brittany Bristow","avatar":""},{"name":"Nicholas Banks","avatar":""},{"name":"Geraldine Fitzgerald","avatar":""},{"name":"India Fowler","avatar":""},{"name":"Esh Alladi","avatar":""},{"name":"Antonio Aakeel","avatar":""},{"name":"Reece Griffin","avatar":""},{"name":"Linda Marshall Miller","avatar":""},{"name":"Zsolt Kerekes","avatar":""},{"name":"Ingrid Pricop","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324395);
