INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-kinh-doc-dao', 'Ống Kính Độc Đáo', 'Claire''s Camera', 'https://phimimg.com/upload/vod/20231121-1/7a7077b994a9dc841f30f7a43c8822fe.jpg', 'https://phimimg.com/upload/vod/20231121-1/bfdf6bc41088d6d3240d00018cbd03c0.jpg', '<p>Nội dung của Claire’s Camera xoay quanh hành trình kết thân lạ kỳ của hai nhân vật: Claire (Isabelle Huppert) – một giáo viên lớn tuổi người Pháp nhưng rất yêu nghệ thuật, lặn lội từ Paris sang Cannes để tham dự buổi ra mắt phim của một người bạn; và Man-hee (Kim Min-hee) – một nhân viên tiếp thị phim đến từ Hàn Quốc vừa bị sếp đuổi việc vì cho rằng cô đang dan díu với nhân tình của mình. Từ chỗ không quen biết, Claire vô tình gặp được Man-hee khi đang đi dạo trên bãi biển. Hai người trở thành bạn đồng hạnh của nhau tại Cannes, để rồi liên tục “xoắn” vào nhau bởi những sự trùng hợp hết sức kỳ quặc.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Isabelle Huppert","avatar":""},{"name":"Kim Min-hee","avatar":""},{"name":"Chang Mi-hee","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Shahira Fahmy","avatar":""},{"name":"Yoon Hee-sun","avatar":""},{"name":"Mark Peranson","avatar":""},{"name":"Kang Tae-u","avatar":""},{"name":"Lee Wan-min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
