INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-ngoai-luong', 'Cuộc Tình Ngoài Luồng', 'Doubting Thomas', 'https://phimimg.com/upload/vod/20231120-1/146034b6cbd5ae547b5588470e3c65e8.jpg', 'https://phimimg.com/upload/vod/20231120-1/22b8159515f08c0b69eef0c5cdab24f7.jpg', '<p>Sau khi một cặp vợ chồng da trắng sinh ra một đứa trẻ da đen một cách không thể giải thích được, những mối liên kết thuần khiết nhất của lòng tin, tình bạn và tình yêu được đưa vào thử thách cuối cùng.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will McFadden","avatar":""},{"name":"Sarah Butler","avatar":""},{"name":"Jamie Hector","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"James Morrison","avatar":""},{"name":"Mike Bash","avatar":""},{"name":"Robert Belushi","avatar":""},{"name":"Alicia Blasingame","avatar":""},{"name":"Kendall Chappell","avatar":""},{"name":"Zach Cregger","avatar":""},{"name":"Christopher Drummond","avatar":""},{"name":"Crista Flanagan","avatar":""},{"name":"Chuma Gault","avatar":""},{"name":"Sharon Houston","avatar":""},{"name":"Shaun O''Hagan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
