INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ung-dung-hen-ho', 'Ứng Dụng Hẹn Hò', 'Swiped', 'https://phimimg.com/upload/vod/20231123-1/7b07427d5e54d96e85c5881c065b2cd2.jpg', 'https://phimimg.com/upload/vod/20231123-1/f74899ff435e3ed74b4e56a03bc3798f.jpg', '<p>James, một sinh viên năm nhất đại học và là một thiên tài máy tính, được người bạn cùng phòng lăng nhăng của anh, Lance, mời viết mã cho ứng dụng kết nối cuối cùng. Nhưng khi James phát hiện ra rằng người mẹ đã ly hôn của mình đang sử dụng ứng dụng này, những hậu quả bất ngờ đã xảy ra.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Centineo","avatar":""},{"name":"Kristen Johnston","avatar":""},{"name":"George Hamilton","avatar":""},{"name":"Kendall Ryan Sanders","avatar":""},{"name":"Leigh-Allyn Baker","avatar":""},{"name":"Nathan Gamble","avatar":""},{"name":"Maddy Curley","avatar":""},{"name":"Christian Hutcherson","avatar":""},{"name":"Kalani Hilliker","avatar":""},{"name":"Shein Mompremier","avatar":""},{"name":"Steve Daron","avatar":""},{"name":"Chase Victoria","avatar":""},{"name":"Alana Stewart","avatar":""},{"name":"Shelby Wulfert","avatar":""},{"name":"Nina Millin","avatar":""},{"name":"Andre","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324395);
