INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-chien-ky', 'Phong Thần Chiến Kỷ', 'The War Records of Deification', 'null', 'https://phimimg.com/upload/vod/20231123-1/69e1a88d522196f139ba23f20388d77d.jpg', '<p>Một câu chuyện trong truyền thuyết kể về con người khi họ sống qua thời kỳ hòa bình rơi vào thời kỳ chiến tranh và hỗn loạn. Nó theo chân Jiang Shang đến tận triều đại nhà Thương khi anh đối đầu với Xin Emperor.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ian Yi","avatar":""},{"name":"Yu Yijie","avatar":""},{"name":"Zhang Zixuan","avatar":""},{"name":"Chen Haoming","avatar":""},{"name":"Chu Qian","avatar":""},{"name":"Kan Benben","avatar":""},{"name":"Qian Zhu","avatar":""},{"name":"Li Ruichao","avatar":""},{"name":"Marco Lo Chi-Fung","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324395);
