INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-than-chien-ky', 'Phong Thần Chiến Kỷ', 'The War Records of Deification', 'phong thần chiến kỷ the war records of deification ian yi yu yijie zhang zixuan chen haoming chu qian kan benben qian zhu li ruichao marco lo chi-fung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-ngua-gia', 'Chú Ngựa Già', 'Lean on Pete', 'https://phimimg.com/upload/vod/20231123-1/bf004f9282853fbd2b15910876e19c03.jpg', 'https://phimimg.com/upload/vod/20231123-1/61d227a1316df4aa5b5f1c46cdff5d7c.jpg', '<p>Thiếu niên mười lăm tuổi Charley Thompson (do Charlie Plummer đóng vai) đến Portland, Oregon, cùng với người cha độc thân Ray (do Travis Fimmel đóng vai). Cả hai cha con đều mong muốn có một khởi đầu mới sau một loạt thử thách gian nan. Trong khi ông Ray rơi vào một cuộc khủng hoảng riêng tư, Charley nhận được tình bạn thân thiết tại một đường đua địa phương, nơi thiếu niên giữ việc chăm sóc một con ngựa quý đang già đi, có tên là Lean On Pete (dựa vào Pete). Ông chủ thô bạo Delton Montgomery (do Steve Buscemi đóng vai) của đội đua ngựa, và Bonnie (do Chlo Sevigny đóng vai) đã giúp Charley lấp đầy khoảng trống do cha em để lại. Thế rồi Charleykhám phá ra rằng Pete sắp bị giết vì già, khiến em nghĩ đến một giải pháp liều lĩnh để cứu mạng con ngựa. Charley và Pete thực hiện một chuyến phiêu lưu vào miền hoang dã của nước Mỹ, để tìm kiếm một người cô yêu quý mà Charley đã không gặp trong nhiều năm. Đôi bạn đã trải qua những khổ đau trong cuộc phiêu lưu, nhưng không bao giờ đánh mất niềm hy vọng và sự linh động, để theo đuổi giấc mơ tìm cho được một nơi dung thân và có thể gọi là nhà.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Charlie Plummer","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Justin Rain","avatar":""},{"name":"Lewis Pullman","avatar":""},{"name":"Bob Olin","avatar":""},{"name":"Alison Elliott","avatar":""},{"name":"Rachael Perrell Fosket","avatar":""},{"name":"Kurt Conroyd","avatar":""},{"name":"Travis Fimmel","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Amy Seimetz","avatar":""},{"name":"Frank Gallegos","avatar":""},{"name":"Julia Prud''homme","avatar":""},{"name":"Jason Beem","avatar":""},{"name":"Tolo Tuitele","avatar":""},{"name":"Ayanna Berk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324395);
