INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dam-phan-sinh-tu', 'Cuộc Đàm Phán Sinh Tử', 'The Negotiation', 'https://phimimg.com/upload/vod/20231123-1/91f66d4bac25312f83267b9fd83c811e.jpg', 'https://phimimg.com/upload/vod/20231123-1/0ddd1fce010426286cee7ad0ca0c1507.jpg', '<p>Ha Chae-youn (Son Ye-jin) là cảnh sát giỏi nhất của đội Đàm phán khủng hoảng, cô luôn giữ một cái đầu lạnh trong mọi tình huống. Tuy nhiên cô rơi vào một cú sốc lớn khi một vụ bắt cóc đã kết thúc trong thảm kịch, cô chứng kiến kẻ bắt cóc và con tin bị giết ngay trước mắt mình. Chỉ 10 ngày sau đó, Min Tae-gu (Hyun Bin), một kẻ buôn bán vũ khí khét tiếng bị cảnh sát truy nã, bắt cóc một phóng viên và một cảnh sát người Hàn và chỉ định Chae-youn là người đàm phán. Tình huống nguy hiểm chưa từng có khiến Chae-youn không thể lùi bước, và sự thật kinh hoàng đằng sau dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Hyun Bin","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Kim Jong-goo","avatar":""},{"name":"Kim Min-sang","avatar":""},{"name":"Han Gi-joong","avatar":""},{"name":"Yoo Yeon-soo","avatar":""},{"name":"Park Su-young","avatar":""},{"name":"Choi Byung-mo","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Lee Joo-young","avatar":""},{"name":"Lee Si-a","avatar":""},{"name":"Lee Moon-sik","avatar":""},{"name":"Jung In-gyeom","avatar":""},{"name":"Ahn Seong-bong","avatar":""},{"name":"Kim Bo-min","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
