INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-47-den-toi', 'Năm 47 Đen Tối', 'Black ''47', 'https://phimimg.com/upload/vod/20231123-1/909f8bffb9dfda9037d1b656c0135995.jpg', 'https://phimimg.com/upload/vod/20231123-1/605ad5abfa4dd19d4ce32685616c725a.jpg', '<p>Trong thời kỳ nạn đói xảy ra ở Ai-Len năm 1847, một người Ai-Len tên là Hannah đã chiến đấu trong quân đội Anh ở nước ngoài, ông từ bỏ vị trí của mình để trở về đoàn tụ với gia đình. Dù đã trải qua những kinh hoàng trong chiến tranh nhưng ông vẫn bị sốc khi chứng kiến nạn đói và bệnh tật ở quê hương ảnh hưởng đến người dân cũng như với gia đình của mình.</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Hugo Weaving","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Freddie Fox","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Moe Dunford","avatar":""},{"name":"Sarah Greene","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Ruairí Heading","avatar":""},{"name":"Aidan McArdle","avatar":""},{"name":"Fiach Kunz","avatar":""},{"name":"Julian Nest","avatar":""},{"name":"Brandon Maher","avatar":""},{"name":"Ciaran Grace","avatar":""},{"name":"Kieran Boland","avatar":""},{"name":"Joe Lydon","avatar":""},{"name":"Ryan McAllis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324395);
