INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-deo-bam-xinh-dep', 'Kẻ Đeo Bám Xinh Đẹp', 'Pretty Little Stalker', 'https://phimimg.com/upload/vod/20231123-1/136ce7ed9be76bb59e2b84d93c491529.jpg', 'https://phimimg.com/upload/vod/20231123-1/7dbc2c3db345e04256622b0065d341f4.jpg', '<p>Lorna Sisco là một tác giả nổi tiếng chuyên viết sách cho phụ nữ. Cô có một cuộc sống như mơ, với người chồng hết đỗi yêu thương mình và cậu con trai ngoan ngoãn. Bỗng nhiên, nhiều sự việc kỳ quái xảy ra sau khi một cô gái lạ mặt xuất hiện trong cuộc đời họ.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicky Whelan","avatar":""},{"name":"Ashley Rickards","avatar":""},{"name":"Jesse Hutch","avatar":""},{"name":"Parker Mack","avatar":""},{"name":"Jason Cermak","avatar":""},{"name":"Heather Morris","avatar":""},{"name":"Sierra McCormick","avatar":""},{"name":"Cory Hart","avatar":""},{"name":"Sarah Cleveland","avatar":""},{"name":"Jane Harber","avatar":""},{"name":"Kim DeJesus","avatar":""},{"name":"Kourtney Hansen","avatar":""},{"name":"Brady Gentry","avatar":""},{"name":"Nicholas David King","avatar":""},{"name":"Victoria Winn","avatar":""},{"name":"Jordan Bryant","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
