INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-hoi-toi-nen-di-dau', 'Trái tim hỡi, tôi nên đi đâu?', 'Jaoon Kahan Bata Ae Dil', 'https://phimimg.com/upload/vod/20231123-1/a2b434ac3705c6f5086702cd9cd10710.jpg', 'https://phimimg.com/upload/vod/20231123-1/81da211525489a3835856e3961563bf3.jpg', '<p>Những mâu thuẫn khó chịu ngày càng tăng của cặp đôi nọ trong một buổi tối ở Mumbai đẩy sự căng thẳng trong mối quan hệ giữa họ lên cao trào và đe dọa sẽ khiến nó rạn nứt.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Rohit Kokate","avatar":""},{"name":"Khushboo Upadhyay","avatar":""},{"name":"Himanshu Kohli","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324395);
