INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-khong-mat', 'Gã Không Mặt', 'Slender Man', 'https://phimimg.com/upload/vod/20231123-1/1dba20a577a1eafb75bb9c310a0ac38b.jpg', 'https://phimimg.com/upload/vod/20231123-1/235bc6139334cc856f95ec7b150b3e62.jpg', '<p>Slender Man được biết đến như một nhân vật kinh dị đầy hãi hùng, hiện thân trong hình tượng của người đàn ông mặc vest lịch lãm nhưng đáng sợ với gương mặt trống trơn, thân người cao bất thường. Gã Không Mặt Slender Man là cơn ác mộng cho những vụ mất tích bí ẩn của những thiếu niên bị dẫn lối vào rừng sâu cùng với tinh thần điên đảo không tìm được lối thoát…Slender man xâm nhập vào tâm trí rồi dần lan truyền và tước quyền kiểm soát từ não bộ cho đến thân xác vật chủ, biến họ trở thành kẻ nô bộc phục dịch cho ý muốn của hắn. Nạn nhân của Slender Man hầu hết là trẻ em, người thì mất tích, người thì hóa điên dại, có người tự sát.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Javier Botet","avatar":""},{"name":"Joey King","avatar":""},{"name":"Julia Goldani Telles","avatar":""},{"name":"Jaz Sinclair","avatar":""},{"name":"Annalise Basso","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Alex Fitzalan","avatar":""},{"name":"Miguel Nascimento","avatar":""},{"name":"Michael Reilly Burke","avatar":""},{"name":"Jessica Blank","avatar":""},{"name":"Kayla Caulfield","avatar":""},{"name":"Jeffrey Corazzini","avatar":""},{"name":"Michael Tow","avatar":""},{"name":"Adrian M. Mompoint","avatar":""},{"name":"Danny Beaton","avatar":""},{"name":"Taylor Ri","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
