INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ga-khong-mat', 'Gã Không Mặt', 'Slender Man', 'gã không mặt slender man javier botet joey king julia goldani telles jaz sinclair annalise basso kevin chapman alex fitzalan miguel nascimento michael reilly burke jessica blank kayla caulfield jeffrey corazzini michael tow adrian m. mompoint danny beaton taylor ri ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tinh-yeu-ban-dien-anh', 'Bẫy Tình Yêu (Bản Điện Ảnh)', 'Cheese in the Trap', 'https://phimimg.com/upload/vod/20231123-1/33176e1bc557278642949c7e6c06f7c6.jpg', 'https://phimimg.com/upload/vod/20231123-1/bd913609afc4363f7da5e6410f3535b1.jpg', '<p>Sau khi làm mưa làm gió mùa Valentine năm 2016, kịch bản tình yêu trường đại học của Cheese In The Trap một lần nữa lại được dựng thành phim để chiếu trên màn ảnh rộng. Bản thân bộ truyện cùng tên vốn đã cực kỳ nổi tiếng trên mạng xã hội Hàn Quốc, cộng thêm dư âm của bộ phim truyền hình ồn ào chiếu trên đài cáp tvN, phiên bản điện ảnh Cheese In The Trap (Bẫy Tình Yêu) lần này được trông ngóng ngay từ thời điểm tháng 8/2016 khi nam diễn viên Park Hae Jin gật đầu đóng tiếp vai nam chính. Vì hoàn cảnh khốn khó mà Hong Seol (Oh Yeon-Seo) phải đi làm thêm để trang trải cuộc sống. Trong khi đó, Yoo Jung (Park Hae Jin), một quý ngài hoàn hảo, anh ta có mọi thứ: gia thế, học thức, ngoại hình, sức khỏe, kể cả tính cách. Thế nhưng, ẩn sau những điều tưởng như hoàn mĩ đó là góc khuất đen tối trong tâm hồn chàng thanh niên này. Người sẽ hóa giải cho những vấn đề của anh chính là cô nữ sinh hạng thường Hong Seol.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hae-jin","avatar":""},{"name":"Oh Yeon-seo","avatar":""},{"name":"Park Ki-woong","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Oh Jong-hyuk","avatar":""},{"name":"Sandara Park","avatar":""},{"name":"Moon Ji-yoon","avatar":""},{"name":"Kim Hyun-jin","avatar":""},{"name":"Na Hye-mi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324395);
