INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-bat-dac-di', 'Anh Hùng Bất Đắc Dĩ', 'Game Over, Man!', 'https://phimimg.com/upload/vod/20231120-1/8fdfd174e688d8371707c887c0f03655.jpg', 'https://phimimg.com/upload/vod/20231120-1/9bfec3cc14d95f09b0f0cefb4ab6fd26.jpg', '<p>Phim Game Over, Man! - Anh Hùng Bất Đắc Dĩ là một bộ phim hài hước pha lẫn hành động, nội dung xoay quanh 3 chàng trai vô danh bỗng chốc trở thành những người hùng, khi khách sạn nơi họ ở, đồng thời cũng là nơi tổ chức một bữa tiệc đầy những ngôi sao, trở thành mục tiêu tấn công của một nhóm khủng bố. Tất cả các vị khách nổi tiếng bị bắt giữ làm con tin, trong đó có cả người tài trợ cho dự án video game của ba chàng trai. Họ quyết định giải cứu những con tin, và những người hùng bất đắc dĩ ấy nhanh chóng lâm vào những tình huống hành động tréo ngoe dở khóc dở cười. Ngoài ra, phim Game Over, Man! - Anh Hùng Bất Đắc Dĩ (2018) còn có sự góp mặt của 3 cây hài tương ứng 3 chàng vai chính trong phim Steve Howey, Lochlyn Munro, Sugar Lyn Beard hứa hẹn sẽ là tác phẩm ăn khách của hãng phim Netflix.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Devine","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"Blake Anderson","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Jamie Demetriou","avatar":""},{"name":"Aya Cash","avatar":""},{"name":"Daniel Stern","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Mac Brandt","avatar":""},{"name":"Geno Segers","avatar":""},{"name":"Roe Hartrampf","avatar":""},{"name":"Andrew Bachelor","avatar":""},{"name":"Chloe Bridges","avatar":""},{"name":"Jere Burns","avatar":""},{"name":"Sugar Lyn Be","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324395);
