INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-dat-ngoai-khong-gian', 'Trôi Dạt Ngoài Không Gian', 'Solis', 'https://phimimg.com/upload/vod/20231120-1/8714f18824577764de6a55d9e7b77333.jpg', 'https://phimimg.com/upload/vod/20231120-1/a8ee8e24e605aff8a61a59940b4ab88f.jpg', '<p>Sau hoạt động khai thác không gian trở nên tồi tệ, Troy lên tàu thoát hiểm khẩn cấp và bị trôi về phía mặt trời. Chỉ có chiếc radio để liên lạc dưới mặt đất, liệu anh ta có thoát khõi bi kịch này không?</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Steven Ogg","avatar":""},{"name":"Alice Lowe","avatar":""},{"name":"Kate Coogan","avatar":""},{"name":"Henry Douthwaite","avatar":""},{"name":"Charlette Kilby","avatar":""},{"name":"Sid Phoenix","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324396);
