INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-da-canh-buom', 'Những đứa trẻ da cánh bướm', 'Butterfly Children', 'https://phimimg.com/upload/vod/20231120-1/53c537d62e83b642eb04dc21a0c6eab7.jpg', 'https://phimimg.com/upload/vod/20231120-1/5f1352d9584b1a97541603542843b463.jpg', '<p>Bộ phim tài liệu này chia sẻ những câu chuyện, khó khăn và hi vọng của bốn gia đình Singapore đang sống với căn bệnh khiến da trở nên vô cùng mong manh.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Singapore', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324396);
