INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-dam-mau', 'Anh em đẫm máu', 'Blood Brother', 'https://phimimg.com/upload/vod/20231120-1/278087470f5acf14bc915b0798028411.jpg', 'https://phimimg.com/upload/vod/20231120-1/df3659f01d911f99ced4b6d0f3d1e132.jpg', '<p>Blood Brother diễn ra trên những con phố của một thành phố đang suy tàn, nơi một kẻ bị kết án vừa mới được thả bắt đầu thực hiện một cuộc trả thù giết người chống lại những người bạn thời thơ ấu của mình, những người mà anh ta tin rằng đã để anh ta phải chịu tội ác mà họ đã cùng nhau phạm phải. Khi các thi thể bắt đầu chồng chất, một trong những người bạn, hiện là cảnh sát, sẽ không dừng lại ở việc chấm dứt vụ giết người hung hãn và sửa chữa nhiều sai lầm trong quá khứ bạo lực bi thảm của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Trey Songz","avatar":""},{"name":"Jack Kesy","avatar":""},{"name":"China Anne McClain","avatar":""},{"name":"Chelle Ramos","avatar":""},{"name":"Hassan Johnson","avatar":""},{"name":"Fetty Wap","avatar":""},{"name":"J.D. Williams","avatar":""},{"name":"Joy Lofton","avatar":""},{"name":"Bill Martin Williams","avatar":""},{"name":"Ron Killings","avatar":""},{"name":"Lindsay Musil","avatar":""},{"name":"Tanee McCall","avatar":""},{"name":"Tony Donno","avatar":""},{"name":"Tim Bell","avatar":""},{"name":"Ann McKenzie","avatar":""},{"name":"Rajeev Jacob","avatar":""},{"name":"Noëlle Renée Bercy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]',