INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nhan-cua-oan-hon', 'Lời Nhắn Của Oan Hồn', 'I Still See You', 'https://phimimg.com/upload/vod/20231120-1/ff73ab89698ca937db2ce2ff19c8989b.jpg', 'https://phimimg.com/upload/vod/20231120-1/f072e90fcef9efc20de843c8fbbd2330.jpg', '<p>Mười năm sau thảm hoạ hạt nhân tại Chicago, thế giới tồn tại khe nứt giữa người sống và người chết. Ronnie nhận được một thông điệp đe dọa từ một hồn ma xa lạ. Cô cùng một người bạn bí ẩn, Kirk, rơi vào thế giới bóng ma, và bắt đầu một cuộc đua tuyệt vọng với thời gian đối đầu một tên giết người xảo quyệt. Khi quá khứ không bao giờ ngủ yên, liệu Ronnie có thể trở về an toàn?</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bella Thorne","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Amy Price-Francis","avatar":""},{"name":"Shaun Benson","avatar":""},{"name":"Louis Herthum","avatar":""},{"name":"Thomas Elms","avatar":""},{"name":"Sara Thompson","avatar":""},{"name":"David Brown","avatar":""},{"name":"Hugh Dillon","avatar":""},{"name":"Stephanie Moroz","avatar":""},{"name":"Micah Kennedy","avatar":""},{"name":"Marina Stephenson Kerr","avatar":""},{"name":"Cassandra Potenza","avatar":""},{"name":"Danika Frederick","avatar":""},{"name":"Arden Alfonso","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324396);
