INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-quanh-the-gioi', 'Vòng Quanh Thế Giới', 'The Mercy', 'https://phimimg.com/upload/vod/20231201-1/3fd9ed8c6e330e3f50321565b4304f69.jpg', 'https://phimimg.com/upload/vod/20231201-1/95259b749b618f4c2538ac9f068499b3.jpg', '<p>Phim là câu chuyện đáng kinh ngạc của thủy thủ nghiệp dư Donald Crowhurst và nỗ lực của ông để đi vòng quanh thế giới một mình. Những cuộc đấu tranh mà anh gặp phải trong cuộc hành trình trong khi gia đình anh chờ đợi sự trở lại của anh là một trong những bí ẩn lâu dài nhất trong thời gian gần đây.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Genevieve Gaunt","avatar":""},{"name":"Jonathan Bailey","avatar":""},{"name":"Andrew Buchan","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Eleanor Stagg","avatar":""},{"name":"Ken Stott","avatar":""},{"name":"Finn Elliot","avatar":""},{"name":"Kit Connor","avatar":""},{"name":"Oliver Maltman","avatar":""},{"name":"Sam Hoare","avatar":""},{"name":"Avye Leventis","avatar":""},{"name":"Anna Madeley","avatar":""},{"name":"Adrian Schiller","avatar":""},{"name":"Simon Chand","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324396);
