INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-dat-tot-lanh', 'Miền Đất Tốt Lành', 'Goodland', 'https://phimimg.com/upload/vod/20231201-1/c3946b058bfd378c9667e47a9049a1b0.jpg', 'https://phimimg.com/upload/vod/20231201-1/3999f94c91e83120740fdb2ea25aa2db.jpg', '<p>Cái chết của một kẻ vô gia cư cùng với sự xuất hiện nhiếp ảnh gia kỳ lạ đã làm xáo trộn mọi thứ ở Goodland. Nữ cảnh sát trưởng Gaines đã ghép nối những sự kiện, thông tin tưởng như không liên quan đến nhau nhưng nó lại giúp cô vén lên bức màn sự thật.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Weiss","avatar":""},{"name":"Cinnamon Schultz","avatar":""},{"name":"Jason Curtis Miller","avatar":""},{"name":"Kip Niven","avatar":""},{"name":"Chris Bylsma","avatar":""},{"name":"Laura Jacobs","avatar":""},{"name":"Walter Coppage","avatar":""},{"name":"Sara Carolynn Kennedy","avatar":""},{"name":"Sarah Jean Robinson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
