INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-sinh-tu-dong-tro-tan', 'Hồi Sinh Từ Đống Tro Tàn', 'The Dawnseeker', 'https://phimimg.com/upload/vod/20231116-1/7cdcab9ec7d8e3770a72051a10ec738f.jpg', 'https://phimimg.com/upload/vod/20231116-1/98bc59ac673382d5ad8d7918ccc9188d.jpg', '<p>Trái đất vào năm 2245: 5 người được gửi đến một hành tinh xa xôi để thu thập khoáng chất Stardust, sẽ được sử dụng để hồi sinh Mặt trời đang hấp hối và cứu Trái đất. Liệu họ có thành công, khi mà có một kẻ săn mồi đang chờ họ ở đích đến.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Khu","avatar":""},{"name":"Alexander Kane","avatar":""},{"name":"Jason Skeen","avatar":""},{"name":"Alex Giuffreda","avatar":""},{"name":"Leonard Jackson","avatar":""},{"name":"Jordan Matlock","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324396);
