INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-sau-tam-guong', 'Bí Ẩn Sau Tấm Gương', 'Looking Glass', 'https://phimimg.com/upload/vod/20231116-1/04a092076766df3efa4cc56e4336aaa5.jpg', 'https://phimimg.com/upload/vod/20231116-1/5705a4eb7a43c2f40d25830fb8faf9c5.jpg', '<p>Vợ chồng Maggie và Ray quyết định mua lại một nhà nghỉ bỏ hoang để lập nghiệp ở vùng đất mới. Nhưng mỗi lần nhìn vào tấm gương dưới tầng hầm, Ray lại thấy những cảnh tượng kỳ lạ diễn ra trong căn phòng số 10. Không tin vào hiện tượng ma quỷ, Ray quyết tâm tìm ra sự thật để lật tẩy kẻ ám hại mình nhưng mọi việc không hề suôn sẻ như anh nghĩ…</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Robin Tunney","avatar":""},{"name":"Marc Blucas","avatar":""},{"name":"Ernie Lively","avatar":""},{"name":"Jacque Gray","avatar":""},{"name":"Bill Bolender","avatar":""},{"name":"Barry Jay Minoff","avatar":""},{"name":"Kassia Conway","avatar":""},{"name":"Jason K. Wixom","avatar":""},{"name":"Sila Agavale","avatar":""},{"name":"Kimmy Jimenez","avatar":""},{"name":"Pascoalina Dunham","avatar":""},{"name":"Atticus Worman-Pope","avatar":""},{"name":"Clint Vanderlinden","avatar":""},{"name":"Michael Christian","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324396);
