INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-giai-cuu-trai-dat', 'Biệt Đội Giải Cứu Trái Đất', 'Next Gen', 'https://phimimg.com/upload/vod/20231116-1/7a0fe9e092f5627f526499beff6216b8.jpg', 'https://phimimg.com/upload/vod/20231116-1/f850d8d76003ab4b21f9a246fd443f9b.jpg', '<p>Phim là sự kết hợp thú vị giữa Blade Runner và Big Hero 6. Nội dung phim xoay quanh câu chuyện về một cô gái cô đơn trong thế giới tương lai, kết bạn cùng một con robot. Tình bạn và sự đoàn kết của họ giờ đây là thứ duy nhất có thể cứu Trái đất khỏi thảm họa diệt vong.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Charlyne Yi","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"David Cross","avatar":""},{"name":"Constance Wu","avatar":""},{"name":"Kiana Ledé","avatar":""},{"name":"Anna Akana","avatar":""},{"name":"Issac Ryan Brown","avatar":""},{"name":"Reba Buhr","avatar":""},{"name":"Amber Friendly","avatar":""},{"name":"Jet Jurgensmeyer","avatar":""},{"name":"Joe Ksander","avatar":""},{"name":"Shaye Ogbonna","avatar":""},{"name":"Jon Oswald","avatar":""},{"name":"Betsy Sodaro","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Kitana Turn","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễ