INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-ngay-yeu', '7 Ngày Yêu', '7 Days', 'https://phimimg.com/upload/vod/20231120-1/cb1d43a9125b3076bbc5dbad79b928af.jpg', 'https://phimimg.com/upload/vod/20231120-1/7b704622a3cc3e3b8769cce1aaf8dd52.jpg', '<p>Nếu mỗi ngày, bạn phải thức dậy trong cơ thể của một người khác và không thể biết được rằng mình sẽ là ai vào ngày mai, bạn sẽ chấp nhận được điều đó không? Và bạn sẽ phải thuyết phục người thân yêu của bạn rằng đó chính là bạn, mặc dù chẳng phải là bạn một chút nào?&#39;. Đó chính là lời mở đầu cho bộ phim&nbsp;7 Ngày Yêu, khi một người đàn ông mỗi lúc thức dậy sẽ xuất hiện trong một cơ thể khác. Xoay quanh những rắc rối của chàng trai trong hành trình thuyết phục bạn gái của mình rằng đó thực sự là anh ta,&nbsp;&#39;7 Ngày Yêu&#39;&nbsp;sẽ là thước phim tình cảm hài ý nghĩa cho những ai đã, đang và sắp có tình yêu của riêng mình.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nittha Jirayungyurn","avatar":""},{"name":"Kan Kantathavorn","avatar":""},{"name":"Lawrence de Stefano","avatar":""},{"name":"Ananda Everingham","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
