INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-hoi-dia-nguc', 'Đêm Hội Địa Ngục', 'Hell Fest', 'https://phimimg.com/upload/vod/20231119-1/d68b888365127c2c24750612317596ef.jpg', 'https://phimimg.com/upload/vod/20231119-1/4e209fe9d16f26a64e49702cf9154705.jpg', '<p>Một kẻ giết người hàng loạt ẩn sau lớp mặt nạ biến một khu vui chơi mùa Halloween thành sân chơi của riêng hắn. Những trò khủng bố điên rồ cứ tiếp diễn, trong khi số khách còn lại cứ ngây thơ nghĩ đây chỉ là một phần của chương trình.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Forsyth","avatar":""},{"name":"Reign Edwards","avatar":""},{"name":"Bex Taylor-Klaus","avatar":""},{"name":"Christian James","avatar":""},{"name":"Roby Attal","avatar":""},{"name":"Matt Mercurio","avatar":""},{"name":"Courtney Dietz","avatar":""},{"name":"Cynthea Mercado","avatar":""},{"name":"Stephen Conroy","avatar":""},{"name":"George Howard Adams","avatar":""},{"name":"Markus Silbiger","avatar":""},{"name":"Michael Tourek","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Aaron Gillespie","avatar":""},{"name":"Cecil Elmore Jr.","avatar":""},{"name":"Elle Graham","avatar":""},{"name":"Rio","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
