INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tan-cung-the-gioi', 'Nơi Tận Cùng Thế Giới', 'To the Ends of the World', 'https://phimimg.com/upload/vod/20231119-1/7b76f2a234b62eac006a3d31542e1219.jpg', 'https://phimimg.com/upload/vod/20231119-1/3f279e447cd2517be1eba6570138282d.jpg', '<p>Tháng 3/1945 Robert Tassen, một quân nhân duy nhất sống sót trong cuộc thảm sát khi Nhật tấn công vào một căn cứ của Pháp đóng tại miền Bắc Việt Nam. Mang lòng thù hận, Tassen quay về trung đoàn với quyết tâm truy tìm kẻ đã giết anh mình để rửa hận. Nhưng khi gặp gỡ, rồi yêu Mai - một cô gái điếm - Tassen đã thay đổi suy nghĩ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Gaspard Ulliel","avatar":""},{"name":"Guillaume Gouix","avatar":""},{"name":"Lang Khê Tran","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jonathan Couzinié","avatar":""},{"name":"Kevin Janssens","avatar":""},{"name":"Anthony Paliotti","avatar":""},{"name":"François Négret","avatar":""},{"name":"Vi Minh Paul","avatar":""},{"name":"Vianney Duburque","avatar":""},{"name":"Hiep Nguyen","avatar":""},{"name":"Thanh Binh Bui","avatar":""},{"name":"Manh Hung Nguyen","avatar":""},{"name":"Paul Chatal","avatar":""},{"name":"Aymeric Pinchart","avatar":""},{"name":"Joseph Go","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324396);
