INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('catherine-va-canh-cong-khong-gian', 'Catherine và Cánh Cổng Không Gian', 'Stargate Origins: Catherine', 'https://phimimg.com/upload/vod/20231118-1/0912a550267afeac4d250a434fcb4f7f.jpg', 'https://phimimg.com/upload/vod/20231118-1/7355eef7e107182f6ee29d6f50ed8d18.jpg', '<p>Hành trình của cha và con gái trong việc khám phá bí ẩn về sự diệt vong của Trái đất.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ellie Gall","avatar":""},{"name":"Connor Trinneer","avatar":""},{"name":"Aylam Orian","avatar":""},{"name":"Philip Alexander","avatar":""},{"name":"Shvan Aladdin","avatar":""},{"name":"Daniel Rashid","avatar":""},{"name":"Salome Azizi","avatar":""},{"name":"Michelle Jubilee Gonzalez","avatar":""},{"name":"Sarah Navratil","avatar":""},{"name":"Tonatiuh","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324396);
