INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-ma', 'Người Vợ Ma', 'Ghost Wife', 'null', 'https://phimimg.com/upload/vod/20231118-1/a7177137da6ac3d8066474951524447b.jpg', '<p>Nard và Mac là một cặp đôi trong trường trung học. Trong một lần quá trớn, Nard vô tình mang thai và từ đây, tình cảm của đôi trẻ bắt đầu gặp nhiều biến cố. Mẹ của Mac bắt cả hai phải chấm dứt ngay mối quan hệ và tìm mọi cách đưa Mac ra nước ngoài du học. Trong khi đó mẹ của Nard thì thuyết phục cô bỏ đứa bé trong bụng. Nhưng điều tồi tệ đã xảy ra, Nard và con cô đều chết trên bàn phẫu thuật. Vì quá phẫn uất hồn ma của Nard không siêu thoát mà luẩn quẩn ở dương thế với hi vọng một ngày Mac trở về và tìm mẹ con cô.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Supawadee Kitisopaku","avatar":""},{"name":"Chitipat Wattanasiripong","avatar":""},{"name":"Nattana Kuwongwattanaseree","avatar":""},{"name":"Kamolpatch Thanwong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324396);
