INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-lai-siji', 'Tay Lái Siji', 'Siji: Driver', 'https://phimimg.com/upload/vod/20231118-1/6e3c10a21fe8f17329e5e60729bcfe48.jpg', 'https://phimimg.com/upload/vod/20231118-1/7a122d3b3b0690e61ef731c8e044a10d.jpg', '<p>Sau khi một tài xế giải cứu một hành khách khỏi một người bạn trai bạo hành, anh ta phát hiện ra cô là một nạn nhân buôn người. Nhưng để giải thoát cho cô, anh phải từ bỏ thứ mình yêu nhất.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Duke Conboy","avatar":""},{"name":"Candice Zhao","avatar":""},{"name":"Richie Ng","avatar":""},{"name":"Lou Martini Jr.","avatar":""},{"name":"Stephen Lin","avatar":""},{"name":"Gilbrando Acevedo","avatar":""},{"name":"JR Carter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
