INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-quai-sieu-cap-va-ngoi-sao-uoc', 'Hội quái siêu cấp và Ngôi sao ước', 'Super Monsters and the Wish Star', 'https://phimimg.com/upload/vod/20231117-1/2b563dfefe9d440b516404bf39aa19fd.jpg', 'https://phimimg.com/upload/vod/20231117-1/89b53aefb5c96825fa35b7c6b32cb563.jpg', '<p>Điều ước Giáng sinh thành hiện thực với Lobo, khi người anh họ cậu thích ghé thăm bất ngờ, và với Glorb, cậu ước có thể cùng lúc ở mọi nơi!</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vincent Tong","avatar":""},{"name":"Erin Mathews","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Alessandro Juliani","avatar":""},{"name":"Nicole Anthony","avatar":""},{"name":"Ian James Corlett","avatar":""},{"name":"Britt McKillip","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Edward Foy","avatar":""},{"name":"Diana Kaarina","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Elishia Perosa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324396);
