INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-ky-la-cua-alex', 'Tình Yêu Kỳ lạ Của Alex', 'Alex Strangelove', 'https://phimimg.com/upload/vod/20231117-1/cd91e7253e49fbfef347c2b9309ecb84.jpg', 'https://phimimg.com/upload/vod/20231117-1/98594cc72598cb9db6ea18bfef241995.jpg', '<p>Alex Truelove đang thực hiện nhiệm vụ đánh mất trinh tiết của mình, một sự kiện được người bạn gái kiên nhẫn của anh ấy háo hức chờ đợi và được những người bạn ồn ào của anh ấy cổ vũ với lời khuyên chào đón. Nhưng Alex, một anh chàng cực kỳ thích giao du, lại không có động lực một cách kỳ lạ. Một bữa tiệc tại nhà ma thuật đưa Alex đến gặp Elliot, một anh chàng đại học vạm vỡ, người cho rằng Alex là người đồng tính và rất tán tỉnh. Alex sửng sốt nhưng sau hàng loạt thất bại với bạn gái, anh quyết định dấn thân và biết được một số sự thật mới thú vị về bản thân.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Doheny","avatar":""},{"name":"Madeline Weinstein","avatar":""},{"name":"Antonio Marziale","avatar":""},{"name":"Daniel Zolghadri","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Nik Dodani","avatar":""},{"name":"Dante Costabile","avatar":""},{"name":"Annie Q.","avatar":""},{"name":"Kathryn Erbe","avatar":""},{"name":"Joanna Adler","avatar":""},{"name":"William Ragsdale","avatar":""},{"name":"Ayden Mayeri","avatar":""},{"name":"Isabella Amara","avatar":""},{"name":"Sophie Faulkenberry","avatar":""},{"name":"David Fierro","avatar":""},{"name":"Jesse James Keitel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
