INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-linh-hon', 'Khế Ước Linh Hồn', 'Spiritpact', 'https://phimimg.com/upload/vod/20231129-1/bb25b10fe62b201e16630596088e8896.jpg', 'https://phimimg.com/upload/vod/20231129-1/a38f54598b4c39da44fd37224af54e61.jpg', '<p>Là hậu duệ của một gia đình pháp sư trừ ma nổi tiếng, Dương Kính Hoa lại bị lâm vào cảnh nghèo đói sau khi cha mẹ qua đời. Để kiếm sống, anh làm nghề xem bói dạo và sửa máy tính. Vào một đêm trong bãi rác, Kính Hoa đã gặp phải pháp sư Đoan Mộc Hy bí ẩn. Cuộc gặp gỡ này là vận rủi, Kính Hoa bị một chiếc xe tông vào và trở thành hồn ma. Với sự xuất hiện của chàng pháp sư đẹp trai Tư Đồ Luật, họ đã cùng nhau đi khắp nơi để diệt trừ ma quỷ.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Meng Zidi","avatar":""},{"name":"Jia Zhengyu","avatar":""},{"name":"Shujun Chen","avatar":""},{"name":"Yu Yijie","avatar":""},{"name":"Teng Yu","avatar":""},{"name":"Wang Xilu","avatar":""},{"name":"Hu Shiwen","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324396);
