INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-xxxl', 'Điệp Vụ XXXL', 'Fat Buddies', 'https://phimimg.com/upload/vod/20231117-1/99694405b6efa41bf232ec11d27e52c8.jpg', 'https://phimimg.com/upload/vod/20231117-1/4ae064aac3f92a25f573881410224102.jpg', '<p>Bộ phim kể về hành trình của 2 chàng trai có cân nặng quá khổ trong công cuộc phá án vạch trần một công ty sản xuất thuốc phiện. Thông qua cuộc phá án này, nhiều tình tiết hài hước, xen lẫn hành động được lồng vào, cùng với đó là sự đồng cảm của chàng trai điệp vụ về sự tự ti của anh chàng bảo vệ bệnh viện.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wen Zhang","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Qi Yuwu","avatar":""},{"name":"Ryu Kohata","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Manfred Wong","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"Xu Juncong","avatar":""},{"name":"Yijun Zeng","avatar":""},{"name":"Zhang Menglu","avatar":""},{"name":"Johnson Chen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324396);
