INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sat-thu', 'Siêu Sát Thủ', 'Asher', 'https://phimimg.com/upload/vod/20231116-1/544cb61d7f0b05299155ac308c7a28bf.jpg', 'https://phimimg.com/upload/vod/20231116-1/4b54dc5d923a147257fde9fa9ce5cdf1.jpg', '<p>Một cựu chiến binh già về hưu làm sát thủ giết thuê với phong cách cổ điển. Trong một lần hành nghề tình cờ quen được một phụ nữ đơn chiếc đang nuôi một bà mẹ mất trí. Tình yêu nảy nở nhưng đồng thời cả 2 cũng rơi vào cuộc chiến tranh giành thị phần của các băng nhóm giết thuê. Trong phim mọi nười sẽ gặp lại &quot;cậu bé già&quot; Hellboy và &quot;chị vợ&quot; của anh Liam Nesson trong serie Taken.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Jacqueline Bisset","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Guy Burnet","avatar":""},{"name":"Jay Hieron","avatar":""},{"name":"Blake Perlman","avatar":""},{"name":"Marta Milans","avatar":""},{"name":"David Wohl","avatar":""},{"name":"Micah A. Hauptman","avatar":""},{"name":"Alton Fitzgerald White","avatar":""},{"name":"Ned Eisenberg","avatar":""},{"name":"Hannah Viederman","avatar":""},{"name":"Joseph Siprut","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
