INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-kich', 'Thảm kịch', '22 July', 'https://phimimg.com/upload/vod/20231116-1/246cf1672bbb8fb232ba832f47a50aa8.jpg', 'https://phimimg.com/upload/vod/20231116-1/b32191ef3b70ee9b470fea02ce91d2c6.jpg', '<p>Vào ngày 22 tháng 7 năm 2011, tên khủng bố tân Quốc xã Anders Behring Breivik đã sát hại 77 thanh niên đang tham dự Trại Thanh niên của Đảng Lao động trên Đảo Utøya bên ngoài Oslo. Câu chuyện gồm ba phần này tập trung vào những người sống sót, giới lãnh đạo chính trị của Na Uy và các luật sư có liên quan.</p>', 'Full', 1, 'single', 'completed', 9, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonas Strand Gravli","avatar":""},{"name":"Anders Danielsen Lie","avatar":""},{"name":"Jon Øigarden","avatar":""},{"name":"Seda Witt","avatar":""},{"name":"Ola G. Furuseth","avatar":""},{"name":"Maria Bock","avatar":""},{"name":"Isak Bakli Aglen","avatar":""},{"name":"Thorbjørn Harr","avatar":""},{"name":"Marit Andreassen","avatar":""},{"name":"Øystein Martinsen","avatar":""},{"name":"Valborg Frøysnes","avatar":""},{"name":"Thor-Harald Normann","avatar":""},{"name":"Anders Kulsrud Storruste","avatar":""},{"name":"Monica Borg Fure","avatar":""},{"name":"Math","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
