INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-o-trai-cho', 'Cuộc Sống Ở Trại Chó', 'Life in the Doghouse', 'https://phimimg.com/upload/vod/20231116-1/b56a69dadf2733685cb7ed694200e4a7.jpg', 'https://phimimg.com/upload/vod/20231116-1/2d972067196018ec96f0d88a98d21301.jpg', '<p>Life in the Doghouse kể câu chuyện đầy cảm hứng đằng sau Danny &amp; Ron&#39;s Rescue, một trung tâm cứu hộ chó. Bắt đầu bởi những người bạn đời Ron Danta và Danny Robertshaw, hai người đàn ông đã bắt đầu hành động sau khi cơn bão Katrina khiến hàng nghìn chú chó bị mắc kẹt và bị bỏ rơi. Hai người đàn ông đã thành lập một khu bảo tồn chó tạm thời trong nhà của họ và 10 năm sau, họ đã nuôi và giải cứu hơn 10.000 chú chó con đầy lông này.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Danta","avatar":""},{"name":"Danny Robertshaw","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324396);
