INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-o-trai-cho', 'Cuộc Sống Ở Trại Chó', 'Life in the Doghouse', 'cuộc sống ở trại chó life in the doghouse ron danta danny robertshaw ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-tru-ngu', 'Linh Hồn Trú Ngụ', 'Reside', 'https://phimimg.com/upload/vod/20231116-1/3dc8342d98f0afbf1718f4a4fafb5aa5.jpg', 'https://phimimg.com/upload/vod/20231116-1/9807a498a9791d574304450a51d5441a.jpg', '<p>Trong một đêm giông bão, tại ngôi biệt thự biệt lập, nhóm sáu người đã thực hiện nghi lễ bí ẩn với một cơ thể vô danh, mà không biết việc này sẽ triệu hồi một linh hồn lang thang. Linh hồn đáng sợ này lần lượt chiếm hữu cơ thể của các thành viên một cách đầy bất ngờ và gây ra những hậu quả không thể lường trước được.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ananda Everingham","avatar":""},{"name":"Natthaweeranuch Thongmee","avatar":""},{"name":"Ploynarin Sornarin","avatar":""},{"name":"Tarika Thidathit","avatar":""},{"name":"Peerapol Kijreunpiromsuk","avatar":""},{"name":"Teerawat Mulvilai","avatar":""},{"name":"Jarunun Phantachat","avatar":""},{"name":"Pannaras Siddhigu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324396);
