INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('milf-ky-nghi-cua-cac-me', 'MILF: Kỳ Nghỉ Của Các Mẹ', 'MILF', 'https://phimimg.com/upload/vod/20231116-1/666983f7584e1db2d091ffe15c346114.jpg', 'https://phimimg.com/upload/vod/20231116-1/e788acc7bc41ad59f36ad5b4d183ecfd.jpg', '<p>Ở miền nam nước Pháp, 3 người bạn thân trong độ tuổi 40 vượt qua sự mất mát và tan vỡ, đồng thời dấn thân vào những mối quan hệ ướt át với các chàng trai trẻ hơn nhiều.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Virginie Ledoyen","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Axelle Laffont","avatar":""},{"name":"Matthias Dandois","avatar":""},{"name":"Victor Meutelet","avatar":""},{"name":"Waël Sersoub","avatar":""},{"name":"Florence Thomassin","avatar":""},{"name":"Rémi Pedevilla","avatar":""},{"name":"Jéromine Chasseriaud","avatar":""},{"name":"Mitty Hazanavicius","avatar":""},{"name":"Claude Attia","avatar":""},{"name":"Anne-Marie Ponsot","avatar":""},{"name":"Pierre Lopez","avatar":""},{"name":"Robert Assolen","avatar":""},{"name":"Patrick Semi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
