INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-dao-tac', 'Gia Đình Đạo Tặc', 'Shoplifters', 'https://phimimg.com/upload/vod/20231117-1/91875fd073557dfbddc72fc49bead608.jpg', 'https://phimimg.com/upload/vod/20231117-1/648b59850e2a163c945e937d4f9f1bf0.jpg', '<p>Phim kể về một gia đình đặc biệt của những con người không cùng chung dòng máu, tất cả nương nhờ mái nhà lụp xụp của bà lão Hatsue, sỗng bằng tiền lương hưu của người chồng quá cố của bà. Kế sinh nhai của họ, ngoài những công việc tay chân tạm bợ, là nghề ăn trộm vặt tại những siêu thị, cửa hàng nhỏ gần nhà. Một ngày nọ, gia đình đặc biệt đã đón nhận một thành viên mới: cô bé Yuri bị cha mẹ ngược đãi.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Lily Franky","avatar":""},{"name":"Sakura Ando","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Kairi Jo","avatar":""},{"name":"Miyu Sasaki","avatar":""},{"name":"Kirin Kiki","avatar":""},{"name":"Sosuke Ikematsu","avatar":""},{"name":"Naoto Ogata","avatar":""},{"name":"Yôko Moriguchi","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Moemi Katayama","avatar":""},{"name":"Kengo Kora","avatar":""},{"name":"Chizuru Ikewaki","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Aju Makita","avatar":""},{"name":"Hajime Inoue","avatar":""},{"name":"Haruna Hori","avatar":""},{"name":"Nana Mizoguchi","avatar":""},{"name":"Madoka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
