INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tro-cua-okko', 'Quán Trọ Của Okko', 'Okko''s Inn', 'https://phimimg.com/upload/vod/20231117-1/776aed1f987d843eec21ae4265e3ec48.jpg', 'https://phimimg.com/upload/vod/20231117-1/60af08a9951cebca1fbb8828e4b28fb5.jpg', '<p>Oriko Seki, 12 tuổi, mất cha mẹ trong một vụ tai nạn xe hơi, cuối cùng phải sống trong Onsen Ryokan &quot;Haru no Ya&quot; của bà cô. Với việc hồn ma &quot;Uribou&quot; sống chung với cô và tất cả những khó khăn khác, cuối cùng cô đã được đào tạo để trở thành một nữ chủ quán trẻ. Lúc đầu, cô không thích công việc huấn luyện, nhưng dần dần cô cảm thấy ngưỡng mộ danh hiệu của mình và bắt đầu tập luyện nghiêm túc. Vì vậy, sự trưởng thành của chiến binh trẻ Oriko bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Seiran Kobayashi","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Satsumi Matsuda","avatar":""},{"name":"Rina Endou","avatar":""},{"name":"Etsuko Kozakura","avatar":""},{"name":"Yoko Asagami","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Teiyu Ichiryusai","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Yumiko Kobayashi","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Makoto Tanaka","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Kunpei Sakamoto","avatar":""},{"name":"Miyako Ito","avatar":""},{"name":"Maiko","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324396);
