INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ly-da-huong-thang-10', 'Hoa Lý Dạ Hương Tháng 10', 'October', 'https://phimimg.com/upload/vod/20231117-1/6e797ba1cb8ee4ea37de58ef35949eb1.jpg', 'https://phimimg.com/upload/vod/20231117-1/d79a8348f65db19bb82313b4e55b1a10.jpg', '<p>Dan, một chàng trai 21 tuổi vô tư luôn được vây quanh bởi một nhóm bạn và những người bạn thực tập tại khách sạn, những người chia sẻ cho nhau những khoảnh khắc hàng ngày, những thăng trầm của họ. Shiuli cũng là một thực tập sinh làm việc trong cùng một khách sạn, người đôi khi phải hứng chịu sự táo bạo của Dan. Mọi thứ đều bình thường trong cuộc sống của họ cho đến khi một sự kiện bất ngờ xảy ra khiến cuộc sống của Dan và Shiuli trở nên gắn bó.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Varun Dhawan","avatar":""},{"name":"Banita Sandhu","avatar":""},{"name":"Gitanjali Rao","avatar":""},{"name":"Sahil Vedoliyaa","avatar":""},{"name":"Isha Chaturvedi","avatar":""},{"name":"Prateek Kapoor","avatar":""},{"name":"Iteeva Pandey","avatar":""},{"name":"Karamveer Kanwar","avatar":""},{"name":"Ashish Ghosh","avatar":""},{"name":"Rachica Oswal","avatar":""},{"name":"Aarti","avatar":""},{"name":"Gauri Aggarwal","avatar":""},{"name":"Rajesh Aggarwal","avatar":""},{"name":"Alex","avatar":""},{"name":"Nikita Anand","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
