INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tich-noi-dai-duong', 'Cổ Tích Nơi Đại Dương', 'The Little Mermaid', 'https://phimimg.com/upload/vod/20231117-1/70f1187599036bcecb97f37dab9a8ab6.jpg', 'https://phimimg.com/upload/vod/20231117-1/2303ef6992c647d3f39d2e88c64bbea1.jpg', '<p>Một phóng viên trẻ và cháu gái của anh ta phát hiện ra một sinh vật xinh đẹp và mê hoặc mà họ tin rằng đó chính là nàng tiên cá nhỏ thực sự.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Poppy Drayton","avatar":""},{"name":"Shirley MacLaine","avatar":""},{"name":"Loreto Peralta","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Shanna Collins","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Tom Nowicki","avatar":""},{"name":"Lexy Kolker","avatar":""},{"name":"Claire Crosby","avatar":""},{"name":"Jo Marie Payton","avatar":""},{"name":"Armando Gutiérrez","avatar":""},{"name":"Chris Yong","avatar":""},{"name":"Alexis Balliro","avatar":""},{"name":"Hunter Gomez","avatar":""},{"name":"Jared Sandler","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
