INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-swerve', 'The Swerve', 'The Swerve', 'https://phimimg.com/upload/vod/20231117-1/395601b6bd9e4f14421287aa23378041.jpg', 'https://phimimg.com/upload/vod/20231117-1/951517c5d88e22cabcfabfcec8e12e27.jpg', '<p>Holly dường như có tất cả: Hai đứa trẻ, một ngôi nhà đẹp, một công việc tốt như một giáo viên, và một người chồng với sự nghiệp của mình trên đường lên. Nhưng có những dấu hiệu rắc rối rằng tất cả đều không đúng trong thế giới của cô. Mất ngủ. Thuốc cho mất ngủ. Những giấc mơ từ thuốc cho mất ngủ. (Họ thậm chí là những giấc mơ?) Và sau đó có chuột xuất hiện trong nhà cô ấy. Làm đảo lộn sự cân bằng tinh tế của cô, nó sẽ khiến cô tránh xa tầm kiểm soát. Nhà văn / Giám đốc Dean Kapsalis &#39;Tính năng ra mắt khám phá một tuần trong cuộc đời của một người phụ nữ trên bờ vực thiền ám ảnh này về bệnh tâm thần</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Azura Skye","avatar":""},{"name":"Bryce Pinkham","avatar":""},{"name":"Ashley Bell","avatar":""},{"name":"Zach Rand","avatar":""},{"name":"Deborah Hedwall","avatar":""},{"name":"Dan Daily","avatar":""},{"name":"Taen Phillips","avatar":""},{"name":"Liam Seib","avatar":""},{"name":"Jenna Marie Hess","avatar":""},{"name":"Chadwick Davilsaint","avatar":""},{"name":"Lindsay Jackson","avatar":""},{"name":"Jason Gupton","avatar":""},{"name":"Maikel Ramic","avatar":""},{"name":"Josh England","avatar":""},{"name":"Gretchen Portelles","avatar":""},{"name":"Kristine Sorenson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324396);
