INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-hao', 'Hoàn Hảo', 'The Perfection', 'https://phimimg.com/upload/vod/20231115-1/e168b4d4331500e9d52f3178eeccc8d1.jpg', 'https://phimimg.com/upload/vod/20231115-1/4fd552ffe569d736852b287effb1bcd6.jpg', '<p>Bộ phim kể về thiên tài âm nhạc Charlotte, cô là một người rất nổi tiếng trong giới Violin. Tuy nhiên một đối thủ khác xuất hiện là Lizze, một người từng học trường thanh nhạc cũ của Charlotte khiến cho tên tuổi của Charlotte bị đi xuống. Thế là Charlotte đã vạch sẵn một kế hoạch man rợ để đưa tên tuổi của Lizze nhưng không chỉ thế, đó là sự hủy hoại cả về thể xác lẫn tinh thần của cô gái...</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Allison Williams","avatar":""},{"name":"Logan Browning","avatar":""},{"name":"Steven Weber","avatar":""},{"name":"Alaina Huffman","avatar":""},{"name":"Glynis Davies","avatar":""},{"name":"Molly Grace","avatar":""},{"name":"Milah Thompson","avatar":""},{"name":"Christina Jastrzembska","avatar":""},{"name":"Mark Kandborg","avatar":""},{"name":"Winnie Hung","avatar":""},{"name":"Graeme Duffy","avatar":""},{"name":"Johnny Ji","avatar":""},{"name":"Eileen Tian","avatar":""},{"name":"Alex Lee","avatar":""},{"name":"Evelyn Chew","avatar":""},{"name":"Sofy Chen","avatar":""},{"name":"Leanne Wang","avatar":""},{"name":"Sharon Cra","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
