INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('auntie-edna', 'Auntie Edna', 'Auntie Edna', 'auntie edna auntie edna brad bird craig t. nelson eli fucile nicholas bird maeve andrews noelle zuber ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('x-the-exploited', 'X - The eXploited', 'X – A rendszerből törölve', 'https://phimimg.com/upload/vod/20231114-1/8ac5ba7543cdf95375c6678f029431dc.jpg', 'https://phimimg.com/upload/vod/20231114-1/9f5aea79f3db1714fa5099a2a8c63e51.jpg', '<p>Bạn có tin vào một nữ cảnh sát mắc chứng rối loạn hoảng sợ nghiêm trọng đến mức sợ đến gần bất kỳ hiện trường vụ án nào và đã làm nhiệm vụ thường trực trong văn phòng hơn một thập kỷ? Bạn có tin rằng một người mẹ đơn độc không đủ khả năng trả nợ thế chấp và còn nuôi dạy đứa con gái đang tuổi mới lớn nổi loạn của mình không? Thật vậy, không ai tin rằng cựu thám tử rắc rối đã khám phá ra một vụ án giết người hàng loạt. Các bộ phim truyền hình cá nhân và một bí ẩn giết người mở ra ở Budapest ngày nay, nơi các cuộc biểu tình là một phần của cuộc sống trước bầu cử của một thành phố vẫn đang cố gắng đối phó với bóng đen của quá khứ lịch sử và gần đây của nó. Đó là một thành phố nơi không có gì có vẻ trung thực và chân thực, ngoại trừ con mắt của một nữ cảnh sát không ổn định về cảm xúc và đứa con gái lầm lì của cô ấy, người muốn biết cha mình thực sự là ai.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Mónika Balsai","avatar":""},{"name":"Schmied Zoltán","avatar":""},{"name":"Áron Molnár","avatar":""},{"name":"Szabolcs Bede-Fazekas","avatar":""},{"name":"Csaba Gosztonyi","avatar":""},{"name":"Olasz Renátó","avatar":""},{"name":"Juli Básti","avatar":""},{"name":"Kata Purt","avatar":""},{"name":"Zoltán Schneider","avatar":""},{"name":"Győző Szabó","avatar":""},{"name":"Geza Szucs","avatar":""},{"name":"Abigél Szőke","avatar":""},{"name":"János Kulka","avatar":""},{"name":"Attila Szatmári","avatar":""},{"name":"Béla Pavletits","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
