INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thai-quy', 'Bào Thai Quỷ', 'Malicious', 'https://phimimg.com/upload/vod/20231113-1/8f08e4b200c40a39e52e513f794807a3.jpg', 'https://phimimg.com/upload/vod/20231113-1/e4fcce895f02ade07cc2baa6ae1ced85.jpg', '<p>Một giáo sư đại học trẻ và người vợ mang thai đang rất hạnh phúc mong chờ đứa con đầu lòng. Thế nhưng, những hiện tượng kỳ lạ bắt đầu xảy ra ám ảnh người vợ và cô bị sảy thai. Dường như đôi vợ chồng trẻ đã vô tình giải thoát một thực thể ma quái khát máu.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bojana Novaković","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Melissa Bolona","avatar":""},{"name":"Yvette Yates Redick","avatar":""},{"name":"Luke Edwards","avatar":""},{"name":"Jaqueline Fleming","avatar":""},{"name":"Ben VanderMey","avatar":""},{"name":"Bailee MyKell Cowperthwaite","avatar":""},{"name":"Joy Kate Lawson","avatar":""},{"name":"Jo-Ann Robinson","avatar":""},{"name":"Presley Richardson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324396);
