INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-night-eats-the-world', 'The Night Eats the World', 'The Night Eats the World', 'https://phimimg.com/upload/vod/20231113-1/3f4a89076cf20ef5d58a4e6287ccb5cc.jpg', 'https://phimimg.com/upload/vod/20231113-1/3799dc18542e7af89bcd86453a6491ab.jpg', '<p>Sau khi thức dậy trong một căn hộ nơi chỉ có đêm trước khi một bữa tiệc đang hoành hành, Sam buộc phải nắm bắt thực tế: Anh ta đang ở một mình và người chết đã xâm chiếm đường phố Paris. Hóa đá với nỗi sợ hãi, Sam sẽ phải là rào chắn trong tòa nhà và tổ chức sự sống còn của mình. Nhưng anh ấy có thực sự là người sống sót duy nhất?</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Anders Danielsen Lie","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"Denis Lavant","avatar":""},{"name":"Sigrid Bouaziz","avatar":""},{"name":"David Kammenos","avatar":""},{"name":"Jean-Yves Cylly","avatar":""},{"name":"Nancy Murillo","avatar":""},{"name":"Lina-Rose Djedje","avatar":""},{"name":"Victor van der Woerd","avatar":""},{"name":"Léo Poulet","avatar":""},{"name":"Déborah Marique","avatar":""},{"name":"Tess Osscini Boudebesse Bejjani","avatar":""},{"name":"Fabien Houssaye","avatar":""},{"name":"Jean-Louis Prio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
