INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hua-tro-ve', 'Lời hứa trở về', 'Pulang', 'https://phimimg.com/upload/vod/20231113-1/8f5bbcaeaac6584398968a42753a14d3.jpg', 'https://phimimg.com/upload/vod/20231113-1/ec24cd093f434957fe8b26b257bb10f2.jpg', '<p>Thom kể cho cháu trai mình về ông nội, một thủy thủ đã ra khơi 61 năm trước để tìm tài vận, và nhờ cháu tìm hiểu chuyện gì đã xảy ra với chồng bà.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Remy Ishak","avatar":""},{"name":"Puteri Aishah","avatar":""},{"name":"Alvin Wong","avatar":""},{"name":"Azrel Ismail","avatar":""},{"name":"Erwin Dawson","avatar":""},{"name":"Juliana Evans","avatar":""},{"name":"Jalaluddin Hassan","avatar":""},{"name":"Dato'' Rahim Razali","avatar":""},{"name":"Sherry Al Jeffry","avatar":""},{"name":"Aida Khalida","avatar":""},{"name":"Naza  Abdul Manas","avatar":""},{"name":"Akmal Ahmad","avatar":""},{"name":"Syazuwan Hassan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324396);
