INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-ao', 'Đấu Trường Ảo', 'Ready Player One', 'https://phimimg.com/upload/vod/20231113-1/051a2e2a34648b85c91d6557ea23943e.jpg', 'https://phimimg.com/upload/vod/20231113-1/ad58fc1d5f1c5398a3ece1c2843f5d0c.jpg', '<p>Phim kể về bối cảnh năm 2044, khi con người có thể trốn tránh thế giới thực ảm đạm bằng việc hòa mình vào không giản ảo mang tên OASIS. Từ đây, xuất hiện anh chàng Wade Watts. Anh đã tới với OASIS và lấy tên cho nhân vật của mình là Parzival. Một ngày nọ, người sáng lập ra Oasis đã thách thức tất cả những người chơi đi tìm Easter Eggs – Trứng phục sinh. Phần thưởng dành cho người chiến thắng là những tài sản vô cùng quý báu mà ông để lại. Wade Watts đã tìm ra được những gợi ý đầu tiên trong cuộc tìm kiếm và bắt đầu hành trình của mình. Tuy nhiên, chàng trai Wade Watts sớm thấy mình bị xoáy sâu vào vòng luẩn quẩn của những bí ẩn, những sự kiện điên rồ giật dây dưới tay tổ chức Innovative Online Industries.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tye Sheridan","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Lena Waithe","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Mark Rylance","avatar":""},{"name":"Philip Zhao","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Hannah John-Kamen","avatar":""},{"name":"Ralph Ineson","avatar":""},{"name":"Susan Lynch","avatar":""},{"name":"Clare Higgins","avatar":""},{"name":"Perdita Weeks","avatar":""},{"name":"Letitia Wright","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Lulu Wilson","avatar":""},{"name":"Cara Pifko","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324396);
