INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-chuong-skypiea', 'Đảo Hải Tặc: Chương Skypiea', 'One Piece: Episode of Skypiea', 'https://phimimg.com/upload/vod/20231113-1/9537eccf5b24ab788f10201865b6ecb3.jpg', 'https://phimimg.com/upload/vod/20231113-1/3a658ad416584c76fe026da1c848330d.jpg', '<p>Cốt truyện xoay quanh băng Mũ Rơm trên đường đến đảo Skypeia. Sau khi tình cờ có vài manh mối về đảo trên trời, băng Mũ Rơm đã dừng chân tại đảo Jaya và vô tình gặp gỡ &quot;Râu Đen&quot; Marshall D. Teach - một kẻ cũng có tham vọng làm Vua Hải Tặc.Với sự giúp đỡ của Montblanc Cricket và Liên hợp quân núi khỉ đã đưa băng Mũ Rơm lên trên trời thành công. Sau khi lên đến đảo trên trời Skypie, băng Mũ Rơm đã vướng vào cuộc chiến tranh giành quyền làm chủ hòn đảo giữa hai tộc người Skypie và Shandia. Enel, kẻ sở hữu sức mạnh của sấm sét là người đứng đầu bên Skypie. Luffy đã đánh bại Enel và cứu Skypie khỏi thảm họa diệt vọng, cuộc chiến kết thúc.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Rieko Takahashi","avatar":""},{"name":"Masami Suzuki","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Masaya Takatsuka","avatar":""},{"name":"Ennosuke Ichikawa","avatar":""},{"name":"Naoya Uchida","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Yuko Minagu","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":