INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dung-lam-sep', 'Bỗng Dưng Làm Sếp', 'Second Act', 'https://phimimg.com/upload/vod/20231114-1/292b9be31bb459564a2c05df2ccb8fc0.jpg', 'https://phimimg.com/upload/vod/20231114-1/3896817f59428baf977aa44c49c9d30a.jpg', '<p>Chán đời sau khi bị từ chối thăng chức do thiếu bằng bằng đại học, một phụ nữ trung tuổi chứng minh rằng cuộc đời không chỉ cần sách vở.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Leah Remini","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Charlyne Yi","avatar":""},{"name":"Annaleigh Ashford","avatar":""},{"name":"Alan Aisenberg","avatar":""},{"name":"Freddie Stroma","avatar":""},{"name":"Dave Foley","avatar":""},{"name":"Larry Miller","avatar":""},{"name":"Dierdre Friel","avatar":""},{"name":"Lacretta","avatar":""},{"name":"Dan Bucatinsky","avatar":""},{"name":"Dalton Harrod","avatar":""},{"name":"John James Cronin","avatar":""},{"name":"Phil Nee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
