INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-nhan-tao', 'Sát Thủ Nhân Tạo', 'The Witch: Part 1. The Subversion', 'https://phimimg.com/upload/vod/20231114-1/83735d2f97e90204242ddeb68d96d998.jpg', 'https://phimimg.com/upload/vod/20231114-1/1e36b048a12f3ade9dbbafbeee5cb34a.jpg', '<p>Sát Thủ Nhân Tạo là bộ phim hành động li kì kể về Koo Ja-yoon – một cô bé được nuôi dưỡng trong một tổ chức đáng sợ - nơi diễn ra các cuộc thí nghiệm y học được thực hiện trên chính cơ thể con người nhằm biến họ thành những cỗ máy giết người. Sau khi chạy trốn khỏi tổ chức, Ja-yoon bị mất trí nhớ và được một cặp vợ chồng già nhận nuôi. &nbsp;10 năm sau, khi đã trở thành một nữ sinh trung học, Ja-yoon đăng ký tham gia một cuộc thi âm nhạc với mong muốn giúp gia đình vượt qua khó khăn tài chính. Nhưng cô không ngờ rằng, ngay từ khi hình ảnh của mình xuất hiện trên truyền hình, cuộc sống của cô bị đảo lộn hoàn toàn bởi sự truy đuổi của những kẻ lạ mặt.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Da-mi","avatar":""},{"name":"Cho Min-soo","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Go Min-si","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Oh Mi-hee","avatar":""},{"name":"Jeong Da-eun","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Kim Ha-na","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Lee Ki-young","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Moo-yeong Yeo","avatar":""},{"name":"Chung Ye-jin","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Lee Si-hoon","avatar":""},{"name":"Baek Seung-chul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8