INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-nho', 'Khu Rừng Nhỏ', 'Little Forest', 'https://phimimg.com/upload/vod/20231114-1/cf0dac74af19f1b4a0d4547b74576829.jpg', 'https://phimimg.com/upload/vod/20231114-1/125e2a43fe6b19f72d082ae94a098bb3.jpg', '<p>Little Forest bản Hàn xoay quanh câu chuyện về Hye Won (Kim Tae Ri), một cô gái trẻ mệt mỏi vì cuộc sống thành thị và quyết định về quê ở vùng nông thôn để sinh sống. Tại đây, Hye Won đã có thể chữa lành vết thương lòng của mình nhờ sự giúp đỡ của những người bạn, thiên nhiên và những thức quả ngon tuyệt.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-ri","avatar":""},{"name":"Moon So-ri","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Jin Ki-joo","avatar":""},{"name":"Jeon Guk-hyang","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Jung Jun-won","avatar":""},{"name":"Jeon Sang-jin","avatar":""},{"name":"Ok Su-boon","avatar":""},{"name":"Jang Jae-hee","avatar":""},{"name":"Cha Soo-jin","avatar":""},{"name":"Hong Sung-duk","avatar":""},{"name":"Kang Hye-eun","avatar":""},{"name":"Kang Min-ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
