INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-giang-sinh-dam-cuoi-hoang-gia', 'Hoàng tử Giáng sinh: Đám cưới hoàng gia', 'A Christmas Prince: The Royal Wedding', 'https://phimimg.com/upload/vod/20231114-1/ecc65313c730c9c8899b03d7da489140.jpg', 'https://phimimg.com/upload/vod/20231114-1/8c44091302cb3d25d2865033b117092f.jpg', '<p>Một năm sau khi giúp Richard lên ngôi, Amber trở lại Aldovia để chuẩn bị cho đám cưới của họ. Nhưng những sở thích giản dị của cô lại trái ngược với lễ nghi hoàng gia.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rose McIver","avatar":""},{"name":"Ben Lamb","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Honor Kneafsey","avatar":""},{"name":"Theo Devaney","avatar":""},{"name":"Sarah Douglas","avatar":""},{"name":"John Guerrasio","avatar":""},{"name":"Andy Lucas","avatar":""},{"name":"Simon Dutton","avatar":""},{"name":"Katarina Čas","avatar":""},{"name":"Richard Ashton","avatar":""},{"name":"Raj Bajaj","avatar":""},{"name":"Joel McVeagh","avatar":""},{"name":"Tahirah Sharif","avatar":""},{"name":"Tom Knight","avatar":""},{"name":"Billy Angell","avatar":""},{"name":"David Broughton-Davies","avatar":""},{"name":"Claudiu Tra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
