INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-ngam', 'Chiến Dịch Ngầm', 'Take Point', 'https://phimimg.com/upload/vod/20231115-1/2c93cffc8b96d5457eae35a9e96d36bb.jpg', 'https://phimimg.com/upload/vod/20231115-1/80e68227a312f22e80f9609cee0adbbd.jpg', '<p>Vào ngày diễn ra cuộc bầu cử tổng thống Hoa Kỳ năm 2024, Ahab (Ha Jung-Woo) cùng nhóm lính đánh thuê tinh nhuệ của mình bắt tay vào một nhiệm vụ bí mật của CIA để bắt cóc Bộ trưởng Lực lượng Vũ trang Bắc Triều Tiên trong một hầm ngầm bên dưới Khu phi quân sự Triều Tiên (DMZ). Tuy nhiên, họ bị cuốn vào cuộc chiến chéo khiến căng thẳng leo thang có khả năng gây nên Chiến Tranh Thế Giới thứ 3.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Lee Sun-kyun","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Spencer Daniels","avatar":""},{"name":"Malik Yoba","avatar":""},{"name":"Julian Juaquin","avatar":""},{"name":"Jorge-Luis Pallo","avatar":""},{"name":"Jeff Bosley","avatar":""},{"name":"Robert Curtis Brown","avatar":""},{"name":"Shin Hyun-bin","avatar":""},{"name":"Seon Uk-hyeon","avatar":""},{"name":"Jack Lyons","avatar":""},{"name":"Warzecha Wyka","avatar":""},{"name":"Paul Meixner","avatar":""},{"name":"Liviu Covalschi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
