INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-gia-quyen-uy-chan-son-ha', 'Hoắc Gia Quyền: Uy Chấn Sơn Hà', 'Shocking Kungfu Of HUO''s', 'https://phimimg.com/upload/vod/20231115-1/cee26833617feb79169cd7a59b8316c1.jpg', 'https://phimimg.com/upload/vod/20231115-1/3d1488c48f69589347f74a4a355c5992.jpg', '<p>Hà Đại Xuyên bị giết trong lúc cố gắng bảo vệ người huynh đệ kết nghĩa là Hoắc Chấn Sơn. Hai mươi năm sau, Hoắc Chấn Sơn mở một võ đường ở Thượng Hải, đồng thời tiếp tục tìm kiếm hai người con của Hà Đại Xuyên. Trong trận đấu tay đôi trên võ đài hắc quyền, Hoắc Chấn Sơn đã đánh bại các đối thủ nhưng từ chối nhận tiền thưởng. Thạch Đầu theo dõi trận quyết đấu ở khán đài và thấy vô cùng nể phục Hoắc Chấn Sơn. Câu chuyện dần được hé mở, Thạch Đầu hóa ra lại là người con trai mất tích bấy lâu của Hà Đại Xuyên!\n\n</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yan Jie","avatar":""},{"name":"Lanyi Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324396);
