INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-baek', 'Cô Baek', 'Miss Baek', 'https://phimimg.com/upload/vod/20231115-1/96289854f671535a68243382ab7e4955.jpg', 'https://phimimg.com/upload/vod/20231115-1/250420d04a7c5d50aedf314ca788a07b.jpg', '<p>Tác phẩm điện ảnh được xây dựng dựa trên một câu chuyện có thật đề cập đến vấn đề xã hội nghiêm trọng: Nạn bạo hành trẻ em.&#39;Cô Baek&#39; là bộ phim xoay quanh câu chuyện về một người phụ nữ trẻ tuổi họ Baek, mang tên Baek Sang-ah, người từng có tiền án tiền sự vì cố gắng bảo vệ bản thân mình trong quá khứ. Sống đơn độc, khép kín, không tin và mở lòng với bất kỳ ai. Bỗng một ngày nọ, cô vô tình gặp một đứa trẻ có hoàn cảnh bất hạnh tương tự với những chuyện đáng sợ khủng khiếp mà cô từng trải qua, từ đó cô quyết định ra sức bảo vệ đứa bé khỏi một thế giới đầy rẫy tội ác và bạo lực.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji-min","avatar":""},{"name":"Kim Si-a","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kwon So-hyun","avatar":""},{"name":"Baek Soo-jang","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Lee Joo-young","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Jo Min-jun","avatar":""},{"name":"Yoon Song-ah","avatar":""},{"name":"Kim Bo-min","avatar":""},{"name":"Yoo Jong-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
