INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-baek', 'Cô Baek', 'Miss Baek', 'cô baek miss baek han ji-min kim si-a lee hee-jun kwon so-hyun baek soo-jang jang young-nam kim sun-young jun suk-ho lee joo-young lee jung-eun jo min-jun yoon song-ah kim bo-min yoo jong-yeon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gianh-anh-tu-bien', 'Giành Anh Từ Biển', 'Adrift', 'https://phimimg.com/upload/vod/20231115-1/6141f1ef368cbdee5eac88c760a815f1.jpg', 'https://phimimg.com/upload/vod/20231115-1/60241418164ca61c2798a8eadceca98b.jpg', '<p>Giành Anh từ biển (tên tiếng anh Adrift) là một bộ phim được lấy cảm hứng dựa trên câu chuyện có thật của một đôi tình nhân vượt biển vào năm 1983. Tới Tahiti để theo đuổi những chuyến phiêu lưu, Tami Oldham (Shailene Woodley) nhanh chóng phải lòng chàng thủy thủ Richard Sharp (Sam Claflin) và cả hai thực hiện chuyến du lịch mơ ước xuyên Thái Bình Dương. Nhưng cả hai không ngờ rằng họ sẽ đi thẳng vào một cơn bão thảm khốc nhất trong lịch sử. Sau cơn bão, Richard bị thương nặng còn con thuyền đã bị phá tan. Không có cơ hội được cứu, Tami phải tìm lấy sức mạnh và lòng quyết tâm để cứu lấy bản thân và người đàn ông duy nhất cô từng yêu. Giành Anh từ biển là một câu chuyện cảm động về tình yêu và nghị lực phi thường để chiến đấu giành sự sống.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Jeffrey Thomas","avatar":""},{"name":"Elizabeth Hawthorne","avatar":""},{"name":"Grace Palmer","avatar":""},{"name":"Tami Ashcraft","avatar":""},{"name":"Siale Tunoka","avatar":""},{"name":"Kael Damlamian","avatar":""},{"name":"Lei-Ming Caine","avatar":""},{"name":"Neil Andrea","avatar":""},{"name":"Apakuki Nalawa","avatar":""},{"name":"Tim Solomon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324396);
