INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tien-hoa-cua-toi-ac', 'Sự Tiến Hóa Của Tội Ác', 'Evolution of Evil', 'https://phimimg.com/upload/vod/20231113-1/9cd1b47a6f4af168fe4164591b5cdf43.jpg', 'https://phimimg.com/upload/vod/20231113-1/6580b534aaa0cc4e94f7f2ecd3f2bed8.jpg', '<p>Bộ phim là câu chuyện về Lori và Christopher, một cặp vợ chồng sống ở Tây Bắc Thái Bình Dương. Vì muốn thoát khỏi cuộc sống hối hả và nhộn nhịp của thành phố nên họ chuyển tới vùng hoang dã để khởi đầu lại. Cặp đôi đi qua các khu cắm trại, từ đây họ dần phát hiện ra những điều kỳ bí nguy hiểm đợi họ ở phía trước.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Erin McGarry","avatar":""},{"name":"Dennis Fitzpatrick","avatar":""},{"name":"Michael Draper","avatar":""},{"name":"Nikki Flinn","avatar":""},{"name":"Jeffrey Arrington","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
