INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-kruty-1918', 'Trận Chiến Kruty 1918', 'Winter of The Braves', 'https://phimimg.com/upload/vod/20231113-1/ada25fd7f25d2fb4289e5361f87aa9f8.jpg', 'https://phimimg.com/upload/vod/20231113-1/b0453678d6991f61cdfaf8ac9d37b081.jpg', '<p>1918 Ukraina. Những sinh viên yêu nước, nhân vật chính của bộ phim, sẵn sàng bảo vệ Kyiv và chiến đấu anh dũng trong Trận chiến Kruty. Trên bối cảnh lịch sử này hé lộ câu chuyện về gia đình Savytskyi - tướng phản gián Ukraine và hai người con trai Andrii và Oleksa.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Ukraine', 0, '[{"name":"Yevhen Lamakh","avatar":""},{"name":"Andrii Fedinchyk","avatar":""},{"name":"Vitalii Salii","avatar":""},{"name":"Oleksii Trytenko","avatar":""},{"name":"Oleksandr Piskunov","avatar":""},{"name":"Bohdan Yusypchuk","avatar":""},{"name":"Nataliia Vasko","avatar":""},{"name":"Yevhen Nyshchuk","avatar":""},{"name":"Serhii Dzialyk","avatar":""},{"name":"Oleksii Smolka","avatar":""},{"name":"Dmytro Stupka","avatar":""},{"name":"Dmytro Oliinyk","avatar":""},{"name":"Ostap Stupka","avatar":""},{"name":"Roman Yasinovskyi","avatar":""},{"name":"Alina Kovalenko","avatar":""},{"name":"Vlad","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
