INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nep-gap-thoi-gian', 'Nếp Gấp Thời Gian', 'A Wrinkle in Time', 'https://phimimg.com/upload/vod/20231113-1/5280b91dd38bfea842238b1bb0a2bb9e.jpg', 'https://phimimg.com/upload/vod/20231113-1/67d76dbcae6b2fc464a008884453c628.jpg', '<p>Bộ phim vén mở tấm màn đầu tiên của bộ phim bằng những hình ảnh về cô bé Meg Murry do ngôi sao nhí Storm Reid thủ vai, người đang chật vật tìm kiếm những giải đáp cho sự hoài nghi về giá trị của bản thân và khát vọng muốn hòa nhập với những người khác. Tuy nhiên mọi sự lo lắng của Meg nhanh chóng dồn vào sự mất tích của bố cô bé, một nhà vật lý học thiên tài với luận điểm mới mẻ gây chấn động giới khoa học, “Hãy tưởng tượng 91 tỷ năm ánh sáng chỉ thoáng qua trong một cái chớp mắt.” Cũng chính lập luận này đã thu hút sự chú ý của những thế lực hung ác khiến cho ông gặp phải nhiều hiểm nguy. Meg Murry và những người bạn sẽ phải trải qua những thử thách đầy cam go trên hành trình siêu thực, chuyển đổi liên tục từ không gian đến thời gian để giải cứu bố mình.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Storm Reid","avatar":""},{"name":"Oprah Winfrey","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Levi Miller","avatar":""},{"name":"Deric McCabe","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Rowan Blanchard","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"André Holland","avatar":""},{"name":"Bellamy Young","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Conrad Roberts","avatar":""},{"name":"Lyric Wilson","avatar":""},{"name":"Yvette Cason","avatar":""}]', '[{"name":"Phiêu Lưu","slug"