INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cham-soc-cho', 'Người Chăm Sóc Chó', 'Dogman', 'https://phimimg.com/upload/vod/20231112-1/82f0a7fb7f51bd256617cb98a9a5fc43.jpg', 'https://phimimg.com/upload/vod/20231112-1/15cc863cd5a3a92e379d41c6eaa60f72.jpg', '<p>Marcello ( Marcello Fonte thủ vai) là một người chăm sóc chó hiền lành và dễ mến. Cả khu phố đều ngán và sợ tên hách dịch, bạo lực Simoncino ( Edoardo Pesce). Những hành động và tội lỗi của hắn đã khiến Marcello đứng lên để dạy cho bài học, trận chiến của người chăm sóc chó và tay võ sĩ bạo lực bắt đầu...</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Marcello Fonte","avatar":""},{"name":"Edoardo Pesce","avatar":""},{"name":"Nunzia Schiano","avatar":""},{"name":"Adamo Dionisi","avatar":""},{"name":"Francesco Acquaroli","avatar":""},{"name":"Alida Baldari Calabria","avatar":""},{"name":"Gianluca Gobbi","avatar":""},{"name":"Laura Pizzirani","avatar":""},{"name":"Giancarlo Porcacchia","avatar":""},{"name":"Aniello Arena","avatar":""},{"name":"Mirko Frezza","avatar":""},{"name":"Marco Perfetti","avatar":""},{"name":"Vittorio Russo","avatar":""},{"name":"Gennaro Iannone","avatar":""},{"name":"Emanuele Barbal","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
