INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhom-nhay-nha-tu', 'Nhóm Nhảy Nhà Tù', 'Swing Kids', 'https://phimimg.com/upload/vod/20231111-1/794d30e41d6bcca787a3ac29171fb52d.jpg', 'https://phimimg.com/upload/vod/20231111-1/8d733f26a4bb8aebe27c61851213ca58.jpg', '<p>Bối cảnh phim được đặt trong những năm 50, thời kì chiến tranh Liên Triều đang diễn ra, Swing Kids là một bộ phim nói về một nhóm nhảy tap dance được sinh ra ngay trong một nhà tù bao gồm 132,000 tù binh của Triều Tiên và Trung Quốc trong cuộc chiến. Năm thành viên của nhóm đều có những câu chuyện riêng khi đến với bộ môn khiêu vũ này nhưng tựu chung thì mục đích cuối cùng của họ là chiến thắng trong cuộc thi khiêu vũ diễn ra ngay trong chính nhà tù họ đang sống.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Doh Kyung-soo","avatar":""},{"name":"Jared Grimes","avatar":""},{"name":"Park Hye-su","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Kim Min-ho","avatar":""},{"name":"Ross Kettle","avatar":""},{"name":"A.J. Simmons","avatar":""},{"name":"Song Jae-ryong","avatar":""},{"name":"Lee Kyu-sung","avatar":""},{"name":"Lee Da-wit","avatar":""},{"name":"Kim Dong-gun","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Joo Hae-eun","avatar":""},{"name":"Park Hyoung-soo","avatar":""},{"name":"Matthew D''Arcy","avatar":""},{"name":"Kim Kyu-baek","avatar":""},{"name":"Oh Gyeong-hwa","avatar":""},{"name":"Joe Nowell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324396);
