INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hay-tien-ti', 'Tình Yêu hay Tiền Tỉ', 'App War', 'https://phimimg.com/upload/vod/20231113-1/f4ff7f0daf47bf79e1ed3c0878273892.jpg', 'https://phimimg.com/upload/vod/20231113-1/f7a5bf0bce9d56a8d29c0022e743cfe3.jpg', '<p>June và Bom, từ tình yêu trở thành đối thủ. Cuộc chiến giữa những ứng dụng công nghệ để giành lấy số tiền đầu tư cho dự án của mình. Cuộc chiến dở khóc dở cười diễn ra, liệu giữa họ sẽ là tình yêu hay số tiền thưởng khổng lồ.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nat Kitcharit","avatar":""},{"name":"Warisara Yu","avatar":""},{"name":"Ticha Wongtipkanon","avatar":""},{"name":"Patchanan Jiajirachote","avatar":""},{"name":"Sirat Intarachote","avatar":""},{"name":"Apiwich Reardon","avatar":""},{"name":"Thanapop Yoovijit","avatar":""},{"name":"Thanwa Jumpapha","avatar":""},{"name":"Jarnnawut Jarnyaharn","avatar":""},{"name":"Chutharat Boonjindamanee","avatar":""},{"name":"Bim Pavaputanont","avatar":""},{"name":"Thanyaratsm Napaphomanorat","avatar":""},{"name":"Naruthum Surakkha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
