INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-moi-nguy-hiem', 'Lời Mời Nguy Hiểm', 'Days of Power', 'https://phimimg.com/upload/vod/20231113-1/a78f978d94adfdb4028c4863e43114e9.jpg', 'https://phimimg.com/upload/vod/20231113-1/aa3d29ae16c3b832c61d8bc0d9a2ab65.jpg', '<p>Trong chuyến lưu diễn vòng quanh thế giới, nữ ngôi sao nhạc pop và những người bạn biến mất sau lời mời của một gã doanh nhân giàu có, khi cô vô tình nhìn thấy điều không nên biết. Một ngành công nghiệp đen tối không thể để bị phát giác, kẻ chứng kiến sẽ phải trải qua sự kinh hoàng hơn cả cái chết!</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"Eliza Roberts","avatar":""},{"name":"Jenny Hutton","avatar":""},{"name":"Alyssa Lee Lewis","avatar":""},{"name":"Robert Venable","avatar":""},{"name":"Lara Wolf","avatar":""},{"name":"Emily Norcia","avatar":""},{"name":"Dominic Ryan Gabriel","avatar":""},{"name":"Keaton Simons","avatar":""},{"name":"Missy Grynkiewicz","avatar":""},{"name":"Emily Grace Ranieri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324396);
