INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-ky-luc-to-hue-nang', 'Truyền Kỳ Lục Tổ Huệ Năng', 'Legend of Dajian Huineng', 'https://phimimg.com/upload/vod/20231123-1/03f9d4147d2ae9c7b43fc5968fc07411.jpg', 'https://phimimg.com/upload/vod/20231123-1/d8b48d667cab42ecddfa49a47045d0b7.jpg', '<p>Ngài Huệ-Năng họ Lư, sinh tại xứ Phạm-Dương bên Trung-Hoa, cha làm quan bị giáng chức đầy tới Lãnh-Nam làm thứ dân tại Tân-Châu, rồi mất sớm; từ khi ấy, Ngài còn rất trẻ không được đi học như các trẻ cùng lứa tuổi mà phải ngày ngày vào rừng kiếm củi đem đến chợ bán lấy tiền nuôi mẹ, nuôi thân, thật là khổ cực trăm bề; bởi thế, Ngài có thân hình gầy ốm, đen đủi, trông rất quê mùa.Bộ phim kể về con đường tìm đến Đức Phật của Lục Tổ Huệ Năng</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Zheng","avatar":""},{"name":"Zhang Lidel","avatar":""},{"name":"Ren Yi","avatar":""},{"name":"Zhou Yuhua","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324396);
