INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-huyet-mat', 'Sào Huyệt Mật', 'Kensho', 'null', 'https://phimimg.com/upload/vod/20231123-1/fadada7eeb99439928bd03e166aa7ea2.jpg', '<p>Bộ phim cực hay mang tính giải trí và kích thích tư duy hấp dẫn đạt được nhiều giải thưởng lớn và lời tán dương của giới phê bình phim. Về cuộc phiêu lưu của anh chàng Dan Bender đang quay cuồng sau cái chết của em gái và chìm vào ảo giác của tình ái và thuốc phiện, cuộc hội ngộ với cô nàng tình đầu như chất xúc tác cho hành trình tự khám phá bản thân mở rộng ý thức vượt qua mọi giới hạn của anh.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Raider","avatar":""},{"name":"Kaley Ronayne","avatar":""},{"name":"Steven Klein","avatar":""},{"name":"Grainger Hines","avatar":""},{"name":"Kathryn Erbe","avatar":""},{"name":"Sahr Ngaujah","avatar":""},{"name":"Christina Brucato","avatar":""},{"name":"Dana Ashbrook","avatar":""},{"name":"Kiran Merchant","avatar":""},{"name":"Danny Deferrari","avatar":""},{"name":"Madison McKinley","avatar":""},{"name":"Mara Davi","avatar":""},{"name":"Shyaporn Theerakulstit","avatar":""},{"name":"Matt Burns","avatar":""},{"name":"Michelle Cameron","avatar":""},{"name":"Ryan Johnston","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
