INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chu-harakuro-cua-toi', 'Ông chủ Harakuro của tôi', 'My Harakuro Boss', 'https://phimimg.com/upload/vod/20231123-1/fafdb121007b700096058cf76ad2801e.jpg', 'https://phimimg.com/upload/vod/20231123-1/91982f1372dd4951f0e7d273653fc229.jpg', '<p>Xuân Xuân, một phóng viên, nghi ngờ công ty của Zheng Yiqun đứng đằng sau việc đóng cửa công ty tạp chí cũ của cô sau khi cô đăng một bài báo về họ. Cô bí mật vào công ty của anh để tìm ra sự thật. Khi Xuân Xuân tiến lại gần anh hơn, cô bắt đầu nhận ra anh không xấu xa như cô nghĩ ban đầu nhưng chắc chắn thông minh hơn cô mong đợi. Zhang Yiqun đã biết danh tính của cô ngay từ đầu và cho cô quyền tự do làm việc trong công ty của anh để tự mình tìm ra sự thật. Khi đang dần yêu nhau, Xuân Xuân cũng bắt đầu nhận ra sự thật phức tạp hơn cô nghĩ. (Nguồn: Tổng hợp từ Baidu)</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tao Siyuan","avatar":""},{"name":"Du Yutong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
