INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-khong-phai-trong-co-tich', 'Nàng Tiên Không Phải Trong Cổ Tích', 'Pari', 'https://phimimg.com/upload/vod/20231121-1/3a0b7b5814431f6af9cddb5d584dcb67.jpg', 'https://phimimg.com/upload/vod/20231121-1/c499bb341bb79c68f7109b4396ef95d4.jpg', '<p>Chàng trai trẻ cùng gia đình đi xem mắt về đã gây ra một vụ tai nạn chết người. Áy náy vì khiến con gái nạn nhân mồ côi, chàng trai đã cưu mang cô gái. Nhưng thân phận cô gái đó lại không bình thường, cô được người ta gọi là &quot;Nàng tiên&quot; - một nàng tiên không giống như trong truyện cổ tích mà chúng ta thường nghe kể.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Anushka Sharma","avatar":""},{"name":"Parambrata Chatterjee","avatar":""},{"name":"Rajat Kapoor","avatar":""},{"name":"Ritabhari Chakraborty","avatar":""},{"name":"Mansi Multani","avatar":""},{"name":"Mithu Chakrabarty","avatar":""},{"name":"Dibyendu Bhattacharya","avatar":""},{"name":"Imran Rasheed","avatar":""},{"name":"Joydeep Mukherjee","avatar":""},{"name":"Anshuman Jha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324396);
