INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-linh', 'Hiển Linh', 'The Apparition', 'https://phimimg.com/upload/vod/20231111-1/5769baa3f1b13ddaa22a1fc6cf57b1a0.jpg', 'https://phimimg.com/upload/vod/20231111-1/1902c52ad66e11a3b551f95785f0d747.jpg', '<p>Danh tiếng của Jacques - là phóng viên kỳ cựu của một nhật báo lớn tại Pháp - đã được Thánh Bộ Vatican chú ý và tuyển dụng để làm việc cùng với một uỷ ban nghiên cứu xác thực về sự kiện đã xảy ra tại một ngôi làng trên dãy Alpes. Nơi có tin đồn một cô gái tên là Anna đã nhiều lần nhìn thấy Đức Mẹ hiện ra. Chuyện đó có thật hay không? Đứng trước các quan điểm đối lập giữa các linh mục và khi tiếp xúc với Anna, dần dần Jacques đã phát hiện ra nhiều bí ẩn khiến anh phải thay đổi quan điểm của mình...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Vincent Lindon","avatar":""},{"name":"Galatéa Bellugi","avatar":""},{"name":"Patrick d''Assumçao","avatar":""},{"name":"Anatole Taubman","avatar":""},{"name":"Elina Löwensohn","avatar":""},{"name":"Claude Lévêque","avatar":""},{"name":"Gérard Dessalles","avatar":""},{"name":"Bruno Georis","avatar":""},{"name":"Candice Bouchet","avatar":""},{"name":"Natalia Dontcheva","avatar":""},{"name":"Gervais Dimwana","avatar":""},{"name":"Bogdan Zamfir","avatar":""},{"name":"Éric Paul","avatar":""},{"name":"Joël Demarty","avatar":""},{"name":"François-Xavier Ledoux","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
