INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-tay-du-phuc-ma-ky', 'Giấc mộng tây du: Phục ma ký', 'Dream Journey 4: Biography of Demon', 'https://phimimg.com/upload/vod/20231111-1/bbb62f9246b0a1fe75cebacd6959739f.jpg', 'https://phimimg.com/upload/vod/20231111-1/d97a86fab0383ce21be1cdcfe42eb8c5.jpg', '<p>Trên đường đi lấy kinh, Đường Tăng và Tôn Ngộ Không xảy ra tranh chấp về vấn đề hàng phục yêu quái, Tôn Ngộ Không sử dụng di hình hoán ảnh đại pháp đem pháp lực của mình cho Đường Tăng, còn mình biến thành học thức uyên bác không hề có pháp lực. Di Hình Hoán Ảnh đại pháp chỉ hiệu quả trong 7 ngày, hai người lấy 7 ngày làm hạn định, chia nhau tới hàng phục bàn tơ động thất tiên và Bách Mục Ma Quân tại Hoàng Hoa Quan.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Sheng Nan","avatar":""},{"name":"Thomas Price","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Yi Zhengfu","avatar":""},{"name":"Fan Rui","avatar":""},{"name":"Ma Peng","avatar":""},{"name":"Mei''e Zhang","avatar":""},{"name":"Li Boer","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324396);
