INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-su-huynh', 'Đại Sư Huynh', 'Big Brother', 'https://phimimg.com/upload/vod/20231111-1/f9960af2cd19c664f8431e94c6e86ad9.jpg', 'https://phimimg.com/upload/vod/20231111-1/6f8b2f5f4c82ef50d3883521fb0b030d.jpg', '<p>Một giáo viên trung học mỗi ngày đều đặn tới trường gõ đầu trẻ cho đến một hôm…cậu học sinh do anh chủ nhiệm dính vào rắc rối với một băng đảng xã hội đen và bị bắt cóc. Đó cũng là lúc bí mật của“anh” thầy trước giờ luôn hiền lành, hết mực yêu thương học sinh và có tâm với nghề bị bộc lộ. Có vẻ như quá khứ máu lửa không buông tha “anh” thầy mà buộc anh phải trở lại con người xưa nhưng có khác là lần này không phải chiến đấu cho bản thân anh, mà cho những đứa trẻ mà anh luôn xem chúng như những đứa em trai.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Joe Chen","avatar":""},{"name":"Lok Ming-Kit","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Bruce Kwan-Chi Tong","avatar":""},{"name":"Chris Kwan-Yiu Tong","avatar":""},{"name":"Gladys Li","avatar":""},{"name":"Chiu-Kin Lau","avatar":""},{"name":"Ka Wah Lam","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Brahim Achabbakhe","avatar":""},{"name":"Craig Miller","avatar":""},{"name":"Jess Liaudin","avatar":""},{"name":"Lockhart Ogilvie","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Benjamin Au","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
