INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruben-brandt-collector', 'Ruben Brandt, Collector', 'Ruben Brandt, Collector', 'https://phimimg.com/upload/vod/20231111-1/186577df30c2c8962502052e98c2cc97.jpg', 'https://phimimg.com/upload/vod/20231111-1/4387c016ea2fd69b9af04766eb738b09.jpg', '<p>Một nhà trị liệu tâm lý gặp phải những cơn ác mộng bạo lực lấy cảm hứng từ các tác phẩm nghệ thuật huyền thoại. Bốn bệnh nhân của ông, kẻ trộm chuyên gia, đề nghị đánh cắp các công trình kể từ khi anh ta tin rằng một khi anh ta sở hữu chúng, những cơn ác mộng sẽ biến mất. Anh ta trở thành một tên tội phạm mong muốn được gọi là &quot;người sưu tầm&quot;. Ai dám bắt anh ta và băng đảng của mình?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2018, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Kamarás Iván","avatar":""},{"name":"Csaba Márton","avatar":""},{"name":"Gabriella Hámori","avatar":""},{"name":"Matt Devere","avatar":""},{"name":"Henry Grant","avatar":""},{"name":"Christian Nielson Buckholdt","avatar":""},{"name":"Katalin Dombi","avatar":""},{"name":"Paul Bellantoni","avatar":""},{"name":"Luca Bercovici","avatar":""},{"name":"Butch Engle","avatar":""},{"name":"Irén Bordán","avatar":""},{"name":"Scott Hoke","avatar":""},{"name":"Iván Hegedűs","avatar":""},{"name":"Peter Linka","avatar":""},{"name":"Virginia Proud","avatar":""},{"name":"Dave Fennoy","avatar":""},{"name":"Geoffrey Tho","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
