INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-hoang-tren-lanh-dia-ma', 'Kinh Hoàng Trên Lãnh Địa Ma', 'Ghostland', 'https://phimimg.com/upload/vod/20231110-1/f2689d3e5a8e93346bf7b7b262a4a2c1.jpg', 'https://phimimg.com/upload/vod/20231110-1/2d7e9ce4e4f5c9324d6265e071e4c035.jpg', '<p>Câu chuyện kể về một bà mẹ hai con thừa kế một ngôi nhà từ dì của cô. Vào đêm đầu tiên ở ngôi nhà mới, cô phải đối mặt với những kẻ đột nhập giết người và chiến đấu vì mạng sống của con gái mình. Mười sáu năm sau khi các cô con gái đoàn tụ tại ngôi nhà, mọi thứ trở nên rất kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Crystal Reed","avatar":""},{"name":"Mylène Farmer","avatar":""},{"name":"Anastasia Phillips","avatar":""},{"name":"Emilia Jones","avatar":""},{"name":"Taylor Hickson","avatar":""},{"name":"Rob Archer","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Alicia Johnston","avatar":""},{"name":"Erik Athavale","avatar":""},{"name":"Kevin Power","avatar":""},{"name":"Mariam Bernstein","avatar":""},{"name":"Ernesto Griffith","avatar":""},{"name":"Denis Cozzi","avatar":""},{"name":"Sharon Bajer","avatar":""},{"name":"Tony Braga","avatar":""},{"name":"Paul Titley","avatar":""},{"name":"Gordon Tanner","avatar":""},{"name":"Pao","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
