INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goyo-vi-tuong-tre-tuoi', 'Goyo: Vị tướng trẻ tuổi', 'Goyo: The Boy General', 'https://phimimg.com/upload/vod/20231110-1/a1a60e379a98155026c45afb0c68f21b.jpg', 'https://phimimg.com/upload/vod/20231110-1/c855c0e61b72330e51a129037466fd0f.jpg', '<p>Với bộ phim này (bộ ba phim chiến tranh thứ hai lấy bối cảnh cuộc chiến tranh Mỹ-Philippines vào đầu những năm 1900), cuộc cách mạng tiến hành chống lại người Mỹ sau cái chết đẫm máu của Tướng Antonio Luna. Những triết lý mâu thuẫn đằng sau cuộc đấu tranh anh hùng vẫn tiếp tục và được nhân cách hóa qua nhân vật đầy màu sắc của Tướng Gregorio &quot;Goyo&quot; del Pilar.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Paulo Avelino","avatar":""},{"name":"Carlo Aquino","avatar":""},{"name":"Arron Villaflor","avatar":""},{"name":"Mon Confiado","avatar":""},{"name":"Jeffrey Quizon","avatar":""},{"name":"Alvin Anson","avatar":""},{"name":"Gwen Zamora","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"Che Ramos","avatar":""},{"name":"Jojit Lorenzo","avatar":""},{"name":"Arthur Acuña","avatar":""},{"name":"Robert Seña","avatar":""},{"name":"Tomas Santos","avatar":""},{"name":"Empress Schuck","avatar":""},{"name":"Ronnie Lazaro","avatar":""},{"name":"RK Bagatsing","avatar":""},{"name":"Karl Medina","avatar":""},{"name":"Carlo Cr","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324396);
