INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-den-bandersnatch', 'Gương Đen: Bandersnatch', 'Black Mirror: Bandersnatch', 'https://phimimg.com/upload/vod/20231110-1/3138422c02b322cecd10aaa037f5235b.jpg', 'https://phimimg.com/upload/vod/20231110-1/bef5016e3050d6f3317d864d956d4dea.jpg', '<p>Black Mirror: Bandersnatch là bộ phim tâm lý viễn tưởng của Mỹ ra mắt vào năm 2018. Bối cảnh phim diễn ra vào những năm đầu thập niên 80 tại thành phố London, kể về cậu thanh niên trẻ tuổi Stefan Butler là một thần đồng công nghệ của nước Anh. &nbsp;Sau khi tìm được công việc tại một hãng phần mềm lớn của Anh, Stefan được giao nhiệm vụ phát triển một thể loại game mới và sẽ được công ty phát hành vào trước ngày giáng sinh. Vì là một fan hâm mộ của cuốn tiểu thuyết thần thoại Bandersnatch của nhà văn Jerome F. Davie, Stefan quyết định sẽ phát triển một game tương tác thực tế dựa trên nội dung và các nhân vật có trong quyển tiểu thuyết này. &nbsp;Tuy nhiên khi bắt tay vào xây dựng trò chơi, tâm trí Stefan bắt đầu trở nên khủng hoảng và rối loạn đến mức cậu không thể phân biệt được đâu là ảo, đâu là thật. Điều này cũng khiến cho Stefan trở nên bạo lực và có phần hoang tưởng dẫn đến việc không thể kiểm soát hành vi của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fionn Whitehead","avatar":""},{"name":"Craig Parkinson","avatar":""},{"name":"Alice Lowe","avatar":""},{"name":"Asim Chaudhry","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Tallulah Haddon","avatar":""},{"name":"Catriona Knox","avatar":""},{"name":"Paul Bradley","avatar":""},{"name":"Jonathan Aris","avatar":""},{"name":"A.J. Houghton","avatar":""},{"name":"Fleur Keith","avatar":""},{"name":"Laura Evelyn","avatar":""},{"name":"Alan Asaad","avatar":""},{"name":"Suzanne Burden","avatar":""},{"name":"Jeff Minter","avatar":""},{"name":"Sandra Teles","avatar":""},{"name":"Rochenda Sandall","avatar":""},{"name":"Elli","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324396);
