INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tang-cua-stalin', 'Chiến Tăng Của Stalin', 'Tanki - Tanks for Stalin', 'https://phimimg.com/upload/vod/20231109-1/32272691b9c27e17203f168fff268281.jpg', 'https://phimimg.com/upload/vod/20231109-1/ebaf0549ec3b4ef57a647f8d09798c3c.jpg', '<p>Bộ phim hư cấu nhưng dựa trên một sự kiện có thật về cuộc chạy thử nghiệm đã được tiến hành tháng 4 và 5 năm 1940, do Tổng công trình sư Xô-viết Mikhail Ilyich Koshkin lãnh đạo. Những sự kiện trong phim không có thật, nhưng những khó khăn để chiếc xe tăng ra đời là có thật. Nó vấp phải sự phản đối của rất nhiều thế lực chính trị trong Nhà nước Xô-viết thời bấy giờ. Nhân vật Đại tướng Zhukov trong phim là đại diện cho giới quân sự cấp tiến của Liên Xô. Vốn là sĩ quan kỵ binh trong quân đội Nga hoàng, ông nhận ra vai trò của lực lượng tăng thiết giáp sẽ có ảnh hưởng đến như thế nào trong những cuộc xung đột quân sự hiện đại.</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Andrey Merzlikin","avatar":""},{"name":"Aglaya Tarasova","avatar":""},{"name":"Anton Filipenko","avatar":""},{"name":"Dmitriy Podnozov","avatar":""},{"name":"Sergey Chetvertkov","avatar":""},{"name":"Aleksandr Tyutin","avatar":""},{"name":"Sergey Stukalov","avatar":""},{"name":"Alexey Ovsyannikov","avatar":""},{"name":"Nikolay Gorshkov","avatar":""},{"name":"Yuriy Itskov","avatar":""},{"name":"Vladimir Verevochkin","avatar":""},{"name":"Merab Maysuradze","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324396);
