INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-thuong-nguoc-dong-thanh-song', 'Bi Thương Ngược Dòng Thành Sông', 'Cry Me a Sad River', 'https://phimimg.com/upload/vod/20231109-1/fbed15740573770e08b7fbe79e3ef403.jpg', 'https://phimimg.com/upload/vod/20231109-1/e9aa6bed3cd368a2e860491c3061f61c.jpg', '<p>Cry Me a Sad River 2018 (Bi Thương Ngược Dòng Thành Sông) kể về một Dị Dao bình thường (Nhậm Mẫn) yêu thầm một nam sinh khét tiếng trong trường học Thảo Tề Minh (Triệu Anh Bác), luôn bị Đường Tiểu Mễ 1 nữ sinh của trường (Châu Dannel) trêu đùa. Đường Tiểu Mễ đem người bắt nạt Bá Băng, Cố Sâm Tây (Vận Vân Lai) đã giúp Dị Dao chống lại bọn họ , và khích lệ Dị Dao dũng cảm luôn là chính mình. Sau nỗ lực của hai người họ, Dị Dao cuối cùng đã thay đổi từ con vịt con xấu xí trở thành Cô gái tự tin tỏa sáng.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Yingbo","avatar":""},{"name":"Ren Min","avatar":""},{"name":"Yunlai Xin","avatar":""},{"name":"Zhang Ruonan","avatar":""},{"name":"Zhu Danni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
