INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-nhung-thien-than-ngu', 'Khi Những Thiên Thần Ngủ', 'When Angels Sleep', 'https://phimimg.com/upload/vod/20231109-1/d38aa881e7d49205349d0476874ce502.jpg', 'https://phimimg.com/upload/vod/20231109-1/08924db1dc5b075af2e5f59f9552fe26.jpg', '<p>Germán luôn bận rộn với công việc của mình, anh ta cố gắng về nhà để mừng sinh nhật con gái nhưng gặp rắc rối khi cứu một cô gái và bị hiểu lầm là người gây ra tai nạn đó...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Julián Villagrán","avatar":""},{"name":"Ester Expósito","avatar":""},{"name":"Marian Álvarez","avatar":""},{"name":"Asia Ortega","avatar":""},{"name":"Marisol Membrillo","avatar":""},{"name":"Christian Mulas","avatar":""},{"name":"Daniel Jumillas","avatar":""},{"name":"Sira Alonso","avatar":""},{"name":"Adolfo Fernández","avatar":""},{"name":"Javier Ruiz de Somavía","avatar":""},{"name":"Ramiro Alonso","avatar":""},{"name":"Font García","avatar":""},{"name":"Antonio Márquez","avatar":""},{"name":"Daniel Mantero","avatar":""},{"name":"Helena Castañeda","avatar":""},{"name":"Luis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
