INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-toi-loi', 'Thiên Thần Tội Lỗi', 'Killer In Red', 'https://phimimg.com/upload/vod/20231110-1/caf06c6fe90da94b85b1dcf7aae645ba.jpg', 'https://phimimg.com/upload/vod/20231110-1/b6cb3bf67a8839710178837d869bae5d.jpg', '<p>Thiên Thần Tội Lỗi - Killer In Red kể về một nữ hoàng quán bar xinh đẹp, quyến rũ, khiến cho bất cứ người đàn ông nào cũng mê mẩn ngay từ lần gặp đầu tiên. Nhưng người càng đẹp càng nguy hiểm, cái chết của gã đại gia bao bọc cô vẫn là một ẩn số.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Tammin Sursok","avatar":""},{"name":"Allison Paige","avatar":""},{"name":"Robin Riker","avatar":""},{"name":"Donna Feldman","avatar":""},{"name":"Greg Perrow","avatar":""},{"name":"Richard Gleason","avatar":""},{"name":"Jacob Osborne","avatar":""},{"name":"Kelly Ryan","avatar":""},{"name":"Steve Rizzo","avatar":""},{"name":"Emmy James","avatar":""},{"name":"Rosalie McIntire","avatar":""},{"name":"Bob Rumnock","avatar":""},{"name":"Blake Massad","avatar":""},{"name":"Charlotte Mary Wen","avatar":""},{"name":"Tessa Auberjonois","avatar":""},{"name":"Troy Osterberg","avatar":""},{"name":"Fidelia Grace","avatar":""}]', '[{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
