INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dam-dau-tien-cua-nha-duong', 'Cú đâm đầu tiên của nhà Đường', 'The First Stab of The Datang', 'https://phimimg.com/upload/vod/20231110-1/d5926ebfc853f47cdbd5e8eaa8808ace.jpg', 'https://phimimg.com/upload/vod/20231110-1/bb30f87fee410006b2185b641d2d601a.jpg', '<p>Nó kể câu chuyện đằng sau số phận gia đình của Hoàng tử bị tấn công bởi một cuộc tấn công kỳ lạ, khiến anh bị tổn thất nặng nề và không rõ tung tích. Hoàng hậu Wu rất tức giận và ra lệnh cho Zhong Xingluo (Guo Meilinzi), thủ lĩnh của Tianji Dao, đi tìm hoàng tử trong vòng bảy ngày. Trong quá trình tìm kiếm, anh bị hồn ma nửa yêu Hoàng đế Jun (Song Kai) tấn công. Trên đường đi, hai kẻ sát nhân tiếp tục giằng co với nhau, xác người văng khắp nơi. Cuối cùng, cả hai bên đều chịu tổn thất nặng nề.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kai Song","avatar":""},{"name":"Wei Sheng Jiang","avatar":""},{"name":"Yu Hui Tao","avatar":""},{"name":"Gao Xiangyu","avatar":""},{"name":"Chen Xi","avatar":""},{"name":"Guo Mei Lin Zi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324396);
