INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-yeu-phap-hai-truyen', 'Tập Yêu: Pháp Hải Truyện', 'Fa Hai', 'https://phimimg.com/upload/vod/20231110-1/f842ce8213c007f68106554b034e39c3.jpg', 'https://phimimg.com/upload/vod/20231110-1/ca4f045f61bde2c22c6e9934e2b3ad73.jpg', '<p>Thời kì hưng thịnh, yêu quái hoành hành, triều đình lập ra tổ chức “Tập Yêu Ti” chuyên lùng bắt yêu quái, từng thành viên đều phải uống máu yêu, để chống lại yêu ma. Nhưng nếu không thể giữ được tấm lòng trong sạch như nước, thì sẽ bị máu yêu phản phệ, hóa thành bán yêu. Ban đêm, thủ lĩnh Tập yêu ti Bùi Văn Đức dẫn người ra ngoài thành tìm kiếm yêu khí lạ xuất hiện. Tại nơi đó phát hiện một thiếu nữ tên Bạch Thanh Thanh thực chất là một con cự xà, trong lúc hai bên giao chiến, hoàng cung bị Quỷ Vương tập kích, tính mạng hoàng đế như chỉ mành treo chuông.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bai Yu","avatar":""},{"name":"Jiang Zhenhao","avatar":""},{"name":"Liu Yuhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324396);
