INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-song-ngoai-vu-tru', 'Sự Sống Ngoài Vũ Trụ', 'High Life', 'https://phimimg.com/upload/vod/20231109-1/1331be65c49102ab9b5d94c399e37a19.jpg', 'https://phimimg.com/upload/vod/20231109-1/0704c08f4ff97323c01fa7d0d0c0c5d5.jpg', '<p>Monte (Robert Pattinson) và con gái bé bỏng của mình bị mắc kẹt trong một nhiệm vụ nguy hiểm cùng cực đến không gian sâu thẳm. Phi hành đoàn dẫn đầu bởi một bác sĩ (Juliette Binoche) với động cơ độc ác - đã biến mất. Khi bí ẩn về những gì đã xảy ra trên con tàu được làm sáng tỏ, cha và con gái phải dựa vào nhau để sống sót khi họ đang dần tiến về vùng bí ẩn của một lỗ đen.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"André 3000","avatar":""},{"name":"Mia Goth","avatar":""},{"name":"Agata Buzek","avatar":""},{"name":"Lars Eidinger","avatar":""},{"name":"Claire Tran","avatar":""},{"name":"Ewan Mitchell","avatar":""},{"name":"Gloria Obianyo","avatar":""},{"name":"Victor Banerjee","avatar":""},{"name":"Scarlett Lindsey","avatar":""},{"name":"Jessie Ross","avatar":""},{"name":"Mikolaj Gruss","avatar":""},{"name":"Joni Brauer","avatar":""},{"name":"Johann Bartlitz","avatar":""},{"name":"Juliette Picollot","avatar":""},{"name":"Weronika Wach","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324396);
