INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-xac-toi-loi', 'Thân Xác Tội Lỗi', 'Body Of Sin', 'https://phimimg.com/upload/vod/20231109-1/3b7b34f216a3d0f5198b89ed183b9065.jpg', 'https://phimimg.com/upload/vod/20231109-1/085edf3a00b001a8049623f414374cef.jpg', '<p>Erica và Lauren dùng sự hấp dẫn của mình để quyến rũ những người đàn ông. Khi “con mồi” Scott Purcell lọt vào tầm ngắm của họ, Erica đã chụp thuốc mê và lấy đi số viên kim cương trị giá hàng triệu đô-la của anh ta. Những tưởng phi vụ trót lọt, nào ngờ đâu khi biết Scott bị sát hại, họ lại vướng vào một cuộc trốn chạy không hồi kết.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elisha Kriis","avatar":""},{"name":"Ellie Patrikios","avatar":""},{"name":"William Mark McCullough","avatar":""},{"name":"Riccardo Berdini","avatar":""},{"name":"Danny Arroyo","avatar":""},{"name":"Barry Piacente","avatar":""},{"name":"Cree Michelle Rogers","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324396);
