INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phut-kinh-hoang-tai-el-royale', 'Phút Kinh Hoàng Tại El Royale', 'Bad Times at the El Royale', 'https://phimimg.com/upload/vod/20231109-1/cc36a54bf5c4efc93cbdf9372c1d2c1f.jpg', 'https://phimimg.com/upload/vod/20231109-1/764b27787ed2a71c784ecab6d628dec7.jpg', '<p>Bad Times at the El Royale lấy bối cảnh El Royale – một khách sạn sang trọng và lâu đời tại nơi giao nhau giữa California và Nevada. Một ngày nọ, chàng lễ tân trẻ tuổi chào đón cùng lúc sáu vị khách bí ẩn. Họ gồm mục sư Daniel Flynn, nữ ca sĩ Darlene Sweet, hai chị em nhà Summerspring , tay bán máy hút hút bụi Laramie Seymour Sullivan và thủ lĩnh giáo phái bí ẩn Billy Lee . Song, tất cả chỉ là danh tính giả khi mỗi người đều có một bí mật đen tối muốn chôn giấu. &nbsp;Họ dường như đều có liên quan đến một vụ cướp xe chở tiền và án mạng bí ẩn. Không những thế, kịch tính càng được đẩy lên cao trào khi Laramie Seymour Sullivan có thể quan sát tất cả các phòng thông qua một con đường hầm bí mật và hé lộ rằng hắn ta đang làm việc với một thế lực có tên “Ban quản lý”. Bảy kẻ xa lạ tìm kiếm theo dõi và giết hại lẫn nhau, ai sẽ người chiến thắng? Tổ chức bí ẩn kia là gì? Danh tính thật sự của kẻ thủ ác là ai? Vụ cướp kia và âm mưu của từng người là gì?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Dakota Johnson","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Lewis Pullman","avatar":""},{"name":"Cailee Spaeny","avatar":""},{"name":"Chris Hemsworth","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Xavier Dolan","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Charles Halford","avatar":""},{"name":"Jim O''Heir","avatar":""},{"name":"Gerry Nairn","avatar":""},{"name":"Alvina August","avatar":""},{"name":"London Morrison","avatar":""},{"name":"Bethany Brow","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
