INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-nuoi-bat-dac-di', 'Con Nuôi Bất Đắc Dĩ', 'Instant Family', 'https://phimimg.com/upload/vod/20231109-1/24c142fcea1c95d125b2ae714df54042.jpg', 'https://phimimg.com/upload/vod/20231109-1/c93ce0a6ece97a2160c2da2e012ba7e4.jpg', '<p>Pete (do Mark Wahlberg thủ vai) và Ellie (Rose Byrne thủ vai) phải học được cách làm bố mẹ nuôi khi họ nhận nuôi ba đứa trẻ. Lấy cảm hứng từ một câu chuyện có thật, những tác giả của bộ phim Khi bố ở nhà cho thấy rằng đây là một bộ phim hài kịch gia đình rất đáng xem.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Allyn Rachel","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Tig Notaro","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Gustavo Escobar","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Julianna Gamiz","avatar":""},{"name":"Tom Segura","avatar":""},{"name":"Britt Rentschler","avatar":""},{"name":"Michael O''Keefe","avatar":""},{"name":"Jody Thompson","avatar":""},{"name":"Iliza Shlesinger","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Joy Ja","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
