INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-kung-fu', 'Huyền Thoại Kung Fu', 'Kung Fu League', 'https://phimimg.com/upload/vod/20231109-1/f792d8d88719b3ee86d183e91c346ab0.jpg', 'https://phimimg.com/upload/vod/20231109-1/a02e4cdf2a487147f4559b3d17c6070a.jpg', '<p>Diệp Vấn, Trần Chân, Hoàng Phi Hồng, Hoắc Nguyên Giáp – 4 vị tôn sư võ thuật của Trung Quốc – sẽ cùng góp mặt trong HUYỀN THOẠI KUNG FU. Bốn võ sư, bốn môn phái, đại diện cho bốn thời đại khác nhau gặp nhau và gây ra vô số tình huống dở khóc dở cười. Liệu những rắc rối của thời hiện đại có khiến tứ đại tôn sư lừng danh thiên hạ trong quá khứ phải chùn bước?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Andy On","avatar":""},{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Yu-Hang To","avatar":""},{"name":"Ashin Shu","avatar":""},{"name":"Bruce Siu-Lung Leung","avatar":""},{"name":"Lam Tze-chung","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Mars","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Madina Memet","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Ziwen Zhang","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Huang Liuy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
