INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-nguoi-khong-gian-thoi-gian-va-con-nguoi', 'Con Người, Không Gian, Thời Gian Và Con Người', 'Human, Space, Time and Human', 'https://phimimg.com/upload/vod/20231109-1/be0c1cb53273ddcb5cd2c5d635bb1879.jpg', 'https://phimimg.com/upload/vod/20231109-1/80e82e3523c49b60a6e761b8e473111e.jpg', '<p>Con Người, Không Gian, Thời Gian Và Con Người xoay quanh một nhóm người cùng bước lên một tàu chiến cũ, mục đích hay điểm đến của họ khi đi trên chuyến tàu này là gì đều không được nhắc đến. Nhóm người chủ yếu là người Hàn, có một số là người Nhật, với đủ hạng người từ chính trị gia, côn đồ, nghệ sĩ đến gái mại dâm,... Chưa được bao lâu thì nhóm côn đồ bắt đầu cà khịa, chúng ra oai với đám thanh niên mới lớn, sau đó chúng tiếp cận chính tri gia với ý đồ bẩn thỉu. Eva cùng chồng mới cưới tưởng chừng có chuyến trăng mật đáng nhớ nhưng lại là sự nghiệt ngã đến kinh hoàng, họ bắt đầu bị lôi vào cuộc chiến máu me, bạo lực và dục tính.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Mina Fujii","avatar":""},{"name":"Jang Keun-suk","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Lee Sung-jae","avatar":""},{"name":"Ryoo Seung-bum","avatar":""},{"name":"Joe Odagiri","avatar":""},{"name":"Sung Ki-yoon","avatar":""},{"name":"Yeo Min-jeong","avatar":""},{"name":"Lee Yoo-jun","avatar":""},{"name":"Hwang Geon","avatar":""},{"name":"Tae Hang-ho","avatar":""},{"name":"Han Sa-myung","avatar":""},{"name":"Kim Dong-chan","avatar":""},{"name":"Park Se-in","avatar":""},{"name":"Park Kyung-man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
