INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-no-thue', 'Đòi Nợ Thuê', 'The Debt Collector', 'https://phimimg.com/upload/vod/20231109-1/aa4418fa4deed5fad7f2d9952e5d7aff.jpg', 'https://phimimg.com/upload/vod/20231109-1/dffe52f2706b8ba290511cb06d8c7daf.jpg', '<p>Một võ sĩ được đào tạo theo phong cách cổ điển đi làm việc như là một kẻ thu nợ nần. Công việc dường như dễ dàng, cho đến khi một khách hàng kéo anh ta vào một tình huống sâu hơn bao giờ hết không thể được dự đoán dược các nguy hiểm đang rình rập anh..</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Vladimir Kulich","avatar":""},{"name":"Robert Rusler","avatar":""},{"name":"Selina Lo","avatar":""},{"name":"Nihan Gur","avatar":""},{"name":"Sara Finley","avatar":""},{"name":"Essam Ferris","avatar":""},{"name":"Marshal Hilton","avatar":""},{"name":"Danice Cabanela","avatar":""},{"name":"Grant Harling","avatar":""},{"name":"Geordie Robinson","avatar":""},{"name":"Jack Lowe","avatar":""},{"name":"Rich Manley","avatar":""},{"name":"Sean Crampton","avatar":""},{"name":"Justin Gant","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324396);
