INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spinning-man', 'Spinning Man', 'Spinning Man', 'https://phimimg.com/upload/vod/20231108-1/c8e45804b78f79b704f6b73baf9ac8f0.jpg', 'https://phimimg.com/upload/vod/20231108-1/09283645f68d851efe9db7dc80aacf4d.jpg', '<p>Evan Birch là một giáo sư gia đình và tôn trọng tại một trường cao đẳng nổi tiếng, nơi sự quyến rũ và danh tiếng của ông đã khiến lớp triết học của mình rất phổ biến. Khi một nữ sinh có tên Joyce bị mất tích, Dallians ngoài trường trước đây của Evan khiến vợ hỏi Alibi của mình. Malloy thám tử cảnh sát coluff thậm chí còn có nhiều lý do hơn để nghi ngờ khi bằng chứng quan trọng làm cho Evan nghi ngờ chính trong sự mất tích của Joyce. Đột nhiên, các câu hỏi mà Evan Faces không chỉ đơn thuần là học tập - họ là vấn đề sống hay cái chết.</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Odeya Rush","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Sean Blakemore","avatar":""},{"name":"Eliza Pryor","avatar":""},{"name":"Noah Salsbury Lipson","avatar":""},{"name":"Jeannie Austin","avatar":""},{"name":"Natasha Bassett","avatar":""},{"name":"Sterling Beaumon","avatar":""},{"name":"Patrika Darbo","avatar":""},{"name":"Jennie Fahn","avatar":""},{"name":"John Mariano","avatar":""},{"name":"Irene Rosee","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
