INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-tro-bi-an', 'Khách Trọ Bí Ẩn', 'Hospitality', 'https://phimimg.com/upload/vod/20231116-1/7d7dfdda5392c7d566ee16616985fa76.jpg', 'https://phimimg.com/upload/vod/20231116-1/eb97d87c08565d7706f0216a964e8f72.jpg', '<p>Một người phụ nữ với quá khứ bí ẩn, phải dùng hết sức lực và trí tuệ để bảo vệ đứa con trai duy nhất khỏi sự uy hiếp của gã đàn ông nguy hiểm đang ở trong khu nhà nghỉ biệt lập của cô ấy.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Conner McVicker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324396);
