INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-tay-hu-khong', 'Phía tây hư không', 'West of Nowhere', 'null', 'https://phimimg.com/upload/vod/20231116-1/da99ae9c30c9c47d796ed477c058c8f8.jpg', '<p>Tại một thị trấn hoang vắng ở miền Tây nước Mỹ, Stan, được mệnh danh là &quot;nghệ sĩ điên&quot;, đã thiết lập thế lực của riêng mình tại đây và trở thành người quyền lực nhất thị trấn. Young Heng là một đứa trẻ ngây thơ, ước mơ lớn nhất của anh ở giai đoạn này là nâng cấp chiếc xe tay ga của mình thành một chiếc mô tô hạng nặng, vì lý do này, anh đã tìm được cơ hội để giúp đỡ Stan làm việc. Cùng lúc đó, Chan, người đến thị trấn để điều tra cái chết của bạn trai, để được gần gũi với Stan, cô cũng nộp đơn xin trở thành người chăm sóc chăm sóc ngôi nhà cần sa của Stan. Khi Can mới đến thị trấn, Stan thận trọng đã chú ý đến cô gái Trung Quốc có khí chất nổi bật này. Nhưng Heng đã yêu nàng Can xinh đẹp ngay từ cái nhìn đầu tiên và yêu cô ấy sâu sắc... Một chàng trai cô đơn, một cô gái mang trong mình hận thù và một kẻ sát nhân khát máu chuẩn bị bắt đầu cuộc hành trình trên vùng đất hoang vắng cằn cỗi này. bão.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Ross","avatar":""},{"name":"Mark Hatfield","avatar":""},{"name":"Anthony Lien","avatar":""},{"name":"Zhang Jizhong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324396);
