INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-ky-dam-luu-nguyet-chieu-minh', 'Cổ Kiếm Kỳ Đàm: Lưu Nguyệt Chiêu Minh', 'Legend of the Ancient Sword', 'https://phimimg.com/upload/vod/20231116-1/9a6cc224eca71c5955b47aaef8a4056c.jpg', 'https://phimimg.com/upload/vod/20231116-1/395940c02233a7844919aef9b460f205.jpg', '<p>Cổ Kiếm Kỳ Đàm: Lưu Nguyệt Chiêu Minh xoay quanh hành trình tìm thanh kiếm Chiêu Minh đầy gian nguy của Nhạc Vô Dị, Văn Nhân Vũ, Hạ Di Tắc và A Nguyễn để ngăn cản tai nạn sắp xảy ra ở thành Lưu Nguyệt. Truyền thuyết về thanh kiếm cổ là một bộ phim hành động phiêu lưu giả tưởng của Trung Quốc do Renny Harlin đạo diễn và dựa trên trò chơi điện tử Gu Jian Qi Tan 2.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leehom Wang","avatar":""},{"name":"Victoria Song","avatar":""},{"name":"Godfrey Gao","avatar":""},{"name":"Archie Kao","avatar":""},{"name":"Karena Ng","avatar":""},{"name":"Julian Cheung","avatar":""},{"name":"Liu Yan","avatar":""},{"name":"Li Yuan","avatar":""},{"name":"Na Wei","avatar":""},{"name":"Dany Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324396);
