INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dao-ngoan-muc', 'Cú Đảo Ngoạn Mục', 'Acts of Violence', 'https://phimimg.com/upload/vod/20231108-1/d4246d0e50f1f680b55b9d03ebf04e23.jpg', 'https://phimimg.com/upload/vod/20231108-1/091726263418142ccd40444a26d8a3fa.jpg', '<p>Nội dung chính của bộ phim là câu chuyện về Roman, vị hôn thê của anh bị bắt cóc bởi một bọn buôn người và anh buộc phải tìm cách giải cứu người vợ sắp cưới của mình trước khi quá muộn. Roman cùng với những người anh em cựu quân nhân của mình bắt đầu theo dõi hành tung của bọn buôn người để có thể tìm ra vị trí giam giữ cô gái và lên kế hoạch giải cứu. Trên đường theo dõi Roman gặp được Avery – một cảnh sát điều tra nạn buôn người và đang đấu tranh với một bộ máy chính quyền thối nát có những ý định hãm hại con người. Cả hai đã quyết định bắt tay với nhau để có thể đưa bọn tội phạm ra ngoài ánh sáng. Liệu rằng cả hai có thể giải thoát cho hôn thê của Roman và vạch trần sự thật đằng sau?</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Ashton Holmes","avatar":""},{"name":"Melissa Bolona","avatar":""},{"name":"Sean Brosnan","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Tiffany Brouwer","avatar":""},{"name":"Jenna B. Kelly","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"Rotimi","avatar":""},{"name":"Matt Metzler","avatar":""},{"name":"Kyle Stefanski","avatar":""},{"name":"Boyd Kestner","avatar":""},{"name":"Nick Petron","avatar":""},{"name":"David Vegh","avatar":""},{"name":"Jerrad Christi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8