INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-toi-cuoi-cung-o-dia-cau', 'Đêm Tối Cuối Cùng Ở Địa Cầu', 'Long Day''s Journey Into Night', 'https://phimimg.com/upload/vod/20231108-1/b90a1ee899c41396c112b15614bc83a6.jpg', 'https://phimimg.com/upload/vod/20231108-1/b899ebb7bf5f210109b7ab6b015efd8d.jpg', '<p>Một người đàn ông trở về quê hương Quý Châu để tìm kiếm người phụ nữ bí ẩn đã cùng anh trải qua mùa hè không thể nào quên mười hai năm trước. Người phụ nữ đó không bao giờ nói tên, hoặc bất kỳ chi tiết nào về cuộc đời cô cho anh, và điều duy nhất anh ấy nhớ là tên của ngôi sao điện ảnh mà cô viết trên bao thuốc lá.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tang Wei","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Lee Hong Chi","avatar":""},{"name":"Chen Yongzhong","avatar":""},{"name":"Zeng Meihuizi","avatar":""},{"name":"Duan Chun-hao","avatar":""},{"name":"Bi Yanmin","avatar":""},{"name":"Feiyang Luo","avatar":""},{"name":"Lixun Xie","avatar":""},{"name":"Qi Xi","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Long Zezhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324396);
