INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-ga-mo-2', 'Thám Tử Gà Mơ 2', 'The Accidental Detective 2: In Action', 'https://phimimg.com/upload/vod/20231108-1/673b4214f761b0a02182aa2e975179e7.jpg', 'https://phimimg.com/upload/vod/20231108-1/7d317c28890b960ae4697430de46dbac.jpg', '<p>Để giải quyết một vụ án chưa có lời giải và hiện thực hóa giấc mơ làm thám tử, chủ cửa hàng truyện tranh Kang Dae-man (Kwon Sang-woo đóng) và thám tử huyền thoại Noh Tae-soo (Sung Dong-il đóng) đã nghỉ việc khỏi đội điều tra cùng hợp tác mở một văn phòng thám tử và mời nhân vật hàng đầu trong đội điều tra an ninh mạng trước đây là Yeo Chi (Lee Kwang-woo đóng) tham gia, mở ra bước đi đầu tiên trong sự nghiệp thám tử. Nhưng ước mơ và thực tế luôn có khoảng cách. Văn phòng thám tử không có khách hàng, khó có thể duy trì hoạt động bình thường vì vấn đề tài chính. Sau một thời gian dài chờ đợi, cuối cùng văn phòng thám tử cũng đã có khách hàng đầu tiên và thù lao khi vụ án thành công lên tới 50 triệu won. Ba người tự tin tiếp nhận vụ án, nhưng càng điều tra, họ càng gặp phải rắc rối vì liên tiếp có những bằng chứng đáng ngờ.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Nam Myung-ryeol","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Son Dam-bi","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Choi Sung-won","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Park Sung-il","avatar":""},{"name":"Jeong Yeon-joo","avatar":""},{"name":"Oh Hee-joon","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Kim Joong-ki","avatar":""},{"name":"Lee Chung-hee","avatar":""},{"name":"Kim Yong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324396);
