INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-tuyet-vong', 'Ngôi Sao Tuyệt Vọng', 'Broken Star', 'https://phimimg.com/upload/vod/20231108-1/5ac643057b95764cf6a95f25bd4add44.jpg', 'https://phimimg.com/upload/vod/20231108-1/8bda2713552cf104bf5e036253a64389.jpg', '<p>Bị bạn bè và người thân bỏ rơi còn cánh báo chí thì săn đuổi ráo riết, ngôi sao nhiều tai tiếng Markey Marlowe được người quản lý đưa đi lánh mặt tại một căn hộ bí mật. Tại đây, cô làm quen với người chủ nhà tên Daryl và dần dần mở lòng, giãi bày hết mọi tâm sự với anh. Tuy nhiên, mối quan hệ này lại dẫn đến những hậu quả mà Markey không thể nào lường trước được.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lio Tipton","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Lauren Bowles","avatar":""},{"name":"Monique Coleman","avatar":""},{"name":"Natasha Loring","avatar":""},{"name":"Alex Lombard","avatar":""},{"name":"Josh Davis","avatar":""},{"name":"Addyson Bell","avatar":""},{"name":"Scott Hamm Duenas","avatar":""},{"name":"Kevin Ross","avatar":""},{"name":"Silvia Tovar","avatar":""},{"name":"Ben Moroski","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
