INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-dao-cocaine', 'Truyền thuyết đảo Cocaine', 'The Legend of Cocaine Island', 'https://phimimg.com/upload/vod/20231107-1/c2a9953d9455c6634f40a61ec9aa306d.jpg', 'https://phimimg.com/upload/vod/20231107-1/19785de7c25c2ea6a2ac8a6b9b5bf4e5.jpg', '<p>Tin vào truyền thuyết đô thị về túi cocaine được chôn ở vùng Caribe, một nhóm người lập dị lên kế hoạch điên rồ nhằm tìm kiếm nó trong bộ phim tài liệu hài hước này.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bo Butterworth","avatar":""},{"name":"Bri Bryant","avatar":""},{"name":"Andy Culpepper","avatar":""},{"name":"Arthur Dean","avatar":""},{"name":"Greg Engleberg","avatar":""},{"name":"Matthew Ezell","avatar":""},{"name":"Edward Steven Harris II","avatar":""},{"name":"Emily Hyden","avatar":""},{"name":"Jamie Hyden","avatar":""},{"name":"Rodney Hyden","avatar":""},{"name":"Michael Opal","avatar":""},{"name":"Danny Pardo","avatar":""},{"name":"Mark Rosenblum","avatar":""},{"name":"Paul D. Schad","avatar":""},{"name":"Melissa Moore Stockham","avatar":""},{"name":"Jesse Yarborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324397);
