INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-dao-cocaine', 'Truyền thuyết đảo Cocaine', 'The Legend of Cocaine Island', 'truyền thuyết đảo cocaine the legend of cocaine island bo butterworth bri bryant andy culpepper arthur dean greg engleberg matthew ezell edward steven harris ii emily hyden jamie hyden rodney hyden michael opal danny pardo mark rosenblum paul d. schad melissa moore stockham jesse yarborough ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-ninja', 'Người Dơi Ninja', 'Batman Ninja', 'https://phimimg.com/upload/vod/20231107-1/5ac2250f34b0bcd1a29b48bf9bcb9aae.jpg', 'https://phimimg.com/upload/vod/20231107-1/f5722e560ee46dcec4fef080b1f411b1.jpg', '<p>Batman Ninja xoay quanh chuyến du hành vượt thời gian do cỗ máy dịch chuyển thời gian của Gorilla Grodd đã chuyển những kẻ đối địch với Batman đến Nhật Bản thời phong kiến. Kể cả Batman và đồng minh của anh cũng đã bị đưa đến nơi này. Dưới hình dáng lãnh chúa phong kiến, bọn gian ác ấy đã tung hoành ngang dọc và thống trị nhiều vùng đất ở đây và Joker là tên cầm đầu của bọn gây rối này. Ở nơi này, những món vũ khí công nghệ cao của Batman đã nhanh chóng hết nhiên liệu. Batman chỉ có thể trông cậy vào tài trí của bản thân cùng những người bạn đồng hành của mình để mang lại yên bình cho vùng đất này và quay trở lại thời điểm cũ. &nbsp;Vẫn là Batman với cơ thể của người phàm và bộ não siêu việt, nhưng dùng phi tiêu của một ninja, mặc áo giáp và dùng kiếm như một chiến binh thời Chiến Quốc, Batman Ninja hứa hẹn là bộ phim vừa thân quen nhưng không kém phần mới mẻ hấp dẫn</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Koichi Yamadera","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Cho","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Atsuko Tanaka","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Anna Mugiho","avatar":""},{"name":"Juri Nagatsuma","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
