INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tang-huyen-thoai', 'Chiến Tăng Huyền Thoại', 'Т-34', 'https://phimimg.com/upload/vod/20231114-1/22f49e33b868efaa2c6e4c05d777f572.jpg', 'https://phimimg.com/upload/vod/20231114-1/c7a287627148856ffd40c9072af63a15.jpg', '<p>Năm 1944, một nhóm binh sĩ Nga can đảm đã trốn thoát khỏi sự giam cầm của Đức trong chiếc xe tăng T-34 huyền thoại đã bị phá hủy một nửa. Đó là những lần dũng cảm khó quên, chiến đấu khốc liệt, tình yêu không thể phá vỡ và là một phép màu...</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Alexander Petrov","avatar":""},{"name":"Victor Dobronravov","avatar":""},{"name":"Irina Starshenbaum","avatar":""},{"name":"Vinzenz Kiefer","avatar":""},{"name":"Petr Skvortsov","avatar":""},{"name":"Semyon Treskunov","avatar":""},{"name":"Artyom Bystrov","avatar":""},{"name":"Michael Janibekyan","avatar":""},{"name":"Anton Bogdanov","avatar":""},{"name":"Sofya Sinitsyna","avatar":""},{"name":"Yuliya Dzhulai","avatar":""},{"name":"Darya Hramtsova","avatar":""},{"name":"Vasiliy Uriyevskiy","avatar":""},{"name":"Vasiliy Butkevich","avatar":""},{"name":"Yarosl","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324397);
