INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bac-sieu-nhan', 'Ông Bác Siêu Nhân', 'Inuyashiki', 'https://phimimg.com/upload/vod/20231103-1/65d2db27334bdac36e78698aa4162e1a.jpg', 'https://phimimg.com/upload/vod/20231103-1/e76802090724f506f7b3fb2cf21633ea.jpg', '<p>Ông Inuyashiki là một lão già khốn khổ có công việc và đời sống gia đình không mấy tốt đẹp.. Bỗng một ngày, ông và một cậu học sinh tên Hiro chứng kiến một vụ nổ từ chiếc phi thuyền của người ngoài hành tinh và bị biến đổi thành một con người mới có sức mạnh siêu nhiên. Trong khi Hiro muốn hủy diệt thế giới thì ông Inuyashiki lại muốn dùng năng lực này để cứu người và ngăn cản Hiro.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Noritake Kinashi","avatar":""},{"name":"Takeru Satoh","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Fumi Nikaido","avatar":""},{"name":"Ayaka Miyoshi","avatar":""},{"name":"Nayuta Fukuzaki","avatar":""},{"name":"Mari Hamada","avatar":""},{"name":"Yuki Saito","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Moeka Koizumi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324397);
