INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-grump-va-vuong-quoc-sac-mau', 'Phù Thủy Grump Và Vương Quốc Sắc Màu', 'A Wizard''s Tale', 'https://phimimg.com/upload/vod/20231103-1/5131a2aa0d026c9c4b703ca85f9566a4.jpg', 'https://phimimg.com/upload/vod/20231103-1/d1b582da410a94d61f1611730594277c.jpg', '<p>Câu chuyện của một phù thủy là một câu chuyện phiêu lưu gia đình kỳ diệu nhìn thấy một đứa trẻ tên là Terry (Toby Kebbell) đã đánh bại vương quốc đầy màu sắc của Groovynham. Wizard Wizard Grump (Ian McShane) đã ban một câu thần chú về vùng đất và như vậy, mỉm cười và tiếng cười bây giờ là một điều của quá khứ. Terry phải đi du lịch vương quốc trong việc tìm kiếm một câu thần chú sẽ giúp lấy lại hạnh phúc của mọi người và dọc theo cách giúp Công chúa bình minh (Lily Collins), đánh lừa tất cả các sinh vật kỳ lạ và tuyệt vời, và thử một cái ôm một thứ có tên &quot;Thay đổi&quot;.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2018, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Toby Kebbell","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Keith Wickham","avatar":""},{"name":"David Holt","avatar":""},{"name":"Rasmus Hardiker","avatar":""},{"name":"Emma Tate","avatar":""},{"name":"Amy Thompson","avatar":""},{"name":"Jay Britton","avatar":""},{"name":"Andres Williams","avatar":""},{"name":"Claire Morgan","avatar":""},{"name":"Paul Tylak","avatar":""},{"name":"Darren Altman","avatar":""},{"name":"Inel Tomlinson","avatar":""},{"name":"Sophie Aldred","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324397);
