INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-tro-ve', 'Xác Chết Trở Về', 'The Vanished', 'https://phimimg.com/upload/vod/20231103-1/cdf18a41e78a1da1ed5f2cd536892725.jpg', 'https://phimimg.com/upload/vod/20231103-1/a5416cefd1966af2e78bef42e6da7151.jpg', '<p>YOON Seol-hee, Chủ tịch của một tập đoàn lớn, được phát hiện đã tử vong. Xác của cô ta đặt trong nhà xác, đang chờ được khám nghiệm bởi Cục Pháp Y Quốc Gia, thì đột nhiên nó biến mất một cách bí ẩn không dấu vết. Trong khi người chồng cô ta đang bị nghi ngờ là thủ phạm, cảnh sát Joongsik quyết điều tra cho ra người đã đánh cắp cái xác và vì lí do gì.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sang-kyung","avatar":""},{"name":"Kim Kang-woo","avatar":""},{"name":"Kim Hee-ae","avatar":""},{"name":"Han Ji-an","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Kyung Soo-jin","avatar":""},{"name":"Lee Ji-hoon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
