INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-co-doc', 'Sói Cô Độc', 'Reprisal', 'https://phimimg.com/upload/vod/20231103-1/29e2c3295a26dce03ae6ed877a4f25fb.jpg', 'https://phimimg.com/upload/vod/20231103-1/3b4fe2382037435b151a2fac39df3495.jpg', '<p>Như một con sói cô độc, Jacob luôn một mình thực hiện các phi vụ mà hắn được thuê. Tuy nhiên, sau lần cướp ngân hàng, hắn linh cảm mình đang sa bẫy nên nhờ sự trợ thủ của James - một người hàng xóm. Nhưng kết quả cuối cùng chính hắn và James cũng không thể lường trước được ...</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Grillo","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Johnathon Schaech","avatar":""},{"name":"Olivia Culpo","avatar":""},{"name":"Natali Yura","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"Shea Buckner","avatar":""},{"name":"Christopher Rob Bowen","avatar":""},{"name":"Ken Strunk","avatar":""},{"name":"Tamara Belous","avatar":""},{"name":"Cameron Brexler","avatar":""},{"name":"Geoff Reeves","avatar":""},{"name":"John Dauer","avatar":""},{"name":"Nicolas Petron","avatar":""},{"name":"Uncle Mu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324397);
