INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-choi-nho-doi', 'Đêm Chơi Nhớ Đời', 'Game Night', 'null', 'https://phimimg.com/upload/vod/20231103-1/46416c8ca5ad2489e278d9cc394055e7.jpg', '<p>Một thành viên tên Brooks trong nhóm những người bạn nảy ra ý tưởng về trò chơi có chủ đề là &quot;vụ bắt cóc bí ẩn&quot;. Người thắng cuộc của trò chơi sẽ giành được phần thưởng là chiếc xe hơi sang trọng. Không ngờ, chính Brooks lại trở thành nạn nhân của một vụ bắt cóc thật sự trong khi mọi người vẫn nghĩ đấy là một phần của trò chơi. Và thế là các nhân vật rơi vào tình thế nguy hiểm với hàng loạt những pha hành động gây cấn xen lẫn hài hước thông minh ...</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Sharon Horgan","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Kylie Bunbury","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Chelsea Peretti","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Camille Chen","avatar":""},{"name":"Zerrick Williams","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"R.F. Daley","avatar":""},{"name":"John Fran","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324397);
