INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-doc-tai', 'Nhà Độc Tài', 'Dear Dictator', 'https://phimimg.com/upload/vod/20231103-1/8bde1e23121dfb9c64e6cb631bdba8a2.jpg', 'https://phimimg.com/upload/vod/20231103-1/73d5c92bc48df7446e24dbc281f702ed.jpg', '<p>Tatiana cũng giống như bao teen dẩm khác, ngoại trừ một điều: Cô là bạn qua thư của nhà độc tài Anton Vincent. Sau khi chính biến xảy ra, Vincent bỏ trốn đến Mỹ và ở trong nhà của Tatiana. Đổi lại Vincent dạy Tatiana cách khơi mào cách mạng và lật đổ mấy con mát rượi ở trường.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Caine","avatar":""},{"name":"Odeya Rush","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Jason Biggs","avatar":""},{"name":"Adrian Voo","avatar":""},{"name":"Jackson Beard","avatar":""},{"name":"Fish Myrr","avatar":""},{"name":"Jordyn Cavros","avatar":""},{"name":"Hannah Joy Brown","avatar":""},{"name":"Yvette Parish","avatar":""},{"name":"Jacob Grodnik","avatar":""},{"name":"Jay Willick","avatar":""},{"name":"Rosemberg Salgado","avatar":""},{"name":"Dana Joyce Schiller","avatar":""},{"name":"John Michael Weatherly","avatar":""},{"name":"Natalie Sha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
