INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-toi-loi', 'Bí Mật Tội Lỗi', 'Kill Mobile', 'https://phimimg.com/upload/vod/20231103-1/2dec325879762d1cfa6cb83a5ff76e56.jpg', 'https://phimimg.com/upload/vod/20231103-1/1d26168bd870a620f2ad95cadda1d246.jpg', '<p>Kill Mobile (Bí Mật Tội Lỗi) là phiên bản remake của điện ảnh Trung Quốc từ tác phẩm gốc Perfect Strangers (Ý) hay Tiệc Trăng Máu (Việt Nam). Trong phim, bảy người bạn cùng nhau ăn tối và nghĩ ra trò chơi tiêu khiển thú vị. Trong đó, mọi người phải chia sẻ tất cả các cuộc gọi và tin nhắn với nhau. Câu chuyện dở khóc dở cười bắt đầu khi những tin nhắn, cuộc gọi, thông báo app liên tục đổ về suốt buổi tối đó.Những câu chuyện bi hài và ngay cả những bí mật thầm kín của cả thảy 7 người dần bị tiết lộ. Điều đó khiến những người bạn vốn thân quen bỗng dưng lại trở nên xa lạ.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tong Dawei","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Huo Si-Yan","avatar":""},{"name":"Qiao Shan","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Dai Lele","avatar":""},{"name":"Allen Ai Lun","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Raquel Xu","avatar":""},{"name":"Xinyu Han","avatar":""},{"name":"He Hongshan","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Di Xu","avatar":""},{"name":"Yang Le","avatar":""},{"name":"Ming Xi","avatar":""},{"name":"Li Ping","avatar":""},{"name":"Liu Jiayi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
