INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-toi-loi', 'Bí Mật Tội Lỗi', 'Kill Mobile', 'bí mật tội lỗi kill mobile tong dawei ma li huo si-yan qiao shan tian yu dai lele allen ai lun morning chang raquel xu xinyu han he hongshan clara lee di xu yang le ming xi li ping liu jiayi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-trung-quoc-dong-tan-nghieu', 'Siêu nhân Trung Quốc Đổng Tân Nghiêu', 'Chinese Superman', 'https://phimimg.com/upload/vod/20231111-1/62efd876493f77e71a48ece4bc2dc1cc.jpg', 'https://phimimg.com/upload/vod/20231111-1/c99def7508ef99a9d629f8b88b3e8340.jpg', '<p>Dong Xinyao, một người nổi tiếng mới nổi trên Internet với danh tiếng không giới hạn, được công chúng công nhận sau khi trừng phạt thành công một tổ chức cho vay trần trụi, tuy nhiên, khi chạm trán với một tên cướp, anh ta đã ngất xỉu và bị giám sát trên Internet và rơi vào tình trạng nguy kịch. vụ bê bối. Kết quả là anh mắc phải một khoản nợ khổng lồ, Dahai, người mơ ước trở thành đạo diễn và Feifei, người muốn trở thành một diễn viên, đã đứng dậy được nhưng vô tình họ lại vướng vào một vụ án giết người liên quan đến tranh chấp quyền thừa kế của gia đình. Trong quá trình quay phim tại một nhà kho bỏ hoang, họ vô tình dính vào một vụ án giết người, sát thủ người Nhật đã thay đổi danh tính và muốn giết em gái của chủ nhân để chủ nhân độc chiếm một khối tài sản khổng lồ. Ba người họ, Dong Xinyao và Dong Xinyao, những người bị đe dọa tính mạng, đã buộc phải dàn dựng một vụ &quot;mua kẻ giết người và bắn ai đó&quot;, sử dụng những bức ảnh dàn dựng, đoạn video giết người nhằm mục đích che giấu nó với công chúng. Không ngờ danh tính của họ bị phát hiện trong lần giao dịch cuối cùng, ông Chu hung hãn không thả họ ra, để ba người giết nhau. Tuy nhiên, Dong Xinyao đã kiên cường chống cự và bảo vệ mọi người, toàn bộ quá trình đã được camera ẩn ghi lại từ trước, ông Chu cuối cùng đã bị pháp luật trừng phạt, cuối cùng Dong Xinyao lại được mọi người công nhận.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Wen","avatar":""},{"name":"Sun Xiaojun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
