INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luan-hoi-chien', 'Luân Hồi Chiến', 'The Killing House', 'https://phimimg.com/upload/vod/20231111-1/43c52a3d923e9f0ec4a6f4cada761f98.jpg', 'https://phimimg.com/upload/vod/20231111-1/b728f27609191b8a6d77849a973198a0.jpg', '<p>3 người bị mắc kẹt trong một ngôi biệt thự kỳ bí, với kíp nổ cài vào tim đã bị kích hoạt, họ chỉ còn lại 1 giờ để tìm lối ra, tự cứu lấy mạng của mình. Cách duy nhất là phải tàn sát lẫn nhau và hồi sinh tìm cơ hội sống sót.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Picardy Jean-Pierre","avatar":""},{"name":"Chloe Mercedez","avatar":""},{"name":"Duojie Suonan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324397);
