INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-nu-nhi', 'Giang Hồ Nữ Nhi', 'Ash is Purest White', 'https://phimimg.com/upload/vod/20231111-1/a1623dada12bb6a9d740845d7af61941.jpg', 'https://phimimg.com/upload/vod/20231111-1/57b6dcfdf7cdada2dd9d062475025827.jpg', '<p>Phim xoay quanh chuyện tình của cô ca sĩ tên Xảo Xảo và A Bân – một gã giang hồ suốt ngày chỉ biết ăn chơi. Khi đại ca của A Bân bị sát hại, anh lên làm trùm băng đảng và trở thành mục tiêu tấn công của những kẻ khác. Trong một trận chiến, Xảo Xảo liều mình nã súng để cứu A Bân và bị cảnh sát bắt. Sau 5 năm tù, cô được tự do nhưng A Bân đã có bạn gái mới. Thế là cô quyết tâm tìm kiếm anh, trải qua một hành trình với nhiều điều dị thường và kỳ ảo.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Tao","avatar":""},{"name":"Liao Fan","avatar":""},{"name":"Diao Yi''nan","avatar":""},{"name":"Ding Jiali","avatar":""},{"name":"Dong Zijian","avatar":""},{"name":"Xu Zheng","avatar":""},{"name":"Zhang Yibai","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Feng Xiaogang","avatar":""},{"name":"Jiamei Feng","avatar":""},{"name":"Kang Kang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
