INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mamma-mia-yeu-lan-nua', 'Mamma Mia! Yêu Lần Nữa', 'Mamma Mia! Here We Go Again', 'https://phimimg.com/upload/vod/20231103-1/b5c6067b11131752915fcf949baf8e92.jpg', 'https://phimimg.com/upload/vod/20231103-1/505e936841afaded7ed3392f8beda8b7.jpg', '<p>Mamma Mia! Yêu Lần Nữa vẫn là những sự kiện kết nối câu chuyện đậm chất tình ca tại hòn đảo Kalokairi xinh đẹp và thơ mộng, khi ba người tình cũ của Donna cùng xuất hiện trước thềm đám cưới Sophie - con gái Donna và đều cho rằng mình là người cha thật sự của cô bé tóc vàng này. Phần hai sẽ khám phá mối tình nồng cháy trong quá khứ của Donna và ba chàng lãng tử hào hoa Sam, Bill, Harry với Lily James trong vai Donna, Jeremy Irvine trong vai Sam, Josh Dylan trong vai Bill và Hugh Skinner trong vai Harry thời trẻ. “Bộ sậu” diễn viên mới này sẽ đảm bảo cho phần “nghe” của Mamma Mia!: Yêu Lần Nữa được thỏa mãn khi hầu hết dàn diễn viên đều là những cái tên đã có kinh nghiệm trong lĩnh vực ca hát và sân khấu ...</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Christine Baranski","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Andy García","avatar":""},{"name":"Lily James","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Cher","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Jeremy Irvine","avatar":""},{"name":"Josh Dylan","avatar":""},{"name":"Hugh Skinner","avatar":""},{"name":"Alexa Davies","avatar":""},{"name":"Jessica Keenan Wynn","avatar":""},{"name":"Maria Vacratsis","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324397);
