INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thinh-cau-bi-an', 'Lời Thỉnh Cầu Bí Ẩn', 'A Simple Favor', 'https://phimimg.com/upload/vod/20231103-1/315d74eb6afa48178240b0eae1659ee8.jpg', 'https://phimimg.com/upload/vod/20231103-1/f7d19c23de7c325af9cb5631ba7100cf.jpg', '<p>Ba nhân vật có mối liên hệ đặc biệt cùng sống ở một thị trấn nhỏ. Stephanie – một blogger làm nghề nội trợ, phát hiện bạn mình là Emily mất tích một cách bí ẩn. Sau vài ngày, Emily được kết luận là đã chết. Trước cái chết đột ngột của người bạn giàu có, Stephanie quyết định tự mình điều tra và đã vô tình cuốn vào mối quan hệ bất chính với Sean – chồng của Emily.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Anna Kendrick","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Henry Golding","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Bashir Salahuddin","avatar":""},{"name":"Danielle Bourgon","avatar":""},{"name":"Kelly McCormack","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Ian Ho","avatar":""},{"name":"Joshua Satine","avatar":""},{"name":"Paul Jurewicz","avatar":""},{"name":"Roger Dunn","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Eric Johnson","avatar":""},{"name":"Jason Oliveira","avatar":""},{"name":"Patti Harr","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
