INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-trai-tu-than', 'Vượt Ngục Trại Tử Thần', 'Sobibor', 'https://phimimg.com/upload/vod/20231103-1/fb386bfc2f2f5e08297c5d1d154ecc1a.jpg', 'https://phimimg.com/upload/vod/20231103-1/891a2ea1e54d0cf91ee9334da0f07d3f.jpg', '<p>Vào năm 1943 trong trại tập trung “Sobibor” của bọn Đức quốc xã, nơi chứa hàng trăm tù nhân, trong đó có nhân vật chính của bộ phim là trung úy của quân đội xô viết Aleksandr Pechersky. Cùng với các tù nhân khác, trong mấy tuần anh đã vạch ra kế hoạch vượt ngục sau khi tiến hành cuộc nổi dậy thành công duy nhất trong lịch sử của các trại tập trung Đức Quốc xã, kết quả là hơn 300 người đã được cứu thoát.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Christophe Lambert","avatar":""},{"name":"Michalina Olszańska","avatar":""},{"name":"Felice Jankell","avatar":""},{"name":"Mariya Kozhevnikova","avatar":""},{"name":"Dainius Kazlauskas","avatar":""},{"name":"Philippe Reinhardt","avatar":""},{"name":"Maximilian Dirr","avatar":""},{"name":"Mindaugas Papinigis","avatar":""},{"name":"Wolfgang Cerny","avatar":""},{"name":"Ivan Zlobin","avatar":""},{"name":"Sergey Godin","avatar":""},{"name":"Gela Meskhi","avatar":""},{"name":"Dirk Martens","avatar":""},{"name":"Evgeni","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
