INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luis-va-nhom-ban-ngoai-hanh-tinh', 'Luis và Nhóm Bạn Ngoài Hành Tinh', 'Luis and the Aliens', 'https://phimimg.com/upload/vod/20231102-1/21296db21c2204c4be0ae7a71126891e.jpg', 'https://phimimg.com/upload/vod/20231102-1/18965bbb58075c1836f751d5d28e712d.jpg', '<p>Luis Và Nhóm Bạn Ngoài Hành Tinh là bộ phim hoạt hình cực kỳ hài hước và vui nhộn cho cả nhà vào Tết này. Chú nhóc tinh nghịch và 3 người bạn mới ngoài hành tinh sẽ khuấy đảo màn ảnh rộng đảm bảo sẽ gây tiếng cười tuyệt đỉnh cho người xem.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2018, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Callum Maloney","avatar":""},{"name":"Dermot Magennis","avatar":""},{"name":"Ian Coppinger","avatar":""},{"name":"Paul Tylak","avatar":""},{"name":"Lucy Carolan","avatar":""},{"name":"Eoin Daly","avatar":""},{"name":"Aileen Mythen","avatar":""},{"name":"Simon Toal","avatar":""},{"name":"Danna Davis","avatar":""},{"name":"Susie Power","avatar":""},{"name":"Eoin McCormick","avatar":""},{"name":"Oisin Murray","avatar":""},{"name":"Núria Blanco","avatar":""},{"name":"Roger Gregg","avatar":""},{"name":"Jill Srigley","avatar":""},{"name":"Dan Russell","avatar":""},{"name":"Mary Murray","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324397);
