INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-chuc-blackmark', 'Tổ Chức Blackmark', 'Blackmark', 'https://phimimg.com/upload/vod/20231102-1/a065653724d51c1314ae71a9acb92e40.jpg', 'https://phimimg.com/upload/vod/20231102-1/033bba2b4aa6c15f51d6d75111ff8640.jpg', '<p>Bộ phim Tổ chức Blackmark - Blackmark dựa trên một câu chuyện có thật xảy ra vào năm 1963, một tổ chức cực đoan đang cố gắng xâm nhập và điều khiển tên lửa Liên Xô để nhắm vào Hoa Kỳ. Arthur Blackmark - điệp viên quốc phòng Mỹ và Chỉ huy Liên Xô đã phải cố gắng ngăn chặn vụ nổ hạt nhân và bảo vệ hòa bình cho thế giới.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kaiwi Lyman","avatar":""},{"name":"Jeff Hatch","avatar":""},{"name":"Corey MacIntosh","avatar":""},{"name":"Timothy Oman","avatar":""},{"name":"John Henry Richardson","avatar":""},{"name":"Jon Briddell","avatar":""},{"name":"Lana Gautier","avatar":""},{"name":"Dave Parke","avatar":""},{"name":"Brad Potts","avatar":""},{"name":"Mike Firek","avatar":""},{"name":"Danny Hansen","avatar":""},{"name":"Keenan Johnston","avatar":""},{"name":"David Light","avatar":""},{"name":"Brenna Piller","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
