INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tuyet-chung-can-ke', 'Sự Tuyệt Chủng Cận Kề', 'Near Extinction Shangri-La', 'https://phimimg.com/upload/vod/20231102-1/c10b6dd017c9fef6b22cc8e387b26d07.jpg', 'https://phimimg.com/upload/vod/20231102-1/203016f21fde6267f6311831e25bba13.jpg', '<p>Một nhóm những người sống sót do Vargas lãnh đạo đang thực hiện nhiệm vụ tìm kiếm nơi trú ẩn an toàn được gọi là Shangri-La, nơi muôn loài bắt đầu khởi động lại nền văn minh. Nhưng nhiều mối nguy hiểm cản đường họ, bao gồm các thành viên của một giáo phái đột biến cuồng tín và một nhóm các sinh vật bí ẩn.</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Szmanda","avatar":""},{"name":"Sara Malakul Lane","avatar":""},{"name":"Ewan Chung","avatar":""},{"name":"Patrick Batiste","avatar":""},{"name":"Rocky Bonifield","avatar":""},{"name":"Josh Shibata","avatar":""},{"name":"Mykayla Sohn","avatar":""},{"name":"Mercy Malick","avatar":""},{"name":"Ken Narasaki","avatar":""},{"name":"Denver Marcus Low","avatar":""},{"name":"Pamela Chau","avatar":""},{"name":"Darin Cooper","avatar":""},{"name":"Alexandre Chen","avatar":""},{"name":"Evangeline Crittenden","avatar":""},{"name":"Aaron Groben","avatar":""},{"name":"Joe Souza","avatar":""},{"name":"Aswan Harr","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
