INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-bao-thu-2', 'Võ Sĩ Báo Thù 2', 'Kickboxer: Retaliation', 'https://phimimg.com/upload/vod/20231101-1/a86b5e5577c70e9db16fea9b01830ef2.jpg', 'https://phimimg.com/upload/vod/20231101-1/83c970a8ae3a73010b65f1f276616c2f.jpg', '<p>Tiếp nối phần trước Kickboxer: Vengeance, diễn viên người Bỉ trở lại với vai bậc thầy karate trong Kickboxer: Retaliation. Cả hai phần đều do biên kịch và nhà sản xuất đang nắm giữ hai đai đen Dimitri Logothesis (Sleepwalkers của Stephen King) thực hiện. Bộ phim sẽ được khởi quay tại Thái Lan vào tuần sau, bên cạnh đó là những ngôi sao như Mike Tyson, Ronaldinho và Hafbor Julius Bjornsson. Kickboxer: Retaliation sẽ do hãng Our House Film chịu trách nhiệm sản xuất.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alain Moussi","avatar":""},{"name":"Christophe Lambert","avatar":""},{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Sara Malakul Lane","avatar":""},{"name":"Hafþór Júlíus Björnsson","avatar":""},{"name":"Sam Medina","avatar":""},{"name":"Steven Swadling","avatar":""},{"name":"Miles Strommen","avatar":""},{"name":"Jessica Jann","avatar":""},{"name":"Maxime Savaria","avatar":""},{"name":"Wanderlei Silva","avatar":""},{"name":"Frankie Edgar","avatar":""},{"name":"Renzo Gracie","avatar":""},{"name":"Renato Sobral","avatar":""},{"name":"Sunan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
