INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-thu-winchester', 'Dinh Thự Winchester', 'Winchester', 'https://phimimg.com/upload/vod/20231101-1/6ee58576238621dbfda048b5d0cff256.jpg', 'https://phimimg.com/upload/vod/20231101-1/49cdbf5b35416a768189a0b827719104.jpg', '<p>Dinh thự Winchester (tên gốc tiếng Anh: Winchester) là một bộ phim điện ảnh kinh dị siêu nhiên năm 2018 do Michael và Peter Spierig đạo diễn, và với phần kịch bản được chấp bút bởi chính bộ đôi Spierig cùng với Tom Vaughan. Bộ phim có sự tham gia của nữ diễn viên Helen Mirren trong vai nữ thừa kế Sarah Winchester, cùng với Jason Clarke và Sarah Snook, với nội dung xoay quanh nhân vật Winchester khi bà bị ám bởi những linh hồn trong biệt thự San Jose năm 1906.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jason Clarke","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Sarah Snook","avatar":""},{"name":"Finn Scicluna-O''Prey","avatar":""},{"name":"Emm Wiseman","avatar":""},{"name":"Alana Fagan","avatar":""},{"name":"Rebecca Makar","avatar":""},{"name":"Tyler Coppin","avatar":""},{"name":"Michael Carman","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Alice Chaston","avatar":""},{"name":"Eamon Farren","avatar":""},{"name":"Laura Brent","avatar":""},{"name":"Adam Bowes","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Phoenix Suhrou-Diamond","avatar":""},{"name":"Jayden Ir","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
