INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dilan-1990', 'Dilan 1990', 'Dilan 1990', 'https://phimimg.com/upload/vod/20231109-1/4a4e36e20535811547049fb0a62ea0c5.jpg', 'https://phimimg.com/upload/vod/20231109-1/a74ba4dc49d11215cf26132a0d5007a1.jpg', '<p>Mila (Vanesha Prescilla) đã gặp Dilan (Iqbaal Ramadhan) tại một trường trung học ở Bandung vào năm 1990, khi Mila chuyển từ Jakarta đến Bandung. Một giới thiệu bất thường mang đến sự hồi hộp để biết sự độc đáo của Dilan, thông minh, tốt bụng, lãng mạn. Cách tiếp cận Dilan Mila không giống như những người bạn nam khác, thậm chí Beni (Brandon Salim), bạn trai của Mila ở Jakarta. Hành trình về mối quan hệ của họ không phải lúc nào cũng trơn tru. Beni, Anhar (Giulio Perangkan), Kang Adi (Tái cấu trúc Hadi) Màu hành trình. Dilan khiến Mila tin rằng cô có thể đến đích một cách an toàn.</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Iqbaal Ramadhan","avatar":""},{"name":"Vanesha Prescilla","avatar":""},{"name":"Sissy Prescillia","avatar":""},{"name":"Debo Andrios","avatar":""},{"name":"Giulio Parengkuan","avatar":""},{"name":"Omara Esteghal","avatar":""},{"name":"Yoriko Angeline","avatar":""},{"name":"Zulfa Maharani","avatar":""},{"name":"Brandon Salim","avatar":""},{"name":"Ira Wibowo","avatar":""},{"name":"Happy Salma","avatar":""},{"name":"Muhammad Farhan","avatar":""},{"name":"Refal Hady","avatar":""},{"name":"Adhisty Zara","avatar":""},{"name":"Moira Tabina Zayn","avatar":""},{"name":"Gusti Rayhan","avatar":""},{"name":"Tik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324397);
