INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-noi-day-cua-robin-hood', 'Sự Nổi Dậy Của Robin Hood', 'Robin Hood: The Rebellion', 'https://phimimg.com/upload/vod/20231101-1/987c3719172078d94e68a0e8dc60cc6e.jpg', 'https://phimimg.com/upload/vod/20231101-1/25e9aab3934ef02fb04bf05bce549f92.jpg', '<p>Trở về sau cuộc Thập Tự Chinh, Robin Hood và người bạn thân Will Scarlett nhận ra quê hương của mình bị cai trị bởi tên quận trưởng bạo tàn. Dưới ách thống trị của hắn, người dân xứ Nottingham phải chọn một trong hai. Quy thuận tên Quận trưởng hoặc sống ngoài vòng pháp luật. Robin, cùng tình yêu của đời mình, tiểu thư Marian tập hợp một băng cướp cùng chung sức chống lại sự bất công.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ben Freeman","avatar":""},{"name":"Brian Blessed","avatar":""},{"name":"Marie Everett","avatar":""},{"name":"Jamie Kenna","avatar":""},{"name":"James G. Nunn","avatar":""},{"name":"James Oliver Wheatley","avatar":""},{"name":"James Groom","avatar":""},{"name":"Charlie Hiett","avatar":""},{"name":"Martyn Ford","avatar":""},{"name":"Kristian Nairn","avatar":""},{"name":"Gareth David-Lloyd","avatar":""},{"name":"Phill Martin","avatar":""},{"name":"Jamie Bacon","avatar":""},{"name":"Tom Ashley","avatar":""},{"name":"Ryan Winsley","avatar":""},{"name":"John Jones","avatar":""},{"name":"James Rockey","avatar":""},{"name":"Mari","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324397);
