INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-lanh', 'Chiến Tranh Lạnh', 'Cold War', 'https://phimimg.com/upload/vod/20231101-1/7f322506262c29b60d234dc20ad90e07.jpg', 'https://phimimg.com/upload/vod/20231101-1/3d3379c4fd09e571384c830f92102ad6.jpg', '<p>Bộ phim hợp tác Ba Lan - Pháp - Anh này do đạo diễn Ba Lan sống ở Anh Pawel Pawlikowski đạo diễn hy vọng đoạt Cành cọ Vàng 2018. Cold War kể một câu chuyện tình tại châu Âu vào thập niên 1950 giữa hai người có xuất thân khác nhau. Đây cũng là phim mới nhất của Pawlikowski sau bộ phim Ida đoạt giải Bafta phim nước ngoài hay nhất năm 2015. Nội dung phim Cold War (Chiến Tranh Lạnh) lấy bối cảnh Ba Lan sau Thế chiến thứ hai, kể về chuyện tình của Zula - một ca sĩ trẻ trong đoàn hát của chính phủ - và Wiktor - một đạo diễn âm nhạc. Mọi chuyện trở nên phức tạp khi họ có chuyến lưu diễn ở Đông Berlin (Đông Đức) và có cơ hội đào ngũ.</p>', 'Full', 1, 'single', 'completed', 22, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Joanna Kulig","avatar":""},{"name":"Tomasz Kot","avatar":""},{"name":"Borys Szyc","avatar":""},{"name":"Agata Kulesza","avatar":""},{"name":"Cédric Kahn","avatar":""},{"name":"Jeanne Balibar","avatar":""},{"name":"Adam Woronowicz","avatar":""},{"name":"Adam Ferency","avatar":""},{"name":"Adam Szyszkowski","avatar":""},{"name":"Dražen Šivak","avatar":""},{"name":"Slavko Sobin","avatar":""},{"name":"Aloïse Sauvage","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324397);
