INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-lang-tien-su', 'Ngôi Làng Tiền Sử', 'Early Man', 'https://phimimg.com/upload/vod/20231101-1/2d300712b403e4c9a7534ebc7f8a91bf.jpg', 'https://phimimg.com/upload/vod/20231101-1/31cafee7b0efd8b9b48db3962cb38529.jpg', '<p>&quot;Khi đồ đá đấu với đồ đồng&quot; Ngày xửa ngày xưa, khi mà người tiền sử và những chú voi ma-mút còn sinh sống trên Trái Đất... Dug và đồng đội &quot;lợn lòi&quot; của mình là Hognob cùng thống nhất bộ lạc và bảo vệ quê hương. Kẻ thù xảo quyệt của họ là Chúa tể Nooth cùng thành phố Đồ Đồng. &nbsp;Bộ phim hoạt hình với kinh phí $50.000,000 này do studio Aardman sản xuất - studio vốn đã quen thuộc với những bộ phim cực kỳ dễ thương như Phi Đội Gà Bay, Wallace &amp; Gromit, Shaun the Sheep... Đặc biệt còn có sự góp mặt lồng tiếng của các diễn viên nổi tiếng Tom Hiddleston, Maisie Williams, Eddie Redmayne.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2018, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Eddie Redmayne","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Maisie Williams","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Rob Brydon","avatar":""},{"name":"Kayvan Novak","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Selina Griffiths","avatar":""},{"name":"Johnny Vegas","avatar":""},{"name":"Mark Williams","avatar":""},{"name":"Gina Yashere","avatar":""},{"name":"Richard Webber","avatar":""},{"name":"Simon Greenall","avatar":""},{"name":"Nick Park","avatar":""},{"name":"Luke Walton","avatar":""},{"name":"Antony Bayman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":