INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-dang-nho', 'Mùa Hè Đáng Nhớ', 'Summer ''03', 'https://phimimg.com/upload/vod/20231101-1/53081c3ca4bd466e4e185c25fcba4dcb.jpg', 'https://phimimg.com/upload/vod/20231101-1/e10fe5523ee0de52355ebac87bf6fd20.jpg', '<p>Khi Jamie (Joey King) bước vào mùa hè quan trọng của tuổi thanh xuân trong quá khứ xa xăm của năm 2003 đầy nắng, cô ấy là một thiếu niên vui vẻ với những tưởng tượng về tình yêu và tình dục, điều cô vẫn chưa được trải nghiệm. Cái chết của bà cô, Dotty (June Squibb), khiến những người đam mê chuyện ấy và những câu chuyện phiếm nữ sinh vào cuối tuần tạm dừng, nhưng thật bất ngờ đối với Jamie, Dotty lại giúp cô có một cuộc nổi loạn ở tuổi vị thành niên.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey King","avatar":""},{"name":"Jack Kilmer","avatar":""},{"name":"Andrea Savage","avatar":""},{"name":"Paul Scheer","avatar":""},{"name":"Erin Darke","avatar":""},{"name":"Stephen Ruffin","avatar":""},{"name":"Kelly Lamor Wilson","avatar":""},{"name":"Logan Medina","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Elise DuQuette","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
