INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-cu-toi-la-diep-vien', 'Bạn Trai Cũ Tôi Là Điệp Viên', 'The Spy Who Dumped Me', 'https://phimimg.com/upload/vod/20231029-1/ce67b87b1dc20789195cd35bcef73e8f.jpg', 'https://phimimg.com/upload/vod/20231029-1/b375f8ead47e92d41a78faa63ca1b907.jpg', '<p>Bộ phim hành động - hài của hãng Lionsgate hứa hẹn sẽ mang đến một màn trình diễn đầy kịch tính và cũng không kém phần &quot;đau cả ruột&quot; cho khán giả Việt trong tháng 8. Chuyện phim xoay quanh câu chuyện của cô nàng Audrey. Theo đó, khi mà nỗi đau bị thất tình chưa kịp nguôi ngoai, Audrey lại phải đối mặt với muôn vàn nguy hiểm và tìm cách trốn khỏi châu Âu. Nguyên nhân cũng chính vì anh bạn trai cũ là một điệp viên và khiến cô bị vạ lây. Liệu Audrey sẽ làm gì để có thể bảo toàn mạng sống của mình...</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Mila Kunis","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Sam Heughan","avatar":""},{"name":"Lolly Adefope","avatar":""},{"name":"Dustin Demri-Burns","avatar":""},{"name":"Hasan Minhaj","avatar":""},{"name":"Mirjam Novak","avatar":""},{"name":"Kev Adams","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Ivanna Sakhno","avatar":""},{"name":"Jane Curtin","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Fred Melamed","avatar":""},{"name":"James Fleet","avatar":""},{"name":"Carolyn Pickles","avatar":""},{"name":"Tom Stourton","avatar":""},{"name":"Ruby Kam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
