INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-trai-cu-toi-la-diep-vien', 'Bạn Trai Cũ Tôi Là Điệp Viên', 'The Spy Who Dumped Me', 'bạn trai cũ tôi là điệp viên the spy who dumped me mila kunis kate mckinnon justin theroux sam heughan lolly adefope dustin demri-burns hasan minhaj mirjam novak kev adams gillian anderson ivanna sakhno jane curtin paul reiser fred melamed james fleet carolyn pickles tom stourton ruby kam ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-ngay-loi-hua-no-hoa', 'Chờ Ngày Lời Hứa Nở Hoa', 'Maquia: When the Promised Flower Blooms', 'https://phimimg.com/upload/vod/20231029-1/1b887e9a41d21945f23ec1387f570cba.jpg', 'https://phimimg.com/upload/vod/20231029-1/6f324baf607751e30440cabc5d5c5db6.jpg', '<p>Có một chủng người nọ tên là Iorph, họ sống tách biệt với thế giới con người, dành cả đời mình dệt một loại vải gọi là Hibiol. Trải qua hàng trăm năm, họ vẫn giữ được nét trẻ trung xinh đẹp như tuổi đôi mươi, cũng chính vì vậy mà người ta gọi họ là gia tộc bất tử. &nbsp;Maquia, một cô bé người Iorph mồ côi sống cùng bạn bè ở một ốc đảo nọ, thế nhưng cô bé vẫn cảm thấy rất cô đơn. Không lâu sau, cuộc sống yên bình của người Iorph bỗng chốc tan vỡ bởi quân xâm lượt Mezarte, chúng đến để tìm kiếm căn nguyên sự bất tử của người Iorph. &nbsp;May mắn trốn thoát được nhưng lại mất tất cả, giờ chỉ còn hai bàn tay trắng, Maquia lang thang trong một cánh rừng nọ, cô bé bắt gặp một đứa trẻ mồ côi giống như mình. Cùng với những người bạn mới, Maquia đã nuôi dạy đứa trẻ, Ariel, câu chuyện cũng từ đây mà bắt đầu… một câu chuyện về 2 con người cô độc tìm được nhau giữa cơn loạn lạc khốn cùng…</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Manaka Iwami","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Yuuki Sakurai","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Rina Satou","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Misaki Kuno","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Jo Bin","avatar":""},{"name":"Yuki Kurimoto","avatar":""},{"name":"Junnosuke Shishido","avatar":""},{"name":"Taichi Iwakawa","avatar":""},{"name":"Hiroshi Iwasaki","avatar":""},{"name":"Keisuke K","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
