INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-16', 'Cấp 16', 'Level 16', 'https://phimimg.com/upload/vod/20231029-1/b3d2a95581e24b346576665c21e40b47.jpg', 'https://phimimg.com/upload/vod/20231029-1/b6c0e4466036830f5930d64987a6d927.jpg', '<p>Vivien mười sáu tuổi bị mắc kẹt trong Học viện Vestalis, một trường nội trú giống như nhà tù, tự giữ mình và không quan hệ với ai. Cho đến khi cô được đoàn tụ với Sophia - người bạn cũ đã phản bội cô. Các cô gái cùng nhau bắt tay vào một cuộc tìm kiếm nguy hiểm để khám phá ra sự thật kinh hoàng đằng sau sự giam cầm của họ. Để chạy thoát vì cuộc sống của họ, các cô gái phải tìm cách tự cứu lấy mình.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Katie Douglas","avatar":""},{"name":"Celina Martin","avatar":""},{"name":"Peter Outerbridge","avatar":""},{"name":"Sara Canning","avatar":""},{"name":"Alexis Whelan","avatar":""},{"name":"Amalia Williamson","avatar":""},{"name":"Josette Halpert","avatar":""},{"name":"Kate Vickery","avatar":""},{"name":"Kiana Madeira","avatar":""},{"name":"Alex Steele","avatar":""},{"name":"Sydney Ozerov-Meyer","avatar":""},{"name":"Joelle Farrow","avatar":""},{"name":"Sarah DaSilva","avatar":""},{"name":"Lori Phun","avatar":""},{"name":"Vladimir Tsyglian","avatar":""},{"name":"Val Ovtcharov","avatar":""},{"name":"Jam","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
