INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-khach-bi-an', 'Hành Khách Bí Ẩn', 'The Commuter', 'https://phimimg.com/upload/vod/20231029-1/cdbbd3e03384fbc2ad03dfdc3176274f.jpg', 'https://phimimg.com/upload/vod/20231029-1/97b233debee36bbaf62e5ea7ff481ccb.jpg', '<p>Nhân viên bán bảo hiểm Michael MacCauley đang trên chuyến tàu về nhà thì ông bỗng dưng bị dính líu vào một âm mưu nham hiểm, có thể đe dọa tính mạng của chính ông cũng như toàn bộ hành khách trên tàu. Và Vera Farmiga vào vai người phụ nữ bí ẩn đã kéo Michael vào rắc rối đầy hiểm họa: nếu anh có thể tìm ra một hành khách vốn không thuộc về chuyến tàu, phần thưởng mà anh nhận được sẽ là một khoản tiền hậu hĩnh...</p>', 'Full', 1, 'single', 'completed', 25, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Killian Scott","avatar":""},{"name":"Shazad Latif","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Clara Lago","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"Florence Pugh","avatar":""},{"name":"Dean-Charles Chapman","avatar":""},{"name":"Ella-Rae Smith","avatar":""},{"name":"Nila Aalia","avatar":""},{"name":"Colin McFarlane","avatar":""},{"name":"Kobna Holdbrook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324397);
