INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-nan-bat-ngo', 'Tai Nạn Bất Ngờ', 'Overboard', 'https://phimimg.com/upload/vod/20231030-1/0b03fe7754f90c72cf9e0a1b29da6a9d.jpg', 'https://phimimg.com/upload/vod/20231030-1/5cc0c381afe4f2c5c2ee899a1b392bd7.jpg', '<p>Một chủ du thuyền giàu có, hư hỏng bị ném xuống biển và trở thành mục tiêu trả thù của người nhân viên bị ngược đãi của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Faris","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Mel Rodriguez","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Hannah Nordberg","avatar":""},{"name":"Alyvia Alyn Lind","avatar":""},{"name":"Payton Lepinski","avatar":""},{"name":"Fernando Luján","avatar":""},{"name":"Cecilia Suárez","avatar":""},{"name":"Mariana Treviño","avatar":""},{"name":"Jesús Ochoa","avatar":""},{"name":"Omar Chaparro","avatar":""},{"name":"Adrián Uribe","avatar":""},{"name":"Edgar Vivar","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
