INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-scotland', 'Nữ Hoàng Scotland', 'Mary Queen of Scots', 'https://phimimg.com/upload/vod/20231030-1/9e3eb4d7ef273b561e19f8eae417c24b.jpg', 'https://phimimg.com/upload/vod/20231030-1/758dbbe5d9714af9f10e226f6ebaa61d.jpg', '<p>là bộ phim dã sử xoay quanh thời kỳ nội chiến tại Anh Quốc vào thế kỷ 16. Khi đó, nữ hoàng Mary của Scotland gặp nhiều biến động tại quê hương và phải cầu cứu sự giúp đỡ từ cô của mình - nữ hoàng Elizabeth nước Anh. Tuy nhiên, chính Elizabeth lại coi Mary là mối đe dọa với ngai vàng của mình, và lập tức chộp lấy thời cơ để tuyên chiến với Mary ngay khi có thể.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Saoirse Ronan","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Jack Lowden","avatar":""},{"name":"Joe Alwyn","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Martin Compston","avatar":""},{"name":"Ismael Cruz Córdova","avatar":""},{"name":"Brendan Coyle","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"James McArdle","avatar":""},{"name":"Richard Cant","avatar":""},{"name":"Guy Rhys","avatar":""},{"name":"Thom Petty","avatar":""},{"name":"Izuka Hoyle","avatar":""},{"name":"John Ramm","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Mar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324397);
