INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-tu-than', 'Cỗ Máy Tử Thần', 'Mortal Engines', 'https://phimimg.com/upload/vod/20231029-1/3c67a8858e521148d1555c2d31da8cd6.jpg', 'https://phimimg.com/upload/vod/20231029-1/b9aae9b1afaf12a7d604785710bcc4c3.jpg', '<p>Cỗ Máy Tử Thần lấy bối cảnh thế giới hậu tận thế khi các thành phố bắt đầu tàn lụi, con người phải tập thích nghi để tồn tại trong hoàn cảnh các nguồn tài nguyên đã cạn kiệt. Tại Traction City, anh chàng Tom Natsworthy gặp gỡ một cô gái ngoại lai bí ẩn tên Hester Shaw. Hai nhân vật với hai nét tính cách hoàn toàn đối lập vô tình bị đẩy vào cuộc hành trình đương đầu với các thế lực nguy hiểm để giành lấy quyền lực và tiếp tục sự sống.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'New Zealand', 0, '[{"name":"Hera Hilmar","avatar":""},{"name":"Robert Sheehan","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Jihae","avatar":""},{"name":"Ronan Raftery","avatar":""},{"name":"Leila George","avatar":""},{"name":"Patrick Malahide","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Mark Mitchinson","avatar":""},{"name":"Regé-Jean Page","avatar":""},{"name":"Menik Gooneratne","avatar":""},{"name":"Frankie Adams","avatar":""},{"name":"Leifur Sigurdarson","avatar":""},{"name":"Kahn West","avatar":""},{"name":"Andrew Lees","avatar":""},{"name":"Sophie Cox","avatar":""},{"name":"Kee Chan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
