INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-trong-luoi-nhen-ao', 'Cô Gái Trong Lưới Nhện Ảo', 'The Girl in the Spider''s Web', 'https://phimimg.com/upload/vod/20231030-1/31f90226755f7b2b4a26ea457422fa65.jpg', 'https://phimimg.com/upload/vod/20231030-1/a286d9db5ae2b0efe005b68f82a485e6.jpg', '<p>Được chuyển thể từ loạt tiểu thuyết trinh thám bán chạy nhất của Thuỵ Điển, The Girl in the Spider’s Web là phần hậu truyện của The Girl with the Dragon Tattoo (2011). &nbsp;Trong phần phim này, nữ hacker có hình xăm rồng Lisbeth Salander (Claire Foy) và nhà báo Mikael Blomkvist (Beau Gadsdon) sẽ trở lại với một phi vụ mới gay go, khó khăn và phức tạp gấp nhiều lần. Cụ thể, Lisbeth Salander được chọn tham gia thực hiện một nhiệm vụ mới, có liên quan đến dự án tuyệt mật quy tụ những bộ óc hàng đầu thế giới. Trong khi đó, nhà báo Mikael Blomkvist vốn đang vật vã ở toà soạn giữa cơn bão khủng hoảng tài chính, cũng bị kéo vào vụ tấn công tin tặc động trời nhằm vào nhà khoa học đầu ngành trong lĩnh vực trí tuệ nhân tạo. Hai người bạn lâu ngày không liên lạc sẽ được kết nối trong một phi vụ đặc biệt.</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Claire Foy","avatar":""},{"name":"Sverrir Gudnason","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Sylvia Hoeks","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Christopher Convery","avatar":""},{"name":"Claes Bang","avatar":""},{"name":"Synnøve Macody Lund","avatar":""},{"name":"Cameron Britton","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Andreja Pejić","avatar":""},{"name":"Mikael Persbrandt","avatar":""},{"name":"Beau Gadsdon","avatar":""},{"name":"Carlotta von Falkenhayn","avatar":""},{"name":"Thomas Wingrich","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
