INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-trong-luoi-nhen-ao', 'Cô Gái Trong Lưới Nhện Ảo', 'The Girl in the Spider''s Web', 'cô gái trong lưới nhện ảo the girl in the spider''s web claire foy sverrir gudnason lakeith stanfield sylvia hoeks stephen merchant christopher convery claes bang synnøve macody lund cameron britton vicky krieps andreja pejić mikael persbrandt beau gadsdon carlotta von falkenhayn thomas wingrich ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-dat-khong-lo-ngay-bang-gia-kinh-hoang', 'Sâu Đất Khổng Lồ: Ngày Băng Giá Kinh Hoàng', 'Tremors: A Cold Day in Hell', 'https://phimimg.com/upload/vod/20231030-1/356903e989678a17d114f541b0ac74b2.jpg', 'https://phimimg.com/upload/vod/20231030-1/25f41f3bdf0bddf0c2e63e793af8a77b.jpg', '<p>Burt Gummer và con trai Travis Welker nhận ra mình đang ở trong Graboids và Ass-Blasters khi họ đến Canada để điều tra một loạt vụ tấn công chết người của loài sâu khổng lồ. Đến một cơ sở nghiên cứu từ xa ở vùng lãnh nguyên Bắc Cực, Burt bắt đầu nghi ngờ rằng Graboid đang bí mật được trang bị vũ khí, nhưng trước khi có thể chứng minh lý thuyết của mình, anh đã bị nọc độc Graboid gạt ra ngoài. Chỉ còn 48 giờ để sống, hy vọng duy nhất là tạo ra thuốc giải độc từ nọc độc tươi - nhưng để làm được điều đó, ai đó sẽ phải tìm ra cách vắt sữa Graboid!</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Gross","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Tanya van Graan","avatar":""},{"name":"Stephanie Schildknecht","avatar":""},{"name":"Jamie-Lee Money","avatar":""},{"name":"Jay Anstey","avatar":""},{"name":"Jenna Upton","avatar":""},{"name":"Christie Peruso","avatar":""},{"name":"Greg Kriek","avatar":""},{"name":"Alistair Moulton Black","avatar":""},{"name":"Kiroshan Naidoo","avatar":""},{"name":"Paul du Toit","avatar":""},{"name":"Adrienne Pearce","avatar":""},{"name":"Francesco Nassimbeni","avatar":""},{"name":"Rob van Vuuren","avatar":""},{"name":"Kee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
