INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-ly-cloverfield', 'Nghịch Lý Cloverfield', 'The Cloverfield Paradox', 'https://phimimg.com/upload/vod/20231026-1/5aa6cd231450e8aaea0b16b0fed253f9.jpg', 'https://phimimg.com/upload/vod/20231026-1/3609f34254f582131f10b2e5e3019c09.jpg', '<p>Bước vào năm 2028, Trái đất đứng trước một cuộc khủng hoảng năng lượng nghiêm trọng. Để giải nguy, chính phủ các nước đã quyết định tập hợp các phi hành gia giỏi nhất của mình vào tàu không gian Shepard, nhằm thực hiện một thử nghiệm tại trạm không gian Cloverfield. &nbsp;Bằng việc khởi động chiếc máy gia tốc hạt trên tàu, Trái đất sẽ được cung cấp một nguồn năng lượng không bao giờ cạn. Song, một số nhà nghiên cứu theo thuyết âm mưu lại cho rằng, hành động liều lĩnh này có thể tạo ra một “dòng nghịch lý” (paradox), mở cánh cổng kêu gọi các thực thể nguy hiểm từ chiều không gian khác tấn công nhân loại.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Aksel Hennie","avatar":""},{"name":"Roger Davies","avatar":""},{"name":"Clover Nee","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Greg Grunberg","avatar":""},{"name":"Jordan Rivera","avatar":""},{"name":"Suzanne Cryer","avatar":""},{"name":"Nathan Oliver","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849