INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-gan-the', 'Trò Gắn Thẻ', 'Tag', 'https://phimimg.com/upload/vod/20231026-1/b2c86b440ed84ed590e90de4f2672741.jpg', 'https://phimimg.com/upload/vod/20231026-1/9e9abc4b268d3fc189399fc769007195.jpg', '<p>Một nhóm nhỏ các cậu bạn cùng lớp tổ chức một trò chơi phức tạp, thường niên suốt từ năm chín tuổi đến khi trưởng thành, yêu cầu họ phải đi khắp đất nước.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Helms","avatar":""},{"name":"Jon Hamm","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Hannibal Buress","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Rashida Jones","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Maxwell Ross","avatar":""},{"name":"Brayden Benson","avatar":""},{"name":"Jaren Lewison","avatar":""},{"name":"Braxton Bjerken","avatar":""},{"name":"Kevin Tyler Moody","avatar":""},{"name":"Tyler Crumley","avatar":""},{"name":"Elijah Marcano","avatar":""},{"name":"Braxton Alexander","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324397);
