INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-cong-ly', 'Tìm Lại Công Lý', 'The Hate U Give', 'https://phimimg.com/upload/vod/20231026-1/e04eb15a087a9a9f1f18118039ce70a0.jpg', 'https://phimimg.com/upload/vod/20231026-1/19c7eb8aab8306da5e65755de0e13d07.jpg', '<p>The Hate U Give nói về Starr, một nhà vận động quyền con người từ khi cô chứng kiến cảnh sát bắn chết người bạn không có vũ khí của mình. Bộ phim dựa trên cuốn truyện lấy cảm hứng từ phong trào “Black Lives Matter” bảo vệ người da đen.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amandla Stenberg","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"K.J. Apa","avatar":""},{"name":"Common","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Algee Smith","avatar":""},{"name":"Lamar Johnson","avatar":""},{"name":"Issa Rae","avatar":""},{"name":"Sabrina Carpenter","avatar":""},{"name":"TJ Wright","avatar":""},{"name":"Dominique Fishback","avatar":""},{"name":"Megan Lawless","avatar":""},{"name":"Tony Vaughn","avatar":""},{"name":"Karan Kendrick","avatar":""},{"name":"Susan Santiago","avatar":""},{"name":"Rayven Symone Ferrell","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
