INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robin-hood-sieu-trom-lung-danh', 'Robin Hood: Siêu Trộm Lừng Danh', 'Robin Hood', 'https://phimimg.com/upload/vod/20231026-1/f8148975213ffbd6867313c55032c50e.jpg', 'https://phimimg.com/upload/vod/20231026-1/46cc52b0b874305e821bbcb3a6d6b0b9.jpg', '<p>Lãnh chúa Robin xứ Loxley (Taron Egerton), chàng chiến binh mạnh mẽ cùng chỉ huy người Moor khởi đầu cuộc nổi dậy táo bạo chống lại Vương triều Anh đã thối nát lấy danh Thập tự chinh bóc lột dân chúng. Một cuộc phiêu lưu hành động ly kỳ mở ra những chiến trường khốc liệt, những trận chiến đấu hùng tráng và một mối tình vượt thời gian. Do Robin Hood là hình ảnh có thể tự do khai thác nên bất cứ hãng phim nào cũng có thể đưa nhân vật thảo khấu rừng xanh này lên màn ảnh. Năm nay, Lionsgate là cái tên tiếp theo thử sức với nhiệm vụ đó khi chọn Taron Egerton - ngôi sao của loạt phim điệp viên Kingsman - cho vai chính Robin Hood ...</p>', 'Full', 1, 'single', 'completed', 10, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Eve Hewson","avatar":""},{"name":"Jamie Dornan","avatar":""},{"name":"Tim Minchin","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Ian Peck","avatar":""},{"name":"Cornelius Booth","avatar":""},{"name":"Kane Headley-Cummings","avatar":""},{"name":"Scot Greenan","avatar":""},{"name":"Lara Rossi","avatar":""},{"name":"Kevin Griffiths","avatar":""},{"name":"Catriona Temple","avatar":""},{"name":"Björn Bengtsson","avatar":""},{"name":"Matt Devere","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
