INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-quy', 'Thành Phố Quỷ', 'Constantine: City of Demons - The Movie', 'https://phimimg.com/upload/vod/20231026-1/9864d7f2d6a8db2435be1ef6342fe33b.jpg', 'https://phimimg.com/upload/vod/20231026-1/86be3c1e54347dc9330e1a204962ba4e.jpg', '<p>City of Demons kể về Constantine hội ngộ với người bạn thân lâu năm không gặp của mình là Chas. Chas cần Constantine giúp vì con gái của anh, Trish, bị rơi vào một cơn hôn mê bất thường và mãi tới giờ vẫn chưa tỉnh dậy. Nghi ngờ là việc này có bàn tay của thế lực hắc ám nhúng vào, Chas quyết định tìm tới người chuyên về nghệ thuật hắc ám giỏi nhất mà anh biết, đó chính là Constantine. Lẽ dĩ nhiên, John đồng ý. Nhưng anh không biết là những con quỷ mà anh sẽ đối mặt không chỉ tới từ bên ngoài, mà còn tới từ bên trong bản thân anh.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Ryan","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Laura Bailey","avatar":""},{"name":"Rachel Kimsey","avatar":""},{"name":"Jim Meskimen","avatar":""},{"name":"Emily O''Brien","avatar":""},{"name":"Damian O''Hare","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Rick D. Wasserman","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324397);
