INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bo-cap-quyen-sach-linh-hon', 'Vua Bọ Cạp: Quyển Sách Linh Hồn', 'The Scorpion King: Book of Souls', 'https://phimimg.com/upload/vod/20231026-1/e7b8c792eb75042ac74db93eb2c24542.jpg', 'https://phimimg.com/upload/vod/20231026-1/2ceb35cafacceb73e0d31328d8985ea0.jpg', '<p>Ở Ai Cập cổ đại, lãnh chúa độc ác, Nebserek (Peter Mensah), phát hiện ra một thanh kiếm bị nguyền rủa khiến người sử dụng nó mạnh hơn với mọi linh hồn mà nó tấn công. Quyết tâm ngăn chặn sức mạnh của mình tăng lên, Vua Bọ Cạp (Zach McGowan) gia nhập lực lượng với Tala (Pearl Doesi), Công chúa Nubian; Amina, một người phụ nữ bí ẩn với một bí mật kỳ diệu và bi thảm; và người bảo vệ golem của cô để tìm ra một thứ có thể đánh bại Nebserek: Quyển sách linh hồn…</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zach McGowan","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Pearl Thusi","avatar":""},{"name":"Mayling Ng","avatar":""},{"name":"Katy Louise Saunders","avatar":""},{"name":"Inge Beckmann","avatar":""},{"name":"Stephanie Schildknecht","avatar":""},{"name":"Howard Charles","avatar":""},{"name":"Rizelle Januk","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Peter Jessop","avatar":""},{"name":"Lesala Mampa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
