INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-kinh-hoang-84', 'Mùa Hè Kinh Hoàng ''84', 'Summer of 84', 'https://phimimg.com/upload/vod/20231026-1/7d6f749f721ad01f8a77b81166ee673e.jpg', 'https://phimimg.com/upload/vod/20231026-1/8fc8220ef7dc829a544133b09b782376.jpg', '<p>Sau khi nghi ngờ người hàng xóm cảnh sát của họ là kẻ giết người hàng loạt, một nhóm bạn tuổi teen dành cả mùa hè để theo dõi anh ta và thu thập bằng chứng, nhưng khi họ tiến gần hơn đến việc khám phá ra sự thật, mọi thứ trở nên nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Graham Verchere","avatar":""},{"name":"Judah Lewis","avatar":""},{"name":"Caleb Emery","avatar":""},{"name":"Cory Gruter-Andrew","avatar":""},{"name":"Tiera Skovbye","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Jason Gray-Stanford","avatar":""},{"name":"J. Alex Brinson","avatar":""},{"name":"William MacDonald","avatar":""},{"name":"Harrison Houde","avatar":""},{"name":"Mark Brandon","avatar":""},{"name":"Susie Castillo","avatar":""},{"name":"Jaiven Natt","avatar":""},{"name":"Shauna Johannesen","avatar":""},{"name":"Aren Buchholz","avatar":""},{"name":"Patrick Lubczy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324397);
