INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-tu-than-4-dai-loan', 'Cuộc Đua Tử Thần 4: Đại Loạn', 'Death Race: Beyond Anarchy', 'https://phimimg.com/upload/vod/20231026-1/3bdd80aee873c173319d29238048b3a5.jpg', 'https://phimimg.com/upload/vod/20231026-1/b802a04efea7e7816e6c99524aa9d19f.jpg', '<p>Trong Đường Đua Tử Thần 4, Danny Trejo trở lại với tư cách là một Bookie tàn nhẫn, Goldberg, trong Death Race điên cuồng nhất, máu nhất. Sau một cuộc tấn công thất bại đối với tù nhân và người lái xe huyền thoại, Frankenstein, chuyên gia Black Ops, Connor Gibson (McGowan) xâm nhập vào một nhà tù liên bang tối đa với một mục tiêu – vào Death Race bất hợp pháp và bất hợp pháp và đưa Frankenstein xuống. &nbsp;Connor sử dụng sự trợ giúp của Baltimore Bob (Glover) và Lists (Koehler), và bất ngờ rơi vào tình yêu với vẻ đẹp bartending, Jane (Marzano). Connor sẽ phải chiến đấu hơn cả cuộc đời của mình trong thế giới tàn nhẫn của không có bảo vệ, không có quy tắc, không theo dõi, và không có sợ hãi…</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Zach McGowan","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Frederick Koehler","avatar":""},{"name":"Christine Marzano","avatar":""},{"name":"Yennis Cheung","avatar":""},{"name":"Nicholas Aaron","avatar":""},{"name":"Lorina Kamburova","avatar":""},{"name":"Julian Seager","avatar":""},{"name":"Kellie Blaise","avatar":""},{"name":"Cameron Jack","avatar":""},{"name":"Velislav Pavlov","avatar":""},{"name":"Cassie Clare","avatar":""},{"name":"Vanina Arias","avatar":""},{"name":"Victoria Ananieva","avatar":""},{"name":"Jasette Amos","avatar":""},{"name":"Neli","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29