INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-overlord', 'Chiến Dịch Overlord', 'Overlord', 'https://phimimg.com/upload/vod/20231026-1/05bd1ec8ad6b9a70ed199a2a9aa855d8.jpg', 'https://phimimg.com/upload/vod/20231026-1/f626ff456c43e20348435c3a8bd8aee0.jpg', '<p>Không gì giúp ta sẵn sàng cho sự hỗn loạn sửng sốt trong phim Chiến Dịch Overlord. Nhà sản xuất tên tuổi J.J. Abrams đã kiến tạo hành trình ly kỳ nghẹt thở về một đội lính nhảy dù Mỹ phải mặt đối mặt với các binh sĩ Phát Xít siêu nhân mà thế giới chưa từng biết đến. Bộ phim hành động kinh điển, dồn dập và được giới chuyên môn ngợi ca này sẽ khiến ta hồi hộp không yên trên ghế cho tới cảnh cuối cùng.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jovan Adepo","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Mathilde Ollivier","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Iain De Caestecker","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Dominic Applewhite","avatar":""},{"name":"Jacob Anderson","avatar":""},{"name":"Mark McKenna","avatar":""},{"name":"Gianny Taufer","avatar":""},{"name":"Erich Redman","avatar":""},{"name":"Patrick Brammall","avatar":""},{"name":"Joseph Quinn","avatar":""},{"name":"Hayley Carmichael","avatar":""},{"name":"Marc Rissmann","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324397);
