INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-co-chiec-dong-ho-ma-thuat', 'Ngôi Nhà Có Chiếc Đồng Hồ Ma Thuật', 'The House with a Clock in Its Walls', 'https://phimimg.com/upload/vod/20231024-1/1b3e644f1e6d72d86e90745b91979cec.jpg', 'https://phimimg.com/upload/vod/20231024-1/66277b442e99f9aa144caaed1c8eb46a.jpg', '<p>Cậu bé 10 tuổi Lewis Barnavelt chuyển đến New Zebedee, Michigan sống với ông bác phù thủy Jonathan trong một căn nhà cổ xưa kỳ quái, nơi ẩn giấu một chiếc đồng hồ ma thuật đe dọa đến sự tồn vong của Trái Đất. Với sự giúp đỡ của ông bác Jonathan và pháp sư “hàng xóm” Zimmerman, Lewis nhát gan phải giành tất cả sự dũng cảm của mình để ngăn chặn các thế lực tà ác và phá hủy chiếc đồng hồ mang đến ngày tận thế cho toàn thế giới.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jack Black","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Owen Vaccaro","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Renée Elise Goldsberry","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Sunny Suljic","avatar":""},{"name":"Lorenza Izzo","avatar":""},{"name":"Braxton Bjerken","avatar":""},{"name":"Vanessa Anne Williams","avatar":""},{"name":"Ricky Muse","avatar":""},{"name":"Charles Green","avatar":""},{"name":"De''Jon Watts","avatar":""},{"name":"Aaron Beelner","avatar":""},{"name":"Joshua Phillips","avatar":""},{"name":"Christian Ca","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
