INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-dao-tau-dia-nguc', 'Kế Hoạch Đào Tẩu: Địa Ngục', 'Escape Plan 2: Hades', 'https://phimimg.com/upload/vod/20231024-1/8d0940dde58f8b7c97901905d3aa2a58.jpg', 'https://phimimg.com/upload/vod/20231024-1/a2c28c9c074898049ce929f53a6ef7cd.jpg', '<p>Sau phần 1 được ra mắt năm 2013 nhận được sự chú ý của khán giả và giới chuyên môn, phần 2 của Escape Plan tiếp tục có nội dung xoay quanh chuyên gia bảo mật Ray Breslin. Anh là một bậc thầy trong việc cài đặt hệ thống an ninh cho các nhà tù liên bang và cũng là người “thử vượt ngục” tại các nhà tù cũ kỹ, nơi mà các nhà chức trách luôn tự hào là chốn không thể xâm phạm.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Jesse Metcalfe","avatar":""},{"name":"50 Cent","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Wes Chatham","avatar":""},{"name":"Titus Welliver","avatar":""},{"name":"Tyron Woodley","avatar":""},{"name":"Chen Tang","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Shea Buckner","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Ashley Cusato","avatar":""},{"name":"Yifan Luo","avatar":""},{"name":"Rowan Bousaid","avatar":""},{"name":"Baylee Curran","avatar":""},{"name":"Zeeko Zaki","avatar":""},{"name":"V","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324397);
