INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-thap-choc-troi', 'Tòa Tháp Chọc Trời', 'Skyscraper', 'https://phimimg.com/upload/vod/20231024-1/1dcb63963dd6053e5470f349845f80bb.jpg', 'https://phimimg.com/upload/vod/20231024-1/8fab82903eac5cd8fc89cc2661a53279.jpg', '<p>Tòa Tháp Chọc Trời là câu chuyện kể về cựu trưởng nhóm cứu hộ FBI Will Ford, giờ đã trở thành người bảo vệ cho những tòa nhà cao tầng. Trong quá trình làm việc, anh bất ngờ thấy tòa nhà cao nhất và có an ninh tốt nhất trên thế giới đột ngột bốc cháy và gia đình anh bị kẹt trong đó. Điều tệ nhất là, anh đã bị gài vào toàn bộ những sự việc này và vừa phải tìm cách thoát khỏi tòa nhà này, vừa phải cứu cả gia đình mình.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Neve Campbell","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"McKenna Roberts","avatar":""},{"name":"Noah Cottrell","avatar":""},{"name":"Hannah Quinlivan","avatar":""},{"name":"Adrian Holmes","avatar":""},{"name":"Elfina Luk","avatar":""},{"name":"Kevin Rankin","avatar":""},{"name":"Gretal Montgomery","avatar":""},{"name":"Jett Klyne","avatar":""},{"name":"Kayden Magnuson","avatar":""},{"name":"Byron Lawson","avatar":""},{"name":"Jaso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
