INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-sieu-anh-hung-2-nguoi-hung', 'Học Viện Siêu Anh Hùng: 2 Người Hùng', 'My Hero Academia: Two Heroes', 'https://phimimg.com/upload/vod/20231024-1/ae9b80ad692c3e199f8604cf99fb1f2a.jpg', 'https://phimimg.com/upload/vod/20231024-1/5d1e5a8ae7dad71a9cfa1d3ea3628e4c.jpg', '<p>Cuộc hành trình cậu bé Izuku sau học kỳ siêu anh hùng đầu tiên, cũng như sau khi trải qua những lần đối đầu với kẻ thù lớn nhất của thế giới là “All For One” - kẻ mang sức mạnh chiếm đoạt các dị năng khác. Mang nặng mối lo nhưng Izuku sẽ được thư giãn vui chơi tại hòn đảo của những nhà khoa học lừng danh và biết thêm về quá khứ của All Might. Tuy nhiên không vì lẽ đó mà cái ác chịu đứng yên khi những thế lực xấu tiếp tục lên kế hoạch tấn công vào hòn đảo kiên cố nhất thế giới này.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2018, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Daiki Yamashita","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Mirai Shida","avatar":""},{"name":"Katsuhisa Namase","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Ryo Hirohashi","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Kei Shindo","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Mitsuru","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d853