INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-chim-se-do', 'Điệp Vụ Chim Sẻ Đỏ', 'Red Sparrow', 'https://phimimg.com/upload/vod/20231024-1/4230d048c05ad3ebd5ceded570e0fbc6.jpg', 'https://phimimg.com/upload/vod/20231024-1/97160cccce55bc83fda4d088485a6042.jpg', '<p>Red Sparrow - Điệp Vụ Chim Sẻ Đỏ (2018) với sự góp mặt của nữ diễn viên xinh đẹp Jennifer Lawrence trong vai Dominica Egorova, nhân vật chính của phim, một điệp viên trẻ người Nga, người đã được tuyển vào Học viện Chim sẻ của nước này, nơi cô bị ép học cách dùng cơ thể mình như một loại vũ khí. Trong điệp vụ đầu tiên của mình, Dominica được giao nhiệm vụ quyến rũ Nathaniel Nash, một điệp viên CIA, người sắp giao cho CIA một tài liệu nhạy cảm, có thể cung cấp những thông tin xuyên suốt về tình báo Nga. Hai đặc vụ trẻ tuổi nhanh chóng rơi vào hiểm cảnh của sự đam mê, cuốn hút và dối lừa đan xen trong mối quan hệ của họ, cuộc sống của họ và cả những người khác nữa cũng nhanh chóng bị đe dọa, khi những thông tin mật của cả hai nước sắp sửa bị đem ra ánh sáng..</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Matthias Schoenaerts","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Thekla Reuten","avatar":""},{"name":"Sakina Jaffrey","avatar":""},{"name":"Sergei Polunin","avatar":""},{"name":"Kristof Konrad","avatar":""},{"name":"Nicole O''Neill","avatar":""},{"name":"Ser","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324397);
