INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-cuop-the-ky-dang-cap-quy-co', 'Băng Cướp Thế Kỷ: Đẳng Cấp Quý Cô', 'Ocean''s Eight', 'https://phimimg.com/upload/vod/20231023-1/0b4576fe805945a3c73352f3f429d87d.jpg', 'https://phimimg.com/upload/vod/20231023-1/606000e870ca5a9b31f783218430cee1.jpg', '<p>Bà hoàng trộm cướp Debbie Ocean (Sandra Bullock) đã tái xuất bên cạnh cô bạn Lou (Cate Blanchett) cùng dàn “đả nữ “ gồm Amita (Mindy Kaling) – chuyên gia trang sức, Constance (Awkwafina) – kẻ chuyên móc túi, Tammy (Sarah Paulson) – bà mẹ hoàn lương, Nine Ball (Rihana) - nữ hacker cực đỉnh và Rose (Helena Bonham Carter) - nhà thiết kế nổi tiếng trong vụ cướp có giá trị triệu đô tại buổi tiệc thường niên Met Gala. Liệu những “nữ quái” của chúng ta có thành công trong phi vụ đánh cắp đầy khó khăn này không ...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Rihanna","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"James Corden","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Nathanya Alexander","avatar":""},{"name":"Damian Young","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Marlo Thomas","avatar":""},{"name":"Dana Ivey","avatar":""},{"name":"Mary Louise Wil","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 178469