INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-giai-cuu', 'Mật Vụ Giải Cứu', 'Hunter Killer', 'https://phimimg.com/upload/vod/20231022-1/da2724f0ac048368856f969bbb27b4ad.jpg', 'https://phimimg.com/upload/vod/20231022-1/abde92ffdd2ecbee39eecab901548ddd.jpg', '<p>“Mật Vụ Giải Cứu” xoay quanh Joe Glass (Gerard Butler ) – một thuyền trưởng tàu ngầm Mỹ, phát hiện ra một âm mưu đảo chính quân sự và bắt cóc tổng thống Nga, được khởi sướng bởi một vị tướng phản trắc Sergi Àndropoyov (Michael Nyqvist). Vì sao Sergi Àndropoyov lại bắt cóc Tổng thống? Liệu Joe Class cùng những hậu vệ của mình có giải cứu được Tổng thống và ngăn chặn chiến tranh Thế Giới thứ 3?</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Toby Stephens","avatar":""},{"name":"Common","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"David Gyasi","avatar":""},{"name":"Gabriel Chavarria","avatar":""},{"name":"Ryan McPartlin","avatar":""},{"name":"Carter MacIntyre","avatar":""},{"name":"Zane Holtz","avatar":""},{"name":"Taylor John Smith","avatar":""},{"name":"Michael Trucco","avatar":""},{"name":"Mikhail Gorevoy","avatar":""},{"name":"Aleksandr Dyachenko","avatar":""},{"name":"Igor Jijikine","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
