INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cap-giang-sinh', 'Kẻ Cắp Giáng Sinh', 'The Grinch', 'https://phimimg.com/upload/vod/20231021-1/15d98914b0d4278b3184f05e28064038.jpg', 'https://phimimg.com/upload/vod/20231021-1/7ad605d6d76711b4a1f72b1c82b54a0c.jpg', '<p>Grinch là một kẻ cô độc, suốt ngày cau có. Hắn không sống chung với bất kỳ ai mà ở trong hang núi với một chú chó. Bị bỏ rơi từ nhỏ, hắn luôn ganh tị với niềm hạnh phúc của tất cả mọi người. Mỗi năm vào dịp Giáng sinh, dân làng phá vỡ sự cô đơn yên tĩnh của hắn với mức độ ngày một ồn ào hơn, náo nhiệt hơn. Khi những người trong làng tuyên bố họ sẽ làm cho Giáng sinh lớn hơn gấp ba lần trong năm nay, Grinch nhận ra rằng chỉ có một cách để hắn đạt được một sự bình an và yên ổn: Phải đánh cắp Giáng sinh.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Rashida Jones","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Cameron Seely","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Pharrell Williams","avatar":""},{"name":"Ramone Hamilton","avatar":""},{"name":"Sam Lavagnino","avatar":""},{"name":"Scarlett Estevez","avatar":""},{"name":"Michael Beattie","avatar":""},{"name":"Scott Mosier","avatar":""},{"name":"Lori Alan","avatar":""},{"name":"Carter Hastings","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"John Kassir","avatar":""},{"name":"Cathy Cavad","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea