INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ralph-dap-pha-pha-dao-the-gioi-ao', 'Ralph Đập Phá: Phá Đảo Thế Giới Ảo', 'Ralph Breaks the Internet', 'https://phimimg.com/upload/vod/20231020-1/e67a82aab84d4cb94fec8c33ea4eb765.jpg', 'https://phimimg.com/upload/vod/20231020-1/889a7c77a815855bf2f4d9ed37ae8cad.jpg', '<p>Sáu năm sau phần 1, một sự kiện thay đổi hoàn toàn cuộc sống của đôi bạn thân Ralph và Vanellope. Máy tính đã kết nối wifi, giờ đây họ bắt đầu cuộc phiêu lưu mới trên mạng Internet.&nbsp; Vì thiết bị trò chơi bị hỏng, anh chàng đập phá Ralph và cô bé Vanellope phải vào thế giới internet để mua đồ mới. Tất nhiên, muốn được như ý thì họ phải làm nhiều việc để kiếm đủ tiền. Cũng chính vì thế mà hai anh em được gặp gỡ và biết được nhiều điều mới lạ cùng một số người bạn vô cùng đặc biệt.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John C. Reilly","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Phil Johnston","avatar":""},{"name":"Anika Noni Rose","avatar":""},{"name":"Irene Bedard","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Ali Wong","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Idina Menzel","avatar":""},{"name":"Glozell Green","avatar":""},{"name":"Hamish Blake","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Mandy Moore","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"