INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-thu-cuong-no', 'Siêu Thú Cuồng Nộ', 'Rampage', 'https://phimimg.com/upload/vod/20231020-1/be4e4c38e4cb513486405bc9f4867c6e.jpg', 'https://phimimg.com/upload/vod/20231020-1/2d10f4ae67ccdde700c2a8c818d9385d.jpg', '<p>Bộ phim kể về nhà sinh vật học Davis Okoye có mối liên kết khăng khít với George - một chú gorilla lưng bạc được anh chăm sóc từ nhỏ. Một thí nghiệm đột biến ngoài ý muốn đã làm biến đổi gorilla thành quái vật khổng lồ hung hăng. Gorilla cùng những sinh vật bị biến đổi khác đã tấn công con người và đẩy nhân loại đứng trước hiểm họa diệt vong. Liệu Davis Okoye sẽ làm gì để giành chiến thắng, không chỉ để ngăn chặn một thảm họa toàn cầu, mà còn để cứu gorilla đã từng là bạn tốt của mình?</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Jake Lacy","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Demetrius Grosse","avatar":""},{"name":"Jack Quaid","avatar":""},{"name":"Breanne Hill","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Urijah Faber","avatar":""},{"name":"Bruce Blackshear","avatar":""},{"name":"Jason Liles","avatar":""},{"name":"Mac Wells","avatar":""},{"name":"Allys","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324397);
