INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sicario-2-chien-binh-mexico', 'Sicario 2: Chiến Binh Mexico', 'Sicario: Day of the Soldado', 'https://phimimg.com/upload/vod/20231020-1/b5a60c24991cb50c9065ddd44339de48.jpg', 'https://phimimg.com/upload/vod/20231020-1/70fb3e593823665a07fc8d7c8672c677.jpg', '<p>Sicario: Day of the Soldado sẽ là một cuộc chiến bất chấp luật lệ giữa chính phủ Mỹ với các băng đảng Mexico - Những tổ chức buôn bán ma túy và vận chuyển người trái phép để thực hiện các vụ khủng bố. Trước tình hình chính trị căng thẳng, đặc vụ liên bang Matt Graver bắt cóc con gái Isabela của tay trùm băng đảng lớn nhất để các phe phái quay sang hạ bệ lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Benicio del Toro","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Elijah Rodriguez","avatar":""},{"name":"Howard Ferguson Jr.","avatar":""},{"name":"David Castañeda","avatar":""},{"name":"Jacqueline Torres","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Bruno Bichir","avatar":""},{"name":"Jake Picking","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
