INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-cu-chot', 'Vét cú chót', 'SuperFly', 'https://phimimg.com/upload/vod/20231019-1/3a4d3e0469ff58c1bb6fc729c326fd94.jpg', 'https://phimimg.com/upload/vod/20231019-1/9051a22afb34e7265571af7bedaac28b.jpg', '<p>Trong phiên bản mới này của bộ phim năm 1972, một tay lừa đảo vui vẻ cố ăn thua đủ với một nhóm đối thủ trước khi từ giã cuộc chơi đường phố mãi mãi.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Trevor Jackson","avatar":""},{"name":"Jason Mitchell","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Lex Scott Davis","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Kaalan Rashad Walker","avatar":""},{"name":"Esai Morales","avatar":""},{"name":"Andrea Londo","avatar":""},{"name":"Big Bank Black","avatar":""},{"name":"Big Boi","avatar":""},{"name":"Jacob Ming-Trent","avatar":""},{"name":"Brian F. Durkin","avatar":""},{"name":"Dominique Madison","avatar":""},{"name":"Angel Love","avatar":""},{"name":"Terayle Hill","avatar":""},{"name":"Dawnta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324397);
