INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-noi-loan', 'Cậu Bé Nổi Loạn', 'Capernaum', 'https://phimimg.com/upload/vod/20231021-1/50848f294647376987f81389ca70e050.jpg', 'https://phimimg.com/upload/vod/20231021-1/0789414ee919da64a658e3ad4452ba1b.jpg', '<p>Dù lấy bối cảnh ở Lebanon, sử dùng dàn diễn viên không mấy tên tuổi nhưng bộ phim vẫn có sức hút riêng khi được “trình làng” tại Liên hoan phim Cannes. Phim kể về một cậu bé nổi loạn muốn chống lại cuộc sống bị áp đặt, và cậu đã bắt đầu một vụ khởi kiện lại chính cha mẹ ruột của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Đảo Síp', 0, '[{"name":"Zain Al Rafeea","avatar":""},{"name":"Yordanos Shifera","avatar":""},{"name":"Boluwatife Treasure Bankole","avatar":""},{"name":"Kawsar Al Haddad","avatar":""},{"name":"Fadi Kamel Yousef","avatar":""},{"name":"Cedra Izzam","avatar":""},{"name":"Alaa Chouchnieh","avatar":""},{"name":"Elias Khoury","avatar":""},{"name":"Nadine Labaki","avatar":""},{"name":"Nour el Husseini","avatar":""},{"name":"Joseph Jimbazian","avatar":""},{"name":"Samira Chalhoub","avatar":""},{"name":"Farah Hasno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
