INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paul-su-do-cua-chua-kito', 'Paul, Sứ Đồ Của Chúa Kito', 'Paul, Apostle of Christ', 'https://phimimg.com/upload/vod/20231021-1/613193a1c8b2815ff8872d51ac8a8db0.jpg', 'https://phimimg.com/upload/vod/20231021-1/e3ab3cf01f4e51fb834126f42d22f3ee.jpg', '<p>Trước lúc bị xử tử, tông đồ Paul đã rao giảng lời của Chúa còn bạn ông, Luke, đã viết một cuốn sách có tính cách mạng dẫn đến sự ra đời của giáo hội.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Caviezel","avatar":""},{"name":"James Faulkner","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Joanne Whalley","avatar":""},{"name":"John Lynch","avatar":""},{"name":"Antonia Campbell-Hughes","avatar":""},{"name":"Noah Huntley","avatar":""},{"name":"Alexandra Vino","avatar":""},{"name":"Alessandro Sperduti","avatar":""},{"name":"Christopher Dingli","avatar":""},{"name":"Husam Chadat","avatar":""},{"name":"Mario Opinato","avatar":""},{"name":"Yorgos Karamihos","avatar":""},{"name":"Manuel Cauchi","avatar":""},{"name":"Anthony Edridge","avatar":""},{"name":"Joe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
