INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-lung', 'Kẻ Săn Lùng', 'Mandy', 'https://phimimg.com/upload/vod/20231021-1/2f2cef3159b176ebf1fabb0e7421b18c.jpg', 'https://phimimg.com/upload/vod/20231021-1/58caaa9080f7f7db2a26d38f386c5f8b.jpg', '<p>Bộ phim Mandy theo chân Red (Nicolas Cage), một người lao động sống tại vùng quê hẻo lánh. Anh sống ở sâu trong rừng cùng vợ mình là Mandy (Andrea Riseborough). Cuộc sống của cả hai trôi qua bình lặng trong căn nhà hòa cùng thiên nhiên. Nhưng Red luôn muốn đi chỗ khác vì anh cảm thấy không an toàn khi mình sống quá sâu trong rừng như vậy. Mọi chuyện có vẻ êm đẹp cho đến khi một nhóm kẻ lạ mặt đi ngang qua khu rừng và nhìn thấy Mandy. Kẻ trưởng nhóm, thủ lĩnh của một giáo phái bí ẩn, mê mẩn vẻ đẹp của Mandy nên đã yêu cầu những thành viên khác bắt cô về cho hắn. Lúc này bộ phim đi theo hướng trả thù khi Mandy bị thiêu sống trước mặt Red. Red đau khổ và nổi giận, quyết tâm truy lùng tiêu diệt bằng được những kẻ làm hại vợ mình ...</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Bill Duke","avatar":""},{"name":"Line Pillet","avatar":""},{"name":"Clément Baronnet","avatar":""},{"name":"Alexis Julemont","avatar":""},{"name":"Ivailo Dimitrov","avatar":""},{"name":"Hayley Saywell","avatar":""},{"name":"Stephan Fraser","avatar":""},{"name":"Kalin Kerin","avatar":""},{"name":"Tamás Hagyuó","avatar":""},{"name":"Paul Painter","avatar":""},{"name":"Zeva DuVall","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
