INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mau-bi-nguyen-rua', 'Dòng Máu Bị Nguyền Rủa', 'Hereditary', 'https://phimimg.com/upload/vod/20231021-1/b9f30c49d07ff71f262237bc49baf09f.jpg', 'https://phimimg.com/upload/vod/20231021-1/6f54bc1f640f441e5c0081268d5c5099.jpg', '<p>Sau khi Ellen – gia chủ nhà Graham – qua đời (thọ 78 tuổi), con cháu của bà bắt đầu khám phá ra hàng loạt bí mật khó hiểu và ngày một đáng sợ về tổ tiên họ. Càng khám phá, họ càng đau đớn nhận thấy gia đình đang phải đối mặt với số phận cay đắng mà dường như họ bị ‘thừa hưởng’ từ người đi trước.</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Toni Collette","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Milly Shapiro","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Pat Barnett Carr","avatar":""},{"name":"Mallory Bechtel","avatar":""},{"name":"Brock McKinney","avatar":""},{"name":"Jake Brown","avatar":""},{"name":"Morgan Lund","avatar":""},{"name":"Christy Summerhays","avatar":""},{"name":"Bus Riley","avatar":""},{"name":"Jarrod Phillips","avatar":""},{"name":"Heidi Mendez","avatar":""},{"name":"Zachary Arthur","avatar":""},{"name":"David Stanley","avatar":""},{"name":"Moises L. Tovar","avatar":""},{"name":"Au","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
