INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-me-cung-loi-thoat-tu-than', 'Giải Mã Mê Cung: Lối Thoát Tử Thần', 'Maze Runner: The Death Cure', 'https://phimimg.com/upload/vod/20231018-1/1f54b0765348f6eca77763e468b1adb5.jpg', 'https://phimimg.com/upload/vod/20231018-1/c2bd6c6ac75214a9cbe8f10f5f096b9c.jpg', '<p>Ở phần trước, trong khi trốn thoát khỏi sự săn lùng của W.C.K.D, Minho đã bị bắt đi và đưa về sào huyệt Last City. Không chấp nhận mất thêm thành viên, trong phần này cư dân Trảng Cỏ với sự lãnh đạo của Thomas quyết định sẽ tấn công vào sào huyệt để cứu người. Đây sẽ là thử thách nguy hiểm nhất mà nhóm bạn phải đối đầu khi Last City được mệnh danh là mê cung nguy hiểm nhất và cũng là sào huyệt cuối cùng của W.C.K.D. Tại đây, sau khi giải mã được mê cung, cả nhóm sẽ có lời giải đáp cho tất cả những thắc mắc của mình từ trước đến nay, cũng như câu hỏi liệu Theresa có phải là kẻ phản bội?</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Ki Hong Lee","avatar":""},{"name":"Rosa Salazar","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Jacob Lofland","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Dexter Darden","avatar":""},{"name":"Katherine McNamara","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
