INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thanh-trung-dau-tien', 'Ngày Thanh Trừng Đầu Tiên', 'The First Purge', 'https://phimimg.com/upload/vod/20231018-1/d2b97ce5dc534f324f071c00df3d308f.jpg', 'https://phimimg.com/upload/vod/20231018-1/295786244df6b2c5643249076340e073.jpg', '<p>Phim hành động kinh dị này của đạo diễn Gerard McMurray đóng vai trò như một prequel kể lại những sự kiện dẫn đến sự kiện Thanh trừng đầu tiên. Để đẩy tỷ lệ tội phạm xuống dưới một phần trăm trong thời gian còn lại của năm, Tổ chức sáng lập mới của Hoa Kỳ (NFFA) kiểm tra một lý thuyết xã hội học nhằm chọc giận một cộng đồng bị cô lập trong một đêm để họ sát hại lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Y''lan Noel","avatar":""},{"name":"Lex Scott Davis","avatar":""},{"name":"Joivan Wade","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"Mugga","avatar":""},{"name":"Patch Darragh","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Luna Lauren Velez","avatar":""},{"name":"Kristen Solis","avatar":""},{"name":"Rotimi Paul","avatar":""},{"name":"Mo McRae","avatar":""},{"name":"Jermel Howard","avatar":""},{"name":"Siya","avatar":""},{"name":"Christian Robinson","avatar":""},{"name":"Derek Basco","avatar":""},{"name":"D.K. Bowser","avatar":""},{"name":"Mitchell Edwards","avatar":""},{"name":"Maria Rivera","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
