INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('venom', 'Venom', 'Venom', 'https://phimimg.com/upload/vod/20231018-1/4bf405a44b047a5c0b85a3b59bee2396.jpg', 'https://phimimg.com/upload/vod/20231018-1/64b47296c11df30d15f81174d54c6db3.jpg', '<p>Quái Vật Venom là một kẻ thù nguy hiểm và nặng ký của Người nhện trong loạt series của Marvel. Chàng phóng viên Eddie Brock bí mật theo dõi âm mưu xấu xa của một tổ chức và đã không may mắn khi nhiễm phải loại cộng sinh trùng ngoài hành tinh (Symbiote) và từ đó đã không còn làm chủ bản thân về thể chất lẫn tinh thần. Điều này đã dần biến anh thành quái vật đen tối và nguy hiểm nhất chống lại người Nhện - Venom ...</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Riz Ahmed","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Peggy Lu","avatar":""},{"name":"Malcolm C. Murray","avatar":""},{"name":"Sope Aluko","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"Michelle Lee","avatar":""},{"name":"Kurt Yue","avatar":""},{"name":"Chris O''Hara","avatar":""},{"name":"Emilio Rivera","avatar":""},{"name":"Amelia Young","avatar":""},{"name":"Ariadne Joseph","avatar":""},{"name":"Dee","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324397);
