INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wild-war', 'Wild War', 'Wild War', 'https://phimimg.com/upload/vod/20231014-1/a94cf1d2f708e8575b508f6d6d217ab3.jpg', 'https://phimimg.com/upload/vod/20231014-1/49f91a6a3f167069fd7a5dec1a7ef442.jpg', '<p>Phim kể về câu chuyện của Lão Mao (do Lưu Cảnh Hồng thủ vai) và người anh trai thiểu năng Can Can (do Zhu Furun thủ vai) mở một nhà hàng lẩu ở thị trấn Qingshui sau khi đội đặc nhiệm &quot;Long Knife&quot; thất bại trong một chiến dịch chung. . Tuy nhiên, cuộc sống yên bình này bỗng nhiên vướng vào vòng xoáy tội phạm phức tạp, còn người bạn đóng hộp Xiaoqian (do Lu Jia thủ vai) dính sâu vào, một giao dịch bí mật không rõ danh tính dần lộ diện, và một cuộc tranh giành sức mạnh chênh lệch cứ kéo nhau đi.</p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Geng-Hong","avatar":""},{"name":"Furun Zhu","avatar":""},{"name":"Shuangli Zhang","avatar":""},{"name":"Sang Ping","avatar":""},{"name":"Liu Rui","avatar":""},{"name":"Jia Lu","avatar":""},{"name":"Mark Vachara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324397);
