INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-thu-doat-menh', 'Biệt Thự Đoạt Mệnh', 'The Villa of Death', 'https://phimimg.com/upload/vod/20231014-1/b0117673be51c96afbc0ebb73c511dd3.jpg', 'https://phimimg.com/upload/vod/20231014-1/67834377f7e7b4d20bccd31e8a17966f.jpg', '<p>Một cô gái xinh đẹp say khướt lảo đảo loạng choạng đi về phía bể bơi ngoài trời, phía sau cô đột nhiên xuất hiện một bóng người cao lớn kỳ lạ, thân hình càng lúc càng lớn, che phủ hoàn toàn cơ thể cô gái. . Một luồng ánh sáng lạnh lẽo xẹt qua cổ cô gái, cô gái rơi xuống bể bơi, mặt nước đột nhiên đỏ rực, màu máu không ngừng lan rộng, toàn bộ tầm nhìn bị nhuộm đỏ bởi máu.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Ming","avatar":""},{"name":"Sun Xiaofei","avatar":""},{"name":"Cui Jingge","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
