INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-thu-sai-kwan', 'Biệt thự Sai Kwan', 'Sai Kwan Mansion', 'https://phimimg.com/upload/vod/20231014-1/9864536095a9d274a990a1c4a294fb84.jpg', 'https://phimimg.com/upload/vod/20231014-1/2c629aa6a36d4a3735983c2bcef7f1e6.jpg', '<p>Pan Mengdie, Hoa hậu Tây Quan cuối cùng ở Quảng Châu, từng là một mỹ nhân vô song, hiện sống trong một ngôi nhà lớn ở Tây Quan. Trong gần một thế kỷ, cô đã giữ chặt tình yêu, bí mật gia đình và quê hương của chính mình... Cảnh sát cộng đồng Ma Sipeng là một cảnh sát nhân dân mạnh mẽ, thông minh và hay giúp đỡ. Anh ta nhận được một vụ án liên quan đến ma túy mang tên &quot;Mật danh Miss Xiguan&quot;. Trong quá trình điều tra, Ma Sipeng đã gặp Pan Mengdie và hậu duệ của ông ta là Ye Yixi. Khi vụ án tiến triển, nhiều bí mật chưa được biết đến sẽ được tiết lộ, và một cuộc chiến sinh tử về những cảm xúc phức tạp như cảnh sát và thường dân, mối quan hệ gia đình và mối quan hệ huyết thống sắp bắt đầu...</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Na Renhua","avatar":""},{"name":"Wu Jingjing","avatar":""},{"name":"Li Qi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324397);
