INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-qua', 'Bỏ Qua', 'Let Go', 'null', 'https://phimimg.com/upload/vod/20231014-1/ee15359b8a1af615323d132adf034cc2.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nhiều khi yêu một người không nhất thiết phải ở bên anh ta, và buông bỏ người khác cũng là buông bỏ chính mình. Có nhiều hơn tình yêu, tình cảm và ước mơ trong cuộc sống. Đừng ép buộc tình yêu của chính mình, ép buộc nó sẽ chỉ khiến bạn tổn thương nhiều hơn. Đừng dằn vặt bản thân vì thất bại, những người không bỏ cuộc sẽ tự tin hơn và có một cuộc sống đầy đủ hơn. Khi bạn học cách buông bỏ và biết cách ban phước, không phải là thế giới còn lại với bạn, mà là có thêm một người yêu bạn. Bộ phim phản ánh rằng các cô gái hiện đại không biết cách tự bảo vệ mình, sự phù phiếm, tôn thờ tiền bạc hầu hết đều hư hỏng, và He Huân trong vở kịch thể hiện rất rõ rằng các cô gái hiện đại được chiều chuộng không vì điều gì, ngon miệng, lười biếng, ham chơi và cố ý. Vở kịch cũng phản ánh rằng mỗi đứa trẻ nghịch ngợm là một cổ phiếu tiềm năng, bởi vì chúng chưa được tiếp xúc với xã hội, chúng sẽ dựa trên hạnh phúc của mình dựa trên nỗi đau của người khác. Miễn là chúng có thể được kiên nhẫn hơn, trẻ sẽ dành tất cả tình yêu và biết cách biết ơn sau khi học cách biết ơn khi bước vào xã hội.</span></p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Xiu Ke","avatar":""},{"name":"Ding He","avatar":""},{"name":"Wu Xiu Ke","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324397);
