INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi-loi', 'Bỏng Tội Lỗi', 'The Burns of Sin', 'null', 'https://phimimg.com/upload/vod/20231014-1/f44d8e35e46fb5273a1faf8d98d46558.jpg', '<p>Su Cheng trở về quê hương sau vài năm ở nước ngoài để tìm người bạn thân nhất của mình là Wang và người yêu cũ Lin Jing đã kết hôn và ổn định cuộc sống. Ký ức của Cheng về thành phố phản ánh một tuổi thơ khó khăn, bị trầm cảm và thường xuyên đánh nhau với các bạn cùng lớp. Đột nhiên Wang được phát hiện bị sát hại dã man trong vụ mà cảnh sát nghi ngờ là một trong hàng loạt vụ giết người hàng loạt vì vợ hoặc chồng lừa dối. Kẻ giết người bắt cóc cặp đôi lừa dối và tra tấn họ trước khi sát hại một người và để người kia làm nhân chứng. Jing từ chối tin rằng chồng cô đã lừa dối cô và tuyệt vọng tìm kiếm câu trả lời cho cái chết của anh. Ở bên cạnh cô, Su Cheng tìm cách bảo vệ Lin Jing trong khi che giấu những bí mật đen tối của riêng mình. Trong khi đó, cảnh sát nghi ngờ Su Cheng có thể có liên quan gì đó đến tội ác. Sự trở lại của anh ấy có thực sự ngẫu nhiên như người ta tưởng không?</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Quân Ninh","avatar":""},{"name":"Mark.DU","avatar":""},{"name":"Du Yi Heng","avatar":""},{"name":"Shi Yu Qing","avatar":""},{"name":"Miko ＆Yumi","avatar":""},{"name":"He Qiang","avatar":""},{"name":"Boa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324397);
