INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-nho-khong-duoc-kiem-soat', 'Bộ Nhớ Không Được Kiểm Soát', 'Out of Control Memory', 'https://phimimg.com/upload/vod/20231014-1/01de264c191512bf9262bf43e8634673.jpg', 'https://phimimg.com/upload/vod/20231014-1/0edc0fe1cd17e34942551c7cd0f603e6.jpg', '<p>Một cặp chị em sinh đôi bị chia cắt vì lý do gia đình khi còn nhỏ, họ lớn lên trong những môi trường khác nhau. Vì sự biến mất của em gái cô (Tian Ying), Xiying bắt đầu cảm nhận được khả năng ngoại cảm đặc biệt của cặp song sinh, thông qua cảm ứng, Xiying cảm thấy vụ việc em gái mình mất tích không hề đơn giản nên cô quyết định tự mình tìm ra sự thật. .</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ariel Ann","avatar":""},{"name":"He Cao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324397);
