INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-lac-sac-dep', 'Bộ Lạc Sắc Đẹp', 'Beauty Tribe', 'null', 'https://phimimg.com/upload/vod/20231014-1/6c1964a5f072ee3ead643c5bc7170cf3.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim chủ yếu kể về câu chuyện của Neeson được lệnh bí mật thâm nhập vào tổ chức buôn bán ma túy của vua Brahma. Danh tính được tiết lộ và anh vô tình bước vào bộ lạc Morba. Ibra có một tình cảm thực sự dành cho Neeson. Neeson phát hiện ra rằng loại thuốc mà anh ta đang theo đuổi, Maha Mandala, là di tích thiêng liêng của bộ lạc Morba! Sanya tuyên bố rằng việc Neeson phá hủy lễ hội là âm mưu của ông với vua Brahma.</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Meng","avatar":""},{"name":"Li Yuyang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
