INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kiem-bat-tu-va-voldemort', 'Thanh kiếm bất tử và Voldemort', 'Four Weapons', 'null', 'https://phimimg.com/upload/vod/20231014-1/c2164ccb6e99c8e96d7908628da91674.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Theo võ thuật: &quot;Người lính quỷ trở lại, và băng nuốt chửng linh hồn; Chiến tranh đốt cháy bầu trời, hủy diệt thế giới tối cao. Chỉ cần bất cứ ai có thể làm chủ bốn chiến sĩ quỷ, họ có thể được tái sinh như một hình phạt và bất khả chiến bại với thế giới! Yan Fengqing, người mạnh về võ thuật nhưng không rành về các vấn đề thế giới, đã đến Thanh Nguyên để tìm tung tích của anh trai Xiao Hanyu, và gặp nữ anh hùng lập dị Yingqing trong một tai nạn, và hai kẻ sai trái Hoàn Tây cùng nhau dấn thân vào một cuộc hành trình săn kiếm nguy hiểm trong âm thanh chiến đấu, và họ không biết rằng sự xuất hiện trở lại của Soul Devouring Sword liên quan đến sự thật và mối hận thù ẩn giấu trong nhiều năm, và một âm mưu xấu xa đang từng bước tiếp cận họ...</span></p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Yirong","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Ma Yongkang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324397);
