INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui', 'Bụi', 'Dust', 'null', 'https://phimimg.com/upload/vod/20231014-1/e441550d01016995ce0d5d1ad0af0257.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Lý Lâm đeo kính dày, theo bạn trai Trịnh Chí Nguyên đến Bắc Kinh sau khi tốt nghiệp, hai người thuê một căn nhà nhỏ, đối mặt với áp lực cuộc sống, Trịnh Chí Nguyên thường xuyên làm thêm giờ, thái độ đối với Lý Lâm dần dần thay đổi, Lý Lâm còn chưa tìm được việc làm, trong lòng rất khó chịu và sợ hãi, cho đến khi bạn học của Lý Lâm là Vương Tiểu Tiên xuất hiện, hoàn toàn phá vỡ cuộc sống của hai người, biết được Vương Tiểu Huyền đang làm ngành tài chính, Lý Lâm ghen tị, Vương Tiểu Hiền đưa Lý Lâm đi uống cà phê, mua sắm và những việc khác mà bạn trai cô chưa bao giờ đưa anh ta làm, Dần dần tận hưởng cảm giác thỏa mãn, vướng mắc tương tự lơ lửng giữa bạn trai Trịnh Chí Viễn và Vương Hiểu Xán, cho đến một ngày, vì son môi và bạn trai cãi nhau, Lý Lâm quyết định thay đổi hiện trạng và kiểm điểm lại bản thân, nhưng đối mặt với Vương Tiểu Hạn, trong lòng cô luôn có chút lo lắng, khi chuẩn bị hoàn toàn đến gặp Vương Hiểu Xán, sự thay đổi trong cuộc sống của Trịnh Chí Nguyên khiến cô lại có được dấu vết ấm áp ở thành phố đông đúc này.</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Ce","avatar":""},{"name":"Jin Hongjie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324397);
