INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-dem', 'Bùa Đêm', 'Drunk', 'https://phimimg.com/upload/vod/20231014-1/02d85cf2ff926516dcac05c8659327e0.jpg', 'https://phimimg.com/upload/vod/20231014-1/b82d534d1fd11fe4e76f7ae00ea03f7f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Kiều Hạ, một giám đốc kế hoạch quảng cáo xinh đẹp đến từ Hồng Kông, có năng lực và hấp dẫn trong công việc, và cô ấy có một tính khí cao và lạnh lùng trong cuộc sống! Tuy nhiên, lý tưởng của nữ chính quyến rũ đi ngược lại với bạn trai giá cả phải chăng Wu Chao, khiến nhiều cuộc khủng hoảng khác nhau nổ ra trong sự quyến rũ ban đêm. Bỗng dưng bị bạn trai chia tay và gặp khủng hoảng công việc. Để giải quyết vấn đề công việc, anh đưa bạn gái Anne đến quán bar vào ban đêm, đầu tiên là say xỉn bởi một đồng nghiệp cũ đã lấy đi thông tin quan trọng của công ty, sau đó bị nhầm lẫn bởi một ông chủ hộp đêm đẹp trai của Gao Fu, và trong quá trình đó, anh đã gặp những nhân vật kỳ quái như chủ đảo và đài truyền hình trực tiếp đen tối... Thức dậy vào một đêm rượu, Josha thức dậy trong phòng ngủ của một người đàn ông lạ, chỉ mặc đồ lót khiêu dâm. Lúc này, giọng nói của hai người đàn ông truyền đến từ ngoài cửa... Điều tồi tệ hơn, thời gian cho lời cầu hôn quan trọng được công ty đồng ý đã trôi qua, và video về xác chết của anh ta được nhặt tối qua đã được đài truyền hình trực tiếp đen tối tải lên Internet, và bạn gái biến mất... Những gì dường như là một cuộc gặp gỡ tình cờ đã biến thành một bộ phim hài điên rồ lãng mạn vui nhộn.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Cốt truyện của &quot;The Drunken Night Enchantment&quot; mở ra trong 36 giờ, cho thấy sự bối rối và lựa chọn của những người lao động cổ cồn trắng thành thị thông qua cảnh câu chuyện thường xuyên của cuộc sống về đêm đô thị. Đối với nữ chính Qiao Xia và bạn trai Wu Chao, đó là một tai nạn, hay đó là một tập phim vào đúng thời điểm? Đối với Qiao Xia và Gao Fu đẹp trai Shi Yang, đó là một khởi đầu mới, hay chỉ là &quot;bữa tối mùa xuân một đêm&quot;?</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhen Caixi","avatar":""},{"name":"Xiao Helin Hua","avatar":""},{"name":"Gu Renqi","avatar":""},{"name":"He Xinyao","avatar":""},{"name":"Wen Ting","avatar":""},{"name":"Lý Thuận Nghi","avatar":""},{"name":"Liêu Tấn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
