INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-qua-tuong', 'Bay Qua Tường', 'Misdelivered Parcel', 'https://phimimg.com/upload/vod/20231014-1/576d8a25dc7b156890b95d8567f798f8.jpg', 'https://phimimg.com/upload/vod/20231014-1/c1cba5c745d9ac582ef3c99bfa6f10de.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nhân vật chính Tianle làm việc trong một công ty chuyển phát nhanh tên là &quot;Thief La Fast&quot; trong thành phố, và một lần vì sai lầm trong công việc, một người chuyển phát nhanh đã được giao không chính xác, nhưng anh ta không biết rằng chuyến chuyển phát nhanh này là một món đồ cổ của băng đảng bán lại di tích văn hóa &quot;Anh Mao&quot;, và Anh Mao tức giận đã sắp xếp cho cấp dưới của mình không lấy được chuyển phát nhanh nhiều lần, và cuối cùng kiểm soát tất cả những người có liên hệ với chuyển phát nhanh đến kho...</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiao Shenlong","avatar":""},{"name":"Lu Haitao","avatar":""},{"name":"Full stop","avatar":""},{"name":"Yang Xiaoman","avatar":""},{"name":"Anh trai tự tin","avatar":""},{"name":"Tôn Tiểu Bắc","avatar":""},{"name":"Tiểu Thần phù hộ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324397);
