INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-bam', 'Bụi Bặm', 'The Struggle', 'https://phimimg.com/upload/vod/20231014-1/c733da6ae60b5d89b164d5f2caf30f99.jpg', 'https://phimimg.com/upload/vod/20231014-1/1e365c0e4fea81a32cc8d6377952a608.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Chen Tu là một người dân làng làm việc ở những nơi khác. Người con trai đã cố gắng tự tử bằng cách cắt cổ tay của mình trong làng, nhưng Chen Tu phát hiện ra rằng anh ta và con trai mình không phù hợp với nhóm máu của họ, và Chen Tu hèn nhát đã thua lỗ. Sau khi tự đấu tranh, Trần Tú vẫn chọn cách hy sinh thận của mình cho vợ của Vương Chính, để không để vợ bỏ mình, và sau đó bảo vệ gia đình. Cốt truyện kịch tính xuất hiện, vợ Vương Chính chết vì đào thải thận, trùng hợp thay, Vương Chính cũng mất mạng vô cớ, Trần Tú không biết lựa chọn tình cảm gia đình và lòng tốt sau khi biết nguyên nhân của sự việc, Trần Tú mất mát và phát điên, cuối cùng với sự giúp đỡ của tình cảm gia đình, Trần Tú đã có thể đối mặt với cuộc sống một lần nữa, suy nghĩ lại về cuộc sống và nhận lại trách nhiệm của mình...</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yong","avatar":""},{"name":"Zhou Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
