INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buom-quy-dot-bien', 'Bướm Quỷ Đột Biến', 'Mutant Demon Butterfly', 'https://phimimg.com/upload/vod/20231014-1/6bec0b6c6d7e87f0049a964d69616f20.jpg', 'https://phimimg.com/upload/vod/20231014-1/75c822362dbca36d4731e98a36302fb0.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Loài bướm bí ẩn của Lingflies cổ đại gần như bị diệt chủng do ô nhiễm của con người, và loài bướm cái duy nhất còn lại Fei&#39;er cũng trở thành quái vật lưỡng tính do đột biến gen. Để thụ thai một bào thai linh hồn, Butterfly Fei&#39;er đã không ngần ngại dành sức sống để giao thoa với con người, và sử dụng Ma thuật Năng lượng Bướm Linh để tấn công con người. Đúng lúc này, cô đột nhiên phát hiện ra Lâm Tử Phàm, con bướm nam của người yêu thời thơ ấu đã thất lạc từ lâu, đang yêu em gái của kẻ thù. Để cho Lâm Tử Phàm trở về gia tộc Bướm Linh hồn và sinh ra những đứa con Bướm Linh thuần chủng với anh ta, Bướm đã giam cầm Yoyo và sử dụng phù thủy để ngụy trang Yoyo để gây nhầm lẫn cho Lâm Tử Phàm, nhưng đã yêu và không thể tự giải thoát. Khi Lin Zifan phát hiện ra sự thật, anh ta đã buộc Bướm Phi Nhĩ giao Yoyo, và khiến Bướm Phi Nhĩ biến dạng. Bướm Phi tức giận, gen nam bị kích thích, bắt đầu trả thù điên cuồng, phát động trả thù cuối cùng đối với người khởi xướng ô nhiễm, Cố Duy Hoa, cuối cùng chết vì kiệt sức vì sử dụng quá nhiều phù thủy! Và Lâm Tử Phàm say mê vẫn đang tìm kiếm người yêu mất tích của mình...</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yuqing","avatar":""},{"name":"Evan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
