INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-bong-trong-mot-nha-may-cu', 'Cái Bóng Trong Một Nhà Máy Cũ', 'Shadow in An Old Factory', 'https://phimimg.com/upload/vod/20231014-1/86482df1e4dcf984d1f2f2b1debf4e63.jpg', 'https://phimimg.com/upload/vod/20231014-1/0f544041e7781b0c2770ab1ae6220df5.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Một nhà máy bỏ hoang đáng sợ, một cặp tình nhân trẻ, một nhiếp ảnh gia, một bức ảnh cũ, một người đàn ông đeo mặt nạ bí ẩn, một câu chuyện tình yêu đã đi sai hai mươi năm trước, diễn giải các quỹ đạo khác nhau của cuộc sống và luật sắt của cùng một con đường, và so sánh sự khác biệt trong quan điểm của mọi người về tình yêu trong các thời đại khác nhau. Đúng sai là do khán giả phán xét.</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tao Meiyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
