INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-yeu-nuoc', 'Cảnh Sát Yêu Nước', 'Patriot Policeman', 'https://phimimg.com/upload/vod/20231014-1/3a680af99c9e4da894b63043c350f8ad.jpg', 'https://phimimg.com/upload/vod/20231014-1/0adb7bff71c8857f0aac464ea4cb24cd.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Năm 1931, Nhật Bản phát động một cuộc chiến tranh xâm lược khác chống lại Trung Quốc, và sớm chiếm đóng ba tỉnh Liêu Ninh, Cát Lâm và Hắc Long Giang ở đông bắc Trung Quốc. Vào thời điểm này, các samurai Nhật Bản ở Trung Quốc bắt đầu nổi điên và khiêu khích vô đạo đức trên đất Trung Quốc, và cuộc sống hàng ngày của người dân rơi vào tình trạng khó khăn. Vào ngày này, một chiến binh cách mạng đã chạy trốn đến thị trấn vì sự truy đuổi của samurai Nhật Bản. Lúc này, tình hình rất nguy cấp, và ngay khi các chiến sĩ cách mạng sẵn sàng chết bất cứ lúc nào, đại úy cảnh sát Zhong Mo đã mạo hiểm xúc phạm người Nhật để giúp anh ta trốn thoát. Zhong Mo giỏi lý luận, và anh ta hiểu rằng anh ta đã hoàn toàn xúc phạm người Nhật. Nhưng vì lợi ích của chính nghĩa quốc gia trong trái tim mình, Zhong Mo kiên quyết bắt đầu chiến đấu chống lại các samurai Nhật Bản.</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fu Honglin","avatar":""},{"name":"Fan Fan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324397);
