INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-bat-quy', 'Câu Chuyện Bắt Quỷ', 'The Story of Catching Demons', 'https://phimimg.com/upload/vod/20231013-1/a4108d6a08596f0ddd1bd536d5850fa6.jpg', 'https://phimimg.com/upload/vod/20231013-1/6840c0bd9fe4c5d7d80d8a330eed7380.jpg', '<p>Trong những năm thịnh vượng, linh hồn ma quỷ tràn lan. Triều đình đặc biệt thành lập một tổ chức săn quỷ, &quot;Sư đoàn săn quỷ&quot;, và mỗi thành viên cần uống máu quỷ để chiến đấu chống lại lũ quỷ. Nhưng nếu không giữ được tâm tĩnh lặng, bạn sẽ bị máu quỷ cắn và biến thành bán yêu. Đêm đó, Pei Wende, thủ lĩnh của Cục săn quỷ, dẫn người của mình ra ngoài thành phố để tìm kiếm năng lượng ma quỷ không thể giải thích được. Tại hiện trường người ta phát hiện ra cô gái tên Bai Qingqing thực chất là một con rắn khổng lồ, trong cuộc chiến giữa hai bên, cung điện bị ma vương tấn công, mạng sống của hoàng đế bị treo lơ lửng. Pei Wende được lệnh đưa Bai Qingqing &quot;nội phản&quot; của quỷ vương lên đường tìm kiếm ma vương. Trên đường đi, Pei Wende phát hiện ra rằng Bai Qingqing vốn bị quỷ vương tống tiền. Hai người đã giải quyết những nghi ngờ trước đó và bắt đầu để phát triển một số cảm xúc khác nhau. Sau bao khó khăn, Pei Wende cuối cùng cũng tìm được nơi ẩn náu của Quỷ vương, nhưng khoảng cách quyền lực giữa hai người lập tức trở nên rõ ràng, trong trận chiến, Bai Qingqing đã chết thảm dưới móng vuốt của Quỷ vương để cứu Pei Wende. . .</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324397);
