INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-do-suc-dinh-cao-cua-vua-co-bac-chau-a', 'Cuộc đọ sức đỉnh cao của Vua cờ bạc châu Á', 'Asian Gambling King''s Showdown on the High', 'null', 'https://phimimg.com/upload/vod/20231013-1/4e9cf2969b066643a26dd3e5bcbe810c.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Mười lăm năm trước, khi vua cờ bạc châu Á Wu Yong và Gege đang đánh bạc, thuyền trưởng cũ của con tàu cờ bạc đã đặt bẫy, và Wu Yong bắt thuyền trưởng già hứa sẽ lên bờ trong mười lăm năm với cái giá phải trả là hai chân của mình, và Gege trở thành thuyền trưởng mới. Mười lăm năm sau, con tàu ở phía bên kia lại xuất hiện, và Wu Yong, người đã nghỉ hưu ở sông hồ, nhận được lời mời, ông yêu cầu con trai Wu Zijian và những người học việc Fei Lengcui và Xiaojie lên tàu thay cho anh ta, và vô tình phát hiện ra rằng thuyền trưởng già xuất hiện trở lại, và thuyền trưởng hiện tại Gege đã hành động bí mật. Vì vậy, đám đông mưu mô đã tung ra một &quot;canh bạc cuối cùng&quot; ly kỳ...</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yao Yao","avatar":""},{"name":"Luo Yingjun","avatar":""},{"name":"He Jiaying","avatar":""},{"name":"Meidai Sakai","avatar":""},{"name":"Zhong Ziqing","avatar":""},{"name":"Hara Take","avatar":""},{"name":"Văn Trác","avatar":""},{"name":"Diêu Kiến Vân","avatar":""},{"name":"Hồ Haofan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
