INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-ban-hang-tu-dong', 'Máy Bán Hàng Tự Động', 'Story Machine', 'null', 'https://phimimg.com/upload/vod/20231013-1/139420fb8c566b946b5142dea718ccb0.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Được biết, bộ phim &quot;Máy bán hàng tự động&quot; bao gồm bốn đơn vị câu chuyện kỳ lạ đô thị độc lập, trong đó &quot;The Taming of Rabbits&quot; Pipiru chọn có nên thuần hóa hay không khi thấy các bạn cùng lớp dần biến thành thỏ; &quot;Ghost Hit the Wall&quot; vừa hồi hộp, vừa gào thét vừa hấp dẫn; &quot;Điều ước chức năng&quot; kể câu chuyện về tình yêu vượt đô thị có được siêu năng lực với cái giá là mất nội tạng; &quot;Chicken Soup Instant Noodles&quot; mang đến cho mì ăn liền bình thường sức mạnh kỳ diệu của ảo giác, vô lý và đầy những trò đùa.</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tào Yunjin","avatar":""},{"name":"Zhao Da","avatar":""},{"name":"Shao Yun","avatar":""},{"name":"Ma Yuan","avatar":""},{"name":"Lu Siyu","avatar":""},{"name":"Triệu Tuyết","avatar":""},{"name":"Góa phụ","avatar":""},{"name":"Trịnh Nguyên Kiệt","avatar":""},{"name":"Tống Xuân","avatar":""},{"name":"Tạ Nguyên","avatar":""},{"name":"Trần Duẫn Nghi","avatar":""},{"name":"Trang Trạch Khê","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
