INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-o-18-do-vi-bac', 'Câu Chuyện Tình Yêu Ở 18 Độ Vĩ Bắc', 'A Love Story of Haikou', 'null', 'https://phimimg.com/upload/vod/20231013-1/0776a0b6196bc980139f94af09ec7b95.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Zheng Lei, đội trưởng đội cứu hỏa Hải Khẩu, lẽ ra phải có một tương lai tươi sáng, nhưng đột nhiên kết thúc sự nghiệp chữa cháy của mình, vì một tai nạn trong một cuộc cứu hỏa, và đồng đội của anh ta là Lin Kai đã chết trong vụ cháy của vụ nổ bồn chứa dầu khí để bảo vệ tính mạng của Zheng Lei. Đồng thời, nó kết thúc cuộc sống tình cảm của Trịnh Lôi bằng đèn đỏ, người lẽ ra phải nói về cuộc hôn nhân với bạn gái An Wei, và bạn gái của anh đã kết thúc tình yêu với Trịnh Lôi trong nhiều năm dưới áp lực của gia đình, và Zheng Lei, người thì là, quyết định trở về quê hương của mình, Hải Khẩu Bảo Đình.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Hao","avatar":""},{"name":"Zheng Yihan","avatar":""},{"name":"Zhang Lifei","avatar":""},{"name":"Yu Yankai","avatar":""},{"name":"Fu Qiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
