INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-duong-long-quan-so-237', 'Câu chuyện về đường Long Quan số 237', 'Story of Long Quan Road No.237', 'null', 'https://phimimg.com/upload/vod/20231013-1/0282c181e61351526029cff891d07d61.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Hứa Tiểu Thủy nhút nhát và hèn nhát, thường rơi vào tưởng tượng bản thân. Ngay khi vào đại học, anh đã bị các đàn anh &quot;nhiệt tình&quot; bắt nạt mạnh mẽ. Và vì tính cách hướng nội và không có khả năng hòa nhập vào nhóm, ba người bạn cùng phòng đã quyết định &quot;ép&quot; anh theo đuổi lớp học và rèn luyện động lực bản thân để giúp anh thoát khỏi chính mình. Tuy nhiên, mọi thứ phản tác dụng, Hứa Tiểu Thủy liên tục thất vọng, tai nạn vẫn tiếp diễn, trong khoảng thời gian giết người đàn ông xe thể thao phá rối tình hình, Hứa Tiểu Thủy bị Ban Hoa &quot;chỉ định&quot; nhầm là bạn trai, anh không có thời gian để hạnh phúc và &quot;chia tay&quot;, sau một thời gian ngắn &quot;yêu&quot; xoắn xuýt, Hứa Tiểu Thủy đã có chút hiểu biết. Trong một vụ tai nạn giao thông tình cờ, trái tim Hứa Tiểu Hoài đã hoàn toàn bùng cháy, anh đứng lên ngăn chặn người đàn ông xe thể thao gây ra tai nạn, đồng thời cũng gặp Hạo Vũ Thanh, từ đó anh dần dần mở lòng và dũng cảm là chính mình. Xiaoshuai và ba anh em tốt đã dàn dựng một câu chuyện trưởng thành tuổi trẻ vui nhộn.</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Peng","avatar":""},{"name":"Cao Can","avatar":""},{"name":"Zou Quanzong","avatar":""},{"name":"Fu Yufan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
