INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-shi-yumo', 'Câu chuyện về Shi Yumo', 'Story of Shi Yumo', 'https://phimimg.com/upload/vod/20231013-1/9e3c7599f0e47b2d1e6eec63ce5f1cff.jpg', 'https://phimimg.com/upload/vod/20231013-1/4dc366c00c2881435a2cdc55debfded5.jpg', '<p>Phim kể về cậu bé mồ côi Shi Yumo học võ trên núi, sau khi từ trên núi xuống núi, với sự giúp đỡ của những người hàng xóm trong làng, cậu không chỉ tìm được việc làm mà còn trở thành ông chủ. buồn cười đến xấu hổ và cũng cảm động, cuối cùng Shi Yumo Mo và những người bạn của mình đã chiến đấu chống lại thế lực tà ác và giành chiến thắng, đưa thế lực tà ác ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324398);
