INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-dai-khanh', 'Câu chuyện về Đại Khánh', 'Story of Daqing', 'https://phimimg.com/upload/vod/20231013-1/8ee518df28a03c1e38318705c8fe0330.jpg', 'https://phimimg.com/upload/vod/20231013-1/81aa46d0f465209a68681f8f6eebe7df.jpg', '<p>Gao Daqing, một người dân làng ở Gaojiazhuang, một vùng nông thôn mới xinh đẹp ở Đông Bắc Trung Quốc, giúp đỡ những người anh em nông dân của mình để lấy tiền lương, nhưng lại rơi vào tình thế khó xử vì anh là bạn tốt của nhà phát triển ông Wang. Sau khi vào thành phố, tôi được biết anh trai của ông Vương đã nhảy khỏi một tòa nhà sau khi thua bạc trong cờ bạc ở Ma Cao, và anh ấy đã rơi vào tình thế tiến thoái lưỡng nan một thời gian. Trong khoảng thời gian này, anh tình cờ gặp một kẻ buôn bán ma túy, anh tiến bước khó khăn và khi nhìn thấy tình thế tiến thoái lưỡng nan của ông Vương, ông đã chọn cách dùng tiền ma túy để giúp người anh tốt của mình là ông Vương thoát khỏi vòng vây. .</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
