INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-ve-dai-khanh', 'Câu chuyện về Đại Khánh', 'Story of Daqing', 'câu chuyện về đại khánh story of daqing  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-mot-con-nhen-yeu-tinh', 'Câu Chuyện Về Một Con Nhện Yêu Tinh', 'Story of a Spider Goblin', 'null', 'https://phimimg.com/upload/vod/20231013-1/f417b535f9f2ca93f1c96478529f673a.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Con quỷ cáo ngàn năm hút dương khí của con người và lắc con nhện nhỏ bên cạnh nó đến lối vào hang động Nam Sơn, con nhện nhỏ vô tình ăn thuốc tiên, con nhện nhỏ bị một đứa trẻ làm bị thương, sau đó được nhà sư nhỏ Jing Kong cứu và đặt tên là Bu Nian, Bu Nian đi theo Jing Kong như một cái bóng, xuân hạ, thu và đông luân hồi, dưới ảnh hưởng của Phật giáo thành hình người, sớm bị chủ nhà Hui Rui phát hiện, sự nhảy nhót sôi nổi không suy nghĩ đã dẫn đến việc vô tình đốt cháy gian hàng kinh điển Tây Tạng, ngôi chùa rất khó ảnh hưởng đến cô nữa, vì vậy hãy để cô mang &quot;Kinh Tình&quot; xuống núi tìm chú Huệ Minh, Bu Nian và Jie Kong bắt đầu cuộc hành trình đến thế giới cùng nhau, trong thời gian đó họ gặp Wang Shanren, một kẻ bắt nạt mạnh mẽ con gái của nhân dân, Wang Shanren coi Bu Nian như một cô gái quỷ, coi Jie Kong như một nhà sư quỷ, và bị Bu Nian đẩy lùi sau nhiều lần bị bắt. Cho nên hắn tìm quỷ cáo giúp đỡ, phòng ngự cũng không bị quỷ cáo làm bị thương, cuối cùng quỷ cáo hiểu được tình yêu không phải là chiếm hữu, mà là hy sinh sinh mệnh, quyết định tu luyện lại. Jie Kong vốn là một người trong phái Phật giáo, nhưng vì bị nhiễm bụi đỏ và phá vỡ Yang Shou vì không nghĩ về điều đó, anh ta quyết định hy sinh một viên thuốc quỷ để cứu Jie Kong, và cầu nguyện cho Jie Kong từ núi Nam Sơn bị đóng cửa.</span></p>', 'Full', 1, 'single', 'completed', 11, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Xiaochao","avatar":""},{"name":"Wei Shio","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
