INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nay-co-bong-ma-tren-pho-mong-ao', 'Đêm Nay Có Bóng Ma Trên Phố Mộng Ảo', 'Haunted Street', 'null', 'https://phimimg.com/upload/vod/20231013-1/8c513f7762e1368f2eac15ba3dad60fd.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Một đạo diễn thường xuyên gặp ác mộng và liên tục bị quấy rầy bởi những cơn đau đầu hẹn gặp một số nhà biên kịch để thảo luận về kịch bản. Các biên kịch đã đến, nghe nhà sản xuất kể câu chuyện mà đạo diễn đã cho mọi người tham khảo, anh kể câu chuyện rằng chỉ cần bạn ném tiền vào bát sắt của mẹ chồng ăn xin sẽ có may mắn, nhưng nhân vật chính dần không thích mẹ chồng vướng víu. Sau khi câu chuyện được kể lại, đạo diễn đã đến, và ông cảm thấy rằng tất cả mọi người trước mặt ông dường như quen thuộc. Các nhà biên kịch kể câu chuyện của riêng họ, các đạo diễn sửa đổi chúng, và những câu chuyện ngày càng trở nên bí ẩn hơn... Lúc này, một người phụ nữ mặc đồ đỏ tham gia vào ghế mà không được mời, và một nhà biên kịch ngay lập tức kể một câu chuyện khủng khiếp khác với cô là nữ anh hùng. Nghe xong, cơn đau đầu của đạo diễn càng tăng lên, càng ngày anh càng cảm thấy mọi thứ dường như đã quen thuộc, mặc dù anh muốn rời đi, nhưng anh lại bị một câu chuyện khác thu hút ở lại, câu chuyện cuối cùng cũng được kể, đạo diễn rất hài lòng, mọi người vui vẻ ra về, nhưng tai nạn lặng lẽ giáng xuống đạo diễn...</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zuo Jing","avatar":""},{"name":"Li Jie","avatar":""},{"name":"Qiu Xiaowen","avatar":""},{"name":"Liu Qingfeng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324398);
