INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ceo-that-vong', 'CEO Thất Vọng', 'Frustrated CEO', 'null', 'https://phimimg.com/upload/vod/20231013-1/d699e861cfc5b1c9662f263012f87d08.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tề Trần đáng thương đã gặp Triệu Linh Linh thế hệ thứ hai giàu có vì mâu thuẫn với cha mình, với sự giúp đỡ của Triệu Linh Lăng, Tề Trần đã có được sự đầu tư của cha Triệu Linh Linh là Triệu Tấn và trở thành chủ tịch của công ty, nhưng sau khi có tiền, anh ta bắt đầu không thích Triệu Linh Linh và bị ám ảnh bởi Xiao San Fang Xue, và sau khi trải qua sự phá sản của công ty và sự nổi loạn của tất cả người thân, cuối cùng anh ta đã ăn năn, và với sự giúp đỡ của người ăn xin nhỏ, vượt qua trước khi phá sản, nhưng, dưới âm mưu của Kiều Tử Văn, bàn tay đen đằng sau hậu trường, Tề Trần một lần nữa không có gì...</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Yu","avatar":""},{"name":"Zhang Mo","avatar":""},{"name":"Xia Meng","avatar":""},{"name":"Huang Jian","avatar":""},{"name":"Liu Huixiu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
