INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-chuot-manh-me', 'Dưa Chuột Mạnh Mẽ', 'Powerful Cocumber', 'null', 'https://phimimg.com/upload/vod/20231013-1/2e96bd5df3f24398051b729caefab891.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Là một thanh niên nông thôn với những ước mơ, Ren Yi đã đi đến thành phố lớn một mình, và trước khi rời đi, ông nội của anh ta đưa cho anh ta một quả dưa chuột và nói với anh ta rằng anh ta chỉ có thể ăn nó khi anh ta bị dồn vào chân tường. Sau đó, sau khi vô tình gặm một quả dưa chuột, anh phát hiện ra bí ẩn, và do đó đã gặp cô gái yêu dấu của mình, một phụ nữ giàu có Tian Luo. Khi anh chuẩn bị thực hiện ước mơ của mình, anh đã bị cản trở bởi tia sét độc ác và chủ nhân của ma thuật đen, Black Cloud, nhưng cuối cùng, với ý chí cá nhân và hiệu ứng ma thuật của &quot;siêu dưa chuột&quot;, anh đã hoàn thành kỳ tích cứu rỗi anh hùng.</span></p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Xu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
