INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-roi-trong-tiem-van-vat', 'Con Rối Trong Tiệm Vạn Vật', 'The Grocery of Everything: The Puppet', 'https://phimimg.com/upload/vod/20231013-1/9c5e1a7f8e1c28fbc414937dbfefce02.jpg', 'https://phimimg.com/upload/vod/20231013-1/e7bcebfe8c8493a1359ec25b4b0b5bc6.jpg', '<p>Mo Wen là một cô gái vừa mới bước vào nơi làm việc. Không có lý lịch và tính cách rụt rè, sự nghiệp, cuộc sống và tình yêu của cô đều gặp khó khăn. Cho đến một ngày, Morven vô tình có được một con rối thần kỳ. Morven làm theo chỉ dẫn, dùng máu để đánh thức con rối, con rối biến thành một &quot;Morven&quot; giống hệt khác. &quot;Morven&quot; này đã thể hiện tài năng, năng lực và sự quyến rũ mà Morven không có, đồng thời giành được sự ưu ái của ông chủ cho Morven. , sự ngưỡng mộ của đồng nghiệp, tình yêu của nam thần... Cuộc sống của Mặc Văn từ đó trở nên vô cùng thú vị. Bởi vì Mowen bị ám ảnh bởi tất cả niềm hạnh phúc và phù phiếm mà con rối đã giành được nên cô không thể không liên tục đánh thức con rối. Cuối cùng, sự tự nhận thức của con rối đã thức tỉnh, nó không còn hài lòng với việc trở thành người thay thế nữa và quyết định thay thế Morven. Thế giới của Morvin bắt đầu phát triển thành một tình thế nguy hiểm, giữa Morvin và những con rối, một cuộc chiến sinh tử bắt đầu!</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
