INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bac', 'Con Bạc', 'Gambler Sanchun', 'https://phimimg.com/upload/vod/20231013-1/b3d98594a4e4d1cd9ffc60ac4aeade60.jpg', 'https://phimimg.com/upload/vod/20231013-1/aad5469356ac1cc5f7870bc4ea8e5286.jpg', '<p>Wang Sanchun, một chàng trai lương thiện đến từ nông thôn, luôn không sẵn lòng thỏa hiệp trong hôn nhân, anh cảm thấy mình phải tìm được người mình thích trước khi kết hôn, anh cũng tin tưởng chắc chắn rằng một ngày nào đó anh sẽ gặp được nữ thần của mình. Trong một khoảnh khắc vô tình, Wang Sanchun đã bị mê hoặc bởi Chen Yan đột nhiên xuất hiện. Lão Mao là bạn thời thơ ấu của Vương Tam Xuân, hắn cho rằng thật nực cười khi Vương Tam Xuân rủ hắn sang làng bên chơi trò lừa, kiếm tiền để theo đuổi các cô gái, tuy nhiên, Lão Mao cuối cùng cũng đồng ý với Vương Tam Xuân vì hắn không thể từ chối tình anh em của họ.. Hành vi gian lận bị phát hiện và Lão Mao bị đâm càng củng cố quyết tâm rửa tay của Lão Mao Jinpen. Sau khi Lão Mao nghỉ việc, Vương Sanchun và Ermaohou lại đi chơi tiền, nhưng cuối cùng họ phát hiện ra rằng anh ta đã mất hết tiền ở nhà và mắc nợ rất nhiều kẻ cho vay nặng lãi. Đúng lúc Vương Tam Xuân đang tuyệt vọng thì tin dữ ập đến Hết người này đến người khác Đến, mèo già chết, mẹ chết, Bạch Thu Hà kết hôn, Vương Tam Xuân đi vào ngõ cụt...</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
