INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-re-cua-toi-la-mot-not-ruoi', 'Con Rể Của Tôi Là Một Nốt Ruồi', 'My Son-in-law Is A Mole', 'https://phimimg.com/upload/vod/20231013-1/42eb870214105aae939ad0563a021701.jpg', 'https://phimimg.com/upload/vod/20231013-1/423c36eb1a4458118681afa928a7ad1c.jpg', '<p>Ông trùm Fang Dafu sợ tập đoàn của mình sẽ không có người thừa kế nên đã tìm mọi cách để tìm con rể cho con gái Fang Keer nhưng lại rơi vào bẫy của em trai Fang Ergui, người đang cố gắng tìm kiếm con rể. giành quyền lực trong nhóm. Tốt nghiệp đại học Xu Enyuan đến nhà Fang Dafu để xin con rể để trả thù cho cha mình, dưới hàng loạt âm mưu của Fang Ergui và con trai ông ta, Xu Enyuan đã giành được sự công nhận của Fang Dafu và Fang Keer. Ngay khi âm mưu của Fang Ergui và con trai sắp thành công, Xu Enyuan biết được sự thật về cái chết của cha mình, và lương tâm của anh phát hiện ra rằng anh đã quay lưng lại với Fang Ergui và con trai ông. Vì cảm giác tội lỗi cũng như vì lý tưởng và theo đuổi của bản thân, Xu Enyuan cuối cùng đã chọn cách trốn tránh hôn nhân. Fang Keer, người đã yêu Xu Enyuan, đã bỏ đi sự kiêu ngạo của mình và kiên trì theo đuổi Xu Enyuan. lời phàn nàn</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
