INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-toc-xam', 'Cô Dâu Tóc Xám', 'The Grey Hair Bride', 'https://phimimg.com/upload/vod/20231013-1/b58435b4f74020286b6593087f801b2c.jpg', 'https://phimimg.com/upload/vod/20231013-1/b0fd9de137436788e5d9c2f3725b578e.jpg', '<p>Cui Li, một người đàn ông trung niên, đã bị bỏ tù sau khi làm ai đó bị thương vì Su Hua, một cô gái nông thôn lên thành phố làm việc. Để trả ơn Cui Li, Su Hua sẵn sàng làm người phụ nữ của anh và đợi anh ở bên ngoài. Không ngờ Su Hua lại bị mỹ nam Wu Minghao lừa tiền và tình dục ở ngoài, sau khi Cui Li ra tù, anh không thể chịu đựng được nữa buộc phải giải cứu cô lần nữa, khiến Cui Li phải vào tù lần thứ hai. thời gian! Tô Hoa già đi chỉ sau một đêm trong cảm giác tội lỗi và tự trách mình tột độ...</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
