INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-noi-bat', 'Cô Gái Nổi Bật', 'The Spotlight Girl', 'https://phimimg.com/upload/vod/20231013-1/4c709ef700e177e150ce532dbedcd5b9.jpg', 'https://phimimg.com/upload/vod/20231013-1/eec3140f5b96f997f0b1fd1a61948838.jpg', '<p>Phim kể về Kang Pingjia, một người về nông thôn để trải nghiệm cuộc sống cùng thầy và các bạn cùng lớp, họ vô tình gặp được cô gái quê Zhang Xue. Dưới ảnh hưởng của hành vi yêu đương của Zhang Xue, họ bị ảnh hưởng sâu sắc. Sau đó, họ theo Zhang Xue và làm nhiều việc tốt ở quê, lúc này họ cũng hiểu thế nào là từ thiện và yêu thương.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
