INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-noi-bat', 'Cô Gái Nổi Bật', 'The Spotlight Girl', 'cô gái nổi bật the spotlight girl  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-vung-ve', 'Cô Gái Vụng Về', 'Awkward Girl', 'https://phimimg.com/upload/vod/20231013-1/ce15002dfddfda035714968373e75095.jpg', 'https://phimimg.com/upload/vod/20231013-1/9099c8cd94b70bfd9b959365805b4f9d.jpg', '<p>Jiang Yuchen thành lập Công ty Huanyu, quyết tâm đổi mới công nghệ và điều chỉnh xu hướng photoshop quá mức trong thế giới người nổi tiếng trên Internet, quảng bá ứng dụng phát sóng trực tiếp Huajiao và tập trung vào các chương trình phát sóng trực tiếp thực sự mà không cần trang điểm. Qiao Xiaoqiao có kỹ năng PS xuất sắc, cô đã yêu Jiang Yuchen từ lâu nên đã cùng Jiang Yuchen bắt đầu công việc kinh doanh của riêng mình. Là một thành viên của thế hệ giàu có, Jiang Yuchen có quá nhiều phụ nữ xinh đẹp xung quanh anh, Qiao Xiaoqiao luôn hy vọng rằng cô sẽ trở nên xinh đẹp và thu hút sự chú ý của Jiang Yuchen. Vào ngày này, Qiao Xiaoqiao bị sét đánh và biến thành một thiếu nữ xinh đẹp ngay lập tức. Cô ấy dường như đã đến bên Jiang Yuchen, nhưng cô ấy chưa bao giờ có thể đến gần trái tim của Jiang Yuchen ... Bởi vì Qin Yaqi phải lòng Jiang Yuchen nên cô ấy đã cản trở cô ấy và gây ra hiểu lầm giữa hai người. Nhưng chính vì điều này, sau khi hóa giải hiểu lầm, Qiao Xiaoqiao đã hiểu ý định của Jiang Yuchen, hóa ra trước đây cô đã bỏ qua rất nhiều manh mối, còn Jiang Yuchen vẫn luôn thích cô... Hai người trở thành người yêu và cuối cùng kết hôn. và ứng dụng phát sóng trực tiếp Huajiao cũng thành công rực rỡ. , Qiao Xiaoqiao được mọi người coi là &quot;nữ thần PS&quot; và là nữ thần duy nhất của Jiang Yuchen.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
