INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-quai-vat-tuyet-dep', 'Công Chúa Quái Vật Tuyệt Đẹp', 'The Stunning Monster Princess', 'null', 'https://phimimg.com/upload/vod/20231013-1/2179f6dc7200bc5342b2b562b0e49784.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim này kể về câu chuyện của người đàn ông nữ toàn năng Giang Thục đến Tây Chu của thời gian và không gian song song, nhưng biến thành một cơ thể đàn ông, không chỉ bị vướng vào tình yêu bởi Daji dai dẳng và ám ảnh nhất, mà còn tham gia vào cuộc tranh chấp Tây Chu, Giang Thục có tính cách thô bạo nhưng tốt bụng và hài hước, Daji khăng khăng đòi tình yêu, Zhou Gongrende cống hiến cho đất nước, Wuying chịu đựng và hy sinh vì tình yêu, Wu Xian nham hiểm và ích kỷ và cuối cùng không đạt được gì, thông qua sự vướng mắc của các nhân vật khác nhau, kể một câu chuyện thay thế nhưng sâu sắc.</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zuo Anna","avatar":""},{"name":"Cai Rui","avatar":""},{"name":"Cheng Zihan","avatar":""},{"name":"Guangshuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
