INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-em-nong-bong-dung-co-bo-chay', 'Cô Em Nóng Bỏng, Đừng Cố Bỏ Chạy', 'Honey, I demand your love', 'null', 'https://phimimg.com/upload/vod/20231013-1/e1b0d1575ce515a62bfc8f74de2c27ca.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Su Nuannuan, một cô gái dân sự, là thành viên của bộ phận kiểm tra kỷ luật của Cục Nội vụ. Cô ấy tốt bụng, chính trực và dũng cảm, và, tất nhiên, một chút đơn giản. Thẩm Vũ là con trai giàu có, là đội trưởng điều tra hình sự của Cục Nội vụ, anh ta đẹp trai kiêu ngạo, lưỡi độc và bụng đen. Có vẻ như hai người ở hai thế giới khác nhau đã bắt đầu vướng vào tình cảm vì một danh sách trừng phạt. Thẩm Vũ đuổi theo Tô Niệm Niên để hủy bỏ hình phạt, nhưng trong quá trình đó, anh thật sự thích Tô Nhuận Niên, nhưng Tô Nhuận Niên không những không nhận ra mà còn đứng tên anh họ sau cái chết của anh họ Tôn Mạnh Á. Tô Niệm Niên không nhận ra rằng cô đã chân thành với Thẩm Vũ từ lâu. Tuy nhiên, Thẩm Vũ vẫn biết cái chết của Mạnh Á có liên quan đến chú của Tô Nhược Niên, Tô Niệm Niên cũng biết hôn sự của Thẩm Vũ từ lâu đã trở thành công cụ cho hôn nhân gia đình. Hai người hiểu lầm nhau, nhưng họ quan tâm đến nhau. Nhưng cuối cùng, tất cả họ đều lộ lòng, tin tưởng lẫn nhau, tìm ra kẻ giết người thực sự của Mengya, và cũng sử dụng tình yêu để thoát khỏi số phận của hôn nhân gia đình.</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Yiwen","avatar":""},{"name":"Xu Ding","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
