INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ty-sat-thu', 'Công Ty Sát Thủ', 'Guns and Talks', 'null', 'https://phimimg.com/upload/vod/20231013-1/e67bdfa1c9a80b3c037c6ce9fd47ece4.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Dazhi và Quan Yong thành lập công ty giết người anh em, và sau một số thất bại, hai anh em đã thành công trong việc thực hiện &quot;lệnh giết&quot; đầu tiên do Boss Gao cung cấp. Thật không may, người ta phát hiện ra rằng mục tiêu là mang thai bảy tháng. Cả hai không đồng ý về việc có nên giết hay không, và cuối cùng quyết định loại bỏ đứa trẻ. Họ đã đến một văn phòng nha sĩ tư nhân đã sinh ra trái tim của họ, nhưng nha sĩ không thể loại bỏ đứa bé vì đứa trẻ quá lớn. Để tránh áp lực của ông chủ cao và tránh bi kịch một xác chết và hai mạng sống, Dazhi đã bí mật lập danh sách tù nhân, và Dazhi đã lên kế hoạch cho một trò hề trộm cắp cửa hàng tiện lợi, và không may đã thay đổi công việc và làm việc tại cửa hàng tiện lợi này. Kế hoạch bỏ tù của Dachi đã thất bại, và khi hai người trở lại văn phòng nha sĩ một lần nữa, họ phát hiện ra rằng cả người phụ nữ mang thai và nha sĩ đã chết một cách bi thảm, và còi báo động đến từ xa và gần...</span></p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Xiaodong","avatar":""},{"name":"Wang Biao","avatar":""},{"name":"Ye Xinxin","avatar":""},{"name":"Lin Xue","avatar":""},{"name":"Zhao Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
