INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giao-my-nhan', 'Cơ Giáo Mỹ Nhân', 'The Hybrid Beauty', 'https://phimimg.com/upload/vod/20231013-1/f6c22c1024c93b4b996a90ab3446aa5b.jpg', 'https://phimimg.com/upload/vod/20231013-1/6bf6fbf9cef84e9785795d8aabd562d1.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Năm 2050, một viện nghiên cứu khoa học đã thiết lập một loại kế hoạch nghiên cứu thông minh mới &quot;Người mẫu đơn&quot; và xác định nguyên mẫu thử nghiệm dự án thông qua một cuộc thi sắc đẹp công cộng; Nhưng tại một thời điểm quan trọng trong nghiên cứu, người ta thấy rằng nguyên mẫu đã được &quot;chuyển giao&quot;, vì vậy một cuộc cạnh tranh giữa âm mưu và trí thông minh, lòng tham và công lý chính thức bắt đầu... Sau nhiều trận chiến và trí tuệ, thiện và ác đã được đền đáp, và tôi nghĩ rằng vấn đề đã kết thúc; Tuy nhiên, một thể xác, hai tâm hồn, nữ chính rơi vào sự lựa chọn tình cảm, tình yêu gia đình...</span></p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Lanxin","avatar":""},{"name":"Li Yuanjie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
