INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-ngay', '28 Ngày', '28 Days', 'https://phimimg.com/upload/vod/20231013-1/c6bc3df8440a66422a60313d35bd7c9e.jpg', 'https://phimimg.com/upload/vod/20231013-1/c183da62f84c93de115f905a6592f1cb.jpg', '<p>Một cô gái trẻ có ước mơ nghệ thuật đã trở thành người nổi tiếng live-stream An Lili. Sau khi chọc giận sếp và vội vàng bỏ chạy, cô vô tình gặp rắc rối với doanh nhân trẻ Qin Shun và bị các tay săn ảnh bắt gặp. Cô trở thành &quot; bạn gái của một gia đình giàu có&quot; và gây chú ý. Một mối quan hệ yêu đương bất ngờ được phơi bày trước công chúng, một cuộc sống mới đang đến, lúc này, một chàng trai trẻ mặc áo sáng và ngựa giận dữ Qin Shun trở thành người đầu tiên trong mối quan hệ này. Điều sắp thay đổi không chỉ là mối quan hệ giữa hai người</p>', 'Full', 1, 'single', 'completed', 15, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Judy Sun","avatar":""},{"name":"Yin Yasen","avatar":""},{"name":"Yu Xiaobin","avatar":""},{"name":"Wang Boyuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
