INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('28-ngay', '28 Ngày', '28 Days', '28 ngày 28 days judy sun yin yasen yu xiaobin wang boyuan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-havoc', 'AI Havoc', 'AI Havoc', 'null', 'https://phimimg.com/upload/vod/20231013-1/85b2c094e399624720fe8f1a0acf624a.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Khái niệm tế bào thần kinh xuất phát từ cách bộ não con người hiểu mọi thứ: sự kết nối giữa các tế bào thần kinh. Mục tiêu cuối cùng của trí tuệ nhân tạo là sử dụng máy móc để đạt được tất cả các chức năng của bộ não con người, và vì đơn vị tế bào nhỏ nhất của não người, tế bào thần kinh, là điểm khởi đầu tốt nhất.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Zheng Hao, con trai duy nhất của người đàn ông giàu nhất tỉnh T, miền nam Trung Quốc, đang ở độ tuổi đôi mươi và vừa trở về sau khi học tại một trường đại học nổi tiếng ở Mỹ. Trên thực tế, tốt hơn là nói rằng đó là trở về từ du học, tốt hơn là nói rằng đó là bỏ học và quay trở lại.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Giống như một số người thế hệ thứ hai giàu có không làm kinh doanh, cuộc sống của Trịnh Hạo ở Trung Quốc là dành nhiều ngày để uống rượu, khoe khoang sự giàu có và xa xỉ, điệu nhảy Yingfei Yan và gây rắc rối.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trịnh Hạo giàu có và đẹp trai là bất khả chiến bại trong lĩnh vực tình yêu, và cô gái anh ta thích chỉ có thể ngoan ngoãn phục tùng. Ở nơi gió và trăng nơi những người hâm mộ vàng say sưa, Trịnh Hạo giống như một huyền thoại đêm đen tối, khiến vô số cô gái đổ xô đến đó và chiêm ngưỡng nó.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tuy nhiên, vào ngày này, Trịnh Hạo đã hơi choáng ngợp khi đối mặt với một cô gái thực sự từ chối anh. Điều này không thể chấp nhận được đối với Trịnh Hạo, lòng tự trọng của anh đã bị tổn hại rất nhiều. Anh ta thề sẽ hạ gục cô gái, bất kể anh ta sử dụng phương pháp nào.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Một chiếc xe tải lao tới với tốc độ nhanh, Trịnh Hạo ở bên đường chưa kịp né tránh thì đã bị đâm thẳng vào người. Trời tối một lúc, nước trái cây và máu hiến trộn lẫn khắp mặt đất...</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Khi Trịnh Hạo tỉnh lại, anh đã quên mất mình là ai. Tôi không biết chuyện gì đã xảy ra trước đây. Tất cả những gì anh ta biết là anh ta không có tay hay chân, và khuôn mặt của anh ta bị biến dạng. Trịnh Hạo hoàn toàn suy sụp, hắn muốn tự sát, đáng tiếc, hắn thậm chí còn không có khả năng tự sát. Bác sĩ Lý Đông Nam trước mặt nói với anh rằng không phải là không thể phục hồi như trước, mà là tham gia vào một &quot;kế hoạch tái sinh trí tuệ nhân tạo&quot; tuyệt mật...</span></p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lu Junyan","avatar":""},{"name":"Chen Saisai","avatar":""},{"name":"Han Haoxuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
