INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-la-meo', 'Anh Ấy Là Mèo', 'He Is Cat', 'null', 'https://phimimg.com/upload/vod/20231013-1/d969c325e51924204f2420931ac9eea2.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">&quot;He is a Cat&quot; là một bộ phim trực tuyến được sản xuất bởi Beijing Shangge United Culture Media Co., Ltd., đạo diễn bởi Zou Pengcheng, Sun Shubo, Chen Lin và Sun Jingwei. Trong phim, họa sĩ hoạt hình Wu Mingxue đã tạo ra một bộ truyện tranh tình yêu giả tưởng &quot;He is a Cat&quot;, nội dung câu chuyện kể rằng Wu Mingxue, tác giả truyện tranh bất đắc dĩ, bắt đầu một cuộc sống chung vô lý với anh ta vì anh ta vô tình giải cứu và nhận con quỷ mèo &quot;Flower Wheel&quot;, và mối quan hệ giữa shemales là bí mật. Và nam thần hoàn hảo muốn đưa tác phẩm mới của Wu Mingxue lên màn ảnh, sự theo đuổi quyết liệt của Li Ming đối với Wu Mingxue, đã khiến cô rơi vào một mối tình tay ba dường như sáo rỗng. Ngay khi phát hiện ra mình thực sự yêu Huaren, cô vô tình biết rằng cái chết của cha mình có liên quan đến sự thật rằng nữ hoàng quỷ mèo (Concubine Shufei) đã bị phong ấn một ngàn năm trước. Hóa ra Hua Lun và Li Ming đã tiếp cận Wu Mingxue để lấy máu tình yêu đích thực của con cháu Wu Clan để mở khóa kỹ thuật &quot;say rượu&quot; đã phong ấn Nữ hoàng Quỷ mèo trong hàng ngàn năm.</span></p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Shubo","avatar":""},{"name":"Chen Lin","avatar":""},{"name":"Sun Jingwei","avatar":""},{"name":"Liu Yufei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
