INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-buu-xong-phung-thien-chi', 'Anh Bưu Xông Phụng Thiên Chi', 'A Pigman''s Battle Against The Invaders', 'null', 'https://phimimg.com/upload/vod/20231013-1/126eee44eae97c5c15427122a51fa4ad.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Meng Xiang, người đang cố gắng nuôi lợn để kiếm tiền cưới con dâu và vợ hưu trí, đã bị máy bay của quân xâm lược Nhật nổ tung để giết chết một số con lợn mà ông đã làm việc chăm chỉ để nuôi, và giấc mơ của ông đã tan vỡ. Sau khi tìm kiếm cảnh sát địa phương nhưng không thành công, anh ta đi vào thành phố để tìm anh họ Huang Er, cũng là một cảnh sát. Là một sĩ quan cảnh sát, Huang Er không muốn trở thành kẻ phản bội, và sau khi chứng kiến sự hy sinh của Quân tình nguyện chống Nhật để thu giữ các loại thuốc quý, anh ta đã giấu thuốc. Sau khi Mạnh Tường vào thành, hắn mới biết Hoàng Nhĩ đã bị giam cầm, dựa vào cảm giác mê đắm và không sợ hãi, sau một trận chiến dũng cảm, hắn đã giải cứu thành công Hoàng Nhĩ khỏi ngục giam. Sau đó, anh em gặp hàng ngũ tình nguyện viên. Bằng trí thông minh và bản lĩnh của mình, cả hai đã đột nhập vào bệnh viện, uống thuốc, đột nhập vào đồn cảnh sát, bắt giữ tù trưởng và cuối cùng giết chết thủ lĩnh đội ma hung ác với sự hợp tác của các tình nguyện viên và đồng nghiệp yêu mến Nhật Bản, đồng thời bàn giao thành công thuốc cho các tình nguyện viên.</span></p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Long","avatar":""},{"name":"Zhang Jiahao","avatar":""},{"name":"Cheng Hong","avatar":""},{"name":"Mao Mao","avatar":""},{"name":"Rừng dương","avatar":""},{"name":"Tống Tiểu Phong","avatar":""},{"name":"Quan Tingna","avatar":""},{"name":"Ôn Song","avatar":""},{"name":"Vương Kim Long","avatar":""},{"name":"Tôn Hiểu Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324398);
