INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lac-loi', 'Anh Hùng Lạc Lối', 'Lost Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/db00011a6925d2b8197ab648c9e9a432.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nhân vật chính, Han Cheng, một đối thủ hạt giống có hy vọng mạnh mẽ thi đấu tại Vòng chung kết võ thuật tổng hợp quốc gia, bị thương chân phải trong quá trình tập luyện chuyên sâu trước trận đấu và không thể thi đấu được nữa. Hàn Thành từ đó đến nay sa sút, bị anh trai Cao dụ dỗ đánh bạc, mở sòng bạc ngầm, Hàn Thành nợ một khoản nợ cờ bạc khổng lồ, anh trai bắt Hàn Thành phải trả nợ cờ bạc, đồng thời, con gái ông cũng cần chi phí y tế cao vì bệnh bạch cầu, Hàn Thành vay tiền khắp nơi, không ai nguyện ý cho hắn mượn. Hàn Thành vô tình đâm vào hiện trường của một nhóm tội phạm khác đang đấu đá nội bộ do chia sẻ hàng hóa bị đánh cắp không đồng đều, và nhặt được số tiền bị đánh cắp, Anh Cao và những kẻ giết người của nhóm tội phạm tìm thấy Hàn Thành cùng một lúc, Hàn Thành phải chiến đấu với hai thế lực tà ác, cuối cùng, tà ác không trấn áp chính nghĩa, và các thế lực tà ác đều bị bắt. Hàn Thành cũng bừng tỉnh, trở về sân huấn luyện quen thuộc để làm huấn luyện viên.</span></p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Guoqing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
