INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-ngoai-hanh-tinh', 'Anh Hùng Ngoài Hành Tinh', 'Alien Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/1bb8a66e0240c599aea1a11bae67f013.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nhà lãnh đạo ngoài hành tinh biết rằng cơ thể năng lượng tồn tại trên Trái đất để có được cơ thể năng lượng. Người lãnh đạo gửi quả bóng đến Trái đất để tìm ra nơi ở của cơ thể năng lượng và bắt giữ cơ thể năng lượng. Sau khi Qiu Qiu đến Trái đất, anh tình cờ biết rằng cơ thể năng lượng đang ở bên cạnh Four Eyes. Anh ta bắt đầu tiếp cận Four Eyes và những người khác, và như một người bạn, anh ta đang ẩn nấp xung quanh Four Eyes và những người khác. Dần dần, dưới sự quan hệ của mọi người, quả cầu đất dần dần phát hiện ra rằng con người có một trái tim nhân hậu. Tôi bắt đầu cảm thấy rằng tôi không nên tiếp tục phạm sai lầm như thế này, và tôi bắt đầu dao động. Người lãnh đạo không bao giờ nghe tin tức từ anh ta, vì vậy anh ta đã gửi Eggman đến Trái đất để điều tra. Eggman quyết định tự mình giải quyết vấn đề, và một vài người bắt đầu một chuyến đi hài hước và ly kỳ. Hai người quyết định từ bỏ, và ngay khi mọi người nghĩ rằng họ có thể làm hòa, kẻ giết người ngoài hành tinh đã chiếm hữu Xiaomei và bắt đầu một trận chiến khốc liệt. Cho đến thời điểm này, mọi người đều biết rằng cơ thể năng lượng là em gái của Four Eyes, và em gái quyết định rời đi với việc giết người ngoài hành tinh vì lợi ích của cuộc sống của anh trai mình, và cuối cùng Four Eyes đã được giải cứu, nhưng cô và em gái đã bị tách ra kể từ đó.</span></p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Xiaoqiao","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
