INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-chien-dau', 'Anh Hùng Chiến Đấu', 'Fighter Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/291711ef973852fb1ae848097a05a404.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về câu chuyện của vua quyền anh Mo Man và con gái. Cựu vương quyền anh Mo Man bị đóng khung và giết chết đối thủ trên võ đài. Sau đó, anh ta bị kết án tù, nhưng cuối cùng sau khi ra ngoài, anh ta không dám nhận ra con gái của mình. Anh ta làm nhân viên bảo vệ địa phương và đi cùng con gái, và phát hiện ra rằng con gái mình là một kẻ móc túi và một tên trộm. Anh tiếp cận cô như một người bạn và chỉ đường cho cô. chỉ để thấy rằng cô ấy đã bị cuốn vào một sự cố liên quan đến ma túy, và để bảo vệ con gái mình, Mo Man bắt đầu trở thành kẻ thù của cả thế giới...</span></p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Yeer","avatar":""},{"name":"Lan Zhiyi","avatar":""},{"name":"Chen Zhi","avatar":""},{"name":"Wei Xiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
