INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-hang-yeu', 'Tế Công Hàng Yêu', 'The Incredible Monk', 'null', 'https://phimimg.com/upload/vod/20231013-1/108a6220a59563fbdc544ddb10930830.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ma lực Cửu Công trong truyền thuyết vô biên, quỷ và quái vật không dám khuấy động phiền phức, chỉ có quỷ nước thỉnh thoảng hành động ở Càn Giang, dùng lũ lụt xâm lấn vào người dân. Một ngày nọ, những con quái vật nước hợp lực hành động như những con quái vật, lật qua ngàn lớp sóng lớn, thẳng đến những ngôi nhà, cuộc sống bị hủy hoại, những con quái vật nước không thể tha thứ, biến thành một vòi rồng quái dị, và thề sẽ nuốt chửng thế giới; Trong tuyệt vọng, người anh hùng hạ xuống, và Jigong phá vỡ không trung, đánh bại con quỷ nước xuống đất với đà sấm sét. Nghĩ rằng từ nay về sau khi thế giới hòa bình, nhưng phát hiện ra rằng Dapeng Bird đang âm mưu chinh phục ba cõi người, thần và quỷ, Jigong đã tìm thấy Ngọc Hoàng với sự trợ giúp của đứa trẻ tiên béo và ra lệnh, triệu tập Erlang God, Lei Zhenzi, Nezha, Cửu Thiên Huyền Nô và Fuhu Luohan đi đến thế giới phàm trần để hạ thấp quỷ và quỷ, phương pháp chiến đấu quỷ tiên kinh thiên động địa, trong tai họa này đến tai họa khác, có một cuộc khủng hoảng trên thế giới bị thế giới quỷ cấm. Là Dao Gao Yizhang hay Demon Gao Yizhang?</span></p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Haomin","avatar":""},{"name":"Lin Zicong","avatar":""},{"name":"Zhong Jiufu","avatar":""},{"name":"Zou Wenzheng","avatar":""},{"name":"Chen Guokun","avatar":""},{"name":"Ye Jinghan","avatar":""},{"name":"Jin Kong","avatar":""},{"name":"Wang Jing","avatar":""},{"name":"Luo Jiaying","avatar":""},{"name":"Yang Neng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
