INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lien-minh', 'Anh Hùng Liên Minh', 'Hero League', 'null', 'https://phimimg.com/upload/vod/20231013-1/1ba84e5e58b1524822f8863b187fafd1.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nhà cờ bạc của quận đã náo nhiệt nhiều ngày, bởi vì một thanh niên phải thắng mọi cờ bạc đã đến. Một ngày nọ, một cậu con trai đẹp trai muốn thử kỹ năng đánh bạc với Ah Tianbi. Chàng trai đẹp trai rời đi mà không đánh bạc. Ah Tian, người thắng tiền, đi đến nhà thổ để tìm niềm vui, và cậu bé đẹp trai đột nhiên chém ra và chém vào Ah Tian, dễ dàng bị Ah Tian né tránh. Chàng trai điển trai là một cô gái tên A Xiang, cô tò mò rằng Ah Tian sẽ thắng mỗi khi đánh bạc, hóa ra Ah Tian có một đôi mắt ma khi học võ dưới sự hướng dẫn của Master Nebula</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Fan","avatar":""},{"name":"Hao Yuyu","avatar":""},{"name":"Zhao Xiaorui","avatar":""},{"name":"Shi Xiaoman","avatar":""},{"name":"Zhang Bohao","avatar":""},{"name":"Lee Sung-hsiung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
