INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-tu-nhan', 'Anh Hùng Tư Nhân', 'Private Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/af6a77226d214fbb7982b186d781bc1a.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong thế giới tội phạm tràn lan, có một thị trấn nhỏ duy nhất không có tội phạm, trấn Thái Bình, không có tên xã hội đen nào dám bước vào trấn Thái Bình, và thị trấn Thái Bình đã trở thành thiên đường trong tâm trí mọi người. Wu Zhengyi, người lớn lên nghe truyền thuyết của thị trấn Taiping, luyện tập chăm chỉ mỗi ngày và quyết tâm trở thành một thành viên của các anh hùng của thị trấn Taiping. Với sự giúp đỡ của ông Xiong (nữ), ông chủ của trung tâm &quot;Cứu tinh công lý&quot;, Wu Zhengyi đã vượt qua thành công cuộc đánh giá anh hùng của thị trấn Taiping, và trong quá trình thực thi công lý, anh ta phát hiện ra rằng Taiping Town thực sự là một tên xã hội đen thực sự đàn áp người dân vì những ham muốn ích kỷ của chính mình, và ông trùm lừa đảo không đáng tin cậy Mr. Xiong đã thực sự bảo vệ kẻ yếu. Wu Zhengyi, người nhận ra sự thật, đã hợp tác để bí mật giúp đỡ mọi người, ông Xiong (nữ), đánh bại cô LinkedIn, anh hùng tư nhân của thị trấn Thái Bình.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Dong","avatar":""},{"name":"Wang Qing","avatar":""},{"name":"He Panpan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
