INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-truyen-tranh', 'Anh Hùng Truyện Tranh', 'Comic Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/491c7d30fc46a2bdcbdec057f9637170.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ngôi trường truyện tranh nơi Dragon City làm việc đã giao cho mọi người một bài tập về nhà truyện tranh: vẽ những hành động anh hùng của gia đình. Bởi vì cha mẹ bận rộn với công việc trong một thời gian dài và không thể gặp gia đình của họ, họ biết rất ít thông tin, khi Dragon City bất lực, lấy cảm hứng từ em gái Long Zinuo, cả hai đã sử dụng trí tưởng tượng của mình để tạo ra một câu chuyện anh hùng với những thăng trầm, và giành được giải thưởng, điều này cho thấy việc bảo vệ và trau dồi trí tưởng tượng của trẻ em là rất quan trọng, và các anh chị em có thể phát huy hết lợi thế này, điều này cũng đáng để học hỏi từ trẻ em. Mặt khác, hai đứa trẻ thể hiện hình ảnh năng lượng tích cực của cha mẹ đóng góp cho xã hội thông qua truyện tranh, Long Xu và Song Meiling biến thành những đặc vụ chính nghĩa, để bảo vệ cây bút ma thuật được truyền từ thế hệ này sang thế hệ khác trong gia đình, và chiến đấu với thế lực tà ác của xã hội đen, những đứa trẻ cũng sử dụng trí tuệ của mình để giúp mọi người vượt qua nguy hiểm, và sau nhiều lần đảo ngược và khó khăn, cuối cùng mọi người đã cùng nhau hợp tác để tiêu diệt các thế lực xấu xa.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Chunzhong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
