INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-va-tinh-yeu', 'Âm Mưu Và Tình Yêu', 'Intrigue And Love', 'null', 'https://phimimg.com/upload/vod/20231013-1/fb14b04880e03a8db15440fcd086eedd.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong thời kỳ Kiến Văn, trưởng lão của Phù Đông Phong đã ra lệnh cho Chu Công Quân đánh cắp võ công đến bảo vật Phong ấn Thanh Thiên vào thứ tư và đổ lỗi cho &quot;tà giáo&quot; Cửu Ngàn Hiên. Tùy Nguyên Ninh, chưởng môn phái của Cửu Ngàn Hiên Viên, là một chiến sĩ liều lĩnh, Cửu Vạn Hiên dưới sự khống chế của hắn rất xuất sắc, chủ trương độc dược mà một mình hành động.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Vào thời điểm đó, sẽ có bốn &quot;cô gái quỷ&quot; có hành động kỳ lạ và đi ra khỏi thanh kiếm bị đánh, ba trong số đó là cô gái piano, cô gái độc và cô gái quỷ của Cửu ngàn gian hàng, và người cuối cùng có một nơi ở bí ẩn, được gọi là &quot;Tiên Rakshasa&quot; Zhou Congjun. Trong quá trình điều tra vụ trộm Phong Ấn Thanh Thiên, Tùy Nguyên Ninh liên tục bí mật đánh nhau với Chu Công Quân, kết quả là hai người gặp đối thủ, có ấn tượng tốt với nhau.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Chu Công Quân đã cản trở cha ruột của cô khi ông chiến đấu với Tùy Nguyên Ninh, và cô đã cứu Sui Yuanning, nhưng đã bị Wednesday Absolute giết nhầm và chết vì ngọc. Công việc kinh doanh vất vả của Wednesday đã bị hủy hoại, danh tiếng của ông bị hủy hoại, cô con gái duy nhất của ông qua đời, và ông mất lòng và phát điên dưới nhiều cú đánh. Thứ tư đã biến mất trong sông hồ kể từ đó, võ công đối với bảo vật Thanh Thiên Âm và Kiếm Công Tông trở về vị trí ban đầu, Cửu Ngàn Hiên cuối cùng cũng được xóa bỏ oán hận.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qin Xiaofei","avatar":""},{"name":"Zhuang Xiaotong","avatar":""},{"name":"Yu Zhong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
