INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-vang-can-khon-cua-niet-tieu-sanh', 'Ấn Vàng Càn Khôn Của Niết Tiểu Sảnh', 'The Fox Spirit And The Golden Seal', 'null', 'https://phimimg.com/upload/vod/20231013-1/23cf1fb4a633009e6754e39b639f17cc.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tu sĩ Đạo giáo Yan Chixia và học giả Ning Caichen, để thoát khỏi bà ngoại quỷ cây và giải cứu Nie Xiaoqian, người phải chịu sự cai trị của bà ngoại, đã chiến đấu với bà ngoại của mình với tất cả các chiến binh trong chùa Lanruo, vô tình kích hoạt sức mạnh thần thánh thời gian và không gian của Con dấu vàng Qiankun, được truyền đến ngày nay bởi Golden Seal. Yến Trì Hạ, Ninh Cải Trần và Niếp Tiểu Thiên, đến thời hiện đại, cứu nữ chính Nguyên Viên khỏi tay quỷ, ba người tạm thời định cư ở nhà Viên Viên, nhưng lại mang đến rất nhiều phiền toái cho Viên Viên. Ở phía bên kia, bà nội và quỷ rắn đến thời hiện đại cùng nhau lên kế hoạch sử dụng sức mạnh thần thánh của Phong ấn vàng Qiankun trong một nỗ lực vô ích để di chuyển đền Lanruo đến thời hiện đại và biến thế giới thành thiên đường cho quỷ. Yến Trì Hạ và Viên Viên không hề biết rằng bọn họ đã tiến vào âm mưu lớn của bà nội. Cuối cùng, Viên Viên hy sinh bản thân để ngăn chặn kế hoạch xấu xa của bà nội. Và Yến Trì Hạ ôm lấy Nguyên Viên đã chết rồi biến mất trên bầu trời đêm. Nhiều năm sau, Yan Chixia, người đã sống trong xã hội hiện đại trong một thời gian dài, gặp một cô gái cảm thấy rằng anh ta quen thuộc, và cô gái đó trông giống hệt như Yuanyuan.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tang Sting","avatar":""},{"name":"Song Bolin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
