INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asura-tam-mat-chin-o-khoa', 'Asura Tám Mặt : Chín Ô khóa', 'Eight-faced Asura : Nine Locks', 'null', 'https://phimimg.com/upload/vod/20231013-1/c08d6157f3928dcfcc8478b4838988c7.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Áo-Hung đã bị đánh bại và tan rã trong Thế chiến I, sĩ quan thất bại Karl và chuyên gia thuốc súng Marie đã phát triển một quả bom với chín nội tạng, và quyết định sử dụng quả bom để giết tất cả các quan chức Đồng minh ở Trung Quốc trong một cú sà xuống.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lu Yantuan","avatar":""},{"name":"Luo Chenshu","avatar":""},{"name":"Chang Xiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
