INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-nguoi-may-cua-toi', 'Bạn Gái Người Máy Của Tôi', 'My Robot Girlfriend', 'null', 'https://phimimg.com/upload/vod/20231013-1/b5d3db35ad2e0310bb1d8bbb15907d78.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Năm 2048, Cao Xiaoming đã dành cả cuộc đời để tạo ra robot Xiaoxia, dịch chuyển tức thời Xiaoxia đến năm 2018. Tất cả những điều không may xảy ra sau đó, và Cao Tiểu Minh, người sống một cuộc sống cô đơn như thế này, đột nhiên gặp được người trong đời vào sinh nhật lần thứ 22 của cô. Sự xuất hiện của Tiểu Hạ đã phá vỡ hoàn toàn cuộc sống của Tào Hiểu Minh, đối với cô gái ngây thơ, ngốc nghếch và dễ thương này. Tào Hiểu Minh bị đánh bại, trái tim chàng trai tràn đầy, cuối cùng anh ta cũng nhận lấy cô gái, quyết định giúp cô tìm gia đình, với mối quan hệ với Tiểu Hạ, Tào Tiểu Minh dần dần nảy sinh tình cảm với cô, nhưng sau khi thân phận thật sự của Tiểu Hạ bị bại lộ, điều đó đã khiến Tào Tiểu Minh trở nên choáng ngợp...</span></p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Lijun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324398);
