INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-dao-mong', 'Bác Sĩ Đạo Mộng', 'Doctor Dream', 'null', 'https://phimimg.com/upload/vod/20231013-1/48d3c2dd5584d2403271374d77a67609.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Mạnh Lệ, một cô gái vừa trở về Trung Quốc, tâm thần rối loạn vì sợ hãi quá mức, cô luôn nhìn mọi thứ theo hướng ngược lại, và bị người đàn ông áo đen đuổi giết chết, với sự giúp đỡ của hai người bạn tốt, họ tìm thấy bác sĩ Lý của tâm lý học, không ngừng giải quyết bí ẩn và sự thật, và cuối cùng họ tìm thấy một kết quả đáng kinh ngạc...</span></p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xin''er","avatar":""},{"name":"Wang Huan","avatar":""},{"name":"Zheng Zhongyu","avatar":""},{"name":"Liu Biao","avatar":""},{"name":"Zhao Zihan","avatar":""},{"name":"Lý Trấn An","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324398);
