INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ten-ngoc-huyet-chien-giang-ho', 'Ba Tên Ngốc Huyết Chiến Giang Hồ', 'Three Idiots Brotherhood', 'null', 'https://phimimg.com/upload/vod/20231013-1/8293e1b64955792960246262af4fb2f5.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim &quot;Ba trận chiến đẫm máu ngu ngốc ở sông hồ&quot; bắt đầu với cảnh ba anh em Haochuan, Dadong và A Qiang vào thành phố để chiến đấu. Cường phản bội anh em Hạo Xuyên và Đại Đông vì phụ nữ và lợi ích, và bị điều khiển bởi khói độc của Anh Sói. Anh Sói là một người chuyên nghiệp, để thống trị thế giới cho chính mình, anh ta bắt đầu tấn công ông chủ trước đó là Đào Diệp, để Đạo Diệp cũng hút thuốc lá có chứa ma túy. Hạo Xuyên biết tình huống của A Khương, muốn dẫn đầu cho A Khương, uy hiếp sư huynh Sói. Nhưng để A Cường cân nhắc, Hạo Xuyên không dám gọi cảnh sát, anh không muốn anh trai mình bị cảnh sát bắt, nhưng điều này lại khiến anh Sói càng căm ghét Hạo Xuyên hơn. Cường không có gì. Anh Sói tìm được Cường, hy vọng có thể dọn sạch Hạo Xuyên kiêu ngạo, hứa hẹn một số điều kiện, Cường vốn là người có lòng sói thật sự đồng ý. Cường lại một lần nữa phản bội anh trai. Cường và anh Sói nghĩ ra một âm mưu để Hạo Xuyên cứu Michelle, sau đó họ hoàn toàn có thể dọn sạch Hạo Xuyên. Có thể Hạo Xuyên lấy lại tình huynh đệ.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Ge","avatar":""},{"name":"Bao Chi","avatar":""},{"name":"Sun Shulei","avatar":""},{"name":"Shi Yunhao","avatar":""},{"name":"Lu Chang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
