INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-da-hiep', 'Bạch Dạ Hiệp', 'The Knight In The White Night', 'null', 'https://phimimg.com/upload/vod/20231013-1/18417cdb7b9b29ea2206bf958a731184.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong triều đại nhà Minh, súng hỏa mai Đông Đình đã cố gắng xâm chiếm Đồng bằng Trung tâm, và chính phủ triều đình đang gặp nguy hiểm. Diao Baiye được hoàng đế ra lệnh đi sông hồ tìm bí mật võ thuật có thể đánh bại súng hỏa mai, Diao Baiye đã vượt qua mọi khó khăn, và cuối cùng đã hoàn thành nhiệm vụ của mình, thành công tìm ra bí mật và đánh bại Ngự lâm quân Đông Đình</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xie Miao","avatar":""},{"name":"Nansheng","avatar":""},{"name":"Huang Yishan","avatar":""},{"name":"He Wenhui","avatar":""},{"name":"Chen Yiming","avatar":""},{"name":"Leung Ka Yan","avatar":""},{"name":"Tiểu Na Ngô","avatar":""},{"name":"Tieying Zhao","avatar":""},{"name":"Làng tuyết","avatar":""},{"name":"Norman Chu","avatar":""},{"name":"Dick Wei","avatar":""},{"name":"Junni Cao","avatar":""},{"name":"TRẦN KHẢI","avatar":""},{"name":"Thiên Khai","avatar":""},{"name":"Trương Mai Duệ","avatar":""},{"name":"Dạy biển tạo ra tiếng ồn","avatar":""},{"name":"Yuan Pengwei","avatar":""},{"name":"Shi Zhonghe","avatar":""},{"name":"Lý Bình An","avatar":""},{"name":"Vua Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
