INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-mon-ngu-giap', 'Bạch Môn Ngũ Giáp', 'The Mystical Treasure', 'null', 'https://phimimg.com/upload/vod/20231013-1/cc397a7d4a7c68514daac6fd94c5fb2f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Ge Zhen trẻ tuổi (do Yuan Bu thủ vai) là một dự bị của Mười hai đội quân Hắc ám của Cục Quân sự bí mật của Vương quốc Che Chi, sử dụng mật danh là Mười hai cung hoàng đạo của Chi nhánh Trái đất để thực hiện các nhiệm vụ mặt tối theo lệnh của triều đình. Ge Zhen học theo Weiyang trong Mười hai đội quân Hắc ám, và anh ta đã học được các kỹ năng của Cổng Trắng và đuổi theo các nghi phạm ở khắp mọi nơi. Trong quá trình điều tra với người cung cấp thông tin Lão Ba, anh gặp trưởng xưởng thêu màu đỏ Huakui Okra (do Hạ Dương thủ vai). Okra sinh ra ở Khotan và có khả năng dự đoán tương lai trong giấc mơ của mình. Cô mơ thấy anh trai mình bị Tiêu Béo giết chết, bị Ge Zhen theo dõi, vì vậy cô lo lắng nhờ đối phương giúp đỡ, và trong quá trình đó, cô cũng có một trái tim dành cho anh hùng trẻ tuổi này. Đồng thời, người đàn ông bí ẩn xâm nhập vào Vương quốc Chế Chi và sử dụng ma thuật tà ác để giết Wuma, đội quân mạnh nhất trong mười hai đội quân hắc ám. Một cuộc chiến giữa thiện và ác là không thể tránh khỏi...</span></p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuan Bu","avatar":""},{"name":"Xia Yang","avatar":""},{"name":"Wen Dongjun","avatar":""},{"name":"Zheng Yafei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324398);
