INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-doi-ba-muoi-bay-do', 'Bạn Đời Ba Mươi Bảy Độ', '37 Degree''s Love', 'null', 'https://phimimg.com/upload/vod/20231013-1/28e23273ed37d7853b08755fc2e12ddd.jpg', '<p>Phim kể về Jiang Xiao Qing, một phụ nữ xinh đẹp sinh vào những năm 1990 làm nghề mai táng, tình tiết phim thăng trầm, gay cấn, dịu dàng và cảm động. Jiang Xiao Qing là một người đẹp được các bạn cùng lớp và bạn bè công nhận. Cô gặp và yêu một chàng trai tốt bụng không kém trong trại trẻ mồ côi, cô cũng là cô con gái tốt nhất trong mắt cha mình. Mọi thứ thật đẹp... Tuy nhiên, Danh tính của cô gái dần dần được công khai, và bản chất nghề nghiệp đặc biệt của cô khiến người bình thường không thể hiểu được, thậm chí còn bị người thân, bạn bè từ chối. Sự phản đối của cha, khoảng cách của các bạn cùng lớp và sự bối rối của bạn trai đã khiến Jiang Xiao Qing phải chịu áp lực tinh thần về gia đình, tình bạn và tình yêu, tuy nhiên, cô không bao giờ lơ là công việc và diễn giải sự thiêng liêng, vĩ đại của nghề này bằng sự chân thành và tình yêu. . Người bạn trai cũng dần nhận ra sự vĩ đại trong sự nghiệp của cô gái và quyết tâm giành lại cô gái. Thông qua câu chuyện phản ánh bản chất con người, bộ phim phát huy năng lượng tích cực, phản đối những tư tưởng ngu dốt của mê tín phong kiến, là tác phẩm tâm hồn gắn kết gia đình, tình bạn, tình yêu và hơi ấm tình người khác.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Niu Xiaodi","avatar":""},{"name":"Zhao Zedong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
