INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-ghen-cua-toi', 'Bạn Gái Ghen Của Tôi', 'My Jealous Girlfriend', 'null', 'https://phimimg.com/upload/vod/20231013-1/1178e3affe30baf238aa45f6b7dbb4ef.jpg', '<p>Xiaogang ở tại một khách sạn bên bờ biển để viết phác thảo cho một bộ phim truyền hình du lịch, và bạn gái Jona đã đến gặp anh. Bên cạnh Xiaogang là ông chủ Mou Qing và bạn gái Xiaoyu. Tiểu Vũ mặc bikini đi bơi ở bãi biển, biết được Mộ Thanh muốn đi cùng người yêu khác một vòng, tức giận ngăn cản, Mộ Thanh trốn ra khỏi nhà, Tiểu Vũ đuổi ra ngoài không đuổi kịp, gió thổi cửa đóng lại, cô phải trốn trong phòng Tiểu Cương, muốn mượn một chiếc khăn choàng lớn, vừa lúc Jona đến, cô lập tức làm đổ bình giấm! Cho dù Tiểu Cương có giải thích thế nào, Jona cũng không tin, không nghĩ rằng mình đã phản bội tình yêu. Mở phòng riêng của bạn và sống một mình. Ngày hôm sau khi bọn họ đang chơi đùa bên bờ biển, Tiểu Cương thấy Jona luôn phớt lờ mình mà bỏ đi, Jona lầm tưởng cậu sẽ đến Tiểu Vũ, vội vã trở về khách sạn, gõ cửa Tiểu Du tìm kiếm, nghe thấy động tĩnh trong phòng tắm, Jona vội vàng chạy vào, nhưng nhìn thấy Mục Thanh đi vệ sinh. Sau một cốt truyện hài hước và lố bịch, Jona cuối cùng đã nhận ra rằng mọi thứ đều là sự nghi ngờ của cô là một con ma đen tối. Vì vậy, cô và Tiểu Cương đã quay lại với nhau...</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hu Xin","avatar":""},{"name":"Huang Tianyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
