INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-ban-do-luan-hoi', 'Địch Nhân Kiệt : Bản Đồ Luân Hồi', 'Di Renjie : The Painting Of Samsara', 'null', 'https://phimimg.com/upload/vod/20231013-1/cc7d7527acab8bed6c7385221f2c3624.webp', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Kể về câu chuyện Di Renjie vừa vào chùa Đại Lý được một tháng, điều tra một vụ án giết người và băm nhỏ, nhưng trong hiện trường vụ án tưởng chừng nhạt nhẽo, một mô hình bí ẩn đột nhiên xuất hiện. Nhưng ngay khi Di Nhậm Kiệt chuẩn bị điều tra sâu, lại bị cấp trên phản đối, điều này càng khiến hắn nghi ngờ, phía sau hậu trường hẳn là có một bàn tay đen to hơn.</span></p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Haixiang","avatar":""},{"name":"Sang Taihua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
