INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-trieu-chau', 'Bang Triều Châu', 'Tycoon', 'null', 'https://phimimg.com/upload/vod/20231013-1/5af5764c54fb7c2b29976d059519f5c3.webp', '<p>&quot;Chiến đấu đến cùng giữa gian khổ&quot;, câu này là phương châm của người Triều Châu! Tuy nhiên, làm thế nào để bạn đối phó với cái chết đột ngột của một người cha đã bị ghẻ lạnh với bạn trong nhiều năm, và ông giao phó cho bạn trách nhiệm của người kế vị? Zheng Kun, được gọi là &quot;Chú Kun&quot;, ban đầu là một ông trùm Hồng Kông. Một đêm nọ, Zheng Kun bị giết chết dã man tại nhà, và sau khi anh ta chết, cả nhóm trở nên hỗn loạn. Không ai ngờ rằng Trịnh Côn đã lập di chúc trước khi chết: bàn giao tất cả công việc kinh doanh của công ty cho con trai út Trịnh Sen, người đã bị ghẻ lạnh trong nhiều năm.<br/></p><p>Trong quá trình Trịnh Sen tiếp quản, ông hồi tưởng về kinh nghiệm kinh doanh của cha mình khi ông còn trẻ, và ông đã giải quyết hết cuộc khủng hoảng này đến khủng hoảng khác. Cùng lúc đó, quá khứ với gia đình dần hiện lên trong tâm trí, Trịnh Ân cảm thấy mình và cha bị tách rời nhau. Dần dần, anh bắt đầu hiểu cha mình, người bị ghẻ lạnh với anh mà không có lý do. Tuy nhiên, một cuộc khủng hoảng lớn đang dần đến gần, gây nguy hiểm đến tính mạng của mọi người trong gia đình Zheng... Trịnh Sen phải xoay chuyển tình thế và chiến đấu đến cùng với tinh thần của người Triều Châu!</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Hao","avatar":""},{"name":"Guo Tao","avatar":""},{"name":"Marseille","avatar":""},{"name":"Shi Junzhe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324398);
