INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-cu-xau-xa', 'Bạn Trai Cũ Xấu Xa', 'Bad Ex-Boy Friend', 'null', 'https://phimimg.com/upload/vod/20231013-1/b78ae25bb77cff7bedc57d6a8c958739.webp', '<p>Trong phim, nam chính Chu Đà vì thể hiện tình yêu với các cô gái trong làng, nhưng tất cả đều bị từ chối một cách thảm hại, anh bị sốc, anh quyết tâm khám phá con đường yêu mạnh mẽ nhất trên thế giới, vì vậy anh dấn thân vào một con đường dài để tìm kiếm một giáo viên, và cuối cùng dưới sự dạy dỗ của &quot;người thật đa tình&quot;, anh đã luyện tập chăm chỉ ngày đêm, tái sinh và trở thành một bậc thầy tình yêu, sau khi đọc vô số phụ nữ, anh đã gặp nữ chính, và sau khi thử mọi cách có thể để giúp người học việc của mình theo đuổi một người, anh đã phản thói quen, để gặp tình yêu đích thực, quyết định thay đổi những sai lầm trong quá khứ của mình, khi mọi thứ dường như đã được giải quyết, Nhưng có một vấn đề nan giải mới, sông hồ rất nguy hiểm, tình yêu đích thực rất khó tìm, và sớm muộn gì nó cũng sẽ phải được trả lại.</p>', 'Full', 1, 'single', 'completed', 13, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sui Cunyi","avatar":""},{"name":"Wu Xuanxuan","avatar":""},{"name":"Sun Yang","avatar":""},{"name":"Li Yifan","avatar":""},{"name":"Fu Gang","avatar":""},{"name":"Ge Youyuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
