INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-kinh-di-truoc-khi-ngu', 'Chuyện Kinh Dị Trước Khi Ngủ', 'Bedtime Horror Stories', 'https://phimimg.com/upload/vod/20231012-1/526b8575877e0cf048dfeee72cadb762.jpg', 'https://phimimg.com/upload/vod/20231012-1/63bfdb0ea881e05cc92d98e85db29671.jpg', '<p>Cina, một cô gái mất cha mẹ từ khi còn nhỏ, bỏ nhà đi và làm việc trong một tiệm cắt tóc ở một thị trấn nhỏ, cô mắc chứng rối loạn giấc ngủ dẫn đến mất ngủ và vô tình biết được tin dữ rằng bà ngoại , người mà cô nương tựa cả đời, đã qua đời, và cô bắt đầu có những ảo tưởng, đối mặt với con quỷ bên trong không thể tránh khỏi cảm giác tội lỗi về bà mình, Cina đã chọn cách tự tử. Lúc này, trái tim ngây thơ và nhân hậu của tuổi thơ đã hướng dẫn cô ôn lại những ký ức trước đây, Cinna đã hiểu được ý nghĩa thực sự của tình yêu và cuộc sống, và cuối cùng đã chuộc lỗi cho chính mình.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324398);
