INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nong-mau', 'Anh Em Nóng Máu', 'Warm Blodd Brothers', 'https://phimimg.com/upload/vod/20231012-1/5a6c00b8383b9b7641a4cb4c1a7cd34b.jpg', 'https://phimimg.com/upload/vod/20231012-1/35d42481f8473408671ef532de288171.jpg', '<p>Ba anh em tốt bụng cùng lớn lên ở làng cùng nhau lên thành phố làm việc. Để thực hiện sự trả thù lý tưởng của mình, hai anh em bất ngờ được trao cơ hội biểu diễn trong một quán bar, và hai anh em nhanh chóng trở nên nổi tiếng ở địa phương nhờ tài năng diễn xuất mạnh mẽ. Khi ham muốn vật chất tràn ngập cuộc sống của anh em, giữa anh em nảy sinh khoảng cách, sau này bị kẻ ác lợi dụng và anh em chia tay nhau. Sau khi trải qua những thăng trầm của cuộc đời, anh em muốn hiểu rằng điều quan trọng là tình anh em hơn là danh lợi. Cuối cùng, sự hiểu lầm đã được giải quyết và hai anh em cùng hợp tác để trừng phạt những kẻ bất lương và tìm ra con người thật của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Mingzan","avatar":""},{"name":"Lin Aofei","avatar":""},{"name":"Hu Chongyang","avatar":""},{"name":"Cui Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
