INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-hoang-gia-zhan-zhao', 'Bảo Vệ Hoàng Gia Zhan Zhao', 'A Case Of A Missing Cat', 'https://phimimg.com/upload/vod/20231012-1/bc3036ff35245223b96fd7a679609b1e.jpg', 'https://phimimg.com/upload/vod/20231012-1/3084fc77440427ef7db9ab740e1ab04d.jpg', '<p>&quot;Royal Cat Zhan Zhao&quot; kể câu chuyện về cận vệ hoàng gia Zhan Xiong Fei, người bị giáng chức xuống huyện Qionglu xa xôi với tư cách là quan huyện, tuy nhiên, không lâu sau khi anh đến nơi, một vụ án mạng đã xảy ra trong quận. Bao Xiaobao, con trai của huyện lệnh và Zhan Xiongfei ngay lập tức thành lập một đội thám tử để giải quyết vụ án trong thời hạn trước khi đội kiểm tra Imperial City đến. Không ngờ mọi chuyện ngày càng mất kiểm soát, cái chết xảy ra thường xuyên, cả hai rơi vào mạng lưới âm mưu khổng lồ do kẻ sát nhân dệt nên.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Daotie","avatar":""},{"name":"Kaixiang Chen","avatar":""},{"name":"Hou Tianfang","avatar":""},{"name":"Liu Jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324398);
