INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-anh-hung-va-nam-anh-hung-moi', 'Bảy Anh Hùng Và Năm Anh Hùng Mới', 'New Seven Heroes and Five Gallants', 'https://phimimg.com/upload/vod/20231012-1/05ce3c1c65259afe5fe12ce2ec758d8f.jpg', 'https://phimimg.com/upload/vod/20231012-1/d4e3980d9aee9ebe1844e0e3540abab8.jpg', '<p>Bộ phim &quot;Vụ án giết rồng mới của bảy anh hùng và năm chính nghĩa&quot; kể về câu chuyện của Song Renzong Tiansheng năm năm trước, chàng trai trẻ Bao Chửng nhậm chức ở Bắc Kinh, nhưng anh ta lại vướng vào một vụ án kỳ quái và bí ẩn khi du hành đến Bắc Kinh. huyện Kiến Xương. May mắn thay, trên đường đi, họ đã gặp Zhan Zhao, &quot;Anh hùng phương Nam&quot; và Bai Yutang, &quot;Jin Mao Rat&quot;. Ba người tuy còn trẻ nhưng cũng không giấu được khí chất hào hiệp. Trong quá trình ba người điều tra từng bước, những dấu hiệu kỳ lạ đã xảy ra - trong một ngôi đền đổ nát, xác chết đã &quot;hồi sinh&quot;... Trước tình thế nguy hiểm, để cứu thi thể của Bai Yutang Zhan Zhao Ai bị thương nặng, Bao Chửng khi nào mới có thể hiểu được vụ án phức tạp này? Zhan và Bai có thể được giải cứu thành công không?</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiao Meng","avatar":""},{"name":"He Qi Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324398);
