INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nham-mat-thay-mua-he', 'Nhắm Mắt Thấy Mùa Hè', 'Summer in Closed Eyes', 'https://phimimg.com/upload/vod/20231012-1/308ea18180dc0695a108f1939a28e858.jpg', 'https://phimimg.com/upload/vod/20231012-1/2722680a7a7aa3f69c752612bd73f800.jpg', '<p>Nhắm Mắt Thấy Mùa hè là hành trình tâm lý của hai nhân vật, kể về tình yêu của hai bạn trẻ người Nhật và Việt khác biệt về ngôn ngữ, văn hoá. Đan xen vào đó là những tình cảm gia đình, cha con. Những con người có xuất phát điểm khác nhau nhưng hội tụ cùng nhau tại thị trấn Higashikawa và viết lên câu chuyện với thông điệp mang đậm hơi thở cuộc sống.</p>', 'Full', 1, 'single', 'completed', 14, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Phương Anh Đào","avatar":""},{"name":"Takafumi Akutsu","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Noriko Takimoto","avatar":""},{"name":"Norihiro Takimoto","avatar":""},{"name":"Ben Pham","avatar":""},{"name":"Diễm Thy","avatar":""},{"name":"Mizuki Miyauchi","avatar":""},{"name":"Sayaka Mitsuta","avatar":""},{"name":"Akira Hatsusegawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
