INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-lang', 'Song Lang', 'Song Lang', 'https://phimimg.com/upload/vod/20231012-1/7d0fcc4f8e27759b62a662a532e1341c.jpg', 'https://phimimg.com/upload/vod/20231012-1/f033ff62b96e621ab3a5145f9dd0011f.jpg', '<p>Phim mở đầu với những tự sự về cải lương, quá khứ của nhân vật Dũng &quot;Thiên Lôi&quot;. Anh vốn sinh ra trong gia đình có truyền thống nhạc dân tộc nhưng do thời cuộc mà trở thành kẻ đòi nợ thuê. Mọi chuyện thay đổi kể từ khi Dũng gặp Linh Phụng - kép hát xem nghề diễn như hơi thở.</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Isaac","avatar":""},{"name":"Lien Binh Phat","avatar":""},{"name":"Thanh Tú","avatar":""},{"name":"Ron Vuong","avatar":""},{"name":"Phuoc Tinh","avatar":""},{"name":"Vu T. Le Thi","avatar":""},{"name":"Minh Phương","avatar":""},{"name":"Huynh Ngoc","avatar":""},{"name":"Bao Chau Nguyen","avatar":""},{"name":"Kiều Trinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324398);
