INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-vo-cho-ba', 'Tìm Vợ Cho Bà', 'Bride for Rent', 'https://phimimg.com/upload/vod/20231012-1/fe1670019c123a67f47051567e19c7f1.jpg', 'https://phimimg.com/upload/vod/20231012-1/0157c0ef340da16963ec84aa5ddfb7ae.jpg', '<p>Để được thừa kế khối tài sản kếch xù của bà nội, Long đã quyết định cùng Linh - một cô gái đang gặp khó khăn về tài chính thực hiện một kế hoạch bí mật. Thế nhưng, mọi chuyện không dễ dàng như anh tưởng tượng...&nbsp; Long là một công tử nhà giàu đang vướng vào một món nợ khổng lồ với bọn giang hồ. Trong lúc nguy nan, anh chợt nhớ đến khối tài sản được kế thừa từ bà nội vào tuổi 25. Trớ trêu thay, muốn được như ý Long phải chấp nhận điều kiện cưới vợ.&nbsp; Không bỏ cuộc, anh chàng đã gặp và cùng Linh - cô gái cũng đang có những rắc rối về tiền bạc - xây dựng một thỏa thuận bí mật. Liệu kế hoạch của Long có thành công?</p>', 'Full', 1, 'single', 'completed', 19, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Sơn Thạch","avatar":""},{"name":"Thanh Hằng","avatar":""},{"name":"Jang Mi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
