INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tim-vo-cho-ba', 'Tìm Vợ Cho Bà', 'Bride for Rent', 'tìm vợ cho bà bride for rent sơn thạch thanh hằng jang mi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sao-sieu-ngo', 'Siêu Sao Siêu Ngố', 'Super Star Super Silly', 'https://phimimg.com/upload/vod/20231012-1/deb264fba1c37561597eb8c2d87d7004.jpg', 'https://phimimg.com/upload/vod/20231012-1/7368fe8cbbf9589281c2c084aa46d3ff.jpg', '<p>Siêu Sao Siêu Ngố là bộ phim hài tình cảm, với sự xuất hiện của danh hài Trường Giang cùng lúc đóng hai vai. Thế Sơn và Thế Tùng là hai anh em sinh đôi bị chia cắt vì cha mẹ chia tay. Người anh Thế Sơn sống cùng cha, trở thành một ngôi sao nổi tiếng với hàng triệu người hâm mộ. Người em Thế Tùng thì an phận nuôi heo ở quê nhà. Khi công việc bận rộn đến mức không có thời gian để nghỉ ngơi, Thế Sơn được ông bầu Tony Dũng (Đức Thịnh) “cố vấn” thuê em trai trở thành thế thân, đảm nhiệm những dự án nhỏ. Sau nhiều lần “làm mình làm mẩy”, Thế Tùng cũng đồng ý giúp đỡ anh mình. Thế nhưng, những mâu thuẫn và rắc rối cũng dần nảy sinh bởi tính cách hai anh em quá khác nhau. Thế Sơn là người cẩn trọng, đứng đắn trong khi Thế Tùng lại rất vui vẻ và ham chơi. Không dừng lại ở đó, căng thẳng giữa hai anh em ngày càng trở nên nghiêm trọng hơn khi Thế Tùng nảy sinh tình cảm với cô bạn gái của anh mình.</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trường Giang","avatar":""},{"name":"Sam","avatar":""},{"name":"NSƯT Đức Thịnh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
