INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-gai-mua', 'Em Gái Mưa', 'Once Upon a Rain', 'https://phimimg.com/upload/vod/20231011-1/f5fb8a71c8d2386089d02ef6f9da7446.jpg', 'https://phimimg.com/upload/vod/20231011-1/8d5a368a309ed855e6c91deb92363823.jpg', '<p>Câu chuyện lấy bối cảnh những năm đầu 2000 về Nguyễn Hà Vy, cô nữ sinh lớp 12A1 trường trung học Thanh Xuân tưởng chừng như sẽ &quot;kết thúc hời học sinh trong nhạt nhẽo&quot; mà không có lấy cho riêng mình một “kỷ niệm sâu sắc” nào thì bỗng gặp được thầy Minh Vũ trong đoàn giáo sinh đến trường thực tập.</p>', 'Full', 1, 'single', 'completed', 18, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Thùy Linh","avatar":""},{"name":"Mai Tài Phến","avatar":""},{"name":"Phương Anh Đào","avatar":""},{"name":"Tiến Vũ","avatar":""},{"name":"Việt Hương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
