INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-doi-chong', 'Kế Hoạch Đổi Chồng', 'Husband Swap', 'https://phimimg.com/upload/vod/20231011-1/7ddf8958dd44d6955090f10f9cd30f76.jpg', 'https://phimimg.com/upload/vod/20231011-1/12bdec8ff3d28f716a61348912fa2cce.jpg', '<p>Đến với Kế hoạch đổi chồng của điện ảnh Việt, hai nhân vật chính là đôi trẻ Quân (Quang Đăng) và Dung (Hoàng Yến Chibi). Sau một lần tình cờ gặp nhau tại sân bay, cả hai nảy sinh tình cảm và sớm đi đến quyết định hôn nhân.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Quang Đăng","avatar":""},{"name":"Trương Thanh Long","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
