INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-con-o-dau', 'Mặt Trời, Con Ở Đâu', 'My Son, Where are You?', 'https://phimimg.com/upload/vod/20231011-1/48b2e28da92107516fa6dc64aaba5176.jpg', 'https://phimimg.com/upload/vod/20231011-1/87147cee98fa3d675b715d69b275730c.jpg', '<p>Là câu chuyện kể về những diễn biến xoay quanh bé Á (Bảo Bảo) – con trai của A Tẻo (Huỳnh Đông). Cuộc sống của hai bố con khá bình yên. Ban ngày, A Tẻo đi bán trái cây, còn cậu bé Á thì nói dối bố là đi học nhưng thực ra lén lút bán vé số kiếm thêm tiền giúp bố. Đến một ngày, Á bị phát hiện có nhóm máu hiếm, trùng khớp với nhóm máu của bé Xuka (Mai Cát Vy) nên đã bị bắt cóc. Những tình tiết sau đó đi vào một lối mòn&nbsp;</p>', 'Full', 1, 'single', 'completed', 16, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Bảo Bảo","avatar":""},{"name":"Huỳnh Đông","avatar":""},{"name":"Mai Cát Vy","avatar":""},{"name":"Bảo Khương","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
