INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-nien-nguy-hiem', 'Thanh Niên Nguy Hiểm', 'Hazy Youth', 'https://phimimg.com/upload/vod/20231010-1/7b4b07f6b8d1c55b2def9e16ba70afcf.jpg', 'https://phimimg.com/upload/vod/20231010-1/f633174b1cc0d81677b632b8dc51bc15.jpg', '<p>Bốn doanh nhân trẻ tổ chức một cuộc họp trong công ty và nhớ lại thời sinh viên của họ, khi đó Zhao Xiaofeng vẫn còn là một tay xã hội đen và thường bắt nạt các bạn cùng lớp của mình, sau đó Zhao Xiaofeng bị những người trẻ tuổi trong xã hội bắt nạt và nhận được sự giúp đỡ từ Wu Zehao, Chen. Weixing và những người khác. Wu Zehao, mẹ mất sớm và cha bỏ nhà đi, được bà ngoại nuôi dưỡng, cha mẹ Chen Weixing quanh năm làm việc ở nơi khác và được ông nội nuôi dưỡng. Cha mẹ Liu Wenjing ly hôn và sống với mẹ anh. xuất sắc, và một số trải nghiệm cảm động đã xảy ra cùng nhau và anh ấy dần dần trở thành một doanh nhân.</p>', 'Full', 1, 'single', 'completed', 12, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Haibing","avatar":""},{"name":"Xu Xiaoqin","avatar":""},{"name":"Du Hongjun","avatar":""},{"name":"Liu Zhenyou","avatar":""},{"name":"Zhao Tiange","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
