INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-thi-tran', 'Bí ẩn thị trấn', 'Mystery of the Town', 'https://phimimg.com/upload/vod/20231009-1/88c590b4b0dd206b364fd92ca976c350.jpg', 'https://phimimg.com/upload/vod/20231009-1/9bb7b3b9dbb8ccc7456039119cbb3f4e.jpg', '<p>Đoàn Thiên Minh, thiếu gia nhà họ Đoàn ở trấn cổ Trung Hoa Dân Quốc bỏ nhà đi vì tham gia cuộc cách mạng lật đổ chế độ phong kiến của nhà Thanh thì bất ngờ nhận được cáo phó báo tin ông nội đã qua đời. Đoàn Thiên Minh đưa bạn gái về nhà dự tang lễ, nhưng bạn gái của cô lại bị một đạo sĩ trong thị trấn gán cho là &quot;quái vật&quot; mang theo khí tức hung ác có thể gây hại cho cả gia đình. Cả gia tộc muốn thiêu chết bạn gái của cậu Duẩn. Lúc này, nhiều chuyện kỳ lạ lần lượt xảy ra. Thi thể của ông nội cậu Duẩn biến mất một cách bí ẩn. Cha của cậu Duẩn cũng chết một cách bí ẩn. Người hầu xinh đẹp lao vào vòng tay của cậu. Tất cả Nghi vấn được giải quyết, bạn gái được cứu an toàn, đè lên người Đoàn Thiên Minh.</p>', 'Full', 1, 'single', 'completed', 17, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fang Xin","avatar":""},{"name":"Tang Fei","avatar":""},{"name":"Lin Hang","avatar":""},{"name":"Quan Chunsheng","avatar":""},{"name":"Xiong Yi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324398);
