INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beo-bat-kha-chien-bai', 'Béo bất khả chiến bại', 'Invincible Fatty', 'https://phimimg.com/upload/vod/20231009-1/0fc47a6036f1caa22b7e7036bc56530f.jpg', 'https://phimimg.com/upload/vod/20231009-1/00e301a776874ad598259f9a9518e60e.jpg', '<p>He Xiongfei là một cậu bé mập mạp, thích nhảy Latin, từng trốn học để học múa Latin và bị cha mình phát hiện, ông rất tức giận. Nhưng He Xiongfei không vì điều này mà bỏ cuộc mà vẫn kiên trì và yêu thích điệu nhảy Latin. Giáo viên dạy múa Latin Yang Nuo đã sắp xếp một bạn nhảy cho Xiaopang, Xinrui, nhưng lúc đầu Xinrui không thích Xiaopang và cho rằng anh ấy thật ngu ngốc. Xiaopang vì điều này mà làm việc chăm chỉ hơn, anh ấy cảm thấy Xinrui ghét anh ấy vì anh ấy nhảy không đẹp. Xinrui cảm động trước hành động của Xiaopang, và sự phản đối ban đầu của cha cô chuyển sang ủng hộ. Để giành chiến thắng trong Cuộc thi khiêu vũ Latin dành cho trẻ em quốc gia, Xiaopang và Xinrui đã tăng cường luyện tập và chuẩn bị cho cuộc thi, tuy nhiên, có ai đó đã bí mật thao túng cuộc thi, cuối cùng Xiaopang và Xinrui đã thua cuộc thi. Tuy nhiên, sự ngây thơ và chăm chỉ của họ lại tràn đầy năng lượng, nhà sản xuất truyền hình Niu Benconscience phát hiện ra rằng anh đã báo cáo câu chuyện mờ ám về việc cha của Tianlong hướng dẫn anh làm giả cuộc thi. Ước mơ khiêu vũ Latin của Xiaopang đã thành hiện thực, đồng thời anh cũng giúp Xinrui thực hiện ước nguyện sang Mỹ tìm mẹ.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Xiongfei","avatar":""},{"name":"Tao Wanqing","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
