INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-bat-chap', 'Yêu Em Bất Chấp', 'Yêu Em Bất Chấp', 'https://phimimg.com/upload/vod/20231007-1/83bc3ec0605f69a19af0273333dd4902.jpg', 'https://phimimg.com/upload/vod/20231007-1/f4f3b5cb334eeadb5b1dc222fc5c467c.jpg', '<p>Giống như các bộ phim remake, Yêu em bất chấp có câu chuyện tổng thể tương đồng với nguyên tác. Minh Khôi (Hoài Lâm) là cậu sinh viên hiền lành, ngô nghê. Trong một lần đi chơi, cậu vô tình gặp mặt Diệu Hiền (Ngọc Thanh Tâm) - cô gái bí ẩn, cá tính và đanh đá, và rơi vào tình huống tréo ngoe.&nbsp; Kể từ đó, mối quan hệ kỳ cục giữa bộ đôi “trai ngoan - gái hư” bắt đầu phát triển, đem đến hàng loạt tình huống bi hài cho khán giả, cũng như dần bóc tách nhiều bí ẩn xung quanh quá khứ đầy ưu tư của Diệu Hiền</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hoài Lâm","avatar":""},{"name":"Ngọc Thanh Tâm","avatar":""},{"name":"Công Dương","avatar":""},{"name":"Ngọc Thảo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324398);
