INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-cu-cuoi', 'Con Cú Cười', 'The Smiling Owl', 'https://phimimg.com/upload/vod/20231006-1/7e8add9e15f95e0ceb92ea92ecaa9005.jpg', 'https://phimimg.com/upload/vod/20231006-1/138db259fc84bf4755ce42812cb8af91.jpg', '<p>Guo Tianhao, một chàng trai trẻ đến từ Trung Quốc đại lục, là một người chăn nuôi động vật. Sau khi vị hôn thê hối hận về cuộc hôn nhân của mình, anh từ chức và đến Hải Nam để tìm kiếm &quot;con cú cười&quot; mà ông nội anh cho rằng khi còn nhỏ là tượng trưng cho hạnh phúc.<br/>Sự xuất hiện của Wu Mengchen, một cô gái bí ẩn như yêu tinh, đã phá vỡ cuộc sống bình thường của Tianhao ở Hải Nam. Tianhao dần dần bị thu hút bởi cô gái dám nghĩ và hành động táo bạo này. Thái độ của cô đối với thiên nhiên và sự tôn trọng cuộc sống đã giải thoát Tianhao khỏi chiếc lồng khép kín của anh. Hai người gặp nhau, quen nhau, biết nhau và yêu nhau, nhưng ngay khi Tianhao quyết tâm lấy hết can đảm để theo đuổi tình yêu thì Mengchen lại biến mất.<br/>Hóa ra Mengchen là một bệnh nhân mắc bệnh XP (xeroderma sắc tố), cô chỉ còn sống được 7.300 ngày (20 tuổi) và không thể nhìn thấy mặt trời. Nhưng để thực hiện lời hứa với Tianhao, cô đã nhìn thấy mặt trời trong lần đầu tiên trong đời, mặt trời mọc cũng khiến tình trạng của anh trở nên trầm trọng và anh sớm qua đời.<br/>Sau khi biết được sự thật, Tianhao quyết định dùng tình yêu để cứu Mengchen. Một đám cưới hoành tráng sắp được tổ chức ở bãi biển nhưng cô dâu lại không xuất hiện...</p>', 'Full', 1, 'single', 'completed', 21, 2018, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Zhishuo","avatar":""},{"name":"Chi Ningning","avatar":""},{"name":"Ou Yuning","avatar":""},{"name":"Yang Chaoran","avatar":""},{"name":"Zhai Xiaoxing","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
