INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-phan-1', 'Siêu Điệp Viên (Phần 1)', 'Tom Clancy''s Jack Ryan (Season 1)', 'https://phimimg.com/upload/vod/20231002-1/8fac6602a5ec7f5a37668b713437332c.jpg', 'https://phimimg.com/upload/vod/20231002-1/12861d7d67429db21417257dd50fb10f.jpg', '<p>Jack Ryan là một chuyên gia phân tích mới toanh của CIA, người sắp bước vào một nhiệm vụ nguy hiểm lần đầu tiên trong đời. Từ những khám phá trong liên lạc giữa bọn khủng bố đã khiến anh chống lại một kiểu khủng bố mới đe dọa hủy diệt toàn cầu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"John Hoogenakker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324398);
