INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gone-are-the-days', 'Gone Are the Days', 'Gone Are the Days', 'https://phimimg.com/upload/vod/20230920-1/d1a345f3a663b6e11a4a815318affd02.jpg', 'https://phimimg.com/upload/vod/20230920-1/09e1ed42c27a13f3a36158d4ea4a7c40.jpg', '<p>Câu chuyện về taylon Flynn khét tiếng, một người đàn ông quyết tâm thoát khỏi cuộc sống này trong ánh hào quang rực rỡ. Kế hoạch của ông trở nên tồi tệ khi phát hiện ra cuộc sống bẩn thỉu mà cô con gái bị ghẻ lạnh của ông buộc phải sống. Để cứu cô, anh phải triệu tập những con quỷ bên trong mà anh đã thanh trừng từ lâu và nhận ra rằng việc cứu chuộc là một con đường khó khăn để đi.</p>', 'Full', 1, 'single', 'completed', 20, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lance Henriksen","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Lulu Wilson","avatar":""},{"name":"Jamie McShane","avatar":""},{"name":"Meg Chambers Steedle","avatar":""},{"name":"Chris Romano","avatar":""},{"name":"Steve Railsback","avatar":""},{"name":"Billy Lush","avatar":""},{"name":"Carter Hastings","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
