INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-nha-sieu-giau-chau-a', 'Con Nhà Siêu Giàu Châu Á', 'Crazy Rich Asians', 'https://phimimg.com/upload/vod/20230919-1/0b4f206688a3802d587275cd2aeb00b8.jpg', 'https://phimimg.com/upload/vod/20230919-1/eb2d0b5bbaee93fa0ab73c01d43f4583.jpg', '<p><span style="font-family: ">Crazy Rich Asians theo chân cô gái người Mỹ gốc Á Rachel Chu cùng bạn trai Nick Young về quê nhà Singapore để dự đám cưới người bạn thân nhất. Khi đến nơi, Rachel sửng sốt khi phát hiện ra bạn trai là con của một trong những gia đình giàu có nhất châu Á, và là một trong những anh chàng độc thân hot nhất Singapore.</span></p>', 'Full', 1, 'single', 'completed', 26, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Constance Wu","avatar":""},{"name":"Henry Golding","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Lisa Lu","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"Chris Pang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
