INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-son-ca', 'Chim Sơn Ca', 'The Nightingale', 'https://phimimg.com/upload/vod/20230917-1/453d1a056c3a79411bb7ae77cb8b2657.jpg', 'https://phimimg.com/upload/vod/20230917-1/b5f0ad06e1c0c2046ea144412c5d6563.jpg', '<p>Năm 1825, Clare, một tù nhân người Ireland 21 tuổi, đuổi theo một người lính Anh xuyên qua vùng hoang dã hiểm trở ở Tasmania, nhằm trả thù cho hành động bạo lực khủng khiếp mà anh ta đã gây ra đối với gia đình cô. Cô nhờ sự phục vụ của một người theo dõi thổ dân, người cũng bị đánh dấu bởi chấn thương từ quá khứ đầy bạo lực của chính mình.</p>', 'Full', 1, 'single', 'completed', 24, 2018, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Aisling Franciosi","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Baykali Ganambarr","avatar":""},{"name":"Damon Herriman","avatar":""},{"name":"Harry Greenwood","avatar":""},{"name":"Ewen Leslie","avatar":""},{"name":"Charlie Shotwell","avatar":""},{"name":"Michael Sheasby","avatar":""},{"name":"Matthew Sunderland","avatar":""},{"name":"Magnolia Maymuru","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324398);
