INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-viet-tinh-ca', 'Mùa Viết Tình Ca', 'Season for Love Songs', 'https://phimimg.com/upload/vod/20230917-1/b6b00861b3e47a0bd47a59412fb3563f.jpg', 'https://phimimg.com/upload/vod/20230917-1/ef6bc1dcf944e58e721bc87d2be2a3e6.jpg', '<p><span style="font-family: ">Mùa Viết Tình Ca là câu chuyện kể về tình yêu âm nhạc của chàng nhạc sĩ trẻ Bảo Trung, được biết đến là gương mặt sáng giá của làng nhạc Việt. Vì chạy theo thị trường âm nhạc, Bảo Trung đã vô tình đánh mất nguồn cảm hứng sáng tác nhạc và phạm phải sai lầm nghiêm trọng. Chính người bạn của Bảo Trung đã vạch mặt anh là “kẻ đạo nhạc” thay vì được mệnh danh là “hit maker”. Trong lúc quá bế tắc và phải chịu đựng quá nhiều sức ép từ phía dư luận, Bảo Trung đã bỏ hết mọi thứ để đến miền biển Mũi Né và tìm gặp người anh em chí cốt Hải Mèo (Hoàng Phi). Cuộc bỏ trốn trở nên rắc rối và cũng “thú vị” hơn khi Bảo Trung đã gặp phải cô nàng thất tình Li Lam (Phan Ngân).</span></p>', 'Full', 1, 'single', 'completed', 25, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Isaac","avatar":""},{"name":"Sunni Hạ Linh","avatar":""},{"name":"Lâm Vinh Hải","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Phan Ngân","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324398);
