INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-que-an-tet', 'Về Quê Ăn Tết', 'Về Quê Ăn Tết', 'https://phimimg.com/upload/vod/20230917-1/80c97c1cba02059bef08cac664db2397.jpg', 'https://phimimg.com/upload/vod/20230917-1/1bed53018efef26c001b66361e7efbf4.jpg', '<p><span style="font-family: ">Jun Phạm sẽ vào vai chàng lơ xe đôn hậu, chân chất, luôn luôn khao khát một cái Tết đậm đà ý nghĩa trong chuyến hành trình về quê từ Sài Gòn đến Cà Mau. Còn Ngô Thanh Vân là một cô nàng ngổ ngáo với diện mạo độc đáo từ trước tới giờ. Một câu chuyện nhẹ nhàng lấy bối cảnh trên chuyến xe về quê đón Tết.</span></p>', 'Full', 1, 'single', 'completed', 27, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Veronica Ngo","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Le Ngoc Tu''o''ng","avatar":""},{"name":"Tiko Tien Cong","avatar":""},{"name":"Hải Triều","avatar":""},{"name":"Puka","avatar":""},{"name":"Việt Anh","avatar":""},{"name":"Hữu Châu","avatar":""},{"name":"Xuân Lan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324398);
