INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('798muoi', '798Mười', '798Mười', 'https://phimimg.com/upload/vod/20230916-1/0e7da412053acc89f0559a9974fa5af0.jpg', 'https://phimimg.com/upload/vod/20230916-1/a3e2817fb3fa736e50aa819260e6d9ac.jpg', '<p><span style="font-family: ">Chuyện phim 798Mười kể về Tám (Kiều Minh Tuấn) và người anh họ mù lòa Mười (Dustin Nguyễn). Tám lên thành phố lập nghiệp bằng chiếc xe bán bánh tiêu, rồi đem lòng yêu nữ ca sĩ phòng trà tên Bích (Nam Em)</span></p>', 'Full', 1, 'single', 'completed', 27, 2018, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dustin Nguyen","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Tiểu Bảo Quốc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324398);
