INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-chim', 'Lồng Chim', 'Bird Box', 'https://phimimg.com/upload/vod/20230915-1/65af9d020fb23e15641d8d3c3ad8ac39.jpg', 'https://phimimg.com/upload/vod/20230915-1/72674287052cc980fd917eb224b48d90.jpg', '<p><span style="font-family: &quot;Times New Roman&quot;; font-size: medium; text-wrap: wrap;">Chuyện gì sẽ xảy ra nếu cả thế giới rơi vào nguy kịch trước sự tấn công bởi những con quái vật mà chưa một ai từng thấy hình dạng? Sẽ đáng sợ ra sao nếu chúng sơ sẩy một tích tắc nhìn vào chúng, và rồi chúng ta phát điên lên, tự huỷ sự sống của bản thân? Với cách duy nhất để sống sót là bịt mắt và trốn chạy, Malorie (Sandra Bullock) phải làm mọi cách để giữ hai con an toàn giữa cuộc chiến trong bóng tối. Không chỉ phải chiến đấu với những con quái vật vô hình, cô còn phải đấu tranh với bản thân khi chỉ cần một lần hé nhìn là có thể mất đi ánh sáng mãi mãi.</span></p>', 'Full', 1, 'single', 'completed', 30, 2018, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Trevante Rhodes","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Rosa Salazar","avatar":""},{"name":"Danielle Macdonald","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Machine Gun Kelly","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324398);
