INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-tim-thep', 'Quả Tim Thép', 'Bleeding Steel', 'https://phimimg.com/uploads/movies/20260713/qua-tim-thep-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/qua-tim-thep-poster.webp', '<p>Một đặc nhiệm Trung Quốc nhận nhiệm vụ bảo vệ nhà khoa học tài ba khỏi sự săn lùng của tổ chức tội phạm nguy hiểm. Trong suốt thời gian bên cạnh nhà khoa học, ông dần phát hiện những góc khuất mờ ám trong chương trình nghiên cứu của nhà khoa học này, trong số đó đặc biệt nhất là chương trình chế tạo ra cô gái mang trái tim thép. Liệu đây chỉ là một thí nghiệm y học bình thường hay nó là mầm mống của một loại vũ khí mới?</p>', 'Full', 1, 'single', 'completed', 40, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"La Chí Tường","avatar":""},{"name":"Âu Dương Na Na","avatar":""},{"name":"Hạ Hầu Vân San","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Tess Haubrich","avatar":""},{"name":"Gina Carano","avatar":""},{"name":"Bảo Ý","avatar":""},{"name":"Damien Garvey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["机器之血","Eroe di Acciaio","Ji qi zhi xue","Sang d''acier","ポリス・ストーリー／REBORN：2017","Bleeding steel","Сердце из стали"]', 1784690324398);
