INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-nghiep-du', 'Tay Súng Nghiệp Dư', 'Gun Shy', 'https://phimimg.com/uploads/movies/20260710/tay-sung-nghiep-du-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/tay-sung-nghiep-du-poster.webp', '<p>Vợ siêu mẫu của một ngôi sao nhạc rock lớn tuổi, bạch kim bị bọn cướp biển bắt cóc khi đang đi nghỉ ở Chile.</p>', 'Full', 1, 'single', 'completed', 41, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Mark Valley","avatar":""},{"name":"Martin Dingle Wall","avatar":""},{"name":"Ben Cura","avatar":""},{"name":"Aisling Loftus","avatar":""},{"name":"David Mitchell","avatar":""},{"name":"Fernando Godoy","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Anna Francolini","avatar":""},{"name":"Ellie Goffe","avatar":""},{"name":"Milanka Brooks","avatar":""},{"name":"Jesse Johnson","avatar":""},{"name":"Emiliano Jofre","avatar":""},{"name":"Sebastián Apiolaza","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Salty","Несносный мачо","Rock''n Chili","گریز از اسلحه","Gun Shy"]', 1784690324398);
