INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tanya-chien-ky-phan-1', 'Tanya Chiến Ký (Phần 1)', 'Saga Of Tanya The Evil (Season 1)', 'https://phimimg.com/upload/vod/20260703-1/edc4a3175d97a15354c6901b1e20fa70.jpg', 'https://phimimg.com/upload/vod/20260703-1/9c0414264c1462db6c3b0171baf78813.jpg', '<p>Trên tiền tuyến giữa cuộc chiến, một cô gái nhỏ bé, tóc vàng, đôi mắt xanh kiên định, và làn da trắng nhuốm màu khói chiến tranh, bằng chất giọng lanh lảnh của mình, cô điều khiển cả sư đoàn pháp thuật của Đế Quốc. Cô chính là Thiếu Úy Tanya Degurechaff. Nhưng bản chất thật đằng sau hình hài cô gái 9 tuổi này là gì đây? Quả thật, cô chính là một chàng nhân viên ưu tú 30 tuổi, tái sinh dưới hình dạng một cô gái nhỏ, vì vậy anh đã kiêu ngạo mà nói phạm đến Chúa Trời nên phải chịu hình phạt này. Dù hình dáng nhỏ bé, nhưng Tanya vẫn không giấu được bản chất của một người chiến binh tàn bạo, coi trọng sự nghiệp của mình hơn bất cứ thứ gì khác, thậm chí cả mạng sống của những người dưới cô.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 32, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Yuuki","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Hochu Otsuka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谭雅战记","幼女战记 沙漠意面大作战","Youjo Senki","Yōjo Senki","ようじょしぇんき","Военная хроника маленькой девочки","The Saga of Tanya the Evil","The Military Chronicles of a Little Girl","A Little Girl''s Military Record","幼女戦記"]', 1784690324398);
