INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tanya-chien-ky-phan-1', 'Tanya Chiến Ký (Phần 1)', 'Saga Of Tanya The Evil (Season 1)', 'tanya chiến ký (phần 1) saga of tanya the evil (season 1) aoi yuuki saori hayami shin-ichiro miki tessyo genda hochu otsuka 谭雅战记 幼女战记 沙漠意面大作战 youjo senki yōjo senki ようじょしぇんき военная хроника маленькой девочки the saga of tanya the evil the military chronicles of a little girl a little girl''s military record 幼女戦記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-doi-tham-hiem-phan-1', 'Gấu Boonie: Đội Thám Hiểm (Phần 1)', 'Boonie Bears: The Adventurers (Season 1)', 'https://phimimg.com/upload/vod/20260429-1/9b4888cbeb47a2754e1be3ab1f1f5671.jpg', 'https://phimimg.com/upload/vod/20260429-1/87149ff5be27caecffcabe8836ca76f3.jpg', '<p>Cuộc hành trình bắt đầu khi cô bé Carly xuất hiện tại rừng thông để tìm kiếm người bạn hổ Kitty đã mất tích từ thuở nhỏ. Lo ngại về những nguy hiểm rình rập từ những kẻ săn trộm hung ác, anh em gấu Boonie và Vick đã quyết định đồng hành cùng Carly trong chuyến thám hiểm xuyên rừng sâu. Những bí mật về thiên nhiên dần hé mở, thử thách lòng can đảm và tình yêu thương của nhóm bạn trước những cạm bẫy nơi đại ngàn.</p>', 'Tập 45', 52, 'hoathinh', 'ongoing', 50, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Yingying Miu","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没：少年篇","森林保卫战","探险日记","Boonie Bears：The Adventurers","Boonie Bears：The Adventurers 2","Boonie Bears the Adventurers","熊出没之探险日记"]', 1784690324398);
