INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-ky-uc', 'Đêm Ký Ức', 'Forgotten (Night Of Memory)', 'https://phimimg.com/upload/vod/20260618-1/91bdda93b45b1674a7a5f210feb61507.jpg', 'https://phimimg.com/upload/vod/20260618-1/542b9a7b66249bc0b48f74b74921ef27.jpg', '<p>Khi người anh trai bị bắt cóc trở về, mất hết ký ức của 19 ngày trước đó và bắt đầu hành xử kỳ quặc, Jin-seok quyết tâm đi tìm sự thật đằng sau vụ bắt cóc.</p>', 'Full', 1, 'single', 'completed', 32, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ha-neul","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Na Young-hee","avatar":""},{"name":"Nam Myung-ryeol","avatar":""},{"name":"Lee Na-ra","avatar":""},{"name":"Jeong Taek-hyeon","avatar":""},{"name":"Jung Chan-bi","avatar":""},{"name":"Choi Go","avatar":""},{"name":"Bae Seong-il","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Byeon Dong-joon","avatar":""},{"name":"Kang Sin-gu","avatar":""},{"name":"An Min-young","avatar":""},{"name":"Park Jae-yeong","avatar":""},{"name":"Park Chae-ik","avatar":""},{"name":"Kwon Jae-hwan","avatar":""},{"name":"Moon Seong-p","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gieogui bam","Uitat","Recall the Night","Olvidado","Rastros de um Sequestro","Porwana pamięć","Memória Roubada","Forgotten","記憶の夜：2017","Забутий","Ніч спогадів","回忆之夜","Unudulmuş","기억의 밤"]', 1784690324398);
