INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-ky-uc', 'Đêm Ký Ức', 'Forgotten (Night Of Memory)', 'đêm ký ức forgotten (night of memory) kang ha-neul kim moo-yul moon sung-keun na young-hee nam myung-ryeol lee na-ra jeong taek-hyeon jung chan-bi choi go bae seong-il lee soon-won byeon dong-joon kang sin-gu an min-young park jae-yeong park chae-ik kwon jae-hwan moon seong-p gieogui bam uitat recall the night olvidado rastros de um sequestro porwana pamięć memória roubada forgotten 記憶の夜：2017 забутий ніч спогадів 回忆之夜 unudulmuş 기억의 밤', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-loi-noi-doi-tai-hai-phan-1', 'Những Lời Nói Dối Tai Hại (Phần 1)', 'Big Little Lies (Season 1)', 'https://phimimg.com/upload/vod/20260616-1/7a57bfb45e1709826f3843d124b134bd.jpg', 'https://phimimg.com/upload/vod/20260616-1/4065b62125d5c2aa81041e5988bb556e.jpg', '<p>Phim xoay quanh những bà mẹ xinh đẹp sống tại một khu dân cư khá giả. Những tưởng họ luôn có một cuộc sống hoàn hảo, nhưng ẩn bên trong họ cũng phải đối mặt với những vấn đề như bao người phụ nữ “bình dân” khác: bạo lực, chồng cũ, bạn mới, vợ mới của chồng, mẹ đơn thân, con chung, con riêng… Có lẽ vì vậy mà cuộc sống của của họ cần tới những lời nói dối nho nhỏ. Khi một lời nói dối nhỏ bỗng trở thành to, đó là khi lời nói dối trở nên nguy hiểm. Và mọi chuyện lại càng rắc rối hơn khi một vụ án mạng xảy ra...</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 26, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Shailene Woodley","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"James Tupper","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Iain Armitage","avatar":""},{"name":"Jeffrey Nordling","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Chloe Coleman","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Cameron Crovetti","avatar":""},{"name":"Darby Camp","avatar":""},{"name":"Nicholas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Böyük Kiçik Yalanlar","美丽心计","Pequeñas mentiras","Big Little Lies"]', 1784690324398);
