INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-loi-noi-doi-tai-hai-phan-1', 'Những Lời Nói Dối Tai Hại (Phần 1)', 'Big Little Lies (Season 1)', 'những lời nói dối tai hại (phần 1) big little lies (season 1) nicole kidman reese witherspoon shailene woodley laura dern alexander skarsgård adam scott james tupper zoë kravitz meryl streep iain armitage jeffrey nordling kathryn newton chloe coleman douglas smith cameron crovetti darby camp nicholas böyük kiçik yalanlar 美丽心计 pequeñas mentiras big little lies', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-nua-the-gioi-phan-2', 'Hai Nửa Thế Giới (Phần 2)', 'Halfworlds (Season 2)', 'https://phimimg.com/upload/vod/20260615-1/76e33ad53449d8c1c01cd3a80618152f.jpg', 'https://phimimg.com/upload/vod/20260615-1/1af64cf750047e1705db39c7c8107be0.jpg', '<p>Giữa những con phố nhộn nhịp và các con hẻm tối tăm của Jakarta, một thế giới song song của những sinh vật khát máu trong thần thoại Indonesia đã chung sống cùng con người qua nhiều thế hệ. Mang lớp bọc ngoài y hệt con người, danh tính thực sự của các sinh vật mang tên &quot;Demit&quot; này đã được che giấu kỹ lưỡng suốt hàng thế kỷ bởi một gia tộc người phàm đầy quyền lực. Sự xuất hiện của một hiện tượng siêu nhiên bí ẩn với tên gọi &quot;Món Quà&quot; (The Gift) sắp sửa đưa thế giới ngầm này bước ra ánh sáng. Khi ngày diễn ra sự kiện cận kề, Sarah - một nữ họa sĩ đường phố trẻ tuổi - bất ngờ rơi vào ngay trung tâm của trận cuồng phong. Một khi các Demit nhận ra thân phận thực sự của Sarah và sứ mệnh cô phải thực hiện, cả nhân loại lẫn loài Demit sẽ lao vào một cuộc va chạm nảy lửa, có thể thay đổi vĩnh viễn thế cân bằng giữa hai thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 39, 2017, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Thanabordee Jaiyen","avatar":""},{"name":"Tia Taveepanichpan","avatar":""},{"name":"Emma Emika","avatar":""},{"name":"JeeJa Yanin","avatar":""},{"name":"Myra Molloy","avatar":""},{"name":"Teresa Daley","avatar":""},{"name":"Nicole Theriault","avatar":""},{"name":"David Asavanond","avatar":""},{"name":"Reza Rahadian","avatar":""},{"name":"Jake Macapagal","avatar":""},{"name":"Arifin Putra","avatar":""},{"name":"Charlie Ruedpokanon","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["魔人争霸","Halfworlds"]', 1784690324398);
