INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hai-nua-the-gioi-phan-2', 'Hai Nửa Thế Giới (Phần 2)', 'Halfworlds (Season 2)', 'hai nửa thế giới (phần 2) halfworlds (season 2) thanabordee jaiyen tia taveepanichpan emma emika jeeja yanin myra molloy teresa daley nicole theriault david asavanond reza rahadian jake macapagal arifin putra charlie ruedpokanon 魔人争霸 halfworlds', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-rung-xanh-phan-1', 'Quái Vật Rừng Xanh (Phần 1)', 'Brahmarakshas (Season 1)', 'https://phimimg.com/upload/vod/20260611-1/0dc0f025831b2f48e11c27f25996bfff.jpg', 'https://phimimg.com/upload/vod/20260611-1/3fefe6880e2c05c876e779886339524a.jpg', '<p>Bí mật rùng rợn sau lớp vỏ “quái vật khát máu” mới là thứ khiến bạn lạnh sống lưng. Quái Vật Rừng Xanh - Phần 1 mở ra chuỗi bi kịch từ một cuộc hôn nhân vụ lợi, nơi tình yêu bị bóp méo bởi lòng tham và sự phản bội tàn nhẫn. Khi oán hận không thể siêu thoát, nó hóa thành cơn ác mộng săn lùng những cô dâu vô tội - nhưng liệu đó có phải sự thật? Ẩn sau những cái chết bí ẩn là một âm mưu đen tối hơn nhiều. Bộ phim kéo người xem vào mê cung của thù hận, tham vọng, ích kỷ và dối trá, biến con người thành “quái vật” đáng sợ nhất.</p>', 'Hoàn Tất (62/62)', 62, 'series', 'completed', 33, 2017, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Adiba Hussain","avatar":""},{"name":"Leenesh Mattoo","avatar":""},{"name":"Ashish Kaul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Brahmarakshas: Jaag Utha Shaitaan","ब्रह्मराक्षस"]', 1784690324398);
