INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-my-2017', 'Giấc Mơ Mỹ', 'Giấc Mơ Mỹ', 'https://phimimg.com/upload/vod/20260605-1/93080dce44af9513173c32643dc65a7e.jpg', 'https://phimimg.com/upload/vod/20260605-1/d13374a3d0dd2e7b58c0d88382cdb109.jpg', '<p>“Giấc mơ Mỹ” (The American Dream) là bộ phim điện ảnh Việt Nam đầu tiên khai thác về đề tài y khoa với bối cảnh chính được quay tại bệnh viện Vinmec vừa mới được xây dựng ở thành phố Hồ Chí Minh và các bối cảnh khác ở các địa danh nổi tiếng ở tại 15 thành phố lớn ở California cũng như một số cảnh đẹp tại Việt Nam. Nhà sản xuất đã không ngại đầu tư du thuyền 5 sao, máy bay trực thăng cũng như một đoàn xe moto phân khối lớn để thực hiện những cảnh quay sang trọng và hoàng tráng cho phim. Bộ phim quy tụ dàn diễn viên trẻ, tài năng cùng với những diễn viên gạo cội, dày dạn kinh nghiệm của điện ảnh trong và ngoài nước như: Mai Thu Huyền, Bình Minh, Kyo York, Đinh Y Nhung, Ramani Raja, Trương Thế Vinh, Mai Thu Trang, á khôi thể thao Băng Châu…</p>', 'Full', 1, 'single', 'completed', 47, 2017, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Mai Thu Huyền","avatar":""},{"name":"Bình Minh","avatar":""},{"name":"Đinh Y Nhung","avatar":""},{"name":"Kyo York","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["The American Dream","Giấc Mơ Mỹ"]', 1784690324398);
