INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-van-tien-tuyet-dinh-kungfu', 'Lục Vân Tiên Tuyệt Đỉnh Kungfu', 'Luc Van Tien: Kung Fu Warrior', 'https://phimimg.com/upload/vod/20260604-1/a0489f24a8defa3a862714e1472bc958.jpg', 'https://phimimg.com/upload/vod/20260604-1/ea8c25f991360fd18257222140122313.jpg', '<p>Nguyên vào vai anh hùng lịch sử Lục Vân Tiên, người được dịch chuyển một cách kỳ diệu (và không thể giải thích được) đến Việt Nam trong tương lai. Anh kết bạn với một kẻ lừa đảo Tèo (Hữu Tiến), kẻ cố gắng lợi dụng Lục cho mục đích tiền bạc của riêng mình. Chẳng mấy chốc, cả hai bị cuốn vào một nhóm buôn người sau khi Lục cứu Nga (Kim Tuyền) khỏi chúng, và sân khấu được dựng lên cho sự điên rồ tột độ.</p>', 'Full', 1, 'single', 'completed', 53, 2017, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Andy Long Nguyen","avatar":""},{"name":"Diep Lam Anh","avatar":""},{"name":"Lorenz Hideyoshi Ruwwe","avatar":""},{"name":"Felix Fukuyoshi Ruwwe","avatar":""},{"name":"Huu Tien","avatar":""},{"name":"Quang Thắng","avatar":""},{"name":"Kim Tuyến","avatar":""},{"name":"Adam Lam","avatar":""},{"name":"Andy Le","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Lục Vân Tiên Tuyệt Đỉnh Kungfu"]', 1784690324398);
