INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-van-ban-lam-nen-nuoc-my', 'Những Văn Bản Làm Nên Nước Mỹ', 'The Words That Built America', 'những văn bản làm nên nước mỹ the words that built america david mccullough kevin bacon jack black tucker carlson common bryan cranston anderson cooper robert de niro laura dern robert duvall america ferrera morgan freeman sean hannity neil patrick harris samuel l. jackson dwayne johnson caitlyn j the words that built america', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-florida', 'Dự Án Florida', 'The Florida Project', 'https://phimimg.com/upload/vod/20260531-1/8f1e91e4697ebccc1393854f5e2b555b.jpg', 'https://phimimg.com/upload/vod/20260531-1/c5100a191651c7c23beddaa0c38a076e.jpg', '<p>The Florida Project theo chân cô bạn nhỏ Moonee (Brooklynn Prince) và mùa hè kỳ diệu của em tại Magic Castle, một khu nhà nghỉ cũ kỹ, rẻ tiền, nằm trên con đường dẫn vào khu trung tâm giải trí hiện đại bậc nhất nước Mỹ - Walt Disney World. Đó là một mùa hè cực kỳ nóng nực, nhưng luôn tràn ngập niềm vui và đầy ắp tiếng cười của Moonne, cùng ba người bạn đồng trang lứa Scooty (Christopher Rivera), Dicky (Aiden Malik) và Jancey (Valeria Cotto). Những chuyến phiêu lưu, những trò quậy phá, và cả những bí mật chôn giấu đã gắn kết đám bạn nhỏ lại với nhau. Để cuối cùng, lũ trẻ nhận ra rằng việc phải trưởng thành, hay bước chân vào thế giới phức tạp của người lớn, quả thực khó khăn. Nó thể hiện qua lời “tạm biệt” dành cho mùa hè mà Moonee đã gắng gượng thốt ra trước khi bước sang chặng đường mới đầy hoang mang, lo sợ.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brooklynn Prince","avatar":""},{"name":"Bria Vinaite","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Christopher Rivera","avatar":""},{"name":"Valeria Cotto","avatar":""},{"name":"Mela Murder","avatar":""},{"name":"Josie Olivo","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Aiden Malik","avatar":""},{"name":"Edward Pagan","avatar":""},{"name":"Jim R. Coleman","avatar":""},{"name":"Patti Wiley","avatar":""},{"name":"Jasineia Ramos","avatar":""},{"name":"Rosa Medina Perez","avatar":""},{"name":"Krystal Nicole Watts","avatar":""},{"name":"Bronwyn Valley","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Проект \"Флорида\"","佛罗里达廉租房","佛罗里达项目","佛罗里达计划","El proyecto Florida","แดน (ไม่) เนรมิต","Mon royaume en Floride","플로리다 프로젝트","フロリダ・プロジェクト 真夏の魔法：2017","迪士尼的夏天","佛罗里达公租乐事","佛罗里达工程","佛罗里达贫民区","Ֆլորիդա Նախագիծը","歡迎光臨夢幻樂園","歡迎光臨奇幻城堡","The Florida Project"]', 1784690324398);
