INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-troi-diet-vong', 'Vùng Trời Diệt Vong', 'Beyond Skyline', 'https://phimimg.com/upload/vod/20260517-1/ea2362781616e7574a5016157ca17e2e.jpg', 'https://phimimg.com/upload/vod/20260517-1/8bf540b6fbc016975125d0e320932f84.jpg', '<p>Phim bắt đầu bằng việc điều tra viên Mark Corley của cục cảnh sát Los Angeles đi bảo lãnh cho cậu con trai Trent 18 tuổi. Trên đường về nhà, ông bỗng phát hiện ra những quầng sáng màu xanh kỳ lạ đang phủ kín bầu trời. Và chỉ trong một chớp mắt, toàn bộ cư dân của thành phố đông đúc này đã bị hút vào một con tàu khổng lồ của người ngoài hành tinh. Hai cha con đã dẫn một nhóm những người sống sót chạy về phía bến thuyền. Và rồi khi Trent bị bắt đưa lên con tàu ác mộng đó, Mark đã phải dấn thân vào một hành trình vô cùng cam go để giải cứu con trai của mình và toàn bộ người còn lại.</p>', 'Full', 1, 'single', 'completed', 25, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Frank Grillo","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Iko Uwais","avatar":""},{"name":"Yayan Ruhian","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Pamelyn Chee","avatar":""},{"name":"Lindsey Morgan","avatar":""},{"name":"Zarah Mahler","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Antonio Fargas","avatar":""},{"name":"Betty Gabriel","avatar":""},{"name":"Jonny Weston","avatar":""},{"name":"Joanne Baron","avatar":""},{"name":"Kevin O''Donnell","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"Karen Glave","avatar":""},{"name":"Phet Mahathongdy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["สงครามสกายไลน์ดูดโลก 2","Dincolo de orizont","Anapus horizonte","비욘드 스카이라인","天際浩劫2","skyline 2 beyond skyline","Beyond Skyline 2017","Skyline 2 - Beyond Skyline","Skyline 2","Beyond Skyline"]', 1784690324398);
