INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-heck-phan-9', 'Gia đình Heck (Phần 9)', 'The Middle (Season 9)', 'https://phimimg.com/upload/vod/20260516-1/787877d67c10f7b397eeef1b7468964d.jpg', 'https://phimimg.com/upload/vod/20260516-1/b1a17588a82fe81c038365a74b883877.jpg', '<p>Trong mùa thứ chín và cũng là mùa cuối cùng, Frankie và Mike đã hy vọng có một cuộc sống yên bình hơn khi con cái đã trưởng thành, nhưng với việc Axl trở về nhà, họ nhận ra hy vọng đó nhanh chóng tan biến. Trong khi đó, Sue và Sean Donahue sẽ phải giải quyết những tình cảm đơn phương của mình. Và Brick tìm cách để trở nên nổi tiếng hơn ở trường trung học. Nhưng, vì là người nhà Heck, mọi chuyện hầu như không bao giờ diễn ra suôn sẻ như mong muốn!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patricia Heaton","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Charlie McDermott","avatar":""},{"name":"Eden Sher","avatar":""},{"name":"Atticus Shaffer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["左右不逢源","中产家庭","中之道","Anyám borogass","Családom és egyéb emberfajták","ザ・ミドル ～中流家族のフツーの幸せ～","คุณแม่สามัญประจำบ้าน","The Middle"]', 1784690324398);
