INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-diem-a-tuyet-doi-den-xxx', 'Từ điểm A Tuyệt đối đến XXX', 'From Straight A''s To XXX', 'https://phimimg.com/upload/vod/20260514-1/15e4f9d820ff33a44111a1e083249c7a.jpg', 'https://phimimg.com/upload/vod/20260514-1/62402d581217363e0ab7feb2ec79b7b5.jpg', '<p>Khi hoàn cảnh thay đổi khiến Miriam không thể trả học phí đại học, cô đưa ra một quyết định bất ngờ: bắt đầu đóng phim người lớn, sử dụng nghệ danh Belle Knox. Miriam nói dối gia đình và bạn bè ở trường, giữ kín cuộc sống hai mặt của mình. Nhưng chẳng bao lâu sau, tin đồn lan rộng và Miriam trở thành mục tiêu của những cuộc tấn công trực tuyến ác ý và sự chú ý không mong muốn. Miriam phản kháng: cô nói chuyện với giới truyền thông, nói rằng công việc mới của cô giúp cô mạnh mẽ hơn với tư cách là một người theo chủ nghĩa nữ quyền. Nhưng lập trường tự tin của cô lại dẫn đến những hậu quả không lường trước được. Miriam bị gia đình bảo thủ và các đồng nghiệp trong giới phim người lớn xa lánh. Một quyết định bốc đồng đã nhanh chóng vượt khỏi tầm kiểm soát - và rắc rối của Miriam chỉ mới bắt đầu.</p>', 'Trailer', 1, 'single', 'ongoing', 37, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Haley Pullos","avatar":""},{"name":"Sasha Clements","avatar":""},{"name":"Judd Nelson","avatar":""},{"name":"Alyson Bath","avatar":""},{"name":"Jacky Lai","avatar":""},{"name":"Jessica Lu","avatar":""},{"name":"Rachelle Gillis","avatar":""},{"name":"Sarah Porchetta","avatar":""},{"name":"Imali Perera","avatar":""},{"name":"Peter Graham-Gaudreau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Straight A''s","Aluna Exemplar e Estrela Pornô","Mindent a jelesért - Egy felnőttfilmes igaz története","Из отличницы в порнозвезду