INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nhiet-doi', 'Đêm Nhiệt đới', 'Tropical Night', 'https://phimimg.com/upload/vod/20260511-1/8f9eded509fa788e9a664dc09b0cf8db.jpg', 'https://phimimg.com/upload/vod/20260511-1/02f15c381df0175cf897fbdcf02dd607.jpg', '<p>Jae Hee và em trai Tae Kyung sống một cuộc sống yên bình ở Pattaya. Một ngày nọ, Min Ki đến thăm họ. Anh trai của Min Ki, Min Hoon, đã tự tử trong thời gian nghỉ phép quân sự. Tin rằng Jae Hee là người chịu trách nhiệm, Min Ki nhận ra rằng Jae Hee rất yêu em trai mình và dần có cảm tình với anh. Mầm mống tình yêu dần nảy nở trong đêm hè nhiệt đới thơ mộng.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Khan","avatar":""},{"name":"Choi Hong-joon","avatar":""},{"name":"Lee Geun-Joo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yeoldaeya","열대야"]', 1784690324399);
