INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-buoi-trua', 'Ngoại Tình Buổi Trưa', 'Hirugao: Love Affairs in the Afternoon', 'https://phimimg.com/upload/vod/20260508-1/440df5a6a77eabb8dc6eaf683330b917.jpg', 'https://phimimg.com/upload/vod/20260508-1/d41f5ae32c3e8d9c42bcfc3a80d91c6d.jpg', '<p>Hirugao kể về một mối tình ngoài hôn nhân chưa bao giờ thật sự kết thúc. Sau scandal ngoại tình nhiều năm trước, Sawa rời bỏ thành phố, ly hôn và sống cô độc ở một thị trấn ven biển để chuộc lỗi và quên quá khứ. Trong khi đó, Kitano vẫn sống trong cuộc hôn nhân lạnh nhạt với vợ mình. Một ngày, hai người vô tình gặp lại. Dù cố giữ khoảng cách, tình cảm cũ nhanh chóng sống dậy. Họ bắt đầu lén gặp nhau, biết rõ rằng nếu tiếp tục sẽ làm tổn thương nhiều người và phá hủy cuộc sống vừa ổn định trở lại.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Ueto","avatar":""},{"name":"Takumi Saitoh","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Hiroyuki Hirayama","avatar":""},{"name":"Asuka Kurosawa","avatar":""},{"name":"Minori Hagiwara","avatar":""},{"name":"Kotaro Shiga","avatar":""},{"name":"Masaki Miura","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Daigo Matsui","avatar":""},{"name":"Ikuji Nakamura","avatar":""},{"name":"Maharu Nemoto","avatar":""},{"name":"Miku","avatar":""},{"name":"Haruno Niiyama","avatar":""},{"name":"Satoshi Koji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Hirugao: Love Affairs in the Afternoon","昼颜：工作日下午3点的恋人们","昼颜 电影版","昼顔"]', 1784690324399);
