INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-vu-trieu-do-phan-1', 'Phi Vụ Triệu Đô (Phần 1)', 'Money Heist (Season 1)', 'phi vụ triệu đô (phần 1) money heist (season 1) úrsula corberó itziar ituño álvaro morte pedro alonso miguel herrán esther acebo jaime lorente najwa nimri enrique arce rodrigo de la serna darko peric hovik keuchkerian luka peroš belén cuesta fernando cayo haus des geldes kuca od papira хартиената къща la casa de papel la maison de papier 纸钞屋 纸钞屋（西班牙版） papirhuset la casa de papel η τέλεια ληστεία سرقت پول خانه کاغذی البروفيسور la casa de papel darphane soygunu money heist', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kungfu-co-khi-hiep-2-dai-hiep-robot-cong-phu-chi-bac-thoai', 'Kungfu Cơ Khí Hiệp 2 (Đại hiệp ro-bot công phu chi Bắc thoái)', 'Kung Fu Traveler 2 (The Great Robot)', 'https://phimimg.com/upload/vod/20260501-1/5fc60a37bcb57a3d4eea8fed2f49c36d.jpg', 'https://phimimg.com/upload/vod/20260501-1/272b4bfb3860940cbf7e9b010a2f74f8.jpg', '<p>Kung Fu Cơ Khí Hiệp Phần 2 kể câu chuyện về sự phát triển vượt bật trong tương lai của khoa học và công nghệ trên thế giới, để chống lại cuộc xâm lăng của kẻ thù ngoài hành tinh, chủ nhiệm Trần Hổ đã chế tạo robot và gửi lại cho Wu Xuexun trong cuối Triều đại nhàThanh và sự khởi đầu của nghiên cứu về câu chuyện kiệt tác võ thuật Trung Quốc. Những diễn biến tiếp theo đưa người xem vào một cuộc chiến tranh khốc liệt, khói cuồn cuộn trong chiến trường ở tương lai với rất nhiều thành phần khác nhau từ: con người, chiến binh robot và chiến tranh máu của người ngoài hành tình, Trần Hổ và Wang Zhi phải sát cánh cùng nhau đểchống lại kẻ thù.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiger Chen Hu","avatar":""},{"name":"Wang Zhi","avatar":""},{"name":"Han Rui","avatar":""},{"name":"Huang Xiaochao","avatar":""},{"name":"Wang Shengkai","avatar":""},{"name":"Svitlana Zavialova","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["功夫机器侠·北腿篇"]', 1784690324399);
