INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-chuyen-phieu-luu-den-fantastica', 'Gấu Boonie: Chuyến Phiêu Lưu Đến Fantastica', 'Fantastica: A Boonie Bears Adventure / Boonie Bears: Fantastica', 'https://phimimg.com/upload/vod/20260429-1/27afd36d1ec7963ea98adaae827658f7.jpg', 'https://phimimg.com/upload/vod/20260429-1/deeee0d0ca20b147c579de21e47eb413.jpg', '<p>Trọng trách bảo vệ bản đồ kho báu của bộ tộc Hươu bỗng chốc đè nặng lên vai người máy Coco khi cô bị các thế lực hắc ám ráo riết săn đuổi. Trong vòng vây nguy hiểm, Coco may mắn nhận được sự hỗ trợ từ anh em gấu Boonie và tiều phu Vick. Một liên minh bất ngờ được thành lập, họ cùng nhau dấn thân vào cuộc hành trình đến vùng đất Fantastica huyền bí. Thế nhưng, nhóm bạn không thể lường trước được những cạm bẫy, mưu đồ đen tối và bí mật khủng khiếp đang chờ đợi mình ở phía trước.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Xiao","avatar":""},{"name":"Ruke Zhang","avatar":""},{"name":"Zhang Wei","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Joseph Zeng","avatar":""},{"name":"Laure Shang","avatar":""},{"name":"Chunlai Bao","avatar":""},{"name":"Sun Jianhong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["熊出没之奇幻空间","Fantastica: A Boonie Bears Adventure","Bonnie Bears:Entangled Worlds","Fantastica: La grande aventure","熊出没·奇幻空间"]', 1784690324399);
