INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-dien-quang-geed', 'Siêu Nhân Điện Quang Geed', 'Ultraman Geed', 'https://phimimg.com/upload/vod/20260117-1/03b8c8e38e8fd2640a9f7b2a9a14312c.jpg', 'https://phimimg.com/upload/vod/20260117-1/bbd4d9a16c358ee0a636d8f57dc5aa19.jpg', '<p>Sau khi thoát khỏi nanh vuốt của quái vật Skull Gomora, Riku Asakura và đồng đội là Pega vô tình tìm thấy một căn cứ bí mật nằm sâu dưới mặt đất. Được cung cấp những thiết bị và vũ khí hiện đại, cậu biến hình thành siêu nhân điện quang Ultraman Geed và trở thành một anh hùng như mong muốn từ thời thơ ấu.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 28, 2017, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuomi Hamada","avatar":""},{"name":"Chihiro Yamamoto","avatar":""},{"name":"Hitomi Hasebe","avatar":""},{"name":"Shintaro Asanuma","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Mayu Hasegawa","avatar":""},{"name":"Yuta Ozawa","avatar":""},{"name":"Kunito Watanabe","avatar":""},{"name":"Mirei Shimizu","avatar":""},{"name":"Tadashi Mizuo","avatar":""},{"name":"Hitomi Miwa","avatar":""},{"name":"Mirai Uchida","avatar":""},{"name":"Hideyoshi Iwata","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["捷德奥特曼","Urutoraman Jīdo","Ultraman Geed","ウルトラマンジード"]', 1784690324399);
