INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-noi-dia', 'Con Đường Nội Địa', 'The Inland Road', 'https://phimimg.com/upload/vod/20260311-1/5dd6d8e4ec26f46e2eb9253a38994e3d.jpg', 'https://phimimg.com/upload/vod/20260311-1/a8ad9cf27b132cce65df3089d4cb61c5.jpg', '<p>Sau khi sống sót trong vụ tai nạn khi đang bỏ nhà đi, Tia rơi vào cảnh không nơi nương tựa. Cô lần theo gia đình của nạn nhân trong vụ tai nạn và xin ở nhờ. Sự xuất hiện bất ngờ của Tia dần làm xáo trộn cuộc sống của họ. Những bí mật và cảm xúc bị chôn giấu bắt đầu trỗi dậy. Bình yên của gia đình ấy đứng trước nguy cơ bị phá vỡ.</p>', 'Full', 1, 'single', 'completed', 31, 2017, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Gloria Popata","avatar":""},{"name":"David Elliot","avatar":""},{"name":"Georgia Spillane","avatar":""},{"name":"Chelsie Preston Crayford","avatar":""},{"name":"Hera Dunleavy","avatar":""},{"name":"Jodie Hillock","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Inland Road"]', 1784690324399);
