INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dahmer-tuoi-tre-ke-sat-nhan', 'Dahmer Tuổi Trẻ Kẻ Sát Nhân', 'My Friend Dahmer', 'https://phimimg.com/upload/vod/20260307-1/1e0bc3a1ea1ff130190ed88e8a2b38c9.jpg', 'https://phimimg.com/upload/vod/20260307-1/35d79ac29d7921b6cd963bc0ececc9d6.jpg', '<p>Cuối thập niên 1970, kẻ sát nhân Dahmer vẫn là một thiếu niên cô độc, lập dị với những tổn thương từ gốc rễ. Không xoáy sâu vào tội ác, phim đem đến góc nhìn ám ảnh và suy ngẫm về nguồn gốc của nó.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ross Lynch","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Liam Koeth","avatar":""},{"name":"Nancy Telzerow","avatar":""},{"name":"Tommy Nelson","avatar":""},{"name":"Harrison Holzer","avatar":""},{"name":"Brigid Naughton","avatar":""},{"name":"Cameron McKendry","avatar":""},{"name":"Katie Stottlemire","avatar":""},{"name":"Brady M.K. Dunn","avatar":""},{"name":"Jake Ingrassia","avatar":""},{"name":"Michael Ryan Boehm","avatar":""},{"name":"Ben Zgorecki","avatar":""},{"name":"Dontez James","avatar":""},{"name":"Miles Rob","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["마이 프렌드 다머","Mi amigo Dahmer","Mon ami Dahmer","My Friend Dahmer"]', 1784690324399);
