INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-8', 'Quá Nhanh Quá Nguy Hiểm 8', 'The Fate of the Furious', 'https://phimimg.com/upload/vod/20260225-1/1cd666d0b6d7c7149b394cec033aff52.jpg', 'https://phimimg.com/upload/vod/20260225-1/cfef26e59931dda42e93e2f1e0b09352.jpg', '<p>Dom và Letty hiện đang đi hưởng tuần trăng mật. Brian cùng Mia đã quyết định từ giã sự nghiệp. Các thành viên còn lại của nhóm cũng đã được minh oan và dần trở về với cuộc sống bình thường. Nhưng một người phụ nữ bí ẩn (do nữ diễn viên đoạt giải Oscar - Charlize Theron thủ vai) đã dẫn dụ Dom vào thế giới tội phạm mà anh dường như không thể thoát ra được và thậm chí phản bội lại cả những người thân thiết nhất, họ sẽ phải trải qua những thử thách cam go mà họ chưa từng đối mặt. &nbsp;Từ bờ biển Cuba tới những con phố của New York cho đến đồng bằng băng giá của vùng cực biển Barents, đội ngũ ưu tú này sẽ tung hoành ngang dọc khắp địa cầu để ngăn chặn âm mưu làm thế giới hỗn loạn của một kẻ vô chính phủ và mang người đàn ông đã gắn kết họ thành một gia đình trở về.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vin Diesel","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Kristofer Hivju","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Corey Maher","avatar":""},{"name":"Tego Calderon","avatar":""},{"name":"Don Omar","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wild Speed: Ice Break","Furious 8","Fast 8","The Fate of the Furious 8","Форсаж 8","The Fast and the Furious 8","F&F8 - The Fate of the Furious","The Fast and the Furious 8: The Fate of the Furious","Fast and Furious 8","The Fate of the Furious","เร็ว...แรงทะลุนรก 8","A todo gas: 8","A Todo Gas 8 Fast Furious 8","玩命關頭8","rapidos y furiosos 8","Форсаж 8 / The Fate of the Furious","Fast & Furious 8","ワイルド・スピード アイス・ブレイク","Fast & Furious: The Extreme","Quá Nhanh Quá Nguy Hiểm 8","08 - Fast & Furious 8","狂野時速8","The Fast and the Furious VIII: The Fate of the Furious","Forsaj 8","ワイルド・スピード ICE BREAK：2017","Velozes e Furiosos 8"]', 1784690324399);
