INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kingsman-to-chuc-hoang-kim', 'Kingsman: Tổ Chức Hoàng Kim', 'Kingsman: The Golden Circle', 'https://phimimg.com/upload/vod/20260222-1/c6da785eb254d58dd3b504c685b6f279.jpg', 'https://phimimg.com/upload/vod/20260222-1/d07d09ac6a7eadf6b196e09ad2c7ba85.jpg', '<p>Sau sự kiện ở phần một, Eggsy giờ đây đã trở thành điệp viên chính thức của tổ chức Kingsman. Eggsy cùng chuyên gia công nghệ Merlin và các đồng đội cũ buộc phải chạy sang Mỹ sau khi căn cứ của Kingsman bị phá hủy. Tại đây, họ phải phối hợp cùng các đồng minh thuộc Statesmen, tổ chức điệp viên tại Mỹ, để triệt phá mưu của ác nữ Poppy, vốn là thành viên của The Golden Circle - một hội kín mang mục đích lập lại trật tự thế giới mới.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Hanna Alström","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Edward Holcroft","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Sophie Cookson","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Elton John","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Thomas Turgoose","avatar":""},{"name":"Calvin Demba","avatar":""},{"name":"Tob","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f