INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-bang-chung-toi-loi-khong-chung-cu', 'Không Bằng Chứng (Tội Lỗi Không Chứng Cứ)', 'Burning Ice', 'https://phimimg.com/upload/vod/20260203-1/8e2019ad3ee548bfaac2538105f8d402.jpg', 'https://phimimg.com/upload/vod/20260203-1/6096cf591d56b86ffb380f25486957fd.jpg', '<p>Bộ phim kể về một loạt các vụ án mạng xảy ra ở thành phố Hàng và thành phố Ninh. Tất cả đều được miêu tả là tội ác cực kì hoàn hảo, hung thủ ra tay đều không để lại chứng cứ nào để cảnh sát có thể điều tra rõ ràng. Nhưng kì lạ ở chỗ, kẻ sát nhân luôn nhét vào miệng nạn nhân 1 điếu thuốc lá Lợi Quần, hơn nữa còn để lại tờ giấy với nội dung thách thức: “Hãy đến bắt ta …”.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cần Hạo","avatar":""},{"name":"Đặng Gia Gia","avatar":""},{"name":"Lữ Diệu","avatar":""},{"name":"Đới Húc","avatar":""},{"name":"Vương Chân Nhi","avatar":""},{"name":"Ninh Lý","avatar":""},{"name":"Kinh Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Do No Cross","Do.Not.Cross","Do Not Cross","Burning Ice","无证之罪"]', 1784690324399);
