INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ha-luong-dien', 'Thiên Hạ Lương Điền', 'The Grainfield', 'https://phimimg.com/upload/vod/20260127-1/de3a2b6449fcb27240c8d9df336f0a3f.jpg', 'https://phimimg.com/upload/vod/20260127-1/6b603b921df3cb72d665732606dfd030.jpg', '<p>Năm Càn Long thứ 8, một vụ án chấn động bắt nguồn từ việc &#39;kiểm tra chim trong điện vàng&#39; đã phơi bày sự thật về nạn giấu giếm thiên tai và tham nhũng tiền cứu trợ, đồng thời lộ ra cuộc khủng hoảng diện tích đất canh tác bị thu hẹp và kho lương trống rỗng của nhà Thanh.&nbsp; Lưu Thống Huân, dù đang dưỡng bệnh ở quê nhà, đã nhận mệnh tái xuất. Ông dẫn dắt những vị quan trẻ mới nhậm chức như Cốc Sơn, Đỗ Tiêu, vượt qua vòng vây của các thế lực thù địch, lấy tính mạng bảo đảm để thực hiện chính sách khai hoang tăng điền của Càn Long. Sau hai năm nỗ lực, tình hình lương thực dần ổn định, kinh tế quốc gia phục hồi.&nbsp; Tuy nhiên, phe lũ tham quan đứng đầu là Thiết Công Nam và Tống Ngũ Lâu đã công nhắm thẳng vào luật &#39;Cấm Trượng&#39; mới ban hành. Chúng mượn danh khai hoang để thu thuế nặng nề, bóc lột dân khẩn hoang, khiến đại nghiệp của Càn Long đứng trước nguy cơ đổ vỡ. Cùng lúc đó, hơn một nửa trong số 18 tỉnh đối mặt với thiên tai trăm năm có một, khủng hoảng lương thực toàn quốc tái bùng phát, lung lay gốc rễ quốc gia.&nbsp; Lưu Thống Huân và các cộng sự một lần nữa nhận lệnh giữa lúc lâm nguy. Họ chọn vùng trọng điểm thiên tai ở Chiết Giang làm điểm đột phá, kiên trì dùng luật trị điền, quyết chiến sinh tử với các thế lực tà ác. Cuối cùng, họ đã bảo vệ được &#39;vạch đỏ&#39; đất canh tác, xác lập an ninh lương thực là ưu tiên hàng đầu của quốc gia. Thế nhưng, khi chính sách mới vừa thực hiện, họ lại phải đối mặt với thách thức khắc nghiệt hơn: thảm họa sinh thái do khai hoang quá mức gây ra...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 15, 2017, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Kinh An","avatar":""},{"name":"Tôn Ninh","avatar":""},{"name":"Từ Tăng","avatar":""},{"name":"Tông Phong Nham","avatar":""},{"name":"Hạo Bình","avatar":""},{"name":"Hầu Nham Tùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tianxia Liang Tian","천하량전: 충신 유통훈","天下粮田"]', 1784690324399);
