INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-vong-kiem-soat-phan-1', 'Ngoài Vòng Kiểm Soát (Phần 1)', 'Ingobernable (Season 1)', 'https://phimimg.com/upload/vod/20260125-1/82d134757f5e112c9a22efc369f5d722.jpg', 'https://phimimg.com/upload/vod/20260125-1/b8c8055fe4f402ba6c58f170509a70cd.jpg', '<p>Đệ nhất phu nhân Mexico có những kế hoạch lớn lao nhằm cải thiện điều kiện sống cho đất nước. Khi bắt đầu mất niềm tin vào chồng mình, Tổng thống Diego Nava, bà nhận thấy mình đang đứng trước một ngã rẽ cuộc đời, nơi bà cần tìm cách đối mặt với một thử thách vô cùng lớn lao.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 31, 2017, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Tamara Mazarrasa","avatar":""},{"name":"Eréndira Ibarra","avatar":""},{"name":"Alberto Guerra","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Maxi Iglesias","avatar":""},{"name":"Álvaro Guerrero","avatar":""},{"name":"Alicia Jaziz Zapién","avatar":""},{"name":"Aida López","avatar":""},{"name":"Diego Cadavid","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["失控","Ingobernable"]', 1784690324399);
