INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-hieu-truong-nam-nu-diep-vu', 'Công Chúa Hiệu Trưởng (Năm Nữ Điệp Vụ)', 'Princess Principal', 'https://phimimg.com/upload/vod/20260117-1/88b0404b5b1a553b4c1cf1803cb84ec0.jpg', 'https://phimimg.com/upload/vod/20260117-1/7a559343fe6c61af1de4273d1c20f2c6.jpg', '<p>Bối cảnh phim diễn ra tại London thế kỷ 19, nơi thủ đô của nó được chia cắt bởi một bức tường thành phía đông và phía tây của Vương quốc Albion. Năm nữ sinh trung học, theo học tại trường Queens May Fair danh tiếng, tham gia vào các hoạt động gián điệp bao gồm cải trang, xâm nhập, rượt đuổi bằng xe hơi, v.v. Những cô gái này tận dụng khả năng đặc biệt của mình và bay lượn khắp thế giới bóng tối.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akira Sekine","avatar":""},{"name":"Ayaka Imamura","avatar":""},{"name":"Nozomi Furuki","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Akari Kageyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["公主代理人","Princess principal","公主准则","プリンセス・プリンシパル"]', 1784690324399);
