INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-trieu-cuoi-cung-phan-2', 'Vương Triều Cuối Cùng (Phần 2)', 'The Last Kingdom (Season 2)', 'https://phimimg.com/upload/vod/20260112-1/bd4e73769da77e45a25566cdbbef1fa2.jpg', 'https://phimimg.com/upload/vod/20260112-1/41a677d1eb357693d06e5c87c68e708b.jpg', '<p>Một bộ phim về những chiến công anh hùng và những trận chiến hoành tráng với chiều sâu chủ đề bao gồm chính trị, tôn giáo, chiến tranh, lòng dũng cảm, tình yêu, lòng trung thành và hành trình tìm kiếm bản sắc chung của chúng ta. &nbsp;Kết hợp các nhân vật và sự kiện lịch sử có thật với các nhân vật hư cấu, đó là câu chuyện về cách một dân tộc kết hợp sức mạnh của họ dưới một trong những vị vua nổi tiếng nhất lịch sử để khai hoang đất đai cho chính họ và xây dựng một nơi mà họ gọi là quê hương.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexander Dreymon","avatar":""},{"name":"Emily Cox","avatar":""},{"name":"Eliza Butterworth","avatar":""},{"name":"Mark Rowley","avatar":""},{"name":"Ruby Hartley","avatar":""},{"name":"Cavan Clerkin","avatar":""},{"name":"Arnas Fedaravičius","avatar":""},{"name":"Harry Gilby","avatar":""},{"name":"Timothy Innes","avatar":""},{"name":"Stefanie Martini","avatar":""},{"name":"Phia Saban","avatar":""},{"name":"Adrian Schiller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sonuncu Krallıq","Последното кралство","O Último Reino","孤国春秋","最后的王国","Το Τελευταίο Βασίλειο","最後的王國","Pos