INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lach-luat-phan-4', 'Lách Luật (Phần 4)', 'How To Get Away With Murder (Season 4)', 'lách luật (phần 4) how to get away with murder (season 4) viola davis billy brown jack falahee rome flynn aja naomi king matt mcgorry conrad ricamora amirah vann charlie weber liza weil lições de um crime meurtres à l''étude cómo defender a un asesino murder le regole del delitto perfetto 하우 투 겟 어웨이 위드 머더 sposób na morderstwo 謀殺入門課 how to get away with murder', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-nha-van', 'Vũ Khí Nhà Văn', 'Chicago Typewriter', 'https://phimimg.com/upload/vod/20260110-1/7c38c77b696b1c9509185110b0b38539.jpg', 'https://phimimg.com/upload/vod/20260110-1/ceacf11ca6c6a3282c0c7264790f5faa.jpg', '<p>Bộ phim với sự tham gia của dàn diễn viên siêu HOT của Đại Hàn Dân Quốc như Yoo Ah In, Im Soo Jung, Go Kyung Pyo, Kwak Si Yang. Vũ Khí Nhà Văn là câu chuyện về 3 nhà văn sống ở những năm 1930, khi Hàn Quốc còn là thuộc địa của Nhật. Họ được đầu thai và sống ở hiện tại, trong đó có một người là nhà văn có tiếng nhưng đang gặp khủng hoảng, hai người còn lại là người viết thuê và anti-fan của anh ta.Yoo Ah In thủ vai Han Se Joo, một nhà văn nổi tiếng, chủ nhân của hàng loạt cuốn sách ăn khách, kèm theo đó là diện mạo ngôi sao khiến anh ta đã nổi lại càng nổi hơn. Không chỉ là thần tượng của giới văn học, chàng trai này còn sở hữu một lượng fan đông đảo tới mức anh ta có hẳn fanfic (truyện do fan viết) cho riêng mình. Về tính cách, anh ta được miêu tả là một kẻ nhạy cảm, dễ cáu giận nhưng cũng rụt rè, nhút nhát và hay u sầu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Ah-in","avatar":""},{"name":"Lim Soo-jung","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Kwak Si-yang","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Yang Jin-sung","avatar":""},{"name":"Jeon Su-gyeong","avatar":""},{"name":"Kang Hong-suk","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Jo Kyung-sook","avatar":""},{"name":"Seo Hye-jin","avatar":""},{"name":"Shim Min","avatar":""},{"name":"Kim Seong-hoon","avatar":""},{"name":"Park Sun-im","avatar":""},{"name":"Choi Seo-yeon","avatar":""},{"name":"Cha Gun-woo","avatar":""},{"name":"Jeong Yeon-jo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sikago Tajagi","Чикагская печатная машинка","Şikago Daktilosu","시카고 타자기"]', 1784690324401);
