INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-phan-2-nguoi-tren-van-nguoi', 'Nhất Nhân Chi Hạ (Phần 2) (Người Trên Vạn Người)', 'The Outcast (Season 2) (Hitori No Shita)', 'https://phimimg.com/upload/vod/20260110-1/70b6942306352110a869a88c963efbf1.jpg', 'https://phimimg.com/upload/vod/20260110-1/7fdcf1e8a1903df6ffd8b19c287ae3fb.jpg', '<p>Thế giới này tồn tại dị nhân. Trương Sở Lam vì để giải đáp bí mật của ông nội và bản thân, cùng Phùng Bảo Bảo đến phủ Thiên Sư núi Long Hổ tham gia đại hội La Thiên Đại Tiếu của giới dị nhân. Đối chiến với nhiều cao thủ dị nhân khác.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Liansha","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Ajie","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一人之下","Fengqi Yunyong, Luotian Dajiao","异人","Yi Ren Zhi Xia","Yi Ren Zhixia","Hitori no Shita – The Outcast","hitorinoshita - The Outcast","Hitori no Shita","一人の下","一人之下 THE OUTCAST","일인지하 The Outcast","Один из отвергнутых: Изгой","Under One Person","The Outcast","The.OutCast"]', 1784690324401);
