INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh', 'Ngoại Tình', 'Infidelity in Suburbia', 'https://phimimg.com/upload/vod/20260109-1/75a1fd57360857d94303d5c20c49dcc8.jpg', 'https://phimimg.com/upload/vod/20260109-1/527c48c662aa216d6d3e36321daed3a0.jpg', '<p>Chồng đi làm xa nhà, con trai đi học, Laura mơ ước về một dự án cải tạo nhà cửa để lấp đầy những ngày tháng buồn tẻ. Elliott, anh chàng thợ xây tư nhân quyến rũ khó cưỡng, chẳng mấy chốc đã hiện thực hóa những giấc mơ cấm kỵ của cô.</p>', 'Full', 1, 'single', 'completed', 24, 2017, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Marcus Rosner","avatar":""},{"name":"Sarah Butler","avatar":""},{"name":"Miranda Frigon","avatar":""},{"name":"Peter Benson","avatar":""},{"name":"Jay Hindle","avatar":""},{"name":"Jason William Lee","avatar":""},{"name":"Lucie Guest","avatar":""},{"name":"Robin T. Rose","avatar":""},{"name":"Arlo Hajdu","avatar":""},{"name":"Maria Meadows","avatar":""},{"name":"Cassandra Cavalli","avatar":""},{"name":"Erika McKitrick","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["인피델리티 인 서버비아","Infidelity in Suburbia"]', 1784690324401);
