INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-den-toi', 'Thời Khắc Đen Tối', 'Darkest Hour', 'https://phimimg.com/upload/vod/20260109-1/bd0a920e2ebd056ec8da0d8172ce7641.jpg', 'https://phimimg.com/upload/vod/20260109-1/635815968455e5b4e5ce8fc15ad2e07c.jpg', '<p>Phim kể về câu chuyện có thật trong giai đoạn căng thẳng của Thế Chiến thứ II. Trong những ngày chuẩn bị nhậm chức Thủ tưởng nước Anh, Winston Churchill phải đối mặt với một trong những thử thách khó khăn và mang tính quyết định nhất của ông: thương thảo một hiệp định hòa bình với quân Phát Xít Đức. Khi lực lượng quân đội Phát Xít tràn khắp Tây Âu với sức mạnh không tài nào cản nổi và mối đe dọa xâm lược nước Anh đã cận kề, những người dân nước Anh chưa được chuẩn bị tinh thần cho điều đó, còn nhà vua thì vẫn lưỡng lự, thậm chí chính Đảng của Winston Churchill cũng đang âm mưu chống lại ông, Churchill đã phải vượt qua thời khắc đen tối nhất của đời mình, lãnh đạo một đất nước và cố gắng xoay chuyển vòng quay lịch sử.</p>', 'Full', 1, 'single', 'completed', 40, 2017, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Gary Oldman","avatar":""},{"name":"Stephen Dillane","avatar":""},{"name":"Lily James","avatar":""},{"name":"Ronald Pickup","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Nicholas Jones","avatar":""},{"name":"Samuel West","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Richard Lumsden","avatar":""},{"name":"Malcolm Storry","avatar":""},{"name":"Hilton McRae","avatar":""},{"name":"Benjamin Whitrow","avatar":""},{"name":"Joe Armstrong","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"David Bamber","avatar":""},{"name":"Paul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '["Las Horas mas Oscuras","O Destino de Uma Nação","다키스트 아워","El instante más oscuro","ウィンストン・チャーチル／ヒトラーから世界を救った男：2017","Churchill - Die dunkelste Stunde","تاریک‌ترین لحظات","Giờ Đen Tối","Les Heures sombres","Darkest Hour"]', 1784690324401);
