INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-khac-den-toi', 'Thời Khắc Đen Tối', 'Darkest Hour', 'thời khắc đen tối darkest hour gary oldman stephen dillane lily james ronald pickup ben mendelsohn kristin scott thomas nicholas jones samuel west david schofield richard lumsden malcolm storry hilton mcrae benjamin whitrow joe armstrong adrian rawlins david bamber paul las horas mas oscuras o destino de uma nação 다키스트 아워 el instante más oscuro ウィンストン・チャーチル／ヒトラーから世界を救った男：2017 churchill - die dunkelste stunde تاریک‌ترین لحظات giờ đen tối les heures sombres darkest hour', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thi-baahubali-2-ket-thuc', 'Sử Thi Baahubali 2: Kết Thúc', 'Bāhubali 2: The Conclusion', 'https://phimimg.com/upload/vod/20260109-1/6dfd1a8af89d1a3a3217e9a1a5cc4755.jpg', 'https://phimimg.com/upload/vod/20260109-1/7887b170323fe8e4e36cd86cc2f7d6e7.jpg', '<p>Nội dung của phim Baahubali 2 tiếp nối câu chuyện của phần 1, lúc này Kattappa (Sathyaraj) tiếp tục kể về câu chuyện mà ông đã giết Amarendra Baahubali (Prabhas) như thế nào. Sau khi đánh bại Kalakeyas, Amarendra chính thức trở thành vị vua kế tiếp của Mahishmati, trong khi đó Bhallaladeva (Rana Daggubati) được phong lên chức tướng quân. Trước lễ đăng quang, Rajamatha Sivagami (Ramya Krishnan) bắt đầu tìm cho Amarendra một nàng dâu ưng ý. Bà đưa Amarendra và Kattappa đi thị sát khắp vương quốc để hiểu hơn về tình trạng hiện tại của quốc gia cũng như cuộc sống của những người dân nơi đây. Tuy nhiên, Amarendra từ trước đã yêu Devasena (Anushka Shetty), công chúa của vương quốc Kuntala và là em gái của vua Kuntala. Mặc dù vậy, Sivagami không muốn 2 người này đến với nhau bởi những xung đột của 2 nước, vì vậy bà đã ra sức ngăn cản. Để rồi sau đó là những biến cố và những cuộc chiến xảy đến.</p>', 'Full', 1, 'single', 'completed', 21, 2017, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Rana Daggubati","avatar":""},{"name":"Anushka Shetty","avatar":""},{"name":"Sathyaraj","avatar":""},{"name":"Nassar","avatar":""},{"name":"Ramya Krishnan","avatar":""},{"name":"Subbaraju","avatar":""},{"name":"Tamannaah Bhatia","avatar":""},{"name":"Prudhviraj","avatar":""},{"name":"Rohini","avatar":""},{"name":"Kalpalatha","avatar":""},{"name":"Ashrita Vemuganti","avatar":""},{"name":"Tanikella Bharani","avatar":""},{"name":"Bharani Shankar","avatar":""},{"name":"P. Ravi Shankar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["바후발리: 폭풍의 신","Baahubali 2","Bahubali 2 - The Conclusion","La Leyenda de Baahubali 2 - La conclusión","Baahubali 2: The Conclusion","Bahubali 2: The Conclusion","Bāhubali 2: Di kan klūjan","Baahubali 2: A Conclusão","Бахубали: Завершение","బాహుబలి 2: ది కన్ క్లూజన్"]', 1784690324401);
