INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kong-dao-dau-lau', 'Kong: Đảo Đầu Lâu', 'Kong: Skull Island', 'https://phimimg.com/upload/vod/20260108-1/af51948f63db9f6bf7c9ba3f9408b872.jpg', 'https://phimimg.com/upload/vod/20260108-1/6c3b562a404a7a7d3178962b8e714dc3.jpg', '<p>Phim &quot;Kong: Skull Island&quot; (&quot;Kong: Đảo Đầu Lâu&quot;) tái hiện lại hình tượng King Kong (Chúa tể loài khỉ) trong một hành trình phiêu lưu, hấp dẫn dưới bàn tay đạo diễn tài ba Jordan Vogt-Robert. &quot;Kong: Skull Islands&quot; được quay ngoại cảnh ở Tràng An, Vân Long, Tam Cốc, Vịnh Hạ Long và Động Phong Nha-Kẻ Bàng cùng các địa danh quốc tế như Hawaii, Úc... &nbsp;Trong phim, một nhóm các nhà thám hiểm liều lĩnh khám phá Đảo Đầu Lâu, nơi chưa có dấu chân người tại Thái Bình Dương. Hoang sơ, tuyệt đẹp nhưng nơi đây lại ẩn chứa rất nhiều cạm bẫy nguy hiểm. Và điều đáng sợ hơn là họ không hề hay biết rằng mình đang dấn thân vào lãnh địa của Kong huyền thoại.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Tom Hiddleston","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Jing Tian","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Corey Hawkins","avatar":""},{"name":"Jason Mitchell","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Terry Notary","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Marc Evan Jackson","avatar":""},{"name":"Eugene Cordero","avatar":""},{"name":"MIYAVI","avatar":""},{"name":"Will Brittain","avatar":""},{"name":"Richard Je","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c7