INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-am-gia-dinh-phan-4', 'Mái Ấm Gia Đình (Phần 4)', 'Come Home Love: Lo And Behold', 'https://phimimg.com/upload/vod/20251210-1/1567af4382a862815af3819bbfc7f4a2.jpg', 'https://phimimg.com/upload/vod/20251210-1/8cc65265d2c571cb55c38334c134c1e9.jpg', '<p>Phim xoay quanh Hùng Thụ Căn gầy dựng nên công ty vận tải. Nhưng điều lo lắng nhất của ông là ở hai cô con gái. Thủy đã đến tuổi lấy chồng, do kén cá chọn canh nên vẫn còn độc thân. Như là một sinh viên xuất sắc, ham học. Hai chị em không hợp tính nhau nên suốt ngày gây chuyện, cãi vã, khiến người cha già nhức hết cả đầu…</p>', 'Hoàn Tất (130/130)', 130, 'series', 'completed', 15, 2017, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Từ Tuấn Oanh","avatar":""},{"name":"Từ Lạc Tư","avatar":""},{"name":"Viên Bảo Tuệ","avatar":""},{"name":"Tăng Thụ Nhân","avatar":""},{"name":"Phùng Nhật Tiến","avatar":""},{"name":"Lương Ân Đông","avatar":""},{"name":"Lý Ỷ Hoa","avatar":""},{"name":"Khâu Hải Kỳ","avatar":""},{"name":"Ngũ Bội Nghi","avatar":""},{"name":"Huỳnh Tú Thanh","avatar":""},{"name":"Trần Khả Nhi","avatar":""},{"name":"Hà Thế Kiệt","avatar":""},{"name":"Lương Chí Hiền","avatar":""},{"name":"Tiêu Quốc Hoa","avatar":""},{"name":"Khu Gia Tuệ","avatar":""},{"name":"Hứa Thế Hiên","avatar":""},{"name":"Lữ Chính Thanh","avatar":""},{"name":"Trần Bội Hoa","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱回家之开心速递","开心速递","爱·回家","Come Home Love: Happy Courier",