INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-dau-sat-nhan', 'Theo Dấu Sát Nhân (Yếu Nhân)', 'V.I.P.', 'https://phimimg.com/upload/vod/20260101-1/5e3c4eae6a79b1ce8c312473650917c1.jpg', 'https://phimimg.com/upload/vod/20260101-1/09b588462536419502fc4a7b8ed1c699.jpg', '<p>Theo Dấu Sát Nhân là bộ phim xoay quanh Gwang Il (Lee Jong Suk), con trai của một quan chức Triều Tiên máu mặt, kẻ bị tình nghi là thủ phạm của vụ án giết người hàng loạt xảy ra trên khắp thế giới. Tham gia vào cuộc truy bắt Gwang Il là các đặc vụ tới từ Hàn Quốc, Triều Tiên và Tổ chức Cảnh sát Hình sự Quốc Tế.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-gun","avatar":""},{"name":"Kim Myung-min","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Lee Jong-suk","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Ji Eun-seo","avatar":""},{"name":"Bae Yong-geun","avatar":""},{"name":"Chung Ye-jin","avatar":""},{"name":"Lee Jung-hyuk","avatar":""},{"name":"You Chea-myung","avatar":""},{"name":"Andreas Fronk","avatar":""},{"name":"Gareth Fannin","avatar":""},{"name":"Daniel C. Kennedy","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["V.I.P.","VIP","beu-iaipi","V.I.P. 修羅の獣たち：2017","Особо важная персона","브이아이피"]', 1784690324401);
