INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-truyen-thong', 'Cuộc Chiến Truyền Thông', 'The Post', 'https://phimimg.com/upload/vod/20251230-1/b84782a4fe3c05e2895a011cc81b4384.jpg', 'https://phimimg.com/upload/vod/20251230-1/7704c79967900ca2ffc9ed39e836887b.jpg', '<p>The Post là tác phẩm nặng ký cho mùa Oscar do đạo diễn Steven Spielberg dàn dựng có hai ngôi sao hạng A tham gia là Meryl Streep và Tom Hanks, lấy đề tài báo chí chính thống quanh sự ra đời của tờ Washington Post. Theo phân tích của giới phê bình, The Post vẫn đang là ứng cử viên &quot;bom tạ&quot; cho mùa giải thưởng cuối năm. Không phải phim nào cũng quy tụ được hai cái tên cộm cán như Meryl Streep và Tom Hanks. Trong vai nhà xuất bản Katharine Graham và biên tập nội dung Ben Bradlee, cả Meryl Streep và Tom Hanks lần lượt mang về danh hiệu Nữ và Nam diễn viên chính xuất sắc nhất của giải Hội đồng phê bình phim quốc gia Mỹ (gọi tắt là NBR) năm nay ...</p>', 'Full', 1, 'single', 'completed', 24, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Matthew Rhys","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Carrie Coon","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"David Cross","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"John Rue","avatar":""},{"name":"Rick Holmes","avatar":""},{"name":"Philip Casnoff","avatar":""},{"name":"Jessie Mueller","avatar":""},{"name":"Stark S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Papers","The Pentagon Papers","The Post: Los Oscuros Secretos del Pentágono","The Post: Los Oscuros Secretos Del Pentágono","The Post - A Guerra Secreta","Los archivos del Pentágono","The Post","더 포스트","더 포스트, 펜타곤 페이퍼","Czwarta Władza","ペンタゴン・ペーパーズ／最高機密文書：2017"]', 1784690324401);
