INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-cam-do', 'Vòng Xoay Cám Dỗ', 'Wonder Wheel', 'https://phimimg.com/upload/vod/20251229-1/e962717f52c0e9f8c6b67bba0e4f1eb0.jpg', 'https://phimimg.com/upload/vod/20251229-1/bc0f06aefc21e39719897f25124808b8.jpg', '<p>Vòng xoay của cuộc đời Ginny (Kate Winslet đóng), một phụ nữ luống tuổi, từng theo đuổi nghiệp diễn viên nhưng đành an phận làm phục vụ tại một nhà hàng nhỏ và sống cùng người chồng thô lỗ, cục mịch. &nbsp;Mọi chuyện càng trở nên phức tạp hơn khi người con gái riêng của chồng Ginny đột ngột trở về nhà sau nhiều năm mất liên lạc,và cũng đem lòng thích Mickey.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jim Belushi","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Jack Gore","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Robert C. Kirk","avatar":""},{"name":"Tommy Nohilly","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"John Doumanian","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Gregory Dann","avatar":""},{"name":"Bobby Slayton","avatar":""},{"name":"Michael Zegarski","avatar":""},{"name":"Geneva Carr","avatar":""},{"name":"Ed Jewe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["La Rueda de la Maravilla","Колело на чудесата","摩天轮","Wonder Wheel - Az óriáskerék","Roda Gigante","奇幻摩天輪","Wonder Wheel"]', 1784690324401);
