INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-vuot-thoi-gian', 'Cặp Đôi Vượt Thời Gian', 'Go Back Couple (Couple On The Backtrack)', 'https://phimimg.com/upload/vod/20251221-1/d3b9ae5198fdb3724c47ee79c2a9238a.jpg', 'https://phimimg.com/upload/vod/20251221-1/003783fe3890b6ae507c916f3161bc63.jpg', '<p>Choi Ban Do và Ma Jin Joo đều 38 tuổi, là một cặp vợ chồng trung niên. Choi Ban Do lo gánh nặng kiếm tiền còn Ma Jin Joo là một bà nội trợ luôn cảm thấy mặc cảm. Mặc dù họ đã từng yêu nhau rất nhiều khi kết hôn, nhưng giờ họ quyết định ly dị. Cả hai đều hối tiếc vì kết hôn ở tuổi quá trẻ như vậy. Bỗng hai vợ chồng vượt thời gian và thấy mình là sinh viên đại học 20 tuổi, thời điểm họ gặp nhau lần đầu tiên.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Na-ra","avatar":""},{"name":"Son Ho-jun","avatar":""},{"name":"Im Ji-gyu","avatar":""},{"name":"Heo Jung-min","avatar":""},{"name":"Han Bo-reum","avatar":""},{"name":"Jang Ki-yong","avatar":""},{"name":"Go Bo-gyeol","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Cho Hye-jeong","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Cha Min-jee","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Cho Ryun","avatar":""},{"name":"Ko Eun-min","avatar":""},{"name":"Lee Do-yeon","avatar":""},{"name":"Won Geun-su","avatar":""},{"name":"Kim Mi-ji","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm