INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gi-xay-ra-voi-thu-hai', 'Chuyện Gì Xảy Ra Với Thứ Hai', 'What Happened to Monday', 'https://phimimg.com/upload/vod/20251216-1/d79eb89596a0da8957e2f17a6780ae01.jpg', 'https://phimimg.com/upload/vod/20251216-1/b15c0752c0e5e9971c12a1f9d6b0314c.jpg', '<p>Trong một thế giới khi dân số trở nên quá tải, chính phủ phải kiểm soát người dân thông qua thiết bị vệ tinh. Đứng trước sự kiểm soát chặt chẽ đó, một nhóm chị em với biệt danh từ thứ hai đến chủ nhật đã âm thầm chống lại sự kiểm soát bằng cách vô hiệu hóa thiết bị trên.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Bỉ', 1, '[{"name":"Noomi Rapace","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Marwan Kenzari","avatar":""},{"name":"Christian Rubeck","avatar":""},{"name":"Pål Sverre Hagen","avatar":""},{"name":"Tomiwa Edun","avatar":""},{"name":"Cassie Clare","avatar":""},{"name":"Cameron Jack","avatar":""},{"name":"Clara Read","avatar":""},{"name":"Kirsty Averton","avatar":""},{"name":"Robert Wagner","avatar":""},{"name":"Vegar Hoel","avatar":""},{"name":"Madalin Dragan","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Daniel Berge Halvorsen","avatar":""},{"name":"Jepp","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["星期一怎么了","星期一发生了什么","七女","Seven Sisters","7 Sisters","Sept soeurs","Sept sœurs","월요일이 사