INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-gi-xay-ra-voi-thu-hai', 'Chuyện Gì Xảy Ra Với Thứ Hai', 'What Happened to Monday', 'chuyện gì xảy ra với thứ hai what happened to monday noomi rapace glenn close willem dafoe marwan kenzari christian rubeck pål sverre hagen tomiwa edun cassie clare cameron jack clara read kirsty averton robert wagner vegar hoel madalin dragan stig frode henriksen daniel berge halvorsen jepp 星期一怎么了 星期一发生了什么 七女 seven sisters 7 sisters sept soeurs sept sœurs 월요일이 사라졌다 was geschah am montag? qué le pasó a lunes? what happened to monday седам сестара шта се десило са понедељком what happened to monday? chuyện gì xảy ra với thứ hai 獵殺星期一 kas notika ar pirmdienu? seven sisters - what happened to monday yedinci hayat', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-thuat-gay-soc', 'Chiến Thuật Gây Sốc', 'Shock And Awe', 'https://phimimg.com/upload/vod/20251214-1/ee36548f879141086f56148d36d18517.jpg', 'https://phimimg.com/upload/vod/20251214-1/5ee7954c8508368c94a5c43ffac9184d.jpg', '<p>Dựa trên câu chuyện có thật, nhóm nhà báo của Knight Ridder đã chất vấn lý do xâm lược Iraq năm 2003 của chính quyền khi ấy, đặc biệt với tuyên bố Saddam Hussein có &quot;vũ khí hủy diệt hàng loạt&quot;.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Marsden","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Rob Reiner","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Teri Wyble","avatar":""},{"name":"Al Sapienza","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Terence Rosemore","avatar":""},{"name":"Margo Moorer","avatar":""},{"name":"Michael Harding","avatar":""},{"name":"Kate Butler","avatar":""},{"name":"Luke White","avatar":""},{"name":"Gabe White","avatar":""},{"name":"Bowen Hoov","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["震慑","威慑与恐吓","Шок и ужас","충격과 공포","Conmocion y Destruccion","The Truth Matters","Attacco alla verità - Shock and Awe","記者たち～衝撃と畏怖の真実～","Shock and Awe"]', 1784690324401);
