INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-thanh-trung', 'Đội Thanh Trừng', 'Eliminators', 'https://phimimg.com/upload/vod/20251206-1/f4e4bda249b7953a608a77bbc5a8378e.jpg', 'https://phimimg.com/upload/vod/20251206-1/1fb658ac5fbf297c78564d34be6a238d.jpg', '<p>Một cựu Đặc vụ Liên bang Hoa Kỳ phải từ bỏ chương trình bảo vệ nhân chứng và trốn thoát khi ngôi nhà ở London của anh ta bị đột nhập do sai địa chỉ. Khi sự kiện kết thúc với nhiều vụ giết người, tin tức đã khiến những kẻ săn lùng anh cử sát thủ nguy hiểm nhất Châu Âu đến giết anh. Giờ đây đang chạy trốn trong khi mạng sống của con gái đang gặp nguy hiểm, một người cha quyết tâm phải đưa cô đến nơi an toàn trước khi những người mà ông đang trốn tránh truy lùng ông.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Stuart Bennett","avatar":""},{"name":"Daniel Caltagirone","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Mem Ferda","avatar":""},{"name":"Ty Glaser","avatar":""},{"name":"Olivia Mace","avatar":""},{"name":"Stephen Marcus","avatar":""},{"name":"Bruce Lester-Johnson","avatar":""},{"name":"Sean Cronin","avatar":""},{"name":"Lee Charles","avatar":""},{"name":"Marc Edwards","avatar":""},{"name":"David William Bryan","avatar":""},{"name":"Franco Flammia","avatar":""},{"name":"Ellie Goffe","avatar":""},{"name":"Frances Millar","avatar":""},{"name":"Danny Babingt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Eliminators","Елиминатори","Οι εξολοθρευτές","Elhárítók","Get Back: Hitojichi Dakkan","Лик