INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-lua-gao-phan-2', 'Học Viện Lúa Gạo (Phần 2)', 'Love Kome: We Love Rice (Season 2)', 'https://phimimg.com/upload/vod/20251205-1/299153126a8b97cceab0c1dcf3b06c86.jpg', 'https://phimimg.com/upload/vod/20251205-1/b6235f06e18822837e0a7d5749daea7d.jpg', '<p>Tại Học viện Kokuritsu Inaho, năm học sinh mới lấy cảm hứng từ gạo (cơm) tìm cách thay thế bánh mì, loại ngũ cốc đang rất được ưa chuộng tại trường.&nbsp; Các học sinh mới này thành lập nhóm &quot;Love Rice&quot; và đặt mục tiêu biểu diễn tại &quot;Harvest Show&quot; (Buổi Diễn Thu Hoạch) để thể hiện sức hấp dẫn thơm ngon của hạt gạo.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chiharu Sawashiro","avatar":""},{"name":"Mark Ishii","avatar":""},{"name":"Sousuke Souma","avatar":""},{"name":"Misae Komori","avatar":""},{"name":"Nina Tamaki","avatar":""},{"name":"Genki Okawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love Kome","ラブ米（コメ）－WE LOVE RICE-"]', 1784690324401);
