INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-tu-than-2017', 'Vùng Đất Tử Thần', 'Wind River', 'https://phimimg.com/upload/vod/20251202-1/30da83d64df25b8d7f847097ffc0c60e.jpg', 'https://phimimg.com/upload/vod/20251202-1/84be46e74ff33a8dd836be01177b7ae8.jpg', '<p>Vùng Đất Tử Thần do Taylor Sheridan đạo diễn kiêm biên kịch. Tác phẩm này gây chú ý ở Liên hoan phim Cannes với giải Đạo diễn xuất sắc trong hạng mục Un Certain Regard (Nhãn quan độc đáo). Trước đây, Taylor Sheridan từng ghi dấu ấn khi viết kịch bản của hai bộ phim Sicario và Hell or High Water. Cả ba bộ phim được giới phê bình đánh giá có liên quan đến nhau, cùng phản ánh những chủ đề chung về góc khuất nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jeremy Renner","avatar":""},{"name":"Elizabeth Olsen","avatar":""},{"name":"Gil Birmingham","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Kelsey Asbille","avatar":""},{"name":"Teo Briones","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Matthew Del Negro","avatar":""},{"name":"Hugh Dillon","avatar":""},{"name":"Julia Jones","avatar":""},{"name":"James Jordan","avatar":""},{"name":"Eric Lange","avatar":""},{"name":"Martin Sensmeier","avatar":""},{"name":"Apesanahkwat","avatar":""},{"name":"Althea Sam","avatar":""},{"name":"Tokala Black Elk","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Wind River","Kardaki İzler","윈드 리버","Terra Selvagem","Muerte mister