INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-lua-dao', 'Vòng Xoáy Lừa Đảo', 'The Swindlers', 'https://phimimg.com/upload/vod/20251122-1/d62ba2e0ea927e1e830e95f43d33a545.jpg', 'https://phimimg.com/upload/vod/20251122-1/ca515964a9e2410fc96f0193a682598f.jpg', '<p>Bộ phim xoay quanh một tên lừa đảo từng được báo cáo là đã chết sau một vụ lừa đảo, tuy nhiên đang có tin đồn rằng hắn vẫn còn sống. Một công tố viên họ Park từng cấu kết với tên này cần phải tiêu diệt hắn trước khi bê bối nổ ra. Trong quá trình trừ khử tên lừa đảo, Park đã gặp một tên lừa đảo khác, tên là Ji Sung. Ji Sung cũng muốn tiêu diệt tên lừa đảo kia để báo thù. Nhận ra cả hai có chung mục tiêu, Park và Ji Sung quyết định hợp tác, thế nhưng chúng lại hành động bí mật không để người kia biết.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Nana","avatar":""},{"name":"Ahn Se-ha","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Choi Il-hwa","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Oh Tae-kyung","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Jo Eun-joo","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Kang Sin-goo","avatar":""},{"name":"Jang Won-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kkun","The Swindlers","Ggoon","スウィンダラーズ：2017","Conman","꾼"]', 1784690324401);
