INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-sat', 'Tàn Sát', 'Kill ''em All', 'https://phimimg.com/upload/vod/20251122-1/2cc1e2ded81b3493f5f43cde30686d14.jpg', 'https://phimimg.com/upload/vod/20251122-1/d4b0de48a3350657e32bb4a6d6ce25ff.jpg', '<p>Sau một cuộc chạm súng, Philip được đưa đến một bệnh viện địa phương với những vết thương nguy hiểm đến tính mạng. Tiếp theo, một nhóm sát thủ nước ngoài kéo đến bệnh viện để tìm giết anh ta. Cô Y tá của anh ta, là nhân chứng duy nhất còn sót lại sau cuộc săn lùng của nhóm sát thủ. Philip vừa phải chiến đấu để sinh tồn, vừa phải bảo vệ cô nữ y tá kia. Cuộc chiến nghẹt thở từng giây bắt đầu.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Autumn Reeser","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Kris Van Damme","avatar":""},{"name":"Mila Kalađurđević","avatar":""},{"name":"Peter Organ","avatar":""},{"name":"Paul Sampson","avatar":""},{"name":"Kieran Gallagher","avatar":""},{"name":"Eddie Matthews","avatar":""},{"name":"Talia Andrews","avatar":""},{"name":"David Maitland","avatar":""},{"name":"Jeffrey Riseden","avatar":""},{"name":"Dominic Salvator","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["殺機瀰漫","火线保镖","همه را بکش","Mátalos a todos","Sans pitié (Kill ''em All)","Kill Them All","Kill ''em All"]', 1784690324401);
