INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-nghiem-diem-chet', 'Trải Nghiệm Điểm Chết', 'Flatliners', 'https://phimimg.com/upload/vod/20251114-1/99488b020db1ab9a34029de57a6e4c36.jpg', 'https://phimimg.com/upload/vod/20251114-1/0a069b701f8c614f5c84603c2e49e81d.jpg', '<p>Trải Nghiệm Điểm Chết, Flatliners một nhóm sinh viên Y khoa bắt đầu khám phá lĩnh vực của những trải nghiệm cái chết lầm sàn, với hy vọng khám phá được những thứ thú vị nhất. Mỗi người đều có trái tim mình ngừng lại và được hồi sinh. Họ bắt đầu có những cơn ác mộng đi bộ từ thời thơ ấu, phản ánh những tội lỗi mà họ đã phạm phải hoặc đã phạm phải chống lại họ. Những kinh nghiệm tiếp tục tăng cường, và họ bắt đầu bị đánh đập về thể chất bởi tầm nhìn của họ khi họ cố gắng đi sâu hơn vào cái chết để tìm ra cách chữa bệnh.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Elliot Page","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"James Norton","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Beau Mirchoff","avatar":""},{"name":"Wendy Raquel Robinson","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Madison Brydges","avatar":""},{"name":"Jacob Soley","avatar":""},{"name":"Anna Arden","avatar":""},{"name":"Miguel Anthony","avatar":""},{"name":"Jenny Raven","avatar":""},{"name":"Charlotte McKinney","avatar":""},{"name":"Steve Byers","avatar":""},{"name":"Lisa Codrington","avatar":""},{"name":"Emily Pi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Trải nghiệm điểm chết","ขอ