INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-con-nai-than', 'Giết Con Nai Thần', 'The Killing Of A Sacred Deer', 'https://phimimg.com/upload/vod/20251023-1/0254a8b0fe2e2d4e4736b4fe4348d8fd.jpg', 'https://phimimg.com/upload/vod/20251023-1/c97be017ed63cb580bcc603e6318f17b.jpg', '<p>Tiến sĩ Steven Murphy là một bác sĩ phẫu thuật tim mạch nổi tiếng, người chủ trì một gia đình không tì vết cùng vợ và hai con. Ẩn mình bên lề cuộc sống bình dị ở vùng ngoại ô của mình là Martin, một thiếu niên mồ côi cha, người đã dấn thân vào cuộc sống bác sĩ theo những cách dần dần đáng lo ngại.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Raffey Cassidy","avatar":""},{"name":"Sunny Suljic","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"Herb Caillouet","avatar":""},{"name":"Barry G. Bernson","avatar":""},{"name":"Denise Dal Vera","avatar":""},{"name":"Drew Logan","avatar":""},{"name":"Ming Wang","avatar":""},{"name":"Michael Trester","avatar":""},{"name":"Anita Farmer Bergman","avatar":""},{"name":"Lea Hutton Beasmore","avatar":""},{"name":"Dylan Keith Ada","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ο θάνατος του ιερού ελαφιού","聖鹿之死","El sacrificio de un ciervo sagrado","Убийство священного оленя","Il sacrificio del cervo sacro","Mise à mort du cerf sacré","킬링 디어","مقتل الغزال المقدس","Püha hirve tapmine","The Killing of a Sacred Deer"]', 1784690324401);
