INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-nang-tokyo-mo-mong-phan-1', 'Cô Nàng Tokyo Mơ Mộng (Phần 1)', 'Tokyo Tarareba Girls (Season 1)', 'cô nàng tokyo mơ mộng (phần 1) tokyo tarareba girls (season 1) yuriko yoshitaka nana eikura yuko oshima kentaro sakaguchi ryohei suzuki kei tanaka yuta hiraoka mokomichi hayami eri murakawa ren ishikawa 東京タラレバ娘', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-ngay-xua-phan-7', 'Ngày Xửa Ngày Xưa (Phần 7)', 'Once Upon A Time (Season 7)', 'https://phimimg.com/upload/vod/20251023-1/6a911f65bcf830b6a1762add2f0eeefb.jpg', 'https://phimimg.com/upload/vod/20251023-1/5fed9c49e1688609ecc5515228be1fdc.jpg', '<p>Loạt phim xoay quanh câu chuyện của nữ trinh thám Emma Swan cùng con trai Henry trong quá trình khám phá thị trấn Storybrooke (tiểu bang Maine, Đông Bắc Hoa Kỳ). Đây được xem là vết tích của một thế giới song song bị nguyền rủa bởi Hoàng hậu độc ác - Regina Mills - người đến từ câu chuyện cổ tích Nàng Bạch Tuyết. Trong phim, mọi nhân vật đến từ thế giới cổ tích đều không có ký ức về thân phận của mình. Nữ trinh thám Emma Swan được gửi đến thế giới này với nhiệm vụ phá vỡ lời nguyền của mụ Hoàng hậu độc ác. Trong phần 2 này, khi lời nguyền bị phá vỡ, nữ trinh thám Emma được đoàn tụ với cha mẹ, nhưng mụ Hoàng hậu độc ác Regina liệu có để mọi chuyện được yên?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lana Parrilla","avatar":""},{"name":"Colin O''Donoghue","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Andrew J. West","avatar":""},{"name":"Alison Fernández","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Era Uma Vez","Il Était une Fois","Bylo nebylo","Gyveno kartą","Érase una vez","OUAT","Once Upon a Time"]', 1784690324401);
