INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('upin-ipin-phan-11', 'Upin & Ipin (Phần 11)', 'Upin & Ipin (Season 11)', 'upin & ipin (phần 11) upin & ipin (season 11) asyiela putri siti khairunnisa hajah ainon ariff calvin tony lokeemin tang ying sowk muhammad hafiz hassan muhammad fareez daniel rufaidah mohamed fadzil usayd uqashah kamsani siti nor adwin safie irfan fahim maheswary mohan suleiman bakti azl upin & ipin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-uop-ai-cap-4', 'Xác Ướp Ai Cập 4', 'The Mummy', 'https://phimimg.com/upload/vod/20251020-1/3c734bd1e719f1cfadd72bac584ab5c1.jpg', 'https://phimimg.com/upload/vod/20251020-1/1915bf00363fc9e50dd579aead7a2b97.jpg', '<p>The Mummy là một bộ phim phiêu lưu, hành động, kinh dị do Mỹ sản xuất được đạo diễn bởi Alex Kurtzman với Jon Spaihts và Christopher McQuarrie chấm bút kịch bản. Đây là phiên bản tái khởi động của loạt phim The Mummy nổi tiếng và là bộ phim thứ hai trong Vũ trụ điện ảnh Quái vật chung của Universal sau bộ phim Dracula Untold. &nbsp;Phim có sự tham gia của dàn diễn viên tên tuổi như: Tom Cruise, Annabelle Wallis, Sofia Boutella, Jake Johnson, Marwan Kenzari, Courtney B. Vance, Russell Crowe và dự kiến được ra mắt vào ngày 9 tháng 6 năm 2017 bởi hãng phim Universal Pictures.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Cruise","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sofia Boutella","avatar":""},{"name":"Jake Johnson","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Marwan Kenzari","avatar":""},{"name":"Neil Maskell","avatar":""},{"name":"Javier Botet","avatar":""},{"name":"Andrew Brooke","avatar":""},{"name":"Selva Rasalingam","avatar":""},{"name":"Shanina Shaik","avatar":""},{"name":"Dylan Smith","avatar":""},{"name":"Hadrian Howard","avatar":""},{"name":"Rez Kempton","avatar":""},{"name":"Bella Ava Georgiou","avatar":""},{"name":"David B","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822