INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-nu-bao-thu', 'Ác Nữ Báo Thù', 'The Villainess', 'https://phimimg.com/upload/vod/20251015-1/691a94eea51713b8a9a28863647915c7.jpg', 'https://phimimg.com/upload/vod/20251015-1/1ac39795fe859160a7193687cfd52d2e.jpg', '<p>Sook Hee – một cô gái có số phận vô cùng nghiệt ngã, sau khi chứng kiến cha mình bị giết, đã được Lee Joong Sang giải cứu và huấn luyện trở thành sát thủ, hòng trở về Hàn Quốc trả thù. Sau vụ trả thù đẫm máu, Soo Hee bị Cục Tình báo Hàn Quốc bắt giữ. Nhận thấy năng lực của cô, họ đã đề nghị Sook Hee trở thành mật vụ ngầm trong vòng 10 năm. “Làm việc cho chúng tôi 10 năm, cô sẽ được tự do. Nhưng nếu thân phận của cô bị lộ, chúng tôi sẽ trừ khử cô.”</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Ok-bin","avatar":""},{"name":"Shin Ha-kyun","avatar":""},{"name":"Sung Joon","avatar":""},{"name":"Kim Seo-hyung","avatar":""},{"name":"Cho Eun-ji","avatar":""},{"name":"Lee Seung-joo","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Son Min-ji","avatar":""},{"name":"Min Ye-ji","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Seo Beom-sik","avatar":""},{"name":"Kim Jae-hyun-I","avatar":""},{"name":"Park Joo-ha","avatar":""},{"name":"Geum Hannah","avatar":""},{"name":"Jung Sung-yoon","avatar":""},{"name":"Yoon Jin-young","avatar":""},{"name":"Kwon Hyeok-beom","avatar":""},{"name":"Yeo D","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075