INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-dai-tru', 'Phương Đại Trù', 'Chef Fang', 'https://phimimg.com/upload/vod/20251014-1/8a002e9e1bf725e1a53d6abfbb8732fd.jpg', 'https://phimimg.com/upload/vod/20251014-1/a15b62aac5fce7da53a29361b37a4883.jpg', '<p>Phương Nhất Thược mất cha mẹ từ nhỏ, trải qua cuộc sống trơ trọi vất vả không nơi nương tựa, tuy đã nếm đủ khổ cực của cuộc đời, nhưng Phương Nhất Thược vẫn luôn tràn đầy hy vọng vào cuộc sống. Phương Nhất Thược sớm đã thể hiện được tài năng thiên phú trên phương diện nấu ăn, luôn có những cách xử lý khiến người ta cảm thấy ấm áp. Phương Nhất Thước không may bị người khác lập kế, bị gả cho tay ăn chơi Thẩm Dũng thay tài nữ Phương Dao trong một trận ẩu đả nhầm lẫn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lôi Giai Âm","avatar":""},{"name":"Dương Khải Trình","avatar":""},{"name":"Trương Duy Nam","avatar":""},{"name":"Lý Uyển","avatar":""},{"name":"Trương Hàm Lôi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花间提壶方大厨"]', 1784690324401);
