INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-xa-hoi-den', 'Đội Chống Xã Hội Đen', 'OCTB', 'https://phimimg.com/upload/vod/20251012-1/73c45cb85e2645b9162cd0a477592e72.jpg', 'https://phimimg.com/upload/vod/20251012-1/d5476623dd1304aa2e75aac2e72a48bc.jpg', '<p>Một bộ phim truyền hình Hong Kong nhưng không phải của TVB. Đội Chống Xã Hội Đen nói về nội gián quay trở lại làm cảnh sát, cũng có nội gián, cũng nói về những khó khăn của nội gián vì phải phản bội lại người tin cậy mình, nhưng ăn đứt Sứ Đồ về độ hấp dẫn và độ thực tế. Vì đây là phim mạng nên bạo lực hơn rất nhiều.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Jordan Chan Siu-Chun","avatar":""},{"name":"Danny Chan Kwok-Kwan","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Chen Miqi","avatar":""},{"name":"Justin Cheung Kin-Sing","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Emme Wong Yi-Man","avatar":""},{"name":"Kathy Tong Yee","avatar":""},{"name":"Alan Kuo","avatar":""},{"name":"Ashina Kwok","avatar":""},{"name":"Michael Chan Wai-Man","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Carrie Ng Ka-Lai","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Philip Chan","avatar":""},{"name":"Samuel Pang K","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["反黑2","反黑"]', 1784690324401);
