INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-than-xuyen-thoi-gian', 'Nam Thần Xuyên Thời Gian', 'A General, A Scholar and An Eunuch', 'https://phimimg.com/upload/vod/20251010-1/dc04f816649466ece25d52271c3635bb.jpg', 'https://phimimg.com/upload/vod/20251010-1/92ce7c19957059b2a2dd276aaad3b88a.jpg', '<p>Nam Thần Xuyên Thời Gian kể về 3 vị nam thần thời nhà Minh là Viên Sùng Hoán, Tả Quang Đầu cùng Lý Tấn Trung đã vô tình vượt thời gian không gian 400 năm đến thời hiện đại. Ban đầu họ vô cùng hoang mang, khi nhìn trên tivi thấy cô minh tinh rất giống Quách Thiến vị thái tử phi mất tích nên 3 người quyết tâm đi tìm và bị Phương Huệ Chi lừa gạt ký vào hợp đồng lao động làm đầu bếp cho nhà hàng của cô ta. Với tài nghệ nấu ăn xuất chúng của Tấn Trung chằng mấy chốc giúp nhà hàng trở nên nổi tiếng . Ba nam thần vẫn cô gắng tìm tung tích của thái tử phi, khi họ đọc sách lịch sữ thì biết được kết cuộc số phận của mình, lúc này thời khắc trở về thời nhà Minh đã đến liệu họ có trở về hay không? Mời các bạn đón xem Nam Thần Xuyên Thời Gian .</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 16, 2017, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Edwin Siu","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Raymond Cho Wing-Lim","avatar":""},{"name":"Matthew Ho","avatar":""},{"name":"Timothy Cheng Chi-Sing","avatar":""},{"name":"Kristal Tin Yui-Nei","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"Willie Wai Ga-Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-