INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien-sieu-anh-hung-mua-2', 'Học Viện Siêu Anh Hùng (Mùa 2)', 'My Hero Academia (Season 2)', 'học viện siêu anh hùng (mùa 2) my hero academia (season 2) daiki yamashita मेरा नायक एकेडेमिया माई हीरो एकेडेमिया ヒロアカ boku no hero academia bnha 僕のヒーローアカデミア memories 僕のヒーローアカデミア no. 170+1 more boku no hero academia: more boku no hero academia no. 170+1: more boku no hero academia: i am a hero too 나의 히어로 아카데미아 أكاديمية بطلي 我的英雄學院 final season моя геройська академія mha my hero academia: more my hero academia: i am a hero too anh hùng học viện 僕のヒーローアカデミア', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-han-la-nguoi-lon-nhung-cung-khong-phai-tre-con-miseinen-dakedo-kodomo-janai', 'Chưa Hẳn Là Người Lớn Nhưng Cũng Không Phải Trẻ Con (Miseinen dakedo Kodomo janai)', 'Teen Bride', 'https://phimimg.com/upload/vod/20250930-1/79c5c230ebddd9214d12575f9dfc8259.jpg', 'https://phimimg.com/upload/vod/20250930-1/b21409cd00c9aa6927171ed11a4d4955.jpg', '<p>Oriyama Karin 16 tuổi, một nữ sinh trung học giàu có và hư hỏng. Công chúa bị cha mẹ thúc đẩy phải kết hôn với cậu nam sinh 18 tuổi đội trưởng đội bóng đá trung học đẹp trai nổi tiếng và là idol của các cô gái – Tsuruki Nao vì lời hứa với bố mẹ cô. Karin ban đầu cảm thấy căm ghét nhưng sau đó cô ấy hiến dâng bản thân cho đam mê của tuổi trẻ và chấp nhận, vì nghĩ rằng đối với họ sẽ thoải mái bởi vì họ giàu có nhưng, bất ngờ, tổ ấm mà bố mẹ họ đã chuẩn bị là bãi rác từ những thứ họ bỏ đi để của hồi môn cho họ. Và như thể nó vẫn chưa đủ là cuộc sống như tiểu thuyết, đám cưới phải được giữ bí mật .. Đồng thời Izusu Ebina bạn thời thơ ấu của Karin cũng yêu cô ấy.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Nakajima","avatar":""},{"name":"Yuna Taira","avatar":""},{"name":"Yuri Chinen","avatar":""},{"name":"Maika Yamamoto","avatar":""},{"name":"Shingo Murakami","avatar":""},{"name":"Sylvia Grab","avatar":""},{"name":"Tomoko Ikuta","avatar":""},{"name":"Masahiro Takashima","avatar":""},{"name":"Keishi Hunt","avatar":""},{"name":"Kyosuke Ichijo","avatar":""},{"name":"Masahiro Takashima","avatar":""},{"name":"Moka Yamazaki","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["That Is Not a Child But a Minor","Miseinen dakedo kodomo janai","虽说是未成年，但可不是小孩哟","未成年だけどコドモじゃない"]', 1784690324401);
