INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-khong-ky-truyen', 'Ngộ Không Kỳ Truyện', 'Immortal Demon Slayer (Wukong)', 'https://phimimg.com/upload/vod/20250926-1/7d740914ce2ae7b3e432bf7966619cd1.jpg', 'https://phimimg.com/upload/vod/20250926-1/c9f8bfbfa334354306894ac2571c5d35.jpg', '<p>Không theo hướng thỉnh kinh tu hành như truyền thống, phim bắt đầu với sự diệt vong ở Hoa Quả Sơn. Tôn Ngộ Không quyết lên thiên đình trả mối thù nhà, mở ra câu chuyện của &quot;hầu tử&quot; chống lại số mệnh.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Vu Yến","avatar":""},{"name":"Nghê Ni","avatar":""},{"name":"Âu Hào","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu Kong zhuan","The Tales of Wukong","Legend of Wukong","Вуконг","Ву Конг","오공전","－悟空伝－","Immortal Demon Slayer","WuKong","The Legend of Wukong","ー悟空伝ー","-悟空伝-","―悟空伝―","Wùkōng Zhuàn","Wu Kong","Xi You Ji Zhi Sun Wu Kong San Da Bai Gu Jing","The Monkey King 2","悟空傳"]', 1784690324401);
