INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngo-khong-ky-truyen', 'Ngộ Không Kỳ Truyện', 'Immortal Demon Slayer (Wukong)', 'ngộ không kỳ truyện immortal demon slayer (wukong) bành vu yến nghê ni âu hào wu kong zhuan the tales of wukong legend of wukong вуконг ву конг 오공전 －悟空伝－ immortal demon slayer wukong the legend of wukong ー悟空伝ー -悟空伝- ―悟空伝― wùkōng zhuàn wu kong xi you ji zhi sun wu kong san da bai gu jing the monkey king 2 悟空傳', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-lanh-cho-the-gioi-tuyet-voi-nay-phan-2', 'Phúc Lành Cho Thế Giới Tuyệt Vời Này (Phần 2)', 'KonoSuba God''s Blessing On This Wonderful World! (Season 2)', 'https://phimimg.com/upload/vod/20250925-1/91d6907af6fb97f83470fcb1e328fec7.jpg', 'https://phimimg.com/upload/vod/20250925-1/5ed5175a8eb15d5a26aabbcae57ca968.jpg', '<p>Satou Kazuma, một hikikomori đam mê trò chơi, Nhưng cuộc sống ngắn ngủi của anh kết thúc vì tai nạn giao thông lãng xẹt ... Nhưng khi anh ta tỉnh dậy, một cô gái xinh đẹp, người tự gọi mình là một nữ thần đã ở phía trước đôi mắt anh ấy và đưa anh ấy đến một thế giới khác, Khi sang thế giới mới, cậu gặp ngày càng nhiều mấy cô nàng không điên thì cũng tâm thần, riết rồi cậu muốn quay trở về thế giới cũ càng nhanh càng tốt...</p>', 'Full', 11, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Fukushima","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["KonoSuba: As Bênçãos de Deus Neste Mundo Maravilhoso!","KonoSuba: Abençoado Mundo Maravilhoso!","素晴","素晴3","Bůh žehnej tomuto nádhernému světu","Konosuba: Un Mundo Maravilloso!","Konosuba - Sois Béni Monde Merveilleux !","KonoSuba","このすば","Kono Subarashii Sekai ni Syuk