INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuc-lanh-cho-the-gioi-tuyet-voi-nay-phan-2', 'Phúc Lành Cho Thế Giới Tuyệt Vời Này (Phần 2)', 'KonoSuba God''s Blessing On This Wonderful World! (Season 2)', 'phúc lành cho thế giới tuyệt vời này (phần 2) konosuba god''s blessing on this wonderful world! (season 2) jun fukushima sora amamiya rie takahashi ai kayano konosuba: as bênçãos de deus neste mundo maravilhoso! konosuba: abençoado mundo maravilhoso! 素晴 素晴3 bůh žehnej tomuto nádhernému světu konosuba: un mundo maravilloso! konosuba - sois béni monde merveilleux ! konosuba このすば kono subarashii sekai ni syukufuku wo! kono subarashii sekai ni shukufuku wo! 3 kono subarashii sekai ni shukufuku wo! kono subarashii sekai ni shukufuku o! 3 kono subarashii sekai ni syukufuku wo! 2 kono subarashii sekai ni syukufuku wo! 3 코노스바 konosuba: ¡una bendición para este maravilloso mundo! богиня благословляет этот прекрасный мир коносуба богиня благословляет этот замечательный мир! да благословят боги сей расчудесный мир! этот замечательный мир! 美好世界 為美好的世界獻上祝福 give blessings to this wonderful world! konosuba - god''s blessing on this wonderful world!! konosuba: god''s blessing on this wonderful world この素晴らしい世界に祝福を！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-sam-iii-tan-the-ragnarok', 'Thần Sấm III: Tận Thế Ragnarok', 'Thor: Ragnarok', 'https://phimimg.com/upload/vod/20250923-1/b3a03143b24418fea856bbee98426d35.jpg', 'https://phimimg.com/upload/vod/20250923-1/59decafde7b70d889356c7b148296018.jpg', '<p>Ở bên kia vũ trụ, Thor (Chris Hemsworth) phải bước vào một cuộc chiến đầy khốc liệt với đối thủ mà anh sẽ gặp là một đồng đội cũ đến từ biệt đội Avenger – Hulk. Cuộc tìm kiếm sự sống còn của Thor khiến anh phải chạy đua với thời gian để ngăn chặn Hela (Cate Blanchett) tiêu diệt cả thế giới anh đang sống cùng nền văn minh Asgard.</p>', 'Full', 1, 'single', 'completed', 23, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Tom Hiddleston","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Benedict Cumberbatch","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Georgia Bl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thor 3","Тор 3: Рагнарёк","ธอร์: แร็กนาร็อค","Thor 3: Ragnarok","Thor 3 - Ragnarok","Thor - Tag der Entscheidung","마블 토르: 라그나로크","Thor 3: Tag der Entscheidung","Marvel Studios'' Thor: Ragnarok","Thor 3: Tận Thế Ragnarok","토르 3","マイティ・ソー バトルロイヤル：2017","雷神3：诸神黄昏","Thor: Ragnarök","ثور راقناروك","Thor: Ragnarok"]', 1784690324401);
