INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-binh-dai-ngan-ha-2', 'Vệ Binh Dải Ngân Hà 2', 'Guardians Of The Galaxy Vol. 2', 'https://phimimg.com/upload/vod/20250917-1/487db4a6e8006f4c83a36f37c3601240.jpg', 'https://phimimg.com/upload/vod/20250917-1/bbbd7aa76bec62c78bf8986cb4b301cb.jpg', '<p>Guardians Of The Galaxy - Vệ binh dải ngân hà Phần 2 tiếp tục câu chuyện về bộ tứ huyền thoại của thiên hà. Lần này, cả nhóm sẽ bắt đầu cuộc phiêu lưu mới nhằm tìm ra bí ẩn thân thế của Star Lord – Peter Quill và viên Power Infinity Gem sở hữu sức mạnh vô song. Nhân vật anti-hero Yondu sẽ có vai trò quan trọng hơn nữa trong phần này, bên cạnh đó cô em gái Nebula của Gamora cũng sẽ trở lại.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Pratt","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Pom Klementieff","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Chris Sullivan","avatar":""},{"name":"Sean Gunn","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Laura Haddock","avatar":""},{"name":"Aaron Schwartz","avatar":""},{"name":"Hannah Gotte","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7