INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-hacker-phan-3', 'Siêu Hacker (Phần 3)', 'Mr. Robot (Season 3)', 'https://phimimg.com/upload/vod/20250905-1/31a9387e97afb26d51d435b6e40659aa.jpg', 'https://phimimg.com/upload/vod/20250905-1/c29755af70d2dc613aed7f39f2ef6dc6.jpg', '<p>Phim MR. ROBOT nói về Elliot, một lập trình viên trẻ 24 tuổi có xu hướng bài xích xã hội và tiếp xúc với những người khác bằng cách xâm nhập vào máy tính của họ. Ban ngày anh là kỹ sữ làm việc cho một công ty an ninh mạng còn ban đêm lại trở thành một hacker. Elliot gặp phải rắc rối khi 1 người tự xưng là lãnh đạo của một nhóm hacker mang tên Fsociety tuyển anh vào nhóm với mục tiêu là phá hủy tập đoàn E Corp mà công ty anh đang có hợp đồng bảo vệ an ninh mạng cho tập đoàn này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rami Malek","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Carly Chaikin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Господин Робот","Mr. Robot: Sociedade Hacker","骇客军团","Sr Robot","黑客軍團","מר. רובוט","آقای ربات","미스터 로봇","Ponas Robotas","Мистер Робот","駭客軍團","Містер Робот","Пан Робот","Janob Robot","Siêu Hacker","Misterr Robot","Mr. Robot"]', 1784690324401);
