INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-nguoi-con-gai-cua-dat-nuoc-cambuchia-nho-lai-dau-tien-ho-giet-cha-toi', 'Một Người Con Gái Của Đất Nước Cambuchia Nhớ Lại (Đầu Tiên Họ Giết Cha Tôi)', 'First They Killed My Father', 'một người con gái của đất nước cambuchia nhớ lại (đầu tiên họ giết cha tôi) first they killed my father sareum srey moch phoeung kompheak sveng socheata mun kimhak heng dara khoun sothea sarun nika run malyna oun srey neang horm chhora nout sophal tharoth sam rous mony first they killed my father: a daughter of cambodia remembers se lo llevaron. recuerdos de una niña de camboya primero mataron a mi padre: recuerdos de una hija de camboya primero mataron a mi padre: una hija de camboya recuerda önce babamı öldürdüler: kamboçyalı bir kızın anıları 他们先杀了我父亲：一个柬埔寨女儿的回忆录 primeiro, mataram o meu pai 그들이 아버지를 죽였다 primeiro, mataram meu pai មុនដំបូងខ្មែរក្រហមសម្លាប់ប៉ារបស់ខ្ញុំ moun dambaung khmer krahm samleab ba robsa khnhom first they killed my father', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-tro-ve-nha', 'Người Nhện: Trở Về Nhà', 'Spider-Man: Homecoming', 'https://phimimg.com/upload/vod/20250707-1/bba16cc8caa5fff4738e33d6c701b3e8.jpg', 'https://phimimg.com/upload/vod/20250707-1/b31b4f5bb26376354ab897033b7ce0be.jpg', '<p>Tạm biệt hai franchise về thời sinh viên, Spider-Man: Homecoming sẽ lần đầu tiên đưa các khán giả đến với cuộc sống trung học của Peter Paker – siêu anh hùng Người Nhện. Liệu một cậu bé chưa trưởng thành sẽ làm thế nào để cân bằng cuộc sống bình thường và trách nhiệm của một anh hùng giải cứu thế giới. Đây cũng là lần đầu tiên, series Người Nhện có sự tham gia sản xuất của Marvel Studio và sự xuất hiện của Iron Man – Robert Downey Jr.</p>', 'Full', 1, 'single', 'completed', 22, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Holland","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Zendaya","avatar":""},{"name":"Donald Glover","avatar":""},{"name":"Jacob Batalon","avatar":""},{"name":"Laura Harrier","avatar":""},{"name":"Tony Revolori","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Tyne Daly","avatar":""},{"name":"Abraham Attah","avatar":""},{"name":"Hannibal Buress","avatar":""},{"name":"Kenneth Choi","avatar":""},{"name":"Selenis Leyva","avatar":""},{"name":"Angou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f008490