INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-vikings-phan-5', 'Huyền Thoại Vikings (Phần 5)', 'Vikings (Season 5)', 'huyền thoại vikings (phần 5) vikings (season 5) alex høgh andersen jordan patrick smith marco ilsø peter franzén georgia hirst danila kozlovsky vikings', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-than', 'Hà Thần', 'Tientsin Mystic', 'https://phimimg.com/upload/vod/20241206-1/50a927d831ce53e75d73da1993463ef6.jpg', 'https://phimimg.com/upload/vod/20241206-1/22ae46e2b1ba2d77047275b66f7ce84b.jpg', '<p>Vào những năm dân quốc, Thiên Tân liên tục xảy ra lũ lụt, những câu chuyện về thế lực thần bí dưới sông không ngừng xuất hiện. Đội trưởng đội cảnh sát sông Quách Đắc Hữu được nhận chân truyền của sư phụ là “Lão Hà Thần”, nhờ tuyệt kĩ bật lửa giải oan, an ủi được vô số oan hồn. Hội trưởng thương hội vận chuyển đường thủy Lý Kỳ chết dưới sông. Quách Đắc Hữu bị hiềm nghi, cùng với con trai hội trưởng là Đinh Mão, thanh mai trúc mã Cố Ảnh và con gái thư ký trưởng ủy ban thành phố Thiên Tân -Tiêu Lan Lan cùng điều tra vụ án, phát hiện tất cả những hiện tượng kì lạ đều hướng về 1 câu chuyện từ 20 năm trước. Hồi ấy có một tổ chức tà giáo tên “Ma Cổ Đạo” hoành hành khắp khu vực Bắc Kinh và Hà Bắc. 20 năm sau, Quách Đắc Hữu và Đinh Mão lại lần nữa phát hiện dấu vết của “Ma Cổ Đạo”. Bốn người Quách Đắc Hữu, Đinh Mão, Cố Ảnh, Tiêu Lan Lan vì ngăn chặn sự khôi phục của Ma Cổ Đạo mà bị cuốn vào từng vụ án ly kỳ hấp dẫn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"Trương Minh Ân","avatar":""},{"name":"Vương Tử Tuyên","avatar":""},{"name":"Trần Dự Mễ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["河神之魔古道","He Shen","河神2","Мистик из Теньцинь 2","Речной дух","Тяньцзиньская загадка","Тяньцзиньская мистика","河神","河神Ⅱ"]', 1784690324401);
