INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ha-than', 'Hà Thần', 'Tientsin Mystic', 'hà thần tientsin mystic lý hiện trương minh ân vương tử tuyên trần dự mễ 河神之魔古道 he shen 河神2 мистик из теньцинь 2 речной дух тяньцзиньская загадка тяньцзиньская мистика 河神 河神ⅱ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-phu-thuy', 'Công Tố Viên Phù Thủy', 'Witch''s Court', 'https://phimimg.com/upload/vod/20250819-1/f298e9c5b6a39b9f416aa0b9c1fa8f00.jpg', 'https://phimimg.com/upload/vod/20250819-1/d4f80fde90ad7e87b7b0a880ea18b147.jpg', '<p>Ma Yi-Deum là một nữ công tố viên có 7 năm kinh nghiệm. Cô nổi tiếng vì tính cách cứng rắn, sẵn sàng dùng mọi cách (dù không mấy chính thống) để giành chiến thắng trong các vụ án. Một ngày, cô bị điều chuyển sang đơn vị đặc biệt chuyên xử lý tội phạm tình dục. Từ đây, Ma Yi-Deum phải đối diện những vụ án khó khăn, đồng thời học cách thay đổi, trưởng thành hơn trong cả công việc lẫn cuộc sống.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Ryeo-won","avatar":""},{"name":"Yoon Hyun-min","avatar":""},{"name":"Jun Kwang-ryul","avatar":""},{"name":"Kim Min-seo","avatar":""},{"name":"Kim Yeo-jin","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Jo Woo-ri","avatar":""},{"name":"Kim Kwon","avatar":""},{"name":"Choi Ri","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Baek Chul-Min","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Tae Won-seok","avatar":""},{"name":"Park Shi-woo","avatar":""},{"name":"Jeong Jae-kwang","avatar":""},{"name":"Ju Min-ha","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Don''t Trust Her","Witch''s Courtroom","Don''t Believe Her","Witch at Court","마녀의 법정"]', 1784690324401);
