INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-9-logan-tran-chien-cuoi-cung', 'X-Men 9: Logan - Trận Chiến Cuối Cùng', 'Logan', 'https://phimimg.com/upload/vod/20250817-1/4e1662277f178f7d79325ffc10657d27.jpg', 'https://phimimg.com/upload/vod/20250817-1/69b267c24435b844ca4086a0f0ea65ff.jpg', '<p>Lấy bối cảnh năm 2029, giống loài dị nhân gần như bị tuyệt diệt. Wolverine lúc này phải đối mặt với sự lão hóa cả về thể chất lẫn khả năng phục hồi. Anh cùng với Giáo sư X, người lúc này đang mắc chứng bệnh Alzheimer, phải hợp sức để bảo vệ cô bé dị nhân Laura Kinney. Đối chọi với một đội quân ác nhân mạnh mẽ do Donald Pierce dẫn đầu và một tổ chức khổng lồ bí ẩn ở phía sau, liệu họ có bảo toàn được tính mạng và viết tiếp câu chuyện của mình ...</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Dafne Keen","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Elizabeth Rodriguez","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Stephen Dunlevy","avatar":""},{"name":"Eriq La Salle","avatar":""},{"name":"Elise Neal","avatar":""},{"name":"Quincy Fouse","avatar":""},{"name":"Al Coronel","avatar":""},{"name":"Frank Gallegos","avatar":""},{"name":"Anthony Escobar","avatar":""},{"name":"Reynaldo Gallegos","avatar":""},{"name":"Krzysztof Soszynsk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{