INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-su-nang-uhwoo', 'Tình Sử Nàng Uh-woo', 'Goddess Eowoodong', 'https://phimimg.com/upload/vod/20250806-1/3fd90287eea4f0e6fcc7a8871d020e17.jpg', 'https://phimimg.com/upload/vod/20250806-1/7f23910bba51771dfb7d4c03e528fcd0.jpg', '<p>Vì vẻ quyến rũ khó cưỡng của Eowoodong, đàn ông trong khu phố mất ăn mất ngủ. Bị truy bắt vì gây náo loạn, cô bỏ trốn đến một ngôi làng, nơi cô bị ngã và mất trí nhớ. Một chàng trai độc thân trong làng tìm thấy, chăm sóc và cho cô ở nhờ cho đến khi nhớ lại mọi chuyện. Nhưng ở làng nhỏ, tin đồn về sắc đẹp của Eowoodong lan nhanh, khơi dậy bản năng khao khát của những người đàn ông nơi đây.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim In-ae","avatar":""},{"name":"Lee Da-min","avatar":""},{"name":"Lee Yoo-chan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shin Eun Dong","Goddess Eowoodong","신어우동"]', 1784690324401);
