INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-thuy-danh-bo-5-chien-truong', 'Lính Thủy Đánh Bộ 5: Chiến Trường', 'The Marine 5: Battleground', 'https://phimimg.com/upload/vod/20250804-1/6fd70a7f32127c88e9b27fd654d590f1.jpg', 'https://phimimg.com/upload/vod/20250804-1/62b0f5c47825fdf690c60dac02194289.jpg', '<p>Khi đang làm việc với tư cách là một EMT ở tiểu bang, Jake Carter sau khi trả lời một cuộc gọi khẩn cấp, nhận ra mình đang bảo vệ một người được quan tâm khỏi một băng nhóm đua xe đạp đang săn lùng họ một cách tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mike Mizanin","avatar":""},{"name":"Anna Van Hooft","avatar":""},{"name":"Joe Hennig","avatar":""},{"name":"Sharon Crandall","avatar":""},{"name":"Maryse Mizanin","avatar":""},{"name":"Trinity Fatu","avatar":""},{"name":"Heath Miller","avatar":""},{"name":"Brad Kelly","avatar":""},{"name":"Tony Skinner","avatar":""},{"name":"Nathan Mitchell","avatar":""},{"name":"Taylor Rotunda","avatar":""},{"name":"Sandy Robson","avatar":""},{"name":"Yusuf A. Ahmed","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["海军陆战队员5","怒火反击5","怒火街头5","마린 5: 배틀그라운드","The Marine 5: Battleground"]', 1784690324401);
