INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-dia-nguc', 'Đảo Địa Ngục', 'The Battleship Island', 'https://phimimg.com/upload/vod/20250804-1/d233455311b457717762da8f0db1091f.jpg', 'https://phimimg.com/upload/vod/20250804-1/7f308707e7fa49b622a31565c8ad9348.jpg', '<p>Lấy bối cảnh thời người dân Triều Tiên bị Nhật Bản đô hộ, Đảo Địa Ngục là khúc ca bi tráng về cuộc đấu tranh và trốn thoát của 400 người lao động khỏi hòn đảo Hashima. Có kinh phí 26 triệu $, đây là bom tấn lớn nhất mùa hè của xứ sở Kim Chi. Phim có sự tham gia của dàn ngôi sao hạng A Hàn Quốc như Song Joong Ki, So Ji Sub, Lee Jung Hyun… &nbsp;Hashima là một hòn đảo nằm giữa đại dương được xây dựng vô cùng kiên cố, với các hầm lò ở độ sâu 1000m so với mực nước biển. Những tù nhân Triều Tiên ở đây bị quân đội Nhật giam cầm và bóc lột sức lao động bằng cách bắt họ khai thác than trong điều kiện hết sức tồi tệ và có thể mất mạng bất cứ lúc nào. Không thể trốn, cũng không thể chết. Làm cách nào 400 người lại có thể đào thoát khỏi hòn đảo địa ngục này?</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-min","avatar":""},{"name":"So Ji-sub","avatar":""},{"name":"Song Joong-ki","avatar":""},{"name":"Lee Jung-hyun","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kim In-woo","avatar":""},{"name":"Kim Joong-hee","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Shin Seung-hwan","avatar":""},{"name":"Kim Yae-eun","avatar":""},{"name":"Jo Kyung-hyun","avatar":""},{"name":"Kim Kyu-baek","avatar":""},{"name":"Yoon Dae-yeul","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Park Seong-il","avatar":""},{"name":"Uhm Ji-sung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["The Battleship Island","Nagy szökés a tengeri Gulagról","Gunhamdo","Battleship Adası","Hashima Kömür Madeni","Battleship Island","جزيرة البارجة","군함도"]', 1784690324401);
