INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-phap-su-phan-1', 'Cô Dâu Pháp Sư (Phần 1)', 'The Ancient Magus'' Bride (Season 1)', 'https://phimimg.com/upload/vod/20250728-1/2563dc41655c8bab807b5b03b99f8aac.jpg', 'https://phimimg.com/upload/vod/20250728-1/b9f517170741b0c5a9162343eb2574d0.jpg', '<p>Anime Cô Dâu Của Pháp Sư kể về Chise Hatori một cô gái mất gia đình phải sống lang thang. Cô bị bắt bán vào một phiên đấu giá nô lệ. Khi cuộc sống của cô không còn ý nghĩa gì nữa thì một người đàn ông có sức mạnh kỳ lạ với cái đầu của một con thú xuất hiện giải phóng cô khỏi xiềng xích nô lệ tuyên bố rằng cô sẽ là học việc và là cô dâu của ông ta.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Atsumi Tanezaki","avatar":""},{"name":"Ryota Takeuchi","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Minami Tsuda","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Daiki Kobayashi","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Koutaro Nishiyama","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Mutsumi Tamura","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Die Braut des Magiers","La novia del mago antiguo","魔法师的爱徒","The Ancient Magus'' Bride","Mahoutsukai no Yome","魔法使いの嫁 SEASON2","Mahou Tsukai no Yome","Mahoyome","عرو