INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-dau-phap-su-phan-1', 'Cô Dâu Pháp Sư (Phần 1)', 'The Ancient Magus'' Bride (Season 1)', 'cô dâu pháp sư (phần 1) the ancient magus'' bride (season 1) atsumi tanezaki ryota takeuchi koki uchiyama aya endo minami tsuda maki kawase seiichiro yamashita daiki kobayashi reina ueda koutaro nishiyama satoshi hino mutsumi tamura die braut des magiers la novia del mago antiguo 魔法师的爱徒 the ancient magus'' bride mahoutsukai no yome 魔法使いの嫁 season2 mahou tsukai no yome mahoyome عروس الساحر القديم oblubienica czarnoksiężnika 魔法使的新娘 第二季 魔法使的新娘 魔法使いの嫁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-xe-taxi', 'Tài Xế Taxi', 'A Taxi Driver', 'https://phimimg.com/upload/vod/20250725-1/1c7fa088eaebac01a0776b41d0b41606.jpg', 'https://phimimg.com/upload/vod/20250725-1/fc6a46f39f0e1dc30b5c57f0b14bf0fe.jpg', '<p>Dựa theo câu chuyện có thật của Phóng viên người Đức Jürgen Hinzpeter và lái xe taxi người Hàn Quốc Kim Sa-Bok. Bối cảnh của A taxi drive được lấy vào tháng 5 của năm 1980, lúc này phóng viên người Đức tên là Peter (Thomas Kretschmann) đang làm việc tại Tokyo, nhưng ở đó tin tức được cập nhật rất chậm. Anh nghe tin từ một đồng nghiệp rằng có một điều gì đó đáng ngại xảy ra ở Gwangju, Hàn Quốc. Các đường dây điện thoại đã bị cắt hoàn toàn trong phạm vi toàn thành phố. Vì thế mà Peter quyết định đến đó để tìm hiểu sự việc.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Yoo Hai-jin","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Park Hyuk-kwon","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Cha Soon-bae","avatar":""},{"name":"Shin Dam-su","avatar":""},{"name":"Ryu Sung-hyun","avatar":""},{"name":"Um Tae-goo","avatar":""},{"name":"Min-hee Park","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Eun-mi Yoo","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Joey Albright","avatar":""},{"name":"Jung Jin-you","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Taeksi Woonjunsa","택시운전사","A Taxi Driver","Egy taxisofőr","Taeksi woonjunsa","出租车司机(2017)","我只是個計程車司機","逆權司機","سائق تاكسي","Таксист"]', 1784690324401);
