INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-xe-taxi', 'Tài Xế Taxi', 'A Taxi Driver', 'tài xế taxi a taxi driver song kang-ho thomas kretschmann yoo hai-jin ryu jun-yeol park hyuk-kwon choi gwi-hwa cha soon-bae shin dam-su ryu sung-hyun um tae-goo min-hee park lee jung-eun eun-mi yoo seo hyun-woo ko chang-seok jeon hye-jin joey albright jung jin-you taeksi woonjunsa 택시운전사 a taxi driver egy taxisofőr taeksi woonjunsa 出租车司机(2017) 我只是個計程車司機 逆權司機 سائق تاكسي таксист', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-bi-mat-phan-1', 'Khu Rừng Bí Mật (Phần 1)', 'Stranger (Season 1)', 'https://phimimg.com/upload/vod/20250723-1/dee2d16109b6b6de87cb5e2745b85f4c.jpg', 'https://phimimg.com/upload/vod/20250723-1/0c0b55315f61939fd3942dd9b717c190.jpg', '<p>Công tố viên Hwang Shi Mok (Jo Seung Woo) và nữ cảnh sát Han Yeo Jin (Bae Doo Na) sẽ là những người lật mở từng bí mật trong “khu rừng&quot;, bắt đầu từ một vụ án mạng mà nạn nhân có liên quan trực tiếp tới những kẻ máu mặt trong văn phòng công tố, còn kẻ bị tình nghi là một người đàn ông luôn miệng phủ nhận tội danh giết người cướp của. Hwang Shi Mok là một tên máu lạnh thực sự, anh ta đã mất đi cảm xúc kể từ sau ca phẫu thuật não khi còn nhỏ. Mục tiêu của anh ta trong vụ án lần này không phải là Kang Jin Sub (Yoon Kyung Ho), người đang bị tình nghi. Những manh mối tại hiện trường và tiết lộ của nạn nhân vài ngày trước khi chết đủ để khiến Hwang Shi Mok nhắm vào những con cá to hơn, trong khi vẫn để một nữ công tố viên vừa kết thúc đợt thực tập 6 tháng đẩy Kang Jin Sub vào tù. Một kẻ tin rằng mình oan uổng sẽ không chịu ngồi tù 22 năm, hắn quyết tâm dùng chính cái chết của mình để tiêu diệt tên công tố viên ấy trước dư luận.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2017, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Seung-woo","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Choi Jae-woong","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Song Ji-ho","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name":"Kim Hak-seon","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Yoon Tae-in","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Secret Forest (Stranger)","秘密森林","Bimilui Soop","جنگل مخفی","جنگل اسرار","비밀의 숲","Stranger","Тайный лес","Таємний ліс","Stranger (2017)","Forest of Secrets"]', 1784690324401);
