INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-no-mau', 'Vùng Đất Quỷ Dữ: Nợ Máu', 'Resident Evil: Vendetta', 'https://phimimg.com/upload/vod/20250716-1/b826b3158b9724149b6730539b8b0c8f.jpg', 'https://phimimg.com/upload/vod/20250716-1/9084f5e88a9fa1138f466912d6e9d188.jpg', '<p>Resident Evil: Vendetta xoay quanh bộ ba Chris Redfield, Leon Scoot Kennedy và Rebecca Chambers có mặt ở thành phố New York để ngăn cản cuộc tấn công khủng bố sinh học đang bùng phát với zombie cũng như nhiều sinh vật đột biến quái dị hơn. Âm mưu phá hoại thành phố được thực hiện bởi nhân vật phản diện mang tên Glenn Arias.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Kevin Dorman","avatar":""},{"name":"Matthew Mercer","avatar":""},{"name":"Erin Cahill","avatar":""},{"name":"John DeMita","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Cristina Valenzuela","avatar":""},{"name":"Arif S. Kinchen","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Arnie Pantoja","avatar":""},{"name":"Alexander Polinsky","avatar":""},{"name":"Jason Faunt","avatar":""},{"name":"Mary Elizabeth McGlynn","avatar":""},{"name":"Karen Strassman","avatar":""},{"name":"Fryda Wolff","avatar":""},{"name":"Jason Hightower","avatar":""},{"name":"Darin De P","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Biohazard: Vendetta","Resident Evil 3 - Vendetta","惡靈古堡：血仇","Baiohazādo Vendetta","바이오해저드: 벤데타","Resident Evil: Vendetta","生化危机