INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-than-chet-giua-hai-the-gioi', 'Thử Thách Thần Chết: Giữa Hai Thế Giới', 'Along With The Gods: The Two Worlds', 'https://phimimg.com/upload/vod/20250701-1/ad492afad6ecb8825b6d40cc6df004e9.jpg', 'https://phimimg.com/upload/vod/20250701-1/8ed1e20265e06bac81be10aef1cc828c.jpg', '<p>Thần hộ vệ Kang Rim được giao nhiệm vụ đưa Ja Hong đến 7 thử thách trong vòng 49 ngày trước khi về với Thế giới của Thần Chết Yeomra. Cuộc hành trình sau cái chết này chính là bài khảo sát cho Thần Chết Yeomra thấy được bản chất linh hồn của Ja Hong và sẽ đưa ra quyết định phán xét cuối cùng cho anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Ju Ji-hoon","avatar":""},{"name":"Kim Hyang-gi","avatar":""},{"name":"Lee Jung-jae","avatar":""},{"name":"Kim Dong-wook","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Im Won-hee","avatar":""},{"name":"Sung Yu-been","avatar":""},{"name":"Goo Seung-hyun","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Doh Kyung-soo","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kim Ha-neul","avatar":""},{"name":"Jang Kwa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a