INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tau-y-duc', 'Con Tàu Y Đức', 'Hospital Ship', 'https://phimimg.com/upload/vod/20250508-1/c4ce81c654529901b8acafb3b983a2a3.jpg', 'https://phimimg.com/upload/vod/20250508-1/862fffef71e04f4841ef2ff545437d0b.jpg', '<p>Xoay quanh câu chuyện về tình yêu, cuộc sống và nghề nghiệp của một đội ngũ bác sĩ trẻ, cũng như hành trình trưởng thành của họ trên những chuyến tàu y tế phục vụ người dân sống ngoài đảo xa. Chính những lần ra sức chữa bệnh cho người gặp nạn đã giúp mỗi người trong số họ tự chữa lành những vết thương trong tâm hồn mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Ji-won","avatar":""},{"name":"Kang Min-hyuk","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Jung Kyung-soon","avatar":""},{"name":"Kwon Min-a","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Kim In-sik","avatar":""},{"name":"Jang Seo-won","avatar":""},{"name":"Lee Seo-won","avatar":""},{"name":"Cha Hwa-yeon","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Kim Tae I","avatar":""},{"name":"Lee Tae-ri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hospital Ship","병원선"]', 1784690324401);
