INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-ky-phien-loan', 'Thời Kỳ Phiến Loạn', 'The Age Of Blood', 'https://phimimg.com/upload/vod/20250619-1/c310dadb22c5c0a2556c7d2fc2f1435a.jpg', 'https://phimimg.com/upload/vod/20250619-1/d26d789b2cc35199f4ab292daf07b455.jpg', '<p>Kim Ho, tay kiếm đệ nhất thời Joseon, đã biết toàn bộ âm mưu tạo phản của Yi In Jwa cùng đồng bọn. Từ đó, anh phải đơn độc cố sức bảo vệ vua Yeong Jo vì chẳng thể tin tưởng được bất cứ ai.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Hae-in","avatar":""},{"name":"Kim Ji-hun","avatar":""},{"name":"Lee Won-jong","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Hong Soo-ah","avatar":""},{"name":"Ryu Tae-joon","avatar":""},{"name":"Hong Seung-jin","avatar":""},{"name":"Kwon Hae-sung","avatar":""},{"name":"Lee Kyu-bok","avatar":""},{"name":"Jeon Seong-ryeol","avatar":""},{"name":"Geum Dan-bi","avatar":""},{"name":"Jung Ji-hoon","avatar":""},{"name":"Lee Tae-geom","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Lee Jae-yong","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Song Min-hyung","avatar":""},{"name":"Kim Ik-tae","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yeongmo - Ballanui sidae","Conspiracy: Age of Rebellion","Two Constables","逆謀 反乱の時代","역모: 반란의 시대","역모 ; 반란의 시대","역모 - 반란의 시대"]', 1784690324401);
