INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-huong-cang', 'Trùm Hương Cảng', 'Chasing the Dragon', 'https://phimimg.com/upload/vod/20250619-1/390c62111a77904db16cb70c5bb40e62.jpg', 'https://phimimg.com/upload/vod/20250619-1/fed2e90c850f95745f4721cf6533b148.jpg', '<p>Nội dung phim xoay quanh một người nhập cư bất hợp pháp từ Trung Quốc đại lục tên là Hào (Chân Tử Đan), người đã tìm cách lẻn sang Hồng Kông vào năm 1963. Từ một tay giang hồ không có số má, nhưng khả năng đánh đấm cùng với sự liều lĩnh hơn người, anh ta nhanh chóng được trọng dụng rồi từ từ gây dựng chỗ đứng cho mình. Sau một thời gian dài trải qua sự mài giũa của xã hội, sự cạnh tranh khốc liệt trong cuộc sống mưu sinh cho tới những biến cố trong cuộc đời đã biến anh ta thành một tên trùm ma túy tàn nhẫn và cực kỳ quyền lực, được ví như một ông vua của tất cả những tay trùm ma túy tại nơi đây. Đặc biệt, anh còn có mối quan hệ thân thiết với một thám trưởng do Lưu Đức Hoa thủ vai, 2 người cùng nhau kiếm tiền qua các phi vụ phi pháp để rồi cùng trở thành những người giàu bậc nhất <span style="text-wrap-mode: wrap;">Hồng Kông</span> tại thời điểm đó.</p>', 'Full', 1, 'single', 'completed', 34, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Chân Tử Đan","avatar":""},{"name":"Lưu Đức Hoa","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Ngũ Doãn Long","avatar":""},{"name":"Lữ Lương Vĩ","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Khương Hạo Văn","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Trần Quốc Bang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["Chui lung","Chasing the Dragon","추룡","CHASING THE DRAGON*","Chasing the Dragon 追龍 (2017)","Chasing the Dragon (2017)","追龙","Chasing the Dragon I","追龍"]', 1784690324402);
