INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-thich-anh-yeu-em', 'Thình Thịch Anh Yêu Em', 'Memory Love', 'https://phimimg.com/upload/vod/20250618-1/635d9217de457338f7d066044f16e69a.jpg', 'https://phimimg.com/upload/vod/20250618-1/15c65ed0308a259a9db2430529334ad8.jpg', '<p>Thình Thịch Thình Thịch Anh Yêu Em bắt đầu khi đầu bếp tráng miệng hàng đầu Hình Thiếu Thiên và cô gái quay về Đài Loan tìm cha Kim Giai Ân tình cờ chạm mặt nhau ở sân bay. Sau đó Giai Ân và bạn trai Tu Khải gặp phải tai nạn giao thông, Tu Khải bị chết não còn Giai Ân bị mất trí nhớ, Giai Ân bị Tiểu Phi lừa rằng cô là Triệu Ngải Lệ để trốn nợ. Trong khi trái tim của Tu Khải được tặng cho Hình Thiếu Thiên, từ đó con người lạnh lùng của Thiếu Thiên dần có tình cảm ấm áp dịu dàng mà anh chưa từng có. Thình Thịch Thình Thịch, trái tim anh đập vì em...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 16, 2017, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Ngạn Tuấn","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Thẩm Tinh Hà","avatar":""},{"name":"Trần Bách Vũ","avatar":""},{"name":"Dương Nhất Huyên","avatar":""},{"name":"Ngô Lập Văn","avatar":""},{"name":"Tăng Kỳ Như","avatar":""},{"name":"Trần Tử Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["사랑은 두근두근: 박통박통아애니","박통박통아애니","噗通噗通我愛你"]', 1784690324402);
