INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-thien-nga-noi-gian-hoang-gia', 'Công Chúa Thiên Nga: Nội Gián Hoàng Gia', 'The Swan Princess: Royally Undercover', 'https://phimimg.com/upload/vod/20250610-1/a929b0a610b3a9a821e76da376c2de88.jpg', 'https://phimimg.com/upload/vod/20250610-1/be8639b6b3b1830a16b982671bdc42f5.jpg', '<p>Sau khi những vị khách bí ẩn đến Vương quốc, Công chúa Alise, Lucas và những người bạn đã bí mật thực hiện một cuộc phiêu lưu gián điệp để xem liệu các vị khách có thể tin tưởng được hay không. Họ sẽ cần tất cả các kỹ năng thám tử siêu việt cũng như một số dụng cụ siêu thú vị để giải quyết bí ẩn hoàng gia và cứu Vương quốc.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2017, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Laura Bailey","avatar":""},{"name":"Brian Nissen","avatar":""},{"name":"Grant Durazzo","avatar":""},{"name":"Gardner Jaas","avatar":""},{"name":"James Clayton","avatar":""},{"name":"David Lodge","avatar":""},{"name":"Jennifer Miller","avatar":""},{"name":"Christine Lakin","avatar":""},{"name":"Joseph Medrano","avatar":""},{"name":"Joe Ochman","avatar":""},{"name":"Doug Stone","avatar":""},{"name":"Kirk Thornton","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["La Princesa Encantada Mision Secreta","La Princesa Espía 7: Misión Secreta","The Swan Princess 7","Svaneprinsessen 7 En Kongelig Forklaedning","백조공주: 비밀 작전","Le Cygne et la Princesse: En mission secrète","L''incantesimo del lago: missione spie","Svaneprinsessen: Majestetiske agenter","A Princesa Encantada: A Espiã","Printesa Lebãdã: Sub acoperire regalã","Принцесса Лебедь 7: Королевское прикрытие","Prenses ve Kurbağa: Ajanlar İş Başında","סוד הממלכה הקסומה: חשאיות מלכותית","The Swan Princess: Royally Undercover"]', 1784690324402);
