INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-hiem', 'Không Lối Thoát Hiểm', 'Only the Brave', 'https://phimimg.com/upload/vod/20250531-1/1d5c8b074287043584dbf0a333881e0e.jpg', 'https://phimimg.com/upload/vod/20250531-1/e68a94510cbe947090a6b274e1da4ed9.jpg', '<p>Dựa trên sự kiện có thật về thảm hoạ kinh hoàng ở núi Granite, thuộc bang Arizona, Mỹ. 19 đặc nhiệm cứu hoả đã phải đối đầu với lựa chọn sinh tử! Thảm hoạ sẽ không hề thông cảm cho bất kỳ hoàn cảnh cá nhân nào. Lối thoát ở đâu khi phía trước là đường cùng? Đây được xem là một trong những vụ cháy kinh hoàng nhất lịch sử nước Mỹ!</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Josh Brolin","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Alex Russell","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Geoff Stults","avatar":""},{"name":"Thad Luckinbill","avatar":""},{"name":"Ben Hardy","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Jake Picking","avatar":""},{"name":"Scott Foxx","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"Ryan Michael Busch","avatar":""},{"name":"Kenneth Miller","avatar":""},{"name":"Ry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["No Exit","Only The Brave","Granite Mountain","Seuls les braves","온리 더 브레이브","Héroes en el Infierno","Homens de Coragem","Héroes en el infierno","No Way Out - Gegen die Flammen","Só Para Bravos","Line of Fire","オンリー・ザ・ブレイブ：2017","Дело храбрых","Only the Brave"]', 1784