INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham-nhan-ban-2049', 'Tội Phạm Nhân Bản 2049', 'Blade Runner 2049', 'https://phimimg.com/upload/vod/20250526-1/47cf1c718a533e0e05b24ad2c99da768.jpg', 'https://phimimg.com/upload/vod/20250526-1/c2f16d5873f9bbd24c6c951ff88bf1b9.jpg', '<p>Một chàng trai trẻ khám phá ra bí mật khiến xã hội rơi vào cảnh hỗn mang. Anh lên đường đi tìm một người khác đã mất tích cách đây ba mươi năm, để rồi cả hai cùng bước vào hành trình cứu thế giới. 35 năm sau ngày phần đầu tiên ra mắt, Blade Runner trở lại với những gương mặt mới, câu chuyện mới, đầy hứa hẹn vẫn sẽ giữ được cái “chất” khiến thương hiệu này trở thành tác phẩm kinh điển trong lịch sử điện ảnh. Nhà sản xuất vừa tung ra trailer đầu tiên của phim do bộ đôi Ridley Scott - sản xuất và Denis Villeneuve - đạo diễn với vô số tình tiết bất ngờ có thể hứa hẹn đây là sẽ bom tấn đáng để chúng ta ra rạp thưởng thức. Phim được xem là tác phẩm kinh điển của thể loại khoa học viễn tưởng.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Sylvia Hoeks","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Carla Juri","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Lennie James","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Sean Young","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"Barkhad Abdi","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Tómas Lemarquis","avatar":""},{"name":"Salli","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b4