INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goi-em-bang-ten-anh', 'Gọi Em Bằng Tên Anh', 'Call Me by Your Name', 'https://phimimg.com/upload/vod/20250526-1/2e537d1c5159d2224a48813b9861b8e1.jpg', 'https://phimimg.com/upload/vod/20250526-1/ffdee4361d1f6101331cbb035f8f45d1.jpg', '<p>Gọi Em Bằng Tên Anh được chuyển thể từ tiểu thuyết cùng tên của nhà văn André Aciman, lấy bối cảnh những năm 80. Nội dung tập trung vào mối quan hệ đầy cảm hứng giữa cậu bé 17 tuổi Elio (Timothée Chalamet) và chàng sinh viên 24 tuổi Oliver (Armie Hammer). &nbsp;Oliver là sinh viên khảo cổ học người Mỹ đến ở trong biệt thự nhà Elio và theo học giáo sư là bố của cậu bé. Hai chàng trai trẻ đã bị cuốn vào một mối tình lãng mạn giữa khung hình tuyệt đẹp của miền quê nước Ý trong một mùa hè rực rỡ năm 1983.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Armie Hammer","avatar":""},{"name":"Timothée Chalamet","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Amira Casar","avatar":""},{"name":"Esther Garrel","avatar":""},{"name":"Victoire du Bois","avatar":""},{"name":"Vanda Capriolo","avatar":""},{"name":"Antonio Rimoldi","avatar":""},{"name":"Elena Bucci","avatar":""},{"name":"Marco Sgrosso","avatar":""},{"name":"André Aciman","avatar":""},{"name":"Peter Spears","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chiamami col tuo nome","Skrivena ljubav","君の名前で僕を呼んで","Vadink mane savo vardu","Strigă-mă pe numele tău","Zovi me svojim imenom","Зови меня своим именем","Poklici me po svojem imenu","Më thirr me emrin tënd","Llámame por tu nombre","Chama-me Pelo Teu Nome","Me Chame Pelo Seu Nome","Tamte dni, tamte noce","Να με φωνάζεις με τ'' όνομά σου","Dej mi své jméno","콜 미 바이 유어 네임","Məni Öz Adınla Çağır","请以你的名字呼唤我","CMBYN","نادني باسمك","Կոչիր Ինձ Քո Անունով","Kochir indz qo anunov","هل من الأفضل الكلام أم الموت؟","الدنيا بعينك","მომმართე შენი სახელით","Call Me by Your Name"]', 1784690324402);
