INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('goi-em-bang-ten-anh', 'Gọi Em Bằng Tên Anh', 'Call Me by Your Name', 'gọi em bằng tên anh call me by your name armie hammer timothée chalamet michael stuhlbarg amira casar esther garrel victoire du bois vanda capriolo antonio rimoldi elena bucci marco sgrosso andré aciman peter spears chiamami col tuo nome skrivena ljubav 君の名前で僕を呼んで vadink mane savo vardu strigă-mă pe numele tău zovi me svojim imenom зови меня своим именем poklici me po svojem imenu më thirr me emrin tënd llámame por tu nombre chama-me pelo teu nome me chame pelo seu nome tamte dni, tamte noce να με φωνάζεις με τ'' όνομά σου dej mi své jméno 콜 미 바이 유어 네임 məni öz adınla çağır 请以你的名字呼唤我 cmbyn نادني باسمك կոչիր ինձ քո անունով kochir indz qo anunov هل من الأفضل الكلام أم الموت؟ الدنيا بعينك მომმართე შენი სახელით call me by your name', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-chuyen-phan-1', 'Lắm Chuyện (Phần 1)', 'Big Mouth (Season 1)', 'https://phimimg.com/upload/vod/20241121-1/b9b979832ff1586293248a41bdb5a6e1.jpg', 'https://phimimg.com/upload/vod/20241121-1/71294e3ac62e422c05e41fdefedf0259.jpg', '<p>Các bạn tuổi teen thấy cuộc sống đảo ngược bởi những điều kỳ diệu và kinh hoàng tuổi dậy thì trong bộ phim hài hước sắc sảo của Nick Kroll và Andrew Goldberg.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Kroll","avatar":""},{"name":"John Mulaney","avatar":""},{"name":"Jessi Klein","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Jordan Peele","avatar":""},{"name":"Maria Bamford","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Ali Wong","avatar":""},{"name":"Chelsea Peretti","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Zachary Quinto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["فم كبير","大嘴巴","Hormonokkal túlfűtve","פה גדול","ビッグマウス","빅마우스","Gură bogată","青春無密語","Bigmouth","Big Mouth"]', 1784690324402);
