INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-chuyen-tham-hiem-nam-cuc-kachi-kochi', 'Doraemon: Nobita và Chuyến Thám Hiểm Nam Cực Kachi Kochi', 'Doraemon: Nobita''s Great Adventure in the Antarctic Kachi Kochi', 'https://phimimg.com/upload/vod/20250521-1/d3a4ca0b84240945009390deb31cb977.jpg', 'https://phimimg.com/upload/vod/20250521-1/5f2086e79b8e7a0c6cd84393a4951170.jpg', '<p>Để tránh cái nóng oi bức của mùa hè, Nobita và những người bạn đã tìm đến một tảng băng trôi lớn và tự xây cho mình một công viên bằng băng từ những bảo bối của Doraemon. Trong lúc ấy, nhóm bạn vô tình tìm được chiếc nhẫn lạ bị chôn vùi trong băng đá. Qua nhiều nỗ lực tìm hiểu, những người bạn nhỏ đã khám phá ra rằng xuất xứ của chiếc nhẫn này là từ vùng Nam Cực ở quá khứ 100,000 năm về trước. Với khát khao mạnh mẽ nhằm tìm kiếm chủ nhân của nó, Doraemon và những người bạn quyết định thực hiện một chuyến hành trình đến Nam Cực. Ở đó, họ đã phát hiện ra dấu tích của một thành phố khổng lồ chìm trong băng.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2017, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Masumi Yagi","avatar":""},{"name":"Shigeo Takahashi","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Ayaka Hirahara","avatar":""},{"name":"Mai Asada","avatar":""},{"name":"Nobunari Oda","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Doraemon: Nobita và chuyến thám hiểm Nam Cực Kachi Kochi","โดราเอมอน ตอน โนบิตะผจญภัยในแอนตาร์กติกแห่งคะจิโคะจิ","Eiga Doraemon: Nobita no nankyoku kachikochi daibouken","도라에몽: 노비타의 남극 꽁꽁대모험","Doraemon - Il Film: Nobita e la grande avventura in Antartide","映画ドラえもん のび太の南極カチコチ大冒険","哆啦A夢：大雄的南極冰天雪地大冒險","Doraemon y la gran aventura en la Antártida","哆啦A梦：大雄的南极冰冰凉大冒险","Doraemon Nobita and the Great Adventure in the Antarctic Kachi Kochi","Eiga Doraemon Nobita No Nankyoku Kachi Kochi Daibouken","哆啦A梦：大雄的南极冰雪大冒险","Doraemon: Great Adventure in the Antarctic Kachi Kochi","哆啦A梦 大雄的南极冰冰凉大冒险"]', 1784690324402);
