INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-chuyen-tham-hiem-nam-cuc-kachi-kochi', 'Doraemon: Nobita và Chuyến Thám Hiểm Nam Cực Kachi Kochi', 'Doraemon: Nobita''s Great Adventure in the Antarctic Kachi Kochi', 'doraemon: nobita và chuyến thám hiểm nam cực kachi kochi doraemon: nobita''s great adventure in the antarctic kachi kochi wasabi mizuta megumi oohara yumi kakazu tomokazu seki subaru kimura chiaki fujimoto kotono mitsuishi daisuke namikawa yasunori matsumoto rie kugimiya masumi yagi shigeo takahashi aya endo nao toyama ayaka hirahara mai asada nobunari oda doraemon: nobita và chuyến thám hiểm nam cực kachi kochi โดราเอมอน ตอน โนบิตะผจญภัยในแอนตาร์กติกแห่งคะจิโคะจิ eiga doraemon: nobita no nankyoku kachikochi daibouken 도라에몽: 노비타의 남극 꽁꽁대모험 doraemon - il film: nobita e la grande avventura in antartide 映画ドラえもん のび太の南極カチコチ大冒険 哆啦a夢：大雄的南極冰天雪地大冒險 doraemon y la gran aventura en la antártida 哆啦a梦：大雄的南极冰冰凉大冒险 doraemon nobita and the great adventure in the antarctic kachi kochi eiga doraemon nobita no nankyoku kachi kochi daibouken 哆啦a梦：大雄的南极冰雪大冒险 doraemon: great adventure in the antarctic kachi kochi 哆啦a梦 大雄的南极冰冰凉大冒险', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-han-son-thanh', 'Nam Hán Sơn Thành', 'The Fortress', 'https://phimimg.com/upload/vod/20231128-1/e1c6a9ad4418eff478aa98422ccf744f.jpg', 'https://phimimg.com/upload/vod/20231128-1/1195b72c85c151504333faff591ccb2c.jpg', '<p>Nam Hán Sơn Thành (The Fortress) là phim điện ảnh bom tấn cổ trang của Hàn Quốc do đạo diễn Hwang Dong Hyuk chỉ đạo sản xuất, được công chiếu năm 2017 với sự tham gia diễn xuất của nhiều ngôi sao nổi tiếng như Kim Yoon Suk, Lee Byung Hun, Park Hae Il, Go Soo... Bộ phim lấy bối cảnh năm 1636 khi nhà Thanh tấn công Triều Tiên, khiến cho Triều Tiên In Jo (Park Hae Il) cùng các cận thần của mình là Choi Myung Kil (Lee Byung Hun) và Kim Sang Hun (Kim Yoon Suk) phải ẩn náu ở Pháo đài núi Nam Hán, một nơi hoàn toàn cô lập với bên ngoài. Tại đây, các vị cận thần của vua In Jo bắt đầu tranh cãi vì những bất đồng quan điểm về việc giải quyết tình hình. Trong khi Choi Myung Kil khăng khăng duy trì mối quan hệ hữu nghị với nhà Thanh để bảo vệ người dân thì Kim Sang Hun lại đề nghị họ nên tiếp tục chiến đấu đến cùng...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Kim Yoon-seok","avatar":""},{"name":"Park Hae-il","avatar":""},{"name":"Go Soo","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Lee Da-wit","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Kim Pub-lae","avatar":""},{"name":"Jo A-in","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Yoo Soon-woong","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Choi Jong-ryul","avatar":""},{"name":"Moon Chang-gil","avatar":""},{"name":"Cho Ah-in","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Kim Seo-hyeon","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324402);
