INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-mat-trang-3', 'Kẻ Trộm Mặt Trăng 3', 'Despicable Me 3', 'https://phimimg.com/upload/vod/20250516-1/de5fd84f9b354a53bd667709cc469928.jpg', 'https://phimimg.com/upload/vod/20250516-1/9cd221bf8e65fb20966f4b6130017dae.jpg', '<p>Chọn trở lại con đường lương thiện, Gru trở thành một cựu ác nhân nghèo khổ. Họ khốn khó đến mức cô bé Agnes quyết định bán đi chú ngựa nhồi bông mình quý nhất để giúp đỡ gia đình. Lũ Minions cũng không chịu yên khi suốt ngày khó chịu về ngài chủ nhân đã không còn ác. Chúng muốn Gru trở lại như ngày xưa. &nbsp;Lúc này, người anh trai sinh đôi của Gru xuất hiện. Anh có cơ hội giữ lấy mọi thứ mình yêu thương nhưng lại phải quay về con đường cũ. Liệu Gru sẽ lựa chọn thế nào đây? &nbsp;Những nguy hiểm đang chờ đón cựu ác nhân này và đám Minions vàng chóe sẽ giúp Despicable Me 3 càn quét toàn cầu.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Steve Carell","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Trey Parker","avatar":""},{"name":"Miranda Cosgrove","avatar":""},{"name":"Dana Gaier","avatar":""},{"name":"Nhev Scharrel","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Michael Beattie","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Adrian Ciscato","avatar":""},{"name":"Brian T. Delaney","avatar":""},{"name":"Katia Saponenko","avatar":""},{"name":"Ken Daurio","avatar":""},{"name":"Jude Alpers","avatar":""},{"name":"Cory Wa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3ac