INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-bup-be-7', 'Ma Búp Bê 7', 'Cult of Chucky', 'https://phimimg.com/upload/vod/20250515-1/131ecf1c1853156ecf0748baf86a2a9a.jpg', 'https://phimimg.com/upload/vod/20250515-1/46a70fcf3b0714557ea0566e949361c6.jpg', '<p>Hãng phim Universal đã gây bất ngờ với tín đồ dòng phim kinh dị khi tung ra trailer cho phần phim tiếp theo của huyền thoại Chukcy có tên là Cult of Chucky. Sau khi ở trong trại tâm thần gần 4 năm, Nica Pierce (Fiona Dourif) đã nhận ra sai lầm khi tin rằng chính cô ấy, không phải Chucky là người đã thảm sát gia đình của mình. Nhưng khi cô được bác sĩ trị liệu của mình giới thiệu đến một người mới thì đó dường như là một gương mặt khá quen thuộc, một búp bê mỉm cười đầy ám ảnh, câu chuyện tiếp tục bắt đầu từ đây. Andy Barclay (Alex Vincent) kẻ thù không đội trời chung với Chucky từ bộ phim gốc trước đó sẽ trở lại để giúp đỡ Nica, Nhưng để cứu cô, anh sẽ phải vượt qua Tiffany, cô dâu của Chucky, người sẽ làm bất cứ điều gì để có được tình yêu của gã búp bê sát nhân này. Nam diễn viên Brad Dourif sẽ trở lại với vai trò lồng tiếng cho Chucky &quot;dễ thương&quot;, phim sẽ được biên kịch và chỉ đạo bởi Don Mancini, người đã gắn bó với tất cả những phần phim về Chukcy trước đó.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Fiona Dourif","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Alex Vincent","avatar":""},{"name":"Jennifer Tilly","avatar":""},{"name":"Michael Therriault","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Elisabeth Rosen","avatar":""},{"name":"Zak Santiago","avatar":""},{"name":"Ali Tataryn","avatar":""},{"name":"Grace Lynn Kung","avatar":""},{"name":"Marina Stephenson Kerr","avatar":""},{"name":"Allison Dawn Doiron","avatar":""},{"name":"Summer H. Howell","avatar":""},{"name":"Tom Anniko","avatar":""},{"name":"Darren Wall","avatar":""},{"name":"Dan De Jaeger","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Child''s Play 7: Cult of Chucky","Kult Chuckyja","鬼娃森77","Zemsta Laleczki","O Culto de Chucky","Cult of Chucky"]', 1784690324402);
