INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-bao-dia-cau', 'Siêu Bão Địa Cầu', 'Geostorm', 'https://phimimg.com/upload/vod/20250515-1/eb4d6b5a192f68443a3b4e6e5879c554.jpg', 'https://phimimg.com/upload/vod/20250515-1/9c6389ccd2d604c624f3ef83b7971227.jpg', '<p>Bộ phim nói về viễn tưởng tương lại khi sự biến đổi khí hậu thảm khốc gây nguy hiểm cho sự sống còn của Trái Đất, các chính phủ trên thế giới đã thống nhất với nhau và tạo ra một mạng lưới các vệ tinh. Mỗi khi muốn thay đổi thời tiết thì các vệ tinh này sẽ tác động lên mây, gió của bầu khí quyển Trái Đất và tạo ra hiệu ứng như ý muốn. Nhưng những việc này làm trái với thiên nhiên của tạo hóa đều có thể gây ra những hậu quả nghiêm trọng, những vệ tinh thời tiết này dần bị hư hỏng và gây ra hàng loạt thảm họa thiên nhiên trên khắp thế giới.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 1, '[{"name":"Gerard Butler","avatar":""},{"name":"Alexandra Maria Lara","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Abbie Cornish","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Andy García","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Robert Sheehan","avatar":""},{"name":"David S. Lee","avatar":""},{"name":"Talitha Eliana Bateman","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Adepero Oduye","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Tom Choi","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00