INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-sot-hoa-tulip', 'Cơn Sốt Hoa Tulip', 'Tulip Fever', 'https://phimimg.com/upload/vod/20250514-1/78665682a097c4ae306255015412559c.jpg', 'https://phimimg.com/upload/vod/20250514-1/6cc7c9c4151f28f3cb1a699e9f0595d8.jpg', '<p>Chàng họa sĩ Jan Van Loos đem lòng yêu một người con gái đã có chồng có tên Sophia sau khi anh được người chồng già thuê vẽ chân dung cho cô. Mối quan hệ vừa chớm nở hai người đã phải đối mặt với sự khắt khe của xã hội. Cặp đôi quyết định đầu tư vào việc buôn bán hoa Tulip và dành một khoản rồi sẽ cùng nhau cao chạy xa bay tìm đến nơi hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alicia Vikander","avatar":""},{"name":"Dane DeHaan","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Matthew Morrison","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"Cressida Bonas","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"David Harewood","avatar":""},{"name":"Joanna Scanlan","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Sebastian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Tulpanfeber","Tulpenfieber","Amor e Tulipas","튤립 피버","La ragazza dei tulipani","Amor y tulipanes","La fiebre de los tulipanes","Tulip Fever"]', 1784690324402);
