INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-khau-phong-van', 'Đãng Khấu Phong Vân', 'God Of War', 'https://phimimg.com/upload/vod/20231101-1/12917b7343538e63e4227d566b72eaac.jpg', 'https://phimimg.com/upload/vod/20231101-1/8db5a216a3df811b1d8613028e82505a.jpg', '<p>Lấy bối cảnh nhà Minh, câu chuyện xoay quanh anh hùng dân tộc Thích Kế Quang (Triệu Văn Trác) cùng Thích phu nhân (Vạn Tây) và Du Đại Du tướng quân (Hồng Kim Bảo) liên minh hợp sức chống giặc Oa Khấu hoành hành ven duyên hải vào thời vua Gia Tĩnh.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Văn Trác","avatar":""},{"name":"Hồng Kim Bảo","avatar":""},{"name":"Vạn Thiến","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324402);
