INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-anh-hung-xa-dieu', 'Tân Anh Hùng Xạ Điêu', 'The Legend Of The Condor Heroes', 'https://phimimg.com/upload/vod/20250513-1/0c0611b696115c5c5a7131b940ac46e5.jpg', 'https://phimimg.com/upload/vod/20230911-1/f8b1255856bb47a49b74d79b8e839c1a.jpg', '<p>Là một trong những bộ phim làm lại được đánh giá cao nhất, phim giành giải thưởng tại Golden Guduo Media Awards lần II và được phát hành rộng rãi ở truyền hình Việt Nam và 11 quốc gia châu Á sau khi được trình chiếu ở các đài truyền hình Trung Quốc. Phim bám sát nguyên tác, không tự ý cải biên thêm thắt nhiều tình tiết thừa thãi, vô lý. Phim đã tái hiện những chi tiết kinh điển trong tiểu thuyết của Kim Dung. Điển hình như phân đoạn Quách Tĩnh đếm lông mi của Hoàng Dung. Không chỉ tôn trọng nguyên tác mà yếu tố võ thuật hành động trong phim cũng rất được chú trọng. Điều này giúp những trường đoạn giao đấu giữa các nhân vật trở nên rất chân thực, đẹp mắt. Bên cạnh đó, các cảnh quay ngoại cảnh trong cũng khá đẹp mắt, yếu tố kỹ xảo chỉ chiếm 20%.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 7, 2017, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Húc Văn","avatar":""},{"name":"Lý Nhất Đồng","avatar":""},{"name":"Trần Tinh Hú","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324402);
