INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-tien-ho-giet-cha-toi', 'Đầu Tiên Họ Giết Cha Tôi', 'First They Killed My Father', 'https://phimimg.com/upload/vod/20250511-1/6e383c0926f2c955d2896b475e527c0f.jpg', 'https://phimimg.com/upload/vod/20250511-1/f7062f9017210b14ae27bfa7b3733060.jpg', '<p>Bộ phim dựa trên cuốn tự truyện của nhà hoạt động nhân quyền Campuchia Loung Ung Jolie, kể về câu chuyện có thật dưới thời kỳ Khmer Đỏ thống trị ở nước này trong những năm 1970 hay còn gọi là chế độ diệt chủng Pol Pot. Bên cạnh việc tái hiện lại thời kỳ đẫm máu ở xứ sở Chùa Vàng với hơn 7 triệu người dân bị giết hại, phim còn khắc họa chi tiết cuộc đời bi thương của một bé gái 5 tuổi tên Loung Ung (tác giả cuốn tự truyện). Đó là những năm tháng mà Loung Ung sẽ không bao giờ quên trong cuộc đời cô.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sareum Srey Moch","avatar":""},{"name":"Phoeung Kompheak","avatar":""},{"name":"Sveng Socheata","avatar":""},{"name":"Mun Kimhak","avatar":""},{"name":"Heng Dara","avatar":""},{"name":"Khoun Sothea","avatar":""},{"name":"Sarun Nika","avatar":""},{"name":"Run Malyna","avatar":""},{"name":"Oun Srey Neang","avatar":""},{"name":"Horm Chhora","avatar":""},{"name":"Nout Sophal","avatar":""},{"name":"Tharoth Sam","avatar":""},{"name":"Rous Mony","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["First They Killed My Father: A Daughter of Cambodia Remembers","Se lo llevaron. Recuerdos de una niña de Camboya","Primero mataron a mi padre: Recuerdos de una hija de Camboya","Primero mataron a mi padre: Una hija de Camboya recuerda","Önce Babamı Öldürdüler: Kamboçyalı Bir Kızın Anıları","他们先杀了我父亲：一个柬埔寨女儿的回忆录","Primeiro, Mataram o Meu Pai","그들이 아버지를 죽였다","Primeiro, Mataram Meu Pai","មុនដំបូងខ្មែរក្រហមសម្លាប់ប៉ារបស់ខ្ញុំ","Moun dambaung Khmer Krahm samleab ba robsa khnhom","First They Killed My Father"]', 1784690324402);
