INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-tien-ho-giet-cha-toi', 'Đầu Tiên Họ Giết Cha Tôi', 'First They Killed My Father', 'đầu tiên họ giết cha tôi first they killed my father sareum srey moch phoeung kompheak sveng socheata mun kimhak heng dara khoun sothea sarun nika run malyna oun srey neang horm chhora nout sophal tharoth sam rous mony first they killed my father: a daughter of cambodia remembers se lo llevaron. recuerdos de una niña de camboya primero mataron a mi padre: recuerdos de una hija de camboya primero mataron a mi padre: una hija de camboya recuerda önce babamı öldürdüler: kamboçyalı bir kızın anıları 他们先杀了我父亲：一个柬埔寨女儿的回忆录 primeiro, mataram o meu pai 그들이 아버지를 죽였다 primeiro, mataram meu pai មុនដំបូងខ្មែរក្រហមសម្លាប់ប៉ារបស់ខ្ញុំ moun dambaung khmer krahm samleab ba robsa khnhom first they killed my father', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-chua-18', 'Em Chưa 18', 'Jailbait', 'https://phimimg.com/upload/vod/20250511-1/1647db994439f2622914335845539019.jpg', 'https://phimimg.com/upload/vod/20250511-1/decf910fa32aa518174b9afc50ea32c3.jpg', '<p>Câu chuyện bắt đầu với Hoàng, một Tay chơi “chất lầy” bảnh tỏn, thu nhập ngất ngưởng, sống cùng quy luật &quot;không có đêm thứ 2&quot; với bất kỳ cô nàng nào. Định mệnh ập đến khi chàng trai trong mơ của bao người đàn ông gặp gỡ Linh Đan. Dĩ nhiên, cả hai đã có mối tình chớp nhoáng và không hề có gì khác biệt với những cô gái trước đây, cho đến khi Hoàng phát hiện ra bạn gái mới của mình chưa đủ 18 tuổi. Từ đây, cả thế giới đào hoa của chàng &quot;lầy gái&quot; số một bất ngờ thu nhỏ lại trong lưới tình của cô học trò xinh đẹp tinh quái.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Kaity Nguyễn","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Will","avatar":""},{"name":"Nguyễn Tiến Dũng","avatar":""},{"name":"Châu Bùi","avatar":""},{"name":"Kiều Trinh","avatar":""},{"name":"Alexandra Nguyễn","avatar":""},{"name":"Võ Ngọc Trai","avatar":""},{"name":"Don Nguyễn","avatar":""},{"name":"Chí Tâm","avatar":""},{"name":"Nguyễn Chánh Tín","avatar":""},{"name":"Võ Quang Minh","avatar":""},{"name":"Aaron Toronto","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Châu Thiên Kim","avatar":""},{"name":"Kim Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Em Chưa 18"]', 1784690324402);
