INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('em-chua-18', 'Em Chưa 18', 'Jailbait', 'em chưa 18 jailbait kaity nguyễn kiều minh tuấn will nguyễn tiến dũng châu bùi kiều trinh alexandra nguyễn võ ngọc trai don nguyễn chí tâm nguyễn chánh tín võ quang minh aaron toronto huy khánh châu thiên kim kim anh em chưa 18', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-kiep-yeu-tinh', 'Hai Kiếp Yêu Tinh', 'Hanson And The Beast', 'https://phimimg.com/upload/vod/20240104-1/0a974287b2ed82bec1643998356cc299.jpg', 'https://phimimg.com/upload/vod/20240104-1/de8521faba59ae36c396144a67db49cb.jpg', '<p>Viên Soái (do Phùng Thiệu Phong thủ vai) là một người chăn nuôi động vật đang ngập trong nợ nần sau khi bị lừa đảo trong một dự án làm phim thất bại. Để giải quyết khó khăn tài chính, anh cố gắng tìm một người bạn gái giàu có thông qua các buổi hẹn hò mai mối. Trong một lần như vậy, anh gặp Bạch Tiên Sơ (do Lưu Diệc Phi thủ vai), một hồ ly tinh đã từng được anh cứu khi còn nhỏ. Bạch Tiên Sơ đến thế giới loài người để trả ơn cứu mạng và nhanh chóng nảy sinh tình cảm với Viên Soái. Tuy nhiên, mối quan hệ giữa người và yêu quái bị cấm đoán bởi Vân Trung Hạc, người đứng đầu Cục Biến Hình, cơ quan giám sát các yêu quái sống ẩn mình trong thế giới con người. Khi Bạch Tiên Sơ bị bắt đi, Viên Soái quyết định dấn thân vào thế giới yêu quái để giải cứu cô, bất chấp mọi nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Lưu Diệc Phi","avatar":""},{"name":"Lý Quang Kiệt","avatar":""},{"name":"Quách Kính Phi","avatar":""},{"name":"Giao Quân Yến","avatar":""},{"name":"Hùng Nại Cần","avatar":""},{"name":"Vương Song Bảo","avatar":""},{"name":"Trần Vũ Mễ","avatar":""},{"name":"Michael Khải Tú","avatar":""},{"name":"Trương Tử Hiên","avatar":""},{"name":"Phạm Điềm Điềm","avatar":""},{"name":"Đỗ Phong Dư Dung","avatar":""},{"name":"Vương Tường","avatar":""},{"name":"Trương Hằng Duệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324402);
