INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tu-thang-ba-phan-2', 'Sư Tử Tháng Ba (Phần 2)', 'March Comes In Like A Lion (Season 2)', 'https://phimimg.com/upload/vod/20250428-1/68816151ee79a95cd5fa2755679e2fb1.jpg', 'https://phimimg.com/upload/vod/20250428-1/c4e24ba4382401b338d05d9f628aa23e.jpg', '<p>3-Gatsu no Lion xoay quanh đời sống thường nhật của một kì thủ cờ shogi (cờ tướng Nhật Bản) 17 tuổi - Kiriyama Rei. Trên hành trình chạy trốn khỏi những ám ảnh quá khứ, cậu gặp gỡ ba chị em nhà Kawamoto là Akari (chị cả), Hina (chị hai), Momo (em út) và bắt đầu từ đây, cuộc sống của Rei dần dần thay đổi.</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三月的狮子","3-Gatsu No Lion","Sangatsu no Lion","3-gatsu no Lion","3月のライオン","3月のライオン 第2シリーズ","3월의 라이온","Marcowy lew","Март приходит подобно льву","March comes in like a lion","March Comes In Like A Lion 2nd Season","３月のライオン"]', 1784690324402);
