INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-tu-thang-ba-phan-2', 'Sư Tử Tháng Ba (Phần 2)', 'March Comes In Like A Lion (Season 2)', 'sư tử tháng ba (phần 2) march comes in like a lion (season 2) kengo kawanishi 三月的狮子 3-gatsu no lion sangatsu no lion 3-gatsu no lion 3月のライオン 3月のライオン 第2シリーズ 3월의 라이온 marcowy lew март приходит подобно льву march comes in like a lion march comes in like a lion 2nd season ３月のライオン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-co-tinh-ca', 'Thượng Cổ Tình Ca', 'A Life Time Love', 'https://phimimg.com/upload/vod/20250424-1/ac83d41a70eefee0113acd2a3722f36e.jpg', 'https://phimimg.com/upload/vod/20250424-1/a2bff7164de9e9c118bdba8807cd1aca.jpg', '<p>Xích Vân là một chiến thần dũng mãnh, mang trong mình khát vọng thống nhất thiên hạ. Trong một lần tình cờ, anh gặp Mộc Thanh Mịch, công chúa của vương quốc Huyền Dương, và đem lòng yêu nàng. Tuy nhiên, Thanh Mịch đã được gia đình hứa gả cho Lăng Vân Thịnh Luân (Thịnh Nhất Luân), hoàng tử của vương quốc Linh Vân. Dù bị ngăn cản, Xích Vân và Thanh Mịch vẫn quyết định bên nhau, thề hẹn dưới hoa đào tại Thung lũng Vô Hồi. Tuy nhiên, khi cha của Thanh Mịch phát động chiến tranh, nàng buộc phải đứng giữa lựa chọn tình yêu và nghĩa vụ với gia đình. Những biến cố liên tiếp xảy ra, từ việc Thanh Mịch mất trí nhớ đến những âm mưu chính trị, đã thử thách tình yêu của họ đến tận cùng...</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 7, 2017, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Tống Thiến","avatar":""},{"name":"Thịnh Nhất Luân","avatar":""},{"name":"Trương Lệ","avatar":""},{"name":"Địch Thiên Lâm","avatar":""},{"name":"La Vân Hi","avatar":""},{"name":"Ngô Thiến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Once Promised","Ancient Times'' Love Song","Ancient Love Song","A Lifetime of Love","上古情歌"]', 1784690324402);
