INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-co-tinh-ca', 'Thượng Cổ Tình Ca', 'A Life Time Love', 'thượng cổ tình ca a life time love huỳnh hiểu minh tống thiến thịnh nhất luân trương lệ địch thiên lâm la vân hi ngô thiến once promised ancient times'' love song ancient love song a lifetime of love 上古情歌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-yeu-em-mot-chut-thoi', 'Chỉ Yêu Em Một Chút Thôi', 'I Love You Just A Little Bit', 'https://phimimg.com/upload/vod/20250424-1/f45d959de3e27db5f694c3c71774a029.jpg', 'https://phimimg.com/upload/vod/20250424-1/11cee99fbbc17fd588952abdd76ec265.jpg', '<p>Mitsu, một phụ nữ đã kết hôn với một người đàn ông tử tế, chín chắn. Cô mong cuộc sống hôn nhân sẽ mang đến hạnh phúc. Nhưng định mệnh trêu ngươi — mối tình đầu năm xưa quay lại đúng lúc hôn nhân hiện tại đang gặp trục trặc. Tình cảm cũ chưa hề nguội lạnh khiến cô phải đứng giữa lựa chọn: an toàn hiện tại hay cảm xúc chân thật trong tim.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Riisa Naka","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Haru","avatar":""},{"name":"Masahiro Higashide","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Eu te amo só um pouquinho","夺爱、春","Anata no Koto wa Sore Hodo","あなたのことはそれほど"]', 1784690324402);
