INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-dan-su-dung-dan-ong', 'Hướng Dẫn Sử Dụng Đàn Ông', 'This Is Not What I Expected', 'https://phimimg.com/upload/vod/20250416-1/d52340c6a64f2a342a4c5cca74da468d.jpg', 'https://phimimg.com/upload/vod/20250416-1/ce85769902fd6ecc57aad9d8eb70eb30.jpg', '<p>Cố Thắng Nam 29 tuổi là bếp phó của nhà hàng Tây trong một khách sạn lâu đời, cô bí mật hẹn hò với tổng giám đốc của khách sạn này. Kết quả khi khách sạn gặp khủng hoảng, người yêu cô đòi chia tay. Đúng lúc đó Lộ Tấn tới khách sạn nơi cô làm việc với ý định thu mua lại nơi này. Cuộc giao đấu vô hình trong ẩm thực, cũng như những tình huống dở khóc dở cười ngoài đời giữa Cố Thắng Nam và vị chủ tịch xoi mói Lộ Tấn đã vô tình kéo họ lại gần nhau hơn. Cuối cùng Lộ Tấn đã chịu khuất phục trước cô nàng đầu bếp tài hoa, ngoan ngoãn trở thành bạn trai cô.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Xi Mengyao","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Sun Yizhou","avatar":""},{"name":"Chang Kuo-Chu","avatar":""},{"name":"Lin Chi-Ling","avatar":""},{"name":"Xiaosong Gao","avatar":""},{"name":"Quan Tong","avatar":""},{"name":"Yuan Zhong Yuan","avatar":""},{"name":"Zhang Xin Qi","avatar":""},{"name":"Zhang Xin Yao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["喜欢·你","男人使用手册","你看上去很好吃","喜歡你","Xi huan ni","This Is Not What I Expected","Je ne m''attendais pas ça!","恋するシェフの最強レシピ：2017","喜欢你"]', 1784690324402);
