INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-than-chet', 'Tình Yêu Thần Chết', 'The Universe''s Star', 'https://phimimg.com/upload/vod/20250416-1/254d55f8ce9d309754138827c11090e6.jpg', 'https://phimimg.com/upload/vod/20250416-1/4b154098acdca8cbdc68e8bdd6c47add.jpg', '<p>Chuyện tình giữa một chàng ca sĩ kiêm nhạc sĩ Woo Joo và Byul, một cô bé học sinh 19 tuổi đã trở thành thần chết sau khi gặp một tai nạn giao thông rồi qua đời.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Suho","avatar":""},{"name":"Ji Woo","avatar":""},{"name":"Na Hae-ryung","avatar":""},{"name":"Shin Hyun-soo","avatar":""},{"name":"Yoon Jin-sol","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Ko Kyu-phil","avatar":""},{"name":"Lee Ji-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Universe''s Star","Three Color Fantasy – The Universe''s Star (White)","Three Color Fantasy Series: White","Woojooui Byeoli","우주의 별이"]', 1784690324402);
