INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-than-chet', 'Tình Yêu Thần Chết', 'The Universe''s Star', 'tình yêu thần chết the universe''s star suho ji woo na hae-ryung shin hyun-soo yoon jin-sol lee si-eon kim ki-cheon ko kyu-phil lee ji-hoon the universe''s star three color fantasy – the universe''s star (white) three color fantasy series: white woojooui byeoli 우주의 별이', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kamen-rider-amazons-phan-2', 'Kamen Rider Amazons (Phần 2)', 'Kamen Rider Amazons (Season 2)', 'https://phimimg.com/upload/vod/20250414-1/32af9823d4e6dab55f6740e6ee2f11a2.jpg', 'https://phimimg.com/upload/vod/20250414-1/db5344ff2dccc59f0bc5a0ef9daf65c3.jpg', '<p>Trong quá khứ, một vụ tràn dầu lớn đã xảy ra tại phòng thí nghiệm thử nghiệm Amazon. Hầu hết những người sống sót đã bị tiêu diệt, những thanh niên máu nóng thích săn lùng người Amazon và cuộc thử nghiệm dường như sắp kết thúc. Tuy nhiên, không chỉ dừng lại ở đó, nó đang bước vào một giai đoạn hoàn toàn mới. Số lượng các trường hợp người dân thường biến thành người Amazon mà không có cảnh báo đang tăng lên. Chính phủ đã thành lập một đơn vị diệt chủng mới để ám sát những người đã bí mật biến thành người Amazon và đấu tranh để che giấu sự thật. Chihiro/Kamen Rider Amazon Neo là một kẻ cô độc, một cậu bé được nuôi dưỡng bởi những người Amazon ghét họ nhưng phải kìm nén ham muốn ăn thịt người của mình. Một ngày nọ, cậu gặp Iyu, một cô gái Amazon biến thành Crow Amazon và đánh bại kẻ thù Amazon bằng sức mạnh chiến đấu tuyệt vời của mình. Chihiro vô cùng kinh ngạc khi lần đầu nhìn thấy Iyu, bởi vì cô là người đầu tiên cậu gặp mà không nghĩ rằng &quot;Mình muốn ăn cô ấy&quot;. Cô là đối thủ đầu tiên cậu muốn tiếp cận, nhưng Chihiro không biết về câu chuyện của cô. Iyu là một &quot;Sigma Type Amazons&quot;, một vũ khí sinh học được hồi sinh sau khi cha mẹ cô chuyển sang Amazons và giết cô.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Masked Rider Amazon","仮面ライダーアマゾン"]', 1784690324402);
