INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-den-phan-4', 'Gương Đen (Phần 4)', 'Black Mirror (Season 4)', 'https://phimimg.com/upload/vod/20231002-1/752241ee3ae5deec7772d6d745857b9e.jpg', 'https://phimimg.com/upload/vod/20231002-1/5c8b4f70b277ab3d83ef52e683e7a47f.jpg', '<p>Black Mirror Phần 4 mô tả những thực tại trong đó con người kết nối liên tục với nhau và với quá khứ bằng thiết bị số. Hình ảnh của mỗi người, hầu như mọi hoạt động của mỗi người trong ngày, đều soi bóng trong vô vàn “gương đen” bủa vây âm thầm. “Gương đen” là thiết bị ghi nhận sự hiện diện của mỗi người, có ở khắp nơi: trên tường, trên bàn, trong tay mọi người.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hannah John-Kamen","avatar":""},{"name":"Daniel Lapaine","avatar":""},{"name":"Michaela Coel","avatar":""},{"name":"Beatrice Robertson-Jones","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324402);
