INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-vong-phap-luat-2017', 'Ngoài Vòng Pháp Luật', 'The Outlaws', 'https://phimimg.com/upload/vod/20250331-1/84f82e5711b60e2f8ff9a3714a7fd61b.jpg', 'https://phimimg.com/upload/vod/20250331-1/e6c17caefaaddcfcbdf07cdc3ae488d6.jpg', '<p>Dù không có dàn cast trai xinh gái đẹp, nhưng The Outlaws vẫn thu hút khán giả ra rạp với ông chú đô con Ma Dong Suk. Bộ phim dựa trên biến cố có thật, xảy ra vào năm 2007 tại quận Guro, Seoul, theo chân thanh tra Ma - do Ma Dong Suk thủ vai cùng những đồng nghiệp của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Don Lee","avatar":""},{"name":"Yoon Kye-sang","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Hong Gi-jun","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Ha Jun","avatar":""},{"name":"Kim Sung-kyu","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Ye Jung-hwa","avatar":""},{"name":"Yoon Joo","avatar":""},{"name":"Min Kyung-jin","avatar":""},{"name":"Uhm Ji-sung","avatar":""},{"name":"Kim Koo-taek","avatar":""},{"name":"Park Sa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Crime City","The Outlaws","Beom-joe-dosi","犯罪都市","The Outlaws (2017)","Cidade do Crime","Beom-joi-do-si","Beomjoidos","범죄도시","범죄도시 1","Криминален град","犯罪都市 (2017)"]', 178469032