INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-den-cung', 'Truy Bắt Đến Cùng', 'The Chase', 'https://phimimg.com/upload/vod/20250327-1/8c7a2ad75d3c7f211a52c46e7f367bb2.jpg', 'https://phimimg.com/upload/vod/20250327-1/3d2fd32bdf9ceda025029c13934aa878.jpg', '<p>Một vụ án giết người chưa có lời giải suốt 30 năm bất ngờ tái diễn với cùng một phương thức gây án. Shim Deok-soo, một người gắn bó lâu năm với khu phố, hợp tác với Park Pyung-dal, một cựu cảnh sát am hiểu vụ án, để truy bắt kẻ thủ ác. Họ phải sử dụng trực giác sắc bén và kỹ năng điều tra nhạy bén để tóm gọn hắn trước khi quá muộn!</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Baek Yoon-sik","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Bae Jong-ok","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Kim Hye-In","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Lee Kan-hee","avatar":""},{"name":"Park Hyeong-su","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Jo Hyun-sik","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Oh Hee-jun","avatar":""},{"name":"Oh Chi-woon","avatar":""},{"name":"Son Seong-chan","avatar":""},{"name":"Park Sung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Chase","bandeusi jabneunda","ล่าฆาตกรวิปริต","Takip","شبح الماضي","Преследование","必ず捕まえる