INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('coco-hoi-ngo-dieu-ky', 'Coco: Hội Ngộ Diệu Kỳ', 'Coco', 'https://phimimg.com/upload/vod/20250327-1/611a931655cbc521859c57786a460f1a.jpg', 'https://phimimg.com/upload/vod/20250327-1/36c5de7e9f44bf77f902c3632c28b528.jpg', '<p>Coco sẽ kể về hành trình của Miguel, một cậu bé say mê những giai điệu nhưng lại sinh trưởng trong một gia đình cấm đoán sự xuất hiện của âm nhạc. Miguel luôn nung nấu giấc mơ trở thành một nhạc sĩ nổi tiếng giống như thần tượng Ernesto de la Cruz. Tuy nhiên, truyền thống ngang trái của gia đình đã khiến cậu không thể chứng minh tài năng của mình. &nbsp;Rũ bỏ thực tế phũ phàng, Miguel tìm thấy chính mình ở Vùng Đất Linh Hồn (Land of the Dead) tuyệt đẹp và đầy sắc màu sau một chuỗi sự kiện huyền bí. Trong hành trình khám phá vùng đất mới, Miguel gặp gỡ “chuyên gia xảo quyệt” Hector. Cả hai cùng tạo nên chuyến phiêu lưu kỳ diệu để lật mở những bí mật chưa được tiết lộ về lịch sử của gia đình Miguel.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2017, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anthony Gonzalez","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Alanna Ubach","avatar":""},{"name":"Renee Victor","avatar":""},{"name":"Jaime Camil","avatar":""},{"name":"Alfonso Arau","avatar":""},{"name":"Herbert Siguenza","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Ana Ofelia Murguía","avatar":""},{"name":"Natalia Cordova-Buckley","avatar":""},{"name":"Sofía Espinosa","avatar":""},{"name":"Selene Luna","avatar":""},{"name":"Edward James Olmos","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["โคโค่: วันอลวน วิญญาณอลเวง","Coco: Το Γεύμα του Δάντη","ΚΟΚΟ: ΤΟ ΓΕΥΜΑ ΤΟΥ ΔΑΝΤΗ","COCO: ΤΟ ΓΕΥΜΑ ΤΟΥ ΔΑΝΤΗ","寻梦环游记","Viva: A Vida é uma Festa","玩轉極樂園","リメンバー・ミー","Koko in velika skrivnost","Coco 3D","Coco i velika tajna","Coco","කෝකෝ"]', 1784690324402);
