INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('coco-hoi-ngo-dieu-ky', 'Coco: Hội Ngộ Diệu Kỳ', 'Coco', 'coco: hội ngộ diệu kỳ coco anthony gonzalez gael garcía bernal benjamin bratt alanna ubach renee victor jaime camil alfonso arau herbert siguenza gabriel iglesias lombardo boyar ana ofelia murguía natalia cordova-buckley sofía espinosa selene luna edward james olmos โคโค่: วันอลวน วิญญาณอลเวง coco: το γεύμα του δάντη κοκο: το γευμα του δαντη coco: το γευμα του δαντη 寻梦环游记 viva: a vida é uma festa 玩轉極樂園 リメンバー・ミー koko in velika skrivnost coco 3d coco i velika tajna coco කෝකෝ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-xe-hoi-3', 'Vương Quốc Xe Hơi 3', 'Cars 3', 'https://phimimg.com/upload/vod/20250327-1/b3a00b8cf959c5de38fde6a948a65c8d.jpg', 'https://phimimg.com/upload/vod/20250327-1/28cf759197df8ac31a607e9a00729146.jpg', '<p>Câu chuyện bắt nguồn từ vụ va chạm giữa Lightning McQueen cùng dòng xe đua thế hệ mới. Sau khi bị chấn thương, McQueen đột nhiên bị loại ra khỏi môn thể thao đua xe mà anh yêu thích. Để quay lại đường băng, anh cần sự trợ giúp từ một nữ kỹ thuật viên trẻ tuổi - Cruz Ramirez. Nhờ vào kế hoạch của Cruz, cùng với sự khơi nguồn cảm hứng từ Fabulous Hudson Hornet, Mc Queen sẽ chứng minh với mọi người rằng #95 chưa hết thời mà vẫn có thể giành chiến thắng trong cuộc đua Piston Cup...</p>', 'Full', 1, 'hoathinh', 'completed', 5, 2017, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'HD', 'Âu Mỹ', 1, '[{"name":"Owen Wilson","avatar":""},{"name":"Cristela Alonzo","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Larry the Cable Guy","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"Ray Magliozzi","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Lea DeLaria","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Bob Costas","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Darrell Waltrip","avatar":""},{"name":"Isiah Whitlock","avatar":""},{"name":"Jr.","avatar":""},{"name":"Bob Peterson","avatar":""},{"name":"Guid","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Cars 3 สี่ล้อซิ่ง ชิงบัลลังก์แชมป์","카3: 새로운 도전","Cars 3 - Evolution","反斗車王3","Autot 3","Avtomobili 3","Maşınlar 3","Cars: 3","Auti 3","カーズ3","赛车总动员3","赛车总动员3：极速挑战","Cars 3"]', 1784690324402);
