INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuong-quoc-xe-hoi-3', 'Vương Quốc Xe Hơi 3', 'Cars 3', 'vương quốc xe hơi 3 cars 3 owen wilson cristela alonzo chris cooper nathan fillion larry the cable guy armie hammer ray magliozzi tony shalhoub bonnie hunt lea delaria kerry washington bob costas margo martindale darrell waltrip isiah whitlock jr. bob peterson guid cars 3 สี่ล้อซิ่ง ชิงบัลลังก์แชมป์ 카3: 새로운 도전 cars 3 - evolution 反斗車王3 autot 3 avtomobili 3 maşınlar 3 cars: 3 auti 3 カーズ3 赛车总动员3 赛车总动员3：极速挑战 cars 3', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-ma', 'Khách Sạn Ma', 'Haunted Road 2', 'https://phimimg.com/upload/vod/20250325-1/3eb34040f3d28756830f8144ef88ef92.jpg', 'https://phimimg.com/upload/vod/20250325-1/438be1672c9480e434332354576e653a.jpg', '<p>Bạch Linh (do Sucharat Manaying thủ vai) xinh đẹp và Vệ Quân (do Lý Xuyên thủ vai) điển trai là một cặp đôi đang say đắm trong tình yêu. Họ cùng nhau đến cao nguyên Genting, Malaysia để tận hưởng kỳ nghỉ riêng tư. Sau khi may mắn thắng lớn tại sòng bạc, cả hai vui vẻ rời đi và check-in tại Khách sạn Sắc Vân – nơi nổi tiếng với những câu chuyện ma ám khắp châu Á. Vệ Quân tỏ ra thờ ơ, nhưng Bạch Linh liên tục gặp những hiện tượng kỳ quái trong khách sạn, khiến cô hoảng loạn và bất an. Những rắc rối từ công ty trước khi đi du lịch đã khiến cô căng thẳng, nay lại rơi vào một nơi đầy u ám khiến cô như mất hồn. Nửa đêm, cả hai bị dọa đến mức gần như sụp đổ tinh thần. Không thể chịu đựng thêm, họ quyết định lái xe bỏ trốn trong đêm. Nhưng một khi đã lọt vào tầm ngắm của thế lực tà ác, liệu họ có thể thoát khỏi chiếc bẫy tăm tối này...?</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Teddy Chin","avatar":""},{"name":"Li Chuan","avatar":""},{"name":"Sushar Manaying","avatar":""},{"name":"Musi Ni","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Haunted Road 2","Haunted Hotel","1174 ห้องผีจองเวร","Khách Sạn Ma","Yuan ling 2","Habitación 1174","El hotel maldito","怨灵 2"]', 1784690324402);
