INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tai-den', 'Thần Tài Đến', 'May Fortune Smile On You', 'https://phimimg.com/upload/vod/20250324-1/65204ff8c73830b81e8682623c2bd82e.jpg', 'https://phimimg.com/upload/vod/20250324-1/9e15c6b7441106a7d014fb3a05b944db.jpg', '<p>Một bộ phim hài kể về những câu chuyện khi các Thần tài xuống hạ giới ban phát tiền tài cho người dân. Phim có sự tham gia của nhiều diễn viên nổi tiếng, nổi bật là Đàm Vịnh Lân và Dương Thiên Hoa.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 8, 2017, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Pal Sinn Lap-Man","avatar":""},{"name":"Matthew Ho","avatar":""},{"name":"Kelly Fu","avatar":""},{"name":"Joel Chan","avatar":""},{"name":"Claire Yiu","avatar":""},{"name":"Amy Fan","avatar":""},{"name":"Winki Lai","avatar":""},{"name":"Jack Wu","avatar":""},{"name":"Zoie Tam","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Griselda Yeung","avatar":""},{"name":"Joseph Yeung","avatar":""},{"name":"Eddie Li Kong","avatar":""},{"name":"Henry Yu Yang","avatar":""},{"name":"Rainbow Ching","avatar":""},{"name":"Dickson Lee Kar-Sing","avatar":""},{"name":"Cheng Chu-Fung","avatar":""},{"name":"Andy Shi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["財神駕到"]', 1784690324402);
