INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-gio-cuoc-doi', 'Sóng Gió Cuộc Đời', 'Waves Of Life', 'https://phimimg.com/upload/vod/20250321-1/0a6f7c38c311ed9b19ce7eee139dbc7c.jpg', 'https://phimimg.com/upload/vod/20250321-1/c96711bb11e6e0bbc15170784aae80bf.jpg', '<p>&quot;Sóng Gió Cuộc Đời&quot; kể về Jeerawat – một nữ diễn viên xinh đẹp, tài năng nhưng luôn bị bủa vây bởi thị phi và tai tiếng. Cô là người mạnh mẽ, thẳng thắn, không ngại đối đầu, nên thường bị hiểu lầm là người phụ nữ dễ dãi và nổi loạn. Ngay cả mẹ ruột cũng không thấu hiểu cô, trong khi người chồng mới của mẹ lại giở trò đồi bại khiến Jeerawat phải bỏ chạy trong hoảng loạn. Trong lúc bị ảnh hưởng bởi thuốc mê, Jeerawat vô tình lái xe gây tai nạn khiến bạn gái của Sathit (สาธิต) – một luật sư chính trực – thiệt mạng. Sathit căm phẫn, không tin đó chỉ là tai nạn và quyết tâm buộc cô phải trả giá. Tuy nhiên, qua những hiểu lầm, giằng xé và đau khổ, Sathit dần nhận ra con người thật của Jeerawat – một cô gái mạnh mẽ nhưng tổn thương, luôn dằn vặt vì lỗi lầm mình gây ra. Tình yêu từ hận thù dần nảy nở giữa hai con người tưởng như không thể thuộc về nhau. Liệu tình yêu có thể xóa bỏ thù hận và chữa lành những vết thương trong quá khứ?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 9, 2017, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Urassaya Sperbund","avatar":""},{"name":"Prin Suparat","avatar":""},{"name":"Jarinporn Joonkiat","avatar":""},{"name":"Louis Scott","avatar":""},{"name":"Nuttanicha Dungwattanawanich","avatar":""},{"name":"Chotika Wongwilas","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""},{"name":"Khwanruedi Klomklom","avatar":""},{"name":"Bua Nalinthip Sakulongumpai","avatar":""},{"name":"Mayurin Pongpudpunth","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Valurile Vieții","Kleun Cheewit","Life''s Waves","คลื่นชีวิต"]', 1784690324402);
