INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-bo-thien-ha', 'Độc Bộ Thiên Hạ', 'Rule The World', 'https://phimimg.com/upload/vod/20250314-1/2f603866bce2cd0ae8e49aec5b445715.jpg', 'https://phimimg.com/upload/vod/20250314-1/da48a0a04be1f9c6912999430643f671.jpg', '<p>Phim kể về cuộc đời sóng gió của đệ nhất mỹ nhân Đông Ca của tộc Nữ Chân với lời nguyền: có thể chấn hưng thiên hạ, cũng có thể khiến xã tắc diệt vong. Thế nhưng, Hoàng Thái Cực thân là hoàng gia chí tôn vì nàng bất chấp lời tiên đoán, cùng Đông Ca dệt nên một chuyện tình kinh thiên động địa, cảm động người đời.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 7, 2017, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Nghệ Hân","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Trương Duệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Du Bu Tian Xia","独步天下"]', 1784690324402);
