INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bach-vo-song-phan-2', 'Hắc Bạch Vô Song (Phần 2)', 'The Unparalleled Black And White (Season 2)', 'https://phimimg.com/upload/vod/20250313-1/c8d108b7479a414642ac6259106a4f24.jpg', 'https://phimimg.com/upload/vod/20250313-1/735f6ffd76e9c8000413ec83c49ba2bd.jpg', '<p>Bên bờ Nại Hà, địa giới thông qua quỷ sai để duy trì sự cân bằng sinh tử trong tam giới. Còn những kẻ phụng mệnh đến nhân gian thu thập linh hồn không ai khác chính là Hắc Bạch Vô Song. Hai tên gà mờ trong giới Hắc Bạch - Tiểu Hắc và Tiểu Bạch, trải qua sự việc bách quỷ phong ấn, quan hệ của hai người ngày càng xa cách, thân thế của Tiểu Bạch cũng dần dần được hé mở.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Guangtao","avatar":""},{"name":"Tang Xiaoxi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["the Unparalleled Black&white","Hei Bai Wu Shuang","Heibai Wushang","Heibai Wushuang","黑白无常","Black and White Warriors","黑白无双"]', 1784690324402);
