INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-nghia-nhan-dan', 'Danh Nghĩa Nhân Dân', 'In The Name Of People', 'https://phimimg.com/upload/vod/20250304-1/102be4732629293210ab3b2bb6705fe8.jpg', 'https://phimimg.com/upload/vod/20250304-1/e176b333160c18d60af02563042f0c98.jpg', '<p>Dù là thể loại chính kịch nhưng bộ phim thu hút sự quan tâm của giới trẻ không thua kém những tác phẩm thần tượng ăn khách. Trong thời đại IP thịnh hành, tại sao lại chọn đề tài khó nhằn như vậy, đạo diễn Lý Lộ cho biết: Một tác phẩm phản ánh hiện thực, đề cập đến những vấn đề được mọi người quan tâm mới có sức sống lâu bền. Thể loại chống tham nhũng đã im lìm nhiều năm nay, một khi trở lại nhất định sẽ trở thành kinh điển.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lục Nghị","avatar":""},{"name":"Trương Phong Nghị","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Hứa Á Quân","avatar":""},{"name":"Trương Chí Kiên","avatar":""},{"name":"Kha Lam","avatar":""},{"name":"Hồ Tịnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The name of the people","人民的名义"]', 1784690324402);
