INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-phan-1', 'Đấu Phá Thương Khung (Phần 1)', 'Fights Break Sphere (Season 1)', 'https://phimimg.com/upload/vod/20230929-1/388eace8bb528fe3af42d0898218d417.jpg', 'https://phimimg.com/upload/vod/20230929-1/84a451551996685197b4c802747d8d40.jpg', '<p>Tiêu Viêm, Chủ Nhân Công, Tiêu Viêm là thiên tài tu luyện đấu khí của nhà họ Tiêu. Năm 4 tuổi bắt đầu tu luyện Đấu Chi Khí, 10 tuổi sở hữu Cửu Đoạn Đấu Chi Khí, 11 tuổi đột phá Thập Đoạn Đấu Chi Khí, trở thành đấu thủ trẻ tuổi nhất của gia tộc suốt trăm năm qua. Nhưng đến năm 12 tuổi, Tiêu Viêm bất ngờ mất đi khả năng tu luyện, chỉ còn lại Tam Đoạn Đấu Chi Khí. Trong 3 năm sau đó, bị gia tộc ghẻ lạnh, người xung quanh kinh thường, bị hủy hôn ước.... Đúng vào lúc Tiêu Viêm tuyệt vọng nhất, một linh hồn xuất hiện từ trong chiếc nhẫn trên tay Tiêu Viêm, mở ra trước mắt Tiêu Viêm một cánh cửa hoàn toàn mới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Sanmu","avatar":""},{"name":"Zhang Pei","avatar":""},{"name":"Yuxuan Liu","avatar":""},{"name":"Su Wan","avatar":""},{"name":"Zhu Jun","avatar":""},{"name":"Chen Yiwen","avatar":""},{"name":"Yang Menglu","avatar":""},{"name":"Wen Xiaoyi","avatar":""},{"name":"Yan Meme","avatar":""},{"name":"Xia Lei","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324402);
