INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-vuong', 'Lục Vương', 'Rikuoh', 'https://phimimg.com/upload/vod/20250228-1/de38956cb2675aaed341659856dc3cd7.jpg', 'https://phimimg.com/upload/vod/20250228-1/cd3931f29156955c7611530864d67211.jpg', '<p>Dựa trên tác phẩm gốc của Ikeido Jun và với sự tham gia của diễn viên trứ danh Yakusho Hiroshi, một doanh nghiệp truyền thống làm tất tabi với hơn 100 năm lịch sử đã liều mạng phát triển giày chạy bộ để cứu vãn sự tồn vong của công ty – một câu chuyện cảm động về sự tái sinh của doanh nghiệp.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koji Yakusho","avatar":""},{"name":"Kento Yamazaki","avatar":""},{"name":"Haruka Uchimura","avatar":""},{"name":"Ayako Yoshitani","avatar":""},{"name":"Yasuko Haru","avatar":""},{"name":"Kotaro Shiga","avatar":""},{"name":"Masato Wada","avatar":""},{"name":"Yoshihisa Amano","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Sawako Agawa","avatar":""},{"name":"Ryoma Takeuchi","avatar":""},{"name":"Akira Terao","avatar":""},{"name":"Midoriko Kimura","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Mone Kamishiraishi","avatar":""},{"name":"Fumi Dan","avatar":""},{"name":"Anna Hara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rikuou","日曜劇場『陸王』","陸王"]', 1784690324402);
