INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-nhap-cu-phan-4', 'Dân Nhập Cư (Phần 4)', 'Fresh Off The Boat (Season 4)', 'https://phimimg.com/upload/vod/20250225-1/40c3d9828a8e6931070b40cfb28bdc17.jpg', 'https://phimimg.com/upload/vod/20250225-1/03afcc5124e15a5314379e99de0070c1.jpg', '<p>Một bộ phim hài đơn camera lấy bối cảnh những năm 90 kể về một cậu bé người châu Á yêu hip-hop lớn lên ở vùng ngoại ô Orlando, được nuôi dưỡng bởi một người cha nhập cư mê mẩn mọi thứ về nước Mỹ và một người mẹ nhập cư thường xuyên bị bối rối bởi văn hóa người da trắng. Hy vọng điều này truyền tải đúng ý của bạn!</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Constance Wu","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Hudson Yang","avatar":""},{"name":"Forrest Wheeler","avatar":""},{"name":"Ian Chen","avatar":""},{"name":"Lucille Soong","avatar":""},{"name":"Ray Wise","avatar":""},{"name":"Chelsey Crisp","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bienvenue chez les Huang","初來報到","Los Huang: Un sueño americano","Понаехали!","С корабля","Fresh Off the Boat"]', 1784690324402);
