INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-giai-cuu', 'Kế Hoạch Giải Cứu', 'You Were Never Really Here', 'https://phimimg.com/upload/vod/20250224-1/d134e6855b8f33aaacd12fc09a428962.jpg', 'https://phimimg.com/upload/vod/20250224-1/7f8689b7023803159401877987a87464.jpg', '<p>Kế hoạch giải cứu nói về một cựu lính thủy đánh bộ Joe nỗ lực giải cứu một cô gái trẻ thoát khỏi đường dây buôn bán tình dục sau khi phát hiện ra cô ấy bị bắt cóc và bị đối xử một cách vô cùng dã man. Tưởng chừng hành động của anh ta hoàn toàn đúng đắn, thế nhưng hóa ra, quyết định anh hùng này lại sớm trở thành một sai lầm khủng khiếp.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Judith Roberts","avatar":""},{"name":"Ekaterina Samsonov","avatar":""},{"name":"John Doman","avatar":""},{"name":"Alex Manette","avatar":""},{"name":"Dante Pereira-Olson","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Larry Canady","avatar":""},{"name":"Vinicius Damasceno","avatar":""},{"name":"Neo Randall","avatar":""},{"name":"Frank Pando","avatar":""},{"name":"Edward Latham","avatar":""},{"name":"Claire Hsu","avatar":""},{"name":"Denis Ozer","avatar":""},{"name":"Tia-Sophia Begh","avatar":""},{"name":"Lucy Lan Luo","avatar":""},{"name":"Annie","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Beautiful Day","Iš tiesų tavęs niekuomet čia nebuvo","너는 여기에 없었다","Tu n''as jamais été vraiment là","En realidad, nunca estuviste aquí","En realitat mai vas estar ací","You Were Never Really Here"]', 1784690324402);
