INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-hoach-giai-cuu', 'Kế Hoạch Giải Cứu', 'You Were Never Really Here', 'kế hoạch giải cứu you were never really here joaquin phoenix judith roberts ekaterina samsonov john doman alex manette dante pereira-olson alessandro nivola larry canady vinicius damasceno neo randall frank pando edward latham claire hsu denis ozer tia-sophia begh lucy lan luo annie a beautiful day iš tiesų tavęs niekuomet čia nebuvo 너는 여기에 없었다 tu n''as jamais été vraiment là en realidad, nunca estuviste aquí en realitat mai vas estar ací you were never really here', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-ho-ly', 'Mùa Hè Của Hồ Ly', 'The Fox''s Summer', 'https://phimimg.com/upload/vod/20231219-1/f83c8c2eaad656c311833da826d1aefc.jpg', 'https://phimimg.com/upload/vod/20231219-1/43b7c98252500a8ec34c7bd4a94990b1.jpg', '<p>Thừa Trạch là con nuôi nhà họ Cố. Bà Cố luôn mong con ruột của mình là Cần Quân có thể tiếp quản công ty nhưng Quân không phải người có chí lớn. Ngược lại Thừa Trạch luôn cần mẫn với công việc. Bà Cố giao Quân cho Thừa Trạch đào tạo. Thừa Trạch tình cờ biết Yến Thư là bạn gái cũ của Quân, nên anh mời Yến Thư về công ty làm việc với hy vọng kích thích ý chí của Quân. Nhưng Thừa Trạch dần phát hiện mình cũng bị cô gái lương thiện này thu hút.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 10, 2017, 'Vietsub + Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Giang Hồ","avatar":""},{"name":"Vương Hâm","avatar":""},{"name":"Trương Nghiên Chi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324402);
