INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-hop-nhat', 'Thế Giới Hợp Nhất', 'Reunited Worlds', 'https://phimimg.com/upload/vod/20250218-1/9520cbc486db82929a91bcb45b12032f.jpg', 'https://phimimg.com/upload/vod/20250218-1/41ed1485a01f4acdb3370ba7d48c1ca6.jpg', '<p>Sung Hae Sung (Yeo Jin Goo) và Jung Jung Won (Jung Chae Yeon) là hai người bạn niên thiếu cùng học với nhau. Nhưng sau một tai nạn bất ngờ, Sung Hae Sung biến mất khiến cho mọi người đều nghĩ rằng anh đã chết. 12 năm sau, Hae Sung xuất hiện trở lại, nhưng vẫn với dáng vẻ và tính cách của độ tuổi 19. Lúc này, người bạn thời niên thiếu của anh là Jung Jung Won (Lee Yeon Hee) đã là một cô gái 31 tuổi. Hai người tiếp nối mối duyên phận bị cắt đứt 12 năm trước, liệu Hae Sung và Jung Won có thể có được kết thúc hạnh phúc?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2017, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yeo Jin-goo","avatar":""},{"name":"Lee Yeon-hee","avatar":""},{"name":"Ahn Jae-hyun","avatar":""},{"name":"Lee Si-eon","avatar":""},{"name":"Kim Jin-woo","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Kim Ga-eun","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Ahn Kil-kang","avatar":""},{"name":"Jung Chae-yeon","avatar":""},{"name":"Ahn Sol-bin","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Han So-hee","avatar":""},{"name":"Choi Sung-min","avatar":""},{"name":"Park Sung-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["再次相遇的世界","Dashi Mannan Segye","อดีตรักพัดหวน","再次重逢的世界","Into the New World","Into the World Again","다시 만난 세계"]', 1784690324402);
