INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-hop-nhat', 'Thế Giới Hợp Nhất', 'Reunited Worlds', 'thế giới hợp nhất reunited worlds yeo jin-goo lee yeon-hee ahn jae-hyun lee si-eon kim jin-woo kwak dong-yeon kim ga-eun park jin-joo ahn kil-kang jung chae-yeon ahn sol-bin kim hye-jun han so-hee choi sung-min park sung-jun 再次相遇的世界 dashi mannan segye อดีตรักพัดหวน 再次重逢的世界 into the new world into the world again 다시 만난 세계', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('snowfall-phan-1', 'Snowfall (Phần 1)', 'Snowfall (Season 1)', 'https://phimimg.com/upload/vod/20250218-1/61d60a17a0cf9f160e49ff8b13933ec2.jpg', 'https://phimimg.com/upload/vod/20250218-1/ca49d5c5f16955c1fff56bfc6648595b.jpg', '<p>Los Angeles. Năm 1983. Một cơn bão đang đến và tên của nó là crack. Câu chuyện diễn ra trong bối cảnh những ngày đầu của dịch crack cocaine và tác động cực kỳ lớn của nó lên văn hóa mà chúng ta biết, theo chân nhiều nhân vật trên một hành trình đầy bạo lực.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Damson Idris","avatar":""},{"name":"Carter Hudson","avatar":""},{"name":"Sergio Peris-Mencheta","avatar":""},{"name":"Michael Hyatt","avatar":""},{"name":"Amin Joseph","avatar":""},{"name":"Angela Lewis","avatar":""},{"name":"Isaiah John","avatar":""},{"name":"Devyn A. Tyler","avatar":""},{"name":"Alejandro Edda","avatar":""},{"name":"Gail Bean","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["白粉飞","毒雪纷飞","Snowfall"]', 1784690324402);
