INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-gio-gia-toc-3', 'Sóng Gió Gia Tộc 3', 'Heart And Greed 3', 'https://phimimg.com/upload/vod/20250217-1/c7a70ecfaf2b1ab142fb984aeed7ee12.jpg', 'https://phimimg.com/upload/vod/20250217-1/ec205db45f00d0b9d2e7f0f9f6c5dd7a.jpg', '<p>Công việc kinh doanh của gia đình đang phát triển thì Huỳnh Vĩnh Chính biết tin ân nhân của mình, Hứa Nhã Lân, sắp bị phá sản. Để cứu Lân, Chính nghe lời em vợ đưa tập đoàn lên sàn chứng khoán, sáp nhập với công ty của Lân. Nhờ kế sách này, cổ phiếu của hai bên đều tăng cao. Tuy nhiên, xung đột giữa hai gia tộc cũng bắt đầu từ đây.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2017, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lý Tư Kỳ","avatar":""},{"name":"Hạ Vũ","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tong sum fung bo","Heart of Greed","溏心风暴I","溏心風暴"]', 1784690324402);
