INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-pham-xung-doi', 'Cực Phẩm Xứng Đôi', 'The Perfect Match', 'https://phimimg.com/upload/vod/20250210-1/6274222e6c059c0ad55098c6cfd48153.jpg', 'https://phimimg.com/upload/vod/20250210-1/e3582778628a418c312abf0a0defc267.jpg', '<p>Cực Phẩm Xứng Đôi: kể về cuộc so tài giữa nữ vương chợ đêm Vệ Phân Thanh với đầu bếp siêu cấp Hoắc Đình Ân. Đối với Vệ Phân Thanh thì chợ đêm là toàn bộ cuộc sống của cô, sự kiêu ngạo lớn nhất của cô chính là việc tự mình nghĩ ra cách kiếm tiền từ thức ăn ngon ở chợ đêm, được tất cả bạn bè trên mạng khen ngợi, được cho là sánh ngang với thực đơn của nhà hàng đẳng cấp ba sao.

Còn đối với Hoắc Đình Ân mà nói, nhà hàng là mục tiêu cuộc sống duy nhất của anh, món ăn mà anh tạo ra được ca ngợi đến mức dù cho có phải bay qua Thái Bình Dương đê thưởng thức thì cũng đáng giá, phương pháp chế biến càng được xem là tuyệt chiêu độc môn.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Ngô Khảng Nhân","avatar":""},{"name":"Vệ Phân Thanh","avatar":""},{"name":"Ngô Tư Hiền","avatar":""},{"name":"Tiểu Man","avatar":""},{"name":"Trần Nãi Vinh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["極品絕配"]', 1784690324402);
