INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thi-tham-cua-toi-ac', 'Lời Thì Thầm Của Tội Ác', 'Whisper', 'https://phimimg.com/upload/vod/20250209-1/a6c4f50a8ff3b3843c5834f54f89193f.jpg', 'https://phimimg.com/upload/vod/20250209-1/bbfacf72c334a06dec64edfc4978e082.jpg', '<p>Nội dung phim xoay quanh cô nàng thám tử Shin Young-Joo (Lee Bo Young), là 1 thám tử có tiếng trong ngành cùng Lee Dong Joon, là một thẩm phán công chính, cùng nhau điều tra và phát hiện hàng loạt tham nhũng tại công ty luật lớn nhất của quốc gia mình, Taebaek.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Bo-young","avatar":""},{"name":"Lee Sang-yun","avatar":""},{"name":"Kwon Yul","avatar":""},{"name":"Park Se-young","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Moon Hee-kyung","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Kim Hyeong-mook","avatar":""},{"name":"Yoon Joo-hee","avatar":""},{"name":"Lee Hyun-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["耳语","Gwitsotmal","귀속말","whisper","귓속말"]', 1784690324402);
