INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-vo-tam-phan-2', 'Pháp Sư Vô Tâm (Phần 2)', 'Wu Xin The Monster Killer (Season 2)', 'https://phimimg.com/upload/vod/20250205-1/c926fb868a259d5b1a5abbd613bd9c7e.jpg', 'https://phimimg.com/upload/vod/20250205-1/307b540bc0f370de48fe6bbe8d2ac5e5.jpg', '<p><span style="text-wrap-mode: wrap;">Phim được cải biên từ tiểu thuyết mạng cùng tên của nhà văn Ni La, kể về pháp sư Vô Tâm mang trong mình khả năng bất tử, không có hơi thở, không có nhịp tim hành tẩu giang hồ trảm yêu trừ ma, vô tình gặp được thiếu nữ Nguyệt Nha - cô gái đang chạy trốn cuộc hôn nhân của mình - liền rơi vào câu chuyện tình yêu thời loạn thế. Vì mưu sinh, hai người đã xin đến nhà của Cố đại nhân để bắt ma, không ngờ do bất cẩn đã động chạm vào cơ mật, giải thoát phong ấn trăm năm của yêu nhân Nhạc Khởi La. Cũng từ đó, Khởi La đem lòng yêu mến Vô Tâm, tìm đủ mọi cách để sát hại người mà Vô Tâm thương yêu - Nguyệt Nha. Vô Tâm bi hận, quyết tâm phong ấn Nhạc Khởi La, sau đó từ biệt Cố đại nhân, một mình tiêu diêu nhân gian.</span></p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 6, 2017, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Quân","avatar":""},{"name":"Trần Dao","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Trương Nhược Quân","avatar":""},{"name":"Tùy Vịnh Lương","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Wu xin fa shi","無心法師","무심법사","무심법사: 불멸의 퇴마사","Wuxin: The Monster Killer","Pháp Sư Vô Tâm","无心法师"]', 1784690324402);
