INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zoe-va-raven-phan-1', 'Zoe và Raven (Phần 1)', 'Free Rein (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/39779f9375110b4805b58e46f9572fd3.jpg', 'https://phimimg.com/upload/vod/20250116-1/2af24585e1e475fde2ea4a2230a91cc4.jpg', '<p>Một cô bé 15 tuổi đến từ Los Angeles tận hưởng mùa hè ở căn nhà thời thơ ấu của mẹ trên hòn đảo ngoài khơi nước Anh, rồi từ đó dần gắn kết với một chú ngựa bí ẩn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jaylen Barron","avatar":""},{"name":"Manpreet Bambra","avatar":""},{"name":"Celine Buckens","avatar":""},{"name":"Freddy Carter","avatar":""},{"name":"Caroline Ford","avatar":""},{"name":"Natalie Gumede","avatar":""},{"name":"Bruce Herbelin-Earle","avatar":""},{"name":"Noah Huntley","avatar":""},{"name":"Kerry Ingram","avatar":""},{"name":"Paul Luebke","avatar":""},{"name":"Geoffrey McGivern","avatar":""},{"name":"Navia Ziraili Robinson","avatar":""},{"name":"Milo Twomey","avatar":""},{"name":"Carla Woodcock","avatar":""},{"name":"Tom Forbes","avatar":""},{"name":"Charlotte Jord","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zoe e Raven","Zoe und Raven – Freiheit im Sattel","Αχαλίνωτα Όνειρα","Free Rein"]', 1784690324402);
