INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-suy-nghi-phan-1', 'Kẻ săn suy nghĩ (Phần 1)', 'Mindhunter (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/1b2479906a8511a4ad0eec344900b692.jpg', 'https://phimimg.com/upload/vod/20250116-1/a7be3f23b6567523bb610cdb5a7ad6b4.jpg', '<p>Phim Truy Tìm Hung Thủ - Mindhunter dựa theo tiểu thuyết Mind Hunter: Inside FBI’s Elite Serial Crime Unit của Mark Olshaker và John E. Douglas, xoay quanh 2 thám tử FBI tên Holden Ford và Bill Tench (thủ vai lần lượt bởi Jonathan Groff và Holt McCallany) và quá trình điều tra của họ. Trong bối cảnh nước Mỹ những năm thập niên 70, khi mà những kẻ giết người hàng loạt càng lúc càng lộng hành và gây tiếng tăm lớn, khi bản thân nạn giết người hàng loạt xảy ra thường xuyên đến mức trở thành một thứ hiện hữu của xã hội, Ford và Tench quyết định bắt tay vào điều tra hành vi suy nghĩ của những kẻ gây tội ác ấy – trước tiên bằng cách phỏng vấn những kẻ sát nhân hàng loạt đã bị bắt và kết tội, hòng hiểu được suy nghĩ của chúng, cách chúng vận hành để có thể ngăn ngừa tội phạm trong tương lai.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holt McCallany","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Hannah Gross","avatar":""},{"name":"Anna Torv","avatar":""},{"name":"Sonny Valicenti","avatar":""},{"name":"Cotter Smith","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["心理神探","צייד המחשבות","Mindhunter","MINDHUNTER"]', 1784690324402);
