INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-trang-phan-1', 'Vàng trắng (Phần 1)', 'White Gold (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/fae3bcbad5cef199e998a5971d02dd35.jpg', 'https://phimimg.com/upload/vod/20250116-1/a16c2ea3cb84c653a4f3d175d92e81a8.jpg', '<p>Trong những năm 1980 tại Essex, gã nhân viên bán hàng tự mãn Vincent Swan và đội ngũ bất hảo của mình sẵn sàng làm mọi thứ miễn là bán được hàng - dù có phải lừa dối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Lee Ross","avatar":""},{"name":"Ed Westwick","avatar":""},{"name":"James Buckley","avatar":""},{"name":"Joe Thomas","avatar":""},{"name":"Linzey Cocker","avatar":""},{"name":"Lauren O''Rourke","avatar":""},{"name":"Rachel Shenton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["白金","White Gold"]', 1784690324402);
