INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('porto', 'Porto', 'Porto', 'https://phimimg.com/upload/vod/20250118-1/032491b5097e930b21a3240dac077301.jpg', 'https://phimimg.com/upload/vod/20250118-1/4b0b371a08fd20671c882955f25f3b51.jpg', '<p>Phim kể về mối tình thoáng qua nhưng đậm sâu giữa Jake (do Anton Yelchin thủ vai) và Mati (do Lucie Lucas thủ vai) tại thành phố Porto, Bồ Đào Nha. Câu chuyện được kể lại thông qua những ký ức rời rạc và cảm xúc đa chiều, tạo nên một bức tranh tình yêu đầy lãng mạn và bi thương. &quot;Porto&quot; không chỉ cuốn hút bởi cốt truyện mà còn bởi hình ảnh đẹp và âm nhạc ấn tượng, khiến khán giả dễ dàng bị cuốn vào thế giới của hai nhân vật chính. Bộ phim nhận được nhiều lời khen ngợi từ giới phê bình và khán giả yêu điện ảnh nghệ thuật.</p>', 'Full', 1, 'single', 'completed', 29, 2017, 'Vietsub', 'FHD', 'Bồ Đào Nha', 0, '[{"name":"Lucie Lucas","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Paulo Calatré","avatar":""},{"name":"Françoise Lebrun","avatar":""},{"name":"Chantal Akerman","avatar":""},{"name":"Rita Pinheiro","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["포르토","Порту","Porto"]', 1784690324402);
