INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('49-ngay-2', '49 Ngày 2', '49 Days 2', 'https://phimimg.com/upload/vod/20250116-1/0b4bfbcaa5fe82ca80e9ab114759a375.jpg', 'https://phimimg.com/upload/vod/20250116-1/e677f22733bef07f382d8d09525c2b35.jpg', '<p>Tiếp tục lấy đề tài vong hồn cần được thực hiện nguyện vọng để siêu thoát trong 49 ngày, phần 2 kể về Phương (Hari Won) - một cô gái đã chết - bám theo Huy (Ngô Kiến Huy) - một anh chàng mất trí nhớ sau tai nạn - để mong anh giúp mình lấy lại ký ức trước khi tan biến vì cô cũng mất trí nhớ. &nbsp;Thế là &quot;trước sợ sau quen&quot;, Huy cảm động trước hoàn cảnh đáng thương của Phương nên đồng ý giúp cô nàng dù bản thân anh vẫn chưa nhớ được câu chuyện của bản thân. Song song đó là những thay đổi của cuộc sống thường nhật xung quanh gia đình và người thân của Huy. Cho đến khi Huy nhớ lại được ký ức khủng khiếp của mình thì…</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hari Won","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Trường Giang","avatar":""},{"name":"Nhã Phương","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["49 Ngày 2"]', 1784690324402);
