INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-pho-phan-2', 'Hiệu Phó (Phần 2)', 'Vice Principals (Season 2)', 'https://phimimg.com/upload/vod/20250110-1/ccba3a646b46b566a4bd19a4abde0d67.jpg', 'https://phimimg.com/upload/vod/20250110-1/de1f4048706ba08350c607bb7e2ce981.jpg', '<p>Mùa hai của bộ phim về hai ông hiệu phó cạnh tranh chiếc ghế hiệu trưởng, nhưng lần này họ buộc phải hợp lức để nhổ đi cái gai trước mắt: vị nữ hiệu trưởng đang đương chức.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny McBride","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Georgia King","avatar":""},{"name":"Busy Philipps","avatar":""},{"name":"Sheaun McKinney","avatar":""},{"name":"Shea Whigham","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["副校长的逆袭","Subdirectores","Vice Principals"]', 1784690324402);
