INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-song-nguc-tu', 'Đời Sống Ngục Tù', 'Prison Playbook', 'https://phimimg.com/upload/vod/20250110-1/dc7a74d27c589f71db537aac69b3135d.jpg', 'https://phimimg.com/upload/vod/20250110-1/6fe7d1957645d7db114a44b11ae508db.jpg', '<p>Je Hyeok là ngôi sao bóng chày nổi tiếng, sắp đến Mỹ thi đấu cho một đội bóng danh giá.Thế nhưng cuộc đời anh rẽ sang hướng khác khi bị tuyên án một năm tù vì tội tấn công kẻ có ý định hãm hiếp em gái mình.Je Hyeok bắt đầu cuộc sống mới tại một nhà tù có khẩu hiệu đầy dễ thương: &quot;Chúng tôi sẽ giúp bạn như người một nhà&quot;.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 4, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae-soo","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Krystal Jung","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Jeong Min-sung","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Kang Seung-yoon","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Jung Hae-in","avatar":""},{"name":"Kim Sung-cheol","avatar":""},{"name":"Im Hwa-young","avatar":""},{"name":"Kang Ki-doong","avatar":""},{"name":"Choi Seong-won","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Kim Kyung-nam","avatar":""},{"name":"Jung Moon-sung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["机智的监狱生活","机智牢房生活","Prison Playbook","机智的牢房生活","Smart Prison Living","Wise Prison Life","Đời sống ngục tù","슬기로운 감빵생활"]', 1784690324402);
