INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lap-di-phan-1', 'Lập dị (Phần 1)', 'Atypical (Season 1)', 'https://phimimg.com/upload/vod/20250103-1/2c9bde9186151c84e63ffb78aca732cd.jpg', 'https://phimimg.com/upload/vod/20250103-1/b430d04744ac8c8536f4fe43e43c5c53.jpg', '<p>Khi một thiếu niên mắc hội chứng tự kỷ quyết định tìm bạn gái, việc cậu đòi thêm quyền tự lập giúp cả gia đình khám phá chính bản thân họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Keir Gilchrist","avatar":""},{"name":"Michael Rapaport","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["非典型孤独","Atipico","Atypical"]', 1784690324402);
