INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-quan-chu', 'Mặt Nạ Quân Chủ', 'Ruler Master Of The Masks', 'https://phimimg.com/upload/vod/20240829-1/6860befb491a682084e9cf63c73baf9f.jpg', 'https://phimimg.com/upload/vod/20240829-1/c5f8f4bf0165a407b9375de394a972a9.jpg', '<p>Mặt Nạ Quân Chủ - Ruler: Master Of The Masks kể về hành trình cam go của thái tử Lee Sun nhằm phá tan tham vọng tư hữu hoá vùng biển Joseon của nhóm thương gia quý tộc Pyunsoo Hwe. Dân chúng lầm than, chính trị rối ren, vị thái tử trẻ này trở thành niềm hy vọng cuối cùng của toàn dân nhưng cũng gặp nhiều hiểm nguy đến tính mạng. Trong khi đó, Ga Eun là nữ tử báo thù, chủ động tiếp cận Lee Sun để đòi nợ máu cho cha mình, sau đó lại bị cuốn vào kế hoạch của thái tử và đồng hành cùng người cho đến lúc lên ngôi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2017, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim So-Hyun","avatar":""},{"name":"Yuko Nakamura","avatar":""},{"name":"Yoo Seung Ho","avatar":""},{"name":"Yoon So Hee","avatar":""},{"name":"Kim Myung Soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324402);
