INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-tinh-o-the-gioi-khac-phan-1', 'Thức Tỉnh Ở Thế Giới Khác (Phần 1)', 'In Another World With My Smartphone (Season 1)', 'https://phimimg.com/upload/vod/20241229-1/71de79b44b8e08dd15c09dea1b42acab.jpg', 'https://phimimg.com/upload/vod/20241229-1/b6f8f64f3f50440676692dd19923051e.jpg', '<p>Anh chàng Mochizuki Touya, 15 tuổi vì cứu người mà chết, cậu ấy gặp được Thần. Vị thần tối cao đã thốt lên một câu: &quot;Ta e rằng ta đã phạm phải một sai lầm ngớ ngẩn&quot;. Nhưng chết chưa phải là hết! Để bù đắp lại lỗi lầm của mình, Thần nói rằng Ngài có thể hồi sinh Touya tại một thế giới khác nơi ma thuật tồn tại. Thêm vào đó, Touya có thể mang theo chiếc smartphone của mình. Thế là cuộc phiêu lưu mới đến thế giới phép thuật ở thế giới khác bắt đầu cùng dàn harem của cậu ấy. Một thế giới bi hùng về kiếm, pháp thuật và điện thoại di động đã được mở màn!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Katsumi Fukuhara","avatar":""},{"name":"Marika Kouno","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Nanami Yamashita","avatar":""},{"name":"Yui Fukuo","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Miyu Takagi","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Miyu Kubota","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Em Outro Mundo com Meu Smartphone","Isekai wa Sumatofon to Tomo ni","带着智能手机闯荡异世界","手机侠2","手机侠","Dans un autre monde avec mon smartphone","Isesuma","Isekai Wa Smartphone To Tomo Ni","Isekai Wa Smartphone","異世界はスマートフォンとともに。2","이세계는 스마트폰과 함께","帶著智慧型手機闖蕩異世界","In Another World with My Smartphone 2","In Another World With My Smartphone","Thức Tỉnh Ở Thế Giới Khác","異世界はスマートフォンとともに。"]', 1784690324402);
