INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuc-tinh-o-the-gioi-khac-phan-1', 'Thức Tỉnh Ở Thế Giới Khác (Phần 1)', 'In Another World With My Smartphone (Season 1)', 'thức tỉnh ở thế giới khác (phần 1) in another world with my smartphone (season 1) katsumi fukuhara marika kouno chinatsu akasaki nanami yamashita yui fukuo sumire uesaka miyu takagi maaya uchida yu serizawa miyu kubota em outro mundo com meu smartphone isekai wa sumatofon to tomo ni 带着智能手机闯荡异世界 手机侠2 手机侠 dans un autre monde avec mon smartphone isesuma isekai wa smartphone to tomo ni isekai wa smartphone 異世界はスマートフォンとともに。2 이세계는 스마트폰과 함께 帶著智慧型手機闖蕩異世界 in another world with my smartphone 2 in another world with my smartphone thức tỉnh ở thế giới khác 異世界はスマートフォンとともに。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-do-den-phan-1', 'Học Viện Đỏ Đen (Phần 1)', 'Kakegurui (Season 1)', 'https://phimimg.com/upload/vod/20241229-1/e8789fd2b887ee15bd93ab67c48e6a5a.jpg', 'https://phimimg.com/upload/vod/20241229-1/ddb5bc899f5cc91c96700295c449c936.jpg', '<p>Học Viện tư thục Hyakkaou là nơi dành cho học sinh thuộc tầng lớp danh giá với một sơ yêu lý lịch cực khủng. Bạn hiểu không? Khi bạn là cậu ấm cô chiêu của một gia đình thuộc lớp quý tộc, mấy thứ như học lực tốt hay chơi thể thao giỏi là hoàn toàn không cần thiết. Vốn là kẻ sinh ra để nắm quyền lực, tất cả những gì bạn cần là một cái đầu chứa đầy mưu kế và nắm bắt được suy nghĩ người khác. Và không có cách nào luyện tập kĩ năng này tốt hơn... cờ bạc! Đúng vậy, cờ bạc gần như là &quot;môn học&quot; chính tại học viện này, không chỉ để luyện tập cái đầu, mà còn quyết định cả giai cấp trong trường. Tại học viện Hyakkaou, kẻ thắng làm vua, kẻ thua làm thú. Nhưng cho đến khi Yumeko Jabami xuất hiện, cô đã dạy cho tụi học sinh này biết thế nào là &quot;canh bạc sinh tử&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Tokutake","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Ayaka Fukuhara","avatar":""},{"name":"Karin Nanami","avatar":""},{"name":"Yuuki Wakai","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Mayu Udono","avatar":""},{"name":"Mariya Ise","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Kakegurui","狂赌之渊××","狂赌之渊XX","Kakegurui - Compulsive Gambler","賭ケグルイ(アニメ)","賭ケグルイ××","Kakegurui: Compulsive Gambler","賭ケグルイ"]', 1784690324402);
