INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-du-ky', 'Hoa Du Ký', 'A Korean Odyssey', 'https://phimimg.com/upload/vod/20241228-1/85a2edd28fa4c330c3c00d427a4fa755.jpg', 'https://phimimg.com/upload/vod/20241228-1/34f72cad35106486457b92555316fc24.jpg', '<p>Là phiên bản cải biên hài hước của tác phẩm kinh điển Tây Du Ký, phim lấy bối cảnh thời hiện đại, nơi những yêu quái nghìn năm tuổi sống chung với con người và che giấu thân phận thật của mình. Không quá đặt nặng tư tưởng Phật giáo, nên các nhân vật của “Tây Du Ký bản Hàn” đã được “hiện đại hóa” một cách đầy thú vị.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Seung-gi","avatar":""},{"name":"Cha Seung-won","avatar":""},{"name":"Oh Yeon-seo","avatar":""},{"name":"Lee Hong-gi","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Lee El","avatar":""},{"name":"Lee Se-young","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Sung Hyuk","avatar":""},{"name":"Yoon Bo-ra","avatar":""},{"name":"Sung Ji-ru","avatar":""},{"name":"Jung Jae-won","avatar":""},{"name":"Kal So-won","avatar":""},{"name":"Song Jong-ho","avatar":""},{"name":"Kim Ji-soo","avatar":""},{"name":"Michael K. Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["华游记","Hwayuki","האור והאופל","花遊記<ファユギ>","花遊記＜ファユギ＞","Хваюги","ตำนานไซอิ๋วฉบับเกาหลี","Хваюгі: Корейська одіссея","Hwayugi","A Korean Odyssey","Hoa Du Ký","화유기"]', 1784690324402);
