INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-duy-nhat-cua-toi', 'Bản Tình Ca Duy Nhất Của Tôi', 'My Only Love Song', 'https://phimimg.com/upload/vod/20241222-1/30ac38cc6ba99cac932a558a6f06651d.jpg', 'https://phimimg.com/upload/vod/20241222-1/cd07b522f596d98a4a2df852b93095c8.jpg', '<p>Song Soo-Jung, một nữ ngôi sao kiêu ngạo, người tin rằng địa vị và tiền bạc có thể đưa con người tới bất cứ đâu. Một ngày nọ, cô vô tình xuyên không về quá khứ và gặp gỡ On Dal, một chàng trai yêu tiền và làm mọi thứ vì tiền. Tuy nhiên, đây cũng là một người có trái tim lương thiện, luôn sẵn lòng giúp đỡ những kẻ nghèo khó.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Gong Seung-yeon","avatar":""},{"name":"Lee Jong-hyun","avatar":""},{"name":"Jin Ye-ju","avatar":""},{"name":"Lee Jae-jin","avatar":""},{"name":"Kim Jung-pal","avatar":""},{"name":"Kim Chae-eun","avatar":""},{"name":"Ahn Bo-hyun","avatar":""},{"name":"Park Joo-Hyung","avatar":""},{"name":"Lee Yong-jik","avatar":""},{"name":"Lee Cheol-min","avatar":""},{"name":"Choi Jong-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我唯一的爱歌","My Only Love Song","Μοναδικό Τραγούδι Αγάπης","שיר האהבה שלי","Mai Onri Reobeusong","ย้อนเวลาวุ่น ลุ้นรักนายจอมทึ่ม","마이 온리 러브송"]', 1784690324402);
