INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac', 'Khoảnh Khắc', 'The Moment', 'https://phimimg.com/upload/vod/20241221-1/32937a1376e981365d22e59a78a828df.jpg', 'https://phimimg.com/upload/vod/20241221-1/ecbb2d6ffa9fbde0e124ea28a5f3b31e.jpg', '<p>Những tâm hồn cô đơn nơi đất khách, rồi sẽ ra sao khi bên họ dần có một ai đó cùng họ sẻ chia? Bộ phim sẽ đưa bạn đến với ba đất nước Hàn Quốc, Mỹ và Anh và lắng nghe những câu chuyện từ Seoul, New York và Luân Đôn của những bạn trẻ Thái rời xa quê hương với những mục đích khác nhau.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Teo Yoo","avatar":""},{"name":"Theerachai Wimolchaireuk","avatar":""},{"name":"Jarinporn Joonkiat","avatar":""},{"name":"Kan Kantathavorn","avatar":""},{"name":"Pachara Chirathivat","avatar":""},{"name":"Supassara Thanachart","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ruk Kong Rao","รักของเรา"]', 1784690324402);
