INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-nhan-so-phan-6', 'Hữu Nhân Sổ (Phần 6)', 'Natsume''s Book Of Friends (Season 6)', 'https://phimimg.com/upload/vod/20240302-1/64fa057e1e1003e5553fafc90ce80665.jpg', 'https://phimimg.com/upload/vod/20240302-1/731977a9bd7a60c5caec6416cb49dfdb.jpg', '<p>Natsume Takashi, một cậu bé có khả năng nhìn thấy yêu quái từ khi còn nhỏ, đã cùng với người bảo hộ tự xưng - chú mèo yêu quái Nyanko-sensei, dành nhiều ngày để trả lại tên cho những con yêu quái đã bị trói buộc tên. Natsume Yujincho Series 6 đã bắt đầu! Một ngày nọ, Natsume đang đi dọc bờ sông, nghe thấy tiếng va chạm của thứ gì đó và cậu ta nhìn thấy một con yêu quái đeo chiếc lọ đang đập đầu vào dầm cầu. Natsume sẽ làm điều gì?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Eiji Itoh","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Hisayoshi Suganuma","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Sanae Kobayashi","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Kazuma Horie","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Rina Sato","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324402);
