INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-mua-hay-nang', 'Dẫu Mưa Hay Nắng', 'Just Between Lovers', 'https://phimimg.com/upload/vod/20241207-1/e5b1ddddc7827e6a71849412937f23fd.jpg', 'https://phimimg.com/upload/vod/20241207-1/365fe243470b95baa4d28e05869bb32e.jpg', '<p>Câu chuyện bắt đầu từ một vụ tai nạn thảm khốc đã cưới đi sinh mạng của 48 người, cuộc sống của những người sống sót, những người mất người thân và những người có liên quan đến đều vô cùng khó khăn. Khi 15 tuổi, Lee Gang Doo mơ ước được chơi cho đội tuyển bóng đá quốc gia Hàn Quốc, nhưng chấn thương nghiêm trọng mà anh mắc phải đã phá hủy ước mơ đó. Trong những năm sau đó, hiếm khi anh có được niềm vui và tiếng cười vì liên tục phải chiến đấu với nỗi đau thể xác và tình cảm.

Ha Moon Soo cũng là một trong số người may mắn đã sống sót qua tai nạn, nhưng vẫn bị ác mộng đeo bám nhiều năm. Vài năm sau, một dự án xây dựng được khởi công tại địa điểm xảy ra tai nạn. Nó là niềm vui của nhiều người nhưng lại gợi ra ký ức đau buồn cho Gang Doo, Moon Soo và tất cả những người có liên quan đến thảm kịch. Mọi người đã cùng nhau giúp tất cả vượt qua ám ảnh nhiều năm, giúp nhau đối mặt với tổn thương và vượt qua nỗi đau</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-ho","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Kang Han-na","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Kim Kang-hyun","avatar":""},{"name":"Na Moon-hee","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Han Seo-jin","avatar":""},{"name":"Park Hee-von","avatar":""},{"name":"Kim Min-gue","avatar":""},{"name":"Tae In-ho","avatar":""},{"name":"Park Si-eun","avatar":""},{"name":"Park Gyu-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rain or Shine","Just in Love","Just Lovers","그냥 사랑하는 사이"]', 1784690324402);
