INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-greenhouse-phan-1', 'Học Viện Greenhouse (Phần 1)', 'Greenhouse Academy (Season 1)', 'https://phimimg.com/upload/vod/20241106-1/3d6f06e16aff33e93dd77ad23de8ae6b.jpg', 'https://phimimg.com/upload/vod/20241106-1/e3f8d578aeb554fd36d8768afa63370e.jpg', '<p>Học Viện Greenhouse được chuyển thể từ hiện tượng teen quốc dân (Ha-Hamama) của Israel, bộ phim xoay quanh chị em nhà Woods, 8 tháng sau khi mẹ mất trong một vụ nổ tàu vũ trụ, họ ghi danh vào Học viện Greenhouse - một trường nội trú tư nhân cho các nhà lãnh đạo tương lai có năng khiếu. Thật không may, hai chị em lại phải gia nhập hai nhóm đối thủ truyền kiếp nhưng lại phải chung tay vào cuộc điều tra bí mật giữa hai nhóm để rồi phát hiện ra bí ẩn chết người buộc thành viên hai nhóm xóa bỏ hiềm khích, tạm gác các mối quan hệ cá nhân và hợp tác bảo vệ thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Grace Van Dien","avatar":""},{"name":"Ariel Mortman","avatar":""},{"name":"Finn Roberts","avatar":""},{"name":"Chris O''Neal","avatar":""},{"name":"Dallas Hart","avatar":""},{"name":"Cinthya Carmona","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["温室学院","Greenhouse Academy"]', 1784690324403);
