INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-rocker', 'Mật Danh Rocker', 'Codename Rocker', 'https://phimimg.com/upload/vod/20241104-1/bcafe56bd6c905ccc220056ed2185e34.jpg', 'https://phimimg.com/upload/vod/20241104-1/ba8c34d81e974d1c87b86795e9036a8a.jpg', '<p>Một vụ án giết người cướp của ẩn chứa nhiều bí ẩn, đã mở ra những cuộc chiến đầy nước mắt và máu trong Mật danh Rocker. Phim hấp dẫn người xem bởi sự khó phân định người thiện - kẻ ác, cùng mạch phim đầy kịch tính với những bí mật.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hoàng Hải","avatar":""},{"name":"Diệp Bảo Ngọc","avatar":""},{"name":"Dương Hoàng Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Молодые и горячие","Hot Blooded Teenager","热血少年"]', 1784690324403);
