INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-song-con-2017', 'Trò Chơi Sống Còn', 'Free Fire', 'https://phimimg.com/upload/vod/20241031-1/f7e562a39f7e6a5c56694df06e30d7fa.jpg', 'https://phimimg.com/upload/vod/20241031-1/f1e68c33fb002c9365a5804e4461a3fa.jpg', '<p>Free Fire là bộ phim hài hành động năm 2016 của đạo diễn Ben Wheatley, do Wheatley và Amy Jump sản xuất. Bộ phim có nội dung kể về cuộc đấu súng vô cùng gam go giữa hai băng nhóm. Mở đầu là cảnh diễn ra một cuộc họp quan trọng trong một nhà kho bỏ hoang tại thành phố Boston của Hoa Kỳ vào năm 1978. Nhưng thực chất đây chỉ là một giao dịch buôn bán vũ khí. Do bất đồng quan điểm, mâu thuẫn từ những người tham gia vào cuộc họp trên đã khiến nơi đây nổ ra một cuộc đọ súng – một trò chơi của sự sống còn.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Babou Ceesay","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"Tom Davis","avatar":""},{"name":"Mark Monero","avatar":""},{"name":"Sara Dee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Hostiles et Armés","Fuego gratuito","Fuego cruzado","Перестрілка","玩命鎗火","フリー・ファイヤー","Φωτιά Στις Κάνες Μας","Päästik põhja","Lodes pa gaisu!","Spausk gaiduką!","Končni obračun","프리 파이어","Kereszttüz","Free Fire: O Tiroteio","Free Fire"]', 1784690324403);
