INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-the', 'Thịnh Thế', 'Advance Bravely', 'https://phimimg.com/upload/vod/20241026-1/3fed62c61cbb0850fd2a3a43544101cd.jpg', 'https://phimimg.com/upload/vod/20241026-1/93ddf40ebd19a76913768c74a14dd366.jpg', '<p>Kể về sự gặp gỡ của anh chàng bộ đội ra binh Viên Tung và chàng trai thanh xuân nhiệt huyết Hạ Diệu, dẫn đến cả một chuỗi câu chuyện cười ra nước mắt nhưng cũng đầy cảm động của họ.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Từ Phong","avatar":""},{"name":"Lý Kiều Đơn","avatar":""},{"name":"Mông Ân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shi Bu Ke Dang","势不可挡","Sheng Shi","盛势"]', 1784690324403);
