INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-man-thien', 'Hoa Mãn Thiên', 'As Flowers Fade And Fly Across The Sky', 'https://phimimg.com/upload/vod/20241026-1/df24530ad667f279121f70b69ca9ea88.jpg', 'https://phimimg.com/upload/vod/20241026-1/6cbee7eeef061ef2e563f8c4f02aa0ed.jpg', '<p>Kinh thành có 4 gia tộc lớn được hoàng đế coi trọng là: Tiêu gia, Tư Mã gia, Hoa gia và Tạ gia. Đại công tử nhà họ Hoa – Hoa Mãn Thiên cùng thiên kim Tạ Gia – Tạ Thiên Tầm vốn là thanh mai trúc mã, đã hứa hôn với nhau. Thế nhưng, Hoa Mãn Thiên lại lọt mắt xanh của công chúa Khuynh Thành – người được hoàng đế vô cùng yêu thương. Từ đây biết bao nhiêu sóng gió thăng trầm xảy ra.</p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"何潤東","avatar":""},{"name":"Zhang Xinyu","avatar":""},{"name":"朱一龍","avatar":""},{"name":"李心艾","avatar":""},{"name":"Jim Yu","avatar":""},{"name":"Zhu Zixiao","avatar":""},{"name":"Deng Yuli","avatar":""},{"name":"Kou Zhenhai","avatar":""},{"name":"Xuan Lu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["花谢花飞花满天","As Flowers Fade and Fly Across the Sky","Hua xie hua fei hua man tian"]', 1784690324403);
