INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-cua-toi', 'Người Hùng Của Tôi', 'Hitorijime My Hero', 'https://phimimg.com/upload/vod/20241019-1/15e657fee88af8c605558a0f88502021.jpg', 'https://phimimg.com/upload/vod/20241019-1/97710382dc501cfed7601d68fcfd0ba3.jpg', '<p>&quot;Em có thể thích anh thật sao?&quot; Chàng trai ngỗ ngược lông bông Setagawa là học sinh kiêm đàn em của giáo viên cấp ba Kousuke. Setagawa luôn bị đùa giỡn bởi thái độ và những lời Kousuke, người mình ngưỡng mộ, không thể nào thích anh ấy! Nhưng khi bị phát hiện thì một ngày 24 tiếng lại luôn...? Càng cố gắng chịu đựng thì lại càng muốn có được người anh hùng của mình, Setagawa nên đối diện với tình cảm này như thế nào đây? Câu chuyện tình yêu giáo viên X học trò vui vẻ cười đùa mà lại kèm theo những giọt nước mắt.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"前野智昭","avatar":""},{"name":"松岡禎丞","avatar":""},{"name":"増田俊樹","avatar":""},{"name":"立花慎之介","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Hitoriji me Maihīrō","รักหมดใจ มาย     ฮีโร่","My Very Own Hero","ひとりじめマイヒーロー"]', 1784690324403);
