INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giup-be-hoc-tu-vung-phan-3', 'Giúp Bé Học Từ Vựng (Phần 3)', 'Word Party (Season 3)', 'https://phimimg.com/upload/vod/20241017-1/52b3e64f4fe003a7025dedd4c285914d.jpg', 'https://phimimg.com/upload/vod/20241017-1/f9f906402d92c25594e6daa0031a6de0.jpg', '<p>Bailey, Franny, Kip và Lulu giúp các bé mẫu giáo học từ mới khi các em thành lập ban nhạc, chơi trò chơi, tìm hiểu về tình bạn và nhiều hoạt động thú vị khác.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Victor Yerrid","avatar":""},{"name":"Alice Dinnean","avatar":""},{"name":"Alon Williams","avatar":""},{"name":"Donna Kimball","avatar":""},{"name":"John Munro Cameron","avatar":""},{"name":"John Tartaglia","avatar":""},{"name":"Arty Casas","avatar":""},{"name":"Dorien Davies","avatar":""},{"name":"Misty Rosas","avatar":""},{"name":"Patina Miller","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["신나는 글자축제","신나는 글자 축제","Word Party"]', 1784690324403);
