INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hoa-tieu-ba-vuong', 'Đào Hoa Tiểu Bá Vương', 'The Romantic Tale Of The Overlord', 'https://phimimg.com/upload/vod/20241016-1/24ecb7fa48376fe98f138725603460e2.jpg', 'https://phimimg.com/upload/vod/20241016-1/47eac88a6c42593a1f27d221097eff4e.jpg', '<p>Mệt mỏi với cuộc sống suốt ngày chỉ biết đánh giết cướp bóc, Chu Thông đã xuống núi và làm một người bình thường. Nhưng với tấm lòng nghĩa hiệp, ông thường trừng trị các quan tham nhũng nên đã đắc tội với không ít người. Vì thế, Chu Thông quyết định đầu quân lên Lương Sơn và trở thành một trong 108 vị anh hùng lỗi lạc.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Bành Mộc Di","avatar":""},{"name":"Dương Tranh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["桃花小霸王"]', 1784690324403);
