INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hanh-trinh-tuyet-voi-phan-2', 'Cuộc Hành Trình Tuyệt Vời (Phần 2)', 'The Grand Tour (Season 2)', 'https://phimimg.com/upload/vod/20241008-1/afb4f6a6a8766508590c9055f3307a68.jpg', 'https://phimimg.com/upload/vod/20241008-1/e506698cd0911f8fd646aa50a7d7d0b8.jpg', '<p>Sau loạt phim đầu tiên, các phân đoạn trường quay của chương trình được quay vĩnh viễn tại Cotswolds. Ngoài ra, những người nổi tiếng đã tham gia đầy đủ hơn vào chương trình so với sự xuất hiện nhỏ mà họ có trong loạt phim trước, tham gia vào một phân đoạn đặc biệt được sử dụng trong phần này chỉ liên quan đến các vòng đối đầu có tính thời gian giữa hai khách mời trong mỗi tập, ngoại trừ của tập cuối cùng là một tập đặc biệt.</p>', 'Full', 11, 'tvshows', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Clarkson","avatar":""},{"name":"Richard Hammond","avatar":""},{"name":"James May","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Гранд тур","伟大的旅程","大世界之旅","歌朗途","The Grand Tour","เดอะแกรนด์ทัวร์","Grand Tour, The"]', 1784690324403);
