INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-kieu-truyen', 'Sở Kiều Truyện', 'Princess Agents', 'https://phimimg.com/upload/vod/20241007-1/f808ae153c5943979adbc7ae1f3b4c17.jpg', 'https://phimimg.com/upload/vod/20241007-1/a476ff50567a8b02f9e9cb5dc17090ae.jpg', '<p>Sở Kiều Truyện - Princess Agents kể về Sở Kiều - một nữ nô lệ bị đưa vào bãi săn bắn nhằm mục đích mua vui cho tầng lớp quý tộc phong kiến và được Tây Lương thế tử Yến Tuân cứu giúp. Sau đó, nàng được đưa vào nhà họ Vũ Văn và lọt mắt xanh của Vũ Văn Nguyệt. Mối quan hệ giữa hai người như nước với lửa khi Vũ Văn Nguyệt luôn ép Sở Kiều phải chịu sự huấn luyện nghiêm khắc từ chàng. Thêm vào đó, tình cảm mà Sở Kiều dành cho Yến Tuân cũng bắt đầu trở nên sâu đậm hơn. Các tầng lớp quý tộc Tây Nguỵ xảy tra tranh đấu khiến gia đình Yên Tuân bị thảm sát. Yên Tuân thay đổi, vì muốn trả thù cho gia tộc nên dã tâm ngày một lớn. Vì sự tàn bạo đó, Sở Kiều chia tay Yên Tuân để kề vai sát cánh bên Vũ Văn Nguyệt với mục tiêu lật đổ kế hoạch báo thù của Yên Tuân và phá bỏ chính sách nô lệ hà khắc mấy trăm năm qua.</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 8, 2017, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đậu Kiêu","avatar":""},{"name":"Lâm Canh Tân","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Trệu Lệ Dĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["11處特工皇妃","楚乔传(TV版)","Agent Empress Chu Chuan","楚喬伝（そきょうでん）～いばらに咲く花～","楚喬伝 いばらに咲く花","Легенда о Чу Цяо","Агенты принцессы","ฉู่เฉียว จอมใจจารชน","楚喬傳","Queen Agent no.11","Legend of Chu Qiao","Princess Agents","特工皇妃楚乔传"]', 1784690324403);
