INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sinh-tu', 'Cuộc Chiến Sinh Tử', 'Death Fighter', 'https://phimimg.com/upload/vod/20241004-1/4bebf8377830a48fe2fe9422632d9166.jpg', 'https://phimimg.com/upload/vod/20241004-1/895f0e4bfb1a5690c58cf0b8c6f5b6a4.jpg', '<p>Khi một cảnh sát Mỹ chứng kiến người cố vấn của mình bị sát hại trong một thỏa thuận thương mại thất bại, anh nhận ra mình đã vi phạm pháp luật ở Thái Lan. Nhưng bất chấp tiền thưởng cho cái đầu và áp lực phải rời khỏi đất nước, anh hợp tác với một cựu lính đánh thuê quân đội để giải quyết vấn đề của riêng mình nhằm đưa những kẻ giết người ra trước công lý. Hành trình trả thù của họ khiến họ phải đối mặt với một nhóm tội phạm khét tiếng.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Mullins","avatar":""},{"name":"Don Wilson","avatar":""},{"name":"Cynthia Rothrock","avatar":""},{"name":"Joe Lewis","avatar":""},{"name":"Jawed Berni","avatar":""},{"name":"Gigi Velicitat","avatar":""},{"name":"Yuhkoh Matsuguchi","avatar":""},{"name":"Prasit Suanphaka","avatar":""},{"name":"Wirat Kemklad","avatar":""},{"name":"Chiranan Manochaem","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Death Fighter"]', 1784690324403);
