INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-co-hoai-lang', 'Dạ Cổ Hoài Lang', 'Hello Vietnam', 'https://phimimg.com/upload/vod/20240920-1/b62897e8f289e09884ffcf71e7db8e80.jpg', 'https://phimimg.com/upload/vod/20240920-1/f1dfa48c173b1e6978ab7369b5c67ddc.jpg', '<p>Dạ Cổ Hoài Lang chuyển thể từ vở kịch kinh điển những năm 90, là câu chuyện cảm động về tình người tình thân. Mượn tâm sự của một người đàn ông già nơi đất khách quê người, phải đối mặt với sự lạc lõng trong gia đình và những khác biệt văn hóa giữa hai dân tộc, vở kịch Dạ Cổ Hoài Lang đã lấy đi nước mắt của nhiều thế hệ và trở thành một trong những tác phẩm sân khấu tiêu biểu. &nbsp;Tiếp nối thành công của bản gốc, Dạ Cổ Hoài Lang được chuyển thể thành phim điện ảnh với sự tham gia của NSƯT Hoài Linh. Ngoài ra, phim còn quy tụ nhiều ngôi sao thực lực tên tuổi như NSƯT Ngọc Hiệp, NSƯT Thanh Hoàng, Thanh Thủy, Đình Hiếu, Will (cựu thành viên nhóm 365), Thanh Mỹ, Trọng Khang...</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hoài Linh","avatar":""},{"name":"Chí Tài","avatar":""},{"name":"Will","avatar":""},{"name":"Võ Đình Hiếu","avatar":""},{"name":"Oanh Kiều","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Hello Vietnam","Dạ Cổ Hoài Lang"]', 1784690324403);
