INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('henri', 'Henri', 'Henri', 'https://phimimg.com/upload/vod/20240918-1/e3f170cf25114d177513368f52866bec.jpg', 'https://phimimg.com/upload/vod/20240918-1/e498d75e17b7252bb6e805f7359a05e4.jpg', '<p>Henri lớn lên trong một tu viện ở Viễn Đông và hiện anh sống ở Mỹ, vùng sâu phía Nam, nơi câu chuyện của anh bắt đầu. Dù được rèn luyện để trở nên bình yên nhưng rắc rối dường như luôn tìm đến anh. Câu chuyện của Henri tràn ngập tình yêu, hành động, hồi hộp và phiêu lưu.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eli Jeffree Zen","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Robert LaSardo","avatar":""},{"name":"Burt Reynolds","avatar":""},{"name":"Lori Katz","avatar":""},{"name":"Steven D. Mairano","avatar":""},{"name":"Jerry Sommer","avatar":""},{"name":"Carl Rimi","avatar":""},{"name":"Roger Byrd","avatar":""},{"name":"Alex Zuko","avatar":""},{"name":"Tina Pfeiffer","avatar":""},{"name":"Xavier Luo","avatar":""},{"name":"Stacey Steele","avatar":""},{"name":"Steve Daron","avatar":""},{"name":"Mitch Price","avatar":""},{"name":"Felix Fernandez","avatar":""},{"name":"Lee Marlow","avatar":""},{"name":"Brooklyn Murphy","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["HENRI","Henri"]', 1784690324403);
