INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-nui-giua-hai-ta', 'Ngọn Núi Giữa Hai Ta', 'The Mountain Between Us', 'https://phimimg.com/upload/vod/20240713-1/178c113ec22f44c23f600e27a0e826a6.jpg', 'https://phimimg.com/upload/vod/20240713-1/c6d14523e3374141e4229c46f27b123f.jpg', '<p>Bị mắc kẹt sau một tai nạn máy bay, hai người lạ mặt phải tạo ra một mối liên hệ để tồn tại ở một đỉnh núi tuyết bao phủ. Khi nhận ra không có sự giúp đỡ nào, họ bắt tay vào một cuộc hành trình nguy hiểm trên hàng trăm dặm của vùng hoang dã, đẩy lẫn nhau để tăng sức chịu đựng và khám phá sức mạnh mà họ chưa từng biết.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Beau Bridges","avatar":""},{"name":"Linda Sorensen","avatar":""},{"name":"Mercy Myrdal","avatar":""},{"name":"Dania Nassar","avatar":""},{"name":"Vincent Gale","avatar":""},{"name":"Marci T. House","avatar":""},{"name":"Lee Majdoub","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
