INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ca-fadil-2', 'Anh Cả Fadil 2', 'Abang Long Fadil 2', 'https://phimimg.com/upload/vod/20240910-1/2111830f035f3bfc457ddef61a1aecf2.jpg', 'https://phimimg.com/upload/vod/20240910-1/9ad47e81f730ff6dff3670e95847ed70.jpg', '<p>Khi cảnh sát nhầm Fadil là một sát thủ khét tiếng, anh bắt đầu gột rửa tiếng xấu cho mình bằng cách lật tẩy danh tính thật của tên sát nhân</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Zizan Razak","avatar":""},{"name":"Syamsul Yusof","avatar":""},{"name":"Datuk AC Mizal","avatar":""},{"name":"Tania Hudson","avatar":""},{"name":"Wak Doyok","avatar":""},{"name":"Achey Bocey","avatar":""},{"name":"Shuib Sepah","avatar":""},{"name":"A. Galak","avatar":""},{"name":"Mas Khan","avatar":""},{"name":"Dalimawati","avatar":""},{"name":"Hafiz Bahari","avatar":""},{"name":"Syed Haikal","avatar":""},{"name":"Ashraf Rahman","avatar":""},{"name":"Fad Anuar","avatar":""},{"name":"Dato'' Yusof Haslam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324403);
