INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-yen-duoi-vuc-sau', 'Lặng Yên Dưới Vực Sâu', 'Silence In The Abyss', 'https://phimimg.com/upload/vod/20240911-1/07699119548f5499267299c6461a95f7.jpg', 'https://phimimg.com/upload/vod/20240911-1/083b1d2630fea80ea5156e02a489f19e.jpg', '<p>Lặng yên dưới vực sâu kể về mối tình của Vừ (Đình Tú) – một chàng trai tài giỏi, tốt bụng đã đem lòng yêu Súa (Phương Oanh) – một cô gái xinh đẹp, mạnh mẽ. Nhưng tình yêu của họ lại bị ngăn cấm bởi gia đình nhà Súa do hoàn cảnh nhà Vừ nghèo, không có tiền cưới vợ, còn Súa thì lại bị Phống (Doãn Quốc Đam) – một thanh niên nhà giàu, cướp về làm vợ. Không đến được với nhau, Súa đành trao duyên lại cho cô bạn thân của mình là Xí (Nguyễn Hương Giang). Những tưởng tình yêu Vừ – Súa sẽ kết thúc ở đây, nhưng bằng bản năng mạnh mẽ, khát vọng tự do của Súa đã khiến cô không chấp nhận và chịu đầu hàng số phận. Còn Vừ, tuy có những lúc tuyệt vọng, định buông xuôi đón nhận tình cảm của Xí, nhưng cuối cùng, anh hành động theo tiếng gọi của trái tim...</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 16, 2017, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Đình Tú","avatar":""},{"name":"Phương Oanh","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Hương Giang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324403);
