INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nham-mat-lai', 'Nhắm Mắt Lại', 'Close Your Eyes', 'https://phimimg.com/upload/vod/20231108-1/aa714d2441b40d3806edde70327d0bad.jpg', 'https://phimimg.com/upload/vod/20231108-1/cdee6db412d8955fe8ca4f5081dd82c7.jpg', '<p>Hyeon-u thường đeo kính râm và giả mù để lắng nghe câu chuyện của nhiều người. Một ngày nọ, có một người kể anh nghe tình tiết của một vụ giết người, Hyeon-u cười phá lên và bảo rằng đó chỉ là tình tiết trong cuốn tiểu thuyết mà anh đang viết. Tuy nhiên vụ giết người đó lại trở thành sự thật. Rốt cuộc tên hung thủ là ai?</p>', 'Full', 1, 'single', 'completed', 4, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Sun-woo","avatar":""},{"name":"Seol In-a","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Lee Han-jong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324403);
