INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-cua-badrinath', 'Cô Dâu Của Badrinath', 'Badrinath Ki Dulhania', 'https://phimimg.com/upload/vod/20231108-1/cddf28546cd70a8c67d99e78e9b83c34.jpg', 'https://phimimg.com/upload/vod/20231108-1/da752a33f5dcde2d18f4c1189839c429.jpg', '<p>Phim Cô Dâu Của Badrinath - Badrinath Ki Dulhania 2017: Badri Bansal sinh ra trong 1 gia đình khá giả, có 1 ông bố gia trưởng và cổ hủ về việc cưới xin của 2 con trai. Vaidehi là cô gái mạnh mẽ cá tính, theo đuổi ước mơ của riêng mình. Badrinath đã yêu Vaidehi ngay từ cái nhìn đầu tiên. Và bằng cố gắng, anh đã thuyết phục được ông bố khó tính rước Vaidehi về rinh. Nhưng cuộc sống không giống cuộc đời, Vaidehi bỏ đi ngay trước lễ cưới. Mọi chuyện sẽ ra sao? Vì sao nàng bỏ đi?</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Varun Dhawan","avatar":""},{"name":"Alia Bhatt","avatar":""},{"name":"Shweta Basu Prasad","avatar":""},{"name":"Gauahar Khan","avatar":""},{"name":"Sahil Vaid","avatar":""},{"name":"Shiv Darshan","avatar":""},{"name":"Aakanksha Singh","avatar":""},{"name":"Puneet Singh Ratn","avatar":""},{"name":"Yash Sinha","avatar":""},{"name":"Gaurav Pandey","avatar":""},{"name":"Swanand Kirkire","avatar":""},{"name":"Rituraj Singh","avatar":""},{"name":"Kanupriya Pandit","avatar":""},{"name":"Aparshakti Khurana","avatar":""},{"name":"Sukhmani Lamba","avatar":""},{"name":"Rajendra Sethi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324403);
