INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-dam-mau', 'Trò Chơi Đẫm Máu', 'Bloody Crayons', 'https://phimimg.com/upload/vod/20231108-1/70c6253ae07af5a374579ac5c53f4233.jpg', 'https://phimimg.com/upload/vod/20231108-1/9c6d55d811de8263ce371c39182408c4.jpg', '<p>&quot;Bloody Crayons&quot; là câu chuyện về một nhóm sinh viên sắp tốt nghiệp đến thăm một hòn đảo để thực hiện dự án phim ngắn trong kỳ nghỉ hè. Một lần, họ quyết định chơi trò Bloody Crayons, kéo theo đó là một loạt những sự việc bí ẩn đã xảy ra. Những bí ẩn bị tiết lộ, tình bạn bị hủy hoại, những sự phẫn nộ không thể kiểm soát. Một tên sát nhân xuất hiện trong nhà khiến cho mọi thứ càng trở nên tệ hơn, họ cần phải tìm ra hắn trước khi tất cả đều bị giết.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Janella Salvador","avatar":""},{"name":"Elmo Magalona","avatar":""},{"name":"Sofia Andres","avatar":""},{"name":"Ronnie Alonte","avatar":""},{"name":"Jane Oineza","avatar":""},{"name":"Maris Racal","avatar":""},{"name":"Empoy Marquez","avatar":""},{"name":"Diego Loyzaga","avatar":""},{"name":"Yves Flores","avatar":""},{"name":"Nanding Josef","avatar":""},{"name":"Sarah Jane Abad","avatar":""},{"name":"Marc Abaya","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
