INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-lon-phan-11', 'Vụ Nổ Lớn (Phần 11)', 'The Big Bang Theory (Season 11)', 'https://phimimg.com/upload/vod/20240910-1/802230a66c5d620ab76b46910177c086.jpg', 'https://phimimg.com/upload/vod/20240910-1/ce8f2bf54b3ed7fca14eb5829be7d5bc.jpg', '<p>Hai nhà vật lý Leonard và Sheldon nhận ra nhóm mọt sách của họ cùng hai người bạn Howard và Raj mở rộng khi Penny, nữ diễn viên chưa thành danh, chuyển vào căn hộ kế bên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Johnny Galecki","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Kaley Cuoco","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Melissa Rauch","avatar":""},{"name":"Mayim Bialik","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324403);
