INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boruto-naruto-hau-sinh-kha-uy', 'Boruto - Naruto: Hậu Sinh Khả Úy', 'Boruto: Naruto Next Generations', 'https://phimimg.com/upload/vod/20240902-1/1eee90f5e137b0bbdece180f057f31ba.jpg', 'https://phimimg.com/upload/vod/20240902-1/9fd25475d1ffaf458771addb177476dc.jpg', '<p>Naruto là một chàng trai trẻ đầy nhiệt huyết cũng như rất nghịch ngợm. Sau tất cả thì cậu cũng đã đạt được ước mơ của mình trở thành một Hokage vĩ đại nhất. Nhưng câu chuyện này không phải về Naruto, mà là câu chuyện về con trai của Naruto.... Chính là Boruto, thế hệ Ninja tiếp theo.</p>', 'Hoàn Tất (293/293)', 293, 'hoathinh', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"三瓶由布子","avatar":""},{"name":"菊池こころ","avatar":""},{"name":"木島隆一","avatar":""},{"name":"白石涼子","avatar":""},{"name":"川田紳司","avatar":""},{"name":"中井和哉","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324403);
