INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dau-nhan-ban', 'Đối Đầu Nhân Bản', 'Duel', 'https://phimimg.com/upload/vod/20240902-1/bbdf0241a7ad59818f50edc77268ccbb.jpg', 'https://phimimg.com/upload/vod/20240902-1/a3c42d52fb21d49d486bfa31e841478e.jpg', '<p>Bộ phim Đối Đầu Nhân Bản xoay quanh cuộc chiến của các nhân bản. Jang Deok Cheon là đội trưởng của đội cảnh sát. Trong gia đình, ông là một người cha tốt bụng và luôn yêu thương con gái. Trong lúc điều tra về vụ bắt cóc của con gái mình, ông bị vướng vào cuộc chiến của hai nhân bản tốt và xấu, có liên quan đến vụ án bắt cóc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2017, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Yea-eun","avatar":""},{"name":"정재영","avatar":""},{"name":"김정은","avatar":""},{"name":"양세종","avatar":""},{"name":"서은수","avatar":""},{"name":"윤경호","avatar":""},{"name":"Lee Na-Yoon","avatar":""},{"name":"김기두","avatar":""},{"name":"이성욱","avatar":""},{"name":"Choi Woong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
