INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-cuoi-cung', 'Giấc Mơ Cuối Cùng', 'The Last Dream', 'https://phimimg.com/upload/vod/20231102-1/45e8970540e04ea5d60905323523fdfa.jpg', 'https://phimimg.com/upload/vod/20231102-1/c597e6aa49abfdf82e39df9509cb11af.jpg', '<p>Phim Giấc Mơ Cuối Cùng - The Last Dream 2017: Trong tương lai, nơi mà mọi người đã mất khả năng mơ, một công ty đã kinh doanh bằng cách thuê những người còn khả năng mơ, nghe họ kể về giấc mơ của mình. Một nhân viên kiểu mẫu, Khalil, là một trong những người tiêu biểu cho đến một ngày, giấc mơ của ông không còn như công ty mong muốn.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Noémie Nakai","avatar":""},{"name":"Mari Yamamoto","avatar":""},{"name":"Carmen Kobayashi","avatar":""},{"name":"Mekdachi Khalil","avatar":""},{"name":"Moctar Diouf","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
