INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-tinh-scooby-doo-phan-2', 'Bình Tĩnh, Scooby Doo (Phần 2)', 'Be Cool, Scooby-Doo! (Season 2)', 'https://phimimg.com/upload/vod/20240729-1/fb1d33ac3ef66a305dcd1d4751b1795a.jpg', 'https://phimimg.com/upload/vod/20240729-1/bf6400cf937d5fe0267976b438cd21eb.jpg', '<p>Do làm việc quá căng thẳng, cả đội đã bắt Fred nghỉ ngơi ở ngôi nhà trên bãi biển của gia đình Daphne. Thật không may khi một con cá mập biết đi tấn công bãi biển, cả nhóm phải phá giải bí ẩn và không được cho Fred biết chuyện đó.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matthew Lillard","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Frank Welker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324403);
