INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-vo-chong', 'Hoán Đổi Vợ Chồng', 'The Day of Swapping', 'https://phimimg.com/upload/vod/20240724-1/f61e93104b39d53109f4c076f9f88b0c.jpg', 'https://phimimg.com/upload/vod/20240724-1/26f3cd4a8b5e4ff91686ceefc56f870a.jpg', '<p>Là một bộ phim mới 18+ được sản xuất năm 2017 của Hàn Quốc. Một quốc gia có nền điện ảnh phát triển khá đa dạng về thể loại, ngoài những bộ phim truyền hình rất ăn khách hay thi thoảng là boom tấn điện ảnh vươn tầm châu lục thì Hàn Quốc còn có khá nhiều tựa phim mới 18+ được phát hành rộng rãi mà ngay đầu năm 2017 khán giả đã được “rửa mắt” cùng dàn diễn viên trẻ đẹp với bộ phim Hoán Đổi Vợ Chồng của đạo diễn Myeong Seok-hwan. Một tựa phim đầy sáng tạo với ý tưởng mới mẻ, quan trọng hơn cả là diễn xuất khá tốt của 2 cặp đôi trong phim cùng với những cảnh quay nóng bỏng đẹp mắt, The Day Of Swapping hứa hẹn mang tới cho bạn những giờ phút giải trí thực sự thú vị.</p>', 'Full', 1, 'single', 'completed', 26, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Joo Ye-bin","avatar":""},{"name":"Baek Se-ri","avatar":""},{"name":"민도윤","avatar":""},{"name":"Ji Eun-seo","avatar":""},{"name":"Jang Seok-min","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324403);
