INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuon-mat-cuoi-cung', 'Khuôn Mặt Cuối Cùng', 'The Last Face', 'https://phimimg.com/upload/vod/20231102-1/06a2c4346def0a166b3f29a090c1724d.jpg', 'https://phimimg.com/upload/vod/20231102-1/9f3cf825d069f0ae8e5f73bce3c2bc7b.jpg', '<p>Miguel (Javier Bardem), một bác sĩ người Tây Ban Nha, đã dấn thân vào hiểm nguy để cung cấp cứu trợ về y tế cho các nạn nhân vùng chiến sự tại Châu Phi. Wren (Charlize Theron) là phát ngôn viên của một tổ chức, nơi lập những gói viện trợ cho các khu vực và vùng lãnh thổ bị chiến tranh, nạn đói tàn phá. Họ gặp nhau ở Liberia, nơi Wren lập tức bị sự xả thân quên mình của Miguel gây ấn tượng mạnh mẽ, sự cuốn hút từ vẻ ngoài cũng như tài năng trong y khoa. Họ bắt đầu gây dựng một mối quan hệ, và họ sẽ làm cách nào để cân bằng giữa công việc và mối quan hệ đó?</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlize Theron","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Adèle Exarchopoulos","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Hopper Penn","avatar":""},{"name":"Denise Newman","avatar":""},{"name":"Mark De Villiers","avatar":""},{"name":"Amy Harries-Jones","avatar":""},{"name":"Obed Baloyi","avatar":""},{"name":"Merritt Wever","avatar":""},{"name":"Vaneshran Arumugam","avatar":""},{"name":"Tinarie Van Wyk-Loots","avatar":""},{"name":"Sebelethu Bonkolo","avatar":""},{"name":"Sibongile Mlambo","avatar":""},{"name":"Bill","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
