INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-nho-ten-toi', 'Hãy Nhớ Tên Tôi', 'Marionette', 'https://phimimg.com/upload/vod/20231101-1/613afa880975eacd80e8137514e8575e.jpg', 'https://phimimg.com/upload/vod/20231101-1/748d0bc5ec15cfe2dba0de86107cd974.jpg', '<p>Han Seo Rin là một giáo viên tại trường cấp 3, hồi đi học cô đã từng bị hãm hiếp tập thể rồi bị quay clip lại từ đó việc đấy đã để lại cho cô một nỗi ám ảnh tâm lý lớn. Sau này khi đi dạy học, vào một ngày đi làm ca tối, cô ấy uống nước do học sinh tặng rồi rơi vào trạng thái hôn mê và lại bị người khác quay clip và những bức ảnh không hay. Từ đó một nhân vật mang tên Master xuất hiện. Mọi việc được thao túng kiểm soát bởi một tay Master, từ đó những sự ám ảnh, hoảng sợ luôn bám riết lấy cô.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee You-young","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Oh Ha-nee","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Kim Da-mi","avatar":""},{"name":"Kim Young-sun","avatar":""},{"name":"Lee Je-yeon","avatar":""},{"name":"Jang Hyuk-jin","avatar":""},{"name":"Son Kang-gook","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Lee Jae-hyeok","avatar":""},{"name":"Jung Woo-jin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324403);
