INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-khac-tinh', 'Cặp Đôi Khắc Tinh', 'Two Wrongs Make a Right', 'https://phimimg.com/upload/vod/20231101-1/e3117e7194336ba984a9da357162dd6e.jpg', 'https://phimimg.com/upload/vod/20231101-1/65aa9f20a35658b9285910039979f6c6.jpg', '<p>Tần Thùy là 1 đại sư “đẹp – giỏi – giàu”, nổi tiếng nhờ tài xem số và phong thủy, có thể tiên đoán như thần. Vừa biết được bản thân sắp gặp đại nạn, cần phải cùng người có bát tự phù hợp để giúp mình che chắn tai ương thì anh tìm được Bội Bội, cô gái sinh ra đã mang mệnh xúi quẩy, làm gì hỏng nấy...</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vic Chou","avatar":""},{"name":"Fiona Sit","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Joy Sheng","avatar":""},{"name":"Sean Liu","avatar":""},{"name":"He Yi-Hang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324403);
