INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-vuong', 'Bạch Vương', 'The White King', 'https://phimimg.com/upload/vod/20231101-1/c04849fd00568849de2c9651c143865a.jpg', 'https://phimimg.com/upload/vod/20231101-1/e1e543c9f84fcb64e8e48374df866045.jpg', '<p>Djata - một cậu bé 12 tuổi lớn lên ở một vùng đất nơi được cai trị dưới chế độ độc tài, và cậu bé không được tiếp cận với phần còn lại của thế giới. Từ nhỏ cậu đã được cha mình kể về nguồn gốc thật sự của nơi mình sinh ra, và bí mật về một kho báu được canh giữ bởi một người đàn ông tên là Pickaxe. Cho đến một ngày cha cậu bị hai người của chính phủ bắt đi...</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Lorenzo Allchurch","avatar":""},{"name":"Agyness Deyn","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Ross Partridge","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Greta Scacchi","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""},{"name":"Clare-Hope Ashitey","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Vilmos Heim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324403);
