INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-rac-roi', 'Anh Em Rắc Rối', 'Trouble Makers', 'null', 'https://phimimg.com/upload/vod/20231101-1/5413039ec0db2d0af977206427813c6f.jpg', '<p>Anh Em Rắc Rối - Trouble Makers/Brother, Come On! với nhân vật chính là Trịnh Hảo - một người rất giỏi lừa gạt và lắm chiêu trò nhưng đang lâm vào cảnh nợ nần sau khi ra tù. Em trai của anh ta là Trịnh Trọng, thừa cân nhưng thiếu thông minh, đã tiêu hết những khoản tiền tiết kiệm của Trịnh Hảo. Hai người họ cùng tham gia vào chương trình truyền hình thực tế.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Xiaopan","avatar":""},{"name":"Yu Shasha","avatar":""},{"name":"Samuel Pang","avatar":""},{"name":"You Xianchao","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Wan Guopeng","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Sky Li","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324403);
