INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thich-khach-phong-luu', 'Thích Khách Phong Lưu', 'Romantic Assassin', 'https://phimimg.com/upload/vod/20240902-1/b8a9246e898db4b00e804f83cc257283.jpg', 'https://phimimg.com/upload/vod/20231101-1/0b4b76b7f8d9c41bd87b35d0e951837b.jpg', '<p>Nội dung của phim Thích Khách Phong Lưu xoay quanh một sát thủ chuyên nghiệp tên là Lâm Hổ (Trần Hổ), người có thể hoàn thành bất kỳ phi vụ nào với tài năng kiệt xuất, đặc biệt anh ta chỉ nhận giết kẻ ác, không giết người tốt. Hổ vừa mới nhận lệnh truy sát Châu Nhị với số tiền lên tới 3 ngàn lượng vàng. Trên đường đi tìm mục tiêu của mình, anh bị bất tỉnh do đang mắc một căn bệnh lạ, Hà Thanh – “người tình” của Châu Nhị, vô tình bắt gặp và đưa anh về nhà để nghỉ ngơi, sau khi tỉnh dậy người đầu tiên anh nhìn thấy chính là Châu Nhị, nghĩ rằng Nhị đã cứu mình nên không giết ngay mà cho y 2 ngày để trốn. Sau đó, Hổ rời khỏi nhà Thanh Hà để đi tìm nơi tá túc.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Tiger Hu Chen","avatar":""},{"name":"Zhu Jiaxi","avatar":""},{"name":"Wang Xiaoyi","avatar":""},{"name":"Dufeng Yurong","avatar":""},{"name":"Xu Liwei","avatar":""},{"name":"Kai Shen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324403);
