INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-tim-rong', 'Khế Ước Tìm Rồng', 'Xun Long Qi Yue', 'https://phimimg.com/upload/vod/20231101-1/bc50c5fe358ca57e833ca461c005944f.jpg', 'https://phimimg.com/upload/vod/20231101-1/6f3240ccdaff1690677b4a6e2f91684d.jpg', '<p>Phim Khế Ước Tìm Rồng - Xun Long Qi Yue 2017: Một con tàu bồng nhiên biến mất giữa biển khơi đã mở đầu cho cuộc chiến giữa tộc Ma và tộc Thợ Săn. Nhóm tộc Thợ Săn cùng người phong ấn phải dấn thân vào hang hổ của tộc Ma để tìm những thủy thủ bị mất tích. Đồng thời, họ còn phải chiến đấu với tộc Ma để giải cứu thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Danson Tang","avatar":""},{"name":"Calvin Chen","avatar":""},{"name":"Ceng Meng-Xue","avatar":""},{"name":"Yokie Xu Yi","avatar":""},{"name":"Qiu Xiaodong","avatar":""},{"name":"Li Yi-Ming","avatar":""},{"name":"Zhang Hengrui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324403);
