INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-vat-va', 'Thanh Xuân Vật Vã', 'Fight For My Way', 'https://phimimg.com/upload/vod/20240901-1/1b2ff2d6a3af3d0136972af495f12611.jpg', 'https://phimimg.com/upload/vod/20240901-1/59a719ee519a786240f34e31d6bc008e.jpg', '<p>Là bộ phim lấy đề tài chia sẻ những câu chuyện của hai con người trẻ tuổi, những người mà luôn cố gắng để có thể bước đi trên con đường mà họ mơ ước mặc dù thực tế khó khăn trên con đường đó.

Park Seo Joon vào vai Go Dong Man, là 1 cựu vận động viên môn Teakwondo đã từng rất nổi tiếng trong quá khứ nhưng cuối cùng lại trở thành 1 đấu sĩ võ thuật tổng hợp vô danh.

Trong đó Kim Ji Won vào vai Choi A Ra, một người phụ nữ làm việc tại 1 cửa hàng bách hóa, nhưng luôn mơ ước được trở thành phát thanh viên.

Hai người họ đã biết nhau từ lâu và đều là những người bạn tốt của đối phương mà họ có thể trêu đùa lẫn nhau thật thoải mái. Liệu cả 2 có thành công để con đường mà họ mơ ước?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박서준","avatar":""},{"name":"김지원","avatar":""},{"name":"안재홍","avatar":""},{"name":"송하윤","avatar":""},{"name":"김성오","avatar":""},{"name":"진희경","avatar":""},{"name":"이엘리야","avatar":""},{"name":"김건우","avatar":""},{"name":"Yang Jae-young","avatar":""},{"name":"Chae Dong-hyeon","avatar":""},{"name":"표예진","avatar":""},{"name":"손병호","avatar":""},{"name":"김예령","avatar":""},{"name":"전배수","avatar":""},{"name":"Kim Hee-chang","avatar":""},{"name":"Kim Seong-beom","avatar":""},{"name":"정순원","avatar":""},{"name":"강기둥","avatar":""},{"name":"최우식","avatar":""},{"name":"Baek Soo-jang","avatar":""},{"name":"Jo Yeon-ho","avatar":""},{"name":"Lee Han-seo","avatar":""},{"name":"Kim Ha-yeon","avatar":""},{"name":"Lee Dal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
