INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-xuan-vat-va', 'Thanh Xuân Vật Vã', 'Fight For My Way', 'thanh xuân vật vã fight for my way 박서준 김지원 안재홍 송하윤 김성오 진희경 이엘리야 김건우 yang jae-young chae dong-hyeon 표예진 손병호 김예령 전배수 kim hee-chang kim seong-beom 정순원 강기둥 최우식 baek soo-jang jo yeon-ho lee han-seo kim ha-yeon lee dal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-ten-xanh-phan-6', 'Mũi Tên Xanh (Phần 6)', 'Arrow (Season 6)', 'https://phimimg.com/upload/vod/20240624-1/5574b9b0bbc709982476d93f1961a313.jpg', 'https://phimimg.com/upload/vod/20240624-1/18e37d50fdb5c7363af8a68128cd497d.jpg', '<p>Mũi Tên Xanh Phần 6 - Arrow (Season 6) là bộ phim truyền hình hành động phiêu lưu, hình sự tội phạm Mỹ 2014. Bộ phim là sự sáng tạo lại từ nhân vật cùa DC Comics, Arrow không phải là một thể loại siêu anh hùng, mà chỉ đơn thuần là một anh hùng bình thường nhưng bí ẩn của công dân Starling, anh hùng Oliver Queen. Một cuộc sống bình yên và an toàn nhờ số lượng tội phạm trong thành phố đã giảm, Oliver tin rằng anh cuối cùng đã có thể có một cuộc sống riêng tư với Felicity vào một ngày. Thế nhưng, một nhân vật phản diện chết người lại xuất hiện trong Starling, buộc Oliver nhận ra rằng anh không bao giờ có thể là một Oliver Queen bình thường. Mọi diễn biến sẽ ra sao? Liệu anh có thể tiếp tục chiến tháng cái ác và tiếp tục giữ lại hoà bình cho Starling?</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Amell","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"David Ramsey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324403);
