INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quoc-si-vo-song-hoang-phi-hong', 'Quốc Sĩ Vô Song Hoàng Phi Hồng', 'Huang Fei Hong', 'https://phimimg.com/upload/vod/20240831-1/f5e0ba4698ff4a42bc5bcb66e9e05ddd.jpg', 'https://phimimg.com/upload/vod/20240831-1/6f7256c611c69407aa10dc99024c4221.jpg', '<p>Quốc Sĩ Vô Song Hoàng Phi Hồng - Huang Fei Hong kể về Hoàng Phi Hồng, tông sư của giới võ thuật Lĩnh Nam, đồng thời cũng là một vị danh y, luôn mang hoài bão với cuộc đời. Thời niên thiếu, Hoàng Phi Hồng luôn chiến đấu hết mình ở Đài Loan. Ông đã cùng Hắc Kỳ quân và các dũng sĩ của tộc Trại Đức Khắc đứng lên chống lại cuộc xâm lăng của quân Nhật, và trở thành vị anh hùng cái thế bảo vệ nước nhà. Sau khi về Quảng Châu, ông mở hiệu thuốc Bảo Chi Lâm và tiếp tục con đường hành nghề y, không dạy võ nữa. Tuy nhiên, giang hồ tranh đấu không ngừng nghỉ buộc ông lại lần nữa rơi vào cảnh đánh nhau sinh tử nhưng chính nó cũng đưa ông trở thành cao thủ vô song trong giới võ thuật. Ông nhận được sự ngưỡng mộ của nhiều người, trừ Thiết Mã Lưu - vị anh hùng âm thầm giết những quan tham lại tái xuất trên giang hồ. Và rồi, một trận chiến giữa hai vị anh hùng “ngoài sáng” và “trong tối” xuất hiện.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Khải","avatar":""},{"name":"Hải Lục","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324403);
