INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-nha-vua-yeu', 'Khi Nhà Vua Yêu', 'The King In Love', 'https://phimimg.com/upload/vod/20240829-1/1c17d79a332defdc99981a4d6b2d66ae.jpg', 'https://phimimg.com/upload/vod/20240829-1/c7aee30ade9a6ba328821ea03827e2bb.jpg', '<p>Phim Hàn Quốc Khi Nhà Vua Yêu (The King Loves 2017) chuyển thể từ tiểu thuyết cùng tên kể về chuyện tình tay ba giữa nhà vua tương lai Wang Won (Im Shi Wan), cô tiểu thư Eun San (Yoona) và hậu vệ đồng thời là bạn thân từ nhỏ của Wang Won, Wang Rin (Hong Jong Hyun).</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2017, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"임시완","avatar":""},{"name":"윤아","avatar":""},{"name":"홍종현","avatar":""},{"name":"박환희","avatar":""},{"name":"오민석","avatar":""},{"name":"윤종훈","avatar":""},{"name":"정보석","avatar":""},{"name":"장영남","avatar":""},{"name":"이기영","avatar":""},{"name":"엄효섭","avatar":""},{"name":"Park Young-woon","avatar":""},{"name":"Choo Soo-hyun","avatar":""},{"name":"남다름","avatar":""},{"name":"Lee Seo-yeon","avatar":""},{"name":"윤찬영","avatar":""},{"name":"기도훈","avatar":""},{"name":"Kim Jeong-wook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324403);
