INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-nha-vua-yeu', 'Khi Nhà Vua Yêu', 'The King In Love', 'khi nhà vua yêu the king in love 임시완 윤아 홍종현 박환희 오민석 윤종훈 정보석 장영남 이기영 엄효섭 park young-woon choo soo-hyun 남다름 lee seo-yeon 윤찬영 기도훈 kim jeong-wook ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-phuong-bat-tu-thuong', 'Cô Phương Bất Tự Thưởng', 'General And I', 'https://phimimg.com/upload/vod/20240828-1/0bc667a450fc3738dd2fa0c3e4ddac13.jpg', 'https://phimimg.com/upload/vod/20240828-1/efa814a0ee51ae4802a5d028b9b86efd.jpg', '<p>Phim là câu chuyện về bốn quốc gia Tấn, Yên, Hàn, Tần trong đó nước Tấn là có quyền lực mạnh nhất. Phim kể về việc Trấn Bắc vương Sở Bắc Tiệp của Tấn quốc nảy sinh tình cảm với nữ tỳ Bạch Sính Đình của Yên quốc.

Bạch Sính Đình là một thị nữ nổi danh trong vương phủ Kính An ở Yên quốc. Vốn thông minh, tài trí và sở hữu tiếng đàn làm say đắm lòng người. Bạch Sính Đình gặp gỡ và đem lòng yêu Sở Bắc Tiệp – người đàn ông quyền lực tối thượng, dáng vẻ uy nghi, phi phàm. Tuy nhiên tình yêu của cả 2 lại liên tiếp gặp phải trắc trở vì ở 2 chiến tuyến khác nhau và vì thiên hạ loạn lạc vì sự ích kỷ của những kẻ cầm quyền.</p>', 'Hoàn Tất (62/62)', 62, 'series', 'completed', 6, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"AngelaBaby","avatar":""},{"name":"鍾漢良","avatar":""},{"name":"Gan Ting Ting","avatar":""},{"name":"孫藝洲","avatar":""},{"name":"Madina Memet","avatar":""},{"name":"Mu Leen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324403);
