INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-di-dung-so', 'Yêu Đi Đừng Sợ', 'Kiss & Spell', 'https://phimimg.com/upload/vod/20240823-1/3cbbe4ddebcac27711617fcdaa29444b.jpg', 'https://phimimg.com/upload/vod/20240823-1/c899c5b9454b05e38be0f04540e89b91.jpg', '<p>Yêu đi, đừng sợ! là câu chuyện tình yêu tróe ngoe, bi hài giữa Tùng (Ngô Kiến Huy), một chàng ảo thuật gia nổi tiếng với những màn hù dọa rùng rợn nhưng cực kì sợ ma và cô gái bí ẩn hay bị ma ám Phương (Nhã Phương). Định mệnh đưa Tùng đến với Phương bằng sự tò mò và chinh phục, sự rung động và cảm thông đưa Phương bước ra khỏi chiếc vỏ bọc khép kín. Những tưởng cả hai sẽ có thể vững tâm đến bên nhau và &quot;yêu đi, đừng sợ!&quot; nhưng những chuyện kì bí không ngừng diễn ra, cả hai phải đối diện với những trò quậy phá nguy hiểm tính mạng của kẻ đến từ cõi âm, ma nữ Vân, cũng là bạn thời trung học của Phương.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Ngô Kiến Huy","avatar":""},{"name":"Nhã Phương","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324403);
