INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-xanh-ii', 'Hành Tinh Xanh II', 'Blue Planet II', 'https://phimimg.com/upload/vod/20240820-1/479b17b37c6767ca86da99dc8b108f9f.jpg', 'https://phimimg.com/upload/vod/20240820-1/4e40c0e00576146d9aa4bd9090413302.jpg', '<p><span style="text-wrap: wrap;">Những chuyến hành trình thám hiểm các đại dương sâu thẳm và thế giới sinh vật kỳ lạ ở các vùng biển khác nhau.</span></p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324403);
