INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-thuong-khung-ban-dac-biet-1-dinh-menh', 'Đấu Phá Thương Khung Bản Đặc Biệt 1 (Định Mệnh)', 'Fights Break Sphere Special 1 (Fate)', 'đấu phá thương khung bản đặc biệt 1 (định mệnh) fights break sphere special 1 (fate)  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-21-ban-tinh-ca-mau-do-tham', 'Thám Tử Lừng Danh Conan 21: Bản Tình Ca Màu Đỏ Thẫm', 'Case Closed: The Crimson Love Letter', 'https://phimimg.com/upload/vod/20231019-1/84f91112b6fe999381342ad1f84e8f81.jpg', 'https://phimimg.com/upload/vod/20231019-1/80b471a5e8172dd3732e7583c841bab3.jpg', '<p>Một đài truyền hình ở Osaka đột ngột phát nổ. Conan và nhóm bạn hoang mang không rõ mục đích của hung thủ. Sự xuất hiện của nhân vật mới Ooka Momiji càng khiến họ trở trở nên bối rối: cô nàng tự xưng là vị hôn thể của Heiji Hattori và là nhà vô địch giải đấu Karuta (một trò chơi thẻ truyền thống của Nhật Bản). Mặt khác, quán quân của giải Karuta tại Kyoto liên tiếp bị sát hại trong 2 năm liền. Trong khi hình ảnh vị quán quân mới Momiji được phát sóng trực tiếp trên truyền hình, một vụ án mạng khác lặng lẽ xảy ra.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2017, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Satsuki Yukino","avatar":""},{"name":"Osamu Saka","avatar":""},{"name":"Daisuke Miyagawa","avatar":""},{"name":"Riho Yoshioka","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Nobuyuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324403);
