INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-21-ban-tinh-ca-mau-do-tham', 'Thám Tử Lừng Danh Conan 21: Bản Tình Ca Màu Đỏ Thẫm', 'Case Closed: The Crimson Love Letter', 'thám tử lừng danh conan 21: bản tình ca màu đỏ thẫm case closed: the crimson love letter minami takayama kappei yamaguchi wakana yamazaki rikiya koyama ryou horikawa yuko miyamura satsuki yukino osamu saka daisuke miyagawa riho yoshioka yukiko iwai wataru takagi ikue otani kenichi ogata megumi hayashibara naoko matsui nobuyuki ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-than-toc-phan-2', 'Vòng Xoáy Thần Tốc (Phần 2)', 'Beyblade Burst (Season 2)', 'https://phimimg.com/upload/vod/20240811-1/4cf142909b23c3afa2cc9b771057d383.jpg', 'https://phimimg.com/upload/vod/20240811-1/4264c000418fa0d62f87a6f6b70e3f95.jpg', '<p>Beyblade Burst là bộ phim xoay quanh cuộc thi con quay nổi tiếng nhất thế giới: Vòng Xoay Thần Tốc Beyblade. Các cậu bé đến từ khắp nơi đã đặt cả trái tim và lòng nhiệt huyết của mình vào những trận đấu Beyblade dữ dội này. Nhân vật chính của bộ phim chính là Valt Aoi, cậu học sinh lớp 5 có niềm đam mê bất tận với Beyblade. Dù khởi đầu từ con số 0 tròn trĩnh, Valt Aoi đã nỗ lực luyện tập với khát khao chiến thắng mạnh mẽ và bản năng của một tay chơi quay thiên tài. Cậu luôn thi đấu hết mình để được tranh tài với những quay thủ tài năng trong giải đấu đỉnh cao, giải đấu quốc gia. Chặng đường chinh phục vòng xoay thần tốc của Valt cũng không hề cô đơn khi có sự đồng hành và giúp đỡ, hỗ trợ từ cậu bạn thân là Shu Kurenai.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 5, 2017, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"井上麻里奈","avatar":""},{"name":"榎木淳弥","avatar":""},{"name":"白石涼子","avatar":""},{"name":"田村睦心","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324403);
