INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-kinh-hoang', 'Trò Chơi Kinh Hoàng', 'Gerald''s Game', 'https://phimimg.com/upload/vod/20231114-1/63416f714a37f97a2bcee17b3d1b99f7.jpg', 'https://phimimg.com/upload/vod/20231114-1/eb146143be691454e8ea17d3517c3666.jpg', '<p>Gerald’s Game được chuyển thể từ tiểu thuyết tâm lí, hồi hộp của Stephen King. Đôi vợ chồng Jessie (Carla Gugino) và Gerald (Bruce Greenwood) hào hứng thực hiện chuyến du lịch lãng mạn tại một vùng nông thôn hẻo lánh. Cả hai đều hy vọng tuần lễ riêng tư với những &quot;ý tưởng điên rồ&quot; về chuyện giường chiếu sẽ giúp hâm nóng hiện thực tình cảm đang nguội lạnh sau 11 năm kết hôn.</p>', 'Full', 1, 'single', 'completed', 4, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Carla Gugino","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Henry Thomas","avatar":""},{"name":"Chiara Aurelia","avatar":""},{"name":"Kate Siegel","avatar":""},{"name":"Carel Struycken","avatar":""},{"name":"Adalyn Jones","avatar":""},{"name":"Bryce Harper","avatar":""},{"name":"Gwendolyn Mulamba","avatar":""},{"name":"Jamie Flanagan","avatar":""},{"name":"Dori Lumpkin","avatar":""},{"name":"Natalie Roers","avatar":""},{"name":"Nikia Reynolds","avatar":""},{"name":"Bill Riales","avatar":""},{"name":"Chuck Borden","avatar":""},{"name":"Mike McGill","avatar":""},{"name":"Charles Dube","avatar":""},{"name":"Ki","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324403);
