INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-loi-phan-4', 'Thành Phố Tội Lỗi (Phần 4)', 'Gotham (Season 4)', 'https://phimimg.com/upload/vod/20240729-1/71389f113633445bcc2a9623af842dc0.jpg', 'https://phimimg.com/upload/vod/20240729-1/2abba4030e6daf0e2610097a822b4092.jpg', '<p>Trước khi làm cảnh sát trưởng, tân cảnh sát James Gordon đã đấu tranh chống tội phạm và nạn tham nhũng ở Thành phố Gotham để trả thù vụ sát hại bố mẹ của Bruce Wayne.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben McKenzie","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"David Mazouz","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Robin Lord Taylor","avatar":""},{"name":"Erin Richards","avatar":""},{"name":"Camren Bicondova","avatar":""},{"name":"Cory Michael Smith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324404);
