INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-lang-phan-1', 'Đêm Lặng (Phần 1)', 'Dark (Season 1)', 'https://phimimg.com/upload/vod/20240609-1/42d90431b6705eb326bc8b9d09187af2.jpg', 'https://phimimg.com/upload/vod/20240609-1/8a37f220ce6311f15f18fdf4b1cb2259.jpg', '<p>Bộ phim Đêm Lặng lấy bối cảnh tại một thị trấn nhỏ giữa nước Đức, nơi những hiện tượng siêu nhiên kỳ lạ liên tục diễn ra, và sự biến mất của 2 đứa trẻ trong một gia đình 4 người đã khiến cư dân nơi đây đặt dấu hỏi giữa vụ án này với những sự việc kỳ bí kia.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Louis Hofmann","avatar":""},{"name":"Oliver Masucci","avatar":""},{"name":"Karoline Eichhorn","avatar":""},{"name":"Jördis Triebel","avatar":""},{"name":"Maja Schöne","avatar":""},{"name":"Stephan Kampwirth","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324404);
