INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-ma-am-2017', 'Ngôi Nhà Ma Ám', 'Ghost House', 'ngôi nhà ma ám ghost house scout taylor-compton james landry hébert mark boone junior michael s. new elana krausz katrina grey russell geoffrey banks rich lee gray kevin ragsdale wen-chu yang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pokemon-the-movie-to-chon-cau', 'Pokémon the Movie: Tớ Chọn Cậu!', 'Pokémon the Movie: I Choose You!', 'https://phimimg.com/upload/vod/20231026-1/c662de9796d48c8657bdd82a093d6aaf.jpg', 'https://phimimg.com/upload/vod/20231026-1/88a1150655b0b00424cef791489e786e.jpg', '<p>Có một mảnh đất huyền bí mà ở đó, loài người và các Pokémon sống hòa thuận, luôn kề vai sát cánh, chiến đấu cùng nhau trong các giải đấu. Và tại thị trấn Masara thuộc vùng Kanto, cậu bé 10 tuổi Satoshi với ước mơ trở thành một người huấn luyện Pokémon, chu du khắp mọi miền và giành được danh hiệu “Chuyên gia Pokémon”. Nhưng mọi chuyện không hề dễ dàng với Satoshi tại buổi chọn lựa Pokémon đầu tiên khi cậu đến muộn và chỉ còn sót lại Pikachu. Cuộc sống của Satoshi cũng từ đó bị đảo lộn hoàn toàn với những tình huống tréo ngoe, những rắc rối dở khóc dở cười do chính sự ngây ngô của Pikachu mang lại. Và cũng từ đó, những hành trình đầy thách thức và thú vị bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2017, 'Lồng Tiếng', 'HD', 'Nhật Bản', 0, '[{"name":"Rica Matsumoto","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Inuko Inuyama","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Masami Toyoshima","avatar":""},{"name":"Shoko Nakagawa","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Shiori Sato","avatar":""},{"name":"Arata Furuta","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Kyoko Hikami","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Yuji Ueda","avatar":""},{"name":"Rikako Aikawa","avatar":""},{"name":"Chika Fujimur","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324404);
