INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pokemon-the-movie-to-chon-cau', 'Pokémon the Movie: Tớ Chọn Cậu!', 'Pokémon the Movie: I Choose You!', 'pokémon the movie: tớ chọn cậu! pokémon the movie: i choose you! rica matsumoto ikue otani megumi hayashibara shin-ichiro miki inuko inuyama unsho ishizuka masami toyoshima shoko nakagawa kanata hongo shiori sato arata furuta ryota osaka kyoko hikami koichi yamadera yuji ueda rikako aikawa chika fujimur ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-quy-du', 'Nô Lệ Quỷ Dữ', 'Satan''s Slaves', 'https://phimimg.com/upload/vod/20231026-1/a69f2b3bdc53bb142eaca4030f03277b.jpg', 'https://phimimg.com/upload/vod/20231026-1/f0680810f1ee6cecaaf279d0ff4bf740.jpg', '<p>Bộ phim nói về những điều kỳ lạ xảy ra trong một gia đình ba thế hệ sống ở vùng ngoại ô Jakarta. Người mẹ Mawarni là một nghệ sĩ nổi tiếng và có những ca khúc ăn khách. Một ngày nọ, Mawarni bị mắc một cơn bệnh lạ kéo dài hơn ba năm rồi qua đời. Và từ đây tấn bi kịch bắt đầu với những người ở lại. Điều đầu tiên là mẹ cô được phát hiện chết một cách bí ẩn trong giếng nước, tiếp theo đó là sự xuất hiện của những hồn ma lởn vởn trong nhà trêu ghẹo hăm dọa những đứa con, và đỉnh điểm là cái chết của người họ hàng đã giúp đỡ gia đình cô nhiệt tình lúc tang gia. Cô con gái lớn Rini sau khi đọc được di thư của bà ngoại thì biết được một sự thật kinh khủng là mẹ cô - bà Mawarni không thể có con, và bốn chị em cô được sinh ra là do mẹ cô tham gia một giáo phái Satanic bí ẩn để có thai. Liệu Rini và ba đứa em có phải là những đứa con của quỷ và khi mẹ cô chết thì chị em cô cũng phải trở về với quỷ?</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Tara Basro","avatar":""},{"name":"Endy Arfian","avatar":""},{"name":"Nasar Anuz","avatar":""},{"name":"M. Adhiyat","avatar":""},{"name":"Ayu Laksmi","avatar":""},{"name":"Bront Palarae","avatar":""},{"name":"Elly D. Luthan","avatar":""},{"name":"Arswendi Nasution","avatar":""},{"name":"Dimas Aditya","avatar":""},{"name":"Egy Fedly","avatar":""},{"name":"Joko Anwar","avatar":""},{"name":"Fachry Albar","avatar":""},{"name":"Asmara Abigail","avatar":""},{"name":"Fransiskus Yuno","avatar":""},{"name":"Allan Sebastian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
