INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-lun-tinh-nghich-ngay-le', 'Quỷ Lùn Tinh Nghịch: Ngày Lễ', 'Trolls Holiday', 'https://phimimg.com/upload/vod/20231026-1/ce5a27bd2958dc4bd18e27fead2389b4.jpg', 'https://phimimg.com/upload/vod/20231026-1/0139a6a799907d1048bac9ab0e47c486.jpg', '<p>Khi Poppy luôn lạc quan, nữ hoàng của lũ quỷ lùn, biết rằng nhà Bergen không còn có ngày nghỉ nào trong lịch của họ nữa, cô đã nhờ đến sự giúp đỡ của Branch và những người còn lại trong nhóm để thực hiện một nhiệm vụ kỳ quặc thú vị là sửa chữa một điều gì đó mà nhà Bergens không làm được. nghĩ là bị hỏng.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2017, 'Vietsub', 'HD', '', 0, '[{"name":"Anna Kendrick","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"James Corden","avatar":""},{"name":"Ron Funches","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Caroline Hjelt","avatar":""},{"name":"Aino Jawo","avatar":""},{"name":"Walt Dohrn","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Curtis Stone","avatar":""},{"name":"Mike Mitchell","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324404);
