INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('three-billboards-truy-tim-cong-ly', 'Three Billboards: Truy Tìm Công Lý', 'Three Billboards Outside Ebbing, Missouri', 'https://phimimg.com/upload/vod/20231211-1/7f0d27847fcfb5059ad3cd5b015b7625.jpg', 'https://phimimg.com/upload/vod/20231211-1/a3a9783fb7031f3d510f3c475dbc013f.jpg', '<p>Một người mẹ đích thân thách thức chính quyền địa phương giải quyết vụ giết người của con gái mình khi họ không bắt được thủ phạm.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
