INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-xac-va-tam-hon', 'Thể Xác và Tâm Hồn', 'On Body and Soul', 'https://phimimg.com/upload/vod/20240616-1/cbd10745b080c06d93f189451e417951.jpg', 'https://phimimg.com/upload/vod/20240616-1/9484d77aa4bba65012e447b0f9f9e3c3.jpg', '<p>Chuyện phim mở đầu với khu rừng tuyết phủ trắng xóa thơ mộng, nơi một cặp hươu nhẩn nha kiếm ăn, thỉnh thoảng chúng tựa vào nhau tình tứ. Ngay sau đó, cảnh chuyển tới một lò mổ mà mặt đất vương vãi máu tươi, la liệt nội tạng và những tảng thịt động vật, đâu đó vang lên những lời bàn tán, xì xào của đám nhân viên về thái độ lạnh lùng, xa cách của Mária (Alexandra Borbély) - nữ chuyên gia giám định chất lượng mới.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Alexandra Borbély","avatar":""},{"name":"Morcsányi Géza","avatar":""},{"name":"Réka Tenki","avatar":""},{"name":"Ervin Nagy","avatar":""},{"name":"Zoltán Schneider","avatar":""},{"name":"Tamás Jordán","avatar":""},{"name":"Itala Békés","avatar":""},{"name":"Éva Bata","avatar":""},{"name":"Pál Mácsai","avatar":""},{"name":"Zsuzsa Járó","avatar":""},{"name":"Nóra Rainer-Micsinyei","avatar":""},{"name":"Júlia Nyakó","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324404);
