INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('logan-tran-chien-cuoi-cung', 'Logan: Trận Chiến Cuối Cùng', 'Logan', 'https://phimimg.com/upload/vod/20230915-1/9d1fc16841fe99bf25f6f37732179457.jpg', 'https://phimimg.com/upload/vod/20230915-1/a8ba6ba4fe347ca3d83e2bdbdee7249b.jpg', '<p><span style="font-family: ">Lấy bối cảnh năm 2029, giống loài dị nhân gần như bị tuyệt diệt. Wolverine lúc này phải đối mặt với sự lão hóa cả về thể chất lẫn khả năng phục hồi. Anh cùng với Giáo sư X, người lúc này đang mắc chứng bệnh Alzheimer, phải hợp sức để bảo vệ cô bé dị nhân Laura Kinney. Đối chọi với một đội quân ác nhân mạnh mẽ do Donald Pierce dẫn đầu và một tổ chức khổng lồ bí ẩn ở phía sau, liệu họ có bảo toàn được tính mạng và viết tiếp câu chuyện của mình.</span></p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Dafne Keen","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Elizabeth Rodriguez","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Stephen Dunlevy","avatar":""},{"name":"Eriq La Salle","avatar":""},{"name":"Elise Neal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324404);
