INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('logan-tran-chien-cuoi-cung', 'Logan: Trận Chiến Cuối Cùng', 'Logan', 'logan: trận chiến cuối cùng logan hugh jackman dafne keen patrick stewart elizabeth rodriguez boyd holbrook stephen merchant richard e. grant stephen dunlevy eriq la salle elise neal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-trom-may-rui', 'Vụ Trộm May Rủi', 'Logan Lucky', 'https://phimimg.com/upload/vod/20230914-1/622e3297b259fd1e09f7108bc1c3cb22.jpg', 'https://phimimg.com/upload/vod/20230914-1/1d585f3b0c0a2deb660117ae6fd485da.jpg', '<p><span style="font-family: ">Lâm vào tình cảnh “không còn gì để mất”, anh em nhà Logan với những suy nghĩ táo bạo và điên rồ đã quyết định thực hiện một vụ cướp thế kỉ tại giải đua xe huyền thoại Coca-Cola 600. Vốn chỉ là những tay gà mờ nên cả hai đã phải tìm mọi cách giúp Joa Bang, tên trộm cắp chuyên nghiệp trốn thoát khỏi nhà tù để giúp đỡ trong phi vụ này. Kể từ đây, vô số tình huống dở khóc dở cười đã xảy ra và càng dấn thân vào vụ việc, họ càng nhận ra rằng mọi thứ dường như đã tuột khỏi tầm kiểm soát</span></p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Seth MacFarlane","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Brian Gleeson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
