INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-nang-say-giac', 'Khi Nàng Say Giấc', 'While You Were Sleeping', 'https://phimimg.com/upload/vod/20240118-1/23608fef9ed5c67819c3587f9ba8345f.jpg', 'https://phimimg.com/upload/vod/20240118-1/d9c75aa092c082d0a31d0d77a5860992.jpg', '<p>Dàn diễn viên bắt mắt Lee Jong Suk, Bae Suzy, Jung Hae In khiến bạn không thể rời mắt! Trí tưởng tượng của biên kịch bay xa! Liệu mối tình giữa cô gái bất hạnh mơ thấy tương lai và công tố viên một mình chiến đấu ngăn chặn ác mộng trở thành hiện thực sẽ như thế nào đây?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jong Suk","avatar":""},{"name":"Suzy Bae","avatar":""},{"name":"Jung Hae In","avatar":""},{"name":"Lee Sang Yeob","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324404);
