INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-5', 'Trại Giam Kiểu Mỹ (Phần 5)', 'Orange Is The New Black (Season 5)', 'https://phimimg.com/upload/vod/20240607-1/0491401d65441b082499c34ac93b8dd6.jpg', 'https://phimimg.com/upload/vod/20240607-1/ff6e64944c317183f47859c329bf8ed3.jpg', '<p>Phim Trại Giam Kiểu Mỹ Phần 5 được chuyển thể từ cuốn hồi ký Orange Is the New Black: My Year in a Women Prison của Piper Kerman, kể về Piper Chapman, một phụ nữ đang có đầy đủ mọi thứ: nhà cửa, công việc và một người chồng sắp cưới. Bỗng một hôm, cô phải vào tù vì dính líu tới vụ buôn ma túy từ 10 năm trước, cùng người tình đồng tính trước đây. Piper sẽ phải làm sao để sống sót trong tù, cũng như giữ được tình yêu của mình?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Schilling","avatar":""},{"name":"Uzo Aduba","avatar":""},{"name":"Micheal Harney","avatar":""},{"name":"Kate Mulgrew","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324404);
