INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-toc-do-phan-2', 'Anne Tóc Đỏ (Phần 2)', 'Anne with an E (Season 2)', 'https://phimimg.com/upload/vod/20240607-1/2026aa9667f1bb4ab22b71240f42549c.jpg', 'https://phimimg.com/upload/vod/20240607-1/a79d2289f4c53e19553b2ae7309bd408.jpg', '<p>Cuộc phiêu lưu của một cô gái mồ côi trẻ sống vào cuối thế kỷ 19. Theo Anne khi cô học cách điều hướng cuộc sống mới của mình trên đảo Hoàng tử Edward, trong tác phẩm mới này về tiểu thuyết kinh điển của L.M Montgomery.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amybeth Mcnulty","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Lucas Jade Zumann","avatar":""},{"name":"Christian Martyn","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"R.h. Thomson","avatar":""},{"name":"Dalila Bela","avatar":""},{"name":"Corrine Koslo","avatar":""},{"name":"Aymeric Jett Montaz","avatar":""},{"name":"Kyla Matthews","avatar":""},{"name":"Helen Johns","avatar":""},{"name":"Lia Pappas-Kemps","avatar":""},{"name":"Ryan Kiera Armstrong","avatar":""},{"name":"Miranda Mckeon","avatar":""},{"name":"Jacob Ursomarzo","avatar":""},{"name":"Dal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
