INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anne-toc-do-phan-2', 'Anne Tóc Đỏ (Phần 2)', 'Anne with an E (Season 2)', 'anne tóc đỏ (phần 2) anne with an e (season 2) amybeth mcnulty geraldine james lucas jade zumann christian martyn jonathan holmes r.h. thomson dalila bela corrine koslo aymeric jett montaz kyla matthews helen johns lia pappas-kemps ryan kiera armstrong miranda mckeon jacob ursomarzo dal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-toc-do-phan-1', 'Anne Tóc Đỏ (Phần 1)', 'Anne with an E (Season 1)', 'https://phimimg.com/upload/vod/20240607-1/07f8cd644ccdf930df8d063ebf6fa996.jpg', 'https://phimimg.com/upload/vod/20240607-1/3ed52387afd834833d141cf7af70f1da.jpg', '<p>Bộ phim được chuyển thể dựa trên tiểu thuyết Anne of Green Gables (Anne Tóc Đỏ Dưới Mái Nhà Xanh) năm 1908 của Lucy Maud Montgomery. Câu chuyện về cô bé Anne Shirley mồ côi, tóc đỏ, mơ mộng và hay gây ra rắc rối đã rất quen thuộc với bạn đọc qua nhiều thập kỉ. Hẳn phải có lí do thì bộ truyện mới đứng vững trên tao đàn văn chương, trở thành tượng đài văn học nói chung và văn học dành cho thiếu nhi nói riêng. Nhưng hôm nay tôi mạn phép không so sánh truyện hay hơn phim hay ngược lại, vì tôi yêu cả tiểu thuyết gốc lẫn bộ phim chuyển thểĐã 32 năm kể từ lúc bản phim đầu tiên được phát hành vào năm 1985, năm 2017 đánh dấu sự trở lại của tác phẩm kinh điển này, ta cùng gặp lại Anne lắm mồm, gia đình Cuthbert, Gilbert,… trong một diện mạo khác mới mẻ và thu hút hơn.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amybeth Mcnulty","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Lucas Jade Zumann","avatar":""},{"name":"Christian Martyn","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"R.h. Thomson","avatar":""},{"name":"Dalila Bela","avatar":""},{"name":"Corrine Koslo","avatar":""},{"name":"Aymeric Jett Montaz","avatar":""},{"name":"Kyla Matthews","avatar":""},{"name":"Helen Johns","avatar":""},{"name":"Lia Pappas-Kemps","avatar":""},{"name":"Ryan Kiera Armstrong","avatar":""},{"name":"Miranda Mckeon","avatar":""},{"name":"Jacob Ursomarzo","avatar":""},{"name":"Dal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
