INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anne-toc-do-phan-1', 'Anne Tóc Đỏ (Phần 1)', 'Anne with an E (Season 1)', 'anne tóc đỏ (phần 1) anne with an e (season 1) amybeth mcnulty geraldine james lucas jade zumann christian martyn jonathan holmes r.h. thomson dalila bela corrine koslo aymeric jett montaz kyla matthews helen johns lia pappas-kemps ryan kiera armstrong miranda mckeon jacob ursomarzo dal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-linh-vo-danh', 'Người Lính Vô Danh', 'The Unknown Soldier', 'https://phimimg.com/upload/vod/20240607-1/c62039773564c1698ed75fa16f45e032.jpg', 'https://phimimg.com/upload/vod/20240607-1/abcb3186110ef1b25f609a0c7b5fc786.jpg', '<p>The Unknown Soldier dựa trên cuốn tiểu thuyết cổ điển bán chạy nhất năm 1954 cùng tên của Väinö Linna, một cuốn sách được coi là một phần của di sản quốc gia. Phim kể về cuộc chiến tranh năm 1941 tại Phần lan của những người lính dũng cảm bảo vệ Tổ quốc.</p><p>Phim lấy bối cảnh năm 1941, khi mà Phần Lan đang bị sự tấn công quyết liệt từ phía Liên Xô khiến đất nước trở nên hoang tàn, người dân rơi vào hoàn cảnh ngàn cân treo sợi tóc. Chính vì thế họ đã phải đồng minh với Đức Quốc Xã dù hai bên không có mấy thiện cảm tốt với nhau, chống lại sự chiếm đóng của Liên Xô tại vùng Biển Bắc. Quân đội bộ binh Phần Lan băng qua những khu rừng của Karelina để giành lại lãnh thổ bị Nga cướp mất nhưng dần dần họ nhận ra đây là cuộc chiến vô nghĩa, chỉ đem lại đau thương và chết chóc.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eero Aho","avatar":""},{"name":"Johannes Holopainen","avatar":""},{"name":"Jussi Vatanen","avatar":""},{"name":"Aku Hirviniemi","avatar":""},{"name":"Hannes Suominen","avatar":""},{"name":"Arttu Kapulainen","avatar":""},{"name":"Paula Vesala","avatar":""},{"name":"Samuli Vauramo","avatar":""},{"name":"Joonas Saartamo","avatar":""},{"name":"Juho Milonoff","avatar":""},{"name":"Andrei Alén","avatar":""},{"name":"Matti Ristinen","avatar":""},{"name":"Диана Пожарская","avatar":""},{"name":"Max Ovaska","avatar":""},{"name":"Vincent Willestrand","avatar":""},{"name":"Severi Saarinen","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
