INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-linh-vo-danh', 'Người Lính Vô Danh', 'The Unknown Soldier', 'người lính vô danh the unknown soldier eero aho johannes holopainen jussi vatanen aku hirviniemi hannes suominen arttu kapulainen paula vesala samuli vauramo joonas saartamo juho milonoff andrei alén matti ristinen диана пожарская max ovaska vincent willestrand severi saarinen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-thi-truong', 'Ngài Thị Trưởng', 'The Mayor', 'https://phimimg.com/upload/vod/20240604-1/f51b58e5d1d19df297c75d76bd860e42.jpg', 'https://phimimg.com/upload/vod/20240604-1/78698bbdb3c416e056fada8c624c7a2a.jpg', '<p>The Mayor khắc họa những mặt tối của giới chính trị gia Hàn Quốc. Để có thể thắng cử, họ sẵn sàng thêu dệt các câu chuyện với giới truyền thông, tô vẽ và đánh bóng bản thân mình dù tay họ đã nhúng chàm. Từ đó, phim cũng tiết lộ bí mật và khía cạnh bẩn thỉu của các cuộc bầu cử. Sau 2 nhiệm kỳ làm Thị trưởng, Byeon Jong Gu (Choi Min Sik đóng) đang cố gắng thắng cử nhiệm kỳ thứ ba để có thể giúp ông tranh cử Tổng thống. Để làm được điều này, ông phải tìm mọi cách che giấu những bí mật đen tối với nhóm dân chúng ủng hộ mình.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"최민식","avatar":""},{"name":"곽도원","avatar":""},{"name":"심은경","avatar":""},{"name":"문소리","avatar":""},{"name":"라미란","avatar":""},{"name":"류혜영","avatar":""},{"name":"Ki Hong Lee","avatar":""},{"name":"김홍파","avatar":""},{"name":"조한철","avatar":""},{"name":"남문철","avatar":""},{"name":"진선규","avatar":""},{"name":"박병은","avatar":""},{"name":"이윤희","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"서이숙","avatar":""},{"name":"이수경","avatar":""},{"name":"Kim Hak-seon","avatar":""},{"name":"박종환","avatar":""},{"name":"이경영","avatar":""},{"name":"마동석","avatar":""},{"name":"김종수","avatar":""},{"name":"김혜은","avatar":""},{"name":"김민재","avatar":""},{"name":"Min Ji-hwan","avatar":""},{"name":"박혁권","avatar":""},{"name":"김창옥","avatar":""},{"name":"Choiza","avatar":""},{"name":"Gaeko","avatar":""},{"name":"이주연","avatar":""},{"name":"Sung Yeol-seok","avatar":""},{"name":"Kim Yun-tae","avatar":""},{"name":"김주