INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngai-thi-truong', 'Ngài Thị Trưởng', 'The Mayor', 'ngài thị trưởng the mayor 최민식 곽도원 심은경 문소리 라미란 류혜영 ki hong lee 김홍파 조한철 남문철 진선규 박병은 이윤희 kang shin-chul 서이숙 이수경 kim hak-seon 박종환 이경영 마동석 김종수 김혜은 김민재 min ji-hwan 박혁권 김창옥 choiza gaeko 이주연 sung yeol-seok kim yun-tae 김주령 김수안 이서환 박보경 강기영 yoon jae-in ki ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-lua-3-khi-tu-thi-len-tieng', 'Hồ Sơ Lửa 3 - Khi Tử Thi Lên Tiếng', 'Hồ Sơ Lửa 3 - Khi Tử Thi Lên Tiếng', 'https://phimimg.com/upload/vod/20240518-1/8699344b80934a1f90ef760439db4de6.jpg', 'https://phimimg.com/upload/vod/20240518-1/b99467ec1a2c64c0685b617118780f67.jpg', '<p>Giữa lúc gia đình đang hạnh phúc, Quỳnh đột nhiên thành trẻ mô côi khi bố mẹ cô tự tử không rõ nguyên nhân. Lớn lên, Quỳnh đam mê với nghề và quyết tâm tìm ra sự thật đằng sau cái chết của bố mẹ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2017, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhung Kate","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Trương Minh Quốc Thái","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
