INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-phan-5', 'Vượt Ngục (Phần 5)', 'Prison Break (Season 5): Sequel', 'https://phimimg.com/upload/vod/20240409-1/f9fe7909136434a4031b5848e1f668d5.jpg', 'https://phimimg.com/upload/vod/20240409-1/d2f1e11648689897162e2cc874265c82.jpg', '<p>Lincoln và Sara tái ngộ sau khi họ khám phá ra rằng Michael vẫn còn sống trong một nhà tù ở Yemen. Và họ lên kế hoạch vượt ngục cực kì lớn với sự giúp đỡ của những người bạn cũ.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Mark Feuerstein","avatar":""},{"name":"Marina Benedict","avatar":""},{"name":"Christian Michael Cooper","avatar":""},{"name":"Steve Mouzakis","avatar":""},{"name":"Bobby Naderi","avatar":""},{"name":"Amin El Gamal","avatar":""},{"name":"Curtis Lum","avatar":""},{"name":"Akin Ga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
