INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-co-ay-phan-2', 'Anh, Em, Cô ấy (Phần 2)', 'You Me Her (Season 2)', 'https://phimimg.com/upload/vod/20240302-1/99731790961cd511cd9f981c1cd1a707.jpg', 'https://phimimg.com/upload/vod/20240302-1/b45aaa0b9ce6ac695bdd193324726416.jpg', '<p>Emma, Jack và Izzy ngày một quấn quýt trong mối tình khác thường, nhưng cùng với đó còn có những thách thức mới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Greg Poehler","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Priscilla Faia","avatar":""},{"name":"Melanie Papalia","avatar":""},{"name":"Jennifer Spence","avatar":""},{"name":"Ennis Esmer","avatar":""},{"name":"Patrick Gilmore","avatar":""},{"name":"Robert Moloney","avatar":""},{"name":"Dave Collette","avatar":""},{"name":"Adam Beauchesne","avatar":""},{"name":"Marc-Anthony Massiah","avatar":""},{"name":"Lee Majdoub","avatar":""},{"name":"Patrick Lubczyk","avatar":""},{"name":"Enid-Raye Adams","avatar":""},{"name":"Jess McLeod","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
