INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-em-co-ay-phan-2', 'Anh, Em, Cô ấy (Phần 2)', 'You Me Her (Season 2)', 'anh, em, cô ấy (phần 2) you me her (season 2) greg poehler rachel blanchard priscilla faia melanie papalia jennifer spence ennis esmer patrick gilmore robert moloney dave collette adam beauchesne marc-anthony massiah lee majdoub patrick lubczyk enid-raye adams jess mcleod ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-gundam-hoang-hon-axis', 'Chiến Binh Gundam: Hoàng Hôn Axis', 'Mobile Suit Gundam: Twilight Axis', 'https://phimimg.com/upload/vod/20240302-1/f1a9e14d9e260b37864d1ad3d0e21cec.jpg', 'https://phimimg.com/upload/vod/20240302-1/7114f2b2ccc93a0f2a6c0ac31bf08063.jpg', '<p>Năm U.C. 0096, Lực Lượng Liên Bang Trái Đất EFF (viết tắt của Earth Federation Forces) hay tin về một mối đe dọa bí ẩn đối với sự tồn tại của “psycho frame” một lần nữa sau sự kiện “Chiếc Hộp Của Laplace.” Nhằm tiếp cận nó, họ đã cử một đội điều tra tới tiểu hành tinh Axis trôi dạt bên ngoài quỹ đạo Trái Đất. Trong đội điều tra có sự tham gia của hai nhân viên dân sự: Arlette Almage và Danton Hyleg. Cả hai đều từng phục vụ trong chính quyền của Công Quốc Zeon và Neo Zeon, lần lượt trong vai trò kỹ sư và phi công thử nghiệm. Khi vừa bước chân tới Axis, cả đội đã bất ngờ bị tấn công bên trong một căn cứ bỏ hoang. Arlette và Dalton sau đó đã bị kéo vào một sự kiện mà họ sẽ không bao giờ có thể ngờ được.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masuda Toshiki","avatar":""},{"name":"Ono Daisuke","avatar":""},{"name":"Sakaguchi Shuuhei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324404);
