INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiet-huyet-truong-an', 'Nhiệt Huyết Trường An', 'Detective Samoyeds', 'https://phimimg.com/upload/vod/20240326-1/22d145249a855c500c5644ed0fe51051.jpg', 'https://phimimg.com/upload/vod/20240326-1/c88abef552311e52e58a048964aa9be2.jpg', '<p>Bộ phim Nhiệt Huyết Trường An với sự tham gia của Từ Hải Kiều, Cúc Tịnh Y, Trương Tân Uyển, Trình Tiểu Tấn, Lưu Quan Lân. Theo từng bước điều tra, mọi người dần dần phát hiện Hắc Già La vọng tưởng dùng thủ đoạn đê tiện để phá hoại Đại Đường thanh bình. Cuối cùng tà không thắng chính, tổ điều tra đập tan âm mưu của Hắc Già La. Những thiếu niên ấy không chỉ có trái tim nhiệt huyết hào hùng, còn có một tấm lòng giàu trách nhiệm bảo vệ quê hương đất nước…</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Joe Xu","avatar":""},{"name":"Ju Jingyi","avatar":""},{"name":"Herman Li He","avatar":""},{"name":"张辛苑","avatar":""},{"name":"Liu Guanlin","avatar":""},{"name":"Cheng Xiaomeng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
