INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('go-jetters-du-hanh-the-gioi-phan-2', 'Go Jetters: Du Hành Thế Giới (Phần 2)', 'Go Jetters (Season 2)', 'https://phimimg.com/upload/vod/20240229-1/c0dab5fe17f6d384b964bd1bc9d5d528.jpg', 'https://phimimg.com/upload/vod/20240229-1/8534219dd835729fd6690346f3038dfc.jpg', '<p>Xuli, Kyan, Lars và Foz trở lại với mùa mới cho những chuyến phiêu lưu thế giới, leo núi Matterhorn, tìm hiểu về cây baobap và khám phá rừng nhiệt đới.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"John Hasler","avatar":""},{"name":"Tommie Earl Jenkins","avatar":""},{"name":"Akie Kotabe","avatar":""},{"name":"Syrus Lowe","avatar":""},{"name":"Naomi McDonald","avatar":""},{"name":"Pilar Orti","avatar":""},{"name":"Marc Silk","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
