INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('120-nhip-tim-1-phut', '120 Nhịp Tim 1 Phút', 'BPM (Beats Per Minute)', 'https://phimimg.com/upload/vod/20240228-1/2bcd8f4d745e61649db1cf445fe7859e.jpg', 'https://phimimg.com/upload/vod/20240228-1/54eb40d6258feb467855657659b7f6bd.jpg', '<p>Bộ phim theo chân Nathan, thành viên mới của tổ ACT-UP, tổ chức chuyên giành quyền lợi cho những người bị nhiễm HIV-AIDS tại Pháp trước sự chậm chạp của chính phủ cũng như các công ty dược phẩm trong việc cung cấp thuốc. Khi tham gia các hoạt động đấu tranh, Nathan gặp gỡ Sean và nhanh chóng rơi vào tình yêu với anh chàng này...</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nahuel Pérez Biscayart","avatar":""},{"name":"Arnaud Valois","avatar":""},{"name":"Adèle Haenel","avatar":""},{"name":"Antoine Reinartz","avatar":""},{"name":"Félix Maritaud","avatar":""},{"name":"Ariel Borenstein","avatar":""},{"name":"Aloïse Sauvage","avatar":""},{"name":"Simon Bourgade","avatar":""},{"name":"Mehdi Touré","avatar":""},{"name":"Simon Guélat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
