INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-co-gai-toi-tu-khong-gian', 'Các Cô Gái Tới Từ Không Gian', 'Space Babes From Outer Space', 'https://phimimg.com/upload/vod/20240228-1/b9214b78259d9332258d362aeb810e4f.jpg', 'https://phimimg.com/upload/vod/20240228-1/2ac7b58662b1e3ed013a931a458f45c6.jpg', '<p>Ba cô gái không gian xinh đẹp bị mắc kẹt trên Trái đất khi tàu vũ trụ của họ hết năng lượng sau cuộc chạm trán nguy hiểm với kẻ thù truyền kiếp của họ, Scrotes. Sau khi phát hiện ra sự hưng phấn tình dục của con người có thể nạp lại năng lượng cho con tàu của mình, họ chấp nhận sự giúp đỡ của một cậu bé nông dân cô đơn để khai thác năng lượng tại một câu lạc bộ thoát y địa phương và trở về nhà - tất cả đều đồng thời tránh né lũ Scrotes khó chịu.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ellie Church","avatar":""},{"name":"Allison Maier","avatar":""},{"name":"Alyss Winkler","avatar":""},{"name":"Brian Papandrea","avatar":""},{"name":"Madison Claire","avatar":""},{"name":"Jason Hignite","avatar":""},{"name":"Brigid Macaulay","avatar":""},{"name":"Lucretia Lynn","avatar":""},{"name":"Maddie Collins","avatar":""},{"name":"Lexi Thompson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324404);
