INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('homejack-dao-nguoc', 'Homejack Đảo Ngược', 'Homejack Reverse', 'https://phimimg.com/upload/vod/20240228-1/df98f1277cbae8efa8648db1b1ba0572.jpg', 'https://phimimg.com/upload/vod/20240228-1/864ee01e8ae857607029dffc48378423.jpg', '<p>Các vai trò bị đảo ngược trong phần tiếp theo của bộ phim năm 2016, với cảnh hai người phụ nữ cưỡng hiếp một người đàn ông trong một cuộc đột nhập vào nhà.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sasa Handa","avatar":""},{"name":"Mayu Minami","avatar":""},{"name":"Kojiro Iida","avatar":""},{"name":"Hiromi Wakasa","avatar":""},{"name":"Junpei  Kawate","avatar":""},{"name":"Hirokio Andô","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
