INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ro-cua-kuroko-tran-dau-cuoi-cung', 'Bóng Rổ Của Kuroko - Trận Đấu Cuối Cùng', 'Kuroko No Basket Movie 4: Last Game', 'https://phimimg.com/upload/vod/20240228-1/8641c03354b8fa7a91a58ea30d5ccc10.jpg', 'https://phimimg.com/upload/vod/20240228-1/41779b915f52c2ae8fcfa3057d4303de.jpg', '<p>Đến từ Mỹ, Jabberwock—một đội bóng rổ đường phố có kỹ năng tương đương với NBA—đã đến Nhật Bản để thi đấu một trận giao hữu với Strky, một đội gồm các cựu sinh viên năm ba từng chơi ở Interhigh và Winter Cup. Tuy nhiên, do chênh lệch quá lớn về kỹ năng nên Jabberwock dễ dàng giành chiến thắng. Đội trưởng của họ, Nash Gold Jr., chế nhạo phong cách bóng rổ của tất cả các cầu thủ ở Nhật Bản bằng cách so sánh họ với những con khỉ. Tức giận trước lời nhận xét ác ý, Kagetora Aida thách họ tham gia một trận trả thù. Vì kiêu hãnh và tin rằng kết quả sẽ không khác, Nash chấp nhận thử thách. Kagetora sau đó tập hợp Vorpal Swords, một đội gồm Thế hệ kỳ tích, bao gồm Kuroko Tetsuya và Kagami Taiga, vì họ là những người duy nhất có cơ hội chống lại kẻ thù dường như bất khả chiến bại từ mọi góc độ.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324404);
