INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-dong-ho', 'Hành Tinh Đồng Hồ', 'Clockwork Planet', 'https://phimimg.com/upload/vod/20240229-1/ea1181f1a22a3c2aae252cf6263485f6.jpg', 'https://phimimg.com/upload/vod/20240229-1/cc6a13c7c95957570a1f2e36762e2684.jpg', '<p>Phim kể về Naoto Miura, một tên cuồng máy móc chính hiệu. Lúc nào cậu cũng mày mò máy móc và cơ khí. Không một ai biết rằng cậu có thể nghe và hiểu rõ máy móc như chính bản thân mình. Mọi người ở hành tình Clockwork đều coi Naoto Miura như là một kĩ sư máy móc. Hàng ngày, cậu ta để tâm trí vào các bánh răng và tay mày mò những động cơ cơ khí tinh vi. Nhưng không ai có thể hiểu tại sao cậu có thể nghe và cảm nhận được những bánh răng đang hoạt động, kể cả từ xa. Sau đó một ngày, một thiếu nữ đồng hồ rơi từ trên trời vào nhà cậu, báo trước sự kiện đó sẽ rung chuyển cả thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Kakuma","avatar":""},{"name":"Yoshino Nanjo","avatar":""},{"name":"Saori Oonishi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324404);
