INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-nhat-nhat-anh-chet-chac-phan-1', 'Long Nhật Nhất, Anh Chết Chắc (Phần 1)', 'Dragon Day, You''re Dead (Season 1)', 'https://phimimg.com/upload/vod/20240229-1/0bca5b2ed5f70cc92d15d1491e141aa4.jpg', 'https://phimimg.com/upload/vod/20240229-1/1139c8c0cc5147793ee8a943b6500b25.jpg', '<p>Bộ phim xoay quanh cô sinh viên ưu tú Trương Tịnh Mỹ, khi chuyển đến Học Viện Bản Thừa - ngôi trường thuộc hàng top, trong ngày đi học đầu tiên, đã không may mắn mà đụng phải đại ma đầu của trường là Long Nhật Nhất. Cặp đôi này từ nhiều lần va chạm đối đầu với nhau, dần dần nảy sinh tình cảm. Mối quan hệ giữa hai người tạo nên một phen sóng gió ở trường, đồng thời khiến cho mối quan hệ của gia đình Long Nhật Nhất trở nên thân thiết hơn.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngụy Triết Minh","avatar":""},{"name":"Khâu Hách Nam","avatar":""},{"name":"Hầu Bội Sam","avatar":""},{"name":"Thạch Tuyết Tịnh","avatar":""},{"name":"Tằng Lệ Dao","avatar":""},{"name":"Hoàng Thiên Mạc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324404);
