INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-gan-tra-dua', 'Già Gân Trả Đũa', 'Going In Style', 'https://phimimg.com/upload/vod/20240228-1/dd876d15f616b9fff38ac0c839f30903.jpg', 'https://phimimg.com/upload/vod/20240228-1/9eb1cf884f92e873a675f3c01ac9ffdd.jpg', '<p>Phim Già Gân Trả Đũa - Going in Style 2017: kể về 3 người đàn ông cao niên đang gặp nỗi lo về tài chính, về các hóa đơn điện, nước,... hằng ngày. Mọi chi tiêu đều có nguy cơ bị cắt giảm tối đa. Cuộc sống sẽ trở nên “bí bách” hơn . Và họ chợt nảy sinh ý định thật “điên rồ”: đi cướp nhà băng. Nhưng điều trớ trêu hơn là cả 3 người họ đều không biết cách sử dụng súng, hay cũng chưa từng làm những phi vụ nguy hiểm đến vậy. Thế là các tình huống dở khóc dở cười, những suy nghĩ và kế hoạch hài hước không giống bất kỳ một băng đảng tội phạm nào đã diễn ra trong suốt quá trình chuẩn bị cho màn cướp có 1-0-2 này.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Alan Arkin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
