INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc', 'Vượt Ngục', 'Jailbreak', 'https://phimimg.com/upload/vod/20240228-1/6977d0de97e0c7215c276d2d00e422f5.jpg', 'https://phimimg.com/upload/vod/20240228-1/8195c524319f33f56530eea66fc1c759.jpg', '<p>Phim kể về chuyến hộ tống tù nhân của Koh Kla qua nhà tù mới tưởng chừng đơn giản đã trở nên hỗn loạn. Lực lượng đặc biệt bị mắc kẹt trong nhà tù sẽ phải chiến đấu để sống sót và bảo vệ nhân chứng quan trọng.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Katsuni","avatar":""},{"name":"Jean-Paul Ly","avatar":""},{"name":"Laurent Plancel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
