INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-bi-dong-dau', 'Kẻ Bị Đóng Dấu', 'Branded', 'https://phimimg.com/upload/vod/20240228-1/08a52891540ce72ef7be783fdb693a89.jpg', 'https://phimimg.com/upload/vod/20240228-1/fb69c856200da1726b1103b7a497b5af.jpg', '<p>Ở miền tây hậu tận thế này, Alexander Dante đã sống 10 năm lưu vong vì giết Edwin, người anh trai yêu quý của mình. Rồi một ngày, anh ấy kinh ngạc khi nhận được một lá thư, có chủ đích từ Edwin. Bức thư nói rằng Edwin hiện đang sống ở một ngôi làng xa xôi được hiển thị trên bản đồ kèm theo. Lúc đầu, Alexander coi bức thư là một trò lừa bịp nhưng có điều gì đó về bức thư là sự thật. Anh ta đi xuyên qua một vùng đất khó khăn và đầy thù địch, nơi cuối cùng mở ra một ngôi làng yên tĩnh. Ở đó, anh ấy choáng váng khi đối mặt với điều không thể: anh trai anh ấy còn rất nhiều sống. Alexander vui mừng khôn xiết khi được gặp lại anh trai mình nhưng anh vẫn đau khổ khi biết mình đã giết anh. Bây giờ Alexander phải tìm ra sự thật - bất kể hậu quả là gì.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason London","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
