INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-vang-da-mat', 'Thành Phố Vàng Đã Mất', 'The Lost City Of Z', 'https://phimimg.com/upload/vod/20240227-1/c9fcee5e304f7412cca4c95fcfd1563b.jpg', 'https://phimimg.com/upload/vod/20240227-1/3839c52cd4c5072acce0905a6fed6871.jpg', '<p>Phim Thành Phố Vàng Đã Mất - The Lost City Of Z 2017: kể lại câu chuyện có thật về nhà thám hiểm người Anh, Percy Fawcett, người đã thám hiểm tới Amazon vào thế kỷ 20 và phát hiện ra một nền văn minh tiên tiến chưa từng được biết tới. Tuy bị các nhà khoa học lúc bấy giờ chế nhạo vì cho rằng người dân bản địa tại đây là những người hoang dã nhưng Percy Fawcett vẫn quyết tâm tìm ra sự thật.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Sienna Miller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
