INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('benh-vien-thay-ma', 'Bệnh Viện Thây Ma', 'Zombie Fighters', 'null', 'https://phimimg.com/upload/vod/20240227-1/55da6913139a88262bc3ea845e00567c.jpg', '<p>Đây là bộ phim kinh dị về thây ma đầu tiên của điện ảnh Thái Lan, kể về cuộc chiến chống lại hàng ngàn xác sống trong bệnh viện Saint Martha của 3 anh em Lambo, Audy, Coopper và những người bạn trẻ. Không hề chuẩn bị trước, họ vào đây nhằm mục đích đi tìm cha mẹ - được báo là đã chết trong bệnh viện và không được mang xác ra ngoài. Chỉ đến khi vào tận nơi 3 anh em mới biết cha mẹ họ và cả những người lính, bác sĩ, bệnh nhân khác đã bị biến thành Zombie, mất đi ý thức và đang điên cuồng đi tìm những người còn sống để tiêu diệt…</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324404);
