INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tro-lai-cua-billa-tra-thu-2', 'Sự Trở Lại Của Billa - Trả Thù 2', 'The Return Of Rebel 2', 'https://phimimg.com/upload/vod/20240227-1/4a1f916606a84a6aacaf8cc510edfa68.jpg', 'https://phimimg.com/upload/vod/20240227-1/cac655c34503b672f895886b8b57932b.jpg', '<p>Phim bắt đầu với một thế giới ngầm Don Billa, nằm trong danh sách tội phạm của Interpol, ẩn náu và hoạt động bên ngoài Malaysia. Krishnamoorthy đã dành vài năm qua để tìm kiếm Billa, bỏ lại cuộc sống ở Ấn Độ. Trong một cuộc rượt đuổi với cảnh sát, Billa bị thương nặng sau một vụ tai nạn và chết trước mặt ACP. ACP sau đó đã bí mật tổ chức chôn cất Billa. Sĩ quan Interpol Dharmendra được giao nhiệm vụ làm việc với ACP để bắt Billa đang lẩn trốn vì không ai biết về cái chết của Billa. ACP giữ bí mật về cái chết của Billa ngay cả với các sĩ quan đồng nghiệp của anh ta và truy tìm một kẻ trông giống tên là Swami Ranga, một tên trộm nhỏ có trụ sở tại Visakhapatnam. Anh ta yêu cầu Ranga thâm nhập vào băng nhóm của Billa bằng cách giả làm Billa. Đổi lại, anh ấy sẽ đảm bảo rằng những đứa trẻ mà Ranga nhận nuôi, Lakshmi và Sreenu, được học hành tử tế ở Hyderabad.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Anushka Shetty","avatar":""},{"name":"Namitha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
