INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-quoc-dien-nghia-nhi', 'Tam Quốc Diễn Nghĩa Nhí', 'Star Of Tomorrow: Three Kingdoms', 'https://phimimg.com/upload/vod/20240227-1/43ce9c2d741846cdd79f8a08e736fb06.jpg', 'https://phimimg.com/upload/vod/20240227-1/82489f4d2f4afb87dde81c1714d26f14.jpg', '<p>Phim Tam Quốc Diễn Nghĩa Nhí - Star Of Tomorrow: Three Kingdoms 2017: Đổng Trác lộng quyền, tàn sát trung thần khiến cho lòng người căm phẫn nhưng không ai giết được bởi vì hắn có Lữ Bố. Điêu Thuyền ôm hận giết cha quyết bày mưu tính kế cũng Tào Tháo để giết Đổng Tặc. Câu chuyện kinh điển được biết đến qua bao thế hệ nay được tái hiện lại bằng diễn xuất của các diễn viên nhí.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Đào Dịch Hy","avatar":""},{"name":"Lý Tuấn Hào","avatar":""},{"name":"Cát Dịch Đức","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
