INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ho-ngui-tuong-vi-thay-troi-hanh-dao', 'Mãnh Hổ Ngửi Tường Vi: Thay Trời Hành Đạo', 'Tiger And Flower: Revenfe For Justice', 'null', 'https://phimimg.com/upload/vod/20240227-1/3f15ff7e3bc94ec2584d8be3eeb71506.jpg', '<p>Mãnh Hổ Ngửi Tường Vi - Thay Trời Hành Đạo - Tiger and flower: Revenfe for Justice kể về câu chuyện của Giám đốc Diệp chủ ngân hàng địa phương bị đầu độc chết vì không đồng ý với việc làm xấu xa của Hồ Lữ Chưởng. Con gái duy nhất của ông Diệp tiểu thư được Đàm Hổ cứu giúp khỏi nhà Hồ Lữ Chưởng. Hai người đi tìm Bá Thiên bái sư học đạo, trải qua sự rèn luyện khổ công vất vả, hai người cũng đượcc xuất sư vì đã thật sự tin tưởng đối phương , hài hòa làm một. Hai người trở về hợp tác lấy lại tất cả tiền bạc mà Hồ Lữ Chưởng đã cướp của người dân và trả lại cho họ.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cheng Cheng","avatar":""},{"name":"Li Yan","avatar":""},{"name":"Wang Jun Peng","avatar":""},{"name":"Yu Xiaowan","avatar":""},{"name":"Zhao Shili","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
