INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-toi-thuong', 'Hoàng Đế Tối Thượng', 'The King', 'https://phimimg.com/upload/vod/20240313-1/5365c8033acd34684eca7c104872decd.jpg', 'https://phimimg.com/upload/vod/20240313-1/78b2a6fa1b02cee0703732a929a8cee2.jpg', '<p>Sinh ra trong đói khổ, điều duy nhất mà Park Tae Soo học được từ người cha trộm cắp, nát rượu của hắn là giỏi đập nhau. Chỉ đến khi nhận ra quyền lực mới là thứ quan trọng nhất trên đời, rằng tụi mọt sách mới là bá chủ thực sự của thế giới, rằng một tay công tố viên choai choai cũng có thể đạp vào mặt lũ côn đồ biết võ nhưng không thể phản kháng nổi, tên ất ơ Park Tae Soo mới lao đầu vào học, nhận lấy tấm bằng của Đại học Seoul và trở thành một công tố viên cân 150 vụ án mỗi tuần. Chấp nhận cả đời làm một trong 99% số công tố viên hộc mặt với đồng lương bèo bọt, hay liều lĩnh xông pha vào 1% đầy bí ẩn còn lại của Đại Hàn Dân Quốc? Park Tae Soo đã được trao một cơ hội dơ bẩn để trở thành một phần trong thứ quyền lực thực sự chỉ chiếm 1% ít ỏi đó. Thế nhưng, những góc khuất tối tăm của cái thế giới này liệu có che giấu được mãi? Thời điểm Park Tae Soo được nếm trải cảm giác như một ông hoàng, cúi mình dưới tay cục trưởng Han Kang Sik (Jung Woo Sung), có lẽ đấy cũng là lúc hắn linh cảm được rằng mình sắp xuống địa ngục thật rồi, rằng mẹ không đùa con đâu!</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jo In-sung","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Bae Sung-woo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
