INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-man-duong', 'Hạnh Phúc Mãn Đường', 'The Love Of Happiness', 'https://phimimg.com/upload/vod/20240215-1/31178b39315b7bc158eda29a6bbcc7f5.jpg', 'https://phimimg.com/upload/vod/20240215-1/aa73285c40194a24fa83ea9459f53443.jpg', '<p>Lộ Tiểu Nam là một cô gái độc lập do bị ảnh hưởng của cuộc sống tân tiến, đối với cô quan điểm hôn nhân không phải chỉ là hai người yêu nhau cùng thân thể hòa hợp là được, mà nó còn có rất nhiều vấn đề cần phải cùng nhau đối mặt và giải quyết. Cũng vì thế, đối với cô hôn nhân tương đối nghiêm khắc, cho đến khi Tô Khải Văn xuất hiện. Trải qua rất nhiều lần đấu tranh tư tưởng, Tiểu Nam quyết định cùng Khải Văn kết hôn những tưởng cuộc sống hoàn mỹ mà cô luôn mong muốn đã xuất hiện. Nhưng đột nhiên vào một ngày, Khải Văn nói với cô muốn tìm kiếm gia đình bị thất lạc. Tiểu Nam người theo chủ nghĩa hoàn mỹ sẽ phải làm sao để đối mặt với vấn đề này đây? Liệu Khải Văn có tìm thấy được gia đình không? Tìm thấy rồi sẽ như thế nào đây?</p>', 'Hoàn Tất (72/72)', 72, 'series', 'completed', 14, 2017, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Vỹ Đình","avatar":""},{"name":"Đường Nghệ Hân","avatar":""},{"name":"Ngụy Đại Huân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324404);
