INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-khung-bo-liep-anh-phan-1', 'Đội Chống Khủng Bố Liệp Ảnh (Phần 1)', 'Anti-Terrorism Special Forces 1', 'https://phimimg.com/upload/vod/20240215-1/0c4c3d8eb2003d5527f05e93763942f5.jpg', 'https://phimimg.com/upload/vod/20240215-1/ff6ddf7ceb0b1ef27d1bc9a3f2044a70.jpg', '<p>Đội Chống Khủng Bố Liệp Ảnh (Phần 1) - Anti-Terrorism Special Forces 1 xoay quanh cuộc chiến chống lại tội phạm và cái ác của các chiến sĩ thuộc tổ chức Liệp Ảnh. Để bảo vệ an ninh quốc gia cũng như cuộc sống bình yên của người dân vô tội, các chiến sĩ chiến đấu, vạch trần nhiều âm mưu khủng bố nguy hiểm, thậm chí phải đánh đổi tính mạng của mình cho công lý.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2017, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Ban","avatar":""},{"name":"Huỳnh Duy Đức","avatar":""},{"name":"Hà Thạnh Minh","avatar":""},{"name":"Thạch Triệu Kỳ","avatar":""},{"name":"Tôn Nghệ","avatar":""},{"name":"Tôn Nghệ Minh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
