INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-dau-2', 'Mất Dấu 2', 'Line Walker: The Prelude', 'https://phimimg.com/upload/vod/20240215-1/043ddf2f0bc568b3c2abc9e8051be1ce.jpg', 'https://phimimg.com/upload/vod/20240215-1/3f96797000c0433d91c669950262210f.jpg', '<p>Năm 2010, Trác Khải, giám đốc cấp cao phòng tình báo hình sự bí mật tới Băng-Cốc làm nhiệm vụ; các thuộc cấp anh ta bị hy sinh toàn bộ. Cũng lúc đó, bạn tốt của Khải là Lê Thụy Quyền cũng bị giết hại một cách ly kỳ. Quyền để lại một nữ cảnh sát nằm vùng chưa chính thức là Trịnh Thục Mai cho Khải. Khải muốn tìm ra chân tướng cái chết của Quyền, phải nhanh chóng tìm ra tung tích những cảnh sát nằm vùng dưới chướng của Quyền bị mất tích. Mặt khác, xã đoàn lớn nhất Hồng Kong xảy ra chuyện lục đục nội bộ, đầu rồng xã đoàn Ngụy Đức Tín tiến hành hành động khử trừ đối thủ. Bọn cảnh sát biến chất do Tín kiểm soát không dừng phát triển thế lực, làm cho Khải và Mai không thể không bắt tay với Hoan Hỷ cùng đối phó. Trác Khải thề nhổ tận gốc thế lực ác, anh ta liều chết chiến đấu tới cùng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2017, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Tuyên Huyên","avatar":""},{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Trần Hào","avatar":""},{"name":"Viên Vỹ Hào","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
