INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wakfu-phan-3', 'Wakfu (Phần 3)', 'Wakfu (Season 3)', 'https://phimimg.com/upload/vod/20240215-1/33be0832283005ed818c81d841a790f2.jpg', 'https://phimimg.com/upload/vod/20240215-1/39f6fd80fd4828fff3367352c20a2d1f.jpg', '<p>Khi một hội bí mật xuất hiện và truy đuổi lũ trẻ nhà Percedal, Yugo và bạn bè bắt tay vào một nhiệm vụ giải cứu đầy khó khăn.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Fanny Bloc","avatar":""},{"name":"Jules De Jongh","avatar":""},{"name":"Patrick Béthune","avatar":""},{"name":"Hugo Chandor","avatar":""},{"name":"Thierry Mercier","avatar":""},{"name":"Matthew Géczy","avatar":""},{"name":"Benjamin Pascal","avatar":""},{"name":"Arthur Bostrom","avatar":""},{"name":"Geneviève Doang","avatar":""},{"name":"Adeline Chetail","avatar":""},{"name":"Jessica Bell","avatar":""},{"name":"Thomas Guitard","avatar":""},{"name":"Ross Grant","avatar":""},{"name":"Gérard Surugue","avatar":""},{"name":"Kier Stewart","avatar":""},{"name":"Benoît Allemane","avatar":""},{"name":"Bruno Ma","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
