INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('wakfu-phan-3', 'Wakfu (Phần 3)', 'Wakfu (Season 3)', 'wakfu (phần 3) wakfu (season 3) fanny bloc jules de jongh patrick béthune hugo chandor thierry mercier matthew géczy benjamin pascal arthur bostrom geneviève doang adeline chetail jessica bell thomas guitard ross grant gérard surugue kier stewart benoît allemane bruno ma ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-cua-toi-2', 'Học Viện Anh Hùng Của Tôi 2', 'Boku No Hero Academia 2nd Season', 'https://phimimg.com/upload/vod/20240215-1/6f0870d39b7579e01b4630710fc06607.jpg', 'https://phimimg.com/upload/vod/20240215-1/8e8f57877a10f410abf00bb38690849b.jpg', '<p>Phim Học Viện Anh Hùng Của Tôi Season 2: Mùa thứ hai của phim Boku no Hero Academia, kể về một vị anh hùng muốn vượt lên đứng đầu trong tất cả! Izuku có một ước mở trở thành anh hùng từ khi còn nhỏ - là một mục tiêu cao nhất mà ai cũng muốn đạt được - nhưng đó là lại là một thách thức đối với một cậu bé không hề có tý năng lực siêu nhiên nào. Đúng thế, ở một cái thế giới mà hơn 80% dân số đều có một loại siêu năng lực một cách lạ thường, Izuku không may mắn khi sinh lại hoàn toàn bình thường. Nhưng việc đó cũng không thể ngăn cản việc cậu ghi danh vào học viện anh hùng được xem là uy tín hàng đầu thế giới. Hiện giờ, điều duy nhất ngăn cản cậu vào học viện chính là kỳ thi tuyển sinh đầy đáng sợ đó. Bài hướng dẫn nho nhỏ từ người anh hùng mạnh nhất thế giới sẽ giúp cậu giải quyết tất cả.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Daiki Yamashita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
