INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bo-xa-la', 'Người Bố Xa Lạ', 'My Father Is Strange', 'https://phimimg.com/upload/vod/20240205-1/90ec5346c5a355d0266aaf98d7409fec.jpg', 'https://phimimg.com/upload/vod/20240205-1/d164ab0865c13789022178cd09a5e028.jpg', '<p>Bốn anh chị em cãi vã và an ủi lẫn nhau đi qua nhiều bất ngờ trong cuộc sống – bao gồm sự kiện có diễn viên một ngày nọ tuyên bố mình là con trai của bố họ.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 14, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Young Cheol","avatar":""},{"name":"Kim Hae Sook","avatar":""},{"name":"Lee Joon","avatar":""},{"name":"Lee Yu Ri","avatar":""},{"name":"Ryu Su Young","avatar":""},{"name":"Jung So Min","avatar":""},{"name":"Min Jin Woong","avatar":""},{"name":"Lee Mi Do","avatar":""},{"name":"Ryu Hwa Young","avatar":""},{"name":"Ahn Hyo Seop","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324404);
