INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-danh-grace', 'Bí Danh Grace', 'Alias Grace', 'https://phimimg.com/upload/vod/20240205-1/508f01c5dff62fb58f6809cd95bd897b.jpg', 'https://phimimg.com/upload/vod/20240205-1/e952f03714adb2acecef1931ab651b5e.jpg', '<p>Phim Bí Danh Grace - Alias Grace 2017: Dựa trên vụ giết người có thật năm 1843 ở Canada với nạn nhân là Thomas Kinnear và người trông nhà của ông là Nancy Montgomery. Hai người hầu của Thomas đã bị kết tội: một hầu gái 16 tuổi người Ireland tên Grace Marks và James McDermott, người trông nom chuồng ngựa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Gadon","avatar":""},{"name":"Edward Holcroft","avatar":""},{"name":"Rebecca Liddiard","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324404);
