INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-danh-grace', 'Bí Danh Grace', 'Alias Grace', 'bí danh grace alias grace sarah gadon edward holcroft rebecca liddiard ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-hai-thuong-muc-van-ky', 'Cửu Châu Hải Thượng Mục Vân Ký', 'Tribes and Empires: Storm of Prophecy', 'https://phimimg.com/upload/vod/20240307-1/7ebbb1ee172e64aae8750fc94778a83b.jpg', 'https://phimimg.com/upload/vod/20240307-1/01cafb334e7cfdd898252880fffe339d.jpg', '<p>Muyun Sheng, được sinh ra từ một người mẹ linh hồn, là con trai thứ sáu không được sủng ái của đương kim Hoàng đế nhà Minh xứ Duẩn. Tình cờ phát hiện ra một bức tranh cổ, anh bị quyến rũ bởi linh hồn bị nhốt bên trong (Panxi), và họ cùng nhau hứa sẽ tìm kiếm những nơi đẹp nhất trên Trái đất. Muru Hanjiang, bạn của Muyun Sheng, là con trai của tướng quân Muru Shuo, người nổi tiếng với việc chinh phục Bát bộ tộc của tỉnh Hán.</p><p>Nhiều năm sau, hậu duệ của Bát tộc Shuofeng Heye gieo rắc mối bất hòa giữa gia đình Muyun và Muru. Chỉ khi tình bạn và lòng trung thành giữa hai gia tộc này được xây dựng lại thì nhà Đoàn mới có thể an toàn trước sự xâm lược của Bát Tộc. Bộ phim này kể về lòng trung thành, tình bạn, thù hận và sự lãng mạn giữa những người con cháu trong những năm hoàng hôn của triều đại Duẩn.</p><p><br/></p>', 'Hoàn Tất (75/75)', 75, 'series', 'completed', 10, 2017, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Xuan","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Zhou Yiwei","avatar":""},{"name":"Xu Lu","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Karlina Zhang","avatar":""},{"name":"Janine Chang","avatar":""},{"name":"Lu Fangsheng","avatar":""},{"name":"Peng Guanying","avatar":""},{"name":"Wang Qian-Yuan","avatar":""},{"name":"Kan Qingzi","avatar":""},{"name":"Zhang Xiaochen","avatar":""},{"name":"Li Xinai","avatar":""},{"name":"Wang Si Si","avatar":""},{"name":"Jiang Qin Qin","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Gao Ye","avatar":""},{"name":"Qu Gaowei","avatar":""},{"name":"Chen Bing Qiang","avatar":""},{"name":"Sun Jian","avatar":""},{"name":"Wang Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324404);
