INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-thuong-than-tham', 'Hoàng Thượng Thần Thám', 'The King''s Case Note', 'https://phimimg.com/upload/vod/20240219-1/cf011f4e27cc31b93f33b12b8a217031.jpg', 'https://phimimg.com/upload/vod/20240219-1/90ee411077c82e0181655454507b66ce.jpg', '<p>Trong triều đại Joseon, quyền lực bị đe dọa bền bỉ bởi các cuộc chiến chính trị và xã hội, thường dẫn đến tội ác và che chở. Vua Yejong, thực hiện một điểm để thu thập bằng chứng liên quan đến các hoạt động tội phạm này và giải quyết các trường hợp, mang lại những vụ chịu trách nhiệm cho công lý. Là Vua làm điều này, một chàng trai trẻ tuyệt vời, SEO, được bổ nhiệm làm thủ môn Chronicle của King. Nhà vua ngay lập tức nhận ra rằng SEO là sự trợ giúp hoàn hảo để giải quyết tội phạm. Chàng trai trẻ gần như có một bộ nhớ nhiếp ảnh và là chớp nhanh khi nhớ lại các chi tiết. Và sự xuất hiện của anh ấy về phía King không thể đến vào thời điểm tốt hơn. Ở Hanyang, có một trường hợp đặc biệt kỳ lạ mà Vua được rút ra. Một phần quan tâm của anh đến từ một tin đồn rằng sự kiện bắt nguồn từ một nỗ lực để Dethrone Yejong. Cảm nhận sự phản đối sản xuất bia, Yejong tân binh SEO để giúp anh ta khám phá sự thật đằng sau sự bất thường, và có khả năng phản đối sự cố.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324404);
