INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-cuoi-hoi', 'Dịch Vụ Cưới Hỏi', 'The Wedding Stalker', 'https://phimimg.com/upload/vod/20231109-1/1d8b6d92c2aa3cfe68fb962249e98c26.jpg', 'https://phimimg.com/upload/vod/20231109-1/5e82c4eb581b252cbc1b6febff422825.jpg', '<p>Kể từ khi cô bắt đầu làm thợ may cho dì Daisy, Jenna đã chứng kiến hàng chục cô dâu kết hôn hạnh phúc trong bộ váy cưới lộng lẫy. Jenna khao khát có một đám cưới trắng của riêng mình và tìm một người đàn ông đẹp trai, người sẽ đưa cô ra khỏi sự ngược đãi của người Dì. Khi Jenna gặp cô dâu sắp cưới Marci và bạn trai Glenn, cô nhận ra Glenn là người đàn ông trong mơ của cô và giờ cô sẽ không dừng lại ở đó để có tất cả cho mình và biến giấc mơ thành hiện thực ... ngay cả khi cô phải Giết cô dâu!</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Heather Morris","avatar":""},{"name":"Fiona Vroom","avatar":""},{"name":"Jason Cermak","avatar":""},{"name":"Robert Salvador","avatar":""},{"name":"Joan Van Ark","avatar":""},{"name":"Paula Giroday","avatar":""},{"name":"Doug Abrahams","avatar":""},{"name":"Elizabeth McLaughlin","avatar":""},{"name":"Paul Duchart","avatar":""},{"name":"Alexis Quednau","avatar":""},{"name":"Sandra Timuss","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324404);
