INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-my-nhan', 'Tư Mỹ Nhân', 'Song Of Phoenix', 'https://phimimg.com/upload/vod/20240126-1/67b9316abdf436c829d952e8025423ee.jpg', 'https://phimimg.com/upload/vod/20240126-1/c21a8df34f11bdf018e3c431546b44ba.jpg', '<p>Phim Tư Mỹ Nhân 2017: lấy cảm hứng từ bài Tư Mỹ Nhân của Khuất Nguyên, phim kể về Khuất Nguyên và Sở Hoài vương là những nhân vật có thật trong lịch sử TQ. Phim lấy lịch sử làm gốc, văn học làm hồn, lãng mạn làm áo, tình hoài làm lý, thanh xuân làm lòng, truyền kỳ làm cốt, tránh xa huyễn hoặc không tưởng, cự tuyệt bịa chuyện não tàn. Đường đi chầm chậm, cùng bạn đồng hành.</p>', 'Hoàn Tất (78/78)', 78, 'series', 'completed', 14, 2017, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Hinh Dư","avatar":""},{"name":"Mã Khả","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
