INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-ki-quai-trong-nha', 'Người Đàn Ông Kì Quái Trong Nhà', 'The Strange Man In My Home', 'https://phimimg.com/upload/vod/20240126-1/2db4c521156b4cbf451913bea53ddbe0.jpg', 'https://phimimg.com/upload/vod/20240126-1/3f25aaa21399900f1274ba94c3fb4d83.jpg', '<p>Trạch nữ Phí Phi mắc chứng sợ đàn ông đã bắt đầu sống chung với chàng trai yêu nghiệt hay ảo tưởng, Hải Dương. Tính cách đối lập khiến hai người không ngừng mâu thuẫn, cuộc sống trở nên hỗn độn. Vào lúc gian nan nhất, hai người những tưởng sẽ cãi vã không ngừng lại trở thành chỗ dựa vững vàng nhất của nhau. Phí Phi cũng dần dần phát hiện điểm kì lạ của Hải Dương…</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fan Shi Qi","avatar":""},{"name":"Huang Can Can","avatar":""},{"name":"Xu Feng","avatar":""},{"name":"Mu Le En","avatar":""},{"name":"Liu Shuang","avatar":""},{"name":"Li Guo","avatar":""},{"name":"Liu Yu Hang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324404);
