INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-bi-tuoc-doat', 'Giấc Mơ Bị Tước Đoạt', 'Dreams I Never Had', 'https://phimimg.com/upload/vod/20240207-1/90106e26a2a958747f155edb3cd32835.jpg', 'https://phimimg.com/upload/vod/20240207-1/8cf6676a26456e3d1e1e167720684abe.jpg', '<p>Giấc Mơ Bị Tước Đoạt - Dreams I Never Had xoay quanh một cô gái trẻ sinh ra trong gia đình giàu có nhưng luôn bị cấm đoán, giam cầm. Cô kết bạn với người làm vườn - một kẻ có xuất thân bất hợp pháp đến từ Mexico. Hai con người với hai hoàn cảnh trái ngược nhưng tình bạn giúp họ cùng vượt qua sự tuyệt vọng và nỗi cô đơn.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iyad Hajjaj","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Robin Givens","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
