INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-thoat', 'Trốn Thoát', 'Get Out', 'https://phimimg.com/upload/vod/20240205-1/79ec2a203aa13c56cf29b38324ceeccd.jpg', 'https://phimimg.com/upload/vod/20240205-1/383a03a29ae363d1332ef6b0e157cc3d.jpg', '<p>Tâm điểm của Get Out là chàng thanh niên da đen Chris Washington (Daniel Kaluuya). Anh có cô bạn gái da trắng xinh đẹp tên Rose Armitage (Allison Williams). Sau vài tháng hẹn hò, Rose quyết định đưa bạn trai về nhà ra mắt. Chris đắn đo khi người bạn thân Rod (Lilrel Howery) can ngăn nhưng cuối cùng vẫn quyết định lên đường tới vùng ngoại ô để gặp nhà Armitage. Khác biệt về màu da làm Chris ngại ngần trước khi gặp mặt bố mẹ bạn gái. Trái với những e ngại ban đầu, anh thấy mình được chào đón với thái độ thân thiện không chỉ từ bố mẹ mà cả những người thân, bạn bè da trắng của Rose. Nhưng trong thâm tâm, chàng trai da màu vẫn cảm nhận được đằng sau những gương mặt vui vẻ này ẩn giấu một bí mật nào đó.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Kaluuya","avatar":""},{"name":"Allison Williams","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Caleb Landry Jones","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
