INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-thu-ma-tuong-quan', 'Thần Thú Ma Tương Quán', 'Insect Mahjong Museum', 'https://phimimg.com/upload/vod/20240118-1/b801bfcd3144bbd4038345f698df9112.jpg', 'https://phimimg.com/upload/vod/20240118-1/dee35b33de74343543d57f28d7140d34.jpg', '<p>Thần thú Bạch Hàn bị trộm linh cốt, phải xuống nhân gian tìm lại. Không ngờ linh cốt được người phàm Lục Trường Sinh làm thành mạt chược. Cha mẹ Trường Sinh lúc du ngoạn trên đảo bị hung thú Tiểu Đào nuốt chửng. Tiểu Đào phải nhờ Bạch Hàn lấy hòn đảo ra. Cơ duyên khiến 3 người gặp nhau và những chuyện thú vị bắt đầu từ đây</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bạch Liễu Tịch","avatar":""},{"name":"Đào Soái","avatar":""},{"name":"Lý Thần Hạo","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324404);
