INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cassidy-toc-do', 'Cassidy Tóc Đỏ', 'Cassidy Red', 'null', 'https://phimimg.com/upload/vod/20240205-1/f08e6354a27f6b316e2384b0cd18bf19.jpg', '<p>Bộ phim Cassidy Tóc Đỏ - Cassidy Red xoay quanh câu chuyện một người phụ nữ tên là Cassidy trở về quê hương của mình để trả thù khi người yêu của cô bị giết bởi vị hôn phu cũ của cô. Bị giằng xé giữa tình yêu, sự căm ghét, lòng trung thành và sự báo thù, hành động của cô ngày càng vượt khỏi sự kiểm soát của bản thân mình.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Abby Eiland","avatar":""},{"name":"David Thomas Jenkins","avatar":""},{"name":"Jason Grasl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
