INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('high-heel-homicide', 'High Heel Homicide', 'High Heel Homicide', 'https://phimimg.com/upload/vod/20240205-1/901e12fbf16df6b23bff502e3c0c5b68.jpg', 'https://phimimg.com/upload/vod/20240205-1/73a271caa3ab83bd6aedc2dc03674b55.jpg', '<p>Khi hàng loạt vụ giết người tàn bạo hoành hành khắp thành phố, hai thám tử chìm chạy đua để giải quyết bí ẩn và vạch mặt kẻ giết người. Manh mối duy nhất của họ: mỗi nạn nhân là một cựu cảnh sát và mỗi người đều có một chữ cái màu đỏ như máu được vẽ trên cơ thể. Bao nhiêu người sẽ phải chết trước khi kẻ sát nhân nói ra thông điệp của chúng bằng máu?</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carter Cruise","avatar":""},{"name":"Mia Li","avatar":""},{"name":"Blair Williams","avatar":""},{"name":"Brent Harvey","avatar":""},{"name":"August Ames","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
