INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('high-heel-homicide', 'High Heel Homicide', 'High Heel Homicide', 'high heel homicide high heel homicide carter cruise mia li blair williams brent harvey august ames ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-uoc-chet', 'Giao Ước Chết', 'The Promise', 'https://phimimg.com/upload/vod/20240205-1/687016b7cc2a92cbfa66797974ba589d.jpg', 'https://phimimg.com/upload/vod/20240205-1/3b8650667e967a9c2ba1667c0d4e7ef9.jpg', '<p>Năm 1997, hai cô gái Ib và Boum quyết định cùng nhau tự tử&nbsp;ở Bangkok, nhưng Boum đã không tự tử. Năm 2017, linh hồn thù hằn của Ib trở lại&nbsp;để ám ảnh Boum và cô con gái 15 tuổi. Ib và Boum là đôi bạn thân từ nhỏ, hai ông bố của Ib và Boum cũng là bạn làm ăn cùng đầu tư xây dựng một dự án căn hộ cao cấp. Năm 1997, cuộc khủng hoảng tài chính ở Thái Lan bùng nổ. Quẫn trí, họ&nbsp;quyết định cùng nhau tự sát, nhưng Boum không đủ can đảm như Ib nên&nbsp;đã bỏ chạy và ôm nỗi day dứt đó tiếp tục sống suốt 20 năm. Thời gian trôi đi, Boum trở thành một doanh nhân thành công&nbsp;và có một cô con gái xinh đẹp là Bell. Như có một thế lực kì bí dẫn đường Bell vô tình tìm đến địa điểm khi xưa xảy ra biến cố kinh hoàng. Kể từ đó mỗi đêm là mỗi cơn ác mộng không chỉ với Bell mà còn đối với Boum. Liệu hai mẹ con có thể thoát qua được kiếp nạn này hay cả hai cùng phải trả giá cho lời hứa bồng bột năm xưa?</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Apichaya Thongkham","avatar":""},{"name":"Numthip Jongrachatawiboon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324404);
