INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spark-thien-du-ky', 'Spark: Thiên Du Ký', 'Spark: A Space Tail', 'https://phimimg.com/upload/vod/20240205-1/116a6ba62a8c0a1375faa6240482c26b.jpg', 'https://phimimg.com/upload/vod/20240205-1/cbe1c85bb44ce7b86e5194aafb84b2f6.jpg', '<p>Phim Spark: Thiên Du Ký - Spark: A Space Tail 2017: Mười ba năm trước, tướng Zhong chiếm lĩnh hành tinh Bana, chia nhỏ hành tinh thành từng mảnh nhỏ. Spark cùng bạn bè, Chunk và Vix đã khám phá ra mưu đồ độc chiếm hành tinh của Zhong. Và nếu Zhong kiểm soát sức mạnh của quái vật cổ xưa – Kraken, hắn sẽ có trong tay thứ vũ khí chết chóc nguy hiểm nhất trong lịch sử của hệ hành tinh. Nhiệm vụ của Spark và bạn bè là ngăn chặn kế hoạch độc ác này. Cùng những người bạn, Spark bắt đầu cuộc phiêu lưu, khám phá ra vị trí thực sự của mình trong vũ trụ.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jessica Biel","avatar":""},{"name":"Hilary Swank","avatar":""},{"name":"Susan Sarandon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324404);
