INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bang-dang-2', 'Cuộc Chiến Băng Đảng 2', 'High And Low: End Of Sky', 'https://phimimg.com/upload/vod/20240205-1/b8b24cf270b9e5fbd31fc376195736b8.jpg', 'https://phimimg.com/upload/vod/20240205-1/376fa82a9586592fea604593b69f619c.jpg', '<p>Phim Cuộc Chiến Băng Đảng 2 - High And Low: End Of Sky 2017: Sau khi Liên Minh SWORD đánh bại được âm mưu thôn tính SWORD từ phía băng xã hội đen ngoại quốc của cha con Chanson và Lee. Giờ đây, khu vực SWORD đã yên bình trở lại. Và người anh em của MUGEN, Kohaku, cũng đã trở lại là con người như xưa của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Akira","avatar":""},{"name":"Shintarô Akiyama","avatar":""},{"name":"Shô Aoyagi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
