INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-roi', 'Bỏ Rơi', 'Stray', 'https://phimimg.com/upload/vod/20240220-1/bd97ac62a0d9aef3ddd02aa49610e269.jpg', 'https://phimimg.com/upload/vod/20240220-1/98ce7bf52bcf4f91bfcff533e6ff1475.jpg', '<p>Sau khi mất đứa con trai duy nhất, Polina và Igor quyết định chữa lành nỗi đau này bằng việc nhận con nuôi. Mọi rắc rối bắt đầu từ khi hai vợ chồng gặp được cậu bé đặc biệt và quyết định nhận đứa bé này làm con. Khi ác quỷ lợi dụng tình yêu thương và ẩn nấu dưới hình hài đứa con trai mà Polina yêu quý, liệu rằng cô có nhận ra sự thật khốc liệt là con trai mình đã qua chết vĩnh viễn từ lâu?</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
