INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lady-bird-tuoi-noi-loan', 'Lady Bird: Tuổi Nổi Loạn', 'Lady Bird', 'https://phimimg.com/upload/vod/20240128-1/335e85f89b60458c90833a7636371cca.jpg', 'https://phimimg.com/upload/vod/20240128-1/202f507178df406d64489b5923b48cf5.jpg', '<p>Christine Lady Bird McPherson (Saoirse Ronan) là một học sinh trung học từ phía sai của các bài hát. Cô khao khát phiêu lưu, tinh tế và cơ hội, nhưng không tìm thấy điều đó trong trường trung học Công giáo Sacramento của cô. Bộ phim này tuân theo năm cuối cấp của nhân vật chủ nhân ở trường trung học, bao gồm sự lãng mạn đầu tiên của cô ấy, sự tham gia của cô ấy vào vở kịch của trường và quan trọng nhất là ứng tuyển của cô ấy.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324404);
