INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-gio-trang-sang', 'Bao Giờ Trăng Sáng', 'Our Time Will Come', 'https://phimimg.com/upload/vod/20240128-1/b31df8d09caca0d8e307678a4499b631.jpg', 'https://phimimg.com/upload/vod/20240128-1/1c1452b5f3cf755d1191c38f3069d4ba.jpg', '<p>Bao Giờ Trăng Sáng được xây dựng dựa trên sự kiện lịch sử có thật vào năm 1941, khi Nhật Bản chiếm đóng Hồng Kông. Phim ca ngợi lớp người trẻ tuổi ở mọi tầng lớp sẵn sàng cùng nhau chung sức giúp đỡ các tri thức và nghệ sĩ Trung Quốc phải bỏ trốn khỏi đại lục trước sự hung bạo của phát xít Nhật.Phương Cô là một giáo viên dạy tiểu học yếu đuối, bình thường, sống cùng với mẹ trong một ngôi nhà nhỏ. Thế nhưng trước sự độc ác tàn bạo của quân Nhật, Phương Cô đã dần trở nên mạnh mẽ hơn và trở thành một nữ anh hùng quả cảm, người dẫn đầu cho cuộc chiến đánh đuổi kẻ thù xâm lược của giới trí thức và nhân dân trong thời kỳ kháng chiến khó khăn và thiếu thốn.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Tấn","avatar":""},{"name":"Bành Vu Yến","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Lương Gia Huy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
