INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-hay-khong-yeu-2017', 'Yêu Hay Không Yêu', 'To Love Or Not To Love', 'https://phimimg.com/upload/vod/20240128-1/002d1051456deb16e532df37fc5de985.jpg', 'https://phimimg.com/upload/vod/20240128-1/3a5443d129f100b68daeebb7cee563a5.jpg', '<p>Phim Yêu Hay Không Yêu kể về Tra Tử Kỳ – một cô gái luôn ao ước có một tình yêu đẹp đẽ và ngọt ngào. Nhưng trớ trêu thay cô lại rung động trước cậu bạn oan gia cùng lớp Trương Tử Hào. Mối tình đầu cả hai đầy mật ngọt nhưng cũng lắm đắng cay. Đối mặt với các thử thách tình cảm, liệu họ có thể viết nên kết thúc viên mãn cho câu chuyện tình yêu của mình?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Venus Wong","avatar":""},{"name":"Edward Ma","avatar":""},{"name":"Jason Fu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
