INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-ngoai-gio', 'Điệp Viên Ngoài Giờ', 'Part-time Spy', 'https://phimimg.com/upload/vod/20240128-1/372b1d942c0233cd0f1ea5091dbfc979.jpg', 'https://phimimg.com/upload/vod/20240128-1/1067e0166f2bb5a18c36ce4c79b0603b.jpg', '<p>Điệp Viên Ngoài Giờ - Part-time Spy (2017):Yeong-sil với vẻ ngoài luộm thuộm, được gọi là “vịt con xấu xí”. Mặc dù, có hàng tá bằng cấp nhưng cô nàng “vịt con” không có nỗi một nghề nghiệp ổn định. Ở tuổi 35, cô trở thành thực tập sinh tại Cơ quan an ninh quốc gia (NSA). Nhưng, để là nhân viên chính thức cô phải hoàn thành một nhiệm vụ từ cơ quan giao. Đó là làm nội gián trong một công ty lừa đảo ẩn mình dưới danh nghĩa trung tâm nguyên cứu khoa học, nhiệm vụ của cô nhằm chỉ điểm và lấy lại số tiền lừa đảo mang về.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Ye-won","avatar":""},{"name":"Han Chae-ah","avatar":""},{"name":"Nam Goong-min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
