INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-chien', 'Mật Chiến', 'Eternal Wave', 'https://phimimg.com/upload/vod/20240128-1/0de639deba8f3db40a03b7672ef735a1.jpg', 'https://phimimg.com/upload/vod/20240128-1/39e5b3d2025f7c2c38bb2d276f16ca4e.jpg', '<p>Phim Mật Chiến - Eternal Wave 2017: Mật Chiến lấy bối cảnh tại Thượng Hải vào những năm 1930, khi nơi này được mệnh danh là Paris của Phương Đông. Ẩn sau vẻ hoa lệ hào nhoáng ấy là một hiện thực vô cùng tàn khốc. Lý Hiệp là một chuyên gia điện tín được cử đến Thượng Hải thực hiện những nhiệm vụ tối mật cho Trung Quốc. Anh là người nổi tiếng với phong cách làm việc táo bạo nhưng đầy thận trọng. Lý Hiệp quen Hà Lan Phân và vì nhiệm vụ, cô đã trở thành vợ hờ của anh. Lan Phân sống dưới vỏ bọc là một bà nội trợ ngờ nghệch. Thế nhưng, cô lại là “nữ hán tử” với tinh thần đanh thép. Trong quá trình tiếp xúc với Lý Hiệp, hai người dần nảy sinh tình cảm với nhau, Lan Phân từ cô vợ hờ trở thành người bạn đồng hành suốt cuộc đời của Lý Hiệp. Cô cùng chồng tham gia vào nhiệm vụ tối mật tại Thượng Hải nhằm hạ bệ bè cánh phát xít Nhật.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Quách Phú Thành","avatar":""},{"name":"Trương Hàn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324404);
