INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-ca-map-2017', 'Mồi Cá Mập', 'Open Water 3: Cage Dive - Shark Terror', 'https://phimimg.com/upload/vod/20240127-1/01d2766015f7db2bbc2b475aefeff6d4.jpg', 'https://phimimg.com/upload/vod/20240127-1/9207dc0a6c7c0973521c73e5df5ac78a.jpg', '<p>Phim xoay quanh một nhóm bạn trẻ người Mỹ đang ấp ủ dự định thực hiện một đoạn clip tư liệu để dự thi chương trình thực tế. Với mong muốn có được những chất liệu chân thực nhất, cả ba quyết định đặt chân đến một vùng biển của Úc và trải nghiệm việc lặn biển trong lồng sắt dưới đáy đại dương. Họ đã có những giây phút vui vẻ và thú vị cho đến khi thảm họa ập đến, tất cả bị bao vây bởi đàn cá mập trắng khát máu. Đoạn clip dự thi ban đầu giờ đây trở thành nhật ký sống còn trong cuộc chiến dưới đại dương…</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Suzanne Dervish-Ali","avatar":""},{"name":"Megan Peta Hill","avatar":""},{"name":"Joel Hogan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324404);
