INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-chin-tang-may', 'Giữa Chín Tầng Mây', 'Beyond The Clouds', 'https://phimimg.com/upload/vod/20240126-1/e55cbe5c0e729b50ab332cf34202e1b0.jpg', 'https://phimimg.com/upload/vod/20240126-1/c3b917fec4687b2887c5b092ea45c7cd.jpg', '<p>Khi đang chạy trốn khỏi cảnh sát, Amir tìm thấy em gái ghẻ lạnh của mình là Tara, người trong nỗ lực bảo vệ anh trai mình đã phải vào tù. Toàn bộ cuộc sống của họ bị bao phủ bởi sự tuyệt vọng khi bất ngờ ánh sáng chiếu vào họ từ Beyond the Clouds.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ishaan Khattar","avatar":""},{"name":"Malavika Mohanan","avatar":""},{"name":"Sharada","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
