INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-oi-em-yeu-anh', 'Thầy Ơi... Em Yêu Anh', 'My Teacher', 'https://phimimg.com/upload/vod/20240126-1/9cde4f5590db769f5cf18dc7954fabc8.jpg', 'https://phimimg.com/upload/vod/20240126-1/6338d94c1d68c1065afe1759f5f1e8b6.jpg', '<p>Hibiki là sinh viên năm thứ hai khó xử, 17 tuổi, những người không biết chuyện tình lãng mạn. Nhưng cô ấy sắp yêu lần đầu tiên. Với ai? Một người đàn ông không tuyệt vời với lời nói, nhưng từ bi về học sinh của mình. Đó là giáo viên lịch sử của cô ấy, ông Ito. Có ổn không nếu tôi yêu bạn? Hibiki hỏi. Tôi sợ rằng tôi không thể trả lại những cảm xúc đó, là câu trả lời của Ito. Tình yêu đầu tiên của Hibiki gặp sự cố trước khi cất cánh. Nhưng nó không thành vấn đề. Tuy nhiên, tôi vẫn muốn trân trọng lòng của mình. Trái tim của một giáo viên bắt đầu biến bằng tình yêu thuần khiết của một học sinh.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
