INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-xena', 'Huyền Thoại Xena', 'Huyền Thoại Xena', 'https://phimimg.com/upload/vod/20240124-1/4eca55d1b0cbf87c5c3dd72ff7869a65.jpg', 'https://phimimg.com/upload/vod/20240124-1/0edbdbe24825bdda46a622f8ec772c09.jpg', '<p>Azura là người cuối cùng của Sarnians, một chủng tộc chiến binh đáng sợ. Thế giới nhà của cô, từng là một thiên đường xinh đẹp, giờ đây là một con trấn vô hồn sau khi Visrary phá hủy nó trong thời thơ ấu của cô. Cô sống sót và sống lang thang trên các đường phố của Draiga, lớn lên để lãnh đạo một nhóm chiến binh kháng chiến chống lại chế độ tà ác của Bộ Tư Lệnh Mục Triết Diện Sorrentine.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
