INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung', 'Nhân Chứng', 'Who Killed Cock Robin', 'https://phimimg.com/upload/vod/20240122-1/5b2b67ff892afa8b2721c5e8b03f69d5.jpg', 'https://phimimg.com/upload/vod/20240122-1/a044dfcc3bbfc286a360df4c2a93b595.jpg', '<p>Nhân chứng (Who Killed Cock Robin) là bộ phim hành động, tội phạm gay cấn do Trình Vĩ Hào đạo diễn và biên kịch xoay quanh anh chàng Tiểu Tề (Trang Khải Huân) - người đang làm việc tại một toà soạn không may trở thành nhân chứng bất đắc dĩ của một vụ tai nạn xe cộ vào một đêm mưa gió. Trong vụ tại nạn đó, người lái xe tử vong tại chỗ, còn cô gái ngồi ở ghế phụ Từ Á Đình (Kha Giai Yến) được đưa tới bệnh viện. Quá hoảng sợ, Tiểu Tề chụp lại biển số xe và rời khỏi hiện trường. Tuy nhiên bức ảnh quá mờ để làm bằng chứng nên vụ án không được thiết lập</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Trang Khải Huân","avatar":""},{"name":"Kha Giai Yến","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324404);
