INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-dem-nguoc', 'Cuộc Giải Cứu Đếm Ngược', 'Reset', 'https://phimimg.com/upload/vod/20240121-1/246dd8b95a55874551b59d1454653e9d.jpg', 'https://phimimg.com/upload/vod/20240121-1/8c6d31c1c1bd2fd8ea80e7025bdc9d57.jpg', '<p>Phim Cuộc Giải Cứu Đếm Ngược - Reset 2017: xoay quanh nhà khoa học kiêm bà mẹ trẻ đơn thân Hạ Thiên. Cô đã phát triển thành công công nghệ vượt thời gian bằng cách xuyên qua lỗ đen và công trình này rơi vào tầm ngắm của Thôi Hổ. Để ép Hạ Thiên giao công nghệ này cho mình, Thôi Hổ đã bắt cóc con trai Đậu Đậu của Hạ Thiên để uy hiếp cô. Để cứu con, Hạ Thiên đã sử dụng công trình nghiên cứu còn chưa hoàn thiện để quay về 1 tiếng 50 phút trước đó. Từ đấy, rất nhiều bí ẩn dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324404);
