INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-loi-cua-me', 'Tội Lỗi Của Mẹ', 'Killer Mom', 'https://phimimg.com/upload/vod/20240111-1/2fa76f7887f58a6ce42633c13d4e50be.jpg', 'https://phimimg.com/upload/vod/20240111-1/3a7c9768312a332218cd7c95ab16b43a.jpg', '<p>Tội Lỗi Của Mẹ - Killer Mom là bộ phim nói về Jessica. Khi cô không còn một xu dính túi bởi người chồng mưu mô của mình, Jessica đặt mục tiêu vào hàng triệu đô la mà cô con gái Allison, người mà cô đã từ bỏ khi còn bé, sẽ được số tiền thừa kế kếch xù. Trong khi Allison chào đón người mẹ ruột của mình thì em gái của Jessica, Sydni và người bảo mẫu mới chính là người hợp pháp được giám hộ số tiền ấy. Thật không may cho cả hai, một Jessica tàn nhẫn sẽ không dừng lại để kiểm soát tiền của Allison, ngay cả khi giết người.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Karen Cliche","avatar":""},{"name":"Kirby Bliss Blanton","avatar":""},{"name":"Maddy Martin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324404);
