INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sao-bi-mat', 'Siêu Sao Bí Mật', 'Secret Superstar', 'https://phimimg.com/upload/vod/20240104-1/998843bbe5e0422f6fa8899f65a81bf6.jpg', 'https://phimimg.com/upload/vod/20240104-1/3f27363d339c4f3dd2160e85a00cacd0.jpg', '<p>Secret Superstar là bộ phim điện ảnh âm nhạc Ấn Độ sắp ra mắt, được lên kịch bản và đạo diễn bởi Advait Chandan và do Aamir Khan và Kiran Rao sản xuất. Bộ phim có sự tham gia của Zaira Wasim, Meher Vij và Aamir Khan, và có nội dung xoay quanh một cô bé với khao khát trở thành ca sĩ. Cô bé Insia 14 tuổi cực kỳ mong muốn được trở thành một ca sĩ nổi tiếng, nhưng người cha hiền lành của cô đang cản bước cô trên con đường đi tới giấc mơ tuyệt diệu đó. Tuy nhiên, xuất hiện dưới vai trò ca sĩ ẩn danh, cô sớm trở thành một hiện tượng internet - một Siêu sao bí mật. Mọi người trên thế giới đều rất kinh ngạc trước khả năng của cô và một nhạc sĩ nổi tiếng cố vấn cho cô, Insia bắt đầu dấn thân vào một cuộc hành trình thú vị sẽ làm thay đổi cuộc sống của cô và mọi người xung quanh cô mãi mãi.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Zaira Wasim","avatar":""},{"name":"Aamir Khan","avatar":""},{"name":"Meher Vij","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324404);
