INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-thoi-hen-ho', 'Một Thời Hẹn Hò', 'Once Upon A Date', 'https://phimimg.com/upload/vod/20240104-1/b65c0adb2a8c6fb0af3ddcb713a8501d.jpg', 'https://phimimg.com/upload/vod/20240104-1/fdc0b06ed2c4e62eb080f14af97c5f9c.jpg', '<p>Một bộ phim hài lãng mạn kể về một rạp hát do một gia đình sở hữu đang gặp khó khăn trước nguy cơ bị buộc phải ngừng kinh doanh bởi một nhà phát triển bất động sản tham lam. Khi Josh Danahue, nhà môi giới bất động sản hàng đầu, được gửi đến để mua lại một nhà hát, anh bất ngờ phải lòng người chủ, buộc anh đảm nhận nhiệm vụ xoay chuyển tình thế của rạp hát bằng cách thử vai cho Prince Charming trong tác phẩm Once Upon A Date sắp tới.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Francia Raisa","avatar":""},{"name":"Dean Geyer","avatar":""},{"name":"James Callis","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"Titus Makin Jr","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324404);
