INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-phan-gian', 'Điệp Vụ Phản Gián', 'Unlocked', 'https://phimimg.com/upload/vod/20240104-1/c129e69b2feaf694b91bbc489822c362.jpg', 'https://phimimg.com/upload/vod/20240104-1/e123ae7744d87e2e3dfdcf54a860f530.jpg', '<p>Phim Điệp Vụ Phản Gián - Unlocked 2017: Alice Racine, một trong những thẩm vấn viên xuất sắc nhất của CIA – , sự nghiệp của Alice xuống dốc sau khi cô chậm trễ trong một nhiệm vụ khai thác thông tin của một kẻ tình nghi. Hậu quả là một vụ tấn công khủng bố đẫm máu đã xảy ra giữa thủ đô Paris – Pháp gây ra cái chết của hàng chục thường dân vô tội. Alice sau đó bị thuyên chuyển công tác tới London, nơi cô thực hiện các nhiệm vụ gián điệp thầm lặng. Tuy nhiên, vì một thẩm vấn viên của CIA đột ngột tử nạn, Alice ngẫu nhiên trở thành lựa chọn duy nhất và cô được giao nhiệm vụ phải truy hồi thông tin của một đối tượng hồi giáo cực đoan, kẻ đang bị nghi ngờ sẽ tấn công London bằng vũ khí sinh học. Từ đây nhiều mối liên quan mờ ám và âm mưu kinh hoàng dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 28, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noomi Rapace","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Michael Douglas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324404);
