INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-o-berlin', 'Mất Tích Ở Berlin', 'Berlin Syndrome', 'https://phimimg.com/upload/vod/20240104-1/50ab365d2aa278d7be1b7cf4374ffe5d.jpg', 'https://phimimg.com/upload/vod/20240104-1/9fafbd0473400c081081f2abf9b288d4.jpg', '<p>Còn gì khủng khiếp hơn khi một cuộc tình cuồng nhiệt và lãng mạn biến thành một mối quan hệ khủng khiếp? Một nhiếp ảnh gia người Úc có trải nghiệm kinh hoàng khi tỉnh giấc vào buổi sáng, trong một căn hộ nơi thủ đô Berlin và không-thể-rời-khỏi. Berlin Syndrome là bộ phim gay cấn và kịch tính mới nhất của đạo diễn Cate Shortland, do nữ diễn viên xinh đẹp Teresa Palmer đóng chính.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Teresa Palmer","avatar":""},{"name":"Max Riemelt","avatar":""},{"name":"Matthias Habich","avatar":""},{"name":"Thuso Lekwape","avatar":""},{"name":"Morgane Ferru","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324404);
