INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-tren-khong', 'Phi Vụ Trên Không', 'Altitude', 'null', 'https://phimimg.com/upload/vod/20240104-1/a04f6f73aa8419d1ac282d532ef0b0b9.jpg', '<p>Bộ phim Phi Vụ Trên Không – Altitude xoay quanh một nữ đặc vụ FBI - Gretchen Blair đang trên đường đến Washington DC, cô được người đàn ông ngồi cạnh đưa ra đề nghị bất thường. Anh giải thích rằng máy bay của họ sắp bị bắt cóc và hứa hẹn sẽ trả 75 triệu đô nếu cô có thể giúp anh trở lại mặt đất an toàn. Khi một băng nhóm những tên trộm chuyên nghiệp đã nắm quyền kiểm soát chiếc máy bay, cô nhận ra rằng anh không hề nói dối và phát hiện anh ta cũng là một tên trộm. Gretchen nhận ra rằng mình đang ở giữa một vụ trộm cắp trên không trung; Một cuộc chiến gây cấn đã xảy ra và cô đang cố gắng cứu sống bản thân mình cùng tất cả hành khách trên chuyến bay</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Denise Richards","avatar":""},{"name":"Jonathan Lipnicki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
