INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-toi-kinh-hoang', 'Vùng Tối Kinh Hoàng', 'Out Of The Shadows', 'https://phimimg.com/upload/vod/20240103-1/ea7e4eecb4e01f9d5dccdb7bc9bf80ed.jpg', 'https://phimimg.com/upload/vod/20240103-1/74d341673de185961749b29bde770520.jpg', '<p>Một thám tử và vợ đang mang thai của anh chuyển đến ở ngôi nhà mơ ước của họ mà không biết về lịch sử đen tối của nó. Khi vợ anh thấy rằng em bé của họ đang bị dày vò bởi một lực lượng siêu nhiên và tìm kiếm sự giúp đỡ của một nhà thần học, anh buộc phải điều tra quá khứ để cứu gia đình mình.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Thuyết Minh', 'HD', 'Úc', 0, '[{"name":"Goran D. Kleut","avatar":""},{"name":"Jake Ryan","avatar":""},{"name":"Lisa Chappell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
