INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ma-luc-nua-dem', 'Chuyện Ma Lúc Nửa Đêm', 'Ghost Stories', 'https://phimimg.com/upload/vod/20231231-1/feb2e08b2dbc6ae1502c7a0ac581c6c3.jpg', 'https://phimimg.com/upload/vod/20231231-1/3b6deff9059f19d352eed28ae0f00c25.jpg', '<p>Ghost Stories nói về Giáo sư Phillip Goodman bắt tay vào một cuộc tìm kiếm ly kỳ sau khi ông vấp phải một tập tin bị mất từ rất lâu, trong đó chứa những thông tin chi tiết về ba trường hợp “bị ám\</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Freeman","avatar":""},{"name":"Alex Lawther","avatar":""},{"name":"Jill Halfpenny","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
