INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-gia-gian-ac-va-nhung-chuyen-khac', 'Cáo Già Gian Ác Và Những Chuyện Khác', 'The Big Bad Fox And Other Tales', 'https://phimimg.com/upload/vod/20231231-1/bb90650bed06bfd07e8c4b7b79f81a26.jpg', 'https://phimimg.com/upload/vod/20231231-1/a86904fb611cde0906cb41cf970c7c36.jpg', '<p>Nông trại của Thung lũng ngàn hoa vốn là một nơi yên bình với những loài động vật chung sống hòa thuận quanh năm. Thế nhưng sự xuất hiện của một vài nhân vật không ngờ tới cùng bản tính khờ dại của bộ đôi Thỏ và Vịt đã cuốn các cư dân ở đây vào những cuộc hành trình dở khóc dở cười, khi Thỏ tinh nghịch phải thay loài cò mang em bé đến cho bố mẹ, Cáo “gian ác” phải giả làm gà mái nuôi nấng ba chú gà con ngộ nghĩnh và bảo vệ chúng trước Sói ranh mãnh, Vịt xí xớn phải sắm vai Ông già Nô-en mang quà cho trẻ em khắp thế giới để cứu lấy Giáng sinh. Ba câu chuyện nhỏ như ba sắc màu đổi thay của mùa màng, của dòng chảy thời gian. Hè về, thu tới, rồi đông sang, Giáng sinh đến cũng là lúc các nhân vật dần học được cách chấp nhận và trân trọng nhau, để hiểu rằng sự nghịch ngợm không hẳn là đáng trách, sự ngây thơ không hẳn là dại dột, và tình bạn chân chính cũng như phép màu luôn tồn tại trong cuộc sống quanh ta, chỉ cần ta biết tin tưởng và yêu thương.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Guillaume Darnault","avatar":""},{"name":"Guillaume Bouchède","avatar":""},{"name":"Boris Rehlinger","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324405);
