INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bep-tranh-tai', 'Vua Bếp Tranh Tài', 'The Chef', 'https://phimimg.com/upload/vod/20231231-1/ce614ace235d76f14e44e816e095d77f.jpg', 'https://phimimg.com/upload/vod/20231231-1/f610bb3288be81941bdbbb54bdc2fc11.jpg', '<p>Vì thất bại trong 1 trận quyết chiến năm xưa, đầu bếp kỳ tài Đàm Nhất Phàm lui về ở ẩn. Mấy năm sau, Hà Thế Long – người sư đệ từng bị anh đuổi đi đến tìm anh phân cao thấp, đồng thời khiêu chiến với địch thủ năm xưa để lấy lại danh tiếng cho lớp Ẩm Thực Trung Hoa. Thế nhưng giờ đây Nhất Phàm đã bị mất hết vị giác.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Giả Chính Vũ","avatar":""},{"name":"Tống Tinh Nghiên","avatar":""},{"name":"Trịnh Húc Đông","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
