INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-tap-chi-tinh-do-thoi-xan', 'Nghịch Tập Chi Tinh Đồ Thôi Xán', 'The Way To Be Shinning Star', 'https://phimimg.com/upload/vod/20240112-1/3139bd71ac11e0359b19936bba60854b.jpg', 'https://phimimg.com/upload/vod/20240112-1/3da1f99f40799b94f5d64e0a8d13a332.jpg', '<p>Sinh viên năm tư Tô Tranh (Tống Dật) vốn là fan của tiểu sinh hạng hai Ngôn Sở Phi (Push Puttichai Kasetsin). Để theo đuổi nam thần, cô khởi nghiệp bằng việc làm trợ lý cho nghệ sỹ rồi bước vào showbiz muôn màu muôn vẻ. Để có cơ hội được Ngôn Sở Phi (Ngạn Hi) để ý đến, Tô Tranh tham gia tuyển chọn, ký hợp đồng với công ty của Đoạn Thừa Hiên, bước vào nghề diễn viên. Quản lý Đoạn Lăng Vi (Hàn Tuyết) giành cơ hội quay phim cho Tô Tranh, cuối cùng Sở Ngôn Phi cũng chú ý tới Tô Tranh, còn Đoạn Thừa Hiên cũng thay đổi ấn tượng ban đầu về Tô Tranh. Suốt quá trình, Tô Tranh chứng kiến đủ chuyện lạ đời trong showbiz, cũng thật sự ý thức được sự hấp dẫn của nghề diễn.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Push Puttichai","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Vương Tử Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
