INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-thoai-hong-gil-dong', 'Giai Thoại Hong Gil Dong', 'Thief Who Stole The People', 'https://phimimg.com/upload/vod/20240112-1/20dbf7e6dbbc780554b8cc64b5d70262.jpg', 'https://phimimg.com/upload/vod/20240112-1/29b94392d34076bd45d523418624e7f4.jpg', '<p>Giai thoại Hong Gil Dong là bộ phim cổ trang, xoay quanh cuộc đời của Hong Gil Dong, người khai sáng ra thời đại Joseon, Hàn Quốc. Hong Gil Dong là con ngoài giá thú của một quý tộc, tinh thông võ nghệ. Cuộc sống lang bạt khắp nơi đã cho Gil Dong thấy rõ bộ mặt thật của xã hội lúc bấy giờ. Kể từ đó, anh quyết định dùng sức mạnh vốn có của mình để ra tay trấn áp kẻ giàu, giúp đỡ dân nghèo, những người có cùng tầng lớp thấp hèn như anh.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ji-suk","avatar":""},{"name":"Yoon Kyun Sang","avatar":""},{"name":"Chae Soo Bin","avatar":""},{"name":"Kim Sang Joong","avatar":""},{"name":"Lee Ha Nui","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324405);
