INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sieu-anh-hung-vixen', 'Nữ Siêu Anh Hùng Vixen', 'Vixen: The Movie', 'https://phimimg.com/upload/vod/20240102-1/ea6498948da964a3ee417056906ef61a.jpg', 'https://phimimg.com/upload/vod/20240102-1/c66162a24d0f8df90c7ff88cf050d340.jpg', '<p>Dựa trên nhân vật Mari McCabe/Vixen của DC, một cô gái sở hữu chiếc mề đay ẩn chứa sức mạnh của muôn thú. McCabe đã sử dụng sức mạnh này và trở thành một nữ anh hùng chống lại cái xấu. Bộ phim được đặt trong một vũ trụ song song với Arrow, Flash &amp; Lengends Of Tomorrow.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Megalyn Echikunwoke","avatar":""},{"name":"Stephen Amell","avatar":""},{"name":"Grant Gustin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324405);
