INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-bien-vung-caribbe-phan-5-salazar-bao-thu', 'Cướp Biển Vùng Caribbe (Phần 5): Salazar Báo Thù', 'Pirates Of The Caribbean 5: Dead Men Tell No Tales', 'https://phimimg.com/upload/vod/20240102-1/2df98b9888e47d288a17fd3651c1277b.jpg', 'https://phimimg.com/upload/vod/20240102-1/e75c0a42743f9c5ad01505b0d6a167a9.jpg', '<p>Dead Men Tell No Tales là bộ phim thứ 5 của loạt phim Cướp Biển Vùng Caribbean do nam diễn viên Johnny Depp thủ vai chính, thuyền trưởng Jack Sparrow. Trong phần 5, hồn ma của thuyền trưởng Salazar trở về và dự định tiêu diệt mọi cướp biển dám đi lại trên biển, kể cả Jack Sparrow. Để sống sót, Jack Sparrow lên đường đi tìm cây đinh ba huyền thoại của thần biển Poseidon (trong thần thoại Hy Lạp, Poseidon là anh em với thần Zeus, Hades và Hera. Poseidon tương đương với thần Neptune trong thần thoại La Mã), một báu vật có khả năng điều khiển biển theo ý muốn của người sử dụng.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Brenton Thwaites","avatar":""},{"name":"Kaya Scodelario","avatar":""},{"name":"Kevin Mcnally","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Angus Barnett","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"Adam Brown","avatar":""},{"name":"Giles New","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Mahesh Jadu","avatar":""},{"name":"Jessica Green","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuon