INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-dac-cong-2-tien-den', 'Lính Đặc Công 2: Tiền Đen', 'Commando 2: The Black Money Trail', 'https://phimimg.com/upload/vod/20240102-1/847ba4f0d85bd8400ba552848900f1ad.jpg', 'https://phimimg.com/upload/vod/20240102-1/f1f67ab7b7d0a2bbb98e3be4f27c666e.jpg', '<p>Vicky Chaddha, một tên trùm về tiền đen ở Ấn Độ, đã bị bắt tại Malaysia, hiện tại Vicky Chaddha cùng với vợ mình đang bị giam giữ tại một căn nhà được chính phủ Malaysia canh gác nghiêm ngặt. Một nhóm biệt kích gồm 4 người được cử đến Malaysia để hộ tống họ trở về Ấn Độ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Vidyut Jamwal","avatar":""},{"name":"Adah Sharma","avatar":""},{"name":"Freddy Daruwala","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
