INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-dac-cong-2-tien-den', 'Lính Đặc Công 2: Tiền Đen', 'Commando 2: The Black Money Trail', 'lính đặc công 2: tiền đen commando 2: the black money trail vidyut jamwal adah sharma freddy daruwala ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phat-minh-ra-giang-sinh', 'Người Phát Minh Ra Giáng Sinh', 'The Man Who Invented Christmas', 'https://phimimg.com/upload/vod/20240102-1/3ab55e5b7e9d3cba7eea579ce22251f3.jpg', 'https://phimimg.com/upload/vod/20240102-1/13c1a018ece82daa268e9c5972255bca.jpg', '<p>Phim kể về cuộc hành trình huyền diệu đã dẫn đến việc tạo ra Ebenezer Scrooge (Christopher Plummer), Tiny Tim và các nhân vật cổ điển khác từ câu chuyện A Christmas Carol. Tháng 10 năm 1843, Charles Dickens (Dan Stevens) nếm mùi thất bại với ba cuốn sách cuối cùng của ông. Bị từ chối bởi các nhà xuất bản của mình, ông bắt đầu viết và tự xuất bản một cuốn sách mà ông hy vọng sẽ đảm bảo cuộc sống cho gia đình và khôi phục sự nghiệp của ông. Được đạo diễn bởi Bharat Nalluri (Miss Pettigrew Lives For A Day), bộ phim thuật lại làm cách nào Charles Dickens (Dan Stevens) đã kết hợp những cảm hứng từ đời thực sống động với sự tưởng tượng bay bổng của mình để gợi lên những nhân vật không thể nào quên và một câu chuyện không hồi kết và thay đổi mãi mãi kỳ nghĩ lễ thành lễ Giáng Sinh mà ta biết ngày nay.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Stevens","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Jonathan Pryce","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324405);
