INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-du-lich-tham-hoa', 'Chuyến Du Lịch Thảm Họa', 'Thailand Only', 'null', 'https://phimimg.com/upload/vod/20240102-1/ff83e2d55c5612e910798a5e73f54b6f.jpg', '<p>Bộ phim Chuyến Du Lịch Thảm Họa - Thailand Only kể về câu chuyện của chàng trai Jack là chủ sở hữu của một công ty du lịch nhỏ không có quỹ, không có tín dụng, không có kết nối và chỉ có hai trợ lý. Để mở rộng sang thị trường khách du lịch Trung Quốc, anh phải tiếp nhận nhóm khách hàng đầu tiên của mình, những người dường như không phải là khách du lịch thông thường. Đây sẽ là chuyến đi của cuộc đời qua nhiều địa điểm và tình huống khác nhau chỉ xảy ra ở Thái Lan. Nhưng mọi thứ có thể không đơn giản như vậy, vì Jack đã được theo dõi chặt chẽ bởi ‘Mao, một du khách trung niên có một bí mật không được tiết lộ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Archom Pridakun","avatar":""},{"name":"Chusak Iamsuk","avatar":""},{"name":"Phadung Song Saeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
