INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ho-ngui-tuong-vi-long-phung-dai-dao', 'Mãnh Hổ Ngửi Tường Vi: Long Phụng Đại Đạo', 'Tiger And Flower: Peony And Lion', 'null', 'https://phimimg.com/upload/vod/20240126-1/b7a5c67335b0854437ef5694381d51a2.jpg', '<p>Mãnh Hổ Ngửi Tường Vi: Long Phụng Đại Đạo - Tiger And Flower: Peony And Lion kể về Lâm Kì Lân đến và mang theo một xấp giấy báo đến trước một cặp nam nữ chuyên trộm đồ trang sức có giá trị, và nói rằng mô thức hoạt động của họ rất giống với mãnh hổ ngửi tường vi. Lâm Kì Lân nói rằng anh ta không thể lấy lại được số tài sản đã mất nên chỉ có thể kết tội hai người là nghi phạm. Cả hai từng có tiền án nên không muốn gây chuyện nên chỉ có thể thỏa thuận.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yan","avatar":""},{"name":"Liu Zhuoting","avatar":""},{"name":"Wang Jun Peng","avatar":""},{"name":"Yi Wen","avatar":""},{"name":"Yu Tiểu Loan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
