INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-em-o-manhattan', 'Gặp Em Ở Manhattan', 'Love Is A Broadway Hit', 'https://phimimg.com/upload/vod/20231231-1/a75d693371b9322c47d2c31218d5929f.jpg', 'https://phimimg.com/upload/vod/20231231-1/fe69c966e6aad9fad1efbbf4c66e69a7.jpg', '<p>Gặp Em Ở Manhattan - Love Is A Broadway Hit kể về Vi Đông và Bạch Kì - hai người trẻ đầy nhiệt huyết với khát vọng được biểu diễn trên sân khấu Broadway. Giữa nơi đất khách quê người tại New York, hai người tình cờ gặp nhau và trở nên thân thiết. Éo le thay, kết quả buổi thử vai Hoa Mộc Lan đã biến Vi Đông và Bạch Kì trở thành đối thủ của nhau. Giữa tình bạn và sự nghiệp, liệu họ sẽ phải chọn như thế nào?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Dĩ Tường","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Lý Viên","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
