INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-hanh-dien-nha-duong', 'Niềm Hãnh Diện Nhà Đường', 'The Glory Of Tang Dynasty', 'https://phimimg.com/upload/vod/20240109-1/ca13892d1505e8b994e608d2619a7c2f.jpg', 'https://phimimg.com/upload/vod/20240109-1/55175afa37da9a1e24376bc9769e0f78.jpg', '<p>Kể về cuộc đời thăng trầm của Thẩm Trân Châu - nàng tiểu thư bị ép tham gia cuộc tuyển chọn phi tần của Quảng Bình Vương. Khi chiến tranh xảy ra, Trân Châu nguyện đồng cam cộng khổ cùng dân chúng. Về sau, khi con trai cả là Đường Đức Tông lên ngôi, nàng đã được sắc phong và tôn vinh vì những cống hiến dành cho đất nước.</p>', 'Hoàn Tất (82/82)', 82, 'series', 'completed', 16, 2017, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Cảnh Điềm","avatar":""},{"name":"Mao Tử Tuấn","avatar":""},{"name":"Thư Sướng","avatar":""},{"name":"Tần Tuấn Kiệt","avatar":""},{"name":"Vạn Thiến","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324405);
