INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kuroko-tuyen-thu-vo-hinh-tran-dau-cuoi-cung', 'Kuroko Tuyển Thủ Vô Hình: Trấn Đấu Cuối Cùng', 'Kuroko''s Basketball: Last Game', 'https://phimimg.com/upload/vod/20231231-1/9ec0d0488f56ebc98398314d78dc53f8.jpg', 'https://phimimg.com/upload/vod/20231231-1/ac809e9d741d40d109eb69da6faa547d.jpg', '<p>Phim Kuruko Tuyển Thủ Vô Hình: Trấn Đấu Cuối Cùng - Kuroko no Basket Movie 4: Last Game 2017: Bộ phim diễn ra sau khi Kuroko và Kagami trở thành học sinh năm 2 cao trung Seirin. Một đội bóng rổ của Hoa Kỳ mang tên Jabberwock đã đến Nhật Bản và đấu giao hữu với đội bóng rổ Nhật. Sau sự thất bại của đội Nhật, các thành viên của Jabberwock bắt đầu chế giễu và khinh thường bóng rổ Nhật Bản. Bắt đầu từ đây, nỗi quyết tâm của những chàng trai trong đội bóng của Nhật được khơi dậy mạnh mẽ, những thành viên của Thế hệ kỳ tích tập hợp lại thành đội Vorpal Swords, đối đầu với Jabberwock.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Yuki Ono","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324405);
