INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('222', '2:22', '2:22', 'https://phimimg.com/upload/vod/20231230-1/aa62cae8f9dcf363f1ed8f7289791097.jpg', 'https://phimimg.com/upload/vod/20231230-1/133f738198cf6d4ff3966708f66aaa62.jpg', '<p>Hai chiếc máy bay suýt va chạm sau khi một tia sáng chói mắt làm tê liệt nhân viên kiểm soát không lưu Dylan Branson trong vài giây. Bị đình chỉ công việc, Dylan bắt đầu nhận thấy một kiểu âm thanh và sự kiện đáng ngại lặp đi lặp lại chính xác theo cùng một cách mỗi ngày, kết thúc chính xác vào lúc 2:22 chiều. Cũng bị cuốn vào một mối quan hệ phức tạp với một người phụ nữ, Dylan phải tìm cách phá vỡ sức mạnh của quá khứ và kiểm soát thời gian.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michiel Huisman","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Sam Reid","avatar":""},{"name":"John Waters","avatar":""},{"name":"Richard Davies","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
