INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-ngan-can-2017', 'Sắc Đẹp Ngàn Cân', '200 Pounds Beauty', 'https://phimimg.com/upload/vod/20231012-1/b0604471d67a11564afd34f315e0b539.jpg', 'https://phimimg.com/upload/vod/20231012-1/9bc2bfc626b6a023dfececbd98f101d1.jpg', '<p>Sắc Đẹp Ngàn Cân là một câu chuyện hài hước, lãng mạn về hai cô gái: Jolie (Jolie Phương Trinh) gợi cảm, quyến rũ nhưng có giọng hát dở tệ và Hà My (Minh Hằng) mập ú nhưng có giọng hát trời phú, phải đứng hát sau cánh gà sân khấu. Vì vẻ ngoài xấu xí, Hà My bị mọi người đối xử rất hững hờ nhưng cô luôn vô tư cho đến khi Jolie sỉ nhục cô ngay trước mặt người mà cô yêu thầm nhớ trộm là Duy Khang (Rocker Nguyễn). Mọi chuyện vì thế từ đây bắt đầu thay đổi.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Minh Hằng","avatar":""},{"name":"Phương Trinh Jolie","avatar":""},{"name":"Rocker Nguyễn","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324405);
