INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trong-toi-ac', 'Sống Trong Tội Ác', 'Heartless City', 'https://phimimg.com/upload/vod/20240109-1/8bd4c1aece59e707b84a3cbbcbfc5e86.jpg', 'https://phimimg.com/upload/vod/20240109-1/109e9555bccfd5ef840b50ba5c4daa00.jpg', '<p>Cuộc đảo chính chấn động thế giới ngầm nhanh chóng khiến con trai tiến sĩ Jung Shi Hyun trở thành mục tiêu săn đuổi của cả giới xã hội đen, lẫn cảnh sát. Vốn sinh ra và lớn lên trong vũng lầy xã hội, được trang bị bản lĩnh, sự điềm tĩnh, khả năng võ nghệ và tài trí hiếm có, những cuộc trạm chán với cả hai giới hắc - bạch đều không khiến Shi Hyun nao núng, mà ngược lại nó càng biến anh thành tay tội phạm cực kỳ nguy hiểm trong mắt cảnh sát. Cuộc sống của ông trùm mới nổi Shi Hyun đột ngột biến đổi khi tận mắt chứng kiến cái chết của mối tình đầu – nữ cảnh sát Lee Kyung Mi. Sự cố đó không chỉ mang đến đau khổ tột cùng cho anh, khiến anh gánh lấy nỗi oan giết người, mà còn là sự kiện bắt đầu cho những sóng gió liên tiếp trong đời tay giang hồ khét tiếng. Nếu ở phía cảnh sát, Shi Hyun liên tục phải lẫn tránh sự truy bắt điên cuồng của Hyung Min – người yêu hiện tại của Kyung Mi – thì trong thế giới ngầm, anh lại phải chịu sự truy sát khốc liệt của ông trùm ma túy Pusan và dàn tay sai tàn nhẫn, thủ đoạn.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 11, 2017, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
