INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-that-su', 'Người Mẹ Thật Sự', 'The Wrong Mother', 'https://phimimg.com/upload/vod/20240121-1/170261c5f29cee05bfad0c2b04ee5ae6.jpg', 'https://phimimg.com/upload/vod/20240121-1/7d97551cf1669c49eae1bec5a447c73b.jpg', '<p>Giấc mơ trở thành mẹ của Kelsey Larsen cuối cùng đã thành hiện thực. Cô sắp trở thành mẹ của cặp song sinh xinh đẹp từ thủ tục trong ống nghiệm. Nhưng khi Kelsey cần có người chăm sóc tại nhà, cô y tá mà cô thuê không ai khác chính là người hiến trứng để Kelsey có thể trở thành mẹ- và người phụ nữ điên rồ đã đến để đòi lại những đứa con của cô ấy!</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vanessa Marcil","avatar":""},{"name":"Brooke Nevin","avatar":""},{"name":"Stephen Snedden","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
