INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-thuoc-ky-bi', 'Phương Thuốc Kỳ Bí', 'A Cure For Wellness', 'https://phimimg.com/upload/vod/20231203-1/b60397d640109b696b2dec107b0b64dd.jpg', 'https://phimimg.com/upload/vod/20231203-1/cf2f0ea5559274069980c1e47f50ee0d.jpg', '<p>Lấy bối cảnh ở một tương lai giả định, phim xoay quanh một chàng nhân viên trẻ tuổi tham vọng được cử tới đón CEO của công ty về từ một “trung tâm điều trị” tại vùng núi Alps, Thụy Sĩ. Tưởng như đây là một chuyến đi đơn giản, anh đã không lường trước được những bí mật chết người mà nơi này đang cố che giấu. Bị ép buộc ở lại, chàng trai sớm hiểu rằng các phương thức chữa trị thần kì của nơi đây không giống như vẻ bề ngoài tốt đẹp của nó. Nhưng càng đào sâu tìm kiếm, anh càng chìm đắm vào những bí mật kinh hoàng đó.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dane DeHaan","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Mia Goth","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
