INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-2017', 'Đối Mặt', 'Drone', 'https://phimimg.com/upload/vod/20240108-1/069a982eb966783c797f71a73cfdb241.jpg', 'https://phimimg.com/upload/vod/20240108-1/a7244e7c954c799d62336373992c7035.jpg', '<p>Bộ phim kể về anh chàng Neil là người lính điều khiển máy bay không người lái, anh thường thực hiện những chuyến bay bí mật theo lệnh, trong đó có vụ bắn chết 1 gia đình tên Hồi giáo cực đoan từ trên không, sau đó quay trở lại cuộc sống gia đình ở ngoại thành - không có vợ hoặc con trai biết về cuộc sống bí mật của anh. Sự việc cứ tiếp diễn như vậy cho đến khi một doanh nhân Pakistan bí ẩn là Imir đến tìm gặp Neil. Imir tin là Neil chịu trách nhiệm về cái chết của gia đình anh ta nên anh ta đã bí mật theo dõi gia đình Neil. Neil không biết rằng hắn là tên Hồi giáo cực đoan đang thực hiện một âm mưu khủng bố thông qua gia đình Neil.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Mary McCormack","avatar":""},{"name":"Joel David Moore","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324405);
