INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-canh-dai-bang', 'Đôi Cánh Đại Bàng', 'On Wings Of Eagles', 'https://phimimg.com/upload/vod/20231219-1/ce126c17b7f3ed858ec0d1647f4b909e.jpg', 'https://phimimg.com/upload/vod/20231219-1/26a28fa7c5fcec53dc4045ae5328d578.jpg', '<p>Bộ phim lược thuật về cuộc đời tận hiến của Eric Liddell, một vận động viên đoạt huy chương vàng thế vận hội 1924, nổi tiếng khắp thế giới với biệt danh “Người Tô Cách Lan thần tốc”. Từ bỏ danh vọng và hạnh phúc gia đình, ông đã quay về Trung Hoa giữa lúc chiến tranh Trung-Nhật đang dai dẳng, để truyền đạo và dạy học. Năm 1943 ông bị Nhật bắt vào trại tập trung. Cả đời ông là một cuộc đua không mệt mỏi để mang lại hạnh phúc và hy vọng cho mọi người.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Joseph Fiennes","avatar":""},{"name":"Shawn Dou","avatar":""},{"name":"Elizabeth Arends","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324405);
