INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kizumonogatari-phan-3-lanh-huyet', 'Kizumonogatari Phần 3 : Lãnh Huyết', 'Kizumonogatari Part 3: Reiketsu', 'https://phimimg.com/upload/vod/20231219-1/f9556aa0eeaf80fb482070e1c666772b.jpg', 'https://phimimg.com/upload/vod/20231219-1/13254e00e90a0c765ad766340d058eba.jpg', '<p>Với sự giúp đỡ của Meme Oshino, chuyên gia về sự hiện thân, Koyomi đánh bại ba thợ săn ma cà rồng mạnh mẽ: Dramaturgy, Episode and Guillotinecutter. Koyomi lấy lại tất cả các chi của Kiss-Shot-Acerola-Orion-Heart-Underblade để trở thành một con người một lần nữa. Nhưng, khi anh trở về Kiss-Shot, cô tiết lộ cho anh ta sự thật lạnh lùng về ý nghĩa của một ma cà rồng - một sinh vật của đêm. Không thể lấy lại những gì anh ta đã làm, Koyomi cảm thấy không có gì tiếc nuối và chỉ có thể phủ nhận số phận đáng sợ của mình. Trong khi Koyomi đang phải vật lộn để đối mặt với thực tế, người bạn Tsubasa Hanekawa đến với anh ta với một kế hoạch nào đó...</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Takahiro Sakurai","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
