INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giu-lay-hanh-phuc', 'Giữ Lấy Hạnh Phúc', 'Million Happy Nows', 'https://phimimg.com/upload/vod/20231219-1/4ca99972ba38bfa44f995d61263b5255.jpg', 'https://phimimg.com/upload/vod/20231219-1/6a6c9972d1bf14ce82f67bf79b92c8fa.jpg', '<p>Giữ Lấy Hạnh Phúc - Million Happy Nows ghi lại sự thay đổi từ mối quan hệ cộng sự giữa Lainey Allen - một nữ diễn viên kỳ cựu và Eva Morales - một nhà báo kiêm người quản lý, khi họ vật lộn để đối phó với căn bệnh Alzheimer khởi phát sớm của Lainey. Lainey cảm thấy khó chấp nhận khi tương lai của mình hoàn thoàn phụ thuộc vào sự hỗ trợ giúp đỡ duy nhất của Eva - người phụ nữ từng khiến cô sợ hãi, bây giờ sẽ chăm sóc và lại trở thành mọi thứ đối với cô.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"DENDRIE TAYLOR","avatar":""},{"name":"Crystal Chappel","avatar":""},{"name":"Jessica Lecia","avatar":""},{"name":"Robert Grant","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
