INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tuong-do-thi', 'Giả Tưởng Đô Thị', 'Fabricated City', 'https://phimimg.com/upload/vod/20231219-1/204a3a04755b09319a91cb757cbad18a.jpg', 'https://phimimg.com/upload/vod/20231219-1/498f494b459886bd3e468426b7f716c5.jpg', '<p>“Thành&nbsp;phố&nbsp;bị&nbsp;thao&nbsp;túng”&nbsp;là&nbsp;bộ&nbsp;phim&nbsp;điện&nbsp;ảnh&nbsp;hành&nbsp;động&nbsp;tội&nbsp;phạm,&nbsp;kể&nbsp;về&nbsp;một&nbsp;thanh&nbsp;niên&nbsp;bị&nbsp;vu&nbsp;oan&nbsp;tội&nbsp;giết&nbsp;người&nbsp;từng&nbsp;bước&nbsp;vạch&nbsp;trần&nbsp;sự&nbsp;thật&nbsp;bị&nbsp;ngụy&nbsp;tạo.</p>', 'Full', 1, 'single', 'completed', 5, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Chang Wook","avatar":""},{"name":"Shen En Jing","avatar":""},{"name":"Ma Dong Xi","avatar":""},{"name":"Jeong-se Oh","avatar":""},{"name":"Sang-ho Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324405);
