INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-biet-giam-99', 'Khu Biệt Giam 99', 'Brawl In Cell Block 99', 'https://phimimg.com/upload/vod/20231219-1/004aa42849fbe0a609bb4915cb1d06c2.jpg', 'https://phimimg.com/upload/vod/20231219-1/774343dff09119185d5124abace5ad68.jpg', '<p>Phim Khu Biệt Giam 99 - Brawl in Cell Block 99 2017: kể về một cựu võ sĩ mất công việc làm thợ cơ khí tự động, và cuộc sống hôn nhân của anh gặp khó khăn. Tại thời điểm đó, anh cảm thấy mình không còn lựa chọn nào tốt hơn ngoài làm việc vận chuyển ma túy. Anh nhanh chóng gặp phải những cuộc đụng độ giữa cảnh sát và các đồng minh tàn nhẫn của mình. Sau đó, Bradley bị thương nặng và bị bỏ tù, nơi mà những kẻ thù của anh ép buộc anh phải bạo lực để biến nơi này thành một chiến trường tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Don Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
