INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-hop-ma-quai', 'Chiếc Hộp Ma Quái', 'Wish Upon', 'https://phimimg.com/upload/vod/20231230-1/40a7aac6eb3da5ed2d1c2b66074d09b1.jpg', 'https://phimimg.com/upload/vod/20231230-1/9bcf17209ff37794c326d765043cec41.jpg', '<p>Phim Chiếc Hộp Ma Quái - Wish Upon 2017: Cuộc sống của Claire được định nghĩa bằng hai từ bất hạnh. Mẹ treo cổ tự vẫn ngay trước mặt khiến cô bé chịu ám ảnh ngay từ khi còn nhỏ. Khi lớn lên, cuộc sống của Claire cũng không khá hơn là bao khi luôn bị bạn bè trong trường bắt nạt. Tình cờ nhặt được một hộp nhạc thần kỳ, Claire được ban cho bảy điều ước. Đứng trước món quà từ trên trời rơi xuống này, cô bé đã không thể kiềm chế được bản thân. Đầu tiên, Claire ước cho cô nàng đã đối xử tồi tệ với mình bị thối rửa từ từ.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Joey King","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Sherilyn Fenn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
