INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('saw-legacy', 'Saw: Legacy', 'Saw: Legacy', 'https://phimimg.com/upload/vod/20231227-1/36159739f3da6831d441a1f2d6120ab6.jpg', 'https://phimimg.com/upload/vod/20231227-1/6ff24a3db65011fded406935eb7a8d7d.jpg', '<p>Nó đã được hơn một thập kỷ kể từ khi Jigsaw qua đời. Tuy nhiên, sau một loạt các vụ giết người mới xảy ra, cảnh sát thấy mình đang đuổi theo sát thủ ghép hình ban đầu - John Kramer. John Kramer có thể còn sống hay là một kẻ giết người khác ngoài động cơ khác nhau?</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
