INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dream', 'BanG Dream!', 'BanG Dream!', 'https://phimimg.com/upload/vod/20231219-1/4480cf9c83b671e8e21d9dc68e38ca81.jpg', 'https://phimimg.com/upload/vod/20231219-1/6a14bb015d01d6d7d7ff9ea7f0007ba0.jpg', '<p>Kasumi, người luôn tìm kiếm thứ gì đó giống như giai điệu của vì sao, một cảm giác như khi nhìn lên những vì sao trên bầu trời đêm thời nhỏ. Sau khi vào trường cấp 3, cô đã tìm thấy một cây đàn guitar với hình dáng giống như ngôi sao, cô thấy lòng mình lần đầu tiên rộn rã như vậy, sau một thời gian dài tâm hồn đã khép kia nay đã mở lại. Tương tự như cô, cùng với 4 cô gái khác đang tìm địa nơi tỏa sáng, sẽ sống nơi đây!</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 14, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324405);
