INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-4', '100 Người Thử Nghiệm (Phần 4)', 'The 100 (Season 4)', 'https://phimimg.com/upload/vod/20231219-1/a927579be7d6249ef72c60f6b5e81adf.jpg', 'https://phimimg.com/upload/vod/20231219-1/2a3c0a9710a83d38b0a2342e958d26c3.jpg', '<p>Những nhà máy hạt nhân liên tục rò rỉ khiến những cơn mưa màu đen rơi xuống từ trên cao và những vùng đất dần mất đi sự sống. Thứ duy nhất có thể giải thoát loài người khỏi tận thế chính là Thành Phố Ánh Sáng. Nhưng Clarke không muốn như vậy, cô gạt cần phá hủy Thành Phố Ánh Sáng và quyết định đối đầu với thiên nhiên. Trong cuộc chiến không cân sức này, liệu bao nhiêu người sẽ tìm được lối thoát?</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Morley","avatar":""},{"name":"Eliza Taylor","avatar":""},{"name":"Marie Avgeropoulos","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
