INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pork-pie', 'Pork Pie', 'Pork Pie', 'https://phimimg.com/upload/vod/20231215-1/7da3efd9ca0ab1cac57ce9850bd9f5ee.jpg', 'https://phimimg.com/upload/vod/20231215-1/6a63f27af9d3d35fddd628995b56eaf6.jpg', '<p>Pigle Pie theo dõi sự trốn thoát của một bộ ba vi phạm tình cờ khi họ đi theo chiều dài của New Zealand trong một sự phù hợp với màu vàng nhỏ, phản đối và đuổi theo tình yêu bị mất, với một cảnh sát và một phương tiện truyền thông nóng bỏng trong việc theo đuổi của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324405);
