INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-si-megan-leavey', 'Hạ Sĩ Megan Leavey', 'Megan Leavey', 'https://phimimg.com/upload/vod/20231215-1/7c6e67dc2d2bda011ce533ca3bdf49ad.jpg', 'https://phimimg.com/upload/vod/20231215-1/cb03334376bcd6cad761c98c3c1cfe80.jpg', '<p>Phim Hạ Sĩ Megan Leavey - Megan Leavey 2017: dựa trên một câu chuyện có thực của một cô lính hải quân trẻ là Megan Leavey, người có kỉ luật độc lập cùng với chú chó nghiệp vụ Rex đã cứu được rất nhiều mạng sống trong suốt thời gian đóng quân ở Iraq. Leavey được phân công cùng với một chú chó đặc biệt hung dữ, tên Rex, và được trao cơ hội huấn luyện chú tại trại huấn luyện Camp Pendleton của Thủy quân lục chiến Hoa Kỳ. Trong suốt khóa huấn luyện của họ, Megan và Rex phải tham gia các nhiệm vụ nguy hiểm nhất, thường xuyên tìm kiếm các khu vực có thể có chất nổ trước khi quân đội đến. Họ đã hoàn thành hơn 100 nhiệm vụ cho đến khi một vụ thiết bị nổ ngẫu nhiên IED làm họ bị thương, đưa số phận của họ vào nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Mara","avatar":""},{"name":"Ramón Rodríguez","avatar":""},{"name":"Tom Felton","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324405);
