INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sau-do-phep-mau-tren-nui-tuyet', 'Âm Sáu Độ: Phép Màu Trên Núi Tuyết', '6 Below: Miracle On The Mountain', 'https://phimimg.com/upload/vod/20231219-1/e1e60e141e3144aef6f813a38b8169d9.jpg', 'https://phimimg.com/upload/vod/20231219-1/6e854fc28cd8b086c69ab6808fecd1c0.jpg', '<p>Một vận động viên trượt tuyết tìm kiếm cảm giác mạnh bị lạc trong một cơn bão mùa đông lớn ở vùng quê hẻo lánh của High Sierras, nơi anh ta bị đẩy đến giới hạn chịu đựng của con người và buộc phải chiến đấu với những con quỷ của chính mình khi anh ta chiến đấu để sinh tồn....</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Sarah Dumont","avatar":""},{"name":"Kale Culley","avatar":""},{"name":"Jason Cottle","avatar":""},{"name":"Austin R. Grant","avatar":""},{"name":"Nathan Stevens","avatar":""},{"name":"Marty McSorely","avatar":""},{"name":"Sean Pilz","avatar":""},{"name":"David H. Stevens","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324405);
