INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-vong-tu-tuong-da', 'Tiếng Vọng Từ Tường Đá', 'Voice From The Stone', 'https://phimimg.com/upload/vod/20231219-1/b5c25c20fa89d4737ff0314846cd788e.jpg', 'https://phimimg.com/upload/vod/20231219-1/17ee400744b6c5a435e5c45f5d5fc9ce.jpg', '<p>Phim Tiếng Vọng Từ Tường Đá - Voice From The Stone 2017: lấy bối cảnh trong một tòa lâu đài hoang vắng ở Tuscany (Ý) vào những năm 1950. Cô y tá Verena được thuê đến đây để chăm sóc Jakob - cậu bé đột ngột trở nên câm lặng sau khi mẹ cậu mất vì bệnh nặng. Verena càng cố gắng để Jakob có thể nói lại thì càng ngày, cô càng dấn vào sâu hơn những bí mật đang bị che giấu trong tòa lâu đài. Cô đã không thể ngờ rằng có một thế lực tà ác đang cố gắng giăng bẫy mình.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emilia Clarke","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Caterina Murino","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
