INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-2017', 'Ác Mộng', 'Before I Wake', 'https://phimimg.com/upload/vod/20231215-1/d2e3ac85257266c880ca7b27f6ebdbd2.jpg', 'https://phimimg.com/upload/vod/20231215-1/d731306e3f467f693accedc6d12b9d1c.jpg', '<p>Câu chuyện bắt đầu khi cặp vợ chồng Mark và Jessie quyết định nhận nuôi cậu bé Cody sau cái chết vì tai nạn của con trai. Ngôi nhà buồn bã bừng sáng trở lại bởi Cody ngoan ngoãn bên cạnh người cha ấm áp và người mẹ dịu dàng. Cùng với sự xuất hiện của cậu bé, Mark và Jessie bắt đầu nhìn thấy những điều kỳ lạ, một thế giới thần tiên hiển hiện trước mắt họ mỗi đêm. Ngày qua ngày, cả hai nhận ra rằng khi Cody ngủ, giấc mơ của cậu trở thành hiện thực. Nhờ giấc mơ của Cody, họ gặp lại được cậu con trai đã mất, nỗi đau quá khứ tưởng chừng sắp được chữa lành, mọi thứ đang rất vui vẻ. Thế nhưng, cuộc đời đâu phải chỉ toàn mộng đẹp, Cody rồi cũng có lúc… gặp ác mộng. Liệu tính mạng của đôi vợ chồng trẻ sẽ ra sao khi nỗi sợ hãi khủng khiếp của cậu bé 8 tuổi trở thành sự thật ngoài đời? Xem thêm tại: https://www.galaxycine.vn/binh-luan-phim/before-i-wake-khi-noi-so-hai-tre-con-tro-thanh-su-kinh-hoang-cua-nguoi-lon</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Kate Bosworth","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
