INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-vo-ky', 'Hàn Võ Ký', 'Cambrian Period', 'https://phimimg.com/upload/vod/20231219-1/09032afb7a1dfac39a529f18e57ccb03.jpg', 'https://phimimg.com/upload/vod/20231219-1/fa175fbbeb55254cc1f48e515b2bb46d.jpg', '<p>Phim Hàn Võ Ký 2017 nói về một cô gái thiện lương lạc quan, ma xui quỷ khiến đi lạc vào một cuộc hành trình mộng ảo trên một hòn đảo hoang, và xảy ra những chuyện dở khóc dỏ cười với một mỹ thiếu niên sát thủ có thân thế bí ẩn, cùng một cảnh sát đẹp trai nắm giữ trong tay bí mật kinh người, vượt qua tam giác tình yêu ngược luyến của tuổi tác và không gian, cũng bởi vì điều này mà hãm sâu vào trò chơi quyền lực đầy rẫy tiền tài, dục vọng thậm chí là sự chết chóc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Vũ Đồng","avatar":""},{"name":"Hạ Quân Tường","avatar":""},{"name":"Hầu Minh Hạo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
