INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-thu-3', 'Kẻ Sát Nhân Thứ 3', 'The Third Murder', 'https://phimimg.com/upload/vod/20231214-1/d238836bf4cb5b3d1ce727827a5ad9d4.jpg', 'https://phimimg.com/upload/vod/20231214-1/64e23909817fed4a72ba963197b2bdeb.jpg', '<p>Câu chuyện phim xoay quanh quá trình bào chữa của Shigemori cho Misumi - một kẻ đang bị khép tội giết người và đã ra đầu thú. Trong quá trình điều tra Shigemori dần phát hiện ra những bí mật khủng khiếp về vụ án, khiến anh trở nên hồ nghi về việc liệu khách hàng của mình có thật sự đã gây tội hay không.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masaharu Fukuyama","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Suzu Hirose","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
