INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-khoang-sao-troi-kia-khoang-bien', 'Đây Khoảng Sao Trời Kia Khoảng Biển', 'The Starry Night The Starry Sea', 'https://phimimg.com/upload/vod/20231219-1/d7d9c351220b841eced2de873b64e4e6.jpg', 'https://phimimg.com/upload/vod/20231219-1/e123acc6bb767ff27feb1c121ee0144b.jpg', '<p>Phim Đây Khoảng Sao Trời Kia Khoảng Biển 2017 kể về câu chuyện tình đẹp như mơ của Thẩm La (Quách Bích Đình) và chàng tiên cá Ngô Cứ Lam (Phùng Thiệu Phong) được kể lại rõ nét trong đoạn video. Tác phẩm cải biên từ tiểu thuyết cùng tên của tác giả Đồng Hoa, do Tiễn Tinh Tinh và Từ Tử Nguyên biên kịch.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Quách Bích Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
