INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-ghet-van-yeu', 'Dù Ghét Vẫn Yêu', 'Love Returns', 'https://phimimg.com/upload/vod/20231219-1/3b56533d11e29797277eca62c64e91e0.jpg', 'https://phimimg.com/upload/vod/20231219-1/50f988e2e079576335c90dc3178b8700.jpg', '<p>Dù Ghét Vẫn Yêu - Love Returns kể về câu chuyện của Eun Jo. Cô đã bị mất tất cả sau khi bố cô đột ngột qua đời và mẹ kế biến mất. Cô quyết tâm bắt đầu lại cuộc sống của mình và dần dần hiểu được tình yêu gia đình là gì và ý nghĩa đích thực của cuộc sống. Khi theo dõi bộ phim, khán giả sẽ có góc nhìn mới mẻ về mối quan hệ trong gia đình khi mà con cái thì coi bố mẹ như kẻ thù còn bố mẹ thì coi con cái như mối phiền toái của mình. Phim cũng nói lên tầm quan trong của tình yêu và tình cảm gia đình, chứ không phải là huyết thống hay pháp luật.</p>', 'Hoàn Tất (120/120)', 120, 'series', 'completed', 10, 2017, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Hye Rin","avatar":""},{"name":"Pyo Ye Jin","avatar":""},{"name":"Lee Dong Ha","avatar":""},{"name":"Lee Sung Yeol","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324405);
