INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-endless', 'The Endless', 'The Endless', 'https://phimimg.com/upload/vod/20231213-1/a28158d20a664b8f8d7bdee8452ebc9c.jpg', 'https://phimimg.com/upload/vod/20231213-1/96ef23089908f5e5127e4efa6b44bb32.jpg', '<p>Thriller uốn cong tâm trí này theo dõi hai anh em nhận được một thông điệp video khó hiểu truyền cảm hứng cho họ để xem lại giáo phái Death Ufo mà họ đã thoát khỏi một thập kỷ trước đó. Hy vọng tìm thấy sự đóng cửa mà họ không thể là những chàng trai trẻ, họ bị buộc phải xem xét lại niềm tin của giáo phái khi đối mặt với những hiện tượng không thể giải thích được bao quanh trại. Khi các thành viên chuẩn bị cho sự kiện diễn ra của một sự kiện bí ẩn, anh em chạy đua để làm sáng tỏ sự thật dường như không thể trước khi cuộc sống của họ trở nên vướng víu vĩnh viễn với sự sùng bái.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
