INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-tinh-yeu-2017', 'Thị Trấn Tình Yêu', 'The Bachelors', 'https://phimimg.com/upload/vod/20240111-1/1f2d735a388dcf4dd2343b7076ff3281.jpg', 'https://phimimg.com/upload/vod/20240111-1/885d0a3f3561d5b1dc65e9ae29aedbc3.jpg', '<p>Sau cái chết của người vợ, Bill Ponder (Simmons) và đứa con trai 17 tuổi Wes rời khỏi thị trấn nhỏ của họ vào thành phố lớn để bắt đầu một cuộc sống mới. Khi họ bắt đầu thích nghi với cuộc sống mới tại nơi đây và tìm cách chữa lành vết thương qua từng ngày, cả hai đều tìm được cho riêng mình chút vui thú trong tình yêu mới. Wes gặp Lacy, một cô gái sống nội tâm nhưng rất quyết liệy với tính cách bí ẩn làm Wes say đắm, và Bill gặp Carine, một giáo viên hiền hậu và thanh lịch. Những trái tim đau đớn trong quá khứ của họ bắt đầu tìm được nhịp được nhịp đập mới. Khi đứng trước thử thách về mối quan hệ giữa họ, Bill và Wes đều chia ly và tái hợp với nhau trong khi khám phá ra bản chất thực sự của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"J.K. Simmons","avatar":""},{"name":"Josh Wiggins","avatar":""},{"name":"Julie Delpy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
