INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cho-ta-bao-lan-doi-muoi', 'Đời Cho Ta Bao Lần Đôi Mươi', 'The Gift Of Youth', 'https://phimimg.com/upload/vod/20231011-1/47bcb572da88fd8450f946039c4f186b.jpg', 'https://phimimg.com/upload/vod/20231011-1/f505c316ab58e81021f0f31e40b2451a.jpg', '<p>Mỹ Phương (Quỳnh Anh Shyn), Lan Anh (Băng Di), Bích Châu (Tú Vi) và Thanh Tân (Văn Anh) là nhóm bạn thân chơi với nhau từ nhỏ. Mỗi đứa một gia cảnh, một thế mạnh và những điểm yếu riêng biệt. Trong đó nổi bật nhất chính là Mỹ Phương, bởi vì cô xấu nhất và hậu đậu nhất, nhưng lại cực kì mê trai. Mỗi lần Mỹ Phương muốn tỏ tình với ai là ba người còn lại đều bày cách hộ. Nhưng mười lần như một, Mỹ Phương đều thất bại ê chề.&nbsp; Trong lần tỏ tình thứ 99 với người sếp Hoàng Tú (Trần Trung), Mỹ Phương còn tuột luôn quần của anh ta, dẫn đến bị mất việc trong ê chề, nhục nhã. Quá túng quẫn nhưng chẳng biết làm gì khác, Mỹ Phương chỉ biết trách đám bạn hay xúi dại và trách luôn ông trời sao số mình quá đen. Kết quả, trời đánh cô một phát đen thui, chấn thương khuôn mặt, phải phẫu thuật thẩm mĩ và còn bị mất trí nhớ tạm thời khi tỉnh lại. Từ đó, cuộc đời Mỹ Phương cũng sang trang, tình bạn của cô với ba người còn lại cũng dần thay đổi.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Văn Anh","avatar":""},{"name":"Quỳnh Anh Shyn","avatar":""},{"name":"Băng Di","avatar":""},{"name":"Tú Vi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324405);
