INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-man-dem', 'Đột Kích Màn Đêm', 'Sleepless', 'https://phimimg.com/upload/vod/20231213-1/4c3bae49c8ca5d5f87e8cd04e631aaf0.jpg', 'https://phimimg.com/upload/vod/20231213-1/54ee4be355e4b46ec6172b2e07d546c6.jpg', '<p>Spleeless kể về Vincent Downs – một viên cảnh sát ở New York. &nbsp;Vincent bị lão chủ sòng bài Stan Rubino bắt cóc con trai vì đã phá vụ vận chuyển ma túy của hắn và đồng nghiệp. Cùng lúc đó, anh lại bị cả thanh tra Sở nội vụ Jen Bryant và trùm ma túy Rob Novak truy đuổi. Vincent phải dùng những kỹ năng của một cảnh sát để cứu lấy bản thân và con trai.&nbsp;Bộ phim hành động, tội phạm, ly kỳ này là tác phẩm mới nhất của ngôi sao Jamie Foxx, do Baran bo Odar cầm trịch đạo diễn và Andrea Berloff biên kịch.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Dermot Mulroney","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
