INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-yoga', 'Kung Fu Yoga', 'Kung Fu Yoga', 'https://phimimg.com/upload/vod/20231213-1/c66ffb987b2b701f2656d16ae7c764e2.jpg', 'https://phimimg.com/upload/vod/20231213-1/a32d4f7afe5b7b6bb33309e84e382802.jpg', '<p>Phim Kung Fu Yoga 2017: Jack là một giáo sư khảo cổ người Trung Quốc. Anh cộng tác cùng nữ giáo sư xinh đẹp người Ấn Độ Ashmita và trợ lý Kyra để tìm kiếm kho báu Magadha bị mất tích. Trong động băng Tibetan, họ phát hiện phần còn sót lại của một đạo quân hoàng gia bị chôn vùi cùng với khó báu và bị phục kích bởi Randall- một hậu duệ của thủ lĩnh phản quân. Khi thoát ra được, họ đến Dubai để tìm viên kim cương trong hang động đang bị đấu giá. Sau nhiều biến cố, Jack và những người bạn tìm đến một ngôi chùa trên núi, dùng viên kim cương để mở kho báu thật sự.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thành Long","avatar":""},{"name":"Lý Trị Đình","avatar":""},{"name":"Trương Nghệ Hưng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324405);
