INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhac-phim-cuoc-doi', 'Nhạc Phim Cuộc Đời', 'Soundtrack', 'https://phimimg.com/upload/vod/20231212-1/fd194e04ae1bf2fd80c11a18ba1d0fb3.jpg', 'https://phimimg.com/upload/vod/20231212-1/e608b7c33e0db72e01c0cd5bb57c1cbe.jpg', '<p>Cris (Selton Mello), một nghệ sĩ trẻ đầy tham vọng tìm kiếm vị trí của mình trong thế giới nghệ thuật, được chính phủ Brazil cho phép dành một tháng tại một trạm nghiên cứu bị cô lập giữa băng. Mục tiêu của anh là thực hiện một cuộc triển lãm pha trộn, theo cách nguyên bản, nhiếp ảnh và âm nhạc. Cris sẽ đối đầu với các giá trị và khái niệm của mình với các nhà nghiên cứu và tìm ra Trái đất theo cách chưa từng thấy trước đây. Cú sốc này sẽ dẫn đến sự tiến hóa và biến đổi của nghệ sĩ trẻ này, người thay đổi câu chuyện của mình mãi mãi.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Ralph Ineson","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"Thomas Chaahing","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
