INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-benh-nang', 'Cơn Bệnh Nặng', 'The Big Sick', 'https://phimimg.com/upload/vod/20231211-1/f57560b66acb43aa267788fad5d78cdd.jpg', 'https://phimimg.com/upload/vod/20231211-1/414da952928d12b4b23a346483a964d2.jpg', '<p>The Big Sick là bộ phim được đạo diễn bởi Micheal Showalter (Hello My Name is Doris). Phim dựa trên câu chuyện cuộc đời của diễn viên chính kiêm biên kịch Kumail Nanjiani và người hiện là vợ anh Emily Gordon. Gia đình Hồi giáo gốc Pakistan của Kumail không hài lòng về mối quan hệ giữa anh và Emily, vốn là một người Mỹ. Tình cảnh của 2 người trở nên éo le hơn bao giờ hết khi Emily bị hành hạ bởi một căn bệnh bí hiểm trong khi Kumail lãnh trách nhiệm đối đầu với phụ huynh của cô.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kumail Nanjiani","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Holly Hunter","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
