INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-ly-toi-pham', 'Tâm Lý Tội Phạm', 'Guilty Of Mind', 'https://phimimg.com/upload/vod/20240108-1/d24cf0872c747230405a74d03087c2a6.jpg', 'https://phimimg.com/upload/vod/20240108-1/508b9e3b78ffd8b9215b831b56d55ec7.jpg', '<p>Phim Tâm Lý Tội Phạm (Bản Điện Ảnh) được chuyển thể từ tiểu thuyết Tâm lý tội phạm - Bức họa (Đề thi đẫm máu) của tác giả Lôi Mễ. Lý Dịch Phong vào vai Phương Mộc, Liêu Phàm trong vai cảnh sát Thái Vĩ. Phim xoay quanh việc nhân vật Phương Mộc vướng vào một vụ án giết người vô cùng dã man, xảy ra tại chính ngôi trường mà cậu theo học.Cho đến tận vụ án thứ năm của chuỗi giết người liên hoàn ấy, Phương Mộc mới kinh hoàng phát hiện ra rằng, mục tiêu mà tên sát nhân muốn hướng đến chính là mình. Một tên sát nhân tàn bạo biến thái, một đề thi tràn ngập máu tanh không thể không phá giải, Phương Mộc đành cùng Thái Vĩ lao vào cuộc thi, lần theo manh mối, quyết tìm ra thủ phạm giết người.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Dịch Phong","avatar":""},{"name":"Lý Thuần","avatar":""},{"name":"Liêu Phàm","avatar":""},{"name":"Vạn Thiến","avatar":""},{"name":"Trương Quốc Trụ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324405);
