INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dark-net-s2', 'Dark Net S2', 'Dark Net S2', 'https://phimimg.com/upload/vod/20231219-1/433c13931e6b087cd437518abd17d2b1.jpg', 'https://phimimg.com/upload/vod/20231219-1/53fd5052a38667445e6067a5a237ca58.jpg', '<p>Đây là nội dung catch-up kênh BlueAnt Entertainment, sẽ hết hạn sau 7 ngày, quý khách cần active gói VIP để xem.Dark Net là một series phim tài liệu của Mỹ do Mati Kochavi sản xuất. Phim khai thác mảng tối của thế giới công nghệ, các chủ đề nóng của nhân loại như virus trên mạng, tấn công chiếm quyền điều khiển các hệ thống bằng internet, các công cụ quay lén và chia sẻ phim người lớn...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324405);
