INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-dinh-phan-2', 'Chuyện Gia Đình (Phần 2)', 'F Is For Family (Season 2)', 'https://phimimg.com/upload/vod/20231219-1/2abe7c1196fa8e2f9850251ba5f12eda.jpg', 'https://phimimg.com/upload/vod/20231219-1/5e6dd85a5aba9609982a4503799696a5.jpg', '<p>Khi Frank và Sue vật lộn với vấn đề tiền bạc, đàn con nhà Murphy đối mặt với những trò trêu chọc mới và những nghi lễ khó hiểu.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Burr","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Debi Derryberry","avatar":""},{"name":"Haley Reinhart","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Mo Collins","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Phil Hendrie","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Joe Pera","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324405);
