INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-em-da-den', 'Vì Em Đã Đến', 'Because Of You', 'https://phimimg.com/upload/vod/20231219-1/6875229c63090da59206958a78ed7c5c.jpg', 'https://phimimg.com/upload/vod/20231219-1/115c431a938c657844a1c9c51daf0452.jpg', '<p>Trương Quả Quả lớn lên ở quán vằn thắn Đồng Lí, là một cô bé bưng bê đồ ăn ở thị trấn này Quả Quả mặc dù không có học lực cao, nhưng cô ấy nhiệt tình, tính cách thật lòng nên có được sự yêu thích của hàng xóm. Điều mà mọi người không biết là Quả Quả là con gái của chủ xưởng thêu nổi tiếng của Kim Lũ Các , vì một sự cố bất ngờ trong quá khứ mà vô tình lại trưởng thành ở Đồng Lí và được Vương Ái Ngoc chủ quán Vằn Thắn nhận nuôi. Quả Quả có một tài năng thiên phú độc đáo ở việc thêu vá, mặc dù luôn bị mẹ nuôi là Vương Ái Ngọc phản đối. Nhưng với sự kiên trì và cố gắng, cô được sự chấp nhận của mọi người, có cơ hội vào học ở Kim Lũ Các. Vũ Hân là cô gái giỏi giang xinh đẹp nhưng cũng nhiều mưu mô, ích kỷ có con với người mình yêu nhưng vì anh chồng bị phá sản mà cô ta nhất quyết đòi li hôn, bỏ mặc con gái cho mẹ đẻ và em gái nuôi… Vũ Hân cũng rất thành thục việc thêu vá, nhưng trong lòng luôn có tham vọng được vào Kim Lũ Các và muốn giành chức trưởng thêu tại đây.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 10, 2017, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Đặng Luân","avatar":""},{"name":"Ngô Ưu","avatar":""},{"name":"Tôn Di","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324405);
