INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-khong-gian', 'Cảnh Sát Không Gian', 'ElDLIVE Space Police', 'https://phimimg.com/upload/vod/20231219-1/d7c23a26f8d641705113ccd4dd9f5e53.jpg', 'https://phimimg.com/upload/vod/20231219-1/5b1b0e1fd7cb9f486dced3b5a3a9b4b2.jpg', '<p>Kokonose Chuta lẩm bẩm không có nhiều bạn bè, mà thực ra, ngoại trừ người thân thì người duy nhất cậu nói chuyện là giọng nói trong đầu cậu. Dần dần thì cậu cũng nhận ra không phải cậu bị điên, chỉ là có một người ngoài hành tinh sống trong cơ thể cậu. Đến khi cậu phát hiện ra sự tồn tại của sinh vật này, cuộc sống trầm lặng của cậu đảo lộn hoàn toàn và phải tham gia vào cuộc chiến giữa nhưng người ngoài hành tinh khác.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Rie Kugimiya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
