INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-trung-ran', 'Quý Ông Trứng Rán', 'Mr.Omelet', 'https://phimimg.com/upload/vod/20240104-1/dd2659bae492caaf3fd76017ddd2868e.jpg', 'https://phimimg.com/upload/vod/20240104-1/0ca2af22ef51558f8c38f40539df038c.jpg', '<p>Bộ phim Quý Ông Trứng Rán - Mr.Omelet kể về cuộc sống và ước mơ của Mali. Mali điều hành một quầy thực phẩm trong một khu chợ trước một trường đại học. Anh có rất nhiều khách hàng và một số trong số họ trở thành bạn của anh ấy. Mặc dù không bình thường khi một đầu bếp gian hàng thực phẩm trở thành bạn thân với khách hàng của mình, họ trở nên rất thân thiết và đi chơi cùng nhau bất cứ khi nào họ có thời gian. Mọi người luôn tự hỏi làm thế nào họ trở thành những người bạn tuyệt vời như vậy. Bởi vì sự trung thực, đạo đức làm việc và kỹ năng nấu nướng của anh ấy. Mali nổi tiếng với nhiều món trứng tráng và với sự hỗ trợ của bạn bè, anh ấy sẽ chứng minh rằng món trứng ốp la Thái có thể thống trị thế giới.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Agaradei Yod Champa","avatar":""},{"name":"Numchoke Thanatram","avatar":""},{"name":"Safe Fanny Avanik","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
