INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cuoi-cung', 'Cuộc Chiến Cuối Cùng', 'Bitter Harvest', 'https://phimimg.com/upload/vod/20231211-1/3ad19ebd021d090d3e84e3a93cc33363.jpg', 'https://phimimg.com/upload/vod/20231211-1/d0f4428b4dd6701ecfe539770e79db8e.jpg', '<p>Lấy bối cảnh giữa hai cuộc Thế chiến và dựa trên các sự kiện lịch sử có thật, Bitter Harvest truyền tải câu chuyện chưa kể về Holodomor, nạn đói diệt chủng do bạo chúa Joseph Stalin gây ra. Bộ phim thể hiện một câu chuyện mạnh mẽ về tình yêu, danh dự, sự nổi loạn và sự sống còn vào thời điểm Ukraine buộc phải điều chỉnh theo tham vọng lãnh thổ khủng khiếp của Liên Xô đang phát triển.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Irons","avatar":""},{"name":"Samantha Barks","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Tamer Hassan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324405);
