INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-lien-hoan', 'Án Mạng Liên Hoàn', 'The Liquidator', 'https://phimimg.com/upload/vod/20231211-1/7a782f097678c4d697cf74bb42e42cb1.jpg', 'https://phimimg.com/upload/vod/20231211-1/9f9e154856b193208b5680bca9ac07ad.jpg', '<p>Một nhà tâm lý học tội phạm và một chuyên gia pháp y làm việc cùng nhau để truy tìm một kẻ giết người hàng loạt nhắm vào những người đã được tha bổng vì những tội đáng chú ý và sử dụng tội lỗi của họ làm phương thức hoạt động của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Liu Shishi","avatar":""},{"name":"Karena Lam","avatar":""},{"name":"He Hongshan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
