INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-den', 'Chiến Dịch Đen', 'China Salesman', 'https://phimimg.com/upload/vod/20240102-1/3a6e8cac843d83bf94a9c7c0f468c801.jpg', 'https://phimimg.com/upload/vod/20240102-1/8e7e84fc2df205cb9633c26921a0d183.jpg', '<p>Yan Jian, một kỹ sư CNTT trẻ người Trung Quốc tình nguyện đến Bắc Phi và giúp công ty anh làm việc giành chiến thắng trong một cuộc thi. Người chiến thắng có thể sở hữu quyền kiểm soát thông tin liên lạc giữa phía nam và phía bắc. Điệp viên người Pháp Michael làm việc cho phương Tây. Ông chủ của anh ta ra lệnh cho anh ta đến Bắc Phi và giành chiến thắng trong cuộc thi, và họ có thể kiểm soát nguồn tài nguyên khoáng sản to lớn của Châu Phi. Anh ta đã thuê người lính đánh thuê giỏi nhất ở Châu Phi tên là Lauder và cựu tướng Kabbah để giúp đỡ anh ta. Yan đã phát hiện ra âm mưu của họ, anh là người duy nhất có thể ngăn chặn họ.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mike Tyson","avatar":""},{"name":"Steven Seagal","avatar":""},{"name":"Eriq Ebouaney","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324405);
