INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-kim-thuat-su', 'Giả Kim Thuật Sư', 'FullMetal Alchemist', 'https://phimimg.com/upload/vod/20231210-1/6d3fed1263ec4b1624c915ed50e95c2d.jpg', 'https://phimimg.com/upload/vod/20231210-1/990ee12947be9139c3b3416ad80423db.jpg', '<p>Trong khi nhà giả kim Edward Elric tìm cách khôi phục cơ thể của người em trai AI, chính phủ quân sự và những con quái vật bí ẩn đang theo dõi sát sao.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yamada Ryosuke","avatar":""},{"name":"Honda Tsubasa","avatar":""},{"name":"Fujioka Dean","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324405);
