INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiem-hoa-rung-chet', 'Hiểm Họa Rừng Chết', 'Jungle', 'https://phimimg.com/upload/vod/20231210-1/2bbeecd67ea4ff29942a4051d0c8f4dd.jpg', 'https://phimimg.com/upload/vod/20231210-1/086f111cc2f7184f35359315c08707a8.jpg', '<p>Phim Hiểm Họa Rừng Chết - Jungle 2017: Một nhóm bạn gia nhập chuyến đi xuyên rừng già Bolivia để tìm kiếm một ngôi làng Ấn Độ cổ đại. Họ sớm nhận ra rằng rừng là một nơi khó sống sót hơn họ nghĩ. Phim dựa trên hồi ức có thực của Yossi Ghinsberg trong những năm đầu 1980. Khi đó, Yossi mới 22 tuổi đã cùng 2 người bạn tham gia một chuyến hành trình khám phá khu rừng rậm Bolivian, thế nhưng họ không thể ngờ được rằng gã hướng dẫn viên mà họ thuê là một gã khó lường và đầy âm mưu nguy hiểm. Bên cạnh đó, rừng rậm hoang sơ là một nơi khó sống, từ những cơn đói khát, cơ thể bị thối rửa, phải ăn thịt sống,… cho đến cuộc vật lộn một sống một còn với rắn hổ mang, báo gấm, những dòng nước chảy xiết chết người,... Liệu cả Yossi và nhóm bạn có toàn mạng trở về hay tất cả phải bỏ xác nơi rừng thiêng nước độc?</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Alex Russell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
