INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tam-than-2017', 'Kẻ Tâm Thần', 'The Slider', 'https://phimimg.com/upload/vod/20231231-1/515db48756fee5f2dddef33dc2883176.jpg', 'https://phimimg.com/upload/vod/20231231-1/13aeb0ff2239b3ebe30b254663523502.jpg', '<p>Michael làm việc như một người chăm sóc bệnh viện và anh ta sống với vợ Ester. Vợ của Milchel đã rơi vào tình trạng trầm cảm sau cái chết của con trai họ. Michael sẵn sàng làm bất cứ điều gì anh có thể để cứu Ester, thậm chí cả những điều mà tâm trí bình thường không bao giờ mơ ước.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Sizemore","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Daryl Hannah","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
