INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-2017', 'Giải Cứu', '6 Days', 'https://phimimg.com/upload/vod/20240111-1/83e017910199b6fa442ad39de7523059.jpg', 'https://phimimg.com/upload/vod/20240111-1/9f67778c6d07f026a771b3c0e82b0958.jpg', '<p>Phim Giải Cứu - 6 Days 2017: dựa trên một câu chuyện khủng bố có thật xảy ra vào ngày 30/04/1980 khi 6 tên khủng bố đã xâm nhập và bắt cóc 26 con tin tại đại sứ quán nước Iran đặt ở Prince’s Gate, Anh Quốc. Trong 6 ngày liên tục, cả thế giới đều hướng về sự kiện này khi được truyền thông đưa tin trực tiếp tại hiện trường.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Mark Strong","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Abbie Cornish","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
