INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-trai-giam', 'Băng Đảng Trại Giam', 'Shot Caller', 'https://phimimg.com/upload/vod/20231230-1/a5c03fae80140fbc38a94c098fe4fae8.jpg', 'https://phimimg.com/upload/vod/20231230-1/18a928b8e69f34a03b66d6fe287019c1.jpg', '<p>Phim Băng Đảng Trại Giam - Shot Caller 2017: Một người đàn ông của gia đình bị đưa đến nhà tù sau khi gây ra tai nạn giao thông chết người. Một thương gia thành công Jacob Harlon đã trở thành một tay găng tơ tàn nhẫn trong nhà tù. Khi bước vào ngôi nhà mới đầy tàn bạo, anh phải thích nghi với các quy tắc và nghi lễ truyền thống của những tù nhân ở đây tạo ra để có thể đảm bảo sự sống còn cho mình. Anh dần dần mất đi bản chất lương thiện và các mối quan hệ trong cuộc sống trước kia bao gồm cả vợ và con trai của mình. Sự kìm kẹp trong gia đình mới của anh và những nhóm tù nhân đã trải dài ra ngoài bức tường của nhà tù. Khi được giải thoát anh vẫn bị theo dõi bởi các cơ quan pháp luật và bị đe dọa bởi những tên tội phạm trong tù trước đây. Jacob đã phải dàn dựng lên một tội ác nguy hiểm cuối cùng. Quá trình tàn nhẫn để hoàn thành nghĩa vụ của mình cũng trở thành con đường dẫn đến sự hy sinh, trả thù và nhìn nhận lại bản thân.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Lake Bell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324405);
