INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-max-2-nguoi-hung-nha-trang', 'Chú Chó Max 2- Người Hùng Nhà Trắng', 'Max 2: White House Hero', 'https://phimimg.com/upload/vod/20231211-1/06ddad215e474ad271d234f8791390d7.jpg', 'https://phimimg.com/upload/vod/20231211-1/5d48e5e1504cc7d4f11d26926e601d5b.jpg', '<p>Max được giao cho Nhà Trắng trong khi Butch, chú chó mật vụ, đang nghỉ sinh. Anh gặp TJ, một cậu bé 12 tuổi, là con trai của Tổng thống. Do cha mình nổi tiếng, anh ấy đang cố gắng hết sức để hòa nhập và có một cuộc sống bình thường. Trong chuyến thăm cấp nhà nước của Tổng thống Nga và con gái của ông, Alexandra (Alex), TJ được yêu cầu đi cùng cô ấy trong thời gian họ ở lại. TJ kết bạn với Alex, nhưng khi họ gặp rắc rối, Max đã đến giải cứu!</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zane Austin","avatar":""},{"name":"Francesca Capaldi","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Andrew Kavadas","avatar":""},{"name":"Reese Alexander","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324405);
