INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-dau-tien', 'Cuộc Đời Đầu Tiên', 'Because This Is My First Life', 'https://phimimg.com/upload/vod/20231209-1/1971fe9450b53eafb747ad18ceb782d4.jpg', 'https://phimimg.com/upload/vod/20231209-1/2ba30dfe50f153e61e399957b59bb92e.jpg', '<p>\Đây là một bộ phim Hàn thuộc thể loại lãng mạn, hài hước, xoay quanh quan điểm sống về tình yêu, hôn nhân và sự nghiệp của giới trẻ hiện nay. Phim kể về một chàng trai độc thân, lựa chọn cuộc sống không hôn nhân, là chủ một căn hộ nhưng nợ nần chồng chất và một cô gái không nhà không cửa, từ bỏ chuyện hẹn hò, tập trung kiếm sống để không phải \cạp đất mà ăn\. Mọi chuyện bắt đầu khi cô gái chuyển đến sống trong căn hộ của chàng trai.\</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung So Min","avatar":""},{"name":"Min-ki Lee","avatar":""},{"name":"Esom","avatar":""},{"name":"Jin Min Xi","avatar":""},{"name":"Byung-eun Park","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324405);
