INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ngu-tro-ve', 'Bộ Ngũ Trở Về', 'Five Came Back', 'https://phimimg.com/upload/vod/20231209-1/b4446829f7fd83d0ded976f9aeb41ad6.jpg', 'https://phimimg.com/upload/vod/20231209-1/47bcda76271dad427cec0c277205fada.jpg', '<p>Năm đạo diễn có tiếng hiện nay kể câu chuyện về năm nhà làm phim Hollywood huyền thoại đã gia nhập quân đội để làm phim tài liệu về Thế Chiến II.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Spielberg","avatar":""},{"name":"Guillermo del Toro","avatar":""},{"name":"Lawrence Kasdan","avatar":""},{"name":"Francis Ford Coppola","avatar":""},{"name":"Paul Greengrass","avatar":""},{"name":"Meryl Streep","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324405);
