INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-cung-cua-toi', 'Thú Cưng Của Tôi', 'Kimi Wa Pet', 'https://phimimg.com/upload/vod/20231209-1/72263fb7ca8d11891782226ab439217b.jpg', 'https://phimimg.com/upload/vod/20231209-1/ac7de04a0d05a7a04503321a34254304.jpg', '<p>Một ngày nọ, Sumire phát hiện ra có một thùng các tông to ở trước cửa nhà, đã vậy còn có một chàng trai đang ngủ trong đó. Sumire đã đưa chàng trai này về nhà và biết được tên cậu là Goda Takeshi. Takeshi muốn ở lại nhà Sumire nhưng Sumire đưa ra yêu cầu cậu phải làm thú cưng của cô. Không ngờ Takeshi lại vui vẻ đồng ý. Cứ vậy Takeshi và Sumire đã bắt đầu cuộc sống chung của họ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Noriko Iriyama","avatar":""},{"name":"Jun Shison","avatar":""},{"name":"Terunosuke Takezai","avatar":""},{"name":"Yurina Yanagi","avatar":""},{"name":"Kayo Noro","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
