INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-bien-quang-cao-ngoai-troi-o-missouri', 'Ba Biển Quảng Cáo Ngoài Trời Ở Missouri', 'Three Billboards Outside Ebbing, Missouri', 'https://phimimg.com/upload/vod/20231209-1/71166c68c9fd01d86af012c94d89bac5.jpg', 'https://phimimg.com/upload/vod/20231209-1/36e0e658eb5755a5ec2f13575c5c30d1.jpg', '<p>Phim xoay quanh nhân vật Mildred – một phụ nữ đã ly thân do bị chồng đánh đập, sống cùng với một cậu con trai đang học trung học và có một đứa con gái bị cưỡng hiếp và giết chết vào 7 tháng trước. Suốt khoảng thời gian này, cảnh sát ở Ebbing vẫn không có câu trả lời cho cái chết của con gái bà vì vậy bà nghĩ rằng đã đến lúc mình phải làm gì đó trước khi vụ án của con bà đi vào quên lãng. Với tình yêu đối với đứa con đã mất cũng như sự bản lĩnh và thẳng thắn của mình, bà đã bán chiếc xe tải cũ để thuê in quảng cáo lên ba tấm biển đặt ở bên con đường vắng vẻ dẫn đến nhà bà nhằm tạo sức ép lên cảnh sát địa phương cũng như thu hút sự chú ý của dư luận.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frances McDormand","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Abbie Cornish","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324405);
