INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jagga-jasoos-hanh-trinh-dinh-menh', 'Jagga Jasoos: Hành Trình Định Mệnh', 'Jagga Jasoos', 'https://phimimg.com/upload/vod/20231209-1/f36113f43e9bb5564b214a14933dd11d.jpg', 'https://phimimg.com/upload/vod/20231209-1/e8da908b8d3c621d02f33839b14125bf.jpg', '<p>Bộ phim là câu chuyện về chàng trai đặc biệt và đáng yêu Jagga Jasoos với hành trình tìm lại ba của mình. Đó là cuộc hành trình thú vị, li kì và cả mạo hiểm cùng cô gái có số mệnh xui xẻo y hệt như ba của Jagga, cô nàng Shruti Sengupta. Cả hai đã cùng nhau trải qua một chặng đường dài từ Purulia và Ukhrul (Ấn Độ) đến Moombaka và Shundi ở Châu Phi, ngăn chặn các tay buôn bán vũ khí bất hợp pháp, trốn tránh gián điệp và tìm ba của Jagga. Bộ phim tựa như một câu chuyện của Disney vẽ lên một bức tranh đầy màu nhiệm về cái mà người ta gọi là định mệnh! “Khi 2 người có số phận gắn bó với nhau, họ sẽ gặp gỡ rồi cùng bước vào một vòng tròn màu đỏ. Và ở bên cạnh nhau mãi mãi!” Phải chăng vòng tròn đỏ đã xuất hiện và gắn bó những người xa lạ lại với nhau, để rồi dù có đi xa đến đâu, cuối cùng vẫn sẽ quay về bên nhau!?</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ranbir Kapoor","avatar":""},{"name":"Katrina Kaif","avatar":""},{"name":"Sayani Gupta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
