INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-cua-tham-vong', 'Cái Giá Của Tham Vọng', 'Money Flower', 'https://phimimg.com/upload/vod/20231207-1/6cd140397c374460e15dffd6831f14ed.jpg', 'https://phimimg.com/upload/vod/20231207-1/96dd41d67b0a22fe4290779dd191f604.jpg', '<p>Cái Giá Của Tham Vọng - Money Flower là một bức tranh sống động khắc họa rõ nét chuỗi bi kịch luẩn quẩn ở những con người ngạo mạn tin rằng họ có thể kiểm soát tất cả mọi thứ bằng tiền, mà không hề nhận ra rằng lòng tham sẽ che mờ sáng suốt. Kể cả việc lợi dụng người khác trở thành công cụ để đạt được mục đích cá nhân được xoay quanh âm mưu trả thù của luật sư Kang Pil Joo (Jang Hyuk) - người lớn lên ở trại trẻ mồ côi và hiện đang làm giám đốc điều hành một bộ phận của một công ty. Anh ta được công nhận nhờ sự thông minh và tinh thần làm việc gương mẫu. Một số đồng nghiệp ghen tị với anh ta. Trong khi đó, Na Mo Hyun (Park Se Young) - con gái của ủy viên quốc hội Na Gi-chul, là một nhà hoạt động môi trường và là một giáo viên khoa học tại trường trung học. Cô là một người biết lắng nghe, cười nhiều và mơ ước có được một câu chuyện tình yêu do định mệnh sắp đặt. Pil Joo đã âm thầm lên kế hoạch sắp xếp cho Na Mo Hyun có một cuộc “hôn nhân trao đổi” với người thừa kế tập đoàn là Jang Boo Cheon (Jang Seung Jo). Trớ trêu thay trong quá trình tiếp cận Mo Hyun, trái tim Pil Joo đã loạn nhịp vì không biết mình đã yêu cô từ lúc nào.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2017, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Park Se Young","avatar":""},{"name":"Jang Seung Jo","avatar":""},{"name":"Lee Mi Sook","avatar":""},{"name":"Lee Soon Jae","avatar":""},{"name":"Han So Hee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324405);
