INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-nhi-dai-chien', 'Thập Nhị Đại Chiến', 'Juni Taisen: Zodiac War', 'https://phimimg.com/upload/vod/20231207-1/38ad7c4868ec9a68b398949c25756034.jpg', 'https://phimimg.com/upload/vod/20231207-1/a11946c3f7bd4298b7550ed19aa26733.jpg', '<p>Phim Thập Nhị Đại Chiến - Juni Taisen: Zodiac War 2017: Biên sử ký của trận chiến đẫm máu giữa 12 vị chiến binh kiêu hãnh—Giải Đấu Thập Nhị lần thứ 12 được tổ chức 12 năm một lần… 12 chiến binh dũng cảm mang trên mình danh hiệu 12 con giáp đã chiến đấu với nhau bằng cả mạng sống mình. Những người tham gia là 12 vị chiến binh kì lạ: “Tí”, “Sửu”, “Dần”, “Mẹo”, “Thìn”, “Tị”, “Ngọ”, “Mùi”, “Thân”, “Dậu”, “Tuất”, “Hợi”. Người chiến thắng trong giải đấu này sẽ được thực hiện một điều ước, bất kỳ điều ước nào cũng sẽ thành hiện thực. Ai sẽ là người sau cùng sống sót? Ai sẽ rơi lệ trong chiến trường đẫm máu đầy âm mưu và thủ đoạn này? Trận chiến rúng động tâm can sắp sửa bắt đầu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2017, 'Thuyết Minh', 'HD', 'Nhật Bản', 0, '[{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324405);
