INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-luong-huy-diet', 'Năng Lượng Hủy Diệt', 'Kill Switch - Redivider', 'https://phimimg.com/upload/vod/20231210-1/26fb409259bb091aabbd6eff679ef931.jpg', 'https://phimimg.com/upload/vod/20231210-1/d56a7b5b7c196cd449dd524224dbf363.jpg', '<p>Xoay quanh 1 cuộc thí nghiệm sai lầm kéo theo vô số hiểm họa không ngờ tới. Một nhóm nhà nghiên cứu thử nghiệm về mức giới hạn không gian khai thác vũ trụ song song mục đích để cứu sống gia đình họ và hành tinh, thế nhưng 1 sai lầm đã xảy ra tạo nên hiểm họa khôn lường. Bám đuổi bởi cùng với đội quân phi cơ và binh lính, nhà vật lí Will Porter phải chạy đua xuyên qua một thế giới xâm chiếm khác để đưa chiếc hộp Redivider lên một chiếc tháp để cứu sống nhân loại và gia đình vẫn đang tồn tại trong thế giới thực.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dan Stevens","avatar":""},{"name":"Bérénice Marlohe","avatar":""},{"name":"Charity Wakefield","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324405);
