INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thuyet-gia-cuong-loan', 'Tiểu Thuyết Gia Cuồng Loạn', 'Based On A True Story', 'https://phimimg.com/upload/vod/20231210-1/e22a5a6f476ead57376768e6d633e3fa.jpg', 'https://phimimg.com/upload/vod/20231210-1/3dfd39c31b5c9abb0d5cb6e25bd1e47c.jpg', '<p>Tiểu Thuyết Gia Cuồng Loạn - Based on a True Story (2018):Chuyện phim theo chân nữ nhà văn Delphine Dayrieux (Emmanuelle Seigner đóng) rơi vào tình trạng khủng khoảng tâm lý sau khi xuất bản quyển sách mới. Cô liên tục nhận được những lá thư ẩn danh đe dọa đến gia đình mình. Trong giai đoạn này, Delphine gặp gỡ một người hâm mộ tên Elle và dường như cũng là bước ngoặt làm xáo trộn cuộc sống của chính mình. Với lần gặp gỡ tình cờ rồi những lúc có chủ ý, Elle (do Eva Green thủ vai) dường như dần bước sâu vào cuộc sống của nữ tiểu thuyết gia Delphine. Cả hai người phụ nữ bắt đầu một mối quan hệ đặc biệt, ngọt ngào và bí hiểm. Tuy nhiên, tình bạn của họ ngày càng trở căng thẳng và đáng sợ khi sự cuồng nhiệt đến mức đáng lo ngại của Elle cùng với nét quyến rũ, thông minh, nhạy cảm có thể thấu hiểu Delphine rõ hơn bất kỳ ai sẽ khiến cho người xem mở ra nhiều cánh cửa bất ngờ pha lẫn sự tò mò hồi hộp...</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Emmanuelle Seigner","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Vincent Pérez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
