INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trainspotting', 'Trainspotting', 'Trainspotting', 'https://phimimg.com/upload/vod/20231208-1/e9b63625585bbed000c8dff64e20f630.jpg', 'https://phimimg.com/upload/vod/20231208-1/5e14a5be01577ee1434e99793aa8369f.jpg', '<p>Đầu tiên có một cơ hội ...... sau đó đã có một sự phản bội. Hai mươi năm đã đi qua. Nhiều đã thay đổi nhưng cũng như vậy vẫn giống nhau. Mark Renton (Ewan McGregor) trở về nơi duy nhất anh ta có thể gọi về nhà. Họ đang đợi anh: Spud (Ewen Bremner), chàng trai ốm yếu (Jonny Lee Miller), và Begbie (Robert Carlyle). Những người bạn cũ khác đang chờ đợi: nỗi buồn, buồn bã, niềm vui, thù hận, thù hận, tình bạn, tình yêu, khao khát, sợ hãi, hối hận, diamorphin, tự hủy, tất cả đều được xếp hàng để chào đón anh ta, sẵn sàng tham gia điệu nhảy .</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324405);
