INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thuyet-kinh-di', 'Tiểu Thuyết Kinh Dị', 'Inside: A Chinese Horror Story', 'https://phimimg.com/upload/vod/20231209-1/55c5e5afc64eaf1778fd03bdb8e9f7ae.jpg', 'https://phimimg.com/upload/vod/20231209-1/14d3233bca1592dac6a1bb8512ba53f0.jpg', '<p>Phim Tiểu Thuyết Kinh Dị - Inside: A Chinese Horror Story 2017: Là một tiểu thuyết gia hết thời, Thôi Khải bỗng nhiên nhận được lời viết tiểu thuyết kị dị từ nhà xuất bản. Kể từ đó, anh lao vào sáng tác nhưng càng viết anh càng bị cuốn vào từng câu chuyện rùng rợn của chính mình. Những ám ảnh của quá khứ, những bí mật chưa rõ liệu có sáng tỏ khi cuốn tiểu thuyết được hoàn thành.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lữ Duật Lai","avatar":""},{"name":"Khang Khải","avatar":""},{"name":"Trương Hồng Kính","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
