INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-cao-giao-vien-quai-quai-quai-quai-vat', 'Báo Cáo Giáo Viên! Quái Quái Quái Quái Vật!', 'Mon Mon Mon Monsters!', 'https://phimimg.com/upload/vod/20231209-1/f9e7a17b1aa07730ae8abf3003495576.jpg', 'https://phimimg.com/upload/vod/20231209-1/21e7044708596226dd905f4cbaf5cd9e.jpg', '<p>Báo Cáo Giáo Viên! Quái Quái Quái Quái Vật! (Mon Mon Mon Monsters) là bộ phim kinh dị hài hước do nhà văn Cửu Bả Đao biên kịch và đạo diễn xoay quanh cậu học sinh ưu tú Lâm Thư Vĩ. Là một người thẳng tính, thật thà, Thư Vĩ thường bị bạn bè cùng lớp, cầm đầu là Đoàn Nhân Hào bắt nạt do tính cách hay mách lẻo. Một ngày, cậu bị buộc tội ăn cắp tiền và phải cùng 3 kẻ chuyên bắt nạt mình hợp tác làm một hoạt động cộng đồng, chăm sóc cho những người già neo đơn. Thư Vĩ dần dần bị ảnh hưởng bởi nhóm bạn và theo họ làm việc xấu. Vào một đêm, bốn người lên kế hoạch ăn cắp tủ sắt của một người già neo đơn mất trí. Không ngờ, họ lại bắt được một con quái vật nhỏ biết ăn thịt người trong căn nhà.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Deng Yukai","avatar":""},{"name":"Cai Fan-xi","avatar":""},{"name":"Liang Ru-xuan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324405);
