INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-lang-2', 'Chiến Lang 2', 'Wolf Warriors Ⅱ', 'https://phimimg.com/upload/vod/20231209-1/9ccd55be79819cd6d4ad4d07b9227ac3.jpg', 'https://phimimg.com/upload/vod/20231209-1/b8d5001fe5500b7bc77b2a8022cd9d33.jpg', '<p>Câu chuyện xảy ra ở khu vực ngoài khơi của Châu Phi, nhân vật chính Lãnh Phong gặp phải biến cố lớn của cuộc đời - bị đuổi khỏi quân đội. Vốn định sẽ để mặc cuộc đời, nhưng khi anh vừa chuẩn bị làm thế thì một sự việc khác bất ngờ ập đến làm thay đổi kế hoạch của mình. Anh bị cuốn vào một cuộc nổi loạn ở quốc gia Châu Phi. Anh vốn có thể rút lui an toàn, nhưng vì không thể nào quên được nhiệm vụ của người lính cho nên đã một mình quay về nơi nguy hiểm để đưa những người dân tị nạn chạy trốn. Cuộc chiến ngày càng khốc liệt, bản chất \</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jason Wu","avatar":""},{"name":"Frank Anthony Grillo","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Hans Zhang","avatar":""},{"name":"Celina Jade","avatar":""},{"name":"Ding Hai Feng","avatar":""},{"name":"Chun Yu Shan Shan","avatar":""},{"name":"Yu Nan","avatar":""},{"name":"Yu Qian","avatar":""},{"name":"Shi Zhao Qi","avatar":""},{"name":"Oleg Strizhenov","avatar":""},{"name":"Thayr Harris","avatar":""},{"name":"Wei Qing","avatar":""},{"name":"Du Jian Qiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324405);
