INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-quyen-phan-1', 'Thiết Quyền (Phần 1)', 'Marvel''s Iron Fist (Season 1)', 'https://phimimg.com/upload/vod/20231207-1/a038e0ddff8add5478112a25d067edbf.jpg', 'https://phimimg.com/upload/vod/20231207-1/d1a1583b24742cc7957bb90b5cb36554.jpg', '<p>Mười lăm năm sau khi được cho là đã chết trong một vụ tai nạn máy bay, Danny Rand bí ẩn trở lại thành phố New York với quyết tâm đòi lại quyền thừa kế và công ty gia đình. Tuy nhiên, khi một kẻ thù truyền kiếp trỗi dậy ở New York, vũ khí sống này buộc phải lựa chọn giữa di sản của gia đình và nhiệm vụ của mình với tư cách là Iron Fist.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 19, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Finn Jones","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Jessica Stroup","avatar":""},{"name":"Tom Pelphrey","avatar":""},{"name":"Sacha Dhawan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324405);
