INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uon-cong-vong-cung', 'Uốn Cong Vòng Cung', 'Bending The Arc', 'https://phimimg.com/upload/vod/20231208-1/c011fd714fecb6f6b4911815161a2b6b.jpg', 'https://phimimg.com/upload/vod/20231208-1/51c3dc76182de75925f9f23a028af358.jpg', '<p>Phim tài liệu này dõi theo một nhóm người ủng hộ đầy tham vọng. Sứ mệnh cứu sống cư dân ở Haiti của họ biến thành một cuộc chiến vì công lý và chăm sóc sức khỏe toàn cầu.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324405);
