INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tin-mat-danh-x', 'Con Tin Mật Danh X', 'Hostage X', 'https://phimimg.com/upload/vod/20231208-1/487c66bf134e79c2e311b6d5f01eeb76.jpg', 'https://phimimg.com/upload/vod/20231208-1/3e6a14437378b43c817ed7d67e3346b9.jpg', '<p>Bạn thức dậy, không có trí nhớ. Bạn có 90 phút trước khi những kẻ bắt cóc giết bạn, trừ khi bạn tìm ra bạn là ai và tại sao những người nước ngoài này muốn giết bạn. Một bộ phim kinh dị thuộc dòng Buried với một tình tiết quanh co.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason London","avatar":""},{"name":"Stefanie Joosten","avatar":""},{"name":"Lua Helenklaken","avatar":""},{"name":"Richard Messina","avatar":""},{"name":"Ergun Simsek","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324405);
