INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-hat-tu-trai-tim', 'Tiếng Hát Từ Trái Tim', 'The Anthem Of The Heart', 'https://phimimg.com/upload/vod/20231208-1/d63aa6611ff3ba072accf3d93e6c1e5d.jpg', 'https://phimimg.com/upload/vod/20231208-1/7b29fe3851fe9c04960921765c86c51b.jpg', '<p>Câu chuyện diễn ra ở thành phố Chichibu của Nhật Bản, bắt đầu bằng giấc mơ cổ tích của cô bé Jun Naruse mong được bước chân vào tòa lâu đài tráng lệ trên đỉnh đồi, nhưng thực chất đây chỉ là một khách sạn tình yêu. Một lần đang ngắm nghía khách sạn từ bên ngoài, cô nhìn thấy ba mình lái xe đi cùng với một người phụ nữ xinh đẹp khác, trong trí tưởng tượng thơ ngây của Jun, ba cô như một chàng hoàng tử cưỡi ngựa trắng, song hành cùng một nàng công chúa kiều diễm đi ra từ lâu đài cổ tích, cô vội vã chạy về nhà và khoe với mẹ điều mình vừa thấy.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kento Nakajima","avatar":""},{"name":"Kyoko Yoshine","avatar":""},{"name":"Anna Ishii","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324406);
