INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-quan-mat-na', 'Phán Quan Mặt Nạ', 'Mask The Judge', 'https://phimimg.com/upload/vod/20231208-1/9f08a8e84fb50e940f69490e74671350.jpg', 'https://phimimg.com/upload/vod/20231208-1/75e1dbd94e59f94e5bdca638ceea212b.jpg', '<p>Phim Phán Quan Mặt Nạ - Mask The Judge 2017: Lâm Hy và Kim Dật Phi là cặp phóng viên chuyên lăn xả vào những nơi nguy hiểm để lấy tin tức. Khi theo dõi một vụ đánh cắp thuốc hóa học, hai người phát hiện ra kẻ chủ mưu đứng đằng sau chính là một dị tộc đã tồn tại hàng nghìn năm nay. Điều kỳ lạ nhất là, mỗi khi Lâm Hy gặp nguy hiểm, một hiệp sĩ mặt nạ lại xuất hiện cứu cô.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Thôi Vĩnh Huyễn","avatar":""},{"name":"Lưu Tĩnh Di","avatar":""},{"name":"Trần Lâm Sinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
