INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-hat-de-2-cong-vien-dai-chien', 'Phi Vụ Hạt Dẻ 2: Công Viên Đại Chiến', 'The Nut Job 2: Nutty by Nature', 'https://phimimg.com/upload/vod/20231220-1/6c892d1f142d854c53123265348dacca.jpg', 'https://phimimg.com/upload/vod/20231220-1/e45e72908e27ccdd6bafcc1ddccf6087.jpg', '<p>Chú sóc chuột Surly và những người bạn của mình đã có cuộc sống đầy sung sướng khi lẩn trốn trong tầng hầm của một tiệm hạt dẻ. Mọi thứ diễn ra tốt đẹp với thức ăn có sẵn. Nhưng Andie lại lo lắng về cuộc sống quá nhàn hạ của Surly. Cô ấy cho rằng những bạn thú đang đánh mất đi bản năng ban đầu của họ. Rồi một tai nạn bất ngờ ập đến, tiệm hạt dẻ phát nổ. Thế nhưng, không may cho họ là thị trưởng của Oakton đã lập ra một kế hoạch mới cho công viên Liberty. Ông ta âm mưu chuộc lợi cho mình bằng cách san bằng công viên Liberty. Surly nhận ra đây là lúc mình và các bạn thú phải gạt bỏ những bất đồng cá nhân để đứng lên chiến đấu cùng nhau, đánh đổ thị trưởng và giành lại công viên Liberty.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Will Arnett","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Jeff Dunham","avatar":""},{"name":"Sebastian Maniscalco","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Katherine Heigl","avatar":""},{"name":"Julie Lemieux","avatar":""},{"name":"Dwayne Hill","avatar":""},{"name":"Josh Robert Thompson","avatar":""},{"name":"Rob Tinkler","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324406);
