INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-bat-cuong-thi', 'Biệt Đội Bắt Cương Thi', 'Vampire Cleanup Department', 'https://phimimg.com/upload/vod/20231219-1/4e265ca520fe1e51d0fdf0fe66ca044e.jpg', 'https://phimimg.com/upload/vod/20231219-1/21c25152a6f8cab0547d84fd293d571c.jpg', '<p>Trong thời hiện đại ở Hồng Kông, một thế hệ các thanh thiếu niên trẻ mà điển hình là Tim Cheung quyết tâm gia nhập vào hội Vampire Cleanup Department, một đội đặc nhiệm và bí mật để giải quyết các vụ án có liên quan đến ma cà rồng tại Trung Quốc mà nhiều người hay gọi nó là Goeng Si. Trong quá trình hành động, anh được sự chỉ dẫn của chú Châu, một trong những đội ngũ cán bộ cao cấp, và cho đến cuối cùng anh lại tự mình cứu lấy một nữ Goeng Si, người đã bị vị lãnh chúa tà ác Goeng Si chôn sống cô kể từ thời phong kiến xa xưa.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Baby John Choi","avatar":""},{"name":"Lin Min-Chen","avatar":""},{"name":"Chin Siu-Ho","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Lo Meng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
