INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-mu', 'Điểm Mù', 'Blind Spot', 'https://phimimg.com/upload/vod/20231219-1/c22b863e4fbc8fb71bf8a06ede1fb178.jpg', 'https://phimimg.com/upload/vod/20231219-1/3c6455abbf947e3652b1ab9c50f4f0ba.jpg', '<p>Phim Điểm Mù - Blind Spot 2017: Cảnh sát trưởng nổi tiếng chính trực Jan Verbeeck quyết định rời ngành đẻ tham gia chính trị và ứng cử tổng thống. Nhận tin về phòng thí nghiệm chế tạo ma túy của một tên đầu sỏ, anh tham gia phá án lần cuối với tư cách cảnh sát. Jan không biết rằng vụ này sẽ vạch trần một bí mật đau buồn và dẫn tới cái kết không ai ngờ.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Peter van den Begin","avatar":""},{"name":"David Murgia","avatar":""},{"name":"Soufiane Chilah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
