INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-tay-du-3-ky-ngo-nu-nhi-quoc', 'Giấc Mộng Tây Du 3: Kỳ Ngộ Nữ Nhi Quốc', 'The Dream Journey 3', 'https://phimimg.com/upload/vod/20231208-1/eb4d87e3e74295eb65f1ac76f076f466.jpg', 'https://phimimg.com/upload/vod/20231208-1/703d6ae30690b7f14a9e39173e88d6e0.jpg', '<p>Phim Giấc Mộng Tây Du 3: Kỳ Ngộ Nữ Nhi Quốc Học sinh diệp mặc mặc ban đêm xông vào cấm địa, cơ duyên xảo hợp hồi tưởng lại trí nhớ kiếp trước của mình. Kiếp trước của nàng là quốc vương nữ nhi quốc Dạ Tịch Mặc, Khi nữ nhi quốc bị diệt quốc, Lão tướng bắc minh công trói hồn phách các nàng vào trong người bù nhìn trở thành nhiếp hồn tộc, từ nay về sau không thể tiến vào luân hồi, chỉ có thể dựa vào hấp thu hồn phách của đàn ông để sống tiếp... Câu chuyện xảy ra khi đoàn người Đường tăng qua nữ nhi quốc.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hứa Minh Hổ","avatar":""},{"name":"Phiền Nhị","avatar":""},{"name":"Trương Thiên Kỳ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
