INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-co-nguoi-phieu-bat-cung-em', 'Nguyện Có Người Phiêu Bạt Cùng Em', 'Accompany You Ups And Downs', 'https://phimimg.com/upload/vod/20231207-1/eca992c420c5020b5e7c36b49487edbe.jpg', 'https://phimimg.com/upload/vod/20231207-1/ec3dc74f9e1db0cf86d6bdaf3305a330.jpg', '<p>Phim kể về câu chuyện người ở bên bạn trong những năm tháng thanh xuân tươi đẹp luôn vào lúc sau khi mất đi mới biết được người nên bảo vệ nhất chính là người luôn ở bên cạnh bạn. Hà Thản sau khi đã trở thành 1 tác giả nổi tiếng, mang theo cuốn sách mới nhất của mình Nguyện cùng người lang bạc kỳ hồ quay trở về trường đại học tham gia buổi gặp mặt với độc giả, có 1 cô gái tỏ tình với cậu ta, khiến Hà Thản nhớ lại cuộc sống đại học đã qua và câu chuyện mối tình đầu như một chuyến đi kì diệu của mình.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 15, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hải Linh","avatar":""},{"name":"Tiết Trạch Nguyên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
