INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ho-ngui-tuong-vi-doc-hanh-ky-dao', 'Mãnh Hổ Ngửi Tường Vi: Độc Hành Kỳ Đạo', 'Tiger And Flower: The Man In Paintings', 'null', 'https://phimimg.com/upload/vod/20231219-1/760fd220c09da9820a84e94b9b94c159.jpg', '<p>Mãnh hổ ngửi tường vi: Độc Hành Kỳ Đạo - Tiger and flower: The man in paintings xoay quanh Đàm Hổ và Thái Vi, sau khi trải qua nhiều vụ án và sự tin tưởng giữu cả hai, họ quyết định kết hôn, nhưng sau khi kết hôn chỉ có thể để một người làm cảnh sát. Lâm Kỳ Lân quyết định để cả hai cùng giải quyết một vụ án trộm tranh nổi tiếng, ai thắng sẽ được ở lại. Trong hai người họ, ai sẽ thắng và sẽ tiếp tục làm cảnh sát?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Yan","avatar":""},{"name":"Yu Tiểu Loan","avatar":""},{"name":"Wang Junpeng","avatar":""},{"name":"Yang Tieou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
