INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-chien-tam-giac-vang', 'Huyết Chiến Tam Giác Vàng', 'Killer LiMo', 'https://phimimg.com/upload/vod/20231219-1/78d1709d20f376b0cae33221752e8f6a.jpg', 'https://phimimg.com/upload/vod/20231219-1/d2474e0ea7fe277b8bc322c94dbc448e.jpg', '<p>Phim Huyết Chiến Tam Giác Vàng - Killer LiMo 2017: Ly Mạt là con gái của một tay anh chị trong một tổ chức tại Tam Giác Vàng. Sau khi bố cô bị thủ tiêu, Ly Mạt may mắn thoát chết và được Nguyên Lương, anh em cùng một tổ chức với bố cô bồi dưỡng. Khi đã trở thành một nữ sát thủ siêu đẳng, Ly Mạt bắt đầu công cuộc trả thù của mình và rồi phát hiện ra một sự thật đau đớn.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Tử Hùng","avatar":""},{"name":"Lưu Na Bình","avatar":""},{"name":"Nelson Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
