INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-hang-xom-doc-than', 'Chàng Hàng Xóm Độc Thân', 'The Bachelor Next Door', 'https://phimimg.com/upload/vod/20231219-1/40eba61670e52dcde6bbf019335d9737.jpg', 'https://phimimg.com/upload/vod/20231219-1/de87b812125bcf079408b7de532d5713.jpg', '<p>Gavin và Alex chưa bao giờ gặp người đàn ông bí ẩn đã chuyển đến ở nhà bên cạnh cho đến khi anh ta cứu Alex khỏi đám cháy. Để tỏ lòng biết ơn, Alex và Gavin kết bạn với Donnie, và thậm chí giới thiệu anh ta với em gái của Alex. Nhưng Donnie ngày càng trở nên kỳ dị hơn, và sự nghi ngờ của Gavin bắt đầu tăng lên. Có phải Donnie đã gây ra đám cháy? Tìm hiểu sâu hơn, Gaving phát hiện ra Donnie có một quá khứ nguy hiểm và bí mật. Gavin và Alex phải làm việc cùng nhau để làm sáng tỏ động cơ của Donnie vì tàn phá cuộc sống của họ - trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Haylie Duff","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
