INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chang-hang-xom-doc-than', 'Chàng Hàng Xóm Độc Thân', 'The Bachelor Next Door', 'chàng hàng xóm độc thân the bachelor next door haylie duff ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('re-trai-hay-re-phai', 'Rẽ Trái Hay Rẽ Phải', 'C Street', 'https://phimimg.com/upload/vod/20231219-1/82ac99498b9ae74458e2b70adff76b58.jpg', 'https://phimimg.com/upload/vod/20231219-1/2998b3824c4f5cdd2eb15603bbd807bc.jpg', '<p>Cô nàng trong mộng bỗng xuất hiện khiêu gợi trên giường ngủ của Guy nhưng trớ trêu lại đang chờ ông chủ của anh, một chính khách có tiếng ở Washington. Gã thực tập sinh trẻ Guy muốn té ngửa khi biết được sự thật không được báo trước: căn hộ của anh đã trở thành chốn hẹn hò bí mật của nhiều chính trị gia và nhân tình nóng bỏng. Phim như một trò hề khiến người xem tò mò khi lối sống hoan lạc của các chính khách bị vạch trần một cách quá chân thực và hài hước.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carey Lowell","avatar":""},{"name":"Dylan Walsh","avatar":""},{"name":"Don Stark","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
