INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-adventure-tri-part-4-loss', 'Digimon Adventure Tri. Part 4: Loss', 'Digimon Adventure Tri. Part 4: Loss', 'https://phimimg.com/upload/vod/20231219-1/a95830feb13ba95c56a387852006221f.jpg', 'https://phimimg.com/upload/vod/20231219-1/9543e40fff77cb1a000d00c5449ba245.jpg', '<p>Khi đến thế giới kỹ thuật số sau khi khởi động lại, Digidestined bị săn lùng bởi một nhân vật phản diện mới. Trong khi đó, Sora gặp rắc rối với sự thờ ơ của đối tác Digimon về phía cô.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
