INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum-ngoi-lang-ky-bi', 'Xì Trum: Ngôi Làng Kỳ Bí', 'Smurfs: The Lost Village', 'https://phimimg.com/upload/vod/20231208-1/7c00eb860208176594cf43a236f16b2c.jpg', 'https://phimimg.com/upload/vod/20231208-1/aca3a72fefbd015db8e0ce7f3269120f.jpg', '<p>Phim Xì Trum: Ngôi Làng Kỳ Bí - Smurfs: The Lost Village 2017: Dựa trên bộ truyện tranh Xì Trum bằng tiếng Pháp nổi tiếng của Bỉ ra mắt vào năm 1958. Xì Trum là một chủng tộc người da xanh tí hon sống trong xứ sở Xì Trum xa xôi. Chúng ở trong những ngôi nhà có hình cây nấm. Làng Xì Trum do Tí Vua đứng đầu và mỗi Tí đại đại diện cho một tính cách của con người. Họ phải đối mặt với lão phù thủy Gargamel độc ác luôn tìm cách xâm chiếm ngôi làng. Ngoài ra, cuộc sống thường ngày của các Tí cũng vô cùng hài hước và thú vị với đủ các trò tinh nghịch cũng như tai nạn “dở khóc dở cười”.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Lồng Tiếng', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Ellie Kemper","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324406);
