INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-co-vat', 'Truy Lùng Cổ Vật', 'S.M.A.R.T. Chase - The Shanghai Job', 'https://phimimg.com/upload/vod/20231206-1/d7aa363d3b5ac351293c86c689cca7ac.jpg', 'https://phimimg.com/upload/vod/20231206-1/6861a8b60edaa30259d68981a585b369.jpg', '<p>Bộ phim kể về Danny Stratton, trong một lần nhận nhiệm vụ bảo vệ cho việc vận chuyển một món đồ cổ quý giá rời khỏi Thượng Hải, anh không may bị kẻ địch mai phục và lấy cắp mất món đồ. Stratton đã triệu tập biệt đội S.M.A.R.T (Security Management Action Recovery Team) – một biệt đội chuyên nghiệp có nghĩa vụ đảm bảo sự suôn sẻ và an toàn cho các vụ làm ăn kinh doanh, đi tìm lại món hàng bị ăn cắp về.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Orlando Bloom","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Lynn Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
