INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-quyet-dinh-2017', 'Thời Khắc Quyết Định', 'Good Time', 'https://phimimg.com/upload/vod/20231204-1/d41e02dc13f7e0d79ec948c6550c98f8.jpg', 'https://phimimg.com/upload/vod/20231204-1/b1e026a1befb6579a325f71ffef1bca7.jpg', '<p>Good Time sẽ xoay quanh câu chuyện của hai anh em Constantine ‘Connie’ Nikas (Robert Pattinson) và Nick (Benny Safdie). Sau khi Nick bị bắt và bỏ tù do cướp ngân hàng không thành công, Connie đã bắt đầu một cuộc phiêu lưu đầy rẫy những nguy hiểm và cạm bẫy xuyên thế giới ngầm của thành phố hòng tìm ra cách giúp Nick thoát kiếp tù nhân. Bối cảnh Good Time xảy ra chỉ trong vòng một đêm ngắn ngủi, hứa hẹn những kịch tính giật gân đến liên tục xuyên suốt thời lượng phim.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Ben Safdie","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
