INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-quan-tai-thuong', 'Tướng Quân Tại Thượng', 'Oh My General', 'https://phimimg.com/upload/vod/20231204-1/8ae6f617b015d5d1d737a0e460f2aeb9.jpg', 'https://phimimg.com/upload/vod/20231204-1/ad14a87ab1a8b1c1e650b55fd311d769.jpg', '<p>Tướng Quân Tại Thượng là dự án phim truyền hình Trung Quốc cổ trang - giả sử với sự góp mặt của nhiều gương mặt triển vọng như nữ diễn viên Mã Tư Thuần thủ vai Diệp Chiêu – một nữ tướng quân tài ba, oai dũng - và Thịnh Nhất Luân đảm nhận vai nam chính Triệu Ngọc Cẩn. Phim xoay quanh chuyện tình yêu và hôn nhân giữa nữ tướng quân Diệp Chiêu lạnh lùng, võ nghệ siêu phàm và vương gia Triệu Ngọc Cẩn tuy có dung mạo hơn người nhưng lại bất tài, vô dụng, không xứng với Diệp Chiêu... Mã Tư Thuần là một trong những gương mặt nữ diễn viên triển vọng của làng giải trí Hoa Ngữ, người hâm mộ hy vọng Tướng Quân Tại Thượng tiếp tục sẽ là một thành công của nữ diễn viên trẻ tuổi. Nam diễn viên Thịnh Nhất Luân mỹ nam cổ trang cũng được kỳ vọng sẽ tỏa sáng trong phim truyền hình Tướng Quân Tại Thượng.</p>', 'Hoàn tất (60/60)', 60, 'series', 'completed', 15, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Mã Tư Thuần","avatar":""},{"name":"Thịnh Nhất Luân","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Đinh Xuyên","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324406);
