INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-cuoi-cung', 'Vùng Đất Cuối Cùng', 'Bushwick', 'https://phimimg.com/upload/vod/20231204-1/8710fa17336ec0f501a0a82dc966a82a.jpg', 'https://phimimg.com/upload/vod/20231204-1/d4fe3af99d74cdd10e1cc396639dea6a.jpg', '<p>Phim Vùng Đất Cuối Cùng - Bushwick 2017: Câu chuyện về Lucy mới 20 tuổi và Stupe chiến binh dày dặn trong 1 cuộc khủng hoảng quốc gia khi Texas muốn rút khỏi liên bang nước Mỹ. Lucy và Stupe gặp nhau trong 1 hành động quân sự xâm lấn Brooklyn và quyết định cùng nhau vượt qua vượt qua 5 chướng ngại lớn của Bushwick, những kẻ cướp, quân đội địa phương, lực lượng xâm lược, và 1 tên anh họ điên để về nhau và đoàn tụ với bà ngoại của Lucy.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Angelic Zambrana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
