INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-nhan', 'Á Nhân', 'Ajin: Demi-Human', 'https://phimimg.com/upload/vod/20231203-1/6708f3d2998abf61c2ee594ee5dc509b.jpg', 'https://phimimg.com/upload/vod/20231203-1/4d0b1b3ca54a25cdf59c11728c89276b.jpg', '<p>Nam sinh Kei Nagai (Takeru Satoh) sau một tai nạn đã bị biến đổi thành Ajin / Á nhân. Họ là những người dù vẫn bị thương, vẫn chịu sự đau đớn như người bình thường nhưng lại bất tử và có thể tái sinh sau khi chết. Chính sự đặc biệt này đã khiến cho các Ajin bị các tổ chức săn lùng một cách gắt gao để đưa vào chương trình quản lý và bảo vệ của chính phủ. Một nhóm Ajin dần phát hiện ra âm mưu đen tối đằng sau và đứng lên chống trả, mỗi người một mục đích. Cuộc chiến ngầm giữa các Ajin thiện-ác và các tổ chức chính phủ từ đó nổ ra.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeru Satoh","avatar":""},{"name":"Go Ayano","avatar":""},{"name":"Minami Hamabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
