INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-thich-mot-minh', 'Quý Cô Thích Một Mình', 'Individualist Ms. Ji Young', 'https://phimimg.com/upload/vod/20231204-1/ab89e599bbf1fc70d195c0b40fcc4dae.jpg', 'https://phimimg.com/upload/vod/20231204-1/16b10714df455d98393cd870a324800a.jpg', '<p>Phim Individualist Ms. Ji Young 2017 xoay quanh hai nhân vật có cách sống trái ngược nhau: Ji Young (Min Hyo Rin), một cô gái theo chủ nghĩa cá nhân, quá yêu bản thân và không muốn ở trong một mối quan hệ với bất kì ai; Byuk Soo (Gong Myung), một chàng trai quá phụ thuộc, không thể sống nổi nếu không có ai ở bên mình. Individualist Ms. Ji Young sẽ là cuộc hành trình hai con người tìm thấy nhau và giúp nhau chữa lành những vết thương lòng.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 15, 2017, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Oh Na Ra","avatar":""},{"name":"Gong Myung","avatar":""},{"name":"Min Hyo Rin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
