INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-dang-ngo', 'Đối Tác Đáng Ngờ', 'Suspicious Partner', 'https://phimimg.com/upload/vod/20231204-1/667e911d5ec3790507ee2d21cfbacdaf.jpg', 'https://phimimg.com/upload/vod/20231204-1/03276238a50c037b5fbc25cde9dd9a2b.jpg', '<p>Giới thiệu vắn tắt: Kỹ năng diễn xuất của nam thần Ji Chang-wook lại bùng nổ một lần nữa! Luật sư chính nghĩa và kiểm sát viên thực tập là kẻ tình nghi phạm tội đã trở thành “cộng sự”, tuy cặp cộng sự này kỳ lạ, thế nhưng mức độ ngọt ngào lúc yêu đương vẫn vô cùng cuồng nhiệt!</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Chang Wook","avatar":""},{"name":"Nam Ji Hyun","avatar":""},{"name":"Kwon Na-ra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
