INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-duyen', 'Linh Duyên', 'Voodoo Doll', 'https://phimimg.com/upload/vod/20231204-1/bf958444e80ac8fc937406e4e0f764c1.jpg', 'https://phimimg.com/upload/vod/20231204-1/9deadb6e0227d1844f97649734407acc.jpg', '<p>Là một bộ phim kinh dị đánh dấu sự hợp tác của hai đạo diễn Võ Ngọc và Hạnh Nhân vừa được ra mắt năm 2017 xoay quanh câu chuyện về ba người bạn thân cùng học một lớp tại nhạc viện tên Thư, Quân và Hạnh. Trong phim mọi chuyện bắt đầu khi thầy giáo chủ nhiệm mới tên Hùng đến nhận lớp. Anh nhận thấy được sự giống nhau kỳ lạ giữa Thư và người yêu cũ của mình, Hùng tìm cách bắt chuyện và rất nhanh chóng làm quen với Thư, điều này khiến vợ của anh, Hương rất khó chịu, bỗng nhiên một ngày ba người bạn tìm được một hình nhân tại lớp học của mình và từ đó hàng loạt những câu chuyện ma quái xảy ra. Liệu hình nhân ấy đang ẩn chứa bí mật to lớn gì và tại sau nó lại được giấy tại nơi nhiều người ra vào như thế? Giữa mùa phim vào đầu năm 2017 với khá nhiều phim thuộc dòng phim kinh dị được ra mắt, Linh Duyên vẫn là bộ phim được khán giả mong đợi, qua đoạn trailer đầy hồi hộp và kịch tính.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dustin Nguyễn","avatar":""},{"name":"Trương Quỳnh Anh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
