INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-co-chien-tranh', 'Hoa Cỏ Chiến Tranh', 'In Harm''s Way', 'https://phimimg.com/upload/vod/20231202-1/b454a9ab43f5e7c699624f7e860ba392.jpg', 'https://phimimg.com/upload/vod/20231202-1/bd5ab90b217cb1f1ea49cf2a0c5e82e9.jpg', '<p>Phim lấy bối cảnh sau sự kiện Trân Châu Cảng, xoay quanh câu chuyện của góa phụ Trung Quốc tên Anh Tử (Lưu Diệc Phi) và sĩ quan Mỹ Jack Turner (Emile Hirsch). Trong một lần tình cờ, cô cùng con gái tình cờ phát hiện viên phi công Mỹ đang hôn mê, Anh Tử bất chấp nguy hiểm, đem vị người Tây về nhà và cứu chữa. Sau đó, dù không thể giao tiếp vì trở ngại ngôn ngữ, bằng hành động quan tâm, cả hai đã nảy sinh tình cảm với nhau. Liệu chuyện của họ sẽ đến đâu?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yifei","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Fangcong Li","avatar":""},{"name":"Kevin Yan","avatar":""},{"name":"Yu Shaoqun","avatar":""},{"name":"Vincent Riotta","avatar":""},{"name":"Tsukagoshi Hirotaka","avatar":""},{"name":"Gallen Lo","avatar":""},{"name":"Shu Yaoxuan","avatar":""},{"name":"Gong Hanlin","avatar":""},{"name":"Tiankuo Gong","avatar":""},{"name":"Cary Woodworth","avatar":""},{"name":"Lambert Houston","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Xie Fang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324406);
