INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-yen-bi-huy-hoai', 'Bình Yên Bị Hủy Hoại', 'Disturbing The Peace', 'https://phimimg.com/upload/vod/20231213-1/d21db65f2b99b3e07b2a34565ffbd483.jpg', 'https://phimimg.com/upload/vod/20231213-1/d8e852693932c64bbeba8b26eafc36dd.jpg', '<p>Kể từ khi rời biệt đội Texa Rangers do ám ảnh vụ xả súng thảm khốc, người cảnh sát trưởng đã quyết định không sử dụng súng. Nhưng ngài cảnh sát trưởng đã phải nhặt lại súng của mình để chiến đấu với một nhóm người đi xe đạp ngoài vòng pháp luật đã xâm nhập thị trấn để thực hiện một vụ trộm bạo lực .</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
