INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-xanh-ky-la-truyen', 'Rừng Xanh Kỳ Lạ Truyện', 'Rung Xanh Ky La Truyen', 'https://phimimg.com/upload/vod/20231210-1/380ef172d81c6260ed65b9f256b9b3f8.jpg', 'https://phimimg.com/upload/vod/20231210-1/203891136545a9eeeb83593d9238dee9.jpg', '<p>Phim kể về cuộc phiêu lưu của Tarzan Việt Nam dựa theo câu chuyện có thật về người rừng nổi tiếng Hồ Văn Lang. Vô tình gặp gỡ cô tiểu thư bướng bỉnh, người rừng cảm nhận lần đầu &quot;biết yêu&quot;.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Hoài Linh","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Tiến Luật","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
