INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-ngay-xua-ay', 'Xin Chào Ngày Xưa Ấy', 'My Huckleberry Friends', 'https://phimimg.com/upload/vod/20231203-1/c7080b6c7f06be95211c1fe0746be91d.jpg', 'https://phimimg.com/upload/vod/20231203-1/c4070f24287c69b925e4c5e9ba9dfe3c.jpg', '<p>Hai mẹ con Dư Châu Châu sống nương tựa vào nhau. Ngày đầu tiên vào tiểu học, vì bị ngã mà Dư Châu Châu quen biết với một cậu bé tên Lâm Dương. Nhờ sự giúp đỡ của Lâm Dương mà cô bé đã vượt qua được những khó chịu của buổi đầu đi học, dần dần hai người trở thành những người bạn tốt của nhau. Tuy nhiên vì một số hiểu lầm mà quan hệ giữa hai người ngày càng trở nên xa cách. Lên cấp ba hai người gặp lại nhau ở Chấn Hoa cùng nhau trải qua mọi buồn vui, cùng nhau trưởng thành. Sau khi tốt nghiệp cấp ba mọi người chia nhau mỗi người mỗi ngã.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 18, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Landy Li","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Zhou Cheng Ao","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Xu Meng Yuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324406);
