INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-khoan-ma', 'Tài Khoản Ma', 'Net I Die', 'https://phimimg.com/upload/vod/20231201-1/dc4e8d4b8ffe2b29d32426eb61b68598.jpg', 'https://phimimg.com/upload/vod/20231201-1/81ba06c34915e9631e2c86e2a1b60481.jpg', '<p>Một năm sau cái chết bí ẩn của nữ Idol &quot;Monica&quot; từng rất nổi tiếng trước đó, một video về cái chết của cô ấy bỗng được lan truyền trên cộng đồng mạng, kèm theo là một hashtag kinh hoàng cùng tên của rất nhiều những Idol khác hiện tại. Một trong số đó là “Beauty Bloger “ Malisa. Cô bắt đầu gặp phải những sự cố lạ lùng. Trong khi những Idol được “tag” còn lại lần lượt chết một cách bí ẩn. Điều này làm Jak – bạn trai của Malisa – quyết định tìm ra sự thật, cứu bạn gái mình thoát khỏi cái chết kinh khủng đang đe dọa…</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sarunthorn Klaiudom","avatar":""},{"name":"Chicha Amatayakul","avatar":""},{"name":"Pitt Karchai","avatar":""},{"name":"Suchada Pramoulkan","avatar":""},{"name":"Rusameekae Fagerlund","avatar":""},{"name":"Kritsana Maroukasonthi","avatar":""},{"name":"Anothai Niruttimetee","avatar":""},{"name":"Rungtawan Chaiha","avatar":""},{"name":"Patara Eksangkul","avatar":""},{"name":"Wisansaya Pakasupakul","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
