INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cong-ly', 'Cuộc Chiến Công Lý', 'In the Fade', 'https://phimimg.com/upload/vod/20231201-1/9744088057f60df6b827b6c8c6d22506.jpg', 'https://phimimg.com/upload/vod/20231201-1/48a0e74d87654f46fc71da75233fa279.jpg', '<p>Cuộc sống của Katja sụp đổ sau một hành động vô nghĩa tác động đến cô. Sau một thời gian than khóc và chịu sự bất công, cô tìm cách trả thù.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Diane Kruger","avatar":""},{"name":"Denis Moschitto","avatar":""},{"name":"Numan Acar","avatar":""},{"name":"Johannes Krisch","avatar":""},{"name":"Ulrich Brandhoff","avatar":""},{"name":"Hanna Hilsdorf","avatar":""},{"name":"Ulrich Tukur","avatar":""},{"name":"Henning Peker","avatar":""},{"name":"Laurens Walter","avatar":""},{"name":"Uwe Rohde","avatar":""},{"name":"Aysel Iscan","avatar":""},{"name":"Christa Krings","avatar":""},{"name":"Adam Bousdoukos","avatar":""},{"name":"Jessica McIntyre","avatar":""},{"name":"Melanie Struve","avatar":""},{"name":"Samia Chancrin","avatar":""},{"name":"Karin Neu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324406);
