INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('method', 'Method', 'Method', 'https://phimimg.com/upload/vod/20231201-1/0412ddb832c474582e37d268d6676bb8.jpg', 'https://phimimg.com/upload/vod/20231201-1/cda990a34d4aa2f6bb30820ec762b720.jpg', '<p>Nam diễn viên Jae-ha (Park Sung-Woong) được chọn cho sân khấu hai người đàn ông &quot;Unchain&quot;. Cũng diễn viên cho &quot;Unchain&quot; là Idol Star Young-woo (Oh Seung-hoon). Young-woo không bị đam mê xuất hiện trong sân khấu chơi. Lúc đầu, hai người đàn ông không hòa thuận. Khi họ đắm chìm nhiều hơn trong các nhân vật mà họ chơi và câu chuyện theo chủ đề Gay, hai người đàn ông phát triển những cảm giác bất ngờ. Trong khi đó, Hee-won (Yoon Seung-ah) là bạn gái của Jae-ha. Cô có một cảm giác kỳ lạ về mối quan hệ giữa Jae-ha và Young-Woo.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Sung-woong","avatar":""},{"name":"Oh Seung-hoon","avatar":""},{"name":"Yoon Seung-ah","avatar":""},{"name":"Ryu Tae-ho","avatar":""},{"name":"Kim Bum-joon","avatar":""},{"name":"Lee Min-woong","avatar":""},{"name":"Lee Doll-hyung","avatar":""},{"name":"Kim Mi-hye","avatar":""},{"name":"Lim Jung-min","avatar":""},{"name":"Son Ji-yoon","avatar":""},{"name":"Kim Dong-seok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
