INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-cu', 'Chồng Cũ', 'Ex-Wife Killer', 'https://phimimg.com/upload/vod/20231212-1/1d3932204a979afd6a481665a1968423.jpg', 'https://phimimg.com/upload/vod/20231212-1/2aeb515edf50c10fb982159278659ee6.jpg', '<p>Khi chồng cũ của Josie, Michael, tình cờ vào cửa hàng hoa của cô với lời đề nghị kinh doanh mà cô không thể từ chối. Cô bị cuốn vào cuộc ly hôn tàn khốc giữa Michael và vợ cũ tự xưng là Cora; một cuộc ly hôn đầy sự thao túng và phản bội. Josie phải xác định ai mới thực sự là kẻ điên, ngay cả khi điều đó đồng nghĩa với việc mạo hiểm mạng sống của chính mình.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marguerite Moreau","avatar":""},{"name":"Jordan Belfi","avatar":""},{"name":"Jessica Blackmore","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324406);
