INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tad-jones-va-bi-mat-cua-vua-midas', 'Tad Jones Và Bí Mật Của Vua Midas', 'Tad Jones 2: The Hero Returns', 'https://phimimg.com/upload/vod/20231211-1/13608d7df5fda07c04048640b923b34d.jpg', 'https://phimimg.com/upload/vod/20231211-1/69bab03342e481664bd9c004ba926847.jpg', '<p>Hai năm sau cuộc phiêu lưu đầu tiên của họ, Tad Jones và Sara Lavrof có cuộc sống riêng biệt, anh là một công nhân xây dựng nghiên cứu khảo cổ học để tốt nghiệp, cô là một nhà khảo cổ nổi tiếng và thám hiểm. Sau khi khám phá bí quyết cuối cùng về sự tồn tại của chiếc vòng cổ King Midas, Sara mời Tad đến một cuộc triển lãm tại Las Vegas, nơi anh ta hy vọng cô ấy chấp nhận quay lại làm bạn gái của mình. Ngay trước khi đi du lịch, Tad nhận ra xác ướp của Paititi đã bị trục xuất từ thành phố Inca bằng cách giúp anh ta và anh ta xuất hiện trong nhà của anh ta, buộc Tad phải đi Las Vegas với chú chó Jeff và xác ướp. Nhưng tất cả những hy vọng và ước mơ của Tad đều vỡ ra khi một triệu phú tên Jack Rackham bắt cóc Sara để buộc cô tiết lộ vị trí của ba phần của vòng cổ Midas. Thành lập nhóm với Tiffany (học giả của Sara), Mummy, con chó Jeff và Belzoni (con vật cưng của Sara, chim cằn nhằn và thông minh sử dụng hóa đơn), Tad Jones và bạn bè của cậu sẽ đi khắp thế giới để giải cứu Sara và đánh bại Rackham...</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Óscar Barberán","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Adriana Ugarte","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324406);
