INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-buon-sung', 'Băng Đảng Buôn Súng', 'Strangers', 'https://phimimg.com/upload/vod/20231211-1/a3cc24a62659347a1bf5a240e30e4706.jpg', 'https://phimimg.com/upload/vod/20231211-1/e83c0b90ef1baf49c6a562dd973d5231.jpg', '<p>Phim Băng Đảng Buôn Súng - Strangers 2017: Du Miêu và Từ Thiên là hai người hoàn toàn xa lạ, gặp nhau trong tình huống hết sức bi thương. Chông chưa cưới của cô trên đường chạy trốn cảnh sát đã bắn chết bạn gái của anh chỉ vì hai bên va quẹt rồi cãi vả. Thế rồi cả hai vô tình bị vướng vào một loạt những nguy hiểm chết người giữa sự truy đuổi của cảnh sát và bọn buôn súng.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bạch Cử Cương","avatar":""},{"name":"Nhiệt Y Trát","avatar":""},{"name":"Liên Dịch Danh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
