INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-my-vi-ngot-ngao', 'Chiến Binh Mỹ Vị Ngọt Ngào', 'Kirakira Pretty Cure A La Mode The Movie', 'https://phimimg.com/upload/vod/20231210-1/268b200c3429bf8c6236e9fa1e2a751a.jpg', 'https://phimimg.com/upload/vod/20231210-1/84ab97709df27d18583f6c4de18c543b.jpg', '<p>Trước thềm cuộc thi quốc tế giữa các tiệm bánh, một con quái vật bất ngờ xuất hiện khiến các thí sinh chủ lực bị mất đi khả năng làm bánh. Nghiêm trọng hơn thiên tài làm bánh Ciel không thể biến hình thành chiến binh. Sát cánh bên nhau, các chiến binh xinh đẹp tiêu diệt con quái vật và lấy lại khả năng làm bánh cho mọi người.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fujita Saki","avatar":""},{"name":"Mori Nanako","avatar":""},{"name":"Muranaka Tomo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
