INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-thuong-tai-truong-phep-thuat-co-gai-trieu-hoi-nhung-vi-sao', 'Bất Thường Tại Trường Phép Thuật- Cô Gái Triệu Hồi Những Vì Sao', 'The Irregular At Magic High School: The Girl Who Summons The Stars', 'https://phimimg.com/upload/vod/20231210-1/188e6350bf3ee6387df76cedb4e979e5.jpg', 'https://phimimg.com/upload/vod/20231210-1/f7a0a84cc042ce5bd3371941b4c306cc.jpg', '<p>Phép thuật, đó không còn là truyền thuyết hay một câu chuyện cổ tích nữa.Nó đã trở thành một công nghệ thực tiễn từ gần một thế kỷ nay. Pháp sư, đó là cách mà người ta gọi những con người mang trong mình một tài năng phép thuật ưu việt. Đối với các quốc gia, sự tồn tại của con người này chính là những vũ khí mạnh mẽ. Nhiều quốc gia trên thế giới đã bị cuốn vào vòng xoáy của cuộc chạy đua trên lĩnh vực đào tạo ma pháp.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuichi Nakamura","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Atsushi Tamaru","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324406);
