INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-thuy-tinh', 'Lâu Đài Thủy Tinh', 'The Glass Castle', 'https://phimimg.com/upload/vod/20231130-1/0e64d2a86feb3255bedec906a4521e6f.jpg', 'https://phimimg.com/upload/vod/20231130-1/6eb048ece2e9e4c206fabab5618e4c70.jpg', '<p>Một cô gái trẻ lớn lên trong một gia đình có quá khứ rối loạn, chính vì quá khứ này mà họ không hề có một cuộc sống yên ổn, hằng ngày họ luôn phải liên tục chạy trốn khỏi FBI. Sống trong cảnh đói nghèo, cô chât vật để đi đến đến tuổi trưởng thành và được nuôi dưỡng bởi người cha say rượu của mình. Gia đình cô không chỉ có cha cô là người nghiện rượu, mẹ cô còn là một người phụ nữ, một người mẹ ích kỷ, người không có ý định nuôi con trong gia đình. Anh trai và em gái, và chị gái khác của cô cũng chỉ mặc nhiên sống theo ý thích của họ, họ không quan tâm xem những người xung quanh đang thực sự có cuộc sống như thế nào. Hiện tại, một biến cố khác xảy ra khiến gia đình họ đã biết cùng nhau, họ phấn đấu vì nhau để trưởng thành và có thể thích ứng với sự biến đổi cuộc sống liên tục của gia đình họ. Liệu họ có thể hàn gắn lại với nhau và thoát tội bị FBI gán cho hay không?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brie Larson","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Max Greenfield","avatar":""},{"name":"Sarah Snook","avatar":""},{"name":"Ella Anderson","avatar":""},{"name":"Sadie Sink","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Chandler Head","avatar":""},{"name":"Iain Armitage","avatar":""},{"name":"Brigette Lundy-Paine","avatar":""},{"name":"Josh Caras","avatar":""},{"name":"Olivia Kate Rice","avatar":""},{"name":"Charlie Stowell","avatar":""},{"name":"Charlie Guyon","avatar":""},{"name":"Noemie Guyon","avatar":""},{"name":"Eden Grace R","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
