INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-tuong-cuoi-cung', 'Bức Tường Cuối Cùng', 'The Wall', 'https://phimimg.com/upload/vod/20231130-1/9b6ca6abb29906350edf49a690f9442f.jpg', 'https://phimimg.com/upload/vod/20231130-1/57dad9582c29d130b78d633334e77587.jpg', '<p>Cuối năm 2007, Tổng Thống Bush tuyên bố quân Mỹ dành thắng lợi tại chiến trường Iraq. Đã có một cuộc thảm sát xảy ra, 2 lình Mỹ gồm Isaac và Matthews tham thính tình hình. Cả 2 đã bị một tên lính bắn tỉa với biệt danh Juba gài bẫy. Ngăn cách giữa họ và tên sát nhân chỉ là một bức tường mong manh.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"John Cena","avatar":""},{"name":"Laith Nakli","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
