INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-nguoi-giu-thu', 'Vợ Người Giữ Thú', 'The Zookeeper''s Wife', 'https://phimimg.com/upload/vod/20231130-1/c371e830d9d839478aa43898413ce3a5.jpg', 'https://phimimg.com/upload/vod/20231130-1/121d6ffdb6e6a10bfcbda92c219b0624.jpg', '<p>Phim Vợ Của Người Giữ Sở Thú - The Zookeeper&quot;s Wife: thuộc dạng tâm lý Mỹ sản xuất năm 2017, do đạo diễn Niki Caro phụ trách chỉ đạo, kết hợp cùng các diễn viên Daniel Brühl, Jessica Chastain, Johan Heldenbergh,...Phim dựa theo 1 câu chuyện có thật xảy ra vào năm 1931 lúc này quân phát xít Đức đã đánh chiếm Ba Lan. Có 2 vợ chồng là cô Antonina Zabinskis &nbsp;cùng chồng là tiến sĩ Jan Zabinskis đang điều hành vườn thú Warsaw, họ đã ra tay giúp đỡ những người Do Thái lẩn trốn khỏi sự tàn sát diệt chủng. Nhờ sự liều lĩnh, nổ lực của 2 vợ chồng tốt bụng mà biến họ thành người hùng cứu sống hàng trăm người trong Thế chiến thứ II.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Johan Heldenbergh","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Timothy Radford","avatar":""},{"name":"Efrat Dor","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Shira Haas","avatar":""},{"name":"Val Maloku","avatar":""},{"name":"Martha Issová","avatar":""},{"name":"Frederick Preston","avatar":""},{"name":"Goran Kostić","avatar":""},{"name":"Anna Rust","avatar":""},{"name":"Daniel Ratimorský","avatar":""},{"name":"Theo Preston","avatar":""},{"name":"Viktoria Zakharyanova","avatar":""},{"name":"Ar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c38711