INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-anh-ma-am-2', 'Bức Ảnh Ma Ám 2', 'The Haunted Graduation Photo 2', 'null', 'https://phimimg.com/upload/vod/20231129-1/1ede9e5ad1fe414a451f107b8ff4eb35.jpg', '<p>Bức Ảnh Ma Ám 2 - The Haunted Graduation Photo 2 lấy bối cảnh một vài tháng sau các sự kiện của phần đầu tiên. Lần này, nhóm bạn quay trở lại khuôn viên trại của phần đầu tiên khi linh hồn của Phiêu Phiêu dường như vẫn còn ám ảnh họ. Nhóm bạn lại tiến hành lễ cầu hồn gọi Phiêu Phiêu, nhưng liệu thế đã đủ giúp họ thoát khỏi những ám ảnh kinh hoàng?</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Yuan","avatar":""},{"name":"Liu Li-Er","avatar":""},{"name":"Song Wei","avatar":""},{"name":"Jinglei Nie","avatar":""},{"name":"Yat Boon-Chai","avatar":""},{"name":"Qian Li","avatar":""},{"name":"Chong-er Liu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
