INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-nghiep-kien-quan', 'Đại Nghiệp Kiến Quân', 'The Founding of An Army', 'https://phimimg.com/upload/vod/20231129-1/26a707e334730b3572cdba7dd991e97f.jpg', 'https://phimimg.com/upload/vod/20231129-1/15ae8d5066d6aa296a28a1f4695ba498.jpg', '<p>Đại Nghiệp Kiến Quân - The Founding of An Army lấy bối cảnh năm 1927, nhân lúc cuộc chiến phương Bắc đạt được những thành quả quan trọng. Quốc Dân đảng (Phe Tưởng) vì tranh giành quyền lực cách mạng, đã phát động chiến dịch Thanh Cộng. Chỉ trong vài tháng, gần 31 vạn người bị giết hại dã man, làm chấn động cả quốc gia.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Ye","avatar":""},{"name":"Zhu Yawen","avatar":""},{"name":"Huang Zhizhong","avatar":""},{"name":"Chen Xiao","avatar":""},{"name":"Wang Jingchun","avatar":""},{"name":"Oho Ou","avatar":""},{"name":"Liu Haoran","avatar":""},{"name":"Ma Tianyu","avatar":""},{"name":"Zhang Yixing","avatar":""},{"name":"Li Yifeng","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Liang Dawei","avatar":""},{"name":"Dong Zijian","avatar":""},{"name":"Ashton Chen","avatar":""},{"name":"Li Xian","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Guan Xiaotong","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Han Geng","avatar":""},{"name":"Wallace Huo","avatar":""},{"name":"Zhang Tian�","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324406);
