INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-troi-day-2017', 'Cuộc Trỗi Dậy', 'Revolt', 'https://phimimg.com/upload/vod/20231129-1/7398f582cea1c18562c0bb3a910f9050.jpg', 'https://phimimg.com/upload/vod/20231129-1/629d61fa8526c29a8c1139a069765445.jpg', '<p>Một lính Mỹ bị hội chứng quên bị nhốt trong phòng giam kế bên vị bác sĩ người Pháp xinh xắn. Trái Đất bị bầy robot khổng lồ ngoài hành tinh tấn công. Lính Kenya xông đến định hãm hiếp, tra tấn và...</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lee Pace","avatar":""},{"name":"Bérénice Marlohe","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Sibulele Gcilitshana","avatar":""},{"name":"Wandile Molebatsi","avatar":""},{"name":"Sekoati Tsubane","avatar":""},{"name":"Leroy Gopal","avatar":""},{"name":"Welile Nzuza","avatar":""},{"name":"Patrick Bokaba","avatar":""},{"name":"Tom Fairfoot","avatar":""},{"name":"Ben Tjibe","avatar":""},{"name":"Chantal Herman","avatar":""},{"name":"Barileng Malabye","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324406);
