INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-tham-hoa', 'Sau Thảm Họa', 'Aftermath', 'https://phimimg.com/upload/vod/20231129-1/20668d529ed4ba61843f121a618d0c14.jpg', 'https://phimimg.com/upload/vod/20231129-1/78b6a2626a1ab5e8fdc0688880d3f592.jpg', '<p>Cuộc sống của hai người lạ bị ràng buộc chặt chẽ với nhau sau một vụ tai nạn máy bay tàn khốc. Lấy cảm hứng từ các sự kiện thực tế, hậu quả kể một câu chuyện về cảm giác tội lỗi và trả thù sau một số lỗi của người điều khiển không lưu (Scoot McNairy) gây ra cái chết của vợ và con gái của người quản lý xây dựng (Arnold Schwarzenegger).</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Maggie Grace","avatar":""},{"name":"Judah Nelson","avatar":""},{"name":"Larry Sullivan","avatar":""},{"name":"Jason McCune","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Mariana Klaveno","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Hannah Ware","avatar":""},{"name":"Christopher Darga","avatar":""},{"name":"Teri Clark","avatar":""},{"name":"Danielle Sherrick","avatar":""},{"name":"Jeff Panzarella","avatar":""},{"name":"Mo McRae","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Lewis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
