INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alien-convergence', 'Alien Convergence', 'Alien Convergence', 'https://phimimg.com/upload/vod/20231129-1/e7b975f97cb0e06f3a6581c5f720a5ee.jpg', 'https://phimimg.com/upload/vod/20231129-1/71a2b5c214fb304921581d933e458a4e.jpg', '<p>Một đội ngũ nhân viên dịch vụ khuyết tật phát triển một mặt phẳng máy bay chiến đấu được kiểm soát cách mạng được áp dụng vào dịch vụ để đẩy lùi một cuộc xâm lược của người ngoài hành tinh.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Caroline Ivari","avatar":""},{"name":"Mishone Feigin","avatar":""},{"name":"Ikaika Jonathan","avatar":""},{"name":"Michael Marcel","avatar":""},{"name":"Britt George","avatar":""},{"name":"Ana Zimhart","avatar":""},{"name":"Dennis Renard","avatar":""},{"name":"Brandon George","avatar":""},{"name":"Mike Duff","avatar":""},{"name":"Kevin Duffin","avatar":""},{"name":"Natalia Herrera","avatar":""},{"name":"Sarah Bartholomew","avatar":""},{"name":"Jude Williams","avatar":""},{"name":"Sari Sabella","avatar":""},{"name":"Darnell Baldwin","avatar":""},{"name":"David Garegnani","avatar":""},{"name":"Susan Mo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324406);
