INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-cu-dong-bac-pha-ma-truong-phi', 'Chuyện Cũ Đông Bắc: Phá Mã Trương Phi', 'Once Upon A Time In The Northeast', 'https://phimimg.com/upload/vod/20231209-1/9a1dfa3d1f6ca8eef510d25bbae20cd3.jpg', 'https://phimimg.com/upload/vod/20231209-1/f8dcb4a26349a7d8b33416e67f7f97bb.jpg', '<p>Phim lấy bối cảnh tại một cô nhi viện nghèo tại miền Đông Bắc Trung Quốc, vì nợ nần mà rơi vào bẫy của một công ty xã hội đên Hồng Kông. Để cứu lấy mái nhà, các thành viên tại đây năm lần bảy lượt lên kế hoạch tìm cách ngắn cản, gây ra nhiều tình huống dở khóc dở cười, tao nên một câu chuyện vừa hài hước vùa mang màu sắc ” anh hùng”.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quách Đại Lôi","avatar":""},{"name":"Giả Nãi Lượng","avatar":""},{"name":"Mã Lệ","avatar":""},{"name":"Vương Tân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
