INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-cu-dong-bac-pha-ma-truong-phi', 'Chuyện Cũ Đông Bắc: Phá Mã Trương Phi', 'Once Upon A Time In The Northeast', 'chuyện cũ đông bắc: phá mã trương phi once upon a time in the northeast quách đại lôi giả nãi lượng mã lệ vương tân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-2017', 'Vỏ Bọc Ma', 'Ghost in the Shell', 'https://phimimg.com/upload/vod/20231025-1/e146f72f9ca12ca5b180fc152cf6fd22.jpg', 'https://phimimg.com/upload/vod/20231025-1/0700ef3ec4ba4d2fcc9956045a265b57.jpg', '<p>Scarlett Johansson vào vai trong Vỏ Bọc Ma với hình ảnh lộng lẫy, một bộ phim phiêu lưu hành động lấy bối cảnh thế giới tương lai nơi con người được cải tiến bằng công nghệ. Tin rằng mình được cứu khỏi cái chết, Major (Johansson) trở thành cá thể đầu tiên trong loài của cô: trí não con người trong cơ thể nhân tạo được thiết kế để thực thi cuộc chiến chống tội ác điện tử. Khi điều tra một tội phạm nguy hiểm, Major phát hiện ra sự thật choáng váng - tập đoàn tạo ra cô đã dối trá về cuộc đời của cô trước đây để điều khiển cô. Hoang mang không biết tin vào gì, Major bất chấp mọi điều nhằm làm sáng tỏ bí mật về thân thế thực của bản thân và để báo thù tổ chức mà cô được tạo nên để phụng sự.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Takeshi Kitano","avatar":""},{"name":"Michael Pitt","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Peter Ferdinando","avatar":""},{"name":"Rila Fukushima","avatar":""},{"name":"Daniel Henshall","avatar":""},{"name":"Yutaka Izumihara","avatar":""},{"name":"Anamaria Marinca","avatar":""},{"name":"Kaori Momoi","avatar":""},{"name":"Lasarus Ratuere","avatar":""},{"name":"Danusia Samal","avatar":""},{"name":"Tawanda Manyimo","avatar":""},{"name":"Mana Hira Davis","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324406);
