INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-anh-la-chuyen-nho-2017', 'Tiếng Anh Là Chuyện Nhỏ', 'I Can Speak', 'https://phimimg.com/upload/vod/20231101-1/0184ccea5160b5d69f9a25e06a1e53c4.jpg', 'https://phimimg.com/upload/vod/20231101-1/0a856aa7106f2b6729da2be4878bca55.jpg', '<p>Phim Tiếng Anh Là Chuyện Nhỏ - I Can Speak 2017: Câu chuyện về một bà giá &quot;khó ở&quot; khiếu nại đủ thứ ở khu dân cư. Anh chàng nhân viên tiếp dân bất đắc dĩ trở thành giáo viên dạy tiếng Anh cho bà và phát hiện ra mọi chuyện đằng sau. Ok-boon là nỗi ám ảnh của văn phòng công dân với kỷ lục trên 8.000 đơn khiếu nại kiên trì suốt 20 năm ròng rã về các vi phạm từ bé đến lớn xảy ra trong khu dân cư. Min-jae là chàng nhân viên tiếp dân mới đụng độ “bà già tinh quái” ngay ngày đi làm đầu tiên vỡi những ấn tượng không hề tốt đẹp với nhau. Không ngờ, bà Ok-boon năn nỉ anh chàng dạy tiếng Anh cho mình. Sau khi dành nhiều thời gian cho nhau qua những buổi “học thêm”, Min-jae dần khám phá ra một sự việc xúc động.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Na Moon-hee","avatar":""},{"name":"Lee Je-hoon","avatar":""},{"name":"Seong Yu-bin","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Jeong Yeon-joo","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Son Sook","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Choi Soo-in","avatar":""},{"name":"Lee Jae-in","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Kim Il-woong","avatar":""},{"name":"Kim Ja-young","avatar":""},{"name":"Cho Wan-ki","avatar":""},{"name":"Lee Shin-seong","avatar":""},{"name":"Kim Seon-kyeong","avatar":""},{"name":"Jo Hyun-i","avatar":""}]', '[{"name":"Chính 