INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-quyen-anh-2017', 'Võ Sĩ Quyền Anh', 'Jawbone', 'https://phimimg.com/upload/vod/20231101-1/cbba3c8a0ad49c17e2742176a02b638f.jpg', 'https://phimimg.com/upload/vod/20231101-1/7cb57c4b7ebe0e5ec78bf8621bb2dcd3.jpg', '<p>Phim Võ Sĩ Quyền Anh - Jawbone 2017: Cựu vô địch quyền anh thanh thiếu niên, Jimmy McCabe, là một người đang tìm kiếm hy vọng nhưng toàn nhầm chỗ. Khi anh ấy rơi vào hoàn cảnh khó khăn, anh ấy quay lại câu lạc bộ quyền anh thời thơ ấu của mình và gia đình duy nhất mà anh ấy từng bỏ lại: chủ phòng gym Bill, chăm sóc viên Eddie, và nhà tài trợ Joe. Trở lại luyện tập sau nhiều năm, khi chẳng còn ai coi anh là đối thủ nữa, Jimmy đánh cược cả sinh mạng của mình, để trụ vững và lấy lại vị trí mà anh từng có.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Johnny Harris","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Michael Smiley","avatar":""},{"name":"Luke J.I. Smith","avatar":""},{"name":"Anna Wilson-Hall","avatar":""},{"name":"Jermaine Allen","avatar":""},{"name":"Archie Cocker","avatar":""},{"name":"Stacey Lynn Crowe","avatar":""},{"name":"Marilyn May James","avatar":""},{"name":"Atul Sharma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
