INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-chen-thanh-loi-the-duoi-tuyet', 'Cuộc Chiến Chén Thánh: Lời Thề Dưới Tuyết', 'Fate/Kaleid Liner Prisma Illya: The Movie - Oath Under Snow', 'https://phimimg.com/upload/vod/20231129-1/58f6ea155411a582ae8f47d2ec9f5dba.jpg', 'https://phimimg.com/upload/vod/20231129-1/1f8f94673c97ddd094d22376143d7482.jpg', '<p>Sự hủy diệt của trái đất đang diễn ra. Điều duy nhất có thể vãn hồi thế giới này đó là sự hi sinh của Miyu. Khi Ainsworth hỏi Illya – người mang danh nghĩa vị-cứu-tinh của thế giới, rằng cô sẽ chọn thế giới hay Miyu. Cô đã đáp lại một câu trả lời đơn giản và có phần “ích kỉ” – “CẢ HAI”. &nbsp;Trong khoảng thời gian nghỉ ngơi, họ sống cùng nhà với Miyu và Shirō. Khi họ quây quần lại một chỗ, Shirō đã kể cho họ nghe về bản thân mình và Miyu. Miyu là Đứa trẻ của Chúa – người có thể ban tặng mọi điều mà cô muốn. Shirō đã nhận Miyu – một cô gái “tứ cố vô thân” vào nhà… Và sau 5 năm kể từ ngày đó đến nay họ sống với nhau như anh chị em ruột vậy. Nhưng cuộc sống an bình của hai người đã bị phá vỡ. Họ đã đem cô ấy đi, trước đó, Julian đã xuất hiện và tiếp tục tìm kiếm sức mạnh trong Miyu mà hắn ta cần.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Noriaki Sugiyama","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Noriko Shitaya","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Jouji Nakata","avatar":""},{"name":"Naoko Takano","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Mai Kadowaki","avatar":""},{"name":"Kana Ueda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324406);
