INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-shimmer', 'Hồ Shimmer', 'Shimmer Lake', 'https://phimimg.com/upload/vod/20231129-1/89d33d4e50c8258d8d14b0d15373c3b9.jpg', 'https://phimimg.com/upload/vod/20231129-1/3147590aa22f1bbc19cd227b763b19ba.jpg', '<p>Bộ phim giật gân tội phạm hài đen tối này đi ngược thời gian, theo cảnh sát trưởng địa phương săn lùng 3 nghi phạm cướp ngân hàng, một trong số đó là anh trai của anh ta.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"Benjamin Walker","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Ron Livingston","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Stephanie Sigman","avatar":""},{"name":"Mark Rendall","avatar":""},{"name":"Julie Khaner","avatar":""},{"name":"Karl Campbell","avatar":""},{"name":"Angela Vint","avatar":""},{"name":"Jordan Duarte","avatar":""},{"name":"Matthew Evans Landry","avatar":""},{"name":"Adam Saunders","avatar":""},{"name":"Neil Whitely","avatar":""},{"name":"Isabel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
