INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-nhai-tieng', 'Kẻ Nhại Tiếng', 'The Mimic', 'https://phimimg.com/upload/vod/20231129-1/411f8b4fc74e1944b56f8de2e6bca422.jpg', 'https://phimimg.com/upload/vod/20231129-1/c78ccd160e95a2a0db3a52cd68751355.jpg', '<p>Kẻ Bắt Chước (The Mimic) lấy cảm hứng từ câu truyện ma dân gian nổi tiếng của Hàn Quốc - Con Hổ trên núi Jang - câu truyện kể về một sinh vật hắc ám có khả năng giả giọng nói để đánh lừa con người và ăn thịt họ. Kẻ Bắt Chước kể về một gia đình nọ sau sự biến mất bí ẩn của đứa con trai nhỏ, cả nhà 3 người gồm người mẹ Hee Yeon cùng chồng và cô con gái út đã quyết định chuyển về quê hương của Hee Yeon - một ngôi làng hẻo lánh gần núi Jang để sinh sống nhằm cải thiện bệnh tình và tâm trạng của cô. Hee Yeon liên tục nghe được những tiếng thì thầm và giọng nói kỳ lạ, những giọng nói này đưa Hee Yeon tới một cái hang trên ngọn núi Jang.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Yum Jung-ah","avatar":""},{"name":"Park Hyeok-kwon","avatar":""},{"name":"Heo Jin","avatar":""},{"name":"Shin Rin-a","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Noh Susanna","avatar":""},{"name":"Jung Ji-hoon","avatar":""},{"name":"Lee Yool","avatar":""},{"name":"Lee Chae-eun","avatar":""},{"name":"Hwang Jae-won","avatar":""},{"name":"Jang Liu","avatar":""},{"name":"Lim Jong-yun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
