INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-la-columbus', 'Đây Là Columbus', 'Columbus', 'https://phimimg.com/upload/vod/20231129-1/7160a4bf956afcc915320fc657b2925a.jpg', 'https://phimimg.com/upload/vod/20231129-1/991975d15f289dd3e080749f2574cf0f.jpg', '<p>Đây Là Columbus - Columbus (2017):Một chàng trai gốc Hàn Quốc kẹt lại ở Columbus, Indiana do người cha làm kiến trúc sư của anh đang trong tình trạng hôn mê. Anh gặp một cô gái muốn ở lại Columbus với mẹ mình - đang trong quá trình cai nghiện - mà từ bỏ việc theo đuổi ước mơ của cô.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cho","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Michelle Forbes","avatar":""},{"name":"Rory Culkin","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Erin Allegretti","avatar":""},{"name":"Shani Salyers Stiles","avatar":""},{"name":"Reen Vogel","avatar":""},{"name":"Rosalyn R. Ross","avatar":""},{"name":"Lindsey Shope","avatar":""},{"name":"Jem Cohen","avatar":""},{"name":"Caitlin Ewald","avatar":""},{"name":"Jim Dougherty","avatar":""},{"name":"Joseph Anthony Foronda","avatar":""},{"name":"Alphaeus Green","avatar":""},{"name":"Jr.","avatar":""},{"name":"Wynn Reiche","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
