INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-vung-ngoai-o', 'Bí Ẩn Vùng Ngoại Ô', 'Suburbicon', 'https://phimimg.com/upload/vod/20231129-1/358b67b1c9fab214d9f2f30782399626.jpg', 'https://phimimg.com/upload/vod/20231129-1/45474a5058bbf561c4c20070503b8115.jpg', '<p>&quot;Bí Ẩn Vùng Ngoại Ô&quot; có một điểm cộng là tất cả các nhân vật xuất hiện trong phim đều không hề “đơn thuần”, họ đều có cho riêng mình những góc tối và bí mật, khiến khán giả khó lòng có thể đặt trọn niềm tin vào bất cứ ai xuyên suốt toàn bộ phim. Thị trấn này có một vẻ bề ngoài yên bình, thân thiện, an toàn, văn minh và là một nơi lý tưởng để sinh sống. Thế nhưng thực chất thì đó chỉ là lớp mặt nạ bao bọc bên ngoài một xã hội mục nát với những con người giả tạo, tham lam, bạo lực, thấp hèn và mang tư tưởng phân biệt chủng tộc nặng nề. Hành trình Lodge cố gắng tìm ra sự thật về cái chết của vợ mình cũng là lúc mà chiếc mặt nạ bị lột bỏ, bản chất của thị trấn dần bị phơi bày.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Landon Gordon","avatar":""},{"name":"Glenn Fleshler","avatar":""},{"name":"Alex Hassell","avatar":""},{"name":"Karimah Westbrook","avatar":""},{"name":"Tony Espinosa","avatar":""},{"name":"Leith M. Burke","avatar":""},{"name":"Gary Basaraba","avatar":""},{"name":"Jack Conley","avatar":""},{"name":"Megan Ferguson","avatar":""},{"name":"Lauren Burns","avatar":""},{"name":"Steve Monroe","avatar":""},{"name":"James Handy","avatar":""},{"name":"Hope Banks","avatar":""},{"name":"Michael D.","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324406);
