INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-toi-di', 'Giết Tôi Đi', 'Kill Me Please', 'https://phimimg.com/upload/vod/20231129-1/1fb0245dff147a6294ab43e357b13fea.jpg', 'https://phimimg.com/upload/vod/20231129-1/9ffc36ef6ec7eda94912a0a3f3e7ab2f.jpg', '<p>Nhận được tin sét đánh mình mắc bệnh ung thư thời kì cuối, Đại Vệ quyết định “chết ngoài ý muốn” để gạt tiền bảo hiểm. Anh sang Thái tìm vợ để từ biệt và tự kết liễu nhưng toàn thất bại. Và rồi chuyện dở khóc dở cười xảy đến khi anh thuê sát thủ giết mình, vừa vô tình vướng vào mâu thuẫn của băng nhóm xã hội đen</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Xun","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Yu Shasha","avatar":""},{"name":"Zhao Yingjun","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Kim Sung Joo","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Liang Jin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324406);
