INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-2017', 'Sự Thật', 'Real', 'https://phimimg.com/upload/vod/20231129-1/e2e8f1967917d6aeabcd9192976e075c.jpg', 'https://phimimg.com/upload/vod/20231129-1/d648032f69bcfa76b5def259e25298a9.jpg', '<p>Real xoay quanh nhân vật Jang Tae Young (Kim Soo Hyun), người đàn ông lạnh lùng và tham vọng, làm việc cho thế giới ngầm. Anh bị đồng tiền mê hoặc và muốn xây dựng một khách sạn casino để điều khiển cả thành phố. Tuy nhiên, mọi thứ bắt đầu rơi khỏi tầm kiểm soát khi một phóng viên theo đuôi Jang Tae Young xuất hiện. Sulli đảm nhận vai Song Yoo Hwa, một nhà vật lý trị liệu. Tác phẩm dán nhãn 19+ vì có nhiều cảnh bạo lực và tình cảm giữa hai nhân vật chính.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Soo-hyun","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Sulli","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Jung In-gyeom","avatar":""},{"name":"Choi Kwon","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Jung Yi-seo","avatar":""},{"name":"Lee Jung-hyun","avatar":""},{"name":"Son Hyun-joo","avatar":""},{"name":"Park Seo-jun","avatar":""},{"name":"Kim Da-som","avatar":""},{"name":"An So-hee","avatar":""},{"name":"Bae Suzy","avatar":""},{"name":"Gyeongree","avatar":""},{"name":"Park Min-ha","avatar":""},{"name":"Ah Ri","avatar":""},{"name":"Ji Eun-seo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
