INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-rut-cuong-loan', 'Vi Rút Cuồng Loạn', 'Mayhem', 'https://phimimg.com/upload/vod/20231129-1/4f7a9b3ee198cf6217f9d140f3a4eb14.jpg', 'https://phimimg.com/upload/vod/20231129-1/475705d68ed6f0472ad31f4b9cee2216.jpg', '<p>Một loại virus bí ẩn có tên là “Red Eye” ID-7 đã và đang lây lan khắp thế giới. Nó không gây chết người, nhưng khiến cho người bị nhiễm trở nên bạo lực và đen tối. Bạo loạn bắt đầu xảy ra khắp nơi và số người chết ngày càng gia tăng.Một buổi sáng nọ, khi đang làm việc tại tòa nhà TSC, Derek bất ngờ nhận được thông tin tòa nhà đang được đặt trong tình trạng cách ly vì virus ID-7 đã được phát hiện trong hệ thống thông gió. Một chất trung hòa đã được thả vào tòa nhà, ước tính khoảng 8 giờ để virus bị tiêu diệt. Tuy nhiên, tất cả mọi người trong tòa nhà đều bị nhiễm bệnh và tình trạng bạo lực bắt đầu bùng nổ.Liệu Derek sẽ làm gì để ngăn bản thân trở thành nạn nhân tiếp theo của con virus quái ác này?</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Yeun","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Steven Brand","avatar":""},{"name":"Caroline Chikezie","avatar":""},{"name":"Kerry Fox","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Mark Frost","avatar":""},{"name":"André Eriksen","avatar":""},{"name":"Claire Dellamar","avatar":""},{"name":"Nikola Kent","avatar":""},{"name":"Lucy Chappell","avatar":""},{"name":"Bojan Perić","avatar":""},{"name":"Annamaria Serda","avatar":""},{"name":"Jovana Prosenik","avatar":""},{"name":"Nina Seničar","avatar":""},{"name":"Vladimir Aleksić","avatar":""},{"name":"Scott Alexander","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
