INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-anh-em-2017', 'Tình Anh Em', 'Tubelight', 'https://phimimg.com/upload/vod/20231115-1/5f20fff5faee8cd99b8d9b21f217149e.jpg', 'https://phimimg.com/upload/vod/20231115-1/360442f387355c0e3294f6b61506c017.jpg', '<p>Năm 1962, Trung Quốc đã phát động cuộc chiến tranh xâm lược biên giới Ấn Độ. Trong hoàn cảnh đó, nhiều người con ưu tú của Ấn Độ đã không quản ngại tình nguyện ra chiến tuyến, trong đó có Bharat. Bharat đã tạm chia tay người anh trai của mình là Laxman để một mình xông pha trận mạc. Xuyên suốt bộ phim và sự mâu thuẫn về nội tâm của Laxman khi anh quyết định kết bạn với một cậu bé người Ấn gốc Trung. Bộ phim cũng đề cao tư tưởng &quot;bất bạo động&quot; của Gandhi để từ đó mà nhân dân Ấn Độ đã trở nên khoan dung và vị tha với những người được coi là kẻ thù ở bên kia chiến tuyến...</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Sohail Khan","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Yashpal Sharma","avatar":""},{"name":"Mohammed Zeeshan Ayyub","avatar":""},{"name":"Matin Rey Tangu","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Brijendra Kala","avatar":""},{"name":"Isha Talwar","avatar":""},{"name":"Shah Rukh Khan","avatar":""},{"name":"Chien Ho Liao","avatar":""},{"name":"Jason D''Souza","avatar":""},{"name":"Neeraj Khetrapal","avatar":""},{"name":"Kapil Sharma","avatar":""},{"name":"Alok Gagdekar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324406);
