INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-chia-cach-chung-ta', 'Những Điều Chia Cách Chúng Ta', 'All That Divides Us', 'https://phimimg.com/upload/vod/20231129-1/a20a24e7c5f51e07c64ea00ee56188c6.jpg', 'https://phimimg.com/upload/vod/20231129-1/03b8f07e699c655f7888ce51a91c3c9e.jpg', '<p>Bị tàn tật sau một tai nạn, Julia buộc phải sống cùng mẹ và tìm đến chất kích thích để quên đi bất hạnh của bản thân. Trong một lần ẩu đả với nhân tình và cũng là kẻ cung cấp thuốc cho cô, Julia đã lỡ tay giết người. Với sự giúp đỡ của mẹ, Julia đã che giấu thành công tội ác của mình. Nhưng cơn ác mộng của họ thật ra chỉ mới bắt đầu.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Catherine Deneuve","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Ken Samaras","avatar":""},{"name":"Nicolas Duvauchelle","avatar":""},{"name":"Sébastien Houbani","avatar":""},{"name":"Michaël Cohen","avatar":""},{"name":"Olivier Loustau","avatar":""},{"name":"Brigitte Sy","avatar":""},{"name":"Julia Faure","avatar":""},{"name":"Élizabeth Mazev","avatar":""},{"name":"Virgile Bramly","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
