INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-soi-chi', 'Bóng Ma Sợi Chỉ', 'Phantom Thread', 'https://phimimg.com/upload/vod/20231128-1/8b6d95d040506fc5617ea73c94cc5d70.jpg', 'https://phimimg.com/upload/vod/20231128-1/d68f894cefe3ee5780e1705c23ca275f.jpg', '<p>Sống trong guồng quay bận rộn cùng với tính chất công việc của ngành thời trang, nhà thiết kế thời trang tài năng Reynolds Woodcock (Daniel Day-Lewis) luôn được vây quanh bởi những minh tinh màn bạc, ngôi sao nổi tiếng, thậm chí cả những giai nhân giàu có bậc nhất trong giới quý tộc thời bấy giờ. Tuy nhiên, phải đến một ngày, trái tim của nhà thiết kế đa tình ấy mới thật sự bắt đầu “loạn nhịp” khi chạm mặt Alma (Vicky Krieps), một cô gái trẻ tuổi với dáng vẻ tự tin và luôn tràn đầy sức sống.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Camilla Rutherford","avatar":""},{"name":"Gina McKee","avatar":""},{"name":"Brian Gleeson","avatar":""},{"name":"Harriet Sansom Harris","avatar":""},{"name":"Lujza Richter","avatar":""},{"name":"Julia Davis","avatar":""},{"name":"Julie Vollono","avatar":""},{"name":"Sue Clark","avatar":""},{"name":"Joan Brown","avatar":""},{"name":"Harriet Leitch","avatar":""},{"name":"Dinah Nicholson","avatar":""},{"name":"Julie Duck","avatar":""},{"name":"Maryanne Frost","avatar":""},{"name":"Elli Bank","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
