INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sandy-wexler', 'Sandy Wexler', 'Sandy Wexler', 'https://phimimg.com/upload/vod/20231128-1/778f2e95a18477e0a2d1d27a8b6c1148.jpg', 'https://phimimg.com/upload/vod/20231128-1/bd22fb6ff9907026a4fa7ff669527329.jpg', '<p>Nhờ ký được hợp đồng với khách hàng đầu tiên thực sự có tài năng, cuối cùng thì sự nghiệp của nhà quản lý tài năng tâm huyết nhưng đen đủi cũng bắt đầu nở hoa.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Colin Quinn","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Aaron Neville","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Sandy Wernick","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Sadie Sandler","avatar":""},{"name":"Sunny Sandler","avatar":""},{"name":"Jared Sandler","avatar":""},{"name":"Arsenio Hall","avatar":""},{"name":"Quincy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324406);
