INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoa-thuan-trieu-do', 'Thỏa Thuận Triệu Đô', 'Scramble', 'https://phimimg.com/upload/vod/20231127-1/12f1be5388f9e52d1ce7d02554e5ec25.jpg', 'https://phimimg.com/upload/vod/20231127-1/a10128741fc7056ad3c8a063dc0c0714.jpg', '<p>Khi bạn gái bị bắt cóc bởi một đường dây mại dâm ngầm, Frank và Simon, bạn thân của anh ta đã vay tiền chuộc từ một tỷ phú tên là The Kid. Để trả nợ cho khoản vay, hai người bạn phải thực hiện một loạt các nhiệm vụ đối đầu, ám sát những tên xã hội đen tàn bạo nhất châu Á. Trong khi đó, chính đường dây mại dâm cũng đang bị tấn công bởi một cặp sát thủ bí ẩn.</p>', 'Full', 1, 'single', 'completed', 6, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Irina Voronina","avatar":""},{"name":"Damien Puckler","avatar":""},{"name":"Victor Kelso","avatar":""},{"name":"Marissa Von Bleicken","avatar":""},{"name":"Brett A. Newton","avatar":""},{"name":"Germaine De Leon","avatar":""},{"name":"Chelsea Gilson","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Eva Skye","avatar":""},{"name":"Jackie Becker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324406);
