INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wonder-woman-nu-than-chien-binh', 'Wonder Woman: Nữ Thần Chiến Binh', 'Wonder Woman', 'https://phimimg.com/upload/vod/20231129-1/89a44eb06f9c334df1c043886ca874a7.jpg', 'https://phimimg.com/upload/vod/20231129-1/10f37ff918b85bf97889759018ad3eae.jpg', '<p>Trước khi trở thành Wonder Woman, Diana là công chúa chiến binh Amazon của hòn đảo Themyscira. Khi chàng phi công Steve Trevor trôi dạt vào đảo và kể về cuộc đại chiến đang diễn ra tại thế giới bên ngoài, Diana quyết định rời khỏi quê nhà để giải cứu nhân loại. Từ đó cô khám phá ra quyền năng và sứ mệnh thật sự của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gal Gadot","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Eugene Brave Rock","avatar":""},{"name":"Lucy Davis","avatar":""},{"name":"Elena Anaya","avatar":""},{"name":"Lilly Aspell","avatar":""},{"name":"Lisa Loven Kongsli","avatar":""},{"name":"Ann Wolfe","avatar":""},{"name":"Ann Ogbomo","avatar":""},{"name":"Emily Carey","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Wolf Kahler","avatar":""},{"name":"Ale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324406);
