INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-christopher-robin', 'Tạm Biệt Christopher Robin', 'Goodbye Christopher Robin', 'https://phimimg.com/upload/vod/20231129-1/46a79437fdc8d1a19d6a4df3f9188a43.jpg', 'https://phimimg.com/upload/vod/20231129-1/397743a565ff033d28a41706634a00d6.jpg', '<p>Tạm Biệt Christopher Robin là bộ phim tự truyện kể về cuộc đời của tác giả A. A. Milne và cậu con trai Christopher Robin trên hành trình sáng tạo nên chú gấu Pooh nổi tiếng toàn thế giới. Nằm ngoài mọi dự đoán của A. Milne, Pooh đã trở thành biểu tượng giúp xoa dịu đi nỗi buồn ở khắp mọi nơi sau chiến tranh thế giới thứ nhất và được trẻ em khắp nơi yêu quý.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Domhnall Gleeson","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Will Tilston","avatar":""},{"name":"Alex Lawther","avatar":""},{"name":"Nico Mirallegro","avatar":""},{"name":"Stephen Campbell Moore","avatar":""},{"name":"Phoebe Waller-Bridge","avatar":""},{"name":"Geraldine Somerville","avatar":""},{"name":"Richard McCabe","avatar":""},{"name":"Shaun Dingwall","avatar":""},{"name":"Vicki Pepperdine","avatar":""},{"name":"Simon Williams","avatar":""},{"name":"Bentley Kalu","avatar":""},{"name":"Mossie Smith","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
