INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-biet-christopher-robin', 'Tạm Biệt Christopher Robin', 'Goodbye Christopher Robin', 'tạm biệt christopher robin goodbye christopher robin domhnall gleeson margot robbie kelly macdonald will tilston alex lawther nico mirallegro stephen campbell moore phoebe waller-bridge geraldine somerville richard mccabe shaun dingwall vicki pepperdine simon williams bentley kalu mossie smith ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-to-la-chan-to', 'Bố Tớ Là Chân To', 'The Son of Bigfoot', 'https://phimimg.com/upload/vod/20231125-1/085c55d8ec043401c6ab6fbf5986dca1.jpg', 'https://phimimg.com/upload/vod/20231125-1/df1bd4265777f32b84efefa1a1b39183.jpg', '<p>Chàng trai trẻ tuổi Adam tự mình đi tìm người cha đã bị lạc từ lâu, không ngờ rằng ông không ai khác chính là Bigfoot huyền thoại! Ông đã ẩn náu trong rừng từ nhiều năm để bảo vệ chính mình và gia đình khỏi HairCo, một tập đoàn khổng lồ đang muốn thí nghiệm khoa học với DNA đặc biệt của ông. Chính lúc đó, Adam phát hiện ra mình cũng có siêu năng lực. Nhưng đâu ngờ, HairCo đã bám đuôi theo Adam từ bao giờ.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Pappy Faulkner","avatar":""},{"name":"Cinda Adams","avatar":""},{"name":"Jeff Doucette","avatar":""},{"name":"Laila Berzins","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Sandy Fox","avatar":""},{"name":"Grant George","avatar":""},{"name":"Kyle Hebert","avatar":""},{"name":"Steve Kramer","avatar":""},{"name":"Joe Ochman","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Christopher Lee Parson","avatar":""},{"name":"Tara Platt","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Michael Sorich","avatar":""},{"name":"Marieve Herington","avatar":""},{"name":"Joe J. Thomas","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324406);
