INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-to-la-chan-to', 'Bố Tớ Là Chân To', 'The Son of Bigfoot', 'bố tớ là chân to the son of bigfoot pappy faulkner cinda adams jeff doucette laila berzins joey camen sandy fox grant george kyle hebert steve kramer joe ochman yuri lowenthal christopher lee parson tara platt roger craig smith michael sorich marieve herington joe j. thomas ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-van-phai-song', 'Tôi Vẫn Phải Sống', 'I Am Still Here', 'https://phimimg.com/upload/vod/20231125-1/8d96b31039980dfc5ded90633bc5ba48.jpg', 'https://phimimg.com/upload/vod/20231125-1/fb9df9602f8c4080cf957508ba3ca5ab.jpg', '<p>Một câu chuyện về hy vọng và sự cứu chuộc được nói qua đôi mắt của một cô gái 17 tuổi sau khi cô trốn thoát khỏi bảy năm bị giam giữ như một nô lệ tình dục. Bộ phim miêu tả sự trung thực tàn bạo, hoàn cảnh không thể tưởng tượng của một cô gái trẻ, Layla, bị bắt cóc và lạm dụng khi chỉ mới 10 tuổi.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Erika Ringor","avatar":""},{"name":"Ciara Jiana","avatar":""},{"name":"Aliyah Conley","avatar":""},{"name":"Kurry Damon","avatar":""},{"name":"Johnny Rey Diaz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
