INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-leisure-seeker', 'The Leisure Seeker', 'The Leisure Seeker', 'https://phimimg.com/upload/vod/20231125-1/2c2e3e45bee5a4c1cb6ba5405477b1c2.jpg', 'https://phimimg.com/upload/vod/20231125-1/5dc26642becf240371cec823a372693b.jpg', '<p>Một cặp vợ chồng chạy trốn qua một hành trình khó quên trong RV cũ trung thành, họ gọi là người tìm kiếm giải trí, du lịch từ Boston, Massachusetts đến Hemingway Evest ở Key West, Florida. Họ chiếm lấy niềm đam mê với cuộc sống và tình yêu của họ dành cho nhau trên một chuyến đi trên đường cung cấp sự mặc khải và bất ngờ ngay đến cuối cùng.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Christian McKay","avatar":""},{"name":"Janel Moloney","avatar":""},{"name":"Dana Ivey","avatar":""},{"name":"Dick Gregory","avatar":""},{"name":"Leander Suleiman","avatar":""},{"name":"Ahmed Lucan","avatar":""},{"name":"Gabriella Cila","avatar":""},{"name":"David Marshall Silverman","avatar":""},{"name":"Lucy Catharine Haskill","avatar":""},{"name":"Joshua Hoover","avatar":""},{"name":"Kirsty Mitchell","avatar":""},{"name":"Mylie Stone","avatar":""},{"name":"Helen LeRoy","avatar":""},{"name":"Joshua Mik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
