INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lac-loai', 'Kẻ Lạc Loài', 'The Cutlass', 'https://phimimg.com/upload/vod/20231125-1/6d9fdd7e0a1267417155cf04a9b1bdae.jpg', 'https://phimimg.com/upload/vod/20231125-1/e2fb5dd74927750e614085ef17b3e75d.jpg', '<p>Lấy cảm hứng từ những sự kiện có thật, Kẻ Lạc Loài là một bộ phim kinh dị kịch tính lấy bối cảnh vùng hoang dã nhiệt đới của Trinidad và kể về câu chuyện của một phụ nữ trẻ rơi vào vòng vây của một tên sát nhân nguy hiểm. Cô thấy mình bị cô lập và lấy hết can đảm để chiến đấu tình cảm với tâm trí bất an của kẻ bắt cóc cô.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lisa-Bel Hirschmann","avatar":""},{"name":"Arnold Goindhan","avatar":""},{"name":"Kirk Baltz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
