INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-tu-than', 'Ranh Giới Tử Thần', 'County Line', 'https://phimimg.com/upload/vod/20231125-1/3e610b1d3f2d0a7d0c0a7bafdbeeff6e.jpg', 'https://phimimg.com/upload/vod/20231125-1/ce4d4563147d31f46dcae1204adf5866.jpg', '<p>Cảnh sát trưởng Rockwell đang chuẩn bị nghỉ hưu thì nghe tin đồng đội cũ của anh và Cảnh sát trưởng thị trấn kế bên bị bắn chết một cách bí ẩn. Ngay lập tức vợ của Clint gây áp lực buộc Alden phải đích thân điều tra vụ nổ súng. Khi các bằng chứng bị bỏ qua chỉ ra sự tham nhũng, Alden phải tự mình ra tay trước khi thế lực xấu muốn thâu tóm, chiếm quyền kiểm soát thị trấn.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Wopat","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Patricia Richardson","avatar":""},{"name":"Grant Goodeve","avatar":""},{"name":"Mark Ashworth","avatar":""},{"name":"Brian F. Durkin","avatar":""},{"name":"James Boivin","avatar":""},{"name":"Justin Debord","avatar":""},{"name":"Abbi Butler","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324406);
