INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-tung-nhip-tho', 'Trong Từng Nhịp Thở', 'Breathe', 'https://phimimg.com/upload/vod/20231125-1/90e94c707fd1bd98db18889199ce668c.jpg', 'https://phimimg.com/upload/vod/20231125-1/f5ab957d7b0f8105385655ffefc67818.jpg', '<p>Dựa trên một câu chuyện có thật, Breathe kể về cuộc đời của Robin Cavendish, một chàng trai trẻ năng động, lạc quan và yêu đời. Tuy nhiên, cuộc đời của Robin nhanh chóng sụp đổ khi căn bệnh bại liệt bộc phát và anh chỉ còn sống được thêm vài tháng nữa. Bất chấp tất cả những lời khuyên của các bác sĩ, người vợ Diana quyết định đưa anh về nhà tự tay chăm sóc. Tình yêu giống như liều thuốc duy nhất đã giúp Robin vượt lên được khuyết tật của bản thân, sống một cuộc đời hạnh phúc và trở thành nhà hoạt động vì quyền lợi của những bệnh nhân bại liệt.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Claire Foy","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Miranda Raison","avatar":""},{"name":"Dean-Charles Chapman","avatar":""},{"name":"Diana Rigg","avatar":""},{"name":"Ed Speleers","avatar":""},{"name":"Emily Grace Bevan","avatar":""},{"name":"Ben Lloyd-Hughes","avatar":""},{"name":"Roger Ashton-Griffiths","avatar":""},{"name":"Camilla Rutherford","avatar":""},{"name":"Penny Downie","avatar":""},{"name":"Amit Shah","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Patrick God","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
