INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-duoi-dai-duong', 'Trận Chiến Dưới Đại Dương', 'The Ghazi Attack', 'https://phimimg.com/upload/vod/20231125-1/92f792f70a2b07076f7ab6a61fdafbc6.jpg', 'https://phimimg.com/upload/vod/20231125-1/a684b56a17a774169ec06e1bee4e07ef.jpg', '<p>Năm 1971, giữa lúc căng thẳng gia tăng giữa Ấn Độ và Pakistan trong cuộc chiến giải phóng Đông Pakistan. Hải quân Pakistan, trong một sứ mệnh bí mật, lên kế hoạch tấn công hàng không mẫu hạm (tàu sân bay) INS Vikrant của Ấn Độ để giành quyền kiểm soát vùng biển Vịnh Bengal. Họ gửi tàu ngầm tốt nhất PNS Ghazi tấn công, nhưng bị một chiếc tàu ngầm INS Karanj (S21) đánh chặn. Cuộc chiến dữ dội dưới làn nước đã diễn ra...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Kay Kay Menon","avatar":""},{"name":"Rana Daggubati","avatar":""},{"name":"Atul Kulkarni","avatar":""},{"name":"Taapsee Pannu","avatar":""},{"name":"Amitabh Bachchan","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Milind Gunaji","avatar":""},{"name":"Rahul Singh","avatar":""},{"name":"Satyadev Kancharana","avatar":""},{"name":"Chiranjeevi","avatar":""},{"name":"Priyadarshi Pullikonda","avatar":""},{"name":"Rajiv Kachroo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324406);
