INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-troi-chet', 'Quay Trối Chết', 'One Cut of the Dead', 'https://phimimg.com/upload/vod/20231125-1/5b3af3587f6aa35a668d33cd10df6556.jpg', 'https://phimimg.com/upload/vod/20231125-1/be68f7b5f1c58546fa18baf3a39ae8b3.jpg', '<p>Câu chuyện phim kể về một đoàn phim lên kế hoạch quay và phát livestream một bộ phim về xác sống. Theo kịch bản thì bộ phim được xây dựng tại một nhà máy lọc nước bị bỏ hoang đã lâu, nơi từng có những giai thoại man rợ khiến không ai dám đặt chân đến, tuy nhiên vì thiếu kinh phí nên đoàn làm phim vẫn quyết định đến đây bấm máy. Đạo diễn Higurashi (Takayuki Hamatsu) do có mâu thuẫn với các diễn viên nên đã bỏ đi không nói lời nào. Trong lúc mọi người ngồi đợi anh ta quay lại thì những xác sống thật sự xuất hiện. Và đến khi Higurashi quay về thì mới hé lộ hóa ra là chính anh ta đã thực hiện một nghi thức cổ xưa để gọi các xác sống dậy để nhằm tăng hiệu quả diễn xuất một cách chân thực nhất cho diễn viên... Tưởng rằng câu chuyện phim chỉ có thế, nhưng thực tế xảy ra lại khác xa với hàng loạt tình huống dở khóc dở cười...</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takayuki Hamatsu","avatar":""},{"name":"Yuzuki Akiyama","avatar":""},{"name":"Kazuaki Nagaya","avatar":""},{"name":"Harumi Shuhama","avatar":""},{"name":"Mao","avatar":""},{"name":"Hiroshi Ichihara","avatar":""},{"name":"Manabu Hosoi","avatar":""},{"name":"Shuntarô Yamazaki","avatar":""},{"name":"Shinichiro Osawa","avatar":""},{"name":"Donguri","avatar":""},{"name":"Miki Yoshida","avatar":""},{"name":"Ayana Gôda","avatar":""},{"name":"Sakina Asamori","avatar":""},{"name":"Tomokazu Yamaguchi","avatar":""},{"name":"Takuya Fujimura","avatar":""},{"name":"Satoshi Iwagô","avatar":""},{"name":"Kyôko Takaha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
