INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-bao-thu-2017', 'Kẻ Báo Thù', 'Vengeance: A Love Story', 'https://phimimg.com/upload/vod/20231117-1/32a23c51c8140251d4ada3a17dbe91e3.jpg', 'https://phimimg.com/upload/vod/20231117-1/5c47058147c17e1d7da5f5045e3a9623.jpg', '<p>Phim Kẻ Báo Thù - Vengeance: A Love Story 2017: John Dromoor, một thám tử đang chạy đua theo thời gian để truy bắt nhóm đã bắt cóc và làm nhục Teena một phụ nữ trẻ đơn thân trước mắt Bethie Maguire 12 tuổi, con gái của cô. Các nghi phạm nhanh chóng bị bắt gọn và đưa ra tòa. Các chứng cứ tội phạm đã không đủ sức thuyết phục tòa buộc tôi, trước tay luật sư hùng biện mạnh mẽ bảo vệ các nghi can. Các nghi can được tự do, trong lúc này không nổi đau nào lớn hơn với Teena và đứa con gái nhỏ, cô đã gieo mình thuốc dòng thác tự tử, rất may thám tử John, người vẫn âm thầm theo dõi bọn tội phạm sau phiên tòa đã kịp thời cứu cô. Không đủ chứng cứ để kết tội, John đã thay mặt công lý quyết định ra tay trừng trị bọn chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Anna Hutchison","avatar":""},{"name":"Talitha Bateman","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Charlene Tilton","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"Rocco Nugent","avatar":""},{"name":"Joe Ochterbeck","avatar":""},{"name":"Carter Burch","avatar":""},{"name":"Jimmy Gonzales","avatar":""},{"name":"Dikran Tulaine","avatar":""},{"name":"Kara Flowers","avatar":""},{"name":"Cory Scott Allen","avatar":""},{"name":"Mike Pniewski","avatar":""},{"name":"Kaleigh Rivera","avatar":""},{"name":"Xavie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
