INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-thanh-thi', 'Phù Thủy Thành Thị', 'Sorcery in The Big City', 'https://phimimg.com/upload/vod/20231206-1/a3cbf8466021d54c7e8eb0c07c44925e.jpg', 'https://phimimg.com/upload/vod/20231206-1/7416ba1becde179403f1f9154e1629d1.jpg', '<p>Phim Phù Thủy Thành Thị - Sorcery in The Big City 2017: Câu chuyện xảy ra ở New York đang được trang trí đèn Giáng Sinh. Tại sở cảnh sát Tokyo Metropolitan, nữ cảnh sát Akari Kido đang điều phối giao thông thì bỗng một nữ phù thủy xuất hiện làm phép Christmas Party, chiếc xe tải lao nhanh về phía Akari thì bỗng một cô gái bí ẩn xuất hiện.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Megumi Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324406);
