INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-dau-2017', 'Nụ Hôn Đầu', 'First Kiss', 'https://phimimg.com/upload/vod/20231120-1/711d77aa9bf7d2bd267d340a63342f15.jpg', 'https://phimimg.com/upload/vod/20231120-1/30e2acca186c59ddae7144fb7e60e4fa.jpg', '<p>Hakan là một người không thể có các mối quan hệ lâu dài. Anh ta có những mối quan hệ ngắn với khách du lịch ở thị trấn nghỉ mát mà anh ta sống, và không thể tiến tới hôn nhân. Anh ta không có ai ngoại trừ 5 đứa cháu trai và anh rể của anh ta, người mà chị gái anh đã bỏ rơi. Mọi thứ thay đổi đối với Hakan khi anh gặp Bahar. Nhưng Bahar có một vấn đề.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Murat Yildirim","avatar":""},{"name":"Özge Gürel","avatar":""},{"name":"Beyti Engin","avatar":""},{"name":"Hayrettin","avatar":""},{"name":"Sadi Celil Cengiz","avatar":""},{"name":"Gamze Karaduman","avatar":""},{"name":"Erol Aksoy","avatar":""},{"name":"Jale Aylanç","avatar":""},{"name":"Hakan Akın","avatar":""},{"name":"Cezmi Baskın","avatar":""},{"name":"Değer Soysal","avatar":""},{"name":"İbrahim Coşkun","avatar":""},{"name":"Birsen Dürülü","avatar":""},{"name":"Zümre Ertürk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324406);
