INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-dia', 'Lãnh Địa', 'Domain', 'https://phimimg.com/upload/vod/20231125-1/965e4b64d288f09858ad858f4df0cd1a.jpg', 'https://phimimg.com/upload/vod/20231125-1/2d6d20e1a5648466c95d3a38e3cbc646.jpg', '<p>Sau khi một loại virus chết người quét sạch hầu hết nhân loại, những người sống sót còn lại buộc phải chờ đợi trong các hầm trú ẩn. Họ duy trì liên lạc với bên ngoài thông qua video được nối mạng. Biến cố xảy ra khi từng người một biến mất một cách bí ẩn.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Britt Lower","avatar":""},{"name":"Ryan Merriman","avatar":""},{"name":"William Gregory Lee","avatar":""},{"name":"Kevin Sizemore","avatar":""},{"name":"Nick Gomez","avatar":""},{"name":"Sonja Sohn","avatar":""},{"name":"Cedric Sanders","avatar":""},{"name":"Beth Grant","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
