INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-boi-doping-icarus', 'Bê Bối Doping Icarus', 'Icarus', 'https://phimimg.com/upload/vod/20231125-1/910a3141afca11334c40e525e9e0b19a.jpg', 'https://phimimg.com/upload/vod/20231125-1/9b7af861e37e6c3f3f158bf016f189c1.jpg', '<p>Trong khi điều tra thế giới sâu rộng về doping trong thể thao, đạo diễn Bryan Fogel kết nối với nhà khoa học Nga tiến sĩ Grigory Rodchenkov — một trụ cột trong chương trình “chống doping” của đất nước ông. Fogel và Rodchenkov đã vạch trần những cáo buộc gây sốc của chương trình gian lận doping Olympic do nhà nước Nga tài trợ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bryan Fogel","avatar":""},{"name":"Dave Zabriskie","avatar":""},{"name":"Don Catlin","avatar":""},{"name":"Grigory Rodchenkov","avatar":""},{"name":"Scott Brandt","avatar":""},{"name":"Ben Stone","avatar":""},{"name":"Richard Pound","avatar":""},{"name":"Richard McLaren","avatar":""},{"name":"Nikita Kamaev","avatar":""},{"name":"Thomas Bach","avatar":""},{"name":"Sebastian Coe","avatar":""},{"name":"Vitaliy Mutko","avatar":""},{"name":"Dan Cogan","avatar":""},{"name":"David Howman","avatar":""},{"name":"Jacques Rogge","avatar":""},{"name":"Jim Walden","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324406);
