INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-chien-tranh', 'Cỗ Máy Chiến Tranh', 'War Machine', 'https://phimimg.com/upload/vod/20231125-1/d6d844740b9ec3fbbc9ff1ae449d0f8e.jpg', 'https://phimimg.com/upload/vod/20231125-1/45b3208bc0d2832d2debd39127afdb27.jpg', '<p>Nhiệm vụ lần này là một cuộc chiến không được lòng dân. Vị tướng kiêu hãnh vẫn sẵn sàng xông pha nhưng ông đâu biết sự ngạo mạn sẽ trở thành kẻ thù lớn nhất của ông.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Emory Cohen","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Daniel Betts","avatar":""},{"name":"Aymen Hamdouchi","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Anthony Hayes","avatar":""},{"name":"RJ Cyler","avatar":""},{"name":"Nicholas Jones","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Meg Tilly","avatar":""},{"name":"Griffin Dunne","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Kola Bokinni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324406);
