INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-so-81-kinh-thanh-2', 'Nhà Số 81 Kinh Thành 2', 'The House That Never Dies 2', 'https://phimimg.com/upload/vod/20231125-1/405a3fa402944f9b6febc81edddf81ee.jpg', 'https://phimimg.com/upload/vod/20231125-1/6375bae120690160708614498c293d5f.jpg', '<p>Phim Nhà Số 81 Kinh Thành 2 - The House That Never Dies 2 (2017): Câu chuyện xảy ra vào cuối thời Dân quốc, giữa thời chiến tranh loạn loạn, thiếu soái Trương Chất Sinh bị ép phải cưới con gái của đại quân phiệt Kỷ Kim Thúy. Sau khi cưới cô vào nhà, Trương phủ liên tục xảy ra những câu chuyện kỳ quái, khiến mọi người trong phủ đều hoang mang.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Julian Cheung","avatar":""},{"name":"Mei Ting","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"Geng Le","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Wang Shuilin","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Wan Guopeng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
