INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-cuoi-cung-2017', 'Phi Vụ Cuối Cùng', 'The Adventurers', 'https://phimimg.com/upload/vod/20231102-1/1cb4ed0e59f9f9b6340e952dfd406b5a.jpg', 'https://phimimg.com/upload/vod/20231102-1/6fc3f1d67ce109a10ae4b0a3fd153342.jpg', '<p>Phim kể về tên trộm khét tiếng Trương Đan trong một lần hành động gặp phải đối thủ khiến phi vụ thất bại rồi anh bị bắt vào tù. Sau 5 năm bị giam giữ, Trương Đan được phóng thích. Anh liền hợp tác cùng đồng bọn cũ, Tiểu Bảo, và tay lính mới Diệp Hồng liên tiếp thực hiện thành công nhiều phi vụ ngay dưới mũi của Pierre , thám tử người Pháp đã truy bắt anh suốt nhiều năm qua. Phim với sự tham gia của các diễn viên Lưu Đức Hoa, Trương Tịnh Sơ, Thư Kỳ, Jean Reno...</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Sha Yi","avatar":""},{"name":"You Tianyi","avatar":""},{"name":"Karel Dobrý","avatar":""},{"name":"David Bowles","avatar":""},{"name":"Gen Seto","avatar":""},{"name":"Seam Turay","avatar":""},{"name":"Eva Larvoire","avatar":""},{"name":"Wonjin Hahn","avatar":""},{"name":"Eric da Costa","avatar":""},{"name":"Jitka Nováčková","avatar":""},{"name":"Adam Vacula","avatar":""},{"name":"Vladimír Javorský","avatar":""},{"name":"Petr Franěk","avatar":""},{"name":"Barbora Petrová","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu