INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tach-biet-2017', 'Tách Biệt', 'Split', 'https://phimimg.com/upload/vod/20231020-1/6cbd3667e974db2dcc5cc2c784868dec.jpg', 'https://phimimg.com/upload/vod/20231020-1/0d138ec20366e77db337f4c8fb27e13f.jpg', '<p>Kevin, một người đàn ông có 23 nhân cách khác nhau trong một cơ thể, bên trong Kevin tồn tại một nhân cách ác quỷ luôn muốn điều khiển và thống trị những nhân cách còn lại. Sau khi bắt cóc ba cô gái trẻ, Kevin đã phải đấu tranh với các mặt tâm lý bên trong hắn và với cả những người xung quanh, khi bức tường ngăn cách giữa các mảng tâm trí đã sụp đổ. Nhân cách xấu xa vốn ẩn giấu lâu nay đang dần hiện hữu và thao túng các nhân cách còn lại.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Betty Buckley","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Jessica Sula","avatar":""},{"name":"Izzie Coffey","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Sebastian Arcelus","avatar":""},{"name":"Neal Huff","avatar":""},{"name":"Ukee Washington","avatar":""},{"name":"Ann Wood","avatar":""},{"name":"Robert Michael Kelly","avatar":""},{"name":"M. Night Shyamalan","avatar":""},{"name":"Rosemary Howard","avatar":""},{"name":"Jerome Gallman","avatar":""},{"name":"Lyne Ren","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
