INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-pablo', 'Ông Trùm Pablo', 'Loving Pablo', 'https://phimimg.com/upload/vod/20231124-1/32c75c1764fee802c8017cba26423a86.jpg', 'https://phimimg.com/upload/vod/20231124-1/2164385404fd2b9be291fe32ce752bde.jpg', '<p>Dựa theo lời kể của Virginia Vallejo – MC truyền hình nổi tiếng đồng thời cũng là người tình xinh đẹp của Pablo Escobar, bộ phim khắc họa chân thực đế chế ma túy khổng lồ và sự máu lạnh của ông trùm khét tiếng bậc nhất trong lịch sử.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Javier Bardem","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Julieth Restrepo","avatar":""},{"name":"Óscar Jaenada","avatar":""},{"name":"David Valencia","avatar":""},{"name":"Mark Basnight","avatar":""},{"name":"Joavany Alvarez","avatar":""},{"name":"Matthew Moreno","avatar":""},{"name":"David Ojalvo","avatar":""},{"name":"Fredy Yate","avatar":""},{"name":"Ricardo Niño","avatar":""},{"name":"Pedro Calvo","avatar":""},{"name":"Santiago Londoño","avatar":""},{"name":"Juan Sebastián Calero","avatar":""},{"name":"Quique Mendoza","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
