INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu-diem-bat-dau', 'Trò Chơi Sinh Tử: Điểm Bắt Đầu', 'No Game, No Life: Zero', 'https://phimimg.com/upload/vod/20231123-1/cc94724bf4ba16ed6f8b3338ceec30e6.jpg', 'https://phimimg.com/upload/vod/20231123-1/698bbab184ecd43be6801f824f098c6b.jpg', '<p>No Game No Life Zero không nối tiếp cuộc hành trình của Sora và Shiro, mà kể lại một câu chuyện khác, một câu chuyện nguồn gốc từ rất lâu, là 6000 năm về trước… từ trước khi thế giới Disboard được tạo ra.</p><p>Ở thế giới Disboard thời cổ đại, Riku là một chiến binh chiến đấu vì sự sống cho nhân loại giữa của chiến của 16 chủng tộc chống lại Vị thần Tối cao, Old Deus. Đứng giữa thế giới phép thuật là tất cả, nhân loại chỉ như một loài sinh vật hạ đẳng chỉ đang chực chờ bị tuyệt chủng. Một ngày nọ, Riku tìm thấy Schwi, một Ex-machina, tại khu tàn tích của tộc Elf. Schwi bị Cluster loại trừ, đơn độc một mình với nhiệm vụ tìm hiểu trái tim con người – thứ đã giúp nhân loại sống sót qua cuộc chiến dài đằng đẵng này.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoko Hikasa","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Ryota Takeuchi","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Lynn","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Nanako Mori","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Yuka Iguchi","avatar":""},{"name":"Toru Okawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324406);
