INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-sat-thu', 'Long Sát Thủ', 'Mr. Long', 'https://phimimg.com/upload/vod/20231121-1/a39ef5e878cf525abaf12fef0b2b5f93.jpg', 'https://phimimg.com/upload/vod/20231121-1/7034510a47d10ed410c5306ef1460299.jpg', '<p>Trương Chấn đóng vai một sát thủ tên Long, hắn ta có thể mang theo thanh đao lớn dài 6 tấc một mình xông vào xào quyệt của địch, đánh đâu thắng đó không gì cản được. Nhưng trong một lần chấp hành nhiệm vụ ở Nhật, hắn ta đã bị trọng thương và được một cậu bé bắt gặp, từ đó cũng gặp được những biến cố không thể ngờ đến trong đời.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chang Chen","avatar":""},{"name":"Sho Aoyagi","avatar":""},{"name":"Yao Yi Ti","avatar":""},{"name":"Bai Run-yin","avatar":""},{"name":"Masashi Arifuku","avatar":""},{"name":"Taro Suwa","avatar":""},{"name":"Ritsuko Ohkusa","avatar":""},{"name":"Shiiko Utagawa","avatar":""},{"name":"Yûsuke Fukuchi","avatar":""},{"name":"Tetsuya Chiba","avatar":""},{"name":"Yasunari Takeshima","avatar":""},{"name":"Sôtarô","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324406);
