INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-kiem-bat-tu', 'Lưỡi Kiếm Bất Tử', 'Blade of the Immortal', 'https://phimimg.com/upload/vod/20231121-1/f9dee5e291dceee2e59949a608b74304.jpg', 'https://phimimg.com/upload/vod/20231121-1/20ab4a11098657199e124ec36a1136bd.jpg', '<p>Blade Of The Immortal (Lưỡi Kiếm Bất Tử) kể về một lãng khách tên Manji (Takuya Kimura). Anh ta từng khét tiếng với biệt danh &quot;võ sĩ giết chết 100 người&quot;. Để đền tội cho quá khứ, Manji được ban cho năng lực bất tử bằng loài ký sinh Huyết Tiên Trùng cùng trách nhiệm phải lấy mạng 1000 kẻ ác. Manji bắt đầu hành trình khó khăn này cùng cô gái trẻ Rin Asano (Hana Sugisaki), người nung nấu ý chí trả thù băng đảng võ sĩ đã hạ sát toàn bộ gia đình mình. Rin vừa là điểm yếu và cũng là động lực cho Manji trong suốt cuộc đời gần như bất tử của vị samurai hùng mạnh này.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takuya Kimura","avatar":""},{"name":"Hana Sugisaki","avatar":""},{"name":"Sota Fukushi","avatar":""},{"name":"Hayato Ichihara","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Chiaki Kuriyama","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Ken Kaneko","avatar":""},{"name":"Yōko Yamamoto","avatar":""},{"name":"Ichikawa Ebizo XI","avatar":""},{"name":"Seizō Fukumoto","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Masayuki Deai","avatar":""},{"name":"Tsutomu Yamazaki","avatar":""},{"name":"Takashi Kitadai","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c7