INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-dai-chien-voi-haimat', 'Người Dơi Đại Chiến Với Hai-Mặt', 'Batman vs. Two-Face', 'https://phimimg.com/upload/vod/20231120-1/e0cc11a9bbe31dc730a5d0137847b0bb.jpg', 'https://phimimg.com/upload/vod/20231120-1/b474c50ae5091cd73a4a14b90d1a78a9.jpg', '<p>Lần này Người Dơi (Batman), Miêu Nữ (Cat Woman) và Robin phải đối đầu với tên Hai-Mặt (Two-Face) để làm rõ các vấn đề phạm tội bí ẩn xảy ra ở thành phố Gotham...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam West","avatar":""},{"name":"Burt Ward","avatar":""},{"name":"William Shatner","avatar":""},{"name":"Julie Newmar","avatar":""},{"name":"Jeff Bergman","avatar":""},{"name":"Sirena Irwin","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Lee Meriwether","avatar":""},{"name":"William Salyers","avatar":""},{"name":"Lynne Marie Stewart","avatar":""},{"name":"Jim Ward","avatar":""},{"name":"Steven Weber","avatar":""},{"name":"Wally Wingert","avatar":""},{"name":"Maurice LaMarche","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324406);
