INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tac-tro-choi', 'Quy Tắc Trò Chơi', 'The Game Changer', 'https://phimimg.com/upload/vod/20231120-1/de1513b7aad007286ec25cb97e99cba2.jpg', 'https://phimimg.com/upload/vod/20231120-1/2fe6c23009bf0ef5c3a6c7bca5fb43c3.jpg', '<p>Lý Tử Hào và Phương Kiệt sau khi trải qua nhiều trận gió tanh mưa máu đã trở thành một cặp huynh đệ đồng sinh cộng tử. Nhưng không may, Đường Thiên Thiên, người mà Phương Kiệt yêu thầm đã lâu lại yêu say đắm Lý Tử Hào, còn Lý Tử Hào lại phát hiện ý trung nhân Lam Nhược Vân trong khoảng thời gian mình bị bắt đã trở thành người tình của Đường tiên sinh. Đường tiên sinh muốn xưng bá bến Thượng Hải, bày ra một trò lừa kinh thiên động địa. Trong trò lừa đó, vòng quan trọng chính là Lý Tử Hào. Nhưng Đường tiên sinh lại không hề biết, thân phận thật của Lý Tử Hào là thành viên của tổ chức ám sát Lam Y Xã…</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peter Ho","avatar":""},{"name":"Huang Zitao","avatar":""},{"name":"Guli Nazha","avatar":""},{"name":"Wang Xueqi","avatar":""},{"name":"Choo Ja-hyun","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Jonathan Kos-Read","avatar":""},{"name":"Huo Qing","avatar":""},{"name":"Miura Kenichi","avatar":""},{"name":"Long Meizi","avatar":""},{"name":"Xu Zixin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
