INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-than-thanh', 'Vùng Đất Thần Thánh', 'God''s Own Country', 'https://phimimg.com/upload/vod/20231120-1/82b758e0914dc09246d4a44db4995f18.jpg', 'https://phimimg.com/upload/vod/20231120-1/bcd834f44c7a2fcb594adfb6c7b1f5b4.jpg', '<p>Một chàng nông dân trẻ ở ngoại ô Yorkshire dùng rượu và sex để quên đi những mối phiền muộn trong cuộc sống cho đến anh gặp &nbsp;một công nhân lao động nhập cư từ Romania.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Josh O''Connor","avatar":""},{"name":"Alec Secăreanu","avatar":""},{"name":"Gemma Jones","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"Harry Lister Smith","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Naveed Choudhry","avatar":""},{"name":"Stefan Dermendjiev","avatar":""},{"name":"Moey Hassan","avatar":""},{"name":"Melanie Kilburn","avatar":""},{"name":"John McCrea","avatar":""},{"name":"Alexander Suvandjiev","avatar":""},{"name":"Liam Thomas","avatar":""},{"name":"Sarah White","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324406);
