INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-duoi-tinh-nhan', 'Săn Đuổi Tình Nhân', 'Girlfriend Killer', 'https://phimimg.com/upload/vod/20231120-1/fa590c12d4c744e8cb93ad997515870f.jpg', 'https://phimimg.com/upload/vod/20231120-1/f05992ff5509a5ace82096448afab387.jpg', '<p>Carmen tạo ra những lời cầu hôn hoàn hảo cho những người đàn ông giàu có. Cho đến khi cô trở thành mục tiêu nỗi ám ảnh của một khách hàng điên rồ, khi cô thể hiện lòng trắc ẩn, sau khi bạn gái của anh ta công khai từ chối anh ta. Cô nhận ra, không phải tất cả các lời cầu hôn đều kết thúc như dự định!</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Dina Meyer","avatar":""},{"name":"Corin Nemec","avatar":""},{"name":"Barbie Castro","avatar":""},{"name":"Jason Cook","avatar":""},{"name":"Brian Gross","avatar":""},{"name":"Elisabetta Fantone","avatar":""},{"name":"Taylor Castro","avatar":""},{"name":"Betsy Graver","avatar":""},{"name":"Khotan Fernández","avatar":""},{"name":"Vivi Pineda","avatar":""},{"name":"Mia Matthews","avatar":""},{"name":"Miguel Fasa","avatar":""},{"name":"Cristina Figarola","avatar":""},{"name":"Eliezer Castro","avatar":""},{"name":"Mary Farah","avatar":""},{"name":"Tess La Bella","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324406);
