INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-xac', 'Thoát Xác', 'The Changeover', 'https://phimimg.com/upload/vod/20231123-1/5f7f46f9acf097b5fe7f43c8dfeea8e2.jpg', 'https://phimimg.com/upload/vod/20231123-1/4352cdf1c16c7222a566f249256c1f20.jpg', '<p>Cô bé 16 tuổi Laura Chant sống cùng mẹ và cậu em trai 4 tuổi Jacko trong một khu dân cư nghèo ở vùng ngoại ô thành phố Christchurch, New Zealand - nơi đang đứng trước nguy cơ bị mai một. Laura bị kéo vào cuộc chiến siêu năng lực với một linh hồn cổ xưa – thứ đã tấn công và dần lấy đi sự sống của em trai cô Jacko để trở nên trẻ trung hơn. Từ đó, Laura phát hiện ra danh tính thực sự của mình và siêu năng lực cô đang sở hữu, để nỗ lực tăng cường sức mạnh và cứu em trai cô.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Erana James","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Lucy Lawless","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Kate Harcourt","avatar":""},{"name":"Benji Purchase","avatar":""},{"name":"Ella Edward","avatar":""},{"name":"Thomasin McKenzie","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Kevin MacIsaac","avatar":""},{"name":"Jess Aspinwall","avatar":""},{"name":"Aryn Azlan","avatar":""},{"name":"Drew Briceford","avatar":""},{"name":"Amy Christian","avatar":""},{"name":"Tawanda Manyimo","avatar":""},{"name":"Claire v","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324406);
