INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deidra-va-laney-cuop-tau', 'Deidra và Laney cướp tàu', 'Deidra & Laney Rob a Train', 'https://phimimg.com/upload/vod/20231123-1/49719a07a62f4d024a0a5ed0e3a94786.jpg', 'https://phimimg.com/upload/vod/20231123-1/1acc61959b010dcef8599f9e527c3275.jpg', '<p>Mẹ thì ở trong tù, hóa đơn thì ngày càng chồng chất, hai thiếu niên đầy tham vọng Deidra và Laney lên kế hoạch một loạt các vụ cướp tàu hỏa để trang trải cho bản thân.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashleigh Murray","avatar":""},{"name":"Rachel Crow","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"David Sullivan","avatar":""},{"name":"Danielle Nicolet","avatar":""},{"name":"Sasheer Zamata","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Sharon Lawrence","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Myko Olivier","avatar":""},{"name":"Kinna McInroe","avatar":""},{"name":"Brooke Markham","avatar":""},{"name":"Monica Moore Smith","avatar":""},{"name":"Deborah Lee Douglas","avatar":""},{"name":"Gerry Garcia","avatar":""},{"name":"Mario DeAngel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
