INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-cua-dan-ngu-cu', 'Đảo Của Dân Ngụ Cư', 'The Way Station', 'https://phimimg.com/upload/vod/20231123-1/cb3c99f0f9122be37693d2004f4fa999.jpg', 'https://phimimg.com/upload/vod/20231123-1/8e6792b48f166a846c73c6c5dd0ad19a.jpg', '<p>Phước (Phạm Hồng Phước) là một gã lang thang. Cậu quyết định tạm dừng chuyến hành trình của mình tại một nhà hàng chuyên bán lẩu dê tên là Đêm trắng. Từ lúc nhận được cái nhìn soi mói của Xiếm Hoa (Ngọc Hiệp) và bước vào bên trong cánh cổng luôn đóng kín vào ban ngày của Đêm trắng, cậu không ngờ cuộc đời mình sẽ thay đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Phạm Hồng Phước","avatar":""},{"name":"Ngọc Thanh Tâm","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Ngọc Hiệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
