INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('highlow-ban-dien-anh-3-nhiem-vu-cuoi', 'HIGH&LOW – Bản Điện Ảnh 3: Nhiệm Vụ Cuối', 'HiGH&LOW THE MOVIE 3 FINAL MISSION', 'https://phimimg.com/upload/vod/20231121-1/8e1c52dea3ecd0deb87337c8e749eb96.jpg', 'https://phimimg.com/upload/vod/20231121-1/ddd7b1ae740c640a9044e3fe898fa1b6.jpg', '<p>Tập đoàn Kuryu quyết xâm chiếm khu vực SWORD một lần và mãi mãi, nhưng liên minh băng đảng đường phố đã có kế hoạch của riêng họ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takanori Iwata","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Akira","avatar":""},{"name":"Sho Aoyagi","avatar":""},{"name":"Keita Machida","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Kento Hayashi","avatar":""},{"name":"Naoki Kobayashi","avatar":""},{"name":"ANARCHY","avatar":""},{"name":"ELLY","avatar":""},{"name":"Hatsunori Hasegawa","avatar":""},{"name":"Keisuke Horibe","avatar":""},{"name":"Wataru Ichinose","avatar":""},{"name":"Naoko Iijima","avatar":""},{"name":"Joey Iwanaga","avatar":""},{"name":"TAKAHIRO","avatar":""},{"name":"Yuya Endo","avatar":""},{"name":"Manabu Kurita","avatar":""},{"name":"Masataka Ku","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
