INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-sau-tham', 'Bầu Trời Sâu Thẳm', 'The Deep Sky', 'null', 'https://phimimg.com/upload/vod/20231123-1/e3ebec1d5b3273c76e52ade77d18f22d.jpg', '<p>Lenora và Arlan đang trong mối quan hệ ổn định lâu dài. Cả hai đều muốn khám phá những trải nghiệm tình dục khác nhau với nhau để mang lại sự gắn bó mật thiết hơn nữa. Vì vậy, họ đưa ra quyết định xem xét để mở ra mối quan hệ của họ với các đối tác bổ sung. Họ gặp một người phụ nữ Đức xinh đẹp bí ẩn, Nina và mối quan hệ giữa ba người phát triển theo những cách không ngờ tới. Qua nhiều tháng, mối liên hệ của họ với Nina ngày càng sâu sắc hơn, cho đến khi cả ba người yêu nhau. Tuy nhiên, giữa Lenora và Arlan, mối quan hệ của họ bị căng thẳng bởi mối tình tay ba theo thời gian, lên đến đỉnh điểm với sự thừa nhận bí mật của Ninaùi. The Deep Sky là một bộ phim đầy chất thơ, điều hướng những phức tạp về cảm xúc và triết lý của thế giới của ménage-à-trois.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luise Helm","avatar":""},{"name":"Kelechi Nwadibia","avatar":""},{"name":"Sarah Rose Butler","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
