INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-cu-nhan', 'Sát Thủ Cử Nhân', 'M.F.A.', 'https://phimimg.com/upload/vod/20231123-1/e090f46ae02bf31d091f0c52725ea268.jpg', 'https://phimimg.com/upload/vod/20231123-1/b799fd837aa293c72a96aa4b49f7984a.jpg', '<p>Phim Sát Thủ Cử Nhân - M.F.A. 2017: Xoay quanh một cô sinh viên nghệ thuật đang vật lộn với sự sáng tạo và bị một người bạn cùng lớp hãm hiếp một cách bạo lực. Sau khi thử qua những cách truyền thống để điều trị chấn thương tâm lý của cô, cô bắt đầu đối mặt với kẻ tấn công một cách bốc đồng - một quyết định ẩn chứa hậu quả chết người. Thế giới của cô bị đảo lộn khi một thực tế lạnh lùng được tiết lộ: cô là một trong số nhiều cô gái sống sót bị tấn công tình dục một cách thầm lặng trong khuôn viên trường. Vậy là cô quyết định thành một sát thủ nung nấu việc trả thù những kẻ đồi bại đã hãm hại cô.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leah McKendrick","avatar":""},{"name":"Francesca Eastwood","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Peter Vack","avatar":""},{"name":"David Sullivan","avatar":""},{"name":"David Huynh","avatar":""},{"name":"Marlon Young","avatar":""},{"name":"Jess Nurse","avatar":""},{"name":"Mary Price Moore","avatar":""},{"name":"Laura Robinson","avatar":""},{"name":"Mariah Owen","avatar":""},{"name":"Melanie Britton","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Mike C. Manning","avatar":""},{"name":"Kyle McKeever","avatar":""},{"name":"Kyler Pettis","avatar":""},{"name":"Javie","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
