INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-ke-sat-nhan', 'Bạn Trai Kẻ Sát Nhân', 'Boyfriend Killer', 'https://phimimg.com/upload/vod/20231123-1/c88b58950a1709e4bbe5cb24fc837c51.jpg', 'https://phimimg.com/upload/vod/20231123-1/6c4453031cfc114b776cb447efe8c290.jpg', '<p>Sandra – Người mẹ đau khổ sau cái chết của con trai, tuyệt vọng tìm lại những hình ảnh qua các tài khoản mạng xã hội và thông báo cái chết của cậu đến bạn bè. Cô phát hiện ra manh mối cái chết của Preston không đơn thuần chỉ là một vụ tai nạn, nghi phạm đáng ngờ số 1 lại là Krystal bạn gái của cậu. Sandra phải chứng minh được điều đó trước khi bị diệt khẩu.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barbie Castro","avatar":""},{"name":"Patrick Muldoon","avatar":""},{"name":"Kate Mansi","avatar":""},{"name":"Yancy Butler","avatar":""},{"name":"Frank Licari","avatar":""},{"name":"Rico Aragon","avatar":""},{"name":"Miguel Fasa","avatar":""},{"name":"Susan Gallagher","avatar":""},{"name":"Mary Shaw","avatar":""},{"name":"Todd Bruno","avatar":""},{"name":"Michael Ryerson Uribe","avatar":""},{"name":"Taylor Castro","avatar":""},{"name":"Jeremy Boros","avatar":""},{"name":"Alea Figueroa","avatar":""},{"name":"Kiki Harris","avatar":""},{"name":"Harry Marsh","avatar":""},{"name":"Xavier Cortes","avatar":""},{"name":"Laurel Le","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
