INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-adventure-tri-part-5-coexistence', 'Digimon Adventure tri. Part 5: Coexistence', 'Digimon Adventure tri. Part 5: Coexistence', 'https://phimimg.com/upload/vod/20231123-1/7465fd42da25a238e4145d1988dd259b.jpg', 'https://phimimg.com/upload/vod/20231123-1/6a4c08202d767a6d54c0a42671c2c32c.jpg', '<p>Meicoomon Rampages sau khi chứng kiến Meiko Mochizuki bị thương bởi người đàn ông mang sự giống nhau của Gennai. &quot;Sẽ tốt hơn nếu bạn không được sinh ra ...&quot; Meicoomon biến mất vào thế giới thực, kể từ đó trở nên méo mó. Sở hữu sức mạnh áp đảo, cô ấy là chìa khóa cho sự hủy diệt của thế giới. Hackmon xuất hiện trước Daigo Nishijima và Giáo sư Mochizuki, và tiết lộ một sự thật gây sốc: Cử thế là cố gắng duy trì sự hài hòa nhưng xem xét sức mạnh của Meicoomon là mối đe dọa tồn tại đối với cả hai thế giới. Digimon khác bắt đầu xuất hiện thông qua sự biến dạng. Trở về thế giới thực sự xa lánh bởi trạng thái bất thường của thế giới kỹ thuật số. Bị người dân, người đàn áp và các đối tác của họ bị cô lập và tuyệt vọng tìm cách tiến về phía trước. Trong khi đó, Meiko vẫn tiếp tục mang gánh nặng của cô một mình, bị điếc với giọng nói của đồng đội. Một số phận khắc nghiệt sau đó xảy ra với sự thuần túy và nhạy cảm, Kari Kamiya.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Hitomi Yoshida","avatar":""},{"name":"Junya Ikeda","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Miho Arakawa","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Miwa Matsumoto","avatar":""},{"name":"Yuka Tokumitsu","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Yukiko Morishita","avatar":""},{"name":"Yu","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324407);
