INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-phu', 'Ác Phụ', 'Inconceivable', 'https://phimimg.com/upload/vod/20231120-1/7221f614d5485f62f589624afa530ae8.jpg', 'https://phimimg.com/upload/vod/20231120-1/87d52c2ee1539c44dd67279f7840f7c1.jpg', '<p>Một phụ nữ trẻ bí ẩn, Katie chuyển đến sống tại một thị trấn mới để thoát khỏi quá khứ đau buồn . Cô đã nhanh chóng kết thân với Angela Morgan, một phụ nữ danh gia vọng tộc ở thị trấn đó. Khi họ bắt đầu trở nên khắng khít với nhau, Angela và chồng cô ấy, Brian mời Katie đến sống tại nhà mình để làm vú em. Thời gian sau, tình cảm giữa hai người phụ nữ ngày càng biến đổi thành nỗi ám ảnh khi Katie ngày càng trở nên gắn bó thái quá với con gái của nhà Morgans. Phải chịu đựng những lời nói dối và sự thao túng của cô ta, Angela và Brian nhận ra Katie tốt bụng đang âm thầm hủy hoại gia đình họ từ bên trong.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Nicky Whelan","avatar":""},{"name":"Faye Dunaway","avatar":""},{"name":"Natalie Eva Marie","avatar":""},{"name":"James Van Patten","avatar":""},{"name":"Jonathan Baker","avatar":""},{"name":"Leah Huebner","avatar":""},{"name":"Ele Bardha","avatar":""},{"name":"Corrie Danieley","avatar":""},{"name":"Burgess Byrd","avatar":""},{"name":"Tess Talbot","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
