INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dj-avicii-va-nhung-cau-chuyen-co-that', 'DJ Avicii và Những Câu Chuyện Có Thật', 'Avicii: True Stories', 'https://phimimg.com/upload/vod/20231120-1/070a562808fd5fec4850ee728b20b22f.jpg', 'https://phimimg.com/upload/vod/20231120-1/56a5e340f53c04e26b722bab8bf301e9.jpg', '<p>Bộ phim tài liệu &quot;Avicii: True Stories&quot; kể về cuộc đời và sự nghiệp của DJ nổi tiếng thế giới từ khi anh vụt sáng trong làng giải trí cho tới quyết định giải nghệ đầy bất ngờ đã khắc họa mặt trái của danh tiếng và bạc tiền trong ngành công nghiệp âm nhạc.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Avicii","avatar":""},{"name":"David Guetta","avatar":""},{"name":"Tiësto","avatar":""},{"name":"Mike Einziger","avatar":""},{"name":"Nile Rodgers","avatar":""},{"name":"Wyclef Jean","avatar":""},{"name":"Chris Martin","avatar":""},{"name":"Aloe Blacc","avatar":""},{"name":"Barack Obama","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324407);
