INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rap-phim-ma-am', 'Rạp Phim Ma Ám', 'The Haunted Cinema 2', 'null', 'https://phimimg.com/upload/vod/20231120-1/9a7c6ab062ab8d9196adcaa3753c5b67.jpg', '<p>Rạp Phim Ma Ám - The Haunted Cinema 2 xoay quanh câu chuyện về đêm chết chóc kinh hoàng xảy ra với 8 sinh viên tại rạp chiếu phim. Tình cờ có cơ hội trải nghiệm bộ phim với suất chiếu sớm, 8 sinh viên vừa bước vào rạp thì các hiện tượng kỳ lạ bắt đầu xuất hiện. Họ lần lượt bị rơi vào bẫy của những linh hồn xấu xa và không có cách nào thoát ra được.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ren Qing''an","avatar":""},{"name":"Yan Weier","avatar":""},{"name":"Abby Yin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
