INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-paddington-2', 'Gấu Paddington 2', 'Paddington 2', 'https://phimimg.com/upload/vod/20231120-1/a53ae81dfc137249d10a5a47418c7eac.jpg', 'https://phimimg.com/upload/vod/20231120-1/a8f3699ae03c1222a277e594200e1bc8.jpg', '<p>Chú gấu Paddington vui vẻ hòa nhập với nhà Brown tại Windsor Gardens, nơi chú trở thành thành viên nổi tiếng của cộng đồng, mang lại niềm vui và bánh mứt cho mọi người. Trong khi tìm kiếm một món quà hoàn hảo cho ngày sinh nhật 100 của người dì Lucy yêu dấu của mình, Paddington phát hiện ra một cuốn sách độc đáo trong cửa hàng đồ cổ của ông Gruber nên tìm cách mua nó. Nhưng vào phút chót, cuốn sách bị đánh cắp nên Paddington và Browns phải đi tìm kẻ trộm.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ben Whishaw","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Madeleine Harris","avatar":""},{"name":"Samuel Joslin","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Peter Capaldi","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Simon Farnaby","avatar":""},{"name":"Ben Miller","avatar":""},{"name":"Sanjeev Bhaskar","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Richard Ayo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
