INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-mu', 'Nhà Văn Mù', 'Blind', 'https://phimimg.com/upload/vod/20231120-1/f45b923aab548ce09de5ceed1a2b4863.jpg', 'https://phimimg.com/upload/vod/20231120-1/372f9b03a2f1978ed0039667581dc466.jpg', '<p>Phim Nhà Văn Mù - Blind 2017: Một chuyện tình đam mê đã xảy ra giữa hai người, buộc cả hai phải đặt câu hỏi liệu có bao giờ là quá muộn để tìm được tình yêu đích thực hay không. Nhưng khi chồng của Suzanne trở về, cô ấy buộc phải đưa ra lựa chọn giữa người đàn ông cô ấy yêu thương và người đàn ông cô ấy đã xây dựng một cuộc sống hôn nhân.</p>', 'Full', 1, 'single', 'completed', 8, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alec Baldwin","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Steven Prescod","avatar":""},{"name":"Eden Epstein","avatar":""},{"name":"Dylan McDermott","avatar":""},{"name":"James McCaffrey","avatar":""},{"name":"Viva Bianca","avatar":""},{"name":"Drew Moerlein","avatar":""},{"name":"John Buffalo Mailer","avatar":""},{"name":"Chloe Goutal","avatar":""},{"name":"Jabari Gray","avatar":""},{"name":"Rae Ritke","avatar":""},{"name":"Dorothy Lyman","avatar":""},{"name":"John Michael Lyles","avatar":""},{"name":"Renée Willett","avatar":""},{"name":"Sasha Lazard","avatar":""},{"name":"Stephen Mailer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
