INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-ru-tu-than', 'Lời Ru Tử Thần', 'The Lullaby', 'https://phimimg.com/upload/vod/20231120-1/76dab2b2c0bfe81bf2c0beaedf1c5fbb.jpg', 'https://phimimg.com/upload/vod/20231120-1/b2117780f49fec232ba1900ed9f14785.jpg', '<p>Chloe bị choáng sau khi sinh đứa con đầu lòng. Tiếng khóc không ngừng của đứa con, cảm giác tội lỗi và hoang tưởng ngày một tăng làm cô ta rơi vào trạng thái trần cảm. Với nỗ lực cao để bảo vệ đứa con, Chloe lúc nào cũng nhìn thấy nguy hiểm kề cập. Cô bắt đầu nghe những âm thanh, tiếng ngân nga của bài hát ru thơ ấu và thấy một thực thể lạ xung quanh đứa con của cô. Bị thuyết phục bởi thực thể đó là thực, Chloe làm mọi cách bằng sức của mình để bảo vệ đứa con. Liệu cô ta bị ám bởi ác quỷ không?</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Reine Swart","avatar":""},{"name":"Deanre Reiners","avatar":""},{"name":"Thandi Puren","avatar":""},{"name":"Brandon Auret","avatar":""},{"name":"Dorothy Ann Gould","avatar":""},{"name":"Shayla-Rae McFarlane","avatar":""},{"name":"Eckardt Spies","avatar":""},{"name":"Amjoné Spies","avatar":""},{"name":"Samuel Frauenstein","avatar":""},{"name":"Briony Horwitz","avatar":""},{"name":"Anne-Marie Ellis","avatar":""},{"name":"Lara de Villiers","avatar":""},{"name":"Dayna McFarlane","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324407);
