INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-ru-tu-than', 'Lời Ru Tử Thần', 'The Lullaby', 'lời ru tử thần the lullaby reine swart deanre reiners thandi puren brandon auret dorothy ann gould shayla-rae mcfarlane eckardt spies amjoné spies samuel frauenstein briony horwitz anne-marie ellis lara de villiers dayna mcfarlane ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-quy-vung-tokyo', 'Ngạ Quỷ Vùng Tokyo', 'Tokyo Ghoul Live-Action', 'https://phimimg.com/upload/vod/20231119-1/2ff2b7ed4820436059159a47e752fc4c.jpg', 'https://phimimg.com/upload/vod/20231119-1/2e1843ae2015a8d19e97e87f4fdd094d.jpg', '<p>Phim Ngạ Quỷ Vùng Tokyo - Tokyo Ghoul Live-Action 2017: lấy bối cảnh thời hiện đại, một thế giới hoàn toàn khác khi mà loài người không phải loài đứng đầu chuỗi thức ăn, có một loài sinh vật khát máu, mang hình dạng giống con người nhưng phát triển hơn với những khả năng đặc biệt để trở thành kẻ đi săn, và con mồi chính là loài người, vốn tưởng mình làm chủ thế giới. Không cam chịu làm kẻ bị săn, loài người đứng lên chống lại loài sinh vật kia – Ghoul, quỷ ăn thịt. CCG (Ủy ban chống Quỷ ăn thịt) ra đời, đào tạo 1 lực lượng các thanh tra có kỹ năng chiến đấu cao nhằm chống lại sự tàn sát con người của quỷ ăn thịt. Ken Kaneki vốn là 1 sinh viên đại học bình thường, hiền lành và mê đọc sách. Vì một sự cố, Kaneki được cấy ghép nội tạng từ một quỷ ăn thịt được cho là đã chết, Rize Kamishiro – kẻ đã định giết anh trước khi cô ta bị giết bởi đống thép xà ngang xây dựng đột ngột rơi xuống. Từ đó, anh phải vật lộn để sống cuộc sống nửa người/nửa ghoul, bao gồm cả việc hòa nhập vào thế giới của quỷ ăn thịt đồng thời đối phó với kẻ thù trong khi luôn phải giữ kín thân phận bí mật của mình với những người khác.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masataka Kubota","avatar":""},{"name":"Yoshiko Sengen","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Yo Oizumi","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Hiyori Sakurada","avatar":""},{"name":"Kunio Murai","avatar":""},{"name":"Kai Ogasawara","avatar":""},{"name":"Shunya Shiraishi","avatar":""},{"name":"Shoko Aida","avatar":""},{"name":"Shuntaro Yanagi","avatar":""},{"name":"Minosuke Bando","avatar":""},{"name":"Nozomi Sasaki","avatar":""},{"name":"Kenta Hamano","avatar":""},{"name":"Seika Furuhata","avatar":""},{"name":"Tomoya Maeno","avatar":""},{"name":"Dankan","avatar":""},{"name":"Ryo Iwamats","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
