INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nga-quy-vung-tokyo', 'Ngạ Quỷ Vùng Tokyo', 'Tokyo Ghoul Live-Action', 'ngạ quỷ vùng tokyo tokyo ghoul live-action masataka kubota yoshiko sengen nobuyuki suzuki yo oizumi yu aoi hiyori sakurada kunio murai kai ogasawara shunya shiraishi shoko aida shuntaro yanagi minosuke bando nozomi sasaki kenta hamano seika furuhata tomoya maeno dankan ryo iwamats ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-doi-menh', 'Oan Gia Đổi Mệnh', 'Never Say Die', 'https://phimimg.com/upload/vod/20231119-1/1b481767bcc576e7230962d85ca0fac5.jpg', 'https://phimimg.com/upload/vod/20231119-1/9b33fb715873b137ab914c41b06696cd.jpg', '<p>Phim kể về câu chuyện của Chàng – một tay đấm bốc bại trận, Nàng – một nữ phóng biên nổi tiếng. Hai oan gia vốn không ưa nhau này vô tình bị hoán đổi linh hồn sau một tai nạn trớ trêu. Kể từ đây, biết bao chuyện dở khóc dở cười đã diễn ra với họ. Nhưng cũng nhờ sự trái khoáy này mà những bí mật phía dưới sàn đấu đấm bốc đã từ từ hé lộ.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Allen Ai Lun","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Shen Teng","avatar":""},{"name":"Xue Haowen","avatar":""},{"name":"Chang Yuan","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Wang Zhi","avatar":""},{"name":"Wang Chengsi","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Gao Zhiheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324407);
