INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-beatles-ban-nhac-thay-doi-the-gioi', 'The Beatles: Ban Nhạc Thay Đổi Thế Giới', 'How the Beatles Changed the World', 'https://phimimg.com/upload/vod/20231118-1/69e0b1e80279137936ef318350b4ed52.jpg', 'https://phimimg.com/upload/vod/20231118-1/fb44e69d5725da29c16e5172f5669b35.jpg', '<p>Câu chuyện hấp dẫn về cuộc cách mạng văn hóa, xã hội, tinh thần và âm nhạc được châm ngòi bởi sự xuất hiện của The Beatles. Theo dõi tác động mà bốn thành viên ban nhạc này đã gây ra, đầu tiên là ở quê hương Anh và ngay sau đó là trên toàn thế giới, nó đánh giá lại ban nhạc và đi theo con đường của họ từ những kẻ lật đổ trẻ tuổi trở thành những anh hùng phản văn hóa. Với các cuộc phỏng vấn mới mẻ, tiết lộ với các cộng tác viên chủ chốt cũng như vô số cảnh quay lưu trữ hiếm thấy, đây là một bước đi mới táo bạo đối với ban nhạc quan trọng nhất trong lịch sử âm nhạc và tác động lâu dài của họ đối với văn hóa đại chúng.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"John Lennon","avatar":""},{"name":"George Harrison","avatar":""},{"name":"Paul McCartney","avatar":""},{"name":"Ringo Starr","avatar":""},{"name":"Tony Bramwell","avatar":""},{"name":"Robert Christgau","avatar":""},{"name":"Jonathan Gould","avatar":""},{"name":"Chris Ingham","avatar":""},{"name":"Mark Paytress","avatar":""},{"name":"Anthony DeCurtis","avatar":""},{"name":"Yoko Ono","avatar":""},{"name":"Brian Epstein","avatar":""},{"name":"Mick Jagger","avatar":""},{"name":"Timothy Leary","avatar":""},{"name":"Allen Ginsberg","avatar":""},{"name":"John F. Kennedy","avatar":""},{"name":"John Dunbar","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324407);
