INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-beatles-ban-nhac-thay-doi-the-gioi', 'The Beatles: Ban Nhạc Thay Đổi Thế Giới', 'How the Beatles Changed the World', 'the beatles: ban nhạc thay đổi thế giới how the beatles changed the world john lennon george harrison paul mccartney ringo starr tony bramwell robert christgau jonathan gould chris ingham mark paytress anthony decurtis yoko ono brian epstein mick jagger timothy leary allen ginsberg john f. kennedy john dunbar t ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-bat-dac-di', 'Bạn Trai Bất Đắc Dĩ', 'La Historia Du Un Amor', 'https://phimimg.com/upload/vod/20231118-1/e5e4484e5bcfe793610710fdcef53723.jpg', 'https://phimimg.com/upload/vod/20231118-1/c8a261d2481e1c1a2e2fbf9fa9ea328b.jpg', '<p>Vì 1 hiểu lầm nhỏ mà Lý Phi Phàm, anh chàng lái xe thuê, được diễn viên nổi tiếng Lương Đan Ny hẹn đến phòng cô ở khách sạn. Cuộc gặp bí mật của 2 người bị đội chó săn chụp được khiến Phi Phàm bị nghi ngờ là người tình bí mật của cô. Để làm dịu dư luận, Đan Ny quyết định thuê Phi Phàm làm bạn trai tạm thời của mình</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ryan Zheng Kai","avatar":""},{"name":"Rayza","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Yin Tao","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Bowie Lam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
