INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-hay-tinh-yeu', 'Tình Bạn Hay Tình Yêu?', '#BKKY', 'https://phimimg.com/upload/vod/20231118-1/29f190310bd7fd46d68897e543271f4c.jpg', 'https://phimimg.com/upload/vod/20231118-1/0eda504820a977681584d5ea9748bcdb.jpg', '<p>Jojo, một cô gái 17 tuổi, sắp tốt nghiệp trung học. Sau khi cô bạn Q tiết lộ một bí mật với cô, hai cô gái ngày càng thân thiết và dành nhiều thời gian cho nhau. Cha của Jojo hết lòng tán thành tình bạn và chỉ vui mừng vì Jojo sẽ không đi hẹn hò với con trai. Nhưng rắc rối bắt đầu xảy ra. Sau khi vào đại học, Jojo gặp Jeff và họ bắt đầu hẹn hò - một quyết định gây nguy hiểm cho mối quan hệ của Jojo với Q.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ploiyukhon Rojanakatanyoo","avatar":""},{"name":"Anongnart Yusanon","avatar":""},{"name":"Jeff Watson Kiatmontri","avatar":""},{"name":"Kesavatana Dohrs","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324407);
