INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kich-hoat-cai-chet', 'Kích Hoạt Cái Chết', 'Dead Trigger', 'https://phimimg.com/upload/vod/20231117-1/ce0ba384d5fbf4f8314fa4703788f9eb.jpg', 'https://phimimg.com/upload/vod/20231117-1/102199e9ae9351e6797effd229bc8048.jpg', '<p>Kích Hoạt Cái Chết - Dead Trigger kể về câu chuyện 5 năm sau sự bùng phát của một loại virus bí ẩn biến con người thành những thây ma khát máu, phần lớn dân số thế giới đã bị tiêu diệt. Khi chính phủ không thể ngăn chặn dịch bệnh, đơn vị đặc nhiệm phòng chống dịch bệnh được thành lập với những binh lính cứng rắn nhất và những chuyên gia giỏi nhất để chống lại những kẻ bị nhiễm bệnh. Do số lượng binh lính giảm nhanh chóng, một trò chơi điện tử trực tuyến nổi tiếng Dead Trigger phản ánh những sự kiện kinh hoàng đã được tạo ra. \r\n</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Autumn Reeser","avatar":""},{"name":"Romeo Miller","avatar":""},{"name":"Isaiah Washington","avatar":""},{"name":"Chris Galya","avatar":""},{"name":"Oleg Taktarov","avatar":""},{"name":"Brooke Johnston","avatar":""},{"name":"Natali Yura","avatar":""},{"name":"Luciana Carro","avatar":""},{"name":"Joel Gretsch","avatar":""},{"name":"Tamara Braun","avatar":""},{"name":"Justin Chon","avatar":""},{"name":"Alyona Chekhova","avatar":""},{"name":"Seira Kagami","avatar":""},{"name":"James Chalke","avatar":""},{"name":"Derek Boone","avatar":""},{"name":"Michael Kupisk","avatar":""},{"name":"Jef","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324407);
