INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-thu-3-kinh-hoang', 'Đêm Thứ 3 Kinh Hoàng', '3rd Night', 'null', 'https://phimimg.com/upload/vod/20231129-1/a6c817450dc372747112d4ec27f1a99f.jpg', '<p>Cặp vợ chồng trẻ chuyển về một nông trại hoang dã để thoát khỏi sự điên rồ của cuộc sống hiện đại. Nhưng họ đã lầm! Sau đêm đầu tiên, mèo cưng mất tích, bắt đầu một chuỗi những sự kiện đáng sợ, như có ai đó hoặc gì đó đang theo dõi từng động thái của họ và đêm thứ 3 thực sự là ác mộng. Nỗi sợ hãi khiến các nhân vật lẫn người xem hoảng hốt tột độ!</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jesse McGinn","avatar":""},{"name":"Robert Hartburn","avatar":""},{"name":"Bruce Denny","avatar":""},{"name":"Connor Gosatti","avatar":""},{"name":"Rose McKenna","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324407);
