INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lommbock', 'Lommbock', 'Lommbock', 'https://phimimg.com/upload/vod/20231117-1/85ef2098c78b07f9a5107aa1bc236a1a.jpg', 'https://phimimg.com/upload/vod/20231117-1/331537bfc3950d8868fa8165ac230be2.jpg', '<p>Sau khi tìm được tình yêu ở thành phố Dubai vắng bóng ma túy, Stefan quay về Đức lấy giấy tờ để kết hôn. Nhưng thói xấu của anh bạn Kai khiến mọi việc trở nên phức tạp.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Moritz Bleibtreu","avatar":""},{"name":"Lucas Gregorowicz","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Antoine Monot Jr.","avatar":""},{"name":"Alexandra Neldel","avatar":""},{"name":"Melanie Winiger","avatar":""},{"name":"Louis Hofmann","avatar":""},{"name":"Mavie Hörbiger","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Elmar Wepper","avatar":""},{"name":"Kailas Mahadevan","avatar":""},{"name":"Mehmet Scholl","avatar":""},{"name":"Thomas Binder","avatar":""},{"name":"Daniela Eck","avatar":""},{"name":"Gunnar Krupp","avatar":""},{"name":"Julius Nitsc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
