INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-co-phieu-luu-ky', 'Vẹt Cò Phiêu Lưu Ký', 'A Stork''s Journey', 'https://phimimg.com/upload/vod/20231116-1/7a5db082885892d6ca9e50f565713c3f.jpg', 'https://phimimg.com/upload/vod/20231116-1/7e7e685451b72d8ac57555f1b6f60991.jpg', '<p>Vốn là một chú chim sẻ mồ côi. Richard được một gia đinh vẹt cò nhận về nuôi và hết lòng yêu mến. Có nằm mơ Richard cũng chưa bao giờ nghĩ mình không phải là vẹt cò. Cho đến một ngày khi bố mẹ nuôi cùng anh trai của chú thừa nhận rằng họ phải bắt đầu đi tránh rét và tìm đến cái nắng ấm chói chang của miền đất châu Phi, hành trình chông gai đó chưa bao giờ phù hợp với thể trạng của Richard vốn là một chú chim sẻ yếu ớt. Lòng nặng trĩu nhưng gia đinh vẹt cò buộc phải để Richard lại để bắt đầu chuyến đi của mình. Việc không có một đôi cánh rậm khỏe mạnh của giống vẹt cò không có nghĩa là Richard không thể bay đến Phi châu để đoàn tụ cùng gia đinh. Quyết tâm lên đường, may mắn thay chú lại được Olga, một cô cú vọ ...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2017, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Cooper Kelly Kramer","avatar":""},{"name":"Shannon Conley","avatar":""},{"name":"Marc Thompson","avatar":""},{"name":"Jason Griffith","avatar":""},{"name":"Maud Ackermann","avatar":""},{"name":"Jonathan Todd Ross","avatar":""},{"name":"Schroeder Kacmar","avatar":""},{"name":"Drake Bell","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3