INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-cuop-nghien-whiskey', 'Trùm Cướp Nghiện Whiskey', 'The Whiskey Bandit', 'https://phimimg.com/upload/vod/20231116-1/dfb378053860564b614d19afb967eb9c.jpg', 'https://phimimg.com/upload/vod/20231116-1/2632eccd85fe0298eb77c8ea16ffee4f.jpg', '<p>The Whiskey Bandit kể về Viszkis, một trong những tên cướp ngân hàng nổi tiếng ở Hungary. Trước khi thực hiện một phi vụ nào đó hắn đều uống rượu Whiskey...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Bence Szalay","avatar":""},{"name":"Piroska Móga","avatar":""},{"name":"Zoltán Schneider","avatar":""},{"name":"Björn Freiberg","avatar":""},{"name":"Imre Csuja","avatar":""},{"name":"Sándor Oszter","avatar":""},{"name":"Attila Ifj. Vidnyánszky","avatar":""},{"name":"Dániel Mertz","avatar":""},{"name":"Viktor Klem","avatar":""},{"name":"Gergely Kaszás","avatar":""},{"name":"György Gazsó","avatar":""},{"name":"Zsolt Szentiványi","avatar":""},{"name":"Ildikó Tóth","avatar":""},{"name":"Zoltan Durko","avatar":""},{"name":"Sándor Zsótér","avatar":""},{"name":"Judit Pogány","avatar":""},{"name":"Gábor Cső","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
