INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trum-cuop-nghien-whiskey', 'Trùm Cướp Nghiện Whiskey', 'The Whiskey Bandit', 'trùm cướp nghiện whiskey the whiskey bandit bence szalay piroska móga zoltán schneider björn freiberg imre csuja sándor oszter attila ifj. vidnyánszky dániel mertz viktor klem gergely kaszás györgy gazsó zsolt szentiványi ildikó tóth zoltan durko sándor zsótér judit pogány gábor cső ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-truong-quan-lot-ban-dien-anh-hoanh-trang-dau-tien', 'Đội Trưởng Quần Lót: Bản Điện Ảnh Hoành Tráng Đầu Tiên', 'Captain Underpants: The First Epic Movie', 'https://phimimg.com/upload/vod/20231116-1/f430a2ebb20bb3b22f94b3ccc03248a3.jpg', 'https://phimimg.com/upload/vod/20231116-1/c5fc2e10ca360d135b46c109e118ae9b.jpg', '<p>Phim hoạt hình 3D của DreamWorks Animation kết hợp cùng Scholastic Entertainment vốn chuyển thể từ bộ tiểu thuyết thiếu nhi của tác giả Dav Pilkey. Captain Underpants vốn là siêu anh hùng hư cấu được hai nhóc học sinh George và Harold thần tượng. Lần nọ, hai nhóc quyết định… thôi miên Mr. Krupp, ông hiệu trưởng xấu tính tại trường mà chúng học. Ngờ đâu, thầy Krupp thực sự tin rằng mình là Captain Underpants, quyết tâm bảo vệ hòa bình thế giới.Nguyên tác vốn là một tập hợp những mẫu truyện ngắn rời rạc, dẫn đến việc kịch bản của bản điện ảnh vẫn còn là một ẩn số. Phim có sự góp giọng của nhiều tên tuổi nổi tiếng như Ed Helms, Kevin Hart, Thomas Middleditch, Nick Kroll và Jordan Peele.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"Thomas Middleditch","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"Jordan Peele","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"DeeDee Rescher","avatar":""},{"name":"Brian Posehn","avatar":""},{"name":"David Soren","avatar":""},{"name":"Mel Rodriguez","avatar":""},{"name":"Susan Fitzker","avatar":""},{"name":"Lynnane Zager","avatar":""},{"name":"Tiffany Lauren Bennicke","avatar":""},{"name":"James Ryan","avatar":""},{"name":"Leslie David Baker","avatar":""},{"name":"Sugar Lyn Beard","avatar":""},{"name":"Lesley Ni","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
