INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-truong-quan-lot-ban-dien-anh-hoanh-trang-dau-tien', 'Đội Trưởng Quần Lót: Bản Điện Ảnh Hoành Tráng Đầu Tiên', 'Captain Underpants: The First Epic Movie', 'đội trưởng quần lót: bản điện ảnh hoành tráng đầu tiên captain underpants: the first epic movie kevin hart thomas middleditch ed helms nick kroll jordan peele kristen schaal deedee rescher brian posehn david soren mel rodriguez susan fitzker lynnane zager tiffany lauren bennicke james ryan leslie david baker sugar lyn beard lesley ni ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-spirou', 'Cậu bé Spirou', 'Little Spirou', 'https://phimimg.com/upload/vod/20231129-1/70c259c15d63f2b3e953c04fb7a9fe55.jpg', 'https://phimimg.com/upload/vod/20231129-1/c6c4f430ae529eda8e7c40dc3e5d16cc.jpg', '<p>Chú bé Spirou nhỏ bé, giống như tất cả các thành viên khác trong gia đình, cậu đã được định sẵn sự nghiệp khi trưởng thành. Khi mẹ cậu thông báo rằng cậu sẽ tham gia trường phù rể vào đầu năm học tới, Spirou bé nhỏ, với sự giúp đỡ của bạn bè, sẽ tận dụng những ngày cuối cùng trước khi vào năm học để tuyên bố tình yêu của mình với Suzette.Viện Pháp tại Việt Nam mong muốn có thể đưa văn hóa Pháp tới gần hơn với các bạn khán giả thông qua các bộ phim Pháp đặc sắc như lời cảm ơn và lời chúc đầu năm chân thành nhất mà Viện Pháp tại Việt Nam xin gửi đến quý vị trong dịp đầu năm mới Tân Sửu 2021.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Sacha Pinault","avatar":""},{"name":"Natacha Régnier","avatar":""},{"name":"Pierre Richard","avatar":""},{"name":"François Damiens","avatar":""},{"name":"Philippe Katerine","avatar":""},{"name":"Armelle","avatar":""},{"name":"Gwendolyn Gourvenec","avatar":""},{"name":"Lila Poulet-Berenfeld","avatar":""},{"name":"Mahé Laridan","avatar":""},{"name":"Timothée Moffen","avatar":""},{"name":"Gwendal Malguid-Salvatore","avatar":""},{"name":"Aaron Denis","avatar":""},{"name":"Mahogany-Elfie Elis","avatar":""},{"name":"Pierre Gommé","avatar":""},{"name":"Tom Grimple","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
