INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-be-spirou', 'Cậu bé Spirou', 'Little Spirou', 'cậu bé spirou little spirou sacha pinault natacha régnier pierre richard françois damiens philippe katerine armelle gwendolyn gourvenec lila poulet-berenfeld mahé laridan timothée moffen gwendal malguid-salvatore aaron denis mahogany-elfie elis pierre gommé tom grimple ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dao-do-lang', 'Chiến Đao Đồ Lang', 'Wolf Hunters', 'null', 'https://phimimg.com/upload/vod/20231129-1/c6974b79196af360773810f65620c529.jpg', '<p>Phim Chiến Đao Đồ Lang - Wolf Hunters 2017: xoay quanh công việc của cảnh sát phòng chống ma túy, kể về mối quan hệ với người thân của cảnh sát phòng chống ma túy Lam Hải, thông qua một chuỗi sự kiện đã thể hiện những áp lực và trách nhiệm nặng nề của công việc vừa nguy hiểm vừa áp lữ này. Bên cạnh đó, phim còn kể lại câu chuyện các chiến sĩ cảnh sát phòng chống ma túy với tinh thần cống hiến và hy sinh hết mình đã dũng cảm tiến lên, không ngại nguy hiểm thâm nhập và cắt đứt giao dịch mua bán ma túy của tội phạm. Phim lấy chân lý cái thiện luôn chiến thắng cái ác, truyền tải năng lượng tích cực, phần nào khiến khán giả hiểu hơn về nghề nghiệp bình thường nhưng cũng đầy vĩ đại này.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang up","avatar":""},{"name":"Zhuang Xiaolong","avatar":""},{"name":"Sang Hyun Lee","avatar":""},{"name":"Zhang Kai","avatar":""},{"name":"Long Shin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
