INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-chan-chinh', 'Tình Yêu Chân Chính', 'Little Lucky', 'https://phimimg.com/upload/vod/20231117-1/a9b859193b0f5002930b1ff53794f546.jpg', 'https://phimimg.com/upload/vod/20231117-1/311445679742165755981c8f1fd0924a.jpg', '<p>Xoay quanh 3 cặp đôi với mỗi cặp là 1 hoàn cảnh khác nhau. Dố là 1 đôi thanh mai trúc mã không dám thổ lộ tình cảm, 1 đôi đã chia tay nhưng còn lưu luyến, đôi còn lại sắp tổ chúc hôn lễ nhưng lại gặp trục trặc phút chót vì gia đình. Trải qua bao thử thách, liệu các đôi trai tài gái sắc này có đi bến đỗ hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Allen Ai Lun","avatar":""},{"name":"Tian Liang","avatar":""},{"name":"Myolie Wu","avatar":""},{"name":"Raquel Xu","avatar":""},{"name":"Zhao Wenqi","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Zijian Wang","avatar":""},{"name":"An-ni Shih","avatar":""},{"name":"Zhang Danfeng","avatar":""},{"name":"Na Wei","avatar":""},{"name":"Jia Ni","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Mimi Chu","avatar":""},{"name":"Zhang Zhihua","avatar":""},{"name":"Ying Zhuang","avatar":""},{"name":"Simon Twu","avatar":""},{"name":"Marc Philip Goodman","avatar":""},{"name":"Liu Yajin","avatar":""},{"name":"Wang Xinyu","avatar":""},{"name":"Wang Zi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
