INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-bay', 'Giăng Bẫy', 'Black Butterfly', 'https://phimimg.com/upload/vod/20231116-1/f94db1648724eb98a01c01b95abcb084.jpg', 'https://phimimg.com/upload/vod/20231116-1/90e1059de7d0a2bb5803b6a21f830ac3.jpg', '<p>Paul là một nhà văn chuyên viết kịch bản phim nhưng đã 4 năm trời từ khi vợ qua đời, ông không viết thêm được gì. Muốn bán căn nhà nhưng không có ai mua, ông đành sống cô đơn nơi đó. Được một kẻ lang thang giúp đỡ, ông quyết định mang hắn về nhà cưu mang. Khi một cơn bão cắt đứt nguồn điện, cuộc đụng độ giữa nhà biên kịch, kẻ lang thang và một cô gái xinh đẹp mang đến rất nhiều bất ngờ.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Abel Ferrara","avatar":""},{"name":"Nicholas Aaron","avatar":""},{"name":"Vincent Riotta","avatar":""},{"name":"Gioia Libardoni","avatar":""},{"name":"Nathalie Rapti Gomez","avatar":""},{"name":"Alexandra Klim","avatar":""},{"name":"Katie McGovern","avatar":""},{"name":"Randall Paul","avatar":""},{"name":"Timothy Martin","avatar":""},{"name":"Cristina Moglia","avatar":""},{"name":"Tracy Green","avatar":""},{"name":"Cherish Gaines","avatar":""},{"name":"George K","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324407);
