INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-linh-thu-12', 'Người Lính Thứ 12', 'The 12th Man', 'https://phimimg.com/upload/vod/20231116-1/67b5c81172e08a4a0609fbcfa4f9986b.jpg', 'https://phimimg.com/upload/vod/20231116-1/d0864c7ad4fae7fcb0405e7211579589.jpg', '<p>Họ là 12 người lính Nauy hoạt động ngầm, chuyên đánh phá các cơ sở của Đức Quốc xã. Họ đã vượt biển Bắc đến vịnh Toftefjord cùng 7 tấn thuốc nổ trên một thuyền đánh cá. Nhưng con thuyền của họ đã bị nghi ngờ và bắn chìm ngay trên biển...</p>', 'Full', 1, 'single', 'completed', 21, 2017, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Thomas Gullestad","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Marie Blokhus","avatar":""},{"name":"Mads Sjøgård Pettersen","avatar":""},{"name":"Martin Kiefer","avatar":""},{"name":"Vegar Hoel","avatar":""},{"name":"Håkon Thorstensen Nielsen","avatar":""},{"name":"Eirik Risholm Velle","avatar":""},{"name":"Daniel Frikstad","avatar":""},{"name":"Alexander Zwart","avatar":""},{"name":"Eric Dirnes","avatar":""},{"name":"Torgny Aanderaa","avatar":""},{"name":"Håkon Smeby","avatar":""},{"name":"Kenneth Åkerland Berg","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
