INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('joshua-thieu-nien-chong-lai-sieu-cuong', 'Joshua: Thiếu niên chống lại Siêu cường', 'Joshua: Teenager vs. Superpower', 'https://phimimg.com/upload/vod/20231115-1/2d7431c693445f308939615ae7420e0a.jpg', 'https://phimimg.com/upload/vod/20231115-1/2821d2f4e61076def63ecddfc841a9e6.jpg', '<p>Được nhà hoạt động thiếu niên Joshua Wong kêu gọi, các công dân trẻ của Hồng Kông xuống đường để bảo vệ lịch sử tự trị của họ khỏi Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joshua Wong","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324407);
