INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-tonya', 'Tôi Là Tonya', 'I, Tonya', 'https://phimimg.com/upload/vod/20231115-1/951e8dba95a958ac0b62f47c41afab2d.jpg', 'https://phimimg.com/upload/vod/20231115-1/3a083d55abe03e84a269a6b3c03e1c94.jpg', '<p>Từ vị trí sai lầm của các đường ray ở Portland, Oregon, cựu cầu thủ cạnh tranh của Skater Tonya Harding không bao giờ được chấp nhận đầy đủ trong cộng đồng trượt băng nghệ thuật vì không phải là hình ảnh của ân sủng, sinh sản và đặc quyền mà cộng đồng muốn miêu tả, mặc dù cô ấy đang ở tự nhiên có năng khiếu trong môn thể thao thể thao. Mặc dù cuối cùng đã thu được một số thành công trong nghệ sĩ trượt băng là nhà vô địch quốc gia, một huy chương vô địch thế giới, một Olympian, và là người phụ nữ Mỹ đầu tiên hoàn thành một hành trình ba trong cuộc thi, cô ấy được cho là có thể được biết đến nhiều nhất với hiệp hội của mình để &quot;sự cố&quot;: chân Bashing vào ngày 6 tháng 1 năm 1994 của đối thủ cạnh tranh của mình, Nancy Kerrigan, người, không giống như Tonya, là tất cả mọi thứ mà cộng đồng trượt băng từng muốn trong đại diện của họ. Sự liên kết của cô ấy đối với sự cố đó đã dẫn đến Tonya bị cấm khỏi trượt băng nghệ thuật cạnh tranh cho cuộc sống. Câu chuyện của Tonya ngay từ đầu cuộc sống trượt băng của cô ở tuổi bốn đến hậu quả của vụ việc được trình bày. Bên cạnh Tonya mình, những người chủ chốt trong cuộc đời cô đưa ra quan điểm về vai trò của họ trong cuộc sống của mình. Mặc dù họ có thể đồng ý về các vấn đề rộng rãi trong tầm tay, chẳng hạn như sự cố đã xảy ra, chúng có thể thay đổi rộng rãi trong hồi ức của họ về các chi tiết. Những người này là: cô hầu bàn của cô ấy lavona vàng, mặc dù đã trả tiền cho những bài học trượt băng bằng đắt tiền của cô ấy, đã lạm dụng đối với cô ấy về thể chất và về mặt tinh thần, không bao giờ tin rằng cô ấy đủ tốt trong bất kỳ khía cạnh nào của từ này, và người kéo cô ấy từ trường đến chỉ tập trung vào trượt băng nghệ thuật; Diane Rawlinson, huấn luyện viên phục vụ đầu tiên và lâu dài nhất của cô, người tốt hay xấu, phần lớn, phần lớn để Tonya là Tonya theo cách cô thể hiện mình với thế giới trượt băng nghệ thuật; Jeff Gillolyool, người chồng đầu tiên của cô, hai người cũng có một mối quan hệ hỗn loạn trên một nhu cầu được yêu thương có lẽ mà không thực sự yêu người kia; Người bạn của Jeff và vệ sĩ Tonya Shawn Eckardt, một bóng đèn mờ, người tin rằng mình là một cầu thủ lớn hơn trong chương trình lớn của cuộc sống hơn là anh ta thực sự là; và nhà báo thể thao Martin Maddox, một nhân vật hư cấu cung cấp bình luận chung về những gì các phương tiện truyền thông thể thao như một tập thể muốn từ Tonya và sự cố</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Robbie","avatar":""},{"name":"Sebastian Stan","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Bojana Novaković","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Caitlin Carver","avatar":""},{"name":"Maizie Smith","avatar":""},{"name":"Suehyla El-Attar","avatar":""},{"name":"Jason Davis","avatar":""},{"name":"Mea Allen","avatar":""},{"name":"Cory Chapman","avatar":""},{"name":"Amy Fox","avatar":""},{"name":"Cara Mantella","avatar":""},{"name":"Joshua M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
