INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-thay-that-lac-long-trong-the-gioi-nay', 'Tôi thấy thật lạc lõng trong thế giới này', 'I Don''t Feel at Home in This World Anymore', 'https://phimimg.com/upload/vod/20231113-1/9a94fe7f6293e94b648fe849b9278913.jpg', 'https://phimimg.com/upload/vod/20231113-1/bab7fa9f3765af641af9b47d70e3d18d.jpg', '<p>Cô trợ lý y tá rụt rè đã thấy cuộc sống thú vị hơn khi cùng người hàng xóm độc thân truy tìm băng cướp đã đột nhập vào nhà của cô.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melanie Lynskey","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"David Yow","avatar":""},{"name":"Jane Levy","avatar":""},{"name":"Devon Graye","avatar":""},{"name":"Christine Woods","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Gary Anthony Williams","avatar":""},{"name":"Myron Natwick","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Jason Manuel Olazabal","avatar":""},{"name":"Lee Eddy","avatar":""},{"name":"Matt Orduna","avatar":""},{"name":"Michelle Moreno","avatar":""},{"name":"Chris Doubek","avatar":""},{"name":"Marilyn Faith Hickey","avatar":""},{"name":"Jare","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
