INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-sach-cua-henry', 'Quyển Sách Của Henry', 'The Book of Henry', 'https://phimimg.com/upload/vod/20231114-1/948c7f7ea12e0b0e42086dca85e27ec5.jpg', 'https://phimimg.com/upload/vod/20231114-1/860f95955be3ac66b6974751bf54ec2f.jpg', '<p>Đôi khi mọi việc không phải lúc nào cũng như vẻ ngoài, đặc biệt là ở thị trấn ngoại ô nhỏ nơi gia đình Carpenter sống. Susan Carpenter làm việc với tư cách là một nhân viên phục vụ tại một quán ăn cùng với người bạn thân Sheila. Con trai nhỏ Peter của cô là một đứa trẻ 8 tuổi vui vẻ. Chăm sóc mọi người và mọi thứ theo cách riêng của mình là con trai lớn Henry 11 tuổi. Henry là một cậu bé thần đồng luôn bảo vệ em trai và lo liệu tính toán mọi việc thay cho mẹ. Henry phát hiện ra rằng gia đình bên cạnh, nơi bạn cùng lớp của Henry, Christina sống cùng với cha dượng, đang ẩn giấu một bí mật nguy hiểm - và Henry đã nghĩ ra kế hoạch đáng ngạc nhiên để giúp đỡ. Tuy nhiên cậu lại lâm bệnh nặng, để lại kế hoạch li kỳ này cho người mẹ trẻ con và vô tư của mình thực hiện.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Jaeden Martell","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Maddie Ziegler","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Tonya Pinkins","avatar":""},{"name":"Geraldine Hughes","avatar":""},{"name":"Jackson Nicoll","avatar":""},{"name":"Joel Marsh Garland","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Marjan Neshat","avatar":""},{"name":"Maxwell Simkins","avatar":""},{"name":"Donnetta Lavinia Grays","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
