INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-em-ho-rachel', 'Cô Em Họ Rachel', 'My Cousin Rachel', 'https://phimimg.com/upload/vod/20231114-1/6ffe2faa3226e85e7f2f2349b3590c98.jpg', 'https://phimimg.com/upload/vod/20231114-1/0869b43b478eebec06c1bfec9010db50.jpg', '<p>Bộ phim &quot; Cô Em Họ Rachel&quot; kể về kế hoạch trả thù của một chàng trai với cô em họ bí ẩn, xinh đẹp vì anh nghi ngờ cô chính là kẻ sát hại người giám hộ của mình. Tuy nhiên, chính chàng trai lại không thể cưỡng lại sự quyến rũ và xinh đẹp của người con gái ấy, đồng thời phim đã lột tả những dòng cảm xúc vô cùng tinh tế và sinh động của chàng trai.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rachel Weisz","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Holliday Grainger","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Vicki Pepperdine","avatar":""},{"name":"Tim Barlow","avatar":""},{"name":"Bobby Scott Freeman","avatar":""},{"name":"Tristram Davies","avatar":""},{"name":"Andrew Havill","avatar":""},{"name":"Poppy Lee Friar","avatar":""},{"name":"Katherine Pearce","avatar":""},{"name":"Roy Sampson","avatar":""},{"name":"Adam Loxley","avatar":""},{"name":"Andrew Knot","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
