INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-quy', 'Luật Quỷ', 'The Lodgers', 'https://phimimg.com/upload/vod/20231114-1/e4d2e229fbb98d0900fdbe34a072d5fb.jpg', 'https://phimimg.com/upload/vod/20231114-1/48ae999078f590884d772ddd55546b78.jpg', '<p>Hai anh em Edward và Rachel buộc phải sống trong căn nhà của dòng tộc và mắc phải lời nguyền của tổ tiên, khi họ di cư từ Anh sang Ireland, tất cả những người con không được rời bỏ toà nhà và họ phải tuân thủ 3 điều luật khắt khe để giữ được mạng sống. Vì không chịu nổi sự giam cầm, Rachel đã phá vỡ điều luật và cái kết nào sẽ đến với cô khi màn đêm buông xuống?</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Charlotte Vega","avatar":""},{"name":"Bill Milner","avatar":""},{"name":"Eugene Simon","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Moe Dunford","avatar":""},{"name":"Deirdre O''Kane","avatar":""},{"name":"Roisin Murphy","avatar":""},{"name":"Anthony Murphy","avatar":""},{"name":"Brendan O''Rourke","avatar":""},{"name":"Emmet Kelly","avatar":""},{"name":"Emma Whelan","avatar":""},{"name":"Ronan Byrne","avatar":""},{"name":"Elijah Egan","avatar":""},{"name":"Matthew Sludds","avatar":""},{"name":"Jack O''Malley","avatar":""},{"name":"Rachel Bennett","avatar":""},{"name":"Sarah","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324407);
