INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhip-dieu-tinh-yeu', 'Nhịp điệu tình yêu', 'Love Beats Rhymes', 'https://phimimg.com/upload/vod/20231114-1/24639cd08f07bb11d22c9fc6f8f7b1f4.jpg', 'https://phimimg.com/upload/vod/20231114-1/42932b8e95714237bcd718d590a119a7.jpg', '<p>Sau khi đăng ký một khóa thơ ca ở trường đại học, một nghệ sĩ nhạc rap đang sống chật vật đã tìm thấy cảm hứng cho tiếng nói mới của mình thông qua đấu thơ.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Azealia Banks","avatar":""},{"name":"Common","avatar":""},{"name":"Jill Scott","avatar":""},{"name":"Lorraine Toussaint","avatar":""},{"name":"Hana Mae Lee","avatar":""},{"name":"Lucien Laviscount","avatar":""},{"name":"John David Washington","avatar":""},{"name":"Mary Christina Brown","avatar":""},{"name":"Nancy Cejari","avatar":""},{"name":"Esperanza Spalding","avatar":""},{"name":"Jin Au-Yeung","avatar":""},{"name":"Jeremie Harris","avatar":""},{"name":"Jas Anderson","avatar":""},{"name":"Bryan Burton","avatar":""},{"name":"Ryan Metcalf","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
