INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-ao', 'Vòng Xoay Ảo', 'The Circle', 'https://phimimg.com/upload/vod/20231115-1/c994614b7cbe4383dbd85ef9adc7f20f.jpg', 'https://phimimg.com/upload/vod/20231115-1/9734c47af98e3ebd10f03968ad7be04a.jpg', '<p>Vòng Xoay Ảo - The Circle lấy bối cảnh trong tương lai, thời đại mà con người phải đối mặt với mối đe dọa vô cùng nguy hiểm bởi công nghệ kỹ thuật số quá tân tiến đến mức vượt ngoài tầm kiểm soát. Cô gái trẻ đầy tham vọng Mae vừa được nhận vào làm việc tại The Circle, một tập đoàn công nghệ nổi tiếng sở hữu những phúc lợi hàng đầu thế giới. Ngỡ như mọi thứ đều hoàn hảo, cho đến khi chia sẻ những thông tin cá nhân lên mạng xã hội của công ty, Mae mới dần phát hiện ra nhiều bí mật khủng khiếp được giấu kín đằng sau sự phát triển và danh tiếng của The Circle.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Watson","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"John Boyega","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Ellar Coltrane","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Glenne Headly","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Nate Corddry","avatar":""},{"name":"Mamoudou Athie","avatar":""},{"name":"Amir Talai","avatar":""},{"name":"Smith Cho","avatar":""},{"name":"Ellen Wong","avatar":""},{"name":"Judy Reyes","avatar":""},{"name":"Elvy","avatar":""},{"name":"Roger Joseph Manning Jr.","avatar":""},{"name":"Joey Waronker","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0