INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-vi-anh-yeu-em', 'Bởi Vì Anh Yêu Em', 'Because I Love You', 'https://phimimg.com/upload/vod/20231113-1/59673c4f57df5648fda7128b59d7cfb9.jpg', 'https://phimimg.com/upload/vod/20231113-1/8010a1195ddaaae531c526185cda4b04.jpg', '<p>Bộ phim kể về câu chuyện của một nhà viết nhạc thiên tài Lee Hyun. Vào đúng ngày cầu hôn, anh đã gặp phải tai nạn và ngẫu nhiên trở thành một sứ giả tình yêu. Anh có thể nhập linh hồn của mình vào cơ thể những người khác và với khả năng này, anh đã giúp nhiều người vượt qua khó khăn khi đến với tình yêu. Tuy nhiên anh lại không thể giúp mình. Liệu sau cùng, hạnh phúc có mỉm cười với anh?</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Tae-hyun","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Seo Hyun-jin","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Sunwoo Yong-nyeo","avatar":""},{"name":"Park Geun-hyung","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Oh Na-ra","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Kim Sa-hee","avatar":""},{"name":"Kim Yoon-hye","avatar":""},{"name":"Kim Kang-hoon","avatar":""},{"name":"Jang Hyuk","avatar":""},{"name":"Park Ji-yoon","avatar":""},{"name":"Lee Jae-woo","avatar":""},{"name":"Han Hee-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
