INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-qua-le-khong-lo', 'Cuộc Phiêu Lưu Của Quả Lê Khổng Lồ', 'The Incredible Story of the Giant Pear', 'https://phimimg.com/upload/vod/20231113-1/b1fb726d782b18c0ed6e56ed75edffcc.jpg', 'https://phimimg.com/upload/vod/20231113-1/2830623a72c244e62ace6ca2288b8a82.jpg', '<p>Cuộc Phiêu Lưu Của Quả Lê Khổng Lồ - The Incredible Story of the Giant Pear (2017):Voi Sebastian và cô bạn mèo thân thiết Mitcho sống cùng nhau trong một ngôi nhà nhỏ ấm cúng ven bờ biển của thị trấn Sunnytown. Cuộc sống của đôi bạn diễn ra trong bình yên và vui vẻ cho đến một ngày ngài thị trưởng đáng quý JB biến mất. Lúc đang thưởng ngoạn thú vui câu cá của mình, mèo Mitcho nhận được tin báo được cất giữ trong một cái chai rằng JB đang bị mắc kẹt tại Đảo Huyền Bí. Ngoài ra trong chai là một hạt mầm nhỏ, mèo Micho mang hạt gieo ở trong vườn, sáng hôm sau một quả lê khổng lồ mọc ra từ đó! Quả lê được voi Sebastian, mèo Mitcho tiến sĩ Glucose hài hước biến thành một chiếc thuyền để bắt đầu cuộc phiêu lưu nguy hiểm nhưng không kém phần hài hước với cướp biển, rồng biển và những con ma tò mò. Phải mất tất cả lòng can đảm, nhưng không có gì có thể ngăn chặn hai người bạn của chúng tôi - họ quyết tâm tìm Đảo Huyền Bí và trở về nhà với JB.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2017, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Alfred Bjerre Larsen","avatar":""},{"name":"Liva Elvira Magnussen","avatar":""},{"name":"Peter Frödin","avatar":""},{"name":"Henrik Koefoed","avatar":""},{"name":"Peter Plaugborg","avatar":""},{"name":"Søren Pilmark","avatar":""},{"name":"Jakob Oftebro","avatar":""},{"name":"Peter Zhelder","avatar":""},{"name":"Bjarne Henriksen","avatar":""},{"name":"Peter Aude","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
