INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-tien-xu', 'Điệp vụ tiền xu', 'Coin Heist', 'https://phimimg.com/upload/vod/20231112-1/e370df2b8aad7e9e0f2cd187d20758af.jpg', 'https://phimimg.com/upload/vod/20231112-1/3363eadbeb09ea53db996632990ad8b4.jpg', '<p>Khi cơn khủng hoảng đe dọa phải đóng cửa ngôi trường trung học của họ, bốn thiếu niên ấp ủ kế hoạch gây quỹ 10 triệu đô. Bước một sẽ là gì? Đột nhập Sở đúc tiền Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Saxon","avatar":""},{"name":"Alexis G. Zall","avatar":""},{"name":"Sasha Pieterse","avatar":""},{"name":"Jay Walker","avatar":""},{"name":"Michael Cyril Creighton","avatar":""},{"name":"Mark Blum","avatar":""},{"name":"David W. Thompson","avatar":""},{"name":"Neal Huff","avatar":""},{"name":"Olivia Birkelund","avatar":""},{"name":"Blanche Baker","avatar":""},{"name":"Connor Ratliff","avatar":""},{"name":"Will Denton","avatar":""},{"name":"Andy Grotelueschen","avatar":""},{"name":"Slate Holmgren","avatar":""},{"name":"Muhammad Cunningham","avatar":""},{"name":"Alex Maizus","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
