INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('heart-blackened', 'Heart Blackened', 'Heart Blackened', 'https://phimimg.com/upload/vod/20231112-1/3bfb400f4c59a227d5f9d926484455c6.jpg', 'https://phimimg.com/upload/vod/20231112-1/772de0d8a736383c4087263527440724.jpg', '<p>Tae-san là một người đàn ông thực sự có tất cả mọi thứ - tiền bạc, danh tiếng và quyền lực. Tất cả mọi thứ mà một người đàn ông có thể mong muốn. Anh ta có hai người phụ nữ mà anh ta sẽ không thay đổi cho thế giới. Họ là con gái duy nhất của mình, Mira và một biểu đồ - Topping Pop Star Fiancee, Yuna. Tae-san muốn họ hòa thuận, nhưng Mira vui lòng đến với mẹ kế của cô ấy. Một ngày nọ, Yuna bị giết trong một tai nạn khủng khiếp, và Mira bị bắt là nghi phạm. Tae-san chắc chắn tin rằng con gái của ông không phải là kẻ giết người và huy động tất cả các nguồn lực của mình để bảo vệ cô ấy. Anh ta phát hiện ra về Stalker của Yuna, Dong-Myung, người biết sự thật về tai nạn, và anh ta thuê Hee-Jung, một luật sư mà Mira tin tưởng như chị gái mình. Làm việc với họ, Tae-san dàn dựng một âm mưu rủi ro để tìm kẻ giết người thực sự của vị hôn phu. Người đàn ông có thế giới sắp thay đổi nó.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Min-sik","avatar":""},{"name":"Park Shin-hye","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Lee Ha-nee","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Jang Won-hyung","avatar":""},{"name":"Ahn Seong-bong","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Anupam Tripathi","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Jin Hyun-kwang","avatar":""},{"name":"Park Ho-san","avatar"