INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-lon-okja', 'Siêu lợn Okja', 'Okja', 'https://phimimg.com/upload/vod/20231112-1/d7c6de96ec90ef119afb2aaa960b447e.jpg', 'https://phimimg.com/upload/vod/20231112-1/c86ca5aa55d48ed1d165fa36893374bd.jpg', '<p>Mija, một cô bé 14 tuổi mồ côi cha mẹ, sống với ông trong vùng quê rừng núi ở Hàn Quốc. Người bạn duy nhất của cô bé là Okja, một con vật tròn ủng nặng tới 6 tấn, là kết quả của quá trình biến đổi gen. &nbsp;Cuộc sống yên bình của Mija bên người bạn khổng lồ không còn nữa, sau khi Okja bất ngờ bị lôi tới New York bởi người của Lucy Mirando (Tilda Swinton), một nữ giám đốc có với những mưu mô nham hiểm.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Tilda Swinton","avatar":""},{"name":"Ahn Seo-hyun","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Lily Collins","avatar":""},{"name":"Steven Yeun","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Devon Bostick","avatar":""},{"name":"Byun Hee-bong","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Daniel Henshall","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Sheena Kamal","avatar":""},{"name":"Michael Mitton","avatar":""},{"name":"Colm Hill","avatar":""},{"name":"Kathryn Kirkpat","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]