INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiec-doc-than-nho-doi', 'Tiệc Độc Thân Nhớ Đời', 'Rough Night', 'https://phimimg.com/upload/vod/20231111-1/375b859ef5b608022923752eb25f66a1.jpg', 'https://phimimg.com/upload/vod/20231111-1/3686d647d56583f3622ce095815f2abb.jpg', '<p>Phim Tiệc Độc Thân Nhớ Đời được coi là phiên bản nữ của siêu phẩm hài The Hangover, Rough Night là câu chuyện về năm cô gái trẻ cùng thuê vũ công thoát y để chơi bời trọn đêm. Đang phấn khích thì “trai nhảy” bỗng nhiên đột tử, báo hại các cô nàng phải khổ sở tìm cách phi tang xác. Vận dụng mọi thủ đoạn có thể nghĩ ra để tạo chứng cứ ngoại phạm giả, các cô gái đem cái xác di chuyển khắp nơi. Thế nhưng, càng sửa lại càng sai, họ phải đương đầu cùng hàng loạt rắc rối.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Jillian Bell","avatar":""},{"name":"Ilana Glazer","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Paul W. Downs","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Enrique Murciano","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Dean Winters","avatar":""},{"name":"Ryan Cooper","avatar":""},{"name":"Colton Haynes","avatar":""},{"name":"Patrick Carlyle","avatar":""},{"name":"Eric André","avatar":""},{"name":"Bo Burnham","avatar":""},{"name":"Hasan Minhaj","avatar":""},{"name":"Laura Grey","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
