INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-gunther', 'Ám Sát Gunther', 'Killing Gunther', 'https://phimimg.com/upload/vod/20231111-1/fd9e1ee90ec4a3cf1a5e6d56dba62368.jpg', 'https://phimimg.com/upload/vod/20231111-1/c1352ea98df70aff5b20844ff0eabae6.jpg', '<p>Phim Ám Sát Gunther - Killing Gunther 2017: kể về một nhóm sát nhân lập dị đang chán ngấy với Gunther, kẻ sát nhân vĩ đại nhất thế giới, và quyết định giết ông, nhưng kế hoạch của họ đã biến thành một loạt các cuộc đụng độ vớ vẩn bởi Gunther dường như luôn đi trước một bước.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Taran Killam","avatar":""},{"name":"Dave ''Squatch'' Ward","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Hannah Simone","avatar":""},{"name":"Marc-Anthony Massiah","avatar":""},{"name":"Sylvesta Stuart","avatar":""},{"name":"Reese Alexander","avatar":""},{"name":"J.C. Williams","avatar":""},{"name":"Eric Mazimpaka","avatar":""},{"name":"Amitai Marmorstein","avatar":""},{"name":"Chad Sayn","avatar":""},{"name":"Tawny West","avatar":""},{"name":"Peter Kelamis","avatar":""},{"name":"Paul Britta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
