INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jumanji-tro-choi-ky-ao', 'Jumanji: Trò Chơi Kỳ Ảo', 'Jumanji: Welcome to the Jungle', 'https://phimimg.com/upload/vod/20231111-1/6f8de94d105b8943fe15e4ad2eaedcf5.jpg', 'https://phimimg.com/upload/vod/20231111-1/3a7d2d4467fd074d6d49e037f9b9cdab.jpg', '<p>Jumanji - Trò Chơi Kỳ Ảo là phần tiếp theo của bộ phim viễn tưởng hành động kinh điển Jumanji (1995). Một nhóm 4 học sinh phổ thông bị phạt dọn dẹp tầng hầm trường học. Tại đó, họ phát hiện ra một trò chơi điện tử mang tên Jumanji. Cả 4 tiến hành chọn nhân vật nhập vai và bắt đầu chơi, nhưng nào ngờ họ bị cuốn vào thế giới bên trong game và sống với ngoại hình, đặc tính nhân vật đã chỉnh trước đó. Họ buộc phải tham gia vào những chuyến phiêu nguy hiểm nhưng vô cùng thú vị và ẩn chứa nhiều bất ngờ. Khác với phần phim năm 1995, trò chơi lần này không được giải phóng ra thế giới bên ngoài mà người sẽ bị hút vào trong game. Liệu họ sẽ phải làm gì để trở về với thực tại? Với một dàn diễn viên đình đám như Dwayne Johnson (nghệ danh The Rock), Karen Gillan, danh hài Jack Black, nghệ sĩ hài có cát-sê cao nhất thế giới Kevin Hart, phim hứa hẹn sẽ đưa khán giả vào một thế giới kỳ ảo đầy mê hoặc, với những pha hành động nghẹt thở xen lẫn các tình tiết dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Nick Jonas","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Ser''Darius Blain","avatar":""},{"name":"Madison Iseman","avatar":""},{"name":"Morgan Turner","avatar":""},{"name":"Sean Buxton","avatar":""},{"name":"Mason Guccione","avatar":""},{"name":"Marin Hinkle","avatar":""},{"name":"Tracey Bonner","avatar":""},{"name":"Najah Jackson","avatar":""},{"name":"Natasha Charles Parke","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324407);
