INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-ma-2017', 'Cô Dâu Ma', 'The Bride - Nevesta', 'https://phimimg.com/upload/vod/20231113-1/a072a46607307138e29bab81e9867927.jpg', 'https://phimimg.com/upload/vod/20231113-1/aa5d246fbc46cd86b3088ba0d2de5a47.jpg', '<p>Phim Cô Dâu Ma - The Bride - Nevesta 2017: Lấy cảm hứng từ một số tập tục kỳ lạ tại nước Nga vào thế kỷ XIX, bộ phim &#39;The Bride&#39; gây ám ảnh với khán giả bởi những bi kịch đau thương của các cô dâu xấu số. Cách đây hơn 100 năm, việc chụp ảnh chân dung vốn là điều xa xỉ chỉ dành cho người quá cố, với mục đích là để người thân có thể lưu giữ kỷ niệm với kẻ đã bước sang thế giới bên kia.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Victoria Agalakova","avatar":""},{"name":"Vyacheslav Chepurchenko","avatar":""},{"name":"Alexandra Rebenok","avatar":""},{"name":"Igor Khripunov","avatar":""},{"name":"Dmitry Kulichkov","avatar":""},{"name":"Miroslava Karpovich","avatar":""},{"name":"Natalya Grinshpun","avatar":""},{"name":"Victor Solovyev","avatar":""},{"name":"Marina Alhamdan","avatar":""},{"name":"Evgeny Koryakovsky","avatar":""},{"name":"Valeriya Dmitrieva","avatar":""},{"name":"Lada Churovskaya","avatar":""},{"name":"Vladimir Seleznyov","avatar":""},{"name":"Vera","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
