INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-lo-am-duong', 'Giao Lộ Âm Dương', 'Always Be With You', 'https://phimimg.com/upload/vod/20231113-1/36d0fead525cedad63899228306a7a46.jpg', 'https://phimimg.com/upload/vod/20231113-1/922e93a8fa993aa520b1f5c4393f6b10.jpg', '<p>Phim Giao Lộ Âm Dương - Always Be With You 2017: kể về chuỗi tai nạn liên hoàn xảy ra tại giao lộ: va quẹt xe do say xỉn, nhảy lầu tự tử vì bị phụ tình, và cuối cùng là vụ tông xe tải kinh hoàng. Các nạn nhân tưởng chừng không liên quan đến nhau nhưng sau đó đều liên tiếp gặp phải những hiện tượng kỳ lạ. Điều gì đã xảy ra? Liệu họ có thể thoát khởi vòng xoáy ma quái được khởi nguồn từ giao lộ đêm ấy? Mỗi người đều có ngày định mệnh. Và giao lộ nào cũng có những linh hồn.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Julian Cheung","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Charmaine Sheh","avatar":""},{"name":"Lam Ka-tung","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Ava Yu Kiu","avatar":""},{"name":"Phat Chan Fei","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Emily Kwan Bo-Wai","avatar":""},{"name":"Cheung Tat-Ming","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324407);
