INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-he-sao-hoa', 'Thế hệ sao Hỏa', 'The Mars Generation', 'https://phimimg.com/upload/vod/20231113-1/e521403c38155a2d1e7eb7ca66ad62ac.jpg', 'https://phimimg.com/upload/vod/20231113-1/e1616430a7f3f3a11c39f40b32e189b0.jpg', '<p>Các &quot;mọt sách không gian&quot; tự xưng ở Trại không gian theo đuổi giấc mơ du hành tới sao Hỏa, trong khi các chuyên gia suy ngẫm về lịch sử và tương lai của NASA.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Nye","avatar":""},{"name":"Jeffrey Kluger","avatar":""},{"name":"Neil deGrasse Tyson","avatar":""},{"name":"Michio Kaku","avatar":""},{"name":"Bobak Ferdowsi","avatar":""},{"name":"Andy Weir","avatar":""},{"name":"Tim Urban","avatar":""},{"name":"Elon Musk","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324407);
