INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-dua-quyen-nang', 'Chiếc Đũa Quyền Năng', 'Bright', 'https://phimimg.com/upload/vod/20231113-1/22507940e18f507583e0733842e788c0.jpg', 'https://phimimg.com/upload/vod/20231113-1/fb6550b3ccdf27ea354fb9cfc8feed6d.jpg', '<p>Bright là một bộ phim khoa học viễn tưởng xen lẫn tội phạm, hình sự sắp ra mắt trong năm nay. Với kinh phí 90 triệu đô la, đây là tác phẩm có đầu tư cao nhất của Netflix. Bright đánh dấu sự tái hợp của David Ayer và &quot;Deadshot&quot; Will Smith sau thành công của Suicide Squad hồi năm ngoái. Ngoài ra, bộ phim còn có sự tham gia của Joel Edgerton, Noomi Rapace, Édgar Ramirez...</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Joel Edgerton","avatar":""},{"name":"Lucy Fry","avatar":""},{"name":"Noomi Rapace","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Ike Barinholtz","avatar":""},{"name":"Veronica Ngo","avatar":""},{"name":"Alex Meraz","avatar":""},{"name":"Happy Anderson","avatar":""},{"name":"Dawn Olivieri","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Margaret Cho","avatar":""},{"name":"Joseph Piccuirro","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Enrique Murciano","avatar":""},{"name":"Scarlet Spencer","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
