INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('17-u-sau', '17 U Sầu', 'Growing Pains', 'https://phimimg.com/upload/vod/20231111-1/124cd4664afc34d70fbc671b021c330c.jpg', 'https://phimimg.com/upload/vod/20231111-1/1f3e577dd90f65eac299ce0aff6cac34.jpg', '<p>Phim xoay quanh tuổi 17 biết đau của cô nữ sinh Hạ Viễn Viễn đam mê truyện tranh và fan cuồng của Vương Lực Hoành. Trong mắt thầy cô và bạn bè, Viễn Viễn là một học sinh cá biệt lười biếng và hư hỏng. Thế nhưng, ít ai biết được nguyên do vì sao và càng không biết cô bé mắc chứng mất đi cảm giác đau.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Jiao","avatar":""},{"name":"Hu Xia","avatar":""},{"name":"Lenox Lu","avatar":""},{"name":"Leehom Wang","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Gigi Lau","avatar":""},{"name":"Ju Hao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
