INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-vat', 'Tội Vặt', 'Small Crimes', 'https://phimimg.com/upload/vod/20231111-1/84ed9a3c79d7683a52c89dc1ad27908a.jpg', 'https://phimimg.com/upload/vod/20231111-1/a3952d1bb6bc77c6b9c550bd0cefebe7.jpg', '<p>Sau khi mãn hạn 6 năm tù, cựu cảnh sát cố gắng làm lại từ đầu ở quê nhà nhưng lại mắc kẹt với những hậu quả đến từ quá khứ của chính mình.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Molly Parker","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Macon Blair","avatar":""},{"name":"Michael Kinney","avatar":""},{"name":"Daniela Sandiford","avatar":""},{"name":"Shawn Lawrence","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Eddie Holland","avatar":""},{"name":"Jasson Finney","avatar":""},{"name":"Anatoly Zinoviev","avatar":""},{"name":"Glen Bowser","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Tara Yelland","avatar":""},{"name":"Derek Barn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
