INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-song-sinh', 'Cặp Song Sinh', 'Judwaa 2', 'https://phimimg.com/upload/vod/20231111-1/18be9da85640c146666cd965c65835d3.jpg', 'https://phimimg.com/upload/vod/20231111-1/ed298692bfb1097809c658d3c63a1fad.jpg', '<p>Bà Malhotra sinh hạ một cặp song sinh tại bệnh viện Mumbai, trên đường đến thăm vợ, ông Malhotra vô tình dính vào một vụ buôn lậu kim cương của Charles - Ông trùm thế giới ngầm. Để trả thù, Charles đã bắt đi một đứa con của ông Malhotra. Cặp song sinh dính liền với sự kết nối kỳ diệu về mặt phản xạ sẽ đoàn tụ thế nào? Họ cùng nhau chống lại thế lực ngầm ra sao? Mời các bạn theo dõi bộ phim &quot;Song sinh 2&quot;</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Varun Dhawan","avatar":""},{"name":"Jacqueline Fernandez","avatar":""},{"name":"Taapsee Pannu","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Upasna Singh","avatar":""},{"name":"Rajpal Yadav","avatar":""},{"name":"Pavan Malhotra","avatar":""},{"name":"Ali Asgar","avatar":""},{"name":"Vivan Bhatena","avatar":""},{"name":"Vikas Verma","avatar":""},{"name":"Manoj Pahwa","avatar":""},{"name":"Zakir Hussain","avatar":""},{"name":"Manoj Joshi","avatar":""},{"name":"Johnny Lever","avatar":""},{"name":"Rajat Rawail","avatar":""},{"name":"Salman Khan","avatar":""},{"name":"Hiten Patel","avatar":""},{"name":"Jip Panosot","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
