INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-dia-nguc', 'Cổng Địa Ngục', 'Devil''s Gate', 'https://phimimg.com/upload/vod/20231110-1/c101a7b58edde7bd1fd6472c19fcef61.jpg', 'https://phimimg.com/upload/vod/20231110-1/c27823ac5b16116fe7903d46f7df624c.jpg', '<p>Bộ phim mở đầu với một đặc vụ đặc biệt của FBI Daria Francis (Amanda Schull) cảm thấy vô cùng day dứt hối hận khi khổng thể cứu một nạn nhân vô tội trong một vụ điều tra. Nhưng thời gian không cho phép cô đắm mình trong cảm giác luyến tiếc quá sâu. Cô đã được giao một nhiệm vụ mới tại một thị trấn nhỏ mang tên Cổng Địa Ngục, phía Bắc Dakota.Trong vụ này, một người phụ nữ địa phương và đứa con trai nhỏ của cô đã mất tích, và tất cả các dấu hiệu đều cho thấy đây đều là do sự sắp đặt của chồng cô ta (Milo Ventimiglia). Nhưng khi đặc vụ Francis và cảnh sát địa phương (Shawn Ashmore) vào tầng hầm trang trại của gia đình này, vụ án chứng minh bản thân nó chứa nhiều những hàm ý sâu xa hơn họ có thể tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Milo Ventimiglia","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Javier Botet","avatar":""},{"name":"Amanda Schull","avatar":""},{"name":"Bridget Regan","avatar":""},{"name":"Jonathan Frakes","avatar":""},{"name":"Sarah Constible","avatar":""},{"name":"Jan Skene","avatar":""},{"name":"Spencer Drever","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Beverly Ndukwu","avatar":""},{"name":"Will Woytowich","avatar":""},{"name":"Muriel Hogue","avatar":""},{"name":"Jeff Strome","avatar":""},{"name":"Marilyn Norry","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324407);
