INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-thep', 'Cơn Mưa Thép', 'Steel Rain', 'https://phimimg.com/upload/vod/20231110-1/57dfd97c117522d6dd4609924e11a776.jpg', 'https://phimimg.com/upload/vod/20231110-1/ea487a1f3dcc93750b227391728b006b.jpg', '<p>Giữa một cuộc đảo chính, một đặc vụ Bắc Hàn trốn thoát về phía nam cùng với một vị nguyên thủ đang bị thương để giữ tính mạng cho ông và ngăn chặn chiến tranh Triều Tiên.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Kim Myung-gon","avatar":""},{"name":"Park Eun-hye","avatar":""},{"name":"Kim Ji-ho","avatar":""},{"name":"Ahn Mi-na","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Park Sun-young","avatar":""},{"name":"Go Na-Hee","avatar":""},{"name":"Jung Won-joong","avatar":""},{"name":"Lee Jae-yong","avatar":""},{"name":"Lee Chae-eun","avatar":""},{"name":"Ahn Hyun-ho","avatar":""},{"name":"Kim Han-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
