INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-cut-bat', 'Trò Chơi Cút Bắt', 'The Hunting', 'https://phimimg.com/upload/vod/20231110-1/e2bb1c11df6026c2637523a459f0acfc.jpg', 'https://phimimg.com/upload/vod/20231110-1/41d8dc86150e9b5256319b9731d07368.jpg', '<p>Một nhóm thợ săn tìm kiếm thủ lĩnh mất tích của họ, người đã biến mất trong khi theo dõi một sinh vật huyền thoại trên một hòn đảo bí ẩn. Các thợ săn phải vượt qua địa hình gồ ghề và những trở ngại bất ngờ khi họ cố gắng làm nhiệm vụ giải cứu của họ. Khi cuộc hành trình trở nên nguy hiểm, các thợ săn thấy mình trở thành con mồi của một lực lượng vô hình.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nate Alger","avatar":""},{"name":"Jared Patrick Burkett","avatar":""},{"name":"Bill Collins","avatar":""},{"name":"Lisa Collins","avatar":""},{"name":"Colleen De Silva","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
