INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-stalin', 'Cái Chết Của Stalin', 'The Death of Stalin', 'https://phimimg.com/upload/vod/20231110-1/d17ae344ebca7f3d49f319cea644865b.jpg', 'https://phimimg.com/upload/vod/20231110-1/46558d6e55922c9513bcd466158c1d39.jpg', '<p>Khi nhà độc tài Joseph Stalin qua đời, những người bạn thân ký sinh của ông ta lao vào một cuộc tranh giành quyền lực điên cuồng để trở thành nhà lãnh đạo tiếp theo của Liên Xô. Khi họ vấp ngã, ẩu đả và đâm sau lưng để vươn lên dẫn đầu, câu hỏi vẫn còn đó - ai đang điều hành chính phủ?</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Steve Buscemi","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Michael Palin","avatar":""},{"name":"Paul Chahidi","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Paul Whitehouse","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Adrian McLoughlin","avatar":""},{"name":"Tom Brooke","avatar":""},{"name":"Sylvestra Le Touzel","avatar":""},{"name":"Justin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324407);
