INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bom-xit', 'Bom xịt', 'Bomb Scared', 'https://phimimg.com/upload/vod/20231120-1/6325927184b3c36c4436b459ff89945e.jpg', 'https://phimimg.com/upload/vod/20231120-1/0cdb97b09fadc05f8cead0076aa36cc7.jpg', '<p>Trong lúc Tây Ban Nha sắp sửa giành chức vô địch World Cup thì đâu đó tại Basque, băng khủng bố ngược đời đang mòn mỏi chờ đợi nhiệm vụ mới.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Javier Cámara","avatar":""},{"name":"Gorka Otxoa","avatar":""},{"name":"Miren Ibarguren","avatar":""},{"name":"Julián López","avatar":""},{"name":"Ramón Barea","avatar":""},{"name":"Luis Bermejo","avatar":""},{"name":"Josean Bengoetxea","avatar":""},{"name":"Ane Gabarain","avatar":""},{"name":"Tina Sainz","avatar":""},{"name":"Bárbara Santa-Cruz","avatar":""},{"name":"Farah Hamed","avatar":""},{"name":"Abdelatif Hwidar","avatar":""},{"name":"Daniel Albaladejo","avatar":""},{"name":"Mon Ceballos","avatar":""},{"name":"Nacho Marraco","avatar":""},{"name":"Javi Coll","avatar":""},{"name":"Rodrigo San Pe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
