INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-dieu-ky-2017', 'Giáng Sinh Diệu Kỳ', 'Her Magical Christmas', 'https://phimimg.com/upload/vod/20231120-1/d872521abe265e11d5e6c825ddfeb260.jpg', 'https://phimimg.com/upload/vod/20231120-1/f518d6a47076d7c6b62089c4e7f1bd79.jpg', '<p>Marie Kendrick từng là Queen Nữ hoàng Giáng sinh, cho đến khi cô tan vỡ trái tim bởi mối tình đầu của mình vào Giáng sinh. Marie ngừng tin vào Giáng sinh. Để giúp Marie, gia đình cô quyết định tặng cô một hộp đồ trang trí Giáng sinh để nâng đỡ tinh thần. Giống như phép thuật, những điều tuyệt vời bắt đầu xảy ra. Nhưng ngay khi Marie bắt đầu cảm thấy hạnh phúc, bạn trai cũ Clark xuất bản một cuốn sách nói về mối quan hệ thất bại của họ. Liệu các đồ trang trí có giúp tinh thần của Marie trong Giáng sinh trở nên hạnh phúc thêm một lần nữa?</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Lowndes","avatar":""},{"name":"Brendan Penny","avatar":""},{"name":"Tim Matheson","avatar":""},{"name":"Farah Merani","avatar":""},{"name":"Stephen Huszar","avatar":""},{"name":"Judah Katz","avatar":""},{"name":"Lindsay Leese","avatar":""},{"name":"Anthony Ulc","avatar":""},{"name":"Kristen Kurnik","avatar":""},{"name":"Hattie Kragten","avatar":""},{"name":"Julianne Arrieta","avatar":""},{"name":"Lukas Engel","avatar":""},{"name":"Darrell Faria","avatar":""},{"name":"Cherisse Woonsam","avatar":""},{"name":"Richard Waugh","avatar":""},{"name":"Neil Whitely","avatar":""},{"name":"Pierre Simpson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
