INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giang-sinh-dieu-ky-2017', 'Giáng Sinh Diệu Kỳ', 'Her Magical Christmas', 'giáng sinh diệu kỳ her magical christmas jessica lowndes brendan penny tim matheson farah merani stephen huszar judah katz lindsay leese anthony ulc kristen kurnik hattie kragten julianne arrieta lukas engel darrell faria cherisse woonsam richard waugh neil whitely pierre simpson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mary-va-doa-hoa-phu-thuy', 'Mary và Đóa Hoa Phù Thuỷ', 'Mary and the Witch''s Flower', 'https://phimimg.com/upload/vod/20231109-1/618f6e261589d05ebd17fb6c98d6a3bd.jpg', 'https://phimimg.com/upload/vod/20231109-1/56137955c075a78947d7edbf27f48a68.jpg', '<p>Nội dung chính của bộ phim Mary và đóa hoa phù thủy là câu chuyện xoay quanh Mary cùng với thế giới phép thuật mà cô bé vô tình khám phá ra. Mọi chuyện bắt đầu khi chú mèo đen Tib dẫn Mary đi sâu vào trong khu rừng nơi có một loài hoa kỳ lạ. Bông hoa được Mary cầm trên tay bỗng nhiên xuất hiện một luồng sáng rực rỡ và xuất hiện một chiếc chối thần kỳ, đưa Mary đến với thế giới phù thủy đầy phép thuật. &nbsp;Tại trường Endor, Mary đã được học khá nhiều phép thuật và gặp gỡ một trong những thầy phù thủy có trình độ cao nhất. Cô bé cũng phát hiện ra nơi này có vô số động vật đột biến bị nhốt trong lồng. Sau đó chú mèo đen Tib bị bắt và Mary buộc phải quay lại nơi này để tìm cách cứu Tib, đồng thời giải phóng cho những con vật đang bị nhốt trong lồng. Thật không may, cuộc giải cứu của Mary bị giáo sư Dee và hiệu trưởng Mumblechook phát giác, cô bé buộc phải tìm cách trốn chạy để bảo vệ mình và giải cứu những người bạn của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuki Amami","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Hana Sugisaki","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Jiro Sato","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Eri Watanabe","avatar":""},{"name":"Shinobu Otake","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Lynn","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3