INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mary-va-doa-hoa-phu-thuy', 'Mary và Đóa Hoa Phù Thuỷ', 'Mary and the Witch''s Flower', 'mary và đóa hoa phù thuỷ mary and the witch''s flower yuki amami ryunosuke kamiki hana sugisaki fumiyo kohinata hikari mitsushima jiro sato kenichi endo eri watanabe shinobu otake ikue otani lynn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-giac-mo', 'Giải Mã Giấc Mơ', 'Ancien And The Magic Tablet', 'https://phimimg.com/upload/vod/20231109-1/8c81618417428eb412a5eac0ce665b9b.jpg', 'https://phimimg.com/upload/vod/20231109-1/fe1e06ee6aae8fd063733d548305cf9c.jpg', '<p>Phim Giải Mã Giấc Mơ - Ancien And The Magic Tablet 2017: Xoay quanh cuộc sống của Kokone - một nữ sinh trung học đang trong giai đoạn sắp bước vào kì thi đại học – liên tục gặp phải những giấc mơ kỳ lạ trong lúc ngủ. Đó là những giấc mơ khác thường về các cỗ máy như đang cố tiết lộ cho cô về bí mật gia đình. Vào một ngày, Kokone đã bước vào cuộc phiêu lưu kì ảo khi người cha lập dị của cô bị cảnh sát bắt tới Tokyo để thẩm tra. Từ đó, bằng niềm tin mãnh liệt vào tình cảm gia đình, Kokone đã quyết tâm dấn thân vào những thử thách bất ngờ để tìm đường tới Tokyo đòi lại sự tự do cho cha cũng như giải mã những giấc mơ bí ẩn đã liên tục bủa vây cô bấy lâu.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mitsuki Takahata","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Tomoya Maeno","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Hideki Takahashi","avatar":""},{"name":"Arata Furuta","avatar":""},{"name":"Risa Shimizu","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":