INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngao-kieu-va-dinh-kien', 'Ngạo Kiều và Định Kiến', 'Mr. Pride VS Miss. Prejudice', 'https://phimimg.com/upload/vod/20231109-1/220a945db65d3ea8586b1034d68b20a0.jpg', 'https://phimimg.com/upload/vod/20231109-1/690c0b3cda1b89d914323c0105c70700.jpg', '<p>Phim Kiêu Ngạo và Định Kiến được chuyển thể từ quyển tiểu thuyết cùng tên của tác giả Mị Mị Miêu, xoay quanh mối tình của nữ tác giả online Đường Nam Nam (Địch Lệ Nhiệt Ba) và anh chàng nhà giàu Chu Hầu (Trương Vân Long). Cô vô tình phá hủy buổi lễ cầu hôn của Chu Hầu, sau đó giữa hai người lại xảy ra một loạt những chuyện hài hước. Trong lúc không để ý, cả hai đã nảy sinh tình cảm với nhau. Tuy nhiên, khi phải lựa chọn giữa sự nghiệp và tình yêu, cả hai sẽ quyết định từ bỏ cái nào và nắm giữ cái nào?</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dilraba Dilmurat","avatar":""},{"name":"Leon Zhang","avatar":""},{"name":"Vengo Gao","avatar":""},{"name":"Jin Chen","avatar":""},{"name":"Mike Angelo","avatar":""},{"name":"Kathy Chow","avatar":""},{"name":"Wang Xiao","avatar":""},{"name":"Liu Wenhuan","avatar":""},{"name":"Golf Pichaya Nitipaisankul","avatar":""},{"name":"Fan Tiantian","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Wen Mengyang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
