INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-bo-nhu-thay-ao', 'Thay Bồ Như Thay Áo', 'A Man For Every Month', 'https://phimimg.com/upload/vod/20231109-1/d673cd0e2dbab3e4239e11d9b28e8ccc.jpg', 'https://phimimg.com/upload/vod/20231109-1/76e949d46e245fd79111df44d72b1157.jpg', '<p>Blogger Megan có xu hướng ngại hẹn hò, nhưng tất cả đều thay đổi khi sếp của cô giao cho cô làm vlog hàng ngày về các buổi hẹn hò của cô. Bị đẩy khỏi vùng an toàn của mình, Megan phải nhanh chóng học được các quy tắc vàng của hẹn hò.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carlson Young","avatar":""},{"name":"Aaron Jakubenko","avatar":""},{"name":"Jolene Blalock","avatar":""},{"name":"Bradley Dodds","avatar":""},{"name":"Cole Gerdes","avatar":""},{"name":"Justene Alpert","avatar":""},{"name":"Najee De-Tiege","avatar":""},{"name":"Steven Good","avatar":""},{"name":"Ashli Haynes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324407);
