INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khong-gian', 'Cuộc Chiến Không Gian', 'The Spacewalker - The Age of Pioneers', 'https://phimimg.com/upload/vod/20231109-1/28a71386251643a85a91950c3fb01328.jpg', 'https://phimimg.com/upload/vod/20231109-1/d6bd2f5d1a9ef8a3fd3bec922153543c.jpg', '<p>Tháng 3 năm 1965, trong Chiến tranh Lạnh và cuộc chạy đua vũ trụ giữa Liên Xô cũ và Hoa Kỳ. Người Nga dự định đưa một phi công vào không gian. Phi công quân sự Pavel Belyayev và Alexey Leonov đã sẵn sàng bước vào không gian mở. Nhưng trên con đường họ phải đối mặt với nhiều trở ngại và nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 22, 2017, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Evgeny Mironov","avatar":""},{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Vladimir Ilin","avatar":""},{"name":"Anatoliy Kotenyov","avatar":""},{"name":"Aleksandra Ursulyak","avatar":""},{"name":"Elena Panova","avatar":""},{"name":"Aleksandr Ilin","avatar":""},{"name":"Yuriy Itskov","avatar":""},{"name":"Kirill Poluhin","avatar":""},{"name":"Vitaliya Kornienko","avatar":""},{"name":"Saveliy Kudryashov","avatar":""},{"name":"Sergey Cherdantsev","avatar":""},{"name":"Aleksandr Filatov","avatar":""},{"name":"Sergey Galakhov","avatar":""},{"name":"Rusla","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
