INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-khong-gian', 'Cuộc Chiến Không Gian', 'The Spacewalker - The Age of Pioneers', 'cuộc chiến không gian the spacewalker - the age of pioneers evgeny mironov konstantin khabenskiy vladimir ilin anatoliy kotenyov aleksandra ursulyak elena panova aleksandr ilin yuriy itskov kirill poluhin vitaliya kornienko saveliy kudryashov sergey cherdantsev aleksandr filatov sergey galakhov rusla ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frozen-chuyen-phieu-luu-cua-olaf', 'Frozen: Chuyến Phiêu Lưu Của Olaf', 'Olaf''s Frozen Adventure', 'https://phimimg.com/upload/vod/20231109-1/f740c3bdf6c4f4cc0c441e156e62feae.jpg', 'https://phimimg.com/upload/vod/20231109-1/c9a5b32298dec31ece85ff4dd57e46b9.jpg', '<p>Trở lại lần này, Olaf sẽ kết hợp với chú tuần lộc Sven cùng đồng hành trên một chuyến phiêu lưu đầy vui nhộn. Đây là kỳ nghỉ lễ đầu tiên kể từ khi những cánh cửa của vương quốc được mở lại và Anna cùng Elsa dự định tổ chức một lễ ăn mừng lớn cho tất cả thần dân xứ Arendelle. Nhưng khi người dân bất ngờ rời lễ ăn mừng sớm để tham gia vào những kỳ nghỉ truyền thống cùng gia đình, hai chị em chợt nhận ra họ không có những lễ nghi truyền thống riêng cho gia đình của chính mình. Vì vậy, Olaf đã quyết định chu du khắp vương quốc để mang về những truyền thống tốt đẹp nhất nhằm cứu vãn buổi lễ Giáng sinh đầu tiên này cho những người bạn thân yêu.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Gad","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Idina Menzel","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Eva Bella","avatar":""},{"name":"Chris Williams","avatar":""},{"name":"John de Lancie","avatar":""},{"name":"Lauri Fraser","avatar":""},{"name":"Stevie Wermers-Skelton","avatar":""},{"name":"Benjamin Deters","avatar":""},{"name":"Kate Anderson","avatar":""},{"name":"Elyssa Samsel","avatar":""},{"name":"Kevin Deters","avatar":""},{"name":"Jaspar Randall","avatar":""},{"name":"Evan Agos","avatar":""},{"name":"Stephen J. Anderson","avatar":""},{"name":"Abraham Ben","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324407);
