INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hop-dong-tinh-yeu', 'Hợp Đồng Tình Yêu', 'Love Contractually', 'https://phimimg.com/upload/vod/20231109-1/c067b62c547e3267555273a6ed19ddc4.jpg', 'https://phimimg.com/upload/vod/20231109-1/e81daf49354895faa20a48ef12140361.jpg', '<p>Buồn vị bị phụ tình, nữ tổng tài &quot;lắm tài nhiều tật&quot; Diệp Cần nhận ra con cái mới mang lại hạnh phúc nên quyết định mở buổi tuyển trợ lý với mục đích nhắm chọn ra người có thể cho cô tinh trùng. Anh chàng Tiêu Bác vô tình được để ý đến, mặc cho có đôi lần mâu thuẫn, nhưng nhờ có hợp đồng mà anh ta không thể thoát khỏi tay cô. &nbsp;Phim có nhiều tình tiết tương đồng với phim Việt Nam &quot;Gái Già Lắm Chiêu&quot;</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Joseph Chang","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Joyce Feng","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"QiaoQiao Jin","avatar":""},{"name":"Raquel Xu","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Xian Zi","avatar":""},{"name":"Wang Bowen","avatar":""},{"name":"Mei Han","avatar":""},{"name":"Xu Huangli","avatar":""},{"name":"Liu Wei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
