INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-tiec-mau', 'Dạ Tiệc Máu', 'Eat Locals', 'https://phimimg.com/upload/vod/20231110-1/89eff1a9b9a1f235ff8c1fb54a64f0db.jpg', 'https://phimimg.com/upload/vod/20231110-1/6a67e6bd46392862aeb12dc8b49f3f7a.jpg', '<p>Phim Dạ Tiệc Máu - Eat Locals 2017: Cậu bé Sebastian chắc chắn sẽ có một đêm đáng nhớ khi vô tình tham dự buổi dạ tiệc máu của ma cà rồng - 50 năm mới tổ chức một lần. Chuyện càng thêm dở khóc dở cười khi dạ tiệc trở thành cuộc đối đầu bất đắc dĩ giữa ma cà rồng và biệt đội săn ma.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Charlie Cox","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Freema Agyeman","avatar":""},{"name":"Eve Myles","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Billy Cook","avatar":""},{"name":"Lukaz Leong","avatar":""},{"name":"Nicholas Rowe","avatar":""},{"name":"Dexter Fletcher","avatar":""},{"name":"Ruth Jones","avatar":""},{"name":"Annette Crosbie","avatar":""},{"name":"Jordan Long","avatar":""},{"name":"Tine Stapelfeldt","avatar":""},{"name":"Elly Fairman","avatar":""},{"name":"Johnny Palmiero","avatar":""},{"name":"Robert Portal","avatar":""},{"name":"Adrian","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324407);
