INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-muon-an-tuy-cua-cau', 'Tớ Muốn Ăn Tụy Của Cậu', 'Let Me Eat Your Pancreas', 'https://phimimg.com/upload/vod/20231110-1/879d7111df46411cf3e92832fcb2d9f9.jpg', 'https://phimimg.com/upload/vod/20231110-1/b05f7f6c85f811f0794a8b6bfc4d264b.jpg', '<p>Tôi là một học sinh trung học. Tôi tình cờ tìm thấy một cuốn nhật ký của người bạn cùng lớp Sakura Yamauchi tiết lộ rằng cô ấy đang bị bệnh tuyến tụy. Tôi đã dành thời gian cho Sakura, nhưng cô ấy đã chết. 12 năm sau, theo lời của Sakura, tôi bây giờ là một giáo viên trung học tại cùng trường nơi tôi tốt nghiệp. Trong khi nói chuyện với học sinh của mình, tôi nhớ vài tháng tôi đã ở với Sakura. Trong khi đó, Kyoko, bạn của Sakura, sắp kết hôn. Kyoko cũng nhớ lại những ngày cô ấy ở bên tôi và Sakura.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Minami Hamabe","avatar":""},{"name":"Takumi Kitamura","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Karen Otomo","avatar":""},{"name":"Keiko Kitagawa","avatar":""},{"name":"Yuma Yamoto","avatar":""},{"name":"Dori Sakurada","avatar":""},{"name":"Daichi Morishita","avatar":""},{"name":"Yusuke Kamiji","avatar":""},{"name":"Satomi Nagano","avatar":""},{"name":"Keisuke Nakata","avatar":""},{"name":"Yuriko Hirooka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324407);
