INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tuyen-delta', 'Trận Tuyến Delta', 'Black Site Delta', 'https://phimimg.com/upload/vod/20231110-1/bd46ad3a6e70f62f456ac2c4e6a1246e.jpg', 'https://phimimg.com/upload/vod/20231110-1/5ee8386bc006c64fd1b55f422ff9ab16.jpg', '<p>Phim Trận Tuyến Delta - Black Site Delta 2017: Một nhóm tù nhân trong nhà tù quân đội phải chống trả lại một cuộc tấn công khủng bố. Nhưng điều họ không ngờ đến rằng, mình lại là vỏ bọc của một cơ sở kiểm soát không gian mật.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cam Gigandet","avatar":""},{"name":"Teri Reeves","avatar":""},{"name":"Sherri Eakin","avatar":""},{"name":"Courtney Compton","avatar":""},{"name":"Casey Hendershot","avatar":""},{"name":"Arash Mokhtar","avatar":""},{"name":"Chris Bosarge","avatar":""},{"name":"Michael Dale","avatar":""},{"name":"Jeremy Sande","avatar":""},{"name":"Danny Cosmo","avatar":""},{"name":"Benjamin Charles Watson","avatar":""},{"name":"Michael Randall","avatar":""},{"name":"Curtis Nichouls","avatar":""},{"name":"Dion Mucciacito","avatar":""},{"name":"John Brodsky","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324407);
