INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-du', 'Sóng Dữ', 'Shock Wave', 'https://phimimg.com/upload/vod/20231110-1/22bb785d54e6052bb76e0bb39fdb9654.jpg', 'https://phimimg.com/upload/vod/20231110-1/f84a52391b00ac8f048021d568d1574b.jpg', '<p>Sóng Dữ – Shock Wave là một trong những tác phẩm hiếm hoi của điện ảnh Hong Kong đi sâu khai thai chuyện đời, chuyện nghề của các chiến sĩ cảnh sát làm nhiệm vụ phá gỡ chất nổ, bom mìn. Bộ phim có phần mở đầu khá ấn tượng và kịch tính bằng vụ cướp ngân hàng do băng nhóm do Hồng Kế Bằng thực hiện. Phim kể về Chương Tại Sơn (do Lưu Đức Hoa thủ vai) là một sĩ quan phá gỡ chất nổ, bom mìn trực thuộc Tổng cục Cảnh sát Hong Kong. Anh được phân công làm cảnh sát chìm , thâm nhập vào băng nhóm tội phạm của tên trùm Hồng Kế Bằng (do Khương Vũ thủ vai) – tên tội phạm chuyên gây án bằng các loại chất nổ và có biệt danh “Hỏa bạo”.</p>', 'Full', 1, 'single', 'completed', 9, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Ron Ng","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Wang Ziyi","avatar":""},{"name":"Felix Wong","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Cheung Chun-Kit","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Lee Kwok-Lun","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Peter Chan Bei-Dak","avatar":""},{"name":"Dion Lam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f69