INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-willy-wonka-va-nha-may-socola', 'Tom và Jerry: Willy Wonka và Nhà Máy Sôcôla', 'Tom and Jerry: Willy Wonka and the Chocolate Factory', 'https://phimimg.com/upload/vod/20231109-1/39c13e993050473f16bb84b01b4a48bc.jpg', 'https://phimimg.com/upload/vod/20231109-1/09816b8f1436c16dfdb48d1b0efc4845.jpg', '<p>Một bài hát lại hoạt hình của bộ phim Willy Wonka và Nhà máy sô cô la, trong đó Tom và Jerry giúp Charlie Buck đạt được một vé vàng và bí mật đi cùng anh ta vào nhà máy sô cô la của Willy Wonka để ngăn chặn một trong những đối thủ của Wonka ăn cắp một viên kẹo đặc biệt được gọi là Gobstopper vĩnh cửu, nhưng cũng trải nghiệm thế giới tuyệt vời của nhà máy sô cô la với hướng dẫn của Tuffy, một con chuột Oompa-loompa.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"JP Karliak","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Lincoln Melcher","avatar":""},{"name":"Mick Wingert","avatar":""},{"name":"Lori Alan","avatar":""},{"name":"Jeff Bergman","avatar":""},{"name":"Spike Brandt","avatar":""},{"name":"Rachel Butera","avatar":""},{"name":"Kate Higgins","avatar":""},{"name":"Dallas Lovato","avatar":""},{"name":"Emily O''Brien","avatar":""},{"name":"Sean Schemmel","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Jim Ward","avatar":""},{"name":"Audrey Wasilewski","avatar":""},{"name":"Lauren Weisman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 17846903