INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-lua', 'Dối Lừa', 'Ring of Deception', 'https://phimimg.com/upload/vod/20231109-1/2d7228bf7b0ea62a283b1758ffaf656d.jpg', 'https://phimimg.com/upload/vod/20231109-1/a77eb912da9a4b0d8f20cbec8457dc8f.jpg', '<p>Carmen tạo ra những lời cầu hôn hoàn hảo cho những người đàn ông giàu có. Cho đến khi cô trở thành mục tiêu nỗi ám ảnh của một khách hàng điên rồ, khi cô thể hiện lòng trắc ẩn, sau khi bạn gái của anh ta công khai từ chối anh ta. Cô nhận ra, không phải tất cả các lời cầu hôn đều kết thúc như dự định!</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Chandra West","avatar":""},{"name":"Steve Bacic","avatar":""},{"name":"Cate Sproule","avatar":""},{"name":"Lucie Guest","avatar":""},{"name":"Madison Smith","avatar":""},{"name":"Françoise Yip","avatar":""},{"name":"Jim Shield","avatar":""},{"name":"Robert Moloney","avatar":""},{"name":"Michasha Armstrong","avatar":""},{"name":"Peter Bundic","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324407);
