INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nha-meyerowitz', 'Chuyện Nhà Meyerowitz', 'The Meyerowitz Stories (New and Selected)', 'https://phimimg.com/upload/vod/20231109-1/a8de774405f9b2a31300aabdf3bcc293.jpg', 'https://phimimg.com/upload/vod/20231109-1/1d677339164589a72e9f0dca5714c410.jpg', '<p>Phim xoay quanh chủ đề gia đình Meyerowitz khi ba người con tụ họp lại về dự sự kiện kỷ niệm sự nghiệp nghệ thuật của cha mình. Matthew Meyerowitz là một doanh nhân giàu có và thành đạt sống ở Los Angeles, anh có hai người em cùng cha khác mẹ lần lượt là Danny và Jean, những người sống ở New York cùng với người cha khó tính của họ là Harold Meyerowitz. Gần đây, ông Harold gặp một tai nạn va đập vào đầu, điều này ảnh hưởng không nhỏ đến trí nhớ của ông. Chính vì vậy, những người con của ông gạt hết những công việc cá nhân để lên kế hoạch tổ chức một buổi lễ kỷ niệm trưng bày những tác phẩm nghệ thuật của ông trước khi sức khỏe của Harold xấu đi.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"Grace Van Patten","avatar":""},{"name":"Candice Bergen","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Rebecca Miller","avatar":""},{"name":"Matthew Shear","avatar":""},{"name":"Danny Flaherty","avatar":""},{"name":"Adam David Thompson","avatar":""},{"name":"Ronald Peet","avatar":""},{"name":"Hannah Mitchell","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Dav","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug"