INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('24-gio-hoi-sinh', '24 Giờ Hồi Sinh', '24 Hours To Live', 'https://phimimg.com/upload/vod/20231108-1/6de63ac863692c0a1848b187916b51ce.jpg', 'https://phimimg.com/upload/vod/20231108-1/21af856852ad8ab06ca223dad98b4312.jpg', '<p>Sau một cuộc phẫu thuật thử nghiệm, sát thủ Travis Conrad được hồi sinh từ cõi chết và có đúng 24 giờ để sống lại. Anh quyết định hợp tác với chính nữ đặc vụ đã giết chết mình nhằm trả thù tổ chức tội phạm đã sát hại vợ và con của anh. Đây cũng chính là cơ hội để Travis chuộc lại những lỗi lầm trong quá khứ. Chỉ có 24 giờ để báo thù, liệu Travis có hoàn thành được nhiệm vụ khi từng giây trôi qua, tử thần lại càng đến gần hơn?</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Tyrone Keogh","avatar":""},{"name":"Nathalie Boltt","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Jeremy Yong","avatar":""},{"name":"Susan Young","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""},{"name":"Claire Berlein","avatar":""},{"name":"Richard Lothian","avatar":""},{"name":"Tanya van Graan","avatar":""},{"name":"Alex Anlos","avatar":""},{"name":"Andrew Morgado","avatar":""},{"name":"Jenna Upton","avatar":""},{"name":"Aidan Whytock","avatar":""},{"name":"Bjorn S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an