INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-poker', 'Nữ Hoàng Poker', 'Molly''s Game', 'https://phimimg.com/upload/vod/20231108-1/93708ee66dd9bcb976a9136c25ca17a1.jpg', 'https://phimimg.com/upload/vod/20231108-1/250c299d18a4695f688457d10b69dcc3.jpg', '<p>Phim nói về sự nghiệp của Molly Bloom, người đứng đầu sòng bài Poker cho các diễn viên, tỉ phú, ngôi sao thể thao bên Mỹ, những người vào chơi không phải để kiếm tiền, mà là tìm kiếm sự hào hứng, tìm kiếm cảm giác được sống, được “thoát tục”. Nơi mỗi ván bài giá trị vài trăm nghìn đô đến vài chục triệu đô, người thua thì trong đêm có thể thua đến trăm triệu đô chứ chằng đùa, và họ không chớp mắt khi thua.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Jeremy Strong","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"J. C. MacKenzie","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Justin Kirk","avatar":""},{"name":"Angela Gots","avatar":""},{"name":"Natalie Krill","avatar":""},{"name":"Stephanie Herfield","avatar":""},{"name":"Madison McKinley","avatar":""},{"name":"Joe Keery","avatar":""},{"name":"Mich","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
