INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-nguoi-may', 'Cuộc Chiến Của Người Máy', 'Singularity', 'https://phimimg.com/upload/vod/20231108-1/66cf31117c8de937514d5a3d104127a4.jpg', 'https://phimimg.com/upload/vod/20231108-1/9ca9d2e1990a32c7bf9c4c49ef477971.jpg', '<p>97 năm sau cuộc xâm lăng trị vì của Robot, một nhóm nhỏ người vẫn còn sống nhưng đang chạy trốn khỏi đội quân Người Máy. Andrew (Julian Schaffner) và Calia (Jeannine Wacker), thành lập một liên minh để cùng chiến đấu đến một thế giới mới, nơi người ta đồn đại rằng loài người tồn tại mà không sợ sự đàn áp của người máy. Nhưng liệu thế giới này có thực sự tồn tại? Và liệu họ có sống đủ lâu để tìm hiểu?</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Jeannine Wacker","avatar":""},{"name":"Julian Schaffner","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Carmen Argenziano","avatar":""},{"name":"Eileen Grubba","avatar":""},{"name":"Pavlo Bubryak","avatar":""},{"name":"David Chrisman","avatar":""},{"name":"Jason Marnocha","avatar":""},{"name":"Elaine Loh","avatar":""},{"name":"Ego Nwodim","avatar":""},{"name":"Robert Kouba Senior","avatar":""},{"name":"Robert Kouba","avatar":""},{"name":"Klemens Niklaus Trenkle","avatar":""},{"name":"Paul American","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324407);
