INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-gia-tinh-yeu', 'Sứ Giả Tình Yêu', 'Cupid''s Proxy', 'https://phimimg.com/upload/vod/20231108-1/e27bf8b584fe86da2104ff9bc8fcb9d9.jpg', 'https://phimimg.com/upload/vod/20231108-1/5bf5680d183814ec116ad70fe6fe21d8.jpg', '<p>Điều gì sẽ xảy ra khi một cậu bé 12 tuổi giúp một người viết chuyên mục tư vấn cùng một biên tập viên muốn có một giọng nói mới mẻ trong khi cố gắng giúp đỡ người mẹ không mấy lãng mạn và giáo viên dạy nhạc của mình?</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jet Jurgensmeyer","avatar":""},{"name":"Valerie Azlynn","avatar":""},{"name":"Steve Byrne","avatar":""},{"name":"Jackée Harry","avatar":""},{"name":"Carolyn Dodd","avatar":""},{"name":"Rex Linn","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
