INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-game-thu', 'Liên Minh Game Thủ', 'Family Of Winners', 'https://phimimg.com/upload/vod/20231107-1/378c6197b7df3272bc8d6f2eb6ee15fb.jpg', 'https://phimimg.com/upload/vod/20231107-1/6d90d95bf8e7cb60490e631805ff789f.jpg', '<p>Xoay quanh một nhóm gồm những game thủ chuyên nghiệp lẫn nghiệp dư cùng tập hợp lại để tham gia giải đấu game. . Lần đầu tiên đặt chân tới đấu trường lớn, với kĩ năng và kinh nghiệm chiến đấu trong game siêu đẳng, họ sẽ phải đưa ra chiến thuật thế nào để chiến đấu với các đối thủ đáng gờm.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sookie Pan","avatar":""},{"name":"Wang Yuexin","avatar":""},{"name":"Ji Xiaobing","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Yu Yue","avatar":""},{"name":"Bai Zhijie","avatar":""},{"name":"Xie Ning","avatar":""},{"name":"Zhang Renbo","avatar":""},{"name":"Fang Zige","avatar":""},{"name":"Lu Enjie","avatar":""},{"name":"Li Gaoji","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324407);
