INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kiem-than-vuc-ranh-gioi-hu-ao-ngoai-truyen-2', 'Đao Kiếm Thần Vực: Ranh Giới Hư Ảo (Ngoại Truyện 2)', 'Sword Art Online: Ordinal Scale (Movie 2)', 'https://phimimg.com/upload/vod/20231107-1/7b98f3820b048fcff2123faa70eeac7d.jpg', 'https://phimimg.com/upload/vod/20231107-1/85a9b91a445bad3542ddb11213616a31.jpg', '<p>Vào năm 2026, các Augma được phát hành ra để thay thế hệ thống AmuSphere, với chức năng mô phỏng thực tế trong khi người chơi vẫn còn giữ được ý thức, an toàn hơn so với công nghệ FullDive. trò chơi chiến đấu nổi bật nhất là Ordinal Scale, với một hệ thống xếp hạng khả năng người chơi. &nbsp;Asuna, Lisbeth và Silica đã khuyến khích Kirito chơi OS khi nghe được rằng các boss trong Aincrad sẽ xuất hiện. Kirito tham gia với Asuna và Klein trong một trận đánh boss nơi linh vật của game, ca sĩ thần tượng ảo Yuna, xuất hiện và mang đến cho người chơi những hiệu ứng buff khi cô hát. Kirito đã không thành công trong bất cứ điều gì do thiếu thể lực và tốc độ. Eiji, người chơi xếp hạng nhì, đã giúp nhóm trong quá trình tiêu diệt boss. trước khi Asuna ra đòn quyết định, Eiji thì thầm từ &quot;Switch&quot;, một chiêu thức game từ SAO mà cô đã tinh ý nhận ra.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Kanae Ito","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Ayahi Takagaki","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Sayaka Kanda","avatar":""},{"name":"Yoshio Inoue","avatar":""},{"name":"Takeshi Kaga","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Chiwa Saito","avatar":""},{"name":"Kenichirou Matsuda","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324407);
