INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-de-xac-chet-tan', 'Hãy để xác chết tan', 'Let the Corpses Tan', 'https://phimimg.com/upload/vod/20231107-1/1e1552e04a08bf926502118ed930badf.jpg', 'https://phimimg.com/upload/vod/20231107-1/7b8d9ce1bfa4de0ec4386cc17234b2b8.jpg', '<p>Với một lượng vàng thỏi nặng 250 kg, kẻ chủ mưu tội phạm tóc hoa râm, Rhino, và nhóm sát thủ tàn nhẫn của hắn, tiến đến một nơi ẩn dật xiêu vẹo ở một nơi nào đó ở Địa Trung Hải để ẩn náu trong một ngày tháng Bảy nóng như thiêu đốt. Tuy nhiên, sự xuất hiện bất ngờ và khá không mong muốn của nhà văn phóng túng Bernier, nàng thơ của anh ta, Luce, cùng với một cặp hiến binh không đùa được càng làm phức tạp thêm mọi thứ, vì lòng trung thành yếu ớt sẽ sớm bị thử thách.</p>', 'Full', 1, 'single', 'completed', 21, 2017, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Elina Löwensohn","avatar":""},{"name":"Stéphane Ferrara","avatar":""},{"name":"Bernie Bonvoisin","avatar":""},{"name":"Hervé Sogne","avatar":""},{"name":"Marine Sainsily","avatar":""},{"name":"Marc Barbé","avatar":""},{"name":"Marilyn Jess","avatar":""},{"name":"Michelangelo Marchese","avatar":""},{"name":"Pierre Nisse","avatar":""},{"name":"Aline Stevens","avatar":""},{"name":"Dorylia Calmel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324407);
