INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bong-chuyen-tai-nang-va-cam-giac', 'Thiếu niên bóng chuyền !! Tài năng và cảm giác', 'Haikyuu!! Movie 3: Genius and Sense', 'https://phimimg.com/upload/vod/20231114-1/de7f41f2083b945fce4b7a40e7365ef5.jpg', 'https://phimimg.com/upload/vod/20231114-1/1bb968db16a1c657223a589340ab83aa.jpg', '<p>Một phiên bản điện ảnh tổng biên tập của anime bom tấn &quot;Haikyu!!&quot; dựa trên bộ truyện tranh nổi tiếng lấy chủ đề về các tuyển thủ bóng chuyền trung học của tác giả Furudate Haruichi. Câu lạc bộ bóng chuyền trung học Karasuno sẽ tham gia trại huấn luyện chung với đội mạnh Kanto cho vòng loại trung học mùa xuân. Karasuno tung ra một cuộc tấn công dữ dội ngay từ đầu, nhưng bị đẩy bởi cú giao bóng của Oikawa và bị giữ lại bởi đôi giày đinh, vũ khí bí mật của Kyotani, và thắng lợi dần nghiêng về Aoba Josai ...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazunari Tanaka","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
