INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ordinary-person', 'Ordinary Person', 'Ordinary Person', 'https://phimimg.com/upload/vod/20231114-1/916e2c425d732c8001ba0d72f8e3535f.jpg', 'https://phimimg.com/upload/vod/20231114-1/121e67ce17fafb38a60024d0b56e7547.jpg', '<p>Một sĩ quan cảnh sát không chính đáng với một người vợ và con trai tham gia với một âm mưu sau khi anh ta bắt giữ một kẻ giết người một cách tình cờ. Điểm yếu của anh là con trai của anh ta cần một phẫu thuật để đối xử với đôi chân của mình. Lựa chọn con đường nào? Sự công bình hoặc âm mưu?</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Jang Hyuk","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Ji Seung-hyun","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Choi Youn-so","avatar":""},{"name":"Jong Ho","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Park Kyung-geun","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Jang Yong-chul","avatar":""},{"name":"Jang Yong-bok","avatar":""},{"name":"Kim Song-il","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Choi Seong-min","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324407);
