INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ordinary-person', 'Ordinary Person', 'Ordinary Person', 'ordinary person ordinary person son hyun-joo jang hyuk ra mi-ran jo dal-hwan ji seung-hyun oh yeon-ah park ji-il choi youn-so jong ho kim sang-ho park kyung-geun ju seok-tae jang yong-chul jang yong-bok kim song-il jeong man-sik son byung-ho jang gwang choi seong-min ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-ma-truyen', 'Hàng Ma Truyện', 'The Golden Monk', 'https://phimimg.com/upload/vod/20231114-1/9a32fab041f3114574b2cab590ad5de5.jpg', 'https://phimimg.com/upload/vod/20231114-1/6d23e9ae9e964b33e6e3b28c3afb7e02.jpg', '<p>Bộ phim Hàng Ma Truyện lấy bối cảnh vào thời Nam Tống khi yêu quái hoành hành ở thành Hàng Châu. Hòa thượng Bất Thông (Trịnh Khải) xuống núi nhằm diệt trừ yêu ma, tình cờ gặp gỡ và quen biết với ma sư Thanh Thanh (Trương Vũ Kỳ). Bất Thông và Thanh Thanh kiếp trước là đôi kim đồng ngọc nữ của thiên đình, nhưng do phạm luật trời nên bị đày xuống trần gian chịu cảnh luân hồi chuyển kiếp. Cả hai cùng hợp sức tiêu diệt Thiên Sơn Lão Yêu, trên đường đi gặp được Kiếm Thần Độc Cô Cầu Bại (Tạ Y Lâm). Vì cùng chung chí hướng nên cả ba dễ dàng trở thành bạn. Đúng lúc này, kẻ địch ngàn năm trước của Bất Thông – Độc Long dẫn đầu lũ yêu ma quay trở lại nhân gian. Liệu ba người có ngăn cản được âm mưu và tiêu diệt Độc Long?</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ryan Zheng Kai","avatar":""},{"name":"Kitty Zhang","avatar":""},{"name":"Xie Yi-lin","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Mao Junjie","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Ye Cheng","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Fiona Zhen","avatar":""},{"name":"Monica Chan","avatar":""},{"name":"Zhang Aiqin","avatar":""},{"name":"John Wu","avatar":""},{"name":"Wang Xinyao","avatar":""},{"name":"Dana Meng","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Guo Haolun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324407);
