INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-tro-ve-2017', 'Đường Trở Về', 'Walking Out', 'https://phimimg.com/upload/vod/20231103-1/b748bb57244226e8eb35c8a65b59ca29.jpg', 'https://phimimg.com/upload/vod/20231103-1/6715f8a2f8738478f8ead08d2831f74a.jpg', '<p>Phim Đường Trở Về - Walking Out 2017: David là một thiếu niên thành thị, trở về quê để đi săn với người cha vùng nông thôn Montana của mình, Cal. Khi họ tiến sâu vào vùng hoang dã, 2 cha con đã gặp phải một con gấu khổng lồ tấn công, cả hai bị thương nặng, họ phải tranh đấu để tồn tại dưới thời tiết khắc nghiệt.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Bomer","avatar":""},{"name":"Josh Wiggins","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Alex Neustaedter","avatar":""},{"name":"Lily Gladstone","avatar":""},{"name":"Ken White","avatar":""},{"name":"Scott McMillion","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
