INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amityville-quy-du-thuc-tinh', 'Amityville: Quỷ Dữ Thức Tỉnh', 'Amityville: The Awakening', 'https://phimimg.com/upload/vod/20231103-1/a8249de2fa4506d91afd1dd0d8642ab3.jpg', 'https://phimimg.com/upload/vod/20231103-1/40df6f916726b75b92bee4160f0a5c4d.jpg', '<p>Bella Thorne và Jennifer Jason Leigh là hai ngôi sao tham gia tập thứ 14 của loạt phim kinh dị nổi tiếng Amityville. Chuyện phim bắt đầu khi một cô gái trẻ chuyển tới ngôi nhà mới cùng bà mẹ đơn thân và cậu em trai đang bị hôn mê. Tại đó, người em trai bất ngờ tỉnh lại và hồi phục nhanh chóng. Nhưng hàng loạt hiện tượng kỳ bí cũng bắt đầu xảy đến với gia đình nhỏ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bella Thorne","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Kurtwood Smith","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Taylor Spreitler","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324407);
