INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-john-wick-phan-2', 'Sát Thủ John Wick: Phần 2', 'John Wick: Chapter 2', 'https://phimimg.com/upload/vod/20231107-1/0aa102b2c7bf0fbb5f16911171787bdd.jpg', 'https://phimimg.com/upload/vod/20231107-1/d79a16e31b8eb24cdc71a3dd5ed9e0fe.jpg', '<p>John Wick 1 chính là bước đệm để John Wick: Chương 2 có thể phát triển mạnh. Phần thứ hai vượt qua bản gốc, phần lớn là nhờ ngân sách tăng thêm của nó ở mức 40 triệu đô la. Có thể khán giả rất thích thú khi xem John Wick lần đầu tiên, nhưng việc sản xuất và thực hiện câu chuyện tiếp theo của đơn giản là ấn tượng và đáng nhớ hơn. Công bằng mà nói, John Wick: Chương 2 không cần phải lo lắng nhiều về việc thể hiện nhân vật. Phim khởi động với một cuộc rượt đuổi xe Brooklyn đầy căng thẳn. Và phần 2 sở hữu những khung hình đầy chất “động” hơn. Các câu thoại được trích dẫn nhiều hơn, và các nguyên tắc của thế giới ngầm được nhân đôi. Đây chính là điểm tạo nên một chapter 2 đầy thú vị. Nhìn chung, John Wick: Chương 2 cố gắng nhắc nhở khán giả rằng đây không nhất thiết là một bộ phim về bạo lực hay lòng can trường. Mà là về một người đàn ông tìm kiếm ý nghĩa và bản chất của bản thân.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Common","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Riccardo Scamarcio","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"Franco Nero","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Claudia Gerini","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Luca Mosca","avatar":""},{"name":"Tobias Segal","avatar":""},{"name":"Thomas Sadoski","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
