INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-bay-mat-trang-muc-tieu-trai-dat', 'Cạm Bẫy Mặt Trăng - Mục Tiêu Trái Đất', 'Moontrap: Target Earth', 'https://phimimg.com/upload/vod/20231106-1/90b99740573083b6b33641fc273845d3.jpg', 'https://phimimg.com/upload/vod/20231106-1/f21a48a0a5b65cd5103b81476925e080.jpg', '<p>Một tàu vũ trụ cổ đại bị lãng quên từ lâu được phát hiện trên Trái đất. Các cuộc điều tra do Scout thực hiện đã đưa cô đến mặt trăng, nơi cô gặp những cỗ máy ấn tượng đang bảo tồn trí tuệ của nền văn minh đã mất từ lâu đó.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Butler","avatar":""},{"name":"Damon Dayoub","avatar":""},{"name":"Charles Shaughnessy","avatar":""},{"name":"Cara AnnMarie","avatar":""},{"name":"Loretta Higgins","avatar":""},{"name":"Niki Spiridakos","avatar":""},{"name":"Chris Newman","avatar":""},{"name":"Steven Dutton","avatar":""},{"name":"Jennifer Kincer","avatar":""},{"name":"D.B. Dickerson","avatar":""},{"name":"Tarick Salmaci","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324407);
