INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-cua-dat', 'Luật Của Đất', 'Law Of The Land', 'https://phimimg.com/upload/vod/20231106-1/666c6bd6292e866e4e5034985104c436.jpg', 'https://phimimg.com/upload/vod/20231106-1/efbe8a54f66e840de262ccf818ee88e9.jpg', '<p>Phim Luật Của Đất - Law Of The Land 2017: Tại một ngôi làng nhỏ ở phía Tây Lapland, ngay trước cửa biên giới Thụy Điển. Một viên cảnh sát đã nghỉ hưu, Lasse, nghe được tin tên tội phạm địa phương Jaakko đã được thả ra khỏi nhà tù và gây gổ với con trai của anh - Erkki. Lasse phải đứng ở giữa để ngăn 2 người họ lại. Lasse muốn bảo vệ con trai mình khỏi xích mích với tên tội phạm khét tiếng Thụy Điển Jaakko.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Phần Lan', 0, '[{"name":"Ville Virtanen","avatar":""},{"name":"Antti Holma","avatar":""},{"name":"Mikko Neuvonen","avatar":""},{"name":"Malin Buska","avatar":""},{"name":"Outi Mäenpää","avatar":""},{"name":"Pernilla August","avatar":""},{"name":"Jørgen Langhelle","avatar":""},{"name":"Andreas af Enehielm","avatar":""},{"name":"Erik Smith-Meyer","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324407);
