INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-anh-hung-nhi', 'Đội Anh Hùng Nhí', 'Axel 2: Adventures of the Spacekids', 'https://phimimg.com/upload/vod/20231106-1/cc8c7fe5a464ef8a16772468e569b3b7.jpg', 'https://phimimg.com/upload/vod/20231106-1/93d5a9a2e577362472e15b6b67f3c2c2.jpg', '<p>Một hành tinh xa xôi ngoài vũ trụ đột nhiên bị người Trái Đất xâm chiếm, biến nó từ một nơi đầy những thực vật đa dạng trở nên khô cằn. Không thể đứng nhìn quê hương tiếp tục bị huỷ hoại, một nhóm gồm 3 người bạn đã dũng cảm lên đường tìm kiếm những hạt giống còn sót lại, đối đầu với người Trái Đất để bảo vệ quê hương</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kate Higgins","avatar":""},{"name":"Colleen O''Shaughnessey","avatar":""},{"name":"Alyson Leigh Rosenfeld","avatar":""},{"name":"Tom Wayland","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324407);
