INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-doi-ki-dieu', 'Biến Đổi Kì Diệu', 'Unleashed', 'https://phimimg.com/upload/vod/20231103-1/ab7611c70cf1fff3f21b3780f6784d35.jpg', 'https://phimimg.com/upload/vod/20231103-1/6475dce91ce2ef7f2d9b31b489030094.jpg', '<p>Khi một sự kiện vũ trụ biến con chó và mèo của Emma thành hai người bạn hoàn hảo, Emma xem xét lại quan điểm của mình về hẹn hò, vui vẻ giải quyết các vấn đề tin cậy của cô, và cuối cùng học cách yêu bản thân mình.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Micucci","avatar":""},{"name":"Justin Chatwin","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Hana Mae Lee","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Illeana Douglas","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Mark Strano","avatar":""},{"name":"John Terrell","avatar":""},{"name":"Don Reed","avatar":""},{"name":"Scott Coffey","avatar":""},{"name":"Jeremy Kahn","avatar":""},{"name":"Kathy Garver","avatar":""},{"name":"Joshua Lomeli","avatar":""},{"name":"Samantha Jackson","avatar":""},{"name":"Diana Amos","avatar":""},{"name":"Andrew Laing","avatar":""},{"name":"Gina Beretta","avatar":""},{"name":"Jenni","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324407);
