INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-san-ho', 'Rạn San Hô', 'Chasing Coral', 'https://phimimg.com/upload/vod/20231103-1/6fcd2963fb52bedfa4cb2519ac2d9750.jpg', 'https://phimimg.com/upload/vod/20231103-1/72d6e09d01788ac49bd4b15e5161be10.jpg', '<p>Phim Rạn San Hô - Chasing Coral 2017: Rạn san hô trên khắp thế giới đang biến mất ở một tỷ lệ chưa từng thấy. Một nhóm thợ lặn, nhiếp ảnh gia và các nhà khoa học đã bắt đầu cuộc phiêu lưu thú vị để khám phá lý do tại sao và để lộ bí ẩn dưới nước cho thế giới.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Ackerman","avatar":""},{"name":"Pim Bongaerts","avatar":""},{"name":"Neal Cantin","avatar":""},{"name":"Phil Dustan","avatar":""},{"name":"Ruth Gates","avatar":""},{"name":"Manuel González-Rivero","avatar":""},{"name":"Ove Hoegh-Guldberg","avatar":""},{"name":"Joanie Kleypas","avatar":""},{"name":"Justin Marshall","avatar":""},{"name":"Trevor Mendelow","avatar":""},{"name":"Rupert Ormond","avatar":""},{"name":"James Porter","avatar":""},{"name":"Morgan Pratchett","avatar":""},{"name":"Zackery Rago","avatar":""},{"name":"Luiz A. Rocha","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324407);
