INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngot-dang', 'Ngọt Đắng', 'The Bittersweet', 'https://phimimg.com/upload/vod/20231103-1/edca759a0545b26274f2157c2ebe5ea3.jpg', 'https://phimimg.com/upload/vod/20231103-1/d4c695fb353a2108adee407e3e5bc92f.jpg', '<p>Khi một kẻ giết người rình rập trên đường phố, một người chuyển phát nhanh trẻ tuổi đang gặp rắc rối nghi ngờ rằng bác sĩ có thể là người chị gái thất lạc từ lâu mà anh ta không gặp từ thời thơ ấu.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Zhu Xuan","avatar":""},{"name":"Lee Tae-ri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324407);
