INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-gac-dem', 'Người Gác Đêm', 'Security', 'https://phimimg.com/upload/vod/20231103-1/4baa15a53b5142fa233ecc7243732d9f.jpg', 'https://phimimg.com/upload/vod/20231103-1/d0897e6a29cb8f7b06f4da5c7a2f3242.jpg', '<p>Một cựu chiến binh dịch vụ cũ (Antonio Banderas), về may mắn và tuyệt vọng cho công việc, có một công việc là một nhân viên bảo vệ tại một trung tâm mua sắm trên một khu vực nông thôn. Vào đêm đầu tiên của mình trong công việc, anh ta mở cánh cửa lên đến một cô gái trẻ quẫn trí và tuyệt vọng đã trốn thoát và bỏ trốn khỏi sự chiếm đoạt của một người phát triển của Hoa Kỳ, đã vận chuyển cô ấy để làm chứng như một nhân chứng thử nghiệm. Nóng bỏng trên gót chân của cô là kẻ tấn công tâm lý (Sir Ben Kingsley), cùng với tay sai tháo vát của mình, người sẽ dừng lại không có gì để chiết xuất và loại bỏ nhân chứng của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Liam McIntyre","avatar":""},{"name":"Chad Lindberg","avatar":""},{"name":"Gabriella Wright","avatar":""},{"name":"Cung Le","avatar":""},{"name":"Mark Rhino Smith","avatar":""},{"name":"Bashar Rahal","avatar":""},{"name":"Yana Marinova","avatar":""},{"name":"Jiro Wang","avatar":""},{"name":"Ivailo Dimitrov","avatar":""},{"name":"Velimir Velev","avatar":""},{"name":"Mark Basnight","avatar":""},{"name":"Lillian Blankenship","avatar":""},{"name":"Katherine de la Rocha","avatar":""},{"name":"Shari Watson","avatar":""},{"name":"Anu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324407);
