INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-can-nha-nam-nghe-nang-mua', 'Có Căn Nhà Nằm Nghe Nắng Mưa', 'Like an Old House', 'https://phimimg.com/upload/vod/20231103-1/af9885e958de248c8916e519a7c3e44e.jpg', 'https://phimimg.com/upload/vod/20231103-1/3330004cb58219ea2a277dcc0f942e16.jpg', '<p>Câu chuyện bắt đầu khi chàng nhân viên địa ốc tên Sơn (Dương Cường) đến một khu phố nghèo để thuyết phục người dân bán nhà. Tại đây, bà Tư (Kim Xuân) nhận anh là người con bỏ trốn 30 năm trước vì bị tình nghi giết người. Trở về, Sơn bắt đầu có những giấc mơ kỳ lạ, thấy mình là con bà Tư trong quá khứ. Anh dần hoài nghi thân phận mình, trong lúc thời hạn giải quyết công việc đã gần kề.</p>', 'Full', 1, 'single', 'completed', 22, 2017, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Dương Cường","avatar":""},{"name":"Khắc Minh","avatar":""},{"name":"Kim Xuân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324407);
