INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-phu', 'Sát Phu', 'Husband Killers', 'https://phimimg.com/upload/vod/20231103-1/de0727fcd1be459da6c6ef58489f9853.jpg', 'https://phimimg.com/upload/vod/20231103-1/459e2ec740d004d8b794fce22dc5b300.jpg', '<p>Nội dung của phim Sát Phu xoay quanh một nữ sát thủ xinh đẹp, quyến rũ tên là Chanel (Đặng Lệ Hân), một người có cuộc sống hôn nhân viên mãn trong suốt 10 năm, tuy nhiên mọi thứ bắt đầu sụp đổ khi cô phát hiện ra chồng của mình có bồ, đó là một phụ nữ tên Dior (Châu Tú Na). &nbsp;Thế nhưng, khi mà mọi chuyện chưa được 2 người giải quyết với nhau thì kẻ tình địch sau đó lại phát hiện ra người đàn ông vốn đang “lén lút” trốn vợ cặp kè với cô còn có một cô bồ nhí nữa tên là Hermes (Gaile Lok). Từ đó, cả ba bắt đầu bước vào một cuộc chiến để trả thù, liệu rằng họ sẽ đấu với nhau hay mục tiêu sẽ là người chồng lăng nhăng của Chanel…</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Stephy Tang","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Gaile Lok","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Lai Man-Wang","avatar":""},{"name":"Kevin Li Kin-Wang","avatar":""},{"name":"Eric Kwok Wai-Leung","avatar":""},{"name":"Wong Chi-On","avatar":""},{"name":"Samuel Leung Cheuk-Moon","avatar":""},{"name":"Catherine Chau","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324407);
