INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cua-ban-gai', 'Ngày của bạn gái', 'Girlfriend''s Day', 'https://phimimg.com/upload/vod/20231103-1/f07e153337a5ceff75db89453cf70b98.jpg', 'https://phimimg.com/upload/vod/20231103-1/e1a9ef9895ebfe4575ce79934dc49e7c.jpg', '<p>Bất ngờ vướng vào một âm mưu hiểm ác, anh chàng chuyên viết thiệp bị đuổi việc buộc phải nghĩ ra lời chúc hoàn hảo cho một ngày lễ đặc biệt hòng thoát thân.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Odenkirk","avatar":""},{"name":"Amber Tamblyn","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Alex Karpovsky","avatar":""},{"name":"Kevin O''Grady","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Larry Fessenden","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Stephanie Courtney","avatar":""},{"name":"Echo Kellum","avatar":""},{"name":"Nate Mooney","avatar":""},{"name":"Radek Lord","avatar":""},{"name":"Tucker Smallwood","avatar":""},{"name":"David Sullivan","avatar":""},{"name":"Toby","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
