INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-the-cao-thu', 'Tuyệt Thế Cao Thủ', 'The One', 'https://phimimg.com/upload/vod/20231111-1/4cf7bcc846077e6a000141a5e86fb377.jpg', 'https://phimimg.com/upload/vod/20231111-1/a23b163093565db4211df6527c16be3f.jpg', '<p>Phim bắt đầu từ một ông chủ của chuỗi nhà hàng nổi tiếng trung quốc tên là Thái hắc ám, người đang muốn tên tuổi cũng như thương hiệu của mình bao trùm khắp cả nước, ông muốn trở thành ông trùm của giới ẩm thực. Để thực hiện được mong muốn đó, ông ta đã thuê một cao thủ chuyên đi lừa đảo đã bị tê liệt cảm giác tên là Tiểu Ngư, đi tìm kiếm quyển “Bí Kíp Nấu Ăn Thật Là Ngon”. Tưởng rằng sẽ rất tốn công để tìm thấy nó nhưng thực tế là cậu ta không hề có một chút khó khăn nào, nhanh chóng tìm được bí kíp ở phố Trụy Lạc, nơi các “cao thủ” đang ẩn mình. &nbsp;Không quy tụ dàn sao đình đám, không kinh phí khủng, thế nhưng điểm mạnh của The One 2017 là chất hài mang tới nhiều tiếng cười và niềm vui cho khán giả theo đúng kiểu “mỳ ăn liền”, người xem không cần phải quá tập trung mà vẫn cảm thấy được hiệu quả của phong cách “hài nhảm” đúng kiểu như Châu Tinh Trì từng thực hiện.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lu Zhengyu","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Fan Wei","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Cai Guoqing","avatar":""},{"name":"Kong Lian-Shun","avatar":""},{"name":"Isabelle Huang","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Yang Di","avatar":""},{"name":"Ke Da","avatar":""},{"name":"Allen Ai Lun","avatar":""},{"name":"He Landou","avatar":""},{"name":"Zhao Yingjun","avatar":""},{"name":"Wei Xiang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
