INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-vu-an-jonbenet', 'Bí mật vụ án JonBenet', 'Casting JonBenet', 'https://phimimg.com/upload/vod/20231103-1/ac3ced9111a354363af33350815f5bdf.jpg', 'https://phimimg.com/upload/vod/20231103-1/01e981ce6c98780fe6731791dbf115ec.jpg', '<p>Các diễn viên ở quê nhà của JonBenet Ramsey sẽ thử vào vai người trong cuộc. Mỗi người trong số họ lại có nhận định khác nhau về tấn bi kịch xảy ra với cô bé năm 1996.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Hannah Cagwin","avatar":""},{"name":"Aeona Cruz","avatar":""},{"name":"Liv Bagley","avatar":""},{"name":"Shylee Sagle","avatar":""},{"name":"Danika Toolson","avatar":""},{"name":"Nicole Hamilton","avatar":""},{"name":"Emma Winslow","avatar":""},{"name":"Elle Walker","avatar":""},{"name":"Jerry Cortese","avatar":""},{"name":"Kit Thompson","avatar":""},{"name":"Amy Dowd","avatar":""},{"name":"Teresa Cocas","avatar":""},{"name":"Stephanie Federico","avatar":""},{"name":"Tamara Hutchins","avatar":""},{"name":"Deb Hultgren","avatar":""},{"name":"Ronda Belser","avatar":""},{"name":"Dorinda Dercar","avatar":""},{"name":"Carolyn","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
