INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-bao-thu', 'Luật Báo Thù', 'Acts of Vengeance', 'https://phimimg.com/upload/vod/20231103-1/eed82050a131c0478f56432e8f9e1898.jpg', 'https://phimimg.com/upload/vod/20231103-1/b28526d7bca133b2ee645908b5e57fcc.jpg', '<p>Frank Valera là một luật sư, sống cùng với vợ con, nhưng tiếc là không có nhiều thời gian dành cho họ. Trong buổi trình diễn tài năng của nhà trường tổ chức, con anh đã trông anh đến nhưng anh đã đến muộn khi phần diễn xuất của con gái đã kết thúc. Hối hận, anh về trong một cơn mưa kéo dài và anh nhận được tin của cảnh sát rằng con gái đã bị giết chết. Cảnh sát dường như không tìm thấy bất cứ bằng chứng nào dẫn tới nghi phạm. Điều đó làm cho Frank thêm đau khổ và anh quyết tâm đi tìm thủ phạm để trả thù...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Cristina Serafini","avatar":""},{"name":"Lillian Blankenship","avatar":""},{"name":"Clint Dyer","avatar":""},{"name":"Isaac Florentine","avatar":""},{"name":"Tim Man","avatar":""},{"name":"Johnathon Schaech","avatar":""},{"name":"David Sakurai","avatar":""},{"name":"Mark Rhino Smith","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
