INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-thu-cung-la-khung-long', 'Khi Thú Cưng Là Khủng Long', 'My Pet Dinosaur', 'https://phimimg.com/upload/vod/20231102-1/579c278197fae5bfc0a530dd426dad51.jpg', 'https://phimimg.com/upload/vod/20231102-1/82e552cf188847fb2c2b1894bd61628f.jpg', '<p>Phim Khi Thú Cưng Là Khủng Long - My Pet Dinosaur 2017: Trong một cuộc thử nghiệm sinh học sai lầm, cậu bé Jake vô tình tạo ra những con vật cưng mới của cậu. Đó là những con khủng long nhỏ kỳ lạ, chúng lớn lên từng ngày một cách nhanh chóng khiến cho bí mật của cậu khó lòng được giữ kín. Lúc này một tổ chức bí ẩn bắt đầu truy lùng đám khủng long nhằm thực hiện âm mưu xấu xa. Làm thế nào Jake và nhóm bạn của cậu có thể bảo vệ chúng khỏi mối nguy hại của tổ chức bí ẩn.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jordan Dulieu","avatar":""},{"name":"Joanne Samuel","avatar":""},{"name":"David Roberts","avatar":""},{"name":"Tiriel Mora","avatar":""},{"name":"Sam Winspear-Schillings","avatar":""},{"name":"Annabel Wolf","avatar":""},{"name":"Darius Williams-Watt","avatar":""},{"name":"Beth Champion","avatar":""},{"name":"Tom Rooney","avatar":""},{"name":"Christopher Gabardi","avatar":""},{"name":"Scott Irwin","avatar":""},{"name":"Stephen Davis","avatar":""},{"name":"Meghan Drummond","avatar":""},{"name":"Aaron Bonham","avatar":""},{"name":"Rowland Holmes","avatar":""},{"name":"Harrison Saun","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
