INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-thu-cung-la-khung-long', 'Khi Thú Cưng Là Khủng Long', 'My Pet Dinosaur', 'khi thú cưng là khủng long my pet dinosaur jordan dulieu joanne samuel david roberts tiriel mora sam winspear-schillings annabel wolf darius williams-watt beth champion tom rooney christopher gabardi scott irwin stephen davis meghan drummond aaron bonham rowland holmes harrison saun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-yeu-bach-ngu-tran', 'Phục yêu. Bạch ngư trấn', 'White Fish Town', 'https://phimimg.com/upload/vod/20231110-1/751c1506d08b40f6aebcacfe5e3ad8a1.jpg', 'https://phimimg.com/upload/vod/20231110-1/87ed8b86862999ba07912a973997f03d.jpg', '<p>Lai Xiaohua, con trai họ Lai và Zhang Huihui, con trai họ Zhang, đã chiến đấu chống lại những người khác và giành được tấm bảng danh hiệu &quot;Vua tranh luận&quot; vì tính cách ghen tị của Zhang Huihui. Không bị thuyết phục, anh lại mời Lai Xiaohua đi đánh bạc, Lai Xiaohua nhận lời vì cho rằng anh rất can đảm. Để lấy lại thể diện, Zhang Hui đã cầu xin người quản gia già tìm những người có năng lực ở quê để giúp đỡ mình. Không ngờ anh lại bị những kẻ tu luyện tà ác trên toàn thế giới lợi dụng. Ma Yiheng, hậu duệ của nhà họ Mã, được cha ra lệnh giúp đỡ Lai thiếu gia, kết quả là thiện và ác gặp nhau và chiến tranh bắt đầu.</p>', 'Full', 1, 'single', 'completed', 11, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"Lin Fengye","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"付赫安琪","avatar":""},{"name":"Gao Xuanming","avatar":""},{"name":"Wang Jiaxi","avatar":""},{"name":"Liu Dongming","avatar":""},{"name":"Chen Yuyong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
