INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ki-dieu-cua-tiem-tap-hoa-namiya', 'Điều Kì Diệu Của Tiệm Tạp Hóa Namiya', 'Namiya', 'https://phimimg.com/upload/vod/20231102-1/75115de6ca9ece39070cb96b1a15d241.jpg', 'https://phimimg.com/upload/vod/20231102-1/75b0a0cc81305943af2f0e47f5921cd4.jpg', '<p>Dựa trên tiểu thuyết cùng tên của tác giả Higashino Keigo. Xoay quanh ba cô cậu trong một dêm đi làm chuyện xấu vô tình tìm thấy tiệm tạp hóa Namiya, từ đó mở ra nhiều bí mật không tưởng, sự biến thiên giữa thời gian bên ngoài và bên trong tiệm tạp hóa ấy, cùng những lá thư ẩn chứa những thông điệp đầy tính nhân văn và xúc động.</p>', 'Full', 1, 'single', 'completed', 25, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Karry Wang","avatar":""},{"name":"Dilraba Dilmurat","avatar":""},{"name":"Hao Lei","avatar":""},{"name":"Qin Hao","avatar":""},{"name":"Dong Zijian","avatar":""},{"name":"Chen Duling","avatar":""},{"name":"Lee Hong Chi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
