INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-doi-dau-samurai', 'Ninja Đối Đầu Samurai', 'MUMON: The Land of Stealth', 'https://phimimg.com/upload/vod/20231102-1/99e2a2a3cfdc590ae8c0a1a1bed39ac5.jpg', 'https://phimimg.com/upload/vod/20231102-1/7d50091987144c2464af82a0f09fc479.jpg', '<p>Mumon - một người có tài năng, sức mạnh phi thường nhưng lại lười biếng. Một ngày nọ, anh đã giết một Samurai từ một gia đình khác để giành phần thưởng. Mumon không biết rằng hành động của mình sẽ dẫn đến một cuộc chiến chết người giữa các quân đoàn ninja của tỉnh Iga và quân đoàn Nobukatsu Oda ở tỉnh Ise.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satoshi Ohno","avatar":""},{"name":"Satomi Ishihara","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Ryohei Suzuki","avatar":""},{"name":"Yuri Chinen","avatar":""},{"name":"Makita Sports","avatar":""},{"name":"Yuna Taira","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Denden","avatar":""},{"name":"Kitaro","avatar":""},{"name":"Danshun Tatekawa","avatar":""},{"name":"Jun Kunimura","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
