INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-quang-phuong-bac', 'Cực Quang Phương Bắc', 'Northern Lights: A Journey to Love', 'https://phimimg.com/upload/vod/20231102-1/47f5c5e39d7479d8e953a2210254574b.jpg', 'https://phimimg.com/upload/vod/20231102-1/37ef404aa2b4b937cf8fdf055a783371.jpg', '<p>Charlie là một anh chàng Philippines độc thân, yêu thích cuộc sống tự do, hiện đang định cư ở Alaska, Mỹ. Bất đắc dĩ phải chăm sóc đứa con trai mà bao năm qua mình bỏ rơi, Charlie buộc phải đối mặt với quá khứ, chuộc lỗi và học cách yêu thương. Giúp đỡ anh trong hành trình cứu chuộc là Angel, một người Philippines đến Alaska để tìm mẹ.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Piolo Pascual","avatar":""},{"name":"Yen Santos","avatar":""},{"name":"Raikko Mateo","avatar":""},{"name":"Joel Torre","avatar":""},{"name":"Sandy Andolong","avatar":""},{"name":"Tirso Cruz III","avatar":""},{"name":"Maricar Reyes","avatar":""},{"name":"Glydel Mercado","avatar":""},{"name":"Jerald Napoles","avatar":""},{"name":"Anna Vicente","avatar":""},{"name":"K Brosas","avatar":""},{"name":"David Chua","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
