INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuc-quang-phuong-bac', 'Cực Quang Phương Bắc', 'Northern Lights: A Journey to Love', 'cực quang phương bắc northern lights: a journey to love piolo pascual yen santos raikko mateo joel torre sandy andolong tirso cruz iii maricar reyes glydel mercado jerald napoles anna vicente k brosas david chua ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thu-dao', 'Không Thủ Đạo', 'The Empty Hands', 'https://phimimg.com/upload/vod/20231102-1/7e90875d1d3c37ec1e533008384a8273.jpg', 'https://phimimg.com/upload/vod/20231102-1/be6984e340046b4401b0a5ec2f6d584f.jpg', '<p>Mari Hirakawa lai Trung Quốc và nửa Nhật Bản là con gái của một huấn luyện viên Karate. Từ khi còn nhỏ, cô ấy đã bị cha mình ép buộc phải tập luyện và đã căm ghét Karate từ rất lâu mà cô ấy có thể nhớ được - mong muốn duy nhất của cô ấy là bán võ đường sau khi cha cô ấy qua đời. Sau cái chết của anh ta, Mari bắt đầu mơ mộng về cuộc sống tự do của mình; tuy nhiên, cô phát hiện ra từ luật sư của mình rằng cha cô chỉ để lại cho cô 49% quyền sở hữu tài sản, 51% còn lại được để lại cho một trong những học trò tồi nhất của ông, Chan Keung. Hai người xung đột, và Chan đưa ra một đề xuất - nếu Mari có thể thắng một trận trong một cuộc thi đấu võ thuật hợp pháp, anh ta sẽ chia cho cô ấy phần tài sản của mình một cách vô điều kiện. Mari bị mắc kẹt trong một tình thế tiến thoái lưỡng nan, và sẽ phải đưa ra lựa chọn sẽ thay đổi cuộc đời cô...</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Stephy Tang","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Stephen Au Kam-Tong","avatar":""},{"name":"Dada Chan","avatar":""},{"name":"Ryan Lau","avatar":""},{"name":"Michelle Lo","avatar":""},{"name":"Chow Chi-Fai","avatar":""},{"name":"Roy Szeto","avatar":""},{"name":"Tanya Chan","avatar":""},{"name":"Man Sai","avatar":""},{"name":"Patrick Leung Pak-Kin","avatar":""},{"name":"Himmy Wong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
