INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-chuyen-cua-su-song-hanh-trinh-xuyen-thoi-gian', 'Biến Chuyển Của Sự Sống: Hành Trình Xuyên Thời Gian', 'Voyage of Time: Life''s Journey', 'https://phimimg.com/upload/vod/20231102-1/155a3617c8c840ad2d97157c29b136da.jpg', 'https://phimimg.com/upload/vod/20231102-1/109a69b472b9bc6afd02531b71427a6e.jpg', '<p>Phim Biến Chuyển Của Sự Sống: Hành Trình Xuyên Thời Gian - Voyage Of Time: Life&#39;s Journey 2016: phim tài liệu khoa học, lấy chủ đề sự hình thành và phát triển của vũ trụ dựa trên những kiến thức mà con người biết được.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Theo Bongani Ndyalvane","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
