INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('77-lan-thu-tha', '77 lần thứ tha', '77 Heartbreaks', 'https://phimimg.com/upload/vod/20231102-1/c75c71cbd78bd3a5c7e26e912046d8cb.jpg', 'https://phimimg.com/upload/vod/20231102-1/16f43d43a434b5dcc98781c7e673e0c0.jpg', '<p>Eva (Thái Trác Nghiên) và Adam (Châu Bách Hào) đã yêu nhau 10 năm nhưng vì một chuyện nhỏ mà bỗng nhiên chia tay. Sau một lần uống rượu say Adam đã nảy sinh tình cảm với Mandy – học sinh của mình (Thi Nhã). Thế nhưng Mandy đã tình cờ tìm thấy cuốn sổ nhật ký “77 lần tha thứ” trong nhà của Adam, trong đó ghi lại những lần tha thứ sau khi Adam đã làm tổn thương Eva. &nbsp;Adam cảm thấy hổ thẹn với lòng mình, lấy hết dũng khí nói lời xin lỗi Eva trước mặt đám đông. Ngờ đâu, Eva lại tìm thấy vật dụng của Mandy trong nhà của Adam. Rốt cuộc cô ấy có tha thứ cho Adam lần thứ 78 này không?</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Charlene Choi","avatar":""},{"name":"Pakho Chau","avatar":""},{"name":"Michelle Wai","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Candy Lo","avatar":""},{"name":"Lei Chenyu","avatar":""},{"name":"C Kwan","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Bob Lam","avatar":""},{"name":"Tyson Chak","avatar":""},{"name":"Terence Tsui","avatar":""},{"name":"Henry Yu Yang","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Amanda Lee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
