INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-cua-su-hanh-phuc', 'Thời Gian Của Sự Hạnh Phúc', 'Mutluluk Zamani', 'https://phimimg.com/upload/vod/20231102-1/654927f8ded433b62ec8afb0573e3159.jpg', 'https://phimimg.com/upload/vod/20231102-1/834d99a29a3f88b4ae1baae495cebb10.jpg', '<p>Mert là chủ sở hữu của công ty &quot;mutluet.com.tr&quot;, công ty đã biến khách hàng của mình thành những người kiên cường chống chọi với cuộc sống. Con đường của Mert, người đã tạo ra cuộc sống hoàn hảo của riêng mình mà không phải đối mặt với quá khứ của mình, và Ada, người đã xây dựng cả cuộc đời mình dựa trên những trải nghiệm trong quá khứ, bất ngờ cắt nhau. Cuộc sống của Mert bắt đầu thay đổi khi anh quen Ada. Ada, người đã yêu Mert khi cô ấy quen anh ấy, không thể thành công cho dù anh ấy có cố gắng ngăn cản tình cảm của mình như thế nào. Cuộc đời của Tarık, anh trai của Ada, người luôn coi mình là kẻ thua cuộc, rẽ sang một hướng hoàn toàn khác khi anh gặp Mert. Tuy nhiên, Cengiz không biết rằng Mert đang yêu em gái mình, cũng như anh trai của Ada không phải là người đang học những bài học hư hỏng từ Mert.<br/>Barış Arduç và Elçin Sangu, những người đã đạt được thành công lớn với các nhân vật Ömer và Defne trong bộ phim truyền hình Cho thuê tình yêu, đóng vai chính trong bộ phim hài lãng mạn.</p>', 'Full', 1, 'single', 'completed', 21, 2017, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Elçin Sangu","avatar":""},{"name":"Barış Arduç","avatar":""},{"name":"Cengiz Bozkurt","avatar":""},{"name":"Dila Bayrak","avatar":""},{"name":"Levent Öktem","avatar":""},{"name":"Nazlı Kar","avatar":""},{"name":"Sedef Avci","avatar":""},{"name":"Yasmin Erbil","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug