INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-hai-hoi-ngo', 'Danh Hài Hội Ngộ', 'Top Funny Comedian: The Movie', 'https://phimimg.com/upload/vod/20231101-1/49b736373a0b90b74e8d6b8c1a338d83.jpg', 'https://phimimg.com/upload/vod/20231101-1/ff35e507113f3dc849f0c960ebdb7f6f.jpg', '<p>Nhằm chuẩn bị tốt cho tiết mục mới, thầy Quách dẫn theo các thành viên trong đội - gồm các danh hài hàng đầu xứ Trung - đến Macao tập luyện. Kể từ đây các hiểu lầm, rắc rối dở khóc dở cười liên tục xảy ra với mọi người.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Degang","avatar":""},{"name":"Yunpeng Yue","avatar":""},{"name":"Rowan Atkinson","avatar":""},{"name":"Allen Ai Lun","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Evander Holyfield","avatar":""},{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Lee Sheung-Ching","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Zhang Xiaofei","avatar":""},{"name":"Wei Lu","avatar":""},{"name":"Chenya Lisa Ting","avatar":""},{"name":"Jingjie Yan","avatar":""},{"name":"Zhang Zidong","avatar":""},{"name":"Lei Pengyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
