INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vincent-thuong-men', 'Vincent Thương Mến', 'Loving Vincent', 'https://phimimg.com/upload/vod/20231101-1/694949084fd6283dc01e0dbb2e2c526f.jpg', 'https://phimimg.com/upload/vod/20231101-1/49e7f538ea0cbb0b9fa4abccfce61752.jpg', '<p>Mùa hè năm 1891, tại nước Pháp. Armand Roulin, được cha mình là Joseph Roulin giao nhiệm vụ đến Paris để trao tận tay một lá thư. Người nhận là Theo Van Gogh, em trai ruột của Vincent Van Gogh – một họa sĩ lập dị đã tự cắt tai mình và tự sát cách đây không lâu. Khi đến nơi, Armand phát hiện ra rằng Theo đã chết, nguyên nhân một phần có lẽ vì quá đau buồn trước cái chết của người anh trai. Armand gặp Pere Tanguy, một người chuyên cung cấp sơn dầu, có quen biết cả hai anh em.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Douglas Booth","avatar":""},{"name":"Robert Gulaczyk","avatar":""},{"name":"Eleanor Tomlinson","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Saoirse Ronan","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"John Sessions","avatar":""},{"name":"Jerome Flynn","avatar":""},{"name":"Aidan Turner","avatar":""},{"name":"Holly Earl","avatar":""},{"name":"Cezary Łukaszewicz","avatar":""},{"name":"Martin Herdman","avatar":""},{"name":"James Greene","avatar":""},{"name":"Bill Thomas","avatar":""},{"name":"Josh Burdett","avatar":""},{"name":"Robin Hodges","avatar":""},{"name":"Carole Le","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324408);
