INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('haikyu-ban-dien-anh-4-huyen-thoai-xuat-hien', 'Haikyu!! Bản điện ảnh 4: Huyền thoại xuất hiện', 'Haikyu!! Movie 4: Battle of Concepts', 'https://phimimg.com/upload/vod/20231101-1/01afbcaea7649618165356903eea5843.jpg', 'https://phimimg.com/upload/vod/20231101-1/28aa3024c97f5053db88dd396dd5ffa6.jpg', '<p>Khi cơ hội tham dự giải quốc gia đang bị đe dọa, đội bóng chuyền trường phổ thông Karasuno đối đầu với đội của Học viện Shiratorizawa, đội bóng mạnh nhất quận.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazunari Tanaka","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
