INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-he-nguy-hiem', 'Quan Hệ Nguy Hiểm', 'Serious Laundry', 'null', 'https://phimimg.com/upload/vod/20231110-1/9a9a76808ba579ba397b3e4ffc2d34ba.jpg', '<p>Khi một người đàn ông trẻ tuổi bị dụ dỗ tham gia giúp dọn xác, anh ta phải tìm ra sự thật đằng sau cái xác trước khi mất mạng hoặc kiếm được tài sản. Đó là một bộ phim trộm cắp truyện tranh điên rồ với rất nhiều trái tim.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michele Richardson","avatar":""},{"name":"Tatiana Grey","avatar":""},{"name":"Jason Zednick","avatar":""},{"name":"Malcolm Mills","avatar":""},{"name":"Michael Gentile","avatar":""},{"name":"Jeffrey Alan Solomon","avatar":""},{"name":"Yukiko Miyawaki","avatar":""},{"name":"Ali Andre Ali","avatar":""},{"name":"Buck Biestek","avatar":""},{"name":"Christian Carroll","avatar":""},{"name":"Alison Chace","avatar":""},{"name":"Sheila Joon Azim","avatar":""},{"name":"Christian Perry","avatar":""},{"name":"Susan Slatin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
