INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-ngoai-o', 'Đêm Ngoại Ô', 'Better Watch Out', 'https://phimimg.com/upload/vod/20231109-1/dd4efcbc3a554c5ca0d890cb73494b22.jpg', 'https://phimimg.com/upload/vod/20231109-1/4f23dfc1eb15d8fa15d9f9696e60dc12.jpg', '<p>Khi bạn nghĩ tới các vùng ngoại ô, bạn nghĩ tới sự an toàn, nhưng đêm nghỉ lễ này ở vùng ngoại ô là bất cứ điều gì ngoại trừ sự an toàn. Ashley (Olivia DeJonge) nghĩ rằng công việc trông trẻ này sẽ là một đêm dễ dàng, nhưng đêm bình an biến mất khi những kẻ xâm nhập nguy hiểm đột nhập vào nhà, khủng bố cô ấy và cậu bé mười hai tuổi, Luke (Levi Miller), người mà cô ấy đang chăm sóc. Ashley cố gắng hết sức bảo vệ cho tất cả chỉ để phát hiện ra đây không phải là màn đột nhập vào nhà bình thường. Đằng sau đó là cả một câu chuyện hết sức nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olivia DeJonge","avatar":""},{"name":"Levi Miller","avatar":""},{"name":"Ed Oxenbould","avatar":""},{"name":"Aleks Mikic","avatar":""},{"name":"Dacre Montgomery","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Alexandra Matusko","avatar":""},{"name":"Georgia Holland","avatar":""},{"name":"Beau Andre","avatar":""},{"name":"Michi Fifer","avatar":""},{"name":"Tara Jade Borg","avatar":""},{"name":"Tricia Mary Hennessy","avatar":""},{"name":"Mary Clearkin","avatar":""},{"name":"Hugo Monotti","avatar":""},{"name":"Brendan Clearkin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
