INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-anh-bi-am', 'Bức Ảnh Bị Ám', 'The Haunted Graduation Photo', 'null', 'https://phimimg.com/upload/vod/20231109-1/410e38b3725611aa8c85f6c0cbb09c7b.jpg', '<p>Bức Ảnh Bị Ám - The Haunted Graduation Photo kể về mùa hè năm cuối cấp khi các sinh viên hẹn nhau chụp ảnh tốt nghiệp. Thế rồi, trong hình các nữ sinh xuất hiện một cô gái tóc thắt hình nơ bướm màu đỏ nhưng không có chân. Mọi người đồn đó là hồn ma của Phiêu Phiêu - một nữ sinh không may qua đời vào kỳ nghỉ hè năm ngoái. Từ đó, hàng loạt chuyện rùng rợn xuất hiện.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Yuan","avatar":""},{"name":"Liu Li-Er","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
