INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-kieu-my', 'Sát Thủ Kiểu Mỹ', 'American Assassin', 'https://phimimg.com/upload/vod/20231101-1/92ea376afaecb67a3865b6e1a163c7ac.jpg', 'https://phimimg.com/upload/vod/20231101-1/54a9cab2747876ac934090d3f5e0d8c1.jpg', '<p>Sát Thủ Kiểu Mỹ, American Assassin câu chuyện buồn của chàng trai 23 tuổi, Mitch. Anh bị mất cha mẹ ở tuổi 14 trong một tai nạn giao thông, và bạn gái anh bị chết trong ngày đính hôn của anh. Muốn trả thù, anh ta được tuyển mộ bởi phó giám đốc CIA Irene Kennedy như là một tuyển dụng cớm đen. Kennedy sau đó chỉ định cựu chiến binh lạnh Stan Hurley để đào tạo Mitch. Họ sẽ cùng nhau điều tra một đợt các cuộc tấn công ngẫu nhiên rõ ràng vào các mục tiêu quân sự và dân sự. Việc khám phá ra một khuôn mẫu trong bạo lực đã dẫn họ đến một sứ mệnh chung với một đại lý Thổ Nhĩ kỳ để ngăn chặn một mục đích bí ẩn nhằm mục đích bắt đầu một cuộc chiến tranh thế giới ở Trung Đông.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Shiva Negar","avatar":""},{"name":"Sanaa Lathan","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"David Suchet","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Joseph Long","avatar":""},{"name":"Charlotte Vega","avatar":""},{"name":"Andrew Pleavin","avatar":""},{"name":"Shahid Ahmed","avatar":""},{"name":"Joost Janssen","avatar":""},{"name":"Adam Collins","avatar":""},{"name":"Christopher Bomford","avatar":""},{"name":"Stephen Shafer","avatar":""},{"name":"Vladimir","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
