INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-rong-4-tam-hoa-chien', 'Tim Rồng 4: Tâm Hỏa Chiến', 'Dragonheart: Battle For The Heartfire', 'https://phimimg.com/upload/vod/20231101-1/3a4be5046224d831b4b2dfef8125642f.jpg', 'https://phimimg.com/upload/vod/20231101-1/05aa068954be8268dea74e65876e53ea.jpg', '<p>Phim Tim Rồng 4: Tâm Hỏa Chiến - Dragonheart: Battle For The Heartfire 2017: Sau khi vua Gareth qua đời thì 2 người anh em tranh nhau ngai vàng, cả 2 đều xứng đáng vì mang trong mình sức mạnh của rồng. Nhưng trong lúc đó nguồn sức mạnh của rồng Drago (được gọi là Heartfire) bị đánh cắp, vả vương quốc bị đe dọa. Hai anh em phải liên kết để bảo vệ vương quốc hoặc mất tất cả.</p>', 'Full', 1, 'single', 'completed', 24, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marte Germaine Christensen","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Tom Rhys Harries","avatar":""},{"name":"Jessamine-Bliss Bell","avatar":""},{"name":"Tamzin Merchant","avatar":""},{"name":"André Eriksen","avatar":""},{"name":"Richard Cordery","avatar":""},{"name":"Martin Hutson","avatar":""},{"name":"Delroy Brown","avatar":""},{"name":"Turlough Convery","avatar":""},{"name":"Dina De Laurentiis","avatar":""},{"name":"Elijah Ungvary","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Daniel Berge Hal","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324408);
