INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-mau-cua-cuoc-chien', 'Sắc Màu Của Cuộc Chiến', 'Colour Of The Game', 'https://phimimg.com/upload/vod/20231101-1/c4afdd9a03f4304b589204c982f3f381.jpg', 'https://phimimg.com/upload/vod/20231101-1/0735f36b1e87f3ed4ede886acb6b042e.jpg', '<p>Nhận lệnh trừ khử con trai cưng của ông trùm trong cùng tổ chức, Đại Hoa rơi vào tình thế tiến thoái lưỡng nan. Để thực hiện phi vụ này Đại Hoa phải hợp tác với các anh em cũ thành lập một nhóm tác chiến cùng nhau tái xuất giang hồ. Thế nhưng mỗi lần hành động điều bị kẻ địch đoán trước được đường đi nước bước.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Sabrina Qiu","avatar":""},{"name":"Oscar Leung","avatar":""},{"name":"Hazel Tong","avatar":""},{"name":"Ye Xiangming","avatar":""},{"name":"Gui Jingjing","avatar":""},{"name":"Dana Meng","avatar":""},{"name":"Law Wing-cheong","avatar":""},{"name":"Angie Cheung Wai-Yee","avatar":""},{"name":"Timothy Cheng","avatar":""},{"name":"Ph","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
