INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sac-mau-cua-cuoc-chien', 'Sắc Màu Của Cuộc Chiến', 'Colour Of The Game', 'sắc màu của cuộc chiến colour of the game simon yam jordan chan philip ng wan-lung eddie cheung kenny wong tak-ban lau siu-ming waise lee chi-hung lam suet sabrina qiu oscar leung hazel tong ye xiangming gui jingjing dana meng law wing-cheong angie cheung wai-yee timothy cheng ph ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-vuot-nghich-canh', 'Hành Trình Vượt Nghịch Cảnh', 'A Fantastic Woman', 'https://phimimg.com/upload/vod/20231101-1/4e7310e8f01cfe2fb05faa7a47722265.jpg', 'https://phimimg.com/upload/vod/20231101-1/965facd756e474d121b18e19f6a8e031.jpg', '<p>Marina (Daniela Vega) kiếm sống bằng công việc phục vụ bàn và ấp ủ giấc mơ trở thành ca sĩ chuyên nghiệp. Cô mạnh mẽ và tự chủ trong cuộc sống. Cô yêu Orlando (Francisco Reyes) - một trí thức già, hơn cô 20 tuổi và đã ly hôn - đang lên kế hoạch đưa Marina đi thăm thác Iguazu ở biên giới Brazil - Argentina. Bi kịch xảy đến khi ông đột ngột bị tai biến và qua đời chỉ vài phút sau khi được đưa tới bệnh viện cấp cứu. Trong tích tắc mất đi người yêu thương, Marina đau đớn, hoảng loạn. Nhưng đó chưa phải cơn ác mộng kinh hoàng nhất đến với cô. Cả xã hội như quay lưng lại với người phụ nữ mạnh mẽ nhưng đau khổ này. Điều khủng khiếp hơn là sự kỳ thị, ngược đãi, bạo hành liên tiếp từ gia đình bạn trai quá cố và đủ mọi thành phần xã hội chỉ vì Marina là một người chuyển giới...</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniela Vega","avatar":""},{"name":"Francisco Reyes","avatar":""},{"name":"Luis Gnecco","avatar":""},{"name":"Aline Küppenheim","avatar":""},{"name":"Nicolás Saavedra","avatar":""},{"name":"Amparo Noguera","avatar":""},{"name":"Néstor Cantillana","avatar":""},{"name":"Alejandro Goic","avatar":""},{"name":"Antonia Zegers","avatar":""},{"name":"Marcial Tagle","avatar":""},{"name":"Cristián Chaparro","avatar":""},{"name":"Diana Cassis","avatar":""},{"name":"Eduardo Paxeco","avatar":""},{"name":"Roberto Farías","avatar":""},{"name":"Pablo Cerda","avatar":""},{"name":"José Antonio Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
