INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-giao-voodoo', 'Ma Giáo Voodoo', 'VooDoo', 'null', 'https://phimimg.com/upload/vod/20231101-1/5fad0e766de93a2b6a34872a0250aba5.jpg', '<p>Dani Lamb, một cô gái trẻ có vẻ ngây thơ đến từ New Orleans, đi nghỉ ở Los Angeles sau khi phát hiện ra bạn trai Frank đã kết hôn với một nữ tu sĩ tốt bụng tên là Serafine trong toàn bộ thời gian cô ấy hẹn hò với anh ta. Khi cô đến LA, cô tái hợp với anh họ Stacy, người luôn như một người chị lớn đối với cô. Vào ngày thứ 2 của cô ở LA, cô nhận được một cuộc điện thoại từ Frank, nói với cô rằng Serafine đã theo cô đến LA và sẽ sử dụng sức mạnh tà thuật của cô để chống lại cô. Dani phản ứng điên cuồng với sự mặc khải và ngay lập tức lo sợ cho cuộc sống của cô. Dani trải qua một nỗi ám ảnh cực độ được tạo ra bởi ác quỷ Serafine và cô ấy đã nguyền rủa xuống Địa ngục. Trên hành trình xuyên qua Địa ngục, Dani phát hiện ra những điều kinh hoàng tồn tại được thiết kế để tiêu diệt cô. Cô ấy đã đánh bại hoàn toàn, cả về tinh thần và thể xác, và khi cô ấy gặp Satan, cô ấy đã từ bỏ tâm hồn mình từ lâu.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samantha Stewart","avatar":""},{"name":"Ruth Reynolds","avatar":""},{"name":"Dominic Matteucci","avatar":""},{"name":"Daniel Kozul","avatar":""},{"name":"Ron Jeremy","avatar":""},{"name":"Alec Justin Henderson","avatar":""},{"name":"Lavelle Roby","avatar":""},{"name":"Constance Strickland","avatar":""},{"name":"Courteney Winter","avatar":""},{"name":"Nicole DeMaria","avatar":""},{"name":"Alexandra DeMartini","avatar":""},{"name":"Richard Kray","avatar":""},{"name":"Emily Charouhas","avatar":""},{"name":"Gina Fantozzi","avatar":""},{"name":"Russell Gielish","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
