INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-den-qua-khu', 'Bóng Đen Quá Khứ', 'Ice Blue', 'https://phimimg.com/upload/vod/20231101-1/37e59c1e705f67da0ff197ff6d9bfba1.jpg', 'https://phimimg.com/upload/vod/20231101-1/bb3771817e0f220bbe4603644ca58e98.jpg', '<p>Thế giới của Arielle, 16 tuổi đang xáo trộn khi mẹ cô trở về một cách bí ẩn, điều khiển mối quan hệ dường như hoàn hảo mà cô có với cha mình trong khi làm sáng tỏ những bí mật gia đình được che giấu từ lâu trong trang trại chân đồi biệt lập của họ.</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Michelle Morgan","avatar":""},{"name":"Billy MacLellan","avatar":""},{"name":"Sophia Lauchlin Hirt","avatar":""},{"name":"Charlie Kerr","avatar":""},{"name":"Mikaela Cochrane","avatar":""},{"name":"Mikaela Cochrane","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
