INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chot-kiem-soat', 'Chốt Kiểm Soát', 'Check Point', 'https://phimimg.com/upload/vod/20231031-1/e2bf24727e12252e76c81ad49948bcd3.jpg', 'https://phimimg.com/upload/vod/20231031-1/e98244c547886f4d0bdefc02fae6eda1.jpg', '<p>Port City North Carolina: Trong một buổi cắm trại thường lệ, một người lang thang địa phương phát hiện ra kế hoạch xâm lược nước Mỹ. Khi anh ta cố gắng thông báo cho Cảnh sát trưởng địa phương về phát hiện của mình, Cảnh sát trưởng bác bỏ yêu cầu của anh ta và nhốt anh ta vì tội lảng vảng. Khi Cảnh sát trưởng nhận thấy những tương tác kỳ lạ với người dân ở các thị trấn khác, anh ta bắt đầu xem xét yêu sách của những người lang thang về một phòng giam ngủ giữa những người dân địa phương trong thị trấn nhỏ này. Sau khi bằng chứng về một vụ chặt đầu được phơi bày, những người khác bắt đầu lo sợ rằng quân nổi dậy sẽ tấn công quê hương Hoa Kỳ. Các câu hỏi và tâm trạng bắt đầu tăng lên. Tại sao cộng đồng bãi biển nhỏ này với lối sống của Norman Rockwell? Một thị trấn nơi mọi người đều biết nhau... hoặc họ nghĩ vậy. Khi sự thật mù mịt và công lý dường như đã mất, Nó sẽ đưa một đội quân gồm năm anh hùng không có khả năng hợp tác với nhau để thâm nhập vào quân nổi dậy và phá vỡ kế hoạch xâm lược của chúng.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Forsythe","avatar":""},{"name":"Kenny Johnson","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Mindy Robinson","avatar":""},{"name":"Tyler Mane","avatar":""},{"name":"Bill Goldberg","avatar":""},{"name":"Fred Williamson","avatar":""},{"name":"Michelle Lee","avatar":""},{"name":"Stephen Geoffreys","avatar":""},{"name":"Ricky Harris","avatar":""},{"name":"John Lewis","avatar":""},{"name":"Krista Grotte Saxon","avatar":""},{"name":"Mel Novak","avatar":""},{"name":"Olga Safari","avatar":""},{"name":"David Schifter","avatar":""},{"name":"Robert Fortunato","avatar":""},{"name":"Deaven Broo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
