INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-nho', 'Thu Nhỏ', 'Downsizing', 'https://phimimg.com/upload/vod/20231030-1/081af45ac45061ed17f061139e84b8a1.jpg', 'https://phimimg.com/upload/vod/20231030-1/211ab3149b70c6c4f5ed198f4a7f0979.jpg', '<p>Đạo diễn từng giành giải Oscar Alexander Payne trở lại với một bộ phim hài hước và cảm động. Khi các nhà khoa học tìm ra cách thu nhỏ con người xuống còn gần 13 cm, Paul và cô vợ Audrey quyết định từ bỏ cuộc sống đầy áp lực để đến với thế giới thu nhỏ giàu sang hơn. Vùng Đất Sung Sướng không chỉ là những cuộc phiêu lưu vĩ đại và vô vàn cơ hội mà ở đó, Paul còn khám phá ra một thế giới mới và nhận ra chúng ta sống vì những điều lớn lao hơn. Chủ nhân giải Oscar Christoph Waltz cũng góp mặt trong bộ phim giàu trí tưởng tượng và sáng tạo này.</p>', 'Full', 1, 'single', 'completed', 34, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Rolf Lassgård","avatar":""},{"name":"Ingjerd Egeberg","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Søren Pilmark","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Maribeth Monroe","avatar":""},{"name":"Jayne Houdyshell","avatar":""},{"name":"Phil Reeves","avatar":""},{"name":"James Van Der Beek","avatar":""},{"name":"Alison J. Palmer","avatar":""},{"name":"Tim Driscoll","avatar":""},{"name":"Kristen Thomson","avatar":""},{"name":"Kevin Kunke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
