INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum', 'Ông Trùm', 'Shot Caller', 'https://phimimg.com/upload/vod/20231029-1/53be3e229ba446ac7b07a98d41e04efc.jpg', 'https://phimimg.com/upload/vod/20231029-1/0262f88592be8f67bc99fcf5636e86d1.jpg', '<p>Một người đàn ông của gia đình bị đưa đến nhà tù sau khi gây ra tai nạn giao thông chết người. Một thương gia thành công Jacob Harlon (Nicolaj Coster Waldau) đã trở thành một tay găng tơ tàn nhẫn trong nhà tù. Khi bước vào ngôi nhà mới đầy tàn bạo, anh phải thích nghi với các quy tắc và nghi lễ truyền thống của những tù nhân ở đây tạo ra để có thể đảm bảo sự sống còn cho mình. Anh dần dần mất đi bản chất lương thiện và các mối quan hệ trong cuộc sống trước kia bao gồm cả vợ và con trai của mình. Sự kìm kẹp trong gia đình mới của anh và những nhóm tù nhân đã trải dài ra ngoài bức tường của nhà tù. Khi được giải thoát anh vẫn bị theo dõi bởi các cơ quan pháp luật và bị đe dọa bởi những tên tội phạm trong tù trước đây. Jacob đã phải dàn dựng lên một tội ác nguy hiểm cuối cùng. Quá trình tàn nhẫn để hoàn thành nghĩa vụ của mình cũng trở thành con đường dẫn đến sự hy sinh, trả thù và nhìn nhận lại bản thân...</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Omari Hardwick","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Emory Cohen","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Evan Jones","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Chris Browning","avatar":""},{"name":"Max Greenfield","avatar":""},{"name":"Jessy Schram","avatar":""},{"name":"Juan Pablo Raba","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Michael Landes","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Sarah Minn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
