INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-7-nhiem-vu-toi-mat', 'Lính Bắn Tỉa 7: Nhiệm Vụ Tối Mật', 'Sniper: Ultimate Kill', 'https://phimimg.com/upload/vod/20231029-1/0e30b0672d88ae56b589367b5524e302.jpg', 'https://phimimg.com/upload/vod/20231029-1/a49d10a7a64c3de45aeff676babd63df.jpg', '<p>Nhà sản xuất ma túy người Colombia, Jesús Morales bí mật trả tiền cho một tay bắn tỉa có biệt danh là &quot;Quỷ dữ&quot;, có khả năng giết chết từng kẻ thù của bất cứ ai thuê anh ta. Không có đối thủ nào còn sống, Morales phát triển mạnh hơn và giành quyền kiểm soát các tuyến buôn lậu vào Mỹ. Tổ chức DEA báo động bởi mối đe dọa này đối với đất nước, gửi mật vụ Kate Estrada, người đã theo dõi Morales trong nhiều năm, và tay bắn tỉa Marine Brandon Beckett đến Colombia thực hiện nhiệm vụ tối mật. Nhiệm vụ của họ là giết &quot;Quỷ dữ&quot; và mang Morales trở lại Mỹ để chịu hình phạt cho tội ác của mình. Các mật vụ nghĩ tất cả mọi thứ dưới sự kiểm soát</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Collins","avatar":""},{"name":"Danay García","avatar":""},{"name":"Joe Lando","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Pedro José Pallares","avatar":""},{"name":"Jaime Correa","avatar":""},{"name":"Lucho Velasco","avatar":""},{"name":"Andrés Felipe Calero","avatar":""},{"name":"Juan Pablo Gamboa","avatar":""},{"name":"Juan Sebastián Calero","avatar":""},{"name":"Diana Hoyos","avatar":""},{"name":"Fausto Garrido","avatar":""},{"name":"Aldemar Correa","avatar":""},{"name":"Conrado Osorio","avatar":""},{"name":"Alvaro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
