INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-lego-ninjago', 'Câu Chuyện Lego: Ninjago', 'The Lego Ninjago Movie', 'https://phimimg.com/upload/vod/20231029-1/a67bf902b978779619139eef0772e837.jpg', 'https://phimimg.com/upload/vod/20231029-1/5586ab13e03deb96cf96ca5e3a5ff54d.jpg', '<p>Tác phẩm hoạt hình hài hước xoay quanh sáu ninja trẻ tuổi sống trên hòn đảo Ninjago. Ban đêm, họ là những chiến binh tài năng, tận dụng kỹ năng võ thuật để chiến đấu với các ác nhân và quái vật. Ban ngày, họ trở về với xuất thân là những cô cậu học trò tuổi teen và phải đối đầu với &quot;kẻ thù&quot; lớn nhất là trường học.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2017, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Dave Franco","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Abbi Jacobson","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"David Burrows","avatar":""},{"name":"Alex Kauffman","avatar":""},{"name":"Ali Wong","avatar":""},{"name":"Garret Elkins","avatar":""},{"name":"Doug Nicholas","avatar":""},{"name":"Charlyne Yi","avatar":""},{"name":"Vanara Taing","avatar":""},{"name":"Laura Kightlinger","avatar":""},{"name":"Randall Park","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408)