INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ngoan-bo-hu-2', 'Bố Ngoan, Bố Hư 2', 'Daddy''s Home 2', 'https://phimimg.com/upload/vod/20231029-1/8f45e324843e741539fe9c78781ced15.jpg', 'https://phimimg.com/upload/vod/20231029-1/9fb4f67581fdb308005b7474824dbcb3.jpg', '<p>Trong phần tiếp theo của siêu phẩm đình đám toàn cầu năm 2015, bố đẻ Dusty (Mark Wahlberg) và bố dượng Brad (Will Ferrell) đã hợp sức để mang tới một kỳ nghỉ Giáng sinh hoàn hảo cho các con. Quan hệ hợp tác mới của họ gặp thử thách khi cha của Dusty (Mel Gibson), một người nghiêm túc và cổ hủ, và cha của Brad (John Lithgow), một người dịu dàng, đến đúng lúc làm đảo lộn kỳ nghỉ.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"John Cena","avatar":""},{"name":"Alessandra Ambrosio","avatar":""},{"name":"Owen Vaccaro","avatar":""},{"name":"Scarlett Estevez","avatar":""},{"name":"Didi Costine","avatar":""},{"name":"Chesley Sullenberger","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"John Franchi","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Yamilah Saravong","avatar":""},{"name":"Hector Presedo","avatar":""},{"name":"Daniel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
