INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tron-tu-than', 'Vòng Tròn Tử Thần', 'Rings', 'https://phimimg.com/upload/vod/20231029-1/1989f69da392b5417ec280c77ac6e66b.jpg', 'https://phimimg.com/upload/vod/20231029-1/8c3853dfd3fa3d30057bc3e353212399.jpg', '<p>Julia trở nên lo lắng cho bạn trai Holt của mình khi anh khám phá truyền thuyết đô thị đen tối về một cuốn băng video bí ẩn được cho là sẽ giết người xem bảy ngày sau khi xem. Cô hy sinh bản thân để cứu bạn trai và làm như vậy đã phát hiện ra một điều kinh hoàng: có một &quot;bộ phim trong phim&quot;; mà chưa ai từng thấy trước đây.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matilda Lutz","avatar":""},{"name":"Alex Roe","avatar":""},{"name":"Johnny Galecki","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Aimee Teegarden","avatar":""},{"name":"Bonnie Morgan","avatar":""},{"name":"Chuck David Willis","avatar":""},{"name":"Patrick R. Walker","avatar":""},{"name":"Zach Roerig","avatar":""},{"name":"Laura Slade Wiggins","avatar":""},{"name":"Lizzie Brocheré","avatar":""},{"name":"Drew Grey","avatar":""},{"name":"Kayli Carter","avatar":""},{"name":"Jill Jane Clements","avatar":""},{"name":"Andrea Laing","avatar":""},{"name":"Surely Alv","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
