INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-xu-venice', 'Bố Già Xứ Venice', 'Once Upon a Time in Venice', 'https://phimimg.com/upload/vod/20231030-1/cdeb2e6bfbc65d0c2d3ee8de5fd53dec.jpg', 'https://phimimg.com/upload/vod/20231030-1/e63f5b141c244fbb27ecbc774688ed7c.jpg', '<p>Steve Ford là một thám tử tư ở Venice Beach, California, người tốt với phụ nữ, dở tệ với những cú đấm và cuồng nhiệt về chú chó Buddy của mình. Khi những tên côn đồ địa phương đánh cắp Buddy, Ford quay sang Spyder, thủ lĩnh quỷ quyệt của chúng và tạo nên một liên minh khó có thể tin được. Với sự giúp đỡ từ người bạn thân nhất của mình, Steve rút những khẩu súng lớn để lấy lại tiền mặt và cocaine bị đánh cắp của Spyder và cứu Buddy.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jason Momoa","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Thomas Middleditch","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Elisabeth Röhm","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Emily Robinson","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Tyga","avatar":""},{"name":"Colin Kane","avatar":""},{"name":"Ana Flavia Gavlak","avatar":""},{"name":"Stephanie Sigman","avatar":""},{"name":"Maurice Compte","avatar":""},{"name":"Ralph Garman","avatar":""},{"name":"Ken Dav","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 178469032440