INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giu-tre', 'Cô Giữ Trẻ', 'The Babysitter', 'https://phimimg.com/upload/vod/20231026-1/5cfbcb7596348a342505ef25decf7c7d.jpg', 'https://phimimg.com/upload/vod/20231026-1/a416c1d03065a4d1629da84c66d81ba3.jpg', '<p>Cole (Judah Lewis) yêu điên dại người giữ trẻ của mình - Bee (Samara Weaving). Cô ấy nóng bỏng, vui tính và nổi tiếng. Một đêm, trong giây phút thách thức, Cole đã bí mật thức để khám phá ra cô ấy thực sự là một kẻ giết người máu lạnh đang ở trong cuộc chiến với ma quỷ. Bây giờ cậu ta phải dành cả đêm để trốn khỏi nhóm giết người của Bee, những người sẽ không dừng lại để ngăn Cole loan ra bí mật của họ. Đó là khi Cole cố sống sót qua một đêm dài.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Judah Lewis","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Hana Mae Lee","avatar":""},{"name":"Bella Thorne","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"Andrew Bachelor","avatar":""},{"name":"Doug Haley","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Samuel Gilbert","avatar":""},{"name":"Zachary Alexander Rice","avatar":""},{"name":"Doc Duhame","avatar":""},{"name":"Jean Claude Leuyer","avatar":""},{"name":"Miles J. Harvey","avatar":""},{"name":"Chris Wylde","avatar":""},{"name":"Carl McDowe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
