INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me', 'mẹ!', 'mother!', 'https://phimimg.com/upload/vod/20231026-1/e8a5b2c743e4a36eef8480d2b75d7e2d.jpg', 'https://phimimg.com/upload/vod/20231026-1/ecd4505f0d8dc2362c1a8bae86381ea7.jpg', '<p>Câu chuyện của Mother! xoay quanh cuộc sống của hai vợ chồng Jennifer Lawrence (Mother) và Javier Bardem (Him) tại một vùng quê hẻo lánh. Javier vào vai một nhà thơ đang bế tắc trong sự nghiệp, trong khi đó, Jennifer Lawrence là một người vợ luôn chăm chỉ lo lắng chuyện bếp núc trong nhà. Cuộc sống của họ bị đảo lộn khi có sự ghé thăm của hai kẻ lạ mặt, đảm nhiệm bởi Michelle Pfeiffer và Ed Harris.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Brian Gleeson","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Jovan Adepo","avatar":""},{"name":"Amanda Chiu","avatar":""},{"name":"Patricia Summersett","avatar":""},{"name":"Eric Davis","avatar":""},{"name":"Raphael Grosz-Harvey","avatar":""},{"name":"Emily Hampshire","avatar":""},{"name":"Abraham Aronofsky","avatar":""},{"name":"Luis Oliva","avatar":""},{"name":"Stephanie Ng Wan","avatar":""},{"name":"Chris Garti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
