INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-luoi-cua', 'Sát Nhân Lưỡi Cưa', 'Leatherface', 'https://phimimg.com/upload/vod/20231026-1/304ec1037f9ccf3f1957c433a38df601.jpg', 'https://phimimg.com/upload/vod/20231026-1/3427045ce9c0e28856b9c1f5282d0322.jpg', '<p>Phim Leatherface là ngoại truyện của một trong những series phim kinh dị nổi tiếng nhất thế giới: The Texas Chainsaw Massacre kể về nguồn gốc của tên sát nhân hàng loạt đáng sợ có biệt danh Lưỡi cưa Texas, một kẻ thích giết người rồi lột da mặt họ để sưu tầm mặt nạ. Mọi sự bắt đầu với Leatherface trong những năm thiếu niên. Cậu đang cư trú trong viện tâm thần và vào một ngày, cậu đã trốn thoát cùng các bạn cùng phòng Bud (Sam Coleman), Ike (James Bloor) và Clarice (Jessica Madsen).
 Trên đường chạy trốn, họ đã bắt cóc y tá Lizzy (Vannesa Grasse) và đẩy cô vào một chuyến đi kinh hoàng. Khi bị Hal Hartman (Stephen Dorff) – một người thực thi pháp luật đầy thù hận, Jackson đã giết Hal. Việc này đã phá hủy tâm trí của Jackson, biến cậu thành con quái vật chuyên giết người bằng cưa máy và lột da nạn nhân để sưu tập. Biệt danh Leatherface đi liền với Jackson từ đó.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Vanessa Grasse","avatar":""},{"name":"Sam Strike","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"James Bloor","avatar":""},{"name":"Jessica Madsen","avatar":""},{"name":"Sam Coleman","avatar":""},{"name":"Lorina Kamburova","avatar":""},{"name":"Christopher Adamson","avatar":""},{"name":"Finn Jones","avatar":""},{"name":"Borisa Tyutyundzhieva","avatar":""},{"name":"Velizar Binev","avatar":""},{"name":"Vladimir Mihaylov","avatar":""},{"name":"Simona Williams","avatar":""},{"name":"Dimo Alexiev","avatar":""},{"name":"Nathan Cooper","avatar":""},{"name":"Dej","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
