INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-va-thuy-quai', 'Người Đẹp và Thủy Quái', 'The Shape of Water', 'https://phimimg.com/upload/vod/20231026-1/adef981162e578e9b8c07270d9b02a6c.jpg', 'https://phimimg.com/upload/vod/20231026-1/3a89cf753ac5e113fa70260e9dacc6ec.jpg', '<p>Người Đẹp &amp; Thủy Quái là một chuyện tình không tưởng lấy bối cảnh trong thời kỳ Chiến Tranh Lạnh 1962. Làm việc cho viện nghiên cứu bí mật được bảo vệ nghiêm ngặt của chính phủ, Elisa cảm thấy trống vắng, cô đơn. Rồi cuộc đời cô gái thay đổi mãi mãi khi cô và cộng sự Zelda khám phá ra một vụ thí nghiệm kinh hoàng - tạo ra thủy quái lốt người!</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sally Hawkins","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Stewart Arnott","avatar":""},{"name":"Nigel Bennett","avatar":""},{"name":"Lauren Lee Smith","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"Allegra Fulton","avatar":""},{"name":"John Kapelos","avatar":""},{"name":"Morgan Kelly","avatar":""},{"name":"Wendy Lyon","avatar":""},{"name":"Madison Fer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
