INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-than-dai-duong', 'Hung Thần Đại Dương', '47 Meters Down', 'https://phimimg.com/upload/vod/20231026-1/0017d3dd133ef87e1892e87ed9c4a232.jpg', 'https://phimimg.com/upload/vod/20231026-1/99ee331a8411b7f389025abc0e1299ae.jpg', '<p>Bộ phim kể về Hai chị em đi nghỉ mát ở Mexico bị mắc kẹt trong một cái lồng quan sát cá mập dưới đáy đại dương, với lượng oxy còn ít và những con cá mập trắng bơi vòng quanh cái lồng sắt, họ có ít hơn một giờ với lượng oxy còn lại để tìm ra cách thoát lên mặt nước...</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Cộng hoà Dominica', 0, '[{"name":"Mandy Moore","avatar":""},{"name":"Claire Holt","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Chris Johnson","avatar":""},{"name":"Yani Gellman","avatar":""},{"name":"Santiago Segura","avatar":""},{"name":"Axel Mansella","avatar":""},{"name":"Mayra Juárez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
