INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-25-cuoc-xam-lang-cua-nguoi-ngoai-hanh-tinh-shiriri', 'Shin - Cậu Bé Bút Chì 25: Cuộc Xâm Lăng Của Người Ngoài Hành Tinh Shiriri', 'Crayon Shin-chan: Invasion!! Alien Shiriri', 'https://phimimg.com/upload/vod/20231025-1/87a03840e378ffb03fcd933f7ac166dd.jpg', 'https://phimimg.com/upload/vod/20231025-1/8ba007bc0db3f6fcbdd8528393a5952c.jpg', '<p>Từ cuộc đến thăm bất ngờ của cậu bé người ngoài hành tinh Shiriri, mọi thứ trong gia đình Noraha đều bị xáo trộn. Bố mẹ của Shin bị tia sáng kỳ lạ phát ra từ Shiriri mà bỗng nhiên biến thành trẻ con. Để giải cứu bố mẹ, Shin cùng Shiriri phải lên đường phiêu dạt khắp nước Nhật để tìm bố của Shiriri, người duy nhất có khả năng vô hiệu hóa phép thuật ấy.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Akiko Yajima","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Mari Mashiba","avatar":""},{"name":"Tamao Hayashi","avatar":""},{"name":"Teiyu Ichiryusai","avatar":""},{"name":"Chie Sato","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Hiroyuki Miyasako","avatar":""},{"name":"Tôru Hotohara","avatar":""},{"name":"Mirai Shida","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
