INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ky-dieu', 'Điều Kỳ Diệu', 'Wonder', 'https://phimimg.com/upload/vod/20231024-1/af906c86adaf4c8c4a4d6cdb775ae7fa.jpg', 'https://phimimg.com/upload/vod/20231024-1/e8aa04e0e2f2ac542a11b5834ab99455.jpg', '<p>Điều Kỳ Diệu là câu chuyện cảm động về lòng tốt và nghị lực sống của Auggie – một cậu bé ngoan nhưng không may khuôn mặt bị dị dạng bẩm sinh do một chứng bệnh hiếm gặp. Auggie sống trong nỗi mặc cảm và hay gặp rắc rối tại trường khi bị bạn bè trêu chọc về ngoại hình khác thường. Liệu tình yêu thương và sự động viên từ gia đình có giúp Auggie có thêm sức mạnh vượt qua thử thách? Và liệu lòng tốt giữa con người với nhau có được đánh thức và xoa dịu nỗi đau ...</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jacob Tremblay","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Izabela Vidovic","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Millie Davis","avatar":""},{"name":"Bryce Gheisar","avatar":""},{"name":"Mandy Patinkin","avatar":""},{"name":"Danielle Rose Russell","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Elle McKinnon","avatar":""},{"name":"Ali Liebert","avatar":""},{"name":"Nadji Jeter","avatar":""},{"name":"Ty Consiglio","avatar":""},{"name":"Kyle Breitkopf","avatar":""},{"name":"James A Hughes","avatar":""},{"name":"Nicole Oliver","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324408);
