INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-cua-nhung-uoc-mo', 'Bậc Thầy Của Những Ước Mơ', 'The Greatest Showman', 'https://phimimg.com/upload/vod/20231023-1/190251b473e2363524ccf3ecff7ff6f1.jpg', 'https://phimimg.com/upload/vod/20231023-1/7b605bbdc79e963cf2d7380b5f84cd83.jpg', '<p>Bậc Thầy Của Những Ước Mơ là một bộ phim nhạc kịch lấy cảm hứng từ cuộc đời của diễn viên P.T. Barnum do Hugh Jackman thủ vai. Barnum là một diễn viên đại tài, có tầm nhìn xa trông rộng và đi từ con số không nhưng ông đã tự tay dựng nên “Vở diễn vĩ đại nhất thế giới” – một màn diễn hoành tráng, thể hiện được trí tưởng tượng thiên tài của ông vượt trên cả đời thực, đã làm mê đắm khán giả toàn cầu. Bộ phim có sự tham gia của Michelle Williams, Zac Efron và Zendaya.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Zendaya","avatar":""},{"name":"Keala Settle","avatar":""},{"name":"Yahya Abdul-Mateen II","avatar":""},{"name":"Natasha Liu Bordizzo","avatar":""},{"name":"Paul Sparks","avatar":""},{"name":"Sam Humphrey","avatar":""},{"name":"Austyn Johnson","avatar":""},{"name":"Cameron Seely","avatar":""},{"name":"Eric Anderson","avatar":""},{"name":"Ellis Rubin","avatar":""},{"name":"Skylar Dunn","avatar":""},{"name":"Daniel Everidge","avatar":""},{"name":"Radu Spin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
