INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-lego-batman', 'Câu Chuyện Lego Batman', 'The Lego Batman Movie', 'https://phimimg.com/upload/vod/20231023-1/59272e776cb42561111ac7882e2b28fe.jpg', 'https://phimimg.com/upload/vod/20231023-1/9d8f882ddd757634ae19028b8ca2c020.jpg', '<p>Nhờ sự nghiêm khắc của người cộng sự Alfred, triệu phú Bruce Wayne phải trở thành một người cha/người thầy bất đắc dĩ cho đứa con nuôi Dick Grayson. Để giải cứu thành phố thoát khỏi bàn tay phá hoại của The Joker, Bruce/ Batman sẽ phải rũ bỏ lối làm việc đơn độc, học cách hợp tác với Robin và lực lượng cảnh sát, đứng đầu là Uỷ viên Gordon.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2017, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Will Arnett","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Mariah Carey","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Conan O''Brien","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Doug Benson","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Riki Lindhome","avatar":""},{"name":"Jonah","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324408);
