INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ngoai-toc', 'Kẻ Ngoại Tộc', 'The Foreigner', 'https://phimimg.com/upload/vod/20231022-1/a6ac34966fa10524696487380cef3b78.jpg', 'https://phimimg.com/upload/vod/20231022-1/7cae750599a533c994314f3bab8a27eb.jpg', '<p>Trong phim Kẻ Ngoại Tộc, Quan – người đàn ông châu Á hiền lành, là chủ một tiệm cơm ở khu phố Tàu (London). Buổi sáng nọ như bao ngày, anh đưa đón cô con gái cưng đi học mà không ngờ rằng mình sắp mất cô bé vĩnh viễn vì một vụ đánh bom của quân khủng bố Ai-len. Tất cả những gì anh hy vọng sau đó là những kẻ thủ ác sẽ bị đưa ra ánh sáng, nhưng không, chính phủ từ chối công khai danh tính của chúng. Uất ức, tuyệt vọng, anh quyết định tự mình trả thù nhóm khủng bố trên. Đúng thời điểm đó, một nhân vật quan trọng là Liam Hennessy&nbsp; xuất hiện và tiết lộ âm mưu phức tạp đằng sau vụ việc.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Rory Fleck-Byrne","avatar":""},{"name":"Ray Fearon","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Orla Brady","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Lia Williams","avatar":""},{"name":"Dermot Crowley","avatar":""},{"name":"Stephen Hogan","avatar":""},{"name":"Liu Tao","avatar":""},{"name":"Katie Leung","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"Pippa Bennett-Warner","avatar":""},{"name":"Roberta Taylor","avatar":""},{"name":"Rufus Jones","avatar":""},{"name":"Niall McNamee","avatar":""},{"name":"Jor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
