INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-due-2', 'Hậu Duệ 2', 'Descendants 2', 'https://phimimg.com/upload/vod/20231022-1/681033dbee242206607a5723107331ec.jpg', 'https://phimimg.com/upload/vod/20231022-1/d2bfcb606cff96927c9201b8bf8f2830.jpg', '<p>Khi áp lực trở thành hoàng gia trở nên quá lớn đối với Mal, cô quay trở lại Isle of the Lost, nơi kẻ thù không đội trời chung của cô là Uma, con gái của Ursula, đã chiếm lấy vị trí tự xưng là nữ hoàng.</p>', 'Full', 1, 'single', 'completed', 21, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dove Cameron","avatar":""},{"name":"Cameron Boyce","avatar":""},{"name":"Sofia Carson","avatar":""},{"name":"Booboo Stewart","avatar":""},{"name":"Mitchell Hope","avatar":""},{"name":"Brenna D''Amico","avatar":""},{"name":"Melanie Paxson","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Thomas Doherty","avatar":""},{"name":"Dylan Playfair","avatar":""},{"name":"Dianne Doan","avatar":""},{"name":"Jedidiah Goodacre","avatar":""},{"name":"Zachary Gibson","avatar":""},{"name":"Anna Cathcart","avatar":""},{"name":"Dan Payne","avatar":""},{"name":"Keegan Connor Tracy","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
