INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mam-song-hiem-hoa', 'Mầm Sống Hiểm Họa', 'Life', 'https://phimimg.com/upload/vod/20231022-1/4028af712205e2e37b36cfdd38f468d0.jpg', 'https://phimimg.com/upload/vod/20231022-1/5d3a8ffa441e825eaea04a56f02954e7.jpg', '<p>Nội dung phim về sáu phi hành gia trên con tàu không gian của một trạm nghiên cứu mẫu vật thu thập được từ sao Hỏa, được cho là có thể cung cấp bằng chứng cho cuộc sống ở ngoài trái đất trên hành tinh Đỏ. Các phi hành đoàn nghiên cứu và cho rằng mẫu vật này có chứa một lượng lớn các đơn bào sinh vật – ví dụ đầu tiên của sự sống tồn tại bên ngoài Trái đất.</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Elizabeth Vargas","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Olga Dihovichnaya","avatar":""},{"name":"Ariyon Bakare","avatar":""},{"name":"Naoko Mori","avatar":""},{"name":"Haruka Kuroda","avatar":""},{"name":"Camiel Warren-Taylor","avatar":""},{"name":"Alexandre Nguyen","avatar":""},{"name":"Hiu Woong-Sin","avatar":""},{"name":"David Muir","avatar":""},{"name":"Allen McLean","avatar":""},{"name":"Jesus Del Orden","avatar":""},{"name":"Leila Grace","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
