INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ferdinand-phieu-luu-ky', 'Ferdinand Phiêu Lưu Ký', 'Ferdinand', 'https://phimimg.com/upload/vod/20231023-1/a90d76c7516bfb66d1f7d4eaaf7a3f0f.jpg', 'https://phimimg.com/upload/vod/20231023-1/23912f602075d53bcd4af11170005641.jpg', '<p>FERDINAND là câu chuyện về một chú bò to xác trong một thế giới nhỏ bé. Vì ngoại hình quá khổ của mình, chú bò biến thành sinh vật nguy hiểm trong mắt mọi người. Ferdinand bị chia cắt khỏi gia đình và được đưa đến một nơi thật xa xôi. Chú bò tội nghiệp gặp gỡ những người bạn &quot;hoàn cảnh&quot; bao gồm một chú dê quái chiêu, bộ ba siêu nhím tưng tửng và một đàn bò sặc sỡ màu sắc. Và rồi hàng loạt chuyến phiêu lưu điên rồ nhất bắt đầu. Ferdinand cùng đồng bọn chu du khắp các thành phố và vùng quê của xứ sở Tây Ban Nha.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cena","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Peyton Manning","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Miguel Ángel Silvestre","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Jerrod Carmichael","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Raúl Esparza","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Juanes","avatar":""},{"name":"Boris Kodjoe","avatar":""},{"name":"Karla Martínez","avatar":""},{"name":"Sally Ph","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
