INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('valerian-va-thanh-pho-ngan-hanh-tinh', 'Valerian và Thành Phố Ngàn Hành Tinh', 'Valerian and the City of a Thousand Planets', 'https://phimimg.com/upload/vod/20231022-1/0347076c1e01c6f11ac2068be06ea868.jpg', 'https://phimimg.com/upload/vod/20231022-1/ecbe08c4cca312450d0abfe42367ed64.jpg', '<p>Bối cảnh được dàn dựng vào khoảng thế kỷ 28, khi xã hội loài người rất phát triển và sẽ sinh sống trên không gian. Thành phố Ngàn Hành Tinh nói tới ở đây là Alpha – một trạm không gian khổng lồ, có vô vàn các sinh vật từ các hành tinh khác nhau cùng chung sống. Tuy nhiên có một thế lực đen tối đe dọa trạm không gian này, ảnh hưởng đến an nguy vũ trụ, nên bộ Quốc phòng đã cử 2 đặc vụ: Valerian và Laureline truy tìm thủ phạm và gìn giữ trật tự, lãnh thổ của loài người trên trung tâm này.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Dane DeHaan","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Rihanna","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Herbie Hancock","avatar":""},{"name":"Kris Wu","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Ola Rapace","avatar":""},{"name":"Alain Chabat","avatar":""},{"name":"Thom Findlay","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Aymeline Valade","avatar":""},{"name":"Sasha Luss","avatar":""},{"name":"Pauline Hoarau","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
