INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-dich-song-cua-mot-chu-cho', 'Mục Đích Sống Của Một Chú Chó', 'A Dog''s Purpose', 'https://phimimg.com/upload/vod/20231023-1/8e8e2ac8caca68219abeeeea04a7f4aa.jpg', 'https://phimimg.com/upload/vod/20231023-1/dc533b388a80068df76af9ee7eee20fa.jpg', '<p>Một con chó trải qua bốn kiếp sống với những người chủ khác nhau trong những khoảng thời gian khác nhau. Trong suốt cuộc hành trình này, anh ta dần dần hiểu ra mục đích thực sự của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Josh Gad","avatar":""},{"name":"K.J. Apa","avatar":""},{"name":"Britt Robertson","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Peggy Lipton","avatar":""},{"name":"Juliet Rylance","avatar":""},{"name":"Luke Kirby","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Kirby Howell-Baptiste","avatar":""},{"name":"Pooch Hall","avatar":""},{"name":"Logan Miller","avatar":""},{"name":"Gabrielle Rose","avatar":""},{"name":"Caroline Cave","avatar":""},{"name":"Nicole LaPlaca","avatar":""},{"name":"Michael Patric","avatar":""},{"name":"Michael Bofshever","avatar":""},{"name":"Primo Allon","avatar":""},{"name":"Kalyn","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
