INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-vua-arthur-thanh-guom-trong-da', 'Huyền Thoại Vua Arthur: Thanh Gươm Trong Đá', 'King Arthur: Legend of the Sword', 'https://phimimg.com/upload/vod/20231023-1/019853d6539772b018618075ebcdfc74.jpg', 'https://phimimg.com/upload/vod/20231023-1/13edb234f7c58921eae26f4b808b2b41.jpg', '<p>Chính tại những khu ổ chuột của thành Luân Đôn thời Trung Cổ, Arthur lớn lên như một kẻ vô danh, tự do và nghèo khổ. Không ai ngờ được, anh là người được định mệnh sắp đặt trở thành chủ nhân của thanh gươm huyền thoại Excalibur. Phát hiện ra dòng máu vương quyền của mình, Arthur nhanh chóng bị cuốn vào cuộc đại chiến ma thuật chống lại tên vua độc tài Vortigern với hi vọng đem lại hoà bình cho vương quốc.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Hunnam","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Astrid Bergès-Frisbey","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Kingsley Ben-Adir","avatar":""},{"name":"Neil Maskell","avatar":""},{"name":"Craig McGinlay","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"Freddie Fox","avatar":""},{"name":"Mikael Persbrandt","avatar":""},{"name":"Peter Ferdinando","avatar":""},{"name":"Geoff Bell","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Katie McGrath","avatar":""},{"name":"Lorraine Bruc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
