INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-than-dong', 'Cô Bé Thần Đồng', 'Gifted', 'https://phimimg.com/upload/vod/20231020-1/c8edaaf8fb7e02985246c32f238ddcb0.jpg', 'https://phimimg.com/upload/vod/20231020-1/f36bc5f1c144ad875b5619bb00ae2f75.jpg', '<p>Frank - người đàn ông độc thân và một mình nuôi Mary - cô con gái của người em đã qua đời. Hai cậu cháu có một cuộc sống bình yên, đơn giản và hạnh phúc cho đến khi tài năng của cô bé được phát hiện. Ngay sau đó, Evelyn - mẹ của Frank xuất hiện nhằm mục đích muốn đưa bé đến một môi trường học tập cao cấp hơn. Tuy nhiên, Frank phản đối kịch liệt vì di nguyện của người em gái là giúp bé Mary có một cuộc sống bình thường và được làm một đứa trẻ đúng nghĩa. Mọi chuyện bắt đầu trở nên phức tạp khi Evelyn đệ đơn ra tòa giành quyền nuôi bé Mary và có vẻ như thần chiến thắng không hề mỉm cười với Frank...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Evans","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Julie Ann Emery","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Jona Xiao","avatar":""},{"name":"John Finn","avatar":""},{"name":"John M. Jackson","avatar":""},{"name":"Candace B. Harris","avatar":""},{"name":"Kelly Collins Lintz","avatar":""},{"name":"Jon Sklaroff","avatar":""},{"name":"Brody Rose","avatar":""},{"name":"Michael Ken","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
