INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-va-quai-vat-2017', 'Người Đẹp và Quái Vật', 'Beauty and the Beast', 'https://phimimg.com/upload/vod/20231019-1/ec35a80e39626b4653784a429b8360eb.jpg', 'https://phimimg.com/upload/vod/20231019-1/ddeb6be1f5078b5653c3d6e260e69e19.jpg', '<p>Một chàng hoàng tử trẻ sống trong một tòa lâu đài nguy nga tráng lệ. Chàng có tất cả nhưng kiêu ngạo, tàn nhẫn và không biết đến tình yêu thương...&nbsp; Chàng sẽ sống ra sao khi bị biến thành một con quái vật xấu xí?&nbsp; Lời nguyền chỉ được hóa giải, khi chàng học được cách yêu ai đó, và cũng được người đó đáp lại trước khi cánh hoa hồng cuối cùng rơi xuống!</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Watson","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Hattie Morahan","avatar":""},{"name":"Haydn Gwynne","avatar":""},{"name":"Gerard Horan","avatar":""},{"name":"Ray Fearon","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Nathan Mack","avatar":""},{"name":"Audra McDonald","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Clive Rowe","avatar":""},{"name":"Thomas Padden","avatar":""},{"name":"Rita D","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
