INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly', 'Liên Minh Công Lý', 'Justice League', 'https://phimimg.com/upload/vod/20231019-1/d571e3972a8f40e47c342daa1c129dec.jpg', 'https://phimimg.com/upload/vod/20231019-1/0ee36367ccf53c1c471f0b3c08ac1354.jpg', '<p>Justice League hay còn được biết đến với cái tên Liên Minh Công Lý, là tập hợp những siêu anh hùng mang trong mình sức mạnh phi thường để giải cứu thế giới khỏi những thế lực đen tối trong vũ trụ DC. Lần này, nhân loại phải đối mặt với tên ác quỷ vô cùng tàn độc – Steppenwolf. Hắn là một trong những tay sai đắc lực của Darksied – một ác nhân và cũng chính là kẻ thù lớn nhất của Liên Minh Công Lý.&nbsp; Steppenwolf đã phô trương năng lực siêu phàm của mình, gieo rắc nỗi sợ hãi và bóng tối tới xứ Themyscira – quê hương của Wonder Woman và loài người.</p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Jason Momoa","avatar":""},{"name":"Ray Fisher","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Lisa Loven Kongsli","avatar":""},{"name":"Ingvar E. Sigurðsson","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Sergi Constance","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678