INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-xxx-phan-don', 'Điệp Viên xXx: Phản Đòn', 'xXx: Return of Xander Cage', 'https://phimimg.com/upload/vod/20231019-1/5adb23c87f0f615321d096577e569a3b.jpg', 'https://phimimg.com/upload/vod/20231019-1/c2bdf7d7163bd3a373ef7d10dcea7a83.jpg', '<p>xXx: Return of Xander Cage là phần thứ ba trong loạt phim về điệp viên xXx. Bộ phim kể về những nhiệm vụ của Xander Cage (biệt danh xXx - do Vin Diesel thủ vai), anh chàng nghiện thể thao mạo hiểm được chính phủ tuyển dụng để trở thành đặc vụ. Lần này, Xander Cage có cuộc chạm trán với tay giang hồ Xiang (Chân Tử Đan) và đội quân tinh nhuệ của hắn trong cuộc chiến giành thiết bị công nghệ cao - Pandora&quot;s Box. Trong quá trình chiêu mộ biệt đội làm việc cùng mình, Xander Cage vô tình vướng vào âm mưu hiểm độc có liên quan đến quan chức cấp cao trong chính phủ nhiều nước trên thế giới...</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"Tony Jaa","avatar":""},{"name":"Kris Wu","avatar":""},{"name":"Hermione Corfield","avatar":""},{"name":"Michael Bisping","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Tony Gonzalez","avatar":""},{"name":"Ariadna Gutiérrez","avatar":""},{"name":"Andrey Ivchenko","avatar":""},{"name":"Nicky Jam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
