INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-khe-uoc', 'Quái Vật Không Gian: Khế Ước', 'Alien: Covenant', 'https://phimimg.com/upload/vod/20231018-1/ffd4d3515e5fd21b17f49fed164f0f8a.jpg', 'https://phimimg.com/upload/vod/20231018-1/fd40a924f317249d52d6d3f1fac232ef.jpg', '<p>Alien: Covenant 2017 (Quái Vật Không Gian: Khế Ước) nói về Ridley Scott đã quay lại với vũ trụ của Alien với phần tiếp nối mang tên Covenant này. Đây là chương 2 của một bộ 3 phim được bắt đầu bằng Prometheus (Bí Ẩn Hành Tinh Chết) và có liên quan đến các bản phim khoa học viễn tưởng nổi tiếng năm 1979. Nội dung phần này kể về con tàu thám hiểm Convenant đáp đến một hành tinh xa xôi nằm ở rìa thiên hà. Đoàn phi hành gia trên tàu cứ ngỡ tìm được một thiên đường cho chuyến thám hiểm vũ trụ, không ai ngờ rằng đó là một thế giới tối tăm đầy rẫy nguy hiểm mà cư dân duy nhất là “người tổng hợp” David_người sống sót từ chuyến thám hiểm kinh hoàng của Prometheus.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Jussie Smollett","avatar":""},{"name":"Callie Hernandez","avatar":""},{"name":"Amy Seimetz","avatar":""},{"name":"Nathaniel Dean","avatar":""},{"name":"Alexander England","avatar":""},{"name":"Benjamin Rigby","avatar":""},{"name":"Uli Latukefu","avatar":""},{"name":"Tess Haubrich","avatar":""},{"name":"Lorelei King","avatar":""},{"name":"Goran D. Kleut","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324408);
