INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-vat-khong-gian-khe-uoc', 'Quái Vật Không Gian: Khế Ước', 'Alien: Covenant', 'quái vật không gian: khế ước alien: covenant michael fassbender katherine waterston billy crudup danny mcbride demián bichir carmen ejogo jussie smollett callie hernandez amy seimetz nathaniel dean alexander england benjamin rigby uli latukefu tess haubrich lorelei king goran d. kleut ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-di-san-de-lai', 'Lưỡi Cưa: Di Sản Để Lại', 'Jigsaw', 'https://phimimg.com/upload/vod/20231017-1/c095605aa94a50906ebcc170924b26e8.jpg', 'https://phimimg.com/upload/vod/20231017-1/c17b0860d196a072808b9d4ecfdd41ec.jpg', '<p>Sau bảy năm đứt quãng kể từ Saw 3D: The Final Chapter (2010), tập thứ tám của thương hiệu phim kinh dị tra tấn - chém giết Saw đã trở lại. Loạt phim Saw luôn khiến người xem mất ăn mất ngủ không chỉ bởi những thước phim máu me gớm ghiếc mà còn bởi con rối Billy đáng sợ. Billy được kẻ sát nhân &quot;chính nghĩa&quot; Jigsaw điều khiển, luôn xuất hiện trên chiếc xe ba bánh và phát giọng nói điện tử rè rè gây ám ảnh... Đây có thể là phần thứ 8 của loạt phim Saw, nhưng không có nghĩa là chúng ta đã thấy người cuối cùng đằng sau mọi sự việc. Chắc chắn, một vài cái chết chính trong loạt phim có thể đã cản trở cốt truyện cho một số nhân vật tương lai, nhưng có rất nhiều chi tiết có thể sẽ được sử dụng được để xây dựng nên Jigsaw (2017). Ai biết di sản hung bạo mà Jigsaw để lại sẽ đưa chúng ta đến đâu?</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Passmore","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Hannah Anderson","avatar":""},{"name":"Clé Bennett","avatar":""},{"name":"Laura Vandervoort","avatar":""},{"name":"Paul Braunstein","avatar":""},{"name":"Mandela Van Peebles","avatar":""},{"name":"Brittany Allen","avatar":""},{"name":"Josiah Black","avatar":""},{"name":"Edward Ruttle","avatar":""},{"name":"Michael Boisvert","avatar":""},{"name":"Sam Koules","avatar":""},{"name":"Troy Feldman","avatar":""},{"name":"Shaquan Lewis","avatar":""},{"name":"Esther Thibault","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324408);
