INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luoi-cua-di-san-de-lai', 'Lưỡi Cưa: Di Sản Để Lại', 'Jigsaw', 'lưỡi cưa: di sản để lại jigsaw matt passmore tobin bell callum keith rennie hannah anderson clé bennett laura vandervoort paul braunstein mandela van peebles brittany allen josiah black edward ruttle michael boisvert sam koules troy feldman shaquan lewis esther thibault ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-cua-ngoi-nha', 'Bóng Ma Của Ngôi Nhà', 'Phantom of the House', 'null', 'https://phimimg.com/upload/vod/20231014-1/bdb4cb22a44564d0ec6b020fe6ef4d1f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">&quot;The Phantom of the Tricky House&quot; kể về câu chuyện của Xiaolian (Yaoyao), người được cha mẹ cô sống trong biệt thự Wu trong thời Trung Hoa Dân Quốc, vì cô đã bị Master Wu lạm dụng và bức hại trong một thời gian dài, dẫn đến sự chia rẽ nhân cách và rơi vào một nhân cách bốn mặt. Do sự thông đồng giữa lão sư Ngô và bọn cướp, khi Tiểu Liên sắp bị dập tắt, cô đã được quản gia cũ của nhà Ngô (Lý Tử Hùng thủ vai) giải cứu. Lúc này, Xiaolian đã mất lòng và phát điên, và sau khi biết về trải nghiệm bi thảm của em gái, anh trai cô, người đang học tâm lý học ở nước ngoài, đã quyết định trở về Trung Quốc để giúp Xiaolian trị liệu tâm lý. Hắn thôi miên Tiểu Liên, đưa Tiểu Liên trở lại sân nhà họ Ngô một lần nữa, khôi phục lại cảnh giam cầm ngay tại chỗ, Tiểu Liên, dưới sự giúp đỡ của anh trai và quản gia cũ của nhà họ Ngô, đánh bại cơn điên, tìm lại chính mình, khôi phục sức khỏe.</span></p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Su Kexin","avatar":""},{"name":"Ma Yingying","avatar":""},{"name":"Liu Jie","avatar":""},{"name":"Li Zixiong","avatar":""},{"name":"Xu Yulan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324408);
