INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-thieu-nu-ba-dao', 'Bọn Thiếu Nữ Bá Đạo', 'The Aggressive Girls Team', 'https://phimimg.com/upload/vod/20231014-1/2962db7a232628a066c6d1445a95444e.jpg', 'https://phimimg.com/upload/vod/20231014-1/e433a54af9788a86dc7d64c0356a4dd1.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim có sự tham gia của nam diễn viên quyền lực Trương Tử Duệ, nữ thần nhà nổi tiếng trên mạng Chen Da Rong và Sun Shuang, trong đó Trương Tử Duệ đã đóng những vai nổi tiếng như &quot;Chiến binh áo giáp&quot;, và Sun Shuang cũng đã thể hiện tốt trong &quot;Another Me in the World&quot;. Trong phim, ba tên xã hội đen đường phố gặp phải sự thay đổi giới tính, và trên hành trình bị truy đuổi và giết chết, họ gặp thám tử tư pháp. Khi phiên bản nữ của Mu Chun, do Wang Yihang thủ vai trong phim, bị bắt cóc bởi một băng đảng xấu, Ah Ying, với tư cách là con trai và con gái của sông hồ, đã thể hiện ý thức nghiêm túc về sông hồ, và cuối cùng đã cản trở kế hoạch xấu xa của thế lực thế giới ngầm.</span></p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ziye","avatar":""},{"name":"Chen Da Rong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
