INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tieu-tieu', 'Bố Tiểu Tiểu', 'Dad''s Metamorphosis', 'https://phimimg.com/upload/vod/20231014-1/0908172a686809989dfa4803d0709a5c.jpg', 'https://phimimg.com/upload/vod/20231014-1/390e60507a5dafc69239c59b02839e3d.jpg', '<p>Liu Dalei, do Liu Xiaoguang thủ vai, là một người đưa thư trung niên đang chờ chết, khi anh sắp được gặp lại bà chủ xinh đẹp Luo Xiaomei (do Zhao Haiyan thủ vai), đứa con trai thất lạc từ lâu của ông là Xiaoxiao (do Wang thủ vai). Han) bất ngờ xuất hiện. Hai cha con đã nhiều năm không gặp bị ghẻ lạnh, để loại bỏ sự phản kháng của con trai đối với mình, Liu Dalei đã cố gắng hết sức để biểu diễn trượt băng, đánh bóng tuyết, đến công viên giải trí và các bộ phim truyền hình khác. , anh ta gây rắc rối vì cờ bạc, và con trai anh ta đã nhìn thấy mặt xấu xí của anh ta. Đối mặt với câu hỏi ngây thơ của con trai &quot;Bố có phải là người xấu không?&quot;, Liu Dalei, người muốn làm gương cho một người cha tốt, sẽ thay đổi hình ảnh của mình trong lòng con trai như thế nào, và bộ phim tình cảm của anh với Luo Xiaomei sẽ phát triển như thế nào...</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Xiaoguang","avatar":""},{"name":"Guan Tingna","avatar":""},{"name":"Zhao Haiyan","avatar":""},{"name":"Wang Xiaobao","avatar":""},{"name":"Sun Lirong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
