INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hoa-bat-vuong-chu-tich-song-bai', 'Bông Hoa Bát Vương Chủ Tịch Sòng Bài', 'The Boss''s Love', 'https://phimimg.com/upload/vod/20231014-1/9de801eaae1a80a8b5955a39ac2759bc.jpg', 'https://phimimg.com/upload/vod/20231014-1/8f121e13590e3cb05909272cc84e5509.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Doanh nhân giàu có Wen Ruhu đã xúc phạm mọi người, và để đảm bảo rằng cô con gái duy nhất Wen Wan không bị tổn hại, ông đã gửi con gái của anh trai Thái Lan Li Kaishi là Thirteen Mei trở lại Trung Quốc để bảo vệ, đồng thời ký hợp đồng bảo hiểm với chủ tịch độc đoán Liang Shan để bảo vệ sự an toàn của Wen Wan. Trên thực tế, đây là mưu đồ của Lý Khai Thạch và Ôn Nhược Hồ, bọn họ lợi dụng Ôn Loan để lừa phí bảo hiểm mặc định của Lương Sơn, nhưng không ngờ rằng Thập Tam Mai và Lương Sơn lại hòa thuận và có tình cảm, hai anh em Ôn Hạc Lệ cũng bị lật úp vì chia sẻ hàng hóa bị đánh cắp không đồng đều...</span></p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yigui","avatar":""},{"name":"Xie Mingyu","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Zhou Guobin","avatar":""},{"name":"Xiaolong Ding","avatar":""},{"name":"Zhang Xiao''ang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
