INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bup-be-robot', 'Búp Bê Ro-bot', 'The Robot', 'https://phimimg.com/upload/vod/20231014-1/0451a09c604a0e5da0d29225247e0c7a.jpg', 'https://phimimg.com/upload/vod/20231014-1/0b50ff7abf4b2a01199024f39cd1d7ae.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về câu chuyện trái đất 50 năm sau, những người trẻ độc thân bị truy nã và bức hại bởi các bức tượng nhỏ trên khắp thế giới, và thảm họa này bắt nguồn từ việc nam chính Ah Kun quá nghiện hai chiều và trò chơi khi còn trẻ và phát minh ra các bức tượng nhỏ, nhưng bất ngờ trong quá trình nâng cấp và thay thế các bức tượng nhỏ, các nhân vật bắt đầu thức tỉnh và tạo ra một chúa tể COS với ý thức tự chủ. Để chấm dứt thảm họa này, Ah Kun đã tạo ra nhân vật cấp cao Sita và dịch chuyển cô đến bản thân 22 tuổi của mình, dạy bản thân trẻ hơn của mình yêu và ngừng đắm chìm trong thế giới ảo, do đó đảo ngược tương lai và chấm dứt thảm họa này. Cùng lúc Sita bước vào cánh cổng không-thời gian, COS Overlord cũng xông vào...</span></p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Luo Mingjie","avatar":""},{"name":"Ma Yuetong","avatar":""},{"name":"Liu Nanxi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324408);
