INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-phe-cat-star', 'Cà phê Cat Star', 'Meow Star Coffee', 'https://phimimg.com/upload/vod/20231014-1/910f4067219313a3664778aa4e652373.jpg', 'https://phimimg.com/upload/vod/20231014-1/8e84ec07150b1fba909f51f7adde6330.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Meow Star sắp phải đối mặt với cuộc khủng hoảng hủy diệt, và thủ lĩnh Meow Sen gửi tín hiệu đến Meow Star trên Trái đất rằng nó có thể di cư. Vào thời điểm đó, con tàu thám hiểm mang theo một số lượng lớn hạt giống sự sống của chủng tộc chúng ta, nhưng do trật khớp thời gian, chúng không thể nở trên hành tinh này, vì vậy chúng bắt đầu chờ đợi, chờ đợi thời điểm sự sống Blue Star tiến hóa trùng với thời gian của Chiều không gian Meow và chiếm giữ hành tinh. Meow Sen đang tìm kiếm những con mèo có thể biến thành hình dạng con người, lây nhiễm tất cả chúng và lây lan gen khắp Blue Star. Tuy nhiên, Fawn, Soybean, Sasa, Arashi và người quản lý cửa hàng cuối cùng đã tìm thấy Meow Mori và đánh bại anh ta để ngăn chặn sự lây nhiễm virus.</span></p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Junchen","avatar":""},{"name":"Yan Yuxin","avatar":""},{"name":"Yao Xinyan","avatar":""},{"name":"Chen Guanning","avatar":""},{"name":"Zhao Yanru","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
