INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cau-tha', 'Cái Chết Cẩu Thả', 'A Hasty Death', 'null', 'https://phimimg.com/upload/vod/20231014-1/405ebf20dce822b32517af124017eb6b.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trần Phi hối hận vì đã ly hôn với Vương Miểu, đuổi theo trên đường, chết trong tai nạn xe hơi, kỳ diệu nhìn thấy một người bất tử bối rối đóng vai một người mới làm quen với thiên thần, vì vậy Trần Phi muốn để thiên sứ giúp hồi sinh, bởi vì môi trường như khói bụi càng ngày càng tồi tệ, và con người ngày càng trở nên không có niềm tin và linh hồn, vì vậy những người bất tử thiếu năng lượng tích cực, vì vậy họ quyết định để Trần Phi du hành xuyên thời gian để phục sinh!</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trần Phi sống lại ở Cục Dân sự, nhưng đã trễ một bước, hai người vừa ký thỏa thuận ly hôn, Trần Phi cũng phát hiện Vương Miểu lần này không quan tâm đến chuyện ly hôn. Cùng một nơi, cùng một chiếc xe, cùng một tài xế. Trần Phi bình tĩnh nghĩ rằng mình vẫn có thể sống lại, và khi anh ta liên tục thúc giục các thiên thần giúp anh ta sống lại, giọng nói của thiên thần đến từ bầu trời: Bạn chỉ có hai cơ hội để được phục sinh, và trong cuộc sống này, mọi người sống ít hơn một ngày! Những gì bị bỏ lỡ là bỏ lỡ...</span></p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Xin","avatar":""},{"name":"Li Jialiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
