INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-cuoc-phieu-luu-tinh-yeu-cua-otaku-man', 'Câu Chuyện Về Cuộc Phiêu Lưu Tình Yêu Của Otaku Man', 'The Story of Otaku Man''s Love Adventures', 'null', 'https://phimimg.com/upload/vod/20231013-1/14a5babfbb256c2852482af4dcc1c50e.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">&quot;Goddess Decoder&quot; được sản xuất bởi Hồ Nam Image Maker Space, đồng sản xuất bởi Hồ Nam Qiyuan Culture Media Co., Ltd., và được phân phối độc quyền bởi Beijing Qijiu Times Film and Television Culture Communication Co., Ltd. Bộ phim kể về câu chuyện của otaku A Anh ấy một ngày nọ đột nhiên nhận được một trò chơi VR về tu luyện tình yêu, với tư cách là một bậc thầy trò chơi, A Anh ấy đang mở khóa sự ưu ái với từng cô gái cùng một lúc, nhưng đột nhiên phát hiện ra rằng các cô gái trong trò chơi thực sự xuất hiện bên cạnh anh ấy từng người một!</span></p>', 'Full', 1, 'single', 'completed', 12, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huang Min''an","avatar":""},{"name":"Xiao Yao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
