INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-cuu-sinh-xong-khoi-cam-khu', 'Con đường cứu sinh : Xông khỏi cấm khu', 'The Road to Survival', 'https://phimimg.com/upload/vod/20231013-1/d7b4af9e0e9f1d6238b51627f1f2f5a6.jpg', 'https://phimimg.com/upload/vod/20231013-1/2f532048159da2cb76f407085b2fa1d5.jpg', '<p>Bộ phim chủ yếu kể về câu chuyện của hai cặp vợ chồng đi nghỉ ở rừng nguyên sinh để săn bắn, David, anh trai của Carrie, vô tình đi vào vùng cấm khi đang săn mồi và gặp nguy hiểm. Đi tìm David, lúc này nỗi sợ hãi ập đến, tính tò mò và tinh thần mạo hiểm đã khiến họ liều lĩnh tiến vào khu vực cấm. Trong khu vực cấm, anh trai và bạn bè của Kari không may nhiễm virus và mất nhân tính, Kari gặp nguy hiểm... Diễn viên Drago Lazetich, người đóng vai anh trai nữ chính Kari trong phim, là nhà sản xuất, diễn viên, đạo diễn hành động Hollywood . , đã hợp tác với các diễn viên nổi tiếng như Thành Long, Mã Y Lợi, Chen Kun, Zhang Yishan và tham gia vào các bộ phim như &quot;Fearless&quot; và &quot;The Lion from Heaven&quot;. Kali do một người đẹp lai Trung - Thái, chuyển giới, tốt nghiệp Học viện Điện ảnh Vancouver Thượng Hải thủ vai, diễn xuất của họ trong phim khiến nhiều khán giả mong chờ. Điều đáng nói là &quot;Long 4 Survival: Out of the Zone&quot; là một chủ đề phiêu lưu rừng hiếm hoi trên phim, cũng là tác phẩm phiêu lưu rừng đầu tiên trên phim trực tuyến, kết hợp hoàn hảo giữa khám phá rừng, cốt truyện hồi hộp và kinh dị sinh hóa. David bị nhiễm virus, anh dần mất đi lý trí, dưới tiếng gọi của tình cảm gia đình, anh vẫn duy trì lý trí nhỏ bé mà mình có.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324408);
