INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-chay-tron', 'Cô Dâu Chạy Trốn', 'Runaway Bride', 'https://phimimg.com/upload/vod/20231013-1/668e0bce4c68d583f6ecfde79c0e87c1.jpg', 'https://phimimg.com/upload/vod/20231013-1/da4723ee5b0c5d5870c47cb18dd38c02.jpg', '<p>Cao Thiên Dương, một thanh niên lớn tuổi lái taxi đã vô tình kéo Ren Lu, người đang chạy trốn khỏi hiện trường đám cưới, trên hành trình đến nơi lý tưởng không tưởng của mình - Route 99. Sau bao gian khổ, cuối cùng cả hai cũng đến được đích. Lúc này, cả hai nhận thấy tình cảm dành cho nhau ngày càng lớn dần, cuối cùng cả hai đã vượt qua mọi khó khăn và cuối cùng đôi tình nhân cũng kết hôn.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
