INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-dau-chay-tron', 'Cô Dâu Chạy Trốn', 'Runaway Bride', 'cô dâu chạy trốn runaway bride  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-kieu-ky-do-suc', 'Cô Bé Kiêu Kỳ Đọ Sức', 'Wrestle for Love', 'https://phimimg.com/upload/vod/20231013-1/7fdb0b0ba3e8bca979ff55d168293a3d.jpg', 'https://phimimg.com/upload/vod/20231013-1/b87d7c91e4c98ffacac2db5a5fc1435b.jpg', '<p>Nam tước Kitagawa Kishi đến câu lạc bộ đấu vật để tìm &quot;kẻ sát nhân&quot; vì vụ việc em gái anh bị đẩy xuống cầu thang. Bộ trưởng Ma Tangtang bước tới đấu tranh nhưng bị hách dịch và lạnh lùng xa lánh, hai người nhìn nhau chán ghét. Kitagawa nghi ngờ Ma Tangtang là kẻ giết người, để bảo vệ công lý, anh tham gia câu lạc bộ đấu vật khi còn là sinh viên, hai người đối đầu nhau và mâu thuẫn ngày càng leo thang. Cùng lúc đó, kẻ sát nhân thực sự Lin Feng đã chăm sóc em gái mình đầy tội lỗi, em gái anh, người đã yêu đơn phương Lin Feng, rất thích thú và giấu nó vô điều kiện. Ma Tangtang đáng thương đã bị buộc tội oan và bị tra tấn, và mối quan hệ của họ ngày càng bền chặt hơn trong cuộc chiến trí tuệ và lòng dũng cảm. Kitagawa dần dần từ bỏ sự nghi ngờ của mình. Khi em gái cô biết Kitagawa sắp cầu hôn Ma Tangtang, cô trở nên ghen tị và nói dối rằng Ma Tangtang là kẻ sát nhân. Bei Chuan&#39;an và Ma Tangtang xảy ra mâu thuẫn và chia tay trong đau khổ. Sau khi biết được sự thật, Mã Đường Đường lựa chọn rời đi để bảo vệ Lâm Phong và em gái. Sau khi Kitagawa biết được sự thật, anh đã hối hận. Vào ngày thi đấu, Mã Đường Đường xuất hiện bất ngờ. Hai người nhìn nhau và mỉm cười.</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
