INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-de-thuong-quyet-chien-giang-ho', 'Cô Gái Dễ Thương Quyết Chiến Giang Hồ', 'The Girl with Super Ability', 'https://phimimg.com/upload/vod/20231013-1/3b70b3a4cad72aeb2b9e235d85d157a3.jpg', 'https://phimimg.com/upload/vod/20231013-1/7e735e9226058202dd2f0f421db314a3.jpg', '<p>Sau hàng loạt sự cố tự gây ra, âm mưu của Smith bị vạch trần và cuộc đọ sức giữa các băng đảng là điều khó tránh khỏi. Lấy cảm hứng từ công lý, ba người họ, Zhuang Xixi, quyết định giúp Yuxuan giải cứu Jia Jia. K Long, người đã nhìn thấu danh tính thực sự của Jiajia, đã chọn giao dịch với Smith tại căn cứ quê hương của mình, Yuxuan, người yếu đuối và yếu đuối, không những không giải cứu được Jiajia mà còn phải ngồi tù. của tà ác và K Long Khi binh lính gặp nhau, trời tối và đất tối. Zhuang Xixi và ba người khác xông lên giữa chừng đã lật ngược tình thế trận chiến. Yuxuan trốn thoát cùng Jiajia và Xixi rồi quay lại giải cứu K Long. K Long cảm kích và đổi ý và gia nhập Yuxuan và những người khác. Cuối cùng, dưới sự chỉ đạo của Yuxuan. cuộc tấn công mạnh mẽ của cảnh sát, Đánh bại tên xã hội đen Ý. Vụ bắt cóc đã được tuyên bố kết thúc, nhưng câu chuyện của họ vẫn tiếp tục...</p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yun Xiang","avatar":""},{"name":"Gong Fangni","avatar":""},{"name":"He Xie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
