INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nguoi-yeu-a-dao-ma-nu-cua-toi', 'Cô Người Yêu Ả Đào Ma Nữ Của Tôi', 'My Magic Girlfriend', 'null', 'https://phimimg.com/upload/vod/20231013-1/80c27b206a6d650d511f957787caf5b2.jpg', '<p>Xinwei là một robot được người ngoài hành tinh cấy ký ức của Shu Yao và giao cho trái đất thực hiện mệnh lệnh, mục đích là tìm ra điểm yếu của con người để chuẩn bị cho cuộc xâm lược trong tương lai. Qin Yan tin rằng Xin Wei là Shu Yao và tìm mọi cách để đến gần cô nhằm đánh thức cảm xúc của cô. Xinwei xúc động trước những ký ức về tình yêu của họ và từ bỏ kế hoạch xâm chiếm trái đất. Tuy nhiên, đối tác của cô là Liu Siqi đã đầu độc Qin Yan và các con của họ. Chỉ có một lọ thuốc giải độc, ai nên được cứu? Xinwei rơi vào tuyệt vọng tình huống...</p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yigui","avatar":""},{"name":"徐槿哲","avatar":""},{"name":"Zhou Jun","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
