INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-dau-bep-ngot-ngao-tinh-yeu', 'Cô Gái Đầu Bếp Ngọt Ngào Tình Yêu', 'The Sweet Cook', 'null', 'https://phimimg.com/upload/vod/20231013-1/91cf35151563416da85118b8a776e685.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Người nổi tiếng trên Internet Le Yoyo trở nên nổi tiếng nhờ kỹ năng nấu ăn của mình trên Internet. Vào ngày này, Le Yoyo đã được người hâm mộ mời và chuẩn bị đến nhà của người hâm mộ để phát sóng trực tiếp. Đi được nửa đường, tôi gặp chủ tịch độc đoán Ren Tianlan, hai người cãi nhau và nói những lời tàn nhẫn với nhau, nói rằng họ không bao giờ muốn gặp lại nhau trong cuộc đời này. Khi Lê U đến nơi đã thỏa thuận, hắn phát hiện Nhậm Thiên Lan chính là chủ nhân của căn nhà này! Để gây quỹ điều trị cho mẹ, Le Youyou phải tiếp tục phát sóng trực tiếp tại nhà của Ren Tianlan, điều này khiến Ren Tianlan tin chắc rằng Le Youyou đang lấy cớ để tiếp cận anh và có kế hoạch khác cho riêng mình. Để xua đuổi Le Youyou, Ren Tianlan đã thay đổi thủ đoạn và lạm dụng Le Youyo. Trong quá trình này, Nhậm Thiên Lan dần dần thích Le Yoyo. Le Youyou đã vô tình làm rò rỉ quyền riêng tư của Ren Tianlan trong buổi phát sóng trực tiếp, điều này khiến Ren Tianlan tức giận. Nhậm Thiên Lan cảnh cáo Le Youyou rằng sau này cô không được phép phát sóng trực tiếp, Le Youyou kiên quyết không đồng ý, và cả hai lại xảy ra mâu thuẫn, và lúc này, người đại diện của Le Youyou đã bỏ trốn với số tiền quyên góp của người hâm mộ, điều này khiến Ren Tianlan hiểu lầm Le Yoyo càng nhiều hơn...</span></p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feng Zhimo","avatar":""},{"name":"Xiong Suyi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
