INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-lon-dao-kinh', 'Côn Lôn Đạo Kinh', 'Kun Lun', 'https://phimimg.com/upload/vod/20231013-1/1ae2068181d7032b665221dc2f387b43.jpg', 'https://phimimg.com/upload/vod/20231013-1/7997c26e16fcc43dbcd39c2b9f77969d.jpg', '<p>Lý Tiểu Bân từ nhỏ đã thuộc lòng &quot;Côn Lôn Đạo Kinh&quot;, năm bảy tuổi bị một đạo sĩ hấp thu, gặp nguy hiểm, vì cứu mẹ mình, chân thần bị rút cạn và chết, cha anh, Li Muzhi, phát điên và biến mất, và ông nội anh cũng qua đời. Khi lớn lên, Li Xiaobin làm quản trị viên mạng, một ngày nọ, Ling Yue&#39;er, công cụ ngọc báu tâm linh, thức dậy và hướng dẫn Li Xiaobin bắt đầu tu luyện sự bất tử, và vô tình giải cứu Ye Caiwei, Thánh thể Huyền Âm đang bị bị truy đuổi bởi Ngũ Quỷ Đạo Sĩ. Để giúp cô phong ấn thánh thể, Li Xiaobin đã bước vào cấp độ đầu tiên của Kinh thánh Kunlun để tu luyện, Ye Bita, người nhận nuôi anh, đã bị Năm đạo sĩ ma khủng bố và cuộc sống của anh còn tệ hơn cả cái chết. Người yêu thời thơ ấu Ye Caiwei cũng không được biết đến. Để hoàn thành phong ấn và bảo vệ những người trong cuộc đời mình Người quan trọng nhất, Li Xiaobin đã thành lập liên minh mạnh nhất với những người bạn của mình là Zhang Zhenqiang và Wang Chuchu. Cả ba dấn thân vào con đường tu luyện và sự bất tử, trên đường đi tiêu diệt yêu quái và ác quỷ, bắt đầu con đường tu luyện bất tử chống lại thiên giới, và mở ra thế giới thông qua Trật tự thế giới bất tử do Li Muzhi tìm thấy, cánh cổng dẫn đến thế giới cổ tích.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
