INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-dieu-tri-tinh-yeu', 'Bác Sĩ Điều Trị Tình Yêu', 'Love Therapist', 'null', 'https://phimimg.com/upload/vod/20231013-1/6d6366b4497fafdd0d0bc3f53cd4da0a.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Phó Hiểu Trì - một bác sĩ tâm lý nổi tiếng, hài hước, cường điệu trong lời nói và việc làm, mặc dù bề ngoài cực kỳ dâm đãng, nhưng thực tế là tốt bụng, để cố gắng hết sức chữa trị cho những bệnh nhân nữ đáng yêu, anh đã không ngần ngại hy sinh nhiều thứ.</span></p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liang Xiaoya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
