INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-vuong-bai', 'Anh Hùng Vương Bài', 'The Ace Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/d7338880281c7262378a38dfa7e623b8.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về giấc mơ anh hùng của những người tí hon, và tinh thần không bỏ cuộc chạm đến mọi anh hùng của Beipiao. Zhao Xingxing, một thanh niên nông thôn, đã có ước mơ trở thành ngôi sao từ khi còn nhỏ, nghiện tất cả các loại tiểu thuyết võ thuật và không làm công việc của mình, kéo dân làng trong làng tập luyện biểu diễn cả ngày, và kỹ năng duy nhất là thị lực tuyệt vời và trí nhớ tuyệt vời. Một ngày nọ, tôi nói lời tạm biệt với dân làng, leo lên một chiếc xe cúp vàng biển số Bắc Kinh mà tôi gặp trên đường trước đó trong một nhà hàng ở thị trấn nhỏ, và chuẩn bị đến Bắc Kinh để tham gia cùng Maozi, em trai của trưởng làng, và chính thức ra mắt để bước vào ngành công nghiệp điện ảnh và truyền hình.</span></p>', 'Full', 1, 'single', 'completed', 13, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Songzhi","avatar":""},{"name":"Tong Bin","avatar":""},{"name":"Gao Yujing","avatar":""},{"name":"Gao Yi","avatar":""},{"name":"Zhu Jianwei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
