INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-ma-thuat', 'Áo Ma Thuật', 'MooYi', 'null', 'https://phimimg.com/upload/vod/20231013-1/4f4f5826503acb798a46025179623f67.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong một thị trấn nhỏ, Trường nữ sinh Iceberg và Trường nam sinh Fire Cloud chiến đấu qua nhiều thế hệ. Nhưng bây giờ lãnh đạo của trường trung học nữ, Binglan, quyết tâm ngăn chặn chiến tranh và tìm kiếm hòa bình, nhưng không ngờ, nhà lãnh đạo cạnh tranh của Đại học Huoyun lại quyết tâm trở thành bá chủ. Cuộc đấu tranh vốn đã khó khăn giữa hai trường cao đẳng và đại học càng trở nên căng thẳng hơn bởi sự xuất hiện trở lại của Quỷ Quần áo và Quân đoàn Quỷ đã biến mất ba mươi năm trước, và cuối cùng kết thúc với chiến thắng theo từng giai đoạn của Trường Trung học Ice Blue.</span></p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liêu Nguyệt","avatar":""},{"name":"Yan Rui","avatar":""},{"name":"Wen Zhiqiang","avatar":""},{"name":"Wei Boren","avatar":""},{"name":"Lu Sihan","avatar":""},{"name":"Từ Du","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
