INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('72-ngay-cua-do-em', '72 Ngày Cưa Đổ Em', 'Say Yes Within 72 Days', 'null', 'https://phimimg.com/upload/vod/20231013-1/17941059ae0bd428af3ec7f1915f40de.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nó kể về câu chuyện của otaku Wang Kai, người đã đến trạm trung chuyển thiên đường sau cái chết đột ngột của mình, vào Celestial Internet Cafe và riêng tư đột nhập vào nơi cấm của Internet Cafe. Sau khi vô tình phá hủy Hệ thống Trực tiếp Thiên thể, Âm Dương trở về thế giới do nhầm lẫn, và đáp xuống phòng tắm của nữ sếp lạnh lùng của mình, Andy, và vô tình nhìn thấy lưng Andy đang tắm. Do lỗi hệ thống, cuộc sống của Vương Khai trên thế giới không thể rời khỏi Andy quá 7,2 mét, nếu không sẽ xảy ra hàng loạt hành động kỳ lạ, thậm chí có thể biến mất khỏi đây. Để trở về thiên đường mà không hề hấn gì sau khi hệ thống được khôi phục, Wang Kai buộc phải tung ra tất cả các loại da chết và truy đuổi dữ dội Andy để ở bên cạnh cô.</span></p>', 'Full', 1, 'single', 'completed', 15, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pan Ke","avatar":""},{"name":"Sanna","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
