INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-mot-sach-cua-toi', 'Bạn Trai Mọt Sách Của Tôi', 'My Boyfriend', 'null', 'https://phimimg.com/upload/vod/20231013-1/2d872c485068ddede028a12e72e59a63.webp', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Cô gái bình thường Du Tiểu Lăng thầm yêu Từ Dương, cỏ học ánh nắng mặt trời ở lớp bên cạnh, nhưng cô chưa bao giờ tìm thấy cơ hội để thổ lộ tình cảm đầy nữ tính của mình. Ye Han là một học sinh cao lạnh nổi tiếng trong trường và được các cô gái yêu mến. Tuy nhiên, Du Tiểu Lăng có một thành kiến không thể giải thích được đối với Diệp Hàn đang ngồi phía sau cô. Trong phòng học, đặc quyền mà giáo viên ban cho Diệp Hàn khiến Du Tiểu Linh vốn là một tên cặn bã càng thêm tức giận. Để làm cho Diệp Hàn xì hơi, Du Tiểu Linh bắt đầu trêu chọc Diệp Hàn, giữa hai người liên tục có xích mích, tuy nhiên, điều khiến Du Tiểu Linh khó hiểu là Diệp Hàn luôn chọn cách khoan dung với những trò đùa của cô. Lòng tốt của Diệp Hàn đối với Du Tiểu Linh khiến Hàn Tuyết Nghi, đóa hoa học đường thầm yêu anh, thầm ghen tị. Đồng thời, người bạn thân nhất của cô là Triệu Đông Mai đã nhiều lần ngược đãi Du Tiểu Linh để dạy cho Du Tiểu Linh một bài học cho Hàn Tuyết Nghi, nhưng cô đã được anh hùng của Diệp Hàn cứu, điều này khiến tình cảm của Du Tiểu Linh dành cho Diệp Hàn thay đổi một cách kỳ diệu...</span></p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Jiawei","avatar":""},{"name":"Xiong Yilan","avatar":""},{"name":"Chang Yiwen","avatar":""},{"name":"Zhao Chenxi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
