INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-dai-cuop-quoc-dan-2-dao-tac-tien-phong', 'Án Đại Cướp Quốc Dân 2 : Đạo Tặc Tiên Phong', 'The Robbery 2 : Theives', 'https://phimimg.com/upload/vod/20231012-1/1d91954b841e102f40a247048f9347c1.jpg', 'https://phimimg.com/upload/vod/20231012-1/c83bf9d552e8a974f1ae38e3740811a9.jpg', '<p>Thời Trung Hoa Dân Quốc, Ngân hàng Đại Nguyên Thượng Hải bị bốn tên cướp cướp, ông chủ đằng sau ngân hàng, Nguyên soái Yan, đã ra lệnh đào sâu ba thước để lấy lại tiền. Lúc này, em cua nhỏ Long Yijin và nữ thám tử bí ẩn Irene đang sống bằng nghề biểu diễn đường phố đã gặp tên cướp ngân hàng đang hấp hối Tie Hu. Tiehu tự nhận đã bị chính người của mình phản bội, trước khi chết còn lấy ra một chiếc chìa khóa và bảo ba người đi tìm thủ lĩnh của đoàn kịch nhà họ Hồ. Ba người họ quyết định hợp tác cùng nhau để kiếm tiền thưởng, nhưng việc truy đuổi Nguyên soái Yan và con trai ông ta Yan Shao, việc bắt giữ Thủ lĩnh Hu và thậm chí cả danh tính bí ẩn của Irene đã khiến họ rơi vào tình thế nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhan Mu","avatar":""},{"name":"Liu Nanxi","avatar":""},{"name":"Sang Ping","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"Lu Yong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
