INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-cuc-pham-cua-toi', 'Bạn Thân Cực Phẩm Của Tôi', 'Girls Friendship', 'https://phimimg.com/upload/vod/20231012-1/35f4ebc0971549a3c9c32aeb4414887d.webp', 'https://phimimg.com/upload/vod/20231012-1/e328ae9871d12e10a7a26bae1ac7915e.jpg', '<p>Amei, Lu Wan và Xiao Min, ba cô gái Đông Bắc với tính cách khác nhau, sống cùng nhau trong một căn hộ. Amei là một nam bác sĩ trong một phòng khám tư nhân, ngày nào cũng điều trị cho những người đàn ông xa lạ, Lao Yun, một bác sĩ phụ khoa nam cùng phòng khám với cô, đã theo đuổi cô. Lu Wan có vẻ ngoài ngọt ngào, ngực khủng điển hình và không có đầu óc, gả vào một gia đình giàu có luôn là mục tiêu của cô. Xiao Min, một giáo viên Taekwondo tại một trung tâm đào tạo tư nhân, có đặc điểm của một nữ thất bại và một cô nàng tomboy thể hiện rõ ràng trên cơ thể. Xiao Min luôn phải lòng Zhixian, một giáo viên dạy nhạc cùng trung tâm đào tạo với anh, tuy nhiên Zhixian lại thích Mei. Ba cô gái với những tính cách rất khác nhau đã có một câu chuyện vui nhộn, ồn ào và đầy nước mắt với bốn chàng trai Lao Yun, Zhixian, Haoze và Bobo dưới sự trêu đùa của số phận.</p>', 'Full', 1, 'single', 'completed', 14, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Yan","avatar":""},{"name":"Meng Qian","avatar":""},{"name":"Nan Chiang","avatar":""},{"name":"Zhang Jing Wei","avatar":""},{"name":"Yang Fan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
