INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-den-tu-hom-qua', 'Cô Gái Đến Từ Hôm Qua', 'The Girl from Yesterday', 'https://phimimg.com/upload/vod/20231011-1/02b399050059c58b23701e992fff1a46.jpg', 'https://phimimg.com/upload/vod/20231011-1/be587c2aaacf9f9a24288b72ba776b8d.jpg', '<p>“Cô gái đến từ hôm qua” đan xen giữa hai câu chuyện của quá khứ và hiện tại về cậu học trò tên Thư. Nếu lúc còn bé, Thư luôn tự hào mình là một đứa con trai thông minh, có thể dễ dàng bắt nạt và sai khiến cô bạn hàng xóm Tiểu Li thì giờ đây, khi lớn lên, Thư luôn khổ sở vì bị Việt An, cô bạn học cùng lớp mà cậu thầm thương trộm nhớ “xỏ mũi” và quay như quay dế. Thư dần nhận ra rằng “con gái càng lớn càng khôn, con trai càng lớn càng ngu”... Bộ phim lãng mạn, hài hước mang đến những cảm xúc trong trẻo về thời học sinh ngây ngô với những trò nghịch ngợm nhất quỷ nhì ma, với những yêu thương, hờn giận, hay những rung động lạ lẫm của tình yêu đầu đời.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Miu Lê","avatar":""},{"name":"Ngô Kiến Huy","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
