INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-pheo-ngoai-truyen', 'Chí Phèo Ngoại Truyện', 'Chi Pheo''s Untold Story', 'https://phimimg.com/upload/vod/20231011-1/1821deeaace5695ffa4d7cdb2e8310e4.jpg', 'https://phimimg.com/upload/vod/20231011-1/5e49998a06dc9656dfe7f294db354b6d.jpg', '<p>Na, một cô gái xấu xí làm lao công trong văn phòng thám tử chuyên điều tra ngoại tình, với hy vọng tìm ra thủ phạm giết chết người anh trai cảnh sát của mình. Chí, một tên giang hồ mặt sẹo có biệt danh Chí “Phèo”, với ước mơ giải oan cho mình vì liên tục bị băng đảng gài bẫy. Một ngày nọ, họ bất ngờ gặp nhau như một sự sắp đặt đầy bi hài của số phận...</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ilram Choi","avatar":""},{"name":"Pho Dac Biet","avatar":""},{"name":"Tiến Luật","avatar":""},{"name":"Nam Thư","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
