INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-thi-chiu', 'Chơi Thì Chịu', 'Choi Thi Chiu', 'https://phimimg.com/upload/vod/20231011-1/eef0686239d9a6be054241d740ac0904.jpg', 'https://phimimg.com/upload/vod/20231011-1/41e99cfba0801fae3cdb861c8d863470.jpg', '<p>Xoay quanh câu chuyện mang thai “ngoài ý muốn”, phim kể về chàng rể “hờ” phải về ở chung với người phụ nữ mà anh không hề mong muốn. Từ đó, những tình huống hài hước, và tình cảm cả hai nảy sinh!&nbsp; Chơi Thì Chịu là bộ phim nhẹ nhàng, sâu sắc giúp giới trẻ nhận thức được sức nặng của hai chữ trách nhiệm, cũng như sẽ là bài học giáo dục “tâm lý” giúp các bậc cha mẹ hiểu và đồng hành cùng những bước ngoặt hay những lần vấp ngã của con cái.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trương Thế Vinh","avatar":""},{"name":"Kim Tuyến","avatar":""},{"name":"Trương Thanh Long","avatar":""},{"name":"Phan Thu Quyên","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
