INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hot-boy-noi-loan-2', 'Hot Boy Nổi Loạn 2', 'Lost in Paradise 2', 'https://phimimg.com/upload/vod/20231011-1/a9d7acea51e4010041c29e20afa589f4.jpg', 'https://phimimg.com/upload/vod/20231011-1/6ab22a731c1c1c239c2dfdb9f07912e4.jpg', '<p>Sau thành công của phần đầu “Hotboy nổi loạn và câu chuyện về thằng Cười, cô gái điếm và con vịt”, phần 2 tiết lộ nhiều chi tiết hơn về thế giới mại dâm nam phức tạp và nghịch lý. Sau khi được cứu sống, Lam quay về với công việc cũ: “đứng đường tìm khách” và vẫn tiếp tục đi tìm Khôi, ban trai cũ. Tới khi Lam gặp được Khôi, Lam nhận ra số phận quá bất công với mình. Liệu rằng Lam có thể làm lại từ đầu để có cuộc sống mới hay không?</p>', 'Full', 1, 'single', 'completed', 20, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"La Quốc Hùng","avatar":""},{"name":"Lương Mạnh Hải","avatar":""},{"name":"Hồ Vĩnh Khoa","avatar":""},{"name":"Trần Huy Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
