INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-con-la-nha', 'Khi Con Là Nhà', 'My Son Is My Home', 'https://phimimg.com/upload/vod/20231011-1/95193f55ce6236565b1dfdf41b17cd97.jpg', 'https://phimimg.com/upload/vod/20231011-1/f8a64233dcc974f0d3dd349e53868c58.jpg', '<p>Khi Con Là Nhà là câu chuyện về hai cha con ở vùng quê yên bình. Người cha rất yêu thương con nhưng lại có tật xấu là ham mê cá độ, cờ bạc. Một biến cố xảy ra khiến hai cha con phải trốn chạy lên thành phố và lạc mất nhau. Giữa biết bao khó khăn ở một thành phố lớn họ chưa từng đặt chân tới, cả hai phải nhờ vào lòng tốt của bạn bè và những người xa lạ để tìm thấy nhau.</p>', 'Full', 1, 'single', 'completed', 36, 2017, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Lương Mạnh Hải","avatar":""},{"name":"Phạm Duy Anh","avatar":""},{"name":"La Quốc Hùng","avatar":""},{"name":"Tú Vi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324408);
