INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-con-la-nha', 'Khi Con Là Nhà', 'My Son Is My Home', 'khi con là nhà my son is my home lương mạnh hải phạm duy anh la quốc hùng tú vi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-bao', 'Lôi Báo', 'Head Rush', 'https://phimimg.com/upload/vod/20231011-1/ab06b080777e0311b5b4e9e6bab82152.jpg', 'https://phimimg.com/upload/vod/20231011-1/9aecc7cd3619b2b48c6dd05c4698dcb2.jpg', '<p>Tâm (Cường Seven) là một họa sĩ truyện tranh có cuộc sống hạnh phúc bên cạnh người vợ hiền Linh (Nhã Phương) và cậu con trai kháu khỉnh Pù (Simba A Pù).&nbsp; Khi đang dồn hết tâm sức để hoàn thiện tác phẩm ấp ủ suốt nhiều năm, anh bỗng phát hiện ra mình bị ung thư phổi và chỉ còn sống được một khoảng thời gian ngắn.&nbsp; Khi biết bi kịch của Tâm, chú Mã (Hoàng Sơn) - một người quen của gia đình anh - đã đưa ra giải pháp không tưởng để có thể cứu sống chàng trai: đổi đầu Tâm vào một cơ thể mới. Sau cuộc phẫu thuật, chàng họa sĩ truyện tranh không chỉ hoàn toàn khỏi bệnh mà còn sở hữu sức mạnh vượt trội.&nbsp; Tâm bắt đầu dùng khả năng của mình để giúp đỡ mọi người, trở thành người hùng tại nơi thị trấn anh đang sinh sống. Nhưng mọi chuyện diễn ra không đơn giản như thế. Những ký ức mơ hồ về một người con gái bí ẩn (Vũ Ngọc Anh) bắt đầu xuất hiện trong tâm trí anh. Sau hàng loạt pha cứu người, Tâm đồng thời lọt vào tầm ngắm của một tổ chức tội phạm bí ẩn.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Cường Seven","avatar":""},{"name":"Nhã Phương","avatar":""},{"name":"Simba A Pù","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Ngoc Anh Vu","avatar":""},{"name":"Quách Ngọc Ngoan","avatar":""},{"name":"Jason Ninh Cao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324408);
