INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-chong', 'Mẹ Chồng', 'Mistress', 'https://phimimg.com/upload/vod/20231011-1/426215c0c951b435f47635beea9db9d0.jpg', 'https://phimimg.com/upload/vod/20231011-1/7013dc679012b1b7ad9b61f62e81307d.jpg', '<p>Mẹ Chồng là câu chuyện xảy ra ở bối cảnh giả định mang tên Đại Điền vào những năm 1945 đến 1950, xoay quanh cuộc đời cô Ba Trân. Ba Trân phải chịu đựng những quy củ hà khắc từ gia đình nhà chồng. Sức ép của việc gìn giữ và duy trì nề nếp dòng họ khiến cô nhân bản bi kịch của mình lên những người phụ nữ khác khi cô trở thành mẹ chồng.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Thanh Hằng","avatar":""},{"name":"Diễm My","avatar":""},{"name":"Ngọc Quyên","avatar":""},{"name":"Lan Khuê","avatar":""},{"name":"Midu","avatar":""},{"name":"Lâm Vinh Hải","avatar":""},{"name":"Song Luan","avatar":""},{"name":"Quốc Cường","avatar":""},{"name":"Tiết Cương","avatar":""},{"name":"Hữu Thạch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324408);
