INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('me-chong', 'Mẹ Chồng', 'Mistress', 'mẹ chồng mistress thanh hằng diễm my ngọc quyên lan khuê midu lâm vinh hải song luan quốc cường tiết cương hữu thạch ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-am-ap-mua-xuan', 'Trái tim ấm áp mùa xuân', 'A Warm Spring', 'https://phimimg.com/upload/vod/20231009-1/41b8d5e2be3effda51c5fd30893a7c4f.jpg', 'https://phimimg.com/upload/vod/20231009-1/71a59e29e0d6ff79229f2452b079a651.jpg', '<p>Kỳ nghỉ đông đã đến, và khi Năm mới đến, các học viên của lớp đào tạo do QianSe Video và Tiantian Xuewu phối hợp tổ chức sẽ chia tay các bạn cùng trường và về nhà đón Tết. Các học viên đã có một kế hoạch hành động đặc biệt. Nhằm giúp các em nhỏ ở trại trẻ mồ côi trong kỳ nghỉ đông gửi gắm tình thương sâu sắc, giúp các em bị bỏ lại có một năm đoàn tụ hạnh phúc bên người thân. Dưới sự dẫn dắt của giáo viên lớp điện ảnh và truyền hình, một số học sinh diễn xuất điện ảnh và truyền hình, thông qua những bài thuyết trình khác nhau về tình yêu, đã hoàn thành nhiệm vụ nâng cao là yêu thương, sưởi ấm mùa xuân, đồng thời mang đến bất ngờ lớn trong năm mới cho trẻ mồ côi và trẻ em khuyết tật. tin nhắn còn sót lại. Đồng thời, các em cũng có được nhiều trải nghiệm xã hội cảm động và ấm áp trong dịp nghỉ lễ.</p>', 'Full', 1, 'single', 'completed', 17, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Yichen","avatar":""},{"name":"Cai Yihan","avatar":""},{"name":"Wang Xinyao","avatar":""},{"name":"Liu Luanxuan","avatar":""},{"name":"Tong Mengyuan","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
