INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bf-chuan-men-cua-toi', 'BF chuẩn Men của tôi', 'My Boyfriend', 'https://phimimg.com/upload/vod/20231009-1/4a80d76ccd06174e306827edae3c2f8e.jpeg', 'https://phimimg.com/upload/vod/20231009-1/ebd918345db64d636dd7306ad8149710.jpg', '<p>Trong đám cưới, chú rể Wu Di bị một người đàn ông bắt đi, cô dâu Alice hét lên... Alice tỉnh dậy từ giấc mơ, có câu nói, điều bạn nghĩ đến hàng ngày chính là điều bạn mơ thấy vào ban đêm. Alice luôn quan tâm đến bạn trai Wu Di và bạn bè của anh ấy, He Yuanfang có mối quan hệ không rõ ràng nên nghi ngờ xu hướng tính dục của bạn trai mình có gì đó không ổn nên đã dẫn theo người bạn thân Murphy của mình để bắt tay vào hành trình xác định kỳ lạ. Xu hướng tính dục của Wu Di. Sau khi trải qua &quot;Sự hấp dẫn chết người&quot;, &quot;Kiểm tra và Thông tin&quot;, &quot;Theo dõi tuyệt mật&quot; và &quot;Bẫy sắc đẹp&quot;, sự thật về danh tính đồng tính của Wu Di được đưa ra ánh sáng. Anh kết hôn với Alice chỉ để che giấu tốt hơn danh tính đồng tính của mình và sử dụng danh tính đồng tính của mình. người vợ đồng giới để che đậy mối quan hệ của anh với Alice, vì sự đeo bám của một người đàn ông khác, Alice và Wu Di đã chia tay. Tuy nhiên, Wu Di đã từng quan tâm đến Alice đến mức Alice không thể rời xa anh được nữa nên cô quyết định đối mặt với khó khăn và giành lại tình yêu của Wu Di. Tuy nhiên, việc chia tay một người đồng tính không hề dễ dàng, Alice sẽ phải đối mặt với một thử thách khắc nghiệt hơn, và một lời nói dối trắng trợn dần lộ diện...</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sam Wang","avatar":""},{"name":"Zhu Keren","avatar":""},{"name":"Liu Lingwei","avatar":""},{"name":"Ye Shuo","avatar":""},{"name":"Li Guangbin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324408);
