INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xom-tro-3d', 'Xóm Trọ 3D', 'The Alley Of Love', 'https://phimimg.com/upload/vod/20231007-1/bbd0a4fcb31e22c45cdd0e902d04f549.jpg', 'https://phimimg.com/upload/vod/20231007-1/302cfb4a30fd5506a8d991943e4a3c0d.jpg', '<p>Nội dung Xóm Trọ 3D xoay quanh xóm trọ dành riêng cho những người thuộc 
giới tính thứ 3 của “má Lâm” (nghệ sĩ Minh Nhí thủ vai) với khẩu hiệu 
“Xóm trọ ba đê trai thẳng không cho thuê”. “Hội chị em bạn dì” gồm có: 
cô em gái mạnh mẽ Na (Maya), nghệ sĩ make-up nghiệp dư Như Ý (Thái Duy),
 diễn viên – trợ lý đạo diễn thời vụ Bảo Bảo (Hoàng Linh), ca sĩ kẹo kéo
 Lệ (Xuân Nghị), nhà thiết kế thời trang Tú (Nam Cường) và chị đại “Ông 
Nội” (Việt Hương). Mỗi người mỗi cảnh, họ đều bị gia đình – xã hội hắt 
hủi, tước đi quyền sống thật với giới tính đúng của mình. Xóm trọ 3D trở
 thành ngôi nhà duy nhất mà ở đó má Lâm vừa là một người mẹ vừa là một 
người chị chở che, đùm bọc mọi người.</p>', 'Full', 1, 'single', 'completed', 16, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Huy Khánh","avatar":""},{"name":"Minh Nhí","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Maya","avatar":""},{"name":"Xuân Nghị","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
