INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-chung-ta-song', 'Khi Chúng Ta Sống', 'While We Live', 'https://phimimg.com/upload/vod/20230926-1/604ab1b6b1f0064a0cf9a3de22cd9e35.jpg', 'https://phimimg.com/upload/vod/20230926-1/10a4a788da9791a853da4aa35308701e.jpg', '<p>Lấy cảm hứng từ những sự kiện có thật, While We Live theo chân bốn người ở miền Bắc Đan Mạch và số phận của họ đan xen như thế nào trong một vụ tai nạn thương tâm.</p>', 'Full', 1, 'single', 'completed', 25, 2017, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Sebastian Jessen","avatar":""},{"name":"Julie Christiansen","avatar":""},{"name":"Nicolas Bro","avatar":""},{"name":"Charlotte Munck","avatar":""},{"name":"Nikolaj Groth","avatar":""},{"name":"Julie Brochorst Andersen","avatar":""},{"name":"Marie Hammer Boda","avatar":""},{"name":"Henrik Prip","avatar":""},{"name":"Paw Henriksen","avatar":""},{"name":"Mia Jexen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
