INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-su-bat-dac-di', 'Cộng Sự Bất Đắc Dĩ', 'Confidential Assignment', 'https://phimimg.com/upload/vod/20230925-1/39cdd6c36dae760ecf0a670f54692d70.jpg', 'https://phimimg.com/upload/vod/20230925-1/d47f2a888e17da6097f875748ca93bbf.jpg', '<p>Cộng Sự Bất Đắc Dĩ là một phim điện ảnh hành động của Hàn Quốc năm 2017 do Kim Sung-hoon đạo diễn, Yoon Je-kyun sản xuất và Yoon Hyun-ho đảm nhiệm phần kịch bản. Phim có sự tham gia diễn xuất của Hyun Bin, Yoo Hae-jin và Kim Joo-hyuk.</p>', 'Full', 1, 'single', 'completed', 18, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Kim Joo-hyuk","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Yoona","avatar":""},{"name":"Gong Jeong-hwan","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Park Min-ha","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
