INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiet-tac-cua-ve-dep', 'Kiệt Tác Của Vẻ Đẹp', 'Picture of Beauty', 'https://phimimg.com/upload/vod/20230922-1/d9361fafd2449e159b5971ee299b4a87.jpg', 'https://phimimg.com/upload/vod/20230922-1/d8d72a467fa1d513eae7828272d14a61.jpg', '<p>Franek là một hoạ sĩ tài năng cùng với trợ lý Hazel, được một nhà thổ thuê vẽ một bức tranh hy vọng việc kinh doanh sẽ khá hơn. Mặc dù các đối tượng của ông tại nhà chứa là những cô gái đẹp, nhưng Franek không thể vừa ý với các cô gái ấy làm mẫu. Julia một thôn nữ xinh đẹp vừa trốn chạy thoát khỏi cuộc hôn nhân cưỡng ép với người chồng già và độc ác. Cô được giới thiệu với Franek, chàng họa sĩ ngất ngây với nét quyến rũ thanh tươi của nàng, nàng là mẫu người mà Franek tìm kiếm bấy lâu nay. Với tài năng nghệ thuật và ái tình thăng hoa, Franek đã làm nên một kiệt tác tuyệt vời.</p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Danielle Rose","avatar":""},{"name":"Taylor Sands","avatar":""},{"name":"Paweł Hajnos","avatar":""},{"name":"Magdalena Bochan-Jachimek","avatar":""},{"name":"Joanna Mazewska","avatar":""},{"name":"Joanna Sobocinska","avatar":""},{"name":"Lidia Banach","avatar":""},{"name":"Misha Czumaczenko","avatar":""},{"name":"Ernestyna Winnicka","avatar":""},{"name":"Sylwia Kaczmarek","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
