INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguc-tu', 'Ngục Tù', 'The Prison', 'https://phimimg.com/upload/vod/20230922-1/ac5f9cab17a3b95def1cf6f2bb35fae6.jpg', 'https://phimimg.com/upload/vod/20230922-1/e6ad3b17e5e4adeab4accdae6a03ed5f.jpg', '<p><span style="font-family: ">Em trai của cảnh sát hình sự do Kim Rae-won thủ vai bị một băng nhóm tội phạm hại chết. Để tìm ra sự thật, anh vào nhà tù với tư cách là tù nhân để tiếp cận với nhân vật tự xưng là “vua” trong nhà tù. Vua nhà tù do Han Suk-kyu thủ vai có thực hiện giao dịch ngầm nào đó với quan chức chính phủ cấp cao nên vẫn có thể một tay che trời trong ngục.</span></p>', 'Full', 1, 'single', 'completed', 19, 2017, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Suk-kyu","avatar":""},{"name":"Kim Rae-won","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Shin Sung-rok","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kang Shin-il","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Park Won-sang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324408);
