INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-di-tan-dunkirk', 'Cuộc Di Tản Dunkirk', 'Dunkirk', 'https://phimimg.com/upload/vod/20230919-1/447c7b2e4a3d6ad329c4fc4a6a8a6574.jpg', 'https://phimimg.com/upload/vod/20230919-1/77817416d1208091af66ec9fd6046a0a.jpg', '<p><span style="font-family: ">Năm 1940, nước Anh và các đồng minh đối diện với một thảm họa quân sự khổng lồ. 400.000 quân của họ sập bẫy trong tuyệt vọng tại Dunkirk, Pháp. Họ đứng trước nguy cơ bị phát xít Đức xóa sổ hoàn toàn… Lúc này, thủ tướng Anh - Winston Churchill đã phát động chiến dịch Dynamo lịch sử kéo dài từ 26/5 đến 4/6/1940. Khi những người lính “Họ không thể về nhà. Quê nhà sẽ đến tìm họ.” Hơn 68.000 quân viễn chinh Anh đã chết hoặc bị bắt làm tù binh nhưng đã có 218.000 lính Anh, 120.000 lính Pháp và Bỉ được giải cứu trong chiến dịch này.</span></p>', 'Full', 1, 'single', 'completed', 25, 2017, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Fionn Whitehead","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Mark Rylance","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Harry Styles","avatar":""},{"name":"Aneurin Barnard","avatar":""},{"name":"Damien Bonnard","avatar":""},{"name":"Lee Armstrong","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324408);
