INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nhuc-chuong-cuoi', 'Ô Nhục: Chương Cuối', 'Outrage Coda', 'https://phimimg.com/upload/vod/20230918-1/94b5494fd63e45740e3756a328ee6628.jpg', 'https://phimimg.com/upload/vod/20230918-1/be229b74f7cdda58ef095183d3cf2750.jpg', '<p><span style="font-family: ">Phim Ô Nhục: Chương Cuối: 5 năm sau khi sống sót trong cuộc đại chiến giữa các gia đình yakuza Sanno và Hanabishi, cựu giám đốc yakuza Otomo hiện đang làm việc tại Hàn Quốc cho ông Chang, một thợ sửa lỗi nổi tiếng có ảnh hưởng đến tận Nhật Bản. Một sự cố tương đối nhỏ gây ra những căng thẳng gia tăng giữa Chang Enterprises và Hanabishi. Xung đột ngày càng lớn dần và bùng nổ một cuộc đấu tranh dữ dội giữa các cấp trên của Hanabishi. Khi cuộc sống của Chang cuối cùng bị đe dọa, yakuza Otomo đã trở về Nhật Bản để giải quyết mọi thứ một lần và mãi mãi.</span></p>', 'Full', 1, 'single', 'completed', 22, 2017, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeshi Kitano","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Sansei Shiomi","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Tokio Kaneda","avatar":""},{"name":"Hakuryu","avatar":""},{"name":"Kanji Tsuda","avatar":""},{"name":"Nao Omori","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324408);
