INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-mai-cuoi', 'Ngày Mai Mai Cưới', 'Get Married', 'https://phimimg.com/upload/vod/20230918-1/2b96c3386ee5a50387d767eed3ca86bd.jpg', 'https://phimimg.com/upload/vod/20230918-1/f9d1eda360f113970ef2cb407f63ce79.jpg', '<p><span style="font-family: ">Ngày Mai Mai Cưới là bộ phim tình cảm hài kể về Mai – một cô gái mạnh mẽ có ước mơ trở thành cảnh sát giao thông nhưng lại bị gia đình ép học kế toán. Đã vậy, cô còn bị gia đình ép cưới. Không chỉ mình Mai chịu áp lực gia đình, ba chàng bạn thân của cô cũng khổ sở không kém. Bền - anh chàng mắc tật cà lăm khi gặp chuyện căng thẳng nuôi mộng trở thành ca sĩ nhưng gia đình muốn anh theo nghề gia truyền cào nghêu. Còn Gừng mong muốn làm nhà thám đại dương lại phải đi bỏ mối nước đá giúp gia đình. Mành bị mù màu đỏ, có một ước mơ “nhỏ nhoi” trở thành tỉ phú đô la, trớ trêu thay gia đình lại muốn anh chàng đi tu. Bộ phim có sự tham gia của các diễn viên: Diệu Nhi, bộ ba FapTV: Vinh Râu- Thái Vũ- Huỳnh Phương, Cát Phượng, Trung Dân, Minh Beta.</span></p>', 'Full', 1, 'single', 'completed', 23, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Diệu Nhi","avatar":""},{"name":"Minh Beta","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324408);
