INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-mai-mai-cuoi', 'Ngày Mai Mai Cưới', 'Get Married', 'ngày mai mai cưới get married diệu nhi minh beta ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-cho', 'Kẻ Trộm Chó', 'Ke Trom Cho', 'null', 'https://phimimg.com/upload/vod/20230917-1/69805cdd10f2082bf65bafecac46476f.jpg', '<p><span style="text-wrap: nowrap;">Kẻ Trộm Chó là một sản phẩm mới của đạo diễn Ngụy Minh Khang thuộc đề tài hài hước, tâm lý, hành động. Có thể nói đây là bộ phim có đề tài vô cùng độc đáo và chạm vào một trong những vấn nạn cực kỳ nóng ở nước ta những năm gần đây đó là nạn trộm chó. Bộ phim đánh dấu sự tham gia của các tên tuổi gạo cội trong làng điện ảnh Việt Nam như Lý Hùng, Hồng Vân, Mạc Can, Minh Nhí.. Ngoài ra bộ phim còn có sự ghóp mặt của Trương Mỹ Nhân - hot girl đình đám của chương trình The Face Viet Nam 2017.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Kẻ Trộm Chó là câu chuyện xoay quanh hai tên trộm chó tên là Đen và Ghẻ, 2 người với hai số phận, hoàn cảnh và tính cách trái ngược nhau nhưng cùng quen nhau trong một vụ trộm chó. Đan xen vào đó là câu chuyện lứa đôi lãng mạn và mang đậm tính nhân văn của Mén cô gái bán hột vịt lộn và bắp xào với anh chàng Ghẻ. Những phi vụ trộm chó của Ghẻ và Đen với những tình huống giở khóc giở cười và những bài học nhân sinh quý báu giúp Ghe và Đen từ bỏ cái ác và đi vào con đường lương thiện. Ghẻ và Đen đã giúp giải cứu nhũng phi vụ trộm chó và từ đó truyền tải thông điệp chính của bộ phim: Yêu thương và bảo vệ động vật, bài trừ nạn trộm chó.</span></p>', 'Full', 1, 'single', 'completed', 26, 2017, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Tiết Cương","avatar":""},{"name":"Hứa Minh Đạt","avatar":""},{"name":"Jayvee Mai The Hiep","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324408);
