INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-muoi-sac-thai-den', 'Năm Mươi Sắc Thái: Đen', 'Fifty Shades Darker', 'https://phimimg.com/upload/vod/20230913-1/a93169bde37b9507138a2e1ff6e3b4d8.jpg', 'https://phimimg.com/upload/vod/20230913-1/8e6c37af7f2f69589804d27bc57bfe2b.jpg', '<p><span style="font-family: ">Phim bắt đầu khi chàng tỷ phú Christian muốn quay lại với Anastasia . Trước sự chân thành của Christian, Anastasia đã đồng ý lời đề nghị này, tuy nhiên cô yêu cầu phải có một thỏa thuận giữa hai người: Không có luật lệ, không có bí mật nào nữa. Trong lúc cả hai bắt đầu gây dựng được lòng tin tưởng và bền vững khi bên nhau, thì một “bóng ma” đến từ quá khứ của Christian bất chợt xuất hiện và quyết tâm hủy hoại mọi hy vọng vào tương lai của họ.</span></p>', 'Full', 1, 'single', 'completed', 31, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Jamie Dornan","avatar":""},{"name":"Eric Johnson","avatar":""},{"name":"Eloise Mumford","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Rita Ora","avatar":""},{"name":"Luke Grimes","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Bruce Altman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '[]', 1784690324408);
