INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-hanh-tinh-khi', 'Đại Chiến Hành Tinh Khỉ', 'War for the Planet of the Apes', 'https://phimimg.com/upload/vod/20230912-1/3b1ff2196f37c3a4f079eab39ca73968.jpg', 'https://phimimg.com/upload/vod/20230912-1/b57d537b43ef8e20eb409e34e22e390a.jpg', '<p><span style="font-family: ">War for Planet of the Apes, phần phim thứ 3 và cũng là cuối cùng của trilogy Planet of the Apes. Tiếp nối phần trước, sau khi quân đội biết sự tồn tại của xã hội loài khỉ dưới sự chỉ huy của Caesar, họ quyết định đến chiến đấu chống lại Caesar, nhóm lính được dẫn đầu bởi một vị tướng tàn bạo. Về phần vị vua khỉ của chúng ta, sau những mất mát của mình, anh ta dần trở nên đen tối hơn, có những suy nghĩ độc đoán hơn về con người và cách thống lĩnh của mình. Số phận của hai giống loài này phụ thuộc vào cuộc chiến cuối cùng này!</span></p>', 'Full', 1, 'single', 'completed', 38, 2017, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy Serkis","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Karin Konoval","avatar":""},{"name":"Michael Adamthwaite","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Terry Notary","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Sara Canning","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324408);
