INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-ngu', 'Mỹ Nhân Ngư', 'The Mermaid', 'https://phimimg.com/uploads/movies/20260713/my-nhan-ngu-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/my-nhan-ngu-poster.webp', '<p>Mỹ Nhân Ngư là phim điện ảnh do Châu Tinh Trì làm biên kịch và đạo diễn. Phim công chiếu lần đầu vào ngày 08 tháng 02 năm 2016, doanh thu đạt 3.39 tỉ NDT, là phim giữ kỉ lục "phim có doanh thu cao nhất trong lịch sử phòng vé Hoa ngữ" trong thời gian 1 năm 6 tháng trước khi bị phá sau đó.</p>', 'Full', 1, 'single', 'completed', 36, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lin Yun","avatar":""},{"name":"Deng Chao","avatar":""},{"name":"Zhang Yuqi","avatar":""},{"name":"Show Lo","avatar":""},{"name":"Tsui Hark","avatar":""},{"name":"Wen Zhang","avatar":""},{"name":"Kris Wu","avatar":""},{"name":"Lee Sheung-Ching","avatar":""},{"name":"Lu Zhengyu","avatar":""},{"name":"Chiu Chi-Ling","avatar":""},{"name":"Zhang Mei''e","avatar":""},{"name":"Gao Shuang","avatar":""},{"name":"Linah Matsuoka","avatar":""},{"name":"Barbie Liu","avatar":""},{"name":"Xu Zhenzhen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Mermaid","Mei ren yu","미인어","Las Travesura De Una Sirena","美人鱼","Русалка","Η Γοργόνα","A sellő","美人魚","La Sirène"]', 1784690324408);
