INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-manh-ho', 'Biệt Đội Mãnh Hổ', 'Railroad Tigers', 'https://phimimg.com/uploads/movies/20260710/biet-doi-manh-ho-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/biet-doi-manh-ho-poster.webp', '<p>Bộ phim hành động, lịch sử được nhiều người chờ đón. Năm 1941, trong bối cảnh Trung Quốc thù trong giặc ngoài, một công nhân đường sắt Trung Quốc đã dẫn dắt những anh em có cùng chí hướng để chống lại quân Nhật, cướp lấy thực phẩm cứu khổ tế bần. Trước tình hình đó, quân đội Nhật bắt đầu gửi thêm quân đội tới đàn áp khiến đội Mãnh Hổ gặp vô vàn khó khăn. Đây là bộ phim võ thuật tiếp theo của “ông vua” Thành Long.</p>', 'Full', 1, 'single', 'completed', 54, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Huang Zitao","avatar":""},{"name":"Jaycee Chan","avatar":""},{"name":"Wang Kai","avatar":""},{"name":"Xu Fan","avatar":""},{"name":"Hiroyuki Ikeuchi","avatar":""},{"name":"Sang Ping","avatar":""},{"name":"Alan Ng Wing-Lun","avatar":""},{"name":"Darren Wang","avatar":""},{"name":"Zhang Lanxin","avatar":""},{"name":"Na Wei","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Asano Nagahide","avatar":""},{"name":"Koji Yano","avatar":""},{"name":"Zhang Yishang","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["铁道飞虎","Railroad Tigers","レイルロード・タイガー：2016","Tie Dao Fei Hu"]', 1784690324408);
