INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tau-thoat-ngoan-muc', 'Tẩu Thoát Ngoạn Mục', 'Skiptrace', 'tẩu thoát ngoạn mục skiptrace jackie chan johnny knoxville fan bingbing eric tsang chi-wai eve torres winston chao yeon jeong-hun shi shi michael wong dylan kuo zhang lanxin na wei charlie rawes mikhail gorevoy sara forsberg thành long jackie chan - skiptrace 绝地逃亡 jue di tao wang una pareja dispareja salva-te se puderes 跨境追捕 跳跃追踪 отпетые напарники по следу jackie chan - skiptrace - auf der jagd nach matador skiptrace', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-do-toi-loi-dan-ong-va-dan-ba', 'Cám Dỗ Tội Lỗi (Đàn Ông và Đàn Bà)', 'A Man and a Woman', 'https://phimimg.com/uploads/movies/20260710/cam-do-toi-loi-dan-ong-va-dan-ba-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/cam-do-toi-loi-dan-ong-va-dan-ba-poster.webp', '<p>Sang Min tới Phần Lan để đưa con trai mắc chứng bệnh tự kỷ tham gia vào một buổi cắm trại đặc biệt. Hong Ki là một kiến trúc sư được cử tới Phần Lan làm việc. Anh có một gia đình không hoàn hảo, với cô con gái mắc bệnh trầm cảm và một người vợ thần kinh không ổn định. Hai người gặp nhau lần đầu tiên tại buổi cắm trại đặc biệt. Họ trải qua một chuyến đi ngắn để tới được nơi cắm trại. Trong chuyến đi, dần dần họ tìm được sự kết nối ở nhau. Và cuối cùng, khi không thể kiềm chế, họ đã dành một đêm bên nhau. Nhưng ngay ngày hôm sau, họ chia tay mà không hề biết tên của đối phương.</p>', 'Full', 1, 'single', 'completed', 53, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon Do-yeon","avatar":""},{"name":"Gong Yoo","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Lee Ru-ahn","avatar":""},{"name":"Park Min-ji","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Min Moo-je","avatar":""},{"name":"Jung Sun-kyung","avatar":""},{"name":"Jeon Ik-ryoung","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Baek Sang-hee","avatar":""},{"name":"No Kang-min","avatar":""},{"name":"Kang Ji-woo","avatar":""},{"name":"Kim Young-sun","avatar":""},{"name":"Jung Soon-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Nam-gwa yeo","關不住的誘惑","Мужчина и женщина","Namgwa Yeo","A Man and A Woman","雪国恋人","จูบนั้นฉันจำไม่ลืม","男と女：2016","남과 여"]', 1784690324408);
