INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-nhau-phan-2', 'Bên Nhau (Phần 2)', 'Togetherness (Season 2)', 'https://phimimg.com/upload/vod/20260630-1/29806108974975166003cd05471abe76.jpg', 'https://phimimg.com/upload/vod/20260630-1/ccd066a0b67d0c0d14854f77d7b1fceb.jpg', '<p>Bốn người trưởng thành đang cận kề ngưỡng tuổi 40, cùng sống chung dưới một mái nhà, phải chật vật đấu tranh để vừa gìn giữ các mối quan hệ tình cảm, vừa nuôi dưỡng những ước mơ cá nhân của riêng mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 39, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Duplass","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Steve Zissis","avatar":""},{"name":"Amanda Peet","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Вместе","Togetherness"]', 1784690324408);
