INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-ban-voi-ma', 'Kết Bạn Với Ma', 'Friend Request', 'https://phimimg.com/upload/vod/20260620-1/a270e608b32f6951eec4b1291613941b.jpg', 'https://phimimg.com/upload/vod/20260620-1/f07a4f016fd0d422add423699d7470f1.jpg', '<p>Laura là một hotgirl của trường, sống thời học sinh vui vẻ và rạng rỡ bên gia đình và 800 người bạn trên Facebook. Khi nhận lời kết bạn của cô bạn cùng lớp nhưng vô cùng bí ẩn - Marina, Laura đã vô hình chung tạo ra một lời nguyền cho chính mình. Tài khoản Facebook của cô gái đã chết nhưng linh hồn không siêu thoát đã khiến Laura rơi vào tình cảnh cô đơn, bi đát. Thế giới ảo và thực của cô bị thống trị bởi những hồn ma. Hơn nữa, những người bạn thân thiết cũng lần lượt bị giết chết một cách thảm thương. Cuối cùng liệu có ai sống sót, lời nguyền ma ám có thể bị phá vỡ? Chúc các bạn xem phim vui vẻ! Tags</p>', 'Full', 1, 'single', 'completed', 51, 2016, 'Vietsub', 'FHD', 'Đức', 1, '[{"name":"Alycia Debnam-Carey","avatar":""},{"name":"Connor Paolo","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Brit Morgan","avatar":""},{"name":"Brooke Markham","avatar":""},{"name":"Sean Marquette","avatar":""},{"name":"Liesl Ahlers","avatar":""},{"name":"Nicholas Pauling","avatar":""},{"name":"Shashawnee Hall","avatar":""},{"name":"Susan Danford","avatar":""},{"name":"Lee Raviv","avatar":""},{"name":"Dorothy Ann Gould","avatar":""},{"name":"Kimberleigh Stark","avatar":""},{"name":"Lauren Steyn","avatar":""},{"name":"Carolyn Forword","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kill a Friend","Unknown Error","Solicitud de amistad","Unfriend","Žádost o Přátelství","Запрос в друзья [Friend Request (2015)]","Friend Request","Pedido de Amizade"]', 1784690324408);
