INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kfc', 'KFC', 'KFC', 'https://phimimg.com/upload/vod/20260620-1/18a0024df17b92fa9775398c2fe3017b.jpg', 'https://phimimg.com/upload/vod/20260620-1/bd8bc4633119f054280b074f60920864.jpg', '<p>Nhân vật trung tâm là một cậu bé béo phì sống cùng cha. Người cha bên ngoài có vẻ bình thường nhưng thực chất là một kẻ biến thái, sát hại và ăn thịt người. Ông ta còn cho con trai ăn thịt người, góp phần khiến cậu bé ngày càng béo phì.</p>', 'Full', 1, 'single', 'ongoing', 80, 2016, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Ta Quang Chien","avatar":""},{"name":"Tram Primrose","avatar":""},{"name":"Hoang Ba Son","avatar":""},{"name":"Tony Nguyen","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["KFC　食人連鎖","KFC"]', 1784690324408);
