INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-quy-keo-cua-quy', 'Nhà Quỷ (Kẹo của Quỷ)', 'The Devil''s Candy', 'https://phimimg.com/upload/vod/20260617-1/a8d2eec3cece6c70b309aeec672fdaa9.jpg', 'https://phimimg.com/upload/vod/20260617-1/8a4dfce48f2e769cee599b0f57d7d742.jpg', '<p>Một họa sĩ đang gặp khó khăn về tài chính bị thế lực ma quỷ chiếm hữu sau khi anh và gia đình nhỏ của mình chuyển đến ngôi nhà mơ ước ở vùng nông thôn Texas.</p>', 'Full', 1, 'single', 'completed', 43, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Ethan Embry","avatar":""},{"name":"Shiri Appleby","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Kiara Glasco","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"Oryan Landa","avatar":""},{"name":"Craig Nigh","avatar":""},{"name":"Marco Perella","avatar":""},{"name":"Mylinda Royer","avatar":""},{"name":"Arthur Dale","avatar":""},{"name":"Jack Dullnig","avatar":""},{"name":"Richard Rollin","avatar":""},{"name":"Ash Thapliyal","avatar":""},{"name":"Jamie Tisdale","avatar":""},{"name":"Jose Villarreal","avatar":""},{"name":"Marisela Menchaca","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Дары смерти","데블스 캔디","The Devil''s Candy"]', 1784690324408);
