INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-quy-keo-cua-quy', 'Nhà Quỷ (Kẹo của Quỷ)', 'The Devil''s Candy', 'nhà quỷ (kẹo của quỷ) the devil''s candy ethan embry shiri appleby pruitt taylor vince kiara glasco tony amendola leland orser oryan landa craig nigh marco perella mylinda royer arthur dale jack dullnig richard rollin ash thapliyal jamie tisdale jose villarreal marisela menchaca дары смерти 데블스 캔디 the devil''s candy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-tu-cai-nhin-dau-tien-2016', 'Yêu Em Từ Cái Nhìn Đầu Tiên', 'Love O2O', 'https://phimimg.com/upload/vod/20260612-1/b7e6198f60a3d69b19bcf7f6d20feb7d.jpg', 'https://phimimg.com/upload/vod/20260612-1/79818be642a47693926f2b33e9084cf7.jpg', '<p>Bộ phim bắt đầu từ một câu chuyện tình yêu trên mạng. Sau khi “ly hôn” (trong trò chơi) với Chân Thủy Vô Hương – một cao thủ của game Giang Hồ Mộng Du, Bối Vi Vi (Trịnh Sảng) – hoa khôi khoa Công nghệ thông tin trường Đại học nổi tiếng A. Với nickname là Lô Vĩ Vi Vi đã “tái hôn” với Đại thần Nhất Tiếu Nại Hà (Dương Dương) – đệ nhất cao thủ trong game. Không ngờ khi hai người quyết định gặp mặt nhau ngoài đời, đệ nhất cao thủ Nhất Tiếu Nại Hà lại là Tiêu Nại – chàng trai đẳng cấp cao nhất của trường đại học Trùng Khánh mà biết bao cô gái ngưỡng mộ yêu thầm. Từ đó Vi Vi và Tiêu Nại bắt đầu một chuyện tình ngoài đời, không chỉ là cuộc “hôn nhân ảo trong game”. Từ khi quen biết đến khi yêu nhau, chuyện tình cảm của hai người không hề có thăng trầm sóng gió, chỉ tích lũy lại từng chút từng chút một, nhưng thấm sâu vào tận đáy lòng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 41, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Trịnh Sảng","avatar":""},{"name":"Ngưu Tuấn Phong","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Trương Bân Bân","avatar":""},{"name":"Thôi Hàng","avatar":""},{"name":"Tần Ngữ","avatar":""},{"name":"Tống Hân Giai Di","avatar":""},{"name":"Trương Hách","avatar":""},{"name":"Mã Xuân Thụy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","s