INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-2016', 'Ranh Giới', 'Boundary', 'https://phimimg.com/upload/vod/20260518-1/f36c5a2fc4011b7e53f806fb5fd36d71.jpg', 'https://phimimg.com/upload/vod/20260518-1/20a29389700192ba90592ec24e8a148a.jpg', '<p>Tae-ho, một học sinh trung học, và bạn bè quyết định đi ngắm sao băng vào cuối tuần. Trong khi đó, Tae-ho, một chàng trai đồng tính, đang giấu bạn bè chuyện này, nhưng cũng tránh các cuộc hẹn vì bận hẹn hò với người yêu. Khi người bạn thân nhất của anh, Ngựa Trắng, vô tình phát hiện ra bí mật này, câu chuyện trở nên khó đoán.</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hwang Ki-yeon","avatar":""},{"name":"Kim Bang-eon","avatar":""},{"name":"김현목","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["경계"]', 1784690324408);
