INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-tinh-nghi-phan-5', 'Kẻ Tình Nghi (Phần 5)', 'Person of Interest (Season 5)', 'kẻ tình nghi (phần 5) person of interest (season 5) jim caviezel michael emerson kevin chapman amy acker sarah shahi personne d''intérêt 嫌疑人 kohde ინტერესის ობიექტი مظنون فرد تحت نظر مظنون تحت نظر suspectul подозреваемый บุคคลต้องสงสัย особливо небезпечно у полі зору p.o.i person of interest', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-than', 'Tiếng Than', 'The Wailing', 'https://phimimg.com/upload/vod/20260511-1/9cba259ceb578a00eae87b765128b8b7.jpg', 'https://phimimg.com/upload/vod/20260511-1/2113239e9315f26182803f1a4fa844ce.jpg', '<p>Tại một ngôi làng heo hút, mọi chuyện mở đầu bằng một vụ thảm sát dã man trong một gia đình. Người vợ bị cứa cổ còn người chồng như tê dại, thẫn thờ bất động với cơ thể nổi đầy lở loét. Anh nhân viên cảnh sát miền quê Jong Goo vốn chỉ quen với chuyện ngồi bàn giấy, đọc truyện tranh lần đầu tiên phải chứng kiến những hiện trường giết người cực kỳ rùng rợn. Đỉnh điểm là khi cô con gái nhỏ của anh bắt đầu có những biểu hiện lạ, trở nên hung hăn, thèm ăn và cứ chực chờ gào thét. Mọi nghi ngờ đều đổ dồn vào một người đàn ông Nhật Bản bí ẩn sống trong rừng với lời đồn đại rằng đó là một kẻ hút máu. Gây sợ hãi nhưng đặc biệt, phim gần như không sử dụng jump-scare. Toàn bộ nỗi sợ được hình thành từ cái không khí u ám, buồn tẻ cùa vùng quê miền núi mưa dầm triền miên. Cùng với đó là sự đa nghi của con người vào những kẻ bí ẩn và cả... ma quỷ. Với The Wailing, nỗi sợ lớn nhất chính là nỗi sợ vào thứ mà ta không thể &quot;điểm mặt gọi tên&quot;.</p>', 'Full', 1, 'single', 'completed', 23, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kwak Do-won","avatar":""},{"name":"Hwang Jung-min","avatar":""},{"name":"Chun Woo-hee","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Kim Hwan-hee","avatar":""},{"name":"Heo Jin","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Kim Do-yoon","avatar":""},{"name":"Cho Han-cheul","avatar":""},{"name":"Son Kang-gook","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Bae Yong-geun","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Yoo Soon-woong","avatar":""},{"name":"Lee Yong-nyeo","avatar":""},{"name":"Hwang Seok-jeong","avatar":""},{"name":"Moon Chang-gil","avatar":""},{"name":"Lee Jun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gok-seong","Gokseong","Goksung","החלילן","הקינה","En presencia del diablo","En Présence du Diable","El lamento","Kvílení","Gok-sung","哭声／コクソン","哭声／コクソン：2016","哭声","Goksung - La presenza del diavolo","곡성"]', 1784690324408);
