INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('esteban', 'Esteban', 'Esteban', 'https://phimimg.com/upload/vod/20260509-1/6c463faa45155b9d089d7d5502718c32.jpg', 'https://phimimg.com/upload/vod/20260509-1/90893384f847ca7a0abccb0a33d84e95.jpg', '<p>Ở Cuba, Esteban - cậu bé 9 tuổi - phụ mẹ đơn thân bán mỹ phẩm chợ đen để mưu sinh. Giữa cuộc sống khó khăn, cậu nuôi dưỡng ước mơ trở thành nghệ sĩ piano. Khi lần đầu được chạm vào cây đàn, Esteban nhận ra tài năng và niềm đam mê thật sự của mình. Nhưng để theo đuổi âm nhạc, cậu phải vượt qua nhiều rào cản của cuộc sống nghèo khó. Hành trình ấy mở ra hy vọng và khát vọng thay đổi tương lai.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Reynaldo Guanche","avatar":""},{"name":"Yuliet Cruz","avatar":""},{"name":"Manuel Porto","avatar":""},{"name":"Raúl Pomares","avatar":""},{"name":"Corina Mestre","avatar":""},{"name":"Mónica Alonso","avatar":""},{"name":"Ismael Isaac","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Esteban"]', 1784690324408);
