INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-trong-bong-toi', 'Thiên đường trong bóng tối', 'Heaven in the Dark', 'https://phimimg.com/upload/vod/20260508-1/25bb1e0c5540bfbb95b332263d623d2e.jpg', 'https://phimimg.com/upload/vod/20260508-1/a779f08c25f7005814abc963c70a4683.jpg', '<p>Michelle và Marco Tol, một cựu mục sư, gặp nhau tại một bữa tiệc. Họ thảo luận về những gì đã xảy ra cách đây 5 năm, khi một vụ bê bối liên quan đến cả hai người nổ ra và khiến Tol mất danh dự.</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Karena Lam Kar-Yan","avatar":""},{"name":"Michelle Wai Si-Nga","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"Wong Hei","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Edmond So Chi-Wai","avatar":""},{"name":"Vincci Cheuk Wan-Chi","avatar":""},{"name":"Tyson Chak","avatar":""},{"name":"Rosa Maria Velasco","avatar":""},{"name":"Chu Pak-Him","avatar":""},{"name":"Dayo Wong Chi-Wah","avatar":""},{"name":"Mishy Fish","avatar":""},{"name":"Wong On-T","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["암색천당","헤븐 인 더 다크","暗色天堂"]', 1784690324408);
