INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-cho-doi-giay-phut-em-yeu-toi', 'Tôi Chờ Đợi Giây Phút Em Yêu Tôi', 'The Moment You Fall in Love', 'https://phimimg.com/upload/vod/20260423-1/48f6bc16a6b804c32399fc56af93e19a.jpg', 'https://phimimg.com/upload/vod/20260423-1/cf4d9cf65932937208e76e796f37d672.jpg', '<p>Sau buổi diễn tập tỏ tình của Natsuki Enomoto với Yuu Setoguchi, hai người em của họ là Kotarou và Hina phải đấu tranh để thú nhận tình yêu của mình. Bất chấp cuộc gặp gỡ đầu tiên thảm khốc ở trường trung học với Koyuki Ayase, trái tim của Hina đã bị nụ cười ấm áp của anh ấy chinh phục. Lần đầu bối rối trước những cảm xúc mới mẻ này, Hina nhanh chóng nhận ra rằng đây là tình yêu đầu của cô.</p>', 'Full', 1, 'hoathinh', 'completed', 33, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tsubasa Yonaga","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Momo Asakura","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Kana Asumi","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Hikaru Midorikawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Suki ni Naru Sono Shunkan o. Kokuhaku Jikkouiinkai","Suki ni naru sono shunkan o.: Kokuhaku jikkou iinkai","Suki ni Naru Sono Shunkan wo.: Kokuhaku Jikkou Iinkai","HoneyWorks: 