INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-muon-song', 'Cậu Bé Muốn Sống', 'The Boy Who Wants To Live', 'https://phimimg.com/upload/vod/20260311-1/5e6552897d648d41b8f69e1f9854db68.jpg', 'https://phimimg.com/upload/vod/20260311-1/b291e751ec6ef1314985c9d822175cba.jpg', '<p>Willi tình cờ bắt gặp Nama đang ăn trộm nhưng không nỡ báo cảnh sát. Từng là một người tị nạn, ông nhìn thấy hình ảnh quá khứ của mình trong cậu bé lạc lõng ấy và quyết định đưa Nama về nhà. Tuy nhiên, hành động đầy trắc ẩn này lại khiến mối quan hệ vốn căng thẳng giữa Willi và con trai thêm rạn nứt. Khi lòng tốt va chạm với những tổn thương chưa lành, cả ba buộc phải đối diện với định kiến, ký ức và câu hỏi về sự tha thứ.</p>', 'Full', 1, 'single', 'completed', 26, 2016, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Nama Traore","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Milan Peschel","avatar":""},{"name":"Ulrich Brandhoff","avatar":""},{"name":"Alwara Höfels","avatar":""},{"name":"Katja Riemann","avatar":""},{"name":"Hildegard Schroedter","avatar":""},{"name":"Anian Zollner","avatar":""},{"name":"Ursula Karusseit","avatar":""},{"name":"Karoline Eichhorn","avatar":""},{"name":"Bettina Stucky","avatar":""},{"name":"Jörg Schüttauf","avatar":""},{"name":"Lars Rudolph","avatar":""},{"name":"Hadiza Oumazou","avatar":""},{"name":"Nadja Engel","avatar":""},{"name":"Vincent Kr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Exodus - Flucht der Kinder","The Boy Who Wants to Live","Nama og Willi","Der Andere - eine Familiengeschichte"]', 1784690324409);
