INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-thay-the', 'Không Thể Thay Thế', 'The Country Doctor / Médecin de campagne / Irreplaceable', 'https://phimimg.com/upload/vod/20260311-1/9f3aa6040f65729ca397c5f8a6e2f415.jpg', 'https://phimimg.com/upload/vod/20260311-1/da1813048b70c68fc9e771c403df7608.jpg', '<p>Jean-Pierre Werner, một bác sĩ nông thôn tận tụy, bàng hoàng khi phát hiện mình mắc khối u không thể phẫu thuật. Tin dữ khiến anh buộc phải đối diện với sự mong manh của chính mình. Khi một nữ bác sĩ từ thành phố đến hỗ trợ điều trị và chăm sóc bệnh nhân, cuộc sống của Werner bắt đầu thay đổi. Sự hiện diện của cô dần khiến anh cảm thấy bất an và lạc lõng. Lần đầu tiên, Werner phải đối mặt với nỗi sợ rằng mình không còn là người không thể thay thế.</p>', 'Full', 1, 'single', 'completed', 23, 2016, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"François Cluzet","avatar":""},{"name":"Marianne Denicourt","avatar":""},{"name":"Isabelle Sadoyan","avatar":""},{"name":"Félix Moati","avatar":""},{"name":"Christophe Odent","avatar":""},{"name":"Patrick Descamps","avatar":""},{"name":"Guy Faucher","avatar":""},{"name":"Margaux Fabre","avatar":""},{"name":"Julien Lucas","avatar":""},{"name":"Yohann Goetzmann","avatar":""},{"name":"Josée Laprun","avatar":""},{"name":"Philippe Bertin","avatar":""},{"name":"Géraldine Schitter","avatar":""},{"name":"Sylvie Lachat","avatar":""},{"name":"Régis Iacono","avatar":""},{"name":"Michel Char","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Country Doctor","Irreplaceable","רופא הכפר","시골 여의사","Селският лекар","Un metge rural","Médecin de campagne"]', 1784690324409);
