INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-cam-quy-du', 'Giam Cầm Quỷ Dữ', 'Shut In', 'https://phimimg.com/upload/vod/20260307-1/3189033d31830c0a40bc24c9cde56e49.jpg', 'https://phimimg.com/upload/vod/20260307-1/0fd0f8439df77f5c8f057ea97cc4fa66.jpg', '<p>Sau một tai nạn giao thông kinh hoàng cướp đi mạng sống của chồng và khiến con trai bị liệt, Mary Portman, một vị bác sĩ tâm lý sống trong một vùng hẻo lánh của New England và chăm sóc con trai. Bị cách biệt với thế giới bên ngoài trong những ngày bão tuyết, cô bắt đầu tin rằng, có một ai đó trong căn nhà đang tìm cách hãm hại họ.</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Naomi Watts","avatar":""},{"name":"Charlie Heaton","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"David Cubitt","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Crystal Balint","avatar":""},{"name":"Clémentine Poidatz","avatar":""},{"name":"Ellen David","avatar":""},{"name":"Tim Post","avatar":""},{"name":"Alexandre Bacon","avatar":""},{"name":"Peter Outerbridge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["셧 인","Refém do Medo","Shut In"]', 1784690324409);
