INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grizzy-va-hoi-lemmut-phan-1', 'Grizzy Và Hội Lemmut (Phần 1)', 'Grizzy And The Lemmings (Season 1)', 'https://phimimg.com/upload/vod/20260123-1/8d8e23f7cd65541b8810f9cc8ff1944f.jpg', 'https://phimimg.com/upload/vod/20260123-1/9ded0402abe0551a960c9aeb49c8b38b.jpg', '<p>Chú gấu Grizzy thích ăn vặt và thư giãn trong một căn nhà gỗ ở khu rừng thuộc Canada. Cũng tại đó, hội lemmut đáng yêu và mê cảm giác mạnh lúc nào cũng gây náo loạn.</p>', 'Hoàn Tất (78/78)', 78, 'hoathinh', 'completed', 22, 2016, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Pierre-Alain de Garrigues","avatar":""},{"name":"Josselin Charier","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大炮与小恶魔","Grizzy & die Lemminge","Medo Grizli i male napasti","Grizzy and the Lemmings","Grizzy et les Lemmings"]', 1784690324409);
