INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('warcraft-dai-chien-hai-the-gioi', 'Warcraft: Đại Chiến Hai Thế Giới', 'Warcraft', 'https://phimimg.com/upload/vod/20260122-1/242db8e4c56b569785fb116bd053184d.jpg', 'https://phimimg.com/upload/vod/20260122-1/320788c61f57133ad60a024270f05dd4.jpg', '<p>Vương quốc yên bình của Azeroth đứng bên bờ vực chiến tranh khi nền văn minh của nó phải đối mặt với một chủng tộc xâm lược đáng sợ: những chiến binh orc chạy trốn khỏi ngôi nhà đang chết của họ để xâm chiếm thuộc địa khác. Khi một cánh cổng mở ra để kết nối hai thế giới, một đội quân phải đối mặt với sự hủy diệt và những người khác phải đối mặt với sự tuyệt chủng. Từ hai phía đối nghịch, hai anh hùng được đặt vào một khóa học va chạm sẽ quyết định số phận của gia đình, người dân và nhà của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Travis Fimmel","avatar":""},{"name":"Paula Patton","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Dominic Cooper","avatar":""},{"name":"Ben Schnetzer","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Robert Kazinsky","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Anna Galvin","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Ruth Negga","avatar":""},{"name":"Burkely Duffield","avatar":""},{"name":"Dean Redman","avatar":""},{"name":"Glenn Ennis","avatar":""},{"name":"Terry Notary","avatar":""},{"name":"Michael A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["World of Warcraft","Варкрафт: Початок","Warcraft: The Beginning","ウォークラフト：2016","Warcraft：2016","Warcraft: Đại Chiến Hai Thế Giới","Warcraft - Początek","魔獸爭霸：戰雄崛起","ვარქრაფტი","ვარკრაფტი","ომის ხელოვნება","Warcraft"]', 1784690324409);
