INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-quan-ly-ca-dem-phan-1', 'Người Quản Lý Ca Đêm (Phần 1)', 'The Night Manager (Season 1)', 'https://phimimg.com/upload/vod/20260113-1/01696d7bd65783ddcbe426449c16ca31.jpg', 'https://phimimg.com/upload/vod/20260113-1/4e15d420e1a31aa15bf14ca41411c1c6.jpg', '<p>Dựa trên tiểu thuyết cùng tên của John le Carré, Tom Hiddleston vào vai một cựu binh sĩ được tuyển chọn vào một tổ chức tình báo lớn nhằm triệt hạ một đường dây buôn bán vũ khí.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 22, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Hiddleston","avatar":""},{"name":"Diego Calva","avatar":""},{"name":"Camila Morrone","avatar":""},{"name":"Paul Chahidi","avatar":""},{"name":"Hayley Squires","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Unax Ugalde","avatar":""},{"name":"Alberto Ammann","avatar":""},{"name":"Diego Santos","avatar":""},{"name":"Slavko Sobin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Нощният управител","O Gerente Noturno","Le directeur de nuit","El infiltrado","מנהל הלילה","Нічний менеджер","The Night Manager"]', 1784690324409);
