INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-nguon-dai-dich-nha-ga-seoul', 'Khởi Nguồn Đại Dịch (Nhà Ga Seoul)', 'Seoul Station', 'https://phimimg.com/upload/vod/20260112-1/71e63178d292c331cc4c22367def7cac.jpg', 'https://phimimg.com/upload/vod/20260112-1/57723b5a294926841eae4948a7f61ae3.jpg', '<p>Bộ phim&nbsp;bắt đầu khi một ông lão vô gia cư bị thương ở cổ và vai, lang thang tiến thẳng vào nhà ga Seoul trong sự làm ngơ của cảnh sát và nhân viên trạm. Không ai có bất kỳ để ý hay quan tâm nào đến khi có một người giúp đỡ ông bị cắm và trở thành zombie. Sau đó, rất nhiều người đã bị cắn và một khung cảnh hoang tàn và hỗn loạn tại nhà ga làm mọi thứ trở nên kịch tính. Cùng lúc đó, Hye Sun vừa trốn khỏi nhà thổ sau một cuộc tranh cãi với bạn trai Ki Woong , nhưng vừa bước ra khỏi thì họ bắt gặp ngay một cảnh tượng mà trong tưởng tượng họ cũng không nghĩ đến, những xác sống đang dần tiến đến và đang đuổi theo cha Hye Sun. Ba người, ba thân phận bước vào cuộc chạy trốn những zombie kinh khủng…</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Shim Eun-kyung","avatar":""},{"name":"Lee Joon","avatar":""},{"name":"Kim Jae-rok","avatar":""},{"name":"Jang Hyuk-jin","avatar":""},{"name":"Kim Dae-heung","avatar":""},{"name":"Yeon Sang-ho","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Seoul Station","尸杀前传","서울역"]', 1