INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-phan-1-nguoi-tren-van-nguoi', 'Nhất Nhân Chi Hạ (Phần 1) (Người Trên Vạn Người)', 'The Outcast (Season 1) (Hitori No Shita)', 'https://phimimg.com/upload/vod/20260110-1/132f923b22814a54d5e5e3827a860b4c.jpg', 'https://phimimg.com/upload/vod/20260110-1/42db96de9d807ddb192d33a572c52765.jpg', '<p>Thế giới này có tồn tại dị nhân. Trương Sở Lam chính là một dị nhân ẩn mình trong những người bình thường. Trong 19 năm cuộc đời trước đó, cậu vẫn luôn cẩn thận ẩn giấu sự khác biệt của bản thân với người khác. Cho đến một ngày, cô gái thần bí Phùng Bảo Bảo tìm đến cậu. Từ đó cậu bị cương thi đuổi, quái nhân chém, bị cuốn vào vòng xoáy những rắc rối mà trước đây chưa từng thấy…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Liansha","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Ajie","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一人之下","Fengqi Yunyong, Luotian Dajiao","异人","Yi Ren Zhi Xia","Yi Ren Zhixia","Hitori no Shita – The Outcast","hitorinoshita - The Outcast","Hitori no Shita","一人の下","一人之下 THE OUTCAST","일인지하 The Outcast","Один из отвергнутых: Изгой","Under One Person","The Outcast","The.OutCast"]', 1784690324409);
