INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-on-dich-2-hoi-nu-sinh-noi-day', 'Hàng Xóm Ôn Dịch 2: Hội Nữ Sinh Nổi Dậy', 'Neighbors 2: Sorority Rising', 'https://phimimg.com/upload/vod/20260108-1/34f2e1d6ab2ad02326f60aa0a430e588.jpg', 'https://phimimg.com/upload/vod/20260108-1/8ea63c5d15bb6dc9339ad1001bd5585f.jpg', '<p>Neighbor 2 sẽ tiếp nối câu chuyện của phần 1. Lúc này Mac và Kelly Radner đã có em bé, và họ quyết định chuyển về vùng ngoại ô để bắt đầu sống “như người trưởng thành”. Tuy nhiên, lúc này họ mới nhận ra rằng những người hàng xóm mới của mình còn điên rồ hơn cả đám hàng xóm cũ. Hàng xóm của nhà Mac là căn nhà hội nữ sinh Kappa Nu với những cô gái nổi loạn, luôn muốn thoát khỏi những quy định chặt chẻ của nhà trường. Và một “cuộc vật lộn” mới lại bắt đầu khi mọi rặc rối nổ ra giữa cuộc sống của 2 bên</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seth Rogen","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Ike Barinholtz","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Jerrod Carmichael","avatar":""},{"name":"Carla Gallo","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Beanie Feldstein","avatar":""},{"name":"Hannibal Buress","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Elise Vargas","avatar":""},{"name":"Zoey Vargas","avatar":""},{"name":"Clara M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bad Neighbours 2: Sorority Rising","Bad Neighbours 2 - Sorority Rising","Nos pires voisins 2","나쁜 이웃들 2","Pis Qonşular 2","Buenos Vecinos 2","Los Manoletes que te Cagas 2","Соседи. На тропе войны 2","Соседи 2","Vecini de coșmar 2: Un nou război în cartier","Neighbors 2: Sorority Rising"]', 1784690324409);
