INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-doi-canh-sat-2', 'Bộ Đôi Cảnh Sát 2', 'Ride Along 2', 'bộ đôi cảnh sát 2 ride along 2 kevin hart ice cube olivia munn tika sumpter ken jeong tyrese gibson nadine velazquez benjamin bratt glen powell sherri shepherd utkarsh ambudkar bruce mcgill arturo del puerto carlos gómez robert pralgo bresha webb james martin kelly eri פטרול משותף 2 novato en apuros 2 un policía y medio 2 ride along 2 - tatort miami ride along 2 - next level miami ブラザー・ミッション -ライド・アロング 2- ブラザー・ミッション ライド・アロング 2 līdzbraucējs 2 ride along 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-lun-tinh-nghich', 'Quỷ Lùn Tinh Nghịch', 'Trolls', 'https://phimimg.com/upload/vod/20260105-1/f0988d734b635d3cfd7307cf7e3959d6.jpg', 'https://phimimg.com/upload/vod/20260105-1/3f43c93e05f616b82a039f5c0b80f557.jpg', '<p>Quỷ lùn Troll - loài sinh vật sống ôn hoà, yêu nhảy múa, hát ca, nhưng đồng thời là con mồi yêu thích của các Bergen. Bergen vốn là một giống loài xấu xí, không bao giờ biết đến hạnh phúc, và chỉ tìm thấy niềm vui mỗi khi được ăn thịt các Troll. Dưới sự lãnh đạo của nhà vua Peppy, các Troll rốt cuộc cũng thoát khỏi cảnh “nằm trên bàn tiệc”. Bẵng đi 20 năm, vương quốc quỷ lùn quyết định mở bữa đại tiệc để kỷ niệm quãng thời gian an lành, hạnh phúc. Toàn bộ vương quốc, đặc biệt là công chúa Poppy, đều mong đến ngày trọng đại. Chỉ còn chàng lùn cục mịch Branch thì không, bởi cậu vốn ghét đám đông và sự ồn ào. Và cũng chính sự ồn ào đó cùng những màn bắn pháo hoa rực rỡ đã khiến một ả đầu bếp của Bergen tìm ra chỗ đám quỷ lùn đang trú ẩn. Lúc này, Poppy và Branch trở thành đôi bạn đồng hành bất đắc dĩ trong cuộc giải cứu vương quốc.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anna Kendrick","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"James Corden","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Ron Funches","avatar":""},{"name":"Aino Jawo","avatar":""},{"name":"Caroline Hjelt","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Quvenzhané Wallis","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Gwen Stefani","avatar":""},{"name":"Iris Dohrn","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Trollid","Trolle","ترول‌ها","Les trolls (1)","Trolls 1","טרולים 1","Tröll","Trolls"]', 1784690324409);
