INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rua-do', 'Rùa Đỏ', 'The Red Turtle', 'https://phimimg.com/upload/vod/20251230-1/aea87b0344fa187be1a9a2e960d94d5a.jpg', 'https://phimimg.com/upload/vod/20251230-1/e3954700c1e7c3aff6ee75e823298125.jpg', '<p>Kể về cuộc sống của một thủy thủ bị đắm tàu mắc kẹt trên một hòn đảo nhiệt đới hoang vắng, nơi sinh sống của rùa, cua và các loài chim. .</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2016, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Tom Hudson","avatar":""},{"name":"Baptiste Goy","avatar":""},{"name":"Axel Devillers","avatar":""},{"name":"Barbara Beretta","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["La tortue rouge","A Tartaruga Vermelha","The Red Turtle"]', 1784690324409);
