INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tinh-yeu', 'Bẫy Tình Yêu', 'Cheese in the Trap', 'https://phimimg.com/upload/vod/20251228-1/b3bd04bbbd74b06f41f2edbe0e308589.jpg', 'https://phimimg.com/upload/vod/20251228-1/00c503583f04a9de92be321226dfd525.jpg', '<p>Bản chuyển thể từ truyện tranh động này nói về cô nữ sinh nghèo cố gắng theo đuổi ước mơ đại học và vô tình thu hút anh chàng thượng lưu nhưng cũng có nhiều góc khuất.

Phim Bẫy tình yêu xoay quanh mối quan hệ giữa cô sinh viên đại học Hong Seol (Kim Go Eun) và tiền bối cùng trường Yoo Jung (Park Hae Jin). Hong Seol là vai diễn truyền hình đầu tiên của Kim Go Eun. Nhân vật này được mô tả là một sinh viên chăm chỉ, cô trở lại trường học sau thời gian dài bị gián đoạn.

Vì hoàn cảnh khốn khó mà Hong Seol phải đi làm thêm để trang trải cuộc sống. Trong khi đó, chàng trai nam thứ Park Hae Jin sẽ vào vai Yoo Jung, một quý ngài hoàn hảo. Anh ta có mọi thứ: gia thế, học thức, ngoại hình, sức khỏe, kể cả tính cách. Thế nhưng, ẩn sau những điều tưởng như hoàn mĩ đó là góc khuất đen tối trong tâm hồn chàng thanh niên này. Người sẽ hóa giải cho những vấn đề của anh chính là cô nữ sinh hạng thường Hong Seol.</p>', 'Full', 1, 'series', 'completed', 33, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae-jin","avatar":""},{"name":"Kim Go-eun","avatar":""},{"name":"Seo Kang-joon","avatar":""},{"name":"Park Min-ji","avatar":""},{"name":"Nam Joo-hyuk","avatar":""},{"name":"Lee Sung-kyoung","avatar":""},{"name":"Kim Hee-chan","avatar":""},{"name":"Ji Yun-ho","avatar":""},{"name":"Yoon Ye-joo","avatar":""},{"name":"Cha Joo-young","avatar":""},{"name":"Son Byung-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["奶酪陷阱","Chijeu In Deo Teuraep","แผนรักกับดักหัวใจ","Сир у мишоловці","Cheese In The Trap","치즈인더트랩"]', 1784690324409);
