INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bien-gioi-phan-1', 'Biên Giới (Phần 1)', 'Frontier (Season 1)', 'biên giới (phần 1) frontier (season 1) jason momoa landon liboiron alun armstrong jessica matten zoe boyle allan hawco christian mckay william belleau evan jonigkeit breanne hill michael patric greg bryk shawn doyle frontier', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-oi-bo-dau-roi', 'Mẹ Ơi Bố Đâu Rồi!', 'Making Family', 'https://phimimg.com/upload/vod/20251222-1/a1bcc767e61711d93c3c849c1701adb0.jpg', 'https://phimimg.com/upload/vod/20251222-1/da80238daf91fdb75c352857effc890c.jpg', '<p>Trong thời đại ngày nay, nhiều người phụ nữ chọn cách trở thành mẹ đơn thân thay vì lập gia đình. Không nằm ngoài xu hướng, Go Mi Yeon (diễn viên Kim Ha Neul) đã quyết định thụ tinh nhân tạo để xây dựng cuộc sống của riêng mình. Đối với Mi Yoen, gia đình của cô và con trai Tae Bong (diễn viên nhí Mason Moon) là một tổ ấm hoàn hảo, bởi cô có thể cân bằng được công việc bận rộn ở đài truyền hình và lo lắng cho con. Kế thừa tính cách của mẹ, Tae Bong là một cậu bé rất lanh lợi và hiểu chuyện. Trong một lần cô giáo giao bài tập Mỹ thuật với đề tài: Vẽ gia đình của mình, cậu bé tinh nghịch đã vẽ hình ảnh mẹ bên cạnh một con tinh trùng to tướng. Mặc dù vậy, Tae Bong vẫn không ngừng thắc mắc về bố của mình. Một ngày, cậu bé phát hiện ra bố mình là người Trung Quốc, Tae Bong lém lỉnh quyết định rời Hàn Quốc để tìm bố. Đến đây, Tae Bong tìm thấy một người đàn ông độc thân, giàu có muốn tự lập khỏi gia đình để theo đuổi đam mê nghệ thuật. Cậu bé khẳng định đây chắc chắn là người bố mà mình tìm kiếm nên đã tìm mọi cách để tác hợp cho mẹ. Như một cầu nối đáng yêu, Tae Bong đã tạo nên mối nhân duyên dành cho hai người. Những rắc rối trong cuộc sống của người lớn được giải quyết một cách êm đẹp nhờ vào&nbsp; sự giúp đỡ của Tae Bong. Cậu bé cũng giúp mẹ và bố nhận ra được ý nghĩa của một gia đình trọn vẹn giữa cuộc sống bộn bề.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Trị Đình","avatar":""},{"name":"Kim Ha Neul","avatar":""},{"name":"Manson Mun","avatar":""},{"name":"Lưu Tùng Nhân","avatar":""},{"name":"Uyển Quỳnh Đan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["幸福家庭打造计划","Making Family","메이킹 패밀리"]', 1784690324409);
