INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kimmy-bat-bai-phan-2', 'Kimmy Bất Bại (Phần 2)', 'Unbreakable Kimmy Schmidt (Season 2)', 'https://phimimg.com/upload/vod/20251220-1/b16df1b42ecefa4ab974d27afbcfa5c2.jpg', 'https://phimimg.com/upload/vod/20251220-1/48754ef49f46303d56702d2479c3f6de.jpg', '<p>Khi một người phụ nữ được giải cứu khỏi một giáo phái ngày tận thế và đặt chân đến thành phố New York, cô phải học cách thích nghi với một thế giới mà cô từng nghĩ rằng không còn tồn tại nữa.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 10, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ellie Kemper","avatar":""},{"name":"Tituss Burgess","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Carol Kane","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["打不倒的金咪","언브레이커블 키미 슈미트","언브레이커블 키미슈미트","Unbreakable Kimmy Schmidt"]', 1784690324409);
