INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-vu-the-ky-2', 'Phi Vụ Thế Kỷ 2', 'Now You See Me 2', 'phi vụ thế kỷ 2 now you see me 2 jesse eisenberg mark ruffalo woody harrelson morgan freeman dave franco daniel radcliffe lizzy caplan michael caine jay chou sanaa lathan david warshofsky tsai chin richard laing henry lloyd-hughes brick patrick zach gerard ben lamb james now you see me: the second act nysm2 mestres da ilusão 2 truque de mestre o segundo ato 나우 유씨 미 2 insaisissable 2 - now you see me 2 グランド・イリュージョン 見破られたトリック phi vụ thế kỷ 2 非常盜2 now you see me 2 ahora me ves: 2 اکنون مرا میبینی 2 insaisissables 2 truque de mestre: o segundo ato truque de mestre 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-sieu-sao-2016', 'Học Viện Siêu Sao', 'Super Star Academy', 'https://phimimg.com/upload/vod/20251203-1/11be5f8de62d8b382f89122341b5b329.jpg', 'https://phimimg.com/upload/vod/20251203-1/5ff2c6c2df40150c9dc352f1717e4001.jpg', '<p>Phim kể về một thế giới song song dựa theo năng lực của các chòm sao hoàng đạo làm tiêu chuẩn cao nhất. Ở thế giới này, chòm sao Xử Nữ không được mọi người chào đón. Một đôi vợ chồng vì muốn nâng cao chất lượng cuộc sống trong tương lai nên mong muốn sinh một đứa con chòm sao Thiên Bình. Không may người mẹ sinh non, đã sinh ra một bé gái chòm sao Xử Nữ, từ nhỏ đã bị mọi người xa lánh. Bỗng nhiên một ngày cô phát hiện ra mình có năng lực lạ thường và được Học Viện Siêu Sao tuyển nhận nhập học.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Vương Ngọc Văn","avatar":""},{"name":"Bạch Thư","avatar":""},{"name":"Ngũ Gia Thành","avatar":""},{"name":"Bành Chúc Việt","avatar":""},{"name":"Từ Tiểu Lộ","avatar":""},{"name":"Cốc Gia Thành","avatar":""},{"name":"Quách Tử Phàm","avatar":""},{"name":"Hồng Thần","avatar":""},{"name":"Triệu Lệ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Super Star Academy","超星星学园"]', 1784690324409);
