INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-hinh-thanh-am', 'Dáng Hình Thanh Âm', 'A Silent Voice: The Movie', 'https://phimimg.com/upload/vod/20251116-1/abe4c53c1d48e2c7d2f5d1508762553d.jpg', 'https://phimimg.com/upload/vod/20251116-1/72eaede3650c1d21475c58f61021b6e8.jpg', '<p>Nishimiya Shouko, một cô bé bị điếc từ nhỏ, đã chuyển trường vào lớp của cậu bé Ishida Shouya. Để thỏa mãn sự tò mò của mình, cậu bé Shouya đã khơi mào trò bắt nạt Shouko vì tật khiếm thính. Trong một lần bắt nạt quá đà, Shouko đã bị chảy máu tai, và sau đó cô bé phải tiếp tục chuyển trường. Shouya, thay cho Shouko, bị cả lớp tẩy chay và bắt nạt. Mãi cho tới khi bước vào cao trung, Shouya, bị hành hạ và ân hận bởi những gì mình đã làm trong quá khứ, quyết định rằng cậu phải gặp lại Shouko một lần nữa. Shouya muốn bù đắp lại những tổn thương mà cậu đã gây ra cho Shouko và thực lòng muốn làm bạn với cô bé.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Miyu Irino","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Yuki Kaneko","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Mayu Matsuoka","avatar":""},{"name":"Sachiko Kojima","avatar":""},{"name":"Hana Takeda","avatar":""},{"name":"Fuminori Komatsu","avatar":""},{"name":"Ikuko Tani","avatar":""},{"name":"Erena Kamata","avatar":""},{"name":"Ayano Hamaguchi","avatar":""},{"name":"Ryunosuke Watanuki","avatar":""},{"name":"Ryo Nishitani","avatar":""},{"name":"Takuya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca59