INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-ngoai-hanh-tinh', 'Chiến Binh Ngoài Hành Tinh', 'Max Steel', 'https://phimimg.com/upload/vod/20251114-1/a672048235735ceb014c5cda844d346c.jpg', 'https://phimimg.com/upload/vod/20251114-1/770508f821bf358489a6cef364b4ddcb.jpg', '<p>Phim Chiến Binh Ngoài Hành Tinh - Max Steel 2016: Một câu chuyện độc đáo về một nhà thám hiểm 16 tuổi Max McGrath cùng một bạn đồng hành ngoài hành tinh Steel. Mặc dù tính tình hay đối lập nhau nhưng họ dần khám phá ra một bí mật chấn động trên hành trình của mình và khi đó, họ buộc phải kết hợp với nhau để trở thành siêu anh hùng Max Steel để cứu lấy thế giới trước nhanh vuốt kẻ ác.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Ben Winchell","avatar":""},{"name":"Josh Brener","avatar":""},{"name":"Ana Villafañe","avatar":""},{"name":"Andy García","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Mike Doyle","avatar":""},{"name":"Brandon Larracuente","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["鋼鐵麥斯","鋼鐵騎士","Max Steel"]', 1784690324409);
