INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tam-dia', 'Hỏa Tâm Địa', 'Trash Fire', 'https://phimimg.com/upload/vod/20251114-1/694e4b2cd464abaee5f271989f0871d0.jpg', 'https://phimimg.com/upload/vod/20251114-1/78d441356a53d7254b32e0fde9f8ebf6.jpg', '<p>Từng có một quá khứ bi kịch khi cha mẹ chết cháy còn em gái bị bỏng nặng sau một vụ hỏa hạn, Owen thường xuyên có những dấu hiệu loạn trí, hành xử thì vô cùng bạo lực. Mọi căng thẳng đổ dồn đến cao trào, khi Isabel mang thai đứa con của Owen. May mắn thay, Owen đồng ý chịu trách nhiệm, và cô gái trẻ chuyển đến sống cùng hắn và người bà Violet. Điều đáng nói là người bà này cũng có nhiều biểu hiện đáng rùng mình, về một mặt nào đó thì bà ta còn đáng sợ hơn Owen rất nhiều.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adrian Grenier","avatar":""},{"name":"Angela Trimbur","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"AnnaLynne McCord","avatar":""},{"name":"Sally Kirkland","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Ray Santiago","avatar":""},{"name":"Ezra Buzzington","avatar":""},{"name":"Molly McCook","avatar":""},{"name":"Alexa Hamilton","avatar":""},{"name":"Michael Laren","avatar":""},{"name":"Clayton Jackson","avatar":""},{"name":"Karl Schott","avatar":""},{"name":"Brayden Austin","avatar":""},{"name":"Ruby Lightfoot","avatar":""},{"name":"Sibyl Grego","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["트래쉬 파이어","Пожар на помой