INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-con-gai-ke-thu', 'Yêu Con Gái Kẻ Thù', 'Thinking Of You, Lu Xiang Bei', 'https://phimimg.com/upload/vod/20251112-1/8b69f145ed65a3163f70f0d636c1eb68.jpg', 'https://phimimg.com/upload/vod/20251112-1/ae739780559bd46ea93859607dd95f44.jpg', '<p>Bộ phim chủ yếu nói về câu chuyện tình yêu đầy trắc trở phức tạp giữa đại tiểu thư tập đoàn Đồng thị – Đồng Nhất Niệm với Lục Hướng Bắc.Lục Hướng Bắc – nhân vật của Lưu Khải Uy là giám đốc bộ phận tiêu thụ của tập đoàn Hoa Thái nổi tiếng, một người có tính cách lạnh lùng, không thích nói chuyện. Cả hai tai của anh từ nhỏ gần như bị điếc, thế nhưng anh vẫn dựa vào ý chí vượt qua, học được ngôn ngữ môi, biểu hiện ngày thường cũng không giống với người bình thường. Kế hoạch trả thù của Lục Hướng Bắc cuối cùng cũng có hiệu quả, làm cho Trầm Mạnh Đức bị lao lực quá độ phải vào bệnh viện. Khi thân phận được lôi ra ánh sáng, Hướng Bắc từ chức ở Hoa Thái và đầu quân cho tập đoàn Hoàn Mĩ của Đồng Tri Hàng.Thế nhưng Đồng Tri Hàng chính là kẻ thù lớn thứ hai của Lục gia, bởi vì ông ta, khiến cho Lục gia suy bại, ông ngoại anh cũng mù hai mắt. Lúc đó, mẹ Lương của Hướng Bắc phát hiện ung thư giai đoạn cuối. Anh càng kinh ngạc hơn vì tìm thấy bức thư mà mẹ ruột để lại. Hóa ra, điều mẹ ruột anh ta trước khi mất mong muốn chính là Hướng Bắc không cần trả thù người cha hay bất kì ai khác, không cần phải sống trong sự thù hận.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 12, 2016, 'Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Khải Uy","avatar":""},{"name":"Trương Lệ","avatar":""},{"name":"Lương Hựu Lâm","avatar":""},{"name":"Ngô Kiến Phi","avatar":""},{"name":"Trương Tử Huyên","avatar":""},{"name":"Trương Tuấn Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一念向北","Road to the North"]', 1784690324409);
