INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-con-gai-ke-thu', 'Yêu Con Gái Kẻ Thù', 'Thinking Of You, Lu Xiang Bei', 'yêu con gái kẻ thù thinking of you, lu xiang bei lưu khải uy trương lệ lương hựu lâm ngô kiến phi trương tử huyên trương tuấn ninh 一念向北 road to the north', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-la-tat-ca-2016', 'Bố Là Tất Cả', 'Father, I''ll Take Care Of You', 'https://phimimg.com/upload/vod/20251110-1/ef43a20b7aabd09f95d51a464451c23c.jpg', 'https://phimimg.com/upload/vod/20251110-1/412e138124ad5ccbfa82915ff6793bb2.jpg', '<p>Bộ phim kể về một cặp vợ chồng già dành cả đời để nuôi dạy bốn người con trở thành những đứa trẻ tự lập, mạnh mẽ. Khi cả bốn người con đều đã khôn lớn và ra ở riêng, hai vợ chồng nghĩ rằng giờ đây họ có thể bắt đầu lại cuộc sống của mình như những gì từng diễn ra trước khi lập gia đình và có con. Tuy nhiên, đúng lúc ước nguyện của họ sắp thành hiện thực thì cả bốn người con bất ngờ cùng quay trở lại ngôi nhà. Bộ phim cho thấy quá trình phát triển của bốn chị em ích kỷ, chỉ quan tâm đến bản thân mình, Bộ phim cũng cho thấy vấn đề của xã hội hiện tại ở Hàn Quốc, khi mà chi phí nhà ở tăng cao đã khuyến khích những cặp vợ chồng trẻ sống cùng với bố mẹ. Do vậy những phát sinh trong cuộc sống hàng ngày giữa những người trẻ lãng mạn với thế hệ cũ.</p>', 'Hoàn Tất (74/74)', 74, 'series', 'completed', 11, 2016, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jae-won","avatar":""},{"name":"Park Eun-bin","avatar":""},{"name":"Lee Tae-hwan","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Kim Yong-rim","avatar":""},{"name":"Na Moon-hee","avatar":""},{"name":"Lee Ye-won","avatar":""},{"name":"Choi Sun-ja","avatar":""},{"name":"Park Jin-su","avatar":""},{"name":"Kim Chang-wan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["爸爸，我来伺候你","Abeonim Jega Mosilgeyo","아버님 제가 모실게요"]', 1784690324409);
