INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-la-tu-thien-duong', 'Phép Lạ Từ Thiên Đường', 'Miracles From Heaven', 'https://phimimg.com/upload/vod/20251106-1/1c920202fc05b746ddaf890a25d8a532.jpg', 'https://phimimg.com/upload/vod/20251106-1/3d3c4c5db206625cc137ed3629372b24.jpg', '<p>Phim được dựa trên một cuốn sách ăn khách của người mẹ Cơ Đốc Christy Beam. Anna Beam vật lộn với hai chứng rối loạn nan y suốt nhiều năm liền. Do mức độ nghiêm trọng của bệnh tật, một lần Anna đã nói với mẹ rằng cô bé muốn lên thiên đàng và gặp Chúa.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Garner","avatar":""},{"name":"Kylie Rogers","avatar":""},{"name":"Martin Henderson","avatar":""},{"name":"Brighton Sharbino","avatar":""},{"name":"Courtney Fansler","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Eugenio Derbez","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Wayne Pére","avatar":""},{"name":"Kelly Collins Lintz","avatar":""},{"name":"Brandon Spink","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"Erica McGee","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Hannah Riley","avatar":""},{"name":"Zach Sale","avatar":""},{"name":"Gwe","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Miracles du Paradis","Miracles From Heaven: A Little Girl, Her Journey to Heaven, and Her Amazing Story of Healing","來自天堂的奇蹟","Mennyei csodák","Miracles from Heaven"]', 1784690324409);
