INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-tien-loi-nha-kim-phan-1', 'Cửa Hàng Tiện Lợi Nhà Kim (Phần 1)', 'Kim''s Convenience (Season 1)', 'https://phimimg.com/upload/vod/20251101-1/45102aa4384629531f390d27a65612b9.jpg', 'https://phimimg.com/upload/vod/20251101-1/1d313d2b3cfbb7adcfedf8fd807916b8.jpg', '<p>Trong khi kinh doanh tạp hóa ở Toronto, các thành viên trong một gia đình gốc Hàn ở Canada phải học cách cư xử với khách hàng, hòa hợp với nhau và với thế giới quanh họ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2016, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Paul Sun-Hyung Lee","avatar":""},{"name":"Nicole Power","avatar":""},{"name":"Jean Yoon","avatar":""},{"name":"Andrea Bang","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Andrew Phung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["金氏便利店","Il negozio dei Kim","Kim''s Convenience"]', 1784690324409);
