INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cua-hang-tien-loi-nha-kim-phan-1', 'Cửa Hàng Tiện Lợi Nhà Kim (Phần 1)', 'Kim''s Convenience (Season 1)', 'cửa hàng tiện lợi nhà kim (phần 1) kim''s convenience (season 1) paul sun-hyung lee nicole power jean yoon andrea bang simu liu andrew phung 金氏便利店 il negozio dei kim kim''s convenience', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngang-qua-the-gioi-cua-em', 'Ngang Qua Thế Giới Của Em', 'I Belonged To You', 'https://phimimg.com/upload/vod/20251030-1/2db470b706bf7a94ae7eacf2c679ee88.jpg', 'https://phimimg.com/upload/vod/20251030-1/497fabda184806b841d9ac6c67077dfa.jpg', '<p>Trần Mạt – người được gọi là “kẻ đáng ghét nhất thành phố”, mỗi ngày đều đấu khẩu với nữ DJ nổi tiếng Tiểu Dung, chẳng ai biết mối thù giữa họ bắt đầu từ đâu. Hai người anh em của Trần Mạt là Trư Đầu – “kẻ ngốc nhất thành phố”, và Mao Thập Bát – “người thuần khiết nhất thành phố”. Ba người tưởng rằng mình có thể sống tự do, nhưng rồi mỗi người đều gặp bước ngoặt lớn trong cuộc đời: Trần Mạt gặp cô gái bí ẩn Yêu Kê, Trư Đầu phải tổ chức một đám cưới đầy bi hài, còn Mao Thập Bát trải qua cuộc chia ly đau đớn nhất. Khi những giấc mơ, tình yêu và tình bạn lần lượt tan vỡ, Trần Mạt – người mất hết tất cả, lạc lối giữa cuộc đời – chỉ thật sự tìm thấy chính mình khi nghe lại một đoạn ghi âm “từ toàn thế giới của em”.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Siêu","avatar":""},{"name":"Bạch Bách Hà","avatar":""},{"name":"Dương Dương","avatar":""},{"name":"Trương Thiên Ái","avatar":""},{"name":"Nhạc Vân Bằng","avatar":""},{"name":"Đỗ Quyên","avatar":""},{"name":"Lưu Nghiên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Belonged To You","Ngang qua the gioi cua em","종니적전세계로과","从你的全世界路过"]', 1784690324409);
