INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-cua-the-gioi-2016', 'Góc Khuất Của Thế Giới', 'In This Corner Of The World', 'https://phimimg.com/upload/vod/20251030-1/e984d77796415da7cfddd56eafc3b53b.jpg', 'https://phimimg.com/upload/vod/20251030-1/a3d309df81357f33e0d18c498765b3a1.jpg', '<p>Một phụ nữ 18 tuổi đầy tinh thần đã kết hôn với một người đàn ông mà cô ấy hầu như không biết khi cô ấy chiến đấu với cuộc sống hàng ngày ở Hiroshima trong Thế chiến thứ hai.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Non","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Natsuki Inaba","avatar":""},{"name":"Minori Omi","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Nanase Iwai","avatar":""},{"name":"Shigeru Ushiyama","avatar":""},{"name":"Mayumi Shintani","avatar":""},{"name":"Tsuyoshi Koyama","avatar":""},{"name":"Masumi Tsuda","avatar":""},{"name":"Kanata Omori","avatar":""},{"name":"Kotone Tachibana","avatar":""},{"name":"Hiromi Seta","avatar":""},{"name":"Kikuyo Semi","avatar":""},{"name":"Nozomu Sasaki","avatar":""},{"name":"Tomoko Shiota","avatar":""},{"name":"Hisako Kyoda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["To All the Corners of the World","Kono sekai no katasumi ni","Góc khuất của thế giới","I dette hjørne af verden","A világ innenső végén","In This Corner (and Other Corners) of the World","この世界の（さらにいくつもの）片隅に","在这世界的（还有更多的）角落","Dans un recoin de ce monde","この世界の片隅に：2016","Kono Sekai no Sara ni Ikutsumo no Katasumi ni","이 세상의 (그리고 다른 세상의) 한구석에","In This Corner and Other Corners of the World","この世界の片隅に"]', 1784690324409);
