INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('goc-khuat-cua-the-gioi-2016', 'Góc Khuất Của Thế Giới', 'In This Corner Of The World', 'góc khuất của thế giới in this corner of the world non yoshimasa hosoya natsuki inaba minori omi daisuke ono megumi han nanase iwai shigeru ushiyama mayumi shintani tsuyoshi koyama masumi tsuda kanata omori kotone tachibana hiromi seta kikuyo semi nozomu sasaki tomoko shiota hisako kyoda to all the corners of the world kono sekai no katasumi ni góc khuất của thế giới i dette hjørne af verden a világ innenső végén in this corner (and other corners) of the world この世界の（さらにいくつもの）片隅に 在这世界的（还有更多的）角落 dans un recoin de ce monde この世界の片隅に：2016 kono sekai no sara ni ikutsumo no katasumi ni 이 세상의 (그리고 다른 세상의) 한구석에 in this corner and other corners of the world この世界の片隅に', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bo-than-yeu', 'Người Bố Thân Yêu', 'Daddy Dearest', 'https://phimimg.com/upload/vod/20251023-1/145b8ddec1283e56c5d1fe6b90c007f8.jpg', 'https://phimimg.com/upload/vod/20251023-1/0c74f356b0f518bd37cbc17753da543b.jpg', '<p>Người Bố Thân Yêu xoay quanh câu chuyện gia đình đầy cảm xúc về hai người cha trẻ tuổi trở lại cuộc sống của con cái mình và học cách trở thành những người cha tốt hơn. Kuk Chi Keung, người kinh doanh lắm suy nghĩ, đối mặt với thách thức lớn khi người vợ cũ của anh tái hôn, khiến anh trở thành một người cha đơn thân khi con trai nhỏ của anh, Kuk Siu Nam, chuyển về sống cùng anh. Anh hoàn toàn bối rối khi phải làm cha đối với con trai nhưng nhận sự giúp đỡ từ Chu Lai Fa, người điều hành một trung tâm giáo dục, và từ đó từ từ học được điều gì là cần thiết để trở thành một người cha tốt. Kiến trúc sư nổi tiếng Sheung Nim Syu là một người nghiện công việc, để trách nhiệm nuôi dạy con cái cho vợ mình Ho Lok Chi và bố mình, Sheung San. Khi vợ và bố cô đụng độ trong việc nuôi dạy con cái, Nim Syu không có lựa chọn nào khác ngoài việc đổi vai với vợ mình và học cách trở thành người cha ở nhà chăm sóc con gái và con trai. Cùng nhau, hai người cha đầy khó khăn học cách trở thành cha mẹ tốt hơn đồng thời luôn ủng hộ lẫn nhau. Người Bố Thân Yêu mang đến cho khán giả những giây phút lắng đọng cùng nhiều tình huống hài hước đầy cảm xúc. Với sự tham gia của các diễn viên hàng đầu như 李思捷, Jason Chan Chi-San, Mandy Wong, Candice Chiu, 陳煒, 古明華, Pat Poon, 蘇恩磁, 魯振順, và 林景程, bộ phim hứa hẹn mang đến cho khán giả nhiều cung bậc cảm xúc khác nhau. Với những tình tiết đầy xúc động và thông điệp sâu sắc về tình cha mẹ và tình gia đình, Người Bố Thân Yêu chắc chắn sẽ là bộ phim thú vị mà bạn không nên bỏ lỡ trên Motchilltv. Hãy cùng xem để hiểu thêm về hành trình chăm sóc con cái và tìm hiểu cách mà hai người cha này vượt qua mọi khó khăn để trở thành những bậc cha tốt.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 2016, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"Jason Chan Chi-San","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Candice Chiu","avatar":""},{"name":"Alice Chan","avatar":""},{"name":"Jerry Koo Ming-Wah","avatar":""},{"name":"Pat Poon","avatar":""},{"name":"Cecilia So Yan-Chee","avatar":""},{"name":"Henry Lo","avatar":""},{"name":"King Lam","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Poon Fong-Fong","avatar":""},{"name":"Snow Suen","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Daddy Dearest","爸B有话儿","超能老豆"]', 1784690324409);
