INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song', 'Sống', 'Raw', 'https://phimimg.com/upload/vod/20251023-1/7b4ee4dd7b741ed9bee97d7978e31389.jpg', 'https://phimimg.com/upload/vod/20251023-1/71fca5e683ef78d48d4c3c59007f084e.jpg', '<p>Một phụ nữ trẻ, học tập để trở thành một bác sĩ thú y, phát triển sự thèm ăn thịt người.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Garance Marillier","avatar":""},{"name":"Ella Rumpf","avatar":""},{"name":"Rabah Nait Oufella","avatar":""},{"name":"Laurent Lucas","avatar":""},{"name":"Joana Preiss","avatar":""},{"name":"Bouli Lanners","avatar":""},{"name":"Marion Vernoux","avatar":""},{"name":"Thomas Mustin","avatar":""},{"name":"Marouan Iddoub","avatar":""},{"name":"Jean-Louis Sbille","avatar":""},{"name":"Benjamin Boutboul","avatar":""},{"name":"Virgil Leclaire","avatar":""},{"name":"Anna Solomin","avatar":""},{"name":"Sophie Breyer","avatar":""},{"name":"Daniel Utegenova","avatar":""},{"name":"Bérangère M","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Grave","舐血成人礼","Nyers","로우","RAW～少女のめざめ～"]', 1784690324409);
