INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-bong-dem', 'Sát Thủ Bóng Đêm', 'Assassin''s Creed', 'https://phimimg.com/upload/vod/20251020-1/8295fcdf843ec4fb8da0c501945848e4.jpg', 'https://phimimg.com/upload/vod/20251020-1/67cc12833efff712e81a83b5463f3b12.jpg', '<p>Nhờ vào một công nghệ cải tiến có thể phá vỡ những kí ức trong cấu trúc gien, Callum Lynch đã có thể làm sống lại kí ức về những cuộc phiêu lưu của tổ tiên mình – Aguilar – Tây Ban Nha vào thế kỉ 15. Thông qua kí ức này, Callum đã phát hiện rằng mình là hậu duệ của một hội kín bí ẩn mang tên Assassins và đồng thời tích lũy được hàng loạt kiến thức, kĩ năng không tưởng để đối đầu với một tổ chức đầy áp bức và hùng mạnh ngày nay – Hiệp Sĩ Dòng Đền.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Fassbender","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Ariane Labed","avatar":""},{"name":"James Sobol Kelly","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Khalid Abdalla","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Carlos Bardem","avatar":""},{"name":"Javier Gutiérrez","avatar":""},{"name":"Hovik Keuchker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075d