INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-jeng-jeng-jeng', 'Upin & Ipin: Jeng Jeng Jeng!', 'Upin & Ipin: Jeng Jeng Jeng!', 'https://phimimg.com/upload/vod/20251018-1/01d54da76ed80221967c44a7a64131bf.jpg', 'https://phimimg.com/upload/vod/20251018-1/fb0338cde2b271c30d809ea285281bd3.jpg', '<p>Một cô bé mồ côi 10 tuổi tên Aqish có khả năng đặc biệt là có thể giao tiếp với hai nhân vật hoạt hình yêu thích của mình — Upin và Ipin. Tuy nhiên, thế giới của cô bé không còn bình yên khi trại trẻ mồ côi mà cô yêu quý sắp bị một doanh nhân tàn nhẫn thu hồi. Aqish nhờ đến sự giúp đỡ của hai người bạn Upin và Ipin để tìm lại ngôi sao nhạc rock nổi tiếng một thời, Awie, với hy vọng anh có thể giúp cô gây quỹ cứu lấy mái ấm của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2016, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Puteri Balqis","avatar":""},{"name":"Asyiela Putri","avatar":""},{"name":"Nur Fathiah Diaz","avatar":""},{"name":"Sara Ali","avatar":""},{"name":"Gambit Saifullah","avatar":""},{"name":"Awie","avatar":""},{"name":"Remy Ishak","avatar":""},{"name":"David Teo","avatar":""},{"name":"Burhanuddin Radzi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["UPIN & IPIN :  JENG JENG JENG!","Upin & Ipin Jeng Jeng Jeng!","Upin & Ipin: Jeng Jeng Jeng!"]', 1784690324409);
