INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-goi-tinh-nhan', 'Thư Gởi Tình Nhân', 'Correspondence', 'https://phimimg.com/upload/vod/20251015-1/0c91176db0f23e91bccf974706becc5e.jpg', 'https://phimimg.com/upload/vod/20251015-1/81e6f4a6d306ae63b97061e850ee7bb0.jpg', '<p>Một y tá từ Ukraine tìm kiếm một cuộc sống tốt đẹp hơn ở phương Tây, trong khi một nhân viên bảo vệ thất nghiệp từ Áo hướng về phía Đông vì lý do tương tự. Cả hai đều đang tìm kiếm việc làm, một khởi đầu mới, một sự tồn tại, đấu tranh để tin vào bản thân, để tìm thấy ý nghĩa trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Jeremy Irons","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Simon Johns","avatar":""},{"name":"Shauna Macdonald","avatar":""},{"name":"Simon Meacock","avatar":""},{"name":"James Warren","avatar":""},{"name":"Oscar Sanders","avatar":""},{"name":"Paolo Calabresi","avatar":""},{"name":"Anna Savva","avatar":""},{"name":"Irina Kara","avatar":""},{"name":"James Bloor","avatar":""},{"name":"Philip Gascoyne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Te amaré eternamente","Lembranças de um Amor Eterno","La correspondencia","Correspondence","La correspondència","愛情天文學","Листування","Двоє у всесвіті","Thư Gởi Tình Nhân","Surematud armastuskirjad","La corrispondenza","Θα σε περιμένω, πάντα","ある天文学者の恋文","Mīlestības vēstules","Amžinos meiles laiškai","Korespondencja","A Correspondência","Двое во вселенной"]', 1784690324409);
