INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-goi-tinh-nhan', 'Thư Gởi Tình Nhân', 'Correspondence', 'thư gởi tình nhân correspondence jeremy irons olga kurylenko simon johns shauna macdonald simon meacock james warren oscar sanders paolo calabresi anna savva irina kara james bloor philip gascoyne te amaré eternamente lembranças de um amor eterno la correspondencia correspondence la correspondència 愛情天文學 листування двоє у всесвіті thư gởi tình nhân surematud armastuskirjad la corrispondenza θα σε περιμένω, πάντα ある天文学者の恋文 mīlestības vēstules amžinos meiles laiškai korespondencja a correspondência двое во вселенной', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-dem-2016', 'Kẻ Săn Đêm', 'Nocturnal Animals', 'https://phimimg.com/upload/vod/20251014-1/a6bdbd55718d2fddfbb507a9522bfe4e.jpg', 'https://phimimg.com/upload/vod/20251014-1/6024dc8a4e7ef09af9c6614268030db1.jpg', '<p>Kẻ Săn Đêm là một bộ phim kinh di do Mỹ sản xuất vừa được ra mắt năm 2016 xoay quanh câu chuyện về những ám ảnh mà cô nàng Susan Morrow chủ nhân của phòng triển lãm nghệ thuật gặp phải. Trong phim Susan Morrow đã phát hiện ra những bí ẩn đằng sau cuốn tiểu thuyết mà chồng cô để lại và đó cũng như một lời một lời đe dọa cho sự tra thù của anh chàng này.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Ellie Bamber","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Robert Aramayo","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Bobbi Salvör Menuez","avatar":""},{"name":"Imogen Waterhouse","avatar":""},{"name":"Franco Vega","avatar":""},{"name":"Zawe Ashton","avatar":""},{"name":"Ev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Tony and Susan","Нічні тварини","คืนทมิฬ","Nocturnal Animals"]', 1784690324409);
