INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-tam-giac-vang', 'Điệp Vụ Tam Giác Vàng', 'Operation Mekong', 'https://phimimg.com/upload/vod/20251014-1/0ddb1aef941239a852546a4d1f20f2df.jpg', 'https://phimimg.com/upload/vod/20251014-1/9dce7275cbc753ae543e86488968797b.jpg', '<p>Ngày 5/10/2011, 13 thuyền viên Trung Quốc bị sát hại dã man tại khu vực Tam Giác Vàng trên sông Mê Kông. Cảnh sát khu vực phát hiện 900.000 viên ma túy đá trên thuyền. Được lệnh từ Chính Phủ, Tổng đội trưởng Vân Nam, Cao Cương (Trương Hàm Dư) cùng một đội lính tinh nhuệ sang Thái Lan để gặp nhân viên tình báo Tân Vũ (Bành Vu Yến) nhằm điều tra chân tướng sự việc. Từ đây những bí mật của lãnh địa không luật pháp và tình người dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 24, 2016, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Zhang Hanyu","avatar":""},{"name":"Eddie Peng Yu-Yan","avatar":""},{"name":"Joyce Feng","avatar":""},{"name":"Wu Xudong","avatar":""},{"name":"Zhan Liguo","avatar":""},{"name":"Liu Xianda","avatar":""},{"name":"Sun Chun","avatar":""},{"name":"Zhao Jian","avatar":""},{"name":"Shi Zhanjie","avatar":""},{"name":"Jonathan Wu","avatar":""},{"name":"Chen Baoguo","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Mandy Wei","avatar":""},{"name":"Li Jiaxuan","avatar":""},{"name":"Hao Wenting","avatar":""},{"name":"Pavarit Mongkolpisit","avatar":""},{"name":"Carl Ng Ka-Lung","avatar":""},{"name":"Wa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae