INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-thanh-trai', 'Anh Hùng Thành Trại', 'A Fist Within Four Walls', 'https://phimimg.com/upload/vod/20251010-1/ca649f84598d481adb354b202413165f.jpg', 'https://phimimg.com/upload/vod/20251010-1/5fa90bdd8970167b764d4289801eb969.jpg', '<p>Được kỳ vọng là bộ phim truyền hình thuộc thể loại hành vộng võ thuật đặc sắc nhất trong những năm trở lại đây của đài TVB, Anh Hùng Thành Trại hi vọng sẽ mang tới những làn gió mới cho phim truyền hình Hồng Kông khi nhiều diễn viên tên tuổi có xu hướng chuyển qua trung quốc đại lục để đóng phim, đặc biệt là thời điểm mà thể loại ngôn tình, mơ mộng đang phát triển ngày càng mạnh mẽ, tuy nhiên phim điện ảnh của Hồng Kông thì vẫn giữ được những vị thế rất lớn của mình. Nếu bạn là tín đồ của dòng phim võ thuật thì chắc chắn 28 tập phim A Fist Within Four Walls sẽ mang tới cho bạn nhiều sự bất ngờ không chỉ về cốt truyện, nội dung phim mà còn những cảnh hành động được dàn dựng công phu.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 16, 2016, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ruco Chan Chin-Pang","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"Nancy Wu","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Yuen Qiu","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Moon Lau","avatar":""},{"name":"Jazz Lam Tsz-Sin","avatar":""},{"name":"Carlo Ng Ka-Lok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["A Fist Within Four Walls","Anh Hùng Thành Trại","城寨英雄"]', 1784690324409);
