INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-ep-buoc', 'Sự Ép Buộc', 'Compulsion', 'https://phimimg.com/upload/vod/20251009-1/0d1f414e2fb4ca370406488a4ffe1dcc.jpg', 'https://phimimg.com/upload/vod/20251009-1/3d308bf9d041d1032279cdad7c2efce1.jpg', '<p>Compulsion, còn được gọi là Sadie, là một bộ phim kinh dị khiêu dâm đồng sản xuất quốc tế năm 2016 do Craig Goodwill đạo diễn. Phim có sự tham gia của Lio Tipton, Jakob Cedergren và Marta Gastini. Phim được công chiếu lần đầu tại Liên hoan phim Torino vào tháng 11 năm 2016.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Lio Tipton","avatar":""},{"name":"Marta Gastini","avatar":""},{"name":"Jakob Cedergren","avatar":""},{"name":"Valentin Merlet","avatar":""},{"name":"Jan Bijvoet","avatar":""},{"name":"Magdalena Grochowska","avatar":""},{"name":"Anita Kravos","avatar":""},{"name":"Nina Seničar","avatar":""},{"name":"Leonardo Messerklinger","avatar":""},{"name":"Franco Barbero","avatar":""},{"name":"Luca Busnengo","avatar":""},{"name":"Marco Tunesi","avatar":""},{"name":"Denitza Diakovska","avatar":""},{"name":"Cristiano Omedè","avatar":""},{"name":"Mélanie Saint-Arnaud Duboi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Sadie","Sadie - Dunkle Begierde","爱欲圆舞曲","Compulsion"]', 1784690324409);
