INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-ep-buoc', 'Sự Ép Buộc', 'Compulsion', 'sự ép buộc compulsion lio tipton marta gastini jakob cedergren valentin merlet jan bijvoet magdalena grochowska anita kravos nina seničar leonardo messerklinger franco barbero luca busnengo marco tunesi denitza diakovska cristiano omedè mélanie saint-arnaud duboi sadie sadie - dunkle begierde 爱欲圆舞曲 compulsion', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-du-hanh', 'Người Du Hành', 'Passengers', 'https://phimimg.com/upload/vod/20251008-1/166e2a60f243b82d6452e0c3f46838cd.jpg', 'https://phimimg.com/upload/vod/20251008-1/1bcb3d43e23f6c64b78acb49cddae095.jpg', '<p>Passengers lấy bối cảnh trên một con tàu chở hơn 5000 con người thực hiện một chuyến hành trình dài tới hành tinh mới. Một sự cố xảy ra dẫn đến việc có hai hành khách thức tỉnh sớm hơn dự định, đánh dấu sự chớm nở của một chuyện tình giữa không gian. Bất ngờ tỉnh dậy sớm hơn dự định, Jim phát hiện ra mình chỉ mới 30 tuổi mà hành trình chuyến tàu đến hành tinh mới vẫn còn đến tận 90 năm. Jim quyết tận hưởng cuộc sống xa hoa trên phi thuyền. Anh đánh thức Aurora ngay sau đó. Trong một lần hẹn hò, Jim và Aurora phát hiện ra con tàu đang lâm vào một tình thế ngặt nghèo. Khi tính mạng của mọi người trên chuyến tàu đang bị đe dọa, Jim quyết định bước ra ngoài vùng không gian để tìm cách cứu lấy cả đoàn, cũng là cứu lấy tình yêu của đời mình.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jennifer Lawrence","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Andy García","avatar":""},{"name":"Vince Foster","avatar":""},{"name":"Kara Flowers","avatar":""},{"name":"Conor Brophy","avatar":""},{"name":"Julee Cerda","avatar":""},{"name":"Aurora Perrineau","avatar":""},{"name":"Lauren Farmer","avatar":""},{"name":"Emerald Mayne","avatar":""},{"name":"Kristin Brock","avatar":""},{"name":"Tom Ferrari","avatar":""},{"name":"Quansae Rutledge","avatar":""},{"name":"Desmond Reid","avatar":""},{"name":"Emma Clarke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Пасажири","Pasagjerët","Passengers - Es Gibt Einen Grund Warum Sie Aufgewacht Sind","Yoʻlovchilar","Passengers 3D","Passagers","Người Du Hành","太空潜航者","Passengers"]', 1784690324409);
