INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuc-lanh-cho-the-gioi-tuyet-voi-nay-phan-1', 'Phúc Lành Cho Thế Giới Tuyệt Vời Này (Phần 1)', 'KonoSuba God''s Blessing On This Wonderful World! (Season 1)', 'phúc lành cho thế giới tuyệt vời này (phần 1) konosuba god''s blessing on this wonderful world! (season 1) jun fukushima sora amamiya rie takahashi ai kayano konosuba: as bênçãos de deus neste mundo maravilhoso! konosuba: abençoado mundo maravilhoso! 素晴 素晴3 bůh žehnej tomuto nádhernému světu konosuba: un mundo maravilloso! konosuba - sois béni monde merveilleux ! konosuba このすば kono subarashii sekai ni syukufuku wo! kono subarashii sekai ni shukufuku wo! 3 kono subarashii sekai ni shukufuku wo! kono subarashii sekai ni shukufuku o! 3 kono subarashii sekai ni syukufuku wo! 2 kono subarashii sekai ni syukufuku wo! 3 코노스바 konosuba: ¡una bendición para este maravilloso mundo! богиня благословляет этот прекрасный мир коносуба богиня благословляет этот замечательный мир! да благословят боги сей расчудесный мир! этот замечательный мир! 美好世界 為美好的世界獻上祝福 give blessings to this wonderful world! konosuba - god''s blessing on this wonderful world!! konosuba: god''s blessing on this wonderful world この素晴らしい世界に祝福を！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-dem-toi-loi', 'Bóng Đêm Tội Lỗi', 'Manhattan Night', 'https://phimimg.com/upload/vod/20250919-1/31a0d550e7f62f77f72a119a0f0290c8.jpg', 'https://phimimg.com/upload/vod/20250919-1/d5ad3643bd7e87fb6b3b373e98ae84f4.jpg', '<p>Phóng viên Porter Wren (Adrien Brody) vốn luôn tìm những scandal nên khi một cô gái lạ mang đến vụ án bí ẩn, anh đã không thể chối từ. Và đó cũng là khởi nguồn của vòng xoáy cám dỗ nuốt chửng anh.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Yvonne Strahovski","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"Jennifer Beals","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Linda Lavin","avatar":""},{"name":"Kevin Breznahan","avatar":""},{"name":"Thomas Bair","avatar":""},{"name":"Will Beinbrink","avatar":""},{"name":"Frank Deal","avatar":""},{"name":"Raul Aranas","avatar":""},{"name":"Chinasa Ogbuagu","avatar":""},{"name":"Uzimann","avatar":""},{"name":"Amelie McKendry","avatar":""},{"name":"Jahni Brown","avatar":""},{"name":"Alex Echevarria","avatar":""},{"name":"Karin Collison","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Manhattan Nocturne","Манхэттенская ночь","Журналист [Manhattan Night (2015)]","Manhattan Night"]', 1784690324409);
