INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-toi-thuong', 'Phù Thuỷ Tối Thượng', 'Doctor Strange', 'https://phimimg.com/upload/vod/20250625-1/024795a342c636e4f673591f2e2c73b9.jpg', 'https://phimimg.com/upload/vod/20250625-1/49251d06f817df134b460eec552c75c5.jpg', '<p>DOCTOR STRANGE là câu chuyện về bác sĩ Giải Phẫu Thần Kinh tên Stephen Vincent Strange. Cuộc đời anh thay đổi từ sau một tai nạn xe hơi khủng khiếp. Sau tai nạn đó, Stephen nhận ra mình có những năng lực bí ẩn cũng như biết thêm về thế giới ma thuật huyền bí. Từ một vị bác sĩ bình thường, Stephen Strange dần nhận được nhiều siêu năng lực để cứu trái đất khỏi những tai họa.</p>', 'Full', 1, 'single', 'completed', 20, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Benedict Cumberbatch","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Zara Phythian","avatar":""},{"name":"Alaa Safi","avatar":""},{"name":"Katrina Durden","avatar":""},{"name":"Topo Wresniwiro","avatar":""},{"name":"Umit Ulgen","avatar":""},{"name":"Linda Louise Duan","avatar":""},{"name":"Mark Anthony B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Marvel''s Doctor