INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-kinh-hoang-2', 'Ám Ảnh Kinh Hoàng 2', 'The Conjuring 2', 'https://phimimg.com/upload/vod/20250515-1/af25811747f5aa8aa15fb713d19aac4b.jpg', 'https://phimimg.com/upload/vod/20250515-1/e94be5187aa19a0f91e1f9f14a5e351f.jpg', '<p>Đây là phần hai của phim năm 2013, The Conjuring, với Patrick Wilson và Vera Farmiga tiếp tục thủ vai hai thám tử săn ma Ed và Lorraine Warren. Phim theo chân họ sang Anh quốc để giúp đỡ gia đình Hodgson khi họ bị tấn công bởi hàng loạt các hiện tượng ma ám được biết đến về sau dưới tên Enfield Poltergeist (hiện tượng ma ám Enfield) tại chính căn nhà của họ vào năm 1977. Phim sáng tạo dựa trên các ghi chép và tư liệu có thật.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Patrick Wilson","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Madison Wolfe","avatar":""},{"name":"Frances O''Connor","avatar":""},{"name":"Lauren Esposito","avatar":""},{"name":"Benjamin Haigh","avatar":""},{"name":"Patrick McAuley","avatar":""},{"name":"Sterling Jerins","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Simon Delaney","avatar":""},{"name":"Franka Potente","avatar":""},{"name":"Bob Adrian","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Chris Royds","avatar":""},{"name":"Abhi Sinha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Conjuring 2: The Enfield Poltergeist","The Conjuring 2: T