INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-so-tu-than-khai-sang-the-gioi-moi', 'Cuốn Sổ Tử Thần: Khai Sáng Thế Giới Mới', 'Death Note: Light Up The NEW World', 'https://phimimg.com/upload/vod/20250903-1/9c0c2734fb92c950c20b07934dfcdddc.jpg', 'https://phimimg.com/upload/vod/20250903-1/41973069d8fb00682493cc8b8c36e3e9.jpg', '<p>Cuộc chiến của Kira và L đã trôi qua được mười năm. Một lần nữa, Tử thần lại gửi Death Note xuống nhân gian, thế giới lại sắp hứng chịu một trận phong ba nữa. Nhân vật chính Tsukuru là thành của đội đặc nhiệm đặc biệt Death Note gồm 6 thành viên. Trong đó có cả Matsuda, là người đã từng tham gia vụ án của Kira 10 năm trước. Những vụ giết người bắt đầu diễn ra ở Wall Street (Mỹ), Shibuya (Nhật Bản) và nhiều nơi khác. Thám tử tư hàng đầu thế giới Ryuzaki – người thừa kế của L cũng bắt đầu điều tra sự kiện này. Họ khám phá ra rằng có tổng cộng 10 quyển Death Note đang xuất hiện. Vào lúc này, virus máy tính mang tên Kira bắt đầu phát tán với thông điệp sẽ sử dụng 6 quyển Death Note. Người sở hữu Death Note ở khắp thế giới. Trận chiến giữa những người muốn Kira phục sinh và những kẻ muốn ngăn chặn điều này bắt đầu..</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masahiro Higashide","avatar":""},{"name":"Sosuke Ikematsu","avatar":""},{"name":"Masaki Suda","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Mina Fujii","avatar":""},{"name":"Rina Kawaei","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Sota Aoyama","avatar":""},{"name":"Eiichiro Funakoshi","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Kensei Mikami","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Desu Nōto 2016","DEATH NOTE 2016","デスノート 2016","ТЕТРАДЬ СМЕРТИ 4 ЗАЖГИ НОВЫЙ МИР","Death Note: El Nuevo Mundo","DEATH NOTE 4 – Light up the NEW world","デスノート: Light up the NEW world","デスノート LNW","DEATH NOTE LNW","Death Note: Light up the NEW World","DEATH NOTE Light up the NEW world","死亡筆記：照亮新世紀","デスノート, Light up the NEW world"]', 1784690324409);
