INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-godzilla-su-hoi-sinh', 'Shin Godzilla : Sự Hồi Sinh', 'Shin Godzilla', 'https://phimimg.com/upload/vod/20250830-1/ff9bb0dcd9463687edda74502d88ae2c.jpg', 'https://phimimg.com/upload/vod/20250830-1/756c57ce43d5c102b2afb5c045c93281.jpg', '<p>Shin Godzilla 2016 bắt đầu từ khi Aqua Line của vịnh Tokyo bị lũ lụt và sụp đổ một cách bí ẩn, Phó Chánh văn phòng Nội Rando Yaguchi của Nhật Bản tin rằng vụ việc đã được gây ra bởi một sinh vật sống. Tuyên bố của ông khiến Thủ tướng Chính phủ cảm thấy không hài lòng và những giả định vụ tai nạn đã được gây ra bởi một thảm họa tự nhiên. Tuy nhiên những dấu hiệu từ vụ thiên tai không giống với bình thường</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroki Hasegawa","avatar":""},{"name":"Yutaka Takenouchi","avatar":""},{"name":"Satomi Ishihara","avatar":""},{"name":"Kengo Kora","avatar":""},{"name":"Satoru Matsuo","avatar":""},{"name":"Mikako Ichikawa","avatar":""},{"name":"Issey Takahashi","avatar":""},{"name":"Kanji Tsuda","avatar":""},{"name":"Shinya Tsukamoto","avatar":""},{"name":"Toru Nomaguchi","avatar":""},{"name":"Daisuke Kuroda","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Sei Hiraizumi","avatar":""},{"name":"Toru Tezuka","avatar":""},{"name":"Kenichi Yajima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92a