INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-sat-thu', 'Nhật Ký Sát Thủ', 'True Memoirs Of An International Assassin', 'https://phimimg.com/upload/vod/20250828-1/07f739e012eb829516cc0d776b2f5c28.jpg', 'https://phimimg.com/upload/vod/20250828-1/48a8ea9229033e3d2cd5219e2e7695b2.jpg', '<p>Sau khi nhà xuất bản thay đổi cuốn tiểu thuyết tội phạm sang thể loại hồi ký, một ngòi bút mới bỗng rơi vào một âm mưu chính trị hiểm ác ở Venezuela.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin James","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Maurice Compte","avatar":""},{"name":"Zulay Henao","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Ron Rifkin","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Kelen Coleman","avatar":""},{"name":"Leonard Earl Howze","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Andy García","avatar":""},{"name":"Anthony Belevtsov","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Katie Couric","avatar":""},{"name":"Gabriel ''G-Rod'' Rodriguez","avatar":""},{"name":"Al Hama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The True Memoirs of an International Assassin","A História Real de um Assassino Falso","Die Wahren Memoiren eines Internationalen Killers","国际杀手的真实回忆录","Wspomnienia tajnego agenta","True Memoirs of an International Assassin"]', 1784690324409);
