INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deadpool', 'Deadpool', 'Deadpool', 'https://phimimg.com/upload/vod/20250821-1/2eef3d1aac354dc42a07e0578b3d7438.jpg', 'https://phimimg.com/upload/vod/20250821-1/48ae866185a5c4aeacc4323a8a32371f.jpg', '<p>Lấy cảm hứng từ nhân vật &quot;phản anh hùng&quot; tiếng tăm bậc nhất trong tuyển tập truyện tranh Marvel, Deadpool xoay quanh câu chuyện về Wade Wilson - kẻ ban đầu nằm trong Lực Lượng Đặc Biệt sau đó trở thành một lính đánh thuê. Sau khi trải qua một cuộc thử nghiệm tàn khốc, anh có được năng lực tự phục hồi phi thường, từ đó lấy biệt danh Deadpool. Mang trong mình khả năng mới và khiếu hài hước dị thường, Deadpool quyết săn lùng người đàn ông đã hủy hoại cả cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"Gina Carano","avatar":""},{"name":"Leslie Uggams","avatar":""},{"name":"Brianna Hildebrand","avatar":""},{"name":"Stefan Kapičić","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Randal Reeder","avatar":""},{"name":"Michael Benyaer","avatar":""},{"name":"Style Dayne","avatar":""},{"name":"Kyle Cassie","avatar":""},{"name":"Taylor Hickson","avatar":""},{"name":"Ayzee","avatar":""},{"name":"Naika Toussaint","avatar":""},{"name":"Isaac C. Singleton","avatar":""},{"name":"Jr.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075d