INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-8-cuoc-chien-chong-apocalypse', 'X-Men 8: Cuộc Chiến Chống Apocalypse', 'X-Men: Apocalypse', 'https://phimimg.com/upload/vod/20250817-1/ce6a1a5d70efe3e0c33998a9fe381c47.jpg', 'https://phimimg.com/upload/vod/20250817-1/601c359a0ceb3dc3675f49ca62e99d26.jpg', '<p>Apocalypse là dị nhân đầu tiên và hùng mạnh nhất của vũ trụ X-Men, đã tích lũy được rất nhiều quyền năng đột biến khác nhau, trở thành kẻ bất tử và bất khả chiến bại. Sau khi tỉnh dậy từ giấc ngủ hàng ngàn năm, hắn cảm thấy thất vọng với thế giới này và năng lực đáng sợ nhất của hắn là khống chế những người khác và biến họ thành kỵ sĩ của mình, nhằm tẩy sạch nhân loại và tạo ra một trật tự thế giới mới và qua đó, hắn sẽ trị vì nó. Số phận của Trái Đất phải đối mặt với tình huống ngàn cân treo sợi tóc, Raven cùng với sự giúp đỡ của Giáo Sư X buộc phải dẫn dắt một đội X-Men trẻ tuổi nhằm chống lại kẻ thù lớn nhất từ trước đến nay và cứu rỗi nhân loại khỏi sự diệt chủng.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Jennifer Lawrence","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Evan Peters","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Sophie Turner","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Lucas Till","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Ben Hardy","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Lana Condor","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Warren Scherer","avatar":""},{"name":"Rochel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["X-Men 6 - Apocalipse","G''aroyib odamlar: Apokalipsis","X-מן: אפוקליפסה","X战警6：天启","X-Men: Apokalipszis","Iks-odamlar","X-Men 6: Apocalipsis","X-Men 6 Apocalypse","Dị Nhân 6: Cuộc Chiến Chống Apocalypse","X-MEN：アポカリプス：2016","X-Men 6: Apocalypse","X-Men 6 - Apocalypse","變種特攻：天啟滅世戰","X-Men: Apocalypse"]', 1784690324409);
