INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-hanh-thai-bao-phep-than-hanh', 'Thần Hành Thái Bảo Phép Thần Hành', 'Windrunner', 'https://phimimg.com/upload/vod/20250808-1/8dda560d1ecd4305ac5b567a0fb330f6.jpg', 'https://phimimg.com/upload/vod/20250808-1/9661a368bcd7bd85211d33795fd3c962.jpg', '<p>Vào thời nhà Tống, Giang Châu có cục hộ tống Thuận Phong, người hộ tống tên là Đại. Vì sự đóng thế, công việc kinh doanh của cục hộ tống phát đạt, nhưng lại bị đồng bọn đóng khung, và cục hộ tống phải đóng cửa. Ông nghe theo lời của sư phụ, đến núi Trừng Phong để học nghệ thuật, và thờ đạo sĩ làm thầy của mình.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Khải","avatar":""},{"name":"Triệu Vân Kiêu","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324409);
