INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-hanh-bao-doi-tung-thu-menh-cuong-bon', 'Thần Hành Bảo Đới: Tung Thủ Mệnh Cuồng Bôn', 'Windrunner 2', 'https://phimimg.com/upload/vod/20250808-1/631b52b750e40469214eb1c4a0fd69a2.jpg', 'https://phimimg.com/upload/vod/20250808-1/b7e4275185c3e7e02948ac8bf1b9f9c1.jpg', '<p>Người mới được bổ nhiệm huyện Đô Xương là Đới Tông đã bắt được thủ lĩnh băng đảng Mạnh Lương. Em trai của Mạnh Lương, Mạnh Linh Ẩn xuất hiện, anh ta lên kế hoạch hãm hại Đới Tông và những người khác, bắt mẹ và vợ của Đới Tông, đồng thời đe dọa Đới Tông phải giải cứu Mạnh Lương. Đới Tông lập một kế hoạch, lấy Mạnh Lương trao đổi mẹ anh và Tiểu Thất, và sau cùng bắt được Linh Ẩn, thủ phạm đã đánh cắp trang sức từ kinh đô của bang.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Khải","avatar":""},{"name":"Trịnh Văn Sâm","avatar":""},{"name":"Triệu Vân Kiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324409);
