INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-dong-vat-phi-vu-dong-troi', 'Thành Phố Động Vật: Phi Vụ Động Trời', 'Zootopia', 'https://phimimg.com/upload/vod/20250731-1/a7c40bbfc8a24ef71dd2d487a3197bbf.jpg', 'https://phimimg.com/upload/vod/20250731-1/f558a7bb32c571adbac1a74ba3218179.jpg', '<p>Trong phim này, Zootopia là một thành phố kì lạ không giống bất kì thành phố nào trước đây của hãng Walt Disney sáng chế. Đây là khu đô thị vui vẻ của các loài động vật, từ voi, tê giác, cho đến những loài nhỏ bé như chuột, thỏ, cún. Cho đến một ngày cô cảnh sát thỏ Judy Hopps xuất hiện, thành phố Zootopia đã có những thay đổi rất là khác. Cô cùng người bạn đồng hành là chú cáo đầy “tiểu xảo” Nick Widle, đã cùng nhau phiêu lưu trong một vụ kỳ án, với mong muốn thiết lập lại trật tự cho thành phố zootopia.</p>', 'Full', 1, 'hoathinh', 'completed', 25, 2016, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ginnifer Goodwin","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Nate Torrence","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Don Lake","avatar":""},{"name":"Tommy Chong","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Shakira","avatar":""},{"name":"Raymond S. Persi","avatar":""},{"name":"Della Saba","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Phil Johnston","avatar":""},{"name":"Fuschia!","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Katie","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zootropolis - Dyreriket","Zoomania - Ganz schön ausgefuchst!","Zootopia 3D","זוטופיה","Zootropolis: Eläinten Kaupunki","动物大都会","Zootropolis","Zootopia","Zootrópolis : 2016","Zootopie","动物乌托邦","Zoomania 1","Zwierzogród","Zwierzogrod","優獸大都會","動物方城市","Zootopia: Essa Cidade é o Bicho"]', 1784690324409);
