INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-hoi-cuoi', 'Vùng Đất Quỷ Dữ: Hồi Cuối', 'Resident Evil: The Final Chapter', 'https://phimimg.com/upload/vod/20250716-1/a00022450d7d3067097f77af17837de2.jpg', 'https://phimimg.com/upload/vod/20250716-1/f08c9738e7cb873cefc31f3a58a30fe7.jpg', '<p>Vùng Đất Quỷ Dữ 6: Hồi cuối - Resident Evil: The Final Chapter diễn ra sau thời điểm kết thúc của &quot;Resident Evil: Retribution&quot;, nhân loại đang đứng trên bờ vực sau khi Alice bị phản bội bởi Albert Wesker ở Washington D.C. Là một trong những người sống sót duy nhất, Alice phải quay trở lại nơi cơn ác mộng bắt đầu. Đó là thành phố Raccoon, nơi Umbrella Corporation đang tập hợp lực lượng của nó trong trận chiến cuối cùng chống lại những người sống sót duy nhất của ngày tận thế.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Eoin Macken","avatar":""},{"name":"Fraser James","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"William Levy","avatar":""},{"name":"Rola","avatar":""},{"name":"Ever Anderson","avatar":""},{"name":"Lee Joon-gi","avatar":""},{"name":"Siobhan Hodgson","avatar":""},{"name":"Milton Schorr","avatar":""},{"name":"Aubrey Shelton","avatar":""},{"name":"Caroline Midgley","avatar":""},{"name":"Dylan Skews","avatar":""},{"name":"Kevin Otto","avatar":""},{"name":"Lee Raviv","avatar":""},{"name":"Raquel Gecelt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916