INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-quy-du-hoi-cuoi', 'Vùng Đất Quỷ Dữ: Hồi Cuối', 'Resident Evil: The Final Chapter', 'vùng đất quỷ dữ: hồi cuối resident evil: the final chapter milla jovovich iain glen ali larter shawn roberts eoin macken fraser james ruby rose william levy rola ever anderson lee joon-gi siobhan hodgson milton schorr aubrey shelton caroline midgley dylan skews kevin otto lee raviv raquel gecelt resident evil: rising バイオハザード：ザ・ファイナル заразно зло 6: финалът resident evil 6 resident evil 6 - chapitre final resident evil: capítulo final resident evil 6: the final chapter 레지던트 이블 6 оселя зла 6 обитель зла: последняя глава оселя зла: фінальна битва resident evil: the final chapter 3d 레지던트 이블 6-파멸의 날 resident evil 6：the final chapter 生化危機6：終極屍殺 生化危机6：终章 resident evil the final chapter resident evil: the final chapter الشر المقيم : الفصل الأخير', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-cuoi-cung', 'Chuyến Đi Cuối Cùng', 'The Last Ride', 'https://phimimg.com/upload/vod/20250712-1/e0c36b0a5a0681f624646f767d960b5f.jpg', 'https://phimimg.com/upload/vod/20250712-1/66ec069747188b26b237e078e59bd835.jpg', '<p>Go-hwan, người mắc căn bệnh Lou Gehrig, nhận ra mình sắp qua đời. Khi những người bạn thân nhất hỏi anh điều ước của mình là gì, anh nói với họ rằng anh muốn được quan hệ tình dục lần đầu tiên và cũng là lần cuối cùng trong đời.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Deok-hwan","avatar":""},{"name":"Ahn Jae-hong","avatar":""},{"name":"Kim Dong-young","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Lee Byeong-heon","avatar":""},{"name":"Han Kuk-jin","avatar":""},{"name":"Bae Jung-hwa","avatar":""},{"name":"Yoo Jung-Rae","avatar":""},{"name":"Woo Ji-won","avatar":""},{"name":"Lee Rang-seo","avatar":""},{"name":"Lee Hong-nae","avatar":""},{"name":"Kim Ra Hee","avatar":""},{"name":"An Min-young","avatar":""},{"name":"Mun Jung Hyun","avatar":""},{"name":"Lee Jeong-ho","avatar":""},{"name":"Kim Yong-woon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Widaehan Sowon","The Great Wish","위대한 소원"]', 1784690324410);
