INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-di-cuoi-cung', 'Chuyến Đi Cuối Cùng', 'The Last Ride', 'chuyến đi cuối cùng the last ride ryu deok-hwan ahn jae-hong kim dong-young jeon no-min jeon mi-seon lee han-wi lee byeong-heon han kuk-jin bae jung-hwa yoo jung-rae woo ji-won lee rang-seo lee hong-nae kim ra hee an min-young mun jung hyun lee jeong-ho kim yong-woon widaehan sowon the great wish 위대한 소원', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-gium-co-chu-2016', 'Yêu Giùm Cô Chủ', 'Asoke''s Shadow', 'https://phimimg.com/upload/vod/20250712-1/798070b6eebd5069ebaae2fd43fcfb59.jpg', 'https://phimimg.com/upload/vod/20250712-1/2864d8601b1a35f6b17d5a011825f7a9.jpg', '<p>Bpeeyachat, một cô bé mồ côi, đã kết bạn với Monthai, một cậu bé giàu có, từ khi còn nhỏ. Sau một tai nạn xe hơi cướp đi người bà – người thân cuối cùng của cô, Bpeeyachat được chuyển đến sống với gia đình của Viyada. Do mâu thuẫn gia đình, Monthai sang nước ngoài du học và liên tục gửi thư cho vị hôn thê Viyada, nhưng các bức thư ấy lại được Bpeeyachat trả lời thay, bởi Viyada đang mải mê gặp gỡ những người đàn ông khác. Khi mẹ của Monthai bị bệnh nặng và yêu cầu Viyada chăm sóc, Viyada từ chối, nên Bpeeyachat đã thay cô ấy đến chăm sóc bà. Khi Monthai trở về, anh nhầm tưởng Bpeeyachat là kẻ đào mỏ giả danh Viyada nên đối xử lạnh nhạt và tàn nhẫn. Tuy nhiên, theo thời gian, anh dần nảy sinh tình cảm với cô. Rắc rối bắt đầu khi Viyada bất ngờ quay lại, đe dọa mối quan hệ đang chớm nở giữa Monthai và Bpeeyachat.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 10, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Sean Jindachot","avatar":""},{"name":"Esther Supreeleela","avatar":""},{"name":"Kornpassorn Duaysienklao","avatar":""},{"name":"Savitree Samipak","avatar":""},{"name":"Prathana Suchookorn","avatar":""},{"name":"Nut Devahastin","avatar":""},{"name":"Nasaran Chumphonwiwat","avatar":""},{"name":"Aerin Yuktadatta","avatar":""},{"name":"Rathfar Chaichueanjit","avatar":""},{"name":"Pattarapol Kantapoj","avatar":""},{"name":"Janya Thanasawaangkoun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新无忧花开","Ngao Asoke","Love Under the Shadow","เงาอโศก"]', 1784690324410);
