INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-gium-co-chu-2016', 'Yêu Giùm Cô Chủ', 'Asoke''s Shadow', 'yêu giùm cô chủ asoke''s shadow sean jindachot esther supreeleela kornpassorn duaysienklao savitree samipak prathana suchookorn nut devahastin nasaran chumphonwiwat aerin yuktadatta rathfar chaichueanjit pattarapol kantapoj janya thanasawaangkoun 新无忧花开 ngao asoke love under the shadow เงาอโศก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-dai-tac-vuong', 'Tam Đại Tặc Vương', 'Trivisa', 'https://phimimg.com/upload/vod/20250707-1/470067775fd3400762cf9f88a3b2ecf7.jpg', 'https://phimimg.com/upload/vod/20250707-1/2ba66065abfdd5dcec537cfcfdf39bc6.jpg', '<p>Gió mà luồn được tận hang sâu...Đâu phải chẳng có nguyên do...
 Đầu năm 1997, ba người Trác Tử Cường, Diệp Quốc Hoan, Quý Chính Hùng... trước đây chẳng hề quen nhau lại ngẫu nhiên cùng xuất hiện ở một tửu lầu.
 Sau đó, khắp giang hồ dậy lên lời đồn thổi rằng thì là: Lịch sử của tội phạm của HongKong sẽ có một trang vàng. Bởi vì &quot;tam đại tặc vương&quot; sẽ bí mật hợp tác để làm một vụ án kinh thiên động địa.
 Ai ai cũng cho rằng ba người bọn họ sẽ nhân dịp này để trở lại những ngày xưa. Thời mà ba người bọn họ là những ngôi sao sáng trong giới tội phạm.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lâm Gia Đống","avatar":""},{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Lâm Tuyết","avatar":""},{"name":"Ngô Chí Hùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chu tai chiu fung","수대초풍","Trivisa","樹大招風"]', 1784690324410);
