INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-loi-anh-chi-la-sat-thu-sat-thu-doi-vai', 'Xin Lỗi Anh Chỉ Là Sát Thủ (Sát Thủ Đổi Vai)', 'Luck Key', 'https://phimimg.com/upload/vod/20240928-1/81cd093a425efd4cb2cf8d1c1bab6fa3.jpg', 'https://phimimg.com/upload/vod/20240928-1/cdabfb7a74a8e53209b718d5043b3840.jpg', '<p>Luck-Key là phiên bản Hàn làm lại từ bộ phim Key of Life (2012) của điện ảnh Nhật Bản. Nhân vật chính trong tác phẩm mới là Hyung Wook (Yoo Hae Jin) - một gã sát thủ khét tiếng trong giới giang hồ. Hắn có phong cách làm việc chuyên nghiệp, hiệu quả, không bao giờ để lại dấu vết sau khi ra tay.
 Một hôm, Hyung Wook gặp phải tai nạn tại nhà tắm công cộng và trở nên bất tỉnh nhân sự. Lợi dụng lúc hỗn loạn, chàng thanh niên Jae Sung (Lee Joon) bèn tráo đổi chìa khóa tủ đồ của mình với gã sát thủ.
 Trái ngược với Hyung Wook, Jae Sung chỉ là chàng diễn viên quèn bất tài, có cuộc sống nghèo khổ, thất bại. Sau khi tráo chìa khóa, anh giả làm gã sát thủ, tận hưởng cuộc sống giàu sang.
 Ở thế trái ngược, Hyung Wook khi tỉnh lại bị mất trí nhớ, cứ ngỡ mình là một diễn viên nghèo. Hàng loạt tình huống dở khóc, dở cười bắt đầu nảy sinh từ đây.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"유해진","avatar":""},{"name":"이준","avatar":""},{"name":"조윤희","avatar":""},{"name":"임지연","avatar":""},{"name":"고준","avatar":""},{"name":"Cha Soon-hyeong","avatar":""},{"name":"조한철","avatar":""},{"name":"차엽","avatar":""},{"name":"김민상","avatar":""},{"name":"Kim Ji-an","avatar":""},{"name":"성병숙","avatar":""},{"name":"Park Seoung-tae","avatar":""},{"name":"이용녀","avatar":""},{"name":"이성욱","avatar":""},{"name":"정희태","avatar":""},{"name":"이동용","avatar":""},{"name":"Song Yo-sep","avatar":""},{"name":"금광산","avatar":""},{"name":"Lee Seung-chul","avatar":""},{"name":"Kim Han-gyu","avatar":""},{"name":"Cho Han-na","avatar":""},{"name":"이동휘","avatar":""},{"name":"아누팜 트리파티","avatar":""},{"name":"장혁진","avatar":""},{"name":"Na Soo-yoon","avatar":""},{"name":"Moon Jong-won","avatar":""},{"name":"서영화","avatar":""},{"name":"Lee Myeong-ja","avatar":""},{"name":"Jang Woo-jin","avatar":""},{"name":"최대성","avatar":""},{"name":"Ah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Luck-Key 2016 - Xin Lỗi Anh Chỉ Là Sát Thủ","Xin Lỗi Anh Chỉ Là Sát Thủ 2016","Luck-Key","LUCK-KEY ラッキー","LUCK-KEY／ラッキー：2016","這個殺手演很大","Luck Key","럭키"]', 1784690324410);
