INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tuoc-chim-se', 'Ma Tước (Chim Sẻ)', 'Sparrow', 'https://phimimg.com/upload/vod/20250706-1/9b7d420f1f1d08d1d426bde9bb77aac5.jpg', 'https://phimimg.com/upload/vod/20250706-1/57c2b2213144d328034ff4ddd7cd2acd.jpg', '<p>Ma Tước là câu chuyện về Đảng viên Trần Sâm làm đặc công nằm vùng dưới chính quyền Uông ngụy, cùng các đặc công ngầm của Quốc Dân Đảng trải qua nguy hiểm để có thể nắm được kế hoạch &quot;Quy Linh&quot; của phe địch. Tiểu thuyết gốc Ma Tước từng được bình chọn là tiểu thuyết hấp dẫn nhất về đề tài chiến tranh tình báo, bộ phim chuyển thể cũng được hy vọng sẽ trở thành một cú hit truyền hình.</p>', 'Hoàn Tất (61/61)', 61, 'series', 'completed', 10, 2016, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Dịch Phong","avatar":""},{"name":"Châu Đông Vũ","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Trương Nhược Vân","avatar":""},{"name":"Khán Thanh Tử","avatar":""},{"name":"Doãn Chính","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Sparrow","麻雀"]', 1784690324410);
