INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-2', 'Họa giang hồ chi bất lương nhân (Phần 2)', 'A Portrait of Jianghu: Bad Guys (Season 2) / Hua Jiang Hu Zhi Bu Liang Ren 2', 'https://phimimg.com/upload/vod/20250412-1/7c8f66131734f3560533efe7689ce04e.jpg', 'https://phimimg.com/upload/vod/20250412-1/4d2e25c8aeb1f8f9a88e51451e9631b0.jpg', '<p>Họa Giang Hồ Chi Bất Lương Nhân Phần 2 là tác phẩm thứ hai trong series hoạt hình võ hiệp 3D lớn Họa Giang Hồ, mang tên Bất Lương Nhân. Kho báu Long Tuyền xuất hiện trở lại, các thế lực giang hồ như Bất Lương Nhân, Huyền Minh Giáo, Thông Văn Quán, Huyễn Âm Phường, Thiên Sư Phủ đều bắt đầu có động tĩnh! Hỏi các vua, ai có thể rút kiếm ra lệnh thiên hạ! Lý Tinh Vân, người nắm giữ kho báu Long Tuyền, là nhân vật then chốt, liệu có thể tái tạo lại thời đại huy hoàng của Đại Đường hay sẽ lui về ẩn dật giang hồ? Lâm Hiên và Tử Phàm liệu có thể gỡ bỏ hiểu lầm và tiếp tục mối duyên? Thiên cơ khó đoán, thế nhân là cờ, Họa Giang Hồ Chi Bất Lương Nhân Phần 2 sẽ tiếp tục kể cho chúng ta một câu chuyện huyền thoại võ hiệp đậm đà phong cách Trung Hoa, vừa lãng mạn vừa rực rỡ!</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324410);
