INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-2', 'Họa giang hồ chi bất lương nhân (Phần 2)', 'A Portrait of Jianghu: Bad Guys (Season 2) / Hua Jiang Hu Zhi Bu Liang Ren 2', 'họa giang hồ chi bất lương nhân (phần 2) a portrait of jianghu: bad guys (season 2) / hua jiang hu zhi bu liang ren 2 jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ba-me-ngoan', 'Những Bà Mẹ "Ngoan"', 'Bad Moms', 'https://phimimg.com/upload/vod/20250701-1/3a3eedf006322daefc45ac913a8de987.jpg', 'https://phimimg.com/upload/vod/20250701-1/e2186e17abff4e99936b2f5d3d03d4d8.jpg', '<p>Phim xoay quanh cuộc sống hằng ngày của các bà nội trợ kiểu Mỹ và áp lực làm mẹ của họ. Amy Mitchell có sự nghiệp thành đạt, một gia đình hạnh phúc cùng những đứa con tài giỏi. Tuy nhiên, sự kì vọng và chuẩn mực hà khắc với người mẹ từ Hội Phụ huynh – Giáo viên khiến cô quá mệt mỏi và quyết định rũ bỏ mọi nguyên tắc phi lí đó.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mila Kunis","avatar":""},{"name":"Kristen Bell","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Annie Mumolo","avatar":""},{"name":"Emjay Anthony","avatar":""},{"name":"Oona Laurence","avatar":""},{"name":"David Walton","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"J.J. Watt","avatar":""},{"name":"Leah McKendrick","avatar":""},{"name":"Megan Ferguson","avatar":""},{"name":"Lyle Brocato","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Ca","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["C奶同学会","阿姐万万醉","叛逆母亲","Pahad emmed","Immahot ra''ot","Bad Moms"]', 1784690324410);
