INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuc-lanh-cho-the-gioi-tuyet-voi-nay', 'Phúc Lành Cho Thế Giới Tuyệt Vời Này', 'KonoSuba God''s Blessing On This Wonderful World!', 'phúc lành cho thế giới tuyệt vời này konosuba god''s blessing on this wonderful world! jun fukushima sora amamiya rie takahashi ai kayano konosuba: as bênçãos de deus neste mundo maravilhoso! konosuba: abençoado mundo maravilhoso! 素晴 素晴3 bůh žehnej tomuto nádhernému světu konosuba: un mundo maravilloso! konosuba - sois béni monde merveilleux ! konosuba このすば kono subarashii sekai ni syukufuku wo! kono subarashii sekai ni shukufuku wo! 3 kono subarashii sekai ni shukufuku wo! kono subarashii sekai ni shukufuku o! 3 kono subarashii sekai ni syukufuku wo! 2 kono subarashii sekai ni syukufuku wo! 3 코노스바 konosuba: ¡una bendición para este maravilloso mundo! богиня благословляет этот прекрасный мир коносуба богиня благословляет этот замечательный мир! да благословят боги сей расчудесный мир! этот замечательный мир! 美好世界 為美好的世界獻上祝福 give blessings to this wonderful world! konosuba - god''s blessing on this wonderful world!! konosuba: god''s blessing on this wonderful world この素晴らしい世界に祝福を！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-bien-thanh-lang-tu', 'Tân Biên Thành Lãng Tử', 'Border Town Prodigal', 'https://phimimg.com/upload/vod/20250626-1/20dccb2f18231f5ae0ee4e6a79f2c94d.jpg', 'https://phimimg.com/upload/vod/20250626-1/5501d4e89a6d198bd4266235fc9990e5.jpg', '<p>Thần Đao Môn môn chủ Bạch Thiên Vũ ở biên thành Hoa Mai Am bị người ta mai phục hại chết, trở thành một kì án trong võ lâm. Hai mươi năm sau, Phó Hồng Tuyết vì điều tra cái chết của phụ thân, từ Tây Vực trở về Trung Nguyên. Cùng lúc đó, Diệp Khai (con của Bạch Thiên Vũ và Hoa Bạch Phượng) cũng tới biên thành. Hai người trải qua khúc chiết, cuối cùng điều tra ra người đứng sau là Mã Không Quần- huynh đệ kết nghĩa của Bạch Thiên Vũ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 9, 2016, 'Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Long","avatar":""},{"name":"Trương Hình Dư","avatar":""},{"name":"Khưu Tâm Chí","avatar":""},{"name":"Tiêu Ấn Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xin Bian Cheng Lang Zi","边城浪子","Edge City Wanderer","新边城浪子"]', 1784690324410);
