INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-trai-toi-la-dac-vu', 'Em Trai Tôi Là Đặc Vụ', 'The Brothers Grimsby', 'https://phimimg.com/upload/vod/20250616-1/abee26aa90c2254586aa5d434f45228c.jpg', 'https://phimimg.com/upload/vod/20250616-1/c11c7d712fef6e2705b1848777ad0517.jpg', '<p>Sau 28 năm thất lạc, Nobby vô cùng vui mừng và tìm cách bù đắp lại thời gian đã mất với em trai. Tuy nhiên, cả hai lại vô tình vướng vào một phi vụ... giải cứu thế giới với những rắc rối khó đỡ.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Sacha Baron Cohen","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Gabourey Sidibe","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Nick Sampson","avatar":""},{"name":"David Harewood","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Sam Hazeldine","avatar":""},{"name":"Tamsin Egerton","avatar":""},{"name":"Johnny Vegas","avatar":""},{"name":"Alex Lanipekun","avatar":""},{"name":"Eileen Davies","avatar":""},{"name":"Rory Keenan","avatar":""},{"name":"Zak Sutcliffe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Brothers Grimsby","האחים גרימסבי","האחים גריסני","Grimsby Kardeşler","Spiegs kļūdas pēc","Agente contrainteligente","Bratia z Grimsby","Brāļi Grimsbiji","Grimsby"]', 1784690324410);
