INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('em-trai-toi-la-dac-vu', 'Em Trai Tôi Là Đặc Vụ', 'The Brothers Grimsby', 'em trai tôi là đặc vụ the brothers grimsby sacha baron cohen mark strong isla fisher penélope cruz rebel wilson gabourey sidibe annabelle wallis nick sampson david harewood scott adkins sam hazeldine tamsin egerton johnny vegas alex lanipekun eileen davies rory keenan zak sutcliffe the brothers grimsby האחים גרימסבי האחים גריסני grimsby kardeşler spiegs kļūdas pēc agente contrainteligente bratia z grimsby brāļi grimsbiji grimsby', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-di-san-ki-la', 'Cuộc Đi Săn Kì Lạ', 'Hunt For The Wilderpeople', 'https://phimimg.com/upload/vod/20250616-1/02046ba7efa7435bd527c15a8933f4c5.jpg', 'https://phimimg.com/upload/vod/20250616-1/1f5902356b1a144d81b9efae1e6c8109.jpg', '<p>Cuộc Đi Săn Kì Lạ được xem là một bộ phim hài “kỳ quái” đến từ đạo diễn Taika Waikiti – tác giả của một trong những phim hài thành công nhất 2015 là What We Do in the Shadow. Kinh phí đầu tư khiêm tốn, diễn viên không đình đám, Hunt for the Widerpeople vẫn gây chú ý tại các Liên hoan phim nhờ nội dung giàu tính nhân văn và cách kể chuyện cực kỳ độc đáo. Cậu bé thành phố ương ngạnh Ricky bắt đầu một cuộc sống mới ở vùng nông thôn New Zealand với gia đình nhận nuôi mình bao gồm: dì Bella dịu dàng, bác Hec khó tính và chú chó Tupac. Một sự kiện bất ngờ xảy ra khiến Ricky có nguy cơ phải chuyển đến gia đình nuôi khác. Bác Hec đành dẫn cậu bé chạy trốn vào khu rừng hoang rậm rạp. Một cuộc săn tìm với quy mô quốc gia được tổ chức ...</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Sam Neill","avatar":""},{"name":"Julian Dennison","avatar":""},{"name":"Rima Te Wiata","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Tioreore Ngatai-Melbourne","avatar":""},{"name":"Oscar Kightley","avatar":""},{"name":"Stan Walker","avatar":""},{"name":"Mike Minogue","avatar":""},{"name":"Cohen Holloway","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Troy Kingi","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Hamish Parkinson","avatar":""},{"name":"Stu Giles","avatar":""},{"name":"Lloyd Scott","avatar":""},{"name":"Selina Woulfe","avatar":""},{"name":"Mabelle Dennison","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu