INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-cuu-hoa-chicago-2016', 'Đội Cứu Hoả Chicago (Phần 5)', 'Chicago Fire (Season 5)', 'đội cứu hoả chicago (phần 5) chicago fire (season 5) taylor kinney david eigenberg joe miñoso christian stolte miranda rae mayo daniel kyri hanako greensmith jocelyn hudon jake lockett dermot mulroney chicago fire : caserne 51 风城烈火 芝加哥烈火群英 chicago fire שיקגו fire שיקגו פייר آتش‌نشانی شیکاگو чикаго в огне one chicago chicago fire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-cac-vi-than', 'Cuộc Chiến Của Các Vị Thần', 'Karmaphal Daata Shani', 'https://phimimg.com/upload/vod/20250604-1/a2da6d039c886ac61b700de1a5c8e385.jpg', 'https://phimimg.com/upload/vod/20250604-1/8ab5a3570e1eca677f8ceb08d325d2f5.jpg', '<p>Lòng tham, sức mạnh và quyền lực… luôn là những thứ khiến con người ta phải bất chấp tất cả để chiếm hữu. Và sức hút đầy ma lực của chúng không chỉ có ở trần gian mà ngay cả chốn Thiên đường cũng rơi vào nguy cơ bị hủy diệt bởi những cuộc chiến tranh giành quyền lực không hồi kết… Với cốt truyện hấp dẫn, dàn dựng công phu, tạo hình nhân vật chân thật cùng lối diễn xuất sắc của dàn diễn viên… &#39;Cuộc chiến của các vị thần&#39; khiến người xem như đắm chìm trong một thế giới thần thoại hào hùng bi tráng đầy huyền bí…</p>', 'Hoàn Tất (174/174)', 174, 'series', 'completed', 41, 2016, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Rohit Khurana","avatar":""},{"name":"Kartikey Malviya","avatar":""},{"name":"Juhi Parmar","avatar":""},{"name":"Tarun Khanna","avatar":""},{"name":"Tina Datta","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '["कर्मफल दाता शनि"]', 1784690324410);
