INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-cuoc-song', 'Vẻ Đẹp Cuộc Sống', 'Collateral Beauty', 'https://phimimg.com/upload/vod/20250526-1/d1147e7cb7dc76ed8c0b6ba5c893936f.jpg', 'https://phimimg.com/upload/vod/20250526-1/bc45750a21f7dc473aa6192cbf61fbd7.jpg', '<p>Rút lui khỏi cuộc sống sau một bi kịch, một người đàn ông đặt câu hỏi về vũ trụ bằng cách viết cho Tình yêu, Thời gian và Cái chết. Nhận được những câu trả lời bất ngờ, anh bắt đầu nhận ra những điều này đan xen vào nhau như thế nào và ngay cả sự mất mát cũng có thể bộc lộ những khoảnh khắc ý nghĩa và vẻ đẹp như thế nào.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Will Smith","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Jacob Latimore","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Kylie Rogers","avatar":""},{"name":"Natalie Gold","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"Shirley Rumierk","avatar":""},{"name":"Alyssa Cheatham","avatar":""},{"name":"Benjamin Snyder","avatar":""},{"name":"Mary Beth Peil","avatar":""},{"name":"Andy Taylor","avatar":""},{"name":"Mi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ukryte piękno","Verborgene Schönheit","素晴らしきかな、人生：2016","زیبایی پنهان","Collateral Beauty"]', 1784690324410);
