INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-nguoi-nhai-2016', 'Sát Nhân Người Nhái', 'Museum', 'https://phimimg.com/upload/vod/20250525-1/83d275ef6fc8803c79295713ba4e6b0c.jpg', 'https://phimimg.com/upload/vod/20250525-1/8d73a6235a9fe2f47d430998a1c09bbd.jpg', '<p>Museum 2016 là bộ phim được chuyển thể từ bộ truyện Museum – The Serial Killer is Laughing in the Rain của tác giả Ryōsuke Tomoe. Bộ phim xoay quanh các vụ giết người hàng loạt được thực hiện bởi kẻ sát nhân của biệt danh Người Nhái – Kẻ tự xưng mình là kẻ Phán quyết và thực hiện việc giết người là bởi đó là “Hình phạt của Dogfood”. Sawamura là thám tử điều tra về người Nhái nhưng chính vợ của Sawamura lại là mục tiêu của Người Nhái. Liệu mọi chuyện sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Shuhei Nomura","avatar":""},{"name":"Tomomi Maruyama","avatar":""},{"name":"Tomoko Tabata","avatar":""},{"name":"Mikako Ichikawa","avatar":""},{"name":"Masatô Ibu","avatar":""},{"name":"Nao Ômori","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Satoshi Tsumabuki","avatar":""},{"name":"Himiko Igarashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Myujiamu","追凶雨","ミュージアム"]', 1784690324410);
