INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-nhan-nguoi-nhai-2016', 'Sát Nhân Người Nhái', 'Museum', 'sát nhân người nhái museum shun oguri machiko ono shuhei nomura tomomi maruyama tomoko tabata mikako ichikawa masatô ibu nao ômori yutaka matsushige satoshi tsumabuki himiko igarashi myujiamu 追凶雨 ミュージアム', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cua-me', 'Nhật Ký Của Mẹ', 'My Little Old Boy', 'https://phimimg.com/upload/vod/20250309-1/68a1b2439bec4f1f79820d4ddd6a1e8b.jpg', 'https://phimimg.com/upload/vod/20250309-1/ca480b54cd2ca6060c6b1e5b7f3abceb.jpg', '<p>Bạn hiểu bao nhiêu về cậu con trai đã trưởng thành của mình? Trong “Nhật Ký Của Mẹ”, cuộc sống thường nhật của những người con trai nổi tiếng nay đã trưởng thành được các bà mẹ theo dõi một cách cẩn thận và đầy yêu thương. Bạn có biết vì sao dạo này con trai mình hay uống rượu không? Bạn hiểu bao nhiêu về triết lý sống và lối sống của con mình? “Nhật Ký Của Mẹ” mang đến những khoảnh khắc xúc động, nơi tình mẫu tử được thể hiện qua sự quan sát và thấu hiểu – một cuộc đối thoại không lời nhưng đầy gắn kết giữa mẹ và con trai.</p>', 'Tập 443', 480, 'tvshows', 'ongoing', 10, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Dong-yup","avatar":""},{"name":"Seo Jang-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["我家的熊孩子","MLOB","미우새","미운 우리 새끼, 다시 쓰는 육아일기","Mom''s Diary: My Ugly Duckling","My Ugly Duckling","My Little Old Boy","미운 우리 새끼"]', 1784690324410);
