INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-cua-me', 'Nhật Ký Của Mẹ', 'My Little Old Boy', 'nhật ký của mẹ my little old boy shin dong-yup seo jang-hoon 我家的熊孩子 mlob 미우새 미운 우리 새끼, 다시 쓰는 육아일기 mom''s diary: my ugly duckling my ugly duckling my little old boy 미운 우리 새끼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nuoc-nhat-thoi-nguyen-thuy', 'Doraemon: Nobita và Nước Nhật Thời Nguyên Thủy', 'Doraemon: Nobita and the Birth of Japan', 'https://phimimg.com/upload/vod/20250521-1/ba842b6f259aaf3a3567884a4c7e1148.jpg', 'https://phimimg.com/upload/vod/20250521-1/c461620ebe1c0b5a441069888b58a270.jpg', '<p>Trong thế kỷ 20, Nobita đã nảy ra ý tưởng sẽ rời khỏi nhà và tìm một nơi tốt đẹp hơn để tạm sống. Cùng lúc đó, những người bạn của Nobita là Shizuka, Gian, Suneo và Doraemon cũng muốn trốn chạy khỏi ngôi nhà của mình vì nhiều lý do khác nhau. Từ đó, Nobita đã đề xuất cả nhóm sẽ đi ngược thời gian, trở về quá khứ để đến sống một nơi ít người. Tất cả đều đồng ý và quyết định quay ngược thời gian trở về Nhật Bản thời nguyên thủy ở thời điểm 70.000 năm trước.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Miyako Takeuchi","avatar":""},{"name":"Chiaki Fujimoto","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Hiroshi Yanaka","avatar":""},{"name":"Koji Ishii","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Hiroki Shimowada","avatar":""},{"name":"Miyako Ito","avatar":""},{"name":"Yuki Kaida","avatar":""},{"name":"Miki Fuku","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fc