INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mat-na-ech', 'Sát Thủ Mặt Nạ Ếch', 'Museum: Introduction', 'https://phimimg.com/upload/vod/20250518-1/a5b5f9ee0f711fb1363bd61d81fd4268.jpg', 'https://phimimg.com/upload/vod/20250518-1/fdd10de2aebba5a724bbc6fb3fa32ea4.jpg', '<p>Hitoshi Kudo là một nhà báo chuyên điều tra các vụ án mạng. Cuộc sống của anh rơi vào khủng hoảng khi con gái anh bị bắt cóc bởi một kẻ bí ẩn mang mặt nạ hình con ếch, được gọi là &quot;Người Ếch&quot;. Để cứu con gái, Kudo buộc phải làm theo một chuỗi mệnh lệnh phi lý và đáng sợ, mỗi mệnh lệnh đều thử thách đạo đức, lý trí và giới hạn của anh.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaki Miura","avatar":""},{"name":"Ririka Kawashima","avatar":""},{"name":"Kokoro Morita","avatar":""},{"name":"Hidetoshi Kawaya","avatar":""},{"name":"Yoshitaka Hosokawa","avatar":""},{"name":"Honoka Ueda","avatar":""},{"name":"Hide Miura","avatar":""},{"name":"Eita Okuno","avatar":""},{"name":"Shohei Uno","avatar":""},{"name":"Hideki Nakano","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ミュージアム -序章-","ミュージアム / 序章","Museum: Prologue","ミュージアム 序章"]', 1784690324410);
