INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-bang-truyen-ky', 'Phong Thần Bảng Truyền Kỳ', 'League Of Gods', 'https://phimimg.com/upload/vod/20250219-1/ec25c7243c0358c51f1b807a516405f6.jpg', 'https://phimimg.com/upload/vod/20250219-1/4c2942f2117de67ea5d6c035558523de.jpg', '<p>Trong trận đánh giữa yêu hồ và tam giới, Đát Kỷ (Phạm Băng Băng) sẽ là nhân vật đại ác. Một mặt, nhân vật này dùng mị thuật để khống chế Trụ Vương (Lương Gia Huy), khiến bậc đế vương mê mệt đến mất nước. Mặt khác, Đát Kỷ dùng yêu thuật đấu Khương Tử Nha (Lý Liên Kiệt), Lôi Chấn Tử (Hướng Tả), Na Tra, Dương Tiễn.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"AngelaBaby","avatar":""},{"name":"Jacky Heung","avatar":""},{"name":"Tony Leung Ka-Fai","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Wen Zhang","avatar":""},{"name":"Zu Feng","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Jordan Chan Siu-Chun","avatar":""},{"name":"Qin Pengfei","avatar":""},{"name":"He Jude","avatar":""},{"name":"Wang Zhipeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["3D封神榜","Saam1 D Fung1 San4 Bong2","Fēng Shén Bǎng","Лига на Боговете","League of Gods","3D Fung1 San4 Bong2","3D Fēng Shén Bǎng","封神演義","Fengshen Yanyi","Investiture of the God