INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-ke-toan', 'Mật Danh: Kế Toán', 'The Accountant', 'https://phimimg.com/upload/vod/20250511-1/ea3610828d6fd615db5434041177458f.jpg', 'https://phimimg.com/upload/vod/20250511-1/d9734a02ec53173c8b6339253eb53d4d.jpg', '<p>Tuy mắc chứng tự kỉ từ nhỏ, Christian Wolff được trời phú cho một bộ óc thiên tài và nhạy bén với những con số. Với tính cách trầm lắng và khác biệt, Wolff chọn công việc là một nhân viên kế toán ở một thị trấn nhỏ. Không ai biết được đằng sau lớp vỏ bọc dường như “vô hại” ấy, Wolff thực sự là một bậc thầy về sổ sách chuyên làm việc cho những tổ chức tội phạm. &nbsp;Khi nhận ra mình đang bị dòm ngó bởi chính phủ, Wolff tạm tránh xa những phi vụ ngoài vòng pháp luật và quyết định nhận một công việc “sạch”. &nbsp;Nhưng mọi rắc rối bắt đầu từ đây, khi anh phải đối mặt với một bài toán tài chính hàng triệu đô của một tập đoàn điện máy – thứ đưa anh vào một cuộc rượt đuổi để cứu lấy chính sinh mạng mình.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ben Affleck","avatar":""},{"name":"Cynthia Addai-Robinson","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"Andy Umberger","avatar":""},{"name":"Alison Wright","avatar":""},{"name":"Jason Davis","avatar":""},{"name":"Robert C. Treveiler","avatar":""},{"name":"Mary Kraft","avatar":""},{"name":"Seth Lee","avatar":""},{"name":"Jake Presley","avatar":""},{"name":"Izzy Fenech","avatar":""},{"name":"Susan Williams","avatar":""},{"name":"Gary","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0