INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-hong-gil-dong', 'Thám Tử Hong Gil Dong', 'Phantom Detective', 'https://phimimg.com/upload/vod/20231114-1/e4566f6739fb2a7fa1432ea8e47e892b.jpg', 'https://phimimg.com/upload/vod/20231114-1/48af6dafa404b4fd23e88574c6a7bc24.jpg', '<p>Lấy bối cảnh thập niên 90, Hong Gil Dong, một thám tử có trí nhớ phi thường và tính cách độc đáo. Anh làm việc như một thám tử tư độc lập với khả năng phá án thành công tuyệt đối. Trong khi theo dấu đối tượng, tình cờ Hong Gil Dong lại vướng vào một vụ án nghiêm trọng, có liên quan tới vụ án của mẹ mình nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Park Geun-hyung","avatar":""},{"name":"Chung Sung-hwa","avatar":""},{"name":"Go Ara","avatar":""},{"name":"Kim Dong-hwi","avatar":""},{"name":"Jang Se-won","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Kim Ha-na","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Yoon Yeong-gyun","avatar":""},{"name":"Hwang Bo-ra","avatar":""},{"name":"Jung Young-hoon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324410);
