INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-phien-mon', 'Lục Phiến Môn', 'The Legend Liu Shan Men', 'https://phimimg.com/upload/vod/20250425-1/bf23d61ce42cce4addb6cde095aa5c5c.jpg', 'https://phimimg.com/upload/vod/20250425-1/e1c6d299bfd399d951293d0f4fe0bbf4.jpg', '<p>Nội dung phim Lục Phiến Môn xoay quanh những cuộc điều tra của Lục Phiến Môn và người đứng đầu là Tử Thân Mộc. Sau khi hoàn đế triều đại nhà minh lâm vào trạng thái hôn mê bất tỉnh thì hệ thống cai trị của triều đình trở nên hỗn loạn, quan lại hoành hành bóc lột nhân dân, những kẻ mạnh hơn thì tranh giành quyền lực, chém giết lẫn nhau và muốn thâu tóm cả triều đình.

Nhân lúc này, kẻ xấu bắt đầu lợi dụng gây ra những vụ giết người kinh hoàng. Đã có rất nhiều người chết một cách kỳ lạ, Lục Phiến Môn bắt buộc phải nhúng tay vào điều tra. Nhưng thủ lĩnh của họ nghi ngờ có một thế lực lớn đứng đằng sau vụ việc nên không muốn mọi chuyện trở nên phức tạp đã cho qua mọi chuyện. Nhưng con trai ông là Thân Lực Hoành lại thấy có nhiều ẩn dấu, quyết theo vụ án đến cùng…</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Raymond Lam Fung","avatar":""},{"name":"Dilraba Dilmurat","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Huang Wenhao","avatar":""},{"name":"Ying Haoming","avatar":""},{"name":"Sun Yaoqi","avatar":""},{"name":"Luo Jin","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"Zhang Haiyu","avatar":""},{"name":"Lee Yiu-King","avatar":""},{"name":"Qiu Xiaochan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Liu Shan Men","Six Doors","六扇門","The Door","六扇门"]', 1784690324410);
