INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-phien-mon', 'Lục Phiến Môn', 'The Legend Liu Shan Men', 'lục phiến môn the legend liu shan men raymond lam fung dilraba dilmurat alex fong chung-sun huang wenhao ying haoming sun yaoqi luo jin he zhonghua zhang haiyu lee yiu-king qiu xiaochan liu shan men six doors 六扇門 the door 六扇门', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-phi-dao', 'Truyền Thuyết Phi Đao', 'The Legend of Flying Daggers', 'https://phimimg.com/upload/vod/20250425-1/4b7ad91ed896cd7406814b89139a47f4.jpg', 'https://phimimg.com/upload/vod/20250425-1/e9b2168ec3c696e43dbe43aabf821043.jpg', '<p>Truyền nhân của “Tiểu Lý Phi Đao” – Lý Hoại (Lưu Khải Uy) dù xuất thân danh môn nhưng phải sống lưu lạc bên ngoài từ nhỏ. Dựa vào tấm họa đồ do mẹ để lại, Lý Hoại đã luyện thành tuyệt học võ công và tìm ra được một kho báu chứa đầy vàng. Lúc này, anh trở lại quê nhà để theo đuổi lý tưởng và tình yêu, đồng thời tìm lại người bạn thanh mai trúc mã Phương Khả Khả (Ngô Ánh Khiết). Mọi chuyện trở nên rắc rối khi anh bị tình nghi có liên can đến số vàng bị mất trong cung. Tiết Thái Nguyệt – Nguyệt Thần (Dương Dung) vốn phụng mệnh triều đình đã bắt Lý Hoại, thế nhưng cô lại đem lòng yêu anh. Mối tình oan nghiệt này đã dẫn đến một kết cục đau thương khi cả hai phải quyết chiến với nhau. Phi đao hựu kiến phi đao được đầu tư nhiều ở khâu kỹ xảo. Vũ khí và những cảnh chiến đấu trong phim đều được thêm các hiệu ứng đặc biệt, lột tả một cách tinh tế nét tinh hoa, huyền diệu của võ thuật Trung Quốc. Đây là điểm khác biệt của Phi đao hựu kiến phi đao với các dòng phim võ hiệp trước đây.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 5, 2016, 'Lồng Tiếng + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hawick Lau Hau-Wai","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Emma Wu","avatar":""},{"name":"Kenny Kwan Chi-Bun","avatar":""},{"name":"Huang Youming","avatar":""},{"name":"Yuan Bingyan","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"Yang Minna","avatar":""},{"name":"Xu Zhengxi","avatar":""},{"name":"Zhou Tingwei","avatar":""},{"name":"Zhao Yunzhuo","avatar":""},{"name":"Lu Shun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["비도우견비도 2016","The Legend of Flying Daggers","飞刀又见飞刀"]', 1784690324410);
