INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('christine-bi-kich-tren-song-truyen-hinh', 'Christine - Bi kịch trên sóng truyền hình', 'Christine', 'https://phimimg.com/upload/vod/20250424-1/cd32a65149eb173e27baa151fd2ca023.jpg', 'https://phimimg.com/upload/vod/20250424-1/7804a9ac6554da2af8268c9117969146.jpg', '<p>Năm 1974, phóng viên truyền hình Christine Chubbuck vật lộn với chứng trầm cảm và những áp lực trong công việc khi cô cố gắng thăng tiến trong sự nghiệp.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rebecca Hall","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Maria Dizzia","avatar":""},{"name":"J. Smith-Cameron","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Kim Shaw","avatar":""},{"name":"John Cullum","avatar":""},{"name":"Morgan Spector","avatar":""},{"name":"Jayson Warner Smith","avatar":""},{"name":"Kimberley Drummond","avatar":""},{"name":"Lindsay Ayliffe","avatar":""},{"name":"Susan Pourfar","avatar":""},{"name":"Rachel Hendrix","avatar":""},{"name":"David Foster","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Christine"]', 1784690324410);
