INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('24h-yeu', '24h Yêu', 'One Day', 'https://phimimg.com/upload/vod/20250420-1/32e8918ed0e78ec3015a9bf60461a20c.jpg', 'https://phimimg.com/upload/vod/20250420-1/0f380fd1e8116ae9b6a08b552a11b99d.jpg', '<p>Là một nhân viên IT 30 tuổi mờ nhạt trong công sở, chỉ được công nhận khi các đồng nghiệp cần hỗ trợ kỹ thuật, thế giới của Denchai bị đảo lộn khi anh sửa máy in cho một cô gái mới tới bộ phận tiếp thị rồi nảy sinh tình yêu sét đánh nhưng chỉ dám yêu đơn phương. Trong chuyến nghỉ dưỡng của công ty tới Hokkaido, Denchai đã ước Nui trở thành bạn gái mình trong Một Ngày. Và như để đáp lại lời cầu nguyện của anh, Nui bị ngã và được chẩn đoán sẽ rối loạn mất trí nhớ trong Một Ngày. Denchai nhân cơ hội nói dối mình là bạn trai cô. Liệu Một Ngày có đủ cho anh?</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Nittha Jirayungyurn","avatar":""},{"name":"Theerapat Sajakul","avatar":""},{"name":"Prim Bulakul","avatar":""},{"name":"Kris Srepoomseth","avatar":""},{"name":"Somyot Matures","avatar":""},{"name":"Suttatip Wutchaipradit","avatar":""},{"name":"Rermthon Kemapech","avatar":""},{"name":"Kaz Sawamura","avatar":""},{"name":"Suttichoke Janya-Angkul","avatar":""},{"name":"Valad Saneeh","avatar":""},{"name":"Itthisak Treesanga","avatar":""},{"name":"Pakorn Siriangkul","avatar":""},{"name":"Rinrapat Ar","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fan Day","Fanday…Fan Kun Khae Wan Diaw","Fanday","One Day","แฟนเดย์..แฟนกันแค่วันเดียว"]', 1784690324410);
