INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('24h-yeu', '24h Yêu', 'One Day', '24h yêu one day chantavit dhanasevi nittha jirayungyurn theerapat sajakul prim bulakul kris srepoomseth somyot matures suttatip wutchaipradit rermthon kemapech kaz sawamura suttichoke janya-angkul valad saneeh itthisak treesanga pakorn siriangkul rinrapat ar fan day fanday…fan kun khae wan diaw fanday one day แฟนเดย์..แฟนกันแค่วันเดียว', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-quyen-tieu-tu', 'Long Quyền Tiểu Tử', 'Kung Fu Boys', 'https://phimimg.com/upload/vod/20231219-1/0249317bd1744d64327699cf0c21d674.jpg', 'https://phimimg.com/upload/vod/20231219-1/dfb03e887f823f77e522f4919cd40036.jpg', '<p>Phim kể về một cậu bé người Mỹ gốc Hoa được gửi về Trung Quốc sống cùng cậu của mình. Tại đây, cậu đối mặt với nhiều tình huống khó khăn như bị bắt nạt ở trường, những rắc rối trong gia đình và cả những vụ án bí ẩn. Với niềm đam mê võ thuật và kỹ năng Taekwondo xuất sắc, cậu cùng những người bạn đã vượt qua thử thách và trưởng thành qua từng trận chiến. Phim mang phong cách nhẹ nhàng, hài hước và phù hợp với khán giả trẻ yêu thích võ thuật và những câu chuyện trưởng thành. Đặc biệt, các diễn viên nhí trong phim đều là những võ sĩ Taekwondo thực thụ, từng đạt giải trong các giải đấu quốc tế.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Thuần An","avatar":""},{"name":"Lưu Duệ Lâm","avatar":""},{"name":"Đồng Phi Phi","avatar":""},{"name":"Lương Siêu","avatar":""},{"name":"Ngô Vịnh Luân","avatar":""},{"name":"Dư Vị Vị","avatar":""},{"name":"Hạo Ỷ Linh","avatar":""},{"name":"Trần Hạo Dân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324410);
