INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-noi-gian', 'Sứ Mệnh Nội Gián', 'Line Walker', 'https://phimimg.com/upload/vod/20231109-1/3c16ffafb886f9ebe443a1fcf8e4a957.jpg', 'https://phimimg.com/upload/vod/20231109-1/f50cdecf6dfc96c231f5f73895fe238a.jpg', '<p>Tiếp nối thành công của phiên bản truyền hình, Line Walker bản điện ảnh đưa Đinh tỷ trở lại thế giới ngầm để truy tìm sáu cảnh sát chìm mất tích. Trong quá trình xâm nhập nguy hiểm, cô bất ngờ chạm trán hai trùm xã hội đen quyền lực, đẩy bản thân vào vòng xoáy hiểm nghèo. Cuộc chiến giữa cảnh sát và tội phạm trở nên căng thẳng hơn bao giờ hết khi danh tính của các điệp viên bị đe dọa. Liệu Đinh tỷ có thể hoàn thành nhiệm vụ và bảo toàn mạng sống giữa những âm mưu và phản bội?</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Trương Gia Huy","avatar":""},{"name":"Trương Tuệ Văn","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Xa Thi Mạn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324410);
