INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-menh-noi-gian', 'Sứ Mệnh Nội Gián', 'Line Walker', 'sứ mệnh nội gián line walker ngô trấn vũ cổ thiên lạc trương gia huy trương tuệ văn hứa thiệu hùng xa thi mạn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kamen-rider-amazons-phan-1', 'Kamen Rider Amazons (Phần 1)', 'Kamen Rider Amazons (Season 1)', 'https://phimimg.com/upload/vod/20250414-1/4435c12c04e4bf142a57dcce1345fda5.jpg', 'https://phimimg.com/upload/vod/20250414-1/f3f1ead2afa08dc3a2da9b0905d0ea84.jpg', '<p>Thế giới tràn ngập hàng ngàn quái vật có tên là Amazon, và công ty Dược phẩm Nozama đã thuê một đội đặc biệt để săn lùng và tiêu diệt chúng. Một ngày nọ, đội đang săn lùng hai chiến binh Amazon, Amazon Riders Alpha và Omega, với những người biến hình của họ là Jin và Haruka. Haruka cuối cùng đã gia nhập đội để săn lùng các chiến binh Amazon. Tuy nhiên, khi họ đang cố gắng tiêu diệt một nhóm chiến binh Amazon đang ẩn náu bên trong một nhà hàng, Haruka cuối cùng đã chia sẻ quan điểm của mình với nhóm khi anh phát hiện ra rằng những chiến binh Amazon đó không có ý định làm hại con người. Nhà hàng cũng đã thay đổi Mamoru, một trong những thành viên trong đội. Cuối cùng, anh bắt đầu có hứng thú với việc ăn thịt người. Sau khi Jin và Haruka đánh bại Sigma, Nozama Pharmacy quyết định triển khai một kế hoạch đặc biệt mang tên Tlaloc, một kế hoạch giết chết tất cả các chiến binh Amazon. Mamoru đã phải vật lộn trong Tlaloc vì trước đó anh đã ăn cánh tay của một trong những người bạn của mình, Kazuya Mizaki. Cuối cùng, Haruka đã giải cứu anh và cả hai đều trốn thoát.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0084