INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kamen-rider-amazons-phan-1', 'Kamen Rider Amazons (Phần 1)', 'Kamen Rider Amazons (Season 1)', 'kamen rider amazons (phần 1) kamen rider amazons (season 1)  masked rider amazon 仮面ライダーアマゾン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-mau-muc', 'Cô Vợ Mẫu Mực', 'Padiwarada', 'https://phimimg.com/upload/vod/20250413-1/454b1fc7549d4943066a4d0528a980b5.jpg', 'https://phimimg.com/upload/vod/20250413-1/8901a73388af72b60f6367d03a540c41.jpg', '<p>Padiwaratda trong tiếng Thái cổ dùng để gọi những người vợ công dung ngôn hạnh, vẹn toàn mẫu mực. Bộ phim như một câu chuyện cổ tích nhằm tôn vinh phẩm chất, nét đẹp tâm hồn của một người phụ nữ trong sự đối lập với cuộc đời đầy sóng gió của cô. Bị bố mẹ ruột vứt bỏ từ bé, Rin được nhận nuôi trong gia đình quý tộc Bamlungprasakit. Gia đình đó có 2 cô con gái tên là Baraly và Buranee. Từ khi còn nhỏ bố mẹ đã hứa hôn Baraly cho một dòng họ quý tộc khác là Siwawed. Cả hai vẫn duy trì mối quan hệ thân thiết cho đến khi nhà Siwawed phá sản. Để đền đáp công ơn gia đình Bamlungprasakit, Rin đã tình nguyện kết hôn với con trai dòng họ Siwawed thay cho hai tiểu thư và đổi tên thành Baraly... Với sự chân thành, Rin có thể lay động được trái tim Saran? Trong khi Saran đã yêu cô bạn từ thuở nhỏ.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jirayu Tangsrisuk","avatar":""},{"name":"Ranee Campen","avatar":""},{"name":"Nutwara Vongvasana","avatar":""},{"name":"Chintara Sukapatana","avatar":""},{"name":"Asanai Tientong","avatar":""},{"name":"Thanayong Wongtrakul","avatar":""},{"name":"Savitree Samipak","avatar":""},{"name":"Passin Reungwoot","avatar":""},{"name":"Songsit Rungnopakunsi","avatar":""},{"name":"Suppakorn Kitsuwan","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Chaiwat Thongsaeng","avatar":""},{"name":"Krit Amornchailerk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beloved Loyal Wife","Padivarada","Padiwaradda","ปดิวรัดา"]', 1784690324410);
