INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-vo-mau-muc', 'Cô Vợ Mẫu Mực', 'Padiwarada', 'cô vợ mẫu mực padiwarada jirayu tangsrisuk ranee campen nutwara vongvasana chintara sukapatana asanai tientong thanayong wongtrakul savitree samipak passin reungwoot songsit rungnopakunsi suppakorn kitsuwan daraneenute pasutanavin chaiwat thongsaeng krit amornchailerk beloved loyal wife padivarada padiwaradda ปดิวรัดา', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-5-troi-sap', 'Kỷ Băng Hà 5: Trời Sập', 'Ice Age: Collision Course', 'https://phimimg.com/upload/vod/20250412-1/cb2f6a7ef2e4be7201fac2d951d38f5e.jpg', 'https://phimimg.com/upload/vod/20250412-1/210dda39091c7c0030a9c6211a1a60b0.jpg', '<p>Chú sóc Scrat cùng hạt dẻ thân yêu tiếp tục cuộc hành trình kỳ lạ khi lên nhầm phi thuyền phóng ra ngoài trái đất. Tại đây, Scrat lại vô tình khiến vũ trụ biến đổi và các thiên thạch bắt đầu rơi xuống. Để chạy trốn thảm họa, Manny, Sid, Diego và các bạn quyết định rời quê nhà và bắt đầu cuộc phiêu lưu nhiều thú vị và đầy ắp tiếng cười đến những vùng đất xa xôi mới, gặp được nhiều người bạn mới và cũng chạm mặt thêm kẻ thù mới.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Keke Palmer","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Neil deGrasse Tyson","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Jessie J","avatar":""},{"name":"Adam Devine","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Melissa Rauch","avatar":""},{"name":"Michael Strahan","avatar":""},{"name":"Nick Offerman","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn T