INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-tu-thu', 'Lật Mặt Tử Thù', 'Monster', 'https://phimimg.com/upload/vod/20250411-1/4439aea68f9dea12694ba9463b130d25.jpg', 'https://phimimg.com/upload/vod/20250411-1/aba0903e8c8da5ce3a379ad8b0663cec.jpg', '<p>Phim kể về câu chuyện của một người đàn ông đã vượt lên tất cả khó khăn của cuộc sống với mong muốn tột cùng là trả thù cho gia đình, trả thù những kẻ cường quyền đã cướp mất những gì quý giá nhất của anh. Nhưng giữa cuộc sống đầy hận thù tăm tối trong đời anh gặp được tình yêu của đời mình, giữa những gian trá của bọn cầm quyền.</p>', 'Hoàn Tất (100/100)', 100, 'series', 'completed', 7, 2016, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ji-hwan","avatar":""},{"name":"Sung Yu-ri","avatar":""},{"name":"Park Ki-woong","avatar":""},{"name":"Claudia Kim","avatar":""},{"name":"Lee Gi-kwang","avatar":""},{"name":"Lee Yul-eum","avatar":""},{"name":"Jung Bo-seog","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Jo Bo-ah","avatar":""},{"name":"Lee Duck-hwa","avatar":""},{"name":"Bae Jong-ok","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Kim Bo-yeon","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Jin Tae-hyeon","avatar":""},{"name":"Lee El","avatar":""},{"name":"Kim Dong-hee","avatar":""},{"name":"Kim Min-Seo","avatar":""},{"name":"Cha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Monseuteo","Tyrant","Monster","몬스터"]', 1784690324410);
