INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lat-mat-tu-thu', 'Lật Mặt Tử Thù', 'Monster', 'lật mặt tử thù monster kang ji-hwan sung yu-ri park ki-woong claudia kim lee gi-kwang lee yul-eum jung bo-seog park young-kyu jo bo-ah lee duck-hwa bae jong-ok jung woong-in kim bo-yeon kim hye-eun kim won-hae jin tae-hyeon lee el kim dong-hee kim min-seo cha monseuteo tyrant monster 몬스터', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-hoa-van-su-thanh', 'Gia Hòa Vạn Sự Thành', 'Happy Home', 'https://phimimg.com/upload/vod/20250410-1/68c1da5332687c48172f91edb6c86a56.jpg', 'https://phimimg.com/upload/vod/20250410-1/d41c199f02382073fb04f92a258f4aee.jpg', '<p>Gia đình Bong Sam Bong, chủ một nhà hàng Trung Quốc và ba người con: hai chị em sinh đôi một trai, một gái Hae Ryung và Man Ho, cùng cô em út Hae Won. &nbsp;Ba chị em, mỗi người một hoàn cảnh một số phận, điều chung nhất của họ chính là cuộc sống luôn gặp những điều rắc rối. Cô chị cả Hae Ryung tuy có một gia đình ấm áp nhưng đó chỉ là vẻ bên ngoài, cô luôn phải hứng chịu những áp lực không nhỏ từ ngôi nhà nhỏ của mình, cậu thứ 2 thì luôn phải dựa vào vợ mình và luôn bị xem nhẹ vì kém cỏi còn cô út thì Hae Won là một người phụ nữ xinh đẹp và thành công nhưng luôn gặp rắc rối từ sếp mình.</p>', 'Hoàn Tất (102/102)', 102, 'series', 'completed', 5, 2016, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim So-yeon","avatar":""},{"name":"Lee Sang-woo","avatar":""},{"name":"Lee Pil-mo","avatar":""},{"name":"Kim Yeong-cheol","avatar":""},{"name":"Kang Yi-eun","avatar":""},{"name":"Won Mi-kyung","avatar":""},{"name":"Jang In-sub","avatar":""},{"name":"Yoon Da-hoon","avatar":""},{"name":"So Hee-jung","avatar":""},{"name":"Ji Soo-won","avatar":""},{"name":"Ahn Hyo-seop","avatar":""},{"name":"Park Ji-il","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gahwamansasung","All’s Well with a Happy Home","Sweet Home","Bong''s Happy Restaurant","가화만사성"]', 1784690324410);
