INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thay-y-duc-phan-1', 'Người Thầy Y Đức (Phần 1)', 'Dr. Romantic (Season 1)', 'https://phimimg.com/upload/vod/20231004-1/a7bfcabb5e14f09d071737b4f7f3d892.jpg', 'https://phimimg.com/upload/vod/20231004-1/aedaed06dd0202136691549aa2bb08ae.jpg', '<p>Người Thầy Y Đức là bộ phim truyền hình Hàn Quốc được giới phê bình đánh giá cao, đồng thời rất thành công về mặt thương mại với sự tham gia của Yoo Yeon Seok và Seo Hyn Jin. Kang Dong Joo là một bác sĩ có khát khao trở thành người vượt trội nhất, và Yoo Seo Jung là một nữ bác sĩ nỗ lực không ngừng để được mọi người công nhận. Họ không có điểm chung nào trước đó cho đến khi cả hai gặp được vị bác sĩ tài ba nhưng kỳ quặc, Kim Sa Bu. Từ đó hai người bắt đầu hiểu ý nghĩa thực sự của cuộc sống và tình yêu.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Suk Gyu","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Hyun-jin Seo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324410);
