INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-va-bon-chang-hiep-si', 'Lọ Lem Và Bốn Chàng Hiệp Sĩ', 'Cinderella And Four Knights', 'https://phimimg.com/upload/vod/20250401-1/358c53c7ad0d01f29d2169031423de0b.jpg', 'https://phimimg.com/upload/vod/20250401-1/07216cbe19b7d0c0da18a288f8f3fecf.jpg', '<p>Lọt vào mắt xanh của một quý ông giàu có, cô gái can đảm Ha Won được ông cụ thuê. Nhiệm vụ của cô là sống cùng ba đứa cháu trai thiếu chín chắn của ông, từ đó uốn nắn họ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Il-woo","avatar":""},{"name":"Park So-dam","avatar":""},{"name":"Ahn Jae-hyun","avatar":""},{"name":"Lee Jung-shin","avatar":""},{"name":"Hye-ri Kim","avatar":""},{"name":"Choi Eun-kyeong","avatar":""},{"name":"Son Na-eun","avatar":""},{"name":"Choi Shang","avatar":""},{"name":"Kim Yong-geon","avatar":""},{"name":"Go Bo-gyeol","avatar":""},{"name":"Park Min soo","avatar":""},{"name":"Jeon Jin-seo","avatar":""},{"name":"Lee Na-Yoon","avatar":""},{"name":"Hong Dong-yeong","avatar":""},{"name":"Jo Yong jin","avatar":""},{"name":"Park Ji So","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cinderella and the Four Knights","Cinderellawa Ne Myungui Gisa","니가 처음이야","Золушка и четыре принца","Четыре принца для золушки","You''re the First","Cinderella with Four Knights","신데렐라와 네명의 기사"]', 1784690324410);
