INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lo-lem-va-bon-chang-hiep-si', 'Lọ Lem Và Bốn Chàng Hiệp Sĩ', 'Cinderella And Four Knights', 'lọ lem và bốn chàng hiệp sĩ cinderella and four knights jung il-woo park so-dam ahn jae-hyun lee jung-shin hye-ri kim choi eun-kyeong son na-eun choi shang kim yong-geon go bo-gyeol park min soo jeon jin-seo lee na-yoon hong dong-yeong jo yong jin park ji so cinderella and the four knights cinderellawa ne myungui gisa 니가 처음이야 золушка и четыре принца четыре принца для золушки you''re the first cinderella with four knights 신데렐라와 네명의 기사', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-dory', 'Đi Tìm Dory', 'Finding Dory', 'https://phimimg.com/upload/vod/20250327-1/4cb96c5ad8d823b17a0972cea6ae28fe.jpg', 'https://phimimg.com/upload/vod/20250327-1/ea2a3eed59a9d0d97087bc3cb878fe7f.jpg', '<p>13 năm trước, Finding Nemo từng cuốn hút khán giả với một câu chuyện cuốn hút và đầy cảm xúc. Bộ phim này từng gắn liền với tuổi thơ của một thế hệ khán giả. 13 năm sau, bộ ba Marlin, Nemo và Dory tiếp tục đưa người xem vào một chuyến đi thú vị không kém và chắc chắn nó sẽ lại gắn liền với một thế hệ khán giả mới. &nbsp;Nhân vật chính của câu chuyện lần này không phải bố con Marlin &amp; Nemo nữa mà là cô nàng Dory. Những mảnh ghép kí ức vụn vặt chợt này ra trong đầu Dory đã thôi thúc cô đi tìm gia đình của mình. Chính điều này đã đưa Dory lạc tới một viện hải dương học ở bên kia đại dương khiến bố con Nemo phải lên đường giải cứu người bạn của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Albert Brooks","avatar":""},{"name":"Ellen DeGeneres","avatar":""},{"name":"Ed O''Neill","avatar":""},{"name":"Hayden Rolence","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Kaitlin Olson","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Andrew Stanton","avatar":""},{"name":"Torbin Xan Bullock","avatar":""},{"name":"Bennett Dammann","avatar":""},{"name":"Bob Peterson","avatar":""},{"name":"Alexander Gould","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Finding Nemo 2","海底奇兵2","Kalatüdruk Dory","Procurando Dory","Oppdrag Dory","Potraga za Dory","U Potrazi za Dori","도리를 찾아서","ファインディング・ドリー","دوري","დორსი ძიებისას","დორის ძიება","پیدا کردن دوری","Đi Tìm Dory","Iskanje pozabljive Dory","İtmiş Balıq Dory","Finding Nemo 2: Finding Dory","Mencari Dory","Findet Dorie","Buscando a Dory","Findet Dory","Finding Dory"]', 1784690324410);
