INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep-5', 'Tiên Kiếm Kỳ Hiệp 5', 'Chinese Paladin 5', 'https://phimimg.com/upload/vod/20250314-1/98425f0872dd3747075e61970f414236.jpg', 'https://phimimg.com/upload/vod/20250314-1/5788b9633a20c3151c0c949f679a8958.jpg', '<p>Khương Vân Phàm - một thiếu niên với trái tim nhiệt huyết, kiên trì chính nghĩa. 20 năm trước, cha Khương Vân Phàm bị lập kế vu oan nên phải chịu trấn áp trong cấm động. 20 năm sau, Vân Phàm thân là nghiệt tử của Khương Thế Li, cũng bị các nhà truy sát. Vân Phàm quen biết với Đường Vũ Nhu - cô gái mang chứng bệnh kỳ quái, Tiểu Man - đệ tử Thục Sơn, Long U - Ma giới Dạ xoa tộc. Vượt qua bao khảo nghiệm, Vân Phàm thành công bái nhập làm đệ tử Thục Sơn, chăm chỉ luyện tập, tiến bộ thần tốc. Tuy nhiên do vẫn mặc cảm vì xuất thân của mình, Vân Phàm không dám đáp trả tình cảm của Vũ Nhu.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 6, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Hàn Đông Quân","avatar":""},{"name":"Trịnh Nguyên Sướng","avatar":""},{"name":"Tiểu Thái Kỳ","avatar":""},{"name":"Vương Chỉ Huyên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["仙剑奇侠传5","仙劍雲之凡","Sword and Fairy 5","Chinese Paladin 5","仙剑云之凡"]', 1784690324410);
