INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-thi-biet-noi', 'Tử Thi Biết Nói', 'The Autopsy of Jane Doe', 'https://phimimg.com/upload/vod/20250309-1/6a2d7c9cefdb7bfc0e8bc98a8004d5fc.jpg', 'https://phimimg.com/upload/vod/20250309-1/d0f632215385ea95b635b0e2e3ef097e.jpg', '<p>Thi thể của cô nàng Jane Done vẫn nguyên vẹn sau khi chết nên cơ quan cảnh sát buộc phải yêu cầu 2 bác sĩ pháp y Cox và Hirsch thực hiện ca giải phẫu để tìm nguyên nhân cái chết. Những bí mật khủng khiếp đã được hé lộ dần dần và dường như có một thế lực đang gieo rắc nỗi kinh hoàng này...</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Ophelia Lovibond","avatar":""},{"name":"Olwen Catherine Kelly","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Parker Sawyers","avatar":""},{"name":"Jane Perry","avatar":""},{"name":"Mark Phoenix","avatar":""},{"name":"Mary Duddy","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["L''autopsie de Jane Doe","Tundmatu naise lahkamine","Obdukcija Džejn Do","Вскрытие Джейн Доу","Вскрытие неизвестной","The Autopsy of Jane Doe"]', 1784690324410);
