INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-khu-tinh-thu', 'Quá Khứ Tình Thù', 'Buang Rak Salak Kaen', 'https://phimimg.com/upload/vod/20250305-1/4176b7a202d599ea0e08951853758d12.jpg', 'https://phimimg.com/upload/vod/20250305-1/e380e3f4da2f87fe6043aad3e3bdea6c.jpg', '<p>Được anh chàng đẹp trai nhà giàu Chayapol theo đuổi, Pan Dao nhanh chóng bị chinh phục và trao trọn trái tim mình cho anh. Nhưng cô đâu ngờ ngay từ đầu Chayapol cố tình tiếp cận cô là để trả thù cho những tổn thương mà bố của cô đã gây ra cho mẹ anh trong quá khứ. Đứng trước những ân oán tình thù rối rắm của thế hệ trước, mối tình của thế hệ sau sẽ có kết cục thế nào?</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2016, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Iang Sittha Sapanuchart","avatar":""},{"name":"Joon Cholrudee Amornluk","avatar":""},{"name":"Nus Nusba Punnakanta","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Buang Ruk Salak Kaen","บ่วงรักสลักแค้น"]', 1784690324410);
