INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nhan-hanh', 'Tam Nhân Hành', 'Three', 'https://phimimg.com/upload/vod/20231219-1/b1d6e046ac52adb9f2f1cfc5af058ff5.jpg', 'https://phimimg.com/upload/vod/20231219-1/fc07085ce57cab3184e8a4b4ff31eb22.jpg', '<p>Tam Nhân Hành xoay quanh mối quan hệ phức tạp của ba nhân vật: nữ bác sĩ Đồng Sảnh có tính cách tự tin nhưng cố chấp, Vĩ Lạc - một cảnh sát xuất sắc nhưng bị áp lực công việc và Lễ Tín - tên tội phạm thông minh đang bị truy nã. Trong một lần bị truy bắt, Lễ Tín bị thương và uy hiếp cảnh sát đưa mình đến bệnh viện nhưng từ chối chữa trị để chờ đồng bọn. Đồng Sảnh quyết định giúp đỡ Lễ Tín bất chấp sự ngăn cản của Vĩ Lạc. Cuộc đấu trí giữa ba người dần hé lộ những bí ẩn trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Triệu Vy","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Ngô Gia Tinh","avatar":""},{"name":"Tạ Thiên Hoa","avatar":""},{"name":"Hồng Thiên Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324410);
