INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-vong-phan-1', 'Sự thất vọng (Phần 1)', 'The Letdown (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/ff9f1af7aa270c83462861f8887c5d48.jpg', 'https://phimimg.com/upload/vod/20250116-1/87cf36f35a76f181467df03e04a23382.jpg', '<p>Audrey, mẹ của bé 2 tháng tuổi, tham gia nhóm hỗ trợ cha mẹ mới có con. Cô kết bạn với những người kỳ cục và đối mặt với nhiều thách thức cũng như đổi thay của cuộc sống.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 14, 2016, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Alison Bell","avatar":""},{"name":"Duncan Fellows","avatar":""},{"name":"Sacha Horler","avatar":""},{"name":"Leon Ford","avatar":""},{"name":"Lucy Durack","avatar":""},{"name":"Celeste Barber","avatar":""},{"name":"Leah Vandenberg","avatar":""},{"name":"Xana Tang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["丧气老妈","렛 다운","The Letdown"]', 1784690324410);
