INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-thong-bat-dac-di-phan-1', 'Tổng Thống Bất Đắc Dĩ (Phần 1)', 'Designated Survivor (Season 1)', 'https://phimimg.com/upload/vod/20250115-1/44222c83f269c426e72df92c5b804831.jpg', 'https://phimimg.com/upload/vod/20250115-1/d02c6f279f4da2696d5a0a48bb6b6991.jpg', '<p>Vào đêm của Liên bang, một vụ nổ phá hủy Tòa nhà Quốc hội, giết chết Tổng thống và mọi người trong hàng ngũ kế vị, ngoại trừ Bộ trưởng Phát triển Nhà và Đô thị Thomas Kirkman, người được mệnh danh là người sống sót được chỉ định. Kirkman ngay lập tức tuyên thệ, không biết rằng cuộc tấn công chỉ là khởi đầu của những gì sắp xảy ra.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Adan Canto","avatar":""},{"name":"Italia Ricci","avatar":""},{"name":"Emiliano Díez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Επιζών της Επόμενης Μέρας","지정 생존자","Дежурный преемник","Последний кандидат","Designated Survivor. 720p","Designated Survivor"]', 1784690324410);
