INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-chuc-phap-su-phan-1', 'Toàn Chức Pháp Sư (Phần 1)', 'Quanzhi Fashi (Season 1)', 'https://phimimg.com/upload/vod/20250113-1/a37d1c9f949f0a0b713ddf30b58d211a.jpg', 'https://phimimg.com/upload/vod/20250113-1/1c74716d1b2c52cc9a0efd82a8fd028d.jpg', '<p>Mở mắt tỉnh giấc, thế giới đại biến. Một trường cấp 3 quen thuộc giảng dạy Ma pháp, cổ vũ các học sinh phải trở thành Ma pháp sư xuất sắc. Bên ngoài đô thị, lũ yêu ma quỷ quái đăng chằm chằm nhìn loài người như hổ đói, chực chờ tấn công. Thế giới vốn tôn sùng khoa học giờ đây tôn sùng Ma pháp... Mạc Phàm phát hiện hầu hết mọi người chỉ học được một hệ ma thuật, nhưng cậu lại là một pháp sư toàn năng...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Junhua Feng","avatar":""},{"name":"Niang Gui","avatar":""},{"name":"Li Yuantao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Quan Zhi Fa Shi","全职法师特别篇之神秘委托","The Almighty Wizard","全职法师","The Almighty Wizard SP:A Mysterious Commission","Quanzhi Fashi","Almighty Mage","전직 법사","Маг на полную ставку","Штатный волшебник","Full-Time Magister","Versatile Mage"]', 1784690324410);
