INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-ke-2016', 'Mẹ Kế', 'Mon Rak Asoon', 'https://phimimg.com/upload/vod/20250111-1/d7ff9268086c6d288eaffb5832d89d76.jpg', 'https://phimimg.com/upload/vod/20250111-1/bf29e534bd27386a51b2ee9d5c31c573.jpg', '<p>Bố vừa ốm đau bệnh tật vừa nợ nần chồng chất, cô giáo trẻ Nampung đứng trước nguy cơ phải làm vợ bé của chủ nợ. May mắn thay, vào lúc đó cô được nhận vào làm gia sư cho Nan, một cậu bé nhà giàu mồ côi mẹ. Ban đầu giữa Nampung và bố Nan là Therd không có thiện cảm, nhưng dần dần, khả năng sư phạm và sự lương thiện của Nampung đã chinh phục và chữa lành trái tim chịu nhiều tổn thương của cả hai bố con.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2016, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Rattapoom Toekongsap","avatar":""},{"name":"Chalida Klampan","avatar":""},{"name":"Panu Suwanno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["What About Brian"]', 1784690324410);
