INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-vet-2016', 'Dấu Vết', 'Signal', 'https://phimimg.com/upload/vod/20250101-1/0c45cc8cd84dcaff6cdeb782d4e93590.jpg', 'https://phimimg.com/upload/vod/20250101-1/64ccd758435b8508fb6257067764c24b.jpg', '<p>Sau khi phá một vụ án bắt cóc, chuyên viên tâm lý tội phạm Park Hae Young được thanh tra Cha Soo Hyun mời về đội của cô để điều tra các vụ án nhiều năm rồi chưa được giải quyết. Điều Soo Hyun không biết là Hae Young luôn được trợ giúp bởi Lee Jae Han - một cảnh sát sống cách họ 15 năm - thông qua một chiếc bộ đàm bí ẩn. Sự liên lạc giữa họ làm thay đổi quá khứ, và hiện tại cũng vì thế mà thay đổi theo.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je Hoon","avatar":""},{"name":"Kim Hye Soo","avatar":""},{"name":"Jo Jin Woong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["解碼追兇","אות","سیگنال","Sigeuneol","信號","signal","시그널"]', 1784690324410);
