INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-trong-nguc', 'Hoa Trong Ngục', 'The Flower In Prison', 'https://phimimg.com/upload/vod/20241229-1/46117b6791548a161bc142c7a494c5b4.jpg', 'https://phimimg.com/upload/vod/20241229-1/cdcb6db6cc941c315e90f1812b7d335e.jpg', '<p>Ok Nyeo là một nữ nhân được sinh ra và nuôi nấng trong nhà ngục dưới thời Joseon. May mắn được tiếp xúc với nhiều nhân tài bị giam cầm, Ok Nyeo trở thành người tinh thông về luật pháp. Khi lớn lên, cô quyết định dùng kiến thức của mình để đứng ra biện hộ cho những tù nhân oan ức.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 10, 2016, 'Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin Se-yeon","avatar":""},{"name":"Go Soo","avatar":""},{"name":"Kim Mi-sook","avatar":""},{"name":"Jeong Jun-ho","avatar":""},{"name":"Park Joo-mi","avatar":""},{"name":"Yoon Joo-hee","avatar":""},{"name":"Jun Kwang-ryul","avatar":""},{"name":"Choi Tae-joon","avatar":""},{"name":"Jung Eun-pyo","avatar":""},{"name":"Jung Da-bin","avatar":""},{"name":"Jung Yoon-suk","avatar":""},{"name":"Kim Soo Yun","avatar":""},{"name":"Im Ho","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Seo Ha-jun","avatar":""},{"name":"Oh Na-ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["گلی در زندان","オクニョ～運命の女（ひと）～","Okjoonghwa","獄中花","옥중화"]', 1784690324410);
