INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-an-quan-he-cha-con-cua-lauren-lake-phan-4', 'Tòa Án Quan Hệ Cha Con Của Lauren Lake (Phần 4)', 'Lauren Lake''s Paternity Court (Season 4)', 'https://phimimg.com/upload/vod/20241226-1/5435774e9ac3ba1f6ca542704a0b2ba4.jpg', 'https://phimimg.com/upload/vod/20241226-1/7fa16e5fa40ce8d84a3f2b635c3d3c38.jpg', '<p>Paternity Court là chương trình trò chuyện kết hợp dài nửa giờ sử dụng định dạng nguyên đơn / bị đơn của chương trình tòa án. Lake trò chuyện với những người kiện tụng trong chương trình và quyết định các vụ án dựa trên kết quả xét nghiệm DNA.</p>', 'Hoàn Tất (109/109)', 109, 'tvshows', 'completed', 12, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Lake","avatar":""},{"name":"Mike Jerome Putnam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Paternity Court","Lauren Lake''s Paternity Court"]', 1784690324410);
