INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toa-an-quan-he-cha-con-cua-lauren-lake-phan-4', 'Tòa Án Quan Hệ Cha Con Của Lauren Lake (Phần 4)', 'Lauren Lake''s Paternity Court (Season 4)', 'tòa án quan hệ cha con của lauren lake (phần 4) lauren lake''s paternity court (season 4) lauren lake mike jerome putnam paternity court lauren lake''s paternity court', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-nhan-so-phan-5', 'Hữu Nhân Sổ (Phần 5)', 'Natsume''s Book Of Friends (Season 5)', 'https://phimimg.com/upload/vod/20241220-1/82514317a34721d7e379cde64b894d51.jpg', 'https://phimimg.com/upload/vod/20241220-1/e634e4704333eac3bf5a1501a30bc96c.jpg', '<p>Từ rất lâu rồi, cậu bé Natsume Takashi đã phát hiện ra mình có khả năng nhìn thấy được các linh hồn, yêu quái - Một năng lực được kế thừa từ người bà quá cố Reiko của mình. Sau khi chết, Reiko đã truyền lại cho người cháu mình cuốn Hữu Nhân Sổ; đây là một cuốn sổ chứa những cái tên của các yêu quái mà Reiko đã thu thập để làm phục dịch cho bà. Hữu Nhân Sổ là một bảo vật trong thế giới linh hồn, chính vì điều này mà Takashi liên tục bị những hồn ma &quot;ám&quot;. Dù Reiko là người lập khế ước và giam hãm các linh hồn, cháu của bà - Takashi lại là người hủy bỏ khế ước và thả tự do cho các linh hồn đến nhờ anh giúp đỡ. Nhưng có những yêu quái độc ác vẫn muốn giết anh bằng mọi giá để cướp cuốn sổ. Lúc này, Madara (hay còn được Natsume gọi là Nyanko-sensei) xuất hiện, ông trở thành vệ sĩ và là cố vấn của Natsume. Dù ông lúc nào cũng ra vẻ muốn chiếm Hữu Nhân Sổ, nhưng ông dần trở thành người bạn đồng hành thân thiết của Natsume Takashi.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Eiji Itoh","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Hisayoshi Suganuma","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Sanae Kobayashi","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Kazuma Horie","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Rina Sato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夏目友人帐 陆","夏目友人帐 伍","夏目友人帐 肆","夏目友人帐 参","续 夏目友人帐","夏目友人帐 柒","夏目友人帐","Pakt der Yokai","Le Pacte des Yōkai","Knjiga Prijatelja","Natsume yûjinchô","کتابِ دوستان ناتسومه","Natsume Yuujinchou","Natsume Yūjin-Chō","Natsume Yūjinchō","Natsume Yuujinchou Go","Natsume Yuujinchou Roku","Natsume Yuujinchou Shi","Natsume Yuujinchou San","Zoku Natsume Yuujinchou","夏目友人帳 陸","続 夏目友人帳","夏目友人帳 参","夏目友人帳 肆","夏目友人帳 伍","Natsume Yuujinchou Shichi","夏目友人帳 漆","나츠메 우인장","나츠메우인장","Тетрадь дружбы Нацумэ","นัตสึเมะกับบันทึกสหาย","Книга друзів Нацуме","Natsume''s Book of Friends","Natsume''s Friend Book","Natsume Yujin-cho","Quyển sổ người bạn","Hữu Nhân Sổ","夏目友人帳"]', 1784690324410);
