INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-dung-toi-ac', 'Chân Dung Tội Ác', 'Night and Day', 'https://phimimg.com/upload/vod/20241214-1/4133a520f9f726928fa11da1c8443cdf.jpg', 'https://phimimg.com/upload/vod/20241214-1/a01a656d1857c50f12cc221c53505cb7.jpg', '<p>Sara Grau là một nữ bác sĩ pháp y, có cuộc sống hôn nhân hạnh phúc bên người chồng là giám đốc điều hành cấp cao. Vào một ngày khi Sara khám nghiệm tử thi, cô nhận ra xác chết chính là người tình trong quá khứ của mình. Phát hiện này khiến cho cuộc sống của cô bị đảo lộn và những bí mật được che giấu bấy lâu trong vỏ bọc của một cuộc hôn nhân yên bình dần hé lộ.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 12, 2016, 'Lồng Tiếng', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Clara Segura","avatar":""},{"name":"Pablo Derqui","avatar":""},{"name":"David Verdaguer","avatar":""},{"name":"Miquel Fernández","avatar":""},{"name":"Oriol Vila","avatar":""},{"name":"Alba Pujol","avatar":""},{"name":"Anna Alarcón","avatar":""},{"name":"Victòria Pagès","avatar":""},{"name":"Josep Maria Pou","avatar":""},{"name":"Lluïsa Mallol","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Night and Day","Nit i dia"]', 1784690324410);
