INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-loi-anh-yeu-em-ban-thai', 'Xin Lỗi Anh Yêu Em (Bản Thái)', 'Sorry I Love You (Thailand Version)', 'https://phimimg.com/upload/vod/20240126-1/1c76955d1333bb00be6d4f535d52601e.jpg', 'https://phimimg.com/upload/vod/20240126-1/dc4de842a39e42c82e2429b71e91348e.jpg', '<p>Nike bị cha mẹ bỏ rơi và sống nay đây mai đó với nghề cướp giật. Tanatat là ca sĩ nổi tiếng, anh có nhân viên phục trang là Punch. Một lần lưu diễn, Punch quyết định bỏ về nước trước khi anh lưu diễn xong. Không may, Punch bị 1 toán lang thang giống như Nike cướp toàn bộ hành lý và giấy tờ. Ban đầu Nike định lừa bán Punch để kiếm tiền nhưng anh đã kịp nhận ra Punch là cô bé rất đáng thương. Sáng hôm sau khi Punch tỉnh dậy thì đã thấy hành lý của mình như chưa hề bị cướp... Về phần Nike, anh tham gia lễ cưới của người yêu cũ (đã bỏ anh để chạy theo đồng tiền). Bi kịch xảy ra khi Nike vô tình bị trúng 2 phát đạn vào đầu khi anh cố gắng cứu cô người yêu phản bội thoát khỏi bàn tay kẻ sát nhân. Nike được cứu sống nhưng vẫn còn sót 1 viên đạn trong đầu. Biết mình không còn sống được lâu, Nike trở về quê hương Thái Lan để tìm mẹ ruột đã bỏ rơi mình. Nhưng sự thật quá vô tình khi anh phát hiện ra mẹ mình là diễn viên nổi tiếng cùng cậu con trai Tanatat đang sống trong vinh hoa phú quý. Cũng từ ngày đó Nike gặp lại Punch, tình cảm hai người dần sâu sắc, rồi hàng loạt những biến cố đã xảy ra...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 10, 2016, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Nitidon Pomsuwan","avatar":""},{"name":"Worakarn Rojjanawat","avatar":""},{"name":"Kangsom Tanatat Chaiyaat","avatar":""},{"name":"Mo Monchanok Saengchaipiangpen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324410);
