INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-trai-phan-1', 'Trang Trại (Phần 1)', 'The Ranch (Season 1)', 'https://phimimg.com/upload/vod/20241206-1/aa596465694eb834e876bc6d91521fb9.jpg', 'https://phimimg.com/upload/vod/20241206-1/48269c1406e77a166e40a498561aa591.jpg', '<p>Giấc mơ không thành, ngôi sao thể thao hết thời trở về trang trại của gia đình ở Colorado để rồi ngộ ra mọi thứ đã thay đổi kể từ khi anh ra đi theo đuổi giấc mơ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ashton Kutcher","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Debra Winger","avatar":""},{"name":"Elisha Cuthbert","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Megyn Price","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Kelli Goss","avatar":""},{"name":"Danny Masterson","avatar":""},{"name":"Wilmer Valderrama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["El Rancho","O Rancho","牧场趣事","牧场物语","The Ranch"]', 1784690324410);
