INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mi-nhan-vi-ham', 'Mĩ Nhân Vi Hãm', 'Memory Lost', 'https://phimimg.com/upload/vod/20241201-1/8c9b4efd48e37adf4e96f308a2df533f.jpg', 'https://phimimg.com/upload/vod/20241201-1/6cbf5c6f6bb3b724b0007296f6cd640d.jpg', '<p>Bộ phim Truy Tìm Ký Ức được chuyển thể từ tiểu thuyết trinh thám Mỹ Nhân Vi Hạm của tác giả Đinh Mặc, với sự tham gia của các diễn viên Dương Dung và Bạch Vũ. Truy tìm ký ức là tác phẩm thứ ba về đề tài trinh thám phá án của tác giả Đinh Mặc sau Nếu ốc sên có tình yêu và Hãy nhắm mắt khi anh đến. Nhân vật chính của câu chuyện là Hàn Trầm. Dù mất trí nhớ, anh vẫn luôn tìm kiếm vị hôn thê của mình. Cô gái bị tất cả mọi người phủ định là không có thật trong suốt 5 năm. Và rồi Hàn Trầm đến thành phố Giang, nơi đây anh đã gặp Tô Miên, một cô gái đầy cá tính theo đuổi ngành tâm lý tội phạm. Giống Hàn Trầm, Tô Miên là nhân vật đầy bí ẩn với quá khứ trống rỗng trong suốt 5 năm. Từ khi gặp nhau, anh đưa cô vào một thế giới hoàn toàn</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2016, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ","avatar":""},{"name":"Dương Dung","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mei Ren Wei Xian","Truy Tìm Ký Ức","美人为馅"]', 1784690324410);
