INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngon-tung-ngo-ngach', 'Ngon Từng Ngõ Ngách', 'Delicious Every Corner', 'ngon từng ngõ ngách delicious every corner  步步惊心 韩国版 月亮的恋人 moon lovers:scarlet heart ryeo 月之恋人 步步惊心 corazon escarlata מאהבי הירח レイ〜はなもゆるはちにんのおうじたち〜 麗＜レイ＞～花萌ゆる８人の皇子たち～ 麗〜花萌ゆる8人の皇子たち〜 麗<レイ>〜花萌ゆる8人の皇子たち〜 bobogyungsim: ryeo 보보경심: 려 달의 연인 - 보보경심 려 scarlet heart алое сердце ข้ามมิติ ลิขิตสวรรค์ 月之戀人－步步驚心：麗 закохані під місяцем: багряні серця рьо time slip: ryeo moon lovers scarlet heart: goryeo moon lovers: scarlet heart ryeo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-y-minh-phi-truyen', 'Nữ Y Minh Phi Truyện', 'The Imperial Doctress', 'https://phimimg.com/upload/vod/20241104-1/0d7fd328cc8239ae6e09e261f91a5a41.jpg', 'https://phimimg.com/upload/vod/20241104-1/35299f75cbb7f789855941dc8dcef346.jpg', '<p>Vào thời nhà Minh, các định kiến về vai trò của người phụ nữ là khá thấp kém trong xã hội. Đàm Doãn Hiền là người phụ nữ đầu tiên đã phá bỏ được những luật lệ đó, trở thành nữ y sĩ đầu tiên trong lịch sử. Cùng lúc đó, cô cũng đã có một mối tình nhiều trắc trở với 2 anh em hoàng đế Minh Anh Tông – Chu Kỳ Trấn và Minh Đại Tông – Chu Kỳ Ngọc.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉詩詩","avatar":""},{"name":"霍建華","avatar":""},{"name":"Huang Xuan","avatar":""},{"name":"袁文康","avatar":""},{"name":"Chengyuan Li","avatar":""},{"name":"金晨","avatar":""},{"name":"吳磊","avatar":""},{"name":"Yu Yonghai","avatar":""},{"name":"Joy Sheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Nv Yi Ming Fei Zhuan","Nu Yi Ming Fei Zhuan","女医·明妃传","女醫 明妃傳","여의 담윤현","Госпожа лекарь","Ming Medicine Woman","The Imperial Doctress","女医明妃传"]', 1784690324410);
