INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giu-tre-xinh-dep', 'Cô Giữ Trẻ Xinh Đẹp', 'Babysitter', 'https://phimimg.com/upload/vod/20241104-1/a3a64ab1cf3d4390d371943b7cb07a45.jpg', 'https://phimimg.com/upload/vod/20241104-1/3bec867774f36d6c97fb42925109ae61.jpg', '<p>Tốt nghiệp một trường đại học danh tiếng, sở hữu nhan sắc xinh đẹp nhưng Eun Joo lại lựa chọn công việc bảo mẫu cho một gia đình tài phiệt. Bị ám ảnh bởi sự sang giàu và ước mơ làm chủ nhân căn biệt thự rộng lớn, cô lạc vào con đường tội lỗi không thể quay đầu lại.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Yeo Jeong","avatar":""},{"name":"Kim Min Joon","avatar":""},{"name":"Shin Yoon Joo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Beibishiteo","베이비시터"]', 1784690324410);
