INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ten-cau-la-gi', 'Tên Cậu Là Gì?', 'Your Name', 'tên cậu là gì? your name 神木隆之介 上白石萌音 成田凌 悠木碧 島﨑信長 石川界人 谷花音 てらそままさき 大原さやか 井上和彦 茶風林 かとう有花 花澤香菜 長澤まさみ 市原悦子 寺崎裕香 小野塚貴志 滑川洋平 辻美優 浜添伸也 佐藤奏美 合田慎二郎 菊池康弘 ひなたたまり 山根希美 新祐樹 村上達哉 長谷川暖 バロン山崎 珠希美碧 井上優 宇佐美涼子 森嵜美穂 山口智大 南嶋毅 大前愛華 中務貴幸 松川央樹 根来彰子 大南友希 塙真奈美 田端美 seu nome твое имя numele tau e ... ton nom 너의 이름은. comment tu t''appelles? 你的名字 君之名 หลับตาฝัน ถึงชื่อเธอ twoje imię. 君の名は. kimi no namae wa twoje imię 君の名は your name तुम्हारा  नाम 你的名字。 sənin adın. tvé jméno your name gestern heute und für immer da anv a neved kimi no na wa. योर नेम. your name. (tên cậu là gì.) 君の名は。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-tuoi-xe-chieu', 'Tình Bạn Tuổi Xế Chiều', 'Dear My Friends', 'https://phimimg.com/upload/vod/20241102-1/f8108b5eaaf5f64b487388642cd0b111.jpg', 'https://phimimg.com/upload/vod/20241102-1/d89e71c8b78ea8b7e7de1d4234207cdd.jpg', '<p>Bộ phim mô tả những câu chuyện cuộc sống của những người thân trong những năm cuối đời của họ, những người nói lên tiếng nói của họ như là &quot;Đó không phải là kết thúc, chúng tôi vẫn còn sống&quot;</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"고현정","avatar":""},{"name":"윤여정","avatar":""},{"name":"나문희","avatar":""},{"name":"고두심","avatar":""},{"name":"김혜자","avatar":""},{"name":"박원숙","avatar":""},{"name":"김영옥","avatar":""},{"name":"주현","avatar":""},{"name":"신구","avatar":""},{"name":"조인성","avatar":""},{"name":"Baek Seung-do","avatar":""},{"name":"변우석","avatar":""},{"name":"이광수","avatar":""},{"name":"고보결","avatar":""},{"name":"Nam Neung Mi","avatar":""},{"name":"장현성","avatar":""},{"name":"염혜란","avatar":""},{"name":"신성우","avatar":""},{"name":"Kwon Jae-hyun","avatar":""},{"name":"Kim Jeong-hwan","avatar":""},{"name":"Kang Eun-jin","avatar":""},{"name":"Han Jeong-hyeon","avatar":""},{"name":"성동일","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Meus Queridos Amigos","Dieo Mai Peurenjeu","Dear My Friends","디어 마이 프렌즈"]', 1784690324410);
