INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-menh-thien-tu', 'Chân Mệnh Thiên Tử', 'Destined Emperor', 'https://phimimg.com/upload/vod/20241028-1/5a9021e10476271cd908fb7335c6e940.jpg', 'https://phimimg.com/upload/vod/20241028-1/f3568d50cec44814a07962182decffe1.jpg', '<p>Vào thời Nguyên triều có rất nhiều cao nhân, thuật sĩ tìm đến vùng núi thiêng vì lời đồn đại về sự xuất hiện của long huyệt ngàn năm hiếm có. Trần Hữu Lượng, Hàn Lâm Nhi, Chu Trùng Bát - 3 cậu bé chào đời là điềm báo chân mạng thiên tử xuất hiện. Lưu Bá Ôn – vị bán tiên có võ công cao cường, phép thuật tinh thông mang theo trọng trách tìm kiếm và phò tá người mang chân mạng thiên tử.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 11, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Trác Văn","avatar":""},{"name":"Ô Tịnh Tịnh","avatar":""},{"name":"Quý Tiếu Băng","avatar":""},{"name":"Từ Hải Kiều","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["真命天子"]', 1784690324410);
