INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chan-menh-thien-tu', 'Chân Mệnh Thiên Tử', 'Destined Emperor', 'chân mệnh thiên tử destined emperor trương trác văn ô tịnh tịnh quý tiếu băng từ hải kiều 真命天子', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-la-oh-hae-young', 'Lại Là Oh Hae Young', 'Another Miss Oh', 'https://phimimg.com/upload/vod/20241026-1/4ace2c9ddd8e0df40823aec926341c2a.jpg', 'https://phimimg.com/upload/vod/20241026-1/d845d5ab6d95e40710bc277ee36d5fd6.jpg', '<p>Park Do-kyung (Eric Mun) là một giám đốc âm thanh ngoài 30 tuổi. Một năm trước, cô dâu của anh, Oh Hae-young (xinh đẹp) (Jeon Hye-bin), đã không xuất hiện trong ngày cưới của họ và để lại anh trong đau khổ. Một năm sau sự việc đó, Do-kyung nghe được rằng Hae-young đang chuẩn bị đám cưới với một doanh nhân trẻ tên là Han Tae-jin (Lee Jae-yoon). Do-kyung đã quyết định trả thù bằng cách ngầm phá hủy việc kinh doanh của Tae-jin khiến anh ta bị phá sản.

Sau đó anh mới biết một cô gái khác có tên là Oh Hae-young (bình thường) (Seo Hyun-jin) thực ra chỉ là một người lạ trùng hợp có cùng họ tên với Oh Hae-young (xinh đẹp) người đã rời bỏ anh ấy. Trùng hợp, Oh Hae-young (bình thường) là cô gái mà Do-kyung đã sớm nhìn thấy trong ảo cảnh của anh, và anh có thể nhìn thấy những hình ảnh trong tương lai với cô ấy.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"에릭","avatar":""},{"name":"서현진","avatar":""},{"name":"전혜빈","avatar":""},{"name":"예지원","avatar":""},{"name":"김지석","avatar":""},{"name":"이재윤","avatar":""},{"name":"허정민","avatar":""},{"name":"남기애","avatar":""},{"name":"이한위","avatar":""},{"name":"김미경","avatar":""},{"name":"Ha Si-eun","avatar":""},{"name":"허영지","avatar":""},{"name":"Kwon Hae-sung","avatar":""},{"name":"최병모","avatar":""},{"name":"조현식","avatar":""},{"name":"박명훈","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Outra Senhorita Oh","Otra vez Oh Hae Young","La Otra Señorita Oh","また!? オ・ヘヨン ～僕が愛した未来(ジカン)～","Ddo Ohhaeyoung","또! 오해영","Ddo Oh Hae Yeong","Другая мисс О","امرأتان في أحلامي","Oh Hae Young Again","Another Oh Hae Young","Also Oh Hae Young","Misunderstood","Another Miss Oh","又，吳海英","또 오해영"]', 1784690324410);
