INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grace-va-frankie-phan-2', 'Grace Và Frankie (Phần 2)', 'Grace And Frankie (Season 2)', 'https://phimimg.com/upload/vod/20241019-1/18a682a32af4650753d53f58e2c37237.jpg', 'https://phimimg.com/upload/vod/20241019-1/ce9f46795cb7e2f080367da22b8053e8.jpg', '<p>Họ không phải bạn bè, nhưng khi hai ông chồng bỏ họ để đến với nhau, Grace đúng mực và Frankie lập dị bắt đầu gắn bó trong loạt phim được đề cử giải Emmy này.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jane Fonda","avatar":""},{"name":"Lily Tomlin","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Sam Waterston","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Baron Vaughn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["格蕾丝与弗兰基","同妻俱乐部","Γκρέις και Φράνκι","그레이스 앤 프랭키","Grace & Frankie","Grace and Frankie"]', 1784690324410);
