INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('grace-va-frankie-phan-2', 'Grace Và Frankie (Phần 2)', 'Grace And Frankie (Season 2)', 'grace và frankie (phần 2) grace and frankie (season 2) jane fonda lily tomlin martin sheen sam waterston june diane raphael brooklyn decker ethan embry baron vaughn 格蕾丝与弗兰基 同妻俱乐部 γκρέις και φράνκι 그레이스 앤 프랭키 grace & frankie grace and frankie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-an', 'Thượng Ẩn', 'Addicted', 'https://phimimg.com/upload/vod/20241017-1/87a388ddfc742733c6c3c0ade05e6bcb.jpg', 'https://phimimg.com/upload/vod/20241017-1/8b20eff2020080d043b9d491a9cebd75.jpg', '<p>Bạch Lạc Nhân (do Hứa Ngụy Châu thủ vai) từ nhỏ sống dựa vào cha mình, cuộc sống khó khăn. Ở tuổi 16, mẹ ruột của cậu tái hôn với một quan nhân cao cấp trong quân đội. Trong khi đó, Cố Hải (do Hoàng Cảnh Du thủ vai), là người con thế hệ thứ hai của một quan nhân đã tự tử sau cái chết của mẹ. Anh luôn mang trong lòng sự oan trái với cha mình và phản đối mọi quyết định của cha, thậm chí tự nguyện chuyển trường đến một trường trung học bình thường. Khi bắt đầu năm học mới, hai người này, cả hai đều đầy phê phán, bị sắp xếp vào cùng một lớp học. Nhờ những sự tình cờ, họ trở nên bạn thân và sau đó phát triển tình cảm đặc biệt dành cho nhau. Bạn thân của Bạch Lạc Nhân, Dương Mãnh (Trần Ẩn thủ vai) và cô bạn cùng lớp của họ, Ưu Kỳ (Lâm Phong Tùng) cũng đóng vai trò thúc đẩy tình cảm của họ, và cuộc sống học đường nhiều sắc màu của họ bắt đầu từ đó.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"許魏洲","avatar":""},{"name":"黃景瑜","avatar":""},{"name":"Chen Wen","avatar":""},{"name":"林楓松","avatar":""},{"name":"Wang Dong","avatar":""},{"name":"Liu Xiaoye","avatar":""},{"name":"Song Tao","avatar":""},{"name":"Su Li","avatar":""},{"name":"Xiong Yuexi","avatar":""},{"name":"Pan Yuchen","avatar":""},{"name":"Zhu Wen Shuo","avatar":""},{"name":"Kong Shaoxiong","avatar":""},{"name":"娄清","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '