INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-tien-thanh-van-chi-phan-2', 'Tru Tiên Thanh Vân Chí (Phần 2)', 'Noble Aspirations (Season 2)', 'https://phimimg.com/upload/vod/20241012-1/c7a1c5fba802e9dd4ba8d18d1ff7ac6b.jpg', 'https://phimimg.com/upload/vod/20241012-1/912d711797c85326d1454ece5afbd31e.jpg', '<p>Cậu bé Trương Tiểu Phàm xuất thân từ Thảo Miếu thôn, vì cứu giúp Phổ Trí thần tăng của Thiên Âm tự mà toàn thôn gặp họa diệt vong. Trương Tiểu Phàm mồ côi cùng người bạn Lâm Kinh Vũ đầu nhập Thanh Vân môn. Lâm Kinh Vũ thuộc Long Thủ phong do Thương Tùng đạo nhân quản lý, còn Trương Tiểu Phàm phân về Đại Trúc phong do Điền Bất Dịch quản lý. Tiểu Phàm trong người mang Phệ Huyết châu là vật mang tà khí cực lớn, đêm ngày bị dày vò tâm trí. Tại đỉnh Đại Trúc, Tiểu Phàm ngày ngày vui vẻ nấu cơm, không ngờ vô tình lại bắt được thần khí luyện huyết Phệ Hồn, còn thầm mến cô bé hoạt bát đáng yêu Điền Linh Nhi.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Yifeng","avatar":""},{"name":"赵丽颖","avatar":""},{"name":"杨紫","avatar":""},{"name":"Tang Yixin","avatar":""},{"name":"Yi Ding","avatar":""},{"name":"Chen Chuang","avatar":""},{"name":"Shu Chang","avatar":""},{"name":"成毅","avatar":""},{"name":"Qin Junjie","avatar":""},{"name":"Fu Cheng Peng","avatar":""},{"name":"Huang Haibing","avatar":""},{"name":"He Zhonghua","avatar":""},{"name":"赵立新","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Xie Ning","avatar":""},{"name":"曾黎","avatar":""},{"name":"佟梦实","avatar":""},{"name":"Zheng Guolin","avatar":""},{"name":"任嘉倫","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},