INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-bay-cuoc-doi', 'Cạm Bẫy Cuộc Đời', 'Stolen Innocence (Bittersweet)', 'https://phimimg.com/upload/vod/20241011-1/6de1426883d111b4d0eb441eef185295.jpg', 'https://phimimg.com/upload/vod/20241011-1/3015b3c66181047bc256acbb1c284ed0.jpg', '<p>Sau cuộc cãi vã khủng khiếp với cha mẹ bảo thủ của mình, Mina, 19 tuổi, chuyển đến sống cùng chị gái Mandy, người làm nghề mại dâm. Mina tìm thấy tình yêu khi gặp Tony, một DJ gặp vấn đề về tài chính. Nhưng hai kẻ đòi nợ nham hiểm đưa ra tối hậu thư quyết liệt: họ có ba ngày để huy động được 11.000 Euro. Lời khuyên của Mandy dành cho Mina thật là độc ác: hãy bán thứ đắt giá nhất mà cô sở hữu, đó là trinh tiết của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Lisa Brand","avatar":""},{"name":"Manuel Cortez","avatar":""},{"name":"Jessy Moravec","avatar":""},{"name":"Steffen Jürgens","avatar":""},{"name":"Milton Welsh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Stolen Innocence","BitterSüß"]', 1784690324410);
