INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-hoang-phuong-nam-phan-1', 'Bà Hoàng Phương Nam (Phần 1)', 'Queen Of The South (Season 1)', 'https://phimimg.com/upload/vod/20241011-1/f1064cd48f858d55b05ab3dff46aac86.jpg', 'https://phimimg.com/upload/vod/20241011-1/11ece824c592b4640fbe189608aff5ec.jpg', '<p>Buộc phải làm việc cho băng đảng vừa sát hại bạn trai mình, Teresa dựa vào những kiến thức đường phố, một người bạn trung thành và một cuốn sổ tay bí ẩn để sống sót.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alice Braga","avatar":""},{"name":"Hemky Madera","avatar":""},{"name":"Peter Gadiot","avatar":""},{"name":"Veronica Falcón","avatar":""},{"name":"Molly Burnett","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Yancey Arias","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Gerardo Taracena","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Regina del Sud","QUEEN OF THE SOUTH/クイーン・オブ・ザ・サウス ～女王への階段～","남부의 여왕","Queen of the South"]', 1784690324410);
