INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-hoang-phuong-nam-phan-1', 'Bà Hoàng Phương Nam (Phần 1)', 'Queen Of The South (Season 1)', 'bà hoàng phương nam (phần 1) queen of the south (season 1) alice braga hemky madera peter gadiot veronica falcón molly burnett joaquim de almeida yancey arias justina machado gerardo taracena regina del sud queen of the south/クイーン・オブ・ザ・サウス ～女王への階段～ 남부의 여왕 queen of the south', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hanh-trinh-tuyet-voi-phan-1', 'Cuộc Hành Trình Tuyệt Vời (Phần 1)', 'The Grand Tour (Season 1)', 'https://phimimg.com/upload/vod/20241008-1/868908d0607077a712aaf8b1d2f457fe.jpg', 'https://phimimg.com/upload/vod/20241008-1/698c4f4286942994005819ef33c6b080.jpg', '<p>Ngoại trừ hai phần đặc biệt cho loạt phim đầu tiên, mỗi tập đều có các phân đoạn trường quay được quay trong một lô lều tạm được tổ chức trên nhiều ngôn ngữ nước ngoài khác nhau - hai trong số các địa điểm này, mỗi địa điểm được sử dụng cho hai tập riêng biệt nhưng liên tiếp. Mặc dù loạt phim có sự góp mặt của những người nổi tiếng, nhưng hầu hết đều xuất hiện với tư cách nhỏ trong khi những người khác được nhắc đến hoặc có vẻ ngoài giống nhau - những lần xuất hiện này chủ yếu dành cho một trò đùa liên quan đến việc họ đến gặp những người thuyết trình trong lều của họ để phỏng vấn, chỉ để &quot;chết&quot; trong một tai nạn kinh hoàng.</p>', 'Hoàn Tất (13/13)', 13, 'tvshows', 'completed', 13, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Clarkson","avatar":""},{"name":"Richard Hammond","avatar":""},{"name":"James May","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Гранд тур","伟大的旅程","大世界之旅","歌朗途","The Grand Tour","เดอะแกรนด์ทัวร์","Grand Tour, The"]', 1784690324410);
