INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-trong-nhung-nha-tu-khoc-liet-nhat-the-gioi-phan-1', 'Bên Trong Những Nhà Tù Khốc Liệt Nhất Thế Giới (Phần 1)', 'Inside The World''s Toughest Prisons (Season 1)', 'https://phimimg.com/upload/vod/20241008-1/2c3881e2c66f0ff6b6bd1def8837ecad.jpg', 'https://phimimg.com/upload/vod/20241008-1/f8a928dd36c1393666e457f6dcf481ec.jpg', '<p>Paul Connolly thâm nhập vào bên trong các nhà tù tồi tệ tại Ba Lan, Mexico, Honduras và Philippines để trải nghiệm điều kiện sống man rợ của họ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Paul Connolly","avatar":""},{"name":"Raphael Rowe","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["深入世界最艰苦的监狱","最凶监狱大揭秘","深入全球最难熬的监狱","Inside the World''s Toughest Prisons"]', 1784690324410);
