INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-goi-con-tim', 'Tiếng Gọi Con Tim', 'The Sound Of Your Heart', 'https://phimimg.com/upload/vod/20241005-1/65ad47b62c25dfd4d9405dfd49e2026e.jpg', 'https://phimimg.com/upload/vod/20241005-1/d2f9af5e550cb193aa1d2773c1a9300d.jpg', '<p>Là một phiên bản làm lại khác của webtoon cùng tên nổi tiếng, Sound of Your Heart (Tiếng Gọi Con Tim) vẫn xoay quanh câu chuyện thú vị về cuộc đời của anh chàng tác giả webtoon Jo Suk (Sung Hoon), cô bạn gái Ae Bong (Kwon Yuri) và gia đình, bạn bè của anh chàng.

Dưới sự chỉ đạo của PD Jung Jung Hwa – người đã từng rất thành công với loạt phim mỹ nam làm nên tên tuổi của tvN</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung So Min","avatar":""},{"name":"Kim Byung Ok","avatar":""},{"name":"Kim Dae Myeung","avatar":""},{"name":"Kim Me Kyung","avatar":""},{"name":"Lee Kwang Soo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["心灵的声音","Maeumui Sori","Maeumeuisori","ครอบครัวจิตหลุด เพี้ยนสุดหัวใจ","The Sound of Heart","The Sound of Your Mind","Sound of Your Heart","Sound of Heart","The Sound of Your Heart","마음의 소리"]', 1784690324410);
