INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-cuu-mon', 'Lão Cửu Môn', 'The Mystic Nine', 'https://phimimg.com/upload/vod/20241004-1/71ce8c71796a3d52f9281e9f9082b002.jpg', 'https://phimimg.com/upload/vod/20241004-1/d4517f2e058a6692ed5ed90a188243db.jpg', '<p>Lão Cửu Môn chuyển thể từ quyển tiểu thuyết cùng tên của Nam Phái Tam Thúc. Bộ phim xoay quanh câu chuyện đi tìm lịch sử của chín gia tộc trộm mộ ở Hồ Nam, Trung Quốc. Lão Cửu Môn chia làm ba loại gồm có Thượng Tam Môn, Bình Tam Môn và Hạ Tam Môn. Trong đó, Trương Khởi Sơn (Trần Vỹ Đình) là một tướng quân quân đội đã từng là một chuyên gia đạo mộ, đồng thời cũng là người đứng đầu Lão Cửu Môn. &nbsp;Một chiếc xe lửa thần bí dẫn Trương Khải Sơn tới một núi quặng nghi vấn trùng trùng. Để phá giải câu đố về ngọn núi này, Trương Khải Sơn phải nhờ sự giúp đỡ của thế gia khảo cổ Nhị Nguyệt Hồng (Trương Nghệ Hưng), người mà Trương Khải Sơn giúp tìm thuốc giải cứu ái thê Nha Đầu (Viên Băng Nghiên); Trương Khải Sơn cũng tìm được tình yêu với Doãn Tân Nguyệt (Triệu Lệ Dĩnh).</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"William Chan Wai-Ting","avatar":""},{"name":"Zhang Yixing","avatar":""},{"name":"Ying Haoming","avatar":""},{"name":"赵丽颖","avatar":""},{"name":"Hu Yunhao","avatar":""},{"name":"Yuan Bingyan","avatar":""},{"name":"張銘恩","avatar":""},{"name":"Wang Mu Yao","avatar":""},{"name":"Wang Chuang","avatar":""},{"name":"Peng Xiaoran","avatar":""},{"name":"Benson Wang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"