INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-tien-thuong', 'Thợ Săn Tiền Thưởng', 'Bounty Hunters', 'https://phimimg.com/upload/vod/20241004-1/2b2e2f1e63801b7d5afa9f8476ca942a.jpg', 'https://phimimg.com/upload/vod/20241004-1/af68f1353a077367d29a70103cb18fb0.jpg', '<p>Phim Thợ Săn Tiền Thưởng - Bounty Hunter 2016 là câu chuyện đầy tình cờ giữa 5 nhân vật chính diễn ra tại nước Mỹ. Họ bất ngờ quen biết và cùng chung chí hướng trừ gian diệt bạo. Từ những thợ săn tiền thưởng chuyên nghiệp, nhóm 5 thành viên gồm Lý Sơn (Lee Min Ho), A Yo (Chung Hán Lương), Cat (Đường Yên), Swan (Ngô Thiên Ngữ), Tommy (Từ Chính Hy), Bảo Bảo (Phàn Thiếu Hoàng) đã chuyển hướng để hành hiệp trượng nghĩa.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"이민호","avatar":""},{"name":"鍾漢良","avatar":""},{"name":"唐嫣","avatar":""},{"name":"Karena Ng","avatar":""},{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"徐正溪","avatar":""},{"name":"김민교","avatar":""},{"name":"황보라","avatar":""},{"name":"이규호","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shang jin lie ren","賞金獵人","바운티 헌터스","바운티 헌터스: 현상금사냥꾼","赏金猎人"]', 1784690324410);
