INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-hien-dai-phan-8', 'Gia Đình Hiện Đại (Phần 8)', 'Modern Family (Season 8)', 'https://phimimg.com/upload/vod/20241001-1/7e62708b9d2f2cbcd0a77a3c8c5743e1.jpg', 'https://phimimg.com/upload/vod/20241001-1/d2c8687246b58937b8c28cbe9b041e3e.jpg', '<p>Sự vui nhộn trong gia đình vẫn tiếp tục khi gia tộc Dunphy đang chuẩn bị cho cuộc phiêu lưu của Big Apple. Trở về nhà, Claire cố gắng giữ trật tự tại Pritchetts Closets trong khi Phil và Jay cùng nhau kinh doanh. Công việc kinh doanh nước sốt nóng của Gloria bắt đầu phát triển khi Cam và Mitchell đối phó với Lily, cô gái mười hai đang tuổi trưởng thành của họ. Trong khi đó, Manny và Luke loay hoay học năm cuối trung học.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ed O''Neill","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Eric Stonestreet","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Nolan Gould","avatar":""},{"name":"Rico Rodriguez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Familja moderne","Съвременно семейство","Modern Family","Famille Moderne","Famille moderne","Egy rém modern család","משפחה מודרנית","Modernā amerikāņu ģimene","Família Moderna","Американская семейка","عائلة عصرية","Сучасна сім’я","A Modern Farewell"]', 1784690324410);
