INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asura-thanh-pho-toi-ac', 'Asura: Thành Phố Tội Ác', 'Asura: The City of Madness', 'https://phimimg.com/upload/vod/20241001-1/83f236f081ccee4d439e806926fc7f66.jpg', 'https://phimimg.com/upload/vod/20241001-1/35dd0ff324d99d1fb1c806520439bd8b.jpg', '<p>Nội dung phim xoay quanh Han Do-kyung là một thanh tra cảnh sát, nhưng bị ép buộc phải làm những việc mờ ám dưới tay của thị trưởng tha hóa Park. Sau một vụ bịt miệng người chống đối, Han Do-kyung lọt vào tầm ngắm của phía công tố. Công tố viên Kim, thực chất là tay sai của phe đối lập với thị trưởng, liên tục đe dọa để buộc Han phải đưa ra các bằng chứng nhằm buộc tội thị trưởng Park. Mặt khác Park dường như đã tìm được một tay chân thân tín khác, nên muốn loại bỏ Han để bịt đầu mối. Chịu sức ép từ cả hai phía, giờ đây Han Do-kyung phải đánh cược mọi thứ để tìm ra lối thoát khỏi địa ngục tội ác này.</p>', 'Full', 1, 'single', 'completed', 4, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"정우성","avatar":""},{"name":"황정민","avatar":""},{"name":"주지훈","avatar":""},{"name":"곽도원","avatar":""},{"name":"정만식","avatar":""},{"name":"김원해","avatar":""},{"name":"김종수","avatar":""},{"name":"김해곤","avatar":""},{"name":"윤지혜","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"최병모","avatar":""},{"name":"Yoo Jeong-ho","avatar":""},{"name":"Park Hyeok-min","avatar":""},{"name":"현봉식","avatar":""},{"name":"Mi-nam Jeong","avatar":""},{"name":"Cho Joon","avatar":""},{"name":"Jung Hyung-suk","avatar":""},{"name":"Park Yu-mil","avatar":""},{"name":"Jeong Dong-gyoo","avatar":""},{"name":"김수진","avatar":""},{"name":"Kim Hyun-bin","avatar":""},{"name":"박정학","avatar":""},{"name":"윤제문","avatar":""},{"name":"Yoon Dae-yeul","avatar":""},{"name":"Lee Ga-kyung","avatar":""},{"name":"Yum Dong-hu