INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-doan-dan-ba', 'Thủ Đoạn Đàn Bà', 'Lady Macbeth', 'https://phimimg.com/upload/vod/20240928-1/8fe4c962b6f27bf2c9635b344438efd7.jpg', 'https://phimimg.com/upload/vod/20240928-1/9ddb55cee181fc77a400a2f9f34c881d.jpg', '<p>Lady Macbeth ban đầu có dáng dấp của các tác phẩm cổ điển như Madame Bovary hay Anna Karenina, thuật lại số phận hồng nhan bạc phận bởi những cuộc hôn nhân sắp đặt, rồi sau đó ngoại tình và dẫn đến kết cục bi thảm. Thế nhưng màn đánh lừa ngoạn mục của Lady Macbeth đã đưa khán giả đi từ ngạc nhiên này đến kinh ngạc khác.</p>', 'Full', 1, 'single', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Florence Pugh","avatar":""},{"name":"Cosmo Jarvis","avatar":""},{"name":"Paul Hilton","avatar":""},{"name":"Naomi Ackie","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Golda Rosheuvel","avatar":""},{"name":"Anton Palmer","avatar":""},{"name":"Rebecca Manley","avatar":""},{"name":"Fleur Houdijk","avatar":""},{"name":"Cliff Burnett","avatar":""},{"name":"David Kirkbride","avatar":""},{"name":"Bill Fellows","avatar":""},{"name":"Nicholas Lumley","avatar":""},{"name":"Raymond Finn","avatar":""},{"name":"Ian Conningham","avatar":""},{"name":"Finn Burridge","avatar":""},{"name":"Jack Rob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Lady M","레이디 맥베스","Lady Macbeth"]', 1784690324410);
