INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-dau-bep-soma-phan-2', 'Vua Đầu Bếp Soma (Phần 2)', 'Shokugeki No Souma: Ni No Sara', 'https://phimimg.com/upload/vod/20240927-1/896394fe883450df9adb049064b43551.jpg', 'https://phimimg.com/upload/vod/20240927-1/dfb5d59f763c43534b2c610d33236c47.jpg', '<p>Soma Yukihira, phụ giúp tại quán ăn bình dân Yukihira của gia đình, được cha cậu, Joichiro, khuyến khích chuyển đến trường dạy nấu ăn danh tiếng của Nhật Bản Học viện nấu ăn chuyên nghiệp Totsuki. Cậu đã gặp những người có thực lực cùng thế hệ và tiếp tục phát triển bản thân. Cậu đã tham gia vào Cuộc tuyển chọn mùa thu, truyền thống của Totsuki và thua với tỷ số sát sao. Ai là đối thủ tiếp theo đây ...!? Ai sẽ đứng đầu !?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"松岡禎丞","avatar":""},{"name":"茅野愛衣","avatar":""},{"name":"内田真礼","avatar":""},{"name":"赤﨑千夏","avatar":""},{"name":"種田梨沙","avatar":""},{"name":"髙橋ミナミ","avatar":""},{"name":"河西健吾","avatar":""},{"name":"瀬戸麻沙美","avatar":""},{"name":"大西沙織","avatar":""},{"name":"柳田淳一","avatar":""},{"name":"諏訪部順一","avatar":""},{"name":"村田太志","avatar":""},{"name":"小野友樹","avatar":""},{"name":"櫻井孝宏","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Food Wars","Shokugeki no Souma","שוקוגקי נו סומה","Shokugeki no Soma","Shokugeki No Souma","Shokugeki no Sōma","Shokugeki No Souma 2","Shokugeki no Souma: Ni no Sara","Shokugeki No Souma 3","Shokugeki No Souma 5","Shokugeki no Soma 2","Shokugeki no Soma 3","Shokugeki No Souma 4","Shokugeki no Souma: San no Sara - Tootsuki Ressha Hen","Shokugeki no Soma 5","Shokugeki no Souma: San no Sara","Shokugeki no Soma 4","Shokugeki no Souma: Gou no Sara","Shokugeki no Souma: S