INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-ky-la', 'Một Ngày Kỳ Lạ', 'Mood Of The Day', 'https://phimimg.com/upload/vod/20240919-1/eb82b8a69f575d650f3b51d12d11b30e.jpg', 'https://phimimg.com/upload/vod/20240919-1/e96099aa07f7b5263b3859167a817424.jpg', '<p>Phim Một Ngày Kỳ Lạ – Mood Of The Day 2016 nói về Soo Jung (Moon Jae Won) vốn đã có mối tình 10 năm với bạn trai và hiện đang cảm thấy thiếu “lửa” bởi mọi thứ đã quá quen thuộc. Trên chuyến xe lửa đến Busan công tác, cô gặp Jae Hyun (Yoo Yun Suk). Anh chàng vừa gặp gỡ này là người sẵn sàng tán tỉnh cô bằng tất cả những trò tinh quái suốt chuyến hành trình. Trước sự tấn công khó chối từ của người đàn ông xa lạ và lắm chiêu này, cô dần mở lòng. Đây là một phim tình cảm hài, chọc cười khán giả bằng những tình tiết đầy tinh quái.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Moon Chae-won","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Kim Dae-ryung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Keunalui Bonwigi","That Day''s Mood","In The Mood For Love","그 날의 분위기","那天的氛圍","その日の雰囲気：2016","그날의 분위기"]', 1784690324411);
