INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tu-lua-dao', 'Bộ Tứ Lừa Đảo', 'Seondal: The Man Who Sells the River', 'https://phimimg.com/upload/vod/20240917-1/c73197386966907ee86c9f7d953d0e3a.jpg', 'https://phimimg.com/upload/vod/20240917-1/49bad3ef2ba9457b00876b29d73eb008.jpg', '<p>Kim Seon-dal (Yoo Seung-ho thủ vai) – kẻ bịp bợm thông minh và điển trai, để lại tên tuổi của mình tại khắp mọi nơi hắn từng đi qua với những chiêu trò ngày một táo tợn hơn. Tay lừa đảo huyền thoại này vẫn luôn tìm kiếm cho mình một màn trình diễn ngoạn mục nhất mọi thời đại. &nbsp;Với sự hỗ trợ từ bậc thầy cải trang Bowon, bà bói chuyên tống tiền khách hàng Madame Yoon và tên lừa đảo học việc Gyun, Seon-dal dẫn đầu bộ tứ lừa đảo “vi diệu” nhất Joseon. Không thể bỏ qua thứ hàng hóa có giá nhất thời điểm bấy giờ – thuốc lá, bọn chúng khám phá ra rằng, kẻ quyền lực đứng đằng sau những thương vụ thuốc lá chính là Sung Dae-ryun. Quyết tâm cho Sung vào tròng, nhóm lừa đảo bá đạo do Kim Seon-dal dẫn đầu đã… rao bán sông Daedong và biến món tài sản vô chủ này trở nên có giá hơn bao giờ hết!</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"유승호","avatar":""},{"name":"조재현","avatar":""},{"name":"고창석","avatar":""},{"name":"라미란","avatar":""},{"name":"시우민","avatar":""},{"name":"연우진","avatar":""},{"name":"전석호","avatar":""},{"name":"서예지","avatar":""},{"name":"Kim Young-pil","avatar":""},{"name":"You Il-han","avatar":""},{"name":"이준혁","avatar":""},{"name":"최귀화","avatar":""},{"name":"기주봉","avatar":""},{"name":"권태원","avatar":""},{"name":"김종수","avatar":""},{"name":"Kwak Min-seok","avatar":""},{"name":"고인범","avatar":""},{"name":"Seo Chong-ju","avatar":""},{"name":"Oh Youn-hong","avatar":""},{"name":"Joo Young-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kim Sun-dal","Bongyi Kimseondal","Kim Seon-dal","김선달","봉이 김선달","봉이김선달"]', 1784690324411);
