INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-dop-mo', 'Mèo đớp mỡ', 'Tiger, Blood in the Mouth', 'https://phimimg.com/upload/vod/20240913-1/9972424fe2eef0d333f08fc4ccdcac4f.jpg', 'https://phimimg.com/upload/vod/20240913-1/414b40f09a8c78b2ac54cd52323c59b1.jpg', '<p>Ramón Alvia là một võ sĩ chuyên nghiệp, mặc dù đã giành được một số chức vô địch quốc tế nhưng đã già và đang ở giai đoạn cuối của sự nghiệp. Anh ta chống cự. Trong phòng tập thể dục, Ramon phát hiện ra trong số các võ sĩ trẻ Deborah, một cô gái xinh đẹp.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'VIetsub', 'FHD', 'Ý', 0, '[{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Eva De Dominici","avatar":""},{"name":"Erica Bianchi","avatar":""},{"name":"Osmar Núñez","avatar":""},{"name":"Claudio Rissi","avatar":""},{"name":"Benicio Mutti Spinetta","avatar":""},{"name":"Camila Zolezzi","avatar":""},{"name":"Aldo Onofri","avatar":""},{"name":"Richard Wagener","avatar":""},{"name":"Diego Chavez","avatar":""},{"name":"Erica Farías","avatar":""},{"name":"Pablo Paoliello","avatar":""},{"name":"Osvaldo Príncipi","avatar":""},{"name":"Marcelo Pitrola","avatar":""},{"name":"Ana Laura Pérez Pacor","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
