INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-phuong-bac', 'Trận Chiến Phương Bắc', 'The Northlander', 'https://phimimg.com/upload/vod/20231108-1/8d8bde7404dd573ad0514b3e7623dbae.jpg', 'https://phimimg.com/upload/vod/20231108-1/188fd2765efc578971db5066a1748817.jpg', '<p>Năm 2961 cũng là lúc mặt đất đã được phục hồi bởi nhân loại và thiên nhiên. Một thợ săn tên Cygnus được kêu gọi để bảo vệ cho tộc người của mình. Anh đi ngang qua vùng thung lũng sa mạc để bảo vệ bộ tộc mình chống lại nhóm Heretics. Cygnus phải làm thế nào để bộ lạc của mình sống sót?</p>', 'Full', 1, 'single', 'completed', 5, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Corey Sevier","avatar":""},{"name":"Roseanne Supernault","avatar":""},{"name":"Michelle Thrush","avatar":""},{"name":"Nathaniel Arcand","avatar":""},{"name":"Julian Black Antelope","avatar":""},{"name":"Roger LeBlanc","avatar":""},{"name":"Angela White","avatar":""},{"name":"Kevin Davey","avatar":""},{"name":"Cameron Gerlitz","avatar":""},{"name":"Jonathan Purvis","avatar":""},{"name":"Stephane Legault","avatar":""},{"name":"John Barry Graham","avatar":""},{"name":"Sarah Hemphill","avatar":""},{"name":"Emiko Shimozawa","avatar":""},{"name":"Tessa Hatheway","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324411);
