INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-lon-phan-10', 'Vụ Nổ Lớn (Phần 10)', 'The Big Bang Theory (Season 10)', 'https://phimimg.com/upload/vod/20240910-1/d81f905369b3e748af6f963f4bd812ab.jpg', 'https://phimimg.com/upload/vod/20240910-1/bf2c39b832ae0f24a0f1a4e686f93e08.jpg', '<p>Hai nhà vật lý Leonard và Sheldon nhận ra nhóm mọt sách của họ cùng hai người bạn Howard và Raj mở rộng khi Penny, nữ diễn viên chưa thành danh, chuyển vào căn hộ kế bên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Johnny Galecki","avatar":""},{"name":"Jim Parsons","avatar":""},{"name":"Kaley Cuoco","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Melissa Rauch","avatar":""},{"name":"Mayim Bialik","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
