INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muu-sat-tuoi-xuan', 'Mưu Sát Tuổi Xuân', 'Kill Time', 'https://phimimg.com/upload/vod/20231103-1/a95b33f63d3e60a23df5df9e7d54842a.jpg', 'https://phimimg.com/upload/vod/20231103-1/0385ee987413aa242f9debde16f9ccdd.jpg', '<p>Phim Mưu Sát Tuổi Xuân - Kill Time 2016: Chuyển thể từ tiểu thuyết cùng tên, kể về cô gái Điền Tiểu Mạch (Angelababy) sắp cưới vị hôn phu Thịnh Tán (Trương Siêu), nhưng cái chết của cảnh sát Điền (Doãn Chú Thắng) – cha của Tiểu Mạch đã làm vỡ tan niềm hạnh phúc yên bình kia. Khi đang soạn lại các di vật của cha, Điền Tiểu Mạch tình cờ phát hiện ra cuốn sổ tay ghi chép các vụ án của cảnh sát Điền, rồi cứ thế rơi vào vòng xoáy của một vụ án bí ẩn chưa có lời giải từ mười năm trước. Chính vụ án đó cũng đưa cô trở về với những kí ức của mối tình đầu sâu sắc mà cũng đầy đau khổ. Cùng lúc đó, Tiểu Mạch được cô bạn thân Tiền Linh (Nhiệt Y Trát) tiết lộ về một cửa hàng online tên “miền ma nữ”, nơi bạn có thể mua được mọi thứ, thậm chí là cả những kí ức về tình yêu. Nhưng khi cô mua về một chiếc khăn lụa màu tím thần bí, thì hàng loạt các sự việc kì lạ đã xảy ra, mọi thứ dường như đều có liên quan đến vụ án bí ẩn kia và cậu bạn trai thời niên thiếu – Thu Thu (Nguyễn Kinh Thiên).</p>', 'Full', 1, 'single', 'completed', 4, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"AngelaBaby","avatar":""},{"name":"Ethan Juan","avatar":""},{"name":"Zhang Chao","avatar":""},{"name":"Rayza","avatar":""},{"name":"Hao Lei","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Pan Hong","avatar":""},{"name":"Song Ningfeng","avatar":""},{"name":"Kou Zhenhai","avatar":""},{"name":"Yin Zhusheng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
