INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguon-goc-dai-chien', 'Nguồn Gốc Đại Chiến', 'Science Fiction Volume One: The Osiris Child', 'nguồn gốc đại chiến science fiction volume one: the osiris child kellan lutz daniel macpherson isabel lucas luke ford rachel griffiths temuera morrison bren foster luke hemsworth zoe carides zoe ventoura louise dodge dwaine stevenson teagan croft grace huang firass dirani harry pavlidis paul winchester ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-than-trieu-tu-long', 'Võ Thần Triệu Tử Long', 'Chinese Hero Zhao Zi Long', 'https://phimimg.com/upload/vod/20240909-1/4874e5867e42a172951e99d68caffa0e.jpg', 'https://phimimg.com/upload/vod/20240909-1/6b7d6974da04c56c0d289bdc36cfdf11.jpg', '<p>Cuối thời Đông Hán, những hoàng đế cuối cùng quá sủng ái hoạn quan mà gạt bỏ bề tôi trung trực. Triều đình ngày càng thối nát, kinh tế suy sụp, an ninh bất ổn. Hạn hán năm 184 càng khiến nhân dân lầm than, khổ cực. Trương Giác lãnh đạo nhân dân nổi dậy chống triều đình trong suốt gần 20 năm. Trong triều, thế lực của Đổng Trác ngày một bành trướng và thao túng cả triều đình.

Triệu Vân giỏi võ nghệ và có tài thao lược, cùng quân tình nguyện gia nhập quân của Công Tôn Toản chinh chiến dẹp quân Khăn Vàng của Trương Giác. Sau, dưới trướng Công Tôn Toản, Triệu Vân kết giao với Lưu Bị và ngày càng trở nên thân thiết. Giữa lúc Công Tôn Toản và Viên Thiệu giao tranh ác liệt, anh cả của Triệu Vân qua đời, Triệu Vân cáo từ Công Tôn Toản về quê để tang anh. Về sau, Triệu Vân tìm Lưu Bị tại Nghiệp Thành và theo phò tá từ đó.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 9, 2016, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Canh Tân","avatar":""},{"name":"Yoona","avatar":""},{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Đỗ Thuần","avatar":""},{"name":"Trâu Triệu Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324411);
