INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gong-shim-dang-yeu', 'Gong Shim Đáng Yêu', 'Beautiful Gong Shim', 'https://phimimg.com/upload/vod/20240908-1/1af38af0e6404c69bad90c39b4d8adec.jpg', 'https://phimimg.com/upload/vod/20240908-1/eb3df53ed12c5a15e7daa5fdcbe0fcde.jpg', '<p>Gong Shim Đáng yêu kể về câu chuyện tình yêu của 2 chị em gái và 2 người đàn ông. Cô em Gong Shim (Kwon Min Ah), là một cô gái có trái tim ấm áp, nhưng luôn phải sống dưới bóng của cô chị gái Gong Mi (Seo Hyo Rim) xinh đẹp, thông minh.

Trong khi đó, Ahn Dan Tae (Nam Goong Min) là 1 người đàn ông sống trong 1 căn hộ trên tầng thượng, mang đẳng cấp của 1 chiến binh phong trần. Thì Suk Joon Soo (Oh Joo Wan), xuất thân là người thừa kết 1 tập đoàn tài phiệt. 2 người đàn ông khác nhau về mọi mặt nhưng lại có mối quan tâm với cùng một cô gái, chính là Gong Shim.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"남궁민","avatar":""},{"name":"방민아","avatar":""},{"name":"온주완","avatar":""},{"name":"서효림","avatar":""},{"name":"오현경","avatar":""},{"name":"우현","avatar":""},{"name":"Jeong Hye-seon","avatar":""},{"name":"견미리","avatar":""},{"name":"김일우","avatar":""},{"name":"김병옥","avatar":""},{"name":"방은희","avatar":""},{"name":"선우용녀","avatar":""},{"name":"Jo Yeon-ho","avatar":""},{"name":"Shin Soo-Ho","avatar":""},{"name":"Choi Hong-il","avatar":""},{"name":"Kim Byeong-se","avatar":""},{"name":"Geum Bo","avatar":""},{"name":"Ahn Su-bin","avatar":""},{"name":"Go Mi-young","avatar":""},{"name":"이채경","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
