INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gong-shim-dang-yeu', 'Gong Shim Đáng Yêu', 'Beautiful Gong Shim', 'gong shim đáng yêu beautiful gong shim 남궁민 방민아 온주완 서효림 오현경 우현 jeong hye-seon 견미리 김일우 김병옥 방은희 선우용녀 jo yeon-ho shin soo-ho choi hong-il kim byeong-se geum bo ahn su-bin go mi-young 이채경 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-hoa-anh-trang', 'Mây Họa Ánh Trăng', 'Love in the Moonlight', 'https://phimimg.com/upload/vod/20240903-1/3043d29e1e3efa804f0141a91b884bf5.jpg', 'https://phimimg.com/upload/vod/20240903-1/e644e03e0e3cff264fba4e0ef1e17736.jpg', '<p>Một lần vì bức thư tình viết giúp cho khách hàng mà khiến cho cô gái trẻ không thân phận này gặp được Thế tử Hyomyeong .Nhưng hai người hiển nhiên không biết về thân phận thực sự của nhau,thế tử vẫn tưởng cô là đàn ông còn cô vẫn nghĩ thế tử là một khách hàng bình thường.Nhưng rắc rối ập đến khi thế tử Hyomyeong bắt đầu quan tâm cô và các hoạn quan trong triều đình nhận ra điều đó.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 9, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"박보검","avatar":""},{"name":"김유정","avatar":""},{"name":"정진영","avatar":""},{"name":"채수빈","avatar":""},{"name":"곽동연","avatar":""},{"name":"김승수","avatar":""},{"name":"전미선","avatar":""},{"name":"Heo Jung-eun","avatar":""},{"name":"정유민","avatar":""},{"name":"천호진","avatar":""},{"name":"정혜성","avatar":""},{"name":"장광","avatar":""},{"name":"최대철","avatar":""},{"name":"태항호","avatar":""},{"name":"오의식","avatar":""},{"name":"안세하","avatar":""},{"name":"조희봉","avatar":""},{"name":"박철민","avatar":""},{"name":"이문식","avatar":""},{"name":"이준혁","avatar":""},{"name":"한수연","avatar":""},{"name":"강기둥","avatar":""},{"name":"방중현","avatar":""},{"name":"안내상","avatar":""},{"name":"이대연","avatar":""},{"name":"Lee Kyu-sub","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681