INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('may-hoa-anh-trang', 'Mây Họa Ánh Trăng', 'Love in the Moonlight', 'mây họa ánh trăng love in the moonlight 박보검 김유정 정진영 채수빈 곽동연 김승수 전미선 heo jung-eun 정유민 천호진 정혜성 장광 최대철 태항호 오의식 안세하 조희봉 박철민 이문식 이준혁 한수연 강기둥 방중현 안내상 이대연 lee kyu-sub ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-vo-doi-dau-chang-re', 'Bố Vợ Đối Đầu Chàng Rể', 'Why Him?', 'https://phimimg.com/upload/vod/20231211-1/98172e1f5ca58bd6d0a6b11ff7584e11.jpg', 'https://phimimg.com/upload/vod/20231211-1/7dd1d362f0e01997d60431e71bd64666.jpg', '<p>Phim Bố Vợ Đối Đầu Chàng Rể - Why Him? 2016: xoay quanh ông Ned do Bryan Cranston thủ vai, một người đàn ông bảo thủ nhưng lại cực kỳ yêu thương gia đình. Trong kỳ nghỉ lễ, ông và gia đình đến thăm cô con gái của mình tại trường đại học, tại đây ông gặp người bạn trai của cô chính là anh chàng Laird do James Franco thủ vai, người bạn trai đại gia của con gái ông. Cậu thanh niên Laird lại mang tính cách hoàn toàn trái ngược với Ned, xuề xòa, không có bất kỳ một nguyên tắc và cũng không theo một khuôn khổ nào. Từ đó, cơn ác mộng bắt đầu đến với ông, những cuộc “chiến tranh” nảy lửa bắt đầu tàn phá cuộc sống của gia đình ông. Lần đầu gặp chàng rể tương lai, cả nhà đã một phen hú hồn khi được bạn trai của con gái đón tiếp theo cách “tự nhiên như ruồi” khó đỡ với mình trần, quần ngố, thân hình xăm trổ và đặc biệt là màn văng tục thuần thục như cơm bữa. Những tưởng là một kẻ đầu đường xó chợ, ất ơ, vớ vẩn nhưng khi tìm hiểu, ông bố choáng váng khi biết chàng trai trong mộng của con gái là một tỷ phú thứ thiệt trên internet với hàng tỷ kết quả hiển thị mỗi khi gõ tên trên Google.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Zoey Deutch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
