INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-di-roi-tinh', 'Chạy Đi Rồi Tính', 'Lost In Saigon', 'https://phimimg.com/upload/vod/20231102-1/aad75221e3bf1905886101f97b65ec6c.jpg', 'https://phimimg.com/upload/vod/20231102-1/0697b07dc2faf75157b0daab64472f5a.jpg', '<p>Phương Trinh là một ca sĩ phòng trà hạng hai, cố gắng mãi chưa được nổi tiếng. Cô sống cùng người chồng bán sữa đậu nành và cậu con trai Subin sắp lên cấp 2. Trong một lần tình cờ, Subin thu được nhân dạng của băng cướp Xà-Nel khét tiếng, khiến cho cả nhà gặp nguy hiểm. Dưới sự giúp đỡ của nữ đặc vụ Lệ Tuyền, gia đình Phương Trinh phải vất vả chạy trốn sự truy đuổi của băng cướp Chanel. Ngoài ra, một bộ đôi vệ sĩ hài hước bí ẩn cũng luôn theo dấu gia đình họ.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Diễm My 9x","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Trọng Khang","avatar":""},{"name":"Nam Thư","avatar":""},{"name":"Puka","avatar":""},{"name":"Diệu Nhi","avatar":""},{"name":"Duy Khánh Zhou Zhou","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
