INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chang-nghe-si-dom', 'Những Chàng Nghệ Sĩ Dỏm', 'The Boys Who Cried Wolf', 'https://phimimg.com/upload/vod/20231101-1/2673987c0755b78f47e4fbe1118485e4.jpg', 'https://phimimg.com/upload/vod/20231101-1/8e78f768cbfce7dde11e303f5fcf73bd.jpg', '<p>Bộ phim Những Chàng Nghệ Sĩ Dỏm -The Boys Who Cried Wolf kể về một chàng trai tên Wanju. Mong ước trở thành diễn viên nhưng dòng đời xô đẩy anh trở thành diễn viên đóng thế - giả làm bạn trai, hàng xóm hay bất cứ vai nào được yêu cầu. Một ngày nọ, có một người phụ nữ yêu cầu Wanju làm nhân chứng giả cho vụ án con trai cô ta bị giết. Wanju có linh cảm vụ này phải mạo hiểm lớn nhưng khi cô ta khóc và cầu xin anh hãy giúp đưa tên nghi phạm vào tù thì Wanju đã đồng ý. Sau khi Wanju hoàn thành nhiệm vụ, anh phát hiện ra nạn nhân là một đứa trẻ mồ côi. Vậy thân phận thật sự của người khách đến tìm anh là gì?</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Jong-hwan","avatar":""},{"name":"Kim Yae-eun","avatar":""},{"name":"Lee Ga-sub","avatar":""},{"name":"Cha Rae-hyung","avatar":""},{"name":"Oh Chang-kyung","avatar":""},{"name":"Ryu Jun-yeol","avatar":""},{"name":"Ha Jun","avatar":""},{"name":"Jeon Kwang-jin","avatar":""},{"name":"Lee Se-ho","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324411);
