INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nam-thang-xua', 'Những Năm Tháng Xưa', 'Back in the Day', 'https://phimimg.com/upload/vod/20231101-1/097d42d78e1661c835f48673e009e4b6.jpg', 'https://phimimg.com/upload/vod/20231101-1/e6fa5f5e19a96253401dd595023a7814.jpg', '<p>Bộ phim Những Năm Tháng Xưa - Back In The Day kể về hành trình vươn lên đỉnh vinh quang của một tay đấm bốc trẻ. Khi mẹ cậu qua đời và bố cậu bỏ trốn do nghiện rượu nặng, cậu đành phải về dưới trướng một ông trùm và cố gắng từng ngày để trở thành tay đấm bốc nổi tiếng.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alec Baldwin","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Shannen Doherty","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Annabella Sciorra","avatar":""},{"name":"Joseph D''Onofrio","avatar":""},{"name":"Louis Lombardi","avatar":""},{"name":"Manny Pérez","avatar":""},{"name":"Paul Borghese","avatar":""},{"name":"Patricia Stark","avatar":""},{"name":"Jimmy Palumbo","avatar":""},{"name":"Maria May","avatar":""},{"name":"Morgan Hammel","avatar":""},{"name":"Regina Hardy","avatar":""},{"name":"Roy Jones Jr.","avatar":""},{"name":"Shirville Jarvis","avatar":""},{"name":"LoDe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
