INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-bao-thu', 'Chiến Binh Báo Thù', 'Fight Valley', 'https://phimimg.com/upload/vod/20231101-1/bc20d1b400578f1ced39c18c53914cc5.jpg', 'https://phimimg.com/upload/vod/20231101-1/7bfdabf38bafc7ca8023da72a0c7ab6b.jpg', '<p>Phim Chiến Binh Báo Thù - Fight Valley 2016: Một người phụ nữ trẻ bị phát hiện chết sau khi dính líu đến tổ chức đấu võ ngầm. Chị gái của cô gái xấu số - Windsor bắt đầu tập luyện dưới sự dẫn dắt của cựu võ sĩ được kính trọng để tìm ra kẻ đã giết em gái mình.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Susie Celek","avatar":""},{"name":"Erin O''Brien","avatar":""},{"name":"Miesha Tate","avatar":""},{"name":"Chelsea Durkalec","avatar":""},{"name":"Cabrina Collesides","avatar":""},{"name":"Holly Holm","avatar":""},{"name":"Cristiane Justino","avatar":""},{"name":"Kari J. Kramer","avatar":""},{"name":"Jefferson Sanders","avatar":""},{"name":"Ivy Lashawn Coleman","avatar":""},{"name":"Salvatore Franciosa","avatar":""},{"name":"Bonnie Bruderer","avatar":""},{"name":"Alexandria Williams","avatar":""},{"name":"Steve Downing","avatar":""},{"name":"Ariel Grama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
