INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-binh-bao-thu', 'Chiến Binh Báo Thù', 'Fight Valley', 'chiến binh báo thù fight valley susie celek erin o''brien miesha tate chelsea durkalec cabrina collesides holly holm cristiane justino kari j. kramer jefferson sanders ivy lashawn coleman salvatore franciosa bonnie bruderer alexandria williams steve downing ariel grama ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-huyet-chien', 'Đại Huyết Chiến', 'My War', 'https://phimimg.com/upload/vod/20231101-1/4e90e98651ac74305e1a35e7a28f2a69.jpg', 'https://phimimg.com/upload/vod/20231101-1/b1f029ce21faea2b94059879c7bc7714.jpg', '<p>Phim Đại Huyết Chiến - My War 2016: Vào ngày 25 tháng 7 năm 1950, nội chiến Triều Tiên bùng nổ vì bất đồng trong việc thống nhất đất nước. Để bảo vệ lợi ích của mình ở châu Á Hoa Kỳ quyết định can thiệp quân sự vào cuộc nội chiến. Cưỡng ép Hội đồng bảo an Liên Hiệp Quốc thành lập một “lực lượng Liên Hiệp Quốc” mình lãnh đạo, Hoa Kỳ xâm lược Triều Tiên, trong khi Hạm đội 7 của họ tiến vào eo biển Đài Loan, nhằm cản trở quá trình thống nhất đất nước của Trung Quốc. Ngày 8 tháng 10, đáp lại lời đề nghị của chính quyền Nam Triều Tiên, Trung Quốc đã đưa ra một quyết định chiến lược nhằm “đáp trả sự gây hấn của Hoa Kỳ và viện trợ Triều Tiên, để bảo vệ mẫu quốc” và nhanh chóng tập hợp Lực Lượng Quân Tình Nguyện để tham chiến.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Ye","avatar":""},{"name":"Wang Luodan","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Ye Qing","avatar":""},{"name":"Huang Zhizhong","avatar":""},{"name":"Lin Yanrou","avatar":""},{"name":"Ma Hui","avatar":""},{"name":"Wang Longhua","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324411);
