INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-nao-ma-kia', 'Chiến Nào, Ma Kia!', 'Bring It On, Ghost', 'https://phimimg.com/upload/vod/20240302-1/01d5ee97e15085bbfe1a72f7481e921f.jpg', 'https://phimimg.com/upload/vod/20240302-1/edd1dfcc601e225e425f3114ad327500.jpg', '<p>Cải biên từ bộ tiểu thuyết cùng tên, nội dung kể về cuộc sống chung dưới một mái nhà của Park Bongpal (Ok Taekyeon) và ma nữ Kim Hyeonji (Kim Sohyeon), nội dung câu truyện kết hợp giữa yếu tố kinh dị, lãng mạn và hài hước</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim So Hyun","avatar":""},{"name":"Ok Taec-yeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
