INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bat-diet', 'Tình Yêu Bất Diệt', 'She Is Nak', 'https://phimimg.com/upload/vod/20240831-1/95fe385ed60fe83c290df92ae4a245bf.jpg', 'https://phimimg.com/upload/vod/20240831-1/3c4d72d469d7632e6799f41ab1bc59fb.jpg', '<p>Tình Yêu Bất Diệt - She is Nak, câu chuyện kể về một phụ nữ trẻ xinh đẹp tên là Nak, sống bên bờ kênh Phra Khanong, và tình yêu bất diệt của cô dành cho chồng mình, Mak. Khi Nak đang mang thai, Mak phải nhập ngũ và bị đưa ra chiến trường, ở đó anh bị thương nặng. Trong khi anh đang được chăm sóc sức khỏe trở lại, cả hai mẹ con Nak đã chết vì sinh khó. Tuy nhiên, khi Mak trở về nhà, anh thấy vợ và đứa con yêu của mình đang đợi anh, nhưng anh không biết họ là ma mặc dù bạn bè và dân làng luôn cố nói điều đó với anh cho đến khi Mak tận mắt chứng kiến cảnh Nak duỗi cánh tay dài ngoằng nhặt trái chanh rớt dưới gầm sàn nhà. Mak bỏ trốn làm cho Nak nổi cơn thịnh nộ, dân làng bị Nak ám đến khiếp sợ. Nak bị trấn một thời gian và rồi được giải thoát, sau cùng linh hồn cô được đưa về chốn bình yên. Tình yêu của Nak dành cho chồng ngay cả khi chết vẫn không thể chia cắt được.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 6, 2016, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Bitoey R-Siam","avatar":""},{"name":"Bitoey R-SiamSun Prachakorn Piyasakulkaew","avatar":""},{"name":"Pitisak Yaowananon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
