INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-hoan-hao', 'Quý Ông Hoàn Hảo', 'Better Man', 'https://phimimg.com/upload/vod/20240831-1/ef1bb92c55071a04faf84c84b6b246da.jpg', 'https://phimimg.com/upload/vod/20240831-1/6dddf645e849082bd13c8bc30ac7a536.jpg', '<p>Anh em nhà họ Dương có tất cả - ngoại hình, trí tuệ và gia cảnh nhưng đều trốn tránh chuyện tình cảm. Anh cả Dương Chấn Vĩ là người nghiện công việc, tâm trí chỉ có mở rộng kinh doanh. Anh thứ Dương Chấn Hạo làm việc trong ngành giải trí và là một huấn luyện viên thể hình. Em út Dương Chấn Khải là ngườitỉ mỉ được giao vị trí CEO của đế chế gia đình. Ba anh em sẽ xử lý cảm xúc của họ như thế nào khi mỗi người gặp một người phụ nữ làm đảo lộn thế giới hoàn hảo của họ?</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 7, 2016, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Yo-Wei","avatar":""},{"name":"Tender Huang","avatar":""},{"name":"言明澔","avatar":""},{"name":"Shara Lin","avatar":""},{"name":"Hope Lin","avatar":""},{"name":"連俞涵","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324411);
