INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-the-gioi', 'Đại Thế Giới', 'War And Peace', 'https://phimimg.com/upload/vod/20240828-1/ec9ca7aead2bde8ae2ab0681e128c643.jpg', 'https://phimimg.com/upload/vod/20240828-1/cdb1528ce8800d763e16ce78e45eb55a.jpg', '<p>Đại Thế Giới - War And Peace xoay quanh bối cảnh những năm đầu thế kỷ 20, ngoại xâm tấn công vào Thượng Hải. Chiến tranh xảy ra khiến bách tính sống trong cơn hoạn nạn, người thân ly tán. Tần Hiếu Thiên và người yêu Hoàng Oanh Âm bị địch mai phục trên chiến trường. Vì cứu người yêu nên Hiếu Thiên bị trọng thương và mất trí. 15 năm sau, Hiếu Thiên bí mật trở về Thượng Hải, đổi tên thành Giang Hành Viễn, bề ngoài điều tra chân tướng cái chết của cha mẹ mình nhưng thực tế là điều tra âm mưu muốn thôn tính thế giới của giặc ngoại xâm. Tại đây, Hiếu Thiên đã gặp lại Hoàng Oanh Âm nhưng anh kiên quyết từ chối thân phận thật của mình.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"喬振宇","avatar":""},{"name":"Li Man","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Zheng Xiaoning","avatar":""},{"name":"Aliyah","avatar":""},{"name":"岳跃利","avatar":""},{"name":"Lu Zizhen","avatar":""},{"name":"Benson Wang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
