INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat-2-phim-truong', 'Lật Mặt 2: Phim Trường', 'Face Off 2: The Studio', 'https://phimimg.com/upload/vod/20240827-1/4bba1c118945b0dcb744e9cbdabb4b4f.jpg', 'https://phimimg.com/upload/vod/20240827-1/5e2e8021cf3f51bdc47567c861b6f268.jpg', '<p><span style="color: rgb(34, 34, 34); font-family: ">Phim xoay quanh hành trình bất đắc dĩ của Trung (Lý Hải) một cascadeur chuyên nghiệp. Vì nghĩa khí nên anh nhận một nhiệm vụ nguy hiểm để kiếm tiền giúp đạo diễn Thuần đang quay dở phim thì bị nhà đầu tư xù vốn. Hỗ trợ Trung là Thành (Hứa Minh Đạt) - cậu em trai thiếu việc làm nhưng thừa hài hước và khôn lỏi. Chưa hoàn thành công việc, Trung và Thành đã phát hiện mình bị chơi xỏ và bọn anh đang vận chuyển hàng quốc cấm.</span></p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lý Hải","avatar":""},{"name":"Hiếu Nguyễn","avatar":""},{"name":"Hoàng Sơn","avatar":""},{"name":"Mai Huỳnh","avatar":""},{"name":"Phi Phung","avatar":""},{"name":"Võ Đình Hiếu","avatar":""},{"name":"Khả Ngân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324411);
