INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-trai-dat-2', 'Hành Tinh Trái Đất 2', 'Planet Earth II', 'https://phimimg.com/upload/vod/20240820-1/099b4687f5d0c2bdfb85d03077888938.jpg', 'https://phimimg.com/upload/vod/20240820-1/4572b197a3e22019e11861f960bc92d7.jpg', '<p>Trải nghiệm thế giới từ góc nhìn của chính động vật. Từ những cảnh tượng kỳ diệu của động vật hoang dã đến những cuộc chạm trán bất ngờ, Hành Tinh Trái Đất 2 mang đến cho bạn trải nghiệm gần gũi hơn bao giờ hết.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324411);
