INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-20-con-ac-mong-den-toi', 'Thám Tử Lừng Danh Conan 20: Cơn Ác Mộng Đen Tối', 'Detective Conan: The Darkest Nightmare', 'https://phimimg.com/upload/vod/20231019-1/30585e5ac070744b7e9dc8c39406d651.jpg', 'https://phimimg.com/upload/vod/20231019-1/7f132171cea926cd16ab52a212b01257.jpg', '<p>Phim Thám Tử Lừng Danh Conan 20: Cơn Ác Mộng Đen Tối - Detective Conan Movie 20: The Darkest Nightmare 2016: Những vụ ám sát bí ẩn xảy ra khắp thế giới. Kẻ tình nghi là một điệp viên có thể truy cập những tài liệu tuyệt mật. Ở Nhật Bản, một điệp viên đột nhập vào trụ sở cảnh sát và truy cập vào những tài liệu mật liên quan đến các cơ sở của điệp viên trong tổ chức Áo Đen đến từ rất nhiều cơ quan tình báo. Bị phát hiện trước khi đánh cắp các tài liệu mật, tên điệp viên bị Rei Furuya phát hiện và trốn thoát. Biệt đội thám tử của Conan nhập cuộc điều tra vụ án liên quan đến Tổ Chức Áo đen.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2016, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Yuki Amami","avatar":""},{"name":"Yukitoshi Hori","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Miyuki Ichijou","avatar":""},{"name":"Shuichi Ike","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324411);
