INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-due-mat-troi', 'Hậu Duệ Mặt Trời', 'Descendants Of The Sun', 'https://phimimg.com/upload/vod/20240814-1/7bb4992625e35a10b3d5cef173fe2509.jpg', 'https://phimimg.com/upload/vod/20240814-1/babd321c8a7bedc86b09fead89459ed8.jpg', '<p>Phim xoay quanh hai nhân vật Yoo Shi Jin và Kang Mo Yeon. Yoo Shi Jin là đội trưởng lực lượng gìn giữ hòa bình của Liên Hợp Quốc. Trong khi đó, Kang Mo Yeon là thành viên của tổ chức Bác sĩ không biên giới. Thời gian đầu gặp gỡ và hợp tác, Shi Jin và Mo Yeon thường xuyên xảy ra xung đột. Tuy nhiên về sau, mối quan hệ giữa họ dần được cải thiện. Trải qua nhiều lần xông pha vào chốn hiểm nguy, cả hai đã nhận ra tình cảm dành cho nhau</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"송중기","avatar":""},{"name":"송혜교","avatar":""},{"name":"김지원","avatar":""},{"name":"진구","avatar":""},{"name":"온유","avatar":""},{"name":"강신일","avatar":""},{"name":"Cho Tae-kwan","avatar":""},{"name":"조재윤","avatar":""},{"name":"Hyun Jyu-ni","avatar":""},{"name":"Jeon Soo-jin","avatar":""},{"name":"이승준","avatar":""},{"name":"김민석","avatar":""},{"name":"안보현","avatar":""},{"name":"David Lee McInnis","avatar":""},{"name":"이이경","avatar":""},{"name":"김병철","avatar":""},{"name":"박환희","avatar":""},{"name":"Elena Zhernovaya","avatar":""},{"name":"Jo Woo-ri","avatar":""},{"name":"태인호","avatar":""},{"name":"서정연","avatar":""},{"name":"박훈","avatar":""},{"name":"Choi Woong","avatar":""},{"name":"Shin Dong-hoon","avatar":""},{"name":"Kim Hyo Myung","avatar":""},{"name":"Ariane Desgagnés-Leclerc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5