INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-vi-khach-kho-chieu-phan-1', 'Những Vị Khách Khó Chiều (Phần 1)', 'High Maintenance (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/9f4e891592c1efac394c2dc02fc95d05.jpg', 'https://phimimg.com/upload/vod/20240808-1/601e92d2588a5687c93562a832d58157.jpg', '<p>Hãy cùng khám phá thói quen hàng ngày của một nhóm người New York đa dạng và cách họ thắp sáng mọi thứ. &quot;The Guy&quot; là một người giao cần sa vô danh có nhóm khách hàng bao gồm một nhóm nhân vật lập dị với chứng loạn thần kinh đa dạng như thành phố này.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Sinclair","avatar":""},{"name":"Katja Blichfeld","avatar":""},{"name":"Katja Blichfeld","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324411);
