INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ham-cuoi-cung-phan-3', 'Chiến Hạm Cuối Cùng (Phần 3)', 'The Last Ship (Season 3)', 'https://phimimg.com/upload/vod/20240118-1/96ad114914b812c9f5f22fb2b3847597.jpg', 'https://phimimg.com/upload/vod/20240118-1/cd286ca787da32f79f16a7b435e62a3b.jpg', '<p>Thủy thủ đoàn của Nathan James đang chuyển sự chú ý của họ sang châu Á sau khi Tổng thống Michener nghe tin đồn rằng nhà lãnh đạo Trung Quốc đang tích trữ thuốc chữa bệnh Scott thay vì phân phát cho người dân trong khu vực. Michener cử Chandler đến một hội nghị thượng đỉnh toàn cầu để điều tra cáo buộc này, cũng như tin đồn về khả năng đột biến của loại vi rút ban đầu đã gây ra đợt bùng phát mới ở Nhật Bản.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 4, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Dane","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Travis Van Winkle","avatar":""},{"name":"Christina Elmore","avatar":""},{"name":"Jocko Sims","avatar":""},{"name":"Kevin Michael Martin","avatar":""},{"name":"Michael Curran-Dorsano","avatar":""},{"name":"Jodie Turner-Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
