INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-k2', 'Mật Danh K2', 'The K2', 'https://phimimg.com/upload/vod/20240805-1/58d2558a63556294061743f4de3b7aed.jpg', 'https://phimimg.com/upload/vod/20240805-1/603f1f1db32ba3db8c6cf0b1bc287d6e.jpg', '<p>The K2 xoay quanh câu chuyện của Kim Je Ha, còn được gọi là K2, một người lính yêu nước bị chính Tổ quốc và đồng nghiệp phản bội. Giờ đây, anh ta được thuê làm vệ sĩ riêng cho Choi Yoo Jin, vợ của ứng cử viên Tổng thống đồng thời là ái nữ của một gia đình tài phiệt. Go Ahn Na, cô con gái riêng của vị ứng cử viên Tổng thống. Những tổn thương thời thơ ấu khiến Go Ahn Na trở nên cô lập và ít giao tiếp với thế giới. Đối với cô, tình yêu chỉ là công cụ để trả thù. Đây là người sẽ khiến trái tim Kim Je Ha phải rung động?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"지창욱","avatar":""},{"name":"송윤아","avatar":""},{"name":"윤아","avatar":""},{"name":"조성하","avatar":""},{"name":"김갑수","avatar":""},{"name":"이정진","avatar":""},{"name":"손태영","avatar":""},{"name":"신동미","avatar":""},{"name":"Park Geon-lak","avatar":""},{"name":"Lee Yea-eun","avatar":""},{"name":"Lee Jae-Woo","avatar":""},{"name":"전배수","avatar":""},{"name":"Song Gyeong-cheol","avatar":""},{"name":"박순천","avatar":""},{"name":"이철민","avatar":""},{"name":"고인범","avatar":""},{"name":"Lee Yoo Joo","avatar":""},{"name":"염혜란","avatar":""},{"name":"주석태","avatar":""},{"name":"김보미","avatar":""},{"name":"이한위","avatar":""},{"name":"조동혁","avatar":""},{"name":"Shin Dong-hoon","avatar":""},{"name":"Jung Ji-young","avatar":""},{"name":"Yoon Jong-hwa","avatar":""},{"name":"Cho Jae-ryong","avatar":""},{"name":"Joey Albright","avatar":""},{"name":"Choi Seung-hoon","avatar":""},{"name":"이순원","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
