INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiet-huyet-tuoi-tre', 'Nhiệt Huyết Tuổi Trẻ', 'Young & Fabulous', 'https://phimimg.com/upload/vod/20240805-1/8e6423b1767e3602fb60536d371f507e.jpg', 'https://phimimg.com/upload/vod/20240805-1/a0d8b304deb920751854978a9e62e94e.jpg', '<p>Câu chuyện về tuổi trưởng thành của một nhóm bạn tuổi teen—Royston, Violet và Hao Ren—những người cố gắng vượt qua mọi thử thách và trở ngại để theo đuổi ước mơ của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Aloysius Pang","avatar":""},{"name":"Joshua Tan","avatar":""},{"name":"Joyce Chu","avatar":""},{"name":"Gurmit Singh","avatar":""},{"name":"Quan Yi Fong","avatar":""},{"name":"Henry Thia","avatar":""},{"name":"Jeffrey Xu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324411);
