INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-cam-tu', 'Biệt Đội Cảm Tử', 'Suicide Squad', 'https://phimimg.com/upload/vod/20231022-1/b443ed1c1cd7579172b3ed8a151d33ba.jpg', 'https://phimimg.com/upload/vod/20231022-1/c2144a79dfafc62d54a7a6a2b0b6095e.jpg', '<p>Suicide Squad xoay quanh nhóm ác nhân mang tên Biệt đội Cảm tử. Đây là tổ chức đánh thuê gồm toàn những kẻ thù của Batman, được chính phủ tập hợp lại để chuyên thực hiện các nhiệm vụ tối mật. Điều gây tò mò nhất cho công chúng về Suicide Squad hẳn là nhân vật Joker.&nbsp; Mọi chuyện bắt đầu từ trò đùa tai quái của Joker, khi hắn gửi tới Harley một lá thư tình rất đẹp chứa trong chiếc hộp đen cùng một con chuột-còn-sống-nhăn trong đó. Và rồi cậu ấy gửi cho Will Smith một băng đạn thật có kèm tâm thư. Hắn còn gửi cho các đồng đội một món quà dưới dạng... một con heo chết, kèm với đó là cuốn băng ghi lại lời của Leto trong hình dạng của Joker: &quot;Mấy người, tôi không thể ở đó cùng các bạn nhưng tôi muốn mấy người biết là tôi cũng đang tập luyện vất vả y như mấy người vậy&quot;.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Will Smith","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Joel Kinnaman","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Cara Delevingne","avatar":""},{"name":"Ike Barinholtz","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Adam Beach","avatar":""},{"name":"Karen Fukuhara","avatar":""},{"name":"Common","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Alex Meraz","avatar":""},{"name":"Corina C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324411);
