INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-truong-sully', 'Cơ Trưởng Sully', 'Sully', 'https://phimimg.com/upload/vod/20231108-1/b7bbde29bd7416ef8a2594b7309afe31.jpg', 'https://phimimg.com/upload/vod/20231108-1/b8c8cf43e78111f1034b8f565b9807f2.jpg', '<p>Bộ phim Cơ Trưởng Sully dựa trên một sự kiện có thật từng gây chấn động lịch sử hàng không Hoa Kì và thế giới hồi năm 2009. Dưới bàn tay đạo diễn của Clint Eastwood, lần đầu tiên, phi vụ giải cứu 155 hành khách trên chuyến bay của hãng hàng không U.S. Airways đáp xuống dòng sông Hudson dưới sự điều khiển của cơ trưởng Chesley “Sully” Sullenberger được tường thuật một cách chi tiết, sống động cùng với những câu chuyện chưa bao giờ kể.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Hanks","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Anna Gunn","avatar":""},{"name":"Autumn Reeser","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Mike O''Malley","avatar":""},{"name":"Jamey Sheridan","avatar":""},{"name":"Jerry Ferrara","avatar":""},{"name":"Molly Hagan","avatar":""},{"name":"Max Adler","avatar":""},{"name":"Sam Huntington","avatar":""},{"name":"Wayne Bastrup","avatar":""},{"name":"Valerie Mahaffey","avatar":""},{"name":"Jeff Kober","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Katie Couric","avatar":""},{"name":"Michael Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
