INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-chi', 'Yên Chi', 'Rookie Agent Rouge', 'https://phimimg.com/upload/vod/20240731-1/6821cdbb5f691ef85bf2881b9fb6d5a5.jpg', 'https://phimimg.com/upload/vod/20240731-1/65cc44cb334ce5ab1af502d8e8c98fe2.jpg', '<p>Yên Chi là con gái của giám đốc ngân hàng Thượng Hải. Một lần tình cờ, vì có được tin tình báo của quân đội Nhật, cô bị hiểu lầm là Hán gian. Để chứng minh sự trong sạch của mình, Yên Chi lẻn vào nhà của người chị em tốt Mạn Na và phát hiện ra chính Phùng Tử Hùng, cha của Mạn Na, mới là Hán gian. Cũng tại đây, cô tình cờ gặp được Chu Vũ Hạo, bạn trai của Mạn Na, vốn là gián điệp của Đảng Cộng Sản được cài vào bên người Tử Hùng. Cuộc gặp gỡ định mệnh này đã mở ra một hướng đi mới trong cuộc đời cả hai.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 6, 2016, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Lục Nghị","avatar":""},{"name":"Đào Hân Nhiên","avatar":""},{"name":"Viên Văn Khang","avatar":""},{"name":"Thạch Triệu Kỳ","avatar":""},{"name":"Lý Mộng Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
