INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-anh-quoc-phan-3', 'Bóng Ma Anh Quốc (Phần 3)', 'Peaky Blinders (Season 3)', 'https://phimimg.com/upload/vod/20240730-1/813dd08de33cc0b05933e01c2f445207.jpg', 'https://phimimg.com/upload/vod/20240730-1/b37769fcc6142d1e116b6486f6b7132b.jpg', '<p>Hiện tại là năm 1924, hai năm sau vụ trường đua ngựa Epsom Derby. Tommy công khai tổ chức đua ngựa và bán xe hơi trong khi bí mật làm việc cho Winston Churchill.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 4, 2016, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Jeffrey Postlethwaite","avatar":""},{"name":"Matthew Postlethwaite","avatar":""},{"name":"Ian Pe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
