INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-cu-ta-kim-bok-joo', 'Cô Nàng Cử Tạ Kim Bok Joo', 'Weightlifting Fairy Kim Bok-joo', 'https://phimimg.com/upload/vod/20240729-1/11ad813cf34331ce3512d48818365704.jpg', 'https://phimimg.com/upload/vod/20240729-1/6591a51e040124b41e87f4c21394d364.jpg', '<p>Kim Bok Joo, một vận động viên cử tạ trẻ tuổi, luôn đấu tranh cho lẽ phải và chống lại sự bất công. Ẩn sau vẻ ngoài lực lưỡng của một vận động viên cử tạ là một Kim Bok Joo với trái tim mỏng manh dễ vỡ, một Kim Bok Joo biết yêu với mối tình đầu đầy ngọt ngào và trong sáng. Đóng cặp cùng Lee Sung Kyung là nam thần Nam Joo Hyuk với vai Jung Joon Hyung, một thiên tài bơi lội, bạn ấu thơ của Kim Bok Joo. Là một chàng trai có tính cách mạnh mẽ và đầy hoài bão, song Jung Joon Hyung lại luôn bị một tai nạn trong quá khứ kìm hãm năng lực.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이성경","avatar":""},{"name":"남주혁","avatar":""},{"name":"경수진","avatar":""},{"name":"이재윤","avatar":""},{"name":"조혜정","avatar":""},{"name":"오의식","avatar":""},{"name":"지일주","avatar":""},{"name":"조수향","avatar":""},{"name":"이주영","avatar":""},{"name":"최무성","avatar":""},{"name":"장영남","avatar":""},{"name":"안길강","avatar":""},{"name":"강기영","avatar":""},{"name":"정인기","avatar":""},{"name":"이정은","avatar":""},{"name":"유다인","avatar":""},{"name":"Kim Ye-joon","avatar":""},{"name":"Cho Mi-nyeo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
