INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-sinh-tu', 'Chuyến Tàu Sinh Tử', 'Train to Busan', 'https://phimimg.com/upload/vod/20230930-1/520782a9ad140133ace2084097dd45be.jpg', 'https://phimimg.com/upload/vod/20230930-1/ce7f187328a4da4b11aa28e628496b4a.jpg', '<p>Chuyến Tàu Sinh Tử lấy bối cảnh đất nước Hàn bị tấn công bởi một loại virus bí ẩn, biến con người thành những xác sống hung hăng, khát máu. Có mặt trên chuyến tàu từ Seoul tới Busan là một người cha cùng con gái, hai vợ chồng chuẩn bị đón đứa con đầu lòng và một số cô cậu học sinh cấp 3. Khi đại dịch xác sống bất ngờ bùng phát, họ không còn cách nào khác ngoài đương đầu với nó để bảo vệ những người thân yêu của mình. Hành trình 453km từ Seoul tới vùng an toàn Busan bỗng trở thành cuộc chiến khốc liệt để sinh tồn...</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gong Yoo","avatar":""},{"name":"Kim Su-an","avatar":""},{"name":"Jung Yu-mi","avatar":""},{"name":"Ma Dong-seok","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"An So-hee","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Ye Soo-jung","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Choi Gwi-hwa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
