INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tau-sinh-tu', 'Chuyến Tàu Sinh Tử', 'Train to Busan', 'chuyến tàu sinh tử train to busan gong yoo kim su-an jung yu-mi ma dong-seok choi woo-shik an so-hee kim eui-sung ye soo-jung park myung-shin choi gwi-hwa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-cong-xuat-cung', 'Công Công Xuất Cung', 'Short End Of The Stick', 'https://phimimg.com/upload/vod/20240719-1/61b21414c0be9c4aac03508fa0344b9e.jpg', 'https://phimimg.com/upload/vod/20240719-1/dc0d32041b9c5a736a2426d6d3d45f5d.jpg', '<p>Lý Thúc Cung, Đan Điền và Tiểu Phụng là ba thái giám bị buộc rời khỏi Tử Cấm Thành. Họ phải che giấu thân phận vì lo sợ người đời khinh bỉ. Trên đường đi họ tình cờ gặp được Thôi Tấn Thăng đang bị tổ chức phản thái giám đánh đập nên đã ra tay tương trợ. Bốn người lưu lạc đến Thâm Trấn xa xôi, vì nóng lòng cứu Tiểu Phụng mà Thúc Cung, Đan Điền, Tấn Thăng cướp bóc nhà họ Kim. Chẳng may họ bị Kim Hương bắt giữ và buộc cả bốn người làm nô tài hầu hạ. Nhiều chuyện &quot;dở khóc dở cười&quot; đã xảy ra tại nhà họ Kim. Các tiểu thư nhà họ Kim đều đem lòng yêu ba chàng thái giám Thúc Cung, Tiểu Phụng và Đan Điền. Trong khi Tấn Thăng không phải là thái giám nhưng không rung động được trái tim của ai ngoại trừ nội gián Huỳnh Liên. Một hôm, Tấn Thăng kinh ngạc phát hiện mình có khả năng là cháu đích tôn của nhà họ Kim. Với sự xúi giục của Huỳnh Liên, Thăng quyết giành lại tài sản thuộc về mình.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2016, 'Lồng Tiếng', 'FullHD', 'Hồng Kông', 0, '[{"name":"黎耀祥","avatar":""},{"name":"Power Chan Kwok-Pong","avatar":""},{"name":"Edwin Siu","avatar":""},{"name":"Raymond Cho Wing-Lim","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Nancy Wu","avatar":""},{"name":"Natalie Tong","avatar":""},{"name":"Rosina Lin","avatar":""},{"name":"Toby Chan","avatar":""},{"name":"Grace Wong","avatar":""},{"name":"Yoyo Chen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324411);
