INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-3', '100 Người Thử Nghiệm (Phần 3)', 'The 100 (Season 3)', 'https://phimimg.com/upload/vod/20240616-1/251e0fa0f4b5f00e5f776a77bb86cd8b.jpg', 'https://phimimg.com/upload/vod/20240616-1/e9a014217644497eedec9c1561586bd7.jpg', '<p>Câu chuyện về 100 tội phạm thiếu niên nổi loạn được cử xuống Trái Đất sẽ tiếp tục với nhiều biến cố mới. Mở đầu bằng việc Bellamy và Kane bất chấp tính mạng để giải cứu Clarke, phần ba sẽ mang đến cho người xem nhiều tình tiết gay cấn và khó đoán.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Marie Avgeropoulos","avatar":""},{"name":"Bob Morley","avatar":""},{"name":"Eliza Taylor","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324411);
