INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-chua-phan-3', 'Bạo Chúa (Phần 3)', 'Tyrant (Season 3)', 'https://phimimg.com/upload/vod/20240612-1/241163803c351ce05106c819cc5400d8.jpg', 'https://phimimg.com/upload/vod/20240612-1/987d56812d17ac69bd935dfad65d683e.jpg', '<p>Câu chuyện về một gia đình người Mỹ khiêm tốn bị cuốn vào hoạt động của một quốc gia Trung Đông đầy hỗn loạn. Bassam Barry Al Fayeed, con trai út của nhà độc tài của một quốc gia bị chiến tranh tàn phá, kết thúc cuộc sống lưu vong 20 năm tự áp đặt để trở về quê hương, cùng với vợ và các con người Mỹ, dự đám cưới của cháu trai. Việc trở về quê hương bất đắc dĩ của Barry dẫn đến một cuộc xung đột kịch tính giữa các nền văn hóa khi anh bị ném trở lại chính trị gia đình và quốc gia thời trẻ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Rayner","avatar":""},{"name":"Jennifer Finnigan","avatar":""},{"name":"Moran Atias","avatar":""},{"name":"Ashraf Barhom","avatar":""},{"name":"Noah Silver","avatar":""},{"name":"Anne Winters","avatar":""},{"name":"Sibylla Deen","avatar":""},{"name":"Waleed Elgadi","avatar":""},{"name":"Caroline Boulton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
