INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-kiep-ran-phan-2', 'Tình Người Kiếp Rắn (Phần 2)', 'Tình Người Kiếp Rắn (Phần 2)', 'https://phimimg.com/upload/vod/20240620-1/60c2999fea065261a3e38e400e30ef02.jpg', 'https://phimimg.com/upload/vod/20240620-1/1adabf61093cac524a9d83391cc884b6.jpg', '<p>Câu chuyện bắt đầu khi nhà tài phiệt En-Đi-Sê-Gô mua lại khu đền thờ thần Shi-Va hơn ngàn năm tuổi để phục vụ cho mục đích kinh doanh.<br/>Biết được dự định của ông ta, nhiều thần sư đã ra sức can ngăn vì họ cho rằng đây là nơi trú ngụ của rất nhiều loài rắn được thần linh ban phước và có thể biến thành người. Tuy nhiên, Sê- Gô vẫn cho người đập phá ngôi đền thiêng để xây dựng một khách sạn sang trọng bật nhất thủ đô.</p>', 'Hoàn Tất (81/81)', 81, 'series', 'completed', 11, 2016, 'Lồng Tiếng', 'HD', 'Ấn Độ', 0, '[{"name":"Mouni Roy","avatar":""},{"name":"Karanvir Bohra","avatar":""},{"name":"Adaa Khan","avatar":""},{"name":"Kinshuk Mahajan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324411);
