INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-giam-kieu-my-phan-4', 'Trại Giam Kiểu Mỹ (Phần 4)', 'Orange Is The New Black (Season 4)', 'https://phimimg.com/upload/vod/20240607-1/ae797b55b6eed065c8b99072a7c01dc9.jpg', 'https://phimimg.com/upload/vod/20240607-1/96c9a48d253d1bb5083431a7114a289f.jpg', '<p>Phim Trại Giam Kiểu Mỹ 4 có nội dung sáng tạo và tình tiết vui nhộn xen lẫn hình sự được chuyển thể từ cuốn hồi ký “Orange Is the New Black: My Year in a Women’s Prison” của Piper Kerman.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Schilling","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Danielle Brooks","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324411);
