INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-hai-dau-kim-thiem', 'Lưu Hải Đấu Kim Thiềm', 'Liu Hai Plays With Gold Toad', 'https://phimimg.com/upload/vod/20240518-1/9ae7d3ad589a2ba935a619210ecaddc5.jpg', 'https://phimimg.com/upload/vod/20240518-1/93f9f9380c5c8e6b22ec9983616c1fd7.jpg', '<p>Lưu Hải Đấu Kim Thiền - Liu Hai Plays With Gold Toad nói về cuộc đời của Lưu Hải, một anh tiều phu hiền lành tốt bụng, hiếu thảo với mẹ, có vị thê tử xinh đẹp Hồ Tú Anh. Khi gặp khó khăn, Lưu Hải không quản hiểm nguy, hết lòng vì mẹ và vợ. Hồ Tú Anh chính là hồ ly Cửu Tiểu Muội biến thành. Cảm phục trước tấm lòng hiếu thảo của Lưu Hải, Cửu Tiểu Muội đã hóa thân thành người để được bên cạnh người mình thương yêu. Kim Thiềm đại vương là con cóc vàng, phép thuật cao cường. Kim Thiềm thầm yêu Cửu Muội nhưng hết lần này đến lần khác bị từ chối. Kim Thiềm ôm hận, tìm mọi cách để chia rẽ Lưu Hải và Cửu Muội. Liệu tình yêu còn nhiều trắc trở của cặp đôi này?</p>', 'Hoàn Tất (64/64)', 64, 'series', 'completed', 8, 2016, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Diệu Văn","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Trần Hạo Dân","avatar":""},{"name":"Mục Đình Đình","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324411);
