INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-2016', 'Ông Trùm', 'Master', 'https://phimimg.com/upload/vod/20240428-1/c0772d94d56482e09e8d6f956a433544.jpg', 'https://phimimg.com/upload/vod/20240428-1/e266c0b9ef168b29ee538d26c7453c4d.jpg', '<p>Master 2016 xoay quanh phi vụ trộm cắp lên tới hàng tỉ đô la của Giám đốc Jin (Lee Byung Hun), một tay lừa đảo khét tiếng, và công cuộc săn lùng tên tội phạm nguy hiểm này của một đội điều tra. Cánh tay phải của Jin, một chuyên gia máy tính, cũng là một nhân vật đóng vai trò quan trọng trong kế hoạch lừa đảo của ông ta.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"Kim Woo-bin","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Jung Won-joong","avatar":""},{"name":"Yoo Yeon-soo","avatar":""},{"name":"Cho Hyun-chul","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Park Jeong-ja","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Song Yo-sep","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Kim Sung-gon","avatar":""},{"name":"Choi Kwang-je","avatar":""},{"name":"Woo Do-hwan","avatar":""},{"name":"Jeong Soo-kyo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324411);
