INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-loi-phan-3', 'Thành Phố Tội Lỗi (Phần 3)', 'Gotham (Season 3)', 'https://phimimg.com/upload/vod/20240302-1/39a479ba3be5e94457b01200403f9d6b.jpg', 'https://phimimg.com/upload/vod/20240302-1/6f5e89ea7f23ed09f1b66809254e1541.jpg', '<p>Jim Gordon không còn là cảnh sát, anh trở thành một thợ săn tiền thưởng đồng thời tìm hiểu về Indian Hill cùng những tên ác nhân được trả tự do khỏi đó. Gotham tiếp tục chìm trong những ngày đen tối với sự trỗi dậy mạnh mẽ hơn bao giờ hết của các ác nhân khét tiếng và hơn nữa là Hội đồng Cú.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Donal Logue","avatar":""},{"name":"David Mazouz","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Erin Richards","avatar":""},{"name":"Cory Michael Smith","avatar":""},{"name":"Ben Mckenzie","avatar":""},{"name":"Robin Lord Taylor","avatar":""},{"name":"Camren Bicondova","avatar":""},{"name":"Drew Powell","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Zabryna Guevara","avatar":""},{"name":"Chris Chalk","avatar":""},{"name":"Jessica Lucas","avatar":""},{"name":"John","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324411);
