INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-hinh-ky-uc', 'Khung Hình Ký Ức', 'Love Songs Love Stories', 'https://phimimg.com/upload/vod/20240302-1/ea07223d589856198eb6ffe1ac4b2476.jpg', 'https://phimimg.com/upload/vod/20240302-1/ab3d0be20bc2b2dbea1b6f1e96c1b9fc.jpg', '<p>Đây là một series gồm nhiều bộ phim ngắn về những câu chuyện tình yêu có thật, Khung Hình Ký Ức là một trong 12 phim cùng series. Phim kể về Namkang có sở thích viết tiểu thuyết từ thời đi học. Shin là một nhiếp ảnh gia và cũng là đàn anh thời đại học của Namkang. Trong một lần, do bất đồng quan điểm nên giữa hai người đã nảy sinh mâu thuẫn và dẫn đến những hiểu lầm không đáng có, khiến Namkang và Shin không gặp lại nhau. Bảy năm sau, Namkang đã là tổng biên tập của tạp chí nổi tiếng Fabulous và đang có một chuyện tình đẹp như mơ với Fam - một doanh nhân thành đạt, Shin lại là nhiếp ảnh gia của tạp chí này. Khi chính mắt chứng kiến cảnh Fam cầu hôn Namkang, liệu Shin có cố gắng để giành lại Namkang hay lựa chọn buông tay để Namkang có được hạnh phúc?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ice Preechaya","avatar":""},{"name":"Toni Rakkaen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
