INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-cao', 'Bị Cáo', 'Defendant', 'https://phimimg.com/upload/vod/20240302-1/d683baa38c205dc4613f33ab6d8860af.jpg', 'https://phimimg.com/upload/vod/20240302-1/73dfecdcc085d3939c404298c0db2c7d.jpg', '<p>Park Jung Woo là một công tố viên ở Văn phòng công Tố Quận. Một ngày nọ anh thức dậy và thấy mình là tội phạm nguy hiểm với tội danh giết vợ và con gái. Bị tạm thời bị mất trí nhớ, Jung Woo không nhớ gì xảy ra với mình. Anh&nbsp;đấu tranh để phục hồi trí nhớ của mình và tìm ra sự thật về kẻ đã giết hại người thân mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Sung","avatar":""},{"name":"Um Ki Joon","avatar":""},{"name":"Kwon Yu Ri","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
