INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-thanh-xuan-ben-nhau', 'Tuổi Thanh Xuân Bên Nhau', 'With You', 'https://phimimg.com/upload/vod/20240229-1/0126e7981fb2451d2f390b105da78498.jpg', 'https://phimimg.com/upload/vod/20240229-1/408da0e75099d0a59c851e594b0ec06b.jpg', '<p>Ai cũng cảm thấy thanh xuân sẽ chẳng bao giờ là vĩnh viễn, mà khi đó chính là lúc đẹp nhất của cuộc đời chúng ta. Lúc này đây tôi và toàn bộ quãng thanh xuân cùng nói lời tạm biệt. Bộ phim được chuyển thể từ cuốn tiểu thuyết về đề tài hoc đường của tác giả Bát Nguyệt Trường An, kể về hai người bạn học sinh bình thường Cảnh Cảnh và Dư Hoài cùng quá trình trưởng thành của mỗi người</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Đàm Tụng Vận","avatar":""},{"name":"Vương Lịch Hâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
