INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('homejack', 'Homejack', 'Homejack', 'https://phimimg.com/upload/vod/20240228-1/91446998bdfbd96fe931b0db3cc50efc.jpg', 'https://phimimg.com/upload/vod/20240228-1/f4bf0f7e083866be74d7435cd1a482a3.jpg', '<p>Một kẻ giết người hàng loạt có biệt danh Jack the Ripper đang sát hại phụ nữ ngay tại nhà riêng của họ. Trong khi giới truyền thông đang đưa tin về những nạn nhân mới nhất của anh ta thì chồng của Tsuko lại đi công tác. Ngay sau khi chồng cô ấy đi vắng, người tình của cô ấy đã đến để quan hệ tình dục nhanh chóng. Sau đó có tiếng gõ cửa...</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sasa Handa","avatar":""},{"name":"Atsushi Tsuda","avatar":""},{"name":"Hirokio Andô","avatar":""},{"name":"Ryô Asagiri","avatar":""},{"name":"Rina Hatsume","avatar":""},{"name":"Mayu Minami","avatar":""},{"name":"Reina Shirogane","avatar":""},{"name":"Hiromi Wakasa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
