INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-diem-giai-mua-dong-vuot-qua-nguong-cua', 'Tiêu Điểm Giải Mùa Đông - Vượt Qua Ngưỡng Cửa', 'Kuroko No Basket Movie 3: Winter Cup - Tobira No Mukou', 'https://phimimg.com/upload/vod/20240228-1/2dcf1064ae0fca80c27a6a90f409966c.jpg', 'https://phimimg.com/upload/vod/20240228-1/92343691df46e7601d5576d2232b5cae.jpg', '<p>Phim thứ ba trong số ba phim tổng hợp của loạt phim Kuroko no Basket. Rakuzan và Shutoku đối đầu trong trận bán kết tại Cúp mùa đông. Mặc dù phải vật lộn với Con mắt Hoàng đế có khả năng nhìn thấu mọi thứ của Akashi, Midorima và Takao vẫn đánh trả bằng những lượt chơi liên tiếp của họ, và cả đội Shutoku đã phản công lại Rakuzan. Tuy nhiên, chẳng bao lâu sau Akashi đã dập tắt mọi hy vọng của họ. Người ta quyết định rằng trận chung kết sẽ diễn ra giữa Seirin và Rakuzan. Kagami ngay lập tức vào Zone ngay khi trận đấu bắt đầu, nhưng đó không phải là đối thủ của Akashi. Đối mặt với sự chênh lệch quá lớn về năng lực so với Rakuzan, Seirin nhiều lần mất hy vọng trong suốt trận đấu. Tuy nhiên, Kuroko không bỏ cuộc và tiếp tục chiến đấu mạnh mẽ chống lại Akashi.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324411);
