INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-diem-giai-mua-dong-anh-duong-va-bong-ro', 'Tiêu Điểm Giải Mùa đông - Ánh Dương Và Bóng Rổ', 'Kuroko No Basket Movie 1: Winter Cup - Kage To Hikari', 'https://phimimg.com/upload/vod/20240228-1/fdbf3a4e25a2c4637a4b161f0944116d.jpg', 'https://phimimg.com/upload/vod/20240228-1/18da11af1bc7fbf427e742925911f1a4.jpg', '<p>Bộ phim đầu tiên trong ba bộ phim tổng hợp của loạt phim Kuroko no Basket. Trận đấu đầu tiên của Seirin vs Touou Gakuen tại Winter Cup. Seirin thề rằng họ sẽ trả thù Liên trường, nhưng tài năng của Aomine thậm chí còn phát triển mạnh mẽ hơn và bước đi mới của Kuroko đã bị nhìn thấu. Sau khi bị ánh sáng cũ Aomine từ chối mọi nỗ lực của mình, Kuroko phải ngồi dự bị và phải đối mặt với sự sỉ nhục. Nhìn thấy người bạn đồng hành của mình như vậy, thứ gì đó gần giống như quái vật đã thức tỉnh trong Kagami và anh thách thức Aomine. Aomine gần như đã mất hết ý thức chiến đấu, cho đến khi anh và Kagami đối đầu với nhau một cách gay gắt khi họ đi vào Zone.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324411);
