INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-riders', 'Long Riders!', 'Rongu Raidasu!', 'https://phimimg.com/upload/vod/20240228-1/4c99d13e1969d97089275db447f9da73.jpg', 'https://phimimg.com/upload/vod/20240228-1/50b65ecf35c6d8bc0801e0a8ece89c90.jpg', '<p>Ami Kurata, một sinh viên đại học năm nhất. Là một người không có năng khiếu gì về thể thao, đột nhiên rơi vào tình yêu sét đánh với một chiếc xe đạp loại có thể gấp gọn lại, sau khi nhìn thấy nó ở phía trước của một nhà ga xe lửa. Được truyền cảm hứng từ tình yêu mới của mình, cô bắt đầu tiết kiệm để mua một chiếc xe đạp và học đi xe đạp.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
