INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-van-chi-pham', 'Tiên Kiếm Vân Chi Phàm', 'Chinese Paladin 5', 'https://phimimg.com/upload/vod/20240228-1/3a672a3f4ff4b6b2c5c7f7b7d78d9ab9.jpg', 'https://phimimg.com/upload/vod/20240228-1/29c7ea0e09c6fc5d911a3711565ab2ae.jpg', '<p>Phim kể về Khương Vân Phàm - một thiếu niên với trái tim nhiệt huyết, kiên trì chính nghĩa. 20 năm trước, cha Khương Vân Phàm bị lập kế vu oan nên phải chịu trấn áp trong cấm động. 20 năm sau, Vân Phàm thân là nghiệt tử của Khương Thế Li, cũng bị các nhà truy sát. Vân Phàm quen biết với Đường Vũ Nhu - cô gái mang chứng bệnh kỳ quái, Tiểu Man - đệ tử Thục Sơn, Long U - Ma giới Dạ xoa tộc. Vượt qua bao khảo nghiệm, Vân Phàm thành công bái nhập làm đệ tử Thục Sơn, chăm chỉ luyện tập, tiến bộ thần tốc. Tuy nhiên do vẫn mặc cảm vì xuất thân của mình, Vân Phàm không dám đáp trả tình cảm của Vũ Nhu.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 13, 2016, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Quân","avatar":""},{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Trịnh Nguyên Sướng","avatar":""},{"name":"Tiểu Thái Kỳ","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Trương Duệ","avatar":""},{"name":"Lưu Nhã Sắt","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324411);
