INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-em-noi-ay', 'Hẹn Em Nơi Ấy', 'At Cafe 6', 'https://phimimg.com/upload/vod/20240228-1/b76ca9d20482a6f13e6e636886b0aeed.jpg', 'https://phimimg.com/upload/vod/20240228-1/7a937887c59c30e39e1f36ec22fc15f7.jpg', '<p>Phim Hẹn Em Nơi Ấy - At Cafe 6 2016: Trong một đêm mưa, sau khi xảy ra tai nạn, cô Lương đã tấp vào 1 quá cà phê gần đó tên là Cafe 6. Chủ quán nhận ra cô Lương lại vừa chia tay với bạn trai mình ở nước ngoài, để san sẻ anh ta kể cho cô nghe về câu chuyện tình yêu, tình bạn hồi thanh xuân của 4 người bạn trẻ.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Bo Hong Lin","avatar":""},{"name":"Dong Zijian","avatar":""},{"name":"Cherry Ngan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
