INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-san-sang', 'Chưa Sẵn Sàng', 'Unwilling', 'https://phimimg.com/upload/vod/20240228-1/fcba6ebee2c1f393bbd87c2872734b3f.jpg', 'https://phimimg.com/upload/vod/20240228-1/720dbd88ec20cd48eb6b36ba8337b20e.jpg', '<p>Sáu thành viên trong gia đình tham dự buổi công bố di chúc của người họ hàng già độc đoán và chuyên chế. Tất cả đều bị sốc khi thay vì bản di chúc mà tất cả bọn họ mong đợi là một chiếc hộp gỗ cổ. Hưỡng dẫn mở chiếc họp rất đơn giản: mỗi người phải chọc ngón tay vào các chốt thép nhô ra khỏi các lỗ gỗ trong hộp để mở nó. Tuy nhiên, mỗi khi máu của họ lần lượt chảy vào trong chiếc hộp, các sự kiện ngày một tồi tệ hơn diễn ra.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dina Meyer","avatar":""},{"name":"Bree Williamson","avatar":""},{"name":"David Lipper","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324411);
