INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dai-yeu-thuong', 'Võ Đài Yêu Thương', 'Sultan', 'https://phimimg.com/upload/vod/20240228-1/1207961f3fa8705d6f38a5a45a35437f.jpg', 'https://phimimg.com/upload/vod/20240228-1/d09a68648127a0380a3c80928841a45a.jpg', '<p>Phim Võ Đài Yêu Thương - Sultan 2016: Một bộ phim hành động tâm lý và lãng mạn, kể về cuộc sống của nhân vật Haryana dựa trên 1 số chi tiết có thật về nhà đô vật, võ thuật Sultan Ali Khan.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Anushka Sharma","avatar":""},{"name":"Randeep Hooda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
