INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-dat-kinh-hoang', 'Động Đất Kinh Hoàng', 'The Earthquake', 'https://phimimg.com/upload/vod/20240228-1/863a579b910ce9f81553a90bc70cca91.jpg', 'https://phimimg.com/upload/vod/20240228-1/2016101fdf1b8a8c34a2e1903cfb05d4.jpg', '<p>Năm 1988 tại Liên Xô, trận động đất kinh hoàng xảy ra vào ngày 7 tháng 12 khiến 25.000 người chết và phá hủy hoàn toàn vùng Tây Bắc Armenia. Konstantin Berezhnoy và Robert Melkonyan đã hợp tác với nhau để cứu hàng ngàn nạn nhân. Bộ phim nói lên sự nỗ lực phi thường của những người giải cứu, ca ngợi tình người quý giá giữa cơn thảm họa, đồng thời là tiếng chuông cảnh tỉnh về những thảm họa thiên nhiên có thể giáng lên con người chính lúc mà người ta mất cảnh giác nhất.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Thuyết Minh', 'HD', 'Nga', 0, '[{"name":"Konstantin Lavronenko","avatar":""},{"name":"Mariya Mironova","avatar":""},{"name":"Artyom Bystrov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324411);
