INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nam-khong-co-cong-viec', 'Một Năm Không Có Công Việc', 'Get A Job', 'https://phimimg.com/upload/vod/20240227-1/4bf3a7f99c47411e4f06259fbae68edb.jpg', 'https://phimimg.com/upload/vod/20240227-1/bbe007c076cb57e30eb561e9e3119eeb.jpg', '<p>Một Năm Không Có Công Việc - Get A Job xoay quanh Will (Teller) và Jillian (Kendrick). Cuộc sống sau khi tốt nghiệp đại học không hoàn toàn diễn ra đúng như dự định đối với họ - những người thấy mình bị lạc trong một biển công việc ngày càng xa lạ. Nhưng với sự giúp đỡ từ gia đình, bạn bè và đồng nghiệp, Will và Jillian sớm phát hiện ra rằng những cuộc phiêu lưu quan trọng nhất là những cuộc phiêu lưu mà chúng ta không thấy sắp tới.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Miles Teller","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Bryan Cranston","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
