INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amanda-knox', 'Amanda Knox', 'Amanda Knox', 'https://phimimg.com/upload/vod/20240227-1/c2150aa57522287bb035efeb1dcb67be.jpg', 'https://phimimg.com/upload/vod/20240227-1/a749850c62c1e97d5c57e040412b5606.jpg', '<p>Hai lần bị buộc tội giết người rồi lại trắng án, Amanda Knox và những người tường tận về vụ án nhất sẽ vén bức màn sự thật trong bộ phim tài liệu này.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324411);
