INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-lui-buoc', 'Không Lùi Bước', 'Hell Or High Water', 'https://phimimg.com/upload/vod/20240227-1/2d10f2efd0c1db03187c1c172d1c68a6.jpg', 'https://phimimg.com/upload/vod/20240227-1/c3a4ee570ca6386d8d57b38e378bbd91.jpg', '<p>Ở Texas, sau cái chết của mẹ, công nhân dầu khí thất nghiệp Toby Howard đang mất trang trại của mình đến Ngân hàng Midlands Texas. Toby đã ly hôn từ vợ sống với hai con trai của họ. Khi anh trai Tanner Howard được thả ra khỏi nhà tù, họ hợp tác với các cơ quan của Ngân hàng Texas Midlands để quyên tiền để trả cho khoản vay để Toby có thể rời khỏi bất động sản cho con trai mình. Trong khi đó, Texas Ranger Marcus Hamilton đang ở gần Nghỉ hưu và đối tác hậu duệ người Mỹ bản địa Alberto Parker cố gắng dự đoán bước đi tiếp theo của những tên trộm.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324411);
