INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cuoc-mang-song', 'Đánh Cược Mạng Sống', 'Caina', 'https://phimimg.com/upload/vod/20240227-1/1c908b71b38cf066aaab1b93a781fd03.jpg', 'https://phimimg.com/upload/vod/20240227-1/bbdbe008efa2b44037edc9e997fba75b.jpg', '<p>Carina sau quá khứ đau thương, cô quay sang thù ghét cả nhân loại, nhận làm công việc rùng rợn: thu hồi và xử lý xác chết của những người dân Châu Phi nhập cư trôi dạt vào bờ biển nước Ý. Đối với mỗi cơ thể được thu thập, cô được trả số tiền khá hời bởi một công ty giao dịch dùng vào việc tái chế. Đến khi số xác chết cạn kệt, những kẻ tìm-xác-chết phải tìm cách tạo ra lợi nhuận. Một chuỗi những tội ác kinh hoàng tiếp diễn khiến người xem sởn gai ốc.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luisa Amatucci","avatar":""},{"name":"Isa Danieli","avatar":""},{"name":"Helmi Dridi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324411);
