INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-khong-phai-phan-kim-lien', 'Tôi Không Phải Phan Kim Liên', 'I Am Not Madame Bovary', 'https://phimimg.com/upload/vod/20240227-1/592b1b35d109908cfdd8f3bad3073045.jpg', 'https://phimimg.com/upload/vod/20240227-1/6e25fb01ede71ee730d46f25b87f68d7.jpg', '<p>Phim Tôi Không Phải Phan Kim Liên - I Am Not Madame Bovary 2016: Lý Tuyết Liên một phụ nữ thôn quê bình dị, có cuộc sống lặng lẽ, do không cẩn thận mà có thai lần hai, nên bị lừa phải giả ly hôn với chồng để tránh luật sinh đẻ có kế hoạch của nhà cầm quyền. Nào ngờ, sau khi ly hôn, người chồng đã thay lòng, cưới người phụ nữ khác. Cô muốn đến nói chuyện lý lẽ, phải trái nhưng lại bị gã chửi là đồ Phan Kim Liên, một người lẳng lơ, trơ trẽn – tên gọi của một dâm phụ trong điển tác Thủy Hử của Trung Quốc. Để chứng minh vụ ly hôn đó là giả và chứng minh mình không là Phan Kim Liên mà suốt hai chục năm cô phải đâm đơn khắp nơi kiện cáo. Kiện từ thị trấn lên huyện, rồi thành phố và tới cả trung ương nhưng cô vẫn không thể thay đổi được tình thế mà còn đem đến kết quả khác là sự ra đi của một loạt quan chức cấp cao.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Phạm Băng Băng","avatar":""},{"name":"Phùng Tiểu Cương","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
