INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fannys-journey', 'Fanny''s Journey', 'Fanny''s Journey', 'https://phimimg.com/upload/vod/20240220-1/c5097b7aaaaf0dc5ecad17acda46890f.jpg', 'https://phimimg.com/upload/vod/20240220-1/ec5a5766f93d11f6b545285bbb9cea08.jpg', '<p>Fanny và chị gái cố gắng thoát khỏi Đức Quốc xã chiếm Pháp nhưng nhiều nguy hiểm đang ở phía trước họ.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324411);
