INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-cuoi-cung', 'Công Chúa Cuối Cùng', 'The Last Princess', 'https://phimimg.com/upload/vod/20240220-1/45cb14e854e25dc6a085b1cb619168ed.jpg', 'https://phimimg.com/upload/vod/20240220-1/1049122f73d4090287f08b5319ee374e.jpg', '<p>Công chúa cuối cùng là cả một bộ phim truyền hình và một bộ phim hành động dựa trên cuộc sống của Công chúa Deok-hye (1912-1989) được sinh ra vào gia đình hoàng gia cuối cùng của Hàn Quốc năm 1912 với tư cách là con gái nhỏ nhất và duy nhất của vị vua cuối cùng của Jo-seon, Ex-Emperor Gojong và vợ lẽ của anh ấy Yang Gui-in. Trong thực tế, cuộc sống buồn bã và bi thảm của cô đã được định hình ở mức độ cao nhất của gia đình Hoàng gia Nhật Bản và chính phủ của nó, và được thực hiện bởi các cộng tác viên Hàn Quốc của họ - một con đường dẫn đến kết thúc chính trị của Nhật Bản với chi phí của hạnh phúc cá nhân của cô. Hai năm trước khi sinh, Quân đội Hoàng gia Nhật Bản đã bao quanh Cung điện Gwang-Bok-Gong với Pin pháo với các đơn đặt hàng để bắn trong khi các quan chức Nhật Bản bên trong Cung điện đã ép buộc Hoàng đế Su-Jong (Son của King Go-Jong) của Hoàng đế để phê duyệt sự sáp nhập của Hàn Quốc cho Nhật Bản Đế chế. Sau khi người cha yêu dấu đột nhiên chết vì bị ngộ độc vào năm 1919 - bị cáo buộc bởi người Nhật chiếm - Công chúa cưỡng bức Nhật Bản Deokye rời khỏi Hàn Quốc và gia đình của cô cho một nền giáo dục ở Nhật Bản - một động thái bắt đầu một vòng xoáy thất vọng bất tận, hy vọng và ước mơ không liên tục, và Nỗi buồn sâu sắc cho đến khi cô có thể trở về Hàn Quốc ba mươi bảy năm sau đó vào năm 1962. Phần tam giác, dựa trên tiểu thuyết năm 2009 của Kwon Bi-Young, được dệt liền mạch vào phim và bao gồm một số nhân vật hư cấu có vai trò thêm vào bộ phim, nước mắt , hành động và sự phấn khích. Công chúa Deokhye đã sống ngoài phần còn lại của những năm của mình tại Cung điện Chang-Deok cho đến khi cô qua đời vào năm 1989. Cô được chôn cất tại Hong-Ryu-Reung bên ngoài Seoul.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324411);
