INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-an-giau', 'Tội Ác Ẩn Giấu', 'The Truth Beneath', 'https://phimimg.com/upload/vod/20240220-1/9b245eed7b6bb5a7e90dcf3a68ad5e36.jpg', 'https://phimimg.com/upload/vod/20240220-1/8df84dc41d4ae98024b30c7326da21da.jpg', '<p>Sau một cuộc đua quốc gia cực kỳ gần gũi, Jong-chan giành được việc đề cử đảng của mình. Ông và vợ Yeon-hong được cam kết đầy đủ cho chiến dịch và khi con gái tuổi teen Min-Jin bị mất tích, Jong-chan thuyết phục Yeon-Hong không thông báo cho chính quyền sợ sự công khai tiêu cực. Với cuộc bầu cử sắp xảy ra, Yeon-Hong quyết định tìm kiếm con gái mình, nhưng thay vào đó là một loạt âm mưu vặn vẹo, bí mật và nằm xung quanh sự biến mất của Min-Jin.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324411);
