INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('antiporno', 'Anti-Porno', 'Anti-Porno', 'https://phimimg.com/upload/vod/20240220-1/db19f9bb45b2495a1dfa08e005faa73a.jpg', 'https://phimimg.com/upload/vod/20240220-1/79e668fa9ae002dfb0d555d0b6a1ee63.jpg', '<p>Nghệ sĩ trẻ Kyoko (Ami Tomite) tàn phá tất cả mọi người rằng cô ấy gặp phải, người tồi tệ nhất của cô ấy dành cho việc tạo lại trợ lý già Noriko (Mariko Trutsui), người mà cô ấy thường xuyên lẩm bẩm - hoặc ít nhất đó là những gì dường như đang xảy ra, trước một khuôn mặt đột ngột . Đóng góp của sono robber tàn khốc cho loạt phim Roman Porno Redo chứa nhiều tình dục, nhưng cũng là một cuộc phá vỡ tường thứ tư, nghiên cứu thực nghiệm của cơ quan nữ tính được thiết lập so với phông nền ngoài trời, xuất hiện mắt.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
