INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-oi-anh-yeu-em', 'Chị Ơi Anh Yêu Em', 'Lovey Dovey', 'https://phimimg.com/upload/vod/20240220-1/cf7c01463b03a22d66f14a38e053200d.jpg', 'https://phimimg.com/upload/vod/20240220-1/274d3b7d42e388af29d06567b7e90fa6.jpg', '<p>Chị Ơi Anh Yêu Em (Lovey Dovey) xoay quanh chuyện tình yêu hài hước của hai cặp đôi “lệch pha” nhau về tuổi tác. Hai anh em Kongfa và Daoneu trúng tiếng sét ái tình với hai chị em Kookai và Khaiwan. Kongfa mê mẩn trước nụ cười hồn nhiên và dễ thương của Khaiwan. Daoneu thì lại say mê trước vẻ ngoài cá tính và tính tình mạnh mẽ của Kookai. Từ lần gặp đầu tiên đó cả hai anh em đã quyết đợi hai chị em Kookai và Khaiwan 8 năm, đợi đến khi Daoneu đã đủ trưởng thành và đàn ông, và Khaiwan đủ 18 tuổi. 8 năm sau hai anh em Kongfa Daoneu quyết định theo đuổi và tỏ tình hai chị em Kookai và Khaiwan. Liệu tình yêu đơn phương 8 năm của hai anh em họ có được hai chị em chấp nhận không?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chutavuth Pattarakampol","avatar":""},{"name":"Sheranut Yusananda","avatar":""},{"name":"Nichaphat Chatchaipholrat","avatar":""},{"name":"Thassapak Hsu (Bie)","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
