INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-khong-kiem-soat', 'Yêu Không Kiểm Soát', 'Uncontrollably Fond', 'https://phimimg.com/upload/vod/20240220-1/fbecbad6ff7c9244b53e10b80a541be7.jpg', 'https://phimimg.com/upload/vod/20240220-1/1d892893e70b10360645f2dcb6d7b2e7.jpg', '<p>Yêu Không Kiểm Soát là câu chuyện tình yêu lãng mạn có sự tham gia của Kim Woo Bin và Bae Suzy của Miss A. Shin Joon Young (Kim Woo Bin) và Noh Eul (Bae Suzy) từng yêu nhau thời còn là học sinh nhưng vì số phận trớ trêu mà họ phải chia xa. Gặp lại nhau khi đã trưởng thành, Shin Joon-young đã là một ca sĩ/diễn viên hạng A kiêu căng ngạo mạn trong khi Noh Eul là một nhà sản xuất đạo/diễn luôn mặc cảm tự ti và tôn thờ vật chất. Liệu sự tái hợp của họ có giúp nối lại tình xưa?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Woo-bin Kim","avatar":""},{"name":"Suzy Bae","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Lim Ju Eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
