INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-san-khau', 'Hào Quang Sân Khấu', 'Hibana: Spark', 'https://phimimg.com/upload/vod/20240215-1/cd78916a0391ec564c27c3fc6c975ec6.jpg', 'https://phimimg.com/upload/vod/20240215-1/e745a36ea722410ef02dd7a50641beb0.jpg', '<p>Loạt phim chuyển thể từ tiểu thuyết đoạt giải kể về tình bạn, những mâu thuẫn gặp phải giữa hai diễn viên hài trên hành trình tìm kiếm ý nghĩa cuộc sống và công việc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hayashi Kento","avatar":""},{"name":"Namioka Kazuki","avatar":""},{"name":"Kadowaki Mugi","avatar":""},{"name":"Yoshii Masao","avatar":""},{"name":"Murata Hideaki","avatar":""},{"name":"Nahana","avatar":""},{"name":"Yamamoto Sayaka","avatar":""},{"name":"Sometani Shota","avatar":""},{"name":"Taguchi Tomorowo","avatar":""},{"name":"Kobayashi Kaoru","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
