INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mi-nguyet-truyen', 'Mị Nguyệt Truyện', 'The Legend Of Miyue', 'https://phimimg.com/upload/vod/20240215-1/d624fb9274e049d38b96ec65773c3974.jpg', 'https://phimimg.com/upload/vod/20240215-1/7c570aa1dde9648a0fec1d507ae1793d.jpg', '<p>Mị Nguyệt vốn là công chúa của nước Sở, cô được Sở Uy Vương hết lòng yêu thương. Ngay từ nhỏ, Mị Nguyệt đã là thanh mai trúc mã với Sở công tử Hoàng Yết. Một lần, do cứu Mị Nguyệt mà Hoàng Yết bị rơi xuống vách núi, từ đó không rõ tung tích. Mị Nguyệt phải theo chị là Mị Xu xuất giá đến nước Tần. Mị Xu được phong làm Hoàng hậu, còn Mị Nguyệt trở thành ái phi. Vốn là tỷ muội thân thiết nhưng kể từ khi Mị Nguyệt sinh được con trai, Mị Xu đã bày ra trăm mưu ngàn kế để dồn mẹ con Mị Nguyệt vào chỗ chết. Sau khi Tần vương qua đời, Mị Nguyệt và con trai bị đầy đến nước Yến xa xôi. Tại đây, cô đã chịu đủ mọi cực khổ và nhục nhã. Sau này, Mị Nguyệt phải lấy Nghĩa Cừ Vương để cứu nước Tần thoát khỏi cơn khủng hoảng chính trị, mượn sức mạnh của Nghĩa Cử Vương để trở về nước Tần. Lần trở về này, Mị Nguyệt đã tiêu diệt thế lực của Mị Xu, lập lại bộ máy chính quyền cho nhà Tần, phong con trai lên làm vua và trở thành vị thái hậu đầu tiên trong lịch sử phong kiến Trung Quốc.</p>', 'Hoàn Tất (81/81)', 81, 'series', 'completed', 9, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Phương Trung Tín","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324411);
