INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-nong-tinh-nam-jung-gi', 'Quý Cô Nóng Tính & Nam Jung Gi', 'Ms. Temper & Nam Jung Gi', 'https://phimimg.com/upload/vod/20240209-1/6765a99ca72f84982edfd5f7ad9b0d8e.jpg', 'https://phimimg.com/upload/vod/20240209-1/6a80d450368014ba5daf1a9572586301.jpg', '<p>Ok Da Jung (Lee Yo Won) là lãnh đạo trẻ nhất của ngành công nghiệp mĩ phẩm. Lận đận trong tình duyên, đến nay cô đã li hôn tổng cộng 3 lần. Ok Da Jung không quan tâm người khác nghĩ gì về mình, bản thân cô cũng khá nóng tính. Trong khi đó, Nam Jung Gi (Yoon Sang Hyun) là sếp của một bộ phận trong cùng công ty với Ok Da Jung. Khác với cô, anh chàng này khá rụt rè và dễ chịu. Cũng chính vì không thể nói những lời làm mất lòng người khác, Nam Jung Gi luôn khiến Ok Da Jung phải sôi máu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 13, 2016, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Yo Won","avatar":""},{"name":"Yoon Sang Hyun","avatar":""},{"name":"Chansung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
