INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-thi-ngai-ma-thoi-cung-ke-phan-1', 'Trốn Thì Ngại Mà Thôi Cũng Kệ (Phần 1)', 'The Full-Time Wife Escapist (Season 1)', 'https://phimimg.com/upload/vod/20240205-1/66c56311e0be8a9984b02d499322ffb0.jpg', 'https://phimimg.com/upload/vod/20240205-1/3ff4e3795a2bf07275b3abb5a88d8fa0.jpg', '<p>Phim dựa trên Manga cùng tên của tác giả Tsunami Umino, bộ manga này cũng đã chiến thắng tại hạng mục giải thưởng best shoujo manga tại giải thưởng thường niên Kodansha Manga lần thứ 39 năm 2015... Câu chuyện xoay quanh cô gái Moriyama Mikuri - 25 tuổi tốt nghiệp đại học danh tiếng nhưng lại là một kẻ vô công rỗi nghề. Bố của Mikuri không muốn nhìn thấy con mình sống một cuộc sống ăn bám vô nghĩa nên đã sắp xếp cho cô công việc trông nhà giúp Hiramasa Tsuzaki. Mọi việc trở nên rắc rối khi Tsuzaki thuê Mikuri đóng giả làm người yêu của anh chàng thông qua một hợp đồng hôn nhân...</p>', 'Full', 11, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kong Hyo-Jin","avatar":""},{"name":"Cho Jung-Seok","avatar":""},{"name":"Ko Gyung-Pyo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
