INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tien-nha-mon', 'Đại Tiên Nha Môn', 'The Fox Fairy Court', 'https://phimimg.com/upload/vod/20240205-1/a1f46a28bb3fdbb34c46d48b975e2cab.jpg', 'https://phimimg.com/upload/vod/20240205-1/0bcdbd0a9fe092864401000e9c0cd06b.jpg', '<p>Phim Đại Tiên Nha Môn - The Fox Fairy Court 2016: kể về Vương Nguyên Phong xuất thân thế gia quan lại, nhưng không ham tiền tại, danh lợi, không đam mê tinh yêu trai gái lại đam mê phá những vụ án vì tình gây chú ý. Vương Nguyên Phong trong khi phá án cứu Hồ yêu Tiểu Thúy bị phong ấn. Để trả ân cứu mạng, đã gả làm vợ của chàng. Nhưng Vương Nguyên Phong vốn không gần nữ sắc nên 2 người vẫn chưa động phòng hoa chúc chính thức là vợ chồng. Tiểu Thúy tính tình tinh quái, thường hay ra ngoài gây rối, khiến Vương mẫu nhức đầu không thôi.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Truyền Quân","avatar":""},{"name":"Ngô Thiến","avatar":""},{"name":"Diệp Tử Đường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
