INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-che-hanh-phuc', 'Định Chế Hạnh Phúc', 'Customize Happiness', 'https://phimimg.com/upload/vod/20240205-1/dab525dcad5fe10be8f48610c5cb66ef.jpg', 'https://phimimg.com/upload/vod/20240205-1/2b6225610a369b6ec2ff38bc3c5ef5f1.jpg', '<p>Phim Định Chế Hạnh Phúc - Customize Happiness 2016: xoay quanh câu chuyện tình yêu và sự nghiệp của Triển Vọng và Điền Hiểu Ni. Điền Hiểu Ni là nhà thiết kế thời trang theo đuổi chủ nghĩa hoàn mỹ, cô luôn áp tiêu chuẩn và yêu cầu cực cao của mình trong thời trang vào chuyện tình cảm. Triển Vọng là tay đua xe nổi tiếng, thường xuyên tiếp xúc với các ngôi sao trong giới giải trí. Điền Hiểu Ni cho rằng Triển Vọng là người đàn ông hoàn hảo mà cô đang tìm kiếm nên đã chủ động theo đuổi anh.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Kiều Nhậm Lương","avatar":""},{"name":"Mễ Lộ","avatar":""},{"name":"Đồng Dao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
