INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-yeu-don-dau', 'Tập Yêu Đớn Đau', 'Lust, Love', 'https://phimimg.com/upload/vod/20240220-1/cae202a4b8ce27df770b38b35cdcffdd.jpg', 'https://phimimg.com/upload/vod/20240220-1/194ef3797b1619ecbe8fb5997c35c008.jpg', '<p>Thượng Quan Tuyết Nhi được gả cho Võ Thiên Tường, người yêu cô hơn cả mạng sống của mình, vốn dĩ cuộc sống hôn nhân vô cùng ngọt ngào nhưng sau khi người chết trỗi dậy thì mọi thứ dần tan vỡ. Đêm tân hôn thái độ của Võ Thiên Tường đột nhiên thay đổi, bỏ mặc Tuyết Nhi mà chạy đến tòa nhà hoa hồng ở trong vườn. Từ đó về sau, Võ Thiên Tường hoàn toàn trở thành một con người khác, tất cả mọi bí ẩn chỉ về tòa nhà hoa hồng bí ẩn đó.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"DINO","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324411);
