INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('below-her-mouth', 'Below Her Mouth', 'Below Her Mouth', 'https://phimimg.com/upload/vod/20240220-1/4dd18d2fe6596f7e4a4e87691f2029d6.jpg', 'https://phimimg.com/upload/vod/20240220-1/49cf34af756ace4bc6815b942495d44a.jpg', '<p>Đặt trong ba ngày; Hai người phụ nữ rất khác nhau yêu nhau. Jasmine là một biên tập viên thời trang thành công sống với vị hôn phu của mình ở Toronto. Vào một đêm thứ Sáu khi ra ngoài trong thành phố với người bạn tốt nhất Claire, cô gặp Dallas, một chiếc lợp mái nữ gần đây đã ra khỏi một mối quan hệ. Ngạc nhiên bởi sự tự tin mà hai phụ nữ rất khác nhau kết nối, Jasmine trở nên mê đắm với người phụ nữ bí ẩn đang làm việc với một phi hành đoàn trên ngôi nhà bên cạnh của cô. Cuộc họp cơ hội sớm biến thành mong muốn trong Jasmine khi cô trở nên làm quen với Dallas, người dẫn cô đi cùng Dallas đến gác xép giá rẻ của cô, nơi hai người phụ nữ sớm tham gia vào tình dục đam mê. Nhiều như cô đấu tranh với cảm xúc của mình khi được tham gia tình dục với một người phụ nữ khác, cô sợ cô với Dallas có thể làm hỏng sự tham gia của cô với vị hôn phu của mình nên được biết đến.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Canada', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
