INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trom-do-cua-ke-cap', 'Trộm Đồ Của Kẻ Cắp', 'To Steal From A Thief', 'https://phimimg.com/upload/vod/20240220-1/004162a2ef7e9b7276dace9177f6d735.jpg', 'https://phimimg.com/upload/vod/20240220-1/6613a4327bcef41e159b1eca8be3f2ca.jpg', '<p>Phim Trộm Đồ Của Kẻ Cắp - To Steal From A Thief 2016: Một nhóm trộm dưới sự chỉ huy của El Uruguayo lén vào một ngân hàng ở Valencia để ăn cắp các hộp an toàn và sau đó bỏ chạy qua một đường hầm đào giao nhau giữa các tòa nhà với một ga tàu điện ngầm bị bỏ trống. Tuy nhiên, các nhân viên báo chí của Thủ tướng Chính phủ đã phát hiện ra ý đồ của những tên trộm: chúng muốn có được tài liệu mật của họ trong hộp số 314, là tài sản của Gonzalo Soriano, một cựu thành viên của chính phủ, người đang rơi vào tình trạng hôn mê sau một tai nạn nghiêm trọng. Các kế hoạch của nhóm trộm là đi xuyên qua đường hầm nhưng do hầm bị ngập nước do mưa lớn, khiến họ không có lối thoát.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Luis Tosar","avatar":""},{"name":"Raúl Arévalo","avatar":""},{"name":"Marian Álvarez","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324411);
