INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-thanh-phong-van-3', 'Đỗ Thành Phong Vân 3', 'From Vegas To Macau III', 'https://phimimg.com/upload/vod/20240219-1/f23e4a0c2b1a2f975a16667716a19d39.jpg', 'https://phimimg.com/upload/vod/20240219-1/cc40b9284799b19548076f8b80331ea8.jpg', '<p>Phim Đỗ Thành Phong Vân 3 - The Man From Macau 3 2016 tiếp tục đưa người xem dõi theo cuộc đời nhiều biến động của Cao Tiến (Châu Nhuận Phát) – một tay chơi bài bất khả chiến bại chuyên hành hiệp trượng nghĩa và ra tay cứu giúp người nghèo. Những tưởng có thể an tâm rút lui khỏi chốn đỏ đen để chăm sóc gia đình của mình, anh đột nhiên bị kéo vào vòng xoáy âm mưu của một ông trùm giấu mặt, kèm theo biết bao rắc rối dở khóc dở cười xảy đến khiến anh và người thân được một phen “lên bờ xuống ruộng”. Bị bao vây giữa những tên giang hồ vô sỉ với võ công cao cường cùng loạt đồ chơi công nghệ mới nhằm ám sát Tiến, liệu một tương lai yên ổn và ấm êm có gọi tên anh?</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Tạ Đình Phong","avatar":""},{"name":"Lưu Đức Hoa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
