INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep', 'Bằng Chứng Thép', 'Sentence Me Guilty', 'https://phimimg.com/upload/vod/20240219-1/f3ab99ede1a8d4a6fb8a3968f961988b.jpg', 'https://phimimg.com/upload/vod/20240219-1/ef467d867ebf8568b4ece8bbe3720f8b.jpg', '<p>Phim Bằng Chứng Thép - Sentence Me Guilty 2016: Bộ phim xoay quanh ba nhân vật chính nữ bác sĩ u sầu Fengxue Hui do Chris Lee thủ vai có một sức hấp dẫn chết người với đàn ông nhưng lại bị luôn bị chồng cô Fang Wennan (Ngô Trấn Vũ thủ vai) bạo hành, có một bí mật và sự căm thù ẩn sâu trong tâm trí họ. Phó chủ tịch bệnh viện bệnh hoạn ham chức quyền luôn tìm cách chia rẽ cặp vợ chồng trẻ. Câu chuyện bắt đầu khi một bệnh nhân bị giết một cách bị ẩn, kéo theo đó là bao mưu toan, kế hèn.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Chris Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
