INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-chon-phon-hoa', 'Cuộc Tình Chốn Phồn Hoa', 'Café Society', 'https://phimimg.com/upload/vod/20240219-1/7b74729b2cc5881b05123d8c37968564.jpg', 'https://phimimg.com/upload/vod/20240219-1/4dab27286299963d76b859caf8852133.jpg', '<p>Chàng trai trẻ Bobby Dorfman mơ ước tìm kiếm cơ hội theo đuổi điện ảnh ở Hollywood, nhờ ông chú là một kẻ có máu mặt trong ngành làm phim, giúp đỡ. Thế nhưng Bobby sớm nhận ra anh không thuộc về thế giới lộng lẫy, uy quyền đó. Trong quá trình tìm hiểu miền đất hứa, Bobby đem lòng yêu Vonnie -cô thư ký xinh đẹp, hờ hững của chú mình dù biết Vonnie là “hoa đã có chủ”. Bobby bắt đầu nảy sinh ý định trở về New York… phục vụ người anh giang hồ đang cầm đầu nhiều quán bar, hộp đêm trong thành phố.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jesse Eisenberg","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Parker Posey","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
