INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-bac-si', 'Chuyện Tình Bác Sĩ', 'Doctors', 'https://phimimg.com/upload/vod/20240205-1/0e8ab70ba6e1e60d51bdf4bb97f11d71.jpg', 'https://phimimg.com/upload/vod/20240205-1/43b0514ddcc532d933223887e11cc196.jpg', '<p>\Chuyện Tình Bác Sĩ\ xoay quanh chủ nghĩa hiện thực về mối quan hệ giữa các bác sĩ và giữa bác sĩ với bệnh nhân qua cái nhìn phiến diện của xã hội đối với học lực, xuất thân… Bộ phim kể về câu chuyện của các bác sĩ trong lúc thực hiện ước mơ không màng đến sự thay đổi của xã hội, luôn kiên trì giữ vững lời thề Hippocrates - \cha đẻ của ngành Y học\.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Rae Won","avatar":""},{"name":"Sung-Kyung Lee","avatar":""},{"name":"Park Shin Hye","avatar":""},{"name":"Yeong-ae Kim","avatar":""},{"name":"Han Bao Bei","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
