INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-nguyet-va-an-sinh', 'Thất Nguyệt Và An Sinh', 'Another Me', 'https://phimimg.com/upload/vod/20240205-1/532c769923a693067395307dcd789cbe.jpg', 'https://phimimg.com/upload/vod/20240205-1/991bc841dcf447a514be5118841fad59.jpg', '<p>Tại một thành phố nhỏ miền Nam, An Sinh hoạt bát giúp cô bạn Thất Nguyệt hay thẹn thùng theo đuổi đàn anh Gia Minh, nhưng người đàn anh này lại dần dần bị sự khác biệt An Sinh hấp dẫn. Để bảo vệ tình bạn, An Sinh đi theo ca sĩ quán bar A Phan lang bạt kiếm sống. Sắp tới thời điểm kết hôn với Thất Nguyệt, Gia Minh vì An Sinh mà bỏ trốn. Trong công việc, vì An Sinh tham gia, Thất Nguyệt bị đuổi, trở về quê. Để được Thất Nguyệt tha thứ, An Sinh mở một quán bar để bầu bạn, nhưng em trai Thất Nguyệt là Cửu Nguyệt lại vì cứu An Sinh mà mất mạng, khiến quan hệ của hai người đóng băng hoàn toàn. Nhưng vận mệnh của hai người vấn quấn chặt vào nhau. Cuối cùng hai cô gái trải qua vô vàn khó khăn mới hiểu ra chân lý của tình bạn.</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yue Shen","avatar":""},{"name":"Chen Dou Ling","avatar":""},{"name":"Hùng Tử Kỳ","avatar":""},{"name":"Zou Tingwei","avatar":""},{"name":"Liang Jing Kang","avatar":""},{"name":"Xu Xiao Sa","avatar":""},{"name":"Li Guang Fu","avatar":""},{"name":"Liu Tao","avatar":""},{"name":"Jie Liu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
