INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-luan', 'Ma Luân', 'The Precipice Game', 'https://phimimg.com/upload/vod/20240207-1/794aaf985bd0ba9f42ae7b98a3b73c8e.jpg', 'https://phimimg.com/upload/vod/20240207-1/349700223b367458198041459d7b3179.jpg', '<p>Phim Ma Luân - The Precipice Game 2016: thuộc thể loại thần bí, kinh dị, xoay quanh câu chuyện cô gái xinh đẹp giàu có Lưu Thần Thần (Lâm Tâm Như) cùng bạn trai Tiểu Xuyên (Kim Thế Giai) và bốn vị khách khác vô tình trúng thưởng rồi leo lên du thuyền Thiên nhai hào. Tại đây, cả 6 người phải tham gia một trò chơi do một người thần bí (Hà Nhuận Đông) với những điều lệ quy định hà khắc. Thế nhưng, trò chơi cuối cùng lại trở thành một công cụ giết người.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Tâm Như","avatar":""},{"name":"Hà Nhuận Đông","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324411);
