INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-le-giang-son-truong-ca-hanh', 'Tú Lệ Giang Sơn - Trường Ca Hành', 'Singing All Along', 'https://phimimg.com/upload/vod/20240118-1/a90f53cb270b981a9f4ad04944fca66e.jpg', 'https://phimimg.com/upload/vod/20240118-1/d587892b448df7c40f5b0f291aca0b70.jpg', '<p>Phim kể về thời tân triều, Lưu Tú xin vào Thái Học ở Trường An, quen biết được các thiếu nên kiệt xuất như Đặng Vũ, Lưu Huyền, Phùng Dị và Âm Lệ Hoa. Vài năm sau đó, triều đình mới ngang tàn bạo ngược, thiên hạ hỗn loạn. Lưu Tú theo huynh trưởng là Lưu Diễn tổ chức khởi nghĩa vũ trang, Âm Lệ Hoa cải trang thành Âm Kích, tùy tùng đi theo.Từ khởi nghĩa Xuân Lăng đến trận chiến Côn Dương, Lưu Tú cùng các huynh đệ đồng cam cộng khổ, kề vai sát cánh, cùng nhau tác chiến, sa trường đẫm máu …</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 13, 2016, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Mã Thiên Vũ","avatar":""},{"name":"Mao Tử Tuấn","avatar":""},{"name":"Lâm Tâm Như","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324411);
