INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-moana', 'Hành Trình Của Moana', 'Moana', 'https://phimimg.com/upload/vod/20240207-1/593dd94a55bbcffd20bb9e8c2a20b7e8.jpg', 'https://phimimg.com/upload/vod/20240207-1/496cd4944df7f1d1f61fc9baf50dad5d.jpg', '<p>Moana Waialiki là một người đam mê khách sạn biển và là con gái duy nhất của một người đứng đầu trong một hàng loạt hoa tiêu dài. Khi ngư dân của hòn đảo của cô ấy không thể bắt bất kỳ loài cá nào và cây trồng thất bại, cô ấy biết rằng Demigod Maui đã gây ra Bleight bằng cách đánh cắp trái tim của nữ thần, Te Fiti. Cách duy nhất để chữa lành hòn đảo là thuyết phục Maui trở về trái tim của Te Fiti, vì vậy Moana bắt đầu một hành trình hoành tráng trên khắp Thái Bình Dương. Bộ phim dựa trên những câu chuyện từ Thần thoại Polynesia.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324411);
