INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chet-2', 'Người Chết 2', 'Dead Men 2', 'https://phimimg.com/upload/vod/20240228-1/95800390c1510651c435b7eaae06697a.jpg', 'https://phimimg.com/upload/vod/20240228-1/bde5f4ca01fd317e3d588584e11aeeb7.jpg', '<p>Bộ phim Người Chết 2 - Dead Men 2 lấy bối cảnh ở Old West vô luật pháp, một người đàn ông trẻ tuổi và anh trai của mình buộc phải thực hiện hành trình trả thù cho cái chết của cha mình, bảo vệ bộ tộc Apache mà họ yêu thương cũng như đòi lại đất đai và vàng thuộc quyền sở hữu của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Marciniak","avatar":""},{"name":"Ric Maddox","avatar":""},{"name":"Richard O. Ryan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
