INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu', 'Thiếu Nữ', 'Night''s Tightrope', 'https://phimimg.com/upload/vod/20240228-1/6550d6be25026de9858c1b6edc20baf7.jpg', 'https://phimimg.com/upload/vod/20240228-1/13c634b5f8872951e55952ef64489ee6.jpg', '<p>Phim Thiếu Nữ - Nights Tightrope 2016: Yuki là học sinh năm 2 của một trường cấp 3. Trong kì nghỉ hè, Yuki làm tình nguyện tại một bệnh viện nhi để tận mắt chứng kiến khoảnh khắc một người chết đi. Yuki có suy nghĩ đó sau khi nghe được câu chuyện nhìn thấy tử thi của một cậu bạn chuyển trường tới và cảm thấy ghen tị. Bạn của Yuki là Atsuko. Atsuko từng có quá khứ bị bạo hành học đường và có chứng lo âu. Cô cũng tham gia tình nguyện tại một viện dưỡng lão trong dịp nghỉ hè với hi vọng có thể lấy lại dũng khí nếu thấy được khoảnh khắc một người chết đi.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tsubasa Honda","avatar":""},{"name":"Mizuki Yamamoto","avatar":""},{"name":"Mackenyu Arata","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324411);
