INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-ngon-tu-do-cua-jones', 'Tuyên Ngôn Tự Do Của Jones', 'Free State Of Jones', 'https://phimimg.com/upload/vod/20240207-1/5fc6ce6ffbc147f51b019c59c65e865d.jpg', 'https://phimimg.com/upload/vod/20240207-1/89d890ef12ceed6c9a124a4762b3f55a.jpg', '<p>Năm 1863, nông dân Newt Knight ở Mississippi phục vụ như một bác sĩ cho Quân đội Liên minh. Phản đối chế độ nô lệ, Knight thà giúp đỡ những người bị thương hơn là chống lại Liên minh. Sau khi cháu trai của mình chết trong trận chiến, Newt trở về nhà ở Hạt Jones để bảo vệ gia đình nhưng nhanh chóng bị coi là kẻ đào ngũ ngoài vòng pháp luật. Buộc phải chạy trốn, anh ta tìm nơi ẩn náu với một nhóm nô lệ bỏ trốn đang trốn trong đầm lầy. Thiết lập một liên minh với nô lệ và những người nông dân khác, Knight lãnh đạo một cuộc nổi dậy sẽ thay đổi lịch sử mãi mãi.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Jacob Lofland","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
