INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-co-anh', 'Chỉ Có Anh', 'All I See Is You', 'https://phimimg.com/upload/vod/20240207-1/b0be8bb00d083dc80dc8d6c891306e58.jpg', 'https://phimimg.com/upload/vod/20240207-1/998a724c6aed2a53cc6057f0611538b1.jpg', '<p>Bị mù từ nhỏ khi gặp tai nạn ô tô, Gina xinh đẹp hiếm khi rời khỏi nhà ở Bangkok xa lạ mà phụ thuộc hoàn toàn vào người chồng chu đáo của cô, James. Và sau đó, thật bất ngờ, một ca cấy ghép giác mạc tiên tiến nhưng mang tính thử nghiệm cao hứa hẹn sẽ khôi phục lại thị lực của Gina, ít nhất là mắt phải của cô ấy - và đột nhiên - toàn bộ phân thần kinh về màu sắc và giác quan chưa được khám phá dần dần mở ra trước mắt cô. Nhưng mọi thứ có như James nói? Và điều gì sẽ xảy ra bây giờ khi cuộc sống không hoàn toàn như Gina đã tưởng tượng?</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Blake Lively","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"Jason Clarke","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
