INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-vi-than-ai-cap', 'Các Vị Thần Ai Cập', 'Gods Of Egypt', 'https://phimimg.com/upload/vod/20240207-1/23af5b84b429dbdc894f944a4828617b.jpg', 'https://phimimg.com/upload/vod/20240207-1/6ac8177aba831c31b523d11ce5400259.jpg', '<p>Nằm, vị thần bóng tối tàn nhẫn, đã chiếm lấy ngai vàng của Ai Cập và lao xuống một đế chế yên bình và thịnh vượng trong sự hỗn loạn và xung đột. Ít dám nổi loạn chống lại anh ta. Một tên trộm trẻ, có tình yêu bị thần chú chết, tìm cách cho Dethrone và thất bại với sự trợ giúp của Horus thần mạnh mẽ.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324411);
