INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-ky-uc-2016', 'Truy Tìm Ký Ức', 'Memory Lost', 'https://phimimg.com/upload/vod/20240118-1/c3100042bb65dd9d9f0ddfdf7779b084.jpg', 'https://phimimg.com/upload/vod/20240118-1/24bd592ec38b9133b9ae50e1c00c8ef1.jpg', '<p>Bộ phim Truy Tìm Ký Ức được chuyển thể từ tiểu thuyết trinh thám Mỹ Nhân Vi Hạm của tác giả Đinh Mặc, với sự tham gia của các diễn viên Dương Dung và Bạch Vũ. Truy tìm ký ức là tác phẩm thứ ba về đề tài trinh thám phá án của tác giả Đinh Mặc sau Nếu ốc sên có tình yêu và Hãy nhắm mắt khi anh đến. Nhân vật chính của câu chuyện là Hàn Trầm. Dù mất trí nhớ, anh vẫn luôn tìm kiếm vị hôn thê của mình. Cô gái bị tất cả mọi người phủ định là không có thật trong suốt 5 năm. Và rồi Hàn Trầm đến thành phố Giang, nơi đây anh đã gặp Tô Miên, một cô gái đầy cá tính theo đuổi ngành tâm lý tội phạm. Giống Hàn Trầm, Tô Miên là nhân vật đầy bí ẩn với quá khứ trống rỗng trong suốt 5 năm. Từ khi gặp nhau, anh đưa cô vào một thế giới hoàn toàn</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Rong","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"He Feng Tian","avatar":""},{"name":"Wang Yu","avatar":""},{"name":"Nan Fu Long","avatar":""},{"name":"Tom Price","avatar":""},{"name":"Tom Bai","avatar":""},{"name":"Mễ Nhiệt","avatar":""},{"name":"Cindy","avatar":""},{"name":"Thích Tích","avatar":""},{"name":"Zhang Yi Jie","avatar":""},{"name":"Chu Jun Chen","avatar":""},{"name":"Muchen Tian","avatar":""},{"name":"Yiqin Zhao","avatar":""},{"name":"Nhậm Gia Luân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324411);
