INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-khung-bo', 'Chuyến Tàu Khủng Bố', 'Red Line', 'null', 'https://phimimg.com/upload/vod/20240220-1/29729178e368a8fd731c3ceb76580874.jpg', '<p>Bộ phim Chuyến Tàu Khủng Bố - Red Line kể về một chuyến tàu điện ngầm ở Los Angeles bất ngờ gặp tai nạn khiến những người sống sót bị chôn vùi dưới đống đổ nát. Bị mắc kẹt trong tuyệt vọng, những người sống sót nhận ra rằng kẻ đã cho nổ bom là một trong số họ. Sự nghi ngờ lẫn nhau bắt đầu xuất hiện trong cuộc chiến sinh tồn này.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Gale Anderson","avatar":""},{"name":"John Billingsley","avatar":""},{"name":"Mark Saul","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
