INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-khun-pan', 'Người Hùng Khun Pan', 'Khun Pan', 'null', 'https://phimimg.com/upload/vod/20240220-1/1b471972ce79c927f3cf1d66b7885c72.jpg', '<p>Bộ phim Người Hùng Khun Pan - Khun Pan dựa trên cuộc đời Khun Pan - Trung úy cảnh sát Khun Puntharak Rachadej. Ông là một thám tử cảnh sát bí ẩn và dũng cảm sống đến tuổi 108. Nổi tiếng với công việc cảnh sát, Khun Pan cũng là một thầy phù thủy có khả năng siêu nhiên bắt nguồn từ niềm tin vào lòng tốt và đạo đức. Anh ta đã sử dụng sức mạnh ma thuật của mình để bắt giữ và đánh bại một số tên côn đồ bị truy nã gắt gao nhất vào giữa thế kỷ 20 Xiêm.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Krisada Sukosol Clapp","avatar":""},{"name":"Ananda Everingham","avatar":""},{"name":"Chupong Changprung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324411);
