INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-tuong', 'Chiếu Tướng', 'Checkmate', 'https://phimimg.com/upload/vod/20240128-1/5c66fb8dc7ac7db4b38eb48caf293ff7.jpg', 'https://phimimg.com/upload/vod/20240128-1/01e8b6250838205df24ab711b778a088.jpg', '<p>Có một cuộc chiến tranh giữa Bikers và các đại lý ma túy tại địa phương. Một nhóm cảnh sát với ý đồ đen tối đang điều tra họ, Cùng lúc đó xuất hiện thám tử điều tra song hành cùng nhóm cảnh sát. Để Thám tử Thám tử làm việc công minh, trước tiên anh ta cần tìm ra những cảnh sát xấu đầu tiên, để bản thân tránh được những rắc rối và cứu bản thân ra khỏi mối nguy hại bởi những cảnh sát độc ác .</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fat Joe","avatar":""},{"name":"Alex Maisonette","avatar":""},{"name":"Christine Borges","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324411);
