INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phong-vien-my', 'Người Phóng Viên Mỹ', 'Whiskey Tango Foxtrot', 'https://phimimg.com/upload/vod/20240128-1/c670219f37eb87f3ef55e90ca1c34239.jpg', 'https://phimimg.com/upload/vod/20240128-1/57513782d646156c441c4da5ffcbf396.jpg', '<p>Năm 2002, nhà sản xuất tin tức cáp Kim Barker quyết định thay đổi thói quen của mình bằng cách nhận một nhiệm vụ mới táo bạo ở Kabul, Afghanistan. Bị tách khỏi lối sống thoải mái của người Mỹ, Barker thấy mình đang ở giữa một vùng chiến sự ngoài tầm kiểm soát. May mắn thay, cô gặp Tanya Vanderpoel, một nhà báo đồng nghiệp, người luôn bảo vệ cô phóng viên bị sốc. Giữa các chiến binh, lãnh chúa và tiệc tùng thâu đêm, Barker khám phá ra chìa khóa để trở thành một phóng viên thành công.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Margot Robbie","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Josh Charles","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324411);
