INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-vuot-nguc', 'Chú Chó Vượt Ngục', 'Ozzy', 'https://phimimg.com/upload/vod/20240128-1/77f4c4eb22d54f0a6709980decb260d4.jpg', 'https://phimimg.com/upload/vod/20240128-1/389d745f882ca643880385971f4599be.jpg', '<p>Cuộc đời của chú chó thân thiện hiền lành và giản dị Ozzy bỗng dưng bị đảo lộn khi gia đình nhà Martin đi du lịch xa. Và vấn đề duy nhất họ gặp phải là: Chó không được phép đến nơi đó! Nhà Martin đành gửi chú chó vào khu giải trí dành cho chó Blue Creek- một nơi thật ra là nhà tù dành cho chó. Ozzy phải cùng những người bạn mới tìm cách thoát khỏi nhà tù Blue Creek để trở về bên gia đình Martin.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Elsa Pataky","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Dani Rovira","avatar":""},{"name":"Carlos Areces","avatar":""},{"name":"Fernando Tejero","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324411);
