INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dinh-quan-trong', 'Quyết Định Quan Trọng', 'The Choice', 'https://phimimg.com/upload/vod/20240123-1/d4521799420cb6b98f044801c6a06463.jpg', 'https://phimimg.com/upload/vod/20240123-1/180976ad99adeb88f2c1ccec98b99a74.jpg', '<p>The Choice kể về cô sinh viên y khoa tính nết sôi nổi Gabby Holland (Teresa Palmer), chuyển đến sống cạnh nhà của một chàng sát thủ tình trường Travis Shaw (Benjamin Walker), và từ đó, chuyến hành trình tình yêu của họ giống như một giấc mơ không có thật. Travis luôn tin rằng một mối quan hệ nghiêm túc với phụ nữ sẽ phá hỏng lối sống lông bông của mình, còn Gabby chỉ muốn ổn định cuộc sống với người bạn trai lâu năm, cho đến một ngày thứ hấp lực mãnh liệt giữa hai con người trái tính trái nết đó làm cuộc sống vốn dĩ được lên kế hoạch từ trước của họ đảo lộn. Sau một buổi hẹn hò chóng vánh, Gabby và Travis làm đám cưới và cùng xây dựng cuộc sống gia đình, cùng nhau quyết định mọi vấn đề trong cuộc sống, cho đến khi một trong hai buộc phải tự mình đưa ra quyết định quan trọng nhất trong đời.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Teresa Palmer","avatar":""},{"name":"Alexandra Daddario","avatar":""},{"name":"Benjamin Walker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324411);
