INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-hung-bao', 'Công Tố Viên Hung Bạo', 'A Violent Prosecutor', 'https://phimimg.com/upload/vod/20240121-1/b8eb733b1279127de28e8cb0964d98f2.jpg', 'https://phimimg.com/upload/vod/20240121-1/d6760c544d46dfa9efbb2f2172d875c7.jpg', '<p>A Violent Prosecutor (Công tố viên hung bạo) là bộ phim bom tấn của điện ảnh Hàn Quốc trong năm 2016. Bộ phim này dẫn đầu về doanh thu phòng vé trong nửa đầu năm 2016, thu về hơn 69 triệu USD và thu hút gần 10 triệu lượt khán giả xứ kim chi.Nội dung phim nói về Byun Jae Wook, một công tố viên nổi tiếng hung bạo. Anh ta bị tống giam sau khi khiến cho một nghi phạm bỏ mạng trong quá trình thẩm vấn. Mọi bằng chứng đều chỉ ra Byun Jae Wook chính là thủ phạm. Từ một công tố viên, Byun Jae Wook bị điều tra về vụ việc và trở thành tội phạm với mức án lên tới 15 năm tù. Sau 5 năm ở tù, anh ta bất ngờ tìm thấy con đường rửa sạch tội lỗi của mình từ một bạn tù.A Violent Prosecutor nhận được nhiều lời khen ngợi từ giới phê bình và khán giả. Các ý kiến đều đánh giá bộ phim này có nội dung hấp dẫn, cuốn hút với nhiều tình tiết bất ngờ khó đoán trước. Bên cạnh đó là các chi tiết hài hước thú vị được cài cắm hợp lý. Cũng không thể bỏ qua diễn xuất “tung hứng” ăn ý của đôi nam diễn viên Hwang Jung-min và Kang Dong-won.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Dong Won","avatar":""},{"name":"Hwang Jung Min","avatar":""},{"name":"Lee Sung Min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324412);
