INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-quy-va-bach-hoang-tu', 'Hắc Quỷ Và Bạch Hoàng Tử', 'The Black Devil And The White Prince', 'https://phimimg.com/upload/vod/20240121-1/3a9f2588fa49f34cb8d48dcc2fb6d14d.jpg', 'https://phimimg.com/upload/vod/20240121-1/46e5aa6da78226263f3420b45a805a0d.jpg', '<p>Yu Akahane chuyển đến một phòng ký túc xá sau khi cha cô chuyển công tác. Cô ấy rất hào hứng rằng cô ấy sẽ sống cùng ký túc xá với Takumi Shirakawa hay còn gọi là Bạch công tử. Tuy nhiên, Haruto Kurosaki hay còn gọi là Quỷ đen hôn cô như một hình phạt vì đã chống lại anh ta. Đó là nụ hôn đầu tiên của Yu Akahane. Kể từ đó, cô ấy trở nên nghe lời Haruto Kurosaki.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kento Nakajima","avatar":""},{"name":"Nana Komatsu","avatar":""},{"name":"Yudai Chiba","avatar":""},{"name":"Sara Takatsuki","avatar":""},{"name":"Yuta Kishi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
