INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-vua-cuoi-cung', 'Vị Vua Cuối Cùng', 'The Last King', 'https://phimimg.com/upload/vod/20240121-1/5d27f167e545d1df94a3a553f19a5357.jpg', 'https://phimimg.com/upload/vod/20240121-1/3f4692e8088736b82dfb1868c7592f68.jpg', '<p>Na Uy, năm 1204. Một cuộc nội chiến giữa birkebeiners—người của nhà vua— và baglers—những người ủng hộ tầng lớp quý tộc Na Uy và Giáo hội—đã tàn phá đất nước. Hai người đàn ông phải bảo vệ một đứa bé, đứa con ngoài giá thú của Vua Håkon, người sẽ trở thành vị vua tương lai và là người kiến tạo hòa bình, khỏi những kẻ muốn giết cậu.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jakob Oftebro","avatar":""},{"name":"Kristofer Hivju","avatar":""},{"name":"Pål Sverre Hagen","avatar":""},{"name":"Thorbjørn Harr","avatar":""},{"name":"Nikolaj Lie Kaas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324412);
