INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-chung', 'Ở Chung', 'Crashing', 'https://phimimg.com/upload/vod/20240116-1/a985964b9de631b2efc901ec8c9203ce.jpg', 'https://phimimg.com/upload/vod/20240116-1/a939c366725d2eba4f810b26ec91d4ae.jpg', '<p>Để đổi lấy tiền thuê rẻ mạt, nhóm trai gái đủ mọi thành phần quyết định làm giám hộ tài sản cho bệnh viện bỏ đi mà họ đang ở. Đã đến lúc vui vẻ rồi đây!</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Phoebe Waller-Bridge","avatar":""},{"name":"Jonathan Bailey","avatar":""},{"name":"Adrian Scarborough","avatar":""},{"name":"Damien Molony","avatar":""},{"name":"Louise Ford","avatar":""},{"name":"Julie Dray","avatar":""},{"name":"Amit Shah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
