INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trang', 'Ánh Trăng', 'Moonlight', 'https://phimimg.com/upload/vod/20240122-1/f958f599f30589f3239bf41c7b5dff50.jpg', 'https://phimimg.com/upload/vod/20240122-1/addaf6ad1eaa6c7e767828c1d740f406.jpg', '<p>Phim Ánh Trăng - Moonlight 2016: xoay quanh cuộc sống của một người đàn ông da màu, đồng tính, sinh sống tại Miami. Bộ phim chia làm ba phần, khắc họa một cách bao quát cuộc đấu tranh của anh với ma túy, những nỗi đau không nguôi từ bi kịch thời thơ ấu và sự dằn vặt kìm nén tình yêu khi mang trong mình giới tính khác biệt.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Trevante Rhodes","avatar":""},{"name":"André Holland","avatar":""},{"name":"Janelle Monae","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
