INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hau-cua-thieu-gia-mu-2016', 'Người Hầu Của Thiếu Gia Mù', 'The Maid Of The Blind Master', 'null', 'https://phimimg.com/upload/vod/20240121-1/9d893df366415db342f7ee4ec403ab7e.jpg', '<p>Vị chủ tịch trẻ độc đoán đã phải lòng cô giúp việc ngọt ngào và tốt bụng! Bộ phim kể về một cô gái đã bị mẹ kế của mình ép làm người giúp việc kiêm trợ lý tại nhà cho vị chủ tịch bị mù độc tài. Cô gái đã cảm hóa được vị chủ tịch mù bằng lòng tốt và sự ngây thơ của mình, và cũng đã giúp anh hồi phục và lấy lại được ánh sáng cho đôi mắt thành công. Tuy nhiên, chính chị gái của cô đã cướp người yêu của cô và cô tiếp tục bị ngược đãi.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Phùng Chỉ Mặc","avatar":""},{"name":"Lưu Dân Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
