INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nhan-online', 'Tình Nhân Online', 'Mike And Dave Need Wedding Dates', 'https://phimimg.com/upload/vod/20240121-1/df1bf1b00fa69df7d122d770aae483b2.jpg', 'https://phimimg.com/upload/vod/20240121-1/0c3d330fc3218cfc05cadefe0cc4a67c.jpg', '<p>Mike và Dave là những anh em trẻ tuổi, thích phiêu lưu, vui vẻ và có xu hướng mất kiểm soát trong các buổi họp mặt gia đình. Khi chị gái Jeanie của họ tiết lộ kế hoạch tổ chức đám cưới ở Hawaii, những người còn lại trong gia đình Stangle nhất quyết yêu cầu hai anh em tổ chức những buổi hẹn hò đàng hoàng. Sau khi đặt một quảng cáo trên Craigslist, hai anh em quyết định chọn Tatiana và Alice, hai người phụ nữ quyến rũ và có vẻ bình thường. Tuy nhiên, khi họ đến hòn đảo, Mike và Dave nhận ra rằng những người bạn đồng hành của họ đã sẵn sàng để trở nên hoang dã và tiệc tùng.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zac Efron","avatar":""},{"name":"Adam DeVine","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"Sam Richardson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
