INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-xuc-tu', 'Quái Vật Xúc Tu', 'The Void', 'https://phimimg.com/upload/vod/20240121-1/fd0dcf48d6d4bd52b21cad17b83d3b29.jpg', 'https://phimimg.com/upload/vod/20240121-1/167624e4ea07e0da813a19440e6afc01.jpg', '<p>Giữa một cuộc tuần tra định kỳ, sĩ quan Daniel Carter tình cờ gặp một người đẫm máu đang đi khập khiễng trên một đoạn đường vắng vẻ. Anh ta vội vã đưa chàng trai trẻ đến một bệnh viện nông thôn gần đó do một đội ngũ nhân viên phục vụ, chỉ để phát hiện ra rằng bệnh nhân và nhân viên đang biến thành một thứ gì đó vô nhân đạo. Khi nỗi kinh hoàng ngày càng gia tăng, Carter dẫn dắt những người sống sót khác trong chuyến hành trình địa ngục vào sâu trong lòng đất của bệnh viện trong một nỗ lực tuyệt vọng để chấm dứt cơn ác mộng trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Poole","avatar":""},{"name":"Kathleen Munroe","avatar":""},{"name":"Art Hindle","avatar":""},{"name":"Daniel Fathers","avatar":""},{"name":"Kenneth Welsh","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
