INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-em-ngay-do', 'Hẹn Em Ngày Đó', 'Will You Be There?', 'https://phimimg.com/upload/vod/20240121-1/7fc955c19070b9d3c3a5312ccc00f742.jpg', 'https://phimimg.com/upload/vod/20240121-1/1129b8a7409c97f7199753f9d6c568bd.jpg', '<p>Một bác sĩ phẫu thuật (Kim Yun-seok) không còn nhiều thời gian do một căn bệnh nghiêm trọng. Mong muốn của anh là nhìn thấy bạn gái đã chết trong một tai nạn 30 năm trước. Bác sĩ phẫu thuật được 10 viên thuốc từ một ông già bí ẩn. 10 viên thuốc cho phép anh ta đi du lịch kịp thời trước quá khứ.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
