INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-beast-so-fierce', 'No Beast So Fierce', 'No Beast So Fierce', 'https://phimimg.com/upload/vod/20240111-1/929065324b4c66b795d306d42fd659a0.jpg', 'https://phimimg.com/upload/vod/20240111-1/0865d980f6241301feabdf4c52efac93.jpg', '<p>Được trả tự do sau 20 năm ngồi tù, gã trai cũ Charlie Sundstrom (Bailey Chase) trở về quê nhà và phát hiện đứa con trai bị ghẻ lạnh của mình, người đã biến mất trong thế giới ngầm tội phạm, đang bị săn đuổi bởi một thủ lĩnh băng đảng tàn nhẫn. Charlie nhờ sự giúp đỡ của một sĩ quan chỉnh sửa lừa đảo (Dylan Baker), để giúp tìm kiếm. Nhưng nhân viên sửa sai có một quá khứ bi thảm của riêng mình. Chẳng bao lâu nữa, cuộc sống tuyệt vọng của họ sẽ đụng độ trong một cao trào thay đổi trò chơi. Theo truyền thống của những bộ phim như Se7en, The Usual Suspects và Angel Heart, No Beast So Fierce rút ra nhiều ý nghĩa và sức mạnh từ cái kết gây sốc của nó.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Kathryn Erbe","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Bailey Chase","avatar":""},{"name":"Amy Spanger","avatar":""},{"name":"Susan Pourfar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
