INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-coc-bat-thanh', 'Bắt Cóc Bất Thành', 'Retribution', 'https://phimimg.com/upload/vod/20240104-1/84c78b9d4865844fee66564bd2148e61.jpg', 'https://phimimg.com/upload/vod/20240104-1/3f67bc5970659a82f5e9016423a1bf7c.jpg', '<p>Dan Williams, kẻ chuyên thu nợ xã hội đen, gần như phát điên khi cô con gái bị bắt cóc. Cuộc báo thù đẫm máu trong 24 giờ bắt đầu, kẻ chủ mưu thực sự hoảng sợ, sát thủ hàng đầu được thuê để săn mạng Dan trước khi quá muộn. Cảnh sát buộc phải vào cuộc ngăn chặn cuộc chiến đường phố khiến bộ phim càng hấp dẫn!</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Albury","avatar":""},{"name":"David Bispham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
