INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-dien-tinh', 'Những Kẻ Điên Tình', 'The Insanity', 'https://phimimg.com/upload/vod/20240104-1/faf3ec267c7cf6283a38cc4a1c2e6c2f.jpg', 'https://phimimg.com/upload/vod/20240104-1/7c626da5ec8da377127fd8a78a883712.jpg', '<p>Sau khi tỉnh lại, bảy con người xa lạ phát hiện bị nhốt chung một chỗ trong bệnh viện tâm thần. Để thoát khỏi đây, họ bày nhiều chiêu trò chứng minh họ là người bình thường. Cho đến một hôm, viện trưởng đưa ra yêu cầu nếu tìm ra kẻ điên thực sự thì những người còn lại sẽ được ra ngoài. Vậy trong số họ là người điên, ai là kẻ tỉnh?</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Kim Sĩ Kiệt","avatar":""},{"name":"Tào Vệ Vũ","avatar":""},{"name":"Vạn Tây","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
