INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-ma-thuat', 'Vũ Điệu Ma Thuật', 'Pop In Q', 'https://phimimg.com/upload/vod/20240104-1/7b8327429672d3a9b13fa833154cc14d.jpg', 'https://phimimg.com/upload/vod/20240104-1/8b7a020200d875f31b7e57dc3888d203.jpg', '<p>Tình cờ nhặt được viên pha lê bí ẩn, năm nữ sinh đang gặp rắc rối trong cuộc sóng bị đưa tới một thế giới song song, nơi sức mạnh được quyết định bởi khả năng nhảy múa. Khi phát hiện ra bí ẩn sau những viên pha le cũng là lúc họ học cách thấu hiểu nhau từ trái tim và cùng hòa chung vũ điệu để có sức mạnh cứu toàn bộ thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Asami Seto","avatar":""},{"name":"Shiori Izawa","avatar":""},{"name":"Ari Ozawa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
