INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-toi-la-meo', 'Bố Tôi Là Mèo', 'Nine Lives', 'https://phimimg.com/upload/vod/20240104-1/156d89626c9614145fdc698ddc38540e.jpg', 'https://phimimg.com/upload/vod/20240104-1/1bd596640fd167785c21194a1f35d09d.jpg', '<p>Phim Bố Tôi Là Mèo - Nine Lives 2016: Tom Brand (Kevin Spacey) là một tỷ phú giàu có với cơ nghiệp đồ sộ. Tuy nhiên vì quá đam mê công việc nên ông xa rời cuộc sống gia đình với người vợ xinh đẹp Lara (Jennifer Garner) và cô con gái đáng yêu Rebecca (Malina Weissman). Vào sinh nhật thứ 11 của Rebecca, cô bé muốn được tặng một chú mèo. Dù ghét mèo nhưng do không còn thời gian, Tom đành đtìm mua một chú mèo để làm quà cho con gái. Ông đến một cửa hàng và được người chủ bán cho chú mèo có cái tên Mr. Fuzzypants. Vội vã đến tiệc sinh nhật của con gái, Tom đã gặp tai nạn. Khi tỉnh dậy ông thấy mình bị nhốt trong cơ thể của Mr. Fuzzypants. Trở thành chú mèo được chăm sóc bởi chính gia đình mình, Tom dần nhận ra ý nghĩa thực sự của cuộc sống…</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Kevin Spacey","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Malina Weissman","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324412);
