INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sieu-nhien-phan-1', 'Thám Tử Siêu Nhiên (Phần 1)', 'Dirk Gently''s Holistic Detective Agency (Season 1)', 'https://phimimg.com/upload/vod/20240112-1/8906828185456d840d9d636cb4637412.jpg', 'https://phimimg.com/upload/vod/20240112-1/4126e9c5acfc6da6db5bc05042e6bc92.jpg', '<p>Thám tử Dirk nghiệp dư lập dị và trợ lý bất đắc dĩ Todd cùng nhau ứng phó với các bí ẩn siêu nhiên nguy hiểm và rối rắm.Sau khi bị dính líu đến một loạt vụ giết người kỳ quái và ghê rợn, Todd, nhân viên hành lý khách sạn hay càu nhàu miễn cưỡng hợp tác với Dirk, thám tử tư sôi nổi quái lạ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel Barnett","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Hannah Marks","avatar":""},{"name":"Fiona Dourif","avatar":""},{"name":"Jade Eshete","avatar":""},{"name":"Mpho Koaho","avatar":""},{"name":"Michael Eklund","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Amanda Walsh","avatar":""},{"name":"Izzie Steele","avatar":""},{"name":"Neil Brown Jr.","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Miguel Sandoval","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
