INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-chong-e', 'Hành Trình Chống Ế', 'Love Chaotically', 'https://phimimg.com/upload/vod/20240109-1/96f8f499c2025116aca207b38135f6af.jpg', 'https://phimimg.com/upload/vod/20240109-1/aed886b876d35fff41008cbe0d745175.jpg', '<p>Priew (Vill) và Wisa (Gypsy) là hai người bạn thân sinh cùng ngày, cùng tháng, cùng năm. Nếu như Priew sắp kết hôn thì Wisa lại chưa bao giờ hẹn hò. Trong một dịp tình cờ, Priew phát hiện chồng sắp cưới của mình đã lừa dối và có người phụ nữ khác, lúc đó cô đã tự hỏi bản thân mình là tại sao tình yêu của cô lại thất bại như thế. Vào một ngày, Wisa may mắn gặp được một nhà tâm linh, người đó nói rằng cô và Priew sinh nhằm ngày xấu nên sẽ gặp vận rủi, nếu muốn tránh số kiếp đen đủi của bản thân thì hai cô phải đi viếng 19 ngôi đền để bày tỏ lòng thành kính của mình, nếu không cả hai sẽ phải sống kiếp cô đơn suốt cả cuộc đời. Trên hành trình chống ế, Priew và Wisa đã gặp được Pete (Kangsom). Người yêu của Pete đã mất vào hai năm trước và anh đang hoàn thành lời hứa vác balo đi du lịch khắp nơi của cả hai, anh dự định sẽ cầm hoa và đến thăm người yêu của mình ở một vách núi. Tại đây, cả ba đã gặp nhau và kể từ lúc biết được người yêu của Pete mất, cả Priew và Wisa đều nhắm anh như là mục tiêu của đời mình. Từ đó cả hai người bạn thân cùng đang trong hành trình chống ế bắt đầu cuộc chiến giành trai ngoạn mục. Liệu trong Priew và Wisa, ai mới là người chiến thắng trong cuộc chiến giành trái tim của trai đẹp? Tình bạn giữa hai người họ có bị ảnh hưởng gì không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Kangsom Tanatat","avatar":""},{"name":"Vill Wannarot","avatar":""},{"name":"Gypsy Keerati","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
