INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-trong-tiem-thuc', 'Sát Nhân Trong Tiềm Thức', 'Himitsu: The Top Secret', 'https://phimimg.com/upload/vod/20231230-1/fe08eff79eefa58bda857a757901ddd2.jpg', 'https://phimimg.com/upload/vod/20231230-1/6ef04af664618e0fd6c1d52486beae81.jpg', '<p>Phim Sát Nhân Trong Tiềm Thức - Himitsu: The Top Secret 2016: được chuyển thể từ manga cùng tên của tác giả Shimizu Reiko, câu chuyện lấy bối cảnh vào năm 2016, kể về một nhóm nhà nghiên cứu thuộc Phòng thí nghiệm Pháp y số 9 của Viện Nghiên cứu Khoa học cảnh sát quốc gia sử dụng một cỗ máy cho phép đọc trí nhớ của người chết trong vòng 2 năm. Cũng bởi vì kí ức của con người được chuyển thể thành hình ảnh như thế, nên càng ngày càng phát sinh ra những vấn đề liên quan đến pháp luật lẫn đạo đức.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Thuyết Minh', 'HD', 'Nhật Bản', 0, '[{"name":"Toma Ikuta","avatar":""},{"name":"Lisa Oda","avatar":""},{"name":"Masaki Okada","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
