INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phieu-luu-cua-gau', 'Chuyến Phiêu Lưu Của Gấu', 'Boonie Fantastica', 'https://phimimg.com/upload/vod/20231230-1/345ecbfc0680680a442233dc26ca6028.jpg', 'https://phimimg.com/upload/vod/20231230-1/abb3ee5cab31778926f455089cf1369c.jpg', '<p>Chuyến Phiêu Lưu Của Gấu Boonie - Fantastica kể về hành trình của những chú gấu Boonie hợp lực cùng với tiều phu Vick và cô nhóc siêu quậy để lật tẩy âm mưu của lũ người xấu. Trong một đêm mưa gió, tiều phu Vick vô tình mang nhầm một chiếc va li bí ẩn về nhà. Cũng từ đây, Vick và anh em nhà gấu bất ngờ trở thành những ông bố bỉm sữa chính hiệu, cùng nhau chăm sóc cô nhóc. Bất ngờ hơn, họ lại cùng song hành, hợp tác đầy ăn ý trên hành trình giải cứu cô bé khỏi tay những kẻ xấu.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324412);
