INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-do-di-ma-co', 'Đường Do Đi Mà Có', 'Đường Do Đi Mà Có', 'https://phimimg.com/upload/vod/20231219-1/c0254d888cfa6a006af73cf8f0fe2550.jpg', 'https://phimimg.com/upload/vod/20231219-1/9b3fb729d49b5e172342f1788510a2b2.jpg', '<p>Đường Do Đi Mà Có kể về quá trình 10 năm đầu tư ra nước ngoài của Tập đoàn Công nghiệp - Viễn thông Quân đội (Viettel). 10 năm trước, Tập đoàn Viettel nhận thấy, chính sự bất bình đẳng thông tin tạo ra đói nghèo. Nhưng cũng chính việc kết nối thông tin từ những vùng quê nghèo với thế giới thông qua dịch vụ viên thông lại giúp chính họ nhanh chóng giàu có. Chính vì thế, Tập đoàn Viettel đã chọn con đường đầy thách thức, đó là đem dịch vụ viễn thông đến những vùng xâu xa nhất của trái đất, phổ cập những dịch vụ viễn thông, để ai cũng có thể sử dụng.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Lồng Tiếng', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324412);
