INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-lien-hoan', 'Sát Nhân Liên Hoàn', 'Strangled', 'https://phimimg.com/upload/vod/20231219-1/c930e86cdeae81574e4fcb66a098ce41.jpg', 'https://phimimg.com/upload/vod/20231219-1/e26bb251d22375ca2a19b38d41f5acbc.jpg', '<p>Một kẻ giết người tâm thần đang rình mò, hắn tiếp tục tàn sát những phụ nữ trẻ trong khi một người đàn ông vô tội bị buộc tội sai và bị kết án vì những tội ác mà anh ta không bao giờ có thể phạm phải. Một thám tử quyết tâm đến hiện trường và nhanh chóng bị ám ảnh bởi vụ án trong khi chịu áp lực từ công tố viên để chứng kiến một người đàn ông bị treo cổ.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Károly Hajduk","avatar":""},{"name":"Jászberényi Gábor","avatar":""},{"name":"Anger Zsolt","avatar":""},{"name":"Mónika Balsai","avatar":""},{"name":"Piroska Móga","avatar":""},{"name":"Eszter Csépai","avatar":""},{"name":"Péter Bárnai","avatar":""},{"name":"Zsolt Trill","avatar":""},{"name":"Zsófia Szamosi","avatar":""},{"name":"András Réthelyi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
