INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bo-bao-thu', 'Ông Bố Bảo Thủ', 'Captain Fantastic', 'https://phimimg.com/upload/vod/20231219-1/9f7013a5f39e157ddf9c47a8bc15d9c0.jpg', 'https://phimimg.com/upload/vod/20231219-1/060f2906f70d9fa67b4ac62af50cacad.jpg', '<p>Phim Ông Bố Bảo Thủ - Captain Fantastic 2016: Bảo vệ sáu đứa con thơ giữa mảnh rừng Tây Bắc Thái Bình Dương, Ben đề ra những luật lệ nghiêm ngặt và áp đặt chúng cho các con. Rồi đến ngày kia, khi ông phải từ bỏ “địa đàng” với các bài học giáo huấn của mình, ông nhận ra hành trình này mới thật sự “dạy” cho ông bài học làm cha thực sự.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Viggo Mortensen","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"Kathryn Hahn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
