INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-quy', 'Đứa Con Của Quỷ', 'Damien', 'https://phimimg.com/upload/vod/20231219-1/c3f6bb55907590d648becc36cd03916b.jpg', 'https://phimimg.com/upload/vod/20231219-1/a00875dddcc954fa6249b61918a8744b.jpg', '<p>Phim Đứa Con Của Quỷ - Damien 2016: Robert cùng vợ mình là Katherine, sau hai lần sẩy thai, đã lại hạ sinh một mụn con chết ngay sau khi lọt lòng. Ngay khi đó, Robert được vị linh mục của bệnh viện cho xem một đứa bé sơ sinh khác và bảo hãy nhận nó làm con vì đó là trẻ mồ côi cả bố lẫn mẹ. Robert đã chấp nhận và quyết định giấu vợ mình chuyện này. Đứa bé được đặt tên là Damien và lớn lên trong tình yêu thương của cặp vợ chồng. Khi Damien được 5 tuổi thì những chuyện kinh khủng liên tiếp xảy ra, vú em treo cổ tự tử đúng vào ngày sinh nhật của bé; những thú hoang trong vườn bách thú tỏ vẻ kinh sợ khi bé xuất hiện, chính bé nổi cơn giận khi được chở đến nhà thờ. Dần dà, Robert phát hiện ra rằng, Damien chính là đại diện của quỷ Satan trên trần gian. Nhiều năm sau khi trưởng thành, Damien phải tiếp tục đối diện với bản ngã của chính mình đứa con của Quỷ Satan - Kẻ Phản Chúa...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bradley James","avatar":""},{"name":"Megalyn Echikunwoke","avatar":""},{"name":"Omid Abtahi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
