INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-hon-nhan', 'Cuộc Sống Hôn Nhân', 'Why Get Maried', 'https://phimimg.com/upload/vod/20240118-1/8cd4c7d5eef481a3a47d0e69624cfae0.jpg', 'https://phimimg.com/upload/vod/20240118-1/1f4ca5bab5fe4c57a8a04559ed722761.jpg', '<p>Cuộc Sống Hôn Nhân - Why Get Married xoay quanh câu chuyện của 3 cô bạn thân: Phàm Phàm (Diêu Địch đóng), Đại Hà (Nhậm Trọng đóng), Lão Điếu (Trịnh Nhã Văn đóng). Bảy năm trước, Phàm Phàm có mối tình đầu đẹp thuần khiết với Vương Đường Dịch (Ngô Trác Hy đóng) nhưng không thành. Quên đi mối tình đầu sâu đậm, Phàm Phàm có tình yêu 3 năm với người đàn ông hoàn mỹ và được gia đình chấp thuận. Mọi chuyện tưởng chừng như rất thuận lợi, nhưng tất cả đã đi trật đường ray. Sau một đêm tiệc tùng, trong cơn say, Phàm Phàm cùng 2 người bạn thân đã đăng kí kết hôn với 3 người đàn ông xa lạ họ mới gặp trong vũ trường. Trớ trêu nhất có lẽ chính là Phàm Phàm, khi người đàn ông cô kết hôn cùng lại không hề xa lạ mà chính là người yêu cũ.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 6, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Diêu Địch","avatar":""},{"name":"Ngô Trác Hy","avatar":""},{"name":"Nhậm Trọng","avatar":""},{"name":"Trịnh Nhã Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
