INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('schwarzes-marken', 'Schwarzes Marken', 'Schwarzes Marken', 'https://phimimg.com/upload/vod/20231219-1/ae0d020322ab461de5381505cc6843ef.jpg', 'https://phimimg.com/upload/vod/20231219-1/7364294434e0b939e90ce62ceef6233f.jpg', '<p>Đức bị chia thành Đông và Tây sau Thế chiến thứ hai, nơi công dân của một trong hai bên coi bên kia là kẻ thù. Tuy nhiên, giữa Chiến tranh Lạnh, Trái đất đã bị xâm chiếm bởi một dạng sống ngoài hành tinh đổ bộ lên Kashgar, Khu tự trị Duy Ngô Nhĩ Tân Cương, được gọi là Beta. Giờ đây, mười năm sau lần tiếp xúc đầu tiên, Đông Đức, tên chính thức là Cộng hòa Dân chủ Đức, đã trở thành tiền tuyến.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kana Marutsuka","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Yoshino Nanjo","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Kaori Fukuhara","avatar":""},{"name":"Nozomi Yamamoto","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Michiyo Murase","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324412);
