INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-hanh-phuc-ban-tho-nhi-ky', 'Ngôi Nhà Hạnh Phúc (Bản Thổ Nhĩ Kỳ)', 'Iliski Durumu Karisik (Full House)', 'https://phimimg.com/upload/vod/20231204-1/04775b999dd52f7e9b2248822b323c65.jpg', 'https://phimimg.com/upload/vod/20231204-1/0eb550de9192dde50168405c72a1b827.jpg', '<p>Aysegul (Seren Şirince) một cô gái trẻ sống trong một ngôi nhà với con mèo cưng Minak. Ayesagul khao khát trở thành một nhà văn. Bạn bè của cô lừa cô đi nghỉ mát, nơi cô gặp nam diễn viên nổi tiếng Can Tekin (Berk Oktay) và vô tình nôn vào người anh ta. Cô ấy cố gắng hết sức để xin lỗi, nhưng Can quá tức giận với cô ấy. Trong khi đó, bạn bè của cô, Ece và Efe bán nhà của cô. Aysegul trở về và phát hiện ra mình là người vô gia cư. Không còn lựa chọn nào khác, cô quyết định trở về ngôi nhà cũ của mình và yêu cầu người chủ mới cho cô ở lại đó. Chủ nhân mới của ngôi nhà được tiết lộ là Can Tiken. Sau một loạt các cuộc chiến, Can cuối cùng cho phép cô ở lại cho đến khi cô tìm thấy nơi trú ẩn nhưng vì vậy cô phải làm tất cả các công việc nhà cho Can. Can đang yêu người bạn thiết kế thời trang xinh đẹp Elif (Eda Ece) nhưng Elif lại yêu Murat. Can, Murat và Elif là bạn thời thơ ấu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 18, 2016, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Seren Şirince","avatar":""},{"name":"Berk Oktay","avatar":""},{"name":"Eda Ece","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
