INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-men-thuong', 'Cuộc Sống Mến Thương', 'Dear Zindagi', 'https://phimimg.com/upload/vod/20231219-1/3ac4e08d0af6ad146be4b1c023684e33.jpg', 'https://phimimg.com/upload/vod/20231219-1/63119a765e4de9a17c5a36b6f9f278e9.jpg', '<p>Phim Cuộc Sống Mến Thương - Dear Zindagi 2016: xoay quanh câu chuyện về cuộc tình đày lãng mạn của cặp đôi Kaira và Jug. Trong phim Kaira là một nhà quay phim tài năng và một lần tình cờ cô đã gặp được anh chàng Jug một nhà tư tưởng độc đáo, từ đó cả hai bắt đầu nảy sinh tình cảm với nhau và cuộc sống của cả hai dần trở nên ý nghĩa hơn.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Alia Bhatt","avatar":""},{"name":"Shah Rukh Khan","avatar":""},{"name":"Ali Zafar","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
