INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-menh-lenh-dac-biet', 'Lính Bắn Tỉa: Mệnh Lệnh Đặc Biệt', 'Sniper: Special Ops', 'https://phimimg.com/upload/vod/20231219-1/0e5aac1305983bb4e061ec93afb56f4d.jpg', 'https://phimimg.com/upload/vod/20231219-1/4fb8b6fe807d751d476980dc40f1757c.jpg', '<p>Phim Lính Bắn Tỉa: Mệnh Lệnh Đặc Biệt (2016): Một lực lượng đặc biệt được chỉ huy bởi Trung Sĩ Jake Chandler, được cử đến đến một ngôi làng hẻo lánh ở Afghan để giải cứu một đại biểu quốc hội Hoa kì đang bị giữ bởi phiến quân Taliban. Nhiệm vụ giải cứu thành công, nhưng Jake bị chia cách với đồng đội của mình sau trận chiến với kẻ thù vì phải ở lại giúp đỡ một binh sĩ bị thương. Trung sĩ Vic Mosby tha thiết thuyết phục Thiếu tá Jackson đồng ý cho mình quay trở lại cứu đồng đội. Nhưng vì thua thiệt về số lượng binh sĩ lẫn số lượng súng, Vic và đồng đội của mình đang phải đối mặt với hiểm nguy tột độ trước kẻ thù trong khi Jake sử dụng kĩ năng của mình để cứu lấy tất cả khỏi cái chết cận kề.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Rob Van Dam","avatar":""},{"name":"Tim Abell","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324412);
