INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('three', 'Three', 'Three', 'https://phimimg.com/upload/vod/20231215-1/cb32d2afa300b9acf460b5065b744d8a.jpg', 'https://phimimg.com/upload/vod/20231215-1/0817c97ad41caa1b6e3d6476fbf11692.jpg', '<p>Tam Nhân Hành là một bộ phim của đạo diễn Đỗ Kỳ Phong, mang đậm phong cách “lạnh lùng, tàn nhẫn, đen tối” vẫn thường thấy trong các bộ phim xã hội đen Hong Kong của ông. Tác phẩm chủ yếu kể lại câu chuyện của ba nhân vật chính: tên tội phạm nguy hiểm Đại Nghĩa (Chung Hán Lương), cảnh sát Trần Vĩ Lạc (Cổ Thiên Lạc) và nữ bác sĩ Đồng Sảnh (Triệu Vy). Trong một lần bị cảnh sát truy bắt, Đại Nghĩa bị thương ở đầu và uy hiếp các cảnh sát phải đưa mình tới bệnh viện. Tuy nhiên hắn lại từ chối chữa trị, kéo dài thời gian để đồng bọn đến giải thoát cho mình. Cùng lúc đó là cuộc giằng co giữa nữ bác sĩ Đồng Sảnh và cảnh sát Vĩ Lạc, với lương tâm của một người bác sĩ, cô quyết ra tay giúp đỡ Đại Nghĩa mặc cho Vĩ Lạc ngăn cản.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Wei","avatar":""},{"name":"Wallace Chung","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Eddie Cheung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
