INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('it', 'I.T.', 'I.T.', 'https://phimimg.com/upload/vod/20231215-1/a39cbbac6d5a18461efcd6285e3a0bb9.jpg', 'https://phimimg.com/upload/vod/20231215-1/ab244f8c3627759abd2a8a3a68b4bbc0.jpg', '<p>Mike Regan là một người đàn ông thành đạt, tự lập, có tất cả: một người vợ xinh đẹp, một cô con gái tuổi teen xinh đẹp và một “ngôi nhà thông minh” bóng bẩy, hiện đại. Nhưng anh ta sớm thấy mình trong một trò chơi mèo vờn chuột nguy hiểm chết người khi I.T. nhà tư vấn, Ed, bắt đầu sử dụng các kỹ năng của mình để theo dõi con gái của Mike và gây nguy hiểm cho gia đình, công việc kinh doanh và tính mạng của anh ấy. Trong một thế giới không có sự riêng tư và những bí mật cá nhân có thể lan truyền chỉ bằng một cú nhấp chuột, Mike cần dựa vào các mối quan hệ cũ của mình để đánh bại một loại kẻ thù mới.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Stefanie Scott","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Michael Nyqvist","avatar":""},{"name":"Anna Friel","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
