INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('si-quan-rustom', 'Sĩ Quan Rustom', 'Rustom', 'https://phimimg.com/upload/vod/20231214-1/5dd4e2644adda819735640bc55676997.jpg', 'https://phimimg.com/upload/vod/20231214-1/52efe12ea23c7e516317580491dcf3fe.jpg', '<p>Phim Sĩ Quan Rustom - Rustom 2016: là một bộ phim hình sự do Ấn Độ sản xuất xoay quanh câu chuyện về anh chàng sĩ quan hải quân Rustom Pavri và những rắc rối anh gặp phải trong chuyến về thăm gia đình. Trong phim Rustom Pavri sau khi trở về nhà anh đã phát hiện ra vợ mình đang ngoại tình với một anh chàng doang nhân có tên Vikram Makhija, quá tức giận với những gì mình phát hiện Rustom Pavri dùng súng băn chết Vikram Makhija và quyết định ra đầu thú. Liệu Vikram Makhija có phải chịu trách nhiệm trước pháp luật vì những việc mình đã làm hay không mời các bạn đón xem bộ phim Sĩ Quan Rustom - Rustom để biết rõ hơn nhé.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Ileana D''Cruz","avatar":""},{"name":"Esha Gupta","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324412);
