INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-dai-hoa-thuong-tan-truyen', 'Bố Đại Hòa Thượng Tân Truyền', 'Legend Of Bubai Monk', 'https://phimimg.com/upload/vod/20231219-1/b80143ff46dd63599f2b3cef5831f971.jpg', 'https://phimimg.com/upload/vod/20231219-1/d18846319f0ef1df4cdd9d9f1acd7690.jpg', '<p>Bố Đại Hòa Thượng Tân Truyền - Legend of Bubai Monk được cải biên từ truyền thuyết thần thoại và các câu chuyện dân gian về Bố đại hòa thượng, viết lên một câu chuyện truyền kỳ về vị hòa thượng trừ bạo an lương, hướng con người tới điều thiện. Phim lấy bối cảnh thời kỳ ngũ đại thập quốc, thiên hạ đại loạn, ở vùng Phụng Hóa của phủ Minh Châu, Trương Trọng Thiên nhặt được một đứa bé quấn trong vải bố, đặt tên là Khiết Thử. Thực chất đứa bé này chính là hóa thân của phật Di Lặc. Sau khi trưởng thành, Khiết Thử xuất gia đi tu, người thấp, mập ú, mặt mày lúc nào cũng vui vẻ, bình thường khoác áo vải bố vân du bốn phương. Ông dùng trí tuệ của mình, đấu trí đấu dũng với các thế lực tà ác, cứu giúp bách tính ra khỏi khổ ải, được người đời ca tụng.</p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 16, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tưởng Lâm Tịnh","avatar":""},{"name":"La Gia Anh","avatar":""},{"name":"Từ Cẩm Giang","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324412);
