INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ba-canh-sat-2', 'Quý Bà Cảnh Sát 2', 'Mrs. Cop 2', 'https://phimimg.com/upload/vod/20231219-1/637c65a9275b040d2cc47b4dab0a51b0.jpg', 'https://phimimg.com/upload/vod/20231219-1/cb60536801299ab40634ffa58b6cbe1f.jpg', '<p>Là câu chuyện sau khi Choi Young- Jin ( Kim Hee Ae ) cần có thời gian nghỉ việc , Ko Yoon Jung ( Kim Sung - Ryoung ) trở thành trưởng đội thám tử mới . Cô trở lại Hàn Quốc sau khi tập luyện với F.B.I. ở Mỹ. Kim Hee Ae cùng hầu hết diễn viên mùa 1 đã từ chối lời mời tiếp tục với Mrs. Cop 2. Người thay thế cho cô là mẹ Kim Tan Kim Sung Ryung, thủ vai Go Yoon Jung, một tân binh của đội phòng chống tội phạm, trở về Hàn sau quãng thời gian được FBI huấn luyện. Ngoài Kim Min Jong là người từng tham gia Mrs. Cop mùa đầu tiên, thì Kim Bum, Im Seul Ong (2AM) và Son Dam Bicũng là những cái tên được chú ý trong dự án lần này.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2016, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sung Ryoung","avatar":""},{"name":"Kim Min Jong","avatar":""},{"name":"Kim Beom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
