INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tac-chien-ngam', 'Biệt Đội Tác Chiến Ngầm', 'Vigilante Diaries', 'https://phimimg.com/upload/vod/20231214-1/daa9b9e4bd841c8a3877724c569bbbea.jpg', 'https://phimimg.com/upload/vod/20231214-1/76aed80b9f042d58d3b22b5fc5d40c1d.jpg', '<p>Phim Biệt Đội Chống Tội Phạm - Vigilante Diaries 2016: Tác phẩm phiêu lưu hành động của những anh hung màn ảnh những năm 90. Bộ phim xoay quanh một đội các đặc vụ Black-ops đấu tranh chống lại tội phạm, lãnh đạo bởi một The Vigilante - nhân vật phản anh hùng. Biệt đội thực hiện nhiệm vụ ở khắp các địa điểm từ Los Angeles đến Iraq, Armenia, Nga và Anh Quốc. Phim được đạo diễn bởi Mike Hanover.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Mewes","avatar":""},{"name":"Quinton ''Rampage'' Jackson","avatar":""},{"name":"Paul Sloan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
