INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-gia-bi-an', 'Quản Gia Bí Ẩn', 'The Caretaker', 'https://phimimg.com/upload/vod/20231212-1/eaeef76521a26eeaa1da96c0761a338f.jpg', 'https://phimimg.com/upload/vod/20231212-1/b0a212106211c416f19f5386215d02fd.jpg', '<p>Davi Carvalho là một giáo sư tâm lý học, người đã viết một cuốn sách về cách chúng ta dự báo những tổn thương trong quá khứ của mình bằng cách thức huyền bí. Một sinh viên đến từ thành phố tên Renata xuất hiện, cầu cứu em gái của anh ta, Julia. Ai đó đang làm tổn thương cô ấy và cha cô ấy tin rằng đó là hồn ma của một người chăm sóc đã sống trong tài sản của gia đình nhiều năm trước. Renata đang tìm kiếm một câu trả lời hợp lý, mời Davi đến nhà của một gia đình để tìm ra sự thật.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Haddad Aguerre","avatar":""},{"name":"Bianca Batista","avatar":""},{"name":"Roberto Arduin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
