INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-lam-nen-hanh-phuc', 'Điều Làm Nên Hạnh Phúc', 'The Love Is Coming', 'https://phimimg.com/upload/vod/20231219-1/8391ea38026431aec6d140e43c86b474.jpg', 'https://phimimg.com/upload/vod/20231219-1/c9238e03a104f71c5d400836531b572b.jpg', '<p>Điều Làm Nên Hạnh Phúc - The Love Is Coming xoay quanh Lee Eun Hee đã chịu nhiều tổn thương trong chuyện tình cảm, sau khi vết thương lòng đã lành cũng là lúc cô tìm tình yêu đích thực cho chính mình. Chuyện ngoại tình của Kim sang-ho – người đã bội bạc với Lee Eun Hee sau khi đã yên bề gia thất lại tiếp tục phản bội người vợ xinh đẹp Na Sun-young với những chiêu trò đầy toan tính khiến người xem phẫn nộ. Trải qua bao biến cố trong cuộc sống, cuối cùng tất cả đều tìm thấy được giá trị đích thực của hạnh phúc gia đình.</p>', 'Hoàn Tất (122/122)', 122, 'series', 'completed', 11, 2016, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Ji Young","avatar":""},{"name":"Lee Min Young","avatar":""},{"name":"Choi Sung Min","avatar":""},{"name":"Go Se Won","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324412);
