INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-hon-hien-linh', 'Âm Hồn Hiển Linh', 'Bridge In Clouds', 'https://phimimg.com/upload/vod/20231212-1/4a98a35da9c0d26160a17400ba9ae1e8.jpg', 'https://phimimg.com/upload/vod/20231212-1/f15ce6181ca306480cefc6e8cef7f085.jpg', '<p>Nỗi ám ảnh vì bỏ đứa con luôn khiến cho Mạnh Nghiên dây dứt không nguôi. Để kinh doanh thuận lợi, chồng cô đã thỉnh tượng kim đồng tử về, kể từ đó trong nhà liên tục xuất hiện những hiện tượng kỳ lạ. Cho đến một hôm cô gặp được hồn ma của một bé trai thì mọi bí mật bấy lâu nay của gia đình dần được vén màn.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chung Huyên","avatar":""},{"name":"Ôn Triệu Luân","avatar":""},{"name":"Hạ Vọng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
