INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-ngam-2016', 'Chiến Dịch Ngầm', 'The Bunker', 'null', 'https://phimimg.com/upload/vod/20231212-1/87bf613a8b9f0d2f4278a8c504c54bbb.jpg', '<p>Chiến Dịch Ngầm - The Bunker là bộ phim kể về thời kì đỉnh điểm của Chiến tranh Lạnh, Nga đang thực hiện một nhiệm vụ khoa học bí mật, nếu thành công, nó sẽ thay đổi tiến trình lịch sử. Nhiệm vụ, Dự án 12, cuối cùng được cho là quá nguy hiểm để tiếp tục và các nhà khoa học tham gia sẽ bị tiêu diệt. Ba nhà khoa học đã trốn thoát và Dự án 12 được niêm phong trong một boongke được canh gác cẩn mật, không bao giờ được nhìn thấy nữa ... cho đến tận bây giờ. Nhà khoa học chính của Dự án 12 giờ đây đã trở thành mục tiêu của một cuộc săn lùng trên toàn thế giới, vì anh ta là người sống sót duy nhất của nhóm Dự án 12 và là người duy nhất biết những bí mật đã được chôn giấu trong boongke. Anh ta có bí mật gì, và ai đang tài trợ cho hoạt động để đưa Dự án 12 trở lại cuộc sống và chương trình nghị sự ẩn giấu của họ là gì</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Natasha Alam","avatar":""},{"name":"Joaquin Sanchez","avatar":""},{"name":" James Cosmo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
