INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-chuoc-than', 'Tiền Chuộc Thân', 'Kidnap Capital', 'https://phimimg.com/upload/vod/20231211-1/1b9c3ac06fe5d516fb3a4bd7d5dd395b.jpg', 'https://phimimg.com/upload/vod/20231211-1/cdd04e411d90dc3757f2978858c04262.jpg', '<p>Phim Tiền Chuộc Thân - Kidnap Capital 2016: Giành nhiều giải thưởng, phim khắc họa hành trinh gian truân của những người di cư trái phép sáng Mỹ khi bị bắt cóc ngay lúc vừa đặt chân lên mảnh đất của tự do. Buộc phải trả tiền để giành lại mạng sống, họ được phép gọi điện cho người thân để vay tiền. Nhưng mãnh đời mỗi người mỗi khác, họ sẽ làm gì khi bị dồn tới đường cùng?</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Johnathan Sousa","avatar":""},{"name":"Paulino Nunes","avatar":""},{"name":"Pedro Miguel Arce","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
