INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than', 'Bạn Thân', 'My Best Friend', 'https://phimimg.com/upload/vod/20240108-1/a36eb66f6b9e30f35dcfa97f7b99311b.jpg', 'https://phimimg.com/upload/vod/20240108-1/185c1aefb12ba3fae9fbfa6e31ffacaf.jpg', '<p>Bây giờ Kristen phải điều chỉnh một cuộc sống mới ở trang trại, với những người bạn mới và một phong cách thời trang hoàn toàn khác. Với sự giúp đỡ của BFF mới của cô - một con ngựa biết nói tên Stanford, cuối cùng cô cũng phù hợp. Stanford, là một người đẹp, giúp đỡ Kristen khi họ trở nên không thể tách rời. Nhưng, đôi khi ngay cả bạn thân cũng có thể ghen tị với những người bạn khác.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Muldoon","avatar":""},{"name":"Alexis Rosinsky","avatar":""},{"name":"Catherine Bach","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
