INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-tan-bao-2016', 'Đế Chế Tàn Bạo', 'Viking Legacy', 'https://phimimg.com/upload/vod/20231211-1/90c33a681cdefb6b857118ce744c139d.jpg', 'https://phimimg.com/upload/vod/20231211-1/ecc9c09020f80529e26c9da389329e24.jpg', '<p>Phim Đế Chế Tàn Bạo - Viking Legacy 2016: Vào thời kì Cổ Đại, xuất hiện bảy cuốn giấy da được tương truyền là sẽ mang lại sức mạnh to lớn cho những ai tiếp thu được chúng. Có một lời tiên tri được truyền đại rằng một đứa trẻ sinh ra mang trong mình dòng máu hoàng gia thuần khiết một ngày nào đó sẽ chế ngự được sức mạnh đó và cai quản mọi bờ cõi. Nhiều triều đại chiến tranh suốt nhiều thời kì chỉ để giành được những cuộn giấy da đó. Để bảo vệ hòa bình, vua xứ Xen-to, cha của đứa trẻ có dòng máu hoàng gia thuần khiết, đã giao những cuộn giấy gia cho giáo hội Cơ Đốc bảo vệ. Những thế lực bên ngoài tiếp tục ra sức tấn công Đức vua để giành lại những cuộn giấy da đó.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hollie Burrows","avatar":""},{"name":"James Cooke","avatar":""},{"name":"Liam Dascombe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
