INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-nam-ay-chung-ta-gap-nhau', 'Thanh Xuân Năm Ấy Chúng Ta Gặp Nhau', 'Precious Youth', 'https://phimimg.com/upload/vod/20231219-1/171f1e25596b4d5adf4edcb726e1f49a.jpg', 'https://phimimg.com/upload/vod/20231219-1/5564bc1cc82d7ea80876631aa968cd9e.jpg', '<p>Nam sinh quậy phá Tiểu Quân nhất kiến chung tình với hoa khôi trong trường Lưu Đình, nhưng vì xích mích nên chia tay. Lưu Đình kết hôn và nhận ra chồng mình - Quách Hải Binh là người bất chấp thủ đoạn. Cô kiên quyết ly hôn. Bao nhiêu năm âm thầm bảo vệ Lưu Đình, liệu Tiểu Quân có trở về bên cô?</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 7, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Khải","avatar":""},{"name":"Lưu Thi Thi; Lý Hạo Hiên","avatar":""},{"name":"Chủng Đan Ni","avatar":""},{"name":"Lưu Đông Thẩm","avatar":""},{"name":"Tào Vệ Vũ","avatar":""},{"name":"Trương Lăng Phong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
