INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-doi-thiet-giap-thien-ha-majestic-prince-gen-thuc-tinh', 'Hạm Đội Thiết Giáp Thiên Hà Majestic Prince: Gen Thức Tỉnh', 'Ginga Kikoutai Majestic Prince Movie: Kakusei No Idenshi', 'https://phimimg.com/upload/vod/20231211-1/a15860b3caac6079ce8cb2da122b7a50.jpg', 'https://phimimg.com/upload/vod/20231211-1/17ccfb7af0673f9a8056cc78eda0fe2a.jpg', '<p>Vào nửa cuối của thế kỷ 21, con người rời Trái Đất và bắt đầu định cư trên không gian, để thích nghi với môi trường trong không gian và đối phó với những người ngoài hành tinh thù địch trên Sao Mộc, những đứa trẻ được biến đổi gen được gọi là Prince được nuôi dưỡng nhân tạo và đào tạo để trở thành phi công lái robot vũ trang AHSMB (Thiết bị chiến đấu đa năng tiên tiến tiêu chuẩn cao). Đây là câu chuyện về đội Rabbits trên hành trình chống lại người ngoài hành tinh để bảo vệ Trái Đất.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324412);
