INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-toan-phong-2', 'Thiếu Nữ Toàn Phong 2', 'The Whirlwind Girl 2', 'https://phimimg.com/upload/vod/20231219-1/72ae76a218ad91dab82aa538fddd08be.jpg', 'https://phimimg.com/upload/vod/20231219-1/07792343898b0d58541b6a03be92b764.jpg', '<p>Thiếu Nữ Toàn Phong chuyển thể từ tiểu thuyết của nhà văn Minh Hiểu Khê. Trong tác phẩm lần này, Dương Dương thủ vai đại sư huynh Nhược Bạch của một võ đường Taekwondo. Tuy bề ngoài có phần lạnh lùng, nhưng anh lại là người luôn giúp đỡ, động viên các sư đệ sư muội của mình. Trong khi đó, nữ chính của bộ phim - Bách Thảo lại là một cô gái quật cường và cực kì đam mê với môn võ Taekwondo. Bách Thảo tuy bình thường dễ bị bắt nạt nhưng có những nguyên tắc của bản thân không thể thay đổi, một khi cô đã quyết định, không gì có thể ngăn cản cô thực hiện ước mơ của mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 14, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Ngô Lỗi","avatar":""},{"name":"Triệu Viên Viên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324412);
