INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham', 'Tội Phạm', 'Criminal', 'null', 'https://phimimg.com/upload/vod/20231211-1/4a1714be3aa5680f4d750039dd737083.jpg', '<p>Kevin Costner&nbsp;vào vai Jericho Stewart, một tên tội phạm cuồng bạo lực bị giam tại nhà tù liên bang. Jericho bất ngờ được lôi khỏi song sắt bởi một sự kiện có liên quan tới an ninh toàn cầu. Điệp viên của CIA Bill Bope (Ryan Reynolds) bị thiệt mạng trong lúc đang truy lùng một hacker có biệt danh ‘The Dutchman’. Cái chết của anh khiến cho mọi manh mối về chiến dịch truy tìm hệ thống phần mềm có khả năng xâm nhập vào mạng lưới của quân đội Mỹ bị đứt quãng. Giám đốc điều hành CIA - Quaker Wells (Gary Oldman) lập tức ra lệnh sử dụng công trình khoa học đang dang dở của tiến sĩ Franks (Tommy Lee Jones) để cứu vãn tình thế. Jericho được chọn vì tình cờ là người có não bộ phù hợp với yêu cầu của quy trình chuyển giao trí nhớ. Vận may đã đến, những kí ức từ não bộ đang chết dần của Bill được chuyển sang và làm hắn dần trở thành một con người khác. Song, vẫn có những kẻ trong bóng tối biết được việc này. Chúng lập tức tiến hành một cuộc truy lùng đẫm máu nhằm vào Jericho và những người liên quan trong đó Jill (Gal Gadot), vợ Bill và cô con gái nhỏ.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Gal Gadot","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Ryan Reynolds","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
