INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-mu-2', 'Điểm Mù 2', 'Blindspot 2', 'https://phimimg.com/upload/vod/20231219-1/7316d2c1cb89dc7e6d798d706d0375f3.jpg', 'https://phimimg.com/upload/vod/20231219-1/22fbf524d81b1c0bcfbc78fcf6b7822a.jpg', '<p>Bộ phim tập trung vào cô gái mang nhiều hình xăm trên cơ thể Jane Doe (Jaimie Alexander thủ vai), hoàn toàn mất trí nhớ và không biết danh tính của mình. Thanh tra của FBI là Kurt Weller (Sullivan Stapleton thủ vai) phát hiện ra rằng mỗi hình xăm trên người Jane là đầu mối của một vụ án đang và sắp diễn ra.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 18, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jaimie Alexander","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"Ashley Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
