INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tat-ca-trong-mot', 'Tất Cả Trong Một', 'All At Once', 'https://phimimg.com/upload/vod/20240102-1/f0da6fe7279761b7f7ed7721c5e76a5b.jpg', 'https://phimimg.com/upload/vod/20240102-1/33016ba553b1db102da5e726eb6c6654.jpg', '<p>Cuộc sống của người họa sĩ trẻ đầy tiềm năng tại New York đã hoàn toàn thay đổi khi thảm kịch 9/11 diễn ra cướp đi mạng sống của hai người bạn thân nhất của anh, và anh nhận nuôi 2 cô con gái của cặp vợ chồng đáng thương đó. 11 năm sau, không thể trang trải cuộc sống nuôi 2 cô gái như con ruột của mình bằng việc dạy nghệ thuật tại trường tiểu học với chi phí sinh hoạt quá đắt đỏ tại New York, anh đã quyết định đưa hai cô con gái rời khỏi nơi mà họ vẫn sinh sống trong suốt những năm qua và trở về Buffalo nơi anh sinh ra và lớn lên. Gia đình bất thường này khi đó phải đối mặt với sự thay đổi, môi trường mới, một hành trình mới và phải học cách hòa nhập với cuộc sống mới đồng thời khám phá bản thân mình.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jon Abrahams","avatar":""},{"name":"Martin Abrahams","avatar":""},{"name":"Med Abrous","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
