INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-life-as-a-courgette', 'My Life as a Courgette', 'Ma Vie De Courgette', 'https://phimimg.com/upload/vod/20231210-1/c4003280b33cc5305aa3946eb20bc475.jpg', 'https://phimimg.com/upload/vod/20231210-1/035e1969bb3bce5b4ed4255f7774427e.jpg', '<p>Courgette (Zucchini) là một biệt danh hấp dẫn cho một cậu bé 9 tuổi. Mặc dù câu chuyện độc đáo của ông là phổ quát đáng ngạc nhiên. Sau sự biến mất của mẹ mình, Courgette được kết bạn với một sĩ quan cảnh sát Raymond, người đồng hành cùng anh ta đến ngôi nhà nuôi dưỡng mới của mình tràn ngập những đứa trẻ khác ở trẻ mồ côi. Lúc đầu, ông đấu tranh để tìm vị trí của mình trong sự kỳ lạ này, đôi khi, môi trường thù địch. Tuy nhiên, với sự giúp đỡ của Raymond và những người bạn mới tìm thấy của anh, Courgette cuối cùng cũng học cách tin tưởng và có thể tìm thấy tình yêu đích thực.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
