INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-linh', 'Khí Linh', 'Weapon And Soul', 'https://phimimg.com/upload/vod/20231203-1/72dd6d86b712720b5b53e53d02b65e56.jpg', 'https://phimimg.com/upload/vod/20231203-1/3fbe2a6ffb63e3e35dd97364b245e435.jpg', '<p>Phim Khí Linh - Weapon And Soul 2016: Cậu thiếu niên Mạc Minh mồ côi cha từ nhỏ. Trong một lần tình cờ, cậu vô tình bị cuốn vào cuộc tranh đấu giữa hai phái chế ngự linh khí là Thiên Công Hội và Cửu Khanh, đồng thời phát hiện ra sự tồn tại của khí linh. Cậu không ngờ rằng loại vũ khí cổ xưa này lại có thể hóa thành một cô gái xinh đẹp, có khả năng chiến đấu. Đối mặt với cuộc chiến đầy cam go và quyết liệt kia, rốt cuộc cậu sẽ lựa chọn ra sao?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 9, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peng Yu Chang","avatar":""},{"name":"Chen Ruoxuan","avatar":""},{"name":"Sunxue Ning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324412);
