INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-giu-tinh-yeu', 'Giam Giữ Tình Yêu', 'Submission', 'https://phimimg.com/upload/vod/20231211-1/491f1e558c9ba98304b0e970887d802b.jpg', 'https://phimimg.com/upload/vod/20231211-1/09e265a58f83e29456a740501bc5554c.jpg', '<p>Thuộc series tình yêu ngang trái. Nguyễn Thanh Di vừa về nước và đang có một cuộc sống độc thân. Một ngày nọ Nhậm Hào Danh đưa người đến gõ cửa và dọn sạch nhà của cô. Thì ra mẹ của Nguyễn Thanh Di đã thế chấp ngôi nhà của cô cho Nhậm Hào Danh. Mẹ của cô từng đánh cắp ý tưởng quảng cáo của mẹ Nhậm Danh Hào, khiến mẹ anh phải gánh chịu tội danh ăn cắp, cuối cùng chết do trầm cảm. Sau khi biết được sự việc, Nhậm Danh Hào quyết tâm trả thù cho mẹ, nhưng lại vô tình phải lòng Thanh Di</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Wei Lun","avatar":""},{"name":"Phùng Chỉ Mặc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
