INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-cua-quy', 'Khế Ước Của Quỷ', 'Simple Man', 'https://phimimg.com/upload/vod/20231219-1/0a9c0638dbd09fdc3e506f45aa97d4b5.jpg', 'https://phimimg.com/upload/vod/20231219-1/d8076a53c4b17749649ec59db60d7559.jpg', '<p>Bộ phim xoay quanh 4 nhân vật bình thường, tình cờ làm cuộc trao đổi với ác quỷ, đổi lại họ nhận được một số siêu năng lực nhỏ, có thể thỏa mãn yêu cầu của mỗi người. Nhưng sau đó họ phát hiện đằng sau những siêu năng lực này là một âm mưu lớn khác...</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 9, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lisi Yang","avatar":""},{"name":"Chen Siyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324412);
