INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ve-si-xinh-dep', 'Nữ Vệ Sĩ Xinh Đẹp', 'Hot Girl', 'https://phimimg.com/upload/vod/20231219-1/3a8b64f755201659e8a7f892a0a43a09.jpg', 'https://phimimg.com/upload/vod/20231219-1/b5151a2022d26be1fe0ea3e34a7600c4.jpg', '<p>Bộ phim có nội dung kể về Quan Tiểu Địch một cô gái xinh đẹp bốc lửa, cơ duyên trùng hợp ngẫu nhiên tham gia một khóa tập huấn vệ sĩ tại một trung tâm đào tạo vệ sĩ, cùng quen biết với những cô gái trẻ tuổi xinh đẹp tài năng khác. Trải qua quá trình rèn luyện gian khổ, các cô gái bị thử thách không chỉ là khả năng thể chất, mà cả sự tự tôn và nhân cách. Nhóm năm cô gái của Quan Tiểu Địch trong kỳ thi tốt nghiệp đã gặp một nhiệm vụ trong đó phải có một người hy sinh tư cách dự thi của bản thân mới có thể hoàn thành. Quan Tiểu Địch đã tự nguyện hy sinh để nhóm vượt qua. Kết quả khi cô gái kiên cường đang khóc nhè vì trượt tốt nghiệp thì huấn luyện viên cười bảo hy sinh bản thân mới là thử thách quan trọng nhất. Kết quả từ những cô gái nổi loạn không hiểu chuyện đã dần trưởng thành, tốt nghiệp khóa huấn luyện, bắt đầu truyền kỳ về những nữ vệ sỹ gợi cảm.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 10, 2016, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
