INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-kinh-hoang', 'Vụ Nổ Kinh Hoàng', 'Deadly Inferno', 'https://phimimg.com/upload/vod/20231230-1/3dfa72d158c8bedb3e13187a4f7d8f85.jpg', 'https://phimimg.com/upload/vod/20231230-1/bf7aac3d38ae7427565ab4ec94d3f2b3.jpg', '<p>Vụ nổ kinh hoàng diễn ra tại tầng 8 trên tòa cao ốc. Tất cả mọi người đều nỗ lực giành sự sống cho mình. Bộ phim ngợi ca những người lính cứu hỏa luôn đối đầu những cái chết không hề được báo trước.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlotte Arnold","avatar":""},{"name":"Stephen Bogaert","avatar":""},{"name":"Jodie Dowdall","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
