INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock', 'Thám Tử Sherlock', 'Sherlock: The Abominable Bride', 'https://phimimg.com/upload/vod/20231230-1/af5926bfd658ff7d29cfd5767f8c2826.jpg', 'https://phimimg.com/upload/vod/20231230-1/20ade62eb24d8769ad443b8ddf898e66.jpg', '<p>Tưởng tượng mình trở lại vào những năm 1890, Sherlock được thanh tra Lestrade ghé thăm sau khi mới cưới Emelia RicoLetti, dường như đã giết chết mình ở nơi công cộng, giết chồng chồng Thomas trước mặt các nhân chứng trước khi biến mất. Vài tháng sau, Holmes được tiếp cận bởi Lady Carmichael, người nói với anh rằng chồng Sir Eustace đã bị Emelia đe dọa, những người sau đó dường như đi với anh. Với một đạo sai xâm nhập của anh ta, Holmes cố gắng giải quyết sự đố kị, với sự giúp đỡ bất ngờ từ vợ Mary của Watson và bằng chứng về một âm mưu liên quan đến một nửa dân số của đất nước.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
