INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-sherlock', 'Thám Tử Sherlock', 'Sherlock: The Abominable Bride', 'thám tử sherlock sherlock: the abominable bride  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('morgan', 'Morgan', 'Morgan', 'https://phimimg.com/upload/vod/20231211-1/647b006061d3049abd57e748e8a557f3.jpg', 'https://phimimg.com/upload/vod/20231211-1/67ab04d10bb457969564b63b88b8e95f.jpg', '<p>Lee Weathers là một chuyên gia quản lý rủi ro đối với Công ty Kỹ thuật di truyền Synsect. Cô ấy đến một khu vực nông thôn tổ chức dự án L-9 của mình, một người nhân tạo với DNA tổng hợp công nghệ nano có tên Morgan. Sinh vật sinh học lai với khả năng đưa ra quyết định tự trị và phản ứng cảm xúc tinh vi thông minh hơn con người và trưởng thành nhanh chóng, đi bộ và nói chuyện trong vòng một tháng và một thiếu niên mặc dù đã năm tuổi ..</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
