INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-ali-va-nino', 'Chuyện Tình Ali Và Nino', 'Ali And Nino', 'https://phimimg.com/upload/vod/20231211-1/5153e61a99f46b9591727695a983e245.jpg', 'https://phimimg.com/upload/vod/20231211-1/06b8910042404bede36b4ebe0102c7b7.jpg', '<p>Phim Chuyện Tình Ali Và Nino - Ali And Nino 2016: Kể về chuyện tình giữa Ali Khan Shirvanshir là con trai nối dõi của một gia đình quý tộc theo đạo Hồi ở Azerbaijan, còn Nino Kipiani là công chúa xinh đẹp danh giá của Gruzia theo đạo Thiên chúa. Ali và Nino cùng sống tại thủ đô dầu mỏ của Azerbaijan, nơi hội tụ của nhiều nền văn hóa. Bất chấp sự khác biệt về tôn giáo, họ yêu nhau từ khi còn trẻ và Ali xác định bằng mọi giá lấy được Nino ngay khi cô rời trường.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Adam Bakri","avatar":""},{"name":"María Valverde","avatar":""},{"name":"Mandy Patinkin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324412);
