INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-gia-noel-xau-tinh-2', 'Ông Già Noel Xấu Tính 2', 'Bad Santa 2', 'https://phimimg.com/upload/vod/20231211-1/45ce202cb6b40dbd8f6f68a0ba0fd0ca.jpg', 'https://phimimg.com/upload/vod/20231211-1/8af95d3c2b1a9a0cf02f00f81278ed68.jpg', '<p>Bad Santa 2 là bộ phim tâm lý tội phạm hài hước của Mỹ ra mắt vào năm 2016. Nối tiếp thành công của phần 1, Bad Santa 2 tiếp tục theo chân Willie và Marcus, hai tên lừa đảo chuyên đóng giả ông già Noel và yêu tinh trong một phi vụ mới. Bối cảnh phim diễn ra 13 năm sau phần phim đầu tiên, cuộc sống của Willie hiện đang trở nên vô cùng tồi tệ sau khi anh phát hiện ra bản thân mắc chứng trầm cảm nặng. Mặc dù đã cố gắng để tự sát thế nhưng hết lần này đến lần khác Willie đều thất bại. Một ngày nọ, Willie tình cờ gặp được Thurman “The Kid” Merman, cháu của Willie và là một nhân viên 21 tuổi làm việc tại cửa hàng bánh sandwich Hungry Hoagies, đến thăm.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Brett Kelly","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Christina Hendricks","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
