INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-dalida', 'Tôi Là Dalida', 'Dalida', 'https://phimimg.com/upload/vod/20231211-1/78ad872d7c218281c196f3df74b21d6c.jpg', 'https://phimimg.com/upload/vod/20231211-1/439ae557faac8cc8b98f39dda014128b.jpg', '<p>Phim Tôi Là Dalida 2017: mô tả lại cuộc đời của nữ danh ca huyền thoại Dalida, với cuộc sống nội tâm khá phức tạp của bà. Chào đời năm 1933 tại Le Caire (Ai Cập), Iolanda Gigliotti lần đầu tiên xuất hiện tại hí viện Olympia 1956 với nghệ danh Dalida đã gây được ấn tượng với ban giám khảo. Kết hôn với Lucien Morisse và bà đã nhanh chóng nổi tiếng qua ca khúc Bambino. Dù sự nghiệp ngày càng rực rỡ, nhưng Dalida vẫn mãi vô vọng tìm gặp một tình yêu đích thực. Cô đơn đã khiến bà tự tìm đến cái chết vào năm 1987.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sveva Alviti","avatar":""},{"name":"Riccardo Scamarcio","avatar":""},{"name":"Jean-Paul Rouve","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
