INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-maigret-cam-bay', 'Thám Tử Maigret: Cạm Bẫy', 'Maigret Sets A Trap', 'https://phimimg.com/upload/vod/20231211-1/9d58831484484372412116227b40d2cb.jpg', 'https://phimimg.com/upload/vod/20231211-1/5ebd370faa5a5f4bc3a9f7fdfc822248.jpg', '<p>Over a five month period in 1955 four women are stabbed to death in Montmartre after dark, a prostitute and a midwife among them - women with nothing in common beyond being brunette. Justice minister Morel leans on chief Inspector Maigret to catch the murderer and Maigret sets a trap, using policewoman Marthe Jusserard as a decoy. She survives an attack, sartorial evidence leading to married mothers boy Marcel Moncin, whom Maigret arrests. However whilst Moncin is in custody there is a further murder and Maigret looks to Moncins family to help solve the murders.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rowan Atkinson","avatar":""},{"name":"Leo Staar","avatar":""},{"name":"Shaun Dingwall","avatar":""},{"name":"Alexander Campbell","avatar":""},{"name":"Beth Cooke","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
