INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-khong-gioi-han', 'Star Trek: Không Giới Hạn', 'Star Trek Beyond', 'null', 'https://phimimg.com/upload/vod/20231211-1/717c71c75370d41396aa3d8893d2c39f.jpg', '<p>Sau khi một người ngoài hành tinh muốn báo thù Starfleet phá hủy tàu Enterprise và bỏ phi hành đoàn ở một hành tinh hoang, thuyền trưởng Kirk phải ngăn vụ tấn công khác.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Zachary Quinto","avatar":""},{"name":"Zoe Saldaña","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324412);
