INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-soi', 'Hoàng Tử Sói', 'Prince Of Wolf', 'https://phimimg.com/upload/vod/20231208-1/b0c4bc751dc5564056ef788e4dc3a65b.jpg', 'https://phimimg.com/upload/vod/20231208-1/fd8f14bdc2071f323899e4242a101773.jpg', '<p>Chàng trai nhỏ Zhe- Ming bị lạc trong rừng sâu trong chuyến du lịch gia đình, trong khi đang đi loanh quay ,cậu vô tình cứu một conn sói cái ,vì vậy thủ lĩnh của bầy sói quyết định sẽ chăm sóc cho cậu. Từ ngày đó, cậu sống chung với bầy sói đã cứu mình. Mimi,một nhiếp ảnh gia nghiệp dư, đã đến Núi Sói để tìm kiếm phong cảnh đẹp. Nhưng cô lại bắt gặp Zhe- Ming đang trần chuồng dưới dòng suối. Không may cô vô tình ngã xuống thung lũng nhỏ và được cứu bởi Zhe-Ming,người mang cô quay lại hang động của mình. Zhe-Ming chắc chắn rằng Mimi là sói cái, bạn tình của mình và họ thuộc về nhau. Vì cô, anh quyết định rời khỏi Núi Sói, và hai người bắt đầu hành trình cùng với nhau , kéo theo hàng tấn những chuyện dở khóc dở cười.<br/>&nbsp;</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 17, 2016, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Amber An","avatar":""},{"name":"Derek Chang","avatar":""},{"name":"Samuel Gu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
