INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-cua-tuong-lai-phan-1', 'Huyền Thoại Của Tương Lai (Phần 1)', 'DC''s Legends of Tomorrow (Season 1)', 'https://phimimg.com/upload/vod/20231203-1/2ac0f387e302ece491d0ab6a5b1920ee.jpg', 'https://phimimg.com/upload/vod/20231203-1/ab7e404efbb0e09f81ad96a2e9b374ea.jpg', '<p>Một vị Chủ thời gian bí ẩn đến từ tương lai tập hợp một nhóm không tưởng gồm các siêu anh hùng và ác nhân để cứu thế giới khỏi tay một kẻ xấu hùng mạnh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Caity Lotz","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Brandon Routh","avatar":""},{"name":"Franz Drameh","avatar":""},{"name":"Amy Pemberton","avatar":""},{"name":"Dominic Purcell","avatar":""},{"name":"Maisie Richardson-Sellers","avatar":""},{"name":"Nick Zano","avatar":""},{"name":"Arthur Darvill","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Tala Ashe","avatar":""},{"name":"Adam Tsekhman","avatar":""},{"name":"Christina Brucato","avatar":""},{"name":"Simon Merrells","avatar":""},{"name":"Nils Hognestad","avatar":""},{"name":"Jes Macallan","avatar":""},{"name":"Keiy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324412);
