INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mythica-ke-sat-than', 'Mythica: Kẻ Sát Thần', 'Mythica: The Godslayer', 'https://phimimg.com/upload/vod/20231210-1/6258972cf7c717f2d5b8392804a97286.jpg', 'https://phimimg.com/upload/vod/20231210-1/5a0a27a2989e918ecf76e5f12621aa7d.jpg', '<p>Khi binh đoàn thây ma của Lich King tàn phá thế giới, một nữ phù thủy trẻ tuổi bị nguyền rủa dấn thân vào nhiệm vụ lấy vũ khí từ các vị thần. Nhưng khi tham gia cùng kẻ thù truyền kiếp của mình trong một nỗ lực tuyệt vọng để cứu thế giới, cô ấy phải phục hồi những điều tốt đẹp trong bản thân trước khi bạn bè của cô ấy chết hết, và đánh bại Lich King trước khi các vị thần bị tiêu diệt và thế giới mãi mãi bị nô lệ.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristian Nairn","avatar":""},{"name":"Matthew Mercer","avatar":""},{"name":"Adam Johnson","avatar":""},{"name":"Melanie Stone","avatar":""},{"name":"Kevin Sorbo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
