INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-cong-ly', 'Chiến Binh Công Lý', 'Code Of Honor', 'null', 'https://phimimg.com/upload/vod/20231210-1/f487b3b9b4e2c1df9e38672d551e4220.jpg', '<p>Bộ phim Chiến Binh Công Lý – The Code Of Honor xoay quanh câu chuyện của đại tá Robert Sikes khi anh đang thực thi nhiệm vụ diệt trừ tội phạm trong thành phố của mình. Anh hoạt động ngầm một mình để diệt trừ những bằng đảng đường phố, các băng trộm cướp, và những chính trị gia quan liêu. Cấp dưới trước đây của anh là William Porter đã hợp tác với cảnh sát địa phương để ngăn cản cựu chỉ huy của mình tiếp tục thực hiện những phi vụ trừ gian diệt ác vượt giới hạn của một cảnh sát địa phương.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Craig Sheffer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
