INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cuoc-song', 'Hành Trình Cuộc Sống', 'My Life As A Zucchini', 'https://phimimg.com/upload/vod/20231209-1/85046e44c14da0375522f871d932d750.jpg', 'https://phimimg.com/upload/vod/20231209-1/3b26362e8c451e86252b3a74281e747c.jpg', '<p>Dựa trên cuốn tiểu thuyết mang tên Autobiographie d’une courgette, phim kể về cậu bé tên Zucchini. Sau cái chết bất ngờ của mẹ, Zucchini bị ép chuyển đến một ngôi nhà tình thương. Ở đây, cậu bé làm quen với những người bạn cũng có cuộc đời bi kịch. Cuộc phiêu lưu của cậu bé tóc xanh Zucchini sẽ khiến người xem xúc động rơi nước mắt với những sự thật đau buồn và nhiều bài học thấm đẫm tình người.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gaspard Schlatter","avatar":""},{"name":"Sixtine Murat","avatar":""},{"name":"Paulin Jaccoud","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324412);
