INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ham-ma-quai', 'Căn Hầm Ma Quái', '10 Cloverfield Lane', 'https://phimimg.com/upload/vod/20231209-1/909f80bafe6deec609decac2e01cfccd.jpg', 'https://phimimg.com/upload/vod/20231209-1/9546530234a016beac6fa19e5bf38fc5.jpg', '<p>Sau khi gặp tai nạn xe hơi, một phụ nữ được giữ trong một nơi trú ẩn cùng với hai người đàn ông, họ cho rằng thế giới bên ngoài bị ảnh hưởng bởi một vụ tấn công hóa học trên diện rộng.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"John Goodman","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Douglas M. Griffin","avatar":""},{"name":"Suzanne Cryer","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
