INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-giam-sieu-nang-luc-2', 'Thái Giám Siêu Năng Lực 2', 'Super Eunuch 2', 'https://phimimg.com/upload/vod/20231208-1/a04f3fbc1bb79a1012705171694fb7ea.jpg', 'https://phimimg.com/upload/vod/20231208-1/6b2d64aa7b458c8e558c5e421b376c38.jpg', '<p>Phim Thái Giám Siêu Năng Lực 2 - Super Eunuch 2 (2016): là phiên bản nhái hài hước của &nbsp;Lộc Đỉnh Ký . Vi Tiểu Bảo từ tên lông bông bỗng chốc thành thái giàm và lập được nhiều đại công nhờ khả năng từ trên trời rơi xuống. Với sự ngạo mạng và khả năng &nbsp;điếc không sợ súng của mình Tiểu Bảo đã giúp Khang Hy tiêu diệt đại gian thần Ngao Bái và được gã Song Nhi cho mình.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bành Ngu Khư","avatar":""},{"name":"Hoàng Bằng","avatar":""},{"name":"Chu Gia Huy","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324412);
