INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-truong-vo-luat', 'Cảnh Trưởng Vô Luật', 'Career', 'https://phimimg.com/upload/vod/20231207-1/3d5a684b0872773617d2a6250352b862.jpg', 'https://phimimg.com/upload/vod/20231207-1/36cfd1889d98636dcb08658cda75651d.jpg', '<p>Vào cái ngày có tân Cảnh Trưởng tới nhậm chức ở đồn Kitamachi, các cán bộ nơi đây đang chuẩn bị chào đón anh. Thì lúc đó, một chiếc xe buýt bị một người đàn ông có dao cướp và uy hiếp các hành khách trên xe. Lính mới Aikawa Minori bị một hành khách đá ra ngoài khi cô gắng lên chuyến xe buýt đó.Cô bám theo chiếc xe buýt bằng taxi, nhưng chiếc xe buýt lại hướng thẳng về phía đồn Kitamachi. Vì một lý do kỳ lạ gì mà tên cướp đã tự tới đồn trình diện. Sau đó Minori đã còng tay người cản trở mình thi hành công vụ. Nhưng người đàn ông mà cô còng tay đó, lại chính là tân Cảnh Trưởng, Toyama Kinshiro.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miori Takimoto","avatar":""},{"name":"Hiroshi Tamaki","avatar":""},{"name":"Masahiro Takashima","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
