INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-co-loi-loi-do-ban-than', 'Tình Yêu Không Có Lỗi, Lỗi Do Bạn Thân', 'Club Friday - The Series 6: Best Friend', 'https://phimimg.com/upload/vod/20231207-1/dbc6674f3fb763dc733ae3cbbff91731.jpg', 'https://phimimg.com/upload/vod/20231207-1/d5b4fa9dc6378076b26311a1db975c3d.jpg', '<p>Xoay quanh niềm tin vào tình bạn và tình yêu. Katun và Lee là đôi bạn thân hơn 20 năm, cùng nhau chia sẻ và vượt qua bao khó khăn. Nhưng rồi sự xuất hiện của một chàng trai đã khiến cả hai trở mặt và coi nhau như kẻ thù, tìm mọi cách hãm hại đối phương nhằm giành lấy tình yêu của chàng trai đó.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 18, 2016, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Golf Pichaya Nitipaisalkul","avatar":""},{"name":"Wanida Termthanaporn","avatar":""},{"name":"Saiparn Apinya Sakuljaroensuk","avatar":""},{"name":"Bie Thassapak Hsu","avatar":""},{"name":"Took Chanokwanun Rakcheep","avatar":""},{"name":"Tom Phollawat Manuprasert","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
