INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ham', 'Căn Hầm', '10 Cloverfield Lane', 'https://phimimg.com/upload/vod/20231026-1/f2a08096d327da98be2a1a373416c719.jpg', 'https://phimimg.com/upload/vod/20231209-1/9546530234a016beac6fa19e5bf38fc5.jpg', '<p>Câu chuyện bắt đầu bằng vụ tai nạn khốc liệt xảy đến với Michelle khiến cô lịm đi trong xe ô tô. Khi tỉnh dậy, Michelle phát hiện mình đang được điều trị vết thương và bị giam trong một căn hầm cùng với hai người đàn ông. Howard – một trong số họ - nói với cô rằng thế giới bên ngoài đang chịu một thảm họa kinh hoàng, và rằng lựa chọn ở lại căn hầm sẽ giúp bảo toàn tính mạng. Không tin những lời Howard nói, Michelle tìm mọi cách trốn thoát để tìm ra sự thật.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"John Goodman","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Douglas M. Griffin","avatar":""},{"name":"Suzanne Cryer","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Sumalee Montano","avatar":""},{"name":"Frank Mottek","avatar":""},{"name":"Jamie Clay","avatar":""},{"name":"Kayla Bechor","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
