INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('4-nam-2-chang-1-tinh-yeu', '4 Năm, 2 Chàng, 1 Tình Yêu', '4 Nam, 2 Chang, 1 Tinh Yeu', 'https://phimimg.com/upload/vod/20231210-1/bc23395748d922a4c62667ab211d379a.jpg', 'https://phimimg.com/upload/vod/20231220-1/90da627dcc1cdac85000c843e81856ba.jpg', '<p>Bộ phim kể về bộ ba Quỳnh (Midu), Tuấn (Harry Lu) và Thành (Anh Tú). Cả 3 đã có một tình yêu thật đẹp, trong sáng và giản dị từ những ngày còn học chung trường. Tuy nhiên một biến cố lớn đã xảy ra: Ngày Quỳnh nhận ra tình cảm mà mình dành cho Tuấn cũng là ngày Tuấn mất! 4 năm sau, Thành trở thành một diễn viên nổi tiếng, Quỳnh là quản lý của anh. Và khi họ đang chuẩn bị quen nhau thì Tuấn đột nhiên xuất hiện. Câu chuyện cũ bất ngờ sống lại cùng với những bí mật tưởng chừng như sẽ được giấu kín đến suốt đời… Với thông điệp: Hãy yêu, trân trọng và sống thật với chính những cảm xúc sâu thẳm bên trong trái tim.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Ngọc Trai","avatar":""},{"name":"Harry Lu","avatar":""},{"name":"MiDu","avatar":""},{"name":"Anh Tú","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324412);
