INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phim-truong-ma', 'Phim Trường Ma', 'Spooky Scene', 'https://phimimg.com/upload/vod/20231210-1/9be626db22426fa9b969dc03a785f8e1.jpg', 'https://phimimg.com/upload/vod/20231210-1/b397d4ad32ef4a20bfe6749deb1ee33f.jpg', '<p>Phim Trường Ma là câu chuyện xoay quanh một đoàn phim về đề tài “người đột biến” gặp phải những hiện tượng kỳ quái khi tiến hành quay phim, như sự dự báo về một lời nguyền sẽ ứng nghiệm trên bối cảnh bỏ hoang mà cả ekip đang thực hiện. Đỉnh điểm của sự việc là khi nữ diễn viên chính (Ninh Dương Lan Ngọc) đột nhiên mất tích bí ẩn, giống hệt như bi kịch đã từng xảy ra với diễn viên đàn chị trước đó. Những hồn ma liệu có tồn tại, lời nguyền có đang xảy ra và số phận nào sẽ dành cho nữ chính của bộ phim kinh dị này?</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Ninh Dương Lan Ngọc","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Mạc Văn Khoa","avatar":""},{"name":"Lê Dương Bảo Lâm","avatar":""},{"name":"Phan Mạnh Quỳnh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
