INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hau-gai', 'Cô Hầu Gái', 'The Handmaiden', 'https://phimimg.com/upload/vod/20231208-1/3267a4c3df7a21cd49862a913ffb4e98.jpg', 'https://phimimg.com/upload/vod/20231208-1/3c5cf248754115dd162e7f5e103ce8b3.jpg', '<p>Những năm 1930 tại Hàn Quốc, trong thời kỳ chiếm đóng của Nhật Bản, một cô gái mới (Soisee) được thuê làm người thừa kế một người thừa kế Nhật Bản (Hideko) sống một cuộc sống hẻo lánh trên một bất động sản nông thôn lớn với chú độc đoán của cô (Kouzuki). Nhưng người giúp việc có một bí mật. Cô là một kẻ móc túi được tuyển chọn bởi một kẻ lừa đảo tạo dáng như một người Nhật Bản để giúp anh ta dụ dỗ người phụ nữ để trốn tránh anh ta, cướp cô ấy trong vận may của cô ấy và khóa cô ấy trong một nhà điên. Kế hoạch dường như tiến hành theo kế hoạch cho đến khi Soopee và Hideko khám phá một số cảm xúc bất ngờ.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
