INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khong-can-suc', 'Cuộc Chiến Không Cân Sức', 'Mole Of Life', 'https://phimimg.com/upload/vod/20231208-1/6c6ac23f8b8695529deb77a7abbedbdf.jpg', 'https://phimimg.com/upload/vod/20231208-1/40f900bda74e8c34b2ad7c0cd02b266a.jpg', '<p>Phim Cuộc Chiến Không Cân Sức - Mole Of Life 2016: kể về một nhóm xã hội đen muốn phá hoại một cuộc họp báo quan trọng được tổ chức ở Đài Bắc. Cảnh sát đã phát hiện âm mưu này và nỗ lực hết mình phá án để cuộc họp báo diễn ra tốt đẹp.</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Truyền Nhất","avatar":""},{"name":"Đậu Trí Khổng","avatar":""},{"name":"Sử Đại Tây","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
