INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bahamut-yeu-nhat-bat-bai', 'Bahamut Yếu Nhất Bất Bại', 'Undefeated Bahamut Chronicle, Saijaku Muhai no Bahamut', 'https://phimimg.com/upload/vod/20231207-1/e200ebcd74f0be741b81b50ab7a4c341.jpg', 'https://phimimg.com/upload/vod/20231207-1/0920886108b3cdf462b62d3ae5cc8f24.jpg', '<p>Lux, vị hoàng tử từ Cựu Đế Chế, nơi bị tiêu diệt từ 5 năm trước trong một cuộc đảo chính. Vô tình được gọi tới Học Viện Kỵ Sĩ Hoàng Gia nhưng điểm đáp của anh lại chính vào nhà tắm nơi anh gặp gỡ một cô gái cũng chính là công chúa của Tân Quốc. Chuyện gì đến cũng đến, cuộc sống của chàng hoàng tử số hưởng và những cô gái trong học viện nữ sinh đó chính thức bắt đầu. Cùng lúc đó là những sự kiện đang ngắm ngầm diễn ra bên ngoài Tân Quốc và truyền thuyết về Hắc Kỵ Sĩ người sở hữu Bahamut (Hắc Thần Trang Cơ Long) dần dần hé lộ. Chuyện gì sẽ tiếp tục xảy đến với chàng cựu hoàng tử nọ và cả Tân Quốc ?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
