INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oc-sen-cung-co-tinh-yeu', 'Ốc Sên Cũng Có Tình Yêu', 'Ốc Sên Cũng Có Tình Yêu', 'https://phimimg.com/upload/vod/20231219-1/108fb674ba4d0dd83e22e3c08f670f7e.jpg', 'https://phimimg.com/upload/vod/20231219-1/f1a4aa4f339964bf22a8690cab64b58b.jpg', '<p>Phim chuyển thể từ tiểu thuyết cùng tên vô cùng đình đám của Đinh Mạc. Phim là chuỗi các vụ án bí hiểm được phá một cách tài tình của chàng cảnh sát siêu đẳng Quý Bạch cùng cô thực tập sinh trẻ vô cùng thông minh Hứa Hủ. Đan xen trong đó là những câu chuyện tình cảm vô cùng lãng mạn và lôi cuốn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Tử Văn","avatar":""},{"name":"Vương Khải","avatar":""},{"name":"Từ Duyệt","avatar":""},{"name":"Triệu Viên VIện","avatar":""},{"name":"Võ Tiểu Vũ","avatar":""},{"name":"Trương Diễm","avatar":""},{"name":"Trương Hiểu Khiêm","avatar":""},{"name":"Hoắc Á Minh.","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324412);
