INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oc-sen-cung-co-tinh-yeu', 'Ốc Sên Cũng Có Tình Yêu', 'Ốc Sên Cũng Có Tình Yêu', 'ốc sên cũng có tình yêu ốc sên cũng có tình yêu vương tử văn vương khải từ duyệt triệu viên viện võ tiểu vũ trương diễm trương hiểu khiêm hoắc á minh. ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-trong-gio', 'Bóng Ma Trong Gió', 'Under The Shadow', 'https://phimimg.com/upload/vod/20231208-1/45dd06d12f69ed100828dc4bd507e3e0.jpg', 'https://phimimg.com/upload/vod/20231208-1/b1f7a95e63f8127521dbfb5f515b2d98.jpg', '<p>Sau khi tòa nhà của Shideh bị trúng tên lửa trong Chiến tranh Iran-Iraq, một người hàng xóm mê tín cho rằng tên lửa đã bị nguyền rủa và có thể mang theo những linh hồn Trung Đông độc ác. Cô tin rằng một thế lực siêu nhiên trong tòa nhà đang cố gắng chiếm hữu con gái Dorsa của cô, và cô không còn lựa chọn nào khác ngoài việc đối đầu với những thế lực này nếu muốn cứu con gái và chính mình.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Narges Rashidi","avatar":""},{"name":"Avin Manshadi","avatar":""},{"name":"Bobby Naderi","avatar":""},{"name":"Ray Haratian","avatar":""},{"name":"Hamid Djavadan","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
