INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nguoi-viking-phan-1', 'Chuyện Người Viking (Phần 1)', 'Norsemen (Season 1)', 'https://phimimg.com/upload/vod/20231207-1/0fca9463254b78732c460c6452727f6c.jpg', 'https://phimimg.com/upload/vod/20231207-1/8e56b51d135750592931469dde931b01.jpg', '<p>Một tù trưởng trở lại, tranh giành quyền lực với người anh em đố kị của anh ta, một nô lệ đưa nghệ thuật đến phương bắc và một chiến binh vật lộn để làm nông.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 22, 2016, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Kåre Conradi","avatar":""},{"name":"Silje Torp","avatar":""},{"name":"Nils Jørgen Kaalstad","avatar":""},{"name":"Marian Saastad Ottesen","avatar":""},{"name":"Trond Fausa Aurvåg","avatar":""},{"name":"Kristine Riis","avatar":""},{"name":"Jon Øigarden","avatar":""},{"name":"Henrik Mestad","avatar":""},{"name":"Øystein Martinsen","avatar":""},{"name":"Mikkel Bratt Silset","avatar":""},{"name":"Mads Jørgensen","avatar":""},{"name":"Nikis Theophilakis","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Bjørn My","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
