INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-bien-xanh', 'Huyền Thoại Biển Xanh', 'Legend of the Blue Sea', 'https://phimimg.com/upload/vod/20231207-1/433405e8d59a2611965bfc50447048a5.jpg', 'https://phimimg.com/upload/vod/20231207-1/a243d476508ff375eed17dd4c785b0ee.jpg', '<p>Huyền Thoại Biển Xanh dựa trên một câu chuyện đồng thoại nổi tiếng của Hàn Quốc, bộ phim xoay quanh câu chuyện tình yêu của một nàng tiên cá cuối cùng còn tồn tại trên Trái Đất và một gã lừa đảo thiên tài tên Heo Joon Hae ở thời hiện đại. Chuyện tình yêu của họ kéo dài 2 kiếp, kiếp trước Heo Joon Hae tên là Kim Moo, một công tử của gia tộc quyền quý thời Joseon. Phim có sự góp mặt của cặp đôi vàng Jun Ji Hyun và Lee Min Ho và sự tham gia của thành viên nhóm nhạc F(x) Krystal và GOT7 Jin Young dưới tư cách khách mời.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gianna Jun","avatar":""},{"name":"Lee Min Ho","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Hye-Sun Shin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324412);
