INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-ket-bi-an', 'Liên Kết Bí Ẩn', 'The Confirmation', 'https://phimimg.com/upload/vod/20231206-1/38f29048a5fd2d149401ed66da788e1b.jpg', 'https://phimimg.com/upload/vod/20231206-1/d32466e82f966d1d6d9d16f182594a27.jpg', '<p>Phim The Confirmation (2016): Cậu bé 8 tuổi Anthony lo lắng khi phải dành cả tuần với ông bố nghiện rượu kém may mắn của mình trong khi mẹ mình là Bonnie cùng chồng mới Kyle đi hành hương Công Giáo cùng nhau. Walt cũng muộn phiền không kém khi dành thời gian với Anthony, đặc biệt trong ngày đầu ở cùng nhau họ gặp phải rất nhiều điều không may, từ chiếc xe tải bị hư, chủ thuê nhà nhốt họ ở ngoài cho đến hộp dụng cụ Walt cần cho công việc sắp tới cũng mất cắp. Khi Walt và Anthony sắp sửa tìm thấy ra kẻ đánh cắp hộp dụng cụ và ứng biến với những tình huống dở khóc dở cười của họ, họ bắt đầu khám phá ra sự kết nối thật sự giữa hai bố con, giúp Walt trở thành một người cha tốt hơn và Anthony giúp bộc lộ mặt tốt trong con người của bố minh.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Jaeden Lieberher","avatar":""},{"name":"Maria Bello","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324412);
