INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('billy-lynn-va-cuoc-chien-nua-doi-nguoi', 'Billy Lynn Và Cuộc Chiến Nửa Đời Người', 'Billy Lynn''s Long Halftime Walk', 'https://phimimg.com/upload/vod/20231204-1/81b35bad8c09df36acf43ff7e7539ae5.jpg', 'https://phimimg.com/upload/vod/20231204-1/c705a6f09f6ac9d5830c266462717cc3.jpg', '<p>Phim Billy Lynn Và Cuộc Chiến Nửa Đời Người - Billy Lynns Long Halftime Walk 2016: xoay quanh Bravo Company và chàng binh nhì 19 tuổi Billy Lynn, hai người lính sống sót sau cuộc chiến tranh ác liệt tại Iraq. Trở về nước Mỹ, họ bị báo chí săn đuổi và vô tình trở thành công cụ tuyên truyền cho chính phủ khi cùng nhau xuất hiện trong giờ nghỉ của trận đấu bóng bầu dục quan trọng diễn ra đúng vào dịp lễ Tạ ơn. Tuy nhiên, sự tung hê của truyền thông khiến những người vừa được vinh danh anh hùng không khỏi suy ngẫm và phẫn nộ.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Joe Alwyn","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Chris Tucker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324412);
