INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuop-va-thien-than', 'Kẻ Cướp Và Thiên Thần', 'Outlaws And Angels', 'https://phimimg.com/upload/vod/20231204-1/4a6882e5fe85fdd44fa9924f002ecfc0.jpg', 'https://phimimg.com/upload/vod/20231204-1/a4c5546fa71b4be6e9e3ef3d19a867bb.jpg', '<p>Phim Kẻ Cướp Và Thiên Thần - Outlaws And Angels 2016: Băng cướp sau khi đánh cướp ngân hàng đã chạy trốn đến vùng biên giới Viễn tây và đột nhập vào một gia đình nông dân có những cô gái xinh xắn, ẩn nấp. Sự quyến rũ của các cô gái đã khiến bọn chúng trở nên đồi bại, cô gái út được chăm sóc tốt hơn và huấn luyện trở thành một tay bắn súng thiện xạ. Và thật bất ngờ, cô gái út đã quay súng bắn chết chị mình và đánh chết người cha vô cùng nhẫn tâm. Trước thảm cảnh máu me ấy, bọn cướp lại hí hửng và tin tưởng cô gái út hơn và cuộc chiến thực sự mới bắt đầu.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Francesca Eastwood","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Frances Fisher","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324412);
