INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-va-ga-khong-lo', 'Cô Gái và Gã Khổng Lồ', 'Colossal', 'https://phimimg.com/upload/vod/20231204-1/50f5e055d3a4b184a9bd25160c93410a.jpg', 'https://phimimg.com/upload/vod/20231204-1/43cc7cfe9c2253a16b967cd15d6b406a.jpg', '<p>Gloria (Anne Hathaway) là một cô gái ngoài công việc, sau khi được bạn trai của cô ấy đá ra khỏi căn hộ của mình, buộc phải rời khỏi cuộc sống ở New York và quay trở lại quê hương. Khi tin tức báo cáo bề mặt rằng một sinh vật khổng lồ đang phá hủy Seoul, Hàn Quốc, Gloria dần dần nhận ra rằng cô ấy bằng cách nào đó đã kết nối với hiện tượng xa xôi này. Khi các sự kiện bắt đầu thoát khỏi tầm kiểm soát, Gloria phải xác định lý do tại sao sự tồn tại dường như không đáng kể của cô ấy có một hiệu ứng khổng lồ như vậy đối với số phận của thế giới.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Canada', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
