INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-bo-nuoc-my', 'Khủng Bố Nước Mỹ', 'AmeriGeddon', 'https://phimimg.com/upload/vod/20231204-1/bc727c561e021846a094745c3ab2f59e.jpg', 'https://phimimg.com/upload/vod/20231204-1/22cae436a3e37400fdd96d6d5aec7305.jpg', '<p>Một cảnh báo nghiêm trọng về một hồi chuông cảnh tỉnh về những gì có thể xảy ra trong tương lai của chúng ta khi một tổ chức khủng bố theo chủ nghĩa toàn cầu liên kết với Liên Hợp Quốc vô hiệu hóa lưới điện của Hoa Kỳ và thiết lập Thiết quân luật. Nó sẽ cần một gia đình yêu nước tận tụy được trang bị các kỹ năng sinh tồn mạnh mẽ và phần còn lại của Tu chính án thứ hai để cứu nước Mỹ và đòi lại tự do.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"India Eisley","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Diane Ladd","avatar":""},{"name":"Alex Jones","avatar":""},{"name":"Marshall R. Teague","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324412);
