INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-pho-quy', 'Ngôi Nhà Phố Quỷ', 'From A House On Willow Street', 'https://phimimg.com/upload/vod/20231203-1/dd2fe27f942a498684da529f32839f10.jpg', 'https://phimimg.com/upload/vod/20231203-1/05e5bd6d841380723bbac887aa570ea0.jpg', '<p>Ngôi Nhà Phố Quỷ, From A House On Willow Street&nbsp;với kế hoạch được lên trong vòng sáu tuần, Hazel, Ade, James và Mark lập kế hoạch bắt cóc Katherine, con gái của một đại lý đồ nữ trang. Khi họ đột nhập vào nhà của gia đình trên phố Willow, Ade nhìn thấy những biểu tượng ăn mặc trên tủ quần áo của cô ấy. Họ đưa Katherine vào xe tải và mang cô đến một cơ sở bị bỏ rơi. Họ kết nối Katherine trong tầng hầm và băng video của cô ấy. Họ gửi video cho gia đình và sau đó gọi điện cho bố để đòi tiền chuộc.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alastair Orr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324412);
