INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ham-indianapolis-thu-thach-sinh-ton', 'Chiến Hạm Indianapolis: Thử Thách Sinh Tồn', 'USS Indianapolis: Men Of Courage', 'https://phimimg.com/upload/vod/20231203-1/52711ac1563dc292cf1cb95aa97aba6a.jpg', 'https://phimimg.com/upload/vod/20231203-1/91159ea9006a9994d3a6036ad9469ab6.jpg', '<p>Phim Chiến Hạm Indianapolis: Thử Thách Sinh Tồn - USS Indianapolis: Men Of Courage 2016 là bộ phim thuộc thể loại hành động chiến tranh, kể về nỗi đau chiến tranh có thật của các thuyền viên tàu USS Indianapolis. Họ đã mắc kẹt tại biển Philippine suốt năm ngày sau khi vận chuyển vũ khí hạt nhân để kết thúc chiến tranh thế giới thứ 2. Chịu đựng cơn đói khát cùng cực, cá mập tấn công không ngừng, lênh đênh trên mặt biển… thủy thủ đoàn chỉ còn 327 người sống sót. Ngay sau đó, thuyển trưởng bị đưa ra tòa án binh để chịu tránh nhiệm. Và phải nửa thế kỷ sau, nỗi oan của ông mới được giải. Phim có sự tham gia của nam diễn viên sở hữu tượng vàng Oscar – Nicolas Cage.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Matt Lanter","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324412);
