INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hentai-kamen-the-abnormal-crisis', 'Hentai Kamen: The Abnormal Crisis', 'Hentai Kamen: The Abnormal Crisis', 'https://phimimg.com/upload/vod/20231203-1/f197aaa2bc2ed235f738c5c4b42e119e.jpg', 'https://phimimg.com/upload/vod/20231203-1/01f32b5dcf4bf5c13e0283f4ab179069.jpg', '<p>Tin tức về sự biến mất của quần lót được bao phủ mỗi ngày. Kyosuke (Ryohei Suzuki) vẫn mặc quần lót Aiko Complete (Fumika Shimizu) để chiến đấu ác. Trong khi đó, Aiko có cảm xúc lẫn lộn và quyết định lấy quần lót của cô trở lại từ Kyosuke. Kyosuke bị Mất quần lót Aiko Completico và biến mất. Kẻ thù lớn nhất dường như xuất hiện trước mặt Kyosuke</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324412);
