INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-biet-3-nhung-ke-trung-kien', 'Dị Biệt 3: Những Kẻ Trung Kiên', 'Divergent 3: Allegiant', 'https://phimimg.com/upload/vod/20231203-1/979411fcada4eecb2ee28fce7febac17.jpg', 'https://phimimg.com/upload/vod/20231203-1/d8563108a62adf142e4abce2539f5c95.jpg', '<p>Phim Dị Biệt 3: Những Kẻ Trung Kiên - The Divergent Series: Allegiant 2016: sẽ đưa Tris và Four bước vào một thế giới mới nguy hiểm hơn bao giờ hết. Lần đầu tiên họ rời khỏi gia đình, rời khỏi thành phố duy nhất biết đến từ trước đến nay, để tìm một giải pháp hòa bình cho thành phố của họ. Ở bên ngoài, những phát hiện cũ nhanh chóng trở nên vô nghĩa qua những chân lý mới gây sốc. Tris và Four phải nhanh chóng quyết định những người mà họ có thể tin tưởng trong một cuộc chiến tàn nhẫn ngoài các bức tường của Chicago, đe dọa toàn nhân loại. Để tồn tại, Tris bị buộc phải lựa chọn giữa lòng dũng cảm, lòng trung thành, sự hy sinh và tình yêu.</p>', 'Full', 1, 'single', 'completed', 5, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shailene Woodley","avatar":""},{"name":"Theo James","avatar":""},{"name":"Zoë Kravitz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324412);
