INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ly-ky-cua-tieu-thuyet-gia', 'Câu Chuyện Ly Kỳ Của Tiểu Thuyết Gia', 'Life Risking Romance', 'https://phimimg.com/upload/vod/20231204-1/917401af77ff83c05362a9e1c006953a.jpg', 'https://phimimg.com/upload/vod/20231204-1/862039ad23ea0dd9558d94789d8b69b4.jpg', '<p>Trong phim, Ha Ji Won vào vai Han Jae In, một nhà văn chuyên tiểu thuyết bí ẩn nhưng lại vụng về, nhát gan mơ lúc nào đó sẽ trở thành cây bút ăn khách. Chun Jung Myoung vào vai bạn từ thủa nhỏ của Jae In nay đã là cảnh sát Seol Lok Hwan, một cái tên hơi hướm Sherlock Holmes.Lok Hwan là một người vô cùng thuần túy với tình yêu kiên định dành cho Jae In. Anh cuối cùng rơi vào tình yêu tay ba với Jae In và Jason, một người lên hồ sơ FBI như thể bước ra từ một tiểu thuyết lãng mạn. Bộ ba cuối cùng tiến tới một mục tiêu là bắt kẻ giết người hàng loạt đang ám ảnh cả thành phố.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji-won","avatar":""},{"name":"Trần Bách Lâm","avatar":""},{"name":"Oh Jung Se","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
