INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-san-catwalk', 'Ác Quỷ Sàn Catwalk', 'The Neon Demon', 'https://phimimg.com/upload/vod/20231204-1/b73fe051d62c2b282ad6c2b97758caa2.jpg', 'https://phimimg.com/upload/vod/20231204-1/8aa913b20601edc4cc499f8cb934215e.jpg', '<p>Cô gái tỉnh lẻ Jesse (Elle Fanning) bước chân vào thế giới của những nàng người mẫu nơi thành phố Thiên Thần, Los Angeles. Jesse lập tức thu hút ánh sáng đèn màu, qua mặt nhiều lớp đàn chị, trở thành người mẫu ăn khách nhất. Cô không hề biết rằngÁc Quỷ Sàn Catwalk” lại là thế giới của những con ma cà rồng hút máu tươi hay những kẻ ăn thịt người để tồn tại; cũng là cái thế giới của những cô người mẫu, lặn ngụp giữa các hãng tuyển dụng gương mặt thương hiệu, giữa những ông bầu có lòng tham vô đáy, những tay ma cô, những mụ tú bà.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elle Fanning","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Abbey Lee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
