INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-nhan-bi-an', 'Tù Nhân Bí Ẩn', 'Prisoner X', 'https://phimimg.com/upload/vod/20231202-1/a97ea43e8d4105d16e833828929df9d9.jpg', 'https://phimimg.com/upload/vod/20231202-1/3c032f9a70fc90df1b67275969b58137.jpg', '<p>Phim Tù Nhân Bí Ẩn - Prisoner X 2016: Một người đàn ông trong khi lái xe đã bị tai nạn ở gần biên giới Canada và một quả bom Uranium được tìm thấy. Anh ta ngay lập tức bị ném vào một nhà tù an ninh đặc biệt và bị tra tấn không ngừng. Nhưng ngoài một vài tiếng la hét bằng ngôn ngữ không rõ, anh ta chẳng hé lộ điều gì thêm. Rồi một ngày anh ta đưa cho nhân viên thẩm vấn một danh sách các con số và chữ cái, mà nó trở thành toạ độ của vụ nổ Supernova thiên hà sắp tới. Ngay ngày hôm sau, vụ nổ đã xảy ra, một trong số những sự kiện trên bầu trời xảy ra chính xác như dự đoán. Rõ ràng người đàn ông bị giam giữ không phải là một kẻ khủng bố thông thường. 15 năm sau, Ramio vẫn ngồi trong cùng một nhà tù bí mật sâu 2 km dưới mặt đất. Trong khi đó Hoa Kỳ đã tiến hành những kế hoach bí mật dựa trên các dữ kiện của tù nhân, biệt danh tù nhân X.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Julian Richings","avatar":""},{"name":"Michelle Nolden","avatar":""},{"name":"Nigel Bennett","avatar":""},{"name":"Damon Runyan","avatar":""},{"name":"Jessica Greco","avatar":""},{"name":"Gianpaolo Venuta","avatar":""},{"name":"Romano Orzari","avatar":""},{"name":"Alex Harrouch","avatar":""},{"name":"Dru Viergever","avatar":""},{"name":"Vladimir Jon Cubrt","avatar":""},{"name":"Jim Codrington","avatar":""},{"name":"Stewart Arnott","avatar":""},{"name":"Shawn Orr","avatar":""},{"name":"Andrew Lichti-Lee","avatar":""},{"name":"Keira McNeice","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324413);
