INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-nham', 'Cưới Nhầm', 'Forever (Vir Altyd)', 'https://phimimg.com/upload/vod/20231213-1/63d3d02ec2ef7e83a16f2b518707ee68.jpg', 'https://phimimg.com/upload/vod/20231213-1/ab035aeb752d6c2e5b9d8db3a99cd1ab.jpg', '<p>Những người bạn thời thơ ấu, Nina và Hugo đã chọn những con đường khác nhau trong cuộc sống. Nhiều năm sau, Hugo trở về quê nhà mà không hề hay biết, một ngày trước đám cưới của Nina. Các sự kiện trong ngày cưới ném họ trở lại với nhau và họ bắt đầu một cuộc phiêu lưu mới.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Ivan Botha","avatar":""},{"name":"DonnaLee Roberts","avatar":""},{"name":"Elize Cawood","avatar":""},{"name":"Wilson Dunster","avatar":""},{"name":"Dirk Stoltz","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
