INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-loi-nguyen', 'Giải Mã Lời Nguyền', 'The Faith of Anna Waters', 'https://phimimg.com/upload/vod/20231201-1/63273b250e290af044338439636d251d.jpg', 'https://phimimg.com/upload/vod/20231201-1/f03b616af6b1198d2e2ead5801382505.jpg', '<p>Cuộc hành trình của Jamie – một phóng viên trẻ tuổi thành đạt đến Singapore để điều tra sự thật về cái chết bí ẩn của chị gái cô - Anna.&nbsp;Tại đây, Jamie phát hiện thêm nhiều cái chết kinh dị giống Anna và bắt đầu tham gia cùng anh rể trong cuộc chiến chống lại những thế lực ma quỷ sử dụng công nghệ mới để giết người.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Settle","avatar":""},{"name":"Elizabeth Rice","avatar":""},{"name":"Pamelyn Chee","avatar":""},{"name":"Jaymee Ong","avatar":""},{"name":"Adina Herz","avatar":""},{"name":"Colin Borgonon","avatar":""},{"name":"Elizabeth Lazan","avatar":""},{"name":"Adrian Pang","avatar":""},{"name":"Tan Kheng Hua","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
