INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-no', 'Phẫn Nộ', 'I Am Wrath', 'https://phimimg.com/upload/vod/20231201-1/12e0c44fb5b3667c041e5fae7ea00b1a.jpg', 'https://phimimg.com/upload/vod/20231201-1/48242d974a6be133930be70ce68b4eae.jpg', '<p>Phẫn Nộ - I Am Wrath xoay quanh hành trình trả thù cho vợ của Hill - một kỹ sư đang thất nghiệp. Hill ám ảnh khi phải tận mắt chứng kiến cảnh người vợ của mình là Vivian bị sát hại bởi những tên côn đồ trong một bãi đỗ xe. Khi cảnh sát bất lực không thể làm gì với những kẻ giết người, không còn cách nào khác, Stanley đã quyết định tự mình tìm cách giải quyết các vấn đề, một mình đương đầu với những thế lực ngầm.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Amanda Schull","avatar":""},{"name":"Sam Trammell","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Asante Jones","avatar":""},{"name":"Paul Sloan","avatar":""},{"name":"Luis Da Silva Jr.","avatar":""},{"name":"Jordan Whalen","avatar":""},{"name":"Jayden Blake Cochran","avatar":""},{"name":"Caroline Kane","avatar":""},{"name":"Robert Forte Shannon III","avatar":""},{"name":"Stacy Levi","avatar":""},{"name":"James Logan","avatar":""},{"name":"Dori","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
