INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-bi-an', 'Tội Ác Bí Ẩn', 'Night Of A 1000 Hours', 'https://phimimg.com/upload/vod/20231211-1/5f9ec96e3d80036fb0d5e5c9c2a98c5b.jpg', 'https://phimimg.com/upload/vod/20231211-1/1cfad795c7c13b853bf8723dadedff29.jpg', '<p>Khi Philip đầy tham vọng tiếp quản công việc kinh doanh của gia đình từ cha mình, anh thấy mình phải đối mặt với sự xuất hiện lại bí ẩn của tổ tiên đã chết. Trong một đêm dài, trong đó có một vụ giết người, một mối tình bất chính và một trò chơi với danh tính giả, Philip đã khám phá ra một bí mật gia đình được bảo vệ chặt chẽ.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laurence Rupp","avatar":""},{"name":"Amira Casar","avatar":""},{"name":"Johann Adam Oest","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
