INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-mat-tich', 'Người Vợ Mất Tích', 'The Secret', 'https://phimimg.com/upload/vod/20231210-1/270a5218919d2cd3e53240b2eceb362a.jpg', 'https://phimimg.com/upload/vod/20231210-1/b70d3115df09c28ab8d6eedee4660e90.jpg', '<p>Người Vợ Mất Tích - The Secret là câu chuyện của cặp vợ chồng Khải Phong và Thu Tiệp. Để kỉ niệm ngày cưới, hai người đã cùng nhau đi du lịch và trượt tuyết. Không may, người vợ Thu Tiệp qua đời vì tai nạn, điều này đã khiến cho Khải Phong hết sức đau lòng. Khải Phong ngày đêm mong chờ vợ quay về, tình yêu và sự chờ đợi của anh đã khiến linh hồn Thu Tiệp thực sự trở lại. Sau này, Khải Phong phát hiện, chỉ có những người thực sự yêu mến Thu Tiệp mới có thể trông thấy cô.</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lê Minh","avatar":""},{"name":"Leon Lai","avatar":""},{"name":"Nick Murphy","avatar":""},{"name":"Patrick J Molloy","avatar":""},{"name":"Wayne J.J. Lim","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
