INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-johnny-cash', 'Tôi Là Johnny Cash', 'I Am Johnny Cash', 'https://phimimg.com/upload/vod/20231210-1/155dab33797133fbe3cd08fad766c843.jpg', 'https://phimimg.com/upload/vod/20231210-1/7e1a185e41899c639b572560ea9d4d1d.jpg', '<p>Đây là nội dung catch-up kênh BlueAnt Entertainment, sẽ hết hạn sau 7 ngày, quý khách cần active gói VIP để xem.Johnny Cash là một trong số các nghệ sĩ có ảnh hưởng nhất của thế kỷ 20. Khởi điểm là một nghệ sĩ nhạc đồng quê, các bài hát và danh tiếng của ông lan sang nhiều thể loại khác gồm rock và rock and roll cũng như nhạc blue, nhạc dân gian và nhạc thánh ca.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Cash","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324413);
