INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia-tinh-duyen', 'Thiên Địa Tình Duyên', 'The World Of Love', 'https://phimimg.com/upload/vod/20231203-1/868f045aeae6a5eb0c7a75b766d36719.jpg', 'https://phimimg.com/upload/vod/20231203-1/144018fd584e5497c465366797d8708d.jpg', '<p>Thiên Địa Tình Duyên được chuyển thể từ tiểu thuyết Kết duyên của nhà văn Tuyết Linh Chi. Trong phim, Lý Thạnh thủ vai Nguyên Nguyệt Tranh, một cô gái xinh đẹp, thông minh và lương thiện. Từ nhỏ, Nguyệt Tranh đã thầm yêu thái tử Phượng Lân, nhưng chẳng may Phượng Lân chỉ một lòng hướng về Đỗ Ti Vũ - con gái của Đỗ Tướng quân. Sau bao phong ba bão táp, cuối cùng Nguyệt Tranh cũng được trở thành chính phi của Phượng Lân. Tuy nhiên, ngay trong đêm tân hôn của nàng, em trai Phượng Lân là Phượng Tuần - người yêu Nguyệt Tranh say đắm đã vào đại náo. Sau đó, Nguyệt Tranh lại bị bắt cóc và buộc phải ký một lời cam kết nếu như nàng muốn trở về với người đàn ông mình yêu. Những sóng gió cứ dồn dập ập đến với Nguyệt Tranh, tuy nhiên, cô đã từng bước vượt qua thử thách để vươn lên thành bậc mẫu nghi thiên hạ.</p>', 'Hoàn tất (36/36)', 36, 'series', 'completed', 19, 2016, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Minh","avatar":""},{"name":"Lý Nhã Nam","avatar":""},{"name":"Lý Thạnh","avatar":""},{"name":"Cao Vân Tường","avatar":""},{"name":"Hoắc Chính Ngạn","avatar":""},{"name":"Lê Nhất Huyên","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324413);
