INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('justin-timberlake-va-the-tennessee-kids', 'Justin Timberlake và The Tennessee Kids', 'Justin Timberlake + The Tennessee Kids', 'https://phimimg.com/upload/vod/20231130-1/19ff0824952051e1c6d5a044f917d6f3.jpg', 'https://phimimg.com/upload/vod/20231130-1/52bb86b9489ddc7cb6f98bbe433df919.jpg', '<p>Vào những đêm cuối của chuyến lưu diễn quanh thế giới, Jonathan Demme đã ghi lại những khoảnh khắc bùng nổ: các nhạc sĩ thiên tài, vũ công khéo léo và ngôi sao cuốn hút.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Timberlake","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324413);
