INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-toi-ac', 'Vòng Xoáy Tội Ác', 'Boost', 'https://phimimg.com/upload/vod/20231130-1/bcb93a55bc24acd464e992b0d003b258.jpg', 'https://phimimg.com/upload/vod/20231130-1/4f3df0706c3c04e3861d92e81af5dcc7.jpg', '<p>Phim Vòng Xoáy Tội Ác - Boost 2015: Khi Jimmy khám phá ra một kiện hàng bí ẩn trong cốp chiếc xe đua mới nhất của mình, anh ta bị đẩy vào thế giới ngầm của tội phạm, một cuộc đua với thời gian để cứu lấy mạng sống của cô gái nhỏ.</p>', 'Full', 1, 'single', 'completed', 6, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny Trejo","avatar":""},{"name":"Danay García","avatar":""},{"name":"Trent Garrett","avatar":""},{"name":"Justin Dray","avatar":""},{"name":"Rob Nagle","avatar":""},{"name":"Jonathan LaVallee","avatar":""},{"name":"Michael Flores","avatar":""},{"name":"Erin Evans","avatar":""},{"name":"Grazi DiPaolo","avatar":""},{"name":"H.C. Fletcher","avatar":""},{"name":"Harut Tovmasyan","avatar":""},{"name":"Vardan Amolikyan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324413);
