INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hoc-ma', 'Đại Học Ma', 'Midnight University', 'https://phimimg.com/upload/vod/20231130-1/0497541cae76d02e6954907925c93410.jpg', 'https://phimimg.com/upload/vod/20231130-1/6693b04ba4d02464d8167ae9c3410f29.jpg', '<p>Đã bao giờ bạn thắc mắc rằng, liệu thế giới bên kia có còn điều gì ngoài muôn vạn hồn ma cùng những câu chuyện truyền miệng rùng rợn? Bạn có từng đặt giả thuyết hoang đường rằng ở đó cũng tồn tại một… lớp học? Nếu có thì sẽ như thế nào? Sẽ có bài kiểm tra chứ? Sẽ phải học những gì? Phim Midnight University xoay quanh nhân vật nữ chính là cô sinh viên tên Star – hotgirl của một trường đại học – cùng sáu người bạn cùng trường khác. Vì nhiều lý do, nhóm bạn buộc phải tham gia lớp học đêm nằm ở phòng Zero (vốn được sinh viên toàn trường xem là “lãnh địa” của những “đồng học” nhưng đã chết trước khi kịp tốt nghiệp), tạm gọi là một “lớp học ma ám” vô cùng đáng sợ. Cũng vì thế, bảy sinh viên “bất đắc dĩ” phải tham gia vào lớp học ở thế giới bên kia, mỗi tối vào lúc nửa đêm.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Darvid Kreepolrerk","avatar":""},{"name":"Rasri Balenciaga","avatar":""},{"name":"Theerachai Wimolchaireuk","avatar":""},{"name":"Maethanee Buranasiri","avatar":""},{"name":"Charada Imraporn","avatar":""},{"name":"Boriboon Junreurng","avatar":""},{"name":"Marut Chuenchomboon","avatar":""},{"name":"Pavinee Bulanacheevalai","avatar":""},{"name":"Koravic Jandan","avatar":""},{"name":"Pongsit Pisittakarn","avatar":""},{"name":"Panita Thanachottarakron","avatar":""},{"name":"Jutamas Plungsuchon","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
