INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-tran-chien-dam-mau', 'Thế Giới Ngầm: Trận Chiến Đẫm Máu', 'Underworld: Blood Wars', 'https://phimimg.com/upload/vod/20231130-1/16aa5df8dd7bbfa9166afdf16be2ec81.jpg', 'https://phimimg.com/upload/vod/20231130-1/b76704aff47e445035640404252f37af.jpg', '<p>Sau các sự kiện của phần phim trước, Selene phải che giấu tung tích Eve, con gái của mình, bởi dòng máu lai đặc biệt mà cô bé nắm giữ. Quá chán nản tình cảnh bị săn đuổi bởi cả 2 giống loài nhằm sử dụng máu của cô để trở nên mạnh hơn, Selene cùng 2 đồng minh mới là David và cha của anh, Thomas, quyết định chấm dứt cuộc chiến kéo dài hàng trăm năm giữa Người sói và Ma cà rồng dù cái giá phải trả có thể là mạng sống của cô.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Theo James","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Lara Pulver","avatar":""},{"name":"Bradley James","avatar":""},{"name":"Peter Andersson","avatar":""},{"name":"James Faulkner","avatar":""},{"name":"Clementine Nicholson","avatar":""},{"name":"Daisy Head","avatar":""},{"name":"Oliver Stark","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Zuzana Stivínová","avatar":""},{"name":"Brian Caspe","avatar":""},{"name":"Jan Nemejovský","avatar":""},{"name":"Sveta Driga","avatar":""},{"name":"Dan Bradford","avatar":""},{"name":"David Bowles","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 178469032