INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-nui-2', 'Ngọn Núi 2', 'The Mountain 2', 'https://phimimg.com/upload/vod/20231130-1/2918342a805b98dc12e22df192ea79ab.jpg', 'https://phimimg.com/upload/vod/20231130-1/0712a8560924eb84d40924569d44704c.jpg', '<p>Một đội bốn người được cử đến từ trụ sở chính để sửa chữa một trạm hài bất ngờ rơi vào một cuộc phục kích khủng bố trên các đỉnh núi. Hai người lính nghĩa vụ, một người là thanh niên giàu có học thức, người còn lại là một tên lưu manh đường phố thô thiển, phải gạt bỏ những khác biệt của họ và học cách tin tưởng lẫn nhau để tồn tại trong một tình huống không thể tha thứ. Cắt bỏ phía sau phòng tuyến của kẻ thù, ngọn núi là lối thoát duy nhất của họ.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Çağlar Ertuğrul","avatar":""},{"name":"Ufuk Bayraktar","avatar":""},{"name":"Murat Serezli","avatar":""},{"name":"Ahu Türkpençe","avatar":""},{"name":"Atılgan Gümüş","avatar":""},{"name":"Murat Arkın","avatar":""},{"name":"Armağan Oğuz","avatar":""},{"name":"Ahmet Pınar","avatar":""},{"name":"Açelya Özcan","avatar":""},{"name":"Bedii Akın","avatar":""},{"name":"Eylül Arular","avatar":""},{"name":"Ozan Ağaç","avatar":""},{"name":"Buse Varol","avatar":""},{"name":"Emir Benderlioğlu","avatar":""},{"name":"Çiğdem Benli","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
