INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('benh-vien-ma', 'Bệnh Viện Ma', 'Ghost Hospital', 'https://phimimg.com/upload/vod/20231208-1/255bcf6e22c7e467dff5050038447d42.jpg', 'https://phimimg.com/upload/vod/20231208-1/9def770b0d3e18ae4cccb42fbf202c6b.jpg', '<p>Mọi chuyện bắt đầu khi chàng bác sĩ trẻ tên Thành xin vào làm tại bệnh viện An Tâm. Trái với cái tên, bệnh viện này lại ẩn chứa đầy những ma quái, đẩy bác sĩ Thành vào những tình huống kỳ lạ…</p>', 'Full', 1, 'single', 'completed', 18, 2016, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Trấn Thành","avatar":""},{"name":"Hari Won","avatar":""},{"name":"Thu Trang","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
