INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-cuu', 'Vĩnh Cửu', 'Eternity', 'https://phimimg.com/upload/vod/20231129-1/5219a9d47b5bb8ee4bb4276a8b823198.jpg', 'https://phimimg.com/upload/vod/20231129-1/8903783426b0ed60098b80c98b6c7b4d.jpg', '<p>Từ sau tác phẩm gây tiếng vang &quot;Rừng Na-uy&quot;, &quot;Vĩnh cửu&quot; (tên gốc: Éternité) là bộ phim mới nhất của đạo diễn người Pháp gốc Việt Trần Anh Hùng, được chuyển thể từ cuốn tiểu thuyết vô cùng đặc biệt “Nét duyên góa phụ&quot; (tên gốc: L’élegance des veuves) của nữ văn sỹ Alice Ferney. Cuối thế kỷ thứ 19, Valentine vừa mới tròn đôi mươi kết hôn với Jules khi tuổi đời còn rất trẻ. 100 năm sau, cô cháu gái của bà đến từ Paris bách bộ trên một cây cầu nhỏ và kết thúc cuộc dạo bước định mệnh đó của mình bằng đám cưới với chàng trai mà cô phải lòng. Đan xen giữa hai thế kỷ đó là những biến động về tình yêu đôi lứa, tình cảm vợ chồng, tình mẫu tử… của ba người phụ nữ trong thời chiến, vượt qua nghịch cảnh và quả cảm đối mặt với những sóng gió của cuộc đời.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Audrey Tautou","avatar":""},{"name":"Bérénice Bejo","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Jérémie Renier","avatar":""},{"name":"Pierre Deladonchamps","avatar":""},{"name":"Arieh Worthalter","avatar":""},{"name":"Irène Jacob","avatar":""},{"name":"Valérie Stroh","avatar":""},{"name":"Philippine Leroy-Beaulieu","avatar":""},{"name":"Trần Nữ Yên Khê","avatar":""},{"name":"Thibault de Montalembert","avatar":""},{"name":"Xavier de Guillebon","avatar":""},{"name":"Louka Meliava","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324413);
