INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-tinh-co', 'Người Yêu Tình Cờ', 'Always Be My Maybe', 'https://phimimg.com/upload/vod/20231129-1/b19c566745b2e73f62e350a7dabd9e3f.jpg', 'https://phimimg.com/upload/vod/20231129-1/65a2f7bb806fe6763c69d2e363b00da2.jpg', '<p>Jake vừa bị người bạn gái lâu năm từ chối lời cầu hôn. Còn Tin-Tin vừa kết thúc một mối quan hệ mập mờ kéo dài ba năm trời. Nhân duyên đưa đẩy cho hai trái tim tan vỡ gặp nhau ở một khu nghỉ dưỡng ven biển. Tình yêu bắt đầu chớm nở trở lại, nhưng liệu họ có thể vượt qua vết thương lòng cũ để toàn tâm toàn ý vun đắp cho mối quan hệ mới?</p>', 'Full', 1, 'single', 'completed', 13, 2016, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Arci Muñoz","avatar":""},{"name":"Gerald Anderson","avatar":""},{"name":"Tirso Cruz III","avatar":""},{"name":"Irma Adlawan","avatar":""},{"name":"Nikki Valdez","avatar":""},{"name":"Carlo Aquino","avatar":""},{"name":"Jane Oineza","avatar":""},{"name":"Ricci Chan","avatar":""},{"name":"Kakai Bautista","avatar":""},{"name":"Matt Evans","avatar":""},{"name":"Ahron Villena","avatar":""},{"name":"Pepe Herrera","avatar":""},{"name":"Jairus Aquino","avatar":""},{"name":"Victor Silayan","avatar":""},{"name":"TJ Trinidad","avatar":""},{"name":"Dionne Monsanto","avatar":""},{"name":"Phi Palmos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324413);
