INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-rung-xanh-2016', 'Cậu Bé Rừng Xanh', 'The Jungle Book', 'https://phimimg.com/upload/vod/20231023-1/1be8ca57aca3a047817452ad2b2dee97.jpg', 'https://phimimg.com/upload/vod/20231023-1/58575b8e8bc991d8d67ff9fd13c12bf4.jpg', '<p>Phim nói về chuyến phiêu lưu của Mowgli – một cậu bé mồ côi được đàn chó sói nuôi dưỡng trong rừng già Ấn Độ. Ngày qua ngày, Mowgli cảm thấy mình không còn được chào đón ở mái nhà tự nhiên này nữa, bởi một con hổ hung dữ tên Shere Khan tuyên bố sẽ tiêu diệt những sinh vật có khả năng gây nên hiểm họa, sau khi hắn bị loài người tấn công. Buộc phải rời khỏi chốn dung thân duy nhất, Mogwli dấn bước vào một hành trình khám phá, với sự dẫn dắt của báo đen Bagheera và gấu Baloo. Trên đường đi, Mowgli đã gặp những sinh vật xấu xa: một con trăn tên Kaa có ánh mắt thôimiên, con khỉ đột King Louie với khả năng nói tiếng người lưu loát. Chúng cố ép buộc Mowgli hé lộ công thức tạo ra “bông hoa đỏ” lập lòe, được gọi là Lửa.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Neel Sethi","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Lupita Nyong''o","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Garry Shandling","avatar":""},{"name":"Emjay Anthony","avatar":""},{"name":"Brighton Rose","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Sam Raimi","avatar":""},{"name":"Russell Peters","avatar":""},{"name":"Max Favreau","avatar":""},{"name":"Chloe Hechter","avatar":""},{"name":"Asher Bl","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6