INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-2016', 'Ám Ảnh', 'Ám Ảnh', 'null', 'https://phimimg.com/upload/vod/20231011-1/b89c9bd6c246f84dcd73205815178afe.jpg', '<p>Phim mở đầu bằng câu hỏi: Làm thế nào để thoát khỏi nỗi ám ảnh về tình yêu và cái chết? Mai Anh không chấp nhận việc mất cha là một tai nạn, cô trở nên trầm cảm và nhờ đến sự chữa trị tâm lý của Nam. Về Nam, anh không thể quên người bạn gái cũ đã phản bội và bỏ rơi anh 3 năm trước.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hiếu Nguyễn","avatar":""},{"name":"Minh Thuận","avatar":""},{"name":"Tuan Luong Tran","avatar":""},{"name":"YaYa Trương Nhi","avatar":""},{"name":"Quốc Cường","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
