INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-bong-dem-lights-out', 'Ác Mộng Bóng Đêm', 'Lights Out', 'https://phimimg.com/upload/vod/20231026-1/d9b8e62ad25e0f0fc9eccc28847d7d58.jpg', 'https://phimimg.com/upload/vod/20231026-1/0c01aba1fe14461e2f1e6ae190644287.jpg', '<p>Nội dung phim Lights Out gây tò mò về “người bạn tưởng tượng” của bà mẹ Martin. Bà luôn miệng khẳng định Diana, từng là người bạn thời thơ ấu của bà đã chịu một thảm kịch khủng khiếp trong quá khứ, đang ở ngay trong chính căn nhà này. Song song đó, cậu bé Martin và chị gái Rebecca luôn bị quấy phá bởi một thực thể bí ẩn khi tắt đèn đi ngủ. Những bí mật xoay quanh Diana chính là mấu chốt làm sáng tỏ thân thế đen tối và là chìa khóa để tiêu diệt được tên ác quỷ bóng đêm nguy hiểm này.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Teresa Palmer","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Gabriel Bateman","avatar":""},{"name":"Alexander DiPersia","avatar":""},{"name":"Alicia Vela-Bailey","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Andi Osho","avatar":""},{"name":"Maria Russell","avatar":""},{"name":"Rolando Boyce","avatar":""},{"name":"Lotta Losten","avatar":""},{"name":"Amiah Miller","avatar":""},{"name":"Elizabeth Pan","avatar":""},{"name":"Emily Alyn Lind","avatar":""},{"name":"Ava Cantrell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
