INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-bong-dem-a-dream-ring', 'Ác Mộng Bóng Đêm', 'A Dream Ring - The Nightmare Call', 'null', 'https://phimimg.com/upload/vod/20231101-1/b6a7b1d157526aadc33ec8afec568fa5.jpg', '<p>Phim Ác Mộng Bóng Đêm - A Dream Ring - The Nightmare Call 2016: Cái chết bí ẩn của vợ, người yêu và trợ lý của Đỗ Dương sau khi nhận được điện thoại từ số lạ. Anh cố gắng khám phá bí ẩn của vụ án này. Đỗ Dương nhận thấy rằng, một khi đã nhận được &quot;Cuộc gọi nhỡ&quot;, chủ nhân của điện thoại sau một khoảng thời gian bị chết rất bi thảm. Rồi con gái của anh đột nhiên bị mất tích, Đỗ Dương bắt đầu trải qua những đêm kinh hoàng trong cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Alex Fong Lik-sun","avatar":""},{"name":"Dany Lee","avatar":""},{"name":"Liu Xiaodong","avatar":""},{"name":"Wang Xinting","avatar":""},{"name":"Yingqiao He","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324413);
