INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-tro-lai', 'Hồn Ma Trở Lại', 'The Remains', 'https://phimimg.com/upload/vod/20231129-1/9c17130f6352352d0c6dc9dc7dd24e3d.jpg', 'https://phimimg.com/upload/vod/20231129-1/49933d0114e1493dd6dc666004a64ecf.jpg', '<p>Phim Hồn Ma Trở Lại - The Remains 2016: Một gia đình sau khi chuyển về một căn hộ cũ từ thời Victoria, họ tìm thấy một cái rương trên gác mái chứa đựng những đồ vật cũ kỹ bị ám bởi một linh hồn tà ác. Các tạo vật càng xâm nhập vào gia đình, linh hồn càng trở nên mạnh mẽ hơn, kiên quyết bắt cóc những đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Todd Lowe","avatar":""},{"name":"Lisa Brenner","avatar":""},{"name":"Brooke Butler","avatar":""},{"name":"Ashley Crow","avatar":""},{"name":"Maria Olsen","avatar":""},{"name":"Samuel Larsen","avatar":""},{"name":"Nikki Hahn","avatar":""},{"name":"Hannah Nordberg","avatar":""},{"name":"Dash Williams","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
