INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wolf-girl-and-black-prince', 'Wolf Girl and Black Prince', 'Wolf Girl and Black Prince', 'https://phimimg.com/upload/vod/20231129-1/dbc3a1576b4d64f10d5fd5ed3f6c9a0e.jpg', 'https://phimimg.com/upload/vod/20231129-1/961e1ff594bb618348932decdcfb38a9.jpg', '<p>Nữ sinh trung học Erika tuyệt vọng muốn có một người bạn trai để trải nghiệm tình yêu, lãng mạn và tình dục. Than ôi, cô ấy độc thân. Cô ấy làm cho một câu chuyện về một người bạn trai giả vờ với những người bạn muốn gặp cậu bé. Erika snaps một bức ảnh của một cậu bé theo học cùng trường. Cô ấy cần được nhìn thấy với anh ấy và yêu cầu anh ấy xin vui lòng chơi cùng.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fumi Nikaido","avatar":""},{"name":"Kento Yamazaki","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Mugi Kadowaki","avatar":""},{"name":"Ryusei Yokohama","avatar":""},{"name":"Elaiza Ikeda","avatar":""},{"name":"Tina Tamashiro","avatar":""},{"name":"Ryo Yoshizawa","avatar":""},{"name":"Nanao","avatar":""},{"name":"Riria Kojima","avatar":""},{"name":"Rena Takeda","avatar":""},{"name":"Megumi Abe","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324413);
