INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tot-cung-sang-chanh', 'Tột Cùng Sang Chảnh', 'Absolutely Fabulous: The Movie', 'https://phimimg.com/upload/vod/20231129-1/065ae312b513ecb3e7139387419443be.jpg', 'https://phimimg.com/upload/vod/20231129-1/30aa1f9bf53a4516ed9dab9d10ecab63.jpg', '<p>Edina và Patsy vẫn toát lên vẻ hào nhoáng và quyến rũ, sống cuộc sống thượng lưu mà họ đã quen thuộc; mua sắm, uống rượu và tham gia câu lạc bộ quanh những điểm nóng thời thượng nhất của London. Bị đổ lỗi cho một sự cố lớn tại một bữa tiệc ra mắt thời trang siêu sang, họ vướng vào cơn bão truyền thông và bị các tay săn ảnh săn đuổi không ngừng. Chạy trốn đến sân chơi hào nhoáng của giới siêu giàu, French Riviera, họ ấp ủ một kế hoạch để trốn thoát vĩnh viễn và sống cuộc sống thượng lưu mãi mãi!</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jennifer Saunders","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Julia Sawalha","avatar":""},{"name":"June Whitfield","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Chris Colfer","avatar":""},{"name":"Christopher Ryan","avatar":""},{"name":"Mo Gaffney","avatar":""},{"name":"Kathy Burke","avatar":""},{"name":"Helen Lederer","avatar":""},{"name":"Harriet Thorpe","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Robert Webb","avatar":""},{"name":"Nick Mohammed","avatar":""},{"name":"Wanda Ventham","avatar":""},{"name":"Marcia Warren","avatar":""},{"name":"Indeyarna Donald","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
