INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-nu-tu-trong-trang', 'Các Nữ Tu Trong Trắng', 'The Innocents', 'https://phimimg.com/upload/vod/20231129-1/374444eb78aab6d0a3905fc1ff7681eb.jpg', 'https://phimimg.com/upload/vod/20231129-1/66381fa2ac6eded167566d8b81073627.jpg', '<p>Câu chuyện kể về cô sinh viên y khoa trẻ Mathilde Beaulieu (Lou de Laâge), đang làm tình nguyện viên cho một chi nhánh Hội Chữ thập đỏ Pháp ở Ba Lan trong thời kỳ hậu Thế chiến 2 vào tháng 12 năm 1945. Công việc hàng ngày của cô là cứu chữa và chăm sóc cho những người lính Pháp bị thương.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Lou de Laâge","avatar":""},{"name":"Agata Buzek","avatar":""},{"name":"Agata Kulesza","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Joanna Kulig","avatar":""},{"name":"Eliza Rycembel","avatar":""},{"name":"Katarzyna Dąbrowska","avatar":""},{"name":"Anna Próchniak","avatar":""},{"name":"Helena Sujecka","avatar":""},{"name":"Mira Maludzińska","avatar":""},{"name":"Dorota Kuduk","avatar":""},{"name":"Klara Bielawka","avatar":""},{"name":"Pascal Elso","avatar":""},{"name":"Thomas Coumans","avatar":""},{"name":"Leon Latan-Paszek","avatar":""},{"name":"Joanna Fertacz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324413);
