INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruot-duoi-ngoan-muc', 'Rượt Đuổi Ngoạn Mục', 'Vincent N Roxxy', 'https://phimimg.com/upload/vod/20231203-1/d1c2be5d6fb4a0ba46d013c65b627bfb.jpg', 'https://phimimg.com/upload/vod/20231203-1/b33e39c3256eeffdde3086d17c8c3a8e.jpg', '<p>Phim Rượt Đuổi Ngoạn Mục - Vincent N Roxxy 2016: Một kẻ cô độc đến từ tỉnh lẻ và một rocker nổi loạn bất ngờ rơi vào bẫy tình. Cặp đôi buộc phải tham gia cuộc đua và phát hiện ra rằng bạo lực xuất hiện ở khắp mọi nơi.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Zoey Deutch","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324413);
