INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-nhac-duong-pho', 'Âm Nhạc Đường Phố', 'Sing Street', 'https://phimimg.com/upload/vod/20231129-1/547cfc8403bd5a3a917a2bbd05578675.jpg', 'https://phimimg.com/upload/vod/20231129-1/b0c8e75a852339c2f151b25942a56159.jpg', '<p>Phim Âm Nhạc Đường Phố - Sing Street 2016 đưa người xem đến với thành phố Dublin những năm 1980 qua góc nhìn của một cậu bé 14 tuổi có tên Conor. Tâm lý của Conor vô cùng xao động bởi mối quan hệ bất hoà giữa cha mẹ cùng vấn đề tiền nong. Cùng lúc đó, cậu còn phải cố gắng hoà nhập vào một môi trường mới – nơi những bạn học rất xấu tính còn giáo viên lại cực kỳ thô lỗ. Thế giới của Conor như bừng sáng khi cậu gặp cô bé bí ẩn, xinh đẹp Raphina.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ferdia Walsh-Peelo","avatar":""},{"name":"Lucy Boynton","avatar":""},{"name":"Jack Reynor","avatar":""},{"name":"Ben Carolan","avatar":""},{"name":"Mark McKenna","avatar":""},{"name":"Kelly Thornton","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Ian Kenny","avatar":""},{"name":"Percy Chamburuka","avatar":""},{"name":"Connor Hamilton","avatar":""},{"name":"Karl Rice","avatar":""},{"name":"Don Wycherley","avatar":""},{"name":"Des Keogh","avatar":""},{"name":"Kian Murphy","avatar":""},{"name":"Dolores Mullally","avatar":""},{"name":"Marcella Plunket","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324413);
