INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-2016', 'Sự Thật', 'The Next Skin', 'https://phimimg.com/upload/vod/20231128-1/f65f7bbb547c9a9623d8a61f2d7c94e8.jpg', 'https://phimimg.com/upload/vod/20231128-1/69bbfc98e163a28660dc23fb495e1620.jpg', '<p>Một thiếu niên khép kín đột nhiên mất tích, khiến cả nhà chìm trong đau khổ. Nhiều năm sau, cậu xuất hiện trở lại, và gia đình bắt đầu nghi ngờ về thân phận của cậu.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Emma Suárez","avatar":""},{"name":"Àlex Monner","avatar":""},{"name":"Sergi López","avatar":""},{"name":"Bruno Todeschini","avatar":""},{"name":"Igor Szpakowski","avatar":""},{"name":"Greta Fernández","avatar":""},{"name":"Sílvia Bel","avatar":""},{"name":"Mikel Iglesias","avatar":""},{"name":"Pol Fercan","avatar":""},{"name":"Alex Moreu Garriga","avatar":""},{"name":"Fred Adenis","avatar":""},{"name":"Lucy Tillett","avatar":""},{"name":"Oriol Maymó","avatar":""},{"name":"David Arribas","avatar":""},{"name":"Juli Costa","avatar":""},{"name":"Intissar El Meskine","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
