INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-that-2016', 'Sự Thật', 'The Next Skin', 'sự thật the next skin emma suárez àlex monner sergi lópez bruno todeschini igor szpakowski greta fernández sílvia bel mikel iglesias pol fercan alex moreu garriga fred adenis lucy tillett oriol maymó david arribas juli costa intissar el meskine ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-mat', 'Nhiệm Vụ Mật', 'Anthropoid', 'https://phimimg.com/upload/vod/20231129-1/0cd673fdd9c5d7f7e9288ad42ad03a73.jpg', 'https://phimimg.com/upload/vod/20231129-1/d18ea01c555c32603c811554e65dbde1.jpg', '<p>Phim Nhiệm Vụ Mật - Anthropoid 2016: Tháng 12/1941, khi Czech bị quân Đức Quốc xã chiếm đóng. Một binh lính người Czech tên Jan Kubiš (Jamie Dornan đóng) cùng đồng đội nhận một nhiệm vụ bí mất nhảy dù vào vùng đất quê hương, phải dùng mưu trí và vũ khí ít ỏi để tìm cách ám sát viên tướng Phát xít – Reinhard Heydrich. Reinhard Heydrich là tư lệnh cao cấp thứ ba dưới quyền Hitler. Sự thành công của nhiệm vụ này sẽ thay đổi lịch sử châu Âu. Anthropoid dựa trên chuyện có thật về nhiệm vụ mật có tên Operation Anthropoid hồi Thế chiến II.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Dornan","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Charlotte Le Bon","avatar":""},{"name":"Anna Geislerová","avatar":""},{"name":"Harry Lloyd","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Alena Mihulová","avatar":""},{"name":"Marcin Dorociński","avatar":""},{"name":"Bill Milner","avatar":""},{"name":"Sam Keeley","avatar":""},{"name":"Jiří Šimek","avatar":""},{"name":"Mish Boyko","avatar":""},{"name":"Václav Neužil","avatar":""},{"name":"Andrej Polák","avatar":""},{"name":"Sean Mahon","avatar":""},{"name":"Detlef Bothe","avatar":""},{"name":"Jan Hájek","avatar":""},{"name":"Jan Budař","avatar":""},{"name":"Pave","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324413);
