INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-mat', 'Nhiệm Vụ Mật', 'Anthropoid', 'nhiệm vụ mật anthropoid jamie dornan cillian murphy charlotte le bon anna geislerová harry lloyd toby jones alena mihulová marcin dorociński bill milner sam keeley jiří šimek mish boyko václav neužil andrej polák sean mahon detlef bothe jan hájek jan budař pave ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-xin-hay-quay-lai', 'Yêu Em Xin Hãy Quay Lại', 'Love, Lost And Found', 'https://phimimg.com/upload/vod/20231208-1/09ca966c2ccaced8ddce379291090277.jpg', 'https://phimimg.com/upload/vod/20231208-1/2f69dd04dc5dc0bbafc709751ab00a7b.jpg', '<p>Yêu Em Xin Hãy Quay Lại - Love, Lost And Found xoay quanh Tĩnh Nghi. Cô cùng gia đình chạy trốn một khoản nợ và đến sinh sống tại một thị trấn nhỏ ở Đài Loan. Cô có cơ hội gặp Big J, người đứng đầu một băng đảng lừa đảo. Big J biết rằng Tĩnh Nghi vô cùng mong muốn thoát khỏi cảnh nghèo khó nên đã thuyết phục cô lừa đảo những người đàn ông giàu có. Cảnh sát Vương phụ trách điều tra những vụ lừa đảo tình cảm cho rằng Tĩnh Nghi rất đáng ngờ. Tĩnh Nghi trốn đến Đài Bắc, cùng lúc đó, cô vô tình phát hiện ra giáo viên Tần đã mất tất cả chỉ vì muốn bảo vệ cô. Tĩnh Nghi tự trách mình và bật khóc. Cô chợt nhớ lại lời hứa của mình với giáo viên Tần và đấu tranh với lương tâm. Liệu cô có thể thoát khỏi băng nhóm lừa đảo hay không?</p>', 'Full', 1, 'single', 'completed', 21, 2016, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chung Dao","avatar":""},{"name":"Dương Tinh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
