INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-bai-co', 'Lá Bài Cổ', 'Chihayafuru Part I', 'https://phimimg.com/upload/vod/20231208-1/52a437a6a80bd876306fcb2c3f5b4a32.jpg', 'https://phimimg.com/upload/vod/20231208-1/d4da47d53f1cf0cdda95e316876ea23d.jpg', '<p>Phim Lá Bài Cổ - Chihayafuru Part I 2016: Khi còn nhỏ, ước mơ của cô bé Chihaya Ayase là có thể nhìn thấy chị gái trở thành người mẫu số một Nhật Bản. Cho đến khi gặp Arata Wataya – cậu bạn vừa chuyển đến từ tỉnh Fukui, Chihaya mới tìm ra niềm đam mê thực sự của bản thân. Đó là karuta, một trò chơi truyền thống của Nhật Bản với những lá bài nhỏ ghi lại các bài thơ cổ. Cùng người bạn thời thơ ấu của Chihaya là Taichi Mashima, cả ba dần trở nên thân thiết và quyết tâm sẽ cùng nhau theo đuổi Karuta. Bốn năm sau, khi đã là học sinh cấp ba, biết được Arata không còn chơi karuta nữa, Chihaya và Taichi đã quyết định lập nên câu lạc bộ karuta mạnh nhất Nhật Bản, với niềm tin Arata chắc chắn sẽ quay trở lại với đam mê ngày nào.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Suzu Hirose","avatar":""},{"name":"Shuhei Nomura","avatar":""},{"name":"Mackenyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
