INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-chet', 'Hành Tinh Chết', 'Arrowhead', 'null', 'https://phimimg.com/upload/vod/20231208-1/bfa42068a158b6585b47c1c2c44ff549.jpg', '<p>Bộ phim Hành Tinh Chết - Arrowhead xoay quanh một công nghệ tiên tiến được một nhà lãnh đạo cách mạng đưa ra khỏi nhà tù. Người này hứa cho anh ta một cơ hội để cứu cha mình khỏi cuộc hành quyết nếu anh ta hoàn thành nhiệm vụ đánh cắp dữ liệu. Nhưng mọi việc không như mong muốn, anh đã bị mắc kẹt trên sa mạc ở mặt trăng với con tàu Arrowhead. Liệu chàng trai này có thể cứu mình và giải thoát cho người cha hay không?</p>', 'Full', 1, 'single', 'completed', 21, 2016, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Aleisha Rose","avatar":""},{"name":"Christopher Kirby","avatar":""},{"name":"Dan Mor","avatar":""},{"name":"Shaun Micallef","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324413);
