INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sang-lap', 'Người Sáng Lập', 'The Founder', 'https://phimimg.com/upload/vod/20231128-1/42fc621dcd2a42d8e3f10f19f55042cd.jpg', 'https://phimimg.com/upload/vod/20231128-1/b0d6c0569d3da402f53d31ecd776918f.jpg', '<p>Chuyện kể về Ray Kroc, một thương nhân đã biến mô hình đồ ăn nhanh táo bạo của hai anh em nhà McDonald trở thành một trong những chuỗi hàng ăn lớn nhất thế giới bởi nỗi tham vọng, lòng kiên trì và cả sự tàn nhẫn.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"B.J. Novak","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Justin Randell Brooke","avatar":""},{"name":"Kate Kneeland","avatar":""},{"name":"Wilbur Fitzgerald","avatar":""},{"name":"Griff Furst","avatar":""},{"name":"David de Vries","avatar":""},{"name":"Andrew Benator","avatar":""},{"name":"Cara Mantella","avatar":""},{"name":"Randall Taylor","avatar":""},{"name":"Kabby Borders","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324413);
