INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-tuong-thap-hen', 'Ảo Tưởng Thấp Hèn', 'Mean Dreams', 'https://phimimg.com/upload/vod/20231128-1/bb89f91c3092141d082744cbf2fd431f.jpg', 'https://phimimg.com/upload/vod/20231128-1/eef24a3114efbf017b3018b48484ee11.jpg', '<p>Phim Ảo Tưởng Thấp Hèn - Mean Dreams 2016: một bộ phim của tuổi teen nghiện ma túy, bắt đầu với cuộc gặp gỡ thân mật giữa cặp đôi tuổi teen là Jonas và Casey. Jonas làm việc ở trang trại chăn nuôi gia đình của cha mình ở vùng Great Lakes của Bắc Mỹ. Casey và cha cô là Wayne, một trung sĩ cảnh sát, là người hàng xóm mới của họ. Ông Wayne cố gắng ngăn tình cảm lãng mạn giữa Casey và Jonas. Khi Jonas biết ông Wayne ngăn cản Casey, cô đã có phản ứng với ông Wayne và Wayne đe dọa cuộc sống của cô. Sau đó, Jonas thấy Wayne có một khoản tiền lớn; Jonas đã cùng với Casey lấy trộm số tiền đó của Wayne và đôi tuổi teen bỏ trốn lên thành phố khác, trước sự lùng sục dã man của ông Wayne.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sophie Nélisse","avatar":""},{"name":"Josh Wiggins","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Joe Cobden","avatar":""},{"name":"Vickie Papavs","avatar":""},{"name":"Ryan Blakely","avatar":""},{"name":"George Buza","avatar":""},{"name":"Tara Nicodemo","avatar":""},{"name":"Mike McPhaden","avatar":""},{"name":"Richard Waugh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
