INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-sat-thu', 'Những Cô Gái Sát Thủ', 'Shadow of the Lotus', 'null', 'https://phimimg.com/upload/vod/20231129-1/07461f5461ee9e5bcbd1836a29ce0008.jpg', '<p>Sau một cuộc đột kích táo bạo vào một thương vụ buôn bán ma túy ở bến cảng, Sarah, một thành viên của bộ ba Black Lotus, bị phản bội và bị các cộng sự của cô ta bỏ mặc cho đến chết. Sau vài tháng hồi phục, cô quay trở lại để trả thù tổ chức tội phạm đã âm mưu giết cô. Cô sớm vượt qua con đường với Claire, một cảnh sát trẻ với ý thức mạnh mẽ về công lý và lý do của riêng cô để theo đuổi hội Tam hoàng. Hai người hình thành một mối quan hệ đối tác khó có thể theo dõi những kẻ phản bội Sarah. Với số tiền đặt cọc tăng lên, tên trùm xã hội đen và cựu cảnh sát một thời thấy mình bị kẹt giữa cuộc chiến không hồi kết giữa hai tổ chức tội phạm, với mạng sống của cả hai đều nằm trên đường dây.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vicky Huang","avatar":""},{"name":"Melanie Neale","avatar":""},{"name":"Alex Law","avatar":""},{"name":"Candice Macalino","avatar":""},{"name":"Geoff Wong","avatar":""},{"name":"Jono Lee","avatar":""},{"name":"Johnson Phan","avatar":""},{"name":"Kevan Ohtsji","avatar":""},{"name":"Marina Pasqua","avatar":""},{"name":"Meghan Kinsley","avatar":""},{"name":"Evan Lee","avatar":""},{"name":"Gordon Seid","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
