INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-cuu-mon-ngoai-truyen-ho-cot-mai-hoa', 'Lão Cửu Môn Ngoại Truyện: Hổ Cốt Mai Hoa', 'The Mystic Nine Side Story: Tiger Bones Plum Blossom', 'https://phimimg.com/upload/vod/20231129-1/f08b05a01f5042295b8383101db32404.jpg', 'https://phimimg.com/upload/vod/20231129-1/ca5404cfe0abb7331960cfad6e4daa98.jpg', '<p>“Lão Cửu Môn” giang hồ tụ họp! Sương mù vây lối, Cửu Gia rơi vào tình thế khó khăn của các vụ án hóc búa, kêu gào ầm ĩ tìm kiếm sự thật, bắt tay với phó quan cùng nhau phá vụ án giết người liên hoàn!</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Zi Jiang","avatar":""},{"name":"Zhang Ming En","avatar":""},{"name":"Hou Tong Jiang","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
