INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lao-cuu-mon-ngoai-truyen-ho-cot-mai-hoa', 'Lão Cửu Môn Ngoại Truyện: Hổ Cốt Mai Hoa', 'The Mystic Nine Side Story: Tiger Bones Plum Blossom', 'lão cửu môn ngoại truyện: hổ cốt mai hoa the mystic nine side story: tiger bones plum blossom yang zi jiang zhang ming en hou tong jiang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-ran-cua-quy', 'Lời Răn Của Quỷ', 'Black Mountain Side', 'https://phimimg.com/upload/vod/20231129-1/176996a683e811f7e60090d8fe26f0e2.jpg', 'https://phimimg.com/upload/vod/20231129-1/4ff170e67f2b6a85b5458429d4a087f7.jpg', '<p>Một nhóm các nhà khảo cổ học khám phá một cấu trúc cổ xưa ở Bắc Cực. Các cổ vật liên quan được chôn sâu dưới lớp trầm tích và băng có niên đại khoảng 14.000 năm trước. Trong khi nhóm kiểm tra và đánh giá khám phá này, mọi thứ bắt đầu trở nên tồi tệ: công nhân bản địa ở công trường khai quật rời đi và mất tích bất thường. Nguồn cung cấp dừng lại và những người đàn ông bắt đầu cảm thấy những tác động tâm lý và thể chất kỳ lạ, tất cả đều bị ép buộc bởi sự cô độc. Olsen và nhóm tranh luận về tính hợp lệ của việc khai quật khảo cổ. Họ chơi bài xì phé và lên kế hoạch cho sự nổi tiếng trong tương lai, nhưng lễ kỷ niệm của họ chỉ diễn ra trong thời gian ngắn. Con mèo cưng của nhóm bị giết và xuất hiện như một vật hiến tế trước hòn đá, chúng mất liên lạc vô tuyến với nền văn minh và các công nhân địa phương, mê tín và kinh hoàng, chạy trốn vào bóng tối mùa đông. Sự điên rồ và sự ngờ vực lây nhiễm cho những người đàn ông còn lại, và sau đó thì sao? Sau đó mọi thứ trở nên thực sự tồi tệ.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Shane Twerdun","avatar":""},{"name":"Michael Dickson","avatar":""},{"name":"Carl Toftfelt","avatar":""},{"name":"Marc Anthony Williams","avatar":""},{"name":"Timothy Lyle","avatar":""},{"name":"Steven Bradley","avatar":""},{"name":"Nathaniel Gordon","avatar":""},{"name":"Bryce McLaughlin","avatar":""},{"name":"Kelvin Bonneau","avatar":""},{"name":"Cameron Tremblay","avatar":""},{"name":"Andrew Moxham","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
