INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nho-dien-ro-mang-ten-tinh-yeu', 'Chuyện nhỏ điên rồ mang tên Tình Yêu', 'I Love That Crazy Little Thing', 'null', 'https://phimimg.com/upload/vod/20231129-1/fab9fb2e881e9b6b9297fe8627d34a73.jpg', '<p>I Love That Crazy Little Thing kể về câu chuyện của chàng trai &quot;số nhọ&quot; Sư Giang Dương, dính vận đen từ năm 18 tuổi, vì quá xui xẻo nên đã thực hiện một chuyến hành trình điên cuồng chu du khắp nơi tìm người giả xui. Trên đường đi anh dính vào chuyện tình với một cô nàng xinh đẹp...</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"William Chan Wai-Ting","avatar":""},{"name":"Jessica Jung","avatar":""},{"name":"Tang Yixin","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"He Jiong","avatar":""},{"name":"Seo In-guk","avatar":""},{"name":"Sun Yi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324413);
