INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-tau', 'Đào Tẩu', 'Nitro Rush', 'https://phimimg.com/upload/vod/20231125-1/0b0cfae3f4aa8c0f2ff0620d1730fe5a.jpg', 'https://phimimg.com/upload/vod/20231125-1/3a584fb37f2ca6ce1dd7f627e78f80a2.jpg', '<p>Lấy bối cảnh năm 1994, Pale Moon là câu chuyện về Rika - một phụ nữ truyền thống vốn chỉ quen ở nhà làm nội trợ và chăm sóc chồng. Nhưng cuộc sống của cô bắt đầu thay đổi khi cô quyết định đi làm bán thời gian cho một ngân hàng, trở thành nữ công sở hiện đại. Cô bắt đầu sử dụng đồng tiền vào nhiều mục đích cá nhân hơn, có thêm nhiều tham vọng. Đến một ngày, Rika ngã vào vòng tay của một cậu sinh viên trẻ trung. Mối tình vụng trộm này là khởi đầu cho nhiều bi kịch xảy đến với một người phụ nữ truyền thống đang phải thích nghi với sự thay đổi của xã hội đương thời…</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Guillaume Lemay-Thivierge","avatar":""},{"name":"Raymond Bouchard","avatar":""},{"name":"Antoine Desrochers","avatar":""},{"name":"Michel Charette","avatar":""},{"name":"Madeleine Péloquin","avatar":""},{"name":"Alexandre Goyette","avatar":""},{"name":"Antoine Olivier Pilon","avatar":""},{"name":"Jean-Nicolas Verreault","avatar":""},{"name":"Andreas Apergis","avatar":""},{"name":"Micheline Lanctôt","avatar":""},{"name":"Victor-Mauricio Pizarro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324413);
