INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-tau', 'Đào Tẩu', 'Nitro Rush', 'đào tẩu nitro rush guillaume lemay-thivierge raymond bouchard antoine desrochers michel charette madeleine péloquin alexandre goyette antoine olivier pilon jean-nicolas verreault andreas apergis micheline lanctôt victor-mauricio pizarro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tiep-vien-hang-khong-dung-cam', 'Nữ Tiếp Viên Hàng Không Dũng Cảm', 'Neerja', 'https://phimimg.com/upload/vod/20231125-1/6e92bffea36ab1db03c653996e4e625b.jpg', 'https://phimimg.com/upload/vod/20231125-1/10bbe9b391f8c2ffe2e441ca5693234a.jpg', '<p>Vào ngày 05/09/1986, chiếc phi cơ của hãng hàng không Pan Am mang số hiệu 73 bay từ Ấn Độ đến Mỹ, bị không tặc tấn công khi dừng lại quá cảnh tại sân bay ở Pakistan. Trên chuyến bay đó, mặc dù là lần đầu tiên đảm nhiệm vai trò tiếp viên trưởng, nhưng bằng nỗ lực, sự nhanh trí và lòng dũng cảm của mình, nữ tiếp viên Neerja Bhanot đã cứu sống được 359 trong số 379 hành khách và thành viên phi hành đoàn.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sonam Kapoor Ahuja","avatar":""},{"name":"Shabana Azmi","avatar":""},{"name":"Shekhar Ravjiani","avatar":""},{"name":"Yogendra Tiku","avatar":""},{"name":"Jim Sarbh","avatar":""},{"name":"Abrar Zahoor","avatar":""},{"name":"Ali Baldiwala","avatar":""},{"name":"Kavi Shastri","avatar":""},{"name":"Waqar Khan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
