INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-quan-shadwell', 'Đội Quân Shadwell', 'ID2: Shadwell Army', 'https://phimimg.com/upload/vod/20231125-1/cc4a06122cd84f38425c960dffd02fa7.jpg', 'https://phimimg.com/upload/vod/20231125-1/50572ad03d070705b61af00e3c857b7b.jpg', '<p>Phim Đội Quân Shadwell - ID2: Shadwell Army 2016: Mo - một chàng trai lai Anh - Á, một sĩ quan cảnh sát thăng tiến nhanh tham gia nằm vùng trong các phần tử cực đoan muốn hồi sinh Shadwell - những kẻ được truyền lửa bởi sự tiếp quản của Shadwell và một tên đầu sỏ người Nga muốn thống trị Châu Âu. Trong quá trình nằm vùng, Mo nhận ra có nhiều ẩn khuất sau nhiệm vụ này và tự đặt ra nhiều câu hỏi về nơi mình thật sự thuộc về.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Simon Rivers","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Paul Popplewell","avatar":""},{"name":"Andy Rush","avatar":""},{"name":"Neil Pearson","avatar":""},{"name":"Benjamin Harris","avatar":""},{"name":"Lee Ross","avatar":""},{"name":"Duncan Airlie James","avatar":""},{"name":"Christine Tremarco","avatar":""},{"name":"Perry Fenwick","avatar":""},{"name":"Richard Graham","avatar":""},{"name":"Shahid Ahmed","avatar":""},{"name":"Naveed Choudhry","avatar":""},{"name":"Sylwia Kaczmarek","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324413);
