INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-thien-dai-nghich-chuyen', 'Kinh Thiên Đại Nghịch Chuyển', 'Tik Tok', 'https://phimimg.com/upload/vod/20231125-1/360fd3f6d521471b13e1bffd52c28fd5.jpg', 'https://phimimg.com/upload/vod/20231125-1/75162f0ccf743c10c4d9054ac850883c.jpg', '<p>Trong phim, một trận chung kết bóng đá châu Á giữa Trung Quốc và Hàn Quốc sắp diễn ra tại Seoul. Lúc này, vợ của một cầu thủ bị bắt cóc và Kang Seung-joon (Lee Jung-jae đóng) được cử điều tra vụ án. Anh biết rằng có thể tìm thấy thông tin của kẻ tống tiền ở văn phòng của nhà tâm lý học Yang Xi (Yang Yueting), vì kẻ tống tiền Guo Zhida (Wallace Chung) đang điều trị tâm lý ở đây. Bây giờ, anh ta đặt cược vào trò chơi bóng đá và muốn giành chiến thắng bằng mọi cách, đó là lý do tại sao anh ta bắt cóc vợ của cầu thủ này.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Wallace Chung","avatar":""},{"name":"Lang Yueting","avatar":""},{"name":"Lee Chae-young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
