INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kizumonogatari-phan-1-thiet-huyet', 'Kizumonogatari Phần 1: Thiết Huyết', 'Kizumonogatari Part 1: Tekketsu', 'https://phimimg.com/upload/vod/20231125-1/6230cb8edc8615ea472d93bc1a733dc9.jpg', 'https://phimimg.com/upload/vod/20231125-1/7e73d7566b35d9f5bcf3c127ccb8a9c4.jpg', '<p>Koyomi Araragi, một học sinh trung học năm thứ hai tại trường trung học Naoetsu, kết bạn với Tsubasa Hanekawa, học sinh giỏi đứng đầu tại trường học của mình. Tsubasa nói đến một tin đồn về &quot;ma cà rồng tóc vàng&quot; đã có người nhìn thấy xung quanh thị trấn của họ gần đây. Koyomimột người thích làm chuyện không giống ai bắt đàu tìm hiểu Buổi tối hôm đó, Koyomi gặp ma cà rồng tin đồn này cố ấy tên là Kiss-shot và cô gái tóc vàng gào to với Koyomi để cứu cô khi cô nằm trong một vũng máu của mình, cả bốn chân tay của cô bị cắt đứt. Kiss-shot nói với Koyomi cho cô ấy máu của mình để cứu cuộc sống cô, và khi cậu làm xong và tỉnh dậy, Koyomi thấy mình.....</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Masashi Ebara","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Hochu Otsuka","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
