INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kizumonogatari-phan-1-thiet-huyet', 'Kizumonogatari Phần 1: Thiết Huyết', 'Kizumonogatari Part 1: Tekketsu', 'kizumonogatari phần 1: thiết huyết kizumonogatari part 1: tekketsu hiroshi kamiya maaya sakamoto yui horie takahiro sakurai masashi ebara miyu irino hochu otsuka ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-hoan-hao', 'Người Lạ Hoàn Hảo', 'Perfect Strangers', 'https://phimimg.com/upload/vod/20231125-1/e9632f54b5354c8303967dde10a71b4a.jpg', 'https://phimimg.com/upload/vod/20231125-1/70782c1bd65db73c6ae2d9ac814e01a6.jpg', '<p>Phim nói về câu chuyện của 7 người bạn chơi thân từ thuở nhỏ khi họ đang tụ tập ăn tối với nhau. Họ quyết định chơi một trò chơi vui là đặt tất cả điện thoại của mọi người lên bàn và tất cả sẽ phải công khai tất cả những cuộc gọi và tin nhắn gửi cho mình trong suốt buổi tối. Mục đích của trò chơi vui này là để chứng minh rằng không có ai che giấu bạn bè mình điều gì.
 Và bộ phim bắt đầu kịch tính từ đây khi những bí mật đời tư của mọi người dần dần được hé lộ, các tình huống dần trở nên phức tạp và liên kết chặt với nhau. Bảy người bạn giờ đây cứ như những người xa lạ với nhau. Những ánh mắt nghi ngờ và sự đau khổ từ từ được phơi bày.
 Những tình tiết trong phim chủ yếu được gói gọn trong căn nhà nhỏ với 7 nhân vật chính. Nhưng những tình tiết mới xuất hiện liên tục đã giữ được sự kịch tính cho bộ phim.
 Bộ phim mang đến cho khán giả cảm giác trần trụi về bộ mặt thật của con người đằng sau những nụ cười thân thiện.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Giuseppe Battiston","avatar":""},{"name":"Anna Foglietta","avatar":""},{"name":"Marco Giallini","avatar":""},{"name":"Edoardo Leo","avatar":""},{"name":"Valerio Mastandrea","avatar":""},{"name":"Alba Rohrwacher","avatar":""},{"name":"Kasia Smutniak","avatar":""},{"name":"Benedetta Porcaroli","avatar":""},{"name":"Elisabetta De Palo","avatar":""},{"name":"Tommaso Tatafiore","avatar":""},{"name":"Noemi Pagotto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
