INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha-mau-muc', 'Người Cha Mẫu Mực', 'A Family Man', 'https://phimimg.com/upload/vod/20231125-1/bae3509a871d8c0cf7cbc4ed1b542036.jpg', 'https://phimimg.com/upload/vod/20231125-1/e8cb8a9603247e0120496ded769f4842.jpg', '<p>Dane Jensen là một chuyên viên tuyển dụng quyết đoán với mục tiêu được giao quyền tiếp quản công ty anh đang làm việc. Trong nhiệm vụ cuối cùng trước khi đánh giá, Dane phải đối đầu với một nữ đồng nghiệp tài năng nhưng cũng rất khó lường, để chạy đua vào vị trí cao nhất. Đúng lúc này, cậu con trai 10 tuổi của anh được chẩn đoán mắc bệnh ung thư. Những ưu tiên về sự nghiệp và gia đình của Dane mâu thuẫn gay gắt, anh buộc phải đưa ra lựa chọn từ bỏ một trong hai.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Gretchen Mol","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Julia Butters","avatar":""},{"name":"Maxwell Jenkins","avatar":""},{"name":"Kathleen Munroe","avatar":""},{"name":"Mayko Nguyen","avatar":""},{"name":"Mimi Kuzyk","avatar":""},{"name":"Stephen Bogaert","avatar":""},{"name":"Sierra Wooldridge","avatar":""},{"name":"Dwain Murphy","avatar":""},{"name":"Jimi Shlag","avatar":""},{"name":"Sadie Munroe","avatar":""},{"name":"Ric","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
