INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dua-ruc-lua-2', 'Đường Đua Rực Lửa 2', 'Børning 2', 'https://phimimg.com/upload/vod/20231125-1/0940afff8515339128e6a5365198b019.jpg', 'https://phimimg.com/upload/vod/20231125-1/ea30b639d1bf196cb8252a18bb5c564f.jpg', '<p>Sau hai năm tù vì tham gia một cuộc đua đường phố bất hợp pháp, Roy nói rằng không với một cuộc đua mùa đông bất hợp pháp mới từ Bergen đến Murmansk ở phía bắc nước Nga. Nhưng sau đó anh nghe thấy rằng con gái anh sẽ tham gia với bạn trai.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Anders Baasmo Christiansen","avatar":""},{"name":"Ida Husøy","avatar":""},{"name":"Jonas Hoff Oftebro","avatar":""},{"name":"Vegar Hoel","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Sven Nordin","avatar":""},{"name":"Otto Jespersen","avatar":""},{"name":"Henrik Mestad","avatar":""},{"name":"Mikkel Gaup","avatar":""},{"name":"Arthur Berning","avatar":""},{"name":"Jenny Skavlan","avatar":""},{"name":"Robert Skjærstad","avatar":""},{"name":"Marie Blokhus","avatar":""},{"name":"Ravdeep Singh Bajwa","avatar":""},{"name":"Fredrik Skogsrud","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324413);
