INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ms-dhoni-chuyen-chua-ke', 'M.S. Dhoni: Chuyện Chưa Kể', 'M.S. Dhoni: The Untold Story', 'https://phimimg.com/upload/vod/20231125-1/c62b52638e59bc34f3b503c5e60ee81f.jpg', 'https://phimimg.com/upload/vod/20231125-1/e08d063a5fd851a3e845479977d563f9.jpg', '<p>Phim M.S. Dhoni: Chuyện Chưa Kể - M.S. Dhoni: The Untold Story 2017: Trong phim, cô gái trẻ xinh đẹp Disha, vào vai Priyanka Jha - bạn gái quá cố của Mahendra, tình yêu đầu tiên của anh và cũng là người truyền cho anh sức mạnh trên con đường sự nghiệp. Mahendra thậm chí đã quyết định sẽ kết hôn với Priyanka. Thật không may, vào năm 2002, một tai nạn thảm khốc đã cướp đi sinh mạng của Priyanka Jha trong khi Mahendra đang đi du đấu tại nước ngoài mà ko hề hay biết người mình yêu đã mất. Trở về từ giải đấu quốc tế, Mahendra nhận được tin buồn và vô cùng suy sụp, sau đó, anh quyết tâm lấy lại phong độ và phá vỡ nhiều kỷ lục đáng nể của bộ môn Cricket, vươn lên trở thành một trong những vận động viên Cricket thành công nhất trong lịch sử Cricket Ấn Độ.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sushant Singh Rajput","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Disha Patani","avatar":""},{"name":"Kiara Advani","avatar":""},{"name":"Rajesh Sharma","avatar":""},{"name":"Kumud Mishra","avatar":""},{"name":"Neetha Mohindra","avatar":""},{"name":"Bhumika Chawla","avatar":""},{"name":"Mithu Chakrabarty","avatar":""},{"name":"Shantilal Mukherjee","avatar":""},{"name":"Kali Prasad Mukherjee","avatar":""},{"name":"Kranti Prakash Jha","avatar":""},{"name":"Ravindra Mankani","avatar":""},{"name":"Kiran More","avatar":""},{"name":"Herry Tangiri","avatar":""},{"name":"Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
