INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ms-dhoni-chuyen-chua-ke', 'M.S. Dhoni: Chuyện Chưa Kể', 'M.S. Dhoni: The Untold Story', 'm.s. dhoni: chuyện chưa kể m.s. dhoni: the untold story sushant singh rajput anupam kher disha patani kiara advani rajesh sharma kumud mishra neetha mohindra bhumika chawla mithu chakrabarty shantilal mukherjee kali prasad mukherjee kranti prakash jha ravindra mankani kiran more herry tangiri ra ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-ngu-cua-florence', 'Nơi Ngủ Của Florence', 'Where Florence Sleeps', 'https://phimimg.com/upload/vod/20231206-1/d0a16bd67d856f3bc317f5a95638bc41.jpg', 'https://phimimg.com/upload/vod/20231206-1/0409ae30fb2f1d7ef47f6a181ff6eae5.jpg', '<p>Hideki Sato, người thừa kế của một công ty gia đình về hóa chất bị bắt cóc. Tiền chuộc là Nước mắt của Florence, một viên kim cương huyền thoại đã bị thất lạc từ lâu. Chủ tịch của công ty, cha Hideki Sato, từ chối yêu cầu tiền chuộc này và sẵn sàng hy sinh mạng sống của con trai mình. Điều này đã gây ra một loạt các sự kiện bởi những kẻ bắt cóc, một cuộc đảo chính từ bên trong công ty, và đưa ra ánh sáng về quá khứ bí ẩn của Nước mắt Florence.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Mansaku Ikeuchi","avatar":""},{"name":"Mikihisa Azuma","avatar":""},{"name":"Ryo Fujimoto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324413);
