INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-tin-vui', 'Nhà Có Tin Vui', 'All''s Well End''s Well extended', 'https://phimimg.com/upload/vod/20231205-1/754f5e412a0eac206f3823960e686373.jpg', 'https://phimimg.com/upload/vod/20231205-1/4e684c3a1a4a98b768f29d3f44a57b90.jpg', '<p>Nhà Có Tin Vui - Alls Well Ends Well extended là bộ phim hài hước kể về ba anh em nhà họ Chang, mỗi người một tính cách, mỗi người có một câu chuyện, một vấn đề rắc rối riêng. Họ gồm: một ông anh cả ngoại tình, cậu hai đa tình và cậu út ‘ẻo lả... kéo theo nhiều mâu thuẫn gia đình liên tục xảy ra cùng với những tình tiết hài hước thú vị đan xen lẫn lộn... Thông qua bộ phim, khán giả sẽ có những giây phút thư giãn nhưng cũng đầy sâu lắng về tình yêu, tình cảm gia đình.</p>', 'Full', 1, 'single', 'completed', 7, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raymond Wong","avatar":""},{"name":"Sandra Ng","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Stephen Chow","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
