INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-rut-lui-lang-le', 'Sự Rút Lui Lặng Lẽ', 'Silent Retreat', 'https://phimimg.com/upload/vod/20231125-1/4a1069c786b4c9a85a3382ea276b87cf.jpg', 'https://phimimg.com/upload/vod/20231125-1/2adcfd66fa2da56f66e4f2a2431fa33b.jpg', '<p>Sáu thành viên của một công ty truyền thông đi nghỉ việc vào cuối tuần tại một nhà nghỉ biệt lập trong rừng. Khi một trong những thành viên mất tích, họ phát hiện ra rằng nhà nghỉ này trước đây là một viện tâm thần tư nhân. Từng người một, họ trở thành nạn nhân của những bí mật đen tối được chôn cất tại nhà nghỉ.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Donny Boaz","avatar":""},{"name":"Rebecca Summers","avatar":""},{"name":"Danilo Di Julio","avatar":""},{"name":"Eli Bildner","avatar":""},{"name":"Devon Ogden","avatar":""},{"name":"Aidan Flynn","avatar":""},{"name":"Trista Robinson","avatar":""},{"name":"Landon Ashworth","avatar":""},{"name":"John Kerry","avatar":""},{"name":"Circus-Szalewski","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
