INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-mac-nhuom-mau', 'Sa Mạc Nhuốm Máu', 'Desierto', 'https://phimimg.com/upload/vod/20231124-1/0aa1326e5afb35876927f1a5d5db0655.jpg', 'https://phimimg.com/upload/vod/20231124-1/ad7e9822f94ae2610f323d302d96f0db.jpg', '<p>Phim Sa Mạc Nhuốm Máu - Desierto 2016: Một nhóm người có ý định vượt qua biên giới Mexico và Mỹ phải đối mặt với một kẻ canh gác biên giới phân biệt chủng tộc.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gael García Bernal","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Diego Cataño","avatar":""},{"name":"Marco Pérez","avatar":""},{"name":"Alondra Hidalgo","avatar":""},{"name":"Oscar Flores","avatar":""},{"name":"David Lorenzo","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Butch McCain","avatar":""},{"name":"Claudia Angélica Amador Castellanos","avatar":""},{"name":"Dolores Micaela Guzmán Méndez","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
