INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-young-offenders', 'The Young Offenders', 'The Young Offenders', 'https://phimimg.com/upload/vod/20231124-1/48dce91112ad384eec2d61317fa850b3.jpg', 'https://phimimg.com/upload/vod/20231124-1/0ae9e2482d1b3e1af783f5a812fe9fb8.jpg', '<p>Lấy cảm hứng từ câu chuyện có thật về cocaine cocaine lớn nhất của Ireland năm 2007, những kẻ phạm tội trẻ tuổi là một bộ phim hài về bộ phim hài về những người bạn tốt nhất Conor và Jock, hai thanh thiếu niên thành phố bên trong từ Cork, người ăn mặc giống nhau, hành động tương tự, và thậm chí có cùng một tiếng bum -Fluff ria mép. Jock là một tên trộm xe đạp huyền thoại chơi một trò chơi hàng ngày của mèo và chuột với Trung sĩ Garda bị ám ảnh bởi người đi xe đạp. Khi một chiếc thuyền buôn bán ma túy capsizes ra khỏi bờ biển phía tây và 61 kiện cocaine, mỗi người trị giá 7 triệu euro, bị tịch thu, từ thoát ra rằng có một chút mất tích. Các chàng trai ăn cắp hai chiếc xe đạp và đi trên một chuyến đi trên đường với hy vọng tìm thấy một kiện bị mất tích mà họ có thể bán để thoát khỏi cuộc sống trong nhà gặp khó khăn của họ .... Nhưng Trung sĩ Healy đang theo đuổi nóng bỏng.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Alex Murphy","avatar":""},{"name":"Chris Walley","avatar":""},{"name":"Hilary Rose","avatar":""},{"name":"Dominic MacHale","avatar":""},{"name":"Ciaran Bermingham","avatar":""},{"name":"Pascal Scott","avatar":""},{"name":"Judy Donovan","avatar":""},{"name":"Shane Casey","avatar":""},{"name":"P.J. Gallagher","avatar":""},{"name":"Cora Fenton","avatar":""},{"name":"Emma Willis","avatar":""},{"name":"Frank Prendergast","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
