INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-young-offenders', 'The Young Offenders', 'The Young Offenders', 'the young offenders the young offenders alex murphy chris walley hilary rose dominic machale ciaran bermingham pascal scott judy donovan shane casey p.j. gallagher cora fenton emma willis frank prendergast ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-thoi-loan', 'Tình Thời Loạn', 'Colonia', 'https://phimimg.com/upload/vod/20231124-1/d25194fc032b8ed7978abddc2f05cc0d.jpg', 'https://phimimg.com/upload/vod/20231124-1/d6764bc2af881262413f1a0708adc617.jpg', '<p>Phim Tình Thời Loạn - Colonia 2016: Emma vào vai một phụ nữ trẻ trà trộn vào một tổ chức giáo phái nguy hiểm để cứu bạn trai mình. Bộ phim còn có sự tham gia của nam diễn viên Daniel Bruhl. Colonia lấy bối cảnh Chile năm 1973, tiếp viên hàng không của hãng Lufthansa là Lena đã đáp chuyến bay đến Santiago để thăm bạn trai Daniel. Daniel là một nhiếp ảnh gia tài năng ủng hộ chính quyền của Tổng thống Salvador Allende. Khi Allende bị đảo chính lật đổ, lực lượng của tướng Augusto Pinochet lên nắm quyền tạo ra nhiều mâu thuẫn lớn. Daniel bắt bắt giữ, giam cầm ở Colonia Dignidad _ trụ sở của một giáo phái bí mật vô cùng nguy hiểm, bệnh hoạn do tướng Paul Schäfer đứng đầu. Ở đây Daniel bị thẩm vấn, tra tấn dã man. Lena buộc phải đi tới Colonia, giả vờ là một tín đồ xin gia nhập giáo phái của Paul Schäfer nhằm tìm kiếm và cứu thoát bạn trai. Nhưng cô lại phải đối mặt với nhiều thử thách kinh hoàng khác của Paul. Với các trailer đã được tung ra, Colonia bước đầu có được nhiều phản hồi tích cực vì không khí phim kịch tính và câu chuyện gây tò mò. Mời các bạn đón xem phim hay này.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Emma Watson","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Michael Nyqvist","avatar":""},{"name":"Richenda Carey","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Jeanne Werner","avatar":""},{"name":"Julian Ovenden","avatar":""},{"name":"August Zirner","avatar":""},{"name":"Martin Wuttke","avatar":""},{"name":"César Bordón","avatar":""},{"name":"Nicolás Barsoff","avatar":""},{"name":"Steve Karier","avatar":""},{"name":"Stefan Merki","avatar":""},{"name":"Lucila Gandolfo","avatar":""},{"name":"Johannes Allmayer","avatar":""},{"name":"Gilles Soeder","avatar":""},{"name":"Katharina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324413);
