INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-hang', 'Người Bán Hàng', 'The Salesman', 'https://phimimg.com/upload/vod/20231124-1/bd05e604284fcc7755f7409be1288220.jpg', 'https://phimimg.com/upload/vod/20231124-1/b6259d8cd8c8a12fc11adef4fae9de36.jpg', '<p>Người Bán Hàng có nội dung chính xoay quanh câu chuyện về đôi vợ chồng trẻ Emad và Rana, những người đóng vai chính trong một vở kịch địa phương &quot;Death of a Salesman của Arthur Miller&quot;. Bị buộc phải rời khỏi căn nhà mà họ đã từng sinh sống một thời gian dài, hai người đã thuê một căn hộ mới mà chủ sở hữu là một trong số những đồng nghiệp làm cùng công ty. Họ không biết rằng căn nhà mình đang thuê trước đây đã được một người phụ nữ mại dâm hành nghề. Nơi đây đã trở thành địa điểm quen thuộc của vài khách quen của cô ta. Trong một hôm, Rena đang tắm thì có người đàn ông lạ vào nhà, đúng lúc ấy chồng cô từ bên ngoài trở về trông thấy. Những câu chuyện bi hài đã bắt đầu làm cho bộ phim trở nên hấp dẫn hơn bao giờ ...</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Shahab Hosseini","avatar":""},{"name":"Taraneh Alidoosti","avatar":""},{"name":"Babak Karimi","avatar":""},{"name":"Mina Sadati","avatar":""},{"name":"Mehdi Koushki","avatar":""},{"name":"Farid Sajjadi Hosseini","avatar":""},{"name":"Maral Bani Adam","avatar":""},{"name":"Mojtaba Pirzadeh","avatar":""},{"name":"Sam Valipour","avatar":""},{"name":"Shirin Aghakashi","avatar":""},{"name":"Emad Emami","avatar":""},{"name":"Sahra Asadollahe","avatar":""},{"name":"Ehteram Boroumand","avatar":""},{"name":"Erfan Barzin","avatar":""},{"name":"Alireza Rofougaran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
