INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-mai-sau', 'Chuyện Mai Sau', 'Things to Come', 'https://phimimg.com/upload/vod/20231123-1/602cdb74faf69b3b9c25d44bf9b1c83f.jpg', 'https://phimimg.com/upload/vod/20231123-1/152cd501cd42ab72fab091c22a53a36c.jpg', '<p>Nathalie dạy triết học tại một trường trung học ở Paris. Cô ấy đam mê công việc của mình và đặc biệt thích truyền lại niềm vui khi được suy nghĩ. Đã kết hôn và có hai con, cô chia thời gian của mình cho gia đình, học sinh cũ và người mẹ rất chiếm hữu của mình. Một ngày nọ, chồng của Nathalie thông báo rằng anh ấy sẽ bỏ cô để theo một người phụ nữ khác. Với sự tự do ập đến, Nathalie phải làm lại cuộc đời mình.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Isabelle Huppert","avatar":""},{"name":"André Marcon","avatar":""},{"name":"Roman Kolinka","avatar":""},{"name":"Edith Scob","avatar":""},{"name":"Sarah Le Picard","avatar":""},{"name":"Solal Forte","avatar":""},{"name":"Élise Lhomeau","avatar":""},{"name":"Lionel Dray","avatar":""},{"name":"Yves Heck","avatar":""},{"name":"Grégoire Montana-Haroche","avatar":""},{"name":"Lina Benzerti","avatar":""},{"name":"Guy-Patrick Sainderichin","avatar":""},{"name":"Rachel Arditi","avatar":""},{"name":"Charline Bourgeois-Tacquet","avatar":""},{"name":"Linus Westheuser","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
