INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ga-mo', 'Đặc Vụ Gà Mờ', 'Ratchet & Clank', 'https://phimimg.com/upload/vod/20231123-1/1cd5a5dd485e2be44b0250d7b9f00fcc.jpg', 'https://phimimg.com/upload/vod/20231123-1/dc0936cbbd0053c28f7dac723c82c2ac.jpg', '<p>Phim Đặc Vụ Gà Mờ - Ratchet And Clank 2016: đưa người xem đến với vũ trụ Solana xa xôi. Mọi thứ đều yên bình cho đến khi Chairman Drek và món vũ khí hủy diệt của y xuất hiện. Với ý đồ điên rồ là phá hủy mọi hành tinh trong vũ trụ Solana, y âm thầm xây dựng cho mình một đội quân đông đảo và thiên chiến. Nắm được thông tin này, Ratchet và người bạn mới của mình là chú robot Clank phải tìm cách cảnh báo cho lực lượng vệ binh Galactic Rangers nhằm chặn đứng âm mưu này.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Arnold Taylor","avatar":""},{"name":"David Kaye","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Bella Thorne","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Jim Ward","avatar":""},{"name":"Armin Shimerman","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Andrew Cownden","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Brian Dobson","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Brad Swaile","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Cole Howar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324413);
