INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-ga-mo', 'Đặc Vụ Gà Mờ', 'Ratchet & Clank', 'đặc vụ gà mờ ratchet & clank james arnold taylor david kaye paul giamatti john goodman bella thorne rosario dawson jim ward armin shimerman vincent tong andrew cownden sylvester stallone lee tockar brian dobson tabitha st. germain brad swaile brian drummond cole howar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suyt-thi-cuoi', 'Suýt Thì Cưới', 'Nearly Married', 'https://phimimg.com/upload/vod/20231204-1/5c2167befd9d111661381e338a8b420e.jpg', 'https://phimimg.com/upload/vod/20231204-1/8feccc8cc25d1295893c17c4e759947f.jpg', '<p>Maddie Brooks sống ở thành phố New York và làm một công việc nhàm chán. Cô vừa chia tay Cooper vị hôn phu lừa dối và người yêu thời trung học. Chìm trong nỗi buồn, cô chợt hồi tưởng về Bobby Browning, người cô thầm thương trộm nhớ thời thơ ấu. Cô tìm kiếm thông tin của Bobby trên Googles và phát hiện ra anh ta bây giờ là một nhiếp ảnh gia thành công và sẽ trở về quê nhà để quảng bá các tác phẩm của mình. Maddie nhận ra cô đã chọn nhầm anh chàng ở trường trung học, và quyết định trở về quê để quyết định lại. Tuy nhiên, cô phát hiện ra rằng Bobby hiện đang đính hôn với Blake và họ sẽ kết hôn sớm. Quyết tâm nhen nhóm ngọn lửa cũ với Bobby, và không cho ai biết cuộc sống bi thảm của cô, Maddie tuyên bố rằng cô cũng sắp kết hôn. Ngay lập tức tất cả bạn bè của cô, bao gồm Bobby và Blake, giúp cô chuẩn bị cho một đám cưới sẽ không bao giờ ...</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cassi Thomson","avatar":""},{"name":"Jen Lilley","avatar":""},{"name":"Matt Dallas","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
