INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-tren-vu-tru', 'Giáng Sinh Trên Vũ Trụ', 'Dogstar: Christmas in Space', 'https://phimimg.com/upload/vod/20231204-1/81b4eb8f522f2824d989523de09a99e0.jpg', 'https://phimimg.com/upload/vod/20231204-1/03fb96a8d0a7e82b21590bde508aaed2.jpg', '<p>Giáng Sinh Trên Vũ Trụ - Dogstar: Christmas in Space là bộ phim hoạt hình vui nhộn, xoay quanh câu chuyện về các chú chó. Một ngày, tất cả những chú chó trên thế giới bỗng nhiên bị lạc trong không gian vũ trụ. Vì vậy, những đứa trẻ ở Clark có nhiệm vụ phải tìm chúng và đưa tất cả về nhà an toàn trước Giáng sinh.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
