INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-tiec-cuoi-cung', 'Buổi Tiệc Cuối Cùng', 'End Of Days', 'https://phimimg.com/upload/vod/20231204-1/73489ef983402b2d03ccd2634d8afba2.jpg', 'https://phimimg.com/upload/vod/20231204-1/c1df2f5ffa36283a29793e2e0fdc28d8.jpg', '<p>Theo lời hứa hẹn ngon ngọt của gã Giám Đốc Godfrey và cô em gái nguy hiểm của hắn, trước ngày giải thể đóng cửa công ty, chỉ cần tất cả nhân viên tham dự bữa tiệc chia tay sẽ được nhận số tiền thưởng kếch xù. Nhưng ẩn dưới đêm tiệc xa hoa là một âm mưu khác được che đậy, chúng không hề muốn chia tiền cho bất kỳ ai, với cám dỗ của đồng tiền và sự uy hiếp, họ chấp nhận làm việc thâu đêm xử lý hết những công việc đang tồn kho nhưng nó lại là ngòi nổ dẫn đến hậu quả khó lường.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark O''Brien","avatar":""},{"name":"Paulino Nunes","avatar":""},{"name":"Carolyne Maraghi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
