INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-thanh-tiem-ba-huyet-chien', 'Nguy Thành Tiêm Bá - Huyết Chiến', 'Call of Heroes', 'https://phimimg.com/upload/vod/20231121-1/6a0121752a68e61710423d438bcfebf3.jpg', 'https://phimimg.com/upload/vod/20231121-1/fb2ee629be48272285fb5fddebecf012.jpg', '<p>Phim lấy bối cảnh vào thời kỳ loạn lạc, nội chiến liên miên, thiếu tướng Tào Thiếu Lân (Cổ Thiên Lạc) vì vô cớ giết chết ba người dân vô tội của Phổ thành nên bị Dương Khắc Nan (Lưu Thanh Vân) đứng đầu Phổ thành bắt nhốt. Thượng tá của Tào gia – Trương Diệc (Ngô Kinh) biết chuyện, liền đem quân đến Phổ thành đòi người.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Maggie Jiang","avatar":""},{"name":"Yuan Quan","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Berg Ng","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Sammy Hung","avatar":""},{"name":"Chen Shengwei","avatar":""},{"name":"He Gang","avatar":""},{"name":"Wang Shengli","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Chun Kit Chang","avatar":""},{"name":"Edward Ma","avatar":""},{"name":"Sula Wenya","avatar":""},{"name":"Long De","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
