INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-tai-quai-vat', 'Xe Tải Quái Vật', 'Monster Trucks', 'https://phimimg.com/upload/vod/20231121-1/747f246ecf93a103f9caf799fa2d5a91.jpg', 'https://phimimg.com/upload/vod/20231121-1/8a3358804ebf60a1e80af31b28de66c7.jpg', '<p>Tripp, nam sinh năm cuối trung học có sở trường chế tạo xe tải, đã có một phát hiện đáng kinh ngạc - một sinh vật thích uống xăng tên là Creech. Để bảo vệ người bạn mới tinh nghịch, Tripp đã giấu Creech trong chiếc xe mới sáng chế của mình, biến nó thành Xe Tải Quái Vật siêu năng lực có thực! Bộ đôi bất đắc dĩ mê tốc độ này cùng hợp sức trong một cuộc hành trình hoang dã và khó quên để đưa Creech về với gia đình. Xe Tải Quái Vật là một cuộc phiêu lưu vui nhộn, hài hước và chân thành không bao giờ chậm lại.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lucas Till","avatar":""},{"name":"Jane Levy","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Rob Lowe","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Aliyah O''Brien","avatar":""},{"name":"Tucker Albrizzi","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Daniel Bacon","avatar":""},{"name":"Faustino Di Bauda","avatar":""},{"name":"Jedidiah Goodacre","avatar":""},{"name":"Chris Gauthier","avatar":""},{"name":"Scott Patey","avatar":""},{"name":"Ryan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vi