INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-va-cong-ly', 'Sự Thật Và Công Lý', 'Truth And Justice', 'https://phimimg.com/upload/vod/20231203-1/370b62dbc6e20bd382fc149f3fddbdfc.jpg', 'https://phimimg.com/upload/vod/20231203-1/9e0de35bae805af591fac63c714f3d10.jpg', '<p>Là một thám tử kì cựu và không khoan nhượng với bất cứ kẻ bất lương nào, Marcus Williams không hề tình nguyện làm việc với linh mục đầy lòng trắc ẩn Samuel Gray. Hai người họ thuộc hai thái cực hoàn toàn đối lập nhau, mỗi người có một cách tiếp cận khác nhau với những đứa trẻ trên phố, nhưng lại được lập thành bộ đôi để giải quyết vụ án mạng của một thiếu niên trong vùng...</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Cleveland","avatar":""},{"name":"Kevin Nichols","avatar":""},{"name":"Laura Avnaim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324413);
