INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-ngam', 'Luật Ngầm', 'Live by Night', 'https://phimimg.com/upload/vod/20231123-1/77499db7b811e079541b2826990a0110.jpg', 'https://phimimg.com/upload/vod/20231123-1/14766bd372d3b4d46c0f75ac037939bc.jpg', '<p>Bộ phim Live By Night 2016 xoay quanh con trai của một sĩ quan cảnh sát cao cấp ở Boston, Joe Coughlin (do chính Ben Affeck thủ vai). Anh gia nhập quân đội để tham gia chiến đấu ở nước ngoài, phục vụ đất nước, nhưng anh chóng nhận ra mình đã ảo tưởng về cuộc chiến tranh mà anh tham gia. Cuối cùng anh trở về và tiếp tục trong một cuộc sống mà anh chưa bao giờ mong đợi…để rồi phải trả giá đắt cho một “giấc mơ Mỹ”.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Titus Welliver","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Robert Glenister","avatar":""},{"name":"Chris Sullivan","avatar":""},{"name":"J.D. Evermore","avatar":""},{"name":"Tom Virtue","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Bruno Amato","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
