INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-an-than', 'Hàng Xóm Ẩn Thân', 'The Good Neighbor', 'https://phimimg.com/upload/vod/20231120-1/1eac9eebd1d6a34d78db2ef2941efc4d.jpg', 'https://phimimg.com/upload/vod/20231120-1/9e7e9f325a3d9334e9aa771fdaab4a50.jpg', '<p>Ethan và Sean là thiếu niên am hiểu công nghệ, 2 cậu quyết định thử nghiệm chương trình của mình lên người hàng xóm của họ là Harold Grainey, bằng cách thuyết phục ông rằng nhà ông là bị ma ám. Khi Grainey rời khỏi nhà vào một buổi chiều, cả hai đã lắp đặt thiết bị để mô phỏng những ám ảnh, cũng như các hình ảnh rùng rợn để xem phản ứng Grainey. Nhưng cả 2 đứa đã nhầm, khi Ethan và Sean sớm nhận ra sai lầm chết người khi đã chọn Grainey làm mục tiêu.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Miller","avatar":""},{"name":"Keir Gilchrist","avatar":""},{"name":"James Caan","avatar":""},{"name":"Bailey Noble","avatar":""},{"name":"Lili Reinhart","avatar":""},{"name":"Nik Dodani","avatar":""},{"name":"Laura Innes","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"Anne Dudek","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Tamlyn Tomita","avatar":""},{"name":"Dean Cameron","avatar":""},{"name":"William Charles Mitchell","avatar":""},{"name":"Billy Khoury","avatar":""},{"name":"Ted King","avatar":""},{"name":"Luke Spencer Roberts","avatar":""},{"name":"Elyse Dinh","avatar":""},{"name":"Hanna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]',