INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-dem-giang-sinh-2', 'Ác Mộng Đêm Giáng sinh 2', 'Krampus 2', 'https://phimimg.com/upload/vod/20231120-1/6612800ab6fc479732ecfdd70436871f.jpg', 'https://phimimg.com/upload/vod/20231120-1/dcd6ae17ea680f3d26d3ae61e13f2cea.jpg', '<p>Con quái vật Krampus đã trở lại để trừng phạt những đứa trẻ xấu trong một thị trấn nhỏ ở Pennsylvania. Đội ngũ cảnh sát và cựu nhân viên đã cố gắng chiến đấu để bảo vệ kỳ nghỉ của Giáng sinh một cách trọn vẹn nhưng đó quả là một nhiệm vụ khó khăn hơn họ nghĩ.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shawn C. Phillips","avatar":""},{"name":"Melantha Blackthorne","avatar":""},{"name":"R.A. Mihailoff","avatar":""},{"name":"Tiffani Fest","avatar":""},{"name":"Jason Hull","avatar":""},{"name":"A.J. Leslie","avatar":""},{"name":"Darren Barcomb","avatar":""},{"name":"Michael Mili","avatar":""},{"name":"Richard Goteri","avatar":""},{"name":"Robbie Barnes","avatar":""},{"name":"Paul Ferm","avatar":""},{"name":"Daniel James","avatar":""},{"name":"Darin Foltz","avatar":""},{"name":"Ben Berlin","avatar":""},{"name":"Johnny Stevenson","avatar":""},{"name":"Max Nicolussi","avatar":""},{"name":"Bill Kennedy","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324413);
