INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruong-bo', 'Ruồng Bỏ', 'Julieta', 'https://phimimg.com/upload/vod/20231120-1/bde17bc758f3a0d06d3a2477e0b6687f.jpg', 'https://phimimg.com/upload/vod/20231120-1/062d8c77bee56a9e7dd061cb684be3d8.jpg', '<p>Tác phẩm mở đầu tại thành phố Madrid của Tây Ban Nha, nơi người mẹ cô độc Julieta đang cố gắng quên đi Antía - đứa con gái đã rời bỏ bà từ năm 18 tuổi. Trên đường đi mua sắm, bà tình cờ gặp Beatriz, bạn học thời thơ ấu của con mình và nhận được tin Antía hiện đã có ba đứa con. Nỗi đau sâu thẳm trong trái tim Julieta một lần nữa trỗi dậy trước tin tức về con. Julieta bắt đầu hồi tưởng lại chuỗi quá khứ đầy bi kịch khiến cô con gái duy nhất rời khỏi vòng tay của bà...</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Emma Suárez","avatar":""},{"name":"Adriana Ugarte","avatar":""},{"name":"Daniel Grao","avatar":""},{"name":"Inma Cuesta","avatar":""},{"name":"Darío Grandinetti","avatar":""},{"name":"Michelle Jenner","avatar":""},{"name":"Pilar Castro","avatar":""},{"name":"Nathalie Poza","avatar":""},{"name":"Susi Sánchez","avatar":""},{"name":"Joaquín Notario","avatar":""},{"name":"Priscilla Delgado","avatar":""},{"name":"Blanca Parés","avatar":""},{"name":"Ariadna Martín","avatar":""},{"name":"Rossy de Palma","avatar":""},{"name":"Sara Jiménez","avatar":""},{"name":"Tomás del Estal","avatar":""},{"name":"Mariam B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324413);
