INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phu-nu', 'Chuyện Phụ Nữ', 'Certain Women', 'https://phimimg.com/upload/vod/20231116-1/a0efed958cfea6ef69621228b98362d8.jpg', 'https://phimimg.com/upload/vod/20231116-1/a3e3dd9baa91d029970fd121e128e750.jpg', '<p>Ba người phụ nữ có ý chí mạnh mẽ cố gắng tạo dựng con đường của riêng họ giữa vùng đồng bằng rộng mở ở Tây Bắc nước Mỹ: một luật sư buộc phải khuất phục một khách hàng đang gặp rắc rối; một người vợ và người mẹ có kế hoạch xây dựng ngôi nhà mơ ước của mình đã tiết lộ những rạn nứt trong cuộc hôn nhân của cô ấy; và một chủ trang trại cô đơn có mối quan hệ không rõ ràng với một sinh viên luật trẻ tuổi.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Dern","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Lily Gladstone","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"René Auberjonois","avatar":""},{"name":"John Getz","avatar":""},{"name":"Sara Rodier","avatar":""},{"name":"Ashlie Atkinson","avatar":""},{"name":"Guy Boyd","avatar":""},{"name":"Edelen McWilliams","avatar":""},{"name":"James Jordan","avatar":""},{"name":"Matt McTighe","avatar":""},{"name":"Joshua T. Fonokalafi","avatar":""},{"name":"Zena Dell Lowe","avatar":""},{"name":"Marcelin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
