INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-than-tien', 'Vũ Điệu Thần Tiên', 'Ballerina', 'https://phimimg.com/upload/vod/20231120-1/0c510020338f3314975d1a34080afa90.jpg', 'https://phimimg.com/upload/vod/20231120-1/164a1a7045dba5749f06aa3d720ec3b9.jpg', '<p>Một bộ đôi mồ côi rời bỏ trại mồ côi đến Paris để theo đuổi ước mơ của mình. Chàng muốn trở thành một nhà sáng chế lỗi lạc, nàng muốn trở thành một vũ công ballet chuyên nghiệp được trình diễn ở sân khấu Grand Opera.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Elle Fanning","avatar":""},{"name":"Dane DeHaan","avatar":""},{"name":"Carly Rae Jepsen","avatar":""},{"name":"Maddie Ziegler","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Julie Khaner","avatar":""},{"name":"Terrence Scammell","avatar":""},{"name":"Joe Sheridan","avatar":""},{"name":"Tamir Kapelian","avatar":""},{"name":"Elana Dunkelman","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Shoshana Sperling","avatar":""},{"name":"Jamie Watson","avatar":""},{"name":"Bronwen Mantel","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324413);
