INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-cuoc-san-trung-phuc-sinh', 'Kỷ Băng Hà: Cuộc Săn Trứng Phục Sinh', 'Ice Age: The Great Egg-Scapade', 'https://phimimg.com/upload/vod/20231120-1/144c9ff5592e8302ead1db151254dc16.jpg', 'https://phimimg.com/upload/vod/20231120-1/a40ffcee98a1e95f7540ce6783d93272.jpg', '<p>Một con chim mẹ thời tiền sử bận rộn giao quả trứng sắp nở quý giá của mình cho Sid. Khi cô ấy giới thiệu anh ấy với những người hàng xóm của mình, công việc kinh doanh bùng nổ với dịch vụ ấp trứng mới của anh ấy. Tuy nhiên, chú thỏ cướp biển đê tiện, Squint, kẻ đang tìm cách trả thù cả đàn, đã đánh cắp, ngụy trang và giấu tất cả những quả trứng. Một lần nữa, với sự hỗ trợ của người anh em sinh đôi của Squint, Manny, Diego và những người còn lại trong nhóm đến giải cứu và thực hiện một nhiệm vụ táo bạo biến thành cuộc săn trứng Phục sinh đầu tiên trên thế giới.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Wendy Williams","avatar":""},{"name":"Lili Estefan","avatar":""},{"name":"Blake Anderson","avatar":""},{"name":"Keke Palmer","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Chris Wedge","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a249