INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-am-xuyen-khong', 'Cậu Ấm Xuyên Không', 'Escape Route', 'https://phimimg.com/upload/vod/20231118-1/b78fb85857d9dcc7ad60680920f4c133.jpg', 'https://phimimg.com/upload/vod/20231118-1/d9b1c911998bc4f7cd39a304b164064a.jpg', '<p>Phim Cậu Ấm Xuyên Không là cậu ấm của một tập đoàn lớn, Hiểu Dịch có cuộc sống chỉ biết ăn chơi đàn đúm ở Úc, Cho đến khi bố cậu hấp hối, Hiểu Dịch phải về nước đê tiếp quản công ty thì một sự cố bất ngờ xảy đến. Sau 1 cơn say cậu tỉnh dậy và phát hiện mình đang ở thời Xuân Thu Chiến Quốc với thân phận là thủ lĩnh của 1 băng nhóm kháng chiến…</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yishan","avatar":""},{"name":"Bak Ha-seon","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Fang Chengcheng","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Shi Zhaoqi","avatar":""},{"name":"Guo Kaimin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324413);
