INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-benhur', 'Hoàng Tử Ben-Hur', 'Ben-Hur', 'https://phimimg.com/upload/vod/20231116-1/1eaf5eeda45f4f783cb66df2a1e894a3.jpg', 'https://phimimg.com/upload/vod/20231116-1/a67e733a15e3b8c023f0f9f8ccc486bd.jpg', '<p>Bị phản bội bởi người bạn, người em nuôi Messala, anh mất tất cả và phải trải qua năm năm trong một con thuyền nô lệ La Mã. Sau đó Ben-Hur tìm cách báo thù kẻ hại mình trong một cuộc đua xe ngựa vĩ đại. Cuộc đời anh cũng thay đổi vĩnh viễn sau những cuộc gặp gỡ với Chúa Jesus.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Huston","avatar":""},{"name":"Pilou Asbæk","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Ayelet Zurer","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Nazanin Boniadi","avatar":""},{"name":"Sofia Black-D''Elia","avatar":""},{"name":"Marwan Kenzari","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Denise Tantucci","avatar":""},{"name":"Haluk Bilginer","avatar":""},{"name":"Stefano Scherini","avatar":""},{"name":"David Walmsley","avatar":""},{"name":"Yasen Atour","avatar":""},{"name":"Fra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
