INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-trai-tim-vang', 'Đảo Hải Tặc: Trái Tim Vàng', 'One Piece: Heart of Gold', 'https://phimimg.com/upload/vod/20231128-1/b7f81d1a6ad1d46669e46a43f3e5e241.jpg', 'https://phimimg.com/upload/vod/20231128-1/f9caad35b4a6e8a800f35ce2737d60c9.jpg', '<p>Tesoro đang truy tìm một kho báu bí ẩn tên là “Vàng Nguyên Chất”. Băng Mũ Rơm vô tình gặp được một cô gái biết vị trí cất giấu kho báu bí ẩn đó, nên họ quyết định tiến thẳng đến nơi cất giấu kho báu bí ẩn – hòn đảo huyền thoại Arukemi. Đối thủ trong tập đặc biệt này tên là Maddo Treasure do Seiyuu (diễn viên lồng tiếng) Shun Oguri đảm nhận lồng tiếng. Tên này ăn trái ác quỷ Jyara-Jyara có khả năng tạo và sử dụng các sợi xích. &nbsp;Tập này để chuẩn bị cho phim chiếu rạp tại Nhật One Piece Film Gold vào ngày 23/07/2016 nhằm giải thích và mở rộng cho One Piece Film Gold chiếu rạp sắp tới.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuki Yao","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Kiko Mizuhara","avatar":""},{"name":"Minami Hamabe","avatar":""},{"name":"Kiyohiko Shibukawa","avatar":""},{"name":"Hiroyuki Yoshino","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Gaku Hamada","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Cho","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài H