INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-giam-sieu-nang-luc', 'Thái Giám Siêu Năng Lực', 'Super Eunuch', 'null', 'https://phimimg.com/upload/vod/20231117-1/692defcc6e6c8bbcf16c01ccc7aad1a9.jpg', '<p>Phim Thái Giám Siêu Năng Lực - Super Eunuch 2016 nói về Đại Bảo, một tiểu thái giám thời nhà Minh, vô tình phát hiện ra bản thân có siêu năng lực biến ra mọi món đồ mình muốn trong thời gian nhất định. Vốn mong muốn được trở lại làm nam nhi chân chính. Đại Bảo quyết tận dụng khả năng trời ban này tìm lại &quot;của quý&quot; của mình</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peng Yu Si","avatar":""},{"name":"Liu Yuting","avatar":""},{"name":"Gao Chenglong","avatar":""},{"name":"Zhang Xiaofei","avatar":""},{"name":"Zhong Ming","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324413);
