INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-milano', 'Điệp Vụ Milano', 'Mission Milano', 'https://phimimg.com/upload/vod/20231117-1/98883fd5dc220487939c62171fd50a7f.jpg', 'https://phimimg.com/upload/vod/20231117-1/f462082acb4fc290cc8cbef1d73f9cd0.jpg', '<p>Phim Điệp Vụ Milano với cái tên tiếng anh là Mission Milano. Tuy không phải là một bộ phim đình đám nhưng nó đủ sức hút để mọi người chú ý đến. Điệp Vụ Milano có sự tham gia của hai ngôi sao hàng đầu hoa ngữ thời điểm hiện tại là trai đẹp Huỳnh Hiểu Minh và tài tử Lưu Đức Hoa. Bộ phim được biết đến là một dự án điện ảnh có kinh phí khá lớn do đạo diễn lừng danh Vương Tinh chỉ đạo, tên tuổi của ông được mọi người biết đến qua loạt phim điện ảnh thần bài hay là bộ phim ăn khách trường học Uy Long, những thước phim này cũng đánh dấu tên tuổi của vua hài Châu Tinh Trì. Ngoài ra, phim còn có sự tham gia của một số diễn viên nổi tiếng khác như: Vương Tổ Lam, Âu Dương Na Na…Trong Điệp Vụ Milano, Huỳnh Hiểu Minh sẽ vào vai một siêu đạo chích tinh quái và anh phải đối đầu với tay thám tử hài hước do Lưu Đức Hoa thủ vai. Lúc đầu, khi chưa biết đối thủ của mình thế nào, 2 người chiến đấu giống như một sống một còn nhưng chính những lần đối đầu đó khiến 2 người hiểu nhau hơn và dần dần trở thành cặp đôi hoàn hảo.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Ouyang Nana","avatar":""},{"name":"Wong Cho-lam","avatar":""},{"name":"Xie Yi-lin","avatar":""},{"name":"Philippe Joly","avatar":""},{"name":"Sean Tierney","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Shen Teng","avatar":""},{"name":"Fung Bo-bo","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Dion Lam Dik-On","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
