INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-tham-nhung', 'Tội Ác Tham Nhũng', 'Misconduct', 'https://phimimg.com/upload/vod/20231117-1/5bf0e524a13b9b7f1fd28d882c44e0d8.jpg', 'https://phimimg.com/upload/vod/20231117-1/0915655af2b140680925ec9f3c260f69.jpg', '<p>Một luật sư đầy tham vọng thấy mình bị cuốn vào cuộc đấu tranh quyền lực giữa một giám đốc điều hành dược phẩm tham nhũng và đối tác cấp cao của công ty anh ta. Khi vụ án có một bước ngoặt chết người, anh ta phải chạy đua để khám phá ra sự thật trước khi mất tất cả.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Duhamel","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Marcus Lyle Brown","avatar":""},{"name":"Leah McKendrick","avatar":""},{"name":"Christopher Marquette","avatar":""},{"name":"Skye P. Marshall","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"Jason Gibson","avatar":""},{"name":"Nathan Moore","avatar":""},{"name":"Julia Sandstrom","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324413);
