INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-dem-trang', 'Xác Chết Đêm Trăng', 'Cold Moon', 'https://phimimg.com/upload/vod/20231117-1/73f3e3bddf51c8718abe429d9daa8072.jpg', 'https://phimimg.com/upload/vod/20231117-1/c0257ac5757e1ebd80913e1df653fd8b.jpg', '<p>Phim Xác Chết Đêm Trăng - Cold Moon 2017: kể về một cô gái lương thiện trở về dương gian trả thù sau khi bị giết thảm bằng cách buộc vào xe đạp rồi thả xuống sông. Ở một thành phố bị lãng quên phía Nam, gia đình Larkin trải qua một bi kịch khủng khiếp khi cô con gái họ bị giết. Rồi sau đó nhiều chuyện lạ lùng xảy ra: Mỗi khi đèn giao thông chớp tắt, một bóng ma xuất hiện trên đường phố, những ngôi mộ trong nghĩa trang bị nổ tung, người chết sống dậy. Và bên dưới lòng sông, một hình dạng mặt người từ từ xuất hiện báo hiệu cuộc trả thù.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Candy Clark","avatar":""},{"name":"Josh Stewart","avatar":""},{"name":"Robbie Kay","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Jaiden Kaine","avatar":""},{"name":"Tommy Wiseau","avatar":""},{"name":"Madison Wolfe","avatar":""},{"name":"Rachele Brooke Smith","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Chester Rushing","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Stephanie Honoré","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Marcus Lyle Brown","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b