INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-dinh-menh', 'Ngày Định Mệnh', 'Patriots Day', 'https://phimimg.com/upload/vod/20231117-1/e76e635f66d1e8d6e62ef8b5d891ec43.jpg', 'https://phimimg.com/upload/vod/20231117-1/b1fed34cd55cb6f4ee591074eca07e2a.jpg', '<p>Phim Ngày Định Mệnh - Patriots Day 2016: vụ đánh bom kinh hoàng ngày 15/04/2013 tại Giải Marathon Boston khiến 5 người thiệt mạng và hơn 280 người bị thương. Chứng kiến toàn bộ sự kiện khủng khiếp này, hạ sĩ Tommy Saunders (Mark Wahlberg) cùng những người sống sót, các điều tra viên và lực lượng FBI phải chạy đua với thời gian trong cuộc truy lùng khủng bố quy mô lớn chưa từng thấy trong lịch sử nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"John Goodman","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Themo Melikidze","avatar":""},{"name":"Michael Beach","avatar":""},{"name":"Vincent Curatola","avatar":""},{"name":"James Colby","avatar":""},{"name":"Jake Picking","avatar":""},{"name":"Melissa Benoist","avatar":""},{"name":"Jimmy O. Yang","avatar":""},{"name":"Chris O''Shea","avatar":""},{"name":"Rachel Brosnahan","avatar":""},{"name":"Khandi Alexander","avatar":""},{"name":"Lana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[