INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hurok', 'Hurok', 'Hurok', 'https://phimimg.com/upload/vod/20231115-1/4c224f3fb1020a8c1cbfa13d40b1ac8d.jpg', 'https://phimimg.com/upload/vod/20231115-1/2e888a745d101006bd34ec9befc17f8c.jpg', '<p>Một kẻ buôn bán ma túy và bạn gái phản bội ông chủ của họ trong nhiệm vụ cuối cùng của họ, và người dẫn đầu bị mắc kẹt trong một thời gian.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Dénes Száraz","avatar":""},{"name":"Dorina Martinovics","avatar":""},{"name":"Anger Zsolt","avatar":""},{"name":"Géza D. Hegedűs","avatar":""},{"name":"Zsuzsa Málnai","avatar":""},{"name":"György Honti","avatar":""},{"name":"János Timkó","avatar":""},{"name":"András Réthelyi","avatar":""},{"name":"Zsolt Dér","avatar":""},{"name":"Péter Lengyel","avatar":""},{"name":"Kati Andresz","avatar":""},{"name":"Kálmán Somody","avatar":""},{"name":"Elek Ferenc","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324413);
