INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-ma-am-2016', 'Trường Học Ma Ám', 'Haunted School', 'https://phimimg.com/upload/vod/20231115-1/2806040757c45b6311514c03ce853dc1.jpg', 'https://phimimg.com/upload/vod/20231115-1/6c5886bc710be83e21b713f06e409ba0.jpg', '<p>Trường học là nơi bao nhiêu câu chuyện xảy ra, học sinh đến và đi, chỉ có phòng học và sân trường còn ở lại. Có những người rời trường với những ký ức khó quên, có những người mãi mãi không bao giờ quên những gì mình đã từng trải qua ở đó. Một ngày đẹp trời, nhóm học sinh nọ trốn lớp và tụ tập kể cho nhau nghe những câu chuyện kinh dị, mỗi câu chuyện càng lúc càng trở nên đáng sợ hơn. Khi những nhân vật ma quái bước từ chuyện vào đời thật, ma quỷ bắt đầu xuất hiện đeo bám các học sinh và trường học không còn là nơi an toàn nữa.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ingkarat Damrongsakkul","avatar":""},{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Apa Bhavilai","avatar":""},{"name":"Jaroenporn Onlamai","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Jennie Panhan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
