INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ham-toi-ac', 'Đường Hầm Tội Ác', 'At the End of the Tunnel', 'https://phimimg.com/upload/vod/20231114-1/73613c4e42a9e28bb0062e678f124def.jpg', 'https://phimimg.com/upload/vod/20231114-1/bf1499bc5cf6f5fdc3b7ee5ad7e177a6.jpg', '<p>Joaquin - một kỹ sư máy tính bị liệt bắt đầu nghe thấy giọng nói và những âm thanh lạ lùng vọng lên từ tầng hầm. Ông ta bắt đầu theo dõi mọi động tĩnh của những người &quot;hàng xóm&quot; và phát hiện ra một kế hoạch vô cùng liều lĩnh và táo bạo của kẻ thủ ác. Cùng lúc đó, một phụ nữ trẻ lạ mặt dọn tới thuê trọ tại nhà Joaquin. Liệu cô ta và những kẻ bí ẩn kia có liên hệ gì, và Joaquin sẽ làm thế nào để bảo vệ mạng sống của chính mình?</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Pablo Echarri","avatar":""},{"name":"Clara Lago","avatar":""},{"name":"Federico Luppi","avatar":""},{"name":"Javier Godino","avatar":""},{"name":"Uma Salduende","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324413);
