INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-von-khong-co-y-xuc-pham', 'Theo Von: Không Có Ý Xúc Phạm', 'Theo Von: No Offense', 'https://phimimg.com/upload/vod/20231113-1/a9b53a0d9b2c22570dbcbf2500093f2b.jpg', 'https://phimimg.com/upload/vod/20231113-1/985be58eab5d0cd5d9fa374b7865296c.jpg', '<p>Được biết đến là người luôn nói ra những điều bất ngờ và kể như đúng như vậy, ngay cả khi phải trả giá bằng việc xúc phạm, diễn viên hài Louisiana Theo Von trở về nhà để quay bộ phim hài độc thoại đầu tiên của anh ấy cho Netflix tại Nhà hát Thành phố ở New Orleans.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Theo Von","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324413);
