INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-nhat-phu-nhan', 'Đệ Nhất Phu Nhân', 'Jackie', 'https://phimimg.com/upload/vod/20231114-1/b7240e93ba479be329c6376568a071cb.jpg', 'https://phimimg.com/upload/vod/20231114-1/c28b7c648bc65c047bee9985c2522422.jpg', '<p>Bộ phim này là một bức chân dung của một trong những khoảnh khắc quan trọng và bi thảm nhất trong lịch sử Mỹ, nhìn qua con mắt của người đệ độc mang tính biểu tượng, sau đó Jacqueline Kennedy (Natalie Portman). Jackie đặt chúng tôi vào thế giới của mình trong những ngày ngay sau vụ ám sát chồng. Được biết đến với nhân phẩm và sự đĩnh đạc phi thường của mình, ở đây chúng ta thấy một bức chân dung của đệ nhất phu nhân khi cô ấy chiến đấu để thiết lập di sản của chồng và thế giới của &quot;Camelot&quot; mà cô ấy đã tạo ra và yêu thương rất tốt.</p>', 'Full', 1, 'single', 'completed', 8, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Natalie Portman","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Greta Gerwig","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Caspar Phillipson","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Sara Verhagen","avatar":""},{"name":"Hélène Kuhn","avatar":""},{"name":"Deborah Findlay","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Aidan O''Hare","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"David Ca","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324413);
