INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-choi-bi-an', 'Cuộc Chơi Bí Ẩn', 'Wazir', 'https://phimimg.com/upload/vod/20231115-1/ab5b988b5321987e86da911a2ad176d7.jpg', 'https://phimimg.com/upload/vod/20231115-1/d3ce564e9c92f7ab8f32cdd6fc86f84d.jpg', '<p>Wazir&#39; là câu chuyện về hai người bạn không ngờ tới, một đại kiện tướng cờ vua ngồi xe lăn và một sĩ quan ATS dũng cảm. Mang lại cho nhau bởi nỗi đau và sự xoay vần kỳ lạ của số phận, hai người đàn ông quyết định giúp nhau giành chiến thắng trong những trò chơi lớn nhất trong cuộc đời họ. Nhưng có một đối thủ bí ẩn, nguy hiểm ẩn nấp trong bóng tối, kẻ sẵn sàng chiếu hết họ.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Amitabh Bachchan","avatar":""},{"name":"Farhan Akhtar","avatar":""},{"name":"Aditi Rao Hydari","avatar":""},{"name":"John Abraham","avatar":""},{"name":"Neil Nitin Mukesh","avatar":""},{"name":"Manav Kaul","avatar":""},{"name":"Prakash Belawadi","avatar":""},{"name":"Murali Sharma","avatar":""},{"name":"Nishigandha Wad","avatar":""},{"name":"Avtar Gill","avatar":""},{"name":"Seema Pahwa","avatar":""},{"name":"Vaidehi Parshurami","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324414);
