INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cong-bang', 'Sự Công Bằng', 'Equity', 'https://phimimg.com/upload/vod/20231115-1/aed83612f6810fec52bce9fe7613810c.jpg', 'https://phimimg.com/upload/vod/20231115-1/96966cc67ce3e67512a77fef744e47ee.jpg', '<p>Thế giới tiền bạc quyền lực cao của chủ ngân hàng đầu tư cấp cao Naomi Bishop thật tàn bạo và khốc liệt, và là thế giới mà cô phát triển mạnh. Khi một vụ IPO gây tranh cãi đe dọa đến sự cân bằng mong manh giữa quyền lực và tính bảo mật, Naomi thấy mình vướng vào một mạng lưới chính trị và lừa dối.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Gunn","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Sarah Megan Thomas","avatar":""},{"name":"Alysia Reiner","avatar":""},{"name":"Sophie von Haselberg","avatar":""},{"name":"Craig Bierko","avatar":""},{"name":"Lee Tergesen","avatar":""},{"name":"Margaret Colin","avatar":""},{"name":"Carrie Preston","avatar":""},{"name":"Michael Izquierdo","avatar":""},{"name":"Nate Corddry","avatar":""},{"name":"Nick Gehlfuss","avatar":""},{"name":"Samuel Roukin","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"James Naughton","avatar":""},{"name":"Roe Hartrampf","avatar":""},{"name":"Caro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
