INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-am-sat-365-ngay-ngoai-truyen', 'Lớp Học Ám Sát: 365 Ngày (Ngoại Truyện)', 'Assassination Classroom: 365 Days (Movie)', 'https://phimimg.com/upload/vod/20231125-1/98859d16dbb4f6384697845847a2023b.jpg', 'https://phimimg.com/upload/vod/20231125-1/ad72c28cbf64cd00bba56dac45b60f75.jpg', '<p>Bộ phim sẽ diễn ra vào ngày trước ngày họp lớp sau 7 năm tốt nghiệp của các học sinh lớp E. Yusei Matsui sẽ tham gia vào dự án phim. Nhà sản xuất cũng đã hé lộ tạo hình của hai nhân vật chính là Nagisa và Karma sau 7 năm.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Mai Fuchigami","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Aya Suzaki","avatar":""},{"name":"Ayaka Suwa","avatar":""},{"name":"Chie Matsuura","avatar":""},{"name":"Eiji Miyashita","avatar":""},{"name":"Fuuko Saito","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Junji Majima","avatar":""},{"name":"Kana Ueda","avatar":""},{"name":"Kouki Harasawa","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Megumi Ogata","avatar":""},{"name":"Miho Hino","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Ryou Naitou","avatar":""},{"name":"Ryota Osaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
