INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nhan-cua-hoa-si-ngang-nguoc', 'Tình nhân của họa sĩ ngang ngược', 'Love Me Hit Me', 'null', 'https://phimimg.com/upload/vod/20231125-1/83e3a8599b9dd782b3f12bc25c5f74fc.jpg', '<p>Người đẹp gặp tai nạn mất trí nhớ, bạn trai cũ mang theo tình yêu sâu đậm, tỉ mỉ chuẩn bị buổi triển lãm tranh thành một màn cầu hôn lãng mạn. Liệu người đẹp có hồi phục lại trí nhớ, tiếp tục tình duyên với bạn trai họa sĩ của mình hay chăng?</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Kai-Yuan Cheng","avatar":""},{"name":"Amy Yen","avatar":""},{"name":"Hsu An-Chih","avatar":""},{"name":"Chunya Chao","avatar":""},{"name":"Clover Kao","avatar":""},{"name":"Bo-Jen Wang","avatar":""},{"name":"Sean Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324414);
