INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-tran-do', 'Quái Trận Đồ', 'Strange Battle', 'null', 'https://phimimg.com/upload/vod/20231125-1/359e33b6a692408559dc675a8a5a7152.jpg', '<p>Phim Quái Trận Đồ - Strange Battle 2016 dựa trên một sự việc kì lạ xảy ra tại Tương Tây vào năm 1945, bộ phim lần đầu tiên vén bức màn bí mật sự thật kinh hoàng về xuất hiện của ma cà rồng và một loại trùng độc của người dân tộc Mèo. Phim là sự sáng tạo kết hợp bởi nhiều yếu tố thần bí chủ yếu tập trung khám phá sự thần bí của trùng độc, hé lộ những ẩn dấu trong truyền thuyết ma cà rồng, sự xuất hiện của chuông gọi hồn, những con ma cà rồng của vùng núi Tương Tây và các làng cổ người Mèo sẽ thu hút người xem từ đầu đến cuối.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Xiaoyi","avatar":""},{"name":"Huang Bailu","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Zong Liqun","avatar":""},{"name":"Xiao Yi","avatar":""},{"name":"Zhu Laicheng","avatar":""},{"name":"Yu Qiuyao","avatar":""},{"name":"Luo Buyi","avatar":""},{"name":"Chen Jiajun","avatar":""},{"name":"Yang Lin","avatar":""},{"name":"Li Ran","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324414);
