INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-bi-am', 'Khách Sạn Bị Ám', 'Hotel of The Damned', 'https://phimimg.com/upload/vod/20231113-1/d58fe2328197aeb447e4c0447e357969.jpg', 'https://phimimg.com/upload/vod/20231113-1/df0adf25678a87dab161816999cb81b6.jpg', '<p>Một tai nạn xe hơi khủng khiếp khiến cô gái trẻ Maria và 3 người đàn ông đi cùng mắc kẹt và bị thương, không sóng di động, không sự cứu giúp, họ đành qua đêm tại một khách sạn bị bỏ hoang nằm giữa khu rừng u ám. Đó không phải là một nơi an toàn, nguy hiểm rình rập từ những kẻ khát máu điên cuồng. Bình minh với họ sẽ rất khó khăn.</p>', 'Full', 1, 'single', 'completed', 17, 2016, 'Vietsub', 'HD', 'Romania', 0, '[{"name":"Peter Dobson","avatar":""},{"name":"Manuela Hărăbor","avatar":""},{"name":"Oltin Hurezeanu","avatar":""},{"name":"Roxana Luca","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Bogdan Marhodin","avatar":""},{"name":"Florin Kevorkian","avatar":""},{"name":"Dimitrina Zhivkova","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324414);
