INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-nguc', 'Hỏa Ngục', 'Inferno', 'https://phimimg.com/upload/vod/20231113-1/061f9ccd31e6a86fd50e95f96ec8dae7.jpg', 'https://phimimg.com/upload/vod/20231113-1/72b033e73df2a69d698d11d3045feb22.jpg', '<p>Tỉnh dậy trong một bệnh viện ở Ý, giáo sư ký tượng học nổi tiếng của đại học Harvard - Robert Langdon nhận ra mình bị mất một phần ký ức vài ngày qua. Phần ký ức đó có gì quan trọng và vì sao Langdon lại mất trí nhớ? Cùng với bác sĩ Sienna Brooks, Langdon bước vào hành trình vòng quanh châu Âu để tìm lại trí nhớ và ngăn chặn một âm mưu khủng khiếp nhằm diệt chủng nhân loại.</p>', 'Full', 1, 'single', 'completed', 9, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Irrfan Khan","avatar":""},{"name":"Sidse Babett Knudsen","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Ana Ularu","avatar":""},{"name":"Ida Darvish","avatar":""},{"name":"Paolo Antonio Simioni","avatar":""},{"name":"Alessandro Grimaldi","avatar":""},{"name":"Fausto Maria Sciarappa","avatar":""},{"name":"Robin Mugnaini","avatar":""},{"name":"Paul Ritter","avatar":""},{"name":"Vincenzo Tanassi","avatar":""},{"name":"Alessandro Fabrizi","avatar":""},{"name":"Simone Marian","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324414);
