INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ma-ca-rong', 'Công Chúa Ma Cà Rồng', 'Last Vampire Princess', 'https://phimimg.com/upload/vod/20231112-1/8f61b76dacb3ee0fa14e74c5af2b0594.jpg', 'https://phimimg.com/upload/vod/20231112-1/2090deeb0ad96fa6c934aaedd5223e43.jpg', '<p>Khi chàng thanh niên Pasha ra tay nghĩa hiệp cứu một cô gái tuyệt đẹp thoát khỏi vòng vây bọn tấn công có siêu năng lực kỳ lạ, anh phát hiện ra một thế giới ngầm với các sinh vật huyền bí siêu nhiên sống giữa loài người.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Ivan Yankovsky","avatar":""},{"name":"Lyubov Aksyonova","avatar":""},{"name":"Leonid Yarmolnik","avatar":""},{"name":"Mikhail Evlanov","avatar":""},{"name":"Sabina Akhmedova","avatar":""},{"name":"Igor Vernik","avatar":""},{"name":"Ekaterina Volkova","avatar":""},{"name":"Konstantin Adaev","avatar":""},{"name":"Kristina Babushkina","avatar":""},{"name":"Yuriy Vaksman","avatar":""},{"name":"Aleksey Dmitriev","avatar":""},{"name":"Anastasiya Tsoy","avatar":""},{"name":"Žilvinas Tratas","avatar":""},{"name":"Vladimir Novikov","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324414);
