INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-anh-van-o-day', 'Hóa Ra Anh Vẫn Ở Đây', 'So Young 2: Never Gone', 'https://phimimg.com/upload/vod/20231112-1/bc4e26d648226bac6e4b5ddafd98740d.jpg', 'https://phimimg.com/upload/vod/20231112-1/e6a386600fc20b60e1ec4746a19d9945.jpg', '<p>Phim Hóa Ra Anh Vẫn Ở Đây 2016 kể về tuổi học trò yêu dấu, trong phim Hóa Ra Anh Vẫn Ở đây nhân vật: Trình Tranh (do Ngô Diệc Phàm thủ vai) vô tình làm Vận Cẩm (do Lưu Diệc Phi thủ vai) xấu hổ trước lớp vì lỡ tay… giật &quot;đồ nhạy cảm&quot; của người ta. Phân đoạn này cũng từng xuất hiện trong nguyên tác của Hoá Ra Anh Vẫn Ở Đây. Hành động nông nổi và hơi &quot;vô tư&quot; quá đà này của Trình Tranh đã khiến anh chàng càng bị Tô Vận Cẩm ghét. Tuy nhiên, công tử Trình nào dễ dàng buông tay như vậy. Anh chàng tiếp tục đeo bám Vận Cẩm nhiệt tình hơn cả lúc trước!</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kris Wu","avatar":""},{"name":"Liu Yifei","avatar":""},{"name":"Jin Shijia","avatar":""},{"name":"Li Meng","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Qiao Renliang","avatar":""},{"name":"Maggie Chen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324414);
