INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-dang-yeu', 'Điệp viên đang yêu', 'Spy In Love', 'null', 'https://phimimg.com/upload/vod/20231112-1/90f930983fbeff3e4f30130448280465.jpg', '<p>Một cựu điệp viên điều tra về vụ tai nạn máy bay, để rồi mang đến rắc rối cho kế hoạch đám cưới của cháu trai và khiến anh bị kéo vào một âm mưu tinh vi hơn.</p>', 'Full', 1, 'single', 'completed', 19, 2016, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Siti Saleha","avatar":""},{"name":"Hamish Daud","avatar":""},{"name":"Nasha Aziz","avatar":""},{"name":"Ray Sahetapy","avatar":""},{"name":"Keith Foo","avatar":""},{"name":"Shafira Umm","avatar":""},{"name":"Rosnah Mat Aris","avatar":""},{"name":"Pong Harjatmo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
