INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-cuu-ho', 'Chú Chó Cứu Hộ', 'Rescue Dogs', 'https://phimimg.com/upload/vod/20231112-1/223f700f6563055be65b889a1272a078.jpg', 'https://phimimg.com/upload/vod/20231112-1/fd51f70545b939d2c78d94a6c598322b.jpg', '<p>Tracy và chú chó cứu hộ Charger của anh ta phải phá vỡ kế hoạch của một Doanh nhân xấu xa muốn đánh sập nhà hàng trên bãi biển của họ để xây dựng sân gôn của anh ta. Với sự giúp đỡ từ anh trai của mình, Tracy cố gắng đáp ứng các hóa đơn, quản lý nhà bếp (nơi Charger giúp nấu ăn!) Và vẫn tìm thấy thời gian để yêu cô vũ công xinh đẹp, Bridgette. Thông qua một bộ phim hài về những sai sót và rủi ro, con người thấy rằng chính họ có thể được giải cứu bởi những con vật cứu hộ của chính họ.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Courtney Daniels","avatar":""},{"name":"Paul Haapaniemi","avatar":""},{"name":"Jordan Rawlins","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Peter Oldring","avatar":""},{"name":"Tamara Garfield","avatar":""},{"name":"Brian Hull","avatar":""},{"name":"Jessalyn Gilsig","avatar":""},{"name":"Casey Campbell","avatar":""},{"name":"Andrew Ryan Harvey","avatar":""},{"name":"Ricardo Chacon","avatar":""},{"name":"Kevin Chambers","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324414);
