INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi-troi-day', 'Người Sói Trỗi Dậy', 'She Wolf Rising', 'null', 'https://phimimg.com/upload/vod/20231124-1/deeff142fff6d2c13b29b7b549c00634.jpg', '<p>Bộ phim kinh dị siêu nhiên She Wolf Rising 2016 khám phá thế giới ngầm u ám. Gina Sklar, nữ hoàng phim kinh dị vào vai Tiffany Shepis, cùng với Jake Bubar (trong vai Timothy Mandala), 2 người phải chiến đấu với những quỷ dữ và quái vật, cố ngăn chúng hoành hành khắp thế giới.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiffany Shepis","avatar":""},{"name":"Debbie Rochon","avatar":""},{"name":"Timothy Mandala","avatar":""},{"name":"Ruby LaRocca","avatar":""},{"name":"Tina Krause","avatar":""},{"name":"Nicola Fiore","avatar":""},{"name":"Alan Rowe Kelly","avatar":""},{"name":"Carl Burrows","avatar":""},{"name":"Kate Rose Reynolds","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324414);
