INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-soi-troi-day', 'Người Sói Trỗi Dậy', 'She Wolf Rising', 'người sói trỗi dậy she wolf rising tiffany shepis debbie rochon timothy mandala ruby larocca tina krause nicola fiore alan rowe kelly carl burrows kate rose reynolds ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-em-17', 'Khi Em 17', 'The Edge of Seventeen', 'https://phimimg.com/upload/vod/20231112-1/74fdbaaed28be5ecfc5e4c81f3146007.jpg', 'https://phimimg.com/upload/vod/20231112-1/b83d1120381eb0bf0c0263166289632a.jpg', '<p>Ai cũng biết trưởng thành là cả một hành trình đầy khó khăn. Nadine, một nữ sinh trung học cũng không phải là ngoại lệ. Nadine từ bé đên lớn luôn giống như một bà cụ non. Vì Darian, anh trai cô là một người luôn nổi bật trước đám đông nên cô luôn ghen tị với điều đó.
 Từ bé đến năm 17 Nadine chỉ có 3 người làm bạn cô là bố cô, Krista - bạn thân từ lớp 2 và thầy giáo dạy lịch sử Bruner. Rồi đến một ngày cô bạn Krista có tình cảm với Darian. Việc đó dẫn đến hàng loạt những suy nghĩ rối rắm trong Nadine. Mười bảy là độ tuổi vô cùng ẩm ương, ai sẽ cùng Nadine vượt qua những điều đó.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Blake Jenner","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Hayden Szeto","avatar":""},{"name":"Alexander Calvert","avatar":""},{"name":"Eric Keenleyside","avatar":""},{"name":"Nesta Cooper","avatar":""},{"name":"Meredith Monroe","avatar":""},{"name":"Katie Stuart","avatar":""},{"name":"Lina Renna","avatar":""},{"name":"Christian Michael Cooper","avatar":""},{"name":"Ava Grace Cooper","avatar":""},{"name":"Laine MacNeil","avatar":""},{"name":"Jen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
