INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-ngon-doc-than', 'Tuyên Ngôn Độc Thân', 'How to Be Single', 'https://phimimg.com/upload/vod/20231112-1/da8e38d54731448a402812bd23ba4f71.jpg', 'https://phimimg.com/upload/vod/20231112-1/f0142a65f277bb01763177b24371df82.jpg', '<p>Có một cách đúng đắn để độc thân, một cách sai lầm để độc thân, và sau đó ... có Alice. Và robin. Lucy. Meg. Tom. David. Thành phố New York đầy những trái tim cô đơn đang tìm kiếm trận đấu phù hợp, hãy là một kết nối tình yêu, một cái móc, hoặc một cái gì đó ở giữa. Và một nơi nào đó giữa các văn bản trêu chọc và khán đài một đêm, những gì mà tất cả những người chưa kết hôn này đều có nhu cầu học cách độc thân trong một thế giới chứa đầy các định nghĩa mãi mãi về tình yêu. Ngủ xung quanh trong thành phố mà không bao giờ ngủ không bao giờ là rất nhiều niềm vui.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Rebel Wilson","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Damon Wayans Jr.","avatar":""},{"name":"Anders Holm","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Jake Lacy","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Colin Jost","avatar":""},{"name":"Mickey Gooch Jr.","avatar":""},{"name":"Sarah Ramos","avatar":""},{"name":"Vanessa Rubio","avatar":""},{"name":"Zani Jones Mbayise","avatar":""},{"name":"Brent Morin","avatar":""},{"name":"Kay Cannon","avatar":""},{"name":"Judith Lightfoot Cla","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324414);
