INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-quyen-2016', 'Sát Quyền', 'Karate Kill', 'https://phimimg.com/upload/vod/20231111-1/f62e554f1fb87b2a4f9a98137c4ff045.jpg', 'https://phimimg.com/upload/vod/20231111-1/d48730643de55cf2d0c0054d17558593.jpg', '<p>Một bậc thầy võ thuật karate phải lên đường tìm em gái mình khi cô mất tích bí ẩn tại Los Angeles. Một điều lạ là bất kỳ ai tham gia tìm kiếm cô gái ấy đều phải đối mặt với một thế lực đen tối dùng võ thuật hại người...</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hayate Masao","avatar":""},{"name":"Mana Sakura","avatar":""},{"name":"Asami","avatar":""},{"name":"David Sakurai","avatar":""},{"name":"Katarina Leigh Waters","avatar":""},{"name":"Jeffrey James Lippold","avatar":""},{"name":"Toshiya Agata","avatar":""},{"name":"Kirk Geiger","avatar":""},{"name":"Orson Chaplin","avatar":""},{"name":"Antuone Torbert","avatar":""},{"name":"Tomm Voss","avatar":""},{"name":"Miki Kawawa","avatar":""},{"name":"Yuu Asakura","avatar":""},{"name":"Akihiro Kitamura","avatar":""},{"name":"Ed Spear","avatar":""},{"name":"Masaya Kato","avatar":""},{"name":"Noriaki Kamata","avatar":""},{"name":"Shin S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324414);
