INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-can-ban-cua-viec-quan-tam', 'Điều căn bản của việc quan tâm', 'The Fundamentals of Caring', 'https://phimimg.com/upload/vod/20231113-1/22b3bb7b4b5cfbeff7c66222e226d3a0.jpg', 'https://phimimg.com/upload/vod/20231113-1/c934c9042715ef46ecdf70bb94c5012e.jpg', '<p>Trong bộ phim hài tình bạn này, một thiếu niên tàn tật và người chăm sóc cho cậu bắt đầu hành trình tới những danh thắng, để rồi nhận ra ý nghĩa của hy vọng và tình bạn.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Craig Roberts","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Megan Ferguson","avatar":""},{"name":"Frederick Weller","avatar":""},{"name":"Julia Denton","avatar":""},{"name":"Alex Huff","avatar":""},{"name":"Samantha Huskey","avatar":""},{"name":"Bill Murphey","avatar":""},{"name":"Alan Boell","avatar":""},{"name":"Robert Walker Branchaud","avatar":""},{"name":"Eric Singer","avatar":""},{"name":"James Donadio","avatar":""},{"name":"Donna Biscoe","avatar":""},{"name":"Ashley White","avatar":""},{"name":"Matthew Pruitt","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
