INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-hoc-duong', 'Đại Ca Học Đường', 'Middle School: The Worst Years Of My Life', 'https://phimimg.com/upload/vod/20231113-1/80df42363090a2f529931f0a17a775e4.jpg', 'https://phimimg.com/upload/vod/20231113-1/0ce5ae683baf3993dd1c6244bcc514c0.jpg', '<p>Phim Đại Ca Học Đường - Middle School: The Worst Years Of My Life 2016: Cậu thiếu niên trầm lặng và có óc tưởng tượng Rafe Katchadorian mệt mỏi với những luật lệ khó khăn và bó buộc của trường trung học. Mọi thứ khiến Rafe muốn phản kháng để rồi cậu đi đến một quyết định liều lĩnh. Rafe và người bạn thân nhất quyết định lập một kế hoạch lớn: Phá hỏng mọi điều lệ của trường và khiến các học sinh nổi loạn.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Griffin Gluck","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Alexa Nisenson","avatar":""},{"name":"Andrew Daly","avatar":""},{"name":"Thomas Barbusca","avatar":""},{"name":"Retta","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Luke Hardeman","avatar":""},{"name":"Jessi Goei","avatar":""},{"name":"Jacob Hopkins","avatar":""},{"name":"Patrick Fagan","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Isabella Amara","avatar":""},{"name":"Madeleine Stack","avatar":""},{"name":"Efren Ramirez","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Gemma Forbes","avatar":""},{"name":"James A. Patt","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
