INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-to-lon', 'Bí Mật To Lớn', 'Boonie Bears: The Big Top Secret', 'https://phimimg.com/upload/vod/20231113-1/c441c55199e8e33e105fa7736bd4b2c1.jpg', 'https://phimimg.com/upload/vod/20231113-1/024fc7edd48416ce77d751ca49dd2bf7.jpg', '<p>Bí Mật To Lớn - Boonie Bears: The Big Top Secret xoay quanh cuộc sống của Briar và gia đình. Briar rời ngôi nhà thân thuộc và gia nhập gánh xiếc dạo, nơi đang gặp vô vàn khó khăn và rất cần một sự thay đổi để vực dậy. Briar đã tìm mọi cách để đưa cuộc sống trở lại với gánh xiếc và cậu cảm thấy rất hạnh phúc với cuộc sống mới. Về phần Bramble và các bạn bè trong khu rừng, sau khi tìm kiếm khắp nơi, cuối cùng họ cũng tìm được Briar, tuy nhiên Briar lại không muốn rời bỏ cuộc sống mới của mình. Sau bao nhiêu biến cố và thử thách, các loài vật cuối cùng cũng nhận ra ý nghĩa thực sự của gia đình.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Pei Liu","avatar":""},{"name":"Xiaodong Sun","avatar":""},{"name":"Yuan Xin","avatar":""},{"name":"Danqing Wan","avatar":""},{"name":"Yutian Meng","avatar":""},{"name":"周子瑜","avatar":""},{"name":"Zhang Bingjun","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
