INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ngu-hai-duong', 'Đại Ngư Hải Đường', 'Big Fish And Begonia', 'https://phimimg.com/upload/vod/20231113-1/19fb9185354a6b07d5f17caca9dd5488.jpg', 'https://phimimg.com/upload/vod/20231113-1/9f7e7942fbae5b0aed5d7c49909c2b05.jpg', '<p>Đại Ngư Hải Đường bắt đầu với truyền thuyết về Côn bằng tương truyền Biển Bắc có con cá gọi là cá Côn, mình dài không biết mấy ngàn dặm. Đại Ngư Hải Đường là câu chuyện về tình bạn cảm động của 3 người bạn: Xuân, Tưu và Côn. &nbsp;Xuân - người thừa kế của thần tộc cai quản sự sinh trưởng của vạn vật. Cùng lớn lên cùng cô còn có Tưu - cậu bé mồ côi gia tộc gió, luôn bên cạnh giúp đỡ Xuân. Nghi lễ trưởng thành khi 16 tuổi, Xuân phải biến thành chú cá nhỏ ngao du nhân gian 7 ngày, chẳng may cô bị mắc kẹt vào cơn lốc xoáy thì Côn - cậu bé làng chài của thế giới loài người, vì cứu Xuân mà chết. Vì trả ơn Xuân tìm đến Linh bà biến linh hồn của Côn thành một chú cá nhỏ, nuôi dưỡng và tìm cách đưa về trần gian...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ji Guanlin","avatar":""},{"name":"Pan Shulan","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"Timmy Xu","avatar":""},{"name":"King Shih-Chieh","avatar":""},{"name":"Jiu''er","avatar":""},{"name":"Xang Yuanyuan","avatar":""},{"name":"Xue Lifang","avatar":""},{"name":"Jie Zhang","avatar":""},{"name":"Yang Ting","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324414);
