INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-vien-dac-biet', 'Phóng viên đặc biệt', 'Special Correspondents', 'https://phimimg.com/upload/vod/20231113-1/4808d38e487a8c77dc8c0e417ef902f5.jpg', 'https://phimimg.com/upload/vod/20231113-1/93fc1a002e1f4bd574a9d7e0b7f482fa.jpg', '<p>Một nhà báo đài phát thanh và kỹ thuật viên của anh ta vướng vào rắc rối khi họ lên kế hoạch giả mạo vụ bắt cóc của chính họ trong một cuộc nổi dậy của phiến quân ở Nam Mỹ và thay vào đó trốn sang New York.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ricky Gervais","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Raúl Castillo","avatar":""},{"name":"America Ferrera","avatar":""},{"name":"Meghan Heffern","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Mimi Kuzyk","avatar":""},{"name":"Jim Norton","avatar":""},{"name":"Ari Cohen","avatar":""},{"name":"Alison Brooks","avatar":""},{"name":"Kim Ramirez","avatar":""},{"name":"Kelly McCormack","avatar":""},{"name":"Duane Murray","avatar":""},{"name":"Jonathan Langdon","avatar":""},{"name":"Daniel D","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
