INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-vien-dac-biet', 'Phóng viên đặc biệt', 'Special Correspondents', 'phóng viên đặc biệt special correspondents ricky gervais eric bana vera farmiga kelly macdonald benjamin bratt raúl castillo america ferrera meghan heffern kevin pollak mimi kuzyk jim norton ari cohen alison brooks kim ramirez kelly mccormack duane murray jonathan langdon daniel d ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-2016', 'Siêu Trộm', 'Bitcoin Heist', 'https://phimimg.com/upload/vod/20231012-1/41e80681684c20430b92d7af4c824493.jpg', 'https://phimimg.com/upload/vod/20231012-1/db37141058269bf6d3ec9776e26b1349.jpg', '<p>Nội dung phim nói về những mánh khóe trong thế giới tội phạm siêu kỹ thuật, một hacker có tên là Bóng Ma đã tạo ra phần mềm có thể khóa ổ cứng của máy tính và buộc nạn nhân sử dụng phải trả một khoản tiền chuộc bằng những đồng tiền ảo. Đa Đa (Nhung Kate), một trinh sát đặc nhiệm, được chỉ đạo hợp tác với liên đoàn cảnh sát quốc tế Interpol và lực lượng đặc nhiệm Việt để bắt Bóng Ma. Nhưng phải dùng một tên trộm để bắt một tên cướp. Đa Đa bí mật tập hợp một nhóm trộm: một ảo thuật gia (Jack Magic), một bậc thầy về ngụy trang (Luhan), một vận động viên thể thao tí hon (Linh), một hacker (Vy), và một kẻ cung cấp thông tin (Phúc) đã từng làm việc cho Bóng Ma. Tuy nhiên Bóng Ma hacker luôn đi trước một bước. Cuộc săn bắt giữa mèo và chuột xảy ra sau đó với nhiều tình huống bất ngờ lôi cuốn khán giả khám phá ai là Bóng Ma và ai chiếm được những đồng tiền ảo.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Nhung Kate","avatar":""},{"name":"Huyme","avatar":""},{"name":"Petey Majik Nguyễn","avatar":""},{"name":"Suboi","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Veronica Ngo","avatar":""},{"name":"Teo Yoo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324414);
