INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-hung-nuoc-my', 'Phục Hưng Nước Mỹ', 'David Cross: Making America Great Again', 'null', 'https://phimimg.com/upload/vod/20231111-1/9ad777d7041e721e9e98199d60e6cb75.jpg', '<p>Không có gì vượt quá giới hạn, David Cross không hối lỗi, sâu sắc và cay độc trong bộ phim hài độc thoại gốc Netflix đặc biệt của mình, LÀM CHO NƯỚC MỸ TUYỆT VỜI LẠI. Được quay trực tiếp tại Nhà hát Paramount ở Austin, TX, Cross nhắm đến bối cảnh chính trị hiện tại.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Cross","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
