INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vach-ngan', 'Vách Ngăn', 'Fences', 'https://phimimg.com/upload/vod/20231111-1/b93d5cd67e061ca0bf6c82eb92b161f3.jpg', 'https://phimimg.com/upload/vod/20231111-1/e23fb259e0a4c5be6456e47f2a6aa6cd.jpg', '<p>Vách Ngăn là một bộ phim tâm lý do Mỹ sản xuất vừa được ra mắt năm 2016 xoay quanh câu chuyện về cuộc đấu tranh chủng tộc vì gia đình của ông bố người Mỹ gốc Phi tên là Troy. Sở hữu tài chơi bóng chày thượng hạng, nhưng trong giai đoạn xã hội Mỹ không chấp nhận sự hiện diện của các ngôi sao da đen tham gia môn thể thao ưa thích của họ, Troy phải kiếm sống bằng nghề dọn rác trên những con phố của thành phố công nghiệp vùng Đông Bắc Pittsburgh. Troy đã làm tất cả mọi cách để có thể giúp cho gia đình mình thoát khỏi sự kỳ thị chủng tộc tại Mỹ những năm 1950. Bên cạnh đó các bạn còn thấy được những biến cố mà gia đình của người bố Troy phải trải qua tại thời điểm này.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Jovan Adepo","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Saniyya Sidney","avatar":""},{"name":"Lesley Boone","avatar":""},{"name":"Christopher Mele","avatar":""},{"name":"Jason Silvis","avatar":""},{"name":"Tra''Waan Coles","avatar":""},{"name":"Joe Fishel","avatar":""},{"name":"Cara Clark","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
