INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-adventure-tri-part-2-determination', 'Digimon Adventure tri. Part 2: Determination', 'Digimon Adventure tri. Part 2: Determination', 'https://phimimg.com/upload/vod/20231111-1/4c71c1d535696d38c0608a17218ec573.jpg', 'https://phimimg.com/upload/vod/20231111-1/0828ab90490d2cbfd663dab402c4379d.jpg', '<p>Digidestined Truy cập một công viên chủ đề suối nước nóng gần đó và mọi người đều có một thời gian tốt, nhưng Joe không xuất hiện vì muốn học hỏi cho các kỳ thi của mình. Một digimon bị nhiễm bệnh khác, Ogremon, tấn công Odaiba. Gomamon chạy trốn khỏi nhà trong khi Mimi phải đối mặt với các vấn đề với các bạn cùng lớp khác và các bạn cùng lớp của cô ấy vì những ý tưởng ích kỷ của cô ấy. Joe sẽ chấp nhận trách nhiệm của mình là một người thừa kế trước khi quá muộn?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2016, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Hitomi Yoshida","avatar":""},{"name":"Junya Ikeda","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Miho Arakawa","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Kinoko Yamada","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Atori Shigematsu","avatar":""},{"name":"Miwa Matsumoto","avatar":""},{"name":"Yuk","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324414);
