INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('digimon-adventure-tri-part-2-determination', 'Digimon Adventure tri. Part 2: Determination', 'Digimon Adventure tri. Part 2: Determination', 'digimon adventure tri. part 2: determination digimon adventure tri. part 2: determination natsuki hanae yoshimasa hosoya suzuko mimori mutsumi tamura hitomi yoshida junya ikeda junya enoki mao ichimichi miho arakawa chika sakamoto mayumi yamaguchi junko takeuchi kinoko yamada takahiro sakurai atori shigematsu miwa matsumoto yuk ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-bao-thu', 'Võ Sĩ Báo Thù', 'Kickboxer: Vengeance', 'https://phimimg.com/upload/vod/20231111-1/2811bcc1855d1a6b516d9a6d38d6d4fd.jpg', 'https://phimimg.com/upload/vod/20231111-1/331daddc268c4707c4c706097dcc9f7d.jpg', '<p>Eric và Kurt Sloane là hậu duệ của một gia đình võ sĩ nổi tiếng ở Venice, California. Kurt luôn ở trong cái bóng của anh trai Eric vì anh thiếu bản năng cần thiết để trở thành nhà vô địch. Trước những lo lắng của Kurt, Eric chấp nhận lời đề nghị trả phí và tới Thái Lan để thách đấu nhà vô địch Muay Thái Tong Po và thất bại với hậu quả thảm khốc. Kurt lên đường trả thù. Anh tập luyện với người cố vấn của anh trai mình, Master Durand, để chiến đấu Muay Thái chống lại nhà vô địch tàn nhẫn Tong Po. Ban đầu Durand nghĩ rằng Kurt không thể huấn luyện được, nhưng thông qua một loạt các bài tập và bài kiểm tra tâm linh, Durand phát hiện ra rằng Kurt có một sức mạnh sâu sắc hơn sẽ giúp anh vượt qua trận đấu cuối cùng với Tong Po.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alain Moussi","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Sara Malakul Lane","avatar":""},{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Darren Shahlavi","avatar":""},{"name":"Georges St-Pierre","avatar":""},{"name":"Gina Carano","avatar":""},{"name":"Phi Vu","avatar":""},{"name":"T.J. Storm","avatar":""},{"name":"Sam Medina","avatar":""},{"name":"Cain Velasquez","avatar":""},{"name":"Steven Swadling","avatar":""},{"name":"Hawn Tran","avatar":""},{"name":"Matthew Ziff","avatar":""},{"name":"Oren Hawxhurst","avatar":""},{"name":"Fabrício Werdum","avatar":""},{"name":"Divine Princ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c71