INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robo-trai-cay-cuoc-dao-thoat-vi-dai', 'Robo Trái Cây: Cuộc Đào Thoát Vĩ Đại', 'Fruity Robo: The Great Escape', 'https://phimimg.com/upload/vod/20231111-1/9785ac0eb1f0fb3a283442d2d5cb73b5.jpg', 'https://phimimg.com/upload/vod/20231111-1/f2c62360ab6a45841486ec07fc08d463.jpg', '<p>Phim Robo Trái Cây: Cuộc Đào Thoát Vĩ Đại - Fruity Robo: The Great Escape (2016): Câu chuyện xảy ra ở một hàng hoa quả trong thị trấn nhỏ vùng nông thôn. Chủ nhân của cửa hàng này là một cậu bé mắc bệnh nặng nhưng vẫn rất yêu đời và nhiệt tình. Ở thị trấn nhỏ này đột nhiên xuất hiện một lũ chuột đáng ghét, chúng phá phách làm loạn mọi ngõ ngách thị trấn. Cậu bé này đã cùng với ROBO trái cây- Cam Lưu Hương dẫn dắt dân làng Hoa quả đấu tranh ác liệt với bọn chuột và thoát ra khỏi sự khống chế của chúng...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2016, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hongyu Lai","avatar":""},{"name":"Yuebin Ju","avatar":""},{"name":"Ke Shen","avatar":""},{"name":"Hong Deng","avatar":""},{"name":"Qing Zu","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324414);
