INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xe-ba-dao', 'Chuyến Xe Bá Đạo', 'Fast 888', 'https://phimimg.com/upload/vod/20231111-1/e7074d5b9dc2436daecd786c00031dc1.jpg', 'https://phimimg.com/upload/vod/20231111-1/90c5e38900e70ca8b322c2d16881a13a.jpg', '<p>Phim xoay quanh chuyến xe buýt mang số 888 của tài xế tên Pon. Công việc của anh rất buồn tẻ. Đến một ngày, mọi thứ thay đổi khi Pon phải tiếp đón rất nhiều vị khách lên xe số 888. Điều đáng nói, những hành khách này rất kỳ quái. Sau đó, nhiều tình huống dở khóc dở cười xảy ra ngay trên chuyến xe. Với những chi tiết hài hước, Chuyến xe bá đạo sẽ khiến khán giả cười không ngừng nghỉ trong hơn 90 phút của bộ phim.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Padung Songsang","avatar":""},{"name":"Kunatip Pinpradub","avatar":""},{"name":"Aukkarat Jittasiri","avatar":""},{"name":"Nida Patcharaveerapong","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Jongruay Somjinna","avatar":""},{"name":"Pasakorn Sanrattana","avatar":""},{"name":"Pensri Pinthong","avatar":""},{"name":"Benjapol Cheuyaroon","avatar":""},{"name":"Suthep Sisai","avatar":""},{"name":"Chompoo Kornbai","avatar":""},{"name":"Kittipat Samantrakulchai","avatar":""},{"name":"Jirapat Sinsanong","avatar":""},{"name":"Panya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
