INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chien-binh', 'Cổng Chiến Binh', 'The Warriors Gate', 'https://phimimg.com/upload/vod/20231116-1/f45b65be5ca99daa0432418a7f4b5c69.jpg', 'https://phimimg.com/upload/vod/20231116-1/e4772b4815287dfa874997d291c86b52.jpg', '<p>Phim Cổng Chiến Binh - The Warriors Gate 2016: kể về cuộc phiêu lưu của một cậu bé tới Trung Quốc. Tại đây cậu phải học cách truyền những kỹ năng video game của mình vào một chiến binh Kung Fu.</p>', 'Full', 1, 'single', 'completed', 12, 2016, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Uriah Shelton","avatar":""},{"name":"Ni Ni","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Mark Chao","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Sienna Guillory","avatar":""},{"name":"Dakota Daulby","avatar":""},{"name":"Ron Smoorenburg","avatar":""},{"name":"Eva Day","avatar":""},{"name":"Byron Gibson","avatar":""},{"name":"Joel Adrian","avatar":""},{"name":"David Torok","avatar":""},{"name":"Henry Mah","avatar":""},{"name":"Ming Xi","avatar":""},{"name":"Zha Ka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324414);
