INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-chien-binh', 'Cổng Chiến Binh', 'The Warriors Gate', 'cổng chiến binh the warriors gate uriah shelton ni ni dave bautista mark chao francis ng kara wai ying-hung sienna guillory dakota daulby ron smoorenburg eva day byron gibson joel adrian david torok henry mah ming xi zha ka ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-dong-bong-chay', 'Thần Đồng Bóng Chày', 'The Phenom', 'https://phimimg.com/upload/vod/20231110-1/8fd5c3893bc1bffc9b1fd3c8c983de72.jpg', 'https://phimimg.com/upload/vod/20231110-1/ada8a51969da68018edfdf496b8ba67c.jpg', '<p>Thần Đồng Bóng Chày - The Phenom xoay quanh câu chuyện về cầu thủ bóng chày Hopper. Ngay từ khi còn là một đứa trẻ, anh đã mơ ước trở thành một vận động viên ném bóng ở các giải đấu lớn. Anh không ngừng bị thúc ép bởi người cha bạo hành của mình, Hopper dần trở thành một trong những người chơi triển vọng nhất của giải đấu. Nhưng anh bất ngờ bị gục ngã trên gò đất khi đang chơi bóng. Giờ đây, hy vọng duy nhất của Hopper về tương lai nằm ở một nhà trị liệu thể thao nghiệp dư, người thúc giục anh nhớ lại quá khứ và đối đầu với cha mình, người đàn ông đã bạo hành anh, nhưng đồng thời cũng vừa là gia đình của Hopper.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Simmons","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Sophie Kennedy Clark","avatar":""},{"name":"Alison Elliott","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Louisa Krause","avatar":""},{"name":"Elizabeth Marvel","avatar":""},{"name":"Frank Wood","avatar":""},{"name":"Meg Gibson","avatar":""},{"name":"Emily Fleischer","avatar":""},{"name":"Journey Smith","avatar":""},{"name":"Niesha Butler","avatar":""},{"name":"Aaron Judlowe","avatar":""},{"name":"John Venti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
