INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-dong-bong-chay', 'Thần Đồng Bóng Chày', 'The Phenom', 'thần đồng bóng chày the phenom johnny simmons ethan hawke paul giamatti sophie kennedy clark alison elliott yul vazquez paul adelstein marin ireland louisa krause elizabeth marvel frank wood meg gibson emily fleischer journey smith niesha butler aaron judlowe john venti ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-cam-tu-quan', '28 Cảm Tử Quân', 'Panfilov''s 28 Men', 'https://phimimg.com/upload/vod/20231110-1/893a1c38c9a51f254ab044aff7576ee0.jpg', 'https://phimimg.com/upload/vod/20231110-1/10178fbffabef273de37c43e9c6d64ed.jpg', '<p>Liên Xô, cuối tháng mười một, năm 1941. Căn cứ vào các tài khoản của phóng viên Vasiliy Koroteev xuất hiện trong tờ báo của Hồng quân, Krasnaya Zvezda, ngay sau trận đấu, đây là câu chuyện của Panifilov của Hai mươi Tám, một nhóm hai mươi tám binh sĩ của 316 Rifle Division Hồng quân, dưới sự chỉ huy của tướng Ivan Panfilov, mà dừng lại tiến vào Moscow của một cột năm mươi bốn xe tăng của Đức Quốc xã của Sư đoàn Panzer 11 trong vài ngày. Mặc dù trang bị chỉ với vấn đề tiêu chuẩn Mosin-Nagant súng bộ binh và súng máy DP và PM-M1910, tất cả vô dụng chống lại xe tăng, và với lựu đạn chống tăng RPG-40 hoàn toàn không đầy đủ và PTRD-41 súng trường chống tăng, họ đã chiến đấu không mệt mỏi và bướng bỉnh , với sự dũng cảm bất thường và sự cống hiến không mệt mỏi, để bảo vệ Moscow và quê hương của họ…</p>', 'Full', 1, 'single', 'completed', 22, 2016, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Azamat Nigmanov","avatar":""},{"name":"Alexey Morozov","avatar":""},{"name":"Yakiv Kucherevskyi","avatar":""},{"name":"Oleg Fyodorov","avatar":""},{"name":"Aleksej Longin","avatar":""},{"name":"Dmitriy Girev","avatar":""},{"name":"Amadu Mamadakov","avatar":""},{"name":"Andrey Shalopa","avatar":""},{"name":"Pavel Goncharov","avatar":""},{"name":"Nikolay Klimchuk","avatar":""},{"name":"Vitaliy Kovalenko","avatar":""},{"name":"Aleksandr Plaksin","avatar":""},{"name":"Anton Filipenko","avatar":""},{"name":"Anton Kuznetsov","avatar":""},{"name":"Sergey Agafonov","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324414);
