INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('silence', 'Silence', 'Silence', 'https://phimimg.com/upload/vod/20231109-1/ab5e40250b49b262f00f341b871eaae6.jpg', 'https://phimimg.com/upload/vod/20231109-1/8448091c36daf74c060ff9cbf8eb1318.jpg', '<p>Hai linh mục Dòng Tên du hành đến Nhật Bản vào thế kỷ XVII, nơi dưới thời Mạc phủ Tokugawa, đã cấm Công giáo và hầu hết mọi liên hệ với nước ngoài.</p>', 'Full', 1, 'single', 'completed', 15, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Issey Ogata","avatar":""},{"name":"Shinya Tsukamoto","avatar":""},{"name":"Yoshi Oida","avatar":""},{"name":"Yosuke Kubozuka","avatar":""},{"name":"Kaoru Endô","avatar":""},{"name":"Diego Calderón","avatar":""},{"name":"Rafael Kading","avatar":""},{"name":"Matthew Blake","avatar":""},{"name":"Benoit Masse","avatar":""},{"name":"Tetsuya Igawa","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Panta","avatar":""},{"name":"Takuya Matsunaga","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324414);
