INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('already-tomorrow-in-hong-kong', 'Already Tomorrow in Hong Kong', 'Already Tomorrow in Hong Kong', 'https://phimimg.com/upload/vod/20231109-1/8b253f0a082dbbb7739f2a58524e88f2.jpg', 'https://phimimg.com/upload/vod/20231109-1/2d8eb7a6156c95032d0729ba869a30da.jpg', '<p>Trong câu chuyện lãng mạn lấp lánh này, Ruby, một nhà thiết kế đồ chơi người Mỹ gốc Hoa đến từ LA, lần đầu tiên đến thăm Hồng Kông vì công việc. Thấy mình bị mắc kẹt, cô gặp Josh, một người Mỹ xa xứ, người đã chỉ cho cô thành phố.</p>', 'Full', 1, 'single', 'completed', 14, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jamie Chung","avatar":""},{"name":"Bryan Greenberg","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Sarah Lian","avatar":""},{"name":"Ines Laimins","avatar":""},{"name":"Emily Ting","avatar":""},{"name":"Po-Chih Leong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324414);
