INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-toi-la-dac-vu', 'Hàng Xóm Tôi Là Đặc Vụ', 'Keeping Up With The Joneses', 'https://phimimg.com/upload/vod/20231109-1/6cfa7d351ce7a59185bd3e7dfe1e206c.jpg', 'https://phimimg.com/upload/vod/20231109-1/c9b81ecfd286c12f5f2c84435250d5bd.jpg', '<p>Phim Hàng Xóm Tôi Là Đặc Vụ - Keeping Up With The Joneses 2016: Một cặp vợ chồng (do Zach Galifianakis và Isla Fisher thủ vai) vốn có cuộc sống không có gì đặc biệt nhưng bỗng chốc trở nên xáo trộn... thậm chí nguy hiểm đến tính mạng khi họ tò mò tìm hiểu và phát hiện ra bí mật của hai vị hàng xóm mới của mình - Mr và Mrs Jones (do Jon Hamm &amp; Gal Gadot thủ vai) chính là hai đặc vụ nằm vùng.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Maribeth Monroe","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Jona Xiao","avatar":""},{"name":"Ming Zhao","avatar":""},{"name":"Richard Regan Paul","avatar":""},{"name":"Henry Boston","avatar":""},{"name":"Jack McQuaid","avatar":""},{"name":"Ari Shaffir","avatar":""},{"name":"Marc Grapey","avatar":""},{"name":"Ying He","avatar":""},{"name":"Yi Dong Hian","avatar":""},{"name":"Lauren Revard","avatar":""},{"name":"Rishik Patel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
