INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tien-den', 'Đồng Tiền Đen', 'War On Everyone', 'https://phimimg.com/upload/vod/20231109-1/eaa9471773a29e1cf6e30fcdacc8a0c6.jpg', 'https://phimimg.com/upload/vod/20231109-1/222de2aa44984d4090665952bcb44e86.jpg', '<p>Phim Đồng Tiền Đen - War On Everyone 2016: Bộ đôi cảnh sát thi hành pháp luật bằng những cách cực kì tồi tệ và trục lợi từ tội phạm.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Michael Peña","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Theo James","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Stephanie Sigman","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Malcolm Barrett","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Zion Rain Leyba","avatar":""},{"name":"Derrick Barry","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Tait Fletcher","avatar":""},{"name":"Jacob Browne","avatar":""},{"name":"Geoffrey Pomeroy","avatar":""},{"name":"Gabriel Isaiah A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324414);
