INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-mau-lua', 'Bầu Trời Máu Lửa', 'Sky On Fire', 'https://phimimg.com/upload/vod/20231109-1/2436ef87d87033d3db820442b885bb3b.jpg', 'https://phimimg.com/upload/vod/20231109-1/748431b8942750893ee5fc6f6b68c6ef.jpg', '<p>Phim Bầu Trời Máu Lửa - Sky On Fire 2016: Tôn Thiên Bảo (Ngô Ngạn Tổ) đảm nhiệm vai trò nhân viên cứu hộ trong vụ cháy lớn ở Viện khoa học, anh đã xả thân cứu một nữ nghiên cứu viên – Cao Ngọc (Trương Tịnh Sơ). Thế nhưng giáo sư Phan của Viện nghiên cứu không may đã qua đời trong vụ cháy lớn đó, những ghi chép bằng tay của giáo sư Phan cũng bị thiêu rụi trong đám cháy.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Daniel Wu","avatar":""},{"name":"Zhang Ruoyun","avatar":""},{"name":"Zhang Jingchu","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Joseph Chang","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Kuang-Yao Fan","avatar":""},{"name":"Li Haitao","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Chung King-Fai","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Wong Sze-Yan","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Rose Chan Ka-Wun","avatar":""},{"name":"Ken Law","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324414);
