INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-paterson', 'Thành phố Paterson', 'Paterson', 'https://phimimg.com/upload/vod/20231109-1/5066d783a6cda096c8dad8b54d5b1ffb.jpg', 'https://phimimg.com/upload/vod/20231109-1/e430ae0abeb86cd8bfa0da0cb39677c9.jpg', '<p>Paterson – tên của nhân vật chính và cũng là thành phố nơi anh sống – là một bộ phim dung dị mà ấm áp, kể về cuộc sống bình dị luôn theo trình tự có sẵn của một anh chàng lái xe buýt, cũng là một “nhà thơ”, cùng cô người yêu mộng mơ, thích làm bánh và chú chó đáng yêu bulldog đáng yêu.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Adam Driver","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Method Man","avatar":""},{"name":"Chasten Harmon","avatar":""},{"name":"William Jackson Harper","avatar":""},{"name":"Masatoshi Nagase","avatar":""},{"name":"Nellie","avatar":""},{"name":"Rizwan Manji","avatar":""},{"name":"Dominic Liriano","avatar":""},{"name":"Jaden Michael","avatar":""},{"name":"Trevor Parham","avatar":""},{"name":"Troy T. Parham","avatar":""},{"name":"Brian McCarthy","avatar":""},{"name":"Frank Harts","avatar":""},{"name":"Luis Da Silva J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324414);
