INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-dep-trai', 'Chú Đẹp Trai', 'Rocky Handsome', 'https://phimimg.com/upload/vod/20231109-1/a7990e326313b9d98fef14411687540f.jpg', 'https://phimimg.com/upload/vod/20231109-1/03bffd2aaa0dba4ef24540507d951981.jpg', '<p>Phim Rocky Handsome kể về đặc vụ Raw sau khi bị đình chỉ đã quy ẩn, và mở 1 tiệm cầm đồ ở cùng xóm với 1 cô bé láu lỉnh có tính cách giống với người yêu đã mất của mình. Một ngày nọ mẹ cô bé bị xã hội đen bắt để lấy lại số ma túy mà mẹ cô bé đã lấy của bọn chúng. Rồi bọn chúng bắt cả cô bé đi theo. Vì có cảm tình nên anh đã tìm cách giải cứu cô bé đáng yêu này….</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"John Abraham","avatar":""},{"name":"Shruti Haasan","avatar":""},{"name":"Nathalia Kaur","avatar":""},{"name":"Diya Chalwad","avatar":""},{"name":"Nishikant Kamat","avatar":""},{"name":"Sharad Kelkar","avatar":""},{"name":"Shivkumar Subramaniam","avatar":""},{"name":"Suhasini Mulay","avatar":""},{"name":"Teddy Maurya","avatar":""},{"name":"Kazu Patrick Tang","avatar":""},{"name":"Uday Tikekar","avatar":""},{"name":"Nora Fatehi","avatar":""},{"name":"Sanjay Khapre","avatar":""},{"name":"Akash Dabas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324414);
