INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-tron-chay', 'Người Đẹp Trốn Chạy', 'Nessun Dorma', 'https://phimimg.com/upload/vod/20231109-1/ba6d9a62c99b5eef1713860a01302ce0.jpg', 'https://phimimg.com/upload/vod/20231109-1/3518d46c771430fa239d47f6073f8eb5.jpg', '<p>Jasmine xinh đẹp nhưng ngây thơ đã suy nghĩ lại về cuộc hôn nhân sắp đặt của mình với anh chàng độc thân có tư cách nhất trong thị trấn vì cô đang yêu thầm thần đồng toán học yêu chó Fong. Một đêm nọ, cô bị tấn công trên đường về nhà. Cô tỉnh dậy và thấy mình bị mắc kẹt trong một căn phòng và bị trói trần truồng trên giường. Cô ấy bị hãm hiếp nhưng đã trốn thoát được, và điều này dẫn đến kết cục giết người.</p>', 'Full', 1, 'single', 'completed', 11, 2016, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lam Ka-tung","avatar":""},{"name":"Andy Hui","avatar":""},{"name":"Janice Man","avatar":""},{"name":"Jacky Cai","avatar":""},{"name":"Wilfred Lau","avatar":""},{"name":"Tarah Chan","avatar":""},{"name":"Phat Chan Fei","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324414);
