INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tim-me', 'Hành Trình Tìm Mẹ', 'Lion', 'https://phimimg.com/upload/vod/20231109-1/983538c30b58881c029a115d16629e7c.jpg', 'https://phimimg.com/upload/vod/20231109-1/6b4e4a41528e16fe142131145c02bd33.jpg', '<p>Như rất nhiều đứa trẻ sinh ra ở vùng nông thôn rộng lớn và nghèo khó của Ấn Độ vào thập niên 1980, Saroo chưa bao giờ có cơ hội tận hưởng cảm giác no đủ khi mẹ cậu phải một mình gánh vác ba đứa con nheo nhóc bằng nghề khuân vác trong các mỏ đá ở ngoại vi thành phố Khandwa. Bỗng dưng bị số phận đưa đẩy tới một thành phố xa lạ, nơi người dân thậm chí còn chẳng sử dụng thứ ngôn ngữ ở quê nhà, Saroo một mình đối mặt với muôn vàn khó khăn: từ những cơn đói triền miên, đến nỗi nhớ mẹ, nhớ anh trai da diết, và cả hiểm họa thường trực từ những kẻ lòng lang dạ thú muốn lạm dụng lũ trẻ ngây thơ như cậu. Dù vẫn tồn tại những tấm lòng nhân hậu muốn giúp đỡ Saroo tìm về với gia đình, nhưng tất cả những gì cậu có thể mô tả cho họ chỉ là Guddu - tên người anh trai, và “Ginestley” - tên ngôi làng nghèo quê hương nhưng chẳng thể tìm thấy ở bất cứ đâu trên tấm bản đồ Ấn Độ.</p>', 'Full', 1, 'single', 'completed', 10, 2016, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dev Patel","avatar":""},{"name":"Rooney Mara","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Abhishek Bharate","avatar":""},{"name":"Divian Ladwa","avatar":""},{"name":"Priyanka Bose","avatar":""},{"name":"Deepti Naval","avatar":""},{"name":"Tannishtha Chatterjee","avatar":""},{"name":"Nawazuddin Siddiqui","avatar":""},{"name":"Sunny Pawar","avatar":""},{"name":"Keshav Jadhav","avatar":""},{"name":"Benjamin Rigby","avatar":""},{"name":"Riddhi Sen","avatar":""},{"name":"Rita Boy","avatar":""},{"name":"Arka Das","avatar":""},{"name":"Emilie Cocquerel","avatar":""},{"name":"Sac","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324414);
