INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-toi-mat', 'Nhiệm Vụ Tối Mật', 'Battle for Incheon: Operation Chromite', 'https://phimimg.com/upload/vod/20231108-1/3f7f839323b41a60cc5716d6fae742f4.jpg', 'https://phimimg.com/upload/vod/20231108-1/b0d6ae3dc4d63d0c57b6f0995589fe87.jpg', '<p>Bộ phim dựa trên những sự kiện có thật xảy ra trong trận đánh Incheon giữa quân đội hai miền Triều Tiên vào năm 1950. Tại đó, đại úy hải quân Jang Hak Soo (do Lee Jung Jae đóng) cùng tướng Douglas MacArthur người Mỹ (do Liam Neeson đóng) và 8 người lính Nam Hàn phải thực hiện một nhiệm vụ bí mật mang tên “X-Ray” để có thể giúp cho các đồng đội an toàn.</p>', 'Full', 1, 'single', 'completed', 16, 2016, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Lee Beom-su","avatar":""},{"name":"Jin Se-yeon","avatar":""},{"name":"Jeong Jun-ho","avatar":""},{"name":"Kim Seon-a","avatar":""},{"name":"Yoshihiro Akiyama","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Kim Yeong-ae","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Shin Soo-hang","avatar":""},{"name":"Sean Dulake","avatar":""},{"name":"Justin Rupple","avatar":""},{"name":"Matthew D''Arcy","avatar":""},{"name":"Yoon Da-young","avatar":""},{"name":"Go Yoon","avatar":""},{"name":"Andrew William Brand","avatar":""},{"name":"Rebec","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324414);
